/** One hour in the past — never the same millisecond as any `now` bound (readRecent uses `ts < now`). */
export function pastIso(): string {
  return new Date(Date.now() - 3600_000).toISOString();
}

/**
 * Remove a temp memory dir, retrying transient ENOTEMPTY/EBUSY races: the
 * orchestrator keeps best-effort background writers that can still be running
 * while rm runs. Mirrors the characterization suite's cleanupDir.
 */
export async function cleanupDir(dir: string): Promise<void> {
  for (let attempt = 0; attempt < 10; attempt += 1) {
    try {
      await rm(dir, { recursive: true, force: true });
      return;
    } catch (err) {
      const code = (err as NodeJS.ErrnoException).code;
      if (code !== "ENOTEMPTY" && code !== "EBUSY") throw err;
      await sleep(100);
    }
  }
  await rm(dir, { recursive: true, force: true });
}

/** The field-level extraction seam replaced by {@link stubExtraction}. */
interface ExtractionClientSeam {
  extraction: { extract: (turns: BufferTurn[]) => Promise<ExtractionResult> };
}

/**
 * Stub the LLM extraction client at the orchestrator FIELD level (the
 * established seam — never a production hook). Records every turn slice the
 * engine is asked to extract; storage/persist stays fully real.
 */
export function stubExtraction(
  orchestrator: Orchestrator,
  factory: (turns: BufferTurn[], call: number) => ExtractionResult | Promise<ExtractionResult>
): BufferTurn[][] {
  const calls: BufferTurn[][] = [];
  // The `extraction` field is private and structurally unexpressible from
  // outside the class; the recorder replaces it in place. Named cast per rule.
  const seam = orchestrator as unknown as ExtractionClientSeam;
  seam.extraction = {
    extract: async (turns: BufferTurn[]) => {
      calls.push(turns);
      return factory(turns, calls.length);
    },
  };
  return calls;
}

/**
 * The production `persistExtraction` signature (issue #2068). Sourced from the
 * extraction-run delegate contract — the single canonical shape the orchestrator
 * both exposes as a private method and delegates to. Test doubles and typed
 * private-access surfaces import THIS so any production signature change breaks
 * every consumer at compile time instead of drifting into stale inline casts.
 */
export type PersistExtractionFn = ExtractionRunCoordinatorDeps["persistExtraction"];

/**
 * The full argument tuple of a {@link PersistExtractionFn} call. Recording the
 * whole tuple — not just the leading ExtractionResult — means a change to ANY
 * parameter (storage, source-context, capability sets) surfaces in every
 * consumer that reads the call log, not only the first argument.
 */
export type PersistExtractionArgs = Parameters<PersistExtractionFn>;

/** The method-level persist seam replaced by {@link stubPersistExtraction}. */
interface PersistExtractionSeam {
  persistExtraction: PersistExtractionFn;
}

/**
 * Stub the orchestrator's `persistExtraction` method (the mutation
 * surface the extraction-run coordinator closure drives). Records the full
 * {@link PersistExtractionArgs} tuple of every call for assertions; wraps the
 * factory's persisted-id list into the rich coordinator return shape, or
 * returns empty IDs when no factory is given. The replacement is typed as the
 * production {@link PersistExtractionFn}, so a production signature change
 * fails to compile here rather than silently passing a stale mock.
 */
export function stubPersistExtraction(
  orchestrator: Orchestrator,
  factory?: (args: PersistExtractionArgs, call: number) => string[] | Promise<string[]>
): PersistExtractionArgs[] {
  const calls: PersistExtractionArgs[] = [];
  // `persistExtraction` is replaced in place; the named cast keeps the
  // recorder typed against the production signature.
  const seam = orchestrator as unknown as PersistExtractionSeam;
  const impl: PersistExtractionFn = async (...args) => {
    calls.push(args);
    const persistedIds = factory ? await factory(args, calls.length) : [];
    return { persistedIds, memoryPathById: new Map(), deferredCount: 0, pendingReviewIds: [] };
  };
  seam.persistExtraction = impl;
  return calls;
}

/** A single-fact extraction result. */
export function singleFactResult(content: string): ExtractionResult {
  return {
