  /**
   * Verify if two memories contradict each other using LLM.
   * Called when QMD finds semantically similar memories (Phase 2B).
   */
  async verifyContradiction(
    newMemory: { content: string; category: string },
    existingMemory: { id: string; content: string; category: string; created: string },
  ): Promise<ContradictionVerificationResult | null> {
    const input = `Memory 1 (existing, created ${existingMemory.created}):
Category: ${existingMemory.category}
Content: ${existingMemory.content}

Memory 2 (new):
Category: ${newMemory.category}
Content: ${newMemory.content}`;

    try {
      const instructionText = `You are a contradiction detection system. Analyze whether two memories contradict each other.

IMPORTANT: Not all similar memories are contradictions!
- "User likes TypeScript" and "User likes Python" are NOT contradictions (preferences can coexist)
- "User prefers dark mode" and "User prefers light mode" ARE contradictions (mutually exclusive)
- "User's email is a@b.com" and "User's email is c@d.com" ARE contradictions (only one email)
- "User works at Acme" and "User used to work at Acme" might be a contradiction (temporal change)

Only mark as contradiction if the two statements CANNOT both be true at the same time.

If they ARE contradictory, determine which represents the more recent/current state based on:
- Explicit time references ("now", "currently", "used to", "no longer")
- The fact that newer corrections often start with "actually" or "correction"
- Context clues about change over time

Respond with valid JSON matching this schema:
{
  "isContradiction": true,
  "confidence": 0.95,
  "reasoning": "why they contradict or don't",
  "whichIsNewer": "first"
}`;

      if (this.shouldUseLocalLlm) {
        try {
          const localResponse = await this.localLlm.chatCompletion(
            [
              { role: "system", content: instructionText },
              { role: "user", content: input },
            ],
            {
              temperature: 0.3,
              maxTokens: 2048,
              operation: "contradiction_verification",
              priority: "background",
            },
          );
          const normalized = this.normalizeContradictionVerificationResult(
            this.parseJsonObject(localResponse?.content),
          );
          if (normalized) {
            log.debug(
              `contradiction check via local LLM: ${normalized.isContradiction ? "YES" : "NO"} (confidence: ${normalized.confidence})`,
            );
            return normalized;
          }
          if (!this.config.localLlmFallback) {
            log.warn("contradiction verification skipped — local LLM returned invalid JSON and cloud fallback is disabled");
            return null;
          }
        } catch (err) {
          if (!this.config.localLlmFallback) {
            log.warn(`contradiction verification skipped — local LLM failed and cloud fallback is disabled: ${err}`);
            return null;
          }
        }
      }

      if (!this.shouldUseDirectClient) {
        const fallbackResponse = await this.fallbackLlm.chatCompletion(
          [
            { role: "system", content: instructionText },
            { role: "user", content: input },
          ],
          this.withGatewayAgent({ temperature: 0.3, maxTokens: 2048 }),
        );
        const normalized = this.normalizeContradictionVerificationResult(
          this.parseJsonObject(fallbackResponse?.content),
        );
        if (normalized) {
          log.debug(
            `contradiction check via fallback: ${normalized.isContradiction ? "YES" : "NO"} (confidence: ${normalized.confidence})`,
          );
          return normalized;
        }
        log.warn("contradiction verification skipped — no OpenAI API key and fallback unavailable");
        return null;
      }

      const response = await this.client!.chat.completions.create({
        model: this.config.model,
        messages: [
          { role: "system", content: instructionText },
          { role: "user", content: input },
        ],
        ...buildChatCompletionTokenLimit(this.config.model, 2048, {
          assumeOpenAI: this.directClientUsesOpenAiTokenSemantics(),
        }),
      });

      const normalized = this.normalizeContradictionVerificationResult(
        this.parseJsonObject(response.choices?.[0]?.message?.content),
      );
      if (normalized) {
        log.debug(
          `contradiction check: ${normalized.isContradiction ? "YES" : "NO"} (confidence: ${normalized.confidence})`,
        );
        return normalized;
      }

      return null;
    } catch (err) {
      log.error("contradiction verification failed", err);
      return null;
    }
  }
  async revalidateDependents(
    superseded: { id: string; content: string },
    replacement: { id: string; content: string } | null,
    dependents: Array<{ id: string; category: string; content: string }>,
    signal?: AbortSignal,
  ): Promise<{
    verdicts: Array<{
      memoryId: string;
      verdict: "still_valid" | "invalidated" | "uncertain";
      reason?: string;
    }>;
  }> {
    const complete: RevalidationFastChatCompletion = async (messages, options) => {
      try {
        const fast = await this.fastChatCompletion?.(messages, options);
        if (fast) return fast;
      } catch (error) {
        if (isAbortError(error) || options.signal?.aborted) throw error;
        log.warn(`dependency revalidation fast route failed: ${error}`);
      }
      if (this.shouldUseLocalLlm) {
        try {
          const local = await this.localLlm.chatCompletion(messages, options);
          if (local || !this.config.localLlmFallback) return local;
        } catch (error) {
          if (!this.config.localLlmFallback) throw error;
        }
      }
      if (!this.shouldUseDirectClient) {
        return this.fallbackLlm.chatCompletion(messages, this.withGatewayAgent(options));
      }
      const client = this.client;
      if (!client) return null;
      if (!shouldAssumeOpenAiChatCompletions(client.baseURL ?? this.config.openaiBaseUrl)) {
        const response = await client.chat.completions.create(
          {
            model: this.config.model,
            messages,
            max_tokens: options.maxTokens,
          },
          { signal: options.signal },
        );
        const content = response.choices[0]?.message?.content;
        return typeof content === "string" ? { content } : null;
      }
      const response = await client.responses.create({
        model: this.config.model,
        instructions: messages.find((message) => message.role === "system")?.content,
        input: messages.filter((message) => message.role !== "system").map((message) => message.content).join("\n\n"),
        max_output_tokens: options.maxTokens,
      }, { signal: options.signal });
      return typeof response.output_text === "string" ? { content: response.output_text } : null;
    };
    return revalidateDependentsViaLlm(
      { fastChatCompletion: complete, parseJsonObject: this.parseJsonObject },
      superseded,
      replacement,
      dependents,
      { signal, timeoutMs: this.config.dependencyPropagation.timeoutMs },
    );
  }
  async suggestLinks(
    newMemory: { content: string; category: string },
    candidateMemories: Array<{ id: string; content: string; category: string }>,
  ): Promise<SuggestedLinks | null> {
    if (candidateMemories.length === 0) {
      return { links: [] };
    }

    const candidateList = candidateMemories
      .map((m, i) => `[${i + 1}] ID: ${m.id}\nCategory: ${m.category}\nContent: ${m.content}`)
      .join("\n\n");

    const input = `New memory:
Category: ${newMemory.category}
Content: ${newMemory.content}

Candidate memories to link to:
${candidateList}`;

    try {
      const instructionText = `You are a memory linking system. Analyze the new memory and suggest relationships to existing memories.

Link types:
- follows: This memory is a continuation or next step (e.g., decision follows discussion)
- references: This memory mentions or refers to the other (e.g., fact references entity)
- contradicts: This memory conflicts with the other (use sparingly, only for true contradictions)
- supports: This memory provides evidence or reinforcement (e.g., example supports principle)
- related: General topical relationship

Rules:
- Only suggest links with strength > 0.5
- Quality over quantity — 0-3 links is typical
- Prefer specific link types over generic "related"
- Consider entity references, topics, and causal relationships

Respond with valid JSON matching this schema:
{
  "links": [{"targetId": "memory-id", "linkType": "follows|references|contradicts|supports|related", "strength": 0.8, "reason": "why"}]
}`;

      if (this.shouldUseLocalLlm) {
        try {
          const localResponse = await this.localLlm.chatCompletion(
            [
              { role: "system", content: instructionText },
              { role: "user", content: input },
            ],
            {
              temperature: 0.3,
              maxTokens: 2048,
              operation: "link_suggestion",
              priority: "background",
            },
          );
          const normalized = this.normalizeSuggestedLinksResult(this.parseJsonObject(localResponse?.content));
          if (normalized) {
            log.debug(`suggested ${normalized.links.length} links via local LLM`);
            return normalized;
          }
          if (!this.config.localLlmFallback) {
            log.warn("link suggestion skipped — local LLM returned invalid JSON and cloud fallback is disabled");
            return null;
          }
        } catch (err) {
          if (!this.config.localLlmFallback) {
            log.warn(`link suggestion skipped — local LLM failed and cloud fallback is disabled: ${err}`);
            return null;
          }
        }
      }

      if (!this.shouldUseDirectClient) {
        const fallbackResponse = await this.fallbackLlm.chatCompletion(
          [
            { role: "system", content: instructionText },
            { role: "user", content: input },
          ],
          this.withGatewayAgent({ temperature: 0.3, maxTokens: 2048 }),
        );
        const normalized = this.normalizeSuggestedLinksResult(this.parseJsonObject(fallbackResponse?.content));
        if (normalized) {
          log.debug(`suggested ${normalized.links.length} links via fallback`);
          return normalized;
        }
        log.warn("link suggestion skipped — no OpenAI API key and fallback unavailable");
        return null;
      }

      const response = await this.client!.chat.completions.create({
        model: this.config.model,
        messages: [
          { role: "system", content: instructionText },
          { role: "user", content: input },
        ],
        ...buildChatCompletionTokenLimit(this.config.model, 2048, {
          assumeOpenAI: this.directClientUsesOpenAiTokenSemantics(),
        }),
      });

      const normalized = this.normalizeSuggestedLinksResult(
        this.parseJsonObject(response.choices?.[0]?.message?.content),
      );
      if (normalized) {
        log.debug(`suggested ${normalized.links.length} links`);
        return normalized;
      }

      return null;
    } catch (err) {
      log.error("link suggestion failed", err);
      return null;
    }
  }

  async generateDaySummary(memories: string | MemoryFile[]): Promise<DaySummaryResultShape | null> {
    if (!resolveRecallAuxiliaryCapabilities(this.config).daySummary) {
      log.warn("day summary skipped — disabled by config");
      return null;
    }

    const memoryContext = formatDaySummaryMemories(memories);
    if (memoryContext.length === 0) return null;

    const instructionText = await loadDaySummaryPrompt();

    // Append extension footer when extensions are active (#382)
    let extensionsFooter = "";
    try {
      extensionsFooter = await buildExtensionsFooterForSummary(this.config);
    } catch {
      // Non-fatal: skip extension footer if discovery fails
    }

    const userPrompt = `Generate an end-of-day summary from this Remnic memory context:

${memoryContext}${extensionsFooter.length > 0 ? `\n\n${extensionsFooter}` : ""}`;
    const traceId = crypto.randomUUID();
    const startedAt = Date.now();
    this.emit({ kind: "llm_start", traceId, model: this.config.model, operation: "day_summary", input: memoryContext.slice(0, 4000) });

    if (this.shouldUseLocalLlm) {
      try {
        const localResponse = await this.localLlm.chatCompletion(
          [
            { role: "system", content: `${instructionText}

Return valid JSON only.` },
            { role: "user", content: userPrompt },
          ],
          {
            temperature: 0.2,
            maxTokens: 2048,
            operation: "day_summary",
            priority: "background",
          },
        );
        const normalized = this.normalizeDaySummaryResult(this.parseJsonObject(localResponse?.content));
        if (normalized) {
          this.emit({ kind: "llm_end", traceId, model: this.config.localLlmModel, operation: "day_summary", durationMs: Date.now() - startedAt, output: JSON.stringify(normalized).slice(0, 2000) });
          log.debug(`generated day summary via local LLM (${normalized.bullets.length} bullets)`);
          return normalized;
        }
        if (!this.config.localLlmFallback) {
          this.emit({ kind: "llm_error", traceId, model: this.config.localLlmModel, operation: "day_summary", durationMs: Date.now() - startedAt, error: "local LLM returned invalid JSON and fallback disabled" });
          log.warn("day summary skipped — local LLM returned invalid JSON and fallback disabled");
          return null;
        }
      } catch (err) {
        if (!this.config.localLlmFallback) {
          this.emit({ kind: "llm_error", traceId, model: this.config.localLlmModel, operation: "day_summary", durationMs: Date.now() - startedAt, error: String(err) });
          log.warn(`day summary skipped — local LLM failed and fallback disabled: ${err}`);
          return null;
        }
      }
    }

    const fallbackResult = await this.parseWithGatewayFallback(
      traceId,
      "day_summary",
      startedAt,
      DaySummaryResultSchema,
      [
        { role: "system", content: `${instructionText}

Return valid JSON only.` },
        { role: "user", content: userPrompt },
      ],
      { temperature: 0.2, maxTokens: 2048 },
    );
    if (fallbackResult) {
      const normalized = this.normalizeDaySummaryResult(fallbackResult);
      if (normalized) {
        log.debug(`generated day summary via fallback (${normalized.bullets.length} bullets)`);
        return normalized;
      }
    }

    // Direct Responses API fallback (AGENTS.md-compliant: never Chat Completions)
    if (this.shouldUseDirectClient) {
      try {
        const response = await (this.client as any).responses.create({
          model: this.config.model,
          instructions: `${instructionText}\n\nReturn valid JSON only.`,
          input: userPrompt,
          max_output_tokens: 2048,
        });
        const rawText = typeof response.output_text === "string" ? response.output_text : JSON.stringify(response.output_text ?? "");
        const normalized = this.normalizeDaySummaryResult(this.parseJsonObject(rawText));
        if (normalized) {
          this.emit({ kind: "llm_end", traceId, model: this.config.model, operation: "day_summary", durationMs: Date.now() - startedAt, output: JSON.stringify(normalized).slice(0, 2000) });
          log.debug(`generated day summary via Responses API (${normalized.bullets.length} bullets)`);
          return normalized;
        }
        this.emit({ kind: "llm_error", traceId, model: this.config.model, operation: "day_summary", durationMs: Date.now() - startedAt, error: "Responses API returned unparseable output" });
      } catch (err) {
        this.emit({ kind: "llm_error", traceId, model: this.config.model, operation: "day_summary", durationMs: Date.now() - startedAt, error: `Responses API failed: ${err}` });
      }
    }

    this.emit({ kind: "llm_error", traceId, model: this.config.model, operation: "day_summary", durationMs: Date.now() - startedAt, error: "all generation paths exhausted (local LLM + gateway + Responses API)" });
    log.warn("day summary skipped — all generation paths exhausted");
    return null;
  }


  /**
   * Summarize a batch of old memories into a compact summary (Phase 4A).
   */
  async summarizeMemories(
    memories: Array<{ id: string; content: string; category: string; created: string }>,
  ): Promise<MemorySummaryResult | null> {
    if (memories.length === 0) return null;

    const memoryList = memories
      .map((m) => `[${m.id}] (${m.category}, ${m.created.slice(0, 10)})\n${m.content}`)
      .join("\n\n");

    try {
      const instructionText = `You are a memory summarization system. You are given a batch of old memories that need to be compressed into a summary.

Your task:
1. Write a concise summary paragraph (2-4 sentences) capturing the essence of these memories
2. Extract the 5-10 most important facts that should be preserved
3. List the key entities mentioned

Guidelines:
- Preserve specific, actionable information
- Merge redundant details into single statements
- Focus on durable insights, not transient details
- Maintain any preferences, decisions, or corrections as key facts

Respond with valid JSON matching this schema:
{
  "summaryText": "concise summary paragraph",
  "keyFacts": ["fact 1", "fact 2"],
  "keyEntities": ["entity-1", "entity-2"]
}`;

      if (this.shouldUseLocalLlm) {
        try {
          const localResponse = await this.localLlm.chatCompletion(
            [
              { role: "system", content: instructionText },
              { role: "user", content: `Summarize these ${memories.length} memories:\n\n${memoryList}` },
            ],
            {
              temperature: 0.3,
              maxTokens: 4096,
              operation: "memory_summarization",
              priority: "background",
            },
          );
          const normalized = this.normalizeMemorySummaryResult(this.parseJsonObject(localResponse?.content));
          if (normalized) {
            log.debug(
              `summarized ${memories.length} memories into ${normalized.keyFacts.length} key facts via local LLM`,
            );
            return normalized;
          }
          if (!this.config.localLlmFallback) {
            log.warn("summarization skipped — local LLM returned invalid JSON and cloud fallback is disabled");
            return null;
          }
        } catch (err) {
          if (!this.config.localLlmFallback) {
            log.warn(`summarization skipped — local LLM failed and cloud fallback is disabled: ${err}`);
            return null;
          }
        }
      }

      if (!this.shouldUseDirectClient) {
        const fallbackResponse = await this.fallbackLlm.chatCompletion(
          [
            { role: "system", content: instructionText },
            { role: "user", content: `Summarize these ${memories.length} memories:\n\n${memoryList}` },
          ],
          this.withGatewayAgent({ temperature: 0.3, maxTokens: 4096 }),
        );
        const normalized = this.normalizeMemorySummaryResult(this.parseJsonObject(fallbackResponse?.content));
        if (normalized) {
          log.debug(`summarized ${memories.length} memories into ${normalized.keyFacts.length} key facts via fallback`);
          return normalized;
        }
        log.warn("summarization skipped — no OpenAI API key and fallback unavailable");
        return null;
      }

      const response = await this.client!.chat.completions.create({
        model: this.config.model,
        messages: [
          { role: "system", content: instructionText },
          { role: "user", content: `Summarize these ${memories.length} memories:\n\n${memoryList}` },
        ],
        ...buildChatCompletionTokenLimit(this.config.model, 4096, {
          assumeOpenAI: this.directClientUsesOpenAiTokenSemantics(),
        }),
      });

      const normalized = this.normalizeMemorySummaryResult(
        this.parseJsonObject(response.choices?.[0]?.message?.content),
      );
      if (normalized) {
        log.debug(`summarized ${memories.length} memories into ${normalized.keyFacts.length} key facts`);
        return normalized;
      }

      return null;
    } catch (err) {
      log.error("memory summarization failed", err);
      return null;
    }
  }
}

/**
 * Extraction Judge — LLM-as-judge fact-worthiness gate (issue #376).
 *
 * Evaluates extracted facts against a durability rubric before they are
 * persisted. Facts that are unlikely to be useful 30+ days from now or
 * across sessions are rejected (or shadow-logged depending on config).
 *
 * Design constraints:
 *   - Corrections and principles are auto-approved (safety bypass).
 *   - Critical-importance facts are auto-approved.
 *   - Batches respect extractionJudgeBatchSize.
 *   - Content-hash caching avoids redundant LLM calls.
 *   - LLM calls use extractionJudgeTimeoutMs (default 20s: measured 2.1-2.5 s
 *     per compact verdict request with a batch-scaled completion budget on a
 *     small fast judge model; 13-22 s per compact call, 41 s verbose, on the
 *     big shared core model — raise it there; the old 150s default only
 *     papered over 59-305s verbose replies).
 */

import { createHash } from "node:crypto";
import { log } from "./logger.js";
import type { PluginConfig, ImportanceLevel } from "./types.js";
import type { LocalLlmClient } from "./local-llm.js";
import { type FallbackLlmClient, gatewayTaskChainOptions } from "./fallback-llm.js";
import { extractJsonCandidates } from "./json-extract.js";
import { normalizeProcedureSteps } from "./procedural/procedure-types.js";
import { OUTPUT_LANGUAGE_POLICY } from "./extraction-prompt.js";

// ---------------------------------------------------------------------------
// Public interfaces
// ---------------------------------------------------------------------------

export interface JudgeCandidate {
  text: string;
  category: string;
  confidence: number;
  tags?: string[];
  /** Local importance level, set by caller before judging. */
  importanceLevel?: ImportanceLevel;
}

/**
 * Verdict kinds (issue #562, PR 1).
 *
 * - `"accept"`: fact is durable, persist it.
 * - `"reject"`: fact is not durable, drop it.
 * - `"defer"`: fact is ambiguous; push it back into the buffer for another
 *   pass with fresh context. Inspired by MemReader (arxiv 2604.07877).
 *
 * PR 1 only introduces the type. No emit path produces `"defer"` yet — the
 * defer-capable prompt, buffer re-routing, telemetry, and GRPO data
 * collection are landing in PRs 2, 3, and 4 respectively.
 */
export type JudgeVerdictKind = "accept" | "reject" | "defer";

/**
 * Judge verdict shape.
 *
 * Back-compat note: `kind` is optional. Verdicts serialized before PR 1
 * (both in-memory cache entries and any persisted caches) only carry
 * `{ durable, reason }`. Downstream consumers must either read `durable`
 * directly, or use {@link getVerdictKind} / {@link isDurableVerdict} which
 * gracefully fall back to the boolean when `kind` is missing, and ignore
 * unknown future `kind` values rather than crashing.
 */
export interface JudgeVerdict {
  /**
   * True iff the fact should be persisted. For `"defer"` verdicts this is
   * `false` — a deferred fact is not (yet) persisted, so callers that only
   * look at `durable` will treat defer as "skip this turn", which matches
   * the pre-PR-1 fail-closed behavior for non-accepted verdicts.
   */
  durable: boolean;
  reason: string;
  /**
   * Optional explicit verdict kind. Added in PR 1 of issue #562. Legacy
   * verdicts (including cache entries produced before this field existed)
   * do not set `kind`; use {@link getVerdictKind} to read this safely.
   */
  kind?: JudgeVerdictKind;
}

/**
 * Resolve a verdict's effective kind.
 *
 * - If `kind` is explicitly set to one of the known values, return it.
 * - If `kind` is absent, infer from `durable` (back-compat with pre-PR-1
 *   cache entries and emit paths that have not been updated yet).
 * - If `kind` is set to an unrecognised value (forward-compat, e.g. a
 *   future cache entry loaded by an older build), fall back to `durable`
 *   so we never crash on unknown strings.
 */
export function getVerdictKind(verdict: JudgeVerdict): JudgeVerdictKind {
  const raw = verdict.kind;
  if (raw === "accept" || raw === "reject" || raw === "defer") {
    return raw;
  }
  return verdict.durable ? "accept" : "reject";
}

/**
 * Type guard: returns `true` only for verdicts that should be persisted.
 * Treats both `"reject"` and `"defer"` as "not durable" — defer means the
 * caller should re-evaluate later, not write now.
 */
export function isDurableVerdict(verdict: JudgeVerdict): boolean {
  return getVerdictKind(verdict) === "accept";
}

/**
 * Validate a cache entry loaded from persistence / another process.
 *
 * Strict: accepts legacy `{ durable, reason }` entries and new entries
 * whose `kind` is one of the three known `JudgeVerdictKind` values.
 * Rejects structurally wrong types and unknown `kind` strings so the
 * type-guard narrowing is sound — callers that receive
 * `value is JudgeVerdict` can safely treat `kind` as the declared
 * union.
 *
 * Forward-compat is handled by {@link normalizeCachedVerdict}, which
 * drops unknown `kind` strings before validation so a newer build's
 * cache entry still loads instead of being rejected.
 */
export function isValidCachedVerdict(value: unknown): value is JudgeVerdict {
  if (typeof value !== "object" || value === null) return false;
  const v = value as Record<string, unknown>;
  if (typeof v.durable !== "boolean") return false;
  if (typeof v.reason !== "string") return false;
  if (v.kind !== undefined) {
    if (v.kind !== "accept" && v.kind !== "reject" && v.kind !== "defer") {
      return false;
    }
  }
  return true;
}

/**
 * Forward-compatible cache-entry loader.
 *
 * Drops unknown `kind` strings to `undefined` (so `getVerdictKind` can
 * fall back to `durable`), then validates structurally. Non-string
 * `kind` values are still treated as structural violations and rejected.
 * Returns the sanitised verdict, or `null` when the entry is structurally
 * unusable.
 */
export function normalizeCachedVerdict(value: unknown): JudgeVerdict | null {
  if (typeof value !== "object" || value === null) return null;
  const v = value as Record<string, unknown>;
  if (typeof v.durable !== "boolean") return null;
  if (typeof v.reason !== "string") return null;
  let kind: JudgeVerdictKind | undefined;
  if (v.kind !== undefined) {
    if (typeof v.kind !== "string") return null;
    if (v.kind === "accept" || v.kind === "reject" || v.kind === "defer") {
      kind = v.kind;
    }
    // Unknown string `kind`: dropped to undefined for forward-compat.
  }
  const out: JudgeVerdict = { durable: v.durable, reason: v.reason };
  if (kind !== undefined) out.kind = kind;
  return out;
}

export interface JudgeBatchResult {
  verdicts: Map<number, JudgeVerdict>;
  /** Number of verdicts served from cache. */
  cached: number;
  /** Number of verdicts produced by an LLM call. */
  judged: number;
  /** Total wall-clock time in milliseconds. */
  elapsed: number;
  /**
   * Number of verdicts in this batch that resolved to `"defer"` (issue #562,
   * PR 2). Callers can use this to decide whether to retain buffer turns for
   * the next extraction pass.
   */
  deferred: number;
  /**
   * Number of defers that were forcibly converted to `"reject"` because the
   * same candidate text had already been deferred at least
   * `extractionJudgeMaxDeferrals` times. Rolled out of `deferred` — a
   * candidate counted here is *not* also in `deferred`.
   */
  deferredCappedToReject: number;
}

/**
 * Per-verdict observation emitted by `judgeFactDurability` when an
 * `onVerdict` callback is supplied (issue #562, PR 3). Used to wire the
 * observation ledger / telemetry stream without coupling the judge module
 * directly to filesystem I/O. One event is emitted for every resolved
 * verdict, including auto-approved and cache-hit paths.
 */
export interface JudgeVerdictObservation {
  verdict: JudgeVerdict;
  /** The original `JudgeCandidate` passed in (same reference). */
  candidate: JudgeCandidate;
  /** SHA-256 of `text\0category`, same key the cache/deferCounter use. */
  contentHash: string;
  /** Verdict resolution path. Useful for debugging + dashboards. */
  source: "auto-approve" | "cache" | "llm" | "llm-cap-rejected" | "fail-open";
  /**
   * How many times this candidate had already been deferred before this
   * verdict resolved. 0 when the candidate had never been deferred.
   */
  priorDeferrals: number;
  /**
   * Milliseconds from batch start to now. Shared across verdicts emitted in
   * the same batch.
   */
  elapsedMs: number;
}

// ---------------------------------------------------------------------------
// Prompt (embedded; mirrors prompts/extraction_judge.prompt.md)
// ---------------------------------------------------------------------------

export const JUDGE_SYSTEM_PROMPT = `You are a memory curator evaluating whether extracted facts are **durable** — worth storing for long-term recall across sessions.

A fact is **durable** if it will still be useful 30+ days from now and is relevant across multiple sessions, not just the current task.

The user message is a JSON array of candidates: [{"index": 0, "text": "...", "category": "...", "confidence": 0.5}, ...].

Verdicts:
- "accept" — durable. Personal preferences, identities, relationships; decisions with rationale that affect future work; corrections to previously held beliefs; principles, rules, or constraints the user wants respected; stable facts about projects, tools, or workflows; commitments, deadlines, or obligations.
- "reject" — not durable. Transient task details ("currently debugging line 42"); ephemeral state ("the build is running now"); routine operations ("ran npm install"); conversational filler; anything stale within hours; step-by-step instructions for a one-time task.
- "defer" — MIGHT be durable but the candidate alone cannot say: ambiguous referents ("he said they'd follow up"), in-progress statements that may become durable once completed, future commitments with unclear subject or timeline. Defer is NOT a soft reject: use it only when another turn of context would genuinely change the verdict; when torn between accept and reject, lean accept — losing a useful fact is worse than keeping a marginal one.

Reply with a JSON object with a single "verdicts" key, exactly one object per input candidate:
{"verdicts": [{"index": <candidate index>, "kind": "accept" | "reject" | "defer"}]}

Rules:
1. The top level must be one object {"verdicts": [...]} — JSON mode rejects a bare top-level array.
2. Copy each object's "index" from the input candidate. One object per candidate, exactly.
3. No other fields — no "reason", no "durable", no commentary.
4. Output valid JSON only. No markdown fences.
5. ${OUTPUT_LANGUAGE_POLICY}

Example output:
{"verdicts": [{"index": 0, "kind": "accept"}, {"index": 1, "kind": "reject"}, {"index": 2, "kind": "defer"}]}`;

// ---------------------------------------------------------------------------
// Judge request assembly (PR 3264 follow-up)
// ---------------------------------------------------------------------------

/** Completion tokens reserved per candidate verdict (measured 13 on a small judge model). */
const JUDGE_TOKENS_PER_CANDIDATE = 24;
/** Ceiling on one judge reply: the old flat budget. */
export const MAX_JUDGE_TOKENS = 2048;
/**
 * Extra completion tokens for a judge call routed through the Responses API. Reasoning tokens count against
 * `max_output_tokens`, so the compact verdict budget alone can be spent before a reasoning-enabled model answers; the
 * unparsed batch would then fail open as durable. A cap, not a target: a non-reasoning model still writes a short reply.
 */
export const JUDGE_REASONING_HEADROOM_TOKENS = 1024;
/** Largest batch whose verdict array fits MAX_JUDGE_TOKENS; a larger configured batch is split. */
export const MAX_JUDGE_BATCH = Math.floor(MAX_JUDGE_TOKENS / JUDGE_TOKENS_PER_CANDIDATE);

/**
 * Compact completion budget for one judge call. A verdict is
 * `{"index":12,"kind":"reject"}` (~14 tokens), so the old flat 2048 only gave
 * a slow model room to produce 59-305s replies that hid inside the timeout.
 * Scales with the batch size (about 24 tokens per candidate verdict, measured
 * 13 per verdict on a small judge model) so a large batch is never truncated;
 * capped at 2048, the old flat budget.
 */
export function judgeMaxTokens(batchSize: number): number {
  return Math.min(MAX_JUDGE_TOKENS, Math.max(64, batchSize * JUDGE_TOKENS_PER_CANDIDATE));
}

/** One indexed candidate entry in a judge request payload. */
export interface JudgeRequestEntry {
  index: number;
  text: string;
  category: string;
  confidence: number;
}

/** Full judge LLM request: messages plus the completion budget. */
export interface JudgeRequest {
  messages: Array<{ role: "system" | "user"; content: string }>;
  maxTokens: number;
}

/** Build a full judge request body: messages plus the completion budget. */
export function buildJudgeRequest(entries: readonly JudgeRequestEntry[]): JudgeRequest {
  return {
    messages: [
      { role: "system", content: JUDGE_SYSTEM_PROMPT },
      { role: "user", content: JSON.stringify(entries) },
    ],
    maxTokens: judgeMaxTokens(entries.length),
  };
}

// ---------------------------------------------------------------------------
// Content-hash cache (in-memory, per-process fallback)
// ---------------------------------------------------------------------------

/** Maximum entries before evicting the oldest half. */
const VERDICT_CACHE_MAX_SIZE = 10_000;

/** Module-level fallback cache, used when callers do not pass their own. */
const defaultVerdictCache = new Map<string, JudgeVerdict>();

/**
 * Per-content-hash deferral counter (issue #562, PR 2).
 *
 * When the judge emits a `"defer"` verdict for a candidate whose content
 * has already been deferred `extractionJudgeMaxDeferrals` times, the verdict
 * is forcibly converted to `"reject"` so a pathological LLM response cannot
 * produce an infinite defer loop.
 *
 * Module-level with a size cap so stale test state cannot leak between runs
 * in the unlikely case a caller does not clear it between processes.
 */
const defaultDeferCounts = new Map<string, number>();
const DEFER_COUNT_MAX_SIZE = 20_000;

function cacheKey(text: string, category: string): string {
  return createHash("sha256").update(`${text}\0${category}`).digest("hex");
}

/**
 * Resolve the effective defer cap from config, defaulting to 2 when the
 * config value is missing or non-positive. Matches the PR 2 spec.
 */
function resolveDeferCap(config: PluginConfig): number {
  const raw = (config as { extractionJudgeMaxDeferrals?: number })
    .extractionJudgeMaxDeferrals;
  if (typeof raw === "number" && Number.isFinite(raw) && raw >= 1) {
    return Math.floor(raw);
  }
  return 2;
}

/**
 * Enforce the max-size invariant on a verdict cache. When the cache exceeds
 * VERDICT_CACHE_MAX_SIZE, the oldest half of entries are deleted (Map
 * iteration order is insertion order).
 */
function enforceMaxCacheSize(cache: Map<string, JudgeVerdict>): void {
  if (cache.size <= VERDICT_CACHE_MAX_SIZE) return;
  const deleteCount = Math.floor(cache.size / 2);
  let deleted = 0;
  for (const key of cache.keys()) {
    if (deleted >= deleteCount) break;
    cache.delete(key);
    deleted++;
  }
}

// ---------------------------------------------------------------------------
// Categories that bypass the judge (safety / correctness)
// ---------------------------------------------------------------------------

const AUTO_APPROVE_CATEGORIES = new Set(["correction", "principle"]);

/** Explicit trigger phrasing — procedures must match to persist (issue #519). */
const PROCEDURE_TRIGGER_RE =
  /(when you|whenever|before you|before running|always\s|first\b.*\bthen|to deploy|to ship|run these steps|follow these steps|how (i|we)\s|recipe for|workflow|each time you)/i;

/**
 * Deterministic gate for extracted `procedure` memories: ≥2 steps with non-empty
 * intents and explicit trigger wording in title and/or steps.
 */
export function validateProcedureExtraction(input: {
  content: string;
  procedureSteps?: unknown;
}): JudgeVerdict {
  const steps = normalizeProcedureSteps(input.procedureSteps);
  if (steps.length < 2) {
    return { durable: false, reason: "Procedure requires at least two steps with intents" };
  }
  const combined = [input.content, ...steps.map((s) => s.intent)].join(" ").toLowerCase();
  if (!PROCEDURE_TRIGGER_RE.test(combined)) {
    return { durable: false, reason: "Procedure missing explicit trigger phrasing" };
  }
  return { durable: true, reason: "Procedure structure validated" };
}

// ---------------------------------------------------------------------------
// Core judge function
// ---------------------------------------------------------------------------

/**
 * Evaluate a batch of candidate facts for durability.
 *
 * Auto-approves corrections, principles, and critical-importance facts.
 * Remaining candidates are batched (up to extractionJudgeBatchSize),
 * checked against an in-memory content-hash cache, and sent to the LLM
 * for verdict.
 */
export async function judgeFactDurability(
  candidates: JudgeCandidate[],
  config: PluginConfig,
  localLlm: LocalLlmClient | null,
  fallbackLlm: FallbackLlmClient | null,
  cache?: Map<string, JudgeVerdict>,
  deferCounts?: Map<string, number>,
  onVerdict?: (observation: JudgeVerdictObservation) => void,
): Promise<JudgeBatchResult> {
  const startMs = Date.now();
  const verdicts = new Map<number, JudgeVerdict>();
  let cached = 0;
  let judged = 0;
  let deferred = 0;
  let deferredCappedToReject = 0;

  // Use caller-provided cache for per-orchestrator scoping, or fall back
  // to the module-level default cache.
  const verdictCache = cache ?? defaultVerdictCache;
  const deferCountMap = deferCounts ?? defaultDeferCounts;
  const deferCap = resolveDeferCap(config);

  // Lazy emit (Codex P2): when `onVerdict` is undefined (default path —
  // telemetry off), payload construction is skipped entirely. Callers
  // pass a factory instead of a pre-built observation so the `sha256`
  // `contentHash` and surrounding object allocation only run when a
  // subscriber is present. For large batches with telemetry off this
  // removes per-verdict overhead that would otherwise fire on every
  // auto-approved / cache / fail-open path.
  const emit = (build: () => JudgeVerdictObservation): void => {
    if (!onVerdict) return;
    let observation: JudgeVerdictObservation;
    try {
      observation = build();
    } catch (err) {
      log.debug(
        `extraction-judge: onVerdict builder threw (non-fatal): ${err instanceof Error ? err.message : String(err)}`,
      );
      return;
    }
    try {
      onVerdict(observation);
    } catch (err) {
      // Fail-open: telemetry errors must never block extraction.
      log.debug(
        `extraction-judge: onVerdict callback threw (non-fatal): ${err instanceof Error ? err.message : String(err)}`,
      );
    }
  };

  if (candidates.length === 0) {
    return {
      verdicts,
      cached,
      judged,
      elapsed: 0,
      deferred,
      deferredCappedToReject,
    };
  }

  // Indices that need LLM judgment
  const pendingIndices: number[] = [];

  for (let i = 0; i < candidates.length; i++) {
    const c = candidates[i];

    // Auto-approve safety categories
    if (AUTO_APPROVE_CATEGORIES.has(c.category)) {
      const v: JudgeVerdict = {
        durable: true,
        reason: `Auto-approved: ${c.category} category bypasses judge`,
      };
      verdicts.set(i, v);
      emit(() => ({
        verdict: v,
        candidate: c,
        contentHash: cacheKey(c.text, c.category),
        source: "auto-approve",
        priorDeferrals: 0,
        elapsedMs: Date.now() - startMs,
      }));
      continue;
    }

    // Auto-approve critical importance
    if (c.importanceLevel === "critical") {
      const v: JudgeVerdict = {
        durable: true,
        reason: "Auto-approved: critical importance",
      };
      verdicts.set(i, v);
      emit(() => ({
        verdict: v,
        candidate: c,
        contentHash: cacheKey(c.text, c.category),
        source: "auto-approve",
        priorDeferrals: 0,
        elapsedMs: Date.now() - startMs,
      }));
      continue;
    }

    // Check cache
    const key = cacheKey(c.text, c.category);
    const cachedVerdict = verdictCache.get(key);
    if (cachedVerdict) {
      verdicts.set(i, cachedVerdict);
      cached++;
      emit(() => ({
        verdict: cachedVerdict,
        candidate: c,
        contentHash: key,
        source: "cache",
        priorDeferrals: deferCountMap.get(key) ?? 0,
        elapsedMs: Date.now() - startMs,
      }));
      continue;
    }

    pendingIndices.push(i);
  }

  // If all resolved without LLM, return early
  if (pendingIndices.length === 0) {
    return {
      verdicts,
      cached,
      judged,
      elapsed: Date.now() - startMs,
      deferred,
      deferredCappedToReject,
    };
  }

  // Batch the pending candidates up to batchSize
  const batchSize = Math.min(config.extractionJudgeBatchSize, MAX_JUDGE_BATCH);
  // Defer bookkeeping spans the WHOLE call, not one batch: identical candidates can land in different batches, and each key
  // must advance the defer cap once and decide against the same prior count (the snapshot taken at its first sighting).
  const deferredThisCall = new Set<string>();
  const priorDefersSeen = new Map<string, number>();
  for (let batchStart = 0; batchStart < pendingIndices.length; batchStart += batchSize) {
    const batchIndices = pendingIndices.slice(batchStart, batchStart + batchSize);
    const request = buildJudgeRequest(
      batchIndices.map((idx) => ({
        index: idx,
        text: candidates[idx].text,
        category: candidates[idx].category,
        confidence: candidates[idx].confidence,
      })),
    );

    try {
      const llmResponse = await callJudgeLlm(request, config, localLlm, fallbackLlm);

      if (llmResponse) {
        const parsed = parseJudgeResponse(llmResponse, batchIndices);
        // Per-call defer-increment dedupe (codex P2): a single extraction
        // pass must not advance the cap more than once for identical
        // candidate content, even if the same text appears several times in
        // one LLM response or in different batches of one call. Duplicate
        // hits share the first sighting's `priorDeferrals` snapshot.
        for (const [idx, rawVerdict] of parsed.entries()) {
          const c = candidates[idx];
          const key = cacheKey(c.text, c.category);
          let verdict = rawVerdict;
          let source: JudgeVerdictObservation["source"] = "llm";
          if (!priorDefersSeen.has(key)) priorDefersSeen.set(key, deferCountMap.get(key) ?? 0);
          const priorDefers = priorDefersSeen.get(key) ?? 0;

          // Defer cap (issue #562, PR 2). A candidate that has already been
          // deferred `deferCap` times is forcibly rejected so a pathological
          // LLM response cannot produce an infinite defer loop.
          if (getVerdictKind(verdict) === "defer") {
            if (priorDefers >= deferCap) {
              verdict = {
                durable: false,
                reason: `Defer cap reached (${deferCap} prior defers); rejecting`,
                kind: "reject",
              };
              source = "llm-cap-rejected";
              // Only clear + count the cap conversion once per batch for
              // this key — duplicates in the same response all resolve to
              // reject but should not inflate the cap-rejection counter.
              if (!deferredThisCall.has(key)) {
                deferCountMap.delete(key);
                deferredCappedToReject++;
                deferredThisCall.add(key);
              }
            } else if (!deferredThisCall.has(key)) {
              deferCountMap.set(key, priorDefers + 1);
              deferred++;
              deferredThisCall.add(key);
              // Bound the per-process defer-counter map.
              if (deferCountMap.size > DEFER_COUNT_MAX_SIZE) {
                const drop = Math.floor(deferCountMap.size / 2);
                let dropped = 0;
                for (const k of deferCountMap.keys()) {
                  if (dropped >= drop) break;
                  deferCountMap.delete(k);
                  dropped++;
                }
              }
            }
            // else: duplicate defer for a key already counted this call —
            // no additional counter increment, verdict still marked defer.
          } else {
            // On accept/reject, clear any outstanding defer counter so a
            // future reappearance of the same text starts fresh.
            deferCountMap.delete(key);
            priorDefersSeen.set(key, 0);
            deferredThisCall.delete(key);
          }

          verdicts.set(idx, verdict);
          judged++;
          // Cache non-defer verdicts. Defer is intentionally NOT cached:
          // caching it would short-circuit the re-evaluation pass that is
          // the entire point of the defer verdict.
          if (getVerdictKind(verdict) !== "defer") {
            verdictCache.set(key, verdict);
          }
          emit(() => ({
            verdict,
            candidate: c,
            contentHash: key,
            source,
            priorDeferrals: priorDefers,
            elapsedMs: Date.now() - startMs,
          }));
        }
        // Evict oldest entries if cache exceeds max size
        enforceMaxCacheSize(verdictCache);
      }
    } catch (err) {
      // Fail-open: if the LLM call fails, approve all candidates in this batch
      log.warn(
        `extraction-judge: LLM call failed, approving batch (fail-open): ${err instanceof Error ? err.message : String(err)}`,
      );
    }

    // Fill in any missing verdicts from this batch (fail-open: approve).
    // Clear defer counts so a transient outage doesn't leave stale state
    // that causes later defers to hit the cap early.
    for (const idx of batchIndices) {
      if (!verdicts.has(idx)) {
        const c = candidates[idx];
        const hash = cacheKey(c.text, c.category);
        // Capture the prior deferral count BEFORE clearing so the
        // telemetry event reflects the true state rather than always 0.
        const priorDefers = deferCountMap.get(hash) ?? 0;
        deferCountMap.delete(hash);
        priorDefersSeen.set(hash, 0);
        deferredThisCall.delete(hash);
        const v: JudgeVerdict = {
          durable: true,
          reason: "Approved by default (judge unavailable or parse error)",
        };
        verdicts.set(idx, v);
        emit(() => {
          return {
            verdict: v,
            candidate: c,
            contentHash: hash,
            source: "fail-open",
            priorDeferrals: priorDefers,
            elapsedMs: Date.now() - startMs,
          };
        });
      }
    }
  }

  return {
    verdicts,
    cached,
    judged,
    elapsed: Date.now() - startMs,
    deferred,
    deferredCappedToReject,
  };
}

// ---------------------------------------------------------------------------
// LLM call helpers
// ---------------------------------------------------------------------------

async function callJudgeLlm(
  request: JudgeRequest,
  config: PluginConfig,
  localLlm: LocalLlmClient | null,
  fallbackLlm: FallbackLlmClient | null,
): Promise<string | null> {
  const { messages, maxTokens } = request;

  const modelOverride = config.extractionJudgeModel || undefined;

  // When modelSource is "gateway", skip localLlm and go directly to fallback
  // (the gateway-routed backend). This respects the operator's explicit
  // routing preference.
  const skipLocal = config.modelSource === "gateway";

  // Route judge-gated extractions through the SAME shared resolution as every
  // other background task (taskModelChain > gatewayAgentId in gateway mode), so
  // the judge never silently falls back to the persona/default chain when a
  // task chain is configured (gotcha #22, #39). Issue #1365 / PR #1425.
  const gatewayChain = gatewayTaskChainOptions(config);

  // Try local LLM first (unless modelSource says gateway)
  if (localLlm && !skipLocal) {
    try {
      const result = await (localLlm as any).chatCompletion(messages, {
        temperature: 0.1,
        maxTokens,
        // A verdict needs no reasoning: keep a thinking-capable model from spending the compact budget on it.
        disableThinking: true,
        responseFormat: { type: "json_object" },
        timeoutMs: config.extractionJudgeTimeoutMs,
        // The client applies timeoutMs per attempt and retries an abort once:
        // one deadline signal bounds the whole call to the configured time.
        signal: AbortSignal.timeout(config.extractionJudgeTimeoutMs),
        operation: "extraction-judge",
        ...(modelOverride ? { model: modelOverride } : {}),
      });
      if (result?.content) {
        return result.content;
      }
    } catch (err) {
      log.debug(
        `extraction-judge: local LLM failed, trying fallback: ${err instanceof Error ? err.message : String(err)}`,
      );
    }
  }

  // Try fallback LLM
  if (fallbackLlm) {
    try {
      const result = await fallbackLlm.chatCompletion(
        messages as Array<{ role: "system" | "user" | "assistant"; content: string }>,
        {
          temperature: 0.1,
          maxTokens,
          reasoningHeadroomTokens: JUDGE_REASONING_HEADROOM_TOKENS,
          timeoutMs: config.extractionJudgeTimeoutMs,
          ...(modelOverride ? { model: modelOverride } : {}),
          ...gatewayChain,
        },
      );
      if (result?.content) {
        return result.content;
      }
    } catch (err) {
      log.debug(
        `extraction-judge: fallback LLM failed: ${err instanceof Error ? err.message : String(err)}`,
      );
    }
  }

  return null;
}

interface JudgeVerdictItem {
  index?: number;
  kind?: string;
  action?: string;
  durable?: boolean;
  reason?: string;
}

/** What a judge model may return: a bare array, or one object wrapping verdicts. */
interface JudgeEnvelope {
  verdicts?: JudgeVerdictItem[];
  index?: number;
}

type ParsedJudgeJson = JudgeVerdictItem[] | JudgeEnvelope | null | undefined;

/**
 * Normalise the object shapes a judge model returns to a verdict array.
 * Requested shape {"verdicts": [...]} (response_format json_object forces a
 * top-level object); a single verdict object counts as one verdict at its
 * index, never the whole batch; legacy: any array-valued key.
 */
function unwrapJudgeEnvelope(parsed: ParsedJudgeJson): JudgeVerdictItem[] | null {
  if (!parsed || Array.isArray(parsed)) return null;
  if (Array.isArray(parsed.verdicts)) return parsed.verdicts;
  if (Number.isInteger(parsed.index)) return [parsed];
  for (const v of Object.values(parsed)) {
    if (Array.isArray(v)) return v;
  }
  return null;
}

// ---------------------------------------------------------------------------
// Response parsing
// ---------------------------------------------------------------------------

function parseJudgeResponse(
  raw: string,
  expectedIndices: number[],
): Map<number, JudgeVerdict> {
  const result = new Map<number, JudgeVerdict>();
  const expectedSet = new Set(expectedIndices);

  try {
    // Try direct parse first, then fall back to JSON extraction
    let parsed: ParsedJudgeJson;
    try {
      parsed = JSON.parse(raw);
    } catch {
      const candidates = extractJsonCandidates(raw);
      if (candidates.length > 0) {
        parsed = JSON.parse(candidates[0]);
      }
    }

    if (!Array.isArray(parsed)) {
      const unwrapped = unwrapJudgeEnvelope(parsed);
      if (unwrapped === null) {
        log.debug("extraction-judge: response is not an array, cannot parse");
        return result;
      }
      parsed = unwrapped;
    }

    for (const item of parsed) {
      if (
        typeof item !== "object" ||
        item === null ||
        typeof (item as any).index !== "number"
      ) {
        continue;
      }
      const idx = (item as any).index as number;
      if (!expectedSet.has(idx)) continue;

      // Parse kind first — it's the primary signal in PR 2 and above.
      // Fall back to durable for pre-PR-2 model responses that only return
      // the boolean.
      let kind: JudgeVerdictKind | undefined;
      const rawKind = (item as any).kind;
      const rawAction = (item as any).action;
      if (rawKind === "accept" || rawKind === "reject" || rawKind === "defer") {
        kind = rawKind;
      } else if (
        rawAction === "accept" ||
        rawAction === "reject" ||
        rawAction === "defer"
      ) {
        // Tolerate `action` as an alias — MemReader uses that word in the
        // paper and models may echo it.
        kind = rawAction;
      }

      const hasDurable = typeof (item as any).durable === "boolean";
      const durableFromModel = hasDurable
        ? ((item as any).durable as boolean)
        : undefined;

      // Resolve the durable flag from kind when present; otherwise trust
      // the model's boolean; otherwise fail-open to durable=true.
      let durable: boolean;
      if (kind === "accept") {
        durable = true;
      } else if (kind === "reject" || kind === "defer") {
        durable = false;
      } else if (durableFromModel !== undefined) {
        durable = durableFromModel;
      } else {
        durable = true; // fail-open
      }

      const reason =
        typeof (item as any).reason === "string"
          ? ((item as any).reason as string).slice(0, 120)
          : "No reason provided";

      const verdict: JudgeVerdict = { durable, reason };
      if (kind !== undefined) verdict.kind = kind;
      result.set(idx, verdict);
    }
  } catch (err) {
    log.debug(
      `extraction-judge: failed to parse response: ${err instanceof Error ? err.message : String(err)}`,
    );
  }

  return result;
}

// ---------------------------------------------------------------------------
// Cache management (exposed for testing)
// ---------------------------------------------------------------------------

/** Clear the in-memory default verdict cache. Primarily for tests. */
export function clearVerdictCache(): void {
  defaultVerdictCache.clear();
  defaultDeferCounts.clear();
}

/** Return the current default verdict cache size. Primarily for tests. */
export function verdictCacheSize(): number {
  return defaultVerdictCache.size;
}

/** Create a new per-instance verdict cache. Orchestrators should hold one. */
export function createVerdictCache(): Map<string, JudgeVerdict> {
  return new Map();
}

/**
 * Create a new per-instance defer-counter map. Orchestrators should hold one
 * alongside their verdict cache so defer counts survive across extraction
 * passes within a single orchestrator but do not leak across orchestrators.
 */
export function createDeferCountMap(): Map<string, number> {
  return new Map();
}

/**
 * Extraction faithfulness gate — entailment verification of extracted
 * facts against their verified source spans (issue #1576).
 *
 * Part of #1572 (glass-box memory). Depends on #1575 (provenance spans).
 * Improved later by #1585 (fine-tuned local gate model).
 *
 * Unlike the extraction-judge (#376), which gates on fact-worthiness
 * ("is this worth remembering?"), this module gates on faithfulness
 * ("is this fact actually supported by what was said?"). Hallucinated
 * or mis-paraphrased extractions become durable memories, get recalled
 * with confidence, and poison downstream answers — the highest-severity
 * accuracy failure a memory system can have.
 *
 * Design constraints:
 *   - Tagged results only — a backend failure is distinguishable from a
 *     genuine verdict (rule 34 / checklist §22: never conflate "empty"
 *     with "failed").
 *   - The gate consumes the QUOTE, not the whole conversation — passing
 *     full turns re-introduces the hallucination surface you're guarding
 *     and blows the latency budget.
 *   - No module-level state — batch queues hang off the orchestrator
 *     instance (rule 11).
 *   - Byte-identical pre-feature pipeline when mode is "off" (rule 39).
 *   - Graceful degradation — a backend failure never blocks writes
 *     (checklist §4); the fact proceeds with verdict "unchecked".
 *   - Never mutate mw_*\/trust fields — faithfulness is its own
 *     frontmatter island consumed by #1577.
 */

import { createHash } from "node:crypto";

import { log } from "./logger.js";
import type { PluginConfig, MemoryFrontmatter, FaithfulnessFrontmatter } from "./types.js";
import type { LocalLlmClient } from "./local-llm.js";
import { type FallbackLlmClient, gatewayTaskChainOptions } from "./fallback-llm.js";
import {
  callOpenAiCompatibleChat,
  resolveFaithfulnessGateEndpoint,
} from "./local-model-endpoint.js";
import { extractJsonCandidates } from "./json-extract.js";

// Re-export for callers importing from this module.
export type { FaithfulnessFrontmatter } from "./types.js";

// ---------------------------------------------------------------------------
// Public types
// ---------------------------------------------------------------------------

/**
 * The three entailment verdicts. "unchecked" is NOT a member of this union —
 * it lives only in the frontmatter to mark facts that bypassed the gate
 * (backend failure, no span, mode=off). A real verdict is always one of
 * these three.
 */
export type FaithfulnessVerdict = "entailed" | "contradicted" | "unsupported";

/**
 * Failure codes for tagged-error results. Each is distinguishable so callers
 * and telemetry can tell "no span available" from "the backend was down".
 */
export type FaithfulnessFailureCode =
  | "no_span"
  | "backend_unavailable"
  | "malformed_output"
  | "timeout";

/**
 * Tagged result — success carries the verdict + model + optional rationale;
 * failure carries only the error code. Never conflate the two (rule 34).
 */
export type FaithfulnessResult =
  | { ok: true; verdict: FaithfulnessVerdict; model: string; rationale?: string }
  | { ok: false; error: { code: FaithfulnessFailureCode } };

/**
 * Input for a single faithfulness check. The quote is the verified span from
 * #1575; context is optional surrounding turn text (bounded by
 * faithfulnessContextChars).
 */
export interface FaithfulnessCheckInput {
  factText: string;
  quote: string;
  context?: string;
}

/**
 * Shape persisted to frontmatter (issue #1576). Serialized as a single JSON
 * line so it round-trips through the existing YAML parser without special
 * handling.
 *
 * `verdict: "unchecked"` marks a fact that entered the gate but could not be
 * evaluated (backend failure, timeout). It is distinct from the field being
 * absent (which means the gate was off entirely or the fact predates #1576).
 */

// ---------------------------------------------------------------------------
// Sealed prompt (hash lets #1573-style caching key on it)
// ---------------------------------------------------------------------------

const FAITHFULNESS_SYSTEM_PROMPT = `You are a faithfulness verifier for a memory system. Given a QUOTE from the source conversation and an extracted FACT, determine whether the FACT is supported by the QUOTE.

Rules:
- "entailed" — the FACT directly follows from the QUOTE (paraphrase is OK).
- "contradicted" — the FACT asserts something the QUOTE directly negates.
- "unsupported" — the FACT introduces information not present in the QUOTE.

Answer with a JSON array. Each element: {"index": <int>, "verdict": "entailed"|"contradicted"|"unsupported", "rationale": "<one sentence>"}.

Examples:
QUOTE: "I've been using Vim for about ten years now."
FACT: "The user has used Vim for approximately a decade."
{"index": 0, "verdict": "entailed", "rationale": "Paraphrase of the same duration."}

QUOTE: "I've been using Vim for about ten years now."
FACT: "The user prefers Emacs."
{"index": 0, "verdict": "unsupported", "rationale": "QUOTE mentions Vim, not Emacs."}

QUOTE: "I stopped drinking coffee last month."
FACT: "The user drinks coffee regularly."
{"index": 0, "verdict": "contradicted", "rationale": "QUOTE says they stopped; FACT claims the opposite."}`;

/**
 * SHA-256 hash of the sealed system prompt. Cache keys and prompt-version
 * telemetry include this so a prompt change is detectable (#1573-style
 * caching can invalidate stale entries).
 */
export const FAITHFULNESS_PROMPT_HASH = createHash("sha256")
  .update(FAITHFULNESS_SYSTEM_PROMPT)
  .digest("hex");

// ---------------------------------------------------------------------------
// Prompt construction
// ---------------------------------------------------------------------------

/**
 * Build the user-prompt payload for a batch of (fact, quote) pairs.
 * Each pair is numbered so the LLM's response can be correlated back.
 *
 * Context (when provided) is included after the quote, clearly delimited,
 * so the model knows it is supplementary — not the primary evidence.
 */
function buildBatchPrompt(inputs: FaithfulnessCheckInput[], contextChars: number): string {
  const parts: string[] = [];
  for (let i = 0; i < inputs.length; i++) {
    const inp = inputs[i];
    if (!inp) continue;
    // The QUOTE is the primary entailment evidence and is already bounded
    // upstream (provenance.maxQuoteChars / locateFactQuote). Send it whole
    // so the verifier never judges entailment on a truncated span. Only the
    // supplementary CONTEXT is bounded by contextChars (the config's "window
    // around the quote" semantics — cursor review).
    parts.push(`--- Item ${i} ---
QUOTE: "${inp.quote}"`);
    if (inp.context && inp.context.trim().length > 0) {
      parts.push(`CONTEXT: "${inp.context.slice(0, contextChars)}"`);
    }
    parts.push(`FACT: "${inp.factText}"

Respond with the JSON array entry for index ${i}.`);
  }
  parts.push(`\nRespond now with a single JSON array covering indexes 0–${inputs.length - 1}.`);
  return parts.join("\n");
}

// ---------------------------------------------------------------------------
// Response parsing
// ---------------------------------------------------------------------------

const VALID_VERDICTS = new Set<string>(["entailed", "contradicted", "unsupported"]);

/**
 * Parsed LLM response entry — validated shape.
 */
interface ParsedFaithfulnessEntry {
  index: number;
  verdict: FaithfulnessVerdict;
  rationale?: string;
}

/**
 * Parse the LLM response into a map of index → entry. Returns null when the
 * response is unparseable (rules 13/18: malformed output → tagged error,
 * never a crash).
 *
 * Accepts both a bare JSON array and a JSON array embedded in surrounding
 * text (the `extractJsonCandidates` helper handles fenced blocks and
 * code-block-wrapped JSON).
 */
export function parseFaithfulnessResponse(
  raw: string,
  expectedCount: number,
): Map<number, ParsedFaithfulnessEntry> | null {
  if (!raw || typeof raw !== "string" || raw.trim().length === 0) {
    return null;
  }

  const candidates = extractJsonCandidates(raw);
  for (const candidate of candidates) {
    let parsed: unknown;
    try {
      parsed = JSON.parse(candidate);
    } catch {
      continue;
    }
    const map = parseEntries(parsed, expectedCount);
    if (map) return map;
  }

  // Last resort: the model may have returned bare objects without array
  // wrapping — try parsing the whole thing as a single entry.
  try {
    const single = JSON.parse(raw.trim());
    const map = parseEntries([single], expectedCount);
    if (map) return map;
  } catch {
    // fall through
  }

  return null;
}

/**
 * True when `map` contains an entry for every integer index in
 * [0, expectedCount). The local parse-fallback gate uses this to accept a
 * local model-lab response only when it is COMPLETE: size alone is
 * insufficient because a malformed response with duplicate/fractional indexes
 * can yield expectedCount distinct map keys without covering index 0..N-1
 * (codex P2 PRRT_kwDORJXyws6O7PfY). parseEntries now rejects non-integer
 * indexes so the two checks agree, but the explicit coverage loop documents
 * the invariant and stays robust to any future parser relaxation.
 */
function coversAllIndexes(
  map: Map<number, ParsedFaithfulnessEntry>,
  expectedCount: number,
): boolean {
  if (map.size < expectedCount) return false;
  for (let i = 0; i < expectedCount; i++) {
    if (!map.has(i)) return false;
  }
  return true;
}

function parseEntries(
  data: unknown,
  expectedCount: number,
): Map<number, ParsedFaithfulnessEntry> | null {
  if (!Array.isArray(data)) {
    // Accept object-wrapped arrays — {"results":[...]}, {"verdicts":[...]},
    // {"entries":[...]}, {"facts":[...]} — a common JSON-object prompt shape the
    // extraction-judge parser already accepts. Rejecting them marked the whole
    // batch malformed_output; in enforce mode those facts then wrote as ACTIVE
    // (gate bypass — codex Ob4RO).
    if (data && typeof data === "object") {
      for (const key of ["results", "verdicts", "entries", "facts"]) {
        const inner = (data as Record<string, unknown>)[key];
        if (Array.isArray(inner)) return parseEntries(inner, expectedCount);
      }
    }
    return null;
  }
  const map = new Map<number, ParsedFaithfulnessEntry>();
  for (const entry of data) {
    if (!entry || typeof entry !== "object") continue;
    const obj = entry as Record<string, unknown>;
    const idx = typeof obj.index === "number" ? obj.index : undefined;
    if (idx === undefined || !Number.isInteger(idx) || idx < 0 || idx >= expectedCount) continue;
    const verdictRaw = typeof obj.verdict === "string" ? obj.verdict : undefined;
    if (!verdictRaw || !VALID_VERDICTS.has(verdictRaw)) continue;
    const rationale =
      typeof obj.rationale === "string" && obj.rationale.trim().length > 0
        ? obj.rationale.trim().slice(0, 500)
        : undefined;
    map.set(idx, {
      index: idx,
      verdict: verdictRaw as FaithfulnessVerdict,
      rationale,
    });
  }
  return map.size > 0 ? map : null;
}

// ---------------------------------------------------------------------------
// LLM call helper
// ---------------------------------------------------------------------------

interface LlmCallResult {
  content: string | null;
  modelUsed: string | null;
}

/**
 * Call the model routing chain (local → fallback) with the faithfulness
 * classification prompt. Mirrors `callJudgeLlm` in extraction-judge.ts so
 * the same routing, model-override, and gateway-chain logic applies.
 *
 * Returns the raw content string and the model that produced it, or
 * `{ content: null, modelUsed: null }` when every backend is unavailable.
 */
async function callFaithfulnessLlm(
  systemPrompt: string,
  userPrompt: string,
  expectedCount: number,
  config: PluginConfig,
  localLlm: LocalLlmClient | null,
  fallbackLlm: FallbackLlmClient | null,
  timeoutMs: number,
  signal?: AbortSignal,
  fetchImpl: typeof fetch = fetch,
): Promise<LlmCallResult> {
  const messages: Array<{ role: "system" | "user"; content: string }> = [
    { role: "system", content: systemPrompt },
    { role: "user", content: userPrompt },
  ];

  // Issue #1585 model-lab pointer: when an explicit local fine-tuned endpoint
  // is configured (base URL + model name), try it FIRST — it is the cheapest,
  // deterministic path the operator opted into by setting
  // extractionFaithfulnessBaseUrl. Unset (the default) skips this entirely,
  // preserving byte-identical pre-feature routing (rule 39). Any failure
  // (network, non-2xx, malformed body, timeout) returns null and falls through
  // to the configured chain (checklist §4 graceful degradation).
  const localEndpoint = resolveFaithfulnessGateEndpoint(config);
  if (localEndpoint) {
    // Give the local probe a SMALLER budget than the outer batch timeout so a
    // wedged local model returns null (and falls through to the configured
    // chain) before the batch timer fires. The local endpoint is meant to be
    // the fast path; if it cannot answer within half the budget (min 500ms),
    // abandon it and let the fallback chain use the remainder (codex P2 — the
    // advertised graceful fallback must actually reach the chain, not be starved
    // by a hanging probe sharing the full batch budget).
    const probeBudgetMs = Math.max(500, Math.floor(timeoutMs / 2));
    const result = await callOpenAiCompatibleChat(
      localEndpoint,
      messages,
      {
        temperature: 0.1,
        maxTokens: 2048,
        responseFormatJson: true,
        timeoutMs: probeBudgetMs,
        // Forward the batch signal so the probe aborts the instant the batch
        // budget elapses, not after probeBudgetMs (issue #1700 nit #5).
        ...(signal ? { signal } : {}),
      },
      fetchImpl,
    );
    if (result?.content) {
      // Issue #1700 nit #6: pre-validate the local endpoint response shape.
      // Default (extractionFaithfulnessLocalParseFallback=false) returns the
      // content as-is -- a 200-with-garbage local response surfaces
      // malformed_output, alerting the operator to a misconfigured endpoint.
      // When the operator opts into resilient fallback, an unparseable OR
      // PARTIAL local response falls through to the configured chain instead
      // of surfacing. parseFaithfulnessResponse is truthy as soon as ONE entry
      // is valid, so accept the local response only when the parsed verdict
      // map covers every expected index -- otherwise the missing indexes would
      // surface as malformed_output downstream, defeating the resilient
      // fallback (codex P2 PRRT_kwDORJXyws6O6zwZ).
      if (!config.extractionFaithfulnessLocalParseFallback) {
        return { content: result.content, modelUsed: result.modelUsed };
      }
      const parsedLocal = parseFaithfulnessResponse(result.content, expectedCount);
      if (parsedLocal && coversAllIndexes(parsedLocal, expectedCount)) {
        return { content: result.content, modelUsed: result.modelUsed };
      }
      log.debug(
        "extraction-faithfulness: local endpoint returned incomplete/unparseable output; falling back to configured chain",
      );
    } else {
      log.debug(
        "extraction-faithfulness: local model-lab endpoint unavailable, trying configured chain",
      );
    }
  }

  // extractionFaithfulnessModel is the LOCAL served model's name (e.g.
  // remnic-faithfulness-gate-v1). When a local endpoint is configured it
  // belongs to that endpoint ONLY — it must NOT leak into the fallback chain
  // as a gateway/local-LLM override, or a local outage forces the configured
  // chain onto an unavailable local-only model and turns graceful fallback
  // into backend_unavailable (codex P2 PRRT_kwDORJXyws6Otp-L). Decouple: the
  // override reaches the fallback chain only when NO local endpoint is
  // configured (the pre-feature model-override contract, preserved
  // byte-identical — rule 39).
  const modelOverride = localEndpoint ? undefined : (config.extractionFaithfulnessModel || undefined);

  // Skip the local backend when (a) modelSource is "gateway", or (b) a
  // faithfulness model override is set. The local client always sends
  // config.localLlmModel and silently ignores options.model, so a local
  // success would run the wrong model and prevent the override from ever
  // reaching the gateway. Routing straight to the gateway honors the
  // override (codex review PRRT_kwDORJXyws6ObYQ8).
  const skipLocal = config.modelSource === "gateway" || Boolean(modelOverride);
  const gatewayChain = gatewayTaskChainOptions(config);

  let modelUsed: string | null = null;

  // Try local LLM first (only when no override routes the call to gateway).
  // The local client uses its OWN per-attempt AbortController keyed on
  // `timeoutMs` (it does not read options.signal — see LocalLlmChatCompletionOptions),
  // so the batch `signal` is not forwarded here; `timeoutMs` bounds each local
  // attempt instead. The batch AbortController still governs the fallback path,
  // which DOES honor the signal. (Matches extraction-judge.ts, which also passes
  // no signal to the local client.)
  if (localLlm && !skipLocal) {
    try {
      const result = await callLocalLlm(localLlm, messages, {
        temperature: 0.1,
        maxTokens: 2048,
        responseFormat: { type: "json_object" },
        timeoutMs,
        operation: "extraction-faithfulness",
      });
      if (result.content) {
        return { content: result.content, modelUsed: result.modelUsed ?? "local" };
      }
    } catch (err) {
      log.debug(
        `extraction-faithfulness: local LLM failed, trying fallback: ${err instanceof Error ? err.message : String(err)}`,
      );
    }
  }

  // Try fallback LLM
  if (fallbackLlm) {
    try {
      const result = await fallbackLlm.chatCompletion(
        messages as Array<{ role: "system" | "user" | "assistant"; content: string }>,
        {
          temperature: 0.1,
          maxTokens: 2048,
          timeoutMs,
          ...(modelOverride ? { model: modelOverride } : {}),
          ...gatewayChain,
          ...(signal ? { signal } : {}),
        },
      );
      if (result?.content) {
        return { content: result.content, modelUsed: result.modelUsed ?? "fallback" };
      }
    } catch (err) {
      log.debug(
        `extraction-faithfulness: fallback LLM failed: ${err instanceof Error ? err.message : String(err)}`,
      );
    }
  }

  return { content: null, modelUsed: null };
}

/**
 * Call the local LLM's chatCompletion through a narrow, typed interface.
 * LocalLlmClient.chatCompletion accepts an options bag that includes an
 * `operation` discriminator; we forward it so the client can route
 * appropriately.
 */
interface LocalLlmCallOptions {
  temperature: number;
  maxTokens: number;
  responseFormat?: { type: string };
  timeoutMs: number;
  operation: string;
}

interface LocalLlmCallResponse {
  content: string | null;
  modelUsed?: string;
}

async function callLocalLlm(
  client: LocalLlmClient,
  messages: Array<{ role: "system" | "user"; content: string }>,
  options: LocalLlmCallOptions,
): Promise<LocalLlmCallResponse> {
  // LocalLlmClient.chatCompletion returns { content: string } — we use a
  // typed call signature so no `any` leaks. The local client does not
  // expose modelUsed, so we return "local" as the model identifier.
  const result = await client.chatCompletion(messages, options);
  return {
    content: result?.content ?? null,
  };
}

// ---------------------------------------------------------------------------
// Core batch check
// ---------------------------------------------------------------------------

/**
 * Result of a batch faithfulness check — per-input results plus timing.
 */
export interface FaithfulnessBatchResult {
  results: FaithfulnessResult[];
  /** Wall-clock duration of the LLM call (0 when backend was not called). */
  elapsedMs: number;
}

/**
 * Evaluate a batch of (fact, quote) pairs for faithfulness.
 *
 * - Calls the LLM once with all pairs (bounded by `inputs.length`).
 * - On timeout → every input gets `{ ok: false, code: "timeout" }`.
 * - On backend unavailable → `{ ok: false, code: "backend_unavailable" }`.
 * - On malformed output → `{ ok: false, code: "malformed_output" }`.
 * - Inputs with empty quotes get `{ ok: false, code: "no_span" }` and are
 *   NOT sent to the LLM.
 *
 * No module-level state: the caller (orchestrator) owns any caches.
 */
export async function checkFaithfulnessBatch(
  inputs: FaithfulnessCheckInput[],
  config: PluginConfig,
  localLlm: LocalLlmClient | null,
  fallbackLlm: FallbackLlmClient | null,
  /**
   * Optional fetch injection (issue #1585). The orchestrator does not pass it
   * (uses global fetch); tests pass a stub to exercise the local model-lab
   * endpoint path without a live server. See callFaithfulnessLlm.
   */
  fetchImpl?: typeof fetch,
): Promise<FaithfulnessBatchResult> {
  const timeoutMs =
    typeof config.extractionFaithfulnessTimeoutMs === "number" &&
    Number.isFinite(config.extractionFaithfulnessTimeoutMs) &&
    config.extractionFaithfulnessTimeoutMs > 0
      ? config.extractionFaithfulnessTimeoutMs
      : 8000;

  const contextChars =
    typeof config.extractionFaithfulnessContextChars === "number" &&
    Number.isFinite(config.extractionFaithfulnessContextChars) &&
    config.extractionFaithfulnessContextChars > 0
      ? config.extractionFaithfulnessContextChars
      : 400;

  // Partition: inputs with a real quote vs. inputs without one.
  const results: FaithfulnessResult[] = new Array(inputs.length);
  const checkableIndices: number[] = [];
  const checkableInputs: FaithfulnessCheckInput[] = [];

  for (let i = 0; i < inputs.length; i++) {
    const inp = inputs[i];
    if (!inp || !inp.quote || inp.quote.trim().length === 0) {
      results[i] = { ok: false, error: { code: "no_span" } };
    } else if (!inp.factText || inp.factText.trim().length === 0) {
      results[i] = { ok: false, error: { code: "no_span" } };
    } else {
      checkableIndices.push(i);
      checkableInputs.push(inp);
    }
  }

  if (checkableInputs.length === 0) {
    return { results, elapsedMs: 0 };
  }

  const userPrompt = buildBatchPrompt(checkableInputs, contextChars);
  const startedAt = Date.now();

  let timedOut = false;
  const controller = new AbortController();
  // Race the LLM call against the budget so the batch fails open at
  // `timeoutMs` regardless of which backend is in flight. The local backend
  // ignores the batch AbortSignal (it aborts each attempt via its own
  // controller keyed on `timeoutMs`), so awaiting callFaithfulnessLlm directly
  // could block past the budget on a slow/retrying local verifier. The timer
  // both aborts the fallback (which honors the signal) and resolves the race
  // so the batch returns promptly; the in-flight local call aborts on its own
  // per-attempt timeoutMs. (codex review PRRT_kwDORJXyws6ObgMJ.)
  // Manual deferred instead of Promise.withResolvers (ES2024) — plugin-openclaw's
  // standalone tsconfig targets ES2022 lib and this module is reachable from its
  // type graph, so withResolvers would TS2550 there.
  let resolveTimeout!: (value: true) => void;
  const racedTimeout = new Promise<true>((resolve) => {
    resolveTimeout = resolve;
  });
  const timer = setTimeout(() => {
    timedOut = true;
    controller.abort();
    resolveTimeout(true);
  }, timeoutMs);

  try {
    const callPromise = callFaithfulnessLlm(
      FAITHFULNESS_SYSTEM_PROMPT,
      userPrompt,
      checkableInputs.length,
      config,
      localLlm,
      fallbackLlm,
      timeoutMs,
      controller.signal,
      fetchImpl,
    );
    const settled = await Promise.race([
      callPromise.then(
        (r) => ({ done: true as const, result: r }),
        // An unexpected throw is treated as "no content" (backend_unavailable)
        // so the race never rejects and the outer catch is the final safety net.
        () => ({ done: true as const, result: { content: null, modelUsed: null } }),
      ),
      racedTimeout.then(() => ({ done: false as const })),
    ]);
    const elapsedMs = Date.now() - startedAt;

    if (!settled.done) {
      // The budget elapsed before any backend returned content. Fail open as
      // timeout; the orphaned callPromise resolves/rejects harmlessly (the
      // fallback was aborted; the local client aborts on its own timeoutMs).
      for (const idx of checkableIndices) {
        results[idx] = { ok: false, error: { code: "timeout" } };
      }
      return { results, elapsedMs };
    }

    const llmResult = settled.result;

    // Cursor review: if the LLM returned usable content, use it even when
    // the abort timer raced — a response that lands just as the timer fires
    // has real verdicts. Only fall back to timeout errors when there is no
    // content to parse (the call genuinely did not complete in time).
    if (timedOut && !llmResult.content) {
      for (const idx of checkableIndices) {
        results[idx] = { ok: false, error: { code: "timeout" } };
      }
      return { results, elapsedMs };
    }

    if (!llmResult.content) {
      for (const idx of checkableIndices) {
        results[idx] = { ok: false, error: { code: "backend_unavailable" } };
      }
      return { results, elapsedMs };
    }

    const parsed = parseFaithfulnessResponse(llmResult.content, checkableInputs.length);
    if (!parsed) {
      for (const idx of checkableIndices) {
        results[idx] = { ok: false, error: { code: "malformed_output" } };
      }
      return { results, elapsedMs };
    }

    for (let j = 0; j < checkableIndices.length; j++) {
      const inputIdx = checkableIndices[j];
      if (inputIdx === undefined) continue;
      const entry = parsed.get(j);
      if (entry) {
        results[inputIdx] = {
          ok: true,
          verdict: entry.verdict,
          model: llmResult.modelUsed ?? "unknown",
          ...(entry.rationale ? { rationale: entry.rationale } : {}),
        };
      } else {
        // LLM response was missing this index
        results[inputIdx] = { ok: false, error: { code: "malformed_output" } };
      }
    }

    return { results, elapsedMs };
  } catch (err) {
    const elapsedMs = Date.now() - startedAt;
    if (timedOut || isAbortError(err)) {
      for (const idx of checkableIndices) {
        results[idx] = { ok: false, error: { code: "timeout" } };
      }
      return { results, elapsedMs };
    }
    log.warn(
      `extraction-faithfulness: batch check threw unexpectedly: ${err instanceof Error ? err.message : String(err)}`,
    );
    for (const idx of checkableIndices) {
      results[idx] = { ok: false, error: { code: "backend_unavailable" } };
    }
    return { results, elapsedMs };
  } finally {
    clearTimeout(timer);
  }
}

function isAbortError(err: unknown): boolean {
  if (!err || typeof err !== "object") return false;
  const maybe = err as { name?: string; message?: string };
  return (
    maybe.name === "AbortError" ||
    maybe.message === "This operation was aborted" ||
    maybe.message === "The operation was aborted"
  );
}


// ---------------------------------------------------------------------------
// Extraction-path orchestration helpers (issue #1576)
//
// These wrap checkFaithfulnessBatch + verdict application so the orchestrator
// holds only thin delegation (ground rule 4: god files gain thin wiring only).
// The core algorithm lives above; these are call-site glue.
// ---------------------------------------------------------------------------

/**
 * Telemetry counters for the faithfulness gate. Hang off the orchestrator
 * instance (rule 11: no module-level state) and surface via console_state so
 * `remnic doctor` renders the verdict distribution.
 */
export interface FaithfulnessGateCounters {
  entailed: number;
  contradicted: number;
  unsupported: number;
  unchecked: number;
  skippedNoSpan: number;
}

/**
 * Create a fresh zeroed counters object. Callers store it on the orchestrator
 * instance and pass it by reference to the gate helpers, which mutate it.
 */
export function createFaithfulnessCounters(): FaithfulnessGateCounters {
  return { entailed: 0, contradicted: 0, unsupported: 0, unchecked: 0, skippedNoSpan: 0 };
}

/**
 * Structural slice of an extracted fact that the gate reads. Kept loose so
 * this pure module does not depend on the full `ExtractedFact` type.
 */
export interface FaithfulnessGateFact {
  content: string;
  sources?: { quote?: string }[];
}

/**
 * Run the faithfulness batch over a list of extracted facts and return a map
 * keyed by the ORIGINAL fact index → result. Facts without a usable verified
 * source span are omitted from the batch (they are tagged `skipped_no_span`
 * at apply time, never gated — don't punish legacy data). Updates `counters`
 * for console_state telemetry.
 *
 * Fail-open: any pipeline error is caught, logged, and an empty map returned
 * so the caller records `unchecked`/`skipped_no_span` and proceeds — a gate
 * outage must never block memory writes (checklist §4).
 */
// Common English stopwords — filtered before overlap scoring so function
// words (the, a, is, ...) don't dilute the signal between a fact and its
// source sentence.
const STOPWORDS = new Set([
  "the","a","an","and","or","but","is","are","was","were","be","been","being",
  "to","of","in","on","at","for","with","from","by","as","it","its","this","that",
  "these","those","i","you","he","she","we","they","my","your","his","her","our","their",
  "has","have","had","do","does","did","will","would","can","could","should","not","no",
  "s","very","really","just","so","than","then","there","here","about","into","over","under",
]);

/**
 * Crude stemmer: strip common suffixes so "prefers"/"prefer",
 * "using"/"use", "started"/"start" collapse to one token. Not a real
 * stemmer — just enough to raise recall for the interim locator (#1575 will
 * replace this with NLI-verified spans).
 */
function crudeStem(word: string): string {
  if (word.length > 5 && word.endsWith("ing")) return word.slice(0, -3);
  if (word.length > 4 && word.endsWith("ed")) return word.slice(0, -2);
  if (word.length > 3 && (word.endsWith("s")) && !word.endsWith("ss")) return word.slice(0, -1);
  return word;
}

/**
 * Tokenize text into a lowercase, stopword-filtered, crudely-stemmed token
 * set for overlap scoring.
 */
function tokenize(text: string): Set<string> {
  const tokens = new Set<string>();
  for (const raw of text.toLowerCase().split(/[^a-z0-9]+/)) {
    if (raw.length <= 1) continue;
    if (STOPWORDS.has(raw)) continue;
    tokens.add(crudeStem(raw));
  }
  return tokens;
}

/**
 * Overlap coefficient: |A ∩ B| / min(|A|, |B|). Robust for paraphrase
 * matching where a short fact paraphrases a longer source sentence — a short
 * fact fully supported by a long sentence scores high, unrelated text scores 0.
 */
function overlapCoefficient(a: Set<string>, b: Set<string>): number {
  if (a.size === 0 || b.size === 0) return 0;
  let intersection = 0;
  const [small, large] = a.size <= b.size ? [a, b] : [b, a];
  for (const t of small) if (large.has(t)) intersection++;
  return intersection / small.size;
}

/**
 * Minimum overlap for a located quote to be trusted as the fact's source span.
 * Below this the fact is treated as having no located span (skipped_no_span)
 * rather than judged against an unrelated sentence.
 */
const LOCATE_QUOTE_MIN_OVERLAP = 0.3;

/**
 * Locate the best-matching verbatim span (sentence) from the source turn text
 * for an extracted fact, by token overlap. Returns the quote when a confident
 * match is found, `undefined` otherwise (the gate then records
 * skipped_no_span — never judged against an unrelated span).
 *
 * This is the interim source-text locator that makes the gate functional on
 * real extraction output (where #1575 has not yet attached per-fact
 * `sources`). It produces a genuine located quote per fact so the gate
 * consumes a span, not the whole conversation (issue #1576 design constraint).
 * #1575's NLI-verified per-fact locator will replace this when it lands.
 */
/**
 * Extract a bounded window of `sourceText` centered on the located `quote`,
 * bounded by `contextChars` (the config's "window around the quote" semantics).
 *
 * Used by the fallback-locator path in `runFaithfulnessGateBatch` so the
 * verifier sees surrounding turn text — without it,
 * `extractionFaithfulnessContextChars` is effectively ignored in the
 * production path (codex review PRRT_kwDORJXyws6OblI1). Returns undefined when
 * the quote is absent from sourceText (e.g. it was truncated by maxQuoteChars).
 */
export function extractContextWindow(
  sourceText: string,
  quote: string,
  contextChars: number,
  /**
   * Character offset of `quote` within `sourceText` (from `locateFactQuote`).
   * When the quote string appears more than once — e.g. repeated anaphoric
   * lines after different entities — pass the matched occurrence's offset so
   * the context window centers on the actual match, not the first occurrence
   * (issue #1633, codex PRRT_kwDORJXyws6ObzwI). Defaults to the first
   * occurrence via indexOf for backward compatibility.
   */
  matchedOffset?: number,
): string | undefined {
  if (!sourceText || !quote || !(contextChars > 0)) return undefined;
  let idx: number;
  if (matchedOffset !== undefined && matchedOffset >= 0) {
    const at = sourceText.indexOf(quote, matchedOffset);
    // Fall back to the first occurrence if the matched offset is stale (e.g.
    // the quote was bounded and is not a literal substring at that offset).
    idx = at >= 0 ? at : sourceText.indexOf(quote);
  } else {
    idx = sourceText.indexOf(quote);
  }
  if (idx < 0) return undefined;
  const quoteEnd = idx + quote.length;
  const center = Math.floor((idx + quoteEnd) / 2);
  const half = Math.floor(contextChars / 2);
  let start = Math.max(0, center - half);
  const end = Math.min(sourceText.length, start + contextChars);
  // Re-anchor start so the window uses the full budget when end clamped.
  start = Math.max(0, end - contextChars);
  const window = sourceText.slice(start, end).trim();
  return window.length > 0 ? window : undefined;
}

/**
 * A located fallback quote plus the offset it begins at in the source text.
 * `offset` lets `extractContextWindow` disambiguate repeated occurrences of
 * the same quote string (issue #1633).
 */
export interface LocatedQuote {
  /** Verbatim source span, centered on the matched terms when truncated. */
  quote: string;
  /** Character offset of `quote` within sourceText. */
  offset: number;
}

interface SourceCandidate {
  /** Trimmed candidate text. */
  text: string;
  /** Character offset of `text` within the source string. */
  start: number;
}

/**
 * Split source text into candidate spans (sentences, then line segments as a
 * fallback for transcripts without sentence punctuation), tracking each
 * candidate's start offset so repeated occurrences can be disambiguated
 * (issue #1633).
 */
function splitSourceCandidates(sourceText: string): SourceCandidate[] {
  const candidates: SourceCandidate[] = [];
  const re = /(?<=[.!?])\s+|\n+/g;
  let lastEnd = 0;
  let m: RegExpExecArray | null;
  while ((m = re.exec(sourceText)) !== null) {
    pushCandidate(candidates, sourceText, lastEnd, m.index);
    lastEnd = re.lastIndex;
  }
  pushCandidate(candidates, sourceText, lastEnd, sourceText.length);
  return candidates;
}

function pushCandidate(
  out: SourceCandidate[],
  source: string,
  begin: number,
  end: number,
): void {
  const seg = source.slice(begin, end);
  const leadingWS = seg.length - seg.trimStart().length;
  const trimmed = seg.trim();
  if (trimmed.length > 0) {
    out.push({ text: trimmed, start: begin + leadingWS });
  }
}

/**
 * Locate the start offsets of fact-token matches inside a candidate. Used by
 * `locateFactQuote` to build a bounded window that is guaranteed to contain
 * real evidence (issue #1633, codex PRRT_kwDORJXyws6Obrwe / PRRT_kwDORJXyws6Oce-O).
 */
function locateMatchedTokens(factTokens: Set<string>, candidate: string): number[] {
  const lower = candidate.toLowerCase();
  const wordRe = /[a-z0-9]+/g;
  const positions: number[] = [];
  let m: RegExpExecArray | null;
  while ((m = wordRe.exec(lower)) !== null) {
    const word = m[0];
    if (word.length <= 1) continue;
    if (STOPWORDS.has(word)) continue;
    if (factTokens.has(crudeStem(word))) {
      positions.push(m.index);
    }
  }
  return positions;
}

/**
 * Build a bounded window of `maxChars` from `text` that contains the densest
 * cluster of matched-token positions. Slides a maxChars-wide window anchored
 * at each matched token and keeps the one that captures the most matches
 * (tiebreak: earliest anchor). This guarantees the window includes real
 * evidence even when the matched span is wider than `maxChars` (e.g. fact
 * tokens at both ends of a long sentence with filler between). Centering on
 * the densest cluster's midpoint then uses any leftover budget as leading and
 * trailing context. Returns the window text and its start offset within `text`
 * so callers can translate the in-candidate offset back to a source-text offset.
 */
function boundedWindow(
  text: string,
  matchedPositions: number[],
  maxChars: number,
): { text: string; start: number } {
  if (matchedPositions.length === 0) {
    // Defensive: overlap scoring accepted the candidate but no individual
    // token matched (e.g. all matches were stopwords). Fall back to prefix.
    const end = Math.min(text.length, maxChars);
    return { text: text.slice(0, end), start: 0 };
  }
  // matchedPositions is sorted ascending (the regex scans left-to-right), so a
  // two-pointer sliding window finds the densest maxChars-wide cluster in O(n)
  // instead of O(n^2). This matters when a long unpunctuated candidate carries
  // many repeats of a fact token (pasted logs, minified text) — thousands of
  // positions would otherwise stall extraction before the LLM call (codex
  // PRRT_kwDORJXyws6Ocih3).
  let bestAnchor = matchedPositions[0]!;
  let bestCount = 0;
  let bestLast = bestAnchor;
  let j = 0;
  for (let i = 0; i < matchedPositions.length; i++) {
    const anchor = matchedPositions[i]!;
    const winEnd = anchor + maxChars;
    if (j < i) j = i;
    while (j + 1 < matchedPositions.length && matchedPositions[j + 1]! < winEnd) {
      j++;
    }
    const count = j - i + 1;
    if (count > bestCount) {
      bestCount = count;
      bestAnchor = anchor;
      bestLast = matchedPositions[j]!;
    }
  }
  // The densest cluster [bestAnchor, bestLast] fits within maxChars by
  // construction; center a maxChars window on its midpoint, clamped to text.
  const center = Math.floor((bestAnchor + bestLast) / 2);
  const half = Math.floor(maxChars / 2);
  let start = Math.max(0, center - half);
  const end = Math.min(text.length, start + maxChars);
  // Re-anchor start so the window uses the full budget when end clamped.
  start = Math.max(0, end - maxChars);
  return { text: text.slice(start, end), start };
}

export function locateFactQuote(
  factText: string,
  sourceText: string,
  maxQuoteChars = 600,
): LocatedQuote | undefined {
  if (!factText || !sourceText) return undefined;
  const factTokens = tokenize(factText);
  if (factTokens.size === 0) return undefined;
  const candidates = splitSourceCandidates(sourceText);
  if (candidates.length === 0) return undefined;
  // Pick the best-overlap candidate. Tiebreak equal own-overlap scores by a
  // "context" score that includes the immediately PRECEDING candidate's text,
  // so a repeated anaphoric line ("It launched in March") resolves to the
  // occurrence whose neighbor names the fact's entity (issue #1633, codex
  // PRRT_kwDORJXyws6Oce-S). Without this tiebreak the first occurrence wins
  // even when the second is the one the fact refers to.
  let best: { candidate: SourceCandidate; score: number; contextScore: number } | null = null;
  for (let i = 0; i < candidates.length; i++) {
    const candidate = candidates[i]!;
    const score = overlapCoefficient(factTokens, tokenize(candidate.text));
    const prevText = i > 0 ? candidates[i - 1]!.text : "";
    const contextText = prevText ? `${prevText} ${candidate.text}` : candidate.text;
    const contextScore = overlapCoefficient(factTokens, tokenize(contextText));
    if (
      !best ||
      score > best.score ||
      (score === best.score && contextScore > best.contextScore)
    ) {
      best = { candidate, score, contextScore };
    }
  }
  if (!best || best.score < LOCATE_QUOTE_MIN_OVERLAP) return undefined;
  const { text, start } = best.candidate;
  if (text.length <= maxQuoteChars) {
    return { quote: text, offset: start };
  }
  // Build a bounded window around the densest cluster of matched terms instead
  // of returning the first maxQuoteChars prefix (issue #1633). Returning the
  // prefix drops supporting words that fall after char ~600, routing
  // actually-entailed facts to pending_review in enforce mode.
  const matched = locateMatchedTokens(factTokens, text);
  const win = boundedWindow(text, matched, maxQuoteChars);
  return { quote: win.text, offset: start + win.start };
}
export async function runFaithfulnessGateBatch(
  facts: readonly FaithfulnessGateFact[],
  mode: "shadow" | "enforce",
  config: PluginConfig,
  localLlm: LocalLlmClient | null,
  fallbackLlm: FallbackLlmClient | null,
  counters: FaithfulnessGateCounters,
  /**
   * The verbatim source turn text the facts were extracted from. When a fact
   * has no #1575 `sources`, locateFactQuote finds a fallback span here so the
   * gate runs on real extraction output. May be empty (replay/import paths
   * with no source turns) — facts then get skipped_no_span.
   */
  sourceText = "",
): Promise<Map<number, FaithfulnessResult> | null> {
  // Phase 1 — build the checkable inputs. This is pure (no LLM, no throw):
  // locateFactQuote and the source/span selection never reject. Keeping it
  // outside the try lets the catch walk the same inputs to tag a pipeline
  // failure as "unchecked" rather than dropping it on the floor.
  const inputs: { factIndex: number; input: FaithfulnessCheckInput }[] = [];
  for (let fi = 0; fi < facts.length; fi++) {
    const f = facts[fi];
    if (!f || typeof f.content !== "string" || !f.content.trim()) continue;
    // Prefer #1575 verified spans; fall back to a located quote from the
    // source turn text so the gate runs even before per-fact sources are
    // attached. Without either, the fact is skipped_no_span (never gated).
    // A composite fact may be supported by multiple adjacent spans — collect
    // every valid source quote so the verifier sees the full evidence, not
    // just sources[0] (codex review PRRT_kwDORJXyws6ObYQ_).
    const sources = Array.isArray(f.sources) ? f.sources : [];
    const sourceQuotes = sources
      .map((s) => (s && typeof s.quote === "string" ? s.quote.trim() : ""))
      .filter((q) => q.length > 0);
    const usingFallbackLocator = sourceQuotes.length === 0;
    let quote: string;
    let matchedOffset: number | undefined;
    if (sourceQuotes.length > 0) {
      quote = sourceQuotes.join("\n");
    } else {
      // Fallback locator returns the matched span AND its offset so the
      // context window centers on the occurrence that actually matched the
      // fact, not the first indexOf hit (issue #1633).
      const located = locateFactQuote(f.content, sourceText);
      if (!located) continue; // no located span — applyFaithfulnessVerdict tags skipped_no_span
      quote = located.quote;
      matchedOffset = located.offset;
    }
    // Pass source context into the verifier so extractionFaithfulnessContextChars
    // actually applies in the fallback-locator path (codex P2
    // PRRT_kwDORJXyws6OblI1). #1575 verified spans already carry full evidence,
    // so context is only synthesized for the fallback locator.
    const fallbackContext =
      usingFallbackLocator
        ? extractContextWindow(
            sourceText,
            quote,
            config.extractionFaithfulnessContextChars,
            matchedOffset,
          )
        : undefined;
    inputs.push({
      factIndex: fi,
      input: {
        factText: f.content,
        quote,
        ...(fallbackContext ? { context: fallbackContext } : {}),
      },
    });
  }
  const resultsByFactIndex = new Map<number, FaithfulnessResult>();
  if (inputs.length === 0) return resultsByFactIndex;
  try {
    const batch = await checkFaithfulnessBatch(
      inputs.map((x) => x.input),
      config,
      localLlm,
      fallbackLlm,
    );
    for (let j = 0; j < inputs.length; j++) {
      const entry = inputs[j];
      if (entry) resultsByFactIndex.set(entry.factIndex, batch.results[j]!);
    }
    // Verdict-distribution counters are bumped in applyFaithfulnessVerdict
    // (at the per-fact apply point), NOT here, so console_state reflects
    // facts that actually reached verdict application — not facts later
    // dropped by dedup, importance, or judge gates (cursor review).
    log.info(
      `extraction-faithfulness[${mode}]: ${inputs.length} facts checked, ${batch.elapsedMs}ms`,
    );
  } catch (err) {
    // Fail-open: a pipeline error never blocks writes (checklist §4). Tag each
    // checkable fact as backend_unavailable so applyFaithfulnessVerdict records
    // "unchecked" (issue spec: backend failure → unchecked). Returning null
    // here would make a shadow/enforce batch failure indistinguishable from
    // gate-off, losing the telemetry signal (cursor review). Facts with no
    // located span stay absent → skipped_no_span at apply time.
    log.warn(
      `extraction-faithfulness: pipeline error, tagging ${inputs.length} checkable facts as unchecked (fail-open): ${err instanceof Error ? err.message : String(err)}`,
    );
    for (const { factIndex } of inputs) {
      resultsByFactIndex.set(factIndex, { ok: false, error: { code: "backend_unavailable" } });
    }
  }
  return resultsByFactIndex;
}

/**
 * Apply a pre-computed faithfulness verdict to a single fact, producing the
 * frontmatter record + an optional enforce-mode `pending_review` status.
 *
 * - `resultsByFactIndex` null (gate off) → nothing (rule 39: byte-identical).
 * - fact has no entry (no verified span) → `skipped_no_span`, never gated.
 * - backend failure (`ok: false`) → `unchecked`, fact proceeds (checklist §4).
 * - enforce + unsupported/contradicted → `pending_review` (memory persists,
 *   enters the review queue, never silently dropped).
 *
 * Mutates `counters.skippedNoSpan` for facts without a span.
 */
export function applyFaithfulnessVerdict(
  resultsByFactIndex: Map<number, FaithfulnessResult> | null,
  factLoopIndex: number,
  mode: "off" | "shadow" | "enforce",
  factContent: string,
  counters: FaithfulnessGateCounters,
): {
  faithfulness: FaithfulnessFrontmatter | undefined;
  enforceStatus: "pending_review" | undefined;
} {
  if (!resultsByFactIndex) {
    return { faithfulness: undefined, enforceStatus: undefined };
  }
  const result = resultsByFactIndex.get(factLoopIndex);
  if (!result) {
    // No result for this fact index — it had no verified source span.
    counters.skippedNoSpan++;
    return {
      faithfulness: { verdict: "skipped_no_span", at: new Date().toISOString() },
      enforceStatus: undefined,
    };
  }
  if (result.ok) {
    if (result.verdict === "entailed") counters.entailed++;
    else if (result.verdict === "contradicted") counters.contradicted++;
    else if (result.verdict === "unsupported") counters.unsupported++;
    const fm: FaithfulnessFrontmatter = {
      verdict: result.verdict,
      ...(result.model ? { model: result.model } : {}),
      ...(result.rationale ? { rationale: result.rationale } : {}),
      at: new Date().toISOString(),
    };
    let enforceStatus: "pending_review" | undefined;
    if (
      mode === "enforce" &&
      (result.verdict === "unsupported" || result.verdict === "contradicted")
    ) {
      enforceStatus = "pending_review";
      log.info(
        `extraction-faithfulness[enforce]: routing "${factContent.slice(0, 60)}…" to pending_review (verdict=${result.verdict})`,
      );
    }
    return { faithfulness: fm, enforceStatus };
  }
  // Backend failure — record as unchecked, fact proceeds (graceful degradation).
  counters.unchecked++;
  return {
    faithfulness: { verdict: "unchecked", at: new Date().toISOString() },
    enforceStatus: undefined,
  };
}
// ---------------------------------------------------------------------------
// Frontmatter serialization (single-line JSON, like provenance sources)
// ---------------------------------------------------------------------------

/**
 * Canonical key order for the serialized `faithfulness` frontmatter field.
 * Deterministic emission (rule 38).
 */
const FAITHFULNESS_KEY_ORDER = ["verdict", "model", "rationale", "at"] as const;

/**
 * Serialize the `faithfulness` frontmatter field as a single JSON line,
 * appended to `lines`. Called from `serializeFrontmatter` in storage.ts.
 *
 * Contract: when `fm.faithfulness` is absent, no line is emitted — the
 * memory round-trips byte-identical to pre-#1576 behavior (rule 39).
 */
export function serializeFaithfulnessFields(fm: MemoryFrontmatter, lines: string[]): void {
  if (!fm.faithfulness) return;
  const fm2 = fm.faithfulness;
  const canonical: Record<string, unknown> = {};
  for (const key of FAITHFULNESS_KEY_ORDER) {
    const val = fm2[key];
    if (val !== undefined && val !== null && val !== "") {
      canonical[key] = val;
    }
  }
  // verdict is always present on a valid FaithfulnessFrontmatter
  if (!canonical.verdict) return;
  lines.push(`faithfulness: ${JSON.stringify(canonical)}`);
}

/**
 * Parse the `faithfulness` frontmatter line from its single-line JSON form.
 * Returns `undefined` for missing, blank, or corrupt values so a malformed
 * frontmatter never poisons downstream readers (rule 34 spirit).
 */
export function parseFaithfulnessField(
  raw: string | undefined,
): FaithfulnessFrontmatter | undefined {
  if (!raw || typeof raw !== "string" || raw.trim().length === 0) return undefined;
  try {
    const parsed: unknown = JSON.parse(raw);
    if (!parsed || typeof parsed !== "object" || Array.isArray(parsed)) return undefined;
    const obj = parsed as Record<string, unknown>;
    const verdictRaw = typeof obj.verdict === "string" ? obj.verdict : undefined;
    if (!verdictRaw) return undefined;
    const validVerdicts = new Set([
      "entailed",
      "contradicted",
      "unsupported",
      "unchecked",
      "skipped_no_span",
    ]);
    if (!validVerdicts.has(verdictRaw)) return undefined;
    const result: FaithfulnessFrontmatter = {
      verdict: verdictRaw as FaithfulnessFrontmatter["verdict"],
    };
    if (typeof obj.model === "string" && obj.model.length > 0) {
      result.model = obj.model;
    }
    if (typeof obj.rationale === "string" && obj.rationale.length > 0) {
      result.rationale = obj.rationale.slice(0, 500);
    }
    if (typeof obj.at === "string" && obj.at.length > 0) {
      result.at = obj.at;
    }
    return result;
  } catch {
    return undefined;
  }
}

import type { PluginConfig } from "../types.js";
import type { SearchBackend } from "./port.js";
import path from "node:path";
import { NoopSearchBackend } from "./noop-backend.js";
import { RemoteSearchBackend } from "./remote-backend.js";
import { LanceDbBackend } from "./lancedb-backend.js";
import { MeilisearchBackend } from "./meilisearch-backend.js";
import { OramaBackend } from "./orama-backend.js";
import { EmbedHelper } from "./embed-helper.js";
import { QmdClient, type QmdClientOptions } from "../qmd.js";
import { log } from "../logger.js";
import { FaissConversationIndexAdapter } from "../conversation-index/faiss-adapter.js";
import { resolvePipelineProcessingCapabilities } from "../capabilities.js";
import {
  resolveIndexingCapabilities,
  resolveQmdCapabilities,
} from "../capabilities.js";
import {
  createConversationIndexBackend,
  type ConversationIndexBackend,
  type ConversationQmdRuntime,
} from "../conversation-index/backend.js";

/**
 * Resolve non-QMD backends from config.
 * Returns a SearchBackend for "noop" or "remote", or undefined to signal "use QMD".
 */
function resolveNonQmdBackend(config: PluginConfig): SearchBackend | undefined {
  const backend = config.searchBackend ?? "qmd";
  const collection = config.qmdCollection;

  if (backend === "noop") {
    return new NoopSearchBackend();
  }

  if (backend === "remote") {
    const baseUrl = config.remoteSearchBaseUrl || "http://localhost:8181";
    if (!config.remoteSearchBaseUrl) {
      log.warn("searchBackend is 'remote' but remoteSearchBaseUrl is not configured; using default http://localhost:8181");
    }
    return new RemoteSearchBackend({
      baseUrl,
      apiKey: config.remoteSearchApiKey,
      timeoutMs: config.remoteSearchTimeoutMs,
    });
  }

  if (backend === "lancedb") {
    const embedHelper = new EmbedHelper(config, {
      hostEmbeddingExpectedDimension: config.lanceEmbeddingDimension,
    });
    return new LanceDbBackend({
      dbPath: config.lanceDbPath!,
      collection,
      embedHelper,
      memoryDir: config.memoryDir,
      embeddingDimension: config.lanceEmbeddingDimension!,
    });
  }

  if (backend === "meilisearch") {
    return new MeilisearchBackend({
      host: config.meilisearchHost!,
      apiKey: config.meilisearchApiKey,
      collection,
      timeoutMs: config.meilisearchTimeoutMs,
      autoIndex: config.meilisearchAutoIndex,
      memoryDir: config.memoryDir,
    });
  }

  if (backend === "orama") {
    const embedHelper = new EmbedHelper(config, {
      hostEmbeddingExpectedDimension: config.oramaEmbeddingDimension,
    });
    return new OramaBackend({
      dbPath: config.oramaDbPath!,
      collection,
      embedHelper,
      memoryDir: config.memoryDir,
      embeddingDimension: config.oramaEmbeddingDimension!,
      cjkSegmentationEnabled: config.oramaCjkSegmentation !== false,
    });
  }

  return undefined;
}

/** Shared QMD options derived from plugin config. */
function qmdOptions(config: PluginConfig): QmdClientOptions {
  return {
    slowLog: {
      enabled: resolvePipelineProcessingCapabilities(config).slowLog,
      thresholdMs: config.slowLogThresholdMs,
    },
    updateTimeoutMs: config.qmdUpdateTimeoutMs,
    updateMinIntervalMs: config.qmdUpdateMinIntervalMs,
    qmdPath: config.qmdPath,
    daemonUrl: resolveQmdCapabilities(config).qmdDaemon ? config.qmdDaemonUrl : undefined,
    daemonRecheckIntervalMs: config.qmdDaemonRecheckIntervalMs,
    qmdSupportedVersion: config.qmdSupportedVersion,
    qmdAutoUpgradeEnabled: resolveQmdCapabilities(config).qmdAutoUpgrade,
    qmdAutoUpgradeCheckIntervalMs: config.qmdAutoUpgradeCheckIntervalMs,
    qmdChunkStrategy: config.qmdChunkStrategy,
    qmdCandidateLimit: config.qmdCandidateLimit,
    qmdQueryRerankEnabled: resolveQmdCapabilities(config).qmdQueryRerank,
    qmdIndexName: config.qmdIndexName,
    qmdForceCpu: config.qmdForceCpu,
    qmdGpuBackend: config.qmdGpuBackend,
    qmdEmbedParallelism: config.qmdEmbedParallelism,
    qmdEmbedModel: config.qmdEmbedModel,
    qmdRerankModel: config.qmdRerankModel,
    qmdGenerateModel: config.qmdGenerateModel,
    qmdSearchStrategy: config.qmdSearchStrategy,
    qmdSubprocessStrategy: config.qmdSubprocessStrategy,
    qmdDaemonTimeoutMs: config.qmdDaemonTimeoutMs,
  };
}

export function isSearchBackendEnabled(config: PluginConfig): boolean {
  const backend = config.searchBackend ?? "qmd";
  return backend !== "noop" && (backend !== "qmd" || resolveQmdCapabilities(config).qmd);
}

/**
 * Create a SearchBackend from plugin config.
 *
 * - "noop" → NoopSearchBackend
 * - "remote" → RemoteSearchBackend (HTTP REST)
 * - "qmd" (default) → QmdClient if qmdEnabled, else NoopSearchBackend
 */
export function createSearchBackend(config: PluginConfig): SearchBackend {
  if (!isSearchBackendEnabled(config)) return new NoopSearchBackend();
  const nonQmd = resolveNonQmdBackend(config);
  if (nonQmd) return nonQmd;
  return new QmdClient(config.qmdCollection, config.qmdMaxResults, qmdOptions(config));
}

/**
 * Create a SearchBackend for conversation index use.
 * Returns undefined if conversation index is not enabled or not using qmd backend.
 */
export function createConversationSearchBackend(config: PluginConfig): SearchBackend | undefined {
  if (!resolveIndexingCapabilities(config).conversationIndex || config.conversationIndexBackend !== "qmd") {
    return undefined;
  }

  // Conversation index is QMD-only — do not use lancedb/meilisearch/orama even if
  // searchBackend is set to one of those. Only respect "noop" to allow disabling.
  const backend = config.searchBackend ?? "qmd";
  if (backend === "noop") return undefined;

  // QMD — respect qmdEnabled to avoid spawning the binary
  if (!resolveQmdCapabilities(config).qmd) return undefined;

  return new QmdClient(
    config.conversationIndexQmdCollection,
    Math.max(6, config.conversationRecallTopK),
    qmdOptions(config),
  );
}

export interface ConversationIndexRuntime {
  qmd?: ConversationQmdRuntime;
  faiss?: FaissConversationIndexAdapter;
  backend?: ConversationIndexBackend;
}

export function createConversationIndexRuntime(
  config: PluginConfig,
  overrides?: {
    getQmd?: () => ConversationQmdRuntime | undefined;
    getFaiss?: () => FaissConversationIndexAdapter | undefined;
  },
): ConversationIndexRuntime {
  const qmd = createConversationSearchBackend(config) as ConversationQmdRuntime | undefined;
  let faiss: FaissConversationIndexAdapter | undefined;
  if (resolveIndexingCapabilities(config).conversationIndex && config.conversationIndexBackend === "faiss") {
    try {
      faiss = new FaissConversationIndexAdapter({
          memoryDir: config.memoryDir,
          scriptPath: config.conversationIndexFaissScriptPath,
          pythonBin: config.conversationIndexFaissPythonBin,
          modelId: config.conversationIndexFaissModelId,
          indexDir: config.conversationIndexFaissIndexDir,
          upsertTimeoutMs: config.conversationIndexFaissUpsertTimeoutMs,
          searchTimeoutMs: config.conversationIndexFaissSearchTimeoutMs,
          healthTimeoutMs: config.conversationIndexFaissHealthTimeoutMs,
          maxBatchSize: config.conversationIndexFaissMaxBatchSize,
          maxSearchK: config.conversationIndexFaissMaxSearchK,
      });
    } catch (err) {
      log.warn(`Conversation index FAISS adapter disabled: ${err instanceof Error ? err.message : String(err)}`);
    }
  }

  const backend = createConversationIndexBackend({
    enabled: resolveIndexingCapabilities(config).conversationIndex,
    backend: config.conversationIndexBackend,
    getQmd: () => overrides?.getQmd?.() ?? qmd,
    getFaiss: () => overrides?.getFaiss?.() ?? faiss,
    collectionDir: path.join(config.memoryDir, "conversation-index"),
  });

  return { qmd, faiss, backend };
}

