  private toProjectedCurrentState(memory: MemoryFile, fallbackStatus: MemoryStatus): MemoryProjectionCurrentState {
    const pathRel = toMemoryPathRel(this.baseDir, memory.path);
    return {
      memoryId: memory.frontmatter.id,
      category: memory.frontmatter.category,
      status: inferCurrentStateStatus(memory.frontmatter, pathRel, fallbackStatus),
      lifecycleState: memory.frontmatter.lifecycleState,
      path: memory.path,
      pathRel,
      created: memory.frontmatter.created,
      updated: memory.frontmatter.updated,
      archivedAt: memory.frontmatter.archivedAt,
      supersededAt: memory.frontmatter.supersededAt,
      entityRef: memory.frontmatter.entityRef,
      source: memory.frontmatter.source,
      confidence: memory.frontmatter.confidence,
      confidenceTier: memory.frontmatter.confidenceTier,
      memoryKind: memory.frontmatter.memoryKind,
      accessCount: memory.frontmatter.accessCount,
      lastAccessed: memory.frontmatter.lastAccessed,
      tags: normalizeProjectionTags(memory.frontmatter.tags),
      preview: normalizeProjectionPreview(memory.content),
      privateRecord: isSupportPassportPrivateMemory(memory),
    };
  }

  async getMemoryTimeline(memoryId: string, limit: number = 200): Promise<MemoryLifecycleEvent[]> {
    const cappedLimit = Math.max(0, Math.floor(limit));
    if (cappedLimit === 0) return [];

    const projected = readProjectedMemoryTimeline(this.baseDir, memoryId, cappedLimit);
    if (projected && projected.length > 0) return projected;
    return this.projectionLedgerLagManager.resolveTimelineWithLag({
      baseDir: this.baseDir,
      ledgerPath: this.memoryLifecycleLedgerPath,
      memoryId,
      cappedLimit,
      readSecureFile: (p) => this.readStorageSecureFile(p),
      projectionAge: () => formatProjectionAge(readProjectionRebuiltAt(this.baseDir)),
    });
  }

  // ---------------------------------------------------------------------------
  // Chunking (Phase 2A)
  // ---------------------------------------------------------------------------

  /**
   * Write a memory chunk with parent reference.
   * Chunk IDs follow format: {parentId}-chunk-{index}
   */
  async writeChunk(
    parentId: string,
    chunkIndex: number,
    chunkTotal: number,
    category: MemoryCategory,
    content: string,
    options: {
      confidence?: number;
      tags?: string[];
      entityRef?: string;
      source?: string;
      importance?: ImportanceScore;
      intentGoal?: string;
      intentActionType?: string;
      intentEntityTypes?: string[];
      memoryKind?: MemoryFrontmatter["memoryKind"];
      validAt?: string;
      /** Lifecycle status (issue #1576): pending_review chunks stay out of active recall. */
      status?: import("./types.js").MemoryStatus;
      /**
       * Tombstone block provenance (issue #1645): when the parent fact was
       * tombstone-blocked, propagate the tombstone id onto each chunk so an
       * independently-surfaced chunk (memory_get/x-ray/doctor) reveals the block
       * and the chunk stays pending_review, never an active resurrection.
       */
      blockedBy?: string;
      /** Faithfulness gate verdict (issue #1576), propagated from the parent fact. */
      faithfulness?: import("./types.js").FaithfulnessFrontmatter;
      /** Claim-level provenance spans (issue #1575 PR 2), propagated from the parent fact so a chunk surfaced independently (memory_get/x-ray) preserves them (chatgpt-codex-connector thread Ocvmo). */
      sources?: ProvenanceSource[];
      /** Coarse provenance tag (issue #1575 PR 2), propagated from the parent. */
      provenance?: "verified" | "unverified" | "none";
      // Issue #1578 — bi-temporal bounds + ingestion provenance propagated from
      // the parent fact so an independently-surfaced chunk expires at the same
      // invalid_at window and carries the same observed-at anchor.
      invalidAt?: string;
      observedAt?: string;
      eventTimeSource?: "extracted" | "assumed";
      sourceConnector?: string;
      origin?: string;
      toolScoped?: true;
    } = {}
  ): Promise<string> {
    await this.ensureDirectories();
    const rawEntityRef = options.entityRef;
    let refIds = typeof options.entityRef === "string" ? this.currentHistoricalIds() : null;
    if (refIds) options = entityRefs.canonicalizeEntityRefOption(options, refIds);
    const now = new Date();
    const today = now.toISOString().slice(0, 10);
    const id = `${parentId}-chunk-${chunkIndex}`;
    const conf = options.confidence ?? 0.8;
    const tier = confidenceTier(conf);
    const validAt = normalizeMemoryWriteTimestamp("validAt", options.validAt);
    const chunkInvalidAt = normalizeMemoryWriteTimestamp("invalidAt", options.invalidAt);
    const chunkObservedAt = normalizeMemoryWriteTimestamp("observedAt", options.observedAt);
    const sanitized = sanitizeMemoryContent(content);
    if (!sanitized.clean) {
      log.warn(`chunk content sanitized for ${id}; violations=${sanitized.violations.join(", ")}`);
    }

    const fm: MemoryFrontmatter = {
      id,
      category,
      created: now.toISOString(),
      updated: now.toISOString(),
      source: options.source ?? "chunking",
      confidence: conf,
      confidenceTier: tier,
      tags: options.tags ?? [],
      entityRef: options.entityRef,
      importance: options.importance,
      parentId,
      chunkIndex,
      chunkTotal,
      intentGoal: options.intentGoal,
      intentActionType: options.intentActionType,
      intentEntityTypes: options.intentEntityTypes,
      memoryKind: options.memoryKind,
      valid_at: validAt,
      invalid_at: chunkInvalidAt,
      observedAt: chunkObservedAt,
      eventTimeSource: options.eventTimeSource,
      ...(options.status ? { status: options.status } : {}),
      ...(options.blockedBy ? { blockedBy: options.blockedBy } : {}),
      ...(options.faithfulness ? { faithfulness: options.faithfulness } : {}),
      ...(options.sources ? { sources: options.sources } : {}),
      ...(options.provenance ? { provenance: options.provenance } : {}),
      ...(options.sourceConnector ? { sourceConnector: options.sourceConnector } : {}),
      ...(options.origin ? { origin: parseOriginClass(options.origin) } : {}),
      ...(options.toolScoped ||
      withholdToolScopedFromSharedNamespace({
        content: sanitized.text,
        sourceConnector: options.sourceConnector,
      })
        ? { toolScoped: true as const }
        : {}),
    };

    const filePath = await this.resolveCategoryWritePath(category, id, today);
    const fileContent = `${serializeFrontmatter(this.withOkfType(fm))}\n\n${sanitized.text}\n`;

    const written = await this.writeTombstoneBlockedChunk(
      filePath,
      fileContent,
      fm,
      sanitized.text,
      () => this.findExistingTombstoneBlockedMemory(sanitized.text, category, fm.sourceConnector),
      async (priorChunk) => {
        if (refIds && typeof rawEntityRef === "string") {
          await this.entityRefRepair.repair(filePath, fm, rawEntityRef, refIds, sanitized.text, {
            regateFact: true,
            ...(priorChunk ? { onFailRestore: priorChunk } : { onFailRemove: filePath }),
          });
        }
        // Keep the version-keyed hot-memories cache coherent with the new chunk
        // file (issue #1902) — same single-file patch path writeMemory uses.
        await this.patchHotMemoriesCache({ addedPath: filePath }, "memory-create");
        log.debug(`wrote chunk ${id} (${chunkIndex + 1}/${chunkTotal}) to ${filePath}`);
      }
    );
    return written;
  }

  /**
   * Get all chunks for a given parent memory ID.
   * Returns chunks sorted by chunkIndex.
   */
  async getChunksForParent(parentId: string): Promise<MemoryFile[]> {
    const memories = await this.readAllMemories();
    return memories
      .filter((m) => m.frontmatter.parentId === parentId)
      .sort((a, b) => (a.frontmatter.chunkIndex ?? 0) - (b.frontmatter.chunkIndex ?? 0));
  }

  async supersedeMemory(
    oldMemoryId: string,
    newMemoryId: string,
    reason: string,
    supersessionMetadata?: Pick<MemoryFrontmatter, "supersessionCause" | "invalidatedBy">,
    options: {
      actor?: string; requireActive?: boolean; acceptExactReplay?: boolean;
      expectedSnapshot?: Pick<MemoryFile, "content" | "frontmatter"> & Partial<Pick<MemoryFile, "path">>;
      audit?: SupersessionAuditOptions;
    } = {},
  ): Promise<boolean> {
    const matchesSupersession = (memory: MemoryFile): boolean =>
      memory.frontmatter.status === "superseded" &&
      memory.frontmatter.supersededBy === newMemoryId &&
      (supersessionMetadata === undefined ||
        (memory.frontmatter.supersessionCause === supersessionMetadata.supersessionCause &&
          memory.frontmatter.invalidatedBy === supersessionMetadata.invalidatedBy));
    const isExactReplay = (memory: MemoryFile): boolean =>
      options.acceptExactReplay === true && matchesSupersession(memory);
    let oldMemory: MemoryFile | undefined;
    if (options.expectedSnapshot?.path) {
      const selected = await this.readMemoryByPath(options.expectedSnapshot.path);
      if (!selected || selected.frontmatter.id !== oldMemoryId) {
        return false;
      }
      if (
        invalidationCommitFingerprint(selected) !== invalidationCommitFingerprint(options.expectedSnapshot) &&
        !isExactReplay(selected)
      ) {
        return false;
      }
      oldMemory = selected;
    } else {
      const memories = [
        ...(await this.readAllMemories()),
        ...(await this.readAllColdMemories()),
        ...(await this.readArchivedMemories()),
      ];
      const candidates = memories.filter((memory) => memory.frontmatter.id === oldMemoryId);
      oldMemory =
        candidates.find(
          (memory) =>
            inferMemoryStatus(memory.frontmatter, toMemoryPathRel(this.baseDir, memory.path)) === "active",
        ) ??
        candidates.find(isExactReplay) ??
        candidates[0];
      if (
        oldMemory &&
        options.expectedSnapshot &&
        invalidationCommitFingerprint(oldMemory) !== invalidationCommitFingerprint(options.expectedSnapshot) &&
        !isExactReplay(oldMemory)
      ) {
        return false;
      }
    }
    if (!oldMemory) return false;
    const requireActiveAtWrite =
      options.requireActive === true ||
      inferMemoryStatus(oldMemory.frontmatter, toMemoryPathRel(this.baseDir, oldMemory.path)) === "active";

    const operationId = createHash("sha256")
      .update(
        JSON.stringify({
          oldMemoryId,
          newMemoryId,
          reason,
          supersessionMetadata: supersessionMetadata ?? null,
        }),
      )
      .digest("hex");
    const initialNow = new Date().toISOString();
    let currentBefore = oldMemory;
    let updatedFm = oldMemory.frontmatter;
    let exactReplay = false;

    try {
      const written = await this.withTombstoneBlockedMemoryPathLock(oldMemory.path, async (current) => {
        if (current?.frontmatter.id !== oldMemoryId) return false;
        if (matchesSupersession(current)) {
          currentBefore = current;
          updatedFm = current.frontmatter;
          return options.acceptExactReplay === true ? "exact-replay" : false;
        }
        if (
          options.expectedSnapshot &&
          invalidationCommitFingerprint(current) !== invalidationCommitFingerprint(options.expectedSnapshot)
        ) {
          return false;
        }
        if (
          current.frontmatter.supersededBy !== undefined ||
          (requireActiveAtWrite &&
            inferMemoryStatus(current.frontmatter, toMemoryPathRel(this.baseDir, current.path)) !== "active")
        ) {
          return false;
        }
        currentBefore = current;
        const refIdsAtWrite = this.currentHistoricalIds();
        updatedFm = entityRefs.canonicalizeEntityRefOption(
          {
            ...current.frontmatter,
            ...supersessionMetadata,
            status: "superseded",
            supersededBy: newMemoryId,
            supersededAt: initialNow,
            updated: initialNow,
          },
          refIdsAtWrite
        );
        const fileContent = `${serializeFrontmatter(this.withOkfType(updatedFm))}\n\n${current.content}\n`;
        await this.writeTombstoneBlockedFrontmatter(current, fileContent, updatedFm);
        if (this.isColdOrArchiveTierPath(current.path)) this.invalidateColdMemoriesCache();
        if (typeof current.frontmatter.entityRef === "string") {
          await this.entityRefRepair.repair(
            current.path,
            updatedFm,
            current.frontmatter.entityRef,
            refIdsAtWrite,
            current.content,
            { onFailRestore: current }
          );
        }
        return true;
      });
      if (!written) return false;
      exactReplay = written === "exact-replay";
      const mentionBefore = { entityRef: currentBefore.frontmatter.entityRef, origin: currentBefore.frontmatter.origin };
      if (exactReplay && typeof updatedFm.entityRef === "string") {
        await this.entityRefRepair.repair(
          currentBefore.path,
          updatedFm,
          updatedFm.entityRef,
          this.currentHistoricalIds(),
          currentBefore.content,
          { onFailRestore: currentBefore },
        );
      }
      const mentionUnchanged = entityMentionEpoch.neutral(mentionBefore, updatedFm);
      const supersededAt = updatedFm.supersededAt ?? initialNow;
      const beforeState = this.summarizeLifecycleState(
        currentBefore.frontmatter,
        currentBefore.path,
      );
      const afterState = this.summarizeLifecycleState(updatedFm, currentBefore.path);
      const sideEffectsComplete = await runSupersessionSideEffects({
        oldMemoryId,
        newMemoryId,
        reason,
        now: supersededAt,
        operationId,
        exactReplay,
        currentBefore,
        updatedFm,
        actor: options.actor, audit: options.audit,
        citationTemplate: this.citationTemplate,
        correctionsDir: this.correctionsDir,
        readMemoryByPath: (filePath) => this.readMemoryByPath(filePath),
        isColdOrArchiveTierPath: (memoryPath) => this.isColdOrArchiveTierPath(memoryPath),
        invalidateColdMemoriesCache: () => this.invalidateColdMemoriesCache(),
        invalidateAllMemoriesCache: () => this.invalidateAllMemoriesCache({ indexedText: mentionUnchanged ? false : undefined }),
        bumpMemoryCorpusVersion: () => this.bumpMemoryCorpusVersion({ indexedText: mentionUnchanged ? false : undefined }),
        appendLifecycleEvent: async () => {
          let lifecycleEvents: MemoryLifecycleEvent[] = [];
          try {
            lifecycleEvents = await this.getMemoryTimeline(oldMemoryId, 200);
          } catch (error) {
            log.warn(`supersession lifecycle replay check failed for ${oldMemoryId}: ${error}`);
          }
          if (
            lifecycleEvents.some(
              (event) =>
                event.memoryId === oldMemoryId &&
                event.eventType === "superseded" &&
                (event.correlationId === operationId ||
                  (event.correlationId === undefined &&
                    event.reasonCode === reason &&
                    event.timestamp === supersededAt &&
                    event.relatedMemoryIds?.includes(newMemoryId))),
            )
          ) {
            return;
          }
          await this.appendGeneratedMemoryLifecycleEventFailOpen("storage.supersedeMemory", {
            memoryId: oldMemoryId,
            eventType: "superseded",
            timestamp: supersededAt,
            actor: options.actor ?? "storage.supersedeMemory",
            reasonCode: reason,
            before: exactReplay ? { ...beforeState, status: "active" } : beforeState,
            after: afterState,
            relatedMemoryIds: [newMemoryId],
            correlationId: operationId,
          });
        },
        bumpMemoryStatusVersion: () => this.bumpMemoryStatusVersion(),
        hasExactTombstone: (input) => this.hasExactTombstone(input),
        appendTombstone: (input) => this.appendTombstone(input),
        writeSealedMemory: (envelope, extras) => this.writeSealedMemory(envelope, extras),
      });
      return sideEffectsComplete || options.acceptExactReplay !== true;
    } catch (err) {
      log.error(`failed to supersede memory ${oldMemoryId}:`, err);
      return false;
    }
  }

  private get summariesDir(): string {
    return path.join(this.baseDir, "summaries");
  }

  async writeSummary(summary: MemorySummary): Promise<void> {
    await mkdir(this.summariesDir, { recursive: true });
    const filePath = path.join(this.summariesDir, `${summary.id}.json`);
    await this.writeStorageSecureFile(filePath, JSON.stringify(summary, null, 2));
    log.debug(`wrote summary ${summary.id}`);
  }

  async readSummaries(): Promise<MemorySummary[]> {
    try {
      const files = await readdir(this.summariesDir);
      const summaries: MemorySummary[] = [];

      for (const file of files) {
        if (isMacOsReplicationJunkBasename(file) || !file.endsWith(".json")) continue;
        const filePath = path.join(this.summariesDir, file);
        const raw = await this.readStorageSecureFile(filePath);
        summaries.push(JSON.parse(raw) as MemorySummary);
      }

      return summaries;
    } catch (err) {
      if (err instanceof SecureStoreLockedError) throw err;
      if (!isErrnoCode(err, "ENOENT")) throw err;
      return [];
    }
  }

  async archiveMemories(memoryIds: string[], summaryId: string): Promise<number> {
    const memories = await this.readAllMemories();
    const memoryMap = new Map(memories.map((m) => [m.frontmatter.id, m]));
    let archived = 0;

    for (const id of memoryIds) {
      const memory = memoryMap.get(id);
      if (!memory) continue;

      const now = new Date().toISOString();
      let currentBefore = memory;
      let updatedFm = memory.frontmatter;

      try {
        const written = await this.withTombstoneBlockedMemoryPathLock(memory.path, async (current) => {
          if (current?.frontmatter.id !== id) return false;
          currentBefore = current;
          const rowIds = this.currentHistoricalIds();
          updatedFm = entityRefs.canonicalizeEntityRefOption(
            { ...current.frontmatter, status: "archived", archivedAt: now, updated: now },
            rowIds
          );
          const fileContent = `${serializeFrontmatter(this.withOkfType(updatedFm))}\n\n${current.content}\n`;
          await this.writeTombstoneBlockedFrontmatter(current, fileContent, updatedFm);
          if (typeof current.frontmatter.entityRef === "string") {
            await this.entityRefRepair.repair(
              current.path,
              updatedFm,
              current.frontmatter.entityRef,
              rowIds,
              current.content,
              { onFailRestore: current }
            );
          }
          return true;
        });
        if (!written) continue;
        // Corpus bump before the lifecycle append (#1902). Epoch moves only if repair changed entityRef or origin.
        this.bumpMemoryCorpusVersion({ indexedText: entityMentionEpoch.neutral(currentBefore.frontmatter, updatedFm) ? false : undefined });
        await this.appendGeneratedMemoryLifecycleEventFailOpen("storage.archiveMemories", {
          memoryId: id,
          eventType: "archived",
          timestamp: updatedFm.archivedAt ?? updatedFm.updated,
          actor: "storage.archiveMemories",
          reasonCode: `summary:${summaryId}`,
          before: this.summarizeLifecycleState(currentBefore.frontmatter, currentBefore.path),
          after: this.summarizeLifecycleState(updatedFm, currentBefore.path),
          relatedMemoryIds: [summaryId],
        });
        archived++;
      } catch {
        // Ignore individual failures
      }
    }

    if (archived > 0) {
      this.bumpMemoryStatusVersion();
      log.debug(`archived ${archived} memories for summary ${summaryId}`);
    }
    return archived;
  }

  async saveTopics(topics: TopicScore[]): Promise<void> {
    const metaPath = path.join(this.stateDir, "topics.json");
    await mkdir(this.stateDir, { recursive: true });
    await this.writeStorageSecureFile(metaPath, JSON.stringify({ topics, updatedAt: new Date().toISOString() }, null, 2));
    log.debug(`saved ${topics.length} topic scores`);
  }

  async loadTopics(): Promise<{ topics: TopicScore[]; updatedAt: string | null }> {
    const metaPath = path.join(this.stateDir, "topics.json");
    try {
      const raw = await this.readStorageSecureFile(metaPath);
      return JSON.parse(raw) as { topics: TopicScore[]; updatedAt: string | null };
    } catch (err) {
      if (err instanceof SecureStoreLockedError) throw err;
      if (!isErrnoCode(err, "ENOENT")) throw err;
      return { topics: [], updatedAt: null };
    }
  }

  async addLinksToMemory(
    memoryId: string,
    links: MemoryLink[],
    lifecycle?: MemoryLifecycleEventWriteOptions
  ): Promise<boolean> {
    const memories = await this.readAllMemories();
    const memory = memories.find((m) => m.frontmatter.id === memoryId);
    if (!memory) return false;

    const existingLinks = memory.frontmatter.links ?? [];
    const mergedLinks = [...existingLinks];

    for (const link of links) {
      if (!mergedLinks.some((l) => l.targetId === link.targetId && l.linkType === link.linkType)) {
        mergedLinks.push(link);
      }
    }

    try {
      await this.writeMemoryFrontmatter(
        memory,
        {
          links: mergedLinks,
          updated: new Date().toISOString(),
        },
        lifecycle
      );
      log.debug(`added ${links.length} links to memory ${memoryId}`);
      return true;
    } catch (err) {
      log.error(`failed to add links to memory ${memoryId}:`, err);
      return false;
    }
  }

  private summarizeLifecycleState(frontmatter: MemoryFrontmatter, filePath: string): MemoryLifecycleStateSummary {
    return {
      category: frontmatter.category,
      path: filePath,
      status: frontmatter.status ?? "active",
      lifecycleState: frontmatter.lifecycleState,
    };
  }

  private frontmatterPatchEventType(before: MemoryFrontmatter, after: MemoryFrontmatter): MemoryLifecycleEventType {
    const beforeStatus = before.status ?? "active";
    const afterStatus = after.status ?? "active";
    if (beforeStatus !== "archived" && afterStatus === "archived") return "archived";
    if (beforeStatus !== "superseded" && afterStatus === "superseded") return "superseded";
    if (beforeStatus !== "rejected" && afterStatus === "rejected") return "rejected";
    if (beforeStatus !== "active" && afterStatus === "active") {
      return "restored";
    }
    return "updated";
  }

  private async appendGeneratedMemoryLifecycleEvent(
    input: Omit<MemoryLifecycleEvent, "eventId" | "ruleVersion">,
    ruleVersion = "memory-lifecycle-ledger.v1"
  ): Promise<void> {
    await this.appendMemoryLifecycleEvents([
      {
        ...input,
        eventId: this.generateId("mle"),
        ruleVersion,
      },
    ]);
  }

  private async appendGeneratedMemoryLifecycleEventFailOpen(
    operation: string,
    input: Omit<MemoryLifecycleEvent, "eventId" | "ruleVersion">,
    ruleVersion?: string
  ): Promise<void> {
    try {
      await this.appendGeneratedMemoryLifecycleEvent(input, ruleVersion);
    } catch (appendErr) {
      log.warn(`${operation} completed but failed to append lifecycle event: ${appendErr}`);
    }
  }
}

/**
 * Conversation Threading (Phase 3B)
 *
 * Groups related memories into conversation threads with auto-generated titles.
 * Thread boundary detection: new session key OR time gap > threshold.
 */

import { readdir, readFile, writeFile, mkdir, stat } from "node:fs/promises";
import { log } from "./logger.js";
import type { BufferTurn, ConversationThread } from "./types.js";
import {
  encodeStoragePathSegment,
  encodeStoragePathSegmentWithHash,
  isSafeLegacyPathSegment,
  resolveSafeStoragePath,
} from "./storage-paths.js";

/** Stop words for title extraction */
const STOP_WORDS = new Set([
  "a", "an", "the", "is", "are", "was", "were", "be", "been", "being",
  "have", "has", "had", "do", "does", "did", "will", "would", "could",
  "should", "may", "might", "must", "shall", "can", "need", "to", "of",
  "in", "for", "on", "with", "at", "by", "from", "as", "into", "through",
  "during", "before", "after", "above", "below", "between", "this", "that",
  "these", "those", "i", "me", "my", "we", "our", "you", "your", "he",
  "she", "it", "they", "them", "their", "what", "which", "who", "how",
  "when", "where", "why", "and", "but", "or", "if", "because", "so",
  "just", "about", "like", "also", "very", "really", "here", "there",
]);

/**
 * Extract top keywords from content for thread title.
 * Simple TF approach (no IDF needed for single thread).
 */
function extractKeywords(content: string, maxKeywords: number = 3): string[] {
  const words = content
    .toLowerCase()
    .replace(/[^a-z0-9\s-]/g, " ")
    .split(/\s+/)
    .filter((w) => w.length >= 4 && !STOP_WORDS.has(w));

  // Count frequencies
  const freq = new Map<string, number>();
  for (const word of words) {
    freq.set(word, (freq.get(word) ?? 0) + 1);
  }

  // Sort by frequency, take top N
  return [...freq.entries()]
    .sort((a, b) => b[1] - a[1])
    .slice(0, maxKeywords)
    .map(([word]) => word);
}

/**
 * Generate a thread title from keywords.
 */
function generateTitle(keywords: string[]): string {
  if (keywords.length === 0) return "Untitled Thread";
  // Capitalize and join
  return keywords
    .map((k) => k.charAt(0).toUpperCase() + k.slice(1))
    .join(", ");
}

function isConversationThread(value: unknown): value is ConversationThread {
  if (value === null || typeof value !== "object") return false;
  const candidate = value as Partial<ConversationThread>;
  return (
    typeof candidate.id === "string" &&
    typeof candidate.title === "string" &&
    typeof candidate.createdAt === "string" &&
    typeof candidate.updatedAt === "string" &&
    Array.isArray(candidate.episodeIds) &&
    Array.isArray(candidate.linkedThreadIds)
  );
}

function parseConversationThread(raw: string): ConversationThread | null {
  try {
    const parsed = JSON.parse(raw) as unknown;
    return isConversationThread(parsed) ? parsed : null;
  } catch {
    return null;
  }
}

/** One session's thread-run state: its current thread and last turn time. */
interface ThreadingRunState {
  currentThreadId: string | null;
  lastTurnTimestamp: number | null;
}

export class ThreadingManager {
  /**
   * Per-session thread-run state. One global slot let two concurrent
   * extractions (bounded-parallel queue) interleave sessions and attach
   * turns to the wrong thread, so the run state is keyed by session.
   * Bounded: a long-lived daemon sees one entry per active session.
   */
  private readonly runStateBySession = new Map<string, ThreadingRunState>();
  /**
   * Run states with a processTurn awaiting inside them. A session parked on
   * `saveThread` can watch 512 other sessions insert and evict; dropping its
   * state mid-await loses its thread id and forks its thread, so eviction
   * never takes an in-flight state (the cap may be exceeded briefly by the
   * number of in-flight extractions, which is bounded by the queue).
   */
  private readonly inFlightRunStates = new Set<ThreadingRunState>();
  private static readonly RUN_STATE_MAX_SESSIONS = 512;

  private runStateFor(turn: BufferTurn): ThreadingRunState {
    const key = turn.sessionKey ?? "";
    let state = this.runStateBySession.get(key);
    if (state) {
      // Refresh recency: Map iteration is insertion-ordered, so re-putting a
      // touched session makes eviction true LRU instead of first-in-first-out —
      // an active session must not be the oldest entry just because it started
      // first.
      this.runStateBySession.delete(key);
      this.runStateBySession.set(key, state);
    } else {
      state = { currentThreadId: null, lastTurnTimestamp: null };
      this.runStateBySession.set(key, state);
      if (this.runStateBySession.size > ThreadingManager.RUN_STATE_MAX_SESSIONS) {
        for (const [oldestKey, oldest] of this.runStateBySession) {
          // Never evict the state being inserted: before the caller registers
          // it in-flight, every older entry can be in flight and the loop
          // would otherwise delete this turn's own state and fork the thread.
          if (oldest === state || this.inFlightRunStates.has(oldest)) continue;
          this.runStateBySession.delete(oldestKey);
          if (this.runStateBySession.size <= ThreadingManager.RUN_STATE_MAX_SESSIONS) break;
        }
      }
    }
    return state;
  }

  constructor(
    private readonly threadsDir: string,
    private readonly gapMinutes: number = 30,
  ) {}

  async ensureDirectory(): Promise<void> {
    await mkdir(this.threadsDir, { recursive: true });
  }

  private encodedThreadFileName(threadId: string): string {
    return `${encodeStoragePathSegment(threadId)}.json`;
  }

  private collisionSafeThreadFileName(threadId: string): string {
    return `${encodeStoragePathSegmentWithHash(threadId)}.json`;
  }

  private legacyThreadFileName(threadId: string): string | undefined {
    if (!isSafeLegacyPathSegment(threadId)) return undefined;
    const legacyFile = `${threadId}.json`;
    return legacyFile === this.encodedThreadFileName(threadId) ? undefined : legacyFile;
  }

  private async threadCandidateStatus(
    filePath: string,
    threadId: string,
  ): Promise<"missing" | "matches" | "invalid" | "mismatches"> {
    try {
      if (!(await stat(filePath)).isFile()) return "mismatches";
      const thread = parseConversationThread(await readFile(filePath, "utf-8"));
      if (!thread) return "invalid";
      return thread.id === threadId ? "matches" : "mismatches";
    } catch (err) {
      const code =
        err && typeof err === "object" && "code" in err
          ? (err as { code?: string }).code
          : undefined;
      if (code === "ENOENT") return "missing";
      throw err;
    }
  }

  private async threadFilePathForWrite(threadId: string): Promise<string> {
    const encodedPath = await resolveSafeStoragePath(
      this.threadsDir,
      this.encodedThreadFileName(threadId),
    );
    const encodedStatus = await this.threadCandidateStatus(encodedPath, threadId);
    if (encodedStatus === "matches") return encodedPath;

    const legacyFile = this.legacyThreadFileName(threadId);
    if (legacyFile) {
      const legacyPath = await resolveSafeStoragePath(this.threadsDir, legacyFile);
      if ((await this.threadCandidateStatus(legacyPath, threadId)) === "matches") {
        return legacyPath;
      }
    }

    if (encodedStatus === "missing") return encodedPath;

    const collisionSafePath = await resolveSafeStoragePath(
      this.threadsDir,
      this.collisionSafeThreadFileName(threadId),
    );
    const collisionSafeStatus = await this.threadCandidateStatus(collisionSafePath, threadId);
    if (collisionSafeStatus === "mismatches") {
      throw new Error(`thread storage path collision for thread id: ${threadId}`);
    }

    return collisionSafePath;
  }

  /**
   * Check if we should start a new thread based on session key and time gap.
   * State is per session, so the cross-session check the shared slot needed
   * is gone: different sessions never share run state at all.
   */
  shouldStartNewThread(turn: BufferTurn): boolean {
    const turnTime = new Date(turn.timestamp).getTime();
    const state = this.runStateFor(turn);

    // Time gap > threshold = new thread
    if (state.lastTurnTimestamp) {
      const gapMs = turnTime - state.lastTurnTimestamp;
      const gapMinutes = gapMs / (1000 * 60);
      if (gapMinutes > this.gapMinutes) {
        return true;
      }
    }

    // No current thread = new thread
    if (!state.currentThreadId) {
      return true;
    }

    return false;
  }

  /**
   * Process a turn and return the thread ID it belongs to.
   * Creates a new thread if needed.
   */
  async processTurn(turn: BufferTurn, episodeIds: string[]): Promise<string> {
    await this.ensureDirectory();

    const turnTime = new Date(turn.timestamp).getTime();
    const state = this.runStateFor(turn);
    this.inFlightRunStates.add(state);
    try {
      if (this.shouldStartNewThread(turn)) {
        // Create new thread
        const threadId = `thread-${Date.now()}-${Math.random().toString(36).slice(2, 6)}`;
        const thread: ConversationThread = {
          id: threadId,
          title: "New Thread", // Will be updated later with keywords
          createdAt: turn.timestamp,
          updatedAt: turn.timestamp,
          sessionKey: turn.sessionKey,
          episodeIds: [...episodeIds],
          linkedThreadIds: [],
        };

        await this.saveThread(thread);
        state.currentThreadId = threadId;
        log.debug(`created new thread ${threadId}`);
      } else if (state.currentThreadId) {
        // Add episodes to current thread
        const thread = await this.loadThread(state.currentThreadId);
        if (thread) {
          for (const id of episodeIds) {
            if (!thread.episodeIds.includes(id)) {
              thread.episodeIds.push(id);
            }
          }
          thread.updatedAt = turn.timestamp;
          await this.saveThread(thread);
        }
      }

      state.lastTurnTimestamp = turnTime;

      return state.currentThreadId!;
    } finally {
      this.inFlightRunStates.delete(state);
    }
  }

  /**
   * Append persisted memory IDs to an existing thread.
   * Keeps IDs unique and updates the thread timestamp.
   */
  async appendEpisodeIds(threadId: string, episodeIds: string[]): Promise<void> {
    if (episodeIds.length === 0) return;
    const thread = await this.loadThread(threadId);
    if (!thread) return;

    let changed = false;
    for (const id of episodeIds) {
      if (!thread.episodeIds.includes(id)) {
        thread.episodeIds.push(id);
        changed = true;
      }
    }
    if (!changed) return;

    thread.updatedAt = new Date().toISOString();
    await this.saveThread(thread);
  }

  /**
   * Update thread title based on accumulated content.
   */
  async updateThreadTitle(threadId: string, content: string): Promise<void> {
    const thread = await this.loadThread(threadId);
    if (!thread) return;

    const keywords = extractKeywords(content);
    const title = generateTitle(keywords);

    if (title !== thread.title) {
      thread.title = title;
      thread.updatedAt = new Date().toISOString();
      await this.saveThread(thread);
      log.debug(`updated thread ${threadId} title: ${title}`);
    }
  }

  /**
   * Get all threads, sorted by updatedAt desc.
   */
  async getAllThreads(): Promise<ConversationThread[]> {
    try {
      const files = await readdir(this.threadsDir);
      const threadsById = new Map<
        string,
        { thread: ConversationThread; storagePriority: number }
      >();

      for (const file of files) {
        if (!file.endsWith(".json")) continue;
        try {
          const raw = await readFile(
            await resolveSafeStoragePath(this.threadsDir, file),
            "utf-8",
          );
          const thread = parseConversationThread(raw);
          if (!thread) continue;

          const legacyFile = this.legacyThreadFileName(thread.id);
          const storagePriority =
            file === this.encodedThreadFileName(thread.id)
              ? 3
              : file === this.collisionSafeThreadFileName(thread.id)
                ? 2
                : legacyFile && file === legacyFile
                  ? 1
                  : 0;
          const current = threadsById.get(thread.id);
          if (!current || storagePriority > current.storagePriority) {
            threadsById.set(thread.id, { thread, storagePriority });
          }
        } catch {
          // skip unreadable or malformed thread files
        }
      }

      return [...threadsById.values()].map(({ thread }) => thread).sort(
        (a, b) => new Date(b.updatedAt).getTime() - new Date(a.updatedAt).getTime(),
      );
    } catch {
      return [];
    }
  }

  /**
   * Get a thread by ID.
   */
  async loadThread(threadId: string): Promise<ConversationThread | null> {
    const candidates = [
      this.encodedThreadFileName(threadId),
      this.legacyThreadFileName(threadId),
      this.collisionSafeThreadFileName(threadId),
    ];
    for (const file of candidates) {
      if (!file) continue;
      try {
        const filePath = await resolveSafeStoragePath(this.threadsDir, file);
        const raw = await readFile(filePath, "utf-8");
        const thread = parseConversationThread(raw);
        if (thread?.id === threadId) return thread;
      } catch {
        // try the next candidate
      }
    }
    return null;
  }

  /**
   * Save a thread.
   */
  async saveThread(thread: ConversationThread): Promise<void> {
    await this.ensureDirectory();
    const filePath = await this.threadFilePathForWrite(thread.id);
    await writeFile(filePath, JSON.stringify(thread, null, 2), "utf-8");
  }

  /**
   * Link two threads together.
   */
  async linkThreads(threadId1: string, threadId2: string): Promise<boolean> {
    const thread1 = await this.loadThread(threadId1);
    const thread2 = await this.loadThread(threadId2);

    if (!thread1 || !thread2) return false;

    // Add bidirectional links
    if (!thread1.linkedThreadIds.includes(threadId2)) {
      thread1.linkedThreadIds.push(threadId2);
      await this.saveThread(thread1);
    }

    if (!thread2.linkedThreadIds.includes(threadId1)) {
      thread2.linkedThreadIds.push(threadId1);
      await this.saveThread(thread2);
    }

    return true;
  }

  /**
   * Get the current thread ID (if any). With per-session run state there is
   * no single current thread; null unless exactly one session is tracked.
   */
  getCurrentThreadId(): string | null {
    if (this.runStateBySession.size === 1) {
      return this.runStateBySession.values().next().value?.currentThreadId ?? null;
    }
    return null;
  }

  /**
   * Reset threading state (e.g., on plugin restart).
   */
  reset(): void {
    this.runStateBySession.clear();
  }
}

import { appendFile, mkdir, readdir, readFile, stat, unlink, writeFile } from "node:fs/promises";
import path from "node:path";
import { log } from "./logger.js";
import type { TranscriptEntry, Checkpoint, PluginConfig } from "./types.js";
import { analyzeSessionIntegrity, type SessionIntegrityReport } from "./session-integrity.js";
import { isDailyFileDatedBefore, resolveSafeStoragePath } from "./storage-paths.js";
import { sessionStoragePaths } from "./session-identity.js";
import { estimateTokenCount } from "./token-estimate.js";
import { isMacOsReplicationJunkBasename } from "./utils/macos-replication-junk.js";

type DirectorySessionStatus = "missing" | "empty" | "matches" | "occupied";
type DirectoryOwnershipCacheEntry = {
  status: "empty" | "matches";
  fileSizes: Map<string, number>;
};

/**
 * De-duplicate JSONL lines collected across multiple read-back candidate
 * directories. A partially-applied migration (issue #1496) can leave the SAME
 * raw row in both the primary `session/<hash>` tree and a legacy read-back dir
 * (`other/default` or an old `parts.length >= 3` directory) when the source was
 * copied but not yet trimmed. Without this guard, `readRecent`, `readToolUse`,
 * footprint estimation, and the summarizer fetch would return that row twice
 * (cursor review on PR #1504). The exact raw JSONL line is the stable identity:
 * the migration preserves byte content per session, so a copied-but-not-trimmed
 * row is byte-identical in both locations. Returns `true` the first time a line
 * is seen, `false` for every subsequent duplicate.
 */
function makeRawLineDeduper(): (rawLine: string) => boolean {
  const seen = new Set<string>();
  return (rawLine: string): boolean => {
    if (seen.has(rawLine)) return false;
    seen.add(rawLine);
    return true;
  };
}

/**
 * Compute the half-open UTC instant range `[start, end)` that covers an entire
 * calendar day, suitable for {@link TranscriptManager.readRange}.
 *
 * `readRange` filters with an EXCLUSIVE upper bound (`entryTime < end`, CLAUDE.md
 * rule #35 / AGENTS.md rule 23). The end is therefore the NEXT day's
 * `00:00:00Z`, not `${date}T23:59:59Z`: a literal `23:59:59Z` end (== `.000Z`)
 * would drop any entry stamped in the final second of the day
 * (`23:59:59.000Z`–`23:59:59.999Z`). Using the next day's midnight keeps the
 * `[start, end)` semantics intact while including the whole day.
 *
 * @param date - A `YYYY-MM-DD` calendar day (UTC).
 */
export function utcDayRange(date: string): { start: string; end: string } {
  const start = `${date}T00:00:00Z`;
  const startMs = Date.parse(start);
  if (Number.isNaN(startMs)) {
    // Malformed date: preserve the pre-existing "empty range" behavior (an
    // unparseable bound makes `readRange` match nothing) rather than throwing.
    return { start, end: start };
  }
  const next = new Date(startMs);
  next.setUTCDate(next.getUTCDate() + 1);
  return { start, end: `${next.toISOString().slice(0, 10)}T00:00:00Z` };
}

/**
 * Manages conversation transcript storage, checkpointing, and recall formatting.
 *
 * Transcripts are stored as JSONL files in a hierarchical structure:
 *   transcripts/{channelType}/{channelId}.jsonl
 *
 * Channel types are extracted from sessionKey (discord, slack, cron, main, etc.)
 * Checkpoints are used to preserve conversation context across compaction events.
 */
export class TranscriptManager {
  private transcriptsDir: string;
  private checkpointPath: string;
  private stateDir: string;
  private toolUsageDir: string;
  private config: PluginConfig;
  private sessionFootprintCache = new Map<
    string,
    {
      totalBytes: number;
      totalTokens: number;
      fileBytes: Map<string, number>;
      fileSizes: Map<string, number>;
      fileTokens: Map<string, number>;
    }
  >();
  private directoryOwnershipCache = new Map<string, DirectoryOwnershipCacheEntry>();

  /** Default checkpoint TTL in hours */
  private static readonly DEFAULT_CHECKPOINT_TTL_HOURS = 24;

  constructor(config: PluginConfig) {
    this.config = config;
    this.transcriptsDir = path.join(config.memoryDir, "transcripts");
    this.stateDir = path.join(config.memoryDir, "state");
    this.checkpointPath = path.join(this.stateDir, "checkpoint.json");
    this.toolUsageDir = path.join(this.stateDir, "tool-usage");
  }

  /**
   * Resolve the storage path pieces for a sessionKey via the shared
   * {@link sessionStoragePaths} helper (issue #1496, rule #22).
   *
   * Legacy `agent:<id>:...` shapes keep their existing readable channel paths.
   * Arbitrary / non-legacy keys (e.g. `pi-geek:abc123`) route to
   * `transcripts/session/<hash>/YYYY-MM-DD.jsonl` from the FIRST write — they
   * never start life in `other/default`. For those keys a list of
   * read-back-only `readbackDirs` is returned so data written by older builds
   * (under `other/default`, or under an old `parts.length >= 3` directory such
   * as `baz/default`) stays discoverable until migrated. New writes never
   * target read-back dirs. See `session-identity.ts`.
   *
   * @returns Object with raw channel identifiers and encoded storage path pieces.
   */
  getTranscriptPath(sessionKey: string): {
    dir: string;
    file: string;
    channelType: string;
    channelId: string;
    alternateDir: string;
    legacyDir?: string;
    readbackDirs: string[];
  } {
    const paths = sessionStoragePaths(sessionKey);

    // Daily rotation: transcripts/{channelType}/{channelId}/YYYY-MM-DD.jsonl
    const today = new Date().toISOString().slice(0, 10);

    return {
      dir: paths.dir,
      file: `${today}.jsonl`,
      channelType: paths.channelType,
      channelId: paths.channelId,
      alternateDir: paths.alternateDir,
      legacyDir: paths.legacyDir,
      readbackDirs: paths.readbackDirs,
    };
  }

  /**
   * Initialize the transcript manager by ensuring directories exist.
   */
  async initialize(): Promise<void> {
    await mkdir(this.transcriptsDir, { recursive: true });
    await mkdir(this.stateDir, { recursive: true });
    await mkdir(this.toolUsageDir, { recursive: true });
    log.info("transcript manager initialized");
  }

  /**
   * Best-effort list of sessionKeys that have transcript files on disk.
   * This is used by cron-style tooling (hourly summaries, conversation indexing)
   * to iterate across "active" sessions.
   */
  async listSessionKeys(): Promise<string[]> {
    const transcriptDir = this.transcriptsDir;
    const sessionKeys = new Set<string>();

    try {
      const typeEntries = await readdir(transcriptDir, { withFileTypes: true });
      for (const typeEnt of typeEntries) {
        if (!typeEnt.isDirectory()) continue;
        const typeDir = path.join(transcriptDir, typeEnt.name);
        const idEntries = await readdir(typeDir, { withFileTypes: true });
        for (const idEnt of idEntries) {
          if (!idEnt.isDirectory()) continue;
          const chanDir = path.join(typeDir, idEnt.name);
          const files = (await readdir(chanDir)).filter((f) => f.endsWith(".jsonl") && !isMacOsReplicationJunkBasename(f)).sort();
          const last = files[files.length - 1];
          if (!last) continue;
          try {
            const raw = await readFile(path.join(chanDir, last), "utf-8");
            const firstLine = raw.split("\n").find((l) => l.trim().length > 0);
            if (!firstLine) continue;
            const entry = JSON.parse(firstLine) as TranscriptEntry;
            if (typeof entry.sessionKey === "string" && entry.sessionKey.length > 0) {
              sessionKeys.add(entry.sessionKey);
            }
          } catch {
            // ignore
          }
        }
      }
    } catch {
      return [];
    }

    return Array.from(sessionKeys);
  }

  getToolUsagePath(sessionKey: string): {
    dir: string;
    file: string;
    alternateDir: string;
    legacyDir?: string;
    readbackDirs: string[];
  } {
    const p = this.getTranscriptPath(sessionKey);
    return {
      dir: p.dir,
      file: p.file,
      alternateDir: p.alternateDir,
      legacyDir: p.legacyDir,
      readbackDirs: p.readbackDirs,
    };
  }

  private async selectStorageDirForWrite(
    root: string,
    dir: string,
    legacyDir?: string,
    sessionKey?: string,
    alternateDir?: string,
  ): Promise<{ dir: string; channelDir: string }> {
    const channelDir = await resolveSafeStoragePath(root, dir);
    const encodedStatus = await this.directorySessionStatus(root, dir, sessionKey);
    if (encodedStatus === "matches" || encodedStatus === "empty") return { dir, channelDir };

    if (legacyDir) {
      const legacyChannelDir = await resolveSafeStoragePath(root, legacyDir);
      if ((await this.directorySessionStatus(root, legacyDir, sessionKey)) === "matches") {
        return { dir: legacyDir, channelDir: legacyChannelDir };
      }
    }

    if (encodedStatus === "missing") return { dir, channelDir };

    if (alternateDir) {
      const alternateChannelDir = await resolveSafeStoragePath(root, alternateDir);
      const alternateStatus = await this.directorySessionStatus(root, alternateDir, sessionKey);
      if (
        alternateStatus === "missing" ||
        alternateStatus === "empty" ||
        alternateStatus === "matches"
      ) {
        return { dir: alternateDir, channelDir: alternateChannelDir };
      }
    }

    throw new Error(`transcript storage path collision for session: ${sessionKey ?? "(unknown)"}`);
  }

  private async directorySessionStatus(
    root: string,
    dir: string,
    sessionKey?: string,
  ): Promise<DirectorySessionStatus> {
    let channelDir: string;
    try {
      channelDir = await resolveSafeStoragePath(root, dir);
      if (!(await stat(channelDir)).isDirectory()) return "occupied";
    } catch (err) {
      const code =
        err && typeof err === "object" && "code" in err
          ? (err as { code?: string }).code
          : undefined;
      if (code === "ENOENT") return "missing";
      throw err;
    }

    let names: string[];
    try {
      names = (await readdir(channelDir)).filter((file) => file.endsWith(".jsonl") && !isMacOsReplicationJunkBasename(file));
    } catch {
      return "occupied";
    }

    const fileSizes = await this.directoryJsonlFileSizes(root, dir, names);
    if (!fileSizes) return "occupied";

    if (!sessionKey) return "matches";
    const cacheKey = this.directoryOwnershipCacheKey(root, dir, sessionKey);
    const cached = this.directoryOwnershipCache.get(cacheKey);
    if (cached && this.sameFileSizes(cached.fileSizes, fileSizes)) {
      return cached.status;
    }

    let hasEntries = false;
    let hasMatchingEntry = false;

    for (const name of names) {
      const filePath = await resolveSafeStoragePath(root, dir, name).catch(() => null);
      if (filePath === null) return "occupied";
      try {
        const raw = await readFile(filePath, "utf-8");
        for (const line of raw.split("\n")) {
          if (!line.trim()) continue;
          hasEntries = true;
          try {
            const obj = JSON.parse(line) as { sessionKey?: string };
            if (obj.sessionKey === sessionKey) {
              hasMatchingEntry = true;
            } else {
              return "occupied";
            }
          } catch {
            return "occupied";
          }
        }
      } catch {
        return "occupied";
      }
    }

    const status = hasMatchingEntry ? "matches" : hasEntries ? "occupied" : "empty";
    if (status === "matches" || status === "empty") {
      this.directoryOwnershipCache.set(cacheKey, { status, fileSizes });
    }
    return status;
  }

  private directoryOwnershipCacheKey(root: string, dir: string, sessionKey: string): string {
    return `${path.resolve(root)}\0${dir}\0${sessionKey}`;
  }

  private sameFileSizes(left: Map<string, number>, right: Map<string, number>): boolean {
    if (left.size !== right.size) return false;
    for (const [name, size] of left) {
      if (right.get(name) !== size) return false;
    }
    return true;
  }

  private async directoryJsonlFileSizes(
    root: string,
    dir: string,
    names: string[],
  ): Promise<Map<string, number> | null> {
    const fileSizes = new Map<string, number>();
    for (const name of names) {
      const filePath = await resolveSafeStoragePath(root, dir, name).catch(() => null);
      if (filePath === null) return null;
      const fileInfo = await stat(filePath).catch(() => null);
      if (!fileInfo?.isFile()) return null;
      fileSizes.set(name, Math.max(0, fileInfo.size));
    }
    return fileSizes;
  }

  private async rememberDirectoryOwnership(
    root: string,
    dir: string,
    sessionKey: string,
  ): Promise<void> {
    try {
      const channelDir = await resolveSafeStoragePath(root, dir);
      const names = (await readdir(channelDir)).filter((file) => file.endsWith(".jsonl") && !isMacOsReplicationJunkBasename(file));
      const fileSizes = await this.directoryJsonlFileSizes(root, dir, names);
      if (!fileSizes) return;
      this.directoryOwnershipCache.set(
        this.directoryOwnershipCacheKey(root, dir, sessionKey),
        { status: "matches", fileSizes },
      );
    } catch {
      // Cache refresh is best-effort; write path correctness does not depend on it.
    }
  }

  private async getSessionStorageFiles(
    root: string,
    dir: string,
    legacyDir?: string,
    alternateDir?: string,
    readbackDirs: string[] = [],
  ): Promise<Array<{ cacheKey: string; name: string; path: string }>> {
    const files: Array<{ cacheKey: string; name: string; path: string }> = [];
    const seenDirs = new Set<string>();

    for (const candidateDir of [dir, alternateDir, legacyDir, ...readbackDirs]) {
      if (!candidateDir || seenDirs.has(candidateDir)) continue;
      seenDirs.add(candidateDir);

      let channelDir: string;
      try {
        channelDir = await resolveSafeStoragePath(root, candidateDir);
      } catch {
        continue;
      }

      let names: string[];
      try {
        names = (await readdir(channelDir)).filter((file) => file.endsWith(".jsonl") && !isMacOsReplicationJunkBasename(file)).sort();
      } catch {
        continue;
      }

      for (const name of names) {
        const filePath = await resolveSafeStoragePath(root, candidateDir, name).catch(() => null);
        if (filePath === null) continue;
        files.push({
          cacheKey: path.join(candidateDir, name),
          name,
          path: filePath,
        });
      }
    }

    return files.sort((a, b) => a.cacheKey.localeCompare(b.cacheKey));
  }

  async appendToolUse(entry: { timestamp: string; sessionKey: string; tool: string }): Promise<void> {
    const { dir, file, alternateDir, legacyDir } = this.getToolUsagePath(entry.sessionKey);
    const { dir: writeDir, channelDir } = await this.selectStorageDirForWrite(
      this.toolUsageDir,
      dir,
      legacyDir,
      entry.sessionKey,
      alternateDir,
    );
    await mkdir(channelDir, { recursive: true });
    const filePath = await resolveSafeStoragePath(this.toolUsageDir, writeDir, file);
    await appendFile(filePath, JSON.stringify(entry) + "\n", "utf-8");
    await this.rememberDirectoryOwnership(this.toolUsageDir, writeDir, entry.sessionKey);
  }

  async readToolUse(
    sessionKey: string,
    startTime: Date,
    endTime: Date,
  ): Promise<Array<{ timestamp: string; sessionKey: string; tool: string }>> {
    const { dir, alternateDir, legacyDir, readbackDirs } = this.getToolUsagePath(sessionKey);
    try {
      const files = await this.getSessionStorageFiles(
        this.toolUsageDir,
        dir,
        legacyDir,
        alternateDir,
        readbackDirs,
      );
      const out: Array<{ timestamp: string; sessionKey: string; tool: string }> = [];
      // Dedup identical raw rows that a partially-applied migration may have left
      // in both the primary dir and a read-back dir (issue #1496, cursor review).
      const keepRawLine = makeRawLineDeduper();
      for (const file of files) {
        const raw = await readFile(file.path, "utf-8");
        for (const line of raw.split("\n")) {
          if (!line.trim()) continue;
          try {
            const obj = JSON.parse(line) as any;
            const ts = new Date(String(obj.timestamp ?? "")).getTime();
            if (!Number.isFinite(ts)) continue;
            if (ts >= startTime.getTime() && ts < endTime.getTime()) {
              if (typeof obj.tool === "string" && typeof obj.sessionKey === "string") {
                if (obj.sessionKey === sessionKey && keepRawLine(line)) {
                  out.push({ timestamp: obj.timestamp, sessionKey: obj.sessionKey, tool: obj.tool });
                }
              }
            }
          } catch {
            // ignore
          }
        }
      }
      return out;
    } catch {
      return [];
    }
  }

  async estimateSessionFootprint(sessionKey: string): Promise<{ bytes: number; tokens: number }> {
    const { dir, alternateDir, legacyDir, readbackDirs } = this.getTranscriptPath(sessionKey);
    let bytes = 0;
    let tokens = 0;
    try {
      const files = await this.getSessionStorageFiles(
        this.transcriptsDir,
        dir,
        legacyDir,
        alternateDir,
        readbackDirs,
      );
      const cached = this.sessionFootprintCache.get(sessionKey);
      if (!cached) {
        const fileBytes = new Map<string, number>();
        const fileSizes = new Map<string, number>();
        const fileTokens = new Map<string, number>();
        for (const file of files) {
          try {
            const fileInfo = await stat(file.path);
            const estimate = await this.estimateSessionBytesInFile(file.path, sessionKey);
            fileBytes.set(file.cacheKey, estimate.bytes);
            fileTokens.set(file.cacheKey, estimate.tokens);
            fileSizes.set(file.cacheKey, Math.max(0, fileInfo.size));
            bytes += estimate.bytes;
            tokens += estimate.tokens;
          } catch {
          }
        }
        this.sessionFootprintCache.set(sessionKey, { totalBytes: bytes, totalTokens: tokens, fileBytes, fileSizes, fileTokens });
      } else {
        bytes = cached.totalBytes;
        tokens = cached.totalTokens;
        const seen = new Set(files.map((file) => file.cacheKey));

        for (const [cachedFile, cachedSessionBytes] of cached.fileBytes.entries()) {
          if (!seen.has(cachedFile)) {
            bytes -= cachedSessionBytes;
            tokens -= cached.fileTokens.get(cachedFile) ?? 0;
            cached.fileBytes.delete(cachedFile);
            cached.fileTokens.delete(cachedFile);
            cached.fileSizes.delete(cachedFile);
          }
        }

        for (const file of files) {
          if (cached.fileBytes.has(file.cacheKey)) continue;
          try {
            const fileInfo = await stat(file.path);
            const estimate = await this.estimateSessionBytesInFile(file.path, sessionKey);
            cached.fileBytes.set(file.cacheKey, estimate.bytes);
            cached.fileTokens.set(file.cacheKey, estimate.tokens);
            cached.fileSizes.set(file.cacheKey, Math.max(0, fileInfo.size));
            bytes += estimate.bytes;
            tokens += estimate.tokens;
          } catch {
          }
        }

        for (const file of files) {
          try {
            const fileInfo = await stat(file.path);
            const size = Math.max(0, fileInfo.size);
            const previousEstimate = {
              bytes: cached.fileBytes.get(file.cacheKey) ?? 0,
              tokens: cached.fileTokens.get(file.cacheKey) ?? 0,
            };
            const previousSize = cached.fileSizes.get(file.cacheKey) ?? -1;
            if (size !== previousSize) {
              const estimate = await this.estimateSessionBytesInFile(file.path, sessionKey);
              cached.fileBytes.set(file.cacheKey, estimate.bytes);
              cached.fileTokens.set(file.cacheKey, estimate.tokens);
              cached.fileSizes.set(file.cacheKey, size);
              bytes += estimate.bytes - previousEstimate.bytes;
              tokens += estimate.tokens - previousEstimate.tokens;
            }
          } catch {
          }
        }

        bytes = Math.max(0, bytes);
        tokens = Math.max(0, tokens);
        cached.totalBytes = bytes;
        cached.totalTokens = tokens;
      }
    } catch {
      this.sessionFootprintCache.delete(sessionKey);
    }

    return { bytes, tokens };
  }

  private async estimateSessionBytesInFile(
    filePath: string,
    sessionKey: string,
  ): Promise<{ bytes: number; tokens: number }> {
    try {
      const raw = await readFile(filePath, "utf-8");
      let bytes = 0;
      let tokens = 0;
      for (const line of raw.split("\n")) {
        if (!line.trim()) continue;
        try {
          const parsed = JSON.parse(line) as { sessionKey?: string; content?: unknown };
          if (parsed.sessionKey === sessionKey) {
            bytes += Buffer.byteLength(`${line}\n`, "utf-8");
            if (typeof parsed.content === "string") tokens += estimateTokenCount(parsed.content);
          }
        } catch {
          // fail-open for malformed lines
        }
      }
      return { bytes, tokens };
    } catch {
      return { bytes: 0, tokens: 0 };
    }
  }

  private isLegacyTranscriptFile(filename: string): boolean {
    return /^\d{4}-\d{2}-\d{2}\.jsonl$/.test(filename);
  }

  /**
   * Append a turn to the appropriate transcript file.
   * Files are stored hierarchically: transcripts/{channelType}/{channelId}.jsonl
   *
   * Skips channel types in config.transcriptSkipChannelTypes (e.g., "cron").
   */
  async append(entry: TranscriptEntry): Promise<void> {
    try {
      const { dir, file, channelType, alternateDir, legacyDir } = this.getTranscriptPath(entry.sessionKey);

      // Skip if this channel type is in the skip list
      if (this.config.transcriptSkipChannelTypes.includes(channelType)) {
        return;
      }

      const { dir: writeDir, channelDir } = await this.selectStorageDirForWrite(
        this.transcriptsDir,
        dir,
        legacyDir,
        entry.sessionKey,
        alternateDir,
      );
      const filePath = await resolveSafeStoragePath(this.transcriptsDir, writeDir, file);

      // Ensure channel directory exists
      await mkdir(channelDir, { recursive: true });

      const line = JSON.stringify(entry) + "\n";
      await appendFile(filePath, line, "utf-8");
      await this.rememberDirectoryOwnership(this.transcriptsDir, writeDir, entry.sessionKey);
      log.debug(`appended transcript entry for ${entry.sessionKey}: ${entry.turnId}`);
    } catch (err) {
      log.error("failed to append transcript entry:", err);
      throw err;
    }
  }

  /**
   * Get all transcript files from the hierarchical directory structure.
   * Recursively finds all .jsonl files in transcripts/{channelType}/{channelId}/ subdirectories.
   */
  private async getAllTranscriptFiles(): Promise<string[]> {
    const files: string[] = [];

    try {
      const entries = await readdir(this.transcriptsDir, { withFileTypes: true });

      for (const entry of entries) {
        if (entry.isDirectory()) {
          // This is a channel type directory (discord, slack, cron, main, etc.)
          const channelTypeDir = path.join(this.transcriptsDir, entry.name);
          try {
            const channelTypeEntries = await readdir(channelTypeDir, { withFileTypes: true });

            for (const channelTypeEntry of channelTypeEntries) {
              if (channelTypeEntry.isDirectory()) {
                // This is a channel ID directory - contains daily transcript files
                const channelDir = path.join(channelTypeDir, channelTypeEntry.name);
                try {
                  const channelFiles = await readdir(channelDir);
                  for (const file of channelFiles) {
                    if (file.endsWith(".jsonl") && !isMacOsReplicationJunkBasename(file)) {
                      files.push(path.join(entry.name, channelTypeEntry.name, file));
                    }
                  }
                } catch {
                  // Skip unreadable directories
                }
              } else if (channelTypeEntry.isFile() && channelTypeEntry.name.endsWith(".jsonl") && !isMacOsReplicationJunkBasename(channelTypeEntry.name)) {
                // Legacy: channel type dir contains .jsonl files directly
                files.push(path.join(entry.name, channelTypeEntry.name));
              }
            }
          } catch {
            // Skip unreadable directories
          }
        } else if (entry.isFile() && entry.name.endsWith(".jsonl") && !isMacOsReplicationJunkBasename(entry.name)) {
          // Legacy flat file - still include for backward compatibility
          files.push(entry.name);
        }
      }
    } catch {
      // Directory doesn't exist or is unreadable
    }

    return files;
  }

  /**
   * Read transcript entries for a date range.
   * Returns entries within the time range, optionally filtered by sessionKey.
   * Reads from all channel subdirectories in the hierarchical structure.
   *
   * The window is half-open `[start, end)`: the upper bound is exclusive so
   * caller-specified ranges (explicit dates, analytics buckets) don't
   * double-count at shared boundaries (CLAUDE.md rule #35 / AGENTS.md rule 23).
   * readRecent's inclusive-of-now behavior is handled by readRecent itself
   * extending its end, not by relaxing this bound.
   */
  async readRange(startTime: string, endTime: string, sessionKey?: string, skipFilesDatedBefore?: string): Promise<TranscriptEntry[]> {
    const start = new Date(startTime);
    const end = new Date(endTime);
    const entries: TranscriptEntry[] = [];

    // When a sessionKey is given, a partially-applied #1496 migration can leave
    // the SAME raw row in both the primary `session/<hash>` dir and a read-back
    // dir (`other/default` or an old `parts.length >= 3` dir). `readRange` scans
    // EVERY transcript file, so it would append that row once per directory.
    // Dedup by exact raw line to give the same exact-once guarantee `readRecent`
    // / `readToolUse` / the summarizer fetch already provide (cursor review on
    // PR #1504). Only applied for the session-scoped path so unfiltered range
    // scans (each file already enumerated once) keep their existing behavior.
    const keepRawLine = sessionKey ? makeRawLineDeduper() : undefined;

    try {
      // Get all transcript files from the hierarchical structure
      const transcriptFiles = (await this.getAllTranscriptFiles()).filter((f) => !isDailyFileDatedBefore(f, skipFilesDatedBefore));

      // Read each relevant file
      for (const relativePath of transcriptFiles) {
        const filePath = path.join(this.transcriptsDir, relativePath);
        try {
          const content = await readFile(filePath, "utf-8");
          const lines = content.trim().split("\n").filter(Boolean);

          for (const line of lines) {
            try {
              const entry = JSON.parse(line) as TranscriptEntry;
              const entryTime = new Date(entry.timestamp);

              // Check if entry is within time range (half-open: exclusive end)
              if (entryTime >= start && entryTime < end) {
                // Filter by sessionKey if provided
                if (!sessionKey || entry.sessionKey === sessionKey) {
                  if (keepRawLine && !keepRawLine(line)) continue;
                  entries.push(entry);
                }
              }
            } catch {
              // Skip malformed lines
              log.debug(`skipped malformed transcript line in ${relativePath}`);
            }
          }
        } catch {
          // File doesn't exist or is unreadable - skip
        }
      }

      // Sort by timestamp
      entries.sort((a, b) => new Date(a.timestamp).getTime() - new Date(b.timestamp).getTime());

      log.debug(`read ${entries.length} transcript entries from ${transcriptFiles.length} file(s)`);
      return entries;
    } catch (err) {
      log.error("failed to read transcript range:", err);
      return [];
    }
  }

  /**
   * Read the last N hours of transcript.
   *
   * Fast path: when sessionKey is given, reads only the 1-2 daily files for that channel. Without one,
   * every channel is scanned but daily files older than the window (less a day of clock skew) are skipped.
   */
  async readRecent(hours: number, sessionKey?: string): Promise<TranscriptEntry[]> {
    const now = new Date();
    // The recent-read window is inclusive of "now": a turn that is buffered and
    // then immediately read back can carry the same millisecond timestamp as
    // this read, so a half-open [start, now) filter would drop it. Extend the
    // upper bound by 1ms so the exclusive [start, end) filters in
    // readRecentForSession / readRange (which stay half-open for
    // caller-specified ranges, CLAUDE.md rule #35) still capture an entry
    // stamped at exactly "now". This is the only place the "up to now" boundary
    // is widened; explicit ranges are unaffected.
    const end = new Date(now.getTime() + 1);
    const start = new Date(now.getTime() - hours * 60 * 60 * 1000);

    if (sessionKey) {
      return this.readRecentForSession(start, end, sessionKey);
    }
    return this.readRange(start.toISOString(), end.toISOString(), undefined, new Date(start.getTime() - 86_400_000).toISOString().slice(0, 10));
  }

  /**
   * Optimized read for a specific session: only looks in that session's channel
   * directory and only reads files whose date falls within the lookback window.
   */
  private async readRecentForSession(
    start: Date,
    end: Date,
    sessionKey: string,
  ): Promise<TranscriptEntry[]> {
    const { dir, alternateDir, legacyDir, readbackDirs } = this.getTranscriptPath(sessionKey);

    // Build set of date strings that overlap with [start, end].
    // Always include end's date to handle midnight-crossing lookbacks
    // (e.g. start=23:30 yesterday, end=00:30 today).
    const dateStrings = new Set<string>();
    const cursor = new Date(start);
    while (cursor <= end) {
      dateStrings.add(cursor.toISOString().slice(0, 10));
      cursor.setDate(cursor.getDate() + 1);
    }
    dateStrings.add(end.toISOString().slice(0, 10));

    const entries: TranscriptEntry[] = [];
    const files = await this.getSessionStorageFiles(
      this.transcriptsDir,
      dir,
      legacyDir,
      alternateDir,
      readbackDirs,
    );

    // Dedup identical raw rows that a partially-applied migration may have left
    // in both the primary dir and a read-back dir (issue #1496, cursor review).
    const keepRawLine = makeRawLineDeduper();
    for (const file of files) {
      // Only read files whose date is within the window
      const dateStr = file.name.slice(0, 10);
      if (!dateStrings.has(dateStr)) continue;

      try {
        const content = await readFile(file.path, "utf-8");
        for (const line of content.split("\n")) {
          if (!line.trim()) continue;
          try {
            const entry = JSON.parse(line) as TranscriptEntry;
            const ts = new Date(entry.timestamp);
            // Half-open window: exclusive end. readRecent widens its own end by
            // 1ms so a just-written "now" entry is still captured here without
            // relaxing this bound for direct callers (tests/transcript-boundary).
            if (ts >= start && ts < end && entry.sessionKey === sessionKey && keepRawLine(line)) {
              entries.push(entry);
            }
          } catch {
            // skip malformed line
          }
        }
      } catch {
        // skip unreadable file
      }
    }

    entries.sort((a, b) => new Date(a.timestamp).getTime() - new Date(b.timestamp).getTime());
    log.debug(`readRecentForSession: ${entries.length} entries from ${files.length} file(s) in ${dir}`);
    return entries;
  }

  /**
   * Cleanup old transcript entries that are older than retentionDays.
   * For hierarchical structure, reads each file and rewrites without old entries.
   * Legacy flat files are deleted if their date is older than retentionDays.
   * Returns the number of files processed (cleaned or deleted).
   */
  async cleanup(retentionDays: number): Promise<number> {
    if (retentionDays <= 0) {
      log.warn("cleanup called with invalid retentionDays:", retentionDays);
      return 0;
    }

    const cutoff = new Date();
    cutoff.setDate(cutoff.getDate() - retentionDays);
    cutoff.setHours(0, 0, 0, 0);

    let processed = 0;

    try {
      const entries = await readdir(this.transcriptsDir, { withFileTypes: true });

      for (const entry of entries) {
        if (entry.isDirectory()) {
          // This is a channel type directory (discord, slack, cron, main, etc.)
          const channelTypeDir = path.join(this.transcriptsDir, entry.name);
          try {
            const channelTypeEntries = await readdir(channelTypeDir, { withFileTypes: true });

            for (const channelTypeEntry of channelTypeEntries) {
              if (channelTypeEntry.isDirectory()) {
                // This is a channel ID directory - contains daily transcript files
                const channelDir = path.join(channelTypeDir, channelTypeEntry.name);
                try {
                  const channelFiles = await readdir(channelDir);
                  for (const file of channelFiles) {
                    if (isMacOsReplicationJunkBasename(file) || !file.endsWith(".jsonl")) continue;

                    const filePath = path.join(channelDir, file);

                    // Check if file is a daily transcript file (YYYY-MM-DD.jsonl)
                    if (this.isLegacyTranscriptFile(file)) {
                      const dateStr = file.slice(0, 10);
                      const fileDate = new Date(dateStr);

                      if (!isNaN(fileDate.getTime()) && fileDate < cutoff) {
                        try {
                          await unlink(filePath);
                          processed++;
                          log.debug(`deleted old daily transcript file: ${entry.name}/${channelTypeEntry.name}/${file}`);
                        } catch (err) {
                          log.error(`failed to delete transcript file ${filePath}:`, err);
                        }
                      }
                    } else {
                      // Legacy file in new structure - clean up old entries
                      const cleaned = await this.cleanupTranscriptFile(filePath, cutoff);
                      if (cleaned) {
                        processed++;
                      }
                    }
                  }
                } catch (err) {
                  log.debug(`failed to process channel directory ${entry.name}/${channelTypeEntry.name}:`, err);
                }
              } else if (channelTypeEntry.isFile() && channelTypeEntry.name.endsWith(".jsonl") && !isMacOsReplicationJunkBasename(channelTypeEntry.name)) {
                // Legacy: channel type dir contains .jsonl files directly
                const filePath = path.join(channelTypeDir, channelTypeEntry.name);
                const cleaned = await this.cleanupTranscriptFile(filePath, cutoff);
                if (cleaned) {
                  processed++;
                }
              }
            }
          } catch (err) {
            log.debug(`failed to process channel type directory ${entry.name}:`, err);
          }
        } else if (entry.isFile() && entry.name.endsWith(".jsonl") && !isMacOsReplicationJunkBasename(entry.name)) {
          // Handle legacy flat files - delete if older than retentionDays
          if (this.isLegacyTranscriptFile(entry.name)) {
            const dateStr = entry.name.slice(0, 10);
            const fileDate = new Date(dateStr);

            if (!isNaN(fileDate.getTime()) && fileDate < cutoff) {
              const filePath = path.join(this.transcriptsDir, entry.name);
              try {
                await unlink(filePath);
                processed++;
                log.debug(`deleted old legacy transcript file: ${entry.name}`);
              } catch (err) {
                log.error(`failed to delete legacy transcript file ${entry.name}:`, err);
              }
            }
          }
        }
      }

      if (processed > 0) {
        log.info(`cleaned up ${processed} transcript file(s) older than ${retentionDays} days`);
      }

      return processed;
    } catch (err) {
      log.error("failed to cleanup old transcripts:", err);
      return 0;
    }
  }

  /**
   * Clean up old entries from a single transcript file.
   * Reads the file, filters out entries older than cutoff, and rewrites if needed.
   * Returns true if the file was processed (cleaned or deleted).
   */
  private async cleanupTranscriptFile(filePath: string, cutoff: Date): Promise<boolean> {
    try {
      const content = await readFile(filePath, "utf-8");
      const lines = content.trim().split("\n").filter(Boolean);

      const validLines: string[] = [];
      let hasOldEntries = false;

      for (const line of lines) {
        try {
          const entry = JSON.parse(line) as TranscriptEntry;
          const entryTime = new Date(entry.timestamp);

          if (entryTime >= cutoff) {
            validLines.push(line);
          } else {
            hasOldEntries = true;
          }
        } catch {
          // Keep malformed lines to avoid data loss
          validLines.push(line);
        }
      }

      if (validLines.length === 0) {
        // No valid entries left, delete the file
        try {
          await unlink(filePath);
          log.debug(`deleted empty transcript file: ${filePath}`);
          return true;
        } catch (err) {
          log.error(`failed to delete empty transcript file ${filePath}:`, err);
          return false;
        }
      }

      if (hasOldEntries) {
        // Rewrite file without old entries
        await writeFile(filePath, validLines.join("\n") + "\n", "utf-8");
        log.debug(`cleaned old entries from transcript file: ${filePath}`);
        return true;
      }

      // No old entries found, no action needed
      return false;
    } catch (err) {
      // File doesn't exist or is unreadable
      return false;
    }
  }

  /**
   * Save a checkpoint to preserve conversation context.
   * Called when compaction is detected.
   */
  async saveCheckpoint(checkpoint: Checkpoint): Promise<void> {
    try {
      await writeFile(this.checkpointPath, JSON.stringify(checkpoint, null, 2), "utf-8");
      log.info(`saved checkpoint for session ${checkpoint.sessionKey} with ${checkpoint.turns.length} turn(s)`);
    } catch (err) {
      log.error("failed to save checkpoint:", err);
      throw err;
    }
  }

  /**
   * Load a checkpoint if one exists and is not expired.
   * Returns null if no checkpoint exists or if it has expired.
   */
  async loadCheckpoint(sessionKey?: string): Promise<Checkpoint | null> {
    try {
      const raw = await readFile(this.checkpointPath, "utf-8");
      const checkpoint = JSON.parse(raw) as Checkpoint;

      // Validate checkpoint structure
      if (!checkpoint.sessionKey || !checkpoint.capturedAt || !checkpoint.ttl || !Array.isArray(checkpoint.turns)) {
        log.warn("checkpoint file has invalid structure");
        return null;
      }

      // Check if checkpoint is for the requested session (if specified)
      if (sessionKey && checkpoint.sessionKey !== sessionKey) {
        log.debug(`checkpoint session mismatch: ${checkpoint.sessionKey} vs ${sessionKey}`);
        return null;
      }

      // Check if checkpoint has expired
      const ttl = new Date(checkpoint.ttl);
      if (isNaN(ttl.getTime())) {
        log.warn("checkpoint has invalid TTL format");
        return null;
      }

      if (ttl < new Date()) {
        log.info(`checkpoint expired at ${checkpoint.ttl}`);
        return null;
      }

      log.info(`loaded checkpoint with ${checkpoint.turns.length} turn(s), expires at ${checkpoint.ttl}`);
      return checkpoint;
    } catch (err) {
      // File doesn't exist or is unreadable - that's fine
      log.debug("no valid checkpoint found");
      return null;
    }
  }

  /**
   * Clear (delete) the checkpoint file.
   * Called after successful injection of checkpoint context.
   */
  async clearCheckpoint(): Promise<void> {
    try {
      await unlink(this.checkpointPath);
      log.info("cleared checkpoint");
    } catch (err) {
      // File doesn't exist - that's fine
      log.debug("no checkpoint to clear");
    }
  }

  /**
   * Format entries for recall injection.
   * Returns a formatted string suitable for injecting into agent context.
   *
   * Format:
   * ## Recent Conversation (last X hours)
   * [10:32] User: message content
   * [10:33] Assistant: response content
   *
   * Content is trimmed to approximately maxTokens.
   */
  formatForRecall(entries: TranscriptEntry[], maxTokens: number): string {
    if (entries.length === 0) {
      return "";
    }

    const maxTokenBudget = Math.max(0, Math.floor(maxTokens));
    if (maxTokenBudget === 0) return "";
    const lines: string[] = [];
    // Calculate time range for header
    const firstEntry = new Date(entries[0].timestamp);
    const lastEntry = new Date(entries[entries.length - 1].timestamp);
    const hoursDiff = Math.round((lastEntry.getTime() - firstEntry.getTime()) / (60 * 60 * 1000));

    // Add header
    if (hoursDiff < 1) {
      lines.push("## Recent Conversation (last few minutes)");
    } else {
      lines.push(`## Recent Conversation (last ${hoursDiff} hour${hoursDiff === 1 ? "" : "s"})`);
    }
    lines.push("");
    if (estimateTokenCount(lines.join("\n")) > maxTokenBudget) {
      return "";
    }

    // Format each entry
    const formattedEntries: string[] = [];
    for (const entry of entries) {
      const time = new Date(entry.timestamp);
      const timeStr = time.toLocaleTimeString("en-US", {
        hour: "2-digit",
        minute: "2-digit",
        hour12: false,
      });
      const roleLabel = entry.role === "user" ? "User" : "Assistant";
      formattedEntries.push(`[${timeStr}] ${roleLabel}: ${entry.content}`);
    }

    const selectedEntries: string[] = [];

    for (let i = formattedEntries.length - 1; i >= 0; i--) {
      const entry = formattedEntries[i];
      const candidate = [...lines, entry, ...selectedEntries, ""].join("\n");
      if (estimateTokenCount(candidate) > maxTokenBudget) {
        if (selectedEntries.length > 0) break;
        return "";
      }

      selectedEntries.unshift(entry);
    }
    if (selectedEntries.length === 0) return "";

    lines.push(...selectedEntries);
    lines.push(""); // Trailing newline

    const result = lines.join("\n");
    log.debug(`formatted ${selectedEntries.length}/${entries.length} transcript entries for recall (~${result.length} chars)`);

    return result;
  }

  /**
   * Create a checkpoint from the current buffer state.
   * Helper method for creating checkpoints before compaction.
   */
  createCheckpoint(sessionKey: string, turns: TranscriptEntry[], ttlHours?: number): Checkpoint {
    const ttl = ttlHours ?? TranscriptManager.DEFAULT_CHECKPOINT_TTL_HOURS;
    const expiresAt = new Date();
    expiresAt.setHours(expiresAt.getHours() + ttl);

    return {
      sessionKey,
      capturedAt: new Date().toISOString(),
      turns: [...turns], // Copy turns to avoid mutation
      ttl: expiresAt.toISOString(),
    };
  }

  /**
   * Get statistics about stored transcripts.
   * Returns counts from the hierarchical directory structure.
   */
  async getStats(): Promise<{
    totalFiles: number;
    totalEntries: number;
    oldestFile: string | null;
    newestFile: string | null;
    channelTypes: Record<string, number>;
  }> {
    try {
      const allFiles = await this.getAllTranscriptFiles();

      if (allFiles.length === 0) {
        return {
          totalFiles: 0,
          totalEntries: 0,
          oldestFile: null,
          newestFile: null,
          channelTypes: {},
        };
      }

      // Sort files by path
      const sortedFiles = allFiles.sort();

      let totalEntries = 0;
      const channelTypes: Record<string, number> = {};

      for (const relativePath of allFiles) {
        const filePath = path.join(this.transcriptsDir, relativePath);
        try {
          const content = await readFile(filePath, "utf-8");
          const lines = content.trim().split("\n").filter(Boolean);
          totalEntries += lines.length;

          // Count by channel type (first directory in path)
          const channelType = relativePath.includes(path.sep)
            ? relativePath.split(path.sep)[0]
            : "legacy";
          channelTypes[channelType] = (channelTypes[channelType] || 0) + 1;
        } catch {
          // Skip unreadable files
        }
      }

      return {
        totalFiles: allFiles.length,
        totalEntries,
        oldestFile: sortedFiles[0],
        newestFile: sortedFiles[sortedFiles.length - 1],
        channelTypes,
      };
    } catch (err) {
      log.error("failed to get transcript stats:", err);
      return {
        totalFiles: 0,
        totalEntries: 0,
        oldestFile: null,
        newestFile: null,
        channelTypes: {},
      };
    }
  }

  async analyzeIntegrity(): Promise<SessionIntegrityReport> {
    return analyzeSessionIntegrity({ memoryDir: this.config.memoryDir });
  }

  async getRecoverySummary(sessionKey?: string): Promise<{
    generatedAt: string;
    sessionKey?: string;
    healthy: boolean;
    issueCount: number;
    incompleteTurns: number;
    brokenChains: number;
    checkpointHealthy: boolean;
  }> {
    const report = await this.analyzeIntegrity();
    const selectedSessions = sessionKey
      ? report.sessions.filter((session) => session.sessionKey === sessionKey)
      : report.sessions;
    const incompleteTurns = selectedSessions.reduce((sum, session) => sum + session.incompleteTurns, 0);
    const brokenChains = selectedSessions.reduce((sum, session) => sum + session.brokenChains, 0);
    const filteredIssues = report.issues.filter((issue) => !sessionKey || issue.sessionKey === sessionKey);
    const issueCount = filteredIssues.length;
    const severeIssueCount = filteredIssues.filter((issue) => issue.severity !== "info").length;
    return {
      generatedAt: report.generatedAt,
      sessionKey,
      healthy: sessionKey ? severeIssueCount === 0 && report.checkpoint.healthy : report.healthy,
      issueCount,
      incompleteTurns,
      brokenChains,
      checkpointHealthy: report.checkpoint.healthy,
    };
  }
}

import { mkdir, readFile, writeFile, readdir } from "node:fs/promises";
import path from "node:path";
import { z } from "zod";
import { log } from "./logger.js";
import { LocalLlmClient } from "./local-llm.js";
import { FallbackLlmClient, fallbackLlmRuntimeContextFromConfig, gatewayTaskChainOptions } from "./fallback-llm.js";
import { ModelRegistry } from "./model-registry.js";
import { extractJsonCandidates } from "./json-extract.js";
import {
  completeBackgroundGeneration,
  parseBackgroundGenerationJson,
} from "./background-generation.js";
import type { HourlySummary, TranscriptEntry, PluginConfig, GatewayConfig } from "./types.js";
import type { TranscriptManager } from "./transcript.js";
import { readSummarySnapshot, upsertSummarySnapshot, writeSummarySnapshot } from "./summary-snapshot.js";
import { encodeStoragePathSegment, resolveSafeStoragePath } from "./storage-paths.js";
import { sessionStoragePaths } from "./session-identity.js";
import { resolveLocalLlmCapabilities } from "./capabilities.js";
import { resolvePipelineProcessingCapabilities } from "./capabilities.js";

// Schema for LLM summary output
const HourlySummarySchema = z.object({
  bullets: z.array(z.string().trim().min(1)).min(1).describe("3-5 bullet points summarizing the hour's activity"),
});

type HourlySummaryResult = z.infer<typeof HourlySummarySchema>;

const HourlySummaryExtendedSchema = z.object({
  topics: z.array(z.string()).default([]),
  decisions: z.array(z.string()).default([]),
  actionItems: z.array(z.string()).default([]),
  rejected: z.array(z.string()).default([]),
});

type HourlySummaryExtendedResult = z.infer<typeof HourlySummaryExtendedSchema>;

type HourlySummaryExtendedMeta = {
  userTurns: number;
  assistantTurns: number;
  toolCalls: number;
  toolCounts: Record<string, number>;
};

function escapeRegExp(value: string): string {
  return value.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
}

/**
 * Outcome stats of one `runHourly` pass (issue #2783). The summarizer must
 * not report success on empty work: an empty or stale transcript store is
 * the delegate-mode starvation signature, and callers surface these counts
 * and the staleness flag as a distinct warning instead of a bare ok.
 */
export interface HourlySummarizerRunStats {
  sessionsConsidered: number;
  sessionsWithEntries: number;
  summariesWritten: number;
  /** True when the newest transcript entry across the store is older than STALE_STORE_MS. */
  staleStore: boolean;
  /** ISO timestamp of the newest transcript entry seen by the scan, when any exist. */
  newestEntryTimestamp: string | null;
  /** True when the transcript scan itself FAILED (unreadable store) — distinct from an empty store. */
  scanFailed: boolean;
}

/** A store whose newest entry is older than this is considered stale (starvation signal, issue #2783). */
const STALE_STORE_MS = 2 * 60 * 60 * 1000;

/**
 * Interpret one {@link HourlySummarizerRunStats} into the operator-facing
 * message/warning (issue #2783). Every degraded shape — failed scan, empty
 * store, backend-down, stale store — is DISTINCT from success; monitoring
 * alerts on `warning`, never on `ok` (ok only means "the run completed").
 */
export function summarizeHourlyStatus(stats: HourlySummarizerRunStats): {
  message: string;
  warning?: string;
} {
  if (stats.scanFailed) {
    return {
      message:
        "Hourly summarization completed, but the transcript store scan FAILED (unreadable directory or I/O error). Investigate the daemon's memoryDir.",
      warning: "transcript store scan failed",
    };
  }
  if (stats.sessionsConsidered === 0) {
    return {
      message:
        "Hourly summarization completed, but the transcript store is empty — no sessions found. If turns are ingested via observe, transcript persistence may be disabled or failing.",
      warning: "transcript store is empty",
    };
  }
  if (stats.sessionsWithEntries > 0 && stats.summariesWritten === 0) {
    return {
      message: `Hourly summarization found ${stats.sessionsWithEntries} session(s) with transcript entries but wrote no summaries — the summarizer backend may be down.`,
      warning: "sessions with entries produced no summaries",
    };
  }
  if (stats.sessionsWithEntries === 0 && stats.staleStore) {
    return {
      message: `Hourly summarization completed with no transcript entries for the target hour, and the store looks stale (newest entry ${stats.newestEntryTimestamp ?? "unknown"}).`,
      warning: "no transcript entries for the target hour and no new entries recently",
    };
  }
  return {
    message: `Hourly summarization completed: ${stats.summariesWritten} summar${stats.summariesWritten === 1 ? "y" : "ies"} written across ${stats.sessionsWithEntries} session${stats.sessionsWithEntries === 1 ? "" : "s"} with transcript entries.`,
  };
}

export class HourlySummarizer {
  private summariesDir: string;
  private config: PluginConfig;
  private localLlm: LocalLlmClient;
  private fallbackLlm: FallbackLlmClient;
  private modelRegistry: ModelRegistry;
  private transcript?: TranscriptManager;

  constructor(
    config: PluginConfig,
    gatewayConfig?: GatewayConfig,
    modelRegistry?: ModelRegistry,
    transcript?: TranscriptManager
  ) {
    this.config = config;
    this.summariesDir = path.join(config.memoryDir, "summaries", "hourly");
    this.modelRegistry = modelRegistry ?? new ModelRegistry(config.memoryDir);
    this.transcript = transcript;

    // Initialize local LLM client with shared model registry
    this.localLlm = new LocalLlmClient(config, this.modelRegistry);

    // Initialize fallback client with gateway config
    this.fallbackLlm = new FallbackLlmClient(gatewayConfig, fallbackLlmRuntimeContextFromConfig(config));

    if (
      !gatewayConfig?.agents?.defaults?.model?.primary &&
      !resolveLocalLlmCapabilities(config).localLlm &&
      config.modelSource !== "gateway"
    ) {
      log.warn("no gateway default AI and local LLM disabled — hourly summarization disabled");
    }
  }

  private get useGatewayModelSource(): boolean {
    return this.config.modelSource === "gateway";
  }

  private get shouldUseLocalLlm(): boolean {
    return resolveLocalLlmCapabilities(this.config).localLlm && !this.useGatewayModelSource;
  }

  private withGatewayAgent(
    options: import("./fallback-llm.js").FallbackLlmOptions
  ): import("./fallback-llm.js").FallbackLlmOptions {
    if (!this.useGatewayModelSource) return options;
    // Shared resolution (taskModelChain > gatewayAgentId) — gotcha #22. Issue #1365.
    return { ...options, ...gatewayTaskChainOptions(this.config) };
  }

  async initialize(): Promise<void> {
    await mkdir(this.summariesDir, { recursive: true });
    log.info("hourly summarizer initialized");
  }

  private async summarySessionDir(sessionKey: string): Promise<string> {
    return resolveSafeStoragePath(this.summariesDir, encodeStoragePathSegment(sessionKey, "session"));
  }

  private async legacySummarySessionDir(sessionKey: string): Promise<string | null> {
    if (sessionKey.includes("\0")) return null;
    try {
      return await resolveSafeStoragePath(this.summariesDir, sessionKey);
    } catch {
      return null;
    }
  }

  private summaryDateString(hour: string): string {
    const dateStr = hour.slice(0, 10);
    if (!/^\d{4}-\d{2}-\d{2}$/.test(dateStr)) {
      throw new Error(`invalid hourly summary timestamp: ${hour}`);
    }
    return dateStr;
  }

  // Generate summary for a specific hour and session
  async generateSummary(
    sessionKey: string,
    hourStart: Date,
    entries: TranscriptEntry[]
  ): Promise<HourlySummary | null> {
    if (entries.length === 0) return null;

    // Format entries for the LLM
    const conversation = entries.map((e) => `[${e.role}] ${e.content}`).join("\n\n");

    if (resolvePipelineProcessingCapabilities(this.config).hourlySummariesExtended) {
      const extended = await this.generateExtended(sessionKey, hourStart, conversation, entries);
      if (!extended) return null;
      const meta: HourlySummaryExtendedMeta = {
        userTurns: entries.filter((e) => e.role === "user").length,
        assistantTurns: entries.filter((e) => e.role === "assistant").length,
        toolCalls: extended._meta.toolCalls,
        toolCounts: extended._meta.toolCounts,
      };
      // Keep HourlySummary surface stable; encode "topics" as bullets for recall injection.
      const base: HourlySummary = {
        hour: hourStart.toISOString(),
        sessionKey,
        bullets: extended.topics.length > 0 ? extended.topics.slice(0, 5) : ["(summary generated)"],
        turnCount: entries.length,
        generatedAt: new Date().toISOString(),
      };
      const withExtras = base as any;
      withExtras._extended = extended;
      withExtras._extendedMeta = meta;
      return base;
    }

    const hourIso = hourStart.toISOString();
    const startTime = Date.now();

    if (this.config.backgroundGeneration) {
      try {
        const text = await completeBackgroundGeneration(this.config, [
          {
            role: "system",
            content:
              "You are a conversation summarization system. Summarize the following conversation transcript into 3-5 concise bullet points.\n\nGuidelines:\n- Focus on what was accomplished, decided, or discussed\n- Include specific topics, projects, or entities mentioned\n- Note any significant user requests or agent actions\n- Keep bullets brief but informative (1-2 sentences each)\n- Skip trivial greetings or meta-conversation\n- Use present tense for ongoing work, past for completed items\n\nRespond with valid JSON only, matching this schema:\n{\"bullets\": [\"bullet 1\", \"bullet 2\", \"bullet 3\"]}",
          },
          { role: "user", content: `Summarize this conversation:\n\n${conversation}` },
        ]);
        const parsed = parseBackgroundGenerationJson(text, (value) => HourlySummarySchema.parse(value));
        if (parsed) {
          return {
            hour: hourIso,
            sessionKey,
            bullets: parsed.bullets,
            turnCount: entries.length,
            generatedAt: new Date().toISOString(),
          };
        }
      } catch {
        log.info("summary generation: background generation unavailable, continuing");
      }
    }

    // Try local LLM first if enabled
    if (this.shouldUseLocalLlm) {
      try {
        const localResult = await this.generateWithLocalLlm(conversation);
        if (localResult) {
          const durationMs = Date.now() - startTime;
          log.debug(`generated hourly summary for ${sessionKey} at ${hourIso} in ${durationMs}ms using local LLM`);
          return {
            hour: hourIso,
            sessionKey,
            bullets: localResult.bullets,
            turnCount: entries.length,
            generatedAt: new Date().toISOString(),
          };
        }
        // Local failed, fall back if allowed
        if (!this.config.localLlmFallback) {
          log.warn("summary generation: local LLM failed and fallback disabled");
          return null;
        }
        log.info("summary generation: local LLM unavailable, falling back to gateway default AI");
      } catch (err) {
        if (!this.config.localLlmFallback) {
          log.warn("summary generation: local LLM error and fallback disabled:", err);
          return null;
        }
        log.info("summary generation: local LLM error, falling back to gateway default AI:", err);
      }
    }

    // Fall back to gateway's default AI
    log.info("summary generation: falling back to gateway default AI");

    try {
      const messages = [
        {
          role: "system" as const,
          content: `You are a conversation summarization system. Summarize the following conversation transcript into 3-5 concise bullet points.

Guidelines:
- Focus on what was accomplished, decided, or discussed
- Include specific topics, projects, or entities mentioned
- Note any significant user requests or agent actions
- Keep bullets brief but informative (1-2 sentences each)
- Skip trivial greetings or meta-conversation
- Use present tense for ongoing work, past for completed items

Respond with valid JSON matching this schema:
{
  "bullets": ["bullet 1", "bullet 2", "bullet 3"]
}`,
        },
        { role: "user" as const, content: `Summarize this conversation:\n\n${conversation}` },
      ];

      const result = await this.fallbackLlm.parseWithSchema(
        messages,
        HourlySummarySchema,
        this.withGatewayAgent({ temperature: 0.3, maxTokens: 8192 })
      );

      const durationMs = Date.now() - startTime;

      if (result) {
        log.debug(`generated hourly summary for ${sessionKey} at ${hourIso} in ${durationMs}ms via fallback`);
        return {
          hour: hourIso,
          sessionKey,
          bullets: result.bullets,
          turnCount: entries.length,
          generatedAt: new Date().toISOString(),
        };
      }

      log.warn("summary generation fallback returned no parsed output");
      return null;
    } catch (err) {
      log.error("summary generation fallback failed", err);
      return null;
    }
  }

  private async generateExtended(
    sessionKey: string,
    hourStart: Date,
    conversation: string,
    entries: TranscriptEntry[]
  ): Promise<(HourlySummaryExtendedResult & { _meta: HourlySummaryExtendedMeta }) | null> {
    const hourIso = hourStart.toISOString();
    const startTime = Date.now();

    const hourEnd = new Date(hourStart.getTime() + 60 * 60 * 1000);
    let toolCounts: Record<string, number> = {};
    if (this.config.hourlySummariesIncludeToolStats && this.transcript) {
      const uses = await this.transcript.readToolUse(sessionKey, hourStart, hourEnd);
      for (const u of uses) toolCounts[u.tool] = (toolCounts[u.tool] ?? 0) + 1;
    }

    const sys = `You are a conversation summarization system.\n\nSummarize the hour into structured sections.\n\nReturn valid JSON matching:\n{\n  \"topics\": [\"...\"],\n  \"decisions\": [\"...\"],\n  \"actionItems\": [\"...\"],\n  \"rejected\": [\"...\"]\n}\n\nGuidelines:\n- Prefer concrete topics and decisions.\n- Action items should be imperative.\n- Rejected ideas are things that were explicitly discarded or reversed.\n- If there are none for a section, return an empty array.\n`;

    const toolStatsLine =
      Object.keys(toolCounts).length > 0
        ? `Tools used (counts): ${Object.entries(toolCounts)
            .sort((a, b) => b[1] - a[1])
            .slice(0, 10)
            .map(([k, v]) => `${k}=${v}`)
            .join(", ")}\n\n`
        : "";
    const userTurns = entries.filter((e) => e.role === "user").length;
    const assistantTurns = entries.filter((e) => e.role === "assistant").length;
    const toolCalls = Object.values(toolCounts).reduce((a, b) => a + b, 0);
    const statsLine = `Stats: userTurns=${userTurns}, assistantTurns=${assistantTurns}, toolCalls=${toolCalls}\n\n`;

    const user = `Hour: ${hourIso}\nSession: ${sessionKey}\n\n${statsLine}${toolStatsLine}Conversation:\n${conversation}\n`;

    if (this.config.backgroundGeneration) {
      try {
        const text = await completeBackgroundGeneration(this.config, [
          { role: "system", content: sys },
          { role: "user", content: user },
        ]);
        const parsed = parseBackgroundGenerationJson(text, (value) => HourlySummaryExtendedSchema.parse(value));
        if (parsed) {
          log.debug(
            `generated extended hourly summary for ${sessionKey} at ${hourIso} in ${Date.now() - startTime}ms (background)`
          );
          return { ...parsed, _meta: { userTurns, assistantTurns, toolCalls, toolCounts } };
        }
      } catch {
        log.info("extended summary: background generation unavailable, continuing");
      }
    }

    // Try local LLM first if enabled
    if (this.shouldUseLocalLlm) {
      try {
        const contextSizes = this.modelRegistry.calculateContextSizes(
          this.config.localLlmModel,
          this.config.localLlmMaxContext
        );
        const truncated =
          user.length > contextSizes.maxInputChars
            ? user.slice(0, contextSizes.maxInputChars) + "\n\n[truncated]"
            : user;
        const response = await this.localLlm.chatCompletion(
          [
            { role: "system", content: "Output valid JSON only." },
            { role: "user", content: sys + "\n\n" + truncated },
          ],
          {
            temperature: 0.2,
            maxTokens: contextSizes.maxOutputTokens,
            operation: "hourly_summary_extended",
            priority: "background",
          }
        );
        if (response?.content) {
          const content = response.content.trim();
          for (const candidate of extractJsonCandidates(content)) {
            try {
              const parsed = JSON.parse(candidate);
              const result = HourlySummaryExtendedSchema.parse(parsed);
              log.debug(
                `generated extended hourly summary for ${sessionKey} at ${hourIso} in ${Date.now() - startTime}ms (local)`
              );
              return { ...result, _meta: { userTurns, assistantTurns, toolCalls, toolCounts } };
            } catch {
              // keep trying candidates
            }
          }
        }
      } catch (err) {
        if (!this.config.localLlmFallback) return null;
        log.info("extended summary: local failed, falling back:", err);
      }
    }

    try {
      const result = await this.fallbackLlm.parseWithSchema(
        [
          { role: "system" as const, content: sys },
          { role: "user" as const, content: user },
        ],
        HourlySummaryExtendedSchema,
        this.withGatewayAgent({ temperature: 0.2, maxTokens: 2048 })
      );
      if (result) {
        log.debug(
          `generated extended hourly summary for ${sessionKey} at ${hourIso} in ${Date.now() - startTime}ms (fallback)`
        );
        return { ...result, _meta: { userTurns, assistantTurns, toolCalls, toolCounts } };
      }
      return null;
    } catch (err) {
      log.error("extended summary generation failed", err);
      return null;
    }
  }

  /**
   * Generate summary using local LLM with JSON mode.
   * Uses dynamic context sizing based on model capabilities.
   */
  private async generateWithLocalLlm(conversation: string): Promise<HourlySummaryResult | null> {
    // Get dynamic context sizes based on model capabilities
    const contextSizes = this.modelRegistry.calculateContextSizes(
      this.config.localLlmModel,
      this.config.localLlmMaxContext
    );
    log.debug(`Summarizer model context: ${contextSizes.description}`);

    const maxConversationChars = contextSizes.maxInputChars;
    const truncatedConversation =
      conversation.length > maxConversationChars
        ? conversation.slice(0, maxConversationChars) + "\n\n[truncated]"
        : conversation;

    const instructions = `You are a conversation summarization system. Summarize the following conversation transcript into 3-5 concise bullet points.

Guidelines:
- Focus on what was accomplished, decided, or discussed
- Include specific topics, projects, or entities mentioned
- Note any significant user requests or agent actions
- Keep bullets brief but informative (1-2 sentences each)
- Skip trivial greetings or meta-conversation
- Use present tense for ongoing work, past for completed items

Respond with valid JSON matching this schema:
{
  "bullets": ["bullet 1", "bullet 2", "bullet 3"]
}`;

    const fullPrompt = `${instructions}\n\nConversation to summarize:\n${truncatedConversation}`;

    const response = await this.localLlm.chatCompletion(
      [
        { role: "system", content: "You are a conversation summarization system. Output valid JSON only." },
        { role: "user", content: fullPrompt },
      ],
      {
        temperature: 0.3,
        maxTokens: contextSizes.maxOutputTokens,
        operation: "hourly_summary",
        priority: "background",
      }
    );

    if (!response?.content) {
      return null;
    }

    try {
      // Parse JSON response
      const content = response.content.trim();
      for (const candidate of extractJsonCandidates(content)) {
        try {
          const parsed = JSON.parse(candidate);
          return HourlySummarySchema.parse(parsed);
        } catch {
          // keep trying candidates
        }
      }
      return null;
    } catch (err) {
      log.warn("local LLM summary: failed to parse JSON response:", err);
      return null;
    }
  }

  // Save summary to file
  async saveSummary(summary: HourlySummary): Promise<void> {
    const sessionDir = await this.summarySessionDir(summary.sessionKey);
    await mkdir(sessionDir, { recursive: true });

    // Format date as YYYY-MM-DD for the filename
    const dateStr = this.summaryDateString(summary.hour);
    const filePath = await resolveSafeStoragePath(sessionDir, `${dateStr}.md`);

    // Format hour as HH:00 for display
    const hourStr = summary.hour.slice(11, 13);

    // Build markdown content
    const lines: string[] = [];

    // Check if file exists to append or create
    let existingContent = "";
    try {
      existingContent = await readFile(filePath, "utf-8");
    } catch {
      // File doesn't exist yet, will create new
    }

    // Check if this hour already exists (idempotent)
    const hourHeader = `## ${hourStr}:00`;
    if (existingContent.includes(hourHeader)) {
      // Replace existing hour section
      const headerMatch = new RegExp(`(^|\\n)${escapeRegExp(hourHeader)}\\n`).exec(existingContent);
      const sectionStart = headerMatch
        ? headerMatch.index + headerMatch[1].length
        : existingContent.indexOf(hourHeader);
      const nextHeaderPattern = /\n## \d{2}:00\n/g;
      nextHeaderPattern.lastIndex = sectionStart + hourHeader.length;
      const nextHeader = nextHeaderPattern.exec(existingContent);
      const beforeHour = existingContent.slice(0, sectionStart);
      const afterHour = nextHeader ? existingContent.slice(nextHeader.index + 1) : "";
      const newSection = this.formatHourSection(summary, hourHeader);
      existingContent = beforeHour + newSection.trimEnd() + (afterHour ? "\n\n" + afterHour : "\n");

      await writeFile(filePath, existingContent, "utf-8");
      log.debug(`updated hourly summary for ${summary.sessionKey} at ${hourStr}:00`);
    } else {
      // Append new hour section
      const newSection = this.formatHourSection(summary, hourHeader);

      if (existingContent) {
        // Add to existing file
        await writeFile(filePath, existingContent.trimEnd() + "\n\n" + newSection, "utf-8");
      } else {
        // Create new file with header
        const header = `# Hourly Summaries — ${dateStr}\n\n*Session: ${summary.sessionKey}*\n`;
        await writeFile(filePath, header + "\n" + newSection, "utf-8");
      }
      log.debug(`saved hourly summary for ${summary.sessionKey} at ${hourStr}:00`);
    }
    try {
      await upsertSummarySnapshot(this.config.memoryDir, summary);
    } catch (error) {
      log.warn(
        `hourly summarizer: failed to update summary snapshot for ${summary.sessionKey} (fail-open): ${String(error)}`
      );
    }
  }

  private formatHourSection(summary: HourlySummary, hourHeader: string): string {
    const ext = (summary as any)._extended as
      | (HourlySummaryExtendedResult & { _meta?: HourlySummaryExtendedMeta })
      | undefined;
    const meta = (summary as any)._extendedMeta as HourlySummaryExtendedMeta | undefined;
    const lines: string[] = [hourHeader, ""];

    if (resolvePipelineProcessingCapabilities(this.config).hourlySummariesExtended && ext) {
      lines.push("### Topics Discussed");
      for (const t of ext.topics) lines.push(`- ${t}`);
      lines.push("");
      lines.push("### Decisions Made");
      for (const d of ext.decisions) lines.push(`- ${d}`);
      lines.push("");
      lines.push("### Action Items");
      for (const a of ext.actionItems) lines.push(`- ${a}`);
      lines.push("");
      lines.push("### Rejected Ideas / Reversals");
      for (const r of ext.rejected) lines.push(`- ${r}`);
      lines.push("");
      if (meta && Object.keys(meta.toolCounts).length > 0) {
        lines.push("### Tools Used");
        const top = Object.entries(meta.toolCounts)
          .sort((a, b) => b[1] - a[1])
          .slice(0, 12);
        for (const [name, count] of top) lines.push(`- ${name}: ${count}`);
        lines.push("");
      }
      lines.push("### Stats");
      lines.push(`- Turns: ${summary.turnCount}`);
      if (meta) {
        lines.push(`- User turns: ${meta.userTurns}`);
        lines.push(`- Assistant turns: ${meta.assistantTurns}`);
        lines.push(`- Tool calls: ${meta.toolCalls}`);
      }
      lines.push("");
      return lines.join("\n");
    }

    for (const bullet of summary.bullets) lines.push(`- ${bullet}`);
    lines.push(`  *(${summary.turnCount} turns)*`);
    lines.push("");
    return lines.join("\n");
  }

  // Read recent summaries for recall injection
  async readRecent(sessionKey: string, hours: number): Promise<HourlySummary[]> {
    try {
      const cutoffTime = Date.now() - hours * 60 * 60 * 1000;

      const snapshot = await readSummarySnapshot(this.config.memoryDir, sessionKey);
      if (snapshot) {
        return snapshot
          .filter((s) => new Date(s.hour).getTime() >= cutoffTime)
          .sort((a, b) => new Date(b.hour).getTime() - new Date(a.hour).getTime());
      }

      const summaries: HourlySummary[] = [];
      const encodedDir = await this.summarySessionDir(sessionKey);
      const legacyDir = await this.legacySummarySessionDir(sessionKey);
      const seenDirs = new Set<string>();

      for (const sessionDir of [encodedDir, legacyDir]) {
        if (!sessionDir || seenDirs.has(sessionDir)) continue;
        seenDirs.add(sessionDir);
        const parsed = await this.readSummaryDir(sessionDir, sessionKey);
        summaries.push(...parsed);
      }

      const byHour = new Map<string, HourlySummary>();
      for (const summary of summaries) {
        if (!byHour.has(summary.hour)) byHour.set(summary.hour, summary);
      }

      const sortedSummaries = Array.from(byHour.values()).sort(
        (a, b) => new Date(b.hour).getTime() - new Date(a.hour).getTime()
      );

      // Filter to recent hours while materializing the full parsed history.
      const recent = sortedSummaries.filter((s) => new Date(s.hour).getTime() >= cutoffTime);

      if (sortedSummaries.length > 0) {
        try {
          await writeSummarySnapshot(this.config.memoryDir, sessionKey, sortedSummaries);
        } catch (error) {
          log.warn(
            `hourly summarizer: failed to materialize summary snapshot for ${sessionKey} (fail-open): ${String(error)}`
          );
        }
      }

      return recent;
    } catch {
      // Directory doesn't exist or error reading
      return [];
    }
  }

  private async readSummaryDir(sessionDir: string, sessionKey: string): Promise<HourlySummary[]> {
    let files: string[];
    try {
      files = await readdir(sessionDir);
    } catch {
      return [];
    }

    const summaries: HourlySummary[] = [];
    const mdFiles = files.filter((f) => f.endsWith(".md"));
    for (const file of mdFiles) {
      const filePath = await resolveSafeStoragePath(sessionDir, file).catch(() => null);
      if (filePath === null) continue;

      try {
        const content = await readFile(filePath, "utf-8");
        summaries.push(...this.parseSummaryFile(content, sessionKey, file));
      } catch {
        // Skip unreadable summary files.
      }
    }

    return summaries;
  }

  private parseSummaryFile(content: string, sessionKey: string, filename: string): HourlySummary[] {
    const summaries: HourlySummary[] = [];

    // Extract date from filename (YYYY-MM-DD.md)
    const dateMatch = filename.match(/^(\d{4}-\d{2}-\d{2})\.md$/);
    if (!dateMatch) return summaries;
    const dateStr = dateMatch[1];

    // Split by hour sections
    const hourSections = content.split(/\n## (\d{2}):00\n/);

    // First element is the header, skip it
    for (let i = 1; i < hourSections.length; i += 2) {
      const hourStr = hourSections[i];
      const sectionContent = hourSections[i + 1] || "";

      // Parse bullets
      const bullets: string[] = [];
      const lines = sectionContent.split("\n");
      let turnCount = 0;

      let inTopics = false;
      let sawExtendedTopicsHeader = false;
      for (const line of lines) {
        if (line.startsWith("### Topics")) {
          inTopics = true;
          sawExtendedTopicsHeader = true;
          continue;
        }
        if (line.startsWith("### ") && !line.startsWith("### Topics")) {
          inTopics = false;
        }
        const bulletMatch = line.match(/^- (.+)$/);
        if (bulletMatch) {
          // For extended format, only treat topic bullets as recall bullets.
          if (!sawExtendedTopicsHeader || inTopics) bullets.push(bulletMatch[1]);
        }
        const turnMatch = line.match(/\((\d+) turns?\)/);
        if (turnMatch) turnCount = parseInt(turnMatch[1], 10);
      }

      if (bullets.length > 0) {
        summaries.push({
          hour: `${dateStr}T${hourStr}:00:00.000Z`,
          sessionKey,
          bullets,
          turnCount,
          generatedAt: "", // Not stored in file, not needed for recall
        });
      }
    }

    return summaries;
  }

  // Format summaries for recall injection
  formatForRecall(summaries: HourlySummary[], maxCount: number): string {
    if (summaries.length === 0) return "";

    const limited = summaries.slice(0, maxCount);
    const lines: string[] = [`## Recent Activity (last ${limited.length} hours)`];

    for (const summary of limited) {
      const hourStr = summary.hour.slice(11, 16); // HH:MM
      for (const bullet of summary.bullets) {
        lines.push(`- ${hourStr}: ${bullet}`);
      }
    }

    return lines.join("\n");
  }

  // Main entry point for cron job
  async runHourly(): Promise<HourlySummarizerRunStats> {
    log.debug("running hourly summary generation");

    // Get active sessions from transcript. The scan outcome is kept LOCAL to
    // this invocation (review round 2): shared instance state would let two
    // concurrent runHourly calls cross-report each other's timestamps.
    const scan = await this.getActiveSessions();
    const sessions = scan.sessionKeys;
    let sessionsWithEntries = 0;
    let summariesWritten = 0;

    for (const sessionKey of sessions) {
      // Calculate the hour we want to summarize (previous hour)
      const now = new Date();
      const hourStart = new Date(now.getTime() - 60 * 60 * 1000);
      hourStart.setMinutes(0, 0, 0);
      const hourEnd = new Date(hourStart.getTime() + 60 * 60 * 1000);

      // Get entries for this session in the target hour
      const entries = await this.getTranscriptEntries(sessionKey, hourStart, hourEnd);

      if (entries.length === 0) {
        log.debug(`no transcript entries for ${sessionKey} at ${hourStart.toISOString()}`);
        continue;
      }
      sessionsWithEntries += 1;

      // Generate and save summary
      const summary = await this.generateSummary(sessionKey, hourStart, entries);
      if (summary) {
        await this.saveSummary(summary);
        summariesWritten += 1;
        log.info(`generated hourly summary for ${sessionKey} (${entries.length} turns)`);
      }
    }

    return {
      sessionsConsidered: sessions.length,
      sessionsWithEntries,
      summariesWritten,
      // Staleness signal (issue #2783): newest entry across the whole
      // store, from the same scan getActiveSessions already performs.
      staleStore:
        scan.newestEntryTimestamp !== null &&
        Date.now() - new Date(scan.newestEntryTimestamp).getTime() > STALE_STORE_MS,
      newestEntryTimestamp: scan.newestEntryTimestamp,
      scanFailed: scan.scanFailed,
    };
  }

  // Get list of active sessions from the transcript directory, plus the
  // scan bookkeeping runHourly reports: newest entry timestamp (staleness
  // signal) and whether the scan itself FAILED. A failed scan must not be
  // reported as an empty store — those are different incidents (review
  // round 2).
  private async getActiveSessions(): Promise<{
    sessionKeys: string[];
    newestEntryTimestamp: string | null;
    scanFailed: boolean;
  }> {
    const transcriptDir = await resolveSafeStoragePath(this.config.memoryDir, "transcripts").catch(() => null);
    if (transcriptDir === null) {
      return { sessionKeys: [], newestEntryTimestamp: null, scanFailed: false };
    }

    const sessionKeys = new Set<string>();
    let newestEntryTimestamp: string | null = null;
    let newestEntryTimeMs = Number.NaN;
    let fileReadFailed = false;
    const collect = async (transcriptPath: string): Promise<void> => {
      try {
        const raw = await readFile(transcriptPath, "utf-8");
        for (const line of raw.split("\n")) {
          if (!line.trim()) continue;
          try {
            const entry = JSON.parse(line) as TranscriptEntry;
            if (typeof entry.sessionKey === "string" && entry.sessionKey.length > 0) {
              sessionKeys.add(entry.sessionKey);
            }
            // Compare parsed epoch values, never strings: a malformed
            // timestamp in a hand-edited file must not poison the staleness
            // signal with a lexically-maximal garbage value (review).
            if (typeof entry.timestamp === "string") {
              const timeMs = new Date(entry.timestamp).getTime();
              if (Number.isFinite(timeMs) && (Number.isNaN(newestEntryTimeMs) || timeMs > newestEntryTimeMs)) {
                newestEntryTimeMs = timeMs;
                newestEntryTimestamp = entry.timestamp;
              }
            }
          } catch {
            // ignore malformed transcript lines
          }
        }
      } catch (err) {
        // ENOENT is a concurrently-deleted file — ignore. Any other read
        // failure (permissions, I/O) means the store is partially UNREADABLE:
        // mark the scan failed so the caller warns instead of reporting an
        // empty store (review round 3).
        if ((err as NodeJS.ErrnoException)?.code !== "ENOENT") {
          fileReadFailed = true;
        }
      }
    };

    try {
      const typeEntries = await readdir(transcriptDir, { withFileTypes: true });
      for (const typeEnt of typeEntries) {
        if (!typeEnt.isDirectory()) continue;
        const typeDir = await resolveSafeStoragePath(transcriptDir, typeEnt.name).catch(() => null);
        if (typeDir === null) continue;
        const idEntries = await readdir(typeDir, { withFileTypes: true });
        for (const idEnt of idEntries) {
          if (!idEnt.isDirectory()) continue;
          const chanDir = await resolveSafeStoragePath(typeDir, idEnt.name).catch(() => null);
          if (chanDir === null) continue;
          const files = (await readdir(chanDir)).filter((f) => f.endsWith(".jsonl")).sort();
          for (const file of files) {
            const transcriptPath = await resolveSafeStoragePath(chanDir, file).catch(() => null);
            if (transcriptPath === null) continue;
            await collect(transcriptPath);
          }
        }
      }
      return {
        sessionKeys: Array.from(sessionKeys),
        newestEntryTimestamp,
        scanFailed: fileReadFailed,
      };
    } catch (err) {
      // ENOENT on the root is a never-written store — an EMPTY store, not a
      // scan failure (those are different incidents).
      const code = (err as NodeJS.ErrnoException)?.code;
      if (code === "ENOENT") {
        return { sessionKeys: [], newestEntryTimestamp: null, scanFailed: false };
      }
      log.warn(`transcript scan failed: ${err}`);
      return { sessionKeys: [], newestEntryTimestamp: null, scanFailed: true };
    }
  }

  // Get transcript entries for a session within a time range
  private async getTranscriptEntries(sessionKey: string, startTime: Date, endTime: Date): Promise<TranscriptEntry[]> {
    // Shared session-identity layer (issue #1496, rule #22). Arbitrary keys
    // route to `session/<hash>`; legacy `agent:<id>:...` keep their paths. The
    // shared helper also supplies the read-back-only candidate dirs (mirrors
    // TranscriptManager) so legacy `other/default` AND old `parts.length >= 3`
    // data stays discoverable here too.
    const paths = sessionStoragePaths(sessionKey);

    try {
      const transcriptRoot = path.join(this.config.memoryDir, "transcripts");
      const candidateDirs = new Set(
        [paths.dir, paths.alternateDir, paths.legacyDir, ...paths.readbackDirs].filter(
          (dir): dir is string => typeof dir === "string" && dir.length > 0
        )
      );
      const entries: TranscriptEntry[] = [];
      // Dedup identical raw rows that a partially-applied migration may have
      // left in both the primary dir and a read-back dir (issue #1496, cursor
      // review). Exact raw JSONL line is the stable identity.
      const seenRawLines = new Set<string>();

      // Read all daily transcript files in the directory
      for (const candidateDir of candidateDirs) {
        const transcriptDir = await resolveSafeStoragePath(transcriptRoot, candidateDir).catch(() => null);
        if (transcriptDir === null) continue;

        const files = await readdir(transcriptDir).catch(() => []);
        for (const file of files) {
          if (!file.endsWith(".jsonl")) continue;

          const transcriptPath = await resolveSafeStoragePath(transcriptDir, file).catch(() => null);
          if (transcriptPath === null) continue;

          try {
            const content = await readFile(transcriptPath, "utf-8");
            const lines = content.trim().split("\n");

            for (const line of lines) {
              if (!line.trim()) continue;
              try {
                const entry = JSON.parse(line) as TranscriptEntry;
                const entryTime = new Date(entry.timestamp).getTime();

                if (
                  entry.sessionKey === sessionKey &&
                  entryTime >= startTime.getTime() &&
                  entryTime < endTime.getTime() &&
                  !seenRawLines.has(line)
                ) {
                  seenRawLines.add(line);
                  entries.push(entry);
                }
              } catch {
                // Skip malformed lines
              }
            }
          } catch {
            // Skip unreadable files
          }
        }
      }

      return entries;
    } catch {
      return [];
    }
  }
}

