  // ───────────────────────────────────────────────────────────────────────
  // Consolidation scheduling
  // ───────────────────────────────────────────────────────────────────────

  /**
   * Maybe trigger a background consolidation pass after an extraction.
   * Counted + interval gated so a burst of extractions does not fan into a
   * burst of consolidation passes. The consolidation runner itself is
   * passed in as a callback because it lives on the orchestrator (LLM +
   * storage dependency surface) and is not owned by this module.
   */
  maybeScheduleConsolidation(
    nonZeroExtraction: boolean,
    runConsolidation: () => Promise<unknown>,
  ): void {
    if (nonZeroExtraction) this.nonZeroExtractionsSinceConsolidation += 1;
    if (
      this.deps.config.consolidationRequireNonZeroExtraction &&
      !nonZeroExtraction
    ) {
      return;
    }
    if (
      this.nonZeroExtractionsSinceConsolidation <
      this.deps.config.consolidateEveryN
    ) {
      return;
    }

    const now = Date.now();
    if (
      now - this.lastConsolidationRunAtMs <
      this.deps.config.consolidationMinIntervalMs
    ) {
      return;
    }
    if (this.disposed || this.consolidationRunPromise) return;

    this.lastConsolidationRunAtMs = now;
    this.nonZeroExtractionsSinceConsolidation = 0;
    this.consolidationRunPromise = Promise.resolve()
      .then(runConsolidation)
      .catch((err) => {
        log.error("background consolidation failed", err);
      })
      .finally(() => {
        this.consolidationRunPromise = null;
      });
  }

  /** Whether a background consolidation pass is currently running. Exposed so
   *  the orchestrator's waitForConsolidationIdle can poll idle state without
   *  owning the cadence state (issue #1526 PR1). */
  isConsolidationInFlight(): boolean {
    return this.consolidationRunPromise !== null;
  }

  /** Whether a debounced QMD maintenance pass is armed and waiting for the
   *  debounce timer. Exposed so drain/teardown diagnostics (e.g. the bench
   *  adapter) can observe scheduler idle state after the #1526 PR1 extraction
   *  moved this flag off the orchestrator. */
  isQmdMaintenancePending(): boolean {
    return this.qmdMaintenancePending;
  }

  /** Whether a QMD maintenance pass is currently running (singleflight guard).
   *  Exposed for drain/teardown diagnostics (see isQmdMaintenancePending). */
  isQmdMaintenanceInFlight(): boolean {
    return this.qmdMaintenanceInFlight;
  }
  // ───────────────────────────────────────────────────────────────────────
  // QMD maintenance scheduling (debounced + singleflight)
  // ───────────────────────────────────────────────────────────────────────

  /** Internal: queue a debounced QMD maintenance pass; false when nothing could be armed. */
  private requestQmdMaintenance(): boolean {
    if (!this.deps.getQmd().isAvailable()) return false;
    if (!resolveQmdCapabilities(this.deps.config).qmdMaintenance) return false;

    this.qmdMaintenancePending = true;
    if (this.qmdMaintenanceTimer) return true;

    this.qmdMaintenanceTimer = setTimeout(() => {
      this.qmdMaintenanceTimer = null;
      this.runQmdMaintenance().catch((err) =>
        log.debug(`background qmd maintenance failed: ${err}`),
      );
    }, this.deps.config.qmdMaintenanceDebounceMs);
    return true;
  }

  /**
   * Like a maintenance request, but resolves true only once a pass that started
   * after it completed successfully. False when nothing could be armed (QMD
   * unavailable or maintenance off), the pass failed, or dispose() abandoned it,
   * so a caller that must not lose the re-index keeps owing it.
   */
  requestQmdMaintenanceCompletion(namespace?: string): Promise<boolean> {
    if (this.disposed || !this.requestQmdMaintenance()) return Promise.resolve(false);
    return this.qmdCompletion.wait(namespace);
  }

  /**
   * Public entrypoint for tool-driven QMD maintenance requests.
   * Routes through existing debounced/singleflight maintenance controls.
   */
  requestQmdMaintenanceForTool(reason: string): void {
    try {
      this.requestQmdMaintenance();
    } catch (err) {
      const msg = err instanceof Error ? err.message : String(err);
      log.warn(`qmd maintenance request failed (${reason}): ${msg}`);
    }
    // Lifecycle-ledger auto-compaction (#1910) must run independently of QMD.
    // When QMD is unavailable or its maintenance capability is off,
    // requestQmdMaintenance() short-circuits and runQmdMaintenance() never
    // fires — so a compaction check living only in that path would never run.
    // Fire it here on every maintenance request (throttled, size-gated,
    // single-flighted, never awaited, never throws) so a QMD-off deployment
    // still bounds the lifecycle ledger.
    void this.maybeCompactMemoryLifecycleLedger().catch((err) =>
      log.debug(`lifecycle ledger auto-compaction check failed (non-fatal): ${err}`),
    );
    // Memory-projection scheduled rebuild (#2119): interval-throttled,
    // single-flighted, never awaited, never throws — see the module docblock.
    void maybeRebuildMemoryProjectionScheduled({
      config: this.deps.config,
      getStorage: this.deps.getStorage,
      state: this.projectionRebuild,
    }).catch((err) =>
      log.debug(`memory projection scheduled rebuild check failed (non-fatal): ${err}`),
    );
  }

  /** Internal: run a single QMD maintenance pass under singleflight guard. */
  async runQmdMaintenance(): Promise<void> {
    if (this.qmdMaintenanceInFlight) return;
    if (!this.qmdMaintenancePending) return;
    this.qmdMaintenanceInFlight = true;
    this.qmdMaintenancePending = false;
    // Waiters claimed here are served by THIS pass; later requests wait for the next.
    const settle = this.qmdCompletion.claim();
    let served = false;
    let deferred = false;
    // Set only by the namespace-aware branch; absent means the pass outcome applies to every waiter.
    let ranNamespaces: Set<string> | undefined;

    try {
      if (resolveNamespaceCapabilities(this.deps.config).namespaces) {
        // Include cataloged dynamic namespaces, not just the configured set
        // (NGnei), but run through the namespace-aware maintenance planner so
        // each namespace is budgeted, lock-protected, and status-recorded
        // independently (issue #1500).
        const plan = await this.namespaceMaintenancePlan("qmd");
        const now = Date.now();
        const lastEmbedAtByNamespace = this.lastQmdEmbedAtMsByNamespace;
        const dueEmbedNamespaces = (namespaces: string[]): string[] => {
          if (!resolveQmdCapabilities(this.deps.config).qmdAutoEmbed) return [];
          return namespaces.filter(
            (namespace) =>
              now - (lastEmbedAtByNamespace.get(namespace) ?? 0) >=
              this.deps.config.qmdEmbedMinIntervalMs,
          );
        };
        const markEmbedded = (namespaces: string[]): void => {
          if (namespaces.length === 0) return;
          for (const namespace of namespaces) {
            lastEmbedAtByNamespace.set(namespace, now);
          }
          this.lastQmdEmbedAtMs = now;
        };
        const summary = await runNamespaceMaintenanceBatchPlan(
          this.deps.config,
          plan,
          async (candidates) => {
            const namespaces = candidates.map((candidate) => candidate.namespace);
            const embedNamespaces = dueEmbedNamespaces(namespaces);
            let result: NamespaceUpdateResult;
            try {
              result = await this.deps.namespaceSearchRouter.updateNamespacesDetailed(
                namespaces,
                undefined,
                { strict: true },
              );
            } catch (error) {
              if (
                embedNamespaces.length > 0 &&
                qmdMaintenanceSkipReasonForError(error) === "throttled"
              ) {
                await this.deps.namespaceSearchRouter.embedNamespaces(embedNamespaces, {
                  strict: true,
                });
                markEmbedded(embedNamespaces);
              }
              throw error;
            }
            if (result.backendCount <= 0) {
              throw new Error("no eligible QMD backend for selected namespaces");
            }
            if (result.eligibleNamespaces.length !== namespaces.length) {
              const eligible = new Set(result.eligibleNamespaces);
              const missing = namespaces.filter(
                (namespace) => !eligible.has(namespace),
              );
              throw new Error(
                `QMD backend ineligible for selected namespaces (${missing.length})`,
              );
            }
            if (embedNamespaces.length > 0) {
              await this.deps.namespaceSearchRouter.embedNamespaces(embedNamespaces, {
                strict: true,
              });
              markEmbedded(embedNamespaces);
            }
            return { itemCount: result.backendCount };
          },
          this.deps.namespaceCatalog,
          {
            skipReasonForError: qmdMaintenanceSkipReasonForError,
          },
        );
        // Namespaces skipped for a TRANSIENT reason (budget_exhausted, lock_held) were not covered
        // by this pass. They are covered once they ran in this or an earlier pass of the same
        // request, so a deployment with more namespaces than the cycle budget still converges.
        // Permanent skip reasons describe namespaces this deployment never re-indexes.
        const covered = this.qmdCoveredNamespaces;
        const ran = new Set<string>();
        ranNamespaces = ran;
        const before = covered.size;
        for (const status of summary.statuses) {
          if (status.state !== "ran") continue;
          covered.add(status.namespace);
          ran.add(status.namespace);
        }
        const uncovered = summary.statuses.some(
          (status) =>
            status.state === "skipped" &&
            (status.reason === "budget_exhausted" || status.reason === "lock_held") &&
            !covered.has(status.namespace),
        );
        // The batch runner drops namespace "*" skips from the statuses, so a failed catalog read
        // is only visible on the plan: cataloged namespaces were never discovered this pass.
        const catalogReadFailed = plan.skipped.some((skip) => skip.reason === "catalog_read_failed");
        served = summary.ran > 0 && summary.failed === 0 && !uncovered && !catalogReadFailed;
        // Partial progress keeps the waiters for another pass; no progress, a failure or a failed
        // catalog read ends the request unserved so the next start asks again.
        deferred = !served && summary.failed === 0 && !catalogReadFailed && covered.size > before && !this.disposed;
      } else {
        const qmd = this.deps.getQmd();
        // Plain update() is fail-open on every backend: it resolves when the min-interval gate,
        // failure backoff or an early exit suppressed it, and when it errored. Only the variants
        // that report whether an update ran count (updateCompleted, else QMD's updateStrict).
        if (qmd.updateCompleted) {
          try {
            served = await qmd.updateCompleted();
          } catch (err) {
            log.debug(`qmd maintenance update did not run: ${err}`);
          }
        } else if (qmd.updateStrict) {
          try {
            await qmd.updateStrict();
            served = true;
          } catch (err) {
            log.debug(`qmd maintenance update did not run: ${err}`);
          }
        } else {
          await qmd.update();
        }
        const now = Date.now();
        if (
          resolveQmdCapabilities(this.deps.config).qmdAutoEmbed &&
          now - this.lastQmdEmbedAtMs >= this.deps.config.qmdEmbedMinIntervalMs
        ) {
          await this.deps.getQmd().embed();
          this.lastQmdEmbedAtMs = now;
        }
      }
      // Note: a successful QMD update/embed clears the global QMD result caches
      // itself (QmdClient.runUpdateForCollection / runEmbedForCollection), so
      // this scheduler does not invalidate them here — every refresh path
      // (direct update, namespace router, wearable/OpenClaw sync) funnels through
      // the backend and clears centrally. A no-op pass (throttle/unavailable/
      // backoff) does not advance lastUpdateRanAtMs, so it leaves caches warm
      // (#1904, Codex/Cursor).
    } finally {
      settle(served, deferred, ranNamespaces);
      if (!deferred) this.qmdCoveredNamespaces.clear();
      this.qmdMaintenanceInFlight = false;
      if (deferred) this.qmdMaintenancePending = true;
      if (this.qmdMaintenancePending) {
        this.requestQmdMaintenance();
      }
      // Lifecycle-ledger auto-compaction is triggered from
      // requestQmdMaintenanceForTool (every maintenance request, QMD or not),
      // so it does not need to be re-fired here (issue #1910).
    }
  }

  /**
   * Size-gated, throttled, single-flighted auto-compaction of the lifecycle
   * ledger (issue #1910). Compacts the root ledger AND every namespace ledger
   * (`memoryDir/namespaces/<token>/state/`) when namespaces are enabled, each
   * through the existing `rebuildMemoryLifecycleLedger` so the
   * archive-then-atomic-write discipline is reused verbatim. `0` disables.
   *
   * Before compacting, drain EVERY target's durable pending-append spill (the
   * root ledger AND each namespace ledger) so a lifecycle event that spilled
   * while a prior long rewrite held the lock is folded back into its ledger and
   * cannot be silently lost (issue #2033). Draining is independent of both the
   * compaction threshold and the min-interval throttle: targets are enumerated
   * through the same safe (symlink/containment-checked) resolver and every
   * eligible queue is drained BEFORE any throttle return, so a namespace spill
   * created after the previous pass never waits out the whole interval.
   * Encrypted-store safety is preserved — a keyed target drains through its
   * secure StorageManager, a filesystem-fallback target only through a plaintext
   * context that refuses encrypted ledgers/spills. Work stays bounded: one
   * target enumeration plus a bounded per-queue drain.
   *
   * The min-interval throttle timestamp advances ONLY after real, fully
   * successful compaction work: a failed OR deferred target leaves the throttle
   * un-advanced so it stays eligible on the next maintenance pass, while
   * `lifecycleCompactionInFlight` still prevents overlapping runs. A "deferred"
   * target is oversized but could not be compacted because its encrypted ledger
   * has no unlocked secure store — arming the throttle for it would suppress the
   * retry of that still-oversized ledger for the whole interval (#2033).
   *
   * The min-interval throttle is bypassed for one case: an encrypted ledger
   * already at/over the whole-file decrypt cap is unreadable, so it must be
   * clamped on the next pass rather than wait out the interval. Ordinary
   * below-cap (or plaintext) targets stay throttled (#2033).
   */
  private async maybeCompactMemoryLifecycleLedger(): Promise<void> {
    // Enumerate every lifecycle target (root + namespaces) through the safe,
    // containment-checked resolver, and fold each one's durable pending spill
    // back into its ledger BEFORE any threshold or throttle return (#2033). A
    // spill created after the previous pass must land promptly even while
    // compaction is throttled or disabled; draining is bounded per queue and
    // never bypasses encrypted-store safety.
    const targets = await this.resolveLifecycleCompactionTargets();
    for (const target of targets) {
      await this.drainPendingForTarget(target);
    }

    const threshold = this.deps.config.memoryLifecycleLedgerCompactBytes;
    if (!(threshold > 0)) return; // 0 / negative / non-numeric disables compaction.
    if (this.lifecycleCompactionInFlight) return;
    const now = Date.now();
    if (
      now - this.lastLifecycleCompactionAtMs <
        this.deps.config.memoryLifecycleLedgerCompactMinIntervalMs &&
      !(await this.hasOverCapEncryptedLifecycleLedger(targets))
    ) {
      // Throttled: no ordinary target is due yet. The exception is an encrypted
      // ledger already at/over the whole-file decrypt cap — it is unreadable, so
      // the global min-interval must not defer clamping it for a whole interval.
      // The guard above lets such a target through immediately (compaction then
      // clamps it via the cap-aware effective threshold) while ordinary
      // below-cap targets stay throttled (#2033).
      return;
    }
    // The over-cap probe above awaits, so a second maintenance request can pass
    // the early `lifecycleCompactionInFlight` guard and reach here during that
    // await. Recheck the guard immediately before claiming it — otherwise two
    // racing requests both see an over-cap ledger and run duplicate 400MB-class
    // compactions/backups back-to-back (#2033). The set below is synchronous
    // with this recheck (no await between), so exactly one caller wins.
    if (this.lifecycleCompactionInFlight) return;
    this.lifecycleCompactionInFlight = true;
    try {
      let compacted = 0;
      let failed = 0;
      let deferred = 0;
      for (const target of targets) {
        const outcome = await this.compactLifecycleLedgerTarget(target, threshold);
        if (outcome === "compacted") compacted += 1;
        else if (outcome === "failed") failed += 1;
        else if (outcome === "deferred") deferred += 1;
      }
      // Arm the throttle only when at least one ledger actually compacted AND
      // nothing failed AND nothing was deferred. A below-threshold no-op
      // (compacted === 0), any failure, or a deferred oversized ledger (locked
      // encrypted store, still pending) leaves the throttle where it was so the
      // next pass retries the untouched targets (#2033).
      if (compacted > 0 && failed === 0 && deferred === 0) {
        this.lastLifecycleCompactionAtMs = now;
      }
    } finally {
      this.lifecycleCompactionInFlight = false;
    }
  }

  /**
   * True when any lifecycle target's ledger is encrypted at rest AND its
   * on-disk size is at/over the whole-file decrypt cap. Such a ledger is already
   * unreadable (the secure reader refuses at/over the cap), so it must reach the
   * bounded compaction path on the next maintenance pass regardless of the
   * global min-interval throttle — otherwise the throttle could keep an
   * unreadable ledger un-clamped for a whole interval (#2033). Ordinary
   * below-cap or plaintext targets never match, so the throttle still governs
   * them. A stat/probe failure yields "no forced target" and is left to the
   * normal compaction path, which classifies it as failed and retries.
   */
  private async hasOverCapEncryptedLifecycleLedger(
    targets: Array<{ memoryDir: string; storage?: StorageManager }>,
  ): Promise<boolean> {
    for (const target of targets) {
      const ledgerPath = path.join(target.memoryDir, "state", "memory-lifecycle-ledger.jsonl");
      let size: number;
      try {
        size = (await stat(ledgerPath)).size;
      } catch {
        continue; // absent/unstattable — nothing to force here.
      }
      if (size < this.lifecycleLedgerMaxBytes) continue;
      try {
        if (await probeEncryptedRegularFileHeader(ledgerPath)) return true;
      } catch {
        continue; // probe failure — the normal compaction path reports it.
      }
    }
    return false;
  }

  /**
   * Drain one compaction target's durable pending spill. A catalog-backed
   * target folds through its secure StorageManager; a filesystem-fallback
   * target (no storage) folds through a path-scoped plaintext context that
   * refuses encrypted ledgers/spills so a keyless drain never downgrades an
   * encrypted ledger (issue #2033).
   */
  private async drainPendingForTarget(
    target: { memoryDir: string; storage?: StorageManager },
  ): Promise<void> {
    if (target.storage) {
      await this.drainPendingLifecycleAppends(target.storage);
    } else {
      await drainPendingLifecycleAppendsForPath(target.memoryDir);
    }
  }

  /** Drain a target's durable pending lifecycle-append spill into its ledger
   *  (issue #2033); non-fatal and a fast no-op when nothing is pending. */
  private async drainPendingLifecycleAppends(storage: StorageManager | undefined): Promise<void> {
    if (!storage) return;
    try {
      await storage.drainPendingMemoryLifecycleEvents();
    } catch (err) {
      log.debug(`lifecycle pending drain failed (non-fatal): ${err}`);
    }
  }

  /**
   * Enumerate the lifecycle ledgers to consider for compaction: the root
   * (through the secure-configured root storage when available) plus every
   * cataloged namespace ledger when namespaces are enabled. Deduplicated by
   * resolved storage dir so a namespace that collapses onto the root is not
   * compacted twice. Namespace resolution failures are non-fatal.
   */
  private async resolveLifecycleCompactionTargets(): Promise<
    Array<{ memoryDir: string; storage?: StorageManager }>
  > {
    const targets: Array<{ memoryDir: string; storage?: StorageManager }> = [];
    const seen = new Set<string>();
    const addTarget = (memoryDir: string, storage?: StorageManager): void => {
      const key = path.resolve(memoryDir);
      if (seen.has(key)) return;
      seen.add(key);
      targets.push({ memoryDir, storage });
    };

    const rootStorage = this.deps.getStorage?.();
    addTarget(rootStorage ? rootStorage.dir : this.deps.config.memoryDir, rootStorage);

    const resolveNamespaceStorage = this.deps.storageForNamespace;
    if (resolveNamespaceStorage && this.deps.namespaceCatalog?.enabled) {
      let records: NamespaceRecord[] = [];
      try {
        records = await this.deps.namespaceCatalog.listNamespaces();
      } catch (err) {
        log.debug(`lifecycle compaction: namespace enumeration failed (non-fatal): ${err}`);
      }
      for (const record of records) {
        const namespace = record.namespace.trim();
        if (!namespace) continue;
        try {
          const storage = await resolveNamespaceStorage(namespace);
          addTarget(storage.dir, storage);
        } catch (err) {
          log.debug(
            `lifecycle compaction: storage resolve failed for namespace ${namespace} (non-fatal): ${err}`,
          );
        }
      }
    }

    // Filesystem fallback (codex P2): when namespaces are enabled but the
    // catalog is disabled (namespaceCatalogEnabled=false) — or a namespace is
    // not yet cataloged — the catalog walk above finds nothing, yet per-namespace
    // ledgers still grow under <memoryDir>/namespaces/<token>/state/. Scan that
    // base directly so those ledgers are still bounded. Deduped by resolved dir,
    // so a namespace already added via the catalog is not compacted twice.
    if (resolveNamespaceCapabilities(this.deps.config).namespaces) {
      const namespacesBase = path.join(this.deps.config.memoryDir, "namespaces");
      // Symlink/traversal containment (issue #2033 codex P2): a symlinked
      // <memoryDir>/namespaces (or a symlinked child) must not redirect the scan
      // — and later backup/ledger rewrites — outside memoryDir. Resolve the
      // memory root and the scan base through realpath, reject a symlinked or
      // escaping base, and skip any symlinked/escaping child, mirroring the
      // memory-store walkers' hardening (utils/path-containment).
      let memoryDirReal: string;
      try {
        memoryDirReal = await realpath(this.deps.config.memoryDir);
        const baseStat = await lstat(namespacesBase);
        if (baseStat.isSymbolicLink() || !baseStat.isDirectory()) {
          throw new Error("namespaces base is a symlink or not a directory");
        }
        assertPathInsideRoot(memoryDirReal, await realpath(namespacesBase), namespacesBase);
      } catch (err) {
        if (!isErrnoCode(err, "ENOENT")) {
          log.debug(`lifecycle compaction: namespaces base rejected (non-fatal): ${err}`);
        }
        return targets;
      }
      let entries: Dirent[] = [];
      try {
        entries = await readdir(namespacesBase, { withFileTypes: true });
      } catch (err) {
        if (!isErrnoCode(err, "ENOENT")) {
          log.debug(`lifecycle compaction: namespaces dir scan failed (non-fatal): ${err}`);
        }
      }
      for (const entry of entries.sort((a, b) => a.name.localeCompare(b.name))) {
        if (!entry.isDirectory() || entry.isSymbolicLink()) continue;
        const childPath = path.join(namespacesBase, entry.name);
        try {
          assertPathInsideRoot(memoryDirReal, await realpath(childPath), childPath);
        } catch (err) {
          log.debug(`lifecycle compaction: skipping out-of-root namespace dir ${childPath}: ${err}`);
          continue;
        }
        // Resolve the namespace's secure-store-aware storage so an encrypted
        // fallback ledger compacts through the correct root key/context instead
        // of deferring forever behind a keyless plaintext StorageManager (#2033
        // thread PRRT_kwDORJXyws6SE5fv). The on-disk dir name is EITHER a
        // namespace identity TOKEN (ns-<hex>) OR a legacy raw namespace dir name
        // written before tokenization (namespaces/<name>/). Decode a token back
        // to its canonical namespace; treat a non-token dir as a raw namespace
        // only when it is a safe route namespace (isSafeRouteNamespace), so a
        // garbage/traversal dir name is never handed to the resolver. Passing the
        // raw token to the resolver would re-tokenize an already-tokenized value
        // and (for namespaces longer than 30 bytes) exceed the router's 64-char
        // safe-route limit, so the resolver throws and the encrypted over-cap
        // ledger defers forever — hence decode first. Resolve the route namespace
        // and accept the keyed storage only when it roots at THIS dir: the secure
        // store keys one master key per memory ROOT (not per namespace), the
        // router routes a token to namespaces/<token>/ and an existing legacy raw
        // name to its namespaces/<name>/ root, so a correct resolve returns THIS
        // childPath; anything else is an unexpected re-route we refuse (keeping
        // namespace isolation and never compacting the wrong ledger). A dir that
        // neither decodes nor is a safe raw namespace, or no resolver wired
        // (focused tests / plaintext deployments), leaves the keyless target
        // standing: the rebuild chokepoint still refuses to downgrade an
        // encrypted ledger, so plaintext behavior holds.
        const decodedNamespace = namespaceIdentityFromToken(entry.name);
        const routeNamespace =
          decodedNamespace !== null
            ? decodedNamespace
            : isSafeRouteNamespace(entry.name)
              ? entry.name
              : null;
        if (resolveNamespaceStorage && routeNamespace !== null) {
          try {
            const storage = await resolveNamespaceStorage(routeNamespace);
            if (path.resolve(storage.dir) === path.resolve(childPath)) {
              addTarget(storage.dir, storage);
              continue;
            }
            log.debug(
              `lifecycle compaction: fallback resolver routed ${childPath} to ${storage.dir}; `
              + "using keyless target",
            );
          } catch (err) {
            log.debug(
              `lifecycle compaction: fallback storage resolve failed for ${childPath} (non-fatal): ${err}`,
            );
          }
        }
        addTarget(childPath);
      }
    }
    return targets;
  }

  /**
   * Compact one lifecycle ledger when it is at/over `threshold`. Returns
   * `"skipped"` (absent or below threshold — nothing to do), `"compacted"`
   * (rewritten and verified under the read/decrypt cap), `"failed"`
   * (rebuild/probe threw, or the rewritten ledger is STILL over the cap — an
   * ineffective compaction — non-fatal, retried next pass), or `"deferred"`
   * (oversized but its encrypted ledger cannot be rewritten because no unlocked
   * secure store is available — real work still pending, so the caller must NOT
   * arm the throttle). #2033: a deferred/failed target is distinct from a genuine
   * no-op so one namespace compacting cannot suppress retries for another, and
   * an over-cap rewrite never arms the throttle.
   */
  private async compactLifecycleLedgerTarget(
    target: { memoryDir: string; storage?: StorageManager },
    threshold: number,
  ): Promise<"skipped" | "compacted" | "failed" | "deferred"> {
    const ledgerPath = path.join(target.memoryDir, "state", "memory-lifecycle-ledger.jsonl");
    let size = 0;
    try {
      size = (await stat(ledgerPath)).size;
    } catch (err) {
      if (isErrnoCode(err, "ENOENT")) return "skipped"; // absent — nothing to compact yet.
      log.warn(
        `lifecycle ledger size check failed (non-fatal) for ${target.memoryDir}: ${err}`,
      );
      return "failed";
    }
    // #2033 finding (1): an encrypted ledger becomes unreadable once its on-disk
    // size reaches the whole-file decrypt cap (the reader refuses at/over it), so
    // the effective compaction trigger for an encrypted target is clamped to that
    // cap even when the configured threshold is LARGER — otherwise a ledger that
    // grows past the cap but stays below a bigger threshold would never compact
    // and stay permanently unreadable. Plaintext streaming is unaffected at any
    // size, so a plaintext target keeps the configured threshold. The cheap
    // pre-check skips anything below the smaller of the two before paying for the
    // extra lstat/open the encryption probe costs.
    if (size < Math.min(threshold, this.lifecycleLedgerMaxBytes)) return "skipped";
    let encrypted: boolean;
    try {
      encrypted = await probeEncryptedRegularFileHeader(ledgerPath);
    } catch (err) {
      log.warn(`lifecycle ledger encryption probe failed (non-fatal) for ${ledgerPath}: ${err}`);
      return "failed";
    }
    const effectiveThreshold = encrypted
      ? Math.min(threshold, this.lifecycleLedgerMaxBytes)
      : threshold;
    if (size < effectiveThreshold) return "skipped";
    // No plaintext rewrite of an encrypted-at-rest ledger (#2033): rebuilding an
    // encrypted ledger without an unlocked secure StorageManager would either
    // fail the preserve-read (locked store) or downgrade the ledger to plaintext.
    // Report "deferred" (NOT "skipped"): the ledger is over threshold and still
    // needs compaction, so the throttle must stay un-armed and retry once a key
    // is available — a "skipped" here would let another target's success arm the
    // throttle and suppress this pending work for the whole interval (#2033).
    if (encrypted && !(target.storage?.isSecureStoreUnlocked() ?? false)) {
      log.warn(
        `lifecycle ledger at ${ledgerPath} is encrypted at rest but no unlocked secure `
        + `storage is available; deferring auto-compaction to avoid a plaintext rewrite. `
        + `Run 'remnic rebuild-memory-lifecycle-ledger --write' after unlocking.`,
      );
      return "deferred";
    }
    // #2033 findings (2)+(4): the rewrite budget bounds the PLAINTEXT payload, but
    // an encrypted-at-rest target adds a fixed secure-store envelope on disk.
    // Reserve that envelope (plus one byte) from the plaintext budget so the
    // encrypted file lands STRICTLY below the reader's refusal cap and the
    // post-write check — which stats the on-disk (encrypted) size against the cap
    // — cannot fail forever on a plaintext budget that equals the cap (the
    // endless-retry bug). Base this on whether the REPLACEMENT will be encrypted
    // (the storage write mode), NOT only on the current file header: a
    // plaintext ledger rewritten under `secureStoreEncryptOnWrite` with the key
    // set becomes encrypted, so it needs the reserve even though its current
    // header is plaintext (#2033 write-mode finding).
    const replacementEncrypted =
      encrypted || (target.storage?.willEncryptStateWrites() ?? false);
    const plaintextBudget = replacementEncrypted
      ? this.lifecycleLedgerMaxBytes - SECURE_STORE_ENVELOPE_OVERHEAD_BYTES - 1
      : this.lifecycleLedgerMaxBytes - 1;
    try {
      const result = await rebuildMemoryLifecycleLedger({
        memoryDir: target.memoryDir,
        dryRun: false,
        storage: target.storage,
        // Background compaction must not lose append-only history that
        // frontmatter cannot reconstruct (issue #1910); the manual CLI repair
        // rebuild now preserves and bounds identically (#2033).
        preserveExistingEvents: true,
        // Bound the PLAINTEXT rewrite to a budget that reserves the secure-store
        // envelope, so the on-disk ledger (plaintext, or plaintext+envelope when
        // encrypted) is strictly below the read/decrypt cap; overflow lands in
        // the verbatim backup (#2033 findings 2+4).
        maxLedgerBytes: plaintextBudget,
      });
      // Verify the rewritten ledger is actually bounded. A compaction that left
      // the ledger at/over the read/decrypt cap is ineffective (the ledger would
      // be unreadable) — report "failed" so the throttle stays un-armed and the
      // next pass retries rather than declaring success (#2033).
      let rewrittenSize = 0;
      try {
        rewrittenSize = (await stat(ledgerPath)).size;
      } catch (err) {
        log.warn(`lifecycle ledger post-compaction size check failed (non-fatal) for ${target.memoryDir}: ${err}`);
        return "failed";
      }
      if (rewrittenSize >= this.lifecycleLedgerMaxBytes) {
        log.warn(
          `lifecycle ledger auto-compaction ineffective for ${target.memoryDir}: rewritten `
          + `ledger is ${rewrittenSize}B, still at/over the ${this.lifecycleLedgerMaxBytes}-byte `
          + `read/decrypt cap; leaving the throttle un-armed to retry.`,
        );
        return "failed";
      }
      if (result.rewritten === false) {
        // No-op pass (#2033 thread PRRT_kwDORJXyws6SExst): a preserving rebuild
        // would reproduce the current ledger byte-for-byte, so it skipped the
        // backup+rewrite. The ledger stays over the trigger but under the cap;
        // report "compacted" so the throttle still arms (nothing more can be
        // done until the ledger grows), which stops the periodic re-archive/
        // rewrite churn the review flagged — the archive no longer grows.
        log.debug(
          `lifecycle ledger already compact for ${target.memoryDir}: ${rewrittenSize}B, `
          + `no rewrite needed (throttle armed to avoid re-archiving an unchanged ledger).`,
        );
      } else {
        log.info(
          `lifecycle ledger auto-compacted (${target.memoryDir}): ${size}B -> `
          + `${rewrittenSize}B, ${result.rebuiltRows} rows `
          + `(${result.preservedAppendOnlyRows ?? 0} append-only preserved, `
          + `${result.archivedOverflowRows ?? 0} overflow archived), `
          + `backup=${result.backupPath ?? "none"}`,
        );
      }
      return "compacted";
    } catch (err) {
      log.warn(
        `lifecycle ledger auto-compaction failed (non-fatal) for ${target.memoryDir}: ${err}`,
      );
      return "failed";
    }
  }

  /** Build the namespace-aware maintenance plan for one job. */
  private async namespaceMaintenancePlan(
    jobName: string,
  ): Promise<NamespaceMaintenancePlan> {
    return planNamespaceMaintenance(this.deps.config, {
      jobName,
      catalog: this.deps.namespaceCatalog,
    });
  }

  // ───────────────────────────────────────────────────────────────────────
  // Lifecycle
  // ───────────────────────────────────────────────────────────────────────

  /**
   * Clear any pending debounce timer and drain the activity sync scheduler.
   * Called from the orchestrator's destroy() so a late tick does not fire on a
   * torn-down instance and no in-flight activity tick keeps writing after
   * teardown. Async: awaits the scheduler's abort+drain before resolving.
   */
  async dispose(): Promise<void> {
    this.disposed = true;
    terminateScheduledProjectionRebuilds(this.projectionRebuild);
    const consolidationDrain = this.consolidationRunPromise;
    // The registrar latches teardown first (so a draining tick's onRun cannot
    // re-arm QMD maintenance) and aborts+drains the sync. Capture its drain and
    // await it last so the rest of teardown runs while the aborted tick unwinds.
    const activityDrain = this.activityRegistrar.dispose();
    const locationDrain = this.locationAutoSync?.stop() ?? Promise.resolve();
    this.locationAutoSync = null; const weeklyDrain = this.compoundingWeekly?.stop() ?? Promise.resolve(); this.compoundingWeekly = null;
    if (this.qmdMaintenanceTimer) {
      clearTimeout(this.qmdMaintenanceTimer);
      this.qmdMaintenanceTimer = null;
    }
    this.qmdMaintenancePending = false;
    this.qmdCompletion.abandon();
    await activityDrain;
    await locationDrain; await weeklyDrain;
    // Belt-and-suspenders: clear anything a late tick armed before the latch.
    if (this.qmdMaintenanceTimer) {
      clearTimeout(this.qmdMaintenanceTimer);
      this.qmdMaintenanceTimer = null;
    }
    this.qmdMaintenancePending = false;
    if (consolidationDrain) await consolidationDrain;
  }
}

import { log } from "../logger.js";
import type { ExtractionFailureClass } from "../types.js";

export interface ProviderBreakerConfig {
  readonly failureThreshold: number;
  readonly cooldownMs: number;
  readonly authCooldownMs: number;
}

export interface ProbeOwnerToken {
  readonly __probeOwner: true;
}

export interface ProviderBreakerSnapshot {
  readonly state: "closed" | "open" | "half_open";
  readonly openUntilMs: number;
  readonly consecutiveFailures: number;
  readonly lastReason: string;
}

export interface ProbeAcquisition {
  /** True when the attempt is suppressed (breaker open, or the half-open
   *  probe is owned by another attempt). */
  readonly suppressed: boolean;
  /** True when THIS attempt owns the single half-open probe and must
   *  terminate it via {@link failure}/{@link success} (with its token), or
   *  release it via {@link releaseProbe} on any early exit (deadline, abort,
   *  throw). */
  readonly probe: boolean;
  /** Opaque ownership token; only the matching token settles or releases the
   *  probe, so attempts that bypass the gate (forced extractions) can never
   *  release another attempt's in-flight probe. */
  readonly token?: ProbeOwnerToken;
}

/**
 * Provider circuit breaker with single-flight half-open probe OWNERSHIP
 * (codex P2 on #3311): under extractionQueueConcurrency > 1 several sessions
 * can pass an expired `open` breaker in the same window, and a wall-clock
 * reservation either expires under a live long provider attempt (600s
 * timeouts) or pins the breaker when an attempt dies without settling. So the
 * probe is OWNED, not timed: exactly one attempt holds it from the
 * open→half_open flip until its terminal `failure()`/`success()`, and any
 * early exit releases it explicitly. A released-but-unfinished probe lets the
 * next attempt re-probe; a retry backoff still throttles that namespace.
 */
export class ProviderCircuitBreaker {
  private consecutiveFailures = 0;
  private openUntilMs = 0;
  private state: ProviderBreakerSnapshot["state"] = "closed";
  private lastReason = "";
  private probeHeld = false;
  private probeToken: ProbeOwnerToken | null = null;

  acquire(now: number): ProbeAcquisition {
    if (now < this.openUntilMs) return { suppressed: true, probe: false };
    if (this.state === "open") {
      this.state = "half_open";
      this.probeHeld = true;
      const token: ProbeOwnerToken = { __probeOwner: true };
      this.probeToken = token;
      this.logTransition();
      return { suppressed: false, probe: true, token }; // THIS attempt is the probe.
    }
    if (this.state === "half_open") {
      if (this.probeHeld) return { suppressed: true, probe: false };
      this.probeHeld = true; // previous owner released without settling; re-probe.
      const token: ProbeOwnerToken = { __probeOwner: true };
      this.probeToken = token;
      return { suppressed: false, probe: true, token };
    }
    return { suppressed: false, probe: false };
  }

  /** Release an owned probe on an attempt that exits without a terminal
   *  outcome (deadline, abort, throw). Only the matching owner releases;
   *  idempotent; state stays half_open so the next attempt re-probes. */
  releaseProbe(token?: ProbeOwnerToken): void {
    if (token === undefined || this.probeToken !== token) return;
    this.probeToken = null;
    this.probeHeld = false;
  }

  failure(cls: ExtractionFailureClass, now: number, config: ProviderBreakerConfig, probeToken?: ProbeOwnerToken): void {
    // Only the probe OWNER's failure settles the half-open probe: a failure
    // from an attempt that bypassed acquire (forced extraction) must not
    // release another attempt's in-flight probe or masquerade as its result.
    const owned = probeToken !== undefined && this.probeToken === probeToken;
    if (owned) {
      this.probeToken = null;
      this.probeHeld = false;
    }
    this.consecutiveFailures += 1;
    const trip =
      // An unowned auth_config failure (forced extraction) must not reopen
      // over a held half-open probe — same ownership rule as the threshold
      // term; the auth cooldown still applies once the probe settles.
      (cls === "auth_config" && (this.state !== "half_open" || owned)) ||
      // A failed half-open probe re-opens immediately (standard breaker
      // semantics). Without this, an auth_config-opened breaker (which trips
      // below the threshold) would get stuck half_open after a transient
      // probe failure and stop suppressing (cursor review).
      (owned && this.state === "half_open") ||
      // PRRT_kwDORJXyws6zxG6V: an unowned (forced-extraction) failure must
      // not cross the threshold while another attempt owns the half-open
      // probe — reopening here would strand the owner's token and let the
      // next cooldown mint a second concurrent probe. The failure count and
      // retry bookkeeping still accumulate for when the state leaves
      // half_open.
      (this.state !== "half_open" && this.consecutiveFailures >= config.failureThreshold);
    if (!trip) return;
    const cooldown = cls === "auth_config" ? config.authCooldownMs : config.cooldownMs;
    this.openUntilMs = now + Math.max(0, cooldown);
    this.lastReason = cls;
    if (this.state !== "open") {
      this.state = "open";
      this.logTransition();
    }
  }

  success(probeToken?: ProbeOwnerToken): void {
    const wasDisturbed =
      this.state !== "closed" || this.consecutiveFailures > 0 || this.openUntilMs > 0;
    if (!wasDisturbed) return;
    // PRRT_kwDORJXyws6zxG6u: while a half-open probe is held, only its OWNER
    // may settle it. An unowned (forced-extraction) success must not clear
    // another run's probe or close the breaker mid-probe — the next ordinary
    // acquisition could then start a second concurrent probe.
    if (this.probeHeld && !(probeToken !== undefined && this.probeToken === probeToken)) return;
    const wasOpen = this.state !== "closed";
    this.probeToken = null;
    this.probeHeld = false;
    this.consecutiveFailures = 0;
    this.openUntilMs = 0;
    this.lastReason = "";
    this.state = "closed";
    if (wasOpen) this.logTransition();
  }

  snapshot(): ProviderBreakerSnapshot {
    return {
      state: this.state,
      openUntilMs: this.openUntilMs,
      consecutiveFailures: this.consecutiveFailures,
      lastReason: this.lastReason,
    };
  }

  private logTransition(): void {
    // Once per state change (not per attempt) — AGENTS.md observability rule.
    log.warn("extraction: provider circuit breaker transition", {
      state: this.state,
      consecutiveFailures: this.consecutiveFailures,
      lastReason: this.lastReason,
      openUntilMs: this.openUntilMs,
    });
  }
}

/**
 * Tier migration coordinator — extracted from the orchestrator (issue #1526).
 *
 * Owns the hot/cold tier-migration lifecycle for a single cycle:
 *   - gating (config flags, in-flight guard, min-interval throttle)
 *   - budget selection (compounding override or config default)
 *   - candidate scanning across hot + cold storage
 *   - promotion/demotion execution via TierMigrationExecutor
 *   - status recording through TierMigrationStatusStore
 *
 * The orchestrator constructs one instance and exposes it as the public
 * `tierMigrationCoordinator` field. CLI commands and maintenance paths call
 * `getStatus`/`runCycle` directly; the orchestrator keeps a private
 * `runTierMigrationCycle` wrapper for the extraction-run dependency.
 * Storage is passed per-call so extraction (which writes to a namespace-
 * scoped storage) and maintenance/manual (which use the default storage)
 * share one coordinator.
 */

import path from "node:path";

import { resolveQmdCapabilities } from "../capabilities.js";
import { type CompoundingEngine, defaultTierMigrationCycleBudget } from "../compounding/engine.js";
// StorageManager type comes from the package barrel (type-only) so this
// module does not add a direct storage.ts import (#1533 ratchet).
import type { StorageManager } from "../index.js";
import { log } from "../logger.js";
import type {
  TierMigrationCycleSummary,
  TierMigrationStatusSnapshot,
  TierMigrationStatusStore,
} from "../recall-state.js";
import type { SearchBackend } from "../search/port.js";
import { TierMigrationExecutor } from "../tier-migration.js";
import { type MemoryTier, decideTierTransition } from "../tier-routing.js";
import type { MemoryFile, PluginConfig } from "../types.js";
import { type UtilityRuntimeValues, applyUtilityPromotionRuntimePolicy } from "../utility-runtime.js";

/** Dependencies injected by the orchestrator. All stable references or live
 *  accessors (the orchestrator reassigns `qmd` to NoopSearchBackend and
 *  `utilityRuntimeValues` after async init, so those arrive as getters). */
export interface TierMigrationCoordinatorDeps {
  config: PluginConfig;
  /** Live accessor — the orchestrator reassigns this.qmd to NoopSearchBackend
   *  after construction when the collection is missing. */
  getQmd: () => SearchBackend;
  tierMigrationStatus: TierMigrationStatusStore;
  /** Live accessor — loaded asynchronously during init, null before that. */
  getUtilityRuntimeValues: () => UtilityRuntimeValues | null;
  /** Live accessor — undefined when compounding is disabled. */
  getCompounding: () => CompoundingEngine | undefined;
  /** Constructs the cold-tier StorageManager for a given parent memory dir.
   *  Injected so this module owns no direct storage.ts import (#1533). */
  createColdStorage: (parentDir: string) => StorageManager;
}

/**
 * Coordinates a single tier-migration cycle. Owns the in-flight guard and
 * last-run timestamp that previously lived as private orchestrator fields.
 */
export class TierMigrationCoordinator {
  private inFlight = false;
  private lastRunAtMs = 0;

  constructor(private readonly deps: TierMigrationCoordinatorDeps) {}

  /** Whether a migration cycle is currently executing (diagnostics). */
  isInFlight(): boolean {
    return this.inFlight;
  }

  /** Latest status snapshot (delegates to the status store). */
  getStatus(): TierMigrationStatusSnapshot {
    return this.deps.tierMigrationStatus.get();
  }

  /**
   * Run one tier-migration cycle. Behavior-preserving move of the
   * orchestrator's former `runTierMigrationCycle`.
   */
  async runCycle(
    storage: StorageManager,
    trigger: "extraction" | "maintenance" | "manual",
    options?: {
      dryRun?: boolean;
      limitOverride?: number;
      force?: boolean;
    }
  ): Promise<TierMigrationCycleSummary> {
    const { config, tierMigrationStatus } = this.deps;
    const dryRun = options?.dryRun === true;
    const persistSkipped = options?.force === true || trigger === "manual";
    if (!resolveQmdCapabilities(config).qmdTierMigration && options?.force !== true) {
      const skipped: TierMigrationCycleSummary = {
        trigger,
        scanned: 0,
        migrated: 0,
        promoted: 0,
        demoted: 0,
        limit: 0,
        dryRun,
        skipped: "tier_migration_disabled",
      };
      if (persistSkipped) await tierMigrationStatus.recordCycle(skipped);
      return skipped;
    }
    if (trigger === "maintenance" && !resolveQmdCapabilities(config).qmdTierAutoBackfill && options?.force !== true) {
      const skipped: TierMigrationCycleSummary = {
        trigger,
        scanned: 0,
        migrated: 0,
        promoted: 0,
        demoted: 0,
        limit: 0,
        dryRun,
        skipped: "maintenance_backfill_disabled",
      };
      if (persistSkipped) await tierMigrationStatus.recordCycle(skipped);
      return skipped;
    }
    if (this.inFlight) {
      const skipped: TierMigrationCycleSummary = {
        trigger,
        scanned: 0,
        migrated: 0,
        promoted: 0,
        demoted: 0,
        limit: 0,
        dryRun,
        skipped: "migration_in_flight",
      };
      if (persistSkipped) await tierMigrationStatus.recordCycle(skipped);
      return skipped;
    }

    const budgetTrigger = trigger === "manual" ? "maintenance" : trigger;
    const budget =
      this.deps.getCompounding()?.tierMigrationCycleBudget(budgetTrigger) ??
      defaultTierMigrationCycleBudget(config, budgetTrigger);
    const limit = options?.limitOverride !== undefined ? Math.max(0, Math.floor(options.limitOverride)) : budget.limit;
    const nowMs = Date.now();
    if (options?.force !== true && nowMs - this.lastRunAtMs < budget.minIntervalMs) {
      const skipped: TierMigrationCycleSummary = {
        trigger,
        scanned: 0,
        migrated: 0,
        promoted: 0,
        demoted: 0,
        limit,
        dryRun,
        skipped: "min_interval",
      };
      if (persistSkipped) await tierMigrationStatus.recordCycle(skipped);
      return skipped;
    }

    const policy = applyUtilityPromotionRuntimePolicy(
      {
        enabled: resolveQmdCapabilities(config).qmdTierMigration,
        demotionMinAgeDays: config.qmdTierDemotionMinAgeDays,
        demotionValueThreshold: config.qmdTierDemotionValueThreshold,
        promotionValueThreshold: config.qmdTierPromotionValueThreshold,
      },
      this.deps.getUtilityRuntimeValues()
    );

    this.inFlight = true;
    try {
      const coldStorage = this.deps.createColdStorage(path.join(storage.dir, "cold"));
      const [hotMemories, coldMemories] = await Promise.all([storage.readAllMemories(), coldStorage.readAllMemories()]);
      const now = new Date();
      const scanLimit = Math.max(0, Math.floor(budget.scanLimit));
      const hotScanLimit = Math.min(hotMemories.length, Math.ceil(scanLimit * 0.75));
      const coldScanLimit = Math.min(coldMemories.length, Math.max(0, scanLimit - hotScanLimit));
      const toTimestamp = (memory: MemoryFile): number =>
        Date.parse(memory.frontmatter.updated ?? memory.frontmatter.created);
      const hotCandidates = hotMemories
        .map((memory) => ({ memory, tier: "hot" as MemoryTier }))
        .sort((a, b) => toTimestamp(a.memory) - toTimestamp(b.memory))
        .slice(0, hotScanLimit);
      const coldCandidates = coldMemories
        .map((memory) => ({ memory, tier: "cold" as MemoryTier }))
        .sort((a, b) => toTimestamp(b.memory) - toTimestamp(a.memory))
        .slice(0, coldScanLimit);
      const candidates = [...hotCandidates, ...coldCandidates];

      const migration = new TierMigrationExecutor({
        storage,
        qmd: this.deps.getQmd(),
        hotCollection: config.qmdCollection,
        coldCollection: config.qmdColdCollection ?? `${config.qmdCollection}-cold`,
        autoEmbed: resolveQmdCapabilities(config).qmdAutoEmbed,
      });

      let migrated = 0;
      let promoted = 0;
      let demoted = 0;
      for (const candidate of candidates) {
        if (migrated >= limit) break;
        const decision = decideTierTransition(candidate.memory, candidate.tier, policy, now);
        if (!decision.changed) continue;

        if (!dryRun) {
          const res = await migration.migrateMemory({
            memory: candidate.memory,
            fromTier: candidate.tier,
            toTier: decision.nextTier,
            reason: `${trigger}:${decision.reason}`,
          });
          if (!res.changed) continue;
        }
        migrated += 1;
        if (decision.nextTier === "cold") demoted += 1;
        if (decision.nextTier === "hot") promoted += 1;
      }

      if (!dryRun) this.lastRunAtMs = Date.now();
      log.debug(
        `tier migration cycle completed: trigger=${trigger} scanned=${candidates.length} migrated=${migrated} limit=${limit}${dryRun ? " dryRun=true" : ""}`
      );
      const summary: TierMigrationCycleSummary = {
        trigger,
        scanned: candidates.length,
        migrated,
        promoted,
        demoted,
        limit,
        dryRun,
      };
      const shouldPersistCycle = trigger === "manual" || migrated > 0;
      if (shouldPersistCycle) await tierMigrationStatus.recordCycle(summary);
      return summary;
    } catch (err) {
      this.lastRunAtMs = Date.now();
      log.warn(`tier migration cycle failed (${trigger}, fail-open): ${err}`);
      const failed: TierMigrationCycleSummary = {
        trigger,
        scanned: 0,
        migrated: 0,
        promoted: 0,
        demoted: 0,
        limit,
        dryRun,
        errorCount: 1,
      };
      await tierMigrationStatus.recordCycle(failed);
      return failed;
    } finally {
      this.inFlight = false;
    }
  }
}

/**
 * Compression-guideline learning coordinator — extracted from the
 * orchestrator (issue #1526, seam 4).
 *
 * Owns the compression-guideline learning lifecycle:
 *   - candidate computation from recorded memory-action events
 *   - optional LLM semantic refinement of the candidate
 *   - draft persistence + activation (optimizer/draft state files)
 *   - the recall section that surfaces active guidelines during recall
 *   - the consolidation-time learning pass that recomputes the draft
 *
 * The orchestrator constructs one instance and delegates the public
 * entrypoints (`optimizeCompressionGuidelines`,
 * `activateCompressionGuidelineDraft`) plus the two internal hooks
 * (`runCompressionGuidelineLearningPass`, called from the consolidation
 * loop; `buildCompressionGuidelineRecallSection`, called from the recall
 * pipeline) to it. Storage is the orchestrator's stable `this.storage`;
 * the fast-tier LLM call arrives as a callback so gateway routing stays
 * owned by the orchestrator.
 *
 * Behavior-preserving move from orchestrator.ts. No logic changes — the
 * orchestrator keeps thin delegating methods so existing call sites and
 * tests that exercise the public API continue to work.
 */

import { createHash } from "node:crypto";
import { resolveCompressionCapabilities } from "../capabilities.js";

// StorageManager type comes from the package barrel (type-only) so this
// module does not add a direct storage.ts import (#1533 ratchet).
import type { StorageManager } from "../index.js";
import type { PluginConfig, MemoryActionType, MemoryActionEvent } from "../types.js";
import { log } from "../logger.js";
import {
  computeCompressionGuidelineCandidate,
  refineCompressionGuidelineCandidateSemantically,
  renderCompressionGuidelinesMarkdown,
} from "../compression-optimizer.js";

/** Dependencies injected by the orchestrator. All stable references or
 *  live accessors. */
export interface CompressionGuidelineCoordinatorDeps {
  config: PluginConfig;
  /** Live accessor: the orchestrator's storage manager (stable post-ctor). */
  getStorage: () => StorageManager;
  /** Fast-tier LLM call used for optional semantic refinement. Routes
   *  through the gateway chain when configured — owned by the
   *  orchestrator, injected here so this module stays LLM-agnostic. */
  fastChatCompletion: (
    messages: Array<{ role: string; content: string }>,
    options: {
      temperature?: number;
      maxTokens?: number;
      timeoutMs?: number;
      operation?: string;
      priority?: "background" | "recall-critical";
    },
  ) => Promise<{ content: string } | null>;
}

/**
 * Coordinates compression-guideline learning. Holds no mutable state of
 * its own — all persistence flows through the injected storage manager.
 */
export class CompressionGuidelineCoordinator {
  constructor(private readonly deps: CompressionGuidelineCoordinatorDeps) {}

  private get storage(): StorageManager {
    return this.deps.getStorage();
  }

  private get config(): PluginConfig {
    return this.deps.config;
  }

  async optimizeCompressionGuidelines(options?: {
    dryRun?: boolean;
    eventLimit?: number;
  }): Promise<{
    enabled: boolean;
    dryRun: boolean;
    eventCount: number;
    previousGuidelineVersion: number | null;
    nextGuidelineVersion: number;
    changedRules: number;
    semanticRefinementApplied: boolean;
    persisted: boolean;
    draftContentHash: string | null;
  }> {
    const dryRun = options?.dryRun === true;
    const eventLimit =
      typeof options?.eventLimit === "number"
        ? Math.max(0, Math.floor(options.eventLimit))
        : 500;

    const [activeState, draftState] = await Promise.all([
      this.storage.readCompressionGuidelineOptimizerState(),
      this.storage.readCompressionGuidelineDraftState().catch(() => null),
    ]);
    const previousState =
      draftState &&
      ((activeState?.guidelineVersion ?? 0) < draftState.guidelineVersion ||
        (activeState?.guidelineVersion ?? 0) === draftState.guidelineVersion)
        ? draftState
        : activeState;

    if (!resolveCompressionCapabilities(this.config).compressionGuidelineLearning) {
      return {
        enabled: false,
        dryRun,
        eventCount: 0,
        previousGuidelineVersion: previousState?.guidelineVersion ?? null,
        nextGuidelineVersion: previousState?.guidelineVersion ?? 0,
        changedRules: 0,
        semanticRefinementApplied: false,
        persisted: false,
        draftContentHash: null,
      };
    }

    let events = await this.storage.readMemoryActionEvents(eventLimit);
    if (eventLimit > 0) {
      let effectiveEvents = events.filter((event) => event.dryRun !== true);
      let fetchLimit = eventLimit;
      while (
        effectiveEvents.length < eventLimit &&
        events.length === fetchLimit
      ) {
        fetchLimit = Math.min(fetchLimit * 2, fetchLimit + 1000);
        if (fetchLimit <= events.length) break;
        events = await this.storage.readMemoryActionEvents(fetchLimit);
        effectiveEvents = events.filter((event) => event.dryRun !== true);
      }
      events = effectiveEvents.slice(-eventLimit);
    }
    const generatedAt = new Date().toISOString();
    const candidate = computeCompressionGuidelineCandidate(events, {
      generatedAtIso: generatedAt,
      previousState,
    });
    if (candidate.eventCounts.total === 0) {
      return {
        enabled: true,
        dryRun,
        eventCount: 0,
        previousGuidelineVersion: previousState?.guidelineVersion ?? null,
        nextGuidelineVersion: previousState?.guidelineVersion ?? 0,
        changedRules: 0,
        semanticRefinementApplied: false,
        persisted: false,
        draftContentHash: null,
      };
    }
    const refinedCandidate =
      await refineCompressionGuidelineCandidateSemantically(candidate, {
        enabled: resolveCompressionCapabilities(this.config).compressionGuidelineSemanticRefinement,
        timeoutMs: this.config.compressionGuidelineSemanticTimeoutMs,
        runRefinement: async (baseline) => {
          const prompt = [
            "You refine compression policy suggestions conservatively.",
            "Return JSON only in this shape:",
            '{"updates":[{"action":"summarize_node","delta":0.02,"confidence":"medium","note":"..."}]}',
            "Constraints:",
            "- Keep updates sparse and conservative.",
            "- delta must stay between -0.15 and 0.15.",
            "- Only include actions present in the input.",
            "Input candidate:",
            JSON.stringify(baseline),
          ].join("\n");

          const response = await this.deps.fastChatCompletion(
            [
              {
                role: "system",
                content: "Respond with strict JSON only. No markdown.",
              },
              { role: "user", content: prompt },
            ],
            {
              temperature: 0.1,
              maxTokens: 400,
              operation: "compression_guideline_semantic_refinement",
              priority: "background",
            },
          );

          return this.parseCompressionSemanticRefinement(
            response?.content ?? "",
          );
        },
      });

    const content = renderCompressionGuidelinesMarkdown(refinedCandidate);
    const contentHash = createHash("sha256").update(content).digest("hex");
    const semanticRefinementApplied =
      JSON.stringify(refinedCandidate.ruleUpdates) !==
      JSON.stringify(candidate.ruleUpdates);
    const changedRules = refinedCandidate.ruleUpdates.filter(
      (rule) => rule.delta !== 0,
    ).length;

    if (!dryRun) {
      await this.storage.writeCompressionGuidelineDraft(content);
      await this.storage.writeCompressionGuidelineDraftState({
        version: refinedCandidate.optimizerVersion,
        updatedAt: refinedCandidate.generatedAt,
        sourceWindow: refinedCandidate.sourceWindow,
        eventCounts: refinedCandidate.eventCounts,
        guidelineVersion: refinedCandidate.guidelineVersion,
        contentHash,
        activationState: "draft",
        actionSummaries: refinedCandidate.actionSummaries,
        ruleUpdates: refinedCandidate.ruleUpdates,
      });
    }

    return {
      enabled: true,
      dryRun,
      eventCount: candidate.eventCounts.total,
      previousGuidelineVersion: previousState?.guidelineVersion ?? null,
      nextGuidelineVersion: refinedCandidate.guidelineVersion,
      changedRules,
      semanticRefinementApplied,
      persisted: !dryRun,
      draftContentHash: dryRun ? null : contentHash,
    };
  }

  async activateCompressionGuidelineDraft(options?: {
    expectedContentHash?: string;
    expectedGuidelineVersion?: number;
  }): Promise<{
    enabled: boolean;
    activated: boolean;
    guidelineVersion: number | null;
    reason?:
      | "disabled"
      | "missing_draft"
      | "expected_revision_required"
      | "content_hash_mismatch"
      | "guideline_version_mismatch"
      | "draft_changed";
  }> {
    if (!resolveCompressionCapabilities(this.config).compressionGuidelineLearning) {
      return {
        enabled: false,
        activated: false,
        guidelineVersion: null,
        reason: "disabled",
      };
    }

    const draftState = await this.storage.readCompressionGuidelineDraftState();
    if (!draftState) {
      return {
        enabled: true,
        activated: false,
        guidelineVersion: null,
        reason: "missing_draft",
      };
    }

    const expectedContentHash = options?.expectedContentHash?.trim();
    const expectedGuidelineVersion = options?.expectedGuidelineVersion;

    if (
      (!expectedContentHash || expectedContentHash.length === 0) &&
      typeof expectedGuidelineVersion !== "number"
    ) {
      return {
        enabled: true,
        activated: false,
        guidelineVersion: null,
        reason: "expected_revision_required",
      };
    }

    if (expectedContentHash && draftState.contentHash !== expectedContentHash) {
      return {
        enabled: true,
        activated: false,
        guidelineVersion: null,
        reason: "content_hash_mismatch",
      };
    }

    if (
      typeof expectedGuidelineVersion === "number" &&
      draftState.guidelineVersion !== expectedGuidelineVersion
    ) {
      return {
        enabled: true,
        activated: false,
        guidelineVersion: null,
        reason: "guideline_version_mismatch",
      };
    }

    const activated = await this.storage.activateCompressionGuidelineDraft({
      ...(expectedContentHash ? { expectedContentHash } : {}),
      ...(typeof expectedGuidelineVersion === "number"
        ? { expectedGuidelineVersion }
        : {}),
    });
    return {
      enabled: true,
      activated,
      guidelineVersion: activated ? draftState.guidelineVersion : null,
      ...(activated ? {} : { reason: "draft_changed" as const }),
    };
  }

  /** Consolidation-time hook: recompute the draft from recent events. */
  async runCompressionGuidelineLearningPass(): Promise<void> {
    if (!resolveCompressionCapabilities(this.config).compressionGuidelineLearning) return;
    try {
      const result = await this.optimizeCompressionGuidelines({
        dryRun: false,
        eventLimit: 500,
      });
      log.info(
        `compression guideline learning updated (${result.eventCount} events)`,
      );
    } catch (err) {
      log.warn(`compression guideline learning failed (ignored): ${err}`);
    }
  }

  /** Recall-time hook: surface active guidelines as a recall section. */
  async buildCompressionGuidelineRecallSection(): Promise<string | null> {
    if (!resolveCompressionCapabilities(this.config).contextCompressionActions) return null;
    if (!resolveCompressionCapabilities(this.config).compressionGuidelineLearning) return null;

    const state = await this.storage
      .readCompressionGuidelineOptimizerState()
      .catch(() => null);
    if (!state || state.guidelineVersion <= 0) return null;

    const raw = await this.storage
      .readCompressionGuidelines()
      .catch(() => null);
    const summary = raw ? formatCompressionGuidelinesForRecall(raw, 5) : null;
    if (!summary) return null;

    return [
      "## Active Compression Guidelines",
      "",
      `Guideline version: ${state.guidelineVersion}`,
      `Updated: ${state.updatedAt}`,
      "",
      summary,
    ].join("\n");
  }

  private parseCompressionSemanticRefinement(raw: string): {
    updates: Array<{
      action: MemoryActionType;
      delta?: number;
      confidence?: "low" | "medium" | "high";
      note?: string;
    }>;
  } | null {
    if (typeof raw !== "string" || raw.trim().length === 0) return null;
    const trimmed = raw.trim();
    const start = trimmed.indexOf("{");
    const end = trimmed.lastIndexOf("}");
    if (start === -1 || end === -1 || end <= start) return null;

    try {
      const parsed = JSON.parse(trimmed.slice(start, end + 1)) as {
        updates?: Array<{
          action?: unknown;
          delta?: unknown;
          confidence?: unknown;
          note?: unknown;
        }>;
      };
      if (!Array.isArray(parsed?.updates)) return null;

      const validActions = new Set<MemoryActionType>([
        "store_episode",
        "store_note",
        "update_note",
        "create_artifact",
        "summarize_node",
        "discard",
        "link_graph",
      ]);

      const updates = parsed.updates
        .filter(
          (item) =>
            item &&
            typeof item.action === "string" &&
            validActions.has(item.action as MemoryActionType),
        )
        .map((item) => {
          const confidence: "low" | "medium" | "high" | undefined =
            item.confidence === "low" ||
            item.confidence === "medium" ||
            item.confidence === "high"
              ? item.confidence
              : undefined;
          return {
            action: item.action as MemoryActionType,
            delta:
              typeof item.delta === "number" && Number.isFinite(item.delta)
                ? item.delta
                : undefined,
            confidence,
            note: typeof item.note === "string" ? item.note : undefined,
          };
        });

      return { updates };
    } catch {
      return null;
    }
  }
}

/**
 * Format the active compression-guidelines section for recall. Extracted
 * from the orchestrator (was a module-level export there); re-exported by
 * the orchestrator barrel to preserve the public API. Pure — no state.
 */
export function formatCompressionGuidelinesForRecall(
  raw: string,
  maxLines: number = 5,
): string | null {
  if (typeof raw !== "string" || raw.trim().length === 0) return null;
  const sectionMatch = raw.match(
    // End the section at `\n## ` or end-of-string. Plain $ (not \s*$): the
    // \s* branch overlapped the lazy body and backtracked polynomially
    // (CodeQL js/polynomial-redos). Captured lines are trimmed/filtered below,
    // so trailing whitespace handling is unchanged.
    /## Suggested Guidelines\s*\n([\s\S]*?)(?:\n##\s+|$)/i,
  );
  if (!sectionMatch) return null;

  const lines = sectionMatch[1]
    .split("\n")
    .map((line) => line.trim())
    .filter((line) => line.startsWith("- "))
    .slice(0, Math.max(1, Math.floor(maxLines)));
  if (lines.length === 0) return null;

  return lines.join("\n");
}

/**
 * Semantic-consolidation coordinator — extracted from the orchestrator
 * (issue #1526, seam 5).
 *
 * Owns the semantic-consolidation lifecycle: discovering clusters of
 * similar memories, synthesizing a canonical memory per cluster via the
 * LLM (operator-aware or legacy), archiving the superseded sources, and
 * firing post-consolidation hooks (Codex materialize, peer-profile
 * reasoner).
 *
 * The orchestrator constructs one instance and delegates the internal
 * entrypoint (`runSemanticConsolidation`) to it. The public wrappers
 * (`runSemanticConsolidationNow`, `runSemanticConsolidationFanout`)
 * remain on the orchestrator as thin pass-throughs. Storage is the
 * orchestrator's stable `this.storage` (or a per-namespace override
 * passed via options); the fast-tier LLM, content-hash removal, and
 * index save arrive as callbacks so the orchestrator keeps ownership of
 * gateway routing and cross-subsystem persistence.
 *
 * Behavior-preserving move from orchestrator.ts. No logic changes — the
 * orchestrator keeps a thin delegating method so existing call sites
 * and tests that exercise the public API continue to work.
 */

import {
  findSimilarClusters,
  buildConsolidationPrompt,
  parseConsolidationResponse,
  buildOperatorAwareConsolidationPrompt,
  parseOperatorAwareConsolidationResponse,
  chooseConsolidationOperator,
  buildExtensionsBlockForConsolidation,
  materializeAfterSemanticConsolidation,
} from "../semantic-consolidation.js";
import type {
  SemanticConsolidationLlmOperator,
  SemanticConsolidationResult,
} from "../semantic-consolidation.js";
import {
  FallbackLlmClient,
  fallbackLlmRuntimeContextFromConfig,
  gatewayTaskChainOptions,
} from "../fallback-llm.js";
import { resolveIndexingCapabilities, resolveConsolidationCapabilities } from "../capabilities.js";
import { deindexMemoriesBatchAsync } from "../temporal-index-batch.js";
import { runPeerProfileReasoner } from "../peers/index.js";
import type { StorageManager } from "../index.js";
import type { LocalLlmClient } from "../local-llm.js";
import type { EmbeddingFallback } from "../embedding-fallback.js";
import type { PluginConfig, MemoryFile, AgentPersonaModelConfig } from "../types.js";
import { log } from "../logger.js";
import { composeMemoryEnvelope } from "../write-envelope.js";
import { resolveConversationContextCapabilities } from "../capabilities.js";
import { excludeSupportPassportPrivateMemories } from "../support-passport/card-projection.js";

/** Dependencies injected by the orchestrator. All stable references or
 *  live accessors. */
export interface SemanticConsolidationCoordinatorDeps {
  config: PluginConfig;
  /** Live accessor: the orchestrator's storage manager (stable post-ctor). */
  getStorage: () => StorageManager;
  /** Live accessor for the fast-tier local LLM client (falls back to main
   *  local LLM when localLlmFastEnabled is false — orchestrator ctor handles
   *  this). Injected as an accessor so tests that overwrite orchestrator.fastLlm
   *  after construction still take effect. */
  getFastLlm: () => LocalLlmClient;
  /** The embedding-fallback manager used for index cleanup on archival. */
  embeddingFallback: EmbeddingFallback;
  /** Remove a memory's content-hash entry from the storage-scoped index.
   *  Delegated to the orchestrator which owns the per-storage index map. */
  removeContentHashForMemory: (
    targetStorage: StorageManager,
    memory: MemoryFile,
    context: string,
  ) => Promise<void>;
  /** Persist all dirty content-hash indexes to disk. */
  saveContentHashIndexes: () => Promise<void>;
}

/**
 * Coordinates semantic consolidation. Holds no mutable state of its own —
 * all persistence flows through the injected storage managers and
 * callbacks.
 */
export class SemanticConsolidationCoordinator {
  constructor(private readonly deps: SemanticConsolidationCoordinatorDeps) {}

  private get config(): PluginConfig {
    return this.deps.config;
  }

  async runSemanticConsolidation(options?: {
    dryRun?: boolean;
    thresholdOverride?: number;
    force?: boolean;
    storage?: StorageManager;
  }): Promise<SemanticConsolidationResult> {
    const targetStorage = options?.storage ?? this.deps.getStorage();
    const result: SemanticConsolidationResult = {
      clustersFound: 0,
      memoriesConsolidated: 0,
      memoriesArchived: 0,
      errors: 0,
      clusters: [],
    };

    if (!resolveConsolidationCapabilities(this.config).semanticConsolidation && !options?.force) {
      log.debug("[semantic-consolidation] disabled in config");
      return result;
    }

    log.info("[semantic-consolidation] starting run");

    const allMemories = excludeSupportPassportPrivateMemories(await targetStorage.readAllMemories());
    if (allMemories.length < 10) {
      log.debug("[semantic-consolidation] too few memories, skipping");
      return result;
    }

    const threshold =
      options?.thresholdOverride ?? this.config.semanticConsolidationThreshold;
    const clusters = findSimilarClusters(allMemories, {
      threshold,
      minClusterSize: this.config.semanticConsolidationMinClusterSize,
      excludeCategories: this.config.semanticConsolidationExcludeCategories,
      maxPerRun: this.config.semanticConsolidationMaxPerRun,
    });

    result.clustersFound = clusters.length;
    result.clusters = clusters;

    if (clusters.length === 0) {
      log.info("[semantic-consolidation] no clusters found");
      return result;
    }

    log.info(`[semantic-consolidation] found ${clusters.length} cluster(s)`);

    if (options?.dryRun) {
      log.info(
        "[semantic-consolidation] dry run — skipping LLM synthesis and archival",
      );
      return result;
    }

    // Use FallbackLlmClient for LLM calls (same pattern as causal-consolidation.ts)
    // Honor semanticConsolidationModel: "auto" = primary, "fast" = local fast, or specific model
    const useGateway = this.config.modelSource === "gateway";
    const modelSetting = this.config.semanticConsolidationModel;
    if (modelSetting === "fast" && this.deps.getFastLlm() && !useGateway) {
      log.info("[semantic-consolidation] using fast local LLM for synthesis");
    }
    // Gateway routing: an explicit "fast" setting keeps the fast persona chain
    // (the operator's deliberate fast-tier choice). Otherwise route through the
    // shared task-chain resolution so taskModelChain applies to semantic
    // consolidation like every other background task (gotcha #22). Issue #1365.
    const gatewayChainOptions: { modelChain?: AgentPersonaModelConfig; agentId?: string } =
      !useGateway
        ? {}
        : modelSetting === "fast"
          ? (this.config.fastGatewayAgentId
              ? { agentId: this.config.fastGatewayAgentId }
              : this.config.gatewayAgentId
                ? { agentId: this.config.gatewayAgentId }
                : {})
          : gatewayTaskChainOptions(this.config);
    const llm = new FallbackLlmClient(
      this.config.gatewayConfig,
      fallbackLlmRuntimeContextFromConfig(this.config),
    );
    if (!llm.isAvailable(gatewayChainOptions) && !(modelSetting === "fast" && this.deps.getFastLlm() && !useGateway)) {
      log.warn(
        "[semantic-consolidation] no LLM available — skipping synthesis",
      );
      return result;
    }

    // Discover memory extensions once for all clusters (#382)
    let extensionsBlock = "";
    try {
      extensionsBlock = await buildExtensionsBlockForConsolidation(this.config);
    } catch (err) {
      log.warn(`[semantic-consolidation] extension discovery failed (non-fatal): ${err instanceof Error ? err.message : String(err)}`);
    }

    for (const cluster of clusters) {
      let canonicalWriteCompleted = false;
      try {
        // Operator-aware prompt (issue #561 PR 3): ask the LLM to pick the
        // SPLIT/MERGE/UPDATE operator alongside the canonical output.  Falls
        // back to the legacy plain-blob prompt when operator-aware
        // consolidation is explicitly disabled via config, so rollbacks stay
        // clean.
        // Use the `=== true` idiom for default-false flags (PR #632
        // review, cursor Low): sibling disabled-by-default flags like
        // `semanticConsolidationEnabled` follow the same convention,
        // while `!== false` is reserved for default-on flags.
        const operatorAwareEnabled =
          resolveConversationContextCapabilities(this.config).operatorAwareConsolidation === true;
        let prompt = operatorAwareEnabled
          ? buildOperatorAwareConsolidationPrompt(cluster)
          : buildConsolidationPrompt(cluster);
        if (extensionsBlock.length > 0) {
          prompt += "\n\n" + extensionsBlock;
        }
        const messages = [
          {
            role: "system" as const,
            content: operatorAwareEnabled
              ? 'You are a memory consolidation system. Return ONLY a JSON object with two keys, "operator" and "output". The "operator" value MUST be one of the exact strings "merge", "update", or "split" — never a pipe-separated placeholder, never prose. The "output" value is the canonical memory text.'
              : "You are a memory consolidation system. Output only the consolidated memory text.",
          },
          { role: "user" as const, content: prompt },
        ];
        const llmOpts = { temperature: 0.2, maxTokens: 2000 };

        // Route to the configured model
        let response: { content: string } | null = null;
        if (useGateway) {
          // Gateway model source — use the appropriate agent chain
          response = await llm.chatCompletion(messages, { ...llmOpts, ...gatewayChainOptions });
        } else if (modelSetting === "fast" && this.deps.getFastLlm()) {
          const fastResult = await this.deps.getFastLlm().chatCompletion(messages, {
            operation: "semantic-consolidation",
            maxTokens: llmOpts.maxTokens,
            temperature: llmOpts.temperature,
            priority: "background",
            forceDisableThinking: true,
          });
          response = fastResult ? { content: fastResult.content } : null;
        } else {
          response = await llm.chatCompletion(messages, llmOpts);
        }

        if (!response?.content) {
          log.warn(
            `[semantic-consolidation] empty LLM response for cluster in "${cluster.category}"`,
          );
          result.errors++;
          continue;
        }

        // Operator-aware parse (issue #561 PR 3).  In legacy mode we fall
        // back to the plain-text parser and derive the operator from the
        // cluster-shape heuristic so `derived_via` still lands.
        // Restricted to `SemanticConsolidationLlmOperator`
        // (split/merge/update) — `pattern-reinforcement` joined the
        // wider `ConsolidationOperator` type in #687 PR 2/4 but is
        // reserved for the maintenance job and must never be assignable
        // here (Cursor Bugbot review, PR #730).
        let canonicalContent: string;
        let operator: SemanticConsolidationLlmOperator;
        if (operatorAwareEnabled) {
          const parsed = parseOperatorAwareConsolidationResponse(
            response.content,
            cluster,
          );
          canonicalContent = parsed.output;
          operator = parsed.operator;
        } else {
          canonicalContent = parseConsolidationResponse(response.content);
          operator = chooseConsolidationOperator(cluster);
        }
        cluster.canonicalContent = canonicalContent;

        // Pick the most recent memory's metadata as the basis for lineage
        const sorted = [...cluster.memories].sort(
          (a, b) =>
            new Date(b.frontmatter.created).getTime() -
            new Date(a.frontmatter.created).getTime(),
        );
        const newest = sorted[0];
        const lineageIds = cluster.memories.map((m) => m.frontmatter.id);

        // Consolidation provenance (issue #561 PR 2+3): snapshot each
        // source memory BEFORE archiving it, collecting
        // "<relpath>:<versionId>" pointers for the new canonical memory's
        // `derived_from` frontmatter field.  Snapshots are best-effort — if
        // page-versioning is disabled (default in `config.ts`) or a single
        // source fails to snapshot we simply omit that entry rather than
        // abort the consolidation.  The `derived_via` operator is chosen
        // above (PR 3) from the LLM response or the cluster-shape
        // heuristic fallback and emitted unconditionally so consolidation
        // outputs stay identifiable even when no snapshots are captured
        // (PR #624 review feedback).
        const derivedFromEntries: string[] = [];
        for (const m of cluster.memories) {
          if (!m.path) continue;
          const entry = await targetStorage.snapshotForProvenance(m.path);
          if (entry) derivedFromEntries.push(entry);
        }

        // Write the canonical memory
        // Sealed-envelope write (issue #1989 PR4): canonical content is
        // LLM-merged and tags are unioned from stored rows — salvage so a
        // limit-violating union cannot abort consolidation (warn-logged).
        const canonicalEnvelope = composeMemoryEnvelope(
          {
            content: canonicalContent,
            category: newest.frontmatter.category,
            confidence: newest.frontmatter.confidence,
            tags: [
              ...new Set(
                cluster.memories.flatMap((m) => m.frontmatter.tags ?? []),
              ),
            ],
          },
          { source: "semantic-consolidation" },
          { salvage: true },
        );
        if (canonicalEnvelope.salvageNotes.length > 0) {
          log.warn(`semantic-consolidation write salvaged invalid fields: ${canonicalEnvelope.salvageNotes.join("; ")}`);
        }
        const { id: canonicalId, tombstoneBlocked: canonicalBlocked } = await targetStorage.writeSealedMemory(
          canonicalEnvelope,
          {
            actor: "semantic-consolidation",
            lineage: lineageIds,
            derivedFrom: derivedFromEntries.length > 0 ? derivedFromEntries : undefined,
            derivedVia: operator,
          },
        );
        if (canonicalBlocked) {
          // #1645: canonical matched a tombstone (pending_review). Don't archive
          // the sources — consolidation must never delete the only active copy.
          log.info(`[semantic-consolidation] cluster in "${cluster.category}" tombstone-blocked — keeping ${cluster.memories.length} source(s) active (pending_review ${canonicalId})`);
          continue;
        }
        canonicalWriteCompleted = true;

        result.memoriesConsolidated++;

        // Archive originals
        // Collect deindex entries and remove them in one batch rather than a full
        // index read-modify-write per archived source. Guard is preserved: entries
        // are only collected when queryAwareIndexing is on.
        const clusterDeindexBatch: Array<{ path: string; createdAt: string; tags: string[] }> = [];
        try {
          for (const m of cluster.memories) {
            const archiveResult = await targetStorage.archiveMemory(m, {
              actor: "semantic-consolidation",
              reasonCode: "semantic-consolidation",
              relatedMemoryIds: [canonicalId],
            });
            if (archiveResult) {
              // Remove from the same storage-scoped content-hash index that
              // originally deduped this memory.
              await this.deps.removeContentHashForMemory(
                targetStorage,
                m,
                "semantic-consolidation",
              );
              // Best-effort index cleanup: a failure here (e.g. on-disk index save
              // under disk-full) must NOT abort the archival loop and thereby skip
              // the catalog write touch below for an already-durable canonical write
              // (kilo NV0mh).
              try {
                await this.deps.embeddingFallback.removeFromIndex(m.frontmatter.id);
                if (
                  resolveIndexingCapabilities(this.config).queryAwareIndexing &&
                  m.path &&
                  m.frontmatter?.created
                ) {
                  clusterDeindexBatch.push({
                    path: m.path,
                    createdAt: m.frontmatter.created,
                    tags: m.frontmatter.tags ?? [],
                  });
                }
              } catch (cleanupErr) {
                log.warn(
                  `[semantic-consolidation] index cleanup failed (non-fatal): ${cleanupErr}`,
                );
              }
              result.memoriesArchived++;
            }
          }
        } finally {
          // Best-effort batch index cleanup, flushed in `finally` so sources
          // already archived on disk are de-indexed even if a later archive
          // iteration throws. Never abort the cluster (and thereby skip the
          // catalog touch in the outer `finally`) on an index write failure.
          if (clusterDeindexBatch.length > 0) {
            try {
              await deindexMemoriesBatchAsync(targetStorage.dir, clusterDeindexBatch);
            } catch (cleanupErr) {
              log.warn(
                `[semantic-consolidation] index cleanup failed (non-fatal): ${cleanupErr}`,
              );
            }
          }
        }

        log.info(
          `[semantic-consolidation] consolidated ${cluster.memories.length} memories → ${canonicalId}`,
        );
      } catch (err) {
        log.warn(
          `[semantic-consolidation] cluster processing failed: ${err instanceof Error ? err.message : String(err)}`,
        );
        result.errors++;
      } finally {
        if (canonicalWriteCompleted) {
          // Catalog write touch (issue #1499 sweep): record after the canonical
          // write and, on the happy path, after archival of superseded cluster
          // memories, so `lastWriteAt` reflects every durable mutation in this
          // consolidation (cursor NUtCK). The `finally` also covers partial
          // failures where the canonical memory was written but a later archive
          // step throws and the cluster catch continues (codex NY-dK).
          // Best-effort; namespace decoded from the storage dir since this path
          // #1522: catalog touch handled at the storage chokepoint.
        }
      }
    }

    // Save hash indexes if we modified them.
    if (result.memoriesArchived > 0) {
      await this.deps.saveContentHashIndexes().catch((err) =>
        log.warn(
          `[semantic-consolidation] content-hash index save failed: ${err}`,
        ),
      );
    }

    log.info(
      `[semantic-consolidation] complete: clusters=${result.clustersFound}, consolidated=${result.memoriesConsolidated}, archived=${result.memoriesArchived}, errors=${result.errors}`,
    );

    // #378: fire the Codex materialize post-hook so `codexMaterializeOnConsolidation`
    // actually has a runtime effect. The helper silently no-ops when the
    // feature flag or the per-trigger toggle is off, when the sentinel is
    // missing, or when nothing has changed since the previous run, so it's
    // safe to always call here. Wrapped in a try/catch because a failed
    // materialize must never abort the consolidation result — consolidation
    // is the load-bearing operation; materialization is an optional mirror.
    try {
      await materializeAfterSemanticConsolidation({
        config: this.config,
        memoryDir: targetStorage.dir,
      });
    } catch (err) {
      log.warn(
        `[semantic-consolidation] Codex materialize post-hook failed (non-fatal): ${
          err instanceof Error ? err.message : String(err)
        }`,
      );
    }

    // Issue #679 PR 2/5 — async peer profile reasoner runs as part of
    // the REM phase, immediately after semantic consolidation. Gated
    // on `peerProfileReasonerEnabled` (default false, opt-in). Wrapped
    // in a try/catch because reasoner I/O (LLM call, peer-profile
    // writes) must never abort the consolidation result. The reasoner
    // itself also defends against partial failure — see profile-reasoner.ts.
    if (resolveConversationContextCapabilities(this.config).peerProfileReasoner) {
      try {
        const peerLlm = new FallbackLlmClient(
          this.config.gatewayConfig,
          fallbackLlmRuntimeContextFromConfig(this.config),
        );
        const peerResult = await runPeerProfileReasoner({
          memoryDir: targetStorage.dir,
          enabled: true,
          llm: peerLlm,
          model: this.config.peerProfileReasonerModel,
          minInteractions: this.config.peerProfileReasonerMinInteractions,
          maxFieldsPerRun: this.config.peerProfileReasonerMaxFieldsPerRun,
          log: {
            debug: (msg) => log.debug(msg),
            info: (msg) => log.info(msg),
            warn: (msg) => log.warn(msg),
          },
        });
        log.info(
          `[peer-profile-reasoner] complete: peers=${peerResult.peersConsidered}, processed=${peerResult.peersProcessed}, fields=${peerResult.fieldsApplied}`,
        );
      } catch (err) {
        log.warn(
          `[peer-profile-reasoner] post-consolidation hook failed (non-fatal): ${
            err instanceof Error ? err.message : String(err)
          }`,
        );
      }
    }

    return result;
  }
}

/**
 * Lifecycle-policy coordinator — extracted from the orchestrator
 * (issue #1526, seam 6).
 *
 * Owns the deterministic memory-lifecycle pipeline: heat/decay scoring
 * (`runLifecyclePolicyPass`), fact archival (`runFactArchival`),
 * summarization (`runSummarization`), and topic extraction
 * (`runTopicExtraction`). Also owns the action-outcome prior builder
 * (`buildLifecycleActionPriors` / `actionOutcomePriorDelta`) that feeds
 * the lifecycle transition decider.
 *
 * The orchestrator constructs one instance and delegates the internal
 * entrypoints to it. The public wrapper (`runLifecyclePolicyNow`)
 * remains on the orchestrator as a thin pass-through. Storage is the
 * orchestrator's stable `this.storage` (or a per-namespace override
 * passed via options); the extraction engine, embedding-fallback, and
 * content-hash callbacks arrive as deps so the orchestrator keeps
 * ownership of gateway routing and cross-subsystem persistence.
 *
 * Behavior-preserving move from orchestrator.ts. No logic changes — the
 * orchestrator keeps thin delegating methods so existing call sites
 * and tests that exercise the public API continue to work.
 */

import {
  decideLifecycleTransition,
  resolveLifecycleState,
  type LifecycleSignals,
} from "../lifecycle.js";
import type { LifecycleState } from "../types.js";
import {
  resolveIndexingCapabilities,
  resolveMemoryLifecycleCapabilities,
  resolveCreationMemoryCapabilities,
} from "../capabilities.js";
import { isActiveMemoryStatus } from "../memory-lifecycle-ledger-utils.js";
import { deindexMemoriesBatchAsync } from "../temporal-index-batch.js";
import { extractTopics } from "../topics.js";
import { log } from "../logger.js";
import path from "node:path";
import { mkdir, writeFile } from "node:fs/promises";
import type { StorageManager } from "../index.js";
import type { ExtractionEngine } from "../extraction.js";
import type { EmbeddingFallback } from "../embedding-fallback.js";
import type {
  PluginConfig,
  MemoryFile,
  MemoryActionEvent,
  MemorySummary,
} from "../types.js";
import { excludeSupportPassportPrivateMemories } from "../support-passport/card-projection.js";
