/** Dependencies injected by the orchestrator. All stable references or
 *  live accessors. */
export interface LifecyclePolicyCoordinatorDeps {
  config: PluginConfig;
  /** Live accessor: the orchestrator's storage manager (stable post-ctor). */
  getStorage: () => StorageManager;
  /** The extraction engine — used for summarization. */
  extraction: ExtractionEngine;
  /** The embedding-fallback manager used for index cleanup on archival. */
  embeddingFallback: EmbeddingFallback;
  /** Effective lifecycle thresholds (promote/stale/archive). Delegated to
   *  the orchestrator which owns runtime-policy-values overlay. */
  getEffectiveLifecycleThresholds: () => {
    promoteHeatThreshold: number;
    staleDecayThreshold: number;
    archiveDecayThreshold: number;
  };
  /** Remove a memory's content-hash entry from the storage-scoped index.
   *  Delegated to the orchestrator which owns the per-storage index map. */
  removeContentHashForMemory: (
    targetStorage: StorageManager,
    memory: MemoryFile,
    context: string,
  ) => Promise<void>;
  /** Persist all dirty content-hash indexes to disk. */
  saveContentHashIndexes: () => Promise<void>;
  /** Recall-handle ring used to suppress quoted-back echo during seed graduation. */
  getHandleHistory?: () => RecallHandleHistoryStore;
}

/**
 * Coordinates the memory-lifecycle policy pipeline. Holds no mutable
 * state of its own — all persistence flows through the injected storage
 * managers and callbacks.
 */
export class LifecyclePolicyCoordinator {
  constructor(
    private readonly deps: LifecyclePolicyCoordinatorDeps,
  ) {}

  private get config(): PluginConfig {
    return this.deps.config;
  }

  // -------------------------------------------------------------------------
  // Action-outcome priors (feeds lifecycle transition decisions)
  // -------------------------------------------------------------------------

  actionOutcomePriorDelta(event: MemoryActionEvent): number {
    if (event.outcome === "failed") return -0.3;
    if (event.policyDecision === "deny") return -0.22;
    if (event.policyDecision === "defer") return -0.14;
    if (event.outcome === "skipped") return -0.1;

    if (event.outcome !== "applied") return 0;
    switch (event.action) {
      case "store_episode":
      case "store_note":
      case "update_note":
        return 0.08;
      case "create_artifact":
      case "summarize_node":
      case "link_graph":
        return 0.04;
      case "discard":
        return -0.03;
      default:
        return 0;
    }
  }

  async buildLifecycleActionPriors(
    storage: StorageManager = this.deps.getStorage(),
  ): Promise<Map<string, number>> {
    const events = await storage.readMemoryActionEvents(1200);
    if (events.length === 0) return new Map<string, number>();

    const nowMs = Date.now();
    const windowMs = 14 * 24 * 60 * 60 * 1000;
    const byMemory = new Map<
      string,
      Array<{ weightedDelta: number; weight: number }>
    >();

    for (const event of events) {
      if (
        typeof event.memoryId !== "string" ||
        event.memoryId.trim().length === 0
      )
        continue;
      const ts = Date.parse(event.timestamp);
      if (!Number.isFinite(ts)) continue;
      const ageMs = nowMs - ts;
      if (ageMs < 0 || ageMs > windowMs) continue;

      const delta = this.actionOutcomePriorDelta(event);
      if (delta === 0) continue;

      const recencyWeight = Math.max(0.2, 1 - ageMs / windowMs);
      const list = byMemory.get(event.memoryId) ?? [];
      if (list.length >= 8) list.shift();
      list.push({
        weightedDelta: delta * recencyWeight,
        weight: recencyWeight,
      });
      byMemory.set(event.memoryId, list);
    }

    const out = new Map<string, number>();
    for (const [memoryId, deltas] of byMemory.entries()) {
      if (deltas.length === 0) continue;
      const weightedSum = deltas.reduce(
        (sum, item) => sum + item.weightedDelta,
        0,
      );
      const weightTotal = deltas.reduce((sum, item) => sum + item.weight, 0);
      if (weightTotal <= 0) continue;
      const score = weightedSum / weightTotal;
      out.set(memoryId, Math.max(-0.25, Math.min(0.15, score)));
    }
    return out;
  }

  // -------------------------------------------------------------------------
  // Lifecycle policy pass (heat/decay scoring + transition)
  // -------------------------------------------------------------------------

  async runLifecyclePolicyPass(
    allMemories: MemoryFile[],
    storage: StorageManager = this.deps.getStorage(),
  ): Promise<number> {
    const now = new Date();
    const nowIso = now.toISOString();
    const countsByState: Record<LifecycleState, number> = {
      candidate: 0,
      validated: 0,
      active: 0,
      stale: 0,
      archived: 0,
    };
    const transitionCounts: Record<string, number> = {};
    let updatedCount = 0;
    let disputedCount = 0;
    let evaluatedCount = 0;
    const lifecycleCaps = resolveMemoryLifecycleCapabilities(this.config);

    const thresholds = this.deps.getEffectiveLifecycleThresholds();
    const policy = {
      promoteHeatThreshold: thresholds.promoteHeatThreshold,
      staleDecayThreshold: thresholds.staleDecayThreshold,
      archiveDecayThreshold: thresholds.archiveDecayThreshold,
      protectedCategories: this.config.lifecycleProtectedCategories,
    };
    const actionPriors = await this.buildLifecycleActionPriors(storage);

    for (const memory of excludeSupportPassportPrivateMemories(allMemories)) {
      if (
        memory.frontmatter.status === "superseded" ||
        memory.frontmatter.status === "forgotten"
      ) {
        continue;
      }
      evaluatedCount += 1;
      const currentState = resolveLifecycleState(memory.frontmatter);
      const actionPriorScore = actionPriors.get(memory.frontmatter.id);
      const signals: LifecycleSignals | undefined =
        typeof actionPriorScore === "number" &&
        Number.isFinite(actionPriorScore)
          ? { actionPriorScore }
          : undefined;
      const decision = decideLifecycleTransition(memory, policy, now, signals);
      const nextState: LifecycleState =
        memory.frontmatter.status === "archived"
          ? "archived"
          : decision.nextState;

      countsByState[nextState] += 1;
      if (memory.frontmatter.verificationState === "disputed") {
        disputedCount += 1;
      }
      if (nextState !== currentState) {
        const key = `${currentState}->${nextState}`;
        transitionCounts[key] = (transitionCounts[key] ?? 0) + 1;
      }

      const prevHeat = memory.frontmatter.heatScore;
      const prevDecay = memory.frontmatter.decayScore;
      const scoreDelta =
        Math.abs((prevHeat ?? -1) - decision.heatScore) +
        Math.abs((prevDecay ?? -1) - decision.decayScore);
      const shouldPersist =
        memory.frontmatter.lifecycleState !== nextState ||
        memory.frontmatter.heatScore === undefined ||
        memory.frontmatter.decayScore === undefined ||
        memory.frontmatter.lastValidatedAt === undefined ||
        scoreDelta >= 0.01;

      if (!shouldPersist) continue;

      const wrote = await storage.writeMemoryFrontmatter(memory, {
        lifecycleState: nextState,
        heatScore: decision.heatScore,
        decayScore: decision.decayScore,
        lastValidatedAt: nowIso,
      });
      if (wrote) updatedCount += 1;
    }

    const history = this.deps.getHandleHistory?.();
    const graduation = await runSeedGraduationPass({
      memories: allMemories,
      storage,
      config: this.config.seedGraduation,
      recalledBySession: history ? (sessionKey) => history.recent(sessionKey) : undefined,
    });
    if (graduation.promoted > 0) {
      await this.deps.saveContentHashIndexes().catch((err) =>
        log.warn(`content-hash index save failed during seed graduation: ${err}`),
      );
    }

    // Report how many memories had frontmatter rewritten so callers can record a
    // catalog write touch for lifecycle-only passes (codex NR-tS).
    if (!lifecycleCaps.lifecycleMetrics) return updatedCount;

    const total = evaluatedCount;
    const metrics = {
      generatedAt: nowIso,
      memoriesEvaluated: total,
      memoriesUpdated: updatedCount,
      countsByLifecycleState: countsByState,
      transitionCounts,
      staleRatio: total > 0 ? countsByState.stale / total : 0,
      disputedRatio: total > 0 ? disputedCount / total : 0,
      policy: {
        promoteHeatThreshold: thresholds.promoteHeatThreshold,
        staleDecayThreshold: thresholds.staleDecayThreshold,
        archiveDecayThreshold: thresholds.archiveDecayThreshold,
        protectedCategories: this.config.lifecycleProtectedCategories,
      },
    };
    const metricsPath = path.join(
      storage.dir,
      "state",
      "lifecycle-metrics.json",
    );
    await mkdir(path.dirname(metricsPath), { recursive: true });
    await writeFile(metricsPath, JSON.stringify(metrics, null, 2), "utf-8");
    return updatedCount;
  }

  // -------------------------------------------------------------------------
  // Fact archival
  // -------------------------------------------------------------------------

  /**
   * Archive old, low-importance, rarely-accessed facts (v6.0).
   * Moves eligible facts from facts/ to archive/YYYY-MM-DD/.
   * Returns the number of archived facts.
   */
  async runFactArchival(
    allMemories: MemoryFile[],
  ): Promise<number> {
    const storage = this.deps.getStorage();
    const now = Date.now();
    const ageCutoffMs = this.config.factArchivalAgeDays * 24 * 60 * 60 * 1000;
    const protectedCategories = new Set(
      this.config.factArchivalProtectedCategories,
    );
    let archivedCount = 0;
    // Collect deindex entries and remove them in one batch rather than a full
    // index read-modify-write per archived fact. Guard is preserved: entries are
    // only collected when queryAwareIndexing is enabled. The flush runs in
    // `finally` so facts already archived on disk are still de-indexed if a later
    // iteration throws; it runs exactly once and any loop error propagates after.
    const deindexBatch: Array<{ path: string; createdAt: string; tags: string[] }> = [];

    try {
      for (const memory of allMemories) {
        const fm = memory.frontmatter;

        // Skip already-archived or superseded
        if (fm.status && fm.status !== "active") continue;

        // Skip protected categories
        if (protectedCategories.has(fm.category)) continue;

        // Skip corrections (always keep)
        if (fm.category === "correction") continue;

        // Check age requirement
        const createdMs = new Date(fm.created).getTime();
        if (now - createdMs < ageCutoffMs) continue;

        // Check importance (only archive low-importance facts)
        const importanceScore = fm.importance?.score ?? 0.5;
        if (importanceScore >= this.config.factArchivalMaxImportance) continue;

        // Check access count
        const accessCount = fm.accessCount ?? 0;
        if (accessCount > this.config.factArchivalMaxAccessCount) continue;

        // All criteria met — archive
        const result = await storage.archiveMemory(memory);
        if (result) {
          // Queue de-indexing immediately after a successful archive, before
          // the secondary content-hash / embedding cleanup can throw. A fact
          // archived on disk must always be de-indexed; the finally-flush then
          // removes every queued fact even if a later step throws.
          if (
            resolveIndexingCapabilities(this.config).queryAwareIndexing &&
            memory.path &&
            memory.frontmatter?.created
          ) {
            deindexBatch.push({
              path: memory.path,
              createdAt: memory.frontmatter.created,
              tags: memory.frontmatter.tags ?? [],
            });
          }
          // Remove from the same storage-scoped content-hash index since it is
          // no longer in hot search.
          await this.deps.removeContentHashForMemory(
            storage,
            memory,
            "fact-archival",
          );
          await this.deps.embeddingFallback.removeFromIndex(memory.frontmatter.id);
          archivedCount++;
        }
      }
    } finally {
      if (deindexBatch.length > 0) {
        await deindexMemoriesBatchAsync(this.config.memoryDir, deindexBatch);
      }
    }

    // Save hash indexes if we removed any entries.
    if (archivedCount > 0) {
      await this.deps.saveContentHashIndexes().catch((err) =>
        log.warn(`content-hash index save failed during archival: ${err}`),
      );
    }

    return archivedCount;
  }

  // -------------------------------------------------------------------------
  // Summarization (Phase 4A)
  // -------------------------------------------------------------------------

  /**
   * Run memory summarization if memory count exceeds threshold (Phase 4A).
   */
  async runSummarization(
    allMemories: MemoryFile[],
  ): Promise<void> {
    const storage = this.deps.getStorage();
    // Only active memories count toward the threshold
    const activeMemories = allMemories.filter(
      (m) => isActiveMemoryStatus(m.frontmatter.status),
    );

    if (activeMemories.length < this.config.summarizationTriggerCount) {
      return;
    }

    log.info(
      `memory count (${activeMemories.length}) exceeds threshold (${this.config.summarizationTriggerCount}) — running summarization`,
    );

    // Sort by creation date, oldest first
    const sorted = activeMemories.sort(
      (a, b) =>
        new Date(a.frontmatter.created).getTime() -
        new Date(b.frontmatter.created).getTime(),
    );

    // Keep recent memories, with explicit zero handling so `slice(-0)` does not
    // accidentally keep every memory out of the summarization candidate set.
    const recentToKeep = Math.max(0, this.config.summarizationRecentToKeep);
    const toSummarize = recentToKeep > 0 ? sorted.slice(0, -recentToKeep) : sorted;

    // Filter candidates for summarization
    const candidates = toSummarize.filter((m) => {
      // Skip if protected by entity reference
      if (m.frontmatter.entityRef) return false;

      // Skip if protected by tag
      const protectedTags = this.config.summarizationProtectedTags;
      if (m.frontmatter.tags.some((t) => protectedTags.includes(t)))
        return false;

      // Skip if importance is above threshold
      const importance = m.frontmatter.importance?.score ?? 0.5;
      if (importance >= this.config.summarizationImportanceThreshold)
        return false;

      return true;
    });

    if (candidates.length < 50) {
      log.debug(
        `only ${candidates.length} candidates for summarization — skipping`,
      );
      return;
    }

    // Summarize in batches of 50
    const batchSize = 50;
    for (let i = 0; i < candidates.length; i += batchSize) {
      const batch = candidates.slice(i, i + batchSize);
      const batchData = batch.map((m) => ({
        id: m.frontmatter.id,
        content: m.content,
        category: m.frontmatter.category,
        created: m.frontmatter.created,
      }));

      const result = await this.deps.extraction.summarizeMemories(batchData);
      if (!result) continue;

      // Create summary
      const summary: MemorySummary = {
        id: `summary-${Date.now()}-${Math.random().toString(36).slice(2, 6)}`,
        createdAt: new Date().toISOString(),
        timeRangeStart: batch[0].frontmatter.created,
        timeRangeEnd: batch[batch.length - 1].frontmatter.created,
        summaryText: result.summaryText,
        keyFacts: result.keyFacts,
        keyEntities: result.keyEntities,
        sourceEpisodeIds: batch.map((m) => m.frontmatter.id),
      };

      await storage.writeSummary(summary);

      // Archive source memories
      const archived = await storage.archiveMemories(
        batch.map((m) => m.frontmatter.id),
        summary.id,
      );

      // Catalog write touch (issue #1499 sweep): summarization writes a durable
      // summary and then rewrites source-memory archive status, bypassing the
      // extraction write path. Record the touch after both mutations complete so
      // `lastWriteAt` covers the final archived-state write.
      // #1522: catalog touch handled at the storage chokepoint.

      log.info(
        `created summary ${summary.id} from ${batch.length} memories, archived ${archived}`,
      );
    }
  }

  // -------------------------------------------------------------------------
  // Topic extraction (Phase 4B)
  // -------------------------------------------------------------------------

  /**
   * Run topic extraction on all memories (Phase 4B).
   */
  async runTopicExtraction(
    allMemories: MemoryFile[],
  ): Promise<void> {
    const storage = this.deps.getStorage();
    // Only extract from active memories
    const activeMemories = allMemories.filter(
      (m) => isActiveMemoryStatus(m.frontmatter.status),
    );

    if (activeMemories.length === 0) return;

    const topics = extractTopics(
      activeMemories,
      this.config.topicExtractionTopN,
    );
    await storage.saveTopics(topics);

    log.debug(
      `extracted ${topics.length} topics from ${activeMemories.length} memories`,
    );
  }
}

/**
 * Entity synthesis coordinator — extracted from the orchestrator (issue #1526).
 *
 * Owns the entity-synthesis lifecycle: processing the queued entities whose
 * evidence has changed since their last synthesis, gathering timeline +
 * structured-section evidence, deduplicating it, batch-feeding it through the
 * fast-tier LLM to produce a compact "current truth" synthesis, and persisting
 * the result with drift/bookkeeping metadata.
 *
 * Moved here (behavior-preserving):
 *   - module-level helpers `dedupeEntitySynthesisEvidenceEntries`,
 *     `flattenStructuredSectionEvidence`, `fingerprintEntitySynthesisEvidence`
 *   - the queue-processing method, now owned by this coordinator as
 *     `processQueue` (originally the orchestrator's `processEntitySynthesisQueue`)
 *
 * The orchestrator constructs one instance and exposes it as
 * `orchestrator.entitySynthesisCoordinator`; call sites invoke `processQueue`
 * directly (issue #1800 removed the orchestrator's forwarding delegate once
 * every caller migrated). Storage is resolved per-call via the injected
 * accessor so namespace-scoped and default-namespace calls share one
 * coordinator.
 */

import { createHash } from "node:crypto";

import type { StorageManager } from "../index.js";
import {
  compareEntityTimestamps,
  fingerprintEntityStructuredFacts,
  parseEntityFile,
} from "../storage.js";
import type {
  EntityStructuredSection,
  EntityTimelineEntry,
  PluginConfig,
} from "../types.js";
import { log } from "../logger.js";
import { resolvePresentationCapabilities } from "../capabilities.js";

// ---------------------------------------------------------------------------
// Evidence helpers (moved verbatim from orchestrator.ts module scope)
// ---------------------------------------------------------------------------

/**
 * Deduplicate synthesis-evidence entries by normalized text, keeping the
 * newest and oldest timestamp per unique fact when they differ.
 */
export function dedupeEntitySynthesisEvidenceEntries(
  entries: EntityTimelineEntry[],
): EntityTimelineEntry[] {
  const dedupedEvidenceEntries: EntityTimelineEntry[] = [];
  const evidenceByFact = new Map<string, {
    newest: EntityTimelineEntry;
    oldest: EntityTimelineEntry;
  }>();

  for (const entry of entries) {
    const normalizedFact = entry.text.trim();
    if (!normalizedFact) continue;
    const existing = evidenceByFact.get(normalizedFact);
    if (!existing) {
      evidenceByFact.set(normalizedFact, { newest: entry, oldest: entry });
      continue;
    }
    if (compareEntityTimestamps(entry.timestamp, existing.newest.timestamp) > 0) {
      existing.newest = entry;
    }
    if (compareEntityTimestamps(entry.timestamp, existing.oldest.timestamp) < 0) {
      existing.oldest = entry;
    }
  }

  for (const { newest, oldest } of evidenceByFact.values()) {
    dedupedEvidenceEntries.push(newest);
    const newestKey = [
      newest.timestamp,
      newest.source ?? "",
      newest.sessionKey ?? "",
      newest.principal ?? "",
      newest.text,
    ].join("\u0000");
    const oldestKey = [
      oldest.timestamp,
      oldest.source ?? "",
      oldest.sessionKey ?? "",
      oldest.principal ?? "",
      oldest.text,
    ].join("\u0000");
    if (oldestKey !== newestKey) {
      dedupedEvidenceEntries.push(oldest);
    }
  }

  return dedupedEvidenceEntries;
}

function flattenStructuredSectionEvidence(
  sections: EntityStructuredSection[] | undefined,
): EntityTimelineEntry[] {
  return (sections ?? []).flatMap((section) =>
    section.facts
      .map((fact) => fact.trim())
      .filter((fact) => fact.length > 0)
      .map((fact) => ({
        timestamp: "",
        text: fact,
        source: `section:${section.title}`,
      })),
  );
}

function fingerprintEntitySynthesisEvidence(entity: {
  timeline: EntityTimelineEntry[];
  structuredSections?: EntityStructuredSection[];
}): string {
  const fingerprint = createHash("sha256");
  const timelineEntries = entity.timeline
    .map((entry) => [
      entry.timestamp,
      entry.source ?? "",
      entry.sessionKey ?? "",
      entry.principal ?? "",
      entry.text,
    ].join("\u0000"))
    .sort();
  const timelineEntrySeparator = String.fromCharCode(1);
  const structuredFactsSeparator = String.fromCharCode(2);
  fingerprint.update(timelineEntries.join(timelineEntrySeparator));
  fingerprint.update(structuredFactsSeparator);
  fingerprint.update(fingerprintEntityStructuredFacts(entity) ?? "");
  return fingerprint.digest("hex");
}

// ---------------------------------------------------------------------------
// Coordinator
// ---------------------------------------------------------------------------

/** Dependencies injected by the orchestrator. */
export interface EntitySynthesisCoordinatorDeps {
  config: PluginConfig;
  /** Resolve the storage manager for a namespace (or the default). */
  getStorage: (namespace?: string) => Promise<StorageManager>;
  /** Fast-tier LLM completion (same signature as Orchestrator.fastChatCompletion). */
  fastChatCompletion: (
    messages: Array<{ role: string; content: string }>,
    options: {
      temperature?: number;
      maxTokens?: number;
      timeoutMs?: number;
      operation?: string;
      priority?: "background" | "recall-critical";
    },
  ) => Promise<{ content: string } | null>;
}

/**
 * Coordinates entity synthesis refresh for queued entities. Owns the
 * evidence-gathering, dedup, batched-LLM-synthesis, and persistence logic
 * that previously lived inline in the orchestrator.
 */
export class EntitySynthesisCoordinator {
  constructor(private readonly deps: EntitySynthesisCoordinatorDeps) {}

  /**
   * Process up to `maxEntities` entities from the synthesis queue for the
   * given namespace. Returns the number of entities whose synthesis was
   * successfully refreshed.
   */
  async processQueue(
    namespace?: string,
    maxEntities: number = 5,
  ): Promise<number> {
    const { config } = this.deps;
    if (
      !resolvePresentationCapabilities(config).entitySummary
      || maxEntities <= 0
      || config.entitySynthesisMaxTokens <= 0
    ) return 0;
    const storage = await this.deps.getStorage(namespace);
    const queued = await storage.refreshEntitySynthesisQueue();
    let processed = 0;
    let attempted = 0;

    for (const entityName of queued) {
      if (attempted >= maxEntities) break;
      attempted += 1;
      try {
        const raw = await storage.readEntity(entityName);
        if (!raw) continue;
        const entity = parseEntityFile(raw, config.entitySchemas);
        const previousSynthesis = entity.synthesis || entity.summary || "";
        const sortedTimelineEntries = entity.timeline
          .slice()
          .sort((left, right) => compareEntityTimestamps(right.timestamp, left.timestamp));
        const newerTimelineEntries = sortedTimelineEntries.filter(
          (entry) =>
            !entity.synthesisUpdatedAt
            || compareEntityTimestamps(entry.timestamp, entity.synthesisUpdatedAt) > 0,
        );
        const appendedTimelineEntries = entity.synthesisTimelineCount === undefined
          ? []
          : entity.timeline.slice(Math.max(0, entity.synthesisTimelineCount));
        const structuredEvidenceEntries = flattenStructuredSectionEvidence(entity.structuredSections);
        const structuredEvidenceCount = structuredEvidenceEntries.length;
        const structuredEvidenceDigest = fingerprintEntityStructuredFacts(entity);
        const structuredEvidenceDrifted = structuredEvidenceDigest !== (entity.synthesisStructuredFactDigest?.trim() || undefined);
        const appendedStructuredEvidenceEntries = entity.synthesisStructuredFactCount === undefined
          || structuredEvidenceDrifted
          ? structuredEvidenceEntries
          : structuredEvidenceEntries.slice(Math.max(0, entity.synthesisStructuredFactCount));
        const candidateEvidenceEntries = [
          ...newerTimelineEntries,
          ...appendedTimelineEntries,
          ...appendedStructuredEvidenceEntries,
        ]
          .slice()
          .sort((left, right) => compareEntityTimestamps(right.timestamp, left.timestamp));
        const dedupedEvidenceEntries = dedupeEntitySynthesisEvidenceEntries(
          candidateEvidenceEntries.length > 0
            ? candidateEvidenceEntries
            : [...sortedTimelineEntries, ...structuredEvidenceEntries],
        );
        const chronologicalEvidenceEntries = dedupedEvidenceEntries
          .slice()
          .sort((left, right) => compareEntityTimestamps(left.timestamp, right.timestamp));
        if (chronologicalEvidenceEntries.length === 0) continue;
        const latestEvidenceTimestamp = chronologicalEvidenceEntries
          .slice()
          .reverse()
          .map((entry) => entry.timestamp?.trim() || undefined)
          .find((timestamp) => Boolean(timestamp));
        const previousSynthesisUpdatedAt = entity.synthesisUpdatedAt?.trim() || undefined;
        const nextSynthesisUpdatedAt = compareEntityTimestamps(
          latestEvidenceTimestamp,
          previousSynthesisUpdatedAt,
        ) >= 0
          ? latestEvidenceTimestamp
          : previousSynthesisUpdatedAt;
        const evidenceBatches: typeof chronologicalEvidenceEntries[] = [];
        for (let index = 0; index < chronologicalEvidenceEntries.length; index += 8) {
          evidenceBatches.push(chronologicalEvidenceEntries.slice(index, index + 8));
        }

        let nextSynthesis = previousSynthesis;
        let batchFailed = false;
        for (const evidenceEntries of evidenceBatches) {
          const evidenceText = evidenceEntries
            .map((entry) => {
              const sectionTitle = entry.source?.startsWith("section:")
                ? entry.source.slice("section:".length)
                : "";
              const metadata = [
                `timestamp=${entry.timestamp}`,
                sectionTitle ? `section=${sectionTitle}` : entry.source ? `source=${entry.source}` : "",
                entry.sessionKey ? `session=${entry.sessionKey}` : "",
                entry.principal ? `principal=${entry.principal}` : "",
              ]
                .filter(Boolean)
                .join(", ");
              return `- ${metadata}: ${entry.text}`;
            })
            .join("\n");
          const response = await this.deps.fastChatCompletion(
            [
              {
                role: "system",
                content:
                  "Rewrite the entity synthesis as compact current truth. Preserve uncertainty when evidence conflicts. Return plain text only.",
              },
              {
                role: "user",
                content: [
                  `Entity: ${entity.name} (${entity.type})`,
                  nextSynthesis ? `Previous synthesis:\n${nextSynthesis}` : "Previous synthesis: none",
                  `New evidence:\n${evidenceText}`,
                ].join("\n\n"),
              },
            ],
            {
              temperature: 0.2,
              maxTokens: config.entitySynthesisMaxTokens,
              operation: "entity_summary",
              priority: "background",
            },
          );
          const synthesis = response?.content?.trim().replace(/^["']|["']$/g, "");
          const maxSynthesisChars = Math.max(2_000, config.entitySynthesisMaxTokens * 8);
          if (!synthesis || synthesis.length < 10 || synthesis.length > maxSynthesisChars) {
            batchFailed = true;
            break;
          }
          nextSynthesis = synthesis;
        }
        if (batchFailed || nextSynthesis.length === 0) continue;
        const latestRaw = await storage.readEntity(entityName);
        if (!latestRaw) continue;
        const latestEntity = parseEntityFile(latestRaw, config.entitySchemas);
        if (
          fingerprintEntitySynthesisEvidence(latestEntity)
          !== fingerprintEntitySynthesisEvidence(entity)
        ) {
          continue;
        }
        await storage.updateEntitySynthesis(entityName, nextSynthesis, {
          entityUpdatedAt: new Date().toISOString(),
          synthesisStructuredFactDigest: structuredEvidenceDigest,
          synthesisStructuredFactCount: structuredEvidenceCount,
          synthesisTimelineCount: entity.timeline.length,
          updatedAt: nextSynthesisUpdatedAt,
        });
        processed += 1;
      } catch (err) {
        log.debug(`entity synthesis refresh failed for ${entityName}: ${err}`);
      }
    }

    return processed;
  }
}

/**
 * Recall result formatter — extracted from the orchestrator (issue #1526).
 *
 * Owns the formatting of recall search results into display sections, plus the
 * identity-continuity section assembly:
 *   - QMD result formatting (with memory handles + epistemic hedge rendering)
 *   - Specialized recall result formatters (objective-state, causal-trajectory,
 *     trust-zone, harmonic-retrieval, work-product, verified-episode,
 *     verified-semantic-rule)
 *   - Identity continuity helpers (summarizeIdentityText, formatOpenIncidentLine,
 *     trimIdentitySection) and the full buildIdentityContinuitySection builder
 *   - Module-level helpers hasIdentityRecoveryIntent and
 *     resolveEffectiveIdentityInjectionMode (only consumed here)
 *
 * Behavior-preserving move from orchestrator.ts. No logic changes — the
 * orchestrator constructs one instance and keeps thin delegating methods so
 * existing call sites and tests that exercise the private API continue to work.
 */

import { buildHandleIndexForResults } from "../recall-handles.js";
import { formatSupersededPrefix } from "../recall-state-view.js";
import path from "node:path";
import { renderAuthorityBoundContent } from "../recall-context-composition.js";
import { renderEpistemicHedge } from "../trust-score.js";
import { resolveIdentityContinuityCapabilities, resolveSecurityCapabilities } from "../capabilities.js";
import type { StorageManager } from "../index.js";
import type { ObjectiveStateSearchResult } from "../objective-state.js";
import type { CausalTrajectorySearchResult } from "../causal-trajectory.js";
import type { TrustZoneSearchResult } from "../trust-zones.js";
import type { HarmonicRetrievalResult } from "../harmonic-retrieval.js";
import type { VerifiedEpisodeResult } from "../verified-recall.js";
import type { VerifiedSemanticRuleResult } from "../semantic-rule-verifier.js";
import type { WorkProductLedgerSearchResult } from "../work-product-ledger.js";
import { trustResultFor, type TrustStageResultItem } from "../trust-score-stage.js";
import { CONNECTOR_ID_PATTERN, CONNECTOR_LABEL_MAX_LENGTH } from "../connectors/label.js";
import { isValidConnectorId } from "../connectors/index.js";
import { coerceIncludedMemories, type IncludedMemory } from "../included-memories.js";
import type {
  ContinuityIncidentRecord,
  IdentityInjectionMode,
  PluginConfig,
  QmdSearchResult,
  RecallPlanMode,
} from "../types.js";

/**
 * Issue #2183 — render the persisted `sourceConnector` carried on the result
 * (hydrated where the memory is loaded) as `[agent: <connector>]`. The value
 * reaches model-visible recall context, so it is validated against the canonical
 * persisted-ID charset (CONNECTOR_ID_PATTERN — IDs the system accepts,
 * including '.'/'_', keep their label) and TRUNCATED past CONNECTOR_LABEL_MAX
 * with an explicit marker (attribution survives; suppression would lose the
 * exact signal this PR adds). One resolver at the single render site.
 */
function renderConnectorLabel(connector: string | undefined): string | null {
  if (!isValidConnectorId(connector)) return null;
  return connector.length <= CONNECTOR_LABEL_MAX_LENGTH
    ? connector
    : `${connector.slice(0, CONNECTOR_LABEL_MAX_LENGTH - 1)}…`;
}

// ---------------------------------------------------------------------------
// Identity injection mode helpers (moved verbatim from orchestrator.ts)
// ---------------------------------------------------------------------------

export function hasIdentityRecoveryIntent(prompt: string): boolean {
  const text = typeof prompt === "string" ? prompt.toLowerCase() : "";
  if (!text) return false;
  return /\b(identity|continuity|recover(?:y|ing|ed)?|incident|drift|restore|regress(?:ion|ed|ing)?)\b/i.test(
    text,
  );
}

export function resolveEffectiveIdentityInjectionMode(options: {
  configuredMode: IdentityInjectionMode;
  recallMode: RecallPlanMode;
  prompt: string;
}): { mode: IdentityInjectionMode; shouldInject: boolean } {
  if (
    options.configuredMode === "recovery_only" &&
    !hasIdentityRecoveryIntent(options.prompt)
  ) {
    return { mode: "recovery_only", shouldInject: false };
  }
  if (options.recallMode === "minimal" && options.configuredMode === "full") {
    return { mode: "minimal", shouldInject: true };
  }
  return { mode: options.configuredMode, shouldInject: true };
}

/**
 * Render an internal (possibly absolute) result path as a memoryDir-relative
 * path for display in prompts/citations, so operator-specific filesystem paths
 * never leak into recall output and citations stay portable across machines
 * (#2020). Non-absolute or out-of-root paths are returned unchanged.
 */
export function displayResultPath(
  resultPath: string,
  memoryDir: string,
  namespace?: string,
): string {
  if (!path.isAbsolute(resultPath)) return resultPath;
  const root = path.resolve(memoryDir);
  const nsRoot = path.join(root, "namespaces");
  if (namespace && (resultPath === nsRoot || resultPath.startsWith(nsRoot + path.sep))) {
    // memoryDir/namespaces/<token>/<rel> -> "<namespace>/<rel>", the exact
    // form the citation resolver decodes back to the owning namespace.
    const afterNs = path.relative(nsRoot, resultPath).split(path.sep).slice(1).join("/");
    if (afterNs) return `${namespace}/${afterNs}`;
  }
  const rel = path.relative(root, resultPath);
  return rel && !rel.startsWith("..") && !path.isAbsolute(rel)
    ? rel.split(path.sep).join("/")
    : resultPath;
}

/**
 * Return a display-safe copy of a recall snapshot for the `includeDebug=true`
 * surface (#2077). `includedMemories[].path` is rendered namespace-relative
 * from each memory's own namespace — the same rendering `resultPaths` received
 * before the struct consolidation; a `tierExplain.sourceAnchors[]` entry
 * reuses that SAME authoritative metadata when its absolute path matches an
 * included memory's path, and otherwise falls back to the memoryDir-relative
 * on-disk form. Either way the debug flag never leaks absolute operator
 * paths, and an anchor is never attributed to a decoded (guessed) namespace —
 * an anchor carries no owner of its own. Returns a shallow copy; the input
 * snapshot is never mutated.
 */
export function displaySafeRecallSnapshot<
  T extends {
    includedMemories?: IncludedMemory[];
    memoryIds?: string[];
    resultPaths?: string[];
    resultNamespaces?: Array<string | undefined>;
    budgetsApplied?: {
      includedMemoryIds?: string[];
      includedMemoryPaths?: string[];
      includedMemoryNamespaces?: Array<string | undefined>;
    };
    tierExplain?: {
      sourceAnchors?: Array<{ path: string; lineRange?: [number, number] }>;
    };
  },
>(snapshot: T, memoryDir: string): T {
  const includedMemories = coerceIncludedMemories(snapshot).map((memory) => ({
    ...memory,
    path: displayResultPath(memory.path, memoryDir, memory.namespace),
  }));
  const namespaceByPath = new Map<string, string | undefined>();
  for (const memory of coerceIncludedMemories(snapshot)) {
    if (!namespaceByPath.has(memory.path)) namespaceByPath.set(memory.path, memory.namespace);
  }
  const tierExplain =
    snapshot.tierExplain?.sourceAnchors
      ? {
          ...snapshot.tierExplain,
          sourceAnchors: snapshot.tierExplain.sourceAnchors.map((anchor) => ({
            ...anchor,
            path: displayResultPath(anchor.path, memoryDir, namespaceByPath.get(anchor.path)),
          })),
        }
      : undefined;
  const resultPaths = includedMemories.map((memory) => memory.path);
  const resultNamespaces = includedMemories.map((memory) => memory.namespace);
  return {
    ...snapshot,
    includedMemories,
    resultPaths,
    resultNamespaces,
    ...(snapshot.budgetsApplied
      ? {
          budgetsApplied: {
            ...snapshot.budgetsApplied,
            includedMemoryPaths: resultPaths,
            includedMemoryNamespaces: resultNamespaces,
          },
        }
      : {}),
    ...(tierExplain ? { tierExplain } : {}),
  };
}

// ---------------------------------------------------------------------------
// Coordinator
// ---------------------------------------------------------------------------

/**
 * Formats recall search results into display sections and assembles the
 * identity-continuity section. Holds a reference to config for feature-gated
 * rendering (memory handles, epistemic hedges, identity injection mode).
 */
export class RecallResultFormatter {
  private readonly originAuthorityEnabled: boolean;
  constructor(private readonly config: PluginConfig) {
    this.originAuthorityEnabled = resolveSecurityCapabilities(config).originAuthority;
  }

  // ── QMD results (memory handles + epistemic hedge) ──────────────────────

  formatQmdResultEntries(
    title: string,
    results: QmdSearchResult[],
    sessionKey?: string,
    trustByPath?: Map<string, TrustStageResultItem> | null,
  ): { heading: string; entries: string[] } {
    const handleByIndex = buildHandleIndexForResults(
      results,
      this.config.recallMemoryHandles === true && sessionKey != null,
    );
    const renderHedge =
      this.config.trustScoreEpistemicRendering &&
      trustByPath !== null &&
      trustByPath !== undefined;
    const hedgeMap = renderHedge ? trustByPath : null;
    const entries = results.map((r, i) => {
      const snippetBody = r.snippet
        ? r.snippet.slice(0, 500).replace(/\n/g, " ")
        : "(no preview)";
      // Historical-prefix contract (issue #1952): only a labeled superseded
      // row gets `[superseded <date> by <id>]`; every other row — and every
      // render with the feature off — stays byte-identical.
      const statePrefix =
        (r.stateLabel === "historical" || r.stateLabel === "transition") &&
        r.supersededAt &&
        r.supersededBy
          ? `${formatSupersededPrefix(r.supersededAt, r.supersededBy)} `
          : "";
      const snippet = renderAuthorityBoundContent(
        `${statePrefix}${snippetBody}`,
        r.origin,
        {
          enabled: this.originAuthorityEnabled,
          untrustedOrigins: this.config.untrustedOrigins,
        },
      );
      const displayPath = displayResultPath(r.path, this.config.memoryDir, r.namespace);
      const source = typeof r.line === "number" ? `${displayPath}:${r.line}` : displayPath;
      const head = `[${i + 1}] ${source} (score: ${r.score.toFixed(3)})\n${snippet}`;
      const handle = handleByIndex.get(i);
      const withHandle = handle ? `${head.trimEnd()} ${handle}` : head.trimEnd();
      const connectorLabel = renderConnectorLabel(r.sourceConnector);
      const withConnector = connectorLabel ? `${withHandle} [agent: ${connectorLabel}]` : withHandle;
      // Preference age note (issue #2371). Set only when
      // `driftDetection.annotateAfterDays` is on, so this suffix is absent —
      // and the rendered line byte-identical to pre-#2371 — by default.
      const withDrift = r.driftNote ? `${withConnector} ${r.driftNote}` : withConnector;
      if (hedgeMap) {
        const item = trustResultFor(hedgeMap, r);
        if (item) {
          const hedge = renderEpistemicHedge(item.trust);
          if (hedge.length > 0) return `${withDrift} ${hedge}`;
        }
      }
      return withDrift;
    });
    return { heading: `## ${title}`, entries };
  }

  formatQmdResults(
    title: string,
    results: QmdSearchResult[],
    sessionKey?: string,
    trustByPath?: Map<string, TrustStageResultItem> | null,
  ): string {
    const formatted = this.formatQmdResultEntries(
      title,
      results,
      sessionKey,
      trustByPath,
    );
    return [formatted.heading, ...formatted.entries].join("\n\n");
  }

  // ── Specialized recall result formatters ────────────────────────────────

  formatObjectiveStateResults(
    results: ObjectiveStateSearchResult[],
  ): string {
    const lines = results.map(({ snapshot }, index) => {
      const parts = [
        snapshot.recordedAt.replace("T", " ").slice(0, 16),
        `${snapshot.kind}/${snapshot.changeKind}`,
      ];
      if (snapshot.outcome) parts.push(snapshot.outcome);
      const header = `[${index + 1}] ${parts.join(" | ")} | ${snapshot.scope}`;
      const detailParts = [snapshot.summary];
      if (snapshot.command) detailParts.push(`command: ${snapshot.command}`);
      else if (snapshot.toolName)
        detailParts.push(`tool: ${snapshot.toolName}`);
      return `${header}\n${detailParts.join(" | ")}`;
    });
    return `## Objective State\n\n${lines.join("\n\n")}`;
  }

  formatCausalTrajectoryResults(
    results: CausalTrajectorySearchResult[],
  ): string {
    const lines = results.map(({ record, matchedFields }, index) => {
      const header = [
        `[${index + 1}] ${record.recordedAt.replace("T", " ").slice(0, 16)}`,
        record.outcomeKind,
      ].join(" | ");
      const details = [
        `goal: ${record.goal}`,
        `action: ${record.actionSummary}`,
        `observation: ${record.observationSummary}`,
        `outcome: ${record.outcomeSummary}`,
      ];
      if (record.followUpSummary)
        details.push(`follow-up: ${record.followUpSummary}`);
      if (matchedFields.length > 0)
        details.push(`matched: ${matchedFields.join(", ")}`);
      return `${header}\n${details.join("\n")}`;
    });

    return `## Causal Trajectories\n\n${lines.join("\n\n")}`;
  }

  formatTrustZoneResults(results: TrustZoneSearchResult[]): string {
    const lines = results.map(({ record, matchedFields }, index) => {
      const header = [
        `[${index + 1}] ${record.recordedAt.replace("T", " ").slice(0, 16)}`,
        record.zone,
        record.kind,
      ].join(" | ");
      const details = [
        record.summary,
        `provenance: ${record.provenance.sourceClass}`,
      ];
      if (record.entityRefs && record.entityRefs.length > 0) {
        details.push(`entities: ${record.entityRefs.join(", ")}`);
      }
      if (record.tags && record.tags.length > 0) {
        details.push(`tags: ${record.tags.join(", ")}`);
      }
      if (matchedFields.length > 0) {
        details.push(`matched: ${matchedFields.join(", ")}`);
      }
      return `${header}\n${details.join("\n")}`;
    });

    return `## Trust Zones\n\n${lines.join("\n\n")}`;
  }

  formatHarmonicRetrievalResults(
    results: HarmonicRetrievalResult[],
  ): string {
    const lines = results.map(
      (
        { node, matchedAnchors, matchedFields, nodeScore, anchorScore },
        index,
      ) => {
        const header = [
          `[${index + 1}] ${node.recordedAt.replace("T", " ").slice(0, 16)}`,
          `${node.kind}/${node.abstractionLevel}`,
          node.sessionKey,
        ].join(" | ");
        // #1955 review: node title/summary copy active source-memory content;
        // harmonic nodes carry no per-node origin yet, so fence as unknown
        // (least privilege) when origin authority is on (plumbing: #2397).
        // Flag-off keeps the original two-slot shape byte-identical.
        const bodyParts = this.originAuthorityEnabled
          ? [renderAuthorityBoundContent(
              [node.title, node.summary].filter(Boolean).join("\n"),
              undefined,
              { enabled: true, untrustedOrigins: this.config.untrustedOrigins },
            )]
          : [node.title, node.summary];
        const details = [
          ...bodyParts,
          `scores: node=${nodeScore.toFixed(1)} anchor=${anchorScore.toFixed(1)}`,
        ];
        if (matchedAnchors.length > 0) {
          details.push(
            `anchors: ${matchedAnchors.map((anchor) => `${anchor.anchorType}:${anchor.anchorValue}`).join("; ")}`,
          );
        }
        if (matchedFields.length > 0) {
          details.push(`matched: ${matchedFields.join(", ")}`);
        }
        return `${header}\n${details.join("\n")}`;
      },
    );

    return `## Harmonic Retrieval\n\n${lines.join("\n\n")}`;
  }

  /**
   * Render grouped raw-turn episodes for the top recalled facts (issue #2331).
   * Returns `null` for zero episodes so the section is omitted entirely —
   * never an empty header.
   */
  formatEpisodicContext(
    episodes: ReadonlyArray<{
      sessionKey: string;
      fromTurn: number;
      toTurn: number;
      memoryIds: readonly string[];
      turns: ReadonlyArray<{ role: string; content: string }>;
    }>,
  ): string | null {
    if (episodes.length === 0) return null;
    const blocks = episodes.map((episode) => {
      const shortKey =
        episode.sessionKey.length > 8
          ? `${episode.sessionKey.slice(0, 8)}…`
          : episode.sessionKey;
      const header =
        `### Episode: ${shortKey} turns ${episode.fromTurn}-${episode.toTurn - 1} ` +
        `(supports [${episode.memoryIds.join(", ")}])`;
      const lines = episode.turns.map((turn) => {
        // Archived conversation turns carry no origin: least-privilege
        // fencing applies when origin authority is enabled (issue #2331).
        const content = renderAuthorityBoundContent(turn.content, undefined, {
          enabled: this.originAuthorityEnabled,
          untrustedOrigins: this.config.untrustedOrigins,
        });
        return `${turn.role}: ${content}`;
      });
      return [header, ...lines].join("\n");
    });
    return `## Source Episodes\n\n${blocks.join("\n\n")}`;
  }

  formatWorkProductResults(
    results: WorkProductLedgerSearchResult[],
  ): string {
    const lines = results.map(({ entry, matchedFields }, index) => {
      const header = [
        `[${index + 1}] ${entry.recordedAt.replace("T", " ").slice(0, 16)}`,
        `${entry.kind}/${entry.action}`,
        entry.sessionKey,
      ].join(" | ");
      const details = [entry.summary, `scope: ${entry.scope}`];
      if (entry.artifactPath) details.push(`artifact: ${entry.artifactPath}`);
      if (entry.tags && entry.tags.length > 0)
        details.push(`tags: ${entry.tags.join(", ")}`);
      if (matchedFields.length > 0)
        details.push(`matched: ${matchedFields.join(", ")}`);
      return `${header}\n${details.join("\n")}`;
    });

    return `## Work Products\n\n${lines.join("\n\n")}`;
  }

  formatVerifiedEpisodeResults(
    results: VerifiedEpisodeResult[],
  ): string {
    const lines = results.map(
      ({ box, verifiedEpisodeCount, matchedFields }, index) => {
        const header = [
          `[${index + 1}] ${box.sealedAt.replace("T", " ").slice(0, 16)}`,
          box.traceId ? `trace:${box.traceId.slice(0, 12)}` : "trace:none",
        ].join(" | ");
        const details = [
          box.goal ?? `topics: ${box.topics.join(", ")}`,
          `verified episodes: ${verifiedEpisodeCount}`,
        ];
        if (box.toolsUsed && box.toolsUsed.length > 0) {
          details.push(`tools: ${box.toolsUsed.join(", ")}`);
        }
        if (matchedFields.length > 0) {
          details.push(`matched: ${matchedFields.join(", ")}`);
        }
        return `${header}\n${details.join("\n")}`;
      },
    );

    return `## Verified Episodes\n\n${lines.join("\n\n")}`;
  }

  formatVerifiedSemanticRuleResults(
    results: VerifiedSemanticRuleResult[],
  ): string {
    const lines = results.map(
      (
        {
          rule,
          sourceMemoryId,
          verificationStatus,
          effectiveConfidence,
          matchedFields,
        },
        index,
      ) => {
        const header = [
          `[${index + 1}] ${rule.frontmatter.updated.replace("T", " ").slice(0, 16)}`,
          verificationStatus,
          `confidence:${effectiveConfidence.toFixed(2)}`,
        ].join(" | ");
        // #1955 review: the rule body derives from a source memory whose
        // origin is not copied onto the rule — fence via the rule's own
        // frontmatter origin (missing → unknown, least privilege) when on.
        const ruleBody = renderAuthorityBoundContent(rule.content, rule.frontmatter.origin, {
          enabled: this.originAuthorityEnabled,
          untrustedOrigins: this.config.untrustedOrigins,
        });
        const details = [ruleBody, `source memory: ${sourceMemoryId}`];
        if (matchedFields.length > 0) {
          details.push(`matched: ${matchedFields.join(", ")}`);
        }
        return `${header}\n${details.join("\n")}`;
      },
    );

    return `## Verified Rules\n\n${lines.join("\n\n")}`;
  }

  // ── Identity continuity helpers ─────────────────────────────────────────

  summarizeIdentityText(
    raw: string,
    maxLines: number,
    maxChars: number,
  ): string {
    const lines = raw
      .replace(/\r/g, "")
      .split("\n")
      .map((line) => line.trim())
      .filter((line) => line.length > 0 && !line.startsWith("#"));
    const compact = lines.slice(0, Math.max(1, maxLines)).join(" ");
    if (compact.length <= maxChars) return compact;
    return `${compact.slice(0, Math.max(0, maxChars - 1))}…`;
  }

  formatOpenIncidentLine(
    incident: ContinuityIncidentRecord,
    includeDetails: boolean,
  ): string {
    const base = `[${incident.id}] ${incident.symptom.trim()}`;
    if (!includeDetails) return `- ${base}`;
    const parts = [base];
    if (incident.suspectedCause)
      parts.push(`cause: ${incident.suspectedCause.trim()}`);
    if (incident.triggerWindow)
      parts.push(`window: ${incident.triggerWindow.trim()}`);
    return `- ${parts.join(" | ")}`;
  }

  trimIdentitySection(
    content: string,
    maxChars: number,
  ): { text: string; truncated: boolean } {
    if (maxChars <= 0) return { text: "", truncated: false };
    if (content.length <= maxChars) return { text: content, truncated: false };
    const suffix = "\n\n...(identity continuity trimmed)";
    if (maxChars <= suffix.length) {
      return { text: content.slice(0, maxChars), truncated: true };
    }
    const headroom = Math.max(0, maxChars - suffix.length);
    return { text: `${content.slice(0, headroom)}${suffix}`, truncated: true };
  }

  async buildIdentityContinuitySection(options: {
    storage: StorageManager;
    recallMode: RecallPlanMode;
    prompt: string;
  }): Promise<{
    section: string;
    mode: IdentityInjectionMode;
    injectedChars: number;
    truncated: boolean;
  } | null> {
    if (!resolveIdentityContinuityCapabilities(this.config).identityContinuity) return null;
    if (this.config.identityMaxInjectChars <= 0) return null;

    const resolved = resolveEffectiveIdentityInjectionMode({
      configuredMode: this.config.identityInjectionMode,
      recallMode: options.recallMode,
      prompt: options.prompt,
    });
    if (!resolved.shouldInject) return null;

    const [anchorRaw, loopsRaw, incidents] = await Promise.all([
      options.storage.readIdentityAnchor(),
      options.storage.readIdentityImprovementLoops(),
      options.storage.readContinuityIncidents(200),
    ]);
    const openIncidents = incidents.filter(
      (incident) => incident.state === "open",
    );

    const lines: string[] = [];
    if (resolved.mode === "full") {
      lines.push("## Identity Continuity");
      if (anchorRaw && anchorRaw.trim().length > 0) {
        lines.push("", "### Anchor", "", anchorRaw.trim());
      }
      if (loopsRaw && loopsRaw.trim().length > 0) {
        lines.push("", "### Improvement Loops", "", loopsRaw.trim());
      }
      lines.push("", "### Open Incidents", "");
      if (openIncidents.length === 0) {
        lines.push("- none");
      } else {
        lines.push(
          ...openIncidents
            .slice(0, 5)
            .map((incident) => this.formatOpenIncidentLine(incident, true)),
        );
      }
    } else {
      const anchorSummary = anchorRaw
        ? this.summarizeIdentityText(anchorRaw, 3, 320)
        : "";
      const loopsSummary = loopsRaw
        ? this.summarizeIdentityText(loopsRaw, 2, 240)
        : "";
      lines.push("## Identity Continuity Signals", "");
      if (anchorSummary) lines.push(`- anchor: ${anchorSummary}`);
      if (loopsSummary) lines.push(`- loops: ${loopsSummary}`);
      if (openIncidents.length === 0) {
        lines.push("- incidents: 0 open");
      } else {
        lines.push(`- incidents: ${openIncidents.length} open`);
        lines.push(
          ...openIncidents
            .slice(0, 2)
            .map((incident) => this.formatOpenIncidentLine(incident, false)),
        );
      }
    }

    const body = lines.join("\n").trim();
    if (!body) return null;

    const { text, truncated } = this.trimIdentitySection(
      body,
      this.config.identityMaxInjectChars,
    );
    if (!text) return null;

    return {
      section: text,
      mode: resolved.mode,
      injectedChars: text.length,
      truncated,
    };
  }
}

/**
 * Conversation index coordinator — extracted from the orchestrator (issue #1526).
 *
 * Owns the conversation-index subsystem: semantic recall over past
 * conversations, plus the build / update / rebuild / inspect / health
 * lifecycle of the on-disk chunk store and its pluggable search backend
 * (qmd or faiss). Behavior-preserving move from orchestrator.ts — no logic
 * changes; the orchestrator constructs one instance and keeps thin
 * delegating methods so existing call sites and tests that exercise the
 * private API continue to work.
 *
 * The backend and transcript are read through getters (not captured at
 * construction) so that post-construction reassignment of the orchestrator's
 * live fields — exercised by the conversation-index integration tests and by
 * backend swap-in at deferred-init time — is honored. This mirrors the
 * TierMigrationCoordinator accessor pattern.
 */

import { readdir } from "node:fs/promises";
import path from "node:path";

import { resolveIndexingCapabilities, resolveSecurityCapabilities } from "../capabilities.js";
import { renderAuthorityBoundContent } from "../recall-context-composition.js";
import { cleanupConversationChunks } from "../conversation-index/cleanup.js";
import { chunkTranscriptEntries } from "../conversation-index/chunker.js";
import type { ConversationChunk } from "../conversation-index/chunker.js";
import { writeConversationChunks } from "../conversation-index/indexer.js";
import type {
  ConversationIndexBackend,
  ConversationIndexBackendHealth,
  ConversationIndexBackendInspection,
} from "../conversation-index/backend.js";
import type { ConversationSearchResult } from "../conversation-index/search.js";
import type { TranscriptManager } from "../transcript.js";
import type { PluginConfig } from "../types.js";

/**
 * Coordinator for the conversation-index subsystem.
 *
 * Holds the per-session last-update timestamps (previously an orchestrator
 * field) and delegates chunk building / persistence / embedding to the
 * configured backend.
 */
export class ConversationIndexCoordinator {
  private readonly config: PluginConfig;
  private readonly originAuthorityEnabled: boolean;
  private readonly getTranscript: () => TranscriptManager;
  private readonly getBackend: () => ConversationIndexBackend | undefined;
  private readonly indexDir: string;
  private readonly lastUpdateAtMs = new Map<string, number>();

  constructor(options: {
    config: PluginConfig;
    getTranscript: () => TranscriptManager;
    getBackend: () => ConversationIndexBackend | undefined;
    indexDir: string;
  }) {
    this.config = options.config;
    this.originAuthorityEnabled = resolveSecurityCapabilities(this.config).originAuthority;
    this.getTranscript = options.getTranscript;
    this.getBackend = options.getBackend;
    this.indexDir = options.indexDir;
  }

  /** Semantic recall over past-conversation chunks (fail-open: empty on miss). */
  async search(
    retrievalQuery: string,
    topK: number,
  ): Promise<ConversationSearchResult[]> {
    const backend = this.getBackend();
    if (backend) {
      return backend.search(retrievalQuery, topK);
    }
    return [];
  }

  /** Render conversation-recall search hits as a budgeted markdown section. */
  formatRecallSection(
    results: ConversationSearchResult[],
    maxChars: number,
  ): string | null {
    if (!Array.isArray(results) || results.length === 0) return null;
    const lines: string[] = ["## Semantic Recall (Past Conversations)", ""];
    let used = 0;
    for (const r of results) {
      if (!r?.snippet) continue;
      const body = renderAuthorityBoundContent(
        r.snippet.trim(),
        undefined,
        {
          enabled: this.originAuthorityEnabled,
          untrustedOrigins: this.config.untrustedOrigins,
        },
      );
      const chunk =
        `### ${r.path}\n` +
        `Score: ${r.score.toFixed(3)}\n\n` +
        `${body}\n`;
      if (used + chunk.length > maxChars) break;
      lines.push(chunk);
      used += chunk.length;
    }
    return used > 0 ? lines.join("\n") : null;
  }

  /** Recursively count `.md` chunk documents under a directory. */
  async countChunkDocs(dir: string): Promise<number> {
    try {
      const entries = await readdir(dir, { withFileTypes: true });
      let total = 0;
      for (const entry of entries) {
        const fullPath = path.join(dir, entry.name);
        if (entry.isDirectory()) {
          total += await this.countChunkDocs(fullPath);
          continue;
        }
        if (entry.isFile() && entry.name.endsWith(".md")) {
          total += 1;
        }
      }
      return total;
    } catch {
      return 0;
    }
  }

  /** Read recent transcript entries and chunk them for indexing. */
  async buildChunks(
    sessionKey?: string,
    hours: number = 24,
  ): Promise<ConversationChunk[]> {
    const entries = await this.getTranscript().readRecent(hours, sessionKey);
    const effectiveSessionKey = sessionKey ?? "all-sessions";
    return chunkTranscriptEntries(effectiveSessionKey, entries, {
      maxChars: this.config.conversationRecallMaxChars * 2,
      maxTurns: Math.max(10, this.config.hourlySummariesMaxTurnsPerRun),
    });
  }

  async getHealth(): Promise<{
    enabled: boolean;
    backend: "qmd" | "faiss";
    status: "ok" | "degraded" | "disabled";
    chunkDocCount: number;
    lastUpdateAt: string | null;
    qmdAvailable?: boolean;
    faiss?: {
      ok: boolean;
      status: "ok" | "degraded" | "error";
      indexPath: string;
      message?: string;
      manifest?: {
        version: number;
        modelId: string;
        normalizedModelId: string;
        dimension: number;
        chunkCount: number;
        updatedAt: string;
        lastSuccessfulRebuildAt: string;
      };
    };
  }> {
    const chunkDocCount = await this.countChunkDocs(this.indexDir);
    const lastUpdateAtMs = Math.max(0, ...this.lastUpdateAtMs.values());
    const lastUpdateAt =
      lastUpdateAtMs > 0 ? new Date(lastUpdateAtMs).toISOString() : null;

    if (!resolveIndexingCapabilities(this.config).conversationIndex) {
      return {
        enabled: false,
        backend: this.config.conversationIndexBackend,
        status: "disabled",
        chunkDocCount,
        lastUpdateAt,
      };
    }
    const backend = this.getBackend();
    const backendHealth: ConversationIndexBackendHealth = backend
      ? await backend.health()
      : {
          backend: this.config.conversationIndexBackend,
          status: "degraded" as const,
        };
    return {
      enabled: true,
      chunkDocCount,
      lastUpdateAt,
      ...backendHealth,
    };
  }

  async inspect(): Promise<
    ConversationIndexBackendInspection & {
      enabled: boolean;
      chunkDocCount: number;
      lastUpdateAt: string | null;
    }
  > {
    const chunkDocCount = await this.countChunkDocs(this.indexDir);
    const lastUpdateAtMs = Math.max(0, ...this.lastUpdateAtMs.values());
    const lastUpdateAt =
      lastUpdateAtMs > 0 ? new Date(lastUpdateAtMs).toISOString() : null;

    if (!resolveIndexingCapabilities(this.config).conversationIndex) {
      return {
        enabled: false,
        backend: this.config.conversationIndexBackend,
        status: "disabled",
        available: false,
        indexPath: this.indexDir,
        supportsIncrementalUpdate: true,
        message: "Conversation index disabled by config",
        metadata: {
          chunkCount: chunkDocCount,
        },
        chunkDocCount,
        lastUpdateAt,
      };
    }

    const backend = this.getBackend();
    const inspection: ConversationIndexBackendInspection = backend
      ? await backend.inspect()
      : {
          backend: this.config.conversationIndexBackend,
          status: "degraded" as const,
          available: false,
          indexPath: this.indexDir,
          supportsIncrementalUpdate: true,
          message: "Conversation index backend unavailable",
          metadata: {
            chunkCount: chunkDocCount,
          },
        };

    return {
      enabled: true,
      chunkDocCount,
      lastUpdateAt,
      ...inspection,
    };
  }

  async update(
    sessionKey: string,
    hours: number = 24,
    opts?: { embed?: boolean; enforceMinInterval?: boolean },
  ): Promise<{
    chunks: number;
    skipped: boolean;
    reason?: string;
    retryAfterMs?: number;
    embedded?: boolean;
  }> {
    if (!resolveIndexingCapabilities(this.config).conversationIndex) {
      return { chunks: 0, skipped: true, reason: "disabled", embedded: false };
    }
    const enforceMinInterval = opts?.enforceMinInterval !== false;
    if (enforceMinInterval) {
      const minIntervalMs = Math.max(
        0,
        this.config.conversationIndexMinUpdateIntervalMs,
      );
      const now = Date.now();
      const last = this.lastUpdateAtMs.get(sessionKey) ?? 0;
      const elapsed = now - last;
      if (minIntervalMs > 0 && elapsed < minIntervalMs) {
        return {
          chunks: 0,
          skipped: true,
          reason: "min_interval",
          retryAfterMs: minIntervalMs - elapsed,
          embedded: false,
        };
      }
    }
    const chunks = await this.buildChunks(sessionKey, hours);
    await writeConversationChunks(this.indexDir, chunks);
    const retentionCutoffMs =
      Number.isFinite(this.config.conversationIndexRetentionDays) &&
      this.config.conversationIndexRetentionDays > 0
        ? Date.now() -
          this.config.conversationIndexRetentionDays * 24 * 60 * 60 * 1000
        : undefined;
    await cleanupConversationChunks(
      this.indexDir,
      this.config.conversationIndexRetentionDays,
    );
    const shouldEmbed =
      opts?.embed ?? this.config.conversationIndexEmbedOnUpdate;
    let embedded = false;

    const backend = this.getBackend();
    if (backend) {
      const result = await backend.update(chunks, {
        embed: shouldEmbed,
        ...(retentionCutoffMs !== undefined ? { retentionCutoffMs } : {}),
      });
      embedded = result.embedded;
    }

    this.lastUpdateAtMs.set(sessionKey, Date.now());
    return { chunks: chunks.length, skipped: false, embedded };
  }

  async rebuild(
    sessionKey?: string,
    hours: number = 24,
    opts?: { embed?: boolean },
  ): Promise<{
    chunks: number;
    skipped: boolean;
    reason?: string;
    embedded?: boolean;
    rebuilt?: boolean;
  }> {
    if (!resolveIndexingCapabilities(this.config).conversationIndex) {
      return {
        chunks: 0,
        skipped: true,
        reason: "disabled",
        embedded: false,
        rebuilt: false,
      };
    }

    const chunks = await this.buildChunks(sessionKey, hours);
    await writeConversationChunks(this.indexDir, chunks);
    await cleanupConversationChunks(
      this.indexDir,
      this.config.conversationIndexRetentionDays,
    );

    const shouldEmbed =
      opts?.embed ?? this.config.conversationIndexEmbedOnUpdate;
    let embedded = false;
    let rebuilt = false;
    const backend = this.getBackend();
    if (backend) {
      const result = await backend.rebuild(chunks, {
        embed: shouldEmbed,
      });
      embedded = result.embedded;
      rebuilt = result.rebuilt;
    }

    const stamp = Date.now();
    if (sessionKey) {
      this.lastUpdateAtMs.set(sessionKey, stamp);
    } else {
      this.lastUpdateAtMs.set("__rebuild__", stamp);
    }
    return { chunks: chunks.length, skipped: false, embedded, rebuilt };
  }
}

/**
 * Recall rerank coordinator — extracted from the orchestrator (issue #1526).
 *
 * Owns the post-retrieval result-ranking subsystem: Memory-Worth reranking,
 * TrustScore scoring + quarantine, reasoning-trace boost, and MMR
 * diversification/limiting. Behavior-preserving move from orchestrator.ts —
 * no logic changes; the orchestrator constructs one instance and keeps thin
 * delegating methods so existing call sites (recallInternal,
 * applyColdFallbackPipeline) continue to work.
 *
 * Config, storage, and the QMD-result memory reader are accessed through
 * getter callbacks (not captured at construction) so that post-construction
 * reassignment of the orchestrator's live fields is honored. This mirrors
 * the ConversationIndexCoordinator / TierMigrationCoordinator accessor
 * pattern.
 */

import { resolveCapabilities, type CapabilitySet } from "../capabilities.js";
import type { PluginConfig, QmdSearchResult, MemoryFile } from "../types.js";
import type { StorageManager } from "../index.js";
import { log } from "../logger.js";
import {
  applyMemoryWorthFilter,
  buildMemoryWorthCounterMap,
  type MemoryWorthCounters,
} from "../memory-worth-filter.js";
import {
  applyPreferenceDriftRanking,
  isPreferenceDriftStageActive,
  type DriftRecallFrontmatter,
} from "../preferences/drift-recall.js";
import {
  applyTrustScoreStage,
  buildTrustSignalsForRerank,
  trustResultKey,
  type TrustStageResultItem,
} from "../trust-score-stage.js";
import type { TrustSignals } from "../trust-score.js";
import { reorderRecallResultsWithMmr } from "../recall-mmr.js";
import { applyReasoningTraceBoost } from "../reasoning-trace-recall.js";
import { memoryMapKey } from "../recall-memory-map.js";
import { capStateViewPackets, reconcileStateViewPairs } from "../recall-state-view.js";

export interface RecallResultPartition {
  appliedResults: QmdSearchResult[];
  headroomResults: QmdSearchResult[];
}
export interface RecallResultPartitionSink {
  partition: RecallResultPartition | null;
}

export function reconcileRecallResultPartition(
  partition: RecallResultPartition | null | undefined,
  appliedResults: QmdSearchResult[],
): RecallResultPartition | null {
  return partition
    ? { appliedResults, headroomResults: partition.headroomResults }
    : null;
}

/**
 * Coordinator for the recall-result reranking subsystem.
 *
 * Holds the per-namespace caches for memory-worth counters and trust signals
 * (previously orchestrator fields) so the reranking stages don't trigger a
 * full `readAllMemories` scan per query.
 */
export class RecallRerankCoordinator {
  private readonly getConfig: () => PluginConfig;
  private readonly getStorage: (namespace: string) => Promise<StorageManager>;
  private readonly readQmdResultMemory: (
    resultPath: string,
    fallbackStorage: StorageManager,
    recallNamespaces: readonly string[],
    preferredNamespace?: string,
  ) => Promise<MemoryFile | null>;

  // Per-namespace corpus-fallback caches (issue #1905). Keyed on the shared
  // cross-process memory-corpus version rather than a wall-clock TTL: the old
  // 30s TTL was SHORTER than recall p50 (~30.5s) so every steady-state recall
  // was a guaranteed miss + full-corpus scan. The corpus version bumps on every
  // memory mutation (StorageManager.getMemoryCorpusVersion / patchHotMemoriesCache),
  // including mw_success/mw_fail counter writes, so a version match means the
  // derived map is still current and can be served; a mismatch re-derives.
  private readonly memoryWorthCounterCache = new Map<
    string,
    { version: number; counters: ReadonlyMap<string, MemoryWorthCounters> }
  >();

  private readonly trustSignalCache = new Map<
    string,
    { version: number; cachedAt: number; signals: ReadonlyMap<string, TrustSignals> }
  >();

  /**
   * Cap on distinct namespaces retained in the corpus-fallback caches. Each
   * entry holds a derived per-namespace map; on high-cardinality namespace
   * workloads an unbounded map would grow without limit (#1905, Cursor). Map
   * preserves insertion order, so overflow evicts the oldest namespace.
   */
  private static readonly CORPUS_FALLBACK_CACHE_MAX_NAMESPACES = 64;

  // Trust-signal age bound (TRUST_SIGNAL_CACHE_MAX_AGE_MS) lives in
  // trust-score-stage.ts — that module owns the signal cache's read/write and
  // the TTL check (signals bake `now` into their values). This coordinator only
  // owns the memory-worth counter cache, whose values are raw (no `now`), so it
  // is version-keyed only.


  /** Insert-ordered bounded set: evict the oldest namespace on overflow. */
  private static capCache<K, V>(cache: Map<K, V>, max: number): void {
    while (cache.size > max) {
      const oldest = cache.keys().next().value;
      if (oldest === undefined) break;
      cache.delete(oldest);
    }
  }

  constructor(options: {
    getConfig: () => PluginConfig;
    getStorage: (namespace: string) => Promise<StorageManager>;
    readQmdResultMemory: (
      resultPath: string,
      fallbackStorage: StorageManager,
      recallNamespaces: readonly string[],
      preferredNamespace?: string,
    ) => Promise<MemoryFile | null>;
  }) {
    this.getConfig = options.getConfig;
    this.getStorage = options.getStorage;
    this.readQmdResultMemory = options.readQmdResultMemory;
  }

  async applyMemoryWorthRerank(
    results: QmdSearchResult[],
    namespaces: string[],
    // Candidate frontmatter already loaded on the hot recall path (issue
    // #1905). Additive + last so the positional call shape stays
    // backward-compatible. When present, counters are seeded from it directly
    // and the O(corpus) `readAllMemories` scan is skipped for warm candidates.
    preloadedFrontmatter?: ReadonlyMap<string, MemoryFile>,
    // Cooperative cancellation (issue #1905, Codex); additive + last.
    abortSignal?: AbortSignal,
  ): Promise<QmdSearchResult[]> {
    const config = this.getConfig();
    const counters = new Map<string, MemoryWorthCounters>();
    // Paths examined via preloaded frontmatter (issue #1905, Codex). A candidate
    // whose frontmatter is present but has no mw_success/mw_fail is a NEUTRAL
    // prior — it must NOT be treated as "missing", otherwise the corpus scan +
    // direct-read fallback fire for every uninstrumented hot-QMD candidate and
    // the O(candidates) fast path is defeated. Track preloaded paths separately
    // from counters and exclude them from every fallback.
    const preloadedPaths = new Set<string>();

    // O(candidates) fast path (issue #1905): seed counters directly from
    // frontmatter already loaded on the hot path. The
    // `mw_success === undefined && mw_fail === undefined` guard matches
    // `buildMemoryWorthCounterMap` exactly so a candidate with no counters is a
    // neutral prior, identical to the corpus scan.
    if (preloadedFrontmatter) {
      for (const r of results) {
        const key = memoryMapKey(r);
        // Composite (namespace, path) key is authoritative — it can never hit a
        // wrong-namespace entry. The bare-path fallback keeps path-keyed callers
        // working and is inert in production (loaded maps are composite-keyed).
        const mem = preloadedFrontmatter.get(key) ?? preloadedFrontmatter.get(r.path);
        if (!mem) continue;
        preloadedPaths.add(key);
        const fm = mem.frontmatter;
        if (fm.mw_success === undefined && fm.mw_fail === undefined) continue;
        counters.set(key, {
          mw_success: fm.mw_success,
          mw_fail: fm.mw_fail,
          lastAccessed: fm.lastAccessed,
        });
      }
    }

    // Corpus-level fallback (config-gated): candidates still missing from the
    // preloaded map probe a per-namespace counter map. The map is cached and
    // invalidated by the shared cross-process corpus version (not a wall-clock
    // TTL), so it actually hits in steady state. Only the candidate rows are
    // copied out — never the whole ~99K-entry map (issue #1905).
    if (config.recallTrustStageCorpusFallbackEnabled) {
      const seenNamespaces = new Set<string>();
      for (const ns of namespaces) {
        // Cooperative cancellation: the recall's assembly deadline may have won
        // the race — stop before another namespace scan (#1905, Codex).
        if (abortSignal?.aborted) break;
        if (seenNamespaces.has(ns)) continue;
        seenNamespaces.add(ns);
        if (results.every((r) => counters.has(memoryMapKey(r)) || preloadedPaths.has(memoryMapKey(r)))) break;
        try {
          const storage = await this.getStorage(ns);
          const version = storage.getMemoryCorpusVersion();
          const cached = this.memoryWorthCounterCache.get(ns);
          let nsMap: ReadonlyMap<string, MemoryWorthCounters>;
          if (cached && cached.version === version) {
            nsMap = cached.counters;
          } else {
            const memories = await storage.readAllMemories();
            nsMap = buildMemoryWorthCounterMap(memories);
            this.memoryWorthCounterCache.set(ns, { version, counters: nsMap });
            RecallRerankCoordinator.capCache(
              this.memoryWorthCounterCache,
              RecallRerankCoordinator.CORPUS_FALLBACK_CACHE_MAX_NAMESPACES,
            );
          }
          for (const r of results) {
            // Skip candidates already satisfied by a counter OR already examined
            // via preloaded frontmatter (neutral prior — no corpus lookup needed).
            const key = memoryMapKey(r);
            if (counters.has(key) || preloadedPaths.has(key)) continue;
            // A namespaced result belongs to exactly one namespace: never seed
            // its counters from a different namespace's corpus map, or two
            // same-path results in different namespaces collapse (#2020).
            if (r.namespace !== undefined && r.namespace !== ns) continue;
            const c = nsMap.get(r.path);
            if (c) counters.set(key, c);
          }
        } catch (err) {
          log.debug("memory-worth: failed to read namespace, skipping", {
            namespace: ns,
            error: (err as Error).message,
          });
        }
      }
    }

    // For candidates still absent (cold-tier / archive, or corpus fallback
    // disabled), try a direct per-path read. Bounded-parallel (≤16) to match
    // loadSearchResultMemoryMap's batch size (issue #1905). Errors are swallowed
    // so a single unreadable archive entry can't break the whole recall.
    const missing = results.filter(
      (r) => !counters.has(memoryMapKey(r)) && !preloadedPaths.has(memoryMapKey(r)),
    );
    if (missing.length > 0) {
      // Use the first-seen namespace's storage as the reader — all
      // StorageManagers share the same on-disk format, and readMemoryByPath
      // takes an absolute path so the baseDir doesn't have to match.
      let reader: StorageManager | null = null;
      for (const ns of namespaces) {
        try {
          reader = await this.getStorage(ns);
          break;
        } catch {
          // try next namespace
        }
      }
      if (reader) {
        const readerNn = reader;
        const BATCH = 16;
        for (let off = 0; off < missing.length; off += BATCH) {
          // Cooperative cancellation between batches (#1905, Codex).
          if (abortSignal?.aborted) break;
          await Promise.all(
            missing.slice(off, off + BATCH).map(async (r) => {
              try {
                const memory = await this.readQmdResultMemory(
                  r.path,
                  readerNn,
                  namespaces,
                  r.namespace,
                );
                if (!memory) return;
                const fm = memory.frontmatter;
                if (fm.mw_success === undefined && fm.mw_fail === undefined) return;
                counters.set(memoryMapKey(r), {
                  mw_success: fm.mw_success,
                  mw_fail: fm.mw_fail,
                  lastAccessed: fm.lastAccessed,
                });
              } catch (err) {
                log.debug("memory-worth: direct path lookup failed", {
                  path: r.path,
                  error: (err as Error).message,
                });
              }
            }),
          );
        }
      }
    }

    // If no memory in the candidate set has any counter data, the filter
    // would be a no-op — skip the reorder to avoid spurious log spam.
    if (counters.size === 0) return results;

    // Preserve upstream ordering (reranker, specialized tiers, etc.) for
    // neutral candidates. The upstream stages set `memoryResults` in their
    // intended order but often leave `r.score` as the raw QMD score. If we
    // sorted by `r.score * multiplier` directly, neutral candidates
    // (multiplier 1.0) would snap back to raw-QMD order and silently undo
    // the reranker. Feed the filter a synthetic monotone-decreasing rank
    // score so it uses input position as the baseline, then applies the
    // multiplier on top. Ties fall back to the stable secondary key in
    // `applyMemoryWorthFilter`.
    const rankedInputs = results.map((r, i) => ({
      // Composite (namespace, path) identity so same-path results in different
      // namespaces stay distinct through the filter and reconstruction (#2020).
      path: memoryMapKey(r),
      // Large positive rank score so multiplier math stays well-scaled and
      // we never hit zero; descending so earlier items rank higher.
      score: results.length - i,
    }));
    const filtered = applyMemoryWorthFilter(rankedInputs, {
      counters,
      now: new Date(),
      halfLifeMs:
        config.recallMemoryWorthHalfLifeMs > 0
          ? config.recallMemoryWorthHalfLifeMs
          : undefined,
    });

    // Reconstruct the QmdSearchResult list in the new order. `.score` is
    // preserved from the upstream pipeline (rerank, tier scoring, etc.) —
    // we only reorder. Writing the synthetic rank-weighted score back
    // would contaminate downstream logic (telemetry, confidence gates)
    // that expects the original QMD/rerank score semantics.
    // Divide rank × multiplier by pool size: a positive scaling preserves
    // MMR's normalized relevance while keeping additive boosts meaningful.
    // Neutral stages leave upstream metadata untouched.
    const adjusted = filtered.some((item) => item.multiplier !== 1);
    const byPath = new Map(results.map((r) => [memoryMapKey(r), r]));
    const reordered: QmdSearchResult[] = [];
    for (const item of filtered) {
      const original = byPath.get(item.path);
      if (!original) continue;
      reordered.push(adjusted ? { ...original, effectiveScore: item.score / results.length } : original);
    }
    return reordered;
  }

  /**
   * Issue #1577 — unified TrustScore recall stage. Thin wiring over the pure
   * {@link applyTrustScoreStage} scorer + the {@link buildTrustSignalsForRerank}
   * signal builder. The stage subsumes the Memory Worth multiplier — the
   * orchestrator runs exactly one of the two (mutual exclusion, rule 39; the
   * double-multiplier test in trust-score-stage.test.ts pins it structurally).
   *
   * Returns the admitted results AND the per-path trust map (including
   * quarantined items) so the caller can: (a) render epistemic hedges, (b)
   * surface quarantined items in X-ray with a reason (rule 34), and (c) filter
   * quarantined paths from fallback recall branches. The trust map is a
   * per-recall local — never instance state — so concurrent recalls cannot
   * race on it (review: shared-trust-map concurrency).
   */
  async applyTrustScoreRerank(
    results: QmdSearchResult[],
    namespaces: string[],
    // Candidate frontmatter already loaded on the hot recall path (issue
    // #1905); additive + last for positional back-compat. Seeds signals
    // directly so warm candidates skip the O(corpus) namespace scan.
    preloadedFrontmatter?: ReadonlyMap<string, MemoryFile>,
    // Cooperative cancellation (issue #1905, Codex): aborted by the host when
    // the recall's assembly deadline wins the race, so orphaned corpus scans
    // stop at the next loop boundary. Additive + last for positional back-compat.
    abortSignal?: AbortSignal,
  ): Promise<{
    results: QmdSearchResult[];
    trustByPath: Map<string, TrustStageResultItem> | null;
  }> {
    if (results.length === 0) return { results, trustByPath: null };
    const config = this.getConfig();
    const now = new Date();
    const halfLifeDays =
      config.recallMemoryWorthHalfLifeMs > 0
        ? config.recallMemoryWorthHalfLifeMs / (24 * 60 * 60 * 1000)
        : undefined;
    // Cold-tier direct-fallback reader: resolve once, reuse for every missing
    // candidate (mirrors the memory-worth filter's reader selection).
    let fallbackReader: StorageManager | null = null;
    const signals = await buildTrustSignalsForRerank(
      results.map((r) => ({
        path: r.path,
        // Signals are keyed by the SAME composite key the trust stage looks up
        // (trustResultKey), and preloaded frontmatter by memoryMapKey, so
        // same-path results in different namespaces stay distinct (#2020).
        signalKey: trustResultKey(r),
        lookupKey: memoryMapKey(r),
        namespace: r.namespace,
      })),
      namespaces,
      {
        readNamespaceMemories: async (ns) => (await this.getStorage(ns)).readAllMemories(),
        readMemoryFrontmatter: async (path, preferredNamespace) => {
          if (!fallbackReader) {
            for (const ns of namespaces) {
              try {
                fallbackReader = await this.getStorage(ns);
                break;
              } catch {
                // try next namespace
              }
            }
          }
          if (!fallbackReader) return null;
          const memory = await this.readQmdResultMemory(
            path,
            fallbackReader,
            namespaces,
            preferredNamespace,
          );
          return memory ? memory.frontmatter : null;
        },
        // Corpus version bumps on every memory mutation (including mw counter
        // writes) — keys the per-namespace signal cache so it invalidates on
        // the next write instead of a wall-clock TTL (issue #1905).
        getNamespaceVersion: async (ns) => (await this.getStorage(ns)).getMemoryCorpusVersion(),
      },
      { cache: this.trustSignalCache },
      now,
      {
        recencyHalfLifeDays: halfLifeDays,
        logDebug: (message, context) => log.debug(message, context),
        preloadedFrontmatter,
        corpusFallbackEnabled: config.recallTrustStageCorpusFallbackEnabled,
        abortSignal,
      },
    );
    if (signals.size === 0) {
      return { results, trustByPath: null };
    }
    // Synthetic monotone-decreasing rank so the multiplier rebias is applied
    const rankedInputs = results.map((r, i) => ({
      path: r.path,
      key: trustResultKey(r),
      score: results.length - i,
    }));
    const stage = applyTrustScoreStage(rankedInputs, {
      signals,
      weights: config.trustScoreWeights,
      minMultiplier: config.trustScoreMinMultiplier,
      maxMultiplier: config.trustScoreMaxMultiplier,
      quarantine: config.trustScoreQuarantine,
    });
    if (stage.quarantined.length > 0) {
      const survivors = stage.all.filter((item) => !item.quarantined);
      for (const [index, item] of survivors.entries()) {
        item.score = (survivors.length - index) * item.multiplier;
      }
      stage.admitted = survivors.sort((a, b) => b.score - a.score);
    }
    const trustByPath = new Map(
      stage.all.map((item) => [item.key ?? item.path, item] as const),
    );
    const byKey = new Map<string, QmdSearchResult[]>();
    for (const result of results) {
      const key = trustResultKey(result);
      const bucket = byKey.get(key);
      if (bucket) bucket.push(result);
      else byKey.set(key, [result]);
    }
    // Same rule as the Memory Worth stage. Quarantined items keep multiplier
    // 1, so they never make the stage look adjusted.
    const adjusted = stage.admitted.some((item) => item.multiplier !== 1);
    // Excluded rows must not compress relevance against MMR's diversity term.
    const relevanceScale = stage.admitted.reduce((max, item) => Math.max(max, item.score), 0) || 1;
    const admitted: QmdSearchResult[] = [];
    for (const item of stage.admitted) {
      const key = item.key ?? item.path;
      const original =
        item.key !== undefined
          ? byKey.get(key)?.shift()
          : results.find((result) => result.path === item.path);
      if (!original) continue;
      admitted.push(adjusted ? { ...original, effectiveScore: item.score / relevanceScale } : original);
    }
    return { results: admitted, trustByPath };
  }

  /**
   * Issue #1577 — apply the TrustScore stage (or, when trust is off, the Memory
   * Worth multiplier fallback) to ONE recall branch's results, returning the
   * scored results + the per-path trust map. Thin wiring over
   * {@link applyTrustScoreRerank} so every recall path — hot QMD, embedding
   * fallback, recent scan — applies the SAME multiplier gate (rule 41: a
   * feature gate must apply across ALL parallel recall paths). TrustScore
   * subsumes Memory Worth; exactly one runs (rule 39). Fail-open on lookup
   * errors so a storage hiccup never breaks a fallback path.
   */
  async applyTrustScoreToBranch(
    results: QmdSearchResult[],
    namespaces: string[],
    caps: CapabilitySet,
    label: string,
    // Candidate frontmatter already loaded on this branch's hot path (issue
    // #1905); additive + last. Threaded to the active stage so it does
    // O(candidates) work instead of a full-corpus scan. `undefined` on
    // branches without a safety-filter map → falls back to corpus/direct-read
    // (identical lookup result, rule 41 parity).
    preloadedFrontmatter?: ReadonlyMap<string, MemoryFile>,
    // Cooperative cancellation (issue #1905, Codex); additive + last.
    abortSignal?: AbortSignal,
  ): Promise<{
    results: QmdSearchResult[];
    trustByPath: Map<string, TrustStageResultItem> | null;
  }> {
    // The trust stage and the Memory Worth multiplier are mutually exclusive
    // (rule 39); the preference-drift stage runs AFTER whichever one applied,
    // on every branch, so its gate is uniform across recall paths (§27).
    let staged = results;
    let trustByPath: Map<string, TrustStageResultItem> | null = null;
    if (caps.recallTrustScore && results.length > 0) {
      try {
        const outcome = await this.applyTrustScoreRerank(results, namespaces, preloadedFrontmatter, abortSignal);
        staged = outcome.results;
        trustByPath = outcome.trustByPath;
      } catch (err) {
        log.debug(`trust-score stage (${label}) failed open`, {
          error: (err as Error).message,
        });
      }
    } else if (caps.recallMemoryWorthFilter && results.length > 0) {
      try {
        staged = await this.applyMemoryWorthRerank(
          results,
          namespaces,
          preloadedFrontmatter,
          abortSignal,
        );
      } catch (err) {
        log.debug(`memory-worth filter (${label}) failed open`, {
          error: (err as Error).message,
        });
      }
    }
    const damped = await this.applyPreferenceDriftStage(
      staged,
      namespaces,
      preloadedFrontmatter,
      abortSignal,
    );
    return { results: damped, trustByPath };
  }

  /**
   * Issue #2371 — stale-preference damping + injection annotation.
   *
   * Runs immediately after the trust/Memory-Worth stage on EVERY recall branch
   * (hot QMD, embedding fallback, recent scan, cold fallback), so the feature
   * gate applies uniformly and fallback parity holds (§27, AGENTS.md retrieval
   * guardrails). Fully inert on the default config: when neither damping nor
   * annotation is active the input array is returned untouched and NO
   * frontmatter is read, so recall ordering and injected text stay
   * byte-identical to pre-#2371.
   *
   * Fail-open: any lookup error leaves the branch's results unchanged.
   */
  async applyPreferenceDriftStage(
    results: QmdSearchResult[],
    namespaces: string[],
    preloadedFrontmatter?: ReadonlyMap<string, MemoryFile>,
    abortSignal?: AbortSignal,
  ): Promise<QmdSearchResult[]> {
    const config = this.getConfig();
    if (!isPreferenceDriftStageActive(config.driftDetection)) return results;
    if (results.length === 0) return results;

    try {
      const frontmatterByKey = new Map<string, DriftRecallFrontmatter>();
      const missing: QmdSearchResult[] = [];
      for (const r of results) {
        const key = memoryMapKey(r);
        const preloaded = preloadedFrontmatter?.get(key) ?? preloadedFrontmatter?.get(r.path);
        if (preloaded) {
          frontmatterByKey.set(key, preloaded.frontmatter);
        } else {
          missing.push(r);
        }
      }

      // Branches without a preloaded map (embedding fallback) read the
      // candidates directly. Bounded-parallel at the same batch size the
      // Memory Worth stage uses, and only for the handful of candidates the
      // branch actually returned — never a corpus scan.
      if (missing.length > 0) {
        let reader: StorageManager | null = null;
        for (const ns of namespaces) {
          try {
            reader = await this.getStorage(ns);
            break;
          } catch {
            // try next namespace
          }
        }
        if (reader) {
          const readerNn = reader;
          const BATCH = 16;
          for (let off = 0; off < missing.length; off += BATCH) {
            if (abortSignal?.aborted) break;
            await Promise.all(
              missing.slice(off, off + BATCH).map(async (r) => {
                try {
                  const memory = await this.readQmdResultMemory(r.path, readerNn, namespaces, r.namespace);
                  if (memory) frontmatterByKey.set(memoryMapKey(r), memory.frontmatter);
                } catch (err) {
                  log.debug("preference-drift: direct path lookup failed", {
                    path: r.path,
                    error: (err as Error).message,
                  });
                }
              }),
            );
          }
        }
      }

      // Preserve upstream effective relevance when available; otherwise use
      // normalized input position, not stale raw retrieval scores.
      const ranked = results.map((r, i) => ({
        key: memoryMapKey(r),
        rank: typeof r.effectiveScore === "number" && Number.isFinite(r.effectiveScore)
          ? r.effectiveScore : (results.length - i) / results.length,
        frontmatter: frontmatterByKey.get(memoryMapKey(r)),
      }));
      const ordered = applyPreferenceDriftRanking(ranked, {
        config: config.driftDetection,
        now: new Date(),
      });

      // Compose damping into the upstream scale. Annotation-only runs
      // leave upstream relevance untouched.
      const adjusted = ordered.some((item) => item.multiplier !== 1);
      const byKey = new Map(results.map((r) => [memoryMapKey(r), r]));
      const rankByKey = new Map(ranked.map((r) => [r.key, r.rank]));
      const reordered: QmdSearchResult[] = [];
      for (const item of ordered) {
        const original = byKey.get(item.key);
        if (!original) continue;
        // `driftNote` is copied onto a NEW result object — never mutated in
        // place — so a shared upstream result can't leak an annotation into an
        // unrelated branch. The copy keeps the upstream effective relevance.
        const annotated: QmdSearchResult = item.note
          ? { ...original, driftNote: item.note }
          : original;
        const rank = rankByKey.get(item.key);
        reordered.push(
          adjusted && rank !== undefined
            ? { ...annotated, effectiveScore: rank * item.multiplier }
            : annotated,
        );
      }
      return reordered;
    } catch (err) {
      log.debug("preference-drift stage failed open", { error: (err as Error).message });
      return results;
    }
  }

  diversifyRecallResultsWithHeadroom(
    sectionId: string,
    results: QmdSearchResult[],
    limit: number,
    retrievalQuery?: string,
    caps: CapabilitySet = resolveCapabilities(this.getConfig()),
    /**
     * #2859 — state-view packet semantics. When true, superseded rows are
     * reconciled against their successors BEFORE MMR (orphan removal can
     * never underfill), and the cap counts complete evidence packets: a
     * predecessor admitted alongside its successor consumes ONE slot and
     * the slice never splits the pair at the boundary. Absent/false keeps
     * the legacy slice byte-identical.
     */
    stateViewActive?: boolean,
  ): RecallResultPartition {
    const safeLimit =
      typeof limit === "number" && Number.isFinite(limit)
        ? Math.max(0, Math.floor(limit))
        : 0;
    // #2859: reconcile pairs before the user cap/MMR so orphan removal
    // happens pre-truncation, never post-cap.
    const candidates =
      stateViewActive === true && Array.isArray(results)
        ? reconcileStateViewPairs(results)
        : Array.isArray(results)
          ? results
          : [];
    let orderedPool: QmdSearchResult[] | undefined;
    const resolveOrderedPool = (): QmdSearchResult[] => {
      if (orderedPool) return orderedPool;
      const boosted =
        caps.recallReasoningTraceBoost && typeof retrievalQuery === "string"
          ? applyReasoningTraceBoost(candidates, {
              enabled: true,
              query: retrievalQuery,
            })
          : candidates;
      orderedPool = this.applyMmrToQmdResults(sectionId, boosted, caps);
      return orderedPool;
    };
    let appliedCache: QmdSearchResult[] | undefined;
    const resolveApplied = (): QmdSearchResult[] => {
      if (appliedCache) return appliedCache;
      if (safeLimit === 0 || candidates.length === 0) {
        appliedCache = [];
        return appliedCache;
      }
      const ordered = resolveOrderedPool();
      // #2859: the cap counts complete evidence packets, not rows.
      appliedCache =
        stateViewActive === true ? capStateViewPackets(ordered, safeLimit) : ordered.slice(0, safeLimit);
      return appliedCache;
    };

    return {
      get appliedResults(): QmdSearchResult[] {
        return resolveApplied().slice();
      },
      get headroomResults(): QmdSearchResult[] {
        if (candidates.length === 0) return [];
        const ordered = resolveOrderedPool();
        if (stateViewActive === true) {
          const applied = new Set(resolveApplied());
          return ordered.filter((row) => !applied.has(row));
        }
        return ordered.slice(safeLimit);
      },
    };
  }

  diversifyAndLimitRecallResults(
    sectionId: string,
    results: QmdSearchResult[],
    limit: number,
    retrievalQuery?: string,
    caps: CapabilitySet = resolveCapabilities(this.getConfig()),
    /** #2859 — see diversifyRecallResultsWithHeadroom. */
    stateViewActive?: boolean,
  ): QmdSearchResult[] {
    return this.diversifyRecallResultsWithHeadroom(
      sectionId,
      results,
      limit,
      retrievalQuery,
      caps,
      stateViewActive,
    ).appliedResults;
  }

  /**
   * Apply Maximal Marginal Relevance to a section's ordered candidate list.
   *
   * Operates per-section so one redundant cluster cannot dominate a section,
   * and so one section's MMR pass cannot starve other sections. Returns the
   * input unchanged when disabled, when there are fewer than 2 candidates, or
   * when no budget information is available.
   */
  applyMmrToQmdResults(
    sectionId: string,
    results: QmdSearchResult[],
    // Additive `caps` (issue #1523); defaults to a config-derived set so direct
    // callers that omit it behave identically to the threaded recall path.
    caps: CapabilitySet = resolveCapabilities(this.getConfig()),
  ): QmdSearchResult[] {
    if (!caps.recallMmr) return results;
    if (!Array.isArray(results) || results.length < 2) return results;

    // Config is runtime API (see AGENTS.md §4): preserve `0` as a true zero
    // limit rather than coercing it to a non-zero value. A configured topN of
    // 0 means "apply MMR over an empty window" — i.e. skip the reorder and
    // return the upstream candidates unchanged. This keeps read-time
    // behavior symmetric with the write-time semantics parseConfig exposes.
    const config = this.getConfig();
    const configuredTopN = config.recallMmrTopN;
    const topN =
      typeof configuredTopN === "number" && Number.isFinite(configuredTopN)
        ? Math.max(0, Math.floor(configuredTopN))
        : 40;
    if (topN === 0) return results;
    const lambda = config.recallMmrLambda ?? 0.7;

    // Delegate to the pure helper so candidate keying (path-first, index
    // suffixed for uniqueness) and the head-of-list diversity metric are
    // exercised by the same code path that the unit tests cover.
    const { reordered, diversity } = reorderRecallResultsWithMmr(results, {
      lambda,
      topN,
    });

    try {
      log.info(
        `recall_mmr: section=${sectionId} kept=${diversity.kept}/${diversity.considered} ` +
          `headReorderCount=${diversity.headReorderCount} ` +
          `avgSimBefore=${diversity.avgPairwiseSimBefore.toFixed(3)} ` +
          `avgSimAfter=${diversity.avgPairwiseSimAfter.toFixed(3)} ` +
          `lambda=${lambda.toFixed(2)}`,
      );
    } catch {
      // Metrics must never break recall.
    }

    return reordered;
  }
}

/**
 * Recall section coordinator — extracted from the orchestrator (issue #1526).
 *
 * Owns the recall-output section-budgeting subsystem: section enablement
 * lookups, per-section maxChars/number resolution, section bucket appends,
 * budget-aware section truncation, and final ordered assembly of recall
 * sections within the configured character budget. Also builds the
 * LastRecallBudgetSummary and collects the sources used for X-ray tracing.
 *
 * Behavior-preserving move from orchestrator.ts — no logic changes; the
 * orchestrator constructs one instance and keeps thin delegating methods so
 * existing call sites (recallInternal, consolidation) continue to work.
 *
 * Config is accessed through a getter callback (not captured at construction)
 * so that post-construction reassignment of the orchestrator's live
 * `config` field is honored. This mirrors the ConversationIndexCoordinator /
 * TierMigrationCoordinator accessor pattern.
 */

import type { IncludedMemory, LastRecallBudgetSummary } from "../recall-state.js";
import { estimateTokenCount } from "../token-estimate.js";
import { graphemeUnits, truncateGraphemeSafe } from "../whitespace.js";
import type { PluginConfig, RecallSectionConfig } from "../types.js";

export interface RecallSectionAppendOptions {
  atomic?: boolean;
  memoryId?: string;
  memoryPath?: string;
  memoryNamespace?: string;
  /**
   * #2928 — state-view packet key (canonical `stateViewPacketKeys` root).
   * Atomic chunks sharing a packetKey are ONE evidence packet: the final
   * budget admits or drops them together, so a historical row can never
   * render without its linked successor. Absent on non-state rows.
   */
  packetKey?: string;
}

export interface RecallSectionChunk {
  content: string;
  atomic?: boolean;
  memoryId?: string;
  memoryPath?: string;
  memoryNamespace?: string;
  packetKey?: string;
}

export type RecallSectionBuckets = Map<
  string,
  Array<string | RecallSectionChunk>
>;

/**
 * Coordinator for the recall section budgeting + assembly subsystem.
 *
 * All methods are pure with respect to the coordinator's own state — they
 * read config via the getter and operate on the caller-provided section
 * buckets. No caches are held because the config-derived values are cheap
 * to recompute and the buckets are transient (per-recall-call).
 */
export class RecallSectionCoordinator {
  private readonly getConfig: () => PluginConfig;
  private readonly resolveSectionEnabled: (
    sectionId: string,
    defaultEnabled: boolean,
  ) => boolean;

  constructor(options: {
    getConfig: () => PluginConfig;
    resolveSectionEnabled?: (
      sectionId: string,
      defaultEnabled: boolean,
    ) => boolean;
  }) {
    this.getConfig = options.getConfig;
    // Default to the coordinator's own config-based check so standalone usage
    // (e.g. config-recall-pipeline tests) keeps self-gating. The orchestrator
    // injects its own resolver so appendRecallSection flows through the same
    // overridable isRecallSectionEnabled that the recallInternal computation
    // gates use — keeping compute-side and append-side enablement coherent
    // (seam 13). This preserves the recall-hardening test seam where tests
    // override orchestrator.isRecallSectionEnabled to isolate sections.
    this.resolveSectionEnabled =
      options.resolveSectionEnabled ??
      ((id, def) => this.isRecallSectionEnabled(id, def));
  }

  getRecallSectionEntry(
    sectionId: string,
  ): RecallSectionConfig | undefined {
    const pipeline = Array.isArray(this.getConfig().recallPipeline)
      ? this.getConfig().recallPipeline
      : [];
    return pipeline.find((entry) => entry.id === sectionId);
  }

  isRecallSectionEnabled(
    sectionId: string,
    defaultEnabled: boolean = true,
  ): boolean {
    const entry = this.getRecallSectionEntry(sectionId);
    if (!entry) return defaultEnabled;
    return entry.enabled !== false;
  }

  isSpecializedRecallSectionEnabled(
    sectionId: string,
    topLevelEnabled: boolean,
  ): boolean {
    const entry = this.getRecallSectionEntry(sectionId);
    if (!entry) return topLevelEnabled;
    return entry.enabled === true || (topLevelEnabled && entry.enabled !== false);
  }

  getRecallSectionMaxChars(
    sectionId: string,
  ): number | null | undefined {
    const entry = this.getRecallSectionEntry(sectionId);
    if (!entry) return undefined;
    if (entry.maxChars === null) return null;
    if (typeof entry.maxChars !== "number") return undefined;
    return Math.max(0, Math.floor(entry.maxChars));
  }

  getRecallSectionNumber(
    sectionId: string,
    key: keyof RecallSectionConfig,
  ): number | undefined {
    const entry = this.getRecallSectionEntry(sectionId);
    if (!entry) return undefined;
    const value = entry[key];
    if (typeof value !== "number" || !Number.isFinite(value)) return undefined;
    return Math.max(0, Math.floor(value));
  }

  appendRecallSection(
    sectionBuckets: RecallSectionBuckets,
    sectionId: string,
    content: string,
    options: RecallSectionAppendOptions = {},
  ): boolean {
    if (!this.resolveSectionEnabled(sectionId, true)) return false;
    const trimmed = content.trim();
    if (trimmed.length === 0) return false;

    const maxChars = this.getRecallSectionMaxChars(sectionId);
    let finalContent = trimmed;
    if (maxChars === 0) return false;
    if (
      !options.atomic &&
      typeof maxChars === "number" &&
      finalContent.length > maxChars
    ) {
      finalContent =
        sectionId === "profile"
          ? this.truncateProfileToBoundary(finalContent, maxChars)
          : `${truncateGraphemeSafe(finalContent, maxChars)}\n\n...(trimmed)\n`;
    }
    if (finalContent.length === 0) return false;
    const existing = sectionBuckets.get(sectionId) ?? [];

    if (options.atomic) {
      existing.push({
        content: finalContent,
        atomic: true,
        ...(options.memoryId ? { memoryId: options.memoryId } : {}),
        ...(options.memoryPath ? { memoryPath: options.memoryPath } : {}),
        ...(options.memoryNamespace
          ? { memoryNamespace: options.memoryNamespace }
          : {}),
        ...(options.packetKey ? { packetKey: options.packetKey } : {}),
      });
    } else {
      existing.push(finalContent);
    }
    sectionBuckets.set(sectionId, existing);
    return true;
  }

  truncateProfileToBoundary(content: string, maxChars: number): string {
    if (maxChars <= 0) return "";
    if (content.length <= maxChars) return content;
    const suffix = "\n\n...(profile context trimmed)";
    const contentLimit = maxChars - suffix.length;
    if (contentLimit <= 0) {
      const boundary = content.lastIndexOf("\n", maxChars);
      const clipped = boundary > 0
        ? content.slice(0, boundary)
        : truncateGraphemeSafe(content, maxChars);
      return clipped.trimEnd();
    }
    const boundary = content.lastIndexOf("\n", contentLimit);
    const clipped = boundary > 0
      ? content.slice(0, boundary)
      : truncateGraphemeSafe(content, contentLimit);
    return `${clipped.trimEnd()}${suffix}`;
  }
  truncateRecallSectionToBudget(
    content: string,
    maxChars: number,
    maxTokens?: number,
  ): string {
    if (maxChars <= 0 || maxTokens === 0) return "";
    const suffix = "\n\n...(memory context trimmed)";
    const charBounded =
      content.length <= maxChars
        ? content
        : maxChars <= suffix.length
          ? truncateGraphemeSafe(content, maxChars)
          : `${truncateGraphemeSafe(content, maxChars - suffix.length)}${suffix}`;
    if (maxTokens === undefined || estimateTokenCount(charBounded) <= maxTokens) {
      return charBounded;
    }
    const markerFits =
      maxChars > suffix.length && estimateTokenCount(suffix) <= maxTokens;
    const tokenSource = content.length > maxChars ? truncateGraphemeSafe(content, maxChars) : content;
    const units = graphemeUnits(tokenSource);
    let low = 0;
    let high = units.length;
    while (low < high) {
      const mid = Math.ceil((low + high) / 2);
      const prefix = units.slice(0, mid).join("");
      const candidate = markerFits ? `${prefix}${suffix}` : prefix;
      if (candidate.length <= maxChars && estimateTokenCount(candidate) <= maxTokens) {
        low = mid;
      } else {
        high = mid - 1;
      }
    }
    if (markerFits && low === 0) {
      low = 0;
      high = units.length;
      while (low < high) {
        const mid = Math.ceil((low + high) / 2);
        const prefix = units.slice(0, mid).join("");
        if (prefix.length <= maxChars && estimateTokenCount(prefix) <= maxTokens) {
          low = mid;
        } else {
          high = mid - 1;
        }
      }
      return units.slice(0, low).join("");
    }
    const prefix = units.slice(0, low).join("");
    return markerFits ? `${prefix}${suffix}` : prefix;
  }


  getRecallBudgetChars(override?: number): number {
    if (
      typeof override === "number" &&
      Number.isFinite(override) &&
      override >= 0
    ) {
      return Math.floor(override);
    }
    const configuredBudget = this.getConfig().recallBudgetChars;
    if (
      typeof configuredBudget === "number" &&
      Number.isFinite(configuredBudget) &&
      configuredBudget >= 0
    ) {
      return Math.floor(configuredBudget);
    }
    const tokenBudget = this.getConfig().maxMemoryTokens;
    if (
      typeof tokenBudget === "number" &&
      Number.isFinite(tokenBudget) &&
      tokenBudget >= 0
    ) {
      return Math.floor(tokenBudget * 4);
    }
    return 0;
  }

  assembleRecallSections(
    sectionBuckets: RecallSectionBuckets,
    budgetOverride?: number,
  ): {
    sections: string[];
    includedIds: string[];
    omittedIds: string[];
    truncated: boolean;
    finalChars: number;
    includedMemories: IncludedMemory[];
    includedMemoryIds: string[];
    includedMemoryPaths: string[];
    includedMemoryNamespaces: Array<string | undefined>;
    omittedMemoryIds: string[];
  } {
    type OrderedSection = { id: string; chunks: RecallSectionChunk[] };
    const normalizeChunk = (
      chunk: string | RecallSectionChunk,
    ): RecallSectionChunk =>
      typeof chunk === "string" ? { content: chunk } : chunk;
    const orderedSections: OrderedSection[] = [];
    const pipeline = Array.isArray(this.getConfig().recallPipeline)
      ? this.getConfig().recallPipeline
      : [];
    const orderedIds = pipeline
      .filter(
        (entry) =>
          entry.enabled !== false &&
          this.resolveSectionEnabled(entry.id, true),
      )
      .map((entry) => entry.id);
    const seen = new Set<string>();

    for (const id of orderedIds) {
      if (seen.has(id)) continue;
      const chunks = sectionBuckets.get(id);
      if (!chunks || chunks.length === 0) continue;
      orderedSections.push({
        id,
        chunks: chunks.map(normalizeChunk),
      });
      seen.add(id);
    }

    for (const [id, chunks] of sectionBuckets.entries()) {
      if (
        seen.has(id) ||
        chunks.length === 0 ||
        !this.resolveSectionEnabled(id, true)
      ) {
        continue;
      }
      orderedSections.push({
        id,
        chunks: chunks.map(normalizeChunk),
      });
      seen.add(id);
    }

    const budget = this.getRecallBudgetChars(budgetOverride);
    const tokenBudget = Math.max(0, Math.floor(this.getConfig().maxMemoryTokens));
    const candidateMemoryChunks =
      orderedSections
        .find((section) => section.id === "memories")
        ?.chunks.filter((chunk) => chunk.atomic && chunk.memoryId)
        .map((chunk) => ({
          id: chunk.memoryId!,
          namespace: chunk.memoryNamespace,
        })) ?? [];
    const candidateMemoryIds = candidateMemoryChunks.map((chunk) => chunk.id);
    if (budget === 0) {
      return {
        sections: [],
        includedIds: [],
        omittedIds: orderedSections.map((entry) => entry.id),
        truncated: orderedSections.length > 0,
        finalChars: 0,
        includedMemories: [],
        includedMemoryIds: [],
        includedMemoryPaths: [],
        includedMemoryNamespaces: [],
        omittedMemoryIds: candidateMemoryIds,
      };
    }

    const separator = "\n\n---\n\n";
    const sectionById = new Map(
      orderedSections.map((section) => [section.id, section]),
    );
    const allocationOrder = orderedSections.map((section) => section.id);
    const memorySection = sectionById.get("memories");
    const memoryIndex = allocationOrder.indexOf("memories");
    const memoryBudget = this.getRecallSectionMaxChars("memories") ?? budget;
    const memoryAllocationBudget = Math.min(budget, memoryBudget);
    let firstAtomicMemoryReserve:
      | { chars: number; tokens: number }
      | undefined;
    for (const chunk of memorySection?.chunks ?? []) {
      if (!chunk.atomic || chunk.content.length > memoryAllocationBudget) {
        continue;
      }
      const tokens = estimateTokenCount(chunk.content);
      if (tokens <= tokenBudget) {
        firstAtomicMemoryReserve = {
          chars: chunk.content.length,
          tokens,
        };
        break;
      }
    }
    const includedMemories: IncludedMemory[] = [];
    let usedChars = 0;
    let usedTokens = 0;
    let truncated = false;
    const selected = new Map<string, string>();

    for (const id of allocationOrder) {
      const section = sectionById.get(id);
      if (!section || selected.has(id)) continue;
      const separatorChars = selected.size > 0 ? separator.length : 0;
      const available = budget - usedChars - separatorChars;
      const separatorTokens = selected.size > 0 ? estimateTokenCount(separator) : 0;
      const availableTokens = tokenBudget - usedTokens - separatorTokens;
      const sectionMaxChars = this.getRecallSectionMaxChars(id);
      const reservedMemory =
        memoryIndex > allocationOrder.indexOf(id)
          ? firstAtomicMemoryReserve
          : undefined;
      const memoryReserveSeparatorChars = separator.length;
      const memoryReserveSeparatorTokens = estimateTokenCount(separator);
      const memoryReserve = reservedMemory
        ? reservedMemory.chars + memoryReserveSeparatorChars
        : 0;
      const availableAfterMemoryReserve = available - memoryReserve;
      const allocatedSectionAvailable =
        typeof sectionMaxChars === "number"
          ? Math.min(availableAfterMemoryReserve, sectionMaxChars)
          : availableAfterMemoryReserve;
      const availableAfterMemoryReserveTokens = reservedMemory
        ? availableTokens -
          reservedMemory.tokens -
          memoryReserveSeparatorTokens
        : availableTokens;
      const allocatedTokenAvailable = availableAfterMemoryReserveTokens;
      if (allocatedSectionAvailable <= 0 || allocatedTokenAvailable <= 0) {
        truncated = true;
        continue;
      }


      const atomicChunks = section.chunks.filter((chunk) => chunk.atomic);
      let finalContent: string;
      if (id !== "memories" || atomicChunks.length === 0) {
        const content = section.chunks.map((chunk) => chunk.content).join("\n\n");
        const profileLimit =
          id === "profile"
            ? Math.min(
                Math.floor(
                  budget *
                    (typeof this.getConfig().recallProfileMaxRatio === "number"
                      ? this.getConfig().recallProfileMaxRatio
                      : 0.3),
                ),
                this.getRecallSectionMaxChars("profile") ?? budget,
              )
            : allocatedSectionAvailable;
        const boundedContent =
          id === "profile"
            ? this.truncateProfileToBoundary(
                content,
                Math.min(profileLimit, allocatedSectionAvailable),
              )
            : content;
        finalContent = this.truncateRecallSectionToBudget(
          boundedContent,
          allocatedSectionAvailable,
          allocatedTokenAvailable,
        );
        if (!finalContent) {
          truncated = true;
          continue;
        }
        if (finalContent.length < content.length) truncated = true;
      } else {
        const firstAtomicIndex = section.chunks.findIndex((chunk) => chunk.atomic);
        let rendered = "";
        let includedAtomicCount = 0;
        let includedPostAtomicContent = false;
        const postAtomicContents: string[] = [];
        let includedLeadingContent = false;
        // #2928 — state-view packets: atomic chunks sharing a packetKey are
        // ONE evidence packet (a historical row plus its linked successor).
        // The packet renders as a block at the FIRST member's position,
        // members in incoming order, and is admitted or dropped together —
        // the final character/token budget can never emit one side alone.
        // Chunks without a packetKey keep the pre-#2928 per-row behavior.
        const packetFirstIndex = new Map<string, number>();
        const packetMembers = new Map<number, number[]>();
        for (const [index, chunk] of section.chunks.entries()) {
          if (!chunk.atomic || !chunk.packetKey) continue;
          const first = packetFirstIndex.get(chunk.packetKey);
          if (first === undefined) {
            packetFirstIndex.set(chunk.packetKey, index);
            packetMembers.set(index, [index]);
          } else {
            packetMembers.get(first)!.push(index);
          }
        }
        const admitMemoryRefs = (memberIndexes: readonly number[]): void => {
          for (const memberIndex of memberIndexes) {
            const member = section.chunks[memberIndex]!;
            if (member.memoryId && member.memoryPath) {
              includedMemories.push(
                member.memoryNamespace
                  ? { id: member.memoryId, path: member.memoryPath, namespace: member.memoryNamespace }
                  : { id: member.memoryId, path: member.memoryPath },
              );
            }
          }
        };
        for (const [index, chunk] of section.chunks.entries()) {
          const members = chunk.atomic ? packetMembers.get(index) : undefined;
          if (chunk.atomic && chunk.packetKey && members === undefined) {
            // Non-first packet member: decided with its block at the first
            // member's position — never admitted alone (#2928).
            continue;
          }
          const memberIndexes = members ?? [index];
          const content = members
            ? members.map((memberIndex) => section.chunks[memberIndex]!.content).join("\n\n")
            : chunk.content;
          if (
            !chunk.atomic &&
            includedAtomicCount === 0 &&
            index < firstAtomicIndex
          ) {
            const candidate = rendered
              ? `${rendered}\n\n${content}`
              : content;
            if (
              candidate.length <= allocatedSectionAvailable &&
              estimateTokenCount(candidate) <= allocatedTokenAvailable
            ) {
              rendered = candidate;
              includedLeadingContent = true;
            } else {
              truncated = true;
            }
            continue;
          }

          const candidate = rendered
            ? `${rendered}\n\n${content}`
            : content;
          if (
            candidate.length > allocatedSectionAvailable ||
            estimateTokenCount(candidate) > allocatedTokenAvailable
          ) {
            if (
              chunk.atomic &&
              includedAtomicCount === 0 &&
              includedLeadingContent &&
              content.length <= allocatedSectionAvailable &&
              estimateTokenCount(content) <= allocatedTokenAvailable
            ) {
              rendered = content;
              includedLeadingContent = false;
              includedAtomicCount += memberIndexes.length;
              admitMemoryRefs(memberIndexes);
              continue;
            }
            if (
              !chunk.atomic &&
              includedAtomicCount === 0 &&
              includedLeadingContent &&
              content.length <= allocatedSectionAvailable &&
              estimateTokenCount(content) <= allocatedTokenAvailable
            ) {
              rendered = content;
              includedLeadingContent = false;
              includedPostAtomicContent = true;
              postAtomicContents.push(content);
              continue;
            }
            truncated = true;
            continue;
          }

          rendered = candidate;
          if (chunk.atomic) {
            includedAtomicCount += memberIndexes.length;
            admitMemoryRefs(memberIndexes);
          } else {
            includedPostAtomicContent = true;
            postAtomicContents.push(content);
          }
        }
        if (includedAtomicCount === 0) {
          if (includedPostAtomicContent) {
            rendered = postAtomicContents.join("\n\n");
          } else {
            rendered = "";
            truncated = true;
          }
        } else if (includedAtomicCount < atomicChunks.length) {
          truncated = true;
        }
        finalContent = rendered;
      }

      if (!finalContent) {
        truncated = true;
        continue;
      }
      selected.set(id, finalContent);
      usedChars += separatorChars + finalContent.length;
      usedTokens += separatorTokens + estimateTokenCount(finalContent);
    }

    const sections: string[] = [];
    const includedIds: string[] = [];
    const omittedIds: string[] = [];
    const emittedIds = new Set<string>();
    for (const section of orderedSections) {
      if (emittedIds.has(section.id)) continue;
      emittedIds.add(section.id);
      const content = selected.get(section.id);
      if (content) {
        sections.push(content);
        includedIds.push(section.id);
      } else {
        omittedIds.push(section.id);
      }
    }
    return {
      sections,
      includedIds,
      omittedIds,
      truncated,
      finalChars: usedChars,
      includedMemories,
      includedMemoryIds: includedMemories.map((memory) => memory.id),
      includedMemoryPaths: includedMemories.map((memory) => memory.path),
      includedMemoryNamespaces: includedMemories.map((memory) => memory.namespace),
      omittedMemoryIds: (() => {
        const includedKeys = new Set(
          includedMemories.map(
            (memory) => `${memory.namespace ?? ""}\u0000${memory.id}`,
          ),
        );
        return candidateMemoryChunks
          .filter(
            (chunk) =>
              !includedKeys.has(`${chunk.namespace ?? ""}\u0000${chunk.id}`),
          )
          .map((chunk) => chunk.id);
      })(),
    };
  }

  buildLastRecallBudgetSummary(options: {
    requestedTopK?: number;
    recallResultLimit: number;
    qmdFetchLimit: number;
    qmdHybridFetchLimit: number;
    finalContextChars?: number;
    truncated?: boolean;
    includedSections?: string[];
    omittedMemoryIds?: string[];
    omittedSections?: string[];
  }): LastRecallBudgetSummary {
    return {
      requestedTopK: options.requestedTopK,
      appliedTopK: options.recallResultLimit,
      recallBudgetChars: this.getRecallBudgetChars(),
      maxMemoryTokens: this.getConfig().maxMemoryTokens,
      qmdFetchLimit: options.qmdFetchLimit,
      qmdHybridFetchLimit: options.qmdHybridFetchLimit,
      finalContextChars: options.finalContextChars,
      truncated: options.truncated,
      omittedMemoryIds: [...(options.omittedMemoryIds ?? [])],
      includedSections: [...(options.includedSections ?? [])],
      omittedSections: [...(options.omittedSections ?? [])],
    };
  }

  collectLastRecallSources(
    sectionBuckets: RecallSectionBuckets,
    recallSource:
      | "none"
      | "hot_qmd"
      | "hot_embedding"
      | "cold_fallback"
      | "recent_scan",
  ): string[] {
    const used = new Set<string>();
    if (recallSource !== "none") {
      used.add(recallSource);
    }
    for (const [sectionId, chunks] of sectionBuckets.entries()) {
      if (chunks.length > 0) {
        used.add(sectionId);
      }
    }
    return [...used];
  }
}

/**
 * QMD result resolver — extracted from the orchestrator (issue #1526 seam 11).
 *
 * Owns the subsystem that resolves a QMD search-result path back to the
 * concrete `MemoryFile` (and its owning namespace/storage). Three concerns
 * live here:
 *
 *   - `readQmdResultMemory` — resolve a result path to a `MemoryFile`,
 *     handling cold-tier collections, namespace-prefixed collections, and
 *     absolute vs relative paths.
 *   - `resolveColdQmdResultForRecall` — wrap a result with its owner
 *     namespace so the recall pipeline can scope-filter candidates.
 *   - `storageForAbsoluteQmdResultPath` — find the `StorageManager` whose
 *     directory tree contains an absolute result path.
 *
 * Behavior-preserving move from orchestrator.ts — no logic changes. The
 * orchestrator constructs one instance and keeps thin delegating methods so
 * existing call sites (recallInternal, applyColdFallbackPipeline,
 * loadSearchResultMemoryMap, suggestLinksForMemory, and the
 * RecallRerankCoordinator callback) continue to work.
 *
 * Config, the storage router, and the orchestrator's namespace-resolution
 * helpers are accessed through getter callbacks (not captured at
 * construction) so that post-construction reassignment of the
 * orchestrator's live fields is honored. This mirrors the
 * RecallRerankCoordinator / ConversationIndexCoordinator accessor pattern.
 */

import { existsSync } from "node:fs";
import path from "node:path";
import { resolveNamespaceCapabilities } from "../capabilities.js";
import type { StorageManager } from "../index.js";
import { log } from "../logger.js";
import { namespaceIdentityFromToken } from "../namespaces/identity.js";
import { normalizeQmdResultPath, resolveNamespaceResultPath } from "../namespaces/search.js";
import { SecureStoreLockedError } from "../secure-store/index.js";
import { isPathInsideStorageRoot } from "../storage-paths.js";
import { isSupportPassportPrivateMemory } from "../support-passport/card-projection.js";
import type { MemoryFile, PluginConfig, QmdSearchResult } from "../types.js";
import { ALL_CATEGORY_DIRS } from "../utils/category-dir.js";

const INTERNAL_QMD_ROOTS = new Set([
  ...ALL_CATEGORY_DIRS,
  "activity",
  "archive",
  "artifacts",
  "cold",
  "config",
  "entities",
  "identity",
  "locations",
  "meetings",
  "namespaces",
  "state",
  "summaries",
  "transcripts",
  "wearables",
  "work",
  "workspace",
]);

const PRIVATE_RESULT_RESOLUTION_CONCURRENCY = 16;

/**
 * Split a relative QMD result path into its collection prefix and the
 * remainder. Returns `null` for absolute paths, date-only prefixes, or
 * paths with no collection separator.
 */
export function qmdCollectionPathParts(resultPath: string): {
  collection: string;
  relativePath: string;
} | null {
  if (!resultPath || path.isAbsolute(resultPath)) return null;
  if (resultPath.trim().startsWith("qmd://")) {
    try {
      const parsed = new URL(resultPath.trim());
      if (parsed.protocol !== "qmd:" || !parsed.hostname) return null;
      const collection = parsed.hostname;
      const relativePath = normalizeQmdResultPath(resultPath, collection).replace(/\\/g, "/").replace(/^\/+/, "");
      if (!relativePath) return null;
      return { collection, relativePath };
    } catch {
      return null;
    }
  }
  const normalized = resultPath.replace(/\\/g, "/").replace(/^\/+/, "");
  const slashIndex = normalized.indexOf("/");
  if (slashIndex <= 0 || slashIndex >= normalized.length - 1) return null;
  const collection = normalized.slice(0, slashIndex);
  if (/^\d{4}-\d{2}-\d{2}$/.test(collection)) return null;
  return {
    collection,
    relativePath: normalized.slice(slashIndex + 1),
  };
}

/**
 * Build the set of on-disk candidate paths to probe for a QMD result,
 * constrained to the storage root so a result path can never escape the
 * namespace directory.
 */
export function qmdResultPathCandidates(storageDir: string, resultPath: string): string[] {
  const candidates = new Set<string>();
  const storageRoot = path.resolve(storageDir);
  const addCandidate = (candidate: string) => {
    const resolved = path.resolve(candidate);
    if (isPathInsideStorageRoot(storageRoot, resolved)) {
      candidates.add(resolved);
    }
  };
  const addRelativeCandidates = (relativePath: string) => {
    const normalized = relativePath.replace(/\\/g, "/").replace(/^\/+/, "");
    if (!normalized) return;
    addCandidate(path.join(storageRoot, normalized));
    if (/^\d{4}-\d{2}-\d{2}\//.test(normalized)) {
      addCandidate(path.join(storageRoot, "facts", normalized));
    }
  };

  if (path.isAbsolute(resultPath)) {
    addCandidate(resultPath);
    // Daemon-mode results can arrive pre-absolutized against the storage
    // root while the file lives under facts/<date>/ (hot-facts collection
    // registered at the facts/ subtree — issue #2111). Mirror the relative
    // branch's facts/ fallback; addCandidate re-checks containment.
    const relative = path.relative(storageRoot, path.resolve(resultPath));
    if (relative && !relative.startsWith("..") && !path.isAbsolute(relative)) {
      const normalized = relative.split(path.sep).join("/");
      if (/^\d{4}-\d{2}-\d{2}\//.test(normalized)) {
        addCandidate(path.join(storageRoot, "facts", normalized));
      }
    }
  } else {
    addRelativeCandidates(resultPath);
  }

  return [...candidates];
}

/** Canonicalize flat hot-memory identities before merging with native hits (#3194).
 * This is a path-only map: no candidates, collections or namespace scopes are removed.
 * Cold/explicit foreign collections keep their existing owner-resolution path.
 */
export function normalizeFlatQmdResults(
  results: QmdSearchResult[],
  config: PluginConfig,
  collection = config.qmdCollection,
): QmdSearchResult[] {
  if (!collection || resolveNamespaceCapabilities(config).namespaces || collection !== config.qmdCollection) return results;
  return results.map((result) => ({
    ...result,
    path: withHotFactsPath(config.memoryDir, resolveNamespaceResultPath(config.memoryDir, collection, result.path)),
  }));
}

/** A hot-facts collection registered at the facts/ subtree returns date-relative paths (#2111); meet the loaded memory's path. */
function withHotFactsPath(memoryDir: string, resolved: string): string {
  const relative = path.relative(path.resolve(memoryDir), resolved).split(path.sep).join("/");
  if (!/^\d{4}-\d{2}-\d{2}\//.test(relative) || existsSync(resolved)) return resolved;
  const hot = path.join(path.resolve(memoryDir), "facts", relative);
  return existsSync(hot) ? hot : resolved;
}

/**
 * Extract a non-empty `dir` from a storage, returning `null` when the
 * property is absent or not a non-empty string at runtime. Proxy-backed
 * fake storages used in recall paths may not provide a real `dir`, so
 * every caller must handle the null case (skip or fall back to a direct
 * `readMemoryByPath`).
 */
function storageDirOrNull(storage: StorageManager): string | null {
  const dir = storage.dir;
  return typeof dir === "string" && dir.length > 0 ? dir : null;
}

/**
 * Coordinator for resolving QMD search-result paths to concrete memory
 * files and their owning namespace/storage.
 */
export class QmdResultResolver {
  private readonly getConfig: () => PluginConfig;
  private readonly storageFor: (namespace: string) => Promise<StorageManager>;
  private readonly storageDirNamespace: (storageDir: string) => string;
  private readonly qmdCollectionNamespaceFromPrefix: (collectionPrefix: string) => string | null;
  private readonly namespaceFromPath: (p: string) => string;

  constructor(options: {
    getConfig: () => PluginConfig;
    storageFor: (namespace: string) => Promise<StorageManager>;
    storageDirNamespace: (storageDir: string) => string;
    qmdCollectionNamespaceFromPrefix: (collectionPrefix: string) => string | null;
    namespaceFromPath: (p: string) => string;
  }) {
    this.getConfig = options.getConfig;
    this.storageFor = options.storageFor;
    this.storageDirNamespace = options.storageDirNamespace;
    this.qmdCollectionNamespaceFromPrefix = options.qmdCollectionNamespaceFromPrefix;
    this.namespaceFromPath = options.namespaceFromPath;
  }

  async readQmdResultMemory(
    resultPath: string,
    fallbackStorage: StorageManager,
    recallNamespaces: readonly string[] = [],
    preferredNamespace?: string
  ): Promise<MemoryFile | null> {
    const parts = qmdCollectionPathParts(resultPath);
    const fallbackStorageDir = storageDirOrNull(fallbackStorage);
    const config = this.getConfig();
    const coldCollection = config.qmdColdCollection ?? "openclaw-engram-cold";
    const fallbackResultPath =
      resultPath.trim().startsWith("qmd://") && parts?.collection === config.qmdCollection
        ? parts.relativePath
        : resultPath;
    if (parts && parts.collection === coldCollection) {
      const storages: StorageManager[] = [];
      const seenStorageDirs = new Set<string>();
      const addStorage = (storage: StorageManager): void => {
        const storageDir = storageDirOrNull(storage);
        const storageKey = storageDir ? path.resolve(storageDir) : `storage-without-dir-${storages.length}`;
        if (seenStorageDirs.has(storageKey)) return;
        seenStorageDirs.add(storageKey);
        storages.push(storage);
      };

      const fallbackNamespace =
        fallbackStorageDir !== null ? this.storageDirNamespace(fallbackStorageDir) : config.defaultNamespace;
      if (
        recallNamespaces.length === 0 ||
        !resolveNamespaceCapabilities(config).namespaces ||
        recallNamespaces.includes(fallbackNamespace)
      ) {
        addStorage(fallbackStorage);
      }

      if (recallNamespaces.length > 0) {
        for (const namespace of recallNamespaces) {
          try {
            addStorage(await this.storageFor(namespace));
          } catch (err) {
            log.debug("qmd cold result namespace storage lookup skipped", {
              path: resultPath,
              namespace,
              error: (err as Error).message,
            });
          }
        }
      }

      for (const storage of storages) {
        const storageDir = storageDirOrNull(storage);
        if (!storageDir) {
          const memory = await storage.readMemoryByPath(resultPath);
          if (memory) return memory;
          continue;
        }
        try {
          const coldRoot = path.join(storageDir, "cold");
          for (const candidate of qmdResultPathCandidates(coldRoot, parts.relativePath)) {
            const memory = await storage.readMemoryByPath(candidate);
            if (memory) return memory;
          }
        } catch (err) {
          if (err instanceof SecureStoreLockedError) throw err;
          log.debug("qmd cold result path lookup failed open", {
            path: resultPath,
            collection: coldCollection,
            error: (err as Error).message,
          });
        }
      }
      return null;
    }
    const collectionNamespace = parts ? this.qmdCollectionNamespaceFromPrefix(parts.collection) : null;

    if (parts && collectionNamespace) {
      try {
        const collectionStorage = await this.storageFor(collectionNamespace);
        for (const candidate of qmdResultPathCandidates(collectionStorage.dir, parts.relativePath)) {
          const memory = await collectionStorage.readMemoryByPath(candidate);
          if (memory) return memory;
        }
        return null;
      } catch (err) {
        if (err instanceof SecureStoreLockedError) throw err;
        log.debug("qmd result namespace path lookup failed open", {
          path: resultPath,
          namespace: collectionNamespace,
          error: (err as Error).message,
        });
        return null;
      }
    }

    if (preferredNamespace) {
      try {
        const preferredStorage = await this.storageFor(preferredNamespace);
        for (const candidate of qmdResultPathCandidates(preferredStorage.dir, fallbackResultPath)) {
          const memory = await preferredStorage.readMemoryByPath(candidate);
          if (memory) return memory;
        }
      } catch (err) {
        if (err instanceof SecureStoreLockedError) throw err;
        log.debug("qmd preferred namespace path lookup failed open", {
          path: resultPath,
          namespace: preferredNamespace,
          error: (err as Error).message,
        });
      }
      // The caller supplied an explicit owning namespace. For a relative path
      // the preferred store was the only correct lead, so a miss means the hit
      // is stale/deleted — do NOT fall through to the default store and validate
      // a same-relative-path memory from the wrong namespace (#2020). Absolute
      // paths still fall through: the absolute branch resolves the true owner.
      if (!path.isAbsolute(fallbackResultPath)) return null;
    }
    if (path.isAbsolute(fallbackResultPath)) {
      if (!fallbackStorageDir) {
        return await fallbackStorage.readMemoryByPath(fallbackResultPath);
      }
      const ownerStorage = await this.storageForAbsoluteQmdResultPath(
        fallbackResultPath,
        fallbackStorage,
        recallNamespaces
      );
      if (!ownerStorage) return null;
      for (const candidate of qmdResultPathCandidates(ownerStorage.dir, fallbackResultPath)) {
        const memory = await ownerStorage.storage.readMemoryByPath(candidate);
        if (memory) return memory;
      }
      return null;
    }

    if (!fallbackStorageDir) {
      return await fallbackStorage.readMemoryByPath(fallbackResultPath);
    }
    for (const candidate of qmdResultPathCandidates(fallbackStorageDir, fallbackResultPath)) {
      const memory = await fallbackStorage.readMemoryByPath(candidate);
      if (memory) return memory;
    }
    return null;
  }

  async filterPrivateSearchResults(
    results: QmdSearchResult[],
    fallbackStorage: StorageManager,
    namespaces: readonly string[] = [],
    preserveUnresolved = false,
    visibilityCache = new Map<string, boolean>()
  ): Promise<QmdSearchResult[]> {
    const namespaceKey = namespaces.join("\0");
    const entries = results
      .filter((result) => Boolean(result.path))
      .map((result) => ({
        result,
        cacheKey: `${namespaceKey}\0${preserveUnresolved ? "1" : "0"}\0${result.namespace ?? ""}\0${result.path}`,
      }));
    const pending = new Map<string, QmdSearchResult>();
    for (const { result, cacheKey } of entries) {
      if (!visibilityCache.has(cacheKey)) pending.set(cacheKey, result);
    }
    const unresolved = [...pending];
    for (let offset = 0; offset < unresolved.length; offset += PRIVATE_RESULT_RESOLUTION_CONCURRENCY) {
      await Promise.all(
        unresolved.slice(offset, offset + PRIVATE_RESULT_RESOLUTION_CONCURRENCY).map(async ([cacheKey, result]) => {
          visibilityCache.set(
            cacheKey,
            await this.isVisibleSearchResult(result, fallbackStorage, namespaces, preserveUnresolved)
          );
        })
      );
    }
    return entries.filter(({ cacheKey }) => visibilityCache.get(cacheKey) === true).map(({ result }) => result);
  }

  private async isVisibleSearchResult(
    result: QmdSearchResult,
    fallbackStorage: StorageManager,
    namespaces: readonly string[],
    preserveUnresolved: boolean
  ): Promise<boolean> {
    const parts = qmdCollectionPathParts(result.path);
    const config = this.getConfig();
    const collectionIsKnownInternal = parts !== null && INTERNAL_QMD_ROOTS.has(parts.collection);
    const collectionIsConfigured =
      parts !== null &&
      (parts.collection === config.qmdCollection ||
        parts.collection === (config.qmdColdCollection ?? "openclaw-engram-cold") ||
        this.qmdCollectionNamespaceFromPrefix(parts.collection) !== null);
    let memory = await this.readQmdResultMemory(result.path, fallbackStorage, namespaces, result.namespace);
    if (!memory && parts && !collectionIsKnownInternal && !collectionIsConfigured) {
      memory = await this.readQmdResultMemory(parts.relativePath, fallbackStorage, namespaces, result.namespace);
    }
    const absoluteInsideMemoryRoot =
      path.isAbsolute(result.path) &&
      isPathInsideStorageRoot(path.resolve(config.memoryDir), path.resolve(result.path));
    const hasExplicitQmdCollection = result.path.trim().startsWith("qmd://");
    const unresolvedInternalPath =
      !memory &&
      (absoluteInsideMemoryRoot ||
        (collectionIsKnownInternal && (!preserveUnresolved || hasExplicitQmdCollection)) ||
        (hasExplicitQmdCollection && collectionIsConfigured));
    const unresolvedExternalCollection =
      !memory &&
      ((parts !== null && !collectionIsKnownInternal && !collectionIsConfigured) ||
        (path.isAbsolute(result.path) &&
          !isPathInsideStorageRoot(path.resolve(config.memoryDir), path.resolve(result.path))));
    return (
      (memory !== null && !isSupportPassportPrivateMemory(memory)) ||
      (!memory && !unresolvedInternalPath && (preserveUnresolved || unresolvedExternalCollection))
    );
  }

  async resolveColdQmdResultForRecall(
    result: QmdSearchResult,
    fallbackStorage: StorageManager,
    recallNamespaces: readonly string[] = []
  ): Promise<{ namespace: string; result: QmdSearchResult } | null> {
    const memory = await this.readQmdResultMemory(result.path, fallbackStorage, recallNamespaces, result.namespace);
    if (!memory) return null;

    let ownerNamespace: string | null = null;
    if (path.isAbsolute(memory.path)) {
      const ownerStorage = await this.storageForAbsoluteQmdResultPath(memory.path, fallbackStorage, recallNamespaces);
      ownerNamespace = ownerStorage?.namespace ?? null;
      if (!ownerNamespace && resolveNamespaceCapabilities(this.getConfig()).namespaces) return null;
    }
    ownerNamespace ??= this.namespaceFromPath(memory.path);
    if (recallNamespaces.length > 0 && !recallNamespaces.includes(ownerNamespace)) {
      return null;
    }

    return {
      namespace: ownerNamespace,
      result: {
        ...result,
        docid: result.docid || memory.frontmatter.id,
        path: memory.path,
        snippet: result.snippet || memory.content.slice(0, 400),
        origin: memory.frontmatter.origin,
      },
    };
  }

  async storageForAbsoluteQmdResultPath(
    resultPath: string,
    fallbackStorage: StorageManager,
    recallNamespaces: readonly string[] = []
  ): Promise<{ storage: StorageManager; dir: string; namespace: string } | null> {
    const resolvedPath = path.resolve(resultPath);
    const config = this.getConfig();
    const memoryRoot = path.resolve(config.memoryDir);
    const namespacesRoot = path.join(memoryRoot, "namespaces");
    const fallbackStorageDir = storageDirOrNull(fallbackStorage);
    const matches: Array<{ storage: StorageManager; dir: string; namespace: string }> = [];
    const seenDirs = new Set<string>();

    const maybeAddStorage = (storage: StorageManager, namespace: string) => {
      const storageDir = storageDirOrNull(storage);
      if (!storageDir) return;
      const candidateRoot = path.resolve(storageDir);
      if (seenDirs.has(candidateRoot)) return;
      if (!isPathInsideStorageRoot(candidateRoot, resolvedPath)) return;
      if (candidateRoot === memoryRoot && isPathInsideStorageRoot(namespacesRoot, resolvedPath)) {
        return;
      }
      seenDirs.add(candidateRoot);
      matches.push({ storage, dir: candidateRoot, namespace });
    };

    const fallbackNamespace =
      fallbackStorageDir !== null ? this.storageDirNamespace(fallbackStorageDir) : config.defaultNamespace;
    maybeAddStorage(fallbackStorage, fallbackNamespace);

    const candidateNamespaces = new Set<string>();
    candidateNamespaces.add(config.defaultNamespace);
    candidateNamespaces.add(config.sharedNamespace);
    for (const ns of recallNamespaces) {
      candidateNamespaces.add(ns);
    }
    if (isPathInsideStorageRoot(namespacesRoot, resolvedPath)) {
      const relativeToNamespaces = path.relative(namespacesRoot, resolvedPath);
      const [namespaceSegment] = relativeToNamespaces.split(/[\\/]/);
      if (namespaceSegment) {
        candidateNamespaces.add(namespaceIdentityFromToken(namespaceSegment) ?? namespaceSegment);
      }
    }
    for (const policy of config.namespacePolicies ?? []) {
      candidateNamespaces.add(policy.name);
    }

    for (const ns of candidateNamespaces) {
      if (!ns) continue;
      try {
        maybeAddStorage(await this.storageFor(ns), ns);
      } catch {}
    }

    matches.sort((a, b) => b.dir.length - a.dir.length);
    return matches[0] ?? null;
  }
}

/**
 * Contradiction-linking coordinator — extracted from the orchestrator (issue #1526).
 *
 * Owns the write-path semantic-analysis subsystem: contradiction detection
 * (QMD similarity search + LLM verification), deferred contradiction
 * auto-resolve (#1645 — retires superseded memories only after the new write's
 * tombstone status is known), and memory link suggestion. The orchestrator
 * constructs one instance and keeps thin delegating methods so existing call
 * sites (writeMemory fact-write branches) continue to work.
 *
 * Config, storage, search, namespace resolution, and the extraction engine are
 * accessed through getter callbacks (not captured at construction) so that
 * post-construction reassignment of the orchestrator's live fields is honored.
 * This mirrors the RecallRerankCoordinator / ConversationIndexCoordinator
 * accessor pattern.
 */

import type {
  MemoryFile,
  MemoryLink,
  PluginConfig,
  QmdSearchResult,
} from "../types.js";
import { coerceBool } from "../connectors/coerce.js";
// StorageManager type comes from the package barrel (type-only) so this
// module does not add a direct storage.ts import (ratchet #1533).
import type { StorageManager } from "../index.js";
import type { ExtractionEngine } from "../extraction.js";
import { log } from "../logger.js";
import { resolveIndexingCapabilities } from "../capabilities.js";
import { deindexMemoryAsync } from "../temporal-index.js";
import {
  inferLocalizationMemoryStatus,
  localizeUpdateCandidates,
  mergeMemorySnapshots,
} from "./update-localization.js";
import {
  isDependencyPropagationEnabled,
  propagateInvalidation,
  type PropagationEvent,
} from "./dependency-propagation.js";
import type {
  DependencyPropagationDeliveryPort,
  DependencyPropagationPreparationToken,
} from "./dependency-propagation-delivery.js";
import { isSupportPassportPrivateMemory } from "../support-passport/card-projection.js";

/** Result type of {@link ContradictionLinkingCoordinator.checkForContradiction}. */
export interface ContradictionResult {
  supersededId: string;
  confidence: number;
  reason: string;
  supersededPath: string;
  supersededCreated: string;
  supersededTags: string[];
}

/** Outcome of the post-write contradiction retirement attempt. */
export type ContradictionResolveOutcome =
  | "not_attempted"
  | "blocked"
  | "resolved"
  | "lost_race"
  | "supersede_failed"
  | "supersedes_clear_failed";

/**
 * Subset of {@link ContradictionResult} used by
 * {@link ContradictionLinkingCoordinator.applyDeferredContradictionResolve}.
 * The deferred resolve runs AFTER writeMemory and only needs the supersede
 * target fields (not confidence, which the caller already consumed).
 */
export interface ContradictionResolveTarget {
  supersededId: string;
  reason: string;
  supersededPath: string;
  supersededCreated: string;
  supersededTags: string[];
}

/**
 * Coordinator for the contradiction-detection + memory-linking subsystem.
 *
 * The three methods mirror the orchestrator's former private methods
 * `checkForContradiction`, `applyDeferredContradictionResolve`, and
 * `suggestLinksForMemory` byte-for-byte in logic.
 */
export class ContradictionLinkingCoordinator {
  private readonly getConfig: () => PluginConfig;
  private readonly isSearchAvailable: () => boolean;
  private readonly searchAcrossNamespaces: (options: {
    query: string;
    namespaces?: string[];
    maxResults?: number;
    mode?: "search" | "hybrid" | "bm25" | "vector";
  }) => Promise<QmdSearchResult[]>;
  private readonly extractMemoryIdsFromResults: (
    results: QmdSearchResult[],
  ) => string[];
  private readonly namespaceFromPath: (p: string) => string;
  private readonly storageForNamespace: (
    namespace: string,
  ) => Promise<StorageManager>;
  private readonly getExtraction: () => ExtractionEngine;
  private readonly storageDirNamespace: (storageDir: string) => string;
  private readonly getDependencyPropagationDelivery: () => DependencyPropagationDeliveryPort;

  constructor(options: {
    getConfig: () => PluginConfig;
    isSearchAvailable: () => boolean;
    searchAcrossNamespaces: (options: {
      query: string;
      namespaces?: string[];
      maxResults?: number;
      mode?: "search" | "hybrid" | "bm25" | "vector";
    }) => Promise<QmdSearchResult[]>;
    extractMemoryIdsFromResults: (results: QmdSearchResult[]) => string[];
    namespaceFromPath: (p: string) => string;
    storageForNamespace: (namespace: string) => Promise<StorageManager>;
    getExtraction: () => ExtractionEngine;
    storageDirNamespace?: (storageDir: string) => string;
    getDependencyPropagationDelivery?: () => DependencyPropagationDeliveryPort;
  }) {
    this.getConfig = options.getConfig;
    this.isSearchAvailable = options.isSearchAvailable;
    this.searchAcrossNamespaces = options.searchAcrossNamespaces;
    this.extractMemoryIdsFromResults = options.extractMemoryIdsFromResults;
    this.namespaceFromPath = options.namespaceFromPath;
    this.storageForNamespace = options.storageForNamespace;
    this.getExtraction = options.getExtraction;
    this.storageDirNamespace = options.storageDirNamespace ?? (() => "default");
    this.getDependencyPropagationDelivery =
      options.getDependencyPropagationDelivery ??
      (() => {
        throw new Error("dependency propagation delivery is unavailable");
      });
  }

  /**
   * Check if a new memory contradicts an existing one.
   * Uses QMD to find similar memories, then LLM to verify contradiction.
   */
  async checkForContradiction(
    content: string,
    category: string,
    namespaceScope: string,
    anchor?: {
      entityRef?: string;
      structuredAttributes?: Record<string, string>;
      attributes?: Record<string, string>;
      storageSnapshot?: MemoryFile[];
    },
  ): Promise<ContradictionResult | null> {
    const config = this.getConfig();
    const localization = config.contradictionLocalization;
    const anchorEnabled = coerceBool(localization?.anchorEnabled) ?? true;
    if (!anchorEnabled) {
      if (!this.isSearchAvailable()) return null;
      const results = await this.searchAcrossNamespaces({
        query: content,
        namespaces: [namespaceScope],
        maxResults: 5,
        mode: "search",
      });
      for (const result of results) {
        if (result.score < config.contradictionSimilarityThreshold) continue;
        const memoryId = this.extractMemoryIdsFromResults([result])[0];
        if (!memoryId) continue;
        const resultNamespace = this.namespaceFromPath(result.path);
        if (resultNamespace !== namespaceScope) continue;
        const resultStorage = await this.storageForNamespace(resultNamespace);
        const existingMemory = await resultStorage.getMemoryById(memoryId);
        if (!existingMemory) continue;
        if (isSupportPassportPrivateMemory(existingMemory)) continue;
        if (inferLocalizationMemoryStatus(existingMemory, resultStorage.dir) !== "active") continue;
        const verification = await this.getExtraction().verifyContradiction(
          { content, category },
          {
            id: existingMemory.frontmatter.id,
            content: existingMemory.content,
            category: existingMemory.frontmatter.category,
            created: existingMemory.frontmatter.created,
          },
        );
        if (!verification) continue;
        if (
          verification.isContradiction &&
          verification.confidence >= config.contradictionMinConfidence
        ) {
          if (verification.whichIsNewer === "first") {
            log.info(
              `detected contradiction (confidence: ${verification.confidence}): ${existingMemory.frontmatter.id} vs new memory — existing is newer, incoming fact is stale`,
            );
            continue;
          }
          log.info(
            `detected contradiction (confidence: ${verification.confidence}): ${existingMemory.frontmatter.id} vs new memory${config.contradictionAutoResolve ? " (auto-resolved)" : " (queued for manual review)"}`,
          );
          return {
            supersededId: existingMemory.frontmatter.id,
            confidence: verification.confidence,
            reason: verification.reasoning,
            supersededPath: existingMemory.path,
            supersededCreated: existingMemory.frontmatter.created,
            supersededTags: existingMemory.frontmatter.tags ?? [],
          };
        }
      }
      return null;
    }

    const localizationOptions = localization ?? {
      anchorEnabled: true,
      anchorCandidates: 5,
      searchCandidates: 5,
      maxCandidates: 8,
    };
    const resultStorage = await this.storageForNamespace(namespaceScope);
    let anchorSnapshot = anchor?.storageSnapshot;
    const anchorLimit = localizationOptions.anchorCandidates;
    if (
      !anchorSnapshot &&
      Number.isInteger(anchorLimit) &&
      anchorLimit > 0 &&
      typeof anchor?.entityRef === "string" &&
      anchor?.entityRef.trim().length > 0
    ) {
      const [hot, cold] = await Promise.all([
        resultStorage.readAllMemories(),
        typeof resultStorage.readAllColdMemories === "function"
          ? resultStorage.readAllColdMemories()
          : Promise.resolve([]),
      ]);
      anchorSnapshot = mergeMemorySnapshots(hot, cold, resultStorage.dir);
    }
    anchorSnapshot = anchorSnapshot?.filter(
      (memory) => !isSupportPassportPrivateMemory(memory),
    );
    const anchorMemoryById = anchorSnapshot
      ? new Map(anchorSnapshot.map((memory) => [memory.frontmatter.id, memory]))
      : undefined;
    const candidates = await localizeUpdateCandidates(
      {
        storage: anchorSnapshot
          ? {
              dir: resultStorage.dir,
              readAllMemories: async () => anchorSnapshot ?? [],
              readAllColdMemories: async () => [],
            }
          : resultStorage,
        qmdSearch: async (query, limit) => {
          if (!this.isSearchAvailable()) {
            log.warn("[contradiction-linking] QMD unavailable; continuing with anchor candidates");
            return [];
          }
          const results = await this.searchAcrossNamespaces({
            query,
            namespaces: [namespaceScope],
            maxResults: limit,
            mode: "search",
          });
          const hits = [];
          for (const result of results) {
            if (result.score < config.contradictionSimilarityThreshold) continue;
            const memoryId = this.extractMemoryIdsFromResults([result])[0];
            if (!memoryId) continue;
            if (this.namespaceFromPath(result.path) !== namespaceScope) continue;
            const existingMemory =
              anchorMemoryById?.get(memoryId) ?? (await resultStorage.getMemoryById(memoryId));
            if (
              !existingMemory ||
              isSupportPassportPrivateMemory(existingMemory) ||
              inferLocalizationMemoryStatus(existingMemory, resultStorage.dir) !== "active"
            ) continue;
            hits.push({
              id: memoryId,
              content: existingMemory.content,
              category: existingMemory.frontmatter.category,
              score: result.score,
            });
          }
          return hits;
        },
      },
      {
        entityRef: anchor?.entityRef,
        category,
        attributes: anchor?.structuredAttributes ?? anchor?.attributes,
      },
      content,
      localizationOptions,
    );

    for (const candidate of candidates) {
      const existingMemory =
        anchorMemoryById?.get(candidate.id) ?? (await resultStorage.getMemoryById(candidate.id));
      if (
        !existingMemory ||
        isSupportPassportPrivateMemory(existingMemory) ||
        inferLocalizationMemoryStatus(existingMemory, resultStorage.dir) !== "active"
      ) continue;
      const verification = await this.getExtraction().verifyContradiction(
        { content, category },
        {
          id: existingMemory.frontmatter.id,
          content: existingMemory.content,
          category: existingMemory.frontmatter.category,
          created: existingMemory.frontmatter.created,
        },
      );
      if (!verification) continue;
      if (
        verification.isContradiction &&
        verification.confidence >= config.contradictionMinConfidence
      ) {
        if (verification.whichIsNewer === "first") {
          log.info(
            `detected contradiction (confidence: ${verification.confidence}): ${existingMemory.frontmatter.id} vs new memory — existing is newer, incoming fact is stale`,
          );
          continue;
        }
        log.info(
          `detected contradiction (confidence: ${verification.confidence}): ${existingMemory.frontmatter.id} vs new memory${config.contradictionAutoResolve ? " (auto-resolved)" : " (queued for manual review)"}`,
        );
        return {
          supersededId: existingMemory.frontmatter.id,
          confidence: verification.confidence,
          reason: verification.reasoning,
          supersededPath: existingMemory.path,
          supersededCreated: existingMemory.frontmatter.created,
          supersededTags: existingMemory.frontmatter.tags ?? [],
        };
      }
    }
    return null;
  }
  /**
   * #1645: Complete the deferred contradiction auto-resolve after writeMemory
   * returns and the new write's tombstone status is known. Retires the old
   * memory + deindexes it ONLY when the new write is genuinely active (not
   * tombstone-blocked / pending_review). A blocked write must not retire the
   * only active copy — deferring here closes the "contradictionAutoResolve
   * supersedes before tombstone status is known" defect class.
   */
  async applyDeferredContradictionResolve(
    contradiction: ContradictionResolveTarget | null | undefined,
    storage: StorageManager,
    newMemoryId: string,
    postWriteGuard: boolean,
  ): Promise<ContradictionResolveOutcome> {
    const config = this.getConfig();
    // #1645 yG2: clear the pre-write `supersedes` link from a blocked row so
    // it doesn't claim to supersede a still-active memory (best-effort).
    if (postWriteGuard && contradiction && config.contradictionAutoResolve) {
      try {
        const blockedRow = await storage.getMemoryById(newMemoryId);
        if (blockedRow?.frontmatter?.supersedes) {
          await storage.writeMemoryFrontmatter(blockedRow, { supersedes: undefined });
        }
      } catch (err) {
        log.warn(
          `contradiction auto-resolve supersedes clear failed for blocked ${newMemoryId}: ${err}`,
        );
      }
    }
    if (
      !contradiction ||
      !config.contradictionAutoResolve ||
      postWriteGuard
    ) {
      return postWriteGuard ? "blocked" : "not_attempted";
    }

    // Capture propagation inputs before the primary supersession. The
    // propagation hook is orchestration-owned, so its own supersessions cannot
    // recurse.
    let oldMemory: PropagationEvent["oldMemory"] | null = null;
    let replacementContent: string | null = null;
    let propagationEvent: PropagationEvent | null = null;
    try {
      const [hot, cold] = await Promise.all([
        typeof storage.readAllMemories === "function"
          ? storage.readAllMemories()
          : Promise.resolve([]),
        typeof storage.readAllColdMemories === "function"
          ? storage.readAllColdMemories()
          : Promise.resolve([]),
      ]);
      const memories = mergeMemorySnapshots(hot, cold, storage.dir);
      const captured = memories.find(
        (memory) =>
          memory.frontmatter.id === contradiction.supersededId &&
          inferLocalizationMemoryStatus(memory, storage.dir) === "active",
      );
      if (captured) {
        oldMemory = {
          content: captured.content,
          frontmatter: {
            ...captured.frontmatter,
            ...(captured.frontmatter.tags
              ? { tags: [...captured.frontmatter.tags] }
              : {}),
            ...(captured.frontmatter.links
              ? { links: captured.frontmatter.links.map((link) => ({ ...link })) }
              : {}),
          },
          path: captured.path,
        };
      }
      replacementContent =
        memories.find((memory) => memory.frontmatter.id === newMemoryId)?.content ??
        (await storage.getMemoryById(newMemoryId))?.content ??
        null;
    } catch (err) {
      log.warn(
        `contradiction propagation snapshot failed for ${contradiction.supersededId}: ${err}`,
      );
    }

    if (oldMemory && replacementContent !== null) {
      try {
        propagationEvent = {
          oldMemory,
          replacementId: newMemoryId,
          replacementContent,
          cause: "contradiction",
          namespaceScope: this.storageDirNamespace(storage.dir),
        };
      } catch (err) {
        log.warn(
          `contradiction dependency propagation event failed for ${contradiction.supersededId}: ${err}`,
        );
      }
    } else if (oldMemory) {
      log.warn(
        `contradiction dependency propagation skipped for ${contradiction.supersededId}: replacement content was not captured`,
      );
    }
    const propagationEnabled = isDependencyPropagationEnabled(config);
    let delivery: DependencyPropagationDeliveryPort | null = null;
    if (propagationEvent && propagationEnabled) {
      try {
        delivery = this.getDependencyPropagationDelivery();
      } catch (err) {
        log.warn(
          `contradiction dependency propagation delivery unavailable for ${contradiction.supersededId}: ${err}`,
        );
      }
    }
    let preparation: DependencyPropagationPreparationToken | null = null;
    if (delivery && propagationEvent) {
      try {
        preparation = await delivery.prepare(propagationEvent);
      } catch (err) {
        log.warn(
          `contradiction dependency propagation prepare failed for ${contradiction.supersededId}: ${err}`,
        );
      }
    }
    const supersessionCommitted = async (): Promise<boolean | null> => {
      try {
        const current = await storage.getMemoryById(contradiction.supersededId);
        if (!current) return null;
        return (
          current.frontmatter.status === "superseded" &&
          current.frontmatter.supersededBy === newMemoryId
        );
      } catch (err) {
        log.warn(
          `contradiction supersession state read failed for ${contradiction.supersededId}: ${err}`,
        );
        return null;
      }
    };

    const settleFailedPropagation = async (commitState: boolean | null): Promise<void> => {
      let token = preparation;
      if (commitState === false) {
        if (token !== null) {
          try {
            await delivery?.cancel(token);
          } catch (err) {
            log.warn(
              `contradiction dependency propagation cancel failed for ${contradiction.supersededId}: ${err}`,
            );
          }
        }
        return;
      }
      if (commitState === null && token === null && delivery && propagationEvent) {
        try {
          token = await delivery.prepare(propagationEvent);
        } catch (err) {
          log.warn(
            `contradiction dependency propagation recovery prepare failed for ${contradiction.supersededId}: ${err}`,
          );
        }
      }
      if (token !== null) {
        try {
          await delivery?.deferPrepared(token);
        } catch (err) {
          log.warn(
            `contradiction dependency propagation defer failed for ${contradiction.supersededId}: ${err}`,
          );
        }
        return;
      }
      if (commitState === true && delivery && propagationEvent) {
        try {
          await delivery.afterMutation(null, propagationEvent);
        } catch (err) {
          log.warn(
            `contradiction dependency propagation fallback failed for ${contradiction.supersededId}: ${err}`,
          );
        }
      }
    };
    const readyPreparedPropagation = async (): Promise<void> => {
      if (!propagationEvent || !propagationEnabled) return;
      if (!delivery) {
        await propagateInvalidation(
          { storage, extraction: this.getExtraction(), config },
          propagationEvent,
        );
        return;
      }
      let token = preparation;
      if (token === null) {
        try {
          token = await delivery.prepare(propagationEvent);
        } catch (err) {
          log.warn(
            `contradiction dependency propagation recovery prepare failed for ${contradiction.supersededId}: ${err}`,
          );
        }
      }
      try {
        await delivery.afterMutation(token, propagationEvent);
      } catch (err) {
        log.warn(
          `contradiction dependency propagation failed for ${contradiction.supersededId}: ${err}`,
        );
      }
    };

    let commitState: boolean | null = false;
    try {
      const committed = await storage.supersedeMemory(
        contradiction.supersededId,
        newMemoryId,
        contradiction.reason,
      );
      commitState = committed ? true : await supersessionCommitted();
      if (!committed || commitState !== true) {
        let mergedSnapshot: MemoryFile[];
        try {
          const [hot, cold] = await Promise.all([
            typeof storage.readAllMemories === "function"
              ? storage.readAllMemories()
              : Promise.all([
                  storage.getMemoryById(contradiction.supersededId),
                  storage.getMemoryById(newMemoryId),
                ]).then((memories) =>
                  memories.filter((memory): memory is MemoryFile => memory !== null),
                ),
            typeof storage.readAllColdMemories === "function"
              ? storage.readAllColdMemories()
              : Promise.resolve([]),
          ]);
          mergedSnapshot = mergeMemorySnapshots(hot, cold, storage.dir);
        } catch (err) {
          log.warn(
            `contradiction auto-resolve race check failed for ${contradiction.supersededId}: ${err}`,
          );
          await settleFailedPropagation(commitState);
          return "supersede_failed";
        }
        const target = mergedSnapshot.find(
          (memory) => memory.frontmatter.id === contradiction.supersededId,
        );
        if (!target) {
          await settleFailedPropagation(commitState);
          return "supersede_failed";
        }
        const losingMemory = mergedSnapshot.find(
          (memory) =>
            memory.frontmatter.id === newMemoryId &&
            inferLocalizationMemoryStatus(memory, storage.dir) === "active",
        );
        if (!losingMemory) {
          await settleFailedPropagation(commitState);
          return "supersede_failed";
        }
        try {
          if (losingMemory.frontmatter.supersedes === contradiction.supersededId) {
            const cleared = await storage.writeMemoryFrontmatter(losingMemory, {
              supersedes: undefined,
            });
            if (cleared === false) {
              await settleFailedPropagation(commitState);
              return "supersedes_clear_failed";
            }
          }
        } catch (err) {
          log.warn(
            `contradiction auto-resolve losing supersedes clear failed for ${newMemoryId}: ${err}`,
          );
          await settleFailedPropagation(commitState);
          return "supersedes_clear_failed";
        }
        const outcome = inferLocalizationMemoryStatus(target, storage.dir) === "active"
          ? "supersede_failed"
          : "lost_race";
        if (commitState === true) {
          await readyPreparedPropagation();
        } else {
          await settleFailedPropagation(commitState);
        }
        return outcome;
      }
    } catch (err) {
      commitState = await supersessionCommitted();
      log.warn(
        `contradiction auto-resolve supersede failed for ${contradiction.supersededId}: ${err}`,
      );
      if (commitState !== true) {
        await settleFailedPropagation(commitState);
        return "supersede_failed";
      }
    }
    await readyPreparedPropagation();

    if (
      resolveIndexingCapabilities(config).queryAwareIndexing &&
      contradiction.supersededPath
    ) {
      try {
        await deindexMemoryAsync(
          config.memoryDir,
          contradiction.supersededPath,
          contradiction.supersededCreated,
          contradiction.supersededTags,
        );
      } catch (err) {
        log.warn(
          `contradiction auto-resolve deindex failed for ${contradiction.supersededId}: ${err}`,
        );
      }
    }
    return "resolved";
  }

  // ---------------------------------------------------------------------------
  // Memory Linking (Phase 3A)
  // ---------------------------------------------------------------------------

  /**
   * Suggest links for a new memory based on similar existing memories.
   */
  async suggestLinksForMemory(
    content: string,
    category: string,
    namespaceScope: string,
  ): Promise<MemoryLink[]> {
    if (!this.isSearchAvailable()) return [];

    // Search for related memories
    const results = await this.searchAcrossNamespaces({
      query: content,
      namespaces: [namespaceScope],
      maxResults: 5,
      mode: "search",
    });
    if (results.length === 0) return [];

    // Get full memory details for candidates
    const candidates: Array<{ id: string; content: string; category: string }> =
      [];
    for (const result of results) {
      const memoryId = this.extractMemoryIdsFromResults([result])[0];
      if (!memoryId) continue;

      const resultNamespace = this.namespaceFromPath(result.path);
      if (resultNamespace !== namespaceScope) continue;
      const resultStorage = await this.storageForNamespace(resultNamespace);
      const memory = await resultStorage.getMemoryById(memoryId);
      if (
        memory &&
        memory.frontmatter.status !== "superseded" &&
        memory.frontmatter.status !== "forgotten"
      ) {
        candidates.push({
          id: memory.frontmatter.id,
          content: memory.content,
          category: memory.frontmatter.category,
        });
      }
    }

    if (candidates.length === 0) return [];

    // Ask LLM for link suggestions
    const extraction = this.getExtraction();
    const suggestions = await extraction.suggestLinks(
      { content, category },
      candidates,
    );

    if (!suggestions || suggestions.links.length === 0) return [];

    // Convert to MemoryLink format
    return suggestions.links.map((link) => ({
      targetId: link.targetId,
      linkType: link.linkType,
      strength: link.strength,
      reason: link.reason || undefined,
    }));
  }
}

