            });
            // Issue #1577 — read the cold pipeline's trust map back (rule 41).
            recallTrustByPath = trustByPathSink.trustByPath;
            if (longTerm.length > 0) {
              recallSource = "cold_fallback";
              recalledMemoryCount = longTerm.length;
