function matchesMemoryPath(candidatePath: string, requestedPath: string, memoryDir: string): boolean {
  const normalizedCandidate = path.resolve(candidatePath);
  return normalizedCandidate === path.resolve(requestedPath) || normalizedCandidate === path.resolve(memoryDir, requestedPath);
}

function accessTrackingPathCandidates(storageDir: string, memoryPath: string): string[] {
  const candidates = qmdResultPathCandidates(storageDir, memoryPath);
  const parts = qmdCollectionPathParts(memoryPath);
  if (!parts) return candidates;

  candidates.push(
    ...qmdResultPathCandidates(storageDir, parts.relativePath),
    ...qmdResultPathCandidates(path.join(storageDir, "cold"), parts.relativePath),
  );
  return [...new Set(candidates)];
}

function canonicalMemoryPath(memoryPath: string, memoryDir: string): string {
  return path.resolve(path.isAbsolute(memoryPath) ? memoryPath : path.resolve(memoryDir, memoryPath));
}
export class WorkspaceOpsCoordinator {
  constructor(
    private readonly deps: WorkspaceOpsDeps,
  ) {}

  /**
   * Run the pattern-reinforcement maintenance job (issue #687 PR 2/4).
   *
   * Cadence-gated on `patternReinforcementCadenceMs` so every caller
   * (orchestrator cron path, MCP tool, CLI) shares a single floor —
   * none can call this on a hot loop and burn the corpus.  When the
   * feature is disabled or the cadence has not elapsed, returns a
   * synthetic "skipped" result rather than throwing.
   *
   * Cadence tracking is per-namespace so a tenant-scoped MCP run in
   * one namespace does not silence a cron run in another (PR #730
   * review feedback, Codex P2).  Pass `force: true` for ad-hoc
   * operator runs that must bypass the cadence floor — mirrors the
   * pattern used by other maintenance MCP tools.
   *
   * `force` deliberately does NOT bypass the master
   * `patternReinforcementEnabled` flag (PR #730 review feedback,
   * Cursor Medium).  Operators who have explicitly disabled the
   * feature must not have their corpus mutated by an MCP tool call —
   * the only way to run the job is to enable the feature in config.
   */
  async runPatternReinforcement(options: {
    force?: boolean;
    namespace?: string;
  } = {}): Promise<{
    ran: boolean;
    skippedReason?: "disabled" | "cadence";
    namespace: string;
    result?: PatternReinforcementResult;
  }> {
    const cadenceKey = options.namespace ?? "";
    // Master switch: a disabled feature is never bypassed, even with
    // force=true.  `force` only relaxes the cadence floor below.
    if (!resolveConsolidationCapabilities(this.deps.config).patternReinforcement) {
      return { ran: false, skippedReason: "disabled", namespace: cadenceKey };
    }
    const cadence = this.deps.config.patternReinforcementCadenceMs;
    const lastAt = this.deps.lastPatternReinforcementAtByNs.get(cadenceKey);
    if (
      !options.force &&
      cadence > 0 &&
      lastAt !== undefined &&
      Date.now() - lastAt < cadence
    ) {
      return { ran: false, skippedReason: "cadence", namespace: cadenceKey };
    }
    const storage = options.namespace
      ? await this.deps.getStorage(options.namespace)
      : this.deps.storage;
    const result = await runPatternReinforcement(storage, {
      categories: this.deps.config.patternReinforcementCategories,
      minCount: this.deps.config.patternReinforcementMinCount,
    });
    this.deps.lastPatternReinforcementAtByNs.set(cadenceKey, Date.now());
    log.debug(
      `pattern reinforcement [ns=${cadenceKey || "(default)"}]: clusters=${result.clustersFound} canonicalsUpdated=${result.canonicalsUpdated} duplicatesSuperseded=${result.duplicatesSuperseded}`,
    );
    return { ran: true, result, namespace: cadenceKey };
  }

  /**
   * Fan out pattern reinforcement across all maintained namespaces (issue #1500).
   * Delegates per-namespace execution to {@link runPatternReinforcement} while
   * the planner handles discovery, budgeting, locking, and status recording.
   * When namespaces are disabled, runs once against default storage.
   */
  async runPatternReinforcementFanout(options: {
    force?: boolean;
  } = {}): Promise<NamespaceMaintenanceSummary> {
    return this.deps.runNamespaceMaintenanceFanoutForJob(
      "pattern-reinforcement",
      async (ctx) => {
        const result = await this.deps.runPatternReinforcement({
          namespace: ctx.candidate.namespace,
          force: options.force,
        });
        // runPatternReinforcement has its own per-namespace cadence gate
        // (lastPatternReinforcementAtByNs). When it throttles (ran:false),
        // signal skip so the planner records state:"skipped" and does NOT
        // touch lastMaintenanceAt — otherwise a throttled namespace would
        // look maintained while pattern reinforcement never ran (#1500
        // review: cadence-skip accuracy).
        if (!result.ran) {
          return {
            skipped: true,
            skipReason: result.skippedReason ?? "throttled",
          };
        }
        return result.result
          ? { itemCount: result.result.clustersFound }
          : { itemCount: 0 };
      },
      { enabled: resolveConsolidationCapabilities(this.deps.config).patternReinforcement },
    );
  }

  async maybeRunFileHygiene(): Promise<void> {
    const hygiene = this.deps.config.fileHygiene;
    if (!hygiene?.enabled) return;

    const now = Date.now();
    if (now - this.deps.lastFileHygieneRunAtMs < hygiene.runMinIntervalMs) return;
    this.deps.lastFileHygieneRunAtMs = now;

    // Rotation first (keeps bootstrap files small).
    if (hygiene.rotateEnabled) {
      for (const rel of hygiene.rotatePaths) {
        const abs = path.isAbsolute(rel)
          ? rel
          : path.join(this.deps.config.workspaceDir, rel);
        try {
          const raw = await readFile(abs, "utf-8");
          if (raw.length > hygiene.rotateMaxBytes) {
            const archiveDir = path.join(
              this.deps.config.workspaceDir,
              hygiene.archiveDir,
            );
            const base = path.basename(abs);
            const prefix =
              base
                .toUpperCase()
                .replace(/\.MD$/i, "")
                .replace(/[^A-Z0-9]+/g, "-") || "FILE";
            const { newContent } = await rotateMarkdownFileToArchive({
              filePath: abs,
              archiveDir,
              archivePrefix: prefix,
              keepTailChars: hygiene.rotateKeepTailChars,
            });
            await writeFile(abs, newContent, "utf-8");
          }
        } catch {
          // ignore missing/unreadable targets
        }
      }
    }

    // Lint (warn before truncation risk).
    if (hygiene.lintEnabled) {
      const warnings = await lintWorkspaceFiles({
        workspaceDir: this.deps.config.workspaceDir,
        paths: hygiene.lintPaths,
        budgetBytes: hygiene.lintBudgetBytes,
        warnRatio: hygiene.lintWarnRatio,
      });
      for (const w of warnings) {
        log.warn(w.message);
      }

      if (hygiene.warningsLogEnabled && warnings.length > 0) {
        const fp = path.join(this.deps.config.memoryDir, hygiene.warningsLogPath);
        await mkdir(path.dirname(fp), { recursive: true });
        const stamp = new Date().toISOString();
        const block =
          `\n\n## ${stamp}\n\n` +
          warnings.map((w) => `- ${w.message}`).join("\n") +
          "\n";
        let existing = "";
        try {
          existing = await readFile(fp, "utf-8");
        } catch {
          existing = "# Engram File Hygiene Warnings\n";
        }
        await writeFile(fp, existing + block, "utf-8");
      }
    }
  }

  /**
   * Read today's facts and hourly summaries from storage, returning them
   * as a formatted string suitable for generateDaySummary().
   */
  async gatherTodayFacts(
    namespace?: string,
    options: DaySummaryGatherOptions = {},
  ): Promise<string> {
    const ns =
      namespace && namespace.length > 0
        ? namespace
        : this.deps.config.defaultNamespace;
    const storage = await this.deps.storageRouter.storageFor(ns);
    const configuredTimeZone = normalizeIanaTimeZone(options.timeZone)
      ?? normalizeIanaTimeZone(this.deps.config.daySummaryTimezone);
    const timeZone =
      configuredTimeZone ?? Intl.DateTimeFormat().resolvedOptions().timeZone;
    const now = options.now instanceof Date && Number.isFinite(options.now.getTime())
      ? options.now
      : new Date();
    const targetLocalDate = formatDateInTimeZone(now, timeZone);
    // Facts are stored under UTC date directories, while the summary target is
    // a local calendar day. Scan the UTC-date envelope that overlaps the local
    // day, then filter parseable fact timestamps to that configured local day.
    const datesToScan = utcDateKeysForLocalDay(now, timeZone);
    const MAX_CHARS = 100_000;

    // --- Read memory files from each category dir × date directory ---
    // Iterate every recall category dir (RECALL_FALLBACK_DIRS — single source
    // of truth) so the day summary includes decisions/, moments/, ... not just
    // facts/ (#1546). corrections/ is flat, so corrections/<date>/ never exists
    // and is skipped by the ENOENT guard — preserving the prior exclusion. The
    // per-file created→local-day filter below is unchanged.
    //
    // Symlink/containment hardening (mirrors scanDir / the CLI walker): the
    // gathered contents feed the day-summary LLM input, so a symlinked category
    // dir (decisions/ → outside memoryDir) must not be followed and leak files.
    // Resolve the store root once; skip symlinked / out-of-root dirs and
    // entries; skip the scan gracefully if the root can't be resolved.
    const facts: MemoryFile[] = [];
    let memoryRootReal: string | null = null;
    try {
      memoryRootReal = await realpath(storage.dir);
    } catch {
      memoryRootReal = null;
    }
    for (const categoryDir of RECALL_FALLBACK_DIRS) {
      if (memoryRootReal === null) break;
      for (const date of datesToScan) {
        const dateDir = path.join(storage.dir, categoryDir, date);
        try {
          const dirStat = await lstat(dateDir);
          if (dirStat.isSymbolicLink() || !dirStat.isDirectory()) continue;
          assertPathInsideRoot(memoryRootReal, await realpath(dateDir), dateDir);
          const entries = await readdir(dateDir, { withFileTypes: true });
          for (const entry of entries) {
            if (entry.isSymbolicLink()) continue;
            if (!entry.name.endsWith(".md")) continue;
            const fullPath = path.join(dateDir, entry.name);
            try {
              assertPathInsideRoot(memoryRootReal, await realpath(fullPath), fullPath);
              const memory = await storage.readMemoryByPath(fullPath);
              if (!memory || isSupportPassportPrivateMemory(memory)) continue;
              const createdAt = parseFiniteDate(memory.frontmatter.created);
              if (
                createdAt &&
                formatDateInTimeZone(createdAt, timeZone) !== targetLocalDate
              ) {
                continue;
              }
              facts.push(memory);
            } catch {
              // Skip unreadable files
            }
          }
        } catch {
          // Absent dir (ENOENT), symlinked/out-of-root dir, or containment
          // violation — skip this category/date without aborting the summary.
        }
      }
    }

    // Sort facts by created timestamp (most recent last) so truncation keeps newest
    facts.sort((a, b) => {
      if (a.frontmatter.created === b.frontmatter.created) return 0;
      return a.frontmatter.created < b.frontmatter.created ? -1 : 1;
    });

    // --- Read hourly summaries for the scanned dates ---
    const hourlySummaries: string[] = [];
    const hourlyBaseDir = path.join(storage.dir, "summaries", "hourly");
    try {
      const sessionKeys = await readdir(hourlyBaseDir, { withFileTypes: true });
      for (const sk of sessionKeys) {
        if (!sk.isDirectory()) continue;
        for (const date of datesToScan) {
          const summaryFile = path.join(hourlyBaseDir, sk.name, `${date}.md`);
          try {
            const raw = await readFile(summaryFile, "utf-8");
            const filtered = filterHourlySummaryMarkdownForLocalDay(
              raw,
              date,
              timeZone,
              targetLocalDate,
            );
            if (filtered) {
              hourlySummaries.push(filtered);
            }
          } catch {
            // No summary file for this session/date
          }
        }
      }
    } catch {
      // No hourly summaries directory
    }

    // --- Format and truncate ---
    let formatted = formatDaySummaryMemories(facts);
    if (hourlySummaries.length > 0) {
      formatted +=
        "\n\n---\n## Hourly Summaries\n\n" +
        hourlySummaries.join("\n\n---\n\n");
    }

    // Truncate intelligently if over budget: drop oldest facts first
    if (formatted.length > MAX_CHARS) {
      // Re-build with fewer facts, keeping most recent
      while (facts.length > 1 && formatted.length > MAX_CHARS) {
        facts.shift(); // drop oldest
        formatted = formatDaySummaryMemories(facts);
        if (hourlySummaries.length > 0) {
          formatted +=
            "\n\n---\n## Hourly Summaries\n\n" +
            hourlySummaries.join("\n\n---\n\n");
        }
      }
      // If still over, hard truncate
      if (formatted.length > MAX_CHARS) {
        formatted = formatted.slice(0, MAX_CHARS);
      }
    }

    if (options.includeLocation === true && this.deps.config.location) {
      const section = await renderDayLocationContext(
        storage.dir,
        localDayKey(now.toISOString(), this.deps.config.location.timezone),
        this.deps.config.location,
      );
      if (section) {
        formatted += `\n\n${section}`;
      }
    }

    log.info(
      `gatherTodayFacts: collected ${facts.length} facts, ${hourlySummaries.length} hourly summaries for ${targetLocalDate} (${timeZone}, ${formatted.length} chars)`,
    );

    return formatted;
  }

  previewMemoryActionEvent(
    event: Omit<MemoryActionEvent, "timestamp"> & { timestamp?: string },
  ): MemoryActionEvent {
    const namespace =
      typeof event.namespace === "string" && event.namespace.length > 0
        ? event.namespace
        : this.deps.config.defaultNamespace;
    const eligibility = parseMemoryActionEligibilityContext(
      event.policyEligibility,
    );
    const policy = evaluateMemoryActionPolicy({
      action: event.action,
      eligibility,
      options: {
        actionsEnabled: resolveCompressionCapabilities(this.deps.config).contextCompressionActions,
        maxCompressionTokensPerHour: this.deps.config.maxCompressionTokensPerHour,
      },
    });
    const dryRun = event.dryRun === true;

    const normalizedOutcome = dryRun
      ? event.outcome === "failed"
        ? "failed"
        : "skipped"
      : policy.decision === "allow"
        ? event.outcome
        : event.outcome === "failed"
          ? "failed"
          : "skipped";
    const sourceSessionKey =
      typeof event.sourceSessionKey === "string" &&
      event.sourceSessionKey.length > 0
        ? event.sourceSessionKey
        : typeof event.sessionKey === "string" && event.sessionKey.length > 0
          ? event.sessionKey
          : undefined;
    const outputMemoryIds = Array.isArray(event.outputMemoryIds)
      ? Array.from(
          new Set(
            event.outputMemoryIds.filter(
              (value): value is string =>
                typeof value === "string" && value.length > 0,
            ),
          ),
        )
      : [];

    const reasonParts = [
      event.reason,
      `policy:${policy.decision}`,
      policy.rationale,
    ].filter(
      (part): part is string => typeof part === "string" && part.length > 0,
    );

    return {
      ...event,
      schemaVersion: event.schemaVersion ?? 1,
      actionId:
        typeof event.actionId === "string" && event.actionId.length > 0
          ? event.actionId
          : `memact-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`,
      outcome: normalizedOutcome,
      status:
        event.status ??
        (dryRun && policy.decision === "allow" && event.outcome !== "failed"
          ? "validated"
          : normalizedOutcome === "applied"
            ? "applied"
            : "rejected"),
      actor:
        typeof event.actor === "string" && event.actor.length > 0
          ? event.actor
          : "engram",
      subsystem:
        typeof event.subsystem === "string" && event.subsystem.length > 0
          ? event.subsystem
          : "memory_action",
      reason: reasonParts.join(" | "),
      namespace,
      sessionKey: sourceSessionKey ?? event.sessionKey,
      sourceSessionKey,
      inputSummary:
        typeof event.inputSummary === "string" && event.inputSummary.length > 0
          ? event.inputSummary
          : undefined,
      outputMemoryIds,
      dryRun,
      policyVersion:
        typeof event.policyVersion === "string" &&
        event.policyVersion.length > 0
          ? event.policyVersion
          : "memory-action-policy.v1",
      timestamp:
        typeof event.timestamp === "string" && event.timestamp.length > 0
          ? event.timestamp
          : new Date().toISOString(),
      policyDecision: policy.decision,
      policyRationale: policy.rationale,
      policyEligibility: eligibility,
    };
  }

  /**
   * Validate local LLM model availability and context window compatibility.
   * Warns the user if there's a mismatch.
   */
  async validateLocalLlmModel(): Promise<void> {
    log.debug("Local LLM: validating model configuration");
    try {
      const modelInfo = await this.deps.localLlm.getLoadedModelInfo();
      if (!modelInfo) {
        log.warn(
          "Local LLM validation: Could not query model info from server",
        );
        log.warn(
          "Local LLM validation: Could not query model info. " +
            "Ensure LM Studio/Ollama is running with the model loaded.",
        );
        return;
      }

      // Check for context window mismatch
      const configuredMaxContext = this.deps.config.localLlmMaxContext;

      if (modelInfo.contextWindow) {
        log.debug(
          `Local LLM: ${modelInfo.id} loaded with ${modelInfo.contextWindow.toLocaleString()} token context window`,
        );

        if (
          configuredMaxContext &&
          configuredMaxContext > modelInfo.contextWindow
        ) {
          log.warn(
            `Local LLM context mismatch: engram configured for ${configuredMaxContext.toLocaleString()} tokens, ` +
              `but ${modelInfo.id} only supports ${modelInfo.contextWindow.toLocaleString()}. ` +
              `Reducing to ${modelInfo.contextWindow.toLocaleString()} to avoid errors.`,
          );
          // Update the config in-memory to match actual capability
          // (This is a temporary fix - user should update their config)
          (this.deps.config as { localLlmMaxContext?: number }).localLlmMaxContext =
            modelInfo.contextWindow;
        }
      } else {
        log.debug(
          `Local LLM: ${modelInfo.id} loaded (context window not reported by server)`,
        );

        if (!configuredMaxContext) {
          log.warn(
            "Local LLM: Server did not report context window. " +
              "If you get 'context length exceeded' errors, set localLlmMaxContext in your config. " +
              "Common defaults: LM Studio (32K), Ollama (2K-128K depending on model).",
          );
        }
      }
    } catch (err) {
      log.warn(`Local LLM validation failed: ${err}`);
    }
  }

  /**
   * Lazily-constructed wearables service (Limitless / Bee / Omi
   * transcript ingestion). All wearables surfaces — CLI, MCP tools,
   * HTTP routes — share this one instance so sync state, search, and
   * memory writes stay consistent. Writes are pinned to the same
   * deterministic namespace bulk-import uses.
   */
  getWearablesService(namespace: string): WearablesService {
    let service = this.deps.wearablesServiceByNamespace.get(namespace);
    if (!service) {
      service = new WearablesService({
        config: this.deps.config.wearables,
        getStorage: async () => await this.deps.getStorageForNamespace(namespace),
        locationConfig: this.deps.config.location,
        extract: (turns) => this.deps.extraction.extract(turns),
        // Smart memoryMode runs candidates through the SAME extraction
        // judge (cache + defer counters included) the live extraction
        // pipeline uses, so wearable facts get identical LLM-as-judge
        // durability gating.
        judgeFacts: (candidates) =>
          judgeFactDurability(
            candidates,
            this.deps.config,
            this.deps.localLlm,
            new FallbackLlmClient(
              this.deps.config.gatewayConfig,
              fallbackLlmRuntimeContextFromConfig(this.deps.config),
            ),
            this.deps.judgeVerdictCache,
            this.deps.judgeDeferCounts,
          ),
        searchBackend: {
          search: async (query, maxResults) => {
            if (!this.deps.qmd.isAvailable()) return null;
            try {
              // Scope the indexed search to the CALLER namespace's collection so a
              // non-default caller's transcript_search never returns root or
              // other-namespace transcripts (#2123). Namespaces off, or the
              // default/machine-owner namespace rooted at memoryDir, resolve to the
              // base collection (unchanged); every other namespace to its own.
              let collection: string | undefined;
              if (resolveNamespaceCapabilities(this.deps.config).namespaces === true) {
                const storage = await this.deps.getStorageForNamespace(namespace);
                const useLegacy =
                  namespace === this.deps.config.defaultNamespace &&
                  storage.dir === this.deps.config.memoryDir;
                collection = namespaceCollectionName(this.deps.config.qmdCollection, namespace, {
                  defaultNamespace: this.deps.config.defaultNamespace,
                  useLegacyDefaultCollection: useLegacy,
                });
              }
              const results = await this.deps.qmd.search(query, collection, maxResults);
              return results.map((result) => ({
                path: result.path,
                score: result.score,
                preview: result.snippet,
              }));
            } catch {
              // Backend hiccup → tell the service "unavailable" so it
              // runs its bounded scan fallback instead of returning a
              // silent empty result (CLAUDE.md rule 34).
              return null;
            }
          },
        },
        reindexSearch: async () => {
          // qmd.update() clears the global QMD result caches itself on success
          // (QmdClient.runUpdateForCollection), so newly-indexed wearable
          // transcript/fact content is never hidden by a pre-sync cache entry
          // (#1904, Codex).
          await this.deps.qmd.update();
        },
        // Meeting tail-step (issue #1900): schedule a debounced meeting rebuild
        // for every day a wearable sync touched. Wired on the shared service so
        // BOTH the auto-sync adapter and the manual HTTP/MCP/CLI sync path
        // (EngramAccessService.wearablesSync -> getWearablesService().sync)
        // rebuild affected meetings. Gated on meetings.enabled so a sync of
        // other signals never spins up meeting building; a failure never fails
        // the sync.
        onDaysSynced: async (days) => {
          if (!this.deps.config.meetings.enabled) return;
          try {
            const meetings = await this.getMeetingsService(namespace);
            for (const day of days) meetings.requestBuild(day);
          } catch (err) {
            log.warn(
              `meetings: failed to schedule post-wearable-sync build: ${
                err instanceof Error ? err.message : String(err)
              }`,
            );
          }
        },
      });
      this.deps.wearablesServiceByNamespace.set(namespace, service);
    }
    return service;
  }

  /**
   * Lazily-constructed meetings service (issue #1900). Owns the record store,
   * the store-backed builder (fed by the concrete activity + wearable day
   * source), and the debounced post-sync build scheduler. Every meeting surface
   * — CLI, MCP tools, HTTP routes — shares this one instance. Writes are pinned
   * to the same deterministic namespace bulk-import uses, so meeting records and
   * episode memories land beside wearable/activity artifacts. Constructing it
   * touches no disk while `meetings.enabled` is off — every entrypoint gates.
   */
  async getMeetingsService(namespace: string): Promise<MeetingsService> {
    let service = this.deps.meetingsServiceByNamespace.get(namespace);
    if (!service) {
      const config = this.deps.config.meetings;
      const memoryDir = this.deps.config.memoryDir;
      const storage = await this.deps.getStorageForNamespace(namespace);
      const store = storage.meetingRecordStore();
      // Activity is machine-scoped (<memoryDir>/state/activity.sqlite) and is
      // consumed ONLY by the machine-owner (default) namespace; every other
      // caller namespace runs audio-only with no activity reader (issue #2123).
      // A missing/unavailable store degrades to no screen context, never a fail.
      const activity: MeetingsActivityReader | undefined =
        namespace !== this.deps.config.defaultNamespace
          ? undefined
          : {
        listSnapshotsForDay: (machine, startUtc, endUtc) => {
          let activityStore: ActivityStore | undefined;
          try {
            activityStore = ActivityStore.open(memoryDir);
            return activityStore.listSnapshotsForDay(machine, startUtc, endUtc);
          } catch (err) {
            log.warn(
              `meetings: activity snapshots unavailable (${
                err instanceof Error ? err.message : String(err)
              }); building without screen context`,
            );
            return [];
          } finally {
            activityStore?.close();
          }
        },
          };
      const source = new ActivityWearablesMeetingsDaySource({
        activity,
        wearables: storageWearableDayReader(storage),
        config,
        timezone: this.deps.config.activity.timezone,
      });
      // Production trust-gated summary/fact deps (issue #1900). Built from the
      // shared LLM clients + the SAME durability-judge closure the wearables
      // service passes (verdict cache + defer counters included), so meeting
      // facts inherit identical judge gating — no forked trust/judge/LLM path.
      // Pure construction (no disk/network); the builder gates on summaryMode.
      const fallbackLlm = new FallbackLlmClient(
        this.deps.config.gatewayConfig,
        fallbackLlmRuntimeContextFromConfig(this.deps.config),
      );
      const summary = createMeetingSummaryDeps({
        localLlm: this.deps.localLlm,
        fallbackLlm,
        judgeFacts: (candidates) =>
          judgeFactDurability(
            candidates,
            this.deps.config,
            this.deps.localLlm,
            fallbackLlm,
            this.deps.judgeVerdictCache,
            this.deps.judgeDeferCounts,
          ),
      });
      const builder = new MeetingsBuilder({
        source,
        store,
        config,
        hooks: {
          reindex: async () => {
            // Meeting records live in the QMD collection root; reindex on change
            // so `show`/search find them immediately (qmd.update clears its own
            // result caches). Fired only when records changed; a failure is
            // surfaced as a build warning, not a hard failure.
            await this.deps.qmd.update();
          },
        },
        // Memory generation behind the builder seam (issue #1900 decouple): the
        // deterministic engine depends only on MeetingMemoryGenerator, never on
        // memory-gen. The generator wraps the same sealed write path the wearables
        // generator uses — createMeetingMemoryWriter adds the source-scoped
        // dedup/retire the raw StorageManager lacks — plus the trust-gated
        // summary/facts layer (extractor + shared durability judge). It gates on
        // summaryMode internally, so `off` never invokes the extractor.
        memoryGenerator: createMeetingMemoryGenerator(createMeetingMemoryWriter(storage), config, summary),
      });
      service = new MeetingsService({
        config,
        store,
        builder,
        buildDebounceMs: MEETINGS_BUILD_DEBOUNCE_MS,
        onBuildError: (date, err) =>
          log.warn(
            `meetings: tail-step build for ${date} failed: ${
              err instanceof Error ? err.message : String(err)
            }`,
          ),
      });
      this.deps.meetingsServiceByNamespace.set(namespace, service);
    }
    return service;
  }

  async autoConsolidateIdentity(): Promise<void> {
    // Fan out over the catalog-union namespace set (issue #1499 sweep): a dynamic
    // namespace that accumulated IDENTITY.md reflections must also be eligible for
    // auto-consolidation, otherwise its identity file grows unbounded and is never
    // consolidated. Falls back to the configured set on any catalog read failure.
    const namespaces = resolveNamespaceCapabilities(this.deps.config).namespaces
      ? await this.deps.maintenanceNamespaces()
      : [this.deps.config.defaultNamespace];

    for (const namespace of namespaces) {
      const storage = await this.deps.storageRouter.storageFor(namespace);
      const identityNamespace =
        resolveNamespaceCapabilities(this.deps.config).namespaces &&
        namespace !== this.deps.config.defaultNamespace
          ? namespace
          : undefined;
      const reflectionsContent =
        (await storage.readIdentityReflections()) ?? "";

      const existingIdentity = await storage.readIdentity(
        this.deps.config.workspaceDir,
        identityNamespace,
      );
      const headerEnd =
        existingIdentity.indexOf("## Learned Patterns") !== -1
          ? existingIdentity.indexOf("## Learned Patterns")
          : existingIdentity.indexOf("## Reflection");
      const staticHeader =
        (headerEnd !== -1
          ? existingIdentity.slice(0, headerEnd)
          : existingIdentity
        ).trimEnd() || "# IDENTITY";
      const identityContent = `${staticHeader}\n\n${reflectionsContent.trim()}\n`;
      if (identityContent.length < Orchestrator.IDENTITY_CONSOLIDATE_THRESHOLD)
        continue;

      log.info(
        `IDENTITY(${namespace}) is ${identityContent.length} chars — auto-consolidating reflections`,
      );
      const result = await this.deps.extraction.consolidateIdentity(
        identityContent,
        "## Reflection",
      );

      if (!result || result.learnedPatterns.length === 0) {
        log.warn(
          `identity consolidation produced no patterns for namespace=${namespace}`,
        );
        continue;
      }

      const patternsSection = [
        "## Learned Patterns (consolidated from reflections, " +
          new Date().toISOString().slice(0, 10) +
          ")",
        "",
        ...result.learnedPatterns.map((p) => `- ${p}`),
        "",
      ].join("\n");

      const newContent = staticHeader + "\n\n" + patternsSection + "\n";

      await storage.writeIdentity(
        this.deps.config.workspaceDir,
        newContent,
        identityNamespace,
      );
      await storage.writeIdentityReflections("");
      // NRcCL (codex P2): record a per-namespace catalog write for THIS namespace
      // after the identity files are updated. This fan-out can mutate a dynamic
      // namespace via `writeIdentity`/`writeIdentityReflections`, but the
      // consolidation pass's only consolidated touch covers `this.deps.storage` (the
      // default) and only fires when `memoryItemMutated` was set by OTHER work — so
      // a namespace whose sole mutation in the pass is identity consolidation would
      // otherwise keep a stale `lastWriteAt`, making `listNamespaces({ writtenSince })`
      // and catalog-recency consumers miss the write. Best-effort and
      // failure-tolerant (the storage chokepoint (#1522) swallows errors, never crashing the
      // consolidation; gotcha #13, rule #40). No double-count with the consolidated
      // touch above: that one is gated on `memoryItemMutated` (which identity
      // consolidation does not set), and `markWrite` is idempotent regardless.
      log.info(
        `IDENTITY(${namespace}) consolidated: ${identityContent.length} → ${newContent.length} chars, ${result.learnedPatterns.length} patterns`,
      );
    }
  }
  trackMemoryAccess(
    memoryIds: string[],
    memoryPaths: string[] = [],
    memoryNamespaces: Array<string | undefined> = [],
  ): void {
    if (!resolveRecallEnhancementCapabilities(this.deps.config).accessTracking) return;

    const now = new Date().toISOString();
    const pathsByMemoryId = new Map<
      string,
      Array<{ path: string; namespace?: string }>
    >();
    for (const [index, memoryPath] of memoryPaths.entries()) {
      const basename = memoryPath.split(/[\\/]/).pop() ?? memoryPath;
      const memoryId = basename.endsWith(".md") ? basename.slice(0, -3) : basename;
      if (memoryId.length > 0 && memoryIds.includes(memoryId)) {
        const paths = pathsByMemoryId.get(memoryId) ?? [];
        const namespace = memoryNamespaces[index];
        paths.push({
          path: memoryPath,
          ...(namespace ? { namespace } : {}),
        });
        pathsByMemoryId.set(memoryId, paths);
      }
    }
    for (const id of memoryIds) {
      const references = pathsByMemoryId.get(id);
      const reference = references?.shift();
      const memoryPath = reference?.path;
      const namespace = reference?.namespace ?? (
        memoryPath
          ? this.deps.namespaceFromPath(memoryPath)
          : this.deps.config.defaultNamespace
      );
      const key = memoryPath
        ? `${namespace}:${canonicalMemoryPath(memoryPath, this.deps.config.memoryDir)}`
        : `${namespace}:${id}`;
      const existing = this.deps.accessTrackingBuffer.get(key);
      this.deps.accessTrackingBuffer.set(key, {
        memoryId: id,
        ...(memoryPath ? { memoryPath, namespace } : {}),
        count: (existing?.count ?? 0) + 1,
        lastAccessed: now,
      });
    }
    if (this.deps.accessTrackingBuffer.size >= this.deps.config.accessTrackingBufferMaxSize) {
      this.deps.trackRecallBackgroundWrite(
        this.flushAccessTracking(),
        "background access tracking flush",
      );
    }
  }

  /**
   * Flush access tracking buffer to disk.
   * Called during consolidation or when buffer is full.
   */
  async flushAccessTracking(): Promise<void> {
    if (this.deps.accessTrackingBuffer.size === 0) return;

    const bufferedNamespaces = new Set<string>();
    for (const [, update] of this.deps.accessTrackingBuffer) {
      bufferedNamespaces.add(
        update.namespace ??
          (update.memoryPath
            ? this.deps.namespaceFromPath(update.memoryPath)
            : this.deps.config.defaultNamespace),
      );
    }
    const configuredNamespaces = resolveNamespaceCapabilities(this.deps.config).namespaces
      ? [
          this.deps.config.defaultNamespace,
          this.deps.config.sharedNamespace,
          ...this.deps.config.namespacePolicies.map((p) => p.name),
        ]
      : [this.deps.config.defaultNamespace];
    const namespaces = Array.from(new Set([...configuredNamespaces, ...bufferedNamespaces]));
    const memoriesByNamespace = new Map<string, MemoryFile[]>();
    const memories = await this.deps.readAllMemoriesForNamespaces(namespaces);
    for (const memory of memories) {
      const namespace = this.deps.namespaceFromPath(memory.path);
      const list = memoriesByNamespace.get(namespace) ?? [];
      list.push(memory);
      memoriesByNamespace.set(namespace, list);
    }

    const entriesByNamespace = new Map<string, AccessTrackingEntry[]>();
    const mergedEntriesByNamespace = new Map<string, Map<string, AccessTrackingEntry>>();
    const storageDirByNamespace = new Map<string, string | null>();
    for (const [, update] of this.deps.accessTrackingBuffer) {
      const memoryPath = update.memoryPath;
      const namespace =
        update.namespace ??
        (memoryPath
          ? this.deps.namespaceFromPath(memoryPath)
          : this.deps.config.defaultNamespace);
      const namespaceMemories = memoriesByNamespace.get(namespace);
      let storageDir = storageDirByNamespace.get(namespace);
      if (storageDir === undefined) {
        const storage = await this.deps.storageRouter.storageFor(namespace);
        storageDir = typeof storage.dir === "string" && storage.dir.length > 0 ? storage.dir : null;
        storageDirByNamespace.set(namespace, storageDir);
      }
      const requestedPaths = memoryPath
        ? [
            memoryPath,
            ...(storageDir ? accessTrackingPathCandidates(storageDir, memoryPath) : []),
          ]
        : [];
      const memory = memoryPath
        ? namespaceMemories?.find((candidate) =>
            matchesMemoryPath(candidate.path, memoryPath, this.deps.config.memoryDir),
          ) ??
          namespaceMemories?.find((candidate) =>
            requestedPaths.some((requestedPath) =>
              matchesMemoryPath(candidate.path, requestedPath, this.deps.config.memoryDir),
            ),
          )
        : namespaceMemories?.find((candidate) => candidate.frontmatter.id === update.memoryId);
      if (!memory) continue;

      const namespaceEntries = mergedEntriesByNamespace.get(namespace) ?? new Map();
      const existing = namespaceEntries.get(memory.path);
      const existingLastAccessed = existing?.lastAccessed;
      const lastAccessed =
        existingLastAccessed &&
        Date.parse(existingLastAccessed) > Date.parse(update.lastAccessed)
          ? existingLastAccessed
          : update.lastAccessed;
      namespaceEntries.set(memory.path, {
        memoryId: existing?.memoryId ?? update.memoryId,
        memoryPath: memory.path,
        newCount:
          (existing?.newCount ?? (memory.frontmatter.accessCount ?? 0)) + update.count,
        lastAccessed,
      });
      mergedEntriesByNamespace.set(namespace, namespaceEntries);
    }
    for (const [namespace, entries] of mergedEntriesByNamespace) {
      entriesByNamespace.set(namespace, Array.from(entries.values()));
    }

    let flushedCount = 0;
    for (const [namespace, entries] of entriesByNamespace) {
      const storage = await this.deps.storageRouter.storageFor(namespace);
      await storage.flushAccessTracking(entries);
      flushedCount += entries.length;
    }
    this.deps.accessTrackingBuffer.clear();
    log.debug(`flushed ${flushedCount} access tracking entries`);
  }
}

/**
 * Namespace read-fanout coordinator — extracted from the orchestrator
 * (issue #1526, seam 26).
 *
 * Owns namespace-scoped READ fanout (never namespace RESOLUTION — the
 * ScopePlan resolver from #1521 stays the single authority for that):
 *   - storage-dir hint loading from the catalog
 *   - cross-namespace search and memory/archive reads
 *   - scoped memory candidate search and artifact recall fanout
 *   - artifact source status resolution (with per-storage cache)
 *   - path→namespace and storage-dir→namespace mapping helpers
 *
 * Behavior-preserving move from orchestrator.ts (late-binding deps rule,
 * seams 18–25).
 */

import { existsSync, readFileSync } from "node:fs";
import { stat } from "node:fs/promises";
import path from "node:path";
import { resolveNamespaceCapabilities } from "../capabilities.js";
import { StorageManager } from "../index.js";
import { NamespaceCatalog } from "../namespaces/catalog.js";
import { namespaceIdentityFromToken, namespaceIdentityToken, normalizeNamespaceIdentity } from "../namespaces/identity.js";
import { NamespaceSearchRouter } from "../namespaces/search.js";
import { NamespaceStorageRouter } from "../namespaces/storage.js";
import { ARTIFACT_STATUS_CACHE_TTL_MS, mergeArtifactRecallCandidates, tokenizeRecallQuery } from "./orchestrator-helpers.js";
import { qmdCollectionPathParts } from "./qmd-result-resolver.js";
import { qmdCollectionNamespaceFromPrefix as computeQmdCollectionNamespaceFromPrefix } from "./orchestrator-namespace-scope.js";
import { resolveNamespaceFromStorageDir } from "../scopes/scope-plan.js";
import { checkCorpusReadAbort, type CorpusReadOptions } from "../corpus-read-cancellation.js";
import type { ArtifactRecallOptions } from "./recall-search-prefilter.js";
import type { SearchBackend, SearchExecutionOptions, SearchQueryOptions } from "../search/port.js";
import type { MemoryFile, PluginConfig, QmdSearchResult } from "../types.js";

export interface NamespaceReadFanoutDeps {
  readonly artifactSourceStatusCache: WeakMap<StorageManager, { loadedAtMs: number; statusVersion: number; statuses: Map<string, "active" | "superseded" | "archived" | "missing"> }>;
  readonly config: PluginConfig;
  configuredNamespaceList(): string[];
  fetchActiveArtifactsForNamespace(
    namespace: string,
    prompt: string,
    targetCount: number,
    options?: ArtifactRecallOptions,
  ): Promise<MemoryFile[]>;
  loadNamespaceStorageDirHintsFromCatalog(): void;
  readonly namespaceCatalog: NamespaceCatalog;
  namespaceFromPath(p: string): string;
  readonly namespaceSearchRouter: NamespaceSearchRouter;
  namespaceStorageDirHintOwnershipRank(
    record: { namespace: string },
    resolvedStorageDir: string,
    configured: Set<string>,
  ): number;
  readonly namespaceStorageDirHints: Map<string, Set<string>>;
  namespaceStorageDirHintsLoaded: boolean;
  preferNamespaceStorageDirHintOwner(
    current: { namespace: string; identityToken: string; storageDir: string },
    candidate: { namespace: string; identityToken: string; storageDir: string },
    resolvedStorageDir: string,
    configured: Set<string>,
  ): { namespace: string; identityToken: string; storageDir: string };
  readonly qmd: SearchBackend;
  rememberNamespaceStorageDirHint(namespace: string, storageDir?: string): void;
  storageDirMatchesNamespaceHint(namespace: string, storageDir: string): boolean;
  readonly storageRouter: NamespaceStorageRouter;
}

export class NamespaceReadFanoutCoordinator {
  constructor(
    private readonly deps: NamespaceReadFanoutDeps,
  ) {}

  preferNamespaceStorageDirHintOwner(
    current: { namespace: string; identityToken: string; storageDir: string },
    candidate: { namespace: string; identityToken: string; storageDir: string },
    resolvedStorageDir: string,
    configured: Set<string>,
  ): { namespace: string; identityToken: string; storageDir: string } {
    const currentRank = this.deps.namespaceStorageDirHintOwnershipRank(
      current,
      resolvedStorageDir,
      configured,
    );
    const candidateRank = this.deps.namespaceStorageDirHintOwnershipRank(
      candidate,
      resolvedStorageDir,
      configured,
    );
    if (candidateRank < currentRank) return candidate;
    if (candidateRank > currentRank) return current;

    const byName = candidate.namespace.localeCompare(current.namespace);
    if (byName < 0) return candidate;
    if (byName > 0) return current;
    return candidate.identityToken.localeCompare(current.identityToken) < 0
      ? candidate
      : current;
  }

  loadNamespaceStorageDirHintsFromCatalog(): void {
    if (this.deps.namespaceStorageDirHintsLoaded || !this.deps.namespaceCatalog.enabled) return;
    this.deps.namespaceStorageDirHintsLoaded = true;
    const catalogPath = path.join(this.deps.config.memoryDir, "state", "namespaces.jsonl");
    if (!existsSync(catalogPath)) return;

    let body: string;
    try {
      body = readFileSync(catalogPath, "utf8");
    } catch {
      return;
    }

    const compactedByNamespace = new Map<
      string,
      { namespace: string; identityToken: string; storageDir: string }
    >();
    for (const line of body.split(/\r?\n/)) {
      const trimmed = line.trim();
      if (!trimmed) continue;
      try {
        const parsed = JSON.parse(trimmed) as unknown;
        if (!parsed || typeof parsed !== "object" || Array.isArray(parsed)) continue;
        const record = parsed as Record<string, unknown>;
        if (
          typeof record.namespace !== "string" ||
          typeof record.storageDir !== "string" ||
          typeof record.identityToken !== "string"
        ) {
          continue;
        }
        const namespace = normalizeNamespaceIdentity(record.namespace);
        if (!namespace || record.identityToken !== namespaceIdentityToken(namespace)) continue;
        compactedByNamespace.set(namespace, {
          namespace,
          identityToken: record.identityToken,
          storageDir: record.storageDir,
        });
      } catch {
        // Catalog hints are best-effort. The catalog reader still owns full recovery.
      }
    }

    const configured = new Set(
      this.deps.configuredNamespaceList().map((namespace) => normalizeNamespaceIdentity(namespace)),
    );
    const preferredByStorageDir = new Map<
      string,
      { namespace: string; identityToken: string; storageDir: string }
    >();
    for (const record of compactedByNamespace.values()) {
      if (!this.deps.storageDirMatchesNamespaceHint(record.namespace, record.storageDir)) {
        continue;
      }
      const resolvedStorageDir = path.resolve(record.storageDir);
      const current = preferredByStorageDir.get(resolvedStorageDir);
      preferredByStorageDir.set(
        resolvedStorageDir,
        current
          ? this.deps.preferNamespaceStorageDirHintOwner(
              current,
              record,
              resolvedStorageDir,
              configured,
            )
          : record,
      );
    }
    for (const record of preferredByStorageDir.values()) {
      this.deps.rememberNamespaceStorageDirHint(record.namespace, record.storageDir);
    }
  }

  async searchAcrossNamespaces(options: {
    query: string;
    namespaces?: string[];
    maxResults?: number;
    mode?: "search" | "hybrid" | "bm25" | "vector";
    searchOptions?: SearchQueryOptions;
    execution?: SearchExecutionOptions;
  }): Promise<QmdSearchResult[]> {
    if (
      resolveNamespaceCapabilities(this.deps.config).namespaces &&
      options.namespaces !== undefined &&
      options.namespaces.length === 0
    ) {
      return [];
    }
    const namespaces = resolveNamespaceCapabilities(this.deps.config).namespaces
      ? Array.from(
          new Set(
            (options.namespaces?.length
              ? options.namespaces
              : this.deps.configuredNamespaceList()
            )
              .map((value) => value.trim())
              .filter(Boolean),
          ),
        )
      : [this.deps.config.defaultNamespace];

    if (!resolveNamespaceCapabilities(this.deps.config).namespaces) {
      switch (options.mode) {
        case "hybrid":
          return await this.deps.qmd.hybridSearch(
            options.query,
            undefined,
            options.maxResults,
            options.execution,
          );
        case "bm25":
          return await this.deps.qmd.bm25Search(
            options.query,
            undefined,
            options.maxResults,
            options.execution,
          );
        case "vector":
          return await this.deps.qmd.vectorSearch(
            options.query,
            undefined,
            options.maxResults,
            options.execution,
          );
        default:
          return await this.deps.qmd.search(
            options.query,
            undefined,
            options.maxResults,
            options.searchOptions,
            options.execution,
          );
      }
    }

    return await this.deps.namespaceSearchRouter.searchAcrossNamespaces({
      query: options.query,
      namespaces,
      maxResults: options.maxResults,
      mode: options.mode,
      searchOptions: options.searchOptions,
      execution: options.execution,
    });
  }

  async resolveArtifactSourceStatuses(
    storage: StorageManager,
    sourceIds: string[],
    options?: CorpusReadOptions,
  ): Promise<Map<string, "active" | "superseded" | "archived" | "missing">> {
    checkCorpusReadAbort(options);
    const currentStatusVersion = storage.getMemoryStatusVersion();
    const cached = this.deps.artifactSourceStatusCache.get(storage);
    let snapshot = cached;
    const isFresh =
      snapshot !== undefined &&
      Date.now() - snapshot.loadedAtMs <=
        ARTIFACT_STATUS_CACHE_TTL_MS &&
      snapshot.statusVersion === currentStatusVersion;

    const rebuildSnapshot = async () => {
      const MAX_STABLE_READ_ATTEMPTS = 3;
      let latestStatuses = new Map<
        string,
        "active" | "superseded" | "archived" | "missing"
      >();
      let latestVersionAfter = storage.getMemoryStatusVersion();

      for (let attempt = 0; attempt < MAX_STABLE_READ_ATTEMPTS; attempt += 1) {
        // Each attempt is a full corpus read; an abandoned caller must not buy a
        // second or third one (issue #2307).
        checkCorpusReadAbort(options);
        const versionBefore = storage.getMemoryStatusVersion();
        const allMemories = await storage.readAllMemories(options);
        // An abort landing between the read and the publish below would otherwise
        // cache and return a snapshot to a caller that had already cancelled
        // (issue #2307 review).
        checkCorpusReadAbort(options);
        const versionAfter = storage.getMemoryStatusVersion();
        latestVersionAfter = versionAfter;
        latestStatuses = new Map(
          allMemories.map((m) => [
            m.frontmatter.id,
            (m.frontmatter.status ?? "active") as
              | "active"
              | "superseded"
              | "archived"
              | "missing",
          ]),
        );

        if (versionAfter === versionBefore) {
          const rebuilt = {
            loadedAtMs: Date.now(),
            statusVersion: versionAfter,
            statuses: latestStatuses,
          };
          this.deps.artifactSourceStatusCache.set(storage, rebuilt);
          return rebuilt;
        }
      }

      // Sustained write churn: return latest read without caching a potentially torn snapshot.
      return {
        loadedAtMs: Date.now(),
        statusVersion: latestVersionAfter,
        statuses: latestStatuses,
      };
    };

    if (!isFresh) {
      snapshot = await rebuildSnapshot();
    } else {
      // Warm cache may miss brand-new sourceMemoryId values created after snapshot build.
      // Refresh once on-demand when unseen IDs are requested.
      const hasUnknownSourceIds = sourceIds.some(
        (id) => !snapshot?.statuses.has(id),
      );
      if (hasUnknownSourceIds) {
        snapshot = await rebuildSnapshot();
      }
    }

    // Persist negative lookups in the cached snapshot so stale source IDs do not
    // trigger repeated full snapshot rebuilds on every matching recall.
    for (const id of sourceIds) {
      if (!snapshot?.statuses.has(id)) {
        snapshot?.statuses.set(id, "missing");
      }
    }

    const statuses = new Map<
      string,
      "active" | "superseded" | "archived" | "missing"
    >();
    for (const id of sourceIds) {
      const status = snapshot?.statuses.get(id);
      if (status) {
        statuses.set(id, status);
      } else {
        statuses.set(id, "missing");
      }
    }
    return statuses;
  }

  async recallArtifactsAcrossNamespaces(
    prompt: string,
    recallNamespaces: string[],
    targetCount: number,
    options: ArtifactRecallOptions = {},
  ): Promise<MemoryFile[]> {
    if (targetCount <= 0) return [];
    const namespaces = Array.from(new Set(recallNamespaces));
    const filteredByNamespace = await Promise.all(
      namespaces.map((namespace) =>
        this.deps.fetchActiveArtifactsForNamespace(namespace, prompt, targetCount, options),
      ),
    );

    return mergeArtifactRecallCandidates(filteredByNamespace, targetCount);
  }

  async searchScopedMemoryCandidates(
    candidatePaths: Set<string>,
    query: string,
    limit: number,
    options?: {
      allowArchived?: boolean;
    },
  ): Promise<QmdSearchResult[]> {
    const cappedLimit = Math.max(0, limit);
    if (cappedLimit === 0 || candidatePaths.size === 0) return [];

    const tokens = Array.from(new Set(tokenizeRecallQuery(query)));
    const memories = (
      await Promise.all(
        Array.from(candidatePaths).map(async (memoryPath) => {
          const namespace = resolveNamespaceCapabilities(this.deps.config).namespaces
            ? this.deps.namespaceFromPath(memoryPath)
            : this.deps.config.defaultNamespace;
          const storage = await this.deps.storageRouter.storageFor(namespace);
          const memory = await storage.readMemoryByPath(memoryPath);
          return memory ? { memory, namespace } : null;
        }),
      )
    ).filter(
      (entry): entry is { memory: MemoryFile; namespace: string } => entry !== null,
    );

    const results: QmdSearchResult[] = [];
    for (const { memory, namespace } of memories) {
      const status = memory.frontmatter.status ?? "active";
      if (!options?.allowArchived && status !== "active") continue;

      const haystack = [
        memory.content,
        memory.frontmatter.category,
        ...(memory.frontmatter.tags ?? []),
      ]
        .join(" ")
        .toLowerCase();
      let hits = 0;
      for (const token of tokens) {
        if (haystack.includes(token)) hits += 1;
      }
      const score = tokens.length > 0 ? hits / tokens.length : 0.01;
      if (tokens.length > 0 && hits === 0) continue;

      results.push({
        docid: memory.frontmatter.id,
        namespace,
        path: memory.path,
        score,
        snippet: memory.content.slice(0, 400).replace(/\n/g, " "),
        origin: memory.frontmatter.origin,
        transport: "scoped_prefilter",
      });
    }

    return results.sort((a, b) => b.score - a.score).slice(0, cappedLimit);
  }

  async resolveStateDirForNamespace(
    namespace: string,
  ): Promise<string> {
    if (!resolveNamespaceCapabilities(this.deps.config).namespaces) {
      return path.join(this.deps.config.memoryDir, "state");
    }
    if (namespace !== this.deps.config.defaultNamespace) {
      return path.join(this.deps.config.memoryDir, "namespaces", namespace, "state");
    }
    const candidate = path.join(
      this.deps.config.memoryDir,
      "namespaces",
      this.deps.config.defaultNamespace,
    );
    try {
      const candidateStat = await stat(candidate);
      if (candidateStat.isDirectory()) {
        return path.join(candidate, "state");
      }
    } catch {
      // Fall back to the legacy root when the migrated default namespace directory is absent.
    }
    return path.join(this.deps.config.memoryDir, "state");
  }

  namespaceFromPath(p: string): string {
    if (!resolveNamespaceCapabilities(this.deps.config).namespaces) return this.deps.config.defaultNamespace;
    const parts = qmdCollectionPathParts(p);
    const collectionNamespace = parts
      ? computeQmdCollectionNamespaceFromPrefix(parts.collection, this.deps.config)
      : null;
    if (collectionNamespace) return collectionNamespace;
    const pathParts = p.replaceAll("\\", "/").split("/");
    const namespaceIndex = pathParts.indexOf("namespaces");
    const namespaceToken = namespaceIndex >= 0 ? pathParts[namespaceIndex + 1] : undefined;
    if (!namespaceToken) return this.deps.config.defaultNamespace;
    return namespaceIdentityFromToken(namespaceToken) ?? namespaceToken;
  }

  storageDirNamespace(storageDir: string): string {
    // #1521: delegates to the scope-module resolver. The inline dir→namespace
    // derivation (token round-trip guard, catalog hints) is retired so the
    // adHocNamespaceResolutions ratchet no longer counts this site. Hints are
    // loaded lazily via the callback (only after early returns, matching the
    // original behavior — codex P2).
    return resolveNamespaceFromStorageDir(storageDir, {
      config: this.deps.config,
      configuredNamespaces: this.deps.configuredNamespaceList(),
      hints: this.deps.namespaceStorageDirHints,
      loadHints: () => this.deps.loadNamespaceStorageDirHintsFromCatalog(),
    });
  }

  async readAllMemoriesForNamespaces(
    namespaces: string[],
    options?: CorpusReadOptions,
  ): Promise<MemoryFile[]> {
    const uniq = Array.from(new Set(namespaces.filter(Boolean)));
    const lists = await Promise.all(
      uniq.map(async (ns) => {
        const sm = await this.deps.storageRouter.storageFor(ns);
        return sm.readAllMemories(options);
      }),
    );
    return lists.flat();
  }

}

/**
 * @remnic/core — per-directory abstract/overview sidecars (issue #2977).
 *
 * One derived `overview.md` per memory directory (category roots and every
 * directory beneath them, including `namespaces/<ns>/` subtrees), rendered
 * bottom-up from existing memory content:
 *
 *   - the ABSTRACT is a single line (<=256 chars) composed from child titles;
 *   - the OVERVIEW body lists one preview line per child memory and embeds
 *     each child DIRECTORY's abstract, so a parent summarizes its subtree
 *     without embedding full child overviews.
 *
 * Determinism: no LLM, no embeddings. Content is assembled with the same
 * preview machinery the OKF index files use (`normalizeProjectionPreview`).
 *
 * Invalidation: each sidecar stores a content-free fingerprint of its subtree
 * (child name|size|mtime for files, recursive fingerprints for child dirs).
 * Any add/edit/delete anywhere below a directory changes its fingerprint, so
 * `loadDirectorySidecar` can detect staleness with `readdir`+`stat` alone and
 * refresh without reading child memory files first. Eager regeneration runs
 * through {@link runDirectorySidecarMaintenance}; lazy refresh on read covers
 * direct-write paths that bypass scheduled maintenance (Gotcha #43).
 *
 * Isolation: sidecars are derived artifacts, excluded from generic recall via
 * `isGenericRecallExcludedPath` (basename match, the same tradeoff OKF makes
 * for `index.md`/`log.md`) while staying full-text searchable. Files at the
 * sidecar path WITHOUT the marker are user content: never overwritten, never
 * removed.
 *
 * Layer 2: {@link refreshDirectorySidecarsAfterWrite} refreshes only the
 * changed directory and its category ancestors. `enabled: false` is a
 * proven no-op (no reads, no writes).
 *
 * Layer 3 (this slice): {@link applyDirectorySidecarDrillDown} scores
 * fresh sidecars and attaches the winning directory's abstract to hits.
 * `enabled` stays a function argument — not a parseConfig key (`config.ts`
 * and `types.ts` are at their file-size ratchets). Retrieval never writes.
 * xray trajectory, storage write-hook, parseConfig wiring, and LLM
 * summarization remain later layers on #2977.
 */

import { createHash } from "node:crypto";
import { lstatSync, readFileSync, readdirSync, statSync, unlinkSync } from "node:fs";
import path from "node:path";

import { coerceBooleanLike } from "./connectors/coerce.js";
import { writeFileAtomically } from "./maintenance/atomic-file.js";
import { normalizeProjectionPreview } from "./memory-projection-format.js";
import { OKF_RESERVED_BASENAMES } from "./okf/type-mapping.js";
import { RECALL_FALLBACK_DIRS } from "./utils/category-dir.js";

export const DIRECTORY_SIDECAR_BASENAME = "overview.md";
export const DIRECTORY_SIDECAR_MARKER = "<!-- remnic-directory-sidecar -->";
/** Prefix prepended to a hit snippet when a fresh directory abstract attaches. */
export const NEIGHBORHOOD_ABSTRACT_LABEL = "Neighborhood:";

const ABSTRACT_MAX_CHARS = 256;
const OVERVIEW_MAX_CHARS = 4000;
const DEFAULT_QUERY_LIMIT = 5;
const CATEGORY_ROOTS: ReadonlySet<string> = new Set(RECALL_FALLBACK_DIRS);

/** Config fields this slice owns. Mix into `PluginConfig` in a later layer. */
export interface DirectorySidecarSettings {
  /** Populate sidecars on memory writes. Default false. */
  directorySidecarsEnabled: boolean;
}

/** Strict off-default: only an explicit true/"true"/1 opts in. */
export function parseDirectorySidecarsEnabled(raw: unknown): boolean {
  return coerceBooleanLike(raw, "directorySidecarsEnabled") === true;
}

const sidecarEnabledByDir = new Map<string, boolean>();

export function setDirectorySidecarsEnabledForDir(memoryDir: string, enabled: boolean): void {
  sidecarEnabledByDir.set(path.resolve(memoryDir), enabled === true);
}

export function isDirectorySidecarsEnabledForDir(memoryDir: string): boolean {
  let dir = path.resolve(memoryDir);
  for (;;) {
    if (sidecarEnabledByDir.has(dir)) return sidecarEnabledByDir.get(dir) === true;
    const parent = path.dirname(dir);
    if (parent === dir) return false;
    dir = parent;
  }
}

/** Basenames never treated as child memories (ours plus OKF's reserved ones). */
const RESERVED_CHILD_BASENAMES: Readonly<Record<string, true>> = Object.freeze({
  ...OKF_RESERVED_BASENAMES,
  [DIRECTORY_SIDECAR_BASENAME]: true,
});

export interface DirectorySidecar {
  /** Absolute directory the sidecar describes. */
  readonly dir: string;
  /** Single-line L0 abstract (<=256 chars). */
  readonly abstract: string;
  /** Abstract plus the per-child preview body (<=4000 chars). */
  readonly overview: string;
  /** Number of memory `.md` children in this directory. */
  readonly childCount: number;
  /** False when the stored fingerprint no longer matches the subtree. */
  readonly fresh: boolean;
}

export interface DirectorySidecarMatch extends DirectorySidecar {
  readonly score: number;
}

/** Minimal hit shape drill-down mutates. Extra fields pass through. */
export interface DirectorySidecarHit {
  path: string;
  snippet: string;
  score: number;
}

export interface DirectorySidecarReport {
  written: string[];
  removed: string[];
}

interface ParsedSidecar {
  abstract: string;
  overview: string;
  childCount: number;
  fingerprint: string;
}

function listEntries(dir: string) {
  try {
    return readdirSync(dir, { withFileTypes: true });
  } catch {
    return [];
  }
}

/** Root check that refuses symlinks (fs-boundary rule, PRs #1938/#1999). */
function isRealDirectory(entryPath: string): boolean {
  try {
    const stats = lstatSync(entryPath);
    return !stats.isSymbolicLink() && stats.isDirectory();
  } catch {
    return false;
  }
}

function memoryChildren(dir: string): string[] {
  // Dirent.isFile() is false for symlinks, so a linked memory never enters the corpus.
  return listEntries(dir)
    .filter((entry) => entry.isFile() && !RESERVED_CHILD_BASENAMES[entry.name] && entry.name.endsWith(".md"))
    .map((entry) => entry.name)
    .sort((a, b) => a.localeCompare(b));
}

function directoryChildren(dir: string): string[] {
  // Dirent.isDirectory() is false for symlinks (fs-boundary rule, PRs #1938/#1999).
  return listEntries(dir)
    .filter((entry) => entry.isDirectory())
    .map((entry) => entry.name)
    .sort((a, b) => a.localeCompare(b));
}

/**
 * Content-free subtree fingerprint: sha256 over sorted child descriptors.
 * Files contribute `name|size|mtimeMs`; directories contribute their own
 * recursive fingerprint, so any change below a directory invalidates every
 * ancestor. Reads no file contents.
 */
export function directoryFingerprint(dir: string): string {
  const hash = createHash("sha256");
  for (const name of memoryChildren(dir)) {
    try {
      const stats = statSync(path.join(dir, name));
      hash.update(`f|${name}|${stats.size}|${Math.trunc(stats.mtimeMs)}\n`);
    } catch {
      hash.update(`f|${name}|missing\n`);
    }
  }
  for (const name of directoryChildren(dir)) {
    hash.update(`d|${name}|${directoryFingerprint(path.join(dir, name))}\n`);
  }
  return hash.digest("hex");
}

function readFileOrNull(target: string): string | null {
  try {
    return readFileSync(target, "utf8");
  } catch {
    return null;
  }
}

function parseSidecar(content: string): ParsedSidecar | null {
  if (!content.startsWith(DIRECTORY_SIDECAR_MARKER)) return null;
  const fingerprint = /^fingerprint: ([0-9a-f]{64})$/m.exec(content)?.[1];
  if (!fingerprint) return null;
  const abstract = /^## Abstract\n([^\n]+)$/m.exec(content)?.[1] ?? "";
  const overviewStart = content.indexOf("## Abstract");
  const overview =
    overviewStart === -1 ? "" : content.slice(overviewStart, overviewStart + OVERVIEW_MAX_CHARS).trim();
  // The `* name — preview` child bullets are the rendered child count.
  const childCount = (content.match(/^\* .+$/gm) ?? []).length;
  return { abstract, overview, childCount, fingerprint };
}

function sidecarPath(dir: string): string {
  return path.join(dir, DIRECTORY_SIDECAR_BASENAME);
}

function renderSidecar(dir: string, fingerprint: string, childAbstracts: Map<string, string>): string | null {
  const children = memoryChildren(dir);
  const childDirs = directoryChildren(dir).filter((name) => childAbstracts.has(path.join(dir, name)));
  if (children.length === 0 && childDirs.length === 0) return null;

  const previews = children.map((name) => {
    try {
      return normalizeProjectionPreview(readFileSync(path.join(dir, name), "utf8"), 120);
    } catch {
      return "";
    }
  });
  const titles = children.map(
    (name, index) => previews[index].split(" ").slice(0, 8).join(" ") || name.replace(/\.md$/, ""),
  );
  const abstract = normalizeProjectionPreview(
    `${path.basename(dir)}/ — ${children.length} memories: ${titles.slice(0, 5).join(" · ")}`,
    ABSTRACT_MAX_CHARS,
  );

  const lines = [
    DIRECTORY_SIDECAR_MARKER,
    `fingerprint: ${fingerprint}`,
    `# ${path.basename(dir)}/ overview`,
    "",
    "## Abstract",
    abstract,
    "",
    "## Children",
  ];
  for (const [index, name] of children.entries()) {
    lines.push(`* ${name} — ${previews[index]}`);
  }
  for (const name of childDirs) {
    lines.push(`### ${name}/`);
    lines.push(childAbstracts.get(path.join(dir, name)) ?? "");
  }
  lines.push("");
  return lines.join("\n");
}

/** Scope roots whose category subtrees carry sidecars: the memory root plus every namespace root. */
function scopeRoots(memoryDir: string): string[] {
  const roots = [memoryDir];
  const namespacesRoot = path.join(memoryDir, "namespaces");
  for (const entry of listEntries(namespacesRoot)) {
    if (entry.isDirectory() && isRealDirectory(path.join(namespacesRoot, entry.name))) {
      roots.push(path.join(namespacesRoot, entry.name));
    }
  }
  return roots;
}

/**
 * Every directory that should carry a sidecar, deepest first (post-order) so
 * parents render after their children and can embed child abstracts.
 */
function collectSidecarDirs(scopeRoot: string): string[] {
  const dirs: string[] = [];
  const walk = (dir: string, isCategoryRoot: boolean): boolean => {
    let carries = memoryChildren(dir).length > 0;
    for (const name of directoryChildren(dir)) {
      carries = walk(path.join(dir, name), false) || carries;
    }
    // A directory that stopped carrying memories must still be visited so its
    // orphaned sidecar can be pruned or rewritten (cache-invalidation completeness).
    const hasSidecar = readFileOrNull(sidecarPath(dir))?.startsWith(DIRECTORY_SIDECAR_MARKER) === true;
    if (isCategoryRoot || carries || hasSidecar) dirs.push(dir);
    return carries;
  };
  for (const category of RECALL_FALLBACK_DIRS) {
    const categoryDir = path.join(scopeRoot, category);
    if (!isRealDirectory(categoryDir)) continue;
    walk(categoryDir, true);
  }
  return dirs;
}

async function syncSidecarDir(
  dir: string,
  enabled: boolean,
  childAbstracts: Map<string, string>,
  written: string[],
  removed: string[],
): Promise<void> {
  const target = sidecarPath(dir);
  const raw = readFileOrNull(target);
  const existing = raw !== null && raw.startsWith(DIRECTORY_SIDECAR_MARKER) ? raw : null;
  if (!enabled) {
    if (existing !== null) {
      unlinkSync(target);
      removed.push(target);
    }
    return;
  }
  const next = renderSidecar(dir, directoryFingerprint(dir), childAbstracts);
  if (next === null) {
    if (existing !== null) {
      unlinkSync(target);
      removed.push(target);
    }
    return;
  }
  const parsedNext = parseSidecar(next);
  if (parsedNext) childAbstracts.set(dir, parsedNext.abstract);
  if (raw === next) return;
  if (existing === null && raw !== null) return; // user-authored file: hands off
  await writeFileAtomically(target, next);
  written.push(target);
}

function childAbstractsFromDisk(dir: string): Map<string, string> {
  const abstracts = new Map<string, string>();
  for (const name of directoryChildren(dir)) {
    const childDir = path.join(dir, name);
    const parsed = parseSidecar(readFileOrNull(sidecarPath(childDir)) ?? "");
    if (parsed) abstracts.set(childDir, parsed.abstract);
  }
  return abstracts;
}

/**
 * Category-root ancestry of a changed memory path, deepest first.
 * Paths outside a recall category return `[]` so writes to `state/` or
 * `namespaces/<ns>/` itself never mint a sidecar.
 */
export function directorySidecarAncestry(memoryDir: string, changedPath: string): string[] {
  const root = path.resolve(memoryDir);
  if (!isRealDirectory(root)) return [];
  const abs = path.isAbsolute(changedPath) ? path.resolve(changedPath) : path.resolve(root, changedPath);
  const rel = path.relative(root, abs);
  if (rel.startsWith("..") || path.isAbsolute(rel)) return [];
  const parts = rel.split(path.sep).filter(Boolean);
  let cursor = root;
  for (let i = 0; i < parts.length; i++) {
    cursor = path.join(cursor, parts[i] ?? "");
    try {
      if (lstatSync(cursor).isSymbolicLink()) return [];
    } catch {
      if (i === parts.length - 1) break;
      return [];
    }
  }
  const dirParts = isRealDirectory(abs) ? parts : parts.slice(0, -1);
  let categoryAt = -1;
  if (dirParts[0] === "namespaces" && dirParts.length >= 3 && CATEGORY_ROOTS.has(dirParts[2] ?? "")) {
    categoryAt = 2;
  } else if (CATEGORY_ROOTS.has(dirParts[0] ?? "")) {
    categoryAt = 0;
  }
  if (categoryAt === -1) return [];
  const dirs: string[] = [];
  for (let i = dirParts.length; i > categoryAt; i--) {
    const dir = path.join(root, ...dirParts.slice(0, i));
    if (!isRealDirectory(dir)) return [];
    dirs.push(dir);
  }
  return dirs;
}

/**
 * Regenerates directory sidecars incrementally. Unchanged sidecars are left
 * untouched; emptied directories lose theirs; user files at the sidecar path
 * (no marker) are never written or removed. With `enabled: false` every
 * generated sidecar is removed — the OKF index-maintenance contract.
 */
export async function runDirectorySidecarMaintenance(
  memoryDir: string,
  enabled: boolean,
): Promise<DirectorySidecarReport> {
  const written: string[] = [];
  const removed: string[] = [];
  for (const scope of scopeRoots(memoryDir)) {
    const childAbstracts = new Map<string, string>();
    for (const dir of collectSidecarDirs(scope)) {
      await syncSidecarDir(dir, enabled, childAbstracts, written, removed);
    }
  }
  return { written, removed };
}

/**
 * Incremental write-path refresh: only the changed directory and its
 * category ancestors, using the same fingerprint/render path as maintenance.
 * `enabled: false` returns immediately — no readdir, no writes.
 */
export async function refreshDirectorySidecarsAfterWrite(
  memoryDir: string,
  changedPath: string,
  enabled: boolean,
): Promise<DirectorySidecarReport> {
  if (!enabled) return { written: [], removed: [] };
  const written: string[] = [];
  const removed: string[] = [];
  for (const dir of directorySidecarAncestry(memoryDir, changedPath)) {
    await syncSidecarDir(dir, true, childAbstractsFromDisk(dir), written, removed);
  }
  return { written, removed };
}

/**
 * Read a directory's sidecar for retrieval. By default a stale sidecar is
 * refreshed in place (child directories first), which is what makes direct
 * writes that bypass maintenance still converge. With `{ refresh: false }`
 * the stored sidecar is returned as-is with `fresh: false` so callers can
 * observe staleness without writes.
 */
export async function loadDirectorySidecar(
  dir: string,
  options: { refresh?: boolean } = {},
): Promise<DirectorySidecar | null> {
  const refresh = options.refresh !== false;
  const target = sidecarPath(dir);
  const stored = readFileOrNull(target);
  const generated = stored !== null && stored.startsWith(DIRECTORY_SIDECAR_MARKER);
  const parsed = generated ? parseSidecar(stored) : null;
  const fingerprint = directoryFingerprint(dir);
  if (parsed !== null && (parsed.fingerprint === fingerprint || !refresh)) {
    return {
      dir,
      abstract: parsed.abstract,
      overview: parsed.overview,
      childCount: parsed.childCount,
      fresh: parsed.fingerprint === fingerprint,
    };
  }
  if (!refresh) return null;

  // Refresh bottom-up so this directory's body embeds current child abstracts.
  const childAbstracts = new Map<string, string>();
  for (const name of directoryChildren(dir)) {
    const child = await loadDirectorySidecar(path.join(dir, name));
    if (child) childAbstracts.set(path.join(dir, name), child.abstract);
  }
  const next = renderSidecar(dir, directoryFingerprint(dir), childAbstracts);
  if (next === null) {
    if (generated) unlinkSync(target);
    return null;
  }
  if (readFileOrNull(target) !== next) {
    if (stored !== null && !generated) {
      // User-authored file at the sidecar path: serve nothing rather than clobber it.
      return null;
    }
    await writeFileAtomically(target, next);
  }
  const refreshed = parseSidecar(next);
  return refreshed
    ? {
        dir,
        abstract: refreshed.abstract,
        overview: refreshed.overview,
        childCount: refreshed.childCount,
        fresh: true,
      }
    : null;
}

/**
 * Overview-query primitive for hierarchical retrieval (layer 1 of #2977):
 * score every sidecar's abstract (+3 per query term) and overview (+1 per
 * term) lexically, then return the most specific matches — when both a
 * directory and its descendant match, only the descendant is kept, matching
 * the drill-down semantics the full retrieval mode will build on.
 */
export async function findDirectorySidecarsForQuery(
  memoryDir: string,
  query: string,
  options: { namespace?: string; limit?: number; refresh?: boolean } = {},
): Promise<DirectorySidecarMatch[]> {
  const scope = options.namespace ? path.join(memoryDir, "namespaces", options.namespace) : memoryDir;
  if (!isRealDirectory(scope)) return [];
  const terms = query
    .toLowerCase()
    .split(/[^a-z0-9]+/)
    .filter((term) => term.length >= 2);

  const matches: DirectorySidecarMatch[] = [];
  for (const root of scopeRoots(scope)) {
    for (const dir of collectSidecarDirs(root)) {
      const sidecar = await loadDirectorySidecar(dir, { refresh: options.refresh });
      if (!sidecar) continue;
      const abstractLower = sidecar.abstract.toLowerCase();
      const overviewLower = sidecar.overview.toLowerCase();
      let score = 0;
      for (const term of terms) {
        if (abstractLower.includes(term)) score += 3;
        else if (overviewLower.includes(term)) score += 1;
      }
      if (score > 0) matches.push({ ...sidecar, score });
    }
  }
  matches.sort((a, b) => b.score - a.score || a.dir.localeCompare(b.dir));

  const limit = options.limit ?? DEFAULT_QUERY_LIMIT;
  return matches
    .filter((candidate) => !matches.some((other) => other.dir.startsWith(`${candidate.dir}${path.sep}`)))
    .slice(0, limit);
}

function attachNeighborhoodAbstract(snippet: string, abstract: string): string {
  const line = `${NEIGHBORHOOD_ABSTRACT_LABEL} ${abstract}`;
  if (snippet === line || snippet.startsWith(`${line}\n`)) return snippet;
  return snippet.length === 0 ? line : `${line}\n${snippet}`;
}

function mostSpecificSidecarForHit(
  memoryDir: string,
  hitPath: string,
  matches: readonly DirectorySidecarMatch[],
): DirectorySidecarMatch | null {
  if (path.basename(hitPath) === DIRECTORY_SIDECAR_BASENAME) return null;
  const abs = path.isAbsolute(hitPath) ? path.resolve(hitPath) : path.resolve(memoryDir, hitPath);
  let best: DirectorySidecarMatch | null = null;
  for (const match of matches) {
    const rel = path.relative(match.dir, abs);
    if (rel === "" || rel.startsWith("..") || path.isAbsolute(rel)) continue;
    if (best === null || match.dir.length > best.dir.length) best = match;
  }
  return best;
}

/**
 * Retrieval drill-down (layer 3 of #2977): score fresh directory sidecars
 * and attach the winning neighborhood abstract to hits under that directory.
 * `enabled: false` (the default) returns hits unchanged with no I/O.
 * Never writes. Does not reorder. parseConfig is not consulted.
 */
export async function applyDirectorySidecarDrillDown<T extends DirectorySidecarHit>(
  memoryDir: string,
  query: string,
  hits: readonly T[],
  options: { enabled?: boolean; namespace?: string; namespaces?: readonly string[] } = {},
): Promise<T[]> {
  if (options.enabled !== true) return hits as T[];
  const namespaces = options.namespaces;
  if (namespaces !== undefined && namespaces.length === 0) return hits as T[];
  const scopes = namespaces && namespaces.length > 0 ? namespaces : [options.namespace];
  const matchLists = await Promise.all(
    scopes.map((namespace) =>
      findDirectorySidecarsForQuery(memoryDir, query, { namespace, refresh: false }),
    ),
  );
  const matches = matchLists.flat();
  const fresh = matches.filter((match) => match.fresh && match.abstract.length > 0);
  if (fresh.length === 0) return [...hits];
  return hits.map((hit) => {
    const match = mostSpecificSidecarForHit(memoryDir, hit.path, fresh);
    if (!match) return hit;
    const snippet = attachNeighborhoodAbstract(hit.snippet, match.abstract);
    return snippet === hit.snippet ? hit : { ...hit, snippet };
  });
}

