/** Scoped flushes must never claim an opaque buffer without trusted ingestion ownership. */
export class SessionOwnershipError extends Error {
  constructor(message: string) {
    super(message);
    this.name = "SessionOwnershipError";
  }
}

const MAX_SET_TIMEOUT_MS = 2_147_483_647;

export async function awaitSessionFlushPhase<T>(
  task: () => Promise<T>,
  options: Pick<SessionFlushOptions, "abortSignal" | "extractionDeadlineMs" | "reason"> & {
    deadlineStage?: string;
    onDeadline?: () => void;
  },
): Promise<T> {
  const abortMessage =
    options.reason === "access_force_flush" ? "extraction force-flush aborted" : "session flush aborted";
  throwIfAborted(options.abortSignal, abortMessage);
  const deadline = options.extractionDeadlineMs;
  if (typeof deadline === "number" && Date.now() >= deadline) {
    options.onDeadline?.();
    throw new ExtractionDeadlineError(options.deadlineStage ?? "before_buffer_flush");
  }

  const taskPromise = Promise.resolve().then(task);
  if (!options.abortSignal && typeof deadline !== "number") return taskPromise;

  let abortHandler: (() => void) | undefined;
  let deadlineTimer: ReturnType<typeof setTimeout> | undefined;
  const abortPromise =
    options.abortSignal === undefined
      ? undefined
      : new Promise<T>((_resolve, reject) => {
          abortHandler = () => reject(abortError(abortMessage));
          options.abortSignal?.addEventListener("abort", abortHandler, { once: true });
        });
  const deadlinePromise =
    typeof deadline !== "number"
      ? undefined
      : new Promise<T>((_resolve, reject) => {
          const schedule = (): void => {
            const remainingMs = deadline - Date.now();
            if (remainingMs <= 0) {
              options.onDeadline?.();
              reject(new ExtractionDeadlineError(options.deadlineStage ?? "before_buffer_flush"));
              return;
            }
            deadlineTimer = setTimeout(schedule, Math.min(remainingMs, MAX_SET_TIMEOUT_MS));
            deadlineTimer.unref?.();
          };
          schedule();
        });
  const races: Promise<T>[] = [taskPromise];
  if (abortPromise) races.push(abortPromise);
  if (deadlinePromise) races.push(deadlinePromise);
  try {
    return await Promise.race(races);
  } finally {
    if (abortHandler && options.abortSignal) {
      options.abortSignal.removeEventListener("abort", abortHandler);
    }
    if (deadlineTimer) clearTimeout(deadlineTimer);
  }
}

export class SessionContextCoordinator {
  constructor(
    private readonly deps: SessionContextDeps,
  ) {}

  /**
   * Effective namespace a same-session LCM/structured-history READER must use
   * to find what the access `observe` surface WROTE (#1495 thread 2).
   *
   * This MUST mirror the `observe` scope plan's write-namespace resolution, NOT
   * `resolveSelfNamespace`: when no coding overlay applies, `observe` archives
   * under `config.defaultNamespace` (an unqualified observed turn is NOT moved
   * to the principal self namespace — identical to
   * `resolveCodingScopedWriteNamespace`/`memory_store`, rule 39). Only when a
   * coding overlay actually changes the namespace does the writer (and so the
   * reader) use the overlaid `project-*` namespace. Returning the self base for
   * the no-overlay case would prefix the read key with a namespace the writer
   * never used, so the reader would miss its own evidence.
   *
   * Honours the access-surface `principalOverride` (#1505 thread 2, codex): when
   * a recall supplies an authenticated principal NOT encoded in the raw
   * `sessionKey`, `observe` archived LCM under THAT principal's base namespace.
   * Deriving the base from `resolvePrincipal(sessionKey)` alone could fall back
   * to `default`, so principal `alice` observing `sess-1` would write under
   * `alice` but READ under `default`. Threading the override here keeps the read
   * base identical to the write base.
   *
   * READ-AUTHORIZATION gate (#1505 round 3, codex P2 "Gate LCM recall keys by
   * readable namespaces"): the overlay LCM read key is a `<principal>-project-*`
   * sub-namespace of the principal SELF base. The normal recall namespace set
   * below only substitutes the coding overlay when the principal SELF base is
   * actually in the readable recall set (`recallNamespacesForPrincipal` — gated
   * by `defaultRecallNamespaces.includes("self")` AND `canReadNamespace`). If a
   * principal can WRITE but not READ its self namespace (or `defaultRecall-
   * Namespaces` omits `self`), QMD/file recall never touches those overlay rows,
   * so neither may the LCM read key. When the self base is NOT readable, fall
   * back to the default store — exactly what an unqualified, unauthorized recall
   * resolves to — rather than injecting overlay rows the rest of recall excludes
   * (rule 42 read/write parity; rule 48 least-privilege).
   */
  lcmReadNamespaceForSession(
    sessionKey?: string,
    principalOverride?: string,
  ): string {
    const principal =
      typeof principalOverride === "string" && principalOverride.length > 0
        ? principalOverride
        : this.deps.resolvePrincipal(sessionKey);
    const base = defaultNamespaceForPrincipal(principal, this.deps.config);
    const overlaid = this.deps.applyCodingNamespaceOverlay(sessionKey, base);
    // No overlay → collapse to the default store so the LCM key is the raw
    // sessionKey, exactly what an unqualified observe archived under.
    if (overlaid === base) return this.deps.config.defaultNamespace;
    // Overlay applied. Only honour it when the principal SELF base is in the
    // readable recall set (same gate the recall namespace set uses to
    // substitute the overlay). Otherwise the overlay rows are unauthorized for
    // this reader — fall back to the default store so the LCM read matches
    // what QMD/file recall would surface.
    const selfReadableInRecall = recallNamespacesForPrincipal(
      principal,
      this.deps.config,
    ).includes(base);
    return selfReadableInRecall ? overlaid : this.deps.config.defaultNamespace;
  }

  /**
   * Attach a coding-agent context to a session (issue #569). Called by the
   * Claude Code / Codex / Cursor connectors at session start after
   * `resolveGitContext(cwd)`. The context is consulted by the recall path
   * and the write path so that memories route to a project- (and optionally
   * branch-) scoped namespace.
   *
   * Pass `null` to clear.
   */
  setCodingContextForSession(sessionKey: string, codingContext: CodingContext | null): void {
    if (typeof sessionKey !== "string" || sessionKey.length === 0) return;
    // Defensive init — `Object.create(Orchestrator.prototype)` stubs in
    // legacy tests skip class-field initializers. The init runs on the
    // ORCHESTRATOR via deps (PR #1802 review: writing here would create
    // the map on the coordinator while reads keep going through deps).
    this.deps.ensureSessionBindingMaps();
    if (codingContext === null) {
      this.deps._codingContextBySession.delete(sessionKey);
      return;
    }
    this.deps._codingContextBySession.set(sessionKey, codingContext);
  }

  /**
   * Read-only accessor for the coding context attached to a session. Returns
   * `null` when none is set. Used by `remnic doctor` and by tests.
   *
   * Defensive `_codingContextBySession` lookup — legacy orchestrator-flush
   * tests use `Object.create(Orchestrator.prototype)` which does not run
   * class-field initializers, so the Map may be undefined on stubs.
   */
  getCodingContextForSession(sessionKey: string | undefined): CodingContext | null {
    if (typeof sessionKey !== "string" || sessionKey.length === 0) return null;
    return this.deps._codingContextBySession?.get(sessionKey) ?? null;
  }

  /**
   * Shared helper used by both the recall path and the write path (rule 42).
   *
   * Given a base namespace computed from the principal, returns the overlaid
   * coding namespace when the session has a coding context AND
   * `codingMode.projectScope` is true AND `namespacesEnabled` is true.
   * Otherwise returns `baseNamespace` unchanged — CLAUDE.md #30 escape hatch.
   *
   * Principal isolation (CLAUDE.md rule 42): the overlay is COMBINED with
   * the principal-derived `baseNamespace` rather than replacing it, so two
   * principals working in the same repository do not share memories through
   * a common `project-*` namespace.
   *
   * Namespaces-disabled gate: when `namespacesEnabled` is false, the
   * storage router maps every namespace to the same `memoryDir`. Returning
   * `project-*` in that mode would create apparent route separation with
   * no actual storage isolation — a false-isolation trap. In that mode we
   * return `baseNamespace` unchanged so coding mode degrades to the existing
   * unscoped behavior.
   *
   * @internal
   */
  applyCodingNamespaceOverlay(sessionKey: string | undefined, baseNamespace: string): string {
    if (!resolveNamespaceCapabilities(this.deps.config).namespaces) return baseNamespace;
    const codingContext = this.deps.getCodingContextForSession(sessionKey);
    const overlay = resolveCodingNamespaceOverlay(codingContext, this.deps.config.codingMode, this.deps.config.defaultNamespace);
    if (!overlay) return baseNamespace;
    return combineNamespaces(baseNamespace, overlay.namespace);
  }

  /**
   * Register a peer ID for a session so recall can inject the peer's
   * profile into context (issue #679 PR 3/5). Pass `null` to clear.
   *
   * Connectors and the `before_prompt_build` hook call this when the
   * session's counter-party is known. The ID is validated against
   * `PEER_ID_PATTERN` before storing.
   *
   * Fail-closed (Codex P1 review): an invalid peerId clears any
   * previously registered mapping for the session rather than silently
   * keeping stale data. This prevents a malformed metadata update from
   * mixing one peer's profile context into another session.
   *
   * Defensive init (Cursor review + rule 16): `Object.create(
   * Orchestrator.prototype)` stubs in legacy tests skip class-field
   * initializers, so `_peerIdBySession` may be undefined. Mirror the
   * same guard used by `setCodingContextForSession`.
   */
  setPeerIdForSession(sessionKey: string, peerId: string | null): void {
    if (typeof sessionKey !== "string" || sessionKey.length === 0) return;
    // Defensive init — mirrors setCodingContextForSession (rule 16);
    // runs on the orchestrator via deps (PR #1802 review).
    this.deps.ensureSessionBindingMaps();
    if (peerId === null) {
      this.deps._peerIdBySession.delete(sessionKey);
      return;
    }
    // Basic pattern guard — full validation lives in peers/storage.ts.
    // Invalid input is fail-closed: clear the existing mapping so stale
    // peer context can't bleed in after a bad metadata update (Codex P1).
    if (
      typeof peerId !== "string" ||
      peerId.length === 0 ||
      peerId.length > 64 ||
      !/^[A-Za-z0-9]+(?:[._-][A-Za-z0-9]+)*$/.test(peerId)
    ) {
      log.warn(`setPeerIdForSession: invalid peerId — clearing session mapping`);
      this.deps._peerIdBySession.delete(sessionKey);
      return;
    }
    this.deps._peerIdBySession.set(sessionKey, peerId);
  }

  /**
   * Return the peer ID registered for a session, or `null` when none
   * is set. Used by `recallInternal` to inject the peer profile section.
   * Defensive `_peerIdBySession` lookup — legacy orchestrator-flush tests
   * use `Object.create(Orchestrator.prototype)` which skips class-field
   * initializers, so the Map may be undefined on stubs.
   */
  getPeerIdForSession(sessionKey: string | undefined): string | null {
    if (typeof sessionKey !== "string" || sessionKey.length === 0) return null;
    return this.deps._peerIdBySession?.get(sessionKey) ?? null;
  }

  async runDeepSleepGovernanceNow(options?: {
    dryRun?: boolean;
    storage?: StorageManager;
  }): Promise<{ scannedMemories: number; appliedActionCount: number; notes?: string }> {
    const targetStorage = options?.storage ?? this.deps.storage;
    const { runMemoryGovernance } = await import("../maintenance/memory-governance.js");
    const { summarizeGovernanceResultForDreams } = await import("../maintenance/dreams-ledger.js");
    const govResult = await runMemoryGovernance({
      memoryDir: targetStorage.dir,
      mode: options?.dryRun === true ? "shadow" : "apply",
    });
    if (options?.dryRun !== true) {
      try {
        await this.deps.entitySynthesisCoordinator.processQueue(
          this.deps.storageDirNamespace(targetStorage.dir),
          5,
        );
      } catch (error) {
        log.debug(`deep-sleep governance: entity synthesis refresh failed after apply: ${error}`);
      }
    }
    return summarizeGovernanceResultForDreams(govResult, options?.dryRun === true);
  }

  async generateDaySummary(
    memories: string | MemoryFile[],
  ): Promise<DaySummaryResult | null> {
    if (this.deps.initPromise) {
      let initGateTimeoutHandle: ReturnType<typeof setTimeout> | undefined;
      try {
        await Promise.race([
          this.deps.initPromise.catch(() => undefined),
          new Promise((resolve) => {
            initGateTimeoutHandle = setTimeout(
              resolve,
              this.deps.config.initGateTimeoutMs,
            );
          }),
        ]);
      } finally {
        if (initGateTimeoutHandle) clearTimeout(initGateTimeoutHandle);
      }
    }
    return this.deps.extraction.generateDaySummary(memories);
  }

  async flushSession(
    sessionKey: string,
    options: SessionFlushOptions,
  ): Promise<void> {
    // Force any pending debounced buffer save to land durably BEFORE we read
    // and (via clearBufferAfterExtraction below) clear turns (issue #1909, PR
    // #2016). In steady-state buffering a `keep_buffering` turn only SCHEDULES a
    // trailing-edge save (see SmartBuffer.scheduleSave), so the newest turns
    // live only in memory behind an unref'd timer. This lifecycle drain
    // (before_reset / session_end / explicit flush) queues extraction with
    // clearBufferAfterExtraction; if that extraction fails or times out and the
    // host then exits, the debounce timer never fires and those turns are lost.
    // Flushing first makes the in-memory turns durable, so a failed or aborted
    // extraction leaves them on disk for re-extraction on next startup.
    // Durability-preserving AND fail-closed: pass throwOnFailure so a failed
    // durable save stops this lifecycle drain BEFORE any extraction runs
    // flushPendingSave retains pending state and re-arms a retry on failure.
    if (typeof this.deps.buffer.flushPendingSave === "function") {
      await awaitSessionFlushPhase(
        () => this.deps.buffer.flushPendingSave!({ throwOnFailure: true }),
        options,
      );
    } else {
      throwIfAborted(
        options.abortSignal,
        options.reason === "access_force_flush" ? "extraction force-flush aborted" : "session flush aborted",
      );
      if (typeof options.extractionDeadlineMs === "number" && Date.now() >= options.extractionDeadlineMs) {
        throw new ExtractionDeadlineError("before_buffer_flush");
      }
    }
    const explicitBufferKey =
      typeof options.bufferKey === "string" && options.bufferKey.length > 0
        ? options.bufferKey
        : null;
    const discoveredBufferKeys =
      explicitBufferKey ||
      typeof sessionKey !== "string" ||
      sessionKey.length === 0 ||
      typeof this.deps.buffer.findBufferKeysForSession !== "function"
        ? []
        : await awaitSessionFlushPhase(
            () => this.deps.buffer.findBufferKeysForSession!(sessionKey),
            options,
          );
    const bufferKeys = explicitBufferKey
      ? [explicitBufferKey]
      : discoveredBufferKeys.length > 0
        ? discoveredBufferKeys
        : typeof sessionKey === "string" && sessionKey.length > 0
          ? [sessionKey]
          : ["default"];
    const namespacesEnabled =
      this.deps.config === undefined ||
      resolveNamespaceCapabilities(this.deps.config).namespaces === true;
    const scopedRequest =
      typeof options.writeNamespaceOverride === "string" ||
      typeof options.principalOverride === "string";
    const ownershipEnforced = namespacesEnabled && scopedRequest;
    const ownerPrincipal =
      typeof options.principalOverride === "string" && options.principalOverride.trim().length > 0
        ? options.principalOverride.trim()
        : undefined;
    const resolvedSessionPrincipal =
      ownershipEnforced && ownerPrincipal !== undefined && this.deps.config
        ? resolvePrincipal(sessionKey, this.deps.config)
        : undefined;
    const opaqueScopedSession =
      ownershipEnforced &&
      ownerPrincipal !== undefined &&
      (resolvedSessionPrincipal === undefined || resolvedSessionPrincipal === "default");
    // #3251: the flush's effective write namespace. An explicit override pins
    // it; otherwise it is the session principal's default store. Only PINNED
    // captures are namespace-compared — legacy unpinned turns keep their
    // prior semantics (any flush of their session drains them), while a
    // pinned capture is never drained under a different namespace.
    const flushNamespace =
      options.writeNamespaceOverride !== undefined
        ? options.writeNamespaceOverride
        : namespacesEnabled && this.deps.config
          ? defaultNamespaceForPrincipal(resolvePrincipal(sessionKey, this.deps.config), this.deps.config)
          : undefined;
    const belongsToSession = (turn: BufferTurn): boolean => {
      if (turn.sessionKey !== sessionKey) return false;
      if (
        namespacesEnabled &&
        turn.writeNamespaceOverride !== undefined &&
        turn.writeNamespaceOverride !== flushNamespace
      ) {
        return false;
      }
      // Existing profile pins require the same profile and project binding.
      // Accepted no-plan captures stay unprofiled within the matching namespace.
      const flushPlanIdentity = scopeProfilePlanIdentity(options.scopeProfileWritePlan);
      if (flushPlanIdentity !== "" && hasPinnedCaptureScope(turn)) {
        if (
          scopeProfilePlanIdentity(turn.scopeProfileWritePlan) !== flushPlanIdentity &&
          !(turn.acceptedCapture === true && turn.scopeProfileWritePlan === undefined)
        ) {
          return false;
        }
        // Compare bindings only when the ORIGINAL capture is context-bound —
        // an unbound capture must not be orphaned by a project attached later.
        if (
          options.codingContext &&
          turn.codingContext &&
          (turn.codingContext.projectId !== options.codingContext.projectId ||
            turn.codingContext.rootPath !== options.codingContext.rootPath ||
            turn.codingContext.branch !== options.codingContext.branch ||
            turn.codingContext.defaultBranch !== options.codingContext.defaultBranch)
        ) {
          return false;
        }
      }
      if (!ownershipEnforced || ownerPrincipal === undefined) return true;
      if (turn.sessionOwnerPrincipal === ownerPrincipal) return true;
      return (
        turn.sessionOwnerPrincipal === undefined &&
        this.deps.config !== undefined &&
        resolvePrincipal(turn.sessionKey, this.deps.config) === ownerPrincipal
      );
    };
    if (
      opaqueScopedSession &&
      bufferKeys.some((bufferKey) =>
        this.deps.buffer
          .getTurns(bufferKey)
          .some((turn) => turn.sessionKey === sessionKey && turn.sessionOwnerPrincipal === undefined),
      )
    ) {
      throw new SessionOwnershipError(
        `session ${sessionKey} has buffered turns without trusted ownership`,
      );
    }
    for (const bufferKey of bufferKeys) {
      const turns = this.deps.buffer.getTurns(bufferKey);
      // #3251: EVERY flush filters — unqualified lifecycle drains must not
      // clear another namespace's pinned capture; single-store mode no-ops
      // the filter (namespacesEnabled gate inside belongsToSession).
      const turnsForSession = turns.filter(belongsToSession);
      if (turnsForSession.length === 0) continue;
      const scopeGroups = groupTurnsByExtractionScope(turnsForSession);
      // Filtered or grouped slices need identity clearing rather than prefix clearing.
      const needsIdentityClear =
        turnsForSession.length < turns.length || scopeGroups.length > 1;
      const namespacesOn = this.deps.config
        ? resolveNamespaceCapabilities(this.deps.config).namespaces === true
        : true;
      for (const group of scopeGroups) {
        const groupPinned =
          group.writeNamespaceOverride !== undefined ||
          group.principalOverride !== undefined ||
          group.scopeProfileWritePlan !== undefined;
        // Preserve groups captured under another profile or project binding;
        // the binding compares only when the ORIGINAL group is context-bound.
        if (
          group.scopeProfileWritePlan &&
          options.scopeProfileWritePlan &&
          (scopeProfilePlanIdentity(group.scopeProfileWritePlan) !==
            scopeProfilePlanIdentity(options.scopeProfileWritePlan) ||
            (options.codingContext &&
              group.codingContext &&
              (group.codingContext.projectId !== options.codingContext.projectId ||
                group.codingContext.rootPath !== options.codingContext.rootPath ||
                group.codingContext.branch !== options.codingContext.branch ||
                group.codingContext.defaultBranch !== options.codingContext.defaultBranch)))
        ) {
          continue;
        }
        // Force-flush must reject preserved work before retained-turn cleanup can run.
        if (
          groupPinned &&
          !namespacesOn &&
          group.writeNamespaceOverride !== undefined &&
          group.writeNamespaceOverride !== this.deps.config?.defaultNamespace
        ) {
          if (options.failOnExtractionFailure === true) {
            throw new Error(
              `accepted capture preserved: pinned_namespace_unavailable (${group.writeNamespaceOverride})`,
            );
          }
          log.warn(
            `flushSession: pinned namespace ${group.writeNamespaceOverride} unavailable while namespaces are disabled; capture stays pending`,
          );
          continue;
        }
        const { promise, resolve, reject } = Promise.withResolvers<void>();
        void this.deps.queueBufferedExtraction(group.turns, "trigger_mode", {
          bufferKey,
          clearBufferAfterExtraction: true,
          skipDedupeCheck: true,
          skipCharThreshold: true,
          skipUserTurnThreshold: true,
          failOnExtractionFailure: options.failOnExtractionFailure === true,
          preemptRunning:
            options.reason === "access_force_flush" && options.failOnExtractionFailure === true,
          forceExtractionAttempt: true,
          abortSignal: options.abortSignal,
          extractionDeadlineMs: options.extractionDeadlineMs,
          writeNamespaceOverride: group.writeNamespaceOverride ?? options.writeNamespaceOverride,
          principalOverride: group.principalOverride ?? options.principalOverride,
          scopeProfileWritePlan: group.turns.some((turn) => turn.acceptedCapture === true)
            ? group.scopeProfileWritePlan ?? null
            : group.scopeProfileWritePlan ?? options.scopeProfileWritePlan,
          clearMatchingTurns: options.clearMatchingTurns === true || scopedRequest || groupPinned || needsIdentityClear,
          onDurableCommit: options.onCommitted,
          onTaskSettled: (error) => (error ? reject(error) : resolve()),
        }).catch(reject);
        await promise;
      }
      if (options.reason === "session_end" && this.deps.config.sessionExperience?.enabled === true) {
        await this.extractSessionEndExperience(turnsForSession, sessionKey, options);
      }
    }
  }

  /**
   * Session-end experience extraction (issue #2979): derive at most one
   * Situation/Approach/Reflect episode from the drained session's turns.
   * Best-effort by contract — a failure here must never fail the flush
   * (the fact extraction already committed). Honors the shared abort signal
   * and flush deadline; the write itself is gated, deduped per session, and
   * lands as `pending_review` inside `runSessionExperienceExtraction`.
   */
  private async extractSessionEndExperience(
    turns: BufferTurn[],
    sessionKey: string,
    options: SessionFlushOptions,
  ): Promise<void> {
    try {
      const explicitNamespace =
        typeof options.writeNamespaceOverride === "string" && options.writeNamespaceOverride.trim().length > 0
          ? options.writeNamespaceOverride.trim()
          : undefined;
      // Same precedence as the extraction write path: explicit override →
      // scope-profile plan → principal + coding overlay.
      const namespace =
        explicitNamespace ??
        options.scopeProfileWritePlan?.writeNamespace ??
        this.deps.applyCodingNamespaceOverlay(
          sessionKey,
          defaultNamespaceForPrincipal(this.deps.resolvePrincipal(sessionKey), this.deps.config),
        );
      const storage = await this.deps.orchestratorSelf.getStorageForNamespace(namespace);
      const result = await runSessionExperienceExtraction({
        turns,
        sessionKey,
        config: this.deps.config,
        storage,
        abortSignal: options.abortSignal,
        deadlineMs: options.extractionDeadlineMs,
      });
      if (result.written) {
        log.info(`session-experience: recorded ${result.episode.outcomeKind} episode for session end`);
      } else {
        log.debug(`session-experience skipped: ${result.skippedReason}`);
      }
    } catch (error) {
      log.warn(`session-experience extraction failed (non-fatal): ${error}`);
    }
  }

  /** Lazily construct the CorrectionService for passive capture. Stateless
   *  across requests (per #1580 design); cached for the orchestrator's life. */
  passiveCorrectionService(): CorrectionService {
    if (this.deps._passiveCorrectionService) return this.deps._passiveCorrectionService;
    this.deps._passiveCorrectionService = createCorrectionService({
      orchestrator: this.deps.orchestratorSelf,
      // Session-scoped write ACL (review: "passive capture bypasses write
      // ACL"). A correction detected in session S plans only against S readable
      // namespaces and applies only to writable ones (rule 42) — passive
      // capture never becomes a cross-tenant mutation vector. Mirrors the
      // access-service createCorrectionService wiring rather than bypassing it.
      resolveAuthorizedNamespace: async (req) => {
        const principal = req.principal || resolvePrincipal(req.sessionKey, this.deps.config);
        const ns = req.namespace ?? defaultNamespaceForPrincipal(principal, this.deps.config);
        if (!canWriteNamespace(principal, ns, this.deps.config)) {
          throw new Error(
            `passive correction: namespace "${ns}" is not writable for principal ${principal ?? "(none)"}`,
          );
        }
        return ns;
      },
      resolveReadableNamespaces: (req) => {
        const principal = req.principal || resolvePrincipal(req.sessionKey, this.deps.config);
        return recallNamespacesForPrincipal(principal, this.deps.config);
      },
      canWriteNamespace: async (req) => {
        const principal = req.principal || resolvePrincipal(req.sessionKey, this.deps.config);
        return canWriteNamespace(principal, req.namespace, this.deps.config);
      },
    });
    return this.deps._passiveCorrectionService;
  }
}

import { log } from "../logger.js";

const pendingWritesByOwner = new WeakMap<object, Set<Promise<void>>>();

export function trackRecallWrite(owner: object, promise: Promise<void>, label: string): void {
  const observed = promise.catch((err) => {
    log.debug(`${label} failed: ${err}`);
  });
  const pendingWrites = pendingWritesByOwner.get(owner) ?? new Set<Promise<void>>();
  pendingWritesByOwner.set(owner, pendingWrites);
  pendingWrites.add(observed);
  void observed.finally(() => {
    pendingWrites.delete(observed);
    if (pendingWrites.size === 0) pendingWritesByOwner.delete(owner);
  });
}

export async function drainRecallWrites(owner: object): Promise<void> {
  while (true) {
    const pendingWrites = pendingWritesByOwner.get(owner);
    if (!pendingWrites || pendingWrites.size === 0) return;
    await Promise.all(pendingWrites);
  }
}

import { abortError, throwIfAborted } from "../abort-error.js";

export interface AtomicCaptureState<TSnapshot> {
  read(): TSnapshot | null;
  clear(): void;
  restore(snapshot: TSnapshot | null): void;
}

export interface AtomicCaptureResult<TResult, TSnapshot> {
  result: TResult;
  snapshot: TSnapshot | null;
  recallStartedAt: number;
}

/** Per-owner abortable FIFO for operations that publish through one mutable slot. */
export class XrayCaptureQueue {
  private tail: Promise<void> = Promise.resolve();

  async run<TResult, TSnapshot>(
    operation: () => Promise<TResult>,
    state: AtomicCaptureState<TSnapshot>,
    signal?: AbortSignal,
  ): Promise<AtomicCaptureResult<TResult, TSnapshot>> {
    throwIfAborted(signal, "x-ray capture aborted before queueing");
    const previous = this.tail;
    let release: () => void = () => {};
    this.tail = new Promise<void>((resolve) => {
      release = resolve;
    });

    try {
      await this.waitForTurn(previous, signal);
    } catch (error) {
      // Keep this abandoned node as a barrier until its predecessor settles,
      // so later callers cannot overtake the still-active operation.
      void previous.then(release, release);
      throw error;
    }

    let previousSnapshot: TSnapshot | null = null;
    let didReadPreviousSnapshot = false;
    try {
      previousSnapshot = state.read();
      didReadPreviousSnapshot = true;
      const recallStartedAt = Date.now();
      state.clear();
      const result = await operation();
      const snapshot = state.read();
      if (!snapshot) state.restore(previousSnapshot);
      return { result, snapshot, recallStartedAt };
    } catch (error) {
      if (didReadPreviousSnapshot) state.restore(previousSnapshot);
      throw error;
    } finally {
      release();
    }
  }

  private async waitForTurn(previous: Promise<void>, signal?: AbortSignal): Promise<void> {
    throwIfAborted(signal, "x-ray capture aborted while queued");
    if (!signal) {
      await previous;
      return;
    }

    let onAbort: (() => void) | undefined;
    const aborted = new Promise<never>((_resolve, reject) => {
      onAbort = () => reject(abortError("x-ray capture aborted while queued"));
      signal.addEventListener("abort", onAbort, { once: true });
    });
    try {
      await Promise.race([previous, aborted]);
      throwIfAborted(signal, "x-ray capture aborted while queued");
    } finally {
      if (onAbort) signal.removeEventListener("abort", onAbort);
    }
  }
}

import path from "node:path";
import { log } from "../logger.js";
import { resolveNamespaceCapabilities } from "../capabilities.js";
import { namespaceIdentityFromToken } from "../namespaces/identity.js";
import type { PluginConfig } from "../types.js";

/**
 * Compute the semantic-dedup path scope for a target storage (issue #1526 seam:
 * extracted verbatim from Orchestrator.semanticDedupScopeFor). Reads only the
 * plugin config + target storage dir; no `this` state.
 */
export function computeSemanticDedupScope(
  targetStorage: { readonly dir: string },
  config: PluginConfig,
): {
  pathPrefix?: string;
  pathExcludePrefixes?: readonly string[];
} {
  if (!resolveNamespaceCapabilities(config).namespaces) return {};
  const memoryDir = path.resolve(config.memoryDir);
  const storageDir = path.resolve(targetStorage.dir);
  if (storageDir === memoryDir) {
    // Default namespace at legacy root. Include everything that isn't
    // under `namespaces/*` (those belong to other namespaces).
    return { pathExcludePrefixes: ["namespaces/"] };
  }
  let rel = path.relative(memoryDir, storageDir);
  if (!rel || rel.startsWith("..")) {
    // Round 12 fix (PR #399): when targetStorage.dir is outside memoryDir
    // (custom namespace routing), toMemoryRelativePath() stores the absolute
    // file path in the index rather than a memoryDir-relative path. Return the
    // absolute storageDir as the pathPrefix so the search() filter still scopes
    // the lookup to the correct tenant's files. Previously this returned {} (no
    // scoping), which let high-similarity hits from other namespaces' absolute-
    // path entries suppress writes in the target namespace — a cross-tenant
    // dedup suppression path.
    log.debug(
      `semantic dedup: target storage dir ${storageDir} is outside memoryDir ${memoryDir}; scoping lookup to absolute path prefix`,
    );
    const absPrefix = storageDir.replace(/\\/g, "/");
    return { pathPrefix: absPrefix.endsWith("/") ? absPrefix : `${absPrefix}/` };
  }
  rel = rel.replace(/\\/g, "/");
  if (!rel.endsWith("/")) rel = `${rel}/`;
  return { pathPrefix: rel };
}

/**
 * Resolve the namespace identity implied by a QMD collection prefix (issue
 * #1526 seam: extracted verbatim from Orchestrator.qmdCollectionNamespaceFromPrefix).
 * Reads only the plugin config; no `this` state.
 */
export function qmdCollectionNamespaceFromPrefix(
  collectionPrefix: string,
  config: PluginConfig,
): string | null {
  const baseCollection = config.qmdCollection;
  if (collectionPrefix === baseCollection) return config.defaultNamespace;
  const namespaceSuffix = collectionPrefix.startsWith(`${baseCollection}--`)
    ? collectionPrefix.slice(baseCollection.length + 2)
    : "";
  if (!namespaceSuffix) return null;

  const decoded = namespaceIdentityFromToken(namespaceSuffix);
  if (decoded !== null) return decoded || config.defaultNamespace;
  if (namespaceSuffix.startsWith("ns--")) {
    const legacyNamespace = namespaceSuffix.slice("ns--".length).trim();
    return legacyNamespace || null;
  }
  return null;
}

import path from "node:path";
import type { QmdSearchResult } from "../types.js";
import { isExternalWikiCollectionName } from "../external-wiki-guard.js";
export { isExternalWikiCollectionName } from "../external-wiki-guard.js";
import { ALL_CATEGORY_DIRS } from "../utils/category-dir.js";
import {
  isActivityDigestPath,
  isArtifactMemoryPath,
  isLocationDayPath,
  isMeetingRecordPath,
} from "./orchestrator-helpers.js";
import { isJournalDayPath } from "../activity/journal.js";
import { DIRECTORY_SIDECAR_BASENAME } from "../directory-sidecars.js";
import { OKF_RESERVED_BASENAMES } from "../okf/type-mapping.js";


export interface GenericRecallPathPolicy {
  readonly memoryDir?: string;
  readonly qmdCollection?: string;
  readonly qmdColdCollection?: string;
  /**
   * The collection THIS request named, when it named one. A caller may select
   * a custom collection whose name is also a memory category, which the
   * configured names alone cannot disambiguate.
   */
  readonly requestedCollection?: string;
}

type GenericRecallPathSource = "filesystem" | "qmd";

const CATEGORY_MEMORY_ROOTS: Record<string, true> = Object.fromEntries(
  ALL_CATEGORY_DIRS.map((directory) => [directory, true]),
);
const RESERVED_ARCHIVE_ROOTS: Record<string, true> = { archive: true, namespaces: true };

function isQmdCollectionPrefix(
  prefix: string,
  collection: string | undefined,
  source: GenericRecallPathSource,
): boolean {
  if (typeof collection !== "string" || collection.length === 0) return false;
  if (prefix.startsWith(`${collection}--`)) return true;
  if (prefix !== collection) return false;
  if (source === "qmd") return true;
  return (
    !Object.hasOwn(CATEGORY_MEMORY_ROOTS, prefix) &&
    !Object.hasOwn(RESERVED_ARCHIVE_ROOTS, prefix)
  );
}

function normalizeQmdUriPath(relativePath: string, source: GenericRecallPathSource): string {
  if (source !== "qmd" || !relativePath.startsWith("qmd://")) return relativePath;
  try {
    const parsed = new URL(relativePath);
    if (parsed.protocol !== "qmd:" || !parsed.hostname) return relativePath;
    const collection = decodeURIComponent(parsed.hostname);
    const pathname = decodeURIComponent(parsed.pathname.replace(/^\/+/, ""));
    return pathname ? `${collection}/${pathname}` : collection;
  } catch {
    return relativePath;
  }
}

function stripQmdCollectionPrefix(
  relativePath: string,
  policy: GenericRecallPathPolicy,
  source: GenericRecallPathSource,
): string {
  const normalized = path.posix.normalize(normalizeQmdUriPath(relativePath, source).replace(/\\/g, "/"));
  const slashIndex = normalized.indexOf("/");
  if (slashIndex <= 0 || slashIndex >= normalized.length - 1) return normalized;

  const prefix = normalized.slice(0, slashIndex);
  const matchesHotCollection = isQmdCollectionPrefix(prefix, policy.qmdCollection, source);
  const matchesColdCollection = isQmdCollectionPrefix(prefix, policy.qmdColdCollection, source);
  return matchesHotCollection || matchesColdCollection
    ? normalized.slice(slashIndex + 1)
    : normalized;
}

export function isTopLevelArchivePath(
  filePath: string,
  policy: GenericRecallPathPolicy = {},
  source: GenericRecallPathSource = "filesystem",
): boolean {
  const isAbsolutePath = path.isAbsolute(filePath);
  const relative =
    policy.memoryDir && isAbsolutePath
      ? path.relative(policy.memoryDir, path.resolve(filePath))
      : filePath;
  const normalized = !isAbsolutePath
    ? stripQmdCollectionPrefix(relative, policy, source)
    : relative;
  return /^(?:archive|namespaces[\\/][^\\/]+[\\/]archive)(?:[\\/]|$)/i.test(normalized);
}

function isExternalWikiQmdPath(
  filePath: string,
  source: GenericRecallPathSource,
): boolean {
  if (source !== "qmd") return false;
  const normalized = normalizeQmdUriPath(filePath, source).replace(/\\/g, "/");
  const slashIndex = normalized.indexOf("/");
  const collection = slashIndex === -1 ? normalized : normalized.slice(0, slashIndex);
  return isExternalWikiCollectionName(collection);
}

/**
 * Paths an EXPLICIT ranked search must not return.
 *
 * Narrower than {@link isGenericRecallExcludedPath} on purpose. Recall
 * injection also drops archived memories because they are cold by definition,
 * but archive is explicitly reserved for "explicit read or search surfaces"
 * (docs/architecture/memory-lifecycle.md) — hiding it from `memory_search`
 * would remove the only way to find it. Everything else stays excluded: those
 * paths flow through their own dedicated surfaces, never a generic search.
 */
export function isSearchExcludedPath(
  filePath: string,
  policy: GenericRecallPathPolicy = {},
  source: GenericRecallPathSource = "filesystem",
): boolean {
  if (isExternalWikiQmdPath(filePath, source)) return true;
  // A QMD transport hands back collection-qualified paths
  // (`qmd://<collection>/activity/<date>.md`, or `<collection>/activity/…`),
  // and the collection is not always one this policy knows: a caller may name
  // a custom one, and global search spans every collection. The activity
  // predicate is ROOT-AWARE — it matches only the top-level
  // `activity/<date>.md` so a nested ordinary memory stays recallable — so an
  // un-stripped prefix reads as a nested path and the digest would be served.
  //
  // Both spellings are therefore tested. Widening is safe in this direction
  // and only here: a leading segment is dropped ONLY to re-test the dedicated
  // surface shapes, never to decide anything else, and a segment that names a
  // memory CATEGORY (`facts/proj/activity/…`) is never treated as a
  // collection, so ordinary nested memories stay searchable.
  for (const candidate of collectionSpellings(filePath, policy, source)) {
    if (
      isArtifactMemoryPath(candidate) ||
      isNamespacedActivityDigestPath(candidate, policy.memoryDir) ||
      isNamespacedLocationDayPath(candidate, policy.memoryDir) ||
      isNamespacedJournalDayPath(candidate, policy.memoryDir) ||
      isMeetingRecordPath(candidate) ||
      isCompoundingReportPath(candidate, policy.memoryDir)
    ) {
      return true;
    }
  }
  return false;
}

/**
 * Derived compounding reports sit at `<root>/compounding/` and
 * `namespaces/<namespace>/compounding/`. Generic recall must not return them:
 * a root report can quote another namespace, and injection already has a
 * filtered compounding section. A namespace literally named `compounding`,
 * and an ordinary memory nested under a category, stay searchable.
 */
function isCompoundingReportPath(candidate: string, memoryDir?: string): boolean {
  let relative = candidate.replace(/\\/g, "/");
  if (memoryDir && memoryDir.length > 0) {
    const absolute = path.resolve(memoryDir, candidate).replace(/\\/g, "/");
    const root = path.resolve(memoryDir).replace(/\\/g, "/");
    if (absolute !== root && !absolute.startsWith(`${root}/`)) return false;
    relative = absolute.slice(root.length);
    if (relative.startsWith("/")) relative = relative.slice(1);
  }
  if (relative.startsWith("../")) return false;
  if (relative.startsWith("namespaces/")) {
    const slash = relative.indexOf("/", "namespaces/".length);
    if (slash < 0) return false;
    relative = relative.slice(slash + 1);
  }
  return relative === "compounding" || relative.startsWith("compounding/");
}

/**
 * The activity check, applied against the NAMESPACE root a hit came from.
 *
 * `isActivityDigestPath` is root-aware — the digest must sit directly under
 * the root it is given — but a namespaced search rewrites hits to absolute
 * paths beneath `…/namespaces/<ns>/`, and only the global `memoryDir` is
 * available here. Measured against that root, a real digest at
 * `<memoryDir>/namespaces/team/activity/<date>.md` reads as nested and is
 * served. Re-measuring against the namespace's own root closes that.
 */
function isNamespacedActivityDigestPath(candidate: string, memoryDir?: string): boolean {
  if (isActivityDigestPath(candidate, memoryDir)) return true;
  if (memoryDir === undefined || memoryDir.length === 0) return false;
  const relative = path.relative(memoryDir, path.resolve(memoryDir, candidate));
  const namespaced = /^namespaces[\\/]([^\\/]+)[\\/](.*)$/.exec(relative);
  if (namespaced === null) return false;
  return isActivityDigestPath(namespaced[2] ?? "", memoryDir);
}

/**
 * The location day-file check, applied against the NAMESPACE root a hit came
 * from — same rationale as `isNamespacedActivityDigestPath`: a namespaced
 * search rewrites hits to absolute paths beneath `…/namespaces/<ns>/`, so the
 * root-aware predicate is re-measured against the namespace's own root.
 */
function isNamespacedLocationDayPath(candidate: string, memoryDir?: string): boolean {
  if (isLocationDayPath(candidate, memoryDir)) return true;
  if (memoryDir === undefined || memoryDir.length === 0) return false;
  const relative = path.relative(memoryDir, path.resolve(memoryDir, candidate));
  const namespaced = /^namespaces[\\/]([^\\/]+)[\\/](.*)$/.exec(relative);
  if (namespaced === null) return false;
  return isLocationDayPath(namespaced[2] ?? "", memoryDir);
}

function isNamespacedJournalDayPath(candidate: string, memoryDir?: string): boolean {
  if (isJournalDayPath(candidate, memoryDir)) return true;
  if (memoryDir === undefined || memoryDir.length === 0) return false;
  const relative = path.relative(memoryDir, path.resolve(memoryDir, candidate));
  const namespaced = /^namespaces[\\/]([^\\/]+)[\\/](.*)$/.exec(relative);
  if (namespaced === null) return false;
  return isJournalDayPath(namespaced[2] ?? "", memoryDir);
}

/** A path as given, plus its form with a leading COLLECTION segment removed. */
function collectionSpellings(
  filePath: string,
  policy: GenericRecallPathPolicy,
  source: GenericRecallPathSource,
): string[] {
  if (path.isAbsolute(filePath)) return [filePath];
  // A `qmd://<collection>/<path>` URI states its collection UNAMBIGUOUSLY in
  // the authority, so the leading segment of its normalized form is never a
  // memory category — strip it outright rather than guessing.
  if (source === "qmd" && filePath.startsWith("qmd://")) {
    const normalized = path.posix.normalize(normalizeQmdUriPath(filePath, source).replace(/\\/g, "/"));
    const slashIndex = normalized.indexOf("/");
    return slashIndex <= 0 || slashIndex >= normalized.length - 1
      ? [normalized]
      : [normalized, normalized.slice(slashIndex + 1)];
  }
  const normalized = path.posix.normalize(
    normalizeQmdUriPath(filePath, source).replace(/\\/g, "/"),
  );
  const stripped = stripQmdCollectionPrefix(filePath, policy, source);
  const spellings = [stripped];
  // If the AUTHORITATIVE strip already fired — the prefix matched a configured
  // collection — stop. Removing a second segment would take a real directory
  // with it: `memories/projects/activity/<date>.md` would become
  // `activity/<date>.md` and an ordinary nested memory would read as a
  // top-level digest, vanishing from search AND recall.
  if (stripped !== normalized) return spellings;
  const slashIndex = stripped.indexOf("/");
  if (slashIndex <= 0 || slashIndex >= stripped.length - 1) return spellings;
  const prefix = stripped.slice(0, slashIndex);
  // The CALLER's own collection is authoritative: a request for
  // `collection: "facts"` means that segment is the collection, whatever it is
  // also the name of. Otherwise a category-shaped prefix stays part of the
  // path, so an ordinary `facts/proj/activity/<date>.md` memory is searchable.
  const requested = policy.requestedCollection;
  if (
    prefix !== requested &&
    (Object.hasOwn(CATEGORY_MEMORY_ROOTS, prefix) || Object.hasOwn(RESERVED_ARCHIVE_ROOTS, prefix))
  ) {
    return spellings;
  }
  spellings.push(stripped.slice(slashIndex + 1));
  return spellings;
}

export function isGenericRecallExcludedPath(
  filePath: string,
  policy: GenericRecallPathPolicy = {},
  source: GenericRecallPathSource = "filesystem",
): boolean {
  return (
    isSearchExcludedPath(filePath, policy, source) ||
    isTopLevelArchivePath(filePath, policy, source) ||
    OKF_RESERVED_BASENAMES[path.basename(filePath)] === true ||
    // Derived per-directory sidecars (#2977): recall-excluded like OKF index
    // files, still searchable. Basename-only, the same accepted tradeoff.
    path.basename(filePath) === DIRECTORY_SIDECAR_BASENAME
  );
}

export function filterRecallCandidates(
  candidates: QmdSearchResult[],
  options: {
    namespacesEnabled: boolean;
    recallNamespaces: string[];
    resolveNamespace: (path: string) => string;
    limit: number;
    pathPolicy?: GenericRecallPathPolicy;
    memoryRoot?: string;
  },
): QmdSearchResult[] {
  const pathPolicy =
    options.pathPolicy ??
    (options.memoryRoot === undefined ? undefined : { memoryDir: options.memoryRoot });
  const scopedByNamespace = options.namespacesEnabled
    ? candidates.filter((r) =>
        options.recallNamespaces.includes(r.namespace ?? options.resolveNamespace(r.path)),
      )
    : candidates;
  return scopedByNamespace
    .filter((r) => !isGenericRecallExcludedPath(r.path, pathPolicy, "qmd"))
    .slice(0, Math.max(0, options.limit));
}

