export class ModelRegistry {
  private registryPath: string;
  private data: ModelRegistryData;
  private readonly CACHE_TTL_DAYS = 7;

  constructor(memoryDir: string) {
    this.registryPath = join(memoryDir, ".registry", "model-capabilities.json");
    this.data = this.loadRegistry();
  }

  private loadRegistry(): ModelRegistryData {
    try {
      if (fs.existsSync(this.registryPath)) {
        const content = fs.readFileSync(this.registryPath, "utf-8");
        const data = JSON.parse(content) as ModelRegistryData;
        log.info(`ModelRegistry: loaded ${Object.keys(data.models).length} cached models`);
        return data;
      }
    } catch (err) {
      log.warn(`ModelRegistry: failed to load registry: ${err}`);
    }
    return { models: {}, version: 1 };
  }

  private saveRegistry(): void {
    try {
      // Created on first save, never at construction: building a registry
      // happens on every plugin registration, including read-only discovery
      // passes, and must not touch the operator's memory dir.
      const registryDir = dirname(this.registryPath);
      if (!fs.existsSync(registryDir)) fs.mkdirSync(registryDir, { recursive: true });
      fs.writeFileSync(this.registryPath, JSON.stringify(this.data, null, 2));
    } catch (err) {
      log.warn(`ModelRegistry: failed to save registry: ${err}`);
    }
  }

  private isCacheExpired(model: ModelCapabilities): boolean {
    const fetched = new Date(model.fetchedAt);
    const now = new Date();
    const daysDiff = (now.getTime() - fetched.getTime()) / (1000 * 60 * 60 * 24);
    return daysDiff > this.CACHE_TTL_DAYS;
  }

  private normalizeModelId(modelId: string): string {
    // Remove common suffixes and prefixes for matching
    return modelId
      .toLowerCase()
      .replace(/@\d+bit$/, "") // Remove @4bit, @8bit
      .replace(/-mlx$/, "")
      .replace(/-awq$/, "")
      .replace(/-gptq$/, "")
      .replace(/-gguf$/, "")
      .replace(/^mlx-community\//, "")
      .replace(/^models\//, "")
      .trim();
  }

  /**
   * Get capabilities for a model, using cache if available
   */
  getCapabilities(modelId: string): ModelCapabilities {
    const normalizedId = this.normalizeModelId(modelId);

    // Check cache first
    if (this.data.models[normalizedId]) {
      const cached = this.data.models[normalizedId];
      if (!this.isCacheExpired(cached)) {
        log.info(`ModelRegistry: using cached capabilities for ${modelId}`);
        return cached;
      }
      log.info(`ModelRegistry: cache expired for ${modelId}, will refresh`);
    }

    // Check known models
    for (const [knownId, capabilities] of Object.entries(KNOWN_MODELS)) {
      if (normalizedId.includes(knownId)) {
        log.info(`ModelRegistry: using known capabilities for ${modelId}`);
        const caps: ModelCapabilities = {
          ...DEFAULT_CAPABILITIES,
          ...capabilities,
          modelId: normalizedId,
          source: "default",
          fetchedAt: new Date().toISOString(),
        };
        this.data.models[normalizedId] = caps;
        this.saveRegistry();
        return caps;
      }
    }

    // Return defaults
    log.info(`ModelRegistry: using default capabilities for ${modelId}`);
    return {
      ...DEFAULT_CAPABILITIES,
      modelId: normalizedId,
    };
  }

  /**
   * Store capabilities for a model
   */
  setCapabilities(modelId: string, capabilities: Omit<ModelCapabilities, "modelId" | "fetchedAt">): void {
    const normalizedId = this.normalizeModelId(modelId);
    const caps: ModelCapabilities = {
      ...capabilities,
      modelId: normalizedId,
      fetchedAt: new Date().toISOString(),
    };
    this.data.models[normalizedId] = caps;
    this.saveRegistry();
    log.info(`ModelRegistry: stored capabilities for ${modelId}`);
  }

  /**
   * Calculate optimal input/output sizes for a model
   * @param maxContextOverride - Optional override for max context (e.g., if LLM server defaults to smaller window)
   */
  calculateContextSizes(modelId: string, maxContextOverride?: number): {
    maxInputChars: number;
    maxOutputTokens: number;
    description: string;
  } {
    const caps = this.getCapabilities(modelId);

    // Use override if provided (e.g., user knows their LLM server limits), otherwise use detected caps
    const sanitizedOverride =
      typeof maxContextOverride === "number" &&
      Number.isFinite(maxContextOverride) &&
      Number.isInteger(maxContextOverride) &&
      maxContextOverride >= 1024
        ? maxContextOverride
        : undefined;
    const effectiveContextWindow = sanitizedOverride ?? Math.max(1024, Math.floor(caps.contextWindow));

    // Guardrails: never allow output budget to exceed the model/server context window.
    // If we do, input budget goes negative and we end up generating huge, invalid prompts.
    const overheadTokens = Math.min(1000, Math.floor(effectiveContextWindow / 10)); // <=10% overhead, max 1k
    const minInputTokens = Math.min(512, Math.floor(effectiveContextWindow / 4)); // keep some room even on small contexts
    const minOutputTokens = Math.min(256, Math.max(1, effectiveContextWindow - overheadTokens - minInputTokens));

    // Base output budget: typical output, but scaled down for small contexts.
    let outputTokens = caps.typicalOutputTokens;

    // For very large contexts, default to ~12.5% output (capped), which tends to be plenty for JSON extraction.
    if (effectiveContextWindow > 65536) {
      outputTokens = Math.min(Math.floor(effectiveContextWindow / 8), 16384);
    }

    // Never let output exceed 25% of context.
    outputTokens = Math.min(outputTokens, Math.floor(effectiveContextWindow / 4));

    // Clamp output so we always have positive input headroom.
    const maxOutputTokens = Math.max(1, effectiveContextWindow - overheadTokens - minInputTokens);
    outputTokens = Math.min(maxOutputTokens, Math.max(minOutputTokens, outputTokens));

    const availableForInput = Math.max(
      0,
      effectiveContextWindow - outputTokens - overheadTokens,
    );

    // Convert to characters (rough estimate: 1 token ≈ 4 chars)
    const maxInputChars = Math.max(0, Math.floor(availableForInput * 3.5)); // Conservative: 3.5 chars/token

    const source = sanitizedOverride ? "user override" : caps.source;
    return {
      maxInputChars,
      maxOutputTokens: outputTokens,
      description: `${caps.modelId}: ${effectiveContextWindow.toLocaleString()} context (${source}), using ${maxInputChars.toLocaleString()} chars input / ${outputTokens} tokens output`,
    };
  }

  /**
   * Fetch capabilities from Hugging Face (if available)
   * Returns true if successful
   */
  async fetchFromHuggingFace(modelId: string): Promise<boolean> {
    // This would be implemented to fetch from HF Hub API
    // For now, we rely on the known models and manual updates
    log.info(`ModelRegistry: fetchFromHuggingFace not yet implemented for ${modelId}`);
    return false;
  }

  /**
   * List all cached models
   */
  listCached(): string[] {
    return Object.keys(this.data.models);
  }

  /**
   * Clear expired cache entries
   */
  cleanExpired(): number {
    const before = Object.keys(this.data.models).length;
    this.data.models = Object.fromEntries(
      Object.entries(this.data.models).filter(([_, caps]) => !this.isCacheExpired(caps))
    );
    const after = Object.keys(this.data.models).length;
    const removed = before - after;
    if (removed > 0) {
      this.saveRegistry();
      log.info(`ModelRegistry: cleaned ${removed} expired entries`);
    }
    return removed;
  }
}

/**
 * Trigger-drain helpers (extraction trigger stall fix).
 *
 * A session whose buffered window outgrows the extraction model's context
 * never drains: the trigger fires `extract_batch` on every observe, the
 * oversized request fails, nothing is cleared, and the window only grows.
 * These helpers split such a window into budget-fitting chunks and classify
 * each extraction run so the caller can drain successes, defer on breaker/
 * backoff retention, and drop repeatedly failing chunks.
 */

import type { ExtractionRunResult } from "./orchestration/extraction-run.js";

/**
 * Split `turns` into chunks whose summed content length stays within
 * `maxChars`. Chunks keep turn order and never split a turn; a single turn
 * longer than the budget becomes its own chunk (the extraction prompt still
 * clamps per-turn content). A non-positive or non-finite budget, or an empty
 * window, yields at most one chunk (no chunking).
 */
export function chunkExtractionWindow<T extends { content: string }>(
  turns: readonly T[],
  maxChars: number,
): T[][] {
  if (turns.length === 0) return [];
  const budget =
    Number.isFinite(maxChars) && maxChars > 0 ? Math.floor(maxChars) : Number.POSITIVE_INFINITY;
  const chunks: T[][] = [];
  let current: T[] = [];
  let currentChars = 0;
  for (const turn of turns) {
    const turnChars = turn.content.length;
    if (current.length > 0 && currentChars + turnChars > budget) {
      chunks.push(current);
      current = [];
      currentChars = 0;
    }
    current.push(turn);
    currentChars += turnChars;
  }
  if (current.length > 0) chunks.push(current);
  return chunks;
}

export type DrainVerdict = "drained" | "deferred" | "failed";

/**
 * Run results that deliberately RETAIN the buffer (provider breaker open,
 * per-fingerprint backoff, a scope policy refusal) are deferrals, not chunk
 * failures — counting them would eventually drop good content that never got
 * its attempt.
 */
const DRAIN_DEFERRAL_REASONS = {
  provider_circuit_open: true,
  extraction_backoff: true,
  scope_profile_no_writable_layer: true,
};

export function classifyDrainResult(result: ExtractionRunResult): DrainVerdict {
  if (result.status !== "skipped") return "drained";
  if (result.reason !== undefined && result.reason in DRAIN_DEFERRAL_REASONS) return "deferred";
  // A run that kept its window for retry did NOT consume the content: it is a
  // chunk failure, never a drain — even when the window was retained.
  if (result.retainedBuffer === true) return "failed";
  return "drained";
}

/**
 * Combine chunk results into the single `ExtractionRunResult` the queue
 * contract settles with: counts sum, any completed chunk completes the drain,
 * and the last non-completed reason wins.
 */
export function mergeDrainResults(
  previous: ExtractionRunResult | null,
  next: ExtractionRunResult,
): ExtractionRunResult {
  if (previous === null) return next;
  const completed = previous.status === "completed" || next.status === "completed";
  const merged: ExtractionRunResult = {
    status: completed ? "completed" : "skipped",
    persistedCount: previous.persistedCount + next.persistedCount,
    durableOutputCount: previous.durableOutputCount + next.durableOutputCount,
  };
  if (!completed) merged.reason = next.reason ?? previous.reason;
  if (previous.postPersistMetadataFailed === true || next.postPersistMetadataFailed === true) {
    merged.postPersistMetadataFailed = true;
  }
  return merged;
}

/** The slice of ModelRegistry the drain budget needs. */
export interface WindowBudgetRegistry {
  calculateContextSizes(modelId: string, maxContextOverride?: number): { maxInputChars: number };
}

/**
 * Character budget for one extraction request. The learned local-model window
 * only describes the extractor when the local LLM does the extracting; with a
 * gateway extractor, a disabled local LLM, or no registry (legacy hosts, test
 * doubles) there is no budget and the window runs in one request as before.
 */
export function extractionWindowBudgetChars(input: {
  registry: WindowBudgetRegistry | undefined;
  localExtractionActive: boolean;
  model: string;
  maxContext: number | undefined;
}): number {
  if (!input.registry || !input.localExtractionActive) return Number.POSITIVE_INFINITY;
  return input.registry.calculateContextSizes(input.model, input.maxContext).maxInputChars;
}

import { clamp01 } from "./lifecycle.js";

export interface QueryExpansionOptions {
  maxQueries: number;
  minTokenLen: number;
}

export interface RuntimeRetrievalPolicy {
  recencyWeight?: number;
}

const DEFAULT_STOPWORDS = new Set([
  "a",
  "an",
  "and",
  "are",
  "as",
  "at",
  "be",
  "but",
  "by",
  "for",
  "from",
  "has",
  "have",
  "i",
  "in",
  "is",
  "it",
  "of",
  "on",
  "or",
  "that",
  "the",
  "this",
  "to",
  "was",
  "were",
  "with",
]);

function tokenize(query: string, minTokenLen: number): string[] {
  return query
    .toLowerCase()
    .split(/[^a-z0-9]+/g)
    .map((t) => t.trim())
    .filter((t) => t.length >= minTokenLen)
    .filter((t) => !DEFAULT_STOPWORDS.has(t));
}

export function applyRuntimeRetrievalPolicy(
  base: { recencyWeight: number },
  runtime: RuntimeRetrievalPolicy | null,
): { recencyWeight: number } {
  const fromRuntime = runtime?.recencyWeight;
  if (typeof fromRuntime !== "number") {
    return { recencyWeight: clamp01(base.recencyWeight) };
  }
  return { recencyWeight: clamp01(fromRuntime) };
}

/**
 * Cheap, deterministic query expansion.
 * Produces additional queries biased toward the most salient tokens in the input.
 */
export function expandQuery(
  query: string,
  options: QueryExpansionOptions,
): string[] {
  const trimmed = query.trim();
  if (!trimmed) return [query];

  const maxQueries = Math.max(1, Math.min(20, options.maxQueries));
  const tokens = tokenize(trimmed, options.minTokenLen);

  // Keep deterministic ordering: first-seen tokens win.
  const seen = new Set<string>();
  const uniqTokens: string[] = [];
  for (const t of tokens) {
    if (seen.has(t)) continue;
    seen.add(t);
    uniqTokens.push(t);
  }

  const expansions: string[] = [query];
  if (uniqTokens.length === 0) return expansions;

  const top = uniqTokens.slice(0, 6);

  const candidates = [
    top.slice(0, 3).join(" "),
    top.slice(0, 2).join(" "),
    top[0],
    top[1],
    top[2],
  ].filter(Boolean) as string[];

  for (const c of candidates) {
    if (expansions.length >= maxQueries) break;
    if (c && !expansions.includes(c)) expansions.push(c);
  }

  return expansions.slice(0, maxQueries);
}

export interface RerankCandidate {
  id: string;
  originalIndex: number;
}

export interface RerankScore {
  id: string;
  score: number;
}

export interface RerankCacheEntry {
  expiresAtMs: number;
  rankedIds: string[];
}

export class RerankCache {
  private entries = new Map<string, RerankCacheEntry>();

  get(key: string): string[] | null {
    const e = this.entries.get(key);
    if (!e) return null;
    if (Date.now() > e.expiresAtMs) {
      this.entries.delete(key);
      return null;
    }
    return e.rankedIds.slice();
  }

  set(key: string, rankedIds: string[], ttlMs: number): void {
    this.entries.set(key, { rankedIds: rankedIds.slice(), expiresAtMs: Date.now() + ttlMs });
  }
}

/**
 * Parse a rerank response (JSON) and return candidates sorted by score.
 *
 * Rules:
 * - Unknown IDs in the response are ignored.
 * - Candidates missing from the response keep relative order after scored ones.
 * - Stable tie-breaker: originalIndex ascending.
 */
export function parseRerankResponse(
  raw: string,
  candidates: RerankCandidate[]
): Array<RerankCandidate & { score?: number }> {
  const byId = new Map<string, RerankCandidate>();
  for (const c of candidates) byId.set(c.id, c);

  const scores = new Map<string, number>();
  try {
    const parsed = JSON.parse(raw) as { scores?: Array<Partial<RerankScore>> };
    if (Array.isArray(parsed.scores)) {
      for (const s of parsed.scores) {
        if (!s || typeof s.id !== "string") continue;
        if (!byId.has(s.id)) continue;
        if (typeof s.score !== "number" || !Number.isFinite(s.score)) continue;
        scores.set(s.id, s.score);
      }
    }
  } catch {
    // Ignore parse errors and fall back to original order.
  }

  const withScore = candidates.map((c) => ({
    ...c,
    score: scores.get(c.id),
  }));

  return withScore.sort((a, b) => {
    const as = a.score;
    const bs = b.score;
    if (typeof as === "number" && typeof bs === "number") {
      if (bs !== as) return bs - as;
      return a.originalIndex - b.originalIndex;
    }
    if (typeof as === "number") return -1;
    if (typeof bs === "number") return 1;
    return a.originalIndex - b.originalIndex;
  });
}

function stableKey(query: string, ids: string[]): string {
  // Keep candidate boundaries explicit; candidate IDs are arbitrary strings.
  return JSON.stringify([query.trim().toLowerCase(), ids]);
}

function clampSnippet(snippet: string, maxChars: number): string {
  const s = snippet.replace(/\s+/g, " ").trim();
  return s.length > maxChars ? s.slice(0, maxChars) : s;
}

export async function rerankLocalOrNoop(opts: {
  query: string;
  candidates: Array<{ id: string; snippet: string }>;
  local: {
    chatCompletion: (
      messages: Array<{ role: string; content: string }>,
      options?: {
        maxTokens?: number;
        temperature?: number;
        timeoutMs?: number;
        operation?: string;
        priority?: "recall-critical" | "background";
      }
    ) => Promise<{ content: string } | null>;
  };
  enabled: boolean;
  timeoutMs: number;
  maxCandidates: number;
  cache?: RerankCache;
  cacheEnabled: boolean;
  cacheTtlMs: number;
}): Promise<string[] | null> {
  if (!opts.enabled) return null;

  const ids = opts.candidates.slice(0, opts.maxCandidates).map((c) => c.id);
  if (ids.length <= 1) return ids;

  const key = stableKey(opts.query, ids);
  if (opts.cache && opts.cacheEnabled) {
    const cached = opts.cache.get(key);
    if (cached) return cached;
  }

  const payload = opts.candidates.slice(0, opts.maxCandidates).map((c) => ({
    id: c.id,
    snippet: clampSnippet(c.snippet, 400),
  }));

  const system = "You are a ranking system. Return JSON only. No markdown, no commentary.";
  const user = JSON.stringify(
    {
      task: "rerank",
      query: opts.query,
      candidates: payload,
      output: {
        scores: [{ id: "string", score: "number 0-100" }],
      },
      rules: [
        "Assign higher score to more relevant candidates.",
        "Prefer durability and direct relevance to the query.",
        "If unsure, keep scores close together.",
      ],
    },
    null,
    0
  );

  const res = await opts.local.chatCompletion(
    [
      { role: "system", content: system },
      { role: "user", content: user },
    ],
    {
      maxTokens: 800,
      temperature: 0.0,
      timeoutMs: opts.timeoutMs,
      operation: "rerank",
      priority: "recall-critical",
    }
  );
  if (!res?.content) return null;

  const parsed = parseRerankResponse(
    res.content,
    ids.map((id, i) => ({ id, originalIndex: i }))
  );
  const rankedIds = parsed.map((p) => p.id);

  if (opts.cache && opts.cacheEnabled) {
    opts.cache.set(key, rankedIds, opts.cacheTtlMs);
  }

  return rankedIds;
}

/**
 * Reorder `results` to match `rankedKeys` (a ranker's output order), keying by
 * `keyOf`. Items not present in `rankedKeys` are appended in their original
 * order. `keyOf` must return a stable identity (e.g. namespace-qualified) so
 * same-relative-path items across namespaces are not conflated.
 */
export function reorderByRankedKeys<T>(
  results: readonly T[],
  rankedKeys: readonly string[],
  keyOf: (item: T) => string,
): T[] {
  const byKey = new Map(results.map((r) => [keyOf(r), r]));
  const reordered: T[] = [];
  for (const key of rankedKeys) {
    const it = byKey.get(key);
    if (it) reordered.push(it);
  }
  const rankedSet = new Set(rankedKeys);
  for (const r of results) if (!rankedSet.has(keyOf(r))) reordered.push(r);
  return reordered;
}

import { mkdir, readFile } from "node:fs/promises";
import path from "node:path";
import { log } from "./logger.js";
import { writeFileAtomically } from "./maintenance/atomic-file.js";
import type { RelevanceFeedback } from "./types.js";

type RelevanceState = Record<string, RelevanceFeedback>;
type StateFileWriter = (filePath: string, content: string) => Promise<void>;

export class RelevanceStore {
  private readonly statePath: string;
  private readonly writeStateFile: StateFileWriter;
  private state: RelevanceState = {};
  private stateWriteChain: Promise<void> = Promise.resolve();

  constructor(memoryDir: string, options: { writeStateFile?: StateFileWriter } = {}) {
    this.statePath = path.join(memoryDir, "state", "relevance.json");
    this.writeStateFile =
      options.writeStateFile ??
      (async (filePath, content) => {
        await writeFileAtomically(filePath, content);
      });
  }

  async load(): Promise<void> {
    try {
      const raw = await readFile(this.statePath, "utf-8");
      const parsed = JSON.parse(raw) as RelevanceState;
      if (parsed && typeof parsed === "object") this.state = parsed;
    } catch {
      this.state = {};
    }
  }

  /**
   * Record a thumbs up/down for a memory ID.
   * This is intentionally lightweight; it should never block agent execution.
   */
  async record(memoryId: string, vote: "up" | "down", note?: string): Promise<void> {
    const now = new Date().toISOString();
    const existing = this.state[memoryId] ?? { up: 0, down: 0, lastUpdatedAt: now };
    const next: RelevanceFeedback = {
      up: existing.up + (vote === "up" ? 1 : 0),
      down: existing.down + (vote === "down" ? 1 : 0),
      lastUpdatedAt: now,
      notes: note
        ? [...(existing.notes ?? []).slice(-19), note]
        : existing.notes,
    };
    this.state[memoryId] = next;

    try {
      await this.flushState();
    } catch (err) {
      log.debug(`relevance store write failed: ${err}`);
    }
  }

  /**
   * Convert feedback into a small score adjustment.
   * Intended to be used as a tie-breaker/soft bias, not a hard filter.
   */
  adjustment(memoryId: string): number {
    const fb = this.state[memoryId];
    if (!fb) return 0;

    // Cap effect to avoid runaway ranking distortion.
    const up = Math.min(3, fb.up);
    const down = Math.min(3, fb.down);

    // Typical QMD scores are around 0-1; keep adjustments small.
    return up * 0.05 - down * 0.10; // max +0.15, min -0.30
  }

  private flushState(): Promise<void> {
    const run = this.stateWriteChain.catch(() => undefined).then(async () => {
      await mkdir(path.dirname(this.statePath), { recursive: true });
      await this.writeStateFile(this.statePath, JSON.stringify(this.state, null, 2));
    });
    this.stateWriteChain = run.then(
      () => undefined,
      () => undefined,
    );
    return run;
  }
}

import { mkdir, readFile, writeFile } from "node:fs/promises";
import path from "node:path";
import { log } from "./logger.js";

export interface NegativeExampleEntry {
  notUseful: number;
  lastUpdatedAt: string;
  notes?: string[];
}

type NegativeState = Record<string, NegativeExampleEntry>;

const POISONOUS_NEGATIVE_MEMORY_IDS = new Set(["__proto__", "prototype", "constructor"]);

function createNegativeState(): NegativeState {
  return Object.create(null) as NegativeState;
}

function isSafeNegativeMemoryId(memoryId: unknown): memoryId is string {
  return (
    typeof memoryId === "string" &&
    memoryId.length > 0 &&
    !POISONOUS_NEGATIVE_MEMORY_IDS.has(memoryId)
  );
}

function sanitizeNegativeState(value: unknown): NegativeState {
  if (!value || typeof value !== "object" || Array.isArray(value)) return createNegativeState();

  const state = createNegativeState();
  for (const [memoryId, rawEntry] of Object.entries(value)) {
    if (!isSafeNegativeMemoryId(memoryId)) continue;
    if (!rawEntry || typeof rawEntry !== "object" || Array.isArray(rawEntry)) continue;
    const entry = rawEntry as Partial<NegativeExampleEntry>;
    if (
      typeof entry.notUseful !== "number" ||
      !Number.isFinite(entry.notUseful) ||
      entry.notUseful < 0
    ) {
      continue;
    }
    if (typeof entry.lastUpdatedAt !== "string") continue;
    const notes = Array.isArray(entry.notes)
      ? entry.notes.filter((note): note is string => typeof note === "string")
      : undefined;
    state[memoryId] = {
      notUseful: Math.floor(entry.notUseful),
      lastUpdatedAt: entry.lastUpdatedAt,
      notes: notes && notes.length > 0 ? notes : undefined,
    };
  }
  return state;
}

export class NegativeExampleStore {
  private readonly statePath: string;
  private state: NegativeState = createNegativeState();

  constructor(memoryDir: string) {
    this.statePath = path.join(memoryDir, "state", "negative_examples.json");
  }

  async load(): Promise<void> {
    try {
      const raw = await readFile(this.statePath, "utf-8");
      this.state = sanitizeNegativeState(JSON.parse(raw));
    } catch {
      this.state = createNegativeState();
    }
  }

  /**
   * Record that a memory was retrieved but not useful for the user.
   * This should be lightweight and never block agent execution.
   */
  async recordNotUseful(memoryIds: string[], note?: string): Promise<void> {
    const now = new Date().toISOString();

    for (const memoryId of memoryIds) {
      if (!isSafeNegativeMemoryId(memoryId)) continue;
      const existing = this.state[memoryId] ?? { notUseful: 0, lastUpdatedAt: now };
      const next: NegativeExampleEntry = {
        notUseful: existing.notUseful + 1,
        lastUpdatedAt: now,
        notes: note
          ? [...(existing.notes ?? []).slice(-19), note]
          : existing.notes,
      };
      this.state[memoryId] = next;
    }

    try {
      await mkdir(path.dirname(this.statePath), { recursive: true });
      await writeFile(this.statePath, JSON.stringify(this.state, null, 2), "utf-8");
    } catch (err) {
      log.debug(`negative example store write failed: ${err}`);
    }
  }

  /**
   * Convert negative examples into a small score penalty.
   * Intended as a soft bias, not a hard filter.
   */
  penalty(memoryId: string, opts: { perHit: number; cap: number }): number {
    if (!isSafeNegativeMemoryId(memoryId)) return 0;
    const entry = this.state[memoryId];
    if (!entry) return 0;
    if (!Number.isFinite(entry.notUseful) || entry.notUseful < 0) return 0;
    if (!Number.isFinite(opts.perHit) || opts.perHit < 0) return 0;
    if (!Number.isFinite(opts.cap) || opts.cap < 0) return 0;

    // Cap effect to avoid runaway ranking distortion.
    const hits = Math.min(10, entry.notUseful);
    const raw = hits * opts.perHit;
    return Math.min(opts.cap, raw);
  }
}

