export interface GraphRecallExpandedEntry {
  path: string;
  score: number;
  namespace: string;
  seed: string;
  hopDepth: number;
  decayedWeight: number;
  graphType: "entity" | "time" | "causal";
  /**
   * Issue #681 PR 3/3 — confidence of the edge that produced this entry's
   * recorded provenance (strongest edge along the chosen entry path).
   * Range `[0, 1]`. Optional so persisted snapshots from older builds
   * round-trip through `clampGraphRecallExpandedEntries` without dropping.
   */
  edgeConfidence?: number;
  /** Graph-relative activation path node ids when provenance is enabled. */
  pathNodeIds?: string[];
  /** True when a graph path penalty was applied. */
  pathPenaltyApplied?: boolean;
}

export function clampGraphRecallExpandedEntries(
  entries: unknown,
  maxEntries: number = 64,
): GraphRecallExpandedEntry[] {
  const limit = Math.max(1, Math.floor(maxEntries));
  if (!Array.isArray(entries)) return [];
  return entries
    .filter((item): item is Record<string, unknown> => !!item && typeof item === "object")
    .map((item) => {
      const graphType: "entity" | "time" | "causal" =
        item.graphType === "entity" || item.graphType === "time" || item.graphType === "causal"
          ? item.graphType
          : "entity";
      const out: GraphRecallExpandedEntry = {
        path: typeof item.path === "string" ? item.path : "",
        score: typeof item.score === "number" && Number.isFinite(item.score) ? item.score : 0,
        namespace: typeof item.namespace === "string" ? item.namespace : "",
        seed: typeof item.seed === "string" ? item.seed : "",
        hopDepth:
          typeof item.hopDepth === "number" && Number.isFinite(item.hopDepth)
            ? Math.max(0, Math.floor(item.hopDepth))
            : 0,
        decayedWeight:
          typeof item.decayedWeight === "number" && Number.isFinite(item.decayedWeight)
            ? Math.max(0, item.decayedWeight)
            : 0,
        graphType,
      };
      // Issue #681 PR 3/3: clamp `edgeConfidence` into [0, 1] when present.
      // Older snapshots without the field round-trip cleanly via the
      // optional shape; legacy callers always rendered as 1.0.
      if (
        typeof item.edgeConfidence === "number" &&
        Number.isFinite(item.edgeConfidence)
      ) {
        out.edgeConfidence = Math.min(1, Math.max(0, item.edgeConfidence));
      }
      if (
        Array.isArray(item.pathNodeIds) &&
        item.pathNodeIds.every((value): value is string => typeof value === "string")
      ) {
        out.pathNodeIds = item.pathNodeIds.slice(0, 64);
      }
      if (typeof item.pathPenaltyApplied === "boolean") {
        out.pathPenaltyApplied = item.pathPenaltyApplied;
      }
      return out;
    })
    .filter((item) => item.path.length > 0 && item.namespace.length > 0)
    .slice(0, limit);
}

type LastRecallState = Record<string, LastRecallSnapshot>;
type StateFileWriter = (filePath: string, content: string) => Promise<void>;

/**
 * Deep-copy a RecallTierExplain block.  Used by both the write path
 * (so caller mutation after `record()` cannot tear the persisted
 * snapshot) and the read path (so caller mutation after `get()` /
 * `getMostRecent()` cannot tear the in-memory store).
 *
 * Uses structuredClone so future additions to RecallTierExplain do
 * not silently share references through hand-enumerated fields —
 * matching the pattern used elsewhere in the codebase (e.g.,
 * qmd-recall-cache.ts).  The payload is pure JSON-shaped data, so
 * structuredClone is both safe and complete here.
 */
/**
 * Stale-snapshot identity guard shared by the annotate methods (issue #518):
 * a writeNonce match wins outright; otherwise traceId (when expected) and
 * recordedAt are compared. Extracted so every annotation surface applies
 * identical guards (CLAUDE.md rule 22).
 */
function cloneTierExplain(
  tierExplain: RecallTierExplain | undefined,
): RecallTierExplain | undefined {
  if (!tierExplain) return undefined;
  return structuredClone(tierExplain);
}

function snapshotMatchesExpectedIdentity(
  current: LastRecallSnapshot,
  expected?: { writeNonce?: string; traceId?: string; recordedAt?: string },
): boolean {
  if (!expected) return true;
  if (typeof expected.writeNonce === "string" && expected.writeNonce.length > 0) {
    return current.writeNonce === expected.writeNonce;
  }
  const hasExpectedTraceId =
    typeof expected.traceId === "string" && expected.traceId.length > 0;
  if (hasExpectedTraceId && current.traceId !== expected.traceId) return false;
  if (typeof expected.recordedAt === "string" && expected.recordedAt.length > 0) {
    return current.recordedAt === expected.recordedAt;
  }
  return true;
}

function hydrateLastRecallSnapshot(snapshot: LastRecallSnapshot): LastRecallSnapshot {
  const includedMemories = coerceIncludedMemories(snapshot);
  const budgets = snapshot.budgetsApplied
    ? {
        ...snapshot.budgetsApplied,
        includedMemoryIds: includedMemories.map((memory) => memory.id),
        includedMemoryPaths: includedMemories.map((memory) => memory.path),
        includedMemoryNamespaces: includedMemories.map((memory) => memory.namespace),
      }
    : undefined;
  return {
    ...snapshot,
    includedMemories,
    memoryIds: includedMemories.map((memory) => memory.id),
    resultPaths: includedMemories.map((memory) => memory.path),
    resultNamespaces: includedMemories.map((memory) => memory.namespace),
    ...(budgets ? { budgetsApplied: budgets } : {}),
  };
}

function cloneLastRecallSnapshot(
  snapshot: LastRecallSnapshot | null,
): LastRecallSnapshot | null {
  if (!snapshot) return null;
  return structuredClone(hydrateLastRecallSnapshot(snapshot));
}



export interface TierMigrationCycleSummary {
  trigger: "extraction" | "maintenance" | "manual";
  scanned: number;
  migrated: number;
  promoted: number;
  demoted: number;
  limit: number;
  dryRun: boolean;
  skipped?: string;
  errorCount?: number;
}

export interface TierMigrationStatusSnapshot {
  updatedAt: string;
  lastCycle: TierMigrationCycleSummary | null;
  totals: {
    cycles: number;
    scanned: number;
    migrated: number;
    promoted: number;
    demoted: number;
    errors: number;
  };
}

const DEFAULT_TIER_MIGRATION_STATUS: TierMigrationStatusSnapshot = {
  updatedAt: new Date(0).toISOString(),
  lastCycle: null,
  totals: {
    cycles: 0,
    scanned: 0,
    migrated: 0,
    promoted: 0,
    demoted: 0,
    errors: 0,
  },
};

/**
 * Suffix marking an impression spill CLAIMED for commit but not yet deleted.
 * The crash-safe drain renames `<uuid>.jsonl` -> `<uuid>.jsonl.claimed` before
 * committing its rows, mirroring the lifecycle ledger's claim/commit protocol
 * (#2033).
 */
const CLAIMED_IMPRESSION_SPILL_SUFFIX = ".claimed";

/**
 * Outcome of {@link LastRecallStore.drainPendingImpressions}. Distinguishes a
 * completed drain (or nothing pending) from a DEFERRED drain that left durable
 * spills in the offline-sync-EXCLUDED queue, so the caller can tell the
 * data-safe cases apart from the one where an offline-sync snapshot would
 * silently omit recorded impressions (#2033).
 */
export interface DrainPendingImpressionsResult {
  /** Pending spill rows were folded into the synced active file this call. */
  folded: boolean;
  /**
   * Durable spill rows remain in the offline-sync-EXCLUDED pending queue after
   * this drain: the rotation lock could not be acquired, a spill could not be
   * claimed, or the drain-only fold left rows that would only fit by rotating
   * into a sync-excluded archive. A snapshot taken now would silently omit them
   * (#2033): the caller MUST treat the active file as INCOMPLETE and retry or
   * abort the snapshot rather than report success. `false` means the active file
   * is complete — every pending row was folded or nothing was pending.
   */
  pendingDeferred: boolean;
}

export class LastRecallStore {
  private readonly statePath: string;
  private readonly impressionsPath: string;
  private readonly writeStateFile: StateFileWriter;
  private readonly impressionsRotateBytes: number;
  private readonly impressionsRotateKeep: number;
  // Lock-acquisition timing for the cross-process impression rotation lock.
  // Only tests set this (small maxWaitMs) to force the acquisition-timeout
  // (`acquired=false`) branch deterministically; production uses the defaults.
  private readonly impressionsLockOptions?: Pick<HeldFileLockOptions, "maxWaitMs" | "pollMs">;
  private state: LastRecallState = {};
  private stateWriteChain: Promise<void> = Promise.resolve();
  // Serializes the rotate-then-append critical section so concurrent record()
  // calls never interleave rotation renames with each other's appends (#1910).
  private impressionsWriteChain: Promise<void> = Promise.resolve();

  constructor(
    memoryDir: string,
    options: {
      writeStateFile?: StateFileWriter;
      impressionsRotateBytes?: number;
      impressionsRotateKeep?: number;
      impressionsLockOptions?: Pick<HeldFileLockOptions, "maxWaitMs" | "pollMs">;
    } = {},
  ) {
    this.statePath = path.join(memoryDir, "state", "last_recall.json");
    this.impressionsPath = path.join(memoryDir, "state", "recall_impressions.jsonl");
    // 0 disables rotation (never coerced to a default); keep floors at 1.
    this.impressionsRotateBytes = Math.max(0, Math.floor(options.impressionsRotateBytes ?? 0));
    this.impressionsRotateKeep = Math.max(1, Math.floor(options.impressionsRotateKeep ?? 5));
    this.impressionsLockOptions = options.impressionsLockOptions;
    this.writeStateFile =
      options.writeStateFile ??
      (async (filePath, content) => {
        await writeFileAtomically(filePath, content);
      });
  }

  async load(): Promise<void> {
    try {
      const raw = await readFile(this.statePath, "utf-8");
      const parsed: unknown = JSON.parse(raw);
      if (!parsed || typeof parsed !== "object" || Array.isArray(parsed)) {
        this.state = {};
        return;
      }
      const next: LastRecallState = {};
      for (const [sessionKey, snapshot] of Object.entries(parsed)) {
        if (sessionKey === "__proto__" || sessionKey === "constructor" || sessionKey === "prototype") {
          continue;
        }
        if (!snapshot || typeof snapshot !== "object" || Array.isArray(snapshot)) {
          continue;
        }
        next[sessionKey] = hydrateLastRecallSnapshot(snapshot as LastRecallSnapshot);
      }
      this.state = next;
    } catch {
      this.state = {};
    }
  }

  get(sessionKey: string): LastRecallSnapshot | null {
    // Defensive copy: callers must not be able to mutate internal state
    // by reaching into array/object fields on the returned snapshot.
    if (isUnsafeStateKey(sessionKey)) return null;
    return cloneLastRecallSnapshot(this.state[sessionKey] ?? null);
  }

  getMostRecent(): LastRecallSnapshot | null {
    const snapshots = Object.values(this.state);
    if (snapshots.length === 0) return null;
    // Secondary key on sessionKey keeps the sort stable when two
    // snapshots share a recordedAt timestamp (CLAUDE.md rule 19).
    snapshots.sort((a, b) => {
      const byTime = b.recordedAt.localeCompare(a.recordedAt);
      if (byTime !== 0) return byTime;
      return a.sessionKey.localeCompare(b.sessionKey);
    });
    return cloneLastRecallSnapshot(snapshots[0] ?? null);
  }

  /**
   * Persist last-recall snapshot and append an impression log entry.
   * Does not store raw query text; uses a stable hash for correlation.
   */
  async record(opts: {
    sessionKey: string;
    query: string;
    memoryIds?: string[];
    includedMemories?: IncludedMemory[];
    namespace?: string;
    recallNamespaces?: string[];
    traceId?: string;
    plannerMode?: RecallPlanMode;
    requestedMode?: RecallPlanMode;
    source?: string;
    fallbackUsed?: boolean;
    sourcesUsed?: string[];
    budgetsApplied?: LastRecallBudgetSummary;
    latencyMs?: number;
    resultPaths?: string[];
    resultNamespaces?: Array<string | undefined>;
    policyVersion?: string;
    appendImpression?: boolean;
    identityInjection?: {
      mode: IdentityInjectionMode | "none";
      injectedChars: number;
      truncated: boolean;
    };
    /**
     * Per-tier explain annotation (issue #518).  When supplied, the
     * snapshot carries it so downstream surfaces (CLI / HTTP / MCP)
     * can render which retrieval tier served the query.
     */
    tierExplain?: RecallTierExplain;
    /**
     * Backend degradations observed while serving this recall (issue #1536).
     * Passed at record time so the published snapshot is born annotated —
     * a post-record annotation would leave a window where readers see the
     * snapshot without them (codex review on #1544).
     */
    backendDegradations?: SearchDegradation[];
  }): Promise<void> {
    if (isUnsafeStateKey(opts.sessionKey)) {
      log.debug("last recall record skipped: unsafe session key");
      return;
    }
    const now = new Date().toISOString();
    const queryHash = createHash("sha256").update(opts.query).digest("hex");

    // Build the snapshot from opts, then deep-copy it via
    // cloneLastRecallSnapshot so caller arrays/objects passed in
    // `opts` cannot retain a live reference to the persisted state and
    // tear it after `record()` returns.
    const includedMemories = coerceIncludedMemories(opts);
    const liveSnapshot: LastRecallSnapshot = {
      sessionKey: opts.sessionKey,
      recordedAt: now,
      queryHash,
      writeNonce: randomUUID(),
      queryLen: opts.query.length,
      includedMemories,
      memoryIds: includedMemories.map((memory) => memory.id),
      namespace: opts.namespace,
      recallNamespaces: opts.recallNamespaces,
      traceId: opts.traceId,
      plannerMode: opts.plannerMode,
      requestedMode: opts.requestedMode,
      source: opts.source,
      fallbackUsed: opts.fallbackUsed,
      sourcesUsed: opts.sourcesUsed,
      budgetsApplied: opts.budgetsApplied,
      latencyMs: opts.latencyMs,
      policyVersion: opts.policyVersion,
      identityInjectionMode: opts.identityInjection?.mode,
      identityInjectedChars: opts.identityInjection?.injectedChars,
      identityInjectionTruncated: opts.identityInjection?.truncated,
      tierExplain: opts.tierExplain,
      backendDegradations:
        opts.backendDegradations && opts.backendDegradations.length > 0
          ? opts.backendDegradations
          : undefined,
    };
    // `cloneLastRecallSnapshot` handles `null` but that never applies
    // at this call site — the non-null assertion keeps the type
    // checker honest.
    const snapshot = cloneLastRecallSnapshot(liveSnapshot)!;

    this.state[opts.sessionKey] = snapshot;

    // Keep the state bounded; the impression log is append-only.
    const keys = Object.keys(this.state);
    if (keys.length > 50) {
      const ordered = keys
        .map((k) => ({ k, at: this.state[k]?.recordedAt ?? "" }))
        .sort((a, b) => b.at.localeCompare(a.at));
      for (const doomed of ordered.slice(50)) {
        delete this.state[doomed.k];
      }
    }

    try {
      await this.flushState();
    } catch (err) {
      log.debug(`last recall store write failed: ${err}`);
    }

    if (opts.appendImpression !== false) {
      const line = JSON.stringify(snapshot) + "\n";
      // Chain onto the previous impression write so rotation + append run as one
      // serialized critical section — concurrent record() calls can never
      // interleave a rename with another call's append (#1910). `.catch` before
      // the link keeps a prior failure from poisoning the chain.
      const chained = this.impressionsWriteChain
        .catch(() => {})
        .then(() => this.appendImpressionSerialized(line));
      this.impressionsWriteChain = chained;
      try {
        await chained;
      } catch (err) {
        log.debug(`recall impressions append failed: ${err}`);
      }
    }
  }

  /**
   * Drain pending spills, rotate (best-effort, sized to the projected payload),
   * then append one impression line under ONE shared cross-process lock (#1910,
   * #2033). Both the archive-shift renames AND the append run inside the same
   * held lock so a peer process holding the lock can never rename the active
   * inode to `.1` between our open and write — which would land the impression in
   * a rotated archive that offline-sync excludes, silently dropping it from
   * active-state/sync consumers.
   *
   * On lock-acquisition timeout the impression is NEVER written to the active
   * file unlocked (#2033): a peer holding the lock is likely mid-rotation, so an
   * unlocked append can land in the inode it is about to rename to `.1` — the
   * exact silent-drop this lock prevents. Instead the row is spilled to a
   * durable node-local per-event file under `<impressions>.pending.d/` and
   * folded back into the active file by the next append that DOES hold the lock,
   * preserving durability without racing rotation. Rotation failure under the
   * held lock is logged and the append still runs. Callers invoke this only
   * through `impressionsWriteChain` so the sequence is serialized in-process.
   */
  private get impressionsPendingDir(): string {
    return `${this.impressionsPath}.pending.d`;
  }

  private async spillImpression(line: string): Promise<void> {
    await ensureContainedSpillDir(this.impressionsPendingDir);
    // Write to a temp name the drain's `.jsonl` lister ignores, then atomically
    // rename to the final `<uuid>.jsonl` (#2033). writeFile creates the path
    // before its bytes are durable, so writing straight to the final name lets a
    // concurrent lock holder's drain read/rename/delete a partial spill and
    // append malformed JSON — permanently losing that impression. The temp lives
    // in the SAME contained dir, so the rename is atomic and stays symlink-safe.
    const id = randomUUID();
    const tempPath = path.join(this.impressionsPendingDir, `${id}.jsonl.tmp`);
    const finalPath = path.join(this.impressionsPendingDir, `${id}.jsonl`);
    await writeFile(tempPath, line, "utf-8");
    await rename(tempPath, finalPath);
  }

  /**
   * Recover a claim a crashed drain left mid-flight (#2033): the crash-safe
   * drain renames `<uuid>.jsonl` -> `<uuid>.jsonl.claimed` BEFORE committing, so
   * a `.claimed` file with no matching commit is the ONLY durable copy of those
   * rows. Rename each orphan back to `<uuid>.jsonl` so it re-enters the normal
   * collect+claim+commit flow. MUST run under the held rotation lock, before
   * collecting. listContainedSpillFiles skips symlinked/escaping entries.
   */
  private async recoverOrphanedImpressionClaims(): Promise<void> {
    const orphans = await listContainedSpillFiles(
      this.impressionsPendingDir,
      `.jsonl${CLAIMED_IMPRESSION_SPILL_SUFFIX}`,
    );
    for (const claimedPath of orphans) {
      const original = claimedPath.slice(0, -CLAIMED_IMPRESSION_SPILL_SUFFIX.length);
      await rename(claimedPath, original).catch(() => undefined);
    }
  }

  /**
   * Recover a crash-orphaned spill temp after its write completed but before
   * the atomic `.tmp` → `.jsonl` rename. Valid JSONL temps are promoted back
   * into the normal queue; incomplete temps remain pending and keep offline sync
   * deferred rather than being discarded.
   */
  private async recoverOrphanedImpressionTemps(): Promise<void> {
    const temps = await listContainedSpillFiles(this.impressionsPendingDir, ".jsonl.tmp");
    for (const tempPath of temps) {
      let content: string;
      try {
        content = await readFile(tempPath, "utf-8");
        for (const line of content.split("\n")) {
          if (line.trim().length > 0) JSON.parse(line);
        }
      } catch {
        continue;
      }
      const finalPath = tempPath.slice(0, -".tmp".length);
      await rename(tempPath, finalPath).catch(() => undefined);
    }
  }

  private async appendImpressionSerialized(line: string): Promise<void> {
    await mkdir(path.dirname(this.impressionsPath), { recursive: true });
    // Every active-file write goes under the shared cross-process rotation lock,
    // even when THIS writer's local rotation is disabled (`impressionsRotateBytes
    // <= 0`). A peer process with rotation enabled shares this lock and may
    // rename the active inode to `.1` at any moment, so an unlocked append could
    // land in an offline-sync-excluded archive and be silently dropped (#2033).
    // Only the local rotate DECISION is disabled — the bounded fold skips
    // rotation when this writer's limit is 0 — the lock itself is not.
    const lockPath = `${this.impressionsPath}.lock`;
    await withHeldFileLock(
      lockPath,
      { staleMs: 30_000, ...this.impressionsLockOptions },
      async (acquired) => {
        // withHeldFileLock falls back to task(false) when it cannot acquire the
        // lock within the budget. Do NOT append to the active file unlocked: a
        // peer holding the lock may be mid-rotation, so an unlocked append could
        // land in the inode it renames to `.1` (an offline-sync-excluded
        // archive), silently dropping the impression. Spill it to the durable
        // pending queue instead — the next lock holder folds it back in (#2033).
        if (!acquired) {
          log.debug("recall impressions rotation lock not acquired; spilling impression to the durable pending queue");
          await this.spillImpression(line);
          return;
        }
        await this.foldPendingImpressionsAndAppend(line);
      },
    );
  }

  /**
   * Fold any durable pending recall-impression spills into the synced active
   * `recall_impressions.jsonl` WITHOUT recording a new impression (#2033).
   *
   * The pending spill dir is offline-sync-excluded, so an impression that a
   * lock-timed-out `record()` spilled there is absent from an offline-sync
   * snapshot and lost if this node is discarded before the next `record()`
   * folds it back. Offline sync calls this before building a snapshot so a
   * recorded impression always reaches the remote. Fast no-op — no lock and no
   * dir/lock-file creation — when nothing is pending.
   *
   * Returns a {@link DrainPendingImpressionsResult}: `folded` is true when rows
   * were folded into the active file; `pendingDeferred` is true when durable
   * spills still remain in the offline-sync-EXCLUDED queue after this call —
   * because the rotation lock could not be acquired, a spill could not be
   * claimed, or the drain-only fold deferred rows that would only fit by
   * rotating into a sync-excluded archive (#2033). A snapshot taken while
   * `pendingDeferred` is true would silently drop those rows, so the caller MUST
   * NOT report a clean snapshot — it either retries or aborts.
   */
  async drainPendingImpressions(): Promise<DrainPendingImpressionsResult> {
    if (!(await this.pendingSpillsRemain())) {
      return { folded: false, pendingDeferred: false };
    }
    const lockPath = `${this.impressionsPath}.lock`;
    let folded = false;
    let acquiredLock = false;
    let spillsRemain = false;
    await withHeldFileLock(
      lockPath,
      { staleMs: 30_000, ...this.impressionsLockOptions },
      async (acquired) => {
        // A peer holds the lock (mid-rotation or mid-append). We MUST NOT touch
        // the active file unlocked (#2033), so the spills stay in the
        // offline-sync-EXCLUDED pending queue. Report the drain as DEFERRED
        // (pendingDeferred=true) so the caller does not build a snapshot that
        // silently omits them; the next lock holder — or a caller retry — folds
        // them in.
        if (!acquired) return;
        acquiredLock = true;
        folded = await this.foldPendingImpressionsAndAppend(null);
        // Even WITH the lock, a spill the fold could not claim or a `.claimed`
        // orphan a failed commit left behind keeps durable rows in the excluded
        // queue. Treat that as an incomplete drain so the caller retries/aborts
        // rather than snapshotting an active file that omits them (#2033).
        spillsRemain = await this.pendingSpillsRemain();
      },
    );
    return { folded, pendingDeferred: !acquiredLock || spillsRemain };
  }

  /**
   * Claim/commit fold of durable pending impression spills into the active file
   * under the held rotation lock (#2033). `line` is a new impression to append
   * after the drained rows, or null for a drain-only pre-sync fold.
   *
   * Each spill is folded as an INDEPENDENT claim -> append -> finalize unit
   * rather than materializing the whole queue as one joined payload and
   * splitting it in a single synchronous pass (#2033). A multi-hundred-MB drain
   * done as one join/split blocks the event loop long enough for
   * `withHeldFileLock`'s ownership-refresh timer to miss its window, so a peer
   * stale-breaks the 30s lock and rotates/appends concurrently — defeating the
   * rotation lock this drain relies on. The per-file `await`s keep the payload
   * bounded to one spill at a time and let the refresh timer fire between files.
   *
   * The DRAIN-ONLY path (`line === null`, run before an offline-sync snapshot)
   * NEVER rotates a drained row into an archive. `recall_impressions.jsonl.*`
   * is offline-sync-EXCLUDED, so rotating a just-drained row into `.1`/`.2` and
   * then deleting its spill would leave that row only in a path sync omits —
   * silently lost when the node is discarded after a "successful" sync (#2033).
   * It folds only the rows that fit the synced active file under the cap and
   * leaves the rest durable in the pending queue; {@link drainPendingImpressions}
   * then reports the drain DEFERRED so the caller retries or aborts. The
   * record() path (`line !== null`) keeps rotating normally — its archives stay
   * on a live node that is not being discarded.
   *
   * Recovers any crash-orphaned claim first. Each impression carries a unique
   * writeNonce, so a crash-recovered re-commit is a collapsible duplicate, never
   * a lost row. listContainedSpillFiles rejects symlinked/escaping entries; a
   * spill that cannot be claimed is skipped this pass. An append failure rolls
   * that spill's claim back so the row retries on the next lock holder's drain.
   * Returns true when the active file was written. MUST run under the held
   * rotation lock.
   */
  private async foldPendingImpressionsAndAppend(line: string | null): Promise<boolean> {
    await this.recoverOrphanedImpressionTemps();
    await this.recoverOrphanedImpressionClaims();
    const spillFiles = await listContainedSpillFiles(this.impressionsPendingDir);
    const drainOnly = line === null;
    const cap = this.impressionsRotateBytes;
    let activeSize = 0;
    if (cap > 0) {
      try {
        activeSize = (await stat(this.impressionsPath)).size;
      } catch (err) {
        if (!isErrnoCode(err, "ENOENT")) throw err;
      }
    }
    let wrote = false;
    for (const filePath of spillFiles) {
      const content = await readFile(filePath, "utf-8");
      const unit = content.length === 0 || content.endsWith("\n") ? content : `${content}\n`;
      const unitBytes = Buffer.byteLength(unit, "utf-8");
      // Drain-only fold must never push a drained row into a sync-excluded
      // archive (#2033). Once the active file cannot take this spill under the
      // cap without rotating, stop: the remaining spills stay durable in the
      // pending queue and the drain reports itself deferred. A lone spill larger
      // than the cap on an empty active file is still folded whole (it cannot be
      // split without corrupting JSONL) so it reaches sync rather than stranding.
      if (drainOnly && cap > 0 && activeSize > 0 && activeSize + unitBytes >= cap) break;
      const claimedPath = `${filePath}${CLAIMED_IMPRESSION_SPILL_SUFFIX}`;
      try {
        await rename(filePath, claimedPath);
      } catch {
        continue; // could not claim → do not commit; a later drain retries it.
      }
      try {
        activeSize = await this.appendImpressionUnit(unit, activeSize, drainOnly);
      } catch (err) {
        // Commit failed: roll this spill's claim back so it retries on the next
        // lock holder's drain instead of being lost.
        await rename(claimedPath, filePath).catch(() => undefined);
        throw err;
      }
      // Commit is durable: delete the claimed file. A delete that fails leaves a
      // `.claimed` orphan the next drain recovers and re-commits — a
      // writeNonce-collapsible duplicate, never a lost row (#2033).
      await unlink(claimedPath).catch(() => undefined);
      wrote = true;
    }
    if (line !== null) {
      activeSize = await this.appendImpressionUnit(line, activeSize, false);
      wrote = true;
    }
    return wrote;
  }

  /**
   * Append one whole JSONL unit (a claimed spill's rows or a fresh impression
   * line) to the active impressions file, returning the resulting active-file
   * byte size. On the rotating (record) path, when the unit would push the
   * current active generation to/over `impressionsRotateBytes`, the full active
   * file is rotated aside FIRST so no generation exceeds the cap (#2033); a lone
   * unit larger than the cap on an empty active file is written whole because
   * splitting a JSONL row would corrupt it. `drainOnly` and disabled rotation
   * (`impressionsRotateBytes <= 0`) both skip rotation — drain-only defers its
   * overflow in {@link foldPendingImpressionsAndAppend} rather than rotating into
   * a sync-excluded archive. A rotation error is logged and the append still
   * runs so a row is never lost; an append failure propagates so the caller
   * rolls its claim back. MUST run under the held rotation lock.
   */
  private async appendImpressionUnit(
    unit: string,
    activeSize: number,
    drainOnly: boolean,
  ): Promise<number> {
    const cap = this.impressionsRotateBytes;
    const unitBytes = Buffer.byteLength(unit, "utf-8");
    if (cap > 0 && !drainOnly && activeSize > 0 && activeSize + unitBytes >= cap) {
      try {
        await this.shiftImpressionArchives();
        activeSize = 0;
      } catch (err) {
        log.debug(`recall impressions rotation failed (append preserved): ${err}`);
      }
    }
    await appendFile(this.impressionsPath, unit, "utf-8");
    return activeSize + unitBytes;
  }

  /**
   * True when any live `<uuid>.jsonl` spill, crash-orphaned `.claimed` file,
   * or crash-orphaned `.jsonl.tmp` spill remains in the offline-sync-EXCLUDED
   * pending queue (#2033). After a drain acquires the rotation lock, a spill
   * the fold could not claim (rename race / read-only dir) or a `.claimed`
   * orphan a failed commit left behind means durable rows are STILL excluded
   * from a snapshot — the drain must report itself INCOMPLETE so the caller
   * retries or aborts rather than snapshotting an active file that omits them.
   */
  private async pendingSpillsRemain(): Promise<boolean> {
    if ((await listContainedSpillFiles(this.impressionsPendingDir, ".jsonl.tmp")).length > 0) {
      return true;
    }
    const liveSpills = await listContainedSpillFiles(this.impressionsPendingDir);
    if (liveSpills.length > 0) return true;
    const claimed = await listContainedSpillFiles(
      this.impressionsPendingDir,
      `.jsonl${CLAIMED_IMPRESSION_SPILL_SUFFIX}`,
    );
    return claimed.length > 0;
  }

  /**
   * Shift `.1..N` archives down one slot and move the active file to `.1`,
   * dropping anything beyond `keep`. Callers invoke this only while holding the
   * cross-process rotation lock (issue #1910).
   */
  private async shiftImpressionArchives(): Promise<void> {
    const keep = this.impressionsRotateKeep;
    // Drop the archive that would fall off the end, then shift down: .(keep-1)
    // -> .keep, ..., .1 -> .2, active -> .1.
    try {
      await rm(`${this.impressionsPath}.${keep}`, { force: true });
    } catch {
      // best-effort cleanup of the oldest archive
    }
    for (let i = keep - 1; i >= 1; i -= 1) {
      try {
        await rename(`${this.impressionsPath}.${i}`, `${this.impressionsPath}.${i + 1}`);
      } catch (err) {
        if (!isErrnoCode(err, "ENOENT")) throw err;
      }
    }
    try {
      await rename(this.impressionsPath, `${this.impressionsPath}.1`);
    } catch (err) {
      if (!isErrnoCode(err, "ENOENT")) throw err;
    }
  }

  /**
   * Attach a RecallTierExplain block to the existing snapshot for a
   * session without rewriting the entire snapshot.  Used by the
   * post-recall direct-answer annotation path (issue #518 slice 3c):
   * recallInternal records the snapshot first, then the orchestrator
   * fires the direct-answer tier in observation mode and annotates
   * the stored snapshot with whichever tier served the query.
   *
   * No-op when no snapshot exists for the given session; callers do
   * not need to guard on existence.
   */
  async annotateTierExplain(
    sessionKey: string,
    tierExplain: RecallTierExplain,
    expected?: { writeNonce?: string; traceId?: string; recordedAt?: string },
  ): Promise<void> {
    if (isUnsafeStateKey(sessionKey)) return;
    const current = this.state[sessionKey];
    if (!current) return;
    if (!snapshotMatchesExpectedIdentity(current, expected)) return;
    this.state[sessionKey] = {
      ...current,
      tierExplain: cloneTierExplain(tierExplain),
    };
    try {
      await this.flushState();
    } catch (err) {
      log.debug(`last recall tier-explain annotate failed: ${err}`);
    }
  }


  private flushState(): Promise<void> {
    const run = this.stateWriteChain.catch(() => undefined).then(async () => {
      await mkdir(path.dirname(this.statePath), { recursive: true });
      await this.writeStateFile(this.statePath, JSON.stringify(this.state, null, 2));
    });
    this.stateWriteChain = run.then(
      () => undefined,
      () => undefined,
    );
    return run;
  }
}

export class TierMigrationStatusStore {
  private readonly statePath: string;
  private state: TierMigrationStatusSnapshot = structuredClone(DEFAULT_TIER_MIGRATION_STATUS);

  constructor(memoryDir: string) {
    this.statePath = path.join(memoryDir, "state", "tier-migration-status.json");
  }

  async load(): Promise<void> {
    try {
      const raw = await readFile(this.statePath, "utf-8");
      const parsed = JSON.parse(raw) as Partial<TierMigrationStatusSnapshot> | null;
      if (!parsed || typeof parsed !== "object") {
        this.state = structuredClone(DEFAULT_TIER_MIGRATION_STATUS);
        return;
      }
      const totals = parsed.totals && typeof parsed.totals === "object"
        ? parsed.totals
        : DEFAULT_TIER_MIGRATION_STATUS.totals;
      this.state = {
        updatedAt:
          typeof parsed.updatedAt === "string" && parsed.updatedAt.length > 0
            ? parsed.updatedAt
            : DEFAULT_TIER_MIGRATION_STATUS.updatedAt,
        lastCycle:
          parsed.lastCycle && typeof parsed.lastCycle === "object"
            ? (parsed.lastCycle as TierMigrationCycleSummary)
            : null,
        totals: {
          cycles: typeof totals.cycles === "number" && Number.isFinite(totals.cycles) ? totals.cycles : 0,
          scanned: typeof totals.scanned === "number" && Number.isFinite(totals.scanned) ? totals.scanned : 0,
          migrated: typeof totals.migrated === "number" && Number.isFinite(totals.migrated) ? totals.migrated : 0,
          promoted: typeof totals.promoted === "number" && Number.isFinite(totals.promoted) ? totals.promoted : 0,
          demoted: typeof totals.demoted === "number" && Number.isFinite(totals.demoted) ? totals.demoted : 0,
          errors: typeof totals.errors === "number" && Number.isFinite(totals.errors) ? totals.errors : 0,
        },
      };
    } catch {
      this.state = structuredClone(DEFAULT_TIER_MIGRATION_STATUS);
    }
  }

  get(): TierMigrationStatusSnapshot {
    return {
      updatedAt: this.state.updatedAt,
      lastCycle: this.state.lastCycle ? { ...this.state.lastCycle } : null,
      totals: { ...this.state.totals },
    };
  }

  async recordCycle(summary: TierMigrationCycleSummary): Promise<void> {
    const now = new Date().toISOString();
    const migratedDelta = summary.dryRun ? 0 : Math.max(0, summary.migrated);
    const promotedDelta = summary.dryRun ? 0 : Math.max(0, summary.promoted);
    const demotedDelta = summary.dryRun ? 0 : Math.max(0, summary.demoted);
    const next: TierMigrationStatusSnapshot = {
      updatedAt: now,
      lastCycle: { ...summary },
      totals: {
        cycles: this.state.totals.cycles + 1,
        scanned: this.state.totals.scanned + Math.max(0, summary.scanned),
        migrated: this.state.totals.migrated + migratedDelta,
        promoted: this.state.totals.promoted + promotedDelta,
        demoted: this.state.totals.demoted + demotedDelta,
        errors: this.state.totals.errors + Math.max(0, summary.errorCount ?? 0),
      },
    };
    this.state = next;
    try {
      await mkdir(path.dirname(this.statePath), { recursive: true });
      await writeFile(this.statePath, JSON.stringify(next, null, 2), "utf-8");
    } catch (err) {
      log.debug(`tier migration status write failed: ${err}`);
    }
  }
}


/**
 * Per-session bounded history of recent recall memory-id sets, used ONLY by
 * handle resolution (issue #1582). Distinct from {@link LastRecallStore} —
 * that keeps ONE last snapshot per session; this keeps a small ring (depth N)
 * of the memory-id arrays a session has recalled, newest first, so a handle
 * cited in a later turn still resolves even after a newer recall displaced the
 * "last" snapshot.
 *
 * Deliberately lightweight: stores only `string[]` per entry (no full
 * snapshot), capped at `depth` per session and 50 sessions total (rule 27
 * slice/cap guards). Misses are acceptable and tagged at resolution time.
 */
export class RecallHandleHistoryStore {
  private readonly statePath: string;
  private readonly writeStateFile: StateFileWriter;
  private state: Record<string, Array<{ at: string; ids: string[] }>> = {};
  private writeChain: Promise<void> = Promise.resolve();
  private readonly maxDepth: number;

  constructor(memoryDir: string, options: { writeStateFile?: StateFileWriter; maxDepth?: number } = {}) {
    this.statePath = path.join(memoryDir, "state", "handle_history.json");
    this.writeStateFile =
      options.writeStateFile ??
      (async (filePath, content) => {
        await writeFileAtomically(filePath, content);
      });
    this.maxDepth =
      typeof options.maxDepth === "number" && Number.isFinite(options.maxDepth)
        ? Math.max(1, Math.min(50, Math.floor(options.maxDepth)))
        : 5;
  }

  async load(): Promise<void> {
    try {
      const raw = await readFile(this.statePath, "utf-8");
      const parsed = JSON.parse(raw);
      if (parsed && typeof parsed === "object" && !Array.isArray(parsed)) {
        const next: Record<string, Array<{ at: string; ids: string[] }>> = {};
        for (const [sessionKey, entries] of Object.entries(parsed)) {
          if (isUnsafeStateKey(sessionKey)) continue;
          if (!Array.isArray(entries)) continue;
          next[sessionKey] = entries;
        }
        this.state = next;
      }
    } catch {
      this.state = {};
    }
  }

  /**
   * Record one recall's admitted memory ids for a session, newest first.
   * The ring is capped at {@link maxDepth}; older entries drop off the tail.
   */
  async record(sessionKey: string, memoryIds: readonly string[]): Promise<void> {
    if (!sessionKey || isUnsafeStateKey(sessionKey)) return;
    const ids = memoryIds.filter((id): id is string => typeof id === "string" && id.length > 0);
    const entry = { at: new Date().toISOString(), ids };
    const prior = this.state[sessionKey] ?? [];
    const next = [entry, ...prior].slice(0, this.maxDepth);
    this.state[sessionKey] = next;
    this.capSessions();
    try {
      await this.flush();
    } catch (err) {
      log.debug(`recall handle history write failed: ${err}`);
    }
  }

  /**
   * Return the memory-id arrays for a session, newest first, capped at `depth`.
   * Empty array when the session has no recorded history.
   */
  recent(sessionKey: string, depth: number = this.maxDepth): Array<readonly string[]> {
    if (isUnsafeStateKey(sessionKey)) return [];
    const entries = this.state[sessionKey];
    if (!entries || entries.length === 0) return [];
    const limit = Math.max(0, Math.min(depth, entries.length));
    return entries.slice(0, limit).map((e) => e.ids);
  }

  /** Test seam: drop all history (used by the corpus-scan hygiene test). */
  clearForTest(): void {
    this.state = {};
  }

  private capSessions(): void {
    const keys = Object.keys(this.state);
    if (keys.length <= 50) return;
    const ordered = keys
      .map((k) => ({ k, at: this.state[k]?.[0]?.at ?? "" }))
      .sort((a, b) => b.at.localeCompare(a.at));
    for (const doomed of ordered.slice(50)) {
      delete this.state[doomed.k];
    }
  }

  private flush(): Promise<void> {
    const run = this.writeChain.catch(() => undefined).then(async () => {
      await mkdir(path.dirname(this.statePath), { recursive: true });
      await this.writeStateFile(this.statePath, JSON.stringify(this.state, null, 2));
    });
    this.writeChain = run.then(() => undefined, () => undefined);
    return run;
  }
}

/**
 * recall-handles.ts — injection-time memory handles (issue #1582).
 *
 * Every injected memory gets a stable short handle — `[m:4f2a]` — so a user
 * (or the agent) can react to ONE specific memory in-band ("[m:4f2a] is
 * stale", thumbs-down, "correct that") without a context switch to a CLI or
 * console. The handle is derived from the memory **id** (never the content),
 * so it is stable across edits/versioning.
 *
 * This module is PURE — no I/O, no side effects, no state. It owns:
 *   - {@link handleFor} — deterministic 4-hex handle from a memory id.
 *   - {@link renderHandle} / {@link renderHandlesForInjection} — render the
 *     `[m:xxxx]` token for one memory (or a whole injection set, extending to
 *     6 chars on intra-injection collision).
 *   - {@link parseHandles} — extract handle tokens from prose.
 *   - {@link normalizeHandle} / {@link isHandleToken} — classify a string.
 *   - {@link resolveHandle} — map a handle back to a memory id against the
 *     session's recent recall snapshots (hit / not-found / ambiguous).
 *
 * Design rules honored (issue #1582 design + pitfalls):
 *   - Handles are derived from the id only — never hashed with content, never
 *     persisted into memory files or rawContent (rule 23). Rendering happens
 *     at injection time only.
 *   - Resolution is per-session and snapshot-scoped — there is NEVER a global
 *     handle→id map (collision space too small globally, leaks across
 *     principals — rule 42). Misses are tagged, never guessed (rule 34/51).
 *   - The formatter is allocation-light: a string append at render time, no
 *     per-memory object churn, because it runs on every recall.
 */

import { createHash } from "node:crypto";

/**
 * Default handle width in hex characters (4 → 65 536-handle space).
 * Per-injection sets are ~10–40 memories, so in-context collisions are
 * vanishingly rare; {@link renderHandlesForInjection} widens the colliding
 * member to {@link HANDLE_EXTENDED_WIDTH} when two ids in ONE injection would
 * collide.
 */
export const HANDLE_DEFAULT_WIDTH = 4;

/**
 * Width used to disambiguate two ids that collide at the default width within
 * a single injection. 6 hex chars → ~16 M-handle space, which is comfortably
 * beyond per-injection set sizes.
 */
export const HANDLE_EXTENDED_WIDTH = 6;

/** Minimum/maximum accepted hex widths for a rendered/parsed handle. */
export const HANDLE_MIN_WIDTH = 4;
export const HANDLE_MAX_WIDTH = 8;

/**
 * Regex matching a rendered handle token anywhere in prose: `[m:` followed by
 * 4–8 lowercase hex chars and a closing `]`. Malformed tokens (`[m:xyz!]`,
 * `[m:abc]` with uppercase, missing bracket) are intentionally NOT matched.
 * Used by {@link parseHandles} and the sanitizer.
 */
export const HANDLE_REGEX = /\[m:[0-9a-f]{4,8}\]/g;

/**
 * Memory ids are `<category>-<timestamp>-<suffix>` (e.g. `fact-1770469224307-eelr`,
 * `artifact-...`, `reasoning_trace-...`, plus parent-`-chunk-N` variants). The
 * category segment allows underscores because `MemoryCategory` includes
 * `reasoning_trace` (codex review); bare names (`Widget`) still fail. Entity
 * reconstructions and other non-memory `.md` rows use bare names (`Widget`)
 * that must NOT receive a handle — citing one would resolve to a basename no
 * storage can load. This pattern gates handle rendering/recording to plausible
 * memory ids only (issue #1582, codex review).
 */
export const MEMORY_ID_PATTERN = /^[a-z][a-z0-9_]*-\d+-[a-z0-9-]+$/;

/**
 * Derive the deterministic handle hex for a memory id at a given width.
 *
 * `handleFor(id) === handleFor(id)` always, and `handleFor(id, w)` is a prefix
 * of `handleFor(id, w+1)` (both slice the same sha256 hex digest), so widening
 * for collision-disambiguation never changes the shorter prefix.
 *
 * @param memoryId  Stable memory id (e.g. `fact-1770469224307-eelr`).
 * @param width     Hex width. Defaults to {@link HANDLE_DEFAULT_WIDTH}.
 *                   Clamped to [4, 8]; the digest has 64 hex chars available.
 */
export function handleFor(memoryId: string, width: number = HANDLE_DEFAULT_WIDTH): string {
  const w = clampWidth(width);
  return createHash("sha256").update(memoryId).digest("hex").slice(0, w);
}

function clampWidth(width: number): number {
  if (!Number.isFinite(width)) return HANDLE_DEFAULT_WIDTH;
  return Math.min(HANDLE_MAX_WIDTH, Math.max(HANDLE_MIN_WIDTH, Math.floor(width)));
}

/**
 * Render the `[m:xxxx]` token for one memory id. Width override is for the
 * collision-extension path in {@link renderHandlesForInjection}; callers that
 * render a single handle in isolation should omit it.
 */
export function renderHandle(memoryId: string, widthOverride?: number): string {
  return `[m:${handleFor(memoryId, widthOverride ?? HANDLE_DEFAULT_WIDTH)}]`;
}

/**
 * Append a handle to a memory line, allocation-light. When `widthOverride` is
 * omitted the default-width handle is used; pass the widened width from
 * {@link renderHandlesForInjection} for a colliding member.
 *
 *   appendHandle("API rate limit is 1000 rpm.", "fact-1-abc")
 *   // → "API rate limit is 1000 rpm. [m:4f2a]"
 */
export function appendHandle(line: string, memoryId: string, widthOverride?: number): string {
  const handle = renderHandle(memoryId, widthOverride);
  // Single trailing space before the handle; collapse a double space if the
  // line already ended in whitespace so output stays clean.
  const trimmed = line.replace(/\s+$/, "");
  return `${trimmed} ${handle}`;
}

/**
 * Result of {@link renderHandlesForInjection}: for each memory id, the width
 * used (default 4, or 6 when widened to break an intra-injection collision)
 * and the rendered token. Ordered for stable iteration.
 */
export interface InjectionHandleEntry {
  memoryId: string;
  width: number;
  handle: string;
}

/**
 * Build handles for a whole injection set, widening to 6 chars when two ids
 * collide at the default width within THIS set (so each rendered token is
 * unique in context). Idempotent for the same input.
 *
 * The collision case is vanishingly rare (~10–40 memories per injection), but
 * widening guarantees a user can always point at exactly one memory in-band.
 */
export function renderHandlesForInjection(
  memoryIds: readonly string[],
): InjectionHandleEntry[] {
  // Group ids by their default-width handle so every member of a 4-char
  // collision group widens to 6 together — not just the later one. Widening
  // only the second id would leave the first rendering a 4-char token whose
  // resolution is ambiguous against the group (codex review).
  const idsByDefaultHandle = new Map<string, string[]>();
  for (const memoryId of memoryIds) {
    if (!memoryId) continue;
    const defaultHandle = handleFor(memoryId, HANDLE_DEFAULT_WIDTH);
    const group = idsByDefaultHandle.get(defaultHandle);
    if (group) group.push(memoryId);
    else idsByDefaultHandle.set(defaultHandle, [memoryId]);
  }
  const entries: InjectionHandleEntry[] = [];
  for (const memoryId of memoryIds) {
    if (!memoryId) continue;
    const defaultHandle = handleFor(memoryId, HANDLE_DEFAULT_WIDTH);
    const group = idsByDefaultHandle.get(defaultHandle) ?? [memoryId];
    const width = group.length > 1 ? HANDLE_EXTENDED_WIDTH : HANDLE_DEFAULT_WIDTH;
    entries.push({ memoryId, width, handle: `[m:${handleFor(memoryId, width)}]` });
  }
  // Reconciliation pass: if two DIFFERENT ids still produce the same rendered
  // token at their assigned width — the pathological case where they also
  // collide at the extended 6-char width — widen ALL members of the collision
  // group together, never just the later one. Leaving the first at 6 chars
  // while widening the second to 7 makes the first token resolve ambiguously
  // (both ids match at width 6). Iterate until no collision remains or every
  // member reaches HANDLE_MAX_WIDTH (codex review).
  let widened = true;
  while (widened) {
    widened = false;
    const tokenToIndices = new Map<string, number[]>();
    for (let i = 0; i < entries.length; i++) {
      const token = entries[i]!.handle;
      const arr = tokenToIndices.get(token);
      if (arr) arr.push(i);
      else tokenToIndices.set(token, [i]);
    }
    for (const indices of tokenToIndices.values()) {
      if (indices.length < 2) continue;
      const uniqueIds = new Set(indices.map((idx) => entries[idx]!.memoryId));
      if (uniqueIds.size < 2) continue; // same id listed twice — same handle is fine
      // Only continue widening if at least one entry has room to grow.
      // When every member has reached HANDLE_MAX_WIDTH the collision is
      // irreducible (two ids with identical sha256 8-char prefixes —
      // astronomically unlikely for real data); stop to avoid an infinite loop.
      let anyWidened = false;
      for (const idx of indices) {
        const entry = entries[idx]!;
        if (entry.width >= HANDLE_MAX_WIDTH) continue;
        entry.width += 1;
        entry.handle = `[m:${handleFor(entry.memoryId, entry.width)}]`;
        anyWidened = true;
      }
      if (anyWidened) widened = true;
    }
  }
  return entries;
}

/**
 * Build a `resultIndex → handle` map for a QMD result set. Returns an empty
 * map when handles are disabled or no result carries a handle-eligible memory
 * id. Extracted from the orchestrator's `formatQmdResults` so the rendering
 * logic lives in the pure handles module, not the god file (issue #1582,
 * rule 4).
 *
 * Only real memory ids (matching {@link MEMORY_ID_PATTERN}) are handle-eligible;
 * entity reconstructions and other non-memory `.md` rows get no handle.
 *
 * @param results  QMD search results (each has a `path` like `…/fact-x.md`).
 * @param enabled  Whether handle rendering is on. The caller gates on both the
 *                  config flag and session-key availability — handles rendered
 *                  without a session key can never be resolved, so they must
 *                  not be shown (cursor review of #1582).
 */
export function buildHandleIndexForResults(
  results: readonly { path: string }[],
  enabled: boolean,
): Map<number, string> {
  if (!enabled) return new Map();
  const ids: string[] = [];
  const idIndexByResult: Array<number | null> = results.map((r) => {
    const match = r.path.match(/([^/]+)\.md$/);
    if (!match) return null;
    const candidate = match[1] as string;
    if (!MEMORY_ID_PATTERN.test(candidate)) return null;
    ids.push(candidate);
    return ids.length - 1;
  });
  const entries = renderHandlesForInjection(ids);
  const handleByIndex = new Map<number, string>();
  results.forEach((_r, i) => {
    const idIndex = idIndexByResult[i];
    if (idIndex === null) return;
    const entry = entries[idIndex];
    if (entry) handleByIndex.set(i, entry.handle);
  });
  return handleByIndex;
}

/**
 * Extract every handle token from prose, in order of appearance. Returns the
 * full rendered tokens (e.g. `[m:4f2a]`) so callers can locate them in text.
 * Malformed tokens are ignored. Duplicates are preserved (a user may cite the
 * same memory twice).
 *
 *   parseHandles("see [m:4f2a] (also [m:1b9e]) — not [m:xyz!]")
 *   // → ["[m:4f2a]", "[m:1b9e]"]
 */
export function parseHandles(text: string): string[] {
  if (typeof text !== "string" || text.length === 0) return [];
  const out: string[] = [];
  // Reset lastIndex because HANDLE_REGEX is /g and may be reused.
  HANDLE_REGEX.lastIndex = 0;
  let match: RegExpExecArray | null;
  while ((match = HANDLE_REGEX.exec(text)) !== null) {
    out.push(match[0]);
  }
  return out;
}

/**
 * Strip every handle token from text, collapsing the spacing it introduced.
 * Used by the sanitizer so handles observed back into the pipeline never
 * become memory content (issue #1582 hygiene §2).
 *
 *   stripHandles("API limit 1000 rpm. [m:4f2a]") → "API limit 1000 rpm."
 */
export function stripHandles(text: string): string {
  if (typeof text !== "string" || text.length === 0) return text;
  // Remove the token and the single preceding space that {@link appendHandle}
  // added, then tidy any double space left behind.
  // \\s? (not \\s*): the renderer appends exactly one preceding space, and a
  // bounded quantifier avoids the polynomial-ReDoS flag on uncontrolled input.
  // A stray run of spaces is collapsed by the following line.
  return text
    .replace(/\s?\[m:[0-9a-f]{4,8}\]/g, "")
    .replace(/[ \t]{2,}/g, " ")
    .replace(/[ \t]+$/g, "");
}

/**
 * Normalize a handle token (or bare hex) to its lowercase hex core, or `null`
 * when the input is not a handle. Accepts both the rendered `[m:4f2a]` form
 * and the bare `m:4f2a` / `4f2a` form a user might type.
 *
 *   normalizeHandle("[m:4f2a]") → "4f2a"
 *   normalizeHandle("m:4f2a")   → "4f2a"
 *   normalizeHandle("4f2a")     → "4f2a"
 *   normalizeHandle("fact-1")   → null
 */
export function normalizeHandle(token: string): string | null {
  if (typeof token !== "string" || token.length === 0) return null;
  const trimmed = token.trim().toLowerCase();
  // [m:4f2a]
  const bracketed = /^\[m:([0-9a-f]{4,8})\]$/.exec(trimmed);
  if (bracketed) return bracketed[1] ?? null;
  // m:4f2a
  const prefixed = /^m:([0-9a-f]{4,8})$/.exec(trimmed);
  if (prefixed) return prefixed[1] ?? null;
  // bare 4f2a — only treat as a handle when it is pure hex in the width range,
  // so we don't mis-classify a real memory id that happens to be 4 hex chars.
  const bare = /^([0-9a-f]{4,8})$/.exec(trimmed);
  if (bare) return bare[1] ?? null;
  return null;
}

/**
 * Whether a string looks like a handle token (rendered or bare). Cheaper
 * boolean form of {@link normalizeHandle} for callers that only need to branch.
 */
export function isHandleToken(token: string): boolean {
  return normalizeHandle(token) !== null;
}

/**
 * A flattened id-or-handle reference: either a raw memory id or the hex core
 * of a handle. {@link resolveMemoryIdOrHandle} produces this so the snapshot
 * lookup only runs for actual handles.
 */
export interface ParsedIdOrHandle {
  /** The original reference as supplied by the caller. */
  raw: string;
  /** `true` when `raw` is a handle that still needs snapshot resolution. */
  isHandle: boolean;
  /** For a handle, its hex core; for a raw id, the id itself. */
  value: string;
}

/**
 * Classify a single caller reference as id-or-handle.
 */
export function parseIdOrHandle(ref: string): ParsedIdOrHandle {
  const hex = normalizeHandle(ref);
  if (hex !== null) {
    return { raw: ref, isHandle: true, value: hex };
  }
  return { raw: ref, isHandle: false, value: ref };
}

/**
 * A flattened view of the memory-id sets a session has recently recalled.
 * Each entry is one past recall's admitted memory ids (newest first).
 * Resolution never sees raw {@link LastRecallSnapshot}s — callers flatten to
 * this so the pure resolver has no dependency on the snapshot type.
 */
export interface RecallSnapshotIds {
  memoryIds: readonly string[];
}

/**
 * Result of resolving a handle against recent recall snapshots.
 * - `{ ok: true, memoryId }` — exactly one match within the lookback window.
 * - `{ ok: false, reason: "not_found" }` — no memory id produced this handle
 *   within the window (misses are acceptable and tagged, never guessed).
 * - `{ ok: false, reason: "ambiguous", candidates }` — two DIFFERENT memory
 *   ids in the window collide on the same handle; the caller must disambiguate
 *   (rule 34/51: never guess).
 */
export type ResolveHandleResult =
  | { ok: true; memoryId: string }
  | { ok: false; reason: "not_found" }
  | { ok: false; reason: "ambiguous"; candidates: string[] };

/**
 * Resolve a handle hex (or a rendered token / bare form) to its memory id
 * against the session's recent recall snapshots.
 *
 * @param handle     A handle token, bare hex, or `m:hex` form.
 * @param snapshots  Recent recall snapshots for the session, newest first.
 *                   Only the first `depth` entries are searched.
 * @param depth      How many snapshots (newest-first) to search. Defaults to
 *                   {@link DEFAULT_HANDLE_SNAPSHOT_DEPTH}.
 */
export function resolveHandle(
  handle: string,
  snapshots: readonly RecallSnapshotIds[],
  depth: number = DEFAULT_HANDLE_SNAPSHOT_DEPTH,
): ResolveHandleResult {
  const hex = normalizeHandle(handle);
  if (hex === null) {
    return { ok: false, reason: "not_found" };
  }
  // A handle resolves when a memory id's handle is a PREFIX of `hex` (handles
  // widened to 6 chars for collision still match their own 4-char core, and a
  // user citing the short form must still resolve the widened memory).
  const width = hex.length;
  const limit = Math.max(0, Math.min(depth, snapshots.length));
  const matches = new Set<string>();
  for (let i = 0; i < limit; i += 1) {
    const snap = snapshots[i];
    if (!snap) continue;
    for (const memoryId of snap.memoryIds) {
      if (!memoryId) continue;
      if (handleFor(memoryId, width) === hex) {
        matches.add(memoryId);
      }
    }
  }
  if (matches.size === 0) {
    return { ok: false, reason: "not_found" };
  }
  if (matches.size === 1) {
    return { ok: true, memoryId: matches.values().next().value as string };
  }
  return { ok: false, reason: "ambiguous", candidates: [...matches] };
}

/**
 * Default snapshot lookback depth for handle resolution (issue #1582 config
 * `recall.handleSnapshotDepth`). Older-than-N snapshots are not searched and a
 * miss is tagged rather than widening the window.
 */
export const DEFAULT_HANDLE_SNAPSHOT_DEPTH = 5;

import path from "node:path";
import { mkdir, open, readFile, stat, unlink, writeFile } from "node:fs/promises";
import { log } from "./logger.js";
import type { SessionObserverBandConfig } from "./types.js";
import { cloneDefaultSessionObserverBands } from "./session-observer-bands.js";

interface SessionObserverCursor {
  sessionKey: string;
  cursorBytes: number;
  cursorTokens: number;
  lastObservedAt: string;
  lastTriggeredAt?: string;
  lastResetAt?: string;
}

interface SessionObserverPersistedState {
  version: 2;
  sessions: Record<string, SessionObserverCursor>;
}

export interface SessionObservationInput {
  sessionKey: string;
  totalBytes: number;
  totalTokens: number;
  observedAt?: string;
}

export interface SessionObservationDecision {
  triggered: boolean;
  deltaBytes: number;
  deltaTokens: number;
  band: SessionObserverBandConfig;
  reason?: "threshold" | "debounced" | "baseline";
}

function sanitizeNonNegativeInt(value: number): number {
  if (!Number.isFinite(value)) return 0;
  return Math.max(0, Math.floor(value));
}

function parseIsoMs(value?: string): number {
  if (!value) return 0;
  const ms = Date.parse(value);
  return Number.isFinite(ms) ? ms : 0;
}

function mergeSessionCursor(
  existing: SessionObserverCursor,
  incoming: SessionObserverCursor,
): SessionObserverCursor {
  const existingObservedMs = parseIsoMs(existing.lastObservedAt);
  const incomingObservedMs = parseIsoMs(incoming.lastObservedAt);
  const existingTriggeredMs = parseIsoMs(existing.lastTriggeredAt);
  const incomingTriggeredMs = parseIsoMs(incoming.lastTriggeredAt);
  const existingResetMs = parseIsoMs(existing.lastResetAt);
  const incomingResetMs = parseIsoMs(incoming.lastResetAt);

  const observedAt =
    incomingObservedMs >= existingObservedMs ? incoming.lastObservedAt : existing.lastObservedAt;
  const triggeredAt =
    incomingTriggeredMs >= existingTriggeredMs ? incoming.lastTriggeredAt : existing.lastTriggeredAt;

  // Preserve monotonic cursor progression except for explicit reset observations.
  const incomingIsNewer = incomingObservedMs >= existingObservedMs;
  const incomingHasNewerReset = incomingResetMs > existingResetMs;
  const allowIncomingReset = incomingIsNewer && incomingHasNewerReset;
  const keepExistingReset =
    existingResetMs > incomingResetMs && existingObservedMs >= incomingObservedMs;

  let cursorBytes = Math.max(
    sanitizeNonNegativeInt(existing.cursorBytes),
    sanitizeNonNegativeInt(incoming.cursorBytes),
  );
  let cursorTokens = Math.max(
    sanitizeNonNegativeInt(existing.cursorTokens),
    sanitizeNonNegativeInt(incoming.cursorTokens),
  );
  if (keepExistingReset) {
    cursorBytes = sanitizeNonNegativeInt(existing.cursorBytes);
    cursorTokens = sanitizeNonNegativeInt(existing.cursorTokens);
  } else if (allowIncomingReset) {
    cursorBytes = sanitizeNonNegativeInt(incoming.cursorBytes);
    cursorTokens = sanitizeNonNegativeInt(incoming.cursorTokens);
  }

  return {
    sessionKey: existing.sessionKey,
    cursorBytes,
    cursorTokens,
    lastObservedAt: observedAt,
    lastTriggeredAt: triggeredAt,
    lastResetAt:
      incomingResetMs >= existingResetMs ? incoming.lastResetAt : existing.lastResetAt,
  };
}

export function normalizeObserverBands(
  bands: SessionObserverBandConfig[],
): SessionObserverBandConfig[] {
  const normalized = bands
    .map((band) => ({
      maxBytes: sanitizeNonNegativeInt(band.maxBytes),
      triggerDeltaBytes: sanitizeNonNegativeInt(band.triggerDeltaBytes),
      triggerDeltaTokens: sanitizeNonNegativeInt(band.triggerDeltaTokens),
    }))
    .filter((band) => band.maxBytes > 0)
    .sort((a, b) => a.maxBytes - b.maxBytes);

  if (normalized.length === 0) {
    return cloneDefaultSessionObserverBands();
  }

  const last = normalized[normalized.length - 1];
  if (last && last.maxBytes < 1_000_000_000) {
    normalized.push({
      maxBytes: 1_000_000_000,
      triggerDeltaBytes: last.triggerDeltaBytes,
      triggerDeltaTokens: last.triggerDeltaTokens,
    });
  }
  return normalized;
}

export class SessionObserverState {
  private readonly statePath: string;
  private readonly lockPath: string;
  private readonly lockStaleMs = 120_000;
  private readonly debounceMs: number;
  private readonly bands: SessionObserverBandConfig[];
  private sessions = new Map<string, SessionObserverCursor>();
  private saveQueue: Promise<void> = Promise.resolve();

  private async readPersistedState(): Promise<SessionObserverPersistedState | null> {
    try {
      const raw = await readFile(this.statePath, "utf-8");
      const parsed = JSON.parse(raw) as SessionObserverPersistedState;
      if (parsed?.version !== 2 || !parsed.sessions || typeof parsed.sessions !== "object") {
        return null;
      }
      return parsed;
    } catch {
      return null;
    }
  }

  private normalizePersistedSessions(
    sessions: Record<string, SessionObserverCursor>,
  ): Map<string, SessionObserverCursor> {
    const next = new Map<string, SessionObserverCursor>();
    for (const [sessionKey, value] of Object.entries(sessions)) {
      if (!value || typeof value !== "object") continue;
      next.set(sessionKey, {
        sessionKey,
        cursorBytes: sanitizeNonNegativeInt(value.cursorBytes),
        cursorTokens: sanitizeNonNegativeInt(value.cursorTokens),
        lastObservedAt:
          typeof value.lastObservedAt === "string" ? value.lastObservedAt : new Date(0).toISOString(),
        lastTriggeredAt: typeof value.lastTriggeredAt === "string" ? value.lastTriggeredAt : undefined,
        lastResetAt: typeof value.lastResetAt === "string" ? value.lastResetAt : undefined,
      });
    }
    return next;
  }

  constructor(opts: {
    memoryDir: string;
    debounceMs: number;
    bands: SessionObserverBandConfig[];
  }) {
    this.statePath = path.join(opts.memoryDir, "state", "session-observer-state.json");
    this.lockPath = path.join(opts.memoryDir, "state", "session-observer-state.lock");
    this.debounceMs = Math.max(0, Math.floor(opts.debounceMs));
    this.bands = normalizeObserverBands(opts.bands);
  }

  private async withSaveLock(fn: () => Promise<void>): Promise<void> {
    await mkdir(path.dirname(this.lockPath), { recursive: true });
    for (let attempt = 0; attempt < 80; attempt++) {
      try {
        const handle = await open(this.lockPath, "wx");
        try {
          await fn();
        } finally {
          await handle.close();
          await unlink(this.lockPath).catch(() => {});
        }
        return;
      } catch (err: any) {
        if (err?.code !== "EEXIST") throw err;
        try {
          const lockInfo = await stat(this.lockPath);
          if (Date.now() - lockInfo.mtimeMs > this.lockStaleMs) {
            await unlink(this.lockPath).catch(() => {});
            continue;
          }
        } catch {
          // Lock might have been released between EEXIST and stat/read.
        }
        await new Promise((resolve) => setTimeout(resolve, 25));
      }
    }
    const error = new Error("session observer save lock timeout");
    log.debug(error.message);
    throw error;
  }

  async load(): Promise<void> {
    const parsed = await this.readPersistedState();
    if (!parsed) {
      this.sessions.clear();
      return;
    }
    this.sessions = this.normalizePersistedSessions(parsed.sessions);
  }

  async save(): Promise<void> {
    await this.withSaveLock(async () => {
      const merged = await this.readMergedSessions();
      this.sessions = merged;

      await this.writeSessions(merged);
    });
  }

  private async readMergedSessions(): Promise<Map<string, SessionObserverCursor>> {
    const merged = new Map<string, SessionObserverCursor>();
    const persisted = await this.readPersistedState();
    if (persisted) {
      for (const [key, value] of this.normalizePersistedSessions(persisted.sessions).entries()) {
        merged.set(key, value);
      }
    }
    for (const [key, current] of this.sessions.entries()) {
      const existing = merged.get(key);
      if (!existing) {
        merged.set(key, current);
        continue;
      }
      merged.set(key, mergeSessionCursor(existing, current));
    }
    return merged;
  }

  private async writeSessions(sessionsMap: Map<string, SessionObserverCursor>): Promise<void> {
    const sessions = Object.create(null) as Record<string, SessionObserverCursor>;
    for (const [key, value] of sessionsMap.entries()) {
      sessions[key] = value;
    }
    const payload: SessionObserverPersistedState = { version: 2, sessions };
    await mkdir(path.dirname(this.statePath), { recursive: true });
    await writeFile(this.statePath, JSON.stringify(payload, null, 2), "utf-8");
  }

  private enqueueObservation(
    input: SessionObservationInput,
  ): Promise<SessionObservationDecision> {
    const operation = this.saveQueue
      .catch(() => undefined)
      .then(() => this.observeWithSaveLock(input));
    this.saveQueue = operation.then(
      () => undefined,
      () => undefined,
    );
    return operation;
  }

  private bandForTotalBytes(totalBytes: number): SessionObserverBandConfig {
    const bytes = sanitizeNonNegativeInt(totalBytes);
    for (const band of this.bands) {
      if (bytes <= band.maxBytes) return band;
    }
    return this.bands[this.bands.length - 1];
  }

  async observe(input: SessionObservationInput): Promise<SessionObservationDecision> {
    return this.enqueueObservation(input);
  }

  private async observeWithSaveLock(
    input: SessionObservationInput,
  ): Promise<SessionObservationDecision> {
    let decision: SessionObservationDecision | undefined;
    await this.withSaveLock(async () => {
      const localExisting = this.sessions.get(input.sessionKey);
      const sessions = await this.readMergedSessions();
      decision = await this.observeMerged(
        input,
        sessions,
        localExisting ? { ...localExisting } : undefined,
      );
    });
    if (!decision) {
      throw new Error("session observer decision was not computed");
    }
    return decision;
  }

  private async observeMerged(
    input: SessionObservationInput,
    sessions: Map<string, SessionObserverCursor>,
    localExisting?: SessionObserverCursor,
  ): Promise<SessionObservationDecision> {
    const nowIso = input.observedAt ?? new Date().toISOString();
    const totalBytes = sanitizeNonNegativeInt(input.totalBytes);
    const totalTokens = sanitizeNonNegativeInt(input.totalTokens);
    const band = this.bandForTotalBytes(totalBytes);

    const existing = sessions.get(input.sessionKey);
    if (!existing) {
      sessions.set(input.sessionKey, {
        sessionKey: input.sessionKey,
        cursorBytes: totalBytes,
        cursorTokens: totalTokens,
        lastObservedAt: nowIso,
      });
      this.sessions = sessions;
      await this.writeSessions(sessions);
      return {
        triggered: false,
        deltaBytes: 0,
        deltaTokens: 0,
        band,
        reason: "baseline",
      };
    }

    const session = { ...existing };
    const observedMs = parseIsoMs(nowIso);
    const existingObservedMs = parseIsoMs(session.lastObservedAt);
    const existingResetMs = parseIsoMs(session.lastResetAt);
    if (existingResetMs > 0 && observedMs < existingResetMs) {
      this.sessions = sessions;
      return { triggered: false, deltaBytes: 0, deltaTokens: 0, band, reason: "baseline" };
    }

    if (totalBytes < session.cursorBytes || totalTokens < session.cursorTokens) {
      const localSawReset =
        localExisting !== undefined
        && (totalBytes < sanitizeNonNegativeInt(localExisting.cursorBytes)
          || totalTokens < sanitizeNonNegativeInt(localExisting.cursorTokens));
      const canApplyReset = localSawReset && observedMs >= existingObservedMs;

      if (canApplyReset) {
        session.cursorBytes = totalBytes;
        session.cursorTokens = totalTokens;
        session.lastObservedAt = nowIso;
        session.lastResetAt = nowIso;
      } else if (observedMs >= existingObservedMs) {
        session.lastObservedAt = nowIso;
      }
      sessions.set(input.sessionKey, session);
      this.sessions = sessions;
      await this.writeSessions(sessions);
      return { triggered: false, deltaBytes: 0, deltaTokens: 0, band, reason: "baseline" };
    }

    const deltaBytes = totalBytes - session.cursorBytes;
    const deltaTokens = totalTokens - session.cursorTokens;
    const crossedThreshold =
      (band.triggerDeltaBytes > 0 && deltaBytes >= band.triggerDeltaBytes)
      || (band.triggerDeltaTokens > 0 && deltaTokens >= band.triggerDeltaTokens);
    session.lastObservedAt = nowIso;

    if (!crossedThreshold) {
      const unchanged = deltaBytes === 0 && deltaTokens === 0;
      if (!unchanged) {
        sessions.set(input.sessionKey, session);
        this.sessions = sessions;
        await this.writeSessions(sessions);
      } else {
        this.sessions = sessions;
      }
      return {
        triggered: false,
        deltaBytes,
        deltaTokens,
        band,
      };
    }

    const nowMs = Date.parse(nowIso);
    const lastTriggeredMs = session.lastTriggeredAt ? Date.parse(session.lastTriggeredAt) : NaN;
    const withinDebounce =
      Number.isFinite(lastTriggeredMs) && nowMs - lastTriggeredMs < this.debounceMs;

    if (withinDebounce) {
      sessions.set(input.sessionKey, session);
      this.sessions = sessions;
      await this.writeSessions(sessions);
      return {
        triggered: false,
        deltaBytes,
        deltaTokens,
        band,
        reason: "debounced",
      };
    }

    session.lastTriggeredAt = nowIso;
    session.cursorBytes = totalBytes;
    session.cursorTokens = totalTokens;
    sessions.set(input.sessionKey, session);
    this.sessions = sessions;
    await this.writeSessions(sessions);
    return {
      triggered: true,
      deltaBytes,
      deltaTokens,
      band,
      reason: "threshold",
    };
  }
}

import { createHash } from "node:crypto";
import { lstat, realpath } from "node:fs/promises";
import path from "node:path";

export function encodeStoragePathSegment(value: string, fallback = "unknown"): string {
  const raw = value.length > 0 ? value : fallback;
  try {
    return encodeURIComponent(raw).replaceAll(".", "%2E");
  } catch {
    return `encoded-${storagePathHash(raw)}`;
  }
}

export function storagePathHash(value: string): string {
  return createHash("sha256").update(value).digest("hex").slice(0, 16);
}

export function encodeStoragePathSegmentWithHash(value: string, fallback = "unknown"): string {
  const raw = value.length > 0 ? value : fallback;
  return `${encodeStoragePathSegment(value, fallback)}--${storagePathHash(raw)}`;
}

export function isSafeLegacyPathSegment(value: string): boolean {
  return (
    value.length > 0 &&
    value !== "." &&
    value !== ".." &&
    !value.includes("/") &&
    !value.includes("\\")
  );
}

const DAILY_FILE_DATE = /^(\d{4}-\d{2}-\d{2})\.jsonl$/;

/**
 * True when `relativePath` is a daily partition, `<type>/<channel>/YYYY-MM-DD.jsonl`,
 * named for a UTC date before `minDate`. Daily transcript files are named for the
 * date they were written on, and an entry is written at or after its own
 * timestamp, so such a file cannot hold an entry stamped on or after `minDate`.
 * Only that three-component layout is a daily partition: a legacy
 * `<type>/<channelId>.jsonl` or a root-level file can have a date-shaped name
 * (a date-shaped channel id) without being one, so it is never reported as older
 * and callers always read it.
 */
export function isDailyFileDatedBefore(relativePath: string, minDate: string | undefined): boolean {
  const parts = relativePath.split(path.sep);
  const fileDate = parts.length === 3 ? DAILY_FILE_DATE.exec(parts[2])?.[1] : undefined;
  return minDate !== undefined && fileDate !== undefined && fileDate < minDate;
}

export function isPathInsideStorageRoot(rootAbs: string, targetAbs: string): boolean {
  const rel = path.relative(rootAbs, targetAbs);
  if (rel === "") return true;
  if (rel === "..") return false;
  if (rel.startsWith(`..${path.sep}`)) return false;
  if (path.isAbsolute(rel)) return false;
  return true;
}

export function resolvePathInsideStorageRoot(
  root: string,
  ...parts: string[]
): string {
  const rootAbs = path.resolve(root);
  const targetAbs = path.resolve(rootAbs, ...parts);
  if (!isPathInsideStorageRoot(rootAbs, targetAbs)) {
    throw new Error(`resolved storage path escapes root: ${targetAbs}`);
  }
  return targetAbs;
}

async function assertNoSymlinkInExistingPath(
  rootAbs: string,
  targetAbs: string,
): Promise<void> {
  let current = rootAbs;
  while (current !== path.dirname(current)) {
    const stat = await lstat(current).catch(() => null);
    if (stat !== null) {
      if (stat.isSymbolicLink()) {
        throw new Error(`storage path must not pass through a symlink: ${current}`);
      }
      break;
    }
    current = path.dirname(current);
  }

  const relative = path.relative(rootAbs, targetAbs);
  if (relative === "") return;

  current = rootAbs;
  for (const segment of relative.split(path.sep)) {
    current = path.join(current, segment);
    const stat = await lstat(current).catch(() => null);
    if (stat === null) return;
    if (stat.isSymbolicLink()) {
      throw new Error(`storage path must not pass through a symlink: ${current}`);
    }
  }
}

async function assertRealPathInsideStorageRoot(
  rootAbs: string,
  targetAbs: string,
): Promise<void> {
  const rootReal = await resolvePossiblyMissingRealPath(rootAbs);
  const targetReal = await resolvePossiblyMissingRealPath(targetAbs);
  if (!isPathInsideStorageRoot(rootReal, targetReal)) {
    throw new Error(`resolved storage path escapes root: ${targetAbs}`);
  }
}

async function resolvePossiblyMissingRealPath(absPath: string): Promise<string> {
  let existing = absPath;
  const suffix: string[] = [];
  while (existing !== path.dirname(existing)) {
    const stat = await lstat(existing).catch(() => null);
    if (stat !== null) break;
    suffix.unshift(path.basename(existing));
    existing = path.dirname(existing);
  }
  const existingReal = await realpath(existing).catch(() => existing);
  return suffix.length > 0 ? path.join(existingReal, ...suffix) : existingReal;
}

export async function resolveSafeStoragePath(
  root: string,
  ...parts: string[]
): Promise<string> {
  const rootAbs = path.resolve(root);
  const targetAbs = resolvePathInsideStorageRoot(rootAbs, ...parts);
  await assertNoSymlinkInExistingPath(rootAbs, targetAbs);
  await assertRealPathInsideStorageRoot(rootAbs, targetAbs);
  return targetAbs;
}

