/**
 * Rebuildable namespace catalog (issue #1499).
 *
 * Purpose: a downstream, rebuildable metadata index that lets Remnic ENUMERATE
 * the configured and dynamically-created namespaces that exist or should be
 * maintained. Filesystem memory remains the single source of truth; the catalog
 * is derived metadata and can always be reconstructed from disk.
 *
 * Storage format: `<memoryDir>/state/namespaces.jsonl` — an append-and-compact
 * JSON-lines log. We chose this over per-namespace sidecar files because:
 *   - touches (markRead/markWrite/markMaintenance) are cheap single appends;
 *   - it is naturally audit-friendly (the raw log preserves touch history);
 *   - a single file makes enumeration trivial (no directory walk per call);
 *   - last-record-wins compaction folds the log into the current state on read,
 *     and `rebuildFromDisk` rewrites it atomically (temp file + rename).
 *
 * SECURITY:
 *   - The catalog stores ONLY metadata (namespace names, kinds, timestamps,
 *     resolved storage dirs). It NEVER holds raw memory content or secrets.
 *   - Catalog presence grants NO authorization. Read/write access still flows
 *     through the namespace policies in `principal.ts`; this module never makes
 *     an access decision.
 *   - All namespace tokens are validated with `isSafeRouteNamespace` (except the
 *     configured default namespace, which is exempt at the routing layer) and
 *     every storage dir is contained under `<memoryDir>/namespaces`.
 *   - `rebuildFromDisk` rejects/reports symlinked roots that escape the memory
 *     root rather than trusting them.
 *
 * LIFECYCLE: catalog write failures must NEVER crash a primary memory op.
 * Callers should wrap touch calls in try/catch (or rely on the internal
 * failure-tolerant append). The internal serialized write chain recovers from
 * rejection so one failed append cannot poison subsequent writes.
 */

export type NamespaceKind =
  | "default"
  | "shared"
  | "project"
  | "branch"
  | "team-project"
  | "explicit";

export type NamespaceDiscoverySource = "config" | "write" | "read" | "scan" | "migration";

export interface NamespaceRecord {
  namespace: string;
  identityToken: string;
  kind: NamespaceKind;
  createdAt: string;
  lastReadAt?: string;
  lastWriteAt?: string;
  lastMaintenanceAt?: Record<string, string>;
  storageDir: string;
  discoveredBy: NamespaceDiscoverySource;
}

export interface NamespaceCatalogFilter {
  kind?: NamespaceKind;
  discoveredBy?: NamespaceDiscoverySource;
  /** Only include namespaces written since this instant (inclusive lower bound). */
  writtenSince?: Date;
}

/** Out-parameter a catalog read fills in when it could not see the whole catalog. */
interface CatalogReadHealth {
  incomplete?: string;
  /**
   * Set ONLY when the file was read to the end and malformed rows were skipped. An unreadable
   * catalog also sets `incomplete` but never `malformed`: its empty result is not the catalog's
   * content, so nothing may be rewritten from it.
   */
  malformed?: boolean;
  /**
   * The raw malformed lines the read skipped, in file order. Only filled when `malformed` is
   * set; the repair quarantines exactly these into its sidecar before rewriting.
   */
  malformedLines?: string[];
}

export interface NamespaceCatalogReadOptions {
  /**
   * Called when the read could not see the whole catalog (an unreadable file, or malformed rows
   * that were skipped). The records that were readable are still returned. A catalog that was
   * never written is normal and does not call this.
   */
  onIncomplete?: (reason: string) => void;
}

export interface NamespaceTouchMetadata {
  discoveredBy?: NamespaceDiscoverySource;
  kind?: NamespaceKind;
  /** Explicit storage dir (when the caller already resolved it). */
  storageDir?: string;
  /** Override the touch timestamp (mainly for tests / migration replay). */
  at?: Date;
}

export interface NamespaceCatalogSkippedRoot {
  token: string;
  reason: "symlink" | "escape" | "unsafe" | "error";
  detail?: string;
}

export interface NamespaceCatalogRebuildResult {
  dryRun: boolean;
  records: NamespaceRecord[];
  /** Roots reported as ambiguous/unsafe rather than silently misclassified. */
  skipped: NamespaceCatalogSkippedRoot[];
  /**
   * Whether the rebuild actually rewrote the on-disk catalog (round 6, codex P2
   * / cursor Medium — NBn3n/NBsGG). `false` for a dry-run, AND for an `--apply`
   * that could NOT acquire the cross-process rebuild lock within the bounded wait
   * (it ran compute-only to avoid clobbering a concurrent lock holder). Callers
   * (CLI) must NOT report unqualified success when `applied` is false for a
   * non-dry-run — the catalog was left unchanged and a retry is needed.
   */
  applied: boolean;
}

const NAMESPACE_KINDS: readonly NamespaceKind[] = [
  "default",
  "shared",
  "project",
  "branch",
  "team-project",
  "explicit",
];

const NAMESPACE_DISCOVERY_SOURCES: readonly NamespaceDiscoverySource[] = [
  "config",
  "write",
  "read",
  "scan",
  "migration",
];

const CATALOG_FILE = "namespaces.jsonl";
const STATE_DIR = "state";
const REBUILD_LOCK_FILE = "namespaces.rebuild.lock";
// A held lock older than this is treated as stale (a crashed rebuild) and broken.
const REBUILD_LOCK_STALE_MS = 30_000;
// Bounded acquisition: poll briefly, then proceed best-effort rather than block
// a CLI rebuild forever behind a busy gateway.
const REBUILD_LOCK_MAX_WAIT_MS = 5_000;
const REBUILD_LOCK_POLL_MS = 50;
// Heartbeat: while a rebuild holds the lock it refreshes the lock file's mtime
// on this interval so a long (>STALE_MS) scan is NOT mistaken for a crashed
// holder and broken out from under it (round 5, cursor/codex Medium/P2). Must be
// comfortably below STALE_MS so at least a couple of beats land per stale window.
const REBUILD_LOCK_HEARTBEAT_MS = 10_000;

// Children that indicate a directory holds Remnic memory data (used for legacy
// default-root detection and to skip empty/non-data roots during rebuild).
//
// `state` is included to MATCH the router's storage-presence check
// (`NamespaceStorageRouter` counts the `state` runtime child via
// `includeRuntimeState: true`). Without it (round 3, cursor Medium) a namespace
// the router actively resolves because it has only a `state/` dir would be
// treated as absent by rebuild and vanish from the catalog after `--apply`.
const MEMORY_DATA_CHILDREN = [
  ...ALL_CATEGORY_DIRS,
  "entities",
  "artifacts",
  "identity",
  "config",
  "summaries",
  "profile.md",
  "state",
] as const;

function isCatalogEnabled(config: PluginConfig): boolean {
  // Inert unless namespaces are enabled. namespaceCatalogEnabled defaults to
  // true (undefined => enabled) but is only honored when namespacesEnabled.
  if (resolveNamespaceCapabilities(config).namespaces !== true) return false;
  return (config as { namespaceCatalogEnabled?: boolean }).namespaceCatalogEnabled !== false;
}

// Marker children that MUST be a regular file rather than a directory. Everything
// else in MEMORY_DATA_CHILDREN is a category/data DIRECTORY that downstream
// indexers (`scanMemoryDir`) read — and which they reject when it is a symlink or
// a non-directory. `profile.md` is the sole file marker.
const FILE_MEMORY_DATA_CHILDREN = new Set<string>(["profile.md"]);

type MemoryDataMarkerStatus =
  | { state: "absent" }
  | { state: "valid" }
  | { state: "invalid"; detail: string };

type MemoryDataRootStatus = {
  hasData: boolean;
  invalidMarker?: string;
};

/**
 * Inspect `child` under `rootDir` as a memory-data marker (NIw0F / PR #1506).
 * Existence alone is not enough: a bogus marker — e.g. `facts` as a symlink or a
 * regular file instead of a real directory — passes `lstat` but makes
 * `scanMemoryDir` throw on the symlinked/non-directory category root. Returning
 * a distinct `invalid` status lets root scans reject a namespace when ANY known
 * marker is malformed, even if a sibling marker such as `state/` is valid.
 */
async function inspectMemoryDataMarker(rootDir: string, child: string): Promise<MemoryDataMarkerStatus> {
  const childPath = path.join(rootDir, child);
  let entry;
  try {
    entry = await lstat(childPath);
  } catch (err) {
    return isNotFoundError(err)
      ? { state: "absent" }
      : { state: "invalid", detail: `${child}: ${err instanceof Error ? err.message : String(err)}` };
  }
  // Reject symlinked markers outright (scan parity — never follow them).
  if (entry.isSymbolicLink()) return { state: "invalid", detail: `${child}: symlink` };
  if (FILE_MEMORY_DATA_CHILDREN.has(child)) {
    // `profile.md` must be a regular file.
    return entry.isFile()
      ? { state: "valid" }
      : { state: "invalid", detail: `${child}: expected file` };
  }
  // Category/data markers must be real directories whose realpath stays inside
  // the namespace root (no escape via a symlinked ancestor).
  if (!entry.isDirectory()) return { state: "invalid", detail: `${child}: expected directory` };
  try {
    const rootReal = await realpath(rootDir);
    const childReal = await realpath(childPath);
    return isPathInside(rootReal, childReal)
      ? { state: "valid" }
      : { state: "invalid", detail: `${child}: escapes namespace root` };
  } catch (err) {
    return { state: "invalid", detail: `${child}: ${err instanceof Error ? err.message : String(err)}` };
  }
}

async function inspectMemoryDataRoot(rootDir: string): Promise<MemoryDataRootStatus> {
  let hasData = false;
  for (const child of MEMORY_DATA_CHILDREN) {
    const marker = await inspectMemoryDataMarker(rootDir, child);
    if (marker.state === "invalid") {
      return { hasData: false, invalidMarker: marker.detail };
    }
    if (marker.state === "valid") {
      hasData = true;
    }
  }
  return { hasData };
}

export async function hasMemoryData(rootDir: string): Promise<boolean> {
  return (await inspectMemoryDataRoot(rootDir)).hasData;
}

function isValidIsoTimestamp(value: string): boolean {
  const ms = Date.parse(value);
  return Number.isFinite(ms);
}

export function isNamespaceKind(value: unknown): value is NamespaceKind {
  return typeof value === "string" && (NAMESPACE_KINDS as readonly string[]).includes(value);
}

function isNamespaceDiscoverySource(value: unknown): value is NamespaceDiscoverySource {
  return typeof value === "string" && (NAMESPACE_DISCOVERY_SOURCES as readonly string[]).includes(value);
}

/**
 * Validate a JSONL line parsed value as a usable NamespaceRecord.
 * Rejects null / non-object / missing-field records (CLAUDE.md rule #18).
 * Persisted enum and timestamp fields are also validated here so a syntactically
 * valid but tampered/pre-fix line cannot surface impossible record states.
 */
function coerceRecord(value: unknown): NamespaceRecord | null {
  if (typeof value !== "object" || value === null) return null;
  const v = value as Record<string, unknown>;
  if (typeof v.namespace !== "string") return null;
  const namespace = normalizeNamespaceIdentity(v.namespace);
  if (namespace.length === 0) return null;
  if (typeof v.identityToken !== "string" || v.identityToken.length === 0) return null;
  const expectedIdentityToken = namespaceIdentityToken(namespace);
  if (v.identityToken !== expectedIdentityToken) return null;
  if (typeof v.storageDir !== "string" || v.storageDir.length === 0) return null;
  if (typeof v.createdAt !== "string" || v.createdAt.length === 0) return null;
  if (!isValidIsoTimestamp(v.createdAt)) return null;
  const kind = isNamespaceKind(v.kind) ? v.kind : "explicit";
  const discoveredBy =
    v.discoveredBy === undefined
      ? "scan"
      : isNamespaceDiscoverySource(v.discoveredBy)
        ? v.discoveredBy
        : null;
  if (!discoveredBy) return null;
  const record: NamespaceRecord = {
    namespace,
    identityToken: expectedIdentityToken,
    kind,
    createdAt: v.createdAt,
    storageDir: v.storageDir,
    discoveredBy,
  };
  if (typeof v.lastReadAt === "string" && isValidIsoTimestamp(v.lastReadAt)) {
    record.lastReadAt = v.lastReadAt;
  }
  if (typeof v.lastWriteAt === "string" && isValidIsoTimestamp(v.lastWriteAt)) {
    record.lastWriteAt = v.lastWriteAt;
  }
  if (v.lastMaintenanceAt && typeof v.lastMaintenanceAt === "object") {
    const out: Record<string, string> = {};
    for (const [k, val] of Object.entries(v.lastMaintenanceAt as Record<string, unknown>)) {
      if (typeof val === "string" && isValidIsoTimestamp(val)) out[k] = val;
    }
    if (Object.keys(out).length > 0) record.lastMaintenanceAt = out;
  }
  return record;
}

/** Later of two optional ISO timestamps (undefined-safe). */
function laterIso(a: string | undefined, b: string | undefined): string | undefined {
  if (!a) return b;
  if (!b) return a;
  const am = Date.parse(a);
  const bm = Date.parse(b);
  if (!Number.isFinite(am)) return b;
  if (!Number.isFinite(bm)) return a;
  return bm > am ? b : a;
}

/**
 * Fold the touch fields (lastReadAt / lastWriteAt / lastMaintenanceAt) from a
 * freshly re-read on-disk record into the rebuilt record, taking the LATER
 * timestamp per field (round 5 cross-process re-merge). Disk-derived fields
 * (storageDir, kind, discoveredBy, createdAt, principal hints) are owned by the
 * rebuilt record and left untouched — we only recover touch recency that a
 * concurrent (possibly cross-process) writer recorded after our initial load.
 */
export function mergeNewerTouchFields(base: NamespaceRecord, fresh: NamespaceRecord): NamespaceRecord {
  const merged: NamespaceRecord = { ...base };
  const lr = laterIso(base.lastReadAt, fresh.lastReadAt);
  if (lr) merged.lastReadAt = lr;
  const lw = laterIso(base.lastWriteAt, fresh.lastWriteAt);
  if (lw) merged.lastWriteAt = lw;
  if (base.lastMaintenanceAt || fresh.lastMaintenanceAt) {
    const jobs: Record<string, string> = { ...(base.lastMaintenanceAt ?? {}) };
    for (const [job, ts] of Object.entries(fresh.lastMaintenanceAt ?? {})) {
      const latest = laterIso(jobs[job], ts);
      if (latest) jobs[job] = latest;
    }
    if (Object.keys(jobs).length > 0) merged.lastMaintenanceAt = jobs;
  }
  return merged;
}

/**
 * Serialize a record with sorted keys (CLAUDE.md rule #38) so byte output is
 * stable across runs — required for idempotent rebuilds.
 */
function serializeRecord(record: NamespaceRecord): string {
  const ordered: Record<string, unknown> = {};
  const source = record as unknown as Record<string, unknown>;
  for (const key of Object.keys(source).sort()) {
    const value = source[key];
    if (value === undefined) continue;
    if (key === "lastMaintenanceAt" && value && typeof value === "object") {
      const sortedJobs: Record<string, string> = {};
      for (const jobKey of Object.keys(value as Record<string, string>).sort()) {
        sortedJobs[jobKey] = (value as Record<string, string>)[jobKey]!;
      }
      ordered[key] = sortedJobs;
      continue;
    }
    ordered[key] = value;
  }
  return JSON.stringify(ordered);
}

/**
 * Infer the namespace kind from its name/structure using the same conventions
 * as `coding-namespace.ts` (project-*, *-branch-*, team-*-project-*). Returns
 * `explicit` when no structural signal is present. The caller can override.
 */
function inferKind(namespace: string, config: PluginConfig): NamespaceKind {
  // Compare against NORMALIZED config names (NGnek, codex P2): the catalog seeds
  // normalized namespace identities, so a configured name with surrounding
  // whitespace (e.g. `sharedNamespace: "shared "`) must still classify the
  // normalized `"shared"` as `shared`, not fall through to `explicit`.
  if (namespace === normalizeNamespaceIdentity(config.defaultNamespace)) return "default";
  if (namespace === normalizeNamespaceIdentity(config.sharedNamespace)) return "shared";
  if (config.namespacePolicies.some((p) => normalizeNamespaceIdentity(p.name) === namespace)) {
    return "explicit";
  }
  // Branch overlays embed "-branch-" (project-<id>-branch-<name>).
  if (/-branch-|^project-[^-]+-branch-/.test(namespace) || namespace.includes("-branch-")) {
    return "branch";
  }
  // Team-project promotions are prefixed team-*-project-*.
  if (/^team-.*-project-/.test(namespace) || /^team-.*project-/.test(namespace)) {
    return "team-project";
  }
  // Project overlays are "project-*" or "<principal>-project-*".
  if (/^project-/.test(namespace) || /-project-/.test(namespace)) {
    return "project";
  }
  return "explicit";
}

interface CatalogFileIdentity {
  size: number;
  mtimeMs: number;
  ctimeMs: number;
  ino: number;
}

interface CompactedCatalogCache {
  identity: CatalogFileIdentity;
  records: Map<string, NamespaceRecord>;
  /** Why the read was incomplete (malformed rows), kept so a cache hit reports it too. */
  incomplete?: string;
}

export class NamespaceCatalog {
  private readonly memoryDir: string;
  private readonly stateDir: string;
  private readonly catalogPath: string;
  private readonly rebuildLockPath: string;
  // In-process serialization for catalog mutations (issue #1524 adoption).
  // Replaces the bespoke `writeChain` field: every touch/rebuild runs through
  // this serializer so a single failed section never poisons subsequent ones
  // (CLAUDE.md rule #40 — recovery is the util's contract, not re-implemented
  // here). Cross-process identity (the lock file's owner-uuid) is now per-CALL
  // inside the shared util, which is STRONGER than the previous per-instance
  // `lockOwnerId` — two calls on the SAME instance get different ids, so
  // neither mistakes the other's lock for self-held (round 6, codex P2 — NBsGP
  // invariant preserved and tightened).
  private readonly criticalSection = new MutationSerializer();
  private compactedCache: CompactedCatalogCache | undefined;
  // Test-only seam (round 7 — NEZkA): fires inside a touch's HELD-lock critical
  // section, after the lock is acquired but BEFORE the read→merge→append. A
  // deterministic concurrency test installs a hook here to widen the (otherwise
  // microscopic) window and prove that a cross-process rebuild CANNOT run its
  // load→rename while a touch holds the lock. Never set in production code.
  protected onTouchCriticalSectionForTest?: () => Promise<void>;
  // Test-only observation seam: fires only when the JSONL file is fully read.
  // Cached loads do not invoke it.
  protected onCatalogReadForTest?: () => void;
  // Test-only seam: fires after this process appends but before it stats the
  // file to refresh the cache identity.
  protected onAfterCatalogAppendForTest?: () => Promise<void>;
  // Test-only seam (round 7 — NEZkA): fires inside a mutating rebuild's HELD-lock
  // critical section, after the final cross-process re-merge `loadCompacted()` and
  // BEFORE the atomic `rename()`. This is the EXACT window in which a check-then-
  // append touch (the old bug) would clobber its append. A deterministic test
  // installs a hook here to attempt a cross-instance touch in this window and
  // assert the held mutex blocks it. Never set in production code.
  protected onRebuildBeforeRenameForTest?: () => Promise<void>;
  // Test-only seam (NFgCT, codex P2): fires AFTER the lockless disk scan but
  // BEFORE the rebuild acquires the cross-process file lock for its final
  // load→merge→rename window. A deterministic test installs a hook here to attempt
  // a cross-instance touch DURING the scan window and assert it is NOT blocked or
  // dropped — proving the scan no longer holds the mutex. Never set in production.
  protected onRebuildAfterScanForTest?: () => Promise<void>;
  // Test-only seam (NG7Bg, codex P2): fires inside `breakStaleRebuildLock` AFTER it
  // has judged the lock stale and captured its identity, but BEFORE the final
  // re-validation+unlink. A deterministic test installs a hook here to REPLACE the
  // lock file (a fresh holder created a new lock in the race window) and assert the
  // break is skipped — the replacement's active lock is not deleted. Never set in
  // production.
  protected onBeforeBreakStaleUnlinkForTest?: () => Promise<void>;

  // Normalized (trimmed) default namespace identity (NH-FH, cursor Medium).
  // Catalog records key namespaces by their NORMALIZED identity
  // (`normalizeNamespaceIdentity`), but several default-namespace exemptions and
  // memoryDir-ownership checks compared against the RAW `config.defaultNamespace`.
  // If the configured default name carries surrounding whitespace the record key
  // is trimmed while the comparison string is not, so the default row is
  // misclassified, dropped at read time, or given the wrong storage root. Compare
  // against this normalized form everywhere instead.
  private readonly defaultNamespaceIdentity: string;

  // Issue #1903 — touch-path performance knobs, resolved with the documented
  // defaults when an externally-built PluginConfig omits them (so a partial
  // config object still yields the production behavior). `0` is a real disable
  // switch for each and is preserved by `??` (0 is not null/undefined).
  private readonly compactBytesLimit: number;
  private readonly readCoalesceMs: number;
  private readonly writeCoalesceMs: number;
  // #3298 review: single-flight + backoff gate for the malformed-catalog repair.
  private readonly malformedRepairGate = new MalformedCatalogRepairGate();

  /** Test-only observability: how many repair attempts actually entered the gate. */
  get malformedRepairAttemptsForTest(): number {
    return this.malformedRepairGate.attemptCount;
  }

  // Size after the most recent auto-compaction (0 = none yet). Hysteresis for
  // maybeAutoCompact: a folded catalog that is itself above the limit (many
  // distinct namespaces) would otherwise be re-folded + re-rewritten on every
  // touch. We only compact again once the log has grown by >= one limit-worth
  // since the last compaction (#1903, Codex).
  private lastCompactedSize = 0;

  // Issue #1903 — per-(namespace, kind) coalescing buffer. Keyed `${kind}:${ns}`.
  // Holds the latest buffered timestamp/metadata for a pure-timestamp touch on
  // an already-known record; a `.unref()`'d timer flushes it once per window so
  // the append-only log does not grow one line per repeat touch. Semantically
  // observable touches (first sight, provenance/field change) bypass this buffer
  // and flush immediately (see `coalesceTouch`).
  private readonly pendingTouches = new Map<
    string,
    {
      namespace: string;
      kind: "read" | "write";
      metadata?: NamespaceTouchMetadata;
      at: Date;
      timer: NodeJS.Timeout;
    }
  >();

  constructor(private readonly config: PluginConfig) {
    this.memoryDir = config.memoryDir;
    this.stateDir = path.join(this.memoryDir, STATE_DIR);
    this.catalogPath = path.join(this.stateDir, CATALOG_FILE);
    this.rebuildLockPath = path.join(this.stateDir, REBUILD_LOCK_FILE);
    this.defaultNamespaceIdentity = normalizeNamespaceIdentity(config.defaultNamespace);
    this.compactBytesLimit = config.namespacesCatalogCompactBytes ?? 16 * 1024 * 1024;
    this.readCoalesceMs = config.namespacesCatalogReadTouchCoalesceMs ?? 60_000;
    this.writeCoalesceMs = config.namespacesCatalogWriteTouchCoalesceMs ?? 1_000;
  }

  /** Whether the catalog is active (namespaces enabled and catalog not opted out). */
  get enabled(): boolean {
    return isCatalogEnabled(this.config);
  }

  // ── Public enumeration API ──────────────────────────────────────────────

  private catalogReadBoundaryPort(): CatalogReadBoundaryPort {
    return {
      defaultNamespaceIdentity: this.defaultNamespaceIdentity,
      memoryDir: this.memoryDir,
      isContainedStorageDir: (candidate) => this.isContainedStorageDir(candidate),
      isStorageDirForNamespace: (namespace, candidate) => this.isStorageDirForNamespace(namespace, candidate),
      resolveSafeStorageDir: (namespace) => this.resolveSafeStorageDir(namespace),
    };
  }

  private loadSanitizedRecords(health?: CatalogReadHealth): Promise<NamespaceRecord[]> {
    return this.queueCritical(async () => {
      const records = await this.loadCompacted(false, health);
      const port = this.catalogReadBoundaryPort();
      const sanitized = await Promise.all(
        [...records.values()].map((r) => sanitizeRecordForRead(port, r)),
      );
      // Drop unsafe-namespace rows (sanitizer returned null) at the read boundary.
      // Then collapse duplicate root aliases so maintenance/QMD see exactly one
      // namespace owner for a physical storage root, matching rebuild ownership,
      // while preserving touch recency from every alias row.
      return dropDuplicateStorageRootAliases(
        port,
        sanitized.filter((r): r is NamespaceRecord => r !== null),
        this.config,
      );
    });
  }

  async listNamespaces(
    filter?: NamespaceCatalogFilter,
    options?: NamespaceCatalogReadOptions,
  ): Promise<NamespaceRecord[]> {
    if (!this.enabled) return [];
    const health: CatalogReadHealth = {};
    let out = await this.loadSanitizedRecords(health);
    if (health.incomplete !== undefined) {
      options?.onIncomplete?.(health.incomplete);
    }
    if (health.malformed === true) {
      // A permanently malformed row keeps every completion request owed until the catalog is
      // rewritten, so repair it now: fold the readable rows and rewrite the log without the bad
      // ones. Best-effort and fail-open like the size-triggered compaction. Only a read that
      // reached the end of the file may trigger it (see CatalogReadHealth.malformed).
      void this.malformedRepairGate.run(() => this.rewriteAfterIncompleteRead()).catch(() => undefined);
    }
    if (filter?.kind) out = out.filter((r) => r.kind === filter.kind);
    if (filter?.discoveredBy) out = out.filter((r) => r.discoveredBy === filter.discoveredBy);
    if (filter?.writtenSince) {
      const sinceMs = filter.writtenSince.getTime();
      out = out.filter((r) => {
        if (!r.lastWriteAt) return false;
        const ms = Date.parse(r.lastWriteAt);
        return Number.isFinite(ms) && ms >= sinceMs;
      });
    }
    // Stable sort: namespace asc, identityToken as deterministic tiebreaker
    // (CLAUDE.md rule #19 — comparator returns 0 only for truly-equal items).
    return out.sort((a, b) => {
      const byName = a.namespace.localeCompare(b.namespace);
      if (byName !== 0) return byName;
      return a.identityToken.localeCompare(b.identityToken);
    });
  }

  async getNamespaceRecord(namespace: string): Promise<NamespaceRecord | null> {
    if (!this.enabled) return null;
    const ns = normalizeNamespaceIdentity(namespace);
    return (await this.loadSanitizedRecords()).find((record) => record.namespace === ns) ?? null;
  }

  // ── Touch API (cheap, failure-tolerant) ─────────────────────────────────

  async markRead(namespace: string, metadata?: NamespaceTouchMetadata): Promise<void> {
    await this.coalesceTouch(namespace, "read", metadata);
  }

  async markWrite(namespace: string, metadata?: NamespaceTouchMetadata): Promise<void> {
    await this.coalesceTouch(namespace, "write", metadata);
  }

  /**
   * Route a read/write touch through the per-(namespace, kind) coalescing buffer
   * (issue #1903). A touch flushes IMMEDIATELY (bypassing the buffer) whenever it
   * is semantically observable to an in-process reader — first sight of the
   * namespace, a `config`→`write` provenance upgrade, the first time a touch
   * field is set (so `listNamespaces({ writtenSince })` and record presence stay
   * correct), or a change to `kind`/`principal`/`projectId`/`branch`/
   * `parentNamespace`. A pure timestamp refresh on an already-known record is
   * DEFERRED and coalesced: the newest buffered `at`/metadata wins and a single
   * `touch` runs when the window elapses (or on `flushPendingTouches`). Window
   * `0` skips the buffer entirely (the pre-#1903 immediate-append behavior).
   * Best-effort: coalescing decisions read only the warm `compactedCache`, never
   * forcing a disk parse; a cold cache flushes immediately (and re-warms it).
   */
  private async coalesceTouch(
    namespace: string,
    kind: "read" | "write",
    metadata?: NamespaceTouchMetadata,
  ): Promise<void> {
    if (!this.enabled) return;
    const window = kind === "read" ? this.readCoalesceMs : this.writeCoalesceMs;
    if (window <= 0) {
      await this.touch(namespace, kind, metadata);
      return;
    }
    // Validate up front so an unsafe namespace rejects deterministically, exactly
    // as the immediate-append path does (touch validates too).
    const ns = this.validateNamespace(namespace);
    const cached = this.compactedCache?.records.get(ns);
    if (cached === undefined || this.touchMustFlushImmediately(kind, metadata, cached)) {
      // Semantically observable in-process → flush now (also warms the cache).
      // Any older buffered touch for this key is now redundant (this newer touch
      // updates the same field with a newer timestamp): drop it so its stale
      // timer cannot regress the timestamp after this flush.
      const stale = this.pendingTouches.get(`${kind}:${ns}`);
      if (stale) {
        clearTimeout(stale.timer);
        this.pendingTouches.delete(`${kind}:${ns}`);
      }
      await this.touch(namespace, kind, metadata);
      return;
    }
    // Pure timestamp refresh on a known record → coalesce within a FIXED window.
    const key = `${kind}:${ns}`;
    const at = metadata?.at ?? new Date();
    const existing = this.pendingTouches.get(key);
    if (existing) {
      // Keep the ORIGINAL timer and only refresh the buffered payload (#1903,
      // Codex). Re-arming on every touch would make this a debounce that never
      // flushes under continuous traffic (e.g. a sustained import), leaving
      // lastWriteAt stale and writtenSince/maintenance consumers blind to an
      // actively-written namespace. With a fixed window, each window flushes on
      // schedule carrying the newest buffered timestamp.
      existing.metadata = metadata;
      existing.at = at;
      return;
    }
    // Cap at Node's maximum setTimeout delay (2^31-1 ms ≈ 24.8 days). Values
    // above that are clamped by Node to 1ms, which would append almost every
    // touch and recreate the churn this coalescing exists to prevent (#1903, Codex).
    const safeWindow = Math.min(window, 2_147_483_647);
    const timer = setTimeout(() => {
      void this.flushPendingTouch(key);
    }, safeWindow);
    timer.unref();
    this.pendingTouches.set(key, { namespace: ns, kind, metadata, at, timer });
  }

  /**
   * Whether a read/write touch on an EXISTING cached record must flush
   * immediately rather than coalesce. Only pure timestamp refreshes (the value
   * returns false) are safe to defer.
   */
  private touchMustFlushImmediately(
    kind: "read" | "write",
    metadata: NamespaceTouchMetadata | undefined,
    cached: NamespaceRecord,
  ): boolean {
    // A write upgrading a config pre-registration to "write" changes the
    // discoveredBy filter result — must be observable at once (~:1261).
    if (kind === "write" && cached.discoveredBy === "config") return true;
    // The first time a touch field is set makes the namespace newly match
    // presence/`writtenSince` reads, so it must not be deferred.
    if (kind === "write" && cached.lastWriteAt === undefined) return true;
    if (kind === "read" && cached.lastReadAt === undefined) return true;
    if (!metadata) return false;
    if (metadata.kind !== undefined && metadata.kind !== cached.kind) return true;
    // A changed storageDir repoints routing/containment for this namespace —
    // must be observable at once, not held stale by the coalesce window (#1903, Cursor).
    if (metadata.storageDir !== undefined && metadata.storageDir !== cached.storageDir) return true;
    return false;
  }

  /** Fire a single buffered touch when its coalescing window elapses. */
  private async flushPendingTouch(key: string): Promise<void> {
    const pending = this.pendingTouches.get(key);
    if (!pending) return;
    this.pendingTouches.delete(key);
    clearTimeout(pending.timer);
    await this.touch(pending.namespace, pending.kind, { ...pending.metadata, at: pending.at }).catch(
      () => undefined,
    );
  }

  /**
   * Flush every buffered coalesced touch now (issue #1903). Called from the
   * router/orchestrator shutdown hook so a long-lived host does not drop
   * buffered read/write timestamps on teardown, and by tests to make coalesced
   * touches deterministically observable. Best-effort: a failed flush never
   * throws (each touch is `.catch()`-guarded).
   */
  async flushPendingTouches(): Promise<void> {
    const pending = [...this.pendingTouches.values()];
    this.pendingTouches.clear();
    for (const p of pending) {
      clearTimeout(p.timer);
      await this.touch(p.namespace, p.kind, { ...p.metadata, at: p.at }).catch(() => undefined);
    }
  }

  async markMaintenance(namespace: string, jobName: string, at?: Date): Promise<void> {
    if (typeof jobName !== "string" || jobName.trim().length === 0) {
      throw new Error("markMaintenance requires a non-empty jobName");
    }
    await this.touch(namespace, "maintenance", { at }, jobName.trim());
  }

  /**
   * Register namespaces known purely from config (default, shared, explicit
   * policies). Source `config`. Cheap and idempotent.
   */
  async registerConfiguredNamespaces(): Promise<void> {
    if (!this.enabled) return;
    const names = new Set<string>([
      this.config.defaultNamespace,
      this.config.sharedNamespace,
      ...this.config.namespacePolicies.map((p) => p.name),
    ]);
    for (const ns of names) {
      if (!ns) continue;
      // Skip unsafe configured names (e.g. a `sharedNamespace`/policy name like
      // `../evil`) consistently with `rebuildFromDisk` (round 6, cursor Low —
      // NBn3w). `register`→`validateNamespace` THROWS on unsafe tokens; without
      // this guard one bad name would abort registration of all the rest. The
      // default namespace is exempt (it may be a non-route literal). Each call is
      // also wrapped so a single failure never blocks the remaining names.
      // `names` carries RAW config values, so normalize before the default-exempt
      // check — a whitespace-padded default must still be recognized (NH-FH).
      if (normalizeNamespaceIdentity(ns) !== this.defaultNamespaceIdentity && !isSafeRouteNamespace(ns)) {
        continue;
      }
      try {
        await this.register(ns, { discoveredBy: "config" });
      } catch {
        // Best-effort: a single bad/unsafe name must not abort the batch.
      }
    }
  }

  /**
   * Register a namespace whose storage was just resolved by the router. Used as
   * the router's integration hook (`discoveredBy: config`). Storage dir is
   * provided so we do not re-resolve it. Failure-tolerant. Returns whether the
   * registration actually APPENDED (round 6, codex P2 — NEFoX), so the router's
   * resolve-hook dedup only marks a namespace notified when it truly persisted —
   * a dropped append (disabled catalog or rebuild-lock-timeout drop) returns
   * `false` and is retried on the next resolve.
   */
  async registerResolved(namespace: string, storageDir: string): Promise<boolean> {
    if (!this.enabled) return false;
    return this.register(namespace, { discoveredBy: "config", storageDir });
  }

  /**
   * Generic register/touch without changing read/write timestamps unless the
   * source implies it. Validates the namespace and resolves a storage dir.
   * Returns whether the touch actually appended.
   */
  private async register(namespace: string, metadata: NamespaceTouchMetadata): Promise<boolean> {
    return this.touch(namespace, "register", metadata);
  }

  private validateNamespace(namespace: string): string {
    const ns = normalizeNamespaceIdentity(namespace);
    if (ns.length === 0) throw new Error("empty namespace");
    // The configured default namespace is exempt from isSafeRouteNamespace at
    // the routing layer; honor the same exemption here, but everything still
    // resolves through the contained storage-dir helper below.
    if (ns !== this.defaultNamespaceIdentity && !isSafeRouteNamespace(ns)) {
      throw new Error(`unsafe namespace: ${ns}`);
    }
    return ns;
  }

  /**
   * Resolve the on-disk storage dir for a namespace WITHOUT trusting caller
   * input. The default namespace may use the legacy memoryDir root; everything
   * else lives under `<memoryDir>/namespaces/<token>`. Containment is enforced
   * by rejecting separators/parent-refs in the token.
   */
  private resolveStorageDir(namespace: string): string {
    if (normalizeNamespaceIdentity(namespace) === this.defaultNamespaceIdentity) {
      // Default may resolve to the legacy memoryDir root OR a tokenized dir; we
      // report memoryDir here as the canonical default root for the catalog.
      // rebuildFromDisk refines this when a tokenized default dir holds data.
      return this.memoryDir;
    }
    const token = namespaceIdentityToken(namespace);
    return this.namespaceTokenDir(token);
  }

  private namespaceTokenDir(token: string): string {
    if (
      token.length === 0 ||
      token.includes("/") ||
      token.includes("\\") ||
      token.includes("..") ||
      path.isAbsolute(token)
    ) {
      throw new Error(`unsafe namespace token: ${token}`);
    }
    return path.join(this.memoryDir, "namespaces", token);
  }

  /**
   * Whether a candidate storage dir is LEXICALLY contained: it is either the
   * legacy default root (`memoryDir`) or a strict descendant of
   * `<memoryDir>/namespaces/`. The router legitimately resolves a namespace to
   * EITHER the tokenized dir or a legacy raw-name dir under `namespaces/`, so we
   * accept any contained child rather than a single exact token path. This is a
   * pure string check — symlink escape is checked separately via realpath.
   */
  private isLexicallyContained(candidate: string): boolean {
    const resolved = path.resolve(candidate);
    if (resolved === path.resolve(this.memoryDir)) return true;
    const nsBase = path.resolve(path.join(this.memoryDir, "namespaces"));
    const rel = path.relative(nsBase, resolved);
    // Must be a strict descendant of namespaces/ (non-empty, no parent escape).
    return rel.length > 0 && !rel.startsWith("..") && !path.isAbsolute(rel);
  }

  /**
   * Whether a candidate storage dir satisfies the catalog containment contract,
   * including SYMLINK-escape rejection (round 5, codex P2). A lexically-contained
   * path that is actually a symlink to an outside directory would let maintenance
   * or QMD follow it outside `memoryDir`. We mirror `rebuildFromDisk`'s posture:
   * the path must be lexically contained AND, if it exists on disk, neither the
   * path itself a symlink nor its realpath escaping the memory root. Non-existent
   * paths pass the realpath stage (nothing to follow yet) but still must be
   * lexically contained.
   */
  private async isContainedStorageDir(candidate: string): Promise<boolean> {
    if (!this.isLexicallyContained(candidate)) return false;
    // The default/legacy memoryDir root is trusted as-is.
    if (path.resolve(candidate) === path.resolve(this.memoryDir)) return true;
    let memoryReal: string;
    try {
      memoryReal = await realpath(this.memoryDir);
    } catch {
      memoryReal = path.resolve(this.memoryDir);
    }
    // Reject a candidate beneath any SYMLINKED ancestor (codex NVuq5): even when
    // the symlink currently resolves back inside memoryDir, the disk scanner
    // rejects such a root, and a later retarget of the link would let
    // maintenance/QMD follow the persisted path outside memoryDir. Mirror the
    // scanner so touch/config seeding cannot persist a root under a symlinked
    // namespace ancestor (the leaf itself is symlink-checked below).
    if (await this.hasSymlinkedAncestor(candidate)) return false;
    try {
      const stat = await lstat(candidate);
      if (stat.isSymbolicLink()) return false;
      // Reject an EXISTING non-directory root (NF21i, codex P2; CLAUDE.md rule
      // #24). A regular file (or socket/fifo) at `<memoryDir>/namespaces/<token>`
      // is lexically contained and its realpath stays inside memoryDir, so the
      // realpath check below would ACCEPT it — but a storage root must be a
      // directory. Recording a file as a namespace root yields a broken install
      // that only fails later when maintenance/QMD/mkdir treat it as a dir. The
      // disk scan already skips non-directory entries; mirror that here so every
      // containment consumer (resolve/touch/fallback/live-recheck) agrees.
      if (!stat.isDirectory()) return false;
    } catch {
      // The leaf does not exist yet. Lexical containment is NOT sufficient: an
      // EXISTING ancestor (e.g. `<memoryDir>/namespaces`) could be a symlink to
      // outside memoryDir, so a future mkdir/maintenance/QMD op would follow the
      // persisted root outside the root (round 6, codex P2 — NDo79). Verify the
      // nearest EXISTING ancestor's realpath still resolves inside memoryDir.
      return this.isNearestExistingAncestorContained(candidate, memoryReal);
    }
    try {
      const real = await realpath(candidate);
      return isPathInside(memoryReal, real);
    } catch {
      return false;
    }
  }

  /**
   * Reject a candidate whose path crosses a SYMLINKED ancestor strictly between
   * memoryDir and the leaf (codex NVuq5). `realpath`-based containment accepts a
   * symlinked `<memoryDir>/namespaces` that currently resolves back inside
   * memoryDir, but the disk scanner rejects such a root and a later retarget would
   * escape the memory tree — so refuse it here too. The leaf itself is
   * symlink-checked by the caller; this walks only the intermediate ancestors.
   */
  private async hasSymlinkedAncestor(candidate: string): Promise<boolean> {
    const stopAt = path.resolve(this.memoryDir);
    let dir = path.dirname(path.resolve(candidate));
    const root = path.parse(dir).root;
    while (dir !== stopAt && dir !== root && dir !== path.dirname(dir)) {
      try {
        if ((await lstat(dir)).isSymbolicLink()) return true;
      } catch {
        // Ancestor does not exist yet — it cannot be a symlink; keep walking up.
      }
      dir = path.dirname(dir);
    }
    return false;
  }

  /**
   * Walk up from a not-yet-existing candidate to the nearest ancestor that exists
   * on disk and verify its realpath stays inside `memoryReal` (round 6, codex P2
   * — NDo79). Rejects a non-existent leaf whose existing parent chain escapes
   * memoryDir via a symlink. Stops at memoryDir's resolved root.
   *
   * The nearest existing ancestor must also be a DIRECTORY (NHIdt, codex P2): if
   * an existing parent such as `<memoryDir>/namespaces` is a regular FILE (or
   * socket/fifo), `realpath(parent)` still succeeds and resolves inside memoryDir,
   * so a containment-only check would ACCEPT a leaf that can never be created — you
   * cannot mkdir a child under a file. We `lstat` the nearest existing ancestor and
   * reject when it is not a directory, mirroring the leaf non-directory rejection
   * (NF21i) and the disk scan, so every containment consumer agrees.
   */
  private async isNearestExistingAncestorContained(
    candidate: string,
    memoryReal: string,
  ): Promise<boolean> {
    let dir = path.resolve(candidate);
    const root = path.parse(dir).root;
    for (;;) {
      const parent = path.dirname(dir);
      // Reached the filesystem root without finding an existing ancestor.
      if (parent === dir || dir === root) return false;
      let real: string;
      try {
        real = await realpath(parent);
      } catch {
        // Parent does not exist yet either — keep walking up.
        dir = parent;
        continue;
      }
      // The nearest EXISTING ancestor must resolve inside the memory root...
      if (!(isPathInside(memoryReal, real) || real === memoryReal)) return false;
      // ...AND be a directory: a non-directory ancestor (e.g. a file occupying
      // `namespaces`) cannot hold the not-yet-created leaf (NHIdt).
      try {
        const stat = await lstat(real);
        return stat.isDirectory();
      } catch {
        // The ancestor vanished between realpath and lstat — treat as not usable.
        return false;
      }
    }
  }

  /**
   * Resolve the storage dir to persist for a touch, validating any caller-
   * provided `metadata.storageDir` against the catalog containment contract
   * (round 4 + round 5, codex P2). `markWrite`/`registerResolved` accept an
   * explicit storageDir, but persisting it verbatim would let a bad hook or
   * external consumer write an arbitrary path — including one outside `memoryDir`
   * or a symlink that escapes it — into the catalog, handing maintenance/QMD an
   * unsafe root. We accept an explicit (or previously-stored) dir ONLY when it
   * stays contained under memoryDir (lexically AND via realpath); otherwise we
   * drop it and fall back to the trusted resolved dir.
   */
  private async resolveTouchStorageDir(
    namespace: string,
    explicit: string | undefined,
    existingDir: string | undefined,
  ): Promise<string> {
    // An explicit storageDir is accepted ONLY when it is both contained AND
    // actually belongs to THIS namespace (round 6, codex P2 — NDATT). Containment
    // alone let a caller pass another namespace's tree (e.g.
    // `markWrite("project-a", { storageDir: ".../namespaces/<project-b-token>" })`)
    // or `memoryDir` for a non-default namespace; `listNamespaces()` would then
    // tell maintenance/QMD that `project-a` lives in another namespace's (or the
    // default) tree — a cross-namespace root confusion. We reject a mismatched
    // explicit root and fall back to the namespace's own resolved root.
    if (
      explicit !== undefined &&
      (await this.isContainedStorageDir(explicit)) &&
      (await this.isStorageDirForNamespace(namespace, explicit))
    ) {
      return explicit;
    }
    // Don't let a record poisoned by a pre-fix out-of-containment write keep an
    // unsafe dir alive across touches — only preserve a contained existing dir
    // that also belongs to this namespace.
    if (
      existingDir !== undefined &&
      (await this.isContainedStorageDir(existingDir)) &&
      (await this.isStorageDirForNamespace(namespace, existingDir))
    ) {
      return existingDir;
    }
    return this.resolveSafeStorageDir(namespace);
  }

  /**
   * Whether `candidate` is a legitimate storage root FOR `namespace` (round 6,
   * codex P2 — NDATT). Accepts the namespace's router-resolved root, its canonical
   * lexical tokenized dir, and (for the default namespace only) memoryDir. This
   * prevents a contained-but-CROSS-NAMESPACE path — another namespace's tree, or
   * memoryDir for a non-default namespace — from being persisted as this
   * namespace's root. Compared on resolved (absolute) paths.
   */
  private async isStorageDirForNamespace(namespace: string, candidate: string): Promise<boolean> {
    const resolvedCandidate = path.resolve(candidate);
    const valid = new Set<string>();
    // The namespace's canonical lexical TOKENIZED dir is always a valid root.
    try {
      valid.add(path.resolve(this.namespaceTokenDir(namespaceIdentityToken(namespace))));
    } catch {
      // Unsafe token cannot build a lexical dir; fall through to other roots.
    }
    // The namespace's legacy RAW-NAME dir (`namespaces/<rawname>`) is also a
    // valid root — the router serves data from it when present, even before any
    // dir exists on disk. Both forms belong to THIS namespace, never another's.
    try {
      valid.add(path.resolve(this.namespaceTokenDir(namespace)));
    } catch {
      // Unsafe raw name cannot build a lexical dir; rely on the other roots.
    }
    // The router-resolved root (whichever of the above it currently serves, a
    // migrated default, etc.).
    try {
      valid.add(path.resolve(await resolveNamespaceStorageRoot(this.config, namespace)));
    } catch {
      // Router resolution failed; rely on the lexical/default roots below.
    }
    // memoryDir is a valid root ONLY for the default namespace.
    if (normalizeNamespaceIdentity(namespace) === this.defaultNamespaceIdentity) {
      valid.add(path.resolve(this.memoryDir));
      try {
        valid.add(path.resolve(await resolveDefaultNamespaceRoot(this.config)));
      } catch {
        // ignore; memoryDir already covers the common default case.
      }
    }
    return valid.has(resolvedCandidate);
  }

  /**
   * Resolve the canonical storage dir for a namespace as the LIVE ROUTER would,
   * but NEVER return a path that escapes the memory root.
   *
   * Router alignment (round 4, cursor Medium): a read/register touch with no
   * explicit storageDir previously used the lexical `resolveStorageDir`, which
   * always picks `<memoryDir>/namespaces/<token>` (or `memoryDir` for the
   * default). That diverges from `NamespaceStorageRouter`, which can route to a
   * legacy raw-name dir or a migrated default root — so a recall touch could
   * record a contained-but-WRONG root that maintenance/rebuild then targets. We
   * now delegate to the shared `resolveNamespaceStorageRoot` (the very helper the
   * router uses) so the catalog records the same on-disk root the router serves.
   *
   * Containment (round 5, codex P2): the resolved path can still be a symlink
   * escaping memoryDir, so we run the full (lexical + realpath) containment
   * contract. When it FAILS we fall back to a NAMESPACE-SPECIFIC safe root, NOT
   * a blanket `memoryDir`. Recording `memoryDir` for a non-default namespace
   * would point enumeration/maintenance at the DEFAULT namespace's tree (round 5,
   * cursor/codex Medium/P2) — a cross-namespace fanout error. The correct safe
   * root is the namespace's own lexical tokenized dir
   * (`<memoryDir>/namespaces/<token>`), which is always contained and is that
   * namespace's canonical location (we record the lexical PATH as metadata; we do
   * not follow the escaping symlink). Only the default namespace — or a token so
   * unsafe even the lexical dir cannot be built — falls back to `memoryDir`.
   */
  private async resolveSafeStorageDir(namespace: string): Promise<string> {
    let resolved: string;
    try {
      resolved = await resolveNamespaceStorageRoot(this.config, namespace);
    } catch {
      return this.safeFallbackStorageDir(namespace);
    }
    if (await this.isContainedStorageDir(resolved)) return resolved;
    return this.safeFallbackStorageDir(namespace);
  }

  /**
   * The namespace-specific contained fallback root, used when the router-resolved
   * root fails containment (round 5, cursor/codex Medium/P2).
   *
   * Preference order:
   *  1. The namespace's OWN lexical tokenized dir (`namespaces/<token>`) — so a
   *     non-default namespace is NOT pointed at the DEFAULT namespace's `memoryDir`
   *     tree (which would misdirect maintenance fanout). Returned only when the
   *     token dir itself stays CONTAINED (it is not a symlink, and its realpath
   *     does not escape memoryDir — e.g. via a symlinked `namespaces/` parent).
   *  2. `memoryDir` as a LAST resort — for the default namespace, an unsafe token
   *     that cannot build a contained path, OR the irreparable case where the
   *     token dir's realpath escapes the root (so even its lexical path resolves
   *     outside). NF21m note (codex P2): we deliberately do NOT record the lexical
   *     token dir in that irreparable case — its realpath escapes memoryDir, and
   *     the NDo79 contract REQUIRES that an escaping path is never persisted (a
   *     later mkdir/maintenance/QMD op would follow it outside the root). Since no
   *     contained namespace-specific path exists, containment wins: `memoryDir` is
   *     the only safe root left. A namespace whose token dir's realpath escapes is
   *     an irreparable on-disk state; recording the contained default root is
   *     strictly safer than persisting an escaping one. The common case where the
   *     token dir IS contained is handled by branch 1, so a healthy non-default
   *     namespace never reaches `memoryDir`.
   */
  private async safeFallbackStorageDir(namespace: string): Promise<string> {
    if (normalizeNamespaceIdentity(namespace) === this.defaultNamespaceIdentity) return this.memoryDir;
    let tokenDir: string;
    try {
      tokenDir = this.namespaceTokenDir(namespaceIdentityToken(namespace));
    } catch {
      return this.memoryDir;
    }
    if (await this.isContainedStorageDir(tokenDir)) return tokenDir;
    return this.memoryDir;
  }

  /**
   * Re-check, NOW, whether a namespace's storage root currently EXISTS on disk
   * with the SAME safety the directory scan uses (NFJV8, codex P2).
   *
   * The rebuild's final re-merge runs under the held lock and folds the freshly
   * re-read log (`latest`) into the scanned `rebuilt` set. A namespace present in
   * `latest` (a live touch row) but ABSENT from `rebuilt` is normally PURGED as
   * deleted (the NATqU "disk scan is authoritative" rule). But there is a TOCTOU
   * window: a dynamic namespace can be CREATED on disk AFTER `rebuildFromDisk()`
   * already enumerated `namespaces/` but BEFORE this re-merge. The scan snapshot
   * missed its new root, yet a gateway `markWrite` already appended a row for it.
   * Blindly purging that row would rewrite the catalog WITHOUT a live namespace
   * that now has data on disk, so `writtenSince`/maintenance/QMD consumers miss
   * it until another touch or rebuild.
   *
   * So before purging, we re-resolve the namespace's safe storage root (the same
   * router-aligned, containment-checked path the scan would have catalogued) and
   * confirm it is a real, contained, non-symlink directory that actually holds
   * memory data RIGHT NOW. If so the namespace was created-after-scan and is LIVE
   * — KEEP its row. This is the precise inverse of NATqU and does NOT reintroduce
   * it: a touch on a REMOVED root re-checks as ABSENT (no data on disk) and is
   * still purged; only a root that EXISTS on a fresh re-check is kept.
   *
   * Mirrors the per-entry scan checks (symlink rejection + realpath containment +
   * `hasMemoryData`) so a symlinked/escaping root is never resurrected.
   */
  private async liveStorageRootExistsForRebuild(
    namespace: string,
    memoryReal: string | null,
  ): Promise<boolean> {
    let root: string;
    try {
      // Use the SAME router-aligned, containment-enforcing resolver the catalog
      // uses everywhere else. It never returns an escaping path (falls back to a
      // namespace-specific contained root on containment failure).
      root = await this.resolveSafeStorageDir(namespace);
    } catch {
      return false;
    }
    // NH3Xy (codex P2): for a NON-default namespace, a generic fallback root is
    // NOT proof of liveness. When the namespace's own token root was skipped by
    // the scan as a symlink/escape, `resolveSafeStorageDir` can fall back to the
    // DEFAULT namespace's `memoryDir`; `hasMemoryData()` on that shared default
    // tree then returns true whenever the default namespace has any data, which
    // would wrongly KEEP a stale project row now pointing at the default tree
    // instead of purging the skipped namespace. Only the namespace's OWN root may
    // attest its liveness — so if a non-default namespace resolved to `memoryDir`,
    // it has no independent contained root and must be treated as absent (purge).
    if (
      normalizeNamespaceIdentity(namespace) !== this.defaultNamespaceIdentity &&
      path.resolve(root) === path.resolve(this.memoryDir)
    ) {
      return false;
    }
    let stat;
    try {
      stat = await lstat(root);
    } catch {
      // Root does not exist on disk → genuinely absent → allow the purge.
      return false;
    }
    // Reject a symlinked root rather than resurrecting it (scan parity).
    if (stat.isSymbolicLink()) return false;
    if (!stat.isDirectory()) return false;
    // Realpath must stay inside the memory root (scan parity).
    try {
      const real = await realpath(root);
      if (memoryReal && !isPathInside(memoryReal, real)) return false;
    } catch {
      return false;
    }
    // Only treat the root as a live namespace when it actually holds memory data,
    // exactly as the scan does (empty shells are not catalogued).
    return hasMemoryData(root);
  }

  /**
   * Record a namespace touch. Returns whether the touch actually APPENDED to the
   * log (round 6, codex P2 — NEFoX): a disabled catalog or a dropped append (the
   * NAUf7 rebuild-lock-timeout drop) returns `false`, so callers (e.g. the router
   * resolve-hook dedup) can avoid marking a dropped registration as completed and
   * suppressing its retry.
   */
  private async touch(
    namespace: string,
    kind: "read" | "write" | "maintenance" | "register",
    metadata?: NamespaceTouchMetadata,
    jobName?: string,
  ): Promise<boolean> {
    if (!this.enabled) return false;
    // Validate up front (outside the chain) so caller-facing rejections — e.g.
    // an unsafe namespace token — surface immediately and deterministically,
    // not interleaved with serialized I/O.
    const ns = this.validateNamespace(namespace);
    const nowIso = (metadata?.at ?? new Date()).toISOString();

    // Run the read → merge → append as a single serialized critical section so
    // two concurrent touches for the same namespace cannot both observe the same
    // stale record and then have the later append win compaction while dropping
    // the earlier touch's fields (CLAUDE.md rule #40 — the chain also recovers
    // from rejection). Reading inside the chain guarantees each touch sees the
    // most recent appended state, including any concurrent read/write/register.
    // Cross-process serialization (round 7, codex P2 — NEZkA: HELD MUTEX). A CLI
    // `rebuild --apply` holds the rebuild lock across its final `loadCompacted()`
    // → atomic `rename`. Previously a touch only POLLED (`waitForRebuildLockClear`)
    // for the lock before reading/appending WITHOUT holding it — a check-then-act
    // gap: a touch could see no lock, a rebuild could then acquire the lock + run
    // its final `loadCompacted()`, and the touch's later append would be clobbered
    // by the rebuild's `rename()`. We now make the touch HOLD the SAME advisory
    // lock for the WHOLE read → merge → append window. While the touch holds the
    // lock, a rebuild in another process blocks on it (and vice-versa), so no
    // append can land between a rebuild's final load and its rename. `queueCritical`
    // serializes this within ONE process (so the OS lock is never self-contended in
    // process); the file lock adds the missing CROSS-process exclusion. If the touch
    // cannot ACQUIRE the lock within the bounded wait (another process's rebuild is
    // mid-flight), it DROPS the append: the catalog is rebuildable best-effort
    // metadata, so skipping one touch is acceptable; it NEVER blocks forever, NEVER
    // appends without the lock, and NEVER crashes the primary memory op.
    return this.queueCritical(async () =>
      this.withHeldCatalogLock(async (acquired) => {
        // Could not hold the lock (a cross-process rebuild is in its load→rename
        // window). DROP rather than append into that window (the lost-append race
        // this lock exists to prevent). Returning false also lets the router's
        // resolve-hook dedup retry a dropped registration later.
        if (!acquired) return false;

        // Test-only seam: widen the held-lock window so a concurrency test can
        // attempt a cross-process rebuild here and assert it is BLOCKED by this
        // held lock (no-op in production).
        if (this.onTouchCriticalSectionForTest) {
          await this.onTouchCriticalSectionForTest();
        }

        const records = await this.loadCompacted();
        const existing = records.get(ns);

        // Containment-check any explicit storageDir before persisting it (round 4
        // + round 5, codex P2). Never trust a caller-provided path verbatim;
        // reject lexical escapes AND symlinks that escape via realpath.
        const storageDir = await this.resolveTouchStorageDir(
          ns,
          metadata?.storageDir,
          existing?.storageDir,
        );
        // Provenance (discoveredBy) and createdAt are CREATION-ONLY fields. Once a
        // record exists they are preserved, so a routine routing/recall touch (or
        // the router's `config` register hook firing on a cache hit) can never
        // clobber the original discovery source — e.g. a `write`-discovered record
        // is not reset to `config` by a later resolve. Touch fields (lastReadAt /
        // lastWriteAt / lastMaintenanceAt) still update on every touch below.
        const record: NamespaceRecord = existing
          ? { ...existing }
          : {
              namespace: ns,
              identityToken: namespaceIdentityToken(ns),
              kind: metadata?.kind ?? inferKind(ns, this.config),
              createdAt: nowIso,
              storageDir,
              discoveredBy:
                metadata?.discoveredBy ??
                (kind === "register" ? "config" : kind === "maintenance" ? "scan" : kind),
            };

        // Update mutable fields. storageDir and kind may change over a
        // namespace's lifetime, so they upsert.
        record.storageDir = storageDir;
        if (metadata?.kind) record.kind = metadata.kind;
        // PROVENANCE (creation-only, with one upgrade — round 6, codex P2 NBPmT):
        // `discoveredBy` is otherwise preserved for existing records (a routine
        // read/register/resolve never relabels it). The single exception is a real
        // WRITE upgrading a record that was only PRE-REGISTERED by the router's
        // `onResolve` hook (`discoveredBy: "config"`) before any data was written.
        // Without this upgrade, `listNamespaces({ discoveredBy: "write" })` misses
        // namespaces that were genuinely written, because `storageFor()` fires
        // `registerResolved()` (config) before `recordCatalogWrite()` runs. We
        // upgrade ONLY config→write — never downgrade write/read, never relabel a
        // read-discovered record — so the authoritative "this namespace has been
        // written" signal is recorded.
        if (kind === "write" && existing && record.discoveredBy === "config") {
          record.discoveredBy = "write";
        }

        if (kind === "read") record.lastReadAt = nowIso;
        if (kind === "write") record.lastWriteAt = nowIso;
        if (kind === "maintenance" && jobName) {
          record.lastMaintenanceAt = { ...(record.lastMaintenanceAt ?? {}), [jobName]: nowIso };
        }

        await this.appendUnchained(record);
        // Size-triggered auto-compaction (issue #1903), still inside the held
        // cross-process lock + queueCritical turn so the fold→rename is atomic
        // against concurrent touches and cross-process rebuilds.
        await this.maybeAutoCompact();
        return true;
      }),
    );
  }

  /**
   * Rewrite the catalog after a read skipped malformed rows (#3297). Same fold-and-rewrite as the
   * size-triggered compaction — the readable rows survive, the malformed ones do not — so a stuck
   * bad row stops keeping every completion request owed. Best-effort and fail-open (rule #40): a
   * failed rewrite leaves the catalog unchanged and the next read reports and retries.
   *
   * Locking: the fold runs inside `queueCritical` (in-process serialization, like every other
   * read), and the rewrite's load→rename window runs under the held catalog file lock, so it can
   * never interleave with another process's touch append or rebuild. If another process already
   * holds the lock, the rewrite is dropped (not queued): that process's own rewrite or rebuild is
   * the likeliest repair, and the next incomplete read retries anyway.
   *
   * Data safety: the locked re-read must itself reach the end of the file and still find
   * malformed rows, and must leave at least one readable row. A failed re-read folds to an empty
   * map, and a catalog with nothing readable is left for `rebuildFromDisk`: rewriting either
   * would replace a healthy or recoverable catalog with an empty file.
   */
  private async rewriteAfterIncompleteRead(): Promise<"repaired" | "dropped" | "failed"> {
    return this.queueCritical(async () =>
      this.withHeldCatalogLock(async (acquired) => {
        if (!acquired) return "dropped";
        const health: CatalogReadHealth = { malformedLines: [] };
        const folded = await this.loadCompacted(true, health);
        if (health.malformed !== true || folded.size === 0) return "failed";
        // Quarantine the rows the rewrite drops before the rename, so nothing is lost
        // silently. Best-effort like the repair itself: a failed sidecar write must not
        // leave a stuck malformed catalog unrepaired.
        const dropped = health.malformedLines ?? [];
        if (dropped.length > 0) {
          // Hash-named (#3298 review): repeated attempts over the same bad rows
          // reuse one sidecar instead of piling one per failed attempt.
          const sidecar = malformedSidecarPath(this.catalogPath, dropped);
          await writeFile(sidecar, dropped.join("\n") + "\n", "utf8").catch(() => undefined);
        }
        await this.rewriteUnchained([...folded.values()]);
        return "repaired";
      }),
    );
  }


  /**
   * Fold-and-rewrite the JSONL log when it exceeds `compactBytesLimit`
   * (issue #1903). MUST be called only from inside `touch`'s held-lock +
   * `queueCritical` critical section — it reuses `loadCompacted` (last-record-
   * wins fold; every namespace row survives) and `rewriteUnchained` (atomic
   * temp-file + rename), so the collapse is cross-process safe and never
   * invokes the disk-scan purge in `finishRebuild`. Best-effort and fail-open
   * (rule #40): the append already succeeded and is durable, so a failed
   * compaction must not fail the touch — the next over-limit touch retries.
   */
  private async maybeAutoCompact(): Promise<void> {
    try {
      const limit = this.compactBytesLimit; // 0 => auto-compaction disabled
      if (limit <= 0) return;
      // Exact post-append size when the cache is warm; skip this touch's check
      // when the cache is cold (a cross-process append invalidated it) — the
      // next touch re-warms and re-checks.
      const size = this.compactedCache?.identity.size;
      if (size === undefined || size <= limit) return;
      // Hysteresis (issue #1903, Codex): a folded catalog whose deduped state is
      // itself above the limit (many distinct namespaces) would otherwise be
      // re-folded + re-rewritten on EVERY touch — O(catalog) per touch. Only
      // compact again once the log has grown by >= one limit-worth since the last
      // compaction; by then the new appends are duplicates the fold can collapse.
      if (this.lastCompactedSize > 0 && size - this.lastCompactedSize < limit) return;
      const folded = await this.loadCompacted();
      await this.rewriteUnchained([...folded.values()]);
      this.lastCompactedSize = this.compactedCache?.identity.size ?? size;
    } catch {
      // Fail-open: compaction is best-effort maintenance on already-durable data.
    }
  }

  // ── Rebuild from disk ────────────────────────────────────────────────────

  async rebuildFromDisk(
    options?: { dryRun?: boolean },
  ): Promise<NamespaceCatalogRebuildResult> {
    const dryRun = options?.dryRun === true;
    if (!this.enabled) {
      return { dryRun, records: [], skipped: [], applied: false };
    }

    // CONCURRENCY (Issue A — round 2): the entire scan → merge → rewrite runs
    // inside ONE serialized critical section on the shared write chain. This
    // closes the round-1 residual risk where a hot-path markRead/markWrite/
    // registerResolved append could land AFTER the snapshot but BEFORE the
    // atomic rewrite and then be discarded by the rewrite. Because touches also
    // run through `queueCritical`, no append can interleave between the load
    // (which now reads the latest persisted state, including touches that
    // landed before this section started) and the rewrite. A `--dry-run` still
    // takes the section for a consistent read but performs no mutation.
    //
    // Deadlock note: the rewrite inside this section uses the unchained
    // `rewriteUnchained` helper (mirroring `appendUnchained`) rather than a
    // helper that re-enters `queueCritical` — re-entering the chain from inside
    // a held turn would await the very entry this section holds.
    //
    // CROSS-PROCESS (round 5, codex P2): `queueCritical` only serializes this
    // process's instance. A CLI `rebuild --apply` and the live gateway are
    // SEPARATE processes with independent write chains, so a gateway append can
    // still land between the CLI's load and its atomic rename. For the mutating
    // path we additionally take a cross-process file lock AND re-merge the latest
    // on-disk touches under that lock immediately before the rewrite (see
    // `rebuildInsideChain`). A dry-run never mutates, so it skips the lock.
    if (dryRun) {
      return this.queueCritical(async () => this.rebuildInsideChain(dryRun, false));
    }
    // A mutating rebuild HOLDS the same advisory lock that touches now hold (round
    // 7, codex P2 — NEZkA). Because the touch path acquires this lock across its
    // read→append window and the rebuild holds it across its final
    // `loadCompacted()` → `rename()`, the two are mutually exclusive cross-process:
    // no touch append can land between a rebuild's final load and its rename.
    //
    // SCOPED MUTEX (NFgCT, codex P2): the lock is acquired ONLY around the final
    // load→merge→rename window, NOT the (potentially long) disk scan. The scan does
    // not mutate, so holding the lock across it merely forces concurrent gateway
    // touches to wait — and they DROP their append after `REBUILD_LOCK_MAX_WAIT_MS`,
    // losing real `lastWriteAt`/new-namespace data the rewrite then misses. Keeping
    // the scan lockless shrinks the window in which a touch must contend with the
    // rebuild to just the final critical section, which is brief. `rebuildInsideChain`
    // acquires `withHeldCatalogLock` itself, immediately before its re-merge+rewrite.
    //
    // LOCK ORDERING (round 7 — NEZkA): the file lock is acquired INSIDE
    // `queueCritical`, identically to the touch path (`queueCritical` → file lock),
    // NOT around it. A consistent acquire order is what prevents an in-process
    // deadlock between a same-instance touch and rebuild: `queueCritical` fully
    // serializes the two turns in this process, so when one turn holds the file
    // lock the other is not even running — the OS lock is never self-contended
    // in-process and a same-instance touch never stalls/drops behind its own
    // rebuild. The file lock therefore adds ONLY the missing cross-process
    // exclusion. `rebuildInsideChain` still runs entirely inside `queueCritical`;
    // it just narrows the cross-process file lock to the final rewrite window.
    return this.queueCritical(async () => this.rebuildInsideChain(dryRun, true));
  }

  /**
   * Body of `rebuildFromDisk`, run inside a single `queueCritical` turn. MUST
   * only be invoked from within the serialized chain so the load and the
   * rewrite are atomic with respect to concurrent touches (in-process).
   *
   * `wantMutate` is true for an `--apply` (the caller intends to rewrite). The
   * cross-process file lock is acquired LATE — only around the final
   * load→merge→rename window (NFgCT, codex P2) — never across the disk scan, so a
   * long scan does not force concurrent gateway touches to wait (and drop their
   * append). Whether the rewrite actually happened is reported via the result's
   * `applied`: true only when `wantMutate` AND the lock was acquired.
   */
  private async rebuildInsideChain(
    dryRun: boolean,
    wantMutate: boolean,
  ): Promise<NamespaceCatalogRebuildResult> {
    // Read the LATEST persisted state inside the chain so any touch that landed
    // before this turn is folded in (and re-merged into the rewrite below).
    const existing = await this.loadCompacted();
    const skipped: NamespaceCatalogSkippedRoot[] = [];
    const rebuilt = new Map<string, NamespaceRecord>();
    const nowIso = new Date().toISOString();

    let memoryReal: string | null = null;
    try {
      memoryReal = await realpath(this.memoryDir);
    } catch {
      memoryReal = this.memoryDir;
    }

    // 1) Configured namespaces always belong in the catalog.
    //
    // NORMALIZE FIRST (NGnek, codex P2): the live router normalizes every namespace
    // via `normalizeNamespaceIdentity` (a trim) in `storageFor()` before resolving
    // storage, and `isSafeRouteNamespace` also trims before validating. So a
    // configured name with harmless surrounding whitespace (e.g.
    // `sharedNamespace: "shared "` or a policy name copied with a trailing space)
    // would otherwise seed a catalog row for the RAW string and resolve a
    // `namespaces/shared ` root the live reads/writes never use — pointing
    // maintenance/QMD at the wrong directory after `rebuild --apply`. We normalize
    // configured names here so the catalog seeds the SAME identity the router uses
    // (rule #42: read/write resolve through the same normalization). The default
    // namespace is normalized too and compared via its normalized form (`defaultNs`)
    // wherever a configured/scanned name is matched against it below.
    const defaultNs = normalizeNamespaceIdentity(this.config.defaultNamespace);
    const configured = new Set<string>(
      [
        this.config.defaultNamespace,
        this.config.sharedNamespace,
        ...this.config.namespacePolicies.map((p) => p.name),
      ]
        .map((n) => normalizeNamespaceIdentity(n))
        .filter((n) => n.length > 0),
    );

    // 2) Default-root alignment (Issue C — round 2): the catalog's default
    //    record MUST point at the SAME root the runtime router resolves, or
    //    maintenance/QMD consumers would read a different default root than
    //    live reads. We delegate to the shared `resolveDefaultNamespaceRoot`
    //    (the very helper the router uses) instead of reimplementing divergent
    //    "prefer tokenized dir if it has data" logic — while legacy data lives
    //    directly under memoryDir, this returns memoryDir, matching runtime.
    const resolvedDefaultRoot = await resolveDefaultNamespaceRoot(this.config);
    // CONTAINMENT (round 6, codex P2 — NEOFS): `resolveDefaultNamespaceRoot()` can
    // return a `namespaces/<default-token>` symlink escaping memoryDir when the
    // legacy default root is empty. The default record must never carry an
    // escaping `storageDir`; fall back to the trusted `memoryDir` root when the
    // resolved one fails containment. Computed ONCE so every later use (the
    // configured-seeding step and the scan's default-dir re-apply) stays safe.
    const defaultStorageDir = (await this.isContainedStorageDir(resolvedDefaultRoot))
      ? resolvedDefaultRoot
      : this.memoryDir;
    const legacyDefaultHasData = defaultStorageDir === this.memoryDir;

    for (const ns of configured) {
      if (!ns) continue;
      // SAFETY (round 6, codex P2 — NBPmO): `parseConfig` intentionally preserves
      // unsafe namespace strings (e.g. a `sharedNamespace`/`namespacePolicies[]`
      // name like `../evil`) so sinks reject them. The hot touch/scan paths
      // already reject via `isSafeRouteNamespace`; rebuild must NOT be the path
      // that admits an unsafe configured namespace into the catalog. The default
      // namespace is exempt (it may be a non-route literal), matching the scan
      // loop's exemption below.
      if (ns !== defaultNs && !isSafeRouteNamespace(ns)) {
        let token: string;
        try {
          token = namespaceIdentityToken(ns);
        } catch {
          token = ns;
        }
        skipped.push({ token, reason: "unsafe", detail: ns });
        continue;
      }
      // ROUTER ALIGNMENT (round 6, codex P2 — NDxiS): seed a configured
      // non-default namespace with the SAME root the runtime router resolves, not
      // a blanket tokenized dir. `resolveNamespaceStorageRoot` returns the legacy
      // RAW root when it exists and only prefers the tokenized root when that has
      // storage markers — so a configured namespace with an empty legacy raw root
      // (e.g. `namespaces/shared`) is catalogued at the runtime path, keeping
      // maintenance/QMD aligned with live reads. Falls back to the lexical token
      // dir if router resolution fails.
      let storageDir: string;
      if (ns === defaultNs) {
        storageDir = defaultStorageDir;
      } else {
        try {
          storageDir = await resolveNamespaceStorageRoot(this.config, ns);
        } catch {
          storageDir = this.namespaceTokenDir(namespaceIdentityToken(ns));
        }
      }
      // CONTAINMENT (round 6, codex P2 — NCzT4/NEOFS): verify the seeded path does
      // not ESCAPE memoryDir before recording it. The scan below rejects
      // escaping/symlinked roots, but this seeding runs FIRST, so without this
      // check rebuild would persist an escaping `storageDir`. `isContainedStorageDir`
      // enforces the full lexical + symlink + realpath contract and allows a
      // not-yet-created path (a brand-new configured namespace seeds its canonical
      // root). The DEFAULT namespace is also checked (NEOFS): if
      // `resolveDefaultNamespaceRoot()` returns a `namespaces/<default-token>`
      // symlink escaping memoryDir, we must NOT persist it. The default cannot be
      // "skipped" (it must always exist), so it falls back to the trusted
      // `memoryDir` root; a non-default namespace is skipped (escape).
      if (!(await this.isContainedStorageDir(storageDir))) {
        if (ns === defaultNs) {
          storageDir = this.memoryDir;
        } else {
          skipped.push({ token: namespaceIdentityToken(ns), reason: "escape", detail: storageDir });
          continue;
        }
      }
      rebuilt.set(
        ns,
        this.mergeForRebuild(existing.get(ns), {
          namespace: ns,
          identityToken: namespaceIdentityToken(ns),
          kind: inferKind(ns, this.config),
          createdAt: existing.get(ns)?.createdAt ?? nowIso,
          storageDir,
          discoveredBy: "config",
        }),
      );
    }

    // 3) Scan the namespaces/ directory for tokenized roots.
    const namespacesDir = path.join(this.memoryDir, "namespaces");
    let entries: Dirent[] = [];
    // CONTAINMENT (round 8, codex P2 — NE9K_): check the `namespaces` ROOT itself
    // BEFORE `readdir` follows it. If `<memoryDir>/namespaces` is a symlink (or its
    // realpath escapes memoryDir), `readdir()` would enumerate an arbitrary outside
    // tree — leaking names or spending time on a huge directory — even though the
    // catalog rejects symlinked/escaping per-entry roots. The per-entry lstat/realpath
    // checks below run AFTER the readdir, so they cannot prevent following an
    // escaping ROOT. We lstat the root: if it is a symlink, OR its realpath escapes
    // memoryDir, we DO NOT read it and report it as a single unsafe scan root.
    let namespacesDirSafe = true;
    try {
      const rootStat = await lstat(namespacesDir);
      if (rootStat.isSymbolicLink()) {
        namespacesDirSafe = false;
      } else {
        const realNamespacesDir = await realpath(namespacesDir);
        if (memoryReal && !isPathInside(memoryReal, realNamespacesDir)) {
          namespacesDirSafe = false;
        }
      }
    } catch {
      // The `namespaces` dir does not exist yet (or lstat failed): nothing to scan,
      // and there is no symlink to follow. Treat as an empty, safe scan.
      namespacesDirSafe = true;
    }
    if (!namespacesDirSafe) {
      skipped.push({ token: "namespaces", reason: "symlink", detail: namespacesDir });
    } else {
      try {
        entries = await readdir(namespacesDir, { withFileTypes: true });
      } catch {
        entries = [];
      }
    }

    // Dual-root alignment (round 5, cursor Medium): when both a legacy raw-name
    // dir and a tokenized dir hold data for the SAME namespace, the router
    // prefers the tokenized root. Track which scanned namespaces were already
    // sourced from their tokenized dir so a later legacy-named `readdir` entry
    // cannot overwrite the tokenized record (and vice-versa: a tokenized entry
    // always wins over a previously-set legacy one).
    const scannedFromTokenized = new Map<string, number>();
    for (const entry of entries) {
      const token = entry.name;
      const fullPath = path.join(namespacesDir, token);
      // Reject symlinks / escaping roots rather than trusting them.
      let stat;
      try {
        stat = await lstat(fullPath);
      } catch (err) {
        skipped.push({ token, reason: "error", detail: err instanceof Error ? err.message : String(err) });
        continue;
      }
      if (stat.isSymbolicLink()) {
        skipped.push({ token, reason: "symlink", detail: fullPath });
        continue;
      }
      if (!stat.isDirectory()) continue;
      // Containment: realpath must stay inside the memory root.
      try {
        const real = await realpath(fullPath);
        if (memoryReal && !isPathInside(memoryReal, real)) {
          skipped.push({ token, reason: "escape", detail: real });
          continue;
        }
      } catch (err) {
        skipped.push({ token, reason: "error", detail: err instanceof Error ? err.message : String(err) });
        continue;
      }

      // Decode the namespace from the dir name. A configured dir name is used
      // verbatim. Otherwise decode a genuine tokenized dir back to its identity,
      // falling back to the raw dir name when it is not a decodable token.
      //
      // NDATN note (round 6, codex P2): a raw dir literally named like a CANONICAL
      // token (e.g. `namespaces/ns-616c706861`, the canonical token of `alpha`) is
      // inherently ambiguous from disk alone — the bytes are identical whether the
      // namespace is `alpha` (in its tokenized dir) or the literal `ns-616c706861`
      // (in a raw dir). Decoding a canonical token is the correct default. The
      // unambiguous fix lives on the WRITE path, where the caller knows the true
      // namespace and records it verbatim (NCQI0); the scanner cannot recover a
      // name the encoding cannot distinguish, so we keep the canonical decode.
      //
      // NRcCD (round 9, codex P2 — same class as namespaceFromStorageDir/NRCve):
      // the canonical decode is WRONG when a namespace LITERALLY named like the
      // token already OWNS this root. A dynamic namespace served from a legacy raw
      // root `namespaces/ns-616c706861` (named verbatim `ns-616c706861`) records a
      // catalog row from the write path; that row is in `existing` (the prior
      // load) here. If we still decoded to `alpha`, this scan would emit an `alpha`
      // row at `fullPath`, and the final live-row remerge in `finishRebuild` would
      // re-add the literal `ns-616c706861` row (its root still has data) — leaving
      // TWO catalog rows at the SAME `storageDir`, fanning QMD/maintenance out under
      // the wrong namespace. So, mirroring `namespaceFromStorageDir`'s "config/catalog
      // match before decode" rule, prefer the LITERAL dir name when it is already a
      // KNOWN namespace — configured OR present as a live/cataloged row in `existing`
      // — and DO NOT also emit the decoded alias for that same root. A genuine
      // tokenized dir with no literal owner (no `existing` row keyed by the raw
      // token) still decodes as before.
      // Root ownership (codex r3499938974): preserving the literal must be
      // ROOT-based, not just key-based. A STALE cataloged row merely NAMED like
      // the token (but whose storageDir is NOT this `fullPath`) must NOT win — a
      // real dynamic `alpha` write served from this tokenized root would then be
      // rebuilt under the stale literal name and the fresh `alpha` row dropped by
      // the owned-by-other guard. So only prefer the literal when a CONFIGURED
      // name matches OR an existing cataloged row named `token` actually OWNS this
      // `fullPath`. A genuine tokenized root with no literal owner decodes.
      const literalRecord = existing.get(token);
      const literalOwnsRoot =
        configured.has(token) ||
        (literalRecord !== undefined &&
          path.resolve(literalRecord.storageDir) === path.resolve(fullPath));
      // Match `storageFor()`'s canonical namespace identity. A raw root whose
      // spelling trims to another namespace (for example `namespaces/shared `)
      // is not a routeable live root and must not be catalogued from disk.
      const tokenDecoded = literalOwnsRoot ? null : namespaceIdentityFromToken(token);
      const rawDecoded = tokenDecoded && tokenDecoded.length > 0 ? tokenDecoded : token;
      const decoded = normalizeNamespaceIdentity(rawDecoded);
      if (decoded.length === 0 || (rawDecoded !== decoded && rawDecoded.normalize("NFC") !== decoded)) {
        skipped.push({ token, reason: "unsafe", detail: rawDecoded });
        continue;
      }
      if (decoded !== defaultNs && !isSafeRouteNamespace(decoded)) {
        skipped.push({ token, reason: "unsafe", detail: decoded });
        continue;
      }
      // Only catalog roots that actually hold memory data (skip empty shells).
      // A malformed PRESENT marker is different from an absent marker: if
      // `facts/` is a file/symlink but `state/` is valid, cataloging the root
      // would later make catalog-driven QMD scan the bad category directory and
      // throw. Reject the whole root on the first malformed known marker.
      const memoryData = await inspectMemoryDataRoot(fullPath);
      if (memoryData.invalidMarker) {
        skipped.push({
          token,
          reason: "unsafe",
          detail: `invalid memory marker: ${memoryData.invalidMarker}`,
        });
        continue;
      }
      if (!memoryData.hasData) continue;

      // Default-root alignment (Issue C): never let a tokenized default dir
      // overwrite the configured default's storageDir with `fullPath`. The
      // default record's root is owned by `resolveDefaultNamespaceRoot` above,
      // which mirrors the router. We still keep the default record (set in
      // step 1) but skip clobbering its root here.
      if (decoded === defaultNs) {
        const def = rebuilt.get(defaultNs);
        if (def) {
          def.storageDir = defaultStorageDir;
          def.kind = "default";
        }
        continue;
      }

      // Dual-root preference: mirror the router, which uses the tokenized root
      // over a legacy raw-name root when the tokenized one has data. `entry.name`
      // is the on-disk dir name; it is the tokenized dir iff it equals the
      // namespace's identity token. If we already recorded this namespace from
      // its tokenized dir, a later legacy-named entry must not clobber it.
      const canonicalToken = namespaceIdentityToken(decoded);
      const legacyToken = namespaceIdentityLegacyToken(decoded.normalize("NFD"));
      const tokenKind = token === canonicalToken ? 2 : token === legacyToken ? 1 : 0;
      const priorTokenKind = scannedFromTokenized.get(decoded) ?? 0;
      if (rebuilt.has(decoded) && priorTokenKind > tokenKind) continue;
      if (tokenKind > 0) scannedFromTokenized.set(decoded, tokenKind);

      const prior = existing.get(decoded);
      rebuilt.set(
        decoded,
        this.mergeForRebuild(prior, {
          namespace: decoded,
          identityToken: namespaceIdentityToken(decoded),
          kind: inferKind(decoded, this.config),
          createdAt: prior?.createdAt ?? nowIso,
          storageDir: fullPath,
          // Configured-and-present namespaces keep config provenance; purely
          // discovered ones are scan.
          discoveredBy: configured.has(decoded) ? "config" : prior?.discoveredBy ?? "scan",
        }),
      );
    }

    // Mark legacy default root explicitly when applicable.
    if (legacyDefaultHasData && defaultStorageDir === this.memoryDir) {
      const def = rebuilt.get(defaultNs);
      if (def) def.kind = "default";
    }

    // ── Final critical section (SCOPED MUTEX — NFgCT, codex P2) ──────────────
    // The disk scan above ran LOCKLESS (it only reads). Now, for a mutating
    // rebuild, acquire the cross-process file lock ONLY for the
    // load→merge→rename window — the brief section a concurrent touch must be
    // excluded from. `canMutate` is true iff we ACTUALLY hold the lock: if
    // acquisition timed out (`acquired === false`) we run compute-only and never
    // re-merge+rewrite unlocked (which would race a concurrent lock holder and
    // recreate the lost-append window). A dry-run skips the lock entirely.
    if (!wantMutate) {
      return this.finishRebuild(rebuilt, skipped, dryRun, false, memoryReal, nowIso);
    }
    // Test-only seam: the SCAN is now complete but the cross-process lock has NOT
    // yet been acquired (NFgCT). A concurrency test attempts a cross-instance touch
    // here and asserts it is NOT blocked/dropped — proving the scan is lockless.
    if (this.onRebuildAfterScanForTest) {
      await this.onRebuildAfterScanForTest();
    }
    return this.withHeldCatalogLock((acquired) =>
      this.finishRebuild(rebuilt, skipped, dryRun, acquired, memoryReal, nowIso),
    );
  }

  /**
   * Final load→merge→rename window of a rebuild, factored out so the caller can
   * run it WITHIN the cross-process file lock (NFgCT, codex P2) without holding
   * that lock across the preceding disk scan. Re-reads the latest on-disk state,
   * folds concurrent touches, then (when `canMutate`) atomically rewrites the log.
   *
   * `canMutate` records that the cross-process lock was actually held. The
   * re-merge + rewrite run only when it is true — a dry-run, or an unlocked apply
   * (lock-acquisition timeout), computes records but does NOT rename, so it can
   * never clobber a concurrent lock holder's window. `applied` mirrors `canMutate`.
   */
  private async finishRebuild(
    rebuilt: Map<string, NamespaceRecord>,
    skipped: NamespaceCatalogSkippedRoot[],
    dryRun: boolean,
    canMutate: boolean,
    memoryReal: string | null,
    nowIso: string,
  ): Promise<NamespaceCatalogRebuildResult> {
    if (canMutate) {
      // CROSS-PROCESS re-merge (round 5, codex P2): under the rebuild lock,
      // re-read the on-disk log ONE more time and fold any touch fields that
      // landed AFTER our initial `loadCompacted()` (e.g. a gateway markWrite in
      // another process) into the rebuilt records — last-write-wins per touch
      // field. This recovers cross-process appends that completed during the
      // scan, which the in-process `queueCritical` alone cannot see. Only runs
      // when we hold the lock (round 6, codex P2 — NBPmY): an unlocked rebuild
      // must not re-merge then rename, or it races a concurrent lock holder.
      const latest = await this.loadCompacted(true);
      for (const [ns, fresh] of latest) {
        const current = rebuilt.get(ns);
        if (!current) {
          // AUTHORITATIVE PURGE (round 6, cursor Medium — NATqU): the disk scan
          // is the single source of truth for which namespaces EXIST. A namespace
          // absent from `rebuilt` was NOT discovered on disk (its root is
          // empty/deleted) and is NOT configured, so the rebuild is purging it.
          // We must NOT resurrect it from the log — not even when a CONCURRENT
          // best-effort `markRead`/`markWrite` touched it after our snapshot. A
          // touch on a dynamic namespace whose on-disk root was removed only
          // bumps a timestamp; re-inserting that row (with its stale `storageDir`)
          // would defeat the purge the rebuild is meant to perform.
          //
          // CREATED-AFTER-SCAN RE-CHECK (NFJV8, codex P2): there is a TOCTOU
          // window where a dynamic namespace is CREATED on disk AFTER the scan
          // enumerated `namespaces/` but BEFORE this re-merge. Its new root was
          // missed by the snapshot, yet a gateway `markWrite` already landed a row
          // in `latest`. Purging that row would drop a LIVE namespace that now has
          // data on disk. So before purging, re-check the namespace's storage root
          // RIGHT NOW (with the same symlink/realpath/containment + memory-data
          // safety the scan uses). If it currently EXISTS with data, the namespace
          // was created-after-scan and is live — KEEP its row. This is the precise
          // inverse of NATqU, not a regression of it: a touch on a REMOVED root
          // re-checks as absent and is still purged below; only a root that EXISTS
          // on a fresh re-check is kept.
          //
          // SAFETY REVALIDATION (NGLz5, codex P2): the `ns` key comes from the
          // UNTRUSTED log (`latest`), which may carry an unsafe namespace row from a
          // pre-fix or tampered catalog. The disk SCAN validates every decoded
          // namespace with `isSafeRouteNamespace` (default exempt) and SKIPS unsafe
          // ones — so an unsafe namespace is absent from `rebuilt` by design, NOT
          // because it was deleted. Without re-applying that exact check here, a
          // matching tokenized dir on disk would let this branch RESURRECT the
          // unsafe row, and `--apply` would rewrite the catalog with a namespace the
          // hot touch/config/scan paths all reject — leaving maintenance/QMD able to
          // enumerate an unsafe namespace after a rebuild that appeared to skip it.
          // Apply the SAME default-exempt safety gate before the live-root recheck;
          // an unsafe row is dropped (fall through to purge), never kept.
          if (ns !== this.defaultNamespaceIdentity && !isSafeRouteNamespace(ns)) {
            continue;
          }
          if (await this.liveStorageRootExistsForRebuild(ns, memoryReal)) {
            // Created-after-scan: keep the live row. Re-resolve its storageDir to
            // the safe (router-aligned, contained) root so we never persist a
            // touch's stale/escaping `storageDir`.
            const safeDir = await this.resolveSafeStorageDir(ns);
            // DUAL-ROOT GUARD (codex NR-td): if another rebuilt row already OWNS
            // this exact storageDir (e.g. the decoded/configured owner of a
            // token-shaped root that the disk scan resolved), do NOT also resurrect
            // this stale alias from the untrusted log — that leaves TWO catalog rows
            // pointing at one root and fans maintenance/QMD out over the wrong
            // namespace. Enforce at most one row per storageDir: the scan's owner
            // wins, the alias is dropped (falls through to purge) after folding
            // its touch fields into the owner so recency filters/maintenance do
            // not miss a real write.
            const resolvedSafe = path.resolve(safeDir);
            let owningNamespace: string | null = null;
            for (const [otherNs, otherRec] of rebuilt) {
              if (otherNs !== ns && path.resolve(otherRec.storageDir) === resolvedSafe) {
                owningNamespace = otherNs;
                break;
              }
            }
            if (owningNamespace) {
              const owner = rebuilt.get(owningNamespace);
              if (owner) rebuilt.set(owningNamespace, mergeNewerTouchFields(owner, fresh));
              continue;
            }
            rebuilt.set(ns, {
              ...fresh,
              storageDir: safeDir,
              identityToken: namespaceIdentityToken(ns),
              kind: fresh.kind ?? inferKind(ns, this.config),
              createdAt: fresh.createdAt ?? nowIso,
            });
            continue;
          }
          // Confirmed absent on disk. Losing a touch timestamp for a deleted root
          // is acceptable (the catalog is rebuildable best-effort metadata);
          // resurrecting a purged record is not. Drop it.
          continue;
        }
        // SURVIVING namespace (still present in the authoritative disk scan):
        // fold in any newer touch fields that landed cross-process after our
        // initial snapshot so a concurrent gateway markWrite is not lost.
        rebuilt.set(ns, mergeNewerTouchFields(current, fresh));
      }
    }

    const records = [...rebuilt.values()].sort((a, b) => {
      const byName = a.namespace.localeCompare(b.namespace);
      if (byName !== 0) return byName;
      return a.identityToken.localeCompare(b.identityToken);
    });

    // Only rewrite when we actually hold the cross-process lock (round 6, codex
    // P2 — NBPmY). A dry-run never mutates; an unlocked rebuild (acquisition
    // timed out) returns the computed records WITHOUT renaming over the log, so
    // it can never clobber a concurrent lock holder's window.
    if (canMutate) {
      // Test-only seam: the load→rename window where the old check-then-append
      // touch could be clobbered. A concurrency test attempts a cross-instance
      // touch here and asserts the held lock blocks it (no-op in production).
      if (this.onRebuildBeforeRenameForTest) {
        await this.onRebuildBeforeRenameForTest();
      }
      await this.rewriteUnchained(records);
    }

    // `applied` is true only when we actually rewrote the log: never for a
    // dry-run, and never for an `--apply` that ran compute-only because it could
    // not acquire the lock (canMutate=false). Surfaces the real mutation state so
    // the CLI does not report success on a skipped rewrite (NBn3n/NBsGG).
    return { dryRun, records, skipped, applied: canMutate };
  }

  // ── Cross-process catalog write lock (held mutex) ────────────────────────

  /**
   * Run `fn` while HOLDING the shared cross-process advisory lock (round 5, codex
   * P2; generalized round 7 — NEZkA). This is the SINGLE mutex shared by BOTH the
   * touch read→merge→append window AND the rebuild final load→merge→rename window,
   * so a touch and a rebuild in different processes are mutually exclusive over
   * their respective critical sections — closing the check-then-append gap where a
   * polled-only touch could append into a rebuild's load→rename window.
   *
   * Issue #1524 adoption: this is now a thin delegation to the shared
   * `withHeldFileLock` utility. The acquire loop, mtime heartbeat, stale-break
   * (NG7Bg replacement-safe), and ownership-checked release (NCzT6) all live in
   * ONE place — the util — so this module no longer re-implements them. The
   * catalog's `REBUILD_LOCK_*` constants and the `onBeforeBreakStaleUnlinkForTest`
   * seam flow straight through. The util generates a per-CALL owner uuid, which
   * is stricter than the previous per-instance `lockOwnerId` (two calls on the
   * same instance get different ids, so neither mistakes the other's lock as
   * self-held — the NBsGP invariant, preserved and tightened).
   *
   * IN-PROCESS SAFETY: every caller invokes this from inside (or wrapping) the
   * per-process `queueCritical` chain, which serializes all catalog mutations in
   * THIS process (now via `MutationSerializer`). So within one process only one
   * logical holder attempts OS-lock acquisition at a time — the file lock is never
   * self-contended in-process, and the lock is acquired and released within a
   * single in-process turn. The file lock adds only the missing CROSS-process
   * exclusion.
   *
   * ACQUISITION RESULT (round 6, codex P2 — NBPmY): `fn` receives whether WE
   * actually hold the lock. When acquisition TIMED OUT (another holder is active),
   * a MUTATING rebuild must NOT perform its load/rename window unlocked, and a
   * touch must NOT append unlocked — both would recreate the lost-append race. The
   * caller uses `acquired` to run compute-only (rebuild) or DROP the append
   * (touch) when unlocked.
   */
  private withHeldCatalogLock<T>(fn: (acquired: boolean) => Promise<T>): Promise<T> {
    return withHeldFileLock(
      this.rebuildLockPath,
      {
        staleMs: REBUILD_LOCK_STALE_MS,
        maxWaitMs: REBUILD_LOCK_MAX_WAIT_MS,
        pollMs: REBUILD_LOCK_POLL_MS,
        heartbeatMs: REBUILD_LOCK_HEARTBEAT_MS,
        // NG7Bg seam: fires inside the util's breakStaleLock after it judges the
        // lock stale and captures its identity, before the atomic rename+verify.
        onBeforeBreakStaleUnlinkForTest: this.onBeforeBreakStaleUnlinkForTest,
      },
      fn,
    );
  }

  /**
   * Merge a prior record's preserved metadata (timestamps, principal hints)
   * onto a freshly-discovered record. Disk-derived fields (storageDir, kind)
   * take precedence from the new record.
   *
   * PROVENANCE (round 3, cursor Low): `discoveredBy` and `createdAt` are
   * CREATION-ONLY — identical to the touch path's invariant. A rebuild must NOT
   * reset a namespace first seen via a `write`/`read` touch back to `config`
   * just because it is also listed in policies. So when a prior record exists we
   * carry its `discoveredBy` forward; only brand-new records keep the fresh
   * (config/scan) provenance.
   */
  private mergeForRebuild(prior: NamespaceRecord | undefined, fresh: NamespaceRecord): NamespaceRecord {
    if (!prior) return fresh;
    const merged: NamespaceRecord = {
      ...fresh,
      createdAt: prior.createdAt ?? fresh.createdAt,
      discoveredBy: prior.discoveredBy ?? fresh.discoveredBy,
    };
    if (prior.lastReadAt) merged.lastReadAt = prior.lastReadAt;
    if (prior.lastWriteAt) merged.lastWriteAt = prior.lastWriteAt;
    if (prior.lastMaintenanceAt) merged.lastMaintenanceAt = { ...prior.lastMaintenanceAt };
    return merged;
  }
  // ── Persistence ──────────────────────────────────────────────────────────

  /** Load the JSONL log and fold it into current state (last-record-wins). */
  private async loadCompacted(
    forceFresh = false,
    health?: CatalogReadHealth,
  ): Promise<Map<string, NamespaceRecord>> {
    const records = new Map<string, NamespaceRecord>();
    let handle;
    try {
      handle = await open(this.catalogPath, "r");
    } catch (error) {
      this.compactedCache = undefined;
      // A catalog that was never written is normal; any other open failure hid the whole catalog.
      if (health && !isNotFoundError(error)) health.incomplete = `catalog unreadable: ${String(error)}`;
      return records;
    }

    let identity: CatalogFileIdentity | undefined;
    try {
      const fileStat = await handle.stat();
      identity = {
        size: fileStat.size,
        mtimeMs: fileStat.mtimeMs,
        ctimeMs: fileStat.ctimeMs,
        ino: fileStat.ino,
      };
      if (
        !forceFresh &&
        this.compactedCache &&
        this.compactedCache.identity.size === identity.size &&
        this.compactedCache.identity.mtimeMs === identity.mtimeMs &&
        this.compactedCache.identity.ctimeMs === identity.ctimeMs &&
        this.compactedCache.identity.ino === identity.ino
      ) {
        await handle.close().catch(() => undefined);
        if (health && this.compactedCache.incomplete) {
          health.incomplete = this.compactedCache.incomplete;
          // Invariant: cache.incomplete is set ONLY by the malformed branch below, so
          // deriving `malformed` here cannot misfire for an unreadable catalog.
          health.malformed = true;
        }
        return this.cloneCompactedRecords(this.compactedCache.records);
      }
    } catch {
      // A failed fstat cannot prove freshness. Read and parse the open file, but
      // do not cache the result without a trustworthy identity.
    }

    let malformed = 0;
    try {
      this.onCatalogReadForTest?.();
      // Streaming chunked parse (issue #1903): the log can reach 100+ MB in
      // production, so read it in bounded chunks and yield to the event loop
      // every ~5000 lines instead of buffering the whole file and blocking on a
      // single giant `split("\n")`. The fold is unchanged (last-record-wins with
      // field-level touch merge across cross-process full-snapshot appends).
      const CHUNK_BYTES = 1 << 16; // 64 KiB
      const YIELD_EVERY_LINES = 5000;
      const chunk = Buffer.allocUnsafe(CHUNK_BYTES);
      // StringDecoder buffers partial multi-byte UTF-8 sequences that straddle a
      // chunk boundary, so a namespace/principal with non-ASCII bytes never
      // corrupts at the seam.
      const decoder = new StringDecoder("utf8");
      let leftover = "";
      let linesSinceYield = 0;
      const foldLine = (line: string): void => {
        const trimmed = line.trim();
        if (trimmed.length === 0) return;
        let parsed: unknown;
        try {
          parsed = JSON.parse(trimmed);
        } catch {
          // Skip corrupt lines (CLAUDE.md rule #18 robustness), but count them so a caller that
          // needs the whole catalog can tell the read was incomplete (issue #3293).
          malformed += 1;
          health?.malformedLines?.push(trimmed);
          return;
        }
        const record = coerceRecord(parsed);
        if (!record) {
          malformed += 1;
          health?.malformedLines?.push(trimmed);
          return;
        }
        const prior = records.get(record.namespace);
        records.set(record.namespace, prior ? mergeNewerTouchFields(record, prior) : record);
      };
      for (;;) {
        const { bytesRead } = await handle.read(chunk, 0, CHUNK_BYTES, null);
        if (bytesRead === 0) break;
        leftover += decoder.write(chunk.subarray(0, bytesRead));
        let newlineIndex = leftover.indexOf("\n");
        while (newlineIndex !== -1) {
          foldLine(leftover.slice(0, newlineIndex));
          leftover = leftover.slice(newlineIndex + 1);
          if (++linesSinceYield >= YIELD_EVERY_LINES) {
            linesSinceYield = 0;
            await new Promise<void>((resolve) => setImmediate(resolve));
          }
          newlineIndex = leftover.indexOf("\n");
        }
      }
      leftover += decoder.end();
      foldLine(leftover);
    } catch (error) {
      this.compactedCache = undefined;
      if (health) health.incomplete = `catalog unreadable: ${String(error)}`;
      return new Map();
    } finally {
      await handle.close().catch(() => undefined);
    }

    const incomplete = malformed > 0 ? `${malformed} malformed catalog line(s) skipped` : undefined;
    if (health && incomplete) {
      health.incomplete = incomplete;
      health.malformed = true;
    }
    this.compactedCache = identity ? { identity, records, incomplete } : undefined;
    return this.cloneCompactedRecords(records);
  }

  private cloneCompactedRecords(
    records: Map<string, NamespaceRecord>,
  ): Map<string, NamespaceRecord> {
    return new Map(
      [...records].map(([namespace, record]) => [
        namespace,
        {
          ...record,
          lastMaintenanceAt: record.lastMaintenanceAt
            ? { ...record.lastMaintenanceAt }
            : undefined,
        },
      ]),
    );
  }

  /**
   * Serialize an arbitrary read-modify-write critical section through the single
   * per-instance chain. Every catalog mutation and cached catalog read runs
   * through this queue, so cache validation and updates cannot race in-process.
   *
   * Issue #1524 adoption: delegates to the shared `MutationSerializer` (stored
   * as `criticalSection`). The util owns the rejection-recovery invariant
   * (CLAUDE.md rule #40 — one failed section never poisons subsequent ones, but
   * the failing section's error still surfaces to ITS awaited promise) and the
   * no-unbounded-growth cleanup. The key is constant: the catalog has ONE
   * logical mutation queue (touches and rebuilds mutually exclude in-process).
   */
  private queueCritical<T>(fn: () => Promise<T>): Promise<T> {
    return this.criticalSection.serialize("catalog", fn);
  }

  /**
   * Append a single record to the JSONL log WITHOUT re-serializing through the
   * write chain. MUST only be called from inside a `queueCritical(...)` section
   * (which already holds the serialized turn); calling it directly would bypass
   * the read-before-append ordering that prevents lost-field races.
   */
  private async appendUnchained(record: NamespaceRecord): Promise<void> {
    const line = serializeRecord(record) + "\n";
    const lineByteLength = Buffer.byteLength(line, "utf8");
    await mkdir(this.stateDir, { recursive: true });
    await appendFile(this.catalogPath, line, "utf8");
    if (this.onAfterCatalogAppendForTest) {
      await this.onAfterCatalogAppendForTest();
    }
    await this.refreshCacheAfterAppend(record, lineByteLength);
  }

  /**
   * Atomic temp-file + rename rewrite (CLAUDE.md rule #54: write temp, then
   * rename — never delete-before-write) WITHOUT re-entering the write chain.
   * MUST only be called from inside a `queueCritical(...)` turn (e.g. the
   * rebuild critical section, which already holds the serialized turn so its
   * load and rewrite are atomic against concurrent touches). Re-entering the
   * chain from within a held turn would deadlock.
   */
  private async rewriteUnchained(records: NamespaceRecord[]): Promise<void> {
    const body = records.map((r) => serializeRecord(r)).join("\n") + (records.length > 0 ? "\n" : "");
    await mkdir(this.stateDir, { recursive: true });
    const tmp = `${this.catalogPath}.${process.pid}.${Date.now()}.tmp`;
    try {
      await writeFile(tmp, body, "utf8");
      await rename(tmp, this.catalogPath);
    } catch (error) {
      // A failed write or rename (for example the catalog path is a directory) must not leave
      // the temp file behind; the original error still surfaces to the caller.
      await rm(tmp, { force: true }).catch(() => undefined);
      throw error;
    }
    await this.refreshCacheIdentity(new Map(records.map((record) => [record.namespace, record])));
  }

  private async refreshCacheAfterAppend(
    record: NamespaceRecord,
    lineByteLength: number,
  ): Promise<void> {
    const cached = this.compactedCache;
    if (!cached) return;
    const expectedSize = cached.identity.size + lineByteLength;
    try {
      const fileStat = await stat(this.catalogPath);
      if (fileStat.size !== expectedSize || fileStat.ino !== cached.identity.ino) {
        this.compactedCache = undefined;
        return;
      }
      const prior = cached.records.get(record.namespace);
      cached.records.set(record.namespace, prior ? mergeNewerTouchFields(record, prior) : record);
      this.compactedCache = {
        identity: {
          size: fileStat.size,
          mtimeMs: fileStat.mtimeMs,
          ctimeMs: fileStat.ctimeMs,
          ino: fileStat.ino,
        },
        records: cached.records,
      };
    } catch {
      this.compactedCache = undefined;
    }
  }

  private async refreshCacheIdentity(records: Map<string, NamespaceRecord>): Promise<void> {
    try {
      const fileStat = await stat(this.catalogPath);
      this.compactedCache = {
        identity: {
          size: fileStat.size,
          mtimeMs: fileStat.mtimeMs,
          ctimeMs: fileStat.ctimeMs,
          ino: fileStat.ino,
        },
        records,
      };
    } catch {
      this.compactedCache = undefined;
    }
  }
}

function isPathInside(root: string, child: string): boolean {
  const relative = path.relative(root, child);
  return relative === "" || (!relative.startsWith("..") && !path.isAbsolute(relative));
}

import { resolveNamespaceCapabilities } from "../capabilities.js";
import { createHash, randomUUID } from "node:crypto";
import type { Dirent } from "node:fs";
import { lstat, mkdir, open, readFile, readdir, rename, rm, rmdir, stat, utimes, writeFile } from "node:fs/promises";
import path from "node:path";

import type { NamespaceCatalog, NamespaceKind, NamespaceRecord } from "../namespaces/catalog.js";
import { hasMemoryData } from "../namespaces/catalog.js";
import { namespaceIdentityToken } from "../namespaces/identity.js";
import { resolveNamespaceStorageRoot } from "../namespaces/storage.js";
import { displayErrorDetail } from "../runtime/better-sqlite.js";
import type { PluginConfig } from "../types.js";
import { getConfiguredNamespaces } from "../scopes/scope-plan.js";
import { resolveConversationContextCapabilities } from "../capabilities.js";

export type NamespaceMaintenanceJobName = string;

export type NamespaceMaintenanceSkipReason =
  | "fanout_disabled"
  | "empty_root"
  | "branch_disabled"
  | "project_disabled"
  | "team_project_disabled"
  | "catalog_read_failed"
  | "unsafe_or_stale_root"
  | "budget_exhausted"
  | "lock_held"
  | "batch_lock_incomplete"
  | "throttled"
  | "job_failed";

export interface NamespaceMaintenancePlannerOptions {
  jobName: NamespaceMaintenanceJobName;
  catalog?: NamespaceCatalog;
  now?: Date;
  budgetMode?: "cycle" | "unbounded";
}

export interface NamespaceMaintenanceCandidate {
  namespace: string;
  kind: NamespaceKind;
  storageDir?: string;
  source: "configured" | "catalog";
  lastWriteAt?: string;
  lastMaintenanceAt?: string;
}

export interface NamespaceMaintenancePlan {
  jobName: NamespaceMaintenanceJobName;
  generatedAt: string;
  namespaces: NamespaceMaintenanceCandidate[];
  skipped: NamespaceMaintenanceSkippedNamespace[];
  budget: {
    maxNamespacesPerCycle: number;
    selected: number;
  };
}

export interface NamespaceMaintenanceSkippedNamespace {
  namespace: string;
  kind?: NamespaceKind;
  reason: NamespaceMaintenanceSkipReason;
  detail?: string;
}

export interface NamespaceMaintenanceRunStatus {
  namespace: string;
  jobName: NamespaceMaintenanceJobName;
  state: "ran" | "skipped" | "failed";
  reason?: NamespaceMaintenanceSkipReason;
  startedAt: string;
  completedAt: string;
  itemCount?: number;
  error?: string;
}

export interface NamespaceMaintenanceSummary {
  jobName: NamespaceMaintenanceJobName;
  generatedAt: string;
  ran: number;
  skipped: number;
  failed: number;
  statuses: NamespaceMaintenanceRunStatus[];
}

export interface NamespaceMaintenanceBatchRunResult {
  itemCount?: number;
  itemCounts?: Record<string, number> | Map<string, number>;
}

export interface NamespaceMaintenanceBatchRunOptions {
  requireAllLocks?: boolean;
  skipReasonForError?: (error: unknown) => NamespaceMaintenanceSkipReason | null | undefined;
}

interface LockHandle {
  path: string;
  touch(): Promise<void>;
  release(): Promise<void>;
}

const DEFAULT_MAX_NAMESPACES_PER_CYCLE = 20;
const DEFAULT_LOCK_STALE_MS = 10 * 60_000;
const LOCK_BASE = "maintenance-locks";
const STATUS_BASE = "namespace-maintenance-status";
const namespaceMaintenanceFs = { open, rm };

export function __setNamespaceMaintenanceFsForTest(overrides: Partial<typeof namespaceMaintenanceFs>): () => void {
  const previous = { ...namespaceMaintenanceFs };
  Object.assign(namespaceMaintenanceFs, overrides);
  return () => {
    Object.assign(namespaceMaintenanceFs, previous);
  };
}



function inferConfiguredKind(config: PluginConfig, namespace: string): NamespaceKind {
  if (namespace === config.defaultNamespace.trim()) return "default";
  if (namespace === config.sharedNamespace.trim()) return "shared";
  return "explicit";
}

function maxNamespacesPerCycle(config: PluginConfig): number {
  return Math.max(
    1,
    Math.floor(
      typeof config.maintenanceMaxNamespacesPerCycle === "number" &&
        Number.isFinite(config.maintenanceMaxNamespacesPerCycle)
        ? config.maintenanceMaxNamespacesPerCycle
        : DEFAULT_MAX_NAMESPACES_PER_CYCLE
    )
  );
}

function namespaceKindAllowed(config: PluginConfig, kind: NamespaceKind): boolean {
  switch (kind) {
    case "branch":
      return config.maintenanceIncludeBranchNamespaces === true;
    case "project":
      return config.maintenanceIncludeProjectNamespaces !== false;
    case "team-project":
      return config.maintenanceIncludeTeamProjectNamespaces !== false;
    default:
      return true;
  }
}

function disabledReasonForKind(kind: NamespaceKind): NamespaceMaintenanceSkipReason {
  if (kind === "branch") return "branch_disabled";
  if (kind === "project") return "project_disabled";
  if (kind === "team-project") return "team_project_disabled";
  return "fanout_disabled";
}

async function catalogRootIsLive(config: PluginConfig, record: NamespaceRecord): Promise<boolean> {
  if (typeof record.storageDir !== "string" || record.storageDir.length === 0) {
    return false;
  }
  try {
    const liveRoot = await resolveNamespaceStorageRoot(config, record.namespace);
    if (path.resolve(liveRoot) !== path.resolve(record.storageDir)) return false;
    return hasMemoryData(liveRoot);
  } catch {
    return false;
  }
}

function candidateSortKey(candidate: NamespaceMaintenanceCandidate): string {
  const write = candidate.lastWriteAt ?? "";
  return `${write}\u0000${candidate.namespace}`;
}

function candidatePriority(candidate: NamespaceMaintenanceCandidate): number {
  if (candidate.kind === "default") return 0;
  if (candidate.kind === "shared") return 1;
  if (candidate.source === "configured") return 2;
  if (candidate.kind === "team-project") return 3;
  if (candidate.kind === "project") return 4;
  if (candidate.kind === "branch") return 8;
  return 7;
}

function sortCandidates(a: NamespaceMaintenanceCandidate, b: NamespaceMaintenanceCandidate): number {
  const priority = candidatePriority(a) - candidatePriority(b);
  if (priority !== 0) return priority;
  const am = Date.parse(a.lastMaintenanceAt ?? "");
  const bm = Date.parse(b.lastMaintenanceAt ?? "");
  const aMaintained = Number.isFinite(am);
  const bMaintained = Number.isFinite(bm);
  if (aMaintained && bMaintained && am !== bm) return am - bm;
  if (aMaintained !== bMaintained) return aMaintained ? 1 : -1;
  const aw = Date.parse(a.lastWriteAt ?? "");
  const bw = Date.parse(b.lastWriteAt ?? "");
  const aValid = Number.isFinite(aw);
  const bValid = Number.isFinite(bw);
  if (aValid && bValid && aw !== bw) return bw - aw;
  if (aValid !== bValid) return aValid ? -1 : 1;
  const byKey = candidateSortKey(a).localeCompare(candidateSortKey(b));
  if (byKey !== 0) return byKey;
  return a.namespace.localeCompare(b.namespace);
}

export async function planNamespaceMaintenance(
  config: PluginConfig,
  options: NamespaceMaintenancePlannerOptions
): Promise<NamespaceMaintenancePlan> {
  const generatedAt = (options.now ?? new Date()).toISOString();
  // When namespaces are disabled, storageFor() collapses every namespace name
  // to config.memoryDir. Seeding all configured namespaces (default + shared +
  // policies) would make a mutating maintenance job process the SAME corpus
  // once per configured name. The #1500 contract is "namespaces disabled:
  // maintain the current default storage only," so collapse to the default.
  const configured = resolveNamespaceCapabilities(config).namespaces
    ? getConfiguredNamespaces(config)
    : [config.defaultNamespace.trim()].filter(Boolean);
  const byNamespace = new Map<string, NamespaceMaintenanceCandidate>();
  const skipped: NamespaceMaintenanceSkippedNamespace[] = [];

  for (const namespace of configured) {
    const kind = inferConfiguredKind(config, namespace);
    byNamespace.set(namespace, {
      namespace,
      kind,
      source: "configured",
    });
  }

  if (resolveNamespaceCapabilities(config).namespaces && resolveConversationContextCapabilities(config).maintenanceNamespaceFanout !== false) {
    const configuredSet = new Set(configured);
    try {
      // An incomplete read (unreadable file, malformed rows) still returns the readable records,
      // so they are planned as before; the callback records that the catalog was not whole.
      const records = options.catalog?.enabled
        ? await options.catalog.listNamespaces(undefined, {
            onIncomplete: (reason) =>
              skipped.push({ namespace: "*", reason: "catalog_read_failed", detail: reason }),
          })
        : [];
      for (const record of records) {
        const namespace = record.namespace.trim();
        if (!namespace) continue;
        const isConfigured = configuredSet.has(namespace);
        const kind = isConfigured ? inferConfiguredKind(config, namespace) : record.kind;
        if (!namespaceKindAllowed(config, kind)) {
          skipped.push({
            namespace,
            kind,
            reason: disabledReasonForKind(kind),
          });
          continue;
        }
        if (!isConfigured && !(await catalogRootIsLive(config, record))) {
          skipped.push({
            namespace,
            kind,
            reason: "unsafe_or_stale_root",
          });
          continue;
        }
        byNamespace.set(namespace, {
          namespace,
          kind,
          storageDir: record.storageDir,
          source: isConfigured ? "configured" : "catalog",
          lastWriteAt: record.lastWriteAt,
          lastMaintenanceAt: record.lastMaintenanceAt?.[options.jobName],
        });
      }
    } catch (error) {
      skipped.push({
        namespace: "*",
        reason: "catalog_read_failed",
        detail: error instanceof Error ? error.message : String(error),
      });
    }
  } else if (resolveNamespaceCapabilities(config).namespaces) {
    skipped.push({
      namespace: "*",
      reason: "fanout_disabled",
    });
  }

  if (options.budgetMode !== "unbounded") {
    const latestStatusAtByNamespace = await readLatestStatusAtByNamespace(config, options.jobName);
    for (const candidate of byNamespace.values()) {
      if (!candidate.lastMaintenanceAt) {
        candidate.lastMaintenanceAt = latestStatusAtByNamespace.get(candidate.namespace);
      }
    }
  }

  const candidates = [...byNamespace.values()]
    .filter((candidate) => namespaceKindAllowed(config, candidate.kind))
    .sort(sortCandidates);

  const max = maxNamespacesPerCycle(config);
  const applyCycleBudget = options.budgetMode !== "unbounded";
  const selected = applyCycleBudget ? candidates.slice(0, max) : candidates;
  if (applyCycleBudget) {
    for (const candidate of candidates.slice(max)) {
      skipped.push({
        namespace: candidate.namespace,
        kind: candidate.kind,
        reason: "budget_exhausted",
      });
    }
  }

  return {
    jobName: options.jobName,
    generatedAt,
    namespaces: selected,
    skipped,
    budget: {
      maxNamespacesPerCycle: max,
      selected: selected.length,
    },
  };
}

function stablePathSegment(value: string): string {
  const sanitized = value.replace(/[^a-zA-Z0-9._-]/g, "_").slice(0, 128) || "unnamed";
  if (sanitized.length <= 128 && sanitized === value) return sanitized;
  return `${sanitized.slice(0, 80)}-${createHash("sha256").update(value).digest("hex").slice(0, 16)}`;
}

function namespacePathSegment(namespace: string): string {
  const token = namespaceIdentityToken(namespace);
  if (token.length <= 160) return token;
  return `ns-${createHash("sha256").update(namespace).digest("hex")}`;
}

function lockPath(config: PluginConfig, jobName: string, namespace: string): string {
  return path.join(
    config.memoryDir,
    "state",
    LOCK_BASE,
    stablePathSegment(jobName),
    `${namespacePathSegment(namespace)}.lock`
  );
}

function namespaceMaintenanceLockStaleMs(config: PluginConfig): number {
  if (
    typeof config.maintenanceNamespaceLockStaleMs === "number" &&
    Number.isFinite(config.maintenanceNamespaceLockStaleMs) &&
    config.maintenanceNamespaceLockStaleMs > 0
  ) {
    return Math.floor(config.maintenanceNamespaceLockStaleMs);
  }
  return DEFAULT_LOCK_STALE_MS;
}

function namespaceMaintenanceLockHeartbeatMs(config: PluginConfig): number {
  const staleMs = namespaceMaintenanceLockStaleMs(config);
  return Math.max(1, Math.min(30_000, Math.floor(staleMs / 3) || 1));
}

function errorCode(error: unknown): string | undefined {
  return typeof error === "object" && error !== null && "code" in error
    ? (error as { code?: string }).code
    : undefined;
}

async function withNamespaceMaintenanceLockHeartbeat<T>(
  config: PluginConfig,
  locks: LockHandle | LockHandle[],
  task: () => Promise<T>,
): Promise<T> {
  const activeLocks = Array.isArray(locks) ? locks : [locks];
  const interval = setInterval(() => {
    for (const lock of activeLocks) {
      void lock.touch().catch(() => undefined);
    }
  }, namespaceMaintenanceLockHeartbeatMs(config));
  interval.unref?.();
  try {
    return await task();
  } finally {
    clearInterval(interval);
  }
}

async function removeStaleLockDirectory(filePath: string): Promise<void> {
  let entries: Dirent[];
  try {
    entries = await readdir(filePath, { withFileTypes: true });
  } catch (error) {
    if (errorCode(error) === "ENOENT") return;
    throw error;
  }
  for (const entry of entries) {
    if (!entry.isFile()) continue;
    await namespaceMaintenanceFs.rm(path.join(filePath, entry.name), { force: true });
  }
  try {
    await rmdir(filePath);
  } catch (error) {
    if (errorCode(error) === "ENOENT") return;
    throw error;
  }
}

async function tryAcquireNamespaceMaintenanceLock(
  config: PluginConfig,
  jobName: string,
  namespace: string
): Promise<LockHandle | null> {
  const filePath = lockPath(config, jobName, namespace);
  await mkdir(path.dirname(filePath), { recursive: true });
  try {
    const lockId = randomUUID();
    await mkdir(filePath);
    const ownerPath = path.join(filePath, `${lockId}.json`);
    let handle: Awaited<ReturnType<typeof open>> | undefined;
    try {
      handle = await namespaceMaintenanceFs.open(ownerPath, "wx");
      await handle.writeFile(
        `${JSON.stringify({
          lockId,
          pid: process.pid,
          jobName,
          namespace,
          acquiredAt: new Date().toISOString(),
        })}\n`,
        "utf8"
      );
      await handle.close();
    } catch (setupError) {
      await handle?.close().catch(() => undefined);
      await namespaceMaintenanceFs.rm(ownerPath, { force: true }).catch(() => undefined);
      await rmdir(filePath).catch(() => undefined);
      throw setupError;
    }
    return {
      path: filePath,
      async touch() {
        try {
          const parsed = JSON.parse(await readFile(ownerPath, "utf8")) as { lockId?: unknown };
          if (parsed.lockId === lockId) {
            const now = new Date();
            await utimes(ownerPath, now, now);
            await utimes(filePath, now, now);
          }
        } catch {}
      },
      async release() {
        try {
          const parsed = JSON.parse(await readFile(ownerPath, "utf8")) as { lockId?: unknown };
          if (parsed.lockId === lockId) {
            await namespaceMaintenanceFs.rm(ownerPath, { force: true });
            await rmdir(filePath).catch(() => undefined);
          }
        } catch {}
      },
    };
  } catch (error) {
    if (errorCode(error) === "EEXIST") {
      const staleMs =
        namespaceMaintenanceLockStaleMs(config);
      try {
        const s = await lstat(filePath);
        if (s.isSymbolicLink()) {
          return null;
        }
        if ((s.isFile() || s.isDirectory()) && Date.now() - s.mtimeMs > staleMs) {
          try {
            if (s.isDirectory()) {
              await removeStaleLockDirectory(filePath);
            } else {
              await namespaceMaintenanceFs.rm(filePath, { force: true });
            }
          } catch (removeError) {
            if (errorCode(removeError) === "ENOENT") {
              return tryAcquireNamespaceMaintenanceLock(config, jobName, namespace);
            }
            if (errorCode(removeError) === "ENOTEMPTY") {
              return null;
            }
            throw removeError;
          }
          return tryAcquireNamespaceMaintenanceLock(config, jobName, namespace);
        }
      } catch (statError) {
        if (errorCode(statError) === "ENOENT") {
          return tryAcquireNamespaceMaintenanceLock(config, jobName, namespace);
        }
        throw statError;
      }
      return null;
    }
    throw error;
  }
}

function statusBasePath(config: PluginConfig): string {
  return path.join(config.memoryDir, "state", STATUS_BASE);
}

function statusPath(config: PluginConfig, jobName: string, namespace: string): string {
  return path.join(statusBasePath(config), stablePathSegment(jobName), `${namespacePathSegment(namespace)}.json`);
}

function lastRanStatusPath(config: PluginConfig, jobName: string, namespace: string): string {
  return path.join(statusBasePath(config), stablePathSegment(jobName), `${namespacePathSegment(namespace)}.last-ran.json`);
}

function parseStatus(value: unknown): NamespaceMaintenanceRunStatus | null {
  if (!value || typeof value !== "object" || Array.isArray(value)) return null;
  const v = value as Partial<NamespaceMaintenanceRunStatus>;
  if (
    typeof v.namespace === "string" &&
    typeof v.jobName === "string" &&
    (v.state === "ran" || v.state === "skipped" || v.state === "failed") &&
    typeof v.startedAt === "string" &&
    typeof v.completedAt === "string"
  ) {
    return v as NamespaceMaintenanceRunStatus;
  }
  return null;
}

async function readLatestStatusAtByNamespace(config: PluginConfig, jobName: string): Promise<Map<string, string>> {
  const latest = new Map<string, string>();
  const latestMs = new Map<string, number>();
  for (const status of [...(await readStatusFiles(config)), ...(await readLastRanStatusFiles(config))]) {
    if (status.state !== "ran") continue;
    if (status.jobName !== jobName) continue;
    const completedAtMs = Date.parse(status.completedAt);
    if (!Number.isFinite(completedAtMs)) continue;
    const previousMs = latestMs.get(status.namespace);
    if (previousMs !== undefined && previousMs >= completedAtMs) continue;
    latestMs.set(status.namespace, completedAtMs);
    latest.set(status.namespace, status.completedAt);
  }
  return latest;
}

async function readStatusFile(filePath: string): Promise<NamespaceMaintenanceRunStatus | null> {
  try {
    const parsed = JSON.parse(await readFile(filePath, "utf8")) as unknown;
    return parseStatus(parsed);
  } catch {
    return null;
  }
}

async function readStatusFiles(config: PluginConfig): Promise<NamespaceMaintenanceRunStatus[]> {
  if (typeof config.memoryDir !== "string" || config.memoryDir.length === 0) {
    return [];
  }
  const root = statusBasePath(config);
  const statuses: NamespaceMaintenanceRunStatus[] = [];
  let jobDirs: Dirent[];
  try {
    jobDirs = await readdir(root, { withFileTypes: true });
  } catch {
    return statuses;
  }
  for (const jobDir of jobDirs) {
    if (!jobDir.isDirectory()) continue;
    let files: Dirent[];
    try {
      files = await readdir(path.join(root, jobDir.name), { withFileTypes: true });
    } catch {
      continue;
    }
    for (const file of files) {
      if (!file.isFile() || !file.name.endsWith(".json")) continue;
      if (file.name.endsWith(".last-ran.json")) continue;
      const status = await readStatusFile(path.join(root, jobDir.name, file.name));
      if (status) statuses.push(status);
    }
  }
  return statuses;
}

async function readLastRanStatusFiles(config: PluginConfig): Promise<NamespaceMaintenanceRunStatus[]> {
  if (typeof config.memoryDir !== "string" || config.memoryDir.length === 0) {
    return [];
  }
  const root = statusBasePath(config);
  const statuses: NamespaceMaintenanceRunStatus[] = [];
  let jobDirs: Dirent[];
  try {
    jobDirs = await readdir(root, { withFileTypes: true });
  } catch {
    return statuses;
  }
  for (const jobDir of jobDirs) {
    if (!jobDir.isDirectory()) continue;
    let files: Dirent[];
    try {
      files = await readdir(path.join(root, jobDir.name), { withFileTypes: true });
    } catch {
      continue;
    }
    for (const file of files) {
      if (!file.isFile() || !file.name.endsWith(".last-ran.json")) continue;
      const status = await readStatusFile(path.join(root, jobDir.name, file.name));
      if (status) statuses.push(status);
    }
  }
  return statuses;
}

async function writeStatusPayload(target: string, status: NamespaceMaintenanceRunStatus): Promise<void> {
  const dir = path.dirname(target);
  await mkdir(dir, { recursive: true });
  const temp = `${target}.${process.pid}.${Date.now()}.${Math.random().toString(36).slice(2)}.tmp`;
  const payload = {
    version: 1,
    ...status,
  };
  await writeFile(temp, `${JSON.stringify(payload, null, 2)}\n`, "utf8");
  await rename(temp, target);
}

async function writeStatusFile(config: PluginConfig, status: NamespaceMaintenanceRunStatus): Promise<void> {
  await writeStatusPayload(statusPath(config, status.jobName, status.namespace), status);
  if (status.state === "ran") {
    await writeStatusPayload(lastRanStatusPath(config, status.jobName, status.namespace), status);
  }
}

async function recordNamespaceMaintenanceStatusSafely(
  config: PluginConfig,
  status: NamespaceMaintenanceRunStatus
): Promise<void> {
  try {
    await writeStatusFile(config, status);
  } catch {
    // Observability must not fail the maintenance operation.
  }
}

function maintenanceErrorDetail(error: unknown): string {
  return displayErrorDetail(error) || "Error";
}

export async function readNamespaceMaintenanceStatuses(config: PluginConfig): Promise<NamespaceMaintenanceRunStatus[]> {
  return (await readStatusFiles(config)).sort((a, b) => {
    const byJob = a.jobName.localeCompare(b.jobName);
    if (byJob !== 0) return byJob;
    return a.namespace.localeCompare(b.namespace);
  });
}

/**
 * Read the last SUCCESSFUL run status per job+namespace (the
 * `<namespace>.last-ran.json` files written only when state === "ran").
 *
 * The latest status file (`<namespace>.json`) is overwritten on every run,
 * so after a successful run followed by a skip (budget/lock/cadence) the
 * latest file shows "skipped" and the prior success is invisible. Merging
 * these last-ran records into the health summary lets `lastRunAt` and run
 * history reflect the most recent successful maintenance (review #1622).
 */
export async function readNamespaceMaintenanceLastRanStatuses(
  config: PluginConfig,
): Promise<NamespaceMaintenanceRunStatus[]> {
  return (await readLastRanStatusFiles(config)).sort((a, b) => {
    const byJob = a.jobName.localeCompare(b.jobName);
    if (byJob !== 0) return byJob;
    return a.namespace.localeCompare(b.namespace);
  });
}

export type NamespaceMaintenancePlanRunnerResult = {
  itemCount?: number;
  /**
   * When `true`, the runner performed NO work for this namespace (e.g. the
   * job's own cadence gate throttled it). The planner records the namespace
   * as `state: "skipped"` with the given reason and does NOT touch the
   * catalog's `lastMaintenanceAt`, so a throttled namespace is not falsely
   * reported as maintained. Without this signal a runner that resolves
   * without throwing is always recorded as `state: "ran"`.
   */
  skipped?: boolean;
  skipReason?: string;
} | undefined;

export async function runNamespaceMaintenancePlan(
  config: PluginConfig,
  plan: NamespaceMaintenancePlan,
  runner: (candidate: NamespaceMaintenanceCandidate) => Promise<NamespaceMaintenancePlanRunnerResult>,
  catalog?: NamespaceCatalog
): Promise<NamespaceMaintenanceSummary> {
  const statuses: NamespaceMaintenanceRunStatus[] = [];

  for (const skipped of plan.skipped) {
    if (skipped.namespace === "*") continue;
    const now = new Date().toISOString();
    const status: NamespaceMaintenanceRunStatus = {
      namespace: skipped.namespace,
      jobName: plan.jobName,
      state: "skipped",
      reason: skipped.reason,
      startedAt: now,
      completedAt: now,
    };
    statuses.push(status);
    await recordNamespaceMaintenanceStatusSafely(config, status);
  }

  for (const candidate of plan.namespaces) {
    const startedAt = new Date().toISOString();
    const lock = await tryAcquireNamespaceMaintenanceLock(config, plan.jobName, candidate.namespace);
    if (!lock) {
      const completedAt = new Date().toISOString();
      const status: NamespaceMaintenanceRunStatus = {
        namespace: candidate.namespace,
        jobName: plan.jobName,
        state: "skipped",
        reason: "lock_held",
        startedAt,
        completedAt,
      };
      statuses.push(status);
      await recordNamespaceMaintenanceStatusSafely(config, status);
      continue;
    }
    try {
      const result = await withNamespaceMaintenanceLockHeartbeat(config, lock, () => runner(candidate));
      const completedAt = new Date().toISOString();
      if (result?.skipped) {
        // The runner performed no work (e.g. the job's own cadence gate
        // throttled this namespace). Record skipped WITHOUT touching the
        // catalog's lastMaintenanceAt so a throttled namespace is not
        // falsely reported as maintained.
        const status: NamespaceMaintenanceRunStatus = {
          namespace: candidate.namespace,
          jobName: plan.jobName,
          state: "skipped",
          reason: (result.skipReason ?? "throttled") as NamespaceMaintenanceSkipReason,
          startedAt,
          completedAt,
        };
        statuses.push(status);
        await recordNamespaceMaintenanceStatusSafely(config, status);
      } else {
        const status: NamespaceMaintenanceRunStatus = {
          namespace: candidate.namespace,
          jobName: plan.jobName,
          state: "ran",
          startedAt,
          completedAt,
          itemCount: result?.itemCount,
        };
        statuses.push(status);
        await recordNamespaceMaintenanceStatusSafely(config, status);
        try {
          await catalog?.markMaintenance(candidate.namespace, plan.jobName, new Date(completedAt));
        } catch {
          // Catalog maintenance touches are best-effort status metadata.
        }
      }
    } catch (error) {
      const completedAt = new Date().toISOString();
      const status: NamespaceMaintenanceRunStatus = {
        namespace: candidate.namespace,
        jobName: plan.jobName,
        state: "failed",
        reason: "job_failed",
        startedAt,
        completedAt,
        error: maintenanceErrorDetail(error),
      };
      statuses.push(status);
      await recordNamespaceMaintenanceStatusSafely(config, status);
    } finally {
      await lock.release().catch(() => undefined);
    }
  }

  return {
    jobName: plan.jobName,
    generatedAt: new Date().toISOString(),
    ran: statuses.filter((s) => s.state === "ran").length,
    skipped: statuses.filter((s) => s.state === "skipped").length,
    failed: statuses.filter((s) => s.state === "failed").length,
    statuses,
  };
}

export async function runNamespaceMaintenanceBatchPlan(
  config: PluginConfig,
  plan: NamespaceMaintenancePlan,
  runner: (candidates: NamespaceMaintenanceCandidate[]) => Promise<NamespaceMaintenanceBatchRunResult | undefined>,
  catalog?: NamespaceCatalog,
  options: NamespaceMaintenanceBatchRunOptions = {}
): Promise<NamespaceMaintenanceSummary> {
  const statuses: NamespaceMaintenanceRunStatus[] = [];

  for (const skipped of plan.skipped) {
    if (skipped.namespace === "*") continue;
    const now = new Date().toISOString();
    const status: NamespaceMaintenanceRunStatus = {
      namespace: skipped.namespace,
      jobName: plan.jobName,
      state: "skipped",
      reason: skipped.reason,
      startedAt: now,
      completedAt: now,
    };
    statuses.push(status);
    await recordNamespaceMaintenanceStatusSafely(config, status);
  }

  const acquired: Array<{
    candidate: NamespaceMaintenanceCandidate;
    lock: LockHandle;
    startedAt: string;
  }> = [];

  try {
    for (const candidate of plan.namespaces) {
      const startedAt = new Date().toISOString();
      const lock = await tryAcquireNamespaceMaintenanceLock(config, plan.jobName, candidate.namespace);
      if (!lock) {
        const completedAt = new Date().toISOString();
        const status: NamespaceMaintenanceRunStatus = {
          namespace: candidate.namespace,
          jobName: plan.jobName,
          state: "skipped",
          reason: "lock_held",
          startedAt,
          completedAt,
        };
        statuses.push(status);
        await recordNamespaceMaintenanceStatusSafely(config, status);
        continue;
      }
      acquired.push({ candidate, lock, startedAt });
    }
  } catch (error) {
    await Promise.all(acquired.map(({ lock }) => lock.release().catch(() => undefined)));
    throw error;
  }

  if (options.requireAllLocks && acquired.length > 0 && acquired.length < plan.namespaces.length) {
    for (const { candidate, startedAt } of acquired) {
      const completedAt = new Date().toISOString();
      const status: NamespaceMaintenanceRunStatus = {
        namespace: candidate.namespace,
        jobName: plan.jobName,
        state: "skipped",
        reason: "batch_lock_incomplete",
        startedAt,
        completedAt,
      };
      statuses.push(status);
      await recordNamespaceMaintenanceStatusSafely(config, status);
    }
    await Promise.all(acquired.map(({ lock }) => lock.release().catch(() => undefined)));
    return {
      jobName: plan.jobName,
      generatedAt: new Date().toISOString(),
      ran: statuses.filter((s) => s.state === "ran").length,
      skipped: statuses.filter((s) => s.state === "skipped").length,
      failed: statuses.filter((s) => s.state === "failed").length,
      statuses,
    };
  }

  if (acquired.length === 0) {
    return {
      jobName: plan.jobName,
      generatedAt: new Date().toISOString(),
      ran: statuses.filter((s) => s.state === "ran").length,
      skipped: statuses.filter((s) => s.state === "skipped").length,
      failed: statuses.filter((s) => s.state === "failed").length,
      statuses,
    };
  }

  try {
    const result = await withNamespaceMaintenanceLockHeartbeat(
      config,
      acquired.map(({ lock }) => lock),
      () => runner(acquired.map(({ candidate }) => candidate)),
    );
    for (const { candidate, startedAt } of acquired) {
      const completedAt = new Date().toISOString();
      const status: NamespaceMaintenanceRunStatus = {
        namespace: candidate.namespace,
        jobName: plan.jobName,
        state: "ran",
        startedAt,
        completedAt,
        itemCount: itemCountForNamespace(result, candidate.namespace),
      };
      statuses.push(status);
      await recordNamespaceMaintenanceStatusSafely(config, status);
      try {
        await catalog?.markMaintenance(candidate.namespace, plan.jobName, new Date(completedAt));
      } catch {
        // Catalog maintenance touches are best-effort status metadata.
      }
    }
  } catch (error) {
    const skipReason = options.skipReasonForError?.(error);
    for (const { candidate, startedAt } of acquired) {
      const completedAt = new Date().toISOString();
      const status: NamespaceMaintenanceRunStatus = skipReason
        ? {
            namespace: candidate.namespace,
            jobName: plan.jobName,
            state: "skipped",
            reason: skipReason,
            startedAt,
            completedAt,
          }
        : {
            namespace: candidate.namespace,
            jobName: plan.jobName,
            state: "failed",
            reason: "job_failed",
            startedAt,
            completedAt,
            error: maintenanceErrorDetail(error),
          };
      statuses.push(status);
      await recordNamespaceMaintenanceStatusSafely(config, status);
    }
  } finally {
    await Promise.all(acquired.map(({ lock }) => lock.release().catch(() => undefined)));
  }

  return {
    jobName: plan.jobName,
    generatedAt: new Date().toISOString(),
    ran: statuses.filter((s) => s.state === "ran").length,
    skipped: statuses.filter((s) => s.state === "skipped").length,
    failed: statuses.filter((s) => s.state === "failed").length,
    statuses,
  };
}

function itemCountForNamespace(
  result: NamespaceMaintenanceBatchRunResult | undefined,
  namespace: string,
): number | undefined {
  const itemCounts = result?.itemCounts;
  if (itemCounts instanceof Map) return itemCounts.get(namespace);
  if (itemCounts && Object.prototype.hasOwnProperty.call(itemCounts, namespace)) {
    return itemCounts[namespace];
  }
  return result?.itemCount;
}

/**
 * Namespace maintenance fanout coordinator (issue #1500).
 *
 * Builds on the namespace-aware maintenance planner (#1499 / #1517) to fan out
 * the REMAINING background maintenance jobs — dreams, pattern reinforcement,
 * governance/lifecycle, contradiction scans, semantic/causal consolidation,
 * graph decay, fact archival, tier migration — across all maintained
 * namespaces.
 *
 * The planner (`namespace-planner.ts`) already handles namespace discovery
 * (configured + catalog), per-kind gating, cycle budgeting, per-job+namespace
 * locking, status recording, and catalog maintenance timestamps. QMD
 * maintenance was wired through it in #1517. This module standardizes the
 * per-job adapter pattern so every other maintenance job can be fanned out
 * with one call, and aggregates per-namespace health for doctor/dashboard.
 *
 * Design contract (issue #1500 compatibility requirements):
 * - Existing direct `runJob({ namespace })` calls continue to work unchanged.
 * - Namespaces disabled: fanout is a no-op (the planner returns only the
 *   default namespace; jobs run exactly as before).
 * - `maintenanceNamespaceFanoutEnabled: false`: fanout is a no-op.
 * - A failure in one namespace must not abort other namespaces (the planner
 *   already isolates per-namespace failures).
 * - Per-namespace locks prevent duplicate concurrent runs (planner-provided).
 */

import { resolveNamespaceCapabilities } from "../capabilities.js";
import type { NamespaceCatalog } from "../namespaces/catalog.js";
import type { PluginConfig } from "../types.js";
import { resolveConversationContextCapabilities } from "../capabilities.js";
import {
  planNamespaceMaintenance,
  readNamespaceMaintenanceLastRanStatuses,
  readNamespaceMaintenanceStatuses,
  runNamespaceMaintenancePlan,
  type NamespaceMaintenanceCandidate,
  type NamespaceMaintenanceRunStatus,
  type NamespaceMaintenanceSummary,
} from "./namespace-planner.js";

/**
 * Standard maintenance job names fanned out across namespaces.
 *
 * These strings are used as the `jobName` key in:
 * - per-namespace status files (`state/namespace-maintenance-status/<job>/...`)
 * - catalog `lastMaintenanceAt[jobName]` timestamps
 * - per-job+namespace lock files (`state/maintenance-locks/<job>/...`)
 *
 * Keeping them centralized ensures the doctor, CLI, and dashboard all report
 * against the same keys.
 */
export const NAMESPACE_MAINTENANCE_JOBS = [
  "qmd",
  "pattern-reinforcement",
  "contradiction-scan",
  "semantic-consolidation",
  "governance",
  "lifecycle",
  "graph-decay",
  "fact-archival",
  "tier-migration",
] as const;

export type NamespaceMaintenanceStandardJob =
  (typeof NAMESPACE_MAINTENANCE_JOBS)[number];

/**
 * Context passed to a fanout job runner. The runner receives the per-namespace
 * candidate (namespace name, kind, storage dir) and a storage resolver that
 * the orchestrator wires to `storageRouter.storageFor(namespace)`.
 *
 * The storage resolver is intentionally typed as `unknown` here so this module
 * does not depend on the `StorageManager` class — the orchestrator provides the
 * typed resolver. This keeps the fanout module free of orchestrator/storage
 * imports and unit-testable with a stub.
 */
export interface NamespaceMaintenanceFanoutRunnerContext {
  config: PluginConfig;
  candidate: NamespaceMaintenanceCandidate;
  resolveStorage: (namespace: string) => Promise<unknown>;
}

/**
 * Result returned by a fanout job runner. `itemCount` is optional and
 * domain-specific (e.g. memories scanned, edges decayed, embeddings updated).
 *
 * `skipped`/`skipReason`: when a runner performs no work for a namespace
 * (e.g. the job's own cadence gate throttled it), set `skipped: true`. The
 * planner records the namespace as `state: "skipped"` and does NOT touch
 * the catalog's `lastMaintenanceAt`, so a throttled namespace is not
 * falsely reported as maintained.
 */
export interface NamespaceMaintenanceFanoutRunnerResult {
  itemCount?: number;
  skipped?: boolean;
  skipReason?: string;
}

export type NamespaceMaintenanceFanoutRunner = (
  ctx: NamespaceMaintenanceFanoutRunnerContext,
) => Promise<NamespaceMaintenanceFanoutRunnerResult | undefined>;

export interface RunNamespaceMaintenanceFanoutOptions {
  config: PluginConfig;
  catalog?: NamespaceCatalog;
  jobName: string;
  runner: NamespaceMaintenanceFanoutRunner;
  resolveStorage: (namespace: string) => Promise<unknown>;
  /**
   * When `false`, skip fanout entirely and return a zero-summary without
   * touching the planner or locks. This lets callers gate fanout on
   * per-job config (e.g. `semanticConsolidationEnabled`) without repeating
   * the namespace-discovery logic.
   */
  enabled?: boolean;
}

/**
 * Fan out a single maintenance job across all maintained namespaces.
 *
 * This is the primary entry point for wiring a maintenance job through the
 * namespace-aware planner. It:
 * 1. Plans which namespaces should be maintained (configured + catalog,
 *    budgeted, kind-gated).
 * 2. Runs the job per-namespace through `runNamespaceMaintenancePlan`, which
 *    acquires per-job+namespace locks, records status files, and touches the
 *    catalog's `lastMaintenanceAt`.
 *
 * When namespaces are disabled or fanout is off, the planner returns only the
 * default namespace, so the job runs exactly once against default storage —
 * preserving single-user behavior.
 */
export async function runNamespaceMaintenanceFanout(
  options: RunNamespaceMaintenanceFanoutOptions,
): Promise<NamespaceMaintenanceSummary> {
  if (options.enabled === false) {
    return {
      jobName: options.jobName,
      generatedAt: new Date().toISOString(),
      ran: 0,
      skipped: 0,
      failed: 0,
      statuses: [],
    };
  }

  const plan = await planNamespaceMaintenance(options.config, {
    jobName: options.jobName,
    catalog: options.catalog,
  });

  return runNamespaceMaintenancePlan(
    options.config,
    plan,
    async (candidate) => {
      return options.runner({
        config: options.config,
        candidate,
        resolveStorage: options.resolveStorage,
      });
    },
    options.catalog,
  );
}

// ---------------------------------------------------------------------------
// Health summary for doctor / dashboard / CLI
// ---------------------------------------------------------------------------

export interface NamespaceMaintenanceJobHealth {
  jobName: string;
  ran: number;
  skipped: number;
  failed: number;
  lastRunAt: string | null;
  namespaces: NamespaceMaintenanceRunStatus[];
}

export interface NamespaceMaintenanceHealthSummary {
  generatedAt: string;
  fanoutEnabled: boolean;
  namespacesEnabled: boolean;
  maxNamespacesPerCycle: number;
  jobs: NamespaceMaintenanceJobHealth[];
  totalRan: number;
  totalSkipped: number;
  totalFailed: number;
}

/**
 * Read all per-namespace maintenance status files and aggregate them into a
 * health summary suitable for `remnic doctor` and the admin dashboard.
 *
 * This is a pure read operation — it never runs maintenance or acquires locks.
 */
export async function summarizeNamespaceMaintenanceHealth(
  config: PluginConfig,
): Promise<NamespaceMaintenanceHealthSummary> {
  const generatedAt = new Date().toISOString();
  const statuses = await readNamespaceMaintenanceStatuses(config);
  // Merge last-successful-run records so lastRunAt reflects the most recent
  // successful maintenance, not just the latest (possibly skipped/failed)
  // outcome. The latest status file is overwritten on every run; without
  // this merge a namespace that ran then got budget-skipped shows ran=0 /
  // lastRunAt=null (review #1622: preserve last successful run).
  const lastRanStatuses = await readNamespaceMaintenanceLastRanStatuses(config);
  const lastRanByJobNs = new Map<string, NamespaceMaintenanceRunStatus>();
  for (const lr of lastRanStatuses) {
    lastRanByJobNs.set(`${lr.jobName}\u0000${lr.namespace}`, lr);
  }

  const byJob = new Map<string, NamespaceMaintenanceRunStatus[]>();
  for (const status of statuses) {
    const bucket = byJob.get(status.jobName);
    if (bucket) {
      bucket.push(status);
    } else {
      byJob.set(status.jobName, [status]);
    }
  }

  const knownJobs = new Set<string>(NAMESPACE_MAINTENANCE_JOBS);
  // Include any job names seen in status files that are not in the standard
  // set (e.g. custom jobs registered by the orchestrator) so the doctor does
  // not silently hide them.
  for (const jobName of byJob.keys()) {
    knownJobs.add(jobName);
  }

  const jobs: NamespaceMaintenanceJobHealth[] = [];
  let totalRan = 0;
  let totalSkipped = 0;
  let totalFailed = 0;

  for (const jobName of [...knownJobs].sort()) {
    const jobStatuses = byJob.get(jobName) ?? [];
    const ran = jobStatuses.filter((s) => s.state === "ran").length;
    const skipped = jobStatuses.filter((s) => s.state === "skipped").length;
    const failed = jobStatuses.filter((s) => s.state === "failed").length;
    // Consider BOTH the latest outcome and the last successful run so a
    // namespace that ran then was later skipped still reports lastRunAt.
    const candidates: string[] = [];
    for (const st of jobStatuses) {
      if (typeof st.completedAt === "string") candidates.push(st.completedAt);
      const lr = lastRanByJobNs.get(`${jobName}\u0000${st.namespace}`);
      if (lr && typeof lr.completedAt === "string") candidates.push(lr.completedAt);
    }
    const lastRunAt = candidates.sort().at(-1) ?? null;

    totalRan += ran;
    totalSkipped += skipped;
    totalFailed += failed;

    jobs.push({
      jobName,
      ran,
      skipped,
      failed,
      lastRunAt,
      namespaces: jobStatuses,
    });
  }

  return {
    generatedAt,
    fanoutEnabled: resolveConversationContextCapabilities(config).maintenanceNamespaceFanout !== false,
    namespacesEnabled: resolveNamespaceCapabilities(config).namespaces,
    maxNamespacesPerCycle: config.maintenanceMaxNamespacesPerCycle,
    jobs,
    totalRan,
    totalSkipped,
    totalFailed,
  };
}

/**
 * Format the health summary as human-readable text for the CLI.
 */
export function formatNamespaceMaintenanceHealthText(
  summary: NamespaceMaintenanceHealthSummary,
): string {
  const lines: string[] = [
    "=== Namespace Maintenance ===",
    "",
    `  fanout:        ${summary.fanoutEnabled ? "enabled" : "disabled"}`,
    `  namespaces:    ${summary.namespacesEnabled ? "enabled" : "disabled"}`,
    `  max/cycle:     ${summary.maxNamespacesPerCycle}`,
    `  total ran:     ${summary.totalRan}`,
    `  total skipped: ${summary.totalSkipped}`,
    `  total failed:  ${summary.totalFailed}`,
    "",
  ];

  if (summary.totalRan === 0 && summary.totalSkipped === 0 && summary.totalFailed === 0) {
    lines.push("  (no maintenance status recorded yet)");
    return lines.join("\n");
  }

  lines.push("  Per-job breakdown:");
  for (const job of summary.jobs) {
    const parts = [
      `ran=${job.ran}`,
      `skipped=${job.skipped}`,
      `failed=${job.failed}`,
    ];
    if (job.lastRunAt) {
      parts.push(`last=${job.lastRunAt}`);
    }
    lines.push(`    ${job.jobName}: ${parts.join(", ")}`);
    // Surface failed namespaces with their reason/error so operators know
    // WHAT to fix without rerunning with --json (review #1622).
    const failedNs = job.namespaces.filter((n) => n.state === "failed");
    for (const ns of failedNs) {
      const detail = ns.error ? `: ${ns.error}` : "";
      lines.push(`      ! ${ns.namespace} failed (reason=${ns.reason ?? "unknown"})${detail}`);
    }
  }

  return lines.join("\n");
}

import { resolveNamespaceCapabilities } from "../capabilities.js";
import type { PluginConfig } from "../types.js";
import { isLikelyUnsafeRegex } from "../routing/engine.js";
import { normalizeNamespaceIdentity } from "./identity.js";
const MAX_REGEX_SESSION_KEY_LENGTH = 512;

function compileSafePrincipalRegex(pattern: string): RegExp | null {
  if (isLikelyUnsafeRegex(pattern)) return null;
  try {
    return new RegExp(pattern);
  } catch {
    return null;
  }
}

export function resolvePrincipal(sessionKey: string | undefined, config: PluginConfig): string | undefined {
  if (!resolveNamespaceCapabilities(config).namespaces) return "default";
  const sk = typeof sessionKey === "string" && sessionKey.trim().length > 0
    ? sessionKey
    : "";
  const mode = config.principalFromSessionKeyMode;
  const rules = config.principalFromSessionKeyRules ?? [];

  if (!sk) return undefined;

  if (mode === "prefix") {
    for (const r of rules) {
      if (sk.startsWith(r.match)) return r.principal;
    }
  } else if (mode === "map") {
    for (const r of rules) {
      if (sk === r.match) return r.principal;
    }
  } else if (mode === "regex") {
    if (sk.length <= MAX_REGEX_SESSION_KEY_LENGTH) {
      for (const r of rules) {
        const re = compileSafePrincipalRegex(r.match);
        if (re?.test(sk)) {
          return r.principal;
        }
      }
    }
  }

  // Fallback heuristic: "agent:<agentId>:<channelType>:..."
  const parts = sk.split(":");
  if (parts.length >= 2 && parts[0] === "agent") {
    const agentId = parts[1];
    if (agentId && agentId.length > 0) return agentId;
  }
  return "default";
}

export function canReadNamespace(principal: string | undefined, namespace: string, config: PluginConfig): boolean {
  if (!resolveNamespaceCapabilities(config).namespaces) return true;
  if (!principal) return false;
  const identity = normalizeNamespaceIdentity(namespace);
  const policy = config.namespacePolicies.find((p) => normalizeNamespaceIdentity(p.name) === identity);
  if (!policy) {
    return identity === normalizeNamespaceIdentity(config.defaultNamespace) ||
      identity === normalizeNamespaceIdentity(config.sharedNamespace);
  }
  return policy.readPrincipals.includes(principal) || policy.readPrincipals.includes("*");
}

export function canWriteNamespace(principal: string | undefined, namespace: string, config: PluginConfig): boolean {
  if (!resolveNamespaceCapabilities(config).namespaces) return true;
  if (!principal) return false;
  const identity = normalizeNamespaceIdentity(namespace);
  const policy = config.namespacePolicies.find((p) => normalizeNamespaceIdentity(p.name) === identity);
  if (!policy) return identity === normalizeNamespaceIdentity(config.defaultNamespace);
  return policy.writePrincipals.includes(principal) || policy.writePrincipals.includes("*");
}

/**
 * Config-time namespace-policy lint (issue #1888 improvement 3). Principal-
 * agnostic mirror of {@link canWriteNamespace}: true when the namespace is
 * writable by AT LEAST ONE principal. When namespace enforcement is off every
 * write is allowed. Otherwise an explicit `namespacePolicies` entry takes
 * precedence (exactly as `canWriteNamespace`): with a matching policy the
 * namespace is covered only if that policy grants at least one non-blank
 * writer — even when the name equals `defaultNamespace`; without a policy it
 * is covered only if it IS the `defaultNamespace`. The `sharedNamespace` is
 * NOT implicitly writable (matching
 * `canWriteNamespace`), and a policy entry with no `writePrincipals` grants
 * nobody. A configured namespace that is NOT covered is writable for no one,
 * so every write to it is rejected by the ACL and dead-lettered — `remnic
 * doctor` warns on that before a session silently loses memory.
 */
export function isNamespacePolicyCovered(namespace: string, config: PluginConfig): boolean {
  if (!resolveNamespaceCapabilities(config).namespaces) return true;
  // An explicit policy wins over the default fallback (exactly as
  // canWriteNamespace), so a policy naming the default with no writers is NOT
  // covered. Only fall back to defaultNamespace when no policy matches.
  const identity = normalizeNamespaceIdentity(namespace);
  const policy = config.namespacePolicies.find((p) => normalizeNamespaceIdentity(p.name) === identity);
  if (!policy) return identity === normalizeNamespaceIdentity(config.defaultNamespace);
  return policy.writePrincipals.some((w) => w.trim().length > 0);
}

/**
 * Default "self" namespace for a principal.
 *
 * Heuristic:
 * - If there's a namespace policy with the same name as the principal, use it.
 * - Otherwise use config.defaultNamespace.
 */
export function defaultNamespaceForPrincipal(principal: string | undefined, config: PluginConfig): string {
  if (!resolveNamespaceCapabilities(config).namespaces) return config.defaultNamespace;
  if (!principal) return config.defaultNamespace;
  const policy = config.namespacePolicies.find(
    (p) => normalizeNamespaceIdentity(p.name) === normalizeNamespaceIdentity(principal),
  );
  return policy ? normalizeNamespaceIdentity(policy.name) : config.defaultNamespace;
}

export function recallNamespacesForPrincipal(principal: string | undefined, config: PluginConfig): string[] {
  const out: string[] = [];
  if (!resolveNamespaceCapabilities(config).namespaces) return [config.defaultNamespace];
  if (!principal) return out;

  const selfNs = defaultNamespaceForPrincipal(principal, config);
  if (config.defaultRecallNamespaces.includes("self") && canReadNamespace(principal, selfNs, config)) {
    out.push(selfNs);
  }
  if (config.defaultRecallNamespaces.includes("shared") && canReadNamespace(principal, config.sharedNamespace, config)) {
    out.push(config.sharedNamespace);
  }

  for (const p of config.namespacePolicies) {
    if (p.includeInRecallByDefault && canReadNamespace(principal, p.name, config)) {
      if (!out.includes(p.name)) out.push(p.name);
    }
  }

  return out;
}

/**
 * Namespaces a principal may attribute a citation to: the default-recall
 * namespaces, every readable policy namespace, and the readable built-in
 * default/shared namespaces — which `defaultRecallNamespaces` can omit even
 * though `canReadNamespace` grants access (#2020).
 */
export function citationAuthorizedNamespaces(
  principal: string | undefined,
  config: PluginConfig,
): string[] {
  return Array.from(
    new Set([
      ...recallNamespacesForPrincipal(principal, config),
      ...config.namespacePolicies
        .filter((p) => canReadNamespace(principal, p.name, config))
        .map((p) => p.name),
      ...[config.defaultNamespace, config.sharedNamespace].filter((ns) =>
        canReadNamespace(principal, ns, config),
      ),
    ]),
  );
}

/**
 * Coding-agent namespace overlay (issue #569 PR 2 + PR 3).
 *
 * Given a `CodingContext` (from `resolveGitContext`) and a `CodingModeConfig`,
 * returns the namespace that recall + write paths should use — or `null` when
 * no overlay should apply (coding mode disabled, no context supplied, or
 * feature flags off).
 *
 * PR 2 ships the project overlay. PR 3 will add the branch overlay; the
 * function here already handles both flags so the schema / types / plumbing
 * don't have to change a second time when branch-scope lands.
 *
 * Pure function — no orchestrator, no config side-effects. Callers keep rule
 * 42 (read + write through same namespace layer) by consulting the same
 * function on both paths.
 */

import type { CodingContext, CodingModeConfig } from "../types.js";
import { stableHash } from "./git-context.js";

export interface CodingNamespaceOverlay {
  /**
   * Effective namespace to use for this session's memory operations. When
   * `branchScope` is on, takes the form `project:<id>/branch:<b>`; otherwise
   * `project:<id>`.
   */
  namespace: string;
  /**
   * Read fallbacks — additional namespaces a caller should include in recall
   * so that, for example, a branch-scoped session still sees project-level
   * memories that were written before the branch scope was enabled.
   *
   * Writes MUST go to `namespace` only; these are read-side only.
   *
   * Introduced to carry PR 3's branch→project fallback; PR 2 returns an empty
   * array here.
   */
  readFallbacks: string[];
  /**
   * `"project"` when only project scope applies, `"branch"` when branch scope
   * is also layered on. Used for diagnostics (`remnic doctor`) and logging.
   */
  scope: "project" | "branch";
}

// ──────────────────────────────────────────────────────────────────────────
// Sanitization
// ──────────────────────────────────────────────────────────────────────────

/**
 * Normalize a projectId / branch fragment so the resulting namespace passes
 * the router's `isSafeRouteNamespace` check (`[A-Za-z0-9._-]{1,64}`).
 *
 * Namespaces are used as filesystem directory names and must not contain
 * path separators (`/`, `\`) or colons — so both `:` and `/` collapse to `-`.
 * The project-id format `origin:<8hex>` and branch names like `feat/x` both
 * flow through this helper before hitting the storage layer.
 *
 * NOT a security boundary — projectIds come from `resolveGitContext` (known
 * hex), and branch names come from local git. This defends against corrupt
 * input only.
 */
/**
 * Single-pass sanitization — each input character is visited exactly once.
 * Rewriting as an explicit loop (instead of chained `replace()` calls with
 * greedy quantifiers) closes the polynomial-backtracking surface that
 * CodeQL flagged on patterns like `-+` and `^-+|-+$`.
 */
export function sanitizeFragment(input: string): string {
  if (typeof input !== "string") return "";
  const trimmed = input.trim().toLowerCase();
  let out = "";
  let prevIsDash = true; // suppress leading dashes
  for (let i = 0; i < trimmed.length; i += 1) {
    const c = trimmed[i]!;
    const cc = trimmed.charCodeAt(i);
    const isSafe =
      (cc >= 48 && cc <= 57) /* 0-9 */ ||
      (cc >= 97 && cc <= 122) /* a-z */ ||
      cc === 46 /* . */ ||
      cc === 95 /* _ */;
    if (isSafe) {
      out += c;
      prevIsDash = false;
    } else if (!prevIsDash) {
      out += "-";
      prevIsDash = true;
    }
  }
  // Strip a single trailing dash introduced by the final run of unsafe chars.
  if (out.endsWith("-")) out = out.slice(0, -1);
  return out;
}

/**
 * Cap to the router's per-namespace upper bound.
 *
 * Raw truncation alone would collapse distinct long inputs that differ near
 * the end (e.g. two `feat/...` branches with different suffixes) into the
 * same namespace — silently mixing recall/write state across branches or
 * projects. When truncation is needed, we append a short deterministic
 * hash suffix (`-<8hex>`) derived from the FULL pre-truncated value so
 * collisions only happen under true hash collisions, not simple prefix
 * overlap.
 *
 * The tail is trimmed to leave room for the separator and 8-char hash and
 * any trailing `-` introduced by the slice is stripped so the final
 * character before `-<hash>` is always alphanumeric or `.`/`_`.
 */
const MAX_NAMESPACE_LEN = 64;
const HASH_SUFFIX_LEN = 9; // "-" + 8 hex chars

function capLength(value: string): string {
  if (value.length <= MAX_NAMESPACE_LEN) return value;
  // Reuse the FNV-1a 32-bit hash from git-context — one canonical
  // implementation, one set of edge-case fixes. Uses Math.imul for
  // correct 32-bit wrap-around, which plain `*` would not guarantee
  // for the largest intermediate products.
  const hash = stableHash(value);
  // Trim trailing '-' with a linear, non-backtracking loop. A regex
  // like `-+$` is linear too, but an explicit loop keeps CodeQL happy
  // about polynomial backtracking warnings when several `\-+` patterns
  // appear in the same module.
  let end = MAX_NAMESPACE_LEN - HASH_SUFFIX_LEN;
  while (end > 0 && value.charCodeAt(end - 1) === 45 /* '-' */) end -= 1;
  return `${value.slice(0, end)}-${hash}`;
}

/**
 * Produce the project-scope namespace name. Exported for tests and for
 * `remnic doctor` to render. Guaranteed to satisfy `isSafeRouteNamespace`:
 * no `/`, no `:`, lowercase only, length-capped to 64 chars.
 */
export function projectNamespaceName(projectId: string): string {
  const frag = sanitizeFragment(projectId);
  return capLength(`project-${frag || "unknown"}`);
}

export function projectTagProjectId(projectTag: string): string {
  const trimmed = projectTag.trim();
  const frag = sanitizeFragment(trimmed);
  const disambig = trimmed.length > 0 && frag !== trimmed;
  const suffix = disambig ? `-${stableHash(trimmed)}` : "";
  return `tag:${frag || "unknown"}${suffix}`;
}

/**
 * Preserve case when sanitizing a principal-derived base namespace. The
 * router's `isSafeRouteNamespace` check accepts `[A-Za-z0-9._-]{1,64}`, so
 * upper-case characters in the principal name are safe and MUST be kept to
 * avoid colliding two otherwise-distinct principals (e.g. `Alice` vs
 * `alice`) into the same combined namespace.
 *
 * Otherwise identical to `sanitizeFragment`: single-pass, linear, no
 * polynomial-backtracking quantifiers, unsafe chars collapse to `-` with
 * leading/trailing dashes suppressed.
 */
function sanitizeBaseFragment(input: string): string {
  if (typeof input !== "string") return "";
  const trimmed = input.trim();
  let out = "";
  let prevIsDash = true;
  for (let i = 0; i < trimmed.length; i += 1) {
    const c = trimmed[i]!;
    const cc = trimmed.charCodeAt(i);
    const isSafe =
      (cc >= 48 && cc <= 57) /* 0-9 */ ||
      (cc >= 65 && cc <= 90) /* A-Z */ ||
      (cc >= 97 && cc <= 122) /* a-z */ ||
      cc === 46 /* . */ ||
      cc === 95 /* _ */;
    if (isSafe) {
      out += c;
      prevIsDash = false;
    } else if (!prevIsDash) {
      out += "-";
      prevIsDash = true;
    }
  }
  if (out.endsWith("-")) out = out.slice(0, -1);
  return out;
}

/**
 * Combine a principal-derived base namespace (e.g. `default`, `alice`) with a
 * coding-agent overlay namespace (e.g. `project-origin-abcd1234`). The result
 * is a single safe-route token that preserves principal isolation (CLAUDE.md
 * rule 42: read + write must resolve through the same namespace layer — and
 * here, through the same principal-scoped prefix) while layering project or
 * project/branch scope on top.
 *
 * Multiple principals working in the same repo thus get distinct namespaces:
 *
 *   alice + project-origin-ab12  →  alice-project-origin-ab12
 *   bob   + project-origin-ab12  →  bob-project-origin-ab12
 *   Alice + project-origin-ab12  →  Alice-project-origin-ab12 (distinct)
 *
 * The base fragment preserves case so `Alice` and `alice` remain distinct;
 * the overlay fragment is still lowercase-sanitized because it derives from
 * deterministic, pre-lowercased git hashes.
 *
 * Output is re-capped through `capLength` so a very long base + overlay
 * combination still fits inside `isSafeRouteNamespace` (≤ 64 chars). The
 * deterministic hash suffix on truncation keeps distinct inputs distinct.
 */
export function combineNamespaces(base: string, overlay: string): string {
  const baseFrag = sanitizeBaseFragment(base);
  const overlayFrag = sanitizeFragment(overlay);
  if (!baseFrag) return capLength(overlayFrag || "unknown");
  if (!overlayFrag) return capLength(baseFrag);
  return capLength(`${baseFrag}-${overlayFrag}`);
}

/**
 * Produce the branch-scope namespace name. Format:
 * `project-<id>-branch-<name>[-<hash>]`. Uses `-` as the structural separator
 * rather than `/` or `:` so the result is a single safe route-namespace
 * token that can be used directly as a filesystem directory.
 *
 * Two failure modes must not collapse distinct branches to one namespace:
 *
 *   1. Sanitization is lossy (`feat/x` and `feat-x` both sanitize to
 *      `feat-x`; `Feature` and `feature` both sanitize to `feature`). When
 *      sanitization rewrote any character, we append a short hash of the
 *      RAW branch so distinct inputs stay distinct.
 *   2. Truncation is applied when the total exceeds 64 chars. In that
 *      mode `capLength` appends its own hash of the full pre-truncated
 *      value.
 *
 * Long branches that also sanitize may receive both kinds of hashes — that
 * is acceptable: the router only requires the result be unique and
 * deterministic, and the two hashes derive from different domains so they
 * don't conflict.
 */
export function branchNamespaceName(projectId: string, branch: string): string {
  const projectFrag = sanitizeFragment(projectId);
  const trimmedBranch = branch.trim();
  const branchFrag = sanitizeFragment(trimmedBranch);
  // Lossy-sanitization disambiguator: append hash of the raw (trimmed)
  // branch when sanitization actually changed the string. Preserves
  // distinctness across `feat/x` vs `feat-x` and `Feature` vs `feature`.
  // The comparison uses the raw trimmed value (NOT `.toLowerCase()`) so
  // case-only variants are treated as lossy and receive their own hash.
  // Empty / already-safe-lowercase inputs get no hash so the common case
  // stays readable.
  const disambig = trimmedBranch.length > 0 && branchFrag !== trimmedBranch;
  const base = `project-${projectFrag || "unknown"}-branch-${branchFrag || "unknown"}`;
  const suffixed = disambig ? `${base}-${stableHash(trimmedBranch)}` : base;
  return capLength(suffixed);
}

// ──────────────────────────────────────────────────────────────────────────
// Overlay resolver
// ──────────────────────────────────────────────────────────────────────────

/**
 * Compute the namespace overlay for a session.
 *
 * Returns `null` when no overlay applies — callers should then use their
 * existing `defaultNamespaceForPrincipal(...)` result unchanged. This keeps
 * CLAUDE.md #30 (escape hatch): setting `codingMode.projectScope: false`
 * exactly restores pre-#569 behaviour at every call site.
 *
 * @param codingContext — git context from the connector
 * @param config — coding mode flags (projectScope, branchScope, globalFallback)
 * @param defaultNamespace — retained for call-site compatibility; no longer
 *   used. The global fallback is expressed as an empty-string sentinel in
 *   `readFallbacks`, which `combineNamespaces(principal, "")` resolves to the
 *   principal's own namespace at the call site.
 */
export function resolveCodingNamespaceOverlay(
  codingContext: CodingContext | null | undefined,
  config: Pick<CodingModeConfig, "projectScope" | "branchScope" | "globalFallback">,
  defaultNamespace?: string,
): CodingNamespaceOverlay | null {
  // No context supplied (session isn't in a git repo, or connector didn't
  // attach one) → no overlay.
  if (!codingContext) return null;

  // Project scope disabled → no overlay at all. Branch scope depends on
  // project scope being on; there is no branch-only mode.
  if (!config.projectScope) return null;

  // Require a non-empty projectId — defensive.
  const projectId = typeof codingContext.projectId === "string" ? codingContext.projectId.trim() : "";
  if (!projectId) return null;

  const projectNs = projectNamespaceName(projectId);

  // Root/global namespace fallback: when `globalFallback` is true, include
  // the principal's self namespace in readFallbacks so cross-project knowledge
  // remains visible. CLAUDE.md #30: the gate is `globalFallback` — set to
  // false for strict project isolation.
  //
  // The fallback value is "" (empty string), NOT the defaultNamespace name.
  // The orchestrator passes each fallback through combineNamespaces(principal, fallback),
  // and combineNamespaces(base, "") returns base unchanged — yielding the
  // principal's own namespace. Using the actual namespace name (e.g., "default")
  // would produce "default-default" after combination, missing the target.
  const includeRoot = config.globalFallback === true;

  // Branch-scope layering (PR 3):
  //   - only when config.branchScope is explicitly true
  //   - only when we actually have a branch (null in detached HEAD)
  //   - project namespace becomes a read fallback so project-level memories
  //     remain visible from any branch (deliberate asymmetry — branch writes
  //     don't leak up, but project reads leak down).
  //   - when globalFallback is on, the root namespace is also appended so
  //     globally useful memories surface in every branch.
  if (config.branchScope && typeof codingContext.branch === "string" && codingContext.branch.length > 0) {
    const branchNs = branchNamespaceName(projectId, codingContext.branch);
    const fallbacks = [projectNs];
    if (includeRoot) fallbacks.push("");
    return {
      namespace: branchNs,
      readFallbacks: fallbacks,
      scope: "branch",
    };
  }

  return {
    namespace: projectNs,
    readFallbacks: includeRoot ? [""] : [],
    scope: "project",
  };
}

// ──────────────────────────────────────────────────────────────────────────
// Diagnostics (issue #569 PR 3 + PR 8)
// ──────────────────────────────────────────────────────────────────────────

export interface CodingScopeDescription {
  /** "none" when no overlay is active; otherwise the resolved scope level. */
  scope: "none" | "project" | "branch";
  /** Project id (raw, not sanitized) when a context is attached. */
  projectId: string | null;
  /** Branch name (raw, not sanitized) when available. */
  branch: string | null;
  /** Effective namespace writes route to. `null` when no overlay applies. */
  effectiveNamespace: string | null;
  /** Read fallbacks included in recall (non-empty only when branch-scope is on). */
  readFallbacks: string[];
  /**
   * Why no overlay applies, when `scope === "none"`. One of:
   *   - `"no-context"`  — connector didn't attach a CodingContext
   *   - `"disabled"`   — codingMode.projectScope is false
   *   - `"empty-project"` — codingContext.projectId was empty/whitespace
   */
  disabledReason: "no-context" | "disabled" | "empty-project" | null;
}

/**
 * Human-readable description of the coding-agent scope that currently applies
 * for a session. Consumed by `remnic doctor` (PR 8) and by logs to surface
 * why recall routes where it does.
 *
 * Pure — callers pass the coding context + config they already have.
 */
export function describeCodingScope(
  codingContext: CodingContext | null | undefined,
  config: Pick<CodingModeConfig, "projectScope" | "branchScope" | "globalFallback">,
  defaultNamespace?: string,
): CodingScopeDescription {
  const projectId = codingContext?.projectId ?? null;
  const branch = codingContext?.branch ?? null;

  if (!codingContext) {
    return {
      scope: "none",
      projectId: null,
      branch: null,
      effectiveNamespace: null,
      readFallbacks: [],
      disabledReason: "no-context",
    };
  }
  if (!config.projectScope) {
    return {
      scope: "none",
      projectId,
      branch,
      effectiveNamespace: null,
      readFallbacks: [],
      disabledReason: "disabled",
    };
  }
  const trimmedId = typeof projectId === "string" ? projectId.trim() : "";
  if (!trimmedId) {
    return {
      scope: "none",
      projectId,
      branch,
      effectiveNamespace: null,
      readFallbacks: [],
      disabledReason: "empty-project",
    };
  }

  const overlay = resolveCodingNamespaceOverlay(codingContext, config, defaultNamespace);
  // Unreachable in practice given the guards above, but keep the return
  // shape consistent if the resolver grows new null branches later.
  if (!overlay) {
    return {
      scope: "none",
      projectId,
      branch,
      effectiveNamespace: null,
      readFallbacks: [],
      disabledReason: "disabled",
    };
  }
  return {
    scope: overlay.scope,
    projectId,
    branch,
    effectiveNamespace: overlay.namespace,
    readFallbacks: overlay.readFallbacks,
    disabledReason: null,
  };
}

// ──────────────────────────────────────────────────────────────────────────
// LCM session-key namespacing (#1495)
// ──────────────────────────────────────────────────────────────────────────

/**
 * Reserved structural sentinel for the namespaced LCM `session_id` encoding
 * (#1495 P1). U+001F (UNIT SEPARATOR) is a C0 control character that CANNOT
 * occur in a route namespace (`isSafeRouteNamespace` ⇒ `[A-Za-z0-9._-]{1,64}`,
 * see routing/engine.ts) and does not occur in any legitimate session key, so
 * it is an unforgeable structural marker for the namespace boundary.
 *
 * SECURITY — why this is unforgeable (the #1495 P1 fix):
 * The LCM archive is keyed by the `session_id` STRING (exact `session_id = ?`
 * and prefix `session_id LIKE '<prefix>%'`), NOT physically partitioned by
 * namespace. The previous encoding `${namespace}:${sessionKey}` shared the SAME
 * string space as a raw default-store key, so a caller authorized for the
 * `default` store could pass a raw `sessionKey` equal to another namespace's
 * encoded key (`"<overlay-ns>:<victim-session>"`) and exact-match the victim's
 * rows — a cross-tenant read leak.
 *
 * The new encoding makes the namespaced and default key-spaces PROVABLY
 * DISJOINT:
 *   - Overlay key  = `\x1f<namespace>\x1f<sessionKey>` — always begins with
 *     `\x1f` followed by a NON-`\x1f` character (the namespace is non-empty and
 *     `\x1f`-free). The leading `\x1f<namespace>\x1f` is an unambiguous,
 *     injective frame: the namespace cannot contain `\x1f`, so the second `\x1f`
 *     terminates it without any escaping of the (raw) session key.
 *   - Default key  = the raw `sessionKey`, UNLESS it already begins with the
 *     sentinel, in which case it is escaped to begin with `\x1f\x1f` (see
 *     `escapeDefaultLcmKey`). A default key therefore NEVER matches the overlay
 *     frame `\x1f<non-\x1f>…`.
 * Hence no caller-controlled raw `sessionKey` (default path) can reproduce an
 * overlay key, closing the forgery for BOTH the exact-`session_id` match and the
 * `sessionPrefix` LIKE match (an overlay prefix `\x1f<ns>\x1f<rawPrefix>` stays a
 * valid LIKE-prefix of the overlay full keys, and a default prefix can only
 * LIKE-match default keys).
 *
 * Existing default-store rows need NO migration: legitimate session keys never
 * contain `\x1f`, so `escapeDefaultLcmKey` is a no-op for them and they remain
 * byte-for-byte their raw form. The namespaced encoding is NEW in this
 * unreleased PR, so changing its shape costs nothing.
 */
const LCM_NS_SENTINEL = "\u001f";

/**
 * Make a default-store (raw) LCM key disjoint from the namespaced key-space.
 *
 * Namespaced overlay keys always begin with `\x1f` followed by a non-`\x1f`
 * namespace character. A raw default key collides with that frame ONLY if it
 * begins with `\x1f`. Legitimate session keys never contain `\x1f`, so this is a
 * pure no-op for them; a forged key that begins with `\x1f` is escaped to begin
 * with `\x1f\x1f`, which can never equal an overlay key (whose second character
 * is a `[A-Za-z0-9._-]` namespace char, never `\x1f`).
 */
function escapeDefaultLcmKey(sessionKey: string): string {
  return sessionKey.startsWith(LCM_NS_SENTINEL)
    ? `${LCM_NS_SENTINEL}${sessionKey}`
    : sessionKey;
}

/**
 * Build the LCM/structured-history `session_id` that a write-producing surface
 * archives under, and that a same-session reader must search under, so reads
 * and writes never drift (#1495, CLAUDE.md rule 42).
 *
 * The LCM archive filters strictly by the `session_id` string, so the writer's
 * archival key and the reader's lookup key MUST agree byte-for-byte. The
 * encoding frames the namespace with the reserved {@link LCM_NS_SENTINEL}
 * (`\x1f<namespace>\x1f<sessionKey>`) whenever that namespace diverges from the
 * single-store default; otherwise it passes the (escaped) raw `sessionKey` so
 * single-user / no-overlay deployments keep pre-#1495 behavior exactly. The two
 * key-spaces are provably disjoint, so a caller-controlled raw `sessionKey`
 * cannot forge another namespace's encoded id (see the {@link LCM_NS_SENTINEL}
 * doc comment for the full security rationale).
 *
 * `observe`, compaction flush/record, and the orchestrator recall readers all
 * route through this one helper so a project-scoped (cwd/projectTag) or
 * explicit-namespace session reads its own compressed-history / structured /
 * targeted-fact evidence instead of missing it.
 */
export function lcmSessionKeyForNamespace(
  namespace: string | undefined,
  sessionKey: string | undefined,
  defaultNamespace: string,
): string | undefined {
  if (typeof sessionKey !== "string" || sessionKey.length === 0) return sessionKey;
  if (
    typeof namespace === "string" &&
    namespace.length > 0 &&
    namespace !== defaultNamespace
  ) {
    // Namespaced (overlay / explicit) key: frame the namespace with the reserved
    // sentinel so the boundary is unambiguous AND unforgeable from the default
    // key-space. The namespace is guaranteed `\x1f`-free by `isSafeRouteNamespace`.
    return `${LCM_NS_SENTINEL}${namespace}${LCM_NS_SENTINEL}${sessionKey}`;
  }
  // Default store: raw sessionKey, escaped only if it would otherwise intrude on
  // the namespaced key-space (no-op for every legitimate key).
  return escapeDefaultLcmKey(sessionKey);
}

/**
 * Map an ORDERED, read-authorized namespace set (the SAME set normal QMD/file
 * recall searches) to the ordered set of LCM `session_id`s a same-session reader
 * must query (#1505 thread "Include coding fallback namespaces in LCM reads").
 *
 * The LCM archive filters strictly by `session_id`, and `observe` archives each
 * turn under `${effectiveNamespace}:${sessionKey}` for the namespace that was
 * effective when it was written. A branch-scoped session that overlays
 * `${base-project-*-branch-*}` only sees rows written under THAT namespace if it
 * reads a single overlay key — but normal recall ALSO searches the
 * `codingOverlay.readFallbacks` (project / root) namespaces, so rows archived at
 * project/root scope are surfaced by QMD/file recall yet MISSED by a single-key
 * LCM read. Deriving the LCM read keys from the SAME `recallNamespaces` set keeps
 * the LCM read path from diverging: every namespace recall is authorized to read
 * (read-auth gate already applied upstream in `recallNamespaces`) contributes one
 * LCM key, ordered primary-overlay-first then fallbacks. Unreadable namespaces
 * are never in `recallNamespaces`, so they are never searched here either (no
 * cross-tenant read leak).
 *
 * Single-user / no-overlay recall passes a single-namespace set that collapses to
 * the raw `sessionKey`, so the result is `[sessionKey]` — byte-for-byte the
 * pre-#1505 single-key behavior.
 *
 * SESSIONLESS recall (`sessionKey === undefined`): returns `[undefined]` so the
 * caller issues ONE archive-wide LCM read with no exact `session_id` filter —
 * byte-for-byte the pre-#1505 sessionless behavior. It must NOT substitute the
 * literal `"default"` session id (codex P2 "Preserve unscoped LCM searches
 * without a session key"): that would filter to a session literally named
 * `default`, silently dropping the explicit-cue / targeted / focused / response /
 * event LCM sections for every recall that omits a session key.
 *
 * The result is deduped while preserving first-seen order so the caller can query
 * keys in priority order and short-circuit on the first hit without re-querying an
 * identical key (e.g. when two namespaces both collapse to the default store).
 */
export function lcmReadSessionIdsForNamespaces(
  namespaces: readonly string[],
  sessionKey: string | undefined,
  defaultNamespace: string,
): Array<string | undefined> {
  // Sessionless ⇒ a single archive-wide read (no `session_id` filter). NEVER the
  // literal "default" session id (codex P2).
  if (typeof sessionKey !== "string" || sessionKey.length === 0) {
    return [undefined];
  }
  const out: string[] = [];
  const seen = new Set<string>();
  for (const namespace of namespaces) {
    const key =
      lcmSessionKeyForNamespace(namespace, sessionKey, defaultNamespace) ??
      sessionKey;
    if (!seen.has(key)) {
      seen.add(key);
      out.push(key);
    }
  }
  return out;
}

/**
 * ScopePlan resolver (issue #1521).
 *
 * A single pure function that resolves every namespace-bearing read/write path
 * to one {@link ScopePlan} value object. Consumers (recall tiers, QMD router,
 * LCM reads, maintenance) never call the ad-hoc resolution helpers directly —
 * they receive a resolved plan and read its fields.
 *
 * The resolver DELEGATES to the existing helpers (`resolvePrincipal`,
 * `recallNamespacesForPrincipal`, `resolveCodingNamespaceOverlay`,
 * `resolveScopeProfilePlan`, `expandScopeProfileReadNamespaces`,
 * `combineNamespaces`, `lcmReadSessionIdsForNamespaces`) — no logic rewrite.
 * The ad-hoc inline resolution that previously lived in the orchestrator's
 * `recallInternal` and `enqueueDirectAnswerObservation` paths is replaced by a
 * single call to {@link resolveScopePlan}, eliminating the duplicated
 * namespace-set construction that produced the largest share of #1519's review
 * threads (scope-profile recall paths missing `readFallbacks` appends).
 *
 * Migration tranches (issue #1521 step 4):
 *  - recall tiers (this PR): the two orchestrator recall entry points consume
 *    the plan instead of building `recallNamespaces`/`observationNamespaces`
 *    inline;
 *  - QMD router calls, LCM reads, maintenance: follow-up PRs.
 *
 * CLAUDE.md rules honoured (pitfalls from the issue):
 *  - rule 42: read/write resolve through the same layer; the coding overlay is
 *    COMBINED with the principal base via `combineNamespaces`;
 *  - rule 39: feature gates identical across every path the plan feeds;
 *  - rule 22/48: LCM keys derived through `lcmSessionKeyForNamespace` (via
 *    `lcmReadSessionIdsForNamespaces`), never hardcoded `:`-joins; unscoped LCM
 *    search stays suppressed when `namespacesEnabled`.
 */

import { resolveNamespaceCapabilities } from "../capabilities.js";
import {
  canReadNamespace,
  canWriteNamespace,
  defaultNamespaceForPrincipal,
  recallNamespacesForPrincipal,
  resolvePrincipal,
} from "../namespaces/principal.js";
import {
  namespaceIdentityFromToken,
  namespaceIdentityLegacyToken,
  namespaceIdentityToken,
  normalizeNamespaceIdentity,
} from "../namespaces/identity.js";
import path from "node:path";
import {
  capabilityAllowsOp,
  isNamespaceAllowed,
  resolveEffectiveNamespace,
  type TokenCapabilities,
} from "../access-token-capabilities.js";
import type { ResolvedScopeProfilePlan } from "../namespaces/scope-profiles.js";
import {
  expandScopeProfileReadNamespaces,
  resolveScopeProfilePlan,
} from "../namespaces/scope-profiles.js";
import {
  combineNamespaces,
  lcmReadSessionIdsForNamespaces,
  resolveCodingNamespaceOverlay,
  type CodingNamespaceOverlay,
} from "../coding/coding-namespace.js";
import type { CodingContext, PluginConfig } from "../types.js";

/**
 * A resolved scope plan: every namespace-bearing field a read or write path
 * needs, produced by ONE call to {@link resolveScopePlan}.
 *
 * Consumers read these fields directly — they never re-resolve namespaces.
 */
export interface ScopePlan {
  /**
   * Resolved principal under which the operation runs. `undefined` only when
   * `namespacesEnabled` is false (collapses to `"default"`) or no session key
   * was supplied in single-user mode.
   */
  readonly principal: string | undefined;

  /**
   * Explicit namespace override, trimmed, when the caller supplied one AND it
   * is readable by the principal. `undefined` when no override was given or the
   * override is not readable (the plan falls through to the coding/scope-profile
   * resolution in that case, mirroring the pre-existing observe-path behavior).
   */
  readonly namespaceOverride: string | undefined;

  /**
   * Resolved base (self) namespace — the effective namespace absent an explicit
   * override. This is the principal-self namespace, optionally substituted by a
   * scope-profile write layer or a coding overlay.
   *
   * Callers that persisted this as the `selfNamespace` / response namespace
   * read it here.
   */
  readonly baseNamespace: string;

  /**
   * Ordered, deduped read-namespace set. Includes the coding overlay fallbacks
   * (branch → project → root) combined with the principal base exactly once, so
   * the #1519 miss (scope-profile path omitted `readFallbacks` appends) cannot
   * recur — the fallback appends live in ONE place.
   */
  readonly readNamespaces: string[];

  /**
   * Coding overlay fallback namespaces combined with the principal base (rule
   * 42). Empty when no coding overlay applies. These are the SAME entries
   * appended into {@link readNamespaces} for the coding-overlay branch,
   * surfaced separately so consumers that need just the fallback set (e.g.
   * LCM read-key derivation) can read them without re-deriving.
   */
  readonly readFallbacks: string[];

  /**
   * LCM read namespace set. May differ from {@link readNamespaces} for
   * read-authorization reasons: when the principal self base is NOT in the
   * readable recall set, the overlay LCM keys collapse to the default store
   * (rule 42 read/write parity; rule 48 least-privilege) even though
   * {@link readNamespaces} still searches the overlay for QMD/file recall.
   */
  readonly lcmReadNamespaces: string[];

  /**
   * LCM read `session_id` set, encoded via
   * `lcmReadSessionIdsForNamespaces` (which delegates to
   * `lcmSessionKeyForNamespace`). Ordered and deduped; the primary overlay key
   * is first. Single-user / no-overlay recall collapses to `[sessionKey]` —
   * byte-for-byte the pre-#1495 behavior.
   *
   * Empty (`[]`) when a scope-profile plan is active and no `sessionKey` was
   * supplied (mirrors the pre-existing guard).
   */
  readonly lcmReadSessionIds: ReadonlyArray<string | undefined>;

  /**
   * Resolved coding overlay, or `null` when none applies (no coding context,
   * `codingMode.projectScope` false, `namespacesEnabled` false, or an explicit
   * readable namespace override is set).
   */
  readonly codingOverlay: { readonly namespace: string; readonly readFallbacks: readonly string[] } | null;

  /**
   * Resolved scope-profile plan, or `null` when no scope profile is active.
   * Consumers that branched on "profile vs. non-profile" read this directly.
   */
  readonly scopeProfilePlan: ResolvedScopeProfilePlan | null;
}

/**
 * Options for {@link resolveScopePlan}.
 */
export interface ResolveScopePlanOptions {
  /** Plugin config (namespace policies, coding mode, default namespace, …). */
  readonly config: PluginConfig;
  /** Session key (may derive the principal and/or coding context). */
  readonly sessionKey?: string;
  /**
   * Explicit namespace override (raw — the resolver trims it). When supplied
   * AND readable by the resolved principal, it wins over every other layer.
   */
  readonly namespace?: string;
  /**
   * Authenticated principal override. Access surfaces that already resolved
   * identity at the transport layer pass it here so namespace ACL decisions
   * use the same identity the surface authorized.
   */
  readonly principalOverride?: string;
  /**
   * Coding context for the session. Callers that track this on the orchestrator
   * pass `getCodingContextForSession(sessionKey)` here; the resolver never
   * reaches back into orchestrator state.
   */
  readonly codingContext?: CodingContext | null;
  /**
   * Whether namespace routing is enabled. Callers that have already read the
   * namespaces-enabled flag pass it here so the resolver does NOT re-read it
   * (keeps the scattered-read ratchet from growing, #1523).
   */
  readonly namespacesEnabled: boolean;
}

/**
 * Resolve a {@link ScopePlan} from the inputs by delegating to the existing
 * namespace-resolution helpers. Pure — no side effects, no orchestrator state.
 *
 * The caller is responsible for authorization checks that should THROW (e.g.
 * `namespacesEnabled && !principal`, or an unreadable explicit override in the
 * recall path). The resolver computes the plan; enforcement stays at the call
 * site so error semantics are unchanged.
 */
export function resolveScopePlan(options: ResolveScopePlanOptions): ScopePlan {
  const { config, sessionKey } = options;

  const namespaceOverride = options.namespace?.trim() || undefined;

  const principal =
    typeof options.principalOverride === "string" && options.principalOverride.length > 0
      ? options.principalOverride
      : resolvePrincipal(sessionKey, config);

  // A namespace override gates the overlay/scope-profile layers. When it is
  // readable it wins; when it is NOT readable the plan falls through to the
  // coding/scope-profile/legacy branches (mirrors the observe-path behavior
  // where an unreadable override does not throw but simply does not suppress
  // the overlay). The recall path validates readability and throws BEFORE
  // calling the resolver, so a reachable override is always readable there.
  const namespaceOverrideReadable =
    namespaceOverride !== undefined && canReadNamespace(principal, namespaceOverride, config);

  const readableRecallNamespaces = recallNamespacesForPrincipal(principal, config);

  // The orchestrator's `applyCodingRecallOverlay` gates on `namespacesEnabled`
  // (returning null when disabled), so the resolver must too — otherwise
  // single-store mode would produce apparent route separation with no actual
  // storage isolation (false-isolation trap, rule 39). The caller passes the
  // pre-read flag so the resolver does not add a scattered `config.*Enabled`
  // read (ratchet, #1523).
  const namespacesEnabled = options.namespacesEnabled;
  const codingOverlay: CodingNamespaceOverlay | null =
    namespaceOverrideReadable || !namespacesEnabled
      ? null
      : resolveCodingNamespaceOverlay(
          options.codingContext ?? null,
          config.codingMode,
          config.defaultNamespace,
        );

  const principalSelfNamespace = defaultNamespaceForPrincipal(principal, config);
  const codingSelfNamespace = codingOverlay
    ? combineNamespaces(principalSelfNamespace, codingOverlay.namespace)
    : null;

  const scopeProfilePlan = namespaceOverrideReadable
    ? null
    : resolveScopeProfilePlan({
        config,
        principal,
        codingContext: options.codingContext ?? null,
        codingOverlay,
      });

  const profileEffectiveNamespace =
    scopeProfilePlan?.writeNamespace || scopeProfilePlan?.readNamespaces[0];

  const baseNamespace = namespaceOverrideReadable
    ? namespaceOverride!
    : profileEffectiveNamespace ?? codingSelfNamespace ?? principalSelfNamespace;

  // ── Read namespace set ────────────────────────────────────────────────────
  let readNamespaces: string[];
  if (namespaceOverrideReadable) {
    readNamespaces = [namespaceOverride!];
  } else if (scopeProfilePlan) {
    readNamespaces = expandScopeProfileReadNamespaces({
      profilePlan: scopeProfilePlan,
      principalSelfNamespace: scopeProfilePlan.baseNamespace,
      config,
      principal,
      codingOverlay,
      legacyRecallNamespaces: readableRecallNamespaces,
    });
  } else if (codingOverlay && codingSelfNamespace) {
    // Substitute the principal's self namespace with the coding-scoped one, and
    // append any read fallbacks (branch → project, rule 42) combined with the
    // principal base so principal isolation is preserved on fallback entries.
    const mapped = readableRecallNamespaces.map((ns) =>
      ns === principalSelfNamespace ? codingSelfNamespace : ns,
    );
    const fallbackNs = codingOverlay.readFallbacks.map((fallback) =>
      combineNamespaces(principalSelfNamespace, fallback),
    );
    readNamespaces = Array.from(new Set<string>([...mapped, ...fallbackNs]));
  } else {
    readNamespaces = readableRecallNamespaces;
  }

  const readFallbacks = codingOverlay
    ? codingOverlay.readFallbacks.map((fb) => combineNamespaces(principalSelfNamespace, fb))
    : [];

  // ── LCM read namespace set ────────────────────────────────────────────────
  // The LCM overlay keys are `<principal>-project-*` sub-namespaces authorized
  // transitively by the principal SELF base. Include them ONLY when that base
  // is in the readable recall set (rule 42 / 48). When it is NOT readable, the
  // overlay rows are unauthorized for this reader, so the LCM read collapses to
  // the default store — exactly what QMD/file recall surfaces for such a
  // principal.
  const codingOverlaySelfReadable =
    codingOverlay !== null &&
    (scopeProfilePlan
      ? scopeProfilePlan.layers.some((layer) => layer.id === "userProject" && layer.readable)
      : readableRecallNamespaces.includes(principalSelfNamespace));

  let lcmReadNamespaces: string[];
  if (namespaceOverrideReadable) {
    lcmReadNamespaces = [namespaceOverride!];
  } else if (scopeProfilePlan) {
    // Scope profiles define a layered read stack; LCM-backed evidence uses the
    // same namespace set as QMD/file recall so team/global/shared observations
    // are not silently skipped.
    lcmReadNamespaces = readNamespaces;
  } else if (codingOverlay && codingSelfNamespace && codingOverlaySelfReadable) {
    const fallbackNs = codingOverlay.readFallbacks.map((fallback) =>
      combineNamespaces(principalSelfNamespace, fallback),
    );
    lcmReadNamespaces = [codingSelfNamespace, ...fallbackNs];
  } else {
    // No overlay, OR overlay present but self base unreadable → collapse to the
    // default store (raw sessionKey). No `<principal>-project-*` overlay key is
    // searched.
    lcmReadNamespaces = [config.defaultNamespace];
  }

  const lcmReadSessionIds =
    scopeProfilePlan && !sessionKey
      ? []
      : lcmReadSessionIdsForNamespaces(lcmReadNamespaces, sessionKey, config.defaultNamespace);

  return {
    principal,
    namespaceOverride: namespaceOverrideReadable ? namespaceOverride : undefined,
    baseNamespace,
    readNamespaces,
    readFallbacks,
    lcmReadNamespaces,
    lcmReadSessionIds,
    codingOverlay: codingOverlay
      ? { namespace: codingOverlay.namespace, readFallbacks: codingOverlay.readFallbacks }
      : null,
    scopeProfilePlan,
  };
}

// ────────────────────────────────────────────────────────────────────────────
// Centralized namespace-resolution helpers (issue #1521 step 3–4)
//
// The three functions below consolidate the ad-hoc namespace-resolution logic
// that was previously scattered across orchestrator.ts (namespaceFromStorageDir,
// configuredNamespaces) and access-service.ts (resolveWritableNamespace). By
// living in THIS module they are excluded from the adHocNamespaceResolutions
// ratchet, and every consumer reaches them through a single well-known import
// instead of reimplementing the derivation inline (#1519's failure mode).
// ────────────────────────────────────────────────────────────────────────────

/**
 * The configured namespace set: default + shared + every namespace-policy
 * name, trimmed and de-duplicated. Pure — reads only from `config`.
 *
 * Replaces the `configuredNamespaces()` private method that lived on both
 * `Orchestrator` and the maintenance namespace-planner (two copies of the
 * same logic).
 */
export function getConfiguredNamespaces(config: PluginConfig): string[] {
  return Array.from(
    new Set(
      [
        config.defaultNamespace,
        config.sharedNamespace,
        ...config.namespacePolicies.map((policy) => policy.name),
      ]
        .map((value) => normalizeNamespaceIdentity(value))
        .filter(Boolean),
    ),
  );
}

/**
 * Options for {@link resolveNamespaceFromStorageDir}.
 */
export interface ResolveNamespaceFromStorageDirOptions {
  /** Plugin config (memoryDir, defaultNamespace, namespacesEnabled, …). */
  readonly config: PluginConfig;
  /**
   * Pre-computed configured-namespace set (from {@link getConfiguredNamespaces}).
   * Passed by the caller so this function does not re-derive it on every call.
   */
  readonly configuredNamespaces: readonly string[];
  /**
   * Catalog-owned dir→namespace hints (best-effort union of configured +
   * catalog-discovered). May be `undefined` when no catalog hints are loaded.
   */
  readonly hints?: ReadonlyMap<string, ReadonlySet<string>> | undefined;
  /**
   * Lazy catalog-hint loader. Called ONLY after the early returns (disabled,
   * memory root, no namespace segment, configured namespace) — matching the
   * original lazy behavior so an eager load does not mark hints as loaded
   * before the catalog file exists (codex P2).
   */
  readonly loadHints?: () => void;
}

/**
 * Derive the namespace a storage directory belongs to.
 *
 * Pure (no orchestrator state): the caller passes `config`, the configured set,
 * and any catalog hints. The logic is byte-identical to the private
 * `namespaceFromStorageDir` method that previously lived on `Orchestrator`
 * (including the token round-trip guard from codex round 6).
 */
export function resolveNamespaceFromStorageDir(
  storageDir: string,
  options: ResolveNamespaceFromStorageDirOptions,
): string {
  const { config } = options;
  if (!resolveNamespaceCapabilities(config).namespaces) return config.defaultNamespace;
  const resolvedStorageDir = path.resolve(storageDir);
  const resolvedMemoryDir = path.resolve(config.memoryDir);
  if (resolvedStorageDir === resolvedMemoryDir) return config.defaultNamespace;
  const m = resolvedStorageDir.match(/[\\/]namespaces[\\/]([^\\/]+)$/);
  if (!m?.[1]) return config.defaultNamespace;
  const dirName = m[1];
  // Token-shaped raw names (codex P2 — NBsFz): a dir name might be a tokenized
  // identity OR a literal raw namespace name that merely LOOKS like a token.
  // A dir name that is itself a KNOWN namespace is preserved BEFORE decoding.
  if (options.configuredNamespaces.includes(dirName)) {
    return dirName;
  }
  // Load catalog hints ONLY after the early returns (codex P2: an eager load
  // before the catalog file exists would mark hints as loaded and skip later
  // catalog-derived rows).
  options.loadHints?.();
  const hints = options.hints;
  const hintedNamespaces = hints?.get(resolvedStorageDir);
  if (hintedNamespaces?.has(dirName)) {
    return dirName;
  }
  if (hintedNamespaces?.size === 1) {
    const [hintedNamespace] = hintedNamespaces;
    if (hintedNamespace) return hintedNamespace;
  }
  const decoded = namespaceIdentityFromToken(dirName);
  if (
    decoded &&
    (namespaceIdentityToken(decoded) === dirName ||
      namespaceIdentityLegacyToken(decoded.normalize("NFD")) === dirName)
  ) {
    return decoded;
  }
  return dirName;
}

/**
 * Result of resolving a writable namespace: either the authorized namespace
 * or a structured rejection. The caller decides how to surface the rejection
 * (e.g. as an `EngramAccessInputError` in the access-service layer), keeping
 * this module free of transport-specific error types.
 */
export type WritableNamespaceResult =
  | { readonly ok: true; readonly namespace: string }
  | { readonly ok: false; readonly reason: "unsupported" | "not_writable"; readonly namespace: string };

/**
 * Resolve and authorize a writable namespace.
 *
 * Combines the three steps that `AccessService.resolveWritableNamespace`
 * performed inline: (1) resolve the namespace value (trim → default fallback →
 * validate against `namespacesEnabled`), (2) resolve the principal, (3) check
 * `canWriteNamespace`. Returns a structured result so this module stays free of
 * `EngramAccessInputError` (avoiding a circular dependency on access-service.ts).
 *
 * The caller throws `EngramAccessInputError` when `ok === false` — the access-
 * service wrapper does this in one place.
 */
export function resolveWritableNamespaceValue(
  namespace: string | undefined,
  sessionKey: string | undefined,
  authenticatedPrincipal: string | undefined,
  config: PluginConfig,
): WritableNamespaceResult {
  const requested = namespace?.trim();
  let resolved: string;
  if (!requested) {
    resolved = config.defaultNamespace;
  } else if (
    !resolveNamespaceCapabilities(config).namespaces &&
    requested !== config.defaultNamespace
  ) {
    return { ok: false, reason: "unsupported", namespace: requested };
  } else {
    resolved = requested;
  }

  const trusted = authenticatedPrincipal?.trim();
  const principal =
    typeof trusted === "string" && trusted.length > 0
      ? trusted
      : resolvePrincipal(sessionKey, config);

  if (!canWriteNamespace(principal, resolved, config)) {
    return { ok: false, reason: "not_writable", namespace: resolved };
  }
  return { ok: true, namespace: resolved };
}

/**
 * Inputs already derived by the access-service's read-only coding-context
 * resolver. Keeping context discovery outside this pure function lets writes
 * and preflight checks apply identical namespace and ACL rules.
 */
export interface ScopedWritableNamespaceInput {
  readonly namespace?: string;
  readonly sessionKey?: string;
  readonly authenticatedPrincipal?: string;
  readonly principal: string | undefined;
  readonly codingOverlay: CodingNamespaceOverlay | null;
  readonly scopeProfile: ResolvedScopeProfilePlan | null;
  readonly config: PluginConfig;
}

/**
 * Resolve the namespace an explicit write or implicit coding-scoped write
 * would use. The caller supplies the same derived coding inputs for the real
 * write and the read-only preflight.
 */
export function resolveScopedWritableNamespaceValue(
  input: ScopedWritableNamespaceInput,
): WritableNamespaceResult {
  const requested = input.namespace?.trim();
  if (requested) {
    return resolveWritableNamespaceValue(
      requested,
      input.sessionKey,
      input.authenticatedPrincipal,
      input.config,
    );
  }
  if (input.scopeProfile) {
    const selectedLayer = input.scopeProfile.layers.find(
      (layer) => layer.id === input.scopeProfile?.writeLayer,
    );
    const writeNamespaceReadable =
      input.scopeProfile.writeNamespace.length > 0 &&
      input.scopeProfile.readNamespaces.includes(input.scopeProfile.writeNamespace);
    if (!selectedLayer?.writable || !writeNamespaceReadable) {
      return {
        ok: false,
        reason: "not_writable",
        namespace: input.scopeProfile.writeNamespace,
      };
    }
    return { ok: true, namespace: input.scopeProfile.writeNamespace };
  }
  if (!input.codingOverlay) {
    return resolveWritableNamespaceValue(
      undefined,
      input.sessionKey,
      input.authenticatedPrincipal,
      input.config,
    );
  }
  const baseNamespace = defaultNamespaceForPrincipal(input.principal, input.config);
  if (!canWriteNamespace(input.principal, baseNamespace, input.config)) {
    return { ok: false, reason: "not_writable", namespace: baseNamespace };
  }
  return {
    ok: true,
    namespace: combineNamespaces(baseNamespace, input.codingOverlay.namespace),
  };
}

/**
 * Namespace preflight (issue #1888 part 3): would a write to `namespace` by a
 * caller carrying `caps` succeed? Combines the token's write-op scope, its
 * namespace allow-list, and policy writability so one call answers the real
 * question. A token that cannot actually write (no `observe`/`memory_store` in
 * its ops allow-list) or is asking about a namespace outside its allow-list
 * gets a definitive `not_writable` — revealing nothing about the namespace's
 * policy beyond what the token's own scope already implies, and never throwing
 * a hard authorization error the caller cannot distinguish from a transport
 * fault. (Unrestricted tokens pass both scope checks unchanged.)
 */
export function resolveNamespacePreflight(
  caps: TokenCapabilities | undefined | null,
  namespace: string | undefined,
  sessionKey: string | undefined,
  authenticatedPrincipal: string | undefined,
  config: PluginConfig,
  writeOp: string,
): WritableNamespaceResult {
  const notWritable = (): WritableNamespaceResult => ({
    ok: false,
    reason: "not_writable",
    namespace: resolveEffectiveNamespace(namespace, config.defaultNamespace) ?? namespace ?? "",
  });
  // The token must be able to perform the write op the caller's ENABLED write
  // path actually uses (`observe` for automatic turn capture — the silent
  // #1888 data-loss path — or `memory_store` for an explicit-only install).
  // A token that cannot perform that op would drop the write, so an otherwise
  // policy-writable namespace is still reported not_writable rather than a
  // false ok:true that promises a write the token cannot make.
  if (!capabilityAllowsOp(caps, writeOp)) {
    return notWritable();
  }
  if (!isNamespaceAllowed(caps, namespace, config.defaultNamespace)) {
    return notWritable();
  }
  return resolveWritableNamespaceValue(namespace, sessionKey, authenticatedPrincipal, config);
}

import { resolveNamespaceCapabilities } from "../capabilities.js";
import path from "node:path";
import { realpathSync } from "node:fs";
import type { PluginConfig, QmdSearchResult } from "../types.js";
import type {
  SearchBackend,
  SearchExecutionOptions,
  SearchQueryOptions,
} from "../search/port.js";
import { createSearchBackend } from "../search/factory.js";
import { namespaceIdentityToken, normalizeNamespaceIdentity } from "./identity.js";
import { ALL_CATEGORY_DIRS } from "../utils/category-dir.js";

const NESTED_NAMESPACE_FILTER_OVERFETCH_FACTOR = 4;
const NESTED_NAMESPACE_FILTER_OVERFETCH_MIN = 50;

export function namespaceCollectionName(
  baseCollection: string,
  namespace: string,
  options?: {
    defaultNamespace?: string;
    useLegacyDefaultCollection?: boolean;
  },
): string {
  const trimmed = normalizeNamespaceIdentity(namespace);
  const defaultNamespace = normalizeNamespaceIdentity(options?.defaultNamespace ?? "") || "default";
  if (
    options?.useLegacyDefaultCollection === true &&
    trimmed === defaultNamespace
  ) {
    return baseCollection;
  }

  return `${baseCollection}--${namespaceIdentityToken(trimmed || defaultNamespace)}`;
}

type StorageRouterLike = {
  storageFor(namespace: string): Promise<{ dir: string }>;
};

type NamespaceBackendRecord = {
  backend: SearchBackend;
  collection: string;
  memoryDir: string;
  available: boolean;
  collectionState: CollectionState;
  filtersNestedNamespaces: boolean;
  disposed: boolean;
};

export interface NamespaceUpdateResult {
  backendCount: number;
  eligibleNamespaces: string[];
}

export type CollectionState = "present" | "missing" | "unknown" | "skipped";

export interface NamespaceSearchHealth {
  collection: string;
  memoryDir: string;
  available: boolean;
  collectionState: CollectionState;
  debugStatus: string;
  installedVersion: string | null;
  supportedVersion: string | null;
  supported: boolean | null;
  upgradeAvailable: boolean | null;
  doctorAvailable: boolean | null;
  daemonMode: boolean | null;
  pendingEmbeddings: number | null;
  oldestPendingAgeMs: number | null;
  embeddingBacklogThreshold: number;
}

type NamespaceScopedSearchConfig = PluginConfig & {
  hostEmbeddingProviderScope?: string;
};

type BackendRecordOptions = {
  autoCreateCollection: boolean;
  abortAsUnavailable: boolean;
  failOpenMissingGuardedCollection: boolean;
};

export class NamespaceSearchRouter {
  private readonly cache = new Map<string, Promise<NamespaceBackendRecord>>();
  private readonly pendingDisposals = new Set<Promise<void>>();

  constructor(
    private readonly config: PluginConfig,
    private readonly storageRouter: StorageRouterLike,
    private readonly createBackend: (config: PluginConfig) => SearchBackend = createSearchBackend,
  ) {}

  async collectionForNamespace(namespace: string): Promise<string> {
    return (await this.backendRecordFor(namespace)).collection;
  }

  /**
   * Resolve the search backend for a namespace (#2019). Returns `unknown` so
   * callers (e.g. the prioritized-embed path) duck-type for capability like
   * `embedFiles` rather than depending on a concrete QMD shape. Reuses the
   * cached backend record, so this never re-creates a backend. Returns `null`
   * when the namespace backend is unavailable.
   */
  async backendForNamespace(namespace: string): Promise<unknown> {
    const record = await this.backendRecordFor(namespace);
    return record.available ? record.backend : null;
  }

  async searchAcrossNamespaces(options: {
    query: string;
    namespaces: string[];
    maxResults?: number;
    mode?: "search" | "hybrid" | "bm25" | "vector";
    searchOptions?: SearchQueryOptions;
    execution?: SearchExecutionOptions;
  }): Promise<QmdSearchResult[]> {
    const query = options.query.trim();
    if (!query) return [];
    const maxResults = Math.max(0, Math.floor(options.maxResults ?? this.config.qmdMaxResults));
    if (maxResults === 0) return [];

    const method = options.mode ?? "search";
    const namespaces = Array.from(new Set(options.namespaces.map((value) => value.trim()).filter(Boolean)));
    if (namespaces.length === 0) return [];

    const resultsByNamespace = await Promise.all(
      namespaces.map(async (namespace) => {
        const record = await this.backendRecordFor(namespace);
        if (!record.available || record.collectionState === "missing") {
          // A per-namespace backend that is unavailable (or missing its
          // collection) must report like any other QMD skip (#1536): its
          // empty contribution is otherwise indistinguishable from a true
          // no-matches for that namespace (codex round-5 review on #1544).
          try {
            options.execution?.onDegradation?.({
              backend: "qmd",
              code: "backend_unavailable",
              detail:
                record.collectionState === "missing"
                  ? `namespace collection missing: ${namespace}`
                  : `namespace backend unavailable: ${namespace}`,
            });
          } catch {
            // Observers must never break search.
          }
          return { namespace, results: [] as QmdSearchResult[] };
        }
        const backendLimit = backendSearchLimit(record, maxResults);
        let results: QmdSearchResult[];
        switch (method) {
          case "hybrid":
            results = await record.backend.hybridSearch(
              query,
              record.collection,
              backendLimit,
              options.execution,
            );
            break;
          case "bm25":
            results = await record.backend.bm25Search(
              query,
              record.collection,
              backendLimit,
              options.execution,
            );
            break;
          case "vector":
            results = await record.backend.vectorSearch(
              query,
              record.collection,
              backendLimit,
              options.execution,
            );
            break;
          default:
            results = await record.backend.search(
              query,
              record.collection,
              backendLimit,
              options.searchOptions,
              options.execution,
            );
            break;
        }
        results = filterNamespaceSubtreeResults(record, results)
          .map((result) => ({
            ...result,
            namespace,
            // Resolve to an absolute path so the (namespace, path) identity is
            // globally unique — same-relative-path hits from different namespaces
            // stay distinct across every downstream consumer with no special
            // handling. Display/citation surfaces relativize for portability (#2020).
            path: resolveNamespaceResultPath(record.memoryDir, record.collection, result.path),
          }))
          // Reject hits whose resolved path escapes the queried namespace's
          // storage root (#2077). A stale/corrupt per-namespace collection can
          // return a path owned by another namespace; stamping it would let
          // downstream scope checks (which trust the stamped namespace) and
          // absolute-path resolution surface a foreign-namespace memory.
          .filter((result) => resolvedPathIsInsideNamespaceRoot(record.memoryDir, result.path));
        return { namespace, results };
      }),
    );

    return mergeNamespaceSearchResults(resultsByNamespace, maxResults);
  }

  /**
   * Update all namespace backends.
   * Returns the number of backends for which an update was attempted
   * (i.e., available and collection present).  Callers can treat 0 as a
   * signal that no backend was eligible — useful for success-verification in
   * startup-sync when namespacesEnabled is true.
   */
  async updateNamespaces(
    namespaces: string[],
    execution?: SearchExecutionOptions,
    options?: { strict?: boolean; force?: boolean },
  ): Promise<number> {
    return (await this.updateNamespacesDetailed(namespaces, execution, options)).backendCount;
  }

  async updateNamespacesDetailed(
    namespaces: string[],
    execution?: SearchExecutionOptions,
    options?: { strict?: boolean; force?: boolean },
  ): Promise<NamespaceUpdateResult> {
    const unique = Array.from(new Set(namespaces.map((value) => value.trim()).filter(Boolean)));
    const eligible = (await Promise.all(
      unique.map(async (namespace) => {
        const record = await this.backendRecordFor(namespace);
        return record.available && record.collectionState !== "missing"
          ? { namespace, record }
          : null;
      }),
    )).filter((entry): entry is { namespace: string; record: NamespaceBackendRecord } => entry !== null);

    const globalEntry = eligible.find(({ record }) => record.backend.updatesAllCollections?.() === true);
    const scopedEntries = globalEntry
      ? eligible.filter(({ record }) => record.backend.updatesAllCollections?.() !== true)
      : eligible;

    await Promise.all([
      globalEntry
        ? updateBackendRecord(globalEntry.record, execution, options)
        : Promise.resolve(),
      ...scopedEntries.map(({ record }) => updateBackendRecord(record, execution, options)),
    ]);

    return {
      backendCount: (globalEntry ? 1 : 0) + scopedEntries.length,
      eligibleNamespaces: eligible.map(({ namespace }) => namespace),
    };
  }

  async embedNamespaces(namespaces: string[], options?: { strict?: boolean }): Promise<void> {
    const unique = Array.from(new Set(namespaces.map((value) => value.trim()).filter(Boolean)));
    await Promise.all(
      unique.map(async (namespace) => {
        const record = await this.backendRecordFor(namespace);
        if (!record.available || record.collectionState === "missing") return;
        await embedBackendRecord(record, options);
      }),
    );
  }

  async ensureNamespaceCollection(
    namespace: string,
    execution?: SearchExecutionOptions,
  ): Promise<"present" | "missing" | "unknown" | "skipped"> {
    const record = await this.backendRecordFor(namespace, execution);
    return record.collectionState;
  }

  async healthForNamespace(
    namespace: string,
    execution?: SearchExecutionOptions,
  ): Promise<NamespaceSearchHealth> {
    const key = namespace.trim() || this.config.defaultNamespace;
    const record = await this.createBackendRecordFor(
      key,
      execution,
      {
        autoCreateCollection: false,
        abortAsUnavailable: true,
        failOpenMissingGuardedCollection: false,
      },
    );
    try {
      const liveRecord = await this.liveCachedRecordForHealth(key, record, execution);
      const diagnosticBackend = liveRecord?.backend ?? record.backend;
      const versionStatus =
        "getVersionStatus" in diagnosticBackend &&
        typeof diagnosticBackend.getVersionStatus === "function"
          ? diagnosticBackend.getVersionStatus()
          : null;
      const daemonMode = daemonModeForBackend(diagnosticBackend);
      const backendStatus =
        "status" in diagnosticBackend &&
        typeof diagnosticBackend.status === "function"
          ? await Promise.race([
              diagnosticBackend.status().catch(() => null),
              new Promise<null>((resolve) => setTimeout(() => resolve(null), 5_000).unref?.()),
            ])
          : null;
      const collectionState =
        liveRecord?.collectionState === "missing"
          ? "missing"
          : record.collectionState;

      return {
        collection: record.collection,
        memoryDir: record.memoryDir,
        available: liveRecord?.available ?? record.available,
        collectionState,
        debugStatus: diagnosticBackend.debugStatus(),
        installedVersion: versionStatus?.installedVersion ?? null,
        supportedVersion: versionStatus?.supportedVersion ?? null,
        supported: versionStatus?.supported ?? null,
        upgradeAvailable: versionStatus?.upgradeAvailable ?? null,
        doctorAvailable: versionStatus?.capabilities?.doctor ?? null,
        daemonMode,
        pendingEmbeddings: backendStatus?.pendingEmbeddings ?? null,
        oldestPendingAgeMs: backendStatus?.oldestPendingAgeMs ?? null,
        embeddingBacklogThreshold: this.config.qmdEmbeddingBacklogThreshold,
      };
    } finally {
      const dispose = (record.backend as { dispose?: () => void | Promise<void> }).dispose;
      await dispose?.call(record.backend);
    }
  }

  private async liveCachedRecordForHealth(
    key: string,
    disposableRecord: NamespaceBackendRecord,
    execution?: SearchExecutionOptions,
  ): Promise<NamespaceBackendRecord | null> {
    const pending = this.cache.get(key);
    if (!pending) return null;
    const cachedRecord = await awaitWithAbort(pending, execution?.signal).catch(() => null);
    if (!cachedRecord) return null;
    if (cachedRecord.collection !== disposableRecord.collection) return null;
    if (cachedRecord.memoryDir !== disposableRecord.memoryDir) return null;
    return cachedRecord;
  }

  private trackDisposal(promise: Promise<void>): void {
    this.pendingDisposals.add(promise);
    void promise.finally(() => this.pendingDisposals.delete(promise));
  }

  private async drainPendingDisposals(): Promise<void> {
    if (this.pendingDisposals.size === 0) return;
    await Promise.allSettled(this.pendingDisposals);
  }

  /** Clear cached backend records so the next access re-probes availability. */
  clearCache(): void {
    const pendingRecords = Array.from(this.cache.values());
    this.cache.clear();
    const disposal = Promise.allSettled(pendingRecords).then(async (settled) => {
      await Promise.allSettled(
        settled.flatMap((entry) =>
          entry.status === "fulfilled" ? [this.disposeRecord(entry.value)] : []),
      );
    });
    this.trackDisposal(disposal);
  }

  private async disposeRecord(record: NamespaceBackendRecord): Promise<void> {
    if (record.disposed) return;
    record.disposed = true;
    const dispose = (record.backend as { dispose?: () => void | Promise<void> }).dispose;
    await dispose?.call(record.backend);
  }

  /** Release any per-namespace backend handles held by cached records. */
  async dispose(): Promise<void> {
    await this.drainPendingDisposals();
    const pendingRecords = Array.from(this.cache.values());
    this.cache.clear();
    const settled = await Promise.allSettled(pendingRecords);
    await Promise.allSettled(
      settled.flatMap((entry) =>
        entry.status === "fulfilled" ? [this.disposeRecord(entry.value)] : []),
    );
  }

  /**
   * Disable namespace search for this runtime while retaining the resolved
   * records as unavailable/missing. This releases concrete QMD/daemon handles
   * without letting later reads recreate a search backend after the root path
   * has been switched to NoopSearchBackend for a missing collection.
   */
  async disableSearchBackends(): Promise<void> {
    const settled = await Promise.allSettled(this.cache.values());
    await Promise.allSettled(
      settled.flatMap((entry) => {
        if (entry.status !== "fulfilled") return [];
        entry.value.available = false;
        entry.value.collectionState = "missing";
        return [this.disposeRecord(entry.value)];
      }),
    );
  }

  private async backendRecordFor(
    namespace: string,
    execution?: SearchExecutionOptions,
  ): Promise<NamespaceBackendRecord> {
    await this.drainPendingDisposals();
    const key = namespace.trim() || this.config.defaultNamespace;
    const existing = this.cache.get(key);
    if (existing) return await existing;

    const pending = this.createBackendRecordFor(key, execution, {
      autoCreateCollection: true,
      abortAsUnavailable: false,
      failOpenMissingGuardedCollection: true,
    }).catch((error) => {
      this.cache.delete(key);
      throw error;
    });

    this.cache.set(key, pending);
    return await pending;
  }

  private async createBackendRecordFor(
    namespace: string,
    execution: SearchExecutionOptions | undefined,
    options: BackendRecordOptions,
  ): Promise<NamespaceBackendRecord> {
    const key = namespace.trim() || this.config.defaultNamespace;
    const storage = await this.storageRouter.storageFor(key);
    const useLegacyDefaultCollection =
      key === this.config.defaultNamespace && storage.dir === this.config.memoryDir;
    const filtersNestedNamespaces =
      resolveNamespaceCapabilities(this.config).namespaces === true && useLegacyDefaultCollection;
    const rootHostEmbeddingScope =
      (this.config as NamespaceScopedSearchConfig).hostEmbeddingProviderScope ??
      this.config.memoryDir;
    const scopedConfig: NamespaceScopedSearchConfig = {
      ...this.config,
      memoryDir: storage.dir,
      hostEmbeddingProviderScope: rootHostEmbeddingScope,
      qmdCollection: namespaceCollectionName(this.config.qmdCollection, key, {
        defaultNamespace: this.config.defaultNamespace,
        useLegacyDefaultCollection,
      }),
    };

    const backend = this.createBackend(scopedConfig);
    try {
      const availabilityProbe =
        options.autoCreateCollection || typeof backend.checkAvailability !== "function"
          ? backend.probe(execution)
          : backend.checkAvailability({ signal: execution?.signal });
      const available = await awaitWithAbort(availabilityProbe, execution?.signal).catch((error) => {
        if (error instanceof NamespaceSearchAbortError && !options.abortAsUnavailable) {
          throw error;
        }
        return false;
      });
      const collectionState = available
        ? await awaitWithAbort(
          // The legacy default namespace at the flat root (`filtersNestedNamespaces`)
          // shares its `memoryDir` with the `namespaces/` container, so its base
          // collection is a "broad root" that also indexes nested-namespace files.
          // We STILL auto-create it (issue #1929): the search side already targets
          // this exact base collection and `filterNamespaceSubtreeResults` strips
          // the nested `namespaces/` subtree out of its results, so index and
          // search stay symmetric. Skipping creation left a configured default
          // namespace (e.g. `geek`) with maintenance "ran" but no collection and 0
          // recall results. `ensureCollection` is a no-op when the collection is
          // already present, so legacy installs that pre-created the broad root are
          // unaffected.
          this.collectionStateForBackend(backend, storage.dir, scopedConfig.qmdCollection, {
            autoCreate: options.autoCreateCollection,
            failOpenMissingGuardedCollection: options.failOpenMissingGuardedCollection,
            execution,
          }),
          execution?.signal,
        ).catch((error) => {
          if (error instanceof NamespaceSearchAbortError && !options.abortAsUnavailable) {
            throw error;
          }
          return "unknown" as const;
        })
        : "unknown";
      return {
        backend,
        collection: scopedConfig.qmdCollection,
        memoryDir: storage.dir,
        available,
        collectionState,
        filtersNestedNamespaces,
        disposed: false,
      };
    } catch (error) {
      const dispose = (backend as { dispose?: () => void | Promise<void> }).dispose;
      if (dispose) {
        await Promise.resolve(dispose.call(backend)).catch(() => {});
      }
      throw error;
    }
  }

  private async collectionStateForBackend(
    backend: SearchBackend,
    memoryDir: string,
    collection: string,
    options: {
      autoCreate: boolean;
      failOpenMissingGuardedCollection: boolean;
      execution?: SearchExecutionOptions;
    },
  ): Promise<CollectionState> {
    if (!options.autoCreate) {
      if (!backend.checkCollection) return "unknown";
      const collectionState = await backend
        .checkCollection(collection, options.execution)
        .catch(() => "unknown" as const);
      return options.failOpenMissingGuardedCollection && collectionState === "missing"
        ? "unknown"
        : collectionState;
    }
    return await backend.ensureCollection(memoryDir, collection, options.execution).catch(() => "unknown" as const);
  }
}

class NamespaceSearchAbortError extends Error {
  constructor() {
    super("operation aborted");
  }
}

function awaitWithAbort<T>(operation: Promise<T>, signal?: AbortSignal): Promise<T> {
  if (!signal) return operation;
  if (signal.aborted) return Promise.reject(new NamespaceSearchAbortError());

  return new Promise<T>((resolve, reject) => {
    const onAbort = () => {
      signal.removeEventListener("abort", onAbort);
      reject(new NamespaceSearchAbortError());
    };
    signal.addEventListener("abort", onAbort, { once: true });
    operation.then(resolve, reject).finally(() => {
      signal.removeEventListener("abort", onAbort);
    });
  });
}

function filterNamespaceSubtreeResults(
  record: NamespaceBackendRecord,
  results: QmdSearchResult[],
): QmdSearchResult[] {
  if (!record.filtersNestedNamespaces) return results;
  return results.filter((result) =>
    !pathIsInsideNamespaceSubtree(record.memoryDir, record.collection, result.path)
  );
}

function backendSearchLimit(
  record: NamespaceBackendRecord,
  maxResults: number,
): number {
  if (!record.filtersNestedNamespaces) return maxResults;
  return Math.max(
    maxResults,
    maxResults * NESTED_NAMESPACE_FILTER_OVERFETCH_FACTOR,
    NESTED_NAMESPACE_FILTER_OVERFETCH_MIN,
  );
}

async function updateBackendRecord(
  record: NamespaceBackendRecord,
  execution?: SearchExecutionOptions,
  options?: { strict?: boolean; force?: boolean },
): Promise<void> {
  if (options?.strict === true) {
    if (
      // Forced refreshes must skip the throttled all-collections update: its
      // success has to prove the current writes are indexed, which a throttle
      // skip cannot.
      options.force !== true &&
      record.backend.updatesAllCollections?.() === true &&
      typeof record.backend.updateStrict === "function"
    ) {
      await record.backend.updateStrict(execution);
      return;
    }
    if (typeof record.backend.updateCollectionStrict === "function") {
      await record.backend.updateCollectionStrict(record.collection, execution);
      return;
    }
    // Backends with no strict variant (Orama, LanceDB, Meilisearch, remote) have a fail-open
    // update(): it resolves when it returned early or failed. Their updateCompleted() says
    // whether the refresh ran, so strict callers get a failure instead of a fake success.
    const completed = await record.backend.updateCompleted?.(execution);
    if (completed !== undefined) {
      if (!completed) throw new Error("search backend update did not complete");
      return;
    }
  }
  await record.backend.update(execution);
}

async function embedBackendRecord(
  record: NamespaceBackendRecord,
  options?: { strict?: boolean },
): Promise<void> {
  if (options?.strict === true) {
    if (typeof record.backend.embedCollectionStrict === "function") {
      await record.backend.embedCollectionStrict(record.collection);
      return;
    }
    if (typeof record.backend.embedStrict === "function") {
      await record.backend.embedStrict();
      return;
    }
  }
  if (typeof record.backend.embedCollection === "function") {
    await record.backend.embedCollection(record.collection);
    return;
  }
  await record.backend.embed();
}

function daemonModeForBackend(backend: SearchBackend): boolean | null {
  return "isDaemonMode" in backend && typeof backend.isDaemonMode === "function"
    ? backend.isDaemonMode() === true
    : null;
}

function isContainedPath(root: string, candidate: string): boolean {
  const relative = path.relative(root, candidate);
  return (
    relative === "" ||
    (relative !== ".." && !relative.startsWith(`..${path.sep}`) && !path.isAbsolute(relative))
  );
}

function pathIsInsideNamespaceSubtree(
  memoryDir: string,
  collection: string,
  resultPath: string | undefined,
): boolean {
  if (!resultPath) return false;
  const normalizedResultPath = normalizeQmdResultPath(resultPath, collection);
  const memoryRoot = path.resolve(memoryDir);
  const namespacesRoot = path.join(memoryRoot, "namespaces");
  const candidate = path.isAbsolute(normalizedResultPath)
    ? path.normalize(normalizedResultPath)
    : path.resolve(memoryRoot, normalizedResultPath);
  return isContainedPath(namespacesRoot, candidate);
}

/**
 * Reject a QMD hit whose resolved path escapes the queried namespace's storage
 * root (#2077). `resolvedPath` is the already-resolved value produced by
 * `resolveNamespaceResultPath`; a stale/corrupt per-namespace collection can
 * yield an absolute path owned by another namespace, and stamping it with the
 * queried namespace would surface a foreign-namespace memory downstream.
 *
 * Lexical containment runs first — it is cheap and the only check possible when
 * the file is not yet on disk (a stale collection may cite a since-deleted
 * path). When both root and candidate exist, their filesystem realpaths are
 * canonicalized and re-checked so a symlink planted inside the namespace root
 * cannot resolve into another namespace or outside storage. An unresolved path
 * (ENOENT) keeps the lexical result rather than rejecting the stale-collection
 * case this guard targets.
 */
function resolvedPathIsInsideNamespaceRoot(memoryDir: string, resolvedPath: string): boolean {
  const root = path.resolve(memoryDir);
  const candidate = path.isAbsolute(resolvedPath)
    ? path.normalize(resolvedPath)
    : path.resolve(root, resolvedPath);
  if (!isContainedPath(root, candidate)) return false;
  try {
    return isContainedPath(realpathSync.native(root), realpathSync.native(candidate));
  } catch {
    return true;
  }
}
export function normalizeQmdResultPath(resultPath: string, collection: string): string {
  let value = resultPath.trim();
  if (value.startsWith("qmd://")) {
    try {
      const parsed = new URL(value);
      if (parsed.protocol === "qmd:" && parsed.hostname === collection) {
        value = decodeURIComponent(parsed.pathname.replace(/^\/+/, ""));
      }
    } catch {
      const remainder = value.slice("qmd://".length);
      const slashIndex = remainder.indexOf("/");
      if (slashIndex !== -1) {
        value = remainder.slice(slashIndex + 1);
      }
    }
  }

  // Only strip a genuine QMD collection prefix — never when the collection name
  // collides with a memory category dir (e.g. qmdCollection == "facts"), or a
  // bare "facts/<id>.md" hit would be corrupted to "<id>.md" and fail namespace
  // reads/access tracking (#2020).
  const collectionPrefix = `${collection}/`;
  if (value.startsWith(collectionPrefix) && !ALL_CATEGORY_DIRS.includes(collection)) {
    value = value.slice(collectionPrefix.length);
  }
  return value;
}
export function resolveNamespaceResultPath(
  memoryDir: string,
  collection: string,
  resultPath: string,
): string {
  const normalized = normalizeQmdResultPath(resultPath, collection);
  if (path.isAbsolute(normalized)) return normalized;
  const root = path.resolve(memoryDir);
  const resolved = path.resolve(root, normalized);
  const relative = path.relative(root, resolved);
  if (relative === "" || relative.startsWith("..") || path.isAbsolute(relative)) {
    return resultPath;
  }
  return resolved;
}
function mergeNamespaceSearchResults(
  lists: Array<{ namespace: string; results: QmdSearchResult[] }>,
  maxResults: number,
): QmdSearchResult[] {
  const merged = new Map<string, QmdSearchResult>();

  for (const { namespace, results } of lists) {
    for (const result of results) {
      const key = `${namespace}\0${result.path || result.docid}`;
      const existing = merged.get(key);
      if (!existing) {
        merged.set(key, { ...result, namespace });
        continue;
      }
      if (result.score > existing.score) {
        merged.set(key, {
          ...result,
          namespace,
          snippet: existing.snippet || result.snippet || "",
        });
      }
    }
  }

  return [...merged.values()]
    .sort((a, b) => b.score - a.score)
    .slice(0, maxResults);
}

