  });
}

export function summarizeOfflineSyncPendingFiles(options: {
  baseFiles?: readonly OfflineSyncFileState[];
  currentFiles: readonly OfflineSyncFileState[];
  includeTranscripts?: boolean;
  userExcludeRegexps?: readonly RegExp[];
  /**
   * When false, enumeration uses only the legacy structural excludes —
   * the apply/pull-side view of local files. Push-side callers keep the
   * default (true): built-in node-local state excludes + user excludes.
   * (Cursor review on PR #1793: apply-side local enumeration must see
   * files like state/lcm.sqlite or merges misclassify them.)
   */
  excludeNodeLocalState?: boolean;
}): OfflineSyncChangesetSummary {
  const includeTranscripts = options.includeTranscripts !== false;
  const base = byPath(filterBaseFilesForMode(
    normalizeFileStates(options.baseFiles),
    includeTranscripts,
  ));
  const currentMap = byPath(filterBaseFilesForMode(
    normalizeFileStates(options.currentFiles),
    includeTranscripts,
  ));
  let upserts = 0;
  let deletes = 0;
  for (const relPath of unionPaths(base, currentMap)) {
    if (shouldPreferIncomingOfflineRuntimeFile(relPath)) continue;
    if (shouldExcludePushRelPath(relPath, includeTranscripts, options.userExcludeRegexps)) continue;
    const baseEntry = base.get(relPath);
    const currentEntry = currentMap.get(relPath);
    if (currentEntry && currentEntry.sha256 !== baseEntry?.sha256) {
      upserts += 1;
      continue;
    }
    if (!currentEntry && baseEntry) {
      deletes += 1;
    }
  }

  return {
    upserts,
    deletes,
    total: upserts + deletes,
  };
}

export async function applyOfflineSyncSnapshot(options: {
  root: string;
  snapshot: unknown;
  baseFiles?: readonly OfflineSyncFileState[];
  currentFiles?: readonly OfflineSyncFileState[];
  deferredPaths?: readonly string[];
  allowMissingConflictContent?: boolean;
  /**
   * Explicit INCOMING content source for snapshot records without inline
   * `contentBase64` (oversized generation members the client fetched
   * chunk-wise into a private staging root). Consulted only for such
   * records; return null to keep the metadata-only behavior (the local
   * file must hash-match the record). Returned buffers are digest-verified
   * against the incoming record before anything is published.
   */
  readIncomingFile?: (target: { path: string; sha256: string; bytes: number }) => Promise<Buffer | null>;
  writeConflictCopies?: boolean;
  readFile?: (target: OfflineSyncFileTarget) => Promise<Buffer>;
  readFileDigest?: (target: OfflineSyncFileTarget) => Promise<OfflineSyncFileDigest>;
  writeFile?: (target: OfflineSyncFileWriteTarget) => Promise<void>;
  writeStagingFile?: (target: OfflineSyncFileStagingWriteTarget) => Promise<void>;
  readStagingFile?: (target: OfflineSyncFileStagingReadTarget) => Promise<Buffer>;
  deleteFile?: (target: OfflineSyncFileDeleteTarget) => Promise<void>;
  recordDeletionRevision?: OfflineSyncRecordDeletionRevision;
}): Promise<OfflineSyncApplySnapshotResult> {
  const snapshot = normalizeOfflineSyncSnapshot(options.snapshot);
  const baseMap = byPath(filterBaseFilesForMode(
    normalizeFileStates(options.baseFiles),
    snapshot.includeTranscripts,
  ));
  const incomingMap = byPath(snapshot.files);
  const deletionMtimeByPath = snapshot.deletions === undefined
    ? undefined
    : new Map(snapshot.deletions.map((deletion) => [deletion.path, deletion.mtimeMs] as const));
  const incomingBuffers = await verifyRecordContents(snapshot.files, "offline sync snapshot", {
    requireContent: false,
    readIncomingFile: options.readIncomingFile,
  });
  const root = await ensureSyncRoot(options.root, "applyOfflineSyncSnapshot");
  const currentFiles = options.currentFiles
    ? filterBaseFilesForMode(normalizeFileStates(options.currentFiles), snapshot.includeTranscripts).sort(compareByPath)
    : (await buildOfflineSyncSnapshot({
        root: root.abs,
        sourceId: "local",
        includeContent: false,
        includeTranscripts: snapshot.includeTranscripts,
        readFile: options.readFile,
        readFileDigest: options.readFileDigest,
        excludeNodeLocalState: false,
      })).files;
  const currentMap = byPath(currentFiles);
  const deferredPaths = new Set([...(options.deferredPaths ?? []),
    ...divergedEmbeddingGenerationDeferrals({
      incomingFiles: snapshot.files, baseFiles: [...baseMap.values()], currentFiles,
    }),
  ]);
  const omittedGenerationDirs = new Set(snapshot.omittedEmbeddingGenerationDirs ?? []);
  if (deletionMtimeByPath && options.recordDeletionRevision) {
    for (const [relPath, mtimeMs] of deletionMtimeByPath) {
      if (
        currentMap.has(relPath) ||
        deferredPaths.has(relPath) ||
        (omittedGenerationDirs.size > 0 &&
          isPathInOmittedEmbeddingGeneration(relPath, omittedGenerationDirs)) ||
        matchesOfflineSyncDefaultExclude(relPath)
      ) {
        continue;
      }
      await options.recordDeletionRevision({
        root: root.abs,
        path: relPath,
        filePath: await resolveSafeArchiveTarget(root, relPath),
        mtimeMs,
      });
    }
  }
  const nextBase = new Map(baseMap);
  const conflicts: OfflineSyncConflict[] = [];
  let upserted = 0;
  let deleted = 0;
  let skipped = 0;
  let pendingLocal = 0;
  const conflictIncomingBuffer = (relPath: string): Buffer | undefined => {
    if (options.writeConflictCopies === false) return undefined;
    const buffer = incomingBuffers.get(relPath);
    if (buffer || options.allowMissingConflictContent === true) return buffer;
    return requiredBuffer(incomingBuffers, relPath);
  };

  // Embedding generations travel and replace as ONE unit (issue #3148):
  // atomic replacement, cross-layout marker conversion, whole-generation
  // removal on tombstones — all extracted to the generation module (issue
  // #3150) so the changeset path can share it without growing this file.
  const { transactionResults, deferredGenerationDirs } = await applyIncomingEmbeddingGenerations({
    root,
    incomingMap,
    incomingBuffers,
    baseMap,
    currentMap,
    deferredPaths,
    omittedGenerationDirs,
    deletionMtimeByPath,
    io: {
      readFile: options.readFile,
      writeStagingFile: options.writeStagingFile,
      readStagingFile: options.readStagingFile,
      deleteFile: options.deleteFile,
    },
    customIoPresent: Boolean(options.writeFile || options.readFile || options.readFileDigest || options.deleteFile),
    now: Date.now(),
  });

  const transactionHandled = new Set<string>();
  let generationUpserted = 0;
  let generationDeleted = 0;
  for (const result of transactionResults) {
    if (result.deferredLocalDivergence) {
      for (const relPath of result.handledPaths) deferredPaths.add(relPath);
      deferredGenerationDirs.add(result.shardDirRel);
      continue;
    }
    generationUpserted += result.upserted;
    generationDeleted += result.deleted;
    for (const relPath of result.handledPaths) transactionHandled.add(relPath);
    // Record converted shard paths directly; they may not be in any input map.
    for (const [relPath, state] of result.writtenStates) {
      nextBase.set(relPath, state);
      transactionHandled.add(relPath);
    }
    for (const relPath of result.removedPaths) {
      nextBase.delete(relPath);
      transactionHandled.add(relPath);
    }
  }

  for (const relPath of unionPaths(baseMap, incomingMap, currentMap)) {
    const base = baseMap.get(relPath);
    const incoming = incomingMap.get(relPath);
    const currentEntry = currentMap.get(relPath);

    if (deferredPaths.has(relPath)) {
      if (base) nextBase.set(relPath, base);
      else nextBase.delete(relPath);
      skipped += 1;
      continue;
    }

    // The generation transaction already published or removed this path and
    // applied its nextBase bookkeeping above; nothing left to do.
    if (transactionHandled.has(relPath)) continue;

    // A deferral anywhere in a generation defers the WHOLE generation: no
    // partial replacement in either direction, local files and base entries
    // stay exactly as they are.
    const membership = embeddingGenerationMembership(relPath);
    if (membership && deferredGenerationDirs.has(membership.shardDir)) {
      if (base) nextBase.set(relPath, base);
      else nextBase.delete(relPath);
      skipped += 1;
      continue;
    }

    if (incoming) {
      // The generation marker (PR #3176) is node-local on BOTH sides: an
      // incoming copy — old or hostile — never overwrites the local file
      // and never enters the base set. Other default excludes stay
      // apply-accepted (#1786: first-sync LCM sqlite bootstrapping).
      if (isEmbeddingGenerationMarkerPath(relPath)) {
        nextBase.delete(relPath);
        skipped += 1;
        continue;
      }
      if (currentEntry?.sha256 === incoming.sha256) {
        if (await setSafeFileMtime(root, relPath, incoming.mtimeMs)) {
          nextBase.set(relPath, toFileState(incoming));
        } else {
          if (base) nextBase.set(relPath, base);
          else nextBase.delete(relPath);
          pendingLocal += 1;
        }
        skipped += 1;
        continue;
      }
      // Remote unchanged from the shared base while the local file drifted:
      // keep the local copy (no content is needed to make that decision).
      // Members of a replaced generation never reach this branch — the
      // generation transaction or the deferral guard handled them above.
      if (
        shouldPreferIncomingOfflineRuntimeFile(relPath) &&
        currentEntry && base && incoming.sha256 === base.sha256
      ) {
        nextBase.set(relPath, base);
        skipped += 1;
        continue;
      }
      if (shouldPreferIncomingOfflineRuntimeFile(relPath)) {
        await writeSafeFile(root, relPath, requiredBuffer(incomingBuffers, relPath), options.writeFile, incoming.mtimeMs);
        nextBase.set(relPath, toFileState(incoming));
        upserted += 1;
        continue;
      }
      if (!currentEntry && base && incoming.sha256 === base.sha256) {
        nextBase.set(relPath, base);
        pendingLocal += 1;
        skipped += 1;
        continue;
      }
      if (!currentEntry && base && incoming.sha256 !== base.sha256) {
        conflicts.push(await recordConflict({
          root,
          relPath,
          reason: "local_deleted_remote_modified",
          baseSha256: base.sha256,
          incomingSha256: incoming.sha256,
          incomingBuffer: conflictIncomingBuffer(relPath),
          writeConflictCopies: options.writeConflictCopies !== false,
          sourceId: snapshot.sourceId,
          writeFile: options.writeFile,
        }));
        nextBase.set(relPath, base);
        continue;
      }
      if (!currentEntry && !base) {
        // Census miss with on-disk file: uncertain local presence, do not overwrite.
        if (await offlineSyncRegularFilePresent(root, relPath)) {
          pendingLocal += 1;
          skipped += 1;
          continue;
        }
        await writeSafeFile(root, relPath, requiredBuffer(incomingBuffers, relPath), options.writeFile, incoming.mtimeMs);
        nextBase.set(relPath, toFileState(incoming));
        upserted += 1;
        continue;
      }
      if (base && currentEntry && currentEntry.sha256 === base.sha256) {
        await writeSafeFile(root, relPath, requiredBuffer(incomingBuffers, relPath), options.writeFile, incoming.mtimeMs);
        nextBase.set(relPath, toFileState(incoming));
        upserted += 1;
        continue;
      }
      if (base && incoming.sha256 === base.sha256) {
        nextBase.set(relPath, base);
        pendingLocal += 1;
        skipped += 1;
        continue;
      }
      conflicts.push(await recordConflict({
        root,
        relPath,
        reason: base ? "both_modified" : "remote_exists_for_local_create",
        baseSha256: base?.sha256,
        localSha256: currentEntry?.sha256,
        incomingSha256: incoming.sha256,
        incomingBuffer: conflictIncomingBuffer(relPath),
        writeConflictCopies: options.writeConflictCopies !== false,
        sourceId: snapshot.sourceId,
        writeFile: options.writeFile,
      }));
      if (base) nextBase.set(relPath, base);
      continue;
    }

    // Node-local runtime state (#1786): a push-filtered remote snapshot
    // never carries these paths, so their absence is NOT a delete
    // instruction. Drop any stale base entry (pre-#1786 state files still
    // carry them) and leave the local file untouched — deleting a live
    // sqlite WAL/SHM here would corrupt the local LCM store.
    if (matchesOfflineSyncDefaultExclude(relPath)) {
      nextBase.delete(relPath);
      skipped += 1;
      continue;
    }
    if (!currentEntry) {
      nextBase.delete(relPath);
      skipped += 1;
      continue;
    }
    if (
      shouldPreferIncomingOfflineRuntimeFile(relPath) &&
      membership !== null && omittedGenerationDirs.has(membership.shardDir)
    ) {
      // The push omitted this whole generation because a filter excluded at
      // least one member (snapshot.omittedEmbeddingGenerationDirs): absence
      // is NOT a deletion — keep the local generation and its base entries
      // until it is pushed unfiltered or deleted with deletion metadata.
      pendingLocal += 1;
      skipped += 1;
      continue;
    }
    if (
      shouldPreferIncomingOfflineRuntimeFile(relPath) &&
      (base || shouldDeleteAbsentIncomingOfflineRuntimeFile(relPath))
    ) {
      await deleteSafeFile(
        root,
        relPath,
        options.deleteFile,
        deletionMtimeByPath?.get(relPath),
      );
      nextBase.delete(relPath);
      deleted += 1;
      continue;
    }
    if (shouldPreferIncomingOfflineRuntimeFile(relPath)) {
      pendingLocal += 1;
      skipped += 1;
      continue;
    }
    if (base && currentEntry.sha256 === base.sha256) {
      await deleteSafeFile(
        root,
        relPath,
        options.deleteFile,
        deletionMtimeByPath?.get(relPath),
      );
      nextBase.delete(relPath);
      deleted += 1;
      continue;
    }
    if (base) {
      conflicts.push({
        path: relPath,
        reason: "local_modified_remote_deleted",
        baseSha256: base.sha256,
        localSha256: currentEntry.sha256,
      });
      nextBase.set(relPath, base);
      continue;
    }
    pendingLocal += 1;
    skipped += 1;
  }

  return {
    upserted: upserted + generationUpserted,
    deleted: deleted + generationDeleted,
    skipped,
    pendingLocal,
    conflicts,
    nextBaseFiles: [...nextBase.values()].sort(compareByPath),
  };
}

export async function applyOfflineSyncChangeset(options: {
  root: string;
  changeset: unknown;
  currentFiles?: readonly OfflineSyncFileState[];
  returnCurrentFiles?: boolean;
  writeConflictCopies?: boolean;
  readFile?: (target: OfflineSyncFileTarget) => Promise<Buffer>;
  readFileDigest?: (target: OfflineSyncFileTarget) => Promise<OfflineSyncFileDigest>;
  writeFile?: (target: OfflineSyncFileWriteTarget) => Promise<void>;
  writeStagingFile?: (target: OfflineSyncFileStagingWriteTarget) => Promise<void>;
  readStagingFile?: (target: OfflineSyncFileStagingReadTarget) => Promise<Buffer>;
  deleteFile?: (target: OfflineSyncFileDeleteTarget) => Promise<void>;
  recordDeletionRevision?: OfflineSyncRecordDeletionRevision;
}): Promise<OfflineSyncApplyChangesetResult> {
  let changeset: OfflineSyncChangeset;
  try {
    changeset = normalizeOfflineSyncChangeset(options.changeset);
  } catch (error) {
    const message = error instanceof Error ? error.message : String(error);
    throw new Error(
      message.startsWith("offline sync")
        ? message
        : `offline sync changeset invalid: ${message}`,
    );
  }
  const root = await ensureSyncRoot(options.root, "applyOfflineSyncChangeset");
  const records = changeset.changes
    .filter((change): change is Extract<OfflineSyncChange, { type: "upsert" }> => change.type === "upsert")
    .map((change) => change.file);
  const incomingBuffers = await verifyRecordContents(records, "offline sync changeset");
  const currentFiles = options.currentFiles
    ? filterBaseFilesForMode(normalizeFileStates(options.currentFiles), changeset.includeTranscripts).sort(compareByPath)
    : (await buildOfflineSyncSnapshotForPaths({
        root: root.abs,
        sourceId: "local",
        paths: changeset.changes.map((change) => change.path),
        includeContent: false,
        includeTranscripts: changeset.includeTranscripts,
        readFile: options.readFile,
        readFileDigest: options.readFileDigest,
        excludeNodeLocalState: false,
      })).files;
  const currentMap = byPath(currentFiles);
  const conflicts: OfflineSyncConflict[] = [];
  let appliedUpserts = 0;
  let appliedDeletes = 0;
  let skipped = 0;

  // Embedding generations apply as ONE unit through the shared locked
  // transaction (issue #3150). Deferred generations surface as conflicts so
  // the push side never checkpoints them as applied.
  const generationRouting = await applyChangesetEmbeddingGenerations({
    root,
    changeset,
    incomingBuffers,
    currentMap,
    io: {
      readFile: options.readFile,
      writeStagingFile: options.writeStagingFile,
      readStagingFile: options.readStagingFile,
      deleteFile: options.deleteFile,
    },
    customIoPresent: Boolean(options.writeFile || options.readFile || options.readFileDigest || options.deleteFile),
    now: Date.now(),
  });
  appliedUpserts += generationRouting.appliedUpserts;
  appliedDeletes += generationRouting.appliedDeletes;
  conflicts.push(...generationRouting.conflicts);

  for (const change of changeset.changes) {
    if (generationRouting.conflictedPaths.has(change.path)) continue;
    if (generationRouting.transactionHandled.has(change.path)) continue;
    if (isEmbeddingGenerationMarkerPath(change.path)) {
      skipped += 1;
      continue;
    }
    const currentEntry = currentMap.get(change.path);
    if (change.type === "upsert") {
      if (currentEntry?.sha256 === change.file.sha256) {
        if (await setSafeFileMtime(root, change.path, change.file.mtimeMs)) {
          skipped += 1;
        } else {
          await writeSafeFile(root, change.path, requiredBuffer(incomingBuffers, change.path), options.writeFile, change.file.mtimeMs);
          currentMap.set(change.path, toFileState(change.file));
          appliedUpserts += 1;
        }
        continue;
      }
      if (!change.baseSha256) {
        if (!currentEntry) {
          await writeSafeFile(root, change.path, requiredBuffer(incomingBuffers, change.path), options.writeFile, change.file.mtimeMs);
          currentMap.set(change.path, toFileState(change.file));
          appliedUpserts += 1;
          continue;
        }
        conflicts.push(await recordConflict({
          root,
          relPath: change.path,
          reason: "remote_exists_for_local_create",
          localSha256: currentEntry.sha256,
          incomingSha256: change.file.sha256,
          incomingBuffer: incomingBuffers.get(change.path),
          writeConflictCopies: options.writeConflictCopies !== false,
          sourceId: changeset.sourceId,
          writeFile: options.writeFile,
        }));
        continue;
      }
      if (currentEntry?.sha256 === change.baseSha256) {
        await writeSafeFile(root, change.path, requiredBuffer(incomingBuffers, change.path), options.writeFile, change.file.mtimeMs);
        currentMap.set(change.path, toFileState(change.file));
        appliedUpserts += 1;
        continue;
      }
      conflicts.push(await recordConflict({
        root,
        relPath: change.path,
        reason: currentEntry ? "remote_changed_for_local_update" : "remote_deleted_for_local_update",
        baseSha256: change.baseSha256,
        localSha256: currentEntry?.sha256,
        incomingSha256: change.file.sha256,
        incomingBuffer: incomingBuffers.get(change.path),
        writeConflictCopies: options.writeConflictCopies !== false,
        sourceId: changeset.sourceId,
        writeFile: options.writeFile,
      }));
      continue;
    }

    if (!currentEntry) {
      if (change.mtimeMs !== undefined && options.recordDeletionRevision) {
        await options.recordDeletionRevision({
          root: root.abs,
          path: change.path,
          filePath: await resolveSafeArchiveTarget(root, change.path),
          mtimeMs: change.mtimeMs,
        });
      }
      skipped += 1;
      continue;
    }
    if (currentEntry.sha256 === change.baseSha256) {
      await deleteSafeFile(root, change.path, options.deleteFile, change.mtimeMs);
      currentMap.delete(change.path);
      appliedDeletes += 1;
      continue;
    }
    conflicts.push({
      path: change.path,
      reason: "remote_changed_for_local_delete",
      baseSha256: change.baseSha256,
      localSha256: currentEntry.sha256,
    });
  }

  // Generation transactions bypassed the per-file loop; fold their published
  // and removed members into the partial result map (returnCurrentFiles ===
  // false consumers) so it reflects the post-apply generation exactly.
  for (const [relPath, state] of generationRouting.writtenStates) currentMap.set(relPath, state);
  for (const relPath of generationRouting.removedPaths) currentMap.delete(relPath);

  return {
    appliedUpserts,
    appliedDeletes,
    skipped,
    conflicts,
    currentFiles: options.returnCurrentFiles === false
      ? [...currentMap.values()].sort(compareByPath)
      : (await buildOfflineSyncSnapshot({
          root: root.abs,
          sourceId: "local",
          includeContent: false,
          includeTranscripts: changeset.includeTranscripts,
          readFile: options.readFile,
          readFileDigest: options.readFileDigest,
          excludeNodeLocalState: false,
        })).files,
    ...(options.returnCurrentFiles === false ? { currentFilesComplete: false } : {}),
  };
}

async function verifyRecordContents(
  records: readonly OfflineSyncFileRecord[],
  context: string,
  options: {
    requireContent?: boolean;
    readIncomingFile?: (target: { path: string; sha256: string; bytes: number }) => Promise<Buffer | null>;
  } = {},
): Promise<Map<string, Buffer>> {
  const buffers = new Map<string, Buffer>();
  for (const record of records) {
    if (typeof record.contentBase64 !== "string") {
      if (options.readIncomingFile) {
        // Explicit INCOMING content source for records whose bytes travel
        // out-of-band (chunked fetch into the client's private staging
        // root). Never the local current-state file: the buffer is
        // digest-verified against the incoming record before anything is
        // published. null keeps the metadata-only behavior below.
        const incoming = await options.readIncomingFile({
          path: record.path,
          sha256: record.sha256,
          bytes: record.bytes,
        });
        if (incoming) {
          const digest = sha256Buffer(incoming);
          if (digest.sha256 !== record.sha256 || digest.bytes !== record.bytes) {
            throw new Error(`${context}: incoming content checksum mismatch for ${record.path}`);
          }
          buffers.set(record.path, incoming);
          continue;
        }
      }
      if (options.requireContent === false) continue;
      throw new Error(`${context}: contentBase64 is required for ${record.path}`);
    }
    const buffer = Buffer.from(record.contentBase64, "base64");
    const digest = sha256Buffer(buffer);
    if (digest.sha256 !== record.sha256 || digest.bytes !== record.bytes) {
      throw new Error(
        `${context}: content checksum mismatch for ${record.path}`,
      );
    }
    buffers.set(record.path, buffer);
  }
  return buffers;
}

function requiredBuffer(buffers: Map<string, Buffer>, relPath: string): Buffer {
  const buffer = buffers.get(relPath);
  if (!buffer) {
    throw new Error(`missing decoded content for ${relPath}`);
  }
  return buffer;
}

async function ensureSyncRoot(rootPath: string, errorPrefix: string): Promise<SafeArchiveRoot> {
  const rootAbs = path.resolve(rootPath);
  await mkdir(rootAbs, { recursive: true });
  return prepareSafeArchiveRoot(rootAbs, errorPrefix, "root");
}

function byPath<T extends OfflineSyncFileState>(files: readonly T[]): Map<string, T> {
  const out = new Map<string, T>();
  for (const file of files) {
    out.set(validateArchiveRelativePath(file.path, "offlineSync"), file);
  }
  return out;
}

function unionPaths(...maps: Array<Map<string, unknown>>): string[] {
  const paths = new Set<string>();
  for (const map of maps) {
    for (const key of map.keys()) paths.add(key);
  }
  return [...paths].sort();
}

function toFileState(file: OfflineSyncFileState): OfflineSyncFileState {
  return {
    path: file.path,
    sha256: file.sha256,
    bytes: file.bytes,
    mtimeMs: file.mtimeMs,
  };
}

async function writeSafeFile(
  root: SafeArchiveRoot,
  relPath: string,
  content: Buffer,
  writeFileHook?: (target: OfflineSyncFileWriteTarget) => Promise<void>,
  mtimeMs?: number,
): Promise<void> {
  const target = await resolveSafeArchiveTarget(root, relPath);
  if (writeFileHook) {
    await writeFileHook({ root: root.abs, path: relPath, filePath: target, content });
    await setSafeFileMtime(root, relPath, mtimeMs);
    return;
  }
  await mkdir(path.dirname(target), { recursive: true });
  const tmp = path.join(
    path.dirname(target),
    `.remnic-sync.${process.pid}.${randomUUID()}.tmp`,
  );
  await writeFile(tmp, content);
  try {
    const targetStat = await lstat(target).catch((error: unknown) => {
      if ((error as NodeJS.ErrnoException).code === "ENOENT") return null;
      throw error;
    });
    if (targetStat?.isSymbolicLink()) {
      throw new Error(`offline sync target is a symlink: ${relPath}`);
    }
    await rename(tmp, target);
    await setSafeFileMtime(root, relPath, mtimeMs);
  } catch (error) {
    await unlink(tmp).catch(() => {});
    throw error;
  }
}


/**
 * Read the local file digest for a single relative path without applying
 * push-side exclude rules. Used by apply-side helpers that need to check
 * the current local state of a path that the push-side exclude would
 * reject (e.g. `state/lcm.sqlite`). Returns `null` if the file does not
 * exist, is not a regular file, or is a symlink.
 */
async function readLocalFileState(options: {
  rootAbs: string;
  relPath: string;
  readFile?: (target: OfflineSyncFileTarget) => Promise<Buffer>;
  readFileDigest?: (target: OfflineSyncFileTarget) => Promise<OfflineSyncFileDigest>;
  signal?: AbortSignal;
}): Promise<OfflineSyncFileState | null> {
  const filePath = await resolveSafeArchiveTarget(
    await prepareSafeArchiveRoot(options.rootAbs, "readLocalFileState", "rootAbs"),
    options.relPath,
  );
  const st = await lstat(filePath).catch((error: unknown) => {
    if ((error as NodeJS.ErrnoException).code === "ENOENT") return null;
    throw error;
  });
  if (!st || st.isSymbolicLink() || !st.isFile()) return null;
  throwIfOfflineSyncAborted(options.signal);
  let digest: OfflineSyncFileDigest;
  if (options.readFileDigest) {
    digest = await options.readFileDigest({ root: options.rootAbs, path: options.relPath, filePath });
  } else if (options.readFile) {
    const content = await options.readFile({ root: options.rootAbs, path: options.relPath, filePath });
    digest = sha256Buffer(content);
  } else {
    digest = await sha256OfflineSyncFile(filePath, options.signal);
  }
  throwIfOfflineSyncAborted(options.signal);
  return {
    path: options.relPath,
    sha256: digest.sha256,
    bytes: digest.bytes,
    mtimeMs: st.mtimeMs,
  };
}

export async function applyOfflineSyncFileContentChunk(options: {
  root: string;
  sourceId: string;
  path: string;
  sha256: string;
  bytes: number;
  mtimeMs: number;
  offset?: number;
  content: Buffer;
  baseSha256?: string;
  includeTranscripts?: boolean;
  readFile?: (target: OfflineSyncFileTarget) => Promise<Buffer>;
  readFileDigest?: (target: OfflineSyncFileTarget) => Promise<OfflineSyncFileDigest>;
  writeFile?: (target: OfflineSyncFileWriteTarget) => Promise<void>;
  writeStagingFile?: (target: OfflineSyncFileStagingWriteTarget) => Promise<void>;
  writeFileChunks?: (target: OfflineSyncFileWriteChunksTarget) => Promise<void>;
}): Promise<OfflineSyncApplyFileContentChunkResult> {
  const root = await ensureSyncRoot(options.root, "applyOfflineSyncFileContentChunk");
  const sourceId = normalizeSourceId(options.sourceId, "sourceId");
  const relPath = normalizeRelativePath(options.path, "path");
  const includeTranscripts = options.includeTranscripts !== false;
  if (shouldExcludeRelPath(relPath, includeTranscripts)) {
    throw new Error(`offline sync file content path is excluded: ${relPath}`);
  }
  if (isEmbeddingGenerationMarkerPath(relPath)) {
    throw new Error(`offline sync file content path is node-local: ${relPath}`);
  }
  const sha256 = assertSha256(options.sha256, "sha256");
  const bytes = assertNonNegativeInteger(options.bytes, "bytes");
  const mtimeMs = assertOfflineSyncMtimeMs(options.mtimeMs, "mtimeMs");
  const offset = options.offset === undefined
    ? 0
    : assertNonNegativeInteger(options.offset, "offset");
  const baseSha256 = options.baseSha256 === undefined
    ? undefined
    : assertSha256(options.baseSha256, "baseSha256");
  const preferIncomingRuntimeFile = shouldPreferIncomingOfflineRuntimeFile(relPath);
  if (!Buffer.isBuffer(options.content)) {
    throw new Error("content must be a Buffer");
  }
  if (options.content.length > OFFLINE_SYNC_FILE_CONTENT_MAX_CHUNK_BYTES) {
    throw new Error(
      `content chunk must be ${OFFLINE_SYNC_FILE_CONTENT_MAX_CHUNK_BYTES} bytes or fewer`,
    );
  }
  if (bytes > 0 && options.content.length === 0) {
    throw new Error("content chunk must be non-empty before EOF");
  }
  if (offset > bytes || offset + options.content.length > bytes) {
    throw new Error(`content chunk range exceeds declared file size for ${relPath}`);
  }
  if (options.writeFile && !options.writeFileChunks) {
    throw new Error("offline sync upload storage hooks require writeFileChunks");
  }
  if (options.writeFile && !options.writeStagingFile) {
    throw new Error("offline sync upload storage hooks require writeStagingFile");
  }
  const baseResult = {
    path: relPath,
    sha256,
    bytes,
    mtimeMs,
    offset,
    chunkBytes: options.content.length,
    done: offset + options.content.length === bytes,
  };
  const currentFileConflict = async (
    currentFile: OfflineSyncFileState | undefined,
  ): Promise<{ conflict: OfflineSyncConflict; currentFile?: OfflineSyncFileState } | null> => {
    if (!baseSha256 && currentFile && !preferIncomingRuntimeFile) {
      const conflict = await recordConflict({
        root,
        relPath,
        reason: "remote_exists_for_local_create",
        localSha256: currentFile.sha256,
        incomingSha256: sha256,
        writeConflictCopies: false,
        sourceId,
        writeFile: options.writeFile,
      });
      return {
        conflict,
        currentFile,
      };
    }
    if (baseSha256 && currentFile?.sha256 !== baseSha256 && !preferIncomingRuntimeFile) {
      const conflict = await recordConflict({
        root,
        relPath,
        reason: currentFile ? "remote_changed_for_local_update" : "remote_deleted_for_local_update",
        baseSha256,
        localSha256: currentFile?.sha256,
        incomingSha256: sha256,
        writeConflictCopies: false,
        sourceId,
        writeFile: options.writeFile,
      });
      return {
        conflict,
        ...(currentFile ? { currentFile } : {}),
      };
    }
    return null;
  };
  if (offset === 0) {
    await pruneOfflineUploadStaging(root);
    const currentFile = await readLocalFileState({
      rootAbs: root.abs,
      relPath,
      readFile: options.readFile,
      readFileDigest: options.readFileDigest,
    });
    if (currentFile && currentFile.sha256 === sha256) {
      await setSafeFileMtime(root, relPath, mtimeMs);
      return {
        ...baseResult,
        done: true,
        chunkBytes: 0,
        applied: false,
        skipped: true,
        currentFile: toFileState(currentFile),
      };
    }
    const conflictResult = await currentFileConflict(currentFile ? toFileState(currentFile) : undefined);
    if (conflictResult) {
      return {
        ...baseResult,
        done: true,
        chunkBytes: 0,
        applied: false,
        skipped: false,
        ...conflictResult,
      };
    }
  }

  const upload = await writeOfflineUploadChunk({
    root,
    sourceId,
    relPath,
    sha256,
    bytes,
    offset,
    content: options.content,
    readFile: options.readFile,
    writeFile: options.writeFile,
    writeStagingFile: options.writeStagingFile,
  });
  const done = baseResult.done;
  if (!done) {
    return {
      ...baseResult,
      applied: false,
      skipped: false,
    };
  }

  const digest = await digestOfflineUploadStagingContent({
    root,
    upload,
    readFile: options.readFile,
  });
  if (digest.sha256 !== sha256 || digest.bytes !== bytes) {
    await cleanupOfflineUpload(upload).catch(() => {});
    throw new Error(`offline sync upload checksum mismatch for ${relPath}`);
  }

  const currentFile = await readLocalFileState({
    rootAbs: root.abs,
    relPath,
    readFile: options.readFile,
    readFileDigest: options.readFileDigest,
  });
  const uploadedState: OfflineSyncFileState = {
    path: relPath,
    sha256,
    bytes,
    mtimeMs,
  };

  try {
    if (currentFile && currentFile.sha256 === sha256) {
      await setSafeFileMtime(root, relPath, mtimeMs);
      return {
        ...baseResult,
        applied: false,
        skipped: true,
        currentFile: uploadedState,
      };
    }

    const conflictResult = await currentFileConflict(currentFile ? toFileState(currentFile) : undefined);
    if (conflictResult) {
      return {
        ...baseResult,
        applied: false,
        skipped: false,
        ...conflictResult,
      };
    }

    await advanceEmbeddingGenerationMarker(root.abs, embeddingGenerationMembership(relPath), () =>
      writeSafeFileFromUpload(root, relPath, upload, options.readFile, options.writeFileChunks, mtimeMs),
    );
    return {
      ...baseResult,
      applied: true,
      skipped: false,
      currentFile: uploadedState,
    };
  } finally {
    await cleanupOfflineUpload(upload).catch(() => {});
  }
}


async function deleteSafeFile(
  root: SafeArchiveRoot,
  relPath: string,
  deleteFile?: (target: OfflineSyncFileDeleteTarget) => Promise<void>,
  mtimeMs?: number,
): Promise<void> {
  const target = await resolveSafeArchiveTarget(root, relPath);
  if (deleteFile) {
    await deleteFile({
      root: root.abs,
      path: relPath,
      filePath: target,
      ...(mtimeMs === undefined ? {} : { mtimeMs }),
    });
    return;
  }
  await unlink(target).catch((error: unknown) => {
    if ((error as NodeJS.ErrnoException).code === "ENOENT") return;
    throw error;
  });
}

async function recordConflict(options: {
  root: SafeArchiveRoot;
  relPath: string;
  reason: OfflineSyncConflict["reason"];
  baseSha256?: string;
  localSha256?: string;
  incomingSha256?: string;
  incomingBuffer?: Buffer;
  writeConflictCopies: boolean;
  sourceId: string;
  writeFile?: (target: OfflineSyncFileWriteTarget) => Promise<void>;
}): Promise<OfflineSyncConflict> {
  let conflictPath: string | undefined;
  if (options.writeConflictCopies && options.incomingBuffer) {
    const sourceHash = hashText(options.sourceId).slice(0, 12);
    const stamp = new Date().toISOString().replace(/[:.]/g, "-");
    conflictPath = `${SYNC_INTERNAL_DIR}/conflicts/${stamp}-${sourceHash}/${options.relPath}`;
    await writeSafeFile(options.root, conflictPath, options.incomingBuffer, options.writeFile);
  }
  return {
    path: options.relPath,
    reason: options.reason,
    baseSha256: options.baseSha256,
    localSha256: options.localSha256,
    incomingSha256: options.incomingSha256,
    ...(conflictPath ? { conflictPath } : {}),
  };
}

export function defaultOfflineSyncStatePath(
  memoryDir: string,
  remoteId: string,
  namespace?: string,
): string {
  const key = hashText(`${remoteId}\0${namespace ?? ""}`).slice(0, 16);
  return path.join(path.resolve(memoryDir), SYNC_INTERNAL_DIR, "state", `${key}.json`);
}

export async function readOfflineSyncState(
  statePath: string,
): Promise<OfflineSyncState | null> {
  let raw: string;
  try {
    raw = await readFile(path.resolve(statePath), "utf-8");
  } catch (error) {
    if ((error as NodeJS.ErrnoException).code === "ENOENT") return null;
    throw error;
  }
  const parsed = JSON.parse(raw) as unknown;
  return normalizeOfflineSyncState(parsed);
}

export async function writeOfflineSyncState(
  statePath: string,
  state: OfflineSyncState,
): Promise<void> {
  const normalized = normalizeOfflineSyncState(state);
  const target = path.resolve(statePath);
  await mkdir(path.dirname(target), { recursive: true });
  const tmp = path.join(
    path.dirname(target),
    `.remnic-sync-state.${process.pid}.${randomUUID()}.tmp`,
  );
  await writeFile(tmp, JSON.stringify(normalized, null, 2) + "\n", "utf-8");
  try {
    await rename(tmp, target);
  } catch (error) {
    await unlink(tmp).catch(() => {});
    throw error;
  }
}

export function offlineSyncStateFromSnapshot(options: {
  remoteId: string;
  namespace?: string;
  snapshot: OfflineSyncSnapshot;
  baseFiles?: readonly OfflineSyncFileState[];
}): OfflineSyncState {
  const snapshot = normalizeOfflineSyncSnapshot(options.snapshot);
  return normalizeOfflineSyncState({
    version: OFFLINE_SYNC_STATE_VERSION,
    remoteId: options.remoteId,
    namespace: options.namespace,
    includeTranscripts: snapshot.includeTranscripts,
    lastSyncedAt: new Date().toISOString(),
    baseFiles: options.baseFiles ?? snapshot.files.map(toFileState),
  });
}

export function normalizeOfflineSyncState(input: unknown): OfflineSyncState {
  if (!input || typeof input !== "object" || Array.isArray(input)) {
    throw new Error("offline sync state must be an object");
  }
  const obj = input as Record<string, unknown>;
  if (obj.version !== OFFLINE_SYNC_STATE_VERSION) {
    throw new Error(`offline sync state version must be ${OFFLINE_SYNC_STATE_VERSION}`);
  }
  const namespace =
    typeof obj.namespace === "string" && obj.namespace.trim().length > 0
      ? obj.namespace.trim()
      : undefined;
  const baseFiles = normalizeFileStates(obj.baseFiles as readonly unknown[] | undefined)
    .sort(compareByPath);
  assertUniquePaths(baseFiles, "offline sync state");
  return {
    version: OFFLINE_SYNC_STATE_VERSION,
    remoteId: normalizeSourceId(obj.remoteId, "remoteId"),
    ...(namespace ? { namespace } : {}),
    includeTranscripts: assertBoolean(obj.includeTranscripts, "includeTranscripts"),
    lastSyncedAt: normalizeIsoString(obj.lastSyncedAt, "lastSyncedAt"),
    baseFiles,
  };
}

export function fileStatesFromSnapshot(snapshot: OfflineSyncSnapshot): OfflineSyncFileState[] {
  return normalizeOfflineSyncSnapshot(snapshot).files.map(toFileState).sort(compareByPath);
}

import path from "node:path";
import { assertExternalWikiRootOutsideMemoryDir } from "./external-wiki-guard.js";
import { expandTildePath } from "./utils/path.js";

export interface ExternalWikiRoot {
  id: string;
  rootDir: string;
  enabled: boolean;
  label?: string;
  pagesDir: string;
  indexFile: string;
  indexInQmd: boolean;
  includeInDefaultRecall: false;
}

const EXTERNAL_WIKI_ID_PATTERN = /^[a-z0-9][a-z0-9_-]{0,63}$/;

function requireObject(value: unknown, keyName: string): Record<string, unknown> {
  if (!value || typeof value !== "object" || Array.isArray(value)) {
    throw new Error(`${keyName} must be an object`);
  }
  return value as Record<string, unknown>;
}

function requireString(value: unknown, keyName: string): string {
  if (typeof value !== "string" || value.trim().length === 0) {
    throw new Error(`${keyName} must be a non-empty string`);
  }
  return value.trim();
}

function parseBoolean(value: unknown, fallback: boolean, keyName: string): boolean {
  if (value === undefined) return fallback;
  if (typeof value !== "boolean") throw new Error(`${keyName} must be a boolean`);
  return value;
}

function parseRootDir(value: unknown, keyName: string): string {
  const raw = requireString(value, keyName);
  if (!path.isAbsolute(raw) && !raw.startsWith("~/")) {
    throw new Error(`${keyName} must be an absolute path or start with ~/`);
  }
  return path.resolve(expandTildePath(raw));
}

function parseRootRelativePath(value: unknown, fallback: string, keyName: string): string {
  const candidate = value === undefined ? fallback : requireString(value, keyName);
  if (candidate.includes("\\")) {
    throw new Error(`${keyName} must use POSIX separators`);
  }
  const normalized = path.normalize(candidate);
  if (
    path.isAbsolute(candidate) ||
    normalized === ".." ||
    normalized.startsWith(`..${path.sep}`) ||
    normalized === "."
  ) {
    throw new Error(`${keyName} must be a relative path within rootDir`);
  }
  return normalized;
}

export function parseExternalWikiRoots(value: unknown, memoryDir?: string): ExternalWikiRoot[] {
  if (value === undefined) return [];
  if (!Array.isArray(value)) throw new Error("externalWikis must be an array");

  const seenIds = new Set<string>();
  return value.map((entry, index) => {
    const keyName = `externalWikis[${index}]`;
    const raw = requireObject(entry, keyName);
    const id = requireString(raw.id, `${keyName}.id`);
    if (!EXTERNAL_WIKI_ID_PATTERN.test(id)) {
      throw new Error(`${keyName}.id must match ${EXTERNAL_WIKI_ID_PATTERN}`);
    }
    if (seenIds.has(id)) throw new Error(`externalWikis contains duplicate id "${id}"`);
    seenIds.add(id);

    const includeInDefaultRecall = parseBoolean(raw.includeInDefaultRecall, false, `${keyName}.includeInDefaultRecall`);
    if (includeInDefaultRecall) {
      throw new Error(`${keyName}.includeInDefaultRecall=true is not supported yet`);
    }

    const rootDir = parseRootDir(raw.rootDir, `${keyName}.rootDir`);
    if (memoryDir !== undefined) {
      assertExternalWikiRootOutsideMemoryDir(memoryDir, rootDir);
    }

    const label = raw.label === undefined ? undefined : requireString(raw.label, `${keyName}.label`);
    return {
      id,
      rootDir,
      enabled: parseBoolean(raw.enabled, true, `${keyName}.enabled`),
      ...(label === undefined ? {} : { label }),
      pagesDir: parseRootRelativePath(raw.pagesDir, "wiki", `${keyName}.pagesDir`),
      indexFile: parseRootRelativePath(raw.indexFile, "INDEX.md", `${keyName}.indexFile`),
      indexInQmd: parseBoolean(raw.indexInQmd, false, `${keyName}.indexInQmd`),
      includeInDefaultRecall: false,
    };
  });
}

import { coerceBool } from "../connectors/coerce.js";
import type {
  ScopeProfileConfig,
  ScopeProfileLayerId,
  ScopeProfilePromotionTarget,
  ScopeTeamConfig,
} from "../types.js";

const SCOPE_PROFILE_LAYER_IDS = [
  "userProject",
  "teamProject",
  "userGlobal",
  "serverShared",
] as const satisfies readonly ScopeProfileLayerId[];
const SCOPE_PROFILE_PROMOTION_TARGETS = [
  ...SCOPE_PROFILE_LAYER_IDS,
] as const satisfies readonly ScopeProfilePromotionTarget[];
const SCOPE_PROFILE_AUTO_PROMOTE_CATEGORIES = [
  "fact",
  "correction",
  "decision",
  "preference",
  "rule",
  "procedure",
] as const;
const CONFIDENCE_TIERS = ["explicit", "implied", "inferred", "speculative"] as const;

type ConfidenceTier = (typeof CONFIDENCE_TIERS)[number];
type AutoPromoteCategory = (typeof SCOPE_PROFILE_AUTO_PROMOTE_CATEGORIES)[number];

function isConfidenceTier(value: unknown): value is ConfidenceTier {
  return typeof value === "string" && (CONFIDENCE_TIERS as readonly string[]).includes(value);
}

function isAutoPromoteCategory(value: unknown): value is AutoPromoteCategory {
  return typeof value === "string" && (SCOPE_PROFILE_AUTO_PROMOTE_CATEGORIES as readonly string[]).includes(value);
}

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

function parseStringList(value: unknown, keyName: string): string[] {
  if (value === undefined || value === null) return [];
  if (!Array.isArray(value)) {
    throw new Error(`${keyName} must be an array`);
  }
  const out: string[] = [];
  for (const entry of value) {
    if (typeof entry !== "string" || entry.length === 0) {
      throw new Error(`${keyName} must contain only non-empty strings`);
    }
    out.push(entry);
  }
  return out;
}

function parseScopeProfileLayerList(
  value: unknown,
  keyName: string,
  fallback: ScopeProfileLayerId[]
): ScopeProfileLayerId[] {
  if (value === undefined || value === null) return [...fallback];
  if (!Array.isArray(value)) {
    throw new Error(`${keyName} must be an array`);
  }
  const out: ScopeProfileLayerId[] = [];
  for (const entry of value) {
    if (!SCOPE_PROFILE_LAYER_IDS.includes(entry as ScopeProfileLayerId)) {
      throw new Error(`${keyName} contains unsupported layer: ${String(entry)}`);
    }
    if (!out.includes(entry as ScopeProfileLayerId)) {
      out.push(entry as ScopeProfileLayerId);
    }
  }
  return out;
}

function parseScopeProfilePromotionTargets(value: unknown, keyName: string): ScopeProfilePromotionTarget[] {
  if (value === undefined || value === null) return [];
  if (!Array.isArray(value)) {
    throw new Error(`${keyName} must be an array`);
  }
  const out: ScopeProfilePromotionTarget[] = [];
  for (const entry of value) {
    if (!SCOPE_PROFILE_PROMOTION_TARGETS.includes(entry as ScopeProfilePromotionTarget)) {
      throw new Error(`${keyName} contains unsupported target: ${String(entry)}`);
    }
    if (!out.includes(entry as ScopeProfilePromotionTarget)) {
      out.push(entry as ScopeProfilePromotionTarget);
    }
  }
  return out;
}

export function parseScopeProfiles(value: unknown): Record<string, ScopeProfileConfig> {
  if (value === undefined || value === null) return {};
  if (!isRecord(value)) {
    throw new Error("scopeProfiles must be an object");
  }
  const profiles: Record<string, ScopeProfileConfig> = {};
  for (const [profileId, rawProfile] of Object.entries(value)) {
    if (profileId.trim().length === 0) {
      throw new Error("scopeProfiles keys must not be empty");
    }
    if (!isRecord(rawProfile)) {
      throw new Error(`scopeProfiles.${profileId} must be an object`);
    }
    const readOrder = parseScopeProfileLayerList(rawProfile.readOrder, `scopeProfiles.${profileId}.readOrder`, [
      "userProject",
      "userGlobal",
      "serverShared",
    ]);
    const writeDefault =
      rawProfile.writeDefault === undefined || rawProfile.writeDefault === null
        ? "userProject"
        : rawProfile.writeDefault;
    if (!SCOPE_PROFILE_LAYER_IDS.includes(writeDefault as ScopeProfileLayerId)) {
      throw new Error(`scopeProfiles.${profileId}.writeDefault contains unsupported layer: ${String(writeDefault)}`);
    }
    if (rawProfile.teamProject !== undefined && rawProfile.teamProject !== null && !isRecord(rawProfile.teamProject)) {
      throw new Error(`scopeProfiles.${profileId}.teamProject must be an object`);
    }
    const teamProject = (() => {
      if (!isRecord(rawProfile.teamProject)) return undefined;
      const out: NonNullable<ScopeProfileConfig["teamProject"]> = {};
      if (rawProfile.teamProject.namespaceTemplate !== undefined) {
        if (
          typeof rawProfile.teamProject.namespaceTemplate !== "string" ||
          rawProfile.teamProject.namespaceTemplate.length === 0
        ) {
          throw new Error(`scopeProfiles.${profileId}.teamProject.namespaceTemplate must be a non-empty string`);
        }
        out.namespaceTemplate = rawProfile.teamProject.namespaceTemplate;
      }
      if (rawProfile.teamProject.teamId !== undefined) {
        if (typeof rawProfile.teamProject.teamId !== "string" || rawProfile.teamProject.teamId.length === 0) {
          throw new Error(`scopeProfiles.${profileId}.teamProject.teamId must be a non-empty string`);
        }
        out.teamId = rawProfile.teamProject.teamId;
      }
      return out;
    })();
    if (rawProfile.autoPromote !== undefined && rawProfile.autoPromote !== null && !isRecord(rawProfile.autoPromote)) {
      throw new Error(`scopeProfiles.${profileId}.autoPromote must be an object`);
    }
    const rawAutoPromote = isRecord(rawProfile.autoPromote) ? rawProfile.autoPromote : {};
    const hasAutoPromoteEnabled = Object.prototype.hasOwnProperty.call(rawAutoPromote, "enabled");
    const autoPromoteEnabled = coerceBool(rawAutoPromote.enabled);
    if (hasAutoPromoteEnabled && autoPromoteEnabled === undefined) {
      throw new Error(`scopeProfiles.${profileId}.autoPromote.enabled must be a boolean or boolean-like string`);
    }
    const minConfidenceTier = (() => {
      const rawTier = rawAutoPromote.minConfidenceTier;
      if (rawTier === undefined || rawTier === null) return "explicit";
      if (!isConfidenceTier(rawTier)) {
        throw new Error(
          `scopeProfiles.${profileId}.autoPromote.minConfidenceTier must be one of: ${CONFIDENCE_TIERS.join(", ")}`
        );
      }
      return rawTier;
    })();
    const autoPromoteCategories: AutoPromoteCategory[] = (() => {
      if (rawAutoPromote.categories === undefined || rawAutoPromote.categories === null) {
        return ["fact", "correction", "decision", "preference"];
      }
      if (!Array.isArray(rawAutoPromote.categories)) {
        throw new Error(`scopeProfiles.${profileId}.autoPromote.categories must be an array`);
      }
      const categories: AutoPromoteCategory[] = [];
      for (const entry of rawAutoPromote.categories) {
        if (!isAutoPromoteCategory(entry)) {
          throw new Error(
            `scopeProfiles.${profileId}.autoPromote.categories must contain only: ${SCOPE_PROFILE_AUTO_PROMOTE_CATEGORIES.join(", ")}`
          );
        }
        categories.push(entry);
      }
      return categories;
    })();
    profiles[profileId] = {
      readOrder,
      writeDefault: writeDefault as ScopeProfileLayerId,
      promotionTargets: parseScopeProfilePromotionTargets(
        rawProfile.promotionTargets,
        `scopeProfiles.${profileId}.promotionTargets`
      ),
      ...(teamProject && Object.keys(teamProject).length > 0 ? { teamProject } : {}),
      autoPromote: {
        enabled: autoPromoteEnabled === true,
        targets: parseScopeProfilePromotionTargets(
          rawAutoPromote.targets,
          `scopeProfiles.${profileId}.autoPromote.targets`
        ),
        categories: autoPromoteCategories,
        minConfidenceTier,
      },
    };
  }
  return profiles;
}

export function parseScopeTeams(value: unknown): Record<string, ScopeTeamConfig> {
  if (value === undefined || value === null) return {};
  if (!isRecord(value)) {
    throw new Error("teams must be an object");
  }
  const teams: Record<string, ScopeTeamConfig> = {};
  for (const [teamId, rawTeam] of Object.entries(value)) {
    if (teamId.trim().length === 0) {
      throw new Error("teams keys must not be empty");
    }
    if (!isRecord(rawTeam)) {
      throw new Error(`teams.${teamId} must be an object`);
    }
    const projectNamespaceTemplate = rawTeam.projectNamespaceTemplate;
    if (projectNamespaceTemplate !== undefined) {
      if (typeof projectNamespaceTemplate !== "string" || projectNamespaceTemplate.length === 0) {
        throw new Error(`teams.${teamId}.projectNamespaceTemplate must be a non-empty string`);
      }
    }
    teams[teamId] = {
      principals: parseStringList(rawTeam.principals, `teams.${teamId}.principals`),
      ...(projectNamespaceTemplate !== undefined ? { projectNamespaceTemplate } : {}),
      read: parseStringList(rawTeam.read, `teams.${teamId}.read`),
      write: parseStringList(rawTeam.write, `teams.${teamId}.write`),
      promote: parseStringList(rawTeam.promote, `teams.${teamId}.promote`),
    };
  }
  return teams;
}

export function validateScopeProfileTeamReferences(
  profiles: Record<string, ScopeProfileConfig>,
  teams: Record<string, ScopeTeamConfig>
): void {
  for (const [profileId, profile] of Object.entries(profiles)) {
    const teamId = profile.teamProject?.teamId;
    if (teamId && !Object.prototype.hasOwnProperty.call(teams, teamId)) {
      throw new Error(`scopeProfiles.${profileId}.teamProject.teamId references unknown team: ${teamId}`);
    }
  }
}

import { mkdir, unlink, writeFile } from "node:fs/promises";
import path from "node:path";
import { listJsonFilesStrict, readJsonFile, withJsonStoreMutationLock, writeJsonFileAtomic } from "./json-store.js";
import { compareDeterministicStrings, mergeSortedUniqueStrings } from "./deterministic-order.js";
import { isNotFoundError } from "./utils/errno.js";
import {
  assertIsoRecordedAt,
  assertSafePathSegment,
  assertString,
  isRecord,
  optionalStringArray,
  recordStoreDay,
  validateStringRecord,
} from "./store-contract.js";

export type AbstractionNodeKind = "episode" | "topic" | "project" | "workflow" | "constraint";
export type AbstractionLevel = "micro" | "meso" | "macro";

export interface AbstractionNode {
  schemaVersion: 1;
  nodeId: string;
  recordedAt: string;
  sessionKey: string;
  kind: AbstractionNodeKind;
  abstractionLevel: AbstractionLevel;
  title: string;
  summary: string;
  sourceMemoryIds?: string[];
  entityRefs?: string[];
  tags?: string[];
  metadata?: Record<string, string>;
}

export interface AbstractionNodeStoreStatus {
  enabled: boolean;
  anchorsEnabled: boolean;
  rootDir: string;
  nodesDir: string;
  nodes: {
    total: number;
    valid: number;
    invalid: number;
    byKind: Partial<Record<AbstractionNodeKind, number>>;
    byLevel: Partial<Record<AbstractionLevel, number>>;
    latestNodeId?: string;
    latestRecordedAt?: string;
    latestSessionKey?: string;
  };
  latestNode?: AbstractionNode;
  invalidNodes: Array<{
    path: string;
    error: string;
  }>;
}

function validateKind(raw: unknown): AbstractionNodeKind {
  const value = assertString(raw, "kind");
  if (!["episode", "topic", "project", "workflow", "constraint"].includes(value)) {
    throw new Error("kind must be one of episode|topic|project|workflow|constraint");
  }
  return value as AbstractionNodeKind;
}

function validateLevel(raw: unknown): AbstractionLevel {
  const value = assertString(raw, "abstractionLevel");
  if (!["micro", "meso", "macro"].includes(value)) {
    throw new Error("abstractionLevel must be one of micro|meso|macro");
  }
  return value as AbstractionLevel;
}

export function resolveAbstractionNodeStoreDir(memoryDir: string, overrideDir?: string): string {
  if (typeof overrideDir === "string" && overrideDir.trim().length > 0) {
    return overrideDir.trim();
  }
  return path.join(memoryDir, "state", "abstraction-nodes");
}

export function validateAbstractionNode(raw: unknown): AbstractionNode {
  if (!isRecord(raw)) throw new Error("abstraction node must be an object");
  if (raw.schemaVersion !== 1) throw new Error("schemaVersion must be 1");

  return {
    schemaVersion: 1,
    nodeId: assertSafePathSegment(assertString(raw.nodeId, "nodeId"), "nodeId"),
    recordedAt: assertIsoRecordedAt(assertString(raw.recordedAt, "recordedAt")),
    sessionKey: assertString(raw.sessionKey, "sessionKey"),
    kind: validateKind(raw.kind),
    abstractionLevel: validateLevel(raw.abstractionLevel),
    title: assertString(raw.title, "title"),
    summary: assertString(raw.summary, "summary"),
    sourceMemoryIds: optionalStringArray(raw.sourceMemoryIds, "sourceMemoryIds"),
    entityRefs: optionalStringArray(raw.entityRefs, "entityRefs"),
    tags: optionalStringArray(raw.tags, "tags"),
    metadata: validateStringRecord(raw.metadata, "metadata"),
  };
}

export async function recordAbstractionNode(options: {
  memoryDir: string;
  abstractionNodeStoreDir?: string;
  node: AbstractionNode;
}): Promise<string> {
  const rootDir = resolveAbstractionNodeStoreDir(options.memoryDir, options.abstractionNodeStoreDir);
  const validated = validateAbstractionNode(options.node);
  const day = recordStoreDay(validated.recordedAt);
  const nodesDir = path.join(rootDir, "nodes", day);
  const filePath = path.join(nodesDir, `${validated.nodeId}.json`);
  await mkdir(nodesDir, { recursive: true });
  await writeFile(filePath, JSON.stringify(validated, null, 2), "utf8");
  return filePath;
}

const MAX_ABSTRACTION_NODE_VALUES = 50;

function mergeSortedValues(existing: string[] | undefined, incoming: string[] | undefined): string[] {
  return mergeSortedUniqueStrings(existing, incoming).slice(0, MAX_ABSTRACTION_NODE_VALUES);
}

export const HARMONIC_SOURCE_MEMORY_INSERTED_AT_KEY = "remnic.harmonic.sourceMemoryInsertedAt.v1";

function sourceMemoryInsertedAt(node: AbstractionNode | undefined): Map<string, string> {
  const insertedAtById = new Map<string, string>();
  if (!node) return insertedAtById;
  let stored: Record<string, unknown> = {};
  try {
    const parsed = JSON.parse(node.metadata?.[HARMONIC_SOURCE_MEMORY_INSERTED_AT_KEY] ?? "{}") as unknown;
    stored = isRecord(parsed) ? parsed : {};
  } catch {
    stored = {};
  }
  for (const memoryId of node.sourceMemoryIds ?? []) {
    const insertedAt = stored[memoryId];
    insertedAtById.set(
      memoryId,
      typeof insertedAt === "string" && Number.isFinite(Date.parse(insertedAt)) ? insertedAt : node.recordedAt
    );
  }
  return insertedAtById;
}

function mergeRecentSourceMemoryIds(
  existing: AbstractionNode | undefined,
  incoming: AbstractionNode
): { ids: string[]; insertedAtJson: string } {
  const insertedAtById = sourceMemoryInsertedAt(existing);
  const incomingSources = [...sourceMemoryInsertedAt(incoming).entries()].sort(
    ([leftId, leftAt], [rightId, rightAt]) =>
      Date.parse(leftAt) - Date.parse(rightAt) || compareDeterministicStrings(leftId, rightId)
  );
  let nextInsertedAtMs = Math.max(
    Date.now(),
    [...insertedAtById.values()].reduce((latest, insertedAt) => Math.max(latest, Date.parse(insertedAt) + 1), 0)
  );
  for (const [memoryId] of incomingSources) {
    if (insertedAtById.has(memoryId)) continue;
    insertedAtById.set(memoryId, new Date(nextInsertedAtMs).toISOString());
    nextInsertedAtMs++;
  }
  const retained = [...insertedAtById.entries()]
    .sort(
      ([leftId, leftAt], [rightId, rightAt]) =>
        Date.parse(rightAt) - Date.parse(leftAt) || compareDeterministicStrings(leftId, rightId)
    )
    .slice(0, MAX_ABSTRACTION_NODE_VALUES);
  const ids = retained.map(([memoryId]) => memoryId).sort(compareDeterministicStrings);
  const retainedInsertedAt = Object.fromEntries(ids.map((memoryId) => [memoryId, insertedAtById.get(memoryId)]));
  return { ids, insertedAtJson: JSON.stringify(retainedInsertedAt) };
}

type AbstractionNodeFile = {
  filePath: string;
  node: AbstractionNode;
};

function compareNodeFiles(left: AbstractionNodeFile, right: AbstractionNodeFile): number {
  return (
    Date.parse(right.node.recordedAt) - Date.parse(left.node.recordedAt) ||
    compareDeterministicStrings(left.filePath, right.filePath)
  );
}

function compareIncomingNodes(left: AbstractionNode, right: AbstractionNode): number {
  return (
    Date.parse(left.recordedAt) - Date.parse(right.recordedAt) ||
    compareDeterministicStrings(canonicalNodeKey(left), canonicalNodeKey(right))
  );
}

function canonicalMetadata(metadata: Record<string, string> | undefined): Record<string, string> {
  return Object.fromEntries(
    Object.entries(metadata ?? {}).sort(([left], [right]) => compareDeterministicStrings(left, right))
  );
}

function canonicalNodeKey(node: AbstractionNode): string {
  return JSON.stringify({
    ...node,
    metadata: canonicalMetadata(node.metadata),
  });
}

function mergeAbstractionNodes(existing: AbstractionNode | undefined, incoming: AbstractionNode): AbstractionNode {
  const incomingIsNewest = !existing || Date.parse(existing.recordedAt) <= Date.parse(incoming.recordedAt);
  const newest = incomingIsNewest ? incoming : existing;
  const older = incomingIsNewest ? existing : incoming;
  if (!newest) throw new Error("abstraction node merge requires a node");
  const retainedSources = mergeRecentSourceMemoryIds(existing, incoming);
  const mergedMetadata = canonicalMetadata({
    ...(older?.metadata ?? {}),
    ...(newest.metadata ?? {}),
    [HARMONIC_SOURCE_MEMORY_INSERTED_AT_KEY]: retainedSources.insertedAtJson,
  });
  return validateAbstractionNode({
    ...newest,
    sourceMemoryIds: retainedSources.ids,
    entityRefs: mergeSortedValues(existing?.entityRefs, incoming.entityRefs),
    tags: mergeSortedValues(existing?.tags, incoming.tags),
    metadata: mergedMetadata,
  });
}

export async function upsertAbstractionNodes(options: {
  memoryDir: string;
  abstractionNodeStoreDir?: string;
  nodes: AbstractionNode[];
}): Promise<string[]> {
  const rootDir = resolveAbstractionNodeStoreDir(options.memoryDir, options.abstractionNodeStoreDir);
  const incomingNodes = options.nodes.map(validateAbstractionNode);
  if (incomingNodes.length === 0) return [];
  return withJsonStoreMutationLock(rootDir, async () => {
    const nodesDir = path.join(rootDir, "nodes");
    const nodeFiles = await listJsonFilesStrict(nodesDir, { allowMissingDirectory: true });
    const existingNodes = await Promise.all(
      nodeFiles.map(async (filePath) => ({
        filePath,
        node: validateAbstractionNode(await readJsonFile(filePath)),
      }))
    );
    const existingById = new Map<string, AbstractionNodeFile[]>();
    for (const existing of existingNodes) {
      const records = existingById.get(existing.node.nodeId) ?? [];
      records.push(existing);
      existingById.set(existing.node.nodeId, records);
    }
    const incomingById = new Map<string, AbstractionNode[]>();
    for (const incoming of incomingNodes) {
      const records = incomingById.get(incoming.nodeId) ?? [];
      records.push(incoming);
      incomingById.set(incoming.nodeId, records);
    }

    const filePaths: string[] = [];
    for (const nodeId of [...incomingById.keys()].sort(compareDeterministicStrings)) {
      const existing = (existingById.get(nodeId) ?? []).sort(compareNodeFiles);
      const incoming = (incomingById.get(nodeId) ?? []).sort(compareIncomingNodes);
      let merged: AbstractionNode | undefined;
      for (const next of [...existing].reverse()) merged = mergeAbstractionNodes(merged, next.node);
      for (const next of incoming) merged = mergeAbstractionNodes(merged, next);
      if (!merged) throw new Error(`abstraction node batch has no node: ${nodeId}`);
      const filePath =
        existing[0]?.filePath ?? path.join(nodesDir, recordStoreDay(merged.recordedAt), `${merged.nodeId}.json`);
      await writeJsonFileAtomic(filePath, merged);
      for (const duplicate of existing.slice(1)) {
        await unlink(duplicate.filePath).catch((error) => {
          if (!isNotFoundError(error)) throw error;
        });
      }
      filePaths.push(filePath);
    }
    return filePaths;
  });
}

export async function upsertAbstractionNode(options: {
  memoryDir: string;
  abstractionNodeStoreDir?: string;
  node: AbstractionNode;
}): Promise<string> {
  const [filePath] = await upsertAbstractionNodes({ ...options, nodes: [options.node] });
  if (!filePath) throw new Error("abstraction node upsert did not write a file");
  return filePath;
}

export async function getAbstractionNodeStoreStatus(options: {
  memoryDir: string;
  abstractionNodeStoreDir?: string;
  enabled: boolean;
  anchorsEnabled: boolean;
}): Promise<AbstractionNodeStoreStatus> {
  const rootDir = resolveAbstractionNodeStoreDir(options.memoryDir, options.abstractionNodeStoreDir);
  const nodesDir = path.join(rootDir, "nodes");
  const files = await listJsonFilesStrict(nodesDir, { allowMissingDirectory: true });
  const nodes: AbstractionNode[] = [];
  const invalidNodes: Array<{ path: string; error: string }> = [];

  for (const filePath of files) {
    try {
      nodes.push(validateAbstractionNode(await readJsonFile(filePath)));
    } catch (error) {
      invalidNodes.push({
        path: filePath,
        error: error instanceof Error ? error.message : String(error),
      });
    }
  }

  nodes.sort(
    (a, b) => Date.parse(b.recordedAt) - Date.parse(a.recordedAt) || compareDeterministicStrings(a.nodeId, b.nodeId)
  );

  const byKind: Partial<Record<AbstractionNodeKind, number>> = {};
  const byLevel: Partial<Record<AbstractionLevel, number>> = {};
  for (const node of nodes) {
    byKind[node.kind] = (byKind[node.kind] ?? 0) + 1;
    byLevel[node.abstractionLevel] = (byLevel[node.abstractionLevel] ?? 0) + 1;
  }

  return {
    enabled: options.enabled,
    anchorsEnabled: options.anchorsEnabled,
    rootDir,
    nodesDir,
    nodes: {
      total: files.length,
      valid: nodes.length,
      invalid: invalidNodes.length,
      byKind,
      byLevel,
      latestNodeId: nodes[0]?.nodeId,
      latestRecordedAt: nodes[0]?.recordedAt,
      latestSessionKey: nodes[0]?.sessionKey,
    },
    latestNode: nodes[0],
    invalidNodes,
  };
}

/** Wait without cancellation; keep the timer referenced so awaited polling can finish. */
export function sleep(ms: number): Promise<void> {
  // Constructor form keeps this reachable utility compatible with ES2022 adapter type graphs.
  return new Promise((resolve) => setTimeout(resolve, ms));
}

import { abortError } from "../abort-error.js";

/**
 * Wait until `ms` elapses, or reject with `AbortError` when `signal` fires.
 * The timer is cleared on abort so a cancelled wait holds no Timeout handle.
 * Executor form: this module targets ES2022 type graphs (no withResolvers).
 */
export function sleepAbortable(ms: number, signal?: AbortSignal): Promise<void> {
  return new Promise((resolve, reject) => {
    if (signal?.aborted) {
      reject(abortError("operation aborted"));
      return;
    }
    const timer = setTimeout(() => {
      if (signal && onAbort) signal.removeEventListener("abort", onAbort);
      resolve();
    }, ms);
    let onAbort: (() => void) | null = null;
    if (signal) {
      onAbort = () => {
        clearTimeout(timer);
        reject(abortError("operation aborted"));
      };
      signal.addEventListener("abort", onAbort, { once: true });
    }
  });
}

import { isAbortError, raceAbort } from "./abort-error.js";

export const BRIEFING_DEADLINE_MS = 30_000;

export class BriefingTimeoutError extends Error {
  constructor(readonly deadlineMs: number) {
    super(`briefing timed out after ${deadlineMs}ms`);
    this.name = "TimeoutError";
  }
}

export async function withBriefingDeadline<T>(
  run: (signal: AbortSignal) => Promise<T>,
  abortSignal?: AbortSignal
): Promise<T> {
  const controller = new AbortController();
  const signal = abortSignal ? AbortSignal.any([abortSignal, controller.signal]) : controller.signal;
  const timer = setTimeout(
    () => controller.abort(new BriefingTimeoutError(BRIEFING_DEADLINE_MS)),
    BRIEFING_DEADLINE_MS
  );
  try {
    signal.throwIfAborted();
    return await raceAbort(run(signal), signal, "briefing aborted");
  } catch (err) {
    // raceAbort normalizes cancellation; retain the distinct deadline reason.
    const reason: unknown = signal.reason;
    if (signal.aborted && (reason instanceof BriefingTimeoutError || isAbortError(reason))) throw reason;
    throw err;
  } finally {
    clearTimeout(timer);
  }
}

export const BRIEFING_FOLLOWUP_TIMEOUT_MS = 8_000;

export async function withBriefingFollowupTimeout<T>(
  work: Promise<T>,
  timeoutMs = BRIEFING_FOLLOWUP_TIMEOUT_MS,
): Promise<T> {
  const { promise: timeout, reject } = Promise.withResolvers<T>();
  const timer = setTimeout(() => reject(new Error("briefing follow-up timeout")), timeoutMs);
  try {
    return await Promise.race([work, timeout]);
  } finally {
    clearTimeout(timer);
  }
}

/**
 * Utilities for extracting JSON payloads from LLM outputs.
 *
 * We see common failure modes:
 * - "Here's an example: {..}\nHere's the real answer: {..}" (multiple JSON blocks)
 * - fenced ```json blocks
 * - leading/trailing prose around JSON
 *
 * These helpers attempt multiple candidates and let callers validate with schemas.
 */

export function stripCodeFences(text: string): string {
  // Drop the leading \s* before the lazy body: it overlapped the body and caused
  // polynomial backtracking on unterminated fences (CodeQL js/polynomial-redos).
  // inner is trimmed, so captured content is identical.
  return text.replace(/```(?:json)?([\s\S]*?)```/gi, (_m, inner) => String(inner).trim());
}

export function extractJsonCandidates(text: string): string[] {
  const trimmed = text.trim();
  const cleaned = stripCodeFences(trimmed);
  const candidates: string[] = [];

  // Verbatim balanced blocks FIRST: stripCodeFences rewrites every ``` pair, so
  // a stripped candidate can parse while carrying altered content (e.g. a
  // patch value that embeds an inner code block). A string-aware balanced scan
  // of the unstripped text yields the payload unmodified; stripped candidates
  // remain as later fallbacks for shapes the raw scan cannot cut.
  candidates.push(...scanBalancedJsonBlocks(trimmed));
  if (cleaned.length > 0) candidates.push(cleaned);
  candidates.push(...scanBalancedJsonBlocks(cleaned));

  // Legacy regex fallback (single object)
  const objMatch = cleaned.match(/\{[\s\S]*\}/);
  if (objMatch) candidates.push(objMatch[0]);

  const seen = new Set<string>();
  return candidates
    .map((c) => c.trim())
    .filter((c) => c.length > 0)
    .filter((c) => {
      if (seen.has(c)) return false;
      seen.add(c);
      return true;
    });
}

function scanBalancedJsonBlocks(text: string): string[] {
  const out: string[] = [];
  const opens = new Set(["{", "["]);
  const closes: Record<string, string> = { "{": "}", "[": "]" };

  for (let i = 0; i < text.length; i++) {
    const start = text[i];
    if (!opens.has(start)) continue;

    const expectedClose = closes[start];
    let depth = 0;
    let inString = false;
    let escape = false;

    for (let j = i; j < text.length; j++) {
      const ch = text[j];

      if (inString) {
        if (escape) {
          escape = false;
        } else if (ch === "\\") {
          escape = true;
        } else if (ch === "\"") {
          inString = false;
        }
        continue;
      }

      if (ch === "\"") {
        inString = true;
        continue;
      }

      if (ch === start) depth++;
      if (ch === expectedClose) depth--;

      if (depth === 0) {
        out.push(text.slice(i, j + 1).trim());
        i = j;
        break;
      }
    }
  }

  return out;
}

/**
 * correction/passive-correction-notifications.ts — JSONL notification queue
 * for auto-applied passive corrections (issue #1581).
 *
 * When passive capture auto-applies a correction, it enqueues a one-line
 * notification here: `✎ Memory updated: <summary> (auto-applied (plan <planId>))`.
 * The plan id is referenced (not a revert command) because `remnic correct`
 * has no `--revert` flag — corrections are page-versioned for manual revert.
 * The next session-start briefing drains the queue ONCE (temp-file-then-rename,
 * rule 54) and clears it, so a notification is shown exactly once.
 *
 * File location: `<storageDir>/state/corrections/notifications.jsonl`
 */

import { mkdir, readFile, rename, writeFile, unlink } from "node:fs/promises";
import path from "node:path";
import { throwIfAborted } from "../abort-error.js";
import { serializeMutations } from "../utils/serialize-mutations.js";

// ---------------------------------------------------------------------------
// Types
// ---------------------------------------------------------------------------

export interface PassiveCorrectionNotification {
  planId: string;
  /** One-line human-readable summary of what changed. */
  summary: string;
  /** Undo command the user can run. */
  undoCommand: string;
  createdAt: string;
}

// ---------------------------------------------------------------------------
// Path
// ---------------------------------------------------------------------------

function notificationsPath(storageDir: string): string {
  return path.join(storageDir, "state", "corrections", "notifications.jsonl");
}

// ---------------------------------------------------------------------------
// Enqueue
// ---------------------------------------------------------------------------

/**
 * Append a notification line to the JSONL queue. Atomic (rule 54): the line
 * is written to a temp file then renamed over the real file. Multiple
 * notifications accumulate across calls — the queue is drained, not replaced.
 */
export async function enqueuePassiveCorrectionNotification(
  storageDir: string,
  notification: PassiveCorrectionNotification,
): Promise<void> {
  const filePath = notificationsPath(storageDir);
  await serializeMutations(`passive-notification:${filePath}`, async () => {
    // Read existing content (if any) so we accumulate rather than overwrite.
    let existing = "";
    try {
      existing = await readFile(filePath, "utf-8");
    } catch (err) {
      const code = (err as NodeJS.ErrnoException)?.code;
      if (code !== "ENOENT") throw err;
    }

    await mkdir(path.dirname(filePath), { recursive: true });
    const line = `${JSON.stringify(notification)}\n`;
    const content = existing + line;

    const tmp = `${filePath}.${process.pid}.${Date.now().toString(36)}.tmp`;
    await writeFile(tmp, content, "utf-8");
    await rename(tmp, filePath);
  });
}

// ---------------------------------------------------------------------------
// Drain (read + clear — exactly once)
// ---------------------------------------------------------------------------

/**
 * Read all pending notifications and atomically clear the file. Returns the
 * notifications in insertion order. If the file does not exist, returns [].
 *
 * Drain-once semantics: the file is deleted after reading, so calling this
 * twice in a row returns notifications only the first time.
 */
export async function drainPassiveCorrectionNotifications(
  storageDir: string,
  signal?: AbortSignal,
): Promise<PassiveCorrectionNotification[]> {
  const filePath = notificationsPath(storageDir);
  return serializeMutations(`passive-notification:${filePath}`, async () => {
    let raw: string;
    try {
      raw = await readFile(filePath, "utf-8");
    } catch (err) {
      const code = (err as NodeJS.ErrnoException)?.code;
      if (code === "ENOENT") return [];
      throw err;
    }

    // Cancellation after the read must keep the queue: the caller never receives these.
    throwIfAborted(signal, "briefing aborted");
    const notifications: PassiveCorrectionNotification[] = [];
    for (const line of raw.split("\n")) {
      const trimmed = line.trim();
      if (!trimmed) continue;
      try {
        notifications.push(JSON.parse(trimmed) as PassiveCorrectionNotification);
      } catch {
        // Skip malformed lines (rule 34 — best-effort, never crash a briefing).
        continue;
      }
    }

    // Clear the file atomically (delete is atomic enough for this use case —
    // the worst case is a duplicate notification, never a lost one, because
    // the read already captured the content).
    try {
      await unlink(filePath);
    } catch (err) {
      const code = (err as NodeJS.ErrnoException)?.code;
      if (code !== "ENOENT") throw err;
    }

    return notifications;
  });
}

import { createHash } from "node:crypto";
import { lstat } from "node:fs/promises";

import type { OfflineSyncExcludeFile } from "../offline-sync-file-io.js";
import { stripAttributesSuffix } from "../structured-attributes.js";
import type { MemoryFile } from "../types.js";
import {
  type SupportPassportCard,
  SupportPassportCardCategorySchema,
  SupportPassportCardSchema,
  SupportPassportCardStatusSchema,
  SupportPassportMemoryIdSchema,
  SupportPassportNamespaceSchema,
  SupportPassportSourceMemoryIdSchema,
  computeSupportPassportCardRevision,
} from "./contracts.js";

export const SUPPORT_PASSPORT_CARD_TAG = "support-passport-card";
export const SUPPORT_PASSPORT_AUDIT_TAG = "support-passport-audit";

export function isSupportPassportPrivateMemory(memory: {
  frontmatter: {
    tags?: readonly string[];
    structuredAttributes?: Readonly<Record<string, string>>;
  };
}): boolean {
  const tags = memory.frontmatter.tags;
  if (tags?.includes(SUPPORT_PASSPORT_CARD_TAG) === true || tags?.includes(SUPPORT_PASSPORT_AUDIT_TAG) === true) {
    return true;
  }
  return Object.keys(memory.frontmatter.structuredAttributes ?? {}).some((key) => key.startsWith("support-passport-"));
}

export function excludeSupportPassportPrivateMemories<T extends Pick<MemoryFile, "frontmatter">>(
  memories: readonly T[]
): T[] {
  return memories.filter((memory) => !isSupportPassportPrivateMemory(memory));
}

/**
 * Stat identity a persisted exclusion classification is keyed on. Any content
 * change rewrites the file, which moves ctime, so a matching identity implies
 * the same bytes and therefore the same classification.
 */
export function supportPassportStatIdentity(file: {
  dev: number;
  ino: number;
  size: number;
  mtimeMs: number;
  ctimeMs: number;
}): string {
  return `${file.dev}:${file.ino}:${file.size}:${file.mtimeMs}:${file.ctimeMs}`;
}

export interface PersistedSupportPassportClassification {
  statIdentity: string;
  excluded: boolean;
}

/**
 * `createSupportPassportPrivateFileExclusion` variant that consults a
 * PERSISTED classification before touching the file. The plain factory
 * classifies by reading and parsing every candidate (readMemoryByPath), which
 * is fine once per process but defeats any persisted-parse optimization: a
 * warm reconcile plan that should skip per-file reads would still read every
 * file just to decide exclusion. When the persisted stat identity matches, the
 * classification is reused and the file is not opened; on mismatch it is
 * recomputed once and recorded into `updates` so the caller can persist it.
 */
export function createPersistedSupportPassportPrivateFileExclusion(
  storage: {
    readMemoryByPath(filePath: string): Promise<MemoryFile | null>;
  },
  persisted: ReadonlyMap<string, { statIdentity?: string; excluded?: boolean }>,
  updates: Map<string, PersistedSupportPassportClassification>
): OfflineSyncExcludeFile {
  const inFlight = new Map<string, { identity: string; excluded: Promise<boolean> }>();
  return async ({ filePath, path: relPath }) => {
    let file: Awaited<ReturnType<typeof lstat>>;
    try {
      file = await lstat(filePath);
    } catch (error) {
      if ((error as NodeJS.ErrnoException).code === "ENOENT") {
        inFlight.delete(filePath);
        return false;
      }
      throw error;
    }
    const identity = supportPassportStatIdentity(file);
    const known = persisted.get(relPath);
    if (known?.statIdentity === identity && known.excluded !== undefined) {
      updates.set(relPath, { statIdentity: identity, excluded: known.excluded });
      return known.excluded;
    }
    const cached = inFlight.get(filePath);
    if (cached?.identity === identity) return await cached.excluded;
    const excluded = storage
      .readMemoryByPath(filePath)
      .then((memory) => (memory ? isSupportPassportPrivateMemory(memory) : false))
      .finally(() => {
        if (inFlight.get(filePath)?.identity === identity) inFlight.delete(filePath);
      });
    inFlight.set(filePath, { identity, excluded });
    const result = await excluded;
    updates.set(relPath, { statIdentity: identity, excluded: result });
    return result;
  };
}

export function createSupportPassportPrivateFileExclusion(storage: {
  readMemoryByPath(filePath: string): Promise<MemoryFile | null>;
}): OfflineSyncExcludeFile {
  const classifications = new Map<string, { identity: string; excluded: Promise<boolean> }>();
  return async ({ filePath }) => {
    let file: Awaited<ReturnType<typeof lstat>>;
    try {
      file = await lstat(filePath);
    } catch (error) {
      if ((error as NodeJS.ErrnoException).code === "ENOENT") {
        classifications.delete(filePath);
        return false;
      }
      throw error;
    }
    const identity = `${file.dev}:${file.ino}:${file.size}:${file.mtimeMs}:${file.ctimeMs}`;
    const cached = classifications.get(filePath);
    if (cached?.identity === identity) return await cached.excluded;
    const excluded = storage
      .readMemoryByPath(filePath)
      .then((memory) => (memory ? isSupportPassportPrivateMemory(memory) : false));
    classifications.set(filePath, { identity, excluded });
    try {
      return await excluded;
    } catch (error) {
      if (classifications.get(filePath)?.excluded === excluded) classifications.delete(filePath);
      throw error;
    }
  };
}

export const SUPPORT_PASSPORT_ATTRIBUTE_KEYS = Object.freeze({
  namespace: "support-passport-namespace",
  namespaceEncoding: "support-passport-namespace-encoding",
  owner: "support-passport-owner",
  title: "support-passport-title",
  category: "support-passport-category",
  order: "support-passport-order",
  reviewBy: "support-passport-review-by",
  sourceMemoryIds: "support-passport-source-ids",
  replacesDraftId: "support-passport-replaces-draft-id",
  replacedRevision: "support-passport-replaced-revision",
  draftReplacementPrepared: "support-passport-draft-replacement-prepared",
  replacementComplete: "support-passport-replacement-complete",
  generatedBatchId: "support-passport-generated-batch-id",
  generatedBatchSize: "support-passport-generated-batch-size",
});

const SUPPORT_PASSPORT_NAMESPACE_ENCODING = "base64url-v1";
const SUPPORT_PASSPORT_NAMESPACE_CHUNK_PREFIX = "support-passport-namespace-";
const SUPPORT_PASSPORT_NAMESPACE_CHUNK_SIZE = 1_024;
const LegacySupportPassportNamespaceSchema = SupportPassportNamespaceSchema.refine(
  (namespace) =>
    !namespace.includes("/") &&
    !namespace.includes("\\") &&
    !namespace.includes("..") &&
    !namespace.includes("]") &&
    !namespace.includes("\0") &&
    !namespace.includes("\n") &&
    !namespace.includes("\r")
);

export function encodeSupportPassportNamespaceAttributes(namespace: string): Record<string, string> {
  const canonical = SupportPassportNamespaceSchema.parse(namespace);
  const encoded = Buffer.from(canonical, "utf8").toString("base64url");
  const chunks = encoded.match(new RegExp(`.{1,${SUPPORT_PASSPORT_NAMESPACE_CHUNK_SIZE}}`, "g")) ?? [];
  const digest = createHash("sha256").update(encoded).digest("hex");
  return Object.fromEntries([
    [SUPPORT_PASSPORT_ATTRIBUTE_KEYS.namespace, chunks[0] ?? ""],
    [
      SUPPORT_PASSPORT_ATTRIBUTE_KEYS.namespaceEncoding,
      `${SUPPORT_PASSPORT_NAMESPACE_ENCODING}:${chunks.length}:${digest}`,
    ],
    ...chunks.slice(1).map((chunk, index) => [`${SUPPORT_PASSPORT_NAMESPACE_CHUNK_PREFIX}${index + 1}`, chunk]),
  ]);
}

export function decodeSupportPassportNamespaceAttributes(attributes: Readonly<Record<string, string>>): string | null {
  const firstChunk = attributes[SUPPORT_PASSPORT_ATTRIBUTE_KEYS.namespace];
  const encoding = attributes[SUPPORT_PASSPORT_ATTRIBUTE_KEYS.namespaceEncoding];
  if (encoding === undefined) {
    const legacy = LegacySupportPassportNamespaceSchema.safeParse(firstChunk);
    return legacy.success ? legacy.data : null;
  }
  const match = /^base64url-v1:([1-9]\d*):([a-f0-9]{64})$/.exec(encoding);
  if (!match || typeof firstChunk !== "string") return null;
  const chunkCount = Number(match[1]);
  if (!Number.isSafeInteger(chunkCount)) return null;
  const chunkIndexes = Object.keys(attributes).flatMap((key) => {
    const chunkMatch = /^support-passport-namespace-(\d+)$/.exec(key);
    return chunkMatch ? [Number(chunkMatch[1])] : [];
  });
  if (
    chunkIndexes.length !== chunkCount - 1 ||
    chunkIndexes.some((index) => !Number.isSafeInteger(index) || index < 1 || index >= chunkCount)
  )
    return null;
  const chunks = [firstChunk];
  for (let index = 1; index < chunkCount; index += 1) {
    const chunk = attributes[`${SUPPORT_PASSPORT_NAMESPACE_CHUNK_PREFIX}${index}`];
    if (typeof chunk !== "string" || chunk.length === 0) return null;
    chunks.push(chunk);
  }
  const encoded = chunks.join("");
  if (createHash("sha256").update(encoded).digest("hex") !== match[2]) return null;
  const decoded = Buffer.from(encoded, "base64url").toString("utf8");
  if (Buffer.from(decoded, "utf8").toString("base64url") !== encoded) return null;
  const namespace = SupportPassportNamespaceSchema.safeParse(decoded);
  return namespace.success ? namespace.data : null;
}

export interface StoredSupportPassportCard {
  card: SupportPassportCard;
  memory: MemoryFile;
  order: number;
  sourceMemoryIds: string[];
  namespace: string;
  owner: string;
  replacesDraftId?: string;
  replacedRevision?: string;
  draftReplacementPrepared: boolean;
  generatedBatchId?: string;
  generatedBatchSize?: number;
}

export function computeSupportPassportOwnerKey(principal: string): string {
  return createHash("sha256").update(principal).digest("hex");
}

export function activeSupportPassportReplacementPredecessorIds(
  cards: readonly StoredSupportPassportCard[]
): Set<string> {
  return new Set(
    cards
      .filter((item) => item.card.status === "active")
      .map((item) => item.memory.frontmatter.supersedes)
      .filter((cardId): cardId is string => typeof cardId === "string")
  );
}

function parseSourceMemoryIds(frontmatter: MemoryFile["frontmatter"]): string[] | null {
  const lineage = frontmatter.lineage;
  const legacyValue = frontmatter.structuredAttributes?.[SUPPORT_PASSPORT_ATTRIBUTE_KEYS.sourceMemoryIds];
  const rawIds = lineage ?? (legacyValue === undefined || legacyValue === "" ? [] : legacyValue.split(","));
  if (rawIds.length > 5) return null;
  const normalized: string[] = [];
  for (const rawId of rawIds) {
    const parsed = SupportPassportSourceMemoryIdSchema.safeParse(rawId);
    if (!parsed.success) return null;
    normalized.push(parsed.data);
  }
  if (new Set(normalized).size !== normalized.length) return null;
  return normalized;
}

interface SupportPassportCardMetadata {
  fields: Omit<SupportPassportCard, "revision" | "statement">;
  order: number;
  sourceMemoryIds: string[];
  namespace: string;
  owner: string;
  replacesDraftId?: string;
  replacedRevision?: string;
  draftReplacementPrepared: boolean;
  generatedBatchId?: string;
  generatedBatchSize?: number;
}

function parseSupportPassportCardMetadata(memory: Pick<MemoryFile, "frontmatter">): SupportPassportCardMetadata | null {
  const frontmatter = memory.frontmatter;
  const attributes = frontmatter.structuredAttributes;
  if (frontmatter.category !== "preference") return null;
  if (!frontmatter.tags?.includes(SUPPORT_PASSPORT_CARD_TAG)) return null;
  if (!attributes || frontmatter.blockedBy || frontmatter.archivedAt || frontmatter.supersededBy) return null;

  const category = SupportPassportCardCategorySchema.safeParse(attributes[SUPPORT_PASSPORT_ATTRIBUTE_KEYS.category]);
  const status = SupportPassportCardStatusSchema.safeParse(frontmatter.status);
  const rawOrder = attributes[SUPPORT_PASSPORT_ATTRIBUTE_KEYS.order];
  const order = Number(rawOrder);
  const sourceMemoryIds = parseSourceMemoryIds(frontmatter);
  const namespace = decodeSupportPassportNamespaceAttributes(attributes);
  const owner = attributes[SUPPORT_PASSPORT_ATTRIBUTE_KEYS.owner];
  let replacesDraftId: string | undefined;
  const rawReplacesDraftId = attributes[SUPPORT_PASSPORT_ATTRIBUTE_KEYS.replacesDraftId];
  if (rawReplacesDraftId !== undefined) {
    const parsedReplacesDraftId = SupportPassportMemoryIdSchema.safeParse(rawReplacesDraftId);
    if (!parsedReplacesDraftId.success) return null;
    replacesDraftId = parsedReplacesDraftId.data;
  }
  let replacedRevision: string | undefined;
  const rawReplacedRevision = attributes[SUPPORT_PASSPORT_ATTRIBUTE_KEYS.replacedRevision];
  if (rawReplacedRevision !== undefined) {
    if (!/^[a-f0-9]{64}$/.test(rawReplacedRevision)) return null;
    replacedRevision = rawReplacedRevision;
  }
  const generatedBatchId = attributes[SUPPORT_PASSPORT_ATTRIBUTE_KEYS.generatedBatchId];
  const rawGeneratedBatchSize = attributes[SUPPORT_PASSPORT_ATTRIBUTE_KEYS.generatedBatchSize];
  let generatedBatchSize: number | undefined;
  if (generatedBatchId !== undefined) {
    if (!/^[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/.test(generatedBatchId)) {
      return null;
    }
    if (typeof rawGeneratedBatchSize !== "string" || !/^[1-8]$/.test(rawGeneratedBatchSize)) {
      return null;
    }
    generatedBatchSize = Number(rawGeneratedBatchSize);
  } else if (rawGeneratedBatchSize !== undefined) {
    return null;
  }
  if (
    !category.success ||
    !status.success ||
    status.data === "superseded" ||
    typeof rawOrder !== "string" ||
    !/^(?:0|[1-9]\d*)$/.test(rawOrder) ||
    !Number.isSafeInteger(order) ||
    namespace === null ||
    typeof owner !== "string" ||
    !/^[a-f0-9]{64}$/.test(owner) ||
    !sourceMemoryIds
  )
    return null;
  const fields = SupportPassportCardSchema.omit({
    revision: true,
    statement: true,
  }).safeParse({
    cardId: frontmatter.id,
    title: attributes[SUPPORT_PASSPORT_ATTRIBUTE_KEYS.title],
    category: category.data,
    status: status.data,
    updatedAt: frontmatter.updated,
    reviewBy: attributes[SUPPORT_PASSPORT_ATTRIBUTE_KEYS.reviewBy],
  });
  if (!fields.success) return null;
  return {
    fields: fields.data,
    order,
    sourceMemoryIds,
    namespace,
    owner,
    replacesDraftId,
    replacedRevision,
    draftReplacementPrepared: attributes[SUPPORT_PASSPORT_ATTRIBUTE_KEYS.draftReplacementPrepared] === "true",
    generatedBatchId,
    generatedBatchSize,
  };
}

export function hasLiveSupportPassportCard(memory: Pick<MemoryFile, "frontmatter" | "content">): boolean {
  const metadata = parseSupportPassportCardMetadata(memory);
  if (metadata?.fields.status !== "active" && metadata?.fields.status !== "pending_review") return false;
  if (metadata.sourceMemoryIds.length === 0) return false;
  return SupportPassportCardSchema.omit({ revision: true }).safeParse({
    ...metadata.fields,
    statement: stripAttributesSuffix(memory.content),
  }).success;
}

export function projectSupportPassportCard(memory: MemoryFile): StoredSupportPassportCard | null {
  const metadata = parseSupportPassportCardMetadata(memory);
  if (!metadata) return null;

  const fields = {
    ...metadata.fields,
    statement: stripAttributesSuffix(memory.content),
  };
  const normalized = SupportPassportCardSchema.omit({
    revision: true,
  }).safeParse(fields);
  if (!normalized.success) return null;
  const parsed = SupportPassportCardSchema.safeParse({
    ...normalized.data,
    revision: computeSupportPassportCardRevision(normalized.data),
  });
  if (!parsed.success) return null;
  return {
    card: parsed.data,
    memory,
    order: metadata.order,
    sourceMemoryIds: metadata.sourceMemoryIds,
    namespace: metadata.namespace,
    owner: metadata.owner,
    replacesDraftId: metadata.replacesDraftId,
    replacedRevision: metadata.replacedRevision,
    draftReplacementPrepared: metadata.draftReplacementPrepared,
    generatedBatchId: metadata.generatedBatchId,
    generatedBatchSize: metadata.generatedBatchSize,
  };
}

import { log } from "./logger.js";
import type { EntityFile, MemoryFile } from "./types.js";
import { isAbortError } from "./abort-error.js";
import type { CorpusReadOptions } from "./corpus-read-cancellation.js";
import type { ParsedBriefingWindow } from "./briefing.js";
import type { WindowedMemoryReadOptions } from "./storage/windowed-memory-read.js";

type BriefingMemoryReader = {
  readMemoriesWindow?: (options: WindowedMemoryReadOptions) => Promise<{ memories: MemoryFile[] }>;
  readAllMemories: ((options?: CorpusReadOptions) => Promise<MemoryFile[]>) & {
    supportsAbortSignal?: boolean;
  };
  supportsAbortSignal?: boolean;
  supportsCancellation?: boolean;
  cancellable?: boolean;
};

/**
 * Deadline for the legacy full-read fallback (issue #2779). Storage doubles
 * that predate `readMemoriesWindow()` can only answer with a full-corpus
 * `readAllMemories()`, which is unbounded work; on a large corpus that read
 * alone can outlast the 60s MCP client timeout. Arm an AbortController with
 * this budget (well under 60s, leaving room for entity reads and follow-ups)
 * and fail open with an empty read. The deadline reaches the read as an
 * abort signal (the #2307 corpus-read contract), so the scan stops at its
 * next boundary instead of being abandoned to run on in the background.
 */
export const BRIEFING_FULL_READ_FALLBACK_MS = 30_000;

/** Options for {@link safeReadMemories}. */
export interface SafeReadMemoriesOptions {
  /** Test seam overriding {@link BRIEFING_FULL_READ_FALLBACK_MS}. */
  fallbackDeadlineMs?: number;
  /**
   * Caller cancellation. The signal reaches the storage read so it stops at
   * its next boundary, and a cancelled read is rethrown rather than degraded
   * into an empty corpus (issue #3139).
   */
  signal?: AbortSignal;
}

type BriefingReadMode = "windowed" | "full-read-fallback";
type BriefingReadOutcome = "success" | "timeout" | "error";

/** Internal marker: the fallback deadline fired and the read was aborted. */
class BriefingReadTimedOut extends Error {
  constructor(readonly deadlineMs: number) {
    super("briefing full-read fallback timed out");
    this.name = "BriefingReadTimedOut";
  }
}

/** Internal marker: the adapter's readAllMemories predates the signal contract. */
class LegacyReadUnsupported extends Error {
  constructor() {
    super("readAllMemories does not accept an abort signal");
    this.name = "LegacyReadUnsupported";
  }
}

const SAFE_ERROR_CLASSES: Record<string, true> = {
  Error: true,
  TypeError: true,
  RangeError: true,
  ReferenceError: true,
  SyntaxError: true,
  URIError: true,
  EvalError: true,
  AggregateError: true,
  AbortError: true,
  TimeoutError: true,
  SystemError: true,
  BriefingReadTimedOut: true,
  LegacyReadUnsupported: true,
  StorageError: true,
  EngramAccessInputError: true,
};

/**
 * Sanitize adapter-controlled Error.name before structured discriminator logs
 * (issue #2827). Allow-lists known system/remnic error names and maps any
 * unrecognized or backend-controlled names to a safe bounded class ("CustomError").
 */
function errorClass(err: unknown): string {
  if (err instanceof Error) {
    const name = err.name;
    if (typeof name === "string" && SAFE_ERROR_CLASSES[name] === true) {
      return name;
    }
    return "CustomError";
  }
  return typeof err === "string"
    ? "string"
    : typeof err === "object" && err !== null
      ? "object"
      : typeof err;
}

function bestEffortLog(level: "info" | "warn", message: string): void {
  try {
    log[level](message);
  } catch {
    // Diagnostics must never turn a successful or fail-open briefing read into
    // a request failure when a host logger transport is unavailable.
  }
}

/**
 * One structured, content-free discriminator per briefing memory read
 * (issue #2779): `mode`, `durationMs`, `count` when known, `outcome`, and on
 * failure a safe error class — never error messages or memory content.
 */
function logBriefingMemoryRead(
  mode: BriefingReadMode,
  outcome: BriefingReadOutcome,
  durationMs: number,
  resultCount: number | undefined,
  errClass: string | undefined,
): void {
  const fields = [
    `mode=${mode}`,
    `durationMs=${durationMs}`,
    ...(resultCount === undefined ? [] : [`count=${resultCount}`]),
    `outcome=${outcome}`,
    ...(errClass === undefined ? [] : [`err=${errClass}`]),
  ];
  bestEffortLog("info", `briefing: memory read ${fields.join(" ")}`);
}

/** Read only the memories needed by a briefing, with compatibility fallback. */
export async function safeReadMemories(
  storage: BriefingMemoryReader,
  window: ParsedBriefingWindow,
  options: SafeReadMemoriesOptions = {},
): Promise<MemoryFile[]> {
  const startedAt = Date.now();
  const mode: BriefingReadMode =
    typeof storage.readMemoriesWindow === "function" ? "windowed" : "full-read-fallback";
  let outcome: BriefingReadOutcome = "error";
  let resultCount: number | undefined;
  let errClass: string | undefined;
  try {
    const memories = await readBriefingMemories(storage, window, mode, options);
    outcome = "success";
    resultCount = memories.length;
    return memories;
  } catch (err) {
    if (isAbortError(err) && options.signal?.aborted) {
      // Caller cancellation is not a read failure: rethrow it so the briefing
      // rejects instead of degrading into an empty corpus (issue #3139). The
      // own fallback deadline is reported as BriefingReadTimedOut below.
      throw err;
    }
    if (err instanceof BriefingReadTimedOut) {
      outcome = "timeout";
      bestEffortLog(
        "warn",
        `briefing: memory read mode=full-read-fallback timed out after ${err.deadlineMs}ms — ` +
          `returning no memories (storage adapter lacks readMemoriesWindow; upgrade it to ` +
          `windowed or signal-aware reads)`,
      );
    } else if (err instanceof LegacyReadUnsupported) {
      errClass = errorClass(err);
      bestEffortLog(
        "warn",
        `briefing: memory read mode=full-read-fallback refused: readAllMemories() takes no abort ` +
          `signal, so its scan could not be stopped at the deadline — returning no memories ` +
          `(upgrade the storage adapter to readMemoriesWindow or a signal-aware readAllMemories)`,
      );
    } else {
      errClass = errorClass(err);
      bestEffortLog("warn", `briefing: read memories failed (${errClass}) — returning no memories`);
    }
    return [];
  } finally {
    logBriefingMemoryRead(mode, outcome, Date.now() - startedAt, resultCount, errClass);
  }
}

async function readBriefingMemories(
  storage: BriefingMemoryReader,
  window: ParsedBriefingWindow,
  mode: BriefingReadMode,
  options: SafeReadMemoriesOptions,
): Promise<MemoryFile[]> {
  // A briefing only needs memories inside its lookback window. Avoid parsing
  // the full corpus on cache misses; keep the full-read fallback for custom
  // StorageManager-compatible callers that predate readMemoriesWindow().
  if (mode === "windowed") {
    const readOptions: WindowedMemoryReadOptions = { updatedAfter: window.from };
    if (options.signal) readOptions.abortSignal = options.signal;
    const result = await storage.readMemoriesWindow!(readOptions);
    return result.memories;
  }
  // Refuse legacy adapters that do not explicitly declare cancellation support (#2827).
  // Require affirmative cancellation support (`true` on one explicit marker) before fallback.
  // Do not rely on Function.length, which is zero for default/rest/bound functions.
  const isCancellable =
    storage.supportsAbortSignal === true ||
    storage.supportsCancellation === true ||
    storage.cancellable === true ||
    storage.readAllMemories?.supportsAbortSignal === true;
  if (!isCancellable) {
    throw new LegacyReadUnsupported();
  }
  const deadlineMs = options.fallbackDeadlineMs ?? BRIEFING_FULL_READ_FALLBACK_MS;
  const controller = new AbortController();
  let deadlineFired = false;
  const timer = setTimeout(() => {
    deadlineFired = true;
    controller.abort();
  }, deadlineMs);
  const signal = options.signal ? AbortSignal.any([options.signal, controller.signal]) : controller.signal;
  try {
    // Direct await, no Promise.race: the signal IS the deadline. A
    // signal-aware read settles on abort (AbortError at its next scan
    // boundary, #2307), so nothing is left scanning in the background once
    // this function returns.
    const memories = await storage.readAllMemories({ abortSignal: signal });
    if (deadlineFired) {
      // A double that resolves partial rows instead of rejecting on abort
      // must not have them served as a complete corpus.
      throw new BriefingReadTimedOut(deadlineMs);
    }
    return memories;
  } catch (err) {
    if (isAbortError(err) && deadlineFired) throw new BriefingReadTimedOut(deadlineMs);
    throw err;
  } finally {
    clearTimeout(timer);
  }
}

export async function safeReadEntities(
  storage: { readAllEntityFiles(options?: CorpusReadOptions): Promise<EntityFile[]> },
  signal: AbortSignal,
): Promise<EntityFile[]> {
  try {
    return await storage.readAllEntityFiles({ abortSignal: signal });
  } catch (err) {
    if (isAbortError(err) && signal.aborted) throw err;
    log.warn(`briefing: readAllEntityFiles failed: ${err}`);
    return [];
  }
}

/**
 * De-linearization transform (SimpleMem-inspired).
 *
 * Converts extracted memories from context-dependent to context-independent
 * by resolving coreferences and anchoring temporal expressions.
 */

import type { EntityMention } from "./types.js";

// possessive: true means the pronoun is a possessive form (his/her/its/their)
// and should be replaced with "entity's" form.
// group: pronouns in the same group are coreferential (he/him/his all refer to the same person)
const PRONOUN_MAP: Record<string, { types: string[]; possessive: boolean; group: string }> = {
  "he": { types: ["person"], possessive: false, group: "masc" },
  "him": { types: ["person"], possessive: false, group: "masc" },
  "his": { types: ["person"], possessive: true, group: "masc" },
  "she": { types: ["person"], possessive: false, group: "fem" },
  // "her" omitted — ambiguous between object ("saw her") and possessive ("her stack")
  "they": { types: ["company", "project", "other"], possessive: false, group: "they" },
  "them": { types: ["company", "project", "other"], possessive: false, group: "they" },
  "their": { types: ["company", "project", "other"], possessive: true, group: "they" },
  "it": { types: ["project", "tool", "company"], possessive: false, group: "it" },
  "its": { types: ["project", "tool", "company"], possessive: true, group: "it" },
};

/**
 * Replace pronouns with entity names when there's exactly one
 * matching entity of the right type (unambiguous resolution).
 *
 * Possessive pronouns (his/her/its/their) become "entity's".
 * No verb agreement is attempted — it's too fragile with adverbs/modals.
 *
 * Guards against:
 * - Multiple pronouns of the same entity type → skip all (ambiguous referent)
 * - Entity names containing pronoun substrings → placeholder-based two-pass
 * - Entity names containing $ → escaped before replacement
 */
export function resolveCoReferences(fact: string, entities: EntityMention[]): string {
  if (entities.length === 0) return fact;

  // First pass: collect which pronoun entries match and which entity type they target.
  // If multiple distinct referent groups resolve to the same entity type, skip them all
  // (e.g., "She told him" has groups "fem" + "masc" both → person → ambiguous).
  // Coreferential pairs like "he"+"his" share a group ("masc") and are NOT ambiguous.
  const matchingEntries: Array<{ pronoun: string; info: { types: string[]; possessive: boolean; group: string }; entity: EntityMention }> = [];
  const typeToGroups = new Map<string, Set<string>>();

  for (const [pronoun, info] of Object.entries(PRONOUN_MAP)) {
    // Negative lookahead for apostrophe prevents matching contractions (He's, It's, They're)
    const regex = new RegExp(`\\b${pronoun}\\b(?![''\u2019])`, "gi");
    if (!regex.test(fact)) continue;

    const candidates = entities.filter((e) => info.types.includes(e.type));
    if (candidates.length !== 1) continue;

    matchingEntries.push({ pronoun, info, entity: candidates[0] });

    // Track which referent groups target the matched entity's actual type (not all candidate types)
    const matchedType = candidates[0].type;
    if (!typeToGroups.has(matchedType)) typeToGroups.set(matchedType, new Set());
    typeToGroups.get(matchedType)!.add(info.group);
  }

  // Determine which entity types have ambiguous multi-group references
  const ambiguousTypes = new Set<string>();
  for (const [type, groups] of typeToGroups) {
    const matchedEntities = entities.filter((e) => e.type === type);
    if (matchedEntities.length === 1 && groups.size > 1) {
      ambiguousTypes.add(type);
    }
  }

  // Filter out entries whose entity type is ambiguous
  const safeEntries = matchingEntries.filter(
    (e) => !e.info.types.some((t) => ambiguousTypes.has(t)),
  );

  if (safeEntries.length === 0) return fact;

  // Two-pass replacement using placeholders to prevent entity names
  // from being re-matched by subsequent pronoun patterns.
  let result = fact;
  const placeholders: string[] = [];

  for (const { pronoun, info, entity } of safeEntries) {
    const placeholder = `\x00ENTITY_${placeholders.length}\x00`;
    const safeEntityName = entity.name.replace(/\$/g, "$$$$");
    const replacement = info.possessive ? `${safeEntityName}'s` : safeEntityName;
    placeholders.push(replacement);
    result = result.replace(
      new RegExp(`\\b${pronoun}\\b(?![''\u2019])`, "gi"),
      placeholder,
    );
  }

  // Restore placeholders with actual entity names
  for (let i = 0; i < placeholders.length; i++) {
    result = result.replaceAll(`\x00ENTITY_${i}\x00`, placeholders[i]);
  }

  return result;
}

function formatDate(d: Date): string {
  return d.toISOString().slice(0, 10);
}

const TEMPORAL_PATTERNS: Array<{
  pattern: RegExp;
  replace: (now: Date) => string;
// Compound patterns first (longer matches before shorter to avoid partial replacement)
}> = [
  {
    pattern: /\bearlier today\b/gi,
    replace: (now) => `earlier on ${formatDate(now)}`,
  },
  {
    pattern: /\bthis morning\b/gi,
    replace: (now) => `on the morning of ${formatDate(now)}`,
  },
  {
    pattern: /\bthis afternoon\b/gi,
    replace: (now) => `on the afternoon of ${formatDate(now)}`,
  },
  {
    pattern: /\bthis evening\b/gi,
    replace: (now) => `on the evening of ${formatDate(now)}`,
  },
  {
    pattern: /\blast week\b/gi,
    replace: (now) => {
      const d = new Date(now);
      d.setUTCDate(d.getUTCDate() - 7);
      return `around ${formatDate(d)}`;
    },
  },
  {
    pattern: /\blast month\b/gi,
    replace: (now) => {
      const d = new Date(now);
      d.setUTCDate(1); // avoid overflow (e.g. Mar 31 → Feb 31 → Mar 3)
      d.setUTCMonth(d.getUTCMonth() - 1);
      return `around ${formatDate(d)}`;
    },
  },
  // Simple patterns last
  {
    pattern: /\byesterday\b/gi,
    replace: (now) => {
      const d = new Date(now);
      d.setUTCDate(d.getUTCDate() - 1);
      return `on ${formatDate(d)}`;
    },
  },
  {
    pattern: /\btoday\b/gi,
    replace: (now) => `on ${formatDate(now)}`,
  },
  {
    pattern: /\btomorrow\b/gi,
    replace: (now) => {
      const d = new Date(now);
      d.setUTCDate(d.getUTCDate() + 1);
      return `on ${formatDate(d)}`;
    },
  },
];

/**
 * Replace relative temporal expressions with absolute ISO-8601 dates.
 */
export function anchorTemporalExpressions(fact: string, now: Date): string {
  let result = fact;
  for (const { pattern, replace } of TEMPORAL_PATTERNS) {
    result = result.replace(pattern, replace(now));
  }
  return result;
}

/**
 * Full de-linearization pipeline: temporal anchoring first, then coreference.
 * Order matters: entity names may contain temporal words (e.g., "project-tomorrow")
 * which would be corrupted if temporal anchoring ran after coreference insertion.
 */
export function delinearize(
  factContent: string,
  entities: EntityMention[],
  timestamp: Date,
): string {
  let result = anchorTemporalExpressions(factContent, timestamp);
  result = resolveCoReferences(result, entities);
  return result;
}

import type { LocalLlmClient } from "./local-llm.js";
import type { PluginConfig } from "./types.js";

/**
 * Decide whether the optional proactive extraction second-pass should run.
 *
 * The proactive pass is fail-soft enrichment: it re-sends the full conversation
 * to generate follow-up questions on top of the base extraction. On a saturated
 * single-lane local LLM host (one Ollama runner), an optional pass queued behind
 * an in-flight extraction loses its short client deadline while it waits, 500s,
 * and wastes prefill GPU-seconds without ever producing output (issue #2011).
 *
 * Returns false (skip the pass, keep the base extraction unchanged) when:
 * - the pass is disabled by budget config (`0` question / timeout / token caps),
 * - or `proactiveExtractionSkipWhenLocalLlmBusy` is on, the extraction is running
 *   against the local LLM, and that client's background lane is already busy —
 *   so the optional pass would only queue behind concurrent extraction work.
 *
 * The cloud-fallback path has no single-lane saturation, so the busy-lane skip
 * only applies when the local LLM is the active extractor.
 */
export function shouldRunProactivePass(
  config: PluginConfig,
  maxAdditional: number,
  usingLocalLlm: boolean,
  localLlm: LocalLlmClient,
): boolean {
  if (maxAdditional === 0) return false;
  if (config.proactiveExtractionTimeoutMs === 0) return false;
  if (config.proactiveExtractionMaxTokens === 0) return false;
  if (
    config.proactiveExtractionSkipWhenLocalLlmBusy &&
    usingLocalLlm &&
    localLlm.isBackgroundLaneContended()
  ) {
    return false;
  }
  return true;
}

/**
 * LLM revalidation of dependent memories after a support link breaks.
 *
 * Extracted from ExtractionEngine to keep extraction.ts under its ratchet
 * ceiling. The ExtractionEngine.revalidateDependents method delegates here.
 */

export interface RevalidationVerdict {
  memoryId: string;
  verdict: "still_valid" | "invalidated" | "uncertain";
  reason?: string;
}

export type RevalidationFastChatCompletion = (
  messages: Array<{ role: "system" | "user" | "assistant"; content: string }>,
  options: {
    temperature?: number;
    maxTokens?: number;
    timeoutMs?: number;
    operation?: string;
    priority?: "background" | "recall-critical";
    signal?: AbortSignal;
  },
) => Promise<{ content: string } | null>;

export interface RevalidationDeps {
  fastChatCompletion: RevalidationFastChatCompletion;
  parseJsonObject: (raw: string | null) => unknown;
}

function isPlainRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

function buildPrompt(
  superseded: { id: string; content: string },
  replacement: { id: string; content: string } | null,
  dependents: Array<{ id: string; category: string; content: string }>,
): { input: string; instructionText: string } {
  const dependentPrompt = dependents
    .map(
      (memory, index) =>
        `[${index + 1}] id: ${memory.id} | category: ${memory.category}\n${memory.content}`,
    )
    .join("\n\n");
  const input = `SUPERSEDED MEMORY (id: ${superseded.id}):
${superseded.content}

REPLACEMENT (id: ${replacement?.id ?? "none"}):
${replacement?.content ?? "none — the memory was removed without replacement"}

DEPENDENTS TO REVALIDATE (return exactly one verdict per id):
${dependentPrompt}`;
  const instructionText = `You revalidate dependent memory claims after a supporting memory changes.
For each requested memory, decide whether its claim still holds.
Return valid JSON only:
{"verdicts":[{"memoryId":"id","verdict":"still_valid|invalidated|uncertain","reason":"brief reason"}]}
Never invent memory IDs. Use "uncertain" when the evidence is insufficient.`;
  return { input, instructionText };
}

function normalizeVerdicts(
  parsed: unknown,
  dependents: Array<{ id: string }>,
): RevalidationVerdict[] {
  const raw: unknown[] = isPlainRecord(parsed) && Array.isArray(parsed.verdicts) ? parsed.verdicts : [];
  const requested = new Set(dependents.map((memory) => memory.id));
  const seen = new Set<string>();
  const normalized: RevalidationVerdict[] = [];
  for (const candidate of raw) {
    if (!isPlainRecord(candidate)) continue;
    const memoryId = typeof candidate.memoryId === "string" ? candidate.memoryId.trim() : "";
    if (!requested.has(memoryId) || seen.has(memoryId)) continue;
    seen.add(memoryId);
    const verdict =
      candidate.verdict === "still_valid" ||
      candidate.verdict === "invalidated" ||
      candidate.verdict === "uncertain"
        ? candidate.verdict
        : "uncertain";
    normalized.push({
      memoryId,
      verdict,
      ...(typeof candidate.reason === "string" ? { reason: candidate.reason } : {}),
    });
  }
  return dependents.map((memory) => {
    const verdict = normalized.find((candidate) => candidate.memoryId === memory.id);
    return verdict ?? { memoryId: memory.id, verdict: "uncertain" as const };
  });
}

export async function revalidateDependentsViaLlm(
  deps: RevalidationDeps,
  superseded: { id: string; content: string },
  replacement: { id: string; content: string } | null,
  dependents: Array<{ id: string; category: string; content: string }>,
  options: { signal?: AbortSignal; timeoutMs?: number } = {},
): Promise<{ verdicts: RevalidationVerdict[] }> {
  const { input, instructionText } = buildPrompt(superseded, replacement, dependents);
  const maxTokens = Math.max(1024, dependents.length * 256);
  const response = await deps.fastChatCompletion(
    [
      { role: "system", content: instructionText },
      { role: "user", content: input },
    ],
    {
      temperature: 0.2,
      maxTokens,
      operation: "dependency_revalidation",
      priority: "background",
      timeoutMs: options.timeoutMs,
      signal: options.signal,
    },
  );
  const rawContent = response?.content ?? null;
  if (!rawContent?.trim()) {
    throw new Error("fast completion returned no dependency revalidation output");
  }

  return { verdicts: normalizeVerdicts(deps.parseJsonObject(rawContent), dependents) };
}

