export const WORK_LAYER_CONTEXT_OPEN = "[WORK_LAYER_CONTEXT";
export const WORK_LAYER_CONTEXT_CLOSE = "[/WORK_LAYER_CONTEXT]";
const WORK_LAYER_CONTEXT_ESCAPED_OPEN = "[WORK_LAYER_ESCAPED_CONTEXT";
const WORK_LAYER_CONTEXT_ESCAPED_CLOSE = "[/WORK_LAYER_CONTEXT_ESC]";

export function wrapWorkLayerContext(content: string, options?: { linkToMemory?: boolean }): string {
  const linkToMemory = options?.linkToMemory === true;
  const header = `${WORK_LAYER_CONTEXT_OPEN} link_to_memory=${linkToMemory ? "true" : "false"}]`;
  const payload = content
    .trim()
    .replaceAll(WORK_LAYER_CONTEXT_OPEN, WORK_LAYER_CONTEXT_ESCAPED_OPEN)
    .replaceAll(WORK_LAYER_CONTEXT_CLOSE, WORK_LAYER_CONTEXT_ESCAPED_CLOSE);
  return `${header}\n${payload}\n${WORK_LAYER_CONTEXT_CLOSE}`;
}

export function applyWorkExtractionBoundary(conversation: string): string {
  if (conversation.trim().length === 0) return "";

  // Replace work-layer blocks using indexOf to avoid backtracking regex.
  let bounded = conversation;
  const OPEN_TAG = "[WORK_LAYER_CONTEXT";
  const CLOSE_TAG = "[/WORK_LAYER_CONTEXT]";
  let searchFrom = 0;
  while (true) {
    const openIdx = bounded.indexOf(OPEN_TAG, searchFrom);
    if (openIdx < 0) break;
    // Require line-start anchor
    if (openIdx > 0 && bounded[openIdx - 1] !== "\n") {
      searchFrom = openIdx + OPEN_TAG.length;
      continue;
    }
    const closeBracket = bounded.indexOf("]", openIdx + OPEN_TAG.length);
    if (closeBracket < 0) break;
    const header = bounded.substring(openIdx + OPEN_TAG.length, closeBracket);
    const closeIdx = bounded.indexOf(CLOSE_TAG, closeBracket + 1);
    if (closeIdx < 0) break;
    // Parse attributes from header
    const flagMatch = header.match(/\blink_to_memory=(true|false)/);
    const encMatch = header.match(/\bencoding=(base64)/);
    const flag = flagMatch?.[1];
    const encoding = encMatch?.[1];
    // Extract body (between ] and closer)
    let bodyStart = closeBracket + 1;
    if (bounded[bodyStart] === "\n") bodyStart++;
    let bodyEnd = closeIdx;
    if (bodyEnd > bodyStart && bounded[bodyEnd - 1] === "\n") bodyEnd--;
    const body = bounded.substring(bodyStart, bodyEnd);
    const shouldLink = flag === "true";
    const prefix = openIdx > 0 ? bounded.substring(0, openIdx) : "";
    const suffix = bounded.substring(closeIdx + CLOSE_TAG.length);
    if (!shouldLink) {
      bounded = prefix + suffix;
      searchFrom = prefix.length;
    } else if (encoding === "base64") {
      try {
        const decoded = Buffer.from(body.trim(), "base64").toString("utf8").trim();
        bounded = prefix + decoded + suffix;
        searchFrom = prefix.length + decoded.length;
      } catch {
        bounded = prefix + suffix;
        searchFrom = prefix.length;
      }
    } else {
      bounded = prefix + body.trim() + suffix;
      searchFrom = prefix.length + body.trim().length;
    }
  }

  // Defensive hardening: if a *real wrapper opener* survives without a closer (e.g., turn-level truncation),
  // strip everything from the opener onward to avoid leaking excluded work-layer payloads.
  // Keep literal "[WORK_LAYER_CONTEXT" text unless it contains wrapper metadata attributes.
  // Strip unterminated work-layer openers using indexOf for safety (avoids backtracking).
  // Only match openers at the start of a line (like the original ^|\n anchor).
  let strippedUnterminated = bounded;
  const opener = "[WORK_LAYER_CONTEXT";
  const closer = "[/WORK_LAYER_CONTEXT]";
  let unterminatedSearchFrom = 0;
  while (true) {
    const openerIdx = bounded.indexOf(opener, unterminatedSearchFrom);
    if (openerIdx < 0) break;

    const isLineStart = openerIdx === 0 || bounded[openerIdx - 1] === "\n";
    if (!isLineStart) {
      unterminatedSearchFrom = openerIdx + opener.length;
      continue;
    }

    const afterOpener = bounded.indexOf("]", openerIdx);
    const bracketContent = afterOpener >= 0
      ? bounded.substring(openerIdx, afterOpener + 1)
      : bounded.substring(openerIdx);
    const hasWrapperMetadata =
      bracketContent.includes("link_to_memory=") || bracketContent.includes("encoding=");
    if (!hasWrapperMetadata) {
      unterminatedSearchFrom = openerIdx + opener.length;
      continue;
    }

    const closerAfter = afterOpener >= 0 ? bounded.indexOf(closer, afterOpener) : -1;
    if (closerAfter < 0) {
      strippedUnterminated = openerIdx > 0
        ? bounded.substring(0, openerIdx - 1)  // exclude the preceding \n
        : "";
      break;
    }

    unterminatedSearchFrom = closerAfter + closer.length;
  }

  const restoredEscapes = strippedUnterminated
    .replaceAll(WORK_LAYER_CONTEXT_ESCAPED_OPEN, WORK_LAYER_CONTEXT_OPEN)
    .replaceAll(WORK_LAYER_CONTEXT_ESCAPED_CLOSE, WORK_LAYER_CONTEXT_CLOSE);

  const cleanedLines = restoredEscapes
    .split("\n")
    .map((line) => line.trimEnd());

  return cleanedLines.join("\n").replace(/\n{3,}/g, "\n\n").trim();
}

const rx = (...parts: string[]): RegExp => new RegExp(parts.join(""), "i");

const INJECTION_PATTERNS: RegExp[] = [
  rx("ignore\\s+(all\\s+)?", "(previous|prior|above)", "\\s+(instructions?|prompts?|context)"),
  rx("forget\\s+", "(everything|all|previous|what)"),
  rx(
    "new\\s+(",
    "system",
    "\\s+)?",
    "prompt:",
  ),
  rx("\\[", "system", "\\]"),
  rx("<\\s*", "system", "\\s*>"),
  rx("you\\s+are\\s+now\\s+(?!called|named)"),
  rx("disregard\\s+(all\\s+)?", "(previous|prior)"),
  rx(
    "over",
    "ride\\s+(previous\\s+)?",
    "(instructions?|",
    "prompt)",
  ),
  rx("act\\s+as\\s+(?:an?\\s+)?(?:AI|assistant|ChatGPT|GPT|Claude|LLM)\\s+(?:without|that\\s+ignores)"),
  rx("do\\s+not\\s+(?:follow|obey)\\s+(?:previous|prior|your)\\s+", "instructions"),
  rx("pretend\\s+(?:you\\s+)?(?:have\\s+no|you\\s+don.?t\\s+have)\\s+(restrictions|guidelines|rules)"),
];

export type SanitizeResult = {
  clean: boolean;
  text: string;
  violations: string[];
};

const REDACTED_PLACEHOLDER = "[content removed: unsafe memory text]";

export function sanitizeMemoryContent(text: string): SanitizeResult {
  const source = typeof text === "string" ? text : "";
  const violations: string[] = [];

  for (const pattern of INJECTION_PATTERNS) {
    if (pattern.test(source)) {
      violations.push(pattern.source);
    }
  }

  if (violations.length === 0) {
    return { clean: true, text: source, violations: [] };
  }

  return {
    clean: false,
    text: REDACTED_PLACEHOLDER,
    violations,
  };
}

export function isSafeMemoryContent(text: string): boolean {
  return sanitizeMemoryContent(text).clean;
}

// Issue #1582 hygiene §2 — handles are render-time-only tokens; when an agent
// echoes one back into a turn, the orchestrator strips it via this name before
// the turn enters the extraction buffer (rule 23). Re-exported from the pure
// recall-handles module so every content-sanitization concern lives here.
export { stripHandles as stripMemoryHandles } from "./recall-handles.js";

function normalizedModel(model: string): string {
  return model.trim().toLowerCase();
}

function matchesModelFamily(normalized: string, familyPattern: RegExp): boolean {
  return familyPattern.test(normalized);
}

export function shouldAssumeOpenAiChatCompletions(baseUrl?: string): boolean {
  if (!baseUrl) return true;
  try {
    return new URL(baseUrl).hostname.toLowerCase() === "api.openai.com";
  } catch {
    return false;
  }
}

export function usesMaxCompletionTokens(model: string, options?: { assumeOpenAI?: boolean }): boolean {
  const normalized = normalizedModel(model);
  if (options?.assumeOpenAI !== true) return false;
  if (matchesModelFamily(normalized, /^gpt-5(?:$|[-.])/)) return true;
  if (matchesModelFamily(normalized, /^gpt-4o(?:$|[-.])/)) return true;
  if (matchesModelFamily(normalized, /^gpt-4\.1(?:$|[-.])/)) return true;
  if (matchesModelFamily(normalized, /^o1(?:$|[-.])/)) return true;
  if (matchesModelFamily(normalized, /^o3(?:$|[-.])/)) return true;
  return matchesModelFamily(normalized, /^o4-mini(?:$|[-.])/);
}

export function buildChatCompletionTokenLimit(
  model: string,
  maxTokens: number,
  options?: { assumeOpenAI?: boolean },
): { max_tokens: number } | { max_completion_tokens: number } {
  const safeMaxTokens = Math.max(0, Math.floor(maxTokens));
  if (usesMaxCompletionTokens(model, options)) {
    return { max_completion_tokens: safeMaxTokens };
  }
  return { max_tokens: safeMaxTokens };
}

export function supportsTemperature(model: string, options?: { assumeOpenAI?: boolean }): boolean {
  const normalized = normalizedModel(model);
  if (options?.assumeOpenAI === true && matchesModelFamily(normalized, /^gpt-5(?:$|[-.])/)) {
    return false;
  }
  return true;
}

export function buildChatCompletionTemperature(
  model: string,
  temperature: number,
  options?: { assumeOpenAI?: boolean },
): { temperature: number } | Record<string, never> {
  if (!supportsTemperature(model, options)) return {};
  return { temperature };
}

import path from "node:path";
import { fileURLToPath } from "node:url";
import { log } from "./logger.js";
import type { MemoryFile, PluginConfig } from "./types.js";
import { discoverMemoryExtensions, renderExtensionsFooter, resolveExtensionsRoot } from "./memory-extension-host/index.js";
import { resolvePipelineProcessingCapabilities } from "./capabilities.js";

const PROMPT_RELATIVE_PATH = path.join("prompts", "day_summary.prompt.md");

// Embedded fallback prompt for packaged/plugin-install builds where
// prompts/day_summary.prompt.md may not be present in the runtime bundle.
const EMBEDDED_DAY_SUMMARY_PROMPT = `# Baseline day-summary prompt

You are writing an Engram end-of-day summary.

Your job:
- compress the day into a short, useful recap
- prioritize concrete events, decisions, mood/energy signals, and open loops
- include a few practical next actions for tomorrow
- avoid hype, fluff, therapy-speak, and invented facts

Output JSON with these keys:
- \`summary\` — one short paragraph
- \`bullets\` — 2 to 5 bullets with the most important moments
- \`next_actions\` — 1 to 3 concrete actions
- \`risks_or_open_loops\` — 0 to 3 things that still need attention

Rules:
- stay grounded in the input only
- if the day was mixed, say so plainly
- do not overstate confidence or importance
- prefer specific verbs over vague abstractions

Brevity:
- keep the summary under 90 words
- keep bullets short and information-dense
- omit anything that does not change what tomorrow should care about

Structure:
- \`summary\` should be one paragraph only
- \`bullets\` should contain the most important moments, not generic restatements
- \`next_actions\` and \`risks_or_open_loops\` should be distinct and non-overlapping

Risk:
- explicitly surface unresolved blockers, dependencies, or fragile assumptions
- do not bury open loops inside the summary if they deserve separate attention

Tone:
- sound like a clear internal daily note, not a report template
- stay natural and direct while remaining compact`;

function candidateRoots(): string[] {
  const currentFile = fileURLToPath(import.meta.url);
  const here = path.dirname(currentFile);
  const candidates = [path.resolve(here, ".."), path.resolve(here, "..", "..")];

  const seen = new Set<string>();
  return candidates.filter((candidate) => {
    const normalized = path.resolve(candidate);
    if (seen.has(normalized)) return false;
    seen.add(normalized);
    return true;
  });
}

async function resolvePromptPath(): Promise<string | null> {
  const { existsSync } = await import("node:fs");
  for (const root of candidateRoots()) {
    const candidate = path.join(root, PROMPT_RELATIVE_PATH);
    if (existsSync(candidate)) {
      return candidate;
    }
  }
  return null;
}

export async function loadDaySummaryPrompt(): Promise<string> {
  const promptPath = await resolvePromptPath();
  if (promptPath) {
    try {
      const { readFile } = await import("node:fs/promises");
      const raw = await readFile(promptPath, "utf-8");
      // CRLF-compatible regex: allow \r\n or \n line endings
      const match = raw.match(/```(?:[a-zA-Z0-9_-]+)?\r?\n([\s\S]*?)\r?\n```/);
      if (match?.[1]) {
        return match[1].trim();
      }
      log.warn("day summary prompt file does not contain a fenced prompt block; using embedded fallback");
    } catch (err) {
      log.warn(`day summary prompt file read failed; using embedded fallback: ${err}`);
    }
  }
  return EMBEDDED_DAY_SUMMARY_PROMPT;
}

const FSI = "\u2068"; // FIRST STRONG ISOLATE
const PDI = "\u2069"; // POP DIRECTIONAL ISOLATE

/**
 * Wrap user content in Unicode bidi isolates so RTL text (Arabic, Hebrew)
 * cannot reorder the surrounding Latin labels on the same composed line.
 * No visible change for LTR content (issue #2198).
 */
function bidiIsolate(text: string): string {
  return `${FSI}${text}${PDI}`;
}

export function formatDaySummaryMemories(memories: string | MemoryFile[]): string {
  if (typeof memories === "string") {
    return memories.trim();
  }

  return memories
    .map((memory) => {
      const category = memory.frontmatter.category || "fact";
      const created = memory.frontmatter.created || "unknown";
      return `[${memory.frontmatter.id}] (${category}, ${created})\n${bidiIsolate(memory.content)}`;
    })
    .join("\n\n")
    .trim();
}

/**
 * Build a one-line extension footer for day-summary and summary-snapshot contexts.
 * Returns "" when extensions are disabled or none are found.
 */
export async function buildExtensionsFooterForSummary(
  config: PluginConfig,
): Promise<string> {
  if (!resolvePipelineProcessingCapabilities(config).memoryExtensions) return "";
  const root = resolveExtensionsRoot(config);
  const extensions = await discoverMemoryExtensions(root, log);
  if (extensions.length === 0) return "";
  return renderExtensionsFooter(extensions);
}

/**
 * Procedural memory types (issue #519).
 * Bodies use ordered "## Step N" sections; machine fields live in frontmatter / structuredAttributes.
 */

export interface ProcedureStep {
  order: number;
  intent: string;
  toolCall?: {
    kind: string;
    signature: string;
  };
  expectedOutcome?: string;
  optional?: boolean;
}

/** Normalize loose extraction JSON into ProcedureStep records. */
export function normalizeProcedureSteps(raw: unknown): ProcedureStep[] {
  if (!Array.isArray(raw)) return [];
  const out: ProcedureStep[] = [];
  for (let i = 0; i < raw.length; i++) {
    const s = raw[i];
    if (!s || typeof s !== "object") continue;
    const o = s as Record<string, unknown>;
    const intent = typeof o.intent === "string" ? o.intent.trim() : "";
    if (!intent) continue;
    const orderRaw = o.order;
    const order =
      typeof orderRaw === "number" && Number.isFinite(orderRaw)
        ? Math.max(1, Math.floor(orderRaw))
        : i + 1;
    let toolCall: ProcedureStep["toolCall"];
    const tc = o.toolCall;
    if (tc && typeof tc === "object" && !Array.isArray(tc)) {
      const t = tc as Record<string, unknown>;
      const kind = typeof t.kind === "string" ? t.kind.trim() : "";
      const signature = typeof t.signature === "string" ? t.signature.trim() : "";
      if (kind && signature) {
        toolCall = { kind, signature };
      }
    }
    const expectedOutcome =
      typeof o.expectedOutcome === "string" && o.expectedOutcome.trim()
        ? o.expectedOutcome.trim()
        : undefined;
    const optional = o.optional === true ? true : undefined;
    out.push({ order, intent, toolCall, expectedOutcome, optional });
  }
  return out;
}

/** Title line plus serialized steps for storage.writeMemory body. */
export function buildProcedurePersistBody(title: string, procedureSteps: unknown): string {
  const head = typeof title === "string" ? title.trim() : "";
  const steps = normalizeProcedureSteps(procedureSteps);
  if (steps.length === 0) return head;
  return `${head}\n\n${buildProcedureMarkdownBody(steps)}`.trimEnd() + "\n";
}

/** Serialize steps into markdown body (human-editable). */
export function buildProcedureMarkdownBody(steps: ProcedureStep[]): string {
  const sorted = [...steps].sort((a, b) => a.order - b.order);
  const lines: string[] = [];
  for (const step of sorted) {
    const n = Number.isFinite(step.order) ? Math.max(1, Math.floor(step.order)) : 1;
    lines.push(`## Step ${n}`);
    lines.push("");
    lines.push(step.intent.trim());
    if (step.toolCall?.kind && step.toolCall.signature) {
      lines.push("");
      lines.push(`- Tool: \`${step.toolCall.kind}\` — ${step.toolCall.signature}`);
    }
    if (step.expectedOutcome?.trim()) {
      lines.push("");
      lines.push(`- Expected: ${step.expectedOutcome.trim()}`);
    }
    if (step.optional === true) {
      lines.push("");
      lines.push("- Optional: true");
    }
    lines.push("");
  }
  return lines.join("\n").trimEnd() + "\n";
}

const STEP_HEADER_RE = /^##\s+Step\s+(\d+)\s*$/im;

/**
 * Best-effort parse of "## Step N" blocks into ProcedureStep records.
 * Returns null when no step headers are found.
 */
export function parseProcedureStepsFromBody(content: string): ProcedureStep[] | null {
  const text = content.replace(/\r\n/g, "\n").trim();
  if (!text) return null;
  const matches = [...text.matchAll(new RegExp(STEP_HEADER_RE.source, "gim"))];
  if (matches.length === 0) return null;

  const steps: ProcedureStep[] = [];
  for (let i = 0; i < matches.length; i++) {
    const m = matches[i];
    const order = Number.parseInt(m[1] ?? "1", 10);
    const start = (m.index ?? 0) + m[0].length;
    const end = i + 1 < matches.length ? (matches[i + 1].index ?? text.length) : text.length;
    const block = text.slice(start, end).trim();
    const lines = block.split("\n").map((l) => l.trim());
    const intentLines = lines.filter(
      (l) => l.length > 0 && !l.startsWith("- Tool:") && !l.startsWith("- Expected:") && !l.startsWith("- Optional:"),
    );
    const intent = intentLines.join(" ").trim() || "(unspecified)";
    let toolCall: ProcedureStep["toolCall"];
    const toolLine = lines.find((l) => l.startsWith("- Tool:"));
    if (toolLine) {
      const inner = toolLine.replace(/^- Tool:\s*/i, "").trim();
      const tick = inner.match(/^`([^`]+)`\s*[—-]\s*(.+)$/);
      if (tick) {
        toolCall = { kind: tick[1].trim(), signature: tick[2].trim() };
      }
    }
    const expectedLine = lines.find((l) => l.startsWith("- Expected:"));
    const expectedOutcome = expectedLine?.replace(/^- Expected:\s*/i, "").trim();
    const optional = /^- Optional:\s*true$/i.test(lines.find((l) => l.startsWith("- Optional:")) ?? "");

    steps.push({
      order: Number.isFinite(order) ? order : i + 1,
      intent,
      toolCall,
      expectedOutcome: expectedOutcome?.length ? expectedOutcome : undefined,
      optional: optional || undefined,
    });
  }
  return steps.length > 0 ? steps : null;
}

/**
 * Reasoning-trace memory structural types (issue #564).
 *
 * Captures stored solution chains / chain-of-thought the user walked through
 * to solve a problem. Traces have an ordered list of steps, a final answer,
 * and an optional observed outcome.
 */

export interface ReasoningTraceStep {
  /** 1-based ordinal within the trace. */
  order: number;
  /** Human-readable description of what happened at this step. */
  description: string;
}

export interface ReasoningTraceStructuredData {
  steps: ReasoningTraceStep[];
  finalAnswer: string;
  /** Optional confirmation of how the answer played out in practice. */
  observedOutcome?: string;
}

/** Normalize loose extraction JSON into ReasoningTraceStep records. */
export function normalizeReasoningTraceSteps(raw: unknown): ReasoningTraceStep[] {
  if (!Array.isArray(raw)) return [];
  const out: ReasoningTraceStep[] = [];
  for (let i = 0; i < raw.length; i++) {
    const s = raw[i];
    let description = "";
    let orderRaw: unknown;
    if (typeof s === "string") {
      description = s.trim();
    } else if (s && typeof s === "object") {
      const o = s as Record<string, unknown>;
      if (typeof o.description === "string") description = o.description.trim();
      else if (typeof o.intent === "string") description = o.intent.trim();
      else if (typeof o.step === "string") description = o.step.trim();
      else if (typeof o.text === "string") description = o.text.trim();
      orderRaw = o.order;
    }
    if (!description) continue;
    const order =
      typeof orderRaw === "number" && Number.isFinite(orderRaw)
        ? Math.max(1, Math.floor(orderRaw))
        : i + 1;
    out.push({ order, description });
  }
  return out;
}

/**
 * Normalize a loose reasoningTrace object (e.g. coming back from the LLM) to
 * a strict ReasoningTraceStructuredData shape. Returns null when the data is
 * clearly incomplete (no steps or no final answer).
 */
export function normalizeReasoningTrace(raw: unknown): ReasoningTraceStructuredData | null {
  if (!raw || typeof raw !== "object" || Array.isArray(raw)) return null;
  const o = raw as Record<string, unknown>;
  const steps = normalizeReasoningTraceSteps(o.steps);
  const finalAnswer =
    typeof o.finalAnswer === "string"
      ? o.finalAnswer.trim()
      : typeof o.final_answer === "string"
      ? (o.final_answer as string).trim()
      : "";
  // Prompts describe reasoning_trace as requiring ≥2 ordered steps + a final
  // answer. Rejecting one-step payloads here keeps the category semantically
  // distinct from ordinary `decision` facts and prevents malformed traces
  // from sneaking through loose local/direct extraction JSON.
  if (steps.length < 2 || finalAnswer.length === 0) return null;
  const observedRaw =
    typeof o.observedOutcome === "string"
      ? o.observedOutcome
      : typeof o.observed_outcome === "string"
      ? (o.observed_outcome as string)
      : undefined;
  const observedOutcome = observedRaw?.trim();
  return {
    steps,
    finalAnswer,
    observedOutcome: observedOutcome && observedOutcome.length > 0 ? observedOutcome : undefined,
  };
}

/**
 * Serialize a normalized reasoning trace into a human-readable markdown body.
 * Output shape mirrors the procedure body format: ## Step N sections followed
 * by final answer and optional observed outcome.
 */
export function buildReasoningTraceMarkdownBody(trace: ReasoningTraceStructuredData): string {
  const sorted = [...trace.steps].sort((a, b) => a.order - b.order);
  const lines: string[] = [];
  for (const step of sorted) {
    const n = Number.isFinite(step.order) ? Math.max(1, Math.floor(step.order)) : 1;
    lines.push(`## Step ${n}`);
    lines.push("");
    lines.push(step.description.trim());
    lines.push("");
  }
  lines.push("## Final Answer");
  lines.push("");
  lines.push(trace.finalAnswer.trim());
  lines.push("");
  if (trace.observedOutcome && trace.observedOutcome.trim().length > 0) {
    lines.push("## Observed Outcome");
    lines.push("");
    lines.push(trace.observedOutcome.trim());
    lines.push("");
  }
  return lines.join("\n").trimEnd() + "\n";
}

/**
 * Combine a short title with the structured trace body. The title becomes the
 * one-line content of the stored memory, and the full body is appended below.
 */
export function buildReasoningTracePersistBody(
  title: string,
  trace: ReasoningTraceStructuredData,
): string {
  const head = typeof title === "string" ? title.trim() : "";
  const body = buildReasoningTraceMarkdownBody(trace);
  if (!head) return body;
  return `${head}\n\n${body}`.trimEnd() + "\n";
}

const STEP_HEADER_RE = /^##\s+Step\s+(\d+)\s*$/im;
const FINAL_HEADER_RE = /^##\s+Final Answer\s*$/im;
const OBSERVED_HEADER_RE = /^##\s+Observed Outcome\s*$/im;

/**
 * Best-effort parse of a reasoning-trace markdown body back into structured
 * data. Returns null when the document does not look like a reasoning trace.
 */
export function parseReasoningTraceFromBody(content: string): ReasoningTraceStructuredData | null {
  const text = content.replace(/\r\n/g, "\n").trim();
  if (!text) return null;
  const stepMatches = [...text.matchAll(new RegExp(STEP_HEADER_RE.source, "gim"))];
  const finalMatch = FINAL_HEADER_RE.exec(text);
  if (stepMatches.length === 0 || !finalMatch) return null;

  const observedMatch = OBSERVED_HEADER_RE.exec(text);

  const steps: ReasoningTraceStep[] = [];
  for (let i = 0; i < stepMatches.length; i++) {
    const m = stepMatches[i];
    const order = Number.parseInt(m[1] ?? String(i + 1), 10);
    const start = (m.index ?? 0) + m[0].length;
    const nextStepStart =
      i + 1 < stepMatches.length ? stepMatches[i + 1].index ?? text.length : text.length;
    const end = Math.min(nextStepStart, finalMatch.index ?? text.length);
    const block = text.slice(start, end).trim();
    const description = block.split("\n").map((l) => l.trim()).filter((l) => l.length > 0).join(" ");
    if (!description) continue;
    steps.push({
      order: Number.isFinite(order) ? order : i + 1,
      description,
    });
  }

  // Honor the >=2 ordered-steps invariant enforced everywhere else in the
  // pipeline (prompts, normalizer, schema). A single-step manually-edited
  // or corrupt file should not round-trip back in as a reasoning_trace.
  if (steps.length < 2) return null;

  const finalStart = (finalMatch.index ?? 0) + finalMatch[0].length;
  const finalEnd = observedMatch?.index ?? text.length;
  const finalAnswer = text
    .slice(finalStart, finalEnd)
    .split("\n")
    .map((l) => l.trim())
    .filter((l) => l.length > 0)
    .join(" ")
    .trim();
  if (!finalAnswer) return null;

  let observedOutcome: string | undefined;
  if (observedMatch) {
    const obsStart = (observedMatch.index ?? 0) + observedMatch[0].length;
    const raw = text
      .slice(obsStart)
      .split("\n")
      .map((l) => l.trim())
      .filter((l) => l.length > 0)
      .join(" ")
      .trim();
    if (raw) observedOutcome = raw;
  }

  return { steps, finalAnswer, observedOutcome };
}

/**
 * Heuristic detector for whether a user message contains a chain-of-thought /
 * solution trace that should be extracted. This is intentionally conservative:
 * we require at least two explicitly-ordered steps and some form of final
 * answer / resolution. Used by the extraction pipeline to decide whether to
 * even consider emitting a reasoning_trace fact, so false positives are more
 * costly than false negatives.
 */
export function looksLikeReasoningTrace(message: string): boolean {
  if (typeof message !== "string") return false;
  const text = message.trim();
  if (text.length < 80) return false;

  // Count lines that carry at least one step marker, not the total number of
  // marker matches. Summing across multiple regexes can let a single line
  // contribute two "steps" (e.g. "Step 1: First,…" matches both patterns),
  // which weakens the "false positives > false negatives" bias. Per-line
  // counting keeps the gate symmetric with real step structure.
  const stepMarkerRes = [
    /\bstep\s+\d+\s*[:.\-]/i,
    /^\s*\d+[.)]\s+\S/,
    /^\s*(first|second|third|fourth|finally|then|next)\b[,:]/i,
  ];
  const lines = text.split(/\r?\n/);
  let stepCount = 0;
  for (const line of lines) {
    if (stepMarkerRes.some((re) => re.test(line))) {
      stepCount += 1;
      if (stepCount >= 2) break;
    }
  }
  if (stepCount < 2) return false;

  // Final-answer / resolution marker. Split into two checks so the trailing
  // `\b` on the word-final alternatives doesn't accidentally require a word
  // character after `answer:` / `result:` (both end in a non-word `:`).
  const wordFinalMarker =
    /\b(final answer|so the answer|therefore|conclusion|in the end|ended up|picked|chose)\b/i;
  const colonMarker = /\b(answer:|result:)/i;
  if (!wordFinalMarker.test(text) && !colonMarker.test(text)) return false;

  return true;
}

const TELEMETRY_TURN_MARKER = /^\[(?:user|assistant|system)\]\s+\[(?:action|observation|state|reward|step|turn|frame)\s+\d+\]:/i;
const BARE_TELEMETRY_MARKER = /^\[(?:action|observation|state|reward|step|turn|frame)\s+\d+\]:/i;
const DURABLE_MEMORY_CUE_PHRASES = [
  "remember",
  "don't forget",
  "prefer",
  "preference",
  "decided",
  "decision",
  "deadline",
  "commitment",
  "promise",
  "my name",
  "i am",
  "i work",
  "we use",
  "correction",
  "actually",
  "always",
  "never",
  "when you",
];

export function stripRolePrefix(line: string): string {
  return line.replace(/^\[(?:user|assistant|system)\]\s+/i, "").trim();
}

export function isTelemetryMarkerLine(line: string): boolean {
  return TELEMETRY_TURN_MARKER.test(line) ||
    BARE_TELEMETRY_MARKER.test(stripRolePrefix(line));
}

export function isMechanicalTelemetryLine(line: string): boolean {
  const stripped = stripRolePrefix(line);
  return (
    isTelemetryMarkerLine(line) ||
    /^(?:left|right|up|down|wait|noop|stop|start|forward|backward)$/i.test(stripped) ||
    /^(?:active rules|objects on (?:the )?map|inventory|score|reward|position|location):?$/i.test(stripped) ||
    /^rule `[^`]+`/i.test(stripped) ||
    /^(?:[a-z][\w-]*|\w+ `[^`]+`)\s+\d+\s+steps?\s+(?:to\s+the\s+)?(?:left|right|up|down)\b/i.test(stripped)
  );
}

export function hasDurableMemoryCue(conversation: string): boolean {
  const lower = conversation.toLowerCase();
  if (DURABLE_MEMORY_CUE_PHRASES.some((phrase) => lower.includes(phrase))) {
    return true;
  }
  const ifIndex = lower.indexOf("if ");
  return ifIndex >= 0 && lower.indexOf(" then", ifIndex + 3) >= 0;
}

export function looksLikeMechanicalTelemetryTranscript(
  conversation: string,
): boolean {
  if (hasDurableMemoryCue(conversation)) return false;

  const lines = conversation
    .split(/\n+/)
    .map((line) => line.trim())
    .filter((line) => line.length > 0);
  if (lines.length < 8) return false;

  const markerLines = lines.filter((line) => isTelemetryMarkerLine(line)).length;
  if (markerLines < 4) return false;

  const mechanicalLines = lines.filter((line) => isMechanicalTelemetryLine(line)).length;
  const mechanicalRatio = mechanicalLines / lines.length;
  return mechanicalRatio >= 0.45;
}

import type { ExtractionResult, ProvenanceConfig } from "./types.js";
import { buildFactProvenance, type ProvenanceTurnInput } from "./provenance.js";
import { delinearize } from "./delinearize.js";
import {
  applyExtractionSourceGrounding as applyGroundingRules,
  filterExtractionResultBySource as filterGroundingRules,
} from "./extraction-source-grounding-rules.js";
import type {
  ExtractionGroundingRoleSources,
  ExtractionSourceGroundingOptions,
} from "./extraction-source-grounding-rules.js";

export type { ExtractionGroundingRoleSources, ExtractionSourceGroundingOptions } from "./extraction-source-grounding-rules.js";

export function applyExtractionSourceGrounding(
  result: ExtractionResult,
  sourceText: string,
  assertionSourceText: string = sourceText,
  roleAssertionSources: ExtractionGroundingRoleSources | undefined,
  messageTimestamp: Date | undefined,
  options: ExtractionSourceGroundingOptions,
): ExtractionResult {
  const sourceForGrounding = (source: string | undefined): string | undefined =>
    source === undefined || !options.anchorTemporalExpressions
      ? source
      : delinearize(source, result.entities, messageTimestamp ?? new Date());
  const groundedRoleSources = roleAssertionSources === undefined
    ? undefined
    : {
      profile: sourceForGrounding(roleAssertionSources.profile),
      identity: sourceForGrounding(roleAssertionSources.identity),
    };
  return applyGroundingRules(
    result,
    sourceForGrounding(sourceText) ?? sourceText,
    sourceForGrounding(assertionSourceText) ?? assertionSourceText,
    groundedRoleSources,
    messageTimestamp,
    { ...options, quoteTransform: (quote) => sourceForGrounding(quote) ?? quote },
  );
}

/**
 * Attach claim-level provenance spans to each fact after extraction has
 * completed. The validator never throws or drops a fact: an unverifiable
 * quote remains a tagged state. When provenance is disabled, transient
 * model-provided quotes are stripped before the result leaves extraction.
 */
export function attachExtractionProvenance(
  result: ExtractionResult,
  turns: ReadonlyArray<{
    content: string;
    sessionKey?: string;
    logicalSessionKey?: string;
    timestamp: string;
    turnFingerprint?: string;
  }>,
  provenanceConfig: ProvenanceConfig,
): ExtractionResult {
  if (!provenanceConfig.enabled) {
    if (result.facts.length === 0) return result;
    return {
      ...result,
      facts: result.facts.map((fact) => {
        if (fact.quote === undefined) return fact;
        const { quote: _stripped, ...rest } = fact;
        return rest;
      }),
    };
  }
  if (result.facts.length === 0) return result;
  const provenanceTurns: ProvenanceTurnInput[] = turns.map((turn) => ({
    content: turn.content,
    sessionKey: turn.sessionKey,
    logicalSessionKey: turn.logicalSessionKey,
    timestamp: turn.timestamp,
    turnId: turn.turnFingerprint,
  }));
  const facts = result.facts.map((fact) => {
    const built = buildFactProvenance(
      fact.quote,
      provenanceTurns,
      provenanceConfig,
    );
    const { quote: _stripped, ...factWithoutQuote } = fact;
    return {
      ...factWithoutQuote,
      ...(built.sources && built.sources.length > 0 ? { sources: built.sources } : {}),
      ...(built.provenance !== "none" ? { provenance: built.provenance } : {}),
      ...(built.requireSpansPending ? { requireSpansPending: true } : {}),
    };
  });
  return { ...result, facts };
}

export function filterExtractionResultBySource(
  result: ExtractionResult,
  source: string,
  assertionSource?: string,
  roleAssertionSources?: ExtractionGroundingRoleSources,
  eventTimeNormalizer?: (eventTime: string) => string,
  spanMode: "off" | "shadow" | "on" = "off",
  quoteTransform?: (quote: string) => string,
): ExtractionResult {
  return filterGroundingRules(
    result,
    source,
    assertionSource,
    roleAssertionSources,
    eventTimeNormalizer,
    spanMode,
    quoteTransform,
  );
}

/**
 * Source-agent qualifier helpers for extraction (#2183).
 *
 * Pure leaf module: imports only types and sibling leaf/orchestration helpers,
 * never `extraction.ts`, so it introduces no cycle (extraction-run.ts only
 * type-imports extraction.ts).
 */
import { resolvePipelineProcessingCapabilities } from "./capabilities.js";
import { applyExtractionSourceGrounding } from "./extraction-source-grounding.js";
import type { ExtractionGroundingRoleSources } from "./extraction-source-grounding.js";
import { isValidConnectorId } from "./connectors/index.js";
import { CONNECTOR_LABEL_MAX_LENGTH, knownConnectorIds } from "./connectors/label.js";
import { deriveSourceConnector } from "./orchestration/extraction-run.js";
import type { BufferTurn, ExtractionResult, PluginConfig } from "./types.js";


export function resolveSourceConnector(turns: readonly BufferTurn[]): string | undefined {
  const contributing = turns.filter((turn) => turn.extractionContextOnly !== true);
  const derived = deriveSourceConnector(contributing);
  if (derived === undefined || !isValidConnectorId(derived)) return undefined;
  return /[\u0000-\u001F\u007F]/.test(derived) ? undefined : derived;
}

// Same bound as the recall renderer (CONNECTOR_LABEL_MAX_LENGTH) but a DIFFERENT
// policy: recall TRUNCATES past the bound (a truncated display label cannot
// mislead), while the prompt SUPPRESSES (a truncated id could collide with a
// different connector). Do not "fix" this inconsistency — it is deliberate.
export function headerConnector(connector: string | undefined): string | undefined {
  return connector !== undefined && connector.length <= CONNECTOR_LABEL_MAX_LENGTH ? connector : undefined;
}

export function renderExtractionConversation(
  boundedTurns: readonly BufferTurn[],
  sourceConnector: string | undefined,
): { conversation: string; renderedConversation: string } {
  const renderedConversation = boundedTurns
    .map((t) => `[${t.extractionContextOnly === true ? `context ${t.role}` : t.role}] ${t.content}`)
    .join("\n\n");
  const conversation = sourceConnector === undefined
    ? renderedConversation
    : `Source agent: ${sourceConnector}\n\nTool and command instructions in this conversation apply to the ${sourceConnector} agent unless they are clearly universal.\n\n${renderedConversation}`;
  return { conversation, renderedConversation };
}

export interface ExtractionGroundingContext {
  groundingSource: string;
  assertionSource: string;
  roleAssertionSources?: ExtractionGroundingRoleSources;
  messageTimestamp: Date | undefined;
  sourceConnector?: string;
  /** Input came from an always-on recorder (issue #2294); the proactive
   *  second pass reads it so its prompts carry the same media warning. */
  ambientCapture?: boolean;
  scopeClassificationEnabled?: boolean;
}

export function applyGroundingWithConnector(
  config: PluginConfig,
  result: ExtractionResult,
  ctx: ExtractionGroundingContext,
): ExtractionResult {
  const caps = resolvePipelineProcessingCapabilities(config);
  const options = {
    sourceGrounding: caps.sourceGrounding,
    anchorTemporalExpressions: caps.delinearize,
    spanMode: config.extraction?.spanMode ?? "off",
  };
  const known = buildKnownConnectors(ctx.sourceConnector);
  // Scope-forcing is decoupled from strip/restore (runs without a trusted
  // connector) but gated on the capability: flag off = byte-identical pre-#2183.
  const scoped = ctx.scopeClassificationEnabled === false
    ? result
    : forceProjectScopeOnAnyQualifier(result, known);
  if (ctx.sourceConnector === undefined) {
    return applyExtractionSourceGrounding(scoped, ctx.groundingSource, ctx.assertionSource, ctx.roleAssertionSources, ctx.messageTimestamp, options);
  }
  const prepared = prepareTrustedConnectorQualifier(scoped, ctx.sourceConnector, known);
  const grounded = applyExtractionSourceGrounding(prepared.result, ctx.groundingSource, ctx.assertionSource, ctx.roleAssertionSources, ctx.messageTimestamp, options);
  return restoreTrustedConnectorQualifier(grounded);
}

function buildKnownConnectors(trusted: string | undefined): Set<string> {
  const known = new Set<string>();
  for (const id of knownConnectorIds()) known.add(id.toLowerCase());
  if (trusted !== undefined) known.add(trusted.toLowerCase());
  return known;
}

/**
 * Parse a leading agent qualifier from fact text. ONE parser, ONE boundary
 * rule, ONE case policy (case-insensitive), ONE definition of "agent" (the name
 * must be a known connector ID). Returns the matched agent and the remaining
 * text, or undefined. Both scope-forcing and strip/restore consume this single
 * result so they can never disagree (#2183 round-11).
 */
function parseLeadingQualifier(content: string, known: ReadonlySet<string>): { agent: string; rest: string } | undefined {
  const lower = content.toLowerCase();
  for (const lead of ["in ", "for "]) {
    if (!lower.startsWith(lead)) continue;
    const m = lower.slice(lead.length).match(/^([a-z0-9][a-z0-9._-]*)\s*,/u);
    if (m && known.has(m[1])) {
      const consumed = lead.length + m[0].length;
      return { agent: m[1], rest: content.slice(consumed).replace(/^[\s,.;:]+/u, "") };
    }
  }
  const pm = lower.match(/^([a-z0-9][a-z0-9._-]*)'s(?![\p{L}\p{N}])/u);
  if (pm && known.has(pm[1])) {
    return { agent: pm[1], rest: content.slice(pm[0].length).replace(/^[\s,.;:]+/u, "") };
  }
  return undefined;
}

/**
 * Force "project" scope on any fact whose content starts with a recognised
 * agent qualifier (a known connector name). A qualifier is evidence the fact is
 * agent-tied; which connector it names does not matter.
 */
function forceProjectScopeOnAnyQualifier(result: ExtractionResult, known: ReadonlySet<string>): ExtractionResult {
  let any = false;
  const facts = result.facts.map((fact) => {
    if (fact.scope === "project") return fact;
    if (parseLeadingQualifier(fact.content, known) === undefined) return fact;
    any = true;
    return { ...fact, scope: "project" as const };
  });
  return any ? { ...result, facts } : result;
}

const RESTORE_KEY = "_qo";

/**
 * Strip the TRUSTED connector's qualifier for the grounding pass. Uses the same
 * parseLeadingQualifier as scope-forcing, but only strips when the matched agent
 * IS the trusted connector. Each stripped fact carries its original content
 * positionally for collision-free restore.
 */
function prepareTrustedConnectorQualifier(
  result: ExtractionResult,
  trustedConnector: string,
  known: ReadonlySet<string>,
): { result: ExtractionResult } {
  const trusted = trustedConnector.toLowerCase();
  const facts = result.facts.map((fact) => {
    const parsed = parseLeadingQualifier(fact.content, known);
    if (parsed === undefined || parsed.agent !== trusted) return fact;
    return { ...fact, content: parsed.rest, [RESTORE_KEY]: fact.content };
  }) as ExtractionResult["facts"];
  return { result: { ...result, facts } };
}

function restoreTrustedConnectorQualifier(grounded: ExtractionResult): ExtractionResult {
  let touched = false;
  const facts = grounded.facts.map((fact) => {
    const record = fact as unknown as Record<string, unknown>;
    const original = record[RESTORE_KEY];
    if (typeof original !== "string") return fact;
    touched = true;
    const rest = { ...record };
    delete rest[RESTORE_KEY];
    return { ...rest, content: original } as ExtractionResult["facts"][number];
  });
  return touched ? { ...grounded, facts } : grounded;
}

/**
 * Sealed memory-write envelope (issue #1989, umbrella #1988).
 *
 * THE single stamping point for cross-cutting memory-creation fields.
 *
 * Why this exists: PR #1852 needed 27 rework commits because adding one
 * cross-cutting field (`sourceConnector`) required hand-editing every
 * write call site and every idempotency payload, and reviewers discovered
 * missed sites one round at a time. This module removes the fan-out:
 *
 *   1. `composeMemoryEnvelope()` is the only way to mint a
 *      `SealedMemoryEnvelope` — the brand is a non-exported `unique symbol`,
 *      so a hand-built object literal fails `tsc` (`npm run check-types`
 *      is already a required repo-wide gate; the type system IS the fence).
 *   2. `buildWriteIdempotencyPayload()` derives every access-surface
 *      idempotency payload from ONE ordered field registry
 *      (`WRITE_FINGERPRINT_FIELDS`). Adding a fingerprint-relevant field is
 *      a one-line registry change picked up by every surface; forgetting to
 *      classify a new `MemoryWriteInput` field is a compile error (see the
 *      exhaustiveness guards at the bottom of this file).
 *
 * PR1 scope (no call-site changes): the composer, the registry, and the
 * payload builder, fully tested. PR2–PR4 migrate storage entry points and
 * the write call sites onto this module (see #1989 for the slicing).
 */

import { isMemorySubject } from "./memory-subject.js";
import type { MemoryCategory, MemorySubject } from "./types.js";
import { normalizeTags } from "./recall-tag-filter.js";
import { parseFlexibleIsoTimestamp } from "./utils/iso-timestamp.js";
import { assemblePersistedBody } from "./structured-attributes.js";

// ---------------------------------------------------------------------------
// Input surface
// ---------------------------------------------------------------------------

/**
 * Every cross-cutting memory-creation field lives HERE and only here.
 *
 * When you add a field you MUST also add it to either
 * `WRITE_FINGERPRINT_FIELDS` or `FINGERPRINT_EXEMPT_FIELDS` — the
 * exhaustiveness guard below makes forgetting a compile error.
 */
export interface MemoryWriteInput {
  /** Raw memory content. Must be non-empty after trimming. */
  content: string;
  /** Memory category — validated against the canonical category set. */
  category: MemoryCategory;
  /** Free-form labels; normalized (trim/dedupe) and capped, see TAG_LIMITS. */
  tags?: string[];
  /** String→string structured attributes; non-string values are rejected. */
  structuredAttributes?: Record<string, string>;
  /** Entity file reference (e.g. `person-jane-doe`). */
  entityRef?: string;
  /** Extraction confidence in [0, 1]. */
  confidence?: number;
  /** Opaque TTL expression (e.g. `90d` or an ISO date) — validated non-empty. */
  ttl?: string;
  /** Event-time validity start (ISO 8601). */
  validAt?: string;
  /** Connector identity that produced this write (issue #1852). */
  sourceConnector?: string;
  /** Origin class stamped at creation time (issue #1955). */
  origin?: string;
  /** Whom the memory models (issue #2372): "user" or "agent". */
  subject?: MemorySubject;
  /** Human-readable provenance note. */
  sourceReason?: string;
}

/** Context supplied by the write path, not by the payload author. */
export interface WriteContext {
  /** Frontmatter `source` string (e.g. `extraction`, `wearable:bee`). */
  source: string;
  /** Clock override for tests. */
  now?: () => Date;
}

/** Scope facts that participate in idempotency but never in frontmatter. */
export interface FingerprintScope {
  /** Access surface performing the write (e.g. `memory_store`, `observe`). */
  surface: string;
  namespace?: string;
  principal?: string;
  codingContext?: string;
}

// ---------------------------------------------------------------------------
// Normalization limits (single source of truth — docs/tags.md contract)
// ---------------------------------------------------------------------------

export const TAG_LIMITS = Object.freeze({
  /** Maximum number of tags persisted per memory. */
  maxTags: 50,
  /** Maximum length of a single tag. */
  maxTagLength: 256,
});

export const STRUCTURED_ATTRIBUTE_LIMITS = Object.freeze({
  /** Maximum number of structured attributes per memory. */
  maxEntries: 64,
  /** Maximum length of one attribute key. */
  maxKeyLength: 128,
  /** Maximum length of one attribute value. */
  maxValueLength: 1024,
});

const MEMORY_CATEGORY_TABLE: Record<MemoryCategory, true> = {
  fact: true,
  preference: true,
  correction: true,
  entity: true,
  decision: true,
  relationship: true,
  principle: true,
  commitment: true,
  moment: true,
  skill: true,
  rule: true,
  procedure: true,
  reasoning_trace: true,
};

/**
 * Canonical category spellings, sorted. Runtime counterpart of the
 * `MemoryCategory` union for error messages and cross-module consistency
 * checks (issue #2829).
 */
export const MEMORY_CATEGORY_NAMES = Object.keys(MEMORY_CATEGORY_TABLE).sort();

export function isMemoryCategory(value: string): value is MemoryCategory {
  return Object.prototype.hasOwnProperty.call(MEMORY_CATEGORY_TABLE, value);
}

// ---------------------------------------------------------------------------
// Sealed envelope
// ---------------------------------------------------------------------------

declare const sealed: unique symbol;

/**
 * A normalized, validated memory-write envelope.
 *
 * Opaque: only `composeMemoryEnvelope()` can mint one. Storage creation
 * entry points accept this type (PR2), so every write path is forced
 * through the composer at compile time.
 */
export interface SealedMemoryEnvelope {
  readonly [sealed]: true;
  /**
   * Caller-supplied content VERBATIM (validated non-empty-after-trim).
   * `StorageManager.writeMemory` persists content byte-for-byte (callers
   * that trim, e.g. explicit capture, do so before composing), so the
   * envelope must not transform it — the earlier compose-time trim/sanitize
   * broke byte-parity with extraction writes and was removed in PR2.
   */
  readonly content: string;
  /**
   * The exact body persistence will write: attribute-suffix enrichment then
   * combined sanitization, produced by the SAME `assemblePersistedBody`
   * helper `writeMemory` uses (issue #1989 PR2; AGENTS.md §13). This is the
   * form write-idempotency fingerprints hash.
   */
  readonly persistedBody: string;
  /** Injection patterns matched during body assembly (empty = clean). */
  readonly sanitizeViolations: readonly string[];
  /**
   * Salvage-mode hygiene notes (empty in strict mode): each dropped/clamped
   * invalid optional field is recorded here — visible, never silent
   * (repo rule 34). Callers persisting machine-generated input log these.
   */
  readonly salvageNotes: readonly string[];
  readonly category: MemoryCategory;
  readonly tags: readonly string[];
  /**
   * CANONICAL attributes (keys trim+lowercase, values trim) — the form
   * fingerprints and downstream consumers use; stable across caller casing.
   */
  readonly structuredAttributes: Readonly<Record<string, string>> | undefined;
  /**
   * The validated ORIGINAL attribute map, byte-preserved. `writeMemory`
   * persists frontmatter attributes raw (canonicalizing only the body
   * suffix via normalizeAttributePairs) — a pre-existing raw/canonical
   * inconsistency (supersession keys read the raw form). The sealed path
   * preserves those bytes; canonicalizing the frontmatter at the storage
   * boundary is a follow-up once the legacy path retires (#1989 PR4).
   */
  readonly rawStructuredAttributes: Readonly<Record<string, string>> | undefined;
  readonly entityRef: string | undefined;
  readonly confidence: number | undefined;
  readonly ttl: string | undefined;
  readonly validAt: string | undefined;
  readonly sourceConnector: string | undefined;
  readonly origin: string | undefined;
  readonly subject: MemorySubject | undefined;
  readonly sourceReason: string | undefined;
  readonly source: string;
  /** ISO timestamp the envelope was composed (from ctx.now). */
  readonly composedAt: string;
}

function fail(field: string, message: string): never {
  throw new Error(`composeMemoryEnvelope: ${field} ${message}`);
}

/**
 * Compose-time input hygiene mode (issue #1989 PR2, review round on #2014).
 *
 * - `strict` (default): every invalid field throws — correct for OPERATOR
 *   and API input (explicit capture, memory_store), where a bad value is a
 *   caller bug that must surface.
 * - `salvage`: for MACHINE-GENERATED input (LLM extraction, wearable
 *   ingestion). One malformed fact from an extractor must not abort a whole
 *   persistence batch that legacy `writeMemory` would have accepted.
 *   Invalid tags/attributes/optional fields are DROPPED with a note pushed
 *   to `envelope.salvageNotes` — visible, never silent (repo rule 34);
 *   callers log the notes. Content, category, ctx.source, and validAt stay
 *   FATAL in both modes (legacy writeMemory also throws on bad validAt, and
 *   a write without valid content/category cannot proceed).
 */
export interface ComposeEnvelopeOptions {
  salvage?: boolean;
}

/** Internal reporter: throws in strict mode, records a note in salvage. */
interface Hygiene {
  salvage: boolean;
  notes: string[];
  flag(field: string, message: string): void;
}

function makeHygiene(salvage: boolean): Hygiene {
  const notes: string[] = [];
  return {
    salvage,
    notes,
    flag(field: string, message: string): void {
      if (!salvage) fail(field, message);
      notes.push(`${field} ${message}`);
    },
  };
}

/**
 * Validate and CANONICALIZE `validAt` via the repo's shared flexible ISO
 * parser (`utils/iso-timestamp.ts`) — the same family durable writes use, so
 * the envelope can never accept a value storage would reject or reinterpret
 * (review findings on #1998: no second validation convention; reduced
 * precision like `2026-07-17T09:30Z` is valid; offsets are bounded ±14:00;
 * `Date.parse` alone is not an ISO validator).
 *
 * Canonical form is the epoch round-trip (`Date.toISOString()`), so
 * fingerprints are identical for `...T09:30Z`, `...T09:30:00.000Z`, and the
 * same instant expressed with an offset (§13 hash-consistency).
 */
function validateIsoTimestamp(field: string, value: string): string {
  const trimmed = value.trim();
  if (trimmed.length === 0) fail(field, "must be a non-empty ISO 8601 timestamp");
  const epochMs = parseFlexibleIsoTimestamp(trimmed);
  if (epochMs === null) {
    fail(
      field,
      `is not a valid ISO 8601 date/timestamp: ${JSON.stringify(value)} (date-only, reduced precision, Z, and ±HH:MM offsets up to ±14:00 are accepted; calendar overflow is not)`,
    );
  }
  return new Date(epochMs).toISOString();
}

function normalizeEnvelopeTags(raw: string[] | undefined, hygiene: Hygiene): readonly string[] {
  if (raw === undefined) return Object.freeze([]);
  if (!Array.isArray(raw)) {
    hygiene.flag("tags", "must be an array of strings — dropped");
    return Object.freeze([]);
  }
  const usable: string[] = [];
  for (const tag of raw) {
    if (typeof tag !== "string") {
      hygiene.flag("tags", `entries must be strings (got ${typeof tag})`);
      continue;
    }
    if (tag.trim().length > TAG_LIMITS.maxTagLength) {
      hygiene.flag("tags", `entry exceeds ${TAG_LIMITS.maxTagLength} characters: ${JSON.stringify(tag.slice(0, 40))}…`);
      continue;
    }
    usable.push(tag);
  }
  let normalized = normalizeTags(usable) ?? [];
  if (normalized.length > TAG_LIMITS.maxTags) {
    hygiene.flag("tags", `exceed the ${TAG_LIMITS.maxTags}-tag limit (got ${normalized.length}) — keeping the first ${TAG_LIMITS.maxTags}`);
    normalized = normalized.slice(0, TAG_LIMITS.maxTags);
  }
  return Object.freeze(normalized);
}

function normalizeStructuredAttributes(
  raw: Record<string, string> | undefined,
  hygiene: Hygiene,
): { canonical: Readonly<Record<string, string>>; raw: Readonly<Record<string, string>> } | undefined {
  if (raw === undefined) return undefined;
  if (
    raw === null ||
    typeof raw !== "object" ||
    Array.isArray(raw) ||
    (Object.getPrototypeOf(raw) !== Object.prototype && Object.getPrototypeOf(raw) !== null)
  ) {
    // Map/Date/class instances have empty Object.entries() and would
    // silently normalize to "no attributes" (review finding on #1998
    // round 5) — never a plain pass-through.
    hygiene.flag("structuredAttributes", "must be a plain object of string values (Map, Date, and class instances are rejected) — dropped");
    return undefined;
  }
  let entries = Object.entries(raw);
  if (entries.length === 0) return undefined;
  if (entries.length > STRUCTURED_ATTRIBUTE_LIMITS.maxEntries) {
    hygiene.flag(
      "structuredAttributes",
      `exceed the ${STRUCTURED_ATTRIBUTE_LIMITS.maxEntries}-entry limit (got ${entries.length}) — keeping the first ${STRUCTURED_ATTRIBUTE_LIMITS.maxEntries} in insertion order`,
    );
    entries = entries.slice(0, STRUCTURED_ATTRIBUTE_LIMITS.maxEntries);
  }
  // Keys that collide with Object.prototype machinery are REJECTED outright:
  // `hashAccessIdempotencyPayload`'s stableStringify rebuilds objects with
  // plain assignment, where a "__proto__" own property silently vanishes —
  // so such a key can never round-trip through the fingerprint faithfully
  // (review finding on #1998 round 3). Rejection beats smuggling (§1/§39).
  const FORBIDDEN_ATTRIBUTE_KEYS = ["__proto__", "constructor", "prototype"];
  const out: Record<string, string> = Object.create(null);
  const survivingOriginal: Array<[string, string]> = [];
  for (const [key, value] of entries) {
    // Canonicalize exactly like storage's normalizeAttributePairs
    // (storage.ts:1277): keys trim+lowercase, values trim — so the
    // fingerprint and the persisted searchable form can never diverge
    // (review finding on #1998; AGENTS.md §13 hash-consistency).
    const cleanKey = key.trim().toLowerCase();
    if (cleanKey.length === 0) {
      hygiene.flag("structuredAttributes", "contain an empty key");
      continue;
    }
    if (cleanKey.length > STRUCTURED_ATTRIBUTE_LIMITS.maxKeyLength) {
      hygiene.flag("structuredAttributes", `key exceeds ${STRUCTURED_ATTRIBUTE_LIMITS.maxKeyLength} characters: ${JSON.stringify(cleanKey.slice(0, 40))}…`);
      continue;
    }
    if (typeof value !== "string") {
      hygiene.flag("structuredAttributes", `value for ${JSON.stringify(cleanKey)} must be a string (got ${typeof value}) — stringify numbers/booleans at the call site`);
      continue;
    }
    const cleanValue = value.trim();
    if (FORBIDDEN_ATTRIBUTE_KEYS.includes(cleanKey)) {
      hygiene.flag(
        "structuredAttributes",
        `contain the reserved key ${JSON.stringify(cleanKey)} — prototype-machinery names cannot round-trip through fingerprint serialization`,
      );
      continue;
    }
    if (cleanValue.length > STRUCTURED_ATTRIBUTE_LIMITS.maxValueLength) {
      hygiene.flag("structuredAttributes", `value for ${JSON.stringify(cleanKey)} exceeds ${STRUCTURED_ATTRIBUTE_LIMITS.maxValueLength} characters`);
      continue;
    }
    if (Object.hasOwn(out, cleanKey)) {
      hygiene.flag("structuredAttributes", `contain duplicate key after canonicalization (trim + lowercase): ${JSON.stringify(cleanKey)}`);
      continue;
    }
    out[cleanKey] = cleanValue;
    survivingOriginal.push([key, value]);
  }
  if (Object.keys(out).length === 0) return undefined;
  // Copy onto a normal object so downstream JSON/stableStringify behavior is
  // unchanged; keys are already validated. The RAW map carries only the
  // SURVIVING original pairs — dropped entries must not reach frontmatter.
  return {
    canonical: Object.freeze({ ...out }),
    raw: Object.freeze(Object.fromEntries(survivingOriginal)),
  };
}

function normalizeOptionalString(
  field: string,
  value: string | undefined,
  hygiene: Hygiene,
): string | undefined {
  if (value === undefined) return undefined;
  if (typeof value !== "string") {
    hygiene.flag(field, `must be a string (got ${typeof value}) — dropped`);
    return undefined;
  }
  const trimmed = value.trim();
  if (trimmed.length === 0) {
    hygiene.flag(field, "must be non-empty when provided — dropped");
    return undefined;
  }
  return trimmed;
}

/**
 * Compose (normalize + validate + seal) a memory-write envelope.
 *
 * Strict mode (default) throws on any invalid input — never silently
 * defaults (AGENTS.md §1/§39). Salvage mode (`{ salvage: true }`, for
 * machine-generated input like LLM extraction) drops invalid OPTIONAL
 * fields with notes on `envelope.salvageNotes` instead of aborting the
 * batch; content/category/source/validAt stay fatal in both modes.
 */
export function composeMemoryEnvelope(
  input: MemoryWriteInput,
  ctx: WriteContext,
  opts: ComposeEnvelopeOptions = {},
): SealedMemoryEnvelope {
  if (input === null || typeof input !== "object") fail("input", "must be an object");
  if (ctx === null || typeof ctx !== "object") fail("ctx", "must be an object");
  const hygiene = makeHygiene(opts.salvage === true);

  if (typeof input.content !== "string" || input.content.trim().length === 0) {
    fail("content", "must be a non-empty string");
  }
  if (typeof input.category !== "string" || !isMemoryCategory(input.category)) {
    fail(
      "category",
      `must be one of: ${MEMORY_CATEGORY_NAMES.join(", ")} (got ${JSON.stringify(input.category)})`,
    );
  }
  if (typeof ctx.source !== "string" || ctx.source.trim().length === 0) {
    fail("ctx.source", "must be a non-empty string");
  }

  let confidence: number | undefined;
  if (input.confidence !== undefined) {
    if (
      typeof input.confidence !== "number" ||
      !Number.isFinite(input.confidence) ||
      input.confidence < 0 ||
      input.confidence > 1
    ) {
      hygiene.flag(
        "confidence",
        `must be a finite number within [0, 1] (got ${String(input.confidence)}) — dropped (storage defaults apply)`,
      );
    } else {
      confidence = input.confidence;
    }
  }

  let subject: MemorySubject | undefined;
  if (input.subject !== undefined) {
    if (!isMemorySubject(input.subject)) {
      hygiene.flag(
        "subject",
        `must be "user" or "agent" (got ${JSON.stringify(input.subject)}) — dropped`,
      );
    } else {
      subject = input.subject;
    }
  }

  // validAt stays FATAL in salvage too: legacy writeMemory throws on an
  // invalid validAt (normalizeMemoryWriteTimestamp), so salvage-dropping it
  // would CHANGE behavior rather than preserve it.
  const validAt =
    input.validAt === undefined ? undefined : validateIsoTimestamp("validAt", input.validAt);

  const now = ctx.now ? ctx.now() : new Date();
  if (!(now instanceof Date) || Number.isNaN(now.getTime())) {
    fail("ctx.now", "must return a valid Date");
  }

  const attributes = normalizeStructuredAttributes(input.structuredAttributes, hygiene);
  // Assemble the EXACT persisted form (attribute suffix + combined sanitize)
  // with the same helper writeMemory uses — fingerprints hash this form, so
  // envelope and storage cannot diverge (§13; #1998 round-8 thread resolved
  // here in PR2 as promised). writeMemory assembles from the RAW map;
  // normalizeAttributePairs canonicalizes internally, so raw and canonical
  // maps yield the same suffix — asserted by the parity suite.
  const assembled = assemblePersistedBody(
    input.content,
    attributes ? { ...attributes.raw } : undefined,
  );
  if (assembled.text.trim().length === 0) {
    fail("content", "is empty after sanitization");
  }

  const body = {
    content: input.content,
    persistedBody: assembled.text,
    sanitizeViolations: Object.freeze([...assembled.violations]),
    category: input.category,
    tags: normalizeEnvelopeTags(input.tags, hygiene),
    structuredAttributes: attributes?.canonical,
    rawStructuredAttributes: attributes?.raw,
    entityRef: normalizeOptionalString("entityRef", input.entityRef, hygiene),
    origin: normalizeOptionalString("origin", input.origin, hygiene),
    subject,
    confidence,
    ttl: normalizeOptionalString("ttl", input.ttl, hygiene),
    validAt,
    sourceConnector: normalizeOptionalString("sourceConnector", input.sourceConnector, hygiene),
    sourceReason: normalizeOptionalString("sourceReason", input.sourceReason, hygiene),
    source: ctx.source.trim(),
    composedAt: now.toISOString(),
    salvageNotes: Object.freeze([...hygiene.notes]),
  };
  const envelope = Object.freeze(body) as unknown as SealedMemoryEnvelope;
  SEALED_ENVELOPES.add(envelope);
  return envelope;
}

// The runtime seal registry. The declared `sealed` unique symbol exists only
// at the type level (compile-time fence); this WeakSet is the runtime fence.
const SEALED_ENVELOPES = new WeakSet<object>();

/**
 * TOCTOU guard for the structural arm (#2014 round 4): a frozen object may
 * still carry ACCESSOR properties whose getters return different values on
 * each read — valid data during re-composition, forged data when the write
 * path reads the field again. Frozen DATA properties are immutable, so
 * requiring data-only descriptors (on the envelope and its array/map
 * fields) makes every later read provably identical to the validated one.
 */
function hasOnlyFrozenDataProperties(value: object): boolean {
  if (!Object.isFrozen(value)) return false;
  // Inherited accessors are as dangerous as own ones (round 5): a frozen
  // object can inherit a `tags` getter from a custom prototype. Composer
  // envelopes are plain object literals and plain arrays — require exactly
  // those prototypes so prototype-supplied getters cannot serve fields.
  const proto = Object.getPrototypeOf(value);
  if (Array.isArray(value)) {
    if (proto !== Array.prototype) return false;
  } else if (proto !== Object.prototype && proto !== null) {
    return false;
  }
  for (const key of Reflect.ownKeys(value)) {
    const descriptor = Object.getOwnPropertyDescriptor(value, key);
    if (!descriptor || descriptor.get !== undefined || descriptor.set !== undefined) {
      return false;
    }
  }
  return true;
}

/**
 * Runtime check (belt) — the compile-time brand is the real fence.
 *
 * Fast path: WeakSet membership (same module graph). Fallback: RE-COMPOSITION
 * EQUIVALENCE — Node resolves `@remnic/core` through `dist/` for built
 * consumers and `src/` for tsx-loaded tests, and each graph gets its OWN
 * WeakSet, so identity alone would reject genuinely-sealed envelopes that
 * crossed a build boundary. The structural arm requires frozen DATA-only
 * properties (no accessors — TOCTOU guard, round 4), then re-runs the
 * STRICT composer on the candidate's own inputs and demands every envelope
 * field reproduce exactly (#2014 round 2: shape-only validation admitted
 * lookalikes with 51 tags or out-of-range confidence). A value that
 * survives has, by construction, passed every composer invariant, and its
 * fields cannot change between validation and the write that follows.
 *
 * `salvageNotes` is deliberately NOT compared: a legitimately salvage-minted
 * envelope carries notes while the strict re-composition of its (already
 * clean) surviving fields yields none. Notes are advisory provenance, not
 * identity — every load-bearing field is still verified.
 */

export function isSealedMemoryEnvelope(value: unknown): value is SealedMemoryEnvelope {
  if (typeof value !== "object" || value === null) return false;
  if (SEALED_ENVELOPES.has(value)) return true;
  if (!hasOnlyFrozenDataProperties(value)) return false;
  const v = value as Partial<SealedMemoryEnvelope>;
  if (
    typeof v.content !== "string" ||
    typeof v.persistedBody !== "string" ||
    typeof v.source !== "string" ||
    typeof v.composedAt !== "string" ||
    typeof v.category !== "string" ||
    !isMemoryCategory(v.category) ||
    !Array.isArray(v.tags) ||
    !hasOnlyFrozenDataProperties(v.tags) ||
    !Array.isArray(v.sanitizeViolations) ||
    !hasOnlyFrozenDataProperties(v.sanitizeViolations) ||
    !Array.isArray(v.salvageNotes) ||
    !hasOnlyFrozenDataProperties(v.salvageNotes)
  ) {
    return false;
  }
  const attrs = v.rawStructuredAttributes;
  if (
    attrs !== undefined &&
    (attrs === null || typeof attrs !== "object" || Array.isArray(attrs) || !hasOnlyFrozenDataProperties(attrs))
  ) {
    return false;
  }
  const canonicalAttrs = v.structuredAttributes;
  if (
    canonicalAttrs !== undefined &&
    (canonicalAttrs === null ||
      typeof canonicalAttrs !== "object" ||
      Array.isArray(canonicalAttrs) ||
      !hasOnlyFrozenDataProperties(canonicalAttrs))
  ) {
    return false;
  }
  let rebuilt: SealedMemoryEnvelope;
  try {
    rebuilt = composeMemoryEnvelope(
      {
        content: v.content,
        category: v.category,
        ...(v.tags.length > 0 ? { tags: [...(v.tags as string[])] } : {}),
        ...(attrs !== undefined ? { structuredAttributes: { ...attrs } } : {}),
        ...(v.entityRef !== undefined ? { entityRef: v.entityRef } : {}),
        ...(v.confidence !== undefined ? { confidence: v.confidence } : {}),
        ...(v.ttl !== undefined ? { ttl: v.ttl } : {}),
        ...(v.validAt !== undefined ? { validAt: v.validAt } : {}),
        ...(v.sourceConnector !== undefined ? { sourceConnector: v.sourceConnector } : {}),
        ...(v.origin !== undefined ? { origin: v.origin } : {}),
        ...(v.sourceReason !== undefined ? { sourceReason: v.sourceReason } : {}),
      },
      { source: v.source, now: () => new Date(v.composedAt as string) },
    );
  } catch {
    // Strict re-composition rejected an input — the candidate carries a
    // value the composer would never have minted.
    return false;
  }
  const sameArray = (a: readonly string[], b: readonly string[]): boolean =>
    a.length === b.length && a.every((entry, i) => entry === b[i]);
  const sameMap = (
    a: Readonly<Record<string, string>> | undefined,
    b: Readonly<Record<string, string>> | undefined,
  ): boolean => {
    if (a === undefined || b === undefined) return a === b;
    const ak = Object.keys(a);
    const bk = Object.keys(b);
    return ak.length === bk.length && ak.every((k) => Object.hasOwn(b, k) && a[k] === b[k]);
  };
  return (
    rebuilt.content === v.content &&
    rebuilt.persistedBody === v.persistedBody &&
    rebuilt.category === v.category &&
    rebuilt.source === v.source &&
    rebuilt.composedAt === v.composedAt &&
    rebuilt.confidence === v.confidence &&
    rebuilt.entityRef === v.entityRef &&
    rebuilt.ttl === v.ttl &&
    rebuilt.validAt === v.validAt &&
    rebuilt.sourceConnector === v.sourceConnector &&
    rebuilt.origin === v.origin &&
    rebuilt.sourceReason === v.sourceReason &&
    sameArray(rebuilt.tags, v.tags as string[]) &&
    sameArray(rebuilt.sanitizeViolations, v.sanitizeViolations as string[]) &&
    sameMap(rebuilt.structuredAttributes, v.structuredAttributes) &&
    sameMap(rebuilt.rawStructuredAttributes, attrs)
  );
}

/**
 * The ONE mapping from a sealed envelope (+ extras) to the legacy
 * `writeMemory(category, content, options)` argument shape. Used by
 * `StorageManager.writeSealedMemory` AND by test doubles that stub storage —
 * so mock fidelity (AGENTS.md §21) cannot drift from production.
 */
export function sealedWriteToLegacyArgs(
  envelope: SealedMemoryEnvelope,
  extras: Record<string, unknown> = {},
): { category: MemoryCategory; content: string; options: Record<string, unknown> } {
  return {
    category: envelope.category,
    content: envelope.content,
    options: {
      ...extras,
      confidence: envelope.confidence,
      tags: envelope.tags.length > 0 ? [...envelope.tags] : undefined,
      entityRef: envelope.entityRef,
      source: envelope.source,
      expiresAt: envelope.ttl,
      validAt: envelope.validAt,
      // RAW map for frontmatter byte-parity with the legacy path; the body
      // suffix canonicalizes identically from either form.
      structuredAttributes: envelope.rawStructuredAttributes
        ? { ...envelope.rawStructuredAttributes }
        : undefined,
      // Unconditional (round 3): envelope-owned fields must ALWAYS overwrite
      // extras — a conditional spread let extras.sourceConnector smuggle
      // unvalidated connector provenance past the sealed envelope when the
      // envelope had none.
      origin: envelope.origin,
      sourceConnector: envelope.sourceConnector,
      subject: envelope.subject,
    },
  };
}

// ---------------------------------------------------------------------------
// Idempotency field registry
// ---------------------------------------------------------------------------

/**
 * Ordered registry of envelope fields that participate in write-idempotency
 * fingerprints. Adding a fingerprint-relevant field = one entry here; every
 * surface that builds its payload via `buildWriteIdempotencyPayload()` picks
 * it up automatically.
 */
export const WRITE_FINGERPRINT_FIELDS = [
  "content",
  "category",
  "tags",
  "structuredAttributes",
  "entityRef",
  "ttl",
  "validAt",
  "sourceConnector",
] as const satisfies readonly (keyof MemoryWriteInput)[];

/**
 * Envelope fields deliberately EXCLUDED from fingerprints. Exempting a field
 * is a visible, reviewable decision — this list exists so the exhaustiveness
 * guard can force every new `MemoryWriteInput` field to be classified.
 */
export const FINGERPRINT_EXEMPT_FIELDS = [
  // Confidence is a scoring detail: two extractions of the same fact with
  // slightly different confidence are the same write for dedup purposes.
  "confidence",
  // Free-text provenance note; carries no identity.
  // Origin is provenance metadata, not write identity (#1955).
  "origin",
  // Subject is derived classification metadata (#2372): two writes identical
  // except subject are the same memory for dedup purposes.
  "subject",
  "sourceReason",
] as const satisfies readonly (keyof MemoryWriteInput)[];

/** Scope keys always folded into the fingerprint payload. */
export const FINGERPRINT_SCOPE_FIELDS = [
  "surface",
  "namespace",
  "principal",
  "codingContext",
] as const satisfies readonly (keyof FingerprintScope)[];

// --- compile-time exhaustiveness guards ------------------------------------
// A new MemoryWriteInput field that is in NEITHER list is a compile error;
// a registry entry that names a non-existent field is a compile error; a
// field in BOTH lists is a compile error.

type RegistryField = (typeof WRITE_FINGERPRINT_FIELDS)[number];
type ExemptField = (typeof FINGERPRINT_EXEMPT_FIELDS)[number];
type UnclassifiedField = Exclude<keyof MemoryWriteInput, RegistryField | ExemptField>;
type DoublyClassifiedField = RegistryField & ExemptField;

const assertEveryFieldClassified: UnclassifiedField extends never ? true : never = true;
const assertNoDoubleClassification: DoublyClassifiedField extends never ? true : never = true;
void assertEveryFieldClassified;
void assertNoDoubleClassification;

// ---------------------------------------------------------------------------
// Payload builder
// ---------------------------------------------------------------------------

/**
 * Build the canonical write-idempotency payload for a sealed envelope.
 *
 * Determinism guarantees (AGENTS.md §26):
 *   - tags are SORTED in the payload (tag order never changes identity);
 *   - structured attributes are serialized key-sorted by the existing
 *     `stableStringify` inside `hashAccessIdempotencyPayload`;
 *   - the payload shape is versioned (`v: 1`) so a future field-semantics
 *     change can migrate stored idempotency state explicitly instead of
 *     silently colliding.
 *
 * Feed the result to `hashAccessIdempotencyPayload()` — this module does
 * not hash so surfaces keep a single hashing implementation.
 */
export function buildWriteIdempotencyPayload(
  envelope: SealedMemoryEnvelope,
  scope: FingerprintScope,
): Record<string, unknown> {
  if (!isSealedMemoryEnvelope(envelope)) {
    throw new Error(
      "buildWriteIdempotencyPayload: envelope must be minted by composeMemoryEnvelope",
    );
  }
  if (scope === null || typeof scope !== "object") {
    throw new Error("buildWriteIdempotencyPayload: scope must be an object");
  }
  if (typeof scope.surface !== "string" || scope.surface.trim().length === 0) {
    throw new Error("buildWriteIdempotencyPayload: scope.surface must be a non-empty string");
  }

  const fields: Record<string, unknown> = {};
  for (const field of WRITE_FINGERPRINT_FIELDS) {
    const value = envelope[field];
    if (value === undefined) continue;
    if (field === "tags") {
      const tags = value as readonly string[];
      if (tags.length === 0) continue;
      fields.tags = [...tags].sort();
      continue;
    }
    if (field === "content") {
      // Fingerprints hash the PERSISTED form (attribute suffix + combined
      // sanitize), not the raw input — one instant of stored state, one
      // fingerprint (§13; issue #1989 PR2).
      fields.content = envelope.persistedBody;
      continue;
    }
    fields[field] = value;
  }
  // The write source (extraction vs wearable:bee vs observe replay, ...) is
  // identity: the same content arriving from two different sources must not
  // dedupe into one write (review finding on #1998). Not a MemoryWriteInput
  // key, so it rides beside the registry fields explicitly.
  fields.source = envelope.source;

  const scopeOut: Record<string, string> = {};
  for (const key of FINGERPRINT_SCOPE_FIELDS) {
    const value = scope[key];
    if (value === undefined) continue;
    if (typeof value !== "string") {
      throw new Error(`buildWriteIdempotencyPayload: scope.${key} must be a string`);
    }
    // Trimmed: "ns" and "ns " must not mint distinct fingerprints (review
    // finding on #1998). Empty-after-trim optional scope values are dropped.
    const cleanValue = value.trim();
    if (key === "surface" || cleanValue.length > 0) {
      scopeOut[key] = cleanValue;
    }
  }

  return { v: 1, kind: "memory-write", fields, scope: scopeOut };
}

// ---------------------------------------------------------------------------
// Access-surface request fingerprints (issue #1989 PR3)
// ---------------------------------------------------------------------------
//
// The access surfaces (memory_store / suggestion_submit writes, their peek
// twins, and observe) key their idempotency dedup on a hash of the RAW
// request — computed BEFORE validation, and persisted indefinitely in
// `AccessIdempotencyStore` (last-512 LRU, no time TTL). Those stored hashes
// are load-bearing state: changing the payload shape would silently break
// replay/conflict detection for every in-flight key. So these builders
// REPRODUCE each surface's historical shape byte-for-byte (asserted by the
// parity suite) instead of adopting the versioned envelope payload above —
// a versioned migration of stored state is the explicit prerequisite for
// unifying them (#1989 PR3 scope note).
//
// What centralizing buys even under byte-parity: one module now owns every
// fingerprint shape, and the compile-time assertion below ties the write
// shape to WRITE_FINGERPRINT_FIELDS — adding a fingerprint-relevant field
// to MemoryWriteInput fails compilation here until the author decides how
// the access surfaces represent it.

/** The raw request fields the write surfaces fingerprint (legacy shape). */
export interface AccessWriteFingerprintParts {
  schemaVersion: number;
  namespace: string;
  content: string;
  category?: string;
  confidence?: number;
  tags?: string[];
  entityRef?: string;
  ttl?: string;
  sourceReason?: string;
  sourceConnector?: string;
}

// Registry coupling: every fingerprint-relevant MemoryWriteInput field must
// either appear in AccessWriteFingerprintParts or be named in this explicit
// exemption list. `structuredAttributes` and `validAt` are exempt because
// the access write requests cannot express them today (ExplicitCaptureInput
// has no such fields) — the moment they become representable, this type
// stops compiling and forces a fingerprint decision (+ versioned state
// migration) instead of a silent dedup gap.
type AccessSurfaceUnrepresentable = "structuredAttributes" | "validAt";
type UncoveredAccessFingerprintField = Exclude<
  Extract<RegistryField, keyof MemoryWriteInput>,
  keyof AccessWriteFingerprintParts | AccessSurfaceUnrepresentable
>;
const assertAccessFingerprintCoversRegistry: UncoveredAccessFingerprintField extends never
  ? true
  : never = true;
void assertAccessFingerprintCoversRegistry;

/**
 * Fingerprint payload for `memory_store` / `suggestion_submit` (write AND
 * peek paths — both MUST call this so peek can never diverge from the
 * write it predicts). Key set and values reproduce the historical inline
 * literals exactly; `hashAccessIdempotencyPayload`'s stableStringify sorts
 * keys and drops `undefined`, so optional absent fields hash identically
 * to the old shape.
 */
export function buildAccessWriteRequestFingerprint(
  parts: AccessWriteFingerprintParts,
): Record<string, unknown> {
  return {
    schemaVersion: parts.schemaVersion,
    content: parts.content,
    category: parts.category,
    confidence: parts.confidence,
    namespace: parts.namespace,
    tags: parts.tags,
    entityRef: parts.entityRef,
    ttl: parts.ttl,
    sourceReason: parts.sourceReason,
    sourceConnector: parts.sourceConnector,
  };
}

/** The raw request fields the observe surface fingerprints (legacy shape). */
export interface ObserveFingerprintParts {
  sessionKey: string;
  messages: unknown;
  namespace?: string;
  skipExtraction?: boolean;
  authenticatedPrincipal?: string;
  cwd?: string;
  projectTag?: string;
  /** Resolved coding context — `null` (not undefined) when absent, matching the historical literal. */
  effectiveCodingContext: unknown;
  sourceConnector?: string;
}

/**
 * Fingerprint payload for `observe` — turn ingestion, not a memory write,
 * so it fingerprints session/message identity rather than MemoryWriteInput
 * fields. Shape reproduces the historical inline literal exactly.
 */
export function buildObserveRequestFingerprint(
  parts: ObserveFingerprintParts,
): Record<string, unknown> {
  return {
    sessionKey: parts.sessionKey,
    messages: parts.messages,
    namespace: parts.namespace,
    skipExtraction: parts.skipExtraction,
    authenticatedPrincipal: parts.authenticatedPrincipal,
    cwd: parts.cwd,
    projectTag: parts.projectTag,
    effectiveCodingContext: parts.effectiveCodingContext,
    sourceConnector: parts.sourceConnector,
  };
}

/**
 * Local fine-tuned model endpoint resolver + openai-compatible caller
 * (issue #1585 model-lab integration).
 *
 * Remnic's two classification workloads — the extraction faithfulness gate
 * (#1576) and passive-correction intent detection (#1581) — can run on small
 * fine-tuned models served locally (Ollama / vLLM) instead of prompted
 * frontier LLMs. The model-lab (`model-lab/`) produces those models; this
 * module is the config-side half: it resolves the optional local endpoint
 * pointer from config and, when set, makes a minimal openai-compatible
 * chat-completions call to it.
 *
 * Design:
 *   - **Pointers are optional.** Empty defaults preserve the existing routing
 *     chain exactly (rule 39 / byte-identical pre-feature). A resolver returns
 *     `null` when the pointer is unset, so callers short-circuit before any
 *     network.
 *   - **Graceful degradation.** A local-endpoint failure (network, non-2xx,
 *     malformed body, timeout) returns `null`; callers fall back to the
 *     configured chain (checklist §4 — never block writes on a classifier).
 *   - **No inline casts.** The fetch JSON is narrowed with `in` / `typeof`
 *     guards (project rule: never assert a shape to read one property).
 *   - **Injectable fetch.** `callOpenAiCompatibleChat` takes an optional
 *     `fetchImpl` so the caller is unit-testable without a live server.
 */

import type { PluginConfig } from "./types.js";

/** A resolved local endpoint: where to call + which model to name. */
export interface LocalModelEndpoint {
  /** Base URL, e.g. `http://localhost:11434/v1` (no trailing slash required). */
  baseUrl: string;
  /** Model name the server expects, e.g. `remnic-faithfulness-gate-v1`. */
  model: string;
}

/** A chat message in the openai-compatible shape this caller sends. */
export interface EndpointChatMessage {
  role: "system" | "user" | "assistant";
  content: string;
}

/** Options for a single local-endpoint chat call. */
export interface EndpointChatOptions {
  /** Per-call timeout in ms. Bounds each attempt so one slow server can't
   *  starve the batch (matches the local-LLM precedent). */
  timeoutMs: number;
  /** Optional batch AbortSignal forwarded into the probe (issue #1700 nit #5).
   *  When the batch budget elapses (or the caller aborts), the in-flight probe
   *  aborts immediately instead of waiting for its own `timeoutMs` — a
   *  micro-optimization, not a correctness fix (the outer race already bounds
   *  the total). Undefined preserves the prior per-attempt-only behavior. */
  signal?: AbortSignal;
  /** Sampling temperature — classification wants low entropy (0.0–0.2). */
  temperature?: number;
  /** Max output tokens. */
  maxTokens?: number;
  /** Request JSON-object output (the gate emits a JSON verdict array). */
  responseFormatJson?: boolean;
}

/** Result of a local-endpoint chat call. */
export interface EndpointChatResult {
  content: string;
  /** The model the server reports it used (falls back to the requested name). */
  modelUsed: string;
}

/**
 * Resolve the faithfulness-gate local endpoint from config (issue #1585).
 *
 * Returns the endpoint only when BOTH a base URL and a model name are
 * configured; otherwise `null` (gate uses its existing routing chain). The
 * gate's verifier needs a model identity, so a base URL alone is intentionally
 * insufficient — silently calling whatever the server's default model is would
 * be an unreviewed behavioral change.
 */
export function resolveFaithfulnessGateEndpoint(
  config: Pick<PluginConfig, "extractionFaithfulnessModel" | "extractionFaithfulnessBaseUrl">,
): LocalModelEndpoint | null {
  const baseUrl = config.extractionFaithfulnessBaseUrl.trim();
  const model = config.extractionFaithfulnessModel.trim();
  if (!baseUrl || !model) return null;
  return { baseUrl, model };
}

/**
 * Resolve the correction-intent local endpoint from config (issue #1581/#1585).
 *
 * Same contract as the gate resolver. Consumption by the model-backed
 * detector is the consuming child's job — the rule-based
 * `detectPassiveCorrections` remains the default path; this pointer lets a
 * future model-backed detector route to a fine-tuned local classifier when an
 * operator configures one.
 */
export function resolveCorrectionIntentEndpoint(
  config: Pick<PluginConfig, "correctionIntentModel" | "correctionIntentBaseUrl">,
): LocalModelEndpoint | null {
  const baseUrl = config.correctionIntentBaseUrl.trim();
  const model = config.correctionIntentModel.trim();
  if (!baseUrl || !model) return null;
  return { baseUrl, model };
}

type FetchLike = typeof fetch;

/**
 * Make an openai-compatible chat-completions call to a local endpoint.
 *
 * POSTs to `${baseUrl}/chat/completions` with `{ model, messages, ... }` and
 * returns the first choice's content. Any failure (non-2xx, network error,
 * malformed body, timeout) returns `null` so callers fall back gracefully.
 *
 * The response is narrowed with runtime guards — never an unchecked cast — so
 * a surprising server response fails closed (`null`) rather than reading a
 * fabricated field.
 */
export async function callOpenAiCompatibleChat(
  endpoint: LocalModelEndpoint,
  messages: EndpointChatMessage[],
  options: EndpointChatOptions,
  fetchImpl: FetchLike = fetch,
): Promise<EndpointChatResult | null> {
  const url = joinBaseUrl(endpoint.baseUrl, "/chat/completions");
  const controller = new AbortController();
  const timer = setTimeout(() => controller.abort(), options.timeoutMs);
  // Forward the batch AbortSignal into the probe (issue #1700 nit #5): if the
  // batch budget already elapsed, abort the in-flight probe immediately rather
  // than waiting for the probe's own timeoutMs. AbortSignal.any is ES2024
  // (forbidden here); wire the listener manually + guard the already-aborted
  // case. The fetch still uses the probe's controller, so clearing the timer
  // below is the only cleanup needed.
  const batchSignal = options.signal;
  const onBatchAbort = () => controller.abort();
  if (batchSignal) {
    if (batchSignal.aborted) {
      controller.abort();
    } else {
      batchSignal.addEventListener("abort", onBatchAbort, { once: true });
    }
  }
  try {
    const body: Record<string, unknown> = {
      model: endpoint.model,
      messages,
      temperature: options.temperature ?? 0.1,
    };
    if (typeof options.maxTokens === "number") {
      body.max_tokens = options.maxTokens;
    }
    if (options.responseFormatJson) {
      body.response_format = { type: "json_object" };
    }
    let response: Response;
    try {
      response = await fetchImpl(url, {
        method: "POST",
        headers: { "content-type": "application/json" },
        body: JSON.stringify(body),
        signal: controller.signal,
      });
    } catch {
      // Network error or abort — fail closed, let the caller fall back.
      return null;
    }
    if (!response.ok) return null;
    const parsed: unknown = await response.json().catch(() => null);
    const content = extractFirstChoiceContent(parsed);
    if (content === null) return null;
    return { content, modelUsed: extractModel(parsed) ?? endpoint.model };
  } finally {
    clearTimeout(timer);
    if (batchSignal) batchSignal.removeEventListener("abort", onBatchAbort);
  }
}

/** Join a base URL and a path, tolerating a trailing slash on the base. */
function joinBaseUrl(base: string, path: string): string {
  return base.endsWith("/") ? `${base.slice(0, -1)}${path}` : `${base}${path}`;
}

/**
 * Narrow the openai-compatible response and pull the first choice's content.
 *
 * `in` / `typeof` guards only — no `as` cast (project rule). Returns `null`
 * for any shape that isn't `{ choices: [{ message: { content: string } }, …] }`.
 */
function extractFirstChoiceContent(data: unknown): string | null {
  if (!data || typeof data !== "object") return null;
  // After `in`, TS narrows the property to `unknown` — read it directly, no cast.
  if (!("choices" in data) || !Array.isArray(data.choices)) return null;
  const choices: unknown[] = data.choices;
  for (const choice of choices) {
    if (!choice || typeof choice !== "object") continue;
    if (!("message" in choice)) continue;
    const message = choice.message;
    if (!message || typeof message !== "object") continue;
    if (!("content" in message)) continue;
    const content = message.content;
    if (typeof content === "string" && content.length > 0) return content;
  }
  return null;
}

/** Narrow the `model` field from the response (best-effort, may be absent). */
function extractModel(data: unknown): string | null {
  if (!data || typeof data !== "object" || !("model" in data)) return null;
  const model = data.model;
  return typeof model === "string" && model.length > 0 ? model : null;
}

/**
 * Extraction seam for span mode (issue #2333 leftover slice + #2952).
 *
 * Default off. Callers pass `enabled` to `applySpanMode`. The provider JSON
 * schema is mode-aware so off-mode structured output cannot advertise `span`.
 */

import { z } from "zod";
import type { ExtractionSpanConfig } from "./extraction-span-config.js";
import { parseSpanOffsets, type ParsedSpan } from "./extraction-span.js";
import { ExtractionProviderOutputSchema } from "./schemas.js";

export function applySpanMode(opts: {
  enabled?: boolean | 0 | 1;
  text: string;
  start: number;
  end: number;
}): ParsedSpan {
  return parseSpanOffsets(opts.text, { start: opts.start, end: opts.end }, opts.enabled);
}

/** The parts of a JSON Schema node the extraction schema uses. */
type SchemaNode = {
  type?: string;
  properties?: Record<string, SchemaNode>;
  items?: SchemaNode;
  anyOf?: SchemaNode[];
  additionalProperties?: boolean | SchemaNode;
};

/**
 * `io: "input"` leaves objects open (zod accepts extra input keys), but providers
 * must be told to emit no extra keys: zod-to-json-schema advertised
 * additionalProperties:false on every object. Close any object schema that
 * does not already state its own.
 */
function closeObjectSchemas(node: SchemaNode): SchemaNode {
  if (node.type === "object" && node.properties && node.additionalProperties === undefined) {
    node.additionalProperties = false;
  }
  Object.values(node.properties ?? {}).forEach(closeObjectSchemas);
  if (node.items) closeObjectSchemas(node.items);
  node.anyOf?.forEach(closeObjectSchemas);
  return node;
}

// zod 4 ships toJSONSchema natively; zod-to-json-schema emits an empty
// document for v4 schemas, so the dependency is dropped here. `io: "input"`
// matches the old effectStrategy: "input" (advertise the input shape of
// transforms/preprocess to providers).
// SAFETY: z.toJSONSchema returns a JSON-Schema document — always an object at
// the root; the record shape is what omitFactSpan walks.
const EXTRACTION_PROVIDER_JSON_SCHEMA_WITH_SPAN: SchemaNode = closeObjectSchemas(
  // SAFETY: z.toJSONSchema returns a JSON Schema document; SchemaNode names the keys this file reads.
  z.toJSONSchema(ExtractionProviderOutputSchema, { target: "draft-7", io: "input" }) as SchemaNode,
);
type FactItems = {
  properties?: Record<string, unknown>;
  required?: string[];
};

function omitFactSpan(schema: Record<string, unknown>): Record<string, unknown> {
  const clone = structuredClone(schema) as {
    properties?: { facts?: { items?: FactItems } };
  };
  const items = clone.properties?.facts?.items;
  if (!items?.properties || !("span" in items.properties)) {
    throw new Error("extraction provider schema is missing facts.items.properties.span");
  }
  delete items.properties.span;
  if (Array.isArray(items.required)) {
    items.required = items.required.filter((key) => key !== "span");
  }
  return clone as Record<string, unknown>;
}

const EXTRACTION_PROVIDER_JSON_SCHEMA_WITHOUT_SPAN = omitFactSpan(
  EXTRACTION_PROVIDER_JSON_SCHEMA_WITH_SPAN,
);

/** Provider JSON schema: `span` is present in on/shadow, absent in off. */
export function extractionProviderJsonSchema(
  spanMode: ExtractionSpanConfig["spanMode"] = "off",
): Record<string, unknown> {
  return spanMode === "off"
    ? EXTRACTION_PROVIDER_JSON_SCHEMA_WITHOUT_SPAN
    : EXTRACTION_PROVIDER_JSON_SCHEMA_WITH_SPAN;
}

export function extractionProviderResponseFormat(spanMode: ExtractionSpanConfig["spanMode"] = "off") {
  return {
    type: "json_schema" as const,
    json_schema: {
      name: "extraction_result",
      schema: extractionProviderJsonSchema(spanMode),
      strict: false,
    },
  };
}

/**
 * Span-mode materialization for production extraction (issue #2333 Phase B).
 *
 * Runs immediately after the extraction result is parsed and BEFORE
 * sanitize/grounding/judge/dedup/persistence, so everything downstream sees
 * exactly one content form and the content-hash dedup invariant (checklist
 * §13) holds by construction. Offsets die here — nothing offset-based is
 * stored.
 *
 * Modes:
 * - "off":    spans are never requested; a stray span is stripped untrusted.
 * - "shadow": spans are requested alongside full content; materialization
 *             runs for comparison only, the generated content is persisted
 *             unchanged (zero behavior change), agreement telemetry logged.
 * - "on":     materialized frame+span content is persisted; per-fact fail-open
 *             to the generated content (the frame) on any validation failure.
 *
 * Validation (identical to the Phase A bench contract):
 * - `0 <= charStart < charEnd <= turn.text.length`, end-exclusive, integers;
 * - slice length <= 400 chars and non-whitespace;
 * - frame 1..15 words;
 * - the turn text's stamp (sha256 + length of the exact in-memory string the
 *   model saw) must verify — offset drift is rejected, never guessed around.
 */

import { log } from "./logger.js";
import { stampSpanSource, verifySpanSource, type SpanSourceStamp } from "./extraction-span-source-hash.js";
import { validateSpanOffsets } from "./extraction-span-validate.js";
import { sliceSpanText } from "./extraction-span-slice.js";
import type { ExtractionResult } from "./types.js";
import type { ExtractedFactSpanRef } from "./extraction-span-config.js";

export const SPAN_MAX_SLICE_CHARS = 400;
export const SPAN_MAX_FRAME_WORDS = 15;

export type SpanMode = "off" | "shadow" | "on";

/** A source turn exactly as rendered into the extraction prompt. */
export interface SpanMaterializeTurn {
  text: string;
  stamp: SpanSourceStamp;
}

export interface SpanMaterializeFact {
  content: string;
  span?: ExtractedFactSpanRef | null;
  quote?: string;
}

export interface SpanMaterializeTelemetry {
  /** Facts that carried a span ref. */
  attempts: number;
  /** Spans that failed validation and fell back to generated content. */
  fallbacks: number;
  /** Shadow mode only: comparisons made / exact-or-containment agreements. */
  shadowComparisons: number;
  shadowAgreements: number;
}

/** Strip span refs from facts that were never given the span prompt
 * (e.g. the proactive second pass). Untrusted: never validated, never used.
 * The key is omitted entirely so no `span: undefined` reaches persistence. */
export function stripUntrustedFactSpans<T extends { span?: unknown }>(facts: readonly T[]): T[] {
  return facts.map((fact) => {
    if (fact.span === undefined || fact.span === null) return fact;
    const { span: _span, ...rest } = fact;
    return rest as T;
  });
}

export function buildSpanMaterializeTurns(texts: readonly string[]): SpanMaterializeTurn[] {
  return texts.map((text) => ({ text, stamp: stampSpanSource(text) }));
}

export function truncateLocalExtractionConversation(
  conversation: string,
  maxConversationChars: number,
): string {
  return conversation.length > maxConversationChars
    ? `${conversation.slice(0, maxConversationChars)}\n\n[truncated]`
    : conversation;
}

export function bindLocalExtractionPrompt(
  conversation: string,
  turns: readonly { role: string; content: string; extractionContextOnly?: boolean }[],
  maxConversationChars: number,
  renderedConversation: string = conversation,
): { promptConversation: string; spanTurns: SpanMaterializeTurn[] } {
  const promptConversation = truncateLocalExtractionConversation(conversation, maxConversationChars);
  if (conversation.length <= maxConversationChars || !conversation.endsWith(renderedConversation)) {
    return { promptConversation, spanTurns: buildSpanMaterializeTurns(turns.map((turn) => turn.content)) };
  }
  const renderedStart = conversation.length - renderedConversation.length;
  const limit = maxConversationChars;
  const texts: string[] = [];
  let pos = 0;
  for (let index = 0; index < turns.length; index += 1) {
    const turn = turns[index];
    if (turn === undefined) {
      texts.push("");
      continue;
    }
    if (index > 0) pos += 2;
    const label = turn.extractionContextOnly === true ? `context ${turn.role}` : turn.role;
    pos += `[${label}] `.length;
    const absStart = renderedStart + pos;
    const absEnd = absStart + turn.content.length;
    texts.push(absEnd > absStart && limit > absStart ? conversation.slice(absStart, Math.min(absEnd, limit)) : "");
    pos += turn.content.length;
  }
  return { promptConversation, spanTurns: buildSpanMaterializeTurns(texts) };
}

export function factCarriesSpan(fact: { span?: ExtractedFactSpanRef | null }): boolean {
  return fact.span !== undefined && fact.span !== null;
}

/**
 * Materialize one fact's span. Never throws: any validation failure falls
 * open to the fact's generated content and is counted.
 */
export function materializeFactSpan<T extends SpanMaterializeFact>(
  fact: T,
  turns: readonly SpanMaterializeTurn[],
  mode: SpanMode,
): { fact: T; outcome: "span" | "fallback"; materialized?: string } {
  const span = fact.span ?? null;
  if (span === null) {
    return { fact, outcome: "fallback" };
  }
  const { sourceMessageIndex, charStart, charEnd, frame, sourceHash, sourceLength } = span;
  const turn = turns[sourceMessageIndex];
  if (
    !Number.isInteger(sourceMessageIndex) ||
    sourceMessageIndex < 0 ||
    sourceMessageIndex >= turns.length ||
    turn === undefined
  ) {
    return { fact: stripSpan(fact), outcome: "fallback" };
  }
  const stampCheck = verifySpanSource(turn.text, turn.stamp);
  if (!stampCheck.ok) {
    return { fact: stripSpan(fact), outcome: "fallback" };
  }
  if (
    (sourceHash !== undefined && sourceHash !== turn.stamp.hash) ||
    (sourceLength !== undefined && sourceLength !== turn.stamp.length)
  ) {
    return { fact: stripSpan(fact), outcome: "fallback" };
  }
  const offsetCheck = validateSpanOffsets({ start: charStart, end: charEnd, textLength: turn.text.length });
  if (!offsetCheck.ok) {
    return { fact: stripSpan(fact), outcome: "fallback" };
  }
  const slice = sliceSpanText({ text: turn.text, start: charStart, end: charEnd });
  if (slice.length > SPAN_MAX_SLICE_CHARS || slice.trim().length === 0) {
    return { fact: stripSpan(fact), outcome: "fallback" };
  }
  const frameWords = frame.trim().split(/\s+/).filter(Boolean);
  if (frameWords.length === 0 || frameWords.length > SPAN_MAX_FRAME_WORDS) {
    return { fact: stripSpan(fact), outcome: "fallback" };
  }

  const trimmedFrame = frameWords.join(" ");
  const materialized = /[:—-]$/.test(trimmedFrame)
    ? `${trimmedFrame} ${slice}`
    : `${trimmedFrame}: ${slice}`;

  if (mode === "on") {
    return {
      fact: { ...stripSpan(fact), content: materialized, quote: slice },
      outcome: "span",
      materialized,
    };
  }
  // shadow: persist generated content unchanged; materialize for comparison.
  return { fact: stripSpan(fact), outcome: "span", materialized };
}

/** Shadow agreement: exact match or containment either way. */
export function spanAgreesWithContent(materialized: string, content: string): boolean {
  const left = materialized.trim();
  const right = content.trim();
  return left === right || left.includes(right) || right.includes(left);
}

/**
 * Whole-result span materialization pass (issue #2333 Phase B). Called from
 * `ExtractionEngine.applySpanMaterialization` after parse, before sanitize /
 * grounding / judge / dedup / persist. "off" strips stray spans untrusted.
 * Shadow logs agreement telemetry and persists generated content. "on"
 * persists materialized frame+span content; facts that omit the optional
 * span are dropped so a short frame cannot persist as a standalone memory.
 */
export function applyExtractionSpanMaterialization(
  result: ExtractionResult,
  turns: readonly SpanMaterializeTurn[],
  mode: SpanMode,
): ExtractionResult {
  if (mode === "off") {
    return { ...result, facts: stripUntrustedFactSpans(result.facts) };
  }
  let attempts = 0;
  let fallbacks = 0;
  let agreements = 0;
  const facts = result.facts.flatMap((fact) => {
    if (!factCarriesSpan(fact)) {
      return mode === "on" ? [] : [fact];
    }
    attempts += 1;
    const { fact: materialized, outcome, materialized: text } = materializeFactSpan(
      fact,
      turns,
      mode,
    );
    if (outcome === "fallback") {
      fallbacks += 1;
    } else if (mode === "shadow" && text !== undefined) {
      if (spanAgreesWithContent(text, fact.content)) {
        agreements += 1;
      }
    }
    return [materialized];
  });
  if (mode === "shadow") {
    log.info(
      `extraction span-mode shadow: ${agreements}/${attempts} span facts agree with generated content (${fallbacks} span validation fallbacks)`,
    );
  } else if (fallbacks > 0) {
    log.info(
      `extraction span-mode: ${fallbacks}/${attempts} span facts fell back to generated content`,
    );
  }
  return { ...result, facts };
}

function stripSpan<T extends SpanMaterializeFact>(fact: T): T {
  const { span: _span, ...rest } = fact;
  return rest as T;
}

import type { ExtractionFailureClass } from "./types.js";
import { isTransientHttpError } from "./connectors/live/transient-errors.js";

/**
 * Read a numeric HTTP status off a thrown error without re-implementing the
 * shared transient classifier. Uses `in`/typeof narrowing (no inline casts).
 */
function httpStatusFromError(err: unknown): number | undefined {
  if (!err || typeof err !== "object") return undefined;
  if ("status" in err && typeof err.status === "number" && Number.isFinite(err.status)) return err.status;
  if ("statusCode" in err && typeof err.statusCode === "number" && Number.isFinite(err.statusCode)) {
    return err.statusCode;
  }
  return undefined;
}

/**
 * Map a thrown extraction error to a coarse failure class for the retry/breaker
 * layer. 401/403 → `auth_config` (misconfigured provider, open the breaker);
 * transient (429/5xx/network, per the shared `isTransientHttpError`) → back off;
 * anything else defaults to `provider_retryable` (fail-open toward retry, but
 * capped by the per-fingerprint attempt budget). Never throws.
 */
export function classifyExtractionThrownError(err: unknown): ExtractionFailureClass {
  try {
    const status = httpStatusFromError(err);
    if (status === 401 || status === 403) return "auth_config";
    if (isTransientHttpError(err)) return "provider_retryable";
    return "provider_retryable";
  } catch {
    return "provider_retryable";
  }
}

/**
 * Map the gateway fallback's discriminated parse-failure reason to a coarse
 * extraction failure class. "no models configured" is an auth/config problem;
 * an HTTP/transport failure backs off; an unparseable-but-present response is a
 * genuine empty-parse.
 */
export function classifyFallbackParseFailure(
  reason: "no_models" | "empty" | "http_error" | "schema_rejection" | "timeout",
): ExtractionFailureClass {
  switch (reason) {
    case "no_models":
      return "auth_config";
    case "http_error":
    case "timeout":
      return "provider_retryable";
    case "empty":
    case "schema_rejection":
      return "parse_empty";
  }
}

/**
 * Operator-visible extraction parse-failure line. Keeps the historical
 * greppable prefix and appends the fields that used to live only at debug.
 */
export function formatExtractionParseFailureLog(input: {
  failureReason: string;
  attemptedModel?: string;
  httpStatus?: number;
  errorClass?: string;
  traceId: string;
}): string {
  const modelUsed =
    typeof input.attemptedModel === "string" && input.attemptedModel.length > 0
      ? input.attemptedModel
      : "unknown";
  const errorClass =
    typeof input.errorClass === "string" && input.errorClass.length > 0
      ? input.errorClass
      : "none";
  const httpStatus =
    typeof input.httpStatus === "number" && Number.isFinite(input.httpStatus)
      ? String(input.httpStatus)
      : "none";
  return [
    "extraction fallback returned no parsed output",
    `failureReason=${input.failureReason}`,
    `modelUsed=${modelUsed}`,
    `errorClass=${errorClass}`,
    `httpStatus=${httpStatus}`,
    `traceId=${input.traceId}`,
  ].join(" ");
}

/**
 * The local endpoint answered, and what it said rejects this input (unusable content, or a client error that is not
 * auth, timeout or rate limiting): the chunk's problem, not an outage. Retried like an empty parse, and a trigger-drain
 * chunk that keeps drawing it is dropped after its recovery copy is saved.
 */
export class LocalLlmRejectedError extends Error {
  constructor(readonly httpStatus?: number) {
    super(httpStatus === undefined ? "local LLM answered with unusable content" : `local LLM rejected the input (HTTP ${httpStatus})`);
    this.name = "LocalLlmRejectedError";
  }
}

/** What the local client recorded about a failed call (`failureDiag`). */
export interface LocalFailureDiag {
  lastError?: unknown;
}

/** The HTTP status when the local endpoint answered and refuses this input (400, 413, 422); else undefined. A wrong model name or route (404, 405, 410), auth, timeout and rate limiting are the setup's problem, not the chunk's. */
export function localRejectionStatus(diag: LocalFailureDiag): number | undefined {
  const status = httpStatusFromError(diag.lastError);
  return status !== undefined && [400, 413, 422].includes(status) ? status : undefined;
}

/**
 * Extraction prompt construction (issue #1995 sibling extraction).
 *
 * The system prompt, its JSON response shape, and the placeholder table
 * derived from that shape are prompt DATA, not engine behavior. They live here
 * so `extraction.ts` holds the pipeline and one module owns the text every
 * extraction path — local LLM, direct client, gateway fallback — sends.
 */

import { AMBIENT_CAPTURE_PROMPT_SECTION, AMBIENT_SPECULATIVE_TIER_CLAUSE } from "./ambient-provenance.js";
import { resolveMemoryLifecycleCapabilities, resolveRecallAuxiliaryCapabilities } from "./capabilities.js";
import type { PluginConfig } from "./types.js";

export const EXTRACTION_RESPONSE_SHAPE = `{
  "facts": [{
    "category": "<category>",
    "content": "<source-grounded statement>",
    "confidence": 0.0,
    "tags": ["<tag>"],
    "entityRef": "<optional normalized-name>",
    "cueAnchors": [{"type": "<anchor-type>", "value": "<entity-or-topic plus key aspect>"}],
    "promptedByQuestion": "<optional source-grounded question>",
    "quote": "<optional exact contiguous source span>",
    "scope": "<optional project-or-global>",
    "subject": "<optional user-or-agent>",
    "structuredAttributes": {"<key>": "<value>"},
    "procedureSteps": [{"order": 1, "intent": "<step>"}, {"order": 2, "intent": "<step>"}],
    "reasoningTrace": {
      "steps": [{"order": 1, "description": "<step>"}, {"order": 2, "description": "<step>"}],
      "finalAnswer": "<answer>",
      "observedOutcome": "<optional outcome>"
    },
    "eventTime": "<optional source temporal expression>"
  }],
  "entities": [{
    "name": "<normalized-name>",
    "type": "<entity-type>",
    "facts": ["<source-grounded statement>"],
    "promptedByQuestion": "<optional source-grounded question>",
    "structuredSections": [{"key": "<section-key>", "title": "<section-title>", "facts": ["<source-grounded statement>"]}]
  }],
  "profileUpdates": ["<source-grounded profile update>"],
  "questions": [{"question": "<source-grounded unresolved question>", "context": "<source-grounded context>", "priority": 0.0}],
  "identityReflection": "<conversation-grounded agent reflection>",
  "episodeTitle": "<six-to-eight word conversation segment title>",
  "relationships": [{"source": "<normalized-name>", "target": "<normalized-name>", "label": "<source-grounded relationship>"}]
}`;
export function extractionResponseShape(spanMode: "off" | "shadow" | "on" = "off"): string {
  if (spanMode === "off") return EXTRACTION_RESPONSE_SHAPE;
  return EXTRACTION_RESPONSE_SHAPE.replace(
    `"eventTime": "<optional source temporal expression>"`,
    `"eventTime": "<optional source temporal expression>",
    "span": {"sourceMessageIndex": <message number>, "charStart": <number>, "charEnd": <number>, "frame": "<at most 15 words>"}`,
  );
}
export const EXTRACTION_RESPONSE_PLACEHOLDERS: Record<string, true> = {};
for (const shape of [EXTRACTION_RESPONSE_SHAPE, extractionResponseShape("on")]) {
  for (const placeholder of shape.match(/<[^<>\r\n]+>/g) ?? []) {
    EXTRACTION_RESPONSE_PLACEHOLDERS[placeholder] = true;
  }
}
export const CUE_ANCHOR_PROMPT_INSTRUCTION = `- For each fact, emit at most 3 "cueAnchors".
- Each cue anchor value must be a source-grounded search hook of at most 120 characters, in the form "<main entity or topic> <key aspect>".
- Set each cue anchor type to entity, file, tool, outcome, constraint, or date.
- Omit cue anchors when the conversation does not support a useful search hook.
- Example: "Alice booked Bistro Max for Mike's surprise party" can use {"type":"entity","value":"Mike surprise party"} and {"type":"entity","value":"Alice restaurant booking"}.`;

/**
 * Output-language policy (issue #2190). Every prompt that produces memory
 * content embeds this verbatim so non-English conversations are not silently
 * translated to English — translated memories fail later lexical recall.
 */
export const OUTPUT_LANGUAGE_POLICY = `Output language: write facts, profile updates, entity names and aliases, tags, questions, and any rewritten or merged memory content in the source language of the conversation or input memories. Never translate into English or another language unless the user explicitly asked for a translation.`;

/**
 * Bi-temporal event-time extraction instruction (#1578 PR2). Emitted on
 * every extraction entry path when `temporal.biTemporal` is on so the LLM
 * emits an optional per-fact `eventTime` expression. The expression is
 * resolved against the source turn timestamp at write time — never
 * wall-clock — so replay/import of old transcripts anchors correctly.
 * Returns an empty string when the gate is off (byte-identical prompt).
 */
export function eventTimePromptInstruction(config: PluginConfig): string {
  if (!config.temporalBiTemporal) return "";
  return `
When a fact states when it became or stopped being true, copy that explicit temporal expression verbatim into "eventTime". Omit "eventTime" when no such expression appears; never infer dates.`;
}

/**
 * Span-mode extraction instructions (issue #2333 Phase B). Empty when the
 * mode is off (byte-identical prompt). The offset convention mirrors the
 * Phase A bench: messages numbered in order from 0, offsets index the
 * message's own text (after the `[role] ` tag), [charStart, charEnd)
 * end-exclusive.
 */
export function spanModePromptSection(spanMode: "off" | "shadow" | "on"): string {
  if (spanMode === "off") return "";
  const requestBoth = spanMode === "shadow";
  return `
Span mode (numbered-message offsets):
- Conversation messages are numbered in order starting at 0 (the "[role] text" blocks).
- For each fact, return "span": {"sourceMessageIndex": <message number>, "charStart": <number>, "charEnd": <number>, "frame": "<at most 15 words>"} pointing at the verbatim supporting words in that message's text (the text after the "] "). Offsets are [charStart, charEnd), end-exclusive, counting from the first character of the message text.
- "frame" is at most 15 generated words that make the span self-contained: resolve pronouns to names, name the subject (e.g., frame "Maya's relocation:" + span "moved to Seattle last spring…").${
    requestBoth
      ? `
- This run is in SHADOW mode: ALSO include the full standalone "content" restatement exactly as you would normally write it, in addition to "span".`
      : `
- Set "content" to the frame text (the short ≤15-word frame) — do not restate the full fact; the span plus frame carry it.`
  }
- Invalid spans fall back to the frame, so keep the frame informative.`;
}

/**
 * Build extraction instructions shared between local and cloud LLM.
 *
 * `ambientCapture` marks input from an always-on recorder, which may carry
 * speech the user never authored (issue #2294).
 */
export function buildExtractionInstructions(
  config: PluginConfig,
  existingEntities?: string[],
  ambientCapture = false
): string {
  const lifecycleCaps = resolveMemoryLifecycleCapabilities(config);
  return `You are a memory extraction system. Analyze the following conversation and extract durable, reusable memories.

Memory categories:
- fact: Objective information about the world
- preference: User likes, dislikes, or stylistic choices
- correction: User correcting a mistake or misconception (highest priority)
- entity: Information about a specific person, project, tool, or company
- decision: A choice that was made with rationale
- relationship: How two entities relate to each other (e.g., "Alice is Bob's manager", "Acme Corp uses Shopify")
- principle: Durable rules, values, or operating beliefs (e.g., "never use Chat Completions API")
- commitment: Promises, obligations, or deadlines (e.g., "deploy by Friday", "call accountant Monday")
- moment: Emotionally significant events or milestones (e.g., "first successful deployment of engram")
- skill: Capabilities the user or agent has demonstrated (e.g., "user is proficient with Kubernetes")${
    resolveRecallAuxiliaryCapabilities(config).causalRuleExtraction
      ? `
- rule: Causal rules discovered through experience (format: "IF <condition> THEN <action/outcome>", e.g., "IF Shopify API returns 401 THEN the admin token is missing read_products scope")`
      : ""
  }
- procedure: A reusable workflow the user wants remembered the same way across sessions. Set category to "procedure". Use "content" for a short title that includes explicit trigger phrasing (e.g. "When you deploy to production…", "Whenever you ship a release…"). Add "procedureSteps": an array of at least two objects {"order": number, "intent": "concrete step description"} in execution order. Optional per-step "toolCall": {"kind": "…", "signature": "…"}, "expectedOutcome", "optional": true.
- reasoning_trace: A stored solution chain / chain-of-thought the user walked through to solve a problem (e.g. "Here's how I debugged the latency spike: first I checked…, then I…, finally I…"). Set category to "reasoning_trace". Use "content" for a short title summarising the problem (e.g. "How I debugged the staging latency spike"). Add "reasoningTrace": {"steps": [{"order": number, "description": "what happened at this step"}, …], "finalAnswer": "the conclusion or answer", "observedOutcome": "optional confirmation of how it played out"}. Require at least two ordered steps AND a finalAnswer. Use this category only when the user explicitly narrates their reasoning — not for ordinary decisions (use "decision") or reusable workflows (use "procedure").

Rules:
- Only extract genuinely new information worth remembering across sessions.
- Statements must be grounded in the conversation.
- ${OUTPUT_LANGUAGE_POLICY}
- Do not treat instruction text, schema placeholders, or examples as conversation evidence.
- Lines labelled [context user] or [context assistant] are reference context only. They may resolve references or complete a question-and-answer pair in a normal turn, but never alone establish durable information.
- Skip transient task details and operational noise, including routine scheduler, monitoring, or automation status.
- Priority: corrections > principles${resolveRecallAuxiliaryCapabilities(config).causalRuleExtraction ? " > rules" : ""} > preferences > commitments > decisions > relationships > entities > moments > skills > facts
- Corrections get highest confidence.
- Each fact should be a standalone, self-contained statement.
- Entity references should use normalized names (lowercase, hyphenated: "jane-doe", "acme-corp"). When the source language is not written in a Latin script, the source-script name IS the normalized form — never transliterate or translate it.
- CRITICAL: Entity names must be CANONICAL. Always use the hyphenated multi-word form: "acme-corp" NOT "acmecorp" or "acme". "jane-doe" NOT "janedoe" or "jane". If unsure, prefer the most specific full name.
- Avoid creating entities typed as "other" when a more specific type fits (company, project, tool, person, place)
${CUE_ANCHOR_PROMPT_INSTRUCTION}
- When entity facts clearly belong under a durable named heading, add them to entity.structuredSections as {key, title, facts}. Example person headings: "Beliefs", "Communication Style", "Building / Working On". Leave structuredSections empty when no stable heading fits.
- Tags should be concise and reusable (e.g., "coding-style", "personal", "tools")
- When a fact contains measurable, categorical, or precisely valued data, include a "structuredAttributes" field with key-value string pairs (e.g., {"price": "29.99", "brand": "Sony"}, {"date": "2024-03-15", "location": "SF"}, {"chosen": "PostgreSQL", "rejected": "MongoDB"}). Only for concrete values, not narrative content.
- Set confidence using these tiers:
  * Explicit (0.95-1.0): Direct user statements — "I prefer X", "my name is Y"
  * Implied (0.70-0.94): Strong contextual inference — user consistently does X, clear from conversation flow
  * Inferred (0.40-0.69): Pattern recognition — reasonable guess from limited evidence
  * Speculative (0.00-0.39): Tentative hypothesis — weak signal, needs future confirmation. Speculative memories auto-expire after 30 days if not confirmed.${ambientCapture ? AMBIENT_SPECULATIVE_TIER_CLAUSE : ""}${
    config.provenance?.enabled
      ? `
- Source quotes: For each fact, include a "quote" field containing the EXACT verbatim words from the conversation that support the fact. Copy a contiguous span from a single speaker turn (not a paraphrase, not a summary). Cap at ~300 characters. This grounds every memory in the literal utterance that created it.`
      : ""
  }
- For commitments: include any deadline or timeframe mentioned${
    lifecycleCaps.extractionScopeClassification
      ? `

Scope classification:
For each fact, set "scope" to one of:
- "global" — knowledge that applies across projects: core framework/library bugs, API behavior patterns, user preferences (editor, language, style), general coding patterns, infrastructure knowledge, technology facts not tied to one codebase
- "project" — knowledge specific to one codebase: file paths, environment configs, deployment details, project-specific workarounds, team/stakeholder info tied to one project, repo-specific conventions. Tool, command, or CLI-flag instructions TIED TO ONE AGENT are also "project", because the same tool name means different things in different agent integrations (a "search" tool may search repository code in one agent and the web in another); when keeping such an agent-tied instruction, the fact text MUST name the originating agent as a leading "In <agent>," clause (e.g. "In Pi, use the search tool with a repository path."). A tool/command fact that holds in every agent and every repo is NOT agent-tied — leave it "global" and do not add a qualifier (e.g. "\`git status --short\` emits compact output"). Examples: "In Pi, the search tool takes a repository path" -> "project"; "\`git status --short\` emits compact output" -> "global".
When in doubt, prefer "project" — it is safer to keep knowledge scoped narrowly.`
      : ""
  }
${
  ambientCapture
    ? `${AMBIENT_CAPTURE_PROMPT_SECTION}
`
    : ""
}
Entity creation rules (STRICT):
- Only create entities for DURABLE things: real people, companies, products, tools, ongoing projects
- NEVER create entities for transient items: individual PRs, branches, Jira tickets, meetings, agent task IDs, log files, database tables, cron job runs, sessions
- When you learn something about a transient item (e.g., PR #58 fixed a bug), store it as a FACT with an entityRef to the parent project — do NOT create an entity for the PR itself
- Prefer attaching facts to broad parent entities rather than creating sub-entities. E.g., "acme-store uses Algolia for search" is a fact on entity "acme-store", NOT a new entity "acme-store-algolia-connector"
- The entity list should be SHORT — think "things that would have their own Wikipedia page" not "things mentioned in passing"

${
  existingEntities && existingEntities.length > 0
    ? `
KNOWN ENTITIES (use these exact names when referencing existing things):
${existingEntities.join(", ")}

When you see something that matches a known entity, use THAT name exactly. Only create a NEW entity if nothing in this list represents it.
`
    : ""
}
${eventTimePromptInstruction(config)}${spanModePromptSection(config.extraction?.spanMode ?? "off")}
Also extract relationships between entities mentioned in the conversation.
- Format: {source: "entity-name", target: "entity-name", label: "relationship description"}
- Max 5 relationships per extraction
- Only include clear, durable relationships (e.g., "works at", "created", "manages", "uses")
- Use normalized entity names (e.g., "person-jane-doe", "company-acme-corp")


Also emit "episodeTitle" as a six-to-eight word title for this conversation segment.
Questions are optional. Include only source-grounded unresolved questions that would be useful in future sessions; otherwise return an empty array.

Finally, write a brief identity reflection about the agent who had this conversation, based only on the conversation. Do not write about the extraction process.`;
}

export const CONSOLIDATION_RESPONSE_SCHEMA = `{
  "items": [
    {
      "existingId": "id",
      "action": "ADD",
      "mergeWith": "optional-existing-id",
      "updatedContent": "optional replacement content",
      "reason": "brief reason for this action"
    }
  ],
  "profileUpdates": ["optional profile update"],
  "entityUpdates": [{"name": "person-jane-doe", "type": "person", "facts": ["Now leads the backend team", "Recently migrated the user service to TypeScript"]}]
}`;

export const PROFILE_CONSOLIDATION_RESPONSE_SCHEMA = `{
  "consolidatedProfile": "# Behavioral Profile\\n\\n... (complete markdown)",
  "removedCount": 42,
  "summary": "brief summary of what was consolidated"
}`;

/**
 * System prompt shared by every consolidation path (gateway, direct client,
 * local LLM). Owns the causal-rule clause and the output-language policy so
 * the three paths cannot drift (issue #2190).
 */
export function buildConsolidationSystemPrompt(config: PluginConfig): string {
  return `You are a memory consolidation system. Compare new memories against existing ones and decide what to do with each.

Actions:
- ADD: Keep the new memory as-is (no duplicate exists)
- MERGE: Combine with an existing memory (provide mergeWith ID and updated content)
- UPDATE: Replace existing memory content (provide updated content)
- INVALIDATE: Remove existing memory (it's been superseded or is wrong)
- SKIP: This new memory is redundant (exact duplicate or subset of existing)

Also:
- Suggest profile updates based on patterns across memories
- Identify entity updates for entity tracking${resolveRecallAuxiliaryCapabilities(config).causalRuleExtraction ? `
- When merging or updating memories, look for IF→THEN causal patterns. If a memory describes "X failed/succeeded because Y" or "doing X led to Y", rewrite its content to make the causal rule explicit in the form "IF <condition> THEN <action/outcome>".` : ""}
- ${OUTPUT_LANGUAGE_POLICY}`;
}

/**
 * System prompt shared by every profile-consolidation path (gateway, direct
 * client, local LLM). Owns the output-language policy (issue #2190).
 */
export function buildProfileConsolidationSystemPrompt(targetLines: number): string {
  return `You are a profile consolidation system. You are given a behavioral profile (markdown) that has grown too large. Your job is to produce a CONSOLIDATED version that:

1. PRESERVES all ## section headers and their structure
2. MERGES duplicate or near-duplicate bullet points into single, clear statements
3. REMOVES stale information that has been superseded by newer bullets
4. REMOVES trivial or overly specific operational details that won't be useful across sessions
5. KEEPS the most important, durable observations about the user's preferences, habits, identity, and working style
6. Target roughly ${targetLines} lines — this is a soft target, prioritize quality over length
7. Write in the same style as the existing profile — concise bullets, no fluff
8. ${OUTPUT_LANGUAGE_POLICY}

The output should be the COMPLETE consolidated profile as valid markdown, starting with "# Behavioral Profile".`;
}

/**
 * Ambient-capture provenance for extraction (issue #2294).
 *
 * Always-on capture devices — wearable recorders, room microphones — hand the
 * extraction engine speech the user never authored: television and film
 * dialogue, podcasts, radio, music with spoken segments, and conversations the
 * user merely walked past. The extraction prompt otherwise reads every turn as
 * first-person user input, so a scripted line about a relative's birthday or a
 * medical diagnosis lands as a high-confidence personal fact and auto-promotes
 * into recall. That output is plausible, personally relevant, and wrong, which
 * makes it materially worse than a missed fact.
 *
 * This module owns both halves of the fix:
 *
 * 1. The prompt text that teaches the model to separate the user's own speech
 *    from background media, drop high-consequence personal claims it cannot
 *    attribute to the user, and score the remainder speculatively. One source
 *    of truth, shared by the cloud, direct-client, and local-LLM prompts so the
 *    three paths cannot drift.
 * 2. A deterministic backstop — `clampAmbientCaptureConfidence` — for when the
 *    model ignores the prompt anyway. It clamps ONLY high-impact personal facts
 *    (family, milestones, medical) to the speculative ceiling. Clamping every
 *    ambient fact would gut the wearable integration, which is explicitly not
 *    the goal; clamping this class costs a birthday landing in the review queue
 *    instead of active recall.
 *
 * The provenance signal itself is `BufferTurn.ambientCapture`, set by the
 * ingesting subsystem (the wearable memory pass), never by tool arguments.
 */

import type { ExtractionResult } from "./types.js";

/**
 * Upper bound of the speculative confidence tier, matching the tier table in
 * the extraction prompt ("Speculative (0.00-0.39)"). A fact at or below this
 * value cannot auto-promote through the wearable trust bands.
 */
export const SPECULATIVE_CONFIDENCE_CEILING = 0.39;

/**
 * Appended to the speculative tier definition when the input is ambient
 * capture, so the tier itself carries the rule rather than relying on the
 * separate section below being obeyed in isolation.
 */
export const AMBIENT_SPECULATIVE_TIER_CLAUSE =
  " Speculative also applies to any fact whose only evidence is ambient or background audio from an always-on capture device, even when the content is concrete and specific.";

/**
 * Full provenance section for the cloud and direct-client extraction prompts.
 */
export const AMBIENT_CAPTURE_PROMPT_SECTION = `
Source provenance — always-on capture audio:
- This transcript came from an always-on capture device (a wearable recorder or room microphone). It may contain audio the user did not author: television, film, podcasts, radio, advertisements, music with spoken segments, and conversations the user merely overheard or walked past.
- Separate the user's own speech from background media before extracting anything. Narrative, scripted, performed, or third-person speech — a show's dialogue, a podcast host, an ad read, a lecture playing in the room — is media, not user input. Never attribute it to the user or to anyone the user knows.
- High-consequence personal claims must be dropped entirely unless the user's own voice is clearly identifiable as their source: family relationships, personal milestones (births, birthdays, anniversaries, weddings, funerals, divorces), and any medical or health detail. Omit them; do not emit them at reduced confidence as a compromise.
- When you cannot tell whether a statement was spoken by the user or captured passively, skip it or set its confidence in the speculative tier (0.00-0.39). Never resolve that doubt upward.`;

/**
 * Compact variant for the local-LLM prompt, which is deliberately small to fit
 * 4k-8k context windows.
 */
export const AMBIENT_CAPTURE_PROMPT_SECTION_COMPACT = `
Ambient capture:
- This transcript came from an always-on capture device and may contain TV, film, podcast, music, or overheard speech the user did not author.
- Treat narrative, scripted, or third-person speech as media, not user input.
- Drop family, milestone (birth, birthday, anniversary, wedding, funeral), and medical claims unless the user's own voice is clearly the source.
- Otherwise, when unsure whether the user said it, set confidence in the speculative tier (0.00-0.39).`;

/**
 * Single rule for prompts that already have their own rule list and only need
 * the ambient warning (the meeting scribe, whose transcript is the same
 * wearable audio).
 */
export const AMBIENT_CAPTURE_PROMPT_RULE =
  "- The transcript may contain ambient audio nobody in the meeting authored: television, podcasts, music, or a passing conversation. Treat scripted, performed, or third-person speech as background media and never record it as a decision, commitment, or question.";

/**
 * Categories that are personal-claim-shaped by construction, independent of any
 * vocabulary: `moment` is defined as an emotionally significant event or
 * milestone, and on ambient audio a `relationship` claim is a link the model
 * inferred between people it overheard. Non-lexical, so they still catch harm
 * the term lists below miss.
 */
const HIGH_IMPACT_CATEGORIES: Record<string, true> = { moment: true, relationship: true };

/**
 * Kinship, milestone, and health vocabulary. Deliberately broad: a false
 * positive costs one ambient fact a trip through the review queue, a false
 * negative puts a fabricated medical claim into active recall. The list cannot
 * be exhaustive and is not the primary defense — the prompt is, and the
 * category signal above plus the trust-band cap in the wearable pass catch
 * classes no word list enumerates. Extend it when a miss is observed.
 *
 * Word-bounded alternation only — no nesting, no backtracking risk.
 */
const HIGH_IMPACT_TOPIC_PATTERN =
  /\b(?:mother|mothers|mom|moms|mum|father|fathers|dad|dads|sister|sisters|brother|brothers|son|sons|daughter|daughters|wife|wives|husband|husbands|spouse|fiance|fiancee|grandmother|grandfather|grandma|grandpa|grandparent|grandparents|grandson|granddaughter|grandchild|grandchildren|aunt|uncle|cousin|niece|nephew|stepmother|stepfather|stepson|stepdaughter|stepchild|godmother|godfather|birthday|birthdays|anniversary|anniversaries|wedding|weddings|honeymoon|married|marriage|divorce|divorced|widow|widowed|funeral|memorial service|engagement party|baby shower|christening|bar mitzvah|pregnant|pregnancy|miscarriage|miscarried|newborn|gave birth|stillbirth|infertility|ivf|menopause|diagnosis|diagnosed|prognosis|tested positive|cancer|carcinoma|leukemia|tumor|tumour|biopsy|chemotherapy|chemo|radiation therapy|remission|hospice|palliative|terminal illness|surgery|surgeon|hospital|hospitalized|hospitalised|icu|emergency room|ambulance|stroke|heart attack|cardiac|arrhythmia|afib|seizure|epilepsy|asthma|allergy|allergic|diabetes|diabetic|insulin|cholesterol|blood pressure|hypertension|dementia|alzheimer|alzheimers|parkinson|parkinsons|hiv|aids diagnosis|medication|medications|prescription|prescribed|dosage|symptom|symptoms|illness|disease|disorder|syndrome|therapy|therapist|psychiatrist|psychologist|antidepressant|depression|anxiety|bipolar|schizophrenia|adhd|autism|ptsd|overdose|relapse|sobriety|rehab|addiction|alcoholism|concussion|transplant|dialysis|immunocompromised|mental health|covid|covid-19|coronavirus|flu|influenza|pneumonia|bronchitis|infection|infected|fever|migraine|ulcer|hernia|appendicitis|sepsis|sick leave|urgent care|broken leg|broken arm|broken wrist|broken hip|broken rib|broken ribs|sprained|dislocated|torn ligament|torn acl|whiplash|burn unit|chronic pain|disability|wheelchair|hearing aid|blind in|vaccinated|vaccination|immunization|blood test|scan results|mri|ct scan|x-ray|deaf|deafness|blind|blindness|mute|nonverbal|paralyzed|paralysed|paraplegic|quadriplegic|amputee|amputation|prosthetic|multiple sclerosis|lupus|crohn|celiac|fibromyalgia|cystic fibrosis|sickle cell|cerebral palsy|down syndrome|muscular dystrophy|chronic fatigue|chronic illness|terminally ill|life support|coma|special needs|caregiver|nursing home|assisted living|treatment|treatments|in treatment|medical leave|oncologist|cardiologist|neurologist|pediatrician|pediatric|als|copd|epilepsy|seizures|hospitalization|infirm|frail|bedridden|home health|physical therapy|occupational therapy|speech therapy)\b/i;

/**
 * Bodily-harm and affliction SHAPES rather than nouns: "broke her leg", "tore
 * his ACL", "caught something at the office". A vocabulary of conditions can
 * never be complete, so this matches the sentence form instead — a verb of
 * injury or contagion pointed at a person's POSSESSION. Articles are excluded
 * on purpose: "the build broke the deploy pipeline" is not an injury.
 */
const AFFLICTION_SHAPE_PATTERN =
  /\b(?:broke|broken|fractured|sprained|dislocated|tore|torn|bruised|burned|scalded|injured|hurt)\s+(?:his|her|their|my|your|our)\s+\w+|\b(?:caught|contracted|came down with|is recovering from|was rushed to|passed away|died of|died from)\b/i;

/**
 * Words that are personal only when someone possesses them: "child process",
 * "parent component", "sibling node", and "customer family" are everyday
 * technical speech, while "his child" and "Rachel's parents" are not.
 */
const POSSESSED_KINSHIP_PATTERN =
  /(?:\b(?:my|your|his|her|their|our)|'s)\s+(?:child|children|kid|kids|parent|parents|partner|family|sibling|siblings|in-law|in-laws|relatives)\b/i;

/** Tags that mark a fact as belonging to the same high-impact classes. */
const HIGH_IMPACT_TAGS: Record<string, true> = {
  disability: true,
  family: true,
  health: true,
  medical: true,
  medication: true,
  diagnosis: true,
  birthday: true,
  anniversary: true,
  marriage: true,
  pregnancy: true,
  "mental-health": true,
};

/**
 * True when this claim is personal in a way whose fabrication causes real
 * harm — a family relationship, a personal milestone, or a medical detail.
 *
 * Read by every ambient guard: the post-extraction confidence clamp below, the
 * wearable trust-band cap, and the meeting trust-band cap. A fact this flags
 * can never auto-approve, on any path, however the boosts add up.
 *
 * Takes the shape rather than `ExtractedFact` so meeting candidates — which
 * carry no tags — pass without a synthetic empty array.
 *
 * `personRefs` comes from `collectPersonEntityRefs` over the same extraction:
 * pass it whenever the entity list is available, so personhood is read from
 * the extractor's own `type: "person"` metadata instead of inferred from how
 * it happened to spell the ref.
 */
export function isHighImpactPersonalFact(
  fact: {
    category: string;
    content: string;
    tags?: readonly string[];
    entityRef?: string;
  },
  personRefs?: ReadonlySet<string>,
): boolean {
  // The strongest non-lexical signal: a claim ABOUT A PERSON is high-impact
  // whatever condition, relationship, or milestone the sentence names. This is
  // what covers wording no list anticipates ("Dana is deaf").
  if (isPersonRef(fact.entityRef, personRefs)) return true;
  if (HIGH_IMPACT_CATEGORIES[fact.category] === true) return true;
  if (HIGH_IMPACT_TOPIC_PATTERN.test(fact.content)) return true;
  if (AFFLICTION_SHAPE_PATTERN.test(fact.content)) return true;
  if (POSSESSED_KINSHIP_PATTERN.test(fact.content)) return true;
  for (const tag of fact.tags ?? []) {
    if (HIGH_IMPACT_TAGS[tag.trim().toLowerCase()] === true) return true;
  }
  return false;
}

/**
 * Normalize an entity reference for comparison: casefold, strip a leading
 * type prefix, and collapse separators. `Person-Jane_Doe`, `person:jane-doe`,
 * and `jane doe` all reduce to `jane-doe`.
 */
function normalizeEntityRef(ref: string): string {
  return ref
    .trim()
    .toLowerCase()
    .replace(/^(?:person|people)[-:_\s]+/, "")
    .replace(/[\s_]+/g, "-");
}

/**
 * Names of every `type: "person"` entity in an extraction, normalized for
 * lookup. Personhood is the extractor's own metadata, not a guess from the
 * shape of `entityRef` — the prompt asks for `person-jane-doe` but the field is
 * optional and models routinely emit a bare `jane-doe`.
 */
export function collectPersonEntityRefs(result: {
  entities: ReadonlyArray<{ name: string; type: string }>;
}): ReadonlySet<string> {
  const refs = new Set<string>();
  for (const entity of result.entities) {
    if (entity.type !== "person") continue;
    const normalized = normalizeEntityRef(entity.name);
    if (normalized.length > 0) refs.add(normalized);
  }
  return refs;
}

/** True when this ref names a person, by metadata or by explicit prefix. */
function isPersonRef(ref: string | undefined, personRefs?: ReadonlySet<string>): boolean {
  if (ref === undefined || ref.trim().length === 0) return false;
  if (/^(?:person|people)[-:_]/i.test(ref.trim())) return true;
  return personRefs !== undefined && personRefs.has(normalizeEntityRef(ref));
}

/**
 * Deterministic backstop applied after extraction on ambient-capture input:
 * hold high-impact personal facts at or below the speculative ceiling so they
 * cannot auto-promote to active recall on a model's unsupported confidence.
 *
 * Returns the input unchanged when nothing needs clamping, so the non-ambient
 * path pays one predicate per fact and allocates nothing.
 */
export function clampAmbientCaptureConfidence(
  result: ExtractionResult,
): ExtractionResult {
  let clampedAny = false;
  const personRefs = collectPersonEntityRefs(result);
  const facts = result.facts.map((fact) => {
    if (fact.confidence <= SPECULATIVE_CONFIDENCE_CEILING) return fact;
    if (!isHighImpactPersonalFact(fact, personRefs)) return fact;
    clampedAny = true;
    return { ...fact, confidence: SPECULATIVE_CONFIDENCE_CEILING };
  });
  return clampedAny ? { ...result, facts } : result;
}

import { EXTRACTION_RESPONSE_PLACEHOLDERS } from "./extraction-prompt.js";
import { normalizeRecallTokens } from "./recall-tokenization.js";
import { sanitizeMemoryContent } from "./sanitize.js";
import type { ExtractedFact } from "./types.js";

export function isPlainRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

export function containsExtractionPlaceholder(value: unknown): boolean {
  if (typeof value === "string") return EXTRACTION_RESPONSE_PLACEHOLDERS[value.trim()] === true;
  if (Array.isArray(value)) return value.some(containsExtractionPlaceholder);
  return isPlainRecord(value) && Object.values(value).some(containsExtractionPlaceholder);
}

export function extractionText(value: unknown): string | undefined {
  if (typeof value !== "string") return undefined;
  const text = value.trim();
  return text.length > 0 && !containsExtractionPlaceholder(text) ? text : undefined;
}

export function extractionAttributes(value: unknown): Record<string, string> | undefined {
  if (!isPlainRecord(value)) return undefined;
  const attributes: Record<string, string> = {};
  for (const [key, candidate] of Object.entries(value).sort(([left], [right]) => left.localeCompare(right))) {
    const normalizedKey = extractionText(key);
    const normalizedValue = extractionText(candidate);
    if (normalizedKey !== undefined && normalizedValue !== undefined) {
      attributes[normalizedKey] = normalizedValue;
    }
  }
  return Object.keys(attributes).length > 0 ? attributes : undefined;
}

const EXTRACTION_CUE_ANCHOR_TYPES = new Set(["entity", "file", "tool", "outcome", "constraint", "date"]);

export function extractionCueAnchors(value: unknown): NonNullable<ExtractedFact["cueAnchors"]> | undefined {
  if (!Array.isArray(value)) return undefined;
  const anchorsByIdentity = new Map<string, NonNullable<ExtractedFact["cueAnchors"]>[number]>();
  for (const candidate of value) {
    if (!isPlainRecord(candidate)) continue;
    const type = extractionText(candidate.type);
    const anchorValue = extractionText(candidate.value);
    const sanitizedAnchor = anchorValue === undefined ? undefined : sanitizeMemoryContent(anchorValue);
    const sanitizedAnchorValue = sanitizedAnchor?.clean === true ? sanitizedAnchor.text.trim() : undefined;
    if (
      type === undefined ||
      sanitizedAnchorValue === undefined ||
      sanitizedAnchorValue.length === 0 ||
      sanitizedAnchorValue.length > 120 ||
      !EXTRACTION_CUE_ANCHOR_TYPES.has(type)
    ) {
      continue;
    }
    const normalizedCue = normalizeRecallTokens(sanitizedAnchorValue).join(" ");
    if (normalizedCue.length === 0) continue;
    const identity = `${type}:${normalizedCue}`;
    const existing = anchorsByIdentity.get(identity);
    if (!existing || sanitizedAnchorValue.localeCompare(existing.value) < 0) {
      anchorsByIdentity.set(identity, {
        type: type as NonNullable<ExtractedFact["cueAnchors"]>[number]["type"],
        value: sanitizedAnchorValue,
      });
    }
  }
  const anchors = [...anchorsByIdentity.entries()]
    .sort(([left], [right]) => left.localeCompare(right))
    .slice(0, 3)
    .map(([, anchor]) => anchor);
  return anchors.length > 0 ? anchors : undefined;
}

