// Entity timeline / structured-section pure helpers extracted from storage.ts
// (issue #1909 PR write-hot-paths). Pure functions only — no I/O — so they are
// safe to share across the write path and entity parsing without circular
// runtime coupling. storage.ts imports these back and re-exports the ones that
// were previously part of its public API.
import { createHash } from "node:crypto";
import { matchEntitySchemaSection, normalizeEntityStructuredSection } from "../entity-schema.js";
import type { EntityFile, EntityStructuredSection, EntityTimelineEntry, PluginConfig } from "../types.js";
export const ENTITY_TIMELINE_METADATA_MARKER = "remnic-meta-v1";

export function parseEntityTimelineBullet(bullet: string, fallbackTimestamp: string): EntityTimelineEntry | null {
  const trimmed = bullet.trim();
  if (!trimmed) return null;

  let rest = trimmed;
  const entry: EntityTimelineEntry = {
    timestamp: trimmed.startsWith("[") ? "" : fallbackTimestamp,
    text: "",
  };
  const consumedMetadataSegments: string[] = [];
  let metadataMarkerSeen = false;
  let literalSingleSourceSegment: string | undefined;

  if (!trimmed.startsWith("[")) {
    entry.text = unescapeEntityTimelineText(trimmed);
    return entry.text ? entry : null;
  }

  const firstEnd = trimmed.indexOf("]");
  if (firstEnd === -1) {
    entry.text = trimmed;
    return entry.text ? entry : null;
  }

  const firstToken = trimmed.slice(1, firstEnd).trim();
  const parsedTimestamp = Date.parse(firstToken);
  if (Number.isFinite(parsedTimestamp)) {
    entry.timestamp = firstToken || fallbackTimestamp;
    rest = trimmed.slice(firstEnd + 1).trimStart();
  }

  while (rest.startsWith("[")) {
    const end = findEntityTimelineTokenEnd(rest);
    if (end === -1) break;
    const rawSegment = rest.slice(0, end + 1);
    const token = rest.slice(1, end).trim();
    const nextRest = rest.slice(end + 1).trimStart();
    if (token === ENTITY_TIMELINE_METADATA_MARKER) {
      metadataMarkerSeen = true;
      consumedMetadataSegments.push(rawSegment);
      rest = nextRest;
      continue;
    }
    const equalsIdx = token.indexOf("=");
    if (equalsIdx === -1) {
      if (rest === trimmed) {
        entry.text = trimmed;
        return entry.text ? entry : null;
      }
      break;
    }
    const key = token.slice(0, equalsIdx).trim().toLowerCase();
    const value = unescapeEntityTimelineMetadataValue(token.slice(equalsIdx + 1).trim());
    if (!value) break;
    if (key === "remnic-origin" && !metadataMarkerSeen) {
      entry.text = rest.trim();
      return entry.text ? entry : null;
    }
    switch (key) {
      case "source_meta":
        entry.source = value;
        break;
      case "source":
        if (
          consumedMetadataSegments.length === 0 &&
          !nextRest.startsWith("[") &&
          nextRest.length > 0 &&
          !isManagedEntityTimelineSource(value)
        ) {
          literalSingleSourceSegment = rawSegment;
          rest = nextRest;
          break;
        }
        entry.source = value;
        break;
      case "session":
      case "sessionkey":
        entry.sessionKey = value;
        break;
      case "principal":
        entry.principal = value;
        break;
      case "remnic-origin":
        entry.origin = value;
        break;
      default:
        entry.text = rest.trim();
        return entry.text ? entry : null;
    }
    if (literalSingleSourceSegment) break;
    consumedMetadataSegments.push(rawSegment);
    rest = nextRest;
  }

  if (literalSingleSourceSegment) {
    return {
      timestamp: entry.timestamp,
      text: `${literalSingleSourceSegment} ${rest}`.trim(),
    };
  }
  entry.text = unescapeEntityTimelineText(rest.trim());
  if (!entry.text) return null;
  return entry;
}

export function isEntitySynthesisTimelinePromotionBullet(bullet: string): boolean {
  const trimmed = bullet.trim();
  if (!trimmed.startsWith("[")) return false;

  const firstEnd = findEntityTimelineTokenEnd(trimmed);
  if (firstEnd === -1) return false;

  const firstToken = trimmed.slice(1, firstEnd).trim();
  return looksLikeEntityTimelineTimestamp(firstToken);
}

export function looksLikeEntityTimelineTimestamp(token: string): boolean {
  if (!/^\d{4}-\d{2}-\d{2}(?:[T\s].*)?$/.test(token)) return false;
  return Number.isFinite(Date.parse(token));
}

export function isManagedEntityTimelineSource(source: string): boolean {
  switch (source.trim().toLowerCase()) {
    case "artifact":
    case "chunking":
    case "cli-migrate":
    case "compounding-promotion":
    case "consolidation":
    case "contradiction-detection":
    case "entity_extraction":
    case "explicit":
    case "explicit-inline":
    case "explicit-inline-review":
    case "explicit-review":
    case "extraction":
    case "extraction-shared-promotion":
    case "manual":
    case "migration":
    case "migration-rechunk":
    case "proactive":
    case "replay":
    case "semantic-consolidation":
    case "unknown":
      return true;
    default:
      return false;
  }
}

export function findEntityTimelineTokenEnd(input: string): number {
  let escaped = false;
  for (let index = 0; index < input.length; index += 1) {
    const char = input[index];
    if (escaped) {
      escaped = false;
      continue;
    }
    if (char === "\\") {
      escaped = true;
      continue;
    }
    if (char === "]") return index;
  }
  return -1;
}

export function escapeEntityTimelineMetadataValue(value: string): string {
  let escaped = "";
  for (const char of value) {
    switch (char) {
      case "\\":
        escaped += "\\\\";
        break;
      case "]":
        escaped += "\\]";
        break;
      case "\n":
        escaped += "\\n";
        break;
      case "\r":
        escaped += "\\r";
        break;
      case "\t":
        escaped += "\\t";
        break;
      default: {
        const codePoint = char.codePointAt(0) ?? 0;
        if (codePoint < 0x20) {
          escaped += `\\u${codePoint.toString(16).padStart(4, "0")}`;
        } else {
          escaped += char;
        }
      }
    }
  }
  return escaped;
}

export function unescapeEntityTimelineMetadataValue(value: string): string {
  if (!value.includes("\\")) return value;

  let result = "";
  for (let index = 0; index < value.length; index += 1) {
    const char = value[index];
    if (char !== "\\") {
      result += char;
      continue;
    }

    const next = value[index + 1];
    if (!next) {
      result += "\\";
      break;
    }

    switch (next) {
      case "n":
        result += "\n";
        index += 1;
        break;
      case "r":
        result += "\r";
        index += 1;
        break;
      case "t":
        result += "\t";
        index += 1;
        break;
      case "u": {
        const hex = value.slice(index + 2, index + 6);
        if (/^[0-9a-fA-F]{4}$/.test(hex)) {
          result += String.fromCharCode(parseInt(hex, 16));
          index += 5;
          break;
        }
        result += "u";
        index += 1;
        break;
      }
      default:
        result += next;
        index += 1;
        break;
    }
  }
  return result;
}
export function escapeEntityTimelineText(value: string): string {
  return /^\\*\[(?:remnic-origin=|remnic-meta-v1\])/i.test(value) ? `\\${value}` : value;
}

export function unescapeEntityTimelineText(value: string): string {
  return /^\\+\[(?:remnic-origin=|remnic-meta-v1\])/i.test(value) ? value.slice(1) : value;
}

export function serializeEntityTimelineEntry(entry: EntityTimelineEntry): string {
  const tokens: string[] = [];
  if (entry.timestamp.trim().length > 0) {
    tokens.push(`[${entry.timestamp}]`);
  }
  if (entry.source) {
    const sourceKey = isManagedEntityTimelineSource(entry.source) ? "source" : "source_meta";
    tokens.push(`[${sourceKey}=${escapeEntityTimelineMetadataValue(entry.source)}]`);
  }
  if (entry.sessionKey) {
    tokens.push(`[session=${escapeEntityTimelineMetadataValue(entry.sessionKey)}]`);
  }
  if (entry.principal) {
    tokens.push(`[principal=${escapeEntityTimelineMetadataValue(entry.principal)}]`);
  }
  if (entry.origin) {
    tokens.push(`[${ENTITY_TIMELINE_METADATA_MARKER}]`);
    tokens.push(`[remnic-origin=${escapeEntityTimelineMetadataValue(entry.origin)}]`);
  }
  const serializedMetadata = tokens.length > 0 ? `${tokens.join(" ")} ` : "";
  return `- ${serializedMetadata}${escapeEntityTimelineText(entry.text)}`.trimEnd();
}

export function dedupeEntityTimelineFacts(timeline: EntityTimelineEntry[]): string[] {
  return [...new Set(timeline.map((entry) => entry.text.trim()).filter((entry) => entry.length > 0))];
}

export function normalizeEntitySectionFact(value: string): string {
  return value.replace(/\s+/g, " ").trim();
}

export function normalizeStructuredSectionFactsWithOrigins(
  facts: string[],
  factOrigins?: Array<string | undefined>,
  defaultOrigin?: string,
): Pick<EntityStructuredSection, "facts" | "factOrigins"> {
  const normalizedFacts: string[] = [];
  const origins: Array<string | undefined> = [];
  const seen = new Map<string, number>();
  for (const [index, fact] of facts.entries()) {
    const normalized = normalizeEntitySectionFact(fact);
    if (!normalized) continue;
    const existingIndex = seen.get(normalized) ?? -1;
    const origin = factOrigins?.[index] ?? defaultOrigin;
    if (existingIndex >= 0) {
      if (origins[existingIndex] !== origin) origins[existingIndex] = undefined;
      continue;
    }
    seen.set(normalized, normalizedFacts.length);
    normalizedFacts.push(normalized);
    origins.push(origin);
  }
  return {
    facts: normalizedFacts,
    ...(origins.some((origin) => origin !== undefined) ? { factOrigins: origins } : {}),
  };
}
export function normalizeStructuredSectionFacts(facts: string[]): string[] {
  return [...new Set(facts.map((fact) => normalizeEntitySectionFact(fact)).filter((fact) => fact.length > 0))];
}

export function collectStructuredSectionFacts(structuredSections: EntityStructuredSection[]): string[] {
  const facts: string[] = [];
  for (const section of structuredSections) {
    for (const fact of section.facts) {
      const normalized = normalizeEntitySectionFact(fact);
      if (!normalized) continue;
      facts.push(normalized);
    }
  }
  return [...new Set(facts)];
}

export function compileEntityFacts(
  timeline: EntityTimelineEntry[],
  structuredSections: EntityStructuredSection[]
): string[] {
  const facts: string[] = [];
  const seen = new Set<string>();
  for (const fact of dedupeEntityTimelineFacts(timeline)) {
    if (seen.has(fact)) continue;
    seen.add(fact);
    facts.push(fact);
  }
  for (const fact of collectStructuredSectionFacts(structuredSections)) {
    if (seen.has(fact)) continue;
    seen.add(fact);
    facts.push(fact);
  }
  return facts;
}

function parseEntityStructuredSectionFacts(
  lines: string[],
): Pick<EntityStructuredSection, "facts" | "factOrigins"> {
  const facts: string[] = [];
  const factOrigins: Array<string | undefined> = [];
  let currentBlock: string[] = [];
  let currentOrigin: string | undefined;

  const flushCurrentBlock = (): void => {
    const normalized = normalizeEntitySectionFact(currentBlock.join(" "));
    if (normalized.length > 0) {
      facts.push(normalized);
      factOrigins.push(currentOrigin);
    }
    currentBlock = [];
    currentOrigin = undefined;
  };

  for (const rawLine of lines) {
    const line = rawLine.trim();
    if (!line) {
      flushCurrentBlock();
      continue;
    }
    if (line.startsWith("- ")) {
      flushCurrentBlock();
      const bullet = line.slice(2).trim();
      const metadataPrefix = `[${ENTITY_TIMELINE_METADATA_MARKER}] `;
      const hasMarker = bullet.startsWith(metadataPrefix);
      const originStart = metadataPrefix.length;
      const originPrefix = hasMarker && bullet.startsWith("[remnic-origin=", originStart);
      const originEndOffset = originPrefix
        ? findEntityTimelineTokenEnd(bullet.slice(originStart))
        : -1;
      const originEnd = originEndOffset >= 0 ? originEndOffset + originStart : -1;
      const token = originEnd >= 0 ? bullet.slice(originStart + 15, originEnd) : "";
      currentBlock = [originEnd >= 0
        ? unescapeEntityTimelineText(bullet.slice(originEnd + 1).trimStart())
        : unescapeEntityTimelineText(hasMarker ? bullet.slice(metadataPrefix.length) : bullet)];
      currentOrigin = originEnd >= 0
        ? unescapeEntityTimelineMetadataValue(token)
        : undefined;
      continue;
    }
    currentBlock.push(line);
  }
  flushCurrentBlock();
  return normalizeStructuredSectionFactsWithOrigins(facts, factOrigins);
}
function looksLikeStructuredSectionFactList(lines: string[]): boolean {
  const firstNonBlank = lines.find((line) => line.trim().length > 0)?.trim() ?? "";
  return firstNonBlank.startsWith("- ");
}

export function partitionEntityStructuredSections(
  entityType: string,
  extraSections: Array<{ title: string; lines: string[] }>,
  entitySchemas?: PluginConfig["entitySchemas"]
): {
  structuredSections: EntityStructuredSection[];
  remainingExtraSections: Array<{ title: string; lines: string[] }>;
} {
  const structuredSections: EntityStructuredSection[] = [];
  const remainingExtraSections: Array<{ title: string; lines: string[] }> = [];
  const structuredSectionIndex = new Map<string, EntityStructuredSection>();

  for (const section of extraSections) {
    const matchedSection = matchEntitySchemaSection(entityType, section.title, entitySchemas);
    if (!matchedSection && !looksLikeStructuredSectionFactList(section.lines)) {
      remainingExtraSections.push(section);
      continue;
    }
    const parsedFacts = parseEntityStructuredSectionFacts(section.lines);
    if (!matchedSection && parsedFacts.facts.length === 0) {
      remainingExtraSections.push(section);
      continue;
    }
    const normalizedSection = matchedSection
      ? { key: matchedSection.key, title: matchedSection.title }
      : normalizeEntityStructuredSection(entityType, { key: section.title, title: section.title }, entitySchemas);
    if (parsedFacts.facts.length === 0) {
      remainingExtraSections.push(section);
      continue;
    }
    const existing = structuredSectionIndex.get(normalizedSection.key);
    if (existing) {
      const existingOrigins = existing.facts.map((_, index) => existing.factOrigins?.[index]);
      const incomingOrigins = parsedFacts.facts.map((_, index) => parsedFacts.factOrigins?.[index]);
      const merged = normalizeStructuredSectionFactsWithOrigins(
        [...existing.facts, ...parsedFacts.facts],
        [...existingOrigins, ...incomingOrigins],
      );
      existing.facts = merged.facts;
      existing.factOrigins = merged.factOrigins;
      continue;
    }
    const structuredSection: EntityStructuredSection = {
      key: normalizedSection.key,
      title: normalizedSection.title,
      facts: parsedFacts.facts,
      ...(parsedFacts.factOrigins ? { factOrigins: parsedFacts.factOrigins } : {}),
    };
    structuredSections.push(structuredSection);
    structuredSectionIndex.set(normalizedSection.key, structuredSection);
  }

  return {
    structuredSections,
    remainingExtraSections,
  };
}

export function latestEntityTimelineTimestamp(entity: EntityFile): string | undefined {
  let latestRaw: string | undefined;
  for (const entry of entity.timeline) {
    const timestamp = entry.timestamp.trim();
    if (!timestamp) continue;
    if (!latestRaw || compareEntityTimestamps(timestamp, latestRaw) > 0) {
      latestRaw = timestamp;
    }
  }
  return latestRaw;
}

export function compareEntityTimestamps(left?: string, right?: string): number {
  const leftValue = left?.trim() ?? "";
  const rightValue = right?.trim() ?? "";

  if (!leftValue && !rightValue) return 0;
  if (!leftValue) return -1;
  if (!rightValue) return 1;

  const leftMs = Date.parse(leftValue);
  const rightMs = Date.parse(rightValue);
  const leftParsed = Number.isFinite(leftMs);
  const rightParsed = Number.isFinite(rightMs);

  if (leftParsed && rightParsed) {
    if (leftMs === rightMs) return 0;
    return leftMs > rightMs ? 1 : -1;
  }
  if (leftParsed) return 1;
  if (rightParsed) return -1;
  return leftValue.localeCompare(rightValue);
}

export function countEntityStructuredFacts(entity: EntityFile): number {
  return (entity.structuredSections ?? []).reduce((count, section) => count + section.facts.length, 0);
}

export function fingerprintEntityStructuredFacts(entity: Pick<EntityFile, "structuredSections">): string | undefined {
  const normalizedSections = (entity.structuredSections ?? [])
    .map((section) => ({
      key: section.key.trim().toLowerCase(),
      title: section.title.replace(/\s+/g, " ").trim(),
      facts: normalizeStructuredSectionFacts(section.facts)
        .slice()
        .sort((left, right) => left.localeCompare(right)),
    }))
    .filter((section) => section.facts.length > 0)
    .sort(
      (left, right) =>
        left.key.localeCompare(right.key) ||
        left.title.localeCompare(right.title) ||
        left.facts.join("\n").localeCompare(right.facts.join("\n"))
    );
  if (normalizedSections.length === 0) return undefined;
  return createHash("sha256").update(JSON.stringify(normalizedSections)).digest("hex");
}

export function isEntitySynthesisStale(entity: EntityFile): boolean {
  const structuredFactCount = countEntityStructuredFacts(entity);
  const structuredFactDigest = fingerprintEntityStructuredFacts(entity);
  const storedStructuredFactDigest = entity.synthesisStructuredFactDigest?.trim() || undefined;
  if (entity.timeline.length === 0 && structuredFactCount === 0) return false;
  if (!entity.synthesis?.trim()) return true;
  if (entity.synthesisTimelineCount === undefined) return true;
  if (structuredFactCount > 0 && entity.synthesisStructuredFactCount === undefined) return true;
  if (structuredFactCount > 0 && !storedStructuredFactDigest) return true;
  const latestTimelineTimestamp = latestEntityTimelineTimestamp(entity);
  if (!latestTimelineTimestamp) {
    return (
      entity.timeline.length > entity.synthesisTimelineCount ||
      structuredFactCount > (entity.synthesisStructuredFactCount ?? 0) ||
      structuredFactDigest !== storedStructuredFactDigest
    );
  }
  if (!entity.synthesisUpdatedAt?.trim()) return true;
  const timelineFreshness = compareEntityTimestamps(latestTimelineTimestamp, entity.synthesisUpdatedAt);
  if (timelineFreshness > 0) return true;
  return (
    entity.timeline.length > entity.synthesisTimelineCount ||
    structuredFactCount > (entity.synthesisStructuredFactCount ?? 0) ||
    structuredFactDigest !== storedStructuredFactDigest
  );
}

// Content-hash dedup index for facts, extracted from storage.ts (issue #1909 /
// PR #2016 write-hot-paths). Self-contained: cross-process locked reconcile /
// rebuild saves plus the deferred durable-retry machinery. storage.ts imports
// these back and re-exports the class + companion types that were previously
// part of its public API.
import { mkdir, stat } from "node:fs/promises";
import path from "node:path";
import { computeContentHash, normalizeContent } from "../content-hash.js";
import { log } from "../logger.js";
import { SecureStoreLockedError, readMaybeEncryptedFile, writeMaybeEncryptedFile } from "../secure-store/secure-fs.js";
import { isErrnoCode } from "../utils/errno.js";
import { withHeldFileLock } from "../utils/serialize-mutations.js";

/**
 * Stale threshold (ms) for the per-file advisory lock guarding a fact-hash
 * index merge-save (issue #1909 review round 7). The critical section is a
 * single read+atomic-rewrite of one index file (≤ a few MB), so a holder older
 * than this is treated as crashed. Generous to tolerate slow/encrypted disks
 * without breaking a legitimately in-progress publish.
 */
const CONTENT_HASH_INDEX_LOCK_STALE_MS = 30_000;
/** Version marker for the normalized Unicode hash index format. */
const CONTENT_HASH_INDEX_FORMAT_HEADER = "# remnic-content-hash-index:v2";

function parseHashIndex(raw: string): { versioned: boolean; hashes: Set<string> } {
  const lines = raw
    .split("\n")
    .map((line) => line.trim())
    .filter((line) => line.length > 0);
  if (lines[0] !== CONTENT_HASH_INDEX_FORMAT_HEADER) {
    return { versioned: false, hashes: new Set() };
  }
  return { versioned: true, hashes: new Set(lines.slice(1)) };
}

function serializeHashIndex(hashes: Set<string>): string {
  return `${CONTENT_HASH_INDEX_FORMAT_HEADER}\n${[...hashes].join("\n")}\n`;
}

/**
 * Durable-retry policy for a deferred content-hash reconcile save whose
 * cross-process lock acquire timed out (issue #1909 / PR #2016). When the lock
 * is contended past `withHeldFileLock`'s bounded wait, the added hashes are held
 * only in this process's memory; relying on "some later batch save" is not
 * durable (the run may be the last before idle/shutdown), and a long-lived peer
 * that already built its authoritative in-memory index will not see the write.
 * So we schedule a bounded, exponentially-backed-off background retry that keeps
 * re-attempting the locked publish until it lands. Bounded because the durable
 * fact `.md` is already on disk and a process restart rebuilds the index from
 * the corpus regardless — exhausting retries degrades to that rebuild safety
 * net, never to data loss or a fatal append failure.
 */
const CONTENT_HASH_INDEX_RETRY_MAX_ATTEMPTS = 5;
/** Base backoff (ms) before the first deferred reconcile-save retry; doubles each attempt. */
const CONTENT_HASH_INDEX_RETRY_BASE_MS = 500;
/** Ceiling (ms) for the exponential reconcile-save retry backoff. */
export const CONTENT_HASH_INDEX_RETRY_MAX_DELAY_MS = 5_000;

/**
 * Tuning for {@link ContentHashIndex} cross-process lock waits and the
 * deferred reconcile-save durable retry (issue #1909 / PR #2016). All optional;
 * production uses the module defaults. Tests inject small values so the
 * lock-timeout + retry path is exercised deterministically without real
 * multi-second waits.
 */
export interface ContentHashIndexLockOptions {
  /** Bounded wait to acquire the per-file advisory lock; passed to `withHeldFileLock` (default 5000ms). */
  readonly maxWaitMs?: number;
  /** Poll interval while waiting for a busy lock (default 50ms). */
  readonly pollMs?: number;
  /** Base backoff before the first deferred-save retry (default 500ms). */
  readonly retryBaseMs?: number;
  /** Max deferred-save retries before falling back to the corpus-rebuild safety net (default 5). */
  readonly retryMaxAttempts?: number;
  /**
   * Tombstone-blocked capture write-lock backoff (COS-392). These do not
   * change the fact-hash index lock. Omitted fields use the 50ms / 2s / 60s
   * defaults. Converge copies its config here before replicating a file.
   */
  readonly captureWriteLockInitialDelayMs?: number;
  readonly captureWriteLockMaxDelayMs?: number;
  readonly captureWriteLockDeadlineMs?: number;
  /** Apply abort signal. Checked before each probe, during backoff, and before the write. */
  readonly captureWriteLockSignal?: AbortSignal;
}

/**
 * Thrown when the fact-hash index cannot be made authoritative — the
 * cross-process rebuild lock could not be acquired within the bounded retry
 * budget (PR #2016). Callers that require an authoritative dedup answer surface
 * this instead of silently trusting a stale loaded snapshot.
 */
export class FactHashIndexNotAuthoritativeError extends Error {
  constructor(stateDir: string) {
    super(
      `fact-hash index is not authoritative: the cross-process rebuild lock for ${stateDir} could not be acquired within the bounded retry budget`
    );
    this.name = "FactHashIndexNotAuthoritativeError";
  }
}

type DiskFingerprint = {
  mtimeMs: number;
  size: number;
  dev: number;
  ino: number;
  ctimeMs: number;
  birthtimeMs: number;
};
export interface ContentHashPathEntry {
  readonly path: string;
  readonly contentHash: string;
}

/**
 * Content-hash dedup index for facts.
 * Normalizes content (lowercase, strip punctuation, collapse whitespace),
 * computes SHA-256, and stores hashes in a line-delimited file.
 * Prevents writing semantically identical facts.
 */
export class ContentHashIndex {
  private hashes: Set<string> = new Set();
  /**
   * Fact-ONLY hash partition (issue #2474). `hashes` above is category-blind
   * (every write category registers there); this subset carries only
   * `category === "fact"` hashes so fact-only membership checks
   * (`hasFact*`) can never be satisfied by an unrelated decision/preference
   * sharing the same normalized body. In-memory only — never serialized to
   * fact-hashes.txt; `clear()` drops it and every authoritative rebuild
   * repopulates it via `addFactByHash`. Subset invariant: `factHashes ⊆
   * hashes` — `addFact*` registers in both, and the removal sites that drop
   * a shared hash also drop the partition entry (removal stays caller-paired
   * because shared-index removal is category-blind: archiving a non-fact
   * must not evict an active fact's fact-only membership).
   */
  private factHashes: Set<string> = new Set();
  private dirty = false;
  /** True when load() found the pre-Unicode, markerless on-disk format. */
  private formatMigrationRequired = false;
  /**
   * Hashes explicitly removed since the last successful save (issue #1909 review
   * round 8 thread 3). Tracked separately so `saveMergingWithDisk` can be
   * removal-AWARE: under the file lock it reads the latest on-disk set, DROPS
   * these, then unions our additions — so a removal batch cannot resurrect a
   * hash (union alone would) and cannot clobber a concurrent extraction's
   * appended hash (blind overwrite would). Consumed + cleared by every save.
   */
  private removed: Set<string> = new Set();
  /**
   * Hashes added by THIS instance since the last successful save (issue #1909
   * review round 9 finding 3). Tracked separately from the loaded snapshot so a
   * reconciling save publishes `(on-disk \ removed) ∪ added` — it re-applies only
   * OUR additions, never the stale loaded entries. Without this, seeding the
   * merge from `this.hashes` (loaded ∪ added) would resurrect a hash a peer
   * removed on disk while this instance held a stale snapshot.
   */
  private added: Set<string> = new Set();
  private readonly filePath: string;
  private readonly secureStoreKeyProvider: () => Buffer | null;
  private readonly secureStoreWriteKeyProvider: () => Buffer | null;
  private readonly memoryDir: string;
  private readonly lockOptions: ContentHashIndexLockOptions;
  /**
   * Deferred reconcile-save durable-retry state (issue #1909 / PR #2016). At
   * most ONE retry is ever armed (`reconcileRetryTimer` is the reentrancy guard)
   * so successive timed-out saves cannot stack duplicate/parallel retries.
   * `reconcileRetryBarrier` resolves when the chain settles (published or gave
   * up) — awaited by tests and any caller wanting the eventual result.
   */
  private reconcileRetryTimer: NodeJS.Timeout | null = null;
  private reconcileRetryAttempts = 0;
  private reconcileRetryBarrier: Promise<void> | null = null;
  private reconcileRetryResolve: (() => void) | null = null;
  /**
   * On-disk fingerprint captured at the last point THIS instance's in-memory
   * set matched disk — after `load()`, `save()`, or a reconcile publish. A peer
   * process that advances the durable index changes its file generation even
   * when byte size and mtime collide, so the freshness check remains safe
   * without an O(file-size) read on the hot path.
   */
  private lastSyncedFingerprint: DiskFingerprint | null = null;
  constructor(
    stateDir: string,
    secureStoreKeyProvider: () => Buffer | null = () => null,
    secureStoreWriteKeyProvider: () => Buffer | null = secureStoreKeyProvider,
    memoryDir: string = path.dirname(stateDir),
    lockOptions: ContentHashIndexLockOptions = {}
  ) {
    this.filePath = path.join(stateDir, "fact-hashes.txt");
    this.secureStoreKeyProvider = secureStoreKeyProvider;
    this.secureStoreWriteKeyProvider = secureStoreWriteKeyProvider;
    this.memoryDir = memoryDir;
    this.lockOptions = lockOptions;
  }
  /** Whether a caller with an authoritative corpus must rebuild this legacy index. */
  get requiresFormatMigration(): boolean {
    return this.formatMigrationRequired;
  }

  /** Load existing hashes from disk. Safe to call multiple times. */
  async load(): Promise<void> {
    try {
      const raw = await readMaybeEncryptedFile(this.filePath, this.secureStoreKeyProvider(), this.memoryDir);
      const parsed = parseHashIndex(raw);
      this.formatMigrationRequired = !parsed.versioned;
      if (!parsed.versioned) {
        // Hashes from the pre-NFC format are unsafe after normalization changes.
        // Ignore them until an authoritative corpus rebuild publishes v2.
        this.hashes.clear();
        log.warn(`content-hash index: ignored legacy unversioned index at ${this.filePath}`);
      } else {
        for (const hash of parsed.hashes) this.hashes.add(hash);
      }
      log.debug(`content-hash index: loaded ${this.hashes.size} hashes`);
    } catch (err) {
      if (err instanceof SecureStoreLockedError) throw err;
      if (!isErrnoCode(err, "ENOENT")) throw err;
      log.debug("content-hash index: no existing index — starting fresh");
    }
    // The loaded set now reflects the on-disk file — baseline the fingerprint so
    // a later peer write is detectable (PR #2016 review).
    await this.captureSyncedFingerprint();
  }

  /** Cheap `stat` of the durable index file; null when it does not exist yet. */
  private async statIndexFile(): Promise<DiskFingerprint | null> {
    try {
      const s = await stat(this.filePath);
      return {
        mtimeMs: s.mtimeMs,
        size: s.size,
        dev: s.dev,
        ino: s.ino,
        ctimeMs: s.ctimeMs,
        birthtimeMs: s.birthtimeMs,
      };
    } catch (err) {
      if (isErrnoCode(err, "ENOENT")) return null;
      throw err;
    }
  }

  /** Record the current on-disk fingerprint as this instance's synced baseline. */
  private async captureSyncedFingerprint(): Promise<void> {
    try {
      this.lastSyncedFingerprint = await this.statIndexFile();
    } catch (err) {
      // A stat failure other than ENOENT leaves no baseline; the next freshness
      // check reports non-current and the caller confirms against the corpus.
      this.lastSyncedFingerprint = null;
      log.debug(`content-hash index: could not fingerprint ${this.filePath}: ${err}`);
    }
  }

  /**
   * True when the durable index file is unchanged since this instance last
   * synced it (load / save / reconcile). False when a peer advanced it, when
   * the file appeared or vanished, or when freshness cannot be established
   * (stat error) — the caller then treats the in-memory snapshot as
   * non-authoritative and confirms a dedup miss against the durable corpus.
   * The stat includes file identity and generation metadata so same-size,
   * same-mtime atomic replacements are detected without reading the file body.
   */
  async isDiskFingerprintCurrent(): Promise<boolean> {
    let current: DiskFingerprint | null;
    try {
      current = await this.statIndexFile();
    } catch {
      return false;
    }
    const last = this.lastSyncedFingerprint;
    if (last === null || current === null) {
      return last === null && current === null;
    }
    return (
      current.mtimeMs === last.mtimeMs &&
      current.size === last.size &&
      current.dev === last.dev &&
      current.ino === last.ino &&
      current.ctimeMs === last.ctimeMs &&
      current.birthtimeMs === last.birthtimeMs
    );
  }

  /** Check if content already exists in the index. */
  has(content: string): boolean {
    return this.hashes.has(ContentHashIndex.computeHash(content));
  }

  /** Add content hash to the index. */
  add(content: string): void {
    const hash = ContentHashIndex.computeHash(content);
    // A re-add supersedes a pending removal of the same hash (round 8 thread 3).
    this.removed.delete(hash);
    // Record OUR durable delta even when the local snapshot already holds the
    // hash (PR #2016 thread SD-nG): local membership can be STALE — a peer
    // removed this hash on disk while this instance kept it in memory. Skipping
    // `added`/`dirty` on that path let the reconciling save compute
    // (on-disk \ removed) ∪ added and silently drop the reintroduced hash, so
    // the peer never saw it again. Set semantics keep this idempotent (no
    // duplicate entries) and the `removed.delete` above preserves remove/add
    // ordering.
    this.hashes.add(hash);
    this.added.add(hash);
    this.dirty = true;
  }

  get size(): number {
    return this.hashes.size;
  }

  /** Clear all loaded hashes so the next save rewrites the index from scratch. */
  clear(): void {
    if (this.hashes.size > 0) {
      this.hashes.clear();
    }
    // The fact-only partition is rebuilt with the shared set on every
    // authoritative corpus rebuild, so it clears here too (issue #2474).
    this.factHashes.clear();
    // A full clear is always paired with a plain overwrite save() (rebuild);
    // pending per-hash add/remove deltas are subsumed by writing the rebuilt set.
    // Cancel any armed deferred-reconcile retry (PR #2016) so it cannot fire in
    // the clear→rebuild→save window and union the pre-clear on-disk rows back.
    this.added.clear();
    this.removed.clear();
    this.cancelReconcileRetry();
    this.dirty = true;
  }

  /** Persist index to disk if changed (plain whole-file overwrite). */
  async save(): Promise<void> {
    if (!this.dirty) return;
    await mkdir(path.dirname(this.filePath), { recursive: true });
    // Snapshot the deltas + overwrite body THIS save publishes BEFORE the write
    // yields the event loop. `writeMaybeEncryptedFile` materializes `serialized`
    // eagerly, then the disk await lets a concurrent same-process add()/remove()
    // land a late delta (PR #2016 thread PRRT_kwDORJXyws6SEBri). Clearing the
    // LIVE added/removed sets afterward — as the previous unconditional
    // clear()+`dirty = false` did — would drop that late hash from the index AND
    // leave no retry, so peers never see it until a corpus rebuild. Consume only
    // what we published; late deltas stay pending. Mirrors saveMergingWithDisk.
    const publishedAdded = new Set<string>(this.added);
    const publishedRemoved = new Set<string>(this.removed);
    const serialized = serializeHashIndex(this.hashes);
    await writeMaybeEncryptedFile(this.filePath, serialized, this.secureStoreWriteKeyProvider(), {}, this.memoryDir);
    this.formatMigrationRequired = false;
    // Consume ONLY the deltas this overwrite published; anything that arrived
    // during the awaits above remains pending for the next save.
    for (const h of publishedAdded) this.added.delete(h);
    for (const h of publishedRemoved) this.removed.delete(h);
    // Honest dirty state: true iff late deltas remain unpersisted.
    this.dirty = this.added.size > 0 || this.removed.size > 0;
    // This overwrite is now the on-disk state — re-baseline the freshness
    // fingerprint so our own write is not later mistaken for a peer's (PR #2016).
    await this.captureSyncedFingerprint();
    if (this.dirty) {
      // Late deltas landed mid-save: arm a bounded durable retry so they reach
      // disk even without a further batch save — never a silent in-memory-only
      // hash. The locked reconcile republishes only OUR delta onto the overwrite.
      this.scheduleReconcileRetry();
    } else {
      // Clean overwrite supersedes any pending deferred reconcile work.
      this.cancelReconcileRetry();
    }
    log.debug(`content-hash index: saved ${this.hashes.size} hashes`);
  }

  /**
   * Persist the index by RECONCILING with the latest on-disk state under a
   * cross-process lock (issue #1909). Used by the extraction-persist batch save
   * for BOTH append and removal batches, so appends and removals to the same
   * index serialize against each other:
   *   final = (on-disk \ this.removed) ∪ this.added
   * Note it re-applies only OUR local additions (`added`), NOT the loaded
   * snapshot (review round 9 finding 3): seeding from `this.hashes` would
   * resurrect a hash a peer removed on disk while we held a stale snapshot. This
   * preserves a concurrent writer's appended hashes (a blind overwrite would
   * drop them), never resurrects a removed hash, and never loses our additions.
   *
   * Hardening:
   *  - Dirty short-circuit (round 7 finding 3): when this instance neither added
   *    nor removed anything this run, skip the O(file) read+rewrite entirely.
   *  - Cross-process lock (round 7 finding 2): serialize the read→reconcile→write
   *    window on a per-file advisory lock. If the lock is NOT acquired (timeout),
   *    do NOT publish (round 9 finding 2): keep `dirty` set AND schedule a bounded
   *    durable background retry (PR #2016) that keeps re-attempting the locked
   *    publish until the deferred additions land — never an unlocked write that
   *    could clobber a peer, and never a silent "batch save complete" that leaves
   *    the addition in this process's memory only.
   */
  async saveMergingWithDisk(): Promise<void> {
    if (!this.dirty) return;
    // The advisory lock file lives beside the index — ensure the dir exists
    // before acquiring it (the index dir may not exist on a first write).
    await mkdir(path.dirname(this.filePath), { recursive: true });
    const publish = async (): Promise<void> => {
      // Snapshot the deltas this publish is responsible for. The read+rewrite
      // below yields the event loop, so a concurrent add()/remove() can land
      // new deltas while we await disk (PR #2016 thread SD7Tj). Consuming the
      // LIVE sets afterward would drop those late deltas AND clear `dirty`,
      // stranding them in no save at all. We consume only what we published;
      // anything that arrived meanwhile stays pending for the next save.
      const publishedAdded = new Set<string>(this.added);
      const publishedRemoved = new Set<string>(this.removed);
      const merged = new Set<string>(publishedAdded);
      try {
        const raw = await readMaybeEncryptedFile(this.filePath, this.secureStoreKeyProvider(), this.memoryDir);
        const parsed = parseHashIndex(raw);
        if (parsed.versioned) {
          for (const hash of parsed.hashes) {
            // Keep prior/concurrent on-disk hashes EXCEPT the ones we removed.
            if (!publishedRemoved.has(hash)) merged.add(hash);
          }
        } else {
          // Do not carry hashes from the pre-NFC format into a v2 write.
          log.warn(`content-hash index: discarded legacy unversioned entries from ${this.filePath}`);
        }
      } catch (err) {
        if (err instanceof SecureStoreLockedError) throw err;
        if (!isErrnoCode(err, "ENOENT")) throw err;
        // ENOENT → no on-disk index yet; write our additions as-is.
      }
      await mkdir(path.dirname(this.filePath), { recursive: true });
      await writeMaybeEncryptedFile(
        this.filePath,
        serializeHashIndex(merged),
        this.secureStoreWriteKeyProvider(),
        {},
        this.memoryDir
      );
      this.formatMigrationRequired = false;
      // Consume ONLY the deltas we just published; deltas that arrived during
      // the awaits above remain pending.
      for (const h of publishedAdded) this.added.delete(h);
      for (const h of publishedRemoved) this.removed.delete(h);
      // Fold any still-pending deltas onto the reconciled set so the in-memory
      // view stays consistent with what the next save will publish.
      for (const h of this.added) merged.add(h);
      for (const h of this.removed) merged.delete(h);
      this.hashes = merged;
      // Honest dirty state: true iff late deltas remain to be persisted. A
      // subsequent batch save or the shutdown flush drains them.
      this.dirty = this.added.size > 0 || this.removed.size > 0;
      // The reconciled set is now the on-disk state — re-baseline the freshness
      // fingerprint (captured under the held lock) so our own publish is not
      // later mistaken for a peer's advance (PR #2016 review).
      await this.captureSyncedFingerprint();
    };
    await withHeldFileLock(
      `${this.filePath}.lock`,
      {
        staleMs: CONTENT_HASH_INDEX_LOCK_STALE_MS,
        ...(this.lockOptions.maxWaitMs !== undefined ? { maxWaitMs: this.lockOptions.maxWaitMs } : {}),
        ...(this.lockOptions.pollMs !== undefined ? { pollMs: this.lockOptions.pollMs } : {}),
      },
      async (acquired) => {
        if (!acquired) {
          // Never publish unlocked (round 9 finding 2): keep dirty AND schedule a
          // durable background retry (PR #2016). Relying on an unguaranteed later
          // batch save silently left the addition in this process's memory only;
          // the retry keeps re-attempting the locked publish until the addition
          // lands on disk.
          log.warn(
            `content-hash index: lock not acquired for ${this.filePath}; deferring reconcile save (dirty retained, scheduling durable retry)`
          );
          this.scheduleReconcileRetry();
          return;
        }
        await publish();
        if (this.dirty) {
          // A concurrent add()/remove() landed during publish's disk awaits, so
          // deltas remain unpersisted (PR #2016 thread SD7Tj). Arm a bounded
          // durable retry so they reach disk even if no further batch save comes
          // — never leave a settled barrier over pending work.
          this.scheduleReconcileRetry();
        } else {
          // Published cleanly: any pending deferred retry is now satisfied.
          this.cancelReconcileRetry();
        }
      }
    );
    log.debug(`content-hash index: reconcile-saved ${this.hashes.size} hashes`);
  }

  /**
   * Rebuild-and-publish the index from an authoritative source (the durable
   * corpus) under the SAME per-file cross-process lock the reconciling
   * append/removal saves (`saveMergingWithDisk`) use (issue #1909 / PR #2016).
   * The `populate` callback runs WHILE the lock is held and MUST repopulate this
   * index from the corpus (`clear()` then `addByHash(...)` for every corpus
   * hash); the rebuilt set is then published with a plain overwrite that is now
   * serialized against every locked writer.
   *
   * This closes the finding where the previous unlocked clear→scan→save() could
   * overwrite a peer's newer lock-merged or deferred additions: a locked writer
   * that committed BEFORE the rebuild acquired the lock has its memory `.md` on
   * disk and is re-scanned; one that commits AFTER the rebuild releases
   * reconciles its additions on top of the freshly-published set. No union with
   * the raw on-disk file is performed, so the rebuild keeps its
   * garbage-collection property (orphaned hashes for deleted memories drop).
   *
   * Lock-acquisition failure is explicit and non-destructive: `populate` is NOT
   * run and nothing is written (never an unlocked overwrite). Returns true when
   * the rebuild was published under the lock, false when the lock timed out —
   * the caller keeps the index non-authoritative and retries on next use. Uses
   * the same non-reentrant file lock as the reconcile path, so it can never
   * deadlock with the deferred reconcile-retry: a concurrent locked writer (or a
   * fired retry) simply yields `acquired=false` after the bounded wait.
   */
  async rebuildUnderLock(populate: () => Promise<void>): Promise<boolean> {
    // The advisory lock file lives beside the index — ensure the dir exists
    // before acquiring it (the index dir may not exist on a first rebuild).
    await mkdir(path.dirname(this.filePath), { recursive: true });
    let published = false;
    await withHeldFileLock(
      `${this.filePath}.lock`,
      {
        staleMs: CONTENT_HASH_INDEX_LOCK_STALE_MS,
        ...(this.lockOptions.maxWaitMs !== undefined ? { maxWaitMs: this.lockOptions.maxWaitMs } : {}),
        ...(this.lockOptions.pollMs !== undefined ? { pollMs: this.lockOptions.pollMs } : {}),
      },
      async (acquired) => {
        if (!acquired) {
          // Never publish unlocked: a concurrent locked writer holds the lock,
          // so overwriting now could clobber its addition. Leave the index as-is
          // and let the caller retry the authoritative rebuild on next use.
          log.warn(
            `content-hash index: lock not acquired for ${this.filePath}; deferring authoritative rebuild (index left non-authoritative, retried on next use)`
          );
          return;
        }
        await populate();
        // Publish under the held lock. save() takes no lock (no re-entrancy) and
        // is a full overwrite that supersedes any pending add/remove deltas.
        await this.save();
        published = true;
      }
    );
    return published;
  }

  /**
   * True while a background durable reconcile-save retry is armed (PR #2016).
   * Test/introspection hook.
   */
  get hasPendingReconcileRetry(): boolean {
    return this.reconcileRetryTimer !== null;
  }

  /** True while this index has in-memory changes not yet published to disk. */
  get hasPendingChanges(): boolean {
    return this.dirty;
  }

  /**
   * Resolve once any armed background reconcile-save retry chain has settled —
   * either it published the deferred additions, or it exhausted its bounded
   * attempts and fell back to the corpus-rebuild safety net. Resolves
   * immediately when nothing is armed. Lets a caller (or a test) await the
   * eventual durability outcome of a lock-timed-out save.
   */
  async whenReconcileRetrySettled(): Promise<void> {
    await (this.reconcileRetryBarrier ?? Promise.resolve());
  }

  /**
   * Drive any deferred lock-timeout reconcile save to completion INLINE at a
   * lifecycle boundary (PR #2016 finding 3). The background retry timer is
   * `unref`'d so it never keeps a long-lived daemon alive — but a short-lived
   * writer (a one-shot CLI) can exit before it fires, leaving a durable fact
   * `.md` whose hash never reached `fact-hashes.txt` for peers that already
   * built their in-memory index. `orchestrator.destroy()` calls this so the
   * addition publishes before the process exits; long-lived hosts only reach it
   * at their own shutdown, so their in-flight retries keep running in the
   * background until then. Bounded by the same attempt ceiling as the background
   * retry; a permanently contended lock falls back to the corpus-rebuild-on-
   * restart safety net (the fact `.md` is already durable). No deadlock: each
   * attempt is the same non-reentrant, bounded-wait file lock.
   */
  async flushReconcileRetry(): Promise<void> {
    if (!this.dirty) return;
    const maxAttempts = this.lockOptions.retryMaxAttempts ?? CONTENT_HASH_INDEX_RETRY_MAX_ATTEMPTS;
    const baseMs = this.lockOptions.retryBaseMs ?? CONTENT_HASH_INDEX_RETRY_BASE_MS;
    for (let attempt = 0; this.dirty && attempt < maxAttempts; attempt += 1) {
      // Cancel the unref'd background timer — we drive the locked publish inline.
      if (this.reconcileRetryTimer) {
        clearTimeout(this.reconcileRetryTimer);
        this.reconcileRetryTimer = null;
      }
      await this.saveMergingWithDisk();
      if (!this.dirty) break;
      if (attempt < maxAttempts - 1) {
        const wait = Math.min(baseMs * 2 ** attempt, CONTENT_HASH_INDEX_RETRY_MAX_DELAY_MS);
        await new Promise<void>((resolve) => setTimeout(resolve, wait));
      }
    }
    // Clear any timer the final saveMergingWithDisk armed and settle the barrier
    // so awaiters unblock — the bounded inline drain has done its best.
    if (this.reconcileRetryTimer) {
      clearTimeout(this.reconcileRetryTimer);
      this.reconcileRetryTimer = null;
    }
    this.reconcileRetryAttempts = 0;
    this.settleReconcileRetry();
  }

  /**
   * Schedule ONE bounded, exponentially-backed-off background retry of the
   * deferred reconcile save (PR #2016). Reentrant-safe: an already-armed timer
   * short-circuits, so successive timed-out saves never stack duplicate retries.
   * When attempts are exhausted the chain settles without publishing — the
   * durable fact `.md` is on disk and a process restart rebuilds the index from
   * the corpus, so this degrades to that safety net, never a fatal failure.
   */
  private scheduleReconcileRetry(): void {
    if (this.reconcileRetryTimer) return; // one retry in flight — no duplicate/reentrant retries
    const maxAttempts = this.lockOptions.retryMaxAttempts ?? CONTENT_HASH_INDEX_RETRY_MAX_ATTEMPTS;
    if (this.reconcileRetryAttempts >= maxAttempts) {
      log.warn(
        `content-hash index: exhausted ${maxAttempts} deferred reconcile-save retries for ${this.filePath}; ` +
          `${this.added.size} addition(s) remain dirty in-memory (a process restart rebuilds the index from the durable corpus)`
      );
      this.reconcileRetryAttempts = 0;
      this.settleReconcileRetry();
      return;
    }
    if (!this.reconcileRetryBarrier) {
      this.reconcileRetryBarrier = new Promise<void>((resolve) => {
        this.reconcileRetryResolve = resolve;
      });
    }
    const attempt = this.reconcileRetryAttempts + 1;
    const baseMs = this.lockOptions.retryBaseMs ?? CONTENT_HASH_INDEX_RETRY_BASE_MS;
    const delay = Math.min(baseMs * 2 ** (attempt - 1), CONTENT_HASH_INDEX_RETRY_MAX_DELAY_MS);
    this.reconcileRetryTimer = setTimeout(() => {
      this.reconcileRetryTimer = null;
      this.reconcileRetryAttempts = attempt;
      void this.saveMergingWithDisk()
        .catch((err) => {
          // A publish-time I/O/encryption error (not a lock timeout) is best-effort:
          // log and let the corpus-rebuild safety net cover it rather than loop.
          log.warn(`content-hash index: deferred reconcile-save retry failed for ${this.filePath}: ${err}`);
        })
        .finally(() => {
          // If the attempt neither published (dirty cleared → cancelReconcileRetry)
          // nor re-armed a further retry, the chain has ended — settle the barrier.
          if (this.dirty && !this.reconcileRetryTimer) this.settleReconcileRetry();
        });
    }, delay);
    this.reconcileRetryTimer.unref?.();
  }

  /** Cancel any armed reconcile-save retry and settle the barrier (a publish landed). */
  private cancelReconcileRetry(): void {
    if (this.reconcileRetryTimer) {
      clearTimeout(this.reconcileRetryTimer);
      this.reconcileRetryTimer = null;
    }
    this.reconcileRetryAttempts = 0;
    this.settleReconcileRetry();
  }

  /** Resolve and clear the retry barrier if one is outstanding. */
  private settleReconcileRetry(): void {
    const resolve = this.reconcileRetryResolve;
    this.reconcileRetryBarrier = null;
    this.reconcileRetryResolve = null;
    resolve?.();
  }

  /** Remove a hash from the index (used when archiving/deleting). */
  remove(content: string): void {
    const hash = ContentHashIndex.computeHash(content);
    // Record the removal (round 8 thread 3) even when the hash is not in our
    // in-memory set — a reconciling save must still drop it from the latest
    // on-disk state. A removal supersedes a pending add. Always mark dirty.
    this.added.delete(hash);
    this.removed.add(hash);
    this.hashes.delete(hash);
    this.dirty = true;
  }

  /**
   * Remove a pre-computed SHA-256 hash directly from the index without
   * re-hashing.  Use this when the caller already holds the stored hash
   * (e.g. `memory.frontmatter.contentHash`) to avoid the double-hash bug
   * where `remove(hash)` would compute `hash(hash)` and never match the
   * entry.
   */
  removeByHash(hash: string): void {
    this.added.delete(hash);
    this.removed.add(hash);
    this.hashes.delete(hash);
    this.dirty = true;
  }

  /**
   * Add a pre-computed SHA-256 hash directly to the index without re-hashing.
   * Use this when the caller already holds the stored hash
   * (e.g. `memory.frontmatter.contentHash`) so that the index records the raw
   * content hash rather than re-hashing the citation-annotated body.
   *
   * @internal Only called from `StorageManager.ensureFactHashIndexAuthoritative`.
   * Not part of the public API — prefer `add(content)` for external callers.
   */
  addByHash(hash: string): void {
    // A re-add supersedes a pending removal of the same hash.
    this.removed.delete(hash);
    // Record OUR durable delta even when the local snapshot already holds the
    // hash (PR #2016 thread PRRT_kwDORJXyws6SEHve). Outside a rebuild
    // (StorageManager.addActiveFactContentHash on reactivation) local
    // membership can be STALE: a peer removed this hash on disk while this
    // instance kept it in memory. Skipping added/dirty on that path let the
    // reconciling save compute (on-disk \ removed) ∪ added and silently drop
    // the reintroduced hash, so the peer never saw it again. Set semantics keep
    // this idempotent (no duplicate entries) and the removed.delete above
    // preserves remove/add ordering. Mirrors add().
    this.hashes.add(hash);
    this.added.add(hash);
    this.dirty = true;
  }

  // ── Fact-only partition (issue #2474) ─────────────────────────────────
  // Folded here from StorageManager's parallel `factOnlyHashes` set, which had
  // to be kept in lockstep by hand on every add/remove/rebuild site. The
  // partition lives on the index instance, so every path that mutates the
  // shared set and needs fact-only truth mutates it in the same breath.

  /** Register fact content in BOTH the shared index and the fact-only partition. */
  addFact(content: string): void {
    this.addFactByHash(ContentHashIndex.computeHash(content));
  }

  /** Register a pre-computed fact hash in both the shared index and the fact-only partition. */
  addFactByHash(hash: string): void {
    this.addByHash(hash);
    this.factHashes.add(hash);
  }

  /** Fact-ONLY membership: has this content been registered as a fact? */
  hasFact(content: string): boolean {
    return this.factHashes.has(ContentHashIndex.computeHash(content));
  }

  /** Fact-ONLY membership for a pre-computed SHA-256 hash. */
  hasFactByHash(hash: string): boolean {
    return this.factHashes.has(hash);
  }

  /**
   * Drop fact-only partition membership WITHOUT touching the shared index.
   * The shared removal stays caller-owned: a shared hash is dropped only when
   * no other active memory holds it, while fact-only membership follows the
   * fact's own lifecycle (supersede/archive/promotion).
   */
  removeFactByHash(hash: string): void {
    this.factHashes.delete(hash);
  }

  /**
   * Resolve a pre-computed semantic hash to one deterministic corpus path.
   *
   * This lookup is separate from durable hash membership: `this.hashes` stays
   * one hash per line and `has(content)` keeps its existing raw-content contract.
   * Reconciliation supplies short-lived manifest rows where hash and path coexist.
   */
  static resolvePathByHash(hash: string, entries: Iterable<ContentHashPathEntry>): string | undefined {
    const canonicalHash = hash.toLowerCase();
    if (!/^[a-f0-9]{64}$/.test(canonicalHash)) return undefined;
    let canonicalPath: string | undefined;
    for (const entry of entries) {
      if (entry.contentHash.toLowerCase() !== canonicalHash || entry.path.length === 0) continue;
      if (canonicalPath === undefined || entry.path < canonicalPath) canonicalPath = entry.path;
    }
    return canonicalPath;
  }

  /** Normalize content (delegates to content-hash.ts for a single source of truth). */
  static normalizeContent(content: string): string {
    return normalizeContent(content);
  }

  /** Compute SHA-256 hash (delegates to content-hash.ts for a single source of truth). */
  static computeHash(content: string): string {
    return computeContentHash(content);
  }
}

import { execFile } from "node:child_process";
import { randomUUID } from "node:crypto";
import { mkdir, readFile, readdir, rename, stat, unlink, writeFile } from "node:fs/promises";
import path from "node:path";
import { promisify } from "node:util";
import { log } from "../logger.js";
import type { CaptureWriteLockLimitSource } from "../capture-write-lock-backoff.js";
import type { MemoryFile, MemoryFrontmatter } from "../types.js";
import { RECALL_FALLBACK_DIRS } from "../utils/category-dir.js";
import { isErrnoCode } from "../utils/errno.js";
import type { withHeldFileLock } from "../utils/serialize-mutations.js";
import {
  CONTENT_HASH_INDEX_RETRY_MAX_DELAY_MS,
  ContentHashIndex,
  type ContentHashIndexLockOptions,
} from "./content-hash-index.js";
import {
  TombstoneBlockedCaptureWriteLock,
  buildExplicitCaptureDedupKey,
} from "./tombstone-blocked-capture-mutation.js";
import type { OfflineSyncMemoryParser } from "./tombstone-blocked-capture-sync.js";
export {
  buildExplicitCaptureDedupKey,
  isTombstoneBlockedCaptureWriteLockBusy,
  normalizeExplicitCaptureContent,
} from "./tombstone-blocked-capture-mutation.js";
export {
  parseTombstoneBlockedOfflineSyncMemory,
  type OfflineSyncMemoryParser,
  TombstoneBlockedCaptureIndexHost,
} from "./tombstone-blocked-capture-sync.js";

const REBUILD_MAX_ATTEMPTS = 3;
const execFileAsync = promisify(execFile);
const REBUILD_RETRY_BASE_MS = 50;

const ABANDONED_MARKER_MIN_AGE_MS = 60_000;
const MARKER_PROCESS_START_TOLERANCE_MS = 2_000;
const DOTNET_UNIX_EPOCH_TICKS = 621_355_968_000_000_000;
const MARKER_PROCESS_STARTED_AT_MS = Date.now() - process.uptime() * 1000;

type RebuildMarker = {
  path: string;
  committed: boolean;
  pid?: number;
  ownerId?: string;
  createdAt?: number;
  processStartedAtMs?: number;
  malformed?: boolean;
};

export type TombstoneBlockedCaptureIndexOptions = {
  readonly stateDir: string;
  readonly memoryDir: string;
  readonly secureStoreKeyProvider: () => Buffer | null;
  readonly secureStoreWriteKeyProvider: () => Buffer | null;
  readonly lockOptions: () => ContentHashIndexLockOptions;
  /** Capture-write-lock limit source; undefined until converge installs limits. */
  readonly captureLockLimitSource?: () => CaptureWriteLockLimitSource | undefined;
  readonly readAllMemories: () => Promise<MemoryFile[]>;
  readonly readAllColdMemories: () => Promise<MemoryFile[]>;
  readonly parseMemory?: OfflineSyncMemoryParser;
  readonly withHeldFileLock?: typeof withHeldFileLock;
};

/**
 * Durable targeted deduplication for tombstone-blocked explicit captures.
 *
 * The active fact-hash index intentionally excludes blocked rows. This small
 * companion index keeps the blocked identity visible without making every
 * authoritative active-index miss scan the full corpus.
 */
export class TombstoneBlockedCaptureIndex {
  private readonly options: TombstoneBlockedCaptureIndexOptions;
  private index: ContentHashIndex | null = null;
  private loadPromise: Promise<ContentHashIndex> | null = null;
  private refreshPromise: Promise<ContentHashIndex> | null = null;
  private authoritative = false;
  private readonly captureWriteLock: TombstoneBlockedCaptureWriteLock;

  constructor(options: TombstoneBlockedCaptureIndexOptions) {
    this.options = options;
    this.captureWriteLock = new TombstoneBlockedCaptureWriteLock({
      stateDir: options.stateDir,
      withHeldFileLock: options.withHeldFileLock,
      lockOptions: options.captureLockLimitSource,
    });
  }

  private createIndex(): ContentHashIndex {
    return new ContentHashIndex(
      path.join(this.options.stateDir, "tombstone-blocked-capture"),
      this.options.secureStoreKeyProvider,
      this.options.secureStoreWriteKeyProvider,
      this.options.memoryDir,
      this.options.lockOptions()
    );
  }

  private indexPath(): string {
    return path.join(this.options.stateDir, "tombstone-blocked-capture", "fact-hashes.txt");
  }

  private rebuildMarkerPath(): string {
    return path.join(this.options.stateDir, "tombstone-blocked-capture", "rebuild-required");
  }

  private async readRebuildMarkers(): Promise<RebuildMarker[]> {
    try {
      const entries = (await readdir(this.rebuildMarkerPath())).filter((entry) => !entry.startsWith("."));
      return (
        await Promise.all(
          entries.map(async (entry) => {
            const markerPath = path.join(this.rebuildMarkerPath(), entry);
            try {
              const raw = (await readFile(markerPath, "utf8")).trim();
              if (raw === "committed") return { path: markerPath, committed: true };
              let value: Record<string, unknown>;
              let malformed = false;
              try {
                const parsed = JSON.parse(raw) as unknown;
                if (!parsed || typeof parsed !== "object" || Array.isArray(parsed)) {
                  malformed = true;
                  value = {};
                } else {
                  value = parsed as Record<string, unknown>;
                }
              } catch {
                malformed = true;
                value = {};
              }
              const state = value.state;
              if (state !== "pending" && state !== "committed") malformed = true;
              const markerStat = await stat(markerPath).catch(() => null);
              // A torn payload can lose its JSON metadata, but the atomic
              // marker filename and filesystem mtime still identify its owner
              // and age. Preserve both so stale malformed markers can be
              // reaped without treating a fresh pre-commit gap as abandoned.
              const createdAt =
                typeof value.createdAt === "number" && Number.isFinite(value.createdAt)
                  ? value.createdAt
                  : markerStat?.mtimeMs;
              if (typeof value.pid !== "number" || !Number.isInteger(value.pid)) malformed = true;
              const ownerId =
                typeof value.ownerId === "string" && value.ownerId.length > 0
                  ? value.ownerId
                  : path.basename(markerPath);
              if (typeof value.ownerId !== "string" || value.ownerId.length === 0) malformed = true;
              const processStartedAtMs =
                typeof value.processStartedAtMs === "number" &&
                Number.isFinite(value.processStartedAtMs) &&
                value.processStartedAtMs > 0
                  ? value.processStartedAtMs
                  : undefined;
              return {
                path: markerPath,
                committed: state === "committed",
                ...(typeof value.pid === "number" && Number.isInteger(value.pid) ? { pid: value.pid } : {}),
                ...(ownerId.length > 0 ? { ownerId } : {}),
                ...(typeof createdAt === "number" && Number.isFinite(createdAt) ? { createdAt } : {}),
                ...(processStartedAtMs === undefined ? {} : { processStartedAtMs }),
                ...(malformed ? { malformed: true } : {}),
              };
            } catch (err) {
              if (isErrnoCode(err, "ENOENT")) return null;
              throw err;
            }
          })
        )
      ).filter((marker): marker is RebuildMarker => marker !== null);
    } catch (err) {
      if (isErrnoCode(err, "ENOENT")) return [];
      throw err;
    }
  }
  private async isAbandonedMarker(marker: RebuildMarker): Promise<boolean> {
    if (marker.committed || marker.createdAt === undefined) return false;
    if (Date.now() - marker.createdAt < ABANDONED_MARKER_MIN_AGE_MS) return false;
    if (marker.malformed) return true;
    return marker.pid !== undefined && !(await this.isProcessAlive(marker.pid, marker.processStartedAtMs));
  }

  private async isProcessAlive(pid: number, processStartedAtMs?: number): Promise<boolean> {
    try {
      process.kill(pid, 0);
    } catch (err) {
      return !isErrnoCode(err, "ESRCH");
    }
    if (processStartedAtMs === undefined) return true;
    const runningStartedAtMs = await this.readProcessStartedAtMs(pid);
    if (runningStartedAtMs === null) return true;
    return runningStartedAtMs <= processStartedAtMs + MARKER_PROCESS_START_TOLERANCE_MS;
  }
  private async readProcessStartedAtMs(pid: number): Promise<number | null> {
    try {
      if (process.platform === "win32") {
        const { stdout } = await execFileAsync(
          "powershell.exe",
          [
            "-NoLogo",
            "-NoProfile",
            "-NonInteractive",
            "-Command",
            `(Get-Process -Id ${pid} -ErrorAction Stop).StartTime.ToUniversalTime().Ticks`,
          ],
          { encoding: "utf8", timeout: 1_000 }
        );
        const ticks = Number(stdout.trim());
        return Number.isFinite(ticks) ? (ticks - DOTNET_UNIX_EPOCH_TICKS) / 10_000 : null;
      }
      const { stdout } = await execFileAsync("ps", ["-p", String(pid), "-o", "lstart="], {
        encoding: "utf8",
        timeout: 1_000,
      });
      const output = stdout.trim();
      if (!output) return null;
      const startedAtMs = Date.parse(output);
      return Number.isFinite(startedAtMs) ? startedAtMs : null;
    } catch {
      return null;
    }
  }

  private async getClearableRebuildMarkerPaths(markers: readonly RebuildMarker[]): Promise<string[]> {
    const paths = await Promise.all(
      markers.map(async (marker) => (marker.committed || (await this.isAbandonedMarker(marker)) ? marker.path : null))
    );
    return paths.filter((markerPath): markerPath is string => markerPath !== null);
  }

  private async getRebuildMarkers(): Promise<RebuildMarker[]> {
    return await this.readRebuildMarkers();
  }

  // A pending marker protects the pre-commit gap; only committed markers are safe for another writer to clear.
  private async writeMarkerAtomically(markerPath: string, payload: string): Promise<void> {
    const temporaryPath = `${markerPath}.tmp-${process.pid}-${randomUUID()}`;
    try {
      await writeFile(temporaryPath, payload, "utf8");
      await rename(temporaryPath, markerPath);
    } finally {
      await unlink(temporaryPath).catch((err: unknown) => {
        if (!isErrnoCode(err, "ENOENT")) throw err;
      });
    }
  }

  private async markRebuildRequired(committed = false): Promise<string> {
    const markerDir = this.rebuildMarkerPath();
    await mkdir(markerDir, { recursive: true });
    const ownerId = randomUUID();
    const markerPath = path.join(markerDir, ownerId);
    await this.writeMarkerAtomically(
      markerPath,
      `${JSON.stringify({
        state: committed ? "committed" : "pending",
        pid: process.pid,
        ownerId,
        createdAt: Date.now(),
        processStartedAtMs: MARKER_PROCESS_STARTED_AT_MS,
      })}\n`
    );
    return markerPath;
  }

  private async markRebuildCommitted(markerPath: string): Promise<void> {
    await this.writeMarkerAtomically(
      markerPath,
      `${JSON.stringify({
        state: "committed",
        pid: process.pid,
        ownerId: path.basename(markerPath),
        createdAt: Date.now(),
        processStartedAtMs: MARKER_PROCESS_STARTED_AT_MS,
      })}\n`
    );
  }

  private async clearRebuildRequired(markerPaths: readonly string[]): Promise<void> {
    await Promise.all(
      markerPaths.map(async (markerPath) => {
        try {
          await unlink(markerPath);
        } catch (err) {
          if (!isErrnoCode(err, "ENOENT")) throw err;
        }
      })
    );
  }

  private async hasRebuildRequired(excludedMarkers: readonly string[] = []): Promise<boolean> {
    const excluded = new Set(excludedMarkers);
    return (await this.getRebuildMarkers()).some((marker) => !excluded.has(marker.path));
  }

  private async setAuthoritative(rebuilt: boolean): Promise<void> {
    this.authoritative = rebuilt && !(await this.getRebuildMarkers()).some((marker) => !marker.committed);
  }
  private isBlocked(memory: MemoryFile): boolean {
    return memory.frontmatter.status === "pending_review" && Boolean(memory.frontmatter.blockedBy);
  }

  private async rebuild(index: ContentHashIndex): Promise<boolean> {
    return await index.rebuildUnderLock(async () => {
      index.clear();
      const existing = [...(await this.options.readAllMemories()), ...(await this.options.readAllColdMemories())];
      for (const memory of existing) {
        if (!this.isBlocked(memory)) continue;
        index.add(
          buildExplicitCaptureDedupKey(memory.content, memory.frontmatter.category, memory.frontmatter.sourceConnector)
        );
      }
    });
  }

  private async hasPersistedIndexOrMarkers(): Promise<boolean> {
    try {
      await stat(this.indexPath());
      return true;
    } catch (err) {
      if (!isErrnoCode(err, "ENOENT")) throw err;
      return (await this.readRebuildMarkers()).length > 0;
    }
  }

  private async getIndex(): Promise<ContentHashIndex> {
    if (this.index) return this.index;
    if (!this.loadPromise) {
      const index = this.createIndex();
      this.loadPromise = (async () => {
        await index.load();
        const rebuildMarkers = await this.getRebuildMarkers();
        const clearableRebuildMarkers = await this.getClearableRebuildMarkerPaths(rebuildMarkers);
        let persisted = !index.requiresFormatMigration;
        try {
          await stat(this.indexPath());
          if (rebuildMarkers.length > 0) persisted = false;
        } catch (err) {
          if (isErrnoCode(err, "ENOENT")) persisted = false;
          else throw err;
        }
        if (!persisted) {
          const lockOptions = this.options.lockOptions();
          const maxAttempts = lockOptions.retryMaxAttempts ?? REBUILD_MAX_ATTEMPTS;
          const baseMs = lockOptions.retryBaseMs ?? REBUILD_RETRY_BASE_MS;
          let rebuilt = false;
          for (let attempt = 0; attempt < maxAttempts; attempt += 1) {
            rebuilt = await this.rebuild(index);
            if (rebuilt || attempt === maxAttempts - 1) break;
            const wait = Math.min(baseMs * 2 ** attempt, CONTENT_HASH_INDEX_RETRY_MAX_DELAY_MS);
            const delayState = Promise.withResolvers<void>();
            setTimeout(delayState.resolve, wait);
            await delayState.promise;
          }
          if (!rebuilt) {
            throw new Error("tombstone-blocked capture index rebuild lock unavailable");
          }
          await this.clearRebuildRequired(clearableRebuildMarkers);
        }
        await this.setAuthoritative(true);
        this.index = index;
        return index;
      })().catch((err) => {
        this.loadPromise = null;
        throw err;
      });
    }
    return this.loadPromise;
  }

  async withCaptureWriteLock<T>(task: () => Promise<T>, identity?: string | readonly string[]): Promise<T> {
    return await this.captureWriteLock.withCaptureWriteLock(task, identity);
  }

  async withCaptureWriteLockHashes<T>(task: () => Promise<T>, identityHashes: readonly string[]): Promise<T> {
    return await this.captureWriteLock.withCaptureWriteLockHashes(task, identityHashes);
  }
  async withCaptureWriteLockAndHashes<T>(
    task: () => Promise<T>,
    identity: string | readonly string[] | undefined,
    identityHashes: readonly string[]
  ): Promise<T> {
    return await this.captureWriteLock.withCaptureWriteLockAndHashes(task, identity, identityHashes);
  }

  private async reload(): Promise<ContentHashIndex> {
    if (!this.refreshPromise) {
      this.refreshPromise = (async () => {
        this.index = null;
        this.loadPromise = null;
        return await this.getIndex();
      })().finally(() => {
        this.refreshPromise = null;
      });
    }
    return this.refreshPromise;
  }

  /** Return blocked-row membership and authority from one index snapshot. */
  async check(
    content: string,
    category: string,
    sourceConnector?: string
  ): Promise<{ has: boolean; authoritative: boolean }> {
    const key = buildExplicitCaptureDedupKey(content, category, sourceConnector);
    let index = await this.getIndex();
    if ((await this.hasRebuildRequired()) || !(await index.isDiskFingerprintCurrent())) {
      index = await this.reload();
    }
    return { has: index.has(key), authoritative: this.authoritative };
  }

  /** Return whether a blocked row matches this explicit-capture identity. */
  async has(content: string, category: string, sourceConnector?: string): Promise<boolean> {
    return (await this.check(content, category, sourceConnector)).has;
  }

  /** Return whether the in-memory index is safe to answer an authoritative miss. */
  async isAuthoritative(): Promise<boolean> {
    const index = await this.getIndex();
    if ((await this.hasRebuildRequired()) || !(await index.isDiskFingerprintCurrent())) {
      await this.reload();
    }
    return this.authoritative;
  }

  /** Reserve durable rebuild intent before a blocked memory file is committed. */
  async prepareWrite(): Promise<string> {
    return this.markRebuildRequired();
  }

  /** Mark a prepared write committed once its memory file is durable. */
  async commitWrite(rebuildMarker: string): Promise<void> {
    await this.markRebuildCommitted(rebuildMarker);
  }

  /** Drop a pending marker when the protected memory write never commits. */
  async discardWrite(rebuildMarker: string): Promise<void> {
    await this.clearRebuildRequired([rebuildMarker]);
  }

  /** Add a newly persisted blocked row to the durable targeted index. */
  async add(memory: MemoryFile, rebuildMarker?: string): Promise<void> {
    if (!this.isBlocked(memory)) return;
    let index = await this.getIndex();
    if (
      (await this.hasRebuildRequired(rebuildMarker ? [rebuildMarker] : [])) ||
      !(await index.isDiskFingerprintCurrent())
    ) {
      index = await this.reload();
    }
    index.add(
      buildExplicitCaptureDedupKey(memory.content, memory.frontmatter.category, memory.frontmatter.sourceConnector)
    );
    const marker = rebuildMarker ?? (await this.markRebuildRequired(true));
    if (rebuildMarker) await this.markRebuildCommitted(rebuildMarker);
    await index.saveMergingWithDisk();
    await index.flushReconcileRetry();
    if (index.hasPendingChanges) {
      this.markUntrusted();
      return;
    }
    await this.clearRebuildRequired([marker]);
    await this.setAuthoritative(true);
  }

  /** Rebuild the index after a blocked row changes or is removed. */
  async rebuildIfLoaded(ownedMarker?: string): Promise<void> {
    const index = this.index ?? ((await this.hasPersistedIndexOrMarkers()) ? this.getIndex() : null);
    if (!index) return;
    const rebuildMarkers = await this.getRebuildMarkers();
    const rebuildMarker = await this.markRebuildRequired(true);
    const clearableRebuildMarkers = await this.getClearableRebuildMarkerPaths(rebuildMarkers);
    const rebuilt = await this.rebuild(await index);
    if (rebuilt) {
      await this.clearRebuildRequired([
        ...clearableRebuildMarkers,
        ...(ownedMarker === undefined || clearableRebuildMarkers.includes(ownedMarker) ? [] : [ownedMarker]),
        rebuildMarker,
      ]);
    }
    await this.setAuthoritative(rebuilt);
  }

  /** Rebuild when either side of a write is blocked and its identity changed. */
  async sync(before: MemoryFile, after: MemoryFile, rebuildMarker?: string): Promise<void> {
    const beforeBlocked = this.isBlocked(before);
    const afterBlocked = this.isBlocked(after);
    if (!beforeBlocked && !afterBlocked) return;
    const beforeKey = buildExplicitCaptureDedupKey(
      before.content,
      before.frontmatter.category,
      before.frontmatter.sourceConnector
    );
    const afterKey = buildExplicitCaptureDedupKey(
      after.content,
      after.frontmatter.category,
      after.frontmatter.sourceConnector
    );
    if (beforeBlocked && afterBlocked && beforeKey === afterKey) {
      if (rebuildMarker) {
        await this.markRebuildCommitted(rebuildMarker);
        await this.clearRebuildRequired([rebuildMarker]);
      }
      return;
    }
    const existingMarkers = await this.getRebuildMarkers();
    const marker = rebuildMarker ?? (await this.markRebuildRequired(true));
    const clearableExistingMarkers = await this.getClearableRebuildMarkerPaths(existingMarkers);
    if (rebuildMarker) await this.markRebuildCommitted(rebuildMarker);
    const rebuilt = await this.rebuild(await this.getIndex());
    if (rebuilt) {
      await this.clearRebuildRequired([...clearableExistingMarkers, marker]);
    }
    await this.setAuthoritative(rebuilt);
  }
  markUntrusted(): void {
    this.authoritative = false;
  }

  private async failOpen(operation: string, action: () => Promise<void>): Promise<void> {
    try {
      await action();
    } catch (err) {
      this.markUntrusted();
      log.warn(`storage.${operation} completed but failed to update tombstone-blocked capture index: ${err}`);
    }
  }

  async addWrittenMemory(
    pathname: string,
    frontmatter: MemoryFrontmatter,
    content: string,
    rebuildMarker?: string
  ): Promise<void> {
    await this.failOpen("writeMemory", () => this.add({ path: pathname, frontmatter, content }, rebuildMarker));
  }

  async rebuildAfterInvalidation(ownedMarker?: string): Promise<void> {
    await this.failOpen("invalidateMemory", () => this.rebuildIfLoaded(ownedMarker));
  }

  /**
   * Drop an already-committed write marker without re-reading the corpus. The
   * offline-sync mutation path commits its marker around the file write, then
   * must clear it even when the write cannot have changed the blocked key set
   * (neither side tombstone-blocked) — otherwise the marker lingers until some
   * later rebuild clears it. Mirrors the tail of `add`/`sync`.
   */
  async clearCommittedWriteMarker(rebuildMarker: string): Promise<void> {
    await this.clearRebuildRequired([rebuildMarker]);
    // getIndex() may have rebuilt while this marker was still pending and
    // left authoritative=false. After the marker is gone, restore authority
    // if no other uncommitted marker remains.
    await this.setAuthoritative(true);
  }

  async syncUpdatedMemory(
    before: MemoryFile,
    frontmatter: MemoryFrontmatter,
    content: string,
    rebuildMarker?: string
  ): Promise<void> {
    await this.failOpen("updateMemory", () => this.sync(before, { ...before, frontmatter, content }, rebuildMarker));
  }

  async syncUpdatedFrontmatter(
    before: MemoryFile,
    frontmatter: MemoryFrontmatter,
    rebuildMarker?: string
  ): Promise<void> {
    await this.failOpen("writeMemoryFrontmatter", () => this.sync(before, { ...before, frontmatter }, rebuildMarker));
  }
  shouldRebuildAfterInvalidationForPath(filePath: string): boolean {
    const relative = path.relative(path.resolve(this.options.memoryDir), path.resolve(filePath));
    const category = relative.split(path.sep)[0];
    return category === "cold" || RECALL_FALLBACK_DIRS.includes(category);
  }
}

import { AsyncLocalStorage } from "node:async_hooks";
import { createHash } from "node:crypto";
import { mkdir } from "node:fs/promises";
import path from "node:path";
import { raceAbort, throwIfAborted } from "../abort-error.js";
import {
  CAPTURE_WRITE_LOCK_BUSY_MESSAGE,
  type CaptureWriteLockLimitSource,
  captureWriteLockDelayMs,
  resolveCaptureWriteLockBackoffLimits,
} from "../capture-write-lock-backoff.js";
import { log } from "../logger.js";
import type { MemoryFile, MemoryFrontmatter } from "../types.js";
import { withHeldFileLock } from "../utils/serialize-mutations.js";
import { sleepAbortable } from "../utils/sleep.js";
import type { CasRevisionTransaction } from "./cas-revision-store.js";

export { isTombstoneBlockedCaptureWriteLockBusy } from "../capture-write-lock-backoff.js";

const TOMBSTONE_CAPTURE_WRITE_LOCK_STALE_MS = 60_000;
/**
 * One exclusive-create probe. The bounded wait lives in the outer backoff,
 * which runs only after every lock from this attempt has been released.
 * A multi-second poll here would hold an already-acquired sibling lock.
 */
const CAPTURE_WRITE_LOCK_PROBE_MS = 1;
const CAPTURE_WRITE_LOCK_RETRY = Symbol("capture-write-lock-retry");
const CAPTURE_WRITE_LOCK_PERMANENT = Symbol("capture-write-lock-permanent-failure");

export function normalizeExplicitCaptureContent(value: string): string {
  return value.toLowerCase().replace(/\s+/g, " ").trim();
}

export function buildExplicitCaptureDedupKey(
  content: string,
  category: string,
  sourceConnector: string | undefined
): string {
  const encode = (label: string, value: string): string => `${label} ${value.length} ${value}`;
  return [
    encode("category", category),
    encode("connector", sourceConnector?.trim() ?? ""),
    encode("content", normalizeExplicitCaptureContent(content)),
  ].join(" ");
}

export function buildCapturePathLockIdentity(pathname: string): string {
  return `path ${pathname.length} ${pathname}`;
}

export function captureIdentityHash(memory: MemoryFile): string {
  return createHash("sha256")
    .update(
      buildExplicitCaptureDedupKey(memory.content, memory.frontmatter.category, memory.frontmatter.sourceConnector)
    )
    .digest("hex");
}

export type TombstoneBlockedCaptureWriteLockOptions = {
  readonly stateDir: string;
  readonly withHeldFileLock?: typeof withHeldFileLock;
  /** Read when an acquire starts, after the caller has installed converge config. */
  readonly lockOptions?: () => CaptureWriteLockLimitSource | undefined;
  readonly now?: () => number;
  readonly random?: () => number;
  readonly sleep?: (ms: number, signal?: AbortSignal) => Promise<void>;
  readonly logDebug?: (message: string) => void;
  readonly logWarn?: (message: string) => void;
  /** Direct seam. Converge passes the same signal through `lockOptions` instead. */
  readonly signal?: AbortSignal;
};

export class TombstoneBlockedCaptureWriteLock {
  private readonly context = new AsyncLocalStorage<ReadonlySet<string>>();

  constructor(private readonly options: TombstoneBlockedCaptureWriteLockOptions) {}

  private captureWriteLockPathForHash(identityHash: string): string {
    const filename =
      identityHash.length === 0 ? "explicit-capture-write.lock" : `explicit-capture-write-${identityHash}.lock`;
    return path.join(this.options.stateDir, "tombstone-blocked-capture", filename);
  }

  private now(): number {
    return this.options.now?.() ?? Date.now();
  }

  private debug(message: string): void {
    if (this.options.logDebug) {
      this.options.logDebug(message);
      return;
    }
    log.debug(message);
  }

  private warn(message: string): void {
    if (this.options.logWarn) {
      this.options.logWarn(message);
      return;
    }
    log.warn(message);
  }

  /** Prefer the constructor seam; converge installs the signal on lock options at acquire time. */
  private captureAbortSignal(): AbortSignal | undefined {
    return this.options.signal ?? this.options.lockOptions?.()?.captureWriteLockSignal;
  }

  /**
   * One probe of a single lock file. Returns the retry symbol when the lock
   * is busy and the permanent symbol on a filesystem error. Does not sleep:
   * the caller backs off only after the whole chain has unwound.
   */
  private async withSingleCaptureWriteLockOnce<T>(
    lockPath: string,
    task: () => Promise<T | typeof CAPTURE_WRITE_LOCK_RETRY>
  ): Promise<T | typeof CAPTURE_WRITE_LOCK_RETRY | typeof CAPTURE_WRITE_LOCK_PERMANENT> {
    await mkdir(path.dirname(lockPath), { recursive: true });
    const runWithHeldFileLock = this.options.withHeldFileLock ?? withHeldFileLock;
    return await runWithHeldFileLock(
      lockPath,
      {
        staleMs: TOMBSTONE_CAPTURE_WRITE_LOCK_STALE_MS,
        maxWaitMs: CAPTURE_WRITE_LOCK_PROBE_MS,
        pollMs: CAPTURE_WRITE_LOCK_PROBE_MS,
      },
      async (acquired, controller) => {
        if (acquired) return await task();
        return controller.failure === "error" ? CAPTURE_WRITE_LOCK_PERMANENT : CAPTURE_WRITE_LOCK_RETRY;
      }
    );
  }

  private async withPhysicalCaptureWriteLocks<T>(
    task: () => Promise<T>,
    identityHashes: readonly string[]
  ): Promise<T> {
    const signal = this.captureAbortSignal();
    const lockPaths = [...new Set(identityHashes.map((hash) => this.captureWriteLockPathForHash(hash)))];
    const limits = resolveCaptureWriteLockBackoffLimits(this.options.lockOptions?.());
    const deadline = this.now() + limits.deadlineMs;
    const giveUp = (): never => {
      throwIfAborted(signal);
      this.warn(
        `tombstone-blocked capture write lock remained busy after ${limits.deadlineMs}ms; failing this write so the rest of the cycle can continue`
      );
      throw new Error(CAPTURE_WRITE_LOCK_BUSY_MESSAGE);
    };
    const acquire = async (
      index: number
    ): Promise<T | typeof CAPTURE_WRITE_LOCK_RETRY | typeof CAPTURE_WRITE_LOCK_PERMANENT> => {
      throwIfAborted(signal);
      // The deadline gates each probe: a chain that started before the
      // deadline must not keep probing locks (or run the write) after it.
      const runTask = async (): Promise<T> => {
        if (this.now() >= deadline) giveUp();
        return await task();
      };
      if (index === lockPaths.length) return await runTask();
      const lockPath = lockPaths[index];
      if (lockPath === undefined) return await runTask();
      if (this.now() >= deadline) giveUp();
      return await this.withSingleCaptureWriteLockOnce(lockPath, () => acquire(index + 1));
    };
    for (let attempt = 0; ; attempt += 1) {
      throwIfAborted(signal);
      const outcome = await acquire(0);
      if (outcome === CAPTURE_WRITE_LOCK_PERMANENT) {
        throw new Error("tombstone-blocked capture write lock acquisition failed");
      }
      if (outcome !== CAPTURE_WRITE_LOCK_RETRY) return outcome;
      throwIfAborted(signal);
      const now = this.now();
      if (now >= deadline) giveUp();
      const delay = Math.min(
        captureWriteLockDelayMs(attempt, limits, this.options.random ?? Math.random),
        deadline - now
      );
      if (delay <= 0) giveUp();
      this.debug(`tombstone-blocked capture write lock busy; backing off ${delay}ms before retry ${attempt + 1}`);
      // raceAbort covers seam sleeps that ignore the signal; the default
      // sleepAbortable also clears its timer so abort holds no Timeout.
      await raceAbort((this.options.sleep ?? sleepAbortable)(delay, signal), signal);
    }
  }

  async withCaptureWriteLock<T>(task: () => Promise<T>, identity?: string | readonly string[]): Promise<T> {
    const identities =
      Array.isArray(identity) && identity.length > 0 ? identity : [typeof identity === "string" ? identity : ""];
    return await this.withCaptureWriteLocks(task, identities, []);
  }

  async withCaptureWriteLockHashes<T>(task: () => Promise<T>, identityHashes: readonly string[]): Promise<T> {
    return await this.withCaptureWriteLocks(task, [], identityHashes);
  }

  async withCaptureWriteLockAndHashes<T>(
    task: () => Promise<T>,
    identity: string | readonly string[] | undefined,
    identityHashes: readonly string[]
  ): Promise<T> {
    const identities =
      Array.isArray(identity) && identity.length > 0 ? identity : [typeof identity === "string" ? identity : ""];
    return await this.withCaptureWriteLocks(task, identities, identityHashes);
  }

  private async withCaptureWriteLocks<T>(
    task: () => Promise<T>,
    identities: readonly string[],
    identityHashes: readonly string[]
  ): Promise<T> {
    throwIfAborted(this.captureAbortSignal());
    const current = this.context.getStore();
    const hashToken = (key: string): string =>
      `\u0000${key.length === 0 ? "" : createHash("sha256").update(key).digest("hex")}`;
    const identityHash = (key: string): string =>
      key.length === 0 ? "" : createHash("sha256").update(key).digest("hex");
    const identityKeys = [...new Set(identities)];
    const hashes = [...new Set(identityHashes)];
    const requested = [
      ...identityKeys
        .filter((key) => !current || (!current.has(key) && !current.has(hashToken(key))))
        .map((key) => ({ hash: identityHash(key), pathLock: key.startsWith("path ") })),
      ...hashes.filter((hash) => !current || !current.has(`\u0000${hash}`)).map((hash) => ({ hash, pathLock: false })),
    ]
      .filter((entry, index, entries) => entries.findIndex((candidate) => candidate.hash === entry.hash) === index)
      .sort(
        (left, right) =>
          Number(left.pathLock) - Number(right.pathLock) ||
          this.captureWriteLockPathForHash(left.hash).localeCompare(this.captureWriteLockPathForHash(right.hash))
      );
    const physicalMissing = requested.map((entry) => entry.hash);
    if (current && requested.length > 0) {
      const held = [...current]
        .filter((token) => token.startsWith("\u0000"))
        .map((token) => {
          const hash = token.slice(1);
          const pathLock = [...current].some(
            (key) => !key.startsWith("\u0000") && key.startsWith("path ") && hashToken(key) === token
          );
          return { hash, pathLock };
        });
      const requestedFirst = requested[0];
      const heldLast = held
        .sort(
          (left, right) =>
            Number(left.pathLock) - Number(right.pathLock) ||
            this.captureWriteLockPathForHash(left.hash).localeCompare(this.captureWriteLockPathForHash(right.hash))
        )
        .at(-1);
      if (
        heldLast &&
        requestedFirst &&
        (Number(requestedFirst.pathLock) < Number(heldLast.pathLock) ||
          (requestedFirst.pathLock === heldLast.pathLock &&
            this.captureWriteLockPathForHash(requestedFirst.hash) < this.captureWriteLockPathForHash(heldLast.hash)))
      ) {
        throw new Error(CAPTURE_WRITE_LOCK_BUSY_MESSAGE);
      }
    }
    const next = new Set(current);
    for (const key of identityKeys) {
      next.add(key);
      next.add(hashToken(key));
    }
    for (const hash of hashes) next.add(`\u0000${hash}`);
    const run = () => {
      throwIfAborted(this.captureAbortSignal());
      return this.context.run(next, task);
    };
    if (physicalMissing.length === 0) return await run();
    return await this.withPhysicalCaptureWriteLocks(run, physicalMissing);
  }
}

export type TombstoneBlockedMutationHost = {
  readCurrent: () => Promise<MemoryFile | null>;
  isBlocked: (memory: MemoryFile | null) => boolean;
  isQueuedReview: (memory: MemoryFile | null) => boolean;
  memoryIdentity: (memory: MemoryFile) => string;
  prepareWrite: () => Promise<string>;
  commitWrite: (marker: string) => Promise<void>;
  discardWrite: (marker: string) => Promise<void>;
  markUntrusted: () => void;
  writeStorageSecureFile: (pathname: string, fileContent: string) => Promise<void>;
  withCaptureWriteLock: (task: () => Promise<void>, identity: string | readonly string[]) => Promise<void>;
  logWarning: (message: string) => void;
  beginDurableMemoryRevision?: (
    pathname: string,
    expectedContent?: string | Buffer | null
  ) => Promise<CasRevisionTransaction | undefined>;
};

export type TombstoneBlockedMutation = {
  blocked: boolean;
  pathname: string;
  fileContent: string;
  identity: string | readonly string[];
  updateIndex: (rebuildMarker?: string, current?: MemoryFile | null) => Promise<void>;
  beforeIndexUpdate?: () => Promise<void>;
  coordinate?: boolean;
  shouldMintRevision?: (current: MemoryFile | null) => boolean;
};

export async function runTombstoneBlockedMutation(
  host: TombstoneBlockedMutationHost,
  mutation: TombstoneBlockedMutation
): Promise<string | undefined> {
  let lockIdentity: string | readonly string[] = mutation.identity;
  for (;;) {
    let retryIdentity: string | undefined;
    let mintedRevision: string | undefined;
    const mutate = async (): Promise<void> => {
      const current = await host.readCurrent();
      const currentBlocked = host.isBlocked(current);
      const currentQueuedReview = host.isQueuedReview(current);
      if (current !== null && (mutation.coordinate === true || currentBlocked || currentQueuedReview)) {
        const currentIdentity = host.memoryIdentity(current);
        const heldIdentities = Array.isArray(lockIdentity) ? lockIdentity : [lockIdentity];
        if (!heldIdentities.includes(currentIdentity)) {
          retryIdentity = currentIdentity;
          return;
        }
      }
      const rebuildMarker = mutation.blocked || currentBlocked ? await host.prepareWrite() : undefined;
      const discardRebuildMarker = async (): Promise<void> => {
        if (!rebuildMarker) return;
        try {
          await host.discardWrite(rebuildMarker);
        } catch (cleanupError) {
          host.markUntrusted();
          host.logWarning(`storage.tombstoneBlocked failed to clear write marker: ${cleanupError}`);
        }
      };
      let transaction: CasRevisionTransaction | undefined;
      try {
        // #2813 (P1 C): a two-phase receipt transaction under this same
        // path lock. The PENDING reservation is minted BEFORE the durable
        // file publish, so a failed reservation leaves the memory file
        // untouched — never a mutated record without a receipt. The
        // COMMITTED receipt publishes only AFTER the write lands, so a
        // failed write can never leave the reservation posing as
        // ownership.
        transaction = mutation.shouldMintRevision?.(current)
          ? await host.beginDurableMemoryRevision?.(mutation.pathname, mutation.fileContent)
          : undefined;
        await host.writeStorageSecureFile(mutation.pathname, mutation.fileContent);
      } catch (err) {
        // The memory write failed (or never ran): abort the reservation so
        // no pending marker survives a write that did not land. A failed
        // abort keeps the marker — ambiguity, recovered later.
        if (transaction) {
          try {
            await transaction.abort();
          } catch (abortError) {
            host.logWarning(
              `storage.tombstoneBlocked failed to abort the reserved receipt (pending marker preserved): ${abortError}`
            );
          }
        }
        await discardRebuildMarker();
        throw err;
      }
      if (transaction) {
        // #2807: record the post-write fingerprint in the PENDING marker
        // BEFORE publishing, so a crash between the durable write and the
        // COMMITTED receipt is decisively recoverable. The evidence only
        // guards that crash window — a recording failure must not fail the
        // landed write, so commit still runs and publishes truthfully.
        try {
          await transaction.writeLanded();
        } catch (evidenceError) {
          host.logWarning(
            `storage.tombstoneBlocked failed to record receipt crash evidence (pending marker preserved): ${evidenceError}`
          );
        }
        try {
          await transaction.commit();
        } catch (err) {
          // #2813 (P1 C): the memory file LANDED but the COMMITTED receipt
          // never published. The PENDING marker stays: readers must see
          // unavailable/recovery-needed — never ownership, never absence —
          // and promotion/rollback refuse until recovery reconciles. The
          // reservation must NOT be aborted: the write is on disk.
          host.logWarning(
            `storage.tombstoneBlocked receipt publication failed after the memory write (pending marker preserved for recovery): ${err}`
          );
          await discardRebuildMarker();
          throw err;
        }
      }
      mintedRevision = transaction?.pendingRevision;
      if (rebuildMarker) {
        try {
          await host.commitWrite(rebuildMarker);
        } catch (err) {
          host.markUntrusted();
          host.logWarning(`storage.tombstoneBlocked committed write marker failed: ${err}`);
        }
      }
      if (rebuildMarker) await mutation.beforeIndexUpdate?.();
      await mutation.updateIndex(rebuildMarker, currentBlocked && current !== null ? current : undefined);
    };

    await host.withCaptureWriteLock(mutate, lockIdentity);
    if (retryIdentity === undefined) return mintedRevision;
    const identities = Array.isArray(lockIdentity) ? [...lockIdentity, retryIdentity] : [lockIdentity, retryIdentity];
    lockIdentity = [...new Set(identities)];
  }
}

export function tombstoneBlocked(frontmatter: MemoryFrontmatter): boolean {
  return frontmatter.status === "pending_review" && Boolean(frontmatter.blockedBy);
}

export function isQueuedReviewFrontmatter(frontmatter: MemoryFrontmatter): boolean {
  return frontmatter.status === "pending_review" && (frontmatter.tags ?? []).includes("queued-review");
}

export function isQueuedReviewMemory(memory: MemoryFile | null): memory is MemoryFile {
  return memory !== null && isQueuedReviewFrontmatter(memory.frontmatter);
}

