  resolvedCache.clear();
  _resolveApiKeyForProviderForTest = null;
  _getRuntimeAuthForModelForTest = null;
}

export function __setGatewayResolverForTest(resolver: ResolveApiKeyFn | null): void {
  _resolveApiKeyForProviderForTest = resolver;
}

