    "--cd",
    workspacePath,
    "--skip-git-repo-check",
    "--json",
    "--output-last-message",
    outputPath,
    "-",
  ];
}

function readReasoningEffort(config: CodexCliFallbackConfig): CodexCliReasoningEffort | undefined {
  for (const value of [config.codexCliReasoningEffort, config.reasoningEffort]) {
    if (typeof value === "string") {
      const normalized = value.trim().toLowerCase();
      if (normalized === "low" || normalized === "medium" || normalized === "high" || normalized === "xhigh") {
        return normalized;
      }
      throw new CodexSubscriptionConfigError(
        "codex-subscription reasoningEffort must be one of low, medium, high, xhigh (got unrecognized value)"
      );
    }
  }
  return undefined;
}

/**
 * One JSON object per message: role boundaries are structural (JSON string
 * escaping), so literal `[system]`/role-marker text inside message content
 * can never forge another role's turn. Content stays model-visible verbatim.
 */
function buildPrompt(messages: readonly CodexCliFallbackMessage[]): string {
  const transcript = messages
    .map((message) => JSON.stringify({ role: message.role, content: message.content }))
    .join("\n");
  return [
    "You are acting as an LLM completion endpoint for a memory-extraction pipeline, not as a coding agent.",
    "Answer the request in the transcript below. Do not inspect files, run commands, browse, or use tools.",
    "Return only the final answer text. If the request asks for JSON, return raw JSON only.",
    "",
    'TRANSCRIPT (JSON Lines: one {"role":"...","content":"..."} object per message; newlines inside content are escaped):',
    transcript,
  ].join("\n");
}

function execFailureError(
  result: CodexSubscriptionExecResult,
  timeoutMs: number,
  executable: string,
  env: NodeJS.ProcessEnv
): Error {
  const combined = `${result.stderr}\n${result.stdout}`;
  // The authoritative timeout marker wins over auth-pattern text: a timed-out
  // exec may have already printed model/diagnostic output containing 401/403
  // before the deadline fired (issue #2833).
  if (TIMEOUT_PATTERN.test(combined)) {
    return new CodexSubscriptionTimeoutError(timeoutMs);
  }
  if (AUTH_FAILURE_PATTERN.test(combined)) {
    // Re-check login on the next request; the cached status is now stale.
    loginStatusCache.delete(loginCacheKey(executable, env));
    return new CodexSubscriptionAuthError(
      "expired_or_revoked",
      "codex-subscription: the Codex CLI rejected the request as unauthenticated " +
        "(session expired or revoked). Run `codex login` again to re-authenticate, then retry."
    );
  }

  const exitLabel = result.signal ? `signal ${result.signal}` : `exit ${result.status ?? "unknown"}`;
  return new Error(
    `codex-subscription: codex exec failed (${exitLabel}): ${summarizeOutput(result.stderr, result.stdout)}`
  );
}

/** Secret-redacted, then bounded tail of child output — the only child text
 * that ever reaches a thrown error. Redaction runs BEFORE bounding so a
 * secret straddling the cutoff cannot survive as an unmatchable fragment. */
function summarizeOutput(stderr: string, stdout: string): string {
  const summary = [stderr.trim(), stdout.trim()].filter((part) => part.length > 0).join("\n");
  if (summary.length === 0) {
    return "no process output";
  }
  return redactSecretEchoes(summary).slice(-OUTPUT_SUMMARY_LIMIT);
}

export function redactSecretEchoes(value: string): string {
  let redacted = value;
  for (const pattern of SECRET_ECHO_PATTERNS) {
    redacted = redacted.replace(pattern, "[redacted]");
  }
  return redacted;
}
type CodexSubscriptionUsage = Pick<CodexCliFallbackResult, "usage">;

function usageFrom(result: CodexSubscriptionExecResult): CodexSubscriptionUsage {
  const usage = parseCodexJsonlUsage(`${result.stdout}\n${result.stderr}`);
  if (!usage) {
    return {};
  }
  return {
    usage: {
      inputTokens: usage.inputTokens,
      outputTokens: usage.outputTokens,
      totalTokens: usage.inputTokens + usage.outputTokens,
    },
  };
}

export function parseCodexJsonlUsage(output: string): { inputTokens: number; outputTokens: number } | undefined {
  let usage: { inputTokens: number; outputTokens: number } | undefined;
  for (const line of output.split(/\r?\n/)) {
    const trimmed = line.trim();
    if (!trimmed.startsWith("{")) continue;
    try {
      const event = JSON.parse(trimmed) as {
        type?: unknown;
        usage?: Record<string, unknown>;
      };
      if (event.type !== "turn.completed" || !event.usage) continue;
      const inputTokens = readCounter(event.usage.input_tokens);
      const outputTokens = readCounter(event.usage.output_tokens);
      if (inputTokens !== undefined && outputTokens !== undefined) {
        usage = { inputTokens, outputTokens };
      }
    } catch {
      // codex exec prints non-JSON status text alongside JSONL; ignore it
    }
  }
  return usage;
}

function readCounter(value: unknown): number | undefined {
  if (typeof value !== "number" || !Number.isFinite(value) || value < 0) {
    return undefined;
  }
  return value;
}

function abortErrorOf(signal: AbortSignal): Error {
  if (signal.reason instanceof CodexSubscriptionTimeoutError) return signal.reason;
  const reason =
    signal.reason instanceof Error
      ? signal.reason
      : signal.reason !== undefined
        ? new Error(String(signal.reason))
        : new DOMException("The operation was aborted.", "AbortError");
  const match = /fallback LLM timed out after (\d+)ms/i.exec(reason.message);
  if (match) {
    return new CodexSubscriptionTimeoutError(Number(match[1]));
  }
  return reason;
}

/** Bounds streamed child output to STDIO_LIMIT, keeping the TAIL — codex
 * prints its final error or turn.completed result last. Secrets are redacted
 * BEFORE bounding so one straddling the cutoff cannot leak a fragment. */
function appendBounded(existing: string, next: string): string {
  const redacted = redactSecretEchoes(existing + next);
  return redacted.length > STDIO_LIMIT ? redacted.slice(-STDIO_LIMIT) : redacted;
}

async function runLoginStatusSubprocess(
  executable: string,
  env: NodeJS.ProcessEnv,
  timeoutMs: number,
  signal: AbortSignal | undefined,
  children: Set<number>,
): Promise<{ status: number | null; stdout: string; stderr: string }> {
  return await runSubprocess(executable, ["login", "status"], {
    env,
    stdin: undefined,
    timeoutMs,
    timeoutLabel: "login status",
    signal,
    children,
  });
}

async function runCodexExecSubprocess(
  request: CodexSubscriptionExecRequest,
  children: Set<number>,
): Promise<CodexSubscriptionExecResult> {
  const result = await runSubprocess(request.executable, request.args, {
    env: request.env,
    stdin: request.input,
    timeoutMs: request.timeoutMs,
    timeoutLabel: "exec",
    signal: request.signal,
    cwd: request.workspacePath,
    children,
  });
  if (result.status === 124) return { ...result, outputText: "" };
  let outputText = "";
  try {
    outputText = (await readFile(request.outputPath, "utf8")).trim();
  } catch {
    // Missing output file surfaces as the no-final-message error path.
  }
  return { ...result, outputText };
}

interface SubprocessOptions {
  env: NodeJS.ProcessEnv;
  stdin?: string;
  timeoutMs?: number;
  timeoutLabel: string;
  signal?: AbortSignal;
  cwd?: string;
  children: Set<number>;
}

async function runSubprocess(executable: string, args: string[], options: SubprocessOptions): Promise<CommandOutput> {
  return await new Promise<CommandOutput>((resolve, reject) => {
    if (options.signal?.aborted) {
      reject(abortErrorOf(options.signal));
      return;
    }
    const child = launchProcess(executable, args, {
      ...(options.cwd ? { cwd: options.cwd } : {}),
      env: options.env,
      stdio: [options.stdin === undefined ? "ignore" : "pipe", "pipe", "pipe"],
      detached: process.platform !== "win32",
      windowsHide: true,
    });
    registerActiveCodexChild(child.pid, options.children);
    let stdout = "";
    let stderr = "";
    let timedOut = false;
    let settled = false;
    let killTimeout: ReturnType<typeof setTimeout> | undefined;
    const clearKillTimeout = (): void => {
      if (killTimeout) {
        clearTimeout(killTimeout);
        killTimeout = undefined;
      }
    };
    const terminate = (signal: NodeJS.Signals): void => {
      if (child.pid && process.platform !== "win32") {
        try {
          process.kill(-child.pid, signal);
          return;
        } catch {
          // fall through to killing the direct child
        }
      }
      child.kill(signal);
    };
    const scheduleForcedKill = (): void => {
      clearKillTimeout();
      killTimeout = setTimeout(() => terminate("SIGKILL"), 1_000);
      killTimeout.unref();
    };
    const finish = (fn: () => void): void => {
      if (settled) return;
      settled = true;
      clearTimeout(timeout);
      options.signal?.removeEventListener("abort", onAbort);
      fn();
    };
    const settleTimeout = (): void => {
      timedOut = true;
      stderr = appendBounded(
        stderr,
        `\ncodex-subscription: ${options.timeoutLabel} timed out after ${options.timeoutMs}ms.`
      );
      finish(() => {
        resolve({
          status: 124,
          signal: "SIGTERM",
          stdout,
          stderr,
        });
      });
    };
    const onAbort = (): void => {
      const reasonText =
        options.signal?.reason instanceof Error
          ? options.signal.reason.message
          : String(options.signal?.reason ?? "");
      terminate("SIGTERM");
      scheduleForcedKill();
      if (/fallback LLM timed out after \d+ms/i.test(reasonText)) {
        settleTimeout();
        return;
      }
      finish(() => reject(abortErrorOf(options.signal!)));
    };
    options.signal?.addEventListener("abort", onAbort, { once: true });
    const timeout = options.timeoutMs
      ? setTimeout(() => {
          terminate("SIGTERM");
          scheduleForcedKill();
          settleTimeout();
        }, options.timeoutMs)
      : undefined;
    timeout?.unref();
    child.stdout?.setEncoding("utf8");
    child.stderr?.setEncoding("utf8");
    child.stdout?.on("data", (chunk: string) => {
      stdout = appendBounded(stdout, chunk);
    });
    child.stderr?.on("data", (chunk: string) => {
      stderr = appendBounded(stderr, chunk);
    });
    child.stdin?.on("error", (error: NodeJS.ErrnoException) => {
      stderr = appendBounded(stderr, `\ncodex-subscription: stdin error: ${error.code ?? error.message}`);
    });
    child.on("error", (error) => {
      unregisterActiveCodexChild(child.pid, options.children);
      finish(() => {
        reject(
          child.pid
            ? new Error(`codex-subscription: codex CLI failed after start: ${safeMessage(error)}`, { cause: error })
            : new CodexSubscriptionAuthError(
                "unauthenticated",
                `codex-subscription: codex CLI not found at \`${executable}\` — install the Codex CLI and run \`codex login\` with a ChatGPT account, then retry.`
              )
        );
      });
    });
    child.on("close", (status, signal) => {
      clearKillTimeout();
      unregisterActiveCodexChild(child.pid, options.children);
      finish(() => {
        resolve({
          status: timedOut ? (status === null || status === 0 ? 124 : status) : status,
          signal: timedOut ? (signal ?? "SIGTERM") : signal,
          stdout,
          stderr,
        });
      });
    });
    if (options.stdin !== undefined) {
      try {
        child.stdin?.end(options.stdin);
      } catch (error) {
        log.debug(`codex-subscription: failed writing prompt to stdin: ${safeMessage(error)}`);
      }
    }
  });
}

function safeMessage(error: unknown): string {
  return error instanceof Error ? error.message : String(error);
}

export const __codexSubscriptionTestHooks = {
  activeCodexChildCount: (runner?: CodexCliFallbackRunner): number => {
    const target = runner ?? defaultRegisteredRunner;
    return target ? (childrenByRunner.get(target)?.size ?? 0) : 0;
  },
  appendBounded,
  resetLoginStatusCache: (): void => {
    loginStatusCache.clear();
  },
  isCoreRunnerRegistered: (): boolean => coreRunnerRegistered,
  resetCoreRunnerRegistered: (): void => {
    coreRunnerRegistered = false;
    defaultRegisteredRunner = undefined;
  },
};

function registerActiveCodexChild(pid: number | undefined, children: Set<number>): void {
  if (pid === undefined) return;
  children.add(pid);
}

function unregisterActiveCodexChild(pid: number | undefined, children: Set<number>): void {
  if (pid === undefined) return;
  children.delete(pid);
}

function terminateCodexChildPid(pid: number, signal: NodeJS.Signals): void {
  if (process.platform !== "win32") {
    try {
      process.kill(-pid, signal);
      return;
    } catch {
      // Fall back to killing the direct child below.
    }
  }

  try {
    process.kill(pid, signal);
  } catch {
    // The child may already have exited.
  }
}

import { mkdir, readFile, rename, rm, stat, writeFile } from "node:fs/promises";
import path from "node:path";

const DAY_SUMMARY_CRON_ID = "engram-day-summary";
const GOVERNANCE_CRON_ID = "engram-nightly-governance";
const PROCEDURAL_MINING_CRON_ID = "engram-procedural-mining";
const CONTRADICTION_SCAN_CRON_ID = "engram-contradiction-scan";
const PATTERN_REINFORCEMENT_CRON_ID = "engram-pattern-reinforcement";
const GRAPH_EDGE_DECAY_CRON_ID = "engram-graph-edge-decay";

type CronJobsShape =
  | Array<Record<string, unknown>>
  | {
      jobs: Array<Record<string, unknown>>;
      [key: string]: unknown;
    };

async function acquireCronJobsLock(jobsPath: string): Promise<() => Promise<void>> {
  const lockPath = `${jobsPath}.lock`;
  const start = Date.now();
  const staleMs = 30_000;
  const timeoutMs = 5_000;
  await mkdir(path.dirname(lockPath), { recursive: true });

  while (Date.now() - start < timeoutMs) {
    try {
      await mkdir(lockPath);
      return async () => {
        try {
          await rm(lockPath, { recursive: true, force: true });
        } catch {
          // Lock cleanup should not fail cron registration.
        }
      };
    } catch (error) {
      const code = (error as NodeJS.ErrnoException).code;
      if (code !== "EEXIST") {
        throw error;
      }
      try {
        const lockStat = await stat(lockPath);
        if (Date.now() - lockStat.mtimeMs > staleMs) {
          await rm(lockPath, { recursive: true, force: true });
          continue;
        }
      } catch {
        // Lock may have been released between stat/rm attempts.
      }
      await new Promise((resolve) => setTimeout(resolve, 25));
    }
  }

  throw new Error(`cron jobs lock acquisition timed out after ${timeoutMs}ms`);
}

function parseCronJobsShape(raw: string): { parsed: CronJobsShape; jobs: Array<Record<string, unknown>> } {
  const parsed = JSON.parse(raw) as CronJobsShape;
  const jobs = Array.isArray(parsed) ? parsed : Array.isArray(parsed.jobs) ? parsed.jobs : null;
  if (!jobs) {
    throw new Error("jobs.json has unexpected structure");
  }
  return { parsed, jobs };
}

async function writeCronJobsAtomic(jobsPath: string, value: CronJobsShape): Promise<void> {
  const tempPath = `${jobsPath}.${process.pid}.${Date.now()}.tmp`;
  await writeFile(tempPath, JSON.stringify(value, null, 2) + "\n", "utf-8");
  await rename(tempPath, jobsPath);
}

export async function ensureCronJob(
  jobsPath: string,
  jobId: string,
  buildJob: () => Record<string, unknown>,
  options: {
    updateExisting?: boolean;
    updateFields?: string[];
    deepMerge?: Record<string, unknown>;
  } = {},
): Promise<{ created: boolean; updated: boolean; jobId: string }> {
  const releaseLock = await acquireCronJobsLock(jobsPath);
  try {
    const raw = await readFile(jobsPath, "utf-8");
    const { parsed, jobs } = parseCronJobsShape(raw);

    const existingIndex = jobs.findIndex((job) => job.id === jobId);
    if (existingIndex >= 0) {
      if (!options.updateExisting) {
        return { created: false, updated: false, jobId };
      }

      const desired = buildJob();
      const existing = jobs[existingIndex];
      const next = mergeCronJobUpdate(existing, desired, options.updateFields, options.deepMerge);
      if (stableJson(existing) === stableJson(next)) {
        return { created: false, updated: false, jobId };
      }

      jobs[existingIndex] = next;
      const output = Array.isArray(parsed) ? jobs : { ...parsed, jobs };
      await writeCronJobsAtomic(jobsPath, output);
      return { created: false, updated: true, jobId };
    }

    jobs.push(buildJob());
    const output = Array.isArray(parsed) ? jobs : { ...parsed, jobs };
    await writeCronJobsAtomic(jobsPath, output);
    return { created: true, updated: false, jobId };
  } finally {
    await releaseLock();
  }
}

function deepMergeObjects(
  target: Record<string, unknown>,
  source: Record<string, unknown>,
): Record<string, unknown> {
  const result = { ...target };
  for (const [key, value] of Object.entries(source)) {
    if (value === null) {
      // null means "remove this key"
      delete result[key];
    } else if (
      value && typeof value === "object" && !Array.isArray(value) &&
      result[key] && typeof result[key] === "object" && !Array.isArray(result[key])
    ) {
      result[key] = deepMergeObjects(
        result[key] as Record<string, unknown>,
        value as Record<string, unknown>,
      );
    } else {
      result[key] = value;
    }
  }
  return result;
}

function mergeCronJobUpdate(
  existing: Record<string, unknown>,
  desired: Record<string, unknown>,
  updateFields?: string[],
  deepMerge?: Record<string, unknown>,
): Record<string, unknown> {
  let next = { ...existing };

  if (!updateFields && !deepMerge) {
    return desired;
  }

  if (updateFields) {
    for (const field of updateFields) {
      if (Object.prototype.hasOwnProperty.call(desired, field)) {
        next[field] = desired[field];
      } else {
        delete next[field];
      }
    }
  }

  if (deepMerge) {
    next = deepMergeObjects(next, deepMerge);
  }

  return next;
}

function stableJson(value: unknown): string {
  if (Array.isArray(value)) {
    return `[${value.map((item) => stableJson(item)).join(",")}]`;
  }
  if (value && typeof value === "object") {
    const record = value as Record<string, unknown>;
    return `{${Object.keys(record)
      .sort()
      .map((key) => `${JSON.stringify(key)}:${stableJson(record[key])}`)
      .join(",")}}`;
  }
  return JSON.stringify(value);
}

export async function ensureDaySummaryCron(
  jobsPath: string,
  options: {
    timezone: string;
    agentId?: string;
    /** Whether agentId was explicitly provided (vs defaulted to "main"). */
    hasExplicitAgentId?: boolean;
    /** Optional model override (e.g. from summaryModel or taskModelChain.primary). */
    model?: string;
    /** Optional fallbacks to include alongside the model. */
    fallbacks?: string[];
  },
): Promise<{ created: boolean; updated: boolean; jobId: string }> {
  const agentId =
    typeof options.agentId === "string" && options.agentId.trim().length > 0
      ? options.agentId.trim()
      : "main";
  const daySummaryParams = JSON.stringify({ timeZone: options.timezone });

  const payload: Record<string, unknown> = {
    kind: "agentTurn",
    timeoutSeconds: 900,
    thinking: "off",
    message:
      `You are OpenClaw automation. Call tool engram.day_summary with params ${daySummaryParams} (it will auto-gather today's facts for that timezone). If successful output exactly NO_REPLY. On error output one concise line. Do NOT use message tool.`,
  };
  if (options.model) {
    payload.model = options.model;
  }
  if (options.fallbacks && options.fallbacks.length > 0) {
    payload.fallbacks = options.fallbacks;
  }

  return ensureCronJob(
    jobsPath,
    DAY_SUMMARY_CRON_ID,
    () => ({
      id: DAY_SUMMARY_CRON_ID,
      agentId,
      name: "Remnic Day Summary (auto)",
      enabled: true,
      schedule: {
        kind: "cron",
        expr: "47 23 * * *",
        tz: options.timezone,
      },
      sessionTarget: "isolated",
      wakeMode: "now",
      // Mirror model at job root for backward compat with older OpenClaw
      // builds that read root model instead of payload.model.
      ...(options.model ? { model: options.model } : {}),
      payload,
      delivery: { mode: "none" },
    }),
    // Reconcile on every startup so model/timezone changes propagate.
    // Issue #1474 (model reconcile) + #1475 (timezone reconcile).
    // Only update managed leaves to avoid clobbering user edits to
    // schedule.expr, payload.message, payload.timeoutSeconds, etc.
    // Only reconcile agentId when explicitly provided, so manually-set
    // cron personas are preserved.
    {
      updateExisting: true,
      updateFields: options.hasExplicitAgentId ? ["agentId"] : [],
      deepMerge: {
        schedule: { tz: options.timezone },
        // Mirror model at job root for backward compat with older OpenClaw
        // builds that read root model instead of payload.model.
        model: options.model ?? null,
        // Always write model/fallbacks so stale values are cleared when
        // an operator removes summaryModel or taskModelChain from config.
        payload: {
          model: options.model ?? null,
          fallbacks: (options.fallbacks && options.fallbacks.length > 0)
            ? options.fallbacks
            : null,
        },
      },
    },
  );
}

export async function ensureNightlyGovernanceCron(
  jobsPath: string,
  options: {
    timezone: string;
    agentId?: string;
    recentDays?: number;
    maxMemories?: number;
    batchSize?: number;
    scheduleExpr?: string;
  },
): Promise<{ created: boolean; jobId: string }> {
  const recentDays =
    typeof options.recentDays === "number" && Number.isFinite(options.recentDays)
      ? Math.max(1, Math.floor(options.recentDays))
      : 2;
  const maxMemories =
    typeof options.maxMemories === "number" && Number.isFinite(options.maxMemories)
      ? Math.max(1, Math.floor(options.maxMemories))
      : 500;
  const batchSize =
    typeof options.batchSize === "number" && Number.isFinite(options.batchSize)
      ? Math.max(1, Math.floor(options.batchSize))
      : 100;
  const scheduleExpr =
    typeof options.scheduleExpr === "string" && options.scheduleExpr.trim().length > 0
      ? options.scheduleExpr.trim()
      : "23 2 * * *";
  const agentId =
    typeof options.agentId === "string" && options.agentId.trim().length > 0
      ? options.agentId.trim()
      : "main";

  return ensureCronJob(jobsPath, GOVERNANCE_CRON_ID, () => ({
      id: GOVERNANCE_CRON_ID,
      agentId,
      name: "Remnic Nightly Governance (batched)",
      enabled: true,
      schedule: {
        kind: "cron",
        expr: scheduleExpr,
        tz: options.timezone,
      },
      sessionTarget: "isolated",
      wakeMode: "now",
