import { stat } from "node:fs/promises";
import { StorageManager } from "../storage.js";
import { assertInjectedStorageRooted } from "./projection-support.js";
import { log } from "../logger.js";
import { displayErrorDetail } from "../runtime/better-sqlite.js";
import type { MemoryLifecycleEvent } from "../types.js";
import { toBackupStamp } from "./backup-stamp.js";
import { copyExistingFileToBackup, writeFileAtomically } from "./atomic-file.js";
import {
  buildLifecycleEventsForMemory,
  compareMemoryLifecycleEvents,
  sortMemoryLifecycleEvents,
  isFrontmatterDerivedLifecycleEventType,
  memoryLifecycleEventProjectionIdentity,
  memoryLifecycleLedgerLockPath,
  MEMORY_LIFECYCLE_LEDGER_LOCK_STALE_MS,
} from "../memory-lifecycle-ledger-utils.js";
import { withHeldFileLock, type HeldFileLockOptions, type HeldFileLockController } from "../utils/serialize-mutations.js";
import { probeEncryptedRegularFileHeader } from "../secure-store/secure-fs.js";
import { isErrnoCode } from "../utils/errno.js";


export interface RebuildMemoryLifecycleLedgerOptions {
  memoryDir: string;
  dryRun?: boolean;
  now?: Date;
  /**
   * Active storage context (issue #1910). When provided, memories are read
   * through it (so encrypted-at-rest memories in a secure-store deployment are
   * decrypted with the live key) and the rebuilt ledger is rewritten through
   * its secure writer (so it stays encrypted at rest). Its `dir` MUST equal
   * `memoryDir`. When omitted, a fresh plaintext `StorageManager` is used and
   * the ledger is written as plaintext — the CLI default.
   */
  storage?: StorageManager;
  /**
   * Preserve append-only lifecycle events that have no frontmatter equivalent
   * (issue #1910). `buildLifecycleEventsForMemory` only reconstructs
   * `created`/`updated`/`superseded`/`archived` from frontmatter, so a bare
   * rebuild silently drops history like `explicit_capture_accepted`,
   * `explicit_capture_queued`, `imported`, `promoted`, `merged`, `restored`,
   * and `rejected`. When true, the existing ledger's non-reconstructable rows
   * are read (via the same secure/permissive `readAllMemoryLifecycleEvents`
   * path), merged with the rebuilt rows, deduplicated by `eventId`, and sorted
   * canonically. Background auto-compaction sets this so it never loses events;
   * the manual/CLI repair rebuild leaves it off (reconstruct purely from
   * frontmatter).
   */
  preserveExistingEvents?: boolean;
  /**
   * Override the ledger-lock acquisition timing (issue #2033). Only
   * `maxWaitMs`/`pollMs` are honored; `staleMs` stays fixed at
   * `MEMORY_LIFECYCLE_LEDGER_LOCK_STALE_MS`. Used by tests to force the
   * lock-acquisition-failure branch (`acquired=false`) deterministically
   * without a multi-second wait.
   */
  lockOptions?: Pick<HeldFileLockOptions, "maxWaitMs" | "pollMs">;
  /**
   * Upper bound (bytes) on the rewritten ledger when preserving events (issue
   * #2033). A preserving compaction carries over ALL append-only history, which
   * — if the history alone is large — could leave the rewritten ledger over the
   * whole-file read/decrypt cap (STATE_FILE_MAX_DECRYPT_BYTES), the exact
   * unreadable-ledger failure compaction exists to prevent. When set and the
   * preserved payload would exceed it, the OLDEST rows are dropped from the
   * active ledger until it fits; because the full pre-compaction ledger is
   * copied verbatim to the timestamped backup first, those rows are archived,
   * not lost. Ignored when `preserveExistingEvents` is off (a frontmatter-only
   * rebuild is already bounded by the corpus). `0`/undefined disables bounding.
   */
  maxLedgerBytes?: number;
}

export interface SkippedLifecycleBlankIdMemory {
  path: string;
}

export interface SkippedDuplicateLifecycleEvent {
  eventId: string;
  keptPath: string;
  skippedPath: string;
}

export interface RebuildMemoryLifecycleLedgerResult {
  dryRun: boolean;
  scannedMemories: number;
  rebuiltRows: number;
  outputPath: string;
  backupPath?: string;
  skippedBlankIdMemories: SkippedLifecycleBlankIdMemory[];
  skippedDuplicateEvents: SkippedDuplicateLifecycleEvent[];
  /**
   * Count of existing-ledger rows carried over beyond the frontmatter
   * reconstruction (only set when `preserveExistingEvents` is on; issue #1910):
   * append-only history with no frontmatter equivalent, plus any
   * frontmatter-derived row that raced in after the corpus scan and so was not
   * reproduced by the reconstruction (#2033).
   */
  preservedAppendOnlyRows?: number;
  /**
   * Count of oldest rows dropped from the ACTIVE ledger to keep it under
   * `maxLedgerBytes` (issue #2033). They remain in the verbatim timestamped
   * backup, so this is a bound-and-archive, not a loss. Set only when bounding
   * actually trimmed rows.
   */
  archivedOverflowRows?: number;
  /**
   * Whether the active ledger was actually backed up and rewritten (issue #2033
   * thread PRRT_kwDORJXyws6SExst). A preserving write-mode rebuild that would
   * reproduce the current ledger byte-for-byte (same decrypted content AND same
   * at-rest format) skips the backup+rewrite, so callers can distinguish a real
   * compaction from a no-op and avoid re-archiving an unchanged ledger every
   * interval. `true` for every dry run's non-write preview is never set — only
   * write-mode results carry it; defaults to `false` when no rewrite happened.
   */
  rewritten?: boolean;
}

/** Serialized on-disk size (bytes, incl. trailing newline) of one ledger row. */
function lifecycleRowBytes(event: MemoryLifecycleEvent): number {
  return Buffer.byteLength(`${JSON.stringify(event)}\n`, "utf8");
}

/**
 * Keep the NEWEST canonically-ordered events whose serialized payload fits
 * strictly under `cap` bytes (issue #2033). Recency is by `timestamp` (newest
 * first), tie-broken by the canonical comparator, so a large append-only
 * history is trimmed to its most recent rows rather than to a single memoryId
 * group (the ledger's on-disk order is by memoryId then time).
 *
 * A row too large to fit the remaining budget is SKIPPED, and scanning
 * continues to older rows that still fit — one oversized (or future-dated,
 * hence recency-first) row cannot truncate the entire older history. The kept
 * subset is returned in the input's canonical order; the caller relies on the
 * verbatim backup to retain the dropped rows.
 */
export function boundLifecycleEventsToByteCap(
  events: MemoryLifecycleEvent[],
  cap: number,
): { kept: MemoryLifecycleEvent[]; dropped: number } {
  if (!(cap > 0)) return { kept: events, dropped: 0 };
  const sizes = new Map<MemoryLifecycleEvent, number>();
  let total = 0;
  for (const event of events) {
    const bytes = lifecycleRowBytes(event);
    sizes.set(event, bytes);
    total += bytes;
  }
  if (total <= cap) return { kept: events, dropped: 0 };
  const byRecency = [...events].sort((a, b) => {
    if (a.timestamp !== b.timestamp) return b.timestamp.localeCompare(a.timestamp);
    return -compareMemoryLifecycleEvents(a, b);
  });
  const keep = new Set<MemoryLifecycleEvent>();
  let running = 0;
  for (const event of byRecency) {
    const bytes = sizes.get(event)!;
    if (running + bytes > cap) continue; // skip this row, keep scanning older rows that still fit
    running += bytes;
    keep.add(event);
  }
  const kept = events.filter((event) => keep.has(event));
  return { kept, dropped: events.length - kept.length };
}

export async function backupExistingLedger(
  memoryDir: string,
  outputPath: string,
  now: Date,
): Promise<string | undefined> {
  try {
    await stat(outputPath);
  } catch (err) {
    if (isErrnoCode(err, "ENOENT")) {
      return undefined;
    }
    throw err;
  }

  const backupPath = path.join(
    memoryDir,
    "archive",
    "memory-lifecycle-ledger",
    toBackupStamp(now),
    "state",
    "memory-lifecycle-ledger.jsonl",
  );
  return backupPath;
}

export async function rebuildMemoryLifecycleLedger(
  options: RebuildMemoryLifecycleLedgerOptions,
): Promise<RebuildMemoryLifecycleLedgerResult> {
  const dryRun = options.dryRun !== false;
  const now = options.now ?? new Date();
  const outputPath = path.join(options.memoryDir, "state", "memory-lifecycle-ledger.jsonl");
  const storage = assertInjectedStorageRooted("rebuildMemoryLifecycleLedger", options.memoryDir, options.storage) ?? new StorageManager(options.memoryDir);
  const secureRewrite = options.storage !== undefined;
  const tiers = [
    await storage.readAllMemories(),
    await storage.readAllColdMemories(),
    await storage.readArchivedMemories(),
  ];
  const allMemories = tiers.flat();
  const skippedBlankIdMemories: SkippedLifecycleBlankIdMemory[] = [];
  const eventCandidates: Array<{ event: MemoryLifecycleEvent; path: string }> = [];
  for (const tier of tiers) {
    for (const memory of [...tier].sort((left, right) => left.path.localeCompare(right.path))) {
      if (!memory.frontmatter.id.trim()) {
        skippedBlankIdMemories.push({ path: memory.path });
        log.warn(`lifecycle ledger rebuild skipped blank memory id: path=${memory.path}`);
        continue;
      }
      for (const event of buildLifecycleEventsForMemory(memory)) {
        eventCandidates.push({ event, path: memory.path });
      }
    }
  }

  const orderedEvents = sortMemoryLifecycleEvents(eventCandidates.map((candidate) => candidate.event));
  const candidateByEvent = new Map(
    eventCandidates.map((candidate) => [candidate.event, candidate]),
  );
  const keptByEventId = new Map<string, { event: MemoryLifecycleEvent; path: string }>();
  const events: MemoryLifecycleEvent[] = [];
  const skippedDuplicateEvents: SkippedDuplicateLifecycleEvent[] = [];
  for (const event of orderedEvents) {
    const candidate = candidateByEvent.get(event)!;
    const kept = keptByEventId.get(event.eventId);
    if (kept) {
      skippedDuplicateEvents.push({
        eventId: event.eventId,
        keptPath: kept.path,
        skippedPath: candidate.path,
      });
      log.warn(
        `lifecycle ledger rebuild skipped duplicate event_id=${event.eventId}: `
        + `kept=${kept.path} skipped=${candidate.path}`,
      );
      continue;
    }
    keptByEventId.set(event.eventId, candidate);
    events.push(event);
  }

  let finalEvents = events;
  let preservedAppendOnlyRows: number | undefined;
  let archivedOverflowRows: number | undefined;
  let backupPath: string | undefined;
  let rewritten = false;
  // The preserve-read + whole-file rewrite are serialized against concurrent
  // lifecycle appends ONLY in write mode (issue #1910, codex):
  // appendMemoryLifecycleEvents holds this same cross-process lock, so an event
  // appended after the preserve-read but before the atomic rename waits and
  // lands on the compacted ledger instead of being clobbered by the rename. A
  // DRY RUN takes no lock — it reads the ledger read-only to compute the
  // preserve/merge/byte-cap PREVIEW and never rewrites, so it must not block
  // appends (#2033 Cursor). The corpus scan above stays outside the lock in
  // both modes — frontmatter-derived rows come from the memory files.
  const runLedgerCriticalSection = async (
    acquired: boolean,
    lock: HeldFileLockController | null,
  ): Promise<void> => {
    // A WRITE that read or rewrote the ledger without the lock could race a
    // concurrent append/rewrite and lose data, so REFUSE the unlocked fallback
    // withHeldFileLock takes on acquisition timeout (issue #2033 CodeRabbit
    // Critical / codex). A dry run passes lock=null and acquired=true: it never
    // reaches the rewrite, so the unlocked preview read is safe.
    if (!dryRun && !acquired) {
      throw new Error(
        "lifecycle ledger rebuild aborted: could not acquire the ledger lock within the "
        + "acquisition budget; refusing to read or rewrite unlocked so a concurrent append "
        + "or compaction cannot be clobbered (issue #1910).",
      );
    }
    if (options.preserveExistingEvents) {
      // Merge the frontmatter reconstruction (`events`) with the CURRENT ledger
      // so compaction never deletes a lifecycle row that raced the scan (issue
      // #1910, #2033). Read the existing ledger through the uncapped BUFFER
      // path — it decrypts with the live key when `storage` carries the secure
      // context and bypasses the whole-file string decrypt cap, so an oversize
      // encrypted ledger (the exact file compaction must shrink) is still
      // readable here rather than aborting (#2033 Cursor High).
      // preserveExistingEvents means "never lose history": if the current
      // ledger genuinely cannot be read (corruption, or a locked required
      // store), ABORT rather than rewrite from frontmatter only and silently
      // drop that history. An absent ledger reads as [] (ENOENT swallowed
      // downstream), so a throw here is always a real read failure.
      let existing: MemoryLifecycleEvent[];
      try {
        existing = await storage.readAllMemoryLifecycleEventsForCompaction();
      } catch (err) {
        throw new Error(
          `lifecycle ledger rebuild aborted: cannot read existing events to preserve `
          + `(${displayErrorDetail(err) || "unknown error"})`,
        );
      }
      // The corpus scan (`events`) runs OUTSIDE the lock and is therefore a
      // stale snapshot; `existing` is read here under the lock and is
      // authoritative for what the ledger holds at rewrite time. A
      // frontmatter-derived row (created/updated/superseded/archived) is safe to
      // collapse into the reconstruction ONLY when the scan actually reproduced
      // the same logical event — same (memoryId, eventType, timestamp), which is
      // exactly what the live append stamps (fm.created/updated/...) and what
      // makeRebuiltMemoryLifecycleEvent emits. A frontmatter-derived row whose
      // content key the reconstruction did NOT produce raced in after the scan
      // (a memory created/updated between the scan and this locked read); the
      // reconstruction has no equivalent, so dropping it by eventType alone
      // would delete it. Preserve it instead, deduped by content key so a
      // retried append of the same logical event still collapses to one. Rows
      // that are not frontmatter-derived are append-only history with no
      // reconstruction — always carried over, deduped by eventId in the merge.
      const reconstructedKeys = new Set(events.map(memoryLifecycleEventProjectionIdentity));
      const racedFrontmatterByKey = new Map<string, MemoryLifecycleEvent>();
      const appendOnly: MemoryLifecycleEvent[] = [];
      for (const event of existing) {
        if (!isFrontmatterDerivedLifecycleEventType(event.eventType)) {
          appendOnly.push(event);
          continue;
        }
        const key = memoryLifecycleEventProjectionIdentity(event);
        if (reconstructedKeys.has(key)) continue; // collapsed into reconstruction
        if (!racedFrontmatterByKey.has(key)) racedFrontmatterByKey.set(key, event);
      }
      const mergedById = new Map<string, MemoryLifecycleEvent>();
      for (const event of sortMemoryLifecycleEvents([
        ...events,
        ...racedFrontmatterByKey.values(),
        ...appendOnly,
      ])) {
        if (!mergedById.has(event.eventId)) mergedById.set(event.eventId, event);
      }
      finalEvents = [...mergedById.values()];
      preservedAppendOnlyRows = finalEvents.length - events.length;
      // Bound the rewritten ledger so a preserving compaction can never leave it
      // over the whole-file read/decrypt cap (#2033). This must run whenever a
      // cap is set — NOT only when `existing.length > 0`: an oversized on-disk
      // ledger whose every row fails validation reads as `existing === []`, yet
      // `finalEvents` (the frontmatter reconstruction) can itself exceed the cap.
      // Overflow (oldest) rows are dropped from the active ledger but survive
      // both in the timestamped backup (a verbatim copy when the ledger is
      // plaintext, re-encrypted under the backup path's own AAD when it is
      // encrypted so it still decrypts there, #2033) and, for frontmatter-derived
      // rows, in the memory files they were reconstructed from — so a later full
      // rebuild regenerates them.
      if (options.maxLedgerBytes && options.maxLedgerBytes > 0) {
        const bounded = boundLifecycleEventsToByteCap(finalEvents, options.maxLedgerBytes);
        if (bounded.dropped > 0) {
          finalEvents = bounded.kept;
          archivedOverflowRows = bounded.dropped;
          log.warn(
            `lifecycle ledger rebuild bounded to ${options.maxLedgerBytes} bytes: `
            + `dropped ${bounded.dropped} oldest row(s) from the active ledger `
            + `(preserved in the backup) to stay under the read/decrypt cap.`,
          );
        }
      }
    }

    // Re-assert the lock immediately before the destructive active-ledger
    // rewrite. Everything above (the preserve read, merge, sort, byte-cap
    // bound, and JSON serialize) is CPU-bound and blocks the event loop, so the
    // timer heartbeat inside withHeldFileLock cannot refresh the lock's mtime;
    // a peer that judged the lock stale within the 30s window could have broken
    // it and appended to the current ledger. `lock.refresh()` (a) reports the
    // lock LOST so we ABORT rather than rename our compacted file over that
    // peer's append, and (b) when still held, re-stamps the mtime so the bounded
    // write below cannot itself be judged stale mid-rename (issue #1910/#2033).
    const abortIfLockLost = async (): Promise<void> => {
      if (lock && await lock.refresh()) return;
      throw new Error(
        "lifecycle ledger rebuild aborted: lost the ledger lock during the compaction "
        + "rewrite (a peer stale-broke it while the event loop was blocked by CPU-bound "
        + "merge/serialize); refusing to clobber a concurrent append (issue #1910/#2033).",
      );
    };
    if (!dryRun) {
      const payload = finalEvents.map((event) => JSON.stringify(event)).join("\n");
      const content = payload.length > 0 ? `${payload}\n` : "";
      // No-op skip (#2033 thread PRRT_kwDORJXyws6SExst): a preserving rebuild
      // bounds the ACTIVE ledger to the read/decrypt cap, so a VALID ledger that
      // sits above the configured compaction trigger but below the cap would
      // otherwise be rewritten to identical content and re-archived on every
      // maintenance interval — unbounded growth of archive/memory-lifecycle-ledger
      // plus pointless disk/CPU churn. Skip the backup+rewrite when it would
      // change neither the logical (decrypted) content NOR the at-rest format.
      // The raw read here doubles as the source for the encrypted verbatim backup
      // below, so the current ledger is read at most once. An absent ledger reads
      // as ENOENT (a create is always a real change) and any other read/probe
      // error propagates rather than masking a needed rewrite.
      let currentEncrypted = false;
      let priorRawBuffer: Buffer | null = null;
      try {
        currentEncrypted = await probeEncryptedRegularFileHeader(outputPath);
        priorRawBuffer = await storage.readMemoryLifecycleLedgerRawBufferForCompaction();
      } catch (err) {
        if (!isErrnoCode(err, "ENOENT")) throw err;
      }
      // Preserve encryption at rest (#2033). An already-encrypted ledger (or its
      // encrypted backup) MUST be rewritten encrypted even when the
      // `secureStoreEncryptOnWrite` policy is paused — otherwise the compaction
      // silently DOWNGRADES encrypted state to plaintext. Force encryption
      // whenever the current ledger is encrypted and the store is unlocked (a
      // key is available); reaching this point with an encrypted ledger already
      // implies an unlocked store, since the raw read above decrypts and would
      // have thrown under a locked key. A plaintext ledger keeps the ordinary
      // policy (`willEncryptStateWrites`), so existing plaintext behavior holds.
      const forceEncrypt =
        secureRewrite && currentEncrypted && storage.isSecureStoreUnlocked();
      const replacementEncrypted =
        secureRewrite && (storage.willEncryptStateWrites() || forceEncrypt);
      // Compare as buffers, never decoding the raw ledger to one giant string:
      // a multi-hundred-MB decrypted ledger can exceed V8's max string length,
      // so `priorRawBuffer.equals(...)` (byte compare) must be used, NOT
      // `.toString()` (#2033 giant-string invariant). `content` is the freshly
      // serialized replacement, already a string; Buffer.from() reuses it.
      if (
        priorRawBuffer !== null &&
        currentEncrypted === replacementEncrypted &&
        priorRawBuffer.equals(Buffer.from(content, "utf8"))
      ) {
        // Nothing to change: leave the active ledger and archive untouched.
        rewritten = false;
      } else {
        const desiredBackup = await backupExistingLedger(options.memoryDir, outputPath, now);
        if (secureRewrite) {
          // Preserve encrypted-at-rest (issue #1910). The BACKUP needs care under
          // secure-store (#2033): when the existing ledger is encrypted, its bytes
          // are path-bound via AAD, so a byte-for-byte copy to the archive path
          // cannot be decrypted there — it would silently orphan the overflow rows
          // a bounded rewrite claims to preserve. Reuse the RAW decrypted ledger
          // content read above (no event parsing, so malformed/truncated/future
          // rows survive exactly as the plaintext verbatim copy keeps them) and
          // re-encrypt it under the backup path's own AAD, yielding a directly
          // decryptable backup that retains every original byte. A PLAINTEXT
          // existing ledger is already readable, so a verbatim copy is correct.
          // Then rewrite the active ledger through the secure writer.
          if (desiredBackup && currentEncrypted) {
            const rawForBackup =
              priorRawBuffer ?? (await storage.readMemoryLifecycleLedgerRawBufferForCompaction());
            await storage.writeMemoryLifecycleLedgerContent(rawForBackup, desiredBackup, forceEncrypt);
            backupPath = desiredBackup;
          } else {
            backupPath = desiredBackup
              ? await copyExistingFileToBackup(outputPath, desiredBackup)
              : undefined;
          }
          await abortIfLockLost();
          await storage.writeMemoryLifecycleLedgerContent(content, undefined, forceEncrypt);
        } else {
          await abortIfLockLost();
          backupPath = await writeFileAtomically(outputPath, content, desiredBackup);
        }
        rewritten = true;
      }
    }
  };
  // Write mode holds the ledger lock across the preserve-read and atomic
  // rewrite so a concurrent append lands on the compacted ledger instead of
  // being clobbered. A dry run computes the SAME preserve/merge/byte-cap
  // preview but WITHOUT the lock (read-only, no rewrite), so `rebuiltRows`,
  // `preservedAppendOnlyRows`, and `archivedOverflowRows` report what a --write
  // would apply while never blocking concurrent appends (#2033 Cursor). A dry
  // run with nothing to preserve touches nothing at all.
  if (!dryRun) {
    await withHeldFileLock(
      memoryLifecycleLedgerLockPath(outputPath),
      { staleMs: MEMORY_LIFECYCLE_LEDGER_LOCK_STALE_MS, ...options.lockOptions },
      runLedgerCriticalSection,
    );
  } else if (options.preserveExistingEvents) {
    await runLedgerCriticalSection(true, null);
  }

  return {
    dryRun,
    scannedMemories: allMemories.length,
    rebuiltRows: finalEvents.length,
    outputPath,
    backupPath,
    skippedBlankIdMemories,
    skippedDuplicateEvents,
    preservedAppendOnlyRows,
    archivedOverflowRows,
    rewritten,
  };
}

/**
 * Day-summary cron model resolution (extracted from
 * orchestration/maintenance.ts in #2047 so that capped file keeps only
 * scheduling wiring). Pure function of config — no I/O.
 */

import type { PluginConfig } from "../types.js";

/**
 * Resolve the cron-routing model + fallback chain. Only in gateway mode is
 * summaryModel routable as an OpenClaw agentTurn model; in plugin mode it is
 * a direct-client model id for Remnic's own LLM calls. Task-chain fallbacks
 * attach only when the model matches the task-chain primary (a distinct
 * override's fallbacks would be unrelated); gateway default models are
 * appended as tail fallbacks (de-duped) so a task-chain outage doesn't stop
 * the cron before reaching the gateway default chain.
 */
export function resolveDaySummaryCronModel(config: PluginConfig): {
  model?: string;
  fallbacks: string[];
} {
  const rawSummaryModel = config.summaryModel;
  const taskPrimary = config.taskModelChain?.primary;
  const isGateway = config.modelSource === "gateway";
  const model = isGateway ? rawSummaryModel || taskPrimary || undefined : undefined;
  const fallbacks: string[] = [];
  if (model && taskPrimary && model === taskPrimary) {
    const seen = new Set<string>(model ? [model] : []);
    const addUnique = (value: string | undefined) => {
      if (typeof value !== "string") return;
      const trimmed = value.trim();
      if (trimmed.length > 0 && !seen.has(trimmed)) {
        seen.add(trimmed);
        fallbacks.push(trimmed);
      }
    };
    for (const fb of config.taskModelChain?.fallbacks ?? []) addUnique(fb);
    const gwDefaults = config.gatewayConfig?.agents?.defaults?.model;
    addUnique(gwDefaults?.primary);
    if (Array.isArray(gwDefaults?.fallbacks)) {
      for (const fb of gwDefaults.fallbacks) addUnique(fb);
    }
  }
  return { ...(model ? { model } : {}), fallbacks };
}

/**
 * Scheduled rebuild of the root memory projection (issue #2119).
 *
 * The projection (`state/memory-projection.sqlite`) is otherwise rebuild-only
 * (manual CLI / tests), so it goes stale as the lifecycle ledger grows and
 * timeline/browse consumers silently fall back to full-corpus scans. The
 * MaintenanceScheduler fires this alongside ledger compaction on every
 * maintenance request — interval-throttled, single-flighted, never awaited,
 * never throws.
 *
 * The rebuild runs in a forked child so the corpus and lifecycle ledger are
 * not allocated in the daemon heap. An unlocked secure store stays in-process:
 * the key is process-local and is never placed on the child's argv or env.
 * The child is killed on scheduler dispose and on parent exit. If the parent
 * dies without running those hooks, the child sees the IPC channel close and
 * stops before it publishes the projection.
 * When the daemon heap is already above `projectionRebuildHeapUsageLimit`,
 * the job is postponed with the failure backoff instead of starting.
 *
 * `projectionRebuildEnabled` gates it (via the lifecycle capabilities
 * resolver, default true); `projectionRebuildIntervalMs` is the cadence.
 *
 * Skipped when the projection was rebuilt within the interval. The freshness
 * check reads the on-disk `rebuiltAt` meta (not just an in-process timestamp)
 * so a daemon restart or an operator's cron `remnic rebuild-memory-projection`
 * both suppress a redundant rebuild. On a real rebuild it logs the lag it just
 * cured (age of the projection before the rebuild) plus the fresh row counts,
 * so operators can see the projection was drifting. Failures are non-fatal
 * and leave the throttle un-advanced to retry.
 *
 * Scope: the root memoryDir projection — the one `getMemoryTimeline` /
 * browse / current-state serve from `baseDir`. Per-namespace projections are
 * not yet scheduled here (they are still served by their own rebuild paths);
 * the fallback WARN surfaces staleness for any namespace that lags.
 */
import { existsSync } from "node:fs";
import { fork, type ChildProcess } from "node:child_process";
import path from "node:path";
import v8 from "node:v8";
import { fileURLToPath } from "node:url";
import { log } from "../logger.js";
import type { PluginConfig } from "../types.js";
import { resolveMemoryLifecycleCapabilities } from "../capabilities.js";
import {
  rebuildMemoryProjection,
  type RebuildMemoryProjectionOptions,
} from "../maintenance/rebuild-memory-projection.js";
import { PROJECTION_REBUILD_RUNNER_FLAG } from "../maintenance/rebuild-memory-projection-runner.js";
import { readProjectionRebuiltAt } from "../maintenance/projection-support.js";
import { DEFAULT_PROJECTION_REBUILD_HEAP_USAGE_LIMIT } from "../projection-rebuild-config.js";
import { fullCorpusHeapPressure, type HeapLimitStatistics } from "./full-corpus-heap-guard.js";

type InjectedStorage = NonNullable<RebuildMemoryProjectionOptions["storage"]>;

export interface ProjectionRebuildScheduleState {
  inFlight: boolean;
  lastRebuildAtMs: number;
  /** Timestamp of the most recent FAILURE; gates a short retry backoff that is
   * separate from the success interval so a transient cause (e.g. a locked
   * secure store) retries promptly once cleared instead of waiting a full
   * interval. */
  lastFailureAtMs: number;
}

export interface ProjectionRebuildForkRequest {
  memoryDir: string;
  defaultNamespace: string;
  now: Date;
}

export interface ProjectionRebuildForkResult {
  currentRows: number;
  timelineRows: number;
  entityMentionRows: number;
}

/** Bounded retry cadence after a failure — short enough to self-heal promptly
 * once a transient cause clears, long enough to keep a persistently-failing
 * rebuild off every maintenance tick. */
const FAILURE_RETRY_BACKOFF_MS = 5 * 60 * 1000;

/** Floor for a hung child. A short interval must not make this tighter:
 * a large corpus can legitimately run longer than 30 minutes. When the
 * configured interval is longer, the child may use that whole interval. */
const FORK_TIMEOUT_MS = 30 * 60 * 1000;

/** Hang cap for one scheduled fork. At least 30 minutes, otherwise the interval,
 * and never above Node's 32-bit setTimeout limit. A larger delay overflows
 * and fires in 1ms, which would kill every rebuild. */
const MAX_SETTIMEOUT_MS = 2_147_483_647;

export function projectionRebuildForkTimeoutMs(intervalMs: number): number {
  const timeout = !Number.isFinite(intervalMs) || intervalMs < FORK_TIMEOUT_MS
    ? FORK_TIMEOUT_MS
    : intervalMs;
  return Math.min(timeout, MAX_SETTIMEOUT_MS);
}

const projectionRebuildChildren = new Map<ProjectionRebuildScheduleState | undefined, Set<ChildProcess>>();
let parentExitHookInstalled = false;

function rememberProjectionRebuildChild(
  child: ChildProcess,
  owner: ProjectionRebuildScheduleState | undefined,
): void {
  let children = projectionRebuildChildren.get(owner);
  if (!children) {
    children = new Set();
    projectionRebuildChildren.set(owner, children);
  }
  children.add(child);
  const forget = () => {
    children.delete(child);
    if (children.size === 0) projectionRebuildChildren.delete(owner);
  };
  child.once("exit", forget);
  child.once("error", forget);
  if (!parentExitHookInstalled) {
    parentExitHookInstalled = true;
    // The exit listener is invoked with the exit code. Ignore that argument
    // so a non-zero code is not treated as a scheduler owner.
    process.on("exit", () => {
      terminateScheduledProjectionRebuilds();
    });
  }
}

/**
 * SIGKILL scheduled rebuild children. A scheduler dispose passes its own
 * state so another instance's child keeps running. Process exit passes no
 * owner and kills every child.
 */
export function terminateScheduledProjectionRebuilds(
  owner?: ProjectionRebuildScheduleState,
): void {
  const groups = owner
    ? [projectionRebuildChildren.get(owner)]
    : [...projectionRebuildChildren.values()];
  for (const children of groups) {
    if (!children) continue;
    for (const child of children) child.kill("SIGKILL");
  }
}

const CHILD_ENV_ALLOWLIST = [
  "PATH",
  "NODE_OPTIONS",
  "HOME",
  "USERPROFILE",
  "TMPDIR",
  "TMP",
  "TEMP",
  "LANG",
  "LC_ALL",
  "LC_CTYPE",
  "TZ",
  "SystemRoot",
  "windir",
  "PATHEXT",
  "COMSPEC",
  "NODE_PATH",
] as const;

export function createProjectionRebuildScheduleState(): ProjectionRebuildScheduleState {
  return { inFlight: false, lastRebuildAtMs: 0, lastFailureAtMs: 0 };
}

/**
 * Environment for the rebuild child. Only runtime locators are copied.
 * API keys, tokens, and secure-store unlock material are not passed.
 */
export function projectionRebuildChildEnv(parent: NodeJS.ProcessEnv): NodeJS.ProcessEnv {
  const env: NodeJS.ProcessEnv = {};
  for (const key of CHILD_ENV_ALLOWLIST) {
    const value = parent[key];
    if (value !== undefined) env[key] = value;
  }
  return env;
}

function projectionRebuildRunnerPath(): string {
  const here = fileURLToPath(import.meta.url);
  const dir = path.dirname(here);
  const candidates = [
    path.join(dir, "..", "maintenance", "rebuild-memory-projection-runner.ts"),
    path.join(dir, "..", "maintenance", "rebuild-memory-projection-runner.js"),
    path.join(dir, "maintenance", "rebuild-memory-projection-runner.js"),
    path.join(dir, "rebuild-memory-projection-runner.js"),
  ];
  for (const candidate of candidates) {
    if (existsSync(candidate)) return candidate;
  }
  throw new Error("projection rebuild runner was not found next to the maintenance bundle");
}

function runnerExecArgv(runnerPath: string): string[] {
  const argv: string[] = [];
  const source = process.execArgv;
  for (let index = 0; index < source.length; index += 1) {
    const arg = source[index] ?? "";
    if (arg === "--inspect" || arg === "--inspect-brk" || arg === "--inspect-port") {
      if (arg === "--inspect-port") index += 1;
      continue;
    }
    if (arg.startsWith("--inspect=") || arg.startsWith("--inspect-brk=") || arg.startsWith("--inspect-port=")) {
      continue;
    }
    argv.push(arg);
  }
  if (runnerPath.endsWith(".ts") && !argv.some((arg) => arg === "tsx" || arg.includes(`${path.sep}tsx`))) {
    argv.unshift("--import", "tsx");
  }
  return argv;
}

function isRunnerSuccess(message: unknown): message is ProjectionRebuildForkResult & { ok: true } {
  if (!message || typeof message !== "object") return false;
  const row = message as Record<string, unknown>;
  return row.ok === true
    && typeof row.currentRows === "number"
    && typeof row.timelineRows === "number"
    && typeof row.entityMentionRows === "number";
}

/** Fork the projection rebuild. Arguments are path, namespace, and timestamp only. */
export async function forkProjectionRebuild(
  request: ProjectionRebuildForkRequest,
  options?: {
    timeoutMs?: number;
    spawnChild?: () => ChildProcess;
    /** Scheduler that owns this child. Dispose kills only that owner's child. */
    owner?: ProjectionRebuildScheduleState;
    /** Invoked after exit listeners are attached. Tests use this to disconnect. */
    onChild?: (child: ChildProcess) => void;
  },
): Promise<ProjectionRebuildForkResult> {
  const timeoutMs = Math.min(options?.timeoutMs ?? FORK_TIMEOUT_MS, MAX_SETTIMEOUT_MS);
  const child = options?.spawnChild
    ? options.spawnChild()
    : spawnProjectionRebuildChild(request);
  rememberProjectionRebuildChild(child, options?.owner);
  return await new Promise((resolve, reject) => {
    let settled = false;
    let timer: ReturnType<typeof setTimeout> | undefined;
    const finish = (err?: Error, result?: ProjectionRebuildForkResult) => {
      if (settled) return;
      settled = true;
      if (timer) clearTimeout(timer);
      if (err) reject(err);
      else if (result) resolve(result);
      else reject(new Error("projection rebuild runner returned no result"));
    };
    timer = setTimeout(() => {
      child.kill("SIGKILL");
      finish(new Error(`projection rebuild runner timed out after ${timeoutMs}ms`));
    }, timeoutMs);
    timer.unref?.();
    child.on("message", (message: unknown) => {
      if (isRunnerSuccess(message)) {
        finish(undefined, message);
        return;
      }
      const error = message && typeof message === "object" && "error" in message
        ? String((message as { error?: unknown }).error ?? "projection rebuild runner failed")
        : "projection rebuild runner failed";
      finish(new Error(error));
    });
    child.on("error", (err) => finish(err));
    child.on("exit", (code) => {
      if (!settled) {
        finish(new Error(`projection rebuild runner exited ${code ?? "null"}`));
      }
    });
    options?.onChild?.(child);
  });
}

function spawnProjectionRebuildChild(request: ProjectionRebuildForkRequest): ChildProcess {
  const runnerPath = projectionRebuildRunnerPath();
  const nowIso = request.now.toISOString();
  return fork(
    runnerPath,
    [PROJECTION_REBUILD_RUNNER_FLAG, request.memoryDir, request.defaultNamespace, nowIso],
    {
      execArgv: runnerExecArgv(runnerPath),
      env: projectionRebuildChildEnv(process.env),
      stdio: ["ignore", "inherit", "inherit", "ipc"],
    },
  );
}

function storageIsUnlocked(storage: InjectedStorage | undefined): boolean {
  if (!storage || typeof storage.isSecureStoreUnlocked !== "function") return false;
  return storage.isSecureStoreUnlocked();
}

export async function maybeRebuildMemoryProjectionScheduled(opts: {
  config: PluginConfig;
  /** The daemon's live root storage, when available (secure-store unlock). */
  getStorage?: () => InjectedStorage | undefined;
  state: ProjectionRebuildScheduleState;
  /** Test seam. Production forks {@link forkProjectionRebuild}. */
  forkRebuild?: (
    request: ProjectionRebuildForkRequest,
    options?: { timeoutMs?: number; owner?: ProjectionRebuildScheduleState },
  ) => Promise<ProjectionRebuildForkResult>;
  /** Test seam. Production reads `v8.getHeapStatistics()`. */
  heapStatistics?: () => HeapLimitStatistics;
}): Promise<void> {
  const { config, state } = opts;
  if (!resolveMemoryLifecycleCapabilities(config).projectionRebuild) return;
  if (state.inFlight) return;
  const intervalMs = config.projectionRebuildIntervalMs;
  const now = Date.now();
  if (now - state.lastRebuildAtMs < intervalMs) return;
  if (now - state.lastFailureAtMs < FAILURE_RETRY_BACKOFF_MS) return;

  const rootStorage = opts.getStorage?.();
  const memoryDir = rootStorage ? rootStorage.dir : config.memoryDir;

  // On-disk freshness check: survives restarts and cross-process CLI rebuilds.
  const rebuiltAt = readProjectionRebuiltAt(memoryDir);
  const rebuiltAtMs = rebuiltAt ? Date.parse(rebuiltAt) : Number.NaN;
  if (Number.isFinite(rebuiltAtMs) && now - rebuiltAtMs < intervalMs) {
    // Fresh already — adopt its timestamp so the next pass short-circuits on
    // the cheap in-process guard without re-opening the projection each time.
    state.lastRebuildAtMs = rebuiltAtMs;
    return;
  }

  const heapLimit = config.projectionRebuildHeapUsageLimit ?? DEFAULT_PROJECTION_REBUILD_HEAP_USAGE_LIMIT;
  const heapStats = (opts.heapStatistics ?? (() => v8.getHeapStatistics()))();
  const pressure = fullCorpusHeapPressure(heapStats, heapLimit);
  if (pressure.postpone) {
    state.lastFailureAtMs = Date.now();
    log.warn(
      `memory projection scheduled rebuild postponed for ${memoryDir}: `
      + `heap used ${heapStats.used_heap_size} of limit ${heapStats.heap_size_limit} `
      + `(ratio ${pressure.ratio.toFixed(3)}) exceeds projectionRebuildHeapUsageLimit ${heapLimit}`,
    );
    return;
  }

  const forkRebuild = opts.forkRebuild ?? forkProjectionRebuild;
  const unlocked = storageIsUnlocked(rootStorage);
  state.inFlight = true;
  try {
    const result = unlocked
      ? await rebuildMemoryProjection({
        memoryDir,
        // Reuse the daemon's live storage so secure-store deployments rebuild
        // through the unlocked instance instead of a fresh locked one.
        ...(rootStorage ? { storage: rootStorage } : {}),
        defaultNamespace: config.defaultNamespace,
        dryRun: false,
        now: new Date(now),
      })
      : await forkRebuild({
        memoryDir,
        defaultNamespace: config.defaultNamespace || "default",
        now: new Date(now),
      }, {
        timeoutMs: projectionRebuildForkTimeoutMs(intervalMs),
        owner: state,
      });
    state.lastRebuildAtMs = Date.now();
    const lag = Number.isFinite(rebuiltAtMs)
      ? `${Math.max(0, Math.round((now - rebuiltAtMs) / 60_000))}m stale`
      : "never previously built";
    log.info(
      `memory projection rebuilt (scheduled) for ${memoryDir}: was ${lag}; `
      + `${result.currentRows} current, ${result.timelineRows} timeline, `
      + `${result.entityMentionRows} entity-mention rows`,
    );
  } catch (err) {
    // Non-fatal. Arm a SHORT backoff (not the full success interval) so a
    // transient cause (locked secure store, momentarily-unavailable storage)
    // retries promptly once it clears, while a persistently-failing rebuild
    // still stays off every maintenance tick. lastRebuildAtMs is left as-is so
    // the success interval is not falsely advanced.
    state.lastFailureAtMs = Date.now();
    log.warn(`memory projection scheduled rebuild failed (non-fatal) for ${memoryDir}: ${err}`);
  } finally {
    state.inFlight = false;
  }
}

/**
 * Fallback lifecycle pending-append drain for targets with no secure
 * StorageManager. Moved verbatim out of maintenance.ts (issue #2033) so that
 * file stays under the structural size ceiling; behavior is unchanged.
 */

import { appendFile, mkdir, readFile, writeFile } from "node:fs/promises";
import path from "node:path";

import { log } from "../logger.js";
import {
  drainPendingLifecycleLedgerIfAny,
  pendingLifecycleLedgerDir,
  type LifecyclePendingIo,
} from "../storage/memory-lifecycle-ledger-access.js";
import { probeEncryptedRegularFileHeader } from "../secure-store/secure-fs.js";
import { listContainedSpillFiles } from "../utils/path-containment.js";

/**
 * Drain a filesystem-fallback target's pending lifecycle-append spill when no
 * secure StorageManager is available (catalog-disabled namespace; issue
 * #2033). Uses the safe path-scoped PLAINTEXT context this fallback already
 * operates in: a keyless drain can only fold plaintext spills into a plaintext
 * ledger, so it refuses when the ledger or ANY spill is encrypted at rest,
 * leaving those pending for a keyed (catalog-path) drain — exactly mirroring
 * the fallback compaction's encrypted-ledger deferral. Non-fatal; a fast
 * no-op when nothing is pending. The shared spill lister enforces the symlink/
 * containment guard on every spill file it reads or deletes.
 */
export async function drainPendingLifecycleAppendsForPath(memoryDir: string): Promise<void> {
  const ledgerPath = path.join(memoryDir, "state", "memory-lifecycle-ledger.jsonl");
  const spillDir = pendingLifecycleLedgerDir(ledgerPath);
  // Enumerate spills through the SAME guarded lister the actual drain uses
  // (listContainedSpillFiles): it rejects a symlinked/non-directory spill dir
  // and skips any symlink/FIFO/device/escaping entry, returning only regular
  // files contained in the dir. Never raw-readdir + open() an untrusted name:
  // opening a FIFO would block until a writer appears and a symlink would
  // redirect the probe outside the dir (#2033). Enumerate BOTH live `*.jsonl`
  // spills and crash-orphaned `*.jsonl.claimed` files: a drain that died
  // between claiming a spill (rename to `.claimed`) and committing it leaves
  // the ONLY copy of those rows as a claimed orphan. Gating solely on live
  // spills would early-return here whenever the pending dir holds nothing but
  // orphans, stranding those rows forever; proceeding lets
  // drainPendingLifecycleLedgerIfAny -> recoverOrphanedClaims restore and
  // re-commit them under the ledger lock (#2033).
  let spillFiles: string[];
  let claimedOrphans: string[];
  try {
    spillFiles = await listContainedSpillFiles(spillDir);
    claimedOrphans = await listContainedSpillFiles(spillDir, ".jsonl.claimed");
  } catch (err) {
    log.debug(`fallback lifecycle pending scan failed (non-fatal) for ${memoryDir}: ${err}`);
    return;
  }
  if (spillFiles.length === 0 && claimedOrphans.length === 0) return;
  // The pending encryption state is authoritative only UNDER the ledger lock:
  // drainPendingLifecycleLedgerIfAny waits for the lock and re-enumerates the
  // pending dir, so a secure-store writer that spills an encrypted file — or a
  // keyed compaction that rewrites the ledger encrypted — while this fallback
  // waits would defeat any pre-lock probe (#2033). Probe each file at the
  // moment of use inside the held lock instead: readSecure refuses an
  // encrypted spill (the fold reads each spill lazily and propagates the throw
  // BEFORE claiming that spill, leaving it intact) and the append refuses a
  // ledger that became encrypted (the fold rolls the claims back). Either way
  // the plaintext IO
  // never reads or writes ciphertext; the keyed catalog-path drain handles the
  // deferred rows.
  const io: LifecyclePendingIo = {
    writeSecure: async (filePath, payload) => {
      await mkdir(path.dirname(filePath), { recursive: true });
      await writeFile(filePath, payload, "utf-8");
    },
    readSecure: async (filePath) => {
      if (await probeEncryptedRegularFileHeader(filePath)) {
        throw new Error(`fallback lifecycle drain deferred: encrypted spill at ${filePath}`);
      }
      return readFile(filePath, "utf-8");
    },
  };
  try {
    await drainPendingLifecycleLedgerIfAny(
      ledgerPath,
      io,
      async (payload) => {
        if (await probeEncryptedRegularFileHeader(ledgerPath)) {
          throw new Error(`fallback lifecycle drain deferred: ledger became encrypted at ${ledgerPath}`);
        }
        await appendFile(ledgerPath, payload, "utf-8");
      },
      async () => {
        await mkdir(path.dirname(ledgerPath), { recursive: true });
      },
    );
  } catch (err) {
    log.debug(`fallback lifecycle pending drain failed (non-fatal) for ${memoryDir}: ${err}`);
  }
}

/**
 * Callers that must know the re-index actually ran (the entity-migration
 * pending marker, issue #3286) cannot rely on arming the debounced timer: a
 * crash or dispose() inside the debounce window would lose the request. They
 * wait here instead; the scheduler claims the waiters when a pass starts and
 * settles them with the pass outcome, and abandons them on dispose().
 */
export class QmdMaintenanceCompletion {
  private waiters: Array<{ resolve: (served: boolean) => void; namespace?: string }> = [];

  /**
   * Resolves true when a pass that started after this call completed successfully. With a
   * `namespace` the request is served as soon as a pass ran that namespace, whatever else it skipped.
   */
  wait(namespace?: string): Promise<boolean> {
    return new Promise((resolve) => this.waiters.push({ resolve, namespace }));
  }

  /**
   * A pass is starting: take every waiter it will serve and return their settle function.
   * `ran` lists the namespaces a namespace-aware pass ran (absent when namespaces are disabled:
   * one corpus is maintained and the pass outcome applies to every waiter); `defer` keeps the
   * waiters it did not serve waiting for a later pass (a pass that covered only part of the selection).
   */
  claim(): (served: boolean, defer?: boolean, ran?: ReadonlySet<string>) => void {
    const claimed = this.waiters.splice(0);
    return (served, defer = false, ran) => {
      const requeue: typeof claimed = [];
      for (const waiter of claimed) {
        // A scoped waiter needs its own namespace to have run; the pass outcome alone is not enough.
        const own = waiter.namespace !== undefined && ran !== undefined ? ran.has(waiter.namespace) : served;
        if (own) waiter.resolve(true);
        else if (defer) requeue.push(waiter);
        else waiter.resolve(false);
      }
      this.waiters.unshift(...requeue);
    };
  }

  /** The scheduler stopped: nothing will serve the waiters. */
  abandon(): void {
    this.claim()(false);
  }
}

/**
 * In-process weekly compounding run for the standalone daemon.
 *
 * OpenClaw delegate mode registers only memory_search and memory_get, so a
 * gateway cron can no longer call `compounding_weekly_synthesize`. When both
 * compounding flags are on, the standalone daemon arms this runner after
 * its HTTP listener is up. Embedded OpenClaw init does not.
 *
 * Each tick synthesizes the ISO week that most recently ended (previous week,
 * not the in-progress one) by calling `synthesizeWeekly`, which includes
 * calibration when that gate is on. A scheduler-owned completion marker is
 * the durable skip signal: only a scheduled run writes it, so a manual
 * access-surface synthesis of the in-progress week cannot suppress the week's
 * scheduled run, and a restart does not write a completed week twice. A
 * daemon that was down at the Monday boundary still writes that missed week
 * on the next start. Older gaps are left alone — one missed week, not a
 * history backfill.
 *
 * The timer is unref'd. Startup fires one tick immediately; later ticks land
 * on the next Monday 00:00 UTC. A failed tick remembers that week and retries
 * it before the newly due week, including after the boundary. That memory is
 * process-local: a restart still keys off the completion marker.
 */

import { lstat } from "node:fs/promises";
import path from "node:path";

import { resolveConsolidationCapabilities } from "../capabilities.js";
import { writeFileAtomically } from "../maintenance/atomic-file.js";
import { log as defaultLog } from "../logger.js";
import type { StorageManager } from "../storage.js";
import type { PluginConfig } from "../types.js";
import { CompoundingEngine } from "./engine.js";
import { isIsoWeekId, msUntilNextIsoWeek, previousIsoWeekId } from "./iso-week.js";

export interface CompoundingWeeklyLog {
  info(message: string): void;
  warn(message: string): void;
  debug(message: string): void;
}

type TimerHandle = { unref?: () => void };

export interface CompoundingWeeklySchedulerOptions {
  memoryDir: string;
  /** Full `synthesizeWeekly` path, including its calibration pass. */
  synthesizeWeekly: (weekId: string) => Promise<unknown>;
  now?: () => Date;
  /** Scheduler-owned completion check: has a scheduled run finished this week? */
  weekDone?: (weekId: string) => Promise<boolean>;
  /** Record a scheduled run's completion. Manual access-surface runs never do. */
  markWeekDone?: (weekId: string) => Promise<void>;
  setTimer?: (fn: () => void, ms: number) => TimerHandle;
  clearTimer?: (handle: TimerHandle) => void;
  log?: CompoundingWeeklyLog;
}

export type CompoundingWeeklyTick =
  | { status: "synthesized" | "skipped" | "failed"; weekId: string }
  | { status: "stopped" | "coalesced"; weekId: null };

export interface CompoundingWeeklySchedulerHandle {
  /** Run one check now (startup catch-up and tests). */
  tick(): Promise<CompoundingWeeklyTick>;
  /** Resolve when no tick is in flight, including a coalesced follow-up. */
  whenIdle(): Promise<void>;
  /** Prevent later ticks and wait for the one already running. */
  stop(): Promise<void>;
}

export function compoundingWeeklyReportPath(memoryDir: string, weekId: string): string {
  if (!isIsoWeekId(weekId)) {
    throw new Error("compounding weekly cron: week id must be YYYY-Www");
  }
  return path.join(memoryDir, "compounding", "weekly", `${weekId}.md`);
}

/**
 * Completion marker for scheduled runs only. A manual access-surface run can
 * synthesize the in-progress current week early; its report file must not
 * satisfy the scheduler's due check, or the evidence added after the manual
 * run would never reach that week's scheduled synthesis.
 */
export function compoundingWeeklyDoneMarkerPath(memoryDir: string, weekId: string): string {
  if (!isIsoWeekId(weekId)) {
    throw new Error("compounding weekly cron: week id must be YYYY-Www");
  }
  return path.join(memoryDir, "compounding", "weekly", ".scheduler", `${weekId}.done`);
}

async function defaultWeekDone(memoryDir: string, weekId: string): Promise<boolean> {
  try {
    await lstat(compoundingWeeklyDoneMarkerPath(memoryDir, weekId));
    return true;
  } catch (error) {
    if (isNotFound(error)) return false;
    throw error;
  }
}

async function defaultMarkWeekDone(memoryDir: string, weekId: string): Promise<void> {
  // Atomic: a partially written marker must never satisfy the skip check.
  await writeFileAtomically(compoundingWeeklyDoneMarkerPath(memoryDir, weekId), `${new Date().toISOString()}\n`);
}

function isNotFound(error: unknown): boolean {
  return typeof error === "object" && error !== null && "code" in error && error.code === "ENOENT";
}

export function startCompoundingWeeklyScheduler(
  options: CompoundingWeeklySchedulerOptions
): CompoundingWeeklySchedulerHandle {
  const now = options.now ?? (() => new Date());
  const logger = options.log ?? defaultLog;
  const weekDone = options.weekDone ?? ((weekId) => defaultWeekDone(options.memoryDir, weekId));
  const markWeekDone = options.markWeekDone ?? ((weekId) => defaultMarkWeekDone(options.memoryDir, weekId));
  const setTimer =
    options.setTimer ??
    ((fn, ms) => {
      const timer = setTimeout(fn, ms);
      timer.unref?.();
      return timer;
    });
  const clearTimer = options.clearTimer ?? ((handle) => clearTimeout(handle as NodeJS.Timeout));

  let stopped = false;
  let pending = false;
  let inFlight: Promise<CompoundingWeeklyTick> | null = null;
  let timer: TimerHandle | null = null;
  let retryWeekId: string | null = null;

  const runWeek = async (weekId: string): Promise<CompoundingWeeklyTick> => {
    try {
      if (await weekDone(weekId)) {
        if (retryWeekId === weekId) retryWeekId = null;
        logger.debug(`compounding weekly cron: ${weekId} already synthesized by the scheduler, skipping`);
        return { status: "skipped", weekId };
      }
      await options.synthesizeWeekly(weekId);
      await markWeekDone(weekId);
      logger.info(`compounding weekly cron: synthesized ${weekId}`);
      return { status: "synthesized", weekId };
    } catch (error) {
      retryWeekId = weekId;
      const name = error instanceof Error ? error.name : "Error";
      logger.warn(`compounding weekly cron: ${weekId} failed (${name}) — retrying on the next tick`);
      return { status: "failed", weekId };
    }
  };

  const arm = (): void => {
    if (stopped) return;
    if (timer) clearTimer(timer);
    const delay = msUntilNextIsoWeek(now());
    timer = setTimer(() => {
      timer = null;
      if (stopped) return;
      arm();
      void request();
    }, delay);
    timer.unref?.();
  };

  const doTick = async (): Promise<CompoundingWeeklyTick> => {
    const due = previousIsoWeekId(now());
    const weekId = retryWeekId ?? due;
    const first = await runWeek(weekId);
    if (first.status === "failed" || weekId === due) return first;
    return runWeek(due);
  };

  const request = (): Promise<CompoundingWeeklyTick> => {
    if (stopped) return Promise.resolve({ status: "stopped", weekId: null });
    if (inFlight) {
      pending = true;
      return inFlight.then(() => ({ status: "coalesced" as const, weekId: null }));
    }
    const run = doTick().finally(() => {
      inFlight = null;
      if (!stopped && pending) {
        pending = false;
        void request();
      }
    });
    inFlight = run;
    return run;
  };

  arm();
  void request();

  return {
    tick: () => request(),
    async whenIdle() {
      while (inFlight) await inFlight;
    },
    async stop() {
      stopped = true;
      pending = false;
      if (timer) clearTimer(timer);
      timer = null;
      while (inFlight) await inFlight;
    },
  };
}

/**
 * Arm the daemon weekly run when both compounding flags are on.
 * Returns null when the run stays off or arming fails. The returned handle's
 * first tick is already in flight and includes calibration via synthesizeWeekly.
 */
export function createCompoundingWeeklyCron(deps: {
  config: PluginConfig;
  getStorage?: () => StorageManager | undefined;
}): CompoundingWeeklySchedulerHandle | null {
  const caps = resolveConsolidationCapabilities(deps.config);
  if (!caps.compounding || !caps.compoundingWeeklyCron) return null;
  try {
    const engine = new CompoundingEngine(deps.config, deps.getStorage?.());
    const handle = startCompoundingWeeklyScheduler({
      memoryDir: deps.config.memoryDir,
      synthesizeWeekly: (weekId) => engine.synthesizeWeekly({ weekId }),
    });
    defaultLog.info("compounding weekly cron armed");
    return handle;
  } catch (error) {
    const name = error instanceof Error ? error.name : "Error";
    defaultLog.warn(`compounding weekly cron failed to arm (${name}) — non-fatal`);
    return null;
  }
}

/**
 * Location auto-sync — in-process periodic day sync (issue #2047).
 *
 * Arms one repeating timer that runs the SAME shared surface runner
 * (`runLocationSync`) as the CLI/MCP/HTTP surfaces over the configured
 * `location.syncDays` window ending yesterday, so late provider uploads are
 * picked up on the next tick. Master default-off: the caller (maintenance
 * scheduler registration) arms this only when `location.enabled` is true and
 * at least one source is enabled; a forced manual sync never bypasses those
 * gates — they live inside the pipeline itself.
 *
 * The timer is unref'd so one-shot CLI processes exit naturally; ticks are
 * serialized (an overlapping tick is skipped, not queued). ponytail: fixed
 * default cadence (daily) with no per-install override — add a
 * location.syncIntervalHours config field if installs need it.
 */

import { log } from "../logger.js";
import { runLocationSync, type LocationSyncRuns } from "./surfaces.js";
import type { LocationConfig } from "./types.js";

export const LOCATION_SYNC_DEFAULT_INTERVAL_MS = 24 * 60 * 60 * 1000;

export interface LocationAutoSyncSettings {
  config: LocationConfig;
  memoryDir: string;
  /** Tick cadence in ms; defaults to LOCATION_SYNC_DEFAULT_INTERVAL_MS. */
  intervalMs?: number;
  /** Clock/timer seam for tests. */
  setInterval?: (fn: () => void, ms: number) => { unref?: () => void };
  clearInterval?: (handle: unknown) => void;
}

export interface LocationAutoSyncDeps {
  /** Run a sync (defaults to the shared surface runner). */
  sync?: (deps: { config: LocationConfig; memoryDir: string }) => Promise<LocationSyncRuns>;
  log?: { info(message: string): void; warn(message: string): void };
}

export interface LocationAutoSyncHandle {
  /** Run one tick now (first-run hook and test seam). */
  tick(): Promise<void>;
  stop(): Promise<void>;
}

export function startLocationAutoSync(
  settings: LocationAutoSyncSettings,
  deps: LocationAutoSyncDeps = {},
): LocationAutoSyncHandle {
  const logger = deps.log ?? log;
  const intervalMs = settings.intervalMs ?? LOCATION_SYNC_DEFAULT_INTERVAL_MS;
  const setIntervalImpl = settings.setInterval ?? ((fn: () => void, ms: number) => setInterval(fn, ms));
  const clearIntervalImpl = settings.clearInterval ?? ((handle: unknown) => clearInterval(handle as NodeJS.Timeout));
  const sync =
    deps.sync ??
    ((deps: { config: LocationConfig; memoryDir: string }) =>
      runLocationSync({ config: deps.config, memoryDir: deps.memoryDir }));
  let inFlight: Promise<void> | null = null;
  let stopped = false;
  const timer = setIntervalImpl(() => {
    if (inFlight !== null || stopped) return;
    inFlight = (async () => {
      try {
        const runs = await sync({ config: settings.config, memoryDir: settings.memoryDir });
        const failed = runs.some((run) => run.results.some((result) => result.status === "failed"));
        if (failed) {
          logger.warn("location auto-sync: one or more sources failed — retrying on the next tick");
        } else {
          logger.info(
            `location auto-sync: refreshed ${settings.config.syncDays}-day window across ${settings.config.sources.length} source(s)`,
          );
        }
      } catch (err) {
        // An abort raised by stop() is intentional shutdown, not a failure.
        if (err instanceof Error && err.name === "AbortError") return;
        logger.warn(
          `location auto-sync failed: ${err instanceof Error ? err.name : "unknown error"} — retrying on the next tick`,
        );
      } finally {
        inFlight = null;
      }
    })();
  }, intervalMs);
  timer.unref?.();
  return {
    async tick() {
      const runs = await sync({ config: settings.config, memoryDir: settings.memoryDir });
      logger.info(
        `location auto-sync tick: ${runs.length} day(s) across ${settings.config.sources.length} source(s)`,
      );
    },
    async stop() {
      stopped = true;
      clearIntervalImpl(timer);
      await inFlight;
    },
  };
}

/**
 * Activity (screen-capture) sync lifecycle owner (issue #1900).
 *
 * The MaintenanceScheduler used to inline the arm / re-arm / teardown wiring
 * for the periodic activity sync, which made the lifecycle invariants easy to
 * break one edit at a time. This module centralizes them in one testable place:
 *
 *  - Re-arm and teardown BOTH stop any prior scheduler first, so a repeated
 *    registration never orphans a running interval.
 *  - An aborted deferred-init signal means teardown began. `destroy()` aborts
 *    the init signal *before* it disposes, so an aborted signal here also
 *    implies `dispose()` may already have latched teardown. `register()` never
 *    arms nor clears the latch while aborted — even when the abort lands
 *    mid-drain — so a late re-init cannot resurrect a torn-down instance.
 *  - The teardown latch gates the reindex-failure retry, so a draining tick's
 *    `onRun` cannot queue QMD maintenance after teardown.
 *  - Activity digests + SQLite are written in the clear, so the registrar
 *    refuses to arm under a secure store rather than silently bypass opted-in
 *    at-rest encryption.
 *
 * Host-agnostic: the scheduler factory is injectable, so tests drive the whole
 * lifecycle against a fake scheduler without real timers.
 */

import { refreshActivityIndex, type ActivityIndexRefresher } from "./reindex.js";
import type { ActivitySyncRunSummary } from "./runner.js";
import { ActivitySyncScheduler, type ActivitySyncSchedulerOptions } from "./scheduler.js";
import type { PluginConfig } from "../types.js";
import type { ActivityConfig } from "./types.js";
import { log } from "../logger.js";

/** The scheduler surface the registrar drives (injectable for tests). */
export interface ActivitySyncSchedulerLike {
  start(): unknown;
  stop(): Promise<void>;
}

export interface ActivitySyncRegistrarDeps {
  /** Activity sync settings; the master default-off flag lives here. */
  readonly config: ActivityConfig;
  /** Memory root the digests + SQLite store live under. */
  readonly memoryDir: string;
  /** QMD collection the day digest is (strictly) reindexed into. */
  readonly qmdCollection: string;
  /**
   * True when at-rest encryption is configured. Activity writes are not yet
   * encrypted, so the registrar refuses to arm rather than leak plaintext.
   */
  readonly secureStoreEnabled: boolean;
  /** Live QMD accessor — the host may swap backends after construction. */
  readonly getQmd: () => ActivityIndexRefresher;
  /** Debounced/singleflighted QMD retry used when a tick's reindex fails. */
  readonly requestReindexRetry: () => void;
  /**
   * Tail step (issue #1900): observe a completed sync tick so a dependent
   * subsystem (meeting building) can rebuild the affected day(s). Fired only
   * after a durable tick and never after teardown. Optional; omitted by hosts
   * that do not build meetings.
   */
  readonly onSynced?: (summary: ActivitySyncRunSummary) => void;
  /** Scheduler factory (injectable for tests); defaults to the real scheduler. */
  readonly createScheduler?: (options: ActivitySyncSchedulerOptions) => ActivitySyncSchedulerLike;
  /** Full plugin config so the default runner can build analysis clients. */
  readonly pluginConfig?: PluginConfig;
}

export class ActivitySyncRegistrar {
  private scheduler: ActivitySyncSchedulerLike | null = null;
  /** Latched by dispose() so a draining tick's onRun cannot re-arm maintenance. */
  private disposed = false;
  private readonly createScheduler: (options: ActivitySyncSchedulerOptions) => ActivitySyncSchedulerLike;

  constructor(private readonly deps: ActivitySyncRegistrarDeps) {
    this.createScheduler = deps.createScheduler ?? ((options) => new ActivitySyncScheduler(options));
  }

  /** True while a scheduler is armed (test/telemetry observability). */
  get armed(): boolean {
    return this.scheduler !== null;
  }

  /**
   * Arm (or re-arm) the periodic sync for the current lifecycle. Idempotent and
   * safe to call repeatedly; always stops a prior scheduler first.
   */
  async register(signal: AbortSignal): Promise<void> {
    // Re-arm or teardown: stop any prior scheduler before anything else, so a
    // repeated registration never orphans a running interval.
    const prior = this.scheduler;
    this.scheduler = null;
    await prior?.stop();
    // Teardown began (possibly during the drain above). Never arm nor clear the
    // latch: dispose() may already have set it, and it must stay set.
    if (signal.aborted) return;
    // Opted-in at-rest encryption must not be silently bypassed: activity
    // digests + SQLite are written in the clear, so refuse to run under it.
    if (this.deps.secureStoreEnabled && this.deps.config.enabled) {
      log.warn(
        "activity sync disabled: secure store is enabled but activity digests/SQLite are not encrypted at rest",
      );
      return;
    }
    // Committed to a fresh lifecycle: clear the latch so this scheduler's
    // reindex retries fire again.
    this.disposed = false;
    try {
      const scheduler = this.createScheduler({
        config: this.deps.config,
        memoryDir: this.deps.memoryDir,
        intervalMs: this.deps.config.autoSyncIntervalMinutes * 60_000,
        // Strict refresh after each digest write (rule 31): bypasses the
        // min-interval gate and throws on a real failure.
        reindexSearch: (sig) => refreshActivityIndex(this.deps.getQmd(), this.deps.qmdCollection, sig),
        ...(this.deps.pluginConfig === undefined ? {} : { pluginConfig: this.deps.pluginConfig }),
        // A failed reindex (QMD down) leaves the next unchanged-digest tick
        // skipping afterWrites, so route the retry through the durable,
        // throttled QMD path — but never after teardown.
        onRun: (summary: ActivitySyncRunSummary) => {
          if (summary.reindexErrorCount > 0 && !this.disposed) {
            log.warn(
              `activity sync: ${summary.reindexErrorCount} source(s) had a failed reindex; queuing a maintenance retry`,
            );
            this.deps.requestReindexRetry();
          }
          // Tail step: a durable tick that ingested snapshots may have changed a
          // meeting's screen context; notify the dependent builder. Never after
          // teardown.
          if (summary.enabled && summary.totalInserted > 0 && !this.disposed) {
            this.deps.onSynced?.(summary);
          }
        },
      });
      this.scheduler = scheduler;
      scheduler.start();
      // Close the race where abort fires between the guard above and start().
      if (signal.aborted) {
        await scheduler.stop();
        this.scheduler = null;
      }
    } catch (err) {
      log.debug(`activity sync scheduler start failed (non-fatal): ${err}`);
    }
  }

  /**
   * Latch teardown and drain the scheduler. Latching first ensures a draining
   * tick's onRun cannot queue a retry; the drain is awaited so no in-flight
   * tick keeps writing after teardown.
   */
  async dispose(): Promise<void> {
    this.disposed = true;
    const drain = this.scheduler?.stop();
    this.scheduler = null;
    await drain;
  }
}

import { appendFile, mkdir } from "node:fs/promises";
import path from "node:path";
import type { MemoryFile } from "./types.js";
import { StorageManager } from "./storage.js";
import type { MemoryTier } from "./tier-routing.js";
import type { SearchBackend } from "./search/port.js";

export type { MemoryTier } from "./tier-routing.js";

export interface TierMigrationRequest {
  memory: MemoryFile;
  fromTier: MemoryTier;
  toTier: MemoryTier;
  reason: string;
}

export interface TierMigrationResult {
  memoryId: string;
  fromTier: MemoryTier;
  toTier: MemoryTier;
  changed: boolean;
  reason: string;
  targetPath: string;
}

export interface TierMigrationExecutorOptions {
  storage: StorageManager;
  qmd: SearchBackend;
  hotCollection: string;
  coldCollection: string;
  autoEmbed?: boolean;
  journalPath?: string;
}

type TierMigrationJournalEntry = {
  ts: string;
  memoryId: string;
  fromTier: MemoryTier;
  toTier: MemoryTier;
  changed: boolean;
  reason: string;
  targetPath: string;
};

export class TierMigrationExecutor {
  private readonly storage: StorageManager;
  private readonly qmd: SearchBackend;
  private readonly hotCollection: string;
  private readonly coldCollection: string;
  private readonly autoEmbed: boolean;
  private readonly journalPath: string;

  constructor(options: TierMigrationExecutorOptions) {
    this.storage = options.storage;
    this.qmd = options.qmd;
    this.hotCollection = options.hotCollection;
    this.coldCollection = options.coldCollection;
    this.autoEmbed = options.autoEmbed === true;
    this.journalPath = options.journalPath ?? path.join(this.storage.dir, "state", "tier-migration-journal.jsonl");
  }

  async migrateMemory(request: TierMigrationRequest): Promise<TierMigrationResult> {
    const { memory, fromTier, toTier, reason } = request;
    const targetPath = this.storage.buildTierMemoryPath(memory, toTier);

    if (fromTier === toTier) {
      const noChange: TierMigrationResult = {
        memoryId: memory.frontmatter.id,
        fromTier,
        toTier,
        changed: false,
        reason,
        targetPath,
      };
      await this.appendJournal(noChange);
      return noChange;
    }

    const moved = await this.storage.migrateMemoryToTier(memory, toTier);
    const result: TierMigrationResult = {
      memoryId: memory.frontmatter.id,
      fromTier,
      toTier,
      changed: moved.changed,
      reason,
      targetPath: moved.targetPath,
    };

    await this.appendJournal(result);

    const destinationCollection = this.collectionForTier(toTier);
    const sourceCollection = this.collectionForTier(fromTier);
    await this.updateCollectionFromTierRoot(destinationCollection, toTier);
    if (sourceCollection !== destinationCollection && this.qmd.updatesAllCollections?.() !== true) {
      await this.updateCollectionFromTierRoot(sourceCollection, fromTier);
    }
    if (this.autoEmbed) {
      await this.qmd.embedCollection(destinationCollection);
      if (sourceCollection !== destinationCollection) {
        await this.qmd.embedCollection(sourceCollection);
      }
    }

    return result;
  }

  private collectionForTier(tier: MemoryTier): string {
    return tier === "cold" ? this.coldCollection : this.hotCollection;
  }

  private async updateCollectionFromTierRoot(collection: string, tier: MemoryTier): Promise<void> {
    const memoryDir = tier === "cold" ? path.join(this.storage.dir, "cold") : this.storage.dir;
    if (this.qmd.updatesAllCollections?.() !== true && this.qmd.updateCollectionFromDir) {
      await this.qmd.updateCollectionFromDir(collection, memoryDir);
      return;
    }
    await this.qmd.updateCollection(collection);
  }

  private async appendJournal(result: TierMigrationResult): Promise<void> {
    const entry: TierMigrationJournalEntry = {
      ts: new Date().toISOString(),
      memoryId: result.memoryId,
      fromTier: result.fromTier,
      toTier: result.toTier,
      changed: result.changed,
      reason: result.reason,
      targetPath: result.targetPath,
    };
    await mkdir(path.dirname(this.journalPath), { recursive: true });
    await appendFile(this.journalPath, `${JSON.stringify(entry)}\n`, "utf-8");
  }
}

/**
 * @remnic/core — Path Containment Guards
 *
 * Shared symlink/traversal containment helpers for filesystem walkers that
 * scan the memory store. Extracted from search/document-scanner.ts so every
 * walker (the search index scanner, the CLI dedupe walker, ...) enforces the
 * SAME containment semantics instead of forking the check (CLAUDE.md rule 22).
 *
 * Both helpers operate on realpath()-resolved absolute paths: callers resolve
 * symlinks first, then assert the resolved target is still inside the (also
 * realpath-resolved) memory root. This blocks a symlinked category directory
 * (e.g. decisions/ → /etc) from redirecting a scan — or a destructive dedupe
 * unlink — outside the memory store.
 */

import path from "node:path";
import { lstat, mkdir, readdir, realpath } from "node:fs/promises";
import { isErrnoCode } from "./errno.js";

/**
 * True when `child` is `parent` itself or nested underneath it. Both arguments
 * must already be resolved (realpath) absolute paths.
 */
export function pathIsInside(parent: string, child: string): boolean {
  const relative = path.relative(parent, child);
  return relative === "" || (!relative.startsWith("..") && !path.isAbsolute(relative));
}

/**
 * Throw if the realpath-resolved `candidateReal` escapes `rootReal`. The
 * message references the original (pre-realpath) path so operators can locate
 * the offending symlink/entry.
 */
export function assertPathInsideRoot(
  rootReal: string,
  candidateReal: string,
  originalPath: string,
): void {
  if (!pathIsInside(rootReal, candidateReal)) {
    throw new Error(`Refusing to scan memory path outside memoryDir: ${originalPath}`);
  }
}

/**
 * List the regular-file children of `dir` whose name ends in `suffix` (default
 * `.jsonl`) in sorted name order as absolute paths, rejecting a symlinked/
 * non-directory `dir` and skipping any entry that is a symlink or whose realpath
 * escapes `dir`. Returns `[]` when the directory is absent or cannot be safely
 * enumerated. Used by the durable pending-spill drains (lifecycle ledger +
 * recall impressions, #2033) so a poisoned link planted in a spill directory
 * cannot redirect a secure read — or a later unlink — outside that directory.
 * The `suffix` override lets the lifecycle drain enumerate crash-orphaned
 * `*.jsonl.claimed` files with the SAME containment guard as live spills.
 */
export async function listContainedSpillFiles(dir: string, suffix = ".jsonl"): Promise<string[]> {
  let dirReal: string;
  try {
    const dirStat = await lstat(dir);
    if (dirStat.isSymbolicLink() || !dirStat.isDirectory()) return [];
    dirReal = await realpath(dir);
  } catch (err) {
    if (isErrnoCode(err, "ENOENT")) return [];
    throw err;
  }
  let names: string[];
  try {
    names = (await readdir(dir)).filter((name) => name.endsWith(suffix)).sort();
  } catch (err) {
    if (isErrnoCode(err, "ENOENT")) return [];
    throw err;
  }
  const files: string[] = [];
  for (const name of names) {
    const filePath = path.join(dir, name);
    let entryStat;
    try {
      entryStat = await lstat(filePath);
    } catch (err) {
      if (isErrnoCode(err, "ENOENT")) continue; // vanished between readdir and lstat
      throw err;
    }
    // Reject a symlinked entry or one whose real target escapes the spill dir
    // BEFORE any secure read/delete: a poisoned link must never redirect a
    // decrypt or a later unlink outside the directory (#2033).
    if (entryStat.isSymbolicLink() || !entryStat.isFile()) continue;
    let entryReal: string;
    try {
      entryReal = await realpath(filePath);
    } catch (err) {
      if (isErrnoCode(err, "ENOENT")) continue;
      throw err;
    }
    if (!pathIsInside(dirReal, entryReal)) continue;
    files.push(filePath);
  }
  return files;
}

/**
 * Create `dir` (recursively, if absent) and assert it is a REAL directory —
 * never a symlink — BEFORE any spill file is written into it (#2033). This
 * mirrors the lstat guard {@link listContainedSpillFiles} applies on the read
 * side so the durable-spill WRITE and its later drain enforce the SAME
 * symlink-safe containment: a symlink planted at the spill-directory path (e.g.
 * `<ledger>.pending.d` -> /etc) cannot redirect a write/rename/unlink outside
 * the intended location. `mkdir` recursive is a no-op when the path already
 * resolves through a symlink, so the post-mkdir lstat is what actually refuses
 * the poisoned link. Throws on a symlinked or non-directory target.
 */
export async function ensureContainedSpillDir(dir: string): Promise<void> {
  await mkdir(dir, { recursive: true });
  const dirStat = await lstat(dir);
  if (dirStat.isSymbolicLink() || !dirStat.isDirectory()) {
    throw new Error(`Refusing to write spill file into symlinked or non-directory path: ${dir}`);
  }
}

import { clamp01 } from "./lifecycle.js";
import type { TierRoutingPolicy } from "./tier-routing.js";
import { readUtilityLearningSnapshot } from "./utility-learner.js";

const RANKING_MULTIPLIER_LIMIT = 0.12;
const PROMOTION_THRESHOLD_DELTA_LIMIT = 0.07;
const PROMOTION_THRESHOLD_WEIGHT_FACTOR = 0.2;

export interface UtilityRuntimeValues {
  rankingBoostMultiplier: number;
  rankingSuppressMultiplier: number;
  promoteThresholdDelta: number;
  demoteThresholdDelta: number;
  snapshotUpdatedAt: string;
}

function roundRuntimeValue(value: number): number {
  return Math.round(value * 1000) / 1000;
}

function clampSigned(value: number, limit: number): number {
  if (!Number.isFinite(value) || limit <= 0) return 0;
  return Math.max(-limit, Math.min(limit, value));
}

function learnedWeightFor(
  snapshot: NonNullable<Awaited<ReturnType<typeof readUtilityLearningSnapshot>>>,
  target: "promotion" | "ranking",
  decision: "promote" | "demote" | "boost" | "suppress",
): number {
  const entry = snapshot.weights.find((weight) => weight.target === target && weight.decision === decision);
  return entry?.learnedWeight ?? 0;
}

export async function loadUtilityRuntimeValues(options: {
  memoryDir: string;
  utilityTelemetryDir?: string;
  memoryUtilityLearningEnabled: boolean;
  promotionByOutcomeEnabled: boolean;
}): Promise<UtilityRuntimeValues | null> {
  if (!options.memoryUtilityLearningEnabled || !options.promotionByOutcomeEnabled) return null;
  const snapshot = await readUtilityLearningSnapshot(options.memoryDir, options.utilityTelemetryDir);
  if (!snapshot) return null;

  return {
    rankingBoostMultiplier: roundRuntimeValue(
      1 + clampSigned(learnedWeightFor(snapshot, "ranking", "boost"), RANKING_MULTIPLIER_LIMIT),
    ),
    rankingSuppressMultiplier: roundRuntimeValue(
      1 + clampSigned(learnedWeightFor(snapshot, "ranking", "suppress"), RANKING_MULTIPLIER_LIMIT),
    ),
    promoteThresholdDelta: roundRuntimeValue(
      clampSigned(
        learnedWeightFor(snapshot, "promotion", "promote") * -PROMOTION_THRESHOLD_WEIGHT_FACTOR,
        PROMOTION_THRESHOLD_DELTA_LIMIT,
      ),
    ),
    demoteThresholdDelta: roundRuntimeValue(
      clampSigned(
        learnedWeightFor(snapshot, "promotion", "demote") * PROMOTION_THRESHOLD_WEIGHT_FACTOR,
        PROMOTION_THRESHOLD_DELTA_LIMIT,
      ),
    ),
    snapshotUpdatedAt: snapshot.updatedAt,
  };
}

export function applyUtilityRankingRuntimeDelta(
  delta: number,
  runtime: UtilityRuntimeValues | null,
  mode: "boost" | "suppress",
): number {
  if (!runtime || !Number.isFinite(delta) || delta === 0) return delta;
  const multiplier = mode === "boost" ? runtime.rankingBoostMultiplier : runtime.rankingSuppressMultiplier;
  return roundRuntimeValue(delta * multiplier);
}

export function applyUtilityPromotionRuntimePolicy(
  policy: TierRoutingPolicy,
  runtime: UtilityRuntimeValues | null,
): TierRoutingPolicy {
  if (!runtime) return policy;
  return {
    ...policy,
    demotionValueThreshold: roundRuntimeValue(clamp01(policy.demotionValueThreshold + runtime.demoteThresholdDelta)),
    promotionValueThreshold: roundRuntimeValue(clamp01(policy.promotionValueThreshold + runtime.promoteThresholdDelta)),
  };
}

import { type LifecycleSignals, clamp01, computeLifecycleValueInputs, daysSince } from "./lifecycle.js";
import { hasLiveSupportPassportCard } from "./support-passport/card-projection.js";
import type { MemoryFile } from "./types.js";

export type MemoryTier = "hot" | "cold";

export interface TierRoutingPolicy {
  enabled: boolean;
  demotionMinAgeDays: number;
  demotionValueThreshold: number;
  promotionValueThreshold: number;
}

export interface TierTransitionDecision {
  currentTier: MemoryTier;
  nextTier: MemoryTier;
  valueScore: number;
  changed: boolean;
  reason: string;
}

function requiresHotTier(memory: Pick<MemoryFile, "frontmatter" | "content">): boolean {
  return hasLiveSupportPassportCard(memory);
}

export function computeTierValueScore(
  memory: Pick<MemoryFile, "frontmatter">,
  now: Date,
  signals?: LifecycleSignals
): number {
  const fm = memory.frontmatter;
  const inputs = computeLifecycleValueInputs(memory, now, signals);
  const correctionBoost = fm.category === "correction" ? 0.08 : 0;
  const confirmedBoost = fm.verificationState === "user_confirmed" ? 0.05 : 0;

  const score =
    inputs.confidence * 0.24 +
    inputs.access * 0.26 +
    inputs.recency * 0.2 +
    inputs.importance * 0.2 +
    inputs.feedback * 0.1 +
    correctionBoost +
    confirmedBoost -
    inputs.disputedPenalty * 0.5;

  return clamp01(score);
}

export function decideTierTransition(
  memory: Pick<MemoryFile, "frontmatter" | "content">,
  currentTier: MemoryTier,
  policy: TierRoutingPolicy,
  now: Date,
  signals?: LifecycleSignals
): TierTransitionDecision {
  const valueScore = computeTierValueScore(memory, now, signals);
  if (!policy.enabled) {
    return {
      currentTier,
      nextTier: currentTier,
      valueScore,
      changed: false,
      reason: "tier_migration_disabled",
    };
  }

  if (requiresHotTier(memory)) {
    return {
      currentTier,
      nextTier: "hot",
      valueScore,
      changed: currentTier !== "hot",
      reason: "support_passport_card_requires_hot_tier",
    };
  }

  if (currentTier === "hot") {
    const ageDays = daysSince(memory.frontmatter.updated ?? memory.frontmatter.created, now.getTime());
    if (ageDays >= policy.demotionMinAgeDays && valueScore <= policy.demotionValueThreshold) {
      return {
        currentTier,
        nextTier: "cold",
        valueScore,
        changed: true,
        reason: "value_below_demotion_threshold",
      };
    }
    return {
      currentTier,
      nextTier: currentTier,
      valueScore,
      changed: false,
      reason: ageDays < policy.demotionMinAgeDays ? "demotion_min_age_not_met" : "value_above_demotion_threshold",
    };
  }

  if (valueScore >= policy.promotionValueThreshold) {
    return {
      currentTier,
      nextTier: "hot",
      valueScore,
      changed: true,
      reason: "value_above_promotion_threshold",
    };
  }
  return {
    currentTier,
    nextTier: currentTier,
    valueScore,
    changed: false,
    reason: "value_below_promotion_threshold",
  };
}

import type {
  CompressionGuidelineOptimizerActionSummary,
  CompressionGuidelineOptimizerEventCounts,
  CompressionGuidelineOptimizerRuleUpdate,
  CompressionGuidelineOptimizerState,
  MemoryActionEvent,
  MemoryActionOutcome,
  MemoryActionType,
} from "./types.js";

export interface CompressionGuidelineCandidate {
  generatedAt: string;
  sourceWindow: {
    from: string;
    to: string;
  };
  eventCounts: CompressionGuidelineOptimizerEventCounts;
  actionSummaries: CompressionGuidelineOptimizerActionSummary[];
  ruleUpdates: CompressionGuidelineOptimizerRuleUpdate[];
  guidelineVersion: number;
  optimizerVersion: number;
}

export interface CompressionSemanticRuleRefinement {
  action: MemoryActionType;
  delta?: number;
  confidence?: "low" | "medium" | "high";
  note?: string;
}

export interface CompressionSemanticRefinementResult {
  updates: CompressionSemanticRuleRefinement[];
}

export interface CompressionSemanticRefinementOptions {
  enabled: boolean;
  timeoutMs: number;
  runRefinement?: (
    candidate: CompressionGuidelineCandidate,
  ) => Promise<CompressionSemanticRefinementResult | null>;
}

const MAX_DELTA = 0.15;
const SPARSE_SAMPLE = 5;

function clamp(value: number, min: number, max: number): number {
  return Math.min(max, Math.max(min, value));
}

function parseRecallQuality(reason: string | undefined): "good" | "poor" | "unknown" {
  if (!reason) return "unknown";
  const text = reason.toLowerCase();
  if (/\bunresolved\b|\b(?:not|never|no|without)\s+(?:yet\s+)?resolved\b/.test(text)) {
    return "poor";
  }
  if (/(recall[_\s-]?good|quality[:=]\s*(good|high)|\bimprov(?:e|ed|ing)\b|\bresolved\b)/.test(text)) {
    return "good";
  }
  if (/(recall[_\s-]?poor|quality[:=]\s*(poor|low)|\bdegrad(?:e|ed|ing)\b|\bmiss(?:ed|ing)\b|\birrelevant\b)/.test(text)) {
    return "poor";
  }
  return "unknown";
}

function nextGuidelineVersion(previousState: CompressionGuidelineOptimizerState | null): number {
  if (!previousState) return 1;
  return Math.max(1, previousState.guidelineVersion + 1);
}

function nextOptimizerVersion(previousState: CompressionGuidelineOptimizerState | null): number {
  if (!previousState) return 1;
  return Math.max(1, previousState.version + 1);
}

function roundDelta(value: number): number {
  return Math.round(value * 1000) / 1000;
}

function confidenceForDelta(delta: number): "low" | "medium" | "high" {
  const magnitude = Math.abs(delta);
  return magnitude >= 0.09 ? "high" : magnitude >= 0.04 ? "medium" : "low";
}

function directionForDelta(delta: number): "increase" | "decrease" | "hold" {
  return delta > 0 ? "increase" : delta < 0 ? "decrease" : "hold";
}

export function computeCompressionGuidelineCandidate(
  events: MemoryActionEvent[],
  options: {
    generatedAtIso?: string;
    previousState?: CompressionGuidelineOptimizerState | null;
  } = {},
): CompressionGuidelineCandidate {
  const generatedAt = options.generatedAtIso ?? new Date().toISOString();
  const previousState = options.previousState ?? null;
  const effectiveEvents = events.filter((event) => event.dryRun !== true);
  const totalCounts: CompressionGuidelineOptimizerEventCounts = {
    total: effectiveEvents.length,
    applied: 0,
    skipped: 0,
    failed: 0,
  };

  const actionMap = new Map<MemoryActionType, CompressionGuidelineOptimizerActionSummary>();
  let windowFrom = effectiveEvents[0]?.timestamp ?? generatedAt;
  let windowTo = effectiveEvents[0]?.timestamp ?? generatedAt;

  for (const event of effectiveEvents) {
    if (event.timestamp < windowFrom) windowFrom = event.timestamp;
    if (event.timestamp > windowTo) windowTo = event.timestamp;
    totalCounts[event.outcome] += 1;

    let summary = actionMap.get(event.action);
    if (!summary) {
      summary = {
        action: event.action,
        total: 0,
        outcomes: { applied: 0, skipped: 0, failed: 0 },
        quality: { good: 0, poor: 0, unknown: 0 },
      };
      actionMap.set(event.action, summary);
    }

    summary.total += 1;
    summary.outcomes[event.outcome] += 1;
    const quality = parseRecallQuality(event.reason);
    summary.quality[quality] += 1;
  }

  const actionSummaries = [...actionMap.values()].sort((a, b) => {
    if (b.total !== a.total) return b.total - a.total;
    return a.action.localeCompare(b.action);
  });

  const ruleUpdates = actionSummaries.map((summary): CompressionGuidelineOptimizerRuleUpdate => {
    const notes: string[] = [];
    if (summary.total < SPARSE_SAMPLE) {
      notes.push("Sparse sample size; holding baseline policy.");
      return {
        action: summary.action,
        delta: 0,
        direction: "hold",
        confidence: "low",
        notes,
      };
    }

    const successRate = summary.outcomes.applied / summary.total;
    const failureRate = summary.outcomes.failed / summary.total;
    const qualitySeen = summary.quality.good + summary.quality.poor;
    const qualitySignal = qualitySeen > 0
      ? (summary.quality.good - summary.quality.poor) / qualitySeen
      : 0;
    const rawDelta = clamp((successRate - failureRate) * 0.12 + qualitySignal * 0.06, -MAX_DELTA, MAX_DELTA);
    const delta = roundDelta(rawDelta);

    const direction = directionForDelta(delta);
    if (direction === "decrease" && summary.outcomes.failed > summary.outcomes.applied) {
      notes.push("Failures exceed applied outcomes; conservative down-adjustment.");
    } else if (direction === "increase" && summary.quality.good > summary.quality.poor) {
      notes.push("Good recall quality markers support this action.");
    } else if (direction === "decrease" && summary.quality.poor > summary.quality.good) {
      notes.push("Poor recall quality markers exceed good markers.");
    } else {
      notes.push("Outcomes are stable; keep bounded adjustments.");
    }

    const confidence = confidenceForDelta(delta);
    return {
      action: summary.action,
      delta,
      direction,
      confidence,
      notes,
    };
  });

  return {
    generatedAt,
    sourceWindow: {
      from: effectiveEvents.length > 0 ? windowFrom : generatedAt,
      to: effectiveEvents.length > 0 ? windowTo : generatedAt,
    },
    eventCounts: totalCounts,
    actionSummaries,
    ruleUpdates,
    guidelineVersion: nextGuidelineVersion(previousState),
    optimizerVersion: nextOptimizerVersion(previousState),
  };
}

export async function refineCompressionGuidelineCandidateSemantically(
  baseline: CompressionGuidelineCandidate,
  options: CompressionSemanticRefinementOptions,
): Promise<CompressionGuidelineCandidate> {
  if (!options.enabled) return baseline;
  if (typeof options.runRefinement !== "function") return baseline;

  const timeoutMs = Math.max(1, Math.floor(options.timeoutMs));
  let timeoutId: ReturnType<typeof setTimeout> | null = null;
  const timeout = new Promise<CompressionSemanticRefinementResult | null>((resolve) => {
    timeoutId = setTimeout(() => resolve(null), timeoutMs);
  });

  const refinementPromise = options.runRefinement(baseline).catch(() => null);

  let refinement: CompressionSemanticRefinementResult | null = null;
  try {
    refinement = await Promise.race([refinementPromise, timeout]);
  } catch {
    if (timeoutId) clearTimeout(timeoutId);
    return baseline;
  }
  if (timeoutId) clearTimeout(timeoutId);
  if (!refinement || !Array.isArray(refinement.updates) || refinement.updates.length === 0) {
    return baseline;
  }

  const updatesByAction = new Map<MemoryActionType, CompressionSemanticRuleRefinement>();
  for (const update of refinement.updates) {
    if (!update || typeof update.action !== "string") continue;
    updatesByAction.set(update.action, update);
  }

  let changed = false;
  const ruleUpdates = baseline.ruleUpdates.map((rule) => {
    const patch = updatesByAction.get(rule.action);
    if (!patch) return rule;

    const nextDelta =
      typeof patch.delta === "number" && Number.isFinite(patch.delta)
        ? roundDelta(clamp(patch.delta, -MAX_DELTA, MAX_DELTA))
        : rule.delta;
    const nextConfidence = patch.confidence ?? confidenceForDelta(nextDelta);
    const nextDirection = directionForDelta(nextDelta);
    const nextNotes =
      typeof patch.note === "string" && patch.note.trim().length > 0
        ? [patch.note.trim()]
        : rule.notes;

    if (
      nextDelta !== rule.delta ||
      nextDirection !== rule.direction ||
      nextConfidence !== rule.confidence ||
      nextNotes.join("\n") !== rule.notes.join("\n")
    ) {
      changed = true;
    }

    return {
      ...rule,
      delta: nextDelta,
      direction: nextDirection,
      confidence: nextConfidence,
      notes: nextNotes,
    };
  });

  if (!changed) return baseline;
  return {
    ...baseline,
    ruleUpdates,
  };
}

export function renderCompressionGuidelinesMarkdown(candidate: CompressionGuidelineCandidate): string {
  const actionLines =
    candidate.actionSummaries.length === 0
      ? ["- (none)"]
      : candidate.actionSummaries.map((item) => `- ${item.action}: ${item.total}`);
  const outcomeLines: string[] = [
    `- applied: ${candidate.eventCounts.applied}`,
    `- skipped: ${candidate.eventCounts.skipped}`,
    `- failed: ${candidate.eventCounts.failed}`,
  ];
  const updateLines =
    candidate.ruleUpdates.length === 0
      ? ["- No telemetry events available yet. Keep defaults conservative and gather action data first."]
      : candidate.ruleUpdates.map((update) => {
          const sign = update.delta > 0 ? "+" : "";
          return `- ${update.action}: ${update.direction} (${sign}${update.delta.toFixed(3)}, confidence=${update.confidence}) — ${update.notes.join(" ")}`;
        });

  return [
    "# Compression Guidelines",
    "",
    `Generated: ${candidate.generatedAt}`,
    `Source events analyzed: ${candidate.eventCounts.total}`,
    `Source window: ${candidate.sourceWindow.from} -> ${candidate.sourceWindow.to}`,
    `Guideline version: ${candidate.guidelineVersion}`,
    "",
    "## Action Distribution",
    ...actionLines,
    "",
    "## Outcome Distribution",
    ...outcomeLines,
    "",
    "## Suggested Guidelines",
    ...updateLines,
    "",
  ].join("\n");
}

export function buildCompressionGuidelinesMarkdown(
  events: MemoryActionEvent[],
  generatedAtIso: string = new Date().toISOString(),
  previousState: CompressionGuidelineOptimizerState | null = null,
): string {
  const candidate = computeCompressionGuidelineCandidate(events, {
    generatedAtIso,
    previousState,
  });
  return renderCompressionGuidelinesMarkdown(candidate);
}

/**
 * Batch temporal/tag index mutations.
 *
 * Split from temporal-index.ts (issue #1911B / #1995): maintenance loops that
 * add or invalidate N memories at once collect their entries and call these once
 * instead of paying the per-memory read-parse-stringify-write amplification.
 * Both operations reuse the low-level primitives exported from temporal-index.ts;
 * per-entry semantics are byte-identical to indexMemoryAsync / deindexMemoryAsync.
 */

import {
  INDEX_VERSION,
  addPathToSet,
  addTagGraphEntry,
  ensureStateDir,
  isoDateFromTimestamp,
  removePathFromAllSets,
  removePathFromAllTagEntries,
  removePathFromSet,
  removeTagGraphEntry,
  temporalEventFromEntry,
  updateTagIndex,
  updateTemporalIndex,
  withMemoryDirMutex,
  type TemporalIndexEntry,
} from "./temporal-index.js";

/**
 * Batch-add multiple memories to both indexes in a single read-modify-write cycle.
 * More efficient than calling indexMemoryAsync() per file when adding many at once.
 */
export async function indexMemoriesBatchAsync(
  memoryDir: string,
  entries: TemporalIndexEntry[]
): Promise<void> {
  if (entries.length === 0) return;
  try {
    await ensureStateDir(memoryDir);

    await withMemoryDirMutex(memoryDir, async () => {
      const temporalOk = await updateTemporalIndex(memoryDir, (index) => {
        index.version = INDEX_VERSION;
        for (const entry of entries) {
          const dateKey = isoDateFromTimestamp(entry.createdAt);
          removePathFromAllSets(index.dates, entry.path);
          addPathToSet(index.dates, dateKey, entry.path);
          index.events[entry.path] = temporalEventFromEntry(entry);
        }
      });
      if (temporalOk) {
        await updateTagIndex(memoryDir, (index) => {
          for (const entry of entries) {
            removePathFromAllTagEntries(index, entry.path);
            for (const tag of entry.tags) {
              if (tag && typeof tag === "string") {
                addTagGraphEntry(index, tag, entry.path);
              }
            }
          }
        });
      }
    });
  } catch {
    // Fail silently
  }
}

/**
 * Batch-remove multiple memories from both indexes in a single read-modify-write
 * cycle per index. Mirrors {@link indexMemoriesBatchAsync}: maintenance loops that
 * invalidate/archive N memories collect their entries and call this once, replacing
 * the O(N) full read-parse-stringify-write amplification of per-memory
 * deindexMemoryAsync with O(1) temporal + O(1) tag write cycles.
 *
 * Per-entry semantics are byte-identical to deindexMemoryAsync: the date
 * set for each entry's `createdAt` drops the path, the temporal event is deleted,
 * and each tag graph entry is removed. The temporal half commits first; the tag
 * half only runs if it succeeds, so a partial failure never leaves tags orphaned
 * from a temporal entry that still exists.
 */
export async function deindexMemoriesBatchAsync(
  memoryDir: string,
  entries: ReadonlyArray<Pick<TemporalIndexEntry, "path" | "createdAt" | "tags">>,
): Promise<void> {
  if (entries.length === 0) return;
  try {
    await ensureStateDir(memoryDir);

    await withMemoryDirMutex(memoryDir, async () => {
      const temporalOk = await updateTemporalIndex(memoryDir, (index) => {
        for (const entry of entries) {
          const dateKey = isoDateFromTimestamp(entry.createdAt);
          removePathFromSet(index.dates, dateKey, entry.path);
          delete index.events[entry.path];
        }
      });
      if (temporalOk) {
        await updateTagIndex(memoryDir, (index) => {
          for (const entry of entries) {
            for (const tag of entry.tags) {
              if (tag && typeof tag === "string") {
                removeTagGraphEntry(index, tag, entry.path);
              }
            }
          }
        });
      }
    });
  } catch {
    // Fail silently — indexes are advisory only
  }
}

