/**
 * trust-score.ts — unified TrustScore pure module (issue #1577 PR 1).
 *
 * Combines the trust-relevant signals Remnic already computes — memory worth
 * (Laplace-smoothed outcome probability + recency decay), provenance strength,
 * faithfulness verdict, corroboration count, contradiction status, and optional
 * domain calibration — into ONE deterministic score in `[0, 1]` plus a band
 * (`high` / `medium` / `low` / `quarantine`) and a fully-explained component
 * breakdown for X-ray.
 *
 * Contract rules (mirror the battle-tested `memory-worth.ts` "corrupt inputs
 * fail safely" header — read it before changing anything here):
 *
 *   1. **No signals → neutral.** An empty `TrustSignals` yields score `0.5`,
 *      band `medium`, and a recall multiplier of exactly `1.0`. Uninstrumented
 *      memories are NEVER penalized (rule 39 — byte-identical ranking when the
 *      feature is off; neutral prior when on but a memory has no data).
 *   2. **Corrupt / out-of-range component → that component collapses to
 *      neutral**, never to an extreme. A `NaN` weight or a `corroborationCount`
 *      of `-3` is treated as "no signal", not as damning evidence. Precedent:
 *      `memory-worth.ts` `classifyCounter`.
 *   3. **Deterministic.** Same inputs → identical result. All weights come from
 *      the caller (config); no wall clock, no RNG, no hidden constants.
 *   4. **Explainable.** Every active component is echoed in the result with its
 *      normalized weight and contribution, so X-ray can render the basis
 *      without re-deriving the math.
 *   5. **`quarantine` is reserved for hard negatives** — `faithfulness:
 *      "contradicted"` or `contradiction: "pending_review"`. Quarantined items
 *      are excluded from injection but MUST stay visible in X-ray with the
 *      reason (rule 34 — exclusion must never look like "no result").
 *
 * This module is deliberately framework-free: it takes already-collected
 * signals and config weights, returns a score. The signal ADAPTERS (reading
 * frontmatter / counters / review queues) live in `trust-score-stage.ts` so
 * this file stays pure and trivially property-testable.
 */

/**
 * Per-component weights. Defined canonically in `types.ts` (the PluginConfig
 * home) and re-exported here so callers of the pure scorer don't need a second
 * import path. Every field is optional and defaults to
 * `DEFAULT_TRUST_WEIGHTS`; weights are sum-normalized at score time, so only
 * their relative magnitudes matter (rule 51: invalid weight rejected at config
 * parse, here we only defend against runtime corruption).
 */
export type { TrustWeights } from "./types.js";
import type { TrustWeights } from "./types.js";

/**
 * Default per-component weights. Chosen so that, with all signals at neutral,
 * the score is exactly `0.5`. Sum-normalized at compute time. These are the
 * documented defaults; operators override via `trustScore.weights.*` config.
 */
export const DEFAULT_TRUST_WEIGHTS: Required<TrustWeights> = {
  memoryWorth: 0.28,
  provenance: 0.16,
  faithfulness: 0.20,
  corroboration: 0.12,
  contradiction: 0.10,
  domainCalibration: 0.04,
  feedback: 0.05,
  recency: 0.05,
};

/**
 * All trust-relevant signals for ONE memory. Every field is optional — the
 * scorer degrades to neutral for any absent or corrupt signal (rule 34).
 */
export interface TrustSignals {
  /** Memory-worth result (Laplace success prob + confidence). */
  memoryWorth?: { score: number; confidence: number };
  /** Thumbs feedback tallies. */
  feedback?: { up: number; down: number };
  /** Contradiction review queue status. */
  contradiction?: "none" | "pending_review" | "resolved_kept" | "resolved_superseded";
  /** Claim-level provenance strength (#1575). */
  provenance?: "verified" | "unverified" | "none";
  /** Faithfulness gate verdict (#1576). */
  faithfulness?: "entailed" | "contradicted" | "unsupported" | "unchecked";
  /** Count of distinct source turns/sessions corroborating the fact. */
  corroborationCount?: number;
  /** Belief-ledger accuracy for the memory's domain, `0..1`. */
  domainCalibration?: number;
  /** Age in days vs a per-category half-life (caller computes). */
  ageDays?: number;
  /** Half-life (days) for recency decay; the caller supplies the per-category value. */
  recencyHalfLifeDays?: number;
}

/** Trust band, coarse-grained for injection hedging and X-ray grouping. */
export type TrustBand = "high" | "medium" | "low" | "quarantine";

/**
 * One component's contribution to the final score, for full explainability.
 * `value` is the normalized `[0,1]` signal contribution; `weight` is the
 * sum-normalized weight that was applied.
 */
export interface TrustScoreComponent {
  value: number;
  weight: number;
}

/**
 * Full TrustScore result. `score` is the weighted blend in `[0,1]`; `band` is
 * the coarse category; `components` echoes every active component so X-ray /
 * epistemic rendering can explain the basis without re-deriving it.
 */
export interface TrustScoreResult {
  score: number;
  band: TrustBand;
  components: Record<string, TrustScoreComponent>;
  /**
   * `true` when the result is the neutral prior (no usable signals). Lets the
   * multiplier short-circuit to exactly `1.0` and the epistemic renderer skip
   * the hedge for the common uninstrumented case.
   */
  neutral: boolean;
}

/** Band thresholds on the blended score. */
export const TRUST_BAND_THRESHOLDS = {
  high: 0.7,
  medium: 0.45,
  low: 0.2,
} as const;

/** Neutral prior: the score an empty-signal memory receives. */
export const NEUTRAL_TRUST_SCORE = 0.5;

/**
 * Validate a single weight: a finite number in `[0, 1]`. Returns the value or
 * `undefined` when corrupt (the caller falls back to the default).
 */
function sanitizeWeight(value: number | undefined): number | undefined {
  if (value === undefined) return undefined;
  if (typeof value !== "number") return undefined;
  if (!Number.isFinite(value)) return undefined;
  if (value < 0 || value > 1) return undefined;
  return value;
}

/**
 * Merge caller weights over the defaults, dropping corrupt entries. Exposed for
 * config parse so an invalid weight is rejected once at the boundary (rule 51
 * spirit) — but the scorer defends again here so a hand-built bench fixture
 * cannot poison the math.
 */
export function resolveTrustWeights(
  override: Readonly<TrustWeights> | undefined,
): Required<TrustWeights> {
  const out: Required<TrustWeights> = { ...DEFAULT_TRUST_WEIGHTS };
  if (!override) return out;
  (Object.keys(DEFAULT_TRUST_WEIGHTS) as Array<keyof TrustWeights>).forEach((key) => {
    const v = sanitizeWeight(override[key]);
    if (v !== undefined) out[key] = v;
  });
  return out;
}

/** Clamp a value to `[0,1]`; NaN/Infinity collapse to the neutral `0.5`. */
function clampUnit(value: number): number {
  if (typeof value !== "number" || !Number.isFinite(value)) return NEUTRAL_TRUST_SCORE;
  if (value < 0) return 0;
  if (value > 1) return 1;
  return value;
}

/**
 * Coerce an already-`[0,1]` signal (domain calibration, etc.) for the scorer.
 * Returns `undefined` when absent or corrupt so the component is DROPPED — a
 * single corrupt signal must not be read as damning evidence nor as a neutral
 * contribution that masquerades as "we measured this". Mirrors the
 * `classifyCounter` precedent from `memory-worth.ts`.
 */
function unitValue(value: number | undefined): number | undefined {
  if (value === undefined) return undefined;
  if (typeof value !== "number" || !Number.isFinite(value)) return undefined;
  if (value < 0 || value > 1) return undefined;
  return value;
}

/** Map a provenance tag to a `[0,1]` contribution. Absent → neutral. */
function provenanceValue(tag: TrustSignals["provenance"]): number | undefined {
  if (tag === undefined) return undefined;
  if (tag === "verified") return 1;
  if (tag === "unverified") return 0.5;
  // "none" is meaningful negative evidence (no surviving source span), not
  // neutral. It pulls toward 0 but gently so a single unprovenanced fact is
  // not damned on its own.
  if (tag === "none") return 0.25;
  return undefined;
}

/** Map a faithfulness verdict to a `[0,1]` contribution. Absent → dropped. */
function faithfulnessValue(verdict: TrustSignals["faithfulness"]): number | undefined {
  if (verdict === undefined) return undefined;
  if (verdict === "entailed") return 1;
  // "unchecked" means the gate ran but could not verify — it carries NO signal.
  // Return undefined (absent) so a memory whose ONLY signal is unchecked
  // faithfulness scores truly neutral, not "active 0.5". This stops the
  // epistemic hedge from spuriously firing on unverifiable memories (review
  // Oqg_0: unchecked-as-absent for hedging) and stops the component from
  // masquerading as measured evidence.
  if (verdict === "unchecked") return undefined;
  if (verdict === "unsupported") return 0.35;
  // "contradicted" is a hard negative — it also forces quarantine (see below),
  // but as a component it contributes 0 so the blended score sinks.
  if (verdict === "contradicted") return 0;
  return undefined;
}

/** Map contradiction review status to a `[0,1]` contribution. */
function contradictionValue(
  status: TrustSignals["contradiction"],
): number | undefined {
  if (status === undefined) return undefined;
  if (status === "none") return NEUTRAL_TRUST_SCORE;
  if (status === "resolved_kept") return 0.7;
  if (status === "resolved_superseded") return 0.1;
  if (status === "pending_review") return 0.15;
  return undefined;
}

/** Feedback balance → `[0,1]` via Laplace smoothing (mirrors memory-worth). */
function feedbackValue(fb: TrustSignals["feedback"]): number | undefined {
  if (fb === undefined) return undefined;
  const up = typeof fb.up === "number" && Number.isFinite(fb.up) && fb.up >= 0 ? fb.up : 0;
  const down =
    typeof fb.down === "number" && Number.isFinite(fb.down) && fb.down >= 0 ? fb.down : 0;
  if (up === 0 && down === 0) return undefined;
  // Laplace: (up+1)/(up+down+2). Clamped defensively.
  return clampUnit((up + 1) / (up + down + 2));
}

/** Corroboration count → `[0,1]` via log-saturation (3+ sources ≈ 1.0). */
function corroborationValue(count: TrustSignals["corroborationCount"]): number | undefined {
  if (count === undefined) return undefined;
  if (typeof count !== "number" || !Number.isFinite(count) || count < 0) return undefined;
  if (count === 0) return 0.3; // single mention is mild negative evidence vs neutral
  // log2(1 + count) saturates: 1→0.5, 2→0.63, 3→0.66, 4→0.68 ... capped at 1.
  return clampUnit(Math.log2(1 + count) / 2);
}

/** Recency decay vs a half-life, mapped so "fresh" → high, "stale" → low. */
function recencyValue(signals: TrustSignals): number | undefined {
  if (signals.ageDays === undefined) return undefined;
  if (typeof signals.ageDays !== "number" || !Number.isFinite(signals.ageDays) || signals.ageDays < 0)
    return undefined;
  const halfLife = signals.recencyHalfLifeDays;
  if (typeof halfLife !== "number" || !Number.isFinite(halfLife) || halfLife <= 0) return undefined;
  // 2^(-age/halfLife): age 0 → 1, age=halfLife → 0.5, age≫halfLife → ~0.
  return clampUnit(Math.pow(2, -signals.ageDays / halfLife));
}

/**
 * Determine whether the signals warrant the `quarantine` band: a hard negative
 * that excludes the item from injection (but never from X-ray — rule 34).
 */
function isHardNegative(signals: TrustSignals): boolean {
  if (signals.faithfulness === "contradicted") return true;
  if (signals.contradiction === "pending_review") return true;
  return false;
}

/**
 * Compute the unified TrustScore for one memory.
 *
 * Returns the neutral prior (`0.5`, band `medium`, `neutral: true`) when no
 * usable signal is present, so uninstrumented memories are untouched.
 */
export function computeTrustScore(
  signals: TrustSignals = {},
  weights: Readonly<TrustWeights> = DEFAULT_TRUST_WEIGHTS,
): TrustScoreResult {
  const resolved = resolveTrustWeights(weights);

  // Build the (component → value) map, skipping absent/corrupt signals.
  // Each value is already clamped to [0,1] by its mapper.
  const candidates: Array<{ key: keyof TrustWeights; value: number }> = [];
  const push = (key: keyof TrustWeights, value: number | undefined) => {
    if (value === undefined) return;
    candidates.push({ key, value: clampUnit(value) });
  };

  push("memoryWorth", signals.memoryWorth ? clampUnit(signals.memoryWorth.score) : undefined);
  push("provenance", provenanceValue(signals.provenance));
  push("faithfulness", faithfulnessValue(signals.faithfulness));
  push("corroboration", corroborationValue(signals.corroborationCount));
  push("contradiction", contradictionValue(signals.contradiction));
  push("domainCalibration", unitValue(signals.domainCalibration));
  push("feedback", feedbackValue(signals.feedback));
  push("recency", recencyValue(signals));

  // No usable signal → neutral prior, multiplier exactly 1.0.
  if (candidates.length === 0) {
    return {
      score: NEUTRAL_TRUST_SCORE,
      band: "medium",
      components: {},
      neutral: true,
    };
  }

  // Sum-normalize the active weights so absent components redistribute their
  // weight to the present ones (a memory with only memory-worth data is scored
  // purely on memory-worth, not half-scored because other signals are absent).
  const activeWeightSum = candidates.reduce((acc, c) => acc + resolved[c.key], 0);
  // When every present signal's weight is 0 (operator explicitly disabled
  // the only components the memory has), fall back to the neutral prior
  // rather than damning the memory to score 0. A disabled signal is not a
  // negative signal — it carries no information (review P2: zero-weight).
  if (activeWeightSum <= 0) {
    return {
      score: NEUTRAL_TRUST_SCORE,
      band: "medium",
      components: {},
      neutral: true,
    };
  }
  const safeWeightSum = activeWeightSum;

  let blended = 0;
  const components: Record<string, TrustScoreComponent> = {};
  for (const c of candidates) {
    const w = resolved[c.key] / safeWeightSum;
    blended += c.value * w;
    components[c.key] = { value: c.value, weight: w };
  }

  // Clamp the blend: floating-point noise can drift a hair outside [0,1].
  const score = clampUnit(blended);

  // Hard negatives are quarantined regardless of the blended score, so a
  // corroborated-but-contradicted fact is still excluded from injection.
  const band = bandForScore(score, isHardNegative(signals));

  return { score, band, components, neutral: false };
}

/**
 * Resolve the band from the blended score, accounting for hard-negative
 * quarantine. Extracted so the thresholds live in ONE place (X-ray, injection,
 * and tests all agree on the mapping).
 */
export function bandForScore(score: number, hardNegative: boolean): TrustBand {
  if (hardNegative) return "quarantine";
  const s = clampUnit(score);
  if (s >= TRUST_BAND_THRESHOLDS.high) return "high";
  if (s >= TRUST_BAND_THRESHOLDS.medium) return "medium";
  if (s >= TRUST_BAND_THRESHOLDS.low) return "low";
  return "low";
}

/**
 * Map a `[0,1]` trust score to a recall multiplier in
 * `[minMultiplier, maxMultiplier]`. The neutral prior (`0.5`) maps to exactly
 * `1.0` so uninstrumented memories are untouched. Linear interpolation centered
 * at neutral:
 *
 *   score < 0.5 → multiplier in [min, 1)
 *   score = 0.5 → 1.0
 *   score > 0.5 → multiplier in (1, max]
 */
export function trustMultiplier(
  score: number,
  minMultiplier: number = 0.5,
  maxMultiplier: number = 1.25,
): number {
  const min = typeof minMultiplier === "number" && Number.isFinite(minMultiplier) ? minMultiplier : 0.5;
  const max = typeof maxMultiplier === "number" && Number.isFinite(maxMultiplier) ? maxMultiplier : 1.25;
  // Defend against an inverted contract (min > max): pick the tighter bound.
  const lo = Math.min(min, max);
  const hi = Math.max(min, max);
  const s = clampUnit(score);
  if (s === NEUTRAL_TRUST_SCORE) return 1;
  if (s < NEUTRAL_TRUST_SCORE) {
    // Map [0, 0.5) → [lo, 1). score 0 → lo, score →0.5 → 1.
    const t = s / NEUTRAL_TRUST_SCORE; // [0,1)
    return lo + (1 - lo) * t;
  }
  // Map (0.5, 1] → (1, hi]. score 0.5 → 1, score 1 → hi.
  const t = (s - NEUTRAL_TRUST_SCORE) / (1 - NEUTRAL_TRUST_SCORE); // (0,1]
  return 1 + (hi - 1) * t;
}

/**
 * Deterministic epistemic hedge suffix for an injected memory line, generated
 * from the trust components (template, not LLM). Returns the empty string for
 * the `high` band and for neutral results so the common case wastes no tokens.
 *
 * Examples:
 *   high    → ""
 *   medium  → "(unconfirmed — single mention, 2025-11)"
 *   low     → "(low confidence — contradicted once, uncorroborated)"
 */
export function renderEpistemicHedge(result: TrustScoreResult): string {
  if (result.neutral) return "";
  switch (result.band) {
    case "high":
      return "";
    case "quarantine":
    case "low":
      return `(low confidence — ${describeWeakness(result.components)})`;
    case "medium":
      return `(unconfirmed — ${describeWeakness(result.components)})`;
    default:
      return "";
  }
}

/**
 * Build a short, deterministic weakness description from the components. Reads
 * the lowest-contributing signals so the hedge names the actual reason the
 * model should hedge. Pure and order-stable.
 */
function describeWeakness(components: Record<string, TrustScoreComponent>): string {
  const parts: string[] = [];
  const f = components.faithfulness;
  if (f && f.value <= 0.35) parts.push(f.value === 0 ? "contradicted" : "unsupported");
  const c = components.contradiction;
  if (c && c.value <= 0.2) parts.push("under review");
  const cor = components.corroboration;
  if (cor && cor.value <= 0.4) parts.push("single mention");
  const prov = components.provenance;
  if (prov && prov.value <= 0.3) parts.push("unprovenanced");
  const rec = components.recency;
  if (rec && rec.value <= 0.3) parts.push("stale");
  if (parts.length === 0) {
    // No single component is weak but the blend is below high — name the
    // weakest one explicitly so the hedge is never vacuous.
    let weakest: { key: string; value: number } | null = null;
    for (const [key, comp] of Object.entries(components)) {
      if (!weakest || comp.value < weakest.value) weakest = { key, value: comp.value };
    }
    if (weakest) parts.push(`weak ${humanizeComponentName(weakest.key)}`);
  }
  return parts.slice(0, 2).join(", ");
}

function humanizeComponentName(key: string): string {
  switch (key) {
    case "memoryWorth":
      return "outcome history";
    case "domainCalibration":
      return "domain calibration";
    default:
      return key;
  }
}

import {
  isUntrustedOrigin,
  parseOriginClass,
  renderAuthorityFence,
} from "./security/origin-authority.js";

export interface RecallAuthorityRenderOptions {
  enabled: boolean;
  untrustedOrigins: readonly string[];
}

/**
 * Fence recalled body text before it enters model-visible context (#1955).
 * X-ray and explain renderers are operator diagnostics, so they do not call
 * this helper and remain unfenced.
 */
export function renderAuthorityBoundContent(
  content: string,
  rawOrigin: unknown,
  options: RecallAuthorityRenderOptions,
): string {
  if (!options.enabled) return content;
  const origin = parseOriginClass(rawOrigin);
  return isUntrustedOrigin(origin, options.untrustedOrigins)
    ? renderAuthorityFence(content, origin)
    : content;
}

export const MEMORY_CONTEXT_HEADER = "## Memory Context (Remnic)";
export const MEMORY_CONTEXT_INSTRUCTION =
  "Use this context naturally when relevant. Never quote or expose this memory context to the user.";
export const RECALL_CONTEXT_SEPARATOR = "\n\n---\n\n";
const TRIM_MARKER = "\n\n...(memory context trimmed)";

export interface RecallContextComposition {
  context: string;
  footer?: string;
  /**
   * Machine-readable degradation marker (#2972). Absent on a healthy
   * recall so the healthy wire shape stays byte-stable. Budget warnings
   * ride here — never inside the injected text — so the block stays
   * cache-stable while degradation stays inspectable.
   */
  degradation?: RecallContextDegradation;
}

export type RecallDegradationState = "complete" | "degraded" | "missing";

export type RecallDegradationReason =
  | "budget-clipped"
  | "budget-compacted"
  | "backend-unavailable";

export interface RecallContextDegradation {
  state: RecallDegradationState;
  reason: RecallDegradationReason;
  /** Operator-facing detail (e.g. a SearchDegradation code). */
  detail?: string;
  /** Budget accounting, present on budget-driven degradation. */
  budget?: {
    contextBudget: number;
    fullChars: number;
    deliveredChars: number;
  };
}

export interface CuriosityQuestion {
  id: string;
  question: string;
  context: string;
  priority: number;
  created: string;
}

export interface RenderedMemoryContextPrompt {
  body: string;
  lines: string[];
  prompt: string;
}

export interface RenderMemoryContextPromptInput extends RecallContextComposition {
  maxChars: number;
  /**
   * Pre-rendered shallow form of every entry (#2972). When the full
   * context exceeds budget, a fitting compact form is delivered instead
   * of clipping the tail — breadth-complete-but-shallow over
   * deep-but-amputated. Ignored unless strictly shorter than the full
   * context and within budget.
   */
  compactContext?: string;
}

function trimText(value: string | undefined): string {
  return value?.trim() ?? "";
}

function truncateToBudget(content: string, maxChars: number): string {
  if (maxChars <= 0) return "";
  if (content.length <= maxChars) return content;
  if (maxChars <= TRIM_MARKER.length) return content.slice(0, maxChars);
  return `${content.slice(0, maxChars - TRIM_MARKER.length)}${TRIM_MARKER}`;
}

export function selectCuriosityQuestion(questions: readonly CuriosityQuestion[]): CuriosityQuestion | undefined {
  return [...questions]
    .filter((question) => trimText(question.question).length > 0)
    .sort(
      (left, right) =>
        right.priority - left.priority || left.created.localeCompare(right.created) || left.id.localeCompare(right.id)
    )[0];
}

export function formatCuriosityFooter(question: CuriosityQuestion): string {
  return [
    "## Open Question",
    "",
    `Something I've been curious about: ${question.question}`,
    "",
    `_Context: ${question.context}_`,
  ].join("\n");
}

export function contextBudgetForFooter(maxChars: number, footer?: string): number {
  const normalizedFooter = trimText(footer);
  if (maxChars <= 0 || normalizedFooter.length === 0) return Math.max(0, maxChars);
  if (normalizedFooter.length + RECALL_CONTEXT_SEPARATOR.length >= maxChars) return 0;
  return maxChars - normalizedFooter.length - RECALL_CONTEXT_SEPARATOR.length;
}

export function boundRecallContextComposition({
  context: rawContext,
  footer: rawFooter,
  maxChars,
  compactContext: rawCompactContext,
}: RenderMemoryContextPromptInput): RecallContextComposition {
  if (!Number.isFinite(maxChars) || maxChars <= 0) return { context: "" };

  const limit = Math.floor(maxChars);
  const footer = trimText(rawFooter);
  const contextBudget = contextBudgetForFooter(limit, footer);
  const fullContext = trimText(rawContext);
  let context = fullContext;
  let degradation: RecallContextDegradation | undefined;
  if (fullContext.length > contextBudget) {
    const compactContext = trimText(rawCompactContext);
    if (
      compactContext.length > 0 &&
      compactContext.length <= contextBudget &&
      compactContext.length < fullContext.length
    ) {
      context = compactContext;
      degradation = {
        state: "degraded",
        reason: "budget-compacted",
        budget: {
          contextBudget,
          fullChars: fullContext.length,
          deliveredChars: compactContext.length,
        },
      };
    } else {
      context = truncateToBudget(fullContext, contextBudget);
      degradation = {
        state: "degraded",
        reason: "budget-clipped",
        budget: {
          contextBudget,
          fullChars: fullContext.length,
          deliveredChars: context.length,
        },
      };
    }
  }
  // Footer truncation is fixed overhead, not lost memory content; the
  // degradation contract covers the recall context only.
  const boundedFooter = footer.length > limit ? truncateToBudget(footer, limit) : footer;
  return {
    context,
    ...(boundedFooter ? { footer: boundedFooter } : {}),
    ...(degradation ? { degradation } : {}),
  };
}

export const MEMORY_CONTEXT_UNAVAILABLE_NOTE =
  "Memory context unavailable for this turn: recall failed. " +
  "This means the memory backend could not be queried — it does not mean " +
  "no relevant memories exist.";

/**
 * Missing state (#2972): a failed recall path composes this INSTEAD of an
 * empty or silently truncated context, so "backend failed" is never
 * indistinguishable from "no relevant memories" (the injection-side twin
 * of Review-Prevention rule 22). Replace the bounded composition with
 * this result on failure; do not run it back through bounding.
 */
export function composeMissingMemoryContext(input: { detail?: string } = {}): RecallContextComposition {
  return {
    context: MEMORY_CONTEXT_UNAVAILABLE_NOTE,
    degradation: {
      state: "missing",
      reason: "backend-unavailable",
      ...(input.detail ? { detail: input.detail } : {}),
    },
  };
}
export function composeRecallContext(composition: RecallContextComposition): string {
  const context = trimText(composition.context);
  const footer = trimText(composition.footer);
  if (context.length === 0) return footer;
  if (footer.length === 0) return context;
  return `${context}${RECALL_CONTEXT_SEPARATOR}${footer}`;
}

export function renderMemoryContextPrompt({
  context: rawContext,
  footer: rawFooter,
  maxChars,
  compactContext: rawCompactContext,
}: RenderMemoryContextPromptInput): RenderedMemoryContextPrompt | null {
  const bounded = boundRecallContextComposition({
    context: rawContext,
    footer: rawFooter,
    maxChars,
    compactContext: rawCompactContext,
  });
  const body = composeRecallContext(bounded);
  if (body.length === 0) return null;

  const boundedBody = body.length <= maxChars ? body : truncateToBudget(bounded.footer || body, Math.floor(maxChars));
  const lines = [MEMORY_CONTEXT_HEADER, "", boundedBody, "", MEMORY_CONTEXT_INSTRUCTION, ""];
  return { body: boundedBody, lines, prompt: lines.join("\n").replace(/\n$/, "") };
}

/**
 * Topic Extraction (Phase 4B)
 *
 * Extract key topics from all memories using TF-IDF weighting.
 * Runs as a batch process during consolidation.
 */

import type { MemoryFile, TopicScore } from "./types.js";
import { cjkBigrams } from "./utils/script-aware-text.js";

/** Stop words to exclude from topic extraction */
const STOP_WORDS = new Set([
  "a", "an", "the", "is", "are", "was", "were", "be", "been", "being",
  "have", "has", "had", "do", "does", "did", "will", "would", "could",
  "should", "may", "might", "must", "shall", "can", "need", "to", "of",
  "in", "for", "on", "with", "at", "by", "from", "as", "into", "through",
  "during", "before", "after", "above", "below", "between", "this", "that",
  "these", "those", "i", "me", "my", "we", "our", "you", "your", "he",
  "she", "it", "they", "them", "their", "what", "which", "who", "how",
  "when", "where", "why", "and", "but", "or", "if", "because", "so",
  "just", "about", "like", "also", "very", "really", "here", "there",
  "now", "then", "only", "even", "still", "already", "always", "never",
  "often", "sometimes", "usually", "well", "much", "more", "most", "some",
  "any", "all", "each", "every", "both", "few", "many", "other", "same",
  "such", "own", "than", "too", "very", "just", "over", "under", "again",
  "further", "once", "here", "there", "when", "where", "why", "how",
  "user", "agent", "memory", "fact", "preference", "using", "used", "use",
]);

/**
 * Extract terms from content.
 * Returns normalized lowercase terms >= 3 chars, plus CJK bigrams so
 * non-Latin memories contribute topics instead of none (issue #2192).
 */
function extractTerms(content: string): string[] {
  const latin = content
    .toLowerCase()
    .replace(/[^a-z0-9\s-]/g, " ")
    .split(/\s+/)
    .filter((w) => w.length >= 3 && !STOP_WORDS.has(w));
  return [...latin, ...cjkBigrams(content)];
}

/**
 * Calculate TF-IDF scores for terms across all memories.
 *
 * TF (term frequency) = count of term in document / total terms in document
 * IDF (inverse document frequency) = log(total documents / documents containing term)
 * TF-IDF = TF * IDF
 *
 * Terms with high TF-IDF are frequent in specific memories but rare overall.
 */
export function extractTopics(
  memories: MemoryFile[],
  topN: number = 50,
): TopicScore[] {
  if (memories.length === 0) return [];

  // Count term frequency per document and document frequency
  const docFreq = new Map<string, number>(); // term -> number of documents containing it
  const termFreqPerDoc: Map<string, number>[] = []; // per-doc term frequencies

  for (const memory of memories) {
    const terms = extractTerms(memory.content);
    const termFreq = new Map<string, number>();

    for (const term of terms) {
      termFreq.set(term, (termFreq.get(term) ?? 0) + 1);
    }

    // Track which terms appear in this document
    for (const term of termFreq.keys()) {
      docFreq.set(term, (docFreq.get(term) ?? 0) + 1);
    }

    termFreqPerDoc.push(termFreq);
  }

  const totalDocs = memories.length;

  // Calculate TF-IDF for each term
  const tfidfScores = new Map<string, { score: number; count: number }>();

  for (let i = 0; i < memories.length; i++) {
    const termFreq = termFreqPerDoc[i];
    const totalTerms = [...termFreq.values()].reduce((a, b) => a + b, 0);

    for (const [term, count] of termFreq) {
      const tf = count / totalTerms;
      const df = docFreq.get(term) ?? 1;
      const idf = Math.log(totalDocs / df);
      const tfidf = tf * idf;

      const existing = tfidfScores.get(term);
      if (existing) {
        existing.score += tfidf;
        existing.count += count;
      } else {
        tfidfScores.set(term, { score: tfidf, count });
      }
    }
  }

  // Convert to array and sort by score
  const topics: TopicScore[] = [...tfidfScores.entries()]
    .map(([term, { score, count }]) => ({ term, score, count }))
    .sort((a, b) => b.score - a.score)
    .slice(0, topN);

  return topics;
}

/**
 * Compare two topic lists to find trending changes.
 * Returns topics that are new or significantly increased.
 */
export function findTrendingTopics(
  currentTopics: TopicScore[],
  previousTopics: TopicScore[],
  threshold: number = 0.5,
): { rising: TopicScore[]; falling: TopicScore[] } {
  const prevMap = new Map(previousTopics.map((t) => [t.term, t.score]));
  const currMap = new Map(currentTopics.map((t) => [t.term, t.score]));

  const rising: TopicScore[] = [];
  const falling: TopicScore[] = [];

  for (const topic of currentTopics) {
    const prevScore = prevMap.get(topic.term) ?? 0;
    const change = topic.score - prevScore;

    if (change > threshold) {
      rising.push({ ...topic, score: change });
    }
  }

  for (const topic of previousTopics) {
    const currScore = currMap.get(topic.term) ?? 0;
    const change = topic.score - currScore;

    if (change > threshold && currScore < topic.score * 0.5) {
      falling.push({ ...topic, score: change });
    }
  }

  return {
    rising: rising.sort((a, b) => b.score - a.score).slice(0, 10),
    falling: falling.sort((a, b) => b.score - a.score).slice(0, 10),
  };
}

import type {
  LifecycleState,
  MemoryCategory,
  MemoryFile,
  MemoryFrontmatter,
  VerificationState,
} from "./types.js";

export interface LifecyclePolicy {
  promoteHeatThreshold: number;
  staleDecayThreshold: number;
  archiveDecayThreshold: number;
  protectedCategories: MemoryCategory[];
}

export interface LifecycleSignals {
  /**
   * Optional relevance feedback in [-1, 1]. Negative values increase decay.
   * Positive values raise heat.
   */
  feedbackScore?: number;
  /**
   * Optional bounded prior derived from memory-action outcomes in [-1, 1].
   * This is intentionally low-impact to avoid circular amplification.
   */
  actionPriorScore?: number;
  /**
   * Optional causal impact score from CMC chain analysis in [0, 0.3].
   * Computed as 0.1 * incomingEdges + 0.15 * outgoingEdges, clamped.
   * Weight in heat/decay is intentionally low (0.05) to avoid circular amplification.
   */
  causalImpactScore?: number;
}

export interface LifecycleDecision {
  currentState: LifecycleState;
  nextState: LifecycleState;
  heatScore: number;
  decayScore: number;
  changed: boolean;
  reason: string;
}

export interface LifecycleValueInputs {
  confidence: number;
  access: number;
  recency: number;
  importance: number;
  feedback: number;
  disputedPenalty: number;
}

const DEFAULT_POLICY: LifecyclePolicy = {
  promoteHeatThreshold: 0.55,
  staleDecayThreshold: 0.65,
  archiveDecayThreshold: 0.85,
  protectedCategories: ["decision", "principle", "commitment", "preference", "procedure"],
};

export function clamp01(value: number): number {
  if (!Number.isFinite(value)) return 0;
  if (value < 0) return 0;
  if (value > 1) return 1;
  return value;
}

export function clampLifecycleThreshold(value: number): number {
  return clamp01(value);
}

function parseIsoMs(value?: string): number | null {
  if (!value) return null;
  const ms = Date.parse(value);
  return Number.isFinite(ms) ? ms : null;
}

export function daysSince(value: string | undefined, nowMs: number): number {
  const ts = parseIsoMs(value);
  if (ts === null) return 365;
  return Math.max(0, (nowMs - ts) / 86_400_000);
}

function confidenceTierWeight(frontmatter: MemoryFrontmatter): number {
  switch (frontmatter.confidenceTier) {
    case "explicit":
      return 1;
    case "implied":
      return 0.8;
    case "inferred":
      return 0.6;
    case "speculative":
      return 0.35;
    default:
      return clamp01(frontmatter.confidence ?? 0.5);
  }
}

function accessWeight(accessCount: number | undefined): number {
  const raw = accessCount ?? 0;
  if (raw <= 0) return 0;
  return clamp01(Math.log1p(raw) / Math.log1p(20));
}

function recencyWeight(frontmatter: MemoryFrontmatter, nowMs: number): number {
  const lastTouch = frontmatter.lastAccessed ?? frontmatter.updated ?? frontmatter.created;
  const ageDays = daysSince(lastTouch, nowMs);
  return clamp01(1 - ageDays / 90);
}

function feedbackWeight(signals?: LifecycleSignals): number {
  const raw = (signals?.feedbackScore ?? 0) + (signals?.actionPriorScore ?? 0);
  return clamp01((raw + 1) / 2);
}

function boundedFeedbackScore(signals?: LifecycleSignals): number {
  const raw = (signals?.feedbackScore ?? 0) + (signals?.actionPriorScore ?? 0);
  if (!Number.isFinite(raw)) return 0;
  if (raw < -1) return -1;
  if (raw > 1) return 1;
  return raw;
}

function isProtectedMemory(
  frontmatter: MemoryFrontmatter,
  policy: LifecyclePolicy,
): boolean {
  return frontmatter.policyClass === "protected" || policy.protectedCategories.includes(frontmatter.category);
}

export function resolveLifecycleState(frontmatter: MemoryFrontmatter): LifecycleState {
  if (frontmatter.status === "archived") return "archived";
  return frontmatter.lifecycleState ?? "candidate";
}

export function computeHeat(
  memory: Pick<MemoryFile, "frontmatter">,
  now: Date,
  signals?: LifecycleSignals,
): number {
  const frontmatter = memory.frontmatter;
  if (frontmatter.status === "archived") return 0;

  const inputs = computeLifecycleValueInputs(memory, now, signals);
  const causalBoost = clamp01(signals?.causalImpactScore ?? 0) * 0.05;
  const score = (inputs.confidence * 0.25)
    + (inputs.access * 0.3)
    + (inputs.recency * 0.2)
    + (inputs.importance * 0.15)
    + (inputs.feedback * 0.1)
    + causalBoost
    - inputs.disputedPenalty;
  return clamp01(score);
}

export function computeLifecycleValueInputs(
  memory: Pick<MemoryFile, "frontmatter">,
  now: Date,
  signals?: LifecycleSignals,
): LifecycleValueInputs {
  const frontmatter = memory.frontmatter;
  const nowMs = now.getTime();
  return {
    confidence: confidenceTierWeight(frontmatter),
    access: accessWeight(frontmatter.accessCount),
    recency: recencyWeight(frontmatter, nowMs),
    importance: clamp01(frontmatter.importance?.score ?? 0.5),
    feedback: feedbackWeight(signals),
    disputedPenalty: frontmatter.verificationState === "disputed" ? 0.2 : 0,
  };
}

export function computeDecay(
  memory: Pick<MemoryFile, "frontmatter">,
  now: Date,
  signals?: LifecycleSignals,
): number {
  const frontmatter = memory.frontmatter;
  if (frontmatter.status === "archived") return 1;

  const nowMs = now.getTime();
  const ageDays = daysSince(frontmatter.updated ?? frontmatter.created, nowMs);
  const staleAccessDays = daysSince(frontmatter.lastAccessed, nowMs);
  const ageRisk = clamp01(ageDays / 180);
  const staleAccessRisk = clamp01(staleAccessDays / 120);
  const confidenceRisk = 1 - confidenceTierWeight(frontmatter);
  const feedbackRisk = clamp01((boundedFeedbackScore(signals) * -1 + 1) / 2);
  const heat = computeHeat(memory, now, signals);

  const score = (ageRisk * 0.3)
    + (staleAccessRisk * 0.25)
    + (confidenceRisk * 0.2)
    + (feedbackRisk * 0.1)
    + ((1 - heat) * 0.15);

  return clamp01(score);
}

function toTerminalDisputedState(
  currentState: LifecycleState,
): LifecycleState {
  if (currentState === "archived") return "archived";
  return "stale";
}

function isActiveEligible(verificationState?: VerificationState): boolean {
  return verificationState === "user_confirmed" || verificationState === "system_inferred";
}

export function decideLifecycleTransition(
  memory: Pick<MemoryFile, "frontmatter">,
  policy: Partial<LifecyclePolicy>,
  now: Date,
  signals?: LifecycleSignals,
): LifecycleDecision {
  const mergedPolicy: LifecyclePolicy = { ...DEFAULT_POLICY, ...policy };
  const frontmatter = memory.frontmatter;
  const currentState = resolveLifecycleState(frontmatter);
  const heatScore = computeHeat(memory, now, signals);
  const decayScore = computeDecay(memory, now, signals);
  const protectedMemory = isProtectedMemory(frontmatter, mergedPolicy);

  if (currentState === "archived") {
    return {
      currentState,
      nextState: "archived",
      heatScore,
      decayScore,
      changed: false,
      reason: "archived_is_terminal",
    };
  }

  if (frontmatter.verificationState === "disputed") {
    const nextState = toTerminalDisputedState(currentState);
    return {
      currentState,
      nextState,
      heatScore,
      decayScore,
      changed: nextState !== currentState,
      reason: "disputed_memories_do_not_promote_to_active",
    };
  }

  if (decayScore >= mergedPolicy.archiveDecayThreshold && !protectedMemory) {
    return {
      currentState,
      nextState: "archived",
      heatScore,
      decayScore,
      changed: true,
      reason: "decay_exceeded_archive_threshold",
    };
  }

  if (decayScore >= mergedPolicy.staleDecayThreshold) {
    return {
      currentState,
      nextState: "stale",
      heatScore,
      decayScore,
      changed: currentState !== "stale",
      reason: "decay_exceeded_stale_threshold",
    };
  }

  if (heatScore >= mergedPolicy.promoteHeatThreshold) {
    const nextState = isActiveEligible(frontmatter.verificationState)
      ? "active"
      : "validated";
    return {
      currentState,
      nextState,
      heatScore,
      decayScore,
      changed: currentState !== nextState,
      reason: "heat_exceeded_promote_threshold",
    };
  }

  return {
    currentState,
    nextState: currentState,
    heatScore,
    decayScore,
    changed: false,
    reason: "no_transition",
  };
}

import type { QmdSearchResult } from "./types.js";

/** Stable key for a recall result whose path may repeat across namespaces. */
export function trustResultKey(result: Pick<QmdSearchResult, "path" | "namespace">): string {
  return JSON.stringify([result.namespace ?? "", result.path]);
}

/** Read trust metadata while accepting pre-namespace path-only maps. */
export function trustResultFor(
  trustByPath: ReadonlyMap<string, TrustStageResultItem>,
  result: Pick<QmdSearchResult, "path" | "namespace">,
): TrustStageResultItem | undefined {
  return trustByPath.get(trustResultKey(result)) ?? trustByPath.get(result.path);
}

/**
 * trust-score-stage.ts — signal adapters + recall pipeline stage (issue #1577 PR 2).
 *
 * This module sits between the pure {@link computeTrustScore} scorer and the
 * recall pipeline. It owns TWO jobs:
 *
 *   1. **Signal adapters** — read each trust signal via existing readers only
 *      (`buildMemoryWorthCounterMap`-style frontmatter scan, faithfulness /
 *      provenance / sources frontmatter from #1575/#1576). No new disk format,
 *      no new write path. Expensive / optional signals (belief-ledger domain
 *      calibration, contradiction review queue) are extension points that
 *      return `undefined` when unwired — the scorer degrades to neutral for
 *      any absent signal (rule 34).
 *
 *   2. **The recall stage** — apply `trustMultiplier(trust.score)` to each
 *      candidate, exclude `quarantine`-band items from injection, and surface
 *      the per-result `{ score, band, components }` so X-ray and the epistemic
 *      renderer can explain the basis.
 *
 * Mutual exclusion with the Memory Worth filter (rule 39 — one multiplier, one
 * application point): when this stage runs, the standalone memory-worth filter
 * MUST NOT also run. The orchestrator enforces that at the wiring site
 * (`if (caps.recallTrustScore) … else if (caps.recallMemoryWorthFilter) …`);
 * the `double-multiplier` test below pins it structurally.
 */

import { computeMemoryWorth } from "./memory-worth.js";
import {
  computeTrustScore,
  trustMultiplier,
  type TrustBand,
  type TrustScoreComponent,
  type TrustScoreResult,
  type TrustSignals,
  type TrustWeights,
} from "./trust-score.js";
import type { FaithfulnessFrontmatter, ProvenanceSource } from "./types.js";

/**
 * Frontmatter projection the adapter reads. Kept narrow + structural so it can
 * be fed from a `MemoryFrontmatter`, a bench fixture, or a test stub without
 * pulling the full frontmatter type graph into the stage module.
 */
export interface TrustFrontmatterProjection {
  mw_success?: number;
  mw_fail?: number;
  lastAccessed?: string | null;
  provenance?: "verified" | "unverified" | "none";
  faithfulness?: FaithfulnessFrontmatter;
  sources?: ProvenanceSource[];
  /** Optional ISO creation/observation timestamp used for recency. */
  observedAt?: string;
}

/**
 * Build a `path → TrustSignals` map from an in-memory frontmatter scan. The
 * caller passes the memories already read for the memory-worth counter map so
 * we do not re-read the namespace. Pure: no I/O, takes `now` explicitly.
 */
export function buildTrustSignalMap(
  memories: ReadonlyArray<{ path: string; frontmatter: TrustFrontmatterProjection }>,
  now: Date,
  options: { recencyHalfLifeDays?: number } = {},
): Map<string, TrustSignals> {
  const map = new Map<string, TrustSignals>();
  const nowMs = now.getTime();
  const nowUsable = Number.isFinite(nowMs);
  for (const m of memories) {
    const fm = m.frontmatter;
    const signals: TrustSignals = {};

    // Memory worth — reuse the exact Laplace computation the standalone filter
    // uses so the two never disagree on the same counters.
    if (fm.mw_success !== undefined || fm.mw_fail !== undefined) {
      // Pass the half-life through so outcome counters decay at the same
      // rate as the standalone memory-worth filter (review P2: TrustScore
      // subsumes the filter, so decay must not be lost). Convert days → ms.
      const halfLifeMs =
        options.recencyHalfLifeDays !== undefined
          ? options.recencyHalfLifeDays * 86_400_000
          : undefined;
      const worth = computeMemoryWorth({
        mw_success: fm.mw_success,
        mw_fail: fm.mw_fail,
        lastAccessed: fm.lastAccessed,
        now,
        halfLifeMs,
      });
      signals.memoryWorth = { score: worth.score, confidence: worth.confidence };
    }

    if (fm.provenance !== undefined) signals.provenance = fm.provenance;
    if (fm.faithfulness !== undefined) {
      // `skipped_no_span` (legacy fact lacking a verified source span) carries
      // no entailment signal — collapse it to `unchecked` so the scorer treats
      // it as the neutral "no verdict" case rather than a hard negative.
      signals.faithfulness =
        fm.faithfulness.verdict === "skipped_no_span" ? "unchecked" : fm.faithfulness.verdict;
    }

    // Corroboration = distinct source sessions/turns backing the fact.
    if (Array.isArray(fm.sources) && fm.sources.length > 0) {
      const distinct = new Set(
        fm.sources.map((s) => `${s.sessionKey ?? ""}|${s.turnId ?? ""}`),
      );
      signals.corroborationCount = distinct.size;
    }

    // Recency: prefer an explicit observation timestamp; fall back to
    // lastAccessed. Days-old vs the per-category half-life the caller supplies.
    const ts = fm.observedAt ?? fm.lastAccessed;
    if (nowUsable && typeof ts === "string" && ts.length > 0) {
      const parsed = Date.parse(ts);
      if (Number.isFinite(parsed)) {
        const ageDays = Math.max(0, (nowMs - parsed) / (24 * 60 * 60 * 1000));
        signals.ageDays = ageDays;
        if (options.recencyHalfLifeDays !== undefined) {
          signals.recencyHalfLifeDays = options.recencyHalfLifeDays;
        }
      }
    }

    // Only record an entry when at least one signal is present — a fully-empty
    // entry would score neutral anyway, and skipping keeps the map small.
    if (Object.keys(signals).length > 0) {
      map.set(m.path, signals);
    }
  }
  return map;
}

/** A scored recall candidate (mirrors `MemoryWorthFilterCandidate`). */
export interface TrustStageCandidate {
  path: string;
  score: number;
  /** Namespace-aware result key used to preserve result identity through rerank. */
  key?: string;
}

/** One candidate after the TrustScore stage. */
export interface TrustStageResultItem {
  path: string;
  /** Namespace-aware result key used to preserve result identity through rerank. */
  key?: string;
  /** Final score after the trust multiplier is applied. */
  score: number;
  /** The untouched input score — for telemetry / X-ray. */
  originalScore: number;
  /** The multiplier applied (exactly `1.0` for neutral / quarantined-kept). */
  multiplier: number;
  /** The full TrustScore result for X-ray + epistemic rendering. */
  trust: TrustScoreResult;
  /** `true` when the item was excluded from injection by quarantine. */
  quarantined: boolean;
}

export interface TrustStageOptions {
  /** `path → TrustSignals`. Candidates absent from the map score neutral. */
  signals: ReadonlyMap<string, TrustSignals>;
  weights?: TrustWeights;
  /** Multiplier bounds; see {@link trustMultiplier}. */
  minMultiplier?: number;
  maxMultiplier?: number;
  /**
   * When `true` (default), `quarantine`-band items are excluded from the
   * returned (injected) list but still appear in {@link TrustStageOutput.all}
   * with `quarantined: true` so X-ray can surface them with a reason.
   * Only effective when the stage is active at all.
   */
  quarantine?: boolean;
  /**
   * Re-sort admitted candidates by descending multiplied score. Default `true`.
   * When `false`, admitted items keep input order; quarantined items are still
   * separated out.
   */
  reorder?: boolean;
}

/** Output of {@link applyTrustScoreStage}. */
export interface TrustStageOutput {
  /** Admitted (injectable) candidates, score-multiplied and optionally sorted. */
  admitted: TrustStageResultItem[];
  /**
   * Quarantined candidates — excluded from injection but visible to X-ray with
   * the reason (rule 34 — exclusion must never look like "no result"). Callers
   * that only need the injected list read `admitted`; X-ray reads `all`.
   */
  quarantined: TrustStageResultItem[];
  /** Every candidate (admitted + quarantined) in input order, for X-ray. */
  all: TrustStageResultItem[];
}

/**
 * Apply the unified TrustScore stage: score each candidate, multiply its base
 * score by `trustMultiplier(trust.score)`, and separate hard-negative
 * (quarantine) items from the injectable set.
 *
 * Neutral candidates (no signals → multiplier `1.0`) are mathematically
 * untouched, preserving byte-identical ranking for uninstrumented memories
 * when the feature is ON (and the whole stage is skipped when OFF — rule 39).
 */
export function applyTrustScoreStage(
  candidates: readonly TrustStageCandidate[],
  options: TrustStageOptions,
): TrustStageOutput {
  const reorder = options.reorder !== false;
  const quarantine = options.quarantine !== false;
  const minMul = options.minMultiplier;
  const maxMul = options.maxMultiplier;

  const all: TrustStageResultItem[] = [];
  const admitted: TrustStageResultItem[] = [];
  const quarantined: TrustStageResultItem[] = [];

  for (let i = 0; i < candidates.length; i += 1) {
    const c = candidates[i]!;
    // Prefer the namespace-aware composite key; fall back to path for callers
    // (and tests) that key signals by bare path (#2020).
    const signals = options.signals.get(c.key ?? c.path) ?? options.signals.get(c.path);
    const trust = computeTrustScore(signals, options.weights);
    const isQuarantined = quarantine && trust.band === "quarantine";
    // Quarantined items are excluded from injection. Keep their score unchanged
    // so X-ray shows what the pipeline WOULD have injected — never inflate or
    // zero the score of a hidden item (rule 34).
    const multiplier = isQuarantined ? 1 : trustMultiplier(trust.score, minMul, maxMul);
    // Clamp the base score at zero before multiplying, mirroring the
    // memory-worth filter: a negative base would invert the multiplier's
    // intended direction (see memory-worth-filter.ts:145-153).
    const safeBase = c.score < 0 ? 0 : c.score;
    const scored = safeBase * multiplier;
    const item: TrustStageResultItem = {
      path: c.path,
      ...(c.key === undefined ? {} : { key: c.key }),
      score: scored,
      originalScore: c.score,
      multiplier,
      trust,
      quarantined: isQuarantined,
    };
    all.push(item);
    if (isQuarantined) quarantined.push(item);
    else admitted.push(item);
  }

  if (reorder) {
    // Stable sort by descending multiplied score, with original input position
    // as the deterministic tiebreaker (CLAUDE.md rule 19 / checklist §12).
    admitted.sort((a, b) => {
      if (b.score !== a.score) return b.score - a.score;
      // Tiebreaker: original insertion order. We don't have the index handy on
      // the item, so derive it from `all` ordering (input order is preserved
      // there). Equal-score items keep first-seen-first order.
      return 0;
    });
    // Node's sort is stable (ES2019+); the explicit `return 0` documents the
    // contract for reviewers.
  }

  return { admitted, quarantined, all };
}

/**
 * Compact X-ray projection of one stage item. Kept separate from the full
 * `TrustScoreResult` so the X-ray snapshot type stays narrow and serializable,
 * and so the renderer never depends on the scorer's internal component map
 * shape beyond `{ value, weight }`.
 */
export interface TrustXrayProjection {
  score: number;
  band: TrustBand;
  components: Record<string, TrustScoreComponent>;
  multiplier: number;
  quarantined: boolean;
  /** Human-readable exclusion reason, present only when quarantined. */
  quarantineReason?: string;
}

/** Build the X-ray projection for one stage result item. */
export function projectTrustForXray(item: TrustStageResultItem): TrustXrayProjection {
  const proj: TrustXrayProjection = {
    score: item.trust.score,
    band: item.trust.band,
    components: item.trust.components,
    multiplier: item.multiplier,
    quarantined: item.quarantined,
  };
  if (item.quarantined) {
    proj.quarantineReason = explainQuarantine(item.trust);
  }
  return proj;
}

/** Deterministic, component-derived reason a memory was quarantined. */
export function explainQuarantine(trust: TrustScoreResult): string {
  const c = trust.components;
  if (c.faithfulness && c.faithfulness.value === 0) return "faithfulness: contradicted";
  if (c.contradiction && c.contradiction.value <= 0.2) return "contradiction: pending review";
  return "hard-negative trust signal";
}


// ─── Recall-stage signal builder (I/O orchestration) ──────────────────────

/**
 * Narrow callbacks the signal builder needs from its host (the orchestrator).
 * Kept as interfaces so the module stays pure-testable: the host binds
 * `getStorage` / `readQmdResultMemory` into these and the builder owns cache
 * management, namespace iteration, and the cold-tier direct fallback.
 */
export interface TrustScoreRerankDeps {
  /** Read every memory in a namespace for the hot-tier signal scan. */
  readNamespaceMemories(
    namespace: string,
  ): Promise<ReadonlyArray<{ path: string; frontmatter: TrustFrontmatterProjection }>>;
  /** Read one memory's frontmatter by path (cold-tier direct fallback). The
   * owning namespace is passed so a relative path resolves against the correct
   * namespace store instead of the first fallback (#2020). */
  readMemoryFrontmatter(
    path: string,
    preferredNamespace?: string,
  ): Promise<TrustFrontmatterProjection | null>;
  /**
   * Current cross-process corpus version for a namespace (issue #1905). Used
   * to key the per-namespace corpus-fallback cache so it invalidates on the
   * next memory mutation instead of on a wall-clock timer that is shorter than
   * recall latency (which produced a permanent steady-state miss).
   */
  getNamespaceVersion(namespace: string): Promise<number>;
}

/**
 * Per-namespace signal cache the host owns and the builder mutates. Keyed on
 * the shared corpus version (issue #1905): an entry is valid iff its `version`
 * still equals the namespace's current corpus version AND it is younger than
 * TRUST_SIGNAL_CACHE_MAX_AGE_MS. The age bound is required because trust
 * signals bake wall-clock time into their values (ageDays,
 * computeMemoryWorth(..., now) with recency half-life) — pure version
 * invalidation would serve stale decay on a read-only corpus (#1905, Codex).
 */
export interface TrustScoreSignalCache {
  cache: Map<string, { version: number; cachedAt: number; signals: ReadonlyMap<string, TrustSignals> }>;
}

/** See TrustScoreSignalCache — bounds time-based staleness of cached signals. */
export const TRUST_SIGNAL_CACHE_MAX_AGE_MS = 300_000;

/** Bound on distinct namespaces retained; overflow evicts the oldest. */
export const TRUST_SIGNAL_CACHE_MAX_NAMESPACES = 64;

/** Insert-ordered bounded set: evict the oldest namespace on overflow. */
function capTrustSignalCache(cache: TrustScoreSignalCache["cache"], max: number): void {
  while (cache.size > max) {
    const oldest = cache.keys().next().value;
    if (oldest === undefined) break;
    cache.delete(oldest);
  }
}

/**
 * Build the `path → TrustSignals` map for recall candidates.
 *
 * O(candidates) inversion (issue #1905): when the host passes
 * `preloadedFrontmatter` (frontmatter already loaded on the hot recall path),
 * candidate signals are seeded directly from it — no corpus scan. Only
 * candidates still missing fall back to the corpus-level per-namespace map
 * (config-gated, version-keyed so it actually hits in steady state) and then
 * to a bounded-parallel direct per-path read.
 *
 * Fail-open: a single unreadable namespace or memory is logged and skipped so
 * a storage hiccup never breaks recall (mirrors `memory-worth-filter.ts`).
 */
export async function buildTrustSignalsForRerank(
  candidates: readonly (
    | string
    | { path: string; signalKey?: string; lookupKey?: string; namespace?: string }
  )[],
  namespaces: readonly string[],
  deps: TrustScoreRerankDeps,
  signalCache: TrustScoreSignalCache,
  now: Date,
  options: {
    recencyHalfLifeDays?: number;
    logDebug?: (message: string, context: Record<string, unknown>) => void;
    /**
     * Candidate frontmatter already loaded on the hot recall path (issue
     * #1905). When present, candidate signals are seeded from it before any
     * corpus scan, so the common warm-candidate recall does zero
     * `readNamespaceMemories` calls. Structural — a `MemoryFile` map satisfies
     * `{ frontmatter: TrustFrontmatterProjection }` without importing it.
     */
    preloadedFrontmatter?: ReadonlyMap<string, { frontmatter: TrustFrontmatterProjection }>;
    /**
     * When false, skip the corpus-level `readNamespaceMemories` fallback
     * entirely (candidates-first + direct-read only). Defaults to true so the
     * corpus path stays reachable. See `recallTrustStageCorpusFallbackEnabled`.
     */
    corpusFallbackEnabled?: boolean;
    /**
     * Cooperative cancellation (issue #1905, Codex): when the recall's shared
     * enrichment-assembly deadline wins the race, the host aborts this signal
     * so an orphaned corpus scan / direct-read loop stops at the next loop
     * boundary instead of continuing to burn I/O after recall already returned.
     */
    abortSignal?: AbortSignal;
  } = {},
): Promise<Map<string, TrustSignals>> {
  const logDebug = options.logDebug ?? (() => {});
  const signals = new Map<string, TrustSignals>();
  const corpusFallbackEnabled = options.corpusFallbackEnabled ?? true;
  const halfLife = { recencyHalfLifeDays: options.recencyHalfLifeDays };

  // Paths examined via preloaded frontmatter (issue #1905, Cursor/Codex).
  // buildTrustSignalMap deliberately OMITS neutral memories (no trust fields),
  // so a preloaded candidate can be examined yet absent from `signals` — it
  // must NOT be treated as missing, or the corpus fallback + direct read fire
  // for every uninstrumented hot candidate, defeating the O(candidates) path.
  // Absent-from-signals still means multiplier 1.0 downstream, exactly what a
  // corpus scan would have produced for the same neutral memory.
  const preloadedKeys = new Set<string>();

  // Normalize candidates to a composite identity: `signalKey` is what the
  // trust stage looks up (namespace-aware), `lookupKey` matches the preloaded
  // frontmatter map's key, `path` is the raw store path used for corpus/direct
  // reads. A bare string keeps the legacy path-only behavior (#2020).
  const normalized = candidates.map((c) =>
    typeof c === "string"
      ? { path: c, signalKey: c, lookupKey: c, namespace: undefined as string | undefined }
      : {
          path: c.path,
          signalKey: c.signalKey ?? c.path,
          lookupKey: c.lookupKey ?? c.path,
          namespace: c.namespace,
        },
  );

  // O(candidates) fast path: seed signals from candidate frontmatter already
  // loaded on the hot recall path. Reuses the exact `buildTrustSignalMap`
  // computation so a candidate's signals equal what a corpus scan produced.
  if (options.preloadedFrontmatter) {
    const preloaded: Array<{ path: string; frontmatter: TrustFrontmatterProjection }> = [];
    for (const c of normalized) {
      // Composite lookupKey is authoritative; the bare-path fallback keeps
      // path-keyed preloaded maps (e.g. the recent-scan branch) hitting the
      // fast path and is inert in production composite-keyed maps (#2020).
      const mem =
        options.preloadedFrontmatter.get(c.lookupKey) ??
        options.preloadedFrontmatter.get(c.path);
      if (!mem) continue;
      preloadedKeys.add(c.signalKey);
      preloaded.push({ path: c.signalKey, frontmatter: mem.frontmatter });
    }
    if (preloaded.length > 0) {
      const seeded = buildTrustSignalMap(preloaded, now, halfLife);
      for (const [key, s] of seeded) signals.set(key, s);
    }
  }

  // Corpus-level fallback (config-gated): candidates still missing probe a
  // per-namespace signal map, cached and invalidated by the shared
  // cross-process corpus version. Only candidate rows are copied out — never
  // the whole map (issue #1905, no per-recall full-map union).
  if (corpusFallbackEnabled) {
    const seenNamespaces = new Set<string>();
    for (const ns of namespaces) {
      // Cooperative cancellation: the recall's assembly deadline may have won
      // the race — stop before starting another namespace scan (#1905, Codex).
      if (options.abortSignal?.aborted) break;
      if (seenNamespaces.has(ns)) continue;
      seenNamespaces.add(ns);
      if (normalized.every((c) => signals.has(c.signalKey) || preloadedKeys.has(c.signalKey))) break;
      try {
        const version = await deps.getNamespaceVersion(ns);
        const cached = signalCache.cache.get(ns);
        const nowMs = now.getTime();
        let nsMap: ReadonlyMap<string, TrustSignals>;
        // Valid iff the corpus version still matches AND the entry is younger
        // than the max age: trust signals bake `now` into their values, so an
        // unchanged corpus still goes stale as wall-clock advances (#1905, Codex).
        if (
          cached &&
          cached.version === version &&
          nowMs - cached.cachedAt < TRUST_SIGNAL_CACHE_MAX_AGE_MS
        ) {
          nsMap = cached.signals;
        } else {
          const memories = await deps.readNamespaceMemories(ns);
          nsMap = buildTrustSignalMap(memories, now, halfLife);
          signalCache.cache.set(ns, { version, cachedAt: nowMs, signals: nsMap });
          capTrustSignalCache(signalCache.cache, TRUST_SIGNAL_CACHE_MAX_NAMESPACES);
        }
        for (const c of normalized) {
          // Preloaded keys were already examined — absent-from-signals means
          // neutral (multiplier 1.0), identical to what the corpus map holds.
          if (signals.has(c.signalKey) || preloadedKeys.has(c.signalKey)) continue;
          // A namespaced candidate belongs to exactly one namespace: never seed
          // its signals from a different namespace's corpus map, or two
          // same-path candidates in different namespaces collapse (#2020).
          if (c.namespace !== undefined && c.namespace !== ns) continue;
          const s = nsMap.get(c.path);
          if (s) signals.set(c.signalKey, s);
        }
      } catch (err) {
        logDebug("trust-score: failed to read namespace, skipping", {
          namespace: ns,
          error: (err as Error).message,
        });
      }
    }
  }

  // Direct per-path fallback for candidates still absent (cold-tier / archive).
  // Preloaded paths are excluded — they were examined and are neutral priors.
  // Bounded-parallel (≤16) to match loadSearchResultMemoryMap's batch size.
  const missing = normalized.filter(
    (c) => !signals.has(c.signalKey) && !preloadedKeys.has(c.signalKey),
  );
  if (missing.length > 0) {
    const fallbackMemories: Array<{ path: string; frontmatter: TrustFrontmatterProjection }> = [];
    const BATCH = 16;
    for (let off = 0; off < missing.length; off += BATCH) {
      // Cooperative cancellation between batches (#1905, Codex).
      if (options.abortSignal?.aborted) break;
      const batch = await Promise.all(
        missing.slice(off, off + BATCH).map(async (c) => {
          try {
            const frontmatter = await deps.readMemoryFrontmatter(c.path, c.namespace);
            return frontmatter ? { path: c.signalKey, frontmatter } : null;
          } catch (err) {
            logDebug("trust-score: direct path lookup failed", {
              path: c.path,
              error: (err as Error).message,
            });
            return null;
          }
        }),
      );
      for (const item of batch) if (item) fallbackMemories.push(item);
    }
    if (fallbackMemories.length > 0) {
      const fallbackSignals = buildTrustSignalMap(fallbackMemories, now, halfLife);
      for (const [key, s] of fallbackSignals) signals.set(key, s);
    }
  }

  return signals;
}

/**
 * connectors/label.ts — shared constants for rendering a connector identity
 * into model-visible surfaces (issue #2183).
 *
 * `CONNECTOR_ID_PATTERN` is the canonical persisted-ID charset (re-exported from
 * index.ts so callers don't depend on the registry module's internals).
 * `CONNECTOR_LABEL_MAX_LENGTH` is the display bound shared by the recall
 * renderer and the extraction-side helper (#2184) so the two cannot drift.
 *
 * The recall renderer TRUNCATES past the bound (attribution survives); #2184
 * SUPPRESSES instead, because a truncated id in a prompt could collide with a
 * different connector whereas a truncated display label cannot mislead the same
 * way. Kept in its own module so the capped registry file (connectors/index.ts)
 * stays at its ratchet ceiling.
 */
export { CONNECTOR_ID_PATTERN } from "./index.js";
import { loadRegistry, BUILTIN_CONNECTORS } from "./index.js";

export const CONNECTOR_LABEL_MAX_LENGTH = 64;

let knownIds: ReadonlySet<string> | null = null;
let knownIdsAt = 0;
const KNOWN_IDS_TTL_MS = 60_000;

export function knownConnectorIds(): ReadonlySet<string> {
  const now = Date.now();
  if (knownIds !== null && now - knownIdsAt < KNOWN_IDS_TTL_MS) return knownIds;
  try {
    const ids = new Set(loadRegistry().connectors.map((c: { id: string }) => c.id));
    knownIds = ids;
    knownIdsAt = now;
    return knownIds;
  } catch {
    return new Set(BUILTIN_CONNECTORS.map((c: { id: string }) => c.id));
  }
}

