// ── Registry management ───────────────────────────────────────────────────

export const CONNECTOR_ID_PATTERN = /^[A-Za-z0-9][A-Za-z0-9._-]*$/;

export function isValidConnectorId(connectorId: unknown): connectorId is string {
  return typeof connectorId === "string" && CONNECTOR_ID_PATTERN.test(connectorId);
}

function isConnectorManifest(value: unknown): value is ConnectorManifest {
  return (
    typeof value === "object" &&
    value !== null &&
    !Array.isArray(value) &&
    isValidConnectorId((value as { id?: unknown }).id)
  );
}


export function loadRegistry(): ConnectorRegistry {
  const regPath = getRegistryPath();

  if (!fs.existsSync(regPath)) {
    // First time — bootstrap with built-in connectors
    const registry: ConnectorRegistry = {
      connectors: BUILTIN_CONNECTORS,
      registryPath: regPath,
    };
    saveRegistry(registry);
    return registry;
  }

  try {
    const raw = fs.readFileSync(regPath, "utf8");
    const parsed = JSON.parse(raw);
    if (
      typeof parsed !== "object" ||
      parsed === null ||
      !Array.isArray((parsed as { connectors?: unknown }).connectors)
    ) {
      throw new Error("invalid registry schema");
    }
    // Built-ins always take precedence over persisted entries with the same ID.
    // This ensures that upgraded manifests (e.g. newly-added requiresToken: true)
    // are never shadowed by stale registry.json entries from an older version.
    // Only connectors whose IDs are NOT in BUILTIN_CONNECTORS are preserved from
    // the persisted file — those are genuine user-added custom connectors.
    const builtinIds = new Set(BUILTIN_CONNECTORS.map((b) => b.id));
    const customOnly = (parsed as { connectors: unknown[] }).connectors.filter(
      (c): c is ConnectorManifest => isConnectorManifest(c) && !builtinIds.has(c.id),
    );
    const merged = [...BUILTIN_CONNECTORS, ...customOnly];
    return {
      connectors: merged,
      registryPath: regPath,
    };
  } catch {
    return {
      connectors: BUILTIN_CONNECTORS,
      registryPath: regPath,
    };
  }
}

export function saveRegistry(registry: ConnectorRegistry): void {
  const regPath = registry.registryPath;
  fs.mkdirSync(path.dirname(regPath), { recursive: true });
  fs.writeFileSync(regPath, JSON.stringify({ connectors: registry.connectors }, null, 2));
}

// ── List connectors ────────────────────────────────────────────────────────

export function listConnectors(): {
  installed: ConnectorInstance[];
  available: ConnectorManifest[];
} {
  const registry = loadRegistry();
  const connectorsDir = getConnectorsDir();
  const installedIds = new Set<string>();

  // Find installed connectors
  if (fs.existsSync(connectorsDir)) {
    for (const entry of fs.readdirSync(connectorsDir)) {
      if (entry.endsWith(".json")) {
        try {
          const config = JSON.parse(
            fs.readFileSync(path.join(connectorsDir, entry), "utf8"),
          );
          if (isValidConnectorId(config.connectorId)) {
            installedIds.add(config.connectorId);
          }
        } catch {
          // ignore malformed configs
        }
      }
    }
  }

  // Mark installed vs available
  const available: ConnectorManifest[] = registry.connectors.map((manifest) => ({
    ...manifest,
    installed: installedIds.has(manifest.id),
  }));

  // Build installed list
  const installed: ConnectorInstance[] = [];
  for (const id of installedIds) {
    const configPath = path.join(connectorsDir, `${id}.json`);
    try {
      const raw = JSON.parse(fs.readFileSync(configPath, "utf8")) as Record<string, unknown>;
      // Codex P1 (PRRT_kwDORJXyws56U9U0): strip any legacy `token` field from
      // the returned config so that `remnic connectors list --json` never prints
      // a bearer token — tokens live only in tokens.json. This handles existing
      // on-disk connector.json files written by older Remnic versions without
      // rewriting user files.
      const { token: _redacted, ...config } = raw;
      installed.push({
        connectorId: id,
        config,
        status: "installed",
        installedAt: raw.installedAt as string | undefined,
      });
    } catch {
      // ignore
    }
  }

  return { installed, available };
}

// ── Get connector token ────────────────────────────────────────────────────
// Codex P1 (PRRT_kwDORJXyws56U9U0): tokens are stored exclusively in
// tokens.json. This helper is the canonical way to retrieve the bearer token
// for a connector — connector.json never contains it.

export function getConnectorToken(connectorId: string): string | undefined {
  if (!isValidConnectorId(connectorId)) {
    return undefined;
  }
  try {
    return loadTokenStore().tokens.find((t) => t.connector === connectorId)?.token;
  } catch {
    return undefined;
  }
}

function readSavedConnectorConfig(configPath: string): Record<string, unknown> {
  if (!fs.existsSync(configPath)) return {};
  try {
    const parsed = JSON.parse(fs.readFileSync(configPath, "utf8"));
    if (!parsed || typeof parsed !== "object" || Array.isArray(parsed)) return {};
    const {
      connectorId: _connectorId,
      installedAt: _installedAt,
      token: _token,
      ...config
    } = parsed as Record<string, unknown>;
    return config;
  } catch {
    return {};
  }
}

function removeClearedSavedConnectorConfig(
  savedConnectorConfig: Record<string, unknown>,
  rawUserConfig: Record<string, unknown>,
): Record<string, unknown> {
  const merged: Record<string, unknown> = { ...savedConnectorConfig };
  for (const [key, value] of Object.entries(rawUserConfig)) {
    if (value === undefined || value === null || value === "") {
      delete merged[key];
    }
  }
  return merged;
}

function compactConnectorConfigOverrides(rawUserConfig: Record<string, unknown>): Record<string, unknown> {
  const safeUserConfig: Record<string, unknown> = {};
  for (const [key, value] of Object.entries(rawUserConfig)) {
    if (value === undefined || value === null || value === "") continue;
    safeUserConfig[key] = value;
  }
  return safeUserConfig;
}

// ── Install connector ───────────────────────────────────────────────────────

export function installConnector(options: InstallOptions): InstallResult {
  if (!isValidConnectorId(options.connectorId)) {
    return {
      connectorId: options.connectorId,
      status: "error",
      message:
        `Invalid connector ID ${JSON.stringify(options.connectorId)}. ` +
        "Connector IDs must match [A-Za-z0-9][A-Za-z0-9._-]*.",
    };
  }

  const registry = loadRegistry();
  const manifest = registry.connectors.find((c) => c.id === options.connectorId);

  if (!manifest) {
    return {
      connectorId: options.connectorId,
      status: "error",
      message: `Unknown connector: ${options.connectorId}`,
    };
  }

  // Check if already installed
  const existing = listConnectors().installed.find(
    (c) => c.connectorId === options.connectorId,
  );

  if (existing && !options.force) {
    // Hermes backfill (Issue #1929): connectors installed before shim
    // materialization shipped are exactly the installs missing the discovery
    // shim, and rerunning `install` without --force lands here. Reconcile the
    // shim (idempotent, marker-gated, cleans a prior-HERMES_HOME shim) and
    // persist the surviving path so `remove` can clean it later. Best-effort:
    // failures never change the status.
    let backfillNote = "";
    if (options.connectorId === "hermes") {
      try {
        const hermesJsonPath = path.join(getConnectorsDir(), "hermes.json");
        let parsed: Record<string, unknown> | null = null;
        try {
          const parsedRaw: unknown = JSON.parse(fs.readFileSync(hermesJsonPath, "utf8"));
          // Same shape guard as removeConnector (Bugbot on PR #1938, round
          // 14): a non-object payload ([], null, scalar) is not a connector
          // record — writes onto it would not survive JSON.stringify, so the
          // shim must not be moved on its authority. Reconcile without a
          // prior path and skip persistence.
          if (parsedRaw !== null && typeof parsedRaw === "object" && !Array.isArray(parsedRaw)) {
            parsed = parsedRaw as Record<string, unknown>;
          }
        } catch {
          /* connector JSON unreadable — reconcile without a prior path */
        }
        const priorRaw = parsed?.pluginShimPath;
        const priorPersisted = typeof priorRaw === "string" && priorRaw.length > 0 ? priorRaw : null;
        // Gate the whole backfill on the ACTIVE home carrying a remnic:
        // config (Codex P2 on PR #1938, round 19): moving/creating the
        // discovery shim under a home whose config.yaml has no remnic: block
        // would make Hermes discover a provider with no host/token — this
        // path never writes configs or tokens, so only --force can migrate
        // config, token, and shim together.
        const profileRaw = parsed?.profile;
        let currentConfigPath: string | null = null;
        let activeConfigHasBlock = false;
        let configResolutionError: string | null = null;
        try {
          currentConfigPath = hermesConfigPath(
            typeof profileRaw === "string" && profileRaw.length > 0 ? profileRaw : "default",
          );
          activeConfigHasBlock =
            fs.existsSync(currentConfigPath) &&
            /^remnic:/m.test(fs.readFileSync(currentConfigPath, "utf8"));
        } catch (resolveErr) {
          // Surface the REAL failure (symlinked/invalid HERMES_HOME, bad
          // profile) instead of masking it as a missing remnic: block
          // (Bugbot on PR #1938, round 23).
          configResolutionError = resolveErr instanceof Error ? resolveErr.message : String(resolveErr);
          activeConfigHasBlock = false;
        }
        if (!activeConfigHasBlock) {
          backfillNote = configResolutionError
            ? ` Note: could not resolve the active Hermes home (${configResolutionError}) — skipped the shim backfill. ` +
              `Fix the HERMES_HOME/profile configuration and re-run.`
            : " Note: the active Hermes home's config.yaml has no remnic: block — skipped the shim backfill " +
              "so Hermes cannot discover an unconfigured provider. If Hermes was installed under a different " +
              "HERMES_HOME, re-run with --force to rewrite the config (and token) and migrate the shim " +
              "under the current home.";
          return {
            connectorId: options.connectorId,
            status: "already_installed",
            message: `Already installed. Use --force to reinstall.${backfillNote}`,
          };
        }
        const outcome = reconcileHermesShim(priorPersisted);
        if (outcome.notes.length > 0) {
          backfillNote = ` ${outcome.notes.join(" ")}`;
        }
        let configProvenanceAdded = false;
        if (
          parsed !== null &&
          currentConfigPath !== null &&
          (typeof parsed.hermesConfigPath !== "string" || parsed.hermesConfigPath.length === 0)
        ) {
          // Backfill config.yaml provenance too (round 7): the active config
          // carries a remnic: block (gate above), so record where it lives.
          parsed.hermesConfigPath = currentConfigPath;
          configProvenanceAdded = true;
        }
        // Prior-shim provenance parity (round 18): keep tracking any prior
        // marker shim that survives (e.g. its cleanup failed), and clean
        // inherited priors on a confirmed replacement.
        let shimPriorsChanged = false;
        const cleanedInheritedBackfillShims: string[] = [];
        if (parsed !== null) {
          const shimPriorCandidates: string[] = [];
          if (priorPersisted !== null) {
            shimPriorCandidates.push(priorPersisted);
          }
          if (Array.isArray(parsed.priorPluginShimPaths)) {
            for (const entry of parsed.priorPluginShimPaths) {
              if (typeof entry === "string" && entry.length > 0) {
                shimPriorCandidates.push(entry);
              }
            }
          }
          if (outcome.materializedAt !== null && shimPriorCandidates.length > 0) {
            const cleanupTargets = shimPriorCandidates.filter(
              (candidate) => outcome.persistPath === null || !sameShimTarget(candidate, outcome.persistPath),
            );
            if (cleanupTargets.length > 0) {
              try {
                const cleaned = removeHermesShim(cleanupTargets);
                cleanedInheritedBackfillShims.push(...cleaned.removedPaths);
              } catch {
                /* survivors below stay tracked */
              }
            }
          }
          const survivingShims = survivingMarkerShims(shimPriorCandidates, outcome.persistPath);
          const persistedShimPriors = Array.isArray(parsed.priorPluginShimPaths)
            ? parsed.priorPluginShimPaths
            : null;
          shimPriorsChanged =
            persistedShimPriors === null
              ? survivingShims.length > 0
              : persistedShimPriors.length !== survivingShims.length ||
                survivingShims.some((entry, index) => persistedShimPriors[index] !== entry);
          if (survivingShims.length > 0) {
            parsed.priorPluginShimPaths = survivingShims;
          } else {
            delete parsed.priorPluginShimPaths;
          }
        }
        const shimPathChanged =
          parsed !== null && outcome.persistPath !== null && parsed.pluginShimPath !== outcome.persistPath;
        if (parsed !== null && (shimPathChanged || configProvenanceAdded || shimPriorsChanged)) {
          if (outcome.persistPath !== null) {
            parsed.pluginShimPath = outcome.persistPath;
          }
          try {
            writeSecretFileSync(hermesJsonPath, JSON.stringify(parsed, null, 2));
          } catch (persistErr) {
            // Mirror the install-path rollback (Codex P2 on PR #1938, round 5):
            // without the persisted path, the registry cannot clean the shims
            // this reconcile just changed — undo the filesystem effects so the
            // JSON on disk still matches reality. Shim content is
            // deterministic, so a cleaned prior shim regenerates exactly.
            const rollbackFailures: string[] = [];
            if (
              outcome.materializedAt !== null &&
              outcome.createdNew &&
              (priorPersisted === null || !sameShimTarget(outcome.materializedAt, priorPersisted))
            ) {
              try {
                removeHermesShim([outcome.materializedAt]);
              } catch {
                rollbackFailures.push(`remove ${outcome.materializedAt} manually`);
              }
            }
            if (outcome.priorCleanedAt !== null) {
              try {
                materializeHermesShim(outcome.priorCleanedAt);
              } catch {
                rollbackFailures.push(`restore the shim at ${outcome.priorCleanedAt} manually`);
              }
            }
            // Regenerate inherited priors this backfill pass cleaned — parity
            // with the main install rollback (Bugbot on PR #1938, round 19).
            for (const cleanedPath of cleanedInheritedBackfillShims) {
              if (outcome.priorCleanedAt !== null && sameShimTarget(cleanedPath, outcome.priorCleanedAt)) {
                continue;
              }
              try {
                materializeHermesShim(cleanedPath);
              } catch {
                rollbackFailures.push(`restore the shim at ${cleanedPath} manually`);
              }
            }
            const persistMsg = persistErr instanceof Error ? persistErr.message : String(persistErr);
            backfillNote =
              rollbackFailures.length === 0
                ? ` Note: could not persist the shim path (${persistMsg}); shim changes were rolled back.`
                : ` Note: could not persist the shim path (${persistMsg}) and rollback was incomplete — ${rollbackFailures.join("; ")}.`;
          }
        }
      } catch {
        /* best-effort backfill — install status is unchanged */
      }
    }
    return {
      connectorId: options.connectorId,
      status: "already_installed",
      message: `Already installed. Use --force to reinstall.${backfillNote}`,
    };
  }

  // Write config
  const configDir = getConnectorsDir();
  fs.mkdirSync(configDir, { recursive: true });

  const configPath = path.join(configDir, `${options.connectorId}.json`);
  const savedConnectorConfig = existing ? readSavedConnectorConfig(configPath) : {};

  // For the hermes connector, resolve profile/host/port with the following
  // precedence: saved-connector-JSON → explicit options.config → defaults.
  // Reading happens BEFORE we overwrite the connector JSON so that a
  // force-reinstall without re-supplied --config options preserves the
  // previously configured values and writes the new token to the correct
  // Hermes profile rather than resetting to "default"/127.0.0.1/4318.
  //
  // Issue C fix: sanitizer calls during options resolution are wrapped in
  // try-catch so that invalid user-supplied values (e.g. --config port=abc)
  // return a clean failed InstallResult instead of throwing.
  let hermesSavedProfile: string | undefined;
  let hermesSavedHost: string | undefined;
  let hermesSavedPort: number | undefined;
  let hermesSavedAllowInsecureHttp: boolean | undefined;
  // Resolved values (used both in resolvedConfig and in the YAML update below)
  let hermesResolvedProfile: string | undefined;
  let hermesResolvedHost: string | undefined;
  let hermesResolvedPort: number | undefined;
  let hermesResolvedAllowInsecureHttp = false;
  if (options.connectorId === "hermes") {
    if (fs.existsSync(configPath)) {
      try {
        const prev = JSON.parse(fs.readFileSync(configPath, "utf8"));
        // Fix 2: coerce saved values through sanitizers so that CLI-written
        // string ports ("5555") are accepted just like number ports (5555).
        // Pass each through its sanitizer and fall back to undefined on error
        // so a corrupt saved value doesn't prevent install from defaulting.
        if (prev?.profile != null) {
          try {
            hermesSavedProfile = sanitizeHermesProfile(String(prev.profile));
          } catch {
            // Invalid saved profile — fall through to default
          }
        }
        if (prev?.host != null) {
          try {
            hermesSavedHost = sanitizeHermesHost(String(prev.host));
          } catch {
            // Invalid saved host — fall through to default
          }
        }
        if (prev?.port != null) {
          try {
            const coercedPort = Number(String(prev.port));
            hermesSavedPort = sanitizeHermesPort(coercedPort);
          } catch {
            // Invalid saved port — fall through to default
          }
        }
        if (prev?.allow_insecure_http != null) {
          hermesSavedAllowInsecureHttp = coerceBool(prev.allow_insecure_http, "allow_insecure_http");
        }
      } catch {
        // Could not read existing config — fall through to defaults
      }
    }
    // Use saved/default values here; user-supplied profile/host are validated
    // and applied in the sanitization block below (single point of validation).
    hermesResolvedProfile = hermesSavedProfile ?? "default";
    hermesResolvedHost = hermesSavedHost ?? "127.0.0.1";
    hermesResolvedAllowInsecureHttp = hermesSavedAllowInsecureHttp ?? false;

    // Issue C: wrap sanitizeHermesPort (and profile/host) in try-catch so
    // that invalid user-supplied values return a clean error result.
    if (options.config?.port !== undefined) {
      try {
        hermesResolvedPort = sanitizeHermesPort(Number(String(options.config.port)));
      } catch (err) {
        return {
          connectorId: options.connectorId,
          status: "error",
          message: `Invalid Hermes config: ${err instanceof Error ? err.message : String(err)}`,
        };
      }
    }
    if (hermesResolvedPort === undefined) {
      hermesResolvedPort = hermesSavedPort ?? 4318;
    }

    // Also validate user-supplied profile and host up-front (Issue C coverage).
    if (options.config?.profile !== undefined) {
      try {
        hermesResolvedProfile = sanitizeHermesProfile(String(options.config.profile));
      } catch (err) {
        return {
          connectorId: options.connectorId,
          status: "error",
          message: `Invalid Hermes config: ${err instanceof Error ? err.message : String(err)}`,
        };
      }
    }
    if (options.config?.host !== undefined) {
      try {
        hermesResolvedHost = sanitizeHermesHost(String(options.config.host));
      } catch (err) {
        return {
          connectorId: options.connectorId,
          status: "error",
          message: `Invalid Hermes config: ${err instanceof Error ? err.message : String(err)}`,
        };
      }
    }
    if (options.config?.allow_insecure_http !== undefined) {
      const allowInsecureHttp = coerceBool(options.config.allow_insecure_http, "allow_insecure_http");
      if (allowInsecureHttp === undefined) {
        return {
          connectorId: options.connectorId,
          status: "error",
          message: "Invalid Hermes config: allow_insecure_http must be true or false",
        };
      }
      hermesResolvedAllowInsecureHttp = allowInsecureHttp;
    }
  }

  // Generate a per-connector auth token so the daemon can authenticate
  // requests from this connector.
  //
  // Security gate (PRRT_kwDORJXyws56U9U0 round 6): tokens are ONLY generated
  // and persisted to tokens.json for connectors that actually require bearer-token
  // auth (manifest.requiresToken === true). MCP, CLI, embedded, and SDK connectors
  // never need a token entry on disk — generating one unconditionally materialized
  // credentials for connectors that have no auth requirement, a security regression.
  //
  // For hermes (Issue B fix): use buildTokenEntry() to generate a candidate
  // token WITHOUT immediately persisting it to tokens.json. We commit the
  // candidate to the store only AFTER upsertHermesConfig succeeds, so that
  // a failed or skipped config.yaml write never leaves the daemon with a
  // revoked token and no valid replacement written.
  //
  // For other connectors that requiresToken: generateToken() is idempotent —
  // it filters the old entry and writes a fresh one atomically, so force-reinstall
  // produces a new token automatically.
  //
  // Token write errors (e.g. read-only HOME with writable XDG_CONFIG_HOME)
  // are non-fatal: we degrade gracefully and proceed with the connector
  // config write rather than aborting the whole install.
  //
  // For non-Hermes connectors that requiresToken: snapshot the FULL token store
  // BEFORE generateToken() so that if the connector JSON write later fails, we
  // can restore the store to its pre-install state (UXJG fix — non-Hermes atomic
  // rollback). Using a full-store snapshot (not a single-entry snapshot) ensures
  // that a partial write of tokens.json during generateToken can be unwound
  // atomically, covering both fresh-install and force-reinstall cases uniformly.
  const nonHermesPriorTokenStore = (options.connectorId !== "hermes" && manifest.requiresToken)
    ? loadTokenStore()
    : null;

  let tokenEntry: ReturnType<typeof generateToken> | null = null;
  if (options.connectorId === "hermes") {
    // Build a candidate token; do NOT save yet (Issue B).
    try {
      tokenEntry = buildTokenEntry(options.connectorId);
    } catch {
      // Non-fatal: fall through with tokenEntry === null.
    }
  } else if (manifest.requiresToken) {
    // Only generate and persist a token entry for connectors that need token auth.
    try {
      tokenEntry = generateToken(options.connectorId);
    } catch {
      // Non-fatal: token store unavailable. Connector config will still be
      // written; user can run `remnic token generate <id>` to create the token.
      //
      // Roll back the snapshot so that a partial write of tokens.json during
      // generateToken (e.g. ENOSPC/EIO mid-write) does not leave other
      // connectors' auth state corrupted. Best-effort: if the restore itself
      // fails there is nothing more we can do here, but the error is swallowed
      // so install continues in the same degraded (tokenEntry === null) path
      // as before (PRRT_kwDORJXyws56UleN fix).
      if (nonHermesPriorTokenStore !== null) {
        try {
          saveTokenStore(nonHermesPriorTokenStore);
        } catch {
          // Best-effort: snapshot restore failed; caller sees degraded install.
        }
      }
    }
  }
  // else: connector does not require token auth — tokenEntry stays null and
  // tokens.json is never touched for this connector.

  // Thread 2 (PRRT_kwDORJXyws56VYwM): if the connector requires token auth but
  // generateToken threw (tokenEntry is still null), abort now instead of
  // continuing with a broken install that returns "success" without a valid token.
  if (options.connectorId !== "hermes" && manifest.requiresToken && tokenEntry === null) {
    return {
      connectorId: options.connectorId,
      status: "error",
      message:
        `${manifest.name} install aborted: token generation failed. ` +
        `Run \`remnic token generate ${options.connectorId}\` to create the token, then reinstall.`,
    };
  }

  // Build config from saved values + user overrides.
  // Codex P1 (PRRT_kwDORJXyws56U9U0): tokens MUST NOT be written into
  // connector.json. The authoritative store is tokens.json (0o600). Writing the
  // token here created a second, unredacted copy that `remnic connectors list
  // --json` printed verbatim, leaking live bearer tokens into shell history, CI
  // logs, and telemetry. Callers needing the token for a specific connector
  // must use loadTokenStore() and find the entry by connectorId directly.
  //
  // For hermes, include the resolved profile/host/port so that future
  // force-reinstalls can read them back even if options.config is not supplied.
  //
  // Strip any stray `token` key the caller may have supplied via options.config
  // so it cannot be persisted to disk even on legacy call paths.
  const { token: _callerToken, ...rawUserConfig } = (options.config ?? {}) as Record<string, unknown>;
  const savedConnectorConfigForMerge = removeClearedSavedConnectorConfig(savedConnectorConfig, rawUserConfig);
  const safeUserConfig = compactConnectorConfigOverrides(rawUserConfig);
  const resolvedConfig: Record<string, unknown> = {
    ...savedConnectorConfigForMerge,
    ...safeUserConfig,
    connectorId: options.connectorId,
    installedAt: new Date().toISOString(),
    // For hermes, always overlay the sanitized/coerced resolved values so that
    // the connector JSON always has a numeric port and validated profile/host.
    // This also ensures options.config string values (from --config=port=5555)
    // are replaced with their sanitized numeric equivalents (Fix 2 root cause).
    ...(hermesResolvedProfile !== undefined ? {
      profile: hermesResolvedProfile,
      host: hermesResolvedHost,
      port: hermesResolvedPort,
      allow_insecure_http: hermesResolvedAllowInsecureHttp,
    } : {}),
  };

  // ── Hermes atomic install flow ─────────────────────────────────────────────
  // The Hermes install sequence must be atomic: connector.json must only be
  // written if and only if both the YAML write AND the token-store commit
  // succeed. Partial failures must leave the prior state intact so the daemon
  // keeps working with the old token.
  //
  // Step order (all-or-nothing):
  //   a. Generate token candidate (buildTokenEntry, no store write yet).
  //   b. Validate profile (fail-fast).
  //   c. Write config.yaml via upsertHermesConfig — if skipped (missing dir)
  //      or throws, abort with status "error". Old token is NOT revoked.
  //   d. Commit new token to tokens.json — if this throws, rollback the YAML
  //      write (restore prior content or delete new file) and abort.
  //   e. Write connector.json only after both (c) and (d) succeed.
  //   f. Health check — gated on committed === true && tokenEntry != null.
  //
  // Non-Hermes connectors: connector.json is written immediately (no YAML
  // dependency) and the health check is not performed.

  if (options.connectorId === "hermes") {
    // hermesResolvedProfile/Host/Port were computed above using the correct
    // precedence (saved JSON → explicit options.config → defaults).
    const rawProfile = hermesResolvedProfile!;
    const hermesHost = hermesResolvedHost!;
    const hermesPort = hermesResolvedPort!;

    // (b) Validate profile name — fail-fast before touching any files.
    let hermesProfile: string;
    try {
      hermesProfile = sanitizeHermesProfile(rawProfile);
    } catch (err) {
      return {
        connectorId: options.connectorId,
        status: "error",
        message: `Hermes install aborted: ${err instanceof Error ? err.message : String(err)}`,
      };
    }

    // Token generation is required for an atomic Hermes install.
    if (!tokenEntry) {
      return {
        connectorId: options.connectorId,
        status: "error",
        message:
          "Hermes install aborted: token store unavailable. " +
          "Run `remnic token generate hermes` then reinstall to complete setup.",
      };
    }

    // When HERMES_HOME is explicitly set to a not-yet-created directory, the
    // user has stated where Hermes lives — create it so the config write does
    // not abort while the shim step (recursive mkdir) would have created the
    // same tree anyway (Bugbot on PR #1938, round 11). Without HERMES_HOME the
    // missing-profile-dir skip below stays load-bearing: it is the signal
    // that Hermes is not installed at all.
    {
      const envHermesHome = readEnvVar("HERMES_HOME");
      if (typeof envHermesHome === "string" && envHermesHome.trim().length > 0) {
        try {
          fs.mkdirSync(path.dirname(hermesConfigPath(hermesProfile)), { recursive: true });
        } catch {
          /* resolution or mkdir failure — the config write below reports it */
        }
      }
    }

    // (c) Write config.yaml. If the profile dir does not exist (skipped) or
    // the write throws, abort WITHOUT committing the token or writing connector.json.
    let yamlResult: HermesConfigResult;
    try {
      yamlResult = upsertHermesConfig({
        profile: hermesProfile,
        host: hermesHost,
        port: hermesPort,
        token: tokenEntry.token,
        allowInsecureHttp: hermesResolvedAllowInsecureHttp,
      });
    } catch (err) {
      // upsertHermesConfig threw — old token preserved, connector.json unchanged.
      return {
        connectorId: options.connectorId,
        status: "error",
        message: `Hermes install aborted: config.yaml write failed — ${err instanceof Error ? err.message : String(err)}`,
      };
    }

    if (!yamlResult.updated) {
      // Skipped (profile dir missing) — abort so connector.json is NOT written
      // with a token the daemon won't recognize (the profile doesn't exist).
      // Preserves any prior Hermes profile/connector.json untouched.
      return {
        connectorId: options.connectorId,
        status: "error",
        message: `Hermes install aborted: ${yamlResult.reason ?? "config.yaml not written"}. ` +
          `Create the Hermes profile directory first, then reinstall.`,
      };
    }

    // (d) Commit token to tokens.json. If this fails, roll back the YAML write
    // and abort — the old token must remain valid and connector.json must stay
    // unchanged so the daemon keeps working.
    //
    // IMPORTANT (UXJI/UXJT): Snapshot the FULL token store BEFORE calling
    // commitTokenEntry(). A single-entry approach (capturing the return value
    // of commitTokenEntry) is insufficient: if commitTokenEntry throws mid-write
    // (e.g. ENOSPC truncating tokens.json), the assignment never completes and
    // the rollback becomes a no-op, leaving tokens.json potentially corrupt.
    // The full-store snapshot, captured before the write attempt, is guaranteed
    // clean and can be written back atomically by saveTokenStore.
    const priorTokenStore = loadTokenStore();
    let committed = false;
    try {
      commitTokenEntry(tokenEntry);
      committed = true;
    } catch (commitErr) {
      // Roll back the token store: restore the full snapshot so a partial write
      // (e.g. ENOSPC truncating tokens.json mid-write) cannot leave the store
      // corrupt or missing the prior hermes entry.
      let tokensRolledBack = true;
      let tokensRollbackErrMsg = "";
      try {
        saveTokenStore(priorTokenStore);
      } catch (tokenRestoreErr) {
        tokensRolledBack = false;
        tokensRollbackErrMsg = tokenRestoreErr instanceof Error ? tokenRestoreErr.message : String(tokenRestoreErr);
      }
      // Roll back the YAML write: restore prior content (or delete newly-created file).
      let yamlRolledBack = true;
      let yamlRollbackErrMsg = "";
      try {
        if (yamlResult.priorContent === null) {
          // File was created new — remove it entirely.
          fs.unlinkSync(yamlResult.configPath);
        } else if (typeof yamlResult.priorContent === "string") {
          // File existed before — restore original content.
          writeSecretFileSync(yamlResult.configPath, yamlResult.priorContent);
        }
      } catch (yamlRestoreErr) {
        yamlRolledBack = false;
        yamlRollbackErrMsg = yamlRestoreErr instanceof Error ? yamlRestoreErr.message : String(yamlRestoreErr);
      }
      // Build an error message that accurately reflects which rollbacks succeeded.
      const commitErrMsg = commitErr instanceof Error ? commitErr.message : String(commitErr);
      let message: string;
      if (tokensRolledBack && yamlRolledBack) {
        message =
          `Hermes install failed during token commit — ` +
          `${commitErrMsg}. ` +
          `config.yaml and tokens.json restored to prior state. ` +
          `Resolve the tokens.json access issue, then reinstall.`;
      } else if (!yamlRolledBack && tokensRolledBack) {
        message =
          `Hermes install failed during token commit — ` +
          `${commitErrMsg}. ` +
          `tokens.json restored but config.yaml rollback ALSO failed ` +
          `(${yamlRollbackErrMsg}). ` +
          `Hermes daemon may be in an inconsistent state: config references a stale token. ` +
          `Manually inspect ${yamlResult.configPath} and reinstall.`;
      } else if (yamlRolledBack && !tokensRolledBack) {
        message =
          `Hermes install failed during token commit — ` +
          `${commitErrMsg}. ` +
          `config.yaml restored but tokens.json rollback ALSO failed ` +
          `(${tokensRollbackErrMsg}). ` +
          `Hermes daemon may be in an inconsistent state: tokens.json is corrupt or incomplete. ` +
          `Manually inspect ~/.remnic/tokens.json and reinstall.`;
      } else {
        message =
          `Hermes install failed during token commit — ` +
          `${commitErrMsg}. ` +
          `BOTH rollbacks failed: config.yaml rollback failed (${yamlRollbackErrMsg}); ` +
          `tokens.json rollback failed (${tokensRollbackErrMsg}). ` +
          `Hermes daemon is likely in an inconsistent state. ` +
          `Manually inspect ${yamlResult.configPath} ` +
          `and ~/.remnic/tokens.json, then reinstall.`;
      }
      return {
        connectorId: options.connectorId,
        status: "error",
        message,
      };
    }

    // (d2) Reconcile the on-disk shim BEFORE connector.json is written so the
    // persisted pluginShimPath always references the shim that actually
    // survives on disk. Invariant (PR #1938 review, third round): a
    // Remnic-generated shim on disk is either removed or referenced by the
    // connector JSON — the registry never silently discards the path of a
    // shim that is still present (e.g. when materialization at the NEW
    // HERMES_HOME fails during a force-reinstall).
    const priorShimPathRaw = savedConnectorConfig.pluginShimPath;
    const shimOutcome = reconcileHermesShim(
      typeof priorShimPathRaw === "string" && priorShimPathRaw.length > 0 ? priorShimPathRaw : null,
    );
    if (shimOutcome.persistPath !== null) {
      resolvedConfig.pluginShimPath = shimOutcome.persistPath;
    }
    // Prior-shim provenance (Codex P2 on PR #1938, round 18): mirror the
    // config handling — a prior marker shim whose cleanup failed or was
    // skipped must stay tracked, or a later remove cannot discover it. On a
    // confirmed replacement, inherited prior shims are actively cleaned
    // (marker-gated); whatever still carries the marker afterwards persists
    // as priorPluginShimPaths in the SAME registry write as everything else.
    const cleanedInheritedShims: string[] = [];
    {
      const shimPriorCandidates: string[] = [];
      if (typeof priorShimPathRaw === "string" && priorShimPathRaw.length > 0) {
        shimPriorCandidates.push(priorShimPathRaw);
      }
      const inheritedShimPriorsRaw = savedConnectorConfig.priorPluginShimPaths;
      if (Array.isArray(inheritedShimPriorsRaw)) {
        for (const entry of inheritedShimPriorsRaw) {
          if (typeof entry === "string" && entry.length > 0) {
            shimPriorCandidates.push(entry);
          }
        }
      }
      if (shimOutcome.materializedAt !== null && shimPriorCandidates.length > 0) {
        const cleanupTargets = shimPriorCandidates.filter(
          (candidate) => shimOutcome.persistPath === null || !sameShimTarget(candidate, shimOutcome.persistPath),
        );
        if (cleanupTargets.length > 0) {
          try {
            const cleaned = removeHermesShim(cleanupTargets);
            cleanedInheritedShims.push(...cleaned.removedPaths);
          } catch {
            /* survivors below stay tracked */
          }
        }
      }
      const survivingShims = survivingMarkerShims(shimPriorCandidates, shimOutcome.persistPath);
      if (survivingShims.length > 0) {
        resolvedConfig.priorPluginShimPaths = survivingShims;
      } else {
        delete resolvedConfig.priorPluginShimPaths;
      }
    }

    // Persist the config.yaml location used at install time (it honors the
    // active HERMES_HOME) so remove can clean the exact file even if
    // HERMES_HOME is unset or changed by then — same provenance rule as
    // pluginShimPath (Codex P2 on PR #1938, round 6).
    resolvedConfig.hermesConfigPath = yamlResult.configPath;

    // Prior-config handling (rounds 9-15) runs BEFORE the primary
    // connector.json write so priorHermesConfigPaths lands atomically in the
    // SAME write as the rest of the record — a best-effort follow-up write
    // could fail and leave surviving remnic: blocks untracked (Bugbot on
    // PR #1938, round 15). Notes are collected here and surfaced after the
    // write succeeds.
    const hermesPriorNotes: string[] = [];
    const priorConfigPathRaw = savedConnectorConfig.hermesConfigPath;
    const priorConfigPath =
      typeof priorConfigPathRaw === "string" && priorConfigPathRaw.length > 0 ? priorConfigPathRaw : null;
    const priorConfigDiffers =
      priorConfigPath !== null && !sameHermesConfigTarget(priorConfigPath, yamlResult.configPath);
    // Every prior-config mutation performed before the registry write records
    // the file's pre-mutation content here, so the connector.json-write
    // failure path can restore it (Bugbot + Codex P2 on PR #1938, round 16).
    const hermesPriorConfigMutations: Array<{ mutatedPath: string; priorContent: string }> = [];
    if (priorConfigDiffers && priorConfigPath !== null && shimOutcome.materializedAt === null) {
      // Unconfirmed shim move: the prior installation stays the working
      // fallback. Refresh its config with the ACTIVE token — the install just
      // rotated the token store, so leaving the old inline token would make
      // the fallback fail daemon auth (round 13). The upsert preserves the
      // file's other remnic: sub-keys.
      let fallbackDetail = "";
      if (isPlausibleHermesConfigPath(priorConfigPath)) {
        try {
          const beforeRefresh = fs.readFileSync(priorConfigPath, "utf8");
          const refresh = upsertHermesConfigAt(priorConfigPath, {
            host: hermesHost,
            port: hermesPort,
            token: tokenEntry.token,
            allowInsecureHttp: hermesResolvedAllowInsecureHttp,
          });
          if (refresh.updated) {
            hermesPriorConfigMutations.push({ mutatedPath: priorConfigPath, priorContent: beforeRefresh });
          }
          fallbackDetail = refresh.updated
            ? " Its remnic: block was refreshed with the newly-issued token so it keeps working."
            : ` Note: its token could not be refreshed (${refresh.reason ?? "config not writable"}) — re-run install with HERMES_HOME pointing there to restore daemon auth.`;
        } catch (refreshErr) {
          fallbackDetail = ` Note: its token could not be refreshed (${refreshErr instanceof Error ? refreshErr.message : String(refreshErr)}) — re-run install with HERMES_HOME pointing there to restore daemon auth.`;
        }
      } else {
        fallbackDetail =
          " Note: its token was rotated by this install — re-run install with HERMES_HOME pointing there to restore daemon auth.";
      }
      hermesPriorNotes.push(
        `Note: left the prior-install Hermes config in place at ${priorConfigPath} — ` +
          `no Remnic shim could be written under the current Hermes home, so the prior ` +
          `installation remains the working fallback.${fallbackDetail} Resolve the shim ` +
          `collision/failure above and re-run with --force to complete the migration.`,
      );
    }
    // Reconcile prior-config provenance (rounds 12-14): on a CONFIRMED
    // replacement, actively clean every displaced/inherited prior config; on
    // an unconfirmed move, preserve them. Every candidate whose remnic: block
    // still survives afterwards is persisted in priorHermesConfigPaths so a
    // later `remove` cleans them all; stale entries are dropped.
    {
      const candidates: string[] = [];
      if (priorConfigDiffers && priorConfigPath !== null) {
        candidates.push(priorConfigPath);
      }
      const inheritedArrayRaw = savedConnectorConfig.priorHermesConfigPaths;
      if (Array.isArray(inheritedArrayRaw)) {
        for (const entry of inheritedArrayRaw) {
          if (typeof entry === "string" && entry.length > 0) {
            candidates.push(entry);
          }
        }
      }
      // Legacy single-path key from earlier builds of this branch.
      const inheritedLegacyRaw = savedConnectorConfig.priorHermesConfigPath;
      if (typeof inheritedLegacyRaw === "string" && inheritedLegacyRaw.length > 0) {
        candidates.push(inheritedLegacyRaw);
      }
      if (shimOutcome.materializedAt !== null) {
        for (const candidate of candidates) {
          if (sameHermesConfigTarget(candidate, yamlResult.configPath)) {
            continue;
          }
          if (!isPlausibleHermesConfigPath(candidate)) {
            continue;
          }
          try {
            const beforeCleanup = fs.readFileSync(candidate, "utf8");
            const cleanup = removeHermesConfigFile(candidate);
            if (cleanup.updated) {
              hermesPriorConfigMutations.push({ mutatedPath: candidate, priorContent: beforeCleanup });
              hermesPriorNotes.push(`Cleaned remnic: block from prior-install Hermes config: ${candidate}`);
            }
          } catch {
            hermesPriorNotes.push(
              `Note: could not clean the remnic: block from the prior-install Hermes config at ${candidate} — remove it manually.`,
            );
          }
        }
      }
      const survivingPriors: string[] = [];
      for (const candidate of candidates) {
        if (sameHermesConfigTarget(candidate, yamlResult.configPath)) {
          continue;
        }
        if (survivingPriors.some((kept) => sameHermesConfigTarget(kept, candidate))) {
          continue;
        }
        let blockSurvives = false;
        try {
          blockSurvives = /^remnic:/m.test(fs.readFileSync(candidate, "utf8"));
        } catch {
          blockSurvives = false;
        }
        if (blockSurvives) {
          survivingPriors.push(candidate);
        }
      }
      if (survivingPriors.length > 0) {
        resolvedConfig.priorHermesConfigPaths = survivingPriors;
      } else {
        delete resolvedConfig.priorHermesConfigPaths;
      }
      // The legacy single-path key never survives a rewrite.
      delete resolvedConfig.priorHermesConfigPath;
    }

    // (e) Both YAML write and token commit succeeded — now attempt to write connector.json.
    // If this write fails (e.g. connectors dir is not writable), roll back Phase D (token
    // commit) and Phase C (YAML upsert) so no partial-install state is left behind.
    // We restore the full token store snapshot captured before Phase D so that
    // tokens.json is guaranteed consistent with the rolled-back config.yaml.
    try {
      writeSecretFileSync(configPath, JSON.stringify(resolvedConfig, null, 2));
    } catch (writeErr) {
      // Roll back Phase D: restore the full token store snapshot so tokens.json
      // is consistent with the rolled-back config.yaml.
      let tokenRollbackFailed = false;
      let tokenRollbackMsg = "token store restored to pre-install snapshot";
      try {
        saveTokenStore(priorTokenStore);
      } catch (tokenRestoreErr) {
        tokenRollbackFailed = true;
        tokenRollbackMsg = `token rollback failed: ${tokenRestoreErr instanceof Error ? tokenRestoreErr.message : String(tokenRestoreErr)}`;
      }
      // Roll back Phase C: restore config.yaml to its prior content.
      let yamlRollbackMsg = "config.yaml restored";
      try {
        if (yamlResult.priorContent === null) {
          // File was created new — delete it.  Track whether the unlink actually
          // succeeded so we report honestly rather than claiming removal when it
          // silently failed inside the inner catch.
          let unlinkSucceeded = false;
          let unlinkErr: unknown;
          try {
            fs.unlinkSync(yamlResult.configPath);
            unlinkSucceeded = true;
          } catch (err) {
            unlinkErr = err;
          }
          if (unlinkSucceeded) {
            yamlRollbackMsg = "config.yaml removed (was newly created)";
          } else {
            const unlinkMsg = unlinkErr instanceof Error ? unlinkErr.message : String(unlinkErr);
            yamlRollbackMsg = `config.yaml rollback failed: could not remove newly-created file — ${unlinkMsg}`;
          }
        } else if (typeof yamlResult.priorContent === "string") {
          writeSecretFileSync(yamlResult.configPath, yamlResult.priorContent);
          yamlRollbackMsg = "config.yaml restored to prior content";
        }
      } catch (yamlRollbackErr) {
        yamlRollbackMsg = `config.yaml rollback failed: ${yamlRollbackErr instanceof Error ? yamlRollbackErr.message : String(yamlRollbackErr)}`;
      }
      // Roll back the (d2) shim reconciliation: without a persisted
      // pluginShimPath the registry cannot clean these effects later
      // (Bugbot + Codex P2 on PR #1938, round 4). The shim content is
      // deterministic, so a cleaned prior shim can be regenerated exactly.
      let shimRollbackMsg = "no shim changes to roll back";
      const shimRollbackFailures: string[] = [];
      const priorPersisted =
        typeof priorShimPathRaw === "string" && priorShimPathRaw.length > 0 ? priorShimPathRaw : null;
      if (
        shimOutcome.materializedAt !== null &&
        shimOutcome.createdNew &&
        (priorPersisted === null || !sameShimTarget(shimOutcome.materializedAt, priorPersisted))
      ) {
        // Newly created at a location the registry never tracked — delete it
        // (marker-gated). A shim that pre-existed this install (createdNew ===
        // false) is left in place: it was functional before and our overwrite
        // is byte-identical deterministic content (Codex P2, round 7). Path
        // comparison is by resolved file identity, not string equality.
        try {
          removeHermesShim([shimOutcome.materializedAt]);
        } catch (err) {
          shimRollbackFailures.push(
            `could not remove the newly-written shim at ${shimOutcome.materializedAt} (${err instanceof Error ? err.message : String(err)})`,
          );
        }
      }
      if (shimOutcome.priorCleanedAt !== null) {
        try {
          materializeHermesShim(shimOutcome.priorCleanedAt);
        } catch (err) {
          shimRollbackFailures.push(
            `could not restore the prior shim at ${shimOutcome.priorCleanedAt} (${err instanceof Error ? err.message : String(err)})`,
          );
        }
      }
      // Regenerate inherited prior shims the (d2) provenance pass cleaned —
      // content is deterministic, so restoration is exact (round 18).
      for (const cleanedPath of cleanedInheritedShims) {
        if (shimOutcome.priorCleanedAt !== null && sameShimTarget(cleanedPath, shimOutcome.priorCleanedAt)) {
          continue;
        }
        try {
          materializeHermesShim(cleanedPath);
        } catch (err) {
          shimRollbackFailures.push(
            `could not restore the prior shim at ${cleanedPath} (${err instanceof Error ? err.message : String(err)})`,
          );
        }
      }
      if (
        shimOutcome.materializedAt !== null ||
        shimOutcome.priorCleanedAt !== null ||
        cleanedInheritedShims.length > 0
      ) {
        shimRollbackMsg =
          shimRollbackFailures.length === 0
            ? "plugin shim changes rolled back"
            : `plugin shim rollback incomplete: ${shimRollbackFailures.join("; ")}`;
      }
      // Roll back the (d2) prior-config mutations from their recorded
      // pre-mutation content: a stripped old-home remnic: block or a
      // token-refreshed fallback must revert alongside tokens.json, or the
      // previously working install is left broken (Bugbot + Codex P2 on
      // PR #1938, round 16). Restore in reverse mutation order.
      let priorConfigRollbackMsg = "no prior-config changes to roll back";
      if (hermesPriorConfigMutations.length > 0) {
        const priorConfigRollbackFailures: string[] = [];
        for (const mutation of [...hermesPriorConfigMutations].reverse()) {
          try {
            writeSecretFileSync(mutation.mutatedPath, mutation.priorContent);
          } catch (restoreErr) {
            priorConfigRollbackFailures.push(
              `could not restore ${mutation.mutatedPath} (${restoreErr instanceof Error ? restoreErr.message : String(restoreErr)})`,
            );
          }
        }
        priorConfigRollbackMsg =
          priorConfigRollbackFailures.length === 0
            ? "prior-install config(s) restored"
            : `prior-install config rollback incomplete: ${priorConfigRollbackFailures.join("; ")}`;
      }
      const urgentSuffix = tokenRollbackFailed
        ? ` tokens.json may be in an inconsistent state — manually restore hermes token with 'remnic token generate hermes'.`
        : "";
      return {
        connectorId: options.connectorId,
        status: "error",
        message:
          `Hermes install aborted: connector config write failed — ` +
          `connector directory may not be writable. ` +
          `Rollback: ${tokenRollbackMsg}; ${yamlRollbackMsg}; ${shimRollbackMsg}; ${priorConfigRollbackMsg}.` +
          `${urgentSuffix} Resolve the permission issue, then reinstall.`,
      };
    }

    const notes: string[] = [];
    notes.push(`Updated Hermes config: ${yamlResult.configPath}`);

    // (g) Report the shim reconciliation performed in (d2) — materialization
    // itself already ran before connector.json was written (Issue #1929).
    notes.push(...shimOutcome.notes);
    // Prior-config handling ran in (d2) before the connector.json write so its
    // provenance landed atomically in the primary record; surface its notes.
    notes.push(...hermesPriorNotes);
    // Provider activation is a manual, non-destructive step: we never edit the
    // exclusive `memory.provider` slot in the user's Hermes config.yaml.
    notes.push(
      "Next step: set `memory.provider: remnic` (and `memory_enabled: true`) in your Hermes config.yaml to activate the provider.",
    );

    // If a migrated default-profile install now writes to Hermes' root config,
    // remove stale Remnic credentials from the legacy default profile file too.
    if (hermesProfile === "default") {
      const legacyDefaultConfigPath = hermesDefaultProfileConfigPath();
      if (!sameHermesConfigTarget(yamlResult.configPath, legacyDefaultConfigPath)) {
        try {
          const legacyDefaultCleanResult = removeHermesConfigFile(legacyDefaultConfigPath);
          if (legacyDefaultCleanResult.updated) {
            notes.push(`Cleaned stale remnic: block from legacy default profile: ${legacyDefaultConfigPath}`);
          }
        } catch {
          notes.push("Note: could not clean stale remnic: block from legacy default profile");
        }
      }
    }

    // Clean up the old profile's remnic: block if the profile changed.
    // Compare resolved config paths (not raw strings) so that case-insensitive
    // filesystems (macOS default) don't treat "Research" and "research" as
    // different profiles — resolving both would yield the same config.yaml,
    // and removing it would strip the block we just wrote (PRRT_kwDORJXyws56VQ76).
    let oldProfileResolvesToDifferentFile = false;
    if (hermesSavedProfile !== undefined) {
      try {
        oldProfileResolvesToDifferentFile =
          !sameHermesConfigTarget(hermesConfigPath(hermesSavedProfile), hermesConfigPath(hermesProfile));
      } catch {
        // If either profile fails sanitization the comparison is moot; skip cleanup.
        oldProfileResolvesToDifferentFile = false;
      }
    }
    if (oldProfileResolvesToDifferentFile) {
      try {
        const oldCleanResult = removeHermesConfig({ profile: hermesSavedProfile! });
        if (oldCleanResult.updated) {
          notes.push(`Cleaned stale remnic: block from previous profile: ${oldCleanResult.configPath}`);
        }
      } catch {
        // Non-fatal: if we can't clean the old profile, log a note but don't fail.
        notes.push(`Note: could not clean stale remnic: block from previous profile "${hermesSavedProfile}"`);
      }
    }

    // (f) Health check — only when the token was actually committed to the store.
    // Without commitment, the daemon won't recognise the token → 401 → 6s sleep
    // → false-negative "Daemon not reachable". committed is always true here
    // (we returned early on failure above) but the explicit guard is kept for
    // clarity and future robustness.
    if (committed && tokenEntry) {
      const daemonOk = checkDaemonHealth(
        hermesHost,
        hermesPort,
        tokenEntry.token,
        hermesResolvedAllowInsecureHttp,
      );
      if (daemonOk) {
        notes.push("Daemon health check: OK");
      } else {
        notes.push(
          `Daemon not reachable at ${hermesHost}:${hermesPort} — start with: remnic daemon start`,
        );
      }
    }

    const suffix = notes.length > 0 ? `\n  ${notes.join("\n  ")}` : "";
    return {
      connectorId: options.connectorId,
      status: "installed",
      configPath,
      message: `Installed ${manifest.name} v${manifest.version}${suffix}`,
    };
  }

  // ── Non-Hermes connectors: write connector.json ───────────────────────────
  // Write with owner-only permissions because the JSON may embed the
  // connector bearer token. Matches the 0o600 hardening on
  // ~/.remnic/tokens.json so the token is never world-readable via this
  // secondary location.

  // Codex CLI: also drop the phase-2 memory extension unless the caller
  // explicitly opted out via `config.installExtension: false`.
  let extensionMessage = "";
  // Explicit structured flag for the config-write rollback gate. This MUST
  // stay decoupled from `extensionMessage` because that string embeds the
  // install path — substring-matching on "skipped" would misfire whenever
  // the codex home happens to contain the word "skipped".
  let extensionInstalled = false;
  // Holds the commit/rollback handle returned by installCodexMemoryExtension().
  // The backup of any prior extension is kept alive until commit() is called.
  let extensionHandle: { commit(): void; rollback(): void } | null = null;
  if (options.connectorId === "codex-cli") {
    // Finding 1: coerce string "false"/"true" from CLI config parsing to a real
    // boolean before the gate check, then persist the coerced value so it is
    // stored as a boolean in the config file.
    const coerced = coerceInstallExtension(resolvedConfig.installExtension);
    if (coerced !== undefined) {
      resolvedConfig.installExtension = coerced;
    }
    const shouldInstall = resolvedConfig.installExtension !== false;
    // Persist the effective installExtension boolean explicitly so that
    // removeConnector's provenance check (Finding 3) can match. When the caller
    // did not pass the key, the default is true — write it so later removal
    // knows Remnic owned the install.
    resolvedConfig.installExtension = shouldInstall;
    // Resolve the Codex home path NOW so we can persist the absolute path
    // into the saved config. This guarantees removeConnector can target the
    // exact same directory later even if $CODEX_HOME is unset or changed.
    const codexHomeOverride =
      typeof resolvedConfig.codexHome === "string" && resolvedConfig.codexHome.length > 0
        ? (resolvedConfig.codexHome as string)
        : null;
    const resolvedCodexHome = resolveCodexHome(codexHomeOverride);
    resolvedConfig.codexHome = resolvedCodexHome;

    if (shouldInstall) {
      try {
        const extensionSourceOverride =
          typeof resolvedConfig.extensionSourceDir === "string" &&
          resolvedConfig.extensionSourceDir.length > 0
            ? (resolvedConfig.extensionSourceDir as string)
            : null;
        const extResult = installCodexMemoryExtension({
          codexHome: resolvedCodexHome,
          sourceDir: extensionSourceOverride,
        });
        extensionMessage = ` (memory extension: ${extResult.remnicExtensionDir})`;
        extensionInstalled = true;
        extensionHandle = extResult;
      } catch (err) {
        const errMsg = err instanceof Error ? err.message : "unknown error";
        // Codex P2 (PRRT_kwDORJXyws56Ur_G): generateToken already rotated
        // tokens.json before reaching this point. The extension threw, so no
        // connector.json was written — roll back the token store to the
        // pre-install snapshot so tokens.json and the absent connector.json
        // stay consistent (no orphaned/active token without a matching config).
        //
        // Initialize to false: only set true once saveTokenStore() succeeds.
        // For connectors without requiresToken the rollback block is skipped
        // entirely, so the suffix must remain absent — not "Token has been
        // rolled back." (which would be factually incorrect).
        let extensionErrTokenRolledBack = false;
        let extensionErrTokenRollbackMsg = "";
        if (tokenEntry !== null && nonHermesPriorTokenStore !== null) {
          try {
            saveTokenStore(nonHermesPriorTokenStore);
            extensionErrTokenRolledBack = true;
          } catch (tokenRestoreErr) {
            extensionErrTokenRolledBack = false;
            extensionErrTokenRollbackMsg =
              tokenRestoreErr instanceof Error ? tokenRestoreErr.message : String(tokenRestoreErr);
          }
        }
        // Only include a token-rollback suffix for connectors that have a token
        // to roll back. Non-token connectors (requiresToken !== true) never
        // generated a token entry, so no rollback occurred and the message must
        // not claim otherwise.
        const tokenRollbackSuffix = manifest.requiresToken
          ? extensionErrTokenRolledBack
            ? " Token has been rolled back."
            : ` Token rollback FAILED (${extensionErrTokenRollbackMsg}) — tokens.json may contain an orphaned entry. ` +
              `Manually inspect ~/.remnic/tokens.json and reinstall.`
          : "";
        return {
          connectorId: options.connectorId,
          status: "error",
          message: `Memory extension install failed — ${errMsg}.${tokenRollbackSuffix} Resolve the issue, then reinstall.`,
        };
      }
    } else {
      extensionMessage = " (memory extension: skipped via installExtension=false)";
    }
  }

  // ── WeClone: write proxy config to ~/.remnic/connectors/weclone.json ─────
  //
  // The standalone `remnic-weclone-proxy` CLI (see packages/connector-weclone)
  // reads its config from ~/.remnic/connectors/weclone.json by default so the
  // proxy can start without depending on Remnic's XDG-scoped registry layout.
  // Compose and write that file here, BEFORE the registry connector.json is
  // written, so that a failure in either file's write path rolls back cleanly.
  //
  // Precedence for each field: user-supplied via --config → saved prior proxy
  // config (on --force) → manifest defaults. The generated bearer token (if
  // any) is persisted into remnicAuthToken so the proxy can authenticate with
  // the daemon without a second token lookup at runtime.
  let weCloneProxyHandleRollback: (() => void) | null = null;
  if (options.connectorId === "weclone") {
    try {
      // Force-reinstall (and any reinstall path) must keep using the exact
      // proxy config path that was persisted on the previous install. If we
      // re-derive from the current env each time, a user whose REMNIC_HOME /
      // ENGRAM_HOME changed between installs would end up with two proxy
      // config files — the old one stays with stale settings + a revoked
      // token, the new one gets the live token, and any running proxy still
      // reading the old file starts failing auth. Read the saved
      // `proxyConfigPath` from the existing registry config first, and only
      // fall back to env-derivation for genuine first-time installs.
      let proxyConfigPath: string | null = null;
      if (existing && fs.existsSync(configPath)) {
        try {
          const savedRegistryConfig = JSON.parse(fs.readFileSync(configPath, "utf8")) as Record<string, unknown>;
          if (
            typeof savedRegistryConfig.proxyConfigPath === "string" &&
            savedRegistryConfig.proxyConfigPath.length > 0
          ) {
            proxyConfigPath = savedRegistryConfig.proxyConfigPath;
          }
        } catch {
          // Saved registry config unreadable — fall through to env resolution.
        }
      }
      if (proxyConfigPath === null) {
        proxyConfigPath = resolveWeCloneProxyConfigPath();
      }
      const prior = readWeCloneProxyConfigIfExists(proxyConfigPath);
      const proxyConfig = buildWeCloneProxyConfig({
        userConfig: safeUserConfig,
        priorConfig: prior ? safeParseJson(prior) : null,
        authToken: tokenEntry?.token,
      });
      fs.mkdirSync(path.dirname(proxyConfigPath), { recursive: true });
      // Install the rollback closure BEFORE the write starts. `writeSecretFileSync`
      // opens the file in truncate mode, so a mid-write failure (ENOSPC, EPERM)
      // could leave `weclone.json` empty. Creating the rollback now guarantees
      // we can always restore prior content (or delete a newly-created file)
      // even if the write itself throws.
      weCloneProxyHandleRollback = () => {
        try {
          if (prior === null) {
            // File was created (or would have been created) by this install —
            // delete whatever is left behind, if anything.
            if (fs.existsSync(proxyConfigPath)) {
              fs.unlinkSync(proxyConfigPath);
            }
          } else {
            writeSecretFileSync(proxyConfigPath, prior);
          }
        } catch {
          // Best-effort rollback.
        }
      };
      try {
        writeSecretFileSync(
          proxyConfigPath,
          JSON.stringify(proxyConfig, null, 2),
        );
      } catch (writeErr) {
        // Truncate-and-write failed partway through — restore the file (or
        // remove the empty partial) and re-throw so the outer catch drives
        // the structured error response + token rollback.
        try {
          weCloneProxyHandleRollback();
        } catch {
          // Best-effort.
        }
        weCloneProxyHandleRollback = null;
        throw writeErr;
      }
      // Record the proxy-side config path on the registry JSON so operators
      // and `remnic connectors doctor weclone` can locate it later. Persist the
      // effective proxy port so `remnic connectors list` reflects the resolved
      // value rather than whatever (possibly missing) the user supplied.
      resolvedConfig.proxyConfigPath = proxyConfigPath;
      resolvedConfig.proxyPort = proxyConfig.proxyPort;
      resolvedConfig.wecloneApiUrl = proxyConfig.wecloneApiUrl;
      resolvedConfig.remnicDaemonUrl = proxyConfig.remnicDaemonUrl;
      resolvedConfig.sessionStrategy = proxyConfig.sessionStrategy;
    } catch (weCloneErr) {
      // Track token rollback success/failure explicitly so the error message
      // can truthfully report whether tokens.json was restored or is in a
      // potentially-inconsistent state. Mirrors the care taken in the
      // registry-config-write failure handler below.
      let tokenRolledBack = false;
      let tokenRollbackMsg = "";
      if (tokenEntry !== null && nonHermesPriorTokenStore !== null) {
        try {
          saveTokenStore(nonHermesPriorTokenStore);
          tokenRolledBack = true;
        } catch (tokenRestoreErr) {
          tokenRolledBack = false;
          tokenRollbackMsg =
            tokenRestoreErr instanceof Error ? tokenRestoreErr.message : String(tokenRestoreErr);
        }
      }
      const tokenSuffix = manifest.requiresToken && tokenEntry !== null
        ? tokenRolledBack
          ? " Token has been rolled back."
          : ` Token rollback FAILED (${tokenRollbackMsg}) — tokens.json may contain an orphaned entry. ` +
            `Manually inspect ~/.remnic/tokens.json and reinstall.`
        : "";
      return {
        connectorId: options.connectorId,
        status: "error",
        message:
          `WeClone install aborted: proxy config write failed — ` +
          `${weCloneErr instanceof Error ? weCloneErr.message : String(weCloneErr)}.` +
          `${tokenSuffix} Resolve the write permission issue on ~/.remnic/connectors/, then reinstall.`,
      };
    }
  }

  // ── Droid: write remnic MCP server entry to ~/.factory/mcp.json ──────────
  let droidMcpRollback: (() => void) | null = null;
  if (options.connectorId === "droid") {
    const stepResult = droidInstallStep(
      tokenEntry?.token,
      resolvedConfig,
      manifest.requiresToken ?? false,
      tokenEntry,
      nonHermesPriorTokenStore,
      saveTokenStore,
    );
    if (!stepResult.ok) {
      return { connectorId: options.connectorId, status: "error", message: stepResult.errorMessage };
    }
    droidMcpRollback = stepResult.rollback;
    resolvedConfig.factoryMcpPath = stepResult.mcpPath;
  }

  // Finding 5: strip internal/test-only keys that must never be persisted to
  // the config file. These keys are used at install time only (e.g. to inject
  // a synthetic extension source dir in tests) and have no meaning on disk.
  // Denylist — add any future test-only keys here with a comment.
  const INTERNAL_KEYS_DENYLIST = [
    "extensionSourceDir", // test-only override for the plugin-codex source path
  ];
  for (const key of INTERNAL_KEYS_DENYLIST) {
    delete resolvedConfig[key];
  }

  // Atomic rollback (UXJG / Codex P1): if the JSON write fails (e.g., permission
  // denied on XDG_CONFIG_HOME), generateToken() above already rotated the token in
  // tokens.json. Roll back via the full-store snapshot captured before generateToken
  // so tokens.json and the absent connector.json stay consistent — no stale token
  // lingers without a matching config file. Full-store restore (vs. single-entry
  // restore/revoke) handles partial writes atomically for both fresh-install and
  // force-reinstall paths uniformly.
  //
  // Also roll back any codex-cli memory extension if the config write fails so
  // that no dangling memories_extensions/remnic directory is left with no config
  // provenance for removeConnector to find and clean up later.
  try {
    writeSecretFileSync(configPath, JSON.stringify(resolvedConfig, null, 2));
  } catch (writeErr) {
    // Roll back non-hermes token store if needed. Track success so we can
    // report accurately — unconditionally claiming rollback succeeded when it
    // silently failed would leave operators unable to diagnose inconsistent state.
    //
    // Initialize to false: only set true once saveTokenStore() succeeds.
    // Non-token connectors skip this block entirely, so we must not emit a
    // "Token has been rolled back." suffix for them.
    let configWriteTokenRolledBack = false;
    let configWriteTokenRollbackMsg = "";
    if (tokenEntry !== null && nonHermesPriorTokenStore !== null) {
      try {
        saveTokenStore(nonHermesPriorTokenStore);
        configWriteTokenRolledBack = true;
      } catch (tokenRestoreErr) {
        configWriteTokenRolledBack = false;
        configWriteTokenRollbackMsg =
          tokenRestoreErr instanceof Error ? tokenRestoreErr.message : String(tokenRestoreErr);
      }
    }
    // Roll back the codex-cli extension if it was installed.
    // Use extensionHandle.rollback() so that a pre-existing (possibly
    // customised) extension is restored from the backup kept by
    // installCodexMemoryExtension(), rather than unconditionally deleted.
    if (extensionInstalled && extensionHandle !== null) {
      try {
        extensionHandle.rollback();
      } catch {
        // Best-effort rollback: log but don't mask the original write error.
        console.warn(
          "[remnic/connectors] installConnector: config write failed and extension rollback also failed — " +
            "manual cleanup of memories_extensions/remnic may be required.",
        );
      }
    }
    // Roll back the WeClone proxy config if it was written.
    if (weCloneProxyHandleRollback !== null) {
      try {
        weCloneProxyHandleRollback();
      } catch {
        // Best-effort rollback.
      }
    }
    // Roll back the Droid ~/.factory/mcp.json if it was written.
    if (droidMcpRollback !== null) {
      try {
        droidMcpRollback();
      } catch {
        // Best-effort rollback.
      }
    }
    // Only include a token-rollback suffix for connectors that actually had a
    // token to roll back. Non-token connectors (requiresToken !== true) never
    // generated a token entry. For requiresToken connectors where generateToken
    // threw (tokenEntry === null), no token was written to tokens.json so no
    // rollback occurred — avoid a misleading "Token rollback FAILED" message
    // (Thread 1, PRRT_kwDORJXyws56VVnB).
    const configWriteTokenSuffix = manifest.requiresToken && tokenEntry !== null
      ? configWriteTokenRolledBack
        ? " Token has been rolled back."
        : ` Token rollback FAILED (${configWriteTokenRollbackMsg}) — tokens.json may contain an orphaned entry. ` +
          `Manually inspect ~/.remnic/tokens.json and reinstall.`
      : "";
    return {
      connectorId: options.connectorId,
      status: "error",
      message:
        `${manifest.name} install aborted: connector config write failed — ` +
        `${writeErr instanceof Error ? writeErr.message : String(writeErr)}.` +
        `${configWriteTokenSuffix} Resolve the write permission issue, then reinstall.`,
    };
  }

  // Config write succeeded — permanently drop the backup of the prior extension.
  if (extensionInstalled && extensionHandle !== null) {
    extensionHandle.commit();
  }

  return {
    connectorId: options.connectorId,
    status: "installed",
    configPath,
    message: `Installed ${manifest.name} v${manifest.version}${extensionMessage}`,
  };
}

// ── Remove connector ───────────────────────────────────────────────────────

export function removeConnector(connectorId: string): RemoveResult {
  const configDir = getConnectorsDir();
  if (!isValidConnectorId(connectorId)) {
    return {
      connectorId,
      configPath: configDir,
      status: "skipped",
      reason: "invalid-connector-id",
      message:
        `Removal aborted: invalid connector ID ${JSON.stringify(connectorId)}. ` +
        "Connector IDs must match [A-Za-z0-9][A-Za-z0-9._-]*.",
    };
  }
  const configPath = path.join(configDir, `${connectorId}.json`);

  // For codex-cli, read the saved config BEFORE touching anything so we have
  // both the persisted codexHome and the installExtension flag available for
  // later use in extension removal (Findings 1, 3, 4, 5).
  let codexHomeOverride: string | null = null;
  let savedInstallExtension: boolean | undefined = undefined;
  // Finding 1: track whether config parsing succeeded. If parsing throws, we
  // cannot trust any metadata and must fail closed (skip extension removal).
  let configParsed = false;
  if (connectorId === "codex-cli" && fs.existsSync(configPath)) {
    try {
      const parsed = JSON.parse(fs.readFileSync(configPath, "utf8")) as Record<string, unknown>;
      configParsed = true;
      if (typeof parsed.codexHome === "string" && parsed.codexHome.length > 0) {
        codexHomeOverride = parsed.codexHome;
      }
      // Finding 4: coerce saved installExtension so string "false" still works.
      const coerced = coerceInstallExtension(parsed.installExtension);
      if (coerced !== undefined) {
        savedInstallExtension = coerced;
      }
    } catch {
      // Finding 1: config is malformed — log debug and fail closed.
      // codexHomeOverride and savedInstallExtension remain unset; configParsed
      // stays false so extension removal is skipped below.
      console.debug(
        "[remnic/connectors] removeConnector: codex-cli.json parse failed — skipping extension removal to avoid touching unverified paths",
      );
    }
  }

  // For hermes, read the shim and config.yaml paths persisted at install time
  // BEFORE the connector JSON is deleted, so removal targets the files written
  // under the HERMES_HOME that was active during install (Codex P2 on PR #1938).
  let savedHermesShimPath: string | null = null;
  let savedHermesConfigPath: string | null = null;
  const savedPriorHermesConfigPaths: string[] = [];
  const savedPriorHermesShimPaths: string[] = [];
  if (connectorId === "hermes" && fs.existsSync(configPath)) {
    try {
      const parsedRaw: unknown = JSON.parse(fs.readFileSync(configPath, "utf8"));
      // A syntactically valid but non-object payload ([], null, "x", 5) is as
      // untrustworthy as unparseable JSON — fail closed like the catch below
      // (Codex P2 on PR #1938, round 10). A plain object that merely LACKS
      // provenance fields is a legitimate pre-#1929 install and must still be
      // removable (cleanup then uses the environment-resolved paths).
      if (parsedRaw === null || typeof parsedRaw !== "object" || Array.isArray(parsedRaw)) {
        throw new Error("hermes.json is not a JSON object");
      }
      const parsed = parsedRaw as Record<string, unknown>;
      if (typeof parsed.pluginShimPath === "string" && parsed.pluginShimPath.length > 0) {
        savedHermesShimPath = parsed.pluginShimPath;
      }
      // Prior-shim provenance (round 18): shims whose cleanup failed on an
      // earlier install move remain tracked here.
      if (Array.isArray(parsed.priorPluginShimPaths)) {
        for (const entry of parsed.priorPluginShimPaths) {
          if (typeof entry === "string" && entry.length > 0) {
            savedPriorHermesShimPaths.push(entry);
          }
        }
      }
      if (typeof parsed.hermesConfigPath === "string" && parsed.hermesConfigPath.length > 0) {
        savedHermesConfigPath = parsed.hermesConfigPath;
      }
      // Array provenance (round 13) plus the legacy single-path key from
      // earlier builds of this branch.
      if (Array.isArray(parsed.priorHermesConfigPaths)) {
        for (const entry of parsed.priorHermesConfigPaths) {
          if (typeof entry === "string" && entry.length > 0) {
            savedPriorHermesConfigPaths.push(entry);
          }
        }
      }
      if (typeof parsed.priorHermesConfigPath === "string" && parsed.priorHermesConfigPath.length > 0) {
        savedPriorHermesConfigPaths.push(parsed.priorHermesConfigPath);
      }
    } catch {
      // Fail closed, mirroring the codex-cli provenance guard: a malformed
      // hermes.json is the only record of the install-time shim location.
      // Proceeding would delete the registry entry while a Remnic-generated
      // shim under a since-changed HERMES_HOME stays discoverable forever
      // (Codex P2 on PR #1938).
      return {
        connectorId,
        configPath,
        status: "error",
        message:
          `Removal aborted: ${configPath} is malformed and cannot be parsed. ` +
          `It records where the Hermes plugin shim was installed; removing the connector without it ` +
          `could orphan the shim. Fix or delete the file (and remove any ` +
          `plugins/remnic/__init__.py under your Hermes home manually), then re-run removal.`,
      };
    }
  }

  if (!fs.existsSync(configPath)) {
    // Best-effort: revoke any orphan token that may have survived a prior partial
    // cleanup (e.g. connector JSON deleted manually or XDG_CONFIG_HOME change).
    // This prevents a stale bearer token from remaining valid in tokens.json while
    // the connector appears "not installed" to the caller.
    // Config file is missing — we have no evidence that this installation ever
    // managed the extension directory, so it is unsafe to remove it (the user
    // may have self-managed it or installed with installExtension=false).
    // Skip removeCodexMemoryExtension entirely in this recovery path.
    let staleTokenRevoked = false;
    try {
      staleTokenRevoked = revokeToken(connectorId);
    } catch {
      // Best-effort: token store may be missing or read-only; do not mask the
      // not_found signal to the caller.
    }
    const message = staleTokenRevoked
      ? `${connectorId} is not installed. Removed stale token entry for ${connectorId}.`
      : "Not installed";
    return {
      connectorId,
      configPath,
      status: "not_found",
      message,
    };
  }

  // Read connector config before deleting it (needed for hermes profile lookup)
  let storedProfile = "default";
  if (connectorId === "hermes") {
    try {
      const stored = JSON.parse(fs.readFileSync(configPath, "utf8"));
      if (typeof stored?.profile === "string") storedProfile = stored.profile;
    } catch {
      // use default profile
    }
  }

  // For weclone, read the persisted proxy config path from the saved registry
  // config BEFORE deleting it. Using the persisted absolute path (rather than
  // recomputing from current REMNIC_HOME / ENGRAM_HOME / $HOME) guarantees
  // that a remove still targets the original file even if the environment
  // has changed between install and remove.
  //
  // Parse failure handling: if the registry config exists but is malformed,
  // we MUST abort the whole removal (mirror of the codex-cli provenance
  // gate). Silently falling back to an env-derived path would delete the
  // registry entry first and then miss the real proxy config if the
  // environment had since changed, orphaning the file (which may still hold
  // a live bearer token). Only install-time WRITES persist the path; if we
  // lost it on read, the only safe action is to stop and let the operator
  // fix the config or clean up manually.
  let weCloneProxyConfigPath: string | null = null;
  let weCloneRegistryParseFailed = false;
  if (connectorId === "weclone") {
    try {
      const stored = JSON.parse(fs.readFileSync(configPath, "utf8")) as Record<string, unknown>;
      if (typeof stored.proxyConfigPath === "string" && stored.proxyConfigPath.length > 0) {
        weCloneProxyConfigPath = stored.proxyConfigPath;
      }
    } catch {
      weCloneRegistryParseFailed = true;
    }
    // No persisted path AND parse succeeded means this is a legacy install
    // pre-dating proxyConfigPath provenance. Fall back to env resolution
    // only in that specific case so we still make a best-effort cleanup.
    if (weCloneProxyConfigPath === null && !weCloneRegistryParseFailed) {
      try {
        weCloneProxyConfigPath = resolveWeCloneProxyConfigPath();
      } catch {
        // Resolution failed (e.g. no HOME) — leave null; cleanup block skips.
      }
    }
  }

  // For droid, read the persisted factoryMcpPath before deleting the config.
  let droidMcpConfigPath: string | null = null;
  let droidRegistryParseFailed = false;
  if (connectorId === "droid") {
    const prov = readDroidMcpProvenance(configPath);
    droidMcpConfigPath = prov.mcpConfigPath;
    droidRegistryParseFailed = prov.registryParseFailed;
  }
  if (connectorId === "droid" && droidRegistryParseFailed) {
    console.warn(`[remnic/connectors] removeConnector: droid.json malformed — aborting. Fix or delete ${configPath} manually and retry.`);
    return { connectorId, configPath, message: "Removal aborted: droid.json is malformed. Registry config left in place.", status: "skipped", reason: "config-parse-failed" };
  }

  if (connectorId === "weclone" && weCloneRegistryParseFailed) {
    console.warn(
      "[remnic/connectors] removeConnector: weclone.json is malformed — " +
        "aborting removal to preserve provenance. Fix or delete " +
        configPath +
        " manually and retry.",
    );
    return {
      connectorId,
      configPath,
      message:
        "Removal aborted: weclone.json is malformed. Registry config left in place for inspection; " +
        "proxy config NOT removed.",
      status: "skipped",
      reason: "config-parse-failed",
    };
  }

  // Finding 4: if the codex-cli config exists but failed to parse, abort the
  // entire removal. Leave both the config file AND the extension directory
  // untouched so the operator can inspect/fix the config file and retry.
  // Unlinking the config here would destroy the only provenance record and make
  // deterministic retry impossible.
  if (connectorId === "codex-cli" && fs.existsSync(configPath) && !configParsed) {
    console.warn(
      "[remnic/connectors] removeConnector: codex-cli.json is malformed — " +
        "aborting removal to preserve provenance. Fix or delete " +
        configPath +
        " manually and retry.",
    );
    return {
      connectorId,
      configPath,
      message: "Removal aborted: codex-cli.json is malformed. Config file left in place for inspection.",
      status: "skipped",
      reason: "config-parse-failed",
    };
  }

  // Finding 5: remove extension BEFORE deleting the config file. If extension
  // removal throws (e.g. EPERM/EBUSY), we re-throw WITHOUT deleting the config
  // so the user can retry — the config still has the persisted codexHome needed
  // to locate the extension directory.
  let extensionMessage = "";
  if (connectorId === "codex-cli") {
    // Finding 4: skip extension deletion when installExtension was explicitly disabled.
    if (savedInstallExtension === false) {
      extensionMessage = " (memory extension: skipped — installExtension=false)";
    // Finding 3: require EXPLICIT provenance (installExtension===true AND a saved
    // codexHome) before removing the extension. Legacy configs that pre-date this
    // feature have no installExtension key, so savedInstallExtension is undefined;
    // without provenance we cannot be sure Remnic ever owned the directory.
    } else if (savedInstallExtension !== true || codexHomeOverride === null) {
      extensionMessage = " (memory extension: skipped — no install provenance in saved config)";
    } else {
      const extResult = removeCodexMemoryExtension({ codexHome: codexHomeOverride });
      extensionMessage = extResult.removed
        ? ` (memory extension removed: ${extResult.remnicExtensionDir})`
        : " (no memory extension present)";
    }
  }

  // Hermes-specific preflight (Codex P2 on PR #1938, round 15): verify every
  // remnic:-bearing config target is writable BEFORE any destructive step.
  // The registry unlink and token revocation must precede the actual yaml
  // cleanup (the unlink-failure contract keeps the install fully functional),
  // but once the registry is gone a cleanup failure would strand the old
  // home's block with no provenance for a retry — so refuse up front while
  // the registry, provenance, and token are all still intact.
  if (connectorId === "hermes") {
    const preflightCandidates: string[] = [];
    try {
      preflightCandidates.push(...hermesConfigCleanupPaths(storedProfile));
    } catch {
      /* current-environment resolution failed — persisted paths still checked */
    }
    // Persisted provenance is filtered through the SAME guard cleanup uses
    // (Bugbot on PR #1938, round 17): a tampered/implausible path that
    // removeHermesConfig would never touch must not be able to block removal.
    if (savedHermesConfigPath !== null && isPlausibleHermesConfigPath(savedHermesConfigPath)) {
      preflightCandidates.push(savedHermesConfigPath);
    }
    preflightCandidates.push(...savedPriorHermesConfigPaths.filter(isPlausibleHermesConfigPath));
    // De-duplicate by resolved file identity first (matching cleanup): in the
    // legacy alias layout profiles/default/config.yaml symlinks to the root
    // config — the alias collapses onto its non-symlinked representative and
    // must not trip the component guard below.
    const uniqueCandidates: string[] = [];
    for (const candidate of preflightCandidates) {
      if (!uniqueCandidates.some((kept) => sameHermesConfigTarget(kept, candidate))) {
        uniqueCandidates.push(candidate);
      }
    }
    const blocked: string[] = [];
    for (const candidate of uniqueCandidates) {
      let needsCleanup = false;
      try {
        needsCleanup = /^remnic:/m.test(fs.readFileSync(candidate, "utf8"));
      } catch {
        needsCleanup = false; // missing/unreadable — cleanup will skip it
      }
      if (!needsCleanup) {
        continue;
      }
      // Cleanup refuses symlinked components (round 19); a target that would
      // be skipped that way must abort HERE, while registry/provenance/token
      // are intact, instead of surfacing as a post-unlink note that strands
      // the block without provenance (Codex P2 on PR #1938, round 22).
      try {
        assertConfigComponentsNotSymlinked(candidate);
      } catch {
        blocked.push(`${candidate} (symlinked path component)`);
        continue;
      }
      try {
        // writeSecretFileSync rewrites via temp file + rename, so BOTH the
        // file and its directory must be writable.
        fs.accessSync(candidate, fs.constants.W_OK);
        fs.accessSync(path.dirname(candidate), fs.constants.W_OK);
      } catch {
        blocked.push(`${candidate} (not writable)`);
      }
    }
    if (blocked.length > 0) {
      return {
        connectorId,
        configPath,
        status: "error",
        message:
          `Hermes remove aborted: the following config.yaml path(s) hold a remnic: block but cannot be cleaned: ` +
          `${blocked.join(", ")}. The connector registry entry, provenance, and token were left untouched — ` +
          `fix the permissions or resolve the symlink and re-run removal.`,
      };
    }
  }

  // Delete the connector config file AFTER extension removal (Finding 5): if
  // extension removal throws, we do not reach here and the config is preserved.
  // Token revocation and YAML cleanup only happen after the file is gone so
  // that a failed unlink (e.g., read-only directory) does not leave a
  // token-less orphan install on disk.
  try {
    fs.unlinkSync(configPath);
  } catch (unlinkErr) {
    const sanitizedErr = unlinkErr instanceof Error ? unlinkErr.message : String(unlinkErr);
    return {
      connectorId,
      configPath,
      status: "error",
      message:
        `${connectorId} remove aborted: could not delete connector file (${sanitizedErr}). ` +
        `Token and any connector-specific state were not modified.`,
    };
  }

  // File removed — now safe to revoke the auth token.
  // Non-fatal: if the token store is read-only or missing, connector removal
  // should still succeed. Stale tokens will be rejected by the daemon when the
  // token file is later accessible.
  const notes: string[] = [];
  // Track revocation success so downstream error branches (e.g. weclone
  // proxy-delete failure) can accurately report whether the token was
  // cleaned up rather than hardcoding "Token has been rolled back".
  let tokenRevoked = true;
  try {
    revokeToken(connectorId);
  } catch (revokeErr) {
    // Surface the failure so callers know the token was not cleaned up.
    // The connector config has already been removed at this point.
    tokenRevoked = false;
    const revokeMsg = revokeErr instanceof Error ? revokeErr.message : String(revokeErr);
    notes.push(`Warning: token revocation failed — ${revokeMsg}. The token for ${connectorId} may still be present in tokens.json.`);
  }

  // WeClone-specific: remove the proxy config file at the path persisted in
  // the registry config (read above before the registry file was deleted).
  // Using the persisted absolute path — not a re-derivation from the current
  // environment — is load-bearing: if REMNIC_HOME / ENGRAM_HOME changes (or
  // is unset) between install and remove, recomputing here would leave the
  // original proxy config (with a live bearer token) on disk while reporting
  // success. If the file is present but unlink fails (e.g. EPERM), we MUST
  // surface an error status rather than pretending success — a later retry
  // via `remnic connectors remove weclone` would go down the `not_found`
  // path because the registry config was already unlinked, leaving the
  // proxy config orphaned (potentially with a still-valid token).
  let weCloneProxyDeleteFailed: string | null = null;
  if (connectorId === "weclone") {
    if (weCloneProxyConfigPath === null) {
      notes.push(
        "WeClone proxy config cleanup skipped: no persisted path found in saved config " +
          "(likely a legacy install predating proxyConfigPath provenance).",
      );
    } else {
      // Safety gate: validate the persisted path before unlinking. Because
      // `weCloneProxyConfigPath` is loaded from user-controlled JSON, a
      // malformed or tampered weclone.json could make `removeConnector` delete
      // an arbitrary file. Restrict deletion to paths that are:
      //   1. Absolute (relative paths are CWD-dependent and were never written
      //      by the installer).
      //   2. End with the known suffix "connectors/weclone.json" — the only
      //      filename the installer ever writes, regardless of base directory.
      // If either check fails, skip the unlink and surface an error so the
      // operator can clean up manually. Failing closed is safer than silently
      // deleting an unexpected path.
      const expectedSuffix = path.join("connectors", "weclone.json");
      const isSafePath =
        path.isAbsolute(weCloneProxyConfigPath) &&
        weCloneProxyConfigPath.endsWith(expectedSuffix);
      if (!isSafePath) {
        weCloneProxyDeleteFailed =
          `Proxy config path ${JSON.stringify(weCloneProxyConfigPath)} failed safety validation ` +
          `(must be absolute and end with "${expectedSuffix}"). ` +
          `Refusing to delete — remove the file manually if it exists.`;
      } else {
        try {
          if (fs.existsSync(weCloneProxyConfigPath)) {
            fs.unlinkSync(weCloneProxyConfigPath);
            notes.push(`Removed WeClone proxy config: ${weCloneProxyConfigPath}`);
          }
        } catch (err) {
          // Hard failure: leaving the file behind with a live token is a
          // security issue. Capture the error so we return status:"error".
          weCloneProxyDeleteFailed = err instanceof Error ? err.message : String(err);
        }
      }
    }
  }
  if (weCloneProxyDeleteFailed !== null && weCloneProxyConfigPath !== null) {
    // Report the token-revocation status truthfully. If revocation already
    // failed above, claiming the token was "cleaned up" here would mislead
    // the operator into thinking the only action left is deleting the
    // orphan file — when in reality the bearer token is also still live.
    const tokenStatus = tokenRevoked
      ? "the registry config was deleted and the token was revoked"
      : "the registry config was deleted but TOKEN REVOCATION ALSO FAILED — " +
        "inspect ~/.remnic/tokens.json and revoke manually";
    return {
      connectorId,
      configPath,
      status: "error",
      message:
        `WeClone remove partially succeeded: ${tokenStatus}, ` +
        `but the proxy config at ${weCloneProxyConfigPath} could not be deleted ` +
        `(${weCloneProxyDeleteFailed}). Manually remove that file — it may still contain ` +
        `a Remnic daemon bearer token.`,
    };
  }

  // Droid-specific: remove the "remnic" entry from ~/.factory/mcp.json.
  let droidMcpDeleteFailed: string | null = null;
  if (connectorId === "droid") {
    if (droidMcpConfigPath === null) {
      notes.push("Droid MCP config cleanup skipped: no persisted path found (legacy install).");
    } else {
      try { const note = removeDroidMcpEntryImpl(droidMcpConfigPath); if (note) notes.push(note); }
      catch (err) { droidMcpDeleteFailed = err instanceof Error ? err.message : String(err); }
    }
  }
  if (droidMcpDeleteFailed !== null && droidMcpConfigPath !== null) {
    const ts = tokenRevoked ? "token was revoked" : "TOKEN REVOCATION ALSO FAILED — inspect ~/.remnic/tokens.json and revoke manually";
    return { connectorId, configPath, status: "error", message: `Droid remove partially succeeded: registry config deleted, ${ts}, but the MCP config at ${droidMcpConfigPath} could not be updated (${droidMcpDeleteFailed}). Manually remove the "remnic" entry.` };
  }

  // Hermes-specific: strip the remnic: block from config.yaml (the writability
  // preflight above already verified every remnic:-bearing target, so a
  // partial failure here is a rare TOCTOU race — the error branch below stays
  // as the backstop).
  if (connectorId === "hermes") {
    // Remove the Hermes plugin-directory shim (Issue #1929) FIRST — it is
    // independent of config.yaml cleanup, and the yaml partial-failure branch
    // below returns early. Running the shim cleanup after that return would
    // leave a Remnic-generated shim discoverable while the registry entry and
    // token are already gone (Bugbot on PR #1938, round 5). removeHermesShim
    // deletes candidates ONLY when they carry our generated marker, then
    // rmdir's the now-empty plugins/remnic/ dir. Never rm -rf; never touch a
    // user-authored __init__.py. Candidates: the path persisted at install
    // time plus the path resolved from the current environment, so a
    // HERMES_HOME change between install and remove cannot orphan the shim.
    // Best-effort: a failure here never aborts remove.
    try {
      const shimCandidates: string[] = [];
      if (savedHermesShimPath !== null) {
        shimCandidates.push(savedHermesShimPath);
      }
      shimCandidates.push(...savedPriorHermesShimPaths);
      try {
        shimCandidates.push(hermesShimPath());
      } catch {
        /* HERMES_HOME unresolved in the current environment — persisted path only */
      }
      const shimResult = removeHermesShim(shimCandidates);
      if (shimResult.notes.length > 0) {
        notes.push(shimResult.notes.join("; "));
      }
    } catch (shimErr) {
      notes.push(
        `Hermes plugin shim cleanup skipped: ${shimErr instanceof Error ? shimErr.message : String(shimErr)}`,
      );
    }

    try {
      const yamlResult = removeHermesConfig({
        profile: storedProfile,
        extraConfigPaths: [
          ...(savedHermesConfigPath !== null ? [savedHermesConfigPath] : []),
          ...savedPriorHermesConfigPaths,
        ],
      });
      if (yamlResult.updated) {
        notes.push(`Removed remnic: block from Hermes config: ${yamlResult.configPath}`);
      } else if (yamlResult.reason?.startsWith("Hermes config cleanup partially failed:")) {
        const tokenStatus = tokenRevoked
          ? "the connector registry config was deleted and the token was revoked"
          : "the connector registry config was deleted but TOKEN REVOCATION ALSO FAILED — " +
            "inspect ~/.remnic/tokens.json and revoke manually";
        const shimSuffix = notes.length > 0 ? ` Completed cleanup: ${notes.join("; ")}.` : "";
        return {
          connectorId,
          configPath,
          status: "error",
          message:
            `Hermes remove partially succeeded: ${tokenStatus}, but ${yamlResult.reason}. ` +
            `Updated paths: ${yamlResult.configPath}. Manually remove any stale remnic: ` +
            `block and token material from the failed Hermes config path.` +
            shimSuffix,
        };
      } else if (yamlResult.skipped) {
        notes.push(`Hermes config cleanup skipped: ${yamlResult.reason}`);
      }
    } catch (err) {
      notes.push(
        `Hermes config cleanup skipped: ${err instanceof Error ? err.message : String(err)}`,
      );
    }
  }

  const suffix = notes.length > 0 ? `\n  ${notes.join("\n  ")}` : "";
  return {
    connectorId,
    configPath,
    status: "removed",
    message: `Removed${extensionMessage}${suffix}`,
  };
}

// ── Hermes config.yaml helpers ─────────────────────────────────────────────────

interface HermesConfigResult {
  updated: boolean;
  skipped: boolean;
  reason?: string;
  configPath: string;
  /**
   * The exact byte-for-byte content of the config.yaml that existed BEFORE
   * this upsert ran. `null` when the file did not exist (new file was created).
   * `undefined` when the write was skipped (priorContent is irrelevant).
   * Used by installConnector to roll back the YAML write if commitTokenEntry
   * subsequently throws.
   */
  priorContent?: string | null;
}

/**
 * Validate and sanitize a Hermes profile name.
 *
 * Profile names appear as a path segment under `~/.hermes/profiles/`, so we
 * must reject any value that could traverse outside that directory. Hermes
 * itself restricts profile names to filesystem-safe identifiers; we mirror
 * that convention and additionally require the resolved config path to stay
 * under the profiles root.
 *
 * Throws on invalid input rather than silently normalizing — the caller
 * should surface the error so the user can supply a valid profile.
 */
function sanitizeHermesProfile(profile: string): string {
  if (typeof profile !== "string" || profile.length === 0) {
    throw new Error("Hermes profile name must be a non-empty string");
  }
  // Disallow anything that isn't a plain profile identifier. We accept
  // letters, digits, hyphen, underscore, and dot — but reject leading dots
  // (hidden dirs) and any path separator or parent-dir reference.
  if (!/^[A-Za-z0-9][A-Za-z0-9._-]*$/.test(profile)) {
    throw new Error(
      `Invalid Hermes profile name: ${JSON.stringify(profile)} — must match [A-Za-z0-9][A-Za-z0-9._-]*`,
    );
  }
  if (profile.includes("..")) {
    throw new Error(`Invalid Hermes profile name: ${JSON.stringify(profile)} — must not contain ".."`);
  }
  return profile;
}

function hermesConfigPath(profile: string): string {
  const safeProfile = sanitizeHermesProfile(profile);
  // Root at the SAME Hermes home the shim uses (honors HERMES_HOME, and the
  // platform-native default). Upstream get_hermes_home() reads HERMES_HOME and
  // the config loader resolves config.yaml relative to it, so writing the
  // remnic: block under ~/.hermes while HERMES_HOME points elsewhere would be
  // silently ignored by Hermes (Codex P2 on PR #1938, round 5).
  const hermesRoot = resolveHermesRoot();
  const rootConfigPath = path.join(hermesRoot, "config.yaml");
  const profilesRoot = path.join(hermesRoot, "profiles");
  if (safeProfile === "default") {
    const defaultProfileDir = path.join(profilesRoot, safeProfile);
    if (isFile(rootConfigPath) || (!fs.existsSync(rootConfigPath) && !isDirectory(defaultProfileDir))) {
      return rootConfigPath;
    }
  }
  const cfgPath = path.resolve(profilesRoot, safeProfile, "config.yaml");
  // Defense in depth: ensure the resolved path is still under profilesRoot.
  const rel = path.relative(profilesRoot, cfgPath);
  if (rel.startsWith("..") || path.isAbsolute(rel)) {
    throw new Error(
      `Invalid Hermes profile path: resolved outside ${profilesRoot}`,
    );
  }
  return cfgPath;
}

function isDirectory(filePath: string): boolean {
  try {
    return fs.statSync(filePath).isDirectory();
  } catch {
    return false;
  }
}

function isFile(filePath: string): boolean {
  try {
    return fs.statSync(filePath).isFile();
  } catch {
    return false;
  }
}

function hermesConfigTarget(filePath: string): string {
  try {
    return fs.realpathSync.native(filePath);
  } catch {
    return path.resolve(filePath);
  }
}

function sameHermesConfigTarget(leftPath: string, rightPath: string): boolean {
  return hermesConfigTarget(leftPath) === hermesConfigTarget(rightPath);
}

function hermesDefaultProfileConfigPath(): string {
  return path.join(resolveHermesRoot(), "profiles", "default", "config.yaml");
}

function hermesConfigCleanupPaths(profile: string): string[] {
  const cfgPath = hermesConfigPath(profile);
  const safeProfile = sanitizeHermesProfile(profile);
  if (safeProfile !== "default") {
    return [cfgPath];
  }
  return [...new Set([cfgPath, hermesDefaultProfileConfigPath()])];
}


/**
 * Validate a Hermes host string before interpolating it into YAML.
 *
 * YAML-injection guard: connector config values come from raw CLI input
 * (`--config host=...`) or config-file JSON, both of which are untrusted.
 * Without validation, a value like `127.0.0.1"\n  session_key: "evil`
 * would emit additional YAML keys into the `remnic:` block and silently
 * override Hermes settings.
 *
 * Accepted forms:
 *   - Plain IPv4: 127.0.0.1, 10.0.0.5
 *   - Plain DNS hostname: localhost, foo.example.com
 *   - Bracketed IPv6 literal: [::1], [2001:db8::1]
 *
 * Rejected forms:
 *   - host:port combos: 127.0.0.1:4318 (colons not allowed outside brackets)
 *   - Unbalanced brackets: [::1
 *   - Any whitespace, quotes, or control characters
 *
 * Hermes builds its base URL as `http://{host}:{port}`, so supplying a
 * host that already embeds a port (e.g. "127.0.0.1:4318") would produce
 * the double-port URL "http://127.0.0.1:4318:4318/..." and fail at runtime
 * even though install reports success.  We reject that form here.
 */
function sanitizeHermesHost(host: string): string {
  if (typeof host !== "string" || host.length === 0) {
    throw new Error("Hermes host must be a non-empty string");
  }
  if (host.length > 253) {
    throw new Error(`Hermes host too long (max 253 chars): ${JSON.stringify(host.slice(0, 32))}…`);
  }

  // Bracketed IPv6 literal: must start with "[", end with "]", and contain
  // only hex digits and colons inside the brackets.
  if (host.startsWith("[")) {
    if (!host.endsWith("]")) {
      throw new Error(
        `Invalid Hermes host: ${JSON.stringify(host)} — unbalanced brackets in IPv6 literal`,
      );
    }
    const inner = host.slice(1, -1);
    if (inner.length === 0 || !/^[0-9A-Fa-f:]+$/.test(inner)) {
      throw new Error(
        `Invalid Hermes host: ${JSON.stringify(host)} — bracketed IPv6 literal must contain only hex digits and colons`,
      );
    }
    return host;
  }

  // Unbracketed value: colons are not allowed (would indicate an embedded port
  // or an unbracketed IPv6 address, both of which must be rejected here).
  if (host.includes(":")) {
    throw new Error(
      `Invalid Hermes host: ${JSON.stringify(host)} — host must not include a port; supply the port separately with --config port=<n>`,
    );
  }

  // Plain IPv4 or DNS hostname: allow letters, digits, dots, and hyphens only.
  // No whitespace, quotes, or control characters.
  if (!/^[A-Za-z0-9._\-]+$/.test(host)) {
    throw new Error(
      `Invalid Hermes host: ${JSON.stringify(host)} — must be a plain hostname or IP literal`,
    );
  }
  return host;
}

/**
 * Validate a Hermes port value. Accepts positive integers in [1, 65535].
 *
 * Rejects non-integer numeric strings (e.g. "4318.9") rather than silently
 * truncating them — a fractional port is almost certainly a typo and writing
 * the truncated value to config.yaml would be misleading.
 */
function sanitizeHermesPort(port: number | string): number {
  const numeric = Number(port);
  // Reject NaN, Infinity, -Infinity, and any non-integer (e.g. 4318.9)
  if (!Number.isInteger(numeric)) {
    throw new Error(
      `Invalid Hermes port "${port}": must be a positive integer`,
    );
  }
  if (numeric < 1 || numeric > 65535) {
    throw new Error(`Invalid Hermes port: ${JSON.stringify(port)} — must be an integer in [1, 65535]`);
  }
  return numeric;
}

/**
 * Atomically write a file with owner-only (0o600) permissions.
 *
 * Used for any file that may contain a bearer token. Write to a unique temp file
 * in the destination directory, chmod the temp file, then rename into place so a
 * failed write cannot truncate or corrupt the existing connector config.
 */
function writeSecretFileSync(filePath: string, data: string): void {
  const dir = path.dirname(filePath);
  const base = path.basename(filePath);
  const tmpPath = path.join(
    dir,
    `.${base}.${process.pid}.${Date.now()}.${Math.random().toString(16).slice(2)}.tmp`,
  );
  let wroteTemp = false;
  try {
    fs.writeFileSync(tmpPath, data, { mode: 0o600, flag: "wx" });
    wroteTemp = true;
    try {
      fs.chmodSync(tmpPath, 0o600);
    } catch {
      /* best-effort on non-POSIX filesystems */
    }
    fs.renameSync(tmpPath, filePath);
    try {
      fs.chmodSync(filePath, 0o600);
    } catch {
      /* best-effort on non-POSIX filesystems */
    }
  } catch (err) {
    if (wroteTemp) {
      try {
        fs.unlinkSync(tmpPath);
      } catch {
        /* best-effort temp cleanup */
      }
    }
    throw err;
  }
}

/**
 * Upsert the `remnic:` block in a Hermes profile config.yaml.
 *
 * Rules:
 * - If the profile directory does not exist, skip with a warning (we do not
 *   create arbitrary Hermes state).
 * - If config.yaml does not exist, create it with only the remnic: block.
 * - If config.yaml exists and already contains a `remnic:` block, update the
 *   host/port/token lines in-place (line-based, preserves comments elsewhere).
 * - If config.yaml exists with no `remnic:` block, append one.
 * - Idempotent on repeated calls.
 */
export function upsertHermesConfig(opts: {
  profile: string;
  host: string;
  port: number;
  token: string;
  allowInsecureHttp?: boolean;
}): HermesConfigResult {
  return upsertHermesConfigAt(hermesConfigPath(opts.profile), opts);
}

/**
 * Path-addressed variant of {@link upsertHermesConfig}: writes/updates the
 * `remnic:` block in the config.yaml at `cfgPath`. Used both for the
 * profile-resolved primary config and for refreshing a preserved
 * prior-install config with the active token (PR #1938, round 13).
 */
function upsertHermesConfigAt(
  cfgPath: string,
  opts: { host: string; port: number; token: string; allowInsecureHttp?: boolean },
): HermesConfigResult {
  // Symlinked components below the Hermes root must not redirect the
  // token-bearing write (Codex P1 on PR #1938, round 19).
  assertConfigComponentsNotSymlinked(cfgPath);
  const profileDir = path.dirname(cfgPath);

  // YAML-injection guard: validate scalar values before interpolating them
  // into the `remnic:` block. sanitizeHermesHost/Port throw on anything
  // that could break out of the scalar context.
  const safeHost = sanitizeHermesHost(opts.host);
  const safePort = sanitizeHermesPort(opts.port);
  const allowInsecureHttp = opts.allowInsecureHttp ?? false;
  // Token is generated by randomBytes + a fixed alphabetic prefix, so it's
  // already safe for YAML scalar interpolation. We still guard against an
  // unexpectedly malformed token reaching this function.
  if (!/^[A-Za-z0-9_]+$/.test(opts.token)) {
    throw new Error("Invalid Hermes token: contains non-alphanumeric characters");
  }

  if (!isDirectory(profileDir)) {
    return {
      updated: false,
      skipped: true,
      reason: `Hermes profile directory not found: ${profileDir}`,
      configPath: cfgPath,
    };
  }

  const block = [
    "remnic:",
    `  host: "${safeHost}"`,
    `  port: ${safePort}`,
    `  token: "${opts.token}"`,
    `  allow_insecure_http: ${allowInsecureHttp}`,
  ].join("\n");

  if (!fs.existsSync(cfgPath)) {
    // Create with just the remnic block. 0o600 because the file now holds
    // a bearer token — matching the permissions on ~/.remnic/tokens.json.
    writeSecretFileSync(cfgPath, block + "\n");
    // priorContent: null signals "file was created new" — rollback means delete.
    return { updated: true, skipped: false, configPath: cfgPath, priorContent: null };
  }

  const raw = fs.readFileSync(cfgPath, "utf8");

  // Check whether there's an existing remnic: block
  const hasRemnicBlock = /^remnic:/m.test(raw);

  if (!hasRemnicBlock) {
    // Append the block (preserve existing content)
    const separator = raw.endsWith("\n") ? "\n" : "\n\n";
    writeSecretFileSync(cfgPath, raw + separator + block + "\n");
    // priorContent: raw preserves the original file so it can be restored on rollback.
    return { updated: true, skipped: false, configPath: cfgPath, priorContent: raw };
  }

  // Update the existing block. Strategy: replace the content of the remnic:
  // section by matching from `^remnic:` to the next top-level key or end-of-file.
  // We rewrite only the host/port/token sub-keys inside the block; other keys
  // under remnic: (e.g. session_key, timeout) are preserved.
  //
  // Trailing-newline handling: split("\n") on a file that ends with "\n" produces
  // a final empty-string element. If that element is still inside the remnic block
  // when we hit it, it gets pushed to newLines via the else branch — placing a
  // blank line between existing sub-keys and any newly-appended missing sub-keys.
  // We strip the trailing empty element before the loop and re-add a single "\n"
  // at write time, normalising the file to always end with exactly one newline.
  const splitLines = raw.split("\n");
  // Remove trailing empty element produced by a file that ends with "\n"
  if (splitLines.length > 0 && splitLines[splitLines.length - 1] === "") {
    splitLines.pop();
  }
  const lines = splitLines;
  const newLines: string[] = [];
  let inRemnicBlock = false;
  let blockWritten = false;

  // Track which sub-keys we've emitted
  const written = { host: false, port: false, token: false, allowInsecureHttp: false };

  for (let i = 0; i < lines.length; i++) {
    const line = lines[i];

    if (/^remnic:/.test(line)) {
      inRemnicBlock = true;
      newLines.push(line);
      continue;
    }

    if (inRemnicBlock) {
      // A line that starts with a non-space character and is not empty signals
      // the start of the next top-level YAML key — we've left the remnic block.
      if (line.length > 0 && !/^\s/.test(line)) {
        // Emit any un-written keys before closing the block. Uses the
        // already-validated safeHost/safePort values.
        if (!written.host) newLines.push(`  host: "${safeHost}"`);
        if (!written.port) newLines.push(`  port: ${safePort}`);
        if (!written.token) newLines.push(`  token: "${opts.token}"`);
        if (!written.allowInsecureHttp) newLines.push(`  allow_insecure_http: ${allowInsecureHttp}`);
        blockWritten = true;
        inRemnicBlock = false;
        newLines.push(line);
        continue;
      }

      // Replace managed transport fields and preserve other sub-keys.
      if (/^\s+host:/.test(line)) {
        newLines.push(`  host: "${safeHost}"`);
        written.host = true;
      } else if (/^\s+port:/.test(line)) {
        newLines.push(`  port: ${safePort}`);
        written.port = true;
      } else if (/^\s+token:/.test(line)) {
        newLines.push(`  token: "${opts.token}"`);
        written.token = true;
      } else if (/^\s+allow_insecure_http:/.test(line)) {
        newLines.push(`  allow_insecure_http: ${allowInsecureHttp}`);
        written.allowInsecureHttp = true;
      } else {
        newLines.push(line);
      }
      continue;
    }

    newLines.push(line);
  }

  if (inRemnicBlock && !blockWritten) {
    // File ended while still inside the remnic block
    if (!written.host) newLines.push(`  host: "${safeHost}"`);
    if (!written.port) newLines.push(`  port: ${safePort}`);
    if (!written.token) newLines.push(`  token: "${opts.token}"`);
    if (!written.allowInsecureHttp) newLines.push(`  allow_insecure_http: ${allowInsecureHttp}`);
  }

  // Always write exactly one trailing newline, matching the create and append paths.
  writeSecretFileSync(cfgPath, newLines.join("\n") + "\n");
  // priorContent: raw is the original file content for rollback if needed.
  return { updated: true, skipped: false, configPath: cfgPath, priorContent: raw };
}

/**
 * Remove the `remnic:` block from a Hermes profile config.yaml.
 * Idempotent — if the block is absent, returns skipped.
 *
 * `extraConfigPaths` carries the config.yaml location persisted in the
 * connector JSON at install time, so a HERMES_HOME change between install and
 * remove cannot leave the old home's remnic: block (with its daemon token)
 * behind (Codex P2 on PR #1938, round 6). Extra candidates are shape-guarded
 * and de-duplicated against the environment-resolved paths.
 */
export function removeHermesConfig(opts: {
  profile: string;
  extraConfigPaths?: readonly string[];
}): HermesConfigResult {
  // Environment-resolved candidates can fail (e.g. HERMES_HOME points at a
  // regular file at remove time). That must not abort cleanup of the VALID
  // persisted install-time path — seed from whatever resolves and continue
  // (Codex P2 on PR #1938, round 8).
  let envCfgPaths: string[];
  let envResolutionError: string | null = null;
  try {
    envCfgPaths = [...hermesConfigCleanupPaths(opts.profile)];
  } catch (err) {
    envCfgPaths = [];
    envResolutionError = err instanceof Error ? err.message : String(err);
  }
  // De-duplicate ALL candidates by resolved file identity, not string
  // equality: in the legacy layout profiles/default/config.yaml is commonly a
  // SYMLINK to the root config.yaml — cleaning the real file and then hitting
  // the symlinked alias would trip the component guard and report a phantom
  // partial failure (Bugbot on PR #1938, round 21).
  const cfgPaths: string[] = [];
  for (const candidate of envCfgPaths) {
    if (!cfgPaths.some((existing) => sameHermesConfigTarget(existing, candidate))) {
      cfgPaths.push(candidate);
    }
  }
  for (const extra of opts.extraConfigPaths ?? []) {
    if (
      isPlausibleHermesConfigPath(extra) &&
      !cfgPaths.some((existing) => sameHermesConfigTarget(existing, extra))
    ) {
      cfgPaths.push(extra);
    }
  }
  if (cfgPaths.length === 0) {
    return {
      updated: false,
      skipped: true,
      reason: envResolutionError
        ? `Hermes config cleanup failed: ${envResolutionError}`
        : "Hermes config.yaml not found",
      configPath: "<unresolved>",
    };
  }
  const results = cfgPaths.map((cfgPath) => {
    try {
      return removeHermesConfigFile(cfgPath);
    } catch (err) {
      return {
        updated: false,
        skipped: true,
        reason: `Hermes config cleanup failed: ${err instanceof Error ? err.message : String(err)}`,
        configPath: cfgPath,
      };
    }
  });
  const updated = results.filter((result) => result.updated);
  const cleanupFailures = results.filter((result) => result.reason?.startsWith("Hermes config cleanup failed:"));

  if (updated.length > 0) {
    const updatedPaths = updated.map((result) => result.configPath).join(", ");
    if (cleanupFailures.length > 0) {
      const failedPaths = cleanupFailures.map((result) => result.configPath).join(", ");
      return {
        updated: false,
        skipped: true,
        reason: `Hermes config cleanup partially failed: updated ${updatedPaths}; failed ${failedPaths}`,
        configPath: `${updatedPaths}; failed: ${failedPaths}`,
      };
    }
    return {
      updated: true,
      skipped: false,
      configPath: updatedPaths,
    };
  }

  const cleanupFailure = cleanupFailures[0];
  if (cleanupFailure) {
    return cleanupFailure;
  }

  const existingWithoutBlock = results.find((result) => result.reason !== "Hermes config.yaml not found");
  const fallbackResult = existingWithoutBlock ?? results[0];
  if (fallbackResult) {
    return fallbackResult;
  }
  return {
    updated: false,
    skipped: true,
    reason: "Hermes config.yaml not found",
    configPath: cfgPaths[0] ?? "<unresolved>",
  };
}

function removeHermesConfigFile(cfgPath: string): HermesConfigResult {
  // Symlinked components below the Hermes root must not redirect the cleanup
  // rewrite (Codex P1 on PR #1938, round 19). A symlinked candidate is either
  // an alias of another candidate (already de-duplicated by file identity) or
  // a redirect we refuse to follow — report it as SKIPPED, not as a cleanup
  // failure, so it cannot manufacture a phantom partial-failure abort
  // (Bugbot on PR #1938, round 21).
  try {
    assertConfigComponentsNotSymlinked(cfgPath);
  } catch (err) {
    return {
      updated: false,
      skipped: true,
      reason: `Hermes config cleanup skipped: ${err instanceof Error ? err.message : String(err)}`,
      configPath: cfgPath,
    };
  }
  if (!fs.existsSync(cfgPath)) {
    return {
      updated: false,
      skipped: true,
      reason: "Hermes config.yaml not found",
      configPath: cfgPath,
    };
  }

  const raw = fs.readFileSync(cfgPath, "utf8");
  if (!/^remnic:/m.test(raw)) {
    return {
      updated: false,
      skipped: true,
      reason: "No remnic: block found in config.yaml",
      configPath: cfgPath,
    };
  }

  // Strip the remnic: block and its indented children
  const lines = raw.split("\n");
  const newLines: string[] = [];
  let inRemnicBlock = false;

  for (const line of lines) {
    if (/^remnic:/.test(line)) {
      inRemnicBlock = true;
      continue;
    }
    if (inRemnicBlock) {
      if (line.length > 0 && !/^\s/.test(line)) {
        inRemnicBlock = false;
        newLines.push(line);
      }
      // else: still in the block — skip the line
      continue;
    }
    newLines.push(line);
  }

  // Trim trailing blank lines left behind after the block removal
  while (newLines.length > 0 && newLines[newLines.length - 1]?.trim() === "") {
    newLines.pop();
  }

  // Use writeSecretFileSync to keep the file at 0o600 even after the token
  // has been removed. The file previously held a bearer token (so it was
  // written with 0o600 originally); preserving that mode prevents a window
  // where a rewrite with default umask temporarily widens permissions.
  writeSecretFileSync(cfgPath, newLines.length > 0 ? newLines.join("\n") + "\n" : "");
  return { updated: true, skipped: false, configPath: cfgPath };
}

// ── Doctor ────────────────────────────────────────────────────────────────────

export async function doctorConnector(connectorId: string): Promise<DoctorResult> {
  const installed = listConnectors().installed;
  const instance = installed.find((c) => c.connectorId === connectorId);

  if (!instance) {
    return {
      connectorId,
      checks: [{ name: "Installed", ok: false, detail: "Not installed" }],
      healthy: false,
    };
  }

  const configPath = path.join(getConnectorsDir(), `${connectorId}.json`);
  const checks: DoctorCheck[] = [];

  // Check config exists
  checks.push({
    name: "Config file",
    ok: fs.existsSync(configPath),
    detail: configPath,
  });

  // Check config is valid JSON
  try {
    const raw = fs.readFileSync(configPath, "utf8");
    JSON.parse(raw);
    checks.push({ name: "Config valid", ok: true, detail: "OK" });
  } catch (e) {
    checks.push({ name: "Config valid", ok: false, detail: String(e) });
  }

  // Check MCP server reachable (if applicable)
  const mcpUrl = instance.config.mcpServerUrl as string | undefined;
  if (mcpUrl) {
    try {
      const controller = new AbortController();
      const timeoutId = setTimeout(() => controller.abort(), 3000);
      const response = await fetch(mcpUrl, { signal: controller.signal });
      clearTimeout(timeoutId);
      checks.push({ name: "MCP server", ok: response.ok, detail: mcpUrl });
    } catch (e) {
      checks.push({
        name: "MCP server",
        ok: false,
        detail: `Cannot reach ${mcpUrl}: ${e instanceof Error ? e.message : "unknown"}`,
      });
    }
  }

  // Check memory dir (if applicable)
  const memoryDir = instance.config.memoryDir as string | undefined;
  if (memoryDir) {
    if (fs.existsSync(memoryDir)) {
      checks.push({ name: "Memory directory", ok: true, detail: memoryDir });
    } else {
      checks.push({ name: "Memory directory", ok: false, detail: `Not found: ${memoryDir}` });
    }
  }

  // Droid-specific: check ~/.factory/mcp.json has the remnic entry
  if (connectorId === "droid") {
    checks.push(droidMcpDoctorCheckImpl(instance.config.factoryMcpPath as string | undefined));
  }

  const healthy = checks.every((c) => c.ok);
  return { connectorId, checks, healthy };
}

// ── Codex memory extension install ────────────────────────────────────────

/**
 * Name of the Codex memories folder. Matches Codex's
 * `MEMORIES_SUBDIR = "memories"`.
 */
const CODEX_MEMORIES_SUBDIR = "memories";

/**
 * Name of the Codex memory-extensions folder. Matches Codex's
 * `EXTENSIONS_SUBDIR = "memories_extensions"`.
 *
 * Codex computes the extensions root as a **sibling** of the memories dir via
 * Rust's `Path::with_file_name("memories_extensions")` — so for the default
 * Codex home the layout is:
 *
 *     ~/.codex/memories/
 *     ~/.codex/memories_extensions/
 *
 * Extension files live **outside** of `memories/`, never inside it.
 */
const CODEX_EXTENSIONS_SUBDIR = "memories_extensions";

/** Folder name Remnic installs its extension under. */
const REMNIC_EXTENSION_DIR_NAME = "remnic";

export interface CodexMemoryExtensionPaths {
  /** Resolved Codex home directory (e.g. `~/.codex`). */
  codexHome: string;
  /** Resolved Codex memories directory (`<codex_home>/memories`). */
  memoriesDir: string;
  /** Sibling extensions root (`<codex_home>/memories_extensions`). */
  extensionsRoot: string;
  /** The specific Remnic extension directory inside the extensions root. */
  remnicExtensionDir: string;
}

export interface InstallCodexMemoryExtensionOptions {
  /** Optional override for `$CODEX_HOME`. Highest priority. */
  codexHome?: string | null;
  /** Optional override for the plugin-codex extension source directory. */
  sourceDir?: string | null;
}

export interface InstallCodexMemoryExtensionResult extends CodexMemoryExtensionPaths {
  /** Absolute path to the installed `instructions.md`. */
  instructionsPath: string;
  /** Number of files copied. */
  filesCopied: number;
  /**
   * Commit the install: permanently remove the backup of the prior extension
   * (if one existed). Call this once the config write has succeeded.
   */
  commit(): void;
  /**
   * Roll back the install: restore the prior extension if one existed, or
   * remove the newly-installed directory for a fresh install. Call this when
   * a subsequent step (e.g. config write) has failed.
   */
  rollback(): void;
}

export interface RemoveCodexMemoryExtensionOptions {
  codexHome?: string | null;
}

export interface RemoveCodexMemoryExtensionResult extends CodexMemoryExtensionPaths {
  /** True if an existing `remnic` extension directory was removed. */
  removed: boolean;
}

/**
 * Resolve the Codex home directory. Precedence:
 *   1. explicit `override` argument (from config)
 *   2. `$CODEX_HOME` env var
 *   3. `$HOME/.codex`, `$USERPROFILE/.codex`, or the OS home directory
 */
export function resolveCodexHome(override?: string | null): string {
  if (override && typeof override === "string" && override.trim().length > 0) {
    return path.resolve(override.trim());
  }
  const envHome = readEnvVar("CODEX_HOME");
  if (envHome && envHome.trim().length > 0) {
    return path.resolve(envHome.trim());
  }
  const home = readEnvVar("HOME") || readEnvVar("USERPROFILE") || resolveHomeDir();
  return path.resolve(home, ".codex");
}

/**
 * Compute the Codex memories + memory-extensions layout for a given Codex home.
 *
 * The extensions root is computed as a **sibling** of the memories dir by
 * taking `path.dirname(memoriesDir)` and joining `memories_extensions`. This
 * mirrors Rust's `with_file_name("memories_extensions")` semantics used by
 * Codex's `memory_extensions_root()`. Do NOT place the extension inside
 * `<codex_home>/memories/`.
 */
export function resolveCodexMemoryExtensionPaths(
  codexHomeOverride?: string | null,
): CodexMemoryExtensionPaths {
  const codexHome = resolveCodexHome(codexHomeOverride);
  const memoriesDir = path.join(codexHome, CODEX_MEMORIES_SUBDIR);
  // Sibling computation: with_file_name(EXTENSIONS_SUBDIR)
  const extensionsRoot = path.join(path.dirname(memoriesDir), CODEX_EXTENSIONS_SUBDIR);
  const remnicExtensionDir = path.join(extensionsRoot, REMNIC_EXTENSION_DIR_NAME);
  return { codexHome, memoriesDir, extensionsRoot, remnicExtensionDir };
}

/**
 * Locate the plugin-codex `memories_extensions/remnic/` source directory on
 * disk. Search order:
 *   1. explicit `override`
 *   2. resolve via `@remnic/plugin-codex` package (handles global npm installs)
 *   3. sibling `node_modules/@remnic/plugin-codex` relative to this module
 *   4. walk upward from this file's location (monorepo development)
 *   5. walk upward from `process.cwd()` (monorepo fallback)
 *
 * Returns the absolute path or throws a descriptive error listing all paths
 * searched when none exist.
 */
export function locatePluginCodexExtensionSource(override?: string | null): string {
  if (override && typeof override === "string" && override.trim().length > 0) {
    const resolved = path.resolve(override.trim());
    if (fs.existsSync(resolved) && fs.statSync(resolved).isDirectory()) {
      return resolved;
    }
    throw new Error(`Codex extension source directory not found: ${resolved}`);
  }

  const EXTENSION_SUBPATH = path.join("memories_extensions", "remnic");
  const WORKSPACE_RELATIVE_PATH = path.join(
    "packages",
    "plugin-codex",
    "memories_extensions",
    "remnic",
  );

  const searched: string[] = [];

  // Primary path: the bundled payload shipped with @remnic/core itself.
  // tsup copies src/connectors/codex/ → dist/connectors/codex/ (see tsup.config.ts
  // onSuccess hook). However, tsup bundles all source into dist/ as flat files
  // (dist/index.js, dist/chunk-*.js), so at runtime import.meta.url points to
  // dist/index.js or a dist/chunk-*.js — NOT dist/connectors/index.js.
  // Therefore we probe two sibling-relative candidates:
  //   1. moduleDir/codex          — matches tsx/ts-node on src/connectors/index.ts
  //   2. moduleDir/connectors/codex — matches the tsup dist layout where this code
  //                                   lands in dist/index.js or dist/chunk-*.js
  try {
    const moduleDir = path.dirname(fileURLToPath(import.meta.url));

    // Candidate 1: adjacent codex/ (tsx/ts-node from src/connectors/)
    const bundledCandidate = path.join(moduleDir, "codex");
    searched.push(bundledCandidate);
    if (fs.existsSync(bundledCandidate) && fs.statSync(bundledCandidate).isDirectory()) {
      return bundledCandidate;
    }

    // Candidate 2: dist/connectors/codex/ — the tsup output path.
    // When this module is bundled into dist/index.js or dist/chunk-*.js,
    // moduleDir is dist/ and tsup copies the payload to dist/connectors/codex/.
    const distConnectorsCandidate = path.join(moduleDir, "connectors", "codex");
    searched.push(distConnectorsCandidate);
    if (
      fs.existsSync(distConnectorsCandidate) &&
      fs.statSync(distConnectorsCandidate).isDirectory()
    ) {
      return distConnectorsCandidate;
    }
  } catch {
    // import.meta.url unavailable — not running as ESM, skip bundled path.
  }

  // Finding 2 — path 1: resolve via `@remnic/plugin-codex` package.json.
  // This covers global `npm install -g @remnic/remnic-core` or pnpm global installs
  // where the package lives under the global node_modules tree.
  try {
    const requireFromHere = createRequire(import.meta.url);
    const pluginPkgJsonPath = requireFromHere.resolve("@remnic/plugin-codex/package.json");
    const pluginPkgRoot = path.dirname(pluginPkgJsonPath);
    const candidate = path.join(pluginPkgRoot, EXTENSION_SUBPATH);
    searched.push(candidate);
    if (fs.existsSync(candidate) && fs.statSync(candidate).isDirectory()) {
      return candidate;
    }
  } catch {
    // @remnic/plugin-codex not installed — fall through to next strategy.
  }

  // Finding 2 — path 2: sibling node_modules under the module's own directory.
  // Handles cases like:
  //   .../node_modules/@remnic/remnic-core/src/connectors/index.js
  //   .../node_modules/@remnic/plugin-codex/memories_extensions/remnic
  try {
    const moduleDir = path.dirname(fileURLToPath(import.meta.url));
    let dir = moduleDir;
    for (let depth = 0; depth < 8; depth += 1) {
      const candidate = path.join(
        dir,
        "node_modules",
        "@remnic",
        "plugin-codex",
        EXTENSION_SUBPATH,
      );
      searched.push(candidate);
      if (fs.existsSync(candidate) && fs.statSync(candidate).isDirectory()) {
        return candidate;
      }
      const parent = path.dirname(dir);
      if (parent === dir) break;
      dir = parent;
    }
  } catch {
    // import.meta.url unavailable — not running as ESM.
  }

  // Finding 2 — path 3 & 4: walk upward from this file's location and from
  // process.cwd() looking for the monorepo layout (`packages/plugin-codex/…`).
  const anchors: string[] = [];
  try {
    anchors.push(path.dirname(fileURLToPath(import.meta.url)));
  } catch {
    // Not running under ESM with import.meta — skip.
  }
  anchors.push(process.cwd());

  for (const anchor of anchors) {
    let dir = anchor;
    for (let depth = 0; depth < 12; depth += 1) {
      const candidate = path.join(dir, WORKSPACE_RELATIVE_PATH);
      searched.push(candidate);
      if (fs.existsSync(candidate) && fs.statSync(candidate).isDirectory()) {
        return candidate;
      }
      const parent = path.dirname(dir);
      if (parent === dir) break;
      dir = parent;
    }
  }

  throw new Error(
    "Could not locate the plugin-codex memories_extensions/remnic source directory.\n" +
      "Paths searched:\n" +
      searched.map((p) => `  - ${p}`).join("\n") +
      "\nInstall @remnic/plugin-codex or pass sourceDir explicitly.",
  );
}

/** Recursive synchronous directory copy. */
function copyDirRecursiveSync(src: string, dest: string): number {
  let count = 0;
  fs.mkdirSync(dest, { recursive: true });
  const entries = fs.readdirSync(src, { withFileTypes: true });
  for (const entry of entries) {
    const from = path.join(src, entry.name);
    const to = path.join(dest, entry.name);
    if (entry.isDirectory()) {
      count += copyDirRecursiveSync(from, to);
    } else if (entry.isFile()) {
      fs.copyFileSync(from, to);
      count += 1;
    }
    // Skip symlinks, sockets, etc. — extension content is plain files.
  }
  return count;
}

/**
 * Install the Remnic memory extension into `<codex_home>/memories_extensions/remnic/`
 * atomically. The copy is written to a sibling `.remnic.tmp-<pid>-<ts>` directory
 * and then renamed into place, so a concurrent Codex phase-2 run never sees a
 * half-written extension.
 *
 * This function is **idempotent and scoped**: it only touches the `remnic`
 * subfolder inside `memories_extensions/`. Adjacent extensions (other
 * vendors) are never read, written, or removed.
 */
export function installCodexMemoryExtension(
  options: InstallCodexMemoryExtensionOptions = {},
): InstallCodexMemoryExtensionResult {
  const paths = resolveCodexMemoryExtensionPaths(options.codexHome ?? null);
  const sourceDir = locatePluginCodexExtensionSource(options.sourceDir ?? null);

  fs.mkdirSync(paths.extensionsRoot, { recursive: true });

  // Clean any stale tmp from a previous crashed run by scanning the
  // extensions root for any `.remnic.tmp-*` prefixed entry. We must do this
  // BEFORE creating the new tmp directory. Per-entry errors are swallowed so
  // one bad entry doesn't abort cleanup of the rest.
  //
  // Finding 2: only remove tmp dirs that are provably stale (older than
  // STALE_TMP_THRESHOLD_MS). Dirs younger than the threshold belong to a
  // concurrent install that is still in progress; deleting them would corrupt
  // the other process's atomic rename.
  const tmpPrefix = `.${REMNIC_EXTENSION_DIR_NAME}.tmp-`;
  const STALE_TMP_THRESHOLD_MS = 10 * 60 * 1000; // 10 minutes
  const now = Date.now();
  try {
    const existingEntries = fs.readdirSync(paths.extensionsRoot);
    for (const entry of existingEntries) {
      if (!entry.startsWith(tmpPrefix)) continue;
      const stalePath = path.join(paths.extensionsRoot, entry);
      try {
        const stat = fs.statSync(stalePath);
        const ageMs = now - stat.mtimeMs;
        if (ageMs < STALE_TMP_THRESHOLD_MS) {
          // Too recent — leave it alone; another install is likely still running.
          continue;
        }
        fs.rmSync(stalePath, { recursive: true, force: true });
      } catch {
        // swallow — one bad entry should not abort the others
      }
    }
  } catch {
    // extensions root just-created / unreadable — nothing to clean
  }

  const tmpName = `${tmpPrefix}${process.pid}-${Date.now()}`;
  const tmpDir = path.join(paths.extensionsRoot, tmpName);

  let filesCopied = 0;
  let commitFn: () => void = () => { /* no-op: set below on success */ };
  let rollbackFn: () => void = () => { /* no-op: set below on success */ };
  try {
    filesCopied = copyDirRecursiveSync(sourceDir, tmpDir);

    // Atomic replace: rename old remnic/ to a timestamped backup, then rename
    // the tmp dir into place.  If the second rename fails, restore from backup
    // so the old extension is never permanently lost.
    const backupDir = `${paths.remnicExtensionDir}.bak-${Date.now()}`;
    const hadExisting = fs.existsSync(paths.remnicExtensionDir);
    if (hadExisting) {
      fs.renameSync(paths.remnicExtensionDir, backupDir);
    }
    try {
      fs.renameSync(tmpDir, paths.remnicExtensionDir);
    } catch (renameErr) {
      // New rename failed — restore backup so the old extension survives.
      if (hadExisting) {
        try {
          fs.renameSync(backupDir, paths.remnicExtensionDir);
        } catch {
          // swallow — backup restore best-effort
        }
      }
      throw renameErr;
    }
    // The new extension is in place. We intentionally keep the backup alive
    // until the caller calls commit(). This gives the caller a chance to roll
    // back to the prior state if a subsequent operation (e.g. config write) fails.
    //
    // commit() — remove the backup (called on success)
    // rollback() — restore the prior extension from backup, or remove the newly
    //              installed directory if this was a fresh install
    commitFn = (): void => {
      if (hadExisting) {
        try {
          fs.rmSync(backupDir, { recursive: true, force: true });
        } catch {
          // swallow — stale backup is harmless
        }
      }
    };
    rollbackFn = (): void => {
      if (hadExisting) {
        // Restore the prior extension from backup.
        try {
          // Remove the newly-installed dir first so rename can succeed.
          if (fs.existsSync(paths.remnicExtensionDir)) {
            fs.rmSync(paths.remnicExtensionDir, { recursive: true, force: true });
          }
          fs.renameSync(backupDir, paths.remnicExtensionDir);
        } catch {
          // swallow — best-effort restore; backup remains on disk
        }
      } else {
        // Fresh install — just remove the directory we created.
        try {
          if (fs.existsSync(paths.remnicExtensionDir)) {
            fs.rmSync(paths.remnicExtensionDir, { recursive: true, force: true });
          }
        } catch {
          // swallow
        }
      }
    };
  } catch (err) {
    // Best-effort cleanup so we never leave .tmp garbage behind.
    if (fs.existsSync(tmpDir)) {
      try {
        fs.rmSync(tmpDir, { recursive: true, force: true });
      } catch {
        // swallow
      }
    }
    throw err;
  }

  const instructionsPath = path.join(paths.remnicExtensionDir, "instructions.md");

  return {
    ...paths,
    instructionsPath,
    filesCopied,
    commit: commitFn,
    rollback: rollbackFn,
  };
}

/**
 * Remove the Remnic memory extension. Only touches
 * `<codex_home>/memories_extensions/remnic/` — never adjacent extensions.
 */
export function removeCodexMemoryExtension(
  options: RemoveCodexMemoryExtensionOptions = {},
): RemoveCodexMemoryExtensionResult {
  const paths = resolveCodexMemoryExtensionPaths(options.codexHome ?? null);
  let removed = false;
  if (fs.existsSync(paths.remnicExtensionDir)) {
    fs.rmSync(paths.remnicExtensionDir, { recursive: true, force: true });
    removed = true;
  }
  return { ...paths, removed };
}

// ── Helpers ───────────────────────────────────────────────────────────────────


// ── WeClone proxy config helpers ───────────────────────────────────────────
//
// The standalone `remnic-weclone-proxy` CLI reads its config from
// ~/.remnic/connectors/weclone.json by default. `remnic connectors install
// weclone` composes and persists that file so the proxy can start without
// additional setup. The file is also tracked by the connector registry (at
// getConnectorsDir()/weclone.json) so `remnic connectors list/remove/doctor`
// work uniformly across all connectors.

const WECLONE_PROXY_CONFIG_DIRNAME = ".remnic";
const WECLONE_PROXY_CONFIG_FILENAME = "weclone.json";

/**
 * Resolve the path to ~/.remnic/connectors/weclone.json for the current user.
 * Honours REMNIC_HOME / ENGRAM_HOME env overrides so tests can point the
 * install at a temp dir without leaking into the real home directory.
 *
 * Always returns an absolute path via `path.resolve` so install-time and
 * run-time resolution agree even when the override is a relative path like
 * `tmp/remnic` (which would otherwise be interpreted against the caller's
 * current working directory). Must stay in lockstep with the proxy CLI's
 * `defaultConfigPath()` in @remnic/connector-weclone/src/cli.ts.
 *
 * `HOME=""` edge case: a nullish fallback would keep the
 * empty string (empty is not nullish), which `path.resolve("", ...)` then
 * interprets as CWD. `os.homedir()` by contrast falls back to the OS
 * password database when HOME is empty, so the two code paths would
 * disagree. We therefore treat empty HOME as absent and delegate to
 * `os.homedir()` in both places — the same rule the proxy CLI follows.
 */
export function resolveWeCloneProxyConfigPath(): string {
  const remnicHome = readEnvVar("REMNIC_HOME");
  const override = remnicHome && remnicHome.length > 0 ? remnicHome : readEnvVar("ENGRAM_HOME");
  if (override && override.length > 0) {
    return path.resolve(expandTildePath(override), "connectors", WECLONE_PROXY_CONFIG_FILENAME);
  }
  const envHome = readEnvVar("HOME");
  const home = envHome && envHome.length > 0 ? envHome : os.homedir();
  return path.resolve(
    home,
    WECLONE_PROXY_CONFIG_DIRNAME,
    "connectors",
    WECLONE_PROXY_CONFIG_FILENAME,
  );
}

/**
 * Read the existing proxy config file, if any. Returns raw contents so the
 * caller can both parse it (for value precedence) and restore it verbatim on
 * rollback without touching byte-level formatting.
 */
function readWeCloneProxyConfigIfExists(configPath: string): string | null {
  try {
    if (!fs.existsSync(configPath)) return null;
    return fs.readFileSync(configPath, "utf8");
  } catch {
    return null;
  }
}

/** Safely parse a JSON string into a record; returns null on error. */
function safeParseJson(raw: string): Record<string, unknown> | null {
  try {
    const parsed = JSON.parse(raw);
    if (typeof parsed === "object" && parsed !== null && !Array.isArray(parsed)) {
      return parsed as Record<string, unknown>;
    }
    return null;
  } catch {
    return null;
  }
}

interface WeCloneProxyConfig {
  wecloneApiUrl: string;
  wecloneModelName: string;
  proxyPort: number;
  remnicDaemonUrl: string;
  remnicAuthToken?: string;
  sessionStrategy: "caller-id" | "single";
  memoryInjection: {
    maxTokens: number;
    position: "system-append" | "system-prepend";
    template: string;
  };
}

const WECLONE_DEFAULTS = {
  wecloneApiUrl: "http://localhost:8000/v1",
  wecloneModelName: "weclone-avatar",
  proxyPort: 8100,
  remnicDaemonUrl: "http://localhost:4318",
  sessionStrategy: "single" as const,
  memoryInjection: {
    maxTokens: 1500,
    position: "system-append" as const,
    template: "[Memory Context]\n{memories}\n[End Memory Context]",
  },
};

/**
 * Resolve a string field with precedence: userConfig → priorConfig → default.
 * Only non-empty strings are accepted from either source; invalid values fall
 * through so the user gets a working default rather than a broken install.
 */
function resolveStringField(
  userConfig: Record<string, unknown>,
  priorConfig: Record<string, unknown> | null,
  key: string,
  fallback: string,
): string {
  const fromUser = userConfig[key];
  if (typeof fromUser === "string" && fromUser.length > 0) return fromUser;
  if (priorConfig) {
    const fromPrior = priorConfig[key];
    if (typeof fromPrior === "string" && fromPrior.length > 0) return fromPrior;
  }
  return fallback;
}

/**
 * Coerce a config value to an integer port in [1, 65535]. Accepts number or
 * numeric string (parseConnectorConfig produces strings from `--config
 * proxyPort=8100`). Returns null if the value is missing or invalid so the
 * caller can fall through to the next precedence level.
 */
function coercePort(value: unknown): number | null {
  if (typeof value === "number" && Number.isInteger(value) && value >= 1 && value <= 65535) {
    return value;
  }
  if (typeof value === "string" && value.length > 0) {
    const n = Number(value);
    if (Number.isInteger(n) && n >= 1 && n <= 65535) return n;
  }
  return null;
}

function resolvePort(
  userConfig: Record<string, unknown>,
  priorConfig: Record<string, unknown> | null,
  fallback: number,
): number {
  const fromUser = coercePort(userConfig.proxyPort);
  if (fromUser !== null) return fromUser;
  if (priorConfig) {
    const fromPrior = coercePort(priorConfig.proxyPort);
    if (fromPrior !== null) return fromPrior;
  }
  return fallback;
}

function resolveSessionStrategy(
  userConfig: Record<string, unknown>,
  priorConfig: Record<string, unknown> | null,
): "caller-id" | "single" {
  const valid = new Set(["caller-id", "single"]);
  const fromUser = userConfig.sessionStrategy;
  if (typeof fromUser === "string" && valid.has(fromUser)) {
    return fromUser as "caller-id" | "single";
  }
  if (priorConfig) {
    const fromPrior = priorConfig.sessionStrategy;
    if (typeof fromPrior === "string" && valid.has(fromPrior)) {
      return fromPrior as "caller-id" | "single";
    }
  }
  return WECLONE_DEFAULTS.sessionStrategy;
}

/**
 * Compose a WeCloneProxyConfig from user-supplied overrides and any prior
 * saved config, filling in defaults for every required field. The returned
 * shape is exactly what the proxy's parseConfig() expects.
 */
export function buildWeCloneProxyConfig(args: {
  userConfig: Record<string, unknown>;
  priorConfig: Record<string, unknown> | null;
  authToken?: string;
}): WeCloneProxyConfig {
  const { userConfig, priorConfig, authToken } = args;

  const wecloneApiUrl = resolveStringField(
    userConfig,
    priorConfig,
    "wecloneApiUrl",
    WECLONE_DEFAULTS.wecloneApiUrl,
  );
  const wecloneModelName = resolveStringField(
    userConfig,
    priorConfig,
    "wecloneModelName",
    WECLONE_DEFAULTS.wecloneModelName,
  );
  const remnicDaemonUrl = resolveStringField(
    userConfig,
    priorConfig,
    "remnicDaemonUrl",
    WECLONE_DEFAULTS.remnicDaemonUrl,
  );
  const proxyPort = resolvePort(
    userConfig,
    priorConfig,
    WECLONE_DEFAULTS.proxyPort,
  );
  const sessionStrategy = resolveSessionStrategy(userConfig, priorConfig);

  // Memory injection: always start from defaults, then shallow-merge any
  // prior values, then user overrides. Individual field validation happens in
  // the proxy's parseConfig() at proxy startup — here we only assemble a
  // best-effort shape. A malformed user override would be rejected later with
  // a clean error message.
  //
  // `typeof [] === "object"` so a bare `typeof ... === "object" && ... !==
  // null` guard would let an array spread numeric-indexed properties into
  // the merged object, silently corrupting it. Explicitly reject arrays.
  const memoryInjection = {
    ...WECLONE_DEFAULTS.memoryInjection,
    ...(priorConfig &&
    typeof priorConfig.memoryInjection === "object" &&
    priorConfig.memoryInjection !== null &&
    !Array.isArray(priorConfig.memoryInjection)
      ? (priorConfig.memoryInjection as Record<string, unknown>)
      : {}),
    ...(typeof userConfig.memoryInjection === "object" &&
    userConfig.memoryInjection !== null &&
    !Array.isArray(userConfig.memoryInjection)
      ? (userConfig.memoryInjection as Record<string, unknown>)
      : {}),
  } as WeCloneProxyConfig["memoryInjection"];

  const config: WeCloneProxyConfig = {
    wecloneApiUrl,
    wecloneModelName,
    proxyPort,
    remnicDaemonUrl,
    sessionStrategy,
    memoryInjection,
  };

  // Token precedence: freshly minted token → user-supplied → prior saved.
  // Never write a token if none is available — the proxy tolerates missing
  // tokens (it just won't send Authorization headers to the daemon).
  if (authToken && authToken.length > 0) {
    config.remnicAuthToken = authToken;
  } else if (typeof userConfig.remnicAuthToken === "string" && userConfig.remnicAuthToken.length > 0) {
    config.remnicAuthToken = userConfig.remnicAuthToken;
  } else if (priorConfig && typeof priorConfig.remnicAuthToken === "string" && priorConfig.remnicAuthToken.length > 0) {
    config.remnicAuthToken = priorConfig.remnicAuthToken;
  }

  return config;
}

import { lstat, readdir, realpath, rm } from "node:fs/promises";
import path from "node:path";
import { log } from "../logger.js";

/**
 * Best-effort retention cleanup for conversation chunk docs.
 *
 * Layout (written by indexer.ts):
 *   <root>/<safeSessionKey>/<YYYY-MM-DD>/<chunkId>.md
 *
 * We prune day directories older than retentionDays, and remove empty session dirs.
 */
export async function cleanupConversationChunks(
  rootDir: string,
  retentionDays: number,
): Promise<void> {
  if (!Number.isFinite(retentionDays) || retentionDays <= 0) return;

  const cutoffMs = Date.now() - retentionDays * 24 * 60 * 60 * 1000;

  try {
    const root = await assertCleanupRoot(rootDir);
    const sessions = await readdir(rootDir, { withFileTypes: true });
    for (const s of sessions) {
      if (!s.isDirectory()) continue;
      const sessionDir = await assertCleanupChild(root, path.join(rootDir, s.name));
      const dayDirs = await readdir(sessionDir, { withFileTypes: true });

      for (const d of dayDirs) {
        if (!d.isDirectory()) continue;
        // Expect YYYY-MM-DD
        if (!/^\d{4}-\d{2}-\d{2}$/.test(d.name)) continue;
        const dayMs = new Date(d.name + "T00:00:00.000Z").getTime();
        if (!Number.isFinite(dayMs)) continue;
        if (dayMs < cutoffMs) {
          await rm(await assertCleanupChild(root, path.join(sessionDir, d.name)), { recursive: true, force: true });
        }
      }

      // Remove empty session dirs after pruning.
      try {
        const remaining = await readdir(sessionDir);
        if (remaining.length === 0) {
          await rm(await assertCleanupChild(root, sessionDir), { recursive: true, force: true });
        }
      } catch {
        // ignore
      }
    }
  } catch (err) {
    log.debug(`conversation chunk cleanup failed: ${err}`);
  }
}

async function assertCleanupRoot(rootDir: string): Promise<string> {
  const stat = await lstat(rootDir);
  if (stat.isSymbolicLink()) {
    throw new Error("conversation chunk cleanup root must not be a symlink");
  }
  return realpath(rootDir);
}

async function assertCleanupChild(rootReal: string, candidate: string): Promise<string> {
  const stat = await lstat(candidate);
  if (stat.isSymbolicLink()) {
    throw new Error("conversation chunk cleanup path must not contain symlinks");
  }
  const real = await realpath(candidate);
  const relative = path.relative(rootReal, real);
  if (relative === "" || (!relative.startsWith("..") && !path.isAbsolute(relative))) {
    return real;
  }
  throw new Error("conversation chunk cleanup path escapes index root");
}

import type { TranscriptEntry } from "../types.js";

export interface ConversationChunk {
  id: string;
  sessionKey: string;
  startTs: string;
  endTs: string;
  text: string;
}

export function chunkTranscriptEntries(
  sessionKey: string,
  entries: TranscriptEntry[],
  opts: { maxChars: number; maxTurns: number },
): ConversationChunk[] {
  const maxChars = Math.max(500, opts.maxChars);
  const maxTurns = Math.max(5, opts.maxTurns);
  const sorted = [...entries].sort((a, b) => a.timestamp.localeCompare(b.timestamp));

  const out: ConversationChunk[] = [];
  let buf: TranscriptEntry[] = [];
  let bufChars = 0;

  function flush(): void {
    if (buf.length === 0) return;
    const startTs = buf[0]!.timestamp;
    const endTs = buf[buf.length - 1]!.timestamp;
    const text = buf.map((e) => `[${e.role}] ${e.content}`).join("\n\n");
    const id = `${startTs}-${out.length}`.replace(/[:.]/g, "-");
    out.push({ id, sessionKey, startTs, endTs, text });
    buf = [];
    bufChars = 0;
  }

  for (const e of sorted) {
    const line = `[${e.role}] ${e.content}\n\n`;
    if (buf.length >= maxTurns || bufChars + line.length > maxChars) {
      flush();
    }
    buf.push(e);
    bufChars += line.length;
  }
  flush();

  return out;
}

export interface IncludedMemory {
  id: string;
  path: string;
  namespace?: string;
}

type LegacyIncludedMemorySource = {
  includedMemories?: unknown;
  memoryIds?: unknown;
  resultPaths?: unknown;
  resultNamespaces?: unknown;
  budgetsApplied?: unknown;
};

function legacyBudgetView(raw: LegacyIncludedMemorySource): {
  includedMemoryIds?: unknown;
  includedMemoryPaths?: unknown;
  includedMemoryNamespaces?: unknown;
} {
  const budgets = raw.budgetsApplied;
  if (!budgets || typeof budgets !== "object") return {};
  const record = budgets as Record<string, unknown>;
  return {
    includedMemoryIds: record.includedMemoryIds,
    includedMemoryPaths: record.includedMemoryPaths,
    includedMemoryNamespaces: record.includedMemoryNamespaces,
  };
}

function asStringList(value: unknown): string[] {
  return Array.isArray(value) ? value.map((item) => (typeof item === "string" ? item : "")) : [];
}

function asOptionalStringList(value: unknown): Array<string | undefined> {
  return Array.isArray(value)
    ? value.map((item) => (typeof item === "string" ? item : undefined))
    : [];
}

function normalizeIncludedMemory(value: unknown): IncludedMemory | undefined {
  if (!value || typeof value !== "object") return undefined;
  const record = value as { id?: unknown; path?: unknown; namespace?: unknown };
  const id = typeof record.id === "string" ? record.id : "";
  const path = typeof record.path === "string" ? record.path : "";
  if (!id && !path) return undefined;
  const namespace = typeof record.namespace === "string" ? record.namespace : undefined;
  return namespace ? { id, path, namespace } : { id, path };
}

export function coerceIncludedMemories(raw: object): IncludedMemory[] {
  const source = raw as LegacyIncludedMemorySource;
  if (Array.isArray(source.includedMemories)) {
    return source.includedMemories
      .map(normalizeIncludedMemory)
      .filter((item): item is IncludedMemory => item !== undefined);
  }

  const budgets = legacyBudgetView(source);
  const ids = asStringList(source.memoryIds ?? budgets.includedMemoryIds);
  const paths = asStringList(source.resultPaths ?? budgets.includedMemoryPaths);
  const namespaces = asOptionalStringList(
    source.resultNamespaces ?? budgets.includedMemoryNamespaces,
  );
  const count = Math.max(ids.length, paths.length);
  const memories: IncludedMemory[] = [];
  for (let index = 0; index < count; index += 1) {
    const id = ids[index] ?? "";
    const path = paths[index] ?? "";
    if (!id && !path) continue;
    const namespace = namespaces[index];
    memories.push(namespace ? { id, path, namespace } : { id, path });
  }
  return memories;
}

export function includedMemoryIds(memories: readonly IncludedMemory[]): string[] {
  return memories.map((memory) => memory.id);
}

export function includedMemoryPaths(memories: readonly IncludedMemory[]): string[] {
  return memories.map((memory) => memory.path);
}

export function includedMemoryNamespaces(
  memories: readonly IncludedMemory[],
): Array<string | undefined> {
  return memories.map((memory) => memory.namespace);
}

import { lstat, mkdir, writeFile } from "node:fs/promises";
import type { Stats } from "node:fs";
import { createHash } from "node:crypto";
import path from "node:path";
import { log } from "../logger.js";
import type { FaissConversationIndexAdapter } from "./faiss-adapter.js";
import type { ConversationChunk } from "./chunker.js";

const MAX_PATH_COMPONENT_LENGTH = 200;

function sanitizePathComponent(
  value: string,
  fallback: string,
  opts: { lowercase?: boolean } = {},
): string {
  const raw = typeof value === "string" && value.trim().length > 0
    ? value.trim()
    : fallback;
  const normalized = opts.lowercase ? raw.toLowerCase() : raw;
  const sanitized = normalized
    .replace(/[^a-zA-Z0-9._-]+/g, "_")
    .slice(0, MAX_PATH_COMPONENT_LENGTH);
  if (!sanitized || sanitized === "." || sanitized === "..") {
    return fallback;
  }
  return sanitized;
}

export function sanitizeSessionKey(sessionKey: string): string {
  const raw = typeof sessionKey === "string" && sessionKey.trim().length > 0
    ? sessionKey.trim()
    : "";
  const safe = sanitizePathComponent(raw, "unknown-session", { lowercase: true });
  if (!raw) return safe;
  const suffix = `-${createHash("sha256").update(raw).digest("hex").slice(0, 12)}`;
  return `${safe.slice(0, MAX_PATH_COMPONENT_LENGTH - suffix.length)}${suffix}`;
}

function sanitizeChunkId(id: string): string {
  return sanitizePathComponent(id, "chunk");
}

function yamlQuotedScalar(value: string): string {
  return JSON.stringify(value);
}

function datePathComponent(startTs: string): string {
  const match = typeof startTs === "string"
    ? /^(\d{4})-(\d{2})-(\d{2})T/.exec(startTs)
    : null;
  if (!match) {
    throw new Error("invalid conversation chunk start timestamp");
  }
  const date = new Date(startTs);
  if (!Number.isFinite(date.getTime())) {
    throw new Error("invalid conversation chunk start timestamp");
  }
  const [, year, month, day] = match;
  if (
    date.getUTCFullYear() !== Number(year) ||
    date.getUTCMonth() + 1 !== Number(month) ||
    date.getUTCDate() !== Number(day)
  ) {
    throw new Error("invalid conversation chunk start timestamp");
  }
  return date.toISOString().slice(0, 10);
}

function resolveInsideRoot(rootDir: string, candidate: string): string {
  const root = path.resolve(rootDir);
  const resolved = path.resolve(candidate);
  const rel = path.relative(root, resolved);
  if (
    rel === "" ||
    (rel !== ".." && !rel.startsWith(`..${path.sep}`) && !path.isAbsolute(rel))
  ) {
    return resolved;
  }
  throw new Error("conversation chunk path escapes index root");
}

async function lstatIfExists(candidate: string): Promise<Stats | undefined> {
  try {
    return await lstat(candidate);
  } catch (err) {
    if ((err as NodeJS.ErrnoException).code === "ENOENT") return undefined;
    throw err;
  }
}

async function rejectSymlinkIfExists(candidate: string): Promise<void> {
  const stat = await lstatIfExists(candidate);
  if (stat?.isSymbolicLink()) {
    throw new Error("conversation chunk path contains symlink");
  }
}

async function rejectExistingSymlinksInPath(baseDir: string, candidate: string): Promise<void> {
  const base = path.resolve(baseDir);
  const resolved = path.resolve(candidate);

  let current = base;
  while (current !== path.dirname(current)) {
    const stat = await lstatIfExists(current);
    if (stat) {
      if (stat.isSymbolicLink()) {
        throw new Error("conversation chunk path contains symlink");
      }
      break;
    }
    current = path.dirname(current);
  }

  const relative = path.relative(base, resolved);
  if (relative === "") return;

  current = base;
  for (const part of relative.split(path.sep)) {
    current = path.join(current, part);
    const stat = await lstatIfExists(current);
    if (!stat) return;
    if (stat.isSymbolicLink()) {
      throw new Error("conversation chunk path contains symlink");
    }
  }
}

async function rejectExistingSymlinkAncestors(
  rootDir: string,
  candidate: string,
): Promise<void> {
  const root = path.resolve(rootDir);
  const resolved = resolveInsideRoot(root, candidate);
  await rejectExistingSymlinksInPath(root, resolved);
}

export async function writeConversationChunks(
  rootDir: string,
  chunks: ConversationChunk[],
): Promise<string[]> {
  const written: string[] = [];
  const root = path.resolve(rootDir);
  await rejectExistingSymlinksInPath(root, root);
  await mkdir(root, { recursive: true });
  await rejectExistingSymlinksInPath(root, root);

  for (const c of chunks) {
    const safe = sanitizeSessionKey(c.sessionKey);
    const date = datePathComponent(c.startTs);
    const dir = resolveInsideRoot(root, path.join(root, safe, date));
    await rejectExistingSymlinkAncestors(root, dir);
    await mkdir(dir, { recursive: true });
    await rejectExistingSymlinkAncestors(root, dir);
    const fp = resolveInsideRoot(root, path.join(dir, `${sanitizeChunkId(c.id)}.md`));
    await rejectExistingSymlinkAncestors(root, path.dirname(fp));
    await rejectSymlinkIfExists(fp);
    const content =
      `---\n` +
      `kind: conversation_chunk\n` +
      `sessionKey: ${yamlQuotedScalar(c.sessionKey)}\n` +
      `startTs: ${yamlQuotedScalar(c.startTs)}\n` +
      `endTs: ${yamlQuotedScalar(c.endTs)}\n` +
      `---\n\n` +
      c.text +
      "\n";
    await writeFile(fp, content, "utf-8");
    written.push(fp);
  }
  return written;
}

export interface ConversationChunkUpsertResult {
  upserted: number;
  skipped: boolean;
  reason?: "adapter-unavailable" | "adapter-error";
}

export interface ConversationChunkRebuildResult {
  rebuilt: number;
  skipped: boolean;
  reason?: "adapter-unavailable" | "adapter-error";
}

export async function upsertConversationChunksFailOpen(
  adapter: FaissConversationIndexAdapter | undefined,
  chunks: ConversationChunk[],
  options: { retentionCutoffMs?: number } = {},
): Promise<ConversationChunkUpsertResult> {
  if (!adapter) {
    return { upserted: 0, skipped: true, reason: "adapter-unavailable" };
  }
  try {
    const upserted = await adapter.upsertChunks(chunks, options);
    return { upserted, skipped: false };
  } catch (err) {
    log.debug(`conversation index FAISS upsert failed (fail-open): ${err}`);
    return { upserted: 0, skipped: true, reason: "adapter-error" };
  }
}

export async function rebuildConversationChunksFailOpen(
  adapter: FaissConversationIndexAdapter | undefined,
  chunks: ConversationChunk[],
): Promise<ConversationChunkRebuildResult> {
  if (!adapter) {
    return { rebuilt: 0, skipped: true, reason: "adapter-unavailable" };
  }
  try {
    const rebuilt = await adapter.rebuildChunks(chunks);
    return { rebuilt, skipped: false };
  } catch (err) {
    log.debug(`conversation index FAISS rebuild failed (fail-open): ${err}`);
    return { rebuilt: 0, skipped: true, reason: "adapter-error" };
  }
}

/**
 * Issue #560 PR 4 — Memory Worth recall filter.
 *
 * Pure helper that multiplies candidate recall scores by a Memory Worth
 * factor (from `computeMemoryWorth`, PR 2) so memories with a history of
 * failed sessions sink in the ranking. Reading the per-memory counters is
 * the caller's job — this module does no I/O and depends only on PR 2's
 * pure scorer.
 *
 * The filter is feature-flagged (`recallMemoryWorthFilterEnabled` on
 * PluginConfig, default `false` in this PR) so operators can A/B it safely
 * before PR 5 flips the default.
 *
 * Intentional properties:
 *   - Pure function. No side effects, no I/O. Tested directly.
 *   - Candidates with no counters (empty `counters` map entry) score exactly
 *     the same as they did pre-filter (multiplier = 0.5, but we renormalize
 *     so the neutral prior stays neutral — see the "neutral prior preserves
 *     ranking among unseen memories" test below).
 *   - Stable: a strictly sorted input stays in its original order among
 *     items that all score to the prior. This matters because an ad-hoc
 *     sort that returns 0 for ties on some comparators but not others
 *     produces non-deterministic ordering (CLAUDE.md rule 19).
 *   - Does not mutate inputs — returns a new array.
 *
 * How the multiplier is applied:
 *   `new_score = old_score * (p_success / PRIOR)`
 *   where PRIOR = 0.5. This way an uninstrumented memory (p_success = 0.5)
 *   gets a multiplier of exactly 1.0 (no penalty, no boost), a memory that
 *   always succeeds gets a multiplier approaching 2.0 (boosted) and a
 *   memory that always fails gets a multiplier approaching 0.0 (sunk).
 *   Using the ratio instead of raw `p_success` keeps the filter from
 *   accidentally halving every un-instrumented memory the moment it ships.
 *
 * Out of scope:
 *   - Reading counters from storage (caller does that once per recall).
 *   - Orchestrator wiring / config plumbing (separate commit in this PR).
 *   - Default flip to `true` (PR 5 once benchmark confirms a win).
 */

import { computeMemoryWorth, type MemoryWorthResult } from "./memory-worth.js";

/**
 * One memory's outcome history, keyed by memory path so the filter can look
 * up a candidate's counters in O(1). `lastAccessed` is passed through to
 * `computeMemoryWorth` where it drives optional recency decay.
 */
export interface MemoryWorthCounters {
  mw_success?: number;
  mw_fail?: number;
  lastAccessed?: string | null;
}

/**
 * A scored recall candidate. Defined locally (rather than importing
 * `QmdSearchResult`) so the filter can be reused by any caller that has a
 * `{ path, score }` shape — e.g. unit tests, bench fixtures, and future
 * non-QMD retrieval backends.
 */
export interface MemoryWorthFilterCandidate {
  path: string;
  score: number;
}

export interface MemoryWorthFilterOptions {
  /**
   * Map from memory path → outcome counters. Candidates whose path is not
   * in this map score at the neutral prior (multiplier = 1.0).
   */
  counters: ReadonlyMap<string, MemoryWorthCounters>;
  /**
   * Current time reference — passed through to `computeMemoryWorth` for
   * decay math. Required (not defaulted) so tests and deterministic bench
   * runs don't depend on the wall clock.
   */
  now: Date;
  /**
   * Half-life for outcome decay, in milliseconds. Optional; when omitted,
   * decay is disabled and raw counters are used.
   */
  halfLifeMs?: number;
  /**
   * Re-sort the candidates by descending filtered score before returning.
   * When `false`, the original input order is preserved (but the `.score`
   * fields still reflect the multiplier). Default `true` because most
   * callers want a ranked result; a few tests / bench fixtures want the
   * order preserved so they can assert on position.
   */
  reorder?: boolean;
}

/**
 * Output of `applyMemoryWorthFilter`. `worth` surfaces the computed
 * `{ score, p_success, confidence }` for each candidate so observability /
 * xray layers can report why each item moved without re-deriving it.
 */
export interface MemoryWorthFilterResultItem {
  path: string;
  /** Final score after the Memory Worth multiplier is applied. */
  score: number;
  /** The untouched input score — useful for telemetry and xray. */
  originalScore: number;
  /** The multiplier that was applied (1.0 for uninstrumented memories). */
  multiplier: number;
  /** The Memory Worth result (`score`, `p_success`, `confidence`). */
  worth: MemoryWorthResult;
}

/**
 * Neutral prior from `computeMemoryWorth`. Uninstrumented memories score
 * exactly 0.5, so dividing by this value makes the multiplier land on 1.0
 * for candidates with no history.
 */
const NEUTRAL_PRIOR = 0.5;

/**
 * Apply the Memory Worth multiplier to each candidate's score and (by
 * default) re-sort the list by descending score.
 *
 * When `counters` is empty, every candidate gets a multiplier of 1.0 — the
 * function is safe to call unconditionally when the feature flag is on,
 * even for namespaces that have zero instrumented memories.
 */
export function applyMemoryWorthFilter(
  candidates: readonly MemoryWorthFilterCandidate[],
  options: MemoryWorthFilterOptions,
): MemoryWorthFilterResultItem[] {
  const reorder = options.reorder !== false;
  const result: MemoryWorthFilterResultItem[] = [];

  // Walk candidates in input order so the pre-sort ordering can act as a
  // stable tiebreaker below. Record each candidate's position so we can
  // break score ties deterministically (CLAUDE.md rule 19).
  for (let i = 0; i < candidates.length; i += 1) {
    const candidate = candidates[i]!;
    const counters = options.counters.get(candidate.path) ?? {};
    const worth = computeMemoryWorth({
      mw_success: counters.mw_success,
      mw_fail: counters.mw_fail,
      lastAccessed: counters.lastAccessed,
      now: options.now,
      halfLifeMs: options.halfLifeMs,
    });
    const multiplier = worth.score / NEUTRAL_PRIOR;
    // Clamp the candidate score at zero before multiplying. A negative
    // base score (can happen when upstream penalties push a candidate
    // below zero) would flip the intended direction: a multiplier > 1
    // would move the score further negative (worse rank), while a
    // multiplier < 1 would move it toward zero (better rank). That's the
    // opposite of "failure-prone memories sink". Treat negatives as zero
    // so the filter's semantics hold regardless of upstream arithmetic.
    const safeBase = candidate.score < 0 ? 0 : candidate.score;
    const scored = safeBase * multiplier;
    result.push({
      path: candidate.path,
      score: scored,
      originalScore: candidate.score,
      multiplier,
      worth,
    });
  }

  if (!reorder) return result;

  // Attach original position for stable sort. Node's Array.sort is stable
  // by spec since ES2019, but we encode the tiebreaker explicitly so a
  // comparator reviewer can see the contract.
  const indexed = result.map((r, i) => ({ r, i }));
  indexed.sort((a, b) => {
    if (b.r.score !== a.r.score) return b.r.score - a.r.score;
    return a.i - b.i;
  });
  return indexed.map((x) => x.r);
}

/**
 * Convenience lookup helper for callers that already have an array of
 * memory files with `path` and frontmatter fields on each. Keeps the map
 * construction in one place so call sites don't drift.
 */
export function buildMemoryWorthCounterMap(
  memories: readonly {
    path: string;
    frontmatter: {
      mw_success?: number;
      mw_fail?: number;
      lastAccessed?: string | null;
    };
  }[],
): Map<string, MemoryWorthCounters> {
  const map = new Map<string, MemoryWorthCounters>();
  for (const m of memories) {
    const fm = m.frontmatter;
    // Only add entries with at least one counter present — keeps the map
    // small when the instrumented fraction is still low.
    if (fm.mw_success === undefined && fm.mw_fail === undefined) continue;
    map.set(m.path, {
      mw_success: fm.mw_success,
      mw_fail: fm.mw_fail,
      lastAccessed: fm.lastAccessed,
    });
  }
  return map;
}

/**
 * Stale-preference recall stage (issue #2371).
 *
 * Pure ranking + annotation helpers, deliberately free of storage, LLM, and
 * config-loading imports so the recall hot path can import them without
 * pulling in the drift scan's dependency graph.
 *
 * Two independent, independently-gated effects:
 *
 *   1. `driftDetection.recallDamping` multiplies the rank score of a
 *      `category: preference` memory carrying `driftState: stale` by
 *      `stalePenalty`, so a stale preference sinks below an otherwise-equal
 *      fresh memory. Applied in the same boost stage as the Memory Worth
 *      multiplier, so the pipeline-order contract (retrieve → filter →
 *      rerank/boost → cap → format) is untouched.
 *   2. `driftDetection.annotateAfterDays` emits a compact age note for a
 *      preference whose last corroboration is older than the configured
 *      window. Formatting-stage only — it never mutates the stored memory.
 *
 * Both are off by default, and with both off this module returns the input
 * order and no notes, so recall output is byte-identical to pre-#2371.
 */

import type { DriftDetectionConfig } from "./drift-config.js";
import type { MemoryDriftState } from "./drift-types.js";

const DAY_MS = 24 * 60 * 60 * 1000;

/** The only frontmatter fields this stage reads. */
export interface DriftRecallFrontmatter {
  category?: string;
  driftState?: MemoryDriftState;
  lastCorroborated?: string;
  created?: string;
}

export interface DriftRankInput {
  /** Opaque candidate identity — the caller's composite (namespace, path) key. */
  key: string;
  /** Monotone-decreasing rank score preserving upstream order. */
  rank: number;
  frontmatter?: DriftRecallFrontmatter;
}

export interface DriftRankOutput {
  key: string;
  /** `1` when untouched, `stalePenalty` when damped. */
  multiplier: number;
  /** Injection annotation, when the age gate fired. */
  note?: string;
}

/**
 * True when this stage would change nothing. Callers use it to skip the
 * frontmatter lookups entirely on the default (all-off) configuration.
 *
 * `stalePenalty === 1` is the documented no-op (§33): damping stays "enabled"
 * but multiplies by one, so it must not by itself activate the stage.
 */
export function isPreferenceDriftStageActive(config: DriftDetectionConfig | undefined): boolean {
  if (!config) return false;
  // `recallDamping` is a real boolean here: parseDriftDetectionConfig already
  // coerced the string forms and threw on anything unrecognized, so no further
  // coercion is needed at this boundary.
  const damping = config.recallDamping && config.stalePenalty < 1;
  return damping || config.annotateAfterDays > 0;
}

/**
 * Render the age note for an uncorroborated preference, or `undefined` when
 * the gate is off or the preference is inside the window.
 *
 * `lastCorroborated` absent falls back to `created`: a preference the scan has
 * never corroborated is measured from when it was stated, which is exactly the
 * "stated 2026-01; not corroborated since" case the survey describes.
 */
export function driftAgeNote(
  frontmatter: DriftRecallFrontmatter | undefined,
  config: DriftDetectionConfig,
  now: Date,
): string | undefined {
  if (config.annotateAfterDays <= 0) return undefined;
  if (!frontmatter || frontmatter.category !== "preference") return undefined;
  const anchor = frontmatter.lastCorroborated ?? frontmatter.created;
  if (typeof anchor !== "string") return undefined;
  const anchorMs = Date.parse(anchor);
  if (!Number.isFinite(anchorMs)) return undefined;
  const ageDays = Math.floor((now.getTime() - anchorMs) / DAY_MS);
  if (ageDays < config.annotateAfterDays) return undefined;
  const stated = new Date(anchorMs).toISOString().slice(0, 7);
  return frontmatter.lastCorroborated
    ? `(corroborated ${stated}; not since)`
    : `(stated ${stated}; not corroborated since)`;
}

/**
 * Rank and annotate one recall branch's candidates.
 *
 * Returns one output per input, ordered by damped rank descending with a
 * stable key tiebreak so the comparator is total and the ordering is identical
 * across runs (§12).
 */
export function applyPreferenceDriftRanking(
  inputs: readonly DriftRankInput[],
  options: { config: DriftDetectionConfig; now: Date },
): DriftRankOutput[] {
  const { config, now } = options;
  const damping = config.recallDamping && config.stalePenalty < 1;

  const scored = inputs.map((input, index) => {
    const fm = input.frontmatter;
    const isStalePreference = fm?.category === "preference" && fm.driftState === "stale";
    const multiplier = damping && isStalePreference ? config.stalePenalty : 1;
    return {
      key: input.key,
      index,
      multiplier,
      damped: input.rank * multiplier,
      note: driftAgeNote(fm, config, now),
    };
  });

  // Sorting only matters when damping applies. On a neutral pass (every
  // multiplier 1) keep input order: damped values mix upstream effective
  // scores with position-derived ranks, so sorting them reorders results
  // even though nothing was damped.
  if (scored.some((s) => s.multiplier !== 1)) {
    scored.sort((a, b) => {
      if (a.damped !== b.damped) return a.damped > b.damped ? -1 : 1;
      // Equal damped score → preserve upstream order, then key, so the
      // comparator returns 0 only for genuinely identical entries.
      if (a.index !== b.index) return a.index < b.index ? -1 : 1;
      if (a.key !== b.key) return a.key < b.key ? -1 : 1;
      return 0;
    });
  }

  return scored.map((s) => (s.note ? { key: s.key, multiplier: s.multiplier, note: s.note } : { key: s.key, multiplier: s.multiplier }));
}

/**
 * Maximal Marginal Relevance (MMR) re-selection for recall candidates.
 *
 * After the reranker produces its ordered candidate list, we run an MMR pass
 * over the top N candidates (per-section) so that a cluster of near-duplicate
 * high-scoring facts cannot dominate the injected context.
 *
 *     MMR(d) = λ * sim(d, query) − (1 − λ) * max_{d' ∈ selected} sim(d, d')
 *
 * - λ defaults to 0.7 (tilted toward relevance, with meaningful diversity).
 * - Similarity uses cosine over pre-computed embeddings when available, and
 *   falls back to Jaccard over normalized tokens (lowercased alphanumerics)
 *   when embeddings are missing.
 * - Per-section application is the caller's responsibility: pass each
 *   section's ordered candidate slice independently so one cluster in one
 *   section cannot starve another section.
 *
 * Pure, deterministic, no IO. Input arrays are never mutated.
 */

/** Minimal candidate shape used by MMR. Callers may wrap their own records. */
export interface MmrCandidate {
  /** Stable identifier for the candidate. Only used for tie-breaking. */
  id: string;
  /** Text content used for the Jaccard similarity fallback. */
  content: string;
  /**
   * Relevance score from the upstream ranker (e.g. rerank score or RRF).
   * Used as the `sim(d, query)` term when no query embedding is available.
   */
  score: number;
  /** Optional pre-computed embedding vector for cosine similarity. */
  embedding?: readonly number[] | null;
}

export interface ApplyMmrOptions<C extends MmrCandidate> {
  /** Ordered candidate list (most relevant first). */
  candidates: readonly C[];
  /** Optional query embedding. If provided and candidates carry embeddings,
   *  relevance is measured by cosine similarity to the query. Otherwise
   *  candidate `score` is normalized and used. */
  queryEmbedding?: readonly number[] | null;
  /** λ ∈ [0, 1]. 1 = pure relevance, 0 = pure diversity. Default 0.7. */
  lambda?: number;
  /** Apply MMR only over the top N candidates. Default 40. */
  topN?: number;
  /** Maximum number of candidates to select. Default = candidates length. */
  budget?: number;
}

export interface MmrDiversityReport {
  /**
   * Total number of candidates MMR considered (the full input pool, pre-MMR).
   * Previously this mirrored `kept` and was therefore uninformative; it now
   * reflects the true pool size so `kept/considered` logs carry signal even
   * though MMR is reorder-only.
   */
  considered: number;
  /**
   * Number of candidates present in the MMR output. With the current
   * orchestrator pipeline MMR is reorder-only (no drops), so this is the
   * same as `considered`. It's still reported separately so a future
   * drop-mode MMR can distinguish them without another schema change.
   */
  kept: number;
  /**
   * Head-of-list positions whose candidate identity changed between the
   * pre-MMR and post-MMR slices. This is the *actionable* diversity signal:
   * it tells the caller how many of the top `sampleSize` results MMR
   * promoted or demoted. Zero means MMR had no head-of-list effect; a value
   * greater than zero means at least one diverse candidate was swapped in.
   */
  headReorderCount: number;
  /** Average pairwise similarity of the head-of-list input slice (pre-MMR). */
  avgPairwiseSimBefore: number;
  /** Average pairwise similarity of the head-of-list MMR output slice. */
  avgPairwiseSimAfter: number;
}

export const DEFAULT_LAMBDA = 0.7;
export const DEFAULT_TOP_N = 40;
/**
 * Default number of head-of-list candidates compared by
 * {@link summarizeMmrDiversity}. Small on purpose: we want to measure whether
 * MMR actually *changed* the head of the list. Comparing the full top-N slice
 * is meaningless when `budget >= candidates.length` because both slices
 * contain the same set (just reordered), making pairwise-similarity
 * order-independent and identical before vs after.
 */
const DEFAULT_DIVERSITY_SAMPLE_SIZE = 10;

/**
 * Pure MMR re-selection over an ordered candidate list.
 *
 * Returns a new array — the input is never mutated. When `candidates.length`
 * is `<= 1` or `budget <= 0`, a defensive copy is returned as a no-op.
 */
export function applyMmrToCandidates<C extends MmrCandidate>(
  opts: ApplyMmrOptions<C>,
): C[] {
  const candidates = Array.isArray(opts.candidates) ? opts.candidates : [];
  if (candidates.length === 0) return [];

  const lambda = clampLambda(opts.lambda);
  const topN = clampPositiveInt(opts.topN, DEFAULT_TOP_N);
  const budget = clampPositiveInt(opts.budget, candidates.length);

  if (budget <= 0) return [];
  if (candidates.length === 1) return [candidates[0]!];

  // Only reorder the top-N slice; anything past it keeps its original position
  // appended at the end (but will not be selected unless budget > topN).
  const pool = candidates.slice(0, topN);
  const tail = candidates.slice(topN);

  // Relevance scores as `sim(d, query)`. Prefer cosine to the query embedding
  // when we can compute it; otherwise fall back to the candidate's own score
  // normalized into [0, 1] across the pool.
  const relevance = computeRelevanceScores(pool, opts.queryEmbedding);

  // Pre-compute pairwise candidate-candidate similarity lazily as needed.
  const pairSim = new Map<string, number>();
  const pairKey = (i: number, j: number): string =>
    i < j ? `${i}:${j}` : `${j}:${i}`;
  const sim = (i: number, j: number): number => {
    if (i === j) return 1;
    const key = pairKey(i, j);
    const cached = pairSim.get(key);
    if (cached !== undefined) return cached;
    const a = pool[i]!;
    const b = pool[j]!;
    const s = similarity(a, b);
    pairSim.set(key, s);
    return s;
  };

  const selectedIdx: number[] = [];
  const remaining = new Set<number>();
  for (let i = 0; i < pool.length; i += 1) remaining.add(i);

  while (selectedIdx.length < budget && remaining.size > 0) {
    let bestIdx = -1;
    let bestMmr = Number.NEGATIVE_INFINITY;
    for (const idx of remaining) {
      const rel = relevance[idx] ?? 0;
      let maxSimToSelected = 0;
      if (selectedIdx.length > 0) {
        for (const s of selectedIdx) {
          const pairwise = sim(idx, s);
          if (pairwise > maxSimToSelected) maxSimToSelected = pairwise;
        }
      }
      const mmr = lambda * rel - (1 - lambda) * maxSimToSelected;
      if (
        mmr > bestMmr ||
        // Stable tie-breaker: prefer the earlier original position.
        (mmr === bestMmr && (bestIdx < 0 || idx < bestIdx))
      ) {
        bestMmr = mmr;
        bestIdx = idx;
      }
    }
    if (bestIdx < 0) break;
    selectedIdx.push(bestIdx);
    remaining.delete(bestIdx);
  }

  const selected: C[] = selectedIdx.map((i) => pool[i]!);

  // If the caller set a budget larger than topN, append tail candidates in
  // their original order until budget is filled. This keeps MMR scoped to the
  // top-N slice while still respecting the caller's requested size.
  if (selected.length < budget && tail.length > 0) {
    for (const c of tail) {
      if (selected.length >= budget) break;
      selected.push(c);
    }
  }

  return selected;
}

/**
 * Summarize how much MMR reshuffled the head of the candidate list, for
 * logging. Optional — callers can skip this if they don't care about metrics.
 *
 * IMPORTANT: `before` should be the score-ordered input (the same ordering the
 * upstream reranker emitted, *not* the MMR output), and `after` should be the
 * MMR-reordered list. Both are truncated to `sampleSize` before their pairwise
 * similarity is averaged.
 *
 * The sample size intentionally defaults to a small number
 * ({@link DEFAULT_DIVERSITY_SAMPLE_SIZE}) so that when the caller uses
 * `budget >= candidates.length` (i.e. MMR only reorders without dropping), the
 * head-of-list comparison still reflects whether MMR promoted diverse
 * candidates. Passing a sample size `>= candidates.length` in that situation
 * makes `avgPairwiseSimBefore` and `avgPairwiseSimAfter` trivially equal
 * because pairwise similarity is order-independent.
 */
export function summarizeMmrDiversity<C extends MmrCandidate>(
  before: readonly C[],
  after: readonly C[],
  sampleSize: number = DEFAULT_DIVERSITY_SAMPLE_SIZE,
): MmrDiversityReport {
  const n = clampPositiveInt(sampleSize, DEFAULT_DIVERSITY_SAMPLE_SIZE);
  const beforeSlice = before.slice(0, n);
  const afterSlice = after.slice(0, n);
  // Count how many head-of-list positions MMR actually changed. A zero value
  // means MMR left the head untouched; a positive value is the actionable
  // "MMR promoted N diverse candidates" signal the previous metric lacked.
  let headReorderCount = 0;
  const compareLength = Math.min(beforeSlice.length, afterSlice.length);
  for (let i = 0; i < compareLength; i += 1) {
    if (beforeSlice[i]!.id !== afterSlice[i]!.id) headReorderCount += 1;
  }
  return {
    considered: before.length,
    kept: after.length,
    headReorderCount,
    avgPairwiseSimBefore: averagePairwiseSimilarity(beforeSlice),
    avgPairwiseSimAfter: averagePairwiseSimilarity(afterSlice),
  };
}

// -----------------------------------------------------------------------------
// Internals
// -----------------------------------------------------------------------------

function clampLambda(value: number | undefined): number {
  if (typeof value !== "number" || !Number.isFinite(value)) return DEFAULT_LAMBDA;
  if (value < 0) return 0;
  if (value > 1) return 1;
  return value;
}

function clampPositiveInt(
  value: number | undefined,
  fallback: number,
): number {
  if (typeof value !== "number" || !Number.isFinite(value)) return fallback;
  if (value <= 0) return 0;
  return Math.floor(value);
}

function computeRelevanceScores<C extends MmrCandidate>(
  pool: readonly C[],
  queryEmbedding: readonly number[] | null | undefined,
): number[] {
  // If we have a query embedding, use cosine against each candidate embedding
  // where possible. Candidates without embeddings fall back to normalized score.
  const canUseQueryEmbedding =
    Array.isArray(queryEmbedding) && queryEmbedding.length > 0;

  if (canUseQueryEmbedding) {
    const scores: number[] = [];
    for (const c of pool) {
      if (Array.isArray(c.embedding) && c.embedding.length > 0) {
        scores.push(cosineSimilarity(queryEmbedding!, c.embedding));
      } else {
        // Fall back to the upstream relevance score for this one candidate.
        scores.push(normalizeFinite(c.score));
      }
    }
    return normalizeVector(scores);
  }

  // No query embedding — use normalized candidate scores.
  const raw = pool.map((c) => normalizeFinite(c.score));
  return normalizeVector(raw);
}

function similarity<C extends MmrCandidate>(a: C, b: C): number {
  if (
    Array.isArray(a.embedding) &&
    a.embedding.length > 0 &&
    Array.isArray(b.embedding) &&
    b.embedding.length > 0 &&
    a.embedding.length === b.embedding.length
  ) {
    return cosineSimilarity(a.embedding, b.embedding);
  }
  return jaccardSimilarity(a.content ?? "", b.content ?? "");
}

function cosineSimilarity(
  a: readonly number[],
  b: readonly number[],
): number {
  if (a.length === 0 || b.length === 0) return 0;
  const len = Math.min(a.length, b.length);
  let dot = 0;
  let na = 0;
  let nb = 0;
  for (let i = 0; i < len; i += 1) {
    const av = a[i] ?? 0;
    const bv = b[i] ?? 0;
    dot += av * bv;
    na += av * av;
    nb += bv * bv;
  }
  if (na === 0 || nb === 0) return 0;
  const cos = dot / (Math.sqrt(na) * Math.sqrt(nb));
  // Clamp to [0, 1]. Negative cosines (opposite directions) are treated as 0
  // for MMR purposes — two embeddings pointing opposite ways should be
  // "maximally diverse", not discouraged further.
  if (cos < 0) return 0;
  if (cos > 1) return 1;
  return cos;
}

export function normalizeTokens(text: string): Set<string> {
  if (!text) return new Set();
  // Unicode-aware normalization. We lowercase and replace any character that
  // is NOT a Unicode letter or number with a space, then split on whitespace.
  // This preserves non-Latin scripts (Cyrillic, Greek, Hebrew, Arabic, etc.)
  // so the Jaccard fallback still detects near-duplicates in multilingual
  // snippets. Without this fix, `[^a-z0-9]+` strips all non-ASCII and two
  // identical Chinese/Japanese/Cyrillic snippets both collapse to the empty
  // set, returning similarity 0 and letting duplicates dominate recall.
  const cleaned = text
    .toLowerCase()
    .replace(/[^\p{L}\p{N}]+/gu, " ")
    .trim();
  if (cleaned.length === 0) {
    // CJK fallback: scripts like Chinese/Japanese/Korean do not use word
    // breaks, so after the Unicode strip the above split-on-whitespace yields
    // one big token. The Latin-style split is a bad match for these scripts;
    // use per-codepoint character tokens instead, which approximates a
    // unigram shingle and is accurate enough for near-duplicate detection.
    const chars = new Set<string>();
    for (const ch of text.toLowerCase()) {
      if (/\s/.test(ch)) continue;
      chars.add(ch);
    }
    return chars;
  }
  const tokens = new Set<string>();
  for (const token of cleaned.split(/\s+/)) {
    if (!token) continue;
    // A single "token" that is actually a run of CJK codepoints (no spaces in
    // the source) should still be split into per-character tokens so the
    // Jaccard overlap works. Latin/Cyrillic/etc. keep their word-level tokens.
    if (token.length >= 2 && hasUnsegmentableScript(token)) {
      for (const ch of token) tokens.add(ch);
    } else {
      tokens.add(token);
    }
  }
  return tokens;
}

/**
 * Returns true when `token` contains at least one codepoint in a script that
 * does not use whitespace for word segmentation (CJK Unified Ideographs,
 * Hiragana, Katakana, Hangul). These are tokenized per-character so Jaccard
 * similarity can still detect near-duplicate snippets.
 */
function hasUnsegmentableScript(token: string): boolean {
  return /[\p{Script=Han}\p{Script=Hiragana}\p{Script=Katakana}\p{Script=Hangul}]/u.test(
    token,
  );
}

function jaccardSimilarity(a: string, b: string): number {
  const ta = normalizeTokens(a);
  const tb = normalizeTokens(b);
  if (ta.size === 0 && tb.size === 0) return 0;
  let intersection = 0;
  for (const t of ta) if (tb.has(t)) intersection += 1;
  const union = ta.size + tb.size - intersection;
  if (union === 0) return 0;
  return intersection / union;
}

function normalizeFinite(value: number): number {
  if (typeof value !== "number" || !Number.isFinite(value)) return 0;
  return value;
}

function normalizeVector(values: number[]): number[] {
  if (values.length === 0) return values;
  // Intentionally *not* min-max normalized. Min-max maps the lowest score to
  // 0 and the highest to 1, which amplifies tiny relevance gaps (e.g. a tight
  // reranker cluster like [0.93, 0.94, 0.95]) into the full [0, 1] range.
  // That lets a near-duplicate at the top permanently beat a diverse
  // candidate at the bottom because `lambda * 0 - (1 - lambda) * 0 = 0` is
  // always worse than `lambda * 1 - (1 - lambda) * maxSim` for any
  // maxSim < lambda / (1 - lambda). MMR is supposed to escape exactly that
  // scenario; min-max defeats it.
  //
  // Instead we preserve the relative score gaps by scaling only if the
  // scores leave the MMR-friendly `[0, 1]` range. Negative or out-of-range
  // scores are clamped to `[0, 1]` by dividing by the max absolute value; if
  // everything is already inside `[0, 1]`, we pass through untouched so
  // tight clusters stay tight and MMR can promote a diverse candidate from
  // the bottom of the cluster.
  let max = 0;
  let min = Number.POSITIVE_INFINITY;
  for (const v of values) {
    if (!Number.isFinite(v)) continue;
    const a = Math.abs(v);
    if (a > max) max = a;
    if (v < min) min = v;
  }
  if (!Number.isFinite(min)) {
    return values.map(() => 0);
  }
  if (max === 0) {
    // All scores are zero — give everyone 1 so diversity fully drives
    // selection (otherwise every candidate has `lambda * 0 = 0` and the
    // first-found wins trivially, hiding any diversity benefit).
    return values.map(() => 1);
  }
  // If scores already live in [0, 1], pass them through so tight clusters
  // (e.g. [0.93, 0.94, 0.95]) stay tight and the (1 - lambda) * maxSim term
  // can actually outweigh a 0.01 relevance gap, which is the whole point of
  // MMR. Otherwise divide by `max` to bring the top score to 1 while
  // preserving *relative* gaps (e.g. [100, 200, 300] -> [0.33, 0.67, 1.0]).
  if (min >= 0 && max <= 1) {
    return values.map((v) =>
      Number.isFinite(v) ? (v < 0 ? 0 : v > 1 ? 1 : v) : 0,
    );
  }
  return values.map((v) => {
    if (!Number.isFinite(v)) return 0;
    const scaled = v / max;
    if (scaled < 0) return 0;
    if (scaled > 1) return 1;
    return scaled;
  });
}

function averagePairwiseSimilarity<C extends MmrCandidate>(
  candidates: readonly C[],
): number {
  if (candidates.length < 2) return 0;
  let sum = 0;
  let count = 0;
  for (let i = 0; i < candidates.length; i += 1) {
    for (let j = i + 1; j < candidates.length; j += 1) {
      sum += similarity(candidates[i]!, candidates[j]!);
      count += 1;
    }
  }
  if (count === 0) return 0;
  return sum / count;
}

// -----------------------------------------------------------------------------
// Orchestration helper: MMR for recall results keyed by path-first
// -----------------------------------------------------------------------------

/**
 * Minimum shape the recall-MMR orchestration helper expects from a result.
 * Any richer result type (e.g. {@link QmdSearchResult}) satisfies this.
 */
export interface MmrRecallResult {
  readonly docid?: string;
  readonly path?: string;
  readonly snippet?: string;
  readonly score?: number;
  /**
   * Effective relevance carried forward by the rerank stage that last
   * adjusted the result. Preferred over `score` for MMR's relevance term.
   */
  readonly effectiveScore?: number;
}

export interface ReorderRecallResultsOptions {
  readonly lambda?: number;
  readonly topN?: number;
  /**
   * Head-of-list sample size used by the diversity metric. Defaults to
   * {@link DEFAULT_DIVERSITY_SAMPLE_SIZE}. Intentionally small so the metric
   * reflects head-of-list changes even when `budget >= results.length`.
   */
  readonly diversitySampleSize?: number;
}

export interface ReorderRecallResultsOutcome<R extends MmrRecallResult> {
  readonly reordered: R[];
  readonly diversity: MmrDiversityReport;
  readonly lambda: number;
}

/**
 * Apply MMR to an ordered list of recall results and return the reordered
 * list plus a head-of-list diversity report.
 *
 * This helper is the single source of truth for the orchestrator's
 * per-section MMR pass. It is pure and deterministic so it can be unit
 * tested without constructing an Orchestrator.
 *
 * Key invariants:
 * 1. **No silent drops.** Candidates are keyed by a stable unique key derived
 *    from `path` first, falling back to `docid`, and always suffixed with the
 *    candidate's original index. Two results that share a basename-style
 *    docid but differ in path are treated as distinct candidates and both
 *    survive the reorder.
 * 2. **No mutation.** The input array is never mutated; a new array is
 *    returned.
 * 3. **Diversity metric is meaningful.** The report compares the *head of
 *    list* before and after MMR using a small sample size, so it reflects
 *    whether MMR promoted diverse candidates even when
 *    `budget >= results.length`.
 */
export function reorderRecallResultsWithMmr<R extends MmrRecallResult>(
  results: readonly R[],
  options: ReorderRecallResultsOptions = {},
): ReorderRecallResultsOutcome<R> {
  const emptyReport: MmrDiversityReport = {
    considered: 0,
    kept: 0,
    headReorderCount: 0,
    avgPairwiseSimBefore: 0,
    avgPairwiseSimAfter: 0,
  };
  const lambda = clampLambda(options.lambda);

  if (!Array.isArray(results) || results.length === 0) {
    return { reordered: [], diversity: emptyReport, lambda };
  }
  if (results.length < 2) {
    // Single-element input: MMR is a trivial no-op but the diversity report
    // must still reflect the real pool size so external callers see
    // `considered=1 kept=1` rather than the `0/0` sentinel used for the
    // empty case. This is also the exact path the orchestrator short-circuits
    // past, but the helper is a public export and external callers cannot
    // rely on that invariant.
    return {
      reordered: [results[0]!],
      diversity: {
        considered: 1,
        kept: 1,
        headReorderCount: 0,
        avgPairwiseSimBefore: 0,
        avgPairwiseSimAfter: 0,
      },
      lambda,
    };
  }

  const topN = clampPositiveInt(options.topN, DEFAULT_TOP_N);

  // Build a per-result *unique* key so distinct results with colliding
  // docids or paths are never silently collapsed by id-based lookups.
  // Keys are always suffixed with the original input index so two results
  // that share the same `path` (or share the same `docid` when `path` is
  // empty) still get distinct identities.
  const candidates: MmrCandidate[] = results.map((r, index) => ({
    id: makeRecallKey(r, index),
    content: r.snippet ?? "",
    score: effectiveRelevance(r),
    embedding: null,
  }));
  // Index lookup by id so we can map MMR-selected candidates back to their
  // *original* position (and therefore their original `candidates[i]` object,
  // which preserves its `id` across the reorder). Reusing those original
  // candidate objects in the diversity comparison means
  // `headReorderCount` works correctly even when two results in the input
  // share the same base key: a swap at the same head position shows up
  // because their original-index-suffixed ids still differ.
  const indexById = new Map<string, number>();
  for (let i = 0; i < candidates.length; i += 1) {
    indexById.set(candidates[i]!.id, i);
  }

  const selectedMmr = applyMmrToCandidates({
    candidates,
    lambda,
    topN,
    budget: results.length,
  });

  const reordered: R[] = [];
  // Parallel array of the *original* candidate objects in the new (post-MMR)
  // order. Used for a faithful diversity comparison that preserves each
  // candidate's original identity.
  const reorderedCandidates: MmrCandidate[] = [];
  const seen = new Set<string>();
  for (const c of selectedMmr) {
    if (seen.has(c.id)) continue;
    const origIndex = indexById.get(c.id);
    if (origIndex === undefined) continue;
    seen.add(c.id);
    reordered.push(results[origIndex]!);
    reorderedCandidates.push(candidates[origIndex]!);
  }
  // Safety: append any candidates MMR did not select so nothing is dropped.
  if (reordered.length < results.length) {
    for (let i = 0; i < results.length; i += 1) {
      const origCandidate = candidates[i]!;
      if (seen.has(origCandidate.id)) continue;
      seen.add(origCandidate.id);
      reordered.push(results[i]!);
      reorderedCandidates.push(origCandidate);
    }
  }

  const diversity = summarizeMmrDiversity(
    candidates,
    reorderedCandidates,
    options.diversitySampleSize,
  );

  return { reordered, diversity, lambda };
}

/**
 * Relevance for MMR's `sim(d, query)` term: the effective relevance an
 * upstream rerank stage carried forward, else the raw retrieval score.
 */
function effectiveRelevance(r: MmrRecallResult): number {
  if (typeof r.effectiveScore === "number" && Number.isFinite(r.effectiveScore)) {
    return r.effectiveScore;
  }
  return typeof r.score === "number" ? r.score : 0;
}

function makeRecallKey(r: MmrRecallResult, index: number): string {
  const baseKey = r.path || r.docid || "";
  return `${baseKey}::${index}`;
}

/**
 * Reasoning-trace recall boost (issue #564 PR 3).
 *
 * Pure helpers for:
 * - detecting whether a user query looks like a problem-solving ask
 *   ("how do I…", "step by step", etc.)
 * - boosting stored reasoning_trace memories within a result list when that
 *   condition matches.
 *
 * Callers gate these helpers behind the `recallReasoningTraceBoostEnabled`
 * config flag (default false); the helpers themselves are also no-ops when
 * `enabled` is false so they can be safely chained into the recall pipeline.
 */

/**
 * Heuristic: does the incoming query read like the user wants a stored
 * solution chain (reasoning trace)?
 *
 * Positive signals:
 *  - starts with "how do I", "how can I", "how would I", "how to"
 *  - contains "step by step", "walk me through", "work through"
 *  - contains "reasoning", "think through", "figure out", "debug"
 *  - explicitly mentions "trace" or "chain of thought"
 *
 * This is intentionally conservative — the boost is OFF by default, so false
 * negatives are cheap, but false positives would shift retrieval for ordinary
 * queries on an opt-in install.
 */
export function looksLikeProblemSolvingQuery(query: string): boolean {
  if (typeof query !== "string") return false;
  const q = query.trim().toLowerCase();
  if (q.length === 0) return false;

  // Starts-with patterns.
  const startsWithPatterns = [
    /^how\s+do\s+i\b/,
    /^how\s+can\s+i\b/,
    /^how\s+would\s+i\b/,
    /^how\s+should\s+i\b/,
    /^how\s+to\b/,
    /^what'?s?\s+the\s+best\s+way\s+to\b/,
    /^can\s+you\s+walk\s+me\s+through\b/,
    /^walk\s+me\s+through\b/,
    /^help\s+me\s+debug\b/,
    /^help\s+me\s+figure\s+out\b/,
    /^why\s+(does|is|did)\b/,
  ];
  for (const re of startsWithPatterns) {
    if (re.test(q)) return true;
  }

  // Anywhere-in-string phrases. These mirror the doc-comment's stated
  // positive signals: broader variants ("work through", "figure out",
  // "debug this") are included so "how do I debug this" doesn't have to
  // lean on the `help me debug` starts-with entry alone, and so queries
  // like "work through the problem" or "figure out why it broke" trigger
  // the heuristic as the docstring claims.
  const phrases = [
    "step by step",
    "step-by-step",
    "work through",
    "walk through",
    "walk me through",
    "reason through",
    "think through",
    "figure out",
    "chain of thought",
    "reasoning trace",
    "solution chain",
    "troubleshoot",
    "debug this",
    "debug the",
    " debug ",
  ];
  for (const phrase of phrases) {
    if (q.includes(phrase)) return true;
  }

  return false;
}

/**
 * Minimal shape the boost helper needs to read from a recall result. Matches
 * QmdSearchResult as of issue #564 but kept structural so tests and future
 * callers don't have to import orchestrator-level types.
 */
export interface BoostableResult {
  path: string;
  score: number;
  docid?: string;
  /** Effective relevance carried forward by an upstream rerank stage. */
  effectiveScore?: number;
}

/**
 * Path-based marker for memories that live in the dedicated
 * reasoning-traces/ subtree. Using a path segment keeps this cheap: no
 * frontmatter parsing or extra I/O is needed.
 */
export function isReasoningTracePath(candidatePath: string): boolean {
  if (typeof candidatePath !== "string") return false;
  // Match "/reasoning-traces/" as a full path segment to avoid false
  // positives like "my-reasoning-traces-notes/".
  return /(^|[\\/])reasoning-traces([\\/]|$)/.test(candidatePath);
}

/**
 * Default additive boost applied to a reasoning_trace candidate when the
 * current query looks like a problem-solving ask.
 *
 * Chosen to be roughly the same magnitude as the existing CATEGORY_BOOSTS
 * entry for reasoning_trace (0.09 in importance scoring), keeping the signal
 * visible but not overwhelming stronger lexical/vector matches.
 */
export const DEFAULT_REASONING_TRACE_BOOST = 0.15;

export interface ApplyReasoningTraceBoostOptions {
  enabled: boolean;
  query: string;
  boost?: number;
}

/**
 * The relevance a row is compared on: its effective relevance when a rerank
 * stage left one (MMR ranks on the same basis), else the raw retrieval score.
 */
function comparisonRelevance(row: BoostableResult): number {
  if (typeof row.effectiveScore === "number" && Number.isFinite(row.effectiveScore)) {
    return row.effectiveScore;
  }
  return typeof row.score === "number" && Number.isFinite(row.score) ? row.score : 0;
}

/**
 * Apply a score boost to results whose path sits under reasoning-traces/
 * when the query looks like a problem-solving ask. Returns a new array;
 * the input array is not mutated.
 *
 * Ordering policy: the helper walks the results in order, boosts every
 * matching reasoning trace in place, then promotes each boosted trace
 * upward PAST any non-boosted neighbor whose score is strictly lower
 * than the trace's boosted score. Non-matching results keep their
 * incoming relative order — so reranker-driven path ordering and any
 * other upstream nudges on non-trace items are preserved. We do NOT
 * re-sort the full list, which would wipe out rerank priority on
 * non-trace items (whose numeric scores may have been left stale by the
 * rerank pass). This matters because MMR runs immediately after and
 * truncates to a topN window — globally re-sorting would silently drop
 * reranker-promoted items below the cutoff.
 *
 * No-ops (returns a copy of the input unchanged) when:
 *  - `enabled` is false,
 *  - `query` is empty / not a problem-solving ask,
 *  - the result list contains no reasoning-trace paths.
 *
 * Note on legacy paths: this helper intentionally only matches paths
 * under the dedicated `reasoning-traces/` subtree introduced by PR 3.
 * Historical reasoning_trace memories (if any) written before that
 * subtree existed were routed to `facts/<date>/` and are NOT
 * boost-eligible. Operators upgrading across that boundary should run
 * the migration CLI or rewrite old paths before enabling the boost.
 */
export function applyReasoningTraceBoost<R extends BoostableResult>(
  results: readonly R[],
  options: ApplyReasoningTraceBoostOptions,
): R[] {
  if (!options.enabled) return [...results];
  if (!Array.isArray(results) || results.length === 0) return [...results];
  if (!looksLikeProblemSolvingQuery(options.query)) return [...results];

  const boostAmount =
    typeof options.boost === "number" && Number.isFinite(options.boost) && options.boost >= 0
      ? options.boost
      : DEFAULT_REASONING_TRACE_BOOST;

  // Step 1: boost the scores of matching traces, preserving positions.
  const boosted: R[] = [];
  let changed = false;
  for (const r of results) {
    if (isReasoningTracePath(r.path)) {
      changed = true;
      const baseScore = typeof r.score === "number" && Number.isFinite(r.score) ? r.score : 0;
      // Compose the boost into the effective relevance too: a downstream MMR
      // pass prefers it over the raw score, so a stale value would drop the
      // boost.
      const effective =
        typeof r.effectiveScore === "number" && Number.isFinite(r.effectiveScore)
          ? r.effectiveScore + boostAmount
          : undefined;
      boosted.push(
        effective === undefined
          ? ({ ...r, score: baseScore + boostAmount } as R)
          : ({ ...r, score: baseScore + boostAmount, effectiveScore: effective } as R),
      );
    } else {
      boosted.push(r);
    }
  }
  if (!changed) return boosted;

  // Step 2: promote each boosted trace upward past any non-trace neighbor
  // whose relevance is strictly lower than the boosted trace's. The
  // comparison uses the SAME basis MMR ranks on — the effective relevance a
  // rerank stage left behind, else the raw score — so the boost cannot
  // promote a trace the pipeline deliberately demoted. Non-trace items never
  // move past each other, so reranker-driven ordering on non-trace items is
  // preserved.
  const out = boosted.slice();
  for (let i = 0; i < out.length; i++) {
    if (!isReasoningTracePath(out[i].path)) continue;
    const trace = out[i];
    const traceScore = comparisonRelevance(trace);
    let j = i;
    while (j > 0) {
      const prev = out[j - 1];
      if (isReasoningTracePath(prev.path)) break; // don't reorder traces vs each other
      const prevScore = comparisonRelevance(prev);
      if (prevScore >= traceScore) break;
      out[j] = prev;
      j -= 1;
    }
    if (j !== i) out[j] = trace;
  }

  return out;
}

import type { MemoryFile, QmdSearchResult } from "./types.js";

export function memoryMapKey(result: Pick<QmdSearchResult, "namespace" | "path">): string {
  // No namespace -> bare path (backward-compatible with path-keyed lookups).
  // Namespaced -> composite so the same relative path across namespaces stays distinct.
  return result.namespace ? `${result.namespace}\0${result.path}` : result.path;
}

export function memoryForResult(
  memoryByPath: ReadonlyMap<string, MemoryFile>,
  result: Pick<QmdSearchResult, "namespace" | "path">,
): MemoryFile | undefined {
  return memoryByPath.get(memoryMapKey(result));
}

export function hasMemoryForResult(
  memoryByPath: ReadonlyMap<string, MemoryFile>,
  result: Pick<QmdSearchResult, "namespace" | "path">,
): boolean {
  return memoryByPath.has(memoryMapKey(result));
}

export function markResultKey(
  keys: Set<string>,
  result: Pick<QmdSearchResult, "namespace" | "path">,
): void {
  keys.add(memoryMapKey(result));
}

export function resultHasKey(
  keys: ReadonlySet<string>,
  result: Pick<QmdSearchResult, "namespace" | "path">,
): boolean {
  return keys.has(memoryMapKey(result));
}

/**
 * Merge recall results from multiple producers, deduplicating by the composite
 * (namespace, path) identity so the same memory found by a fanout hit and a
 * seed/hybrid/archive hit collapses to ONE entry instead of being injected and
 * access-tracked twice (#2020). The namespace is resolved the SAME way on every
 * producer — carried when present, else derived from the path — and stamped on
 * the surviving result. Highest score wins; a surviving result keeps its own
 * snippet, falling back to the displaced entry's snippet when empty. Results are
 * returned sorted by descending score and capped to `limit`.
 */
export function dedupeResultsByNamespace(
  results: readonly QmdSearchResult[],
  namespaceFromPath: (path: string) => string,
  limit: number,
  options?: {
    transportFallback?: QmdSearchResult["transport"];
    filter?: (result: QmdSearchResult) => boolean;
  },
): QmdSearchResult[] {
  const merged = new Map<string, QmdSearchResult>();
  for (const result of results) {
    const namespace = result.namespace ?? namespaceFromPath(result.path);
    const key = `${namespace}\0${result.path || result.docid}`;
    const existing = merged.get(key);
    if (existing && result.score <= existing.score) continue;
    merged.set(key, {
      ...result,
      namespace,
      ...(options?.transportFallback !== undefined
        ? { transport: result.transport ?? options.transportFallback }
        : {}),
      snippet: result.snippet || existing?.snippet || "",
    });
  }
  let out = [...merged.values()];
  if (options?.filter) out = out.filter(options.filter);
  return out.sort((a, b) => b.score - a.score).slice(0, limit);
}

export function collapseWhitespace(value: string): string {
  return value.replace(/\s+/g, " ").trim();
}

export function truncateCodePointSafe(value: string, maxChars: number): string {
  const glyphs = Array.from(value);
  if (maxChars <= 0) return "";
  if (glyphs.length <= maxChars) return value;
  return glyphs.slice(0, Math.max(1, maxChars)).join("").trimEnd();
}

let graphemeSegmenter: Intl.Segmenter | null | undefined;

function getGraphemeSegmenter(): Intl.Segmenter | null {
  if (graphemeSegmenter === undefined) {
    graphemeSegmenter =
      typeof Intl !== "undefined" && typeof Intl.Segmenter === "function"
        ? new Intl.Segmenter(undefined, { granularity: "grapheme" })
        : null;
  }
  return graphemeSegmenter;
}

/**
 * Longest prefix of `value` whose UTF-16 length stays within `maxChars`
 * without splitting a surrogate pair or a grapheme cluster (ZWJ emoji
 * sequences, flags, Hangul jamo runs, combining marks). A cluster wider than
 * the budget is dropped whole rather than split. Falls back to code-point
 * boundaries when Intl.Segmenter is unavailable.
 */
export function truncateGraphemeSafe(value: string, maxChars: number): string {
  if (maxChars <= 0) return "";
  if (value.length <= maxChars) return value;
  let truncated = "";
  for (const unit of graphemeUnits(value)) {
    if (truncated.length + unit.length > maxChars) break;
    truncated += unit;
  }
  return truncated;
}

/**
 * Grapheme clusters of `value` as separate strings, or its code points when
 * Intl.Segmenter is unavailable.
 */
export function graphemeUnits(value: string): string[] {
  const segmenter = getGraphemeSegmenter();
  if (segmenter === null) return [...value];
  return Array.from(segmenter.segment(value), (segment) => segment.segment);
}

const COMBINING_MARK = /\p{M}/u;
const FORMAT_CHAR = /\p{Cf}/u;
const EMOJI_PRESENTATION = /\p{Emoji_Presentation}/u;
const EMOJI_PRESENTATION_SELECTOR = "\uFE0F";

// ponytail: pragmatic East_Asian_Width Wide/Fullwidth subset - contiguous
// block ranges plus the emoji presentation planes. Sparse exceptions inside
// those ranges (narrow unassigned code points, U+303F) do not matter for
// terminal column alignment; switch to a full EAW table only if drift shows.
const WIDE_CODE_POINT_RANGES: ReadonlyArray<readonly [number, number]> = [
  [0x1100, 0x115f], // Hangul Jamo
  [0x2e80, 0x303e], // CJK radicals, Kangxi radicals, CJK symbols and punctuation
  [0x3041, 0x33ff], // Hiragana, Katakana, Bopomofo, Hangul compatibility jamo
  [0x3400, 0x4dbf], // CJK unified ideographs extension A
  [0x4e00, 0xa4cf], // CJK unified ideographs, Yi
  [0xa960, 0xa97f], // Hangul Jamo extension A
  [0xac00, 0xd7a3], // Hangul syllables
  [0xf900, 0xfaff], // CJK compatibility ideographs
  [0xfe10, 0xfe19], // Vertical forms
  [0xfe30, 0xfe6b], // CJK compatibility forms
  [0xff00, 0xff60], // Fullwidth ASCII and punctuation
  [0xffe0, 0xffe6], // Fullwidth signs
  [0x1f300, 0x1f64f], // Emoji symbols, pictographs, emoticons
  [0x1f680, 0x1f6ff], // Transport and map
  [0x1f900, 0x1f9ff], // Supplemental symbols
  [0x1fa70, 0x1faff], // Symbols and pictographs extended-A
  [0x20000, 0x2fffd], // CJK extensions B-F
  [0x30000, 0x3fffd], // CJK extension G and later
];

function isWideGlyph(glyph: string): boolean {
  const codePoint = glyph.codePointAt(0)!;
  let low = 0;
  let high = WIDE_CODE_POINT_RANGES.length - 1;
  while (low <= high) {
    const mid = (low + high) >> 1;
    const [start, end] = WIDE_CODE_POINT_RANGES[mid]!;
    if (codePoint < start) high = mid - 1;
    else if (codePoint > end) low = mid + 1;
    else return true;
  }
  return false;
}

/**
 * Terminal cell width: East_Asian_Width Wide/Fullwidth glyphs count as 2,
 * combining marks and format characters (ZWJ, variation selectors) as 0,
 * everything else as 1. A grapheme cluster with emoji presentation - ZWJ
 * sequences, flags, skin-tone modifiers - occupies two cells.
 */
export function displayWidth(value: string): number {
  let width = 0;
  for (const cluster of graphemeUnits(value)) {
    width += graphemeClusterWidth(cluster);
  }
  return width;
}

function graphemeClusterWidth(cluster: string): number {
  if (cluster.includes(EMOJI_PRESENTATION_SELECTOR)) return 2;
  let emojiCluster = false;
  let width = 0;
  for (const glyph of cluster) {
    if (COMBINING_MARK.test(glyph) || FORMAT_CHAR.test(glyph)) continue;
    if (EMOJI_PRESENTATION.test(glyph)) emojiCluster = true;
    width += isWideGlyph(glyph) ? 2 : 1;
  }
  return emojiCluster ? 2 : width;
}

/**
 * padEnd analog that pads to a terminal cell width, so rows containing CJK
 * or emoji keep their columns aligned.
 */
export function padEndDisplay(value: string, targetWidth: number): string {
  const padding = targetWidth - displayWidth(value);
  return padding > 0 ? value + " ".repeat(padding) : value;
}

/**
 * Temporal and Tag Indexes (v8.1 — SwiftMem-inspired)
 *
 * Maintains two fast on-disk lookup structures in `state/`:
 *   index_time.json — maps YYYY-MM-DD date buckets to memory file paths
 *   index_tags.json — maps tag strings to memory file paths
 *
 * Used as an optional prefilter in the retrieval pipeline:
 * given a time range or a set of tags, narrow the candidate set
 * before the QMD hybrid search so we can pass a smaller pool to scoring.
 *
 * Design constraints:
 * - Must be fail-open (any error returns empty / unfiltered)
 * - Reads/writes are batched per extraction run
 * - Both indexes are plain JSON; no external dependencies
 */

import { execFile } from "node:child_process";
import * as crypto from "node:crypto";
import * as fs from "node:fs";
import * as path from "node:path";
import { setTimeout as delay } from "node:timers/promises";
import { promisify } from "node:util";

const execFileAsync = promisify(execFile);

export {
  clearIndexes,
  deindexMemory,
  indexMemoriesBatch,
  indexMemory,
  indexesExist,
} from "./temporal-index-compat.js";

export {
  deindexMemoriesBatchAsync,
  indexMemoriesBatchAsync,
} from "./temporal-index-batch.js";

export interface TemporalIndex {
  /** version bumped when schema changes */
  version: number;
  /** Last full rebuild timestamp (ISO string) */
  lastRebuildAt?: string;
  /** Map from YYYY-MM-DD → array of memory paths */
  dates: Record<string, string[]>;
  /**
   * Per-memory event-time rows used to reconstruct one chronology across
   * source sessions. Keyed by path so an update replaces the prior row.
   */
  events: Record<string, TemporalIndexEvent>;
}

export interface TemporalIndexEvent {
  path: string;
  /** Event/valid time used for chronology. */
  eventAt: string;
  /** Ingest/source-observation time, when known. */
  observedAt?: string;
  /** Source session provenance, when the extractor recorded it. */
  sessionKey?: string;
  /** Exclusive validity end, when the event is bounded. */
  validUntil?: string;
  /** SHA-256 lexical fingerprints for bounded query-aware candidate selection. */
  searchTokenHashes?: string[];
}

export interface TemporalIndexEntry {
  path: string;
  createdAt: string;
  tags: string[];
  validAt?: string;
  observedAt?: string;
  sessionKey?: string;
  validUntil?: string;
  /** Used only to derive token hashes; raw text is never persisted in the index. */
  searchText?: string;
}

export interface TagIndex {
  version: number;
  lastRebuildAt?: string;
  /** Map from canonical tag string → node metadata */
  tags: Record<string, TagNode | string[]>;
  /** Map from alias string → canonical tags */
  aliases?: Record<string, string[]>;
}

export interface TagNode {
  paths: string[];
  aliases?: string[];
  parents?: string[];
}

export const INDEX_VERSION = 2;
const TEMPORAL_INDEX_FILE = "index_time.json";
const TAG_INDEX_FILE = "index_tags.json";
const TAG_INDEX_VERSION = 2;
const INDEX_LOCK_STALE_MS = 60_000;
const INDEX_LOCK_POLL_MS = 10;
const INDEX_PROCESS_START_TOLERANCE_MS = 2_000;
const INDEX_PROCESS_STARTED_AT_MS = Date.now() - process.uptime() * 1000;

interface IndexFileIdentity {
  size: number;
  mtimeMs: number;
  ctimeMs: number;
  ino: number;
}

interface CachedIndex<T> {
  identity: IndexFileIdentity;
  index: T;
  currentSchema: boolean;
}

type IndexLoadResult<T> =
  | { kind: "ok"; index: T; currentSchema: boolean }
  | { kind: "missing" }
  | { kind: "invalid" };

const parsedIndexCache = new Map<string, CachedIndex<unknown>>();
const writeChains = new Map<string, Promise<void>>();
// Operation-level serialization keyed by memoryDir (issue #1911, Codex Medium):
// a single logical index mutation touches TWO files (temporal + tag), each with
// its own per-file writeChain. Without an outer lock, two overlapping
// indexMemoryAsync calls could interleave so the temporal half of one commits
// with the tag half of the other. This chain makes each public mutator's paired
// writes atomic relative to other mutators on the same memoryDir.
const opChains = new Map<string, Promise<void>>();
let indexReadObserverForTest: (() => void) | undefined;

/** Test-only observer for asserting cache read/parse behavior. */
export function setIndexReadObserverForTest(observer?: () => void): void {
  indexReadObserverForTest = observer;
}

let indexWriteObserverForTest: ((filePath: string) => void) | undefined;

/** Test-only observer fired once per committed atomic index write. */
export function setIndexWriteObserverForTest(observer?: (filePath: string) => void): void {
  indexWriteObserverForTest = observer;
}

let indexWriteFailureForTest: ((filePath: string) => boolean) | undefined;

/**
 * Test-only hook to deterministically fail an atomic index write for matching
 * paths. Return true to fail the write for a given path. Lets partial-failure
 * branches be exercised without relying on filesystem permissions, which no-op
 * for privileged users (common in containerized CI) and differ on Windows.
 */
export function setIndexWriteFailureForTest(shouldFail?: (filePath: string) => boolean): void {
  indexWriteFailureForTest = shouldFail;
}

interface IndexLockOwner {
  pid: number;
  createdAt?: string;
  processStartedAtMs?: number;
}

type IndexLockCleanupResult = "removed" | "wait" | "blocked";

function stateDir(memoryDir: string): string {
  return path.join(memoryDir, "state");
}

function temporalIndexPath(memoryDir: string): string {
  return path.join(stateDir(memoryDir), TEMPORAL_INDEX_FILE);
}

function tagIndexPath(memoryDir: string): string {
  return path.join(stateDir(memoryDir), TAG_INDEX_FILE);
}

export async function ensureStateDir(memoryDir: string): Promise<void> {
  await fs.promises.mkdir(stateDir(memoryDir), { recursive: true });
}

function identityFromStat(stat: fs.Stats): IndexFileIdentity {
  return {
    size: stat.size,
    mtimeMs: stat.mtimeMs,
    ctimeMs: stat.ctimeMs,
    ino: stat.ino,
  };
}

function identityEquals(left: IndexFileIdentity, right: IndexFileIdentity): boolean {
  return left.size === right.size &&
    left.mtimeMs === right.mtimeMs &&
    left.ctimeMs === right.ctimeMs &&
    left.ino === right.ino;
}

async function loadIndexCached<T>(
  filePath: string,
  normalize: (raw: unknown) => T,
  hasCurrentSchema: (raw: unknown) => boolean,
): Promise<IndexLoadResult<T>> {
  let handle: fs.promises.FileHandle;
  try {
    handle = await fs.promises.open(filePath, "r");
  } catch (error) {
    return (error as NodeJS.ErrnoException)?.code === "ENOENT"
      ? { kind: "missing" }
      : { kind: "invalid" };
  }

  try {
    const identity = identityFromStat(await handle.stat());
    const cached = parsedIndexCache.get(filePath) as CachedIndex<T> | undefined;
    if (cached && identityEquals(cached.identity, identity)) {
      return { kind: "ok", index: cached.index, currentSchema: cached.currentSchema };
    }
    indexReadObserverForTest?.();
    const parsed = JSON.parse(await handle.readFile("utf8")) as unknown;
    const index = normalize(parsed);
    const currentSchema = hasCurrentSchema(parsed);
    parsedIndexCache.set(filePath, { identity, index, currentSchema });
    return { kind: "ok", index, currentSchema };
  } catch {
    parsedIndexCache.delete(filePath);
    return { kind: "invalid" };
  } finally {
    await handle.close().catch(() => undefined);
  }
}

function withPathMutex<T>(filePath: string, update: () => Promise<T>): Promise<T> {
  const previous = writeChains.get(filePath) ?? Promise.resolve();
  const run = previous.then(update, update);
  const tail = run.then(() => undefined, () => undefined);
  writeChains.set(filePath, tail);
  void tail.then(() => {
    if (writeChains.get(filePath) === tail) writeChains.delete(filePath);
  });
  return run;
}

/**
 * Operation-level mutex keyed by memoryDir (issue #1911, Codex Medium). Wraps a
 * whole logical index mutation (which writes BOTH the temporal and tag index
 * files) so overlapping mutators on the same memoryDir cannot interleave their
 * per-file writes and commit mismatched halves. The inner per-file writeChains
 * still protect each file; this outer chain just orders complete operations.
 */
export function withMemoryDirMutex<T>(memoryDir: string, op: () => Promise<T>): Promise<T> {
  const previous = opChains.get(memoryDir) ?? Promise.resolve();
  const run = previous.then(op, op);
  const tail = run.then(() => undefined, () => undefined);
  opChains.set(memoryDir, tail);
  void tail.then(() => {
    if (opChains.get(memoryDir) === tail) opChains.delete(memoryDir);
  });
  return run;
}
async function primeCacheAfterWrite(
  filePath: string,
  index: unknown,
  isCurrentSchema: () => boolean,
): Promise<void> {
  try {
    const identity = identityFromStat(await fs.promises.stat(filePath));
    // Derive currentSchema from the ACTUAL written index (issue #1911, Codex):
    // hardcoding true let deindexMemoryAsync (which does not bump version) cache
    // an old-schema index as current, so indexesExistAsync then skipped a
    // needed rebuild. The tag index is always current (no version gate); the
    // temporal index is current only when hasCurrentTemporalIndexSchema holds.
    parsedIndexCache.set(filePath, { identity, index, currentSchema: isCurrentSchema() });
  } catch {
    parsedIndexCache.delete(filePath);
  }
}

function uniqueTempPath(filePath: string): string {
  const dir = path.dirname(filePath);
  const base = path.basename(filePath);
  const nonce = crypto.randomBytes(6).toString("hex");
  return path.join(dir, `.${base}.${process.pid}.${Date.now()}.${nonce}.tmp`);
}

function lockOwnerPath(lockDir: string): string {
  return path.join(lockDir, "owner.json");
}

async function writeIndexLockOwner(lockDir: string): Promise<void> {
  try {
    await fs.promises.writeFile(
      lockOwnerPath(lockDir),
      JSON.stringify({
        pid: process.pid,
        createdAt: new Date().toISOString(),
        processStartedAtMs: INDEX_PROCESS_STARTED_AT_MS,
      }),
      {
        encoding: "utf8",
        flag: "wx",
      }
    );
  } catch {
    // Fail silently — the directory lock is still the serialization primitive.
  }
}

async function readIndexLockOwner(lockDir: string): Promise<IndexLockOwner | null> {
  try {
    const parsed = JSON.parse(await fs.promises.readFile(lockOwnerPath(lockDir), "utf8")) as { pid?: unknown };
    if (!(typeof parsed.pid === "number" && Number.isInteger(parsed.pid) && parsed.pid > 0)) return null;
    const owner: IndexLockOwner = { pid: parsed.pid };
    if (
      "createdAt" in parsed &&
      typeof (parsed as { createdAt?: unknown }).createdAt === "string" &&
      (parsed as { createdAt: string }).createdAt.length > 0
    ) {
      owner.createdAt = (parsed as { createdAt: string }).createdAt;
    }
    const processStartedAtMs = (parsed as { processStartedAtMs?: unknown }).processStartedAtMs;
    if (typeof processStartedAtMs === "number" && Number.isFinite(processStartedAtMs) && processStartedAtMs > 0) {
      owner.processStartedAtMs = processStartedAtMs;
    }
    return owner;
  } catch {
    return null;
  }
}

function processIsAlive(pid: number): boolean {
  try {
    process.kill(pid, 0);
    return true;
  } catch (error) {
    const code = (error as NodeJS.ErrnoException)?.code;
    return code === "EPERM";
  }
}

async function readProcessStartedAtMs(pid: number): Promise<number | null> {
  try {
    const { stdout } = await execFileAsync("ps", ["-p", String(pid), "-o", "lstart="], {
      encoding: "utf8",
      timeout: 1_000,
    });
    const output = stdout.trim();
    if (!output) return null;
    const startedAtMs = Date.parse(output);
    return Number.isFinite(startedAtMs) ? startedAtMs : null;
  } catch {
    return null;
  }
}

async function lockOwnerIsRunning(owner: IndexLockOwner): Promise<boolean> {
  if (!processIsAlive(owner.pid)) return false;
  if (owner.processStartedAtMs === undefined) return true;
  const runningStartedAtMs = await readProcessStartedAtMs(owner.pid);
  if (runningStartedAtMs === null) return true;
  return runningStartedAtMs <= owner.processStartedAtMs + INDEX_PROCESS_START_TOLERANCE_MS;
}

function lockIsFresh(lockInfo: fs.Stats, owner: IndexLockOwner | null): boolean {
  const ownerCreatedAtMs =
    typeof owner?.createdAt === "string" && owner.createdAt.length > 0 ? Date.parse(owner.createdAt) : Number.NaN;
  const referenceMs = Number.isFinite(ownerCreatedAtMs) ? ownerCreatedAtMs : lockInfo.mtimeMs;
  return Date.now() - referenceMs < INDEX_LOCK_STALE_MS;
}

async function removeAbandonedIndexLock(lockDir: string): Promise<IndexLockCleanupResult> {
  try {
    const info = await fs.promises.lstat(lockDir);
    if (info.isSymbolicLink()) return "blocked";
    if (!info.isDirectory()) {
      await fs.promises.rm(lockDir, { force: true });
      return "removed";
    }
    const owner = await readIndexLockOwner(lockDir);
    if (owner !== null) {
      if (await lockOwnerIsRunning(owner)) return "wait";
    }
    if (owner === null && lockIsFresh(info, null)) return "wait";
    await fs.promises.rm(lockDir, { recursive: true, force: true });
    return "removed";
  } catch (error) {
    if ((error as NodeJS.ErrnoException)?.code === "ENOENT") return "removed";
    // Fail silently — indexes are advisory only
    return "blocked";
  }
}

async function withIndexFileLock<T>(filePath: string, update: () => Promise<T>): Promise<T | undefined> {
  const lockDir = `${filePath}.lock.d`;
  let acquired = false;

  while (!acquired) {
    try {
      await fs.promises.mkdir(lockDir);
      await writeIndexLockOwner(lockDir);
      acquired = true;
    } catch (error) {
      const code = (error as NodeJS.ErrnoException)?.code;
      if (code === "ENOENT") {
        try {
          await fs.promises.mkdir(path.dirname(lockDir), { recursive: true });
        } catch {
          return undefined;
        }
        await delay(INDEX_LOCK_POLL_MS);
        continue;
      }
      if (code !== "EEXIST") return undefined;
      const cleanupResult = await removeAbandonedIndexLock(lockDir);
      if (cleanupResult === "blocked") return undefined;
      await delay(INDEX_LOCK_POLL_MS);
    }
  }

  let result: T;
  try {
    result = await update();
  } finally {
    try {
      await fs.promises.rm(lockDir, { recursive: true, force: true });
    } catch {
      // Fail silently — indexes are advisory only
    }
  }
  return result;
}

/**
 * Atomic write: write to a unique `.tmp` sibling then rename so readers never
 * observe a partially-written file.
 */
async function writeJsonAtomic(filePath: string, data: unknown): Promise<boolean> {
  const payload = JSON.stringify(data);
  for (let attempt = 0; attempt < 3; attempt += 1) {
    const tmp = uniqueTempPath(filePath);
    try {
      if (indexWriteFailureForTest?.(filePath)) {
        throw new Error("injected atomic-write failure (test)");
      }
      await fs.promises.writeFile(tmp, payload, "utf8");
      await fs.promises.rename(tmp, filePath);
      // The observer fires only after the committed rename. Isolate its
      // exceptions so a test hook can never turn a successful write into a
      // retry or a false (failed) result, which would clear the cache and
      // skip the paired tag-index phase.
      try {
        indexWriteObserverForTest?.(filePath);
      } catch {
        // Test hooks must not alter committed index-write results.
      }
      return true;
    } catch {
      try {
        await fs.promises.unlink(tmp);
      } catch {
        // Fail silently — indexes are advisory only
      }
      await delay(INDEX_LOCK_POLL_MS);
    }
  }
  return false;
}

function emptyTemporalIndex(): TemporalIndex {
  return { version: INDEX_VERSION, dates: {}, events: {} };
}

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

function normalizeTemporalIndex(raw: TemporalIndex | null | undefined): TemporalIndex {
  if (!isRecord(raw)) return emptyTemporalIndex();
  return {
    version: typeof raw.version === "number" ? raw.version : 0,
    dates: isRecord(raw.dates) ? raw.dates as Record<string, string[]> : {},
    events: isRecord(raw.events) ? raw.events as Record<string, TemporalIndexEvent> : {},
    ...(typeof raw.lastRebuildAt === "string" ? { lastRebuildAt: raw.lastRebuildAt } : {}),
  };
}

function hasCurrentTemporalIndexSchema(raw: unknown): boolean {
  return isRecord(raw) &&
    raw.version === INDEX_VERSION &&
    isRecord(raw.dates) &&
    isRecord(raw.events);
}

export async function updateTemporalIndex(memoryDir: string, update: (index: TemporalIndex) => void): Promise<boolean> {
  const indexPath = temporalIndexPath(memoryDir);
  return withPathMutex(indexPath, async () => {
    const ok = await withIndexFileLock(indexPath, async () => {
      const loaded = await loadIndexCached(
        indexPath,
        (raw) => normalizeTemporalIndex(raw as TemporalIndex),
        hasCurrentTemporalIndexSchema,
      );
      const index = structuredClone(loaded.kind === "ok" ? loaded.index : emptyTemporalIndex());
      update(index);
      if (await writeJsonAtomic(indexPath, index)) {
        await primeCacheAfterWrite(indexPath, index, () => hasCurrentTemporalIndexSchema(index));
        return true;
      }
      parsedIndexCache.delete(indexPath);
      return false;
    });
    return ok === true;
  });
}

export async function updateTagIndex(memoryDir: string, update: (index: TagIndex) => void): Promise<void> {
  const indexPath = tagIndexPath(memoryDir);
  await withPathMutex(indexPath, async () => {
    await withIndexFileLock(indexPath, async () => {
      const loaded = await loadIndexCached(
        indexPath,
        (raw) => normalizeTagIndex(raw as TagIndex),
        () => true,
      );
      const index = structuredClone(
        loaded.kind === "ok"
          ? loaded.index
          : { version: TAG_INDEX_VERSION, tags: {}, aliases: {} },
      );
      update(index);
      if (await writeJsonAtomic(indexPath, index)) {
        await primeCacheAfterWrite(indexPath, index, () => true);
      } else {
        parsedIndexCache.delete(indexPath);
      }
    });
  });
}

export function isoDateFromTimestamp(isoString: string): string {
  if (typeof isoString !== "string" || isoString.length < 10) {
    // Malformed frontmatter — fall back to today so the memory is still indexed.
    // Log a warning to surface data-quality issues without aborting the write.
    console.warn(`[engram] temporal-index: malformed timestamp "${isoString}", falling back to today`);
    return new Date().toISOString().slice(0, 10);
  }
  return isoString.slice(0, 10); // YYYY-MM-DD
}

function normalizedIsoTimestamp(value: string | undefined): string | undefined {
  if (typeof value !== "string" || value.trim().length === 0) return undefined;
  const ms = Date.parse(value);
  if (!Number.isFinite(ms)) return undefined;
  try {
    return new Date(ms).toISOString();
  } catch {
    return undefined;
  }
}

export function temporalEventFromEntry(entry: TemporalIndexEntry): TemporalIndexEvent {
  const createdAt = normalizedIsoTimestamp(entry.createdAt) ?? new Date(0).toISOString();
  const eventAt = normalizedIsoTimestamp(entry.validAt) ?? createdAt;
  const observedAt = normalizedIsoTimestamp(entry.observedAt);
  const validUntil = normalizedIsoTimestamp(entry.validUntil);
  const sessionKey = typeof entry.sessionKey === "string" && entry.sessionKey.trim().length > 0
    ? entry.sessionKey.replace(/[\u0000-\u001f\u007f]+/g, " ").trim()
    : undefined;
  const searchTokenHashes = temporalSearchTokenHashes(entry.searchText);
  return {
    path: entry.path,
    eventAt,
    ...(observedAt ? { observedAt } : {}),
    ...(sessionKey ? { sessionKey } : {}),
    ...(validUntil ? { validUntil } : {}),
    ...(searchTokenHashes.length > 0 ? { searchTokenHashes } : {}),
  };
}

function temporalSearchTokens(value: string | undefined): string[] {
  if (!value) return [];
  const tokens = value
    .toLowerCase()
    .match(/[\p{L}\p{N}][\p{L}\p{N}'_-]*/gu)
    ?.filter((token) => token.length > 1) ?? [];
  return [...new Set(tokens)].slice(0, 128);
}

function temporalSearchTokenHashes(value: string | undefined): string[] {
  return temporalSearchTokens(value).map((token) =>
    crypto.createHash("sha256").update(token).digest("hex"),
  );
}

function compareTemporalIndexEvents(
  left: TemporalIndexEvent,
  right: TemporalIndexEvent,
): number {
  const byEvent = left.eventAt.localeCompare(right.eventAt);
  if (byEvent !== 0) return byEvent;
  const byObservation = (left.observedAt ?? "").localeCompare(right.observedAt ?? "");
  if (byObservation !== 0) return byObservation;
  return left.path.localeCompare(right.path);
}

export function addPathToSet(record: Record<string, string[]>, key: string, p: string): void {
  if (!record[key]) {
    record[key] = [];
  }
  if (!record[key].includes(p)) {
    record[key].push(p);
  }
}

export function removePathFromSet(record: Record<string, string[]>, key: string, p: string): void {
  if (!record[key]) return;
  record[key] = record[key].filter((x) => x !== p);
  if (record[key].length === 0) {
    delete record[key];
  }
}

export function removePathFromAllSets(record: Record<string, string[]>, p: string): void {
  for (const key of Object.keys(record)) {
    removePathFromSet(record, key, p);
  }
}

function normalizeTagSegment(segment: string): string {
  return segment
    .trim()
    .toLowerCase()
    .replace(/[_\s]+/g, "-")
    .replace(/[^a-z0-9-]/g, "-")
    .replace(/-+/g, "-")
    .replace(/^-|-$/g, "");
}

function normalizeCanonicalTag(tag: string): string {
  return tag
    .trim()
    .toLowerCase()
    .replace(/\s*[>:|.]+\s*/g, "/")
    .replace(/\s*\/\s*/g, "/")
    .split("/")
    .map(normalizeTagSegment)
    .filter(Boolean)
    .join("/");
}

function normalizeAliasKey(tag: string): string {
  return tag
    .trim()
    .toLowerCase()
    .replace(/[\/_.:-]+/g, " ")
    .replace(/[-]+/g, " ")
    .replace(/[^a-z0-9\s]+/g, " ")
    .replace(/\s+/g, " ")
    .trim();
}

function singularizeAlias(alias: string): string | null {
  if (!alias.endsWith("s") || alias.length <= 3) return null;
  return alias.slice(0, -1);
}

function deriveParentTags(canonical: string): string[] {
  const parts = canonical.split("/").filter(Boolean);
  const parents: string[] = [];
  for (let i = parts.length - 1; i > 0; i -= 1) {
    parents.push(parts.slice(0, i).join("/"));
  }
  return parents;
}

function deriveTagAliases(rawTag: string, canonical: string): string[] {
  const aliases = new Set<string>();
  const canonicalAlias = normalizeAliasKey(canonical);
  const rawAlias = normalizeAliasKey(rawTag);
  const leaf = canonical.split("/").at(-1) ?? canonical;
  const leafAlias = normalizeAliasKey(leaf);

  for (const candidate of [canonicalAlias, rawAlias, leafAlias]) {
    if (!candidate) continue;
    aliases.add(candidate);
    const singular = singularizeAlias(candidate);
    if (singular) aliases.add(singular);
  }

  return Array.from(aliases);
}

function normalizeTagIndex(raw: TagIndex | null | undefined): TagIndex {
  const normalized: TagIndex = {
    version: TAG_INDEX_VERSION,
    tags: {},
    aliases: {},
  };

  if (!raw || typeof raw !== "object") {
    return normalized;
  }

  const sourceTags = raw.tags ?? {};
  for (const [rawCanonical, nodeOrPaths] of Object.entries(sourceTags)) {
    const canonical = normalizeCanonicalTag(rawCanonical);
    if (!canonical) continue;
    const node: TagNode = Array.isArray(nodeOrPaths)
      ? { paths: [...new Set(nodeOrPaths)] }
      : {
          paths: Array.isArray(nodeOrPaths?.paths) ? [...new Set(nodeOrPaths.paths)] : [],
          aliases: Array.isArray(nodeOrPaths?.aliases) ? [...new Set(nodeOrPaths.aliases)] : [],
          parents: Array.isArray(nodeOrPaths?.parents) ? [...new Set(nodeOrPaths.parents)] : [],
        };
    const existingNode = normalized.tags[canonical];
    if (existingNode && !Array.isArray(existingNode)) {
      existingNode.paths = [...new Set([...existingNode.paths, ...node.paths])];
      existingNode.aliases = [...new Set([...(existingNode.aliases ?? []), ...(node.aliases ?? [])])];
      existingNode.parents = [...new Set([...(existingNode.parents ?? []), ...(node.parents ?? [])])];
    } else if (Array.isArray(existingNode)) {
      normalized.tags[canonical] = {
        paths: [...new Set([...existingNode, ...node.paths])],
        aliases: [...new Set(node.aliases ?? [])],
        parents: [...new Set(node.parents ?? deriveParentTags(canonical))],
      };
    } else {
      normalized.tags[canonical] = node;
    }
    for (const alias of deriveTagAliases(canonical, canonical)) {
      const list = normalized.aliases![alias] ?? [];
      if (!list.includes(canonical)) list.push(canonical);
      normalized.aliases![alias] = list;
    }
    for (const alias of node.aliases ?? []) {
      const aliasKey = normalizeAliasKey(alias);
      if (!aliasKey) continue;
      const list = normalized.aliases![aliasKey] ?? [];
      if (!list.includes(canonical)) list.push(canonical);
      normalized.aliases![aliasKey] = list;
    }
    const mergedNode = normalized.tags[canonical];
    if (mergedNode && !Array.isArray(mergedNode)) {
      mergedNode.parents = [...new Set(mergedNode.parents ?? deriveParentTags(canonical))];
    }
  }

  for (const [alias, canonicals] of Object.entries(raw.aliases ?? {})) {
    const aliasKey = normalizeAliasKey(alias);
    if (!aliasKey) continue;
    const list = normalized.aliases![aliasKey] ?? [];
    for (const canonical of canonicals ?? []) {
      const normalizedCanonical = normalizeCanonicalTag(canonical);
      if (normalizedCanonical && !list.includes(normalizedCanonical)) {
        list.push(normalizedCanonical);
      }
    }
    normalized.aliases![aliasKey] = list;
  }

  return normalized;
}

function ensureTagNode(index: TagIndex, canonical: string): TagNode {
  const existing = index.tags[canonical];
  if (existing && !Array.isArray(existing)) {
    return existing;
  }
  const created: TagNode = {
    paths: Array.isArray(existing) ? [...new Set(existing)] : [],
    aliases: [],
    parents: deriveParentTags(canonical),
  };
  index.tags[canonical] = created;
  return created;
}

export function addTagGraphEntry(index: TagIndex, rawTag: string, memoryPath: string): void {
  const canonical = normalizeCanonicalTag(rawTag);
  if (!canonical) return;
  const node = ensureTagNode(index, canonical);
  if (!node.paths.includes(memoryPath)) {
    node.paths.push(memoryPath);
  }

  for (const alias of deriveTagAliases(rawTag, canonical)) {
    const aliasKey = normalizeAliasKey(alias);
    if (!aliasKey) continue;
    if (!node.aliases?.includes(aliasKey)) {
      node.aliases = [...new Set([...(node.aliases ?? []), aliasKey])];
    }
    const list = index.aliases?.[aliasKey] ?? [];
    if (!list.includes(canonical)) {
      index.aliases![aliasKey] = [...list, canonical];
    }
  }
}

export function removeTagGraphEntry(index: TagIndex, rawTag: string, memoryPath: string): void {
  const canonical = normalizeCanonicalTag(rawTag);
  if (!canonical) return;
  const node = index.tags[canonical];
  if (!node || Array.isArray(node)) return;
  node.paths = node.paths.filter((value) => value !== memoryPath);
  if (node.paths.length === 0) {
    delete index.tags[canonical];
    pruneTagAliases(index);
  }
}

export function removePathFromAllTagEntries(index: TagIndex, memoryPath: string): void {
  for (const [canonical, nodeOrPaths] of Object.entries(index.tags)) {
    if (Array.isArray(nodeOrPaths)) {
      const paths = nodeOrPaths.filter((value) => value !== memoryPath);
      if (paths.length === 0) {
        delete index.tags[canonical];
      } else {
        index.tags[canonical] = paths;
      }
      continue;
    }

    nodeOrPaths.paths = nodeOrPaths.paths.filter((value) => value !== memoryPath);
    if (nodeOrPaths.paths.length === 0) {
      delete index.tags[canonical];
    }
  }
  pruneTagAliases(index);
}

function pruneTagAliases(index: TagIndex): void {
  if (!index.aliases) return;
  for (const [alias, canonicals] of Object.entries(index.aliases)) {
    const filtered = [...new Set(canonicals.map(normalizeCanonicalTag))].filter(
      (canonical) => canonical.length > 0 && index.tags[canonical] !== undefined
    );
    if (filtered.length === 0) {
      delete index.aliases[alias];
    } else {
      index.aliases[alias] = filtered;
    }
  }
}

function expandCanonicalTags(index: TagIndex, rawTags: string[]): string[] {
  const canonicals = new Set<string>();
  for (const rawTag of rawTags) {
    const canonical = normalizeCanonicalTag(rawTag);
    if (canonical && index.tags[canonical]) {
      canonicals.add(canonical);
    }
    const aliasKey = normalizeAliasKey(rawTag);
    for (const resolved of index.aliases?.[aliasKey] ?? []) {
      canonicals.add(resolved);
    }
  }

  const expanded = new Set<string>();
  for (const canonical of canonicals) {
    expanded.add(canonical);
    const node = index.tags[canonical];
    if (node && !Array.isArray(node)) {
      for (const parent of node.parents ?? []) {
        expanded.add(parent);
      }
    }
  }
  return Array.from(expanded);
}

function aliasPhrase(alias: string): string {
  return alias.replace(/\//g, " ").replace(/-/g, " ").replace(/\s+/g, " ").trim();
}

export type TemporalIndexCompatibilityMutation =
  | { kind: "index"; entries: TemporalIndexEntry[] }
  | { kind: "deindex"; entries: TemporalIndexEntry[] }
  | { kind: "clear" };

/** @internal Pure model shared by the deprecated synchronous compatibility surface. */
export function applyTemporalIndexCompatibilityMutation(
  raw: unknown,
  mutation: TemporalIndexCompatibilityMutation,
): TemporalIndex {
  const index = structuredClone(normalizeTemporalIndex(raw as TemporalIndex));
  if (mutation.kind === "clear") {
    return emptyTemporalIndex();
  }
  if (mutation.kind === "index") index.version = INDEX_VERSION;
  for (const entry of mutation.entries) {
    const dateKey = isoDateFromTimestamp(entry.createdAt);
    if (mutation.kind === "index") {
      removePathFromAllSets(index.dates, entry.path);
      addPathToSet(index.dates, dateKey, entry.path);
      index.events[entry.path] = temporalEventFromEntry(entry);
    } else {
      removePathFromSet(index.dates, dateKey, entry.path);
      delete index.events[entry.path];
    }
  }
  return index;
}

/** @internal Pure model shared by the deprecated synchronous compatibility surface. */
export function applyTagIndexCompatibilityMutation(
  raw: unknown,
  mutation: TemporalIndexCompatibilityMutation,
): TagIndex {
  const index = structuredClone(normalizeTagIndex(raw as TagIndex));
  if (mutation.kind === "clear") {
    return { version: TAG_INDEX_VERSION, tags: {}, aliases: {} };
  }
  for (const entry of mutation.entries) {
    if (mutation.kind === "index") {
      removePathFromAllTagEntries(index, entry.path);
      for (const tag of entry.tags) {
        if (tag && typeof tag === "string") addTagGraphEntry(index, tag, entry.path);
      }
    } else {
      for (const tag of entry.tags) {
        if (tag && typeof tag === "string") removeTagGraphEntry(index, tag, entry.path);
      }
    }
  }
  return index;
}

/** @internal Schema check shared by the deprecated synchronous compatibility surface. */
export function hasCurrentTemporalIndexSchemaForCompatibility(raw: unknown): boolean {
  return hasCurrentTemporalIndexSchema(raw);
}

// ─── Public API ────────────────────────────────────────────────────────────────

/**
 * Add (or update) a memory file in both indexes.
 *
 * @param memoryDir Root memory directory
 * @param memoryPath Absolute path to the memory file
 * @param createdAt ISO timestamp of the memory's creation date
 * @param tags Array of tag strings from the memory's frontmatter
 */
export async function indexMemoryAsync(
  memoryDir: string,
  memoryPath: string,
  createdAt: string,
  tags: string[],
  temporal: Omit<Partial<TemporalIndexEntry>, "path" | "createdAt" | "tags"> = {},
): Promise<void> {
  try {
    await ensureStateDir(memoryDir);

    const dateKey = isoDateFromTimestamp(createdAt);
    await withMemoryDirMutex(memoryDir, async () => {
      // Write the temporal half first; if its atomic write FAILS, do NOT commit
      // the tag half (issue #1911, Cursor Medium) — committing tags while
      // temporal stays unchanged leaves a durable mismatch until a later index.
      const temporalOk = await updateTemporalIndex(memoryDir, (index) => {
        index.version = INDEX_VERSION;
        removePathFromAllSets(index.dates, memoryPath);
        addPathToSet(index.dates, dateKey, memoryPath);
        index.events[memoryPath] = temporalEventFromEntry({
          path: memoryPath,
          createdAt,
          tags,
          ...temporal,
        });
      });
      if (temporalOk) {
        await updateTagIndex(memoryDir, (index) => {
          removePathFromAllTagEntries(index, memoryPath);
          for (const tag of tags) {
            if (tag && typeof tag === "string") {
              addTagGraphEntry(index, tag, memoryPath);
            }
          }
        });
      }
    });
  } catch {
    // Fail silently
  }
}

/**
 * Remove a memory file from both indexes (called on deletion/archival).
 */
export async function deindexMemoryAsync(
  memoryDir: string,
  memoryPath: string,
  createdAt: string,
  tags: string[],
): Promise<void> {
  try {
    await ensureStateDir(memoryDir);

    const dateKey = isoDateFromTimestamp(createdAt);
    await withMemoryDirMutex(memoryDir, async () => {
      const temporalOk = await updateTemporalIndex(memoryDir, (index) => {
        removePathFromSet(index.dates, dateKey, memoryPath);
        delete index.events[memoryPath];
      });
      if (temporalOk) {
        await updateTagIndex(memoryDir, (index) => {
          for (const tag of tags) {
            if (tag && typeof tag === "string") {
              removeTagGraphEntry(index, tag, memoryPath);
            }
          }
        });
      }
    });
  } catch {
    // Fail silently
  }
}

/**
 * Reset both index files to empty state.
 * Called before a full-corpus rebuild so stale paths in any surviving index
 * file do not persist after the rebuild completes.
 */
export async function clearIndexesAsync(memoryDir: string): Promise<void> {
  try {
    await ensureStateDir(memoryDir);
    await withMemoryDirMutex(memoryDir, async () => {
      const temporalOk = await updateTemporalIndex(memoryDir, (index) => {
        index.version = INDEX_VERSION;
        index.lastRebuildAt = undefined;
        index.dates = {};
        index.events = {};
      });
      if (temporalOk) {
        await updateTagIndex(memoryDir, (index) => {
          index.version = TAG_INDEX_VERSION;
          index.lastRebuildAt = undefined;
          index.tags = {};
          index.aliases = {};
        });
      }
    });
  } catch {
    // Fail silently — indexes are advisory only
  }
}

/**
 * Returns true when both index files exist on disk.
 * Used to detect first-time enablement so callers can trigger a full rebuild.
 */
export async function indexesExistAsync(memoryDir: string): Promise<boolean> {
  try {
    await fs.promises.access(tagIndexPath(memoryDir));
    const loaded = await loadIndexCached(
      temporalIndexPath(memoryDir),
      (raw) => normalizeTemporalIndex(raw as TemporalIndex),
      hasCurrentTemporalIndexSchema,
    );
    return loaded.kind === "ok" && loaded.currentSchema;
  } catch {
    return false;
  }
}

/**
 * Return the set of memory paths whose index date falls in [fromDate, toDate).
 *
 * Boundary semantics (exclusive upper bound):
 * - `fromDate` is INCLUSIVE — entries on this date ARE returned.
 * - `toDate`   is EXCLUSIVE — entries on this date are NOT returned.
 *   Pass `recencyWindowBoundsFromPrompt(query).toDate` to get the correct
 *   exclusive boundary; do NOT add +1 day yourself.
 * - Default `toDate` = tomorrow, so omitting it includes all of today.
 *
 * @param memoryDir - root memory directory (contains state/index_time.json)
 * @param fromDate  - inclusive start date, YYYY-MM-DD
 * @param toDate    - exclusive end date, YYYY-MM-DD (default: tomorrow)
 * @returns Set of matching file paths, or null if the index is unavailable.
 */
export async function queryByDateRangeAsync(
  memoryDir: string,
  fromDate: string,
  toDate?: string
): Promise<Set<string> | null> {
  try {
    const tPath = temporalIndexPath(memoryDir);
    const loaded = await loadIndexCached(
      tPath,
      (raw) => normalizeTemporalIndex(raw as TemporalIndex),
      hasCurrentTemporalIndexSchema,
    );
    if (loaded.kind === "missing") return null;
    const tIndex = loaded.kind === "ok" ? loaded.index : emptyTemporalIndex();
    // toDate is exclusive (first day NOT included). Default: tomorrow so "all of today" is included.
    const end = toDate ?? new Date(Date.now() + 86_400_000).toISOString().slice(0, 10);

    const results = new Set<string>();
    for (const [date, paths] of Object.entries(tIndex.dates)) {
      if (date >= fromDate && date < end) {
        for (const p of paths) {
          results.add(p);
        }
      }
    }
    return results;
  } catch {
    return null;
  }
}

/**
 * Return the persisted event-time rows as one deterministic cross-session
 * chronology. Equal event times are ordered by observation time, then path.
 * Returns `null` when the index is missing, corrupt, or from an older schema;
 * callers can then fail open to the pre-index recall path.
 */
export async function queryTemporalTimelineAsync(
  memoryDir: string,
  options: { query?: string; limit?: number } = {},
): Promise<TemporalIndexEvent[] | null> {
  try {
    const loaded = await loadIndexCached(
      temporalIndexPath(memoryDir),
      (raw) => normalizeTemporalIndex(raw as TemporalIndex),
      hasCurrentTemporalIndexSchema,
    );
    if (loaded.kind !== "ok" || !loaded.currentSchema) return null;
    const index = loaded.index;
    const chronology = Object.values(index.events)
      .filter((event) =>
        typeof event?.path === "string" &&
        event.path.length > 0 &&
        normalizedIsoTimestamp(event.eventAt) !== undefined
      )
      .map((event) => ({
        path: event.path,
        eventAt: normalizedIsoTimestamp(event.eventAt)!,
        ...(normalizedIsoTimestamp(event.observedAt)
          ? { observedAt: normalizedIsoTimestamp(event.observedAt) }
          : {}),
        ...(typeof event.sessionKey === "string" && event.sessionKey.trim().length > 0
          ? { sessionKey: event.sessionKey.trim() }
          : {}),
        ...(normalizedIsoTimestamp(event.validUntil)
          ? { validUntil: normalizedIsoTimestamp(event.validUntil) }
          : {}),
        ...(Array.isArray(event.searchTokenHashes)
          ? { searchTokenHashes: event.searchTokenHashes.filter((hash) => typeof hash === "string") }
          : {}),
      }))
      .sort(compareTemporalIndexEvents);
    const requestedLimit = typeof options.limit === "number" && Number.isFinite(options.limit)
      ? Math.max(0, Math.floor(options.limit))
      : chronology.length;
    if (requestedLimit === 0) return [];
    if (chronology.length <= requestedLimit) return chronology;

    const queryHashes = new Set(temporalSearchTokenHashes(options.query));
    const scored = chronology.map((event) => ({
      event,
      score: (event.searchTokenHashes ?? []).reduce(
        (sum, hash) => sum + (queryHashes.has(hash) ? 1 : 0),
        0,
      ),
    }));
    if (scored.some(({ score }) => score > 0)) {
      return scored
        .filter(({ score }) => score > 0)
        .sort((left, right) => right.score - left.score || compareTemporalIndexEvents(left.event, right.event))
        .slice(0, requestedLimit)
        .map(({ event }) => event)
        .sort(compareTemporalIndexEvents);
    }

    // No lexical match (legacy rows or generic "first/last" query): retain
    // both chronology edges so earliest and latest questions remain answerable.
    const earlyCount = Math.ceil(requestedLimit / 2);
    const lateCount = requestedLimit - earlyCount;
    const selected = [
      ...chronology.slice(0, earlyCount),
      ...(lateCount > 0 ? chronology.slice(-lateCount) : []),
    ];
    return selected.sort(compareTemporalIndexEvents);
  } catch {
    return null;
  }
}

/**
 * Async version of queryByTags — uses non-blocking fs.promises.readFile
 * to avoid blocking the Node.js event loop.
 */
export async function queryByTagsAsync(memoryDir: string, tags: string[]): Promise<Set<string> | null> {
  if (tags.length === 0) return null;
  try {
    const gPath = tagIndexPath(memoryDir);
    const loaded = await loadIndexCached(
      gPath,
      (raw) => normalizeTagIndex(raw as TagIndex),
      () => true,
    );
    if (loaded.kind !== "ok") return null;
    return queryByTagsFromIndex(loaded.index, tags);
  } catch {
    return null;
  }
}

function queryByTagsFromIndex(index: TagIndex, tags: string[]): Set<string> {
  const expandedTags = expandCanonicalTags(index, tags);
  const results = new Set<string>();
  for (const canonical of expandedTags) {
    const nodeOrPaths = index.tags[canonical];
    const paths = Array.isArray(nodeOrPaths) ? nodeOrPaths : (nodeOrPaths?.paths ?? []);
    for (const pathValue of paths) {
      results.add(pathValue);
    }
  }
  return results;
}

/**
 * Extract tags from a prompt for tag-based prefiltering.
 * Looks for hashtag-style tokens (#foo).
 * Returns lowercase, deduplicated list.
 */
export function extractTagsFromPrompt(prompt: string): string[] {
  const found = new Set<string>();

  // Match #tag style tokens
  const hashMatches = prompt.matchAll(/#([a-zA-Z][\w-]{1,30})/g);
  for (const m of hashMatches) {
    const canonical = normalizeCanonicalTag(m[1]);
    if (canonical) found.add(canonical);
  }

  return Array.from(found);
}

export async function resolvePromptTagPrefilterAsync(
  memoryDir: string,
  prompt: string
): Promise<{
  matchedTags: string[];
  expandedTags: string[];
  paths: Set<string> | null;
}> {
  const explicitTags = extractTagsFromPrompt(prompt);
  try {
    const loaded = await loadIndexCached(
      tagIndexPath(memoryDir),
      (raw) => normalizeTagIndex(raw as TagIndex),
      () => true,
    );
    if (loaded.kind !== "ok") {
      return { matchedTags: explicitTags, expandedTags: explicitTags, paths: null };
    }
    const tagIndex = loaded.index;
    const matched = new Set<string>(explicitTags);
    const normalizedPrompt = ` ${normalizeAliasKey(prompt)} `;
    const containsAlias = (alias: string): boolean => {
      const phrase = aliasPhrase(alias);
      return phrase.length > 0 && normalizedPrompt.includes(` ${phrase} `);
    };

    for (const canonical of Object.keys(tagIndex.tags)) {
      if (containsAlias(canonical)) {
        matched.add(canonical);
      }
    }
    for (const [alias, canonicals] of Object.entries(tagIndex.aliases ?? {})) {
      if (!containsAlias(alias)) continue;
      for (const canonical of canonicals) {
        matched.add(canonical);
      }
    }
    if (matched.size === 0) {
      return {
        matchedTags: [],
        expandedTags: [],
        paths: null,
      };
    }

    const expandedTags = expandCanonicalTags(tagIndex, Array.from(matched));
    const paths = queryByTagsFromIndex(tagIndex, expandedTags);
    return {
      matchedTags: Array.from(matched),
      expandedTags,
      paths,
    };
  } catch {
    return { matchedTags: explicitTags, expandedTags: explicitTags, paths: null };
  }
}

/**
 * Run a group of index reads as ONE consistent snapshot (issue #1911, Codex
 * Medium). The `read` callback executes inside a single withMemoryDirMutex
 * acquisition — the same in-memory op-lock every async mutator holds across its
 * paired temporal+tag writes — so no mutation can land between the reads inside
 * it. A recall that reads the temporal and tag indexes together therefore never
 * observes a half-updated state (e.g. a new temporal row with a not-yet-written
 * tag membership) that would let prefiltering drop the current memory. The
 * genuine-tag-miss contract is preserved: a truly absent tag still yields an
 * empty set, only now never as a transient artifact of an in-flight write.
 * Index reads are cache-backed (microseconds), so ordering them on the op-chain
 * is negligible beside the multi-second QMD phase.
 */
export function readIndexSnapshotAsync<T>(
  memoryDir: string,
  read: () => Promise<T>,
): Promise<T> {
  return withMemoryDirMutex(memoryDir, read);
}

/**
 * Detect if a prompt is time-sensitive (mentions specific time references).
 * Used to decide whether to activate the temporal prefilter.
 */
export function isTemporalQuery(prompt: string): boolean {
  return /\b(today|yesterday|this week|last week|this month|last month|recent(?:ly)?|lately|just now|earlier today|this morning|last night|last year|this year|\d+ days? ago|\d+ hours? ago|\d+ weeks? ago|\d+ months? ago|(?:in |on |during |since |before |after )?(?:january|february|march|april|may|june|july|august|september|october|november|december)(?:\s+\d{1,4})?|\d{4}-\d{2}-\d{2}|\d{1,2}\/\d{1,2}\/\d{2,4}|(?:spring|summer|fall|autumn|winter)\s+\d{4}|on the \d{1,2}(?:st|nd|rd|th)?|last (?:monday|tuesday|wednesday|thursday|friday|saturday|sunday))\b/i.test(
    prompt
  );
}

/**
 * Compute a "from date" string (YYYY-MM-DD) for a recency-based temporal query.
 * For "recent" / "lately" returns 7 days ago; for today/yesterday the obvious window.
 */
export function recencyWindowFromPrompt(prompt: string, nowMs: number = Date.now()): string {
  const p = prompt.toLowerCase();
  const now = new Date(nowMs);
  let daysBack = 7; // default

  if (/\btoday\b/.test(p) || /\bthis morning\b/.test(p) || /\bjust now\b/.test(p) || /\bearlier today\b/.test(p)) {
    daysBack = 0; // fromDate = today → window [today, today]
  } else if (/\byesterday\b/.test(p) || /\blast night\b/.test(p)) {
    daysBack = 1; // fromDate = yesterday → window [yesterday, today]
  } else if (/\bthis week\b/.test(p)) {
    daysBack = 7;
  } else if (/\blast week\b/.test(p)) {
    daysBack = 14;
  } else if (/\bthis month\b/.test(p)) {
    daysBack = 31;
  } else if (/\blast month\b/.test(p)) {
    daysBack = 62;
  } else if (/\bthis year\b/.test(p)) {
    // From Jan 1 of current year
    const jan1 = new Date(now.getFullYear(), 0, 1);
    return jan1.toISOString().slice(0, 10);
  } else if (/\blast year\b/.test(p)) {
    const jan1LastYear = new Date(now.getFullYear() - 1, 0, 1);
    return jan1LastYear.toISOString().slice(0, 10);
  } else {
    // Try specific month references: "in March", "during January", "since February"
    const monthNames = [
      "january",
      "february",
      "march",
      "april",
      "may",
      "june",
      "july",
      "august",
      "september",
      "october",
      "november",
      "december",
    ];
    const monthMatch = p.match(
      /\b(january|february|march|april|may|june|july|august|september|october|november|december)(?:\s+(\d{4}))?\b/
    );
    if (monthMatch) {
      const monthIdx = monthNames.indexOf(monthMatch[1]);
      const year = monthMatch[2] ? Number.parseInt(monthMatch[2], 10) : now.getFullYear();
      // "before <month>" means everything prior to that month: use 2-year lookback
      // as fromDate so the window isn't unbounded. toDate is set to the month start
      // in recencyWindowBoundsFromPrompt.
      // IMPORTANT: when an explicit year is given, anchor the lookback to the named
      // month start (not to today). "before January 2024" should produce
      // fromDate ≈ 2022-01 — not today-730 days, which could land after 2024-01 and
      // invert the window for any explicitly past month within the 730-day horizon.
      if (/\bbefore\b/.test(p)) {
        if (monthMatch[2]) {
          // Explicit year: anchor fromDate 730 days before the named month start.
          const monthStart = new Date(year, monthIdx, 1);
          return new Date(monthStart.getTime() - 730 * 86_400_000).toISOString().slice(0, 10);
        }
        daysBack = 730;
      } else {
        const monthStart = new Date(year, monthIdx, 1);
        return monthStart.toISOString().slice(0, 10);
      }
    }

    // Try "N weeks ago"
    const weekMatch = p.match(/(\d{1,5})\s*weeks?\s*ago/);
    if (weekMatch) {
      daysBack = Math.min(365, Number.parseInt(weekMatch[1], 10) * 7);
    } else {
      // Try "N months ago"
      const monthsAgoMatch = p.match(/(\d{1,5})\s*months?\s*ago/);
      if (monthsAgoMatch) {
        daysBack = Math.min(730, Number.parseInt(monthsAgoMatch[1], 10) * 31);
      } else {
        const numMatch = p.match(/(\d{1,5})\s*days?\s*ago/);
        if (numMatch) {
          daysBack = Math.min(365, Number.parseInt(numMatch[1], 10)); // no off-by-one: "3 days ago" → 3
        } else {
          const hrMatch = p.match(/(\d{1,5})\s*hours?\s*ago/);
          if (hrMatch) {
            // Convert hours to days (ceiling); at least 1 day window
            daysBack = Math.max(1, Math.ceil(Number.parseInt(hrMatch[1], 10) / 24));
          }
        }
      }
    }

    // Try explicit date patterns: YYYY-MM-DD or MM/DD/YYYY
    const isoMatch = p.match(/(\d{4})-(\d{2})-(\d{2})/);
    if (isoMatch) {
      return `${isoMatch[1]}-${isoMatch[2]}-${isoMatch[3]}`;
    }
    const usMatch = p.match(/(\d{1,2})\/(\d{1,2})\/(\d{2,4})/);
    if (usMatch) {
      const year = usMatch[3].length === 2 ? 2000 + Number.parseInt(usMatch[3], 10) : Number.parseInt(usMatch[3], 10);
      return `${year}-${usMatch[1].padStart(2, "0")}-${usMatch[2].padStart(2, "0")}`;
    }

    // Try "last Monday/Tuesday/etc"
    const dayOfWeekMatch = p.match(/\blast\s+(monday|tuesday|wednesday|thursday|friday|saturday|sunday)\b/);
    if (dayOfWeekMatch) {
      const dayNames = ["sunday", "monday", "tuesday", "wednesday", "thursday", "friday", "saturday"];
      const targetDay = dayNames.indexOf(dayOfWeekMatch[1]);
      const currentDay = now.getDay();
      daysBack = (currentDay - targetDay + 7) % 7 || 7; // at least 7 days back
    }
  }

  const from = new Date(nowMs - daysBack * 24 * 60 * 60 * 1000);
  return from.toISOString().slice(0, 10);
}

/**
 * Returns both the start and end of the temporal window implied by the prompt.
 *
 * `fromDate` is computed by delegating to `recencyWindowFromPrompt`, so the two
 * functions cannot diverge on the lower bound.  `toDate` is computed independently
 * here using the same pattern-priority ordering, because the upper-bound arithmetic
 * differs (exclusive end vs. inclusive start) and would not be expressible as a
 * simple wrapper.
 *
 * Known divergence to be aware of: for "N hours ago", `recencyWindowFromPrompt`
 * uses `Math.max(1, Math.ceil(hours/24))` days back, so `fromDate` = yesterday for
 * sub-24h values.  `toDate` here is always `tomorrow` when no explicit date is
 * specified (see the `toDaysBack === 0` branch), giving a 2-day window.  This is
 * intentional — the window must cover both yesterday and today for recent hour-level
 * queries.  Any fix to the hours formula in `recencyWindowFromPrompt` must be
 * manually reflected here.
 *
 * - `fromDate`: first day of the implied window (same as `recencyWindowFromPrompt`)
 * - `toDate`: first day NOT in the window (exclusive upper bound), so callers
 *   should filter with `date >= fromDate && date < toDate`.
 */
export function recencyWindowBoundsFromPrompt(
  prompt: string,
  nowMs: number = Date.now()
): { fromDate: string; toDate: string } {
  const fromDate = recencyWindowFromPrompt(prompt, nowMs);
  const p = prompt.toLowerCase();
  const now = new Date(nowMs);
  const today = now.toISOString().slice(0, 10);
  const tomorrow = new Date(nowMs + 86_400_000).toISOString().slice(0, 10);

  let toDate: string;

  if (/\btoday\b|\bthis morning\b|\bjust now\b|\bearlier today\b/.test(p)) {
    toDate = tomorrow; // exclusive: include all of today
  } else if (/\byesterday\b|\blast night\b/.test(p)) {
    toDate = today; // exclusive: include all of yesterday, stop before today
  } else if (/\bthis week\b|\bthis month\b|\bthis year\b/.test(p)) {
    toDate = tomorrow; // exclusive: include all of today
  } else if (/\blast week\b/.test(p)) {
    toDate = new Date(nowMs - 7 * 86_400_000).toISOString().slice(0, 10); // already exclusive
  } else if (/\blast month\b/.test(p)) {
    toDate = new Date(nowMs - 31 * 86_400_000).toISOString().slice(0, 10); // approximately exclusive
  } else if (/\blast year\b/.test(p)) {
    toDate = `${now.getFullYear()}-01-01`; // exclusive: stop at Jan 1 of current year
  } else {
    // Mirror the structure of recencyWindowFromPrompt's else branch:
    // month name → early set (highest priority), then ago patterns set a
    // working offset, then ISO/US/weekday patterns run AFTER ago patterns
    // and can override them — matching the priority ordering in recencyWindowFromPrompt.

    const monthNames = [
      "january",
      "february",
      "march",
      "april",
      "may",
      "june",
      "july",
      "august",
      "september",
      "october",
      "november",
      "december",
    ];
    const monthMatch = p.match(
      /\b(january|february|march|april|may|june|july|august|september|october|november|december)(?:\s+(\d{4}))?\b/
    );
    if (monthMatch) {
      // "since <month>" / "after <month>" — open-ended: everything from that month to now.
      // "before <month>" — closed upper bound: everything before that month starts.
      // Plain "<month>" — just that calendar month.
      const monthIdx = monthNames.indexOf(monthMatch[1]);
      const year = monthMatch[2] ? Number.parseInt(monthMatch[2], 10) : now.getFullYear();
      const isSinceOrAfter = /\b(since|after)\b/.test(p);
      const isBefore = /\bbefore\b/.test(p);
      if (isSinceOrAfter) {
        toDate = tomorrow;
      } else if (isBefore) {
        // "before <month>" means everything prior to that month.
        // toDate = first day of that month (exclusive upper bound).
        toDate = new Date(year, monthIdx, 1).toISOString().slice(0, 10);
      } else {
        // Closed window: first day of the NEXT month is the exclusive upper bound.
        toDate = new Date(year, monthIdx + 1, 1).toISOString().slice(0, 10);
      }
    } else {
      // Ago patterns set a working offset (recent edge of the N-ago window).
      // Same nesting order as recencyWindowFromPrompt.
      // Sentinel -1 means "no ago pattern matched" → toDate falls back to tomorrow.
      let toDaysBack = -1;
      const weekMatch = p.match(/(\d{1,5})\s*weeks?\s*ago/);
      if (weekMatch) {
        toDaysBack = Math.max(0, Math.min(52, Number.parseInt(weekMatch[1], 10)) - 1) * 7;
      } else {
        const monthsAgoMatch = p.match(/(\d{1,5})\s*months?\s*ago/);
        if (monthsAgoMatch) {
          toDaysBack = Math.max(0, Math.min(24, Number.parseInt(monthsAgoMatch[1], 10)) - 1) * 31;
        } else {
          const numMatch = p.match(/(\d{1,5})\s*days?\s*ago/);
          if (numMatch) {
            // (N-1) mirrors the weeks/months ago formula: "3 days ago" → window [today-3, today-2]
            // N=1 → toDaysBack=0 → toDate=today (exclusive) → window [yesterday, today) = 1 day. ✓
            toDaysBack = Math.max(0, Math.min(365, Number.parseInt(numMatch[1], 10)) - 1);
          } else {
            const hrMatch = p.match(/(\d{1,5})\s*hours?\s*ago/);
            if (hrMatch) {
              // Sub-day precision: keep sentinel -1 so toDate falls back to tomorrow,
              // which includes today. fromDate = yesterday (recencyWindowFromPrompt uses ceiling).
              toDaysBack = -1;
            }
          }
        }
      }

      // Explicit date/weekday patterns run AFTER ago patterns (same as recencyWindowFromPrompt)
      // and override the ago-derived offset when present.
      const isoMatch = p.match(/(\d{4})-(\d{2})-(\d{2})/);
      if (isoMatch) {
        // +1 day: exclusive upper bound includes the named date
        const d = new Date(`${isoMatch[1]}-${isoMatch[2]}-${isoMatch[3]}T00:00:00Z`);
        toDate = new Date(d.getTime() + 86_400_000).toISOString().slice(0, 10);
      } else {
        const usMatch = p.match(/(\d{1,2})\/(\d{1,2})\/(\d{2,4})/);
        if (usMatch) {
          const year =
            usMatch[3].length === 2 ? 2000 + Number.parseInt(usMatch[3], 10) : Number.parseInt(usMatch[3], 10);
          // +1 day: exclusive upper bound includes the named date
          const d = new Date(`${year}-${usMatch[1].padStart(2, "0")}-${usMatch[2].padStart(2, "0")}T00:00:00Z`);
          toDate = new Date(d.getTime() + 86_400_000).toISOString().slice(0, 10);
        } else {
          const dayOfWeekMatch = p.match(/\blast\s+(monday|tuesday|wednesday|thursday|friday|saturday|sunday)\b/);
          if (dayOfWeekMatch) {
            const dayNames = ["sunday", "monday", "tuesday", "wednesday", "thursday", "friday", "saturday"];
            const targetDay = dayNames.indexOf(dayOfWeekMatch[1]);
            const currentDay = now.getDay();
            const daysBack = (currentDay - targetDay + 7) % 7 || 7;
            // +1 day: exclusive upper bound includes the named weekday
            toDate = new Date(nowMs - (daysBack - 1) * 86_400_000).toISOString().slice(0, 10);
          } else {
            // Use the ago-derived offset.
            // toDaysBack=-1 means no pattern matched (or hours-ago): use tomorrow so today
            // is included in the window. toDaysBack=0 means N=1 ago (e.g. "1 day ago"):
            // toDate = today (exclusive) correctly creates a 1-day window [yesterday, today).
            toDate = toDaysBack < 0 ? tomorrow : new Date(nowMs - toDaysBack * 86_400_000).toISOString().slice(0, 10);
          }
        }
      }
    }
  }

  // Guard: if toDate would precede fromDate (inverted window from conflicting keywords),
  // fall back to tomorrow (exclusive upper bound that covers today) so we never produce
  // an empty window. Using `today` is insufficient because `date < today` excludes today.
  if (toDate <= fromDate) toDate = tomorrow;

  return { fromDate, toDate };
}

import type { MemoryFile, MemoryStatus } from "../types.js";
import { inferMemoryStatus, isActiveMemoryStatus, toMemoryPathRel } from "../memory-lifecycle-ledger-utils.js";
import { lookupAttributeByNormalizedKey, normalizeSupersessionKey } from "../temporal-supersession.js";

export interface UpdateLocalizationStorage {
  dir?: string;
  readAllMemories(): Promise<MemoryFile[]>;
  readAllColdMemories?: () => Promise<MemoryFile[]>;
}

export function mergeMemorySnapshots(
  hot: MemoryFile[],
  cold: MemoryFile[],
  storageDir?: string,
): MemoryFile[] {
  const merged: MemoryFile[] = [];
  const indexById = new Map<string, number>();
  for (const memory of [...hot, ...cold]) {
    const id = memory.frontmatter.id;
    const existingIndex = indexById.get(id);
    if (existingIndex === undefined) {
      indexById.set(id, merged.length);
      merged.push(memory);
      continue;
    }
    const existing = merged[existingIndex];
    if (
      !isActiveMemoryStatus(inferLocalizationMemoryStatus(existing, storageDir)) &&
      isActiveMemoryStatus(inferLocalizationMemoryStatus(memory, storageDir))
    ) {
      merged[existingIndex] = memory;
    }
  }
  return merged;
}

export interface UpdateAnchor {
  entityRef?: string;
  category: string;
  attributes?: Record<string, string>;
}

export interface UpdateLocalizationSearchHit {
  id: string;
  content: string;
  category: string;
  score: number;
}

export interface LocalizedCandidate {
  id: string;
  content: string;
  category: string;
  source: "anchor" | "search";
  score: number;
}

export interface UpdateLocalizationOptions {
  anchorCandidates: number;
  searchCandidates: number;
  maxCandidates: number;
}

export interface UpdateLocalizationDeps {
  storage: UpdateLocalizationStorage;
  qmdSearch: (query: string, limit: number) => Promise<UpdateLocalizationSearchHit[]>;
}

function cap(value: number): number {
  return Number.isFinite(value) ? Math.max(0, Math.floor(value)) : 0;
}

function normalizeEntityRef(value: unknown): string | undefined {
  if (typeof value !== "string") return undefined;
  const normalized = normalizeSupersessionKey(value);
  return normalized.length > 0 ? normalized : undefined;
}

function compareCandidates(left: LocalizedCandidate, right: LocalizedCandidate): number {
  const leftScore = Number.isFinite(left.score) ? left.score : Number.NEGATIVE_INFINITY;
  const rightScore = Number.isFinite(right.score) ? right.score : Number.NEGATIVE_INFINITY;
  if (leftScore !== rightScore) return leftScore > rightScore ? -1 : 1;
  return left.id < right.id ? -1 : left.id > right.id ? 1 : 0;
}

function anchorScore(memory: MemoryFile, anchor: UpdateAnchor): number {
  const attributes = anchor.attributes;
  if (attributes && Object.keys(attributes).length > 0) {
    const candidateAttributes = memory.frontmatter.structuredAttributes;
    if (!candidateAttributes) return 0;
    let overlap = 0;
    for (const key of Object.keys(attributes)) {
      if (lookupAttributeByNormalizedKey(candidateAttributes, key) !== undefined) overlap++;
    }
    return overlap;
  }

  const created = Date.parse(memory.frontmatter.created);
  return Number.isFinite(created) ? created : 0;
}

function toAnchorCandidate(memory: MemoryFile, anchor: UpdateAnchor): LocalizedCandidate {
  return {
    id: memory.frontmatter.id,
    content: memory.content,
    category: memory.frontmatter.category,
    source: "anchor",
    score: anchorScore(memory, anchor),
  };
}

export function inferLocalizationMemoryStatus(
  memory: MemoryFile,
  storageDir?: string,
): MemoryStatus {
  const pathRel = storageDir ? toMemoryPathRel(storageDir, memory.path) : memory.path;
  return inferMemoryStatus(memory.frontmatter, pathRel);
}

export async function localizeUpdateCandidates(
  deps: UpdateLocalizationDeps,
  anchor: UpdateAnchor,
  newContent: string,
  options: UpdateLocalizationOptions,
): Promise<LocalizedCandidate[]> {
  const maxCandidates = cap(options.maxCandidates);
  if (maxCandidates === 0) return [];

  const anchorLimit = cap(options.anchorCandidates);
  const searchLimit = cap(options.searchCandidates);
  const anchorCandidates: LocalizedCandidate[] = [];
  const normalizedAnchorEntityRef = normalizeEntityRef(anchor.entityRef);
  if (normalizedAnchorEntityRef !== undefined && anchorLimit > 0) {
    const hot = await deps.storage.readAllMemories();
    const cold = deps.storage.readAllColdMemories ? await deps.storage.readAllColdMemories() : [];
    const memories = mergeMemorySnapshots(hot, cold, deps.storage.dir);
    for (const memory of memories) {
      if (inferLocalizationMemoryStatus(memory, deps.storage.dir) !== "active") continue;
      const normalizedCandidateEntityRef = normalizeEntityRef(memory.frontmatter.entityRef);
      if (normalizedCandidateEntityRef !== normalizedAnchorEntityRef) continue;
      if (memory.frontmatter.category !== anchor.category) continue;
      anchorCandidates.push(toAnchorCandidate(memory, anchor));
    }
    anchorCandidates.sort(compareCandidates);
    anchorCandidates.splice(anchorLimit);
  }

  const searchCandidates: LocalizedCandidate[] = [];
  if (searchLimit > 0) {
    const searchHits = await deps.qmdSearch(newContent, searchLimit);
    for (const hit of searchHits) {
      searchCandidates.push({
        id: hit.id,
        content: hit.content,
        category: hit.category,
        source: "search",
        score: hit.score,
      });
    }
    searchCandidates.sort(compareCandidates);
    searchCandidates.splice(searchLimit);
  }

  const merged: LocalizedCandidate[] = [];
  const seen = new Set<string>();
  for (const candidate of [...anchorCandidates, ...searchCandidates]) {
    if (seen.has(candidate.id)) continue;
    seen.add(candidate.id);
    merged.push(candidate);
    if (merged.length >= maxCandidates) break;
  }
  return merged;
}

/**
 * Derive issue #1955 origin metadata at the extraction boundary.
 */

import { classifyOrigin, type OriginClass } from "../security/origin-authority.js";
import type { BufferTurn } from "../types.js";

export interface ExtractionSourceContext {
  sessionKey?: string;
  principal?: string;
  validAt?: string;
  sourceConnector?: string;
  turnRole?: "user" | "assistant" | "tool" | string;
  importAdapter?: string;
  originConflict?: boolean;
}

/** Derive one origin context from the turns that supplied an extraction. */
export function deriveExtractionOriginContext(
  targetTurns: readonly BufferTurn[],
  fallbackConnector?: string,
): Pick<ExtractionSourceContext, "turnRole" | "importAdapter" | "sourceConnector" | "originConflict"> {
  const originRoles = new Set(targetTurns.map((turn) => turn.originRole ?? turn.role));
  const turnRole = originRoles.size === 1 ? [...originRoles][0] : undefined;
  const originConnectors = new Set(
    targetTurns
      .map((turn) => turn.sourceConnector)
      .filter((connector): connector is string => typeof connector === "string" && connector.length > 0),
  );
  // Mirror the pre-#1955 provenance rule: a batch only carries a connector
  // when EVERY turn is tagged with the same one — a mixed tagged+untagged
  // batch must stay connector-less (connector-provenance-lifecycle tests).
  const connector =
    targetTurns.length > 0 &&
    targetTurns.every(
      (turn) => typeof turn.sourceConnector === "string" && turn.sourceConnector.length > 0,
    ) &&
    originConnectors.size === 1
      ? [...originConnectors][0]
      : undefined;
  const originAdapters = new Set(
    targetTurns
      .map((turn) => turn.importProvenance?.sourceLabel)
      .filter((adapter): adapter is string => typeof adapter === "string" && adapter.length > 0),
  );
  // Conflict when identities disagree OR are only partially present: a batch
  // where some turns carry an import label (or connector) and others do not
  // must classify as unknown, never fall back to the uniform turn role
  // (#1955 review: mixed import labels previously became `user`).
  const everyTurnHasConnector =
    targetTurns.length > 0 &&
    targetTurns.every((turn) => typeof turn.sourceConnector === "string" && turn.sourceConnector.length > 0);
  const everyTurnHasAdapter =
    targetTurns.length > 0 &&
    targetTurns.every(
      (turn) => typeof turn.importProvenance?.sourceLabel === "string" && turn.importProvenance.sourceLabel.length > 0,
    );
  const originConflict =
    originConnectors.size > 1 ||
    originAdapters.size > 1 ||
    (originConnectors.size > 0 && originAdapters.size > 0) ||
    (originConnectors.size > 0 && !everyTurnHasConnector) ||
    (originAdapters.size > 0 && !everyTurnHasAdapter);
  const importAdapter =
    targetTurns.length > 0 &&
    targetTurns.every(
      (turn) =>
        typeof turn.importProvenance?.sourceLabel === "string" &&
        turn.importProvenance.sourceLabel.length > 0,
    ) &&
    originAdapters.size === 1
      ? [...originAdapters][0]
      : undefined;
  return {
    ...(turnRole ? { turnRole } : {}),
    ...(importAdapter ? { importAdapter } : {}),
    ...(originConflict ? { originConflict: true } : {}),
    sourceConnector: fallbackConnector ?? connector,
  };
}

/** Classify the persisted origin without reading config flags. */
export function classifyExtractionOrigin(sourceContext?: ExtractionSourceContext): OriginClass {
  if (sourceContext?.originConflict === true) return "unknown";
  return classifyOrigin({
    turnRole: sourceContext?.turnRole,
    connectorId: sourceContext?.sourceConnector,
    importAdapter: sourceContext?.importAdapter,
  });
}

/**
 * Extraction-LLM availability tracking surfaced on `/health` (issue #3140).
 *
 * A failing extraction LLM (unreachable endpoint, gateway with no models)
 * used to surface only as debug-level lines while extraction silently skipped
 * persistence and the buffer grew for days. The extraction run records every
 * attempt outcome here; the access `/health` payload reads the last outcome so
 * an unavailable extractor is visible without debug logs, and each distinct
 * failure reason logs at ERROR level at most once per window instead of once
 * per failed flush.
 */

import { log } from "./logger.js";

export interface ExtractionLlmHealth {
  /** Whether the LAST extraction attempt completed without a failure marker. */
  llmReachable: boolean;
  /** `failureReason` of the last failed attempt; null while reachable. */
  lastFailureReason: string | null;
  /** ISO timestamp of the last failed attempt; null while reachable. */
  lastFailureAt: string | null;
}

/** One ERROR line per distinct reason per window; repeats stay at debug. */
const DEDUP_WINDOW_MS = 3_600_000;

let lastFailureReason: string | null = null;
let lastFailureAtMs: number | null = null;
const lastErrorEmitByReason = new Map<string, number>();

export function recordExtractionLlmSuccess(): void {
  lastFailureReason = null;
  lastFailureAtMs = null;
}

export function recordExtractionLlmFailure(reason: string, atMs: number = Date.now()): void {
  lastFailureReason = reason;
  lastFailureAtMs = atMs;
}

export function getExtractionLlmHealth(): ExtractionLlmHealth {
  return {
    llmReachable: lastFailureReason === null,
    lastFailureReason,
    lastFailureAt: lastFailureAtMs === null ? null : new Date(lastFailureAtMs).toISOString(),
  };
}

/**
 * ERROR-level, deduplicated failure event (issue #3140): the first failure of
 * a given reason inside the window logs at error level; repeats inside the
 * window log at debug so the backoff retry loop cannot flood the transcript
 * while the outage stays visible. Returns whether the error line was emitted.
 */
export function emitExtractionLlmFailureError(reason: string, detail?: string, nowMs: number = Date.now()): boolean {
  const suffix = detail ? `: ${detail}` : "";
  const last = lastErrorEmitByReason.get(reason);
  if (last !== undefined && nowMs - last < DEDUP_WINDOW_MS) {
    log.debug(`extraction failure repeat suppressed for ${DEDUP_WINDOW_MS / 60_000}m: ${reason}${suffix}`);
    return false;
  }
  lastErrorEmitByReason.set(reason, nowMs);
  log.error(`extraction failed with no durable outputs (buffer retained for retry): ${reason}${suffix}`);
  return true;
}

/** Test seam: restore pristine singleton state. */
export function resetExtractionLlmHealthForTests(): void {
  recordExtractionLlmSuccess();
  lastErrorEmitByReason.clear();
}

/**
 * Location tagging service (issue #2046) — the IO half around the pure
 * matcher in `matching.ts`. Three consumers share it so the policy can never
 * fork:
 *
 *  1. Write-time enrichment: after an extraction batch has cleared the
 *     trust/importance/content-hash gates and persisted, the caller tags the
 *     new memories (post-write, best-effort, never fails the extraction).
 *  2. Historical backfill (`location/backfill.ts`): the same plan/apply core
 *     over a bounded date range, idempotent by construction.
 *  3. Wearable conversation fill: `WearableConversation.location` is filled
 *     ONLY when the source did not provide one and the match passes policy.
 *
 * Segment data comes from the machine-global location sync state
 * (`state/locations/sync.json`, ≤ 90 tracked days — matching the bounded
 * backfill range). Reads are plain file loads; every memory mutation goes
 * through `StorageManager.writeMemoryFrontmatter`, the atomic frontmatter
 * chokepoint that preserves content (and therefore the content hash),
 * lifecycle, and versioning invariants.
 */

import type { StorageManager } from "../index.js";
import { log } from "../logger.js";
import type { BriefingResult, MemoryFile } from "../types.js";
import type { WearableConversation } from "../wearables/types.js";
import { localDayKey, placeDurations } from "./intervals.js";
import {
  matchDominantPlace,
  memoryLocationWindow,
  planLocationUpdate,
  type LocationSourceSegments,
  type LocationTagPolicy,
  type LocationUpdatePlan,
} from "./matching.js";
import { loadLocationSyncState } from "./store.js";
import type { LocationConfig } from "./types.js";

/** Segments for one local day, per source id, from the sync state. */
export type DaySegmentIndex = Map<string, LocationSourceSegments[]>;

/** Load every tracked day's per-source segments (one file read). */
export async function loadDaySegmentIndex(memoryDir: string): Promise<DaySegmentIndex> {
  const state = await loadLocationSyncState(memoryDir);
  const index: DaySegmentIndex = new Map();
  for (const [sourceId, source] of Object.entries(state.sources)) {
    for (const [date, payload] of Object.entries(source.days ?? {})) {
      const entry: LocationSourceSegments = { sourceId, segments: payload.segments ?? [] };
      const existing = index.get(date);
      if (existing === undefined) index.set(date, [entry]);
      else existing.push(entry);
    }
  }
  return index;
}

export function locationTagPolicy(config: LocationConfig): LocationTagPolicy {
  return {
    minimumOverlapSeconds: config.minimumOverlapSeconds,
    minimumConfidence: config.minimumConfidence,
    retainCoordinates: config.retainCoordinates,
  };
}

/** Every tagging path is off unless BOTH gates are on. */
export function locationTaggingEnabled(config: LocationConfig): boolean {
  return config.enabled && config.tagging.enabled;
}

/**
 * Write-time post-persist hook (issue #2046): tag the memories an extraction
 * batch just made durable. Best-effort by contract — gated on both location
 * gates, and a location failure must never fail the extraction that already
 * persisted.
 */
export async function tagPersistedMemories(
  storage: StorageManager,
  memoryIds: string[],
  config: { memoryDir: string; location?: LocationConfig },
): Promise<void> {
  if (memoryIds.length === 0 || !config.location || !locationTaggingEnabled(config.location)) return;
  try {
    await enrichMemoriesWithLocation({
      storage,
      memoryIds,
      memoryDir: config.memoryDir,
      config: config.location,
    });
  } catch (locationError) {
    log.warn("[location] post-write tagging failed (non-fatal)", locationError);
  }
}

function segmentsForDays(index: DaySegmentIndex, days: readonly string[]): LocationSourceSegments[] {
  const merged = new Map<string, LocationSourceSegments>();
  for (const day of days) {
    for (const entry of index.get(day) ?? []) {
      const existing = merged.get(entry.sourceId);
      if (existing === undefined) {
        merged.set(entry.sourceId, { sourceId: entry.sourceId, segments: [...entry.segments] });
        continue;
      }
      existing.segments.push(...entry.segments);
    }
  }
  return [...merged.values()];
}

/** The full plan for one memory: window → segments → match → provider-owned diff. */
function planForMemory(
  frontmatter: Pick<MemoryFile["frontmatter"], "valid_at" | "observedAt" | "invalid_at" | "tags" | "structuredAttributes">,
  index: DaySegmentIndex,
  config: LocationConfig,
): LocationUpdatePlan {
  const policy = locationTagPolicy(config);
  const result = memoryLocationWindow(frontmatter, (instant) => localDayKey(instant, config.timezone));
  if (result.rejected === "span-too-long") return { outcome: "span-too-long" };
  if (result.rejected === "untimed" || result.window === undefined || result.days === undefined) {
    return { outcome: "untimed" };
  }
  const sources = segmentsForDays(index, result.days);
  return planLocationUpdate(frontmatter, matchDominantPlace(result.window, sources, policy), policy);
}

export interface LocationEnrichmentCounts {
  tagged: number;
  updated: number;
  removed: number;
  unchanged: number;
  unmatched: number;
  manual: number;
  untimed: number;
  spanTooLong: number;
  failed: number;
}

export function emptyEnrichmentCounts(): LocationEnrichmentCounts {
  return {
    tagged: 0,
    updated: 0,
    removed: 0,
    unchanged: 0,
    unmatched: 0,
    manual: 0,
    untimed: 0,
    spanTooLong: 0,
    failed: 0,
  };
}

function countOutcome(counts: LocationEnrichmentCounts, outcome: LocationUpdatePlan["outcome"]): void {
  if (outcome === "tagged") counts.tagged += 1;
  else if (outcome === "updated") counts.updated += 1;
  else if (outcome === "removed") counts.removed += 1;
  else if (outcome === "unchanged") counts.unchanged += 1;
  else if (outcome === "manual-metadata") counts.manual += 1;
  else if (outcome === "unmatched") counts.unmatched += 1;
  else if (outcome === "untimed") counts.untimed += 1;
  else if (outcome === "span-too-long") counts.spanTooLong += 1;
}

export interface EnrichMemoriesOptions {
  storage: Pick<StorageManager, "getMemoryById" | "writeMemoryFrontmatter">;
  memoryDir: string;
  config: LocationConfig;
  /** Enrich exactly these memory ids (write-time path). */
  memoryIds?: string[];
  /** Pre-loaded memories (backfill path — one readAllMemories per run). */
  memories?: MemoryFile[];
  /** Reuse a caller-loaded segment index (backfill). */
  index?: DaySegmentIndex;
  /** Skip every mutation and only report (dry-run). */
  dryRun?: boolean;
}

/**
 * Apply the matcher to a set of memories and patch provider-owned location
 * metadata. A failure on ONE memory is counted and skipped — it never blocks
 * the others (failure isolation, issue #2046).
 */
export async function enrichMemoriesWithLocation(
  options: EnrichMemoriesOptions,
): Promise<LocationEnrichmentCounts> {
  if (!locationTaggingEnabled(options.config)) return emptyEnrichmentCounts();
  const counts = emptyEnrichmentCounts();
  const index = options.index ?? (await loadDaySegmentIndex(options.memoryDir));

  let memories = options.memories;
  if (memories === undefined && options.memoryIds !== undefined) {
    memories = [];
    for (const id of options.memoryIds) {
      const memory = await options.storage.getMemoryById(id);
      if (memory !== null) memories.push(memory);
    }
  }
  if (memories === undefined) return counts;

  for (const memory of memories) {
    try {
      const plan = planForMemory(memory.frontmatter, index, options.config);
      // Count patch outcomes (tagged/updated/removed) only after the write
      // lands — a rejected write is `failed`, never also `tagged`.
      if (plan.patch === undefined || options.dryRun === true) {
        countOutcome(counts, plan.outcome);
        continue;
      }
      await options.storage.writeMemoryFrontmatter(memory, plan.patch, { actor: "location-tagging" });
      countOutcome(counts, plan.outcome);
    } catch {
      counts.failed += 1;
    }
  }
  return counts;
}

/**
 * Fill `WearableConversation.location` for conversations whose source did not
 * provide one. Missing-only and source-aware: a provider-supplied value is
 * never overwritten, and a failing conversation never blocks the others.
 */
export async function fillWearableConversationLocations(
  conversations: WearableConversation[],
  deps: { memoryDir: string; config: LocationConfig },
): Promise<void> {
  if (!locationTaggingEnabled(deps.config) || conversations.length === 0) return;
  let index: DaySegmentIndex;
  try {
    index = await loadDaySegmentIndex(deps.memoryDir);
  } catch {
    return;
  }
  const policy = locationTagPolicy(deps.config);
  for (const conversation of conversations) {
    if (conversation.location !== undefined && conversation.location.length > 0) continue;
    try {
      const startMs = Date.parse(conversation.startIso);
      const endMs = conversation.endIso !== undefined ? Date.parse(conversation.endIso) : Number.NaN;
      const window =
        Number.isFinite(startMs) && Number.isFinite(endMs) && endMs > startMs
          ? { kind: "interval" as const, startUtc: conversation.startIso, endUtc: conversation.endIso as string }
          : { kind: "instant" as const, atUtc: conversation.startIso };
      const anchor = window.kind === "interval" ? new Date(Date.parse(window.endUtc) - 1).toISOString() : window.atUtc;
      const days = [...new Set([localDayKey(anchor, deps.config.timezone), localDayKey(conversation.startIso, deps.config.timezone)])];
      const outcome = matchDominantPlace(window, segmentsForDays(index, days), policy);
      if (outcome.status === "matched") {
        conversation.location = outcome.match.place.label;
      }
    } catch {
      // One bad conversation never blocks the rest of the day's fill.
    }
  }
}

/** Render an opt-in, labels-only location context section for a day summary. */
export async function renderDayLocationContext(
  memoryDir: string,
  date: string,
  config: LocationConfig,
): Promise<string | null> {
  if (!locationTaggingEnabled(config)) return null;
  const state = await loadLocationSyncState(memoryDir);
  const segments = [];
  for (const source of Object.values(state.sources)) {
    for (const segment of source.days?.[date]?.segments ?? []) segments.push(segment);
  }
  if (segments.length === 0) return null;
  const durations = placeDurations(segments)
    .filter((duration) => ["home", "work", "poi"].includes(duration.place.kind ?? "poi"))
    .sort((a, b) => (a.totalMs !== b.totalMs ? b.totalMs - a.totalMs : a.place.id < b.place.id ? -1 : 1));
  if (durations.length === 0) return null;
  const lines = durations.map((duration) => {
    const minutes = Math.round(duration.totalMs / 60_000);
    const hours = Math.floor(minutes / 60);
    const rendered = hours <= 0 ? `${minutes}m` : `${hours}h ${String(minutes % 60).padStart(2, "0")}m`;
    return `- ${duration.place.label.replace(/\s+/g, " ").replace(/[`*_]/g, "").trim()}: ${rendered}`;
  });
  return `## Location context\n\n${lines.join("\n")}`;
}

/**
 * Location context for a briefing (issue #2925): the place names of the
 * local day containing the briefing window's start, bucketed in the
 * location config's own timezone (the store's bucketing zone). Opt-in and
 * labels-only — the caller decides whether to include it.
 */
export async function briefingLocationSection(
  memoryDir: string,
  windowStartUtc: string,
  config: LocationConfig,
): Promise<string | null> {
  return renderDayLocationContext(
    memoryDir,
    localDayKey(windowStartUtc, config.timezone),
    config,
  );
}

/**
 * Append the opt-in location section to a briefing. The section is read BEFORE
 * `build` runs: buildBriefing drains correction notifications at most once, so
 * a deadline during this read must not lose them.
 */
export async function buildWithBriefingLocation<T extends Pick<BriefingResult, "markdown" | "json">>(
  includeLocation: boolean | undefined,
  memoryDir: string,
  windowStartUtc: string,
  location: LocationConfig,
  build: () => Promise<T>,
): Promise<T> {
  const section =
    includeLocation === true && locationTaggingEnabled(location)
      ? await briefingLocationSection(memoryDir, windowStartUtc, location)
      : null;
  const result = await build();
  if (!section) return result;
  return { ...result, markdown: `${result.markdown}\n\n${section}\n`, json: { ...result.json, locationContext: section } };
}

/**
 * Opt-in matched-place-name context (issue #2925), shared by the access
 * request surfaces (day summary and briefing). Absent or false keeps the
 * output byte-identical.
 */
export interface LocationContextRequestOptions {
  /** Opt-in matched-place-name context appended to the summary or briefing output. */
  includeLocation?: boolean;
}

/**
 * Auto-gather options for the day summary (issue #2925): the caller's
 * timezone plus the strictly-opt-in location flag. Only the literal
 * `true` opts in, matching the transport schemas' boolean contract.
 */
export function daySummaryAutoOptions(
  request: LocationContextRequestOptions & { timeZone?: string },
): { timeZone?: string; includeLocation: boolean } {
  return { timeZone: request.timeZone, includeLocation: request.includeLocation === true };
}

import type { BufferTurn, ExtractionFailureClass, ExtractionResult, MetaState } from "../types.js";
import type { StorageManager } from "../index.js";
import { log } from "../logger.js";
import type { ExtractionRunResult } from "./extraction-run.js";

export function combineExtractionAbortSignals(
  primary: AbortSignal | undefined,
  deadlineController: AbortController | undefined,
): AbortSignal | undefined {
  if (!deadlineController) return primary;
  return primary ? AbortSignal.any([primary, deadlineController.signal]) : deadlineController.signal;
}


/** Result of a run whose extraction found nothing durable; `retained` marks a recorded failure that left the window in the buffer. */
export function emptyExtractionResult(retained: boolean, failureClass?: ExtractionFailureClass): ExtractionRunResult {
  const result: ExtractionRunResult = { status: "skipped", reason: "empty_extraction_result", persistedCount: 0, durableOutputCount: 0 };
  if (retained) Object.assign(result, { retainedBuffer: true, failureClass: failureClass ?? "provider_retryable" }); // same default as the retry bookkeeping
  return result;
}

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null;
}

export function deriveTopicsFromExtraction(result: ExtractionResult): string[] {
  if (!isRecord(result)) return [];
  const topics = new Set<string>();
  const facts = Array.isArray(result.facts) ? result.facts : [];
  for (const rawFact of facts) {
    if (!isRecord(rawFact)) continue;
    const tags = Array.isArray(rawFact.tags) ? rawFact.tags : [];
    for (const tag of tags) {
      if (typeof tag === "string" && tag.length >= 2) topics.add(tag.toLowerCase());
    }
    if (typeof rawFact.entityRef === "string" && rawFact.entityRef.length >= 2) {
      topics.add(rawFact.entityRef.toLowerCase());
    }
    if (typeof rawFact.category === "string" && rawFact.category.length > 0) {
      topics.add(rawFact.category);
    }
  }
  const entities = Array.isArray(result.entities) ? result.entities : [];
  for (const rawEntity of entities) {
    if (!isRecord(rawEntity)) continue;
    if (typeof rawEntity.name === "string" && rawEntity.name.length >= 2) {
      topics.add(rawEntity.name.toLowerCase());
    }
  }
  return [...topics].slice(0, 16);
}

/** Bounded cap on persisted per-fingerprint retry-state entries (per namespace meta). */
export const EXTRACTION_RETRY_STATE_MAX_ENTRIES = 500;

export interface ExtractionRetryStateEntry {
  attempts: number;
  nextEligibleAtMs: number;
  firstFailedAtMs: number;
  lastFailureClass: ExtractionFailureClass;
}

export interface ExtractionResilienceStatus {
  breaker: {
    state: "closed" | "open" | "half_open";
    openUntilMs: number;
    consecutiveFailures: number;
    lastReason: string;
  };
  backoffFingerprintCount: number;
}

/**
 * Pure backoff scheduler. Returns the absolute ms timestamp at which a
 * fingerprint that has failed `attempts` times becomes eligible again:
 * exponential via the configured schedule, clamped to `maxBackoffMs`, with
 * ±`jitterRatio` multiplicative jitter. `rng` is injectable for deterministic
 * tests. Never returns a timestamp before `now`.
 */
export function computeExtractionRetryNextEligibleMs(
  attempts: number,
  scheduleMs: readonly number[],
  maxBackoffMs: number,
  jitterRatio: number,
  now: number,
  rng: () => number = Math.random,
): number {
  if (!Number.isFinite(attempts) || !Number.isInteger(attempts) || attempts < 1) {
    throw new RangeError("attempts must be a finite integer >= 1");
  }
  if (!Number.isFinite(maxBackoffMs) || maxBackoffMs < 0) {
    throw new RangeError("maxBackoffMs must be a finite number >= 0");
  }
  if (!Number.isFinite(jitterRatio) || jitterRatio < 0 || jitterRatio > 1) {
    throw new RangeError("jitterRatio must be a finite number in [0, 1]");
  }
  const safeNow = Number.isFinite(now) ? now : 0;
  const cap = maxBackoffMs;
  if (!Array.isArray(scheduleMs) || scheduleMs.length === 0) {
    return safeNow + cap;
  }
  const idx = Math.min(attempts - 1, scheduleMs.length - 1);
  const step = scheduleMs[idx];
  const base = Math.min(typeof step === "number" && Number.isFinite(step) && step > 0 ? step : cap, cap);
  const randomValue = rng();
  if (!Number.isFinite(randomValue) || randomValue < 0 || randomValue > 1) {
    throw new RangeError("rng() must return a finite number in [0, 1]");
  }
  const jitter = 1 + (randomValue * 2 - 1) * jitterRatio;
  return safeNow + Math.max(0, Math.round(base * jitter));
}

/**
 * Cap the persisted retry-state array to the newest `maxEntries` by
 * firstFailedAt. Guards invalid caps so they cannot turn `slice(-maxEntries)`
 * into an unbounded copy (AGENTS.md rule 17).
 */
export function capExtractionRetryStateEntries<T extends { firstFailedAt: string }>(
  entries: readonly T[],
  maxEntries: number,
): T[] {
  if (!Number.isFinite(maxEntries) || !Number.isInteger(maxEntries) || maxEntries <= 0) return [];
  const sorted = [...entries].sort((a, b) => a.firstFailedAt.localeCompare(b.firstFailedAt));
  return sorted.slice(-maxEntries);
}

/**
 * Derive a single `sourceConnector` from a batch of turns.
 * Returns the connector ONLY when ALL turns carry the same connector.
 * Mixed tagged/untagged batches return undefined — extraction facts are
 * persisted at batch level, so attributing them to the single tagged
 * connector would falsely label facts from untagged turns.
 * Conflicting connectors (different values) also return undefined.
 */
export function deriveSourceConnector(turns: readonly BufferTurn[]): string | undefined {
  if (turns.length === 0) return undefined;
  const connectors = new Set<string>();
  let untaggedCount = 0;
  for (const turn of turns) {
    if (typeof turn.sourceConnector === "string" && turn.sourceConnector.length > 0) {
      connectors.add(turn.sourceConnector);
    } else {
      untaggedCount += 1;
    }
  }
  // All turns must agree on the same connector — no untagged turns mixed in.
  if (untaggedCount > 0) return undefined;
  return connectors.size === 1 ? [...connectors][0] : undefined;
}

export async function runExtractionPostPersistBestEffort(
  runDeadlineAware: (
    operation: () => Promise<unknown>,
    phase: string,
    clearTimerOnError?: boolean,
    options?: { ignoreAbort?: boolean; ignoreDeadline?: boolean },
  ) => Promise<unknown>,
  stage: string,
  operation: () => Promise<unknown>,
  options?: { ignoreAbort?: boolean; ignoreDeadline?: boolean; propagateErrors?: boolean },
): Promise<void> {
  try {
    await runDeadlineAware(operation, stage, false, {
      ignoreAbort: options?.ignoreAbort,
      ignoreDeadline: options?.ignoreDeadline,
    });
  } catch (error) {
    if (options?.propagateErrors) throw error;
    log.warn(`runExtraction: ${stage} failed after persistence (non-fatal)`, error);
  }
}

/**
 * Applies deferred-judge retention only to live, non-shadow extraction runs.
 * Replay/import paths must not synthesize live-buffer entries after persistence.
 */
export interface ExtractionDeferRetentionOptions {
  clearBufferAfterExtraction: boolean;
  extractionJudgeShadow: boolean;
  deferredCount: number;
  normalizedTurns: BufferTurn[];
  bufferKey: string;
  retainDeferredTurns: (bufferKey: string, turns: BufferTurn[], max: number) => Promise<void>;
}

export async function runExtractionDeferRetention(
  runPostPersistBestEffort: (
    stage: string,
    operation: () => Promise<unknown>,
    options?: { ignoreAbort?: boolean },
  ) => Promise<void>,
  options: ExtractionDeferRetentionOptions,
): Promise<void> {
  await runPostPersistBestEffort("during_defer_retention", async () => {
    if (options.clearBufferAfterExtraction && !options.extractionJudgeShadow) {
      const deferredCount = options.deferredCount;
      if (deferredCount > 0 && options.normalizedTurns.length > 0) {
        await options.retainDeferredTurns(options.bufferKey, options.normalizedTurns, 10);
      } else {
        await options.retainDeferredTurns(options.bufferKey, [], 0);
      }
    }
  });
}

export interface ExtractionPostPersistOptions {
  result: ExtractionResult;
  storage: StorageManager;
  extractionFingerprint?: string;
  shouldPersistProcessedFingerprint: boolean;
  recordProcessedExtractionFingerprint: (
    storage: StorageManager,
    fingerprint: string,
    meta: MetaState,
  ) => Promise<void>;
  runDeadlineAware: (
    operation: () => Promise<unknown>,
    phase: string,
    clearTimerOnError?: boolean,
    options?: { ignoreAbort?: boolean; ignoreDeadline?: boolean },
  ) => Promise<unknown>;
  isDeadlineError: (error: unknown) => boolean;
  createDeadlineError: (stage: string) => Error;
  deadlineMs?: number;
  clearBufferAfterExtraction: boolean;
  runPostPersistBestEffort: (
    stage: string,
    operation: () => Promise<unknown>,
    options?: { ignoreAbort?: boolean; ignoreDeadline?: boolean; propagateErrors?: boolean },
  ) => Promise<void>;
  extractionJudgeShadow: boolean;
  /** Facts this run's persist deferred to the judge — drives retention (#1523). */
  deferredCount: number;
  normalizedTurns: BufferTurn[];
  bufferKey: string;
  retainDeferredTurns: (bufferKey: string, turns: BufferTurn[], max: number) => Promise<void>;
  clearBuffer: (options?: { ignoreAbort?: boolean }) => Promise<void>;
  failOnExtractionFailure: boolean;
}

export interface ExtractionPostPersistResult {
  metadataFailed: boolean;
}

export async function runExtractionPostPersist(
  options: ExtractionPostPersistOptions,
): Promise<ExtractionPostPersistResult> {
  let metadataFailed = false;
  let deadlineError: Error | undefined;
  const recordFailure = (stage: string, error: unknown): void => {
    metadataFailed = true;
    if (options.isDeadlineError(error) && deadlineError === undefined) {
      deadlineError = error as Error;
    }
    log.warn(`runExtraction: ${stage} failed after durable persistence; continuing with buffer clear`, error);
  };
  // Applied under the storage's per-dir meta lock (storage.updateMeta): the
  // fingerprint record and the counters land on a FRESHLY loaded meta, so a
  // concurrent extraction's updates are not reverted by this save.
  const applyPostPersistMetadata = async (fresh: MetaState): Promise<void> => {
    if (options.extractionFingerprint && options.shouldPersistProcessedFingerprint) {
      try {
        await options.recordProcessedExtractionFingerprint(options.storage, options.extractionFingerprint, fresh);
      } catch (error) {
        metadataFailed = true;
        log.warn("runExtraction: processed fingerprint failed after durable persistence; continuing with buffer clear", error);
      }
    }
    fresh.extractionCount += 1;
    fresh.lastExtractionAt = new Date().toISOString();
    fresh.totalMemories += Array.isArray(options.result.facts) ? options.result.facts.length : 0;
    fresh.totalEntities += Array.isArray(options.result.entities) ? options.result.entities.length : 0;
  };
  try {
    await options.runDeadlineAware(
      () => options.storage.updateMeta(applyPostPersistMetadata),
      "during_post_persist_meta_save",
      false,
    );
  } catch (error) {
    recordFailure("metadata save", error);
  }
  const runBestEffort = options.runPostPersistBestEffort;
  await runExtractionDeferRetention(runBestEffort, {
    clearBufferAfterExtraction: options.clearBufferAfterExtraction,
    extractionJudgeShadow: options.extractionJudgeShadow,
    deferredCount: options.deferredCount,
    normalizedTurns: options.normalizedTurns,
    bufferKey: options.bufferKey,
    retainDeferredTurns: options.retainDeferredTurns,
  });
  await runBestEffort(
    "during_buffer_clear",
    () => options.clearBuffer({ ignoreAbort: true }),
    {
      ignoreAbort: true,
      ignoreDeadline: options.failOnExtractionFailure,
      propagateErrors: options.failOnExtractionFailure,
    },
  );
  if (options.failOnExtractionFailure && typeof options.deadlineMs === "number" && Date.now() >= options.deadlineMs) {
    throw options.createDeadlineError("during_buffer_clear");
  }
  if (deadlineError) throw deadlineError;
  return { metadataFailed };
}

/**
 * Record a processed fingerprint when applicable and advance the extraction
 * liveness watermark only for a provider-backed empty success. Fingerprinted
 * imports treat the metadata save as load-bearing dedupe state; normal live
 * runs treat the stamp as diagnostic and fail open. Deadline errors always
 * propagate.
 */
export async function commitEmptySuccessExtraction(args: {
  storage: StorageManager;
  extractionFingerprint: string | null;
  shouldPersistProcessedFingerprint: boolean;
  hasExtractionFailure: boolean;
  extractionSkippedReason: ExtractionResult["extractionSkippedReason"];
  recordProcessedExtractionFingerprint: (storage: StorageManager, fingerprint: string, meta: MetaState) => Promise<unknown>;
  runDeadlineAware: <T>(operation: () => Promise<T>, phase: string, clearTimerOnError?: boolean) => Promise<T>;
  isDeadlineError: (error: unknown) => boolean;
}): Promise<void> {
  const {
    storage,
    extractionFingerprint,
    shouldPersistProcessedFingerprint,
    hasExtractionFailure,
    extractionSkippedReason,
    recordProcessedExtractionFingerprint,
    runDeadlineAware,
    isDeadlineError,
  } = args;
  const shouldRecordFingerprint =
    extractionFingerprint !== null &&
    shouldPersistProcessedFingerprint &&
    !hasExtractionFailure;
  const shouldStampLiveness =
    !hasExtractionFailure && extractionSkippedReason === undefined;
  if (!shouldRecordFingerprint && !shouldStampLiveness) return;

  const metadataFailureIsFatal = shouldRecordFingerprint;
  try {
    await runDeadlineAware(
      () =>
        storage.updateMeta(async (meta) => {
          if (shouldRecordFingerprint) {
            await recordProcessedExtractionFingerprint(storage, extractionFingerprint!, meta);
          }
          if (shouldStampLiveness) {
            meta.extractionCount += 1;
            meta.lastExtractionAt = new Date().toISOString();
          }
        }),
      "during_empty_success_liveness_save",
      false,
    );
  } catch (err) {
    if (isDeadlineError(err)) throw err;
    if (metadataFailureIsFatal) throw err;
    log.warn("runExtraction: failed to stamp empty-success liveness watermark (non-fatal)", err);
  }
}

import path from "node:path";
import { mkdir, unlink, writeFile } from "node:fs/promises";
import { listJsonFiles, readJsonFile } from "./json-store.js";
import {
  assertIsoRecordedAt,
  assertSafePathSegment,
  assertString,
  isRecord,
  optionalString,
  optionalStringArray,
  recordStoreDay,
  validateStringRecord,
} from "./store-contract.js";

export type CommitmentLedgerSource = "tool_result" | "cli" | "system" | "manual";
export type CommitmentLedgerKind = "promise" | "follow_up" | "deadline" | "deliverable";
export type CommitmentLedgerState = "open" | "fulfilled" | "cancelled" | "expired";

export interface CommitmentLedgerEntry {
  schemaVersion: 1;
  entryId: string;
  recordedAt: string;
  sessionKey: string;
  source: CommitmentLedgerSource;
  kind: CommitmentLedgerKind;
  state: CommitmentLedgerState;
  scope: string;
  summary: string;
  dueAt?: string;
  entityRefs?: string[];
  workProductEntryRefs?: string[];
  objectiveStateSnapshotRefs?: string[];
  tags?: string[];
  metadata?: Record<string, string>;
  stateChangedAt?: string;
  resolvedAt?: string;
}

export interface CommitmentLedgerStatus {
  enabled: boolean;
  rootDir: string;
  entriesDir: string;
  entries: {
    total: number;
    valid: number;
    invalid: number;
    byKind: Partial<Record<CommitmentLedgerKind, number>>;
    byState: Partial<Record<CommitmentLedgerState, number>>;
    latestEntryId?: string;
    latestRecordedAt?: string;
    latestSessionKey?: string;
  };
  latestEntry?: CommitmentLedgerEntry;
  invalidEntries: Array<{
    path: string;
    error: string;
  }>;
  lifecycle?: {
    staleOpen: number;
    overdueOpen: number;
    decayEligibleResolved: number;
  };
}

export interface CommitmentLedgerLifecycleResult {
  transitionedToExpired: CommitmentLedgerEntry[];
  deletedResolved: CommitmentLedgerEntry[];
}

export function resolveCommitmentLedgerDir(memoryDir: string, overrideDir?: string): string {
  if (typeof overrideDir === "string" && overrideDir.trim().length > 0) {
    return overrideDir.trim();
  }
  return path.join(memoryDir, "state", "commitment-ledger");
}

export function validateCommitmentLedgerEntry(raw: unknown): CommitmentLedgerEntry {
  if (!isRecord(raw)) throw new Error("commitment ledger entry must be an object");
  if (raw.schemaVersion !== 1) throw new Error("schemaVersion must be 1");

  const source = assertString(raw.source, "source");
  if (!["tool_result", "cli", "system", "manual"].includes(source)) {
    throw new Error("source must be one of tool_result|cli|system|manual");
  }

  const kind = assertString(raw.kind, "kind");
  if (!["promise", "follow_up", "deadline", "deliverable"].includes(kind)) {
    throw new Error("kind must be one of promise|follow_up|deadline|deliverable");
  }

  const state = assertString(raw.state, "state");
  if (!["open", "fulfilled", "cancelled", "expired"].includes(state)) {
    throw new Error("state must be one of open|fulfilled|cancelled|expired");
  }

  const dueAt = optionalString(raw.dueAt);
  if (dueAt !== undefined) {
    assertIsoRecordedAt(dueAt, "dueAt");
  }

  const stateChangedAt = optionalString(raw.stateChangedAt);
  if (stateChangedAt !== undefined) {
    assertIsoRecordedAt(stateChangedAt, "stateChangedAt");
  }

  const resolvedAt = optionalString(raw.resolvedAt);
  if (resolvedAt !== undefined) {
    assertIsoRecordedAt(resolvedAt, "resolvedAt");
  }

  const normalizedStateChangedAt = stateChangedAt ?? (state === "open" ? undefined : assertString(raw.recordedAt, "recordedAt"));
  const normalizedResolvedAt = resolvedAt ?? (state === "open" ? undefined : normalizedStateChangedAt);

  return {
    schemaVersion: 1,
    entryId: assertSafePathSegment(assertString(raw.entryId, "entryId"), "entryId"),
    recordedAt: assertIsoRecordedAt(assertString(raw.recordedAt, "recordedAt")),
    sessionKey: assertString(raw.sessionKey, "sessionKey"),
    source: source as CommitmentLedgerSource,
    kind: kind as CommitmentLedgerKind,
    state: state as CommitmentLedgerState,
    scope: assertString(raw.scope, "scope"),
    summary: assertString(raw.summary, "summary"),
    dueAt,
    entityRefs: optionalStringArray(raw.entityRefs, "entityRefs"),
    workProductEntryRefs: optionalStringArray(raw.workProductEntryRefs, "workProductEntryRefs"),
    objectiveStateSnapshotRefs: optionalStringArray(raw.objectiveStateSnapshotRefs, "objectiveStateSnapshotRefs"),
    tags: optionalStringArray(raw.tags, "tags"),
    metadata: validateStringRecord(raw.metadata, "metadata"),
    stateChangedAt: normalizedStateChangedAt,
    resolvedAt: normalizedResolvedAt,
  };
}

export async function recordCommitmentLedgerEntry(options: {
  memoryDir: string;
  commitmentLedgerDir?: string;
  entry: CommitmentLedgerEntry;
}): Promise<string> {
  const rootDir = resolveCommitmentLedgerDir(options.memoryDir, options.commitmentLedgerDir);
  const validated = validateCommitmentLedgerEntry(options.entry);
  const day = recordStoreDay(validated.recordedAt);
  const entriesDir = path.join(rootDir, "entries", day);
  const filePath = path.join(entriesDir, `${validated.entryId}.json`);
  await mkdir(entriesDir, { recursive: true });
  await writeFile(filePath, JSON.stringify(validated, null, 2), "utf8");
  return filePath;
}

async function readCommitmentLedgerEntries(options: {
  memoryDir: string;
  commitmentLedgerDir?: string;
}): Promise<{
  files: string[];
  entries: CommitmentLedgerEntry[];
  entryFiles: Array<{ entry: CommitmentLedgerEntry; filePath: string }>;
  invalidEntries: Array<{ path: string; error: string }>;
}> {
  const rootDir = resolveCommitmentLedgerDir(options.memoryDir, options.commitmentLedgerDir);
  const files = await listJsonFiles(path.join(rootDir, "entries"));
  const entries: CommitmentLedgerEntry[] = [];
  const entryFiles: Array<{ entry: CommitmentLedgerEntry; filePath: string }> = [];
  const invalidEntries: Array<{ path: string; error: string }> = [];
  for (const filePath of files) {
    try {
      const entry = validateCommitmentLedgerEntry(await readJsonFile(filePath));
      entries.push(entry);
      entryFiles.push({ entry, filePath });
    } catch (error) {
      invalidEntries.push({
        path: filePath,
        error: error instanceof Error ? error.message : String(error),
      });
    }
  }
  return { files, entries, entryFiles, invalidEntries };
}

function isResolvedState(state: CommitmentLedgerState): boolean {
  return state === "fulfilled" || state === "cancelled" || state === "expired";
}

function isOverdueOpenEntry(entry: CommitmentLedgerEntry, nowMs: number): boolean {
  return entry.state === "open" && typeof entry.dueAt === "string" && Date.parse(entry.dueAt) < nowMs;
}

function isStaleOpenEntry(entry: CommitmentLedgerEntry, nowMs: number, staleDays: number): boolean {
  if (entry.state !== "open") return false;
  if (typeof entry.dueAt === "string") return false;
  const staleCutoff = nowMs - staleDays * 24 * 60 * 60 * 1000;
  return Date.parse(entry.recordedAt) < staleCutoff;
}

function isDecayEligibleResolvedEntry(entry: CommitmentLedgerEntry, nowMs: number, decayDays: number): boolean {
  if (!isResolvedState(entry.state)) return false;
  const reference = entry.resolvedAt ?? entry.stateChangedAt ?? entry.recordedAt;
  const decayCutoff = nowMs - decayDays * 24 * 60 * 60 * 1000;
  return Date.parse(reference) < decayCutoff;
}

function assertPositiveIntegerDays(value: number, keyName: string): number {
  if (!Number.isFinite(value) || !Number.isInteger(value) || value < 1) {
    throw new Error(`${keyName} must be an integer greater than or equal to 1; got ${String(value)}`);
  }
  return value;
}

async function findCommitmentLedgerEntryById(options: {
  memoryDir: string;
  commitmentLedgerDir?: string;
  entryId: string;
}): Promise<{ entry: CommitmentLedgerEntry; filePath: string } | null> {
  const { entryFiles } = await readCommitmentLedgerEntries(options);
  for (const candidate of entryFiles) {
    if (candidate.entry.entryId === options.entryId || path.basename(candidate.filePath, ".json") === options.entryId) {
      return candidate;
    }
  }
  return null;
}

export async function transitionCommitmentLedgerEntryState(options: {
  memoryDir: string;
  commitmentLedgerDir?: string;
  entryId: string;
  nextState: CommitmentLedgerState;
  changedAt: string;
}): Promise<CommitmentLedgerEntry> {
  const match = await findCommitmentLedgerEntryById(options);
  if (!match) {
    throw new Error(`commitment entry not found: ${options.entryId}`);
  }

  const changedAt = assertIsoRecordedAt(options.changedAt, "changedAt");
  const nextState = options.nextState;
  const nextEntry: CommitmentLedgerEntry = {
    ...match.entry,
    state: nextState,
    stateChangedAt: changedAt,
    resolvedAt: isResolvedState(nextState) ? changedAt : undefined,
  };

  await writeFile(match.filePath, JSON.stringify(validateCommitmentLedgerEntry(nextEntry), null, 2), "utf8");
  return nextEntry;
}

export async function applyCommitmentLedgerLifecycle(options: {
  memoryDir: string;
  commitmentLedgerDir?: string;
  enabled: boolean;
  decayDays: number;
  now?: string;
}): Promise<CommitmentLedgerLifecycleResult> {
  if (!options.enabled) {
    return { transitionedToExpired: [], deletedResolved: [] };
  }

  const nowIso = assertIsoRecordedAt(options.now ?? new Date().toISOString(), "now");
  const nowMs = Date.parse(nowIso);
  const decayDays = assertPositiveIntegerDays(options.decayDays, "decayDays");
  const { entryFiles } = await readCommitmentLedgerEntries(options);

  const transitionedToExpired: CommitmentLedgerEntry[] = [];
  const deletedResolved: CommitmentLedgerEntry[] = [];

  for (const { entry, filePath } of entryFiles) {

    if (isOverdueOpenEntry(entry, nowMs)) {
      const updated = validateCommitmentLedgerEntry({
        ...entry,
        state: "expired",
        stateChangedAt: nowIso,
        resolvedAt: nowIso,
      });
      await writeFile(filePath, JSON.stringify(updated, null, 2), "utf8");
      transitionedToExpired.push(updated);
      continue;
    }

    if (isDecayEligibleResolvedEntry(entry, nowMs, decayDays)) {
      await unlink(filePath);
      deletedResolved.push(entry);
    }
  }

  return { transitionedToExpired, deletedResolved };
}

export async function getCommitmentLedgerStatus(options: {
  memoryDir: string;
  commitmentLedgerDir?: string;
  enabled: boolean;
  lifecycleEnabled?: boolean;
  staleDays?: number;
  decayDays?: number;
  now?: string;
}): Promise<CommitmentLedgerStatus> {
  const rootDir = resolveCommitmentLedgerDir(options.memoryDir, options.commitmentLedgerDir);
  const entriesDir = path.join(rootDir, "entries");
  const { files, entries, invalidEntries } = await readCommitmentLedgerEntries(options);
  entries.sort((a, b) => b.recordedAt.localeCompare(a.recordedAt));
  const nowMs = Date.parse(assertIsoRecordedAt(options.now ?? new Date().toISOString(), "now"));
  const staleDays = Math.max(1, Math.floor(options.staleDays ?? 14));
  const decayDays = Math.max(1, Math.floor(options.decayDays ?? 90));

  const byKind: Partial<Record<CommitmentLedgerKind, number>> = {};
  const byState: Partial<Record<CommitmentLedgerState, number>> = {};
  for (const entry of entries) {
    byKind[entry.kind] = (byKind[entry.kind] ?? 0) + 1;
    byState[entry.state] = (byState[entry.state] ?? 0) + 1;
  }

  return {
    enabled: options.enabled,
    rootDir,
    entriesDir,
    entries: {
      total: files.length,
      valid: entries.length,
      invalid: invalidEntries.length,
      byKind,
      byState,
      latestEntryId: entries[0]?.entryId,
      latestRecordedAt: entries[0]?.recordedAt,
      latestSessionKey: entries[0]?.sessionKey,
    },
    latestEntry: entries[0],
    invalidEntries,
    lifecycle: options.lifecycleEnabled
      ? {
          overdueOpen: entries.filter((entry) => isOverdueOpenEntry(entry, nowMs)).length,
          staleOpen: entries.filter((entry) => isStaleOpenEntry(entry, nowMs, staleDays)).length,
          decayEligibleResolved: entries.filter((entry) => isDecayEligibleResolvedEntry(entry, nowMs, decayDays)).length,
        }
      : undefined,
  };
}

/**
 * dreams-ledger.ts — per-phase telemetry for the Dreams consolidation pipeline.
 *
 * Every scheduled or manual phase run appends one JSONL entry to
 *   <memoryDir>/state/dreams-ledger.jsonl
 *
 * The entry records which phase ran, how long it took, and a small
 * itemsProcessed counter so `remnic dreams status` can aggregate the last
 * 24-hour window without scanning the full memory corpus.
 *
 * This module is intentionally side-effect-free on import (no fs calls at
 * module load time) so tests can import it without touching the filesystem.
 */

import path from "node:path";
import { createReadStream, type ReadStream } from "node:fs";
import { appendFile, lstat, mkdir, readdir, readFile } from "node:fs/promises";
import { createInterface } from "node:readline";
import { isMacOsReplicationJunkBasename } from "../utils/macos-replication-junk.js";

// ── Types ─────────────────────────────────────────────────────────────────────

/** The three named phases of the Dreams consolidation pipeline. */
export type DreamsPhase = "lightSleep" | "rem" | "deepSleep";

/**
 * One entry written to the dreams ledger for every phase run.
 * Older entries that predate this field simply won't have it (no backfill).
 */
export interface DreamsLedgerEntry {
  /** Schema version — always 1 for entries written by this module. */
  schemaVersion: 1;
  /** ISO-8601 timestamp when the phase run started. */
  startedAt: string;
  /** ISO-8601 timestamp when the phase run completed. */
  completedAt: string;
  /** Wall-clock duration in milliseconds. */
  durationMs: number;
  /**
   * Which Dreams phase this entry represents.
   * - `lightSleep` — recent activity scoring + clustering
   * - `rem`        — cross-session synthesis, supersession, consolidation
   * - `deepSleep`  — tier migration, page-version snapshots, archive
   */
  phase: DreamsPhase;
  /** How many memory items were evaluated (scored / clustered / migrated). */
  itemsProcessed: number;
  /** Whether this was a dry-run (no writes committed). */
  dryRun: boolean;
  /**
   * How the phase was triggered.
   * - `scheduled` — invoked by the governance cron or orchestrator maintenance pass
   * - `manual`    — invoked via `remnic dreams run`
   */
  trigger: "scheduled" | "manual";
  /** Free-form notes for debugging (optional, never required). */
  notes?: string;
}

/** Aggregated stats for a single phase over a time window. */
export interface DreamsPhaseStatus {
  phase: DreamsPhase;
  /** Number of phase runs in the window. */
  runCount: number;
  /** Total wall-clock milliseconds across all runs in the window. */
  totalDurationMs: number;
  /** Total items processed across all runs in the window. */
  totalItemsProcessed: number;
  /** ISO-8601 timestamp of the most recent completed run, or null if none. */
  lastRunAt: string | null;
  /** Duration of the most recent run in ms, or null if none. */
  lastDurationMs: number | null;
}

/** Shape returned by `getDreamsStatus` — the canonical telemetry response. */
export interface DreamsStatusResult {
  /** ISO-8601 start of the query window (inclusive). */
  windowStart: string;
  /** ISO-8601 end of the query window (exclusive). */
  windowEnd: string;
  /** Per-phase summaries, always present for all three phases. */
  phases: {
    lightSleep: DreamsPhaseStatus;
    rem: DreamsPhaseStatus;
    deepSleep: DreamsPhaseStatus;
  };
}

// ── Path helpers ──────────────────────────────────────────────────────────────

export function dreamsLedgerPath(memoryDir: string): string {
  return path.join(memoryDir, "state", "dreams-ledger.jsonl");
}

// ── Writer ────────────────────────────────────────────────────────────────────

/**
 * Append a single entry to the dreams ledger.
 * Creates the file (and its parent directory) if needed.
 * Uses `appendFile` (O_APPEND) so concurrent callers never overwrite each other.
 */
export async function appendDreamsLedgerEntry(
  memoryDir: string,
  entry: DreamsLedgerEntry,
): Promise<void> {
  const ledgerPath = dreamsLedgerPath(memoryDir);
  await mkdir(path.dirname(ledgerPath), { recursive: true });
  await appendFile(ledgerPath, JSON.stringify(entry) + "\n", "utf-8");
}

// ── Reader ────────────────────────────────────────────────────────────────────

/**
 * Parse and validate one ledger line into a `DreamsLedgerEntry`, or `null` when
 * blank/malformed/incomplete. Shared by the streaming reader and the windowed
 * status aggregator so both apply the identical fail-open guard.
 */
function parseDreamsLedgerLine(line: string): DreamsLedgerEntry | null {
  const trimmed = line.trim();
  if (!trimmed) return null;
  let parsed: Record<string, unknown>;
  try {
    const raw = JSON.parse(trimmed);
    if (typeof raw !== "object" || raw === null) return null;
    parsed = raw as Record<string, unknown>;
  } catch {
    return null; // Malformed JSON — skip (fail-open).
  }

  // Required, strongly-typed fields. A row missing or mistyping any of these is
  // not a usable telemetry entry.
  const phase = parsed.phase;
  if (phase !== "lightSleep" && phase !== "rem" && phase !== "deepSleep") return null;
  if (
    typeof parsed.startedAt !== "string" ||
    typeof parsed.completedAt !== "string" ||
    typeof parsed.durationMs !== "number" ||
    typeof parsed.itemsProcessed !== "number"
  ) {
    return null;
  }

  // Optional fields: absence is tolerated (older entries predate them, no
  // backfill), but a PRESENT value with the wrong type/value marks the row
  // malformed and skips it — never silently coerced to a default (issue #1910).
  if ("schemaVersion" in parsed && parsed.schemaVersion !== 1) return null;
  if ("dryRun" in parsed && typeof parsed.dryRun !== "boolean") return null;
  if ("trigger" in parsed && parsed.trigger !== "manual" && parsed.trigger !== "scheduled") {
    return null;
  }

  return {
    schemaVersion: 1,
    startedAt: parsed.startedAt,
    completedAt: parsed.completedAt,
    durationMs: parsed.durationMs,
    phase,
    itemsProcessed: parsed.itemsProcessed,
    dryRun: parsed.dryRun === true,
    trigger: parsed.trigger === "manual" ? "manual" : "scheduled",
    notes: typeof parsed.notes === "string" ? parsed.notes : undefined,
  };
}

/**
 * Stream the dreams ledger line-by-line. The ledger is plaintext `appendFile`
 * (never encrypted), so a raw line stream is safe at any size — heap stays
 * O(1) in the file, unlike the previous whole-file `readFile` + `split`.
 * Yields nothing when the ledger does not exist yet.
 */
export async function* streamDreamsLedgerLines(memoryDir: string): AsyncGenerator<string> {
  const ledgerPath = dreamsLedgerPath(memoryDir);
  let input: ReadStream;
  try {
    input = createReadStream(ledgerPath, { encoding: "utf8" });
  } catch (err) {
    if ((err as NodeJS.ErrnoException).code === "ENOENT") return;
    throw err;
  }
  const rl = createInterface({ input, crlfDelay: Infinity });
  try {
    for await (const line of rl) yield line;
  } catch (err) {
    if ((err as NodeJS.ErrnoException).code === "ENOENT") return;
    throw err;
  } finally {
    // Close the readline interface AND destroy the underlying stream. When a
    // consumer stops early (e.g. `getDreamsStatus` breaks out), the generator's
    // `.return()` runs this finally; `rl.close()` alone leaves the file
    // descriptor open, so destroy the stream to release it (issue #1910).
    rl.close();
    input.destroy();
  }
}

/**
 * Parse all valid `DreamsLedgerEntry` rows from the ledger file. Thin wrapper
 * over the line stream so any caller that genuinely needs every row still
 * works; `getDreamsStatus` streams directly and filters in-window instead.
 * Malformed lines are silently skipped (resilience over strictness for
 * telemetry).
 */
export async function readDreamsLedgerEntries(memoryDir: string): Promise<DreamsLedgerEntry[]> {
  const entries: DreamsLedgerEntry[] = [];
  for await (const line of streamDreamsLedgerLines(memoryDir)) {
    const entry = parseDreamsLedgerLine(line);
    if (entry) entries.push(entry);
  }
  return entries;
}

// ── Aggregator ────────────────────────────────────────────────────────────────

const ALL_PHASES: DreamsPhase[] = ["lightSleep", "rem", "deepSleep"];
const MAX_WINDOW_HOURS = 24 * 365 * 100;

export function normalizeDreamsStatusWindowHours(value: unknown, fallback = 24): number {
  const raw = value === undefined || value === null ? fallback : value;
  if (
    typeof raw !== "number" ||
    !Number.isFinite(raw) ||
    !Number.isInteger(raw) ||
    raw < 1 ||
    raw > MAX_WINDOW_HOURS
  ) {
    throw new RangeError(`windowHours must be a positive integer no greater than ${MAX_WINDOW_HOURS}`);
  }
  return raw;
}

/**
 * Build per-phase 24-hour summary.
 *
 * @param memoryDir   The memory directory (parent of `state/`).
 * @param windowHours How many hours to look back (default 24).
 * @param now         Reference time (default `new Date()`).
 */
export async function getDreamsStatus(
  memoryDir: string,
  windowHours = 24,
  now: Date = new Date(),
): Promise<DreamsStatusResult> {
  const boundedWindowHours = normalizeDreamsStatusWindowHours(windowHours);
  const nowMs = now.getTime();
  if (!Number.isFinite(nowMs)) {
    throw new RangeError("now must be a valid Date");
  }
  const windowMs = boundedWindowHours * 60 * 60 * 1000;
  const windowStart = new Date(nowMs - windowMs);
  const windowEnd = now;
  if (!Number.isFinite(windowStart.getTime())) {
    throw new RangeError("windowHours produces an invalid status window");
  }

  const windowStartMs = windowStart.getTime();
  const windowEndMs = windowEnd.getTime();

  const statusMap = new Map<DreamsPhase, DreamsPhaseStatus>();
  for (const phase of ALL_PHASES) {
    statusMap.set(phase, {
      phase,
      runCount: 0,
      totalDurationMs: 0,
      totalItemsProcessed: 0,
      lastRunAt: null,
      lastDurationMs: null,
    });
  }

  // Stream the ledger and aggregate every in-window row inline, so heap use is
  // O(number of phases) regardless of window or file size (issue #1910) — no
  // per-row array and no row cap, so a large in-window window is still counted
  // in full rather than truncated.
  for await (const line of streamDreamsLedgerLines(memoryDir)) {
    const entry = parseDreamsLedgerLine(line);
    if (!entry) continue;
    const ts = Date.parse(entry.completedAt);
    if (!Number.isFinite(ts) || ts < windowStartMs || ts >= windowEndMs) continue;
    const status = statusMap.get(entry.phase);
    if (!status) continue;
    status.runCount += 1;
    status.totalDurationMs += entry.durationMs;
    status.totalItemsProcessed += entry.itemsProcessed;
    // Track the most recent run (by completedAt).
    if (status.lastRunAt === null || ts > Date.parse(status.lastRunAt)) {
      status.lastRunAt = entry.completedAt;
      status.lastDurationMs = entry.durationMs;
    }
  }

  return {
    windowStart: windowStart.toISOString(),
    windowEnd: windowEnd.toISOString(),
    phases: {
      lightSleep: statusMap.get("lightSleep")!,
      rem: statusMap.get("rem")!,
      deepSleep: statusMap.get("deepSleep")!,
    },
  };
}

// ── Phase runner (PR 4/4: manual invocation) ─────────────────────────────────

export interface DreamsRunOptions {
  memoryDir: string;
  phase: DreamsPhase;
  dryRun?: boolean;
}

/** Public result shape — identical to what HTTP, MCP, and CLI surfaces expose. */
export interface DreamsRunResult {
  phase: DreamsPhase;
  dryRun: boolean;
  durationMs: number;
  itemsProcessed: number;
  notes?: string;
}

/** Internal result shape returned by `runDreamsPhase` — includes the raw ledger entry. */
export interface DreamsRunResultInternal extends DreamsRunResult {
  ledgerEntry?: DreamsLedgerEntry;
}

export async function recordDreamsPhaseRun(options: {
  memoryDir: string;
  phase: DreamsPhase;
  trigger: DreamsLedgerEntry["trigger"];
  dryRun?: boolean;
  itemsProcessed: number;
  notes?: string;
  startedAt?: string;
  completedAt?: string;
}): Promise<DreamsLedgerEntry> {
  const startedAt = options.startedAt ?? new Date().toISOString();
  const completedAt = options.completedAt ?? new Date().toISOString();
  const durationMs = Math.max(0, Date.parse(completedAt) - Date.parse(startedAt));
  const ledgerEntry: DreamsLedgerEntry = {
    schemaVersion: 1,
    startedAt,
    completedAt,
    durationMs: Number.isFinite(durationMs) ? durationMs : 0,
    phase: options.phase,
    itemsProcessed: Math.max(0, Math.floor(options.itemsProcessed)),
    dryRun: options.dryRun === true,
    trigger: options.trigger,
    notes: options.notes,
  };
  if (!ledgerEntry.dryRun) {
    await appendDreamsLedgerEntry(options.memoryDir, ledgerEntry);
  }
  return ledgerEntry;
}

/**
 * Manually invoke a single Dreams phase pass.
 *
 * For light sleep and REM: runs a lightweight scan against the observation
 * ledger and returns a count of items that would be (or were, if not dry-run)
 * processed.  The actual heavy consolidation is long-running and orchestrator-
 * bound; the manual surface delegates to existing ledger utilities and returns
 * the phase telemetry so callers get the same shape as a scheduled run.
 *
 * For deep sleep: delegates to the memory governance run (shadow mode when
 * dryRun is true, apply mode otherwise).
 */
export async function runDreamsPhase(
  options: DreamsRunOptions,
  governanceRunner?: (opts: { memoryDir: string; dryRun: boolean }) => Promise<{ scannedMemories: number; appliedActionCount: number; notes?: string }>,
  phaseRunner?: (opts: { memoryDir: string; phase: Exclude<DreamsPhase, "deepSleep"> }) => Promise<{ itemsProcessed: number; notes?: string }>,
): Promise<DreamsRunResultInternal> {
  const { memoryDir, phase, dryRun = false } = options;
  const startedAt = new Date().toISOString();

  let itemsProcessed = 0;
  let notes: string | undefined;

  if (phase === "lightSleep") {
    // Dry-run light sleep counts recent observation entries as a preview.
    // Live runs must be backed by the orchestrator phase runner so the command
    // never reports success without executing the phase.
    if (!dryRun) {
      if (!phaseRunner) {
        throw new Error("light-sleep manual runs require a phase runner");
      }
      const result = await phaseRunner({ memoryDir, phase });
      itemsProcessed = Math.max(0, Math.floor(result.itemsProcessed));
      notes = result.notes ?? `scored ${itemsProcessed} memories`;
    } else {
      // Light sleep: count observation ledger entries from the last 24h as a
      // proxy for "items scored". The live value-scoring pass runs through the
      // phase runner above.
      try {
        const ledgerPath = path.join(memoryDir, "state", "observation-ledger", "rebuilt-observations.jsonl");
        let raw = "";
        try {
          raw = await readFile(ledgerPath, "utf-8");
        } catch {
          // No ledger yet — zero items.
        }
        const lines = raw.split("\n").filter((l) => l.trim().length > 0);
        const nowMs = Date.now();
        const cutoff = nowMs - 24 * 60 * 60 * 1000;
        itemsProcessed = lines.filter((line) => {
          try {
            const obj = JSON.parse(line) as {
              hour?: string;
              timestamp?: string;
              ts?: string;
            };
            const timestamp = typeof obj.hour === "string"
              ? obj.hour
              : typeof obj.ts === "string"
                ? obj.ts
                : typeof obj.timestamp === "string"
                  ? obj.timestamp
                  : null;
            if (!timestamp) return false;
            const ms = Date.parse(timestamp);
            return Number.isFinite(ms) && ms >= cutoff && ms < nowMs;
          } catch {
            return false;
          }
        }).length;
        notes = `dry-run: would score ${itemsProcessed} observation entries`;
      } catch (err) {
        throw new Error(`light-sleep scan failed: ${err instanceof Error ? err.message : String(err)}`);
      }
    }
  } else if (phase === "rem") {
    if (!dryRun) {
      if (!phaseRunner) {
        throw new Error("REM manual runs require a phase runner");
      }
      const result = await phaseRunner({ memoryDir, phase });
      itemsProcessed = Math.max(0, Math.floor(result.itemsProcessed));
      notes = result.notes ?? `REM pass assessed ${itemsProcessed} memories`;
    } else {
      // REM dry-runs estimate candidates without synthesizing or archiving.
      try {
        const stateFilePath = path.join(memoryDir, "state", "semantic-consolidation-last-run.json");
        let lastRunAt: string | null = null;
        try {
          const stateRaw = await readFile(stateFilePath, "utf-8");
          const stateData = JSON.parse(stateRaw) as { lastRunAt?: string };
          lastRunAt = stateData.lastRunAt ?? null;
        } catch {
          // No state file — never run.
        }
        const memFiles = await listMemoryFiles(memoryDir);
        itemsProcessed = memFiles.length;
        notes = `dry-run: ${itemsProcessed} memories would enter REM consolidation pass${lastRunAt ? ` (last run: ${lastRunAt})` : " (never run)"}`;
      } catch (err) {
        throw new Error(`REM scan failed: ${err instanceof Error ? err.message : String(err)}`);
      }
    }
  } else {
    // deep sleep
    if (governanceRunner) {
      try {
        const result = await governanceRunner({ memoryDir, dryRun });
        itemsProcessed = result.scannedMemories;
        notes = result.notes ?? (dryRun ? `dry-run: ${result.appliedActionCount} actions proposed` : `${result.appliedActionCount} actions applied`);
      } catch (err) {
        throw new Error(`deep-sleep governance run failed: ${err instanceof Error ? err.message : String(err)}`);
      }
    } else {
      // Fallback: count memory files.
      const memFiles = await listMemoryFiles(memoryDir);
      itemsProcessed = memFiles.length;
      notes = dryRun
        ? `dry-run: ${itemsProcessed} memories eligible for deep-sleep governance`
        : `assessed ${itemsProcessed} memories for deep-sleep governance`;
    }
  }

  const completedAt = new Date().toISOString();
  const durationMs = Math.max(0, Date.parse(completedAt) - Date.parse(startedAt));
  let ledgerEntry: DreamsLedgerEntry | undefined;
  try {
    ledgerEntry = await recordDreamsPhaseRun({
      memoryDir,
      startedAt,
      completedAt,
      phase,
      itemsProcessed,
      dryRun,
      trigger: "manual",
      notes,
    });
  } catch {
    // Telemetry is best-effort: the phase work has already completed.
  }

  return {
    phase,
    dryRun,
    durationMs: ledgerEntry?.durationMs ?? durationMs,
    itemsProcessed,
    notes,
    ledgerEntry,
  };
}

// ── Shared governance result mapping ──────────────────────────────────────────

export function summarizeGovernanceResultForDreams(
  govResult: {
    summary?: { scannedMemories?: number };
    proposedActions: unknown[];
    appliedActions: unknown[];
    reviewQueue: unknown[];
  },
  dryRun: boolean,
): { scannedMemories: number; appliedActionCount: number; notes?: string } {
  const proposedCount = govResult.proposedActions.length;
  const appliedCount = govResult.appliedActions.length;
  const scannedCount =
    typeof govResult.summary?.scannedMemories === "number" &&
    Number.isFinite(govResult.summary.scannedMemories)
      ? Math.max(0, Math.floor(govResult.summary.scannedMemories))
      : govResult.reviewQueue.length;
  return {
    scannedMemories: scannedCount,
    appliedActionCount: appliedCount,
    notes: dryRun
      ? `shadow mode: ${proposedCount} actions proposed`
      : `applied ${appliedCount} actions`,
  };
}

