async function listMemoryFiles(memoryDir: string): Promise<string[]> {
  const out: string[] = [];
  try {
    const root = await lstat(memoryDir);
    if (root.isSymbolicLink()) {
      throw new Error(`memoryDir must not be a symlink: ${memoryDir}`);
    }
    if (!root.isDirectory()) return out;
  } catch (err) {
    if (err instanceof Error && /must not be a symlink/.test(err.message)) {
      throw err;
    }
    return out;
  }

  async function walk(dir: string): Promise<void> {
    let entries: Array<{ name: string; isDirectory(): boolean; isFile(): boolean; isSymbolicLink(): boolean }>;
    try {
      entries = (await readdir(dir, { withFileTypes: true })) as typeof entries;
    } catch {
      return;
    }
    for (const entry of entries) {
      if (entry.isSymbolicLink()) continue;
      if (isMacOsReplicationJunkBasename(entry.name)) continue;
      const full = path.join(dir, entry.name);
      if (entry.isDirectory()) {
        // Skip state/ and archive/ subdirs.
        if (
          entry.name === "state" ||
          entry.name === "archive" ||
          entry.name === "namespaces" ||
          entry.name === ".git"
        ) continue;
        await walk(full);
      } else if (entry.isFile() && entry.name.endsWith(".md")) {
        out.push(full);
      }
    }
  }

  await walk(memoryDir);
  return out;
}

import { createHash } from "node:crypto";

import type { MemoryFile } from "../types.js";
import { isRecord } from "../store-contract.js";
import type { PropagationEvent } from "./dependency-propagation.js";
import type {
  DependencyPropagationJob,
  DependencyPropagationJobStatus,
} from "./dependency-propagation-delivery.js";

export const JOB_STATES: readonly DependencyPropagationJobStatus[] = [
  "prepared",
  "ready",
  "leased",
  "retryable",
  "completed",
  "dead_letter",
  "canceled",
];

const CAUSES: Record<PropagationEvent["cause"], true> = {
  contradiction: true,
  temporal_supersession: true,
  consolidation_invalidate: true,
  consolidation_merge: true,
};

export function isFiniteNumber(value: unknown): value is number {
  return typeof value === "number" && Number.isFinite(value);
}

export function isPropagationEvent(value: unknown): value is PropagationEvent {
  if (!isRecord(value) || !isRecord(value.oldMemory)) return false;
  const oldMemory = value.oldMemory;
  if (!isRecord(oldMemory.frontmatter)) return false;
  const frontmatter = oldMemory.frontmatter;
  if (typeof oldMemory.content !== "string" || typeof frontmatter.id !== "string") return false;
  if (
    !(value.replacementId === null || typeof value.replacementId === "string") ||
    !(value.replacementContent === null || typeof value.replacementContent === "string") ||
    typeof value.namespaceScope !== "string" ||
    value.namespaceScope.length === 0 ||
    typeof value.cause !== "string" ||
    !Object.hasOwn(CAUSES, value.cause)
  ) {
    return false;
  }
  const temporalMutation = value.temporalMutation;
  if (
    temporalMutation !== undefined &&
    (!isRecord(temporalMutation) ||
      typeof temporalMutation.supersededAt !== "string" ||
      (temporalMutation.invalidAt !== undefined && typeof temporalMutation.invalidAt !== "string") ||
      !Array.isArray(temporalMutation.matchedKeys) ||
      temporalMutation.matchedKeys.some((key) => typeof key !== "string"))
  ) {
    return false;
  }
  if (frontmatter.links !== undefined) {
    if (!Array.isArray(frontmatter.links)) return false;
    for (const link of frontmatter.links) {
      if (!isRecord(link) || typeof link.targetId !== "string" || typeof link.linkType !== "string") return false;
    }
  }
  return true;
}

export function validateJob(
  value: unknown,
  expectedState?: DependencyPropagationJobStatus,
): DependencyPropagationJob | null {
  if (!isRecord(value)) return null;
  const status = value.status;
  const event = value.event;
  const attempts = value.attempts;
  const createdAt = value.createdAt;
  const updatedAt = value.updatedAt;
  if (
    typeof value.jobId !== "string" ||
    value.jobId.length === 0 ||
    typeof value.namespace !== "string" ||
    value.namespace.length === 0 ||
    typeof value.sourceId !== "string" ||
    value.sourceId.length === 0 ||
    !isPropagationEvent(event) ||
    value.jobId !== eventJobId(event) ||
    value.namespace !== event.namespaceScope ||
    value.sourceId !== event.oldMemory.frontmatter.id ||
    typeof status !== "string" ||
    !JOB_STATES.includes(status as DependencyPropagationJobStatus) ||
    (expectedState !== undefined && status !== expectedState) ||
    typeof attempts !== "number" ||
    !Number.isInteger(attempts) ||
    attempts < 0 ||
    !isFiniteNumber(createdAt) ||
    !isFiniteNumber(updatedAt)
  ) {
    return null;
  }
  const revision = value.revision === undefined ? 0 : value.revision;
  if (typeof revision !== "number" || !Number.isInteger(revision) || revision < 0) return null;
  const reservationIdsValue = value.reservationIds;
  if (!Array.isArray(reservationIdsValue)) return null;
  const reservationIds = reservationIdsValue as unknown[];
  if (
    reservationIds.some(
      (reservationId) => typeof reservationId !== "string" || reservationId.trim().length === 0,
    ) || new Set(reservationIds).size !== reservationIds.length
  ) {
    return null;
  }
  const reservations = value.reservations;
  if (
    typeof reservations !== "number" ||
    !Number.isInteger(reservations) ||
    reservations < 0 ||
    reservations !== reservationIds.length
  ) {
    return null;
  }
  const nextAttemptAt = value.nextAttemptAt;
  const leaseOwner = value.leaseOwner;
  const leaseExpiresAt = value.leaseExpiresAt;
  const lastError = value.lastError;
  const preparedReplacementFingerprint = value.preparedReplacementFingerprint;
  if (nextAttemptAt !== undefined && !isFiniteNumber(nextAttemptAt)) return null;
  if (leaseOwner !== undefined && typeof leaseOwner !== "string") return null;
  if (leaseExpiresAt !== undefined && !isFiniteNumber(leaseExpiresAt)) return null;
  if (lastError !== undefined && typeof lastError !== "string") return null;
  if (
    preparedReplacementFingerprint !== undefined &&
    (typeof preparedReplacementFingerprint !== "string" || preparedReplacementFingerprint.length === 0)
  ) {
    return null;
  }
  if (status === "retryable" && nextAttemptAt === undefined) return null;
  if (status === "leased" && (typeof leaseOwner !== "string" || leaseExpiresAt === undefined)) return null;
  return {
    jobId: value.jobId as string,
    namespace: value.namespace as string,
    sourceId: value.sourceId as string,
    event,
    status: status as DependencyPropagationJobStatus,
    attempts,
    createdAt,
    updatedAt,
    reservations,
    reservationIds: [...(reservationIds as string[])],
    revision,
    ...(nextAttemptAt === undefined ? {} : { nextAttemptAt: nextAttemptAt as number }),
    ...(leaseOwner === undefined ? {} : { leaseOwner: leaseOwner as string }),
    ...(leaseExpiresAt === undefined ? {} : { leaseExpiresAt: leaseExpiresAt as number }),
    ...(lastError === undefined ? {} : { lastError: lastError as string }),
    ...(preparedReplacementFingerprint === undefined
      ? {}
      : { preparedReplacementFingerprint: preparedReplacementFingerprint as string }),
  };
}
export function canonicalize(value: unknown): unknown {
  if (Array.isArray(value)) return value.map((item) => canonicalize(item));
  if (isRecord(value)) {
    const result: Record<string, unknown> = {};
    for (const key of Object.keys(value).sort()) {
      if (value[key] === undefined) continue;
      result[key] = canonicalize(value[key]);
    }
    return result;
  }
  return value === undefined ? null : value;
}

export function compareByteStable(left: string, right: string): number {
  return Buffer.from(left, "utf8").compare(Buffer.from(right, "utf8"));
}

export function canonicalEvent(event: PropagationEvent): PropagationEvent {
  return canonicalize(event) as PropagationEvent;
}

export function stableLinks(links: unknown): unknown {
  if (!Array.isArray(links)) return links;
  return [...links].sort((left, right) => {
    const leftKey = JSON.stringify(canonicalize(left));
    const rightKey = JSON.stringify(canonicalize(right));
    return compareByteStable(leftKey, rightKey);
  });
}

export function matchesPreparedSource(
  current: MemoryFile,
  prepared: Pick<MemoryFile, "content" | "frontmatter">,
): boolean {
  const { accessCount: _currentAccessCount, lastAccessed: _currentLastAccessed, ...currentSemantic } =
    current.frontmatter;
  const { accessCount: _preparedAccessCount, lastAccessed: _preparedLastAccessed, ...preparedSemantic } =
    prepared.frontmatter;
  const normalizedCurrent = { ...currentSemantic, links: stableLinks(currentSemantic.links) };
  const normalizedPrepared = { ...preparedSemantic, links: stableLinks(preparedSemantic.links) };
  return (
    current.content === prepared.content &&
    JSON.stringify(canonicalize(normalizedCurrent)) === JSON.stringify(canonicalize(normalizedPrepared))
  );
}

export function eventJobId(event: PropagationEvent): string {
  const { accessCount: _accessCount, lastAccessed: _lastAccessed, links, ...semanticFrontmatter } =
    event.oldMemory.frontmatter;
  const semanticEvent = {
    ...event,
    oldMemory: {
      ...event.oldMemory,
      frontmatter: { ...semanticFrontmatter, links: stableLinks(links) },
    },
  };
  return createHash("sha256").update(JSON.stringify(canonicalize(semanticEvent))).digest("hex");
}

export function isNotFound(error: unknown): boolean {
  return isRecord(error) && error.code === "ENOENT";
}

import path from "node:path";
import { serializeMutations, withHeldFileLock } from "../utils/serialize-mutations.js";
import { ContentHashIndex, type StorageManager } from "../index.js";
import type { MemoryFile } from "../types.js";
import { normalizeStoredHashSource } from "./extraction-persist-citation.js";
import { stripAttributesSuffix } from "../structured-attributes.js";
import { log } from "../logger.js";

/**
 * Fact-dedup commit window (codex P2, #1526): with extractionQueueConcurrency
 * > 1 (or daemon + external drain workers), two sessions can both pass the
 * content-hash check at persist time and both write, producing duplicate
 * active copies — the persist-time checks run well before the write, and
 * writeMemory mints a fresh id per write. This module serializes the short
 * "final recheck → write" window per storage dir (in-process chain +
 * fail-closed cross-process fact-dedup.lock, mirroring the profile/meta lock
 * shape: bounded, no LLM or corpus-scale work planned inside, throw BEFORE
 * any read/write when the lock is not acquired). The persist-time check stays
 * OUTSIDE the window exactly like the consolidation LLM call stays outside
 * commitConsolidatedProfile.
 */
export interface FactDedupProbe {
  hasContentHashDedup(storage: StorageManager, key: string): Promise<boolean>;
}

interface FactDedupMatchOptions {
  readonly category: string;
  readonly contentHashDedupKey: string;
  readonly connector?: string;
  readonly citationEnabled: boolean;
  readonly citationTemplate: string;
}

function matchesActiveConnectorDuplicate(memory: MemoryFile, opts: FactDedupMatchOptions): boolean {
  if (memory.frontmatter.category !== opts.category) return false;
  if ((memory.frontmatter.status ?? "active") !== "active") return false;
  // Thread 5 (QPDE5): for procedures the hash is keyed on the full
  // body (title + steps via buildProcedurePersistBody), so compare
  // against contentHashDedupKey — not the canonical title-only form.
  // Thread 3 (QO42V): facts with structuredAttributes get an appended
  // [Attributes: ...] suffix in the stored body that the hash key lacks;
  // strip it before comparing so same-connector enriched facts dedup
  // correctly.
  if (normalizeStoredHashSource(stripAttributesSuffix(memory.content ?? ""), opts.citationEnabled, opts.citationTemplate) !==
    ContentHashIndex.normalizeContent(opts.contentHashDedupKey)) return false;
  return (memory.frontmatter.sourceConnector?.trim() || undefined) === opts.connector;
}

/**
 * Connector-aware duplicate confirm: same final semantics as the persist-time
 * check — an authoritative index miss is a clean NOT-duplicate, a hash hit or
 * a non-authoritative/failed lookup must be confirmed against the hot+cold
 * corpus (same category, active, same normalized content, same connector),
 * and a corpus-scan failure fails OPEN so an unverifiable state cannot
 * silently drop content.
 */
export async function confirmActiveFactDuplicate(
  probe: FactDedupProbe,
  storage: StorageManager,
  opts: FactDedupMatchOptions,
): Promise<boolean> {
  let needsCorpusConfirm: boolean;
  try {
    if (!(await probe.hasContentHashDedup(storage, opts.contentHashDedupKey))) {
      if (await storage.isFactContentHashAuthoritative()) return false;
      needsCorpusConfirm = true;
    } else {
      needsCorpusConfirm = true;
    }
  } catch {
    // Dedup lookup failed (e.g. the authoritative rebuild could not run). Do
    // NOT fail-open into a possible duplicate — confirm against the corpus.
    needsCorpusConfirm = true;
  }
  try {
    // #2016 cold-tier finding: the authoritative content-hash rebuild unions
    // the HOT and COLD tiers, so a cold-only active copy must still confirm
    // the duplicate and suppress the redundant hot write.
    const [hotMems, coldMems] = await Promise.all([
      storage.readAllMemories(),
      storage.readAllColdMemories(),
    ]);
    return hotMems.some((m) => matchesActiveConnectorDuplicate(m, opts)) ||
      coldMems.some((m) => matchesActiveConnectorDuplicate(m, opts));
  } catch (err) {
    log.warn(
      `connector-aware dedup scan failed for storage ${storage.dir}; writing fail-open: ${err instanceof Error ? err.message : String(err)}`,
    );
    return false;
  }
}

export type FactDedupWindowOutcome<T> = { suppressed: true } | { suppressed: false; result: T };

/**
 * Run `write` inside the per-dir fact-dedup window: recheck `recheck` (the
 * SAME confirm used at persist time, now under the lock) and suppress as a
 * duplicate when a concurrent session committed the same content first;
 * otherwise write. Lock contention throws (fail closed) — never an unlocked
 * write; the extraction retry path retains the accepted turns.
 */
export async function persistUnderFactDedupWindow<T>(
  storageDir: string,
  recheck: () => Promise<boolean>,
  write: () => Promise<T>,
): Promise<FactDedupWindowOutcome<T>> {
  return serializeMutations(`fact-dedup:${storageDir}`, () =>
    withHeldFileLock(
      path.join(storageDir, "fact-dedup.lock"),
      // Bounded: the window holds one corpus confirm + one memory write, not a
      // scan-length lock (catalog round 5 adoption note).
      { staleMs: 5_000, maxWaitMs: 2_000, pollMs: 50 },
      async (acquired) => {
        if (!acquired) {
          throw new Error(`fact write skipped: fact-dedup.lock not acquired (${storageDir})`);
        }
        if (await recheck()) return { suppressed: true };
        return { suppressed: false, result: await write() };
      },
    ),
  );
}

import { mkdir, unlink, writeFile } from "node:fs/promises";
import path from "node:path";
import { resolveAbstractionNodeStoreDir, validateAbstractionNode, type AbstractionNode } from "./abstraction-nodes.js";
import { listJsonFilesStrict, readJsonFile, withJsonStoreMutationLock, writeJsonFileAtomic } from "./json-store.js";
import { compareDeterministicStrings, mergeSortedUniqueStrings } from "./deterministic-order.js";
import { isNotFoundError } from "./utils/errno.js";
import {
  assertIsoRecordedAt,
  assertSafePathSegment,
  assertString,
  isRecord,
  optionalStringArray,
  validateStringRecord,
} from "./store-contract.js";

export type CueAnchorType = "entity" | "file" | "tool" | "outcome" | "constraint" | "date";

export interface CueAnchor {
  schemaVersion: 1;
  anchorId: string;
  anchorType: CueAnchorType;
  anchorValue: string;
  normalizedCue: string;
  recordedAt: string;
  sessionKey: string;
  nodeRefs: string[];
  sourceMemoryIdsByNodeRef?: Record<string, string[]>;
  tags?: string[];
  metadata?: Record<string, string>;
}

export interface CueAnchorStoreStatus {
  enabled: boolean;
  anchorsEnabled: boolean;
  rootDir: string;
  anchors: {
    total: number;
    valid: number;
    invalid: number;
    byType: Partial<Record<CueAnchorType, number>>;
    totalNodeRefs: number;
    latestAnchorId?: string;
    latestRecordedAt?: string;
    latestSessionKey?: string;
  };
  latestAnchor?: CueAnchor;
  invalidAnchors: Array<{
    path: string;
    error: string;
  }>;
}

function validateAnchorType(raw: unknown): CueAnchorType {
  const value = assertString(raw, "anchorType");
  if (!["entity", "file", "tool", "outcome", "constraint", "date"].includes(value)) {
    throw new Error("anchorType must be one of entity|file|tool|outcome|constraint|date");
  }
  return value as CueAnchorType;
}

function validateNodeRefs(raw: unknown): string[] {
  const nodeRefs = optionalStringArray(raw, "nodeRefs");
  if (!nodeRefs || nodeRefs.length === 0) {
    throw new Error("nodeRefs must contain at least one node reference");
  }
  return nodeRefs.map((nodeRef, index) => assertSafePathSegment(nodeRef, `nodeRefs[${index}]`));
}

function validateSourceMemoryIdsByNodeRef(raw: unknown): Record<string, string[]> | undefined {
  if (raw === undefined) return undefined;
  if (!isRecord(raw)) throw new Error("sourceMemoryIdsByNodeRef must be an object of string arrays");
  const entries: Array<[string, string[]]> = [];
  for (const [rawNodeRef, rawSourceMemoryIds] of Object.entries(raw)) {
    const nodeRef = assertSafePathSegment(
      assertString(rawNodeRef, "sourceMemoryIdsByNodeRef key"),
      "sourceMemoryIdsByNodeRef.nodeRef"
    );
    const sourceMemoryIds = optionalStringArray(rawSourceMemoryIds, `sourceMemoryIdsByNodeRef.${nodeRef}`);
    if (sourceMemoryIds) entries.push([nodeRef, mergeSortedUniqueStrings(sourceMemoryIds)]);
  }
  if (entries.length === 0) return undefined;
  return Object.fromEntries(entries.sort(([left], [right]) => compareDeterministicStrings(left, right)));
}

function mergeSourceMemoryIdsByNodeRef(
  existing: Record<string, string[]> | undefined,
  incoming: Record<string, string[]> | undefined
): Record<string, string[]> | undefined {
  const merged = new Map<string, string[]>();
  for (const [nodeRef, sourceMemoryIds] of Object.entries(existing ?? {})) {
    merged.set(nodeRef, [...sourceMemoryIds]);
  }
  for (const [nodeRef, sourceMemoryIds] of Object.entries(incoming ?? {})) {
    merged.set(nodeRef, mergeSortedUniqueStrings(merged.get(nodeRef), sourceMemoryIds));
  }
  return validateSourceMemoryIdsByNodeRef(Object.fromEntries(merged));
}

function boundSourceMemoryIdsByNodeRef(
  sourceMemoryIdsByNodeRef: Record<string, string[]> | undefined,
  nodeRefs: string[],
  liveNodes?: Map<string, AbstractionNode>
): Record<string, string[]> | undefined {
  if (!sourceMemoryIdsByNodeRef) return undefined;
  const retained = Object.fromEntries(
    nodeRefs.flatMap((nodeRef) => {
      const sourceMemoryIds = sourceMemoryIdsByNodeRef[nodeRef];
      if (!sourceMemoryIds) return [];
      const liveSourceMemoryIds = liveNodes?.get(nodeRef)?.sourceMemoryIds;
      if (liveNodes && !liveSourceMemoryIds) return [];
      const retainedSourceMemoryIds = mergeSortedUniqueStrings(sourceMemoryIds).filter((sourceMemoryId) =>
        liveSourceMemoryIds ? liveSourceMemoryIds.includes(sourceMemoryId) : true
      );
      return retainedSourceMemoryIds.length > 0 ? [[nodeRef, retainedSourceMemoryIds] as const] : [];
    })
  );
  return validateSourceMemoryIdsByNodeRef(retained);
}

export function resolveCueAnchorStoreDir(abstractionNodeStoreDir: string, overrideDir?: string): string {
  if (typeof overrideDir === "string" && overrideDir.trim().length > 0) {
    return overrideDir.trim();
  }
  return path.join(abstractionNodeStoreDir, "anchors");
}

export function validateCueAnchor(raw: unknown): CueAnchor {
  if (!isRecord(raw)) throw new Error("cue anchor must be an object");
  if (raw.schemaVersion !== 1) throw new Error("schemaVersion must be 1");

  return {
    schemaVersion: 1,
    anchorId: assertSafePathSegment(assertString(raw.anchorId, "anchorId"), "anchorId"),
    anchorType: validateAnchorType(raw.anchorType),
    anchorValue: assertString(raw.anchorValue, "anchorValue"),
    normalizedCue: assertString(raw.normalizedCue, "normalizedCue"),
    recordedAt: assertIsoRecordedAt(assertString(raw.recordedAt, "recordedAt")),
    sessionKey: assertString(raw.sessionKey, "sessionKey"),
    nodeRefs: validateNodeRefs(raw.nodeRefs),
    sourceMemoryIdsByNodeRef: validateSourceMemoryIdsByNodeRef(raw.sourceMemoryIdsByNodeRef),
    tags: optionalStringArray(raw.tags, "tags"),
    metadata: validateStringRecord(raw.metadata, "metadata"),
  };
}

export async function recordCueAnchor(options: {
  memoryDir: string;
  abstractionNodeStoreDir?: string;
  cueAnchorStoreDir?: string;
  anchor: CueAnchor;
}): Promise<string> {
  const abstractionNodeStoreDir = options.abstractionNodeStoreDir?.trim().length
    ? options.abstractionNodeStoreDir.trim()
    : path.join(options.memoryDir, "state", "abstraction-nodes");
  const rootDir = resolveCueAnchorStoreDir(abstractionNodeStoreDir, options.cueAnchorStoreDir);
  const validated = validateCueAnchor(options.anchor);
  const boundedNodeRefs = boundNodeRefs(validated.nodeRefs);
  const bounded = validateCueAnchor({
    ...validated,
    nodeRefs: boundedNodeRefs,
    sourceMemoryIdsByNodeRef: boundSourceMemoryIdsByNodeRef(validated.sourceMemoryIdsByNodeRef, boundedNodeRefs),
  });
  const anchorDir = path.join(rootDir, bounded.anchorType);
  const filePath = path.join(anchorDir, `${bounded.anchorId}.json`);
  await mkdir(anchorDir, { recursive: true });
  await writeFile(filePath, JSON.stringify(bounded, null, 2), "utf8");
  return filePath;
}

function mergeSortedValues(existing: string[] | undefined, incoming: string[] | undefined): string[] {
  return mergeSortedUniqueStrings(existing, incoming);
}

function boundNodeRefs(nodeRefs: string[], liveNodes?: Map<string, AbstractionNode>): string[] {
  const uniqueRefs = mergeSortedUniqueStrings(nodeRefs);
  if (!liveNodes) return uniqueRefs.slice(0, 50);
  return uniqueRefs
    .filter((nodeRef) => liveNodes.has(nodeRef))
    .sort(
      (left, right) =>
        Date.parse(liveNodes.get(right)?.recordedAt ?? "") - Date.parse(liveNodes.get(left)?.recordedAt ?? "") ||
        compareDeterministicStrings(left, right)
    )
    .slice(0, 50);
}

async function readLiveNodes(nodesDir: string): Promise<Map<string, AbstractionNode> | undefined> {
  const liveNodes = new Map<string, AbstractionNode>();
  let nodeFiles: string[];
  try {
    nodeFiles = await listJsonFilesStrict(nodesDir);
  } catch (error) {
    if (isNotFoundError(error)) return undefined;
    throw error;
  }
  for (const filePath of nodeFiles) {
    const node = validateAbstractionNode(await readJsonFile(filePath));
    const previous = liveNodes.get(node.nodeId);
    if (
      !previous ||
      Date.parse(previous.recordedAt) < Date.parse(node.recordedAt) ||
      (Date.parse(previous.recordedAt) === Date.parse(node.recordedAt) &&
        compareDeterministicStrings(previous.sessionKey, node.sessionKey) < 0)
    ) {
      liveNodes.set(node.nodeId, node);
    }
  }
  return liveNodes;
}

export async function upsertCueAnchors(options: {
  memoryDir: string;
  abstractionNodeStoreDir?: string;
  cueAnchorStoreDir?: string;
  anchors: CueAnchor[];
}): Promise<string[]> {
  const abstractionNodeStoreDir = resolveAbstractionNodeStoreDir(options.memoryDir, options.abstractionNodeStoreDir);
  const incomingAnchors = options.anchors.map(validateCueAnchor);
  if (incomingAnchors.length === 0) return [];

  return withJsonStoreMutationLock(abstractionNodeStoreDir, async () => {
    const rootDir = resolveCueAnchorStoreDir(abstractionNodeStoreDir, options.cueAnchorStoreDir);
    const liveNodes = await readLiveNodes(path.join(abstractionNodeStoreDir, "nodes"));
    const incomingByKey = new Map<string, CueAnchor[]>();
    for (const anchor of incomingAnchors) {
      const key = `${anchor.anchorType}\u0000${anchor.anchorId}`;
      const grouped = incomingByKey.get(key) ?? [];
      grouped.push(anchor);
      incomingByKey.set(key, grouped);
    }
    const filePaths: string[] = [];
    for (const key of [...incomingByKey.keys()].sort(compareDeterministicStrings)) {
      const grouped = incomingByKey.get(key) ?? [];
      grouped.sort(compareIncomingCueAnchors);
      const incoming = grouped.shift();
      if (!incoming) throw new Error(`cue anchor batch has no anchor: ${key}`);
      const filePath = path.join(rootDir, incoming.anchorType, `${incoming.anchorId}.json`);
      let existing: CueAnchor | undefined;
      try {
        existing = validateCueAnchor(await readJsonFile(filePath));
      } catch (error) {
        if (!isNotFoundError(error)) throw error;
      }
      let merged = mergeCueAnchors(existing, incoming, liveNodes);
      for (const next of grouped) merged = mergeCueAnchors(merged, next, liveNodes);
      await writeJsonFileAtomic(filePath, merged);
      filePaths.push(filePath);
    }
    return filePaths;
  });
}

function compareIncomingCueAnchors(left: CueAnchor, right: CueAnchor): number {
  const recordedAtComparison = Date.parse(left.recordedAt) - Date.parse(right.recordedAt);
  if (recordedAtComparison < 0) return -1;
  if (recordedAtComparison > 0) return 1;
  return compareDeterministicStrings(canonicalCueAnchorKey(left), canonicalCueAnchorKey(right));
}

function canonicalMetadata(metadata: Record<string, string> | undefined): Record<string, string> {
  return Object.fromEntries(
    Object.entries(metadata ?? {}).sort(([left], [right]) => compareDeterministicStrings(left, right))
  );
}

function canonicalCueAnchorKey(anchor: CueAnchor): string {
  return JSON.stringify({
    ...anchor,
    metadata: canonicalMetadata(anchor.metadata),
  });
}

function mergeCueAnchors(
  existing: CueAnchor | undefined,
  incoming: CueAnchor,
  liveNodes: Map<string, AbstractionNode> | undefined
): CueAnchor {
  const incomingIsNewest = !existing || Date.parse(existing.recordedAt) <= Date.parse(incoming.recordedAt);
  const newest = incomingIsNewest ? incoming : existing;
  const older = incomingIsNewest ? existing : incoming;
  const mergedMetadata = canonicalMetadata({
    ...(older?.metadata ?? {}),
    ...(newest.metadata ?? {}),
  });
  const nodeRefs = boundNodeRefs(mergeSortedValues(existing?.nodeRefs, incoming.nodeRefs), liveNodes);
  return validateCueAnchor({
    ...newest,
    nodeRefs,
    sourceMemoryIdsByNodeRef: boundSourceMemoryIdsByNodeRef(
      mergeSourceMemoryIdsByNodeRef(existing?.sourceMemoryIdsByNodeRef, incoming.sourceMemoryIdsByNodeRef),
      nodeRefs,
      liveNodes
    ),
    tags: mergeSortedValues(existing?.tags, incoming.tags),
    metadata: mergedMetadata,
  });
}

export async function upsertCueAnchor(options: {
  memoryDir: string;
  abstractionNodeStoreDir?: string;
  cueAnchorStoreDir?: string;
  anchor: CueAnchor;
}): Promise<string> {
  const [filePath] = await upsertCueAnchors({ ...options, anchors: [options.anchor] });
  if (!filePath) throw new Error("cue anchor upsert did not write a file");
  return filePath;
}

export async function pruneOrphanCueAnchors(options: {
  memoryDir: string;
  abstractionNodeStoreDir?: string;
  cueAnchorStoreDir?: string;
}): Promise<number> {
  const abstractionNodeStoreDir = resolveAbstractionNodeStoreDir(options.memoryDir, options.abstractionNodeStoreDir);
  return withJsonStoreMutationLock(abstractionNodeStoreDir, async () => {
    const cueAnchorStoreDir = resolveCueAnchorStoreDir(abstractionNodeStoreDir, options.cueAnchorStoreDir);
    const liveNodes = (await readLiveNodes(path.join(abstractionNodeStoreDir, "nodes"))) ?? new Map();
    let removed = 0;
    const anchorFiles = await listJsonFilesStrict(cueAnchorStoreDir, {
      allowMissingDirectory: true,
    });
    for (const filePath of anchorFiles) {
      let anchor: CueAnchor;
      try {
        anchor = validateCueAnchor(await readJsonFile(filePath));
      } catch {
        continue;
      }
      const nodeRefs = boundNodeRefs(anchor.nodeRefs, liveNodes);
      const sourceMemoryIdsByNodeRef = boundSourceMemoryIdsByNodeRef(
        anchor.sourceMemoryIdsByNodeRef,
        nodeRefs,
        liveNodes
      );
      if (nodeRefs.length === 0) {
        try {
          await unlink(filePath);
          removed++;
        } catch (error) {
          if (!isNotFoundError(error)) throw error;
        }
        continue;
      }
      if (
        nodeRefs.length !== anchor.nodeRefs.length ||
        nodeRefs.some((nodeRef, index) => nodeRef !== anchor.nodeRefs[index]) ||
        JSON.stringify(sourceMemoryIdsByNodeRef) !== JSON.stringify(anchor.sourceMemoryIdsByNodeRef)
      ) {
        await writeJsonFileAtomic(filePath, validateCueAnchor({ ...anchor, nodeRefs, sourceMemoryIdsByNodeRef }));
      }
    }
    return removed;
  });
}

export async function getCueAnchorStoreStatus(options: {
  memoryDir: string;
  abstractionNodeStoreDir?: string;
  cueAnchorStoreDir?: string;
  enabled: boolean;
  anchorsEnabled: boolean;
}): Promise<CueAnchorStoreStatus> {
  const abstractionNodeStoreDir = options.abstractionNodeStoreDir?.trim().length
    ? options.abstractionNodeStoreDir.trim()
    : path.join(options.memoryDir, "state", "abstraction-nodes");
  const rootDir = resolveCueAnchorStoreDir(abstractionNodeStoreDir, options.cueAnchorStoreDir);
  const files = await listJsonFilesStrict(rootDir, { allowMissingDirectory: true });
  const anchors: CueAnchor[] = [];
  const invalidAnchors: Array<{ path: string; error: string }> = [];

  for (const filePath of files) {
    try {
      anchors.push(validateCueAnchor(await readJsonFile(filePath)));
    } catch (error) {
      invalidAnchors.push({
        path: filePath,
        error: error instanceof Error ? error.message : String(error),
      });
    }
  }

  anchors.sort(
    (a, b) => Date.parse(b.recordedAt) - Date.parse(a.recordedAt) || compareDeterministicStrings(a.anchorId, b.anchorId)
  );

  const byType: Partial<Record<CueAnchorType, number>> = {};
  let totalNodeRefs = 0;
  for (const anchor of anchors) {
    byType[anchor.anchorType] = (byType[anchor.anchorType] ?? 0) + 1;
    totalNodeRefs += anchor.nodeRefs.length;
  }

  return {
    enabled: options.enabled,
    anchorsEnabled: options.anchorsEnabled,
    rootDir,
    anchors: {
      total: files.length,
      valid: anchors.length,
      invalid: invalidAnchors.length,
      byType,
      totalNodeRefs,
      latestAnchorId: anchors[0]?.anchorId,
      latestRecordedAt: anchors[0]?.recordedAt,
      latestSessionKey: anchors[0]?.sessionKey,
    },
    latestAnchor: anchors[0],
    invalidAnchors,
  };
}

/**
 * Promotion destination writes under the fact-dedup commit window (codex P2,
 * PRRT_kwDORJXyws6zzdG4 / #3311). The persist-time promotion gates run
 * OUTSIDE the window that serializes source writes, so with
 * extractionQueueConcurrency > 1 two sessions promoting the same fact from
 * different source namespaces can both gate-miss and both write the shared
 * destination — duplicate active copies, because writeMemory mints a fresh id
 * per write and does not coalesce active duplicates. This module wraps each
 * promotion destination write in `persistUnderFactDedupWindow` keyed on the
 * DESTINATION storage dir and rechecks with the same connector/content
 * predicate the promotion gates confirm with, so a twin promotion committed
 * between the gate and the write is suppressed instead of duplicated.
 *
 * Split out of extraction-persist.ts for the structural ratchet (#1995);
 * behavior is a verbatim move of the wrapped writes the persist closure
 * previously inlined.
 */

import { ContentHashIndex, type StorageManager } from "../index.js";
import { log } from "../logger.js";
import type { ImportanceScore, MemoryFile, MemoryFrontmatter, ProvenanceSource } from "../types.js";
import type { SealedMemoryEnvelope } from "../write-envelope.js";
import type { SealedWriteExtras } from "../storage.js";
import { normalizeStoredHashSource } from "./extraction-persist-citation.js";
import { readActiveMemoriesBothTiers } from "./extraction-persist-promotion.js";
import { applyTemporalSupersession, normalizeSupersessionKey } from "../temporal-supersession.js";
import type { DependencyPropagationDeliveryPort } from "./dependency-propagation-delivery.js";
import { persistUnderFactDedupWindow, type FactDedupWindowOutcome } from "./fact-dedup-window.js";

/**
 * The promotion fields the windowed write and its suppression-path bounds
 * backfill read. Structurally satisfied by both promotion closures' options
 * objects in extraction-persist.ts (profile-target and shared).
 */
export interface PromotionDedupWriteFields {
  category: string;
  sourceMemoryId: string;
  importance?: ImportanceScore;
  intentGoal?: string;
  intentActionType?: string;
  intentEntityTypes?: string[];
  memoryKind?: MemoryFrontmatter["memoryKind"];
  validAt?: string;
  invalidAt?: string;
  observedAt?: string;
  eventTimeSource?: "extracted" | "assumed";
  sources?: ProvenanceSource[];
  provenance?: "verified" | "unverified" | "none";
  toolScoped?: true;
}

export interface PromotionDedupWriteArgs {
  /** Promotion DESTINATION storage — the commit window is keyed on its dir. */
  destination: StorageManager;
  /** Composed sealed envelope for the promoted copy. */
  envelope: SealedMemoryEnvelope;
  /** The promotion closure's options (read structurally). */
  promotion: PromotionDedupWriteFields;
  /** Fact hash-key content (attrs-suffixed); pre-citation raw for others. */
  dedupContent: string;
  rawContent: string;
  /** promotionWithholdsToolScope() result (shared) / forwarded marker (profile). */
  toolScoped: boolean;
  /** Raw source connector: trimmed for the recheck, raw for bounds backfill. */
  connector: string | undefined;
  citationEnabled: boolean;
  citationTemplate: string;
  /** lifecycleCaps.temporalSupersession on the shared path; false on the
   *  profile path (its gate predicate has no entity filter). When true AND the
   *  envelope carries an entityRef with non-empty surviving attrs, the recheck
   *  additionally requires the same entity (PR #402 Uybg guard parity). */
  sameEntityGuardEnabled: boolean;
  /** Envelope-surviving structured attributes (PR #402 Uybg guard input). */
  survivingAttrs?: Record<string, string> | null;
  /** When set, the suppression path runs the post-write supersession pass
   *  against the winning copy (PRRT_kwDORJXyws6z18qb): a suppressed
   *  later-dated promotion must still retire a conflicting shared fact dated
   *  between the events, mirroring the gate's hash-dedup-hit pass. */
  supersession?: {
    /** Caller's lifecycleCaps.temporalSupersession — without it the pass
     *  must not run even though the event-time `enabled` gate passes
     *  (PRRT_kwDORJXyws6z2o1t). */
    supersessionEnabled: boolean;
    dependencyPropagationDelivery?: DependencyPropagationDeliveryPort;
    namespaceScope?: string;
  };
  backfillTemporalBoundsOnDedupHit: ExtractionPersistDeps["backfillTemporalBoundsOnDedupHit"];
}

type ExtractionPersistDeps = {
  backfillTemporalBoundsOnDedupHit: (
    targetStorage: StorageManager,
    dedupContent: string,
    bounds: {
      invalidAt?: string;
      validFrom?: string;
      observedAt?: string;
      eventTimeSource?: "extracted" | "assumed";
    },
    entityRef?: string,
    sourceConnector?: string,
  ) => Promise<void>;
};

/**
 * Locate the active same-destination fact a raced promotion would duplicate:
 * same connector/content predicate the promotion gates confirm with
 * (`readActiveMemoriesBothTiers` + citation-aware stored normalization vs the
 * normalized dedup key). The optional entity key mirrors the shared
 * supersession branch's same-entity guard (PR #402 Uybg) so cross-entity
 * same-content facts stay distinct. Returns undefined on scan error — an
 * unverifiable state never suppresses (fail-open).
 */
async function findPromotionRaceDuplicate(args: {
  storage: StorageManager;
  dedupContent: string;
  category: string;
  connector: string | undefined;
  citationEnabled: boolean;
  citationTemplate: string;
  entityKeyNorm?: string;
}): Promise<MemoryFile | undefined> {
  try {
    const allMems = await readActiveMemoriesBothTiers(args.storage);
    const nc = args.connector?.trim() || undefined;
    const incomingNormalized = ContentHashIndex.normalizeContent(args.dedupContent);
    return allMems.find((m: MemoryFile) => {
      if (m.frontmatter.category !== args.category) return false;
      if ((m.frontmatter.status ?? "active") !== "active") return false;
      if (
        normalizeStoredHashSource(m.content ?? "", args.citationEnabled, args.citationTemplate) !==
        incomingNormalized
      )
        return false;
      if (args.entityKeyNorm !== undefined) {
        if (!m.frontmatter.entityRef) return false;
        if (normalizeSupersessionKey(m.frontmatter.entityRef) !== args.entityKeyNorm) return false;
      }
      return (m.frontmatter.sourceConnector?.trim() || undefined) === nc;
    });
  } catch (err) {
    log.warn(
      `promotion race recheck scan failed for ${args.storage.dir}; writing fail-open: ${err instanceof Error ? err.message : String(err)}`,
    );
    return undefined;
  }
}

/**
 * In-window race confirm for a promotion destination. Authoritative index +
 * miss is a clean NOT-duplicate answered WITHOUT the corpus scan, mirroring
 * `confirmActiveFactDuplicate` and the window contract (one corpus confirm +
 * one write, not a scan-length lock) — PRRT_kwDORJXyws6z18qS. On a hit, a
 * non-authoritative index, or a probe failure, confirm against the corpus
 * with the gates' predicate.
 */
export async function confirmPromotionRaceDuplicate(args: {
  storage: StorageManager;
  dedupContent: string;
  category: string;
  connector: string | undefined;
  citationEnabled: boolean;
  citationTemplate: string;
  entityKeyNorm?: string;
}): Promise<boolean> {
  try {
    if (await args.storage.isFactContentHashAuthoritative()) {
      if (!(await args.storage.hasFactContentHash(args.dedupContent))) return false;
    }
  } catch (probeErr) {
    log.warn(
      `promotion race recheck authoritative probe failed for ${args.storage.dir}; confirming against corpus: ${probeErr instanceof Error ? probeErr.message : String(probeErr)}`,
    );
  }
  return (await findPromotionRaceDuplicate(args)) !== undefined;
}

/**
 * Presence-iff-set extras, byte-equivalent to the conditional spreads the
 * persist closure previously inlined at both promotion call sites.
 */
function buildPromotionWriteOptions(args: PromotionDedupWriteArgs): SealedWriteExtras {
  const { promotion } = args;
  const writeOptions: SealedWriteExtras = {
    importance: promotion.importance,
    lineage: [promotion.sourceMemoryId],
    sourceMemoryId: promotion.sourceMemoryId,
    intentGoal: promotion.intentGoal,
    intentActionType: promotion.intentActionType,
    intentEntityTypes: promotion.intentEntityTypes,
    memoryKind: promotion.memoryKind,
    contentHashSource: promotion.category === "fact" ? args.dedupContent : args.rawContent,
  };
  if (promotion.invalidAt) writeOptions.invalidAt = promotion.invalidAt;
  // #1578 — forward bi-temporal bounds + ingestion provenance.
  if (promotion.observedAt) writeOptions.observedAt = promotion.observedAt;
  if (promotion.eventTimeSource) writeOptions.eventTimeSource = promotion.eventTimeSource;
  if (promotion.sources && promotion.sources.length > 0) writeOptions.sources = promotion.sources;
  if (promotion.provenance) writeOptions.provenance = promotion.provenance;
  if (args.toolScoped) writeOptions.toolScoped = true;
  return writeOptions;
}

/**
 * Run one promotion destination write inside the destination-dir fact-dedup
 * commit window: recheck (facts only; the same confirm the persist-time gate
 * used, now under the lock) and suppress as a duplicate when a concurrent
 * promotion committed the same content first. A suppressed promotion backfills
 * temporal bounds onto the winning copy (#1671 parity with the gates' skip
 * paths) and reports `{ suppressed: true }`. Lock contention throws
 * fail-closed to the caller — never an unlocked write; the durable source
 * fact is unaffected.
 */
export async function writePromotionUnderFactDedupWindow(
  args: PromotionDedupWriteArgs,
): Promise<FactDedupWindowOutcome<Awaited<ReturnType<StorageManager["writeSealedMemory"]>>>> {
  const { destination, envelope, promotion } = args;
  // PRRT_kwDORJXyws6z2WsK: the recheck is fact-only, so for other categories
  // the window would add lock acquisition and fail-closed throw risk with no
  // dedup value. Write directly with the same extras.
  if (promotion.category !== "fact") {
    return {
      suppressed: false,
      result: await destination.writeSealedMemory(envelope, buildPromotionWriteOptions(args)),
    };
  }
  const entityKeyNorm =
    args.sameEntityGuardEnabled &&
    envelope.entityRef &&
    args.survivingAttrs &&
    Object.keys(args.survivingAttrs).length > 0
      ? normalizeSupersessionKey(envelope.entityRef)
      : undefined;
  const outcome = await persistUnderFactDedupWindow(
    destination.dir,
    () =>
      promotion.category === "fact"
        ? confirmPromotionRaceDuplicate({
            storage: destination,
            dedupContent: args.dedupContent,
            category: promotion.category,
            connector: args.connector,
            citationEnabled: args.citationEnabled,
            citationTemplate: args.citationTemplate,
            entityKeyNorm,
          })
        : Promise.resolve(false),
    () => destination.writeSealedMemory(envelope, buildPromotionWriteOptions(args)),
  );
  if (outcome.suppressed) {
    log.info(`dedup: raced promotion duplicate suppressed in fact-dedup window for ${destination.dir}`);
    if (promotion.invalidAt || promotion.validAt) {
      await args.backfillTemporalBoundsOnDedupHit(
        destination,
        args.dedupContent,
        {
          invalidAt: promotion.invalidAt,
          // #1707 thread 2 — carry the corrected start bound.
          validFrom: promotion.validAt,
          observedAt: promotion.observedAt,
          eventTimeSource: promotion.eventTimeSource,
        },
        envelope.entityRef,
        args.connector,
      );
    }
    // PRRT_kwDORJXyws6z18qb: the unsuppressed path runs temporal supersession
    // after the write; the suppressed promotion must too, or a later-dated
    // raced promotion leaves a conflicting shared fact dated between the
    // events active. Anchor to the winning copy with useCallerTimestamp —
    // the gate's hash-dedup-hit shape (PR #402 Uyui/UvU1) — and fail open.
    if (
      args.supersession?.supersessionEnabled &&
      promotion.category === "fact" &&
      envelope.entityRef &&
      args.survivingAttrs &&
      Object.keys(args.survivingAttrs).length > 0
    ) {
      try {
        const winning = await findPromotionRaceDuplicate({
          storage: destination,
          dedupContent: args.dedupContent,
          category: promotion.category,
          connector: args.connector,
          citationEnabled: args.citationEnabled,
          citationTemplate: args.citationTemplate,
          // PRRT_kwDORJXyws6z2o11: the winner ANCHORS the pass, so the lookup
          // is always entity-guarded — without it (profile path) it could
          // match another entity's equal-content fact and combine that fact's
          // id with the incoming entity's attributes (PR #402 Uybg hazard).
          entityKeyNorm: normalizeSupersessionKey(envelope.entityRef),
        });
        if (winning) {
          await applyTemporalSupersession({
            storage: destination,
            newMemoryId: winning.frontmatter.id,
            entityRef: envelope.entityRef,
            structuredAttributes: { ...args.survivingAttrs },
            // Ordering anchor mirrors the gate's supersessionOrderingAt: an
            // incoming event date orders the pass, wall clock otherwise.
            createdAt:
              promotion.validAt && promotion.validAt.length > 0
                ? promotion.validAt
                : new Date().toISOString(),
            useCallerTimestamp: true,
            enabled: !(promotion.eventTimeSource === "extracted" && !promotion.validAt),
            namespaceScope: args.supersession.namespaceScope,
            dependencyPropagationDelivery: args.supersession.dependencyPropagationDelivery,
          });
        }
      } catch (supersessionErr) {
        log.warn(
          `promotion window supersession failed open for ${destination.dir}: ${supersessionErr instanceof Error ? supersessionErr.message : String(supersessionErr)}`,
        );
      }
    }
  }
  return outcome;
}

import { parseOriginClass } from "../security/origin-authority.js";
import { normalizeAttributePairs } from "../structured-attributes.js";
import { buildProcedurePersistBody } from "../procedural/procedure-types.js";
import { screenCandidateFact } from "../security/injection-screen.js";
import type { InjectionScreenProfile } from "../security/injection-screen.js";
import type { EntityStructuredSection } from "../types.js";

export interface InjectionScreenCandidate {
  content: string;
  category?: string;
  structuredAttributes?: Record<string, unknown>;
  procedureSteps?: unknown;
}

export interface InjectionScreenGateResult {
  status?: "pending_review";
  tags: string[];
}

/** Serialize the body fields that the persistence path will store. */
export function serializeInjectionScreenCandidate(candidate: InjectionScreenCandidate): string {
  const body =
    candidate.category === "procedure"
      ? buildProcedurePersistBody(candidate.content, candidate.procedureSteps)
      : candidate.content;
  // Salvage malformed extractor output: non-string attribute values (e.g.
  // `{ priority: 1 }`) must not throw and abort the whole extraction batch
  // (#1955 review). Coerce primitives; drop anything else.
  const attrs = Object.fromEntries(
    Object.entries(candidate.structuredAttributes ?? {}).flatMap(([key, value]): Array<[string, string]> => {
      if (typeof value === "string") return [[key, value]];
      if (typeof value === "number" || typeof value === "boolean") return [[key, String(value)]];
      return [];
    }),
  );
  return Object.keys(attrs).length > 0
    ? `${body}\n[Attributes: ${normalizeAttributePairs(attrs)}]`
    : body;
}

/** Screen one candidate and assemble the persistence effects. */
export function evaluateInjectionScreen(
  candidate: InjectionScreenCandidate | string,
  enabled: boolean,
  profile: InjectionScreenProfile = "default",
): InjectionScreenGateResult {
  if (!enabled) return { tags: [] };
  const content =
    typeof candidate === "string" ? candidate : serializeInjectionScreenCandidate(candidate);
  const result = screenCandidateFact(content, profile);
  return {
    status: result.quarantine === true ? "pending_review" : undefined,
    tags: result.quarantine === true
      ? result.findings.map((finding) => `injection-screen:${finding.rule}`)
      : [],
  };
}

/**
 * Withhold injection-flagged strings from an entity-index write (#1955
 * review): entity facts/sections have no review status, so a flagged field is
 * excluded from the recallable index and surfaced via the returned rules for
 * the caller to log. Screen off → strings pass through unfiltered.
 */
export function withholdScreenedStrings(
  values: readonly unknown[],
  enabled: boolean,
  profile: InjectionScreenProfile = "default",
): { kept: string[]; withheldRules: string[] } {
  const kept: string[] = [];
  const withheldRules: string[] = [];
  for (const value of values) {
    if (typeof value !== "string") continue;
    if (!enabled) {
      kept.push(value);
      continue;
    }
    const screened = screenCandidateFact(value, profile);
    if (screened.quarantine) {
      withheldRules.push(...screened.findings.map((finding) => `injection-screen:${finding.rule}`));
    } else {
      kept.push(value);
    }
  }
  return { kept, withheldRules };
}

export interface ScreenedEntityWrite {
  name: string;
  type: string;
  source: string;
  facts: string[];
  structuredSections?: EntityStructuredSection[];
  withheldRules: string[];
  /** True when the entity NAME itself was flagged — callers must not index it. */
  withheld: boolean;
}

/**
 * Validate and screen one extracted entity before it enters the entity index
 * (#1955 review): flagged facts/section facts are withheld and reported via
 * `withheldRules` (entities carry no review status; routing is #2397).
 * Returns null for entities without a usable name/type.
 */
export function screenEntityForIndex(entity: unknown, enabled: boolean, profile: InjectionScreenProfile = "default"): ScreenedEntityWrite | null {
  const record = entity as { name?: unknown; type?: unknown; source?: unknown; facts?: unknown; structuredSections?: unknown } | null;
  const name = record?.name;
  const type = record?.type;
  if (typeof name !== "string" || !name.trim() || typeof type !== "string" || !type.trim()) return null;
  // #1955 review: the raw name is emitted as the entity target outside the
  // snippet fence — a flagged name withholds the whole entity from the index.
  const nameScreen = withholdScreenedStrings([name], enabled, profile);
  const factScreen = withholdScreenedStrings(Array.isArray(record?.facts) ? record.facts : [], enabled, profile);
  const rawSections: EntityStructuredSection[] | undefined = Array.isArray(record?.structuredSections)
    ? (record.structuredSections as EntityStructuredSection[])
    : undefined;
  const sectionScreens = enabled && rawSections
    ? rawSections.map((section) => ({ section, screen: withholdScreenedStrings(section?.facts ?? [], true, profile) }))
    : undefined;
  return {
    name,
    type,
    source: typeof record?.source === "string" ? record.source : "extraction",
    facts: factScreen.kept,
    ...(sectionScreens
      ? {
        structuredSections: sectionScreens.map(({ section, screen }) => {
          let nextFactIndex = 0;
          const factOrigins = screen.kept.map((fact) => {
            const factIndex = section.facts.indexOf(fact, nextFactIndex);
            nextFactIndex = factIndex + 1;
            const origin = section.factOrigins?.[factIndex];
            return origin === undefined ? undefined : parseOriginClass(origin);
          });
          return {
            ...section,
            facts: screen.kept,
            ...(factOrigins.some((origin) => origin !== undefined) ? { factOrigins } : {}),
          };
        }),
      }
      : rawSections
        ? { structuredSections: rawSections }
        : {}),
    withheldRules: [
      ...nameScreen.withheldRules,
      ...factScreen.withheldRules,
      ...(sectionScreens ?? []).flatMap(({ screen }) => screen.withheldRules),
    ],
    withheld: nameScreen.withheldRules.length > 0,
  };
}

/**
 * Screen a batch of persist-bound strings and preformat the withheld warning
 * (#1955): keeps persist call sites within their file-size ratchet.
 */
export function screenPersistStrings(
  values: readonly string[],
  enabled: boolean,
  profile: InjectionScreenProfile = "default",
): { kept: string[]; warning?: string } {
  const screen = withholdScreenedStrings(values, enabled, profile);
  return {
    kept: screen.kept,
    ...(screen.withheldRules.length > 0
      ? { warning: `injection screen withheld ${values.length - screen.kept.length} candidate(s) [${screen.withheldRules.join(", ")}]` }
      : {}),
  };
}

import {
  composeMemoryEnvelope,
  TAG_LIMITS,
  type MemoryWriteInput,
  type SealedMemoryEnvelope,
  type WriteContext,
} from "../write-envelope.js";
import { normalizeTags } from "../recall-tag-filter.js";
import { log } from "../logger.js";

/**
 * Envelope helpers for the extraction persistence pipeline (issue #1989 PR2).
 *
 * Extraction input is MACHINE-GENERATED: one malformed LLM field must never
 * abort a whole persistence batch that legacy `writeMemory` would have
 * accepted. Every extraction-side compose therefore runs in salvage mode,
 * and every drop is warn-logged (rule 34 — visible, never silent).
 */

/**
 * Compose an extraction-side envelope in salvage mode and warn-log any
 * salvage notes. The single compose wrapper for all extraction-persist
 * write sites, so note logging cannot be forgotten at a new site.
 */
export function composeSalvagedExtractionEnvelope(
  input: MemoryWriteInput,
  ctx: WriteContext,
): SealedMemoryEnvelope {
  const envelope = composeMemoryEnvelope(input, ctx, { salvage: true });
  if (envelope.salvageNotes.length > 0) {
    log.warn(`extraction write salvaged invalid fields: ${envelope.salvageNotes.join("; ")}`);
  }
  return envelope;
}

/**
 * System marker tags ("shared-promotion", "<target>-promotion", "chunked")
 * must survive the tag cap — the CLI and stats identify chunked parents and
 * promotions through them (#2014/#2017 review round). Normalize the source
 * tags first (same trim/dedupe salvage would apply), reserve one slot for
 * the marker, and warn when source tags are dropped to make room.
 */
export function withReservedMarkerTag(sourceTags: string[], marker: string): string[] {
  // Drop overlong tags BEFORE budgeting (round 3): normalizeTags only
  // trims/dedupes, so a >256-char tag would consume a budget slot here and
  // then be salvage-dropped at compose time — squeezing out a valid later
  // tag for nothing.
  const usable = sourceTags.filter(
    (tag) => typeof tag !== "string" || tag.trim().length <= TAG_LIMITS.maxTagLength,
  );
  const normalized = normalizeTags(usable) ?? [];
  const budget = TAG_LIMITS.maxTags - 1;
  if (normalized.length > budget) {
    log.warn(
      `extraction tags exceed ${budget}+marker cap; keeping the first ${budget} of ${normalized.length} and the ${JSON.stringify(marker)} marker`,
    );
  }
  const capped = normalized.length > budget ? normalized.slice(0, budget) : normalized;
  return [...capped, marker];
}

/**
 * Pure salvage-compose probe: reproduce the SURVIVING entityRef and raw
 * attribute pairs a salvage write of these fields would persist
 * (deterministic, side-effect-free). Returns null when strict envelope
 * preconditions reject (such input never reached a salvage write either) —
 * callers fail open to their raw fields.
 */
export function probeSalvageSurvivingFields(input: {
  content: string;
  category: MemoryWriteInput["category"];
  structuredAttributes?: Record<string, string>;
  entityRef?: string;
}): { entityRef?: string; structuredAttributes?: Record<string, string> } | null {
  try {
    const probe = composeSalvagedExtractionEnvelope(
      {
        content: input.content,
        category: input.category,
        structuredAttributes: input.structuredAttributes,
        entityRef: input.entityRef,
      },
      { source: "bitemporal-backfill-probe" },
    );
    return {
      entityRef: probe.entityRef,
      structuredAttributes: probe.rawStructuredAttributes
        ? { ...probe.rawStructuredAttributes }
        : undefined,
    };
  } catch {
    return null;
  }
}

