}

export interface Chunk {
  /** Chunk content */
  content: string;
  /** 0-based index */
  index: number;
  /** Approximate token count */
  tokenCount: number;
}

export interface ChunkResult {
  /** Whether content was chunked */
  chunked: boolean;
  /** Array of chunks (length 1 if not chunked) */
  chunks: Chunk[];
}

/** Default chunking configuration */
export const DEFAULT_CHUNKING_CONFIG: ChunkingConfig = {
  targetTokens: 200,
  minTokens: 150,
  overlapSentences: 2,
};

/**
 * Split text into sentences.
 *
 * The scan stays linear and does not use a backtracking regular expression.
 * ASCII punctuation keeps its old whitespace rule. Unicode terminators also
 * split when the next sentence starts immediately, as in CJK text.
 */
const UNICODE_SENTENCE_TERMINATORS = "。．！？؟۔।॥｡…";
const ASCII_SENTENCE_TERMINATORS = ".!?";
const CJK_NO_SPACE_TERMINATORS = "。．！？｡";
const CLOSING_PUNCTUATION = "\"'”’»」』）］】〉》)]}";
const DIGITS = "0123456789０１２３４５６７８９";
const SENTENCE_SEGMENTER =
  typeof Intl.Segmenter === "function"
    ? new Intl.Segmenter(undefined, { granularity: "sentence" })
    : undefined;

function isSentenceTerminator(character: string): boolean {
  return (
    ASCII_SENTENCE_TERMINATORS.includes(character) ||
    UNICODE_SENTENCE_TERMINATORS.includes(character)
  );
}

function isCjk(character: string): boolean {
  return /[\u3000-\u9fff\uf900-\ufaff\uac00-\ud7af]/u.test(character);
}

type SentenceList = string[] & { separators: string[] };

function splitSentencesFallback(text: string): SentenceList {
  const sentences = [] as unknown as SentenceList;
  Object.defineProperty(sentences, "separators", {
    value: [],
    writable: true,
  });
  let start = 0;
  let separator = "";
  for (let i = 0; i < text.length; i++) {
    const ch = text[i];
    if (!isSentenceTerminator(ch)) continue;

    let end = i;
    let hasUnicodeTerminator = UNICODE_SENTENCE_TERMINATORS.includes(ch);
    while (end + 1 < text.length && isSentenceTerminator(text[end + 1])) {
      end++;
      hasUnicodeTerminator ||= UNICODE_SENTENCE_TERMINATORS.includes(text[end]);
    }

    const isFullwidthDecimal =
      ch === "．" &&
      DIGITS.includes(text[i - 1] ?? "") &&
      DIGITS.includes(text[end + 1] ?? "");
    while (end + 1 < text.length && CLOSING_PUNCTUATION.includes(text[end + 1])) {
      end++;
    }

    const after = text[end + 1];
    const boundary =
      !isFullwidthDecimal &&
      (hasUnicodeTerminator || after === undefined || /\s/u.test(after));
    if (boundary) {
      const sentence = text.slice(start, end + 1).trim();
      if (sentence.length > 0) {
        sentences.push(sentence);
        if (sentences.length > 1) sentences.separators.push(separator);
      }
      let nextStart = end + 1;
      while (nextStart < text.length && /\s/u.test(text[nextStart])) nextStart++;
      separator = text.slice(end + 1, nextStart);
      start = nextStart;
    }
    i = end;
  }

  const remaining = text.slice(start).trim();
  if (remaining.length > 0) {
    sentences.push(remaining);
    if (sentences.length > 1) sentences.separators.push(separator);
  }
  return sentences;
}
export function splitSentences(text: string): string[] {
  const canUseSegmenter =
    SENTENCE_SEGMENTER !== undefined &&
    !/\s/u.test(text) &&
    [...text].some((character) => UNICODE_SENTENCE_TERMINATORS.includes(character));
  if (canUseSegmenter) {
    const segments = Array.from(SENTENCE_SEGMENTER.segment(text), ({ segment }) =>
      segment.trim(),
    ).filter((segment) => segment.length > 0) as SentenceList;
    if (
      segments.length > 1 &&
      segments.slice(0, -1).every((segment) =>
        [...segment].some((character) =>
          UNICODE_SENTENCE_TERMINATORS.includes(character),
        ),
      )
    ) {
      Object.defineProperty(segments, "separators", {
        value: Array(segments.length - 1).fill(""),
        writable: true,
      });
      return segments;
    }
  }
  return splitSentencesFallback(text);
}

function endsWithoutSpace(text: string): boolean {
  let index = text.length - 1;
  while (index >= 0 && CLOSING_PUNCTUATION.includes(text[index])) index--;
  const terminator = text[index] ?? "";
  if (CJK_NO_SPACE_TERMINATORS.includes(terminator)) {
    return isCjk(text[index - 1] ?? "");
  }
  return terminator === "…" && isCjk(text[index - 1] ?? "");
}
export function joinSentences(sentences: string[]): string {
  let result = "";
  const separators = (sentences as Partial<SentenceList>).separators;
  for (let i = 0; i < sentences.length; i++) {
    const sentence = sentences[i];
    if (result.length > 0) {
      const separator = separators?.[i - 1];
      result += separator ?? (endsWithoutSpace(result) ? "" : " ");
    }
    result += sentence;
  }
  return result;
}


/**
 * Chunk content into overlapping segments at sentence boundaries.
 *
 * @param content - The text content to chunk
 * @param config - Chunking configuration
 * @returns ChunkResult with chunks array
 */
export function chunkContent(
  content: string,
  config: ChunkingConfig = DEFAULT_CHUNKING_CONFIG,
): ChunkResult {
  const totalTokens = estimateTokenCount(content);

  // Don't chunk if below minimum threshold
  if (totalTokens < config.minTokens) {
    return {
      chunked: false,
      chunks: [{
        content,
        index: 0,
        tokenCount: totalTokens,
      }],
    };
  }

  const sentences = splitSentences(content);

  // If we couldn't split into multiple sentences, don't chunk
  if (sentences.length <= 1) {
    return {
      chunked: false,
      chunks: [{
        content,
        index: 0,
        tokenCount: totalTokens,
      }],
    };
  }

  const chunks: Chunk[] = [];
  let currentChunkSentences: string[] = [];
  let currentTokens = 0;
  let chunkIndex = 0;

  for (let i = 0; i < sentences.length; i++) {
    const sentence = sentences[i];
    const sentenceTokens = estimateTokenCount(sentence);

    // Add sentence to current chunk
    currentChunkSentences.push(sentence);
    currentTokens += sentenceTokens;

    // Check if we've reached target size (with some flexibility)
    // Allow going over by up to 50% to avoid tiny final chunks
    const atTarget = currentTokens >= config.targetTokens;
    const isLastSentence = i === sentences.length - 1;

    if (atTarget || isLastSentence) {
      // Create chunk from accumulated sentences
      const chunkContent = joinSentences(currentChunkSentences);
      chunks.push({
        content: chunkContent,
        index: chunkIndex,
        tokenCount: estimateTokenCount(chunkContent),
      });
      chunkIndex++;

      // Start new chunk with overlap (if not at end)
      if (!isLastSentence) {
        // Keep last N sentences for overlap.
        // Guard: slice(-0) === slice(0), which returns the ENTIRE array
        // (CLAUDE.md gotcha #27). When overlapSentences is 0, clear fully.
        const overlapCount = Math.min(config.overlapSentences, currentChunkSentences.length);
        if (overlapCount <= 0) {
          currentChunkSentences = [];
          currentTokens = 0;
        } else {
          currentChunkSentences = currentChunkSentences.slice(-overlapCount);
          currentTokens = currentChunkSentences.reduce((sum, s) => sum + estimateTokenCount(s), 0);
        }
      }
    }
  }

  // Only consider it "chunked" if we got multiple chunks
  return {
    chunked: chunks.length > 1,
    chunks,
  };
}

/**
 * Get parent content by reassembling chunks.
 * Useful for displaying full context when a chunk is retrieved.
 *
 * @param chunks - Array of chunk contents in order
 * @returns Reassembled parent content (with overlap removed)
 */
export function reassembleChunks(chunks: string[]): string {
  if (chunks.length === 0) return "";
  if (chunks.length === 1) return chunks[0];

  // For overlapping chunks, we need to deduplicate
  // Simple approach: use full first chunk, then non-overlapping parts of subsequent chunks
  // This is imperfect but handles most cases
  const result: string[] = [chunks[0]];

  for (let i = 1; i < chunks.length; i++) {
    const prevChunk = chunks[i - 1];
    const currChunk = chunks[i];

    // Find overlap by looking for common suffix/prefix
    // Try to find where the previous chunk ends in the current chunk
    const prevSentences = splitSentences(prevChunk);
    const currSentences = splitSentences(currChunk);

    // Find how many sentences from prev are at the start of curr
    let overlapCount = 0;
    for (let j = 0; j < Math.min(prevSentences.length, currSentences.length); j++) {
      // Check if last N sentences of prev match first N sentences of curr
      const prevEnd = prevSentences.slice(-(j + 1));
      const currStart = currSentences.slice(0, j + 1);

      if (joinSentences(prevEnd) === joinSentences(currStart)) {
        overlapCount = j + 1;
      }
    }

    // Add non-overlapping portion
    if (overlapCount > 0 && overlapCount < currSentences.length) {
      result.push(joinSentences(currSentences.slice(overlapCount)));
    } else if (overlapCount === 0) {
      // No detected overlap, add full chunk
      result.push(currChunk);
    }
    // If overlapCount === currSentences.length, skip (fully contained)
  }

  return joinSentences(result);
}

/**
 * Semantic Chunking with Smoothing-Based Topic Boundaries (Issue #368)
 *
 * An optional alternative to the recursive chunker in chunking.ts.
 * Uses sentence embeddings + cosine similarity + smoothing to detect
 * natural topic boundaries, producing more coherent chunks.
 */

import {
  chunkContent,
  joinSentences,
  splitSentences,
  type Chunk,
  type ChunkResult,
} from "./chunking.js";
import { estimateTokenCount } from "./token-estimate.js";

// ---------------------------------------------------------------------------
// Configuration
// ---------------------------------------------------------------------------

export interface SemanticChunkingConfig {
  /** Target tokens per chunk. Default: 200. */
  targetTokens: number;
  /** Minimum tokens for a segment before merging with neighbor. Default: 100. */
  minTokens: number;
  /** Maximum tokens for a segment before recursive splitting. Default: 400. */
  maxTokens: number;
  /** Window size for the moving-average smoothing filter. Default: 3. */
  smoothingWindowSize: number;
  /** How many standard deviations below the mean constitutes a boundary. Default: 1.0. */
  boundaryThresholdStdDevs: number;
  /** Batch size for embedding requests. Default: 32. */
  embeddingBatchSize: number;
  /** Fall back to recursive chunking when embeddings are unavailable. Default: true. */
  fallbackToRecursive: boolean;
}

export const DEFAULT_SEMANTIC_CHUNKING_CONFIG: SemanticChunkingConfig = {
  targetTokens: 200,
  minTokens: 100,
  maxTokens: 400,
  smoothingWindowSize: 3,
  boundaryThresholdStdDevs: 1.0,
  embeddingBatchSize: 32,
  fallbackToRecursive: true,
};

// ---------------------------------------------------------------------------
// Result types
// ---------------------------------------------------------------------------

export interface SemanticChunk extends Chunk {
  /** Optional topic hint derived from position. */
  topicLabel?: string;
  /** Cosine similarity score at the trailing boundary of this chunk. */
  boundaryScore: number;
}

export interface SemanticChunkResult {
  /** Whether content was split into multiple chunks. */
  chunked: boolean;
  /** The chunks produced. */
  chunks: SemanticChunk[];
  /** Sentence indices where topic splits occurred. */
  boundaries: number[];
  /** Which algorithm produced the result. */
  method: "semantic" | "recursive-fallback";
}

// ---------------------------------------------------------------------------
// Embedding function signature
// ---------------------------------------------------------------------------

/** Caller-provided function that embeds an array of texts, returning vectors. */
export type EmbedFn = (texts: string[]) => Promise<number[][]>;

// ---------------------------------------------------------------------------
// Math utilities (exported for testing)
// ---------------------------------------------------------------------------

/**
 * Cosine similarity between two vectors.
 * Returns a value in [-1, 1]. Identical direction = 1, orthogonal = 0.
 *
 * NOTE: This duplicates cosineSimilarity in recall-mmr.ts and embedding-fallback.ts.
 * Consider extracting to a shared math utility in a future refactor.
 */
export function cosineSimilarity(a: number[], b: number[]): number {
  if (a.length !== b.length) {
    throw new Error(
      `cosineSimilarity: vector length mismatch (${a.length} vs ${b.length})`,
    );
  }
  if (a.length === 0) return 0;

  let dot = 0;
  let magA = 0;
  let magB = 0;
  for (let i = 0; i < a.length; i++) {
    dot += a[i] * b[i];
    magA += a[i] * a[i];
    magB += b[i] * b[i];
  }

  const denom = Math.sqrt(magA) * Math.sqrt(magB);
  if (denom === 0) return 0;
  return dot / denom;
}

/**
 * Arithmetic mean of a numeric series.
 */
export function mean(series: number[]): number {
  if (series.length === 0) return 0;
  let sum = 0;
  for (const v of series) sum += v;
  return sum / series.length;
}

/**
 * Population standard deviation of a numeric series.
 */
export function stddev(series: number[]): number {
  if (series.length === 0) return 0;
  const m = mean(series);
  let sumSq = 0;
  for (const v of series) {
    const d = v - m;
    sumSq += d * d;
  }
  return Math.sqrt(sumSq / series.length);
}

/**
 * Simple moving average over a 1D series.
 * The window is centered: for window size W, each output[i] averages
 * series[i - floor(W/2) .. i + floor(W/2)], clamped to bounds.
 *
 * Even window sizes are rounded up to the next odd value so the window
 * is symmetric around the center point (Finding 4, PR #420).
 */
export function movingAverage(series: number[], windowSize: number): number[] {
  if (series.length === 0) return [];
  if (windowSize < 1) windowSize = 1;
  // Round even values up to the next odd so the window is symmetric.
  if (windowSize % 2 === 0) windowSize = windowSize + 1;

  const halfW = Math.floor(windowSize / 2);
  const result: number[] = new Array(series.length);

  for (let i = 0; i < series.length; i++) {
    const lo = Math.max(0, i - halfW);
    const hi = Math.min(series.length - 1, i + halfW);
    let sum = 0;
    for (let j = lo; j <= hi; j++) sum += series[j];
    result[i] = sum / (hi - lo + 1);
  }
  return result;
}

/**
 * Find indices in the series that are local minima AND below the threshold.
 * A local minimum is a point lower than both its immediate neighbors
 * (or lower-or-equal at series boundaries).
 */
export function findLocalMinima(
  series: number[],
  threshold: number,
): number[] {
  if (series.length <= 2) return [];

  const minima: number[] = [];
  for (let i = 1; i < series.length - 1; i++) {
    if (
      series[i] < series[i - 1] &&
      series[i] < series[i + 1] &&
      series[i] < threshold
    ) {
      minima.push(i);
    }
  }
  return minima;
}

// ---------------------------------------------------------------------------


// ---------------------------------------------------------------------------
// Core semantic chunking
// ---------------------------------------------------------------------------

/**
 * Batch-embed sentences using the provided embed function.
 * Respects the configured batch size.
 */
async function batchEmbed(
  sentences: string[],
  embedFn: EmbedFn,
  batchSize: number,
): Promise<number[][]> {
  const allEmbeddings: number[][] = [];

  for (let i = 0; i < sentences.length; i += batchSize) {
    const batch = sentences.slice(i, i + batchSize);
    const batchResult = await embedFn(batch);
    for (const vec of batchResult) {
      allEmbeddings.push(vec);
    }
  }

  return allEmbeddings;
}

function findEmbeddingDimensionMismatch(
  embeddings: number[][],
): { expected: number; actual: number; index: number } | null {
  if (embeddings.length <= 1) return null;
  const expected = embeddings[0].length;
  for (let i = 1; i < embeddings.length; i++) {
    const actual = embeddings[i].length;
    if (actual !== expected) {
      return { expected, actual, index: i };
    }
  }
  return null;
}

/**
 * Build segments from boundary indices.
 * boundaries are sentence indices at which splits occur (i.e., the split
 * happens AFTER the boundary index sentence).
 */
function buildSegments(
  sentences: string[],
  boundaries: number[],
): string[][] {
  const sorted = [...boundaries].sort((a, b) => a - b);
  const segments: string[][] = [];
  let start = 0;

  for (const b of sorted) {
    // Split after sentence at index b: segment is [start .. b]
    const splitPoint = b + 1;
    if (splitPoint > start && splitPoint <= sentences.length) {
      segments.push(sentences.slice(start, splitPoint));
      start = splitPoint;
    }
  }

  // Remaining sentences
  if (start < sentences.length) {
    segments.push(sentences.slice(start));
  }

  return segments;
}

/**
 * Merge short segments (below minTokens) with their neighbor.
 * Prefers merging forward; falls back to merging backward.
 */
function mergeShortSegments(
  segments: string[][],
  minTokens: number,
): string[][] {
  if (segments.length <= 1) return segments;

  const merged: string[][] = [];
  let buffer: string[] = [];

  for (let i = 0; i < segments.length; i++) {
    buffer = [...buffer, ...segments[i]];
    const tokenCount = estimateTokenCount(joinSentences(buffer));

    if (tokenCount >= minTokens || i === segments.length - 1) {
      merged.push(buffer);
      buffer = [];
    }
  }

  // If the last merge left a dangling buffer, attach it to the last segment
  if (buffer.length > 0) {
    if (merged.length > 0) {
      merged[merged.length - 1] = [...merged[merged.length - 1], ...buffer];
    } else {
      merged.push(buffer);
    }
  }

  return merged;
}

/**
 * Split an oversized segment using recursive chunking.
 */
function splitLongSegment(
  segment: string[],
  maxTokens: number,
  targetTokens: number,
): SemanticChunk[] {
  const text = joinSentences(segment);
  // Cap targetTokens to maxTokens so recursive splitting never produces
  // segments larger than the configured maximum (Finding 2, PR #420).
  const cappedTarget = Math.min(targetTokens, maxTokens);
  const result: ChunkResult = chunkContent(text, {
    targetTokens: cappedTarget,
    minTokens: Math.min(cappedTarget, maxTokens),
    overlapSentences: 0,
  });

  return result.chunks.map((c) => ({
    content: c.content,
    index: c.index,
    tokenCount: c.tokenCount,
    boundaryScore: 0,
  }));
}

/**
 * Semantic chunking with smoothing-based topic boundary detection.
 *
 * @param content   - Full text to chunk.
 * @param embedFn   - Async function that embeds an array of texts.
 * @param config    - Optional partial config overrides.
 * @returns SemanticChunkResult
 */
export async function semanticChunkContent(
  content: string,
  embedFn: EmbedFn,
  config?: Partial<SemanticChunkingConfig>,
): Promise<SemanticChunkResult> {
  const cfg: SemanticChunkingConfig = {
    ...DEFAULT_SEMANTIC_CHUNKING_CONFIG,
    ...config,
  };

  // Guard against non-positive batch size which would cause an infinite loop
  const batchSize = Math.max(1, cfg.embeddingBatchSize);

  // --- Empty / trivially short input ---
  if (!content || content.trim().length === 0) {
    return {
      chunked: false,
      chunks: [],
      boundaries: [],
      method: "semantic",
    };
  }

  const sentences = splitSentences(content);

  if (sentences.length <= 1) {
    const tokenCount = estimateTokenCount(content);
    return {
      chunked: false,
      chunks: [
        {
          content: content.trim(),
          index: 0,
          tokenCount,
          boundaryScore: 1,
        },
      ],
      boundaries: [],
      method: "semantic",
    };
  }

  // If total tokens is short enough, return as single chunk
  const totalTokens = estimateTokenCount(content);
  if (totalTokens <= cfg.minTokens) {
    return {
      chunked: false,
      chunks: [
        {
          content: content.trim(),
          index: 0,
          tokenCount: totalTokens,
          boundaryScore: 1,
        },
      ],
      boundaries: [],
      method: "semantic",
    };
  }

  // --- Attempt embedding ---
  let embeddings: number[][];
  try {
    embeddings = await batchEmbed(sentences, embedFn, batchSize);
  } catch {
    // Embedding failed — fall back if configured
    if (cfg.fallbackToRecursive) {
      return buildRecursiveFallback(content, cfg);
    }
    throw new Error(
      "Semantic chunking failed: embedding function threw and fallbackToRecursive is disabled",
    );
  }

  if (embeddings.length !== sentences.length) {
    if (cfg.fallbackToRecursive) {
      return buildRecursiveFallback(content, cfg);
    }
    throw new Error(
      `Semantic chunking failed: expected ${sentences.length} embeddings but received ${embeddings.length}`,
    );
  }

  const dimensionMismatch = findEmbeddingDimensionMismatch(embeddings);
  if (dimensionMismatch) {
    if (cfg.fallbackToRecursive) {
      return buildRecursiveFallback(content, cfg);
    }
    throw new Error(
      `Semantic chunking failed: embedding vectors have mismatched dimensions ` +
        `(${dimensionMismatch.expected} vs ${dimensionMismatch.actual} at index ${dimensionMismatch.index})`,
    );
  }

  // --- Compute pairwise cosine similarity ---
  const similarities: number[] = [];
  for (let i = 0; i < sentences.length - 1; i++) {
    similarities.push(cosineSimilarity(embeddings[i], embeddings[i + 1]));
  }

  // If only one pair (2 sentences), nothing to smooth or split meaningfully.
  // However, if the combined content exceeds maxTokens, apply recursive splitting.
  if (similarities.length <= 1) {
    if (totalTokens > cfg.maxTokens) {
      return buildRecursiveFallback(content, cfg);
    }
    return {
      chunked: false,
      chunks: [
        {
          content: content.trim(),
          index: 0,
          tokenCount: totalTokens,
          boundaryScore: similarities.length === 1 ? similarities[0] : 1,
        },
      ],
      boundaries: [],
      method: "semantic",
    };
  }

  // --- Smooth the similarity series ---
  const smoothed = movingAverage(similarities, cfg.smoothingWindowSize);

  // --- Detect boundaries: local minima below (mean - k * stddev) ---
  const m = mean(smoothed);
  const s = stddev(smoothed);
  const threshold = m - cfg.boundaryThresholdStdDevs * s;
  const rawBoundaries = findLocalMinima(smoothed, threshold);

  // --- Build segments, merge short, split long ---
  let segments = buildSegments(sentences, rawBoundaries);
  segments = mergeShortSegments(segments, cfg.minTokens);

  // --- Convert segments to chunks, splitting oversized ones ---
  const chunks: SemanticChunk[] = [];
  const finalBoundaries: number[] = [];
  let sentenceOffset = 0;

  for (let segIdx = 0; segIdx < segments.length; segIdx++) {
    const segment = segments[segIdx];
    const segText = joinSentences(segment);
    const segTokens = estimateTokenCount(segText);

    if (segTokens > cfg.maxTokens) {
      // Recursive split for oversized segment
      const subChunks = splitLongSegment(segment, cfg.maxTokens, cfg.targetTokens);
      for (const sc of subChunks) {
        chunks.push({
          ...sc,
          index: chunks.length,
        });
      }
    } else {
      // Compute boundary score: the similarity at the trailing edge
      const trailingSentenceIdx = sentenceOffset + segment.length - 1;
      let bScore = 1;
      if (
        trailingSentenceIdx < similarities.length &&
        segIdx < segments.length - 1
      ) {
        bScore = smoothed[trailingSentenceIdx] ?? similarities[trailingSentenceIdx] ?? 1;
      }

      chunks.push({
        content: segText,
        index: chunks.length,
        tokenCount: segTokens,
        boundaryScore: bScore,
      });
    }

    // Record boundaries (all but the last segment produce a boundary)
    if (segIdx < segments.length - 1) {
      finalBoundaries.push(sentenceOffset + segment.length - 1);
    }
    sentenceOffset += segment.length;
  }

  return {
    chunked: chunks.length > 1,
    chunks,
    boundaries: finalBoundaries,
    method: "semantic",
  };
}

// ---------------------------------------------------------------------------
// Recursive fallback helper
// ---------------------------------------------------------------------------

function buildRecursiveFallback(
  content: string,
  cfg: SemanticChunkingConfig,
): SemanticChunkResult {
  // Cap targetTokens to maxTokens so the recursive fallback path honours the
  // same constraint as splitLongSegment (PR #439 post-merge cursor[bot] finding).
  const cappedTarget = Math.min(cfg.targetTokens, cfg.maxTokens);
  const result: ChunkResult = chunkContent(content, {
    targetTokens: cappedTarget,
    minTokens: Math.min(cfg.minTokens, cappedTarget),
    overlapSentences: 0,
  });

  return {
    chunked: result.chunked,
    chunks: result.chunks.map((c) => ({
      ...c,
      boundaryScore: 0,
    })),
    boundaries: [],
    method: "recursive-fallback",
  };
}

/**
 * Extraction Judge Telemetry (issue #562, PR 3).
 *
 * Appends one structured event per judge verdict to the observation ledger
 * under a dedicated JSONL file. The ledger is the same directory used by
 * the turn-count observation writer
 * (`state/observation-ledger/rebuilt-observations.jsonl`) but judge events
 * live in their own file so aggregation stays cheap and schemas do not
 * collide.
 *
 * Emit path is best-effort and fail-open: a telemetry write must never
 * block an extraction run.
 */

import path from "node:path";
import { appendFile, mkdir, readFile } from "node:fs/promises";
import { log } from "./logger.js";
import type { JudgeVerdictKind } from "./extraction-judge.js";

/**
 * Observation-ledger category for judge verdict events. Callers that
 * aggregate across event kinds can filter on this constant.
 */
export const EXTRACTION_JUDGE_VERDICT_CATEGORY = "EXTRACTION_JUDGE_VERDICT";

/**
 * Structured event written for every judge verdict (including verdicts
 * served from cache). The `version` field lets future readers upgrade the
 * schema without breaking older rows.
 */
export interface JudgeVerdictEvent {
  version: 1;
  category: typeof EXTRACTION_JUDGE_VERDICT_CATEGORY;
  ts: string; // ISO-8601
  verdictKind: JudgeVerdictKind;
  /** Short free-text reason from the judge / deterministic fallback. */
  reason: string;
  /**
   * How many times this candidate's content hash had already been deferred
   * before this verdict. 0 for the first defer, 1 for the second, etc.
   * Not applicable for non-defer kinds — emitted as 0.
   */
  deferrals: number;
  /**
   * Milliseconds between batch start and batch return (the whole
   * `judgeFactDurability` call, shared across all verdicts in a single
   * batch).
   */
  elapsedMs: number;
  /** Candidate metadata for coarse filtering. */
  candidateCategory: string;
  confidence?: number;
  /** SHA-256 of the (text\0category) pair, same as the verdict-cache key. */
  contentHash: string;
  /** Whether the verdict came from the in-memory verdict cache. */
  fromCache: boolean;
  /**
   * True when the judge forcibly converted a defer to reject because the
   * defer cap was reached. Only set on cap-triggered rejects.
   */
  deferCapTriggered?: boolean;
}

/**
 * Options to control emit behavior. `enabled` gates all writes; when
 * false, `recordJudgeVerdict` is a no-op so callers can unconditionally
 * invoke it.
 */
export interface JudgeTelemetryOptions {
  enabled: boolean;
  memoryDir: string;
}

export function judgeTelemetryPath(memoryDir: string): string {
  return path.join(
    memoryDir,
    "state",
    "observation-ledger",
    "extraction-judge-verdicts.jsonl",
  );
}

/**
 * Append a single verdict event as a JSONL row. Fails open — if the write
 * cannot be completed (directory missing, permissions, disk full), the
 * error is logged at debug level and swallowed so extraction never fails
 * because of telemetry.
 */
export async function recordJudgeVerdict(
  event: JudgeVerdictEvent,
  options: JudgeTelemetryOptions,
): Promise<void> {
  if (!options.enabled) return;
  const filePath = judgeTelemetryPath(options.memoryDir);
  try {
    await mkdir(path.dirname(filePath), { recursive: true });
    await appendFile(filePath, `${JSON.stringify(event)}\n`, "utf-8");
  } catch (err) {
    log.debug(
      `extraction-judge-telemetry: append failed (non-fatal): ${err instanceof Error ? err.message : String(err)}`,
    );
  }
}

/**
 * Aggregate statistics over the verdict ledger, optionally restricted to a
 * time window. Returns zero-count stats when the ledger is missing or
 * empty — callers do not need to special-case a cold install.
 */
export interface JudgeVerdictStats {
  total: number;
  accept: number;
  reject: number;
  defer: number;
  deferCapTriggered: number;
  /** Mean elapsed milliseconds across all events in the window. */
  meanElapsedMs: number;
  /** Defer rate as `defer / total`, in `[0, 1]`. `0` when total is 0. */
  deferRate: number;
  /** First and last event timestamps observed in the window. */
  firstTs?: string;
  lastTs?: string;
  /** Number of rows skipped because they were malformed or wrong shape. */
  malformed: number;
}

/**
 * Read and aggregate events from the verdict ledger.
 *
 * `sinceMs` / `untilMs` bound by `ts` parse — events with unparseable
 * timestamps are counted toward `malformed`. The upper bound is exclusive
 * (`ts < untilMs`), per CLAUDE.md gotcha 35.
 */
export async function readJudgeVerdictStats(
  memoryDir: string,
  opts: { sinceMs?: number; untilMs?: number } = {},
): Promise<JudgeVerdictStats> {
  const filePath = judgeTelemetryPath(memoryDir);
  let raw: string;
  try {
    raw = await readFile(filePath, "utf-8");
  } catch (err) {
    const code = (err as NodeJS.ErrnoException).code;
    if (code === "ENOENT") {
      return {
        total: 0,
        accept: 0,
        reject: 0,
        defer: 0,
        deferCapTriggered: 0,
        meanElapsedMs: 0,
        deferRate: 0,
        malformed: 0,
      };
    }
    throw err;
  }

  let total = 0;
  let accept = 0;
  let reject = 0;
  let defer = 0;
  let deferCapTriggered = 0;
  let elapsedSum = 0;
  let malformed = 0;
  let firstTs: string | undefined;
  let lastTs: string | undefined;

  for (const line of raw.split("\n")) {
    if (!line.trim()) continue;
    let parsed: unknown;
    try {
      parsed = JSON.parse(line);
    } catch {
      malformed += 1;
      continue;
    }
    if (
      typeof parsed !== "object" ||
      parsed === null ||
      Array.isArray(parsed)
    ) {
      malformed += 1;
      continue;
    }
    const p = parsed as Record<string, unknown>;
    if (p.category !== EXTRACTION_JUDGE_VERDICT_CATEGORY) {
      malformed += 1;
      continue;
    }
    const ts = typeof p.ts === "string" ? p.ts : null;
    if (ts === null) {
      malformed += 1;
      continue;
    }
    const tsMs = Date.parse(ts);
    if (!Number.isFinite(tsMs)) {
      malformed += 1;
      continue;
    }
    if (typeof opts.sinceMs === "number" && tsMs < opts.sinceMs) continue;
    if (typeof opts.untilMs === "number" && tsMs >= opts.untilMs) continue;

    const kind = p.verdictKind;
    if (kind === "accept") accept += 1;
    else if (kind === "reject") reject += 1;
    else if (kind === "defer") defer += 1;
    else {
      malformed += 1;
      continue;
    }

    if (p.deferCapTriggered === true) deferCapTriggered += 1;
    if (typeof p.elapsedMs === "number" && Number.isFinite(p.elapsedMs)) {
      elapsedSum += p.elapsedMs;
    }
    total += 1;
    if (firstTs === undefined || ts < firstTs) firstTs = ts;
    if (lastTs === undefined || ts > lastTs) lastTs = ts;
  }

  return {
    total,
    accept,
    reject,
    defer,
    deferCapTriggered,
    meanElapsedMs: total > 0 ? elapsedSum / total : 0,
    deferRate: total > 0 ? defer / total : 0,
    firstTs,
    lastTs,
    malformed,
  };
}

/**
 * Extraction Judge Training Data Shim (issue #562, PR 4).
 *
 * Opt-in collector for `(candidate_text, verdict_kind, reason,
 * ground_truth_label?)` tuples. Rows are appended to JSONL files under
 * `~/.remnic/judge-training/<YYYY-MM-DD>.jsonl` so operators can ship the
 * data into a future GRPO training pipeline without exfiltrating live
 * memory content through the regular observation ledger.
 *
 * Gating:
 *   - Off by default. Must be explicitly enabled via
 *     `collectJudgeTrainingPairs: true` in plugin config.
 *   - The ground-truth label is always optional — labels are added out-of-
 *     band once reviewers disambiguate the candidate's fate.
 *
 * Privacy: the row carries only what the judge already sees — the
 * candidate text and its metadata. It does NOT carry session keys,
 * principal IDs, or any user identifiers. The file lives in the user's
 * home directory rather than the shared memory directory so it is never
 * committed, sync'd, or bundled into exports.
 */

import path from "node:path";
import { homedir } from "node:os";
import { appendFile, chmod, lstat, mkdir, readFile, readdir, realpath } from "node:fs/promises";
import { log } from "./logger.js";
import type { JudgeVerdictKind } from "./extraction-judge.js";

/**
 * Persisted training row. Intentionally minimal: just the signal needed
 * to train a judge replacement policy. Schema version is tagged so future
 * readers can migrate older rows.
 */
export interface JudgeTrainingPair {
  version: 1;
  ts: string; // ISO-8601
  candidateText: string;
  candidateCategory: string;
  candidateConfidence?: number;
  verdictKind: JudgeVerdictKind;
  reason: string;
  /**
   * Number of prior deferrals when the verdict was resolved. `0` for the
   * first resolution; only set when known (defer pathway).
   */
  priorDeferrals?: number;
  /**
   * Optional human-applied ground-truth label. Added after the fact by a
   * reviewer / labelling script; not present on fresh rows.
   */
  groundTruthLabel?: JudgeVerdictKind;
}

export interface JudgeTrainingOptions {
  enabled: boolean;
  /**
   * Override for the output directory. Defaults to
   * `~/.remnic/judge-training`. Tests pass a temp path here.
   */
  directory?: string;
}

/**
 * Expand a leading `~` / `~/` / `$HOME/` / `${HOME}/` to the process home
 * directory. Node's `fs` APIs do not expand `~` themselves (CLAUDE.md
 * gotcha 17), so every user-facing path input must be funnelled through
 * this helper before it reaches the filesystem.
 */
function expandTilde(p: string): string {
  const home = homedir();
  if (p === "~" || p.startsWith("~/") || p.startsWith("~\\")) {
    return home + p.slice(1);
  }
  if (p === "$HOME" || p.startsWith("$HOME/") || p.startsWith("$HOME\\")) {
    return home + p.slice(5);
  }
  if (p === "${HOME}" || p.startsWith("${HOME}/") || p.startsWith("${HOME}\\")) {
    return home + p.slice(7);
  }
  return p;
}

export function resolveTrainingDir(options: JudgeTrainingOptions): string {
  if (options.directory && options.directory.length > 0) {
    // Expand `~` / `$HOME` in the override so operators can write the
    // config as the user sees it (CLAUDE.md gotcha 17).
    return expandTilde(options.directory);
  }
  return path.join(homedir(), ".remnic", "judge-training");
}

function dateStamp(iso: string): string {
  // `YYYY-MM-DD` from an ISO-8601 string. Falls back to today on a parse
  // failure rather than throwing — the caller already wrote a row and the
  // timestamp is best-effort.
  const ms = Date.parse(iso);
  const d = Number.isFinite(ms) ? new Date(ms) : new Date();
  const yyyy = d.getUTCFullYear().toString().padStart(4, "0");
  const mm = (d.getUTCMonth() + 1).toString().padStart(2, "0");
  const dd = d.getUTCDate().toString().padStart(2, "0");
  return `${yyyy}-${mm}-${dd}`;
}

export function trainingFilePathFor(directory: string, iso: string): string {
  return path.join(directory, `${dateStamp(iso)}.jsonl`);
}

function isPathInsideDirectory(filePath: string, directory: string): boolean {
  const relative = path.relative(directory, filePath);
  return relative === "" || (!relative.startsWith("..") && !path.isAbsolute(relative));
}

/**
 * Append a single training row. Fails open — write errors are logged at
 * debug level and swallowed, same policy as the telemetry emitter.
 * No-op when `options.enabled` is false.
 */
export async function recordJudgeTrainingPair(row: JudgeTrainingPair, options: JudgeTrainingOptions): Promise<void> {
  if (!options.enabled) return;
  const dir = resolveTrainingDir(options);
  const filePath = trainingFilePathFor(dir, row.ts);
  try {
    await mkdir(dir, { recursive: true, mode: 0o700 });
    await appendFile(filePath, `${JSON.stringify(row)}\n`, {
      encoding: "utf-8",
      mode: 0o600,
    });
    await chmod(filePath, 0o600);
  } catch (err) {
    log.debug(
      `extraction-judge-training: append failed (non-fatal): ${err instanceof Error ? err.message : String(err)}`
    );
  }
}

/**
 * Read all training rows from the configured directory. Returns an empty
 * array when the directory is missing. Malformed lines are skipped and
 * counted in the returned `malformed` tally.
 */
export async function readJudgeTrainingPairs(
  options: Pick<JudgeTrainingOptions, "directory">
): Promise<{ rows: JudgeTrainingPair[]; malformed: number }> {
  const dir = resolveTrainingDir({ enabled: true, ...options });
  try {
    const dirStat = await lstat(dir);
    if (dirStat.isSymbolicLink()) {
      throw new Error("Judge training directory must not be a symlink");
    }
    if (!dirStat.isDirectory()) {
      throw new Error("Judge training path must be a directory");
    }
  } catch (err) {
    const code = (err as NodeJS.ErrnoException).code;
    if (code === "ENOENT") return { rows: [], malformed: 0 };
    throw err;
  }

  let entries: string[];
  try {
    entries = await readdir(dir);
  } catch (err) {
    const code = (err as NodeJS.ErrnoException).code;
    if (code === "ENOENT") return { rows: [], malformed: 0 };
    throw err;
  }

  const rows: JudgeTrainingPair[] = [];
  let malformed = 0;
  const resolvedDir = await realpath(dir);
  // Sort so reads are deterministic across platforms.
  entries.sort();
  for (const name of entries) {
    if (!name.endsWith(".jsonl")) continue;
    const filePath = path.join(dir, name);
    let fileStat: Awaited<ReturnType<typeof lstat>>;
    try {
      fileStat = await lstat(filePath);
    } catch (err) {
      const code = (err as NodeJS.ErrnoException).code;
      if (code === "ENOENT") continue;
      throw err;
    }
    if (fileStat.isSymbolicLink() || !fileStat.isFile()) continue;

    let resolvedFilePath: string;
    try {
      resolvedFilePath = await realpath(filePath);
    } catch (err) {
      const code = (err as NodeJS.ErrnoException).code;
      if (code === "ENOENT") continue;
      throw err;
    }
    if (!isPathInsideDirectory(resolvedFilePath, resolvedDir)) continue;

    const raw = await readFile(resolvedFilePath, "utf-8");
    for (const line of raw.split("\n")) {
      if (!line.trim()) continue;
      let parsed: unknown;
      try {
        parsed = JSON.parse(line);
      } catch {
        malformed += 1;
        continue;
      }
      if (!isValidTrainingPair(parsed)) {
        malformed += 1;
        continue;
      }
      rows.push(parsed);
    }
  }
  return { rows, malformed };
}

/**
 * Structural validator matching the persisted schema. Forward-compat: an
 * unknown `verdictKind` string is treated as malformed (strict training
 * signal — we do not want to admit unlabelled gibberish into a trainer).
 */
export function isValidTrainingPair(value: unknown): value is JudgeTrainingPair {
  if (typeof value !== "object" || value === null || Array.isArray(value)) {
    return false;
  }
  const p = value as Record<string, unknown>;
  if (p.version !== 1) return false;
  if (typeof p.ts !== "string") return false;
  if (typeof p.candidateText !== "string") return false;
  if (typeof p.candidateCategory !== "string") return false;
  if (p.verdictKind !== "accept" && p.verdictKind !== "reject" && p.verdictKind !== "defer") {
    return false;
  }
  if (typeof p.reason !== "string") return false;
  if (p.candidateConfidence !== undefined && typeof p.candidateConfidence !== "number") {
    return false;
  }
  if (p.priorDeferrals !== undefined && typeof p.priorDeferrals !== "number") {
    return false;
  }
  if (
    p.groundTruthLabel !== undefined &&
    p.groundTruthLabel !== "accept" &&
    p.groundTruthLabel !== "reject" &&
    p.groundTruthLabel !== "defer"
  ) {
    return false;
  }
  return true;
}

/**
 * Event-time resolver (issue #1578).
 *
 * Extraction can carry an optional per-fact `eventTime` expression — an ISO
 * date or a relative phrase verbatim from the source turn ("last March",
 * "yesterday", "since 2024").  This module resolves such expressions into a
 * `[validFrom, validUntil)` event-time interval, **anchored to the source
 * turn's timestamp** — never to `Date.now()`.
 *
 * Why anchor (not wall-clock): replay/import of old transcripts must resolve
 * "yesterday" against the *old* turn's yesterday, not today.  A relative
 * expression is meaningless without its anchor; resolving it against the
 * current time would silently rewrite history (AGENTS.md §39 — byte-identical
 * when the feature is off; rule 35 — half-open intervals; rule 51 — never
 * silently default invalid input).
 *
 * Resolution is **write-time-only**.  The on-disk frontmatter stores absolute
 * ISO timestamps strings (`valid_at` / `invalid_at`); readers never call back
 * into this module.  Anything unresolvable yields `ok: false` and the caller
 * records `eventTimeSource: "assumed"` with `valid_at` copied from the
 * ingestion anchor (`observedAt`).
 *
 * Interval semantics are `[validFrom, validUntil)` — inclusive start,
 * exclusive end (AGENTS.md §23).  A date-only expression resolving an *end*
 * bound converts to start-of-next-day so the end date itself is excluded.
 */
import { parseFlexibleIsoTimestamp } from "./utils/iso-timestamp.js";

/**
 * Resolved event-time interval.  All timestamps are UTC ISO strings.
 *
 * - `validFrom` / `validUntil` carry the half-open `[from, until)` event
 *   interval.  Either may be absent when the expression only pinned one side
 *   ("since 2024" → validFrom only).
 * - `ok` is false when the expression could not be resolved.  The caller then
 *   falls back to `eventTimeSource: "assumed"`.
 */
export interface ResolvedEventTime {
  validFrom?: string;
  validUntil?: string;
  ok: boolean;
}

const UNITS = ["day", "week", "month", "quarter", "year"] as const;
type RelativeUnit = (typeof UNITS)[number];

function isRelativeUnit(unit: string): unit is RelativeUnit {
  return (UNITS as readonly string[]).includes(unit);
}

/**
 * Format a `Date` as a UTC ISO string with millisecond precision, matching the
 * canonical frontmatter form.  Returns `undefined` when the input is not
 * finite (the resolver treats that as unresolvable rather than emitting
 * `Invalid Date`).
 */
function toIsoUtc(ms: number | null): string | undefined {
  if (ms === null || !Number.isFinite(ms)) return undefined;
  return new Date(ms).toISOString();
}

/**
 * Compute the start of the day (UTC) for the given ms, used when a date-only
 * expression resolves a *start* bound — the fact holds from midnight UTC.
 */
function startOfDayUtc(ms: number): number {
  const d = new Date(ms);
  d.setUTCHours(0, 0, 0, 0);
  return d.getTime();
}

/**
 * Compute the start of the *next* day (UTC) for the given ms, used when a
 * date-only expression resolves an *end* bound — the exclusive `validUntil`
 * must land on the following midnight so the end date itself is excluded
 * (AGENTS.md §23: date-only ends convert to start-of-next-day).
 */
function startOfNextDayUtc(ms: number): number {
  const d = new Date(startOfDayUtc(ms));
  d.setUTCDate(d.getUTCDate() + 1);
  return d.getTime();
}

const SEASON_TO_MONTH: Record<string, number> = {
  winter: 12, // Dec–Feb anchor Dec (Northern Hemisphere convention)
  spring: 3,
  summer: 6,
  fall: 9,
  autumn: 9,
};

const MONTH_NAMES: Record<string, number> = {
  january: 1, february: 2, march: 3, april: 4, may: 5, june: 6,
  july: 7, august: 8, september: 9, october: 10, november: 11, december: 12,
  jan: 1, feb: 2, mar: 3, apr: 4, jun: 6, jul: 7, aug: 8, sep: 9, sept: 9,
  oct: 10, nov: 11, dec: 12,
};

const QUARTER_START_MONTH: Record<number, number> = {
  1: 1, 2: 4, 3: 7, 4: 10,
};

function monthIndex(token: string): number | undefined {
  const idx = MONTH_NAMES[token.toLowerCase()];
  return typeof idx === "number" ? idx : undefined;
}

/**
 * Construct a UTC timestamp from year/month(1-12)/day with overflow validation.
 * Returns `null` when the components do not form a real calendar date (e.g.
 * Feb 30) rather than letting `Date` silently roll over.
 */
function buildDateMs(year: number, month1: number, day: number): number | null {
  if (
    !Number.isInteger(year) ||
    !Number.isInteger(month1) ||
    month1 < 1 ||
    month1 > 12 ||
    !Number.isInteger(day) ||
    day < 1 ||
    day > daysInMonth(year, month1)
  ) {
    return null;
  }
  return Date.UTC(year, month1 - 1, day, 0, 0, 0, 0);
}

function daysInMonth(year: number, month1: number): number {
  return new Date(Date.UTC(year, month1, 0)).getUTCDate();
}

/**
 * Add `count` units to a UTC ms timestamp, returning the start-of-period for
 * the resulting date.  Used by "last/this/next <unit>" resolution.
 */
function shiftUnit(anchorMs: number, unit: RelativeUnit, count: number): number {
  const d = new Date(anchorMs);
  switch (unit) {
    case "day":
      d.setUTCDate(d.getUTCDate() + count);
      return startOfDayUtc(d.getTime());
    case "week":
      d.setUTCDate(d.getUTCDate() + count * 7);
      return startOfDayUtc(d.getTime());
    case "month":
      d.setUTCMonth(d.getUTCMonth() + count, 1);
      return startOfDayUtc(d.getTime());
    case "quarter":
      d.setUTCMonth(d.getUTCMonth() + count * 3, 1);
      return startOfDayUtc(d.getTime());
    case "year":
      d.setUTCFullYear(d.getUTCFullYear() + count, 0, 1);
      return startOfDayUtc(d.getTime());
  }
}

/**
 * Resolve "last December" / "this March" / "next Q2" against the anchor.
 * `direction` is -1 (last), 0 (this), +1 (next).  Returns the start-of-period
 * ms for the referenced month/season/quarter, or `null` if it cannot be
 * placed (e.g. month token not recognized).
 */
function resolveMonthYear(
  anchorMs: number,
  monthToken: string,
  direction: number,
): number | null {
  const lower = monthToken.toLowerCase();
  const targetMonth = monthIndex(lower);
  if (typeof targetMonth === "number") {
    const d = new Date(anchorMs);
    let year = d.getUTCFullYear();
    let m = targetMonth;
    if (direction === -1 && m >= d.getUTCMonth() + 1) year -= 1;
    else if (direction === +1 && m <= d.getUTCMonth() + 1) year += 1;
    return buildDateMs(year, m, 1);
  }
  return null;
}
/**
 * Resolve an explicit "<month|season> <year>" token (e.g. "march 2025",
 * "dec 2024", "spring 2025") to a start-of-month ms.  The explicit year is
 * authoritative — it is never derived from the anchor.  Returns null when
 * the token is not in that shape or does not name a real month/season.
 * Shared by the bare phrase path, "since <month> <year>", and the end bound
 * so all three resolve identically (review: month-year phrases after since).
 */
function resolveExplicitMonthYear(token: string): number | null {
  const m = token.trim().toLowerCase().match(/^([a-z]+)\s+(\d{4})$/);
  if (!m) return null;
  const year = parseInt(m[2], 10);
  if (!Number.isInteger(year)) return null;
  const monthIdx = monthIndex(m[1]);
  const baseMonth = typeof monthIdx === "number" ? monthIdx : SEASON_TO_MONTH[m[1]];
  if (typeof baseMonth !== "number") return null;
  return buildDateMs(year, baseMonth, 1);
}


/**
 * Resolve a bare four-digit year token (e.g. "2024") to January 1 of that
 * year.  Used by "since 2024" and bare year expressions.  Review #1578 r2:
 * previously these fell through to ok:false, stamping the fact at ingestion
 * time instead of the documented year start.
 */
function resolveBareYear(token: string): number | null {
  const m = token.trim().match(/^(\d{4})$/);
  if (!m) return null;
  return buildDateMs(Number(m[1]), 1, 1);
}


/**
 * Check whether the anchor month falls inside a season's 3-month span.
 * Seasons start at `baseMonth` and span 3 months (e.g. summer = Jun–Aug).
 * Winter (Dec=12) wraps: Dec, Jan, Feb.
 */
function isInSeason(baseMonth: number, anchorMonth: number): boolean {
  for (let i = 0; i < 3; i++) {
    if (((baseMonth - 1 + i) % 12) + 1 === anchorMonth) return true;
  }
  return false;
}

function resolveSeasonYear(
  anchorMs: number,
  seasonToken: string,
  direction: number,
): number | null {
  const baseMonth = SEASON_TO_MONTH[seasonToken.toLowerCase()];
  if (typeof baseMonth !== "number") return null;
  const d = new Date(anchorMs);
  let year = d.getUTCFullYear();
  const anchorMonth = d.getUTCMonth() + 1;

  if (direction === -1) {
    // "last <season>": go to the previous occurrence.
    // If the season hasn't started yet this year (baseMonth > anchorMonth)
    // or the anchor is currently INSIDE the season, roll back a year.
    if (baseMonth > anchorMonth || isInSeason(baseMonth, anchorMonth)) year -= 1;
    // Winter tail (Jan/Feb): current winter started prev Dec, so "last"
    // needs one more year back.
    if (baseMonth === 12 && anchorMonth <= 2) year -= 1;
  } else if (direction === +1) {
    // "next <season>": go to the next occurrence.
    // Winter from Jan/Feb: current winter started prev Dec; next is this Dec.
    if (baseMonth === 12 && anchorMonth <= 2) {
      // no year change — next winter is December of the anchor year
    } else if (baseMonth < anchorMonth || isInSeason(baseMonth, anchorMonth)) {
      year += 1;
    }
  } else if (direction === 0 && baseMonth === 12 && anchorMonth <= 2) {
    // "this winter" from Jan/Feb: winter started in the previous December.
    year -= 1;
  }
  return buildDateMs(year, baseMonth, 1);
}

function resolveQuarter(
  anchorMs: number,
  qNumber: number,
  direction: number,
): number | null {
  const startMonth = QUARTER_START_MONTH[qNumber];
  if (typeof startMonth !== "number") return null;
  const d = new Date(anchorMs);
  let year = d.getUTCFullYear();
  const anchorMonth = d.getUTCMonth() + 1;
  const anchorQ = Math.floor((anchorMonth - 1) / 3) + 1;
  // Roll back/forward when the target quarter hasn't started yet this year
  // (startMonth past the anchor month) OR when the anchor is currently
  // INSIDE the target quarter (review r2: "last Q2" from May returned 2026
  // instead of 2025 because the quarter start month had already passed but
  // the quarter was still ongoing).
  if (direction === -1 && (startMonth >= anchorMonth || anchorQ === qNumber))
    year -= 1;
  else if (direction === +1 && (startMonth <= anchorMonth || anchorQ === qNumber))
    year += 1;
  return buildDateMs(year, startMonth, 1);
}

/**
 * Resolve an absolute ISO date/datetime to ms.  A date-only value yields
 * start-of-day (UTC).  Returns `null` when the string is not a well-formed,
 * non-overflowed ISO timestamp.
 */
function resolveAbsolute(raw: string): number | null {
  const trimmed = raw.trim();
  // YYYY-MM (ISO year-month, no day) → first day of that month, UTC
  // (#1578 review r3: the prompt example "until 2025-06" must resolve, not
  // fall back to "assumed").
  const ym = /^(\d{4})-(\d{2})$/.exec(trimmed);
  if (ym) {
    const ms = buildDateMs(Number(ym[1]), Number(ym[2]), 1);
    return ms === null ? null : startOfDayUtc(ms);
  }
  const ms = parseFlexibleIsoTimestamp(trimmed);
  if (ms === null) return null;
  // Date-only inputs (no T) anchor to start-of-day UTC.
  if (!/[Tt]/.test(trimmed)) return startOfDayUtc(ms);
  return ms;
}

/**
 * Resolve a relative event-time expression against an anchor ISO timestamp.
 *
 * Supported shapes (case-insensitive, trimmed):
 *   - absolute ISO date / datetime: `"2026-03-01"`, `"2026-03-01T00:00:00Z"`
 *   - `"since <date|monthyear>"` → validFrom only
 *   - `"until <date|monthyear>"` / `"through ..."` / `"until end of ..."` → validUntil only
 *   - `"last <month|season|Qn|unit>"` → validFrom = start of referenced period
 *   - `"this <month|season|Qn|unit>"` → validFrom = start of current period
 *   - `"next <month|season|Qn|unit>"` → validFrom = start of referenced period
 *   - `"yesterday"` / `"today"` / `"tomorrow"` → validFrom = start of that day
 *
 * Anything else returns `{ ok: false }`.  The caller then records
 * `eventTimeSource: "assumed"`.
 *
 * @param expression the raw per-fact event-time phrase (may be empty/garbage)
 * @param anchorIso  the source turn's ISO timestamp — the resolution anchor
 */
export function resolveEventTime(
  expression: string | undefined | null,
  anchorIso: string,
): ResolvedEventTime {
  const fallback: ResolvedEventTime = { ok: false };
  if (typeof expression !== "string") return fallback;
  const expr = expression.trim();
  if (expr.length === 0) return fallback;

  const anchorMs = parseFlexibleIsoTimestamp(anchorIso);
  if (anchorMs === null || !Number.isFinite(anchorMs)) return fallback;

  const lower = expr.toLowerCase();

  // ── "since <x>" / "until <x>" / "through <x>" ──────────────────────────
  const sinceMatch = lower.match(/^since\s+(.+)$/);
  if (sinceMatch) {
    const inner = sinceMatch[1].trim();
    let fromMs =
      resolveRelativePeriod(anchorMs, inner) ??
      resolveExplicitMonthYear(inner) ??
      resolveBareYear(inner) ??
      resolveAbsolute(inner);
    // "since <bare month/season>": if the resolved start is future and the
    // expression carries no explicit 4-digit year, the fact meant the most
    // recent PAST occurrence of that period (codex review r2: "since March"
    // from January produced a future validFrom).
    if (
      fromMs !== null &&
      fromMs > anchorMs &&
      !/\d{4}/.test(inner)
    ) {
      const nd = new Date(fromMs);
      nd.setUTCFullYear(nd.getUTCFullYear() - 1);
      fromMs = nd.getTime();
    }
    const fromIso = toIsoUtc(fromMs);
    if (!fromIso) return fallback;
    return { validFrom: fromIso, ok: true };
  }
  const untilMatch = lower.match(/^(?:until|through|till|ending)\s+(.+)$/);
  if (untilMatch) {
    const inner = untilMatch[1].trim();
    const untilMs = resolveEndBound(anchorMs, inner);
    const untilIso = toIsoUtc(untilMs);
    if (!untilIso) return fallback;
    return { validUntil: untilIso, ok: true };
  }

  // ── "yesterday" / "today" / "tomorrow" ─────────────────────────────────
  if (lower === "today") {
    const fromIso = toIsoUtc(startOfDayUtc(anchorMs));
    return fromIso ? { validFrom: fromIso, ok: true } : fallback;
  }
  if (lower === "yesterday") {
    const fromIso = toIsoUtc(shiftUnit(anchorMs, "day", -1));
    return fromIso ? { validFrom: fromIso, ok: true } : fallback;
  }
  if (lower === "tomorrow") {
    const fromIso = toIsoUtc(shiftUnit(anchorMs, "day", +1));
    return fromIso ? { validFrom: fromIso, ok: true } : fallback;
  }

  // ── "last/this/next <period>" ──────────────────────────────────────────
  const relMatch = lower.match(/^(last|this|next)\s+(.+)$/);
  if (relMatch) {
    const direction = relMatch[1] === "last" ? -1 : relMatch[1] === "next" ? +1 : 0;
    const period = relMatch[2].trim();
    const ms = resolveRelativePeriod(anchorMs, period, direction);
    const fromIso = toIsoUtc(ms);
    return fromIso ? { validFrom: fromIso, ok: true } : fallback;
  }

  // ── bare month+year ("March 2025", "Dec 2024", "spring 2025") or
  // bare four-digit year ("2024") ────────────────────────────────────────
  // Explicit year is authoritative (never derived from the anchor). Shares
  // resolveExplicitMonthYear / resolveBareYear with the since/until paths.
  const explicitMs = resolveExplicitMonthYear(lower) ?? resolveBareYear(lower);
  if (explicitMs !== null) {
    const fromIso = toIsoUtc(explicitMs);
    if (fromIso) return { validFrom: fromIso, ok: true };
  }

  // ── absolute ISO date / datetime ───────────────────────────────────────
  const absMs = resolveAbsolute(expr);
  if (absMs !== null) {
    const fromIso = toIsoUtc(absMs);
    return fromIso ? { validFrom: fromIso, ok: true } : fallback;
  }

  return fallback;
}

/**
 * Resolve a period token (with optional direction) to a start-of-period ms.
 * Handles month/season names, quarter tokens (`q1`..`q4`), and relative units
 * (`day/week/month/quarter/year`) used by "last week", "this month", etc.
 */
function resolveRelativePeriod(
  anchorMs: number,
  period: string,
  direction: number = 0,
): number | null {
  const lower = period.trim().toLowerCase();

  // Quarter token: "q1", "Q2", "quarter 3"
  const qTok = lower.match(/^q(?:uarter)?\s?([1-4])$/);
  if (qTok) {
    return resolveQuarter(anchorMs, Number(qTok[1]), direction);
  }
  if (lower === "quarter") {
    // "last quarter" / "next quarter" move the quarter INDEX (with year
    // wraparound), not just the year — resolveQuarter only nudges the year
    // for an explicit quarter number, so routing "last quarter" through it
    // returned the current quarter's start (review: bare last/next quarter).
    const d = new Date(anchorMs);
    let q = Math.floor(d.getUTCMonth() / 3) + 1;
    let year = d.getUTCFullYear();
    if (direction === -1) {
      q -= 1;
      if (q < 1) { q = 4; year -= 1; }
    } else if (direction === +1) {
      q += 1;
      if (q > 4) { q = 1; year += 1; }
    }
    return buildDateMs(year, QUARTER_START_MONTH[q], 1);
  }

  // Relative unit: "week", "month", "year", "day"
  if (isRelativeUnit(lower)) {
    return shiftUnit(anchorMs, lower, direction);
  }

  // Month or season name
  const monthMs = resolveMonthYear(anchorMs, lower, direction);
  if (monthMs !== null) return monthMs;
  const seasonMs = resolveSeasonYear(anchorMs, lower, direction);
  if (seasonMs !== null) return seasonMs;

  return null;
}

/**
 * Resolve an end-bound period to an *exclusive* upper bound ms.  Date-only
 * values convert to start-of-next-day (AGENTS.md §23); period names resolve to
 * the start of the *following* period.
 */
function resolveEndBound(anchorMs: number, period: string): number | null {
  // Strip an optional "end of " prefix so "until end of March" resolves the
  // same as "until March".  Review #1578 r2: previously the prefix was passed
  // unchanged and resolveEndBound returned null for the full phrase.
  const trimmed = period.trim().replace(/^end\s+of\s+/i, "").trim();

  // Bare four-digit year: exclusive end = January 1 of the FOLLOWING year.
  if (/^\d{4}$/.test(trimmed)) {
    return buildDateMs(Number(trimmed) + 1, 1, 1);
  }

  // YYYY-MM (year-month) end bound: exclusive end = start of the FOLLOWING
  // month, so "until 2025-06" spans all of June (#1578 review r3).
  const ymEnd = /^(\d{4})-(\d{2})$/.exec(trimmed);
  if (ymEnd) {
    const startMs = buildDateMs(Number(ymEnd[1]), Number(ymEnd[2]), 1);
    if (startMs === null) return null;
    const nd = new Date(startMs);
    nd.setUTCMonth(nd.getUTCMonth() + 1);
    return startOfDayUtc(nd.getTime());
  }

  // Absolute date/datetime end bound.
  const absMs = resolveAbsolute(trimmed);
  if (absMs !== null) {
    // Date-only → start of next day (exclusive end).  Datetime → use as-is.
    if (!/[Tt]/.test(trimmed)) return startOfNextDayUtc(absMs);
    return absMs;
  }
  // Explicit "<month|season> <year>" end bound (e.g. "until March 2025",
  // "through spring 2025"). The explicit year is authoritative, so the
  // exclusive end = start of the FOLLOWING month (for a single month) or the
  // start of the month AFTER the season ends (for a 3-month season).
  // Review r2: seasons previously advanced only 1 month, cutting off the
  // last 2 months of the season.
  const explicitMs = resolveExplicitMonthYear(trimmed);
  if (explicitMs !== null) {
    const nd = new Date(explicitMs);
    const firstWord = trimmed.toLowerCase().split(/\s+/)[0];
    const monthAdvance = firstWord in SEASON_TO_MONTH ? 3 : 1;
    nd.setUTCMonth(nd.getUTCMonth() + monthAdvance);
    return startOfDayUtc(nd.getTime());
  }

  // Period-name end bound: month → exclusive end at start of the FOLLOWING
  // month. "until <month>" is backwards-looking (the fact already stopped
  // being true), so prefer the most recent PAST boundary: build it in the
  // anchor year and roll back a year if that boundary is still future.
  const lower = trimmed.toLowerCase();
  const monthIdx = monthIndex(lower);
  if (typeof monthIdx === "number") {
    const d = new Date(anchorMs);
    const startMs = buildDateMs(d.getUTCFullYear(), monthIdx, 1);
    if (startMs === null) return null;
    // Exclusive end = start of the month AFTER the named month.
    const nd = new Date(startMs);
    nd.setUTCMonth(nd.getUTCMonth() + 1);
    let endMs = startOfDayUtc(nd.getTime());
    // Only roll back when the named month boundary is genuinely future
    // relative to the anchor cycle.  When the anchor IS in the named month,
    // the end of the current month is the right boundary — do not roll back
    // (cursor review r2: "until March" from mid-March returned the prior year).
    if (endMs > anchorMs && d.getUTCMonth() + 1 !== monthIdx) {
      nd.setUTCFullYear(nd.getUTCFullYear() - 1);
      endMs = startOfDayUtc(nd.getTime());
    }
    return endMs;
  }
  // Season end bound: advance by the full 3-month season.  Same
  // backwards-looking rollback logic as month names, but do not roll back
  // when the anchor is currently inside the season (codex review r2: bare
  // season end bounds like "until spring" / "through summer" returned null).
  const seasonMonth = SEASON_TO_MONTH[lower];
  if (typeof seasonMonth === "number") {
    const d = new Date(anchorMs);
    const anchorMonth = d.getUTCMonth() + 1;
    let year = d.getUTCFullYear();
    // Winter (Dec) from Jan/Feb: the current winter started in prev Dec,
    // so build the season start from the previous year (codex review r2:
    // bare winter end bounds used the anchor year's December, producing
    // an exclusive end one year too far forward).
    if (seasonMonth === 12 && anchorMonth <= 2) year -= 1;
    const startMs = buildDateMs(year, seasonMonth, 1);
    if (startMs === null) return null;
    const nd = new Date(startMs);
    nd.setUTCMonth(nd.getUTCMonth() + 3);
    let endMs = startOfDayUtc(nd.getTime());
    if (endMs > anchorMs && !isInSeason(seasonMonth, anchorMonth)) {
      nd.setUTCFullYear(nd.getUTCFullYear() - 1);
      endMs = startOfDayUtc(nd.getTime());
    }
    return endMs;
  }
  if (lower === "year") {
    const d = new Date(anchorMs);
    return buildDateMs(d.getUTCFullYear() + 1, 1, 1);
  }
  return null;
}

/**
 * Resolved bi-temporal fields for a single extracted fact (issue #1578 PR2).
 *
 * - `validFrom` / `validUntil` — the event-time `[from, until)` interval.
 *   When `eventTimeSource === "assumed"`, `validFrom` is copied from
 *   `observedAt` (the ingestion anchor) so every bi-temporal-on fact carries
 *   at least a start bound.
 * - `observedAt` — always the ingestion anchor (the source turn timestamp).
 * - `eventTimeSource` — `"extracted"` when the expression resolved to a real
 *   event-time interval; `"assumed"` when the expression was absent or
 *   unresolvable.
 *
 * This is the single write-time helper every extraction entry path calls
 * (rule 39). It is pure: (expression, anchor) in, interval out. Resolution
 * never touches `Date.now()` — replay/import of old transcripts resolves
 * against the old anchor.
 */
export interface FactEventTime {
  validFrom?: string;
  validUntil?: string;
  observedAt: string;
  eventTimeSource: "extracted" | "assumed";
}

/**
 * Resolve a single fact's event-time expression against the ingestion anchor.
 *
 * Returns the bi-temporal interval to persist alongside the fact. When the
 * expression is absent, empty, or unresolvable, falls back to
 * `eventTimeSource: "assumed"` with `validFrom = observedAt` — per the
 * #1578 frontmatter contract. When the expression resolves but only pins one
 * bound ("since 2024" → validFrom only; "until 2025-06" → validUntil only),
 * only the resolved bound is returned.
 */
export function resolveFactEventTime(
  expression: string | undefined | null,
  anchorIso: string,
): FactEventTime {
  const resolved = resolveEventTime(expression, anchorIso);
  if (resolved.ok && (resolved.validFrom !== undefined || resolved.validUntil !== undefined)) {
    return {
      ...(resolved.validFrom !== undefined ? { validFrom: resolved.validFrom } : {}),
      ...(resolved.validUntil !== undefined ? { validUntil: resolved.validUntil } : {}),
      observedAt: anchorIso,
      eventTimeSource: "extracted",
    };
  }
  return {
    validFrom: anchorIso,
    observedAt: anchorIso,
    eventTimeSource: "assumed",
  };
}

/**
 * Input shape for {@link pickFactEventTimeAnchor} — a structural slice of
 * `ExtractedFact` so the helper stays decoupled from the full type.
 */
export interface FactAnchorInput {
  /** Explicit per-fact source-turn timestamp (#1670). */
  sourceTurnTimestamp?: string;
  /** Claim-level provenance spans (#1575), each carrying the turn's `observedAt`. */
  sources?: { observedAt: string }[];
}

/**
 * Issue #1670 — select the per-fact event-time anchor.
 *
 * Prefers the fact's explicit `sourceTurnTimestamp` (set by extractors that
 * know the exact source turn). Falls back to the earliest provenance span's
 * `observedAt` (the turn where the supporting quote was located). Finally
 * falls back to the batch-wide anchor (latest source turn timestamp) when
 * neither per-fact signal is present — preserving legacy behaviour for
 * extractors that do not emit provenance.
 *
 * The earliest provenance span wins because a fact backed by quotes from
 * multiple turns was *first* uttered at the earliest turn: a relative
 * expression ("yesterday") on that fact should resolve against that turn,
 * not a later turn that merely restated the claim.
 *
 * Returns `undefined` only when no signal is usable AND `batchAnchor` is
 * absent — in which case the caller skips bi-temporal resolution entirely
 * (identical to the pre-feature pipeline when biTemporal is off).
 */
export function pickFactEventTimeAnchor(
  fact: FactAnchorInput,
  batchAnchor: string | undefined,
): string | undefined {
  // 1. Explicit per-fact source-turn timestamp (highest priority).
  if (
    typeof fact.sourceTurnTimestamp === "string" &&
    fact.sourceTurnTimestamp.trim().length > 0
  ) {
    const ms = parseFlexibleIsoTimestamp(fact.sourceTurnTimestamp.trim());
    if (ms !== null) return new Date(ms).toISOString();
  }
  // 2. Earliest provenance span turn timestamp.
  if (fact.sources && fact.sources.length > 0) {
    let earliestMs: number | null = null;
    for (const src of fact.sources) {
      if (typeof src.observedAt !== "string") continue;
      const ms = parseFlexibleIsoTimestamp(src.observedAt.trim());
      if (ms === null) continue;
      if (earliestMs === null || ms < earliestMs) earliestMs = ms;
    }
    if (earliestMs !== null) return new Date(earliestMs).toISOString();
  }
  // 3. Batch-wide anchor (legacy fallback).
  return batchAnchor;
}

/**
 * Local Importance Scoring (Phase 1B)
 *
 * Zero-LLM heuristic system that evaluates each memory's significance.
 * Analyzes content for markers like explicit importance statements,
 * personal information, instructions, emotional content, and factual density.
 */

import type { ImportanceLevel, ImportanceScore, MemoryCategory, MemoryFile } from "./types.js";
import { cjkBigrams, hasLatinWord, informationalLength } from "./utils/script-aware-text.js";

// ---------------------------------------------------------------------------
// Marker patterns for each tier
// ---------------------------------------------------------------------------

/** Critical importance markers (0.9-1.0) */
const CRITICAL_PATTERNS = [
  // Explicit importance
  /\b(critical|crucial|essential|must|always|never)\b/i,
  /\b(important|remember this|don't forget)\b/i,
  // Personal identity
  /\b(my name is|i am|i'm called)\b/i,
  /\b(my (birthday|phone|email|address|ssn|password))\b/i,
  // Strong preferences
  /\b(i (hate|love|despise|adore))\b/i,
  /\b(absolutely|definitely|certainly) (not|must|should)\b/i,
  // Corrections (high weight)
  /\b(actually|no,? that's wrong|correction:?|let me correct)\b/i,
  /\b(i said|i meant|i was wrong)\b/i,
];

/** High importance markers (0.7-0.9) */
const HIGH_PATTERNS = [
  // Decisions
  /\b(decided|decision|chose|choosing|picked|selected)\b/i,
  /\b(we('ll| will) (go with|use|implement))\b/i,
  // Instructions
  /\b(make sure|ensure|always|don't|do not|never|avoid)\b/i,
  /\b(you (should|must|need to))\b/i,
  // Temporal references (deadlines, schedules)
  /\b(by (monday|tuesday|wednesday|thursday|friday|saturday|sunday))\b/i,
  /\b(deadline|due (date|by)|by (end of|next))\b/i,
  /\b(tomorrow|next week|this week|today)\b/i,
  // Preferences
  /\b(i (prefer|like|want|need|dislike))\b/i,
  /\b(my (preference|style|approach|way))\b/i,
  // Commitments
  /\b(i('ll| will)|promise|commit|guarantee)\b/i,
  /\b(scheduled|appointment|meeting|call)\b/i,
];


/** Low importance markers (0.2-0.4) */
const LOW_PATTERNS = [
  // Uncertainty
  /\b(maybe|perhaps|possibly|might|could be)\b/i,
  /\b(i think|i guess|not sure|uncertain)\b/i,
  /\b(probably|likely|seems like)\b/i,
  // Hedging
  /\b(kind of|sort of|somewhat|a bit)\b/i,
  /\b(in a way|to some extent)\b/i,
];

/** Trivial content markers (0.0-0.2) */
const TRIVIAL_PATTERNS = [
  // Greetings and filler
  /^(hi|hello|hey|yo|sup|greetings)[.!,]?\s*$/i,
  /^(ok|okay|k|sure|yes|no|yep|nope|yeah|nah)[.!]?\s*$/i,
  /^(thanks|thank you|thx|ty|cheers)[.!]?\s*$/i,
  /^(got it|understood|roger|copy|noted)[.!]?\s*$/i,
  /^(bye|goodbye|later|see ya|ttyl)[.!]?\s*$/i,
  /^(lol|haha|hehe|lmao|rofl)[.!]?\s*$/i,
  /^(hmm+|uhh*|ahh*|err*|umm*)[.!]?\s*$/i,
];

// ---------------------------------------------------------------------------
// Category-based importance boosts
// ---------------------------------------------------------------------------

const CATEGORY_BOOSTS: Record<MemoryCategory, number> = {
  correction: 0.15,        // Corrections are always important
  principle: 0.12,         // Durable rules/values
  rule: 0.11,              // Causal IF→THEN rules
  procedure: 0.10,         // Repeatable workflows (issue #519)
  preference: 0.10,        // User preferences matter
  commitment: 0.10,        // Promises/obligations
  reasoning_trace: 0.09,   // Stored reasoning chains (issue #564)
  decision: 0.08,          // Decisions with rationale
  relationship: 0.05,      // Entity relationships
  skill: 0.05,             // Capabilities
  moment: 0.03,            // Emotional milestones
  entity: 0.02,            // Entity facts
  fact: 0.00,              // Base facts, no boost
};

// ---------------------------------------------------------------------------
// Keyword extraction
// ---------------------------------------------------------------------------

/** Common stop words to filter out */
const STOP_WORDS = new Set([
  "a", "an", "the", "is", "are", "was", "were", "be", "been", "being",
  "have", "has", "had", "do", "does", "did", "will", "would", "could",
  "should", "may", "might", "must", "shall", "can", "need", "dare",
  "ought", "used", "to", "of", "in", "for", "on", "with", "at", "by",
  "from", "as", "into", "through", "during", "before", "after", "above",
  "below", "between", "under", "again", "further", "then", "once",
  "here", "there", "when", "where", "why", "how", "all", "each", "few",
  "more", "most", "other", "some", "such", "no", "nor", "not", "only",
  "own", "same", "so", "than", "too", "very", "just", "and", "but",
  "or", "if", "because", "until", "while", "this", "that", "these",
  "those", "i", "me", "my", "myself", "we", "our", "ours", "ourselves",
  "you", "your", "yours", "yourself", "yourselves", "he", "him", "his",
  "himself", "she", "her", "hers", "herself", "it", "its", "itself",
  "they", "them", "their", "theirs", "themselves", "what", "which",
  "who", "whom", "whose", "am", "been", "being", "about", "against",
]);

/**
 * Extract salient keywords from content.
 * Returns top N keywords sorted by relevance.
 */
function extractKeywords(content: string, maxKeywords: number = 5): string[] {
  // Latin words plus CJK bigrams, so non-Latin content still yields
  // keywords (pure-CJK prose returned none before #2192).
  const candidates = [
    ...content
      .toLowerCase()
      .replace(/[^a-z0-9\s-]/g, " ")
      .split(/\s+/)
      .filter((w) => w.length >= 3 && !STOP_WORDS.has(w)),
    ...cjkBigrams(content),
  ];

  // Count frequencies
  const freq = new Map<string, number>();
  for (const word of candidates) {
    freq.set(word, (freq.get(word) ?? 0) + 1);
  }

  // Sort by frequency, take top N
  return [...freq.entries()]
    .sort((a, b) => b[1] - a[1])
    .slice(0, maxKeywords)
    .map(([word]) => word);
}

// ---------------------------------------------------------------------------
// Main scoring function
// ---------------------------------------------------------------------------

/**
 * Calculate importance score for a memory.
 * Pure local heuristics, zero LLM calls.
 */
export function scoreImportance(
  content: string,
  category: MemoryCategory,
  tags: string[] = [],
): ImportanceScore {
  const reasons: string[] = [];
  let score = 0.5; // Start at normal baseline

  const contentLength = content.length;

  // Check for trivial content first (short-circuit)
  for (const pattern of TRIVIAL_PATTERNS) {
    if (pattern.test(content)) {
      return {
        score: 0.1,
        level: "trivial",
        reasons: ["Trivial content (greeting, filler, or very short)"],
        keywords: [],
      };
    }
  }

  // Very short content. informationalLength weights CJK/Hangul 3:1, so a
  // dense non-Latin sentence ("予約しました") is not trivial for being
  // under 10 raw characters while its English equivalent is not (#2192).
  const weightedLength = informationalLength(content);
  if (weightedLength >= 1 && weightedLength <= 10) {
    return {
      score: 0.1,
      level: "trivial",
      reasons: ["Trivial content (greeting, filler, or very short)"],
      keywords: [],
    };
  }

  // Documented non-Latin fallback (#2192): the English keyword tiers below
  // cannot fire without Latin words, so the score rests on the 0.5 baseline
  // plus script-agnostic signals (category boost, length, digits, tags).
  if (!hasLatinWord(content)) {
    reasons.push("Non-Latin script: keyword tiers not applicable; script-agnostic signals only");
  }

  // Check critical patterns
  for (const pattern of CRITICAL_PATTERNS) {
    if (pattern.test(content)) {
      score += 0.20;
      reasons.push(`Critical marker: ${pattern.source.slice(0, 30)}`);
      break; // Only count once per tier
    }
  }

  // Check high patterns
  for (const pattern of HIGH_PATTERNS) {
    if (pattern.test(content)) {
      score += 0.12;
      reasons.push(`High importance marker detected`);
      break;
    }
  }

  // Check low patterns (reduces score)
  for (const pattern of LOW_PATTERNS) {
    if (pattern.test(content)) {
      score -= 0.15;
      reasons.push(`Uncertainty/hedging detected`);
      break;
    }
  }

  // Category boost
  const categoryBoost = CATEGORY_BOOSTS[category] ?? 0;
  if (categoryBoost > 0) {
    score += categoryBoost;
    reasons.push(`Category boost: ${category}`);
  }

  // Length bonus (longer = more substance, capped)
  if (contentLength > 200) {
    const lengthBonus = Math.min((contentLength - 200) / 1000, 0.1);
    score += lengthBonus;
    if (lengthBonus > 0.05) {
      reasons.push("Substantial content length");
    }
  }

  // Check for personal pronouns (signals personal relevance)
  if (/\b(my|mine|i|i'm|i've|i'd|i'll)\b/i.test(content)) {
    score += 0.05;
    reasons.push("Personal reference");
  }

  // Check for numbers/specifics (concrete details)
  if (/\b\d{2,}\b/.test(content) || /\b(version|v\d|api|config)\b/i.test(content)) {
    score += 0.03;
    reasons.push("Contains specific details");
  }

  // Tag-based boosts
  const importantTags = tags.filter((t) =>
    ["important", "critical", "preference", "decision", "rule", "principle"].includes(t.toLowerCase())
  );
  if (importantTags.length > 0) {
    score += 0.05 * importantTags.length;
    reasons.push(`Important tags: ${importantTags.join(", ")}`);
  }

  // Clamp score to 0-1 range
  score = Math.max(0, Math.min(1, score));

  // Determine level from score
  let level: ImportanceLevel;
  if (score >= 0.9) {
    level = "critical";
  } else if (score >= 0.7) {
    level = "high";
  } else if (score >= 0.4) {
    level = "normal";
  } else if (score >= 0.2) {
    level = "low";
  } else {
    level = "trivial";
  }

  // Extract keywords
  const keywords = extractKeywords(content);

  return {
    score: Math.round(score * 100) / 100, // Round to 2 decimal places
    level,
    reasons: reasons.slice(0, 5), // Cap at 5 reasons
    keywords,
  };
}

/**
 * Recompute importance for an existing memory file using current local heuristics.
 */
export function rescoreMemoryImportance(memory: MemoryFile): ImportanceScore {
  return scoreImportance(memory.content, memory.frontmatter.category, memory.frontmatter.tags ?? []);
}

/**
 * Get importance level from numeric score.
 */
export function importanceLevel(score: number): ImportanceLevel {
  if (score >= 0.9) return "critical";
  if (score >= 0.7) return "high";
  if (score >= 0.4) return "normal";
  if (score >= 0.2) return "low";
  return "trivial";
}

// ---------------------------------------------------------------------------
// Importance threshold helper (issue #372)
// ---------------------------------------------------------------------------

/**
 * Ordering for importance levels used by the extraction write gate.
 * Higher indices mean more important.
 */
const IMPORTANCE_LEVEL_RANK: Record<ImportanceLevel, number> = {
  trivial: 0,
  low: 1,
  normal: 2,
  high: 3,
  critical: 4,
};

/**
 * Return true if `candidate` meets or exceeds `threshold`. Used by the
 * extraction write gate in orchestrator.persistExtraction() to drop trivial
 * content before it is written to the memory store.
 *
 * Note: callers should pass the ALREADY-BOOSTED level returned by
 * scoreImportance(), because category boosts (e.g. corrections) are applied
 * inside scoreImportance() before the level is derived.
 */
export function isAboveImportanceThreshold(
  candidate: ImportanceLevel,
  threshold: ImportanceLevel,
): boolean {
  return IMPORTANCE_LEVEL_RANK[candidate] >= IMPORTANCE_LEVEL_RANK[threshold];
}

import { createHash } from "node:crypto";
import type { BehaviorSignalEvent, MemoryCategory } from "./types.js";

function normalizeSignalText(input: string): string {
  return input.replace(/\s+/g, " ").trim().toLowerCase();
}

export function buildBehaviorSignalHash(category: MemoryCategory, content: string): string {
  const normalized = `${category}:${normalizeSignalText(content)}`;
  return createHash("sha256").update(normalized).digest("hex").slice(0, 16);
}

export function buildBehaviorSignalsForMemory(input: {
  memoryId: string;
  category: MemoryCategory;
  content: string;
  namespace: string;
  confidence: number;
  timestamp?: string;
  source?: "extraction" | "correction";
}): BehaviorSignalEvent[] {
  const timestamp = input.timestamp ?? new Date().toISOString();
  const signalHash = buildBehaviorSignalHash(input.category, input.content);
  const source = input.source ?? "extraction";

  if (input.category === "correction") {
    return [
      {
        timestamp,
        namespace: input.namespace,
        memoryId: input.memoryId,
        category: "correction",
        signalType: "correction_override",
        direction: "negative",
        confidence: input.confidence,
        signalHash,
        source,
      },
    ];
  }

  if (input.category === "preference") {
    return [
      {
        timestamp,
        namespace: input.namespace,
        memoryId: input.memoryId,
        category: "preference",
        signalType: "preference_affinity",
        direction: "positive",
        confidence: input.confidence,
        signalHash,
        source,
      },
    ];
  }

  return [];
}

export function dedupeBehaviorSignalsByMemoryAndHash(
  signals: BehaviorSignalEvent[],
): BehaviorSignalEvent[] {
  const seen = new Set<string>();
  const out: BehaviorSignalEvent[] = [];
  for (const signal of signals) {
    const key = `${signal.namespace}:${signal.memoryId}:${signal.signalHash}`;
    if (seen.has(key)) continue;
    seen.add(key);
    out.push(signal);
  }
  return out;
}

/**
 * extraction-redaction-rules.ts — consults persisted correction redaction
 * rules during the extraction→persist path so a `never_store` / redaction_rule
 * correction actually blocks future extraction of matching content (issue
 * #1669, #1580 follow-up).
 *
 * The Correction Contract persists `redaction_rule` patterns to
 * `<storage>/state/corrections/redaction-rules/<slug>.json` (one file per
 * rule, idempotent on pattern). This module reads those patterns at the start
 * of each extraction persist pass and exposes a pure matcher the orchestrator
 * consults BEFORE a fact reaches the storage write chokepoint — mirroring how
 * tombstones are consulted at the write chokepoint (#1579), but one stage
 * earlier so the content never even lands as `pending_review`.
 *
 * Scope (issue #1669): the extraction layer consults the rules. Persistence
 * stays owned by the correction module. This helper is the read surface.
 *
 * Safety: patterns are validated at correction-apply time
 * (`validateRedactionPattern` — bounded literal/safe-regex, no catastrophic
 * shapes). We compile defensively here too: a pattern that fails to compile
 * as a regex is treated as a literal substring, and any matcher error is
 * swallowed (fail-open to "no match") so a malformed rule can never block the
 * entire extraction pipeline.
 */
import { readdir, readFile } from "node:fs/promises";
import path from "node:path";

/**
 * Directory (relative to a namespace storage dir) where redaction rules live.
 * Kept in sync with `registerRedactionRuleFn` in correction-access-wiring.ts.
 */
export const REDACTION_RULES_SUBDIR = path.join("state", "corrections", "redaction-rules");

/** Maximum number of rule files read per pass (defense in depth). */
const MAX_RULE_FILES = 256;

/**
 * A compiled redaction rule. `pattern` is the original (validated) pattern;
 * `matcher` returns true when content should be withheld.
 */
export interface CompiledRedactionRule {
  pattern: string;
  matcher: (content: string) => boolean;
}

/** Shape persisted by `registerRedactionRuleFn`. */
interface RedactionRuleFile {
  pattern: string;
  namespace?: string;
  createdAt?: string;
}

/**
 * Only `/…/`-wrapped patterns compile as RegExp; everything else is a literal
 * substring (review thread P1). An unwrapped pattern like `abc+def` must match
 * the literal string `abc+def`, NOT the regex `abccccdef`.
 */
function isRegexLike(pattern: string): boolean {
  return pattern.startsWith("/") && pattern.endsWith("/") && pattern.length >= 2;
}

/**
 * Reject patterns prone to catastrophic backtracking (ReDoS, review thread #3).
 * Mirrors the safe-regex heuristic: a quantifier inside a group that is itself
 * quantified creates exponential blowup on near-miss inputs. Also rejects
 * patterns with overlapping alternation under repetition
 * (e.g. (a|a)*). Returns true when the pattern is safe to compile.
 *
 * This is a second line of defense — validateRedactionPattern runs first at
 * apply time, but a hand-edited rule file or an edge case can still slip past.
 */
function isSafeRegex(source: string): boolean {
  if (source.length === 0 || source.length > 512) return false;
  // Reject overly-broad patterns (.*) that would match every fact and
  // withhold all extraction (cursor Bugbot thread — mirrors
  // isUnsafeRedactionRegex in correction-contract.ts).
  if (/(?:^|[^\\])\(\.\*\)|(?:^|[^\\])\.\*|(?:^|[^\\])\.\+|^\.([^*+]?)$/.test(source)) {
    return false;
  }
  // group body itself ends with a quantifier. This catches (a+)+, (a*)*, etc.
  // Also catches overlapping alternation like (a|a)+.
  for (let i = 0; i < source.length; i++) {
    if (source[i] !== "(") continue;
    // Find the matching close paren
    let depth = 1;
    let j = i + 1;
    while (j < source.length && depth > 0) {
      if (source[j] === "\\") { j += 2; continue; }
      if (source[j] === "(") depth++;
      else if (source[j] === ")") depth--;
      j++;
    }
    if (depth !== 0) continue; // unbalanced — will fail RegExp compile anyway
    // Check if the char after the closing paren is a quantifier
    const afterGroup = source[j];
    if (afterGroup !== "+" && afterGroup !== "*" && afterGroup !== "{") continue;
    const groupBody = source.slice(i + 1, j - 1);
    // The group body ends with a quantifier on a non-escape char
    if (/[+*?]$/.test(groupBody) || /\{\d+,?\d*\}[+*?]?$/.test(groupBody)) {
      // Nested quantifier → potential ReDoS
      return false;
    }
    // Overlapping alternation: (a|a)+ where branches share a common prefix
    if (groupBody.includes("|")) {
      const branches = groupBody.split("|");
      if (branches.length >= 2) {
        const firstChars = new Set(branches.map((b) => b[0]).filter(Boolean));
        if (firstChars.size < branches.filter((b) => b.length > 0).length) {
          return false;
        }
      }
    }
    i = j;
  }
  return true;
}

/**
 * Compile a single pattern into a matcher. A literal pattern matches by
 * case-sensitive substring; a `/…/`-wrapped pattern compiles into a RegExp
 * anchored to search (global flag off — we only need a boolean). Compilation
 * failures fall back to literal substring so a bad pattern never throws here.
 */
export function compileRedactionPattern(pattern: string): CompiledRedactionRule {
  const trimmed = pattern.trim();
  if (!isRegexLike(trimmed)) {
    return { pattern: trimmed, matcher: (content) => content.includes(trimmed) };
  }
  const body = trimmed.slice(1, -1);
  try {
    if (!isSafeRegex(body)) {
      if (body.length === 0) return { pattern: trimmed, matcher: () => false };
      return { pattern: trimmed, matcher: (content) => content.includes(body) };
    }
    const re = new RegExp(body);
    if (re.test("")) {
      // Zero-width regex matches every string — would withhold all extraction.
      return { pattern: trimmed, matcher: (content) => content.includes(body) };
    }
    return { pattern: trimmed, matcher: (content) => re.test(content) };
  } catch {
    // Malformed regex despite validation (e.g. rule file hand-edited) —
    // treat as a literal on the BODY so the rule still does something useful.
    return { pattern: trimmed, matcher: (content) => content.includes(body) };
  }
}

/**
 * Load + compile every redaction rule persisted under a namespace's storage
 * dir. Returns an empty array when the directory is absent or unreadable
 * (fail-open — a missing or corrupt rules dir must never block extraction).
 */
export async function loadRedactionRules(stateDir: string): Promise<CompiledRedactionRule[]> {
  const dir = path.join(stateDir, REDACTION_RULES_SUBDIR);
  let names: string[];
  try {
    names = await readdir(dir);
  } catch {
    // ENOENT (cold install, no rules yet) or permission error — no rules.
    return [];
  }
  // Sort deterministically (alphabetical by filename) so the set of rules
  // that survives the MAX_RULE_FILES cap is NOT filesystem-dependent (review
  // thread P2). Without this, readdir order varies by OS/FS and the silently
  // truncated rules are arbitrary — a never-store pattern could be dropped.
  const jsonFiles = names.filter((n) => n.endsWith(".json")).sort();
  if (jsonFiles.length > MAX_RULE_FILES) {
    // Visible failure mode: log a warning so the operator knows rules were
    // truncated, rather than silently dropping enforcement.
    console.warn(
      `extraction-redaction: ${jsonFiles.length} redaction rules in ${dir} exceed the ${MAX_RULE_FILES} cap; ` +
      `${jsonFiles.length - MAX_RULE_FILES} rules will NOT be enforced. Remove unused rules or raise the cap.`,
    );
  }
  const rules: CompiledRedactionRule[] = [];
  for (const name of jsonFiles.slice(0, MAX_RULE_FILES)) {
    try {
      const raw = await readFile(path.join(dir, name), "utf-8");
      const parsed = JSON.parse(raw) as RedactionRuleFile;
      if (typeof parsed?.pattern !== "string" || parsed.pattern.trim().length === 0) continue;
      rules.push(compileRedactionPattern(parsed.pattern));
    } catch {
      // Skip a corrupt rule file rather than failing the pass (rule 34 —
      // visible skip, never a silent pipeline block).
    }
  }
  return rules;
}

/**
 * Test content against a set of compiled rules. Returns true if ANY rule
 * matches (the content should be withheld). An empty rule set never matches.
 */
export function contentMatchesRedactionRules(
  content: string,
  rules: readonly CompiledRedactionRule[],
): boolean {
  for (const rule of rules) {
    try {
      if (rule.matcher(content)) return true;
    } catch {
      // A matcher should not throw (compilation already fell back), but if a
      // RegExp blows up on pathological input we skip that rule rather than
      // failing the whole gate.
    }
  }
  return false;
}

/**
 * HiMem — Episode/Note dual store (v8.0 Phase 2B)
 *
 * Classifies extracted memories as:
 *   episode — time-specific events, actions, observations (event fidelity)
 *   note    — stable beliefs, preferences, decisions, constraints
 *
 * Based on the HiMem paper: episodes are ephemeral, notes are reconsolidated
 * into a stable belief layer. This classification gates reconsolidation.
 */

export type MemoryKind = "episode" | "note";

/**
 * Keywords that signal a stable belief/preference/constraint.
 * Includes present and past tense to catch extraction phrasing like
 * "user preferred X" or "team needed Y".
 */
const NOTE_SIGNALS = [
  /\bprefer(?:red|s|ring)?\b/i,
  /\bwant(?:ed|s|ing)?\b/i,
  /\bneed(?:ed|s|ing)?\b/i,
  /\balways\b/i,
  /\bnever\b/i,
  /\bmust\b/i,
  /\bshould\b/i,
  /\bgoals?\b/i,
  /\bdecid(?:ed|es|e|ing)\b/i,
  /\bpolic(?:y|ies)\b/i,
  /\brequir(?:ed|es?|ements?|ing)\b/i,
  /\bconstraints?\b/i,
  /\bstandards?\b/i,
  /\bconventions?\b/i,
];

/**
 * Unambiguous date/time markers — checked at step 1 (highest priority) before
 * category overrides.  Only include signals that cannot appear in stable-belief
 * sentences (e.g. "today I prefer…" is contrived; "yesterday" in a preference
 * is almost always a past event).
 *
 * Note: "just" excluded — it too often means "merely/only".
 */
const TEMPORAL_SIGNALS = [
  /\byesterday\b/i,
  /\btoday\b/i,
  /\blast\s+(?:week|month|year|Monday|Tuesday|Wednesday|Thursday|Friday|Saturday|Sunday)\b/i,
  /\bon\s+(?:Monday|Tuesday|Wednesday|Thursday|Friday|Saturday|Sunday)\b/i,
  /\b(?:recently|earlier|this morning|this afternoon)\b/i,
];

/**
 * Past-tense action verbs that suggest an episodic memory.
 * Checked AFTER category overrides (step 3.5) to avoid misclassifying
 * stable-knowledge sentences like "User mentioned they always prefer X"
 * where category="preference" should win over the verb "mentioned".
 */
const VERB_EPISODE_SIGNALS = [
  /\bdeployed\b/i,
  /\bpushed\b/i,
  /\bfixed\b/i,
  /\bmerged\b/i,
  /\breported\b/i,
  /\bmentioned\b/i,
  /\bsaid\b/i,
  /\bhappened\b/i,
  /\bfailed\b/i,
  /\bcompleted\b/i,
  /\bshipped\b/i,
];

/** Category names that strongly suggest a note (stable belief) */
const NOTE_CATEGORIES = new Set([
  "preference",
  "constraint",
  "goal",
  "habit",
  "policy",
  "standard",
  "belief",
  "decision",
  "principle",     // durable operating rules emitted by extraction
  "commitment",    // deadlines/promises — stable obligations
  "relationship",  // durable facts about people/entities
  "skill",         // capabilities — stable knowledge
  "correction",    // user corrections — durable override of prior belief
  "entity",        // stable facts about people, projects, tools, etc.
]);

/** Category names that strongly suggest an episode */
const EPISODE_CATEGORIES = new Set(["event", "action", "observation", "issue", "bug", "incident", "moment"]);

/** Tag values that signal a stable belief */
const NOTE_TAGS = new Set(["preference", "constraint", "goal", "habit", "policy", "belief"]);

/** Tag values that signal a time-specific event */
const EPISODE_TAGS = new Set(["bug", "fix", "deploy", "incident", "release", "merge", "event"]);

/**
 * Classify a memory fact as "episode" (time-specific event) or "note"
 * (stable belief/preference/decision).
 *
 * @param content   - The memory's text content
 * @param tags      - Tags from extraction (checked for episode/note signals)
 * @param category  - Category from extraction
 * @returns "episode" | "note"
 */
export function classifyMemoryKind(
  content: string,
  tags: string[],
  category: string,
): MemoryKind {
  const lowerContent = content.toLowerCase();
  const lowerCategory = category.toLowerCase();

  // 1. True temporal markers — unambiguous date/time references override everything.
  //    These are safe at highest priority because genuine date/time phrases cannot
  //    appear in a stable-belief sentence without making it episodic.
  for (const re of TEMPORAL_SIGNALS) {
    if (re.test(lowerContent)) return "episode";
  }

  // 2. Category-level override — strong semantic signal from extraction
  if (NOTE_CATEGORIES.has(lowerCategory)) return "note";
  if (EPISODE_CATEGORIES.has(lowerCategory)) return "episode";

  // 3. Tag-level signals — lower priority than category; note tags win over episode tags
  //    to avoid non-deterministic results when tag order varies across LLM runs.
  let tagMatchesNote = false;
  let tagMatchesEpisode = false;
  for (const tag of tags) {
    const lowerTag = tag.toLowerCase();
    if (NOTE_TAGS.has(lowerTag)) tagMatchesNote = true;
    if (EPISODE_TAGS.has(lowerTag)) tagMatchesEpisode = true;
  }
  if (tagMatchesNote) return "note";
  if (tagMatchesEpisode) return "episode";

  // 3.5. Verb-based episode signals — run after category so that stable categories
  //      (preference, principle, etc.) are not overridden by common narrative verbs
  //      like "mentioned" or "said" (e.g. "User mentioned they always prefer X").
  for (const re of VERB_EPISODE_SIGNALS) {
    if (re.test(lowerContent)) return "episode";
  }

  // 4. Non-temporal note signals in content
  for (const re of NOTE_SIGNALS) {
    if (re.test(lowerContent)) return "note";
  }

  // 5. Default: episode (preserves fidelity, safer to not promote to stable note)
  return "episode";
}

/**
 * Memory subject: user-centric vs agent-centric classification (issue #2372).
 *
 * Scope says WHERE a memory lives; subject says WHOM it is about — and that
 * is what determines where it may safely go. `user` memories model one
 * person (preferences, relationships, biography, moments, commitments);
 * `agent` memories model how to operate (procedures, principles,
 * tool-usage lessons, debugging strategies, environment facts with no
 * personal content).
 *
 * This module owns, in one place:
 *  - the deterministic write-time classification (category defaults with an
 *    optional extractor override),
 *  - the promotion guard shared by EVERY promotion surface (spaces promote
 *    AND scope-profile promotion targets — AGENTS.md §27 uniform gating),
 *  - read-only promotion-candidate surfacing (reuse-signaled agent-subject
 *    memories with no equivalent in the target layer), and
 *  - the deterministic backfill pass (shadow/apply, no LLM).
 */

import { ContentHashIndex } from "./storage/content-hash-index.js";
import { sanitizeMemoryContent } from "./sanitize.js";
import type { McpTool } from "./access-mcp.js";
import type { MemoryCategory, MemoryFile, MemorySubject, SubjectGuardMode } from "./types.js";

export const SUBJECT_VALUES = ["user", "agent"] as const;
export const SUBJECT_GUARD_MODES = ["off", "warn", "enforce"] as const;

/** The CLI / per-call override that permits a user-subject promotion. */
export const SUBJECT_GUARD_OVERRIDE_FLAG = "--allow-user-subject";

export function isMemorySubject(value: unknown): value is MemorySubject {
  return value === "user" || value === "agent";
}

export function isSubjectGuardMode(value: unknown): value is SubjectGuardMode {
  return value === "off" || value === "warn" || value === "enforce";
}

// ---------------------------------------------------------------------------
// Write-time classification
// ---------------------------------------------------------------------------

/**
 * Deterministic category defaults (issue #2372 §1):
 *   user — preference, relationship, moment, commitment
 *   agent — procedure, principle, skill
 * Every other category has no default; the resolver falls back to `"user"`,
 * the most-restrictive value (Review Prevention Checklist §36 — an unsafe
 * enum default is never the convenient one).
 */
const SUBJECT_CATEGORY_DEFAULTS: Partial<Record<MemoryCategory, MemorySubject>> = {
  preference: "user",
  relationship: "user",
  moment: "user",
  commitment: "user",
  procedure: "agent",
  principle: "agent",
  skill: "agent",
};

export function subjectDefaultForCategory(category: MemoryCategory): MemorySubject {
  return SUBJECT_CATEGORY_DEFAULTS[category] ?? "user";
}

/**
 * Resolve the write-time subject: the extractor's single-token value when it
 * emitted a valid one, else the category default. Never reclassifies on read.
 */
export function resolveWriteSubject(
  category: MemoryCategory,
  extractorValue: unknown,
): MemorySubject {
  return isMemorySubject(extractorValue) ? extractorValue : subjectDefaultForCategory(category);
}

// ---------------------------------------------------------------------------
// Promotion guard (uniform across every promotion surface — §27)
// ---------------------------------------------------------------------------

/** Scope-profile promotion targets that are shared layers. */
export function isSharedPromotionTarget(target: string): boolean {
  return target === "teamProject" || target === "serverShared";
}

export interface SubjectGuardDecision {
  action: "allow" | "warn" | "reject";
  /** Effective subject — an absent subject resolves to "user" (fail closed, §36). */
  effectiveSubject: MemorySubject;
  /** Structured reason; empty string when action === "allow". */
  reason: string;
  /** The override that permits this promotion when action is reject/warn. */
  override: typeof SUBJECT_GUARD_OVERRIDE_FLAG;
}

/**
 * Evaluate one promotion against the subject guard. Shared by the spaces
 * promotion workflow and the scope-profile promotion targets so the two
 * surfaces cannot drift (issue #2372 acceptance 2, AGENTS.md §27).
 *
 *  - mode "off", non-shared targets, agent-subject memories, and explicit
 *    `allowUserSubject` overrides all allow.
 *  - a `user`-subject memory (or a memory with NO subject — fail closed)
 *    promoted to a shared layer warns under "warn" and rejects under
 *    "enforce", with the override named in the reason (§39: never a silent
 *    accept).
 */
export function evaluateSubjectGuard(params: {
  subject: MemorySubject | undefined;
  sharedTarget: boolean;
  mode: SubjectGuardMode;
  allowUserSubject?: boolean;
}): SubjectGuardDecision {
  const effectiveSubject = params.subject ?? "user";
  const base = { effectiveSubject, override: SUBJECT_GUARD_OVERRIDE_FLAG } as const;
  if (params.mode === "off" || !params.sharedTarget || effectiveSubject === "agent") {
    return { action: "allow", reason: "", ...base };
  }
  if (params.allowUserSubject === true) {
    return { action: "allow", reason: "user-subject promotion override accepted", ...base };
  }
  return {
    action: params.mode === "enforce" ? "reject" : "warn",
    reason:
      `subject=${effectiveSubject} memory targets a shared layer (team/server); ` +
      `user-subject memories model one person and must not be shared; ` +
      `override with ${SUBJECT_GUARD_OVERRIDE_FLAG} (allowUserSubject: true) if intended`,
    ...base,
  };
}

// ---------------------------------------------------------------------------
// Promotion candidates (read-only surfacing — no auto-promotion)
// ---------------------------------------------------------------------------

export type PromotionReuseSignal = "reinforcement" | "memory_worth" | "access_count";

export interface PromotionCandidate {
  id: string;
  path: string;
  category: MemoryCategory;
  content: string;
  accessCount: number;
  reinforcementCount: number;
  mwSuccess: number;
  mwFail: number;
  reuseSignal: PromotionReuseSignal;
}

/** Default reuse-signal threshold for `accessCount` (config `promotionCandidates.minAccessCount`). */
export const PROMOTION_CANDIDATES_DEFAULT_MIN_ACCESS = 3;

/** Canonical content form for target-equivalence checks (same normalize pipeline as dedup). */
export function promotionCandidateKey(content: string): string {
  return ContentHashIndex.normalizeContent(sanitizeMemoryContent(content).text);
}

/**
 * List `subject: "agent"` memories that (a) are active, (b) show a reuse
 * signal (`reinforcement_count > 0` OR `mw_success > mw_fail` OR
 * `accessCount >= minAccessCount`), and (c) have no equivalent already in
 * the promotion target layer (content-hash check via the dedup normalizer).
 * Pure over the two memory lists; callers resolve namespaces.
 */
export function computePromotionCandidates(options: {
  memories: MemoryFile[];
  targetMemories: MemoryFile[];
  minAccessCount: number;
  limit?: number;
}): PromotionCandidate[] {
  if (!Number.isFinite(options.minAccessCount) || options.minAccessCount < 0) {
    throw new Error(
      `computePromotionCandidates: minAccessCount must be a non-negative number (got ${String(options.minAccessCount)})`,
    );
  }
  const targetKeys = new Set(
    options.targetMemories.map((m) => promotionCandidateKey(m.content ?? "")),
  );
  const out: PromotionCandidate[] = [];
  for (const memory of options.memories) {
    const fm = memory.frontmatter;
    if (fm.subject !== "agent") continue;
    if ((fm.status ?? "active") !== "active") continue;
    const reinforcementCount = fm.reinforcement_count ?? 0;
    const mwSuccess = fm.mw_success ?? 0;
    const mwFail = fm.mw_fail ?? 0;
    const accessCount = fm.accessCount ?? 0;
    let reuseSignal: PromotionReuseSignal | undefined;
    if (reinforcementCount > 0) reuseSignal = "reinforcement";
    else if (mwSuccess > mwFail) reuseSignal = "memory_worth";
    else if (accessCount >= options.minAccessCount) reuseSignal = "access_count";
    if (reuseSignal === undefined) continue;
    if (targetKeys.has(promotionCandidateKey(memory.content ?? ""))) continue;
    out.push({
      id: fm.id,
      path: memory.path,
      category: fm.category,
      content: memory.content ?? "",

      accessCount,
      reinforcementCount,
      mwSuccess,
      mwFail,
      reuseSignal,
    });
    if (options.limit !== undefined && out.length >= options.limit) break;
  }
  return out;
}

export interface PromotionCandidatesResult {
  namespace: string;
  targetNamespace: string;
  minAccessCount: number;
  candidates: PromotionCandidate[];
}

export const PROMOTION_CANDIDATES_MCP_TOOLS: McpTool[] = [
  {
