// ---------------------------------------------------------------------------
// Backfill (governance shadow/apply — deterministic rules only, no LLM)
// ---------------------------------------------------------------------------

/**
 * Storage surface the backfill needs (mirrors pattern-reinforcement's
 * structural interface so tests can pass an in-memory stub).
 * `writeMemoryFrontmatter` invalidates caches and syncs the fact-hash index
 * (§25/§31), so a stamped memory is immediately discoverable.
 */
export interface SubjectBackfillStorage {
  readAllMemories(): Promise<MemoryFile[]>;
  writeMemoryFrontmatter(memory: MemoryFile, patch: Partial<MemoryFile["frontmatter"]>): Promise<boolean>;
}

export interface SubjectBackfillReport {
  mode: "shadow" | "apply";
  scanned: number;
  stamped: number;
  alreadyStamped: number;
  stamps: Array<{
    id: string;
    category: MemoryCategory;
    subject: MemorySubject;
    path: string;
  }>;
}

/**
 * Stamp `subject` on memories that have none, using ONLY the deterministic
 * category defaults (never an LLM, never reclassifying an existing subject —
 * issue #2372 §1.3). `shadow` reports the intended stamps without writing;
 * `apply` writes through `writeMemoryFrontmatter`, which invalidates the
 * memory caches and re-syncs the fact-hash index.
 */
export async function backfillMemorySubjects(options: {
  storage: SubjectBackfillStorage;
  mode: "shadow" | "apply";
}): Promise<SubjectBackfillReport> {
  const memories = await options.storage.readAllMemories();
  const report: SubjectBackfillReport = {
    mode: options.mode,
    scanned: memories.length,
    stamped: 0,
    alreadyStamped: 0,
    stamps: [],
  };
  for (const memory of memories) {
    if (memory.frontmatter.subject !== undefined) {
      report.alreadyStamped++;
      continue;
    }
    const subject = subjectDefaultForCategory(memory.frontmatter.category);
    report.stamps.push({
      id: memory.frontmatter.id,
      category: memory.frontmatter.category,
      subject,
      path: memory.path,
    });
    if (options.mode === "apply") {
      await options.storage.writeMemoryFrontmatter(memory, { subject });
    }
    report.stamped++;
  }
  return report;
}

/**
 * @remnic/core — Write-time semantic dedup guard
 *
 * Complements the exact content-hash check in the orchestrator's write path
 * by detecting near-duplicate candidate facts via embedding cosine similarity.
 *
 * The module intentionally has no dependency on the EmbeddingFallback or QMD
 * classes directly — callers pass in a `lookup` function that returns the
 * top-K nearest neighbors with their cosine scores. This keeps the decision
 * logic pure and trivially testable with synthetic fixtures, and lets the
 * orchestrator reuse whichever backend it already has wired up.
 *
 * Related issue: joshuaswarren/remnic#373
 */

import { connectorMatchesScope, normalizeConnectorScope } from "./connector-scope.js";

// ── Public types ──────────────────────────────────────────────────────────────

/** A single nearest-neighbor hit from the embedding backend. */
export interface SemanticDedupHit {
  /** Memory id of the existing neighbor. */
  id: string;
  /** Cosine similarity score in [0, 1]. */
  score: number;
  /** Optional source path, purely informational. */
  path?: string;
  /**
   * Source connector of the existing neighbor memory's provenance, used by
   * the connector-aware skip gate (PR #1852 review finding on 7e0eb1a0).
   * Absent when the neighbor is operator/unattributed or its frontmatter
   * could not be read.
   */
  sourceConnector?: string;
}

/**
 * Lookup function passed by the caller. Must return an array of hits sorted
 * descending by score. Implementations must throw when the embedding backend
 * is unavailable or the provider call fails, and return an empty array only
 * when a reachable backend successfully reports no hits. The decision function
 * fail-opens on thrown lookup errors while preserving a distinct
 * "backend_unavailable" reason for telemetry.
 */
export type SemanticDedupLookup = (
  content: string,
  limit: number,
) => Promise<SemanticDedupHit[]>;

export interface SemanticDedupOptions {
  /** Master switch. When false, `decideSemanticDedup` always returns `keep`. */
  enabled: boolean;
  /** Cosine similarity threshold (0-1). ≥ threshold ⇒ treat as duplicate. */
  threshold: number;
  /** How many nearest neighbors to compare against. */
  candidates: number;
  /**
   * Source connector of the CANDIDATE fact being evaluated (its provenance).
   * When present, a near-duplicate skip is permitted only against a neighbor
   * carrying the SAME connector; a different or absent neighbor connector
   * must NOT suppress the write (PR #1852 review finding on 7e0eb1a0).
   * Absent for operator / unattributed writes, which preserve the original
   * behavior (skip on any near-duplicate regardless of neighbor connector).
   */
  sourceConnector?: string;
}

export type SemanticDedupDecision =
  | {
      action: "keep";
      reason:
        | "disabled"
        | "backend_unavailable"
        | "no_candidates"
        | "no_near_duplicate"
        | "connector_mismatch";
      topScore?: number;
      topId?: string;
    }
  | {
      action: "skip";
      reason: "near_duplicate";
      topScore: number;
      topId: string;
      topPath?: string;
    };

// ── Pure decision function ────────────────────────────────────────────────────

const DEFAULT_SEMANTIC_THRESHOLD = 0.92;
const DEFAULT_SEMANTIC_CANDIDATES = 5;

function normalizeSemanticThreshold(value: number): number {
  return Number.isFinite(value)
    ? Math.min(1, Math.max(0, value))
    : DEFAULT_SEMANTIC_THRESHOLD;
}

function normalizeSemanticCandidates(value: number): number {
  if (!Number.isFinite(value) || value < 0) {
    return DEFAULT_SEMANTIC_CANDIDATES;
  }
  const normalized = Math.floor(value);
  return value > 0 && normalized === 0 ? 1 : normalized;
}

/**
 * Pure decision function: given a lookup callback and options, decide whether
 * the candidate content should be written or skipped as a near-duplicate.
 *
 * Contract:
 *   - When `options.enabled` is false → always keep, reason="disabled".
 *   - When the lookup throws (provider down / network error) → keep,
 *     reason="backend_unavailable". Fail-open: a lookup failure must not block
 *     writes.
 *   - When the lookup succeeds but returns 0 hits (empty index or no
 *     neighbors above the score floor) → keep, reason="no_candidates".
 *     This is distinct from backend_unavailable so telemetry dashboards can
 *     correctly distinguish "provider is down" from "index is empty".
 *   - When the top hit's score ≥ threshold → skip with reason="near_duplicate".
 *   - Otherwise → keep with reason="no_near_duplicate".
 */
export async function decideSemanticDedup(
  content: string,
  lookup: SemanticDedupLookup,
  options: SemanticDedupOptions,
): Promise<SemanticDedupDecision> {
  if (!options.enabled) {
    return { action: "keep", reason: "disabled" };
  }
  const threshold = normalizeSemanticThreshold(options.threshold);
  const candidates = normalizeSemanticCandidates(options.candidates);
  // Zero candidates means the operator has disabled the embedding lookup.
  // Treat it identically to enabled=false so no backend call is made.
  if (candidates === 0) {
    return { action: "keep", reason: "disabled" };
  }
  const trimmed = typeof content === "string" ? content.trim() : "";
  if (!trimmed) {
    return { action: "keep", reason: "no_near_duplicate" };
  }
  let hits: SemanticDedupHit[] = [];
  try {
    hits = await lookup(trimmed, candidates);
  } catch {
    // Fail-open: a lookup error must not block writes.
    return { action: "keep", reason: "backend_unavailable" };
  }
  if (!Array.isArray(hits) || hits.length === 0) {
    // Provider responded (no throw) but returned no hits: the embedding index
    // is empty or contains no neighbors above the score floor. Use a distinct
    // reason so callers and telemetry can differentiate this from a genuine
    // backend failure.
    return { action: "keep", reason: "no_candidates" };
  }

  // Resolve the candidate's provenance connector through the shared scope
  // contract (`connector-scope.ts`): an empty/whitespace value is treated as
  // absent (operator / unattributed).
  const candidateConnector = normalizeConnectorScope(options.sourceConnector);

  // Defensive: callers ought to return sorted, but don't trust it.
  let top: SemanticDedupHit | undefined;
  // Best same-connector neighbor — only tracked when the candidate is
  // provenance-bearing. Tracked in the same pass so a connector-aware skip
  // matches the best neighbor from the SAME connector even when a higher-
  // scoring neighbor from a DIFFERENT connector would otherwise win.
  let sameConnectorTop: SemanticDedupHit | undefined;
  for (const hit of hits) {
    if (
      !hit ||
      typeof hit.id !== "string" ||
      hit.id.trim().length === 0 ||
      typeof hit.score !== "number" ||
      !Number.isFinite(hit.score)
    ) {
      continue;
    }
    if (!top || hit.score > top.score) {
      top = hit;
    }
    if (
      candidateConnector !== undefined &&
      connectorMatchesScope(hit.sourceConnector, candidateConnector) &&
      (!sameConnectorTop || hit.score > sameConnectorTop.score)
    ) {
      sameConnectorTop = hit;
    }
  }
  if (!top) {
    return { action: "keep", reason: "no_near_duplicate" };
  }

  if (top.score >= threshold) {
    // Connector-aware skip gate (PR #1852 review finding on 7e0eb1a0):
    // A provenance-bearing candidate may be suppressed ONLY by a near-
    // duplicate from the SAME connector. A different or absent neighbor
    // connector must NOT suppress the write — otherwise a connector B
    // paraphrase would be dropped against connector A's memory before the
    // write ever happens. When the candidate carries no connector (operator
    // / unattributed), preserve the original behavior and skip on any match.
    if (candidateConnector !== undefined) {
      const match =
        sameConnectorTop !== undefined && sameConnectorTop.score >= threshold
          ? sameConnectorTop
          : undefined;
      if (match) {
        return {
          action: "skip",
          reason: "near_duplicate",
          topScore: match.score,
          topId: match.id,
          topPath: match.path,
        };
      }
      // Best overall hit cleared threshold but came from a different or
      // absent connector; no same-connector near-duplicate exists. Keep.
      return {
        action: "keep",
        reason: "connector_mismatch",
        topScore: top.score,
        topId: top.id,
      };
    }
    return {
      action: "skip",
      reason: "near_duplicate",
      topScore: top.score,
      topId: top.id,
      topPath: top.path,
    };
  }

  return {
    action: "keep",
    reason: "no_near_duplicate",
    topScore: top.score,
    topId: top.id,
  };
}

import {
  type HarmonicConstructionInput,
  deriveHarmonicRecords,
  harmonicEntityReferenceMatches,
  harmonicEntitySegment,
  normalizedHarmonicEntityIdentity,
  persistHarmonicRecords,
} from "../harmonic-construction.js";
import { log } from "../logger.js";
import type { StorageManager } from "../index.js";
import type { MemoryFile, ExtractionResult } from "../types.js";

export interface HarmonicPersistenceEntry {
  storage: { dir: string };
  facts: HarmonicConstructionInput["persistedFacts"];
}

export function filterHarmonicEntityMentions(
  facts: HarmonicConstructionInput["persistedFacts"],
  entityMentions: ExtractionResult["entities"]
): ExtractionResult["entities"] {
  const identitiesBySegment = new Map<string, Set<string>>();
  for (const entity of entityMentions) {
    const segment = harmonicEntitySegment(entity.name);
    const identities = identitiesBySegment.get(segment) ?? new Set<string>();
    identities.add(normalizedHarmonicEntityIdentity(entity.name));
    identitiesBySegment.set(segment, identities);
  }
  return entityMentions.flatMap((entity) => {
    const allowSegmentFallback = identitiesBySegment.get(harmonicEntitySegment(entity.name))?.size === 1;
    const activeFacts = facts.filter(
      (fact) =>
        typeof fact.entityRef === "string" &&
        harmonicEntityReferenceMatches(fact.entityRef, entity.name, allowSegmentFallback)
    );
    return activeFacts.length > 0 ? [{ ...entity, facts: activeFacts.map((fact) => fact.content) }] : [];
  });
}

/**
 * Finding B (round N+3, PR #2771): a successful merge-on-write commits new
 * claims into an EXISTING target id. `persistedIds` stays new-fragment only
 * by contract and cue anchors ride only through the per-fact harmonic
 * entry, so without this enqueue a merge-only extraction emits no episode,
 * abstraction node, or cue anchors for the committed claims. Enqueue the
 * surviving target — with the COMMITTED merged body as content — into the
 * same batch map the create path feeds, so the end-of-batch
 * {@link persistConstructedHarmonicRecords} pass covers it.
 *
 * Round N+9 (C): two facts merging into the SAME target in one batch enqueue
 * twice under one `memoryId`. `deriveHarmonicRecords` dedupes only
 * `sourceMemoryIds` — `persistedFacts` keeps both entries, so the episode
 * summary concatenated both cumulative snapshots and the inserted-at
 * metadata overwrote its duplicate key. Coalesce instead: the entry for a
 * repeated target is REPLACED by the latest committed body (each merge's
 * body is cumulative, so the latest carries every claim) while the cue
 * anchors UNION across merges — anchors are deduped by id downstream, but
 * the union keeps the earlier merge's anchors alive when the later incoming
 * fact carried none.
 *
 * #2807 (finding 3): the entry's metadata comes from the REREAD committed
 * target, never the incoming fact alone. The parity gate lets an incoming
 * fact with no entityRef merge into a target that HAS one (only a
 * differing non-undefined incoming entity refuses), and incoming tags are
 * a subset of the target's — so stamping the incoming fields onto the
 * cumulative body dropped the target's committed entity association and
 * extra tags, and `deriveHarmonicRecords` skipped the deterministic
 * entity cue/topic linkage for the merged claims. Cue anchors stay
 * incoming-only: they are event-specific. An unreadable or advanced record
 * falls back to the incoming fact's own fields (fail-open, like every
 * merge-adjacent effect).
 */
export async function enqueueMergedTargetForHarmonicConstruction(
  entries: Map<
    string,
    { storage: StorageManager; facts: HarmonicConstructionInput["persistedFacts"] }
  >,
  storage: StorageManager,
  fact: Omit<
    HarmonicConstructionInput["persistedFacts"][number],
    "memoryId" | "insertedAt"
  >,
  memoryId: string,
  content: string,
  insertedAt: string,
): Promise<void> {
  let committed: MemoryFile | null = null;
  try {
    committed = await storage.getMemoryByIdIncludingArchived(memoryId);
  } catch {
    committed = null;
  }
  const derived =
    committed && committed.content === content
      ? {
          ...fact,
          category: committed.frontmatter.category,
          tags: [...new Set([...(committed.frontmatter.tags ?? []), ...fact.tags])],
          entityRef: committed.frontmatter.entityRef ?? fact.entityRef,
          validAt: committed.frontmatter.valid_at ?? fact.validAt,
        }
      : fact;
  const entry = entries.get(storage.dir) ?? { storage, facts: [] };
  const prior = entry.facts.findIndex((existing) => existing.memoryId === memoryId);
  if (prior !== -1) {
    entry.facts[prior] = {
      ...derived,
      content,
      memoryId,
      insertedAt,
      cueAnchors: [
        ...(entry.facts[prior]!.cueAnchors ?? []),
        ...(derived.cueAnchors ?? []),
      ],
    };
  } else {
    entry.facts.push({ ...derived, content, memoryId, insertedAt });
  }
  entries.set(storage.dir, entry);
}

export async function persistConstructedHarmonicRecords(options: {
  entries: Iterable<HarmonicPersistenceEntry>;
  baseStorageDir: string;
  abstractionNodeStoreDir?: string;
  sessionKey?: string;
  validAt?: string;
  episodeTitle?: string;
  anchorsEnabled: boolean;
  entityMentions: ExtractionResult["entities"];
}): Promise<void> {
  const sessionKey = options.sessionKey?.trim();
  if (!sessionKey) {
    log.warn("harmonic construction skipped: extraction session key is missing");
    return;
  }
  const recordedAt =
    options.validAt && Number.isFinite(Date.parse(options.validAt))
      ? new Date(options.validAt).toISOString()
      : new Date().toISOString();
  const entries = [...options.entries];
  const sharedEpisodeTitle = entries.length === 1 ? options.episodeTitle : undefined;
  for (const entry of entries) {
    try {
      const records = deriveHarmonicRecords({
        sessionKey,
        recordedAt,
        episodeTitle: sharedEpisodeTitle,
        persistedFacts: entry.facts,
        entityMentions: filterHarmonicEntityMentions(entry.facts, options.entityMentions).map((entity) => ({
          name: entity.name,
          type: entity.type,
          facts: entity.facts,
        })),
      });
      await persistHarmonicRecords({
        memoryDir: entry.storage.dir,
        abstractionNodeStoreDir:
          entry.storage.dir === options.baseStorageDir ? options.abstractionNodeStoreDir : undefined,
        nodes: records.nodes,
        anchors: options.anchorsEnabled ? records.anchors : [],
      });
    } catch (error) {
      log.warn(
        `harmonic construction failed open for namespace ${entry.storage.dir}: ${error instanceof Error ? error.message : String(error)}`
      );
    }
  }
}

/**
 * Auto-promotion gating helpers for the extraction-persist pipeline
 * (extracted from extraction-persist.ts to keep that file under the
 * structural line-count ceiling; issue #1909 / seam 16).
 *
 * Pure decision helpers that answer "may this fact be auto-promoted?" for
 * both scope-profile targets and the server-shared namespace. Behavior is a
 * verbatim move from the closures that previously lived inside
 * `persistExtraction`; `this.deps.*` state is threaded in as explicit
 * parameters so the functions stay free of coordinator instance state.
 */

import { StorageManager } from "../index.js";
import { log } from "../logger.js";
import { withholdToolScopedFromSharedNamespace } from "../tool-scoped-memory.js";
import { evaluateSubjectGuard, isSharedPromotionTarget } from "../memory-subject.js";
import { inferMemoryStatus, toMemoryPathRel } from "../memory-lifecycle-ledger-utils.js";
import { confidenceTier, type MemorySubject } from "../types.js";
import {
  resolveNamespaceCapabilities,
  resolveRecallEnhancementCapabilities,
} from "../capabilities.js";
import type { MemoryFile, PluginConfig } from "../types.js";
import type { ResolvedScopeProfilePlan } from "../namespaces/scope-profiles.js";
import { readDurableSemanticFingerprint, readPromotionReceiptStatus, type MergedTargetPromotionPayload } from "./semantic-merge-promotion-payload.js";
import type { BehaviorSignalEvent, ExtractionResult } from "../types.js";
import type { HarmonicConstructionInput } from "../harmonic-construction.js";
import { dedupeBehaviorSignalsByMemoryAndHash } from "../behavior-signals.js";
import { persistConstructedHarmonicRecords } from "./harmonic-construction-persist.js";


export const confidenceTierOrder = [
  "explicit",
  "implied",
  "inferred",
  "speculative",
] as const;

export function profileAutoPromotionAllows(
  scopeProfileWritePlan: ResolvedScopeProfilePlan | null | undefined,
  category: string,
  confidence: number,
): boolean {
  if (!scopeProfileWritePlan) return false;
  const actualTier = confidenceTier(confidence);
  const actualRank = confidenceTierOrder.indexOf(actualTier);
  if (actualRank === -1) return false;
  const autoPromote = scopeProfileWritePlan.profile.autoPromote;
  if (!autoPromote.enabled) return false;
  if (!autoPromote.categories.includes(category as any)) return false;
  const minimumRank = confidenceTierOrder.indexOf(autoPromote.minConfidenceTier);
  return minimumRank !== -1 && actualRank <= minimumRank;
}

export function sharedAutoPromotionAllows(
  config: PluginConfig,
  scopeProfileWritePlan: ResolvedScopeProfilePlan | null | undefined,
  category: string,
  confidence: number,
): boolean {
  if (!scopeProfileWritePlan) {
    const actualTier = confidenceTier(confidence);
    const actualRank = confidenceTierOrder.indexOf(actualTier);
    if (actualRank === -1) return false;
    if (!resolveRecallEnhancementCapabilities(config).autoPromoteToShared) return false;
    if (!config.autoPromoteToSharedCategories.includes(category as any))
      return false;
    const minimumRank = confidenceTierOrder.indexOf(
      config.autoPromoteMinConfidenceTier,
    );
    return minimumRank !== -1 && actualRank <= minimumRank;
  }
  return (
    scopeProfileWritePlan.profile.autoPromote.targets.includes("serverShared") &&
    profileAutoPromotionAllows(scopeProfileWritePlan, category, confidence)
  );
}

export function shouldPromoteToShared(
  config: PluginConfig,
  scopeProfileWritePlan: ResolvedScopeProfilePlan | null | undefined,
  profileAllowsSharedWrites: boolean,
  storageDirNamespace: (storageDir: string) => string,
  targetStorage: StorageManager,
  category: string,
  confidence: number,
): boolean {
  if (
    !resolveNamespaceCapabilities(config).namespaces ||
    !profileAllowsSharedWrites ||
    !sharedAutoPromotionAllows(config, scopeProfileWritePlan, category, confidence)
  )
    return false;
  if (
    storageDirNamespace(targetStorage.dir) ===
    config.sharedNamespace
  )
    return false;
  return true;
}

/**
 * Read the active-copy corpus across BOTH storage tiers (hot + cold).
 *
 * #2016 cold-tier finding: the authoritative content-hash rebuild unions the
 * hot and cold tiers, so `hasFactContentHash()` can report a hit for a
 * fact/procedure whose only active copy was demoted to `cold/`. A promotion or
 * dedup confirmation scan that reads `readAllMemories()` (hot) alone misses
 * that copy, so it either writes a duplicate hot copy or skips a needed
 * temporal backfill. Scanning both tiers keeps the confirmation coherent with
 * the hash index. Cold reads are folded in only when the cold tier is
 * non-empty so hot-only namespaces incur no extra allocation.
 */
export async function readActiveMemoriesBothTiers(
  storage: StorageManager,
): Promise<MemoryFile[]> {
  const [hotMems, coldMems] = await Promise.all([
    storage.readAllMemories(),
    storage.readAllColdMemories(),
  ]);
  return coldMems.length === 0 ? hotMems : [...hotMems, ...coldMems];
}


/**
 * Batch-end finalization for facts already durable in this persist pass:
 * content-hash save, behavior signals, harmonic construction, temporal/tag
 * indexes. Shared by the success tail and every rethrow path so a partial
 * batch (e.g. fact wrote, entity failed) still lands deferred side effects
 * before the original error propagates (#3228 / #3231). Best-effort: each
 * step logs and never masks `originalError` at the call site.
 *
 * `scheduleQmd` is failure-only. Success still schedules QMD from
 * extraction-run after persist returns, so success passes false.
 */
export async function finalizeExtractionCommittedWrites(options: {
  saveContentHashIndexes: () => Promise<void>;
  behaviorSignalsByStorage: Iterable<{
    storage: StorageManager;
    events: BehaviorSignalEvent[];
  }>;
  harmonic?: {
    enabled: boolean;
    entries: Iterable<{
      storage: StorageManager;
      facts: HarmonicConstructionInput["persistedFacts"];
    }>;
    baseStorageDir: string;
    abstractionNodeStoreDir?: string;
    sessionKey?: string;
    validAt?: string;
    episodeTitle?: string;
    anchorsEnabled: boolean;
    entityMentions: ExtractionResult["entities"];
  };
  updateTemporalTagIndexes: (
    storage: StorageManager,
    persistedIds: string[],
  ) => Promise<void>;
  fallbackStorage: StorageManager;
  persistedIdsByStorage: Map<string, { storage: StorageManager; ids: string[] }>;
  requestQmdMaintenance?: () => void;
  scheduleQmd: boolean;
}): Promise<void> {
  await options.saveContentHashIndexes().catch((err) => {
    log.warn(`content-hash index save failed: ${err}`);
  });

  // Snapshot once — Map iterators are single-pass.
  const behaviorEntries = [...options.behaviorSignalsByStorage];
  for (const { storage: targetStorage, events } of behaviorEntries) {
    const dedupedSignals = dedupeBehaviorSignalsByMemoryAndHash(events);
    if (dedupedSignals.length === 0) continue;
    await targetStorage
      .appendBehaviorSignals(dedupedSignals)
      .catch((err) =>
        log.warn(`appendBehaviorSignals failed (non-fatal): ${err}`),
      );
  }

  const harmonic = options.harmonic;
  let harmonicEntryCount = 0;
  if (harmonic?.enabled) {
    const entries = [...harmonic.entries];
    harmonicEntryCount = entries.length;
    if (entries.length > 0) {
      await persistConstructedHarmonicRecords({
        entries,
        baseStorageDir: harmonic.baseStorageDir,
        abstractionNodeStoreDir: harmonic.abstractionNodeStoreDir,
        sessionKey: harmonic.sessionKey,
        validAt: harmonic.validAt,
        episodeTitle: harmonic.episodeTitle,
        anchorsEnabled: harmonic.anchorsEnabled,
        entityMentions: harmonic.entityMentions,
      });
    }
  }

  void (async () => {
    if (options.persistedIdsByStorage.size === 0) {
      await options.updateTemporalTagIndexes(options.fallbackStorage, []);
      return;
    }
    for (const entry of options.persistedIdsByStorage.values()) {
      await options.updateTemporalTagIndexes(entry.storage, entry.ids);
    }
  })().catch((err) =>
    log.debug(`temporal-index update error (non-fatal): ${err}`),
  );

  if (!options.scheduleQmd || !options.requestQmdMaintenance) return;
  const hasCommitted =
    options.persistedIdsByStorage.size > 0 ||
    behaviorEntries.length > 0 ||
    harmonicEntryCount > 0;
  if (!hasCommitted) return;
  try {
    options.requestQmdMaintenance();
  } catch (err) {
    log.warn(
      `QMD maintenance schedule after partial persist failed (non-fatal): ${err}`,
    );
  }
}


/**
 * Merged-target promotion scope gate (PR #2771 finding A). A committed
 * record stamped `toolScoped: true` must keep its promoted copy withheld
 * from the shared namespace even when the merged body no longer matches
 * the content heuristics that earned the target its marker at write time —
 * the merge judge composes new text, and without the incoming connector
 * the heuristic returns false outright. The committed marker is
 * authoritative; the heuristics only ever ADD withholding. Not a
 * parsed-config surface: the field is the frontmatter literal `true` or
 * absent.
 */
export function promotionWithholdsToolScope(options: {
  toolScoped?: true;
  content: string;
  sourceConnector?: string;
  procedureSteps?: ReadonlyArray<{ toolCall?: { kind?: string } }>;
}): boolean {
  return (
    options.toolScoped === true || withholdToolScopedFromSharedNamespace(options)
  );
}

/**
 * Subject guard (issue #2372), extracted verbatim from the coordinator
 * closure: the ONE gate shared by every extraction-side promotion path so
 * behavior matches the spaces surface (§27).
 */
export function makeSubjectGuardAllows(
  config: PluginConfig,
): (subject: MemorySubject | undefined, target: string, label: string) => boolean {
  return (subject, target, label) => {
    const decision = evaluateSubjectGuard({
      subject,
      sharedTarget: isSharedPromotionTarget(target),
      mode: config.subjectGuard,
    });
    if (decision.action !== "allow") {
      log.warn(`subject-guard(${decision.action}) ${label}: ${decision.reason}`);
    }
    return decision.action !== "reject";
  };
}

/**
 * Finding C (issue #2330 review): a successful semantic merge mutates only
 * the source namespace, but the create path's promotion step owns the
 * shared/profile copies linked back by `sourceMemoryId`. Merging a target
 * that already has promoted copies would leave those copies serving the
 * pre-merge body while the source serves the merged claims, so such a
 * target must bypass the merge and let the normal write run.
 *
 * Finding E (final round) + round N+12 (B): the scan covers ALL resolved
 * layers — NEVER filtered by today's `autoPromote.targets` selection, by
 * current write authorization, or by today's `promotionTargets` list. A copy
 * created while a layer was listed stays linked by `sourceMemoryId` after
 * the operator removes that layer from the promotion selection while it
 * remains resolvable through readOrder/layers; detection scans history while
 * policy governs writes (the authorization-change lesson applied to
 * selection). An unreadable promotion namespace is treated as "copies may
 * exist": the conservative create path runs rather than risk
 * cross-namespace divergence.
 */
export function promotionScanNamespaces(
  config: PluginConfig,
  scopeProfileWritePlan: ResolvedScopeProfilePlan | null | undefined,
): string[] {
  const namespaces: string[] = [];
  if (scopeProfileWritePlan) {
    for (const target of scopeProfileWritePlan.promotionTargets) {
      if (target.target !== "serverShared" && target.namespace) {
        namespaces.push(target.namespace);
      }
    }
    // Round N+12 (B): enumerate EVERY resolvable layer, not only today's
    // promotionTargets. A namespace that received promoted copies while its
    // layer was selected keeps serving them after the operator removes the
    // layer from the selection — the layer stays resolvable through
    // readOrder/layers, and the documented guarantee is that historical
    // copies remain detectable after selection changes. The shared namespace
    // joins below from config (the authoritative value).
    for (const layer of scopeProfileWritePlan.layers ?? []) {
      if (layer.id !== "serverShared" && layer.namespace) {
        namespaces.push(layer.namespace);
      }
    }
  }
  namespaces.push(config.sharedNamespace);
  return [...new Set(namespaces)];
}

/** One namespace's promoted-copy scan. `sourceIds: null` means unreadable. */
interface PromotedCopyScanEntry {
  dir: string;
  sourceIds: Set<string> | null;
}

export interface BatchPromotedCopyProbe {
  check: (sourceStorage: StorageManager, targetMemoryId: string) => Promise<boolean>;
  /**
   * Finding F (final round): drop the cached scans after this batch itself
   * promoted a copy, so a later fact merging into the same target still sees
   * the copy the batch just wrote.
   */
  invalidate: () => void;
}

/**
 * Finding F (capacity regression): the guard scans every promotion
 * namespace's full hot+cold corpus, and a multi-fact extraction calls it
 * once per judge-approved fact — O(facts × namespaces × corpus). The probe
 * scans each namespace ONCE per batch and reuses the result. The uncached
 * per-call helper below shares this single implementation.
 */
export function createBatchPromotedCopyProbe(
  config: PluginConfig,
  getStorageRouter: () => {
    storageFor: (namespace: string) => Promise<StorageManager>;
  },
  scopeProfileWritePlan: ResolvedScopeProfilePlan | null | undefined,
): BatchPromotedCopyProbe {
  const scans = new Map<string, Promise<PromotedCopyScanEntry>>();
  const scanNamespace = (namespace: string): Promise<PromotedCopyScanEntry> => {
    let entry = scans.get(namespace);
    if (entry === undefined) {
      entry = (async (): Promise<PromotedCopyScanEntry> => {
        try {
          const storage = await getStorageRouter().storageFor(namespace);
          const active = await readActiveMemoriesBothTiers(storage);
          return {
            dir: storage.dir,
            // Round N+11 (A): only ACTIVE copies count as promoted (§41 —
            // enumerate the active set). readActiveMemoriesBothTiers returns
            // every hot+cold copy, superseded ones included; a superseded
            // copy serves no body, so counting it made targetHasPromotedCopies
            // reject every later judge-approved merge and the supposedly
            // mergeable updates accumulated as new fragments instead.
            sourceIds: new Set(
              active
                .filter(
                  (memory) =>
                    inferMemoryStatus(memory.frontmatter, toMemoryPathRel(storage.dir, memory.path)) ===
                    "active",
                )
                .map((memory) => memory.frontmatter.sourceMemoryId)
                .filter((id): id is string => typeof id === "string"),
            ),
          };
        } catch (err) {
          log.warn(
            `semantic-merge guard: promotion namespace "${namespace}" unreadable; bypassing the merge (finding C): ${err instanceof Error ? err.message : String(err)}`,
          );
          return { dir: "", sourceIds: null };
        }
      })();
      scans.set(namespace, entry);
    }
    return entry;
  };
  return {
    check: async (sourceStorage, targetMemoryId) => {
      for (const namespace of promotionScanNamespaces(config, scopeProfileWritePlan)) {
        const entry = await scanNamespace(namespace);
        if (entry.sourceIds === null) return true;
        if (entry.dir === sourceStorage.dir) continue;
        if (entry.sourceIds.has(targetMemoryId)) return true;
      }
      return false;
    },
    invalidate: () => {
      scans.clear();
    },
  };
}

export async function mergeTargetHasPromotedCopies(args: {
  config: PluginConfig;
  getStorageRouter: () => {
    storageFor: (namespace: string) => Promise<StorageManager>;
  };
  scopeProfileWritePlan: ResolvedScopeProfilePlan | null | undefined;
  sourceStorage: StorageManager;
  targetMemoryId: string;
}): Promise<boolean> {
  return createBatchPromotedCopyProbe(
    args.config,
    args.getStorageRouter,
    args.scopeProfileWritePlan,
  ).check(args.sourceStorage, args.targetMemoryId);
}

/**
 * Round N+10 (A): run the merged target's promotion and its stale-copy
 * reconciliation as ONE step so reconciliation cannot be skipped on a
 * no-promotion exit. `promoteMemoryToShared` returns undefined when this
 * merge's min(incoming, target) downgrade dropped the committed record below
 * the profile/shared promotion minimum, and `buildMergedTargetPromotionPayload`
 * returns null for a degraded merge — in both cases no replacement copy is
 * written, yet a concurrent writer may have published the PRE-merge body
 * after the caller's initial probe. Reconciliation still runs: with no
 * promoted body supplied, {@link retireStaleMergedTargetPromotionCopies}
 * re-reads the committed record and retires copies predating it, superseding
 * them onto the committed target itself ("none is warranted" below the
 * threshold). Promotion failures stay fail-open — the merge stands.
 *
 * Round N+15 (A): the payload is a CACHE of the committed record as of the
 * builder's read. Between that read and this promotion another writer can
 * merge the same target again (or a lifecycle operation can retire it), so
 * the record is re-read and the cache confirmed against the committed
 * revision AND body immediately before promoting. On any advance — or an
 * unreadable record, which can never confirm the cache — the promotion AND
 * its reconciliation are abandoned: the newer writer's copy stands, a cached
 * body never becomes canonical, and the next merge retries both.
 */
export async function promoteAndReconcileMergedTarget(args: {
  promote: (payload: MergedTargetPromotionPayload) => Promise<string | undefined>;
  config: PluginConfig;
  getStorageRouter: () => {
    storageFor: (namespace: string) => Promise<StorageManager>;
  };
  scopeProfileWritePlan: ResolvedScopeProfilePlan | null | undefined;
  sourceStorage: StorageManager;
  sourceMemoryId: string;
  /** Null = payload builder refused (degraded merge / target replaced mid-flight). */
  mergedPromotion: MergedTargetPromotionPayload | null;
  /** #2807 (finding 1): the builder's post-commit reread FAILED — the payload is unknown, not refused. Skips the destructive reconciliation. */
  mergedPromotionReadFailed?: boolean;
  normalize: (content: string) => string;
  onReconciled?: () => void;
}): Promise<void> {
  // #2807 (finding 1): an unreadable payload is not a no-promotion
  // verdict. Reconciling anyway rereads the record successfully a moment
  // later and interprets the missing payload as "no promotion warranted" —
  // retiring a concurrently published PRE-merge copy with no current-body
  // replacement and removing an otherwise eligible memory from the
  // shared/profile layer. Skip the destructive pass; the next merge
  // retries promotion and reconciliation against a readable record.
  if (args.mergedPromotion === null && args.mergedPromotionReadFailed === true) {
    log.warn(
      `persistExtraction: merged-target promotion reconciliation skipped for ${args.sourceMemoryId} — the committed record was unreadable at payload-build time, so no promotion outcome is confirmed`,
    );
    return;
  }
  let promotedCopyId: string | undefined;
  if (args.mergedPromotion) {
    const payload = args.mergedPromotion;
    const current = await args.sourceStorage
      .getMemoryByIdIncludingArchived(args.sourceMemoryId)
      .catch(() => null);
    if (
      !current ||
      inferMemoryStatus(current.frontmatter, current.path) !== "active" ||
      current.content !== payload.content
    ) {
      log.warn(
        `persistExtraction: merged-target promotion abandoned for ${args.sourceMemoryId} — the committed record advanced past the cached payload, so the newer writer's copy stands`,
      );
      return;
    }
    // #2813 (P1 A, P1 B) + #2870: confirm the cached payload against a
    // TRUTHFUL receipt read and a SEMANTIC fingerprint check. An
    // unavailable sidecar or revision mismatch abandons the promotion —
    // the previous undefined-vs-undefined comparison confirmed any payload
    // whose receipt identity had become unreadable. A genuinely absent
    // receipt still compares equal and promotes. The file check binds
    // SEMANTIC identity, not bytes: an access-tracking flush between build
    // and promotion rewrites only `accessCount`/`lastAccessed` (mints no
    // receipt, changes no semantic line), so it stays compatible and the
    // promotion proceeds; any body/confidence/provenance/scope/tags/status
    // change makes the fingerprint differ and refuses.
    const standingReceipt = await readPromotionReceiptStatus(args.sourceStorage, current.path);
    const standingSemanticFingerprint = await readDurableSemanticFingerprint(current.path);
    if (
      !standingReceipt.available ||
      (standingReceipt.revision ?? undefined) !== (payload.committedRevision ?? undefined) ||
      (payload.committedDigest !== undefined &&
        standingReceipt.committedDigest !== undefined &&
        standingReceipt.committedDigest !== payload.committedDigest) ||
      (payload.committedSemanticFingerprint !== undefined &&
        standingSemanticFingerprint !== null &&
        standingSemanticFingerprint !== payload.committedSemanticFingerprint)
    ) {
      log.warn(
        `persistExtraction: merged-target promotion abandoned for ${args.sourceMemoryId} — the committed record's CAS receipt or semantic fingerprint ${standingReceipt.available ? "does not match the cached payload's" : "is unreadable"}, so the cached body is not confirmed`,
      );
      return;
    }
    try {
      promotedCopyId = await args.promote(payload);
    } catch (err) {
      log.warn(
        `persistExtraction: merged-target promotion failed open for ${args.sourceMemoryId}: ${err}`,
      );
    }
  }
  try {
    await retireStaleMergedTargetPromotionCopies({
      config: args.config,
      getStorageRouter: args.getStorageRouter,
      scopeProfileWritePlan: args.scopeProfileWritePlan,
      sourceStorage: args.sourceStorage,
      sourceMemoryId: args.sourceMemoryId,
      ...(args.mergedPromotion
        ? { promotedContent: args.mergedPromotion.content }
        : {}),
      ...(promotedCopyId !== undefined
        ? { promotedMemoryId: promotedCopyId }
        : {}),
      normalize: args.normalize,
    });
    args.onReconciled?.();
  } catch (err) {
    log.warn(
      `persistExtraction: merged-target promotion reconciliation failed open for ${args.sourceMemoryId}: ${err}`,
    );
  }
}

/**
 * Round N+7 (B) + P1-A (#2330 round N+8) + round N+10 (A): reconcile a
 * merged target's promoted copies after the merged-body promotion lands.
 * The pre-mutation probe that guards the merge can race a concurrent writer
 * that is promoting the same target: the probe reports no copies, the other
 * writer publishes the PRE-merge body, and the merged-target promotion then
 * adds the current body — promotion dedups by content, so both copies stay
 * active across namespaces. Detection: an ACTIVE memory in any resolved
 * promotion namespace (never the source's own) whose `sourceMemoryId` names
 * this target and whose normalized body differs from the canonical body.
 * Round N+10 (A) extended this to the NO-promotion path:
 * `promotedContent` may be omitted and `promotedMemoryId` may be omitted
 * (below-threshold downgrade or degraded merge) — stale copies then
 * supersede onto the committed source target itself, leaving exactly one
 * current copy or none if none is warranted. Round N+13 (A): an
 * unreadable, missing, or empty canonical body ABORTS the reconciliation —
 * no copy is ever retired off a body that was never confirmed. Round N+15
 * (A): the canonical body is ALWAYS the re-read committed record, never the
 * promotion's cached payload — a writer committing a newer merge between
 * this writer's promotion and its reconciliation would otherwise have its
 * current copy superseded off the older cached body; when the re-read has
 * moved past the promoted body, this promotion's own copies are stale too
 * and supersede onto the SOURCE target. Replace, not add: each stale copy
 * is superseded with `supersededBy` pointing at the current copy (or the
 * source target). Best-effort and fail-open per namespace — a failed
 * retirement is logged and leaves the pre-fix state, which the next merge
 * retries. Returns the number of stale copies retired.
 */
export async function retireStaleMergedTargetPromotionCopies(args: {
  config: PluginConfig;
  getStorageRouter: () => {
    storageFor: (namespace: string) => Promise<StorageManager>;
  };
  scopeProfileWritePlan: ResolvedScopeProfilePlan | null | undefined;
  sourceStorage: StorageManager;
  sourceMemoryId: string;
  /** The body the merged-target promotion wrote (raw committed record content). Omit on the no-promotion path. The canonical body is always re-read from the committed record; this only selects the supersession target. */
  promotedContent?: string;
  /** The id of the promoted copy just written (supersession target while it still carries the canonical body). Omit when no replacement promotion ran — stale copies supersede onto the source target. */
  promotedMemoryId?: string;
  /** The caller's canonical content form (normalizeStoredHashSource). */
  normalize: (content: string) => string;
}): Promise<number> {
  const canonicalRecord = await args.sourceStorage
    .getMemoryByIdIncludingArchived(args.sourceMemoryId)
    .catch(() => null);
  const canonicalBody = canonicalRecord?.content;
  // Round N+13 (A): the guard's outcomes are "keep copies" and "retire
  // copies", so an unreadable canonical record MUST resolve to keep. A
  // failed re-read degrading to "" made every non-empty active copy compare
  // stale against normalize("") and superseded the whole copy set with no
  // confirmed replacement body to compare against. Abort the reconciliation
  // entirely; the next merge retries it.
  if (typeof canonicalBody !== "string" || canonicalBody.length === 0) {
    log.warn(
      `persistExtraction: merged-target promotion reconciliation aborted for ${args.sourceMemoryId} — the canonical record could not be read, so no copy is retired`,
    );
    return 0;
  }
  const canonicalForm = args.normalize(canonicalBody);
  // Round N+15 (A): the just-written copy is the supersession target only
  // while it still carries the canonical body. When the re-read record has
  // moved past the promoted body (a newer writer committed mid-flight), the
  // SOURCE target is the live canonical record and every stale copy — this
  // promotion's own included — supersedes onto it. The id exclusion the
  // filter used to carry is subsumed by the body compare: a copy carrying
  // the canonical body is never stale, whatever its id.
  const supersessionTarget =
    args.promotedContent !== undefined &&
    args.promotedMemoryId !== undefined &&
    args.normalize(args.promotedContent) === canonicalForm
      ? args.promotedMemoryId
      : args.sourceMemoryId;
  let retired = 0;
  for (const namespace of promotionScanNamespaces(args.config, args.scopeProfileWritePlan)) {
    try {
      const storage = await args.getStorageRouter().storageFor(namespace);
      if (storage.dir === args.sourceStorage.dir) continue;
      const active = await readActiveMemoriesBothTiers(storage);
      const stale = active.filter(
        (memory) =>
          memory.frontmatter.sourceMemoryId === args.sourceMemoryId &&
          (memory.frontmatter.status ?? "active") === "active" &&
          args.normalize(memory.content ?? "") !== canonicalForm,
      );
      for (const memory of stale) {
        const superseded = await storage.supersedeMemory(
          memory.frontmatter.id as string,
          supersessionTarget,
          "merged-target promotion reconciliation",
        );
        if (superseded) {
          retired++;
          log.warn(
            `persistExtraction: superseded stale promoted copy ${memory.frontmatter.id} of ${args.sourceMemoryId} — it carried the pre-merge body while ${supersessionTarget} serves the merged body`,
          );
        }
      }
    } catch (err) {
      log.warn(
        `persistExtraction: merged-target promotion reconciliation failed open for namespace "${namespace}": ${err instanceof Error ? err.message : String(err)}`,
      );
    }
  }
  return retired;
}

/**
 * Merged-target promotion payload builder (issue #2330, rounds final/N+18).
 * Sibling of semantic-merge-persist.ts — extracted there so that file stays
 * within its file-size ratchet. Everything here derives from the re-read
 * COMMITTED record; nothing reads the incoming extraction.
 */
import { createHash } from "node:crypto";
import { readFile } from "node:fs/promises";
import { canonicalSemanticFileText } from "../storage/cas-revision-store.js";
import { parseOriginClass } from "../security/origin-authority.js";
import { log } from "../logger.js";
import { inferMemoryStatus } from "../memory-lifecycle-ledger-utils.js";
import type { StorageManager } from "../index.js";
import type {
  ImportanceScore,
  MemoryFile,
  MemoryFrontmatter,
  MemorySubject,
  ProvenanceSource,
} from "../types.js";

/**
 * The merged-target promotion payload (final round): EVERY field the
 * shared/profile copy is stamped from, taken wholesale off the re-read
 * committed record — no field on the promotion path reads the incoming
 * extraction. `origin` is normalized through `parseOriginClass` so an
 * unstamped legacy target promotes as `unknown`, the fence's
 * least-privilege default, and never falls back to the extraction's own
 * origin. Absent optional fields stay absent: a target without temporal
 * bounds or attributes promotes a copy without them. The record's
 * confidence is the downgraded min(incoming, target) value the merge
 * patch stamped (final round A), so the copy stamps that same value. The
 * tool-scope marker and owning connector ride along (finding A) so the
 * promotion's withhold gate evaluates the record's committed scope, not a
 * fresh content-heuristic guess over the merged body.
 */
export interface MergedTargetPromotionPayload {
  category: string;
  content: string;
  confidence: number;
  tags: string[];
  entityRef?: string;
  structuredAttributes?: Record<string, string>;
  sourceMemoryId: string;
  importance?: ImportanceScore;
  intentGoal?: string;
  intentActionType?: string;
  intentEntityTypes?: string[];
  memoryKind?: MemoryFrontmatter["memoryKind"];
  validAt?: string;
  invalidAt?: string;
  observedAt?: string;
  eventTimeSource?: "extracted" | "assumed";
  /** Normalized committed origin; never undefined, so the envelope's extraction fallback cannot fire. */
  origin: string;
  sources?: ProvenanceSource[];
  provenance?: "verified" | "unverified" | "none";
  subject?: MemorySubject;
  /** The committed target's own write provenance label. */
  source: string;
  /** Committed tool-scope marker + owning connector (finding A): the copy must
   * stay withheld from the shared namespace exactly like the record it copies.
   * Re-running the content heuristics over the merged body is not equivalent —
   * the judge-composed text can drop the tool references that earned the
   * target its marker at write time, and without the connector the heuristic
   * returns false outright. */
  toolScoped?: true;
  sourceConnector?: string;
  /**
   * The committed record's CAS revision token at payload-build time (round
   * N+15 A, #2807) — the dedicated sidecar identity, never public
   * `frontmatter.updated`. The payload is a CACHE: before promoting it, the
   * caller re-reads the record and confirms the token AND body still match —
   * a writer that merged the same target again in between makes this
   * payload stale, and a stale body must never be promoted or become the
   * reconciliation canon.
   */
  committedRevision?: string;
  /** #2813 (P1 B): sha256 hex digest of the durable memory file when committed. */
  committedDigest?: string;
  /** #2870: canonical SEMANTIC fingerprint of the durable file at
   * payload-build time — access telemetry (`accessCount`/`lastAccessed`)
   * excluded, the same exclusion set `invalidationCommitFingerprint`
   * applies. The final guard re-reads the file and compares THIS, not the
   * byte digest: an access-tracking flush between build and promotion
   * leaves it equal (the flush mints no receipt and touches no semantic
   * line), while any body/confidence/provenance/scope/tags/status change
   * makes it differ. */
  committedSemanticFingerprint?: string;
}

/**
 * #2807 (finding 1): the builder's null has two meanings the caller must
 * not conflate. A REFUSED payload (degraded merge, target replaced
 * mid-flight, retired record) means "no promotion is warranted" — the
 * caller's destructive reconciliation may proceed on that conclusion. A
 * payload that is UNKNOWN because the post-commit reread itself failed
 * means no such conclusion was reached, so `readFailed` preserves the
 * failure reason across the call boundary.
 */
export interface MergedTargetPromotionResult {
  payload: MergedTargetPromotionPayload | null;
  /** True when `payload` is null because the reread threw OR the CAS receipt
   * sidecar was unreadable (#2813 P1 A) — the payload is unknown, not refused. */
  readFailed: boolean;
}

/**
 * Re-read the committed merge target (cold-aware id lookup — the same
 * resolver the merge itself used) and derive the promotion payload solely
 * from that record. Returns a null payload when the record can no longer
 * ground the promotion (deleted, its body was replaced after the merge
 * committed, or a concurrent lifecycle operation archived/superseded it
 * between the merge commit and this reread — promoting from a retired
 * record would resurrect content that operation retired, final round B),
 * and null for a degraded merge whose provenance patch never landed (round
 * N+7 A) — the gate every trust-elevating consumer routes through; callers
 * then skip the promotion fail-open — the merge itself stands. Round N+18
 * (B): the reread itself is isolated fail-open — a locked secure store or
 * a corpus read I/O error resolves to a null payload with `readFailed:
 * true` and a logged warn rather than a rejection, because the merge has
 * already committed and the hash-index repair makes any retry dedupe
 * against the committed body; an uncaught throw here would strand every
 * remaining durable effect (thread episode, temporal/tag refresh, harmonic
 * construction, graph rebuild, behavior signals, artifact write). #2807:
 * the failure reason rides out on the result so reconciliation can tell an
 * unknown payload from a refused one.
 */
export async function buildMergedTargetPromotionPayload(
  storage: StorageManager,
  merge: { targetId: string; mergedContent: string; provenancePatched: boolean },
): Promise<MergedTargetPromotionResult> {
  // Round N+7 (A): a degraded merge's record still holds its pre-merge
  // confidence, provenance, sources, and hash — a copy built off it would
  // publish incoming claims under that stronger metadata. No promotion may
  // be constructed from an unpatched provenance record.
  if (!merge.provenancePatched) {
    log.warn(
      `semantic-merge: skipping merged-target promotion for ${merge.targetId} — provenance patch did not land; the record still holds pre-merge trust metadata`,
    );
    return { payload: null, readFailed: false };
  }
  let committed: MemoryFile | null;
  try {
    committed = await storage.getMemoryByIdIncludingArchived(merge.targetId);
  } catch (err) {
    // Round N+18 (B): fail-open with a notice, like the artifact helper.
    log.warn(
      `semantic-merge: merged-target promotion reread failed for ${merge.targetId} (non-fatal; promotion skipped, the committed merge stands): ${err instanceof Error ? err.message : String(err)}`,
    );
    return { payload: null, readFailed: true };
  }
  if (!committed || committed.content !== merge.mergedContent) {
    return { payload: null, readFailed: false };
  }
  // Final round (B): the including-archived lookup still returns a retired
  // record, and body equality alone cannot tell a concurrent archive or
  // supersede apart from a live target. Recompute the status from the
  // committed record itself and refuse to promote unless it is still
  // active.
  if (inferMemoryStatus(committed.frontmatter, committed.path) !== "active") {
    return { payload: null, readFailed: false };
  }
  const fm = committed.frontmatter;
  // #2870: bind to the record's SEMANTIC identity, not its bytes. The
  // receipt's committed semantic fingerprint — the durable file with the
  // access-telemetry keys (`accessCount:`, `lastAccessed:`) stripped, the
  // same exclusion set `invalidationCommitFingerprint` applies — stays
  // equal across an access-tracking flush (which rewrites exactly those
  // two lines without minting a receipt), so a flush between the merge
  // commit and this reread no longer blocks a valid promotion. Any other
  // frontmatter or body change still refuses. Shards recorded before
  // #2870 carry no stored semantic fingerprint; those keep the stricter
  // full-digest comparison until the next semantic write re-records the
  // shard.
  const snapshotDigest =
    typeof storage.readDurableFileDigest === "function"
      ? await storage.readDurableFileDigest(committed.path).catch(() => null)
      : null;
  const snapshotSemanticFingerprint = await readDurableSemanticFingerprint(committed.path);
  const receipt = await readPromotionReceiptStatus(storage, committed.path);
  if (!receipt.available) {
    log.warn(
      `semantic-merge: merged-target promotion refused for ${merge.targetId} — the CAS revision receipt for ${committed.path} is unavailable (${receipt.reason}); promotion and reconciliation retry on the next merge`,
    );
    return { payload: null, readFailed: true };
  }
  if (
    receipt.committedSemanticFingerprint !== undefined &&
    snapshotSemanticFingerprint !== receipt.committedSemanticFingerprint
  ) {
    log.warn(
      snapshotSemanticFingerprint == null
        ? `semantic-merge: merged-target promotion refused for ${merge.targetId} — the semantic snapshot fingerprint is unavailable while the CAS receipt carries ${receipt.committedSemanticFingerprint}; promotion and reconciliation retry on the next merge`
        : `semantic-merge: merged-target promotion refused for ${merge.targetId} — record semantic fingerprint (${snapshotSemanticFingerprint}) does not match committed receipt fingerprint (${receipt.committedSemanticFingerprint}); record metadata was mutated concurrently`,
    );
    return { payload: null, readFailed: true };
  }
  if (
    receipt.committedSemanticFingerprint === undefined &&
    receipt.committedDigest !== undefined &&
    snapshotDigest !== receipt.committedDigest
  ) {
    log.warn(
      snapshotDigest == null
        ? `semantic-merge: merged-target promotion refused for ${merge.targetId} — the record snapshot digest is unavailable while the CAS receipt carries committed digest ${receipt.committedDigest}; promotion and reconciliation retry on the next merge`
        : `semantic-merge: merged-target promotion refused for ${merge.targetId} — record snapshot digest (${snapshotDigest}) does not match committed receipt digest (${receipt.committedDigest}); record metadata was mutated concurrently`,
    );
    return { payload: null, readFailed: true };
  }
  return {
    payload: {
      category: fm.category,
      content: committed.content,
      confidence: fm.confidence,
      tags: fm.tags ?? [],
      sourceMemoryId: fm.id,
      origin: parseOriginClass(fm.origin),
      source: fm.source,
      ...(fm.entityRef !== undefined ? { entityRef: fm.entityRef } : {}),
      ...(fm.structuredAttributes !== undefined
        ? { structuredAttributes: { ...fm.structuredAttributes } }
        : {}),
      ...(fm.importance !== undefined ? { importance: fm.importance } : {}),
      ...(fm.intentGoal !== undefined ? { intentGoal: fm.intentGoal } : {}),
      ...(fm.intentActionType !== undefined ? { intentActionType: fm.intentActionType } : {}),
      ...(fm.intentEntityTypes !== undefined
        ? { intentEntityTypes: [...fm.intentEntityTypes] }
        : {}),
      ...(fm.memoryKind !== undefined ? { memoryKind: fm.memoryKind } : {}),
      ...(fm.valid_at !== undefined ? { validAt: fm.valid_at } : {}),
      ...(fm.invalid_at !== undefined ? { invalidAt: fm.invalid_at } : {}),
      ...(fm.observedAt !== undefined ? { observedAt: fm.observedAt } : {}),
      ...(fm.eventTimeSource !== undefined ? { eventTimeSource: fm.eventTimeSource } : {}),
      ...(fm.sources && fm.sources.length > 0
        ? { sources: fm.sources.map((source) => ({ ...source })) }
        : {}),
      ...(fm.provenance !== undefined ? { provenance: fm.provenance } : {}),
      ...(fm.subject !== undefined ? { subject: fm.subject } : {}),
      ...(fm.toolScoped === true ? { toolScoped: true as const } : {}),
      ...(fm.sourceConnector !== undefined ? { sourceConnector: fm.sourceConnector } : {}),
      ...(receipt.revision !== undefined ? { committedRevision: receipt.revision } : {}),
      ...(receipt.committedDigest !== undefined
        ? { committedDigest: receipt.committedDigest }
        : snapshotDigest !== null
          ? { committedDigest: snapshotDigest }
          : {}),
      ...(receipt.committedSemanticFingerprint !== undefined
        ? { committedSemanticFingerprint: receipt.committedSemanticFingerprint }
        : snapshotSemanticFingerprint !== null
          ? { committedSemanticFingerprint: snapshotSemanticFingerprint }
          : {}),
    },
    readFailed: false,
  };
}

/** #2870: canonical SEMANTIC fingerprint of a durable file's CURRENT
 * bytes — the file text with access telemetry stripped
 * ({@link canonicalSemanticFileText}), hashed exactly the way the CAS
 * receipt records it at commit time. Null when the file cannot be read
 * (fail-open, like readDurableFileDigest). */
export async function readDurableSemanticFingerprint(filePath: string): Promise<string | null> {
  try {
    return createHash("sha256")
      .update(canonicalSemanticFileText(await readFile(filePath, "utf8")))
      .digest("hex");
  } catch {
    return null;
  }
}
/** #2813 (P1 A): read the standing receipt as a three-way truth for the
 * promotion path. Present and absent are usable identities (absent = the
 * target predates the sidecar); unavailable is not. A storage whose status
 * probe itself throws reads as unavailable — never as absence. */
export async function readPromotionReceiptStatus(
  storage: Pick<StorageManager, "readCasRevisionStatus">,
  filePath: string,
): Promise<
  | { available: true; revision: string | undefined; committedDigest?: string; committedSemanticFingerprint?: string }
  | { available: false; reason: string }
> {
  try {
    const status = await storage.readCasRevisionStatus(filePath);
    if (status.status === "unavailable") return { available: false, reason: status.reason };
    return {
      available: true,
      revision: status.status === "present" ? status.revision : undefined,
      committedDigest: status.status === "present" ? status.committedDigest : undefined,
      committedSemanticFingerprint:
        status.status === "present" ? status.committedSemanticFingerprint : undefined,
    };
  } catch (err) {
    return { available: false, reason: err instanceof Error ? err.message : String(err) };
  }
}

/**
 * Persist-side executor for judge-mediated merge-on-write (issue #2330, step 3).
 *
 * Lives beside `extraction-persist.ts` so that file stays within its
 * file-size ratchet ceiling. Called once per surviving fact, right before
 * the normal (non-chunked) sealed-envelope write. On every failure mode —
 * disabled gate, empty band, judge refusal, invalid verdict, snapshot or
 * update failure — the outcome is "created" and the caller falls through
 * to the unchanged write path.
 *
 * Exact mutation order (checklist #14/#42): version snapshot FIRST, then
 * the in-place content update, then the frontmatter patch, then hash-index
 * remove/add, then reindex. The new fact's content is never indexed as
 * its own entry — it was never persisted (checklist #32).
 */

