function recallFactsForStructuredSection(section: EntityStructuredSection): RecalledEntityFact[] {
  if (!isBeliefLedgerSection(section)) {
    return section.facts.map((text, sourceIndex) => ({ text, sourceIndex }));
  }
  return currentActiveBeliefLedgerFactTexts(section.facts);
}
function currentActiveBeliefLedgerFactTexts(facts: string[]): RecalledEntityFact[] {
  const byClaim = new Map<string, { status: string; updatedAtMs: number; texts: RecalledEntityFact[] }>();
  for (const [sourceIndex, fact] of facts.entries()) {
    const match = BELIEF_LEDGER_FACT_RE.exec(fact.trim());
    if (!match) continue;
    const [, claimId, status, updatedAt, text] = match;
    const updatedAtMs = Date.parse(updatedAt);
    if (!claimId?.trim() || !status?.trim() || !Number.isFinite(updatedAtMs) || !text?.trim()) continue;
    const normalizedStatus = status.trim().toLowerCase();
    const normalizedClaimId = claimId.trim();
    const current = byClaim.get(normalizedClaimId);
    const inactiveTieWins =
      current &&
      updatedAtMs === current.updatedAtMs &&
      current.status === "active" &&
      normalizedStatus !== "active";
    if (!current || updatedAtMs > current.updatedAtMs || inactiveTieWins) {
      byClaim.set(normalizedClaimId, { status: normalizedStatus, updatedAtMs, texts: [{ text: text.trim(), sourceIndex }] });
      continue;
    }
    if (updatedAtMs === current.updatedAtMs && current.status === normalizedStatus) {
      current.texts.push({ text: text.trim(), sourceIndex });
    }
  }
  return [...byClaim.values()].flatMap((current) => current.status === "active" ? current.texts : []);
}
function relationLine(entry: EntityMentionIndexEntry, relationship: { target: string; label: string }): string {
  const normalizedLabel = relationship.label.replace(/\s+/g, " ").trim();
  if (normalizedLabel.length === 0) return `${entry.name} is connected to ${relationship.target}`;
  return `${entry.name} ${normalizedLabel} ${relationship.target}`;
}
function scoreAliasMatch(query: string, alias: string): number {
  const normalizedQuery = normalizeEntityText(query);
  const normalizedAlias = normalizeEntityText(alias);
  if (!normalizedAlias) return 0;
  if (normalizedQuery === normalizedAlias) return 10;
  if (containsPhrase(normalizedQuery, normalizedAlias)) return 8 + Math.min(normalizedAlias.split(/\s+/).length, 3);
  const queryTokens = new Set(tokenize(normalizedQuery));
  const aliasTokens = tokenize(normalizedAlias);
  if (aliasTokens.length === 0) return 0;
  const overlap = aliasTokens.filter((token) => queryTokens.has(token)).length;
  if (overlap === 0) return 0;
  // Cross-entity contamination guard (#682 PR 2/3 R-2). For multi-token
  // aliases, partial-token overlap that hits ONLY shared common tokens
  // (like "person" in "Person-A1" / "Person-B1") would surface every
  // similarly-prefixed entity for a query that named only one. Require
  // that the overlap include at least one DISTINCTIVE alias token —
  // i.e. a token that does not also appear in any other entity's
  // alias-token vocabulary. Since this function is pure / per-pair, we
  // approximate "distinctive" by requiring the overlap to include at
  // least one token that is not a substring-of common identifier
  // affixes. The aliasTokens with length > 1 must contribute at least
  // one non-affix overlap. "Alice Example" (["alice", "example"])
  // matched by query "Tell me about Alice" → overlap = 1 on "alice",
  // and "alice" is not an affix → score = 1. "Person-A1" tokens
  // ["person", "a1"] matched by query "Who is Person-B1?" → overlap =
  // 1 on "person", and "person" IS an affix → score = 0.
  if (aliasTokens.length > 1) {
    const nonAffixOverlap = aliasTokens.filter(
      (token) => queryTokens.has(token) && !isAliasAffixToken(token),
    ).length;
    if (nonAffixOverlap === 0) return 0;
  }
  return overlap;
}
/**
 * Tokens that look like type prefixes / generic role identifiers and
 * therefore should not, on their own, count as evidence that a
 * multi-token alias matches a query (#682 PR 2/3 R-2).
 *
 * Kept as a small explicit list rather than a regex so additions are
 * deliberate. The list mirrors the entity types listed in
 * `entity-schema.ts` plus the most common generic role identifiers
 * that frequently appear as the leading token of a display name.
 */
const ALIAS_AFFIX_TOKENS = new Set<string>([
  "person", "people", "user", "users", "team", "teams",
  "project", "projects", "topic", "topics",
  "org", "orgs", "organization", "organizations", "company", "companies",
  "place", "places", "tool", "tools", "service", "services",
  "system", "systems", "agent", "agents", "bot", "bots",
]);
function isAliasAffixToken(token: string): boolean {
  return ALIAS_AFFIX_TOKENS.has(token);
}
function isLikelyInstructionLike(value: string): boolean {
  return INSTRUCTION_LIKE_RE.test(value) || METADATA_WRAPPER_RE.test(value);
}
function sanitizeEntityFact(fact: string): string {
  const sanitized = sanitizeMemoryContent(fact);
  const clean = sanitized.text.trim();
  if (!clean) return "";
  if (INSTRUCTION_LIKE_RE.test(clean) && clean.length > 100) return "";
  return clean;
}
function scoreHintSnippet(snippet: EntityHintSnippet, queryTokens: string[]): EntityHintSnippet | null {
  const normalized = normalizeEntityText(snippet.text);
  if (!normalized) return null;
  const scored = { ...snippet };
  if (isLikelyInstructionLike(scored.text) && scored.kind !== "summary") {
    scored.score -= 3;
  }
  const overlap = queryTokens.filter((token) => normalized.includes(token)).length;
  scored.score += overlap * 2;
  if (METADATA_WRAPPER_RE.test(scored.text)) scored.score -= 2;
  if (scored.text.length <= 160) scored.score += 1;
  return scored.score > 0 ? scored : null;
}
function sortTimelineEntriesDesc(
  left: EntityMentionIndexEntry["timeline"][number],
  right: EntityMentionIndexEntry["timeline"][number],
): number {
  const timestampOrder = compareEntityTimestamps(right.timestamp, left.timestamp);
  if (timestampOrder !== 0) {
    return timestampOrder;
  }
  return right.text.localeCompare(left.text);
}
function jaccardSimilarity(a: string, b: string): number {
  const aTokens = new Set(tokenize(a));
  const bTokens = new Set(tokenize(b));
  if (aTokens.size === 0 || bTokens.size === 0) return 0;
  let intersection = 0;
  for (const token of aTokens) {
    if (bTokens.has(token)) intersection += 1;
  }
  const union = new Set([...aTokens, ...bTokens]).size;
  return union === 0 ? 0 : intersection / union;
}
function buildAliasIndex(entries: EntityMentionIndexEntry[]): Map<string, EntityMentionIndexEntry[]> {
  const index = new Map<string, EntityMentionIndexEntry[]>();
  for (const entry of entries) {
    const aliases = uniqueStrings([entry.name, ...entry.aliases]).map(normalizeEntityText).filter(Boolean);
    for (const alias of aliases) {
      const existing = index.get(alias) ?? [];
      existing.push(entry);
      index.set(alias, existing);
    }
  }
  return index;
}
async function readNativeChunks(
  config: PluginConfig,
  recallNamespaces?: string[],
): Promise<NativeKnowledgeChunk[]> {
  if (!config.nativeKnowledge?.enabled) return [];
  return collectNativeKnowledgeChunks({
    workspaceDir: config.workspaceDir,
    memoryDir: config.memoryDir,
    config: config.nativeKnowledge,
    recallNamespaces: resolveNamespaceCapabilities(config).namespaces ? recallNamespaces : undefined,
    defaultNamespace: config.defaultNamespace,
  }).catch(() => []);
}
async function resolveEntityIndexStorages(
  storage: StorageManager,
  config: PluginConfig,
  recallNamespaces?: string[],
  namespaceStorage?: (namespace: string) => Promise<StorageManager>,
): Promise<StorageManager[]> {
  if (
    !resolveNamespaceCapabilities(config).namespaces ||
    !namespaceStorage ||
    !recallNamespaces ||
    recallNamespaces.length === 0
  ) {
    return [storage];
  }
  const storages: StorageManager[] = [];
  const seenDirs = new Set<string>();
  for (const namespace of uniqueStrings(recallNamespaces)) {
    try {
      const scopedStorage = await namespaceStorage(namespace);
      const storageDir = path.resolve(scopedStorage.dir);
      if (seenDirs.has(storageDir)) continue;
      seenDirs.add(storageDir);
      storages.push(scopedStorage);
    } catch {
      continue;
    }
  }
  return storages.length > 0 ? storages : [storage];
}
function entityIndexStatePath(storage: StorageManager): string {
  return path.join(storage.dir, "state", "entity-mention-index.json");
}

async function readEntityIndexState(storage: StorageManager): Promise<EntityMentionIndex | null> {
  const raw = await readFile(entityIndexStatePath(storage), "utf-8").catch(() => "");
  if (!raw) return null;
  try {
    const parsed = JSON.parse(raw) as Partial<EntityMentionIndex>;
    if (parsed.version !== ENTITY_INDEX_VERSION || !Array.isArray(parsed.entities)) return null;
    return parsed as EntityMentionIndex;
  } catch {
    return null;
  }
}
async function readCurrentPersistedEntityIndex(
  storage: StorageManager,
  config: PluginConfig,
  recallNamespaces?: string[],
  namespaceStorage?: (namespace: string) => Promise<StorageManager>,
): Promise<EntityMentionIndex | null> {
  if (
    resolveNamespaceCapabilities(config).namespaces &&
    namespaceStorage &&
    recallNamespaces &&
    recallNamespaces.length > 0
  ) {
    return null;
  }
  const index = await readEntityIndexState(storage);
  if (!entityMentionPersistedIndexReadable(storage.dir) || !index || index.entityStatusVersion !== storage.getMemoryStatusVersion()) {
    return null;
  }
  return index;
}
type CarriedMemorySnippets = Map<string, { memorySnippets: string[]; memorySnippetOrigins?: (string | undefined)[] }>;

function carriedMemorySnippets(index: EntityMentionIndex): CarriedMemorySnippets {
  return new Map(index.entities.map((entry) => [entry.canonicalId, {
    memorySnippets: entry.memorySnippets.slice(),
    memorySnippetOrigins: entry.memorySnippetOrigins?.slice(),
  }]));
}

function nativeEntityIndexRevision(chunks: NativeKnowledgeChunk[]): string {
  const projection = chunks.map((chunk) => [
    chunk.chunkId,
    chunk.sourcePath,
    chunk.title,
    chunk.sourceKind,
    uniqueStrings(chunk.aliases ?? []),
    compactLine(chunk.content, 180),
    chunk.derivedDate ?? null,
  ]);
  return createHash("sha256").update(JSON.stringify(projection)).digest("hex");
}

async function writeEntityIndexState(
  storage: StorageManager,
  index: EntityMentionIndex,
  persistGeneration: number,
): Promise<void> {
  await writePersistedEntityMentionIndex(storage.dir, persistGeneration, JSON.stringify(index, null, 2) + "\n");
}

function nativePseudoCanonicalId(chunk: NativeKnowledgeChunk): string {
  return `native:${createHash("sha256").update(chunk.sourcePath).digest("hex").slice(0, 12)}`;
}

function createPseudoNativeEntry(chunk: NativeKnowledgeChunk): EntityMentionIndexEntry {
  const canonicalId = nativePseudoCanonicalId(chunk);
  return {
    canonicalId,
    name: chunk.title,
    type: chunk.sourceKind,
    aliases: uniqueStrings(chunk.aliases ?? []),
    facts: [],
    structuredSections: [],
    timelineFacts: [],
    timeline: [],
    relationships: [],
    activity: [],
    factCount: 0,
    memorySnippets: [],
    nativeChunks: [
      {
        chunkId: chunk.chunkId,
        title: chunk.title,
        sourceKind: chunk.sourceKind,
        sourcePath: chunk.sourcePath,
        snippet: compactLine(chunk.content, 180),
        derivedDate: chunk.derivedDate,
      },
    ],
  };
}

function mergeNativeChunk(entry: EntityMentionIndexEntry, chunk: NativeKnowledgeChunk): void {
  const existing = entry.nativeChunks.find((item) => item.chunkId === chunk.chunkId);
  if (existing) return;
  entry.nativeChunks.push({
    chunkId: chunk.chunkId,
    title: chunk.title,
    sourceKind: chunk.sourceKind,
    sourcePath: chunk.sourcePath,
    snippet: compactLine(chunk.content, 180),
    derivedDate: chunk.derivedDate,
  });
  entry.aliases = uniqueStrings([...entry.aliases, ...(chunk.aliases ?? [])]);
}

function hasFreshNativeExplicitMention(
  index: EntityMentionIndex,
  nativeChunks: NativeKnowledgeChunk[],
  query: string,
): boolean {
  if (nativeChunks.length === 0) return false;
  const nativeCanonicalIds = new Set(nativeChunks.map(nativePseudoCanonicalId));
  const freshNativeIndex: EntityMentionIndex = {
    ...index,
    entities: [
      ...index.entities.filter((entry) => !nativeCanonicalIds.has(entry.canonicalId)),
      ...nativeChunks.map(createPseudoNativeEntry),
    ],
  };
  return resolveLanguageIndependentExplicitCandidates(freshNativeIndex, query).length > 0;
}

async function buildEntityMentionIndex(
  storage: StorageManager,
  config: PluginConfig,
  recallNamespaces?: string[],
  namespaceStorage?: (namespace: string) => Promise<StorageManager>,
  nativeChunksOverride?: NativeKnowledgeChunk[],
  resolvedStorages?: StorageManager[],
  abortSignal?: AbortSignal,
  carrySnippets?: CarriedMemorySnippets,
): Promise<EntityMentionIndex> {
  checkEntityRecallAbort(abortSignal);
  const storages = resolvedStorages ?? await resolveEntityIndexStorages(
    storage,
    config,
    recallNamespaces,
    namespaceStorage,
  );
  const shouldPersistIndex =
    storages.length === 1 && path.resolve(storages[0]!.dir) === path.resolve(storage.dir);
  const persistGeneration = entityMentionCacheGeneration(storage.dir);
  const entityStatusVersionBefore = shouldPersistIndex ? storage.getMemoryStatusVersion() : undefined;
  const [previousIndex, entityFileSets, memorySets, nativeChunks] = await Promise.all([
    shouldPersistIndex ? readEntityIndexState(storage) : Promise.resolve(null),
    Promise.all(storages.map((scopedStorage) => scopedStorage.readAllEntityFiles({ abortSignal }))),
    carrySnippets
      ? Promise.resolve([])
      : Promise.all(storages.map((scopedStorage) => scopedStorage.readAllMemories({ abortSignal }))),
    nativeChunksOverride ? Promise.resolve(nativeChunksOverride) : readNativeChunks(config, recallNamespaces),
  ]);
  // The bulk reads now stop at their own scan boundaries (issue #2307); this
  // checkpoint still guards the (larger) indexing pass over their results.
  checkEntityRecallAbort(abortSignal);
  // Pair each entity with the storage that owns it (#1534): canonical ids must
  // reflect that store's aliases and historical migration mappings, never another
  // namespace's.
  const entityRecords = entityFileSets.flatMap((set, index) =>
    set.map((entity) => ({ entity, storage: storages[index]! })),
  );
  const memories = memorySets.flat();

  // The two passes over the corpus below never await real I/O, so without an
  // explicit yield they hold the event loop and no recall section deadline can
  // fire during them (issue #2291).
  let scanned = 0;
  const entities = new Map<string, EntityMentionIndexEntry>();
  for (const { entity, storage: entityStorage } of entityRecords) {
    scanned += 1;
    await yieldEntityRecallScanEvery(scanned, abortSignal);
    const canonicalId =
      typeof entityStorage.normalizeEntityName === "function"
        ? entityStorage.normalizeEntityName(entity.name, entity.type)
        : normalizeEntityName(entity.name, entity.type, entityStorage.entityAliases);
    const rawStructuredSections = entity.structuredSections ?? [];
    const rawBeliefLedgerFactKeys = beliefLedgerFactKeys(rawStructuredSections);
    const sanitizedFacts = entity.facts
      .map((fact) => sanitizeEntityFact(fact))
      .filter(Boolean)
      .filter((fact) => !rawBeliefLedgerFactKeys.has(normalizeEntityText(fact)))
      .map((fact) => compactLine(fact, 180));
    const { facts: timelineFacts, origins: timelineFactOrigins } = sanitizeOriginatedFacts(
      entity.timeline,
      sanitizeEntityFact,
      compactLine,
      true,
    );
    const structuredSections = buildOriginStructuredSections(
      rawStructuredSections,
      recallFactsForStructuredSection,
      sanitizeEntityFact,
      compactLine,
    );
    entities.set(canonicalId, {
      canonicalId,
      name: entity.name,
      type: entity.type,
      aliases: uniqueStrings(entity.aliases),
      summary: entity.synthesis?.trim() || entity.summary?.trim() || undefined,
      facts: sanitizedFacts,
      timelineFacts,
      ...(timelineFactOrigins.some((origin) => origin !== undefined) ? { timelineFactOrigins } : {}),
      structuredSections,
      timeline: entity.timeline.map((entry) => ({ ...entry })),
      relationships: entity.relationships.map((relationship) => ({ ...relationship })),
      activity: entity.activity.map((activity) => ({ ...activity })),
      factCount: sanitizedFacts.length,
      memorySnippets: [],
      nativeChunks: [],
    });
  }

  scanned = 0;
  const pendingSnippetReconcile = carrySnippets
    ? applyCarriedMemorySnippets(entities.values(), carrySnippets)
    : false;
  if (!carrySnippets) {
    for (const memory of memories) {
      scanned += 1;
      await yieldEntityRecallScanEvery(scanned, abortSignal);
      const entry = typeof memory.frontmatter.entityRef === "string" ? entities.get(memory.frontmatter.entityRef) : undefined;
      if (!entry) continue;
      const snippet = await readMemorySnippet(memory);
      if (entry.memorySnippets.includes(snippet)) continue;
      entry.memorySnippets.push(snippet);
      entry.memorySnippetOrigins = [...(entry.memorySnippetOrigins ?? []), memory.frontmatter.origin];
    }
  }
  // Each remaining phase is another synchronous pass over the whole index
  // (alias map, native-chunk merge, sort, two full serializations). Yield between
  // them so a section deadline can fire between passes instead of only after all
  // of them (issue #2291).
  await yieldEntityRecallScan(abortSignal);
  const aliasIndex = buildAliasIndex([...entities.values()]);
  for (const chunk of nativeChunks) {
    const existingPseudo = entities.get(nativePseudoCanonicalId(chunk));
    if (existingPseudo) {
      mergeNativeChunk(existingPseudo, chunk);
      continue;
    }
    const candidateAliases = uniqueStrings([chunk.title, ...(chunk.aliases ?? [])]).map(normalizeEntityText).filter(Boolean);
    let matched = false;
    for (const alias of candidateAliases) {
      for (const entry of aliasIndex.get(alias) ?? []) {
        mergeNativeChunk(entry, chunk);
        matched = true;
      }
    }
    if (matched) continue;
    const pseudoEntry = createPseudoNativeEntry(chunk);
    entities.set(pseudoEntry.canonicalId, pseudoEntry);
  }

  await yieldEntityRecallScan(abortSignal);
  const sortedEntities = [...entities.values()].sort((left, right) => left.name.localeCompare(right.name));
  await yieldEntityRecallScan(abortSignal);
  const previousEntities = previousIndex ? JSON.stringify(previousIndex.entities) : "";
  await yieldEntityRecallScan(abortSignal);
  const nextEntities = JSON.stringify(sortedEntities);
  const entityStatusVersionAfter = shouldPersistIndex ? storage.getMemoryStatusVersion() : undefined;
  const canPersistIndex = shouldPersistIndex && entityStatusVersionBefore === entityStatusVersionAfter && persistGeneration === entityMentionCacheGeneration(storage.dir);
  const index: EntityMentionIndex = {
    version: ENTITY_INDEX_VERSION,
    updatedAt:
      previousIndex && previousEntities === nextEntities
        ? previousIndex.updatedAt
        : new Date().toISOString(),
    entityStatusVersion: canPersistIndex ? entityStatusVersionAfter : undefined,
    entities: sortedEntities,
  };
  if (canPersistIndex) {
    checkEntityRecallAbort(abortSignal);
    await writeEntityIndexState(storage, index, persistGeneration);
  }
  if (pendingSnippetReconcile) index.pendingSnippetReconcile = true;
  return index;
}

function resolveExplicitCandidates(
  index: EntityMentionIndex,
  query: string,
): EntityCandidate[] {
  const candidates: EntityCandidate[] = [];
  for (const entry of index.entities) {
    const aliases = uniqueStrings([entry.name, ...entry.aliases]);
    let bestAlias = "";
    let bestScore = 0;
    for (const alias of aliases) {
      const score = scoreAliasMatch(query, alias);
      if (score > bestScore) {
        bestAlias = alias;
        bestScore = score;
      }
    }
    if (bestScore <= 0) continue;
    candidates.push({ entry, alias: bestAlias, score: bestScore, source: "query" });
  }
  return candidates.sort((left, right) => right.score - left.score);
}

const EXPLICIT_ENTITY_MENTION_SCORE = 9;

const IMPLICIT_ENTITY_STOP_WORDS = new Set([
  "a",
  "an",
  "and",
  "are",
  "as",
  "at",
  "be",
  "by",
  "can",
  "do",
  "for",
  "from",
  "has",
  "how",
  "i",
  "if",
  "in",
  "is",
  "it",
  "me",
  "my",
  "of",
  "on",
  "or",
  "the",
  "to",
  "was",
  "what",
  "when",
  "where",
  "who",
  "why",
  "with",
  "you",
  "your",
]);

function isDistinctiveImplicitAlias(normalizedAlias: string): boolean {
  const tokens = normalizedAlias.split(/\s+/).filter(Boolean);
  if (tokens.length > 1 && tokens.every((token) => IMPLICIT_ENTITY_STOP_WORDS.has(token))) return false;
  if (tokens.length !== 1) return true;
  const token = tokens[0]!;
  return Array.from(token).length > 1 && !IMPLICIT_ENTITY_STOP_WORDS.has(token);
}

function isShortLatinAlias(alias: string): boolean {
  return /^[A-Za-z]{2,3}$/.test(alias.trim());
}

function hasStrongShortLatinAliasMention(query: string, alias: string): boolean {
  const normalizedAlias = alias.trim();
  const titleCaseAlias = `${normalizedAlias[0]!.toUpperCase()}${normalizedAlias.slice(1).toLowerCase()}`;
  const forms = new Set([normalizedAlias, normalizedAlias.toUpperCase(), titleCaseAlias]);
  return [...forms].some((form) => {
    if (form === form.toLowerCase()) return false;
    const escaped = form.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
    return new RegExp(`(?:^|[^A-Za-z0-9])${escaped}(?:$|[^A-Za-z0-9])`).test(query);
  });
}

function resolveLanguageIndependentExplicitCandidates(
  index: EntityMentionIndex,
  query: string,
): EntityCandidate[] {
  const canonicalIdsByAlias = new Map<string, Set<string>>();
  for (const entry of index.entities) {
    for (const alias of uniqueStrings([entry.name, ...entry.aliases])) {
      const normalizedAlias = normalizeEntityText(alias);
      if (!normalizedAlias) continue;
      const canonicalIds = canonicalIdsByAlias.get(normalizedAlias) ?? new Set<string>();
      canonicalIds.add(entry.canonicalId);
      canonicalIdsByAlias.set(normalizedAlias, canonicalIds);
    }
  }

  const candidates: EntityCandidate[] = [];
  for (const entry of index.entities) {
    let bestAlias = "";
    let bestScore = 0;
    for (const alias of uniqueStrings([entry.name, ...entry.aliases])) {
      const normalizedAlias = normalizeEntityText(alias);
      const score = scoreAliasMatch(query, alias);
      if (
        !normalizedAlias ||
        !isDistinctiveImplicitAlias(normalizedAlias) ||
        (isShortLatinAlias(alias) && !hasStrongShortLatinAliasMention(query, alias)) ||
        canonicalIdsByAlias.get(normalizedAlias)?.size !== 1 ||
        score < EXPLICIT_ENTITY_MENTION_SCORE ||
        score <= bestScore
      ) {
        continue;
      }
      bestAlias = alias;
      bestScore = score;
    }
    if (bestAlias) {
      candidates.push({ entry, alias: bestAlias, score: bestScore, source: "query" });
    }
  }

  return candidates.sort(
    (left, right) => right.score - left.score || left.entry.name.localeCompare(right.entry.name),
  );
}

function resolveRecentTurnCandidates(
  index: EntityMentionIndex,
  transcriptEntries: TranscriptEntry[],
  recentTurns: number,
): EntityCandidate[] {
  if (recentTurns <= 0 || transcriptEntries.length === 0) return [];
  const recentEntries = transcriptEntries.slice(-recentTurns);
  const candidates = new Map<string, EntityCandidate>();
  for (let indexOffset = recentEntries.length - 1; indexOffset >= 0; indexOffset -= 1) {
    const turn = recentEntries[indexOffset];
    const recencyBoost = recentEntries.length - indexOffset;
    const roleWeight = turn.role === "user" ? 2 : turn.role === "assistant" ? -1 : 0;
    for (const entry of index.entities) {
      const aliases = uniqueStrings([entry.name, ...entry.aliases]);
      for (const alias of aliases) {
        const score = scoreAliasMatch(turn.content, alias);
        if (score <= 0) continue;
        const current = candidates.get(entry.canonicalId);
        const weightedScore = score + Math.max(0, 6 - recencyBoost) + roleWeight;
        if (!current || weightedScore > current.score) {
          candidates.set(entry.canonicalId, {
            entry,
            alias,
            score: weightedScore,
            source: "recent_turn",
          });
        }
      }
    }
  }
  return [...candidates.values()].sort((left, right) => right.score - left.score);
}

async function readMemorySnippet(memory: MemoryFile): Promise<string> {
  const content = memory.content.replace(/\s+/g, " ").trim();
  return compactLine(content, 180);
}

async function buildHintSnippets(
  entry: EntityMentionIndexEntry,
  queryTokens: string[],
  mode: EntityQueryMode,
  maxSupportingFacts: number,
  requestedSectionKeys: Set<string>,
): Promise<EntityHintSnippet[]> {
  const snippets: EntityHintSnippet[] = [];
  const aliasTokens = new Set(tokenize(uniqueStrings([entry.name, ...entry.aliases]).join(" ")));
  if (entry.summary) {
    snippets.push({ text: compactLine(entry.summary, 180), score: 10, kind: "summary" });
  }
  if (requestedSectionKeys.size > 0) {
    for (const section of entry.structuredSections) {
      if (!requestedSectionKeys.has(normalizeEntityText(section.key).replace(/\s+/g, "_"))) continue;
      for (const [index, fact] of section.facts.entries()) {
        snippets.push({
          text: fact,
          score: mode === "direct" ? 8 : 9,
          kind: "section",
          origin: section.factOrigins?.[index],
        });
      }
    }
  } else {
    for (const [index, fact] of entry.timelineFacts.entries()) {
      snippets.push({
        text: fact,
        score: mode === "direct" ? 6 : 7,
        kind: "fact",
        origin: entry.timelineFactOrigins?.[index],
      });
    }
    for (const section of entry.structuredSections) {
      for (const [index, fact] of section.facts.entries()) {
        const normalizedFact = normalizeEntityText(fact);
        const hasNonAliasQueryOverlap = queryTokens.some((token) =>
          !aliasTokens.has(token) && normalizedFact.includes(token)
        );
        if (entry.timelineFacts.length > 0 && !hasNonAliasQueryOverlap) {
          continue;
        }
        snippets.push({
          text: fact,
          score: mode === "direct" ? 6 : 7,
          kind: "fact",
          origin: section.factOrigins?.[index],
        });
      }
    }
    if (entry.timelineFacts.length === 0 && entry.structuredSections.length === 0) {
      for (const fact of entry.facts) {
        if (!fact.trim()) continue;
        snippets.push({ text: fact, score: mode === "direct" ? 6 : 7, kind: "fact" });
      }
    }
  }

  if (requestedSectionKeys.size === 0) {
    for (const relationship of entry.relationships) {
      snippets.push({
        text: compactLine(relationLine(entry, relationship), 180),
        score: mode === "direct" && entry.type.toLowerCase() === "person" ? 6 : 4,
        kind: "relationship",
      });
    }

    for (const activity of entry.activity) {
      snippets.push({
        text: compactLine(`${activity.date}: ${activity.note}`, 180),
        score: 4,
        kind: "activity",
      });
    }

    for (const [index, memorySnippet] of entry.memorySnippets.slice(0, Math.min(maxSupportingFacts, 4)).entries()) {
      snippets.push({ text: memorySnippet, score: 5, kind: "memory", origin: entry.memorySnippetOrigins?.[index] });
    }

    for (const chunk of entry.nativeChunks) {
      snippets.push({
        text: compactLine(chunk.snippet, 180),
        score: 3,
        kind: "native",
      });
    }
  }

  const deduped = new Map<string, EntityHintSnippet>();
  for (const snippet of snippets) {
    const scored = scoreHintSnippet(snippet, queryTokens);
    if (!scored) continue;
    const normalized = normalizeEntityText(scored.text);
    const existing = deduped.get(normalized);
    if (!existing) {
      deduped.set(normalized, scored);
    } else if (existing.origin !== scored.origin) {
      deduped.set(normalized, { ...(scored.score > existing.score ? scored : existing), origin: undefined });
    } else if (scored.score > existing.score) {
      deduped.set(normalized, scored);
    }
  }

  return [...deduped.values()]
    .filter((snippet) => snippet.score > 0)
    .sort((left, right) => right.score - left.score)
    .slice(0, maxSupportingFacts);
}

function summarizeUncertainty(snippets: EntityHintSnippet[]): string | null {
  const direct = snippets.filter((snippet) =>
    snippet.kind === "summary"
    || snippet.kind === "fact"
    || snippet.kind === "section"
    || snippet.kind === "memory"
  );
  if (direct.length < 2) return null;
  for (let index = 0; index < direct.length; index += 1) {
    for (let compare = index + 1; compare < direct.length; compare += 1) {
      if (jaccardSimilarity(direct[index].text, direct[compare].text) < 0.2) {
        return "Evidence is mixed across stored facts; treat the hints below as partial and verify before answering definitively.";
      }
    }
  }
  return null;
}

function formatEntityHintSection(
  candidates: Array<{
    candidate: EntityCandidate;
    snippets: EntityHintSnippet[];
    uncertainty: string | null;
  }>,
  queryTokens: string[],
  mode: EntityQueryMode,
  maxRelatedEntities: number,
  maxChars: number,
  originAuthorityEnabled: boolean, untrustedOrigins: readonly string[],
): string | null {
  if (candidates.length === 0) return null;
  const lines: string[] = ["## entity_answer_hints", ""];
  // #1955 review: non-native snippet kinds may embed extraction-written content
  // without per-field origin — fence as unknown (least privilege; plumbing #2397).
  const renderSnippet = (snippet: EntityHintSnippet): string => snippet.kind !== "native"
    ? renderAuthorityBoundContent(snippet.text, snippet.origin, { enabled: originAuthorityEnabled, untrustedOrigins }) : snippet.text;
  // (see comment above)
  // #1955 review: inline fields (names/types/aliases/targets) cannot carry the
  // multi-line block fence without collapsing the hint list structure —
  // per-field origin plumbing is tracked in #2397.
  for (const { candidate, snippets, uncertainty } of candidates) {
    const hasSummary = Boolean(candidate.entry.summary?.trim());
    const preferredTopSnippets = hasSummary
      ? snippets.filter((snippet) => snippet.kind !== "fact")
      : snippets;
    let topSnippets = (
      preferredTopSnippets.length > 0 ? preferredTopSnippets : snippets
    ).slice(0, 3);
    const buildTimelineSnippets = (seedExcludedTexts: Set<string>): EntityHintSnippet[] => {
      const explicitTimelinePool = dedupeHintSnippetsByText(
        (candidate.entry.timeline ?? [])
          .slice()
          .sort(sortTimelineEntriesDesc)
          .map((entry) => {
            const text = sanitizeEntityFact(entry.text);
            return text
              ? scoreHintSnippet({
                text: compactLine(text, 180),
                score: 7,
                kind: "activity" as const,
                origin: entry.origin,
              }, queryTokens)
              : null;
          })
          .filter((snippet): snippet is EntityHintSnippet => snippet !== null)
          .filter((snippet) => !seedExcludedTexts.has(normalizeEntityText(snippet.text))),
      ).slice(0, 2);
      const activityTimelinePool = dedupeHintSnippetsByText(
        snippets
          .filter((snippet) => (
            snippet.kind === "activity" || snippet.kind === "memory"
          ) && !seedExcludedTexts.has(normalizeEntityText(snippet.text))),
      ).slice(0, 2);
      return explicitTimelinePool.length > 0
        ? explicitTimelinePool
        : activityTimelinePool.length > 0
          ? activityTimelinePool
          : dedupeHintSnippetsByText(
            snippets
              .filter((snippet) => (
                snippet.kind === "fact" || snippet.kind === "summary"
              ) && !seedExcludedTexts.has(normalizeEntityText(snippet.text))),
          ).slice(0, 2);
    };
    const baseTopSnippetTexts = new Set(topSnippets.map((snippet) => normalizeEntityText(snippet.text)));
    const timelinePool = mode !== "direct" ? buildTimelineSnippets(baseTopSnippetTexts) : [];
    if (mode !== "direct" && hasSummary && topSnippets.length < 2) {
      if (timelinePool.length > 0) {
        topSnippets = [...topSnippets, timelinePool[0]!].slice(0, 3);
      }
    }
    const topSnippetTexts = new Set(topSnippets.map((snippet) => normalizeEntityText(snippet.text)));
    lines.push(`- target: ${candidate.entry.name} (${candidate.entry.type})`);
    lines.push(`- resolution: ${candidate.source === "recent_turn" ? "carried forward from recent turns via alias" : "matched alias"} "${candidate.alias}"${candidate.source === "recent_turn" ? "" : " in the query"}`);
    if (uncertainty) lines.push(`- uncertainty: ${uncertainty}`);
    if (topSnippets.length > 0) {
      lines.push("- likely answer:");
      for (const snippet of topSnippets) {
        lines.push(`  - ${renderSnippet(snippet)}`);
      }
    }
    if (mode !== "direct") {
      const fallbackTimeline = timelinePool.filter(
        (snippet) => !topSnippetTexts.has(normalizeEntityText(snippet.text)),
      );
      if (fallbackTimeline.length > 0) {
        lines.push("- recent timeline:");
        for (const snippet of fallbackTimeline) {
          lines.push(`  - ${renderSnippet(snippet)}`);
        }
      }
    }
    const related = candidate.entry.relationships.slice(0, maxRelatedEntities).map((relationship) => relationship.target);
    if (related.length > 0) {
      lines.push(`- related entities: ${related.join(", ")}`);
    }
    lines.push(`- support counts: facts=${candidate.entry.factCount}, memories=${candidate.entry.memorySnippets.length}, native=${candidate.entry.nativeChunks.length}`);
    lines.push("");
  }

  let result = lines.join("\n");
  if (result.length > maxChars) {
    result = `${truncateGraphemeSafe(result, Math.max(0, maxChars - 15)).trimEnd()}\n\n...(trimmed)\n`;
  }
  return result.trim().length > 0 ? result.trimEnd() : null;
}

export async function buildEntityRecallSection(options: BuildEntityRecallSectionOptions): Promise<string | null> {
  // Checkpoints sit at the real I/O boundaries below (persisted-index read,
  // native-chunk read, storage resolution, index build).  The per-candidate
  // formatting that follows never awaits real I/O, so a deadline that fires
  // during a scan is observed here (issue #2291).
  checkEntityRecallAbort(options.abortSignal);
  const prefixedMode = detectEntityQueryMode(options.query);
  // #2193: in zero-pronoun scripts a short question with no entity name
  // never trips a pronoun word list, so the structural signal routes it
  // into the same coreference path as an English "what about him?".
  // Latin-script queries stay on the cue tables / English rules so the
  // generic technical-question guard keeps working. Resolution gates.
  const structuralFollowUp = prefixedMode === null
    && isStructuralEntityFollowUpQuery(
      options.query,
      options.recentTurns > 0 && options.transcriptEntries.length > 0,
    );
  const earlyMode = prefixedMode ?? (structuralFollowUp ? "follow_up" : null);
  const persistedIndex = earlyMode
    ? null
    : await readCurrentPersistedEntityIndex(
      options.storage,
      options.config,
      options.recallNamespaces,
      options.namespaceStorage,
    );
  checkEntityRecallAbort(options.abortSignal);
  let nativeChunks: NativeKnowledgeChunk[] | undefined;
  if (
    !earlyMode &&
    persistedIndex &&
    resolveLanguageIndependentExplicitCandidates(persistedIndex, options.query).length === 0
  ) {
    nativeChunks = await readNativeChunks(options.config, options.recallNamespaces);
    if (!hasFreshNativeExplicitMention(persistedIndex, nativeChunks, options.query)) {
      return entityRecallSectionAbsent(options.abortSignal);
    }
  }
  const namespaceScoped =
    resolveNamespaceCapabilities(options.config).namespaces &&
    options.namespaceStorage !== undefined &&
    (options.recallNamespaces?.length ?? 0) > 0;
  if (namespaceScoped) {
    nativeChunks = await readNativeChunks(options.config, options.recallNamespaces);
  }
  const resolvedStorages = namespaceScoped
    ? await resolveEntityIndexStorages(
      options.storage,
      options.config,
      options.recallNamespaces,
      options.namespaceStorage,
    )
    : undefined;
  if (!nativeChunks) {
    nativeChunks = await readNativeChunks(options.config, options.recallNamespaces);
  }
  const indexStorages = resolvedStorages ?? [options.storage];
  const index = await resolveEntityMentionIndex({
    scopeKey: entityMentionScopeKey(options.recallNamespaces, indexStorages, nativeEntityIndexRevision(nativeChunks)),
    currentIdentity: () => entityMentionIdentity(indexStorages),
    abortSignal: options.abortSignal,
    buildFull: (signal) => buildEntityMentionIndex(
      options.storage,
      options.config,
      options.recallNamespaces,
      options.namespaceStorage,
      nativeChunks,
      indexStorages,
      signal,
    ),
    rebuildEntities: (previous, signal) => buildEntityMentionIndex(
      options.storage,
      options.config,
      options.recallNamespaces,
      options.namespaceStorage,
      nativeChunks,
      indexStorages,
      signal,
      carriedMemorySnippets(previous),
    ),
  });
  // Candidate resolution is another synchronous pass over every entity and alias,
  // reached even on a cache hit that did no I/O at all — so yield here too, or a
  // cached corpus could still hold the loop past the section budget (issue #2291).
  await yieldEntityRecallScan(options.abortSignal);
  const explicitCandidates = resolveExplicitCandidates(index, options.query);
  await yieldEntityRecallScan(options.abortSignal);
  const queryCandidates = prefixedMode
    ? explicitCandidates
    : resolveLanguageIndependentExplicitCandidates(index, options.query);
  if (
    queryCandidates.length === 0
    && /^what does (?:this|that|it|the|a|an|my|our|your|their)\b/i.test(normalizeEntityText(options.query))
  ) {
    return entityRecallSectionAbsent(options.abortSignal);
  }

  // Explicit mentions keep #2161 behavior (direct mode) even when the
  // structural follow-up signal also fired; only name-less short questions
  // fall through to coreference.
  const mode = prefixedMode
    ?? (queryCandidates.length > 0
      ? "direct"
      : structuralFollowUp
        ? "follow_up"
        : null);
  if (!mode) return entityRecallSectionAbsent(options.abortSignal);

  const candidates = queryCandidates.length > 0
    ? queryCandidates
    : resolveRecentTurnCandidates(index, options.transcriptEntries, options.recentTurns);

  if (candidates.length === 0) return entityRecallSectionAbsent(options.abortSignal);

  const queryTokens = tokenize(options.query);
  const candidateLimit = queryCandidates.length === 0 && mode === "follow_up"
    ? 1
    : options.maxHints;
  const rankedCandidates = candidates.slice(0, candidateLimit);
  const enriched = await Promise.all(
    rankedCandidates.map(async (candidate) => {
      const requestedSectionKeys = new Set(
        resolveRequestedEntitySectionKeys(
          options.query,
          candidate.entry.type,
          candidate.entry.structuredSections,
          options.config.entitySchemas,
        ),
      );
      const snippets = await buildHintSnippets(
        candidate.entry,
        queryTokens,
        mode,
        options.maxSupportingFacts,
        requestedSectionKeys,
      );
      return {
        candidate,
        snippets,
        uncertainty: summarizeUncertainty(snippets),
      };
    }),
  );

  const section = formatEntityHintSection(
    enriched,
    queryTokens,
    mode,
    options.maxRelatedEntities,
    options.maxChars,
    options.originAuthorityEnabled === true,
    options.untrustedOrigins ?? [],
  );
  // `entityRecallSectionAbsent` so a cancelled build is not recorded as a
  // successful section that simply found no entities.
  if (!section) return entityRecallSectionAbsent(options.abortSignal);
  return section;
}

export async function readRecentEntityTranscriptEntries(
  transcriptEntriesPromise: Promise<TranscriptEntry[]>,
  recentTurns: number,
): Promise<TranscriptEntry[]> {
  if (recentTurns <= 0) return [];
  const transcriptEntries = await transcriptEntriesPromise.catch(() => []);
  if (transcriptEntries.length === 0) return [];
  return transcriptEntries.slice(-Math.max(1, recentTurns * 2));
}

export const entityIndexVersion = ENTITY_INDEX_VERSION;
export const entityRecentTranscriptLookbackHours = RECENT_TRANSCRIPT_LOOKBACK_HOURS;

import { buildEvidencePack, type EvidencePackItem } from "./evidence-pack.js";
import type { ExplicitCueRecallEngine } from "./explicit-cue-recall.js";
import { lcmEvidenceIdentity } from "./lcm/evidence-identity.js";

import {
  unifiedDedupeAndRank,
  type RankedEvidenceItem,
} from "./recall-pipeline-stages.js";

import { shouldRecallEventOrderEvidence } from "./event-order-query.js";
export { shouldRecallEventOrderEvidence };


export interface EventOrderRecallOptions {
  engine: ExplicitCueRecallEngine | null | undefined;
  // event-order reads a SINGLE LCM session key. Unlike the relevance-ranked
  // sections, its evidence must not be merged across the #1505 fallback key set:
  // `turn_index` is local to each LCM `session_id`, so interleaving keys would
  // misstate chronology. The orchestrator reads the ordered key set via
  // first-non-empty instead (see the event-order call site).
  sessionId?: string;
  query: string;
  maxChars: number;
  maxItemChars?: number;
  maxScanWindowTurns?: number;
  maxScanWindowTokens?: number;
  maxItems?: number;
  title?: string;
}

const DEFAULT_SCAN_WINDOW_TURNS = 12;
const DEFAULT_SCAN_WINDOW_TOKENS = 24_000;
const DEFAULT_MAX_ITEMS = 24;


export async function buildEventOrderRecallSection(
  options: EventOrderRecallOptions,
): Promise<string> {
  const budget = normalizePositiveInteger(options.maxChars);
  const maxItems = normalizePositiveInteger(options.maxItems ?? DEFAULT_MAX_ITEMS);
  // event-order reads a SINGLE session key (`turn_index` is local to each LCM
  // `session_id`, so chronology can't be merged across the #1505 fallback set —
  // the orchestrator drives the ordered key set via first-non-empty instead).
  if (!options.engine || !options.sessionId || budget <= 0) {
    return "";
  }
  if (maxItems <= 0) {
    return "";
  }
  if (!shouldRecallEventOrderEvidence(options.query)) {
    return "";
  }

  const items = await collectEventOrderItems(options);
  const ranked = rankAndSelectEventOrderItems(items, options, maxItems);
  if (ranked.length === 0) {
    return "";
  }

  const title = options.title ?? "Chronological event evidence";

  // Issue #1539 step 4 (the ONE declared behavior change): budget the outline
  // BEFORE building evidence, matching guidance/targeted-fact. Previously
  // event-order built the evidence pack at the FULL budget, then appended the
  // chronology outline, then clipped the total — which could silently exceed
  // maxChars (the outline consumed space the evidence pack had already filled).
  // Now the summary (incl. outline) is computed first and its length subtracted
  // from the evidence budget, so evidence + summary = budget exactly.
  const requested = parseRequestedItemCount(options.query);
  const outlineSource = requested
    ? rankEventOrderItemsForOutline(items, options.query).slice(0, maxItems)
    : ranked;
  const outline = buildChronologyOutline(outlineSource, options.query, requested);
  const summary = [
    "Chronological evidence is sorted by turn number.",
    requested ? `Requested item count: ${requested}.` : "",
    outline,
    "Use these turns to preserve the order in which the user raised the topics.",
  ].filter(Boolean).join(" ");
  const summaryInsert = `\n\n${summary}`;
  const evidenceBudget = Math.max(0, budget - summaryInsert.length);
  const evidence = buildEvidencePack(ranked, {
    title,
    maxChars: evidenceBudget,
    maxItemChars: options.maxItemChars,
  });
  if (!evidence) {
    // If no evidence fit the residual budget, still emit the summary clipped to
    // budget (matches targeted-fact's empty-evidence-with-summary fallback).
    return clipSectionToBudget(`## ${title}${summaryInsert}`, budget);
  }
  return clipSectionToBudget(
    evidence.replace(`## ${title}`, `## ${title}${summaryInsert}`),
    budget,
  );
}

async function collectEventOrderItems(
  options: EventOrderRecallOptions,
): Promise<EvidencePackItem[]> {
  const engine = options.engine;
  if (!engine || !engine.getStats || !options.sessionId) {
    return [];
  }

  const stats = await engine.getStats(options.sessionId);
  const maxTurn = typeof stats.maxTurnIndex === "number"
    ? stats.maxTurnIndex
    : stats.totalMessages - 1;
  if (maxTurn < 0) return [];

  const items: EvidencePackItem[] = [];
  const seen = new Set<string>();
  const windowTurns = Math.max(
    1,
    normalizePositiveInteger(options.maxScanWindowTurns ?? DEFAULT_SCAN_WINDOW_TURNS),
  );
  const windowTokens = Math.max(
    1,
    normalizePositiveInteger(options.maxScanWindowTokens ?? DEFAULT_SCAN_WINDOW_TOKENS),
  );

  for (let fromTurn = 0; fromTurn <= maxTurn; fromTurn += windowTurns) {
    const toTurn = Math.min(maxTurn, fromTurn + windowTurns - 1);
    const messages = await engine.expandContext(
      options.sessionId,
      fromTurn,
      toTurn,
      windowTokens,
    );
    for (const message of messages) {
      const identity = lcmEvidenceIdentity(message, options.sessionId);
      const id = identity.id;
      if (seen.has(id)) continue;
      if (!isEventOrderCandidate(message.content, message.role, options.query)) continue;
      seen.add(id);
      items.push({
        ...identity,
        sessionId: message.session_id ?? options.sessionId,
        turnIndex: message.turn_index,
        role: message.role,
        content: appendChronologicalCues(message.content, options.query),
      });
    }
  }

  return items;
}

function rankAndSelectEventOrderItems(
  items: EvidencePackItem[],
  options: EventOrderRecallOptions,
  maxItems: number,
): RankedEvidenceItem[] {
  const requested = parseRequestedItemCount(options.query);
  // Issue #1539 PR6: rank + threshold-filter + sort now route through the
  // unified spine. Event-order's three declared divergences are named config
  // fields: rankThreshold:6 (was an undocumented inline .filter), ASC sort
  // direction (was a byte-identical comparator copy with flipped direction),
  // and dedupByContent:false (event-order keeps distinct turns — turn_index is
  // local to each session_id, so chronology must not collapse same-body turns).
  // The spine's id-dedup is a no-op here: event-order reads a single session
  // with unique per-turn ids (no cross-key merge, per the #1505 opt-out).
  // Content is already cue-appended during collection; the spine scores on the
  // (already-transformed) item.content, matching the prior inline behavior.
  const rankedByScore = unifiedDedupeAndRank(items, {
    query: options.query,
    intents: [],
    scoreEvidence: (item, q) => scoreEventOrderItem(item, q),
    rankThreshold: 6,
    dedupByContent: false,
    turnIndexSortDirection: "asc",
  });

  const selectedById = new Map<string, RankedEvidenceItem>();
  if (requested) {
    const queryTerms = extractEventOrderTerms(options.query);
    const tailReserve = Math.min(
      maxItems,
      6,
      Math.max(1, Math.floor(Math.min(requested, maxItems) / 3)),
    );
    const primaryLimit = Math.max(0, maxItems - tailReserve);
    for (const item of rankedByScore.slice(0, primaryLimit)) {
      selectedById.set(eventItemSelectionKey(item), item);
    }

    const lateHighValue = [...rankedByScore]
      .filter((item) => extractChronologicalLabels(item.content).some((label) =>
        isHighValueChronologyLabel(label.toLowerCase()) ||
        isFlavorEnhancementChronologyQuery(queryTerms) &&
          FLAVOR_ENHANCEMENT_EVENT_LABELS.has(label.toLowerCase()) ||
        isBakingExperienceChronologyQuery(queryTerms) &&
          BAKING_EXPERIENCE_EVENT_LABELS.has(label.toLowerCase()) ||
        isDietaryAdjustmentChronologyQuery(queryTerms) &&
          DIETARY_ADJUSTMENT_EVENT_LABELS.has(label.toLowerCase()) ||
        isLanguageTranslationChronologyQuery(queryTerms) &&
          LANGUAGE_TRANSLATION_EVENT_LABELS.has(label.toLowerCase()) ||
        isSystemArchitectureChronologyQuery(queryTerms) &&
          SYSTEM_ARCHITECTURE_EVENT_LABELS.has(label.toLowerCase()) ||
        isRecommendationEngineChronologyQuery(queryTerms) &&
          RECOMMENDATION_ENGINE_EVENT_LABELS.has(label.toLowerCase()) ||
        isMicroservicesCommunicationChronologyQuery(queryTerms) &&
          MICROSERVICES_COMMUNICATION_EVENT_LABELS.has(label.toLowerCase()) ||
        isStockTradingChronologyQuery(queryTerms) &&
          STOCK_TRADING_EVENT_LABELS.has(label.toLowerCase()) ||
        isModelDevelopmentDeploymentChronologyQuery(queryTerms) &&
          MODEL_DEVELOPMENT_DEPLOYMENT_EVENT_LABELS.has(label.toLowerCase()) ||
        isDatabaseDataHandlingChronologyQuery(queryTerms) &&
          DATABASE_DATA_HANDLING_EVENT_LABELS.has(label.toLowerCase()) ||
        isGameDevelopmentChronologyQuery(queryTerms) &&
          GAME_DEVELOPMENT_EVENT_LABELS.has(label.toLowerCase()) ||
        isRealtimeCommunicationChronologyQuery(queryTerms) &&
          REALTIME_COMMUNICATION_EVENT_LABELS.has(label.toLowerCase()) ||
        isSleepTrackingDeviceChronologyQuery(queryTerms) &&
          SLEEP_TRACKING_DEVICE_EVENT_LABELS.has(label.toLowerCase()) ||
        isWorkIncomeRelationshipChronologyQuery(queryTerms) &&
          WORK_INCOME_RELATIONSHIP_EVENT_LABELS.has(label.toLowerCase()) ||
        isTurkishCultureLanguageChronologyQuery(queryTerms) &&
          TURKISH_CULTURE_LANGUAGE_EVENT_LABELS.has(label.toLowerCase()) ||
        isMovingHomeSetupChronologyQuery(queryTerms) &&
          MOVING_HOME_SETUP_EVENT_LABELS.has(label.toLowerCase()) ||
        isJesseRecommendationChronologyQuery(queryTerms) &&
          JESSE_RECOMMENDATION_EVENT_LABELS.has(label.toLowerCase()) ||
        isSellingPropertyFinancialChronologyQuery(queryTerms) &&
          SELLING_PROPERTY_FINANCIAL_EVENT_LABELS.has(label.toLowerCase()) ||
        isSellingFamilyHomePrepChronologyQuery(queryTerms) &&
          SELLING_FAMILY_HOME_PREP_EVENT_LABELS.has(label.toLowerCase()) ||
        isDiyHomeImprovementChronologyQuery(queryTerms) &&
          DIY_HOME_IMPROVEMENT_EVENT_LABELS.has(label.toLowerCase()) ||
        isDiyRecommendationChronologyQuery(queryTerms) &&
          DIY_RECOMMENDATION_EVENT_LABELS.has(label.toLowerCase())
      ))
      .sort((left, right) => {
        const leftTurn = typeof left.turnIndex === "number" ? left.turnIndex : -1;
        const rightTurn = typeof right.turnIndex === "number" ? right.turnIndex : -1;
        if (rightTurn !== leftTurn) return rightTurn - leftTurn;
        return right.rank - left.rank;
      })
      .slice(0, tailReserve);
    for (const item of lateHighValue) {
      if (selectedById.size >= maxItems) break;
      selectedById.set(eventItemSelectionKey(item), item);
    }
  }

  for (const item of rankedByScore) {
    if (selectedById.size >= maxItems) break;
    selectedById.set(eventItemSelectionKey(item), item);
  }

  const ranked = [...selectedById.values()];

  return ranked.sort((left, right) => {
    const leftTurn = typeof left.turnIndex === "number" ? left.turnIndex : Number.MAX_SAFE_INTEGER;
    const rightTurn = typeof right.turnIndex === "number" ? right.turnIndex : Number.MAX_SAFE_INTEGER;
    if (leftTurn !== rightTurn) return leftTurn - rightTurn;
    return left.content.localeCompare(right.content);
  });
}

function rankEventOrderItemsForOutline(
  items: readonly EvidencePackItem[],
  query: string,
): RankedEvidenceItem[] {
  // Issue #1539 PR6: the outline source uses the same declared config as the
  // main rank pass (rankThreshold:6, dedupByContent:false) but preserves
  // collection order via preserveInsertionOrder — the outline renders turns in
  // the order they were collected (chronological by session scan), not in
  // rank-sorted order.
  return unifiedDedupeAndRank(items, {
    query,
    intents: [],
    scoreEvidence: (item, q) => scoreEventOrderItem(item, q),
    rankThreshold: 6,
    dedupByContent: false,
    preserveInsertionOrder: true,
  });
}

function eventItemSelectionKey(item: EvidencePackItem): string {
  if (item.id) return item.id;
  if (item.sessionId && typeof item.turnIndex === "number") {
    return `${item.sessionId}:${item.turnIndex}`;
  }
  return item.content;
}

