    out.push(...file.chunks);
  }
  return out;
}

function dedupeNativeKnowledgeChunks(chunks: NativeKnowledgeChunk[]): NativeKnowledgeChunk[] {
  const seen = new Set<string>();
  const priority = new Map<NativeKnowledgeChunk["sourceKind"], number>([
    ["handoff", 1],
    ["daily_summary", 2],
    ["bootstrap_doc", 3],
    ["automation_note", 4],
    ["workspace_doc", 5],
    ["identity", 6],
    ["memory", 7],
    ["obsidian_note", 8],
  ]);
  return [...chunks]
    .sort((left, right) => {
      const leftPriority = priority.get(left.sourceKind) ?? 99;
      const rightPriority = priority.get(right.sourceKind) ?? 99;
      return (
        leftPriority - rightPriority
        || left.sourcePath.localeCompare(right.sourcePath)
        || left.startLine - right.startLine
      );
    })
    .filter((chunk) => {
      const key = [
        chunk.sourcePath,
        chunk.startLine,
        chunk.endLine,
        chunk.content,
      ].join("::");
      if (seen.has(key)) return false;
      seen.add(key);
      return true;
    });
}

async function findPersistedNativeKnowledgeStateFiles(
  rootDir: string,
  maxDepth: number,
  currentDepth: number = 0,
): Promise<string[]> {
  if (currentDepth > maxDepth) return [];
  const entries = await readdir(rootDir, { withFileTypes: true }).catch(() => []);
  const out: string[] = [];
  for (const entry of entries) {
    const fullPath = path.join(rootDir, entry.name);
    if (entry.isFile() && PERSISTED_NATIVE_KNOWLEDGE_STATE_FILES.has(entry.name)) {
      out.push(fullPath);
      continue;
    }
    if (!entry.isDirectory()) continue;
    out.push(...await findPersistedNativeKnowledgeStateFiles(fullPath, maxDepth, currentDepth + 1));
  }
  return out;
}

export async function loadPersistedNativeKnowledgeChunks(options: {
  memoryDir: string;
  recallNamespaces?: string[];
  defaultNamespace: string;
}): Promise<NativeKnowledgeChunk[]> {
  const stateFiles = await findPersistedNativeKnowledgeStateFiles(options.memoryDir, 4);
  if (stateFiles.length === 0) return [];

  const chunks: NativeKnowledgeChunk[] = [];
  for (const statePath of stateFiles.sort()) {
    const raw = await readFile(statePath, "utf-8").catch(() => "");
    if (!raw) continue;
    try {
      const parsed = JSON.parse(raw) as { vaults?: unknown; files?: unknown };
      if (typeof parsed.vaults === "object" && parsed.vaults) {
        const state: ObsidianSyncState = {
          version: 1,
          updatedAt: new Date(0).toISOString(),
          vaults: parsed.vaults as Record<string, ObsidianVaultState>,
        };
        chunks.push(...loadActiveObsidianChunks({
          state,
          recallNamespaces: options.recallNamespaces,
          defaultNamespace: options.defaultNamespace,
        }).map((chunk) => {
          const note = Object.values(state.vaults)
            .flatMap((vault) => Object.values(vault.notes))
            .find((entry) => entry.chunks.some((candidate) => candidate.chunkId === chunk.chunkId));
          if (!note) return chunk;
          return {
            ...chunk,
            derivedDate: chunk.derivedDate ?? note.derivedDate,
            namespace: chunk.namespace ?? note.namespace,
            privacyClass: chunk.privacyClass ?? note.privacyClass,
            aliases: chunk.aliases ?? note.aliases,
            tags: chunk.tags ?? note.tags,
            wikilinks: chunk.wikilinks ?? note.wikilinks,
            backlinks: chunk.backlinks ?? note.backlinks,
          };
        }));
        continue;
      }
      if (typeof parsed.files === "object" && parsed.files) {
        if (path.basename(statePath) === "openclaw-workspace-sync.json") {
          const state: OpenClawWorkspaceSyncState = {
            version: 1,
            updatedAt: new Date(0).toISOString(),
            files: parsed.files as Record<string, OpenClawWorkspaceFileState>,
          };
          chunks.push(...loadActiveOpenClawWorkspaceChunks({
            state,
            recallNamespaces: options.recallNamespaces,
            defaultNamespace: options.defaultNamespace,
          }).map((chunk) => {
            const file = state.files[chunk.sourcePath];
            if (!file) return chunk;
            return {
              ...chunk,
              derivedDate: chunk.derivedDate ?? file.derivedDate,
              namespace: chunk.namespace ?? file.namespace,
              privacyClass: chunk.privacyClass ?? file.privacyClass,
              sessionKey: chunk.sessionKey ?? file.sessionKey,
              workflowKey: chunk.workflowKey ?? file.workflowKey,
              author: chunk.author ?? file.author,
              agent: chunk.agent ?? file.agent,
            };
          }));
          continue;
        }
        const state: CuratedIncludeFilesSyncState = {
          version: 1,
          updatedAt: new Date(0).toISOString(),
          files: parsed.files as Record<string, CuratedIncludeFileState>,
        };
        chunks.push(...loadActiveCuratedIncludeChunks({
          state,
          recallNamespaces: options.recallNamespaces,
          defaultNamespace: options.defaultNamespace,
        }).map((chunk) => {
          const file = state.files[chunk.sourcePath];
          if (!file) return chunk;
          return {
            ...chunk,
            derivedDate: chunk.derivedDate ?? file.derivedDate,
            namespace: chunk.namespace ?? file.namespace,
            privacyClass: chunk.privacyClass ?? file.privacyClass,
          };
        }));
      }
    } catch {
      continue;
    }
  }

  return dedupeNativeKnowledgeChunks(chunks);
}

export async function syncOpenClawWorkspaceArtifacts(options: {
  workspaceDir: string;
  memoryDir: string;
  config: NativeKnowledgeConfig;
}): Promise<{
  statePath: string;
  touchedFiles: number;
  deletedFiles: number;
  chunkCount: number;
  activeChunks: NativeKnowledgeChunk[];
}> {
  const adapter = options.config.openclawWorkspace;
  const statePath = resolveOpenClawWorkspaceStatePath(options.memoryDir, options.config);
  if (!adapter?.enabled) {
    return { statePath, touchedFiles: 0, deletedFiles: 0, chunkCount: 0, activeChunks: [] };
  }

  const previousState = await loadOpenClawWorkspaceState(options.memoryDir, options.config);
  const listedFiles = await listMarkdownFiles(options.workspaceDir);
  if (listedFiles === null) {
    return {
      statePath,
      touchedFiles: 0,
      deletedFiles: 0,
      chunkCount: Object.values(previousState.files)
        .filter((file) => !file.deleted)
        .reduce((total, file) => total + file.chunks.length, 0),
      activeChunks: loadActiveOpenClawWorkspaceChunks({
        state: previousState,
        defaultNamespace: "default",
      }),
    };
  }

  const candidates = resolveFileCandidates({
    listedFiles,
    bootstrapFiles: adapter.bootstrapFiles,
    handoffGlobs: adapter.handoffGlobs,
    dailySummaryGlobs: adapter.dailySummaryGlobs,
    automationNoteGlobs: adapter.automationNoteGlobs,
    workspaceDocGlobs: adapter.workspaceDocGlobs,
    excludeGlobs: adapter.excludeGlobs,
  });
  const nextFiles: Record<string, OpenClawWorkspaceFileState> = {};
  const seen = new Set<string>();
  let touchedFiles = 0;
  let deletedFiles = 0;

  for (const candidate of candidates) {
    const absPath = path.join(options.workspaceDir, candidate.sourcePath);
    const content = await readFile(absPath, "utf-8").catch(() => null);
    if (content === null) continue;
    const info = await stat(absPath).catch(() => null);
    if (!info?.isFile()) continue;

    const sourceHash = createHash("sha256").update(content).digest("hex");
    const parsed = parseFrontmatter(content);
    const metadata = deriveOpenClawArtifactMetadata({
      sourcePath: candidate.sourcePath,
      parsed,
      sharedSafeGlobs: adapter.sharedSafeGlobs,
    });
    const title = resolveNoteTitle(candidate.sourcePath, parsed);
    const syncConfigHash = createHash("sha256")
      .update(JSON.stringify({
        sourceKind: candidate.sourceKind,
        maxChunkChars: options.config.maxChunkChars,
        metadata,
      }))
      .digest("hex");
    const previous = previousState.files[candidate.sourcePath];
    if (
      previous &&
      previous.deleted !== true &&
      previous.sourceHash === sourceHash &&
      previous.mtimeMs === info.mtimeMs &&
      previous.syncConfigHash === syncConfigHash
    ) {
      nextFiles[candidate.sourcePath] = {
        ...previous,
        deleted: false,
        deletedAt: undefined,
      };
      seen.add(candidate.sourcePath);
      continue;
    }

    const chunks = buildOpenClawWorkspaceChunks({
      sourcePath: candidate.sourcePath,
      sourceKind: candidate.sourceKind,
      body: parsed.body,
      bodyStartLine: parsed.bodyStartLine,
      maxChunkChars: options.config.maxChunkChars,
      sourceHash,
      mtimeMs: info.mtimeMs,
      metadata,
    });

    nextFiles[candidate.sourcePath] = {
      sourcePath: candidate.sourcePath,
      sourceKind: candidate.sourceKind,
      title,
      namespace: metadata.namespace,
      privacyClass: metadata.privacyClass,
      derivedDate: metadata.derivedDate,
      sessionKey: metadata.sessionKey,
      workflowKey: metadata.workflowKey,
      author: metadata.author,
      agent: metadata.agent,
      sourceHash,
      syncConfigHash,
      mtimeMs: info.mtimeMs,
      deleted: false,
      chunks,
    };
    touchedFiles += 1;
    seen.add(candidate.sourcePath);
  }

  for (const [sourcePath, previous] of Object.entries(previousState.files)) {
    if (seen.has(sourcePath)) continue;
    nextFiles[sourcePath] = {
      ...previous,
      deleted: true,
      deletedAt: new Date().toISOString(),
      chunks: [],
    };
    deletedFiles += 1;
  }

  const nextState: OpenClawWorkspaceSyncState = {
    version: 1,
    updatedAt: new Date().toISOString(),
    files: nextFiles,
  };
  const activeChunks = loadActiveOpenClawWorkspaceChunks({
    state: nextState,
    defaultNamespace: "default",
  });
  const chunkCount = activeChunks.length;
  try {
    await mkdir(path.dirname(statePath), { recursive: true });
    await writeFile(statePath, `${JSON.stringify(nextState, null, 2)}\n`, "utf-8");
  } catch (error) {
    log.warn(`native knowledge: failed to persist openclaw workspace sync state (fail-open): ${String(error)}`);
  }

  return {
    statePath,
    touchedFiles,
    deletedFiles,
    chunkCount,
    activeChunks,
  };
}

export async function syncCuratedIncludeFiles(options: {
  workspaceDir: string;
  memoryDir: string;
  config: NativeKnowledgeConfig;
  recallNamespaces?: string[];
  defaultNamespace: string;
  skipSourcePaths?: string[];
}): Promise<{
  statePath: string;
  touchedFiles: number;
  deletedFiles: number;
  chunkCount: number;
  activeChunks: NativeKnowledgeChunk[];
}> {
  const statePath = resolveCuratedIncludeFilesStatePath(options.memoryDir, options.config);
  const previousState = await loadCuratedIncludeFilesState(options.memoryDir, options.config);
  const workspaceInfo = await stat(options.workspaceDir).catch(() => null);
  if (!workspaceInfo?.isDirectory()) {
    return {
      statePath,
      touchedFiles: 0,
      deletedFiles: 0,
      chunkCount: Object.values(previousState.files)
        .filter((file) => !file.deleted)
        .reduce((total, file) => total + file.chunks.length, 0),
      activeChunks: loadActiveCuratedIncludeChunks({
        state: previousState,
        recallNamespaces: options.recallNamespaces,
        defaultNamespace: options.defaultNamespace,
      }),
    };
  }

  const skipped = new Set((options.skipSourcePaths ?? []).map((value) => value.replace(/\\/g, "/")));
  const candidatePaths = await resolveCandidatePaths({
    workspaceDir: options.workspaceDir,
    includeFiles: options.config.includeFiles,
    defaultNamespace: options.defaultNamespace,
    identityVariantMode: "disk",
  });
  const nextFiles: Record<string, CuratedIncludeFileState> = {};
  const seen = new Set<string>();
  let touchedFiles = 0;
  let deletedFiles = 0;

  for (const filePath of candidatePaths) {
    if (!(await readableFile(filePath))) continue;
    const content = await readFile(filePath, "utf-8").catch(() => null);
    if (content === null) continue;
    const info = await stat(filePath).catch(() => null);
    if (!info?.isFile()) continue;

    const sourcePath = path.relative(options.workspaceDir, filePath).replace(/\\/g, "/");
    if (skipped.has(sourcePath)) continue;

    const parsed = parseFrontmatter(content);
    const metadata = deriveCuratedFileMetadata({
      sourcePath,
      parsed,
    });
    const sourceKind = detectSourceKind(sourcePath);
    const sourceHash = createHash("sha256").update(content).digest("hex");
    const title = resolveNoteTitle(sourcePath, parsed);
    const syncConfigHash = createHash("sha256")
      .update(JSON.stringify({
        sourceKind,
        maxChunkChars: options.config.maxChunkChars,
        metadata,
      }))
      .digest("hex");
    const previous = previousState.files[sourcePath];
    if (
      previous &&
      previous.deleted !== true &&
      previous.sourceHash === sourceHash &&
      previous.mtimeMs === info.mtimeMs &&
      previous.syncConfigHash === syncConfigHash
    ) {
      nextFiles[sourcePath] = {
        ...previous,
        deleted: false,
        deletedAt: undefined,
      };
      seen.add(sourcePath);
      continue;
    }

    const chunks = buildCuratedIncludeChunks({
      sourcePath,
      body: parsed.body,
      bodyStartLine: parsed.bodyStartLine,
      maxChunkChars: options.config.maxChunkChars,
      sourceHash,
      mtimeMs: info.mtimeMs,
      metadata,
    });
    nextFiles[sourcePath] = {
      sourcePath,
      sourceKind,
      title,
      namespace: metadata.namespace,
      privacyClass: metadata.privacyClass,
      derivedDate: metadata.derivedDate,
      sourceHash,
      syncConfigHash,
      mtimeMs: info.mtimeMs,
      deleted: false,
      chunks,
    };
    touchedFiles += 1;
    seen.add(sourcePath);
  }

  for (const [sourcePath, previous] of Object.entries(previousState.files)) {
    if (seen.has(sourcePath) || skipped.has(sourcePath)) continue;
    if (previous.deleted) {
      nextFiles[sourcePath] = previous;
      continue;
    }
    nextFiles[sourcePath] = {
      ...previous,
      deleted: true,
      deletedAt: new Date().toISOString(),
      chunks: [],
    };
    deletedFiles += 1;
  }

  const nextState: CuratedIncludeFilesSyncState = {
    version: 1,
    updatedAt: new Date().toISOString(),
    files: nextFiles,
  };
  const activeChunks = loadActiveCuratedIncludeChunks({
    state: nextState,
    recallNamespaces: options.recallNamespaces,
    defaultNamespace: options.defaultNamespace,
  });
  const chunkCount = Object.values(nextFiles)
    .filter((file) => !file.deleted)
    .reduce((total, file) => total + file.chunks.length, 0);
  try {
    await mkdir(path.dirname(statePath), { recursive: true });
    await writeFile(statePath, `${JSON.stringify(nextState, null, 2)}\n`, "utf-8");
  } catch (error) {
    log.warn(`native knowledge: failed to persist curated include sync state (fail-open): ${String(error)}`);
  }

  return {
    statePath,
    touchedFiles,
    deletedFiles,
    chunkCount,
    activeChunks,
  };
}

export async function collectNativeKnowledgeChunks(options: {
  workspaceDir: string;
  memoryDir?: string;
  config: NativeKnowledgeConfig;
  recallNamespaces?: string[];
  defaultNamespace: string;
  abortSignal?: AbortSignal;
}): Promise<NativeKnowledgeChunk[]> {
  throwIfNativeKnowledgeAborted(options.abortSignal);
  if (!options.config.enabled) return [];

  const chunks: NativeKnowledgeChunk[] = [];
  const openclawBootstrapFiles = new Set(
    (options.memoryDir && options.config.openclawWorkspace?.enabled
      ? options.config.openclawWorkspace.bootstrapFiles
      : []
    )
      .map((value) => value.replace(/\\/g, "/")),
  );
  if (options.memoryDir) {
    throwIfNativeKnowledgeAborted(options.abortSignal);
    const syncResult = await syncCuratedIncludeFiles({
      workspaceDir: options.workspaceDir,
      memoryDir: options.memoryDir,
      config: options.config,
      recallNamespaces: options.recallNamespaces,
      defaultNamespace: options.defaultNamespace,
      skipSourcePaths: [...openclawBootstrapFiles],
    });
    chunks.push(...syncResult.activeChunks);
  } else {
    throwIfNativeKnowledgeAborted(options.abortSignal);
    const candidatePaths = await resolveCandidatePaths({
      workspaceDir: options.workspaceDir,
      includeFiles: options.config.includeFiles,
      recallNamespaces: options.recallNamespaces,
      defaultNamespace: options.defaultNamespace,
      identityVariantMode: "recall",
    });
    for (const filePath of candidatePaths) {
      throwIfNativeKnowledgeAborted(options.abortSignal);
      if (!(await readableFile(filePath))) continue;
      const content = await readFile(filePath, "utf-8").catch(() => null);
      if (!content) continue;
      const sourcePath = path.relative(options.workspaceDir, filePath).replace(/\\/g, "/");
      if (openclawBootstrapFiles.has(sourcePath)) continue;
      const parsed = parseFrontmatter(content);
      const metadata = deriveCuratedFileMetadata({
        sourcePath,
        parsed,
      });
      const directChunks = buildCuratedIncludeChunks({
        sourcePath,
        body: parsed.body,
        bodyStartLine: parsed.bodyStartLine,
        maxChunkChars: options.config.maxChunkChars,
        sourceHash: createHash("sha256").update(content).digest("hex"),
        mtimeMs: 0,
        metadata,
      }).filter((chunk) => isChunkAllowedForRecall(chunk, options.recallNamespaces, options.defaultNamespace));
      chunks.push(...directChunks);
    }
  }

  if (options.memoryDir && options.config.openclawWorkspace?.enabled) {
    throwIfNativeKnowledgeAborted(options.abortSignal);
    const syncResult = await syncOpenClawWorkspaceArtifacts({
      workspaceDir: options.workspaceDir,
      memoryDir: options.memoryDir,
      config: options.config,
    });
    chunks.push(
      ...syncResult.activeChunks.filter((chunk) =>
        isChunkAllowedForRecall(chunk, options.recallNamespaces, options.defaultNamespace),
      ),
    );
  }

  if (options.memoryDir && options.config.obsidianVaults.length > 0) {
    throwIfNativeKnowledgeAborted(options.abortSignal);
    const syncResult = await syncObsidianVaults({
      memoryDir: options.memoryDir,
      config: options.config,
    });
    chunks.push(
      ...syncResult.activeChunks.filter((chunk) =>
        isChunkAllowedForRecall(chunk, options.recallNamespaces, options.defaultNamespace),
      ),
    );
  }

  return dedupeNativeKnowledgeChunks(chunks);
}

function throwIfNativeKnowledgeAborted(signal?: AbortSignal): void {
  if (!signal?.aborted) return;
  const err = new Error("native knowledge collection aborted");
  Object.defineProperty(err, "name", { value: "AbortError" });
  throw err;
}

export function searchNativeKnowledge(options: {
  query: string;
  chunks: NativeKnowledgeChunk[];
  maxResults: number;
}): NativeKnowledgeSearchResult[] {
  const normalizedQuery = normalizeText(options.query);
  const queryTokens = new Set(tokenize(options.query));
  if (!normalizedQuery || queryTokens.size === 0 || options.maxResults <= 0) return [];
  const temporalQuery = /\b(today|yesterday|recent|latest|current|next|handoff|summary)\b/i.test(options.query);
  const now = Date.now();

  return options.chunks
    .map((chunk) => {
      const metadataText = [
        chunk.title,
        chunk.content,
        chunk.sourcePath,
        chunk.notePath,
        chunk.derivedDate,
        chunk.sessionKey,
        chunk.workflowKey,
        chunk.author,
        chunk.agent,
        ...(chunk.tags ?? []),
        ...(chunk.aliases ?? []),
        ...(chunk.wikilinks ?? []),
        ...(chunk.backlinks ?? []),
      ]
        .filter((value): value is string => typeof value === "string" && value.length > 0)
        .join("\n");
      const normalizedContent = normalizeText(metadataText);
      const contentTokens = new Set(tokenize(normalizedContent));
      let overlap = 0;
      for (const token of queryTokens) {
        if (contentTokens.has(token)) overlap += 1;
      }
      if (overlap === 0 && !normalizedContent.includes(normalizedQuery)) return null;
      const kindBoost =
        chunk.sourceKind === "handoff"
          ? 0.2
          : chunk.sourceKind === "daily_summary"
            ? 0.16
            : chunk.sourceKind === "bootstrap_doc" || chunk.sourceKind === "identity"
              ? 0.15
              : chunk.sourceKind === "memory"
                ? 0.1
                : chunk.sourceKind === "obsidian_note"
                  ? 0.08
                  : chunk.sourceKind === "automation_note"
                    ? 0.06
                    : 0.05;
      const phraseBoost = normalizedContent.includes(normalizedQuery) ? 0.35 : 0;
      const metadataBoost =
        (chunk.aliases?.some((alias) => normalizeText(alias).includes(normalizedQuery)) ? 0.12 : 0) +
        (chunk.tags?.some((tag) => normalizeText(tag).includes(normalizedQuery)) ? 0.08 : 0) +
        (chunk.derivedDate && normalizeText(chunk.derivedDate).includes(normalizedQuery) ? 0.08 : 0) +
        (chunk.sessionKey && normalizeText(chunk.sessionKey).includes(normalizedQuery) ? 0.1 : 0) +
        (chunk.workflowKey && normalizeText(chunk.workflowKey).includes(normalizedQuery) ? 0.08 : 0) +
        (chunk.agent && normalizeText(chunk.agent).includes(normalizedQuery) ? 0.06 : 0) +
        (chunk.author && normalizeText(chunk.author).includes(normalizedQuery) ? 0.05 : 0);
      let temporalBoost = 0;
      if (chunk.derivedDate) {
        const parsed = Date.parse(`${chunk.derivedDate}T00:00:00Z`);
        if (Number.isFinite(parsed)) {
          const ageDays = Math.max(0, Math.floor((now - parsed) / (24 * 60 * 60 * 1000)));
          if (ageDays <= 1) temporalBoost += temporalQuery ? 0.12 : 0.04;
          else if (ageDays <= 7) temporalBoost += temporalQuery ? 0.08 : 0.02;
          else if (temporalQuery && ageDays >= 90) temporalBoost -= 0.08;
        }
      }
      return {
        ...chunk,
        score: overlap / Math.max(queryTokens.size, 1) + kindBoost + phraseBoost + metadataBoost + temporalBoost,
      };
    })
    .filter((chunk): chunk is NativeKnowledgeSearchResult => chunk !== null)
    .sort((a, b) => b.score - a.score || a.sourcePath.localeCompare(b.sourcePath) || a.startLine - b.startLine)
    .slice(0, options.maxResults);
}

export function formatNativeKnowledgeSection(options: {
  results: NativeKnowledgeSearchResult[];
  maxChars: number;
}): string | null {
  if (options.results.length === 0 || options.maxChars <= 0) return null;
  const lines = ["## Curated Workspace Knowledge", ""];
  let used = lines.join("\n").length;

  for (const result of options.results) {
    const snippet = result.content.length > 500 ? `${result.content.slice(0, 497)}...` : result.content;
    const meta = [
      `kind=${result.sourceKind}`,
      result.derivedDate ? `date=${result.derivedDate}` : null,
      result.sessionKey ? `session=${result.sessionKey}` : null,
      result.workflowKey ? `workflow=${result.workflowKey}` : null,
      result.agent ? `agent=${result.agent}` : null,
      result.author ? `author=${result.author}` : null,
      result.tags && result.tags.length > 0 ? `tags=${result.tags.join(",")}` : null,
      result.vaultId ? `vault=${result.vaultId}` : null,
    ]
      .filter((value): value is string => value !== null)
      .join(" ");
    const block =
      `- ${result.sourcePath}:${result.startLine}-${result.endLine} [${result.title}] ` +
      `(score: ${result.score.toFixed(3)}${meta ? `; ${meta}` : ""})\n  ${snippet.replace(/\n/g, "\n  ")}`;
    if (used + block.length > options.maxChars && lines.length > 2) break;
    if (used + block.length > options.maxChars) return null;
    lines.push(block);
    used += block.length + 1;
  }

  return lines.length > 2 ? lines.join("\n") : null;
}

import path from "node:path";
import { mkdir, writeFile } from "node:fs/promises";
import { listJsonFiles, readJsonFile } from "./json-store.js";
import {
  assertIsoRecordedAt,
  assertSafePathSegment,
  assertString,
  isRecord,
  optionalString,
  optionalStringArray,
  recordStoreDay,
  validateStringRecord,
} from "./store-contract.js";

export type ObjectiveStateSnapshotSource = "tool_result" | "cli" | "system" | "manual";
export type ObjectiveStateSnapshotKind = "tool" | "file" | "process" | "record" | "workspace";
export type ObjectiveStateChangeKind = "created" | "updated" | "deleted" | "observed" | "executed" | "failed";
export type ObjectiveStateOutcome = "success" | "failure" | "partial" | "unknown";

export interface ObjectiveStateValueRef {
  exists?: boolean;
  ref?: string;
  valueHash?: string;
}

export interface ObjectiveStateSnapshot {
  schemaVersion: 1;
  snapshotId: string;
  recordedAt: string;
  sessionKey: string;
  source: ObjectiveStateSnapshotSource;
  kind: ObjectiveStateSnapshotKind;
  changeKind: ObjectiveStateChangeKind;
  scope: string;
  summary: string;
  toolName?: string;
  command?: string;
  outcome?: ObjectiveStateOutcome;
  before?: ObjectiveStateValueRef;
  after?: ObjectiveStateValueRef;
  entityRefs?: string[];
  tags?: string[];
  metadata?: Record<string, string>;
}

export interface ObjectiveStateStoreStatus {
  enabled: boolean;
  writesEnabled: boolean;
  rootDir: string;
  snapshotsDir: string;
  snapshots: {
    total: number;
    valid: number;
    invalid: number;
    byKind: Partial<Record<ObjectiveStateSnapshotKind, number>>;
    byOutcome: Partial<Record<ObjectiveStateOutcome, number>>;
    latestSnapshotId?: string;
    latestRecordedAt?: string;
    latestSessionKey?: string;
  };
  latestSnapshot?: ObjectiveStateSnapshot;
  invalidSnapshots: Array<{
    path: string;
    error: string;
  }>;
}

export interface ObjectiveStateSearchResult {
  snapshot: ObjectiveStateSnapshot;
  score: number;
}

function validateValueRef(raw: unknown, field: string): ObjectiveStateValueRef | undefined {
  if (raw === undefined) return undefined;
  if (!isRecord(raw)) throw new Error(`${field} must be an object`);
  const exists = typeof raw.exists === "boolean" ? raw.exists : undefined;
  const ref = optionalString(raw.ref);
  const valueHash = optionalString(raw.valueHash);
  if (exists === undefined && ref === undefined && valueHash === undefined) {
    throw new Error(`${field} must include exists, ref, or valueHash`);
  }
  return { exists, ref, valueHash };
}

function validateMetadata(raw: unknown): Record<string, string> | undefined {
  return validateStringRecord(raw, "metadata");
}

// Assert that a built path stays inside the expected base directory before it is
// used in a filesystem write. snapshotId/recordedAt are already validated by
// validateObjectiveStateSnapshot, so for valid data this is a defense-in-depth
// barrier (and makes the containment provable to CodeQL js/path-injection).
function assertWithinDir(baseDir: string, candidate: string): string {
  const resolvedBase = path.resolve(baseDir);
  const resolved = path.resolve(candidate);
  const rel = path.relative(resolvedBase, resolved);
  if (rel === ".." || rel.startsWith(`..${path.sep}`) || path.isAbsolute(rel)) {
    throw new Error("objective-state path escapes the snapshots directory");
  }
  return resolved;
}

export function resolveObjectiveStateStoreDir(memoryDir: string, overrideDir?: string): string {
  if (typeof overrideDir === "string" && overrideDir.trim().length > 0) {
    return overrideDir.trim();
  }
  return path.join(memoryDir, "state", "objective-state");
}

export function objectiveStateStoreOverrideForNamespace(options: {
  memoryDir: string;
  configuredStoreDir?: string;
  namespacesEnabled: boolean;
  namespace: string;
}): string | undefined {
  const configured = options.configuredStoreDir?.trim();
  if (!configured) return undefined;
  if (!options.namespacesEnabled) return configured;

  const defaultStoreDir = path.join(options.memoryDir, "state", "objective-state");
  if (path.resolve(configured) === path.resolve(defaultStoreDir)) {
    return undefined;
  }
  return path.join(configured, "namespaces", options.namespace);
}

export function validateObjectiveStateSnapshot(raw: unknown): ObjectiveStateSnapshot {
  if (!isRecord(raw)) throw new Error("objective-state snapshot must be an object");
  if (raw.schemaVersion !== 1) throw new Error("schemaVersion must be 1");

  const source = assertString(raw.source, "source");
  if (!["tool_result", "cli", "system", "manual"].includes(source)) {
    throw new Error("source must be one of tool_result|cli|system|manual");
  }

  const kind = assertString(raw.kind, "kind");
  if (!["tool", "file", "process", "record", "workspace"].includes(kind)) {
    throw new Error("kind must be one of tool|file|process|record|workspace");
  }

  const changeKind = assertString(raw.changeKind, "changeKind");
  if (!["created", "updated", "deleted", "observed", "executed", "failed"].includes(changeKind)) {
    throw new Error("changeKind must be one of created|updated|deleted|observed|executed|failed");
  }

  const outcomeRaw = optionalString(raw.outcome);
  if (outcomeRaw !== undefined && !["success", "failure", "partial", "unknown"].includes(outcomeRaw)) {
    throw new Error("outcome must be one of success|failure|partial|unknown");
  }

  return {
    schemaVersion: 1,
    snapshotId: assertSafePathSegment(assertString(raw.snapshotId, "snapshotId"), "snapshotId"),
    recordedAt: assertIsoRecordedAt(assertString(raw.recordedAt, "recordedAt")),
    sessionKey: assertString(raw.sessionKey, "sessionKey"),
    source: source as ObjectiveStateSnapshotSource,
    kind: kind as ObjectiveStateSnapshotKind,
    changeKind: changeKind as ObjectiveStateChangeKind,
    scope: assertString(raw.scope, "scope"),
    summary: assertString(raw.summary, "summary"),
    toolName: optionalString(raw.toolName),
    command: optionalString(raw.command),
    outcome: outcomeRaw as ObjectiveStateOutcome | undefined,
    before: validateValueRef(raw.before, "before"),
    after: validateValueRef(raw.after, "after"),
    entityRefs: optionalStringArray(raw.entityRefs, "entityRefs"),
    tags: optionalStringArray(raw.tags, "tags"),
    metadata: validateMetadata(raw.metadata),
  };
}

export async function recordObjectiveStateSnapshot(options: {
  memoryDir: string;
  objectiveStateStoreDir?: string;
  snapshot: ObjectiveStateSnapshot;
}): Promise<string> {
  const rootDir = resolveObjectiveStateStoreDir(options.memoryDir, options.objectiveStateStoreDir);
  const validated = validateObjectiveStateSnapshot(options.snapshot);
  const day = recordStoreDay(validated.recordedAt);
  const snapshotsRoot = path.join(rootDir, "snapshots");
  const snapshotsDir = assertWithinDir(snapshotsRoot, path.join(snapshotsRoot, day));
  const filePath = assertWithinDir(snapshotsDir, path.join(snapshotsDir, `${validated.snapshotId}.json`));
  await mkdir(snapshotsDir, { recursive: true });
  await writeFile(filePath, JSON.stringify(validated, null, 2), "utf8");
  return filePath;
}

export async function getObjectiveStateStoreStatus(options: {
  memoryDir: string;
  objectiveStateStoreDir?: string;
  enabled: boolean;
  writesEnabled: boolean;
}): Promise<ObjectiveStateStoreStatus> {
  const rootDir = resolveObjectiveStateStoreDir(options.memoryDir, options.objectiveStateStoreDir);
  const snapshotsDir = path.join(rootDir, "snapshots");
  const { files, snapshots, invalidSnapshots } = await readObjectiveStateSnapshots(options);

  snapshots.sort((a, b) => b.recordedAt.localeCompare(a.recordedAt));
  const byKind: Partial<Record<ObjectiveStateSnapshotKind, number>> = {};
  const byOutcome: Partial<Record<ObjectiveStateOutcome, number>> = {};
  for (const snapshot of snapshots) {
    byKind[snapshot.kind] = (byKind[snapshot.kind] ?? 0) + 1;
    const outcome = snapshot.outcome ?? "unknown";
    byOutcome[outcome] = (byOutcome[outcome] ?? 0) + 1;
  }

  return {
    enabled: options.enabled,
    writesEnabled: options.writesEnabled,
    rootDir,
    snapshotsDir,
    snapshots: {
      total: files.length,
      valid: snapshots.length,
      invalid: invalidSnapshots.length,
      byKind,
      byOutcome,
      latestSnapshotId: snapshots[0]?.snapshotId,
      latestRecordedAt: snapshots[0]?.recordedAt,
      latestSessionKey: snapshots[0]?.sessionKey,
    },
    latestSnapshot: snapshots[0],
    invalidSnapshots,
  };
}

async function readObjectiveStateSnapshots(options: {
  memoryDir: string;
  objectiveStateStoreDir?: string;
}): Promise<{
  files: string[];
  snapshots: ObjectiveStateSnapshot[];
  invalidSnapshots: Array<{ path: string; error: string }>;
}> {
  const rootDir = resolveObjectiveStateStoreDir(options.memoryDir, options.objectiveStateStoreDir);
  const files = await listJsonFiles(path.join(rootDir, "snapshots"));
  const snapshots: ObjectiveStateSnapshot[] = [];
  const invalidSnapshots: Array<{ path: string; error: string }> = [];
  for (const filePath of files) {
    try {
      snapshots.push(validateObjectiveStateSnapshot(await readJsonFile(filePath)));
    } catch (error) {
      invalidSnapshots.push({
        path: filePath,
        error: error instanceof Error ? error.message : String(error),
      });
    }
  }
  return { files, snapshots, invalidSnapshots };
}

function normalizeTokens(value: string): string[] {
  return value
    .toLowerCase()
    .split(/[^a-z0-9]+/)
    .map((token) => token.trim())
    .filter((token) => token.length >= 2);
}

function overlapScore(queryTokens: Set<string>, value: string | undefined, weight: number): number {
  if (!value) return 0;
  const tokens = new Set(normalizeTokens(value));
  let matches = 0;
  for (const token of queryTokens) {
    if (tokens.has(token)) matches += 1;
  }
  return matches * weight;
}

function lexicalScoreObjectiveStateSnapshot(
  snapshot: ObjectiveStateSnapshot,
  queryTokens: Set<string>,
): number {
  let score = 0;
  score += overlapScore(queryTokens, snapshot.scope, 4);
  score += overlapScore(queryTokens, snapshot.summary, 3);
  score += overlapScore(queryTokens, snapshot.command, 3);
  score += overlapScore(queryTokens, snapshot.toolName, 2);
  score += overlapScore(queryTokens, snapshot.tags?.join(" "), 2);
  score += overlapScore(queryTokens, snapshot.entityRefs?.join(" "), 2);
  score += overlapScore(queryTokens, snapshot.kind, 1);
  score += overlapScore(queryTokens, snapshot.changeKind, 1);
  score += overlapScore(queryTokens, snapshot.outcome, 1);
  return score;
}

function scoreObjectiveStateSnapshot(
  snapshot: ObjectiveStateSnapshot,
  lexicalScore: number,
  sessionKey?: string,
): number {
  let score = lexicalScore;
  if (sessionKey && snapshot.sessionKey === sessionKey) score += 1.5;

  const recordedAtMs = Date.parse(snapshot.recordedAt);
  if (Number.isFinite(recordedAtMs)) {
    const ageHours = Math.max(0, (Date.now() - recordedAtMs) / 3_600_000);
    score += 1 / (1 + ageHours);
  }
  return score;
}

export async function searchObjectiveStateSnapshots(options: {
  memoryDir: string;
  objectiveStateStoreDir?: string;
  query: string;
  maxResults: number;
  sessionKey?: string;
}): Promise<ObjectiveStateSearchResult[]> {
  const maxResults = Math.max(0, Math.floor(options.maxResults));
  if (maxResults === 0) return [];

  const { snapshots } = await readObjectiveStateSnapshots(options);
  if (snapshots.length === 0) return [];

  const queryTokens = new Set(normalizeTokens(options.query));
  const scored = snapshots.map((snapshot) => {
    const lexicalScore = lexicalScoreObjectiveStateSnapshot(snapshot, queryTokens);
    return {
      snapshot,
      lexicalScore,
      score: scoreObjectiveStateSnapshot(snapshot, lexicalScore, options.sessionKey),
    };
  });

  const filtered = queryTokens.size === 0
    ? scored
    : scored.filter((result) => result.lexicalScore > 0);

  filtered.sort((left, right) => {
    if (right.score !== left.score) return right.score - left.score;
    return right.snapshot.recordedAt.localeCompare(left.snapshot.recordedAt);
  });
  return filtered.slice(0, maxResults);
}

/**
 * Recall X-ray snapshot schema (issue #570, PR 1).
 *
 * The X-ray surface is the unified, per-result attribution document that
 * merges the tier that served each memory, its score decomposition, any
 * graph path, an audit entry id, and the exact filter/eligibility ladder
 * that either admitted or rejected each candidate.  This file defines the
 * schema and an in-memory builder + builder-state helper.
 *
 * Scope for PR 1 (this slice):
 *   - Types only + pure builder functions (no IO, no rendering).
 *   - Orchestrator plumbing captures a snapshot when the caller passes
 *     `xrayCapture: true`.  No behavior change when the flag is absent.
 *   - NO new public surfaces here — CLI/HTTP/MCP land in later slices.
 *
 * The shared renderer lands in PR 2 at `recall-xray-renderer.ts`.  Do not
 * fork formatting logic into other surfaces; extend the renderer.
 */

import { randomUUID } from "node:crypto";

import { normalizeRetrievedMemoryProvenance, type RetrievedMemoryProvenance } from "./memory-provenance.js";
import { estimateTokenCount } from "./token-estimate.js";
import type { RecallDisclosure, RecallTierExplain } from "./types.js";
import type { StateLabel } from "./recall-state-view.js";
import { isRecallDisclosure } from "./types.js";
import type { RecallContextDegradation } from "./recall-context-composition.js";

/**
 * Estimate token cost of a payload for X-ray disclosure accounting.
 */
export function estimateRecallTokens(text: string | null | undefined): number {
  if (typeof text !== "string" || text.length === 0) return 0;
  return estimateTokenCount(text);
}

/**
 * Aggregated per-disclosure token spend summary, computed by the
 * renderer from a snapshot's results.  Non-negative integers.
 */
export interface RecallXrayDisclosureSummary {
  chunk: { count: number; estimatedTokens: number };
  section: { count: number; estimatedTokens: number };
  raw: { count: number; estimatedTokens: number };
  /** Number of results without a recorded disclosure level. */
  unspecified: { count: number; estimatedTokens: number };
}

/**
 * Which retrieval source produced a given result.  This is the X-ray
 * tier ladder called out in issue #570 and is *distinct* from the
 * `RetrievalTier` enum (which describes issue #518's tier-explain
 * block).  Keeping the sets separate lets the two observability
 * surfaces evolve without conflating their vocabularies:
 *
 *   - `RetrievalTier`     — direct-answer eligibility ladder.
 *   - `RecallXrayServedBy` — which source materialized each result.
 */
export type RecallXrayServedBy =
  | "direct-answer"
  | "hybrid"
  | "graph"
  | "recent-scan"
  | "procedural"
  | "review-context"
  | "lcm-file-parts"
  | "lcm-tool-parts";

export const RECALL_XRAY_SERVED_BY_VALUES: readonly RecallXrayServedBy[] = [
  "direct-answer",
  "hybrid",
  "graph",
  "recent-scan",
  "procedural",
  "review-context",
  "lcm-file-parts",
  "lcm-tool-parts",
] as const;

export function isRecallXrayServedBy(
  value: unknown,
): value is RecallXrayServedBy {
  return (
    typeof value === "string" &&
    (RECALL_XRAY_SERVED_BY_VALUES as readonly string[]).includes(value)
  );
}

/**
 * Score decomposition for a single X-ray result.
 *
 * All fields are optional because different tiers populate different
 * terms: `hybrid` reports vector + bm25 + mmr penalty, `direct-answer`
 * reports importance + tier prior, etc.  The only guaranteed field is
 * `final`, which is the post-combination score used for ordering.
 */
export interface RecallXrayScoreDecomposition {
  vector?: number;
  bm25?: number;
  importance?: number;
  mmrPenalty?: number;
  tierPrior?: number;
  /** Additive boost from `reinforcement_count` frontmatter (issue #687 PR 3/4). */
  reinforcementBoost?: number;
  final: number;
}

/**
 * Per-result breakdown inside an X-ray snapshot.
 */
export interface RecallXrayResult {
  memoryId: string;
  path: string;
  servedBy: RecallXrayServedBy;
  scoreDecomposition: RecallXrayScoreDecomposition;
  graphPath?: string[];
  /**
   * Issue #681 PR 3/3 — per-edge confidence values aligned with
   * `graphPath`. When present, `graphEdgeConfidences[i]` is the
   * confidence of the edge between `graphPath[i]` and `graphPath[i+1]`,
   * so the array length is one less than `graphPath`. Legacy edges
   * without a recorded confidence render as `1.0`. Operators use this
   * to attribute floor-pruning and PageRank ranking decisions back to
   * specific edges. The renderer drops the line when the array is
   * empty or absent so legacy snapshots round-trip cleanly.
   */
  graphEdgeConfidences?: number[];
  /** Graph activation node ids recorded for path-scoring provenance. */
  pathNodeIds?: string[];
  /** True when a graph path penalty was applied. */
  pathPenaltyApplied?: boolean;
  auditEntryId?: string;
  /** Human-readable list of filters the candidate *passed*. */
  admittedBy: string[];
  /**
   * First filter that *would have* rejected the candidate, or undefined
   * when the candidate was admitted without a rejection trace.  When
   * present, `admittedBy` may still contain filters the candidate passed
   * before the rejecting gate; consumers should render both.
   */
  rejectedBy?: string;
  /**
   * Disclosure depth used to render this result's payload (issue #677
   * PR 3/4).  Mirrors the per-result disclosure already exposed in the
   * recall response so X-ray consumers can attribute token spend to
   * the depth that produced it.
   */
  disclosure?: RecallDisclosure;
  /**
   * Estimated token cost of the rendered payload at the chosen
   * disclosure depth.  Non-negative integer.  Computed by callers via
   * `estimateRecallTokens(text)`; the renderer aggregates these into
   * a per-disclosure summary so operators can see where their budget
   * went.
   */
  estimatedTokens?: number;
  /**
   * Free-form tags from the memory's YAML frontmatter (issue #689 PR 3/3).
   * Populated by the X-ray capture path when the caller passes a `tags`
   * filter so per-result tags are available alongside the filter trace
   * in `snapshot.filters`.  Also populated without a filter when the
   * orchestrator decorates results via `xrayCapture: true` so all X-ray
   * consumers can inspect memory labels without a separate storage read.
   * Absent (not `[]`) when the frontmatter has no tags or the memory
   * could not be read.
   */
  tags?: string[];
  /**
   * Per-result memory provenance and safety context. Populated by recall
   * capture when the memory frontmatter was already loaded by retrieval.
   */
  provenance?: RetrievedMemoryProvenance;
  /**
   * Claim-level provenance span (issue #1575 PR 3). The first source excerpt
   * backing this memory, surfaced so X-ray consumers can see the literal
   * utterance each fact derives from alongside retrieval provenance. Absent
   * when the memory carries no source spans (legacy or `provenance: "none"`).
   */
  sourceSpan?: {
    /** Verbatim quote excerpt (capped at write time by `provenance.maxQuoteChars`). */
    quote: string;
    /** ISO timestamp of the source turn. */
    observedAt: string;
    /** Coarse strength tag from the frontmatter. */
    provenance: "verified" | "unverified" | "none";
  };
  /**
   * Issue #1577 — per-result trust score, band, and components from the
   * unified TrustScore recall stage. Present when `trustScoreEnabled` is on.
   * Quarantined items appear here with `quarantined: true` and a reason so
   * exclusion never looks like "no result" (rule 34).
   */
  trust?: {
    score: number;
    band: "high" | "medium" | "low" | "quarantine";
    components: Record<string, { value: number; weight: number }>;
    multiplier: number;
    quarantined: boolean;
    quarantineReason?: string;
  };
  /**
   * #1952 — recall state-view label for this result (`current`,
   * `historical`, or `transition`). Present only when state views were
   * active for the recall AND the result was annotated at the inject
   * seam; absent otherwise, so legacy snapshots round-trip unchanged.
   */
  stateView?: StateLabel;
}

/**
 * Trace entry for a filter the orchestrator evaluated during recall.
 * Captures the name of the filter, how many candidates it saw, and how
 * many it let through.  Used by X-ray consumers to render the filter
 * ladder above the per-result breakdown.
 */
export interface RecallFilterTrace {
  name: string;
  considered: number;
  admitted: number;
  /** Optional human-readable reason for any rejections. */
  reason?: string;
}

/**
 * Peer-profile injection annotation (issue #679 completion).
 *
 * When `peerProfileRecallEnabled` is true and a peer is registered for
 * the session, the orchestrator injects a `## Peer Profile` section into
 * the recall context. This annotation records which peer was injected and
 * how many profile fields were included so operators can correlate
 * retrieval quality with peer-context enrichment.
 *
 * `null` means no peer profile was injected (peer not registered, feature
 * disabled, or peer has no profile fields).
 */
export interface RecallXrayPeerProfileInjection {
  /** The peer id whose profile was injected. */
  peerId: string;
  /**
   * Number of profile fields included after the `peerProfileRecallMaxFields`
   * cap was applied.  Zero means the profile existed but had no fields.
   */
  fieldsInjected: number;
}

/**
 * The unified X-ray snapshot.  CLI, HTTP, and MCP surfaces all render
 * this same shape through the shared renderer (CLAUDE.md rule 22).
 */
export interface RecallXraySnapshot {
  /** Stable v1 tag so downstream consumers can version-gate their parsers. */
  schemaVersion: "1";
  query: string;
  /** UUID minted per capture; unique across snapshots within a process. */
  snapshotId: string;
  /** Epoch milliseconds the snapshot was captured. */
  capturedAt: number;
  /**
   * Tier-explain block from issue #518, carried verbatim when present.
   * `null` means direct-answer tier did not run (disabled, or another
   * tier served the query).
   */
  tierExplain: RecallTierExplain | null;
  results: RecallXrayResult[];
  appliedResultLimit: number;
  appliedResults: RecallXrayResult[];
  headroomResults: RecallXrayResult[];
  filters: RecallFilterTrace[];
  /**
   * Character budget accounting for the final assembled recall payload.
   * `used` is the rendered-context length; `chars` is the cap.  Both are
   * non-negative integers in `[0, 2**31)`.
   */
  budget: { chars: number; used: number };
  /** Optional session-scope fields carried for downstream filtering. */
  sessionKey?: string;
  namespace?: string;
  traceId?: string;
  /**
   * Peer-profile injection metadata (issue #679 completion).
   * Non-null when `peerProfileRecallEnabled` is true and a peer profile
   * was successfully injected into this recall's context. `null` (or
   * absent) means no peer profile was injected.
   */
  peerProfileInjection?: RecallXrayPeerProfileInjection | null;
  /**
   * Injected-context degradation (#2972). Absent on a healthy recall so
   * the snapshot stays byte-stable. Budget warnings ride here, never
   * in the injected text.
   */
  degradation?: RecallContextDegradation;
}

// ─── Builder ──────────────────────────────────────────────────────────────

export interface BuildXraySnapshotInput {
  query: string;
  tierExplain?: RecallTierExplain | null;
  results?: RecallXrayResult[];
  appliedResultLimit?: number;
  appliedResults?: RecallXrayResult[];
  headroomResults?: RecallXrayResult[];
  filters?: RecallFilterTrace[];
  budget?: { chars?: number; used?: number };
  sessionKey?: string;
  namespace?: string;
  traceId?: string;
  /** Peer-profile injection metadata (issue #679 completion). */
  peerProfileInjection?: RecallXrayPeerProfileInjection | null;
  /** Injected-context degradation (#2972). Omit on a healthy recall. */
  degradation?: RecallContextDegradation;
  /** Optional injected timestamp for deterministic tests. */
  now?: () => number;
  /** Optional injected id generator for deterministic tests. */
  snapshotIdGenerator?: () => string;
}

/**
 * Build a `RecallXraySnapshot` from explicit input fields.  Pure
 * function; safe to call from anywhere.  All array/object inputs are
 * shallow-copied so caller mutation after build cannot tear the
 * returned snapshot.
 */
export function buildXraySnapshot(
  input: BuildXraySnapshotInput,
): RecallXraySnapshot {
  const now = input.now ?? Date.now;
  const snapshotIdGenerator = input.snapshotIdGenerator ?? randomUUID;

  const results = Array.isArray(input.results)
    ? input.results.map(cloneResult)
    : [];
  const appliedResults = Array.isArray(input.appliedResults)
    ? input.appliedResults.map(cloneResult)
    : [];
  const headroomResults = Array.isArray(input.headroomResults)
    ? input.headroomResults.map(cloneResult)
    : [];
  const filters = Array.isArray(input.filters)
    ? input.filters.map(cloneFilter)
    : [];

  const budgetChars = nonNegativeInt(input.budget?.chars);
  const budgetUsed = nonNegativeInt(input.budget?.used);

  const tierExplain =
    input.tierExplain && typeof input.tierExplain === "object"
      ? cloneTierExplain(input.tierExplain)
      : null;

  // Peer-profile injection annotation (issue #679 completion).
  // Deep-copy via structuredClone so the caller can't mutate the snapshot
  // after build. Accept null explicitly (no injection) or a valid object.
  let peerProfileInjection: RecallXrayPeerProfileInjection | null | undefined;
  if (input.peerProfileInjection && typeof input.peerProfileInjection === "object") {
    const raw = input.peerProfileInjection;
    const peerId = nonEmptyString(raw.peerId);
    if (peerId !== undefined) {
      peerProfileInjection = {
        peerId,
        fieldsInjected: nonNegativeInt(raw.fieldsInjected),
      };
    }
  } else if (input.peerProfileInjection === null) {
    peerProfileInjection = null;
  }

  const out: RecallXraySnapshot = {
    schemaVersion: "1",
    query: typeof input.query === "string" ? input.query : "",
    snapshotId: snapshotIdGenerator(),
    capturedAt: now(),
    tierExplain,
    results,
    appliedResultLimit: nonNegativeInt(input.appliedResultLimit),
    appliedResults,
    headroomResults,
    filters,
    budget: { chars: budgetChars, used: budgetUsed },
    sessionKey: nonEmptyString(input.sessionKey),
    namespace: nonEmptyString(input.namespace),
    traceId: nonEmptyString(input.traceId),
  };
  if (peerProfileInjection !== undefined) {
    out.peerProfileInjection = peerProfileInjection;
  }
  if (input.degradation && typeof input.degradation === "object") {
    out.degradation = { ...input.degradation };
    if (input.degradation.budget) {
      out.degradation.budget = { ...input.degradation.budget };
    }
  }
  return out;
}

/**
 * Mutable builder used by the orchestrator to accumulate X-ray fields
 * as recall progresses.  Call `build()` to get the finalized
 * immutable-ish snapshot.  All inputs are validated at insert time so
 * a malformed entry cannot poison the snapshot later.
 */
export class RecallXrayBuilder {
  private readonly query: string;
  private readonly sessionKey: string | undefined;
  private namespace: string | undefined;
  private traceId: string | undefined;
  private tierExplain: RecallTierExplain | null = null;
  private readonly results: RecallXrayResult[] = [];
  private readonly filters: RecallFilterTrace[] = [];
  private budgetChars = 0;
  private budgetUsed = 0;
  private peerProfileInjection: RecallXrayPeerProfileInjection | null | undefined;

  constructor(opts: {
    query: string;
    sessionKey?: string;
    namespace?: string;
    traceId?: string;
  }) {
    this.query = typeof opts.query === "string" ? opts.query : "";
    this.sessionKey = nonEmptyString(opts.sessionKey);
    this.namespace = nonEmptyString(opts.namespace);
    this.traceId = nonEmptyString(opts.traceId);
  }

  setNamespace(namespace: string | undefined): void {
    this.namespace = nonEmptyString(namespace);
  }

  setTraceId(traceId: string | undefined): void {
    this.traceId = nonEmptyString(traceId);
  }

  setTierExplain(tierExplain: RecallTierExplain | null | undefined): void {
    this.tierExplain =
      tierExplain && typeof tierExplain === "object"
        ? cloneTierExplain(tierExplain)
        : null;
  }

  setBudget(budget: { chars?: number; used?: number }): void {
    this.budgetChars = nonNegativeInt(budget.chars);
    this.budgetUsed = nonNegativeInt(budget.used);
  }

  /**
   * Record peer-profile injection metadata for this recall snapshot
   * (issue #679 completion). Pass `null` to explicitly record that no
   * injection happened (feature enabled but no peer / no profile fields).
   */
  setPeerProfileInjection(
    injection: RecallXrayPeerProfileInjection | null,
  ): void {
    this.peerProfileInjection = injection;
  }

  recordResult(result: RecallXrayResult): void {
    this.results.push(cloneResult(result));
  }

  recordFilter(filter: RecallFilterTrace): void {
    this.filters.push(cloneFilter(filter));
  }

  build(opts: {
    now?: () => number;
    snapshotIdGenerator?: () => string;
  } = {}): RecallXraySnapshot {
    return buildXraySnapshot({
      query: this.query,
      tierExplain: this.tierExplain,
      results: this.results,
      filters: this.filters,
      budget: { chars: this.budgetChars, used: this.budgetUsed },
      sessionKey: this.sessionKey,
      namespace: this.namespace,
      traceId: this.traceId,
      peerProfileInjection: this.peerProfileInjection,
      now: opts.now,
      snapshotIdGenerator: opts.snapshotIdGenerator,
    });
  }
}

// ─── Internals ────────────────────────────────────────────────────────────

function cloneResult(result: RecallXrayResult): RecallXrayResult {
  if (!result || typeof result !== "object") {
    throw new TypeError("RecallXrayResult must be an object");
  }
  if (!isRecallXrayServedBy(result.servedBy)) {
    throw new TypeError(
      `RecallXrayResult.servedBy must be one of ${RECALL_XRAY_SERVED_BY_VALUES.join(
        ", ",
      )}; got ${JSON.stringify(result.servedBy)}`,
    );
  }
  const memoryId = typeof result.memoryId === "string" ? result.memoryId : "";
  const path = typeof result.path === "string" ? result.path : "";
  const admittedBy = Array.isArray(result.admittedBy)
    ? result.admittedBy.filter((x): x is string => typeof x === "string")
    : [];
  const graphPath = Array.isArray(result.graphPath)
    ? result.graphPath.filter((x): x is string => typeof x === "string")
    : undefined;
  // Issue #681 PR 3/3 — per-edge confidences alongside graph path.
  // Each entry is clamped into [0, 1]; the array is rejected wholesale
  // when alignment cannot be verified so downstream surfaces can rely
  // on `graphEdgeConfidences[i]` describing the edge between
  // `graphPath[i]` and `graphPath[i+1]`.
  //
  // Cursor review (#735): the input array length MUST match
  // `graphPath.length - 1` *before* any per-element filtering. The
  // earlier implementation skipped non-finite entries via `continue`
  // and then length-checked the cleaned array — that would silently
  // shift surviving values to earlier positions. Example: input
  // `[0.5, NaN, 0.7]` for a 3-edge path would collapse to
  // `[0.5, 0.7]`, length-check would pass against `expected = 2`, and
  // the renderer would mis-attribute `0.7` to edge B→C when it really
  // came from edge C→D. Reject on either size mismatch or any
  // non-finite entry so misalignment is impossible.
  let graphEdgeConfidences: number[] | undefined;
  if (Array.isArray(result.graphEdgeConfidences) && graphPath && graphPath.length > 1) {
    const expected = graphPath.length - 1;
    const raw = result.graphEdgeConfidences;
    if (raw.length === expected) {
      const cleaned: number[] = [];
      let allFinite = true;
      for (const value of raw) {
        if (typeof value !== "number" || !Number.isFinite(value)) {
          allFinite = false;
          break;
        }
        cleaned.push(Math.min(1, Math.max(0, value)));
      }
      if (allFinite) {
        graphEdgeConfidences = cleaned;
      }
    }
  }
  const pathNodeIds = Array.isArray(result.pathNodeIds)
    ? result.pathNodeIds.filter((x): x is string => typeof x === "string")
    : undefined;
  const pathPenaltyApplied =
    typeof result.pathPenaltyApplied === "boolean"
      ? result.pathPenaltyApplied
      : undefined;
  const stateView =
    result.stateView === "current" || result.stateView === "historical" || result.stateView === "transition"
      ? result.stateView
      : undefined;
  const auditEntryId = nonEmptyString(result.auditEntryId);
  const rejectedBy = nonEmptyString(result.rejectedBy);
  const scoreDecomposition = cloneScoreDecomposition(result.scoreDecomposition);
  const out: RecallXrayResult = {
    memoryId,
    path,
    servedBy: result.servedBy,
    scoreDecomposition,
    admittedBy,
  };
  if (graphPath !== undefined) out.graphPath = graphPath;
  if (graphEdgeConfidences !== undefined) {
    out.graphEdgeConfidences = graphEdgeConfidences;
  }
  if (pathNodeIds !== undefined) out.pathNodeIds = pathNodeIds;
  if (pathPenaltyApplied !== undefined) out.pathPenaltyApplied = pathPenaltyApplied;
  if (stateView !== undefined) out.stateView = stateView;
  if (auditEntryId !== undefined) out.auditEntryId = auditEntryId;
  if (rejectedBy !== undefined) out.rejectedBy = rejectedBy;
  // Disclosure + token telemetry (issue #677 PR 3/4).  Only attach when
  // present and well-formed; unknown disclosure values are dropped so a
  // bad caller can't poison downstream renderers.  Uses the shared
  // `isRecallDisclosure` guard so adding a fourth disclosure level
  // requires touching only `types.ts`.
  if (isRecallDisclosure(result.disclosure)) {
    out.disclosure = result.disclosure;
  }
  if (
    typeof result.estimatedTokens === "number" &&
    Number.isFinite(result.estimatedTokens) &&
    result.estimatedTokens >= 0
  ) {
    out.estimatedTokens = Math.floor(result.estimatedTokens);
  }
  // Tags from frontmatter (issue #689 PR 3/3).  Normalize identically to
  // the recall-surface path: trim and drop empty strings so consumers can
  // compare tags directly without a secondary normalization step.
  if (Array.isArray(result.tags)) {
    const cleanedTags = result.tags
      .filter((t): t is string => typeof t === "string")
      .map((t) => t.trim())
      .filter((t) => t.length > 0);
    if (cleanedTags.length > 0) {
      out.tags = cleanedTags;
    }
  }
  const provenance = normalizeRetrievedMemoryProvenance(result.provenance);
  if (provenance !== undefined) {
    out.provenance = provenance;
  }
  // Claim-level provenance span (#1575 PR 3). Deep-copy the three scalar
  // fields so the snapshot returned by getLastXraySnapshot is independent
  // of the caller's object (matches the structuredClone contract).
  const ss = result.sourceSpan;
  if (
    ss &&
    typeof ss.quote === "string" &&
    typeof ss.observedAt === "string" &&
    (ss.provenance === "verified" ||
      ss.provenance === "unverified" ||
      ss.provenance === "none")
  ) {
    out.sourceSpan = {
      quote: ss.quote,
      observedAt: ss.observedAt,
      provenance: ss.provenance,
    };
  }
  // Issue #1577 — preserve the trust projection through the clone so
  // getLastXraySnapshot surfaces trust score/band/quarantine reason (review
  // Oqg_o: cloneResult was silently dropping the field). Deep-copy the scalar +
  // record fields so the snapshot is independent of the caller's object,
  // matching the structuredClone contract used for every other field above.
  if (result.trust) {
    const t = result.trust;
    const components: Record<string, { value: number; weight: number }> = {};
    for (const [k, v] of Object.entries(t.components)) {
      components[k] = { value: v.value, weight: v.weight };
    }
    out.trust = {
      score: t.score,
      band: t.band,
      components,
      multiplier: t.multiplier,
      quarantined: t.quarantined,
      ...(t.quarantineReason ? { quarantineReason: t.quarantineReason } : {}),
    };
  }
  return out;
}

/**
 * Summarize per-disclosure token spend across an X-ray snapshot's
 * results.  Pure helper — used by the markdown renderer to print a
 * "per-disclosure token spend" line and exposed for tests / surfaces.
 */
export function summarizeDisclosureTokens(
  results: ReadonlyArray<Pick<RecallXrayResult, "disclosure" | "estimatedTokens">>,
): RecallXrayDisclosureSummary {
  const summary: RecallXrayDisclosureSummary = {
    chunk: { count: 0, estimatedTokens: 0 },
    section: { count: 0, estimatedTokens: 0 },
    raw: { count: 0, estimatedTokens: 0 },
    unspecified: { count: 0, estimatedTokens: 0 },
  };
  for (const result of results) {
    const tokens =
      typeof result.estimatedTokens === "number" &&
      Number.isFinite(result.estimatedTokens) &&
      result.estimatedTokens >= 0
        ? Math.floor(result.estimatedTokens)
        : 0;
    const bucket = isRecallDisclosure(result.disclosure)
      ? result.disclosure
      : "unspecified";
    summary[bucket].count += 1;
    summary[bucket].estimatedTokens += tokens;
  }
  return summary;
}

function cloneFilter(filter: RecallFilterTrace): RecallFilterTrace {
  if (!filter || typeof filter !== "object") {
    throw new TypeError("RecallFilterTrace must be an object");
  }
  const out: RecallFilterTrace = {
    name: typeof filter.name === "string" ? filter.name : "",
    considered: nonNegativeInt(filter.considered),
    admitted: nonNegativeInt(filter.admitted),
  };
  const reason = nonEmptyString(filter.reason);
  if (reason !== undefined) out.reason = reason;
  return out;
}

function cloneScoreDecomposition(
  value: RecallXrayScoreDecomposition | undefined,
): RecallXrayScoreDecomposition {
  if (!value || typeof value !== "object") {
    return { final: 0 };
  }
  const out: RecallXrayScoreDecomposition = {
    final: finiteNumber(value.final) ?? 0,
  };
  const vector = finiteNumber(value.vector);
  if (vector !== undefined) out.vector = vector;
  const bm25 = finiteNumber(value.bm25);
  if (bm25 !== undefined) out.bm25 = bm25;
  const importance = finiteNumber(value.importance);
  if (importance !== undefined) out.importance = importance;
  const mmrPenalty = finiteNumber(value.mmrPenalty);
  if (mmrPenalty !== undefined) out.mmrPenalty = mmrPenalty;
  const tierPrior = finiteNumber(value.tierPrior);
  if (tierPrior !== undefined) out.tierPrior = tierPrior;
  const reinforcementBoost = finiteNumber(value.reinforcementBoost);
  if (reinforcementBoost !== undefined && reinforcementBoost > 0) {
    out.reinforcementBoost = reinforcementBoost;
  }
  return out;
}

function cloneTierExplain(tierExplain: RecallTierExplain): RecallTierExplain {
  // Use structuredClone so future RecallTierExplain additions do not
  // silently share references through hand-enumerated fields.  The
  // payload is JSON-shaped.
  return structuredClone(tierExplain);
}

function nonNegativeInt(value: unknown): number {
  if (typeof value !== "number" || !Number.isFinite(value)) return 0;
  if (value <= 0) return 0;
  return Math.floor(value);
}

function finiteNumber(value: unknown): number | undefined {
  if (typeof value !== "number" || !Number.isFinite(value)) return undefined;
  return value;
}

function nonEmptyString(value: unknown): string | undefined {
  if (typeof value !== "string") return undefined;
  const trimmed = value.trim();
  if (trimmed.length === 0) return undefined;
  return trimmed;
}

import { abortError, isAbortError } from "./abort-error.js";
import { log, type LoggerBackend } from "./logger.js";

/**
 * Hand the event loop one macrotask.
 *
 * A recall section deadline is a timer, and a timer cannot fire while a
 * synchronous scan holds the loop — so a provider that iterates the whole corpus
 * must call this periodically or its budget is unenforceable (issue #2291).
 * `setImmediate` (check phase) is used rather than a `0ms` timer so the yield
 * cannot be starved by the timer queue it exists to let run.
 */
export function yieldToEventLoop(): Promise<void> {
  const { promise, resolve } = Promise.withResolvers<void>();
  setImmediate(resolve);
  return promise;
}

export type RecallSectionPriority = "core" | "enrichment";
/**
 * `timeout` records a section that started, exceeded its deadline, and was
 * degraded to its neutral value (issue #2291).  It is distinct from `skip`
 * (never ran: disabled or zero-limit) so operators can tell a configuration
 * choice from a budget breach in the section metric log.
 */
export type RecallSectionSource = "fresh" | "stale" | "skip" | "timeout";

export interface RecallSectionMetric {
  section: string;
  priority: RecallSectionPriority;
  durationMs: number;
  deadlineMs: number;
  source: RecallSectionSource;
  success: boolean;
  timing?: string;
}

export interface RecallSectionMetricLog {
  message: string;
  payload: {
    section: string;
    priority: RecallSectionPriority;
    durationMs: number;
    deadlineMs: number;
    source: RecallSectionSource;
    success: boolean;
  };
  level: "info" | "debug";
  timing: string;
}

function defaultTiming(metric: RecallSectionMetric): string {
  if (typeof metric.timing === "string" && metric.timing.length > 0) {
    return metric.timing;
  }
  if (metric.source === "timeout") {
    return `timeout(${Math.max(0, Math.round(metric.durationMs))}ms)`;
  }
  if (metric.source === "skip") {
    return "skip";
  }
  return `${Math.max(0, Math.round(metric.durationMs))}ms`;
}

export function formatRecallSectionMetric(metric: RecallSectionMetric): RecallSectionMetricLog {
  const payload = {
    section: metric.section,
    priority: metric.priority,
    durationMs: metric.durationMs,
    deadlineMs: metric.deadlineMs,
    source: metric.source,
    success: metric.success,
  };
  return {
    message: "recall section metric",
    payload,
    level: metric.priority === "core" && metric.success && metric.source !== "skip" ? "info" : "debug",
    timing: defaultTiming(metric),
  };
}

export function createRecallSectionMetricRecorder(options: {
  timings?: Record<string, string>;
  logger?: Pick<LoggerBackend, "info" | "debug">;
} = {}) {
  const logger = options.logger ?? log;
  return (metric: RecallSectionMetric): RecallSectionMetricLog => {
    const entry = formatRecallSectionMetric(metric);
    if (options.timings) {
      options.timings[metric.section] = entry.timing;
    }
    if (entry.level === "info") {
      if (typeof logger.info === "function") {
        logger.info(entry.message, entry.payload);
      } else {
        log.info(entry.message, entry.payload);
      }
    } else {
      if (typeof logger.debug === "function") {
        logger.debug(entry.message, entry.payload);
      } else {
        log.debug(entry.message, entry.payload);
      }
    }
    return entry;
  };
}

/**
 * Fraction of the request's REMAINING budget that a single core section may
 * consume.  The remainder is what makes degradation possible at all: time to
 * assemble and return the sections that did arrive before the outer timeout
 * kills the request outright.
 */
const CORE_SECTION_MAX_SHARE_OF_REQUEST = 0.8;

/**
 * Effective per-section deadline for optional core recall providers.
 *
 * Two things make the configured value unusable as-is (issue #2291):
 *
 *  - `recallCoreDeadlineMs` and `recallOuterTimeoutMs` both default to 75s, so a
 *    section budget taken at face value can never fire before the request ceiling
 *    that cancels everything — the caller loses the whole recall rather than one
 *    section.
 *  - Sections start *after* planning, namespace resolution, and mode selection.
 *    Capping against the original ceiling would let a section that starts 20s in
 *    still be running when the request is aborted, which is the same failure.
 *
 * So the cap is taken against `remainingOuterMs` — the request budget left when
 * the section actually starts. An operator who lowers `recallCoreDeadlineMs`
 * below that still gets exactly what they asked for.
 *
 * `remainingOuterMs === null` means the request is unbounded and there is nothing
 * to reserve headroom against. A non-positive remainder means the request is
 * already over budget, so the section degrades immediately rather than starting
 * work that cannot be delivered.
 */
export function resolveRecallCoreSectionDeadlineMs(options: {
  configuredCoreDeadlineMs: number;
  remainingOuterMs: number | null;
}): number {
  const configured = options.configuredCoreDeadlineMs;
  if (!Number.isFinite(configured) || configured <= 0) return configured;
  const remaining = options.remainingOuterMs;
  if (remaining === null || !Number.isFinite(remaining)) return configured;
  if (remaining <= 0) return 1;
  return Math.min(
    configured,
    Math.max(1, Math.floor(remaining * CORE_SECTION_MAX_SHARE_OF_REQUEST)),
  );
}

export interface RecallSectionDeadlineOutcome<T> {
  /** The section's value, or `fallback` when the deadline was exceeded. */
  value: T;
  timedOut: boolean;
  durationMs: number;
}

/**
 * Run one recall section under a deadline, degrading to `fallback` instead of
 * blocking the phase it belongs to (issue #2291).
 *
 * Before this existed, `deadlineMs` was recorded in the section metric but
 * never enforced for core sections: a provider doing a multi-minute scan on a
 * slow filesystem blocked the whole phase-one `Promise.all`, and kept scanning
 * after the caller aborted.  Two guarantees fix that:
 *
 *  1. The returned promise settles within `deadlineMs`, with `timedOut: true`
 *     and the caller's neutral value, so one slow optional provider degrades
 *     independently rather than holding the response.
 *  2. `run` receives a signal that fires on the deadline AND on the caller's
 *     abort, so the section can stop its own work at its next checkpoint.
 *
 * `deadlineMs <= 0` (or non-finite) means unbounded, matching the config
 * contract that a zero budget disables the limit.  The section signal is still
 * created and still tracks the parent, so cancellation propagates either way.
 */
export async function runRecallSectionWithinDeadline<T>(options: {
  deadlineMs: number;
  fallback: T;
  parentSignal?: AbortSignal;
  run: (sectionSignal: AbortSignal) => Promise<T>;
  now?: () => number;
}): Promise<RecallSectionDeadlineOutcome<T>> {
  const now = options.now ?? Date.now;
  const startedAtMs = now();
  const controller = new AbortController();
  const parentSignal = options.parentSignal;
  const onParentAbort = () => controller.abort();
  if (parentSignal?.aborted) {
    controller.abort();
  } else if (parentSignal) {
    parentSignal.addEventListener("abort", onParentAbort, { once: true });
  }

  const bounded = Number.isFinite(options.deadlineMs) && options.deadlineMs > 0;
  let timer: NodeJS.Timeout | undefined;

  try {
    // Wrap in a tagged result rather than racing raw values against a sentinel:
    // T is caller-chosen and must never be mistaken for the timeout marker.
    const work = options.run(controller.signal).then(
      (value) => ({ kind: "value" as const, value }),
    );
    if (!bounded) {
      const settled = await work;
      return { value: settled.value, timedOut: false, durationMs: now() - startedAtMs };
    }
    const deadline = Promise.withResolvers<{ kind: "timeout" }>();
    // Deliberately NOT unref'd: the caller is awaiting this bound, so the timer
    // must keep the loop alive until it fires or `finally` clears it.
    timer = setTimeout(() => deadline.resolve({ kind: "timeout" }), options.deadlineMs);
    const settled = await Promise.race([work, deadline.promise]);
    if (settled.kind === "timeout") {
      controller.abort(abortError("recall section deadline exceeded"));
      // The abandoned work outlives this call; swallow its settlement so a
      // late rejection is not reported as unhandled.
      void work.catch(() => {});
      return { value: options.fallback, timedOut: true, durationMs: now() - startedAtMs };
    }
    return { value: settled.value, timedOut: false, durationMs: now() - startedAtMs };
  } finally {
    clearTimeout(timer);
    parentSignal?.removeEventListener("abort", onParentAbort);
  }
}

/**
 * Runs one *optional* core recall section, bounded and accounted for.
 *
 * Binds a section's deadline, the caller's abort signal, and the QoS recorder
 * once so each provider is one call (issue #2291).  A breach degrades the
 * section to `fallback`, warns with the section name and budget, and records the
 * section as `timeout` — so a slow provider costs its own section, not the
 * response.
 *
 * The budget is resolved when each section STARTS, against the request budget
 * still left at that moment (`outerDeadlineAtMs`), not against the original
 * configured ceiling: sections begin after planning and namespace resolution, and
 * a section sized to the full request would otherwise still be running when the
 * request itself is aborted.
 *
 * Cancellation degrades too, and must: the section signal fires on the caller's
 * abort, and the phase this section belongs to is awaited through a race that the
 * caller's abort also wins.  A rejection here would therefore land on a promise
 * nobody is awaiting any more — an unhandled rejection rather than a signal.  The
 * caller learns of its own abort from that race, not from a section result.
 *
 * Only sections whose absence leaves recall coherent belong here: the fallback
 * IS the degraded contract.
 */
export function createBoundedCoreSectionRunner(options: {
  configuredDeadlineMs: number;
  /** Absolute time the whole request is aborted, or null when unbounded. */
  outerDeadlineAtMs: number | null;
  parentSignal?: AbortSignal;
  record: (metric: RecallSectionMetric) => unknown;
  logger?: Pick<LoggerBackend, "warn">;
  now?: () => number;
}): <T>(
  section: string,
  fallback: T,
  run: (sectionSignal: AbortSignal) => Promise<T>,
) => Promise<T> {
  const logger = options.logger ?? log;
  const now = options.now ?? Date.now;
  return async <T>(
    section: string,
    fallback: T,
    run: (sectionSignal: AbortSignal) => Promise<T>,
  ): Promise<T> => {
    const startedAtMs = now();
    const deadlineMs = resolveRecallCoreSectionDeadlineMs({
      configuredCoreDeadlineMs: options.configuredDeadlineMs,
      remainingOuterMs:
        options.outerDeadlineAtMs === null ? null : options.outerDeadlineAtMs - startedAtMs,
    });
    let outcome: RecallSectionDeadlineOutcome<T>;
    try {
      outcome = await runRecallSectionWithinDeadline({
        deadlineMs,
        fallback,
        parentSignal: options.parentSignal,
        run,
        now,
      });
    } catch (err) {
      if (!isAbortError(err)) throw err;
      const durationMs = now() - startedAtMs;
      options.record({
        section,
        priority: "core",
        durationMs,
        deadlineMs,
        source: "skip",
        success: false,
        timing: `cancelled(${durationMs}ms)`,
      });
      return fallback;
    }
    if (outcome.timedOut) {
      logger.warn(
        `recall section [${section}] exceeded its ${deadlineMs}ms core deadline ` +
          `after ${outcome.durationMs}ms; recall continues without it`,
      );
    }
    options.record({
      section,
      priority: "core",
      durationMs: outcome.durationMs,
      deadlineMs,
      source: outcome.timedOut ? "timeout" : "fresh",
      success: !outcome.timedOut,
    });
    return outcome.value;
  };
}

import { normalizeRecallTokens } from "./recall-tokenization.js";

export type RecallPromptShape = "standard" | "instruction_heavy";
export type CronConversationRecallMode = "auto" | "always" | "never";
export type RecallBudgetMode = "full" | "minimal";

export interface RecallQueryPolicyConfig {
  cronRecallPolicyEnabled: boolean;
  cronRecallNormalizedQueryMaxChars: number;
  cronRecallInstructionHeavyTokenCap: number;
  cronConversationRecallMode: CronConversationRecallMode;
}

export interface RecallQueryPolicyResult {
  promptShape: RecallPromptShape;
  retrievalQuery: string;
  skipConversationRecall: boolean;
  retrievalBudgetMode: RecallBudgetMode;
}

const DEFAULT_STOPWORDS = [
  "the",
  "and",
  "for",
  "with",
  "from",
  "that",
  "this",
  "your",
  "you",
  "are",
  "was",
  "were",
  "have",
  "has",
  "had",
  "not",
  "but",
  "its",
  "into",
  "only",
  "use",
  "run",
  "then",
  "when",
  "what",
  "where",
  "which",
  "will",
  "would",
  "should",
  "could",
  "goal",
  "output",
  "format",
  "rules",
  "section",
  "sections",
  "skip",
  "today",
  "yesterday",
  "return",
  "summary",
  "plain",
  "text",
  "before",
  "after",
  "time",
  "date",
  "daily",
  "cron",
  "agent",
  "mode",
  "data",
  "gathering",
  "context",
];
const MAX_COMPACT_TOKENS_PER_SOURCE_TERM = 8;
const COMPACT_IDENTIFIER_RE = /^[a-z0-9]+(?:[:_-][a-z0-9]+)+$/i;

function collapseWhitespace(text: string): string {
  return text.replace(/\s+/g, " ").trim();
}

function stripFilesystemLikePaths(text: string): string {
  return text
    .replace(/(?:^|\s)(~\/[^\s)]+)(?=\s|$)/g, " ")
    .replace(/(?:^|\s)(\/[A-Za-z0-9._\-\/]+)(?=\s|$)/g, " ")
    .replace(/(?:^|\s)([A-Za-z]:\\[^\s)]+)(?=\s|$)/g, " ");
}

function trimCompactSourceTerm(term: string): string {
  return term.replace(/^[^\p{L}\p{N}\p{M}]+|[^\p{L}\p{N}\p{M}]+$/gu, "");
}

function splitCompactSourceTerm(term: string): string[] {
  return term
    .split(/[^\p{L}\p{N}\p{M}:_-]+/gu)
    .map((part) => trimCompactSourceTerm(part))
    .filter((part) => part.length > 0);
}

function capCompactSourceTermTokens(tokens: string[]): string[] {
  if (tokens.length <= MAX_COMPACT_TOKENS_PER_SOURCE_TERM) return tokens;
  const last = tokens.at(-1);
  if (!last) return tokens.slice(0, MAX_COMPACT_TOKENS_PER_SOURCE_TERM);
  return [...tokens.slice(0, MAX_COMPACT_TOKENS_PER_SOURCE_TERM - 1), last];
}

function isBulletOrNumberedLine(line: string): boolean {
  if (line.startsWith("-") || line.startsWith("*")) {
    return true;
  }

  let i = 0;
  while (i < line.length) {
    const code = line.charCodeAt(i);
    if (code < 48 || code > 57) {
      break;
    }
    i += 1;
  }
  return i > 0 && i < line.length && line.charAt(i) === ".";
}

function scoreInstructionHeavyShape(prompt: string): number {
  const lines = prompt
    .split(/\r?\n/)
    .map((line) => line.trim())
    .filter((line) => line.length > 0);
  const lineCount = lines.length;
  if (lineCount === 0) return 0;

  const headingLineCount = lines.filter(
    (line) =>
      /^(goal|output format|tone rules|grounding rules|data gathering|date computation|crm context|follow-up|social|current time|return)\b/i.test(
        line
      ) || /^[A-Z][A-Z\s/-]{4,}:$/.test(line)
  ).length;
  const bulletLineCount = lines.filter((line) => isBulletOrNumberedLine(line)).length;
  const longLineCount = lines.filter((line) => line.length >= 180).length;
  const hasPathDensity = (prompt.match(/(?:~\/|\/Users\/|[A-Za-z]:\\)/g)?.length ?? 0) >= 2;
  const hasImperativeDensity =
    (prompt.match(/\b(run|extract|read|parse|determine|include|omit|skip)\b/gi)?.length ?? 0) >= 8;

  let score = 0;
  if (lineCount >= 24) score += 2;
  if (headingLineCount >= 4) score += 2;
  if (bulletLineCount >= 8) score += 1;
  if (longLineCount >= 3) score += 1;
  if (hasPathDensity) score += 1;
  if (hasImperativeDensity) score += 1;
  return score;
}

export function classifyRecallPromptShape(prompt: string): RecallPromptShape {
  const score = scoreInstructionHeavyShape(prompt);
  return score >= 5 ? "instruction_heavy" : "standard";
}

function tokenizeForCompactQuery(text: string): string[] {
  const tokens: string[] = [];
  const seen = new Set<string>();
  const addToken = (token: string) => {
    if (token.length === 0 || seen.has(token)) return;
    seen.add(token);
    tokens.push(token);
  };

  for (const rawTerm of text.split(/\s+/)) {
    for (const sourceTerm of splitCompactSourceTerm(trimCompactSourceTerm(rawTerm))) {
      if (COMPACT_IDENTIFIER_RE.test(sourceTerm)) {
        addToken(sourceTerm.toLowerCase());
        continue;
      }
      for (const token of capCompactSourceTermTokens(normalizeRecallTokens(sourceTerm, DEFAULT_STOPWORDS))) {
        addToken(token);
      }
    }
  }
  return tokens;
}

function buildInstructionHeavyQuery(prompt: string, tokenCap: number, maxChars: number): string {
  const cleaned = stripFilesystemLikePaths(prompt);
  const tokens = tokenizeForCompactQuery(cleaned).slice(0, Math.max(8, tokenCap));
  const joined = tokens.join(" ");
  const compact = collapseWhitespace(joined);
  if (compact.length <= maxChars) return compact;
  return compact.slice(0, maxChars).trim();
}

export function clampInstructionHeavyTokenCap(value: number): number {
  if (!Number.isFinite(value)) return 8;
  return Math.max(8, Math.round(value));
}

function buildStandardQuery(prompt: string, maxChars: number): string {
  const trimmed = collapseWhitespace(prompt);
  if (trimmed.length <= maxChars) return trimmed;
  return trimmed.slice(0, maxChars).trim();
}

export function buildRecallQueryPolicy(
  prompt: string,
  sessionKey: string | undefined,
  cfg: RecallQueryPolicyConfig
): RecallQueryPolicyResult {
  const normalizedPrompt = collapseWhitespace(prompt);
  const isCron = (sessionKey ?? "").includes(":cron:");
  if (!cfg.cronRecallPolicyEnabled || !isCron) {
    return {
      promptShape: "standard",
      retrievalQuery: prompt,
      skipConversationRecall: false,
      retrievalBudgetMode: "full",
    };
  }

  const promptShape = classifyRecallPromptShape(prompt);
  const maxChars = Math.max(120, cfg.cronRecallNormalizedQueryMaxChars);
  const tokenCap = clampInstructionHeavyTokenCap(cfg.cronRecallInstructionHeavyTokenCap);
  const retrievalQuery =
    promptShape === "instruction_heavy"
      ? buildInstructionHeavyQuery(prompt, tokenCap, maxChars)
      : buildStandardQuery(prompt, maxChars);

  const skipConversationRecall =
    cfg.cronConversationRecallMode === "never"
      ? true
      : cfg.cronConversationRecallMode === "always"
        ? false
        : promptShape === "instruction_heavy";

  const retrievalBudgetMode = promptShape === "instruction_heavy" ? "minimal" : "full";

  return {
    promptShape,
    retrievalQuery: retrievalQuery.length > 0 ? retrievalQuery : normalizedPrompt.slice(0, maxChars),
    skipConversationRecall,
    retrievalBudgetMode,
  };
}

import type { RecallPlanMode } from "./types.js";
import type { SearchQueryOptions } from "./search/port.js";

type QmdRecallCacheEntry = {
  value: unknown;
  cachedAtMs: number;
};

export type QmdRecallCacheSource = "fresh" | "stale";

export interface QmdRecallCacheHit<T> {
  value: T;
  source: QmdRecallCacheSource;
  ageMs: number;
}

export interface QmdRecallCacheKeyOptions {
  query: string;
  namespaces: string[];
  recallMode: RecallPlanMode;
  maxResults: number;
  memoryDir?: string;
  collection?: string;
  searchOptions?: SearchQueryOptions;
  // QMD search/subprocess strategies change the recalled results, so they must
  // participate in the cache key — otherwise a different strategy's cached QMD
  // phase is served within the TTL (gotcha #37). Issue #1335 (codex review #1422).
  searchStrategy?: string;
  subprocessStrategy?: string;
}

const qmdRecallCache = new Map<string, QmdRecallCacheEntry>();

function cloneCacheValue<T>(value: T): T {
  return structuredClone(value);
}

function normalizeQuery(query: string): string {
  return query.trim().toLowerCase().replace(/\s+/g, " ");
}

function normalizePathScope(pathValue: string | undefined): string {
  if (typeof pathValue !== "string") return "";
  return pathValue.trim().replace(/\\/g, "/");
}

function normalizeSearchOptions(
  options: SearchQueryOptions | undefined,
): Record<string, unknown> {
  if (!options) return {};
  return Object.fromEntries(
    Object.entries(options)
      .filter(([, value]) => value !== undefined)
      .sort(([left], [right]) => left.localeCompare(right)),
  );
}

export function buildQmdRecallCacheKey(
  options: QmdRecallCacheKeyOptions,
): string {
  return JSON.stringify({
    query: normalizeQuery(options.query),
    namespaces: [...options.namespaces].sort(),
    recallMode: options.recallMode,
    maxResults: options.maxResults,
    memoryDir: normalizePathScope(options.memoryDir),
    collection: options.collection ?? "",
    searchOptions: normalizeSearchOptions(options.searchOptions),
    searchStrategy: options.searchStrategy ?? "",
    subprocessStrategy: options.subprocessStrategy ?? "",
  });
}

export function getCachedQmdRecall<T>(
  cacheKey: string,
  options: {
    freshTtlMs: number;
    staleTtlMs: number;
  },
): QmdRecallCacheHit<T> | null {
  const entry = qmdRecallCache.get(cacheKey);
  if (!entry) return null;

  const ageMs = Date.now() - entry.cachedAtMs;
  if (ageMs <= options.freshTtlMs) {
    return { value: cloneCacheValue(entry.value as T), source: "fresh", ageMs };
  }
  if (ageMs <= options.staleTtlMs) {
    return { value: cloneCacheValue(entry.value as T), source: "stale", ageMs };
  }

  qmdRecallCache.delete(cacheKey);
  return null;
}

export function setCachedQmdRecall<T>(
  cacheKey: string,
  value: T,
  options: { maxEntries: number },
): void {
  qmdRecallCache.delete(cacheKey);
  if (options.maxEntries <= 0) return;

  qmdRecallCache.set(cacheKey, {
    value: cloneCacheValue(value),
    cachedAtMs: Date.now(),
  });

  while (qmdRecallCache.size > options.maxEntries) {
    const oldestKey = qmdRecallCache.keys().next().value;
    if (typeof oldestKey !== "string") break;
    qmdRecallCache.delete(oldestKey);
  }
}

export function clearQmdRecallCache(): void {
  qmdRecallCache.clear();
}

/** Number of cached recall entries. Used by the cache-layer registry in
 *  memory-cache.ts (`ALL_CACHE_LAYERS`) and its fitness tests (issue #1535). */
export function qmdRecallCacheSize(): number {
  return qmdRecallCache.size;
}

/**
 * Recall composition decision (#2972 layer 2).
 *
 * Extracted from recall-internal so that file stays under its ratchet
 * ceiling. Classifies injected memory context as complete / degraded /
 * missing, builds the compact (first-line) form from section buckets,
 * and turns outer-recall failures into the missing-note instead of "".
 */

import { isAbortError } from "./abort-error.js";
import {
  boundRecallContextComposition,
  composeMissingMemoryContext,
  composeRecallContext,
  RECALL_CONTEXT_SEPARATOR,
  type RecallContextComposition,
} from "./recall-context-composition.js";
import {
  describeSearchDegradations,
  fatalSearchDegradations,
  type SearchDegradation,
} from "./search/port.js";

export type RecallCompositionChunk = string | { readonly content: string };

export interface DecideRecallContextCompositionInput {
  context: string;
  compactContext?: string;
  footer?: string;
  maxChars: number;
  /** Mid-recall backend degradations (#3082). Absent on the healthy path. */
  backendDegradations?: readonly SearchDegradation[];
  /**
   * When false, `{ backend: "qmd", code: "backend_unavailable" }` is the
   * QMD-disabled/noop skip marker, not an outage. Other backends still count.
   * Default true so unit tests that pass degradations stay honest.
   */
  qmdExpected?: boolean;
}

export interface DecidedRecallContextComposition {
  composition: RecallContextComposition;
  context: string;
  truncated: boolean;
}

function firstLine(content: string): string {
  const trimmed = content.trim();
  if (trimmed.length === 0) return "";
  const newline = trimmed.indexOf("\n");
  return newline === -1 ? trimmed : trimmed.slice(0, newline).trimEnd();
}

function chunkContent(chunk: RecallCompositionChunk): string {
  return typeof chunk === "string" ? chunk : chunk.content;
}

/**
 * Shallow form of every section chunk: the first line of each entry,
 * so a budget miss prefers breadth-complete-but-shallow over a clipped
 * tail. Empty chunks contribute nothing.
 */
export function compactRecallContextFromBuckets(
  buckets: Iterable<readonly [unknown, readonly RecallCompositionChunk[]]>,
): string {
  const sections: string[] = [];
  for (const [, chunks] of buckets) {
    const lines: string[] = [];
    for (const chunk of chunks) {
      const line = firstLine(chunkContent(chunk));
      if (line.length > 0) lines.push(line);
    }
    if (lines.length > 0) sections.push(lines.join("\n"));
  }
  return sections.join(RECALL_CONTEXT_SEPARATOR);
}

export function decideRecallContextComposition(
  input: DecideRecallContextCompositionInput,
): DecidedRecallContextComposition {
  const observed = input.backendDegradations ?? [];
  const qmdExpected = input.qmdExpected !== false;
  const fatal = fatalSearchDegradations(observed).filter(
    (d) => qmdExpected || d.backend !== "qmd" || d.code !== "backend_unavailable",
  );
  if (fatal.length > 0 && input.context.trim().length === 0) {
    const missing = composeMissingMemoryContext({
      detail: describeSearchDegradations(fatal),
    });
    const composition = input.footer
      ? { ...missing, footer: input.footer }
      : missing;
    return {
      composition,
      context: composeRecallContext(composition),
      truncated: false,
    };
  }
  const bounded = boundRecallContextComposition({
    context: input.context,
    footer: input.footer,
    maxChars: input.maxChars,
    compactContext: input.compactContext,
  });
  if (fatal.length === 0) {
    return {
      composition: bounded,
      context: composeRecallContext(bounded),
      truncated:
        bounded.degradation?.reason === "budget-clipped" ||
        bounded.degradation?.reason === "budget-compacted",
    };
  }
  const composition = {
    ...bounded,
    degradation: {
      state: "degraded" as const,
      reason: "backend-unavailable" as const,
      detail: describeSearchDegradations(fatal),
      ...(bounded.degradation?.budget ? { budget: bounded.degradation.budget } : {}),
    },
  };
  return {
    composition,
    context: composeRecallContext(composition),
    truncated:
      bounded.degradation?.reason === "budget-clipped" ||
      bounded.degradation?.reason === "budget-compacted",
  };
}

export function notifyContextComposition(
  onContextComposition:
    | ((composition: RecallContextComposition) => void | PromiseLike<void>)
    | undefined,
  composition: RecallContextComposition,
  onError: (err: unknown) => void,
): void {
  if (!onContextComposition) return;
  try {
    const result = onContextComposition(composition);
    if (result && typeof result.then === "function") {
      void Promise.resolve(result).catch(onError);
    }
  } catch (err) {
    onError(err);
  }
}

/**
 * Outer-recall failure: abort stays silent (empty string). Timeout and
 * other errors become the missing-note so a failed query is never
 * indistinguishable from "no matches".
 */
export function recallFailureComposition(err: unknown): RecallContextComposition | null {
  if (isAbortError(err)) return null;
  const detail =
    err instanceof Error && err.message === "recall timeout"
      ? "timeout"
      : "recall_failed";
  return composeMissingMemoryContext({ detail });
}

import type {
  LifecycleState,
  MemoryFile,
  MemoryFrontmatter,
  MemoryStatus,
  PolicyClass,
  VerificationState,
} from "./types.js";
import {
  isUserBoundaryScope,
  normalizeUserContextScope,
  type UserContextScope,
} from "./user-model.js";

export type RetrievedMemoryCorrectionState =
  | "none"
  | "correction"
  | "superseded"
  | "disputed"
  | "forgotten";

export type RetrievedMemorySafety = "safe" | "requires-review" | "blocked";

export interface RetrievedMemoryProvenance {
  /** Frontmatter source, for example conversation, artifact, import, or consolidation. */
  source: string;
  /** ISO timestamp the memory was created, when known. */
  created?: string;
  /** ISO timestamp the memory was last updated, when known. */
  updated?: string;
  /** Namespace that produced the result, when known. */
  namespace?: string;
  /** Concrete retrieval scope. Defaults to namespace:<name> or the storage path. */
  scope: string;
  /** User-aware context scopes inferred from explicit scope metadata or tags. */
  userContextScopes: UserContextScope[];
  /** Why this memory was retrieved for the current response. */
  retrievalReason: string;
  /** Memory confidence clamped into [0, 1]. */
  confidence: number;
  /** Whether lifecycle, validity, or expiry metadata says this memory is stale now. */
  stale: boolean;
  /** Whether this result represents, has, or is affected by a user/system correction. */
  corrected: boolean;
  correctionState: RetrievedMemoryCorrectionState;
  /** Whether the memory is safe to use in the current context without asking first. */
  safeToUse: boolean;
  safety: RetrievedMemorySafety;
  safetyReasons: string[];
  status?: MemoryStatus;
  lifecycleState?: LifecycleState;
  verificationState?: VerificationState;
  policyClass?: PolicyClass;
  sourceMemoryId?: string;
  sourceTurnId?: string;
  derivedFrom?: string[];
  derivedVia?: MemoryFrontmatter["derived_via"];
  validAt?: string;
  invalidAt?: string;
  forgottenAt?: string;
  forgottenReason?: string;
}

export interface BuildRetrievedMemoryProvenanceOptions {
  namespace?: string;
  scope?: string;
  retrievalReason?: string;
  currentContextScopes?: readonly unknown[];
  now?: () => number;
}

const MEMORY_STATUS_VALUES: readonly MemoryStatus[] = [
  "active",
  "pending_review",
  "rejected",
  "quarantined",
  "superseded",
  "archived",
  "forgotten",
];

const LIFECYCLE_STATE_VALUES: readonly LifecycleState[] = [
  "candidate",
  "validated",
  "active",
  "stale",
  "archived",
];

const VERIFICATION_STATE_VALUES: readonly VerificationState[] = [
  "unverified",
  "user_confirmed",
  "system_inferred",
  "disputed",
];

const POLICY_CLASS_VALUES: readonly PolicyClass[] = [
  "ephemeral",
  "durable",
  "protected",
];

const SAFETY_VALUES: readonly RetrievedMemorySafety[] = [
  "safe",
  "requires-review",
  "blocked",
];

const CORRECTION_STATE_VALUES: readonly RetrievedMemoryCorrectionState[] = [
  "none",
  "correction",
  "superseded",
  "disputed",
  "forgotten",
];

export function buildRetrievedMemoryProvenance(
  memory: MemoryFile,
  options: BuildRetrievedMemoryProvenanceOptions = {},
): RetrievedMemoryProvenance {
  const frontmatter = memory.frontmatter;
  const nowMs = safeNow(options.now);
  const namespace = nonEmptyString(options.namespace);
  const scope =
    nonEmptyString(options.scope) ??
    (namespace ? `namespace:${namespace}` : nonEmptyString(memory.path) ?? "unknown");
  const userContextScopes = inferUserContextScopes(frontmatter);
  const currentContextScopes = normalizeScopeList(options.currentContextScopes);
  const stale = isStale(frontmatter, nowMs);
  const correctionState = inferCorrectionState(frontmatter);
  const corrected = correctionState !== "none";
  const safetyReasons = inferSafetyReasons({
    frontmatter,
    stale,
    userContextScopes,
    currentContextScopes,
  });
  const safety = inferSafety(safetyReasons);
  const provenance: RetrievedMemoryProvenance = {
    source: nonEmptyString(frontmatter.source) ?? "unknown",
    scope,
    userContextScopes,
    retrievalReason: nonEmptyString(options.retrievalReason) ?? "retrieved",
    confidence: clamp01(frontmatter.confidence),
    stale,
    corrected,
    correctionState,
    safeToUse: safety === "safe",
    safety,
    safetyReasons,
  };

  assignString(provenance, "created", frontmatter.created);
  assignString(provenance, "updated", frontmatter.updated);
  assignString(provenance, "namespace", namespace);
  assignStatus(provenance, "status", frontmatter.status);
  assignLifecycleState(provenance, "lifecycleState", frontmatter.lifecycleState);
  assignVerificationState(provenance, "verificationState", frontmatter.verificationState);
  assignPolicyClass(provenance, "policyClass", frontmatter.policyClass);
  assignString(provenance, "sourceMemoryId", frontmatter.sourceMemoryId);
  assignString(provenance, "sourceTurnId", frontmatter.sourceTurnId);
  assignString(provenance, "validAt", frontmatter.valid_at);
  assignString(provenance, "invalidAt", frontmatter.invalid_at);
  assignString(provenance, "forgottenAt", frontmatter.forgottenAt);
  assignString(provenance, "forgottenReason", frontmatter.forgottenReason);
  if (Array.isArray(frontmatter.derived_from) && frontmatter.derived_from.length > 0) {
    provenance.derivedFrom = stringList(frontmatter.derived_from);
  }
  if (frontmatter.derived_via !== undefined) {
    provenance.derivedVia = frontmatter.derived_via;
  }

  return provenance;
}

export function normalizeRetrievedMemoryProvenance(
  value: unknown,
): RetrievedMemoryProvenance | undefined {
  if (!value || typeof value !== "object") return undefined;
  const raw = value as Record<string, unknown>;
  const source = nonEmptyString(raw.source) ?? "unknown";
  const scope = nonEmptyString(raw.scope) ?? "unknown";
  const retrievalReason = nonEmptyString(raw.retrievalReason) ?? "retrieved";
  let safety = isRetrievedMemorySafety(raw.safety)
    ? raw.safety
    : raw.safeToUse === false
      ? "requires-review"
      : "safe";
  if (raw.safeToUse === false && safety === "safe") {
    safety = "requires-review";
  }
  const correctionState = isRetrievedMemoryCorrectionState(raw.correctionState)
    ? raw.correctionState
    : raw.corrected === true
      ? "correction"
      : "none";
  const safetyReasons = stringList(raw.safetyReasons);
  const provenance: RetrievedMemoryProvenance = {
    source,
    scope,
    userContextScopes: normalizeScopeList(raw.userContextScopes),
    retrievalReason,
    confidence: clamp01(raw.confidence),
    stale: raw.stale === true,
    corrected: raw.corrected === true || correctionState !== "none",
    correctionState,
    safeToUse: safety === "safe",
    safety,
    safetyReasons,
  };

  assignString(provenance, "created", raw.created);
  assignString(provenance, "updated", raw.updated);
  assignString(provenance, "namespace", raw.namespace);
  assignStatus(provenance, "status", raw.status);
  assignLifecycleState(provenance, "lifecycleState", raw.lifecycleState);
  assignVerificationState(provenance, "verificationState", raw.verificationState);
  assignPolicyClass(provenance, "policyClass", raw.policyClass);
  assignString(provenance, "sourceMemoryId", raw.sourceMemoryId);
  assignString(provenance, "sourceTurnId", raw.sourceTurnId);
  assignString(provenance, "validAt", raw.validAt);
  assignString(provenance, "invalidAt", raw.invalidAt);
  assignString(provenance, "forgottenAt", raw.forgottenAt);
  assignString(provenance, "forgottenReason", raw.forgottenReason);
  const derivedFrom = stringList(raw.derivedFrom);
  if (derivedFrom.length > 0) provenance.derivedFrom = derivedFrom;
  if (
    raw.derivedVia === "split" ||
    raw.derivedVia === "merge" ||
    raw.derivedVia === "update" ||
    raw.derivedVia === "pattern-reinforcement"
  ) {
    provenance.derivedVia = raw.derivedVia;
  }
  return provenance;
}

export function summarizeRetrievedMemoryProvenance(
  provenance: RetrievedMemoryProvenance,
): string {
  return [
    `source=${provenance.source}`,
    `created=${provenance.created ?? "unknown"}`,
    `scope=${provenance.scope}`,
    `confidence=${provenance.confidence.toFixed(2)}`,
    `stale=${provenance.stale ? "true" : "false"}`,
    `corrected=${provenance.corrected ? provenance.correctionState : "false"}`,
    `safe=${provenance.safeToUse ? "true" : "false"}`,
  ].join(" ");
}

function inferUserContextScopes(frontmatter: MemoryFrontmatter): UserContextScope[] {
  const scoped = frontmatter as MemoryFrontmatter & {
    userContextScopes?: readonly unknown[];
  };
  return normalizeScopeList([
    ...(Array.isArray(scoped.userContextScopes) ? scoped.userContextScopes : []),
    ...(Array.isArray(frontmatter.tags) ? frontmatter.tags : []),
  ]);
}

function normalizeScopeList(values: unknown): UserContextScope[] {
  const input = Array.isArray(values) ? values : [];
  const seen = new Set<UserContextScope>();
  const normalized: UserContextScope[] = [];
  for (const value of input) {
    const scope = normalizeUserContextScope(value);
    if (!scope || seen.has(scope)) continue;
    seen.add(scope);
    normalized.push(scope);
  }
  return normalized;
}

function isStale(frontmatter: MemoryFrontmatter, nowMs: number): boolean {
  if (
    frontmatter.status === "superseded" ||
    frontmatter.status === "archived" ||
    frontmatter.status === "forgotten"
  ) {
    return true;
  }
  if (
    frontmatter.lifecycleState === "stale" ||
    frontmatter.lifecycleState === "archived"
  ) {
    return true;
  }
  const expiresAtMs = parseEpochMs(frontmatter.expiresAt);
  if (expiresAtMs !== null && expiresAtMs <= nowMs) return true;
  const invalidAtMs = parseEpochMs(frontmatter.invalid_at);
  if (invalidAtMs !== null && invalidAtMs <= nowMs) return true;
  return false;
}

function inferCorrectionState(
  frontmatter: MemoryFrontmatter,
): RetrievedMemoryCorrectionState {
  if (frontmatter.status === "forgotten") return "forgotten";
  if (
    frontmatter.status === "superseded" ||
    frontmatter.supersededBy ||
    frontmatter.supersededAt
  ) {
    return "superseded";
  }
  if (frontmatter.verificationState === "disputed") return "disputed";
  if (frontmatter.category === "correction" || frontmatter.supersedes) {
    return "correction";
  }
  return "none";
}

function inferSafetyReasons(input: {
  frontmatter: MemoryFrontmatter;
  stale: boolean;
  userContextScopes: UserContextScope[];
  currentContextScopes: UserContextScope[];
}): string[] {
  const reasons: string[] = [];
  const { frontmatter, stale, userContextScopes, currentContextScopes } = input;
  if (frontmatter.status === "forgotten") reasons.push("status=forgotten");
  if (frontmatter.status === "rejected") reasons.push("status=rejected");
  if (frontmatter.status === "quarantined") reasons.push("status=quarantined");
  if (frontmatter.status === "pending_review") reasons.push("status=pending_review");
  if (frontmatter.status === "superseded") reasons.push("status=superseded");
  if (frontmatter.status === "archived") reasons.push("status=archived");
  if (frontmatter.verificationState === "disputed") {
    reasons.push("verification=disputed");
  }
  // Issue #1579 — x-ray visibility (rule 34: never a silent drop). When a
  // memory carries `blockedBy`, it was tombstone-blocked at the storage
  // chokepoint. Surface the tombstone id (and the matched tier when known)
  // in the safety reasons so every recall x-ray consumer (CLI / HTTP / MCP)
  // can attribute the pending_review state to a tombstone rather than a
  // generic low-confidence review.
  if (typeof frontmatter.blockedBy === "string" && frontmatter.blockedBy.length > 0) {
    reasons.push(`tombstone-blocked=${frontmatter.blockedBy}`);
    if (frontmatter.tombstoneBlockTier) {
      reasons.push(`tombstone-tier=${frontmatter.tombstoneBlockTier}`);
    }
  }
  if (stale) reasons.push("stale=true");

  const boundaryScopes = userContextScopes.filter(isUserBoundaryScope);
  if (boundaryScopes.length > 0) {
    const current = new Set(currentContextScopes);
    const hasMatchingBoundary = boundaryScopes.some((scope) => current.has(scope));
    if (!hasMatchingBoundary) {
      const joined = boundaryScopes.join(",");
      if (boundaryScopes.includes("do-not-use-outside-this-context")) {
        reasons.push(`boundary-blocked=${joined}`);
      } else {
        reasons.push(`boundary-review=${joined}`);
      }
    }
  }
  return uniqueStrings(reasons);
}

function inferSafety(reasons: readonly string[]): RetrievedMemorySafety {
  if (
    reasons.some((reason) =>
      reason === "status=forgotten" ||
      reason === "status=rejected" ||
      reason === "status=quarantined" ||
      reason.startsWith("boundary-blocked="),
    )
  ) {
    return "blocked";
  }
  return reasons.length > 0 ? "requires-review" : "safe";
}

function safeNow(now: (() => number) | undefined): number {
  const value = now ? now() : Date.now();
  return Number.isFinite(value) ? value : Date.now();
}

function parseEpochMs(value: unknown): number | null {
  if (typeof value !== "string" || value.trim().length === 0) return null;
  const parsed = Date.parse(value);
  return Number.isFinite(parsed) ? parsed : null;
}

function clamp01(value: unknown): number {
  if (typeof value !== "number" || !Number.isFinite(value)) return 0;
  return Math.min(1, Math.max(0, value));
}

function nonEmptyString(value: unknown): string | undefined {
  if (typeof value !== "string") return undefined;
  const trimmed = value.trim();
  return trimmed.length > 0 ? trimmed : undefined;
}

function stringList(value: unknown): string[] {
  if (!Array.isArray(value)) return [];
  return uniqueStrings(
    value
      .filter((item): item is string => typeof item === "string")
      .map((item) => item.trim())
      .filter((item) => item.length > 0),
  );
}

function uniqueStrings(values: readonly string[]): string[] {
  const seen = new Set<string>();
  const out: string[] = [];
  for (const value of values) {
    if (seen.has(value)) continue;
    seen.add(value);
    out.push(value);
  }
  return out;
}

type RetrievedMemoryProvenanceStringField =
  | "created"
  | "updated"
  | "namespace"
  | "sourceMemoryId"
  | "sourceTurnId"
  | "validAt"
  | "invalidAt"
  | "forgottenAt"
  | "forgottenReason";

function assignString(
  target: RetrievedMemoryProvenance,
  key: RetrievedMemoryProvenanceStringField,
  value: unknown,
): void {
  const normalized = nonEmptyString(value);
  if (normalized !== undefined) {
    target[key] = normalized;
  }
}

function assignStatus(
  target: RetrievedMemoryProvenance,
  key: "status",
  value: unknown,
): void {
  if (isMemoryStatus(value)) target[key] = value;
}

function assignLifecycleState(
  target: RetrievedMemoryProvenance,
  key: "lifecycleState",
  value: unknown,
): void {
  if (isLifecycleState(value)) target[key] = value;
}

function assignVerificationState(
  target: RetrievedMemoryProvenance,
  key: "verificationState",
  value: unknown,
): void {
  if (isVerificationState(value)) target[key] = value;
}

function assignPolicyClass(
  target: RetrievedMemoryProvenance,
  key: "policyClass",
  value: unknown,
): void {
  if (isPolicyClass(value)) target[key] = value;
}

function isMemoryStatus(value: unknown): value is MemoryStatus {
  return typeof value === "string" && MEMORY_STATUS_VALUES.includes(value as MemoryStatus);
}

function isLifecycleState(value: unknown): value is LifecycleState {
  return typeof value === "string" && LIFECYCLE_STATE_VALUES.includes(value as LifecycleState);
}

function isVerificationState(value: unknown): value is VerificationState {
  return typeof value === "string" && VERIFICATION_STATE_VALUES.includes(value as VerificationState);
}

function isPolicyClass(value: unknown): value is PolicyClass {
  return typeof value === "string" && POLICY_CLASS_VALUES.includes(value as PolicyClass);
}

function isRetrievedMemorySafety(value: unknown): value is RetrievedMemorySafety {
  return typeof value === "string" && SAFETY_VALUES.includes(value as RetrievedMemorySafety);
}

function isRetrievedMemoryCorrectionState(
  value: unknown,
): value is RetrievedMemoryCorrectionState {
  return typeof value === "string" && CORRECTION_STATE_VALUES.includes(value as RetrievedMemoryCorrectionState);
}

import type { PluginConfig } from "./types.js";

export interface RecallTimingRecord {
  readonly timestamp: string;
  readonly namespace: string;
