  const normalized = content.toLowerCase();
  if (hasInstructionOrPreferenceCue(normalized)) {
    return forceGeneric ||
      hasGuidanceIntentCue(normalized, intents) ||
      countGuidanceTermOverlap(normalized, query) >= 1;
