import { getCachedRuleMemories, setCachedRuleMemories } from "./memory-cache.js";
import { StorageManager } from "./storage.js";
import type { MemoryFile } from "./types.js";
import { countRecallTokenOverlap, normalizeRecallTokens } from "./recall-tokenization.js";

export type SemanticRuleVerificationStatus =
  | "verified"
  | "source-memory-missing"
  | "source-memory-archived"
  | "source-memory-forgotten"
  | "source-memory-not-episode";

export interface VerifiedSemanticRuleResult {
  rule: MemoryFile;
  score: number;
  sourceMemoryId: string;
  verificationStatus: SemanticRuleVerificationStatus;
  effectiveConfidence: number;
  matchedFields: string[];
}

const DEFAULT_MIN_EFFECTIVE_CONFIDENCE = 0.45;

function verificationConfidenceMultiplier(status: SemanticRuleVerificationStatus): number {
  switch (status) {
    case "verified":
      return 1;
    case "source-memory-not-episode":
      return 0.45;
    case "source-memory-archived":
      return 0.4;
    case "source-memory-forgotten":
      return 0.3;
    case "source-memory-missing":
      return 0.35;
    default:
      return 0.35;
  }
}

function resolveVerificationStatus(sourceMemory: MemoryFile | undefined): SemanticRuleVerificationStatus {
  if (!sourceMemory) return "source-memory-missing";
  if (sourceMemory.frontmatter.status === "archived") {
    return "source-memory-archived";
  }
  if (sourceMemory.frontmatter.status === "forgotten") return "source-memory-forgotten";
  if (sourceMemory.frontmatter.memoryKind !== "episode") return "source-memory-not-episode";
  return "verified";
}

function resolveEffectiveConfidence(rule: MemoryFile, sourceMemory: MemoryFile | undefined): {
  status: SemanticRuleVerificationStatus;
  effectiveConfidence: number;
} {
  const status = resolveVerificationStatus(sourceMemory);
  const ruleConfidence = Number.isFinite(rule.frontmatter.confidence) ? rule.frontmatter.confidence : 0.8;
  const sourceConfidence = Number.isFinite(sourceMemory?.frontmatter.confidence)
    ? sourceMemory!.frontmatter.confidence
    : ruleConfidence;
  const anchoredConfidence = Math.min(ruleConfidence, sourceConfidence);
  const effectiveConfidence = Math.max(
    0,
    Math.min(1, anchoredConfidence * verificationConfidenceMultiplier(status)),
  );
  return { status, effectiveConfidence };
}

function scoreVerifiedSemanticRuleCandidate(
  rule: MemoryFile,
  sourceMemory: MemoryFile | undefined,
  queryTokens: Set<string>,
  effectiveConfidence: number,
): { score: number; matchedFields: Set<string> } {
  const matchedFields = new Set<string>();
  let score = 0;

  const ruleContentMatches = countRecallTokenOverlap(queryTokens, rule.content);
  if (ruleContentMatches > 0) {
    score += ruleContentMatches * 5;
    matchedFields.add("ruleContent");
  }

  const tagMatches = countRecallTokenOverlap(queryTokens, rule.frontmatter.tags?.join(" "));
  if (tagMatches > 0) {
    score += tagMatches * 2;
    matchedFields.add("tags");
  }

  const sourceContentMatches = countRecallTokenOverlap(queryTokens, sourceMemory?.content);
  if (sourceContentMatches > 0) {
    score += sourceContentMatches * 2;
    matchedFields.add("sourceContent");
  }

  if (score > 0) {
    score += effectiveConfidence;
  }

  return { score, matchedFields };
}

export function compareVerifiedSemanticRuleResults(
  left: VerifiedSemanticRuleResult,
  right: VerifiedSemanticRuleResult,
): number {
  return (
    right.score - left.score ||
    right.effectiveConfidence - left.effectiveConfidence ||
    right.rule.frontmatter.updated.localeCompare(left.rule.frontmatter.updated) ||
    left.rule.frontmatter.id.localeCompare(right.rule.frontmatter.id)
  );
}

export async function searchVerifiedSemanticRules(options: {
  memoryDir: string;
  query: string;
  maxResults: number;
  minEffectiveConfidence?: number;
  /** Hot-memories cache gate (issue #1902, Codex P2). Threaded from the caller
   *  so a named-namespace root (never registered in the per-dir default map)
   *  honors the owning daemon's config instead of the process-wide default. */
  hotMemoriesCacheEnabled?: boolean;
}): Promise<VerifiedSemanticRuleResult[]> {
  const queryTokens = new Set(normalizeRecallTokens(options.query, ["what", "which"]));
  if (queryTokens.size === 0 || options.maxResults <= 0) return [];

  const storage = new StorageManager(options.memoryDir, undefined, options.hotMemoriesCacheEnabled);
  // Key the derived rule cache on the CORPUS version, not memory-status (Codex
  // P1, #1902): rule memories are derived from the full corpus, and plain
  // creates/writeChunk bump only the corpus sentinel. Keying on memory-status
  // would let a peer process serve a stale rule set that omits newly created
  // rule memories.
  const version = storage.getMemoryCorpusVersion();

  // Use derived rule cache to avoid O(146K) iteration on every call — but honor
  // the hotMemoriesCacheEnabled opt-out (Codex P2): when disabled, never read or
  // retain the derived cache, always rebuild from a fresh scan.
  const cacheEnabled = storage.isHotCacheEnabled();
  const keyId = storage.hotCacheKeyId();
  let cachedRules = cacheEnabled ? getCachedRuleMemories(storage.dir, version, keyId, storage.hotCacheTtlMs()) : null;
  if (!cachedRules) {
    const allMems = await storage.readAllMemories();
    cachedRules = setCachedRuleMemories(storage.dir, allMems, version, cacheEnabled, keyId);
  }
  const { all: ruleMemories, byId: memoryById } = cachedRules;
  const minEffectiveConfidence = options.minEffectiveConfidence ?? DEFAULT_MIN_EFFECTIVE_CONFIDENCE;

  const candidates: VerifiedSemanticRuleResult[] = [];
  // ruleMemories is pre-filtered to category=rule and recall-hidden statuses.
  for (const memory of ruleMemories) {
    if (memory.frontmatter.source !== "semantic-rule-promotion") continue;
    const sourceMemoryId = memory.frontmatter.sourceMemoryId;
    if (!sourceMemoryId) continue;

    const sourceMemory = memoryById.get(sourceMemoryId);
    const { status, effectiveConfidence } = resolveEffectiveConfidence(memory, sourceMemory);
    if (effectiveConfidence < minEffectiveConfidence) continue;

    const { score, matchedFields } = scoreVerifiedSemanticRuleCandidate(
      memory,
      sourceMemory,
      queryTokens,
      effectiveConfidence,
    );
    if (score <= 0) continue;

    candidates.push({
      rule: memory,
      score,
      sourceMemoryId,
      verificationStatus: status,
      effectiveConfidence,
      matchedFields: [...matchedFields].sort(),
    });
  }

  return candidates
    .sort(compareVerifiedSemanticRuleResults)
    .slice(0, options.maxResults);
}

import { renderAuthorityBoundContent } from "./recall-context-composition.js";
import type { MemoryFile } from "./types.js";

export interface TemporalTimelineRecallItem {
  memory: MemoryFile;
  eventAt: string;
  observedAt?: string;
  sessionKey?: string;
  validUntil?: string;
}

export interface TemporalTimelineRecallOptions {
  items: readonly TemporalTimelineRecallItem[];
  query: string;
  maxChars: number;
  maxItems: number;
  title?: string;
  originAuthorityEnabled?: boolean;
  untrustedOrigins?: readonly string[];
}

const QUERY_STOPWORDS = new Set([
  "a", "an", "and", "did", "do", "first", "happened", "how", "i", "in",
  "is", "it", "last", "many", "most", "my", "of", "on", "or", "recent",
  "recently", "the", "to", "was", "what", "when", "which", "who", "with",
]);

function queryTerms(query: string): string[] {
  return [...new Set(
    query
      .toLowerCase()
      .match(/[\p{L}\p{N}][\p{L}\p{N}'_-]*/gu)
      ?.filter((term) => term.length > 1 && !QUERY_STOPWORDS.has(term)) ?? [],
  )];
}

function relevanceScore(item: TemporalTimelineRecallItem, terms: readonly string[]): number {
  if (terms.length === 0) return 1;
  const haystack = `${item.memory.content} ${(item.memory.frontmatter.tags ?? []).join(" ")} ${item.memory.frontmatter.entityRef ?? ""}`.toLowerCase();
  let score = 0;
  for (const term of terms) {
    if (haystack.includes(term)) score += 1;
  }
  return score;
}

function compareChronology(
  left: TemporalTimelineRecallItem,
  right: TemporalTimelineRecallItem,
): number {
  const eventOrder = left.eventAt.localeCompare(right.eventAt);
  if (eventOrder !== 0) return eventOrder;
  const observedOrder = (left.observedAt ?? "").localeCompare(right.observedAt ?? "");
  if (observedOrder !== 0) return observedOrder;
  return left.memory.frontmatter.id.localeCompare(right.memory.frontmatter.id);
}

function clip(text: string, maxChars: number): string {
  if (text.length <= maxChars) return text;
  if (maxChars <= 1) return text.slice(0, maxChars);
  return `${text.slice(0, maxChars - 1).trimEnd()}…`;
}

/**
 * Build a query-focused timeline from ingest-indexed memory primitives.
 * Selection is relevance-first; presentation is always event-time ordered.
 */
export function buildTemporalTimelineRecallSection(
  options: TemporalTimelineRecallOptions,
): string {
  const maxChars = Number.isFinite(options.maxChars) ? Math.floor(options.maxChars) : 0;
  const maxItems = Number.isFinite(options.maxItems) ? Math.floor(options.maxItems) : 0;
  if (maxChars <= 0 || maxItems <= 0 || options.items.length === 0) return "";

  const terms = queryTerms(options.query);
  const uniqueById = new Map<string, TemporalTimelineRecallItem>();
  for (const item of options.items) {
    const id = item.memory.frontmatter.id;
    const current = uniqueById.get(id);
    if (!current || compareChronology(item, current) < 0) uniqueById.set(id, item);
  }

  const scored = [...uniqueById.values()].map((item) => ({
    item,
    score: relevanceScore(item, terms),
  }));
  const relevant = scored.some(({ score }) => score > 0)
    ? scored.filter(({ score }) => score > 0)
    : scored;
  const selected = relevant
    .sort((left, right) => {
      if (right.score !== left.score) return right.score - left.score;
      return compareChronology(left.item, right.item);
    })
    .slice(0, maxItems)
    .map(({ item }) => item)
    .sort(compareChronology);

  const title = options.title ?? "Cross-session temporal timeline";
  const lines = [
    `## ${title}`,
    "Ordered by event time across source sessions; event time is distinct from ingest time.",
  ];
  for (const item of selected) {
    const provenance = [
      `event=${item.eventAt}`,
      item.validUntil ? `until<${item.validUntil}` : "",
      item.observedAt ? `observed=${item.observedAt}` : "",
      item.sessionKey ? `session=${item.sessionKey}` : "",
    ].filter(Boolean).join(", ");
    const content = renderAuthorityBoundContent(
      item.memory.content.trim(),
      item.memory.frontmatter.origin,
      {
        enabled: options.originAuthorityEnabled === true,
        untrustedOrigins: options.untrustedOrigins ?? [],
      },
    );
    lines.push(`- [${provenance}] ${content}`);
  }
  return clip(lines.join("\n"), maxChars);
}

/**
 * Episodic-context recall section (issue #2331, harmonic-memory P3).
 *
 * Extracted sibling of `recallInternal`'s final assembly phase: resolves the
 * structured `sources` provenance of the top recalled facts to LCM archive
 * turn ranges, groups overlapping ranges into episodes, and appends the raw
 * turns as a `## Source Episodes` section — pure lookup + formatting, no LLM
 * calls, read-only archive access, inside the enrichment deadline.
 *
 * Opt-in: the registry entry is gated on `episodicContextEnabled === true`
 * (default off), so flag-off returns before touching the archive and recall
 * output stays byte-identical.
 */

import { lcmSessionKeyForNamespace } from "../coding/coding-namespace.js";
import { type EpisodicFactInput, planEpisodeWindowsWithFallback } from "../episodic-context.js";
import type { LcmMessage } from "../lcm/archive.js";
import { log } from "../logger.js";
import {
  type RecallSectionMetric,
  resolveRecallCoreSectionDeadlineMs,
  runRecallSectionWithinDeadline,
} from "../recall-qos.js";
import { cleanArchivedUserMessage } from "../user-message-cleaning.js";
import type { RecallSectionBuckets } from "./recall-section-coordinator.js";
import type { RecallInternalDeps } from "./recall-internal-deps.js";
import type { ScopePlan } from "../scopes/scope-plan.js";

/** Cap on recalled facts whose provenance is read per recall. */
const EPISODIC_FACT_SCAN_LIMIT = 8;
/** Per-turn character cap inside a Source Episodes block. */
const EPISODIC_TURN_CHAR_LIMIT = 300;

export async function appendEpisodicContextSection(
  deps: RecallInternalDeps,
  options: {
    sectionBuckets: RecallSectionBuckets;
    recalledMemoryPaths: string[];
    recalledMemoryNamespaces: Array<string | undefined>;
    scopePlan: ScopePlan;
    namespacesEnabled: boolean;
    enrichmentSectionDeadlineMs: number;
    recallOuterTimeoutMs: number;
    recallStart: number;
    abortSignal?: AbortSignal;
    recordMetric: (metric: RecallSectionMetric) => void;
  },
): Promise<void> {
  const engine = deps.lcmEngine;
  if (!engine?.enabled) return;
  if (!deps.isRecallSectionEnabled("episodic-context", false)) return;
  const maxEpisodes =
    deps.getRecallSectionNumber("episodic-context", "maxResults") ?? 2;
  const maxTurns = deps.getRecallSectionNumber("episodic-context", "maxTurns") ?? 8;
  const skip = (timing: string) =>
    options.recordMetric({
      section: "episodicContext",
      priority: "enrichment",
      durationMs: 0,
      deadlineMs: options.enrichmentSectionDeadlineMs,
      source: "skip",
      success: true,
      timing,
    });
  if (maxEpisodes <= 0 || maxTurns <= 0) {
    // Zero semantics (checklist item 33): disable before any archive query.
    skip("skip(limit=0)");
    return;
  }
  if (options.recalledMemoryPaths.length === 0) {
    skip("skip(no-memories)");
    return;
  }

  const outerDeadlineAtMs =
    options.recallOuterTimeoutMs > 0
      ? options.recallStart + options.recallOuterTimeoutMs
      : null;
  const remainingOuterMs =
    outerDeadlineAtMs === null ? null : outerDeadlineAtMs - deps.recallAssemblyClockMs();
  const deadlineMs = resolveRecallCoreSectionDeadlineMs({
    configuredCoreDeadlineMs: options.enrichmentSectionDeadlineMs,
    remainingOuterMs,
  });

  const outcome = await runRecallSectionWithinDeadline<string | null>({
    deadlineMs,
    fallback: null,
    parentSignal: options.abortSignal,
    run: async (signal) => {
      // 1. Structured provenance from the top recalled facts. Facts whose
      // frontmatter carries no `sources` array are silently skipped (no
      // legacy scalar `source` parsing — issue non-goal).
      const facts: EpisodicFactInput[] = [];
      const scanLimit = Math.min(
        options.recalledMemoryPaths.length,
        EPISODIC_FACT_SCAN_LIMIT,
      );
      for (let index = 0; index < scanLimit; index += 1) {
        const memoryPath = options.recalledMemoryPaths[index]!;
        const namespace = options.recalledMemoryNamespaces[index];
        try {
          const storage = await deps.storageRouter.storageFor(
            namespace ?? deps.config.defaultNamespace,
          );
          const memory = await storage.readMemoryByPath(memoryPath);
          const sources = memory?.frontmatter?.sources;
          if (memory && Array.isArray(sources) && sources.length > 0) {
            facts.push({
              memoryId: memory.frontmatter.id,
              rank: index,
              sources,
            });
          }
        } catch (err) {
          log.debug(
            `episodic-context: provenance read failed for ${memoryPath}`,
            err,
          );
        }
      }
      if (facts.length === 0) return null;

      // 2. Authoritative LCM session ids for a provenance sessionKey
      // (checklist item 30): only keys framed under the caller's authorized read
      // namespaces. A foreign session's rows live under a foreign namespace
      // frame and are unreachable through this mapping.
      const readNamespaces = options.namespacesEnabled
        ? options.scopePlan.lcmReadNamespaces
        : [deps.config.defaultNamespace];
      const candidateSessionIds = (sessionKey: string): string[] => {
        const seen = new Set<string>();
        const out: string[] = [];
        for (const namespace of readNamespaces) {
          const key =
            lcmSessionKeyForNamespace(
              namespace,
              sessionKey,
              deps.config.defaultNamespace,
            ) ?? sessionKey;
          if (!seen.has(key)) {
            seen.add(key);
            out.push(key);
          }
        }
        return out;
      };

      // 3. Plan windows (pure) with the single documented quote fallback.
      const windows = await planEpisodeWindowsWithFallback({
        recalledFacts: facts,
        maxEpisodes,
        maxTurnsPerEpisode: maxTurns,
        locateQuote: async (quote, sessionKey) => {
          for (const sessionId of candidateSessionIds(sessionKey)) {
            try {
              const hits = await engine.searchContextFull(quote, 1, sessionId);
              if (hits.length > 0) return hits[0]!.turn_index;
            } catch (err) {
              // One failing session read must not sink the fallback; try the
              // next candidate (fail-open per candidate).
              log.debug(
                `episodic-context: quote search failed for session ${sessionId}`,
                err,
              );
            }
          }
          return null;
        },
      });
      if (windows.length === 0) return null;

      // 4. Fetch + clean raw turns. `getMessages` bounds are inclusive, so
      // the exclusive `toTurn` passes as `toTurn - 1`.
      const episodes: Array<{
        sessionKey: string;
        fromTurn: number;
        toTurn: number;
        memoryIds: readonly string[];
        turns: ReadonlyArray<{ role: string; content: string }>;
      }> = [];
      for (const window of windows) {
        if (signal.aborted) break;
        let rows: LcmMessage[] = [];
        for (const sessionId of candidateSessionIds(window.sessionKey)) {
          try {
            const fetched = await engine.getTurnRange(
              sessionId,
              window.fromTurn,
              window.toTurn - 1,
            );
            if (fetched.length > 0) {
              rows = fetched;
              break;
            }
          } catch (err) {
            // A failing session read skips that candidate only; the window
            // is dropped when every candidate fails (fail-open).
            log.debug(
              `episodic-context: turn-range read failed for session ${sessionId}`,
              err,
            );
          }
        }
        if (rows.length === 0) continue;
        const turns = rows
          .filter((m) => m.role === "user" || m.role === "assistant")
          .map((m) => ({
            role: m.role,
            content:
              m.role === "user"
                ? cleanArchivedUserMessage(m.content)
                : m.content,
          }))
          .map((turn) => ({
            ...turn,
            content:
              turn.content.length > EPISODIC_TURN_CHAR_LIMIT
                ? `${turn.content.slice(0, EPISODIC_TURN_CHAR_LIMIT)}…`
                : turn.content,
          }));
        if (turns.length === 0) continue;
        episodes.push({
          sessionKey: window.sessionKey,
          fromTurn: window.fromTurn,
          toTurn: window.toTurn,
          memoryIds: window.memoryIds,
          turns,
        });
      }
      return episodes.length > 0
        ? deps.recallResultFormatter.formatEpisodicContext(episodes)
        : null;
    },
  });

  options.recordMetric({
    section: "episodicContext",
    priority: "enrichment",
    durationMs: outcome.durationMs,
    deadlineMs,
    source: outcome.timedOut ? "timeout" : "fresh",
    success: true,
    ...(outcome.timedOut
      ? { timing: `timeout(${Math.max(0, Math.round(outcome.durationMs))}ms)` }
      : {}),
  });
  if (outcome.value === null) return;
  const maxChars = deps.getRecallSectionMaxChars("episodic-context");
  const body =
    typeof maxChars === "number"
      ? deps.truncateRecallSectionToBudget(outcome.value, maxChars)
      : outcome.value;
  deps.appendRecallSection(options.sectionBuckets, "episodic-context", body);
}

/**
 * Composite profile storage proxy for recall orchestration — extracted from
 * recall-internal.ts (issue #1526, seam 18).
 */

import path from "node:path";
import type { StorageManager } from "../index.js";

export interface CompositeProfileStorageOptions {
  profileStorages: StorageManager[];
  memoryDir: string;
}

export interface CompositeProfileStorageResult {
  profileStorage: StorageManager;
  profileStorageDirs: string[];
}

/**
 * Creates a composite profile storage proxy over multiple namespace storage instances.
 * When multiple storages exist, methods aggregate results across all instances.
 * When storages is empty, returns a safe empty fallback storage.
 */
export function resolveCompositeProfileStorage(
  options: CompositeProfileStorageOptions,
): CompositeProfileStorageResult {
  const { profileStorages, memoryDir } = options;

  const emptyProfileStorage = new Proxy(
    { dir: path.join(memoryDir, ".empty-scope-profile") } as unknown as StorageManager,
    {
      get(target, prop: string | symbol) {
        if (prop in target) return Reflect.get(target, prop);
        if (prop === "readProfile") return async () => "";
        if (
          prop === "readQuestions" ||
          prop === "listEntityNames" ||
          prop === "readContinuityIncidents"
        )
          return async () => [];
        if (
          prop === "readIdentityAnchor" ||
          prop === "readIdentityImprovementLoops"
        )
          return async () => "";
        if (prop === "readEntity" || prop === "readMemoryByPath")
          return async () => null;
        return async () => [];
      },
    },
  );

  const profileStorage =
    profileStorages.length <= 1
      ? profileStorages[0] ?? emptyProfileStorage
      : new Proxy(profileStorages[0] as StorageManager, {
          get(target, prop: string | symbol) {
            if (prop === "readProfile") {
              return async () => {
                for (const storage of profileStorages) {
                  const profile = await storage.readProfile();
                  if (profile.trim().length > 0) return profile;
                }
                return "";
              };
            }
            if (prop === "readQuestions") {
              return async (...args: unknown[]) => {
                const merged: unknown[] = [];
                const seen = new Set<string>();
                const priorityOf = (question: unknown): number => {
                  const priority = Number((question as Record<string, unknown>)?.priority ?? 0);
                  return Number.isFinite(priority) ? priority : 0;
                };
                for (const storage of profileStorages) {
                  const readFn = (storage as unknown as Record<string, (...a: unknown[]) => Promise<unknown[]>>).readQuestions;
                  const questions = await readFn.call(storage, ...args);
                  for (const question of questions) {
                    const key = typeof question === "string" ? question : JSON.stringify(question);
                    if (seen.has(key)) continue;
                    seen.add(key);
                    merged.push(question);
                  }
                }
                return merged.sort(
                  (left, right) =>
                    priorityOf(right) - priorityOf(left) ||
                    String((left as Record<string, unknown>)?.id ?? "").localeCompare(String((right as Record<string, unknown>)?.id ?? "")),
                );
              };
            }
            if (prop === "readIdentityAnchor") {
              return async () => {
                for (const storage of profileStorages) {
                  const anchor = (await storage.readIdentityAnchor()) ?? "";
                  if (anchor.trim().length > 0) return anchor;
                }
                return "";
              };
            }
            if (prop === "readIdentityImprovementLoops") {
              return async () => {
                const sections: string[] = [];
                const seen = new Set<string>();
                for (const storage of profileStorages) {
                  const loops = ((await storage.readIdentityImprovementLoops()) ?? "").trim();
                  if (!loops || seen.has(loops)) continue;
                  seen.add(loops);
                  sections.push(loops);
                }
                return sections.join("\n\n");
              };
            }
            if (prop === "readContinuityIncidents") {
              return async (...args: unknown[]) => {
                const limit = typeof args[0] === "number" && Number.isFinite(args[0]) ? Math.max(0, args[0]) : undefined;
                const incidents: unknown[] = [];
                const seen = new Set<string>();
                const incidentTime = (incident: unknown): number => {
                  const incObj = incident as Record<string, unknown>;
                  const raw = incObj?.updatedAt ?? incObj?.openedAt ?? incObj?.createdAt;
                  const parsed = typeof raw === "string" ? Date.parse(raw) : Number.NaN;
                  return Number.isFinite(parsed) ? parsed : 0;
                };
                for (const storage of profileStorages) {
                  const readFn = (storage as unknown as Record<string, (...a: unknown[]) => Promise<unknown[]>>).readContinuityIncidents;
                  for (const incident of await readFn.call(storage, ...args)) {
                    const key = JSON.stringify(incident);
                    if (seen.has(key)) continue;
                    seen.add(key);
                    incidents.push(incident);
                  }
                }
                incidents.sort(
                  (left, right) =>
                    incidentTime(right) - incidentTime(left) ||
                    String((left as Record<string, unknown>)?.id ?? "").localeCompare(String((right as Record<string, unknown>)?.id ?? "")),
                );
                return limit === undefined ? incidents : incidents.slice(0, limit);
              };
            }
            if (prop === "listEntityNames") {
              return async (...args: unknown[]) => {
                const names = new Set<string>();
                for (const storage of profileStorages) {
                  const listFn = (storage as unknown as Record<string, (...a: unknown[]) => Promise<string[]>>).listEntityNames;
                  for (const name of await listFn.call(storage, ...args)) names.add(name);
                }
                return [...names];
              };
            }
            if (prop === "readEntity" || prop === "readMemoryByPath") {
              return async (...args: unknown[]) => {
                for (const storage of profileStorages) {
                  const methodFn = (storage as unknown as Record<string, (...a: unknown[]) => Promise<unknown>>)[prop as string];
                  if (methodFn) {
                    const value = await methodFn.call(storage, ...args);
                    if (value) return value;
                  }
                }
                return null;
              };
            }
            if (prop === "readAllMemories") {
              return async (...args: unknown[]) => {
                const memories: unknown[] = [];
                const seen = new Set<string>();
                for (const storage of profileStorages) {
                  const readFn = (storage as unknown as Record<string, (...a: unknown[]) => Promise<unknown[]>>).readAllMemories;
                  for (const memory of await readFn.call(storage, ...args)) {
                    const memObj = memory as Record<string, unknown>;
                    const key = String(memObj?.path ?? (memObj?.frontmatter as Record<string, unknown>)?.id ?? JSON.stringify(memory));
                    if (seen.has(key)) continue;
                    seen.add(key);
                    memories.push(memory);
                  }
                }
                return memories;
              };
            }
            return Reflect.get(target, prop);
          },
        });

  const profileStorageDirs = Array.from(
    new Set(
      profileStorages
        .map((storage) => storage.dir)
        .filter((dir): dir is string => typeof dir === "string" && dir.length > 0),
    ),
  );

  return { profileStorage, profileStorageDirs };
}

import { isChangeOrientedQuery, stateViewKey } from "./recall-state-view.js";
/**
 * State-view anchor admission (#2859).
 *
 * Shared namespace-qualified admission tracker for the recall safety
 * filter (QMD/embedding/cold paths) and the recent-scan path. A deferred
 * superseded row is admitted only when an in-set successor anchors it —
 * through the row's own `supersededBy` or through an admitted successor's
 * `supersedes` back-pointer. Identities are `namespace\0id`, so identical
 * ids across namespace fanout never cross-anchor.
 */
import { shouldFilterSupersededFromRecall } from "./temporal-supersession.js";
import type { MemoryFile } from "./types.js";

export interface StateViewAnchorFrontmatter {
  id?: string;
  supersedes?: string;
  supersededBy?: string;
}

/**
 * #2859 — pair reconciliation and packet-counting caps apply only WITHOUT
 * a historical pin: under asOf the validity filter legitimately orphans
 * predecessors (see annotateStateView's asOf mode).
 */
export function stateViewPacketActive(stateViewActive: boolean | undefined, asOfMs: number | undefined): boolean {
  return stateViewActive === true && !(typeof asOfMs === "number" && Number.isFinite(asOfMs));
}

/**
 * #1952/#2859 — config flag OR per-call override, gated on change intent.
 * Packet semantics are off under a historical asOf pin (see stateViewPacketActive).
 */
export function resolveRecallStateViewFlags(
  optionFlag: boolean | undefined,
  configFlag: boolean | undefined,
  retrievalQuery: string,
  asOfMs: number | undefined,
): { stateViewActive: boolean; stateViewPacketActive: boolean } {
  const stateViewActive =
    (optionFlag === true || configFlag === true) && isChangeOrientedQuery(retrievalQuery);
  return { stateViewActive, stateViewPacketActive: stateViewPacketActive(stateViewActive, asOfMs) };
}

export class StateViewAnchorTracker {
  private readonly admitted = new Set<string>();
  private readonly supersedesAnchors = new Set<string>();

  has(namespace: string | undefined, frontmatter: StateViewAnchorFrontmatter): boolean {
    const id = frontmatter.id;
    return typeof id === "string" && id.length > 0 ? this.admitted.has(stateViewKey(namespace, id)) : false;
  }

  /**
   * Register a row as admitted (a survivor of every gate, or a deferred
   * row whose successor anchored it). The row's `supersedes` back-pointer
   * then anchors its own predecessor.
   */
  admit(namespace: string | undefined, frontmatter: StateViewAnchorFrontmatter): void {
    const id = frontmatter.id;
    if (typeof id !== "string" || id.length === 0) return;
    this.admitted.add(stateViewKey(namespace, id));
    if (frontmatter.supersedes) {
      this.supersedesAnchors.add(stateViewKey(namespace, frontmatter.supersedes));
    }
  }

  /** True when an admitted successor anchors this superseded row. */
  anchored(namespace: string | undefined, frontmatter: StateViewAnchorFrontmatter): boolean {
    const id = frontmatter.id;
    if (typeof id !== "string" || id.length === 0) return false;
    const successorId = frontmatter.supersededBy;
    return (
      (typeof successorId === "string" && this.admitted.has(stateViewKey(namespace, successorId))) ||
      this.supersedesAnchors.has(stateViewKey(namespace, id))
    );
  }
}

export interface StateViewRecentAdmissionDeps {
  namespaceOf: (path: string) => string;
  isExcluded: (path: string) => boolean;
  supersessionOptions: { enabled: boolean; includeInRecall: boolean };
}

/**
 * #2859 — recent-scan admission: seed the tracker with every memory that
 * survives the supersession gate, then admit superseded rows anchored by
 * an in-set successor (fixpoint — an admitted link anchors the next).
 */
export function admitStateViewRecentMemories(
  memories: readonly MemoryFile[],
  deps: StateViewRecentAdmissionDeps
): StateViewAnchorTracker {
  const tracker = new StateViewAnchorTracker();
  for (const m of memories) {
    if (deps.isExcluded(m.path)) continue;
    if (m.frontmatter.status === "superseded") continue;
    if (shouldFilterSupersededFromRecall(m.frontmatter, deps.supersessionOptions)) continue;
    tracker.admit(deps.namespaceOf(m.path), m.frontmatter);
  }
  for (let progress = true; progress; ) {
    progress = false;
    for (const m of memories) {
      const namespace = deps.namespaceOf(m.path);
      if (tracker.has(namespace, m.frontmatter)) continue;
      if (deps.isExcluded(m.path)) continue;
      if (m.frontmatter.status !== "superseded") continue;
      if (!shouldFilterSupersededFromRecall(m.frontmatter, deps.supersessionOptions)) continue;
      if (tracker.anchored(namespace, m.frontmatter)) {
        tracker.admit(namespace, m.frontmatter);
        progress = true;
      }
    }
  }
  return tracker;
}

export interface RecentScanMemoryFilterDeps extends StateViewRecentAdmissionDeps {
  stateViewActive: boolean;
  asOfMs: number | undefined;
}

/**
 * Recent-scan admission for the fallback path.
 *
 * Superseded-status filtering delegates to
 * shouldFilterSupersededFromRecall so recent-scan and the QMD
 * safety filter share semantics (kill switch, audit mode, PR #402).
 * #1952: an active state view admits a superseded memory whose
 * successor ALSO survives this admission filter (fixpoint below).
 * PR #713: when `as_of` is active, pass superseded candidates
 * through here — boostSearchResults's `[valid_at, invalid_at)`
 * evaluation is the authoritative historical gate. Other
 * non-active statuses stay excluded.
 * #2859: namespace-qualified anchors with the supersedes
 * back-pointer — mirrors the safety-filter fixpoint.
 */
export function filterRecentScanMemories(
  memories: readonly MemoryFile[],
  deps: RecentScanMemoryFilterDeps,
): MemoryFile[] {
  const asOfActive = typeof deps.asOfMs === "number" && Number.isFinite(deps.asOfMs);
  const stateViewAnchors =
    deps.stateViewActive && !asOfActive ? admitStateViewRecentMemories(memories, deps) : null;
  return memories.filter((m) => {
    if (deps.isExcluded(m.path)) return false;
    const status = m.frontmatter.status;
    if (!status || status === "active") return true;
    if (status === "superseded") {
      if (asOfActive) return true;
      if (stateViewAnchors?.has(deps.namespaceOf(m.path), m.frontmatter)) {
        return true;
      }
      // Include superseded memory only if the canonical gate says
      // NOT to filter it (kill switch off or audit mode on).
      return !shouldFilterSupersededFromRecall(m.frontmatter, deps.supersessionOptions);
    }
    // Other non-active statuses (archived, retired, etc.) are
    // excluded from the recent-scan path by default.
    return false;
  });
}

/**
 * Shared memory-age resolution (issue #2976).
 *
 * "Age is not mtime" (distill-kura `weave.py` `age_days`): `cp -r`, a
 * restore, a checkout, or a bulk import resets file mtimes, so any freshness
 * mechanism keyed on mtime either switches itself off or boosts everything
 * equally. Remnic therefore resolves a memory's age from dates written
 * INSIDE the memory first:
 *
 *   1. frontmatter `created` — the recall ranking reference before #2976,
 *      kept first so every dated memory scores exactly as it did;
 *   2. frontmatter `updated` — the content-revision date;
 *   3. file mtime — only when no content date exists AND the caller's trust
 *      assessment accepts it (see `assessMtimeTrust`);
 *   4. otherwise UNKNOWN: no reference instant, and downstream scoring must
 *      treat unknown age as never-fresh (no recency boost), never as
 *      "just written".
 *
 * Bi-temporal `valid_at`/`observedAt` are deliberately NOT in the ladder:
 * they date when the fact was true, not when the memory was written, so a
 * fresh correction about an old event would be misaged by them.
 *
 * Bulk-touch heuristic (distill-kura measured 50/214 files sharing one
 * bulk-touch day, mtime understating true age by a median of 11 days, worst
 * case 425): a UTC calendar day shared by >= max(BULK_TOUCH_MIN_FILES,
 * BULK_TOUCH_STORE_FRACTION of the sampled files) is a bulk-touch day, and
 * mtimes falling on a bulk-touch day are untrusted — those ages are unknown,
 * not fresh. The sample is the scored result set of the calling pipeline
 * (bounded I/O), which observes a bulk-touched store as a same-day cluster.
 */

import { stat } from "node:fs/promises";

/** Minimum files sharing one calendar day before that day is bulk-touched. */
export const BULK_TOUCH_MIN_FILES = 2;
/** Fraction of the sampled files on one day that marks a bulk touch. */
export const BULK_TOUCH_STORE_FRACTION = 0.2;

/** Recency half-life (days) used by `applyRecencyBoost`. */
export const RECENCY_HALF_LIFE_DAYS = 7;

/** How the resolved age reference was obtained. */
export type MemoryAgeSource = "content" | "mtime" | "unknown";

export interface ResolvedMemoryAge {
  /** Reference instant for age computations, or null when age is unknown. */
  referenceMs: number | null;
  source: MemoryAgeSource;
}

/** Content dates written inside the memory (frontmatter). */
export interface MemoryAgeDates {
  created?: string | null;
  updated?: string | null;
}

/** Minimal memory shape the resolver needs; `path` keys the mtime fallback. */
export interface MemoryAgeSubject extends MemoryAgeDates {
  path: string;
}

/** MemoryFile slice `applyRecencyBoost` reads; dates live in frontmatter. */
export interface RecencyBoostSubject {
  path: string;
  frontmatter: MemoryAgeDates;
}

/** Result of assessing a sample of mtimes for bulk-touch clustering. */
export interface MtimeTrust {
  /** UTC day keys ("YYYY-MM-DD") whose mtime counts mark a bulk touch. */
  bulkTouchDays: ReadonlySet<string>;
  isTrusted(mtimeMs: number): boolean;
}

/** Per-recall mtime fallback context (null when no scored memory needs it). */
export interface MtimeFallbackContext {
  mtimeMsByPath: Map<string, number | null>;
  trust: MtimeTrust;
}

function finiteMs(value: string | null | undefined): number | null {
  if (typeof value !== "string") return null;
  const ms = Date.parse(value);
  return Number.isFinite(ms) ? ms : null;
}

/**
 * Resolve the reference instant for a memory's age. Content dates win over
 * mtime; an mtime is consulted only when no content date parses and the
 * trust assessment (when provided) accepts it; otherwise age is unknown.
 */
export function resolveMemoryAge(
  subject: MemoryAgeDates,
  mtimeMs?: number | null,
  trust?: MtimeTrust | null,
): ResolvedMemoryAge {
  const contentMs = finiteMs(subject.created) ?? finiteMs(subject.updated);
  if (contentMs !== null) return { referenceMs: contentMs, source: "content" };
  if (
    typeof mtimeMs === "number" &&
    Number.isFinite(mtimeMs) &&
    trust?.isTrusted(mtimeMs) !== false
  ) {
    return { referenceMs: mtimeMs, source: "mtime" };
  }
  return { referenceMs: null, source: "unknown" };
}

/** UTC calendar-day key ("YYYY-MM-DD") for a millisecond instant. */
export function utcDayKey(ms: number): string {
  return new Date(ms).toISOString().slice(0, 10);
}

/**
 * Assess a sample of mtimes: days shared by >= max(BULK_TOUCH_MIN_FILES,
 * BULK_TOUCH_STORE_FRACTION of the sample) are bulk-touch days, and their
 * mtimes are untrusted for age. An empty or scattered sample trusts nothing
 * less than it did before — only clustering changes anything.
 */
export function assessMtimeTrust(sampleMtimesMs: readonly number[]): MtimeTrust {
  const counts = new Map<string, number>();
  for (const ms of sampleMtimesMs) {
    if (!Number.isFinite(ms)) continue;
    const key = utcDayKey(ms);
    counts.set(key, (counts.get(key) ?? 0) + 1);
  }
  const threshold = Math.max(
    BULK_TOUCH_MIN_FILES,
    sampleMtimesMs.length * BULK_TOUCH_STORE_FRACTION,
  );
  const bulkTouchDays = new Set<string>();
  for (const [day, count] of counts) {
    if (count >= threshold) bulkTouchDays.add(day);
  }
  return {
    bulkTouchDays,
    isTrusted: (mtimeMs: number) => Number.isFinite(mtimeMs) && !bulkTouchDays.has(utcDayKey(mtimeMs)),
  };
}

/**
 * Build the mtime fallback context for a recall boost pass. Returns null —
 * with zero stat calls — when every scored memory already has a content
 * date, so the common path pays nothing. Otherwise stats the scored files
 * (bounded by the result count) and assesses their mtimes for bulk-touch
 * clustering. Unreadable files map to null mtimes (unknown age, never fresh).
 */
export async function collectMtimeFallbackContext(
  memories: ReadonlyArray<MemoryAgeSubject>,
): Promise<MtimeFallbackContext | null> {
  const needsFallback = memories.some(
    (m) => finiteMs(m.created) === null && finiteMs(m.updated) === null,
  );
  if (!needsFallback) return null;
  const stats = await Promise.all(
    memories.map(async (m) => {
      try {
        return (await stat(m.path)).mtimeMs;
      } catch {
        return null;
      }
    }),
  );
  const mtimeMsByPath = new Map<string, number | null>(
    memories.map((m, i) => [m.path, stats[i] ?? null]),
  );
  const trust = assessMtimeTrust(
    stats.filter((ms): ms is number => ms !== null && Number.isFinite(ms)),
  );
  return { mtimeMsByPath, trust };
}

/**
 * Apply the exponential recency blend to one score. Age resolves per
 * `resolveMemoryAge`; unknown age leaves the score untouched (never fresh).
 * A future reference instant clamps to age zero rather than boosting above
 * the recency ceiling (corrupt dates are not super-fresh).
 */
export function applyRecencyBoost(
  score: number,
  memory: RecencyBoostSubject,
  recencyWeight: number,
  nowMs: number,
  fallback?: MtimeFallbackContext | null,
): number {
  if (recencyWeight <= 0) return score;
  const resolved = resolveMemoryAge(
    memory.frontmatter,
    fallback?.mtimeMsByPath.get(memory.path) ?? null,
    fallback?.trust,
  );
  if (resolved.referenceMs === null) return score;
  const ageDays = Math.max(0, (nowMs - resolved.referenceMs) / 86_400_000);
  const recencyScore = Math.pow(0.5, ageDays / RECENCY_HALF_LIFE_DAYS);
  return score * (1 - recencyWeight) + recencyScore * recencyWeight;
}

import path from "node:path";
import { mkdir, writeFile } from "node:fs/promises";
import { listJsonFiles, readJsonFile } from "./json-store.js";
import { countRecallTokenOverlap, normalizeRecallTokens } from "./recall-tokenization.js";
import {
