} from "./store-contract.js";

export type WorkProductLedgerSource = "tool_result" | "cli" | "system" | "manual";
export type WorkProductLedgerKind = "artifact" | "file" | "record" | "report" | "workspace";
export type WorkProductLedgerAction = "created" | "updated" | "deleted" | "referenced" | "published";

export interface WorkProductLedgerEntry {
  schemaVersion: 1;
  entryId: string;
  recordedAt: string;
  sessionKey: string;
  source: WorkProductLedgerSource;
  kind: WorkProductLedgerKind;
  action: WorkProductLedgerAction;
  scope: string;
  summary: string;
  artifactPath?: string;
  objectiveStateSnapshotRefs?: string[];
  entityRefs?: string[];
  tags?: string[];
  metadata?: Record<string, string>;
}

export interface WorkProductLedgerStatus {
  enabled: boolean;
  rootDir: string;
  entriesDir: string;
  entries: {
    total: number;
    valid: number;
    invalid: number;
    byKind: Partial<Record<WorkProductLedgerKind, number>>;
    byAction: Partial<Record<WorkProductLedgerAction, number>>;
    latestEntryId?: string;
    latestRecordedAt?: string;
    latestSessionKey?: string;
  };
  latestEntry?: WorkProductLedgerEntry;
  invalidEntries: Array<{
    path: string;
    error: string;
  }>;
}

export interface WorkProductLedgerSearchResult {
  entry: WorkProductLedgerEntry;
  score: number;
  matchedFields: string[];
}

export function resolveWorkProductLedgerDir(memoryDir: string, overrideDir?: string): string {
  if (typeof overrideDir === "string" && overrideDir.trim().length > 0) {
    return overrideDir.trim();
  }
  return path.join(memoryDir, "state", "work-product-ledger");
}

export function validateWorkProductLedgerEntry(raw: unknown): WorkProductLedgerEntry {
  if (!isRecord(raw)) throw new Error("work-product ledger entry must be an object");
  if (raw.schemaVersion !== 1) throw new Error("schemaVersion must be 1");

  const source = assertString(raw.source, "source");
  if (!["tool_result", "cli", "system", "manual"].includes(source)) {
    throw new Error("source must be one of tool_result|cli|system|manual");
  }

  const kind = assertString(raw.kind, "kind");
  if (!["artifact", "file", "record", "report", "workspace"].includes(kind)) {
    throw new Error("kind must be one of artifact|file|record|report|workspace");
  }

  const action = assertString(raw.action, "action");
  if (!["created", "updated", "deleted", "referenced", "published"].includes(action)) {
    throw new Error("action must be one of created|updated|deleted|referenced|published");
  }

  return {
    schemaVersion: 1,
    entryId: assertSafePathSegment(assertString(raw.entryId, "entryId"), "entryId"),
    recordedAt: assertIsoRecordedAt(assertString(raw.recordedAt, "recordedAt")),
    sessionKey: assertString(raw.sessionKey, "sessionKey"),
    source: source as WorkProductLedgerSource,
    kind: kind as WorkProductLedgerKind,
    action: action as WorkProductLedgerAction,
    scope: assertString(raw.scope, "scope"),
    summary: assertString(raw.summary, "summary"),
    artifactPath: optionalString(raw.artifactPath),
    objectiveStateSnapshotRefs: optionalStringArray(raw.objectiveStateSnapshotRefs, "objectiveStateSnapshotRefs"),
    entityRefs: optionalStringArray(raw.entityRefs, "entityRefs"),
    tags: optionalStringArray(raw.tags, "tags"),
    metadata: validateStringRecord(raw.metadata, "metadata"),
  };
}

export async function recordWorkProductLedgerEntry(options: {
  memoryDir: string;
  workProductLedgerDir?: string;
  entry: WorkProductLedgerEntry;
}): Promise<string> {
  const rootDir = resolveWorkProductLedgerDir(options.memoryDir, options.workProductLedgerDir);
  const validated = validateWorkProductLedgerEntry(options.entry);
  const day = recordStoreDay(validated.recordedAt);
  const entriesDir = path.join(rootDir, "entries", day);
  const filePath = path.join(entriesDir, `${validated.entryId}.json`);
  await mkdir(entriesDir, { recursive: true });
  await writeFile(filePath, JSON.stringify(validated, null, 2), { encoding: "utf8", flag: "wx" });
  return filePath;
}

async function readWorkProductLedgerEntries(options: {
  memoryDir: string;
  workProductLedgerDir?: string;
}): Promise<{
  files: string[];
  entries: WorkProductLedgerEntry[];
  invalidEntries: Array<{ path: string; error: string }>;
}> {
  const rootDir = resolveWorkProductLedgerDir(options.memoryDir, options.workProductLedgerDir);
  const files = await listJsonFiles(path.join(rootDir, "entries"));
  const entries: WorkProductLedgerEntry[] = [];
  const invalidEntries: Array<{ path: string; error: string }> = [];
  for (const filePath of files) {
    try {
      entries.push(validateWorkProductLedgerEntry(await readJsonFile(filePath)));
    } catch (error) {
      invalidEntries.push({
        path: filePath,
        error: error instanceof Error ? error.message : String(error),
      });
    }
  }
  return { files, entries, invalidEntries };
}

function lexicalScoreWorkProductLedgerEntry(
  entry: WorkProductLedgerEntry,
  queryTokens: Set<string>,
): { score: number; matchedFields: string[] } {
  const weightedFields: Array<[string, string | undefined, number]> = [
    ["scope", entry.scope, 4],
    ["summary", entry.summary, 3],
    ["artifactPath", entry.artifactPath, 3],
    ["tags", entry.tags?.join(" "), 2],
    ["entityRefs", entry.entityRefs?.join(" "), 2],
    ["objectiveStateSnapshotRefs", entry.objectiveStateSnapshotRefs?.join(" "), 1],
    ["kind", entry.kind, 1],
    ["action", entry.action, 1],
    ["source", entry.source, 1],
  ];

  let score = 0;
  const matchedFields: string[] = [];
  for (const [field, value, weight] of weightedFields) {
    const matches = countRecallTokenOverlap(queryTokens, value, ["what", "can", "reuse"]);
    if (matches > 0) matchedFields.push(field);
    score += matches * weight;
  }
  return { score, matchedFields };
}

function scoreWorkProductLedgerEntry(
  entry: WorkProductLedgerEntry,
  lexicalScore: number,
  sessionKey?: string,
): number {
  let score = lexicalScore;
  if (entry.kind === "artifact" || entry.kind === "file") score += 1;
  if (entry.action === "created" || entry.action === "updated" || entry.action === "published") score += 1;
  if (sessionKey && entry.sessionKey === sessionKey) score += 1;

  const recordedAtMs = Date.parse(entry.recordedAt);
  if (Number.isFinite(recordedAtMs)) {
    const ageHours = Math.max(0, (Date.now() - recordedAtMs) / 3_600_000);
    score += 1 / (1 + ageHours);
  }
  return score;
}

export async function searchWorkProductLedgerEntries(options: {
  memoryDir: string;
  workProductLedgerDir?: string;
  query: string;
  maxResults: number;
  sessionKey?: string;
}): Promise<WorkProductLedgerSearchResult[]> {
  const maxResults = Math.max(0, Math.floor(options.maxResults));
  if (maxResults === 0) return [];

  const { entries } = await readWorkProductLedgerEntries(options);
  if (entries.length === 0) return [];

  const queryTokens = new Set(normalizeRecallTokens(options.query, ["what", "can", "reuse"]));
  if (queryTokens.size === 0) return [];

  const scored = entries.map((entry) => {
    const lexical = lexicalScoreWorkProductLedgerEntry(entry, queryTokens);
    return {
      entry,
      matchedFields: lexical.matchedFields,
      lexicalScore: lexical.score,
      score: scoreWorkProductLedgerEntry(entry, lexical.score, options.sessionKey),
    };
  });

  const filtered = scored.filter((result) => result.lexicalScore > 0);
  filtered.sort((left, right) => {
    if (right.score !== left.score) return right.score - left.score;
    return right.entry.recordedAt.localeCompare(left.entry.recordedAt);
  });

  return filtered.slice(0, maxResults).map(({ entry, score, matchedFields }) => ({
    entry,
    score,
    matchedFields,
  }));
}

export async function getWorkProductLedgerStatus(options: {
  memoryDir: string;
  workProductLedgerDir?: string;
  enabled: boolean;
}): Promise<WorkProductLedgerStatus> {
  const rootDir = resolveWorkProductLedgerDir(options.memoryDir, options.workProductLedgerDir);
  const entriesDir = path.join(rootDir, "entries");
  const { files, entries, invalidEntries } = await readWorkProductLedgerEntries(options);
  entries.sort((a, b) => b.recordedAt.localeCompare(a.recordedAt));

  const byKind: Partial<Record<WorkProductLedgerKind, number>> = {};
  const byAction: Partial<Record<WorkProductLedgerAction, number>> = {};
  for (const entry of entries) {
    byKind[entry.kind] = (byKind[entry.kind] ?? 0) + 1;
    byAction[entry.action] = (byAction[entry.action] ?? 0) + 1;
  }

  return {
    enabled: options.enabled,
    rootDir,
    entriesDir,
    entries: {
      total: files.length,
      valid: entries.length,
      invalid: invalidEntries.length,
      byKind,
      byAction,
      latestEntryId: entries[0]?.entryId,
      latestRecordedAt: entries[0]?.recordedAt,
      latestSessionKey: entries[0]?.sessionKey,
    },
    latestEntry: entries[0],
    invalidEntries,
  };
}

/**
 * Recall-internal state-view admission (issue #1952).
 *
 * Flag resolution, recent-scan successor-anchor admission, and the X-ray
 * inject-seam annotation live here so recall-internal.ts stays under its
 * ratchet ceiling. Callers keep one-line sites.
 */

import { isGenericRecallExcludedPath, type GenericRecallPathPolicy } from "./orchestration/generic-recall-paths.js";
import { isChangeOrientedQuery, type StateViewResult } from "./recall-state-view.js";
import { applyRecallStateViews } from "./recall-state-view-wire.js";
import { shouldFilterSupersededFromRecall } from "./temporal-supersession.js";
import type { MemoryFile } from "./types.js";

/**
 * Config flag OR per-call override, gated on change intent; computed once
 * for all branches.
 *
 * #2893: `query` MUST be the ORIGINAL prompt, not the cron-normalized
 * retrievalQuery — buildRecallQueryPolicy truncates standard prompts at
 * maxChars and strips stop-words ("when", "before", "after") from
 * instruction-heavy ones, either of which can erase the change-intent
 * signal before retrieval. Only the resulting boolean flows downstream;
 * retrieval itself keeps using the normalized query.
 */
export function resolveRecallStateViewActive(
  options: { stateView?: boolean },
  config: { recallStateViews?: boolean },
  query: string,
): boolean {
  return (options.stateView === true || config.recallStateViews === true) && isChangeOrientedQuery(query);
}

/**
 * Superseded-status filtering delegates to shouldFilterSupersededFromRecall
 * so recent-scan and the QMD safety filter share semantics (kill switch,
 * audit mode, PR #402).
 *
 * #1952: an active state view admits a superseded memory whose successor
 * ALSO survives this admission filter — a successor excluded by status or
 * path can never anchor (mirrors the filterSearchResultsByRecallSafety
 * fixpoint). Anchors grow through admitted chain links, so iterate to a
 * fixpoint.
 *
 * PR #713: when `as_of` is active, pass superseded candidates through here
 * — boostSearchResults's `[valid_at, invalid_at)` evaluation is the
 * authoritative historical gate. Other non-active statuses stay excluded.
 */
export function filterRecentScanMemoriesForStateView(
  memories: readonly MemoryFile[],
  config: GenericRecallPathPolicy,
  supersessionOptions: { enabled: boolean; includeInRecall: boolean },
  stateViewActive: boolean,
  asOfMs: number | undefined,
): MemoryFile[] {
  const asOfActive = typeof asOfMs === "number" && Number.isFinite(asOfMs);
  let stateViewAdmittedIds: Set<string> | null = null;
  if (stateViewActive && !asOfActive) {
    stateViewAdmittedIds = new Set(
      memories
        .filter(
          (m) =>
            !isGenericRecallExcludedPath(m.path, config) &&
            m.frontmatter.status !== "superseded" &&
            !shouldFilterSupersededFromRecall(m.frontmatter, supersessionOptions),
        )
        .map((m) => m.frontmatter.id)
        .filter((id): id is string => typeof id === "string" && id.length > 0),
    );
    for (let progress = true; progress; ) {
      progress = false;
      for (const m of memories) {
        const id = m.frontmatter.id;
        if (typeof id !== "string" || id.length === 0) continue;
        if (stateViewAdmittedIds.has(id)) continue;
        if (isGenericRecallExcludedPath(m.path, config)) continue;
        if (m.frontmatter.status !== "superseded") continue;
        if (!shouldFilterSupersededFromRecall(m.frontmatter, supersessionOptions)) continue;
        if (stateViewAdmittedIds.has(m.frontmatter.supersededBy ?? "")) {
          stateViewAdmittedIds.add(id);
          progress = true;
        }
      }
    }
  }
  return memories.filter((m) => {
    if (isGenericRecallExcludedPath(m.path, config)) return false;
    const status = m.frontmatter.status;
    if (!status || status === "active") return true;
    if (status === "superseded") {
      if (asOfActive) return true;
      const id = m.frontmatter.id;
      if (
        stateViewAdmittedIds !== null &&
        typeof id === "string" &&
        stateViewAdmittedIds.has(id)
      ) {
        return true;
      }
      // Include superseded memory only if the canonical gate says
      // NOT to filter it (kill switch off or audit mode on).
      return !shouldFilterSupersededFromRecall(m.frontmatter, supersessionOptions);
    }
    // Other non-active statuses (archived, retired, etc.) are
    // excluded from the recent-scan path by default.
    return false;
  });
}

/** Label the captured X-ray branch through the same inject-seam annotator. */
export function indexStateViewAnnotatedResults<T extends StateViewResult & { path: string; namespace?: string }>(
  results: T[],
  query: string,
  config: unknown,
  stateViewActive?: boolean,
  asOfMs?: number,
): Map<string, T> {
  return new Map(
    applyRecallStateViews(results, query, config, stateViewActive, asOfMs).map((xr) => [
      `${xr.namespace ?? ""}\0${xr.path}`,
      xr,
    ]),
  );
}

/**
 * Recognition-tier swap at fetchQmdMemoryResultsWithArtifactTopUp (issue #2975).
 *
 * Off-path (recallRecognitionTier !== true): original fetch only — no index
 * load, no model call. On-path: namespaces whose index is at or under
 * recognitionIndexMaxEntries go through one recognizer call; the rest keep
 * vector search. A failing recognizer degrades that namespace to vector search.
 */
import path from "node:path";

import { log } from "../logger.js";
import { dedupeResultsByNamespace } from "../recall-memory-map.js";
import {
  decideRecognitionTier,
  loadRecognitionIndex,
  runRecognitionTier,
  type RecognitionIndex,
} from "../recall-recognition-tier.js";
import type { QmdSearchResult } from "../types.js";
import { throwIfRecallAborted } from "./orchestrator-helpers.js";
import type { RecallInternalDeps } from "./recall-internal-deps.js";

export type RecognitionSearchDeps = Pick<
  RecallInternalDeps,
  "config" | "storageRouter" | "fastLlmForRerank" | "fetchQmdMemoryResultsWithArtifactTopUp"
>;

type ArtifactTopUpOptions = Parameters<
  RecognitionSearchDeps["fetchQmdMemoryResultsWithArtifactTopUp"]
>[3];

type RecognitionStorage = {
  dir: string;
  findExistingMemoryPaths(ids: string[]): Promise<Map<string, string[]>>;
};

export async function fetchQmdMemoryResultsWithRecognitionSwap(
  deps: RecognitionSearchDeps,
  prompt: string,
  qmdFetchLimit: number,
  qmdHybridFetchLimit: number,
  options: ArtifactTopUpOptions,
): Promise<QmdSearchResult[]> {
  if (
    deps.config.recallRecognitionTier !== true ||
    options.collection ||
    options.namespacesEnabled !== true
  ) {
    return deps.fetchQmdMemoryResultsWithArtifactTopUp(
      prompt,
      qmdFetchLimit,
      qmdHybridFetchLimit,
      options,
    );
  }

  const namespaces = options.recallNamespaces.filter(Boolean);
  if (namespaces.length === 0) {
    return deps.fetchQmdMemoryResultsWithArtifactTopUp(
      prompt,
      qmdFetchLimit,
      qmdHybridFetchLimit,
      options,
    );
  }

  throwIfRecallAborted(options.abortSignal);
  const maxEntries = deps.config.recognitionIndexMaxEntries;
  const recognitionNs: Array<{ namespace: string; storage: RecognitionStorage; index: RecognitionIndex }> = [];
  const vectorNs: string[] = [];

  for (const namespace of namespaces) {
    throwIfRecallAborted(options.abortSignal);
    const storage = (await deps.storageRouter.storageFor(namespace)) as RecognitionStorage;
    const index = await loadRecognitionIndex(storage.dir);
    const decision = decideRecognitionTier(index, { maxEntries });
    if (index !== null && decision.tier === "recognition") {
      recognitionNs.push({ namespace, storage, index });
    } else {
      vectorNs.push(namespace);
    }
  }

  if (recognitionNs.length === 0) {
    return deps.fetchQmdMemoryResultsWithArtifactTopUp(
      prompt,
      qmdFetchLimit,
      qmdHybridFetchLimit,
      options,
    );
  }

  const recognize = async (recognitionPrompt: string): Promise<string | null | undefined> => {
    const reply = await deps.fastLlmForRerank.chatCompletion(
      [{ role: "user", content: recognitionPrompt }],
      { operation: "recognition-tier", priority: "recall-critical" },
    );
    return reply?.content;
  };

  const recognized: QmdSearchResult[] = [];
  for (const { namespace, storage, index } of recognitionNs) {
    throwIfRecallAborted(options.abortSignal);
    try {
      const run = await runRecognitionTier(prompt, index.entries, recognize);
      recognized.push(
        ...(await hitsFromIds(namespace, storage, index, run.ids)),
      );
    } catch (err) {
      log.warn(
        `recognition tier degraded to vector search: recognizer failed${
          err instanceof Error ? ` (${err.message})` : ""
        }`,
      );
      vectorNs.push(namespace);
    }
  }

  const vectorResults =
    vectorNs.length === 0
      ? []
      : await deps.fetchQmdMemoryResultsWithArtifactTopUp(
          prompt,
          qmdFetchLimit,
          qmdHybridFetchLimit,
          { ...options, recallNamespaces: vectorNs },
        );

  return dedupeResultsByNamespace(
    [...recognized, ...vectorResults],
    options.resolveNamespace,
    qmdFetchLimit,
  );
}

export function recognitionHitScore(rankOffset: number): number {
  return 1 / (1 + rankOffset);
}

async function hitsFromIds(
  namespace: string,
  storage: RecognitionStorage,
  index: RecognitionIndex,
  ids: readonly string[],
): Promise<QmdSearchResult[]> {
  if (ids.length === 0) return [];
  const pathsById = await storage.findExistingMemoryPaths([...ids]);
  const descriptionById = new Map(index.entries.map((entry) => [entry.id, entry.description]));
  const hits: QmdSearchResult[] = [];
  for (const [offset, id] of ids.entries()) {
    const absPath = pathsById.get(id)?.[0];
    if (!absPath) continue;
    const rel = path.relative(storage.dir, absPath).split(path.sep).join("/");
    if (!rel || rel.startsWith("..")) continue;
    hits.push({
      docid: `${namespace}:${rel}`,
      namespace,
      path: rel,
      score: recognitionHitScore(offset),
      snippet: descriptionById.get(id) ?? id,
    });
  }
  return hits;
}

import { createHash } from "node:crypto";
import path from "node:path";
import {
  chmod,
  copyFile,
  lstat,
  mkdir,
  open,
  readFile,
  readdir,
  rm,
  stat,
  unlink,
  writeFile,
} from "node:fs/promises";
import { existsSync } from "node:fs";
import { resolveHomeDir } from "../runtime/env.js";
import { launchProcessSync } from "../runtime/child-process.js";

export interface MigrationResult {
  status: "fresh-install" | "already-migrated" | "migrated";
  copied: string[];
  tokensRegenerated: number;
  servicesReinstalled: string[];
  rollbackCommand: string;
}

interface RollbackManifestEntry {
  targetPath: string;
  backupPath?: string;
  createdByMigration?: boolean;
  contentHash?: string;
  mode?: number;
}

interface RollbackManifest {
  version: 1;
  createdAt: string;
  entries: RollbackManifestEntry[];
}

interface ValidatedRollbackManifestEntry extends RollbackManifestEntry {
  targetPath: string;
  backupPath?: string;
  contentHash?: string;
  mode?: number;
}

export interface MigrationOptions {
  connectorConfigPaths?: string[];
  cwd?: string;
  execCommand?: (command: string, args: string[]) => void;
  homeDir?: string;
  logger?: (message: string) => void;
  platform?: NodeJS.Platform;
  quiet?: boolean;
}

export interface RollbackResult {
  removed: string[];
  restored: string[];
}

interface TokenEntry {
  connector: string;
  createdAt: string;
  token: string;
}

type PersistRollbackManifest = () => Promise<void>;

const MARKER_FILE = ".migrated-from-engram";
const LOCK_FILE = ".migration.lock";
const ROLLBACK_MANIFEST = ".rollback.json";
const BACKUP_DIR = ".backup";
const LOCK_RETRY_MS = 100;
const LOCK_TIMEOUT_MS = 5_000;
const TOKEN_STORE_MODE = 0o600;

function resolvePlatform(options?: MigrationOptions): NodeJS.Platform {
  return options?.platform ?? process.platform;
}

function resolveMigrationHome(options?: MigrationOptions): string {
  return options?.homeDir ?? resolveHomeDir();
}

function resolveLogger(options?: MigrationOptions): (message: string) => void {
  const sink = options?.logger ?? ((message: string) => console.log(message));
  return (message: string) => {
    if (!options?.quiet) sink(`[remnic] ${message}`);
  };
}

function resolveExec(options?: MigrationOptions): (command: string, args: string[]) => void {
  return options?.execCommand ?? ((command: string, args: string[]) => {
    const result = launchProcessSync(command, args, { stdio: "ignore" });
    if (result.error) {
      throw result.error;
    }
    if (result.status !== 0) {
      const reason = result.status === null
        ? `signal ${result.signal ?? "unknown"}`
        : `exit code ${result.status}`;
      throw new Error(`migration command failed: ${command} ${args.join(" ")} (${reason})`);
    }
  });
}

function remnicRoot(homeDir: string): string {
  return path.join(homeDir, ".remnic");
}

function legacyRoot(homeDir: string): string {
  return path.join(homeDir, ".engram");
}

function legacyConfigPath(homeDir: string): string {
  return path.join(homeDir, ".config", "engram", "config.json");
}

function remnicConfigPath(homeDir: string): string {
  return path.join(homeDir, ".config", "remnic", "config.json");
}

function markerPath(homeDir: string): string {
  return path.join(remnicRoot(homeDir), MARKER_FILE);
}

function lockPath(homeDir: string): string {
  return path.join(remnicRoot(homeDir), LOCK_FILE);
}

function rollbackManifestPath(homeDir: string): string {
  return path.join(remnicRoot(homeDir), ROLLBACK_MANIFEST);
}

function backupRoot(homeDir: string): string {
  return path.join(remnicRoot(homeDir), BACKUP_DIR);
}

function defaultRollbackCommand(): string {
  return "remnic migrate --rollback";
}

function resolveMigrationCwd(options?: MigrationOptions): string {
  return path.resolve(options?.cwd ?? process.cwd());
}

function resolveConnectorConfigPath(candidate: string, cwd: string): string {
  return path.isAbsolute(candidate) ? path.resolve(candidate) : path.resolve(cwd, candidate);
}

async function ensureParent(filePath: string): Promise<void> {
  await mkdir(path.dirname(filePath), { recursive: true });
}

async function secureTokenFilePermissions(filePath: string): Promise<void> {
  await chmod(filePath, TOKEN_STORE_MODE);
}

async function writeOwnerOnlyFile(filePath: string, content: string): Promise<void> {
  await writeFile(filePath, content, { encoding: "utf8", mode: TOKEN_STORE_MODE });
  await chmod(filePath, TOKEN_STORE_MODE);
}

async function fileContentHash(filePath: string): Promise<string> {
  return createHash("sha256").update(await readFile(filePath)).digest("hex");
}

async function writeTokenStoreFile(filePath: string, content: string): Promise<void> {
  await writeOwnerOnlyFile(filePath, content);
}

function isRemnicTokenStorePath(filePath: string, homeDir: string): boolean {
  return path.resolve(filePath) === path.resolve(path.join(remnicRoot(homeDir), "tokens.json"));
}

async function pathExistsNoFollow(filePath: string): Promise<boolean> {
  try {
    await lstat(filePath);
    return true;
  } catch (error) {
    if ((error as NodeJS.ErrnoException).code === "ENOENT") return false;
    throw error;
  }
}

async function assertExistingRegularFileNoFollow(filePath: string, label: string): Promise<void> {
  const fileStat = await lstat(filePath);
  if (fileStat.isSymbolicLink()) {
    throw new Error(`${label} must not be a symlink: ${filePath}`);
  }
  if (!fileStat.isFile()) {
    throw new Error(`${label} must be a regular file: ${filePath}`);
  }
}

async function isExistingRegularFileNoFollow(filePath: string): Promise<boolean> {
  try {
    const fileStat = await lstat(filePath);
    return fileStat.isFile() && !fileStat.isSymbolicLink();
  } catch (error) {
    if ((error as NodeJS.ErrnoException).code === "ENOENT") return false;
    throw error;
  }
}

async function copyTreeMissing(
  source: string,
  destination: string,
  copied: string[],
  manifest: RollbackManifest,
  persistManifest?: PersistRollbackManifest,
  isRoot = true,
): Promise<void> {
  if (!existsSync(source)) return;
  const sourceStat = await lstat(source);
  if (sourceStat.isSymbolicLink()) {
    if (isRoot) {
      throw new Error(`legacy migration root must not be a symlink: ${source}`);
    }
    return;
  }
  if (sourceStat.isDirectory()) {
    await mkdir(destination, { recursive: true });
    const entries = await readdir(source, { withFileTypes: true });
    for (const entry of entries) {
      if (entry.name === MARKER_FILE || entry.name === LOCK_FILE || entry.name === ROLLBACK_MANIFEST) {
        continue;
      }
      await copyTreeMissing(
        path.join(source, entry.name),
        path.join(destination, entry.name),
        copied,
        manifest,
        persistManifest,
        false,
      );
    }
    return;
  }

  if (await pathExistsNoFollow(destination)) return;
  await ensureParent(destination);
  await copyFile(source, destination);
  await recordCreatedPath(destination, manifest, persistManifest);
  copied.push(destination);
}

function rewriteRemnicText(content: string): string {
  return content
    .replaceAll(".engram/", ".remnic/")
    .replaceAll(".engram\\", ".remnic\\")
    .replaceAll("ENGRAM_", "REMNIC_")
    .replaceAll("{{ENGRAM_TOKEN}}", "{{REMNIC_TOKEN}}")
    .replaceAll("${ENGRAM_AUTH_TOKEN}", "${REMNIC_AUTH_TOKEN}")
    .replaceAll("ai.engram.daemon", "ai.remnic.daemon")
    .replaceAll("engram.service", "remnic.service");
}

function rewriteTokenValue(token: string): string {
  return token.startsWith("engram_") ? `remnic_${token.slice("engram_".length)}` : token;
}

function parseTokenEntries(raw: unknown): TokenEntry[] {
  if (typeof raw !== "object" || raw === null) return [];

  if (Array.isArray((raw as { tokens?: unknown }).tokens)) {
    return ((raw as { tokens: unknown[] }).tokens)
      .filter((entry): entry is TokenEntry => {
        if (typeof entry !== "object" || entry === null) return false;
        const candidate = entry as Partial<TokenEntry>;
        return typeof candidate.connector === "string" &&
          candidate.connector.length > 0 &&
          typeof candidate.token === "string" &&
          candidate.token.length > 0 &&
          typeof candidate.createdAt === "string" &&
          candidate.createdAt.length > 0;
      })
      .map((entry) => ({ ...entry }));
  }

  return Object.entries(raw)
    .filter(([key, value]) => key !== "tokens" && typeof value === "string" && value.length > 0)
    .map(([connector, token]) => ({
      connector,
      createdAt: new Date().toISOString(),
      token,
    }));
}

function isPlainJsonObject(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

function parseRollbackManifestEntry(raw: unknown, index: number): RollbackManifestEntry {
  if (!isPlainJsonObject(raw)) {
    throw new Error(`rollback manifest entry ${index} must be an object`);
  }
  if (typeof raw.targetPath !== "string" || raw.targetPath.length === 0 || !path.isAbsolute(raw.targetPath)) {
    throw new Error(`rollback manifest entry ${index} has an invalid targetPath`);
  }
  if (raw.backupPath !== undefined && (typeof raw.backupPath !== "string" || raw.backupPath.length === 0 || !path.isAbsolute(raw.backupPath))) {
    throw new Error(`rollback manifest entry ${index} has an invalid backupPath`);
  }
  if (raw.createdByMigration !== undefined && typeof raw.createdByMigration !== "boolean") {
    throw new Error(`rollback manifest entry ${index} has an invalid createdByMigration flag`);
  }
  if (raw.contentHash !== undefined && (typeof raw.contentHash !== "string" || !/^[a-f0-9]{64}$/u.test(raw.contentHash))) {
    throw new Error(`rollback manifest entry ${index} has an invalid contentHash`);
  }
  const rawMode = raw.mode;
  if (
    rawMode !== undefined &&
    (typeof rawMode !== "number" || !Number.isInteger(rawMode) || rawMode < 0 || rawMode > 0o777)
  ) {
    throw new Error(`rollback manifest entry ${index} has an invalid mode`);
  }
  return {
    targetPath: raw.targetPath,
    ...(raw.backupPath === undefined ? {} : { backupPath: raw.backupPath }),
    ...(raw.createdByMigration === undefined ? {} : { createdByMigration: raw.createdByMigration }),
    ...(raw.contentHash === undefined ? {} : { contentHash: raw.contentHash }),
    ...(rawMode === undefined ? {} : { mode: rawMode }),
  };
}

function parseRollbackManifest(raw: unknown, manifestPath: string): RollbackManifest {
  if (!isPlainJsonObject(raw)) {
    throw new Error(`rollback manifest must be an object: ${manifestPath}`);
  }
  if (raw.version !== 1) {
    throw new Error(`rollback manifest has unsupported version: ${manifestPath}`);
  }
  if (typeof raw.createdAt !== "string") {
    throw new Error(`rollback manifest has an invalid createdAt: ${manifestPath}`);
  }
  if (!Array.isArray(raw.entries)) {
    throw new Error(`rollback manifest entries must be an array: ${manifestPath}`);
  }
  return {
    version: 1,
    createdAt: raw.createdAt,
    entries: raw.entries.map(parseRollbackManifestEntry),
  };
}

function isPathInside(parentPath: string, candidatePath: string): boolean {
  const relative = path.relative(path.resolve(parentPath), path.resolve(candidatePath));
  return relative === "" || (!relative.startsWith("..") && !path.isAbsolute(relative));
}

function isPathDescendant(parentPath: string, candidatePath: string): boolean {
  const relative = path.relative(path.resolve(parentPath), path.resolve(candidatePath));
  return relative !== "" && !relative.startsWith("..") && !path.isAbsolute(relative);
}

function hasConnectorConfigShape(targetPath: string, homeDir: string): boolean {
  const relative = path.relative(path.resolve(homeDir), path.resolve(targetPath));
  if (relative === ".claude.json" || relative === path.join(".claude", ".mcp.json")) {
    return true;
  }

  return hasRepoConnectorConfigShape(relative);
}

function hasRepoConnectorConfigShape(relativePath: string): boolean {
  const parts = relativePath.split(path.sep);
  const last = parts.at(-1);
  const packageName = parts.at(-2);
  const packagesDir = parts.at(-3);
  return last === ".mcp.json" &&
    packagesDir === "packages" &&
    (packageName === "plugin-claude-code" || packageName === "plugin-codex");
}

function connectorBackupPathForTarget(targetPath: string, homeDir: string): string {
  const digest = createHash("sha256").update(targetPath).digest("hex").slice(0, 12);
  return path.join(backupRoot(homeDir), "mcp", `${digest}.json`);
}

function isRollbackTargetAllowed(
  entry: RollbackManifestEntry,
  targetPath: string,
  homeDir: string,
  options?: MigrationOptions,
): boolean {
  const resolvedTarget = path.resolve(targetPath);
  if (isPathDescendant(remnicRoot(homeDir), resolvedTarget)) {
    if (entry.createdByMigration && !entry.backupPath) return true;
    return Boolean(entry.backupPath) && isRemnicTokenStorePath(resolvedTarget, homeDir);
  }
  if (isPathDescendant(path.join(homeDir, ".config", "remnic"), resolvedTarget)) {
    return entry.createdByMigration === true && !entry.backupPath;
  }

  const serviceTargets = new Set([
    path.resolve(path.join(homeDir, "Library", "LaunchAgents", "ai.remnic.daemon.plist")),
    path.resolve(path.join(homeDir, ".config", "systemd", "user", "remnic.service")),
  ]);
  if (serviceTargets.has(resolvedTarget)) return true;

  const cwd = resolveMigrationCwd(options);
  const allowedConnectorPaths = new Set(
    [
      ...defaultConnectorConfigPaths(homeDir, cwd),
      ...(options?.connectorConfigPaths ?? []),
    ].map((candidate) => resolveConnectorConfigPath(candidate, cwd)),
  );
  if (allowedConnectorPaths.has(resolvedTarget)) return true;

  return isPathInside(homeDir, resolvedTarget) && hasConnectorConfigShape(resolvedTarget, homeDir);
}

function isRollbackBackupAllowed(backupPath: string, homeDir: string): boolean {
  return isPathInside(backupRoot(homeDir), backupPath);
}

async function assertNoSymlinkPathSegments(filePath: string, trustedRoot: string, label: string): Promise<void> {
  const resolvedPath = path.resolve(filePath);
  const resolvedRoot = path.resolve(trustedRoot);
  if (!isPathInside(resolvedRoot, resolvedPath)) {
    throw new Error(`${label} is outside the trusted rollback root: ${filePath}`);
  }
  const segments = path.relative(resolvedRoot, resolvedPath).split(path.sep).filter(Boolean);
  let current = resolvedRoot;

  for (const [index, segment] of segments.entries()) {
    current = path.join(current, segment);
    try {
      const currentStat = await lstat(current);
      if (currentStat.isSymbolicLink()) {
        throw new Error(`${label} must not contain symlink segments: ${filePath}`);
      }
    } catch (error) {
      if ((error as NodeJS.ErrnoException).code === "ENOENT" && index === segments.length - 1) return;
      if ((error as NodeJS.ErrnoException).code === "ENOENT") {
        throw new Error(`${label} must not contain missing parent segments: ${filePath}`);
      }
      throw error;
    }
  }
}

function rollbackTargetSymlinkRoot(targetPath: string, homeDir: string, options?: MigrationOptions): string {
  if (isPathInside(homeDir, targetPath)) return homeDir;

  const cwd = resolveMigrationCwd(options);
  if (isPathInside(cwd, targetPath)) return cwd;

  return path.parse(targetPath).root;
}

async function validateRollbackManifestEntries(
  manifest: RollbackManifest,
  homeDir: string,
  options?: MigrationOptions,
): Promise<ValidatedRollbackManifestEntry[]> {
  const validated: ValidatedRollbackManifestEntry[] = [];

  for (const entry of manifest.entries) {
    const targetPath = path.resolve(entry.targetPath);
    if (!isRollbackTargetAllowed(entry, targetPath, homeDir, options)) {
      throw new Error(`rollback manifest target is outside migration-owned paths: ${entry.targetPath}`);
    }
    if (entry.backupPath && entry.createdByMigration) {
      throw new Error(`rollback manifest entry cannot restore and remove the same target: ${entry.targetPath}`);
    }
    const targetExists = await pathExistsNoFollow(targetPath);
    if (!entry.createdByMigration || targetExists) {
      const targetSymlinkRoot = rollbackTargetSymlinkRoot(targetPath, homeDir, options);
      await assertNoSymlinkPathSegments(targetPath, targetSymlinkRoot, "rollback manifest target");
    }
    if (entry.createdByMigration && targetExists) {
      await assertCreatedRollbackTargetMatchesRecord(entry, targetPath);
    }

    let backupPath: string | undefined;
    if (entry.backupPath) {
      backupPath = path.resolve(entry.backupPath);
      if (!isRollbackBackupAllowed(backupPath, homeDir)) {
        throw new Error(`rollback manifest backup is outside migration backup storage: ${entry.backupPath}`);
      }
      if (await pathExistsNoFollow(backupPath)) {
        await assertNoSymlinkPathSegments(backupPath, homeDir, "rollback manifest backup");
        await assertExistingRegularFileNoFollow(backupPath, "rollback manifest backup");
      }
      if (backupPath !== connectorBackupPathForTarget(targetPath, homeDir)) {
        throw new Error(`rollback manifest backup does not match target: ${entry.targetPath}`);
      }
    }

    validated.push({
      targetPath,
      ...(backupPath === undefined ? {} : { backupPath }),
      ...(entry.createdByMigration === undefined ? {} : { createdByMigration: entry.createdByMigration }),
      ...(entry.contentHash === undefined ? {} : { contentHash: entry.contentHash }),
      ...(entry.mode === undefined ? {} : { mode: entry.mode }),
    });
  }

  return validated;
}

async function assertCreatedRollbackTargetMatchesRecord(
  entry: RollbackManifestEntry,
  targetPath: string,
): Promise<boolean> {
  const targetStat = await lstat(targetPath);
  if (targetStat.isDirectory()) {
    throw new Error(`rollback manifest created target must be a file path: ${entry.targetPath}`);
  }
  if (!targetStat.isFile() || !entry.contentHash) return false;
  if (await fileContentHash(targetPath) !== entry.contentHash) {
    throw new Error(`rollback manifest created target content does not match migration record: ${entry.targetPath}`);
  }
  return true;
}

async function rewriteTokensIfPresent(filePath: string): Promise<number> {
  if (!existsSync(filePath)) return 0;
  await assertExistingRegularFileNoFollow(filePath, "Remnic token store");
  await secureTokenFilePermissions(filePath);
  let raw: Record<string, unknown>;
  try {
    raw = JSON.parse(await readFile(filePath, "utf8")) as Record<string, unknown>;
  } catch {
    return 0;
  }
  let rewritten = 0;

  if (Array.isArray(raw.tokens)) {
    for (const entry of raw.tokens as Array<Record<string, unknown>>) {
      if (typeof entry.token === "string") {
        const next = rewriteTokenValue(entry.token);
        if (next !== entry.token) {
          entry.token = next;
          rewritten += 1;
        }
      }
    }
  } else {
    for (const [key, value] of Object.entries(raw)) {
      if (typeof value === "string") {
        const next = rewriteTokenValue(value);
        if (next !== value) {
          raw[key] = next;
          rewritten += 1;
        }
      }
    }
  }

  if (rewritten > 0) {
    await writeTokenStoreFile(filePath, `${JSON.stringify(raw, null, 2)}\n`);
  }
  return rewritten;
}

async function mergeLegacyTokens(
  legacyTokensPath: string,
  remnicTokensPath: string,
  homeDir: string,
  manifest: RollbackManifest,
  backupExisting: boolean,
  persistManifest?: PersistRollbackManifest,
): Promise<number> {
  if (existsSync(legacyTokensPath)) {
    await assertExistingRegularFileNoFollow(legacyTokensPath, "legacy Engram token store");
  }
  if (!existsSync(remnicTokensPath)) return 0;
  await assertExistingRegularFileNoFollow(remnicTokensPath, "Remnic token store");
  await secureTokenFilePermissions(remnicTokensPath);
  if (!existsSync(legacyTokensPath)) return rewriteTokensIfPresent(remnicTokensPath);

  let remnicRaw: unknown;
  let legacyRaw: unknown;
  const originalRemnic = await readFile(remnicTokensPath, "utf8");

  try {
    remnicRaw = JSON.parse(originalRemnic) as unknown;
    legacyRaw = JSON.parse(await readFile(legacyTokensPath, "utf8")) as unknown;
  } catch {
    try {
      legacyRaw = JSON.parse(await readFile(legacyTokensPath, "utf8")) as unknown;
    } catch {
      return rewriteTokensIfPresent(remnicTokensPath);
    }

    const legacyEntries = parseTokenEntries(legacyRaw);
    let rewritten = 0;
    const recoveredEntries = legacyEntries.map((entry) => {
      const nextToken = rewriteTokenValue(entry.token);
      if (nextToken !== entry.token) rewritten += 1;
      return {
        ...entry,
        token: nextToken,
      };
    });

    if (backupExisting) {
      await backupFile(remnicTokensPath, originalRemnic, homeDir, manifest, persistManifest);
    }

    await writeTokenStoreFile(
      remnicTokensPath,
      `${JSON.stringify({ tokens: recoveredEntries }, null, 2)}\n`,
    );
    return rewritten;
  }

  const mergedEntries = parseTokenEntries(remnicRaw);
  const legacyEntries = parseTokenEntries(legacyRaw);
  const existingConnectors = new Set(mergedEntries.map((entry) => entry.connector));
  let rewritten = 0;
  let changed = false;

  for (const entry of mergedEntries) {
    const nextToken = rewriteTokenValue(entry.token);
    if (nextToken !== entry.token) {
      entry.token = nextToken;
      rewritten += 1;
      changed = true;
    }
  }

  for (const entry of legacyEntries) {
    const nextToken = rewriteTokenValue(entry.token);
    if (nextToken !== entry.token) {
      rewritten += 1;
    }
    if (existingConnectors.has(entry.connector)) continue;
    mergedEntries.push({ ...entry, token: nextToken });
    existingConnectors.add(entry.connector);
    changed = true;
  }

  if (!changed) return rewritten;

  if (backupExisting) {
    await backupFile(remnicTokensPath, originalRemnic, homeDir, manifest, persistManifest);
  }

  await writeTokenStoreFile(
    remnicTokensPath,
    `${JSON.stringify({ tokens: mergedEntries }, null, 2)}\n`,
  );
  return rewritten;
}

async function rewriteJsonFile(
  targetPath: string,
  homeDir: string,
  manifest: RollbackManifest,
  persistManifest?: PersistRollbackManifest,
): Promise<boolean> {
  if (!existsSync(targetPath)) return false;
  const targetStat = await lstat(targetPath);
  if (targetStat.isSymbolicLink()) return false;
  if (!targetStat.isFile()) {
    const error = new Error(`connector config must be a regular file: ${targetPath}`) as NodeJS.ErrnoException;
    error.code = targetStat.isDirectory() ? "EISDIR" : "EINVAL";
    throw error;
  }

  const original = await readFile(targetPath, "utf8");
  let parsed: unknown;
  try {
    parsed = JSON.parse(original) as unknown;
  } catch {
    return false;
  }
  if (!isPlainJsonObject(parsed)) return false;

  let changed = false;
  if (
    parsed.mcpServers &&
    typeof parsed.mcpServers === "object" &&
    !Array.isArray(parsed.mcpServers)
  ) {
    const servers = parsed.mcpServers as Record<string, unknown>;
    if (servers.engram && !servers.remnic) {
      servers.remnic = servers.engram;
      delete servers.engram;
      changed = true;
    }
  }

  const rewritten = rewriteRemnicText(JSON.stringify(parsed, null, 2));
  const next = `${rewritten}\n`;
  if (!changed && next === original) return false;

  await backupFile(targetPath, original, homeDir, manifest, persistManifest);
  await writeFile(targetPath, next, "utf8");
  return true;
}

async function backupFile(
  targetPath: string,
  originalContent: string,
  homeDir: string,
  manifest: RollbackManifest,
  persistManifest?: PersistRollbackManifest,
): Promise<void> {
  if (manifest.entries.some((entry) => entry.targetPath === targetPath && entry.backupPath)) {
    return;
  }
  const backupPath = connectorBackupPathForTarget(targetPath, homeDir);
  await ensureParent(backupPath);
  const originalMode = isRemnicTokenStorePath(targetPath, homeDir)
    ? TOKEN_STORE_MODE
    : (await stat(targetPath)).mode & 0o777;
  if (isRemnicTokenStorePath(targetPath, homeDir)) {
    await writeOwnerOnlyFile(backupPath, originalContent);
  } else {
    await writeFile(backupPath, originalContent, { encoding: "utf8", mode: originalMode });
    await chmod(backupPath, originalMode);
  }
  manifest.entries.push({ targetPath, backupPath, mode: originalMode });
  await persistManifest?.();
}

async function recordCreatedPath(
  filePath: string,
  manifest: RollbackManifest,
  persistManifest?: PersistRollbackManifest,
): Promise<void> {
  if (manifest.entries.some((entry) => entry.targetPath === filePath)) return;
  manifest.entries.push({
    targetPath: filePath,
    createdByMigration: true,
    contentHash: await fileContentHash(filePath),
  });
  await persistManifest?.();
}

async function refreshCreatedPathHash(
  filePath: string,
  manifest: RollbackManifest,
  persistManifest?: PersistRollbackManifest,
): Promise<void> {
  const entry = manifest.entries.find((candidate) =>
    candidate.targetPath === filePath && candidate.createdByMigration
  );
  if (!entry) return;
  entry.contentHash = await fileContentHash(filePath);
  await persistManifest?.();
}

function defaultConnectorConfigPaths(homeDir: string, cwd: string): string[] {
  return [
    path.join(homeDir, ".claude.json"),
    path.join(homeDir, ".claude", ".mcp.json"),
    path.join(cwd, "packages", "plugin-claude-code", ".mcp.json"),
    path.join(cwd, "packages", "plugin-codex", ".mcp.json"),
  ];
}

async function updateConnectorConfigs(
  homeDir: string,
  cwd: string,
  options: MigrationOptions | undefined,
  manifest: RollbackManifest,
  persistManifest?: PersistRollbackManifest,
): Promise<string[]> {
  const updated: string[] = [];
  const candidates = options?.connectorConfigPaths ?? defaultConnectorConfigPaths(homeDir, cwd);
  for (const targetPath of candidates) {
    const resolvedTarget = resolveConnectorConfigPath(targetPath, cwd);
    if (await rewriteJsonFile(resolvedTarget, homeDir, manifest, persistManifest)) {
      updated.push(resolvedTarget);
    }
  }
  return updated;
}

async function copyLegacyConfig(
  homeDir: string,
  copied: string[],
  manifest: RollbackManifest,
  persistManifest?: PersistRollbackManifest,
): Promise<void> {
  const source = legacyConfigPath(homeDir);
  const destination = remnicConfigPath(homeDir);
  if (!existsSync(source) || existsSync(destination)) return;
  if (!(await isExistingRegularFileNoFollow(source))) return;
  await ensureParent(destination);
  const original = await readFile(source, "utf8");
  let next = rewriteRemnicText(original);
  try {
    const parsed = JSON.parse(next) as unknown;
    if (isPlainJsonObject(parsed) && parsed.engram && !parsed.remnic) {
      parsed.remnic = parsed.engram;
      delete parsed.engram;
      next = JSON.stringify(parsed, null, 2);
    }
  } catch {
    // Keep rewritten text when config is not JSON.
  }
  await writeFile(destination, `${next.trimEnd()}\n`, "utf8");
  await recordCreatedPath(destination, manifest, persistManifest);
  copied.push(destination);
}

function rewriteServiceText(content: string): string {
  return rewriteRemnicText(content);
}

async function migrateServices(
  homeDir: string,
  options: MigrationOptions | undefined,
  manifest: RollbackManifest,
  persistManifest?: PersistRollbackManifest,
): Promise<string[]> {
  const logger = resolveLogger(options);
  const exec = resolveExec(options);
  const servicesReinstalled: string[] = [];
  const platform = resolvePlatform(options);

  if (platform === "darwin") {
    const legacyPlist = path.join(homeDir, "Library", "LaunchAgents", "ai.engram.daemon.plist");
    const remnicPlist = path.join(homeDir, "Library", "LaunchAgents", "ai.remnic.daemon.plist");
    if (existsSync(legacyPlist) && !existsSync(remnicPlist)) {
      if (!(await isExistingRegularFileNoFollow(legacyPlist))) return servicesReinstalled;
      const next = rewriteServiceText(await readFile(legacyPlist, "utf8"));
      await ensureParent(remnicPlist);
      await writeFile(remnicPlist, next, "utf8");
      await recordCreatedPath(remnicPlist, manifest, persistManifest);
      try {
        exec("launchctl", ["unload", legacyPlist]);
      } catch {
        // Keep migration fail-open when launchd rejects unload.
      }
      try {
        exec("launchctl", ["load", "-w", remnicPlist]);
      } catch {
        // Keep migration fail-open when launchd rejects load.
      }
      servicesReinstalled.push("ai.remnic.daemon");
      logger("launchd: ai.engram.daemon unloaded, ai.remnic.daemon installed");
    }
    return servicesReinstalled;
  }

  if (platform === "linux") {
    const legacyUnit = path.join(homeDir, ".config", "systemd", "user", "engram.service");
    const remnicUnit = path.join(homeDir, ".config", "systemd", "user", "remnic.service");
    if (existsSync(legacyUnit) && !existsSync(remnicUnit)) {
      if (!(await isExistingRegularFileNoFollow(legacyUnit))) return servicesReinstalled;
      const next = rewriteServiceText(await readFile(legacyUnit, "utf8"));
      await ensureParent(remnicUnit);
      await writeFile(remnicUnit, next, "utf8");
      await recordCreatedPath(remnicUnit, manifest, persistManifest);
      try {
        exec("systemctl", ["--user", "stop", "engram.service"]);
        exec("systemctl", ["--user", "disable", "engram.service"]);
        exec("systemctl", ["--user", "daemon-reload"]);
        exec("systemctl", ["--user", "enable", "remnic.service"]);
        exec("systemctl", ["--user", "start", "remnic.service"]);
      } catch {
        // Keep migration fail-open when systemd is unavailable.
      }
      servicesReinstalled.push("remnic.service");
      logger("systemd: engram.service disabled, remnic.service installed");
    }
  }

  return servicesReinstalled;
}

async function writeRollbackManifest(homeDir: string, manifest: RollbackManifest): Promise<void> {
  await ensureParent(rollbackManifestPath(homeDir));
  await writeFile(
    rollbackManifestPath(homeDir),
    `${JSON.stringify(manifest, null, 2)}\n`,
    "utf8",
  );
}

async function readRollbackManifest(homeDir: string): Promise<RollbackManifest | null> {
  const target = rollbackManifestPath(homeDir);
  let targetStat: Awaited<ReturnType<typeof lstat>>;
  try {
    targetStat = await lstat(target);
  } catch (error) {
    if ((error as NodeJS.ErrnoException).code === "ENOENT") return null;
    throw error;
  }
  if (targetStat.isSymbolicLink()) {
    throw new Error(`rollback manifest must not be a symlink: ${target}`);
  }
  if (!targetStat.isFile()) {
    throw new Error(`rollback manifest must be a regular file: ${target}`);
  }
  let parsed: unknown;
  try {
    parsed = JSON.parse(await readFile(target, "utf8")) as unknown;
  } catch {
    return null;
  }
  return parseRollbackManifest(parsed, target);
}

async function acquireLock(homeDir: string): Promise<() => Promise<void>> {
  const target = lockPath(homeDir);
  await mkdir(remnicRoot(homeDir), { recursive: true });
  const started = Date.now();

  while (true) {
    try {
      const handle = await open(target, "wx");
      await handle.writeFile(`${process.pid}\n${Date.now()}\n`, "utf8");
      return async () => {
        try {
          await handle.close();
        } finally {
          await unlink(target).catch(() => undefined);
        }
      };
    } catch (error) {
      const code = (error as NodeJS.ErrnoException).code;
      if (code !== "EEXIST") throw error;

      const details = await readFile(target, "utf8").catch(() => null);
      if (details === null) {
        if (await removeLock(target)) continue;
      } else {
        const lines = details.split("\n");
        const pid = Number.parseInt(lines[0] ?? "", 10);
        const createdAt = Number.parseInt(lines[1] ?? "", 10);
        const malformed = !Number.isSafeInteger(pid) || pid <= 0 || !Number.isFinite(createdAt);
        const deadPid = !malformed && !processIsAlive(pid);
        if (malformed || deadPid) {
          if (await removeLockIfUnchanged(target, details)) continue;
        }
      }
      if (Date.now() - started > LOCK_TIMEOUT_MS) {
        throw new Error(`timed out waiting for migration lock: ${target}`);
      }
      await new Promise((resolve) => setTimeout(resolve, LOCK_RETRY_MS));
    }
  }
}

async function removeLockIfUnchanged(target: string, expectedContent: string): Promise<boolean> {
  const current = await readFile(target, "utf8").catch(() => null);
  if (current !== expectedContent) return false;
  return removeLock(target);
}

async function removeLock(target: string): Promise<boolean> {
  try {
    await rm(target, { force: true });
    return true;
  } catch {
    return false;
  }
}

function processIsAlive(pid: number): boolean {
  try {
    process.kill(pid, 0);
    return true;
  } catch (error) {
    if ((error as NodeJS.ErrnoException).code === "EPERM") return true;
    return false;
  }
}

export async function rollbackFromEngramMigration(options?: MigrationOptions): Promise<RollbackResult> {
  const homeDir = resolveMigrationHome(options);
  const manifest = await readRollbackManifest(homeDir);
  const exec = resolveExec(options);
  const platform = resolvePlatform(options);
  const restored: string[] = [];
  const removed: string[] = [];

  if (!manifest) return { restored, removed };
  const entries = await validateRollbackManifestEntries(manifest, homeDir, options);

  if (platform === "darwin") {
    const remnicPlist = path.join(homeDir, "Library", "LaunchAgents", "ai.remnic.daemon.plist");
    if (existsSync(remnicPlist)) {
      try {
        exec("launchctl", ["unload", remnicPlist]);
      } catch {
        // Ignore launchctl rollback failures.
      }
    }
  } else if (platform === "linux") {
    try {
      exec("systemctl", ["--user", "stop", "remnic.service"]);
      exec("systemctl", ["--user", "disable", "remnic.service"]);
    } catch {
      // Ignore systemd rollback failures.
    }
  }

  for (const entry of [...entries].reverse()) {
    if (entry.backupPath && await pathExistsNoFollow(entry.backupPath)) {
      await assertNoSymlinkPathSegments(entry.backupPath, homeDir, "rollback manifest backup");
      await assertExistingRegularFileNoFollow(entry.backupPath, "rollback manifest backup");
      await ensureParent(entry.targetPath);
      await copyFile(entry.backupPath, entry.targetPath);
      const restoreMode = isRemnicTokenStorePath(entry.targetPath, homeDir)
        ? TOKEN_STORE_MODE
        : entry.mode ?? ((await lstat(entry.backupPath)).mode & 0o777);
      await chmod(entry.targetPath, restoreMode);
      restored.push(entry.targetPath);
      continue;
    }
    if (entry.createdByMigration && existsSync(entry.targetPath)) {
      const targetSymlinkRoot = rollbackTargetSymlinkRoot(entry.targetPath, homeDir, options);
      await assertNoSymlinkPathSegments(entry.targetPath, targetSymlinkRoot, "rollback manifest target");
      if (!await assertCreatedRollbackTargetMatchesRecord(entry, entry.targetPath)) continue;
      await rm(entry.targetPath, { recursive: true, force: true });
      removed.push(entry.targetPath);
    }
  }

  if (platform === "linux") {
    try {
      exec("systemctl", ["--user", "daemon-reload"]);
    } catch {
      // Ignore systemd rollback failures after removing unit files.
    }
  }

  await rm(markerPath(homeDir), { force: true }).catch(() => undefined);
  await rm(rollbackManifestPath(homeDir), { force: true }).catch(() => undefined);
  return { restored, removed };
}

export async function migrateFromEngram(options?: MigrationOptions): Promise<MigrationResult> {
  const homeDir = resolveMigrationHome(options);
  const cwd = resolveMigrationCwd(options);
  const logger = resolveLogger(options);
  const copied: string[] = [];
  let tokensRegenerated = 0;
  let servicesReinstalled: string[] = [];

  if (existsSync(markerPath(homeDir))) {
    return {
      status: "already-migrated",
      copied,
      tokensRegenerated,
      servicesReinstalled,
      rollbackCommand: defaultRollbackCommand(),
    };
  }

  const hasLegacyRoot = existsSync(legacyRoot(homeDir));
  const hasLegacyConfig = existsSync(legacyConfigPath(homeDir));
  if (!hasLegacyRoot && !hasLegacyConfig) {
    return {
      status: "fresh-install",
      copied,
      tokensRegenerated,
      servicesReinstalled,
      rollbackCommand: defaultRollbackCommand(),
    };
  }

  const releaseLock = await acquireLock(homeDir);
  try {
    if (existsSync(markerPath(homeDir))) {
      return {
        status: "already-migrated",
        copied,
        tokensRegenerated,
        servicesReinstalled,
        rollbackCommand: defaultRollbackCommand(),
      };
    }

    const manifest: RollbackManifest = await readRollbackManifest(homeDir) ?? {
      version: 1,
      createdAt: new Date().toISOString(),
      entries: [],
    };
    const persistManifest = () => writeRollbackManifest(homeDir, manifest);

    logger("First run after Engram -> Remnic rename. Migrating...");
    await mkdir(remnicRoot(homeDir), { recursive: true });
    await persistManifest();
    await copyTreeMissing(legacyRoot(homeDir), remnicRoot(homeDir), copied, manifest, persistManifest);
    await copyLegacyConfig(homeDir, copied, manifest, persistManifest);

    const legacyTokens = path.join(legacyRoot(homeDir), "tokens.json");
    const remnicTokens = path.join(remnicRoot(homeDir), "tokens.json");
    if (copied.includes(remnicTokens)) {
      tokensRegenerated += await rewriteTokensIfPresent(remnicTokens);
      await refreshCreatedPathHash(remnicTokens, manifest, persistManifest);
    } else {
      tokensRegenerated += await mergeLegacyTokens(
        legacyTokens,
        remnicTokens,
        homeDir,
        manifest,
        true,
        persistManifest,
      );
    }
    if (existsSync(remnicTokens)) {
      logger("tokens copied to ~/.remnic/tokens.json (legacy prefixes rewritten)");
    }

    const updatedConfigs = await updateConnectorConfigs(homeDir, cwd, options, manifest, persistManifest);
    for (const updated of updatedConfigs) {
      logger(`Updated connector config: ${updated}`);
    }

    servicesReinstalled = await migrateServices(homeDir, options, manifest, persistManifest);
    await writeRollbackManifest(homeDir, manifest);
    await writeFile(markerPath(homeDir), `${new Date().toISOString()}\n`, "utf8");
    logger("Migration complete. Welcome to Remnic.");

    return {
      status: "migrated",
      copied,
      tokensRegenerated,
      servicesReinstalled,
      rollbackCommand: defaultRollbackCommand(),
    };
  } finally {
    await releaseLock();
  }
}

import path from "node:path";
import { resolveIndexingCapabilities, resolveMemoryLifecycleCapabilities } from "../capabilities.js";
import type { EmbeddingFallback } from "../embedding-fallback.js";
import type { CorpusReadOptions } from "../corpus-read-cancellation.js";
import type { StorageManager } from "../index.js";
import type { NamespaceStorageRouter } from "../namespaces/storage.js";
import {
  computeArtifactCandidateFetchLimit,
  throwIfRecallAborted,
  type QueryAwarePrefilter,
} from "../orchestrator.js";
import {
  extractTagsFromPrompt,
  isTemporalQuery,
  queryByDateRangeAsync,
  readIndexSnapshotAsync,
  recencyWindowFromPrompt,
  resolvePromptTagPrefilterAsync,
} from "../temporal-index.js";
import type { MemoryFile, PluginConfig, QmdSearchResult } from "../types.js";
import { isGenericRecallExcludedPath } from "./generic-recall-paths.js";

export interface PrefilterAndArtifactDeps {
  readonly config: PluginConfig;
  readonly storageRouter: NamespaceStorageRouter;
  readonly storage: StorageManager;
  readonly embeddingFallback: EmbeddingFallback;
  resolveArtifactSourceStatuses(
    storage: StorageManager,
    sourceIds: string[],
    options?: CorpusReadOptions,
  ): Promise<Map<string, "active" | "superseded" | "archived" | "missing">>;
  scopeQueryAwarePaths(
    paths: Set<string> | null,
    recallNamespaces: string[],
  ): Set<string> | null;
  searchScopedMemoryCandidates(
    candidatePaths: Set<string>,
    query: string,
    limit: number,
    options?: {
      allowArchived?: boolean;
    },
  ): Promise<QmdSearchResult[]>;
}

/**
 * Cancellation for the artifact recall path (issue #2291).  Artifact recall
 * re-scans and re-tokenizes every stored artifact, up to `MAX_ATTEMPTS` times
 * with a growing fetch limit; on a large or slow memory tree that is minutes of
 * work that used to keep running after the caller had already given up.
 */
export interface ArtifactRecallOptions {
  abortSignal?: AbortSignal;
}

export async function fetchActiveArtifactsForNamespace(
  deps: Pick<PrefilterAndArtifactDeps, "storageRouter" | "resolveArtifactSourceStatuses">,
  namespace: string,
  prompt: string,
  targetCount: number,
  options: ArtifactRecallOptions = {},
): Promise<MemoryFile[]> {
  const storage = await deps.storageRouter.storageFor(namespace);
  let fetchLimit = computeArtifactCandidateFetchLimit(targetCount);
  const maxFetchLimit = Math.min(800, Math.max(fetchLimit, targetCount * 8));
  const MAX_ATTEMPTS = 4;
  let bestFiltered: MemoryFile[] = [];

  for (let attempt = 0; attempt < MAX_ATTEMPTS; attempt += 1) {
    throwIfRecallAborted(options.abortSignal);
    const rawResults = await storage.searchArtifacts(prompt, fetchLimit, {
      abortSignal: options.abortSignal,
    });
    const sourceIds = Array.from(
      new Set(
        rawResults
          .map((a) => a.frontmatter.sourceMemoryId)
          .filter(
            (id): id is string => typeof id === "string" && id.length > 0,
          ),
      ),
    );
    // The status snapshot rebuild reads every memory in the namespace; do not
    // start one for a recall that has already been abandoned.
    throwIfRecallAborted(options.abortSignal);
    const sourceStatus =
      sourceIds.length > 0
        ? await deps.resolveArtifactSourceStatuses(storage, sourceIds, {
            abortSignal: options.abortSignal,
          })
        : new Map<string, "active" | "superseded" | "archived" | "missing">();

    const filtered: MemoryFile[] = [];
    for (const artifact of rawResults) {
      const sourceId = artifact.frontmatter.sourceMemoryId;
      if (!sourceId) {
        filtered.push(artifact);
        if (filtered.length >= targetCount) break;
        continue;
      }
      const status = sourceStatus.get(sourceId) ?? "missing";
      if (status !== "active") continue;
      filtered.push(artifact);
      if (filtered.length >= targetCount) break;
    }

    if (filtered.length >= targetCount) return filtered.slice(0, targetCount);
    if (filtered.length > bestFiltered.length) {
      bestFiltered = filtered;
    }
    if (rawResults.length === 0) return filtered;
    if (rawResults.length < fetchLimit && filtered.length > 0)
      return filtered;
    if (fetchLimit >= maxFetchLimit) return filtered;

    const growth = Math.max(targetCount * 2, 12);
    fetchLimit = Math.min(maxFetchLimit, fetchLimit + growth);
  }

  return bestFiltered;
}

export async function buildQueryAwarePrefilter(
  deps: Pick<PrefilterAndArtifactDeps, "config" | "scopeQueryAwarePaths">,
  prompt: string,
  recallNamespaces: string[],
): Promise<QueryAwarePrefilter> {
  if (!resolveIndexingCapabilities(deps.config).queryAwareIndexing || !prompt.trim()) {
    return {
      candidatePaths: null,
      temporalFromDate: null,
      matchedTags: [],
      expandedTags: [],
      combination: "none",
      filteredToFullSearch: false,
    };
  }

  const temporalFromDate = isTemporalQuery(prompt)
    ? recencyWindowFromPrompt(prompt, Date.now())
    : null;
  // Read the temporal + tag prefilter indexes as ONE consistent snapshot
  // (issue #1911, Codex Medium) so a concurrent async index mutation can't be
  // observed half-applied (new temporal row, tag membership not yet written),
  // which would drop the current memory from the tag prefilter.
  const [rawTemporal, tagSignals] = await readIndexSnapshotAsync(
    deps.config.memoryDir,
    () =>
      Promise.all([
        temporalFromDate
          ? queryByDateRangeAsync(deps.config.memoryDir, temporalFromDate)
          : Promise.resolve<Set<string> | null>(null),
        resolvePromptTagPrefilterAsync(deps.config.memoryDir, prompt).catch(
          () => ({
            matchedTags: extractTagsFromPrompt(prompt),
            expandedTags: extractTagsFromPrompt(prompt),
            paths: null,
          }),
        ),
      ]),
  );

  const temporalCandidates = deps.scopeQueryAwarePaths(
    rawTemporal,
    recallNamespaces,
  );
  const tagCandidates = deps.scopeQueryAwarePaths(
    tagSignals.paths,
    recallNamespaces,
  );
  const maxCandidates = deps.config.queryAwareIndexingMaxCandidates;

  let candidatePaths: Set<string> | null = null;
  let combination: QueryAwarePrefilter["combination"] = "none";
  let filteredToFullSearch = false;

  if (
    tagSignals.matchedTags.length > 0 &&
    tagCandidates !== null &&
    tagCandidates.size === 0
  ) {
    candidatePaths = tagCandidates;
    combination = "tag";
  } else if (temporalCandidates !== null && tagCandidates !== null) {
    const intersection = new Set(
      Array.from(temporalCandidates).filter((memoryPath) =>
        tagCandidates.has(memoryPath),
      ),
    );
    if (intersection.size > 0) {
      candidatePaths = intersection;
      combination = "intersection";
    } else {
      candidatePaths = new Set([...temporalCandidates, ...tagCandidates]);
      combination = "union";
    }
  } else if (temporalCandidates !== null) {
    candidatePaths = temporalCandidates;
    combination = "temporal";
  } else if (tagCandidates !== null) {
    candidatePaths = tagCandidates;
    combination = "tag";
  }

  if (
    candidatePaths &&
    maxCandidates > 0 &&
    candidatePaths.size > maxCandidates
  ) {
    filteredToFullSearch = true;
    candidatePaths = null;
  }

  return {
    candidatePaths,
    temporalFromDate,
    matchedTags: tagSignals.matchedTags,
    expandedTags: tagSignals.expandedTags,
    combination,
    filteredToFullSearch,
  };
}

export async function searchEmbeddingFallback(
  deps: Pick<PrefilterAndArtifactDeps, "config" | "embeddingFallback" | "storage">,
  query: string,
  limit: number,
): Promise<QmdSearchResult[]> {
  if (!resolveMemoryLifecycleCapabilities(deps.config).embeddingFallback) return [];
  if (!(await deps.embeddingFallback.isAvailable())) return [];
  const hits = await deps.embeddingFallback.search(query, limit);
  if (hits.length === 0) return [];

  const results: QmdSearchResult[] = [];
  for (const hit of hits) {
    const fullPath = path.isAbsolute(hit.path)
      ? hit.path
      : path.join(deps.config.memoryDir, hit.path);
    const memory = await deps.storage.readMemoryByPath(fullPath);
    if (!memory) continue;
    results.push({
      docid: hit.id,
      path: fullPath,
      score: hit.score,
      snippet: memory.content.slice(0, 400).replace(/\n/g, " "),
      origin: memory.frontmatter.origin,
    });
  }
  return results;
}

export async function searchQueryAwareFallback(
  deps: Pick<PrefilterAndArtifactDeps, "config" | "searchScopedMemoryCandidates">,
  prompt: string,
  limit: number,
  queryAwarePrefilter?: QueryAwarePrefilter,
  abortSignal?: AbortSignal,
): Promise<QmdSearchResult[]> {
  throwIfRecallAborted(abortSignal);
  const cappedLimit = Math.max(0, limit);
  if (cappedLimit === 0 || queryAwarePrefilter?.candidatePaths?.size === 0) return [];

  const candidatePaths = queryAwarePrefilter?.candidatePaths;
  const scopedSeedResults = (
    candidatePaths?.size
      ? await deps.searchScopedMemoryCandidates(
          candidatePaths,
          prompt,
          candidatePaths.size,
          { allowArchived: true },
        )
      : []
  ).filter((result) => !isGenericRecallExcludedPath(result.path, deps.config, "qmd"));
  return scopedSeedResults.slice(0, cappedLimit);
}

/**
 * Direct-answer wiring (issue #518 slice 3).
 *
 * Binds the pure eligibility decision (`direct-answer.ts`) to the data
 * sources needed to build candidates: storage, trust-zones, taxonomy,
 * and importance scoring.  Kept as a separate module so that:
 *
 * - The eligibility layer stays pure and unit-testable without stores.
 * - Each caller injects its own source accessors.  The orchestrator
 *   binding is a follow-on slice; tests here use mock sources.
 * - The wiring is safe to ship alone — nothing calls `tryDirectAnswer`
 *   yet, so enabling this module's presence does not change recall
 *   behavior.  The next slice adds exactly one call site before QMD.
 *
 * Short-circuit contract:
 *
 * - When the resolved gate (`input.enabled`, projected from
 *   `caps.recallDirectAnswer` at the recall-operation entry) is `false`, the
 *   function returns the
 *   eligibility verdict with reason `"disabled"` without touching any source
 *   accessor.  This is the documented default.
 * - When enabled, the wiring cheaply drops non-trusted-zone memories
 *   and ineligible taxonomy buckets before computing importance, so
 *   the eligibility module sees a pre-filtered candidate set.  The
 *   eligibility module still performs the same checks itself — this
 *   module is purely an I/O and prefiltering layer.
 */

import type { MemoryFile, PluginConfig } from "./types.js";
import type { TrustZoneName } from "./trust-zones.js";
import type { Taxonomy } from "./taxonomy/types.js";
import { resolveCategory } from "./taxonomy/resolver.js";
import { normalizeRecallTokens } from "./recall-tokenization.js";
import { throwIfAborted } from "./abort-error.js";
import {
  isDirectAnswerEligible,
  type DirectAnswerCandidate,
  type DirectAnswerConfig,
  type DirectAnswerResult,
} from "./direct-answer.js";

/**
 * Caller-provided accessors for candidate sourcing.  Decouples the
 * wiring from any specific storage / trust-zone / importance backend.
 */
export interface DirectAnswerSources {
  /**
   * List memories eligible to be considered for direct-answer.
   * Callers are expected to return only active, non-superseded memories
   * in the requested namespace; the wiring will cheaply re-filter on
   * trust zone and taxonomy bucket and hand the rest to the eligibility
   * module, which applies the full gate ladder.
   */
  listCandidateMemories(options: {
    namespace: string;
    abortSignal?: AbortSignal;
  }): Promise<MemoryFile[]>;
  /**
   * Resolve the trust-zone record for a memory.  Returns `null` when
   * the memory has no trust-zone record (treated as not trusted).
   */
  trustZoneFor(memoryId: string): Promise<TrustZoneName | null>;
  /**
   * Resolve a calibrated importance score in [0, 1] for a memory.
   */
  importanceFor(memory: MemoryFile): number;
  /**
   * Taxonomy used to classify memories into direct-answer buckets.
   */
  taxonomy: Taxonomy;
}

export interface DirectAnswerWiringInput {
  query: string;
  namespace: string;
  config: Pick<
    PluginConfig,
    | "recallDirectAnswerTokenOverlapFloor"
    | "recallDirectAnswerImportanceFloor"
    | "recallDirectAnswerAmbiguityMargin"
    | "recallDirectAnswerEligibleTaxonomyBuckets"
  >;
  /**
   * Direct-answer capability gate, resolved once at the recall-operation entry
   * via `resolveCapabilities(config).recallDirectAnswer` (issue #1523). This
   * is the sole gate — the function no longer reads the config flag directly.
   * Callers MUST pass the resolved capability so the whole operation agrees on
   * a single gate value.
   */
  enabled: boolean;
  sources: DirectAnswerSources;
  queryEntityRefs?: string[];
  abortSignal?: AbortSignal;
}

/**
 * Attempt direct-answer resolution.  Returns the eligibility verdict
 * produced by `isDirectAnswerEligible` with candidates materialized
 * from the caller-supplied sources.
 */
export async function tryDirectAnswer(
  input: DirectAnswerWiringInput,
): Promise<DirectAnswerResult> {
  const { query, namespace, config, enabled, sources, queryEntityRefs, abortSignal } = input;

  const eligibilityConfig: DirectAnswerConfig = {
    enabled,
    tokenOverlapFloor: config.recallDirectAnswerTokenOverlapFloor,
    importanceFloor: config.recallDirectAnswerImportanceFloor,
    ambiguityMargin: config.recallDirectAnswerAmbiguityMargin,
    eligibleTaxonomyBuckets: config.recallDirectAnswerEligibleTaxonomyBuckets,
  };

  // Short-circuit disabled case before touching any I/O.
  if (!eligibilityConfig.enabled) {
    return isDirectAnswerEligible({
      query,
      candidates: [],
      config: eligibilityConfig,
      queryEntityRefs,
    });
  }

  // Short-circuit empty-query case before any I/O.  isDirectAnswerEligible
  // deterministically returns reason "empty-query" when the query
  // normalizes to zero searchable tokens; there's no point materializing
  // candidates just to reach the same verdict, and doing so would
  // surface avoidable upstream errors for requests that should exit
  // immediately.
  if (normalizeRecallTokens(query).length === 0) {
    return isDirectAnswerEligible({
      query,
      candidates: [],
      config: eligibilityConfig,
      queryEntityRefs,
    });
  }

  throwIfAborted(abortSignal, "direct-answer wiring aborted");
  const memories = await sources.listCandidateMemories({ namespace, abortSignal });
  throwIfAborted(abortSignal, "direct-answer wiring aborted");
  const candidates: DirectAnswerCandidate[] = [];

  for (const memory of memories) {
    // Throw rather than returning a partial verdict — a mid-loop abort
    // that left competing candidates unprocessed could otherwise surface
    // a spurious "eligible" result that the ambiguity gate never got a
    // chance to reject.  The check repeats after every await so an
    // abort that lands during the in-flight I/O on the final memory
    // (after which no further iteration would exist) still stops us.
    throwIfAborted(abortSignal, "direct-answer wiring aborted");

    const trustZone = await sources.trustZoneFor(memory.frontmatter.id);
    throwIfAborted(abortSignal, "direct-answer wiring aborted");

    // Cheap pre-filter: non-trusted memories can't qualify, so skip
    // taxonomy and importance resolution for them.
    if (trustZone !== "trusted") continue;

    const decision = resolveCategory(
      memory.content,
      memory.frontmatter.category,
      sources.taxonomy,
    );
    const taxonomyBucket = decision.categoryId;
    if (!eligibilityConfig.eligibleTaxonomyBuckets.includes(taxonomyBucket)) continue;

    const importanceScore = sources.importanceFor(memory);

    candidates.push({
      memory,
      trustZone,
      taxonomyBucket,
      importanceScore,
    });
  }

  // Final check — if abort landed during the trust-zone await for the
  // last memory, the loop condition no longer fires.  Guard before we
  // hand candidates to the eligibility gate.
  throwIfAborted(abortSignal, "direct-answer wiring aborted");

  return isDirectAnswerEligible({
    query,
    candidates,
    config: eligibilityConfig,
    queryEntityRefs,
  });
}

/**
 * Recall inject seam for state views (issue #1952).
 *
 * Widening lives in recall-state-view-widen.ts. parseConfig cannot grow.
 * Operators set `recallStateViews` on the live PluginConfig extra field.
 * Default false is identity.
 */

import { widenRecallStateViews } from "./recall-state-view-widen.js";
import type { StateViewResult } from "./recall-state-view.js";

export function applyRecallStateViews<T extends StateViewResult>(
  results: T[],
  query: string,
  config: unknown,
  stateViewActive?: boolean,
  asOfMs?: number,
): T[] {
  return widenRecallStateViews(results, query, config, [], stateViewActive, asOfMs);
}

