  baseMemoryDir?: string;
  candidateMemoryDir?: string;
  baseEvalStoreDir?: string;
  candidateEvalStoreDir?: string;
}): Promise<EvalCiGateReport> {
  const baseRootDir = resolveRequiredEvalStoreRoot(
