  }
  if (candidateSnapshot.status.invalidShadows.length > 0) {
    regressions.push(`candidate store has ${candidateSnapshot.status.invalidShadows.length} invalid shadow record(s)`);
  }

  const baseRuns = latestCompletedRunsByBenchmark(baseSnapshot.runs);
  const candidateRuns = latestCompletedRunsByBenchmark(candidateSnapshot.runs);
  const missingCandidateBenchmarks = [...baseRuns.keys()]
    .filter((benchmarkId) => !candidateRuns.has(benchmarkId))
    .sort();
  for (const benchmarkId of missingCandidateBenchmarks) {
    regressions.push(`candidate is missing latest completed benchmark run for ${benchmarkId}`);
  }

  const deltas: EvalBenchmarkDelta[] = [];
  for (const benchmarkId of [...baseRuns.keys()].sort()) {
    const baseRun = baseRuns.get(benchmarkId);
    const candidateRun = candidateRuns.get(benchmarkId);
    if (!baseRun || !candidateRun) continue;

    const basePassRate = computePassRate(baseRun);
    const candidatePassRate = computePassRate(candidateRun);
    const passRateDelta = candidatePassRate - basePassRate;
    const delta: EvalBenchmarkDelta = {
      benchmarkId,
      baseRunId: baseRun.runId,
      candidateRunId: candidateRun.runId,
      basePassRate,
      candidatePassRate,
      passRateDelta,
      metricDeltas: {},
      regressions: [],
      improvements: [],
    };

    if (passRateDelta < 0) {
      delta.regressions.push(`passRate ${basePassRate} -> ${candidatePassRate}`);
      regressions.push(`${benchmarkId} pass rate regressed (${basePassRate} -> ${candidatePassRate})`);
    } else if (passRateDelta > 0) {
      delta.improvements.push(`passRate ${basePassRate} -> ${candidatePassRate}`);
      improvements.push(`${benchmarkId} pass rate improved (${basePassRate} -> ${candidatePassRate})`);
    }

    const metricDelta = compareMetricDeltas(baseRun.metrics, candidateRun.metrics);
    delta.metricDeltas = metricDelta.deltas;
    for (const regression of metricDelta.regressions) {
      delta.regressions.push(regression);
      regressions.push(`${benchmarkId} ${regression}`);
    }
    for (const improvement of metricDelta.improvements) {
      delta.improvements.push(improvement);
      improvements.push(`${benchmarkId} ${improvement}`);
    }
    deltas.push(delta);
  }

  return {
    passed: regressions.length === 0,
    baseRootDir: baseSnapshot.status.rootDir,
    candidateRootDir: candidateSnapshot.status.rootDir,
    comparedBenchmarks: deltas.length,
    missingCandidateBenchmarks,
    invalidArtifacts: {
      base: {
        benchmarks: baseSnapshot.status.invalidBenchmarks.length,
        runs: baseSnapshot.status.invalidRuns.length,
        shadows: baseSnapshot.status.invalidShadows.length,
      },
      candidate: {
        benchmarks: candidateSnapshot.status.invalidBenchmarks.length,
        runs: candidateSnapshot.status.invalidRuns.length,
        shadows: candidateSnapshot.status.invalidShadows.length,
      },
    },
    regressions,
    improvements,
    deltas,
  };
}

import {
  DEFAULT_UNTRUSTED_ORIGINS,
  isUntrustedOrigin,
  parseOriginClass,
} from "./security/origin-authority.js";
import type { PluginConfig } from "./types.js";
import {
  buildStandingMemoryBlock,
  lintStandingBlockVolatility,
  type StandingMemoryEntry,
} from "./standing-memory-block.js";

export interface StandingMemorySource {
  id?: string;
  path?: string;
  content: string;
  frontmatter: {
    id?: unknown;
    pinned?: unknown;
    updated?: unknown;
    origin?: unknown;
    status?: unknown;
    toolScoped?: unknown;
    sourceConnector?: unknown;
  };
}

export function memoriesToStandingEntries(
  memories: readonly StandingMemorySource[],
  opts: { requestingConnector?: string } = {},
): StandingMemoryEntry[] {
  const entries: StandingMemoryEntry[] = [];
  for (const memory of memories) {
    const id = String(memory.frontmatter.id ?? memory.id ?? memory.path ?? "");
    if (!id) continue;
    if (isUntrustedOrigin(parseOriginClass(memory.frontmatter.origin), DEFAULT_UNTRUSTED_ORIGINS)) {
      continue;
    }
    if (typeof memory.frontmatter.status === "string" && memory.frontmatter.status !== "active") {
      continue;
    }
    const requestingConnector = opts.requestingConnector?.trim();
    const memoryConnector =
      typeof memory.frontmatter.sourceConnector === "string" ? memory.frontmatter.sourceConnector.trim() : "";
    if (memory.frontmatter.toolScoped === true && memoryConnector && requestingConnector && memoryConnector !== requestingConnector) {
      continue;
    }
    const description =
      memory.content
        .split("\n")
        .map((line) => line.trim())
        .find((line) => line.length > 0 && !line.startsWith("#") && !line.startsWith("---")) ?? "";
    if (description.length < 8) continue;
    if (lintStandingBlockVolatility(description).length > 0) continue;
    const pinned = memory.frontmatter.pinned === true;
    const lastChangedAt =
      typeof memory.frontmatter.updated === "string" ? memory.frontmatter.updated : undefined;
    entries.push({ id, description: description.slice(0, 200), pinned, lastChangedAt });
  }
  return entries;
}

export function renderStandingMemoryBlock(config: PluginConfig, entries: StandingMemoryEntry[]): string {
  if (!config.recallStandingBlock || entries.length === 0) return "";
  try {
    return buildStandingMemoryBlock({
      entries,
      nowMs: Date.now(),
      maxChars: config.standingBlockMaxChars,
      freshDays: config.standingBlockFreshDays,
    }).text;
  } catch {
    return "";
  }
}

export function prefixStandingMemoryBlock(
  recallResult: string,
  standingText: string,
  budgetChars?: number,
): string {
  if (standingText.length === 0) return recallResult;
  if (budgetChars === 0) return recallResult;
  const combined = `${standingText}\n\n${recallResult}`;
  if (!budgetChars || combined.length <= budgetChars) return combined;
  return combined.slice(0, budgetChars);
}

