import type {
  MemoryActionEligibilityContext,
  MemoryActionPolicyResult,
  MemoryActionType,
} from "./types.js";

export interface MemoryActionPolicyOptions {
  actionsEnabled: boolean;
  maxCompressionTokensPerHour: number;
}

const HIGH_IMPORTANCE_DISCARD_THRESHOLD = 0.8;
const LOW_CONFIDENCE_DEFER_THRESHOLD = 0.35;

export function evaluateMemoryActionPolicy(input: {
  action: MemoryActionType;
  eligibility: MemoryActionEligibilityContext;
  options: MemoryActionPolicyOptions;
}): MemoryActionPolicyResult {
  const { action, eligibility, options } = input;

  if (!options.actionsEnabled) {
    return {
      action,
      decision: "deny",
      rationale: "contextCompressionActionsEnabled=false",
      eligibility,
    };
  }

  if (options.maxCompressionTokensPerHour === 0 && action === "summarize_node") {
    return {
      action,
      decision: "defer",
      rationale: "maxCompressionTokensPerHour=0",
      eligibility,
    };
  }

  if (action === "discard" && eligibility.importance >= HIGH_IMPORTANCE_DISCARD_THRESHOLD) {
    return {
      action,
      decision: "deny",
      rationale: "importance_too_high_for_discard",
      eligibility,
    };
  }

  if (
    (eligibility.lifecycleState === "archived" || eligibility.lifecycleState === "stale") &&
    (action === "update_note" || action === "create_artifact" || action === "link_graph")
  ) {
    return {
      action,
      decision: "deny",
      rationale: `lifecycle_state_${eligibility.lifecycleState}_restricted`,
      eligibility,
    };
  }

  if (
    eligibility.source !== "unknown" &&
    eligibility.confidence < LOW_CONFIDENCE_DEFER_THRESHOLD &&
    action !== "discard"
  ) {
    return {
      action,
      decision: "defer",
      rationale: "confidence_below_threshold",
      eligibility,
    };
  }

  return {
    action,
    decision: "allow",
    rationale: "eligible",
    eligibility,
  };
}

/**
 * Gate for active-context SUMMARY/FILTER plans (issue #2347). The single
 * deny rule is the shared `contextCompressionActionsEnabled` gate — a closed
 * gate returns `feature_disabled` before any selection or model work. LLM
 * summaries carry their own cap gate (`activeContextTransformLlmEnabled`)
 * resolved at plan time, not here.
 */
export interface ActiveContextTransformPolicyResult {
  decision: "allow" | "deny";
  rationale: string;
}

export function evaluateActiveContextTransformPolicy(options: {
  actionsEnabled: boolean;
  operation: "SUMMARY" | "FILTER";
}): ActiveContextTransformPolicyResult {
  if (!options.actionsEnabled) {
    return {
      decision: "deny",
      rationale: "contextCompressionActionsEnabled=false",
    };
  }
  return {
    decision: "allow",
    rationale: `${options.operation.toLowerCase()}_eligible`,
  };
}

/**
 * Location interval math (issue #2044).
 *
 * Pure, deterministic helpers over UTC ISO-8601 instants: half-open
 * [start, end) day windows (reusing the DST-correct activity day-window), IANA
 * local-day bucketing, overlap, observation→segment dwell, and dominant-place
 * selection with stable tie-breaking. No IO, no clocks, no randomness.
 */

import { activityDayWindow, isValidActivityDate } from "../activity/digest.js";
import type { LocationObservation, LocationPlace, LocationSegment } from "./types.js";

export function isValidLocationDate(date: string): boolean {
  return isValidActivityDate(date);
}

/** Half-open [start, end) UTC ISO bounds of a local day. */
export function locationDayWindow(date: string, timezone: string): { startUtc: string; endUtc: string } {
  if (!isValidActivityDate(date)) {
    throw new RangeError(`Invalid location date "${date}"; expected a real YYYY-MM-DD day.`);
  }
  return activityDayWindow(date, timezone);
}

function assertFiniteInstant(iso: string, what: string): number {
  const ms = Date.parse(iso);
  if (typeof iso !== "string" || !Number.isFinite(ms)) {
    throw new RangeError(`${what} must be a UTC ISO-8601 instant; got "${String(iso)}"`);
  }
  return ms;
}

/** The IANA local calendar day (YYYY-MM-DD) an instant falls in. */
export function localDayKey(instantUtc: string, timezone: string): string {
  assertFiniteInstant(instantUtc, "instantUtc");
  return new Intl.DateTimeFormat("en-CA", {
    timeZone: timezone,
    year: "numeric",
    month: "2-digit",
    day: "2-digit",
  }).format(new Date(instantUtc));
}

function compareObservations(a: LocationObservation, b: LocationObservation): number {
  if (a.observedAtUtc !== b.observedAtUtc) {
    return a.observedAtUtc < b.observedAtUtc ? -1 : 1;
  }
  // Total comparator (§12): equal-key observations fall back to place id so
  // ordering — and therefore dwell attribution — is deterministic.
  if (a.place.id !== b.place.id) {
    return a.place.id < b.place.id ? -1 : 1;
  }
  return 0;
}

/** Bucket observations into their IANA local days, sorted within each day. */
export function bucketObservationsByDay(
  observations: readonly LocationObservation[],
  timezone: string,
): Map<string, LocationObservation[]> {
  const buckets = new Map<string, LocationObservation[]>();
  for (const observation of observations) {
    assertFiniteInstant(observation.observedAtUtc, "observation observedAtUtc");
    const key = localDayKey(observation.observedAtUtc, timezone);
    const bucket = buckets.get(key);
    if (bucket === undefined) buckets.set(key, [observation]);
    else bucket.push(observation);
  }
  for (const bucket of buckets.values()) bucket.sort(compareObservations);
  return buckets;
}

/** Overlap in ms of two half-open intervals; 0 when disjoint. */
export function intervalOverlapMs(
  a: { startUtc: string; endUtc: string },
  b: { startUtc: string; endUtc: string },
): number {
  const overlap =
    Math.min(Date.parse(a.endUtc), Date.parse(b.endUtc)) - Math.max(Date.parse(a.startUtc), Date.parse(b.startUtc));
  return Math.max(0, overlap);
}

function placeForSegment(place: LocationPlace, retainCoordinates: boolean): LocationPlace {
  if (retainCoordinates || place.latitude === undefined || place.longitude === undefined) {
    return place;
  }
  return {
    id: place.id,
    label: place.label,
    ...(place.kind === undefined ? {} : { kind: place.kind }),
  };
}

/**
 * Derive place-visit segments from a day's observations: each observation
 * covers [its instant, the next observation's instant ∩ window end). The last
 * observation is capped by the window end, so dwell never crosses the day
 * boundary. Out-of-window observations are a provider contract violation and
 * are rejected loudly rather than silently reshaping the day. Coordinates are
 * stripped unless `retainCoordinates` is set.
 */
export function observationSegments(
  observations: readonly LocationObservation[],
  window: { startUtc: string; endUtc: string },
  options: { retainCoordinates: boolean },
): LocationSegment[] {
  const startMs = assertFiniteInstant(window.startUtc, "window startUtc");
  const endMs = assertFiniteInstant(window.endUtc, "window endUtc");
  if (startMs >= endMs) {
    throw new RangeError("location window must satisfy startUtc < endUtc");
  }
  const ordered = [...observations].sort(compareObservations);
  const segments: LocationSegment[] = [];
  for (let index = 0; index < ordered.length; index += 1) {
    const current = ordered[index]!;
    const currentMs = Date.parse(current.observedAtUtc);
    if (currentMs < startMs || currentMs >= endMs) {
      throw new RangeError(
        `location observation at "${current.observedAtUtc}" falls outside the requested [${window.startUtc}, ${window.endUtc}) window`,
      );
    }
    const nextMs =
      index + 1 < ordered.length ? Date.parse(ordered[index + 1]!.observedAtUtc) : endMs;
    const segmentEndMs = Math.min(nextMs, endMs);
    if (currentMs >= segmentEndMs) continue;
    segments.push({
      startUtc: new Date(currentMs).toISOString(),
      endUtc: new Date(segmentEndMs).toISOString(),
      place: placeForSegment(current.place, options.retainCoordinates),
      ...(current.confidence !== undefined ? { confidence: current.confidence } : {}),
    });
  }
  return segments;
}

/** Total time a place was occupied (union of its segment intervals, ms). */
export interface PlaceDuration {
  place: LocationPlace;
  totalMs: number;
  /** Earliest segment start contributing to this place's total. */
  firstStartUtc: string;
}

function unionIntervalMs(segments: readonly LocationSegment[]): number {
  // Merge overlapping [start, end) intervals per place so two providers
  // observing the same visit do not double-count its duration.
  const bounds = segments
    .map((segment) => ({ start: Date.parse(segment.startUtc), end: Date.parse(segment.endUtc) }))
    .sort((a, b) => (a.start !== b.start ? a.start - b.start : a.end - b.end));
  let total = 0;
  let sweepStart: number | null = null;
  let sweepEnd = 0;
  for (const bound of bounds) {
    if (sweepStart === null || bound.start > sweepEnd) {
      if (sweepStart !== null) total += sweepEnd - sweepStart;
      sweepStart = bound.start;
      sweepEnd = bound.end;
    } else if (bound.end > sweepEnd) {
      sweepEnd = bound.end;
    }
  }
  if (sweepStart !== null) total += sweepEnd - sweepStart;
  return total;
}

/** Per-place totals across every segment given (multi-source safe). */
export function placeDurations(segments: readonly LocationSegment[]): PlaceDuration[] {
  const byPlace = new Map<string, { place: LocationPlace; segments: LocationSegment[]; firstStartUtc: string }>();
  for (const segment of segments) {
    const existing = byPlace.get(segment.place.id);
    if (existing === undefined) {
      byPlace.set(segment.place.id, { place: segment.place, segments: [segment], firstStartUtc: segment.startUtc });
      continue;
    }
    existing.segments.push(segment);
    if (segment.startUtc < existing.firstStartUtc) existing.firstStartUtc = segment.startUtc;
    // Two providers may label the same place id differently; keep the
    // lexicographically smallest label so rendering stays deterministic.
    if (segment.place.label < existing.place.label) existing.place = segment.place;
  }
  const durations: PlaceDuration[] = [...byPlace.values()].map((entry) => ({
    place: entry.place,
    totalMs: unionIntervalMs(entry.segments),
    firstStartUtc: entry.firstStartUtc,
  }));
  durations.sort((a, b) => {
    if (a.place.id !== b.place.id) return a.place.id < b.place.id ? -1 : 1;
    return 0;
  });
  return durations;
}

export interface DominantPlaceResult {
  place: LocationPlace;
  totalMs: number;
}

/**
 * The place with the longest total occupancy. Ties are stable and
 * deterministic: earlier first start wins, then the lexicographically smaller
 * place id — never insertion order.
 */
export function dominantPlace(segments: readonly LocationSegment[]): DominantPlaceResult | null {
  const durations = placeDurations(segments);
  let best: PlaceDuration | null = null;
  for (const duration of durations) {
    if (best === null) {
      best = duration;
      continue;
    }
    if (duration.totalMs !== best.totalMs) {
      if (duration.totalMs > best.totalMs) best = duration;
      continue;
    }
    if (duration.firstStartUtc !== best.firstStartUtc) {
      if (duration.firstStartUtc < best.firstStartUtc) best = duration;
      continue;
    }
    if (duration.place.id < best.place.id) best = duration;
  }
  return best === null ? null : { place: best.place, totalMs: best.totalMs };
}

/**
 * Pattern-reinforcement maintenance job (issue #687 PR 2/4).
 *
 * Reads all memories via `StorageManager.readAllMemories()`, clusters
 * non-procedural memories by normalized content, and reinforces the
 * most-recent member of each large-enough cluster:
 *
 *   1. Cluster across active AND already-superseded members.  This is
 *      load-bearing: after the first reinforcement pass, older
 *      duplicates are marked `superseded`, so on the next pass the
 *      "active count" alone would be just `canonical + N-new`.  By
 *      keeping superseded members in the cluster for the threshold
 *      check, an established canonical (count >= minCount) keeps
 *      growing as soon as a single new duplicate arrives.
 *      `forgotten` / `archived` / `quarantined` / `pending_review` /
 *      `rejected` stay excluded per CLAUDE.md rule 53.
 *   2. Pick the most-recent ACTIVE member of each cluster as the
 *      canonical.  Stamp it with `reinforcement_count` (total cluster
 *      size including superseded members) and `last_reinforced_at`.
 *      Record provenance: `derived_from = [...source-ids...]` and
 *      `derived_via = "pattern-reinforcement"`.
 *   3. Mark any still-active duplicates with `status: "superseded"`
 *      and point `supersededBy` at the canonical id.
 *
 * The job is idempotent: re-running on the same corpus does not
 * double-bump `reinforcement_count` (the bump-only-on-change guard
 * compares cluster size to the canonical's previous counter), and
 * already-superseded duplicates simply pass through.
 *
 * Recall integration (boost from `reinforcement_count`) and the CLI
 * surface ship in PR 3/4 and PR 4/4 respectively — this PR only wires
 * the maintenance job and storage plumbing.
 */

import { clusterByKey } from "../procedural/reinforcement-core.js";
import { buildRetiredFactTombstoneInputs, type TombstoneReason, type TombstoneCreatedBy } from "../lifecycle/tombstones.js";
import { supersessionKeysForFact } from "../temporal-supersession.js";
import { excludeSupportPassportPrivateMemories } from "../support-passport/card-projection.js";
import type {
  MemoryFile,
  MemoryFrontmatter,
  MemoryStatus,
} from "../types.js";

/**
 * Storage surface the job needs.  Defined as a structural interface so
 * tests can pass an in-memory stub without booting a full
 * `StorageManager` (mirrors the pattern in `forget.ts`).
 */
export interface PatternReinforcementStorage {
  readAllMemories(): Promise<MemoryFile[]>;
  writeMemoryFrontmatter(
    memory: MemoryFile,
    patch: Partial<MemoryFrontmatter>,
  ): Promise<boolean>;
  /**
   * Best-effort tombstone append for retired duplicates (issue #1579 thread
   * Oblq9). Optional so unit-test stubs need not implement it; the production
   * StorageManager satisfies it via its appendTombstone chokepoint.
   */
  appendTombstone?(input: {
    reason: TombstoneReason;
    createdBy: TombstoneCreatedBy;
    sourceMemoryId: string;
    contentHash?: string;
    rawContent: string;
    entityRef?: string;
    supersessionKey?: string;
    createdAt: string;
  }): Promise<string | null>;
}

export interface PatternReinforcementOptions {
  /** Categories the job considers (e.g. ["preference", "fact", "decision"]). */
  categories: readonly string[];
  /** Minimum cluster size required to promote a canonical. */
  minCount: number;
  /** ISO 8601 timestamp source.  Defaults to `Date.now()`. */
  now?: () => Date;
}

export interface PatternReinforcementClusterResult {
  /** Memory id of the canonical (most-recent) member. */
  canonicalId: string;
  /** Cluster size at run time (mirrors `reinforcement_count`). */
  count: number;
  /** IDs of the source memories that contributed (canonical + duplicates). */
  sourceIds: readonly string[];
  /** IDs of the older duplicates that were marked superseded. */
  supersededIds: readonly string[];
  /**
   * `true` when the canonical's `reinforcement_count` actually
   * changed during this run.  False when the job converged
   * idempotently (same cluster size as the previous run).
   */
  reinforcementBumped: boolean;
}

export interface PatternReinforcementResult {
  /** Number of clusters that met the `minCount` threshold. */
  clustersFound: number;
  /** Number of canonical memories whose reinforcement counter changed. */
  canonicalsUpdated: number;
  /** Total duplicate memories newly marked `status: "superseded"`. */
  duplicatesSuperseded: number;
  /** Per-cluster details for tests / observability. */
  clusters: PatternReinforcementClusterResult[];
}

/**
 * Cluster key derivation: lowercase + collapse whitespace + truncate to
 * 200 chars.  Pure helper so callers and tests can compute the same key
 * without re-implementing the rule.
 *
 * Truncation is intentional — long-form content with a stable opening
 * still clusters together even when the tail differs slightly.  200
 * chars matches the spec.
 *
 * @deprecated Prefer `patternReinforcementClusterKey(category, content)`
 * which partitions by memory category so identical text in different
 * categories does not get cross-superseded (PR #730 review feedback,
 * Codex P2).  This bare helper is kept exported for backward
 * compatibility with callers that already partition by category
 * upstream.
 */
export function patternReinforcementKey(content: string): string {
  return content.trim().toLowerCase().replace(/\s+/g, " ").slice(0, 200);
}

/**
 * Cluster key derivation that includes the memory category as a prefix
 * so identical text under different categories (e.g. `fact` and
 * `decision`) does not collapse into one cluster.  Without this,
 * pattern reinforcement would silently supersede a fact when a
 * decision happens to share the same canonical text — distorting
 * downstream category-scoped retrieval and governance behavior (PR
 * #730 review feedback, Codex P2).
 */
export function patternReinforcementClusterKey(category: string, content: string): string {
  // Use a `::` separator that cannot appear in either component so
  // a category like `fact` plus content starting with `decision:...`
  // cannot collide with category `decision`.
  return `${category}::${patternReinforcementKey(content)}`;
}

/**
 * Compare two memories by their effective timestamp.
 *
 * Parses each timestamp to an *instant* (epoch ms) via `Date.parse`
 * rather than lexicographic `localeCompare` so ISO-8601 variants with
 * non-`Z` offsets (e.g. `2026-04-26T10:00:00+02:00`) and mixed
 * millisecond precision compare by actual time rather than by raw
 * string (PR #730 review feedback, Codex P2).  Imported / hand-edited
 * memory files routinely use such variants.
 *
 * Falls back to the raw string when an instant is unparseable (a
 * corrupt frontmatter is rare but possible) and tie-breaks on memory
 * id for stable ordering.
 */
function pickCanonical(memories: MemoryFile[]): MemoryFile {
  let best = memories[0];
  let bestInstant = memoryInstant(best);
  let bestStamp = memoryStamp(best);
  for (let i = 1; i < memories.length; i += 1) {
    const candidate = memories[i];
    const instant = memoryInstant(candidate);
    const stamp = memoryStamp(candidate);
    let cmp: number;
    if (instant !== null && bestInstant !== null) {
      cmp = instant - bestInstant;
    } else {
      // One side is unparseable — fall back to lexicographic compare
      // on raw strings.  This keeps ordering deterministic even when
      // a corrupt timestamp slipped past the parser.
      cmp = stamp.localeCompare(bestStamp);
    }
    if (cmp > 0 || (cmp === 0 && candidate.frontmatter.id > best.frontmatter.id)) {
      best = candidate;
      bestInstant = instant;
      bestStamp = stamp;
    }
  }
  return best;
}

function memoryStamp(memory: MemoryFile): string {
  // Prefer `updated`, fall back to `created`.  Both are ISO-8601 and
  // present on every well-formed memory; the parser default-fills them
  // when absent.
  return memory.frontmatter.updated || memory.frontmatter.created || "";
}

/**
 * Parse a memory's effective timestamp to epoch milliseconds.  Returns
 * `null` for an unparseable / empty stamp so callers can fall back to
 * a string compare without observing `NaN` propagation.
 */
function memoryInstant(memory: MemoryFile): number | null {
  const stamp = memoryStamp(memory);
  if (stamp.length === 0) return null;
  const parsed = Date.parse(stamp);
  return Number.isFinite(parsed) ? parsed : null;
}

const ACTIVE_STATUS: MemoryStatus = "active";

/**
 * Run pattern reinforcement across the configured categories.
 *
 * The function is intentionally pure (modulo the storage handle): no
 * cron scheduling, no telemetry side effects, no logging.  Callers
 * (orchestrator cron path / CLI surface in PR 4) own those concerns.
 */
export async function runPatternReinforcement(
  storage: PatternReinforcementStorage,
  options: PatternReinforcementOptions,
): Promise<PatternReinforcementResult> {
  const minCount = Math.max(2, Math.floor(options.minCount));
  const targetCategories = new Set(options.categories);
  const now = options.now ?? (() => new Date());
  const nowIso = now().toISOString();

  // No-op fast paths so unconfigured callers get a clean result rather
  // than walking the entire corpus.
  if (targetCategories.size === 0) {
    return emptyResult();
  }

  const memories = excludeSupportPassportPrivateMemories(await storage.readAllMemories());

  // Cluster across BOTH active and already-superseded memories so a
  // canonical that has previously absorbed duplicates still gets
  // reinforced when a single new duplicate arrives (Codex P1).
  // Without this, the post-first-pass active set is just
  // `canonical + N-new`, which falls below `minCount` for any
  // realistic cadence.  CLAUDE.md rule 53 still applies — forgotten,
  // archived, quarantined, pending_review, and rejected memories
  // remain excluded.
  const eligible = memories.filter((m) => {
    if (!targetCategories.has(m.frontmatter.category)) return false;
    const status = m.frontmatter.status ?? ACTIVE_STATUS;
    return status === ACTIVE_STATUS || status === "superseded";
  });

  if (eligible.length === 0) return emptyResult();

  // Cluster by `<category> <content>` so identical text in different
  // categories does not get cross-superseded (PR #730 review feedback,
  // Codex P2).
  const clusters = clusterByKey(eligible, (m) =>
    patternReinforcementClusterKey(m.frontmatter.category, m.content),
  );

  const result: PatternReinforcementResult = {
    clustersFound: 0,
    canonicalsUpdated: 0,
    duplicatesSuperseded: 0,
    clusters: [],
  };

  for (const cluster of clusters.values()) {
    // The cluster represents the full historical pattern — its size
    // is the threshold the user configured against.
    if (cluster.length < minCount) continue;

    // Active members are the only ones we can write to (or pick as
    // canonical).  If every member is already superseded — e.g. a
    // prior canonical was archived externally — there's nothing to
    // do for this cluster on this pass.
    const activeMembers = cluster.filter((m) => {
      const status = m.frontmatter.status ?? ACTIVE_STATUS;
      return status === ACTIVE_STATUS;
    });
    if (activeMembers.length === 0) continue;

    result.clustersFound += 1;

    const canonical = pickCanonical(activeMembers);
    const activeDuplicates = activeMembers.filter((m) => m !== canonical);

    // Source-id provenance: include the canonical + every member
    // that contributed to the cluster (active and superseded), so
    // the lineage is fully reconstructible.  Sort ids
    // deterministically (CLAUDE.md rule 38) so re-runs produce
    // stable on-disk output.
    const sourceIds = [...cluster]
      .map((m) => m.frontmatter.id)
      .filter((id): id is string => typeof id === "string" && id.length > 0)
      .sort();

    // Use `sourceIds.length` (the filtered, valid-ID set) as the
    // canonical cluster count for both the reinforcement bump guard
    // and the on-disk `reinforcement_count` field.  Using the raw
    // `cluster.length` would inflate the metric whenever any member
    // lacks a valid string ID, causing telemetry to diverge from
    // what is actually being reinforced (PR #730 review, Cursor).
    const previousCount = canonical.frontmatter.reinforcement_count ?? 0;
    const newCount = sourceIds.length;
    const reinforcementBumped = newCount > previousCount;

    // Refresh provenance on the canonical whenever cluster membership
    // changes — even if the cluster size happens to stay constant
    // (e.g. one older member archived externally while a new
    // duplicate arrived).  Without this, `derived_from` would
    // silently fall out of sync with the actual contributors and
    // diagnostics would surface false-positive "missing source"
    // signals (PR #730 review feedback, Codex P2).
    const previousDerivedFrom = Array.isArray(canonical.frontmatter.derived_from)
      ? [...canonical.frontmatter.derived_from].sort()
      : [];
    const sortedSourceIds = [...sourceIds].sort();
    const membershipChanged =
      previousDerivedFrom.length !== sortedSourceIds.length ||
      previousDerivedFrom.some((id, i) => id !== sortedSourceIds[i]);
    const previousVia = canonical.frontmatter.derived_via;
    const viaChanged = previousVia !== "pattern-reinforcement";
    const canonicalNeedsRefresh =
      reinforcementBumped || membershipChanged || viaChanged;

    // Patch the canonical when the cluster grew, the cluster
    // membership rotated, or the canonical was previously stamped by
    // a different operator.  Idempotent re-runs on a stable corpus
    // (same size, same members, same operator) still produce zero
    // writes.
    //
    // On a provenance-only refresh (membership rotated but count
    // unchanged), preserve the existing `reinforcement_count` and
    // `last_reinforced_at` so they remain monotonic and only advance
    // on genuine reinforcement events (PR #730 review, Codex P2).
    if (canonicalNeedsRefresh) {
      const patch: Partial<MemoryFrontmatter> = {
        derived_from: sourceIds,
        derived_via: "pattern-reinforcement",
        updated: nowIso,
      };
      if (reinforcementBumped) {
        patch.reinforcement_count = newCount;
        patch.last_reinforced_at = nowIso;
      } else {
        // Carry forward the existing values so a provenance-only
        // refresh does not reset or re-timestamp the counter.
        patch.reinforcement_count =
          canonical.frontmatter.reinforcement_count ?? newCount;
        patch.last_reinforced_at =
          canonical.frontmatter.last_reinforced_at ?? nowIso;
      }
      await storage.writeMemoryFrontmatter(canonical, patch);
      result.canonicalsUpdated += 1;
    }

    // Supersede any still-active duplicates.  Already-superseded
    // members were filtered out above, which doubles as our
    // crash-recovery guard: a previous run that died mid-supersede
    // simply re-runs the active half on the next pass.
    const supersededIds: string[] = [];
    for (const dup of activeDuplicates) {
      const patch: Partial<MemoryFrontmatter> = {
        status: "superseded",
        supersededBy: canonical.frontmatter.id,
        supersededAt: nowIso,
        updated: nowIso,
      };
      await storage.writeMemoryFrontmatter(dup, patch);
      supersededIds.push(dup.frontmatter.id);
      result.duplicatesSuperseded += 1;
      // Issue #1579 thread Oblq9 / Ocn0C / OcoPs: emit a tombstone so the
      // retired duplicate cannot resurrect through re-extraction / import.
      // Pattern reinforcement retires via writeMemoryFrontmatter which
      // bypasses the writeMemory chokepoint; without this emit, the same
      // content re-extracted before a manual rebuild would be stored active.
      // Threads Ocn0C/OcoPs: emit one tombstone PER derived supersession key
      // via buildRetiredFactTombstoneInputs (same helper as supersedeMemory +
      // forgetMemory), not a single entityRef-only record — a paraphrased
      // re-extraction with the same entity/attribute can only be caught by
      // the keyed tier. Best-effort (the interface method is optional; a
      // failure must not fail the reinforcement job).
      if (storage.appendTombstone) {
        for (const input of buildRetiredFactTombstoneInputs(
          {
            id: dup.frontmatter.id,
            content: dup.content,
            contentHash: dup.frontmatter.contentHash,
            entityRef: dup.frontmatter.entityRef,
            structuredAttributes: dup.frontmatter.structuredAttributes,
          },
          { reason: "supersession", createdBy: "supersession", createdAt: nowIso, supersessionKeysForFact },
        )) {
          try {
            await storage.appendTombstone(input);
          } catch {
            // Best-effort: a tombstone append failure must not fail the
            // reinforcement job (gotcha #13 / rule 34 spirit).
          }
        }
      }
    }

    result.clusters.push({
      canonicalId: canonical.frontmatter.id,
      count: newCount,
      sourceIds,
      supersededIds,
      reinforcementBumped,
    });
  }

  return result;
}

function emptyResult(): PatternReinforcementResult {
  return {
    clustersFound: 0,
    canonicalsUpdated: 0,
    duplicatesSuperseded: 0,
    clusters: [],
  };
}

/**
 * Recognition-index write-path maintenance (issue #2975).
 *
 * Sibling of recall-recognition-search.ts at the memory write-path seam:
 * when recallRecognitionTier is enabled, a namespace write upserts (or
 * removes) that memory's id in `<memoryDir>/state/index_recognition.json`
 * so the recall slice's loadRecognitionIndex sees a fresh entry. Off-path
 * (`enabled !== true`) returns immediately — zero index I/O.
 *
 * Descriptions: layer 1 has no generator. This slice keeps ids current and
 * fills description from the first non-empty body line (the compact
 * `id: description` form the tier already renders). Discriminability
 * rewrite is a later tidy pass.
 *
 * Serialization matches temporal-index: an in-process op chain per index
 * path plus a directory lock around load → mutate → save. saveRecognitionIndex
 * is single-writer and does not lock on its own.
 */
import { promises as fsp } from "node:fs";
import path from "node:path";
import { setTimeout as delay } from "node:timers/promises";

import {
  buildRecognitionIndex,
  loadRecognitionIndex,
  recognitionIndexPath,
  saveRecognitionIndex,
  type RecognitionIndexEntry,
} from "../recall-recognition-tier.js";

export type RecognitionIndexChange =
  | { readonly action: "upsert"; readonly id: string; readonly content: string }
  | { readonly action: "remove"; readonly id: string };

const writeChains = new Map<string, Promise<void>>();
const LOCK_POLL_MS = 10;
const LOCK_ATTEMPTS = 50;
const LOCK_STALE_MS = 60_000;

/**
 * First non-empty line of a memory body. Layer 1 has no description
 * generator; this is the compact line the tier already renders.
 */
export function recognitionDescriptionFromContent(content: string): string {
  const trimmed = content.trim();
  if (trimmed.length === 0) return "";
  const newline = trimmed.indexOf("\n");
  return newline === -1 ? trimmed : trimmed.slice(0, newline).trimEnd();
}

function withIndexChain<T>(indexPath: string, op: () => Promise<T>): Promise<T> {
  const previous = writeChains.get(indexPath) ?? Promise.resolve();
  const run = previous.then(op, op);
  const tail = run.then(() => undefined, () => undefined);
  writeChains.set(indexPath, tail);
  void tail.then(() => {
    if (writeChains.get(indexPath) === tail) writeChains.delete(indexPath);
  });
  return run;
}

async function removeAbandonedRecognitionLock(
  lockDir: string,
): Promise<"removed" | "wait" | "blocked"> {
  try {
    const info = await fsp.lstat(lockDir);
    if (info.isSymbolicLink()) return "blocked";
    if (!info.isDirectory()) {
      await fsp.rm(lockDir, { force: true });
      return "removed";
    }
    if (Date.now() - info.mtimeMs < LOCK_STALE_MS) return "wait";
    await fsp.rm(lockDir, { recursive: true, force: true });
    return "removed";
  } catch (error) {
    if ((error as NodeJS.ErrnoException)?.code === "ENOENT") return "removed";
    return "blocked";
  }
}

async function withRecognitionIndexLock<T>(memoryDir: string, op: () => Promise<T>): Promise<T> {
  const lockDir = `${recognitionIndexPath(memoryDir)}.lock.d`;
  for (let attempt = 0; attempt < LOCK_ATTEMPTS; attempt++) {
    try {
      await fsp.mkdir(lockDir);
      try {
        return await op();
      } finally {
        await fsp.rm(lockDir, { recursive: true, force: true }).catch(() => undefined);
      }
    } catch (error) {
      const code = (error as NodeJS.ErrnoException)?.code;
      if (code === "ENOENT") {
        await fsp.mkdir(path.dirname(lockDir), { recursive: true }).catch(() => undefined);
        continue;
      }
      if (code !== "EEXIST") throw error;
      const cleanup = await removeAbandonedRecognitionLock(lockDir);
      if (cleanup === "blocked") {
        throw new Error(`recognition index lock blocked at ${lockDir}`);
      }
      if (cleanup === "removed") continue;
      await delay(LOCK_POLL_MS);
    }
  }
  throw new Error(`recognition index lock timed out at ${lockDir}`);
}

function applyChanges(
  entries: readonly RecognitionIndexEntry[],
  changes: readonly RecognitionIndexChange[],
): RecognitionIndexEntry[] {
  const next = entries.map((entry) => ({ id: entry.id, description: entry.description }));
  const byId = new Map(next.map((entry, index) => [entry.id, index]));
  for (const change of changes) {
    const id = change.id.trim();
    if (id.length === 0) continue;
    if (change.action === "remove") {
      const index = byId.get(id);
      if (index === undefined) continue;
      next.splice(index, 1);
      byId.delete(id);
      for (const [key, value] of byId) {
        if (value > index) byId.set(key, value - 1);
      }
      continue;
    }
    const description = recognitionDescriptionFromContent(change.content);
    const existing = byId.get(id);
    if (existing !== undefined) {
      next[existing] = { id, description };
    } else {
      byId.set(id, next.length);
      next.push({ id, description });
    }
  }
  return next;
}

function meaningfulChanges(changes: readonly RecognitionIndexChange[]): RecognitionIndexChange[] {
  return changes.filter((change) => change.id.trim().length > 0);
}

/**
 * Incrementally maintain a namespace recognition index after memory writes.
 * `enabled: false` is a proven no-op: no reads, no writes, no locks.
 */
export async function maintainRecognitionIndexAfterWrite(args: {
  memoryDir: string;
  enabled: boolean;
  changes: readonly RecognitionIndexChange[];
}): Promise<void> {
  if (args.enabled !== true) return;
  const changes = meaningfulChanges(args.changes);
  if (changes.length === 0) return;

  const indexPath = recognitionIndexPath(args.memoryDir);
  await withIndexChain(indexPath, () =>
    withRecognitionIndexLock(args.memoryDir, async () => {
      const loaded = await loadRecognitionIndex(args.memoryDir);
      // `changes` is the full set the caller wants published. Persist-path
      // bootstraps from the active corpus when the file is absent so a
      // first post-enable write cannot mint a 1-id index that recall would
      // treat as authoritative.
      const entries = applyChanges(loaded?.entries ?? [], changes);
      await saveRecognitionIndex(args.memoryDir, buildRecognitionIndex(entries));
    }),
  );
}

