/**
 * Session-end agent-experience extraction (issue #2979).
 *
 * At `session_end` the completed session's buffered turns are distilled —
 * deterministically, no LLM — into at most ONE Situation/Approach/Reflect
 * "experience episode" memory (agent-subject, category `procedure`,
 * `pending_review`), mirroring OpenViking's experience-memory schema at the
 * granularity Remnic's trust model allows: a machine-derived write that
 * stays behind the existing sealed-envelope write path and never activates
 * itself.
 *
 * Determinism: the episode is a pure function of the turn list — same
 * transcript, same episode. Refusal/failure is signal, not a skip: a
 * session whose terminal assistant turn records a failure gets a failure
 * reflection.
 *
 * v1 heuristics (same tier as procedure-miner's `pseudoStepsFromCluster`):
 * situation = first substantive user turn (task shape); approach = first
 * sentences of the assistant turns; reflection = terminal outcome evidence.
 */

import { createHash } from "node:crypto";

import { log } from "../logger.js";
import type { BufferTurn, MemoryFile, MemoryStatus, PluginConfig } from "../types.js";
import { composeSalvagedEnvelope } from "../salvage-envelope.js";
import type { SealedMemoryEnvelope } from "../write-envelope.js";

export type SessionExperienceOutcomeKind = "success" | "failure" | "inconclusive";

/** The OpenViking Situation/Approach/Reflect classes, Remnic spelling. */
export interface ExperienceEpisode {
  /** Task shape: what the session was asked to do. */
  situation: string;
  /** What the agent tried, in order. */
  approach: string;
  /** Outcome and what to do differently. */
  reflection: string;
  outcomeKind: SessionExperienceOutcomeKind;
}

export type SessionExperienceSkippedReason =
  | "session_experience_disabled"
  | "aborted"
  | "deadline_elapsed"
  | "duplicate_session"
  | "insufficient_signal";

export type SessionExperienceRunResult =
  | { written: true; episode: ExperienceEpisode; memoryId: string }
  | { written: false; skippedReason: SessionExperienceSkippedReason };

/** The subset of StorageManager the experience write needs (test-friendly). */
export interface SessionExperienceStorage {
  readAllMemories(): Promise<MemoryFile[]>;
  writeSealedMemory(
    envelope: SealedMemoryEnvelope,
    extras?: { status?: MemoryStatus },
  ): Promise<{ id?: string }>;
}

export interface SessionExperienceRunOptions {
  turns: readonly BufferTurn[];
  sessionKey: string;
  config: PluginConfig;
  storage: SessionExperienceStorage;
  abortSignal?: AbortSignal;
  /** Shared flush deadline (epoch ms); skipped when already elapsed. */
  deadlineMs?: number;
}

// ---------------------------------------------------------------------------
// Deterministic derivation
// ---------------------------------------------------------------------------

const SITUATION_MAX_CHARS = 280;
const SNIPPET_MAX_CHARS = 160;
const APPROACH_MAX_SNIPPETS = 3;
const MIN_SITUATION_CHARS = 16;

/** Terminal-outcome markers, scanned over ASSISTANT turns only (last first). */
const FAILURE_MARKER =
  /\b(?:failed|failing|failure|cannot|can't|unable to|blocked|refused|refusal)\b/i;
const SUCCESS_MARKER =
  /\b(?:succeeded|verified|tests? pass(?:ed|ing)?|fixed|resolved|completed successfully|shipped)\b/i;

function collapse(text: string): string {
  return text.replace(/\s+/g, " ").trim();
}

function capAtWordBoundary(text: string, maxChars: number): string {
  if (text.length <= maxChars) return text;
  const slice = text.slice(0, maxChars);
  const lastSpace = slice.lastIndexOf(" ");
  return `${(lastSpace > maxChars * 0.6 ? slice.slice(0, lastSpace) : slice).trim()}…`;
}

function firstSentence(text: string): string {
  const match = collapse(text).match(/^[^.!?]*[.!?]/);
  return collapse(match ? match[0] : text);
}

function sentenceContaining(text: string, marker: RegExp): string {
  const flat = collapse(text);
  for (const sentence of flat.split(/(?<=[.!?])\s+/)) {
    if (marker.test(sentence)) return sentence;
  }
  return flat;
}

function classifyOutcome(assistantTurns: string[]): { outcomeKind: SessionExperienceOutcomeKind; evidence: string } {
  for (let i = assistantTurns.length - 1; i >= 0; i -= 1) {
    const turn = assistantTurns[i];
    if (FAILURE_MARKER.test(turn)) {
      return { outcomeKind: "failure", evidence: sentenceContaining(turn, FAILURE_MARKER) };
    }
    if (SUCCESS_MARKER.test(turn)) {
      return { outcomeKind: "success", evidence: sentenceContaining(turn, SUCCESS_MARKER) };
    }
  }
  return { outcomeKind: "inconclusive", evidence: "" };
}

function reflectionFor(outcomeKind: SessionExperienceOutcomeKind, evidence: string): string {
  if (outcomeKind === "failure") {
    return `The session failed: "${capAtWordBoundary(evidence, SNIPPET_MAX_CHARS)}". Change that step before retrying the same approach.`;
  }
  if (outcomeKind === "success") {
    return `The session succeeded: "${capAtWordBoundary(evidence, SNIPPET_MAX_CHARS)}". The approach above worked for this situation.`;
  }
  return "No terminal outcome signal appears in the transcript; treat the approach above as unverified.";
}

/**
 * Derive the single experience episode a completed session yields, or `null`
 * when the transcript carries no learnable signal (no task, or no agent work).
 */
export function extractExperienceEpisode(turns: readonly BufferTurn[]): ExperienceEpisode | null {
  const userTurns = turns.filter((turn) => turn.role === "user").map((turn) => collapse(turn.content)).filter(Boolean);
  const situationSource = userTurns.find((content) => content.length >= MIN_SITUATION_CHARS);
  if (situationSource === undefined) return null;

  const assistantTurns = turns
    .filter((turn) => turn.role === "assistant")
    .map((turn) => collapse(turn.content))
    .filter(Boolean);
  if (assistantTurns.length === 0) return null;

  const snippets: string[] = [];
  for (const turn of assistantTurns) {
    const sentence = firstSentence(turn);
    if (sentence.length === 0 || snippets.includes(sentence)) continue;
    snippets.push(capAtWordBoundary(sentence, SNIPPET_MAX_CHARS));
    if (snippets.length >= APPROACH_MAX_SNIPPETS) break;
  }
  if (snippets.length === 0) return null;

  const { outcomeKind, evidence } = classifyOutcome(assistantTurns);
  return {
    situation: capAtWordBoundary(situationSource, SITUATION_MAX_CHARS),
    approach: snippets.join("; "),
    reflection: reflectionFor(outcomeKind, evidence),
    outcomeKind,
  };
}

// ---------------------------------------------------------------------------
// Gated write
// ---------------------------------------------------------------------------

const EXPERIENCE_SOURCE = "session-experience";

function sessionKeyHash(sessionKey: string): string {
  return createHash("sha256").update(sessionKey).digest("hex");
}

async function hasExistingExperience(
  storage: SessionExperienceStorage,
  hash: string,
): Promise<boolean> {
  const memories = await storage.readAllMemories();
  return memories.some((m) => m.frontmatter.structuredAttributes?.experience_session_hash === hash);
}

/**
 * Run session-end experience extraction for one session. With the gate off
 * this touches NOTHING — no reads, no envelope, no write. On write the
 * episode lands as one `pending_review` agent-subject `procedure` memory
 * (trust-mode review; promotion is the operator's call), deduped per
 * session key so a replayed session_end cannot double-write.
 */
export async function runSessionExperienceExtraction(
  options: SessionExperienceRunOptions,
): Promise<SessionExperienceRunResult> {
  if (options.config.sessionExperience?.enabled !== true) {
    return { written: false, skippedReason: "session_experience_disabled" };
  }
  if (options.abortSignal?.aborted === true) {
    return { written: false, skippedReason: "aborted" };
  }
  if (typeof options.deadlineMs === "number" && Date.now() >= options.deadlineMs) {
    return { written: false, skippedReason: "deadline_elapsed" };
  }

  const hash = sessionKeyHash(options.sessionKey);
  if (await hasExistingExperience(options.storage, hash)) {
    return { written: false, skippedReason: "duplicate_session" };
  }

  const episode = extractExperienceEpisode(options.turns);
  if (episode === null) {
    return { written: false, skippedReason: "insufficient_signal" };
  }

  // Machine-derived from buffered turns — salvage-mode envelope, warn-logged
  // drops (issue #1989 PR4 convention for machine-generated writes).
  const envelope = composeSalvagedEnvelope(
    EXPERIENCE_SOURCE,
    {
      content: `Situation: ${episode.situation}\nApproach: ${episode.approach}\nReflection: ${episode.reflection}`,
      category: "procedure",
      subject: "agent",
      confidence: 0.6,
      tags: ["session-experience", `experience-${episode.outcomeKind}`],
      structuredAttributes: {
        experience_situation: episode.situation,
        experience_approach: episode.approach,
        experience_reflection: episode.reflection,
        experience_outcome: episode.outcomeKind,
        experience_session_hash: hash,
      },
    },
    { source: EXPERIENCE_SOURCE },
  );
  const written = await options.storage.writeSealedMemory(envelope, { status: "pending_review" });
  log.debug(
    `${EXPERIENCE_SOURCE}: wrote episode for session hash ${hash.slice(0, 12)}… (outcome ${episode.outcomeKind})`,
  );
  return { written: true, episode, memoryId: typeof written.id === "string" ? written.id : "" };
}

/**
 * User-owned daily journal (issue #1984 PR1).
 *
 * Files live at `<memoryDir>/journal/<YYYY-MM-DD>.md` — inside the memory
 * directory but outside scan roots, same placement as activity digests.
 * Once written, Remnic never rewrites the file except `seed` with force.
 * All writes go through writeJournalFile, which stats first.
 */
import { mkdirSync, statSync, writeFileSync } from "node:fs";
import path from "node:path";

import { isValidActivityDate } from "./digest.js";

export const JOURNAL_DIR_NAME = "journal";

/** Minimal card shape the seed renderer needs. TimelineCard is assignable. */
export interface JournalSeedCard {
  title: string;
  startUtc: string;
  endUtc: string;
}

export interface SeedJournalInput {
  memoryDir: string;
  date: string;
  cards?: readonly JournalSeedCard[];
  force?: boolean;
}

export interface SeedJournalResult {
  path: string;
  wrote: boolean;
}

const JOURNAL_DAY_TOPLEVEL = /^journal[\\/]\d{4}-\d{2}-\d{2}\.md$/i;
const JOURNAL_DAY_ANYWHERE = /(?:^|[\\/])journal[\\/]\d{4}-\d{2}-\d{2}\.md$/i;

export function journalPath(memoryDir: string, date: string): string {
  if (!isValidActivityDate(date)) {
    throw new RangeError(`Invalid journal date "${date}"; expected YYYY-MM-DD.`);
  }
  return path.join(memoryDir, JOURNAL_DIR_NAME, `${date}.md`);
}

/**
 * Root-aware journal day-file check. With a memory root, only the top-level
 * `journal/<date>.md` matches so a nested `facts/journal/<date>.md` stays
 * recallable. Without a root, fall back to the day-file shape anywhere.
 */
export function isJournalDayPath(filePath: string, memoryRoot?: string): boolean {
  if (memoryRoot !== undefined && memoryRoot.length > 0) {
    const relative = path.relative(memoryRoot, path.resolve(memoryRoot, filePath));
    return JOURNAL_DAY_TOPLEVEL.test(relative);
  }
  return JOURNAL_DAY_ANYWHERE.test(filePath);
}

export function todayJournalDate(now: Date = new Date()): string {
  const year = now.getFullYear();
  const month = String(now.getMonth() + 1).padStart(2, "0");
  const day = String(now.getDate()).padStart(2, "0");
  return `${year}-${month}-${day}`;
}

function formatCardDuration(card: JournalSeedCard): string {
  const start = Date.parse(card.startUtc);
  const end = Date.parse(card.endUtc);
  const minutes =
    Number.isFinite(start) && Number.isFinite(end) && end > start
      ? Math.round((end - start) / 60_000)
      : 0;
  return `${minutes}m`;
}

function renderJournalSeed(date: string, cards: readonly JournalSeedCard[]): string {
  const ordered = [...cards].sort((left, right) => {
    const byStart = left.startUtc.localeCompare(right.startUtc);
    return byStart !== 0 ? byStart : left.title.localeCompare(right.title);
  });
  const glance =
    ordered.length === 0
      ? ["_No cards._"]
      : ordered.map((card) => `- ${formatCardDuration(card)} ${card.title}`);
  return [`# Journal — ${date}`, "", "## Day at a glance", "", ...glance, "", "## Notes", "", ""].join(
    "\n",
  );
}

/** The only journal write. Stats first; existing files are a no-op unless force. */
export function writeJournalFile(filePath: string, content: string, force: boolean): boolean {
  let exists = false;
  try {
    statSync(filePath);
    exists = true;
  } catch (err) {
    const code = (err as NodeJS.ErrnoException).code;
    if (code !== "ENOENT") throw err;
  }
  if (exists && !force) return false;
  mkdirSync(path.dirname(filePath), { recursive: true });
  writeFileSync(filePath, content);
  return true;
}

export function seedJournal(input: SeedJournalInput): SeedJournalResult {
  const filePath = journalPath(input.memoryDir, input.date);
  const wrote = writeJournalFile(
    filePath,
    renderJournalSeed(input.date, input.cards ?? []),
    input.force === true,
  );
  return { path: filePath, wrote };
}

import type { ActivationPath } from "./graph.js";
import type { MemoryFrontmatter, MemoryStatus } from "./types.js";
import { isValidAsOf } from "./temporal-validity.js";

/** Memory state used to score an intermediate path node. */
export interface PathNodeState
  extends Pick<
    MemoryFrontmatter,
    "valid_at" | "invalid_at" | "created" | "supersededAt" | "eventTimeSource"
  > {
  id: string;
  status: MemoryStatus | null;
}

/** Configuration for graph-path evidence scoring. */
export interface PathScoringOptions {
  asOf: string;
  invalidNodePenalty: number;
}

function isInvalidIntermediate(state: PathNodeState | undefined, asOfMs: number): boolean {
  if (!state || state.status === null) return false;
  if (!isValidAsOf({ ...state, status: state.status }, asOfMs)) return true;

  const hasSupersessionEnd =
    state.status === "superseded" &&
    ((state.invalid_at?.trim().length ?? 0) > 0 ||
      (state.supersededAt?.trim().length ?? 0) > 0);
  return state.status !== "active" && !hasSupersessionEnd;
}

export interface PathScoreDetail {
  score: number;
  pathPenaltyApplied: boolean;
}

export function scoreEvidencePathDetail(
  evidencePath: ActivationPath | null,
  nodeStates: ReadonlyMap<string, PathNodeState>,
  options: PathScoringOptions,
): PathScoreDetail {
  const asOfMs = Date.parse(options.asOf);
  if (!Number.isFinite(asOfMs)) {
    throw new Error("asOf must be a finite timestamp");
  }
  if (!evidencePath) return { score: 1, pathPenaltyApplied: false };
  let multiplier = evidencePath.edgeConfidences.reduce(
    (product, confidence) => product * confidence,
    1,
  );
  let invalidIntermediateCount = 0;
  for (const nodeId of evidencePath.nodeIds.slice(1, -1)) {
    if (isInvalidIntermediate(nodeStates.get(nodeId), asOfMs)) {
      invalidIntermediateCount += 1;
      multiplier *= options.invalidNodePenalty;
    }
  }
  return {
    score: multiplier,
    pathPenaltyApplied: invalidIntermediateCount > 0 && options.invalidNodePenalty !== 1,
  };
}

/**
 * Return the multiplicative evidence factor for one graph activation path.
 *
 * Edge confidence is multiplied for every hop. Invalid intermediate memories
 * receive the configured penalty once each. Seed and candidate states do not
 * affect the result because the caller already scored those memories.
 */
export function scoreEvidencePath(
  evidencePath: ActivationPath | null,
  nodeStates: ReadonlyMap<string, PathNodeState>,
  options: PathScoringOptions,
): number {
  return scoreEvidencePathDetail(evidencePath, nodeStates, options).score;
}

import type { Dir, Dirent, Stats } from "node:fs";
import type { MemoryFile } from "../types.js";
import type { StorageManager } from "../index.js";
import { lstat, opendir, realpath } from "node:fs/promises";
import path from "node:path";
import { isErrnoCode } from "../utils/errno.js";
import { inferMemoryStatus, toMemoryPathRel } from "../memory-lifecycle-ledger-utils.js";

interface ArchivePathIndex {
  version: number;
  pathsByBasename: Map<string, string[]>;
}
interface ArchivePathIndexUnavailable {
  version: number;
  unavailable: "oversized";
}
type ArchivePathIndexResult = ArchivePathIndex | ArchivePathIndexUnavailable;

function isArchivePathIndexUnavailable(index: ArchivePathIndexResult): index is ArchivePathIndexUnavailable {
  return "unavailable" in index;
}

const MAX_ARCHIVE_PATH_INDEXES = 32;
const MAX_ARCHIVE_PATH_INDEX_BUILDS = 32;
const MAX_ARCHIVE_PATH_INDEX_GENERATION_RETRIES = 1;
const MAX_ARCHIVE_INDEX_ENTRIES = 100_000;

function isArchiveScanAbsenceError(error: unknown): boolean {
  return isErrnoCode(error, "ENOENT") || isErrnoCode(error, "ENOTDIR");
}

export class GraphPathStateLoader {
  private archivePathIndexes?: Map<string, ArchivePathIndexResult>;
  private archivePathIndexBuilds = new Map<string, Promise<ArchivePathIndexResult | null>>();
  private archiveLstat: (filePath: string) => Promise<Stats> = lstat;
  private archiveRealpath: (filePath: string) => Promise<string> = realpath;
  private openArchiveDirectory: (directoryPath: string) => Promise<Dir> = opendir;
  async readNode(
    storage: StorageManager,
    nodeId: string,
    deadlineAtMs: number | null | undefined,
    allowArchiveLookup: boolean,
  ): Promise<MemoryFile | null> {
    if (typeof deadlineAtMs === "number" && Date.now() >= deadlineAtMs) return null;
    const configuredStorageRoot = path.resolve(storage.dir);
    const storageRoot = await realpath(configuredStorageRoot).catch(() => null);
    if (!storageRoot || storageRoot !== configuredStorageRoot) return null;
    const logicalId = path.basename(nodeId, path.extname(nodeId));
    const directRelativePaths = [nodeId, path.join("cold", nodeId)];
    let inactiveDirectMemory: MemoryFile | null = null;
    for (const relativePath of directRelativePaths) {
      const safePath = await this.resolveContainedPath(storageRoot, relativePath);
      if (!safePath) continue;
      if (typeof deadlineAtMs === "number" && Date.now() >= deadlineAtMs) return null;
      const memory = await storage.readMemoryByPath(safePath);
      if (!memory || memory.frontmatter.id !== logicalId) continue;
      const inferredStatus = inferMemoryStatus(
        memory.frontmatter,
        toMemoryPathRel(storageRoot, safePath),
      );
      if (inferredStatus === "active") return memory;
      inactiveDirectMemory ??= memory;
    }
    if (inactiveDirectMemory) return inactiveDirectMemory;
    if (!allowArchiveLookup || (typeof deadlineAtMs === "number" && Date.now() >= deadlineAtMs)) {
      return null;
    }
    const archiveIndex = await this.getArchivePathIndex(storage, storageRoot, deadlineAtMs);
    if (
      !archiveIndex ||
      isArchivePathIndexUnavailable(archiveIndex) ||
      (typeof deadlineAtMs === "number" && Date.now() >= deadlineAtMs)
    ) {
      return null;
    }
    const archivePaths = archiveIndex.pathsByBasename.get(path.basename(nodeId)) ?? [];
    for (const archivePath of archivePaths) {
      if (typeof deadlineAtMs === "number" && Date.now() >= deadlineAtMs) return null;
      const memory = await storage.readMemoryByPath(archivePath);
      if (!memory) continue;
      if (memory.frontmatter.id === logicalId) return memory;
    }
    return null;
  }

  private async resolveContainedPath(
    storageRoot: string,
    relativePath: string,
  ): Promise<string | null> {
    if (path.isAbsolute(relativePath)) return null;
    const rawSegments = relativePath.replace(/\\/g, "/").split("/");
    if (rawSegments.includes("..")) return null;
    const candidate = path.resolve(storageRoot, relativePath);
    const lexicalRelative = path.relative(storageRoot, candidate);
    if (
      lexicalRelative.length > 0 &&
      (lexicalRelative.startsWith("..") || path.isAbsolute(lexicalRelative))
    ) {
      return null;
    }
    const canonical = await realpath(candidate).catch(() => candidate);
    const canonicalRelative = path.relative(storageRoot, canonical);
    if (
      canonicalRelative.length > 0 &&
      (canonicalRelative.startsWith("..") || path.isAbsolute(canonicalRelative))
    ) {
      return null;
    }
    return canonical;
  }

  private async getArchivePathIndex(
    storage: StorageManager,
    storageRoot: string,
    deadlineAtMs: number | null | undefined,
  ): Promise<ArchivePathIndexResult | null> {
    if (typeof deadlineAtMs === "number" && Date.now() >= deadlineAtMs) return null;
    if (!this.archivePathIndexes) this.archivePathIndexes = new Map();
    const archivePathIndexes = this.archivePathIndexes;
    let generationRetries = 0;

    while (true) {
      const version = storage.getArchiveMutationVersion();
      if (typeof deadlineAtMs === "number" && Date.now() >= deadlineAtMs) return null;
      const cacheKey = `${storageRoot}\0${version}`;
      const cached = archivePathIndexes.get(cacheKey);
      if (cached) {
        archivePathIndexes.delete(cacheKey);
        archivePathIndexes.set(cacheKey, cached);
        return cached;
      }

      let build = this.archivePathIndexBuilds.get(cacheKey);
      if (!build) {
        if (this.archivePathIndexBuilds.size >= MAX_ARCHIVE_PATH_INDEX_BUILDS) {
          const trackedBuilds = [...this.archivePathIndexBuilds.values()].map((pending) =>
            pending.then(() => undefined, () => undefined)
          );
          const admitted = await this.waitForDeadline(Promise.race(trackedBuilds), deadlineAtMs);
          if (admitted === null) return null;
          continue;
        }
        build = this.buildArchivePathIndex(storageRoot, version)
          .then((index) => {
            if (!index) return null;
            if (storage.getArchiveMutationVersion() !== version) return null;
            const rootPrefix = `${storageRoot}\0`;
            for (const key of archivePathIndexes.keys()) {
              if (key.startsWith(rootPrefix)) archivePathIndexes.delete(key);
            }
            archivePathIndexes.set(cacheKey, index);
            while (archivePathIndexes.size > MAX_ARCHIVE_PATH_INDEXES) {
              const oldestKey = archivePathIndexes.keys().next().value;
              if (oldestKey === undefined) break;
              archivePathIndexes.delete(oldestKey);
            }
            return index;
          })
          .finally(() => {
            this.archivePathIndexBuilds.delete(cacheKey);
          });
        this.archivePathIndexBuilds.set(cacheKey, build);
      }
      const index = await this.waitForDeadline(build, deadlineAtMs);
      if (typeof deadlineAtMs === "number" && Date.now() >= deadlineAtMs) return null;
      const currentVersion = storage.getArchiveMutationVersion();
      if (index && currentVersion === version) return index;
      if (index && currentVersion !== version) archivePathIndexes.delete(cacheKey);
      if (currentVersion === version) return null;
      if (generationRetries >= MAX_ARCHIVE_PATH_INDEX_GENERATION_RETRIES) return null;
      generationRetries += 1;
    }
  }

  private async waitForDeadline<T>(
    promise: Promise<T>,
    deadlineAtMs: number | null | undefined,
  ): Promise<T | null> {
    if (typeof deadlineAtMs !== "number") return promise;
    const remainingMs = deadlineAtMs - Date.now();
    if (remainingMs <= 0) return null;
    const timeout = Promise.withResolvers<null>();
    const timer = setTimeout(() => timeout.resolve(null), remainingMs);
    try {
      return await Promise.race([promise, timeout.promise]);
    } finally {
      clearTimeout(timer);
    }
  }

  private async buildArchivePathIndex(
    storageRoot: string,
    version: number,
  ): Promise<ArchivePathIndexResult | null> {
    const pathsByBasename = new Map<string, string[]>();
    const archiveRoot = path.join(storageRoot, "archive");
    let archiveRootStatus: Stats;
    try {
      archiveRootStatus = await this.archiveLstat(archiveRoot);
    } catch (error) {
      if (isArchiveScanAbsenceError(error)) return { version, pathsByBasename };
      return null;
    }
    if (
      !archiveRootStatus ||
      !archiveRootStatus.isDirectory() ||
      archiveRootStatus.isSymbolicLink()
    ) {
      return { version, pathsByBasename };
    }
    let canonicalArchiveRoot: string;
    try {
      canonicalArchiveRoot = await this.archiveRealpath(archiveRoot);
    } catch (error) {
      if (isArchiveScanAbsenceError(error)) return { version, pathsByBasename };
      return null;
    }
    const archiveRelative = path.relative(storageRoot, canonicalArchiveRoot);
    if (
      archiveRelative.length > 0 &&
      (archiveRelative.startsWith("..") || path.isAbsolute(archiveRelative))
    ) {
      return { version, pathsByBasename };
    }
    const pending = [canonicalArchiveRoot];
    let indexedPathCount = 0;
    let visitedEntryCount = 1;
    while (pending.length > 0) {
      const current = pending.pop();
      if (!current) break;
      let currentStatus: Stats;
      try {
        currentStatus = await this.archiveLstat(current);
      } catch (error) {
        if (isArchiveScanAbsenceError(error)) continue;
        return null;
      }
      if (
        !currentStatus ||
        !currentStatus.isDirectory() ||
        currentStatus.isSymbolicLink()
      ) {
        continue;
      }
      let canonicalCurrent: string;
      try {
        canonicalCurrent = await this.archiveRealpath(current);
      } catch (error) {
        if (isArchiveScanAbsenceError(error)) continue;
        return null;
      }
      const currentRelative = path.relative(storageRoot, canonicalCurrent);
      if (
        currentRelative.length > 0 &&
        (currentRelative.startsWith("..") || path.isAbsolute(currentRelative))
      ) {
        continue;
      }
      let directory: Dir;
      try {
        directory = await this.openArchiveDirectory(canonicalCurrent);
      } catch (error) {
        if (isArchiveScanAbsenceError(error)) continue;
        return null;
      }
      try {
        for await (const entry of directory) {
          visitedEntryCount += 1;
          if (visitedEntryCount > MAX_ARCHIVE_INDEX_ENTRIES) {
            return { version, unavailable: "oversized" };
          }
          if (entry.isSymbolicLink()) continue;
          const entryPath = path.join(canonicalCurrent, entry.name);
          if (entry.isDirectory()) {
            pending.push(entryPath);
            continue;
          }
          if (!entry.isFile() || !entry.name.endsWith(".md")) continue;
          if (indexedPathCount >= MAX_ARCHIVE_INDEX_ENTRIES) {
            return { version, unavailable: "oversized" };
          }
          let canonical: string;
          try {
            canonical = await this.archiveRealpath(entryPath);
          } catch (error) {
            if (isArchiveScanAbsenceError(error)) continue;
            return null;
          }
          const relative = path.relative(storageRoot, canonical);
          if (
            relative.length > 0 &&
            (relative.startsWith("..") || path.isAbsolute(relative))
          ) {
            continue;
          }
          const paths = pathsByBasename.get(entry.name);
          if (paths) paths.push(canonical);
          else pathsByBasename.set(entry.name, [canonical]);
          indexedPathCount += 1;
        }
      } catch {
        return null;
      }
    }
    for (const paths of pathsByBasename.values()) {
      paths.sort((left, right) => {
        const normalizedLeft = left.normalize("NFC");
        const normalizedRight = right.normalize("NFC");
        return normalizedRight < normalizedLeft
          ? -1
          : normalizedRight > normalizedLeft
            ? 1
            : 0;
      });
    }
    return { version, pathsByBasename };
  }
}

/**
 * `remnic connectors` CLI helpers (issue #683 PR 6/N).
 *
 * Three subcommands:
 *
 *   remnic connectors list
 *     Lists all configured live connectors, their enabled state, last poll
 *     time, and last error.  Output formats: text (default), markdown, json.
 *
 *   remnic connectors status
 *     Identical data to `list` but defaults to JSON output so scripts can
 *     reliably parse it.  Accepts `--format` to override.
 *
 *   remnic connectors run <name>
 *     Manually triggers a single `syncIncremental()` pass for the named
 *     connector.  Operator debug surface — useful when you want to test
 *     credentials without waiting for the scheduler tick.  Prints the
 *     number of new documents imported plus any error.
 *
 * Design decisions:
 *
 *   - Pure functions for list / status / run option parsing so they can be
 *     unit-tested without booting an orchestrator (CLAUDE.md rules 14 + 51).
 *   - Rendering lives here (not in cli.ts) so HTTP/MCP surfaces can reuse the
 *     same output without forking formatting (CLAUDE.md rule 22).
 *   - The `run` command requires the caller to pass a `pollFn` callback
 *     (wrapping the actual connector's `syncIncremental`).  This keeps the
 *     helper module free of direct orchestrator / live-connector imports while
 *     still being testable (CLAUDE.md rule 33 — mock signatures must match
 *     production).
 *   - CLAUDE.md rule 51: invalid `--format` throws with listed options; unknown
 *     connector name in `run` throws a descriptive error; `--format` without a
 *     value is caught by Commander's built-in argument check.
 *   - `runConnectorPollOnce` encapsulates the persist-before-cursor-advance
 *     contract (CLAUDE.md gotcha #25, #43) so it can be unit-tested in
 *     isolation without an orchestrator.
 */

import {
  type ConnectorCursor,
  type ConnectorDocument,
  type ConnectorState,
  type ConnectorSyncStatus,
} from "./connectors/live/index.js";

// ─────────────────────────────────────────────────────────────────────────────
// Types that cross the module boundary
// ─────────────────────────────────────────────────────────────────────────────

/**
 * A lightweight descriptor for one live connector, assembled from the parsed
 * config and any persisted state.  The CLI handler builds this from
 * `orchestrator.config.connectors` + `listConnectorStates(memoryDir)`.
 */
export interface ConnectorRow {
  /** Stable connector id (e.g. `"google-drive"`, `"notion"`). */
  id: string;
  /** Human-readable display name. */
  displayName: string;
  /** Whether the operator has enabled this connector in config. */
  enabled: boolean;
  /** Persisted sync state, or `null` if no sync has ever run. */
  state: ConnectorState | null;
}

export interface ConnectorRowDefinition {
  id: string;
  displayName: string;
  enabled: boolean;
}

export function buildConnectorRowsFromDefinitions(
  definitions: readonly ConnectorRowDefinition[],
  states: readonly ConnectorState[],
): ConnectorRow[] {
  const stateMap = new Map(states.map((state) => [state.id, state]));
  return definitions.map((definition) => ({
    id: definition.id,
    displayName: definition.displayName,
    enabled: definition.enabled,
    state: stateMap.get(definition.id) ?? null,
  }));
}

/**
 * Result returned by the `run` command's poll function.
 */
export interface ConnectorRunResult {
  /** Number of new documents imported in this pass. */
  docsImported: number;
  /**
   * Error message if the sync or ingest failed, undefined on full success.
   * When only the cursor write failed after a successful ingest, this field is
   * undefined and `stateWriteError` carries the failure. When persisting error
   * state fails after a sync/ingest error, both fields are set so callers can
   * preserve the primary failure while also reporting stale persisted state.
   */
  error?: string;
  /**
   * Set when cursor/error-state persistence fails. On the success path,
   * `docsImported` reflects the actual count of successfully ingested docs so
   * the operator knows data was persisted even though the cursor did not
   * advance. On the error path, `error` preserves the primary sync/ingest
   * failure and this field reports the secondary persistence failure.
   */
  stateWriteError?: string;
}

// ─────────────────────────────────────────────────────────────────────────────
// Output formats
// ─────────────────────────────────────────────────────────────────────────────

export const CONNECTORS_OUTPUT_FORMATS = ["text", "markdown", "json"] as const;
export type ConnectorsOutputFormat = (typeof CONNECTORS_OUTPUT_FORMATS)[number];

/**
 * Validate `--format <fmt>`.  Throws a listed-options error for any value not
 * in `CONNECTORS_OUTPUT_FORMATS`.  Returns the given default when the value is
 * `undefined` (no flag supplied).
 */
export function parseConnectorsFormat(
  value: unknown,
  defaultFormat: ConnectorsOutputFormat = "text",
): ConnectorsOutputFormat {
  if (value === undefined || value === null) return defaultFormat;
  if (
    typeof value !== "string" ||
    !(CONNECTORS_OUTPUT_FORMATS as readonly string[]).includes(value)
  ) {
    throw new Error(
      `--format expects one of ${CONNECTORS_OUTPUT_FORMATS.join(", ")}; got ${JSON.stringify(value)}`,
    );
  }
  return value as ConnectorsOutputFormat;
}

// ─────────────────────────────────────────────────────────────────────────────
// Parsed option types
// ─────────────────────────────────────────────────────────────────────────────

export interface ParsedConnectorsListOptions {
  format: ConnectorsOutputFormat;
}

export interface ParsedConnectorsStatusOptions {
  /** `status` defaults to JSON for scripting; `--format` can override. */
  format: ConnectorsOutputFormat;
}

// ─────────────────────────────────────────────────────────────────────────────
// Option parsers (pure, unit-testable)
// ─────────────────────────────────────────────────────────────────────────────

/**
 * Validate the option bag for `remnic connectors list`.
 */
export function parseConnectorsListOptions(
  options: Record<string, unknown>,
): ParsedConnectorsListOptions {
  return {
    format: parseConnectorsFormat(options.format, "text"),
  };
}

/**
 * Validate the option bag for `remnic connectors status`.
 * Defaults to `json` (machine-readable) unless `--format` overrides.
 */
export function parseConnectorsStatusOptions(
  options: Record<string, unknown>,
): ParsedConnectorsStatusOptions {
  return {
    format: parseConnectorsFormat(options.format, "json"),
  };
}

/**
 * Validate the positional `<name>` argument for `remnic connectors run`.
 */
export function parseConnectorsRunName(rawName: unknown): string {
  if (typeof rawName !== "string" || rawName.trim().length === 0) {
    throw new Error(
      "connectors run: <name> is required and must be a non-empty connector id",
    );
  }
  return rawName.trim();
}

// ─────────────────────────────────────────────────────────────────────────────
// Formatters: shared helpers
// ─────────────────────────────────────────────────────────────────────────────

/**
 * Human-readable summary of `ConnectorSyncStatus`.
 *
 * Does NOT fold in the enabled/disabled state — the text and markdown
 * renderers already display that separately.  Mixing them produced
 * "state: disabled, disabled" when `enabled=false` and `status="never"`.
 */
function statusLabel(status: ConnectorSyncStatus): string {
  switch (status) {
    case "never":
      return "never synced";
    case "success":
      return "ok";
    case "error":
      return "error";
    default:
      return status;
  }
}

/**
 * Format a UTC ISO timestamp for display.  If the value is `null` / `undefined`
 * returns the given fallback string.
 */
function fmtTimestamp(value: string | null | undefined, fallback = "—"): string {
  if (!value) return fallback;
  return value;
}

// ─────────────────────────────────────────────────────────────────────────────
// Renderers
// ─────────────────────────────────────────────────────────────────────────────

/**
 * Render connector rows for `remnic connectors list` / `remnic connectors status`.
 */
export function renderConnectorsList(
  rows: readonly ConnectorRow[],
  format: ConnectorsOutputFormat,
): string {
  if (format === "json") {
    const out = rows.map((row) => ({
      id: row.id,
      displayName: row.displayName,
      enabled: row.enabled,
      lastSyncAt: row.state?.lastSyncAt ?? null,
      lastSyncStatus: row.state?.lastSyncStatus ?? "never",
      lastSyncError: row.state?.lastSyncError ?? null,
      totalDocsImported: row.state?.totalDocsImported ?? 0,
      updatedAt: row.state?.updatedAt ?? null,
    }));
    return JSON.stringify(out, null, 2);
  }

  if (rows.length === 0) {
    if (format === "markdown") {
      return "# Live connectors\n\n_No live connectors are configured._\n";
    }
    return "No live connectors configured.";
  }

  if (format === "markdown") {
    const lines: string[] = ["# Live connectors", ""];
    lines.push("| ID | Display name | Enabled | Last poll | Docs imported | Status |");
    lines.push("| --- | --- | --- | --- | --- | --- |");
    for (const row of rows) {
      const lastPoll = fmtTimestamp(row.state?.lastSyncAt);
      const docs = row.state?.totalDocsImported ?? 0;
      const status = statusLabel(row.state?.lastSyncStatus ?? "never");
      lines.push(
        `| \`${row.id}\` | ${row.displayName} | ${row.enabled ? "yes" : "no"} | ${lastPoll} | ${docs} | ${status} |`,
      );
      if (row.state?.lastSyncError) {
        lines.push(
          `| | | | | | _Error: ${escapePipes(row.state.lastSyncError)}_ |`,
        );
      }
    }
    return lines.join("\n") + "\n";
  }

  // text
  const lines: string[] = [`Live connectors (${rows.length}):`];
  lines.push("");
  for (const row of rows) {
    const enabledStr = row.enabled ? "enabled" : "disabled";
    const status = statusLabel(row.state?.lastSyncStatus ?? "never");
    const lastPoll = fmtTimestamp(row.state?.lastSyncAt, "(never polled)");
    const docs = row.state?.totalDocsImported ?? 0;
    lines.push(`  ${row.id}  (${row.displayName})`);
    lines.push(`    state:         ${enabledStr}, ${status}`);
    lines.push(`    last_poll:     ${lastPoll}`);
    lines.push(`    docs_imported: ${docs}`);
    if (row.state?.lastSyncError) {
      lines.push(`    last_error:    ${row.state.lastSyncError}`);
    }
  }
  return lines.join("\n");
}

/**
 * Render the result of a manual `remnic connectors run <name>` invocation.
 */
export function renderConnectorsRunResult(
  connectorId: string,
  result: ConnectorRunResult,
  format: ConnectorsOutputFormat,
): string {
  // A run is "ok" when neither a sync/ingest error nor a state-write error
  // is present.  A partial success (ingest ok, cursor write failed) still
  // surfaces as a non-ok status so the operator knows to investigate.
  const ok = result.error === undefined && result.stateWriteError === undefined;

  if (format === "json") {
    return JSON.stringify(
      {
        connector: connectorId,
        docsImported: result.docsImported,
        error: result.error ?? null,
        stateWriteError: result.stateWriteError ?? null,
        ok,
      },
      null,
      2,
    );
  }

  if (format === "markdown") {
    const lines: string[] = [`# connectors run: \`${connectorId}\``, ""];
    lines.push(`- **Status:** ${ok ? "success" : "error"}`);
    lines.push(`- **Docs imported:** ${result.docsImported}`);
    if (result.error !== undefined) {
      lines.push(`- **Error:** ${result.error}`);
    }
    if (result.stateWriteError !== undefined) {
      const label =
        result.error === undefined
          ? "State-write error (cursor not advanced)"
          : "State-write error (error state not persisted)";
      lines.push(`- **${label}:** ${result.stateWriteError}`);
    }
    return lines.join("\n") + "\n";
  }

  // text
  const lines: string[] = [];
  if (ok) {
    lines.push(`connectors run: ${connectorId} — OK`);
    lines.push(`  docs_imported: ${result.docsImported}`);
  } else {
    lines.push(`connectors run: ${connectorId} — FAILED`);
    lines.push(`  docs_imported: ${result.docsImported}`);
    if (result.error !== undefined) {
      lines.push(`  error:         ${result.error}`);
    }
    if (result.stateWriteError !== undefined) {
      lines.push(
        `  state_write_error: ${result.stateWriteError}`,
      );
      if (result.error === undefined) {
        lines.push(
          result.docsImported > 0
            ? `  (docs were ingested; cursor was not advanced — next poll will re-fetch from prior position)`
            : `  (cursor was not advanced — next poll will retry from prior position)`,
        );
      } else {
        lines.push(
          `  (error state was not persisted — next poll will retry from prior position)`,
        );
      }
    }
  }
  return lines.join("\n");
}

// ─────────────────────────────────────────────────────────────────────────────
// Poll orchestration helper
// ─────────────────────────────────────────────────────────────────────────────

/**
 * Arguments for a single connector poll pass.
 *
 * All I/O is injectable so callers (cli.ts) can supply real implementations
 * and tests can supply lightweight stubs without booting an orchestrator.
 */
export interface RunConnectorPollOnceArgs {
  /** Connector identifier (used in error/success state writes). */
  connectorId: string;
  /** Prior persisted state, or `null` on the very first sync. */
  priorState: ConnectorState | null;
  /**
   * Perform a single incremental sync.  Returns newly-fetched documents and
   * the cursor that should be persisted on success.
   */
  syncFn: (
    cursor: ConnectorCursor | null,
  ) => Promise<{ newDocs: ConnectorDocument[]; nextCursor: ConnectorCursor }>;
  /**
   * Ingest fetched documents into the memory layer.  Called BEFORE the cursor
   * is advanced.  If this throws the cursor is NOT advanced (CLAUDE.md gotcha
   * #25 — don't destroy old state before confirming new state succeeds).
   */
  ingestFn: (docs: ConnectorDocument[]) => Promise<void>;
  /**
   * Persist connector state (cursor + metadata).  Called after `ingestFn`
   * succeeds (success path) or when `syncFn` / `ingestFn` throws (error path,
   * with old cursor retained).
   */
  writeCursorFn: (state: {
    cursor: ConnectorCursor | null;
    lastSyncStatus: ConnectorSyncStatus;
    lastSyncError?: string;
    totalDocsImported: number;
  }) => Promise<void>;
}

/**
 * Execute one `syncIncremental` pass for a live connector, enforcing the
 * persist-before-advance-cursor contract.
 *
 * Invariant (CLAUDE.md gotcha #25 + #43):
 *   1. `syncFn` fetches new docs and a next cursor.
 *   2. `ingestFn` persists the docs into the memory layer.
 *   3. Only if (2) succeeds does `writeCursorFn` advance the cursor.
 *   4. If (1) or (2) throws, `writeCursorFn` is still called but retains the
 *      **prior** cursor so the next poll re-fetches the same window.
 *
 * Returns the `ConnectorRunResult` that `cli.ts` uses for output rendering.
 */
export async function runConnectorPollOnce(
  args: RunConnectorPollOnceArgs,
): Promise<ConnectorRunResult> {
  const { connectorId, priorState, syncFn, ingestFn, writeCursorFn } = args;

  let syncResult: Awaited<ReturnType<typeof syncFn>> | undefined;
  let ingestError: string | undefined;

  // ── Phase 1: fetch ──────────────────────────────────────────────────────────
  try {
    syncResult = await syncFn(priorState?.cursor ?? null);
  } catch (err) {
    const msg = err instanceof Error ? err.message : String(err);
    // syncFn failed — persist error state with the OLD cursor.
    let stateWriteError: string | undefined;
    try {
      await writeCursorFn({
        cursor: priorState?.cursor ?? null,
        lastSyncStatus: "error",
        lastSyncError: msg,
        totalDocsImported: priorState?.totalDocsImported ?? 0,
      });
    } catch (writeErr) {
      stateWriteError = writeErr instanceof Error ? writeErr.message : String(writeErr);
      console.error(
        `[remnic] connectors/${connectorId}: failed to persist error state after syncFn failure (${stateWriteError}); original error: ${msg}`,
      );
    }
    return {
      docsImported: 0,
      error: msg,
      ...(stateWriteError !== undefined ? { stateWriteError } : {}),
    };
  }

  // ── Phase 2: ingest ─────────────────────────────────────────────────────────
  // CRITICAL: ingest docs BEFORE advancing the cursor (CLAUDE.md gotcha #25).
  // If ingestFn throws, write the error state with the OLD cursor so the
  // next poll re-fetches the same document window.
  if (syncResult.newDocs.length > 0) {
    try {
      await ingestFn(syncResult.newDocs);
    } catch (err) {
      ingestError = err instanceof Error ? err.message : String(err);
    }
  }

  if (ingestError !== undefined) {
    // ingestFn failed — persist error state with the OLD cursor.
    let stateWriteError: string | undefined;
    try {
      await writeCursorFn({
        cursor: priorState?.cursor ?? null,
        lastSyncStatus: "error",
        lastSyncError: ingestError,
        totalDocsImported: priorState?.totalDocsImported ?? 0,
      });
    } catch (writeErr) {
      stateWriteError = writeErr instanceof Error ? writeErr.message : String(writeErr);
      // Intentionally not re-throwing: the original ingest error is the
      // actionable failure for the operator.  The state-write failure is
      // secondary and should not replace it in the rendered output.
      // (CLAUDE.md gotcha #13; Codex P2 thread PRRT_kwDORJXyws59sk8K,
      //  Cursor thread PRRT_kwDORJXyws59slAG)
      console.error(
        `[remnic] connectors/${connectorId}: failed to persist error state after ingestFn failure (${stateWriteError}); original error: ${ingestError}`,
      );
    }
    return {
      docsImported: 0,
      error: ingestError,
      ...(stateWriteError !== undefined ? { stateWriteError } : {}),
    };
  }

  // ── Phase 3: advance cursor ─────────────────────────────────────────────────
  // Ingest succeeded — advance the cursor.  If the cursor write fails, the
  // docs ARE already in the memory layer so we must report the actual
  // docsImported count.  Surface the state-write failure as a separate
  // `stateWriteError` field so the operator can diagnose it without
  // confusing it with a sync/ingest failure (Codex P1 thread
  // PRRT_kwDORJXyws59sm76, Cursor thread PRRT_kwDORJXyws59sm_N).
  const docsImported = syncResult.newDocs.length;
  try {
    await writeCursorFn({
      cursor: syncResult.nextCursor,
      lastSyncStatus: "success",
      totalDocsImported: (priorState?.totalDocsImported ?? 0) + docsImported,
    });
  } catch (writeErr) {
    const writeMsg = writeErr instanceof Error ? writeErr.message : String(writeErr);
    // Docs are already ingested — preserve the count so the operator knows
    // data was persisted.  The next poll will re-fetch from the prior cursor
    // position but that only causes duplicate-ingest, not data loss.
    return { docsImported, stateWriteError: writeMsg };
  }

  return { docsImported };
}

