/**
 * Escape characters that would break a Markdown table cell (backslash first,
 * then pipe).  Same pattern as in `patterns-cli.ts`.
 */
function escapePipes(value: string): string {
  return value.replace(/\\/g, "\\\\").replace(/\|/g, "\\|");
}

