function selectProjectionMemories(
  tiers: MemoryFile[][],
): {
  allMemories: MemoryFile[];
  memories: MemoryFile[];
  skippedDuplicateMemories: SkippedDuplicateMemory[];
  skippedBlankIdMemories: SkippedBlankIdMemory[];
} {
  const allMemories = tiers.flat();
  const memories: MemoryFile[] = [];
  const keptById = new Map<string, MemoryFile>();
  const skippedDuplicateMemories: SkippedDuplicateMemory[] = [];
  const skippedBlankIdMemories: SkippedBlankIdMemory[] = [];

  // Tier order is authoritative: hot wins over cold, and cold wins over archive.
  // Paths break ties within a tier so the winner does not depend on readdir order.
  for (const tier of tiers) {
    for (const memory of [...tier].sort((left, right) => left.path.localeCompare(right.path))) {
      const memoryId = memory.frontmatter.id.trim();
      if (!memoryId) {
        skippedBlankIdMemories.push({ path: memory.path });
        log.warn(`projection rebuild skipped blank memory id: path=${memory.path}`);
        continue;
      }
      const kept = keptById.get(memoryId);
      if (kept) {
        skippedDuplicateMemories.push({
          memoryId,
          keptPath: kept.path,
          skippedPath: memory.path,
        });
        log.warn(
          `projection rebuild skipped duplicate memory id=${memoryId}: kept=${kept.path} skipped=${memory.path}`,
        );
        continue;
      }
      keptById.set(memoryId, memory);
      memories.push(memory);
    }
  }

  return { allMemories, memories, skippedDuplicateMemories, skippedBlankIdMemories };
}

async function loadAuthoritativeProjectionSnapshot(options: {
  memoryDir: string;
  defaultNamespace?: string;
  storage?: StorageManager;
  updatedAfter?: string;
  updatedBefore?: string;
  retainRaw?: boolean;
  signal?: AbortSignal;
}): Promise<{
  allMemories: MemoryFile[];
  currentRows: MemoryProjectionCurrentState[];
  timelineRows: MemoryLifecycleEvent[];
  scopedCurrentRows: MemoryProjectionCurrentState[];
  scopedTimelineRows: MemoryLifecycleEvent[];
  entityMentionRows: ProjectedEntityMentionRow[];
  scopedEntityMentionRows: ProjectedEntityMentionRow[];
  nativeKnowledgeRows: ProjectedNativeKnowledgeChunkRow[];
  governance:
    | {
      runId: string;
      summary: unknown;
      metrics: unknown;
      reviewQueueRows: MemoryProjectionGovernanceReviewQueueRow[];
      appliedActionRows: MemoryProjectionGovernanceAppliedActionRow[];
      report: string;
    }
    | null;
  usedLifecycleLedger: boolean;
  sourceLifecycleLedgerEventCount: number;
  scope: {
    updatedAfter: string | null;
    updatedBefore: string | null;
  };
  skippedDuplicateMemories: SkippedDuplicateMemory[];
  skippedBlankIdMemories: SkippedBlankIdMemory[];
  skippedDuplicateTimelineEvents: SkippedDuplicateTimelineEvent[];
  skippedBlankIdTimelineEvents: SkippedBlankIdTimelineEvent[];
}> {
  const storage = assertInjectedStorageRooted("rebuildMemoryProjection", options.memoryDir, options.storage) ?? new StorageManager(options.memoryDir);
  // Force a fresh disk read — projection verify/rebuild must see the true
  // on-disk state, not a potentially stale in-process cache.
  storage.invalidateAllMemoriesCacheForDir({ indexedText: false });
  const corpusRead = {
    retainRaw: options.retainRaw === true,
    abortSignal: options.signal,
  };
  const hot = await storage.readAllMemories(corpusRead);
  await throwIfProjectionRebuildAborted(options.signal);
  const cold = await storage.readAllColdMemories(corpusRead);
  await throwIfProjectionRebuildAborted(options.signal);
  const archived = await storage.readArchivedMemories(corpusRead);
  await throwIfProjectionRebuildAborted(options.signal);
  const selected = selectProjectionMemories([hot, cold, archived]);
  const allMemories = selected.allMemories;
  const projectionMemories = selected.memories;
  const currentRows = projectionMemories.map((memory) => toCurrentStateRow(options.memoryDir, memory));
  // Preview is already a detached copy. Drop the document bodies before the
  // ledger scan so peak heap is the larger of the corpus and the timeline,
  // not both. These objects bypass the shared caches when retainRaw is off,
  // so clearing them cannot strip a raw copy another caller is holding.
  if (options.retainRaw !== true) {
    for (const memory of allMemories) memory.content = "";
  }
  const {
    events,
    usedLifecycleLedger,
    sourceLifecycleLedgerEventCount,
    skipped: skippedDuplicateTimelineEvents,
    skippedBlankIds: skippedBlankIdTimelineEvents,
  } = await loadProjectionTimeline({
    storage,
    memoryDir: options.memoryDir,
    memories: projectionMemories,
    signal: options.signal,
  });
  await throwIfProjectionRebuildAborted(options.signal);
  const scope = normalizeProjectionScope(options);
  const scopedMemories = filterMemoriesForProjectionScope(projectionMemories, scope);
  const scopedMemoryIds = new Set(scopedMemories.map((memory) => memory.frontmatter.id));
  const nativeKnowledgeRows = await loadPersistedNativeKnowledgeChunks({
    memoryDir: options.memoryDir,
    defaultNamespace: options.defaultNamespace ?? "default",
  }).then((rows) => rows.map((row) => ({
    chunkId: row.chunkId,
    sourceKind: row.sourceKind,
    sourcePath: row.sourcePath,
    title: row.title,
    startLine: row.startLine,
    endLine: row.endLine,
    namespace: row.namespace ?? options.defaultNamespace ?? "default",
    privacyClass: row.privacyClass,
    derivedDate: row.derivedDate,
    sessionKey: row.sessionKey,
    workflowKey: row.workflowKey,
    author: row.author,
    agent: row.agent,
    sourceHash: row.sourceHash,
    preview: normalizeProjectionPreview(row.content),
  })));
  const governance = await loadLatestGovernanceProjection(options.memoryDir);
  const entityMentionRows = buildEntityMentionRows(currentRows);

  return {
    allMemories,
    currentRows,
    timelineRows: events,
    scopedCurrentRows: currentRows.filter((row) => scopedMemoryIds.has(row.memoryId)),
    scopedTimelineRows: events.filter((event) => scopedMemoryIds.has(event.memoryId)),
    entityMentionRows,
    scopedEntityMentionRows: entityMentionRows.filter((row) => scopedMemoryIds.has(row.memoryId)),
    nativeKnowledgeRows,
    governance,
    usedLifecycleLedger,
    sourceLifecycleLedgerEventCount,
    scope,
    skippedDuplicateMemories: selected.skippedDuplicateMemories,
    skippedBlankIdMemories: selected.skippedBlankIdMemories,
    skippedDuplicateTimelineEvents,
    skippedBlankIdTimelineEvents,
  };
}

function readProjectedCurrentRows(
  memoryDir: string,
): { projectionExists: boolean; rows: MemoryProjectionCurrentState[] } {
  const dbPath = getMemoryProjectionPath(memoryDir);
  try {
    const db = openBetterSqlite3(dbPath, { readonly: true, fileMustExist: true });
    try {
      const selectExpressions = memoryCurrentSelectExpressions(db);
      const rows = db.prepare(`
        SELECT
          memory_id,
          category,
          status,
          lifecycle_state,
          path_rel,
          created_at,
          updated_at,
          archived_at,
          superseded_at,
          entity_ref,
          source,
          confidence,
          confidence_tier,
          memory_kind,
          access_count,
          last_accessed,
          ${selectExpressions.tagsJson}, ${selectExpressions.previewText}, ${selectExpressions.privateRecord}
        FROM memory_current
      `).all() as Array<Record<string, unknown>>;

      return {
        projectionExists: true,
        rows: rows
          .map((row) => parseCurrentRow(memoryDir, row))
          .filter((row): row is MemoryProjectionCurrentState => row !== null),
      };
    } finally {
      db.close();
    }
  } catch {
    return { projectionExists: false, rows: [] };
  }
}

function readProjectedTimelineRows(
  memoryDir: string,
): { projectionExists: boolean; rows: MemoryLifecycleEvent[] } {
  const dbPath = getMemoryProjectionPath(memoryDir);
  try {
    const db = openBetterSqlite3(dbPath, { readonly: true, fileMustExist: true });
    try {
      const rows = db.prepare(`
        SELECT
          event_id,
          memory_id,
          event_type,
          timestamp,
          actor,
          reason_code,
          rule_version,
          related_memory_ids_json,
          before_json,
          after_json,
          correlation_id
        FROM memory_timeline
      `).all() as Array<Record<string, unknown>>;

      return {
        projectionExists: true,
        rows: parseTimelineRows(rows),
      };
    } finally {
      db.close();
    }
  } catch {
    return { projectionExists: false, rows: [] };
  }
}


function writeProjectionDb(
  dbPath: string,
  nowIso: string,
  currentRows: MemoryProjectionCurrentState[],
  timelineRows: MemoryLifecycleEvent[],
  entityMentionRows: ProjectedEntityMentionRow[],
  nativeKnowledgeRows: ProjectedNativeKnowledgeChunkRow[],
  governance: Awaited<ReturnType<typeof loadLatestGovernanceProjection>>,
  usedLifecycleLedger: boolean,
  sourceLifecycleLedgerEventCount: number,
  complete: boolean,
): void {
  const db = openBetterSqlite3(dbPath);
  const memoryDir = path.dirname(path.dirname(dbPath));
  try {
    initializeMemoryProjectionDb(db);

    const insertMeta = db.prepare("INSERT OR REPLACE INTO meta(key, value) VALUES (?, ?)");
    insertMeta.run("schemaVersion", String(MEMORY_PROJECTION_SCHEMA_VERSION));
    insertMeta.run("rebuiltAt", nowIso);
    insertMeta.run("usedLifecycleLedger", usedLifecycleLedger ? "true" : "false");
    insertMeta.run("complete", complete ? "true" : "false");
    writeProjectionMetaHighWater(insertMeta, sourceLifecycleLedgerEventCount, timelineRows);
    insertMeta.run("latestGovernanceRunId", governance?.runId ?? "");

    const insertCurrent = db.prepare(`
      INSERT INTO memory_current (
        memory_id,
        category,
        status,
        lifecycle_state,
        path_rel,
        path_valid,
        created_at,
        updated_at,
        archived_at,
        superseded_at,
        entity_ref,
        source,
        confidence,
        confidence_tier,
        memory_kind,
        access_count,
        last_accessed,
        tags_json, preview_text, private_record
      ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
    `);

    const insertTimeline = db.prepare(`
      INSERT INTO memory_timeline (
        event_id,
        memory_id,
        event_type,
        timestamp,
        event_order,
        actor,
        reason_code,
        rule_version,
        related_memory_ids_json,
        before_json,
        after_json,
        correlation_id
      ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
    `);

    const insertEntityMention = db.prepare(`
      INSERT INTO memory_entity_mentions (
        memory_id,
        entity_ref,
        mention_source,
        created_at,
        updated_at
      ) VALUES (?, ?, ?, ?, ?)
    `);

    const insertNativeKnowledge = db.prepare(`
      INSERT INTO native_knowledge_chunks (
        chunk_id,
        source_kind,
        source_path,
        title,
        start_line,
        end_line,
        namespace,
        privacy_class,
        derived_date,
        session_key,
        workflow_key,
        author,
        agent,
        source_hash,
        preview_text
      ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
    `);

    const insertGovernanceReviewQueue = db.prepare(`
      INSERT INTO memory_review_queue (
        entry_id,
        run_id,
        memory_id,
        path,
        reason_code,
        severity,
        suggested_action,
        suggested_status,
        related_memory_ids_json
      ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)
    `);

    const insertGovernanceAppliedAction = db.prepare(`
      INSERT INTO memory_review_actions (
        row_key,
        run_id,
        action,
        memory_id,
        reason_code,
        before_status,
        after_status,
        original_path,
        current_path
      ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)
    `);

    const insertGovernanceRun = db.prepare(`
      INSERT INTO memory_review_runs (
        run_id,
        created_at,
        mode,
        summary_json,
        metrics_json,
        applied_actions_json,
        report_markdown
      ) VALUES (?, ?, ?, ?, ?, ?, ?)
    `);

    const writeTx = db.transaction(() => {
      for (const row of currentRows) {
        insertCurrent.run(
          row.memoryId,
          row.category,
          row.status,
          row.lifecycleState ?? null,
          row.pathRel,
          isProjectedMemoryPathValid(memoryDir, row.pathRel) ? 1 : 0,
          row.created,
          row.updated,
          row.archivedAt ?? null,
          row.supersededAt ?? null,
          row.entityRef ?? null,
          row.source,
          row.confidence,
          row.confidenceTier,
          row.memoryKind ?? null,
          row.accessCount ?? null,
          row.lastAccessed ?? null, JSON.stringify(row.tags ?? []), row.preview ?? "",
          row.privateRecord === true ? 1 : 0,
        );
      }

      for (const event of timelineRows) {
        insertTimeline.run(
          event.eventId,
          event.memoryId,
          event.eventType,
          event.timestamp,
          MEMORY_LIFECYCLE_EVENT_SORT_ORDER[event.eventType],
          event.actor,
          event.reasonCode ?? null,
          event.ruleVersion,
          JSON.stringify(event.relatedMemoryIds ?? []),
          event.before ? JSON.stringify(event.before) : null,
          event.after ? JSON.stringify(event.after) : null,
          event.correlationId ?? null,
        );
      }

      for (const row of entityMentionRows) {
        insertEntityMention.run(
          row.memoryId,
          row.entityRef,
          row.mentionSource,
          row.created,
          row.updated,
        );
      }

      for (const row of nativeKnowledgeRows) {
        insertNativeKnowledge.run(
          row.chunkId,
          row.sourceKind,
          row.sourcePath,
          row.title,
          row.startLine,
          row.endLine,
          row.namespace ?? null,
          row.privacyClass ?? null,
          row.derivedDate ?? null,
          row.sessionKey ?? null,
          row.workflowKey ?? null,
          row.author ?? null,
          row.agent ?? null,
          row.sourceHash ?? null,
          row.preview,
        );
      }

      for (const row of governance?.reviewQueueRows ?? []) {
        insertGovernanceReviewQueue.run(
          row.entryId,
          row.runId,
          row.memoryId,
          row.path,
          row.reasonCode,
          row.severity,
          row.suggestedAction,
          row.suggestedStatus ?? null,
          JSON.stringify(row.relatedMemoryIds),
        );
      }

      for (const row of governance?.appliedActionRows ?? []) {
        insertGovernanceAppliedAction.run(
          row.rowKey,
          row.runId,
          row.action,
          row.memoryId,
          row.reasonCode,
          row.beforeStatus,
          row.afterStatus ?? null,
          row.originalPath,
          row.currentPath,
        );
      }

      if (governance) {
        const createdAt =
          typeof (governance.summary as { createdAt?: unknown } | undefined)?.createdAt === "string"
            ? (governance.summary as { createdAt: string }).createdAt
            : nowIso;
        const mode =
          typeof (governance.summary as { mode?: unknown } | undefined)?.mode === "string"
            ? (governance.summary as { mode: string }).mode
            : "shadow";
        insertGovernanceRun.run(
          governance.runId,
          createdAt,
          mode,
          JSON.stringify(governance.summary ?? null),
          JSON.stringify(governance.metrics ?? null),
          JSON.stringify(
            (governance.appliedActionRows ?? []).map((row) => ({
              action: row.action,
              memoryId: row.memoryId,
              reasonCode: row.reasonCode,
              beforeStatus: row.beforeStatus,
              afterStatus: row.afterStatus,
              originalPath: row.originalPath,
              currentPath: row.currentPath,
            })),
          ),
          governance.report,
        );
      }
    });

    writeTx();
  } finally {
    db.close();
  }
}

function mergeScopedCurrentRows(
  existingRows: MemoryProjectionCurrentState[],
  replacementRows: MemoryProjectionCurrentState[],
  scopedMemoryIds: Set<string>,
): MemoryProjectionCurrentState[] {
  return [...existingRows.filter((row) => !scopedMemoryIds.has(row.memoryId)), ...replacementRows]
    .sort((a, b) => a.memoryId.localeCompare(b.memoryId));
}

function mergeScopedTimelineRows(
  existingRows: MemoryLifecycleEvent[],
  replacementRows: MemoryLifecycleEvent[],
  scopedMemoryIds: Set<string>,
): MemoryLifecycleEvent[] {
  return sortMemoryLifecycleEvents([
    ...existingRows.filter((event) => !scopedMemoryIds.has(event.memoryId)),
    ...replacementRows,
  ]);
}

function mergeScopedEntityMentionRows(
  existingRows: ProjectedEntityMentionRow[],
  replacementRows: ProjectedEntityMentionRow[],
  scopedMemoryIds: Set<string>,
): ProjectedEntityMentionRow[] {
  return [
    ...existingRows.filter((row) => !scopedMemoryIds.has(row.memoryId)),
    ...replacementRows,
  ].sort((left, right) =>
    [left.entityRef, left.memoryId, left.mentionSource].join("::").localeCompare(
      [right.entityRef, right.memoryId, right.mentionSource].join("::"),
    )
  );
}

export async function rebuildMemoryProjection(
  options: RebuildMemoryProjectionOptions,
): Promise<RebuildMemoryProjectionResult> {
  const dryRun = options.dryRun !== false;
  const now = options.now ?? new Date();
  const outputPath = getMemoryProjectionPath(options.memoryDir);
  const snapshot = await loadAuthoritativeProjectionSnapshot(options);
  await throwIfProjectionRebuildAborted(options.signal);

  let backupPath: string | undefined;
  if (!dryRun) {
    let nextCurrentRows = snapshot.currentRows;
    let nextTimelineRows = snapshot.timelineRows;
    let nextEntityMentionRows = snapshot.entityMentionRows;
    let nextNativeKnowledgeRows = snapshot.nativeKnowledgeRows;
    let nextGovernance = snapshot.governance;
    if (hasScopedProjectionFilter(snapshot.scope)) {
      nextCurrentRows = snapshot.scopedCurrentRows;
      nextTimelineRows = snapshot.scopedTimelineRows;
      nextEntityMentionRows = snapshot.scopedEntityMentionRows;
      const projectedCurrent = readProjectedCurrentRows(options.memoryDir);
      const projectedTimeline = readProjectedTimelineRows(options.memoryDir);
      const projectedEntityMentions = readProjectedEntityMentionRows(options.memoryDir);
      const projectedNativeKnowledge = readProjectedNativeKnowledgeRows(options.memoryDir);
      const projectedGovernance = readProjectedGovernanceRows(options.memoryDir);
      if (projectedCurrent.projectionExists && projectedTimeline.projectionExists) {
        const actualScopedCurrentRows = filterCurrentStateRowsForProjectionScope(
          projectedCurrent.rows,
          snapshot.scope,
        );
        const scopedMemoryIds = new Set([
          ...snapshot.scopedCurrentRows.map((row) => row.memoryId),
          ...snapshot.scopedTimelineRows.map((event) => event.memoryId),
          ...actualScopedCurrentRows.map((row) => row.memoryId),
        ]);
        nextCurrentRows = mergeScopedCurrentRows(
          projectedCurrent.rows,
          snapshot.scopedCurrentRows,
          scopedMemoryIds,
        );
        nextTimelineRows = mergeScopedTimelineRows(
          projectedTimeline.rows,
          snapshot.scopedTimelineRows,
          scopedMemoryIds,
        );
        nextEntityMentionRows = mergeScopedEntityMentionRows(
          projectedEntityMentions.rows,
          snapshot.scopedEntityMentionRows,
          scopedMemoryIds,
        );
      }
      if (projectedNativeKnowledge.projectionExists) {
        // Native knowledge rows are always loaded from the full persisted sync state,
        // so scoped memory rebuilds should publish the fresh snapshot instead of
        // pinning the projection to stale previously projected rows.
        nextNativeKnowledgeRows = snapshot.nativeKnowledgeRows;
      }
      if (projectedGovernance.projectionExists && projectedGovernance.runId) {
        // Governance rows are also sourced from standalone artifact snapshots, so
        // scoped memory rebuilds should keep the latest governance artifact data
        // instead of restoring whatever happened to be in the prior projection.
        nextGovernance = snapshot.governance;
      }
    }

    const tempPath = `${outputPath}.tmp`;
    await mkdir(path.dirname(outputPath), { recursive: true });
    await throwIfProjectionRebuildAborted(options.signal);
    await rm(tempPath, { force: true });
    writeProjectionDb(
      tempPath,
      now.toISOString(),
      nextCurrentRows,
      nextTimelineRows,
      nextEntityMentionRows,
      nextNativeKnowledgeRows,
      nextGovernance,
      snapshot.usedLifecycleLedger,
      snapshot.sourceLifecycleLedgerEventCount,
      !hasScopedProjectionFilter(snapshot.scope),
    );
    try {
      await throwIfProjectionRebuildAborted(options.signal);
      backupPath = await backupExistingProjection(options.memoryDir, outputPath, now);
      await throwIfProjectionRebuildAborted(options.signal);
      backupPath = await commitPreparedFileAtomically(
        tempPath,
        outputPath,
        backupPath,
        () => throwIfProjectionRebuildAborted(options.signal),
      );
    } catch (err) {
      if (options.signal?.aborted) await rm(tempPath, { force: true });
      throw err;
    }
  }

  return {
    dryRun,
    scannedMemories: snapshot.allMemories.length,
    currentRows: snapshot.scopedCurrentRows.length,
    timelineRows: snapshot.scopedTimelineRows.length,
    entityMentionRows: snapshot.scopedEntityMentionRows.length,
    nativeKnowledgeRows: snapshot.nativeKnowledgeRows.length,
    reviewQueueRows: snapshot.governance?.reviewQueueRows.length ?? 0,
    outputPath,
    backupPath,
    usedLifecycleLedger: snapshot.usedLifecycleLedger,
    skippedDuplicateMemories: snapshot.skippedDuplicateMemories,
    skippedBlankIdMemories: snapshot.skippedBlankIdMemories,
    skippedDuplicateTimelineEvents: snapshot.skippedDuplicateTimelineEvents,
    skippedBlankIdTimelineEvents: snapshot.skippedBlankIdTimelineEvents,
    scope: snapshot.scope,
  };
}

export async function verifyMemoryProjection(
  options: VerifyMemoryProjectionOptions,
): Promise<VerifyMemoryProjectionResult> {
  const outputPath = getMemoryProjectionPath(options.memoryDir);
  const snapshot = await loadAuthoritativeProjectionSnapshot(options);
  const projectedCurrent = readProjectedCurrentRows(options.memoryDir);
  const projectedTimeline = readProjectedTimelineRows(options.memoryDir);
  const projectedEntityMentions = readProjectedEntityMentionRows(options.memoryDir);
  const projectedNativeKnowledge = readProjectedNativeKnowledgeRows(options.memoryDir);
  const projectedGovernance = readProjectedGovernanceRows(options.memoryDir);
  const projectionExists = projectedCurrent.projectionExists
    || projectedTimeline.projectionExists
    || projectedEntityMentions.projectionExists
    || projectedNativeKnowledge.projectionExists
    || projectedGovernance.projectionExists;

  const actualScopedCurrentRows = filterCurrentStateRowsForProjectionScope(projectedCurrent.rows, snapshot.scope);
  const expectedCurrentById = new Map(
    snapshot.scopedCurrentRows.map((row) => [row.memoryId, serializeCurrentStateRow(row)]),
  );
  const actualCurrentById = new Map(
    actualScopedCurrentRows.map((row) => [row.memoryId, serializeCurrentStateRow(row)]),
  );

  const missingCurrentMemoryIds = [...expectedCurrentById.keys()]
    .filter((memoryId) => !actualCurrentById.has(memoryId))
    .sort();
  const extraCurrentMemoryIds = [...actualCurrentById.keys()]
    .filter((memoryId) => !expectedCurrentById.has(memoryId))
    .sort();
  const mismatchedCurrentMemoryIds = [...expectedCurrentById.keys()]
    .filter((memoryId) =>
      actualCurrentById.has(memoryId) && actualCurrentById.get(memoryId) !== expectedCurrentById.get(memoryId)
    )
    .sort();

  const selectedMemoryIds = new Set([
    ...snapshot.scopedCurrentRows.map((row) => row.memoryId),
    ...actualScopedCurrentRows.map((row) => row.memoryId),
  ]);
  const expectedTimelineById = new Map(
    snapshot.scopedTimelineRows.map((event) => [event.eventId, serializeTimelineEvent(event)]),
  );
  const actualTimelineRows = projectedTimeline.rows.filter((event) => selectedMemoryIds.has(event.memoryId));
  const actualTimelineById = new Map(
    actualTimelineRows.map((event) => [event.eventId, serializeTimelineEvent(event)]),
  );
  const missingTimelineEventIds = [...expectedTimelineById.keys()]
    .filter((eventId) => !actualTimelineById.has(eventId))
    .sort();
  const extraTimelineEventIds = [...actualTimelineById.keys()]
    .filter((eventId) => !expectedTimelineById.has(eventId))
    .sort();

  const expectedEntityMentionsByKey = new Map(
    snapshot.scopedEntityMentionRows.map((row) => [
      `${row.memoryId}::${row.entityRef}::${row.mentionSource}`,
      serializeEntityMentionRow(row),
    ]),
  );
  const actualScopedEntityMentionRows = projectedEntityMentions.rows.filter((row) => selectedMemoryIds.has(row.memoryId));
  const actualEntityMentionsByKey = new Map(
    actualScopedEntityMentionRows.map((row) => [
      `${row.memoryId}::${row.entityRef}::${row.mentionSource}`,
      serializeEntityMentionRow(row),
    ]),
  );
  const missingEntityMentionKeys = [...expectedEntityMentionsByKey.keys()]
    .filter((key) => !actualEntityMentionsByKey.has(key))
    .sort();
  const extraEntityMentionKeys = [...actualEntityMentionsByKey.keys()]
    .filter((key) => !expectedEntityMentionsByKey.has(key))
    .sort();
  const mismatchedEntityMentionKeys = [...expectedEntityMentionsByKey.keys()]
    .filter((key) =>
      actualEntityMentionsByKey.has(key) && actualEntityMentionsByKey.get(key) !== expectedEntityMentionsByKey.get(key)
    )
    .sort();

  const expectedNativeKnowledgeById = new Map(
    snapshot.nativeKnowledgeRows.map((row) => [row.chunkId, serializeNativeKnowledgeRow(row)]),
  );
  const actualNativeKnowledgeById = new Map(
    projectedNativeKnowledge.rows.map((row) => [row.chunkId, serializeNativeKnowledgeRow(row)]),
  );
  const missingNativeKnowledgeChunkIds = [...expectedNativeKnowledgeById.keys()]
    .filter((chunkId) => !actualNativeKnowledgeById.has(chunkId))
    .sort();
  const extraNativeKnowledgeChunkIds = [...actualNativeKnowledgeById.keys()]
    .filter((chunkId) => !expectedNativeKnowledgeById.has(chunkId))
    .sort();
  const mismatchedNativeKnowledgeChunkIds = [...expectedNativeKnowledgeById.keys()]
    .filter((chunkId) =>
      actualNativeKnowledgeById.has(chunkId) && actualNativeKnowledgeById.get(chunkId) !== expectedNativeKnowledgeById.get(chunkId)
    )
    .sort();

  const expectedReviewQueueById = new Map(
    (snapshot.governance?.reviewQueueRows ?? []).map((row) => [
      `${row.runId}::${row.entryId}`,
      serializeGovernanceReviewQueueRow(row),
    ]),
  );
  const actualReviewQueueById = new Map(
    projectedGovernance.reviewQueueRows.map((row) => [
      `${row.runId}::${row.entryId}`,
      serializeGovernanceReviewQueueRow(row),
    ]),
  );
  const missingReviewQueueEntryIds = [...expectedReviewQueueById.keys()]
    .filter((entryId) => !actualReviewQueueById.has(entryId))
    .sort();
  const extraReviewQueueEntryIds = [...actualReviewQueueById.keys()]
    .filter((entryId) => !expectedReviewQueueById.has(entryId))
    .sort();
  const mismatchedReviewQueueEntryIds = [...expectedReviewQueueById.keys()]
    .filter((entryId) =>
      actualReviewQueueById.has(entryId) && actualReviewQueueById.get(entryId) !== expectedReviewQueueById.get(entryId)
    )
    .sort();

  return {
    outputPath,
    projectionExists,
    ok:
      projectionExists &&
      missingCurrentMemoryIds.length === 0 &&
      extraCurrentMemoryIds.length === 0 &&
      mismatchedCurrentMemoryIds.length === 0 &&
      missingTimelineEventIds.length === 0 &&
      extraTimelineEventIds.length === 0 &&
      missingEntityMentionKeys.length === 0 &&
      extraEntityMentionKeys.length === 0 &&
      mismatchedEntityMentionKeys.length === 0 &&
      missingNativeKnowledgeChunkIds.length === 0 &&
      extraNativeKnowledgeChunkIds.length === 0 &&
      mismatchedNativeKnowledgeChunkIds.length === 0 &&
      missingReviewQueueEntryIds.length === 0 &&
      extraReviewQueueEntryIds.length === 0 &&
      mismatchedReviewQueueEntryIds.length === 0,
    expectedCurrentRows: snapshot.scopedCurrentRows.length,
    actualCurrentRows: actualScopedCurrentRows.length,
    expectedTimelineRows: snapshot.scopedTimelineRows.length,
    actualTimelineRows: actualTimelineRows.length,
    expectedEntityMentionRows: snapshot.scopedEntityMentionRows.length,
    actualEntityMentionRows: actualScopedEntityMentionRows.length,
    expectedNativeKnowledgeRows: snapshot.nativeKnowledgeRows.length,
    actualNativeKnowledgeRows: projectedNativeKnowledge.rows.length,
    expectedReviewQueueRows: snapshot.governance?.reviewQueueRows.length ?? 0,
    actualReviewQueueRows: projectedGovernance.reviewQueueRows.length,
    missingCurrentMemoryIds,
    extraCurrentMemoryIds,
    mismatchedCurrentMemoryIds,
    missingTimelineEventIds,
    extraTimelineEventIds,
    missingEntityMentionKeys,
    extraEntityMentionKeys,
    mismatchedEntityMentionKeys,
    missingNativeKnowledgeChunkIds,
    extraNativeKnowledgeChunkIds,
    mismatchedNativeKnowledgeChunkIds,
    missingReviewQueueEntryIds,
    extraReviewQueueEntryIds,
    mismatchedReviewQueueEntryIds,
    usedLifecycleLedger: snapshot.usedLifecycleLedger,
    scope: snapshot.scope,
  };
}

export async function repairMemoryProjection(
  options: RepairMemoryProjectionOptions,
): Promise<RepairMemoryProjectionResult> {
  const dryRun = options.dryRun !== false;
  const verify = await verifyMemoryProjection(options);
  if (verify.ok) {
    return {
      dryRun,
      repaired: false,
      verify,
    };
  }
  if (dryRun) {
    return {
      dryRun: true,
      repaired: false,
      verify,
    };
  }

  const rebuild = await rebuildMemoryProjection({
    ...options,
    dryRun: false,
  });
  const verified = await verifyMemoryProjection(options);
  return {
    dryRun: false,
    repaired: verified.ok,
    verify: verified,
    rebuild,
  };
}

export type HostEmbeddingInputType =
  | "query"
  | "document"
  | "semantic"
  | "classification"
  | "clustering";

export interface HostEmbeddingProvider {
  id: string;
  model?: string;
  dimensions?: number;
  embed(
    text: string,
    options?: { signal?: AbortSignal; inputType?: HostEmbeddingInputType },
  ): Promise<ArrayLike<number> | null>;
  embedBatch?(
    texts: string[],
    options?: { signal?: AbortSignal; inputType?: HostEmbeddingInputType },
  ): Promise<Array<ArrayLike<number> | null>>;
  close?: () => Promise<void> | void;
}

const HOST_EMBEDDING_PROVIDERS_KEY = Symbol.for(
  "remnic.hostEmbeddingProviders",
);

function providerMap(): Map<string, HostEmbeddingProvider> {
  const store = globalThis as Record<PropertyKey, unknown>;
  const existing = store[HOST_EMBEDDING_PROVIDERS_KEY];
  if (existing instanceof Map) {
    return existing as Map<string, HostEmbeddingProvider>;
  }
  const created = new Map<string, HostEmbeddingProvider>();
  store[HOST_EMBEDDING_PROVIDERS_KEY] = created;
  return created;
}

export function registerHostEmbeddingProvider(
  scope: string,
  provider: HostEmbeddingProvider,
): () => void {
  const key = normalizeScope(scope);
  const providers = providerMap();
  const previous = providers.get(key);
  if (previous && previous !== provider) {
    void previous.close?.();
  }
  providers.set(key, provider);
  return () => {
    const providers = providerMap();
    if (providers.get(key) === provider) {
      providers.delete(key);
      void provider.close?.();
    }
  };
}

export function getHostEmbeddingProvider(
  scope: string,
): HostEmbeddingProvider | undefined {
  return providerMap().get(normalizeScope(scope));
}

export function clearHostEmbeddingProvidersForTest(): void {
  providerMap().clear();
}

export function normalizeHostEmbeddingVector(value: unknown): number[] | null {
  if (!Array.isArray(value) && (!ArrayBuffer.isView(value) || value instanceof DataView)) {
    return null;
  }
  const vector = Array.from(value as unknown as ArrayLike<unknown>);
  return vector.length > 0 &&
    vector.every((component): component is number => {
      return typeof component === "number" && Number.isFinite(component);
    })
    ? vector
    : null;
}

function normalizeScope(scope: string): string {
  const normalized = typeof scope === "string" ? scope.trim() : "";
  return normalized || "default";
}

/**
 * File-level storage for the embedding fallback index (issue #3146).
 *
 * Two single-generation layouts, exactly one authoritative at a time:
 *   - `legacy`:  the single `state/embeddings.json` file, used while the
 *     whole index serializes within `resolveIndexFileCharLimit()` chars;
 *   - `sharded`: the published `state/embeddings/` directory of hash-assigned
 *     shard files, migrated to ONE-WAY and ATOMICALLY (stage a complete shard
 *     set, publish with a single directory rename, demote the legacy file to
 *     a non-authoritative recovery artifact). Generations never merge, so a
 *     crash cannot resurrect deleted entries or drop published ones.
 *
 * This module owns files, budgets, and durable diagnostics only — no index
 * caching or provider logic (that lives in `embedding-fallback.ts`).
 */
import path from "node:path";
import { randomUUID } from "node:crypto";
import { constants as bufferConstants } from "node:buffer";
import { lstat, mkdir, mkdtemp, realpath, readFile, readdir, rename, rm, stat, writeFile } from "node:fs/promises";
import { log } from "./logger.js";
import {
  GENERATION_MARKER_IN_FLIGHT,
  beginGenerationMarker as writeGenerationMarkerInFlight,
  completeGenerationMarker as writeGenerationMarkerComplete,
  generationMarkerPath,
  writeGenerationMarkerRaw,
} from "./embedding-generation-marker.js";
import { readEnvVar } from "./runtime/env.js";
import type { EmbeddingGenerationFence } from "./embedding-generation-lock.js";

export type EmbeddingProviderType = "openai" | "local" | "host";

export type EmbeddingIndexEntry = {
  vector: number[];
  path: string;
};

export type EmbeddingIndexFile = {
  version: 1;
  provider: EmbeddingProviderType;
  model: string;
  entries: Record<string, EmbeddingIndexEntry>;
};

export type EmbeddingIndexIdentity = Pick<EmbeddingIndexFile, "provider" | "model">;

/** Outcome of reading one managed index file (legacy or shard). */
export type ManagedIndexRead =
  | { outcome: "ok"; file: EmbeddingIndexFile }
  | { outcome: "absent" }
  | { outcome: "foreign" }
  | { outcome: "unreadable"; reason: string };

/** Which generation owns the index right now. */
export type IndexLayout = "empty" | "legacy" | "sharded";

/**
 * Thrown when an embedding index (or one of its shards) cannot be persisted
 * within the per-file serialization budget. Issue #3146: index files are
 * materialized as single V8 strings, so a JSON document at or past
 * `bufferConstants.MAX_STRING_LENGTH` chars makes every read and write throw
 * `RangeError: Invalid string length`. The index is sharded before that
 * ceiling; this tagged error is reserved for the residual case where even
 * one shard cannot hold the payload (e.g. a single entry with an enormous
 * vector), so callers can classify it as recoverable-with-record instead of
 * an opaque background failure.
 */
export class EmbeddingIndexCapacityError extends Error {
  override readonly name = "EmbeddingIndexCapacityError" as const;
  constructor(
    message: string,
    readonly memoryId?: string,
  ) {
    super(message);
  }
}

/**
 * Thrown when an index file that should be authoritative cannot be read
 * (I/O error, over-budget size, unparseable JSON). Mutation paths fail
 * CLOSED on this: they must not continue with a fresh empty index and
 * pretend the previous vectors were loaded — the file is left untouched in
 * place for recovery. Read-only paths (recall) fail open to empty results
 * and record the reason durably.
 */
export class EmbeddingIndexStorageError extends Error {
  override readonly name = "EmbeddingIndexStorageError" as const;
}

/** Durable diagnostic row describing the last failed embedding-index write. */
export interface EmbeddingIndexWriteFailure {
  ts: string;
  kind: "capacity" | "io";
  message: string;
  memoryId?: string;
}

/**
 * Durable embedding-index diagnostics (issue #3146), persisted at
 * `<memoryDir>/state/embedding-fallback-status.json` and surfaced through
 * console_state, so background ingestion failures are visible to operators
 * instead of only ever appearing as log lines.
 */
export interface EmbeddingIndexStatusFile {
  version: 1;
  /** Cumulative count of failed index writes since the file was created. */
  failureCount: number;
  /** Active write failure; cleared by the next successful save. */
  lastWriteFailure?: EmbeddingIndexWriteFailure;
  /** Set when an unreadable index file was detected instead of overwritten. */
  lastReadRecovery?: { ts: string; message: string };
  lastSuccessAt?: string;
}

/**
 * Per-file serialization budget (JSON-string chars) for WRITES of the legacy
 * `state/embeddings.json` file and of every shard under `state/embeddings/`.
 * The 16MiB margin keeps the write round-trip clear of the V8 single-string
 * ceiling even with UTF-8 byte/count skew and small header growth. Override
 * per environment (tests, headroom tuning) via
 * `REMNIC_EMBEDDING_INDEX_FILE_CHAR_LIMIT`.
 *
 * READS are gated by the HARD ceiling (`resolveIndexHardReadCharLimit`),
 * never by this budget: a legacy index written by an older version may
 * legitimately sit between the soft budget and the hard ceiling (the
 * reported production file does), and it must still load and migrate.
 */
const DEFAULT_INDEX_FILE_CHAR_LIMIT =
  bufferConstants.MAX_STRING_LENGTH - 16 * 1024 * 1024;

/**
 * Hard single-string ceiling for READS: files at or above this size are not
 * attempted (a readFile would throw `RangeError: Invalid string length`);
 * their bytes are preserved in place and mutations fail closed with an
 * actionable error. Defaults to the V8 maximum; tests inject a small value
 * via `REMNIC_EMBEDDING_INDEX_HARD_READ_LIMIT_CHARS`.
 */
function resolveIndexHardReadCharLimit(): number {
  const soft = resolveIndexFileCharLimit();
  const raw = readEnvVar("REMNIC_EMBEDDING_INDEX_HARD_READ_LIMIT_CHARS");
  if (raw) {
    const parsed = Number(raw);
    if (Number.isInteger(parsed) && parsed >= soft) return parsed;
  }
  return bufferConstants.MAX_STRING_LENGTH;
}

/** Hash shards under `state/embeddings/` used once the budget is exceeded. */
const SHARD_COUNT = 64;

const SHARD_FILE_PATTERN = /^shard-\d{4}\.json$/;

export function resolveIndexFileCharLimit(): number {
  const raw = readEnvVar("REMNIC_EMBEDDING_INDEX_FILE_CHAR_LIMIT");
  if (raw) {
    const parsed = Number(raw);
    if (Number.isInteger(parsed) && parsed >= 1024) return parsed;
  }
  return DEFAULT_INDEX_FILE_CHAR_LIMIT;
}

function shardFileName(shardIndex: number): string {
  return `shard-${String(shardIndex).padStart(4, "0")}.json`;
}

/**
 * Fixed transaction backup path for identity replacements. A fixed (not
 * per-process) name is what makes the rename gap recoverable: whatever
 * process restarts after a crash finds the demoted former generation here
 * and rolls it back into place.
 */
function replacementBackupPath(shardDir: string): string {
  return path.join(path.dirname(shardDir), "embeddings.pre-replace.tmp");
}

/**
 * Stable FNV-1a shard assignment: an entry always hashes to the same shard,
 * so an update or removal never needs a manifest to find its file.
 */
export function shardIndexOf(memoryId: string, shardCount: number): number {
  let hash = 0x811c9dc5;
  for (let i = 0; i < memoryId.length; i++) {
    hash ^= memoryId.charCodeAt(i);
    hash = Math.imul(hash, 0x01000193) >>> 0;
  }
  return hash % shardCount;
}

/**
 * A shard file named `shard-NNNN.json` must only contain ids that hash to
 * that shard: a misplaced copy would be loaded today and silently resurrect
 * stale vectors after the computed shard is rewritten (issue #3148, round 6).
 * Throws the tagged storage error so mutations fail closed and recall fails
 * open at its boundary.
 */
export function validateShardMembership(shardName: string, file: EmbeddingIndexFile): void {
  const match = /^shard-(\d{4})\.json$/.exec(shardName);
  if (!match) return; // not a shard file (legacy documents have no constraint)
  const shardIndex = Number(match[1]);
  for (const id of Object.keys(file.entries)) {
    if (shardIndexOf(id, SHARD_COUNT) !== shardIndex) {
      throw new EmbeddingIndexStorageError(
        `refusing embedding index shard ${shardName}: id ${id} hashes to shard ${shardIndexOf(id, SHARD_COUNT)}, not ${shardIndex}; file preserved in place`,
      );
    }
  }
}

export function isInvalidStringLengthError(err: unknown): boolean {
  return err instanceof RangeError && /invalid string length/i.test(err.message);
}

/**
 * Parse and FULLY validate one serialized index document (legacy or shard).
 * The single read boundary shared by disk reads and offline-sync pulls: a
 * document with a valid header but a malformed body (`entries` not a plain
 * record, or an entry whose `path` is not a string / whose `vector` is not a
 * finite-number array) is `unreadable`, not `ok` — recall fails open on the
 * tagged reason, mutations fail closed, and the bytes are never overwritten
 * (issue #3148 review, round 4).
 */
export function parseEmbeddingIndexDocument(raw: string): ManagedIndexRead {
  let parsed: unknown;
  try {
    parsed = JSON.parse(raw);
  } catch (err) {
    return {
      outcome: "unreadable",
      reason: `JSON parse failed: ${err instanceof Error ? err.message : String(err)}`,
    };
  }
  if (
    !parsed ||
    typeof parsed !== "object" ||
    Array.isArray(parsed) ||
    (parsed as Partial<EmbeddingIndexFile>).version !== 1 ||
    typeof (parsed as Partial<EmbeddingIndexFile>).provider !== "string" ||
    typeof (parsed as Partial<EmbeddingIndexFile>).model !== "string" ||
    ((parsed as Partial<EmbeddingIndexFile>).model as string).length === 0
  ) {
    return { outcome: "foreign" };
  }
  // An unsupported identity must fail closed like any other malformed
  // document: recall cannot serve it and mutations must not adopt it as
  // authoritative (issue #3148, round 6).
  if (
    (parsed as Partial<EmbeddingIndexFile>).provider !== "openai" &&
    (parsed as Partial<EmbeddingIndexFile>).provider !== "local" &&
    (parsed as Partial<EmbeddingIndexFile>).provider !== "host"
  ) {
    return { outcome: "foreign" };
  }
  const entries = (parsed as Partial<EmbeddingIndexFile>).entries;
  if (!entries || typeof entries !== "object" || Array.isArray(entries)) {
    return {
      outcome: "unreadable",
      reason: "entries must be a plain record of memory id -> entry",
    };
  }
  for (const [id, entry] of Object.entries(entries as Record<string, unknown>)) {
    if (!entry || typeof entry !== "object" || Array.isArray(entry)) {
      return { outcome: "unreadable", reason: `entry ${id} must be an object` };
    }
    const candidate = entry as Partial<EmbeddingIndexEntry>;
    if (typeof candidate.path !== "string") {
      return { outcome: "unreadable", reason: `entry ${id}.path must be a string` };
    }
    if (!Array.isArray(candidate.vector)) {
      return { outcome: "unreadable", reason: `entry ${id}.vector must be an array` };
    }
    for (const component of candidate.vector) {
      if (!Number.isFinite(component)) {
        return {
          outcome: "unreadable",
          reason: `entry ${id}.vector must contain only finite numbers`,
        };
      }
    }
  }
  return { outcome: "ok", file: parsed as EmbeddingIndexFile };
}

/**
 * Group a complete index into per-shard entry records using the stable FNV
 * assignment. Shared by `persist()` and the offline-sync generation
 * transaction so a converted generation shards identically everywhere.
 */
export function shardEntriesForIndex(
  index: EmbeddingIndexFile,
): Map<number, Record<string, EmbeddingIndexEntry>> {
  const groups = new Map<number, Record<string, EmbeddingIndexEntry>>();
  for (const id of Object.keys(index.entries)) {
    const shardIndex = shardIndexOf(id, SHARD_COUNT);
    const group = groups.get(shardIndex);
    if (group) group[id] = index.entries[id];
    else groups.set(shardIndex, { [id]: index.entries[id] });
  }
  return groups;
}

/**
 * Serialize one shard, translating a ceiling overflow into a tagged,
 * recoverable capacity error. Exported for the offline-sync generation
 * transaction, which stages incoming generations through the same budget.
 */
export function serializeEmbeddingShard(
  index: EmbeddingIndexFile,
  shardIndex: number,
  entries: Record<string, EmbeddingIndexEntry>,
  limit: number = resolveIndexFileCharLimit(),
): string {
  let body: string;
  try {
    body = JSON.stringify({
      version: 1 as const,
      provider: index.provider,
      model: index.model,
      entries,
    });
  } catch (err) {
    throw new EmbeddingIndexCapacityError(
      `embedding index shard ${shardFileName(shardIndex)} exceeded the single-string ceiling while serializing: ${err instanceof Error ? err.message : String(err)}`,
      largestEntryId(entries) || undefined,
    );
  }
  if (body.length > limit) {
    const worstId = largestEntryId(entries);
    const worstLength = worstId && entries[worstId] ? JSON.stringify(entries[worstId]).length : 0;
    throw new EmbeddingIndexCapacityError(
      `embedding index shard ${shardFileName(shardIndex)} needs ${body.length} chars, over the ${limit}-char single-file limit; largest entry ${worstId || "(unknown)"} serializes to ${worstLength} chars`,
      worstId || undefined,
    );
  }
  return body;
}

function largestEntryId(entries: Record<string, EmbeddingIndexEntry>): string {
  let worstId = "";
  let worstLength = 0;
  for (const [id, entry] of Object.entries(entries)) {
    let length: number;
    try {
      length = JSON.stringify(entry).length;
    } catch {
      return id;
    }
    if (length > worstLength) {
      worstLength = length;
      worstId = id;
    }
  }
  return worstId;
}

/**
 * Optional canonical secure-store IO for the daemon. When provided (both
 * halves), file content is read/written through the SAME
 * StorageManager-backed contract offline sync uses: canonical-path AAD,
 * secure-key-aware, atomic. Shard STAGING writes carry the FINAL published
 * path so the post-publish rename keeps the ciphertext decryptable; dirty
 * shard, status, and legacy writes are their own canonical final path.
 * When omitted, the store behaves exactly as before (raw plaintext fs).
 * The diagnostics status file is intentionally ALWAYS plain: it holds no
 * memory content (failure strings/counts only) and console_state reads it
 * without unlocking the store.
 */
export interface EmbeddingIndexStoreIo {
  readUtf8(filePath: string): Promise<string>;
  writeUtf8(filePath: string, contents: string, opts?: { finalAadFilePath?: string }): Promise<void>;
}

export class EmbeddingIndexFileStore {
  constructor(
    private readonly indexPath: string,
    private readonly shardDir: string,
    private readonly statusPath: string,
    private readonly io?: EmbeddingIndexStoreIo,
  ) {
    if (io && (Boolean(io.readUtf8) !== Boolean(io.writeUtf8))) {
      throw new EmbeddingIndexStorageError(
        "embedding index store io requires both readUtf8 and writeUtf8; a half-wired io would mix encrypted and plaintext files",
      );
    }
  }

  /** Legacy single-file layout path (public for error messages). */
  get legacyPath(): string {
    return this.indexPath;
  }

  /** Record an unreadable-authoritative-file reason (both read and mutation paths). */
  async recordIndexStatusForLoad(reason: string): Promise<void> {
    await this.recordIndexStatus({
      lastReadRecovery: { ts: new Date().toISOString(), message: reason },
    });
  }

  /**
   * Which generation owns the index right now. The published
   * `state/embeddings/` directory IS the layout marker: until it exists the
   * legacy file is authoritative; from the atomic rename onward it never
   * merges again.
   */
  async detectLayout(): Promise<IndexLayout> {
    // An interrupted identity replacement leaves the published directory
    // absent with the fixed transaction backup still on disk (the publish
    // rename never completed). Report SHARDED for that gap: the backup holds
    // the authoritative generation, so neither the legacy file nor a fresh
    // index may win, and reads fail open to empty until the mutation queue
    // performs the rollback. The rollback itself only ever runs inside
    // persist() — a write — so read paths never race an in-flight
    // replacement with a recovery rename (issue #3148 review).
    try {
      // lstat, NOT stat: a symlinked generation directory must be rejected
      // outright — following it would read or write OUTSIDE the state
      // directory through the link (codex PRRT_kwDORJXyws6mZ72r).
      const info = await lstat(this.shardDir);
      if (info.isSymbolicLink()) {
        throw new EmbeddingIndexStorageError(
          `embedding index shard directory is a symlink; refusing to read or write through it: ${this.shardDir}`,
        );
      }
      return "sharded";
    } catch (err) {
      if (err instanceof EmbeddingIndexStorageError) throw err;
      if ((err as NodeJS.ErrnoException).code !== "ENOENT") {
        // The pointer exists but cannot be stat'ed — fail towards the
        // published generation so its readers surface the I/O error.
        log.warn(`embedding index: shard dir stat failed (${err instanceof Error ? err.message : String(err)}); assuming sharded layout`);
        return "sharded";
      }
      if (await this.replacementBackupExists()) return "sharded";
      return this.legacyOrEmptyLayout();
    }
  }

  /**
   * Roll the fixed transaction backup back into the published position.
   * Returns true when a rollback happened.
   */
  private async replacementBackupExists(): Promise<boolean> {
    const backupPath = replacementBackupPath(this.shardDir);
    try {
      await stat(backupPath);
      return true;
    } catch (err) {
      if ((err as NodeJS.ErrnoException).code === "ENOENT") return false;
      // An unreadable backup must not be silently treated as absent —
      // that would permit the legacy fallback over a generation we cannot
      // inspect (issue #3148 review, round 1).
      throw new EmbeddingIndexStorageError(
        `cannot stat embedding index replacement backup ${backupPath}: ${err instanceof Error ? err.message : String(err)}`,
      );
    }
  }

  /**
   * The fixed transaction backup is a path with well-known semantics; a
   * planted symlink must never be restored into the published position (it
   * would point the generation outside the memory dir) nor removed through
   * as if it were the former generation. Symlinks are rejected outright.
   */
  private async assertBackupNotSymlink(backupPath: string): Promise<void> {
    const info = await lstat(backupPath).catch((err) => {
      if ((err as NodeJS.ErrnoException).code === "ENOENT") return null;
      throw err;
    });
    if (info?.isSymbolicLink()) {
      throw new EmbeddingIndexStorageError(
        `embedding index replacement backup is a symlink; refusing to touch it: ${backupPath}`,
      );
    }
  }

  /**
   * Mutation-queue entry point: roll the fixed transaction backup back into
   * the published position after an interrupted replacement. Returns true
   * when a rollback happened. Only fires in the actual rename gap
   * (published directory absent); callers must invalidate any cached index
   * view when this returns true. A successful rollback finalizes the
   * generation marker strictly: a failed completion write fails the
   * recovery instead of leaving every search reloading forever.
   */
  async recoverIfInterrupted(fence?: EmbeddingGenerationFence): Promise<boolean> {
    // Only the rename gap (published directory absent) is recoverable. When
    // the directory is present - including after a crash that followed a
    // successful publish - the generation on disk is already authoritative
    // and renaming the backup onto it would fail with EEXIST (issue #3148
    // review, round 2).
    try {
      await stat(this.shardDir);
      return false;
    } catch (err) {
      if ((err as NodeJS.ErrnoException).code !== "ENOENT") {
        log.warn(`embedding index: recovery skipped because shard dir stat failed: ${err instanceof Error ? err.message : String(err)}`);
        return false;
      }
    }
    const backupPath = replacementBackupPath(this.shardDir);
    if (!(await this.replacementBackupExists())) return false;
    await this.assertBackupNotSymlink(backupPath);
    // The rollback rename is destructive: reassert lock ownership first.
    await fence?.();
    await rename(backupPath, this.shardDir);
    await this.writeGenerationMarker(randomUUID());
    log.warn(
      `embedding index: recovered interrupted replacement; former generation restored from ${backupPath}`,
    );
    await this.recordIndexStatus({
      lastReadRecovery: {
        ts: new Date().toISOString(),
        message: "interrupted identity replacement rolled back to the former generation",
      },
    });
    return true;
  }

  private async legacyOrEmptyLayout(): Promise<IndexLayout> {
    try {
      await stat(this.indexPath);
      return "legacy";
    } catch (err) {
      if ((err as NodeJS.ErrnoException).code === "ENOENT") return "empty";
      throw err;
    }
  }

  /** Barrier first half: strict, so bytes can never change under a stable stamp. */
  private async beginGenerationMarker(): Promise<void> {
    await writeGenerationMarkerInFlight(generationMarkerPath(path.dirname(this.shardDir)));
  }

  /**
   * Barrier second half: written after the last content write. Best-effort;
   * the in-flight fallback semantics live in the shared marker module.
   */
  private async completeGenerationMarker(): Promise<void> {
    await writeGenerationMarkerComplete(generationMarkerPath(path.dirname(this.shardDir)));
  }

  private async writeGenerationMarker(value: string): Promise<void> {
    await writeGenerationMarkerRaw(generationMarkerPath(path.dirname(this.shardDir)), value);
  }

  /** Marker value, or null when absent/unreadable (pre-marker stores keep the stat stamp). */
  private async readGenerationMarker(): Promise<string | null> {
    try {
      const raw = await readFile(
        generationMarkerPath(path.dirname(this.shardDir)),
        "utf-8",
      );
      const value = raw.trim();
      return value.length > 0 ? value : null;
    } catch {
      return null;
    }
  }

  /**
   * Warm-cache stamp. A completed generation marker alone would freeze the
   * stamp for a pre-marker writer in a rolling deployment (it publishes
   * shard/index changes without updating the marker), so the marker is
   * combined with the watched path's stat: the marker keeps consecutive
   * publications distinct on coarse-tick filesystems, the stat keeps
   * legacy writers visible. In-flight never repeats, forcing revalidation
   * until a publication completes. Stores never published through this
   * module keep the plain stat stamp — a directory stat alone aliases
   * consecutive publications on coarse-tick filesystems and across inode
   * reuse.
   */
  async identityStamp(): Promise<string> {
    const layout = await this.detectLayout();
    if (layout === "sharded") {
      const info = await lstat(this.shardDir).catch((err) => {
        // SAFETY: only the errno code is inspected; any other rejection shape rethrows uninterpreted.
        if ((err as NodeJS.ErrnoException).code === "ENOENT") return null;
        throw new EmbeddingIndexStorageError(
          `cannot stat embedding index shard directory ${this.shardDir}: ${err instanceof Error ? err.message : String(err)}`,
        );
      });
      if (!info) return "rename-gap";
      const marker = await this.readGenerationMarker();
      // An in-flight marker must never produce a repeatable stamp: a probe
      // that cached one (completion write failed) must revalidate on every
      // later probe until a publication completes.
      if (marker) {
        if (marker === GENERATION_MARKER_IN_FLIGHT) return `gen:${randomUUID()}`;
        return `gen:${marker}:${info.ino}:${info.mtimeMs}`;
      }
      return `shard:${info.ino}:${info.mtimeMs}`;
    }
    if (layout === "legacy") {
      const info = await stat(this.indexPath).catch((err) => {
        // SAFETY: only the errno code is inspected; any other rejection shape rethrows uninterpreted.
        if ((err as NodeJS.ErrnoException).code === "ENOENT") return null;
        throw new EmbeddingIndexStorageError(
          `cannot stat embedding index file ${this.indexPath}: ${err instanceof Error ? err.message : String(err)}`,
        );
      });
      if (!info) return "rename-gap";
      const marker = await this.readGenerationMarker();
      if (marker) {
        if (marker === GENERATION_MARKER_IN_FLIGHT) return `gen:${randomUUID()}`;
        return `gen:${marker}:${info.ino}:${info.mtimeMs}`;
      }
      return `legacy:${info.ino}:${info.mtimeMs}`;
    }
    return "empty";
  }

  /** Header identity of the authoritative generation, read leniently. */
  async identityFromDisk(): Promise<EmbeddingIndexIdentity | null> {
    const layout = await this.detectLayout();
    if (layout === "sharded") {
      // Shard files are bounded by the per-file budget, so the identity
      // probe never reads a ceiling-sized string.
      for (const name of await this.readShardNames()) {
        const read = await this.readFileAt(path.join(this.shardDir, name));
        if (read.outcome === "ok") {
          return { provider: read.file.provider, model: read.file.model };
        }
      }
      return null;
    }
    if (layout === "legacy") {
      const read = await this.readFileAt(this.indexPath);
      if (read.outcome === "ok") {
        return { provider: read.file.provider, model: read.file.model };
      }
    }
    return null;
  }

  /**
   * Load every readable shard into `merged`. Returns the generation identity.
   * Unreadable shards record durable diagnostics; `strict` additionally
   * fails the mutation closed.
   */
  async readShardGenerationInto(
    merged: Record<string, EmbeddingIndexEntry>,
  ): Promise<EmbeddingIndexIdentity | null> {
    let identity: EmbeddingIndexIdentity | null = null;
    for (const name of await this.readShardNames()) {
      const read = await this.readFileAt(path.join(this.shardDir, name));
      if (read.outcome !== "ok") {
        if (read.outcome === "unreadable") {
          await this.recordIndexStatus({
            lastReadRecovery: { ts: new Date().toISOString(), message: `${name}: ${read.reason}` },
          });
          throw new EmbeddingIndexStorageError(
            `refusing to continue from unreadable embedding index shard ${name}: ${read.reason}`,
          );
        }
        await this.recordIndexStatus({
          lastReadRecovery: { ts: new Date().toISOString(), message: `${name}: unrecognized index format` },
        });
        throw new EmbeddingIndexStorageError(
          `refusing to continue from malformed embedding index shard ${name} (unrecognized format); file preserved in place`,
        );
      }
      try {
        validateShardMembership(name, read.file);
      } catch (error) {
        await this.recordIndexStatus({
          lastReadRecovery: { ts: new Date().toISOString(), message: String(error) },
        });
        throw error;
      }
      const shardIdentity = { provider: read.file.provider, model: read.file.model };
      if (!identity) identity = shardIdentity;
      if (!sameIndexIdentity(shardIdentity, identity)) {
        // A partial rewrite from this map would silently drop the foreign
        // shard's entries, so even recall must not serve this generation.
        throw new EmbeddingIndexStorageError(
          `refusing to continue from mixed-identity embedding index generation: ${name} is ${shardIdentity.provider}/${shardIdentity.model} but the generation identity is ${identity.provider}/${identity.model}; files preserved in place`,
        );
      }
      Object.assign(merged, read.file.entries);
    }
    return identity;
  }

  async readLegacy(): Promise<ManagedIndexRead> {
    return this.readFileAt(this.indexPath);
  }

  /**
   * Read one managed index file (legacy or shard). The file is never
   * modified or moved here: an unreadable file stays in place for recovery
   * and is reported through the returned outcome (mutation paths fail
   * closed on it; read-only paths fail open and record the reason).
   */
  /**
   * Read/mutation boundary for any generation member or the legacy marker
   * (codex PRRT_kwDORJXyws6mZ72r): a symlinked member is rejected outright
   * and its real target must stay inside the canonical state directory —
   * following a planted link would read or write outside the memory root.
   * Runs BEFORE the secure IO so storage-backed reads are covered too.
   */
  private async assertGenerationFileNotSymlinked(filePath: string): Promise<void> {
    const info = await lstat(filePath).catch((err) => {
      if ((err as NodeJS.ErrnoException).code === "ENOENT") return null;
      throw new EmbeddingIndexStorageError(
        `cannot lstat embedding index file ${filePath}: ${err instanceof Error ? err.message : String(err)}`,
      );
    });
    const stateDir = path.dirname(this.shardDir);
    // Containment must be checked even when the member itself is a regular
    // file: a SYMLINKED GENERATION DIRECTORY lets reads through to whatever
    // path the link resolves to — a regular file in a linked dir is still
    // outside the memory root and must be rejected.
    const real = await realpath(filePath).catch(() => null);
    if (real) {
      const scope = await realpath(stateDir).catch(() => stateDir);
      const rel = path.relative(scope, real);
      if (rel.startsWith("..") || path.isAbsolute(rel)) {
        throw new EmbeddingIndexStorageError(
          `embedding index file escapes the state directory via symlink; refusing: ${filePath} -> ${real}`,
        );
      }
    }
    if (!info || !info.isSymbolicLink()) return;
    throw new EmbeddingIndexStorageError(
      `embedding index file is a symlink; refusing to read or write through it: ${filePath}`,
    );
  }

  async readFileAt(filePath: string): Promise<ManagedIndexRead> {
    await this.assertGenerationFileNotSymlinked(filePath);
    const hardLimit = resolveIndexHardReadCharLimit();
    let size = 0;
    try {
      size = (await stat(filePath)).size;
    } catch (err) {
      if ((err as NodeJS.ErrnoException).code === "ENOENT") return { outcome: "absent" };
      return { outcome: "unreadable", reason: `stat failed: ${err instanceof Error ? err.message : String(err)}` };
    }
    // Reads are gated by the HARD single-string ceiling only — NOT by the
    // soft write budget — so a legacy index from an older version sitting
    // between the two still loads and migrates (issue #3146). Byte size is
    // only a conservative bound for UTF-8 (bytes ≥ chars): at or below it a
    // readFile is guaranteed materializable; past it the file MAY still be
    // readable as a string, but refusing is the safe side. An over-ceiling
    // file is preserved in place; the caller decides fail-open (recall) or
    // fail-closed (mutation).
    if (size > hardLimit) {
      return {
        outcome: "unreadable",
        reason: `file is ${size} bytes, over the ${hardLimit}-char hard single-string read ceiling (V8 RangeError territory); bytes preserved in place — move or prune the file to recover`,
      };
    }
    let raw: string;
    try {
      raw = this.io
        ? await this.io.readUtf8(filePath)
        : await readFile(filePath, "utf-8");
    } catch (err) {
      return { outcome: "unreadable", reason: `read failed: ${err instanceof Error ? err.message : String(err)}` };
    }
    return parseEmbeddingIndexDocument(raw);
  }

  private async readShardNames(): Promise<string[]> {
    try {
      return (await readdir(this.shardDir))
        .filter((name) => SHARD_FILE_PATTERN.test(name))
        .sort();
    } catch (err) {
      if ((err as NodeJS.ErrnoException).code === "ENOENT") return [];
      // The published generation exists but cannot be enumerated. Treating
      // it as empty would let a mutation overwrite shards it never saw, so
      // this must propagate — strict mutation fails closed, recall fails
      // open at its boundary (issue #3146 review).
      throw new EmbeddingIndexStorageError(
        `cannot enumerate embedding index shard directory ${this.shardDir}: ${err instanceof Error ? `${err.message} (${(err as NodeJS.ErrnoException).code ?? "unknown"})` : String(err)}`,
      );
    }
  }

  /**
   * Persist the index. Layout decisions, in order:
   *   - published generation: rewrite only the shards this mutation touched;
   *   - legacy/empty generation and the whole index fits one bounded JSON
   *     string: stay the single `state/embeddings.json` file;
   *   - over budget: ONE-WAY migration — stage a complete shard set, publish
   *     it with a single directory rename, then rename the legacy file aside
   *     as a non-authoritative recovery artifact (issue #3146).
   */
  async persist(
    index: EmbeddingIndexFile,
    opts: {
      touchedIds?: readonly string[];
      memoryId?: string;
      /** Reasserts mutation-lock ownership immediately before each destructive write (after serialization). */
      fence?: EmbeddingGenerationFence;
    } = {},
  ): Promise<void> {
    const stateDir = path.dirname(this.indexPath);
    await mkdir(stateDir, { recursive: true });
    await this.cleanForeignStagingDirs();
    // NOTE: interrupted-replacement recovery runs in the mutation wrapper
    // (EmbeddingFallback.enqueueIndexMutation) BEFORE this method, so the
    // caller's index already reflects the restored generation.

    const groups = shardEntriesForIndex(index);

    const layout = await this.detectLayout();

    if (layout === "sharded") {
      const limit = resolveIndexFileCharLimit();
      // An identity change on a published generation (a sharded host index
      // replaced by a fallback provider, or a host-model change) must
      // publish a COMPLETE replacement: the dirty-shard fast path would
      // rewrite only the touched shard under the new identity and leave the
      // former identity's shards in place — a mixed generation that every
      // later load rejects (codex P1, PR #3148).
      const diskIdentity = await this.identityFromDisk();
      if (groups.size === 0) {
        // An empty directory has no transport-visible deletion evidence.
        // Publish a valid empty shard so a peer without a shared base also
        // replaces its stale generation rather than preserving old vectors.
        groups.set(0, {});
        await this.publishReplacementGeneration(index, groups, limit, opts.fence);
        return;
      }
      const identityChanged =
        diskIdentity !== null &&
        (diskIdentity.provider !== index.provider || diskIdentity.model !== index.model);
      if (identityChanged) {
        await this.publishReplacementGeneration(index, groups, limit, opts.fence);
        return;
      }
      const dirtyShards = opts.touchedIds?.length
        ? new Set(opts.touchedIds.map((id) => shardIndexOf(id, SHARD_COUNT)))
        : null;
      // Serialize every touched shard BEFORE writing anything so a capacity
      // failure cannot leave a partial rewrite.
      const targets = dirtyShards ? [...dirtyShards] : [...groups.keys()];
      const payloads = targets
        .filter((shardIndex) => groups.has(shardIndex))
        .map((shardIndex) => ({
          shardIndex,
          body: serializeEmbeddingShard(index, shardIndex, groups.get(shardIndex)!, limit),
        }));
      // Serialization is done: reassert lock ownership immediately before
      // the destructive live-generation writes.
      await opts.fence?.();
      await this.beginGenerationMarker();
      await opts.fence?.();
      for (const payload of payloads) {
        await this.writeAtomicFile(
          path.join(this.shardDir, shardFileName(payload.shardIndex)),
          payload.body,
        );
      }
      // A dirty shard with no remaining entries (its last entry was just
      // removed) must be removed from disk, not silently skipped.
      for (const shardIndex of targets) {
        if (!groups.has(shardIndex)) {
          await rm(path.join(this.shardDir, shardFileName(shardIndex)), { force: true });
        }
      }
      await this.completeGenerationMarker();
      return;
    }

    let whole: string | null;
    try {
      whole = JSON.stringify(index);
    } catch (err) {
      if (!isInvalidStringLengthError(err)) throw err;
      whole = null;
    }
    const limit = resolveIndexFileCharLimit();
    if (whole !== null && whole.length <= limit) {
      // Serialized above: reassert lock ownership immediately before the
      // destructive atomic write.
      await opts.fence?.();
      await this.beginGenerationMarker();
      await opts.fence?.();
      await this.writeAtomicFile(this.indexPath, whole);
      await this.completeGenerationMarker();
      return;
    }

    // One-way migration. Until the publish rename, the legacy file stays
    // authoritative; afterwards the published directory is the only
    // generation and the legacy file is demoted to a recovery artifact.
    const stagingDir = path.join(
      stateDir,
      `embeddings.staging.tmp-${process.pid}-${Date.now()}-${Math.random().toString(16).slice(2)}`,
    );
    await mkdir(stagingDir, { recursive: true });
    try {
      await this.stageShardSet(stagingDir, index, groups, limit);
      // Atomic publish: the directory appearing IS the layout marker.
      await this.publishSwappedGeneration(stagingDir, opts.fence);
    } catch (err) {
      await rm(stagingDir, { recursive: true, force: true }).catch(() => undefined);
      throw err;
    }
    await rename(
      this.indexPath,
      `${this.indexPath}.pre-migration.tmp-${Date.now()}-${Math.random().toString(16).slice(2)}`,
    ).catch(() => undefined);
  }

  /**
   * Replace a published generation wholesale after a provider/model identity
   * change (replacement semantics — the former entries are obsolete by
   * definition). Crash-safe by the same construction as the migration: the
   * COMPLETE new-identity set is staged and validated first (old bytes are
   * not touched until staging succeeds), then published atomically through
   * `publishSwappedGeneration`.
   */
  private async publishReplacementGeneration(
    index: EmbeddingIndexFile,
    groups: Map<number, Record<string, EmbeddingIndexEntry>>,
    limit: number,
    fence?: EmbeddingGenerationFence,
  ): Promise<void> {
    const stateDir = path.dirname(this.indexPath);
    const stagingDir = path.join(
      stateDir,
      `embeddings.staging.tmp-${process.pid}-${Date.now()}-${Math.random().toString(16).slice(2)}`,
    );
    await mkdir(stagingDir, { recursive: true });
    try {
      await this.stageShardSet(stagingDir, index, groups, limit);
      await this.publishSwappedGeneration(stagingDir, fence);
    } catch (err) {
      await rm(stagingDir, { recursive: true, force: true }).catch(() => undefined);
      throw err;
    }
  }

  /**
   * Write a complete shard set into a staging directory. Every shard is
   * serialized before the first write, so a capacity failure cannot leave a
   * partial stage behind.
   */
  private async stageShardSet(
    stagingDir: string,
    index: EmbeddingIndexFile,
    groups: Map<number, Record<string, EmbeddingIndexEntry>>,
    limit: number,
  ): Promise<void> {
    const payloads = [...groups]
      .map(([shardIndex, entries]) => ({
        shardIndex,
        body: serializeEmbeddingShard(index, shardIndex, entries, limit),
      }));
    for (const payload of payloads) {
      const finalAadFilePath = path.join(this.shardDir, shardFileName(payload.shardIndex));
      await this.writeAtomicFile(
        path.join(stagingDir, shardFileName(payload.shardIndex)),
        payload.body,
        { finalAadFilePath },
      );
    }
  }

  /**
   * Atomically remove the published generation (offline-sync: the remote
   * deleted the whole index) by publishing an EMPTY staged directory
   * through the shared swap: the rename is atomic, so the former generation
   * moves whole into the fixed backup and back — a failure before the
   * commit rolls the former generation back intact, and a post-commit
   * backup-cleanup failure is non-fatal (the empty published directory
   * stays the authoritative one-way layout marker). The fixed backup is
   * symlink-checked first (round 5).
   */
  async removePublishedGeneration(fence?: EmbeddingGenerationFence): Promise<void> {
    const backupPath = replacementBackupPath(this.shardDir);
    await this.assertBackupNotSymlink(backupPath);
    await rm(backupPath, { recursive: true, force: true });
    // Remove by publishing an EMPTY staged directory through the SAME swap
    // state machine as every other publication: rename is atomic, so the
    // former generation moves whole into the fixed backup and back — a
    // partially-deleted generation can never be exposed. The empty
    // published directory stays the one-way layout marker, so a stray
    // legacy file can never become authoritative after removal. The
    // demoted backup's post-commit cleanup is non-fatal (existing
    // publishSwappedGeneration semantics).
    await mkdir(path.dirname(this.shardDir), { recursive: true });
    const emptyStaging = await mkdtemp(
      path.join(path.dirname(this.shardDir), "embeddings.staging.tmp-empty-"),
    );
    try {
      await this.publishSwappedGeneration(emptyStaging, fence);
    } catch (err) {
      await rm(emptyStaging, { recursive: true, force: true }).catch(() => undefined);
      throw err;
    }
  }

  /**
   * Atomically publish a fully staged generation directory as THE published
   * generation. The former published directory is demoted to the FIXED
   * transaction backup and the staging dir is renamed in with a single
   * rename; if the publish rename fails the former generation is rolled
   * back, and if the process dies in the rename gap `detectLayout()` /
   * `recoverIfInterrupted()` perform the same rollback on next use.
   * Shared by the mutation-side migration/replacement and the offline-sync
   * generation transaction (issue #3148, round 4) so there is exactly one
   * swap state machine. Staging-dir cleanup stays with the caller.
   */
  async publishSwappedGeneration(stagingDir: string, fence?: EmbeddingGenerationFence): Promise<void> {
    // The replacement is published: the backup is obsolete disk. A cleanup
    // failure is non-fatal (the next replacement removes it) but must stay
    // visible.
    const backupPath = replacementBackupPath(this.shardDir);
    await this.assertBackupNotSymlink(backupPath);
    // Cheap ownership check before the destructive backup cleanup: a peer
    // stale-break would otherwise see the backup vanish under it before we
    // even reach the live renames (Kilo PRRT_kwDORJXyws6mZ8i5).
    await fence?.();
    await rm(backupPath, { recursive: true, force: true });
    // Second ownership check immediately before the live renames: any
    // delay between the cleanup and the rename still allows a stale-break,
    // and publishing now would clobber the peer's write.
    await fence?.();
    // Publication barrier: in-flight before the renames, final at commit.
    await this.beginGenerationMarker();
    await fence?.();
    let demoted = false;
    try {
      await stat(this.shardDir);
      await rename(this.shardDir, backupPath);
      demoted = true;
    } catch (err) {
      if ((err as NodeJS.ErrnoException).code !== "ENOENT") throw err;
    }
    try {
      await rename(stagingDir, this.shardDir);
    } catch (err) {
      if (demoted) {
        try {
          await rename(backupPath, this.shardDir);
          await this.completeGenerationMarker();
        } catch (rollbackErr) {
          log.warn(`embedding index: publication rollback did not restore the generation; marker stays in-flight: ${rollbackErr instanceof Error ? rollbackErr.message : String(rollbackErr)}`);
        }
      } else {
        await this.completeGenerationMarker();
      }
      throw err;
    }
    await this.completeGenerationMarker();
    await rm(backupPath, { recursive: true, force: true }).catch((err) => {
      log.warn(`embedding index: could not remove replacement backup ${backupPath}: ${err}`);
    });
  }

  /** Remove staging dirs orphaned by crashed migrations. A foreign dir younger than the grace window may belong to a live writer mid-migration, so only older dirs are removed (issue #3148 review, round 3). */
  private static readonly STAGING_CLEANUP_GRACE_MS = 10 * 60 * 1000;

  private async cleanForeignStagingDirs(): Promise<void> {
    const stateDir = path.dirname(this.indexPath);
    let names: string[] = [];
    try {
      names = await readdir(stateDir);
    } catch {
      return;
    }
    const ownPrefix = `embeddings.staging.tmp-${process.pid}-`;
    const cutoff = Date.now() - EmbeddingIndexFileStore.STAGING_CLEANUP_GRACE_MS;
    for (const name of names) {
      if (!name.startsWith("embeddings.staging.tmp-") || name.startsWith(ownPrefix)) continue;
      try {
        const stats = await stat(path.join(stateDir, name));
        if (stats.mtimeMs > cutoff) continue;
      } catch {
        continue;
      }
      await rm(path.join(stateDir, name), { recursive: true, force: true }).catch(() => undefined);
    }
  }

  /**
   * Temp-file + rename write. The temp name carries `.tmp-` so offline sync
   * ignores in-flight files under `state/`. With a wired io, the write goes
   * through the canonical secure-store contract instead, optionally binding
   * the ciphertext to the FINAL published path (staged shards).
   */
  private async writeAtomicFile(
    filePath: string,
    contents: string,
    opts?: { finalAadFilePath?: string; bypassSecureIo?: boolean },
  ): Promise<void> {
    if (this.io && opts?.bypassSecureIo !== true) {
      await this.io.writeUtf8(filePath, contents, opts?.finalAadFilePath === undefined ? undefined : { finalAadFilePath: opts.finalAadFilePath });
      return;
    }
    const tempPath = `${filePath}.tmp-${process.pid}-${Date.now()}-${Math.random().toString(16).slice(2)}`;
    try {
      await writeFile(tempPath, contents, "utf-8");
      await rename(tempPath, filePath);
    } catch (err) {
      await rm(tempPath, { force: true }).catch(() => undefined);
      throw err;
    }
  }

  /**
   * Record the outcome of one index mutation durably. This is diagnostics,
   * NOT recovery: write failures are recorded and then re-thrown by the
   * caller so the extraction/consolidation task fails explicitly instead of
   * declaring success over an index that could not be persisted (issue
   * #3146).
   */
  async recordIndexWriteOutcome(err: unknown, memoryId?: string): Promise<void> {
    if (!err) {
      await this.recordIndexStatus({
        lastWriteFailure: null,
        lastSuccessAt: new Date().toISOString(),
      });
      return;
    }
    const kind: EmbeddingIndexWriteFailure["kind"] =
      err instanceof EmbeddingIndexCapacityError || isInvalidStringLengthError(err)
        ? "capacity"
        : "io";
    await this.recordIndexStatus({
      failureCountIncrement: 1,
      lastWriteFailure: {
        ts: new Date().toISOString(),
        kind,
        message: err instanceof Error ? err.message : String(err),
        ...(memoryId ? { memoryId } : {}),
      },
    });
  }

  /**
   * Merge diagnostic state into `state/embedding-fallback-status.json`.
   * Best-effort: a diagnostics failure never masks the real outcome.
   */
  private async recordIndexStatus(
    patch: {
      failureCountIncrement?: number;
      lastWriteFailure?: EmbeddingIndexWriteFailure | null;
      lastReadRecovery?: { ts: string; message: string };
      lastSuccessAt?: string;
    },
  ): Promise<void> {
    try {
      let current: EmbeddingIndexStatusFile = { version: 1, failureCount: 0 };
      try {
        const parsed = JSON.parse(await readFile(this.statusPath, "utf-8")) as Partial<EmbeddingIndexStatusFile>;
        if (parsed && typeof parsed === "object" && typeof parsed.failureCount === "number") {
          current = { ...parsed, version: 1, failureCount: parsed.failureCount };
        }
      } catch {
        // Absent or unreadable status starts fresh; the index files own the truth.
      }
      const next: EmbeddingIndexStatusFile = { ...current };
      if (patch.failureCountIncrement) next.failureCount += patch.failureCountIncrement;
      if (patch.lastWriteFailure !== undefined) {
        if (patch.lastWriteFailure === null) delete next.lastWriteFailure;
        else next.lastWriteFailure = patch.lastWriteFailure;
      }
      if (patch.lastReadRecovery !== undefined) next.lastReadRecovery = patch.lastReadRecovery;
      if (patch.lastSuccessAt !== undefined) next.lastSuccessAt = patch.lastSuccessAt;
      // The status file is ALWAYS plain (non-secret diagnostics: failure
      // strings and counts only). It bypasses the secure io so console_state
      // keeps reading it on locked stores and failure counts never reset.
      await mkdir(path.dirname(this.statusPath), { recursive: true });
      await this.writeAtomicFile(this.statusPath, JSON.stringify(next), { bypassSecureIo: true });
    } catch (err) {
      log.debug(`embedding fallback status write failed: ${err}`);
    }
  }
}

function sameIndexIdentity(
  left: EmbeddingIndexIdentity,
  right: EmbeddingIndexIdentity,
): boolean {
  return left.provider === right.provider && left.model === right.model;
}

// Runtime-state generation rules for offline sync (issue #1786, #3146).
// Extracted from offline-sync.ts so the god-file line-count ratchet does not
// grow when the rules gain entries; behavior is unchanged.

export const EMBEDDING_SHARD_FILE_PATTERN = /^shard-\d{4}\.json$/;

export function isCanonicalRuntimeStatePath(parts: string[]): boolean {
  if (parts[0] === "state") return true;
  return parts[0] === "namespaces" && parts.length >= 4 && parts[2] === "state";
}

const REMOTE_AUTHORITATIVE_RUNTIME_STATE_FILES = new Set([
  ".artifact-write-version.log",
  ".memory-status-version.log",
  "buffer.json",
  "embeddings.json",
  "index_time.json",
  "last_intent.json",
  "last_qmd_recall.json",
  "last_recall.json",
  "lcm.sqlite-shm",
  "lcm.sqlite-wal",
  "memory-lifecycle-ledger.jsonl",
  "recall_impressions.jsonl",
]);

const ABSENT_INCOMING_RUNTIME_DELETE_FILES = new Set([
  "lcm.sqlite-shm",
  "lcm.sqlite-wal",
]);

// Sharded embedding index (#3146): remote-authoritative like embeddings.json.
function isRemoteAuthoritativeRuntimeShard(basename: string, parts: string[]): boolean {
  return EMBEDDING_SHARD_FILE_PATTERN.test(basename) && parts[parts.length - 2] === "embeddings";
}

/**
 * Per-session buffer state files (`state/buffer/<session>.json`) are
 * remote-authoritative like the legacy single `state/buffer.json` they
 * replaced: the incoming copy wins so two nodes do not each keep their own
 * version of the same session's buffered turns.
 */
function isRemoteAuthoritativeBufferSessionFile(parts: string[]): boolean {
  const basename = parts[parts.length - 1] ?? "";
  // Matches both `state/buffer/<session>.json` and the namespace-scoped
  // `namespaces/<ns>/state/buffer/<session>.json`.
  return (
    parts.length >= 3 &&
    parts[parts.length - 2] === "buffer" &&
    parts[parts.length - 3] === "state" &&
    basename.endsWith(".json")
  );
}

export function shouldPreferIncomingOfflineRuntimeFile(relPosix: string): boolean {
  const parts = relPosix.split("/");
  const basename = parts[parts.length - 1] ?? "";
  return (
    isCanonicalRuntimeStatePath(parts) &&
    (REMOTE_AUTHORITATIVE_RUNTIME_STATE_FILES.has(basename) ||
      isRemoteAuthoritativeRuntimeShard(basename, parts) ||
      isRemoteAuthoritativeBufferSessionFile(parts))
  );
}

export function shouldDeleteAbsentIncomingOfflineRuntimeFile(relPosix: string): boolean {
  const parts = relPosix.split("/");
  const basename = parts[parts.length - 1] ?? "";
  return isCanonicalRuntimeStatePath(parts) && ABSENT_INCOMING_RUNTIME_DELETE_FILES.has(basename);
}

import { createHash, randomUUID } from "node:crypto";
import {
  lstat,
  mkdir,
  open,
  readdir,
  readFile,
  realpath,
  rename,
  rm,
  stat,
  writeFile,
} from "node:fs/promises";
import path from "node:path";

const fatalUtf8Decoder = new TextDecoder("utf-8", { fatal: true, ignoreBOM: true });

export async function sha256File(filePath: string): Promise<{ sha256: string; bytes: number }> {
  const buf = await readFile(filePath);
  const sha256 = createHash("sha256").update(buf).digest("hex");
  return { sha256, bytes: buf.byteLength };
}

export function sha256Bytes(content: Uint8Array): { sha256: string; bytes: number } {
  const buf = Buffer.from(content);
  const sha256 = createHash("sha256").update(buf).digest("hex");
  return { sha256, bytes: buf.byteLength };
}

export function sha256String(content: string): { sha256: string; bytes: number } {
  return sha256Bytes(Buffer.from(content, "utf-8"));
}

export async function readUtf8FileStrict(filePath: string): Promise<{ content: string; sha256: string; bytes: number }> {
  const buf = await readFile(filePath);
  let content: string;
  try {
    content = fatalUtf8Decoder.decode(buf);
  } catch {
    throw new Error(`transfer export requires UTF-8 text files: ${filePath}`);
  }
  return { content, ...sha256Bytes(buf) };
}

export async function writeJsonFile(filePath: string, value: unknown): Promise<void> {
  await mkdir(path.dirname(filePath), { recursive: true });
  await writeFile(filePath, JSON.stringify(value, null, 2) + "\n", "utf-8");
}

export async function readJsonFile<T>(filePath: string): Promise<T> {
  const raw = await readFile(filePath, "utf-8");
  return JSON.parse(raw) as T;
}

export async function listFilesRecursive(rootDir: string): Promise<string[]> {
  const out: string[] = [];
  async function walk(dir: string): Promise<void> {
    const entries = await readdir(dir, { withFileTypes: true });
    for (const ent of entries) {
      const fp = path.join(dir, ent.name);
      if (ent.isDirectory()) {
        await walk(fp);
      } else if (ent.isFile()) {
        out.push(fp);
      }
    }
  }
  await walk(rootDir);
  return out.sort();
}

export async function ensureDirExists(dirPath: string): Promise<void> {
  await mkdir(dirPath, { recursive: true });
}

export async function fileExists(filePath: string): Promise<boolean> {
  try {
    await stat(filePath);
    return true;
  } catch {
    return false;
  }
}

export function toPosixRelPath(absPath: string, rootDir: string): string {
  const rel = path.relative(rootDir, absPath);
  // normalize to posix for portability across platforms
  return rel.split(path.sep).join("/");
}

export function fromPosixRelPath(relPath: string): string {
  return relPath.split("/").join(path.sep);
}

export interface SafeArchiveRoot {
  abs: string;
  real: string;
  errorPrefix: string;
  argName: string;
}

export async function prepareSafeArchiveRoot(
  absPath: string,
  errorPrefix: string,
  argName: string,
): Promise<SafeArchiveRoot> {
  const rootAbs = path.resolve(absPath);
  await assertIsDirectoryNotSymlink(rootAbs, errorPrefix, argName);
  return {
    abs: rootAbs,
    real: await realpath(rootAbs),
    errorPrefix,
    argName,
  };
}

export function validateArchiveRelativePath(
  relPath: string,
  errorPrefix: string,
): string {
  if (relPath.length === 0) {
    throw new Error(`${errorPrefix}: record path must not be empty`);
  }
  if (relPath.includes("\\")) {
    throw new Error(
      `${errorPrefix}: record path must use POSIX separators: ${relPath}`,
    );
  }
  if (path.posix.isAbsolute(relPath)) {
    throw new Error(
      `${errorPrefix}: record path must be relative: ${relPath}`,
    );
  }

  const segments = relPath.split("/");
  if (segments.some((segment) => segment === "" || segment === "." || segment === "..")) {
    throw new Error(
      `${errorPrefix}: record path contains unsafe segments: ${relPath}`,
    );
  }

  const normalized = path.posix.normalize(relPath);
  if (
    normalized === "." ||
    normalized === ".." ||
    normalized.startsWith("../") ||
    path.posix.isAbsolute(normalized)
  ) {
    throw new Error(
      `${errorPrefix}: record path escapes target root: ${relPath}`,
    );
  }

  return normalized;
}

export async function resolveSafeArchiveTarget(
  root: SafeArchiveRoot,
  relPath: string,
): Promise<string> {
  const safeRelPath = validateArchiveRelativePath(relPath, root.errorPrefix);
  const targetAbs = path.resolve(root.abs, fromPosixRelPath(safeRelPath));
  if (!isPathInsideRoot(root.abs, targetAbs)) {
    throw new Error(
      `${root.errorPrefix}: record path escapes target root: ${relPath}`,
    );
  }

  const targetStat = await lstat(targetAbs).catch((error: unknown) => {
    if ((error as NodeJS.ErrnoException).code === "ENOENT") return null;
    throw error;
  });
  if (targetStat?.isSymbolicLink()) {
    throw new Error(
      `${root.errorPrefix}: record path targets a symlink: ${relPath}`,
    );
  }

  await assertRealpathInsideRoot(
    root.real,
    targetAbs,
    relPath,
    root.errorPrefix,
  );
  return targetAbs;
}

export async function writeSafeArchiveTarget(
  root: SafeArchiveRoot,
  relPath: string,
  content: string | Uint8Array,
): Promise<void> {
  const targetAbs = await resolveSafeArchiveTarget(root, relPath);
  const parentAbs = path.dirname(targetAbs);
  await mkdir(parentAbs, { recursive: true });
  await assertRealpathInsideRoot(
    root.real,
    parentAbs,
    relPath,
    root.errorPrefix,
  );
  const parentStat = await lstat(parentAbs);
  if (!parentStat.isDirectory() || parentStat.isSymbolicLink()) {
    throw new Error(
      `${root.errorPrefix}: record path parent is not a safe directory: ${relPath}`,
    );
  }
  const targetStat = await lstat(targetAbs).catch((error: unknown) => {
    if ((error as NodeJS.ErrnoException).code === "ENOENT") return null;
    throw error;
  });
  if (targetStat?.isSymbolicLink()) {
    throw new Error(
      `${root.errorPrefix}: record path targets a symlink: ${relPath}`,
    );
  }

  const tempAbs = path.join(parentAbs, `.remnic-import-${process.pid}-${randomUUID()}.tmp`);
  let renamed = false;
  try {
    const handle = await open(tempAbs, "wx", 0o600);
    try {
      await handle.writeFile(content);
    } finally {
      await handle.close();
    }
    await rename(tempAbs, targetAbs);
    renamed = true;
  } finally {
    if (!renamed) {
      await rm(tempAbs, { force: true }).catch(() => undefined);
    }
  }
}

// ---------------------------------------------------------------------------
// Shared path-safety helpers (used by capsule-import, capsule-merge, and
// capsule-fork).
//
// These helpers are security-critical (path-traversal and symlink-bypass
// guards), so any future fix must apply uniformly. The `errorPrefix` and
// `argName` arguments let each caller surface module-specific error messages
// ("importCapsule:" vs "mergeCapsule:" vs "forkCapsule:") without forking the
// implementation.
// ---------------------------------------------------------------------------

/**
 * Return true when {@link absPath} is the same as {@link rootReal} or a
 * descendant. {@link rootReal} should be the value returned by
 * `realpath(rootAbs)` so that symlinked subdirectories are detected.
 */
export function isPathInsideRoot(rootReal: string, absPath: string): boolean {
  const rel = path.relative(rootReal, absPath);
  if (rel === "") return true;
  if (rel === "..") return false;
  if (rel.startsWith(`..${path.sep}`)) return false;
  if (path.isAbsolute(rel)) return false;
  return true;
}

/**
 * Assert that {@link absPath} is an existing directory and is not itself a
 * symlink. `existsSync` returns true for files (gotcha #24); a stat-based
 * check is required. Symlinked roots are rejected up-front so an attacker
 * cannot hand the importer a `~/import-target` link → `/etc` and have writes
 * silently follow the link (Codex P1 round 5 thread on PR #741).
 */
export async function assertIsDirectoryNotSymlink(
  absPath: string,
  errorPrefix: string,
  argName: string,
): Promise<void> {
  const st = await stat(absPath).catch(() => null);
  if (!st || !st.isDirectory()) {
    throw new Error(
      `${errorPrefix}: '${argName}' must be an existing directory: ${absPath}`,
    );
  }
  const lst = await lstat(absPath).catch(() => null);
  if (lst && lst.isSymbolicLink()) {
    throw new Error(
      `${errorPrefix}: '${argName}' must not be a symlink — resolve it to its real path first: ${absPath}`,
    );
  }
}

/**
 * Walk upward from {@link targetAbs} to find the nearest existing ancestor,
 * resolve it via `fs.realpath` (which follows symlinks), then re-append the
 * remaining suffix and verify the result is inside {@link rootReal}.
 *
 * This catches the case where an existing subdirectory at any point in the
 * path is a symlink that points outside the intended root. Because the file
 * does not exist yet we cannot realpath it directly; we resolve the deepest
 * existing prefix and re-apply the non-existent suffix. Callers must ensure
 * {@link rootReal} was already resolved via `realpath`.
 */
export async function assertRealpathInsideRoot(
  rootReal: string,
  targetAbs: string,
  sourcePath: string,
  errorPrefix: string,
): Promise<void> {
  let existing = targetAbs;
  const suffix: string[] = [];
  while (existing !== path.dirname(existing)) {
    const st = await lstat(existing).catch(() => null);
    if (st !== null) break;
    suffix.unshift(path.basename(existing));
    existing = path.dirname(existing);
  }
  const existingReal = await realpath(existing).catch(() => existing);
  const targetReal =
    suffix.length > 0 ? path.join(existingReal, ...suffix) : existingReal;
  if (!isPathInsideRoot(rootReal, targetReal)) {
    throw new Error(
      `${errorPrefix}: record path escapes target root via symlink: ${sourcePath}`,
    );
  }
}

// Node-local warm-cache generation marker (`<stateDir>/embeddings.generation`).
// Two-phase publication barrier: in-flight before a publication's first
// destructive write, fresh unique value after its last write (PR #3176), so a
// completed stamp is only ever stable while generation bytes are unchanged.
// Single owner of the atomic protocol and logging — the store's own mutations
// and the offline-sync direct write/delete paths (issue #3182) share it.
// Plain fs always (tmp + rename): the marker is node-local raw bytes, never
// sync traffic or secure-store content.
import { randomUUID } from "node:crypto";
import { rename, rm, writeFile } from "node:fs/promises";
import path from "node:path";

import { log } from "./logger.js";

export const GENERATION_MARKER_BASENAME = "embeddings.generation";

/** Reserved in-flight marker value; never equals a completion marker. */
export const GENERATION_MARKER_IN_FLIGHT = "in-flight";

export function generationMarkerPath(stateDirAbs: string): string {
  return path.join(stateDirAbs, GENERATION_MARKER_BASENAME);
}

/** Strict atomic marker write; recovery uses it for a fresh completed value. */
export async function writeGenerationMarkerRaw(markerAbs: string, value: string): Promise<void> {
  const tempPath = `${markerAbs}.tmp-${process.pid}-${Date.now()}-${Math.random().toString(16).slice(2)}`;
  try {
    await writeFile(tempPath, value, "utf-8");
    await rename(tempPath, markerAbs);
  } catch (err) {
    await rm(tempPath, { force: true }).catch(() => undefined);
    throw err;
  }
}

/** Barrier first half: strict, so bytes can never change under a stable stamp. */
export async function beginGenerationMarker(markerAbs: string): Promise<void> {
  await writeGenerationMarkerRaw(markerAbs, GENERATION_MARKER_IN_FLIGHT);
}

/**
 * Barrier second half: written after the last content write. Best-effort:
 * a failure leaves the in-flight marker, whose stamp identityStamp()
 * never repeats, so cached probes revalidate on every search until a
 * publication completes.
 */
export async function completeGenerationMarker(markerAbs: string): Promise<void> {
  await writeGenerationMarkerRaw(markerAbs, randomUUID()).catch((err) => {
    log.warn(`embedding index: could not write generation completion marker: ${err instanceof Error ? err.message : String(err)}`);
  });
}

// Cross-process embedding-generation mutation lock (issue #3148, Codex P1).
//
// Two processes legitimately mutate the SAME embedding generation: the
// daemon's EmbeddingFallback index mutations (load → modify → persist) and
// the offline-sync apply transaction (census → stage → swap) — plus the
// snapshot walkers that must capture one COMPLETE generation. All of them
// enumerate or replace `state/embeddings/` (or the legacy marker), so an
// unsynchronized writer's bytes are silently discarded by the other side's
// wholesale directory swap.
//
// Built directly on the existing utilities: `serializeMutations` (in-process
// keyed chain, rejection-recovering — gotcha #40) around `withHeldFileLock`
// (cross-process held advisory lock, replacement-safe stale breaking,
// ownership-checked release). A lock that cannot be acquired within the
// bounded wait FAILS CLOSED — proceeding unsynchronized would reintroduce
// the lost-write race this lock exists to prevent.
//
// The lock is keyed by the PHYSICAL state directory (dirname of the
// generation's shard dir / of the legacy marker), so every caller
// convention — memory-root-relative (`namespaces/<ns>/state`) or
// namespace-scoped roots (`<ns>/state`) — contends on the SAME lock file
// for the same generation. The lock file lives under that state dir's
// `.offline-sync/` (sync-internal, excluded from every offline-sync
// snapshot by the default excludes).
import path from "node:path";
import { type HeldFileLockController, serializeMutations, withHeldFileLock } from "./utils/serialize-mutations.js";

/** Stale-lock window for a crashed holder (mirrors the graph lock). */
const LOCK_STALE_MS = 30_000;
/** Bounded acquisition wait; a busy lock FAILS the operation (strict). */
const LOCK_MAX_WAIT_MS = 10_000;

/** Control surface handed to a held embedding-generation lock section. */
export type EmbeddingGenerationLockSection = HeldFileLockController;

/**
 * A fence the store calls immediately before a destructive write: reasserts
 * lock ownership so a peer that stale-broke and replaced the lock aborts
 * this write instead of clobbering the peer's.
 */
export type EmbeddingGenerationFence = () => Promise<void>;

/**
 * A held embedding-generation lock section was lost mid-critical-section —
 * a peer stale-broke and replaced it. Abort; never publish.
 */
export class EmbeddingGenerationLockLostError extends Error {
  constructor(lockPath: string) {
    super(
      `embedding generation: the mutation lock for ${lockPath} was lost mid-section — a peer stale-broke and replaced it; aborting instead of clobbering the peer's write`
    );
    this.name = "EmbeddingGenerationLockLostError";
  }
}

/** The generation lock could not be acquired; callers fail closed and report it. */
export class EmbeddingGenerationLockUnavailableError extends Error {
  constructor(lockPath: string, reason: "timeout" | "error") {
    super(`embedding generation: could not acquire the mutation lock for ${lockPath} (${reason})`);
    this.name = "EmbeddingGenerationLockUnavailableError";
  }
}

/**
 * The lock file path for the generation whose canonical state dir is
 * `absoluteStateDir` (physical path; e.g. `<memoryRoot>/state` or
 * `<memoryRoot>/namespaces/<ns>/state`). Keyed by the physical directory so
 * every root convention contends on one lock file per generation.
 */
export function embeddingGenerationLockPath(absoluteStateDir: string): string {
  const stateDir = path.resolve(absoluteStateDir);
  return path.join(stateDir, ".offline-sync", "locks", "embedding-generation.lock");
}

/**
 * Revalidate lock ownership immediately before a destructive publish.
 * Throws {@link EmbeddingGenerationLockLostError} when the lock was
 * broken/replaced, so the caller aborts and leaves the peer's write intact.
 */
export async function assertEmbeddingGenerationLockHeld(
  lockPath: string,
  section: EmbeddingGenerationLockSection
): Promise<void> {
  if (!(await section.refresh())) throw new EmbeddingGenerationLockLostError(lockPath);
}

/**
 * Run `fn` while holding the embedding-generation mutation lock for the
 * generation whose state dir is `absoluteStateDir`, handing it the section
 * controller. `serializeMutations` provides the in-process keyed chain
 * INSIDE the cross-process advisory lock, so peers serialize against every
 * section this process runs, one at a time. Times out fail-closed.
 */
export function withEmbeddingGenerationLock<T>(
  absoluteStateDir: string,
  fn: (lock: EmbeddingGenerationLockSection) => Promise<T>
): Promise<T> {
  const lockPath = embeddingGenerationLockPath(absoluteStateDir);
  return serializeMutations(lockPath, () =>
    withHeldFileLock(lockPath, { staleMs: LOCK_STALE_MS, maxWaitMs: LOCK_MAX_WAIT_MS }, (acquired, lock) => {
      if (!acquired) {
        throw new EmbeddingGenerationLockUnavailableError(lockPath, lock.failure ?? "error");
      }
      return fn(lock);
    })
  );
}

/** Capture a complete bounded digest census under lock, then stream outside
 * the lock. If any member changes, throw rather than emit a complete subset. */
export async function* withEmbeddingGenerationLockIter<T extends { path: string; sha256: string; bytes: number }>(
  absoluteStateDir: string,
  make: (includeContent: boolean) => AsyncIterable<T>,
  includeContent: boolean,
  verify?: () => Promise<void>
): AsyncIterable<T> {
  const lockPath = embeddingGenerationLockPath(absoluteStateDir);
  // Capture only bounded metadata under the lock, never large content or
  // network backpressure. Every emitted record must match this complete
  // generation census; a concurrent swap/dirty write aborts the stream.
  const baseline = await withEmbeddingGenerationLock(absoluteStateDir, async (section) => {
    await verify?.();
    const records: Array<{ path: string; sha256: string; bytes: number }> = [];
    for await (const record of make(false)) {
      await assertEmbeddingGenerationLockHeld(lockPath, section);
      records.push({ path: record.path, sha256: record.sha256, bytes: record.bytes });
    }
    return records;
  });
  let count = 0;
  for await (const record of make(includeContent)) {
    const expected = baseline[count++];
    if (!expected || expected.path !== record.path || expected.sha256 !== record.sha256 || expected.bytes !== record.bytes) {
      throw new Error(`embedding generation changed while streaming ${absoluteStateDir}; retry the snapshot`);
    }
    yield record;
  }
  if (count !== baseline.length) {
    throw new Error(`embedding generation changed while streaming ${absoluteStateDir}; retry the snapshot`);
  }
}

// Issue #1786: node-local runtime state that each node rebuilds from synced
// records. Pushing these wastes bandwidth, corrupts the remote's live state
// dir, and trips the large-file push retry loop on a live SQLite database.
// Extracted from offline-sync.ts (issue #1995) so the god-file line-count
// ratchet does not grow when the list gains entries; behavior is unchanged.
/**
 * Directory-name prefix for the transient plaintext staging dir the CLI offline
 * decrypt path (`offline-storage-io.ts`) creates under the memory root when it
 * must materialize a decrypted secure-store file before hashing/pushing (#2033
 * P1). Shared here so the hard-exclude glob below and the CLI's `mkdtemp` prefix
 * can never drift apart: a crash-orphaned staging dir must NEVER be enumerated
 * into an offline snapshot, or decrypted secure-store plaintext would leak into
 * the remote push.
 */
export const OFFLINE_DECRYPT_STAGING_DIR_PREFIX = ".remnic-offline-decrypt-";

export const DEFAULT_OFFLINE_SYNC_EXCLUDE_GLOBS: readonly string[] = [
  // Leading `**/` matches zero or more segments, so each pattern covers both
  // the root `state/` dir AND per-namespace `namespaces/<ns>/state/` dirs
  // (Cursor review on PR #1793: multi-namespace deployments previously kept
  // pushing their namespaced live sqlite files).
  "**/state/*.sqlite",
  "**/state/*.sqlite-*",
  "**/state/index_tags.json",
  "**/state/entity-mention-index.json",
  "**/state/memory-governance/runs/**",
  // Rotated recall-impression archives (issue #1910). The active
  // recall_impressions.jsonl stays remote-authoritative; only the .1..N
  // archives and the .lock are node-local and never pushed/hashed.
  "**/state/recall_impressions.jsonl.*",
  // Durable recall-impression pending spill directory (issue #2033). Node-local:
  // an impression spills a per-event file here when its rotation lock cannot be
  // acquired, and the next lock holder folds them back into the synced active
  // recall_impressions.jsonl. The `.*` glob above matches the directory name but
  // not its children, so exclude the contents explicitly.
  "**/state/recall_impressions.jsonl.pending.d/**",
  // Durable lifecycle-append pending spill directory (issue #2033). Node-local:
  // an append spills a per-event file here when it cannot get the ledger lock,
  // and the next lock holder folds them back into the synced
  // memory-lifecycle-ledger.jsonl. Pushing them would duplicate rows remotely.
  // The offline-sync snapshot entrypoints drain this queue first (access-service
  // `drainPendingLifecycleForSync` -> `StorageManager.drainPendingMemoryLifecycleEventsForSync`),
  // aborting the snapshot when durable rows cannot be folded, so excluding the
  // dir never silently drops append-only lifecycle history (promotions/imports).
  "**/state/memory-lifecycle-ledger.jsonl.pending.d/**",
  // The active lifecycle ledger lock is node-local and must never be
  // transferred to another node during an offline snapshot.
  "**/state/memory-lifecycle-ledger.jsonl.lock",
  // Transient plaintext decrypt staging (issue #2033 P1). The CLI offline
  // decrypt path materializes a decrypted secure-store file under an owner-only
  // `<OFFLINE_DECRYPT_STAGING_DIR_PREFIX>*` dir before hashing/pushing, removing
  // it in a `finally`. A hard crash between create and cleanup would otherwise
  // let a later snapshot walk `<prefix>*/content` and push decrypted secure-store
  // plaintext to the remote. Exclude the dir and its contents unconditionally so
  // a crash-orphan can never be enumerated into a snapshot; the leading `**/`
  // matches the root-level dir (zero segments) and any nested placement.
  "**/.remnic-offline-decrypt-*/**",
  // Embedding-index transaction leftovers (issue #3146, PR #3148). The
  // identity-replacement backup (`embeddings.pre-replace.tmp`) can hold a
  // full obsolete generation and `embeddings.staging.tmp-*` holds a
  // partially staged one; both are node-local recovery state that must
  // never be enumerated into a snapshot. The demoted legacy recovery file
  // (`embeddings.json.pre-migration.tmp-*`) is likewise node-local.
  "**/state/embeddings.pre-replace.tmp/**",
  "**/state/embeddings.staging.tmp-*/**",
  "**/state/embeddings.json.pre-migration.tmp-*",
  "**/namespaces/*/state/embeddings.pre-replace.tmp/**",
  "**/namespaces/*/state/embeddings.staging.tmp-*/**",
  "**/namespaces/*/state/embeddings.json.pre-migration.tmp-*",
  // The warm-cache generation marker (PR #3176) is node-local coherence
  // state: a synced copy — worse, a captured `in-flight` value — would make
  // the receiving node's stamp probes unique forever and force a full index
  // reload on every search. Exclude on both sides: never snapshotted, and
  // an incoming (old or hostile) marker never overwrites or deletes the
  // local one.
  "**/state/embeddings.generation",
  "**/namespaces/*/state/embeddings.generation",
];


const DEFAULT_OFFLINE_SYNC_EXCLUDE_REGEXPS: readonly RegExp[] =
  DEFAULT_OFFLINE_SYNC_EXCLUDE_GLOBS.map((glob) => globToRegExp(glob));

/**
 * The warm-cache generation marker is the one default-excluded path that
 * must ALSO be refused on apply (push-side default excludes like the live
 * LCM sqlite are deliberately apply-accepted for first-sync bootstrapping).
 * Node-local on both sides: never snapshotted, never overwritten by an
 * incoming old or hostile copy.
 */
export function isEmbeddingGenerationMarkerPath(relPosix: string): boolean {
  const normalized = relPosix.includes("\\") ? relPosix.replaceAll("\\", "/") : relPosix;
  // Case-insensitive: on APFS/NTFS a differently cased path resolves to the
  // same file, so `state/Embeddings.Generation` must be refused like the
  // canonical spelling.
  return /(?:^|\/)state\/embeddings\.generation$/i.test(normalized);
}

/**
 * Precompiled-once default-exclude check for the snapshot enumeration hot
 * path (Kilo review, PR #1793). Moved here from offline-sync.ts with the
 * glob list so the two can never drift (issue #1995).
 */
export function matchesOfflineSyncDefaultExclude(relPosix: string): boolean {
  for (const regexp of DEFAULT_OFFLINE_SYNC_EXCLUDE_REGEXPS) {
    if (regexp.test(relPosix)) return true;
  }
  return false;
}

export function globToRegExp(glob: string): RegExp {
  if (typeof glob !== "string" || glob.length === 0) {
    throw new Error("offlineSyncExcludes entry must be a non-empty string");
  }
  if (glob.includes("\0")) {
    throw new Error("offlineSyncExcludes entry must not contain NUL bytes");
  }
  let source = "";
  for (let i = 0; i < glob.length; i += 1) {
    const ch = glob[i];
    if (ch === "*") {
      if (glob[i + 1] === "*") {
        // `**` is cross-segment wherever it appears:
        //   leading `**/`  -> zero or more whole segments
        //   `/**` at end   -> everything under the directory
        //   `a/**/b`       -> any depth between segments
        // (Cursor review on PR #1793: trailing `scratch/**` must match
        // nested `scratch/a/b.md`, matching the offline-mode guide.)
        if (glob[i + 2] === "/") {
          source += "(?:[\\s\\S]*/)?";
          i += 2;
          continue;
        }
        source += "[\\s\\S]*";
        i += 1;
        continue;
      }
      source += "[^/]*";
      continue;
    }
    if (ch === "?") {
      source += "[^/]";
      continue;
    }
    if (ch === "/") {
      source += "/";
      continue;
    }
    source += ch.replace(/[\\^$.+()|{}\[\]]/g, "\\$&");
  }
  return new RegExp(`^${source}$`);
}

/** Match relative POSIX paths: `*` stays within a segment; `**` crosses separators and matches every path alone. */
export function compileOfflineSyncExcludeGlobs(
  globs: readonly unknown[],
): RegExp[] {
  const out: RegExp[] = [];
  for (const entry of globs) {
    if (typeof entry !== "string" || entry.length === 0) {
      throw new Error("offlineSyncExcludes must contain only non-empty strings");
    }
    out.push(globToRegExp(entry));
  }
  return out;
}

/**
 * Validate the operator-supplied offline-sync exclude list (#1786).
 * Rejects loudly instead of silently defaulting (CLAUDE.md rule 39):
 * a misspelled key value must fail config parse, not be ignored.
 * Lives next to the glob compiler so config.ts only carries the call.
 */
export function parseOfflineSyncExcludes(raw: unknown): string[] {
  if (raw === undefined || raw === null) return [];
  if (!Array.isArray(raw)) {
    throw new Error(
      `offlineSyncExcludes must be an array of non-empty glob strings; got ${typeof raw}`,
    );
  }
  for (const entry of raw) {
    if (typeof entry !== "string" || entry.trim().length === 0) {
      throw new Error(
        "offlineSyncExcludes must contain only non-empty glob strings",
      );
    }
  }
  const globs = raw.map((entry) => (entry as string).trim());
  // Compile-check every glob now so a bad pattern fails at parse time
  // rather than mid-sync. compileOfflineSyncExcludeGlobs throws with a
  // per-entry message.
  compileOfflineSyncExcludeGlobs(globs);
  return globs;
}

/**
 * Cross-process-safe write lock for graph JSONL files (issue #2330 round
 * N+18 A). Sibling of graph.ts — extracted there so graph.ts stays within
 * its file-size ratchet; graph.ts re-exports {@link withGraphWriteLock}
 * because `@remnic/core/graph` is a public subpath export.
 *
 * Three layers, one per section:
 *
 * 1. An in-process promise chain keyed by JSONL file path (gotcha #40):
 *    the append path (`appendEdge`) and the rewrite path used by the decay
 *    maintenance job serialize on the same lock. Without this, an
 *    extraction can append a new edge between the decay job's
 *    read-snapshot and rewrite, silently dropping the appended edge during
 *    active traffic (issue #729 / Codex P1).
 *
 * 2. A cross-process advisory lock: the promise chain only serializes THIS
 *    process. A peer Remnic process sharing the memory directory could
 *    append an edge after this process reads its JSONL snapshot but before
 *    the rename-backed rewrite publishes, permanently discarding the
 *    peer's edge — so every section also holds the established
 *    `withHeldFileLock` advisory lock (the same primitive round N+16 gave
 *    the page-versioning manifest) as a sibling `<file>.lock`. A lock that
 *    cannot be taken within the bounded wait FAILS the write (strict,
 *    matching the manifest): proceeding unsynchronized would reintroduce
 *    the lost-write race the lock exists to prevent. Graph write callers
 *    are fail-open, so the surfaced error degrades to a logged skip.
 *
 * 3. Ownership revalidation before destructive writes (round N+19 A): the
 *    lock's mtime heartbeat is a TIMER — it cannot fire while a
 *    synchronous parse/serialize of a large graph blocks the event loop.
 *    A peer can then judge the lock stale past the 30s window, break it,
 *    and publish its own write. Every section therefore receives the
 *    lock's {@link GraphWriteLockSection} controller and MUST pass it to
 *    {@link assertGraphLockHeld} immediately before publishing a
 *    replacement (or appending): a lost lock aborts THIS write with
 *    {@link GraphLockLostError} instead of clobbering the peer's. Long
 *    CPU passes inside a section should await {@link
 *    yieldForLockHeartbeat} every few thousand rows so the heartbeat
 *    timer gets a turn and the section is less likely to be broken in
 *    the first place.
 */

import { withHeldFileLock, type HeldFileLockController } from "./utils/serialize-mutations.js";

const graphWriteLocks = new Map<string, Promise<void>>();

/** Stale-lock window for the cross-process graph lock (crashed holder). */
const GRAPH_LOCK_STALE_MS = 30_000;
/** Bounded acquisition wait for the cross-process graph lock. */
const GRAPH_LOCK_MAX_WAIT_MS = 10_000;

/** Control surface handed to a graph write-lock section (round N+19 A). */
export type GraphWriteLockSection = HeldFileLockController;

/**
 * A graph write section lost its advisory lock mid-critical-section — a peer
 * stale-broke and replaced it while this process's event loop was blocked.
 * The thrower has NOT published its write; callers treat it like any other
 * write failure (graph callers are fail-open).
 */
export class GraphLockLostError extends Error {
  constructor(filePath: string) {
    super(
      `graph: the write lock for ${filePath} was lost mid-section — a peer stale-broke and replaced it; aborting this write instead of clobbering the peer's`,
    );
    this.name = "GraphLockLostError";
  }
}

/**
 * Revalidate lock ownership immediately before a destructive graph write.
 * Throws {@link GraphLockLostError} when the lock was broken/replaced, so the
 * caller aborts and leaves the peer's write intact.
 */
export async function assertGraphLockHeld(
  filePath: string,
  lock: GraphWriteLockSection,
): Promise<void> {
  if (!(await lock.refresh())) throw new GraphLockLostError(filePath);
}

/**
 * Yield one event-loop turn so the lock's heartbeat timer can fire during a
 * long, CPU-bound parse/serialize/decay pass inside a held graph lock
 * section (round N+19 A). `setImmediate` runs in the check phase, after any
 * due timers, so each yield lets an overdue heartbeat stamp the lock's mtime
 * before a peer judges it stale.
 */
export function yieldForLockHeartbeat(): Promise<void> {
  return new Promise<void>((resolve) => setImmediate(resolve));
}

/**
 * Run `fn` while holding the write lock for the given graph JSONL file,
 * handing it the section's {@link GraphWriteLockSection} controller.
 *
 * The lock is keyed by absolute file path so concurrent writes to
 * different graph types proceed independently. The chain recovers from
 * rejection (gotcha #40) so a single I/O failure does not poison all
 * future writers, but the original error is still surfaced to the
 * caller of `withGraphWriteLock`. The in-process chain runs INSIDE the
 * cross-process advisory lock, so peers serialize against every section
 * this process runs, one section at a time.
 */
export function withGraphWriteLock<T>(
  filePath: string,
  fn: (lock: GraphWriteLockSection) => Promise<T>,
): Promise<T> {
  const run = () =>
    withHeldFileLock(
      `${filePath}.lock`,
      { staleMs: GRAPH_LOCK_STALE_MS, maxWaitMs: GRAPH_LOCK_MAX_WAIT_MS },
      (acquired, lock) => {
        if (!acquired) {
          throw new Error(
            `graph: could not acquire the graph write lock for ${filePath} within ${GRAPH_LOCK_MAX_WAIT_MS}ms — another process holds it`,
          );
        }
        return fn(lock);
      },
    );
  const prev = graphWriteLocks.get(filePath) ?? Promise.resolve();
  const next = prev.then(run, run);
  graphWriteLocks.set(
    filePath,
    next.then(
      () => undefined,
      () => undefined
    )
  );
  return next;
}

/**
 * Per-script closed-class cue tables and script-agnostic signal helpers
 * shared by the recall planner heuristics (issue #2191).
 *
 * English keyword regexes stay in their consumers. These tables seed the
 * top ~10 languages so non-English prompts route to the same recall modes
 * as their English equivalents. Substring cues are curated so pure-ASCII
 * entries are multi-word phrases (or non-English single words) that cannot
 * occur in English text — the English corpus behavior is unchanged.
 */

const ASCII_CHARS = /[\u0000-\u007f]/g;
const LETTER_RE = /\p{L}/u;
const WORDISH_RE = /[\p{L}\p{N}]/u;
const QUESTION_MARK_END_RE = /[?？؟]$/u;
const COLON_TERMINATED_RE = /[:：]\s*$/u;

/** True when the text contains a letter outside ASCII — the English keyword
 * tables cannot be assumed to apply. */
export function hasNonAsciiLetter(text: string): boolean {
  return LETTER_RE.test(text.replace(ASCII_CHARS, ""));
}

/** Strip trailing punctuation/symbols/emojis (Unicode-aware) so exact-match
 * ack detection works for "はい。", "merci !", "شكرا" etc. */
export function stripTrailingRecallNoise(text: string): string {
  let candidate = text;
  while (candidate.length > 0) {
    const last = candidate.at(-1) ?? "";
    if (WORDISH_RE.test(last)) break;
    candidate = candidate.slice(0, -1);
  }
  return candidate.trim();
}

/** True when the text ends with an ASCII, fullwidth, or Arabic question mark. */
export function endsWithQuestionMark(text: string): boolean {
  return QUESTION_MARK_END_RE.test(text.trimEnd());
}

export function containsRecallCue(text: string, cues: readonly string[]): boolean {
  const normalized = text.toLowerCase();
  return cues.some((cue) => normalized.includes(cue));
}

