/**
 * Sibling of {@link "./graph.js"} holding the append-failure error type so
 * graph.ts stays within its file-size ratchet cap (issue #1995). Type-only
 * dependency on GraphEdge — no runtime cycle with graph.ts.
 */
import type { GraphEdge } from "./graph.js";

/**
 * Issue #2330 round N+16 (A): thrown by `GraphIndex.onMemoryWritten` when an
 * append fails, carrying the rows this call had ALREADY appended — tracked
 * incrementally as each row is written, before any return value exists. A
 * rollback that only sees the raw failure used to fall back to a node-wide
 * sweep, which also deleted rows a NEWER writer had rebuilt inside the
 * failing writer's window; with the partial set on the error, the rollback
 * stays surgical even on the throwing path. The original failure is
 * preserved as `cause` (create-path callers only log it).
 */
export class GraphEdgeAppendError extends Error {
  readonly appendedEdges: readonly GraphEdge[];
  constructor(cause: unknown, appendedEdges: readonly GraphEdge[]) {
    super(
      `graph edge append failed after ${appendedEdges.length} row(s): ${cause instanceof Error ? cause.message : String(cause)}`,
      { cause },
    );
    this.name = "GraphEdgeAppendError";
    this.appendedEdges = appendedEdges;
  }
}

export interface LcmRowIdentity {
  id?: number;
  session_id?: string;
  turn_index: number;
}

export interface LcmEvidenceIdentity {
  id: string;
  archiveRowId?: number;
}

export function lcmArchiveRowId(row: Pick<LcmRowIdentity, "id">): number | undefined {
  const value = row.id;
  return typeof value === "number" && Number.isSafeInteger(value) && value > 0
    ? value
    : undefined;
}

function resolveSessionId(row: LcmRowIdentity, fallbackSessionId: string): string {
  return row.session_id ?? fallbackSessionId;
}

/**
 * Build the non-rendered evidence identity for an LCM archive row.
 *
 * Older adapters and test doubles may omit the SQLite row id. Those callers
 * retain the historical session+turn identity until they adopt row lineage.
 */
export function lcmEvidenceIdentity(
  row: LcmRowIdentity,
  fallbackSessionId: string,
): LcmEvidenceIdentity {
  const sessionId = resolveSessionId(row, fallbackSessionId);
  const archiveRowId = lcmArchiveRowId(row);
  if (archiveRowId === undefined) {
    return { id: `${sessionId}:${row.turn_index}` };
  }
  return {
    id: JSON.stringify(["lcm-row", sessionId, archiveRowId]),
    archiveRowId,
  };
}

/** Match a search hit to its expanded archive row without conflating siblings. */
export function isSameLcmRow(
  left: LcmRowIdentity,
  leftFallbackSessionId: string,
  right: LcmRowIdentity,
  rightFallbackSessionId: string,
): boolean {
  const leftRowId = lcmArchiveRowId(left);
  const rightRowId = lcmArchiveRowId(right);
  const leftSessionId = resolveSessionId(left, leftFallbackSessionId);
  const rightSessionId = resolveSessionId(right, rightFallbackSessionId);
  if (leftRowId !== undefined && rightRowId !== undefined) {
    return leftRowId === rightRowId && leftSessionId === rightSessionId;
  }
  return leftSessionId === rightSessionId && left.turn_index === right.turn_index;
}

/**
 * Graph edge confidence + reinforcement primitives (issue #681, PR 1/3).
 *
 * Pure functions only — no I/O, no global state. The maintenance job (PR 2/3)
 * and PageRank weighting (PR 3/3) compose these helpers.
 *
 * Schema:
 *   - `confidence`   ∈ [0, 1]; missing on legacy edges, treated as 1.0.
 *   - `lastReinforcedAt` — ISO timestamp of most recent reinforcement; missing
 *     on legacy edges, treated as the original edge `ts`.
 *
 * Defaults documented here are the agreed-on starting points and may be
 * tuned later via config. They live as named constants so call sites and
 * tests share the same values.
 */

import type { GraphEdge } from "./graph.js";

/** Default confidence bump per reinforcement event. */
export const DEFAULT_REINFORCE_DELTA = 0.05;

/** Maximum edge confidence — confidence is capped at this on reinforcement. */
export const CONFIDENCE_CEILING = 1.0;

/** Default decay window in milliseconds (90 days). */
export const DEFAULT_DECAY_WINDOW_MS = 90 * 24 * 60 * 60 * 1000;

/** Default decay floor — confidence will not drop below this purely from age. */
export const DEFAULT_DECAY_FLOOR = 0.1;

/** Default per-window decay amount (linear). */
export const DEFAULT_DECAY_PER_WINDOW = 0.1;

/**
 * Treat a missing `confidence` on a legacy edge as 1.0.
 * Clamps to `[0, CONFIDENCE_CEILING]` so downstream math is well-behaved.
 */
export function readEdgeConfidence(edge: Pick<GraphEdge, "confidence">): number {
  const raw = edge.confidence;
  if (raw === undefined || raw === null || !Number.isFinite(raw)) {
    return CONFIDENCE_CEILING;
  }
  if (raw < 0) return 0;
  if (raw > CONFIDENCE_CEILING) return CONFIDENCE_CEILING;
  return raw;
}

/**
 * Resolve the reference timestamp for decay calculations.
 * Falls back to the edge's creation `ts` when `lastReinforcedAt` is absent
 * (legacy edges have never been reinforced).
 */
export function readLastReinforcedAt(
  edge: Pick<GraphEdge, "lastReinforcedAt" | "ts">,
): string {
  return edge.lastReinforcedAt ?? edge.ts;
}

/**
 * Reinforce an edge: bump confidence by `delta` (capped at 1.0) and stamp
 * `lastReinforcedAt = now`. Pure — returns a new edge, never mutates input.
 *
 * Idempotency note: calling reinforceEdge twice with the same `now` and a
 * delta of 0 returns an edge equal to the input (modulo timestamp).
 *
 * @param edge  the edge to reinforce
 * @param now   ISO timestamp of the reinforcement event
 * @param delta confidence bump; defaults to DEFAULT_REINFORCE_DELTA
 */
export function reinforceEdge(
  edge: GraphEdge,
  now: string,
  delta: number = DEFAULT_REINFORCE_DELTA,
): GraphEdge {
  const current = readEdgeConfidence(edge);
  // Codex P2: reinforcement must never silently decrease confidence.
  // A negative delta sneaking in through parsed config / CLI flags
  // would push strong edges toward zero on every observation. Treat
  // anything below zero as 0 (no-op besides the timestamp bump) so
  // misconfiguration is harmless rather than corrupting.
  const safeDelta =
    Number.isFinite(delta) && delta >= 0 ? delta : 0;
  const next = Math.min(CONFIDENCE_CEILING, Math.max(0, current + safeDelta));
  return {
    ...edge,
    confidence: next,
    lastReinforcedAt: now,
  };
}

/** Options for {@link decayEdgeConfidence}. */
export interface DecayOptions {
  /** Decay window in milliseconds. Defaults to 90 days. */
  windowMs?: number;
  /** Per-window decay amount. Defaults to 0.1. */
  perWindow?: number;
  /** Floor confidence will not decay below. Defaults to 0.1. */
  floor?: number;
}

/**
 * Apply linear decay to an edge's confidence based on time since last
 * reinforcement (or creation, for legacy edges). Pure — returns a new edge.
 *
 * Decay model:
 *   age = now - lastReinforcedAt
 *   if age <= windowMs:           confidence unchanged
 *   else:                          confidence -= perWindow * floor((age - windowMs) / windowMs + 1)
 *   confidence is clamped to [floor, 1.0]
 *
 * Boundary semantics: `age === windowMs` is INSIDE the no-decay grace period
 * (`<=`). Decay only kicks in once age strictly exceeds the window. This
 * keeps the boundary deterministic and easy to test.
 *
 * @param edge edge to decay (confidence and lastReinforcedAt may be absent)
 * @param now  ISO timestamp representing "now"
 * @param opts override window / per-window / floor; otherwise defaults are used
 */
export function decayEdgeConfidence(
  edge: GraphEdge,
  now: string,
  opts: DecayOptions = {},
): GraphEdge {
  const windowMs = opts.windowMs ?? DEFAULT_DECAY_WINDOW_MS;
  const perWindow = opts.perWindow ?? DEFAULT_DECAY_PER_WINDOW;
  const floor = opts.floor ?? DEFAULT_DECAY_FLOOR;

  // Codex P2: reject negative `perWindow` so a misconfigured value
  // doesn't invert the decay equation and silently boost stale
  // edges instead of decaying them. Negative `floor` would also let
  // confidence drop below zero — clamp the floor to [0, 1] so the
  // model stays well-defined.
  if (
    !(windowMs > 0) ||
    !Number.isFinite(perWindow) ||
    perWindow < 0 ||
    !Number.isFinite(floor)
  ) {
    // Degenerate options — return a normalized copy without changing confidence.
    return { ...edge, confidence: readEdgeConfidence(edge) };
  }
  const safeFloor = Math.min(CONFIDENCE_CEILING, Math.max(0, floor));

  const nowMs = Date.parse(now);
  const refMs = Date.parse(readLastReinforcedAt(edge));
  if (!Number.isFinite(nowMs) || !Number.isFinite(refMs)) {
    return { ...edge, confidence: readEdgeConfidence(edge) };
  }

  const age = nowMs - refMs;
  const current = readEdgeConfidence(edge);

  if (age <= windowMs) {
    // Inside the grace period: no decay.
    return { ...edge, confidence: current };
  }

  // Number of full windows past the grace window.
  //
  // Codex P2: the previous formula (`Math.floor((age - windowMs) / windowMs) + 1`)
  // over-counted at exact multiples of the window. At `age === 2 * windowMs`,
  // only ONE post-grace window has elapsed (we're sitting on the boundary
  // of the second), but the old formula returned 2. Switch to a ceiling
  // count: `ceil((age - windowMs) / windowMs)` correctly returns 1 for
  // `windowMs < age <= 2*windowMs`, 2 for `2*windowMs < age <= 3*windowMs`,
  // etc. With the outer `age > windowMs` guard, this always evaluates to
  // a positive integer.
  const windowsPast = Math.ceil((age - windowMs) / windowMs);
  const decayed = current - perWindow * windowsPast;
  // Codex P2: an edge that already sits below `safeFloor` (e.g. an
  // explicit confidence: 0) must NOT be boosted up to the floor by a
  // decay pass. Decay can lower confidence or leave it unchanged — it
  // can never raise it. Cap the result at `current` and only apply
  // the floor when the pre-existing value is still above it.
  const lowerBound = Math.min(safeFloor, current);
  const next = Math.max(lowerBound, Math.min(current, decayed));

  // Cursor Medium round 2 + Codex P1: the anchor must advance by
  // EXACTLY the windows we just charged for — not to `now`. Resetting
  // to `now` makes every decay pass look like a fresh reinforcement
  // and re-applies the grace window on every run, under-decaying
  // stale edges when the maintenance job runs less frequently than
  // `windowMs` (codex P1). Leaving the anchor unchanged compounds
  // decay on frequent calls (cursor Medium). Advancing by
  // `windowsPast * windowMs` from the prior anchor is the right
  // middle ground: subsequent calls see a fresh grace window,
  // decay accrues at most `perWindow` per real `windowMs` regardless
  // of cadence, and historical anchor information is preserved.
  const newRefMs = refMs + windowsPast * windowMs;
  const newRef = new Date(newRefMs).toISOString();
  return { ...edge, confidence: next, lastReinforcedAt: newRef };
}

/**
 * In-process EventEmitter for graph mutation events (issue #691 PR 5/5).
 *
 * The singleton is keyed by memoryDir so multiple orchestrator instances in
 * the same process get distinct event buses (CLAUDE.md rule 11: scope globals
 * per service).  The SSE handler in access-http.ts subscribes to the bus for
 * the resolved namespace and fans out to connected clients.
 *
 * Event types mirror the five mutations the graph layer can produce:
 *   node-added    — a memory file was referenced for the first time
 *   node-updated  — a memory file's metadata changed
 *   edge-added    — a new edge was appended
 *   edge-updated  — an existing edge's confidence/weight was modified
 *   edge-removed  — an edge was pruned (e.g. by decay maintenance)
 *
 * The `GraphEventBus` interface is intentionally narrow so nothing outside
 * this module needs to import Node.js EventEmitter directly.
 */

import { EventEmitter } from "node:events";

// ---------------------------------------------------------------------------
// Public types
// ---------------------------------------------------------------------------

export type GraphEventType =
  | "node-added"
  | "node-updated"
  | "edge-added"
  | "edge-updated"
  | "edge-removed";

export interface GraphEvent {
  type: GraphEventType;
  /** Memory dir that owns this event (absolute path). */
  memoryDir: string;
  /** ISO timestamp of the event. */
  ts: string;
  /** Payload depends on event type — always serialisable to JSON. */
  payload: Record<string, unknown>;
}

export interface NodeAddedPayload {
  nodeId: string;   // relative memory path
  kind: string;
  label: string;
  lastUpdated: string;
}

export interface NodeUpdatedPayload {
  nodeId: string;
  kind: string;
  label: string;
  lastUpdated: string;
}

export interface EdgeAddedPayload {
  source: string;
  target: string;
  kind: string;
  weight: number;
  label: string;
  confidence: number;
}

export interface EdgeUpdatedPayload {
  source: string;
  target: string;
  kind: string;
  weight: number;
  confidence: number;
}

export interface EdgeRemovedPayload {
  source: string;
  target: string;
  kind: string;
}

// ---------------------------------------------------------------------------
// Per-memoryDir singleton bus
// ---------------------------------------------------------------------------

const buses = new Map<string, EventEmitter>();

/**
 * Return (or lazily create) the event bus for the given memoryDir.
 * The same bus is shared by the write side (graph.ts → appendEdge hooks) and
 * the read side (EngramAccessHttpServer SSE handler).
 */
export function getGraphEventBus(memoryDir: string): EventEmitter {
  let bus = buses.get(memoryDir);
  if (!bus) {
    bus = new EventEmitter();
    // Remove the default listener-count warning — SSE clients may hold many
    // concurrent connections. Each SSE client registers one "graph-event"
    // listener; warn only when an unreasonably high count suggests a leak.
    bus.setMaxListeners(200);
    buses.set(memoryDir, bus);
  }
  return bus;
}

/**
 * Emit a single graph event onto the bus for memoryDir.
 * Fails open: any listener that throws is caught so one bad client can't
 * crash the extraction pipeline.
 */
export function emitGraphEvent(
  memoryDir: string,
  type: GraphEventType,
  payload: Record<string, unknown>,
): void {
  const event: GraphEvent = {
    type,
    memoryDir,
    ts: new Date().toISOString(),
    payload,
  };
  const bus = getGraphEventBus(memoryDir);
  for (const listener of bus.listeners("graph-event")) {
    try {
      (listener as (event: GraphEvent) => void)(event);
    } catch {
      // fail-open: never let one subscriber block later listeners or writes
    }
  }
}

/**
 * Subscribe to graph events for a given memoryDir.
 * Returns an unsubscribe function.
 */
export function subscribeGraphEvents(
  memoryDir: string,
  listener: (event: GraphEvent) => void,
): () => void {
  const bus = getGraphEventBus(memoryDir);
  bus.on("graph-event", listener);
  return () => bus.off("graph-event", listener);
}

/**
 * Remove all listeners and the bus entry for a memoryDir.
 * Useful for tests that spin up isolated memory dirs.
 */
export function destroyGraphEventBus(memoryDir: string): void {
  const bus = buses.get(memoryDir);
  if (bus) {
    bus.removeAllListeners();
    buses.delete(memoryDir);
  }
}

import type { ActivationPath, GraphType } from "./graph.js";

export interface ActivationPredecessor {
  prev: string;
  edgeConfidence: number;
  graphType: GraphType;
}

export interface ActivationPathCandidate {
  hopDepth: number;
  landingStrength: number;
  pathKey: string;
}

/** Compare path winners: fewer hops, stronger landing, then lexical path order. */
export function compareActivationPathCandidates(
  left: ActivationPathCandidate,
  right: ActivationPathCandidate,
): number {
  if (left.hopDepth !== right.hopDepth) return right.hopDepth - left.hopDepth;
  if (left.landingStrength !== right.landingStrength) return left.landingStrength - right.landingStrength;
  if (left.pathKey === right.pathKey) return 0;
  return left.pathKey < right.pathKey ? 1 : -1;
}

export class ActivationPathTracker {
  readonly predecessors = new Map<string, ActivationPredecessor>();
  private readonly winners = new Map<string, ActivationPathCandidate>();
  private readonly pathKeys = new Map<string, string>();

  constructor(seeds: Iterable<string>) {
    for (const seed of seeds) {
      this.pathKeys.set(`${seed}\0${seed}`, seed);
    }
  }

  consider(
    seed: string,
    node: string,
    neighbor: string,
    hopDepth: number,
    landingStrength: number,
    edgeConfidence: number,
    graphType: GraphType,
  ): string {
    const sourcePathKey = this.pathKeys.get(`${seed}\0${node}`);
    if (!sourcePathKey) return "";

    const key = `${seed}\0${neighbor}`;
    const pathKey = `${sourcePathKey}\0${neighbor}`;
    const candidate: ActivationPathCandidate = { hopDepth, landingStrength, pathKey };
    const previous = this.winners.get(key);
    if (!previous || compareActivationPathCandidates(candidate, previous) > 0) {
      this.winners.set(key, candidate);
      this.pathKeys.set(key, pathKey);
      this.predecessors.set(key, { prev: node, edgeConfidence, graphType });
    }
    return pathKey;
  }
}
export function reconstructActivationPath(
  seed: string,
  candidate: string,
  predecessors: Map<string, ActivationPredecessor>,
  maxSteps: number,
): ActivationPath | null {
  const nodeIds = [candidate];
  const edgeConfidences: number[] = [];
  const graphTypes: GraphType[] = [];
  let current = candidate;
  const stepCap = Number.isFinite(maxSteps)
    ? Math.max(0, Math.ceil(maxSteps))
    : predecessors.size + 1;
  for (let step = 0; step < stepCap && current !== seed; step += 1) {
    const predecessor = predecessors.get(`${seed}\0${current}`);
    if (!predecessor) return null;
    nodeIds.push(predecessor.prev);
    edgeConfidences.push(predecessor.edgeConfidence);
    graphTypes.push(predecessor.graphType);
    current = predecessor.prev;
  }

  if (current !== seed) return null;
  nodeIds.reverse();
  edgeConfidences.reverse();
  graphTypes.reverse();
  if (edgeConfidences.length !== nodeIds.length - 1 || graphTypes.length !== nodeIds.length - 1) {
    return null;
  }
  return { nodeIds, edgeConfidences, graphTypes };
}

