function positiveInteger(value: unknown, fallback: number, min = 1): number {
  if (typeof value !== "number" || !Number.isFinite(value)) return fallback;
  return Math.max(min, Math.floor(value));
}

function abortOnSignal<T>(abortSignal: AbortSignal | undefined, work: Promise<T>): Promise<T> {
  if (abortSignal === undefined) return work;
  abortSignal.throwIfAborted();
  return new Promise((resolve, reject) => {
    const onAbort = (): void => {
      reject(abortSignal.reason instanceof Error ? abortSignal.reason : new DOMException("Aborted", "AbortError"));
    };
    abortSignal.addEventListener("abort", onAbort, { once: true });
    work.then(resolve, reject).finally(() => abortSignal.removeEventListener("abort", onAbort));
  });
}

export function extractLcmConfig(cfg: PluginConfig): LcmEngineConfig {
  return {
    enabled: (cfg as any).lcmEnabled === true,
    leafBatchSize: positiveInteger((cfg as any).lcmLeafBatchSize, 8),
    rollupFanIn: positiveInteger((cfg as any).lcmRollupFanIn, 4, 2),
    freshTailTurns: positiveInteger((cfg as any).lcmFreshTailTurns, 16),
    maxDepth: positiveInteger((cfg as any).lcmMaxDepth, 5),
    deterministicMaxTokens: positiveInteger((cfg as any).lcmDeterministicMaxTokens, 512),
    archiveRetentionDays: positiveInteger((cfg as any).lcmArchiveRetentionDays, 90, 0),
    recallBudgetShare: (cfg as any).lcmRecallBudgetShare ?? 0.15,
    observeConcurrency:
      typeof (cfg as any).lcmObserveConcurrency === "number" &&
        Number.isFinite((cfg as any).lcmObserveConcurrency)
        ? Math.max(1, Math.floor((cfg as any).lcmObserveConcurrency))
        : 1,
    telemetryPrefilterEnabled: (cfg as any).lcmTelemetryPrefilterEnabled !== false,
    messagePartsEnabled: (cfg as any).messagePartsEnabled === true,
    messagePartsRecallMaxResults:
      typeof (cfg as any).messagePartsRecallMaxResults === "number"
        ? Math.max(0, Math.floor((cfg as any).messagePartsRecallMaxResults))
        : 6,
  };
}

function normalizeLcmSessionId(sessionId: string): string {
  return sessionId.trim();
}

function normalizeOptionalLcmSessionId(sessionId?: string): string | undefined {
  if (sessionId === undefined) {
    return undefined;
  }
  const normalized = normalizeLcmSessionId(sessionId);
  return normalized.length > 0 ? normalized : undefined;
}

const EMPTY_LCM_STATS = {
  totalMessages: 0,
  totalSummaryNodes: 0,
  maxDepth: -1,
} as const;

/**
 * Upper bound on leaf batches summarized by one background job. Keeps a single
 * job's archive read and wall time bounded; leftover batches stay durable and
 * the job re-queues itself.
 */
const LCM_SUMMARIZE_MAX_LEAF_BATCHES_PER_JOB = 16;

/** Retry pacing for a failed summary pass: base delay and backoff ceiling. */
const LCM_SUMMARIZE_RETRY_BASE_MS = 500;
const LCM_SUMMARIZE_RETRY_MAX_MS = 30_000;

export class LcmEngine {
  private db: Database.Database | null = null;
  private archive: LcmArchive | null = null;
  private dag: LcmDag | null = null;
  private summarizer: LcmSummarizer | null = null;
  private observeQueue: LcmWorkQueue | null = null;
  private closed = false;
  private readonly config: LcmEngineConfig;
  private readonly memoryDir: string;
  private initPromise: Promise<void> | null = null;
  private readonly summarizeRetryTimers = new Map<string, NodeJS.Timeout>();
  private readonly summarizeRetryAttempts = new Map<string, number>();
  /** Resolved when the session's pending retry timer has fired or been cleared. */
  private readonly summarizeRetryWaiters = new Map<
    string,
    { promise: Promise<void>; resolve: () => void }
  >();
  /** Explicit idle waiters per session; referenced only while nonzero. */
  private readonly summarizeRetryIdleWaiters = new Map<string, number>();
  /** Base backoff delay; tests shrink it to keep the retry loop fast. */
  private summarizeRetryBaseMs = LCM_SUMMARIZE_RETRY_BASE_MS;
  private readonly pendingObserveInitCounts = new Map<string, number>();
  private readonly pendingObserveInitWaiters = new Map<string, Array<() => void>>();
  private readonly pendingObserveInitIdleWaiters: Array<() => void> = [];

  constructor(
    pluginConfig: PluginConfig,
    private readonly summarizeFn: SummarizeFn,
  ) {
    this.config = extractLcmConfig(pluginConfig);
    this.memoryDir = pluginConfig.memoryDir;
  }

  get enabled(): boolean {
    return this.config.enabled;
  }

  /** Lazy init — open database on first use. */
  async ensureInitialized(): Promise<void> {
    if (this.closed) return;
    if (this.db) return;
    if (this.initPromise) {
      await this.initPromise;
      return;
    }
    this.initPromise = this.doInit().catch((err) => {
      // Reset so next call retries instead of caching the failure
      this.initPromise = null;
      throw err;
    });
    await this.initPromise;
  }

  private async doInit(): Promise<void> {
    await ensureLcmStateDir(this.memoryDir);
    const db = openLcmDatabase(this.memoryDir);
    const archive = new LcmArchive(db);
    const dag = new LcmDag(db);
    const { telemetryPrefilterEnabled } = this.config;
    const summarizer = new LcmSummarizer(
      archive,
      dag,
      this.summarizeFn,
      {
        leafBatchSize: this.config.leafBatchSize,
        rollupFanIn: this.config.rollupFanIn,
        maxDepth: this.config.maxDepth,
        deterministicMaxTokens: this.config.deterministicMaxTokens,
        telemetryPrefilterEnabled,
      },
    );
    const observeQueue = new LcmWorkQueue({
      concurrency: this.config.observeConcurrency,
      worker: async (sessionId) => {
        await this.processSummarizeJob(sessionId);
      },
      hooks: {
        onJobStart: ({ sessionId, depth, inFlight, waitMs }) => {
          log.debug(
            `LCM observe queue start: session=${sessionId}, depth=${depth}, inFlight=${inFlight}, wait=${waitMs}ms`,
          );
        },
        onJobFinish: ({
          sessionId,
          depth,
          inFlight,
          waitMs,
          runMs,
          totalMs,
          error,
        }) => {
          if (error) {
            log.error(
              `LCM observe queue failure: session=${sessionId}, depth=${depth}, inFlight=${inFlight}, wait=${waitMs}ms, run=${runMs}ms, total=${totalMs}ms, error=${error}`,
            );
            return;
          }

          log.debug(
            `LCM observe queue finish: session=${sessionId}, depth=${depth}, inFlight=${inFlight}, wait=${waitMs}ms, run=${runMs}ms, total=${totalMs}ms`,
          );
        },
      },
    });

    if (this.closed) {
      db.close();
      return;
    }

    this.db = db;
    this.archive = archive;
    this.dag = dag;
    this.summarizer = summarizer;
    this.observeQueue = observeQueue;
    this.resumeOutstandingSummaries();
    log.info("LCM engine initialized");
  }

  /**
   * Restart resume: sessions whose durable archive still holds complete
   * unsummarized batches get a summary job without any new observe call.
   * Only session references are queued — the content already lives in SQLite.
   */
  private resumeOutstandingSummaries(): void {
    if (!this.archive || !this.observeQueue) return;
    const sessions = this.archive.listSessionsWithUnsummarizedTurns(
      this.config.leafBatchSize,
    );
    if (sessions.length === 0) return;
    for (const sessionId of sessions) this.observeQueue.enqueue(sessionId);
    log.info(`LCM resume scheduled summary jobs: sessions=${sessions.length}`);
  }

  /**
   * Archive observed messages and schedule background summarization.
   *
   * The archive append completes BEFORE this resolves: an accepted observe is
   * already durable in SQLite, so a crash cannot lose it. Only the
   * summarization is background work, and it resumes from the durable archive.
   */
  async observeMessages(
    sessionId: string,
    messages: LcmObserveMessage[],
  ): Promise<void> {
    const normalizedSessionId = normalizeLcmSessionId(sessionId);
    if (!normalizedSessionId) return;
    await this.enqueueObserveMessages(normalizedSessionId, messages);
  }

  /**
   * Durably archive messages, then queue a metadata-only summary job.
   *
   * Rejects when the archive append fails — callers must not treat a failed
   * archive as an accepted observation.
   */
  async enqueueObserveMessages(
    sessionId: string,
    messages: LcmObserveMessage[],
  ): Promise<void> {
    // LCM off is a feature gate (the caller reports "not archived"); a closed
    // engine is a failure — accepting the turn and archiving nothing would
    // acknowledge a turn the archive never stored.
    if (!this.config.enabled) return;
    if (this.closed) throw new Error("LCM engine is closed");
    const normalizedSessionId = normalizeLcmSessionId(sessionId);
    if (!normalizedSessionId) return;
    if (messages.length === 0) return;

    this.reservePendingObserveInit(normalizedSessionId);

    try {
      await this.ensureInitialized();
      if (this.closed) throw new Error("LCM engine is closed");
      if (!this.archive || !this.observeQueue) {
        throw new Error("LCM engine is not initialized");
      }

      const archived = this.archiveObservedMessages(normalizedSessionId, messages);
      this.observeQueue.enqueue(normalizedSessionId);
      log.debug(
        `LCM observe archived: session=${normalizedSessionId}, messages=${archived}, depth=${this.observeQueue.depth}, inFlight=${this.observeQueue.inFlightCount}`,
      );
    } catch (err) {
      log.error(
        `LCM observe archive failed: session=${normalizedSessionId}, error=${err}${nativeBindingRecoveryHint(err)}`,
      );
      throw err;
    } finally {
      this.releasePendingObserveInit(normalizedSessionId);
    }
  }

  /** Append observed messages to the archive; returns the number of rows. */
  private archiveObservedMessages(
    sessionId: string,
    messages: LcmObserveMessage[],
  ): number {
    const currentMax = this.archive!.getMaxTurnIndex(sessionId);
    const { messagePartsEnabled } = this.config;
    const rows = messages.map((m, i) => ({
      turnIndex: currentMax + 1 + i,
      role: m.role,
      content: m.content,
      parts: messagePartsEnabled ? m.parts : undefined,
      rawContent: messagePartsEnabled ? m.rawContent : undefined,
      sourceFormat: messagePartsEnabled ? m.sourceFormat : undefined,
    }));

    this.archive!.appendMessages(sessionId, rows, { messagePartsEnabled });
    return rows.length;
  }

  /**
   * Summarize one session's durable backlog.
   *
   * The pass is capped so a long backlog never holds a job open indefinitely;
   * remaining batches stay durable and the job re-queues itself.
   */
  private async processSummarizeJob(sessionId: string): Promise<void> {
    if (this.closed) return;
    await this.ensureInitialized();
    if (this.closed || !this.archive || !this.summarizer || !this.observeQueue)
      return;

    try {
      await this.summarizer.summarizeIncremental(sessionId, {
        maxLeafBatches: LCM_SUMMARIZE_MAX_LEAF_BATCHES_PER_JOB,
      });
    } catch (err) {
      // The archived turns are durable; a failed pass must not strand them
      // until the next observe or a restart.
      log.error(`LCM incremental summarization failed: session=${sessionId}, error=${err}`);
      this.scheduleSummarizeRetry(sessionId);
      return;
    }

    this.clearSummarizeRetry(sessionId);

    if (this.hasCompleteBatchPending(sessionId)) {
      this.observeQueue.enqueue(sessionId);
    }
  }

  /**
   * Schedule a metadata-only retry for a failed summary pass.
   *
   * The retry keeps trying for as long as the engine is open and complete
   * batches remain — a transient failure must never strand durable work.
   * What is bounded is the RATE, not the ability to retry: one pending timer
   * per session, exponential backoff capped at
   * {@link LCM_SUMMARIZE_RETRY_MAX_MS}, and an unreferenced timer that is
   * cleared when the engine closes.
   */
  private scheduleSummarizeRetry(sessionId: string): void {
    if (this.closed || this.summarizeRetryTimers.has(sessionId)) return;
    const attempt = (this.summarizeRetryAttempts.get(sessionId) ?? 0) + 1;
    this.summarizeRetryAttempts.set(sessionId, attempt);
    const delayMs = Math.min(
      LCM_SUMMARIZE_RETRY_MAX_MS,
      this.summarizeRetryBaseMs * 2 ** Math.min(attempt - 1, 16),
    );
    // The waiter makes the pending retry visible to idle waits, so a direct
    // flush (pre-compaction) serializes with the retry instead of racing it.
    const retry = Promise.withResolvers<void>();
    this.summarizeRetryWaiters.set(sessionId, retry);
    const timer = setTimeout(() => {
      this.summarizeRetryTimers.delete(sessionId);
      this.summarizeRetryWaiters.delete(sessionId);
      if (this.closed) {
        retry.resolve();
        return;
      }
      if (!this.hasCompleteBatchPending(sessionId)) {
        this.summarizeRetryAttempts.delete(sessionId);
        retry.resolve();
        return;
      }
      // Re-queue before releasing the waiter: an idle wait released by the
      // retry must observe the queued job, never run beside it.
      this.observeQueue?.enqueue(sessionId);
      retry.resolve();
    }, delayMs);
    // Pure background: unreferenced, so a one-shot host is never kept alive
    // by a retry loop. An explicit idle waiter (see waitForSessionObserveIdle)
    // references it for the duration of the wait, and close() clears all.
    timer.unref?.();
    this.summarizeRetryTimers.set(sessionId, timer);
  }

  /** True when the session still holds a complete unsummarized batch. */
  private hasCompleteBatchPending(sessionId: string): boolean {
    if (!this.archive) return false;
    return (
      this.archive.countUnsummarizedMessages(sessionId) >=
      this.config.leafBatchSize
    );
  }

  /** Drop a pending retry, its attempt counter, and release idle waiters. */
  private clearSummarizeRetry(sessionId: string): void {
    const timer = this.summarizeRetryTimers.get(sessionId);
    if (timer) {
      clearTimeout(timer);
      this.summarizeRetryTimers.delete(sessionId);
    }
    const waiter = this.summarizeRetryWaiters.get(sessionId);
    if (waiter) {
      this.summarizeRetryWaiters.delete(sessionId);
      waiter.resolve();
    }
    this.summarizeRetryAttempts.delete(sessionId);
  }

  get observeQueueDepth(): number {
    return this.observeQueue?.depth ?? 0;
  }

  get observeQueueInFlightCount(): number {
    return this.observeQueue?.inFlightCount ?? 0;
  }

  async waitForObserveQueueIdle(abortSignal?: AbortSignal): Promise<void> {
    abortSignal?.throwIfAborted();
    if (!this.config.enabled || this.closed) return;
    await this.ensureInitialized();
    abortSignal?.throwIfAborted();
    if (this.closed) return;
    for (;;) {
      abortSignal?.throwIfAborted();
      await this.waitForPendingObserveInitIdle(undefined, abortSignal);
      await this.observeQueue?.whenIdle(abortSignal);
      abortSignal?.throwIfAborted();
      const entry = [...this.summarizeRetryWaiters.entries()][0];
      if (!entry) return;
      await this.awaitSummarizeRetry(entry[0], entry[1], abortSignal);
      // A fired retry may have re-queued a session: wait for the queue again.
    }
  }

  async waitForSessionObserveIdle(sessionId: string, abortSignal?: AbortSignal): Promise<void> {
    abortSignal?.throwIfAborted();
    if (!this.config.enabled || this.closed) return;
    const normalizedSessionId = normalizeLcmSessionId(sessionId);
    if (!normalizedSessionId) return;
    await this.ensureInitialized();
    abortSignal?.throwIfAborted();
    if (this.closed) return;
    // Serialize with pending summary retries: a direct flush (pre-compaction)
    // must not run beside a retry pass for the same session.
    for (;;) {
      await this.waitForPendingObserveInitIdle(normalizedSessionId, abortSignal);
      await this.observeQueue?.whenSessionIdle(normalizedSessionId, abortSignal) ?? Promise.resolve();
      const waiter = this.summarizeRetryWaiters.get(normalizedSessionId);
      if (!waiter) return;
      await this.awaitSummarizeRetry(normalizedSessionId, waiter, abortSignal);
      // The retry fired and may have re-queued the session: wait again.
    }
  }

  /**
   * Park an explicit idle wait on a pending retry. While any wait is parked,
   * the retry timer is referenced so a one-shot host cannot exit under the
   * wait; with no waiters the timer stays unreferenced background work.
   */
  private async awaitSummarizeRetry(
    sessionId: string,
    waiter: { promise: Promise<void>; resolve: () => void },
    abortSignal?: AbortSignal,
  ): Promise<void> {
    const waiters = (this.summarizeRetryIdleWaiters.get(sessionId) ?? 0) + 1;
    this.summarizeRetryIdleWaiters.set(sessionId, waiters);
    this.summarizeRetryTimers.get(sessionId)?.ref?.();
    try {
      await abortOnSignal(abortSignal, waiter.promise);
    } finally {
      const remaining = (this.summarizeRetryIdleWaiters.get(sessionId) ?? 1) - 1;
      if (remaining <= 0) {
        this.summarizeRetryIdleWaiters.delete(sessionId);
        this.summarizeRetryTimers.get(sessionId)?.unref?.();
      } else {
        this.summarizeRetryIdleWaiters.set(sessionId, remaining);
      }
    }
  }

  private reservePendingObserveInit(sessionId: string): void {
    const count = this.pendingObserveInitCounts.get(sessionId) ?? 0;
    this.pendingObserveInitCounts.set(sessionId, count + 1);
  }

  private releasePendingObserveInit(sessionId: string): void {
    const count = this.pendingObserveInitCounts.get(sessionId);
    if (!count) return;

    if (count === 1) {
      this.pendingObserveInitCounts.delete(sessionId);
      const waiters = this.pendingObserveInitWaiters.get(sessionId) ?? [];
      this.pendingObserveInitWaiters.delete(sessionId);
      for (const resolve of waiters) resolve();
      if (this.pendingObserveInitCounts.size === 0) {
        const idleWaiters = this.pendingObserveInitIdleWaiters.splice(
          0,
          this.pendingObserveInitIdleWaiters.length,
        );
        for (const resolve of idleWaiters) resolve();
      }
      return;
    }

    this.pendingObserveInitCounts.set(sessionId, count - 1);
  }

  private async waitForPendingObserveInitIdle(sessionId?: string, abortSignal?: AbortSignal): Promise<void> {
    abortSignal?.throwIfAborted();
    if (sessionId) {
      if (!this.pendingObserveInitCounts.has(sessionId)) return;
      await new Promise<void>((resolve, reject) => {
        const finish = (): void => {
          abortSignal?.removeEventListener("abort", onAbort);
          resolve();
        };
        const onAbort = (): void => {
          const remaining = (this.pendingObserveInitWaiters.get(sessionId) ?? []).filter((waiter) => waiter !== finish);
          if (remaining.length === 0) this.pendingObserveInitWaiters.delete(sessionId);
          else this.pendingObserveInitWaiters.set(sessionId, remaining);
          reject(abortSignal?.reason instanceof Error ? abortSignal.reason : new DOMException("Aborted", "AbortError"));
        };
        const waiters = this.pendingObserveInitWaiters.get(sessionId) ?? [];
        waiters.push(finish);
        this.pendingObserveInitWaiters.set(sessionId, waiters);
        abortSignal?.addEventListener("abort", onAbort, { once: true });
      });
      return;
    }

    if (this.pendingObserveInitCounts.size === 0) return;
    await new Promise<void>((resolve, reject) => {
      const finish = (): void => {
        abortSignal?.removeEventListener("abort", onAbort);
        resolve();
      };
      const onAbort = (): void => {
        const remaining = this.pendingObserveInitIdleWaiters.filter((waiter) => waiter !== finish);
        this.pendingObserveInitIdleWaiters.splice(0, this.pendingObserveInitIdleWaiters.length, ...remaining);
        reject(abortSignal?.reason instanceof Error ? abortSignal.reason : new DOMException("Aborted", "AbortError"));
      };
      this.pendingObserveInitIdleWaiters.push(finish);
      abortSignal?.addEventListener("abort", onAbort, { once: true });
    });
  }

  /** Build the compressed history recall section for a session. */
  async assembleRecall(
    sessionId: string,
    budgetChars: number,
  ): Promise<string> {
    return (await this.assembleRecallWithTrace(sessionId, budgetChars)).text;
  }

  /** Build compressed recall plus content-free selected-summary receipts. */
  async assembleRecallWithTrace(
    sessionId: string,
    budgetChars: number,
  ): Promise<LcmRecallWithTraceResult> {
    if (!this.config.enabled) return { text: "", selectedSummaries: [] };
    const normalizedSessionId = normalizeLcmSessionId(sessionId);
    if (!normalizedSessionId) return { text: "", selectedSummaries: [] };
    await this.ensureInitialized();

    const effectiveBudget = Math.ceil(
      budgetChars * this.config.recallBudgetShare,
    );
    if (effectiveBudget <= 0) return { text: "", selectedSummaries: [] };

    return assembleCompressedHistoryWithTrace(this.dag!, this.archive!, normalizedSessionId, {
      freshTailTurns: this.config.freshTailTurns,
      budgetChars: effectiveBudget,
    });
  }

  async searchStructuredParts(
    sessionId: string,
    query: string,
    limit = this.config.messagePartsRecallMaxResults,
  ): Promise<LcmStructuredRecallMatch[]> {
    const { messagePartsEnabled } = this.config;
    if (!this.config.enabled || !messagePartsEnabled) return [];
    const normalizedSessionId = normalizeLcmSessionId(sessionId);
    if (!normalizedSessionId) return [];
    await this.ensureInitialized();
    if (!this.archive) return [];
    return this.archive.searchStructuredParts(query, limit, normalizedSessionId);
  }

  formatStructuredRecall(
    matches: LcmStructuredRecallMatch[],
    budgetChars: number,
  ): string {
    if (matches.length === 0 || budgetChars <= 0) return "";
    const lines: string[] = [];
    let used = "## Structured Session Matches\n\n".length;
    for (const match of matches) {
      const label = match.file_path
        ? `${match.kind} ${match.file_path}`
        : match.tool_name
          ? `${match.kind} ${match.tool_name}`
          : match.kind;
      const excerpt = match.content.replace(/\s+/g, " ").slice(0, 220);
      const line = `- turn ${match.turn_index} (${match.role}): ${label} — ${excerpt}`;
      if (used + line.length + 1 > budgetChars) break;
      lines.push(line);
      used += line.length + 1;
    }
    return lines.length > 0 ? `## Structured Session Matches\n\n${lines.join("\n")}` : "";
  }

  /** Flush pending summaries before compaction (called from before_compaction hook). */
  async preCompactionFlush(sessionId: string, abortSignal?: AbortSignal): Promise<void> {
    abortSignal?.throwIfAborted();
    if (!this.config.enabled) return;
    const normalizedSessionId = normalizeLcmSessionId(sessionId);
    if (!normalizedSessionId) return;
    await this.ensureInitialized();
    abortSignal?.throwIfAborted();
    await this.waitForSessionObserveIdle(normalizedSessionId, abortSignal);
    abortSignal?.throwIfAborted();

    try {
      await abortOnSignal(abortSignal, this.summarizer!.summarizeIncremental(normalizedSessionId));
    } catch (err) {
      if (abortSignal?.aborted) throw err;
      log.debug(`LCM pre-compaction flush error: ${err}`);
    }
  }

  /** Record a compaction event with real token counts (called from after_compaction hook). */
  async recordCompaction(
    sessionId: string,
    tokensBefore: number,
    tokensAfter: number,
  ): Promise<void> {
    if (!this.config.enabled) return;
    const normalizedSessionId = normalizeLcmSessionId(sessionId);
    if (!normalizedSessionId) return;
    await this.ensureInitialized();
    await this.waitForSessionObserveIdle(normalizedSessionId);

    const maxTurn = this.archive!.getMaxTurnIndex(normalizedSessionId);

    this.dag!.recordCompaction(normalizedSessionId, maxTurn, tokensBefore, tokensAfter);
    log.info(
      `LCM compaction recorded: session=${normalizedSessionId}, turn=${maxTurn}, tokens ${tokensBefore}→${tokensAfter}`,
    );
  }

  /** Verify archive coverage after compaction. */
  async verifyPostCompaction(sessionId: string): Promise<void> {
    if (!this.config.enabled) return;
    const normalizedSessionId = normalizeLcmSessionId(sessionId);
    if (!normalizedSessionId) return;
    await this.ensureInitialized();

    const msgCount = this.archive!.getMessageCount(normalizedSessionId);
    const nodeCount = this.dag!.getNodeCount(normalizedSessionId);
    log.debug(
      `LCM post-compaction verify: session=${normalizedSessionId}, messages=${msgCount}, summaryNodes=${nodeCount}`,
    );
  }

  // ── MCP Tool implementations ──

  /** Search across all conversation history via FTS (snippet mode). */
  async searchContext(
    query: string,
    limit: number,
    sessionId?: string,
    sessionPrefix?: string,
  ): Promise<
    Array<{
      turn_index: number;
      role: string;
      snippet: string;
      session_id: string;
    }>
  > {
    if (!this.config.enabled) return [];
    const normalizedSessionId = normalizeOptionalLcmSessionId(sessionId);
    if (sessionId !== undefined && !normalizedSessionId) return [];
    const normalizedSessionPrefix = normalizeOptionalLcmSessionId(sessionPrefix);
    if (sessionPrefix !== undefined && !normalizedSessionPrefix) return [];
    await this.ensureInitialized();
    return this.archive!.search(query, limit, normalizedSessionId, normalizedSessionPrefix);
  }

  /** Search via FTS returning full message content (not snippets). */
  async searchContextFull(
    query: string,
    limit: number,
    sessionId?: string,
    sessionPrefix?: string,
  ): Promise<
    Array<{
      id: number;
      turn_index: number;
      role: string;
      content: string;
      session_id: string;
      score: number;
    }>
  > {
    if (!this.config.enabled) return [];
    const normalizedSessionId = normalizeOptionalLcmSessionId(sessionId);
    if (sessionId !== undefined && !normalizedSessionId) return [];
    const normalizedSessionPrefix = normalizeOptionalLcmSessionId(sessionPrefix);
    if (sessionPrefix !== undefined && !normalizedSessionPrefix) return [];
    await this.ensureInitialized();
    return this.archive!.searchWithContent(
      query,
      limit,
      normalizedSessionId,
      1000,
      normalizedSessionPrefix,
    );
  }

  /** Get a compressed summary of a turn range. */
  async describeContext(
    sessionId: string,
    fromTurn: number,
    toTurn: number,
  ): Promise<{ summary: string; turn_count: number; depth: number } | null> {
    if (!this.config.enabled) return null;
    const normalizedSessionId = normalizeLcmSessionId(sessionId);
    if (!normalizedSessionId) return null;
    await this.ensureInitialized();

    const nodes = this.dag!.getCoveringNodes(normalizedSessionId, fromTurn, toTurn);
    if (nodes.length === 0) {
      // No summary exists — build a description from raw messages
      const messages = this.archive!.getMessages(normalizedSessionId, fromTurn, toTurn);
      if (messages.length === 0) return null;
      const preview = messages
        .slice(0, 5)
        .map((m) => `[${m.role}] ${m.content.slice(0, 100)}`)
        .join("\n");
      return {
        summary: `No summary available for this range. Preview of ${messages.length} messages:\n${preview}`,
        turn_count: messages.length,
        depth: -1,
      };
    }

    // Use the deepest covering node
    const best = nodes[0]; // Already sorted by depth DESC
    return {
      summary: best.summary_text,
      turn_count: best.msg_end - best.msg_start + 1,
      depth: best.depth,
    };
  }

  /**
   * Retrieve raw archived messages for a turn range (inclusive bounds),
   * read-only and unshaped — no token-budget trimming (issue #2331
   * episodic-context). Callers own truncation and cleaning.
   */
  async getTurnRange(
    sessionId: string,
    fromTurn: number,
    toTurn: number,
  ): Promise<LcmMessage[]> {
    if (!this.config.enabled) return [];
    const normalizedSessionId = normalizeLcmSessionId(sessionId);
    if (!normalizedSessionId) return [];
    await this.ensureInitialized();
    return this.archive!.getMessages(normalizedSessionId, fromTurn, toTurn);
  }

  /** Retrieve raw messages for a turn range (lossless expansion). */
  async expandContext(
    sessionId: string,
    fromTurn: number,
    toTurn: number,
    maxTokens: number,
  ): Promise<LcmExpandedMessage[]> {
    if (!this.config.enabled) return [];
    const normalizedSessionId = normalizeLcmSessionId(sessionId);
    if (!normalizedSessionId) return [];
    await this.ensureInitialized();

    const messages = this.archive!.getMessages(normalizedSessionId, fromTurn, toTurn);
    if (messages.length === 0) return [];

    // Enforce the token budget while keeping the existing first/last shape.
    const tokenBudget = Math.max(0, Math.floor(maxTokens));
    if (tokenBudget === 0) return [];
    const totalTokens = messages.reduce(
      (sum, message) => sum + estimateTokenCount(message.content),
      0,
    );
    if (totalTokens <= tokenBudget) {
      return messages.map((m) => ({
        id: m.id,
        session_id: m.session_id,
        turn_index: m.turn_index,
        role: m.role,
        content: m.content,
      }));
    }

    const result: LcmExpandedMessage[] = [];
    const lastMsg = messages[messages.length - 1];
    const reservedLastTokens = Math.min(
      estimateTokenCount(lastMsg.content),
      Math.max(1, Math.floor(tokenBudget * 0.3)),
    );
    let remainingTokens = tokenBudget - reservedLastTokens;

    for (let i = 0; i < messages.length - 1; i++) {
      if (remainingTokens <= 0) break;
      const content = truncateToTokenBudget(
        messages[i].content,
        remainingTokens,
      );
      if (!content) continue;
      result.push({
        id: messages[i].id,
        session_id: messages[i].session_id,
        turn_index: messages[i].turn_index,
        role: messages[i].role,
        content,
      });
      remainingTokens -= estimateTokenCount(content);
    }

    const lastContent = truncateToTokenBudget(
      lastMsg.content,
      reservedLastTokens + remainingTokens,
    );
    if (lastContent) {
      result.push({
        id: lastMsg.id,
        session_id: lastMsg.session_id,
        turn_index: lastMsg.turn_index,
        role: lastMsg.role,
        content: lastContent,
      });
    }
    return result;
  }


  /** Get statistics about the LCM archive. */
  async getStats(sessionId?: string): Promise<{
    totalMessages: number;
    totalSummaryNodes: number;
    maxDepth: number;
    maxTurnIndex?: number;
  }> {
    if (!this.config.enabled)
      return { totalMessages: 0, totalSummaryNodes: 0, maxDepth: -1 };
    const normalizedSessionId = normalizeOptionalLcmSessionId(sessionId);
    if (sessionId !== undefined && !normalizedSessionId) {
      return { ...EMPTY_LCM_STATS };
    }
    await this.ensureInitialized();

    if (normalizedSessionId) {
      return {
        totalMessages: this.archive!.getMessageCount(normalizedSessionId),
        totalSummaryNodes: this.dag!.getNodeCount(normalizedSessionId),
        maxDepth: this.dag!.getMaxDepth(normalizedSessionId),
        maxTurnIndex: this.archive!.getMaxTurnIndex(normalizedSessionId),
      };
    }

    return {
      totalMessages: this.archive!.getTotalMessageCount(),
      totalSummaryNodes: 0, // Would need a global count query
      maxDepth: -1,
    };
  }

  /** Clear all LCM archive and summary state for one session. */
  async clearSession(sessionId: string, abortSignal?: AbortSignal): Promise<void> {
    if (!this.config.enabled || this.closed) return;
    const normalizedSessionId = normalizeLcmSessionId(sessionId);
    if (!normalizedSessionId) return;
    await this.ensureInitialized();
    if (this.closed || !this.archive || !this.dag) return;
    await this.waitForSessionObserveIdle(normalizedSessionId, abortSignal);
    abortSignal?.throwIfAborted();
    this.dag.deleteSession(normalizedSessionId);
    this.archive.deleteSession(normalizedSessionId);
  }

  /** Clear all LCM archive and summary state without closing the engine. */
  async clearAll(abortSignal?: AbortSignal): Promise<void> {
    if (!this.config.enabled || this.closed) return;
    await this.ensureInitialized();
    if (this.closed || !this.archive || !this.dag) return;
    await this.waitForObserveQueueIdle(abortSignal);
    abortSignal?.throwIfAborted();
    this.dag.deleteAll();
    this.archive.deleteAll();
  }

  /** Prune old data beyond retention period. */
  async prune(): Promise<{ messagesPruned: number; nodesPruned: number }> {
    if (!this.config.enabled) return { messagesPruned: 0, nodesPruned: 0 };
    await this.ensureInitialized();

    const messagesPruned = this.archive!.pruneOldMessages(
      this.config.archiveRetentionDays,
    );
    const nodesPruned = this.dag!.pruneOldNodes(
      this.config.archiveRetentionDays,
    );
    return { messagesPruned, nodesPruned };
  }

  /** Close the database connection. */
  close(): void {
    this.closed = true;
    for (const timer of this.summarizeRetryTimers.values()) clearTimeout(timer);
    this.summarizeRetryTimers.clear();
    this.summarizeRetryAttempts.clear();
    for (const retry of this.summarizeRetryWaiters.values()) retry.resolve();
    this.summarizeRetryWaiters.clear();
    this.summarizeRetryIdleWaiters.clear();
    if (this.db) {
      this.db.close();
    }
    this.db = null;
    this.archive = null;
    this.dag = null;
    this.summarizer = null;
    this.observeQueue = null;
    this.initPromise = null;
  }
}
function truncateToTokenBudget(text: string, maxTokens: number): string {
  if (maxTokens <= 0) return "";
  if (estimateTokenCount(text) <= maxTokens) return text;
  const codePoints = [...text];
  let low = 0;
  let high = codePoints.length;
  while (low < high) {
    const mid = Math.ceil((low + high) / 2);
    if (estimateTokenCount(codePoints.slice(0, mid).join("")) <= maxTokens) {
      low = mid;
    } else {
      high = mid - 1;
    }
  }
  return codePoints.slice(0, low).join("");
}

import type Database from "better-sqlite3";
import { log } from "../logger.js";
import {
  type LcmMessagePartInput,
  type MessagePartSourceFormat,
  parseMessageParts,
} from "../message-parts/index.js";
import { estimateTokenCount } from "../token-estimate.js";

export interface LcmMessage {
  id: number;
  session_id: string;
  turn_index: number;
  role: string;
  content: string;
  token_count: number;
  created_at: string;
  metadata: string | null;
}

export interface LcmSearchResult {
  turn_index: number;
  role: string;
  snippet: string;
  session_id: string;
  score: number;
}

export interface LcmSearchWithContentResult {
  id: number;
  turn_index: number;
  role: string;
  content: string;
  session_id: string;
  score: number;
}

export interface LcmStructuredRecallMatch {
  part_id: number;
  message_id: number;
  turn_index: number;
  role: string;
  content: string;
  session_id: string;
  kind: string;
  tool_name: string | null;
  file_path: string | null;
  payload: string;
  score: number;
}

/** Shared script-aware token estimate used by LCM accounting. */
export const estimateTokens = estimateTokenCount;

const PUBLIC_LCM_SEARCH_LIMIT = 100;

function normalizeSearchLimit(limit: number, fallback = 10, max = PUBLIC_LCM_SEARCH_LIMIT): number {
  if (typeof limit !== "number" || !Number.isFinite(limit)) return fallback;
  const normalized = Math.floor(limit);
  if (normalized <= 0) return 0;
  return Math.min(max, normalized);
}

function escapeSqlLike(value: string): string {
  return value.replace(/[\\%_]/g, (match) => `\\${match}`);
}

export class LcmArchive {
  constructor(private readonly db: Database.Database) {}

  /** Append a message to the archive. Returns the row id. */
  appendMessage(
    sessionId: string,
    turnIndex: number,
    role: string,
    content: string,
    metadata?: Record<string, unknown>,
    parts?: LcmMessagePartInput[],
  ): number {
    const tokenCount = estimateTokens(content);
    const now = new Date().toISOString();
    const metaJson = metadata ? JSON.stringify(metadata) : null;

    const stmt = this.db.prepare(`
      INSERT INTO lcm_messages (session_id, turn_index, role, content, token_count, created_at, metadata)
      VALUES (?, ?, ?, ?, ?, ?, ?)
    `);
    const result = stmt.run(sessionId, turnIndex, role, content, tokenCount, now, metaJson);
    const rowId = Number(result.lastInsertRowid);

    // Keep FTS in sync
    this.db
      .prepare("INSERT INTO lcm_messages_fts (rowid, content) VALUES (?, ?)")
      .run(rowId, content);

    if (parts && parts.length > 0) {
      this.insertMessageParts(rowId, parts, now);
    }

    return rowId;
  }

  /** Append multiple messages in a single transaction. */
  appendMessages(
    sessionId: string,
    messages: Array<{
      turnIndex: number;
      role: string;
      content: string;
      metadata?: Record<string, unknown>;
      parts?: LcmMessagePartInput[];
      rawContent?: unknown;
      sourceFormat?: MessagePartSourceFormat;
    }>,
    options: { messagePartsEnabled?: boolean } = {},
  ): void {
    if (messages.length === 0) return;
    const captureMessageParts = options.messagePartsEnabled !== false;

    const txn = this.db.transaction(() => {
      for (const msg of messages) {
        const explicitParts =
          msg.parts && msg.parts.length > 0 ? msg.parts : undefined;
        const rawContent = msg.rawContent ?? msg.content;
        const parts =
          captureMessageParts
            ? explicitParts ??
              parseMessageParts(rawContent, {
                sourceFormat: msg.sourceFormat,
                renderedContent: msg.content,
              })
            : undefined;
        this.appendMessage(
          sessionId,
          msg.turnIndex,
          msg.role,
          msg.content,
          msg.metadata,
          parts,
        );
      }
    });
    txn();
  }

  insertMessageParts(
    messageId: number,
    parts: LcmMessagePartInput[],
    fallbackCreatedAt: string,
  ): void {
    if (parts.length === 0) return;
    const stmt = this.db.prepare(`
      INSERT INTO lcm_message_parts (message_id, ordinal, kind, payload, tool_name, file_path, created_at)
      VALUES (?, ?, ?, ?, ?, ?, ?)
    `);
    for (let index = 0; index < parts.length; index += 1) {
      const part = parts[index]!;
      const rawPart = part as unknown as Record<string, unknown>;
      const toolName = part.toolName ?? asNullableString(rawPart.tool_name);
      const filePath = part.filePath ?? asNullableString(rawPart.file_path);
      const createdAt = part.createdAt ?? asNullableString(rawPart.created_at);
      stmt.run(
        messageId,
        part.ordinal ?? index,
        part.kind,
        JSON.stringify(part.payload ?? {}),
        toolName ?? null,
        filePath ?? null,
        createdAt ?? fallbackCreatedAt,
      );
    }
  }

  /** Get the highest turn_index for a session, or -1 if none. */
  getMaxTurnIndex(sessionId: string): number {
    const row = this.db
      .prepare("SELECT MAX(turn_index) as max_turn FROM lcm_messages WHERE session_id = ?")
      .get(sessionId) as { max_turn: number | null } | undefined;
    return row?.max_turn ?? -1;
  }

  /** Retrieve messages in a turn range (inclusive). */
  getMessages(sessionId: string, fromTurn: number, toTurn: number): LcmMessage[] {
    return this.db
      .prepare(
        "SELECT * FROM lcm_messages WHERE session_id = ? AND turn_index >= ? AND turn_index <= ? ORDER BY turn_index",
      )
      .all(sessionId, fromTurn, toTurn) as LcmMessage[];
  }

  /** Highest turn index covered by a leaf summary (-1 when none exist). */
  private lastLeafSummaryEnd(sessionId: string): number {
    // SAFETY: the query returns exactly one aggregate column, `last_end`.
    const row = this.db
      .prepare(
        "SELECT MAX(msg_end) as last_end FROM lcm_summary_nodes WHERE session_id = ? AND depth = 0",
      )
      .get(sessionId) as { last_end: number | null } | undefined;
    return row?.last_end ?? -1;
  }

  /** Retrieve unsummarized messages (after last leaf summary), optionally bounded. */
  getUnsummarizedMessages(sessionId: string, limit?: number): LcmMessage[] {
    const lastSummarized = this.lastLeafSummaryEnd(sessionId);
    if (limit !== undefined && limit <= 0) return [];

    const stmt = this.db.prepare(
      limit === undefined
        ? "SELECT * FROM lcm_messages WHERE session_id = ? AND turn_index > ? ORDER BY turn_index"
        : "SELECT * FROM lcm_messages WHERE session_id = ? AND turn_index > ? ORDER BY turn_index LIMIT ?",
    );
    // SAFETY: the statement selects the lcm_messages row shape.
    const rows = (
      limit === undefined ? stmt.all(sessionId, lastSummarized) : stmt.all(sessionId, lastSummarized, limit)
    ) as LcmMessage[];
    return rows;
  }

  /** Count archived turns that no leaf summary covers yet. */
  countUnsummarizedMessages(sessionId: string): number {
    const lastSummarized = this.lastLeafSummaryEnd(sessionId);
    // SAFETY: the query returns exactly one aggregate column, `n`.
    const row = this.db
      .prepare(
        "SELECT COUNT(*) as n FROM lcm_messages WHERE session_id = ? AND turn_index > ?",
      )
      .get(sessionId, lastSummarized) as { n: number };
    return row.n;
  }

  /**
   * Sessions whose durable archive still holds at least `minTurns`
   * unsummarized turns. Metadata only — used to resume outstanding summary
   * work after a restart.
   */
  listSessionsWithUnsummarizedTurns(minTurns: number): string[] {
    if (minTurns <= 0) return [];
    // SAFETY: the query returns one `session_id` column per session.
    const rows = this.db
      .prepare(
        `
        SELECT m.session_id AS session_id
        FROM lcm_messages m
        LEFT JOIN (
          SELECT session_id, MAX(msg_end) AS last_end
          FROM lcm_summary_nodes
          WHERE depth = 0
          GROUP BY session_id
        ) leaves ON leaves.session_id = m.session_id
        WHERE m.turn_index > COALESCE(leaves.last_end, -1)
        GROUP BY m.session_id
        HAVING COUNT(*) >= ?
      `,
      )
      .all(minTurns) as Array<{ session_id: string }>;
    return rows.map((row) => row.session_id);
  }

  /** Full-text search across all messages. */
  search(query: string, limit: number, sessionId?: string, sessionPrefix?: string): LcmSearchResult[] {
    try {
      const ftsQuery = sanitizeFtsQuery(query);
      if (!ftsQuery) return [];
      const cappedLimit = normalizeSearchLimit(limit);
      if (cappedLimit === 0) return [];

      let sql: string;
      const params: unknown[] = [ftsQuery];

      if (sessionId) {
        sql = `
          SELECT m.turn_index, m.role, snippet(lcm_messages_fts, 0, '>>>', '<<<', '...', 48) as snippet,
                 m.session_id, rank
          FROM lcm_messages_fts f
          JOIN lcm_messages m ON m.id = f.rowid
          WHERE lcm_messages_fts MATCH ?
            AND m.session_id = ?
          ORDER BY rank
          LIMIT ?
        `;
        params.push(sessionId, cappedLimit);
      } else if (sessionPrefix) {
        sql = `
          SELECT m.turn_index, m.role, snippet(lcm_messages_fts, 0, '>>>', '<<<', '...', 48) as snippet,
                 m.session_id, rank
          FROM lcm_messages_fts f
          JOIN lcm_messages m ON m.id = f.rowid
          WHERE lcm_messages_fts MATCH ?
            AND m.session_id LIKE ? ESCAPE '\\'
          ORDER BY rank
          LIMIT ?
        `;
        params.push(`${escapeSqlLike(sessionPrefix)}%`, cappedLimit);
      } else {
        sql = `
          SELECT m.turn_index, m.role, snippet(lcm_messages_fts, 0, '>>>', '<<<', '...', 48) as snippet,
                 m.session_id, rank
          FROM lcm_messages_fts f
          JOIN lcm_messages m ON m.id = f.rowid
          WHERE lcm_messages_fts MATCH ?
          ORDER BY rank
          LIMIT ?
        `;
        params.push(cappedLimit);
      }

      const rows = this.db.prepare(sql).all(...params) as Array<{
        turn_index: number;
        role: string;
        snippet: string;
        session_id: string;
        rank: number;
      }>;

      return rows.map((r) => ({
        turn_index: r.turn_index,
        role: r.role,
        snippet: r.snippet,
        session_id: r.session_id,
        score: -r.rank, // FTS5 rank is negative; negate for ascending score
      }));
    } catch (err) {
      log.debug(`LCM FTS search error: ${err}`);
      return [];
    }
  }

  /**
   * Full-text search returning focused excerpts around matching terms.
   * Returns ~1000-char windows centered on query term matches.
   * Deduplicates by message id and returns results sorted by FTS rank.
   */
  searchWithContent(query: string, limit: number, sessionId?: string, excerptChars = 1000, sessionPrefix?: string): LcmSearchWithContentResult[] {
    try {
      const ftsQuery = sanitizeFtsQuery(query);
      if (!ftsQuery) return [];
      const cappedLimit = normalizeSearchLimit(limit);
      if (cappedLimit === 0) return [];

      // Extract content words from query for excerpt windowing
      const queryWords = query
        .replace(/[^\w\s]/g, " ")
        .split(/\s+/)
        .filter((w) => w.length > 1 && !STOPWORDS.has(w.toLowerCase()))
        .map((w) => w.toLowerCase());

      let sql: string;
      const params: unknown[] = [ftsQuery];

      if (sessionId) {
        sql = `
          SELECT m.id, m.turn_index, m.role, m.content, m.session_id, rank
          FROM lcm_messages_fts f
          JOIN lcm_messages m ON m.id = f.rowid
          WHERE lcm_messages_fts MATCH ?
            AND m.session_id = ?
          ORDER BY rank
          LIMIT ?
        `;
        params.push(sessionId, cappedLimit);
      } else if (sessionPrefix) {
        sql = `
          SELECT m.id, m.turn_index, m.role, m.content, m.session_id, rank
          FROM lcm_messages_fts f
          JOIN lcm_messages m ON m.id = f.rowid
          WHERE lcm_messages_fts MATCH ?
            AND m.session_id LIKE ? ESCAPE '\\'
          ORDER BY rank
          LIMIT ?
        `;
        params.push(`${escapeSqlLike(sessionPrefix)}%`, cappedLimit);
      } else {
        sql = `
          SELECT m.id, m.turn_index, m.role, m.content, m.session_id, rank
          FROM lcm_messages_fts f
          JOIN lcm_messages m ON m.id = f.rowid
          WHERE lcm_messages_fts MATCH ?
          ORDER BY rank
          LIMIT ?
        `;
        params.push(cappedLimit);
      }

      const rows = this.db.prepare(sql).all(...params) as Array<{
        id: number;
        turn_index: number;
        role: string;
        content: string;
        session_id: string;
        rank: number;
      }>;

      // Deduplicate by message id (same message may match multiple terms)
      const seen = new Set<number>();
      const results: LcmSearchWithContentResult[] = [];
      for (const r of rows) {
        if (seen.has(r.id)) continue;
        seen.add(r.id);
        results.push({
          id: r.id,
          turn_index: r.turn_index,
          role: r.role,
          content: extractExcerpt(r.content, queryWords, excerptChars),
          session_id: r.session_id,
          score: -r.rank,
        });
      }
      return results;
    } catch (err) {
      log.debug(`LCM FTS searchWithContent error: ${err}`);
      return [];
    }
  }

  searchStructuredParts(
    query: string,
    limit: number,
    sessionId?: string,
  ): LcmStructuredRecallMatch[] {
    const cappedLimit = Math.max(0, Math.min(20, Math.floor(limit)));
    if (cappedLimit === 0) return [];

    const fileTerms = extractStructuredFileTerms(query);
    const toolTerms = extractStructuredToolTerms(query);
    if (fileTerms.length === 0 && toolTerms.length === 0) return [];

    const matchWhere: string[] = [];
    const whereParams: unknown[] = [];
    for (const term of fileTerms) {
      matchWhere.push("(p.file_path = ? OR p.file_path LIKE ? ESCAPE '\\')");
      whereParams.push(term, `%${escapeLike(term)}%`);
    }
    for (const term of toolTerms) {
      matchWhere.push("p.tool_name LIKE ? ESCAPE '\\'");
      whereParams.push(`%${escapeLike(term)}%`);
    }
    const where = [`(${matchWhere.join(" OR ")})`];
    if (sessionId) {
      where.push("m.session_id = ?");
      whereParams.push(sessionId);
    }
    const exactFileScoreParams = [...fileTerms];
    const sqlParams = [...exactFileScoreParams, ...whereParams, cappedLimit];

    const rows = this.db.prepare(`
      SELECT
        p.id AS part_id,
        p.message_id AS message_id,
        m.turn_index AS turn_index,
        m.role AS role,
        m.content AS content,
        m.session_id AS session_id,
        p.kind AS kind,
        p.tool_name AS tool_name,
        p.file_path AS file_path,
        p.payload AS payload,
        CASE
          WHEN p.file_path IN (${fileTerms.map(() => "?").join(",") || "NULL"}) THEN 3
          WHEN p.file_path IS NOT NULL THEN 2
          WHEN p.tool_name IS NOT NULL THEN 1
          ELSE 0
        END AS score
      FROM lcm_message_parts p
      JOIN lcm_messages m ON m.id = p.message_id
      WHERE ${where.join(" AND ")}
      ORDER BY score DESC, m.turn_index DESC, p.ordinal ASC
      LIMIT ?
    `).all(...sqlParams) as LcmStructuredRecallMatch[];

    return rows;
  }

  /** Get total message count for a session. */
  getMessageCount(sessionId: string): number {
    const row = this.db
      .prepare("SELECT COUNT(*) as cnt FROM lcm_messages WHERE session_id = ?")
      .get(sessionId) as { cnt: number };
    return row.cnt;
  }

  /** Get total message count across all sessions. */
  getTotalMessageCount(): number {
    const row = this.db
      .prepare("SELECT COUNT(*) as cnt FROM lcm_messages")
      .get() as { cnt: number };
    return row.cnt;
  }

  /** Delete all archived messages for one session. */
  deleteSession(sessionId: string): number {
    const txn = this.db.transaction(() => {
      this.db
        .prepare(
          "DELETE FROM lcm_messages_fts WHERE rowid IN (SELECT id FROM lcm_messages WHERE session_id = ?)",
        )
        .run(sessionId);
      this.db
        .prepare(
          "DELETE FROM lcm_message_parts WHERE message_id IN (SELECT id FROM lcm_messages WHERE session_id = ?)",
        )
        .run(sessionId);
      const result = this.db
        .prepare("DELETE FROM lcm_messages WHERE session_id = ?")
        .run(sessionId);
      return result.changes;
    });
    return txn();
  }

  /** Delete all archived messages. */
  deleteAll(): number {
    const txn = this.db.transaction(() => {
      this.db.prepare("DELETE FROM lcm_messages_fts").run();
      this.db.prepare("DELETE FROM lcm_message_parts").run();
      const result = this.db.prepare("DELETE FROM lcm_messages").run();
      return result.changes;
    });
    return txn();
  }

  /** Prune messages older than retentionDays. */
  pruneOldMessages(retentionDays: number): number {
    const cutoff = new Date(Date.now() - retentionDays * 86400_000).toISOString();

    const txn = this.db.transaction(() => {
      // Delete from FTS and child tables first. Some handles may not have
      // foreign_keys enabled, so do not rely on ON DELETE CASCADE for parts.
      this.db
        .prepare(
          "DELETE FROM lcm_messages_fts WHERE rowid IN (SELECT id FROM lcm_messages WHERE created_at < ?)",
        )
        .run(cutoff);
      this.db
        .prepare(
          "DELETE FROM lcm_message_parts WHERE message_id IN (SELECT id FROM lcm_messages WHERE created_at < ?)",
        )
        .run(cutoff);

      const result = this.db
        .prepare("DELETE FROM lcm_messages WHERE created_at < ?")
        .run(cutoff);
      return result.changes;
    });
    return txn();
  }
}

/**
 * Extract a focused excerpt from content centered on query term matches.
 * Returns a window of ~excerptChars around the first matching term.
 * If content is shorter than excerptChars, returns the full content.
 */
function extractExcerpt(content: string, queryWords: string[], excerptChars: number): string {
  if (content.length <= excerptChars) return content;

  // Find the earliest position of any query word in the content
  const contentLower = content.toLowerCase();
  let bestPos = -1;
  for (const word of queryWords) {
    const pos = contentLower.indexOf(word);
    if (pos !== -1 && (bestPos === -1 || pos < bestPos)) {
      bestPos = pos;
    }
  }

  // If no match found (shouldn't happen for FTS results), return start
  if (bestPos === -1) {
    return content.slice(0, excerptChars) + "...";
  }

  // Center the window around the match
  const halfWindow = Math.floor(excerptChars / 2);
  let start = Math.max(0, bestPos - halfWindow);
  let end = Math.min(content.length, start + excerptChars);

  // Adjust start if we hit the end
  if (end === content.length) {
    start = Math.max(0, end - excerptChars);
  }

  // Extend to sentence boundaries if possible
  if (start > 0) {
    const sentenceStart = content.lastIndexOf(". ", start);
    if (sentenceStart !== -1 && start - sentenceStart < 200) {
      start = sentenceStart + 2;
    }
  }
  if (end < content.length) {
    const sentenceEnd = content.indexOf(". ", end - 1);
    if (sentenceEnd !== -1 && sentenceEnd - end < 200) {
      end = sentenceEnd + 1;
    }
  }

  const prefix = start > 0 ? "..." : "";
  const suffix = end < content.length ? "..." : "";
  return prefix + content.slice(start, end) + suffix;
}

const STOPWORDS = new Set([
  "a", "an", "the", "is", "are", "was", "were", "be", "been", "being",
  "have", "has", "had", "do", "does", "did", "will", "would", "could",
  "should", "may", "might", "shall", "can", "to", "of", "in", "for",
  "on", "with", "at", "by", "from", "as", "into", "about", "between",
  "through", "during", "before", "after", "and", "but", "or", "nor",
  "not", "so", "if", "then", "than", "that", "this", "it", "its",
  "what", "which", "who", "whom", "how", "when", "where", "why",
  "all", "each", "every", "both", "few", "more", "most", "other",
  "some", "such", "no", "only", "own", "same", "just", "very",
  "my", "your", "his", "her", "our", "their", "me", "him", "us", "them",
  "i", "you", "he", "she", "we", "they",
]);

function extractStructuredFileTerms(query: string): string[] {
  const terms = new Set<string>();
  for (const raw of splitQueryTerms(query)) {
    const cleaned = trimStructuredQueryTerm(raw);
    if (
      cleaned.includes("/") ||
      hasStructuredFileExtension(cleaned)
    ) {
      terms.add(cleaned);
      const basename = cleaned.split("/").pop();
      if (basename && basename !== cleaned) terms.add(basename);
    }
  }
  return [...terms].filter((term) => term.length > 1).slice(0, 12);
}

function splitQueryTerms(query: string): string[] {
  const terms: string[] = [];
  let term = "";
  for (const char of query.slice(0, 20_000)) {
    if (char === " " || char === "\n" || char === "\r" || char === "\t") {
      if (term.length > 0) terms.push(term);
      term = "";
      continue;
    }
    term += char;
    if (term.length > 512) {
      terms.push(term);
      term = "";
    }
  }
  if (term.length > 0) terms.push(term);
  return terms;
}

function trimStructuredQueryTerm(raw: string): string {
  const leading = new Set(["`", "'", "\"", "(", "[", "{"]);
  const trailing = new Set(["`", "'", "\"", ",", ".", "?", "!", ":", ";", ")", "]", "}"]);
  let start = 0;
  let end = raw.length;
  while (start < end && leading.has(raw[start]!)) start += 1;
  while (end > start && trailing.has(raw[end - 1]!)) end -= 1;
  return raw.slice(start, end);
}

function hasStructuredFileExtension(value: string): boolean {
  const slash = value.lastIndexOf("/");
  const basename = value.slice(slash + 1);
  const dot = basename.lastIndexOf(".");
  if (dot <= 0 || dot === basename.length - 1) return false;
  const ext = basename.slice(dot + 1);
  if (ext.length < 1 || ext.length > 12) return false;
  for (const char of ext) {
    const code = char.charCodeAt(0);
    const valid =
      (code >= 48 && code <= 57) ||
      (code >= 65 && code <= 90) ||
      (code >= 97 && code <= 122) ||
      char === "_" ||
      char === "+" ||
      char === "-";
    if (!valid) return false;
  }
  return true;
}

function extractStructuredToolTerms(query: string): string[] {
  const lower = query.toLowerCase();
  if (!/\b(tool|command|invocation|called|used|ran|read|write|patch|edit|grep|search)\b/.test(lower)) {
    return [];
  }
  return query
    .replace(/[^\w.-]/g, " ")
    .split(/\s+/)
    .filter((term) => term.length > 2 && !STOPWORDS.has(term.toLowerCase()))
    .slice(0, 8);
}

function escapeLike(value: string): string {
  return value.replace(/[\\%_]/g, (char) => `\\${char}`);
}

function asNullableString(value: unknown): string | null {
  return typeof value === "string" && value.trim().length > 0 ? value : null;
}

/**
 * Sanitize a query for FTS5 MATCH.
 * Uses OR logic so partial matches rank higher than no matches.
 * Filters stopwords to focus on content words.
 */
function sanitizeFtsQuery(raw: string): string {
  const words = raw
    .replace(/[^\w\s]/g, " ")
    .split(/\s+/)
    .filter((w) => w.length > 1 && !STOPWORDS.has(w.toLowerCase()));
  if (words.length === 0) {
    // If all words were stopwords, fall back to using all words
    const allWords = raw.replace(/[^\w\s]/g, " ").split(/\s+/).filter((w) => w.length > 1);
    if (allWords.length === 0) return "";
    return allWords.map((w) => `"${w}"`).join(" OR ");
  }
  return words.map((w) => `"${w}"`).join(" OR ");
}

import type Database from "better-sqlite3";
import { log } from "../logger.js";

export interface SummaryNode {
  id: string;
  session_id: string;
  depth: number;
  parent_id: string | null;
  summary_text: string;
  token_count: number;
  msg_start: number;
  msg_end: number;
  escalation: number;
  created_at: string;
}

export class LcmDag {
  constructor(private readonly db: Database.Database) {}

  /** Insert a new summary node. */
  insertNode(node: Omit<SummaryNode, "created_at">): void {
    const now = new Date().toISOString();
    this.db
      .prepare(`
        INSERT INTO lcm_summary_nodes (id, session_id, depth, parent_id, summary_text, token_count, msg_start, msg_end, escalation, created_at)
        VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
      `)
      .run(
        node.id,
        node.session_id,
        node.depth,
        node.parent_id,
        node.summary_text,
        node.token_count,
        node.msg_start,
        node.msg_end,
        node.escalation,
        now,
      );

    // Keep FTS in sync
    const rowid = this.db
      .prepare("SELECT rowid FROM lcm_summary_nodes WHERE id = ?")
      .get(node.id) as { rowid: number } | undefined;
    if (rowid) {
      this.db
        .prepare("INSERT INTO lcm_summaries_fts (rowid, summary_text) VALUES (?, ?)")
        .run(rowid.rowid, node.summary_text);
    }
  }

  /** Get leaf nodes (depth=0) for a session without a parent yet, ordered by msg_start. */
  getOrphanNodesAtDepth(sessionId: string, depth: number): SummaryNode[] {
    return this.db
      .prepare(
        "SELECT * FROM lcm_summary_nodes WHERE session_id = ? AND depth = ? AND parent_id IS NULL ORDER BY msg_start",
      )
      .all(sessionId, depth) as SummaryNode[];
  }

  /** Get all nodes at a given depth for a session. */
  getNodesAtDepth(sessionId: string, depth: number): SummaryNode[] {
    return this.db
      .prepare(
        "SELECT * FROM lcm_summary_nodes WHERE session_id = ? AND depth = ? ORDER BY msg_start",
      )
      .all(sessionId, depth) as SummaryNode[];
  }

  /** Get child nodes of a parent. */
  getChildren(parentId: string): SummaryNode[] {
    return this.db
      .prepare("SELECT * FROM lcm_summary_nodes WHERE parent_id = ? ORDER BY msg_start")
      .all(parentId) as SummaryNode[];
  }

  /** Get the deepest summary nodes covering a session (highest depth, broadest coverage). */
  getDeepestNodes(sessionId: string): SummaryNode[] {
    const maxDepth = this.db
      .prepare("SELECT MAX(depth) as max_depth FROM lcm_summary_nodes WHERE session_id = ?")
      .get(sessionId) as { max_depth: number | null } | undefined;

    if (!maxDepth?.max_depth && maxDepth?.max_depth !== 0) return [];

    return this.getNodesAtDepth(sessionId, maxDepth.max_depth);
  }

  /** Get the maximum depth for a session. */
  getMaxDepth(sessionId: string): number {
    const row = this.db
      .prepare("SELECT MAX(depth) as max_depth FROM lcm_summary_nodes WHERE session_id = ?")
      .get(sessionId) as { max_depth: number | null } | undefined;
    return row?.max_depth ?? -1;
  }

  /** Get summary nodes that best cover a turn range, preferring higher depth. */
  getCoveringNodes(sessionId: string, fromTurn: number, toTurn: number): SummaryNode[] {
    return this.db
      .prepare(`
        SELECT * FROM lcm_summary_nodes
        WHERE session_id = ?
          AND msg_start <= ?
          AND msg_end >= ?
        ORDER BY depth DESC, msg_start
      `)
      .all(sessionId, toTurn, fromTurn) as SummaryNode[];
  }

  /** Get all nodes for a session, ordered by depth then range. */
  getAllNodes(sessionId: string): SummaryNode[] {
    return this.db
      .prepare(
        "SELECT * FROM lcm_summary_nodes WHERE session_id = ? ORDER BY depth, msg_start",
      )
      .all(sessionId) as SummaryNode[];
  }

  /** Get total node count for a session. */
  getNodeCount(sessionId: string): number {
    const row = this.db
      .prepare("SELECT COUNT(*) as cnt FROM lcm_summary_nodes WHERE session_id = ?")
      .get(sessionId) as { cnt: number };
    return row.cnt;
  }

  /** Delete all summary and compaction state for one session. */
  deleteSession(sessionId: string): number {
    const txn = this.db.transaction(() => {
      this.db
        .prepare(
          "DELETE FROM lcm_summaries_fts WHERE rowid IN (SELECT rowid FROM lcm_summary_nodes WHERE session_id = ?)",
        )
        .run(sessionId);
      this.db
        .prepare("DELETE FROM lcm_compaction_events WHERE session_id = ?")
        .run(sessionId);
      const result = this.db
        .prepare("DELETE FROM lcm_summary_nodes WHERE session_id = ?")
        .run(sessionId);
      return result.changes;
    });
    return txn();
  }

  /** Delete all summary and compaction state. */
  deleteAll(): number {
    const txn = this.db.transaction(() => {
      this.db.prepare("DELETE FROM lcm_summaries_fts").run();
      this.db.prepare("DELETE FROM lcm_compaction_events").run();
      const result = this.db.prepare("DELETE FROM lcm_summary_nodes").run();
      return result.changes;
    });
    return txn();
  }

  /** Set parent_id for a list of child node IDs. */
  setParent(childIds: string[], parentId: string): void {
    const stmt = this.db.prepare(
      "UPDATE lcm_summary_nodes SET parent_id = ? WHERE id = ?",
    );
    const txn = this.db.transaction(() => {
      for (const childId of childIds) {
        stmt.run(parentId, childId);
      }
    });
    txn();
  }

  /** Record a compaction event. */
  recordCompaction(
    sessionId: string,
    msgBefore: number,
    tokensBefore: number,
    tokensAfter: number,
  ): void {
    this.db
      .prepare(`
        INSERT INTO lcm_compaction_events (session_id, fired_at, msg_before, tokens_before, tokens_after)
        VALUES (?, ?, ?, ?, ?)
      `)
      .run(sessionId, new Date().toISOString(), msgBefore, tokensBefore, tokensAfter);
  }

  /** Prune summary nodes for old sessions. */
  pruneOldNodes(retentionDays: number): number {
    const cutoff = new Date(Date.now() - retentionDays * 86400_000).toISOString();

    this.db
      .prepare(
        "DELETE FROM lcm_summaries_fts WHERE rowid IN (SELECT rowid FROM lcm_summary_nodes WHERE created_at < ?)",
      )
      .run(cutoff);

    const result = this.db
      .prepare("DELETE FROM lcm_summary_nodes WHERE created_at < ?")
      .run(cutoff);
    return result.changes;
  }
}

import type { LcmDag, SummaryNode } from "./dag.js";
import type { LcmArchive } from "./archive.js";
import { log } from "../logger.js";

export interface LcmRecallConfig {
  freshTailTurns: number;
  budgetChars: number;
}

export interface LcmSummarySelectionReceipt {
  id: string;
  depth: number;
  msgStart: number;
  msgEnd: number;
  /** Half-open offsets within the returned compressed-history string. */
  entryStart: number;
  entryEnd: number;
}

export interface LcmRecallWithTraceResult {
  text: string;
  selectedSummaries: LcmSummarySelectionReceipt[];
}

/**
 * Assemble a compressed session history section from the summary DAG.
 *
 * Strategy:
 * 1. For the "fresh tail" (most recent N turns), use leaf-level summaries for maximum detail.
 * 2. For older portions, use the deepest available summary nodes (most compressed).
 * 3. Fill within budget, prioritizing recent content.
 */
export function assembleCompressedHistory(
  dag: LcmDag,
  archive: LcmArchive,
  sessionId: string,
  config: LcmRecallConfig,
): string {
  return assembleCompressedHistoryWithTrace(dag, archive, sessionId, config).text;
}

export function assembleCompressedHistoryWithTrace(
  dag: LcmDag,
  archive: LcmArchive,
  sessionId: string,
  config: LcmRecallConfig,
): LcmRecallWithTraceResult {
  const maxTurn = archive.getMaxTurnIndex(sessionId);
  if (maxTurn < 0) return { text: "", selectedSummaries: [] };

  const allNodes = dag.getAllNodes(sessionId);
  if (allNodes.length === 0) return { text: "", selectedSummaries: [] };

  const freshTailStart = Math.max(0, maxTurn - config.freshTailTurns + 1);
  const sections: string[] = [];
  const selectedNodes: SummaryNode[] = [];
  let usedChars = 0;

  // Collect nodes covering the "old" portion (before fresh tail)
  if (freshTailStart > 0) {
    const oldNodes = selectBestCoverage(allNodes, 0, freshTailStart - 1);
    for (const node of oldNodes) {
      const label = formatRangeLabel(node, maxTurn);
      const entry = `**${label}** (depth ${node.depth}):\n${node.summary_text}`;
      if (usedChars + entry.length > config.budgetChars) break;
      sections.push(entry);
      selectedNodes.push(node);
      usedChars += entry.length;
    }
  }

  // Collect leaf nodes that overlap with the fresh tail region.
  // The old section uses deep nodes (depth > 0), so leaf nodes included here
  // won't duplicate old-section content. Use msg_end >= freshTailStart to
  // include straddling leaf nodes that partially cover the fresh region.
  const freshNodes = allNodes
    .filter(
      (n) => n.depth === 0 && n.msg_end >= freshTailStart && n.msg_end <= maxTurn,
    )
    .sort((a, b) => a.msg_start - b.msg_start);

  for (const node of freshNodes) {
    const label = `Recent (turns ${node.msg_start}-${node.msg_end})`;
    const entry = `**${label}**:\n${node.summary_text}`;
    if (usedChars + entry.length > config.budgetChars) break;
    sections.push(entry);
    selectedNodes.push(node);
    usedChars += entry.length;
  }

  if (sections.length === 0) return { text: "", selectedSummaries: [] };

  const prefix = "## Session History (Compressed)\n\n";
  const text = `${prefix}${sections.join("\n\n")}`;
  let entryStart = prefix.length;
  const selectedSummaries = selectedNodes.map((node, index) => {
    const entryEnd = entryStart + sections[index]!.length;
    const receipt: LcmSummarySelectionReceipt = {
      id: node.id,
      depth: node.depth,
      msgStart: node.msg_start,
      msgEnd: node.msg_end,
      entryStart,
      entryEnd,
    };
    entryStart = entryEnd + 2;
    return receipt;
  });
  return { text, selectedSummaries };
}

/**
 * Select the best coverage for a turn range.
 * Prefers deeper (more compressed) nodes. Avoids overlapping coverage.
 */
function selectBestCoverage(
  allNodes: SummaryNode[],
  fromTurn: number,
  toTurn: number,
): SummaryNode[] {
  // Filter to nodes fully contained in the requested range. Straddling nodes
  // would duplicate protected fresh-tail turns while still emitting their full
  // summary text and range label.
  const candidates = allNodes.filter(
    (n) => n.msg_start >= fromTurn && n.msg_end <= toTurn,
  );

  if (candidates.length === 0) return [];

  // Sort by msg_start ascending, then depth descending (prefer deeper at same position)
  candidates.sort((a, b) => {
    if (a.msg_start !== b.msg_start) return a.msg_start - b.msg_start;
    return b.depth - a.depth;
  });

  // Greedily select non-overlapping nodes, preferring deeper coverage.
  const selected: SummaryNode[] = [];
  let coveredUpTo = fromTurn - 1;

  for (const node of candidates) {
    if (node.msg_start > coveredUpTo) {
      selected.push(node);
      coveredUpTo = node.msg_end;
      if (coveredUpTo >= toTurn) break;
    }
  }

  // Re-sort selected by msg_start for chronological output
  selected.sort((a, b) => a.msg_start - b.msg_start);
  return selected;
}

function formatRangeLabel(node: SummaryNode, maxTurn: number): string {
  const startPct = Math.round((node.msg_start / Math.max(1, maxTurn)) * 100);
  const endPct = Math.round((node.msg_end / Math.max(1, maxTurn)) * 100);

  if (startPct < 33) return `Early session (turns ${node.msg_start}-${node.msg_end})`;
  if (endPct < 66) return `Mid session (turns ${node.msg_start}-${node.msg_end})`;
  return `Later session (turns ${node.msg_start}-${node.msg_end})`;
}

import { Type } from "@sinclair/typebox";
import type { LcmEngine } from "./engine.js";
import { log } from "../logger.js";

interface ToolApi {
  registerTool(
    spec: {
      name: string;
      label: string;
      description: string;
      parameters: unknown;
      execute: (
        toolCallId: string,
        params: Record<string, unknown>,
        signal?: AbortSignal,
      ) => Promise<{ content: Array<{ type: string; text: string }>; details: undefined }>;
    },
    options: { name: string },
  ): void;
}

function toolResult(text: string) {
  return { content: [{ type: "text" as const, text }], details: undefined as undefined };
}

function registerAliasedTool(
  api: ToolApi,
  name: string,
  label: string,
  description: string,
  parameters: unknown,
  execute: (
    toolCallId: string,
    params: Record<string, unknown>,
    signal?: AbortSignal,
  ) => Promise<{ content: Array<{ type: string; text: string }>; details: undefined }>,
): void {
  const aliases = [name];
  if (name.startsWith("engram_")) {
    aliases.unshift(`remnic_${name.slice("engram_".length)}`);
  }

  for (const alias of aliases) {
    api.registerTool(
      {
        name: alias,
        label,
        description,
        parameters,
        execute,
      },
      { name: alias },
    );
  }
}

export function registerLcmTools(api: ToolApi, engine: LcmEngine): void {
  // engram.context_search — FTS search across conversation history
  registerAliasedTool(
    api,
    "engram_context_search",
    "Search Conversation History",
    "Search all conversation history (including compacted regions) by keyword. Returns matching message snippets from the lossless context archive.",
    Type.Object({
      query: Type.String({
        description: "Search query — keywords or phrases",
      }),
      limit: Type.Optional(
        Type.Number({
          description: "Maximum results (default: 10)",
          minimum: 1,
          maximum: 50,
        }),
      ),
      session_id: Type.Optional(
        Type.String({
          description: "Limit search to a specific session",
        }),
      ),
    }),
    async (_toolCallId, params) => {
        const query = params.query as string;
        const limit = (params.limit as number) ?? 10;
        const sessionId = params.session_id as string | undefined;

        const results = await engine.searchContext(query, limit, sessionId);

        if (results.length === 0) {
          return toolResult(`No results found for "${query}" in conversation history.`);
        }

        const formatted = results
          .map(
            (r, i) =>
              `${i + 1}. [${r.session_id}:${r.turn_index}] (${r.role})\n   ${r.snippet}`,
          )
          .join("\n\n");

        return toolResult(
          `## Context Search: "${query}"\n\nFound ${results.length} result(s):\n\n${formatted}`,
        );
      },
  );

  // engram.context_describe — Get compressed summary of a turn range
  registerAliasedTool(
    api,
    "engram_context_describe",
    "Describe Conversation Range",
    "Get a compressed summary of a conversation turn range. Uses the hierarchical summary DAG to provide the best available summary.",
    Type.Object({
      session_id: Type.String({
        description: "Session ID to describe",
      }),
      from_turn: Type.Number({
        description: "Start turn index",
        minimum: 0,
      }),
      to_turn: Type.Number({
        description: "End turn index",
        minimum: 0,
      }),
    }),
    async (_toolCallId, params) => {
        const sessionId = params.session_id as string;
        const fromTurn = params.from_turn as number;
        const toTurn = params.to_turn as number;

        const result = await engine.describeContext(sessionId, fromTurn, toTurn);
        if (!result) {
          return toolResult(`No data found for session "${sessionId}" turns ${fromTurn}-${toTurn}.`);
        }

        return toolResult(
          `## Context Description (turns ${fromTurn}-${toTurn})\n\n` +
            `**Turns covered:** ${result.turn_count} | **Summary depth:** ${result.depth}\n\n` +
            result.summary,
        );
      },
  );

  // engram.context_expand — Retrieve raw messages (lossless)
  registerAliasedTool(
    api,
    "engram_context_expand",
    "Expand Conversation Range",
    "Retrieve full conversation messages for a turn range (lossless). Use this to recover the exact content of messages that may have been compacted.",
    Type.Object({
      session_id: Type.String({
        description: "Session ID to expand",
      }),
      from_turn: Type.Number({
        description: "Start turn index",
        minimum: 0,
      }),
      to_turn: Type.Number({
        description: "End turn index",
        minimum: 0,
      }),
      max_tokens: Type.Optional(
        Type.Number({
          description: "Maximum tokens to return (default: 8000)",
          minimum: 100,
          maximum: 32000,
        }),
      ),
    }),
    async (_toolCallId, params) => {
        const sessionId = params.session_id as string;
        const fromTurn = params.from_turn as number;
        const toTurn = params.to_turn as number;
        const maxTokens = (params.max_tokens as number) ?? 8000;

        const messages = await engine.expandContext(sessionId, fromTurn, toTurn, maxTokens);
        if (messages.length === 0) {
          return toolResult(
            `No messages found for session "${sessionId}" turns ${fromTurn}-${toTurn}.`,
          );
        }

        const formatted = messages
          .map((m) => `### Turn ${m.turn_index} (${m.role})\n\n${m.content}`)
          .join("\n\n---\n\n");

        return toolResult(
          `## Context Expansion (turns ${fromTurn}-${toTurn})\n\n` +
            `**Messages:** ${messages.length}\n\n${formatted}`,
        );
      },
  );
}

import path from "node:path";
import { mkdir } from "node:fs/promises";
import { log } from "../logger.js";
import {
  openBetterSqlite3,
  type BetterSqlite3Database,
} from "../runtime/better-sqlite.js";

const LCM_SCHEMA_VERSION = 2;

export function openLcmDatabase(memoryDir: string): BetterSqlite3Database {
  const dbPath = path.join(memoryDir, "state", "lcm.sqlite");
  const db = openBetterSqlite3(dbPath);
  db.pragma("journal_mode = WAL");
  db.pragma("busy_timeout = 5000");
  db.pragma("synchronous = NORMAL");
  applySchema(db);
  return db;
}

export async function ensureLcmStateDir(memoryDir: string): Promise<void> {
  await mkdir(path.join(memoryDir, "state"), { recursive: true });
}

/**
 * Apply (or upgrade) the LCM schema on an already-open SQLite handle.
 *
 * Exposed so optional host packages — e.g. importers using an in-memory
 * destination database for true read-only `--dry-run` execution — can
 * bootstrap the schema without going through `openLcmDatabase()` (which
 * always touches the filesystem).
 */
export function applyLcmSchema(db: BetterSqlite3Database): void {
  applySchema(db);
}

function applySchema(db: BetterSqlite3Database): void {
  const versionRow = db
    .prepare("SELECT name FROM sqlite_master WHERE type='table' AND name='lcm_meta'")
    .get() as { name: string } | undefined;

  if (!versionRow) {
    createTables(db);
    return;
  }

  const meta = db
    .prepare("SELECT value FROM lcm_meta WHERE key = 'schema_version'")
    .get() as { value: string } | undefined;
  const currentVersion = meta ? parseInt(meta.value, 10) : 0;

  if (currentVersion < LCM_SCHEMA_VERSION) {
    log.info(`LCM schema upgrade: v${currentVersion} → v${LCM_SCHEMA_VERSION}`);
    createTables(db);
  }
}

function createTables(db: BetterSqlite3Database): void {
  db.exec(`
    CREATE TABLE IF NOT EXISTS lcm_meta (
      key   TEXT PRIMARY KEY,
      value TEXT NOT NULL
    );

    CREATE TABLE IF NOT EXISTS lcm_messages (
      id          INTEGER PRIMARY KEY AUTOINCREMENT,
      session_id  TEXT NOT NULL,
      turn_index  INTEGER NOT NULL,
      role        TEXT NOT NULL,
      content     TEXT NOT NULL,
      token_count INTEGER NOT NULL,
      created_at  TEXT NOT NULL,
      metadata    TEXT
    );
    CREATE INDEX IF NOT EXISTS idx_lcm_messages_session
      ON lcm_messages(session_id, turn_index);

    CREATE TABLE IF NOT EXISTS lcm_message_parts (
      id          INTEGER PRIMARY KEY AUTOINCREMENT,
      message_id  INTEGER NOT NULL REFERENCES lcm_messages(id) ON DELETE CASCADE,
      ordinal     INTEGER NOT NULL,
      kind        TEXT NOT NULL,
      payload     TEXT NOT NULL,
      tool_name   TEXT,
      file_path   TEXT,
      created_at  TEXT NOT NULL
    );
    CREATE INDEX IF NOT EXISTS idx_lcm_message_parts_msg
      ON lcm_message_parts(message_id, ordinal);
    CREATE INDEX IF NOT EXISTS idx_lcm_message_parts_tool
      ON lcm_message_parts(tool_name);
    CREATE INDEX IF NOT EXISTS idx_lcm_message_parts_file
      ON lcm_message_parts(file_path);

    CREATE TABLE IF NOT EXISTS lcm_summary_nodes (
      id            TEXT PRIMARY KEY,
      session_id    TEXT NOT NULL,
      depth         INTEGER NOT NULL,
      parent_id     TEXT,
      summary_text  TEXT NOT NULL,
      token_count   INTEGER NOT NULL,
      msg_start     INTEGER NOT NULL,
      msg_end       INTEGER NOT NULL,
      escalation    INTEGER NOT NULL DEFAULT 0,
      created_at    TEXT NOT NULL,
      FOREIGN KEY (parent_id) REFERENCES lcm_summary_nodes(id)
    );
    CREATE INDEX IF NOT EXISTS idx_lcm_summary_session
      ON lcm_summary_nodes(session_id, depth);
    CREATE INDEX IF NOT EXISTS idx_lcm_summary_range
      ON lcm_summary_nodes(session_id, msg_start, msg_end);

    CREATE TABLE IF NOT EXISTS lcm_compaction_events (
      id            INTEGER PRIMARY KEY AUTOINCREMENT,
      session_id    TEXT NOT NULL,
      fired_at      TEXT NOT NULL,
      msg_before    INTEGER NOT NULL,
      tokens_before INTEGER NOT NULL,
      tokens_after  INTEGER NOT NULL
    );
  `);

  // FTS5 tables — created separately so IF NOT EXISTS works correctly
  const hasFts = db
    .prepare("SELECT name FROM sqlite_master WHERE type='table' AND name='lcm_messages_fts'")
    .get();
  if (!hasFts) {
    db.exec(`
      CREATE VIRTUAL TABLE lcm_messages_fts USING fts5(
        content,
        content=lcm_messages,
        content_rowid=id
      );
    `);
  }

  const hasSummaryFts = db
    .prepare("SELECT name FROM sqlite_master WHERE type='table' AND name='lcm_summaries_fts'")
    .get();
  if (!hasSummaryFts) {
    db.exec(`
      CREATE VIRTUAL TABLE lcm_summaries_fts USING fts5(
        summary_text,
        content=lcm_summary_nodes,
        content_rowid=rowid
      );
    `);
  }

  // Upsert meta version
  db.prepare("INSERT OR REPLACE INTO lcm_meta (key, value) VALUES ('schema_version', ?)").run(
    String(LCM_SCHEMA_VERSION),
  );
}

import { summarizeContextPure, type SummarizeFn } from "../context-summary.js";
import { estimateTokens } from "./archive.js";
import type { LcmArchive, LcmMessage } from "./archive.js";
import type { LcmDag } from "./dag.js";

/** Generate a ULID-like ID (timestamp + random). */
function generateNodeId(): string {
  const ts = Date.now().toString(36).padStart(9, "0");
  const rand = Math.random().toString(36).slice(2, 10);
  return `lcm-${ts}-${rand}`;
}

// `SummarizeFn` moved to the shared pure summary seam (context-summary.ts,
// #2347); re-exported here for back-compat with existing imports.
export type { SummarizeFn };

export interface LcmSummarizerConfig {
  leafBatchSize: number;
  rollupFanIn: number;
  maxDepth: number;
  deterministicMaxTokens: number;
  telemetryPrefilterEnabled: boolean;
}

export class LcmSummarizer {
  constructor(
    private readonly archive: LcmArchive,
    private readonly dag: LcmDag,
    private readonly summarizeFn: SummarizeFn,
    private readonly config: LcmSummarizerConfig,
  ) {}

  /**
   * Run incremental summarization for a session.
   * Creates leaf nodes from unsummarized messages, then rolls up as needed.
   *
   * `maxLeafBatches` bounds one pass: the archive read is limited to that
   * many complete batches, so a long backlog never loads the whole
   * unsummarized tail into memory. Remaining batches stay durable in the
   * archive and are picked up by the next pass.
   */
  async summarizeIncremental(
    sessionId: string,
    options: { maxLeafBatches?: number } = {},
  ): Promise<number> {
    let nodesCreated = 0;

    // Phase 1: Create leaf nodes from unsummarized messages
    const maxLeafBatches = options.maxLeafBatches;
    const readLimit =
      maxLeafBatches === undefined
        ? undefined
        : maxLeafBatches * this.config.leafBatchSize;
    const unsummarized = this.archive.getUnsummarizedMessages(sessionId, readLimit);
    if (unsummarized.length >= this.config.leafBatchSize) {
      const batches = chunkArray(unsummarized, this.config.leafBatchSize);
      // Only process complete batches (leave partial for next time)
      const completeBatches = unsummarized.length % this.config.leafBatchSize === 0
        ? batches
        : batches.slice(0, -1);

      for (const batch of completeBatches) {
        const created = await this.createLeafNode(sessionId, batch);
        if (created) nodesCreated++;
      }
    }

    // Phase 2: Roll up at each depth level
    if (nodesCreated > 0) {
      nodesCreated += await this.rollupAll(sessionId);
    }

    return nodesCreated;
  }

  /** Create a leaf summary node (depth 0) from a batch of messages. */
  private async createLeafNode(
    sessionId: string,
    messages: LcmMessage[],
  ): Promise<boolean> {
    if (messages.length === 0) return false;

    const combinedText = messages
      .map((m) => `[${m.role}] ${m.content}`)
      .join("\n\n");

    const inputTokens = estimateTokens(combinedText);
    const targetTokens = Math.max(64, Math.ceil(inputTokens * 0.25));

    const summary = await this.summarizeWithEscalation(combinedText, targetTokens);

    this.dag.insertNode({
      id: generateNodeId(),
      session_id: sessionId,
      depth: 0,
      parent_id: null,
      summary_text: summary.text,
      token_count: estimateTokens(summary.text),
      msg_start: messages[0].turn_index,
      msg_end: messages[messages.length - 1].turn_index,
      escalation: summary.escalation,
    });

    return true;
  }

  /** Roll up orphan nodes at each depth level up to maxDepth. */
  private async rollupAll(sessionId: string): Promise<number> {
    let totalCreated = 0;

    for (let depth = 0; depth < this.config.maxDepth; depth++) {
      const orphans = this.dag.getOrphanNodesAtDepth(sessionId, depth);
      if (orphans.length < this.config.rollupFanIn) continue;

      const batches = chunkArray(orphans, this.config.rollupFanIn);
      // Only process complete batches
      const completeBatches = orphans.length % this.config.rollupFanIn === 0
        ? batches
        : batches.slice(0, -1);

      for (const batch of completeBatches) {
        const combinedText = batch
          .map((n) => n.summary_text)
          .join("\n\n");

        const inputTokens = estimateTokens(combinedText);
        const targetTokens = Math.max(64, Math.ceil(inputTokens * 0.25));

        const summary = await this.summarizeWithEscalation(combinedText, targetTokens);

        const parentId = generateNodeId();
        this.dag.insertNode({
          id: parentId,
          session_id: sessionId,
          depth: depth + 1,
          parent_id: null,
          summary_text: summary.text,
          token_count: estimateTokens(summary.text),
          msg_start: batch[0].msg_start,
          msg_end: batch[batch.length - 1].msg_end,
          escalation: summary.escalation,
        });

        this.dag.setParent(
          batch.map((n) => n.id),
          parentId,
        );

        totalCreated++;
      }
    }

    return totalCreated;
  }

  /**
   * Three-level escalation, delegated to the shared pure summary seam
   * (context-summary.ts): 0 = normal LLM, 1 = aggressive, 2 = deterministic.
   */
  private async summarizeWithEscalation(
    text: string,
    targetTokens: number,
  ): Promise<{ text: string; escalation: number }> {
    const { deterministicMaxTokens, telemetryPrefilterEnabled } = this.config;
    const result = await summarizeContextPure(text, targetTokens, "auto", {
      llm: this.summarizeFn,
      deterministicMaxTokens,
      telemetryPrefilterEnabled,
    });
    return { text: result.text, escalation: result.escalation ?? 2 };
  }
}


function chunkArray<T>(arr: T[], size: number): T[][] {
  const chunks: T[][] = [];
  for (let i = 0; i < arr.length; i += size) {
    chunks.push(arr.slice(i, i + size));
  }
  return chunks;
}

import path from "node:path";
import type { PluginConfig } from "../types.js";
import { namespaceIdentityToken, normalizeNamespaceIdentity } from "./identity.js";
import { mergeNewerTouchFields } from "./catalog.js";
import type { NamespaceRecord } from "./catalog.js";
import { isSafeRouteNamespace } from "../routing/engine.js";

/**
 * Read-boundary sanitation for NamespaceCatalog (extracted in #3297): the two
 * defenses against a tampered or pre-fix `namespaces.jsonl` row, and the
 * storage-root alias collapse that picks one owner per physical root.
 */
export interface CatalogReadBoundaryPort {
  defaultNamespaceIdentity: string;
  memoryDir: string;
  isContainedStorageDir(candidate: string): Promise<boolean>;
  isStorageDirForNamespace(
    namespace: string,
    candidate: string,
  ): Promise<boolean>;
  resolveSafeStorageDir(namespace: string): Promise<string>;
}

/**
 * Sanitize a record at the enumeration boundary (round 5, cursor Medium + codex
 * P2; round 6 — NDXHe). Reads return whatever is in `namespaces.jsonl` after
 * schema checks only, so a tampered or pre-fix row could surface unsafe data to
 * maintenance/QMD until a rewrite occurs. Two distinct defenses:
 *
 *  1. UNSAFE NAMESPACE NAME (NGZqr, codex P2): an unsafe non-default namespace
 *     (e.g. `../evil`, a name with separators, or >64 chars) is REJECTED outright
 *     — return `null` so the caller drops it. The disk SCAN and the hot touch
 *     path both reject such names with the SAME default-exempt `isSafeRouteNamespace`
 *     gate, so the read boundary MUST agree, or `listNamespaces()`/`getNamespaceRecord()`
 *     would expose a namespace those paths reject (note `isStorageDirForNamespace`
 *     can still build a tokenized root even for `../evil`, so storageDir sanitation
 *     alone does not catch it). The default namespace is exempt (it may be a
 *     non-route literal), matching every other validation site.
 *
 *  2. UNSAFE storageDir: for an otherwise-valid namespace, apply the SAME contract
 *     as the write path — full containment (`isContainedStorageDir`: lexical +
 *     symlink/realpath) AND namespace ownership (`isStorageDirForNamespace`). When
 *     a record fails EITHER check we substitute the trusted resolved-and-safe root
 *     for that namespace (rule 42: read and write stay symmetric).
 */
export async function sanitizeRecordForRead(
  port: CatalogReadBoundaryPort,
  record: NamespaceRecord,
): Promise<NamespaceRecord | null> {
  // Defense 1: drop an unsafe non-default namespace name entirely. Compare
  // against the NORMALIZED default identity — record keys are trimmed, so a raw
  // whitespace-padded config default would never match the default row (NH-FH).
  if (
    record.namespace !== port.defaultNamespaceIdentity &&
    !isSafeRouteNamespace(record.namespace)
  ) {
    return null;
  }
  // Defense 2: keep the record but substitute a safe storageDir when needed.
  if (
    (await port.isContainedStorageDir(record.storageDir)) &&
    (await port.isStorageDirForNamespace(record.namespace, record.storageDir))
  ) {
    return record;
  }
  const safe = await port.resolveSafeStorageDir(record.namespace);
  return { ...record, storageDir: safe };
}

export function storageRootOwnershipRank(
  port: CatalogReadBoundaryPort,
  record: NamespaceRecord,
  resolvedStorageDir: string,
  configured: Set<string>,
): number {
  if (resolvedStorageDir === path.resolve(port.memoryDir)) {
    return record.namespace === port.defaultNamespaceIdentity ? 0 : 3;
  }

  const leaf = path.basename(resolvedStorageDir);
  const tokenOwnsRoot = namespaceIdentityToken(record.namespace) === leaf;
  if (tokenOwnsRoot && configured.has(record.namespace)) {
    return 0;
  }
  if (record.namespace === leaf) return 1;
  if (tokenOwnsRoot) return 2;
  return 3;
}

export function configuredNamespaceIdentities(
  config: PluginConfig,
): Set<string> {
  return new Set(
    [
      config.defaultNamespace,
      config.sharedNamespace,
      ...config.namespacePolicies.map((p) => p.name),
    ]
      .map((n) => normalizeNamespaceIdentity(n))
      .filter((n) => n.length > 0),
  );
}

export function preferStorageRootOwner(
  port: CatalogReadBoundaryPort,
  current: NamespaceRecord,
  candidate: NamespaceRecord,
  resolvedStorageDir: string,
  configured: Set<string>,
): NamespaceRecord {
  const currentRank = storageRootOwnershipRank(
    port,
    current,
    resolvedStorageDir,
    configured,
  );
  const candidateRank = storageRootOwnershipRank(
    port,
    candidate,
    resolvedStorageDir,
    configured,
  );
  if (candidateRank < currentRank) return candidate;
  if (candidateRank > currentRank) return current;

  const byName = candidate.namespace.localeCompare(current.namespace);
  if (byName < 0) return candidate;
  if (byName > 0) return current;
  return candidate.identityToken.localeCompare(current.identityToken) < 0
    ? candidate
    : current;
}

export function dropDuplicateStorageRootAliases(
  port: CatalogReadBoundaryPort,
  records: NamespaceRecord[],
  config: PluginConfig,
): NamespaceRecord[] {
  const byStorageDir = new Map<string, NamespaceRecord>();
  const configured = configuredNamespaceIdentities(config);
  for (const record of records) {
    const resolvedStorageDir = path.resolve(record.storageDir);
    const current = byStorageDir.get(resolvedStorageDir);
    if (!current) {
      byStorageDir.set(resolvedStorageDir, record);
      continue;
    }
    const owner = preferStorageRootOwner(
      port,
      current,
      record,
      resolvedStorageDir,
      configured,
    );
    const alias = owner === current ? record : current;
    byStorageDir.set(resolvedStorageDir, mergeNewerTouchFields(owner, alias));
  }
  return [...byStorageDir.values()];
}

/**
 * Per-token capabilities (issue #1837).
 *
 * A token entry MAY carry an explicit, versioned capabilities record. The
 * record's PRESENCE is mechanically detectable, which is load-bearing for
 * security:
 *
 *   - ABSENT `capabilities` field ⇒ a PRE-FEATURE legacy entry (minted
 *     before this feature). It is UNRESTRICTED — full access — purely for
 *     backward compatibility. This is the ONLY path by which "full access"
 *     is granted by omission.
 *
 *   - PRESENT `capabilities` record (always carries a `version` marker) ⇒ a
 *     token minted by the capability-aware path. Even a new token minted
 *     without `--ops`/`--namespaces` records an EXPLICIT unrestricted record
 *     (`{ version: 1 }`) — a deliberate, auditable choice, never an
 *     accidentally-omitted field. Within the record, the two axes follow
 *     absent-vs-present semantics:
 *       * axis ABSENT (e.g. no `ops` key)        ⇒ unrestricted on that axis.
 *       * axis PRESENT and empty (`ops: []`)     ⇒ deny all (fail-closed).
 *       * axis PRESENT and non-empty             ⇒ allow only the listed values.
 *
 * Malformed capability input at mint time (bad version, non-array axes,
 * non-string elements, unknown op names against the catalog, malformed
 * namespace values) is REJECTED — a token is never created from invalid
 * input (rule: invalid input rejected, not defaulted).
 *
 * This module owns the pure capability logic (shape validation, allow-list
 * checks) and the per-request AsyncLocalStorage carrying the presenting
 * token's resolved capabilities down to the access boundary. It imports
 * nothing else in the package except the forbidden-error class, so it can be
 * reused by the token store, the boundary, and the HTTP/MCP surfaces without
 * cycles.
 */

import { AsyncLocalStorage } from "node:async_hooks";
import { EngramAccessForbiddenError } from "./access-errors.js";

/** Current capability-record schema version. */
export const TOKEN_CAPABILITIES_VERSION = 1 as const;

/**
 * Versioned capabilities record stored on a token entry. Presence of this
 * record (vs. an absent field) is what distinguishes a capability-aware
 * token from a pre-feature legacy entry.
 */
export interface TokenCapabilities {
  readonly version: typeof TOKEN_CAPABILITIES_VERSION;
  /**
   * Operations allow-list. `undefined` (key absent) ⇒ unrestricted on this
   * axis. `[]` ⇒ deny all ops (fail-closed). Non-empty ⇒ allow only listed.
   */
  ops?: string[];
  /**
   * Namespaces allow-list. `undefined` ⇒ unrestricted. `[]` ⇒ deny all.
   * Non-empty ⇒ allow only listed.
   */
  namespaces?: string[];
}

/**
 * Namespace value validation. Namespace identifiers are flexible (default,
 * team, self, principal-prefixed, project-prefixed) but must never contain
 * whitespace, path separators, traversal segments, or control characters —
 * such values are malformed at mint time and rejected, never silently
 * coerced.
 */
const NAMESPACE_VALUE_MAX_LENGTH = 128;
// Non-empty, no whitespace, no path separators, no control chars. `.` and
// `..` are rejected separately so legitimate dotted names (e.g. a domain)
// remain allowed while traversal is not.
const NAMESPACE_VALUE_PATTERN = /^[^\s\/\\\x00-\x1F]+$/;

/** True when `value` is an acceptable namespace allow-list entry. */
export function isValidNamespaceValue(value: unknown): value is string {
  if (typeof value !== "string" || value.length === 0 || value.length > NAMESPACE_VALUE_MAX_LENGTH) {
    return false;
  }
  if (!NAMESPACE_VALUE_PATTERN.test(value)) return false;
  if (value === "." || value === "..") return false;
  return true;
}

function isStringArray(value: unknown): value is unknown[] {
  return Array.isArray(value) && value.every((v) => typeof v === "string");
}

function dedupeSort(values: string[]): string[] {
  return [...new Set(values)].sort();
}

/**
 * Parse one axis (ops or namespaces) for PERSISTENCE/LOAD. Returns the
 * cleaned array (deduped, sorted; possibly empty to preserve "present ⇒
 * fail-closed") or `undefined` when the key is absent. Throws on a malformed
 * shape (non-array, non-string elements, malformed namespace values). Op
 * validation against the catalog happens only at mint time.
 */
function parseAxis(
  obj: Record<string, unknown>,
  key: "ops" | "namespaces",
  validateValue: (v: unknown) => boolean,
  valueLabel: string,
): string[] | undefined {
  if (!Object.prototype.hasOwnProperty.call(obj, key)) return undefined;
  const value = obj[key];
  if (value === undefined || value === null) return undefined;
  if (!isStringArray(value)) {
    throw new Error(`capabilities ${key} must be an array of non-empty strings`);
  }
  const cleaned: string[] = [];
  for (const v of value) {
    if (typeof v !== "string" || v.length === 0) {
      throw new Error(`capabilities ${key} must be an array of non-empty strings`);
    }
    if (!validateValue(v)) {
      throw new Error(`capabilities ${key} contains a malformed ${valueLabel}: ${JSON.stringify(v)}`);
    }
    cleaned.push(v);
  }
  // Preserve presence: an explicitly empty array stays [] (fail-closed),
  // NOT coerced to undefined (which would mean unrestricted).
  return dedupeSort(cleaned);
}

/**
 * Normalize a capabilities record for PERSISTENCE/LOAD. Returns `undefined`
 * ONLY when the record is entirely absent (a pre-feature legacy entry ⇒
 * unrestricted). When present, an absent/`undefined` `version` is COERCED to
 * the current default (1) — mirroring {@link validateCapabilitiesForMint} — so
 * a record that mint-validated also load-normalizes without a schema throw.
 * An explicitly-present WRONG version (not 1) is still rejected. Throws on a
 * malformed record (non-object, explicitly-wrong version, malformed axes).
 */
export function normalizeCapabilities(raw: unknown): TokenCapabilities | undefined {
  if (raw === undefined || raw === null) return undefined;
  if (typeof raw !== "object" || Array.isArray(raw)) {
    throw new Error("capabilities must be an object with a version marker");
  }
  const obj = raw as Record<string, unknown>;
  // Coerce absent/undefined version → 1, mirroring validateCapabilitiesForMint
  // (version 1 is the only schema version; coercing keeps mint-validated
  // records reloadable). Only an explicitly-present WRONG version throws.
  if (obj.version !== undefined && obj.version !== TOKEN_CAPABILITIES_VERSION) {
    throw new Error(`capabilities.version must be ${TOKEN_CAPABILITIES_VERSION}`);
  }
  const ops = parseAxis(obj, "ops", () => true, "operation");
  const namespaces = parseAxis(obj, "namespaces", isValidNamespaceValue, "namespace");
  const result: TokenCapabilities = { version: TOKEN_CAPABILITIES_VERSION };
  if (ops !== undefined) result.ops = ops;
  if (namespaces !== undefined) result.namespaces = namespaces;
  return result;
}

/**
 * Validate a capabilities record at MINT time. ALWAYS returns a versioned
 * record (never `undefined`) so every newly-minted token carries an explicit
 * capability decision — a new token can never gain full access by OMITTING
 * the field. When `raw` is absent/null, the result is an explicit
 * unrestricted record (`{ version: 1 }`), a deliberate/auditable choice. A
 * present-but-`undefined` (or absent) `version` is coerced to the current
 * default (1); an explicitly-wrong version is rejected. This version rule is
 * identical to {@link normalizeCapabilities} (mint/load symmetry). Rejects
 * unknown op names against the catalog and malformed namespace values;
 * throws a plain Error — the caller must NOT create a token when this throws.
 */
export function validateCapabilitiesForMint(
  raw: unknown,
  validOps: readonly string[],
): TokenCapabilities {
  const result: TokenCapabilities = { version: TOKEN_CAPABILITIES_VERSION };
  if (raw === undefined || raw === null) {
    return result;
  }
  if (typeof raw !== "object" || Array.isArray(raw)) {
    throw new Error("capabilities must be an object with optional ops/namespaces arrays");
  }
  const obj = raw as Record<string, unknown>;
  if (Object.prototype.hasOwnProperty.call(obj, "version") && obj.version !== undefined) {
    if (obj.version !== TOKEN_CAPABILITIES_VERSION) {
      throw new Error(`capabilities.version must be ${TOKEN_CAPABILITIES_VERSION}`);
    }
  }
  const validOpSet = new Set(validOps);

  if (Object.prototype.hasOwnProperty.call(obj, "ops") && obj.ops !== undefined && obj.ops !== null) {
    if (!isStringArray(obj.ops)) {
      throw new Error("capabilities ops must be an array of non-empty strings");
    }
    const ops = obj.ops as unknown[];
    for (const v of ops) {
      if (typeof v !== "string" || v.length === 0) {
        throw new Error("capabilities ops must be an array of non-empty strings");
      }
    }
    // Reject unknown op names against the catalog (unknown ⇒ reject, never drop).
    const unknown = ops.filter((op) => typeof op === "string" && !validOpSet.has(op));
    if (unknown.length > 0) {
      throw new Error(
        `capabilities ops contains unknown operation name(s): ${unknown.map((o) => JSON.stringify(o)).join(", ")}`,
      );
    }
    // Preserve presence (empty stays [] ⇒ deny all ops).
    result.ops = dedupeSort(ops as string[]);
  }

  if (
    Object.prototype.hasOwnProperty.call(obj, "namespaces") &&
    obj.namespaces !== undefined &&
    obj.namespaces !== null
  ) {
    if (!isStringArray(obj.namespaces)) {
      throw new Error("capabilities namespaces must be an array of non-empty strings");
    }
    const namespaces = obj.namespaces as unknown[];
    for (const v of namespaces) {
      if (typeof v !== "string" || v.length === 0) {
        throw new Error("capabilities namespaces must be an array of non-empty strings");
      }
      if (!isValidNamespaceValue(v)) {
        throw new Error(`capabilities namespaces contains a malformed namespace: ${JSON.stringify(v)}`);
      }
    }
    result.namespaces = dedupeSort(namespaces as string[]);
  }

  return result;
}

/**
 * True when `caps` imposes any restriction (a present record with at least
 * one axis key). `undefined` (legacy / absent record) ⇒ unrestricted. A
 * present `{ version: 1 }` record with no axes ⇒ also unrestricted (but
 * auditable — it is a deliberate new-token decision, not omission).
 */
export function isCapabilityRestricted(caps: TokenCapabilities | undefined | null): boolean {
  if (!caps) return false;
  return caps.ops !== undefined || caps.namespaces !== undefined;
}

/**
 * True when `caps` permits `op`.
 *   - record ABSENT (legacy) ⇒ unrestricted (true).
 *   - ops axis ABSENT        ⇒ unrestricted on this axis (true).
 *   - ops axis PRESENT       ⇒ `op` must be listed; `[]` ⇒ false (deny all).
 */
export function capabilityAllowsOp(caps: TokenCapabilities | undefined | null, op: string): boolean {
  if (caps?.ops === undefined) return true;
  return caps.ops.includes(op);
}

/**
 * The operation policy that all access surfaces use to decide whether a token
 * can invoke an operation.
 */
export interface OperationAuthorizationPolicy {
  readonly name: string;
  readonly allowedByOps?: readonly string[];
  readonly fleetWide?: boolean;
}

/**
 * Apply an operation's alternate grant and fleet-wide restrictions without
 * invoking its handler.
 */
export function assertOperationAuthorizationAllowed(
  caps: TokenCapabilities | undefined | null,
  operation: OperationAuthorizationPolicy,
): void {
  if (operation.allowedByOps && operation.allowedByOps.length > 0) {
    if (!operation.allowedByOps.some((allowedOperation) => capabilityAllowsOp(caps, allowedOperation))) {
      throw new EngramAccessForbiddenError(`token is not permitted to call operation: ${operation.name}`);
    }
  } else {
    assertOperationAllowed(caps, operation.name);
  }

  if (operation.fleetWide) {
    assertFleetWideOperationAllowed(caps);
  }
}

/**
 * True when `caps` permits `namespace`.
 *   - record ABSENT / namespaces axis ABSENT ⇒ unrestricted (true).
 *   - namespaces axis PRESENT ⇒ `namespace` must be listed; undefined
 *     namespace ⇒ false; `[]` ⇒ false (deny all).
 */
export function capabilityAllowsNamespace(
  caps: TokenCapabilities | undefined | null,
  namespace: string | undefined,
): boolean {
  if (caps?.namespaces === undefined) return true;
  if (namespace === undefined) return false;
  return caps.namespaces.includes(namespace);
}

/**
 * Throw {@link EngramAccessForbiddenError} when `caps` restricts ops and
 * `op` is not permitted. No-op for unrestricted tokens.
 */
export function assertOperationAllowed(
  caps: TokenCapabilities | undefined | null,
  op: string,
): void {
  if (!capabilityAllowsOp(caps, op)) {
    throw new EngramAccessForbiddenError(
      `token is not permitted to call operation: ${op}`,
    );
  }
}

/**
 * Throw {@link EngramAccessForbiddenError} when `caps` restricts namespaces
 * and `namespace` is not permitted. No-op for unrestricted tokens.
 */
export function assertNamespaceAllowed(
  caps: TokenCapabilities | undefined | null,
  namespace: string | undefined,
): void {
  if (!capabilityAllowsNamespace(caps, namespace)) {
    throw new EngramAccessForbiddenError(
      namespace === undefined
        ? "token is scoped to specific namespaces and this operation requires an explicit namespace"
        : `token is not permitted to access namespace: ${namespace}`,
    );
  }
}

/**
 * Resolve the EFFECTIVE namespace an operation runs against: a present,
 * non-empty request namespace wins, otherwise the server default — the same
 * resolution downstream storage applies
 * (`getWritableStorageForNamespace(undefined)` → `defaultNamespace`). Empty
 * strings are treated as absent. Centralized so every invocation surface
 * (HTTP query/body, MCP `tools/call`, id-loaded records, legacy pairs that
 * carry no namespace) applies ONE rule and none can dodge the check by
 * dropping the param. (issue #1850)
 */
export function resolveEffectiveNamespace(
  namespace: string | undefined,
  defaultNamespace: string | undefined,
): string | undefined {
  const normalized = namespace !== undefined && namespace.length > 0 ? namespace : undefined;
  return normalized ?? defaultNamespace;
}

/**
 * The single effective-namespace allow-list chokepoint (issues #1837/#1850).
 * Throws {@link EngramAccessForbiddenError} when `caps` carries a namespaces
 * allow-list and the EFFECTIVE namespace (request value OR server default) is
 * not a member. FAIL CLOSED:
 *   - a scoped token whose allow-list does not cover the effective namespace
 *     (explicit OR defaulted) is rejected;
 *   - an absent server default (unconfigured) is also rejected for scoped
 *     tokens, so omitting `?namespace=` can never bypass the allow-list.
 * No-op for unrestricted tokens (no namespaces axis) so legacy/unrestricted
 * behavior is unchanged. Both the HTTP transport (`resolveNamespace`) and the
 * MCP dispatch route through this ONE function so no surface is missed.
 */
export function isNamespaceAllowed(
  caps: TokenCapabilities | undefined | null,
  namespace: string | undefined,
  defaultNamespace: string | undefined,
): boolean {
  if (caps?.namespaces === undefined) return true; // unrestricted token
  const effective = resolveEffectiveNamespace(namespace, defaultNamespace);
  return effective !== undefined && caps.namespaces.includes(effective);
}

export function enforceNamespaceAllowList(
  caps: TokenCapabilities | undefined | null,
  namespace: string | undefined,
  defaultNamespace: string | undefined,
): void {
  if (isNamespaceAllowed(caps, namespace, defaultNamespace)) return;
  throw new EngramAccessForbiddenError(
    namespace === undefined
      ? "token is scoped to specific namespaces; the server default namespace is not permitted — supply an allowed namespace"
      : `token is not permitted to access namespace: ${namespace}`,
  );
}

/**
 * Fleet-wide / global maintenance operation guard (issue #1850 round 10).
 *
 * A distinct escalation class from the id-addressed routes (round 9) and the
 * param-namespace ops (round 4): some boundary operations inherently run
 * ACROSS ALL namespaces — or against a single global layer (compression
 * guidelines, shared context, compounding) that is not namespace-partitioned
 * — and carry NO `namespace` argument, so the MCP `tools/call` effective-
 * namespace chokepoint ({@link enforceNamespaceAllowList}, which only fires
 * when `toolAcceptsNamespace`) never applies. Without this guard a bearer
 * scoped to ONE tenant could trigger maintenance that mutates state in EVERY
 * namespace (privilege escalation).
 *
 * Fail CLOSED exactly like the other shared guards: a namespace-SCOPED token
 * (namespaces axis present) is rejected; unrestricted / legacy tokens (absent
 * record or no namespaces axis — i.e. cron and internal callers that never
 * bind a capability record) are unaffected. Reuses the EXISTING capability
 * model via {@link capabilityAllowsNamespace} — no new "all"/"*" scope concept.
 * Must run BEFORE any side effect so a denial never leaks a partial mutation.
 */
export function assertFleetWideOperationAllowed(
  caps: TokenCapabilities | undefined | null,
): void {
  // capabilityAllowsNamespace returns false for ANY scoped token when the
  // namespace is undefined (a fleet-wide op has no single namespace), and
  // true for unrestricted/legacy tokens — exactly the desired policy.
  if (!capabilityAllowsNamespace(caps, undefined)) {
    throw new EngramAccessForbiddenError(
      "token is scoped to specific namespaces; this maintenance operation runs across all namespaces and is not permitted for a namespace-scoped token",
    );
  }
}

/**
 * Per-request AsyncLocalStorage carrying the presenting token's resolved
 * capabilities. The HTTP surface binds the resolved capabilities with
 * `.run(caps, handler)` for the WHOLE authorized request dispatch (NOT
 * `.enterWith()`, which mutates the current async resource and does not
 * reliably isolate the store across the handler's awaits / concurrent
 * requests — risking a fail-open read of undefined mid-handler); the
 * access boundary reads `.getStore()` to enforce the ops allow-list for
 * every boundary operation without each dispatch site threading the value
 * explicitly. Unset (CLI, direct boundary callers, tests) ⇒ undefined ⇒
 * unrestricted (issue #1850 round 7).
 */
export const tokenCapabilityStore = new AsyncLocalStorage<TokenCapabilities | undefined>();

/**
 * Single-flight gate for the malformed-catalog repair (#3298 review), extracted
 * from catalog.ts so that file stays under its structural-ratchet ceiling
 * (issue #1995). Pure scheduling state plus the quarantine-sidecar path helper.
 */

import { createHash } from "node:crypto";

/** After a dropped attempt, wait this long before another read may schedule one. */
export const MALFORMED_REPAIR_DROP_BACKOFF_MS = 250;

/**
 * Bounds repairs triggered by malformed reads (#3298 review): one attempt in
 * flight at a time, and a short backoff after an attempt was dropped (another
 * process held the lock). The guard is what stops concurrent malformed reads
 * from queueing serial lock waits ahead of touch(); the 5 s lock wait is itself
 * the rate limiter under sustained contention, which is why the backoff is
 * short — a longer window would delay the legitimate warm-cache retry after
 * contention clears. A fast failure holds no lock budget and does not back off.
 */
export class MalformedCatalogRepairGate {
  private inFlight: Promise<void> | undefined;
  private nextAttemptAt = 0;
  private attempts = 0;

  /** Test-only observability: attempts that actually entered the gate. */
  get attemptCount(): number {
    return this.attempts;
  }

  /**
   * Run `attempt` unless one is already in flight or the backoff window is on.
   * Resolves when the attempt settles; never rejects (the repair is fail-open).
   */
  run(attempt: () => Promise<"repaired" | "dropped" | "failed">): Promise<void> {
    if (this.inFlight || Date.now() < this.nextAttemptAt) return Promise.resolve();
    this.attempts += 1;
    // Start the attempt as a microtask so run() returns before any of its work
    // begins, keeping the guard decision synchronous for every caller.
    this.inFlight = Promise.resolve().then(async () => {
      let outcome: "repaired" | "dropped" | "failed" = "failed";
      try {
        outcome = await attempt();
      } catch {
        outcome = "failed";
      } finally {
        this.inFlight = undefined;
        if (outcome === "dropped") {
          this.nextAttemptAt = Date.now() + MALFORMED_REPAIR_DROP_BACKOFF_MS;
        }
      }
    });
    return this.inFlight;
  }
}

/**
 * Quarantine sidecar path for the rows a repair drops (#3298 review): named by a
 * hash of the dropped lines, so repeated attempts over the same bad rows reuse
 * one file instead of piling one sidecar per failed attempt.
 */
export function malformedSidecarPath(catalogPath: string, dropped: string[]): string {
  return `${catalogPath}.malformed-${contentHash(dropped.join("\n"))}`;
}

// sha256 of the dropped lines, truncated for a filename; stable across processes.
function contentHash(input: string): string {
  return createHash("sha256").update(input, "utf8").digest("hex").slice(0, 16);
}

import { createRequire } from "node:module";
import type BetterSqlite3 from "better-sqlite3";

export type BetterSqlite3Database = BetterSqlite3.Database;
type BetterSqlite3Ctor = typeof BetterSqlite3;
type RuntimeRequire = ReturnType<typeof createRequire>;

let cachedCtor: BetterSqlite3Ctor | null = null;

function loadBetterSqlite3(): BetterSqlite3Ctor {
  if (cachedCtor) return cachedCtor;

  const require = createRequire(import.meta.url);

  try {
    cachedCtor = requireBetterSqlite3Ctor(require);
    return cachedCtor;
  } catch (error) {
    throw unavailableError(error);
  }
}

export function openBetterSqlite3(
  file: string,
  options?: ConstructorParameters<BetterSqlite3Ctor>[1],
): BetterSqlite3Database {
  const Database = loadBetterSqlite3();
  return new Database(file, options);
}

export interface BetterSqlite3DriverProbe {
  /** true when the native binding loaded successfully under this process. */
  ok: boolean;
  /** Path-free detail string (class + code) from `displayErrorDetail`; "" when ok. */
  detail: string;
  /** true when the failure is classified as a native-binding ABI mismatch. */
  nativeBindingMismatch: boolean;
}

/**
 * Attempt to load the better-sqlite3 native driver under the running process
 * WITHOUT opening a database. Used by the server startup check (issue #1829)
 * to surface a wrong-ABI build loudly instead of letting each memory browse
 * silently fall back to a full-corpus scan. Never throws — callers log the
 * result. A successful probe also warms the ctor cache for later opens.
 */
export function probeBetterSqlite3Driver(): BetterSqlite3DriverProbe {
  try {
    loadBetterSqlite3();
    return { ok: true, detail: "", nativeBindingMismatch: false };
  } catch (error) {
    return {
      ok: false,
      detail: displayErrorDetail(error),
      nativeBindingMismatch: isLikelyBetterSqlite3NativeBindingError(error),
    };
  }
}

function requireBetterSqlite3Ctor(require: RuntimeRequire): BetterSqlite3Ctor {
  const loaded = require("better-sqlite3") as
    | BetterSqlite3Ctor
    | { default?: BetterSqlite3Ctor };
  const ctor = typeof loaded === "function" ? loaded : loaded.default;

  if (typeof ctor !== "function") {
    throw new Error("module did not export a constructor");
  }

  return ctor;
}

// Raw, unredacted message — used ONLY for internal classification (detecting a
// native-binding mismatch). Never returned to a user-facing surface, because it
// can contain absolute paths. Native-binding markers (better_sqlite3.node,
// NODE_MODULE_VERSION, "was compiled against a different Node.js version") live
// in error.message, so message text is sufficient and we never read .stack.
function rawErrorMessage(error: unknown): string {
  return error instanceof Error ? error.message : String(error ?? "");
}

/**
 * Iterate an error and every node reachable along its `cause` chain and any
 * `AggregateError.errors` siblings (depth-first), cycle-safe via a visited set.
 *
 * Native-binding failures thrown from openBetterSqlite3 /
 * probeBetterSqlite3Driver are caught and re-thrown as a sanitized
 * `unavailableError` WRAPPER: the wrapper's message drops the ABI markers
 * (NODE_MODULE_VERSION, better_sqlite3.node, …) that live on the ORIGINAL
 * error. So classification must walk `.cause` (and aggregate siblings) instead
 * of inspecting only the top wrapper's message — otherwise startup logs, browse
 * warnings, and the memory_projection doctor check all MISS the native-binding
 * hint (issue #1848).
 */
function* errorChain(error: unknown): Generator<unknown> {
  const seen = new Set<unknown>();
  const stack: unknown[] = [error];
  while (stack.length > 0) {
    const node = stack.pop();
    if (node === null || node === undefined) continue;
    if (typeof node !== "object") continue;
    if (seen.has(node)) continue;
    seen.add(node);
    yield node;
    // Narrow with `in` (not a cast) so the property access is compiler-checked.
    if ("cause" in node) {
      const cause = node.cause;
      if (cause !== null && cause !== undefined) stack.push(cause);
    }
    if ("errors" in node) {
      const errors = node.errors;
      if (Array.isArray(errors)) {
        for (const member of errors) {
          if (member !== null && member !== undefined) stack.push(member);
        }
      }
    }
  }
}

// True when a single error's RAW message carries a native-binding ABI marker.
// Raw (not displayErrorDetail) so redaction can't strip detection markers
// (e.g. the loader path containing "better_sqlite3.node").
function messageHasNativeBindingMarker(error: unknown): boolean {
  const detail = rawErrorMessage(error);
  return (
    detail.includes("Could not locate the bindings file") ||
    detail.includes("better_sqlite3.node") ||
    (detail.includes("node-v") && detail.includes("better-sqlite3")) ||
    (detail.includes("NODE_MODULE_VERSION") && detail.includes("better-sqlite3")) ||
    detail.includes("was compiled against a different Node.js version")
  );
}

export function isLikelyBetterSqlite3NativeBindingError(error: unknown): boolean {
  // Walk the full cause / aggregate chain so a SANITIZED wrapper
  // (unavailableError) — whose message drops the ABI markers that live on the
  // original error — is still classified. Inspecting only the top-level message
  // misses the real mismatch when the failure was wrapped (issue #1848).
  for (const node of errorChain(error)) {
    if (messageHasNativeBindingMarker(node)) return true;
  }
  return false;
}

function unavailableError(error: unknown): Error {
  const detail = displayErrorDetail(error);
  const nativeBindingHint = isLikelyBetterSqlite3NativeBindingError(error)
    ? " This usually means the better-sqlite3 native binding was not compiled for this Node.js/platform combination. " +
      "Run `node scripts/ensure-better-sqlite3.mjs` from the Remnic install directory, or run " +
      "`npx node-gyp rebuild --directory=node_modules/better-sqlite3` if the verification script is unavailable."
    : "";
  return new Error(
    "better-sqlite3 is unavailable. Remnic attempted to load the native SQLite binding and could not." +
      nativeBindingHint +
      (detail ? ` Original error: ${detail}` : ""),
    { cause: error instanceof Error ? error : undefined },
  );
}

// Sanitized, user-facing error detail. This string becomes the message of the
// Error thrown by unavailableError(), which propagates to user-facing surfaces
// (HTTP error bodies, MCP tool errors — access-http.ts / access-mcp.ts return
// err.message). We must not leak server internals (CodeQL js/stack-trace-exposure):
//   - error.stack is never read.
// We deliberately surface only the error's class name and Node error code —
// never the raw message. Node module-load failures embed absolute server paths
// directly in error.message (the "Require stack:" block, and unquoted native
// loader paths that may even contain spaces), which no regex can redact
// reliably. The error code (MODULE_NOT_FOUND, ERR_DLOPEN_FAILED, …) is a stable,
// path-free identifier that, together with the native-binding hint, is enough
// for a user to act on. The full original error stays on the `cause` chain and
// is logged with its stack elsewhere.
export function displayErrorDetail(error: unknown): string {
  if (!(error instanceof Error)) return "";
  const code = (error as NodeJS.ErrnoException).code;
  return typeof code === "string" && code.length > 0 ? `${error.name} (${code})` : error.name;
}

/**
 * Shared-item contradiction detection (issue #1957).
 *
 * Pure helper. Same-id items are one item; overlapping claim keys with
 * unequal values are a conflict. No deletes, no persistence.
 */

export interface SharedClaimItem {
  id: string;
  claims: Record<string, string>;
}

export type ContradictionPairResult =
  | { kind: "same" }
  | { kind: "conflict"; keys: string[] }
  | { kind: "none" };

export function detectContradictionPair(
  a: SharedClaimItem,
  b: SharedClaimItem,
): ContradictionPairResult {
  if (a.id === b.id) {
    return { kind: "same" };
  }
  const keys: string[] = [];
  for (const key of Object.keys(a.claims)) {
    if (key in b.claims && a.claims[key] !== b.claims[key]) {
      keys.push(key);
    }
  }
  return keys.length > 0 ? { kind: "conflict", keys: keys.sort() } : { kind: "none" };
}

/**
 * Shared-item envelope wiring (issue #1957, control 1: origin + authority).
 *
 * Bridges the pure envelope helpers onto the markdown frontmatter the
 * shared-context manager reads and writes.
 *
 * Write side rejects invalid input (an unrecognized authority or a binding
 * request without the config opt-in throws — never silently reinterpreted).
 * Read side resolves least privilege: a missing, malformed, or unrecognized
 * authority never resolves above informational, and stored binding
 * downgrades to advisory unless config opted in.
 */

import { applyDefaultEnvelope, parseSharedEnvelope, type SharedEnvelope } from "./governance.js";
import { resolveSharedAuthority } from "./authority-precedence.js";
import type { SharedAuthority } from "./governance.js";
import { parseEnvelopeActor } from "./envelope-actor.js";
import { parseEnvelopeAt } from "./envelope-at.js";
import { parseEnvelopeId } from "./envelope-id.js";

export interface ComposeWriteEnvelopeInput {
  /** Governance origin. Becomes the envelope's `sharedBy`. */
  origin: string;
  /** Requested authority class. Unrecognized values throw. */
  authority?: string;
  /** Optional ISO-8601 expiry. Invalid timestamps throw. */
  expiresAt?: string;
  /** Optional id of the item this one supersedes. */
  supersedes?: string;
  /** Config opt-in (`sharedContextAllowBindingAuthority`). Binding throws without it. */
  allowBinding: boolean;
  /**
   * Write instant for the expiry TTL policy (issue #2920). When finite, an
   * `expiresAt` must land strictly after it and within the maximum TTL —
   * a past or effectively-immortal expiry is a client input error, never a
   * silently accepted stamp.
   */
  nowMs?: number;
}

function requireEnvelopeActor(agentId: string): string {
  const parsed = parseEnvelopeActor(agentId);
  if (!parsed.ok) {
    throw new Error(`composeWriteEnvelope: agentId must be a non-blank single-line string (${parsed.error})`);
  }
  return parsed.actor;
}

function optionalEnvelopeAt(expiresAt: string | undefined): string | undefined {
  if (expiresAt === undefined) return undefined;
  const parsed = parseEnvelopeAt(expiresAt);
  if (!parsed.ok) {
    throw new Error(`composeWriteEnvelope: expiresAt must be a valid ISO-8601 timestamp (${parsed.error})`);
  }
  return parsed.at;
}

/** Maximum write-side TTL: 10 years. A farther `expiresAt` is rejected. */
export const MAX_WRITE_EXPIRES_AT_TTL_MS = 3650 * 24 * 60 * 60 * 1000;

function assertBoundedFutureExpiry(expiresAt: string, nowMs: number): void {
  const expiresAtMs = Date.parse(expiresAt);
  if (expiresAtMs <= nowMs) {
    throw new Error("composeWriteEnvelope: expiresAt must be an instant strictly after the write time");
  }
  if (expiresAtMs - nowMs > MAX_WRITE_EXPIRES_AT_TTL_MS) {
    throw new Error(
      `composeWriteEnvelope: expiresAt exceeds the maximum TTL of ${MAX_WRITE_EXPIRES_AT_TTL_MS}ms`,
    );
  }
}

function optionalEnvelopeId(supersedes: string | undefined): string | undefined {
  if (supersedes === undefined) return undefined;
  const parsed = parseEnvelopeId(supersedes);
  if (!parsed.ok) {
    throw new Error(`composeWriteEnvelope: supersedes must be a non-blank single-line id (${parsed.error})`);
  }
  return parsed.id;
}

/**
 * Reserved governance origin for an authenticated external access write that
 * resolved no principal (`agentAccessHttp.principal` unset, no adapter
 * identity). Server-owned: the caller cannot mint or influence it, and the
 * caller-supplied `agentId` never becomes audit metadata on that path.
 */
export const UNATTRIBUTED_ACCESS_WRITE_ORIGIN = "unattributed:access-surface";

export interface ResolvedWriteIdentity {
  /**
   * Producer identity: frontmatter `agent`, on-disk segment, and the
   * cross-signals grouping key. Self-declared by the caller only on
   * surfaces that resolved no server identity; never decides authority.
   */
  agent: string;
  /** Governance origin stamped as the envelope's `sharedBy`. */
  origin: string;
}

/**
 * Resolve the producer identity and governance origin for a shared-context
 * write. They are different fields with different trust requirements:
 *
 * - The origin (`sharedBy`) is audit metadata and is always server-derived.
 *   When the surface resolved an authenticated identity, that identity IS the
 *   origin; when it resolved none but the write crosses an external
 *   boundary, the caller-supplied `unattributedOrigin` token is stamped
 *   instead — never the caller's value. Only a trusted in-process caller
 *   (no identity, no token) may stamp its own id as the origin.
 * - The producer (`agent`) drives grouping and display only. When an
 *   authenticated identity exists it is also the producer, and a
 *   caller-supplied `agentId` naming a different agent is REJECTED, so a
 *   caller can never publish an item attributed to another agent. Without a
 *   server identity the caller's label stands as the producer — collapsing
 *   it instead would merge every writer into one agent and erase
 *   multi-agent overlaps from `synthesizeCrossSignals`.
 */
export function resolveWriteOrigin(input: {
  agentId: string;
  authenticatedIdentity?: string;
  unattributedOrigin?: string;
}): ResolvedWriteIdentity {
  const identity = input.authenticatedIdentity?.trim() ?? "";
  if (identity.length > 0) {
    const requested = input.agentId.trim();
    if (requested.length > 0 && requested !== identity) {
      throw new Error(
        `shared-context write origin mismatch: authenticated identity ${JSON.stringify(identity)} cannot publish as ${JSON.stringify(requested)}`,
      );
    }
    return { agent: identity, origin: identity };
  }
  const unattributed = input.unattributedOrigin?.trim() ?? "";
  if (unattributed.length > 0) {
    const label = input.agentId.trim();
    return {
      agent: label.length > 0 ? requireProducer(label) : requireProducer(unattributed),
      origin: requireProducer(unattributed),
    };
  }
  const actor = requireProducer(input.agentId);
  return { agent: actor, origin: actor };
}

function requireProducer(value: string): string {
  const parsed = parseEnvelopeActor(value);
  if (!parsed.ok) {
    throw new Error(`shared-context write producer must be a non-blank single-line string (${parsed.error})`);
  }
  return parsed.actor;
}

/**
 * Validate and compose the envelope for a shared-context write.
 * `sharedBy` is stamped from the server-derived origin — provenance is
 * never injected through item content or the caller's producer label.
 */
export function composeWriteEnvelope(input: ComposeWriteEnvelopeInput): SharedEnvelope {
  const sharedBy = requireEnvelopeActor(input.origin);
  const expiresAt = optionalEnvelopeAt(input.expiresAt);
  if (expiresAt !== undefined && Number.isFinite(input.nowMs ?? Number.NaN)) {
    assertBoundedFutureExpiry(expiresAt, input.nowMs as number);
  }
  const supersedes = optionalEnvelopeId(input.supersedes);
  return applyDefaultEnvelope(
    { sharedBy, authority: input.authority, expiresAt, supersedes },
    { binding: input.allowBinding },
  );
}

/** Serialize an envelope into frontmatter lines (caller adds the `---` fences). */
export function envelopeToFrontmatterLines(envelope: SharedEnvelope): string[] {
  const line = (key: string, value: string) => `${key}: ${JSON.stringify(value)}`;
  const lines = [line("sharedBy", envelope.sharedBy ?? ""), line("authority", envelope.authority)];
  if (envelope.expiresAt !== undefined) lines.push(line("expiresAt", envelope.expiresAt));
  if (envelope.supersedes !== undefined) lines.push(line("supersedes", envelope.supersedes));
  return lines;
}

/**
 * Build an envelope from frontmatter scalars already read off a stored item.
 * Missing scalars (legacy items) compose to informational with no expiry.
 */
export function envelopeFromScalars(scalars: {
  sharedBy: string | null;
  authority: string | null;
  expiresAt: string | null;
  supersedes: string | null;
}): SharedEnvelope {
  const record: Record<string, string> = {};
  if (scalars.sharedBy !== null) record.sharedBy = scalars.sharedBy;
  if (scalars.authority !== null) record.authority = scalars.authority;
  if (scalars.expiresAt !== null) record.expiresAt = scalars.expiresAt;
  if (scalars.supersedes !== null) record.supersedes = scalars.supersedes;
  return parseSharedEnvelope(record);
}

/**
 * Resolve a stored envelope's authority for read-side consumption.
 * Least privilege: unrecognized/missing stays informational; binding
 * requires the config opt-in or downgrades to advisory.
 */
export function resolveReadAuthority(
  envelope: Pick<SharedEnvelope, "authority">,
  allowBinding: boolean,
): SharedAuthority {
  return resolveSharedAuthority({ authority: envelope.authority, allowBinding });
}

/**
 * Shared-context curation self-check (issue #1957 requirement 4).
 *
 * Pure. A synthesized claim with no traceable source is a lint error:
 * report claims whose citations are missing, blank, or absent from the
 * item ids the curation run actually had available.
 */

export interface CuratedClaim {
  claimId: string;
  /** Shared-context item ids this claim was synthesized from. */
  citedItemIds?: readonly string[];
}

export interface CurationLintFinding {
  claimId: string;
  reason: "no_citations" | "unknown_citation";
  /** Cited ids that are not in the available set. Only for unknown_citation. */
  unknownIds?: string[];
}

export function lintCuratedClaims(input: {
  claims: readonly CuratedClaim[];
  availableItemIds: readonly string[];
}): CurationLintFinding[] {
  const available = new Set(input.availableItemIds);
  const findings: CurationLintFinding[] = [];

  for (const claim of input.claims) {
    const claimId = claim.claimId;
    if (typeof claimId !== "string" || claimId.trim().length === 0) {
      throw new RangeError("claimId must be a non-blank string");
    }

    const unknown = new Set<string>();
    let validCount = 0;
    for (const id of claim.citedItemIds ?? []) {
      if (id.trim().length === 0) continue;
      if (available.has(id)) {
        validCount += 1;
      } else {
        unknown.add(id);
      }
    }

    if (validCount === 0) {
      findings.push({ claimId, reason: "no_citations" });
      continue;
    }
    if (unknown.size > 0) {
      findings.push({ claimId, reason: "unknown_citation", unknownIds: [...unknown].sort() });
    }
  }

  findings.sort((a, b) => {
    if (a.claimId !== b.claimId) return a.claimId < b.claimId ? -1 : 1;
    if (a.reason !== b.reason) return a.reason < b.reason ? -1 : 1;
    // Duplicate claim ids are linted independently, so two findings can share
    // both keys above and still differ. Without this tertiary key the result
    // would depend on upstream iteration order, which the deterministic-output
    // contract forbids.
    const left = (a.unknownIds ?? []).join(",");
    const right = (b.unknownIds ?? []).join(",");
    if (left !== right) return left < right ? -1 : 1;
    return 0;
  });
  return findings;
}

/**
 * Shared-item provenance stamp (issue #1957).
 *
 * First slice: stamp actor + at onto a new object. Curation wiring
 * comes later. Does not mutate the input.
 */

import { isStrictIsoInstant } from "./iso-instant.js";

export interface ProvenanceStamp {
  actor: string;
  at: string;
}

export interface StampProvenanceOptions {
  actor: string;
  at: string;
}

function requireActor(actor: string): string {
  if (typeof actor !== "string" || actor.trim().length === 0) {
    throw new Error("stampProvenance: actor must be a non-empty string");
  }
  return actor;
}

function requireAt(at: unknown): string {
  if (typeof at !== "string" || !isStrictIsoInstant(at)) {
    throw new Error("stampProvenance: at must be a valid ISO-8601 timestamp");
  }
  return at;
}

export function stampProvenance<T extends object>(
  item: T,
  stamp: StampProvenanceOptions,
): T & { provenance: ProvenanceStamp } {
  return {
    ...item,
    provenance: {
      actor: requireActor(stamp.actor),
      at: requireAt(stamp.at),
    },
  };
}

/**
 * Shared-item staleness (issue #1957).
 *
 * Pure helpers. Expired items drop; superseded items that still circulate
 * get a marker. Callers never `rm`.
 */
import { isExpired } from "./governance.js";

export interface SharedStalenessItem {
  id: string;
  expiresAt?: string;
  supersedes?: string;
  circulating?: boolean;
}

/** Drop expired items. Half-open: `nowMs >= expiresAt` is expired. */
export function filterLiveEnvelopes<T extends { expiresAt?: string }>(
  items: readonly T[],
  nowMs: number,
): T[] {
  return items.filter((item) => !isExpired(item, nowMs));
}

/**
 * Mark items whose id appears in another item's `supersedes`.
 * Returns a new array. Does not mutate input and does not delete files.
 */
export function markSupersededCirculation<T extends SharedStalenessItem>(
  items: readonly T[],
): (T & { circulating?: boolean })[] {
  const supersededIds = new Set<string>();
  for (const item of items) {
    if (item.supersedes) supersededIds.add(item.supersedes);
  }
  return items.map((item) =>
    supersededIds.has(item.id) ? { ...item, circulating: true } : item,
  );
}

/**
 * UTC ISO-8601 week ids (`YYYY-Www`) shared by compounding reports and the
 * daemon weekly run. Week boundaries follow the Thursday rule: the week
 * belongs to the year that contains its Thursday.
 */

const DAY_MS = 86_400_000;
const WEEK_MS = 7 * DAY_MS;

/** ISO week id for `d`, evaluated in UTC. */
export function isoWeekId(d: Date): string {
  // ISO week based on Thursday.
  const dt = new Date(Date.UTC(d.getUTCFullYear(), d.getUTCMonth(), d.getUTCDate()));
  const day = dt.getUTCDay() || 7;
  dt.setUTCDate(dt.getUTCDate() + 4 - day);
  const yearStart = new Date(Date.UTC(dt.getUTCFullYear(), 0, 1));
  const week = Math.ceil(((dt.getTime() - yearStart.getTime()) / 86400000 + 1) / 7);
  const yyyy = dt.getUTCFullYear();
  return `${yyyy}-W${String(week).padStart(2, "0")}`;
}

/** The ISO week that ended before the week containing `d`. */
export function previousIsoWeekId(d: Date): string {
  const dt = new Date(d.getTime());
  dt.setUTCDate(dt.getUTCDate() - 7);
  return isoWeekId(dt);
}

/**
 * Milliseconds until the next Monday 00:00 UTC. Exactly on a Monday boundary
 * the next run is one week out, so a tick that fires on the boundary does not
 * schedule a zero-delay follow-up.
 */
export function msUntilNextIsoWeek(d: Date): number {
  const utcMidnight = Date.UTC(d.getUTCFullYear(), d.getUTCMonth(), d.getUTCDate());
  const day = new Date(utcMidnight).getUTCDay() || 7;
  const daysFromMonday = day - 1;
  const thisMonday = utcMidnight - daysFromMonday * DAY_MS;
  const nextMonday = thisMonday + WEEK_MS;
  const delta = nextMonday - d.getTime();
  if (delta <= 0) return WEEK_MS;
  return delta;
}

/** True for the `YYYY-Www` ids this module produces (week 01 through 53). */
export function isIsoWeekId(weekId: string): boolean {
  if (weekId.length !== 8 || weekId[4] !== "-" || weekId[5] !== "W") return false;
  const year = weekId.slice(0, 4);
  const week = weekId.slice(6);
  for (let i = 0; i < year.length; i += 1) {
    const code = year.charCodeAt(i);
    if (code < 48 || code > 57) return false;
  }
  for (let i = 0; i < week.length; i += 1) {
    const code = week.charCodeAt(i);
    if (code < 48 || code > 57) return false;
  }
  const weekNum = Number(week);
  return weekNum >= 1 && weekNum <= 53;
}

/** How long a rubric cadence may go unreviewed before it counts as stale. */
export function cadenceStaleWindowMs(cadence: "daily" | "weekly" | "monthly" | "quarterly"): number {
  switch (cadence) {
    case "daily":
      return 2 * 24 * 60 * 60 * 1000;
    case "weekly":
      return 10 * 24 * 60 * 60 * 1000;
    case "monthly":
      return 45 * 24 * 60 * 60 * 1000;
    case "quarterly":
      return 120 * 24 * 60 * 60 * 1000;
    default:
      return 45 * 24 * 60 * 60 * 1000;
  }
}

import {
  composeMemoryEnvelope,
  type MemoryWriteInput,
  type SealedMemoryEnvelope,
  type WriteContext,
} from "./write-envelope.js";
import { log } from "./logger.js";

/**
 * Shared salvage-compose helper for MACHINE-GENERATED or replayed-from-store
 * write input (issue #1989 PR4): one malformed optional field must not abort
 * the surrounding batch/action, and every drop is warn-logged with the
 * caller's label — visible, never silent (rule 34).
 *
 * Operator/system-built input must NOT use this — compose strict so caller
 * bugs surface (see AGENTS.md "Sealed memory-write envelope").
 */
export function composeSalvagedEnvelope(
  label: string,
  input: MemoryWriteInput,
  ctx: WriteContext,
): SealedMemoryEnvelope {
  const envelope = composeMemoryEnvelope(input, ctx, { salvage: true });
  if (envelope.salvageNotes.length > 0) {
    log.warn(`${label} write salvaged invalid fields: ${envelope.salvageNotes.join("; ")}`);
  }
  return envelope;
}

import type {
  ContinuityIncidentCloseInput,
  ContinuityIncidentOpenInput,
  ContinuityImprovementLoop,
  ContinuityLoopCadence,
  ContinuityLoopReviewInput,
  ContinuityLoopStatus,
  ContinuityLoopUpsertInput,
  ContinuityIncidentRecord,
  ContinuityIncidentState,
} from "./types.js";

function parseFrontmatterValue(raw: string): unknown {
  try {
    return JSON.parse(raw);
  } catch {
    return raw;
  }
}

function parseFrontmatter(raw: string): Record<string, unknown> {
  const parsed: Record<string, unknown> = {};
  for (const line of raw.split("\n")) {
    const idx = line.indexOf(":");
    if (idx <= 0) continue;
    const key = line.slice(0, idx).trim();
    const value = line.slice(idx + 1).trim();
    parsed[key] = parseFrontmatterValue(value);
  }
  return parsed;
}

function emitSection(lines: string[], title: string, value?: string): void {
  if (!value || value.trim().length === 0) return;
  lines.push(`## ${title}`, "", value.trim(), "");
}

function parseSection(body: string, title: string): string | undefined {
  const escaped = title.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
  const re = new RegExp(`## ${escaped}\\n\\n([\\s\\S]*?)(?=\\n## |$)`);
  const match = body.match(re);
  if (!match) return undefined;
  const value = match[1].trim();
  return value.length > 0 ? value : undefined;
}

export function serializeContinuityIncident(incident: ContinuityIncidentRecord): string {
  const lines = [
    "---",
    `id: ${JSON.stringify(incident.id)}`,
    `state: ${JSON.stringify(incident.state)}`,
    `openedAt: ${JSON.stringify(incident.openedAt)}`,
    `updatedAt: ${JSON.stringify(incident.updatedAt)}`,
  ];
  if (incident.closedAt) lines.push(`closedAt: ${JSON.stringify(incident.closedAt)}`);
  if (incident.triggerWindow) lines.push(`triggerWindow: ${JSON.stringify(incident.triggerWindow)}`);
  lines.push("---", "");

  emitSection(lines, "Symptom", incident.symptom);
  emitSection(lines, "Suspected Cause", incident.suspectedCause);
  emitSection(lines, "Fix Applied", incident.fixApplied);
  emitSection(lines, "Verification Result", incident.verificationResult);
  emitSection(lines, "Preventive Rule", incident.preventiveRule);

  return lines.join("\n").trimEnd() + "\n";
}

export function parseContinuityIncident(raw: string): ContinuityIncidentRecord | null {
  const match = raw.match(/^---\n([\s\S]*?)\n---\n?([\s\S]*)$/);
  if (!match) return null;
  const frontmatter = parseFrontmatter(match[1]);
  const body = match[2] ?? "";

  const id = typeof frontmatter.id === "string" ? frontmatter.id : "";
  const stateRaw = frontmatter.state;
  const state: ContinuityIncidentState = stateRaw === "closed" ? "closed" : "open";
  const openedAt = typeof frontmatter.openedAt === "string" ? frontmatter.openedAt : "";
  const updatedAt = typeof frontmatter.updatedAt === "string" ? frontmatter.updatedAt : openedAt;
  const symptom = parseSection(body, "Symptom");

  if (!id || !openedAt || !updatedAt || !symptom) return null;

  return {
    id,
    state,
    openedAt,
    updatedAt,
    triggerWindow: typeof frontmatter.triggerWindow === "string" ? frontmatter.triggerWindow : undefined,
    symptom,
    suspectedCause: parseSection(body, "Suspected Cause"),
    fixApplied: parseSection(body, "Fix Applied"),
    verificationResult: parseSection(body, "Verification Result"),
    preventiveRule: parseSection(body, "Preventive Rule"),
    closedAt: typeof frontmatter.closedAt === "string" ? frontmatter.closedAt : undefined,
  };
}

export function createContinuityIncidentRecord(
  id: string,
  input: ContinuityIncidentOpenInput,
  nowIso: string,
): ContinuityIncidentRecord {
  return {
    id,
    state: "open",
    openedAt: nowIso,
    updatedAt: nowIso,
    triggerWindow: input.triggerWindow?.trim() || undefined,
    symptom: input.symptom.trim(),
    suspectedCause: input.suspectedCause?.trim() || undefined,
  };
}

export function closeContinuityIncidentRecord(
  incident: ContinuityIncidentRecord,
  closure: ContinuityIncidentCloseInput,
  nowIso: string,
): ContinuityIncidentRecord {
  return {
    ...incident,
    state: "closed",
    updatedAt: nowIso,
    closedAt: nowIso,
    fixApplied: closure.fixApplied.trim(),
    verificationResult: closure.verificationResult.trim(),
    preventiveRule: closure.preventiveRule?.trim() || incident.preventiveRule,
  };
}

const LOOP_HEADER = "# Continuity Improvement Loops";
const LOOP_CADENCES = new Set<ContinuityLoopCadence>(["daily", "weekly", "monthly", "quarterly"]);
const LOOP_STATUSES = new Set<ContinuityLoopStatus>(["active", "paused", "retired"]);
const STALE_LAST_REVIEWED_FALLBACK = "1970-01-01T00:00:00.000Z";

function normalizeLoopField(value: string | undefined): string | undefined {
  if (typeof value !== "string") return undefined;
  const trimmed = value.trim();
  if (trimmed.length === 0) return undefined;
  return trimmed.replace(/\s+/g, " ");
}

function isValidIso(value: string): boolean {
  const ts = Date.parse(value);
  return Number.isFinite(ts);
}

function normalizeContinuityLoop(
  input: ContinuityLoopUpsertInput | ContinuityImprovementLoop,
  nowIso: string,
): ContinuityImprovementLoop | null {
  const id = normalizeLoopField(input.id);
  const cadence = normalizeLoopField(input.cadence) as ContinuityLoopCadence | undefined;
  const status = normalizeLoopField(input.status) as ContinuityLoopStatus | undefined;
  const purpose = normalizeLoopField(input.purpose);
  const killCondition = normalizeLoopField(input.killCondition);
  const notes = normalizeLoopField(input.notes);
  const lastReviewedRaw =
    "lastReviewed" in input && typeof input.lastReviewed === "string" ? input.lastReviewed : undefined;
  const lastReviewed = normalizeLoopField(lastReviewedRaw) ?? nowIso;

  if (!id || !cadence || !status || !purpose || !killCondition) return null;
  if (!LOOP_CADENCES.has(cadence)) return null;
  if (!LOOP_STATUSES.has(status)) return null;
  if (!isValidIso(lastReviewed)) return null;

  return {
    id,
    cadence,
    purpose,
    status,
    killCondition,
    lastReviewed,
    notes,
  };
}

function serializeContinuityLoopSection(loop: ContinuityImprovementLoop): string {
  const lines = [
    `## ${loop.id}`,
    `cadence: ${loop.cadence}`,
    `purpose: ${loop.purpose}`,
    `status: ${loop.status}`,
    `killCondition: ${loop.killCondition}`,
    `lastReviewed: ${loop.lastReviewed}`,
  ];
  if (loop.notes) lines.push(`notes: ${loop.notes}`);
  return lines.join("\n");
}

type MarkdownSection = {
  title: string;
  body: string;
};

function splitLoopMarkdown(raw: string | null): { header: string; sections: MarkdownSection[] } {
  const text = (raw ?? "").replace(/\r/g, "");
  const lines = text.split("\n");
  const headerLines: string[] = [];
  const sections: MarkdownSection[] = [];
  let current: MarkdownSection | null = null;

  for (const line of lines) {
    // /^##\s(.+)$/ + the trim below is exactly equivalent to the original
    // /^##\s+(.+?)\s*$/ (same match/no-match and same trimmed title across all
    // inputs, including "## " → no-match and "##  " → empty title) but has no
    // adjacent overlapping quantifiers, so it cannot backtrack polynomially
    // (CodeQL js/polynomial-redos). \s matches a single fixed-width char and
    // .+ runs greedily to the line end — no \s+/.* overlap.
    const sectionMatch = line.match(/^##\s(.+)$/);
    if (sectionMatch) {
      if (current) sections.push({ title: current.title, body: current.body.trimEnd() });
      current = { title: sectionMatch[1].trim(), body: "" };
      continue;
    }
    if (!current) {
      headerLines.push(line);
      continue;
    }
    current.body += current.body.length > 0 ? `\n${line}` : line;
  }
  if (current) sections.push({ title: current.title, body: current.body.trimEnd() });

  const headerRaw = headerLines.join("\n").trim();
  const header = headerRaw.length > 0 ? headerRaw : LOOP_HEADER;
  return { header, sections };
}

function parseLoopFromSection(section: MarkdownSection, nowIso: string): ContinuityImprovementLoop | null {
  const fields: Record<string, string> = {};
  for (const line of section.body.split("\n")) {
    const kv = line.match(/^([A-Za-z][A-Za-z0-9_]*):\s*(.+?)\s*$/);
    if (!kv) continue;
    fields[kv[1]] = kv[2];
  }
  const parsedLastReviewed = normalizeLoopField(fields.lastReviewed);
  const safeLastReviewed =
    parsedLastReviewed && isValidIso(parsedLastReviewed) ? parsedLastReviewed : STALE_LAST_REVIEWED_FALLBACK;
  return normalizeContinuityLoop(
    {
      id: section.title,
      cadence: (fields.cadence ?? "") as ContinuityLoopCadence,
      purpose: fields.purpose ?? "",
      status: (fields.status ?? "") as ContinuityLoopStatus,
      killCondition: fields.killCondition ?? "",
      lastReviewed: safeLastReviewed,
      notes: fields.notes,
    },
    nowIso,
  );
}

function joinLoopMarkdown(header: string, sections: MarkdownSection[]): string {
  const lines: string[] = [header.trim(), ""];
  for (const section of sections) {
    lines.push(`## ${section.title}`);
    if (section.body.trim().length > 0) {
      lines.push(section.body.trimEnd());
    }
    lines.push("");
  }
  return lines.join("\n").replace(/\n{3,}/g, "\n\n").trimEnd() + "\n";
}

export function parseContinuityImprovementLoops(raw: string): ContinuityImprovementLoop[] {
  const parsed = splitLoopMarkdown(raw);
  const nowIso = new Date().toISOString();
  return parsed.sections
    .map((section) => parseLoopFromSection(section, nowIso))
    .filter((loop): loop is ContinuityImprovementLoop => loop !== null);
}

export function upsertContinuityLoopInMarkdown(
  raw: string | null,
  input: ContinuityLoopUpsertInput,
  nowIso: string,
): { markdown: string; loop: ContinuityImprovementLoop } {
  const normalized = normalizeContinuityLoop(input, nowIso);
  if (!normalized) {
    throw new Error("Invalid continuity loop input");
  }

  const parsed = splitLoopMarkdown(raw);
  let replaced = false;
  const nextSections = parsed.sections.map((section) => {
    if (normalizeLoopField(section.title) !== normalized.id) return section;
    replaced = true;
    return { title: normalized.id, body: serializeContinuityLoopSection(normalized).split("\n").slice(1).join("\n") };
  });

  if (!replaced) {
    nextSections.push({
      title: normalized.id,
      body: serializeContinuityLoopSection(normalized).split("\n").slice(1).join("\n"),
    });
  }

  return { markdown: joinLoopMarkdown(parsed.header, nextSections), loop: normalized };
}

export function reviewContinuityLoopInMarkdown(
  raw: string | null,
  id: string,
  input: ContinuityLoopReviewInput,
  nowIso: string,
): { markdown: string; loop: ContinuityImprovementLoop | null } {
  const parsed = splitLoopMarkdown(raw);
  const normalizedId = normalizeLoopField(id);
  if (!normalizedId) {
    return { markdown: joinLoopMarkdown(parsed.header, parsed.sections), loop: null };
  }
  let updatedLoop: ContinuityImprovementLoop | null = null;
  const nextSections = parsed.sections.map((section) => {
    if (normalizeLoopField(section.title) !== normalizedId) return section;
    const existing = parseLoopFromSection(section, nowIso);
    if (!existing) return section;
    const reviewed = applyContinuityLoopReview(existing, input, nowIso);
    updatedLoop = reviewed;
    return { title: reviewed.id, body: serializeContinuityLoopSection(reviewed).split("\n").slice(1).join("\n") };
  });

  return { markdown: joinLoopMarkdown(parsed.header, nextSections), loop: updatedLoop };
}

function applyContinuityLoopReview(
  existing: ContinuityImprovementLoop,
  input: ContinuityLoopReviewInput,
  nowIso: string,
): ContinuityImprovementLoop {
  const nextStatus = normalizeLoopField(input.status) as ContinuityLoopStatus | undefined;
  const nextNotes = normalizeLoopField(input.notes);
  const reviewedAt = normalizeLoopField(input.reviewedAt) ?? nowIso;

  return {
    ...existing,
    status: nextStatus && LOOP_STATUSES.has(nextStatus) ? nextStatus : existing.status,
    notes: nextNotes ?? existing.notes,
    lastReviewed: isValidIso(reviewedAt) ? reviewedAt : nowIso,
  };
}

/**
 * Week-scoped inputs for compounding synthesis.
 *
 * Corrections, namespace action ledgers, and the feedback inbox are read here
 * so CompoundingEngine stays inside its line ceiling. Scans are bounded:
 * correction files outside the ISO week are skipped before they are read.
 * Parsing stops after WEEKLY_CORRECTION_READ_LIMIT accepted corrections or
 * WEEKLY_CORRECTION_SCAN_LIMIT opened files, whichever comes first. Visible
 * store candidates are opened before other namespaces, so a foreign store
 * cannot fill the accepted cap and hide an older default-store correction.
 */

