type NamespaceDir = {
  dirName: string;
  namespace: string;
  root: string;
};

/** Monday 00:00 UTC of an ISO week id, or null when `weekId` is not one this module emits. */
export function isoWeekStartMs(weekId: string): number | null {
  if (!isIsoWeekId(weekId)) return null;
  const year = Number(weekId.slice(0, 4));
  const week = Number(weekId.slice(6));
  const jan4 = Date.UTC(year, 0, 4);
  const jan4Day = new Date(jan4).getUTCDay() || 7;
  const start = jan4 - (jan4Day - 1) * DAY_MS + (week - 1) * 7 * DAY_MS;
  if (isoWeekId(new Date(start)) !== weekId) return null;
  return start;
}

export async function readFeedbackEntriesForWeekFile(
  inboxPath: string,
  weekId: string
): Promise<FeedbackEntryWithProvenance[]> {
  // Includes entries whose date falls in the ISO week.
  const out: FeedbackEntryWithProvenance[] = [];
  try {
    const raw = await readFile(inboxPath, "utf-8");
    const lines = raw.split("\n");
    for (let idx = 0; idx < lines.length; idx += 1) {
      const line = lines[idx];
      if (!line.trim()) continue;
      try {
        const obj = JSON.parse(line);
        const parsed = SharedFeedbackEntrySchema.safeParse(obj);
        if (!parsed.success) continue;
        const d = new Date(parsed.data.date);
        if (!Number.isFinite(d.getTime())) continue;
        if (isoWeekId(d) !== weekId) continue;
        const sourceLine = idx + 1;
        out.push({
          entry: parsed.data,
          sourceLine,
          sourcePath: inboxPath,
          entryId: `${parsed.data.agent}-${parsed.data.date}-${sourceLine}`.replace(/[^a-zA-Z0-9._:-]/g, "_"),
        });
      } catch {
        // ignore a malformed line
      }
    }
  } catch {
    // missing feedback is normal
  }
  return out;
}

export function buildActionFailurePatterns(
  events: WeeklyActionEvent[]
): Array<{ pattern: string; provenance: string }> {
  const out: Array<{ pattern: string; provenance: string }> = [];
  for (const event of events) {
    const failed = event.outcome === "failed" || event.outcome === "skipped";
    if (!failed && event.policyDecision === null) continue;
    const suffix = event.reason && event.reason.trim().length > 0 ? ` - ${event.reason.trim().slice(0, 140)}` : "";
    out.push({
      pattern: `memory-action/${event.namespace}: ${event.action} ${event.outcome}${event.policyDecision ? `/${event.policyDecision}` : ""}${suffix}`,
      provenance: `${event.ledgerLabel}:*`,
    });
  }
  return out;
}

export async function readWeeklyActionEvents(input: {
  storage: WeeklyEvidenceStorage;
  memoryDir: string;
  weekId: string;
}): Promise<WeeklyActionEvent[]> {
  const seenActionIds = new Set<string>();
  const out: WeeklyActionEvent[] = [];
  const rootRows = await input.storage.readMemoryActionEventRows(Number.MAX_SAFE_INTEGER);
  for (const row of rootRows) {
    pushActionEvent(out, seenActionIds, row.line, row.event, "default", "memory-actions.jsonl", input.weekId);
  }

  const rootReal = await realpath(input.memoryDir);
  const namespaces = await listNamespaceStorageDirs(input.memoryDir, rootReal);
  const key = keyring.getKey(secureStoreDir(input.memoryDir));
  for (const ns of namespaces) {
    const filePath = path.join(ns.root, "state", "memory-actions.jsonl");
    const label = `namespaces/${ns.dirName}/state/memory-actions.jsonl`;
    let entryStat: Stats;
    try {
      entryStat = await lstat(filePath);
    } catch (err) {
      if (isErrnoCode(err, "ENOENT")) continue;
      throw err;
    }
    if (entryStat.isSymbolicLink() || !entryStat.isFile()) continue;
    const fileReal = await realpath(filePath);
    assertPathInsideRoot(rootReal, fileReal, filePath);
    try {
      let lineNumber = 0;
      for await (const row of readMaybeEncryptedLines(
        filePath,
        () => readMaybeEncryptedFile(filePath, key, input.memoryDir),
      )) {
        lineNumber += 1;
        const line = row.trim();
        if (line.length === 0) continue;
        const event = parseMemoryActionEventLine(line);
        if (!event) continue;
        pushActionEvent(out, seenActionIds, lineNumber, event, ns.namespace, label, input.weekId);
      }
    } catch (err) {
      if (isErrnoCode(err, "ENOENT")) continue;
      throw err;
    }
  }
  return out;
}

export async function readWeeklyCorrections(input: {
  storage: WeeklyEvidenceStorage;
  memoryDir: string;
  weekId: string;
  /** Flat root stays visible when this is null. A routed default store passes its `namespaces/<dir>/` prefix. */
  defaultNamespacePrefix?: string | null;
}): Promise<WeeklyCorrectionEvidence[]> {
  const weekStartMs = isoWeekStartMs(input.weekId);
  if (weekStartMs === null) return [];
  const rootReal = await realpath(input.memoryDir);
  const candidates: CorrectionCandidate[] = [];
  await collectCorrectionCandidates(candidates, input.memoryDir, "default", input.weekId, weekStartMs, rootReal);
  const namespaces = await listNamespaceStorageDirs(input.memoryDir, rootReal);
  for (const ns of namespaces) {
    await collectCorrectionCandidates(candidates, ns.root, ns.namespace, input.weekId, weekStartMs, rootReal);
  }
  candidates.sort((a, b) => b.sortMs - a.sortMs || a.filePath.localeCompare(b.filePath));
  const ordered = preferVisibleCorrectionCandidates(
    candidates,
    input.memoryDir,
    input.defaultNamespacePrefix ?? null,
  );
  const out: WeeklyCorrectionEvidence[] = [];
  let scanned = 0;
  for (const candidate of ordered) {
    if (out.length >= WEEKLY_CORRECTION_READ_LIMIT || scanned >= WEEKLY_CORRECTION_SCAN_LIMIT) break;
    scanned += 1;
    const evidence = await readCorrectionCandidate(input.storage, input.memoryDir, input.weekId, candidate);
    if (evidence) out.push(evidence);
  }
  if (scanned < candidates.length) {
    log.warn(
      `weekly synthesis kept ${out.length} accepted corrections after scanning ${scanned} of ${candidates.length} in-week candidates`
    );
  }
  return out;
}

/** Newest-first within the visible store, then newest-first everywhere else. */
function preferVisibleCorrectionCandidates(
  candidates: readonly CorrectionCandidate[],
  memoryDir: string,
  defaultNamespacePrefix: string | null,
): CorrectionCandidate[] {
  const visible: CorrectionCandidate[] = [];
  const foreign: CorrectionCandidate[] = [];
  for (const candidate of candidates) {
    const relative = path.relative(memoryDir, candidate.filePath).split(path.sep).join("/");
    if (provenanceVisibleInStoreRecall([relative], defaultNamespacePrefix)) visible.push(candidate);
    else foreign.push(candidate);
  }
  return visible.concat(foreign);
}

function parseMemoryActionEventLine(line: string): MemoryActionEvent | null {
  let parsed: Partial<MemoryActionEvent> & { recordKind?: unknown };
  try {
    parsed = JSON.parse(line) as Partial<MemoryActionEvent> & { recordKind?: unknown };
  } catch {
    return null;
  }
  if (parsed.recordKind !== undefined) return null;
  const outcome = parsed.outcome === "applied" || parsed.outcome === "skipped" || parsed.outcome === "failed"
    ? parsed.outcome
    : null;
  const timestamp = parsed.timestamp;
  const action = parsed.action;
  if (typeof timestamp !== "string" || typeof action !== "string" || outcome === null) return null;
  return { ...parsed, timestamp, action, outcome };
}

function pushActionEvent(
  out: WeeklyActionEvent[],
  seenActionIds: Set<string>,
  line: number,
  event: MemoryActionEvent,
  fallbackNamespace: string,
  ledgerLabel: string,
  weekId: string
): void {
  const ts = new Date(event.timestamp);
  if (!Number.isFinite(ts.getTime()) || isoWeekId(ts) !== weekId) return;
  const actionId = typeof event.actionId === "string" && event.actionId.length > 0 ? event.actionId : null;
  if (actionId) {
    if (seenActionIds.has(actionId)) return;
    seenActionIds.add(actionId);
  }
  out.push({
    line,
    action: event.action,
    outcome: event.outcome,
    policyDecision: event.policyDecision === "deny" || event.policyDecision === "defer" ? event.policyDecision : null,
    namespace: typeof event.namespace === "string" && event.namespace.length > 0 ? event.namespace : fallbackNamespace,
    reason: typeof event.reason === "string" ? event.reason : null,
    ledgerLabel,
    actionId,
  });
}

async function listNamespaceStorageDirs(memoryDir: string, rootReal: string): Promise<NamespaceDir[]> {
  const nsRoot = path.join(memoryDir, "namespaces");
  let rootStat: Stats;
  try {
    rootStat = await lstat(nsRoot);
  } catch (err) {
    if (isErrnoCode(err, "ENOENT")) return [];
    throw err;
  }
  // A symlinked namespaces directory can point outside the store. Reject the
  // whole tree rather than following it.
  if (rootStat.isSymbolicLink() || !rootStat.isDirectory()) return [];
  const nsReal = await realpath(nsRoot);
  assertPathInsideRoot(rootReal, nsReal, nsRoot);
  const names = await readdir(nsRoot);
  const out: NamespaceDir[] = [];
  for (const dirName of names) {
    const namespace = namespaceFromDirName(dirName);
    if (!namespace) continue;
    const root = path.join(nsRoot, dirName);
    let entryStat: Stats;
    try {
      entryStat = await lstat(root);
    } catch (err) {
      if (isErrnoCode(err, "ENOENT")) continue;
      throw err;
    }
    if (entryStat.isSymbolicLink() || !entryStat.isDirectory()) continue;
    const dirReal = await realpath(root);
    assertPathInsideRoot(rootReal, dirReal, root);
    out.push({ dirName, namespace, root });
  }
  out.sort((a, b) => a.dirName.localeCompare(b.dirName));
  return out;
}

function namespaceFromDirName(dirName: string): string | null {
  if (dirName.length === 0 || dirName.includes("/") || dirName.includes("\\") || dirName.includes("..")) {
    return null;
  }
  if (dirName.startsWith("ns-")) {
    const decoded = namespaceIdentityFromToken(dirName);
    if (decoded === null) return null;
    // `ns-default` is the empty identity. It is the migrated default store,
    // not a foreign namespace.
    if (decoded.length === 0) return "default";
    return isSafeRouteNamespace(decoded) ? decoded : null;
  }
  return isSafeRouteNamespace(dirName) ? dirName : null;
}

async function collectCorrectionCandidates(
  candidates: CorrectionCandidate[],
  storageRoot: string,
  namespace: string,
  weekId: string,
  weekStartMs: number,
  rootReal: string
): Promise<void> {
  await collectCorrectionDir(
    candidates,
    path.join(storageRoot, "corrections"),
    namespace,
    weekId,
    weekStartMs,
    rootReal
  );
  const factsDir = path.join(storageRoot, "facts");
  const dayNames = await readContainedDirNames(factsDir, rootReal);
  if (!dayNames) return;
  for (const dayName of dayNames) {
    if (!utcDayDirInWeek(dayName, weekId)) continue;
    await collectCorrectionDir(candidates, path.join(factsDir, dayName), namespace, weekId, weekStartMs, rootReal);
  }
}

async function collectCorrectionDir(
  candidates: CorrectionCandidate[],
  dir: string,
  namespace: string,
  weekId: string,
  weekStartMs: number,
  rootReal: string
): Promise<void> {
  const names = await readContainedDirNames(dir, rootReal);
  if (!names) return;
  for (const name of names) {
    if (!name.startsWith("correction-") || !name.endsWith(".md")) continue;
    // A timestamped name outside this week is historical. Skip it before
    // lstat or realpath so a large corrections directory stays inside the
    // weekly budget.
    const filenameMs = correctionFilenameTimestampMs(name);
    if (filenameMs !== null && isoWeekId(new Date(filenameMs)) !== weekId) continue;
    const filePath = path.join(dir, name);
    let entryStat: Stats;
    try {
      entryStat = await lstat(filePath);
    } catch (err) {
      if (isErrnoCode(err, "ENOENT")) continue;
      throw err;
    }
    if (entryStat.isSymbolicLink() || !entryStat.isFile()) continue;
    if (entryStat.size > CORRECTION_FILE_BYTE_LIMIT) continue;
    const fileReal = await realpath(filePath);
    assertPathInsideRoot(rootReal, fileReal, filePath);
    if (filenameMs !== null) {
      candidates.push({ filePath, sortMs: filenameMs, namespace });
      continue;
    }
    if (entryStat.mtimeMs < weekStartMs) continue;
    candidates.push({ filePath, sortMs: entryStat.mtimeMs, namespace });
  }
}

async function readContainedDirNames(dir: string, rootReal: string): Promise<string[] | null> {
  let entryStat: Stats;
  try {
    entryStat = await lstat(dir);
  } catch (err) {
    if (isErrnoCode(err, "ENOENT")) return null;
    throw err;
  }
  if (entryStat.isSymbolicLink() || !entryStat.isDirectory()) return null;
  const dirReal = await realpath(dir);
  assertPathInsideRoot(rootReal, dirReal, dir);
  return readdir(dir);
}

function utcDayDirInWeek(name: string, weekId: string): boolean {
  if (name.length !== 10 || name[4] !== "-" || name[7] !== "-") return false;
  for (let i = 0; i < name.length; i += 1) {
    if (i === 4 || i === 7) continue;
    const code = name.charCodeAt(i);
    if (code < 48 || code > 57) return false;
  }
  const year = Number(name.slice(0, 4));
  const month = Number(name.slice(5, 7));
  const day = Number(name.slice(8, 10));
  if (month < 1 || month > 12 || day < 1 || day > 31) return false;
  const stamp = new Date(Date.UTC(year, month - 1, day));
  if (stamp.getUTCFullYear() !== year || stamp.getUTCMonth() !== month - 1 || stamp.getUTCDate() !== day) {
    return false;
  }
  return isoWeekId(stamp) === weekId;
}

function correctionFilenameTimestampMs(fileName: string): number | null {
  const prefix = "correction-";
  if (!fileName.startsWith(prefix) || !fileName.endsWith(".md")) return null;
  const rest = fileName.slice(prefix.length, fileName.length - 3);
  let i = 0;
  while (i < rest.length) {
    const code = rest.charCodeAt(i);
    if (code < 48 || code > 57) break;
    i += 1;
  }
  if (i < 10) return null;
  if (i < rest.length && rest[i] !== "-") return null;
  const ms = Number(rest.slice(0, i));
  if (!Number.isSafeInteger(ms)) return null;
  return ms;
}

async function readCorrectionCandidate(
  storage: WeeklyEvidenceStorage,
  memoryDir: string,
  weekId: string,
  candidate: CorrectionCandidate
): Promise<WeeklyCorrectionEvidence | null> {
  const memory = await storage.readMemoryByPath(candidate.filePath);
  if (!memory) return null;
  const raw = readRawMemoryDocument(memory);
  if (!raw) return null;
  if (rawFrontmatterScalar(raw, "category") !== "correction") return null;
  // Missing status is the writer default (`active`). Any other explicit
  // status, including forgotten, stays out of compounding so a forget is
  // not copied back into recall or promotion.
  const status = rawFrontmatterScalar(raw, "status");
  if (status && status !== "active") return null;
  const created = rawFrontmatterScalar(raw, "created");
  if (!created) return null;
  const createdDate = new Date(created);
  if (!Number.isFinite(createdDate.getTime()) || isoWeekId(createdDate) !== weekId) return null;
  const note = collapseWhitespace(memory.content).slice(0, CORRECTION_NOTE_LIMIT);
  if (note.length === 0) return null;
  const rawSource = rawFrontmatterScalar(raw, "source");
  const source = rawSource && rawSource !== "unknown" ? rawSource : null;
  const entityRef =
    typeof memory.frontmatter.entityRef === "string" && memory.frontmatter.entityRef.length > 0
      ? memory.frontmatter.entityRef
      : null;
  const confidence = rawConfidence(raw);
  const tags = Array.isArray(memory.frontmatter.tags)
    ? memory.frontmatter.tags.filter((tag) => typeof tag === "string" && tag.length > 0)
    : [];
  const id =
    typeof memory.frontmatter.id === "string" && memory.frontmatter.id.length > 0
      ? memory.frontmatter.id
      : path.basename(candidate.filePath, ".md");
  return {
    id,
    namespace: candidate.namespace,
    pattern: `correction: ${note}`,
    note,
    created,
    source,
    entityRef,
    confidence,
    tags,
    provenance: path.relative(memoryDir, candidate.filePath).split(path.sep).join("/"),
  };
}

/**
 * Relative `namespaces/` prefix for the routed default store, or null when
 * that store is still the flat memory root. Recall and promotion treat this
 * prefix as the caller's own store.
 */
export async function defaultNamespaceRecallPrefix(config: PluginConfig): Promise<string | null> {
  const root = await resolveDefaultNamespaceRoot(config);
  const rel = path.relative(path.resolve(config.memoryDir), path.resolve(root));
  if (rel === "" || rel === "." || rel.startsWith("..") || path.isAbsolute(rel)) return null;
  const posix = rel.split(path.sep).join("/");
  if (!posix.startsWith("namespaces/")) return null;
  return `${posix}/`;
}

/**
 * Store recall and promotion keep the flat root and the routed default
 * namespace. Other `namespaces/` provenance stays on the weekly report.
 */
export function visibleRubricEntries<T extends {
  observations: string[];
  provenance: string[];
  observationEntries?: Array<{ note: string; provenance: string[] }>;
}>(
  entries: T[],
  observationsFor: (entry: T) => Array<{ note: string; provenance: string[] }>,
  defaultNamespacePrefix: string | null,
): T[] {
  return entries.flatMap((entry) => {
    const visible = observationsFor(entry).filter((item) =>
      provenanceVisibleInStoreRecall(item.provenance, defaultNamespacePrefix),
    );
    if (visible.length === 0) return [];
    return [{
      ...entry,
      observations: visible.map((item) => item.note),
      provenance: [...new Set(visible.flatMap((item) => item.provenance))],
      observationEntries: visible,
    }];
  });
}

/**
 * The mistake registry keeps 500 patterns. Store-visible action failures stay
 * ahead of correction text, and every visible pattern stays ahead of another
 * namespace, so a full correction week cannot drop the caller's own outcomes.
 */
export function capWeeklyPatternDetails<T extends { pattern: string; provenance: readonly string[] }>(
  details: readonly T[],
  categoryFor: (pattern: string) => string | undefined,
  defaultNamespacePrefix: string | null,
  limit = 500,
): T[] {
  const visibleActions: T[] = [];
  const visibleOther: T[] = [];
  const foreign: T[] = [];
  for (const detail of details) {
    if (!provenanceVisibleInStoreRecall(detail.provenance, defaultNamespacePrefix)) {
      foreign.push(detail);
      continue;
    }
    if (categoryFor(detail.pattern) === "action") visibleActions.push(detail);
    else visibleOther.push(detail);
  }
  return [...visibleActions, ...visibleOther, ...foreign].slice(0, limit);
}

/**
 * Active correction mistakes whose visible source files are all missing or
 * non-active. The next synthesis retires those registry entries immediately.
 * Every active correction entry is checked. The weekly pattern cap and the
 * retirement window already bound how many of those entries exist.
 */
export async function forgottenCorrectionPatterns(
  storage: WeeklyEvidenceStorage,
  memoryDir: string,
  registry: ReadonlyArray<{ category?: string; status?: string; pattern: string; provenance?: readonly string[] }>,
  defaultNamespacePrefix: string | null,
): Promise<Set<string>> {
  const out = new Set<string>();
  for (const entry of registry) {
    if (entry.category !== "correction" || entry.status !== "active") continue;
    const visible = (entry.provenance ?? []).filter((item) =>
      provenanceVisibleInStoreRecall([item], defaultNamespacePrefix),
    );
    if (visible.length === 0) continue;
    let stillActive = false;
    for (const rel of visible) {
      if (rel.includes("..") || path.isAbsolute(rel)) {
        stillActive = true;
        break;
      }
      let memory: MemoryFile | null;
      try {
        memory = await storage.readMemoryByPath(path.join(memoryDir, rel));
      } catch {
        stillActive = true;
        break;
      }
      if (!memory) {
        // readMemoryByPath returns null for a missing file and for a read
        // or decrypt failure. Only a confirmed absence can retire the lesson.
        const sourcePath = path.join(memoryDir, rel);
        try {
          await lstat(sourcePath);
          stillActive = true;
          break;
        } catch (err) {
          if (!isErrnoCode(err, "ENOENT")) {
            stillActive = true;
            break;
          }
        }
        continue;
      }
      const raw = readRawMemoryDocument(memory);
      const status = raw ? rawFrontmatterScalar(raw, "status") : undefined;
      if (!status || status === "active") {
        stillActive = true;
        break;
      }
    }
    if (!stillActive) out.add(entry.pattern);
  }
  return out;
}

export function provenanceVisibleInStoreRecall(
  provenance: readonly string[],
  defaultNamespacePrefix: string | null = null,
): boolean {
  return provenance.length === 0 || provenance.some((item) => {
    if (!item.startsWith("namespaces/")) return true;
    return defaultNamespacePrefix !== null && item.startsWith(defaultNamespacePrefix);
  });
}

/** Ledger rows that belong to the flat root or the routed default namespace. */
export function actionEventsVisibleInStore<T extends { ledgerLabel: string; line: number }>(
  events: readonly T[],
  defaultNamespacePrefix: string | null,
): T[] {
  return events.filter((event) =>
    provenanceVisibleInStoreRecall([`${event.ledgerLabel}:L${event.line}`], defaultNamespacePrefix),
  );
}

function collapseWhitespace(value: string): string {
  return value.replace(/\s+/g, " ").trim();
}

function rawConfidence(raw: string): number | null {
  const text = rawFrontmatterScalar(raw, "confidence");
  if (!text) return null;
  const value = Number(text);
  if (!Number.isFinite(value)) return null;
  return Math.max(0, Math.min(1, value));
}

/** Top-level frontmatter scalar. Missing keys stay missing — parser defaults are not used. */
function rawFrontmatterScalar(raw: string, key: string): string | undefined {
  const newline = raw.startsWith("---\r\n") ? 5 : raw.startsWith("---\n") ? 4 : -1;
  if (newline < 0) return undefined;
  const headerEnd = raw.indexOf("\n---", newline);
  if (headerEnd < 0) return undefined;
  const block = raw.slice(newline, headerEnd);
  const prefix = `${key}:`;
  for (const line of block.split("\n")) {
    const normalized = line.endsWith("\r") ? line.slice(0, -1) : line;
    if (normalized.startsWith(" ") || normalized.startsWith("\t")) continue;
    if (!normalized.startsWith(prefix)) continue;
    let value = normalized.slice(prefix.length).trim();
    if (value.length >= 2) {
      const quote = value[0];
      if ((quote === '"' || quote === "'") && value.endsWith(quote)) {
        value = value.slice(1, -1);
      }
    }
    return value.length > 0 ? value : undefined;
  }
  return undefined;
}

/**
 * Single-flight boundary for weekly synthesis, keyed by memory directory.
 * The daemon scheduler and the access surface each drive their own engine
 * instance against the same files; without serialization, concurrent
 * read-modify-write of mistakes.json, rubrics, and the calibration index
 * would let the last finisher discard the other run's updates.
 */

const weeklySynthesisTails = new Map<string, Promise<void>>();

export function queueWeeklySynthesis<T>(memoryDir: string, run: () => Promise<T>): Promise<T> {
  const prior = weeklySynthesisTails.get(memoryDir);
  const next = prior === undefined ? run() : prior.then(run, run);
  const tail = next.then(
    () => undefined,
    () => undefined
  );
  weeklySynthesisTails.set(memoryDir, tail);
  void tail.then(() => {
    if (weeklySynthesisTails.get(memoryDir) === tail) weeklySynthesisTails.delete(memoryDir);
  });
  return next;
}

/**
 * Key-derivation functions for the secure-store module.
 *
 * Issue #690 (PR 1/4) — pure primitives, no I/O.
 *
 * Naming note
 * -----------
 * The directory is named `secure-store/` — NOT `vault/` — because
 * `vault` is already a content-source concept in `native-knowledge.ts`
 * (Obsidian vaults: `ObsidianVaultState`, `vaultId`, `obsidianVaults`
 * config, etc.). Reusing the `vault` namespace for at-rest encryption
 * would cause symbol collisions and reader confusion.
 *
 * KDF choice — Argon2id primary, scrypt compatibility
 * ---------------------------------------------------
 * Issue #690 specifies Argon2id (OWASP m=64 MiB, t=3, p=4) as the
 * preferred KDF. We use `@node-rs/argon2` for the Argon2id runtime
 * and keep scrypt as the compatibility path for stores initialized
 * before Argon2id support landed.
 *
 * The algorithm name + params are persisted in the metadata file, so
 * stores keep deriving with the same KDF they were initialized with.
 *
 * Trade-off summary:
 *   - scrypt N=2^17, r=8, p=1 → ~128 MiB memory, ~150 ms on a modern
 *     laptop. Memory-hard. Resists GPU/ASIC attacks meaningfully.
 *   - Argon2id m=64 MiB, t=3, p=4 → ~64 MiB memory, similar wall
 *     time. Considered the modern best-in-class but requires native
 *     bindings.
 *
 * Both produce a 32-byte key suitable for AES-256-GCM.
 */

import { scryptSync, timingSafeEqual } from "node:crypto";
import { createRequire } from "node:module";

type Argon2Runtime = typeof import("@node-rs/argon2");

const requireArgon2 = createRequire(import.meta.url);
let argon2Runtime: Argon2Runtime | undefined;

function loadArgon2Runtime(): Argon2Runtime {
  try {
    argon2Runtime ??= requireArgon2("@node-rs/argon2") as Argon2Runtime;
    return argon2Runtime;
  } catch (cause) {
    throw new Error(
      "Argon2id KDF requires @node-rs/argon2 to be installed and loadable on this platform. " +
        "Use scrypt compatibility mode for stores that must run without the Argon2 native binding.",
      { cause },
    );
  }
}

/** KDF algorithms supported by the secure-store metadata format. */
export type KdfAlgorithm = "scrypt" | "argon2id";

/** Parameters for the scrypt KDF (RFC 7914). */
export interface ScryptParams {
  /** CPU/memory cost. Must be a power of 2. Default 2^17 = 131072. */
  N: number;
  /** Block size. Default 8. */
  r: number;
  /** Parallelization. Default 1. */
  p: number;
  /** Output key length in bytes. Default 32 (AES-256). */
  keyLength: number;
  /** maxmem ceiling for scrypt; defaults to 256 MiB. */
  maxmem: number;
}

/** Parameters for the Argon2id KDF. */
export interface Argon2idParams {
  /** Memory cost in KiB. OWASP default 65536 (64 MiB). */
  memoryKiB: number;
  /** Time cost (iterations). OWASP default 3. */
  iterations: number;
  /** Parallelism. OWASP default 4. */
  parallelism: number;
  /** Output key length in bytes. Default 32 (AES-256). */
  keyLength: number;
}

/** Strong scrypt defaults (OWASP-acceptable for 2024+). */
export const DEFAULT_SCRYPT_PARAMS: Readonly<ScryptParams> = Object.freeze({
  // 2^17. Hex-coding the literal would obscure the doubling chain.
  N: 1 << 17,
  r: 8,
  p: 1,
  keyLength: 32,
  // 256 MiB ceiling — comfortably above the 128 MiB scrypt needs at N=2^17.
  maxmem: 256 * 1024 * 1024,
});

/** OWASP Argon2id defaults. */
export const DEFAULT_ARGON2ID_PARAMS: Readonly<Argon2idParams> = Object.freeze({
  memoryKiB: 64 * 1024,
  iterations: 3,
  parallelism: 4,
  keyLength: 32,
});

/** Salt length in bytes. 128 bits is the modern minimum. */
export const KDF_SALT_LENGTH = 16;

/** Required derived-key length for AES-256 (32 bytes). */
export const KDF_KEY_LENGTH = 32;

/**
 * Validate that scrypt parameters are within sane bounds and that
 * `N` is a power of 2 (required by RFC 7914).
 */
export function validateScryptParams(params: ScryptParams): void {
  const { N, r, p, keyLength, maxmem } = params;
  if (!Number.isInteger(N) || N < 2) {
    throw new Error(`scrypt N must be an integer ≥ 2, got ${N}`);
  }
  // Cursor Low + codex P2: a `(N & (N - 1)) !== 0` check truncates
  // to 32-bit semantics for `N >= 2**31`, so values like `5 * 2**30`
  // would pass even though they are not powers of two, and absurdly
  // large values like `2**33` would silently lock up the KDF. Use
  // Math.log2-based detection plus an explicit upper bound at 2**30
  // (already orders of magnitude past any practical memory budget)
  // so out-of-range or non-power-of-two values are rejected loudly.
  if (N > 2 ** 30) {
    throw new Error(`scrypt N is unreasonably large (max 2^30), got ${N}`);
  }
  if (!Number.isInteger(Math.log2(N))) {
    throw new Error(`scrypt N must be a power of 2, got ${N}`);
  }
  if (!Number.isInteger(r) || r < 1) {
    throw new Error(`scrypt r must be a positive integer, got ${r}`);
  }
  if (!Number.isInteger(p) || p < 1) {
    throw new Error(`scrypt p must be a positive integer, got ${p}`);
  }
  if (!Number.isInteger(keyLength) || keyLength < 16) {
    throw new Error(
      `scrypt keyLength must be ≥ 16 (need 32 for AES-256), got ${keyLength}`,
    );
  }
  if (!Number.isInteger(maxmem) || maxmem < 1024) {
    throw new Error(`scrypt maxmem must be a sane positive integer, got ${maxmem}`);
  }
}

/** Validate Argon2id parameters before invoking the native KDF binding. */
export function validateArgon2idParams(params: Argon2idParams): void {
  const { memoryKiB, iterations, parallelism, keyLength } = params;
  if (!Number.isInteger(memoryKiB) || memoryKiB < 8) {
    throw new Error(`argon2id memoryKiB must be an integer ≥ 8, got ${memoryKiB}`);
  }
  if (!Number.isInteger(iterations) || iterations < 1) {
    throw new Error(`argon2id iterations must be a positive integer, got ${iterations}`);
  }
  if (!Number.isInteger(parallelism) || parallelism < 1 || parallelism > 255) {
    throw new Error(`argon2id parallelism must be an integer in [1, 255], got ${parallelism}`);
  }
  if (!Number.isInteger(keyLength) || keyLength !== KDF_KEY_LENGTH) {
    throw new Error(
      `argon2id keyLength must be ${KDF_KEY_LENGTH} (AES-256 requires a 32-byte key), got ${keyLength}`,
    );
  }
}

/**
 * Derive a key from a passphrase + salt using scrypt.
 *
 * Pure: no I/O, no global state, deterministic for a given
 * (passphrase, salt, params) tuple.
 *
 * @throws if params are invalid.
 */
export function deriveKeyScrypt(
  passphrase: string,
  salt: Uint8Array,
  params: ScryptParams = DEFAULT_SCRYPT_PARAMS,
): Buffer {
  if (typeof passphrase !== "string") {
    throw new Error("passphrase must be a string");
  }
  if (passphrase.length === 0) {
    throw new Error("passphrase must not be empty");
  }
  if (!(salt instanceof Uint8Array) || salt.length < 8) {
    throw new Error(
      `salt must be a Uint8Array of at least 8 bytes, got ${salt?.length ?? "non-buffer"}`,
    );
  }
  validateScryptParams(params);
  return scryptSync(passphrase, Buffer.from(salt), params.keyLength, {
    N: params.N,
    r: params.r,
    p: params.p,
    maxmem: params.maxmem,
  });
}

/**
 * Derive a key from a passphrase + salt using Argon2id.
 *
 * The returned raw hash is used directly as the AES-256-GCM master key.
 * The same public KDF params are persisted in secure-store metadata so
 * unlock can reproduce the exact key later.
 */
export function deriveKeyArgon2id(
  passphrase: string,
  salt: Uint8Array,
  params: Argon2idParams = DEFAULT_ARGON2ID_PARAMS,
): Buffer {
  if (typeof passphrase !== "string") {
    throw new Error("passphrase must be a string");
  }
  if (passphrase.length === 0) {
    throw new Error("passphrase must not be empty");
  }
  if (!(salt instanceof Uint8Array) || salt.length < 8) {
    throw new Error(
      `salt must be a Uint8Array of at least 8 bytes, got ${salt?.length ?? "non-buffer"}`,
    );
  }
  validateArgon2idParams(params);
  const { Algorithm, Version, hashRawSync } = loadArgon2Runtime();
  return hashRawSync(passphrase, {
    algorithm: Algorithm.Argon2id,
    version: Version.V0x13,
    memoryCost: params.memoryKiB,
    timeCost: params.iterations,
    parallelism: params.parallelism,
    outputLen: params.keyLength,
    salt,
  });
}

/**
 * Algorithm-dispatching KDF. The algorithm name is recorded in the
 * metadata file so existing stores continue using their original KDF.
 */
export function deriveKey(
  algorithm: KdfAlgorithm,
  passphrase: string,
  salt: Uint8Array,
  params: ScryptParams | Argon2idParams,
): Buffer {
  if (algorithm === "scrypt") {
    return deriveKeyScrypt(passphrase, salt, params as ScryptParams);
  }
  if (algorithm === "argon2id") {
    return deriveKeyArgon2id(passphrase, salt, params as Argon2idParams);
  }
  throw new Error(`unknown KDF algorithm: ${algorithm as string}`);
}

/**
 * Constant-time equality for two derived keys / MACs. Re-exported so
 * callers don't reach into `node:crypto` directly for this primitive.
 */
export function constantTimeEqual(a: Uint8Array, b: Uint8Array): boolean {
  if (a.length !== b.length) {
    return false;
  }
  return timingSafeEqual(Buffer.from(a), Buffer.from(b));
}

/**
 * Secure-store metadata file format.
 *
 * Issue #690 (PR 1/4) — pure data structure + serialize/parse helpers.
 * No I/O. The eventual `secure-store init` CLI (PR 2/4) will be the
 * surface that actually writes a metadata file to disk.
 *
 * Purpose
 * -------
 * When at-rest encryption is enabled, the memory directory needs a
 * stable record of:
 *
 *   - which KDF algorithm was used to derive the master key,
 *   - the algorithm parameters (so changing OWASP defaults later
 *     doesn't break existing stores),
 *   - the canonical salt for the master key,
 *   - the metadata format version (so we can evolve the file).
 *
 * Crucially, the metadata file does **not** contain the master key,
 * the passphrase, or anything that would let an attacker decrypt
 * memories. It contains only the public parameters needed to
 * re-derive the same key from the same passphrase.
 *
 * On-disk shape
 * -------------
 * The file is JSON. All binary fields are encoded as lowercase hex
 * strings (chosen over base64 for readability when the file is
 * `cat`'d during incident response).
 *
 *   {
 *     "format": "remnic.secure-store.metadata",
 *     "formatVersion": 1,
 *     "kdf": {
 *       "algorithm": "argon2id",
 *       "params": { "memoryKiB": 65536, "iterations": 3, "parallelism": 4, "keyLength": 32 },
 *       "salt": "<32-hex-chars-for-16-bytes>"
 *     },
 *     "createdAt": "<ISO-8601 timestamp>",
 *     "note": "<optional human-readable note>"
 *   }
 */

import {
  DEFAULT_ARGON2ID_PARAMS,
  DEFAULT_SCRYPT_PARAMS,
  KDF_SALT_LENGTH,
  type Argon2idParams,
  type KdfAlgorithm,
  type ScryptParams,
} from "./kdf.js";

/** Stable identifier so we can sniff the file shape without parsing JSON. */
export const METADATA_FORMAT = "remnic.secure-store.metadata" as const;

/** Current metadata format version. Bump on breaking schema changes. */
export const METADATA_FORMAT_VERSION = 1 as const;

export interface SecureStoreMetadataKdfScrypt {
  algorithm: "scrypt";
  params: ScryptParams;
  /** Hex-encoded salt. Length must match `KDF_SALT_LENGTH` after decode. */
  salt: string;
}

export interface SecureStoreMetadataKdfArgon2id {
  algorithm: "argon2id";
  params: Argon2idParams;
  salt: string;
}

export type SecureStoreMetadataKdf =
  | SecureStoreMetadataKdfScrypt
  | SecureStoreMetadataKdfArgon2id;

export interface SecureStoreMetadata {
  format: typeof METADATA_FORMAT;
  formatVersion: number;
  kdf: SecureStoreMetadataKdf;
  /** ISO-8601 timestamp recorded at init time. */
  createdAt: string;
  /** Optional human-readable note. Never persist secrets here. */
  note?: string;
}

function bytesToHex(bytes: Uint8Array): string {
  return Buffer.from(bytes).toString("hex");
}

function hexToBytes(hex: string, expectedLength: number): Buffer {
  if (typeof hex !== "string") {
    throw new Error("hex field must be a string");
  }
  if (!/^[0-9a-f]*$/i.test(hex)) {
    throw new Error("hex field must contain only hexadecimal characters");
  }
  if (hex.length % 2 !== 0) {
    throw new Error("hex field must have even length");
  }
  const buf = Buffer.from(hex, "hex");
  if (buf.length !== expectedLength) {
    throw new Error(
      `hex field decoded to ${buf.length} bytes, expected ${expectedLength}`,
    );
  }
  return buf;
}

export interface BuildMetadataOptions {
  algorithm: KdfAlgorithm;
  salt: Uint8Array;
  /** Optional override; defaults to `DEFAULT_SCRYPT_PARAMS` / `DEFAULT_ARGON2ID_PARAMS`. */
  params?: ScryptParams | Argon2idParams;
  /** Optional ISO timestamp. Defaults to `new Date().toISOString()`. */
  createdAt?: string;
  /** Optional human-readable note. */
  note?: string;
}

/**
 * Build an in-memory `SecureStoreMetadata` object from the given
 * algorithm + salt. Pure: does not touch the filesystem or the clock
 * unless `createdAt` is omitted (in which case `new Date()` is read).
 */
export function buildMetadata(options: BuildMetadataOptions): SecureStoreMetadata {
  const { algorithm, salt } = options;
  if (!(salt instanceof Uint8Array) || salt.length !== KDF_SALT_LENGTH) {
    throw new Error(
      `salt must be ${KDF_SALT_LENGTH} bytes, got ${salt?.length ?? "non-buffer"}`,
    );
  }
  const createdAt = options.createdAt ?? new Date().toISOString();

  let kdf: SecureStoreMetadataKdf;
  if (algorithm === "scrypt") {
    const params = (options.params as ScryptParams | undefined) ?? {
      ...DEFAULT_SCRYPT_PARAMS,
    };
    kdf = { algorithm: "scrypt", params, salt: bytesToHex(salt) };
  } else if (algorithm === "argon2id") {
    const params = (options.params as Argon2idParams | undefined) ?? {
      ...DEFAULT_ARGON2ID_PARAMS,
    };
    kdf = { algorithm: "argon2id", params, salt: bytesToHex(salt) };
  } else {
    throw new Error(`unknown KDF algorithm: ${algorithm as string}`);
  }

  const meta: SecureStoreMetadata = {
    format: METADATA_FORMAT,
    formatVersion: METADATA_FORMAT_VERSION,
    kdf,
    createdAt,
  };
  if (options.note !== undefined) {
    meta.note = options.note;
  }
  return meta;
}

/**
 * Serialize metadata to a stable JSON string with sorted top-level
 * keys. Stable ordering matters because hash-based integrity checks
 * may eventually consume the serialized form.
 */
export function serializeMetadata(meta: SecureStoreMetadata): string {
  // Validate before serializing so we never write a malformed file.
  validateMetadata(meta);
  // JSON.stringify preserves insertion order; we construct the object
  // explicitly to lock the field order.
  const ordered: Record<string, unknown> = {
    format: meta.format,
    formatVersion: meta.formatVersion,
    kdf: orderKdf(meta.kdf),
    createdAt: meta.createdAt,
  };
  if (meta.note !== undefined) {
    ordered.note = meta.note;
  }
  return JSON.stringify(ordered, null, 2);
}

function orderKdf(kdf: SecureStoreMetadataKdf): Record<string, unknown> {
  if (kdf.algorithm === "scrypt") {
    return {
      algorithm: kdf.algorithm,
      params: {
        N: kdf.params.N,
        r: kdf.params.r,
        p: kdf.params.p,
        keyLength: kdf.params.keyLength,
        maxmem: kdf.params.maxmem,
      },
      salt: kdf.salt,
    };
  }
  return {
    algorithm: kdf.algorithm,
    params: {
      memoryKiB: kdf.params.memoryKiB,
      iterations: kdf.params.iterations,
      parallelism: kdf.params.parallelism,
      keyLength: kdf.params.keyLength,
    },
    salt: kdf.salt,
  };
}

/**
 * Parse a metadata JSON string. Throws on any structural problem.
 * Callers that need to migrate older formats should branch on
 * `formatVersion` *before* calling this; this function is strict
 * about the current version.
 */
export function parseMetadata(json: string): SecureStoreMetadata {
  if (typeof json !== "string") {
    throw new Error("metadata input must be a string");
  }
  let parsed: unknown;
  try {
    parsed = JSON.parse(json);
  } catch (e) {
    const msg = e instanceof Error ? e.message : String(e);
    throw new Error(`metadata is not valid JSON: ${msg}`);
  }
  if (typeof parsed !== "object" || parsed === null || Array.isArray(parsed)) {
    throw new Error("metadata must be a JSON object");
  }
  const obj = parsed as Record<string, unknown>;
  if (obj.format !== METADATA_FORMAT) {
    throw new Error(
      `unexpected metadata format: ${String(obj.format)} (expected ${METADATA_FORMAT})`,
    );
  }
  if (obj.formatVersion !== METADATA_FORMAT_VERSION) {
    throw new Error(
      `unsupported metadata formatVersion: ${String(obj.formatVersion)} ` +
        `(this build supports ${METADATA_FORMAT_VERSION})`,
    );
  }
  if (typeof obj.createdAt !== "string" || obj.createdAt.length === 0) {
    throw new Error("metadata.createdAt must be a non-empty string");
  }
  if (obj.note !== undefined && typeof obj.note !== "string") {
    throw new Error("metadata.note must be a string when present");
  }
  const kdf = parseKdf(obj.kdf);
  const meta: SecureStoreMetadata = {
    format: METADATA_FORMAT,
    formatVersion: METADATA_FORMAT_VERSION,
    kdf,
    createdAt: obj.createdAt,
  };
  if (typeof obj.note === "string") {
    meta.note = obj.note;
  }
  validateMetadata(meta);
  return meta;
}

function parseKdf(value: unknown): SecureStoreMetadataKdf {
  if (typeof value !== "object" || value === null || Array.isArray(value)) {
    throw new Error("metadata.kdf must be an object");
  }
  const k = value as Record<string, unknown>;
  if (k.algorithm !== "scrypt" && k.algorithm !== "argon2id") {
    throw new Error(`metadata.kdf.algorithm must be 'scrypt' or 'argon2id', got ${String(k.algorithm)}`);
  }
  if (typeof k.salt !== "string") {
    throw new Error("metadata.kdf.salt must be a hex string");
  }
  // Decode to validate length and hex shape; we don't need the bytes here.
  hexToBytes(k.salt, KDF_SALT_LENGTH);
  if (typeof k.params !== "object" || k.params === null || Array.isArray(k.params)) {
    throw new Error("metadata.kdf.params must be an object");
  }
  const params = k.params as Record<string, unknown>;
  if (k.algorithm === "scrypt") {
    const required: (keyof ScryptParams)[] = ["N", "r", "p", "keyLength", "maxmem"];
    for (const key of required) {
      if (typeof params[key] !== "number" || !Number.isFinite(params[key] as number)) {
        throw new Error(`metadata.kdf.params.${key} must be a finite number`);
      }
    }
    return {
      algorithm: "scrypt",
      params: {
        N: params.N as number,
        r: params.r as number,
        p: params.p as number,
        keyLength: params.keyLength as number,
        maxmem: params.maxmem as number,
      },
      salt: k.salt,
    };
  }
  // argon2id
  const required2: (keyof Argon2idParams)[] = [
    "memoryKiB",
    "iterations",
    "parallelism",
    "keyLength",
  ];
  for (const key of required2) {
    if (typeof params[key] !== "number" || !Number.isFinite(params[key] as number)) {
      throw new Error(`metadata.kdf.params.${key} must be a finite number`);
    }
  }
  return {
    algorithm: "argon2id",
    params: {
      memoryKiB: params.memoryKiB as number,
      iterations: params.iterations as number,
      parallelism: params.parallelism as number,
      keyLength: params.keyLength as number,
    },
    salt: k.salt,
  };
}

/** Validate a metadata object's invariants. Throws on the first problem. */
export function validateMetadata(meta: SecureStoreMetadata): void {
  if (meta.format !== METADATA_FORMAT) {
    throw new Error(`metadata.format must be ${METADATA_FORMAT}`);
  }
  if (meta.formatVersion !== METADATA_FORMAT_VERSION) {
    throw new Error(`metadata.formatVersion must be ${METADATA_FORMAT_VERSION}`);
  }
  if (typeof meta.createdAt !== "string" || meta.createdAt.length === 0) {
    throw new Error("metadata.createdAt must be a non-empty ISO-8601 string");
  }
  // Salt round-trip check.
  hexToBytes(meta.kdf.salt, KDF_SALT_LENGTH);
  if (meta.kdf.algorithm === "scrypt") {
    const { N, r, p, keyLength, maxmem } = meta.kdf.params;
    // Cursor Low + codex P2: bitwise `(N & (N - 1))` truncates to
    // 32-bit signed in JS, so for N >= 2**31 the check silently
    // wraps and accepts non-powers-of-two like `5 * 2**30`. Use
    // Math.log2 plus an upper bound at 2**30 so out-of-range
    // values are rejected loudly at metadata-load time rather than
    // locking up the KDF later.
    if (
      !Number.isInteger(N) ||
      N < 2 ||
      N > 2 ** 30 ||
      !Number.isInteger(Math.log2(N))
    ) {
      throw new Error("metadata.kdf.params.N must be a power of 2 in [2, 2^30]");
    }
    if (!Number.isInteger(r) || r < 1) {
      throw new Error("metadata.kdf.params.r must be a positive integer");
    }
    if (!Number.isInteger(p) || p < 1) {
      throw new Error("metadata.kdf.params.p must be a positive integer");
    }
    // Codex P2: cipher.ts hard-requires a 32-byte AES-256 key
    // (`assertAesKey`). Accepting `keyLength: 16` here would parse
    // and validate cleanly but later fail at encrypt/decrypt time
    // — a latent runtime break. Reject anything other than 32 at
    // load time so the metadata file is the authoritative gate.
    if (!Number.isInteger(keyLength) || keyLength !== 32) {
      throw new Error("metadata.kdf.params.keyLength must be 32 (AES-256 requires a 32-byte key)");
    }
    if (!Number.isInteger(maxmem) || maxmem < 1024) {
      throw new Error("metadata.kdf.params.maxmem must be a positive integer");
    }
  } else if (meta.kdf.algorithm === "argon2id") {
    const { memoryKiB, iterations, parallelism, keyLength } = meta.kdf.params;
    if (!Number.isInteger(memoryKiB) || memoryKiB < 8) {
      throw new Error("metadata.kdf.params.memoryKiB must be ≥ 8");
    }
    if (!Number.isInteger(iterations) || iterations < 1) {
      throw new Error("metadata.kdf.params.iterations must be a positive integer");
    }
    if (!Number.isInteger(parallelism) || parallelism < 1 || parallelism > 255) {
      throw new Error("metadata.kdf.params.parallelism must be an integer in [1, 255]");
    }
    // Codex P2: cipher.ts hard-requires a 32-byte AES-256 key
    // (`assertAesKey`). Accepting `keyLength: 16` here would parse
    // and validate cleanly but later fail at encrypt/decrypt time
    // — a latent runtime break. Reject anything other than 32 at
    // load time so the metadata file is the authoritative gate.
    if (!Number.isInteger(keyLength) || keyLength !== 32) {
      throw new Error("metadata.kdf.params.keyLength must be 32 (AES-256 requires a 32-byte key)");
    }
  }
}

/**
 * Decode the salt field of a metadata object back into bytes.
 * Convenience helper so callers don't reach into the hex codec.
 */
export function decodeMetadataSalt(meta: SecureStoreMetadata): Buffer {
  return hexToBytes(meta.kdf.salt, KDF_SALT_LENGTH);
}

/**
 * On-disk header for an initialized secure-store (issue #690 PR 2/4).
 *
 * The header file is the persistent record that a memory directory
 * has had `remnic secure-store init` run against it. It is a JSON
 * file at `<memoryDir>/.secure-store/header.json` with two parts:
 *
 *   1. The KDF metadata from PR 1/4 (`SecureStoreMetadata`) —
 *      algorithm, params, and salt. Public; safe to read/copy.
 *   2. A "verifier" — a tiny AES-GCM-encrypted envelope sealed under
 *      the derived key at init time. Unlock re-derives the key from
 *      the entered passphrase and tries to `open()` the verifier; if
 *      the auth tag validates, the passphrase is correct.
 *
 * Why a verifier?
 * ---------------
 * Without one, "wrong passphrase" can only be detected when the
 * daemon tries to decrypt actual memory data — too late for a
 * useful CLI error. The verifier gives the unlock command a fast,
 * data-independent passphrase check.
 *
 * The verifier plaintext is a fixed magic string (no secret content).
 * Its only role is to be sealable + openable; the auth-tag check is
 * what proves the key.
 *
 * Naming
 * ------
 * Directory: `.secure-store/` (leading dot — hidden, hints at
 * sensitivity). File: `header.json`. Avoids collision with
 * `.secure-store-metadata.json` from PR 1/4 docs since the header
 * is a strict superset.
 */

import { mkdir, readFile, writeFile } from "node:fs/promises";
import path from "node:path";

import { open, seal } from "./cipher.js";
import {
  KDF_KEY_LENGTH,
  KDF_SALT_LENGTH,
  deriveKey,
  type Argon2idParams,
  type ScryptParams,
} from "./kdf.js";
import {
  buildMetadata,
  decodeMetadataSalt,
  parseMetadata,
  serializeMetadata,
  type SecureStoreMetadata,
} from "./metadata.js";

/** Subdirectory under `memoryDir` that holds the header + future state. */
export const SECURE_STORE_DIR_NAME = ".secure-store";

/** Header filename. Stable name so operators can locate it. */
export const HEADER_FILENAME = "header.json";

/** Stable identifier so the file shape is sniffable without parsing JSON. */
export const HEADER_FORMAT = "remnic.secure-store.header" as const;

/** Current header format version. Bump on breaking schema changes. */
export const HEADER_FORMAT_VERSION = 1 as const;

/**
 * Magic bytes sealed under the master key at init time. Constant
 * across stores — there's no value in randomizing it because the
 * salt + IV + auth tag already make every verifier envelope unique.
 *
 * The string never appears in plaintext on disk; it only exists
 * inside an AES-GCM-sealed envelope. Its job is purely to give the
 * cipher something to authenticate.
 */
export const VERIFIER_PLAINTEXT = Buffer.from("remnic-secure-store-v1", "utf8");

/** AAD bound into the verifier envelope. */
const VERIFIER_AAD = Buffer.from("remnic-secure-store/verifier", "utf8");

export interface SecureStoreHeader {
  format: typeof HEADER_FORMAT;
  formatVersion: number;
  /** KDF metadata (algorithm + params + salt). */
  metadata: SecureStoreMetadata;
  /** Hex-encoded sealed envelope. */
  verifier: string;
  /** ISO-8601 timestamp recorded at init time. */
  createdAt: string;
}

/** Resolve the canonical secure-store directory for a memory root. */
export function secureStoreDir(memoryDir: string): string {
  return path.join(memoryDir, SECURE_STORE_DIR_NAME);
}

/** Resolve the canonical header path for a memory root. */
export function headerPath(memoryDir: string): string {
  return path.join(secureStoreDir(memoryDir), HEADER_FILENAME);
}

/**
 * Build a `SecureStoreHeader` in memory from an already-derived key
 * and metadata. Pure: does not touch the filesystem. The clock is
 * read once if `createdAt` is omitted.
 */
export function buildHeader(options: {
  metadata: SecureStoreMetadata;
  derivedKey: Buffer;
  createdAt?: string;
}): SecureStoreHeader {
  const { metadata, derivedKey } = options;
  if (!Buffer.isBuffer(derivedKey) || derivedKey.length !== KDF_KEY_LENGTH) {
    throw new Error(
      `derivedKey must be a ${KDF_KEY_LENGTH}-byte Buffer, got length=${derivedKey?.length ?? "non-buffer"}`,
    );
  }
  const salt = decodeMetadataSalt(metadata);
  if (salt.length !== KDF_SALT_LENGTH) {
    throw new Error(`metadata salt is ${salt.length} bytes, expected ${KDF_SALT_LENGTH}`);
  }
  const envelope = seal(derivedKey, salt, VERIFIER_PLAINTEXT, { aad: VERIFIER_AAD });
  return {
    format: HEADER_FORMAT,
    formatVersion: HEADER_FORMAT_VERSION,
    metadata,
    verifier: envelope.toString("hex"),
    createdAt: options.createdAt ?? new Date().toISOString(),
  };
}

/** Stable JSON serialization with locked top-level key order. */
export function serializeHeader(header: SecureStoreHeader): string {
  validateHeader(header);
  // Inline metadata as a parsed object so it shares the same
  // canonical key ordering as the standalone metadata file.
  const metadataString = serializeMetadata(header.metadata);
  const metadataObject = JSON.parse(metadataString) as Record<string, unknown>;
  const ordered = {
    format: header.format,
    formatVersion: header.formatVersion,
    metadata: metadataObject,
    verifier: header.verifier,
    createdAt: header.createdAt,
  };
  return JSON.stringify(ordered, null, 2);
}

/** Parse a header JSON string. Throws on any structural problem. */
export function parseHeader(json: string): SecureStoreHeader {
  if (typeof json !== "string") {
    throw new Error("header input must be a string");
  }
  let parsed: unknown;
  try {
    parsed = JSON.parse(json);
  } catch (e) {
    const msg = e instanceof Error ? e.message : String(e);
    throw new Error(`header is not valid JSON: ${msg}`);
  }
  if (typeof parsed !== "object" || parsed === null || Array.isArray(parsed)) {
    throw new Error("header must be a JSON object");
  }
  const obj = parsed as Record<string, unknown>;
  if (obj.format !== HEADER_FORMAT) {
    throw new Error(
      `unexpected header format: ${String(obj.format)} (expected ${HEADER_FORMAT})`,
    );
  }
  if (obj.formatVersion !== HEADER_FORMAT_VERSION) {
    throw new Error(
      `unsupported header formatVersion: ${String(obj.formatVersion)} (this build supports ${HEADER_FORMAT_VERSION})`,
    );
  }
  if (typeof obj.verifier !== "string" || obj.verifier.length === 0) {
    throw new Error("header.verifier must be a non-empty hex string");
  }
  if (!/^[0-9a-fA-F]+$/.test(obj.verifier)) {
    throw new Error("header.verifier must be a hex-encoded string");
  }
  // Codex P2 on PR #737: odd-length hex strings produce a malformed
  // Buffer via `Buffer.from(hex, "hex")` — Node silently truncates the
  // trailing nibble, yielding a buffer that is one byte shorter than
  // expected. Reject odd-length strings before they reach the cipher.
  if (obj.verifier.length % 2 !== 0) {
    throw new Error(
      "header.verifier hex string must have even length (each byte encodes as two hex digits)",
    );
  }
  if (typeof obj.createdAt !== "string" || obj.createdAt.length === 0) {
    throw new Error("header.createdAt must be a non-empty string");
  }
  if (typeof obj.metadata !== "object" || obj.metadata === null) {
    throw new Error("header.metadata must be an object");
  }
  // Reuse the metadata parser for nested validation. We re-stringify
  // the nested object and feed it through `parseMetadata` so any
  // schema drift is caught in one place.
  const metadata = parseMetadata(JSON.stringify(obj.metadata));
  const header: SecureStoreHeader = {
    format: HEADER_FORMAT,
    formatVersion: HEADER_FORMAT_VERSION,
    metadata,
    verifier: obj.verifier,
    createdAt: obj.createdAt,
  };
  validateHeader(header);
  return header;
}

/** Validate a header object's invariants. Throws on the first problem. */
export function validateHeader(header: SecureStoreHeader): void {
  if (header.format !== HEADER_FORMAT) {
    throw new Error(`header.format must be ${HEADER_FORMAT}`);
  }
  if (header.formatVersion !== HEADER_FORMAT_VERSION) {
    throw new Error(`header.formatVersion must be ${HEADER_FORMAT_VERSION}`);
  }
  if (typeof header.createdAt !== "string" || header.createdAt.length === 0) {
    throw new Error("header.createdAt must be a non-empty ISO-8601 string");
  }
  if (typeof header.verifier !== "string" || header.verifier.length === 0) {
    throw new Error("header.verifier must be a non-empty hex string");
  }
  if (!/^[0-9a-fA-F]+$/.test(header.verifier)) {
    throw new Error("header.verifier must be a hex-encoded string");
  }
  // Enforce even length: odd-length hex is silently truncated by
  // `Buffer.from(hex, "hex")` which yields a malformed envelope.
  if (header.verifier.length % 2 !== 0) {
    throw new Error(
      "header.verifier hex string must have even length (each byte encodes as two hex digits)",
    );
  }
  // The nested metadata object is already validated by `parseMetadata`
  // when read from disk; on the build path, `buildHeader` constructs
  // it via `buildMetadata`. We still re-run shape validation here as
  // a belt-and-braces guard for callers that hand-construct headers.
  if (header.metadata.format !== "remnic.secure-store.metadata") {
    throw new Error("header.metadata.format must be remnic.secure-store.metadata");
  }
}

/**
 * Verify a candidate key against the header's verifier envelope.
 *
 * Returns true iff the AES-GCM auth tag validates. Wrong passphrase,
 * tampered envelope, and tampered AAD all return false.
 */
export function verifyKey(header: SecureStoreHeader, candidateKey: Buffer): boolean {
  if (!Buffer.isBuffer(candidateKey) || candidateKey.length !== KDF_KEY_LENGTH) {
    return false;
  }
  const envelope = Buffer.from(header.verifier, "hex");
  try {
    const plaintext = open(candidateKey, envelope, { aad: VERIFIER_AAD });
    return plaintext.equals(VERIFIER_PLAINTEXT);
  } catch {
    return false;
  }
}

/**
 * Derive a key from the passphrase using the algorithm + params +
 * salt recorded in the header. Pure: no I/O.
 */
export function deriveKeyFromHeader(header: SecureStoreHeader, passphrase: string): Buffer {
  const salt = decodeMetadataSalt(header.metadata);
  // Cursor low on PR #737: a previous version branched on the
  // algorithm and returned `header.metadata.kdf.params` from both
  // arms — a no-op conditional. Pass the discriminated union member
  // through directly; `deriveKey` performs the algorithm dispatch.
  const params: ScryptParams | Argon2idParams = header.metadata.kdf.params;
  return deriveKey(header.metadata.kdf.algorithm, passphrase, salt, params);
}

/**
 * Read and parse the header at `<memoryDir>/.secure-store/header.json`.
 * Returns `null` if the file does not exist; throws on malformed
 * content.
 */
export async function readHeader(memoryDir: string): Promise<SecureStoreHeader | null> {
  const target = headerPath(memoryDir);
  let raw: string;
  try {
    raw = await readFile(target, "utf8");
  } catch (e) {
    if ((e as NodeJS.ErrnoException).code === "ENOENT") {
      return null;
    }
    throw e;
  }
  return parseHeader(raw);
}

/**
 * Write the header with atomic exclusive-create semantics.
 *
 * Uses the `wx` flag (`O_CREAT | O_EXCL`) so the OS rejects the call
 * atomically when the file already exists. Two concurrent
 * `secure-store init` invocations cannot both observe "missing" and
 * race to overwrite each other — the second writer reliably gets
 * `EEXIST` and surfaces "Refusing to overwrite".
 *
 * Codex P1 on PR #737: a previous version pre-checked existence with
 * `readFile` then `writeFile`+`rename`, which is a check-then-act
 * race. The `wx` flag closes that window at the kernel layer.
 *
 * Crash safety: if the write is interrupted mid-flight, a partial
 * `header.json` may remain on disk. `parseHeader` rejects partial
 * files cleanly and the operator can delete the stub and retry. We
 * don't use temp+rename here because (a) headers are tiny (≤ 1 KiB),
 * (b) there is no prior valid file to destroy, and (c) `wx` already
 * gives us atomic exclusivity — the rename trick (CLAUDE.md gotcha
 * #54) is for replacing an existing valid file, which is exactly the
 * scenario this function refuses.
 */
export async function writeHeader(memoryDir: string, header: SecureStoreHeader): Promise<string> {
  validateHeader(header);
  const dir = secureStoreDir(memoryDir);
  await mkdir(dir, { recursive: true });
  const target = headerPath(memoryDir);
  try {
    await writeFile(target, serializeHeader(header), {
      encoding: "utf8",
      mode: 0o600,
      flag: "wx",
    });
  } catch (e) {
    if ((e as NodeJS.ErrnoException).code === "EEXIST") {
      throw new Error(
        `secure-store header already exists at ${target}. Refusing to overwrite — initialize a fresh store or remove the existing header explicitly.`,
      );
    }
    throw e;
  }
  return target;
}

/** Convenience: build metadata + header in one call from a passphrase. */
export function buildHeaderFromPassphrase(options: {
  passphrase: string;
  salt: Buffer;
  /** Optional override; defaults to Argon2id with `DEFAULT_ARGON2ID_PARAMS`. */
  algorithm?: "scrypt" | "argon2id";
  params?: ScryptParams | Argon2idParams;
  createdAt?: string;
  note?: string;
}): { header: SecureStoreHeader; derivedKey: Buffer } {
  const { passphrase, salt } = options;
  const algorithm = options.algorithm ?? "argon2id";
  const metadataOpts: {
    algorithm: "scrypt" | "argon2id";
    salt: Buffer;
    params?: ScryptParams | Argon2idParams;
    createdAt?: string;
    note?: string;
  } = { algorithm, salt };
  if (options.params !== undefined) metadataOpts.params = options.params;
  if (options.createdAt !== undefined) metadataOpts.createdAt = options.createdAt;
  if (options.note !== undefined) metadataOpts.note = options.note;
  const metadata = buildMetadata(metadataOpts);
  // Cursor low on PR #737: same identical-branches ternary as in
  // `deriveKeyFromHeader`. The discriminated union already carries
  // the right shape; `deriveKey` dispatches on `algorithm`.
  const params: ScryptParams | Argon2idParams = metadata.kdf.params;
  const derivedKey = deriveKey(algorithm, passphrase, salt, params);
  const headerOpts: { metadata: SecureStoreMetadata; derivedKey: Buffer; createdAt?: string } = {
    metadata,
    derivedKey,
  };
  if (options.createdAt !== undefined) headerOpts.createdAt = options.createdAt;
  const header = buildHeader(headerOpts);
  return { header, derivedKey };
}

/**
 * In-memory keyring for the secure-store module (issue #690 PR 2/4).
 *
 * Holds derived AES-256-GCM master keys for unlocked stores. The
 * keyring is process-local: keys are NEVER persisted to disk, never
 * logged, and never serialized. A daemon restart re-locks every
 * registered store.
 *
 * Scoping
 * -------
 * Entries are keyed by a stable string id (typically the absolute
 * path to the secure-store directory, after `~` expansion). This
 * lets multiple memory roots share a single daemon process without
 * one store's key bleeding into another (matches the per-`serviceId`
 * scoping discipline called out in CLAUDE.md gotcha #11).
 *
 * Lifecycle
 * ---------
 *   - `unlock(id, key)` — register a derived key.
 *   - `getKey(id)` — read a registered key (or `null`).
 *   - `lock(id)` — clear a single entry, zeroing the key bytes.
 *   - `lockAll()` — clear every entry, zeroing every key.
 *   - `status(id)` — non-secret status snapshot for `secure-store
 *     status`.
 *
 * Zeroization
 * -----------
 * `lock` and `lockAll` overwrite the key buffer with zeros before
 * dropping the reference. The JS engine may keep additional copies
 * outside our control; this is best-effort hygiene, not a defense
 * against memory-dump attacks.
 */

const ENTRIES = new Map<string, KeyringEntry>();

/** A single unlocked store. The key buffer is never copied out. */
interface KeyringEntry {
  key: Buffer;
  unlockedAt: string;
}

/** Status snapshot — no secret material. */
export interface KeyringStatus {
  /** True iff a key is currently registered for this id. */
  unlocked: boolean;
  /** ISO-8601 timestamp the key was registered, or null when locked. */
  unlockedAt: string | null;
}

/**
 * Register a derived key for the given id. If an entry already
 * exists, its old key is zeroed before being replaced.
 *
 * The caller MUST pass an exclusive 32-byte buffer; the keyring
 * takes ownership and will zero it on lock.
 */
export function unlock(id: string, key: Buffer, now: () => Date = () => new Date()): void {
  if (typeof id !== "string" || id.length === 0) {
    throw new Error("keyring id must be a non-empty string");
  }
  if (!Buffer.isBuffer(key) || key.length !== 32) {
    throw new Error(`keyring key must be a 32-byte Buffer, got length=${key?.length ?? "non-buffer"}`);
  }
  const existing = ENTRIES.get(id);
  if (existing) {
    existing.key.fill(0);
  }
  ENTRIES.set(id, { key, unlockedAt: now().toISOString() });
}

/** Read the registered key for `id`, or `null` if locked. */
export function getKey(id: string): Buffer | null {
  const entry = ENTRIES.get(id);
  return entry ? entry.key : null;
}

/** Clear a single entry. Zeros the underlying buffer. Returns true if cleared. */
export function lock(id: string): boolean {
  const entry = ENTRIES.get(id);
  if (!entry) return false;
  entry.key.fill(0);
  ENTRIES.delete(id);
  return true;
}

/** Clear every registered key. Used on shutdown or for tests. */
export function lockAll(): void {
  for (const entry of ENTRIES.values()) {
    entry.key.fill(0);
  }
  ENTRIES.clear();
}

/** Non-secret status snapshot. */
export function status(id: string): KeyringStatus {
  const entry = ENTRIES.get(id);
  if (!entry) {
    return { unlocked: false, unlockedAt: null };
  }
  return { unlocked: true, unlockedAt: entry.unlockedAt };
}

/** Test-only helper: how many entries are currently registered. */
export function size(): number {
  return ENTRIES.size;
}

/**
 * AES-256-GCM encrypt / decrypt primitives for the secure-store
 * module.
 *
 * Issue #690 (PR 1/4) — pure primitives, no I/O.
 *
 * Sealed envelope format
 * ----------------------
 * A "sealed" buffer is the canonical on-disk shape for a single
 * encrypted blob. It contains the salt used to derive the key from
 * the user's passphrase, so a caller who has the passphrase + the
 * sealed buffer can decrypt without any external metadata.
 *
 *   [VERSION:1][SALT:16][IV:12][AUTHTAG:16][CIPHERTEXT:...]
 *
 *   - VERSION (1 byte): envelope format version. Currently 1. Future
 *     versions can change the layout (e.g. variable salt length, an
 *     algorithm identifier byte) by bumping this byte.
 *   - SALT (16 bytes): KDF salt. Persisted with the ciphertext so the
 *     same passphrase can re-derive the key on read.
 *   - IV (12 bytes): GCM nonce. Must be unique per (key, ciphertext)
 *     pair. We generate it fresh from `randomBytes` on every encrypt
 *     call. Reusing an IV with the same key destroys GCM's
 *     confidentiality and authenticity guarantees.
 *   - AUTHTAG (16 bytes): GCM authentication tag. Tampering with any
 *     byte of (salt | iv | tag | ciphertext) causes decryption to
 *     fail with an auth-tag mismatch.
 *   - CIPHERTEXT (variable): the encrypted payload.
 *
 * The salt is stored alongside the ciphertext (rather than only in a
 * separate metadata file) so an individual encrypted blob is
 * self-contained for diagnostics and recovery. The metadata file
 * (see `metadata.ts`) records the *canonical* salt + KDF params for a
 * store; the per-blob salt is expected to match the metadata salt in
 * normal operation, but the format does not require it — a future PR
 * could rotate per-blob salts if desired.
 *
 * AAD support
 * -----------
 * Callers can pass associated authenticated data (AAD) — typically a
 * file path or namespace tag — that is authenticated but not
 * encrypted. AAD must be supplied identically on encrypt and decrypt;
 * a mismatch causes auth-tag failure. AAD is NOT serialized into the
 * envelope; the caller is responsible for re-supplying it on decrypt.
 */

import { createCipheriv, createDecipheriv, randomBytes } from "node:crypto";

/** Current envelope format version. */
export const ENVELOPE_VERSION = 1 as const;

/** GCM nonce length. 96 bits is the NIST-recommended size for AES-GCM. */
export const IV_LENGTH = 12;

/** GCM authentication tag length. 16 bytes (128 bits) — the maximum. */
export const AUTH_TAG_LENGTH = 16;

/** Salt length carried in the envelope. Must match KDF_SALT_LENGTH. */
export const ENVELOPE_SALT_LENGTH = 16;

/** Required key length for AES-256. */
export const AES_KEY_LENGTH = 32;

/** Byte offsets of each envelope field (for clarity at call sites). */
export const ENVELOPE_LAYOUT = Object.freeze({
  version: 0,
  salt: 1,
  iv: 1 + ENVELOPE_SALT_LENGTH,
  authTag: 1 + ENVELOPE_SALT_LENGTH + IV_LENGTH,
  ciphertext: 1 + ENVELOPE_SALT_LENGTH + IV_LENGTH + AUTH_TAG_LENGTH,
});

/** Minimum envelope size: header + zero-length ciphertext. */
export const ENVELOPE_HEADER_SIZE = ENVELOPE_LAYOUT.ciphertext;

export interface EncryptOptions {
  /**
   * Optional associated data — authenticated but not encrypted.
   * Caller must supply the same value on decrypt.
   */
  aad?: Uint8Array;
  /**
   * Override the per-call IV. Strongly discouraged outside of tests:
   * GCM is catastrophically broken if an IV is reused under the same
   * key. Production callers should always let the cipher generate a
   * fresh random IV.
   */
  iv?: Uint8Array;
}

export interface DecryptOptions {
  /** Same AAD that was supplied to `encrypt`. */
  aad?: Uint8Array;
}

/**
 * Validate that a key is a 32-byte buffer suitable for AES-256.
 */
function assertAesKey(key: Uint8Array): void {
  if (!(key instanceof Uint8Array)) {
    throw new Error("key must be a Uint8Array");
  }
  if (key.length !== AES_KEY_LENGTH) {
    throw new Error(
      `AES-256-GCM requires a ${AES_KEY_LENGTH}-byte key, got ${key.length}`,
    );
  }
}

/**
 * Encrypt `plaintext` under `key` and return a sealed envelope buffer.
 *
 * @param key 32-byte AES-256 key (from `deriveKey`).
 * @param salt 16-byte KDF salt to embed in the envelope. The caller is
 *   responsible for using the same salt that was passed to the KDF.
 * @param plaintext the bytes to encrypt.
 * @param options optional `aad` / `iv` overrides.
 */
export function seal(
  key: Uint8Array,
  salt: Uint8Array,
  plaintext: Uint8Array,
  options: EncryptOptions = {},
): Buffer {
  assertAesKey(key);
  if (!(salt instanceof Uint8Array) || salt.length !== ENVELOPE_SALT_LENGTH) {
    throw new Error(
      `salt must be ${ENVELOPE_SALT_LENGTH} bytes, got ${salt?.length ?? "non-buffer"}`,
    );
  }
  if (!(plaintext instanceof Uint8Array)) {
    throw new Error("plaintext must be a Uint8Array");
  }
  let iv: Uint8Array;
  if (options.iv) {
    if (options.iv.length !== IV_LENGTH) {
      throw new Error(`iv must be ${IV_LENGTH} bytes, got ${options.iv.length}`);
    }
    iv = options.iv;
  } else {
    iv = randomBytes(IV_LENGTH);
  }

  const cipher = createCipheriv("aes-256-gcm", Buffer.from(key), Buffer.from(iv), {
    authTagLength: AUTH_TAG_LENGTH,
  });
  // Codex P1: bind the envelope header (version + salt) into AAD so
  // flipping the salt or version on a sealed envelope triggers an
  // auth failure on open. Without this, callers using a metadata-
  // derived store key would still decrypt successfully even after
  // the per-blob salt was tampered with — silently desynchronizing
  // per-blob salt from metadata/recovery logic. Caller-supplied AAD
  // is appended after the header so existing AAD usage stays intact.
  const headerAad = buildHeaderAad(salt);
  const finalAad = options.aad
    ? Buffer.concat([headerAad, Buffer.from(options.aad)])
    : headerAad;
  cipher.setAAD(finalAad);
  const ciphertext = Buffer.concat([cipher.update(Buffer.from(plaintext)), cipher.final()]);
  const authTag = cipher.getAuthTag();
  if (authTag.length !== AUTH_TAG_LENGTH) {
    // Defensive: Node always produces 16 bytes when authTagLength is 16.
    throw new Error(`unexpected auth tag length: ${authTag.length}`);
  }

  const envelope = Buffer.alloc(ENVELOPE_HEADER_SIZE + ciphertext.length);
  envelope.writeUInt8(ENVELOPE_VERSION, ENVELOPE_LAYOUT.version);
  Buffer.from(salt).copy(envelope, ENVELOPE_LAYOUT.salt);
  Buffer.from(iv).copy(envelope, ENVELOPE_LAYOUT.iv);
  authTag.copy(envelope, ENVELOPE_LAYOUT.authTag);
  ciphertext.copy(envelope, ENVELOPE_LAYOUT.ciphertext);
  return envelope;
}

/** Parsed view of a sealed envelope. Useful for inspection in tests. */
export interface ParsedEnvelope {
  version: number;
  salt: Buffer;
  iv: Buffer;
  authTag: Buffer;
  ciphertext: Buffer;
}

/**
 * Parse a sealed envelope into its component fields without
 * decrypting. Throws on malformed input. The returned buffers are
 * sub-views (not copies) — do not mutate.
 */
export function parseEnvelope(envelope: Uint8Array): ParsedEnvelope {
  if (!(envelope instanceof Uint8Array)) {
    throw new Error("envelope must be a Uint8Array");
  }
  if (envelope.length < ENVELOPE_HEADER_SIZE) {
    throw new Error(
      `envelope too short: need ≥ ${ENVELOPE_HEADER_SIZE} bytes, got ${envelope.length}`,
    );
  }
  const buf = Buffer.from(envelope.buffer, envelope.byteOffset, envelope.byteLength);
  const version = buf.readUInt8(ENVELOPE_LAYOUT.version);
  if (version !== ENVELOPE_VERSION) {
    throw new Error(
      `unsupported envelope version: ${version} (this build supports ${ENVELOPE_VERSION})`,
    );
  }
  return {
    version,
    salt: buf.subarray(ENVELOPE_LAYOUT.salt, ENVELOPE_LAYOUT.salt + ENVELOPE_SALT_LENGTH),
    iv: buf.subarray(ENVELOPE_LAYOUT.iv, ENVELOPE_LAYOUT.iv + IV_LENGTH),
    authTag: buf.subarray(
      ENVELOPE_LAYOUT.authTag,
      ENVELOPE_LAYOUT.authTag + AUTH_TAG_LENGTH,
    ),
    ciphertext: buf.subarray(ENVELOPE_LAYOUT.ciphertext),
  };
}

/**
 * Decrypt a sealed envelope and return the plaintext.
 *
 * Throws on:
 *   - malformed envelope (wrong length, wrong version);
 *   - wrong key (auth-tag mismatch);
 *   - tampered ciphertext / iv / auth tag (auth-tag mismatch);
 *   - mismatched AAD (auth-tag mismatch).
 *
 * The same error class is intentional: from the caller's standpoint
 * "wrong passphrase" and "tampered ciphertext" should both be
 * non-recoverable failures.
 */
export function open(
  key: Uint8Array,
  envelope: Uint8Array,
  options: DecryptOptions = {},
): Buffer {
  assertAesKey(key);
  const parsed = parseEnvelope(envelope);
  const decipher = createDecipheriv("aes-256-gcm", Buffer.from(key), parsed.iv, {
    authTagLength: AUTH_TAG_LENGTH,
  });
  decipher.setAuthTag(parsed.authTag);
  // Codex P1: header (version + salt) is bound at seal time.
  // Reconstruct it identically so a tampered salt fails auth.
  const headerAad = buildHeaderAad(parsed.salt);
  const finalAad = options.aad
    ? Buffer.concat([headerAad, Buffer.from(options.aad)])
    : headerAad;
  decipher.setAAD(finalAad);
  // `final()` throws if the auth tag doesn't validate.
  return Buffer.concat([decipher.update(parsed.ciphertext), decipher.final()]);
}

/**
 * Build the canonical header AAD: a single byte version followed by
 * the per-blob salt. Binds the immutable envelope header into AES-GCM
 * authentication so tampering with either value triggers auth failure
 * on open (codex P1 on PR #718).
 */
function buildHeaderAad(salt: Uint8Array): Buffer {
  const out = Buffer.alloc(1 + ENVELOPE_SALT_LENGTH);
  out.writeUInt8(ENVELOPE_VERSION, 0);
  Buffer.from(salt).copy(out, 1);
  return out;
}

/**
 * Generate a fresh random salt of the canonical envelope length.
 * Convenience wrapper so callers don't reach into `node:crypto`.
 */
export function generateSalt(): Buffer {
  return randomBytes(ENVELOPE_SALT_LENGTH);
}

/**
 * Pure handlers behind the `remnic secure-store {init,unlock,lock,
 * status,migrate,disable}` CLI surface (issue #690 PR 2/4 + #779/#780).
 *
 * Each handler:
 *   - takes an explicit `memoryDir` (already `~`-expanded by the CLI),
 *   - takes an injectable passphrase reader (so tests don't need a
 *     real TTY and never touch real readline state),
 *   - returns a structured report (no `console.log` inside),
 *   - never logs the passphrase or any secret material.
 *
 * The actual `console.log` formatting lives in `cli-renderer.ts` so
 * tests can assert on the report shape without parsing text.
 */

import { generateSalt as generateEnvelopeSalt } from "./cipher.js";
import {
  buildHeaderFromPassphrase,
  deriveKeyFromHeader,
  headerPath,
  readHeader,
  secureStoreDir,
  verifyKey,
  writeHeader,
  type SecureStoreHeader,
} from "./header.js";
import * as keyring from "./keyring.js";
import {
  DEFAULT_ARGON2ID_PARAMS,
  DEFAULT_SCRYPT_PARAMS,
  KDF_SALT_LENGTH,
  type Argon2idParams,
  type KdfAlgorithm,
  type ScryptParams,
} from "./kdf.js";
import {
  decryptMemoryDirToPlaintext,
  migrateMemoryDirToEncrypted,
  type DecryptResult,
  type MigrateResult,
} from "./secure-fs.js";

/** Passphrase source — async so callers can read from a TTY without echo. */
export type PassphraseReader = (
  prompt: string,
  options?: { confirm?: boolean },
) => Promise<string>;

/** Common options accepted by every handler. */
export interface SecureStoreHandlerCommon {
  memoryDir: string;
  /**
   * Stable identifier for the in-memory keyring entry. Defaults to
   * the secure-store directory under `memoryDir`. Tests override
   * this to keep entries from leaking across cases.
   */
  keyringId?: string;
  /** Optional clock injection for deterministic tests. */
  now?: () => Date;
}

// ─── init ─────────────────────────────────────────────────────────────

export interface SecureStoreInitOptions extends SecureStoreHandlerCommon {
  /** Passphrase reader — called twice (entry + confirmation). */
  readPassphrase: PassphraseReader;
  /**
   * KDF algorithm. Defaults to `"argon2id"` for new stores.
   * `"scrypt"` remains supported for explicit compatibility cases.
   */
  algorithm?: KdfAlgorithm;
  /** KDF parameter override; defaults to OWASP-acceptable params for the selected KDF. */
  params?: ScryptParams | Argon2idParams;
  /** Pre-generated salt for tests; production callers should omit. */
  salt?: Buffer;
  /** Optional human-readable note recorded in metadata. Never persist secrets. */
  note?: string;
}

export interface SecureStoreInitReport {
  ok: true;
  /** Absolute path of the header file that was written. */
  headerPath: string;
  /** Algorithm + params used for the master key derivation. */
  kdf: SecureStoreHeader["metadata"]["kdf"];
  /** ISO-8601 timestamp recorded in the header. */
  createdAt: string;
}

/**
 * Initialize a new secure-store header. Refuses to overwrite an
 * existing header (use `header.ts:writeHeader` directly with explicit
 * intent if you need to reinitialize a destroyed store).
 */
export async function runSecureStoreInit(
  options: SecureStoreInitOptions,
): Promise<SecureStoreInitReport> {
  const { memoryDir, readPassphrase } = options;
  if (typeof memoryDir !== "string" || memoryDir.length === 0) {
    throw new Error("secure-store init: memoryDir is required");
  }
  // Fail fast if a header already exists, before we waste KDF time.
  const existing = await readHeader(memoryDir);
  if (existing !== null) {
    throw new Error(
      `secure-store header already exists at ${headerPath(memoryDir)}. Run 'remnic secure-store status' to inspect, or remove the .secure-store directory explicitly to reinitialize.`,
    );
  }
  const passphrase = await readPassphrase("Enter new passphrase: ", { confirm: true });
  validatePassphrase(passphrase);

  const algorithm: KdfAlgorithm = options.algorithm ?? "argon2id";
  const params = resolveParams(algorithm, options.params);
  const salt = options.salt ?? generateEnvelopeSalt();
  if (salt.length !== KDF_SALT_LENGTH) {
    throw new Error(`salt must be ${KDF_SALT_LENGTH} bytes, got ${salt.length}`);
  }

  const built = buildHeaderFromPassphrase({
    passphrase,
    salt,
    algorithm,
    params,
    ...(options.note !== undefined ? { note: options.note } : {}),
    ...(options.now ? { createdAt: options.now().toISOString() } : {}),
  });
  // Zero the derived key — init does NOT auto-unlock; the operator
  // must run `unlock` separately. This mirrors GnuPG-style hygiene
  // and keeps `init` safe to run from automation that should never
  // hold the master key in memory.
  built.derivedKey.fill(0);

  const writtenPath = await writeHeader(memoryDir, built.header);
  return {
    ok: true,
    headerPath: writtenPath,
    kdf: built.header.metadata.kdf,
    createdAt: built.header.createdAt,
  };
}

// ─── unlock ───────────────────────────────────────────────────────────

export interface SecureStoreUnlockOptions extends SecureStoreHandlerCommon {
  readPassphrase: PassphraseReader;
}

export type SecureStoreUnlockReport =
  | { ok: true; unlockedAt: string; algorithm: KdfAlgorithm }
  | { ok: false; reason: "not-initialized" | "wrong-passphrase" };

export async function runSecureStoreUnlock(
  options: SecureStoreUnlockOptions,
): Promise<SecureStoreUnlockReport> {
  const { memoryDir, readPassphrase } = options;
  const header = await readHeader(memoryDir);
  if (!header) {
    return { ok: false, reason: "not-initialized" };
  }
  const passphrase = await readPassphrase("Enter passphrase: ");
  validatePassphrase(passphrase);
  const candidateKey = deriveKeyFromHeader(header, passphrase);
  if (!verifyKey(header, candidateKey)) {
    candidateKey.fill(0);
    return { ok: false, reason: "wrong-passphrase" };
  }
  const id = options.keyringId ?? secureStoreDir(memoryDir);
  const now = options.now ?? (() => new Date());
  keyring.unlock(id, candidateKey, now);
  const status = keyring.status(id);
  return {
    ok: true,
    unlockedAt: status.unlockedAt ?? now().toISOString(),
    algorithm: header.metadata.kdf.algorithm,
  };
}

// ─── lock ─────────────────────────────────────────────────────────────

export interface SecureStoreLockOptions extends SecureStoreHandlerCommon {}

export interface SecureStoreLockReport {
  ok: true;
  /** True if a key was registered and is now cleared; false if it was already locked. */
  cleared: boolean;
}

export function runSecureStoreLock(options: SecureStoreLockOptions): SecureStoreLockReport {
  const id = options.keyringId ?? secureStoreDir(options.memoryDir);
  const cleared = keyring.lock(id);
  return { ok: true, cleared };
}

// ─── migrate ─────────────────────────────────────────────────────────

export interface SecureStoreMigrateOptions extends SecureStoreHandlerCommon {
  /**
   * Optional passphrase reader for standalone CLI migration. A prior
   * `secure-store unlock` command only unlocks that process-local keyring, so
   * standalone migrate can prompt and install the key in this process instead
   * of pretending another process still has it.
   */
  readPassphrase?: PassphraseReader;
}

export type SecureStoreMigrateReport =
  | ({ ok: true } & MigrateResult)
  | ({
      ok: false;
      reason: "not-initialized" | "locked" | "wrong-passphrase" | "file-errors";
    } & MigrateResult);

export async function runSecureStoreMigrate(
  options: SecureStoreMigrateOptions,
): Promise<SecureStoreMigrateReport> {
  const { memoryDir } = options;
  const header = await readHeader(memoryDir);
  if (!header) {
    return {
      ok: false,
      reason: "not-initialized",
      encrypted: 0,
      skipped: 0,
      errors: [],
    };
  }

  const id = options.keyringId ?? secureStoreDir(memoryDir);
  const key = keyring.getKey(id) ?? await unlockForThisProcess({
    memoryDir,
    header,
    keyringId: id,
    readPassphrase: options.readPassphrase,
    now: options.now,
  });
  if (key === null) {
    return {
      ok: false,
      reason: "locked",
      encrypted: 0,
      skipped: 0,
      errors: [],
    };
  }
  if (key === "wrong-passphrase") {
    return {
      ok: false,
      reason: "wrong-passphrase",
      encrypted: 0,
      skipped: 0,
      errors: [],
    };
  }

  const result = await migrateMemoryDirToEncrypted(memoryDir, key);
  if (result.errors.length > 0) {
    return { ok: false, reason: "file-errors", ...result };
  }
  return { ok: true, ...result };
}

// ─── disable/decrypt ─────────────────────────────────────────────────

export interface SecureStoreDisableOptions extends SecureStoreHandlerCommon {
  /**
   * Optional passphrase reader for standalone CLI decrypt/disable. See
   * SecureStoreMigrateOptions.readPassphrase for the process-local keyring
   * contract.
   */
  readPassphrase?: PassphraseReader;
}

export type SecureStoreDisableReport =
  | ({ ok: true } & DecryptResult)
  | ({
      ok: false;
      reason: "not-initialized" | "locked" | "wrong-passphrase" | "file-errors";
    } & DecryptResult);

export async function runSecureStoreDisable(
  options: SecureStoreDisableOptions,
): Promise<SecureStoreDisableReport> {
  const { memoryDir } = options;
  const header = await readHeader(memoryDir);
  if (!header) {
    return {
      ok: false,
      reason: "not-initialized",
      decrypted: 0,
      skipped: 0,
      errors: [],
    };
  }

  const id = options.keyringId ?? secureStoreDir(memoryDir);
  const key = keyring.getKey(id) ?? await unlockForThisProcess({
    memoryDir,
    header,
    keyringId: id,
    readPassphrase: options.readPassphrase,
    now: options.now,
  });
  if (key === null) {
    return {
      ok: false,
      reason: "locked",
      decrypted: 0,
      skipped: 0,
      errors: [],
    };
  }
  if (key === "wrong-passphrase") {
    return {
      ok: false,
      reason: "wrong-passphrase",
      decrypted: 0,
      skipped: 0,
      errors: [],
    };
  }

  const result = await decryptMemoryDirToPlaintext(memoryDir, key);
  if (result.errors.length > 0) {
    return { ok: false, reason: "file-errors", ...result };
  }
  return { ok: true, ...result };
}

// ─── status ───────────────────────────────────────────────────────────

export interface SecureStoreStatusOptions extends SecureStoreHandlerCommon {}

export interface SecureStoreStatusReport {
  /** True iff a header file exists in `<memoryDir>/.secure-store/`. */
  initialized: boolean;
  /** Path the status check probed. Useful for operators. */
  headerPath: string;
  /** Locked/unlocked state of the in-memory keyring entry. */
  locked: boolean;
  /** ISO-8601 timestamp of the most recent unlock, or null when locked. */
  unlockedAt: string | null;
  /** Header metadata (algorithm + params + salt hex), or null when uninitialized. */
  kdf: SecureStoreHeader["metadata"]["kdf"] | null;
  /** Header `createdAt`, or null when uninitialized. */
  createdAt: string | null;
}

export async function runSecureStoreStatus(
  options: SecureStoreStatusOptions,
): Promise<SecureStoreStatusReport> {
  const { memoryDir } = options;
  const id = options.keyringId ?? secureStoreDir(memoryDir);
  const header = await readHeader(memoryDir);
  const ks = keyring.status(id);
  const target = headerPath(memoryDir);
  if (!header) {
    return {
      initialized: false,
      headerPath: target,
      locked: !ks.unlocked,
      unlockedAt: ks.unlockedAt,
      kdf: null,
      createdAt: null,
    };
  }
  return {
    initialized: true,
    headerPath: target,
    locked: !ks.unlocked,
    unlockedAt: ks.unlockedAt,
    kdf: header.metadata.kdf,
    createdAt: header.createdAt,
  };
}

// ─── helpers ──────────────────────────────────────────────────────────

/** Minimum passphrase length. 8 chars is intentionally permissive — operators may use phrase managers. */
export const MIN_PASSPHRASE_LENGTH = 8;

function validatePassphrase(passphrase: string): void {
  if (typeof passphrase !== "string") {
    throw new Error("passphrase must be a string");
  }
  if (passphrase.length === 0) {
    throw new Error("passphrase must not be empty");
  }
  if (passphrase.length < MIN_PASSPHRASE_LENGTH) {
    throw new Error(`passphrase must be at least ${MIN_PASSPHRASE_LENGTH} characters`);
  }
}

function resolveParams(
  algorithm: KdfAlgorithm,
  override: ScryptParams | Argon2idParams | undefined,
): ScryptParams | Argon2idParams {
  if (override !== undefined) return override;
  if (algorithm === "scrypt") return { ...DEFAULT_SCRYPT_PARAMS };
  return { ...DEFAULT_ARGON2ID_PARAMS };
}

async function unlockForThisProcess(options: {
  memoryDir: string;
  header: SecureStoreHeader;
  keyringId: string;
  readPassphrase?: PassphraseReader;
  now?: () => Date;
}): Promise<Buffer | null | "wrong-passphrase"> {
  if (!options.readPassphrase) return null;
  const passphrase = await options.readPassphrase("Enter passphrase: ");
  validatePassphrase(passphrase);
  const candidateKey = deriveKeyFromHeader(options.header, passphrase);
  if (!verifyKey(options.header, candidateKey)) {
    candidateKey.fill(0);
    return "wrong-passphrase";
  }
  keyring.unlock(options.keyringId, candidateKey, options.now ?? (() => new Date()));
  return candidateKey;
}

/**
 * Console-text renderers for the `remnic engram secure-store {init,unlock,
 * lock,status,migrate,disable}` CLI surface (issue #690 PR 2/4 + #779/#780).
 *
 * Pure: each `render*` function takes a typed report and returns a
 * string. CLI handlers do the `console.log`. Tests assert on the
 * returned text directly so behavior stays decoupled from stdout.
 */

import type {
  SecureStoreInitReport,
  SecureStoreLockReport,
  SecureStoreDisableReport,
  SecureStoreMigrateReport,
  SecureStoreStatusReport,
  SecureStoreUnlockReport,
} from "./cli-handlers.js";
import type { SecureStoreHeader } from "./header.js";

export function renderInitReport(report: SecureStoreInitReport): string {
  const lines: string[] = [];
  lines.push("=== Remnic secure-store initialized ===");
  lines.push("");
  lines.push(`header: ${report.headerPath}`);
  lines.push(`createdAt: ${report.createdAt}`);
  lines.push(...renderKdfLines(report.kdf));
  lines.push("");
  lines.push("Note: init does NOT auto-unlock the store. Run");
  lines.push("  remnic engram secure-store unlock");
  lines.push("to register the master key in the current Remnic process.");
  return lines.join("\n");
}

export function renderUnlockReport(report: SecureStoreUnlockReport): string {
  if (report.ok) {
    return `OK — secure-store unlocked in this process at ${report.unlockedAt} (algorithm=${report.algorithm}).`;
  }
  if (report.reason === "not-initialized") {
    return "ERR — secure-store is not initialized. Run 'remnic engram secure-store init' first.";
  }
  return "ERR — wrong passphrase.";
}

export function renderLockReport(report: SecureStoreLockReport): string {
  if (report.cleared) {
    return "OK — secure-store key cleared from this process's in-memory keyring.";
  }
  return "OK — secure-store was already locked in this process (no in-memory key to clear).";
}

export function renderMigrateReport(report: SecureStoreMigrateReport): string {
  if (!report.ok && report.reason === "not-initialized") {
    return "ERR — secure-store is not initialized. Run 'remnic engram secure-store init' first.";
  }
  if (!report.ok && report.reason === "locked") {
    return "ERR — secure-store is locked in this process. Run migrate from an interactive CLI so it can prompt for the passphrase, or unlock inside the daemon process that will perform the migration.";
  }
  if (!report.ok && report.reason === "wrong-passphrase") {
    return "ERR — wrong passphrase.";
  }

  const lines: string[] = [];
  lines.push(report.ok ? "OK — secure-store migration complete." : "ERR — secure-store migration completed with file errors.");
  lines.push(`encrypted: ${report.encrypted}`);
  lines.push(`skipped: ${report.skipped}`);
  lines.push(`errors: ${report.errors.length}`);
  for (const entry of report.errors.slice(0, 10)) {
    lines.push(`- ${entry.filePath}: ${entry.error}`);
  }
  if (report.errors.length > 10) {
    lines.push(`- ... ${report.errors.length - 10} more error(s)`);
  }
  return lines.join("\n");
}

export function renderDisableReport(report: SecureStoreDisableReport): string {
  if (!report.ok && report.reason === "not-initialized") {
    return "ERR — secure-store is not initialized. Run 'remnic engram secure-store init' first.";
  }
  if (!report.ok && report.reason === "locked") {
    return "ERR — secure-store is locked in this process. Run disable from an interactive CLI so it can prompt for the passphrase, or unlock inside the daemon process that will decrypt files.";
  }
  if (!report.ok && report.reason === "wrong-passphrase") {
    return "ERR — wrong passphrase.";
  }

  const lines: string[] = [];
  lines.push(report.ok ? "OK — secure-store disable complete." : "ERR — secure-store disable completed with file errors.");
  lines.push(`decrypted: ${report.decrypted}`);
  lines.push(`skipped: ${report.skipped}`);
  lines.push(`errors: ${report.errors.length}`);
  for (const entry of report.errors.slice(0, 10)) {
    lines.push(`- ${entry.filePath}: ${entry.error}`);
  }
  if (report.errors.length > 10) {
    lines.push(`- ... ${report.errors.length - 10} more error(s)`);
  }
  lines.push("header: kept");
  return lines.join("\n");
}

export function renderStatusReport(report: SecureStoreStatusReport): string {
  const lines: string[] = [];
  lines.push("=== Remnic secure-store status ===");
  lines.push("");
  lines.push(`header: ${report.headerPath}`);
  lines.push(`initialized: ${report.initialized ? "yes" : "no"}`);
  if (!report.initialized) {
    lines.push("");
    lines.push("Run 'remnic engram secure-store init' to initialize a new store.");
    return lines.join("\n");
  }
  lines.push(`createdAt: ${report.createdAt ?? "n/a"}`);
  lines.push(`lockedInThisProcess: ${report.locked ? "yes" : "no"}`);
  if (!report.locked) {
    lines.push(`lastUnlockAt: ${report.unlockedAt ?? "n/a"}`);
  }
  if (report.kdf) {
    lines.push(...renderKdfLines(report.kdf));
  }
  return lines.join("\n");
}

function renderKdfLines(kdf: SecureStoreHeader["metadata"]["kdf"]): string[] {
  const lines: string[] = [];
  lines.push(`kdf.algorithm: ${kdf.algorithm}`);
  if (kdf.algorithm === "scrypt") {
    const { N, r, p, keyLength, maxmem } = kdf.params;
    lines.push(`kdf.params: N=${N} r=${r} p=${p} keyLength=${keyLength} maxmem=${maxmem}`);
  } else {
    const { memoryKiB, iterations, parallelism, keyLength } = kdf.params;
    lines.push(
      `kdf.params: memoryKiB=${memoryKiB} iterations=${iterations} parallelism=${parallelism} keyLength=${keyLength}`,
    );
  }
  return lines;
}

/**
 * TTY passphrase reader (issue #690 PR 2/4).
 *
 * Reads a line from stdin without echoing it back to the terminal.
 * Disables echo by setting raw mode + manually buffering input until
 * Enter / EOT.
 *
 * Why not `readline.question`?
 * ----------------------------
 * `readline` echoes by default and has no clean "no-echo" toggle that
 * survives across Node versions. The raw-mode loop is the canonical
 * idiom for reading passwords on Node and matches what `npm` uses
 * internally.
 *
 * Security
 * --------
 *   - Never log the passphrase (no `console.log`, no debug output).
 *   - Never include it in a thrown error message.
 *   - On Ctrl+C / Ctrl+D, abort with a clear error rather than
 *     silently treating EOF as an empty submission.
 *   - On non-TTY stdin (pipe, redirect), read a line via line-buffered
 *     readline so automation (`echo "passphrase" | remnic ...`) works.
 *     Operators are responsible for not piping plaintext passphrases
 *     in shell history; we surface a stderr warning.
 */

import { createInterface } from "node:readline";
import type { Readable, Writable } from "node:stream";
import { StringDecoder } from "node:string_decoder";

import type { PassphraseReader } from "./cli-handlers.js";

export interface CreatePassphraseReaderOptions {
  input?: Readable;
  output?: Writable;
  /** Override stderr for warning surface; defaults to `process.stderr`. */
  errorStream?: Writable;
}

/**
 * Build a `PassphraseReader` bound to the given streams. Exported so
 * tests can construct one against in-memory streams without touching
 * the real TTY.
 */
export function createPassphraseReader(
  options: CreatePassphraseReaderOptions = {},
): PassphraseReader {
  const input = options.input ?? process.stdin;
  const output = options.output ?? process.stdout;
  const errorStream = options.errorStream ?? process.stderr;
  // Codex/Cursor on PR #737: a fresh readline interface per call
  // breaks confirm-mode on piped non-TTY input — the first
  // `createInterface` consumes the entire prebuffered stream
  // (including the second line), so the second `createInterface`
  // sees an already-ended stream and resolves to "". Fix: maintain
  // ONE non-TTY line reader across both reads of a confirm-mode
  // session and pull lines on demand from a buffered queue.
  let nonTtyReader: NonTtyLineReader | null = null;
  let nonTtyWarned = false;
  return async function readPassphrase(
    prompt: string,
    readerOptions?: { confirm?: boolean },
  ): Promise<string> {
    const first = await readSinglePassphrase(prompt);
    if (readerOptions?.confirm) {
      const second = await readSinglePassphrase("Confirm passphrase: ");
      if (first !== second) {
        throw new Error("passphrases did not match");
      }
    }
    return first;
  };

  async function readSinglePassphrase(prompt: string): Promise<string> {
    const inputAsAny = input as Readable & {
      isTTY?: boolean;
      setRawMode?: (raw: boolean) => Readable;
    };
    if (inputAsAny.isTTY && typeof inputAsAny.setRawMode === "function") {
      return readNoEcho(prompt, inputAsAny, output);
    }
    // Non-TTY: line-buffered fallback. Warn once per reader so
    // operators piping plaintext passphrases in shell pipelines are
    // aware their history may contain the secret.
    if (!nonTtyWarned) {
      errorStream.write(
        "[remnic secure-store] warning: stdin is not a TTY; reading passphrase as a plain line. " +
          "Take care that the passphrase is not exposed in shell history.\n",
      );
      nonTtyWarned = true;
    }
    // Codex P1 on PR #737: write the prompt to stderr, not stdout.
    // When the surrounding command outputs JSON to stdout (e.g.
    // `remnic secure-store status --json`), injecting prompt text on
    // stdout corrupts the JSON output and breaks machine consumers.
    // The prompt is UI noise — it belongs on the error/diagnostics
    // stream regardless of whether we're in a TTY.
    errorStream.write(prompt);
    if (!nonTtyReader) nonTtyReader = createNonTtyLineReader(input);
    return nonTtyReader.next();
  }
}

function readNoEcho(
  prompt: string,
  input: Readable & { setRawMode?: (raw: boolean) => Readable },
  output: Writable,
): Promise<string> {
  return new Promise((resolve, reject) => {
    output.write(prompt);
    let buffer = "";
    let settled = false;
    const wasRaw = (input as Readable & { isRaw?: boolean }).isRaw === true;
    // Codex P2 on PR #737: per-chunk `chunk.toString("utf8")` corrupts
    // multibyte characters that straddle a chunk boundary (Node inserts
    // U+FFFD replacement characters for incomplete sequences). Use a
    // StringDecoder, which buffers partial sequences across chunks so
    // non-ASCII passphrases survive intact.
    const decoder = new StringDecoder("utf8");
    if (input.setRawMode) input.setRawMode(true);
    input.resume();
    const cleanup = (): void => {
      input.pause();
      input.removeListener("data", onData);
      // Flush any remaining bytes the decoder is holding so trailing
      // partial sequences are surfaced rather than silently swallowed.
      decoder.end();
      // Restore the prior raw-mode state so we don't strand the parent shell
      // in an unexpected configuration.
      if (input.setRawMode) input.setRawMode(wasRaw);
      output.write("\n");
    };
    const onData = (chunk: Buffer): void => {
      const str = decoder.write(chunk);
      for (const ch of str) {
        if (settled) return;
        const code = ch.charCodeAt(0);
        // Enter / newline: submit.
        if (ch === "\n" || ch === "\r") {
          settled = true;
          cleanup();
          resolve(buffer);
          return;
        }
        // Ctrl+C: abort.
        if (code === 0x03) {
          settled = true;
          cleanup();
          reject(new Error("passphrase entry aborted (Ctrl+C)"));
          return;
        }
        // Ctrl+D / EOT: treat as abort if buffer is empty, else submit.
        if (code === 0x04) {
          settled = true;
          cleanup();
          if (buffer.length === 0) {
            reject(new Error("passphrase entry aborted (EOF)"));
          } else {
            resolve(buffer);
          }
          return;
        }
        // Backspace / DEL.
        // Cursor on PR #737: `buffer.slice(0, -1)` deletes one UTF-16
        // code unit, which splits a surrogate pair when the last
        // character is a non-BMP code point (emoji, etc.). Fix: count
        // code points with `Array.from` and remove the last one. This
        // correctly handles both BMP (single code unit) and non-BMP
        // (surrogate pair) characters atomically.
        if (code === 0x08 || code === 0x7f) {
          if (buffer.length > 0) {
            const codePoints = Array.from(buffer);
            buffer = codePoints.slice(0, -1).join("");
          }
          continue;
        }
        // Ignore other control bytes (escape sequences, etc.).
        if (code < 0x20) {
          continue;
        }
        buffer += ch;
      }
    };
    input.on("data", onData);
  });
}

/**
 * One-shot line reader bound to a non-TTY input stream.
 *
 * Cursor medium on PR #737: a previous version constructed a fresh
 * `readline.createInterface` per `next()` call. On piped non-TTY
 * input, the first interface consumed the entire prebuffered stream
 * (including any subsequent lines) into its internal buffer. The
 * second interface saw an already-`end()`'d input and resolved to "".
 * Fix: construct ONE readline interface, queue every emitted `line`,
 * and let `next()` either return a queued line or wait for the next
 * one. Pending waiters at `close` time are resolved with "" (so an
 * abandoned-stream caller still sees a clean empty response).
 */
interface NonTtyLineReader {
  next(): Promise<string>;
}

function createNonTtyLineReader(input: Readable): NonTtyLineReader {
  const rl = createInterface({ input, terminal: false });
  const lineQueue: string[] = [];
  const waiterQueue: Array<(value: string) => void> = [];
  const errorQueue: Array<(err: Error) => void> = [];
  let closed = false;
  let error: Error | null = null;

  rl.on("line", (line: string) => {
    const waiter = waiterQueue.shift();
    if (waiter) {
      waiter(line);
    } else {
      lineQueue.push(line);
    }
  });
  rl.on("close", () => {
    closed = true;
    while (waiterQueue.length > 0) {
      const w = waiterQueue.shift()!;
      // Drop the matching error slot since we're settling cleanly.
      errorQueue.shift();
      w("");
    }
  });
  rl.on("error", (err: Error) => {
    error = err;
    while (errorQueue.length > 0) {
      const r = errorQueue.shift()!;
      // Drop the matching value slot.
      waiterQueue.shift();
      r(err);
    }
  });

  return {
    next(): Promise<string> {
      if (error) return Promise.reject(error);
      const queued = lineQueue.shift();
      if (queued !== undefined) return Promise.resolve(queued);
      if (closed) return Promise.resolve("");
      return new Promise<string>((resolve, reject) => {
        waiterQueue.push(resolve);
        errorQueue.push(reject);
      });
    },
  };
}

/**
 * Backoff for the tombstone-blocked capture write lock (COS-392).
 *
 * A converge cycle used to give up after three probes about 25ms apart while
 * the daemon still held the lock for an ordinary write. Waiters now sleep
 * outside every lock: equal-jitter exponential backoff, capped per wait, with
 * one overall deadline. The numbers are the production defaults; converge
 * config and env can override them.
 */

export const CAPTURE_WRITE_LOCK_BUSY_MESSAGE = "tombstone-blocked capture write lock remained busy";

export function isTombstoneBlockedCaptureWriteLockBusy(error: unknown): boolean {
  return error instanceof Error && error.message === CAPTURE_WRITE_LOCK_BUSY_MESSAGE;
}

export const DEFAULT_CAPTURE_WRITE_LOCK_INITIAL_DELAY_MS = 50;
export const DEFAULT_CAPTURE_WRITE_LOCK_MAX_DELAY_MS = 2_000;
export const DEFAULT_CAPTURE_WRITE_LOCK_DEADLINE_MS = 60_000;
/** Same hour ceiling as the converge peer HTTP timeout. */
export const MAX_CAPTURE_WRITE_LOCK_WAIT_MS = 3_600_000;

const MAX_BACKOFF_EXPONENT = 16;

export type CaptureWriteLockBackoffLimits = {
  readonly initialDelayMs: number;
  readonly maxDelayMs: number;
  readonly deadlineMs: number;
};

export type CaptureWriteLockLimitSource = {
  readonly captureWriteLockInitialDelayMs?: number;
  readonly captureWriteLockMaxDelayMs?: number;
  readonly captureWriteLockDeadlineMs?: number;
  /**
   * Read when an acquire starts. Converge installs the apply abort signal
   * here so a SIGINT during backoff never reaches the guarded write.
   */
  readonly captureWriteLockSignal?: AbortSignal;
};

/**
 * One backoff wait. Attempt 0 is uniform in `[ceil(initial/2), initial]`
 * (25–50ms at the defaults). Each later attempt doubles that window until
 * `maxDelayMs`. `random` returns a finite number in `[0, 1]`.
 */
export function captureWriteLockDelayMs(
  attempt: number,
  limits: Pick<CaptureWriteLockBackoffLimits, "initialDelayMs" | "maxDelayMs">,
  random: () => number = Math.random
): number {
  if (!Number.isInteger(attempt) || attempt < 0) {
    throw new TypeError("capture write lock backoff attempt must be a non-negative integer");
  }
  if (!Number.isInteger(limits.initialDelayMs) || limits.initialDelayMs <= 0) {
    throw new TypeError("capture write lock initialDelayMs must be a positive integer");
  }
  if (!Number.isInteger(limits.maxDelayMs) || limits.maxDelayMs <= 0) {
    throw new TypeError("capture write lock maxDelayMs must be a positive integer");
  }
  if (limits.initialDelayMs > limits.maxDelayMs) {
    throw new TypeError("capture write lock initialDelayMs must be <= maxDelayMs");
  }
  const unit = random();
  if (typeof unit !== "number" || !Number.isFinite(unit) || unit < 0 || unit > 1) {
    throw new TypeError("capture write lock jitter source must return a finite number in [0, 1]");
  }
  const exponent = Math.min(attempt, MAX_BACKOFF_EXPONENT);
  const ceiling = Math.min(limits.maxDelayMs, limits.initialDelayMs * 2 ** exponent);
  const floor = Math.ceil(ceiling / 2);
  if (ceiling <= floor) return ceiling;
  const span = ceiling - floor;
  const offset = Math.min(span, Math.floor(unit * (span + 1)));
  return floor + offset;
}

export function normalizeCaptureWriteLockWaitMs(value: unknown, label: string): number {
  if (typeof value !== "number" || !Number.isInteger(value) || value <= 0) {
    throw new Error(`${label} must be a positive integer number of milliseconds; got ${JSON.stringify(value)}`);
  }
  return Math.min(value, MAX_CAPTURE_WRITE_LOCK_WAIT_MS);
}

function pickWaitMs(value: number | undefined, fallback: number, label: string): number {
  if (value === undefined) return fallback;
  return normalizeCaptureWriteLockWaitMs(value, label);
}

/**
 * Limits for a capture with no lock-options source — the plain daemon or an
 * inline capture. The deadline matches the pre-backoff tolerance of about 3s
 * (three probe waits of up to 1s each plus short retry sleeps), so ordinary
 * capture contention keeps that wait and still fails in bounded time.
 */
export const LEGACY_CAPTURE_WRITE_LOCK_INITIAL_DELAY_MS = 25;
export const LEGACY_CAPTURE_WRITE_LOCK_MAX_DELAY_MS = 50;
export const LEGACY_CAPTURE_WRITE_LOCK_DEADLINE_MS = 3_000;

/** Fill omitted knobs from the defaults and reject an inverted schedule. */
export function resolveCaptureWriteLockBackoffLimits(
  source: CaptureWriteLockLimitSource | undefined
): CaptureWriteLockBackoffLimits {
  // No source means a non-converge capture: keep the short legacy bounds.
  const defaults =
    source === undefined
      ? {
          initialDelayMs: LEGACY_CAPTURE_WRITE_LOCK_INITIAL_DELAY_MS,
          maxDelayMs: LEGACY_CAPTURE_WRITE_LOCK_MAX_DELAY_MS,
          deadlineMs: LEGACY_CAPTURE_WRITE_LOCK_DEADLINE_MS,
        }
      : {
          initialDelayMs: DEFAULT_CAPTURE_WRITE_LOCK_INITIAL_DELAY_MS,
          maxDelayMs: DEFAULT_CAPTURE_WRITE_LOCK_MAX_DELAY_MS,
          deadlineMs: DEFAULT_CAPTURE_WRITE_LOCK_DEADLINE_MS,
        };
  const initialDelayMs = pickWaitMs(
    source?.captureWriteLockInitialDelayMs,
    defaults.initialDelayMs,
    "captureWriteLockInitialDelayMs"
  );
  const maxDelayMs = pickWaitMs(
    source?.captureWriteLockMaxDelayMs,
    defaults.maxDelayMs,
    "captureWriteLockMaxDelayMs"
  );
  const deadlineMs = pickWaitMs(
    source?.captureWriteLockDeadlineMs,
    defaults.deadlineMs,
    "captureWriteLockDeadlineMs"
  );
  if (initialDelayMs > maxDelayMs) {
    throw new Error(
      `captureWriteLockInitialDelayMs (${initialDelayMs}) must be <= captureWriteLockMaxDelayMs (${maxDelayMs})`
    );
  }
  if (maxDelayMs > deadlineMs) {
    throw new Error(`captureWriteLockMaxDelayMs (${maxDelayMs}) must be <= captureWriteLockDeadlineMs (${deadlineMs})`);
  }
  return { initialDelayMs, maxDelayMs, deadlineMs };
}

import { isIP } from "node:net";

function normalizedIp(host: string): string {
  const value = host.trim().replace(/^\[/, "").replace(/\]\.?$/, "").replace(/\.$/, "");
  if (isIP(value) === 4) return value;
  if (isIP(value) !== 6) return "";
  return new URL(`http://[${value}]/`).hostname.slice(1, -1);
}

export function isLoopbackHost(host: string): boolean {
  const normalized = host.trim().replace(/^\[/, "").replace(/\]\.?$/, "").replace(/\.$/, "").toLowerCase();
  if (normalized === "localhost" || normalized.endsWith(".localhost")) return true;

  const ip = normalizedIp(normalized);
  if (ip === "::1") return true;
  if (isIP(ip) === 4) return ip.startsWith("127.");
  if (!ip.startsWith("::ffff:")) return false;

  const [high, low] = ip.slice("::ffff:".length).split(":");
  return Number.parseInt(high, 16) >>> 8 === 127 || (high === "0" && Number.parseInt(low, 16) >>> 8 === 127);
}

export function httpProtocolForHost(host: string, allowInsecureHttp = false): "http" | "https" {
  return isLoopbackHost(host) || allowInsecureHttp ? "http" : "https";
}

/**
 * Honest names for the gateway/task LLM chain (issue #2967).
 *
 * `FallbackLlmClient` is the primary configured path in gateway mode, not a
 * secondary recovery path. `taskLlmTimeoutMs` / `taskLlmFallback` are the
 * current keys. `localLlmTimeoutMs` / `localLlmFallback` remain documented
 * legacy aliases, read only when the corresponding new key is absent.
 */
import { coerceBool, coerceNumber } from "./connectors/coerce.js";
import { log } from "./logger.js";

const DEFAULT_TIMEOUT_MS = 180_000;
const MIN_TIMEOUT_MS = 1;
const MAX_TIMEOUT_MS = 86_400_000;

const warnedLegacy = new Set<string>();

export function resetTaskLlmLegacyWarningsForTest(): void {
  warnedLegacy.clear();
}

function warnLegacyOnce(legacyKey: string, currentKey: string, extra: string): void {
  if (warnedLegacy.has(legacyKey)) return;
  warnedLegacy.add(legacyKey);
  log.warn(
    `config: ${legacyKey} is a legacy alias for ${currentKey}; set ${currentKey} instead. ${legacyKey} still works when ${currentKey} is absent. ${extra}`,
  );
}

function parseBoundedIntegerMs(value: unknown, fallback: number): number {
  const coerced = coerceNumber(value);
  if (coerced === undefined) return fallback;
  return Math.min(MAX_TIMEOUT_MS, Math.max(MIN_TIMEOUT_MS, Math.floor(coerced)));
}

function hasOwnKey(raw: Record<string, unknown>, key: string): boolean {
  return Object.hasOwn(raw, key);
}

export interface ParsedTaskLlmConfig {
  timeoutMs: number;
  localTimeoutMs: number;
  fallback: boolean;
}

/**
 * Resolve task-LLM timeout and local→task fallback.
 *
 * New key wins when present (including present-with-`undefined`, which takes
 * the default rather than falling through to the legacy key). Legacy keys are
 * read only when the new key is absent, and warn once per process.
 */
export function parseTaskLlmConfig(cfg: Record<string, unknown>): ParsedTaskLlmConfig {
  const localTimeoutMs = hasOwnKey(cfg, "localLlmTimeoutMs")
    ? parseBoundedIntegerMs(cfg.localLlmTimeoutMs, DEFAULT_TIMEOUT_MS)
    : DEFAULT_TIMEOUT_MS;

  let timeoutMs: number;
  if (hasOwnKey(cfg, "taskLlmTimeoutMs")) {
    timeoutMs = parseBoundedIntegerMs(cfg.taskLlmTimeoutMs, DEFAULT_TIMEOUT_MS);
  } else if (hasOwnKey(cfg, "localLlmTimeoutMs")) {
    warnLegacyOnce(
      "localLlmTimeoutMs",
      "taskLlmTimeoutMs",
      "localLlmTimeoutMs remains the local-endpoint timeout; without taskLlmTimeoutMs it also sizes the gateway/task chain.",
    );
    timeoutMs = localTimeoutMs;
  } else {
    timeoutMs = DEFAULT_TIMEOUT_MS;
  }

  let fallback: boolean;
  if (hasOwnKey(cfg, "taskLlmFallback")) {
    const coerced = coerceBool(cfg.taskLlmFallback, "taskLlmFallback");
    fallback = coerced !== undefined ? coerced : true;
  } else if (hasOwnKey(cfg, "localLlmFallback")) {
    warnLegacyOnce(
      "localLlmFallback",
      "taskLlmFallback",
      "taskLlmFallback is the current name for using the gateway/task chain when the local path fails.",
    );
    fallback = cfg.localLlmFallback !== false;
  } else {
    fallback = true;
  }

  return { timeoutMs, localTimeoutMs, fallback };
}

/**
 * Extraction-pipeline liveness (issue #2151).
 *
 * A daemon's implicit extraction can fail continuously for months while
 * `/health` stays green and recall keeps serving: every individual failure is
 * logged (timeouts, fallback-no-parsed-output), but nothing aggregates them
 * into a checkable status. This module surfaces a liveness *watermark* — the
 * last successful extraction plus the current buffer backlog — and decides when
 * that watermark is stale enough to call the pipeline degraded.
 *
 * The §22 error-vs-empty principle applies at the pipeline level: "no
 * extraction succeeded for 90 days" (a non-empty buffer with a stale/absent
 * watermark) must be distinguishable from "nothing to extract" (an empty
 * buffer). Degradation therefore requires a NON-EMPTY buffer — an idle daemon
 * with nothing buffered is healthy, not degraded.
 *
 * The core decision (`evaluateExtractionLiveness`) is a pure function shared by
 * every surface (authenticated `/health`, `remnic doctor`, `remnic stats`) so
 * the verdict never diverges across code paths.
 */
import { coerceBool, coerceNumber } from "./connectors/coerce.js";
import { getExtractionLlmHealth } from "./extraction-llm-health.js";
import { log } from "./logger.js";
import type { OperatorDoctorCheck } from "./operator-doctor-types.js";
import type { PluginConfig } from "./types.js";

/** Default staleness window: 24h. A watermark older than this with a non-empty buffer is degraded. */
const DEFAULT_STALE_WINDOW_MS = 86_400_000;

export interface ExtractionLivenessConfig {
  /** Master gate. When false, liveness is never reported degraded. Default true. */
  enabled: boolean;
  /**
   * How stale the last-successful-extraction watermark may get (ms) before a
   * non-empty buffer flags the pipeline degraded. Default 24h.
   */
  staleWindowMs: number;
}

/**
 * A read-only snapshot of buffered, not-yet-extracted work. Structurally
 * satisfied by `SmartBuffer.getBufferSnapshot()` so callers can pass the live
 * buffer without this module depending on the buffer implementation.
 */
export interface ExtractionBufferSnapshot {
  bufferedSessionCount: number;
  pendingTurnCount: number;
  oldestTurnTimestamp: string | null;
  /**
   * Set by the liveness reader (never by `SmartBuffer`) when the buffer exists
   * but its snapshot read threw. An unreadable buffer is a pipeline fault, not
   * an empty queue (§22): it degrades the pipeline with a distinct reason
   * instead of masquerading as a zero-backlog (healthy) snapshot.
   */
  readFailed?: boolean;
  /** Read-failure detail, surfaced in the degraded reason when `readFailed`. */
  readError?: string;
}

export interface ExtractionBufferSource {
  getBufferSnapshot(): Promise<ExtractionBufferSnapshot>;
}

export interface ExtractionRootStats {
  extractionCount?: number;
  lastConsolidationAt?: string | null;
}

export interface ExtractionWatermarkRead {
  lastExtractionAt: string | null;
  readFailed: boolean;
  readError?: string;
  pending?: boolean;
  rootStats?: ExtractionRootStats;
}

export type ExtractionWatermarkOrStorage =
  | ExtractionWatermarkRead
  | { readMetadata(): Promise<{ lastExtractionAt?: string | null } | null> }
  | { loadMeta(): Promise<{ lastExtractionAt?: string | null }> };

export async function coerceExtractionWatermark(
  watermark: ExtractionWatermarkOrStorage,
): Promise<ExtractionWatermarkRead> {
  if (watermark && "readFailed" in watermark && typeof watermark.readFailed === "boolean") {
    return watermark as ExtractionWatermarkRead;
  }
  try {
    let lastExtractionAt: string | null = null;
    if ("loadMeta" in watermark && typeof watermark.loadMeta === "function") {
      const meta = await watermark.loadMeta();
      lastExtractionAt = meta?.lastExtractionAt ?? null;
    } else if ("readMetadata" in watermark && typeof watermark.readMetadata === "function") {
      const meta = await watermark.readMetadata();
      lastExtractionAt = meta?.lastExtractionAt ?? null;
    }
    return {
      lastExtractionAt,
      readFailed: true,
      readError: "aggregate watermark unavailable from legacy root-store-only storage argument",
    };
  } catch (error) {
    return {
      lastExtractionAt: null,
      readFailed: true,
      readError: error instanceof Error ? error.message : String(error),
    };
  }
}

/**
 * The daemon-scoped liveness payload surfaced on `/health.extraction` and in
 * doctor/stats details. Its watermark is the maximum successful extraction
 * across every distinct namespace store, matching the daemon-wide buffer scope.
 */
export interface ExtractionLivenessStatus {
  lastExtractionAt: string | null;
  bufferedSessionCount: number;
  pendingTurnCount: number;
  oldestBufferedTurnAgeMs: number | null;
  degraded: boolean;
  degradedReason: string | null;
  watermarkPending?: boolean;
  watermarkScope: "aggregate";
  /**
   * Extraction-LLM availability (issue #3140): outcome of the last extraction
   * attempt. `lastFailureReason` is non-null exactly while `llmReachable` is
   * false. Populated by the daemon-wide status readers (`/health`, doctor,
   * stats), not by the pure evaluators below.
   */
  llmReachable?: boolean;
  lastFailureReason?: string | null;
  lastFailureAt?: string | null;
}

interface ExtractionLivenessOrchestratorLike {
  config: Pick<PluginConfig, "extractionLiveness">;
  buffer?: ExtractionBufferSource;
}

/**
 * Parse the `extractionLiveness` config block. Follows the nested-block shape
 * validation used elsewhere in `config.ts` and coerces string booleans (§24:
 * CLI/JSON deliver `"false"`/`"0"` as strings, which must read as falsy).
 */
export function parseExtractionLivenessConfig(
  cfg: Record<string, unknown>,
): ExtractionLivenessConfig {
  const raw = cfg.extractionLiveness;
  if (raw !== undefined && (raw === null || typeof raw !== "object" || Array.isArray(raw))) {
    throw new Error(`extractionLiveness must be a plain object (got ${JSON.stringify(raw)})`);
  }
  const block = (raw ?? {}) as Record<string, unknown>;
  return {
    // `?? true` keeps the default on when the key is absent while honoring
    // explicit "false"/"0"/false opt-outs (coerceBool handles the string forms).
    enabled: coerceBool(block.enabled) ?? true,
    staleWindowMs: parseStaleWindowMs(block.staleWindowMs),
  };
}

/**
 * Parse `extractionLiveness.staleWindowMs`. Absent (`undefined`) → the 24h
 * default; any PRESENT value (including an explicit `null`) must coerce to a
 * positive INTEGER of milliseconds, else THROW. A fractional or non-positive
 * value ("0.5" would floor to 0, making every backlog instantly stale; 1.9 would
 * floor to 1) is rejected, never floored/reinterpreted (§1/§17/§39). Mirrors
 * config.ts's `parseIntegerInClosedRange` (round 9 finding 1): only an absent key
 * falls back; an explicit `null` is invalid input, not "use the default".
 * Inlined rather than imported because config.ts already imports this module
 * (importing back would be circular), the same reason `recall-concurrency-config.ts`
 * inlines its numeric validation.
 */
function parseStaleWindowMs(value: unknown): number {
  // Only an absent key (undefined) falls back to the default; an explicit `null`
  // is invalid input and proceeds to validation → throw (mirrors
  // parseIntegerInClosedRange, round 9 finding 1).
  if (value === undefined) return DEFAULT_STALE_WINDOW_MS;
  const coerced = coerceNumber(value);
  if (coerced === undefined || !Number.isFinite(coerced) || !Number.isInteger(coerced) || coerced < 1) {
    throw new Error(
      `extractionLiveness.staleWindowMs must be an integer greater than or equal to 1; got ${JSON.stringify(value)}`,
    );
  }
  return coerced;
}

/** Milliseconds between `timestamp` and `nowMs`, clamped at 0; null when unparsable/absent. */
function ageMsFrom(timestamp: string | null, nowMs: number): number | null {
  if (typeof timestamp !== "string") return null;
  const parsed = Date.parse(timestamp);
  if (!Number.isFinite(parsed)) return null;
  return Math.max(0, nowMs - parsed);
}

/** Compact human-readable duration ("3d", "5h", "12m", "45s") for logs and CLI output. */
export function formatAgeMs(ms: number): string {
  const s = Math.max(0, Math.floor(ms / 1000));
  if (s >= 86_400) return `${Math.floor(s / 86_400)}d`;
  if (s >= 3_600) return `${Math.floor(s / 3_600)}h`;
  if (s >= 60) return `${Math.floor(s / 60)}m`;
  return `${s}s`;
}

/**
 * Pure liveness verdict. Degraded when the feature is enabled AND any of: the
 * last-extraction watermark could not be READ (a storage fault, §22), the buffer
 * read failed (a pipeline fault, §22), or the buffer is non-empty and the
 * watermark is absent or stale. Each cause yields a DISTINCT reason so an
 * operator can tell a meta-read failure from a buffer-read failure from a
 * pipeline that has genuinely never extracted.
 *
 * Staleness uses a half-open freshness window (§23): an extraction is fresh
 * while its age is in `[0, staleWindowMs)`, so an age of EXACTLY `staleWindowMs`
 * is stale (the upper bound on "fresh" is exclusive). A null/unparsable watermark
 * means "never succeeded" and is treated as stale — as is a FUTURE watermark (a
 * clock-skewed or corrupt timestamp ahead of now must not read as a fresh
 * extraction and hide a real backlog stall).
 */
export function evaluateExtractionLiveness(input: {
  config: ExtractionLivenessConfig;
  lastExtractionAt: string | null;
  snapshot: ExtractionBufferSnapshot;
  nowMs: number;
  metaReadFailed?: boolean;
  metaReadError?: string;
  watermarkPending?: boolean;
}): ExtractionLivenessStatus {
  const { config, lastExtractionAt, snapshot, nowMs } = input;
  const lastMs = lastExtractionAt !== null ? Date.parse(lastExtractionAt) : Number.NaN;
  const hasWatermark = Number.isFinite(lastMs);
  const ageMs = nowMs - lastMs;
  // A future watermark (negative age) is clock-skewed or corrupt data, not a
  // fresh extraction: treat it as stale so a real backlog stall is not hidden.
  const stale = !hasWatermark || ageMs < 0 || ageMs >= config.staleWindowMs;
  const hasBacklog = snapshot.bufferedSessionCount > 0;
  // A watermark or buffer that cannot be READ is a fault, not an empty queue
  // (§22): a storage/pipeline outage must not read as healthy, and must stay
  // distinct from a pipeline that has genuinely never extracted.
  const metaReadFailed = input.metaReadFailed === true;
  const watermarkPending = input.watermarkPending === true;
  const readFailed = snapshot.readFailed === true;
  const degraded =
    config.enabled && (metaReadFailed || readFailed || (!watermarkPending && hasBacklog && stale));

  let degradedReason: string | null = null;
  if (degraded) {
    if (metaReadFailed) {
      degradedReason = `extraction watermark unreadable: ${input.metaReadError ?? "meta read failed"}`;
    } else if (readFailed) {
      degradedReason = `extraction buffer unreadable: ${snapshot.readError ?? "buffer snapshot read failed"}`;
    } else {
      const watermark = hasWatermark
        ? `last succeeded ${formatAgeMs(nowMs - lastMs)} ago`
        : "no successful extraction on record";
      degradedReason =
        `${watermark}; ${snapshot.bufferedSessionCount} buffered session(s), ` +
        `${snapshot.pendingTurnCount} turn(s) pending extraction`;
    }
  }

  return {
    lastExtractionAt,
    bufferedSessionCount: snapshot.bufferedSessionCount,
    pendingTurnCount: snapshot.pendingTurnCount,
    oldestBufferedTurnAgeMs: ageMsFrom(snapshot.oldestTurnTimestamp, nowMs),
    degraded,
    degradedReason,
    ...(watermarkPending ? { watermarkPending: true } : {}),
    watermarkScope: "aggregate",
  };
}

const EMPTY_SNAPSHOT: ExtractionBufferSnapshot = {
  bufferedSessionCount: 0,
  pendingTurnCount: 0,
  oldestTurnTimestamp: null,
};

/**
 * Read a buffer snapshot without throwing. An ABSENT buffer degrades to an empty
 * (healthy) snapshot — some service constructions have no orchestrator buffer. A
 * buffer that EXISTS but whose read throws yields a `readFailed` snapshot so the
 * verdict can distinguish a pipeline fault from an empty queue (§22).
 */
async function readBufferSnapshot(
  buffer: ExtractionBufferSource | undefined,
): Promise<ExtractionBufferSnapshot> {
  if (!buffer || typeof buffer.getBufferSnapshot !== "function") return EMPTY_SNAPSHOT;
  try {
    return await buffer.getBufferSnapshot();
  } catch (err) {
    return {
      ...EMPTY_SNAPSHOT,
      readFailed: true,
      readError: err instanceof Error ? err.message : String(err),
    };
  }
}

/**
 * Gather the liveness status from an aggregate watermark read and an optional
 * buffer. A read failure on either side is surfaced as a degraded status with a
 * distinct reason rather than swallowed into a healthy-looking verdict.
 */
export async function gatherExtractionLivenessStatus(input: {
  config: ExtractionLivenessConfig;
  watermark: ExtractionWatermarkOrStorage;
  buffer: ExtractionBufferSource | undefined;
  nowMs: number;
}): Promise<ExtractionLivenessStatus> {
  const { config, buffer, nowMs } = input;
  const watermarkRead = await coerceExtractionWatermark(input.watermark);
  const snapshot = await readBufferSnapshot(buffer);
  return evaluateExtractionLiveness({
    config,
    lastExtractionAt: watermarkRead.lastExtractionAt,
    snapshot,
    nowMs,
    metaReadFailed: watermarkRead.readFailed,
    metaReadError: watermarkRead.readError,
    watermarkPending: watermarkRead.pending,
  });
}

/**
 * Aggregated-WARN throttle (issue #2151): emit at most ONE warning per
 * staleness window while degraded — not one line per failed extraction attempt.
 * State is instance-scoped (held by the owning service), never a module global
 * (§5), so multiple service instances throttle independently.
 */
export class ExtractionLivenessWarnThrottle {
  private lastWarnAtMs: number | null = null;

  /** Warn if degraded and outside the throttle window; returns whether a WARN was emitted. */
  maybeWarn(status: ExtractionLivenessStatus, staleWindowMs: number, nowMs: number): boolean {
    if (!status.degraded) {
      // Recovered (or never degraded): reset so a fresh episode warns at once.
      this.lastWarnAtMs = null;
      return false;
    }
    if (this.lastWarnAtMs !== null && nowMs - this.lastWarnAtMs < staleWindowMs) return false;
    this.lastWarnAtMs = nowMs;
    log.warn(
      `extraction pipeline liveness degraded: ${status.degradedReason ?? "buffered turns are not being extracted"}`,
    );
    return true;
  }
}

/**
 * Normalize the `extractionLiveness` block at the read boundary. `parseConfig`
 * always populates it, but a host adapter, an older persisted config, or a
 * hand-built `PluginConfig` can hand us an absent, partial, or loosely-typed
 * block - and every liveness surface (/health, doctor, stats) must degrade to
 * the documented default (enabled, 24h window) rather than throw. Both fields
 * are coerced with the same rules as `parseExtractionLivenessConfig` (§24:
 * `"false"`/`"0"` read as falsy; a numeric string like `"5000"` parses), except a
 * present but non-integer or non-positive `staleWindowMs` falls back to the
 * default here rather than throwing.
 */
export function resolveExtractionLivenessConfig(
  block: { enabled?: unknown; staleWindowMs?: unknown } | undefined,
): ExtractionLivenessConfig {
  const staleWindowMs = coerceNumber(block?.staleWindowMs);
  return {
    enabled: coerceBool(block?.enabled) ?? true,
    staleWindowMs:
      staleWindowMs !== undefined && Number.isInteger(staleWindowMs) && staleWindowMs >= 1
        ? staleWindowMs
        : DEFAULT_STALE_WINDOW_MS,
  };
}

/**
 * Compute the daemon-wide liveness status for the authenticated `/health`
 * payload and emit the throttled aggregate warning.
 */
export async function computeExtractionLivenessStatus(
  orchestrator: ExtractionLivenessOrchestratorLike,
  watermark: ExtractionWatermarkOrStorage,
  throttle?: ExtractionLivenessWarnThrottle,
  nowMs: number = Date.now(),
): Promise<ExtractionLivenessStatus> {
  const config = resolveExtractionLivenessConfig(orchestrator.config.extractionLiveness);
  const status = await gatherExtractionLivenessStatus({
    config,
    watermark,
    buffer: orchestrator.buffer,
    nowMs,
  });
  throttle?.maybeWarn(status, config.staleWindowMs, nowMs);
  // Extraction-LLM availability (#3140): a silent no_models / LLM-unreachable
  // outage must be visible on /health (and doctor/stats) without debug logs.
  return { ...status, ...getExtractionLlmHealth() };
}

/**
 * `remnic doctor` check for extraction-pipeline liveness. Status `warn` when
 * degraded (with a remediation hint), `ok` otherwise.
 */
export async function summarizeExtractionLiveness(
  config: Pick<PluginConfig, "extractionLiveness">,
  watermark: ExtractionWatermarkOrStorage,
  buffer?: ExtractionBufferSource,
  nowMs: number = Date.now(),
): Promise<OperatorDoctorCheck> {
  const livenessConfig = resolveExtractionLivenessConfig(config.extractionLiveness);
  const status = await gatherExtractionLivenessStatus({
    config: livenessConfig,
    watermark,
    buffer,
    nowMs,
  });
  const scopeNote = ` Watermark scope: ${status.watermarkScope}.`;
  const summary =
    (status.degraded
      ? `Extraction pipeline degraded: ${status.degradedReason}.`
      : `Extraction pipeline healthy: last extraction ${status.lastExtractionAt ?? "never"}, ` +
        `${status.bufferedSessionCount} buffered session(s), ${status.pendingTurnCount} turn(s) pending` +
        `${livenessConfig.enabled ? "" : " (liveness check disabled)"}.`) + scopeNote;
  return {
    key: "extraction_liveness",
    status: status.degraded ? "warn" : "ok",
    summary,
    remediation: status.degraded
      ? "Extraction has stalled while turns are buffered. Inspect daemon logs for extraction " +
        "timeouts or fallback-no-parsed-output errors, verify the extraction model/provider is " +
        "reachable, then force a flush (e.g. `remnic flush`)."
      : undefined,
    details: { ...status, staleWindowMs: livenessConfig.staleWindowMs, enabled: livenessConfig.enabled },
  };
}

/**
 * Lines for `remnic stats`: the aggregate extraction watermark, root metadata
 * counters, buffer backlog, and liveness verdict. Root counter failures render
 * those counters unavailable; the injected aggregate read alone determines
 * watermark liveness so stats cannot diverge from health and doctor.
 */
export async function renderExtractionLivenessStats(
  orchestrator: ExtractionLivenessOrchestratorLike,
  watermark: ExtractionWatermarkRead,
  nowMs: number = Date.now(),
): Promise<string[]> {
  const status = evaluateExtractionLiveness({
    config: resolveExtractionLivenessConfig(orchestrator.config.extractionLiveness),
    lastExtractionAt: watermark.lastExtractionAt,
    snapshot: await readBufferSnapshot(orchestrator.buffer),
    nowMs,
    metaReadFailed: watermark.readFailed,
    metaReadError: watermark.readError,
    watermarkPending: watermark.pending,
  });
  const oldestAge =
    status.oldestBufferedTurnAgeMs !== null ? formatAgeMs(status.oldestBufferedTurnAgeMs) : "n/a";
  const rootStats = watermark.rootStats;
  const watermarkDisplay = watermark.readFailed
    ? "unavailable"
    : watermark.pending
      ? "pending"
      : status.lastExtractionAt ?? "never";
  return [
    `Extractions: ${rootStats?.extractionCount ?? "unavailable"}`,
    `Last extraction: ${watermarkDisplay}`,
    `Last consolidation: ${rootStats ? rootStats.lastConsolidationAt ?? "never" : "unavailable"}`,
    `Buffered sessions: ${status.bufferedSessionCount} (${status.pendingTurnCount} turns pending)`,
    `Oldest buffered turn age: ${oldestAge}`,
    `Extraction watermark scope: ${status.watermarkScope}`,
    `Extraction liveness: ${status.degraded ? `DEGRADED — ${status.degradedReason}` : "ok"}`,
  ];
}

import type { AgentAccessAuthToken, SecretRef } from "./types.js";

/**
 * Resolve `agentAccessHttp.authToken` (issue #757).
 *
 * Two shapes are accepted:
 *
 *   1. Plain string — returned unchanged. This is the only shape supported
 *      in standalone Remnic; it preserves backward compatibility with every
 *      pre-#757 config.
 *
 *   2. SecretRef-like object (`{source, provider?, id?, command?, ...}`) —
 *      resolved only through a resolver supplied by the host adapter. Core
 *      stays host-agnostic and never scans OpenClaw, Hermes, or any other
 *      runtime directly.
 *
 * Resolution flow for SecretRef objects:
 *
 *   - Plain strings short-circuit before any host work.
 *   - Host adapters pass their native SecretRef resolver in `options`.
 *   - If no resolver is provided, throw a clear, actionable error rather
 *     than silently leaving the bridge open or starting with no auth.
 *
 * Lessons baked in from PRs #316–#319:
 *
 *   - Successful resolutions are cached for the process lifetime; failures
 *     are not cached so transient issues (Keychain unlocked late, agent
 *     restarts) recover automatically.
 */

export type ResolveSecretRefFn = (
  ref: SecretRef,
  context?: unknown,
) => Promise<string | undefined> | string | undefined;

type ResolveAgentAccessAuthTokenOptions = {
  resolveSecretRef?: ResolveSecretRefFn | null;
};

let resolvedCache = new WeakMap<ResolveSecretRefFn, Map<string, string>>();

/**
 * SecretRef objects are stable per (source, provider, id, command) tuple.
 * Sort keys before serializing so semantically-identical refs hit the same
 * cache slot regardless of authoring order (Lesson 38 in CLAUDE.md).
 */
function cacheKeyForSecretRef(ref: SecretRef): string {
  const sortedKeys = Object.keys(ref).sort();
  const stable: Record<string, unknown> = {};
  for (const key of sortedKeys) {
    stable[key] = ref[key];
  }
  return JSON.stringify(stable);
}

function isPlainObject(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

/**
 * Resolve an `agentAccessHttp.authToken` value to a literal bearer string.
 *
 * @returns the resolved string, or `undefined` if input was undefined/empty.
 * @throws if the input is a SecretRef and no resolver is provided, if the
 *         resolver returns no value, or if the input shape is malformed.
 */
export async function resolveAgentAccessAuthToken(
  value: AgentAccessAuthToken | undefined,
  options: ResolveAgentAccessAuthTokenOptions = {},
): Promise<string | undefined> {
  if (value === undefined || value === null) return undefined;

  if (typeof value === "string") {
    const trimmed = value.trim();
    return trimmed.length > 0 ? trimmed : undefined;
  }

  if (!isPlainObject(value)) {
    throw new Error(
      "unsupported SecretRef shape for agentAccessHttp.authToken — " +
        "expected a string or an object with a `source` field " +
        "(see https://github.com/joshuaswarren/remnic/issues/757)",
    );
  }

  const ref = value as SecretRef;
  if (typeof ref.source !== "string" || ref.source.trim().length === 0) {
    throw new Error(
      "unsupported SecretRef shape for agentAccessHttp.authToken — " +
        "missing required `source` field " +
        "(see https://github.com/joshuaswarren/remnic/issues/757)",
    );
  }

  const resolver = options.resolveSecretRef ?? null;
  if (!resolver) {
    throw new Error(
      `cannot resolve agentAccessHttp.authToken SecretRef (source="${ref.source}") — ` +
        "a SecretRef resolver was not provided. Use a literal string or " +
        "${ENV_VAR} expansion in standalone Remnic, or have the host adapter " +
        "resolve SecretRef objects through its native secret resolver " +
        "(see https://github.com/joshuaswarren/remnic/issues/757).",
    );
  }

  const cacheKey = cacheKeyForSecretRef(ref);
  let resolverCache = resolvedCache.get(resolver);
  if (!resolverCache) {
    resolverCache = new Map<string, string>();
    resolvedCache.set(resolver, resolverCache);
  }
  const cached = resolverCache.get(cacheKey);
  if (cached !== undefined) return cached;

  let resolved: string | undefined;
  try {
    const out = await resolver(ref);
    if (typeof out === "string") {
      const trimmed = out.trim();
      if (trimmed.length > 0) resolved = trimmed;
    }
  } catch (err) {
    throw new Error(
      `failed to resolve agentAccessHttp.authToken SecretRef (source="${ref.source}"): ${
        err instanceof Error ? err.message : String(err)
      }`,
    );
  }

  if (!resolved) {
    throw new Error(
      `agentAccessHttp.authToken SecretRef resolved to empty value (source="${ref.source}", provider="${
        ref.provider ?? ""
      }") — refusing to start the HTTP bridge with an empty bearer token.`,
    );
  }

  resolverCache.set(cacheKey, resolved);
  return resolved;
}

/**
 * Returns true if the value is a SecretRef object (issue #757). Useful for
 * surfaces (CLI flags, doctor checks) that want to render a redacted
 * placeholder instead of leaking the unresolved object shape.
 */
export function isAgentAccessSecretRef(value: unknown): value is SecretRef {
  if (!isPlainObject(value)) return false;
  const ref = value as Record<string, unknown>;
  return typeof ref.source === "string" && ref.source.trim().length > 0;
}

/** Test/operations hook: drop the cache and force resolver rediscovery. */
export function clearAuthTokenSecretCache(): void {
  resolvedCache = new WeakMap<ResolveSecretRefFn, Map<string, string>>();
}

/**
 * Resolve a host SecretRef resolver, preferring an explicitly supplied one over
 * the lazy loader.
 *
 * Shared by every CLI command that authenticates with a SecretRef — `access
 * serve` and `doctor` (replica peer tokens, issue #2149) — so the two cannot
 * drift. Structurally typed rather than importing the CLI's options type, which
 * would invert the dependency.
 */
export async function loadHostSecretRefResolver(options: {
  resolveSecretRef?: ResolveSecretRefFn | null;
  loadResolveSecretRef?: () =>
    | Promise<ResolveSecretRefFn | null | undefined>
    | ResolveSecretRefFn
    | null
    | undefined;
}): Promise<ResolveSecretRefFn | null | undefined> {
  if (options.resolveSecretRef) return options.resolveSecretRef;
  if (!options.loadResolveSecretRef) return null;
  try {
    return await options.loadResolveSecretRef();
  } catch {
    // A host whose lazy loader throws means "no resolver available" — not
    // "abort the caller". `doctor` must still run its unrelated checks and let
    // the replica check report token_error per affected peer (round 9, codex).
    return null;
  }
}

/**
 * Adapt a host's lazily-loaded SecretRef resolver into the eager
 * `ResolveSecretRefFn` that `EngramAccessService` expects, so replica peer
 * tokens resolve at poll time (issue #2149).
 */
export function hostSecretRefResolver(options: Parameters<typeof loadHostSecretRefResolver>[0]): ResolveSecretRefFn {
  return (ref, context) => loadHostSecretRefResolver(options).then((resolve) => resolve?.(ref, context));
}

/**
 * skills-registry.ts
 *
 * Built-in Remnic procedural memory skills — the canonical SKILL.md sources
 * shipped with the monorepo. Consumers (e.g. the Codex materializer in #378)
 * read this registry to discover which skills to materialize into
 * `~/.codex/memories/skills/<slug>/SKILL.md`.
 *
 * This module is intentionally free of Codex/Claude Code host coupling —
 * it only exposes the static metadata each host needs.
 */

import { fileURLToPath } from "node:url";
import { statSync } from "node:fs";
import { dirname, resolve } from "node:path";

/**
 * A single procedural-memory skill source that Remnic ships.
 *
 * - `slug` is the canonical folder name under `skills/` and the file on disk
 *   must live at `<pluginRoot>/skills/<slug>/SKILL.md`.
 * - `staticPath`, when set, points at a pre-authored SKILL.md on disk.
 * - `generator`, when set, produces a SKILL.md body at materialization time.
 *   Exactly one of `staticPath` or `generator` should be provided.
 * - `disableModelInvocation` mirrors the `disable-model-invocation` frontmatter
 *   key and indicates a skill that writes or mutates state and therefore
 *   should not be auto-invoked by a model without explicit opt-in.
 */
export interface RemnicSkillSource {
  slug: string;
  staticPath?: string;
  generator?: () => Promise<string>;
  disableModelInvocation: boolean;
}

/**
 * Validate a Remnic skill slug. Rules:
 *
 * - lowercase letters, digits, and `-` only
 * - must start with a letter or digit
 * - 1–64 characters
 *
 * This is the same shape the Codex skills directory expects.
 */
export function isValidSkillSlug(slug: string): boolean {
  // Must start with alphanumeric; each dash must be followed by alphanumeric
  // (no trailing dashes, no consecutive dashes); 1–64 characters total.
  return /^[a-z0-9](?:[a-z0-9]|-(?=[a-z0-9])){0,63}$/.test(slug);
}

