export interface ExtractionSourceGroundingOptions {
  sourceGrounding: boolean;
  anchorTemporalExpressions: boolean;
  spanMode?: "off" | "shadow" | "on";
  /** Rewrite applied to the source before this stage, so a verbatim quote can still be located in it. */
  quoteTransform?: (quote: string) => string;
}

export function applyExtractionSourceGrounding(
  result: ExtractionResult,
  sourceText: string,
  assertionSourceText: string = sourceText,
  roleAssertionSources: ExtractionGroundingRoleSources | undefined,
  messageTimestamp: Date | undefined,
  options: ExtractionSourceGroundingOptions,
): ExtractionResult {
  if (!options.sourceGrounding) return result;
  const anchorSource = (source: string): string =>
    options.anchorTemporalExpressions
      ? anchorTemporalExpressions(source, messageTimestamp ?? new Date())
      : source;
  const anchoredRoleSources = roleAssertionSources === undefined
    ? undefined
    : {
      profile: roleAssertionSources.profile === undefined
        ? undefined
        : anchorSource(roleAssertionSources.profile),
      identity: roleAssertionSources.identity === undefined
        ? undefined
        : anchorSource(roleAssertionSources.identity),
    };
  return filterExtractionResultBySource(
    result,
    anchorSource(sourceText),
    anchorSource(assertionSourceText),
    anchoredRoleSources,
    options.anchorTemporalExpressions ? anchorSource : undefined,
    options.spanMode ?? "off",
    options.anchorTemporalExpressions
      ? (quote) => anchorSource(options.quoteTransform?.(quote) ?? quote)
      : undefined,
  );
}

export interface ExtractionGroundingRoleSources {
  profile?: string;
  identity?: string;
}



interface GroundingCopularClaim {
  subject: string;
  predicate: string;
}

function groundingCopularClaim(text: string): GroundingCopularClaim | undefined {
  const lexemes = groundingLexemes(text);
  const copulaIndex = lexemes.findIndex(({ token }) => GROUNDING_COPULAR_FORMS.has(token));
  if (copulaIndex <= 0) return undefined;

  let subjectIndex = copulaIndex - 1;
  while (
    subjectIndex >= 0
    && GROUNDING_AUXILIARY_TOKENS.has(lexemes[subjectIndex]!.token)
  ) {
    subjectIndex -= 1;
  }
  const subjectLexeme = lexemes[subjectIndex];
  const predicateLexeme = lexemes
    .slice(copulaIndex + 1)
    .find(({ token }) => GROUNDING_STOPWORDS[token] !== true);
  if (subjectLexeme === undefined || predicateLexeme === undefined) return undefined;

  return {
    subject: stemToken(subjectLexeme.token, subjectLexeme.preserveTerminalS, true),
    predicate: stemToken(predicateLexeme.token, predicateLexeme.preserveTerminalS, true),
  };
}

function hasCopularPredicateEvidence(candidate: string, source: string): boolean {
  const candidateClaim = groundingCopularClaim(candidate);
  if (candidateClaim === undefined) return true;
  const sourceClaim = groundingCopularClaim(source);
  return sourceClaim !== undefined
    && areGroundingTokensCompatible(candidateClaim.subject, sourceClaim.subject)
    && areGroundingTokensCompatible(candidateClaim.predicate, sourceClaim.predicate);
}
const GROUNDING_ALIGNMENT_MODIFIERS = new Set([
  "actively",
  "again",
  "already",
  "currently",
  "eventually",
  "finally",
  "generally",
  "mainly",
  "newly",
  "now",
  "often",
  "previously",
  "primarily",
  "quickly",
  "recently",
  "repeatedly",
  "simply",
  "slowly",
  "sometimes",
  "still",
  "successfully",
  "typically",
  "usually",
]);

function isGroundingAlignmentModifier(token: string): boolean {
  return GROUNDING_ALIGNMENT_MODIFIERS.has(token);
}

function groundingSubjectTokenSequence(text: string): string[] {
  const lexemes = groundingLexemes(text)
    .filter(({ token }) => GROUNDING_STOPWORDS[token] !== true);
  const predicateIndex = lexemes.findIndex(({ isPredicate }) => isPredicate);
  if (predicateIndex < 1) return [];
  return lexemes
    .slice(0, predicateIndex)
    .filter(({ token }) => !isGroundingAlignmentModifier(token) && !token.endsWith("ly"))
    .map(({ token, preserveTerminalS }) => stemToken(token, preserveTerminalS, true));
}


function hasAlignedSubjectPredicateOverlap(candidate: string, source: string): boolean {
  const candidateTokens = normalizedGroundingAlignmentTokenSequence(candidate);
  const sourceTokens = normalizedGroundingAlignmentTokenSequence(source);
  const candidateSubjectTokens = groundingSubjectTokenSequence(candidate);
  const sourceSubjectTokens = groundingSubjectTokenSequence(source);
  const hasCorrectionReordering = /\b(?:rather\s+than|instead\s+of)\b/iu.test(candidate)
    && /\b(?:not|rather\s+than|instead\s+of)\b/iu.test(source);
  if (
    candidateSubjectTokens.length > 0
    && sourceSubjectTokens.length > 0
    && !hasCorrectionReordering
    && (
      candidateSubjectTokens.length !== sourceSubjectTokens.length
      || candidateSubjectTokens.some(
        (token, index) => !areGroundingTokensCompatible(token, sourceSubjectTokens[index]!),
      )
    )
  ) {
    return false;
  }
  if (candidateTokens.length < 3 || sourceTokens.length < 3) {
    return hasCopularPredicateEvidence(candidate, source);
  }

  const candidateSubject = candidateTokens[0];
  if (candidateSubject === undefined) return false;
  for (let sourceSubjectIndex = 0; sourceSubjectIndex < sourceTokens.length; sourceSubjectIndex += 1) {
    if (!areGroundingTokensCompatible(candidateSubject, sourceTokens[sourceSubjectIndex]!)) continue;
    let sourceCursor = sourceSubjectIndex + 1;
    let foundAlignedToken = false;
    let aligned = true;
    for (let candidateIndex = 1; candidateIndex < candidateTokens.length; candidateIndex += 1) {
      const candidateToken = candidateTokens[candidateIndex]!;
      const sourceIndex = sourceTokens.findIndex(
        (sourceToken, index) =>
          index >= sourceCursor && areGroundingTokensCompatible(candidateToken, sourceToken),
      );
      if (sourceIndex === -1) {
        if (hasCorrectionReordering) continue;
        aligned = false;
        break;
      }
      foundAlignedToken = true;
      const candidateNext = candidateTokens[candidateIndex + 1];
      const sourceNext = sourceTokens[sourceIndex + 1];
      if (
        candidateNext !== undefined
        && sourceNext !== undefined
        && !hasCorrectionReordering
        && !areGroundingTokensCompatible(candidateNext, sourceNext)
        && !isGroundingAlignmentModifier(sourceNext)
      ) {
        aligned = false;
        break;
      }
      sourceCursor = sourceIndex + 1;
    }
    if (aligned && foundAlignedToken) return true;
  }
  return false;
}

function omitsSourceDisjunction(candidate: string, source: string): boolean {
  if (!/\bor\b/iu.test(source) || /\bor\b/iu.test(candidate)) return false;
  const candidateTokens = normalizedGroundingTokenSequence(candidate);
  return splitGroundingClauses([source], true).some((sourceSpan) => {
    const sourceSpanTokens = normalizedGroundingTokenSequence(sourceSpan);
    return candidateTokens.length === sourceSpanTokens.length
      && candidateTokens.every(
        (token, index) => areGroundingTokensCompatible(token, sourceSpanTokens[index]!),
      );
  });
}

function groundedTokenScore(
  candidate: string,
  source: string,
  requireAlignedArguments = true,
  requireAllCandidateTokensGrounded = true,
): number {
  const scriptAwareScore = spacelessScriptGroundedTokenScore(candidate, source);
  if (scriptAwareScore !== null) return scriptAwareScore;
  const candidateTokens = tokenize(candidate);
  if (candidateTokens.size === 0) return 0;
  const sourceTokens = tokenize(source);
  const allowCorrectionReordering = /\b(?:rather\s+than|instead\s+of)\b/iu.test(candidate);
  let sharedTokens = 0;
  let allCandidateTokensGrounded = true;
  for (const token of candidateTokens) {
    if ([...sourceTokens].some((sourceToken) => areGroundingTokensCompatible(token, sourceToken))) {
      sharedTokens += 1;
    } else if (!allowCorrectionReordering && token !== "rather" && token !== "instead") {
      allCandidateTokensGrounded = false;
    }
  }
  if (
    (requireAllCandidateTokensGrounded && !allCandidateTokensGrounded)
    || sharedTokens < GROUNDING_MIN_SHARED_TOKENS
    || sharedTokens / candidateTokens.size < GROUNDING_MIN_COVERAGE
  ) {
    return 0;
  }
  if (requireAlignedArguments && !hasAlignedSubjectPredicateOverlap(candidate, source)) return 0;
  return sharedTokens / candidateTokens.size;
}

function candidateClauses(candidate: string): string[] {
  return sourceSentences(candidate).flatMap((sentence) =>
    /\bor\b/iu.test(sentence) ? [sentence] : splitGroundingClauses([sentence]));
}

function isSourceGroundedClause(
  candidate: string,
  source: string,
  includeInterrogativeSource = false,
): boolean {
  let bestSupportedScore = 0;
  let bestContradictedScore = 0;
  const sentences = sourceSentences(source);
  for (let index = 0; index < sentences.length; index += 1) {
    const sentence = sentences[index];
    if (isYesNoAnswer(sentence)) {
      const precedingSentence = sentences[index - 1];
      const answerToken = tokenSequence(sentence)[0];
      const contradictoryPolarity = precedingSentence !== undefined
        ? hasContradictoryPolarity(candidate, precedingSentence)
        : false;
      if (
        precedingSentence !== undefined
        && isInterrogativeSourceSentence(precedingSentence)
        && !omitsSourceDisjunction(candidate, precedingSentence)
        && groundedTokenScore(candidate, precedingSentence) === 1
        && (
          (answerToken === "yes" && !contradictoryPolarity)
          || (answerToken === "no" && contradictoryPolarity)
        )
      ) {
        return true;
      }
      continue;
    }
    const sentenceText = normalizeForExactMatch(sentence);
    const isExplanatoryLabel = sentenceText.startsWith(`${normalizeForExactMatch(candidate)}:`)
      && !sentence.trim().endsWith("?");
    if (!includeInterrogativeSource && isInterrogativeSourceSentence(sentence) && !isExplanatoryLabel) {
      continue;
    }
    if (omitsSourceDisjunction(candidate, sentence)) continue;
    const sourceSpans = /\b(?:rather\s+than|instead\s+of)\b/iu.test(candidate)
      ? [sentence]
      : splitGroundingClauses([sentence], true);
    for (const sourceSpan of sourceSpans) {
      const sourceSpanText = normalizeForExactMatch(sourceSpan);
      if (containsExactTokenSequence(candidate, sourceSpanText)) {
        if (!hasContradictoryPolarity(candidate, sourceSpan)) return true;
        bestContradictedScore = Math.max(bestContradictedScore, 1);
        continue;
      }
      const score = groundedTokenScore(
        candidate,
        sourceSpan,
        !includeInterrogativeSource,
        !includeInterrogativeSource,
      );
      if (score === 0) continue;
      if (hasContradictoryPolarity(candidate, sourceSpan)) {
        bestContradictedScore = Math.max(bestContradictedScore, score);
      } else {
        bestSupportedScore = Math.max(bestSupportedScore, score);
      }
    }
  }
  return bestSupportedScore > bestContradictedScore;
}
function isSourceGrounded(
  candidate: string,
  source: string,
  includeInterrogativeSource = false,
): boolean {
  const candidateText = normalizeForExactMatch(candidate);
  const sourceText = source.normalize("NFKC").trim();
  if (candidateText.length === 0 || sourceText.length === 0) return false;
  const hasSupportedExactMatch = sourceSentences(sourceText).some((sentence) => {
    const sentenceText = normalizeForExactMatch(sentence);
    const isExplanatoryLabel = sentenceText.startsWith(`${candidateText}:`)
      && !sentence.trim().endsWith("?");
    if (!includeInterrogativeSource && isInterrogativeSourceSentence(sentence) && !isExplanatoryLabel) return false;
    if (omitsSourceDisjunction(candidateText, sentenceText)) return false;
    return containsExactTokenSequence(candidateText, sentenceText)
      && !hasContradictoryPolarity(candidateText, sentenceText);
  });
  if (hasSupportedExactMatch) return true;

  const clauses = candidateClauses(candidate);
  if (clauses.length > 1) {
    return clauses.every((clause) =>
      isSourceGroundedClause(clause, sourceText, includeInterrogativeSource));
  }
  return isSourceGroundedClause(candidate, sourceText, includeInterrogativeSource);
}

function buildEntitySupportSource(name: string, source: string): string {
  const nameTokens = normalizedEntityIdentifierTokens(name);
  if (nameTokens.length === 0) return "";
  return sourceSentences(source)
    .filter((sentence) => {
      const sentenceTokens = groundingLexemes(sentence)
        .filter(({ token }) => GROUNDING_STOPWORDS[token] !== true)
        .map(({ token, preserveTerminalS }) => stemToken(token, preserveTerminalS));
      return containsContiguousGroundingTokens(nameTokens, sentenceTokens);
    })
    .join(" ");
}

function hasGroundedPredicateAnchor(candidate: string, sentence: string): boolean {
  const candidateTokens = normalizedGroundingTokenSequence(candidate);
  const sourceTokens = normalizedGroundingTokenSequence(sentence);
  const comparableCandidateTokens = GROUNDING_ROLE_SUBJECT_TOKENS.has(
    (candidateTokens[0] ?? "").replace(/^[\u0000\u0001]/u, ""),
  )
    ? candidateTokens.slice(1)
    : candidateTokens;
  if (comparableCandidateTokens.length < 2) return false;
  const subjectToken = comparableCandidateTokens[0];
  if (
    subjectToken === undefined
    || !sourceTokens.some((sourceToken) => areGroundingTokensCompatible(subjectToken, sourceToken))
  ) {
    return false;
  }
  const candidatePredicateTokens = comparableCandidateTokens.slice(1);
  const sharedPredicateTokens = candidatePredicateTokens.filter((token) =>
    sourceTokens.some((sourceToken) => areGroundingTokensCompatible(token, sourceToken)));
  const requiredSharedTokens = Math.min(2, candidatePredicateTokens.length);
  return sharedPredicateTokens.length >= requiredSharedTokens;
}
function hasGroundingAnchor(
  candidate: string,
  assertionSource: string,
  includeInterrogativeSource = false,
  requirePredicateSupport = false,
): boolean {
  return sourceSentences(assertionSource).some((sentence) => {
    if (!includeInterrogativeSource && isInterrogativeSourceSentence(sentence)) return false;
    if (omitsSourceDisjunction(candidate, sentence)) return false;
    const sourceSpans = /\b(?:rather\s+than|instead\s+of)\b/iu.test(candidate)
      ? [sentence]
      : splitGroundingClauses([sentence], true);
    return sourceSpans.some((sourceSpan) => {
      const exactMatch = containsExactTokenSequence(candidate, sourceSpan)
        && !hasContradictoryPolarity(candidate, sourceSpan);
      if (exactMatch) return true;
      if (requirePredicateSupport && !hasGroundedPredicateAnchor(candidate, sourceSpan)) return false;
      return groundedTokenScore(candidate, sourceSpan) > 0
        || hasRoleNormalizedGrounding(candidate, sourceSpan);
    });
  });
}

function hasAnswerSupport(
  candidate: string,
  source: string,
  assertionSource: string,
): boolean {
  const assertedAnswerSentences = new Set(
    sourceSentences(assertionSource)
      .filter((sentence) => {
        const answerToken = tokenSequence(sentence)[0];
        return answerToken === "yes" || answerToken === "no";
      })
      .map((sentence) => normalizeForExactMatch(sentence)),
  );
  if (assertedAnswerSentences.size === 0) return false;
  const sentences = sourceSentences(source);
  return sentences.some((sentence, index) => {
    const answerToken = tokenSequence(sentence)[0];
    if (answerToken !== "yes" && answerToken !== "no") return false;
    if (!assertedAnswerSentences.has(normalizeForExactMatch(sentence))) return false;
    const precedingSentence = sentences[index - 1];
    if (
      precedingSentence === undefined
      || !isInterrogativeSourceSentence(precedingSentence)
      || omitsSourceDisjunction(candidate, precedingSentence)
      || groundedTokenScore(candidate, precedingSentence) !== 1
    ) {
      return false;
    }
    const contradictoryPolarity = hasContradictoryPolarity(candidate, precedingSentence);
    return answerToken === "yes" ? !contradictoryPolarity : contradictoryPolarity;
  });
}

const GROUNDING_ROLE_SUBJECT_TOKENS = new Set(["assistant", "user"]);

function hasRoleNormalizedGrounding(candidate: string, source: string): boolean {
  const candidateTokens = groundingTokenSequence(candidate);
  if (!GROUNDING_ROLE_SUBJECT_TOKENS.has(
    (candidateTokens[0] ?? "").replace(/^[\u0000\u0001]/u, ""),
  )) return false;
  const claimTokens = candidateTokens.slice(1);
  if (claimTokens.length === 0) return false;

  return sourceSentences(source).some((sentence) => {
    if (isInterrogativeSourceSentence(sentence)) return false;
    const sourceTokens = groundingTokenSequence(sentence);
    const requiredSharedTokens = Math.min(GROUNDING_MIN_SHARED_TOKENS, claimTokens.length);
    let sourceIndex = 0;
    let sharedTokens = 0;
    for (const claimToken of claimTokens) {
      const matchingIndex = sourceTokens.findIndex(
        (sourceToken, index) =>
          index >= sourceIndex && areGroundingTokensCompatible(claimToken, sourceToken),
      );
      if (matchingIndex === -1) continue;
      sharedTokens += 1;
      sourceIndex = matchingIndex + 1;
    }
    return sharedTokens >= requiredSharedTokens
      && !hasContradictoryPolarity(candidate, sentence);
  });
}

interface GroundingContext {
  source: string;
  assertionSource: string | undefined;
  allowRoleNormalization: boolean;
  fallbackSource?: string;
  fallbackAssertionSource?: string;
}

function resolveGroundingContext(
  candidate: string,
  source: string,
  assertionSource: string | undefined,
  roleAssertionSources: ExtractionGroundingRoleSources | undefined,
): GroundingContext {
  const candidateRole = (groundingTokenSequence(candidate)[0] ?? "")
    .replace(/^[\u0000\u0001]/u, "");
  if (!GROUNDING_ROLE_SUBJECT_TOKENS.has(candidateRole)) {
    return { source, assertionSource, allowRoleNormalization: false };
  }
  if (roleAssertionSources === undefined) {
    return { source, assertionSource, allowRoleNormalization: true };
  }
  const roleSource = candidateRole === "user"
    ? roleAssertionSources.profile
    : roleAssertionSources.identity;
  if (roleSource === undefined) {
    return { source, assertionSource, allowRoleNormalization: true };
  }
  return {
    source: roleSource,
    assertionSource: roleSource,
    allowRoleNormalization: true,
    fallbackSource: source,
    fallbackAssertionSource: assertionSource,
  };
}

function selectGroundingContext(candidate: string, context: GroundingContext): GroundingContext {
  if (isGroundedCandidate(
    candidate,
    context.source,
    context.assertionSource,
    false,
    context.allowRoleNormalization,
  )) {
    return context;
  }
  if (
    context.fallbackSource === undefined
    || !hasExplicitRoleSubjectToken(
      (groundingTokenSequence(candidate)[0] ?? "").replace(/^[\u0000\u0001]/u, ""),
      sourceSentences(context.fallbackSource).map((sentence) => groundingTokenSequence(sentence)),
    )
  ) return context;
  const fallbackContext: GroundingContext = {
    source: context.fallbackSource,
    assertionSource: context.fallbackAssertionSource,
    allowRoleNormalization: false,
  };
  return isGroundedCandidate(
    candidate,
    fallbackContext.source,
    fallbackContext.assertionSource,
    false,
    fallbackContext.allowRoleNormalization,
  )
    ? fallbackContext
    : context;
}

function isGroundedCandidate(
  candidate: string,
  source: string,
  assertionSource: string | undefined,
  includeInterrogativeSource = false,
  allowRoleNormalization = false,
): boolean {
  const allowInterrogativeSource = includeInterrogativeSource
    || (
      assertionSource !== undefined
      && normalizeForExactMatch(assertionSource) !== normalizeForExactMatch(source)
    );
  const sourceGrounded = isSourceGrounded(candidate, source, allowInterrogativeSource);
  const roleGrounded = allowRoleNormalization && hasRoleNormalizedGrounding(candidate, source);
  const candidateTokens = groundingTokenSequence(candidate);
  const roleNormalizedCandidate = allowRoleNormalization
    && GROUNDING_ROLE_SUBJECT_TOKENS.has(
      (candidateTokens[0] ?? "").replace(/^[\u0000\u0001]/u, ""),
    );
  if (roleNormalizedCandidate && !roleGrounded) return false;
  if (!sourceGrounded && !roleGrounded) return false;
  if (assertionSource === undefined) return true;
  const clauses = candidateClauses(candidate);
  const requirePredicateSupport = !includeInterrogativeSource
    && assertionSource !== undefined
    && normalizeForExactMatch(assertionSource) !== normalizeForExactMatch(source);
  return clauses.length > 0
    && (
      clauses.every((clause) =>
        hasGroundingAnchor(clause, assertionSource, includeInterrogativeSource, requirePredicateSupport))
      || hasAnswerSupport(candidate, source, assertionSource)
    );
}

function groundWithinQuoteAnchors(
  content: string,
  anchors: readonly QuoteAnchor[],
  sourceHas: TokenPool,
): GroundingContext | undefined {
  const anchor = anchors.find((candidate) => isQuoteAnchoredClaim(content, candidate, sourceHas));
  if (anchor === undefined) return undefined;
  return {
    source: anchor.window,
    assertionSource: undefined,
    allowRoleNormalization: GROUNDING_ROLE_SUBJECT_TOKENS.has(
      (groundingTokenSequence(content)[0] ?? "").replace(/^[\u0000\u0001]/u, ""),
    ),
  };
}

function buildFactSupportSource(
  source: string,
  supportingSentences: ReadonlyArray<string>,
): string {
  const sentences = sourceSentences(source);
  const selectedIndices = new Set<number>();
  for (const supportingSentence of supportingSentences) {
    const supportIndex = sentences.indexOf(supportingSentence);
    if (supportIndex < 0) continue;
    let endIndex = supportIndex;
    while (
      endIndex < sentences.length - 1
      && sentences[endIndex]!.trimEnd().endsWith(";")
      && /^(?:its|their|this|that|these|those)\b/iu.test(
        sentences[endIndex + 1]!.trimStart(),
      )
    ) {
      endIndex += 1;
    }
    for (let index = supportIndex; index <= endIndex; index += 1) {
      selectedIndices.add(index);
    }
  }
  return [...selectedIndices]
    .sort((left, right) => left - right)
    .map((index) => sentences[index]!)
    .join(" ");
}
function buildProcedureSupportSource(
  fact: ExtractionResult["facts"][number],
  source: string,
  factSupportSource: string,
): string {
  if (fact.category !== "procedure" || fact.procedureSteps === undefined) return factSupportSource;
  const parentSupportSentences = new Set(
    sourceSentences(factSupportSource).map((sentence) => normalizeForExactMatch(sentence)),
  );
  const parentGroundedSteps = fact.procedureSteps.filter((step) =>
    isGroundedCandidate(step.intent, factSupportSource, undefined, false),
  );
  if (parentGroundedSteps.length === 0) return factSupportSource;
  return sourceSentences(source)
    .filter((sentence) => {
      if (parentSupportSentences.has(normalizeForExactMatch(sentence))) return true;
      const sentenceTokens = tokenize(sentence);
      return parentGroundedSteps.some((step) =>
        [...tokenize(step.intent)].some((token) =>
          [...sentenceTokens].some((sourceToken) => areGroundingTokensCompatible(token, sourceToken)),
        ),
      );
    })
    .join(" ");
}
function filterGroundedFact(
  fact: ExtractionResult["facts"][number],
  source: string,
  assertionSource: string | undefined,
  roleAssertionSources: ExtractionGroundingRoleSources | undefined,
  eventTimeNormalizer: ((eventTime: string) => string) | undefined,
  spanMode: "off" | "shadow" | "on" = "off",
  anchors: readonly QuoteAnchor[],
  sourceHas: TokenPool,
): ExtractionResult["facts"][number] | undefined {
  // Span-materialized content (issue #2333) is "frame: verbatim slice". The
  // frame is generated deixis, so full-content gating would drop a verbatim
  // fact. Only on-mode facts whose content is that materialized shape may
  // fall back to the slice. Shadow stays zero-diff with off.
  const quote = typeof fact.quote === "string" ? fact.quote : "";
  const materializedPrefix = quote.length > 0 && fact.content.endsWith(quote) && fact.content !== quote
    ? fact.content.slice(0, fact.content.length - quote.length)
    : "";
  const embeddedQuote =
    spanMode === "on"
    && quote.trim().length > 0
    && (materializedPrefix.endsWith(": ") || /[:—-]\s$/.test(materializedPrefix))
      ? quote
      : undefined;
  const contentContext = selectGroundingContext(
    fact.content,
    resolveGroundingContext(fact.content, source, assertionSource, roleAssertionSources),
  );
  let gateContent = fact.content;
  let factContext = contentContext;
  let quoteAnchored = false;
  if (
    !isGroundedCandidate(
      fact.content,
      contentContext.source,
      contentContext.assertionSource,
      false,
      contentContext.allowRoleNormalization,
    )
  ) {
    const quoteContext = spanMode === "on"
      ? undefined
      : groundWithinQuoteAnchors(fact.content, anchors, sourceHas);
    if (quoteContext !== undefined) {
      factContext = quoteContext;
      quoteAnchored = true;
    } else {
      if (embeddedQuote === undefined) return undefined;
      gateContent = embeddedQuote;
      factContext = selectGroundingContext(
        gateContent,
        resolveGroundingContext(gateContent, source, assertionSource, roleAssertionSources),
      );
      if (!isGroundedCandidate(
        gateContent,
        factContext.source,
        factContext.assertionSource,
        false,
        factContext.allowRoleNormalization,
      )) return undefined;
    }
  }
  const factEventTime = fact.eventTime;
  const groundedFactEventTime = factEventTime === undefined
    ? undefined
    : eventTimeNormalizer?.(factEventTime) ?? factEventTime;
  // A quote-anchored claim is reworded from the quote and its turn, so no single
  // sentence grounds it; the anchor window is the support for its sub-fields.
  const factSupportingSentences = quoteAnchored ? [] : sourceSentences(factContext.assertionSource ?? factContext.source).filter(
    (sentence) =>
    isGroundedCandidate(
      gateContent,
      sentence,
      undefined,
      false,
      factContext.allowRoleNormalization,
    ),
  );
  const factSupportingSource = factEventTime === undefined
    ? factSupportingSentences[0]
    : factSupportingSentences.find((sentence) =>
      isGroundedCandidate(
        groundedFactEventTime ?? factEventTime,
        sentence,
        undefined,
        false,
        factContext.allowRoleNormalization,
      ),
    ) ?? factSupportingSentences[0];
  const eventTimeSource = factSupportingSource ?? factContext.source;
  const eventTimeAssertionSource = factSupportingSource === undefined
    ? factContext.assertionSource
    : undefined;

  const factSupportSource = quoteAnchored
    ? factContext.source
    : buildFactSupportSource(
      factContext.assertionSource ?? factContext.source,
      factSupportingSentences,
    );
  const groundedAttributes = fact.structuredAttributes
    ? Object.fromEntries(
      Object.entries(fact.structuredAttributes)
        .filter(([key, value]) =>
          isGroundedCandidate(
            `${key}: ${value}`,
            factSupportSource,
            undefined,
            false,
            factContext.allowRoleNormalization,
          ),
        ),
    )
    : undefined;
  const procedureGroundingSource = buildProcedureSupportSource(
    fact,
    factContext.assertionSource ?? factContext.source,
    factSupportSource,
  );
  const groundedProcedureSteps = fact.procedureSteps
    ? fact.procedureSteps.flatMap((step) => {
      if (!isGroundedCandidate(step.intent, procedureGroundingSource, undefined, false)) return [];
      const expectedOutcome = step.expectedOutcome
        && isGroundedCandidate(step.expectedOutcome, procedureGroundingSource, undefined, false)
        ? step.expectedOutcome
        : undefined;
      const toolCall = step.toolCall
        && isGroundedCandidate(step.toolCall.signature, procedureGroundingSource, undefined, false)
        ? step.toolCall
        : undefined;
      const {
        expectedOutcome: _expectedOutcome,
        toolCall: _toolCall,
        ...stepWithoutOptionalFields
      } = step;
      return [{
        ...stepWithoutOptionalFields,
        ...(expectedOutcome !== undefined ? { expectedOutcome } : {}),
        ...(toolCall !== undefined ? { toolCall } : {}),
      }];
    })
    : undefined;
  const groundedReasoningTrace = fact.reasoningTrace
    && fact.reasoningTrace.steps.length > 0
    && isGroundedCandidate(
      fact.reasoningTrace.finalAnswer,
      factContext.source,
      factContext.assertionSource,
      false,
      factContext.allowRoleNormalization,
    )
    && fact.reasoningTrace.steps.every((step) =>
      isGroundedCandidate(
        step.description,
        factContext.source,
        factContext.assertionSource,
        false,
        factContext.allowRoleNormalization,
      ),
    )
    ? {
      steps: fact.reasoningTrace.steps,
      finalAnswer: fact.reasoningTrace.finalAnswer,
      ...(fact.reasoningTrace.observedOutcome
        && isGroundedCandidate(
          fact.reasoningTrace.observedOutcome,
          factContext.source,
          factContext.assertionSource,
          false,
          factContext.allowRoleNormalization,
        )
        ? { observedOutcome: fact.reasoningTrace.observedOutcome }
        : {}),
    }
    : undefined;
  const groundedEventTime = groundedFactEventTime
    && isGroundedCandidate(groundedFactEventTime, eventTimeSource, eventTimeAssertionSource)
    ? factEventTime
    : undefined;
  const groundedEntityRef = fact.entityRef !== undefined
    && isGroundedEntityName(fact.entityRef, factSupportSource)
    ? fact.entityRef
    : undefined;
  const {
    entityRef: _entityRef,
    structuredAttributes: _structuredAttributes,
    procedureSteps: _procedureSteps,
    reasoningTrace: _reasoningTrace,
    eventTime: _eventTime,
    ...factWithoutGroundingFields
  } = fact;
  return {
    ...factWithoutGroundingFields,
    ...(groundedEntityRef !== undefined ? { entityRef: groundedEntityRef } : {}),
    ...(groundedAttributes && Object.keys(groundedAttributes).length > 0
      ? { structuredAttributes: groundedAttributes }
      : {}),
    ...(groundedProcedureSteps && groundedProcedureSteps.length > 0
      ? { procedureSteps: groundedProcedureSteps }
      : {}),
    ...(groundedReasoningTrace !== undefined ? { reasoningTrace: groundedReasoningTrace } : {}),
    ...(groundedEventTime !== undefined ? { eventTime: groundedEventTime } : {}),
  };
}

function filterGroundedEntity(
  entity: ExtractionResult["entities"][number],
  source: string,
  assertionSource: string | undefined,
  anchorSupport?: (fact: string) => boolean,
): ExtractionResult["entities"][number] | undefined {
  const nameGrounded = isGroundedEntityName(entity.name, source);
  if (!nameGrounded && anchorSupport === undefined) return undefined;
  const entitySource = nameGrounded ? buildEntitySupportSource(entity.name, source) : "";
  const entityAssertionSource = !nameGrounded || assertionSource === undefined
    ? undefined
    : buildEntitySupportSource(entity.name, assertionSource);
  return filterEntityFacts(entity, (fact) =>
    (nameGrounded && isGroundedCandidate(fact, entitySource, entityAssertionSource))
    || anchorSupport?.(fact) === true);
}

function normalizedEntitySourceText(name: string): string {
  return normalizedEntityIdentifierTokens(name).join(" ");
}

function isGroundedRelationship(
  relationship: NonNullable<ExtractionResult["relationships"]>[number],
  source: string,
  assertionSource: string | undefined,
): boolean {
  const sourceName = normalizedEntitySourceText(relationship.source);
  const targetName = normalizedEntitySourceText(relationship.target);
  const labelTokens = tokenize(relationship.label);
  if (sourceName.length === 0 || targetName.length === 0 || labelTokens.size === 0) return false;
  const relationText = `${sourceName} ${relationship.label} ${targetName}`;
  const hasCoherentSourceSpan = sourceSentences(source).some((sentence) => {
    if (isInterrogativeSourceSentence(sentence)) return false;
    return groundedTokenScore(relationText, sentence) === 1
      && !hasContradictoryPolarity(relationText, sentence);
  });
  return hasCoherentSourceSpan
    && isGroundedCandidate(relationText, source, assertionSource);
}
const GROUNDING_TEMPORAL_WORDS = new Set([
  "today",
  "yesterday",
  "tomorrow",
  "now",
  "recently",
  "earlier",
  "later",
  "soon",
  "morning",
  "afternoon",
  "evening",
  "tonight",
  "night",
  "noon",
  "midnight",
  "monday",
  "tuesday",
  "wednesday",
  "thursday",
  "friday",
  "saturday",
  "sunday",
  "january",
  "february",
  "march",
  "april",
  "may",
  "june",
  "july",
  "august",
  "september",
  "october",
  "november",
  "december",
  "q1",
  "q2",
  "q3",
  "q4",
]);
const GROUNDING_TEMPORAL_CLOCK_PATTERN = /\b\d{1,2}:\d{2}(?:\s*[ap]\.?m\.?)?\b/iu;
const GROUNDING_TEMPORAL_DURATION_PATTERN = new RegExp(
  "\\b(?:\\d+|one|two|three|four|five|six|seven|eight|nine|ten)\\s+"
    + "(?:seconds?|minutes?|hours?|days?|weeks?|months?|quarters?|years?)\\b",
  "iu",
);

function isWhenQuestion(question: string): boolean {
  return /^(?:when|what\s+(?:time|date)|which\s+day)\b/iu.test(question.trim());
}
function isWhyQuestion(question: string): boolean {
  return /^why\b/iu.test(question.trim());
}

function hasCausalAnswerEvidence(question: string, sentence: string): boolean {
  if (!isWhyQuestion(question)) return true;
  return /\b(?:because|since|due\s+to|owing\s+to|thanks\s+to|therefore|thus|hence|so)\b/iu.test(
    sentence,
  );
}

function hasTemporalAnswerEvidence(question: string, sentence: string): boolean {
  if (!isWhenQuestion(question)) return true;
  return groundingLexemes(sentence).some(({ token }) =>
    GROUNDING_TEMPORAL_WORDS.has(token) || /^(?:19|20)\d{2}$/u.test(token),
  )
    || GROUNDING_TEMPORAL_CLOCK_PATTERN.test(sentence)
    || GROUNDING_TEMPORAL_DURATION_PATTERN.test(sentence);
}


function isUnknownAnswerSentence(sentence: string): boolean {
  return /\b(?:unknown|unclear|unsure|unresolved|unanswered|not\s+(?:known|sure|available)|don't\s+know|do\s+not\s+know|no\s+idea|pending)\b/iu
    .test(sentence);
}

function isYesNoAnswer(sentence: string): boolean {
  return /^(?:yes|no)(?:[.!?]|,\s*(?:absolutely|definitely|indeed|exactly|correct|of\s+course|use\s+that|do\s+that)[.!?]?)?$/iu
    .test(sentence.trim());
}

const GROUNDING_WH_OBJECT_QUESTION_PATTERN = new RegExp(
  "^(?:(?:what|which)(?:\\s+.+?)?|who|whom)\\s+"
    + "(?:is|are|was|were|do|does|did|can|could|will|would|should|has|have|had)\\s+"
    + "(.+?)\\??$",
  "iu",
);

function hasWhAnswerRoleAlignment(question: string, sentence: string): boolean {
  const normalizedQuestion = question.trim();
  const objectQuestionMatch = GROUNDING_WH_OBJECT_QUESTION_PATTERN.exec(normalizedQuestion);
  const sourceTokens = normalizedGroundingTokenSequence(sentence);
  if (objectQuestionMatch !== null) {
    const questionBodyLexemes = groundingLexemes(objectQuestionMatch[1] ?? "");
    const predicateIndex = questionBodyLexemes.findIndex(({ isPredicate }) => isPredicate);
    if (predicateIndex < 1) return false;
    const subjectTokens = groundingTokenSequence(
      questionBodyLexemes.slice(0, predicateIndex).map(({ surface }) => surface).join(" "),
    );
    const predicateTokens = groundingTokenSequence(
      questionBodyLexemes.slice(predicateIndex).map(({ surface }) => surface).join(" "),
    );
    if (subjectTokens.length === 0 || predicateTokens.length === 0) return false;
    let sourceIndex = 0;
    for (const token of [...subjectTokens, ...predicateTokens]) {
      const matchedIndex = sourceTokens.findIndex(
        (sourceToken, index) =>
          index >= sourceIndex && areGroundingTokensCompatible(token, sourceToken),
      );
      if (matchedIndex === -1) return false;
      sourceIndex = matchedIndex + 1;
    }
    return true;
  }

  const subjectQuestionMatch = /^(?:who|what)\s+([^\s?]+)\s+(.+?)\??$/iu.exec(normalizedQuestion);
  if (subjectQuestionMatch === null) return true;
  const predicateTokens = groundingTokenSequence(subjectQuestionMatch[1] ?? "");
  const objectTokens = groundingTokenSequence(subjectQuestionMatch[2] ?? "");
  if (predicateTokens.length === 0 || objectTokens.length === 0) return true;
  const predicateStart = sourceTokens.findIndex((sourceToken) =>
    areGroundingTokensCompatible(predicateTokens[0]!, sourceToken));
  if (predicateStart === -1) return false;
  let sourceIndex = predicateStart + predicateTokens.length;
  for (const objectToken of objectTokens) {
    const objectIndex = sourceTokens.findIndex(
      (sourceToken, index) =>
        index >= sourceIndex && areGroundingTokensCompatible(objectToken, sourceToken),
    );
    if (objectIndex === -1) return false;
    sourceIndex = objectIndex + 1;
  }
  return true;
}

function isQuestionAnsweredBySource(
  question: string,
  source: string,
  assertionSource: string | undefined,
): boolean {
  const questionTokens = tokenize(question);
  if (questionTokens.size === 0) return false;
  const isYesNoQuestion = /^(?:is|are|am|was|were|do|does|did|can|could|will|would|should|has|have|had)\b/iu
    .test(question.trim());
  const assertedSentences = new Set(sourceSentences(assertionSource ?? source).map((sentence) => normalizeForExactMatch(sentence)));
  const sentences = sourceSentences(source);
  return sentences.some((sentence, index) => {
    if (!assertedSentences.has(normalizeForExactMatch(sentence))) return false;
    if (isInterrogativeSourceSentence(sentence)) return false;
    if (isYesNoAnswer(sentence)) {
      const precedingSentence = sentences[index - 1];
      return precedingSentence !== undefined
        && isInterrogativeSourceSentence(precedingSentence)
        && groundedTokenScore(question, precedingSentence) === 1;
    }
    if (isUnknownAnswerSentence(sentence)) return false;
    const score = groundedTokenScore(question, sentence, false);
    if (score !== 1) return false;
    const sentenceTokens = tokenize(sentence);
    const hasAnswerToken = [...sentenceTokens].some((token) => !questionTokens.has(token));
    return (isYesNoQuestion || hasAnswerToken)
      && hasTemporalAnswerEvidence(question, sentence)
      && hasCausalAnswerEvidence(question, sentence)
      && hasWhAnswerRoleAlignment(question, sentence);
  });
}

function groundQuestion(
  question: ExtractionResult["questions"][number],
  source: string,
  assertionSource: string | undefined,
): ExtractionResult["questions"][number] | undefined {
  if (isQuestionAnsweredBySource(question.question, source, assertionSource)) return undefined;
  if (!isGroundedCandidate(question.question, source, assertionSource, true)) return undefined;
  const normalizedContext = question.context.trim();
  if (
    normalizedContext.length > 0
    && !isGroundedCandidate(normalizedContext, assertionSource ?? source, undefined, false)
  ) {
    return { ...question, context: "" };
  }
  return question;
}

function isRoleGroundedCandidate(
  candidate: string,
  source: string,
  assertionSource: string | undefined,
  roleAssertionSources: ExtractionGroundingRoleSources | undefined,
): boolean {
  const context = selectGroundingContext(
    candidate,
    resolveGroundingContext(candidate, source, assertionSource, roleAssertionSources),
  );
  return isGroundedCandidate(
    candidate,
    context.source,
    context.assertionSource,
    false,
    context.allowRoleNormalization,
  );
}

export function filterExtractionResultBySource(
  result: ExtractionResult,
  source: string,
  assertionSource?: string,
  roleAssertionSources?: ExtractionGroundingRoleSources,
  eventTimeNormalizer?: (eventTime: string) => string,
  spanMode: "off" | "shadow" | "on" = "off",
  quoteTransform?: (quote: string) => string,
): ExtractionResult {
  if (source.trim().length === 0) {
    return {
      ...result,
      facts: [],
      profileUpdates: [],
      entities: [],
      questions: [],
      ...(result.relationships !== undefined ? { relationships: [] } : {}),
      identityReflection: undefined,
    };
  }

  const quoteSource = assertionSource ?? source;
  const keptAnchors: QuoteAnchor[] = [];
  const sourceHas = tokenPool(
    result.facts.some((fact) => typeof fact.quote === "string") ? tokenize(quoteSource) : new Set(),
  );
  const facts = result.facts.flatMap((fact) => {
    const anchors = quoteAnchors(fact.quote, quoteSource, quoteTransform);
    const grounded = filterGroundedFact(
      fact,
      source,
      assertionSource,
      roleAssertionSources,
      eventTimeNormalizer,
      spanMode,
      anchors,
      sourceHas,
    );
    if (grounded === undefined) return [];
    keptAnchors.push(...anchors);
    return [grounded];
  });
  const profileUpdates = result.profileUpdates.filter((update) =>
    isRoleGroundedCandidate(update, source, assertionSource, roleAssertionSources),
  );
  const entities = result.entities.flatMap((entity) => {
    const anchorSupport = quoteAnchoredEntitySupport(entity, keptAnchors, sourceHas);
    const grounded = filterGroundedEntity(entity, source, assertionSource, anchorSupport);
    return grounded === undefined ? [] : [grounded];
  });
  const questions = result.questions.flatMap((question) => {
    const grounded = groundQuestion(question, source, assertionSource);
    return grounded === undefined ? [] : [grounded];
  });
  const relationships = result.relationships?.filter((relationship) =>
    isGroundedRelationship(relationship, source, assertionSource)
    || isQuoteAnchoredRelationship(relationship, keptAnchors, sourceHas),
  );
  const identityReflection = result.identityReflection
    && isRoleGroundedCandidate(
      result.identityReflection,
      source,
      assertionSource,
      roleAssertionSources,
    )
    ? result.identityReflection
    : undefined;

  return {
    ...result,
    facts,
    profileUpdates,
    entities,
    questions,
    ...(result.relationships !== undefined ? { relationships } : {}),
    ...(identityReflection !== undefined ? { identityReflection } : { identityReflection: undefined }),
  };
}

/**
 * Isolated span-offset parser (issue #2333 first slice).
 *
 * Default off. Extraction wiring waits on the Phase A bench gate.
 */

export interface SpanOffsets {
  start: number;
  end: number;
}

export interface ParsedSpan {
  text: string;
  start?: number;
  end?: number;
}

export function parseSpanOffsets(
  text: string,
  offsets: SpanOffsets,
  spanModeEnabled: boolean | 0 | 1 = false,
): ParsedSpan {
  if (spanModeEnabled !== true && spanModeEnabled !== 1) {
    return { text };
  }

  const { start, end } = offsets;
  if (!Number.isInteger(start) || !Number.isInteger(end)) {
    throw new RangeError("invalid span: out of range");
  }
  if (start > end) {
    throw new RangeError("invalid span: reversed");
  }
  if (start < 0 || end > text.length) {
    throw new RangeError("invalid span: out of range");
  }

  return { text: text.slice(start, end), start, end };
}

// Tag filtering helpers for memory recall (issue #689).
//
// Tags are free-form labels stored on each memory's frontmatter (see
// `storage.ts`). Recall callers can filter the result set down to memories
// that match a set of tags using `any` (default) or `all` semantics.
//
// This module is intentionally small and pure. The actual filter is applied
// at the access-service seam after `serializeRecallResults` hydrates each
// result's tags from frontmatter, so we don't have to touch QMD or thread
// tag-aware metadata through orchestrator internals for v1.
//
// Comparison is case-sensitive exact match — same form storage uses for tags.

import type { RecallFilterTrace } from "./recall-xray.js";

export type TagMatchMode = "any" | "all";

const TAG_MATCH_VALUES: ReadonlyArray<TagMatchMode> = ["any", "all"];

/**
 * Coerce a caller-supplied `tagMatch` value to the allowed enum.
 *
 * - `undefined` / `null` → `undefined` (caller didn't ask).
 * - Valid string → narrowed `TagMatchMode`.
 * - Invalid string → throws (CLAUDE.md rule 51 — never silently default).
 */
export function parseTagMatch(value: unknown): TagMatchMode | undefined {
  if (value === undefined || value === null) return undefined;
  if (typeof value !== "string") {
    throw new Error(
      `tagMatch must be a string (one of: ${TAG_MATCH_VALUES.join(", ")})`,
    );
  }
  const trimmed = value.trim();
  if (trimmed.length === 0) return undefined;
  if (trimmed !== "any" && trimmed !== "all") {
    throw new Error(
      `invalid tagMatch value: ${value} (expected one of: ${TAG_MATCH_VALUES.join(", ")})`,
    );
  }
  return trimmed;
}

/**
 * Coerce a caller-supplied `tags` value into a clean string[].
 *
 * Accepts `string[]` and discards non-string / empty entries. Returns
 * `undefined` when no usable tags remain so downstream callers can treat
 * "no filter" and "empty filter" identically.
 */
export function normalizeTags(value: unknown): string[] | undefined {
  if (!Array.isArray(value)) return undefined;
  const out: string[] = [];
  const seen = new Set<string>();
  for (const entry of value) {
    if (typeof entry !== "string") continue;
    const trimmed = entry.trim();
    if (trimmed.length === 0) continue;
    if (seen.has(trimmed)) continue;
    seen.add(trimmed);
    out.push(trimmed);
  }
  return out.length > 0 ? out : undefined;
}

export interface TagFilterInput {
  tags: string[] | undefined;
  tagMatch: TagMatchMode | undefined;
}

export interface TagFilterDecision {
  /** Whether the candidate's tags satisfy the filter. */
  admitted: boolean;
}

/**
 * Decide whether a single result's tags satisfy the filter.
 *
 * `any` (default) admits when the result has at least one of the filter
 * tags. `all` admits only when every filter tag is present on the result.
 * Returns `admitted: true` whenever no filter tags are configured.
 */
export function evaluateTagFilter(
  candidateTags: string[] | undefined,
  filter: TagFilterInput,
): TagFilterDecision {
  const filterTags = filter.tags;
  if (!filterTags || filterTags.length === 0) {
    return { admitted: true };
  }
  const tags = Array.isArray(candidateTags) ? candidateTags : [];
  const tagSet = new Set(tags);
  const mode: TagMatchMode = filter.tagMatch ?? "any";
  if (mode === "all") {
    for (const t of filterTags) {
      if (!tagSet.has(t)) return { admitted: false };
    }
    return { admitted: true };
  }
  for (const t of filterTags) {
    if (tagSet.has(t)) return { admitted: true };
  }
  return { admitted: false };
}

export interface TaggedResult {
  tags: string[];
}

/**
 * Apply the tag filter to an array of recall results.
 *
 * Returns `{results, trace}`:
 *  - `results` is the filtered array (or the original when no filter).
 *  - `trace` is a `RecallFilterTrace` capturing how many candidates were
 *    seen vs admitted, suitable for surfacing in X-ray output.
 *
 * `trace` is `null` when no filter tags were configured so callers can
 * skip emitting an empty trace entry.
 */
export function applyTagFilter<T extends TaggedResult>(
  results: T[],
  filter: TagFilterInput,
): { results: T[]; trace: RecallFilterTrace | null } {
  const filterTags = filter.tags;
  if (!filterTags || filterTags.length === 0) {
    return { results, trace: null };
  }
  const mode: TagMatchMode = filter.tagMatch ?? "any";
  const admitted: T[] = [];
  for (const r of results) {
    if (evaluateTagFilter(r.tags, filter).admitted) {
      admitted.push(r);
    }
  }
  const trace: RecallFilterTrace = {
    name: "tag-filter",
    considered: results.length,
    admitted: admitted.length,
    reason: `tags=${filterTags.join(",")} match=${mode}`,
  };
  return { results: admitted, trace };
}

/**
 * Span source stamp/verify (issue #2333).
 *
 * Offsets index the exact normalized string sent to the model. If that string
 * drifts before materialization, the offsets point at different characters and
 * a wrong quote is persisted as verbatim source. The stamp lets materialization
 * detect the drift without carrying the source text alongside it.
 *
 * Pure apart from hashing: no I/O, no clock, no randomness. The input text is
 * never mutated and never appears in a result or error message.
 */

import { createHash } from "node:crypto";

export interface SpanSourceStamp {
  /** Hex digest of the exact string the model was shown. */
  hash: string;
  /** Length of that string, so a mismatch reports which dimension drifted. */
  length: number;
}

export type SpanSourceCheck =
  | { ok: true }
  | {
      ok: false;
      error: "length_mismatch" | "hash_mismatch";
      expected: SpanSourceStamp;
      actual: SpanSourceStamp;
    };

const HASH_PATTERN = /^[0-9a-f]{64}$/;

function requireText(text: string): void {
  if (typeof text !== "string") {
    throw new TypeError(`text must be a string, got ${typeof text}`);
  }
}

function requireStamp(expected: SpanSourceStamp): void {
  if (!Object.hasOwn(expected, "hash")) {
    throw new RangeError("expected stamp is missing field hash");
  }
  if (!Object.hasOwn(expected, "length")) {
    throw new RangeError("expected stamp is missing field length");
  }
  const { hash, length } = expected;
  if (typeof hash !== "string" || !HASH_PATTERN.test(hash)) {
    throw new RangeError(
      "expected stamp field hash must be 64 lowercase hex characters",
    );
  }
  if (!Number.isInteger(length) || length < 0) {
    throw new RangeError(
      "expected stamp field length must be a non-negative integer",
    );
  }
}

/**
 * Hash the exact string. No trimming, no newline normalization.
 *
 * The digest covers UTF-16LE code units, not UTF-8 bytes: Node's UTF-8
 * encoder replaces an unpaired surrogate with U+FFFD before hashing, so
 * "\ud800", "\ud801", and "\ufffd" all produce ONE digest under utf8 and
 * drift between them would verify as unchanged. Unpaired surrogates reach
 * real memory text through JSON escapes, and this stamp exists to catch
 * exactly that class of silent substitution, so it hashes a lossless
 * representation of the string instead.
 */
export function stampSpanSource(text: string): SpanSourceStamp {
  requireText(text);
  const hash = createHash("sha256").update(Buffer.from(text, "utf16le")).digest("hex");
  return { hash, length: text.length };
}

/**
 * Verify the materialized string against its stamp. Length is compared first:
 * it is the cheaper, more diagnostic dimension. Mismatch results carry both
 * stamps and never the text itself.
 */
export function verifySpanSource(
  text: string,
  expected: SpanSourceStamp,
): SpanSourceCheck {
  requireText(text);
  requireStamp(expected);
  const actual = stampSpanSource(text);
  // Project the caller's stamp down to exactly the two stamp fields. Echoing
  // the original object would re-export any extra property it carries — a
  // `source` field holding the text defeats the whole point of a stamp, which
  // exists so the content does not have to travel.
  const safeExpected: SpanSourceStamp = { hash: expected.hash, length: expected.length };
  if (actual.length !== safeExpected.length) {
    return { ok: false, error: "length_mismatch", expected: safeExpected, actual };
  }
  if (actual.hash !== safeExpected.hash) {
    return { ok: false, error: "hash_mismatch", expected: safeExpected, actual };
  }
  return { ok: true };
}

/**
 * Isolated span-offset validator (issue #2333 leftover).
 *
 * Pure. Extraction wiring waits on the Phase A bench gate.
 */

export type SpanValidateOk = { ok: true };
export type SpanValidateErr = { ok: false; error: "out_of_range" | "empty" };
export type SpanValidateResult = SpanValidateOk | SpanValidateErr;

export function validateSpanOffsets(opts: {
  start: number;
  end: number;
  textLength: number;
}): SpanValidateResult {
  const { start, end, textLength } = opts;
  if (!Number.isInteger(start) || !Number.isInteger(end) || !Number.isInteger(textLength)) {
    throw new TypeError("span offsets must be integers");
  }
  if (start < 0 || end < start || end > textLength) {
    return { ok: false, error: "out_of_range" };
  }
  if (start === end) {
    return { ok: false, error: "empty" };
  }
  return { ok: true };
}

/**
 * Isolated span slicer (issue #2333 leftover).
 *
 * Pure. Extraction wiring waits on the Phase A bench gate.
 */

export function sliceSpanText(opts: {
  text: string;
  start: number;
  end: number;
}): string {
  const { text, start, end } = opts;
  if (!Number.isInteger(start) || !Number.isInteger(end)) {
    throw new TypeError("span offsets must be integers");
  }
  if (start < 0 || end < start || end > text.length) {
    throw new RangeError("span offsets out of range");
  }
  return text.slice(start, end);
}

/**
 * Shared transient-error classifier for live connectors.
 *
 * All three connectors (Drive, Notion, Gmail) need to distinguish transient
 * errors (re-throw so the pass stops without advancing the cursor — the next
 * poll retries the same batch) from terminal errors (skip-and-continue — the
 * resource is gone, inaccessible, or malformed in a non-recoverable way).
 *
 * Having three independent copies of this logic caused divergent edge-case
 * handling (Cursor thread PRRT_kwDORJXyws59sdH4 / #745). This module is the
 * single source of truth; all three connectors import from here.
 *
 * Transient classes:
 *   - 429  (rate-limit / quota — retry after backoff)
 *   - 5xx  (backend error — retry)
 *   - AbortError / cancelled requests
 *   - Network errors with no HTTP status (ECONNRESET, ETIMEDOUT, ENOTFOUND, EAI_AGAIN, …)
 *   - Bare `Error` with no metadata (plain network failures)
 *
 * Terminal classes (skip-and-continue):
 *   - 400  (bad request — won't be fixed by retrying)
 *   - 403  (permission denied)
 *   - 404  (resource gone or not shared)
 *   - 410  (gone)
 *   - Any other 4xx that isn't 429
 *
 * Connector-specific status properties are resolved via the `statusProps`
 * parameter. Connectors attach their own status property name (e.g.
 * `gmailStatus`, `notionStatus`) so the classifier can resolve it without
 * knowing the error shape in detail.
 */

/**
 * Duck-typed error shape that all three connector error types share.
 * Callers pass additional connector-specific status property names via
 * `statusProps`.
 */
interface ErrorLike {
  name?: unknown;
  code?: unknown;
  status?: unknown;
  response?: { status?: unknown } | null;
  [key: string]: unknown;
}

/**
 * Set of Node.js network-layer error codes we treat as transient.
 * Explicitly enumerated (not a denylist) so unknown codes don't accidentally
 * get swallowed.
 */
const TRANSIENT_NODE_CODES = new Set([
  "ECONNRESET",
  "ECONNREFUSED",
  "ECONNABORTED",
  "ETIMEDOUT",
  "ESOCKETTIMEDOUT",
  "ENOTFOUND",
  "EAI_AGAIN",
  "EPIPE",
  "EHOSTUNREACH",
  "ENETUNREACH",
  "ENETDOWN",
  "ERR_NETWORK",
  "ERR_NETWORK_CHANGED",
]);

/**
 * Resolve a numeric HTTP status from any of the documented locations on an
 * error-shaped object.
 *
 * Resolution order:
 *   1. `statusProps` — connector-specific status properties (e.g. `gmailStatus`, `notionStatus`)
 *   2. `response.status` — canonical for fetch-compatible / GaxiosError shapes
 *   3. `status` — top-level for some HTTP client libraries
 *   4. `code` — numeric (older GaxiosError) or string-numeric ("429" / "503")
 */
function resolveHttpStatus(
  e: ErrorLike,
  statusProps: readonly string[],
): number | undefined {
  // Connector-specific properties first.
  for (const prop of statusProps) {
    const v = e[prop];
    if (typeof v === "number" && Number.isFinite(v)) return v;
  }

  // response.status (canonical GaxiosError / fetch-compatible).
  const responseStatus = e.response?.status;
  if (typeof responseStatus === "number" && Number.isFinite(responseStatus)) {
    return responseStatus;
  }

  // Top-level status.
  if (typeof e.status === "number" && Number.isFinite(e.status)) return e.status;

  // Numeric code.
  if (typeof e.code === "number" && Number.isFinite(e.code)) return e.code;

  // String-numeric codes ("429" / "503" — older googleapis / older Node HTTP).
  if (typeof e.code === "string" && /^\d+$/.test(e.code)) {
    const n = Number(e.code);
    if (Number.isFinite(n) && n >= 100 && n <= 599) return n;
  }

  return undefined;
}

/**
 * Generic transient-error classifier.
 *
 * Returns `true` when `err` looks transient (caller should re-throw without
 * advancing the cursor so the next poll retries). Returns `false` for terminal
 * errors (skip-and-continue is safe).
 *
 * @param err      - The caught error value.
 * @param statusProps - Additional property names the caller attaches an HTTP
 *                  status to (e.g. `["gmailStatus"]`, `["notionStatus"]`).
 *                  Pass an empty array when only the generic locations are needed.
 */
export function isTransientHttpError(
  err: unknown,
  statusProps: readonly string[] = [],
): boolean {
  if (err === null || typeof err !== "object") return false;
  const e = err as ErrorLike;

  // AbortError — always transient.
  if (typeof e.name === "string" && e.name === "AbortError") return true;

  // Resolve HTTP status.
  const status = resolveHttpStatus(e, statusProps);
  if (status !== undefined) {
    if (status === 429) return true;
    if (status >= 500 && status <= 599) return true;
    // Any 4xx that isn't 429 is terminal.
    return false;
  }

  // Network-layer codes.
  if (typeof e.code === "string") {
    if (TRANSIENT_NODE_CODES.has(e.code)) return true;
    // Unknown string code with no HTTP status: conservative terminal to avoid
    // looping on a permanent error. Callers can override if needed.
    return false;
  }

  // No status, no code — likely a plain `Error` from a fetch-layer network
  // failure. Treat as transient.
  return true;
}

import type { QmdSearchResult } from "../types.js";

/** Alias so consumers don't need to reference "Qmd" in a backend-agnostic context. */
export type SearchResult = QmdSearchResult;

export interface SearchQueryOptions {
  intent?: string;
  explain?: boolean;
  candidateLimit?: number;
  rerank?: boolean;
  chunkStrategy?: "auto" | "regex";
  structuredSearches?: Array<{ type: "lex" | "vec" | "hyde"; query: string }>;
}

/**
 * A search that returned empty (or partial) results because the backend was
 * unavailable, still loading, or timed out — cases that are otherwise
 * indistinguishable from a genuine "no matches" (issue #1536, CLAUDE.md
 * rule 34).
 */
export interface SearchDegradation {
  backend: "qmd" | "remote" | "meilisearch" | "orama" | "lancedb";
  code:
    | "backend_unavailable"
    | "backend_error"
    | "daemon_timeout"
    | "daemon_loading"
    | "subprocess_error"
    | "deadline_exceeded"
    | "remote_error"
    | "vector_tier_unavailable";
  detail?: string;
}

export interface SearchExecutionOptions {
  signal?: AbortSignal;
  /**
   * Observer invoked when the backend degrades during this call (#1536).
   * Callers that need to distinguish empty-because-degraded from
   * empty-because-no-matches (recall x-ray, fallback decisions) pass a
   * collector here. Observer failures are swallowed by the notifier —
   * observability must never break search.
   */
  onDegradation?: (degradation: SearchDegradation) => void;
}

export function reportSearchDegradation(
  execution: SearchExecutionOptions | undefined,
  degradation: SearchDegradation
): void {
  try {
    execution?.onDegradation?.(degradation);
  } catch {
    // Observability must never break search.
  }
}

/**
 * Codes that mean the search backend could NOT answer, so an empty
 * result set carries no information (issue #3082 / recall_why #3033).
 * `vector_tier_unavailable` is excluded on purpose: the lexical tier
 * still answered, so the result set is degraded but real.
 */
export const FATAL_SEARCH_DEGRADATION_CODES: Readonly<
  Partial<Record<SearchDegradation["code"], true>>
> = Object.freeze({
  backend_unavailable: true,
  backend_error: true,
  daemon_timeout: true,
  daemon_loading: true,
  subprocess_error: true,
  deadline_exceeded: true,
  remote_error: true,
});

export function fatalSearchDegradations(
  degradations: readonly SearchDegradation[],
): SearchDegradation[] {
  return degradations.filter((d) => FATAL_SEARCH_DEGRADATION_CODES[d.code] === true);
}

export function describeSearchDegradations(
  degradations: readonly SearchDegradation[],
): string {
  return degradations
    .map((d) => `${d.backend}:${d.code}${d.detail !== undefined ? ` (${d.detail})` : ""}`)
    .join("; ");
}

export function resolveEnsureCollectionArgs(
  collectionOrExecution?: string | SearchExecutionOptions,
  execution?: SearchExecutionOptions
): { collection?: string; execution?: SearchExecutionOptions } {
  if (typeof collectionOrExecution === "string") {
    return { collection: collectionOrExecution, execution };
  }
  return { collection: undefined, execution: collectionOrExecution ?? execution };
}

/**
 * Optional status report for search backends that track embedding backlog.
 * Backends without embedding pipelines return null from status().
 */
export interface SearchBackendStatus {
  pendingEmbeddings: number | null;
  oldestPendingAgeMs: number | null;
  totalFiles: number | null;
  embeddedFiles: number | null;
}

/**
 * Abstract search backend interface.
 *
 * Implementations:
 * - QmdClient (default, local hybrid BM25+vector+reranking)
 * - OramaBackend (embedded, pure JS, hybrid FTS+vector)
 * - LanceDbBackend (embedded, native Arrow bindings, RRF reranking)
 * - MeilisearchBackend (server-based SDK, hybrid search)
 * - RemoteSearchBackend (HTTP REST adapter)
 * - NoopSearchBackend (graceful degradation)
 *
 * See docs/writing-a-search-backend.md for the implementation guide.
 */
export interface SearchBackend {
  // ── Lifecycle ──
  probe(execution?: SearchExecutionOptions): Promise<boolean>;
  /**
   * Optional non-mutating availability probe for health/readiness checks.
   * Implementations must avoid auto-upgrades, collection creation, daemon
   * startup, or any other runtime-modifying side effects.
   */
  checkAvailability?(execution?: SearchExecutionOptions): Promise<boolean>;
  isAvailable(): boolean;
  debugStatus(): string;
  /** Optional embedding backlog status for health surfaces. */
  status?(): Promise<SearchBackendStatus>;

  // ── Search ──
  search(
    query: string,
    collection?: string,
    maxResults?: number,
    options?: SearchQueryOptions,
    execution?: SearchExecutionOptions
  ): Promise<SearchResult[]>;
  searchGlobal(query: string, maxResults?: number, execution?: SearchExecutionOptions): Promise<SearchResult[]>;
  bm25Search(
    query: string,
    collection?: string,
    maxResults?: number,
    execution?: SearchExecutionOptions
  ): Promise<SearchResult[]>;
  vectorSearch(
    query: string,
    collection?: string,
    maxResults?: number,
    execution?: SearchExecutionOptions
  ): Promise<SearchResult[]>;
  hybridSearch(
    query: string,
    collection?: string,
    maxResults?: number,
    execution?: SearchExecutionOptions
  ): Promise<SearchResult[]>;

  // ── Maintenance ──
  update(execution?: SearchExecutionOptions): Promise<void>;
  /**
   * Wall-clock ms of the most recent SUCCESSFUL index refresh, or null when the
   * backend has never run one. Ordinary update() is fail-open: it returns
   * silently (without throwing or advancing this timestamp) when the backend is
   * unavailable or the call is suppressed by a min-interval / failure backoff.
   * Callers that must know whether update() actually indexed — so they can
   * invalidate dependent caches only on a real refresh — snapshot this before
   * the call and treat the backend as refreshed iff the value advanced. Optional
   * because not every backend tracks it; absent means "assume refreshed".
   */
  readonly lastUpdateRanAtMs?: number | null;
  /**
   * Optional strict refresh used by callers that must know whether the backend
   * was actually refreshed before writing success markers. Ordinary update
   * calls remain fail-open for migration/maintenance resilience.
   */
  updateStrict?(execution?: SearchExecutionOptions): Promise<void>;
  /**
   * Fail-open like update(), but reports whether the index was actually brought
   * up to date: false when it returned early (aborted, unavailable, suppressed
   * or skipped) or failed. It never rejects for an update failure. For backends with no strict variant, so a caller
   * that must not lose a re-index (the entity-migration pending marker) can tell.
   */
  updateCompleted?(execution?: SearchExecutionOptions): Promise<boolean>;
  updateCollection(collection: string, execution?: SearchExecutionOptions): Promise<void>;
  updateCollectionFromDir?(collection: string, memoryDir: string, execution?: SearchExecutionOptions): Promise<void>;
  /**
   * True when update() refreshes every indexed collection, not just this
   * backend's configured collection. Namespace routers use this to avoid
   * repeating the same expensive global update once per namespace.
   */
  updatesAllCollections?(): boolean;
  /**
   * Optional strict refresh used by callers that must know whether a collection
   * was actually refreshed before writing success markers. Ordinary update
   * calls remain fail-open for migration/maintenance resilience.
   */
  updateCollectionStrict?(collection: string, execution?: SearchExecutionOptions): Promise<void>;
  embed(): Promise<void>;
  /**
   * Optional strict embed used by callers that must know vectors were actually
   * refreshed before writing success markers.
   */
  embedStrict?(): Promise<void>;
  embedCollection(collection: string): Promise<void>;
  /**
   * Optional strict collection embed used by callers that must know vectors were
   * actually refreshed before writing success markers.
   */
  embedCollectionStrict?(collection: string): Promise<void>;

  // ── Collection management ──
  /**
   * True only when the backend can bind, isolate, search, and delete collections
   * outside Remnic's primary memory roots.
   */
  supportsAdditionalCollections?(): boolean;
  /**
   * Prevent a collection from participating in unscoped/global searches.
   * Dedicated corpora must call this immediately after collection creation.
   */
  excludeCollectionFromGlobalSearch?(collection: string, execution?: SearchExecutionOptions): Promise<void>;
  /** Remove a non-primary collection and its backend-owned index state. */
  deleteCollection?(collection: string, execution?: SearchExecutionOptions): Promise<boolean>;
  /** Canonical source root currently bound to a named collection. */
  collectionRoot?(collection: string, execution?: SearchExecutionOptions): Promise<string | null>;
  /** Collection-scoped status for observability surfaces. */
  collectionStatus?(collection: string): Promise<Pick<SearchBackendStatus, "totalFiles">>;
  /**
   * Optional non-mutating collection probe. Backends that can distinguish a
   * missing collection from a transient probe failure should implement this so
   * callers can avoid auto-creating collections in unsafe layouts.
   */
  checkCollection?(
    collectionOrExecution?: string | SearchExecutionOptions,
    execution?: SearchExecutionOptions
  ): Promise<"present" | "missing" | "unknown" | "skipped">;
  ensureCollection(
    memoryDir: string,
    execution?: SearchExecutionOptions
  ): Promise<"present" | "missing" | "unknown" | "skipped">;
  ensureCollection(
    memoryDir: string,
    collection?: string,
    execution?: SearchExecutionOptions
  ): Promise<"present" | "missing" | "unknown" | "skipped">;
}

import path from "node:path";
import { lstat, readdir, readFile, realpath } from "node:fs/promises";
import { RECALL_FALLBACK_DIRS } from "../utils/category-dir.js";
import { assertPathInsideRoot } from "../utils/path-containment.js";
import { isErrnoCode } from "../utils/errno.js";
import { isMacOsReplicationJunkBasename } from "../utils/macos-replication-junk.js";

export interface IndexableDocument {
  /** Memory ID from frontmatter or filename stem */
  docid: string;
  /** Absolute file path */
  path: string;
  /** Markdown body (no YAML frontmatter) */
  content: string;
  /** First ~200 chars for display */
  snippet: string;
}

/**
 * Parse YAML frontmatter from a markdown string.
 * Returns the frontmatter key-value pairs and body, or null if no frontmatter block.
 */
function parseFrontmatter(raw: string): { data: Record<string, string>; body: string } | null {
  // Support both LF and CRLF line endings
  const normalized = raw.replace(/\r\n/g, "\n");
  const match = normalized.match(/^---\n([\s\S]*?)\n---\n?([\s\S]*)$/);
  if (!match) return null;

  const fmBlock = match[1];
  const body = (match[2] ?? "").trim();
  const data: Record<string, string> = {};

  for (const line of fmBlock.split("\n")) {
    const colonIdx = line.indexOf(":");
    if (colonIdx === -1) continue;
    const key = line.slice(0, colonIdx).trim();
    const value = line.slice(colonIdx + 1).trim();
    data[key] = value;
  }

  return { data, body };
}

/**
 * Recursively scan a directory for `.md` files and return IndexableDocuments.
 */
async function scanDir(dir: string, memoryRootReal: string): Promise<IndexableDocument[]> {
  const docs: IndexableDocument[] = [];
  try {
    const dirStat = await lstat(dir);
    if (dirStat.isSymbolicLink()) {
      throw new Error(`Refusing to scan symlinked memory category directory: ${dir}`);
    }
    if (!dirStat.isDirectory()) {
      const error = new Error(`Memory category path is not a directory: ${dir}`) as NodeJS.ErrnoException;
      error.code = "ENOTDIR";
      throw error;
    }
    assertPathInsideRoot(memoryRootReal, await realpath(dir), dir);

    const entries = await readdir(dir, { withFileTypes: true });
    for (const entry of entries) {
      if (entry.isSymbolicLink()) continue;
      // QMD's indexer already skips hidden paths. This scanner is the
      // non-QMD index input and must ignore the same Finder metadata.
      if (isMacOsReplicationJunkBasename(entry.name)) continue;
      const fullPath = path.join(dir, entry.name);
      if (entry.isDirectory()) {
        assertPathInsideRoot(memoryRootReal, await realpath(fullPath), fullPath);
        const sub = await scanDir(fullPath, memoryRootReal);
        docs.push(...sub);
      } else if (entry.name.endsWith(".md")) {
        try {
          assertPathInsideRoot(memoryRootReal, await realpath(fullPath), fullPath);
          const raw = await readFile(fullPath, "utf-8");
          const parsed = parseFrontmatter(raw);
          const body = parsed ? parsed.body : raw.trim();
          const docid = parsed?.data.id || path.basename(entry.name, ".md");
          docs.push({
            docid,
            path: fullPath,
            content: body,
            snippet: body.slice(0, 200),
          });
        } catch {
          // Skip unreadable files
        }
      }
    }
  } catch (err) {
    if (isErrnoCode(err, "ENOENT")) {
      // Optional category directories may not exist yet.
      return docs;
    }
    throw err;
  }
  return docs;
}

/**
 * Scan every recall category subdir of memoryDir for indexable markdown
 * documents. The directory set is derived from `RECALL_FALLBACK_DIRS`
 * (utils/category-dir.ts → ALL_CATEGORY_DIRS minus non-recall queue dirs) —
 * the single source of truth — so adding a new category never requires
 * touching this scanner. Non-QMD backends (Orama / Meilisearch / LanceDB)
 * build their index through this helper; deriving from RECALL_FALLBACK_DIRS
 * keeps them in parity with writeMemory's category-dir routing (issue #1546)
 * and the QMD filesystem-fallback corpus. reasoning-traces/ and the other
 * category dirs are covered automatically (issue #564 PR 3 no longer needs a
 * hand-maintained list). scanDir tolerates missing dirs (ENOENT), so category
 * dirs that do not exist yet are skipped.
 */
export async function scanMemoryDir(memoryDir: string): Promise<IndexableDocument[]> {
  let memoryRootReal: string;
  try {
    memoryRootReal = await realpath(memoryDir);
  } catch (err) {
    if (isErrnoCode(err, "ENOENT")) {
      return [];
    }
    throw err;
  }
  const perDir = await Promise.all(
    RECALL_FALLBACK_DIRS.map((dir) => scanDir(path.join(memoryDir, dir), memoryRootReal)),
  );
  return perDir.flat();
}

import { throwIfAborted } from "../abort-error.js";
import type { SearchExecutionOptions } from "./port.js";

export function isSearchAborted(execution?: SearchExecutionOptions): boolean {
  return execution?.signal?.aborted === true;
}

export function throwIfSearchAborted(
  execution?: SearchExecutionOptions,
  message = "search operation aborted",
): void {
  throwIfAborted(execution?.signal, message);
}

export function withTimeoutSignal(signal: AbortSignal | undefined, timeoutMs: number): AbortSignal {
  const timeoutSignal = AbortSignal.timeout(timeoutMs);
  return signal ? AbortSignal.any([signal, timeoutSignal]) : timeoutSignal;
}

import { expandUnsegmentableRecallNGrams, isUnsegmentableRecallChar } from "../recall-tokenization.js";

/**
 * Language marker persisted inside Orama index files (`.msp`). Orama persists
 * `tokenizer.language` with the index, so this doubles as the tokenization
 * version: `OramaBackend` detects any other marker on restore and rebuilds
 * the full-text index (issue #2187). Bump the suffix whenever tokenization
 * changes.
 */
export const ORAMA_CJK_TOKENIZER_LANGUAGE = "english+cjk-v1";

/** Minimal structural surface of `@orama/orama` this module consumes. */
export interface OramaTokenizerComponents {
  components: {
    tokenizer: {
      createTokenizer: (config: { language: string }) => OramaTokenizer;
    };
  };
}

export interface OramaTokenizer {
  language: string;
  normalizationCache: Map<string, string>;
  tokenize: (raw: string, language?: string, prop?: string, withCache?: boolean) => string[];
}

const THAI_SCRIPT_CHAR = /[\p{Script=Thai}]/u;
const WORD_CHAR = /[\p{L}\p{N}\p{M}]/u;
const COMBINING_MARK = /\p{M}/u;
const WHITESPACE_CHAR = /\s/u;
/**
 * Chars the stock English tokenizer keeps inside a token. Input made only of
 * these (plus whitespace) is delegated to the stock tokenizer byte-for-byte so
 * existing English indexes stay term-compatible.
 */
const LEGACY_TOKENIZER_CHAR = /[A-Za-zàèéìòóù0-9_'-]/u;

/**
 * Space-free scripts: CJK per the shared recall segmentation strategy, plus
 * Thai. Runs in these scripts are indexed as character n-grams so phrase
 * queries match without word boundaries.
 */
export function isSpaceFreeScriptChar(char: string): boolean {
  return isUnsegmentableRecallChar(char) || THAI_SCRIPT_CHAR.test(char);
}

/**
 * True when tokenizing the value differs from the stock English tokenizer —
 * i.e. the value contains characters outside the stock keep-set that this
 * tokenizer still indexes as token material: word characters (whole-word
 * non-ASCII scripts), combining marks (attached to runs), and space-free
 * scripts (CJK/Thai n-grams). Symbols and punctuation that are separators in
 * BOTH tokenizers do not count. `OramaBackend` uses this to decide whether a
 * stale pre-CJK index needs re-indexing on upgrade.
 */
export function containsNonLegacyTokenizerChars(value: string): boolean {
  for (const ch of value) {
    if (LEGACY_TOKENIZER_CHAR.test(ch) || WHITESPACE_CHAR.test(ch)) continue;
    if (WORD_CHAR.test(ch) || COMBINING_MARK.test(ch) || isSpaceFreeScriptChar(ch)) {
      return true;
    }
  }
  return false;
}

/**
 * Orama tokenizer component that segments space-free scripts (CJK, Thai).
 *
 * - CJK/Thai runs expand to the same n-gram set the recall query-side
 *   tokenizer (`recall-tokenization.ts`) produces, so index-side and
 *   query-side tokens agree.
 * - Other non-Latin scripts (Hangul, Cyrillic, Greek, Arabic, ...) are kept
 *   as whole words instead of being dropped by the English splitter.
 * - Legacy Latin content tokenizes exactly like the stock English tokenizer;
 *   content with other characters keeps every stock token and additionally
 *   indexes non-ASCII words whole (e.g. "über" adds "über" beside "ber").
 */
export function createCjkCapableTokenizer(oramaModule: OramaTokenizerComponents): OramaTokenizer {
  const base = oramaModule.components.tokenizer.createTokenizer({ language: "english" });

  const tokenize = (raw: string, _language?: string, prop?: string, withCache?: boolean): string[] => {
    if (typeof raw !== "string") return [];
    const normalized = raw.normalize("NFC");

    if (!containsNonLegacyTokenizerChars(normalized)) {
      return base.tokenize(normalized, "english", prop, withCache);
    }

    // The stock tokenizer treats every non-legacy char as a separator, so its
    // output over the raw input already carries the legacy-Latin tokens
    // (e.g. the "nebula-472" in "Nebula-472 東京都庁").
    const tokens = base.tokenize(normalized, "english", prop, withCache);
    const seen = new Set(tokens);

    const pushToken = (token: string) => {
      if (token && !seen.has(token)) {
        seen.add(token);
        tokens.push(token);
      }
    };

    let spaceFreeRun = "";
    let wordRun = "";
    const flushSpaceFreeRun = () => {
      if (!spaceFreeRun) return;
      for (const token of expandUnsegmentableRecallNGrams(spaceFreeRun)) {
        pushToken(token);
      }
      spaceFreeRun = "";
    };
    const flushWordRun = () => {
      if (!wordRun) return;
      pushToken(wordRun.toLowerCase());
      wordRun = "";
    };

    for (const ch of normalized) {
      if (isSpaceFreeScriptChar(ch)) {
        flushWordRun();
        spaceFreeRun += ch;
      } else if (COMBINING_MARK.test(ch)) {
        if (spaceFreeRun) spaceFreeRun += ch;
        else if (wordRun) wordRun += ch;
      } else if (WORD_CHAR.test(ch) && !LEGACY_TOKENIZER_CHAR.test(ch)) {
        flushSpaceFreeRun();
        wordRun += ch;
      } else {
        flushSpaceFreeRun();
        flushWordRun();
      }
    }
    flushSpaceFreeRun();
    flushWordRun();

    return tokens;
  };

  return {
    language: ORAMA_CJK_TOKENIZER_LANGUAGE,
    normalizationCache: base.normalizationCache,
    tokenize,
  };
}

import { abortError, throwIfAborted } from "./abort-error.js";
import { log } from "./logger.js";
import { type CommandChildProcess, launchProcess } from "./runtime/child-process.js";
import { mergeEnv } from "./runtime/env.js";
import { sleep } from "./utils/sleep.js";

export type QmdRuntimeEnv = Record<string, string | undefined>;

export type QmdDaemonSpawn = (
  command: string,
  args: string[],
  options?: Record<string, unknown>
) => CommandChildProcess;

type PendingRequest = {
  resolve: (value: unknown) => void;
  reject: (reason: Error) => void;
  timer: ReturnType<typeof setTimeout>;
  cleanup: () => void;
};

let nextJsonRpcId = 1;

/**
 * Drop C0 controls and one ANSI CSI sequence. Char scan on purpose:
 * the regex-safety ratchet flags new regular expressions on changed lines.
 */
function sanitizeForLog(value: string, max = 200): string {
  let out = "";
  const cap = Math.min(value.length, max);
  for (let i = 0; i < cap; i++) {
    const code = value.charCodeAt(i);
    if (code === 0x1b && value.charCodeAt(i + 1) === 0x5b) {
      i += 2;
      while (i < cap) {
        const next = value.charCodeAt(i);
        const isLetter = (next >= 65 && next <= 90) || (next >= 97 && next <= 122);
        if (isLetter) break;
        i += 1;
      }
      continue;
    }
    if (code < 0x20 || code === 0x7f) continue;
    out += value[i] ?? "";
  }
  if (value.length > max) return `${out}…(truncated)`;
  return out;
}

function isTimeoutMessage(message: string): boolean {
  return message.toLowerCase().includes("timed out");
}

/**
 * One `qmd mcp` child and its JSON-RPC session.
 *
 * Aborting or timing out a `tools/call` writes MCP `notifications/cancelled`
 * and rejects the caller immediately. The SDK drops the tool result once the
 * server's request controller is aborted, so this session does not wait for
 * a response after cancel. The initialize handshake is not cancelled: a slow
 * model load is supposed to stay alive for the next probe.
 *
 * The child is not killed on cancel. Reloading the rerank model costs longer
 * than the recall budget, and a slow query would then take the warm process
 * down on every timeout.
 */
export class QmdDaemonSession {
  private child: CommandChildProcess | null = null;
  private initialized = false;
  private buffer = "";
  private startPromise: Promise<boolean> | null = null;
  private pendingRequests = new Map<number, PendingRequest>();
  private readonly qmdPath: string;
  private readonly runtimeEnv: QmdRuntimeEnv;
  private readonly indexName?: string;
  private readonly spawn: QmdDaemonSpawn;

  constructor(
    qmdPath: string,
    runtimeEnv: QmdRuntimeEnv = {},
    indexName?: string,
    spawn: QmdDaemonSpawn = launchProcess
  ) {
    this.qmdPath = qmdPath;
    this.runtimeEnv = runtimeEnv;
    this.indexName = indexName?.trim() || undefined;
    this.spawn = spawn;
  }

  /** Spawn the qmd mcp child process and perform MCP handshake. */
  async start(): Promise<boolean> {
    if (this.child && !this.child.killed && this.initialized) {
      return true;
    }
    if (this.startPromise) {
      return this.startPromise;
    }
    this.startPromise = (async () => {
      const processAlreadyRunning = this.child != null && !this.child.killed;
      if (!processAlreadyRunning) {
        if (this.child) {
          this.cleanup({ killChild: true });
        }
        try {
          const args = this.indexName ? ["--index", this.indexName, "mcp"] : ["mcp"];
          const child = this.spawn(this.qmdPath, args, {
            env: mergeEnv({ NO_COLOR: "1", ...this.runtimeEnv }),
            stdio: ["pipe", "pipe", "pipe"],
          });
          this.child = child;
          this.buffer = "";

          child.stdout?.on("data", (data: Buffer) => {
            if (this.child !== child) return;
            this.handleStdoutData(data);
          });
          child.stderr?.on("data", (data: Buffer) => {
            if (this.child !== child) return;
            const msg = data.toString().trim();
            if (msg) log.debug(`QMD mcp stderr: ${sanitizeForLog(msg)}`);
          });
          child.stdin?.on("error", (err) => {
            log.debug(`QMD mcp stdin error (suppressed): ${err.message}`);
          });
          child.on("error", (err) => {
            if (this.child !== child) return;
            log.debug(`QMD mcp process error: ${err.message}`);
            this.cleanup({ child });
          });
          child.on("close", (code) => {
            if (this.child !== child) return;
            log.debug(`QMD mcp process exited (code ${code})`);
            this.cleanup({ child });
          });
        } catch (err) {
          log.debug(`QMD mcp: failed to spawn process: ${err}`);
          this.cleanup({ killChild: true });
          return false;
        }
      } else {
        log.debug("QMD mcp: process already running, retrying handshake");
      }

      try {
        const result = await this.sendRequest(
          "initialize",
          {
            protocolVersion: "2024-11-05",
            capabilities: {},
            clientInfo: { name: "openclaw-remnic", version: "1.0.0" },
          },
          60_000
        );
        if (!result) {
          this.cleanup({ killChild: true });
          return false;
        }
        this.sendNotification("notifications/initialized");
        this.initialized = true;
        log.info("QMD mcp: stdio session initialized");
        return true;
      } catch (err) {
        const msg = err instanceof Error ? err.message : String(err);
        if (isTimeoutMessage(msg)) {
          log.debug("QMD mcp: handshake timed out — process still loading, will retry later");
          this.initialized = false;
        } else {
          log.debug(`QMD mcp: failed to start stdio session: ${err}`);
          this.cleanup({ killChild: true });
        }
        return false;
      } finally {
        this.startPromise = null;
      }
    })();
    return this.startPromise;
  }

  /** Call an MCP tool and return the parsed result. */
  async callTool(
    name: string,
    args: Record<string, unknown>,
    timeoutMs = 30_000,
    signal?: AbortSignal
  ): Promise<unknown> {
    if (!this.child || this.child.killed || !this.initialized) {
      throw new Error("QMD mcp process not running");
    }
    return this.sendRequest("tools/call", { name, arguments: args }, timeoutMs, signal);
  }

  /** Kill stdio process and clear state so the next probe can restart. */
  invalidate(): void {
    this.cleanup({ killChild: true });
  }

  /** Kill stdio process and wait briefly for the child handle to close. */
  async close(timeoutMs = 1_000): Promise<void> {
    const target = this.child;
    if (!target) {
      this.cleanup({ killChild: true });
      return;
    }

    let closed = false;
    const closedPromise = new Promise<void>((resolve) => {
      target.once("close", () => {
        closed = true;
        resolve();
      });
    });

    this.cleanup({ killChild: true });
    await Promise.race([closedPromise, sleep(timeoutMs)]);
    if (!closed) {
      try {
        target.kill("SIGKILL");
      } catch {
        // Ignore process-kill races during shutdown.
      }
      await Promise.race([closedPromise, sleep(250)]);
    }
  }

  isActive(): boolean {
    return this.child !== null && !this.child.killed && this.initialized;
  }

  /** True while the process is spawned but the MCP handshake has not yet completed. */
  isLoading(): boolean {
    return this.child !== null && !this.child.killed && !this.initialized;
  }

  private sendRequest(
    method: string,
    params: Record<string, unknown>,
    timeoutMs: number,
    signal?: AbortSignal
  ): Promise<unknown> {
    return new Promise((resolve, reject) => {
      throwIfAborted(signal, `QMD mcp ${method} aborted before request`);
      if (!this.child || !this.child.stdin || this.child.killed) {
        reject(new Error("QMD mcp process not available"));
        return;
      }

      const id = nextJsonRpcId++;
      let written = false;
      const abandon = (reason: string) => {
        // Only a tool call that actually went out can be holding the worker.
        // initialize stays running across a slow model load.
        if (!written || method !== "tools/call") return;
        this.sendNotification("notifications/cancelled", { requestId: id, reason });
      };
      const timer = setTimeout(() => {
        this.pendingRequests.delete(id);
        cleanup();
        const reason = `QMD mcp ${method} timed out after ${timeoutMs}ms`;
        abandon(reason);
        reject(new Error(reason));
      }, timeoutMs);
      const onAbort = () => {
        clearTimeout(timer);
        this.pendingRequests.delete(id);
        cleanup();
        abandon("client aborted");
        reject(abortError(`QMD mcp ${method} aborted`));
      };
      const cleanup = () => {
        signal?.removeEventListener("abort", onAbort);
      };

      this.pendingRequests.set(id, { resolve, reject, timer, cleanup });
      signal?.addEventListener("abort", onAbort, { once: true });
      const message = `${JSON.stringify({ jsonrpc: "2.0", id, method, params })}\n`;
      try {
        this.child.stdin.write(message, (err) => {
          if (!err) return;
          written = false;
          clearTimeout(timer);
          this.pendingRequests.delete(id);
          cleanup();
          reject(new Error(`Failed to write to QMD mcp stdin: ${err.message}`));
        });
        written = true;
      } catch (err) {
        written = false;
        clearTimeout(timer);
        this.pendingRequests.delete(id);
        cleanup();
        const messageText = err instanceof Error ? err.message : String(err);
        reject(new Error(`Failed to write to QMD mcp stdin: ${messageText}`));
      }
    });
  }

  private sendNotification(method: string, params?: Record<string, unknown>): void {
    if (!this.child || !this.child.stdin || this.child.killed) return;
    if (this.child.stdin.destroyed) return;
    const msg: Record<string, unknown> = { jsonrpc: "2.0", method };
    if (params) msg.params = params;
    try {
      this.child.stdin.write(`${JSON.stringify(msg)}\n`);
    } catch {
      // Ignore EPIPE / write-after-close
    }
  }

  private handleStdoutData(data: Buffer | string): void {
    this.buffer += data.toString();
    let newlineIdx: number;
    // Re-evaluated on every pass so a blank line cannot leave a stale index.
    while ((newlineIdx = this.buffer.indexOf("\n")) !== -1) {
      const line = this.buffer.slice(0, newlineIdx).trim();
      this.buffer = this.buffer.slice(newlineIdx + 1);
      if (!line) continue;
      try {
        const msg = JSON.parse(line) as Record<string, unknown>;
        this.handleMessage(msg);
      } catch {
        log.debug(`QMD mcp: unparseable stdout: ${sanitizeForLog(line, 200)}`);
      }
    }
  }

  private handleMessage(msg: Record<string, unknown>): void {
    if (msg.id !== undefined && msg.id !== null) {
      const pending = this.pendingRequests.get(msg.id as number);
      if (pending) {
        clearTimeout(pending.timer);
        this.pendingRequests.delete(msg.id as number);
        pending.cleanup();
        if (msg.error) {
          pending.reject(new Error(JSON.stringify(msg.error)));
        } else {
          pending.resolve(msg.result);
        }
      }
      return;
    }
    if (msg.method) {
      log.debug(`QMD mcp notification: ${msg.method}`);
    }
  }

  private cleanup(opts?: { killChild?: boolean; child?: CommandChildProcess | null }): void {
    const target = opts?.child ?? this.child;
    if (!target) return;
    if (opts?.child && this.child !== opts.child) {
      return;
    }
    if (opts?.killChild && !target.killed) {
      target.kill("SIGTERM");
    }
    this.initialized = false;
    for (const [, pending] of this.pendingRequests) {
      clearTimeout(pending.timer);
      pending.cleanup();
      pending.reject(new Error("QMD mcp process terminated"));
    }
    this.pendingRequests.clear();
    this.startPromise = null;
    this.child = null;
    this.buffer = "";
  }
}

import { abortError } from "./abort-error.js";

/**
 * One in-flight daemon search shared by identical callers.
 * The shared signal aborts only when every waiter has aborted, which is
 * what tells the QMD process to stop. One caller giving up must not cancel
 * a sibling that still wants the result.
 */
export type InflightJoiner<T> = {
  join(key: string, signal: AbortSignal | undefined, run: (signal: AbortSignal) => Promise<T>): Promise<T>;
};

type InflightSlot<T> = {
  controller: AbortController;
  refs: number;
  promise: Promise<T>;
};

export function createInflightJoiner<T>(): InflightJoiner<T> {
  const slots = new Map<string, InflightSlot<T>>();

  return {
    join(key, signal, run) {
      if (signal?.aborted) {
        return Promise.reject(abortError("QMD inflight search aborted"));
      }
      let slot = slots.get(key);
      // A slot whose last waiter already aborted is doomed; its promise settles
      // late. Never hand it to a new caller.
      if (slot?.controller.signal.aborted) slot = undefined;
      if (!slot) {
        const controller = new AbortController();
        const created: InflightSlot<T> = {
          controller,
          refs: 0,
          promise: Promise.resolve() as Promise<T>,
        };
        slots.set(key, created);
        created.promise = new Promise<T>((resolve, reject) => {
          try {
            resolve(run(controller.signal));
          } catch (err) {
            reject(err);
          }
        }).finally(() => {
          if (slots.get(key) === created) slots.delete(key);
        });
        // A cancel with no remaining waiter rejects this promise after the
        // waiter has already settled. Swallow that so it is not unhandled.
        created.promise.catch(() => {});
        slot = created;
      }
      return attachWaiter(slot, signal);
    },
  };
}

function attachWaiter<T>(slot: InflightSlot<T>, signal?: AbortSignal): Promise<T> {
  if (signal?.aborted) {
    return Promise.reject(abortError("QMD inflight search aborted"));
  }
  slot.refs += 1;
  let settled = false;

  return new Promise<T>((resolve, reject) => {
    const finish = (abortShared: boolean, settle: () => void) => {
      if (settled) return;
      settled = true;
      if (onAbort) signal?.removeEventListener("abort", onAbort);
      slot.refs -= 1;
      if (slot.refs < 0) slot.refs = 0;
      if (abortShared && slot.refs === 0) {
        slot.controller.abort();
      }
      settle();
    };
    const onAbort = () => {
      finish(true, () => reject(abortError("QMD inflight search aborted")));
    };
    if (signal) {
      signal.addEventListener("abort", onAbort, { once: true });
      if (signal.aborted) {
        onAbort();
        return;
      }
    }
    slot.promise.then(
      (value) => finish(false, () => resolve(value)),
      (err) => finish(false, () => reject(err))
    );
  });
}

/**
 * Score documents on a shared cursor and stop between documents when
 * `signal` aborts. In-flight `rankIndex` calls finish; later indexes
 * are not started. A cancelled batch throws and does not return scores.
 *
 * `docs/patches/qmd-2.8.3-mcp-cancel.patch` uses the same loop inside
 * QMD's reranker. `rank()` and `rankAll()` share one evaluate path, so
 * a document that finishes has the same score either way.
 */
export async function rankDocumentsUntilAbortParallel<T>(
  count: number,
  parallelism: number,
  signal: AbortSignal | undefined,
  rankIndex: (index: number) => Promise<T>
): Promise<T[]> {
  if (signal?.aborted) {
    throw abortError("qmd rerank aborted");
  }
  if (count <= 0) return [];
  const scores = new Array<T>(count);
  let cursor = 0;
  const workers = Math.max(1, Math.min(Math.floor(parallelism) || 1, count));
  await Promise.all(
    Array.from({ length: workers }, async () => {
      while (true) {
        if (signal?.aborted) return;
        const index = cursor++;
        if (index >= count) return;
        scores[index] = await rankIndex(index);
      }
    })
  );
  if (signal?.aborted) {
    throw abortError("qmd rerank aborted");
  }
  return scores;
}

/**
 * QMD version-check PREFLIGHT / probe-classification helpers.
 *
 * Pure, self-contained functions extracted from qmd.ts (issue #1841) so the
 * QmdClient class file stays under the structural-ratchet LOC ceiling. These
 * cover two related concerns of the startup preflight:
 *
 * 1. VERSION parsing/comparison — turning `qmd --version` output into a tuple,
 *    comparing against the supported target, and resolving feature capability
 *    flags from the parsed version.
 * 2. PROBE failure classification — distinguishing a slow/overloaded binary
 *    (transient → retry) from a genuine misconfiguration (ENOENT/EACCES → fail
 *    fast) using STRUCTURED signals, never the error message.
 *
 * No behavioral change from qmd.ts round 1 (issue #1841): structured-signal
 * classification (code=ENOENT/EACCES=>missing, timedOut flag=>transient,
 * caller-cancel silenced, non-zero-exit=>other); backoff [300,800].
 */
import { isAbortError } from "./abort-error.js";
import type { QmdCapabilities, QmdVersionTuple } from "./qmd.js";

// Deadline (ms) for a single `qmd --version` probe.
export const QMD_PROBE_TIMEOUT_MS = 8_000;

// Backoff schedule (ms) for retrying a TRANSIENT (timeout/abort) version-check
// probe of a CONFIGURED qmdPath before declaring it failed. A binary that
// resolved and ran before is more likely slow under load than gone, so we retry
// transient failures but NOT ENOENT/EACCES (hard misconfiguration, fail fast).
// Length == number of retries after the initial attempt. Issue #1841.
export const QMD_PROBE_RETRY_BACKOFF_MS = [300, 800];

export const QMD_SUPPORTED_VERSION = "2.8.3";

/**
 * Classify a `qmd --version` probe failure so the preflight can distinguish a
 * slow/overloaded binary (a genuine deadline timeout) from a real
 * misconfiguration (ENOENT/EACCES — the configured path is missing or not
 * executable). Only transient failures are retried; missing binaries fail fast.
 *
 * Classification keys on STRUCTURED signals, never the error *message*: a
 * non-zero-exit failure embeds the child's stderr in its message, so scanning
 * that text for "abort"/"timed out"/"not found" would misclassify a healthy
 * binary. The structured signals are: `code` (ENOENT/EACCES) for missing; the
 * `timedOut` flag set by `runCommandWithTimeout` for a genuine timeout; an
 * AbortError name for a deadline/abort under load. Issue #1841.
 */
export type QmdProbeFailureKind = "transient" | "missing" | "other";
export function classifyProbeFailure(err: unknown): QmdProbeFailureKind {
  if (err && typeof err === "object") {
    // Node spawn failures carry a structured `code`: ENOENT (not found) /
    // EACCES (not executable).
    if ("code" in err) {
      const code = err.code;
      if (code === "ENOENT" || code === "EACCES") return "missing";
    }
    // runCommandWithTimeout flags a genuine deadline breach with `timedOut`.
    if ("timedOut" in err && err.timedOut === true) return "transient";
  }
  // An AbortError reaching here is a deadline/abort under load → transient.
  // (Caller cancellation is intercepted by the retry loop before this runs.)
  if (isAbortError(err)) return "transient";
  // Anything else — including a non-zero exit whose message embeds stderr — is
  // a generic failure: never scan the message to upgrade/downgrade it.
  return "other";
}

export function parseQmdVersion(version: string | null): QmdVersionTuple | null {
  if (!version) return null;
  const match = version.match(/v?(\d{1,10})\.(\d{1,10})\.(\d{1,10})/i);
  if (!match) return null;
  return [
    Number.parseInt(match[1] ?? "0", 10),
    Number.parseInt(match[2] ?? "0", 10),
    Number.parseInt(match[3] ?? "0", 10),
  ];
}

export function parseQmdVersionOutput(stdout: string, stderr: string): string | null {
  const lines = `${stdout}\n${stderr}`
    .split("\n")
    .map((s) => s.trim())
    .filter((s) => s.length > 0);
  if (lines.length === 0) return null;
  const semanticLines = lines.filter((line) => parseQmdVersion(line) !== null);
  if (semanticLines.length === 0) return lines[0] ?? null;
  return semanticLines.find((line) => /\bqmd\b/i.test(line)) ?? semanticLines[0] ?? null;
}

export function compareQmdVersions(left: QmdVersionTuple | null, right: QmdVersionTuple | null): number {
  if (!left && !right) return 0;
  if (!left) return -1;
  if (!right) return 1;
  for (let i = 0; i < 3; i += 1) {
    if ((left[i] ?? 0) > (right[i] ?? 0)) return 1;
    if ((left[i] ?? 0) < (right[i] ?? 0)) return -1;
  }
  return 0;
}

export function versionAtLeast(current: QmdVersionTuple | null, target: QmdVersionTuple): boolean {
  return compareQmdVersions(current, target) >= 0;
}

export function resolveQmdCapabilities(version: string | null): QmdCapabilities {
  const parsedVersion = parseQmdVersion(version);
  const atLeast = (target: QmdVersionTuple): boolean => versionAtLeast(parsedVersion, target);
  return {
    version,
    parsedVersion,
    stableSdk: atLeast([2, 0, 0]),
    unifiedSearch: atLeast([2, 0, 0]),
    getDocumentBody: atLeast([2, 0, 0]),
    maintenanceApi: atLeast([2, 0, 0]),
    legacySkillInstall: atLeast([2, 0, 1]),
    intentHints: atLeast([1, 1, 5]),
    explainTraces: atLeast([1, 1, 2]),
    candidateLimit: atLeast([1, 1, 2]),
    v2McpQueryTool: atLeast([2, 0, 0]),
    structuredSearches: atLeast([2, 0, 0]),
    queryRerankToggle: atLeast([2, 1, 0]),
    chunkStrategy: atLeast([2, 1, 0]),
    qmdBench: atLeast([2, 1, 0]),
    perCollectionModels: atLeast([2, 1, 0]),
    jsonLineNumbers: atLeast([2, 1, 0]),
    editorLinks: atLeast([2, 1, 0]),
    doctor: atLeast([2, 5, 0]),
    versionedSkills: atLeast([2, 5, 0]),
    absoluteSnippetLines: atLeast([2, 5, 0]),
    fullQueryOutput: atLeast([2, 5, 0]),
    forceCpu: atLeast([2, 5, 0]),
    gpuBackendOverride: atLeast([2, 5, 0]),
    embedParallelism: atLeast([2, 5, 0]),
    modelEnvConsistency: atLeast([2, 5, 0]),
    scopedEmbed: atLeast([2, 5, 0]),
    safeStatusDeviceProbe: atLeast([2, 5, 0]),
    mcpIndexSelection: atLeast([2, 5, 0]),
    outputFormatFlag: atLeast([2, 5, 3]),
  };
}

export function shouldAutoUpgradeQmd(
  installedVersion: string | null,
  supportedVersion: string = QMD_SUPPORTED_VERSION
): boolean {
  const installed = parseQmdVersion(installedVersion);
  const supported = parseQmdVersion(supportedVersion);
  if (!installed || !supported) return false;
  return compareQmdVersions(installed, supported) < 0;
}

/** First QMD release that needs the pinned, patched build (docs/qmd-2.8.3.md); stock npm lacks the patches. */
const QMD_PATCHED_BUILD_MIN: QmdVersionTuple = [2, 8, 3];

/** False when `npm install -g @tobilu/qmd@<supported>` would install stock QMD instead of the patched build. */
export function autoUpgradeInstallsStockPackage(supportedVersion: string): boolean {
  const supported = parseQmdVersion(supportedVersion);
  return supported !== null && compareQmdVersions(supported, QMD_PATCHED_BUILD_MIN) < 0;
}

export function getQmdPostInstallProbeTargets(
  qmdPath: string,
  qmdPathSource: "configured" | "auto-path" | "auto-fallback"
): Array<{ qmdPath: string; source: "auto-path" | "auto-fallback" }> {
  const targets: Array<{ qmdPath: string; source: "auto-path" | "auto-fallback" }> = [
    { qmdPath: "qmd", source: "auto-path" },
  ];
  const normalizedPath = qmdPath.trim();
  if (qmdPathSource === "auto-fallback" && normalizedPath.length > 0 && normalizedPath !== "qmd") {
    targets.push({ qmdPath: normalizedPath, source: "auto-fallback" });
  }
  return targets;
}

export function qmdVersionToString(version: QmdVersionTuple): string {
  return `${version[0]}.${version[1]}.${version[2]}`;
}

/**
 * QMD status parsing and backlog reporting helpers.
 *
 * Extracted from qmd.ts to keep that module under its structural ceiling.
 * Issue #2019: expose embedding backlog metrics in health and CLI surfaces.
 */

export interface QmdStatusReport {
  totalFiles: number | null;
  embeddedFiles: number | null;
  pendingEmbeddings: number | null;
  /** Age in ms of the oldest file still pending embedding, or null if unavailable. */
  oldestPendingAgeMs: number | null;
  /** Raw text output from `qmd status` for debugging. */
  raw: string;
  /** Error message when the status command fails, if any. */
  error?: string;
}

/** Minimal interface for backends that expose QMD status. */
export interface QmdStatusCapable {
  status(): Promise<QmdStatusReport>;
}

/**
 * Parse `qmd status -c <collection>` text output into structured metrics.
 * Handles formats like:
 *   Total files: 200129
 *   Embedded: 189091 (94.5%)
 *   Pending embedding: 108186
 * Returns null fields for unparseable or missing lines.
 */
function parseLeadingInt(s: string): number | null {
  let digits = "";
  for (const ch of s) {
    if (ch >= "0" && ch <= "9") digits += ch;
    else if (ch === "," && digits.length > 0) continue;
    else break;
  }
  return digits.length > 0 ? Number.parseInt(digits, 10) : null;
}

function parseLeadingDurationMs(s: string): number | null {
  let digits = "";
  let i = 0;
  for (; i < s.length; i++) {
    if (s[i] >= "0" && s[i] <= "9") digits += s[i];
    else break;
  }
  if (digits.length === 0) return null;
  const val = Number.parseInt(digits, 10);
  const unit = s.slice(i).trim();
  if (unit === "ms") return val;
  if (unit === "s") return val * 1000;
  if (unit === "m") return val * 60_000;
  if (unit === "h") return val * 3_600_000;
  return null;
}

export function parseQmdStatusOutput(stdout: string): QmdStatusReport {
  const raw = stdout;
  let totalFiles: number | null = null;
  let embeddedFiles: number | null = null;
  let pendingEmbeddings: number | null = null;
  let oldestPendingAgeMs: number | null = null;

  for (const rawLine of stdout.split("\n")) {
    const line = rawLine.trim().toLowerCase();
    const colonIdx = line.indexOf(":");
    if (colonIdx === -1) continue;
    const key = line.slice(0, colonIdx).trim();
    const value = line.slice(colonIdx + 1).trim();

    if (key === "total" || key === "total files" || key === "total file") {
      totalFiles = parseLeadingInt(value);
    } else if (key === "vectors" || key === "embedded") {
      embeddedFiles = parseLeadingInt(value);
    } else if (key === "oldest pending") {
      oldestPendingAgeMs = parseLeadingDurationMs(value);
    } else if (key.startsWith("pending")) {
      pendingEmbeddings = parseLeadingInt(value);
    }
  }

  return { totalFiles, embeddedFiles, pendingEmbeddings, oldestPendingAgeMs, raw };
}

/** Empty status report returned when QMD is unavailable or the command fails. */
export const EMPTY_QMD_STATUS: QmdStatusReport = {
  totalFiles: null,
  embeddedFiles: null,
  pendingEmbeddings: null,
  oldestPendingAgeMs: null,
  raw: "",
};

/**
 * Format backlog lines from a pre-resolved status report.
 * Returns display strings for CLI output; empty array when unavailable.
 */
export function formatBacklogLinesFromReport(
  report: QmdStatusReport | null | undefined,
  threshold: number,
): string[] {
  if (!report) return [];
  const lines: string[] = [];

  if (report.pendingEmbeddings != null) {
    lines.push(`  Pending embeddings: ${report.pendingEmbeddings}`);
    if (threshold > 0 && report.pendingEmbeddings > threshold) {
      lines.push(`  ⚠ Embedding backlog exceeds threshold (${threshold}) — degraded`);
    }
  }

  if (report.oldestPendingAgeMs != null) {
    const ageMin = Math.round(report.oldestPendingAgeMs / 60_000);
    lines.push(`  Oldest pending: ${ageMin}m`);
  }

  return lines;
}

/**
 * Fetch QMD status and format backlog lines for CLI output.
 * Returns empty array when the backend lacks status() or the call fails.
 */
export async function renderQmdBacklogStatus(
  qmd: unknown,
  threshold: number,
): Promise<string[]> {
  const backend = qmd as Partial<QmdStatusCapable> | null;
  if (!backend || typeof backend.status !== "function") return [];
  try {
    const report = await Promise.race([
      backend.status(),
      new Promise<null>((resolve) => setTimeout(() => resolve(null), 5_000).unref?.()),
    ]);
    if (!report) return [];
    return formatBacklogLinesFromReport(report, threshold);
  } catch {
    return [];
  }
}

export type QmdCommandRunner = (args: string[], timeoutMs: number) => Promise<{ stdout: string; stderr: string }>;

/**
 * Fetch QMD collection status via the `qmd status` command. Returns an
 * unavailable report (with `error` set) when the command fails.
 */
export async function fetchQmdStatus(
  runQmdCommand: QmdCommandRunner,
  collection: string,
  timeoutMs: number,
): Promise<QmdStatusReport> {
  try {
    const { stdout } = await runQmdCommand(["status", "-c", collection], timeoutMs);
    return parseQmdStatusOutput(stdout);
  } catch (error) {
    return { ...EMPTY_QMD_STATUS, error: error instanceof Error ? error.message : String(error) };
  }
}

/**
 * Trigger a collection-level embed run via `qmd embed -c <collection>`.
 * The QMD CLI does not support per-file embed targeting; this triggers
 * embedding for all pending files in the collection. The prioritized-embed
 * module debounces and batches these triggers so fresh writes become
 * searchable within minutes without hammering the CLI on every write.
 * Returns `{ ok: false }` on failure so callers can reschedule without crashing.
 */
export async function embedQmdFiles(
  runQmdCommand: QmdCommandRunner,
  collection: string,
  _filePaths: string[],
  timeoutMs: number,
  embedArgs?: string[],
): Promise<{ ok: boolean; error?: string }> {
  try {
    await runQmdCommand(["update", "-c", collection], timeoutMs);
    await runQmdCommand(embedArgs ?? ["embed", "-c", collection], timeoutMs);
    return { ok: true };
  } catch (error) {
    return { ok: false, error: error instanceof Error ? error.message : String(error) };
  }
}

import { log } from "../logger.js";
