// ── hashing ────────────────────────────────────────────────────────────────

function sha256Hex(value: string): string {
  return createHash("sha256").update(value, "utf8").digest("hex");
}

/** Deterministic JSON: sorted keys, so field order never changes a hash. */
function canonicalJson(value: unknown): string {
  if (value === null || typeof value !== "object") return JSON.stringify(value);
  if (Array.isArray(value)) return `[${value.map(canonicalJson).join(",")}]`;
  const entries = Object.entries(value as Record<string, unknown>)
    .filter(([, v]) => v !== undefined)
    .sort(([a], [b]) => (a < b ? -1 : a > b ? 1 : 0))
    .map(([k, v]) => `${JSON.stringify(k)}:${canonicalJson(v)}`);
  return `{${entries.join(",")}}`;
}

function hashSnapshot(snapshot: ActiveContextSnapshot): string {
  return sha256Hex(
    canonicalJson({
      namespace: snapshot.namespace,
      revision: snapshot.revision,
      sessionKey: snapshot.sessionKey,
      messages: snapshot.messages.map((m) => ({
        contentHash: sha256Hex(m.content),
        id: m.id,
        ordinal: m.ordinal,
        role: m.role,
      })),
    }),
  );
}

// ── shared validation ──────────────────────────────────────────────────────

interface PlanContext {
  caps: ActiveContextCapabilitySet;
  scope: ActiveContextResolvedScope;
  snapshotRevision: string | number;
  byId: Map<string, ActiveContextMessage>;
  ordered: ActiveContextMessage[];
  snapshotContentHash: string;
  generatedAt: string;
  expiresAt: string;
}

const VALID_PHASES: Record<string, true> = { plan: true, prepare: true };
const VALID_ROLES: Record<string, true> = {
  system: true,
  developer: true,
  user: true,
  assistant: true,
  tool: true,
};

function rejectedPlan(
  operation: ActiveContextOperation,
  errorCode: ActiveContextErrorCode,
  context: PlanContext | null,
  policy: { decision: "allow" | "deny"; rationale: string },
): ActiveContextTransformPlan {
  const planId = `actx-rejected-${sha256Hex(`${operation}:${errorCode}:${policy.rationale}`).slice(0, 12)}`;
  return {
    schemaVersion: ACTIVE_CONTEXT_PLAN_SCHEMA_VERSION,
    planId,
    planHash: sha256Hex(canonicalJson({ planId, errorCode, operation })),
    operation,
    status: "rejected",
    errorCode,
    precondition: context
      ? {
          principal: context.scope.principal,
          sessionKey: context.scope.sessionKey,
          namespace: context.scope.namespace,
          adapterId: context.scope.adapterId,
          snapshotRevision: context.snapshotRevision,
          expiresAt: context.expiresAt,
        }
      : {
          principal: "",
          sessionKey: "",
          namespace: "",
          adapterId: "",
          snapshotRevision: "",
          expiresAt: "",
        },
    selectedMessageIds: [],
    retainedMessageIds: [],
    proposedRemovalIds: [],
    preserve: { protectedMessageIds: [], minimumRetainedMessages: 0 },
    inverse: { kind: "restore-source-message-ids", sourceMessageIds: [] },
    retention: {
      planId,
      mode: "adapter-local",
      expiresAt: "",
      maxBytes: 0,
      snapshotContentHash: context?.snapshotContentHash ?? "",
    },
    provenance: {
      algorithmVersion: ACTIVE_CONTEXT_ALGORITHM_VERSION,
      selectorHash: "",
      snapshotContentHash: context?.snapshotContentHash ?? "",
      generatedAt: context?.generatedAt ?? new Date().toISOString(),
    },
    policy,
  };
}

/** Scope + snapshot validation shared by plan and prepare. Throws PlanReject. */
class PlanReject extends Error {
  constructor(readonly code: ActiveContextErrorCode) {
    super(code);
  }
}

function buildContext(
  request: ActiveContextTransformRequest,
  deps: ActiveContextTransformDeps,
): PlanContext {
  const caps = deps.caps ?? {
    ...DEFAULT_ACTIVE_CONTEXT_CAPS,
    activeContextTransforms: true,
    activeContextLlm: false,
  };
  const scope = deps.resolvedScope;
  if (!scope || !scope.sessionKey || !scope.namespace || !scope.principal || !scope.adapterId) {
    throw new PlanReject("scope_mismatch");
  }
  // Trusted-scope checks run before any ID selection or model work.
  if (request.snapshot.sessionKey !== scope.sessionKey) throw new PlanReject("scope_mismatch");
  if (request.snapshot.namespace !== scope.namespace) throw new PlanReject("scope_mismatch");

  const snapshot = request.snapshot;
  if (snapshot.schemaVersion !== ACTIVE_CONTEXT_SNAPSHOT_SCHEMA_VERSION) {
    throw new PlanReject("invalid_request");
  }
  if (!Array.isArray(snapshot.messages) || snapshot.messages.length === 0) {
    throw new PlanReject("invalid_request");
  }
  const byId = new Map<string, ActiveContextMessage>();
  let totalChars = 0;
  for (const message of snapshot.messages) {
    if (
      typeof message?.id !== "string" ||
      message.id.length === 0 ||
      typeof message.content !== "string" ||
      VALID_ROLES[message.role] !== true
    ) {
      throw new PlanReject("invalid_request");
    }
    if (byId.has(message.id)) throw new PlanReject("invalid_request"); // duplicate IDs
    byId.set(message.id, message);
    totalChars += message.content.length;
  }
  if (snapshot.messages.length > caps.activeContextMaxMessages) throw new PlanReject("invalid_request");
  if (totalChars > caps.activeContextMaxSnapshotChars) throw new PlanReject("invalid_request");

  const now = (deps.now ?? (() => new Date()))();
  const generatedAt = now.toISOString();
  const expiresAt = new Date(now.getTime() + caps.activeContextPlanTtlMinutes * 60_000).toISOString();
  return {
    caps,
    scope,
    snapshotRevision: snapshot.revision,
    byId,
    ordered: [...snapshot.messages].sort((a, b) => a.ordinal - b.ordinal || a.id.localeCompare(b.id)),
    snapshotContentHash: hashSnapshot(snapshot),
    generatedAt,
    expiresAt,
  };
}

/** Resolve the selector to ordered source messages. Exactly one form allowed. */
function resolveSelection(
  request: ActiveContextTransformRequest,
  context: PlanContext,
): ActiveContextMessage[] {
  const messageIds = request.selector?.messageIds;
  const span = request.selector?.span;
  const hasIds = Array.isArray(messageIds) && messageIds.length > 0;
  if (hasIds === (span !== undefined)) throw new PlanReject("invalid_request"); // both or neither

  if (hasIds && messageIds) {
    const seen = new Set<string>();
    const picked: ActiveContextMessage[] = [];
    for (const id of messageIds) {
      if (seen.has(id)) throw new PlanReject("invalid_request"); // duplicate IDs
      seen.add(id);
      const message = context.byId.get(id);
      if (!message) throw new PlanReject("invalid_request"); // unknown IDs
      picked.push(message);
    }
    return picked.sort((a, b) => a.ordinal - b.ordinal || a.id.localeCompare(b.id)); // snapshot order
  }

  if (!span) throw new PlanReject("invalid_request");
  const { startMessageId, endMessageId } = span;
  const start = context.byId.get(startMessageId);
  const end = context.byId.get(endMessageId);
  if (!start || !end) throw new PlanReject("invalid_request");
  if (start.ordinal > end.ordinal) throw new PlanReject("invalid_request"); // inverted span
  const inSpan = context.ordered.filter(
    (m) => m.ordinal >= start.ordinal && m.ordinal <= end.ordinal, // closed and full
  );
  if (inSpan.length === 0) throw new PlanReject("invalid_request"); // empty span
  return inSpan;
}

function protectedIdSet(
  request: ActiveContextTransformRequest,
  context: PlanContext,
): Set<string> {
  const protectedIds = new Set<string>();
  for (const message of context.ordered) {
    if (PROTECTED_ROLES[message.role] === true || message.protected === true) {
      protectedIds.add(message.id);
    }
  }
  for (const role of request.preserve?.roles ?? []) {
    if (PROTECTED_ROLES[role] === true) continue;
    for (const message of context.ordered) {
      if (message.role === role) protectedIds.add(message.id);
    }
  }
  for (const id of request.preserve?.messageIds ?? []) {
    if (context.byId.has(id)) protectedIds.add(id);
  }
  return protectedIds;
}

// ── plan ───────────────────────────────────────────────────────────────────

/**
 * Build one bounded, content-addressed SUMMARY or FILTER plan. Returns a
 * rejected plan (with a stable error code) instead of throwing on bad
 * input — bad input is never hidden behind a no-op. `planHash` binds the
 * scope, revision, and every selected/removal/replacement ID; replay
 * across principal, session, namespace, adapter, or revision therefore
 * fails the adapter's comparisons before retain, apply, or undo.
 */
export function planActiveContextTransform(
  request: ActiveContextTransformRequest,
  deps: ActiveContextTransformDeps,
): ActiveContextTransformPlan {
  const caps =
    deps.caps ?? { ...DEFAULT_ACTIVE_CONTEXT_CAPS, activeContextTransforms: true, activeContextLlm: false };
  const policy = evaluateActiveContextTransformPolicy({
    actionsEnabled: deps.actionsEnabled ?? caps.activeContextTransforms,
    operation: request.operation,
  });
  if (policy.decision === "deny") {
    // feature_disabled — evaluated before scope or selection work.
    return rejectedPlan(request.operation, "feature_disabled", null, policy);
  }
  let context: PlanContext | null = null;
  try {
    if (request.schemaVersion !== ACTIVE_CONTEXT_SNAPSHOT_SCHEMA_VERSION) {
      throw new PlanReject("invalid_request");
    }
    if (request.operation !== "SUMMARY" && request.operation !== "FILTER") {
      throw new PlanReject("invalid_request");
    }
    if (VALID_PHASES[request.phase] !== true) throw new PlanReject("invalid_request");
    context = buildContext(request, deps);

    if (
      request.expectedRevision !== undefined &&
      request.expectedRevision !== request.snapshot.revision
    ) {
      throw new PlanReject("stale_context");
    }

    const selected = resolveSelection(request, context);
    const protectedIds = protectedIdSet(request, context);
    const removable = selected.filter((m) => !protectedIds.has(m.id));
    if (removable.length === 0) {
      throw new PlanReject("preserve_conflict"); // nothing chosen is removable
    }

    const minimumRetained = Math.max(
      1,
      request.preserve?.minRetainedMessages ?? caps.activeContextMinRetainedMessages,
    );
    const idList = (messages: ActiveContextMessage[]) => messages.map((m) => m.id);
    const allIds = idList(context.ordered);
    const selectorHash = sha256Hex(canonicalJson(request.selector ?? {}));

    if (request.operation === "FILTER") {
      return buildFilterPlan(request, deps, context, {
        selected,
        removable,
        protectedIds,
        minimumRetained,
        allIds,
        selectorHash,
        policy,
      });
    }
    return buildSummaryPlan(request, deps, context, {
      selected,
      removable,
      protectedIds,
      minimumRetained,
      allIds,
      selectorHash,
      policy,
    });
  } catch (err) {
    if (err instanceof PlanReject) {
      return rejectedPlan(request.operation, err.code, context, policy);
    }
    throw err;
  }
}

interface SelectionBundle {
  selected: ActiveContextMessage[];
  removable: ActiveContextMessage[];
  protectedIds: Set<string>;
  minimumRetained: number;
  allIds: string[];
  selectorHash: string;
  policy: { decision: "allow" | "deny"; rationale: string };
}

function finalizePlan(
  operation: ActiveContextOperation,
  context: PlanContext,
  bundle: SelectionBundle,
  proposedRemovalIds: string[],
  extras: {
    scoreRows?: ActiveContextScoreRow[];
    replacement?: ActiveContextPlanReplacement;
    criterionHash?: string;
    sourcePromptHash?: string;
  },
): ActiveContextTransformPlan {
  const retainedIds = bundle.allIds.filter((id) => !proposedRemovalIds.includes(id));
  if (retainedIds.length < bundle.minimumRetained) {
    throw new PlanReject("preserve_conflict"); // below keep floor / no safe message left
  }
  const sourceMessageIds = bundle.removable.map((m) => m.id);
  const precondition = {
    principal: context.scope.principal,
    sessionKey: context.scope.sessionKey,
    namespace: context.scope.namespace,
    adapterId: context.scope.adapterId,
    snapshotRevision: context.snapshotRevision,
    expiresAt: context.expiresAt,
  };
  const provenance = {
    algorithmVersion: ACTIVE_CONTEXT_ALGORITHM_VERSION,
    selectorHash: bundle.selectorHash,
    snapshotContentHash: context.snapshotContentHash,
    ...(extras.criterionHash ? { criterionHash: extras.criterionHash } : {}),
    ...(extras.sourcePromptHash ? { sourcePromptHash: extras.sourcePromptHash } : {}),
    generatedAt: context.generatedAt,
  };
  const planId = `actx-${sha256Hex(
    canonicalJson({
      adapterId: precondition.adapterId,
      criterionHash: extras.criterionHash,
      namespace: precondition.namespace,
      operation,
      principal: precondition.principal,
      selectorHash: bundle.selectorHash,
      sessionKey: precondition.sessionKey,
      snapshotContentHash: context.snapshotContentHash,
    }),
  ).slice(0, 16)}`;
  const planBody = {
    operation,
    planId,
    precondition,
    proposedRemovalIds,
    replacementMessageId: extras.replacement?.messageId,
    replacementSourceIds: extras.replacement?.sourceMessageIds,
    retainedIds,
    selectedIds: bundle.selected.map((m) => m.id),
  };
  const planHash = sha256Hex(canonicalJson(planBody));
  return {
    schemaVersion: ACTIVE_CONTEXT_PLAN_SCHEMA_VERSION,
    planId,
    planHash,
    operation,
    status: "ready",
    precondition,
    selectedMessageIds: planBody.selectedIds,
    retainedMessageIds: retainedIds,
    proposedRemovalIds,
    ...(extras.scoreRows ? { scoreRows: extras.scoreRows } : {}),
    ...(extras.replacement ? { replacement: extras.replacement } : {}),
    preserve: {
      protectedMessageIds: [...bundle.protectedIds],
      minimumRetainedMessages: bundle.minimumRetained,
    },
    inverse: {
      kind: "restore-source-message-ids",
      sourceMessageIds,
      ...(extras.replacement ? { removeReplacementMessageId: extras.replacement.messageId } : {}),
      expectedAppliedPlanHash: planHash,
    },
    retention: {
      planId,
      mode: "adapter-local",
      expiresAt: context.expiresAt,
      maxBytes: context.caps.activeContextRetentionMaxBytes,
      snapshotContentHash: context.snapshotContentHash,
    },
    provenance,
    policy: bundle.policy,
  };
}

function buildFilterPlan(
  request: ActiveContextTransformRequest,
  deps: ActiveContextTransformDeps,
  context: PlanContext,
  bundle: SelectionBundle,
): ActiveContextTransformPlan {
  const filter = request.filter;
  if (!filter || typeof filter.keepCriterion !== "string" || filter.keepCriterion.length === 0) {
    throw new PlanReject("invalid_request"); // Filter needs keepCriterion
  }
  const threshold = filter.threshold;
  if (typeof threshold !== "number" || !Number.isFinite(threshold) || threshold < 0 || threshold > 1) {
    throw new PlanReject("invalid_request"); // fixed limit in [0,1], never defaulted
  }
  if (!deps.scoreMessage) {
    throw new PlanReject("filter_unavailable"); // Filter needs a score function
  }

  const scoreRows: ActiveContextScoreRow[] = [];
  const removalIds: string[] = [];
  for (const message of bundle.removable) {
    const score = deps.scoreMessage(message);
    if (typeof score !== "number" || !Number.isFinite(score) || score < 0 || score > 1) {
      throw new PlanReject("filter_unavailable"); // missing / NaN / out of range
    }
    const decision = score >= threshold ? "keep" : "drop"; // fixed keep rule
    scoreRows.push({ messageId: message.id, score, decision });
    if (decision === "drop") removalIds.push(message.id);
  }

  return finalizePlan("FILTER", context, bundle, removalIds, {
    scoreRows,
    criterionHash: sha256Hex(filter.keepCriterion), // hash, never the rule text
    sourcePromptHash: request.sourcePromptHash,
  });
}

function buildSummaryPlan(
  request: ActiveContextTransformRequest,
  deps: ActiveContextTransformDeps,
  context: PlanContext,
  bundle: SelectionBundle,
): ActiveContextTransformPlan {
  const requested = request.summary?.method ?? "deterministic";
  const llmEnabled = context.caps.activeContextLlm;
  let method: "deterministic" | "llm";
  let fallbackPolicy: "allowed" | "none";
  if (requested === "deterministic") {
    method = "deterministic";
    fallbackPolicy = "none";
  } else if (requested === "llm") {
    if (!llmEnabled) throw new PlanReject("unsupported"); // explicit llm behind a closed gate
    method = "llm";
    fallbackPolicy = "none"; // fallback only in auto mode
  } else {
    // auto: prefer the LLM seam when allowed; deterministic otherwise.
    method = llmEnabled && deps.summarize ? "llm" : "deterministic";
    fallbackPolicy = method === "llm" ? "allowed" : "none";
  }

  const requestedTokens = request.summary?.targetTokens ?? context.caps.activeContextSummaryMaxTokens;
  if (
    typeof requestedTokens !== "number" ||
    !Number.isFinite(requestedTokens) ||
    requestedTokens <= 0 ||
    requestedTokens > context.caps.activeContextSummaryMaxTokens
  ) {
    throw new PlanReject("invalid_request");
  }
  const targetTokens = Math.floor(requestedTokens);

  // planId is derived inside finalizePlan; the replacement ID must be stable
  // relative to it, so derive from the same stable inputs.
  const replacementSeed = sha256Hex(
    canonicalJson({
      operation: "SUMMARY",
      selectorHash: bundle.selectorHash,
      snapshotContentHash: context.snapshotContentHash,
      sessionKey: context.scope.sessionKey,
      namespace: context.scope.namespace,
      principal: context.scope.principal,
      adapterId: context.scope.adapterId,
    }),
  );
  const replacement: ActiveContextPlanReplacement = {
    messageId: `actxr-${replacementSeed.slice(0, 16)}`,
    sourceMessageIds: bundle.removable.map((m) => m.id),
    method,
    fallbackPolicy,
    targetTokens,
  };

  const plan = finalizePlan("SUMMARY", context, bundle, [...replacement.sourceMessageIds], {
    replacement,
    sourcePromptHash: request.sourcePromptHash,
  });
  return plan;
}

// ── prepare ────────────────────────────────────────────────────────────────

/**
 * Produce the SUMMARY replacement text for a ready plan through the pure
 * summary seam (context-summary.ts). Never calls `LcmSummarizer`. FILTER
 * plans pass through unchanged after revalidation. The caller must supply
 * the same snapshot the plan was built from; a changed transcript fence
 * rejects with `plan_conflict`.
 */
export async function prepareActiveContextTransform(
  plan: ActiveContextTransformPlan,
  deps: ActiveContextTransformDeps & { snapshot: ActiveContextSnapshot },
): Promise<ActiveContextPreparedTransform> {
  if (plan.status !== "ready") {
    return { status: "rejected", plan, errorCode: plan.errorCode ?? "invalid_request" };
  }

  const scope = deps.resolvedScope;
  const p = plan.precondition;
  if (
    !scope ||
    scope.principal !== p.principal ||
    scope.sessionKey !== p.sessionKey ||
    scope.namespace !== p.namespace ||
    scope.adapterId !== p.adapterId
  ) {
    return { status: "rejected", plan, errorCode: "scope_mismatch" };
  }
  const now = deps.now?.() ?? new Date();
  if (now.getTime() >= new Date(plan.retention.expiresAt).getTime()) {
    return { status: "rejected", plan, errorCode: "stale_context" }; // expired plan
  }
  if (deps.snapshot.sessionKey !== p.sessionKey || deps.snapshot.namespace !== p.namespace) {
    return { status: "rejected", plan, errorCode: "scope_mismatch" };
  }
  const fenceHash = hashSnapshot(deps.snapshot);
  if (fenceHash !== plan.provenance.snapshotContentHash) {
    return { status: "rejected", plan, errorCode: "plan_conflict" }; // changed fence
  }

  if (plan.operation === "FILTER") {
    return { status: "ready", plan };
  }

  const replacement = plan.replacement;
  if (!replacement) {
    return { status: "failed", plan, errorCode: "invalid_request" };
  }
  const byId = new Map(deps.snapshot.messages.map((m) => [m.id, m] as const));
  const sourceText = replacement.sourceMessageIds
    .map((id) => byId.get(id))
    .filter((m): m is ActiveContextMessage => m !== undefined)
    .sort((a, b) => a.ordinal - b.ordinal || a.id.localeCompare(b.id))
    .map((m) => m.content)
    .join("\n\n"); // exact order, exact text

  const method =
    replacement.method === "deterministic"
      ? "deterministic"
      : replacement.fallbackPolicy === "allowed"
        ? "auto"
        : "llm";
  try {
    const result = await summarizeContextPure(sourceText, replacement.targetTokens, method, {
      llm: deps.summarize,
      deterministicMaxTokens: deps.caps?.activeContextSummaryMaxTokens ?? replacement.targetTokens,
    });
    if (result.text.trim().length === 0) {
      return { status: "failed", plan, errorCode: "summary_unavailable" }; // bad model text
    }
    return {
      status: "ready",
      plan,
      replacement: {
        messageId: replacement.messageId,
        text: result.text,
        contentHash: sha256Hex(result.text),
        method: result.method,
        ...(result.modelUsed ? { modelUsed: result.modelUsed } : {}),
        fallback: result.fallback,
        sourceMessageIds: replacement.sourceMessageIds,
      },
    };
  } catch (err) {
    if (err instanceof ContextSummaryUnavailableError) {
      return { status: "failed", plan, errorCode: "summary_unavailable" };
    }
    throw err;
  }
}

// ── receipts and telemetry ─────────────────────────────────────────────────

/**
 * Validate a host receipt against the plan's bindings and append one
 * context record to the ledger. Order of checks: scope → hash → revision →
 * shape. One-time use is enforced by the adapter's persisted apply/undo
 * markers (retention store); this recorder appends only. A ledger write
 * failure returns `recorded: false` and never fabricates an apply.
 */
export async function recordActiveContextApplyReceipt(
  plan: ActiveContextTransformPlan,
  receipt: ActiveContextApplyReceipt,
  trustedScope: ActiveContextResolvedScope,
  recorder: {
    append(record: ContextTransformTelemetryRecord): Promise<boolean>;
  },
): Promise<{ recorded: boolean; event: ContextTransformTelemetryRecord }> {
  const p = plan.precondition;
  const scopeMatch =
    trustedScope.principal === p.principal &&
    trustedScope.sessionKey === p.sessionKey &&
    trustedScope.namespace === p.namespace &&
    trustedScope.adapterId === p.adapterId &&
    receipt.adapterId === trustedScope.adapterId;
  if (!scopeMatch) throw new PlanReject("scope_mismatch");
  if (receipt.planHash !== plan.planHash) throw new PlanReject("plan_conflict"); // bad hash
  if (receipt.hostRevisionBefore === undefined || receipt.hostRevisionBefore !== p.snapshotRevision) {
    throw new PlanReject("stale_context"); // old plan / bad revision
  }
  const shapeOk =
    receipt.schemaVersion === ACTIVE_CONTEXT_RECEIPT_SCHEMA_VERSION &&
    receipt.planId === plan.planId &&
    (receipt.outcome === "applied" || receipt.outcome === "skipped" || receipt.outcome === "failed") &&
    typeof receipt.appliedAt === "string" &&
    !Number.isNaN(Date.parse(receipt.appliedAt));
  if (!shapeOk) throw new PlanReject("invalid_receipt");

  const event: ContextTransformTelemetryRecord = {
    recordKind: "context_transform",
    schemaVersion: ACTIVE_CONTEXT_RECORD_SCHEMA_VERSION,
    timestamp: receipt.appliedAt,
    actionId: plan.planId,
    action: plan.operation === "SUMMARY" ? "summarize_context" : "filter_context",
    outcome: receipt.outcome,
    status: receipt.outcome === "applied" ? "applied" : receipt.outcome === "failed" ? "rejected" : "validated",
    subsystem: "active-context",
    namespace: p.namespace,
    sourceSessionKey: p.sessionKey,
    planHash: plan.planHash,
    snapshotRevision: p.snapshotRevision,
    adapterId: receipt.adapterId,
    algorithmVersion: plan.provenance.algorithmVersion,
    selectedCount: plan.selectedMessageIds.length,
    retainedCount: plan.retainedMessageIds.length,
    proposedRemovalCount: plan.proposedRemovalIds.length,
    receiptOutcome: receipt.outcome,
    selectorHash: plan.provenance.selectorHash,
    snapshotContentHash: plan.provenance.snapshotContentHash,
    ...(plan.provenance.criterionHash ? { criterionHash: plan.provenance.criterionHash } : {}),
    ...(plan.provenance.sourcePromptHash ? { sourcePromptHash: plan.provenance.sourcePromptHash } : {}),
    policyDecision: plan.policy.decision,
    policyRationale: plan.policy.rationale,
  };

  let recorded = false;
  try {
    recorded = await recorder.append(event);
  } catch {
    recorded = false; // ledger errors surface in the result, never as an apply
  }
  return { recorded, event: { ...event, telemetryRecorded: recorded } };
}

/**
 * Build a plan-stage ledger record (plan produced, rejected, skipped, or
 * failed before host apply). Receipt-backed applies use
 * {@link recordActiveContextApplyReceipt} instead.
 */
export function buildContextTransformPlanEvent(
  plan: ActiveContextTransformPlan,
  outcome: "skipped" | "failed",
): ContextTransformTelemetryRecord {
  return {
    recordKind: "context_transform",
    schemaVersion: ACTIVE_CONTEXT_RECORD_SCHEMA_VERSION,
    timestamp: plan.provenance.generatedAt,
    actionId: plan.planId,
    action: plan.operation === "SUMMARY" ? "summarize_context" : "filter_context",
    outcome,
    status: plan.status === "ready" ? "validated" : "rejected",
    subsystem: "active-context",
    namespace: plan.precondition.namespace,
    sourceSessionKey: plan.precondition.sessionKey,
    planHash: plan.planHash,
    snapshotRevision: plan.precondition.snapshotRevision,
    algorithmVersion: plan.provenance.algorithmVersion,
    selectedCount: plan.selectedMessageIds.length,
    retainedCount: plan.retainedMessageIds.length,
    proposedRemovalCount: plan.proposedRemovalIds.length,
    selectorHash: plan.provenance.selectorHash,
    snapshotContentHash: plan.provenance.snapshotContentHash,
    ...(plan.provenance.criterionHash ? { criterionHash: plan.provenance.criterionHash } : {}),
    ...(plan.provenance.sourcePromptHash ? { sourcePromptHash: plan.provenance.sourcePromptHash } : {}),
    policyDecision: plan.policy.decision,
    policyRationale: plan.policy.rationale,
    telemetryRecorded: true,
  };
}

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

/**
 * Resolve standalone config-file shapes into the core Remnic config record.
 *
 * Legacy files store core keys at the top level. During migration, a partial
 * `remnic` or `engram` block may coexist with those keys. Flat top-level core
 * keys remain fallbacks, while the selected nested block wins on key conflicts.
 * Host-only blocks are never forwarded into core parsing.
 */
export function resolveRemnicConfigRecord(raw: unknown): Record<string, unknown> {
  if (!isRecord(raw)) {
    throw new Error("Top-level Remnic config must be a JSON object");
  }

  const { remnic, engram, server: _server, ...flat } = raw;
  const nested = remnic ?? engram;
  if (nested !== undefined && !isRecord(nested)) {
    throw new Error("Nested remnic/engram config must be a JSON object");
  }

  return nested === undefined ? flat : { ...flat, ...nested };
}

export interface PluginEntryResolverOptions {
  candidateIds: readonly string[];
  preferredId?: string;
  getEntries(raw: Record<string, unknown>): Record<string, unknown> | undefined;
  getSlotId?: (raw: Record<string, unknown>) => string | undefined;
}

function uniqueDefined(values: Array<string | undefined>): string[] {
  const seen = new Set<string>();
  const out: string[] = [];
  for (const value of values) {
    if (value === undefined || seen.has(value)) continue;
    seen.add(value);
    out.push(value);
  }
  return out;
}

export function resolvePluginEntry(
  raw: unknown,
  options: PluginEntryResolverOptions,
): Record<string, unknown> | undefined {
  if (!raw || typeof raw !== "object" || Array.isArray(raw)) return undefined;
  const root = raw as Record<string, unknown>;
  const entries = options.getEntries(root);
  if (!entries) return undefined;

  const allowedIds = new Set(options.candidateIds);
  const slotId = options.getSlotId?.(root);
  if (typeof slotId === "string" && !allowedIds.has(slotId)) {
    return undefined;
  }
  const activeId = typeof slotId === "string" ? slotId : undefined;
  const ownId =
    !activeId &&
    typeof options.preferredId === "string" &&
    allowedIds.has(options.preferredId)
      ? options.preferredId
      : undefined;

  for (const id of uniqueDefined([activeId, ownId, ...options.candidateIds])) {
    const entry = entries[id];
    if (entry && typeof entry === "object" && !Array.isArray(entry)) {
      return entry as Record<string, unknown>;
    }
  }
  return undefined;
}

/**
 * Shared Remnic config-file discovery (issue #2796).
 *
 * One implementation of the candidate order every surface uses: explicit
 * `--config` path, then `REMNIC_CONFIG_PATH`/`ENGRAM_CONFIG_PATH`, then the
 * first existing candidate under cwd, then the home default. The standalone
 * server boots from this order and the CLI resolves `--config`-less commands
 * through it, so the two can never drift onto different files.
 */

import fs from "node:fs";
import path from "node:path";

import { readCompatEnv, resolveHomeDir } from "./runtime/env.js";

export interface DiscoveredConfigPath {
  path: string;
  explicit: boolean;
  source: string;
}

/**
 * Expand a leading home reference — `~`, `~\`, `$HOME`, or `${HOME}` — to the
 * resolved home directory. Union of the historical server (tilde only) and
 * CLI (tilde plus `$HOME` forms) behaviors; every other path passes through
 * unchanged.
 */
function expandHomeReference(p: string): string {
  if (p === "~" || p.startsWith("~/") || p.startsWith("~\\")) {
    return resolveHomeDir() + p.slice(1);
  }
  const home = resolveHomeDir();
  if (p === "$HOME" || p.startsWith("$HOME/") || p.startsWith("$HOME\\")) {
    return home + p.slice(5);
  }
  if (p === "${HOME}" || p.startsWith("${HOME}/") || p.startsWith("${HOME}\\")) {
    return home + p.slice(7);
  }
  return p;
}

/**
 * The ordered candidates every probing surface walks: the expanded
 * `REMNIC_CONFIG_PATH`/`ENGRAM_CONFIG_PATH` value (if set), then the cwd
 * files, then the home defaults. The standalone server and the CLI resolve to
 * the single file `discoverConfigPath` picks; the OpenClaw bridge probes each
 * candidate's endpoint. One list, so a daemon the server can discover is never
 * invisible to the bridge.
 */
export function configPathCandidates(): string[] {
  const envPath = readCompatEnv("REMNIC_CONFIG_PATH", "ENGRAM_CONFIG_PATH");
  return [
    ...(envPath ? [path.resolve(expandHomeReference(envPath))] : []),
    ...autoDiscoveryCandidates(),
  ];
}

function autoDiscoveryCandidates(): string[] {
  const homeDir = resolveHomeDir();
  return [
    path.join(process.cwd(), "remnic.config.json"),
    path.join(process.cwd(), "engram.config.json"),
    path.join(homeDir, ".config", "remnic", "config.json"),
    path.join(homeDir, ".config", "engram", "config.json"),
  ];
}

export function discoverConfigPath(cliPath?: string): DiscoveredConfigPath {
  if (cliPath) {
    return { path: path.resolve(expandHomeReference(cliPath)), explicit: true, source: "--config" };
  }

  const envPath = readCompatEnv("REMNIC_CONFIG_PATH", "ENGRAM_CONFIG_PATH");
  if (envPath) {
    return {
      path: path.resolve(expandHomeReference(envPath)),
      explicit: true,
      source: "REMNIC_CONFIG_PATH/ENGRAM_CONFIG_PATH",
    };
  }

  const candidates = autoDiscoveryCandidates();
  for (const candidate of candidates) {
    if (fs.existsSync(candidate) && fs.statSync(candidate).isFile()) {
      return { path: candidate, explicit: false, source: "auto-discovery" };
    }
  }

  return { path: candidates[2], explicit: false, source: "auto-discovery" };
}

import { constants } from "node:fs";
import { open, opendir, realpath, stat } from "node:fs/promises";
import type { FileHandle } from "node:fs/promises";
import path from "node:path";
import type { ExternalWikiRoot } from "./external-wiki-config.js";

const DEFAULT_MAX_INDEX_BYTES = 1_048_576;
const DEFAULT_MAX_PAGE_BYTES = 1_048_576;
const DEFAULT_MAX_CATALOG_ENTRIES = 10_000;
const DEFAULT_MAX_DIRECTORY_DEPTH = 32;
const MAX_READ_BYTES = 16_777_216;
const MAX_CATALOG_ENTRIES = 100_000;
const MAX_DIRECTORY_DEPTH = 128;
const MIN_VISITED_ENTRIES = 100;
const MAX_VISITED_ENTRIES = 1_000_000;

export type { ExternalWikiRoot } from "./external-wiki-config.js";

export interface ExternalWikiLayout {
  rootDir: string;
  pagesDir: string;
  indexFile: string;
  indexPresent: boolean;
  rawDir?: string;
  outputsDir?: string;
}

export interface ExternalWikiCatalogEntry {
  title: string;
  path: string;
  indexBlurb?: string;
  indexLine?: number;
}

export interface ExternalWikiCatalog {
  wikiId: string;
  indexPresent: boolean;
  entries: ExternalWikiCatalogEntry[];
}

export interface ExternalWikiCatalogLimits {
  maxIndexBytes?: number;
  maxEntries?: number;
  maxDepth?: number;
}

export interface ExternalWikiPage {
  wikiId: string;
  path: string;
  title: string;
  content: string;
  bytes: number;
}

function assertPositiveInteger(value: number, keyName: string, maximum?: number): void {
  if (!Number.isSafeInteger(value) || value <= 0) {
    throw new Error(`${keyName} must be a positive integer`);
  }
  if (maximum !== undefined && value > maximum) {
    throw new Error(`${keyName} must be at most ${maximum}`);
  }
}

function isInside(baseDir: string, candidate: string): boolean {
  const relative = path.relative(baseDir, candidate);
  return relative === "" || (relative !== ".." && !relative.startsWith(`..${path.sep}`) && !path.isAbsolute(relative));
}

function resolveInside(baseDir: string, relativePath: string, keyName: string): string {
  const resolved = path.resolve(baseDir, relativePath);
  if (!isInside(baseDir, resolved) || resolved === baseDir) {
    throw new Error(`${keyName} must stay within ${baseDir}`);
  }
  return resolved;
}

async function requireDirectory(candidate: string, rootDir: string, description: string): Promise<string> {
  let canonical: string;
  try {
    canonical = await realpath(candidate);
  } catch (error) {
    if ((error as NodeJS.ErrnoException).code === "ENOENT") {
      throw new Error(`${description} does not exist: ${candidate}`);
    }
    throw error;
  }
  if (!isInside(rootDir, canonical)) throw new Error(`${description} escapes rootDir`);
  if (!(await stat(canonical)).isDirectory()) throw new Error(`${description} is not a directory`);
  return canonical;
}

async function optionalDirectory(rootDir: string, name: "raw" | "outputs"): Promise<string | undefined> {
  const candidate = path.join(rootDir, name);
  let canonical: string;
  try {
    canonical = await realpath(candidate);
  } catch (error) {
    if ((error as NodeJS.ErrnoException).code === "ENOENT") return undefined;
    throw error;
  }
  if (!isInside(rootDir, canonical)) throw new Error(`${name} directory escapes rootDir`);
  if (!(await stat(canonical)).isDirectory()) throw new Error(`${name} path is not a directory`);
  return canonical;
}

async function optionalIndexFile(candidate: string, rootDir: string): Promise<string | undefined> {
  let canonical: string;
  try {
    canonical = await realpath(candidate);
  } catch (error) {
    if ((error as NodeJS.ErrnoException).code === "ENOENT") return undefined;
    throw error;
  }
  if (!isInside(rootDir, canonical)) throw new Error("catalog index escapes rootDir");
  if (!(await stat(canonical)).isFile()) throw new Error("catalog index is not a file");
  return canonical;
}

export async function validateExternalWikiLayout(config: ExternalWikiRoot): Promise<ExternalWikiLayout> {
  let rootDir: string;
  try {
    rootDir = await realpath(config.rootDir);
  } catch (error) {
    if ((error as NodeJS.ErrnoException).code === "ENOENT") {
      throw new Error(`external wiki root does not exist: ${config.rootDir}`);
    }
    throw error;
  }
  if (!(await stat(rootDir)).isDirectory()) throw new Error("external wiki root is not a directory");

  const pagesDir = await requireDirectory(
    resolveInside(rootDir, config.pagesDir, "pages directory"),
    rootDir,
    "pages directory"
  );
  const configuredIndexFile = resolveInside(rootDir, config.indexFile, "catalog index");
  const canonicalIndexFile = await optionalIndexFile(configuredIndexFile, rootDir);
  const [rawDir, outputsDir] = await Promise.all([
    optionalDirectory(rootDir, "raw"),
    optionalDirectory(rootDir, "outputs"),
  ]);

  return {
    rootDir,
    pagesDir,
    indexFile: canonicalIndexFile ?? configuredIndexFile,
    indexPresent: canonicalIndexFile !== undefined,
    ...(rawDir === undefined ? {} : { rawDir }),
    ...(outputsDir === undefined ? {} : { outputsDir }),
  };
}

type CatalogPathBase = "index" | "pages";

function normalizeCatalogPath(target: string, config: ExternalWikiRoot, base: CatalogPathBase): string | null {
  let decoded: string;
  try {
    decoded = decodeURIComponent(target.trim());
  } catch {
    return null;
  }
  const withoutFragment = decoded.split(/[?#]/, 1)[0] ?? "";
  if (
    withoutFragment.length === 0 ||
    withoutFragment.startsWith("/") ||
    withoutFragment.includes("\\") ||
    /^[a-z][a-z0-9+.-]*:/i.test(withoutFragment)
  ) {
    return null;
  }

  const pagesDir = path.posix.normalize(config.pagesDir);
  let relative: string;
  if (base === "index") {
    const baseDir = path.posix.dirname(config.indexFile);
    const rootRelativeTarget = path.posix.normalize(path.posix.join(baseDir, withoutFragment));
    relative = path.posix.relative(pagesDir, rootRelativeTarget);
  } else {
    const pagesPrefix = pagesDir === "." ? "" : `${pagesDir}/`;
    const stripped = pagesPrefix.length > 0 && withoutFragment.startsWith(pagesPrefix)
      ? withoutFragment.slice(pagesPrefix.length)
      : withoutFragment;
    relative = path.posix.normalize(stripped);
  }
  if (
    relative === ".." ||
    relative.startsWith("../") ||
    path.posix.isAbsolute(relative) ||
    relative === "." ||
    !relative.toLowerCase().endsWith(".md")
  ) {
    return null;
  }
  return relative;
}

function catalogBlurb(line: string, matchEnd: number): string | undefined {
  const blurb = line
    .slice(matchEnd)
    .trim()
    .replace(/^[-:|]\s*/, "")
    .trim();
  return blurb.length === 0 ? undefined : blurb;
}

export function parseExternalWikiCatalog(
  content: string,
  config: ExternalWikiRoot,
  limits: Pick<ExternalWikiCatalogLimits, "maxEntries"> = {}
): ExternalWikiCatalogEntry[] {
  const maxEntries = limits.maxEntries ?? DEFAULT_MAX_CATALOG_ENTRIES;
  assertPositiveInteger(maxEntries, "maxEntries", MAX_CATALOG_ENTRIES);
  const entries: ExternalWikiCatalogEntry[] = [];
  const seenPaths = new Set<string>();

  for (const [lineIndex, line] of content.split(/\r?\n/).entries()) {
    const markdownMatch = /\[([^\]]+)]\(([^)\s]+)(?:\s+"[^"]*")?\)/.exec(line);
    const wikiMatch = /\[\[([^\]|]+)(?:\|([^\]]+))?]]/.exec(line);
    let target: string;
    let title: string;
    let matchEnd: number;
    let pathBase: CatalogPathBase;
    if (markdownMatch) {
      title = markdownMatch[1]?.trim() ?? "";
      target = markdownMatch[2]?.trim() ?? "";
      matchEnd = (markdownMatch.index ?? 0) + markdownMatch[0].length;
      pathBase = "index";
    } else if (wikiMatch) {
      const wikiTarget = wikiMatch[1]?.trim() ?? "";
      title = wikiMatch[2]?.trim() || humanizePagePath(wikiTarget);
      target = wikiTarget.toLowerCase().endsWith(".md") ? wikiTarget : `${wikiTarget}.md`;
      matchEnd = (wikiMatch.index ?? 0) + wikiMatch[0].length;
      pathBase = "pages";
    } else {
      continue;
    }

    const pagePath = normalizeCatalogPath(target, config, pathBase);
    if (!pagePath || title.length === 0 || seenPaths.has(pagePath)) continue;
    if (entries.length >= maxEntries) {
      throw new Error(`catalog contains more than ${maxEntries} entries`);
    }
    seenPaths.add(pagePath);
    const indexBlurb = catalogBlurb(line, matchEnd);
    entries.push({
      title,
      path: pagePath,
      ...(indexBlurb === undefined ? {} : { indexBlurb }),
      indexLine: lineIndex + 1,
    });
  }
  return entries;
}

interface BoundedUtf8Read {
  content: string;
  bytes: number;
}

async function canonicalOpenedFile(handle: FileHandle, filePath: string, displayPath: string): Promise<string> {
  if (process.platform === "linux") {
    const descriptorPath = await realpath(`/proc/self/fd/${handle.fd}`).catch(() => undefined);
    if (descriptorPath !== undefined) return descriptorPath;
  }

  let canonical: string;
  try {
    canonical = await realpath(filePath);
  } catch {
    throw new Error(`${displayPath} changed while being opened`);
  }
  const [openedStat, pathStat] = await Promise.all([handle.stat(), stat(canonical)]);
  if (openedStat.dev !== pathStat.dev || openedStat.ino !== pathStat.ino) {
    throw new Error(`${displayPath} changed while being opened`);
  }
  return canonical;
}

async function readBoundedUtf8(
  filePath: string,
  allowedRoot: string,
  maxBytes: number,
  displayPath: string
): Promise<BoundedUtf8Read> {
  assertPositiveInteger(maxBytes, "maxBytes", MAX_READ_BYTES);
  const handle = await open(filePath, constants.O_RDONLY | constants.O_NOFOLLOW);
  try {
    const openedStat = await handle.stat();
    if (!openedStat.isFile()) throw new Error(`${displayPath} is not a file`);
    const canonical = await canonicalOpenedFile(handle, filePath, displayPath);
    if (!isInside(allowedRoot, canonical)) {
      throw new Error(`${displayPath} escapes configured root`);
    }
    const buffer = Buffer.allocUnsafe(maxBytes + 1);
    const { bytesRead } = await handle.read(buffer, 0, buffer.length, 0);
    if (bytesRead > maxBytes) throw new Error(`${displayPath} exceeds ${maxBytes} bytes`);
    let content: string;
    try {
      content = new TextDecoder("utf-8", { fatal: true }).decode(buffer.subarray(0, bytesRead));
    } catch {
      throw new Error(`${displayPath} is not valid UTF-8`);
    }
    return { content, bytes: bytesRead };
  } finally {
    await handle.close();
  }
}

function humanizePagePath(pagePath: string): string {
  const stem = path.posix.basename(pagePath, path.posix.extname(pagePath));
  const words = stem.replace(/[-_]+/g, " ").trim();
  return words.length === 0 ? stem : `${words[0]?.toUpperCase() ?? ""}${words.slice(1)}`;
}

async function listMarkdownPages(
  pagesDir: string,
  maxEntries: number,
  maxDepth: number
): Promise<ExternalWikiCatalogEntry[]> {
  assertPositiveInteger(maxEntries, "maxEntries", MAX_CATALOG_ENTRIES);
  assertPositiveInteger(maxDepth, "maxDepth", MAX_DIRECTORY_DEPTH);
  const paths: string[] = [];
  const maxVisitedEntries = Math.min(MAX_VISITED_ENTRIES, Math.max(MIN_VISITED_ENTRIES, maxEntries * 100));
  let visitedEntries = 0;
  const walk = async (directory: string, relativeDirectory: string, depth: number): Promise<void> => {
    if (depth > maxDepth) throw new Error(`pages directory exceeds maxDepth ${maxDepth}`);
    const dir = await opendir(directory);
    for await (const entry of dir) {
      visitedEntries += 1;
      if (visitedEntries > maxVisitedEntries) {
        throw new Error(`pages directory contains more than ${maxVisitedEntries} filesystem entries`);
      }
      const relativePath = relativeDirectory ? path.posix.join(relativeDirectory, entry.name) : entry.name;
      if (entry.isDirectory()) {
        await walk(path.join(directory, entry.name), relativePath, depth + 1);
      } else if (entry.isFile() && entry.name.toLowerCase().endsWith(".md")) {
        if (paths.length >= maxEntries) {
          throw new Error(`pages directory contains more than ${maxEntries} markdown files`);
        }
        paths.push(relativePath);
      }
    }
  };
  await walk(pagesDir, "", 1);
  return paths
    .sort((left, right) => left.localeCompare(right))
    .map((pagePath) => ({
      title: humanizePagePath(pagePath),
      path: pagePath,
    }));
}

function assertWikiEnabled(config: ExternalWikiRoot): void {
  if (!config.enabled) throw new Error(`external wiki "${config.id}" is disabled`);
}

export async function loadExternalWikiCatalog(
  config: ExternalWikiRoot,
  limits: ExternalWikiCatalogLimits = {}
): Promise<ExternalWikiCatalog> {
  assertWikiEnabled(config);
  const maxIndexBytes = limits.maxIndexBytes ?? DEFAULT_MAX_INDEX_BYTES;
  const maxEntries = limits.maxEntries ?? DEFAULT_MAX_CATALOG_ENTRIES;
  const maxDepth = limits.maxDepth ?? DEFAULT_MAX_DIRECTORY_DEPTH;
  assertPositiveInteger(maxEntries, "maxEntries", MAX_CATALOG_ENTRIES);
  assertPositiveInteger(maxDepth, "maxDepth", MAX_DIRECTORY_DEPTH);
  const layout = await validateExternalWikiLayout(config);
  const entries = layout.indexPresent
    ? parseExternalWikiCatalog(
        (await readBoundedUtf8(layout.indexFile, layout.rootDir, maxIndexBytes, config.indexFile)).content,
        config,
        { maxEntries }
      )
    : await listMarkdownPages(layout.pagesDir, maxEntries, maxDepth);
  return { wikiId: config.id, indexPresent: layout.indexPresent, entries };
}

function normalizePagePath(relativePath: string): string {
  if (relativePath.includes("\\")) {
    throw new Error("page path must use POSIX separators");
  }
  const normalized = path.posix.normalize(relativePath);
  if (normalized === "." || normalized === ".." || normalized.startsWith("../") || normalized.startsWith("/")) {
    throw new Error("page path must stay within the pages directory");
  }
  if (!normalized.toLowerCase().endsWith(".md")) {
    throw new Error("page path must end in .md");
  }
  return normalized;
}

function pageTitle(content: string, pagePath: string): string {
  const heading = /^#\s+(.+?)\s*$/m.exec(content)?.[1]?.trim();
  return heading && heading.length > 0 ? heading : humanizePagePath(pagePath);
}

export async function readExternalWikiPage(
  config: ExternalWikiRoot,
  relativePath: string,
  maxBytes = DEFAULT_MAX_PAGE_BYTES
): Promise<ExternalWikiPage> {
  assertWikiEnabled(config);
  const pagePath = normalizePagePath(relativePath);
  const layout = await validateExternalWikiLayout(config);
  const candidate = resolveInside(layout.pagesDir, pagePath, "page path");
  let canonical: string;
  try {
    canonical = await realpath(candidate);
  } catch (error) {
    if ((error as NodeJS.ErrnoException).code === "ENOENT") {
      throw new Error(`external wiki page does not exist: ${pagePath}`);
    }
    throw error;
  }
  if (!isInside(layout.pagesDir, canonical)) {
    throw new Error("page path must stay within the pages directory");
  }
  if (!(await stat(canonical)).isFile()) throw new Error(`external wiki page is not a file: ${pagePath}`);
  const page = await readBoundedUtf8(canonical, layout.pagesDir, maxBytes, pagePath);
  return {
    wikiId: config.id,
    path: pagePath,
    title: pageTitle(page.content, pagePath),
    content: page.content,
    bytes: page.bytes,
  };
}

import { type ExternalWikiRoot, type ExternalWikiSearchResult, searchExternalWikis } from "./external-wiki-search.js";

interface ExternalWikiCliIo {
  readonly stdout: { write(chunk: string): unknown };
  readonly stderr: { write(chunk: string): unknown };
}

const USAGE =
  "Usage: remnic external-wiki search <query...> [--wiki-id <id>] [--limit <1-20>] [--max-chars-per-hit <100-8000>] [--json]\n";

export async function runExternalWikiCliCommand(
  roots: readonly ExternalWikiRoot[],
  args: readonly string[],
  io: ExternalWikiCliIo
): Promise<number> {
  if (args[0] === "help" || args[0] === "--help" || args[0] === "-h") {
    io.stdout.write(USAGE);
    return 0;
  }
  const searchArgs = args[0] === "search" ? args.slice(1) : args;

  let limit: number | undefined;
  let wikiId: string | undefined;
  let maxCharsPerHit: number | undefined;
  let json = false;
  const queryParts: string[] = [];
  for (let index = 0; index < searchArgs.length; index += 1) {
    const argument = searchArgs[index];
    if (argument === "--json") {
      json = true;
      continue;
    }
    if (argument === "--limit" || argument === "--wiki-id" || argument === "--max-chars-per-hit") {
      const value = searchArgs[index + 1];
      if (value === undefined || value.startsWith("--")) {
        io.stderr.write(`external-wiki: ${argument} requires a value\n`);
        return 2;
      }
      index += 1;
      if (argument === "--wiki-id") {
        wikiId = value.trim();
        if (wikiId.length === 0) {
          io.stderr.write("external-wiki: --wiki-id must not be empty\n");
          return 2;
        }
        continue;
      }
      const parsed = Number(value);
      const maximum = argument === "--limit" ? 20 : 8_000;
      const minimum = argument === "--limit" ? 1 : 100;
      if (!Number.isInteger(parsed) || parsed < minimum || parsed > maximum) {
        io.stderr.write(`external-wiki: ${argument} must be an integer from ${minimum} to ${maximum}\n`);
        return 2;
      }
      if (argument === "--limit") limit = parsed;
      else maxCharsPerHit = parsed;
      continue;
    }
    if (argument.startsWith("-")) {
      io.stderr.write(`external-wiki: unknown option '${argument}'\n${USAGE}`);
      return 2;
    }
    queryParts.push(argument);
  }

  const query = queryParts.join(" ").trim();
  if (query.length === 0) {
    io.stderr.write("external-wiki: provide a search query\n");
    return 1;
  }
  const enabled = roots.filter((root) => root.enabled !== false);
  if (enabled.length === 0) {
    io.stderr.write("external-wiki: no enabled wiki roots configured\n");
    return 1;
  }

  let result: ExternalWikiSearchResult;
  try {
    result = await searchExternalWikis(enabled, { query, limit, wikiId, maxCharsPerHit });
  } catch (error) {
    io.stderr.write(`external-wiki: ${error instanceof Error ? error.message : "search failed"}\n`);
    return 1;
  }
  if (json) {
    io.stdout.write(`${JSON.stringify(result, null, 2)}\n`);
    return 0;
  }

  if (result.degradedWikiIds.length > 0) {
    io.stderr.write(`Warning: degraded roots: ${result.degradedWikiIds.join(", ")}\n`);
  }
  if (result.hits.length === 0) {
    io.stdout.write("No results.\n");
    return 0;
  }
  for (const hit of result.hits) {
    io.stdout.write(`[${hit.wikiId}] ${hit.path} (score ${hit.score})\n${hit.snippet}\n\n`);
  }
  return 0;
}

import { canReadNamespace, defaultNamespaceForPrincipal } from "./namespaces/principal.js";
import type { ResolvedScopeProfilePlan } from "./namespaces/scope-profiles.js";
import { EngramAccessInputError } from "./access-errors.js";
import { log } from "./logger.js";
import type { SearchDegradation, SearchExecutionOptions } from "./search/port.js";
import type { PluginConfig } from "./types.js";

/**
 * Issue #2018: `memory_search` has no sessionKey, so — unlike recall — it
 * cannot resolve a coding overlay. With scope profiles active and no overlay,
 * `expandScopeProfileReadNamespaces` derives a per-principal self namespace.
 * On a legacy flat-root deployment the corpus still lives under the configured
 * DEFAULT namespace's base collection, which that derived set excludes, so
 * every query silently returned 0.
 *
 * Returns the configured default namespace to merge into the profile read set
 * when the base collection must stay reachable, or `null` otherwise. ALL of:
 *
 *   - the default namespace is THIS principal's own self store — i.e. the
 *     principal has no dedicated namespace policy, so
 *     `defaultNamespaceForPrincipal` resolves to the configured default. On a
 *     multi-tenant scope-profile deployment every principal has its own
 *     policy; reaching into the default would read ANOTHER namespace, so the
 *     fallback must not fire (#2056 r2 / #1501 privateOnly);
 *   - the profile resolved `userGlobal` as a READABLE layer (not just listed
 *     it in `readOrder`). `serverShared` maps to `sharedNamespace`, not the
 *     default, and an unreadable resolved layer is a deliberate omission —
 *     neither may trigger this fallback (#2056 r2);
 *   - the profile's resolved self namespace is NOT already the default
 *     (otherwise it is already in the set);
 *   - the principal is authorized to read the default namespace.
 *
 * The flat-root signal is resolved lazily via {@link defaultAtFlatRootProvider}
 * — the provider is only invoked once the cheap gates (readOrder consent,
 * resolved-layer readability, principal-self, self-resolved-away, ACL) all
 * pass, so a project-only / serverShared-only / unreadable-userGlobal
 * profile never touches the default store (#2056 r6).
 */
export async function resolveMemorySearchDefaultFallback(options: {
  profilePlan: ResolvedScopeProfilePlan;
  config: PluginConfig;
  principal: string | undefined;
  /**
   * True only when the configured default namespace's storage root equals
   * `config.memoryDir` (the legacy flat-root layout). Invoked ONLY after the
   * cheap gates pass, so ineligible profiles never probe the default store.
   */
  defaultAtFlatRootProvider: () => Promise<boolean>;
}): Promise<string | null> {
  const { profilePlan, config, principal } = options;
  // Defense-in-depth: principalSelfIsDefault is only ever true alongside a
  // flat-root default on legacy deployments (a hosted scope-profile principal
  // with its own policy fails this even when default is at the flat root). It
  // is NOT redundant — it keeps a policy-having principal isolated from the
  // flat default corpus.
  const principalSelfIsDefault =
    defaultNamespaceForPrincipal(principal, config) === config.defaultNamespace;
  // readOrder must explicitly intend userGlobal (resolveScopeProfilePlan
  // always materializes a userGlobal layer even when readOrder omits it, so
  // the layer's presence alone is not consent), AND that layer must have
  // resolved readable (a listed-but-unreadable layer is a deliberate
  // omission). serverShared maps to sharedNamespace, not the default.
  const profileIntendsUserGlobal =
    profilePlan.profile.readOrder.includes("userGlobal");
  const userGlobalLayerReadable = profilePlan.layers.some(
    (layer) => layer.id === "userGlobal" && layer.readable && Boolean(layer.namespace),
  );
  const selfResolvedAwayFromDefault =
    profilePlan.baseNamespace !== config.defaultNamespace;
  if (
    !(
      profileIntendsUserGlobal &&
      userGlobalLayerReadable &&
      principalSelfIsDefault &&
      selfResolvedAwayFromDefault &&
      canReadNamespace(principal, config.defaultNamespace, config)
    )
  ) {
    // Cheap gates failed — never probe the default store.
    return null;
  }
  const defaultAtFlatRoot = await options.defaultAtFlatRootProvider();
  return defaultAtFlatRoot ? config.defaultNamespace : null;
}

/**
 * Issue #2018 r4: the explicit legacy-flat-root signal — the configured
 * default namespace's storage root equals `config.memoryDir`. Resolved from
 * storage (not inferred from config/policy shape) so a hosted scope-profile
 * deployment never reaches into the default corpus.
 */
export async function defaultNamespaceAtFlatRoot(
  getStorage: (namespace: string) => Promise<{ dir: string }>,
  config: { defaultNamespace: string; memoryDir: string },
): Promise<boolean> {
  const storage = await getStorage(config.defaultNamespace);
  return storage.dir === config.memoryDir;
}

/**
 * Merge the {@link resolveMemorySearchDefaultFallback} result into a profile
 * read-namespace set without duplicates. Returns the original set unchanged
 * when no fallback applies.
 */
export function mergeMemorySearchDefaultFallback(
  profileNamespaces: string[],
  fallback: string | null,
): string[] {
  if (!fallback || profileNamespaces.includes(fallback)) return profileNamespaces;
  return [...profileNamespaces, fallback];
}


/**
 * Run a memory_search namespace fanout with the observability required by
 * issue #2018: a silent empty fanout is surfaced as a warning (never silently
 * empty), and per-namespace backend degradations — which memory_search
 * previously swallowed — are collected and warned so a missing collection
 * looks different from a genuine no-matches.
 *
 * `search` is injected so this stays free of the orchestrator type.
 */
export async function runMemorySearchFanout<TResult>(options: {
  query: string;
  namespaces: string[];
  maxResults?: number;
  principal?: string;
  requestedNamespace?: string;
  collection?: string;
  mode?: "search" | "hybrid" | "bm25" | "vector";
  search(params: {
    query: string;
    namespaces: string[];
    maxResults?: number;
    mode: "search" | "hybrid" | "bm25" | "vector";
    execution: SearchExecutionOptions;
  }): Promise<TResult[]>;
}): Promise<TResult[]> {
  const { query, namespaces, maxResults, principal, requestedNamespace, collection } = options;
  if (namespaces.length === 0) {
    log.warn("memory_search resolved zero readable namespaces", {
      principal: principal ?? null,
      requestedNamespace: requestedNamespace ?? null,
      collection: collection ?? null,
    });
    return [];
  }
  log.debug("memory_search fanout", {
    principal: principal ?? null,
    namespaces,
    collection: collection ?? null,
  });
  const degradations: SearchDegradation[] = [];
  const results = await options.search({
    query,
    namespaces,
    maxResults,
    mode: options.mode ?? "search",
    execution: {
      onDegradation: (degradation) => degradations.push(degradation),
    },
  });
  if (degradations.length > 0) {
    log.warn("memory_search backend degradation", {
      principal: principal ?? null,
      degradations,
    });
  }
  return results;
}

/**
 * Resolve results for a FLAT corpus (namespaces disabled).
 *
 * An explicit ranking mode routes through the namespace-aware search even
 * here, because that is the only path honoring it; the legacy direct-QMD calls
 * stay the default so nothing else moves.
 */
/**
 * Reject an option combination a flat corpus cannot honor.
 *
 * A `mode` routes through the namespace-aware backend, which cannot target a
 * specific collection, so pairing the two would silently search the default
 * collection and return unrelated results (AGENTS.md pattern 39).
 *
 * Exported as its own step because callers validate BEFORE any budget
 * short-circuit: changing only the requested result count must never make an
 * invalid request succeed.
 */
export const MEMORY_SEARCH_MODES = ["search", "hybrid", "bm25", "vector"] as const;

export type MemorySearchMode = (typeof MEMORY_SEARCH_MODES)[number];

/**
 * Reject an unrecognized ranking mode at the service boundary.
 *
 * The HTTP and MCP schemas already validate their own input, but an
 * in-process caller reaches this service untyped. Both namespace backends
 * route an unknown mode through their DEFAULT ordinary-search branch, so a
 * typo would silently rank differently instead of reporting bad input
 * (AGENTS.md §39).
 */
/**
 * Reject a budget that is not a finite non-negative integer.
 *
 * The HTTP and MCP schemas validate their own input, but an in-process caller
 * reaches this service untyped: a negative would hit the `budget <= 0`
 * short-circuit and return a successful EMPTY page, and a fraction or a
 * non-finite value would flow into the backend limit and top-up arithmetic.
 * Zero keeps its documented meaning — an empty result with no backend call.
 */
export function assertMemorySearchLimit(maxResults: unknown): void {
  if (maxResults === undefined) return;
  if (typeof maxResults !== "number" || !Number.isInteger(maxResults) || maxResults < 0) {
    throw new EngramAccessInputError(
      `maxResults must be a non-negative integer (got ${JSON.stringify(maxResults)})`,
    );
  }
}

export function assertMemorySearchMode(mode: unknown): void {
  if (mode === undefined) return;
  if (typeof mode !== "string" || !(MEMORY_SEARCH_MODES as readonly string[]).includes(mode)) {
    throw new EngramAccessInputError(
      `mode must be one of ${MEMORY_SEARCH_MODES.join(", ")} (got ${JSON.stringify(mode)})`,
    );
  }
}

export function assertFlatCorpusOptions(
  mode: string | undefined,
  collection: string | undefined,
): void {
  assertMemorySearchMode(mode);
  if (mode && collection) {
    throw new EngramAccessInputError(
      `mode is not supported together with collection on a flat corpus (got collection: ${collection})`,
    );
  }
}

export async function runFlatCorpusMemorySearch<TResult>(options: {
  query: string;
  maxResults?: number;
  collection?: string;
  mode?: "search" | "hybrid" | "bm25" | "vector";
  searchAcrossNamespaces(params: {
    query: string;
    maxResults?: number;
    mode: "search" | "hybrid" | "bm25" | "vector";
  }): Promise<TResult[]>;
  searchGlobal(query: string, maxResults?: number): Promise<TResult[]>;
  search(query: string, collection: string | undefined, maxResults?: number): Promise<TResult[]>;
}): Promise<TResult[]> {
  const { query, maxResults, collection, mode } = options;
  assertFlatCorpusOptions(options.mode, options.collection);
  if (mode) {
    // The mode-aware backend has no collection selector on a flat corpus, so
    // honoring the mode would silently search the default collection instead
    return options.searchAcrossNamespaces({ query, maxResults, mode });
  }
  return collection === "global"
    ? options.searchGlobal(query, maxResults)
    : options.search(query, collection, maxResults);
}

/**
 * How far one generic memory search may page before it stops.
 *
 * A backend-safety bound, NOT a stand-in for corpus exhaustion — which is why
 * it is ABSOLUTE rather than a multiple of the caller's budget. Scaling it to
 * the budget made "the excluded paths happen to rank first" indistinguishable
 * from "there is nothing else": a 1,000-row request whose first 4,000 hits are
 * artifacts stopped at 4,000 and returned an empty page while valid memories
 * sat at rank 4,001. Pages that come back FULL mean the corpus is not
 * exhausted, so the loop keeps going until a short page proves it is or this
 * cap protects the backend.
 */
const MEMORY_SEARCH_CANDIDATE_CAP = 25_000;


/**
 * Run a ranked memory search and apply the generic-recall path exclusions
 * BEFORE the user-facing cap.
 *
 * Artifact isolation is a retrieval contract, not a ranking preference:
 * artifacts flow only through the dedicated verbatim path. Filtering after the
 * backend's own cap would let a handful of top-ranked artifacts shrink - or
 * empty - a page that has valid memories right behind them, so the search runs
 * with candidate headroom and tops up until the post-filter budget is met or
 * the corpus is exhausted.
 */
export async function searchWithGenericExclusion<TResult extends { path: string }>(options: {
  budget: number;
  /**
   * `false` omits `maxResults` on the FIRST request, so a caller that named no
   * budget keeps the backend's own page size on the wire; the resolved budget
   * is still what the filtered page is measured against.
   */
  sendInitialLimit: boolean;
  search(limit: number | undefined): Promise<TResult[]>;
  filterPrivate(results: TResult[]): Promise<TResult[]>;
  isExcluded(memoryPath: string): boolean;
}): Promise<TResult[]> {
  const { budget } = options;
  if (budget <= 0) return [];
  let results: TResult[] = [];
  let limit: number | undefined = options.sendInitialLimit ? budget : undefined;
  // With no explicit limit the caller asked for the BACKEND's page, so that
  // page's size is the target — not the configured cap. Using the cap would
  // reissue the query whenever the backend's default page is smaller, and
  // return more rows than the same request used to.
  let target = budget;
  let firstPage = true;
  for (;;) {
    const raw = await options.search(limit);
    const eligible = raw.filter((hit) => !options.isExcluded(hit.path));
    results = await options.filterPrivate(eligible);
    if (firstPage) {
      firstPage = false;
      if (!options.sendInitialLimit) target = Math.min(budget, raw.length);
      if (target <= 0) return [];
    }
    if (results.length >= target) break;
    // What the backend actually served this round: its own page size when we
    // named no limit.
    const served = limit ?? raw.length;
    // A short page means the corpus is exhausted - asking for more is wasted
    // work that returns the same rows.
    if (raw.length === 0 || raw.length < served) break;
    // The cap protects the backend from an unbounded walk, but it can never
    // sit at or below what the caller explicitly asked for: a request for N
    // rows needs room BEYOND N to replace the excluded hits among them, or a
    // large search returns a short page for a count the operation deliberately
    // supports.
    const cap = Math.max(MEMORY_SEARCH_CANDIDATE_CAP, target * 2);
    if (served >= cap) break;
    limit = Math.min(served * 2, cap);
  }
  return results.slice(0, target);
}

/**
 * The whole ranked memory-search path behind `POST /engram/v1/memories/search`
 * and the `memory_search` tool: pick the flat-corpus or namespace-aware
 * backend, then apply generic-recall exclusions before the caller's cap.
 */
export async function runScopedMemorySearch(options: {
  query: string;
  budget: number;
  /** `false` when the caller named no `maxResults`; see the helper below. */
  sendInitialLimit: boolean;
  /**
   * Authorize the scope. Runs BEFORE any budget decision so a zero budget - a
   * valid empty search - can never skip the namespace/principal gate and turn
   * an access error into a successful empty result.
   */
  authorizeScope(): Promise<void> | void;
  collection?: string;
  mode?: "search" | "hybrid" | "bm25" | "vector";
  namespacesEnabled: boolean;
  isExcluded(memoryPath: string): boolean;
  filterPrivate(
    results: Array<{ path: string; score: number; snippet?: string }>,
  ): Promise<Array<{ path: string; score: number; snippet?: string }>>;
  flatCorpus(
    limit: number | undefined,
  ): Promise<Array<{ path: string; score: number; snippet?: string }>>;
  namespaced(
    limit: number | undefined,
  ): Promise<Array<{ path: string; score: number; snippet?: string }>>;
}): Promise<Array<{ path: string; score: number; snippet: string }>> {
  await options.authorizeScope();
  const results = await searchWithGenericExclusion({
    budget: options.budget,
    sendInitialLimit: options.sendInitialLimit,
    isExcluded: options.isExcluded,
    filterPrivate: options.filterPrivate,
    search: (limit) =>
      options.namespacesEnabled ? options.namespaced(limit) : options.flatCorpus(limit),
  });
  return results.map((hit) => ({
    path: hit.path,
    score: hit.score,
    snippet: (hit.snippet ?? "").slice(0, 800),
  }));
}

/** Everything the ranked memory-search surface needs from the service. */
export interface ScopedMemorySearchDeps {
  namespacesEnabled: boolean;
  defaultBudget: number;
  memoryCollections: readonly string[];
  isExcluded(memoryPath: string): boolean;
  filterPrivate(
    results: Array<{ path: string; score: number; snippet?: string }>,
    namespaces: readonly string[],
    preserveUnresolved?: boolean,
    visibilityCache?: Map<string, boolean>,
  ): Promise<Array<{ path: string; score: number; snippet?: string }>>;
  /** Flat-corpus authorization; throws when the namespace is unreadable. */
  authorizeFlatCorpus(namespace: string | undefined, principal: string | undefined): void;
  /** Namespace-aware authorization; throws, else returns the search fan-out. */
  authorizeNamespaces(
    namespace: string | undefined,
    principal: string | undefined,
    collection: string | undefined,
  ): Promise<string[]>;
  searchAcrossNamespaces(params: {
    query: string;
    namespaces?: string[];
    maxResults?: number;
    mode?: "search" | "hybrid" | "bm25" | "vector";
  }): Promise<Array<{ path: string; score: number; snippet?: string }>>;
  searchGlobal(
    query: string,
    maxResults?: number,
  ): Promise<Array<{ path: string; score: number; snippet?: string }>>;
  search(
    query: string,
    collection?: string,
    maxResults?: number,
  ): Promise<Array<{ path: string; score: number; snippet?: string }>>;
}

/** The whole `memory_search` surface: validate, authorize, search, shape. */
export async function memorySearchThroughScope(
  deps: ScopedMemorySearchDeps,
  request: {
    query: string;
    namespace?: string;
    maxResults?: number;
    collection?: string;
    mode?: "search" | "hybrid" | "bm25" | "vector";
    principal?: string;
  },
): Promise<{
  query: string;
  results: Array<{ path: string; score: number; snippet: string }>;
  count: number;
}> {
  const { query, namespace, maxResults, mode, principal } = request;
  // BOTH branches take the mode, and only the flat one reaches
  // `assertFlatCorpusOptions` — validate here so a namespaced request cannot
  // rank differently on a typo, and before any budget short-circuit.
  assertMemorySearchMode(mode);
  assertMemorySearchLimit(maxResults);
  const collection = request.collection?.trim();
  if (request.collection !== undefined && !collection) {
    throw new EngramAccessInputError("collection must be a non-empty string");
  }
  let searchNamespaces: string[] = [];
  const privateVisibilityCache = new Map<string, boolean>();
  const results = await runScopedMemorySearch({
    query, collection, mode,
    namespacesEnabled: deps.namespacesEnabled,
    isExcluded: deps.isExcluded,
    filterPrivate: (results) => deps.filterPrivate(
      results,
      searchNamespaces,
      !deps.namespacesEnabled &&
        collection !== undefined &&
        collection !== "global" &&
        !deps.memoryCollections.includes(collection),
      privateVisibilityCache,
    ),
    budget: maxResults ?? deps.defaultBudget,
    sendInitialLimit: maxResults !== undefined,
    authorizeScope: async () => {
      if (!deps.namespacesEnabled) {
        // Validate the option combination here too: a zero budget must not be
        // a way to slip an invalid request past the check.
        assertFlatCorpusOptions(mode, collection);
        return deps.authorizeFlatCorpus(namespace, principal);
      }
      searchNamespaces = await deps.authorizeNamespaces(namespace, principal, collection);
    },
    flatCorpus: (limit) =>
      runFlatCorpusMemorySearch({
        query, maxResults: limit, collection, mode,
        searchAcrossNamespaces: (p) => deps.searchAcrossNamespaces(p),
        searchGlobal: (q, globalLimit) => deps.searchGlobal(q, globalLimit),
        search: (q, coll, searchLimit) => deps.search(q, coll, searchLimit),
      }),
    namespaced: (limit) =>
      runMemorySearchFanout({
        query, maxResults: limit, principal, collection, mode,
        requestedNamespace: namespace,
        namespaces: searchNamespaces,
        search: (p) => deps.searchAcrossNamespaces(p),
      }),
  });
  return { query, results, count: results.length };
}

