export interface EvidencePackSelectionReceipt {
  item: EvidencePackSelectedItem;
  /** Half-open offsets within the returned evidence-pack string. */
  blockStart: number;
  blockEnd: number;
}

const DEFAULT_MAX_ITEM_CHARS = 1_200;
const QUERY_FOCUS_STOPWORDS = new Set([
  "about",
  "after",
  "again",
  "also",
  "and",
  "are",
  "between",
  "can",
  "could",
  "did",
  "does",
  "during",
  "for",
  "from",
  "have",
  "how",
  "into",
  "many",
  "should",
  "that",
  "the",
  "this",
  "till",
  "until",
  "want",
  "was",
  "were",
  "what",
  "when",
  "which",
  "with",
  "would",
  "you",
]);

export function buildEvidencePack(
  items: readonly EvidencePackItem[],
  options: EvidencePackOptions,
): string {
  const budget = normalizePositiveInteger(options.maxChars);
  if (budget <= 0 || items.length === 0) {
    return "";
  }

  const maxItemChars = normalizePositiveInteger(
    options.maxItemChars ?? DEFAULT_MAX_ITEM_CHARS,
  );
  if (maxItemChars <= 0) {
    return "";
  }

  const title = options.title ?? "Evidence";
  const lines: string[] = [`## ${title}`];
  const seenIds = new Set<string>();
  const seenContent = new Set<string>();
  let used = lines[0]!.length;

  for (const item of items) {
    const content = item.content.trim();
    if (!content) continue;

    const id = item.id ?? evidenceItemFallbackId(item);
    if (id && seenIds.has(id)) continue;

    const contentKey = normalizeEvidenceContent(content);
    if (seenContent.has(contentKey)) continue;

    const label = formatEvidenceLabel(item);
    const clipped = clipEvidenceContent(content, maxItemChars, options.query);
    const block = `${label}: ${clipped}`;
    const separatorLength = lines.length > 0 ? 2 : 0;
    const remaining = budget - used - separatorLength;
    if (remaining <= 0) break;

    const finalBlock =
      block.length > remaining ? clipText(block, remaining) : block;
    if (!finalBlock.trim()) break;

    const blockStart = used + separatorLength;
    const blockEnd = blockStart + finalBlock.length;
    lines.push(finalBlock);
    used += separatorLength + finalBlock.length;
    if (id) seenIds.add(id);
    seenContent.add(contentKey);
    options.onSelection?.({
      item: evidencePackSelectedItem(item),
      blockStart,
      blockEnd,
    });
  }

  return lines.length === 1 ? "" : lines.join("\n\n");
}

function evidencePackSelectedItem(
  item: EvidencePackItem,
): EvidencePackSelectedItem {
  return {
    ...(typeof item.archiveRowId === "number"
      ? { archiveRowId: item.archiveRowId }
      : {}),
    ...(typeof item.turnIndex === "number" ? { turnIndex: item.turnIndex } : {}),
    ...(typeof item.role === "string" ? { role: item.role } : {}),
    ...(typeof item.score === "number" && Number.isFinite(item.score)
      ? { score: item.score }
      : {}),
  };
}

export function insertAfterEvidenceHeading(
  evidence: string,
  title: string,
  insert: string,
): string {
  const heading = `## ${title}`;
  if (!evidence.startsWith(heading)) {
    return evidence;
  }
  return `${heading}${insert}${evidence.slice(heading.length)}`;
}

function normalizePositiveInteger(value: number): number {
  if (!Number.isFinite(value) || value <= 0) {
    return 0;
  }
  return Math.floor(value);
}

function evidenceItemFallbackId(item: EvidencePackItem): string | undefined {
  if (item.sessionId && typeof item.turnIndex === "number") {
    return `${item.sessionId}:${item.turnIndex}`;
  }
  return undefined;
}

function normalizeEvidenceContent(content: string): string {
  return content.toLowerCase().replace(/\s+/g, " ").trim();
}

function formatEvidenceLabel(item: EvidencePackItem): string {
  const parts: string[] = [];
  if (item.sessionId) parts.push(item.sessionId);
  if (typeof item.turnIndex === "number") parts.push(`turn ${item.turnIndex}`);
  if (item.role) parts.push(item.role);
  if (typeof item.score === "number" && Number.isFinite(item.score)) {
    parts.push(`score ${item.score.toFixed(3)}`);
  }
  return parts.length > 0 ? `[${parts.join(", ")}]` : "[evidence]";
}

function clipText(text: string, maxChars: number): string {
  if (text.length <= maxChars) {
    return text;
  }
  if (maxChars <= 1) {
    return text.slice(0, maxChars);
  }
  if (maxChars <= 3) {
    return text.slice(0, maxChars);
  }
  return `${text.slice(0, maxChars - 3).trimEnd()}...`;
}

function clipEvidenceContent(
  content: string,
  maxChars: number,
  query?: string,
): string {
  if (content.length <= maxChars) {
    return content;
  }

  const focused = buildQueryFocusedExcerpt(content, maxChars, query);
  return focused ?? clipText(content, maxChars);
}

function buildQueryFocusedExcerpt(
  content: string,
  maxChars: number,
  query?: string,
): string | undefined {
  const cues = collectQueryFocusCues(query ?? "");
  if (cues.length === 0) {
    return undefined;
  }

  const lines = content
    .replaceAll("\r\n", "\n")
    .replaceAll("\r", "\n")
    .split("\n")
    .map((line) => line.trim())
    .filter((line) => line.length > 0);
  if (lines.length < 2) {
    return undefined;
  }

  const temporalIntent = hasTemporalFocusIntent(query ?? "");
  const scored = lines
    .map((line, index) => ({
      index,
      score: scoreEvidenceLine(line, cues, temporalIntent, index),
    }))
    .filter((entry) => entry.score > 0)
    .sort((left, right) => right.score - left.score || left.index - right.index);

  if (scored.length === 0) {
    return undefined;
  }

  let selected = new Set<number>();
  for (let index = 0; index < Math.min(3, lines.length); index += 1) {
    if (isEvidenceMetadataLine(lines[index]!)) {
      selected.add(index);
    }
  }

  for (const entry of scored.slice(0, 8)) {
    const candidate = new Set(selected);
    const radius = lineWindowRadius(lines[entry.index]!, temporalIntent);
    for (
      let index = Math.max(0, entry.index - radius);
      index <= Math.min(lines.length - 1, entry.index + radius);
      index += 1
    ) {
      candidate.add(index);
    }
    if (renderSelectedEvidenceLines(lines, candidate).length <= maxChars) {
      selected = candidate;
    }
  }

  const excerpt = buildExcerptFromLineSelection(lines, selected, maxChars);
  return excerpt.length > 0 ? excerpt : undefined;
}

function collectQueryFocusCues(query: string): string[] {
  const words = (query.toLowerCase().match(/[a-z][a-z0-9-]{2,}/g) ?? [])
    .map(trimBoundaryHyphens)
    .filter(
      (word) =>
        word.length >= 3 &&
        !/^\d+$/.test(word) &&
        !QUERY_FOCUS_STOPWORDS.has(word),
    );
  const cues = new Set<string>();
  for (const word of words) {
    cues.add(word);
  }
  for (let index = 0; index < words.length - 1; index += 1) {
    const left = words[index]!;
    const right = words[index + 1]!;
    if (left.length >= 4 && right.length >= 4) {
      cues.add(`${left} ${right}`);
    }
  }
  for (let index = 0; index < words.length - 2; index += 1) {
    const left = words[index]!;
    const middle = words[index + 1]!;
    const right = words[index + 2]!;
    if (left.length >= 4 && middle.length >= 4 && right.length >= 4) {
      cues.add(`${left} ${middle} ${right}`);
    }
  }
  return [...cues].sort((left, right) => right.length - left.length || left.localeCompare(right));
}

function trimBoundaryHyphens(value: string): string {
  let start = 0;
  let end = value.length;
  while (start < end && value[start] === "-") {
    start += 1;
  }
  while (end > start && value[end - 1] === "-") {
    end -= 1;
  }
  return start === 0 && end === value.length ? value : value.slice(start, end);
}

function hasTemporalFocusIntent(query: string): boolean {
  return /\b(?:after|before|between|date|deadline|during|finish(?:ing|ed)?|how many|timeline|week|weeks|when)\b/i.test(
    query,
  );
}

function scoreEvidenceLine(
  line: string,
  cues: readonly string[],
  temporalIntent: boolean,
  index: number,
): number {
  const normalized = line.toLowerCase();
  let score = 0;
  for (const cue of cues) {
    if (!normalized.includes(cue)) {
      continue;
    }
    score += cue.includes(" ") ? 8 : 3;
  }
  if (temporalIntent && hasDateLikeEvidence(line)) {
    score += 6;
  }
  if (
    temporalIntent &&
    /\b(?:deadline|deployment|finish(?:ing|ed)?|milestones?|schedule|timeline)\b/i.test(line)
  ) {
    score += 5;
  }
  if (/^\s{0,3}(?:#{1,6}\s*)?(?:milestones?|schedule|timeline)\b/i.test(line)) {
    score += 3;
  }
  if (isEvidenceMetadataLine(line)) {
    score += Math.max(0, 3 - index);
  }
  return score;
}

function hasDateLikeEvidence(line: string): boolean {
  return /\b(?:Jan(?:uary)?|Feb(?:ruary)?|Mar(?:ch)?|Apr(?:il)?|May|Jun(?:e)?|Jul(?:y)?|Aug(?:ust)?|Sep(?:tember)?|Oct(?:ober)?|Nov(?:ember)?|Dec(?:ember)?)\.?\s+\d{1,2}\b/i.test(
    line,
  ) || /\b\d{4}-\d{2}-\d{2}\b/.test(line);
}

function isEvidenceMetadataLine(line: string): boolean {
  return /\b(?:chat_id|source_chat_id|session_id|plan_id|task_id|ability)=/.test(
    line,
  );
}

function lineWindowRadius(line: string, temporalIntent: boolean): number {
  if (temporalIntent && hasDateLikeEvidence(line)) {
    return 0;
  }
  if (temporalIntent && /^\s{0,3}(?:#{1,6}\s*)?(?:milestones?|schedule|timeline)\b/i.test(line)) {
    return 2;
  }
  return 1;
}

function buildExcerptFromLineSelection(
  lines: readonly string[],
  selected: ReadonlySet<number>,
  maxChars: number,
): string {
  const ordered = [...selected].sort((left, right) => left - right);
  const output: string[] = [];
  let used = 0;
  let lastIndex = -1;

  const append = (text: string): boolean => {
    const separator = output.length === 0 ? "" : "\n";
    const remaining = maxChars - used - separator.length;
    if (remaining <= 0) {
      return false;
    }
    const value = text.length > remaining ? clipText(text, remaining) : text;
    if (!value.trim()) {
      return false;
    }
    output.push(value);
    used += separator.length + value.length;
    return text.length <= remaining;
  };

  for (const index of ordered) {
    if (lastIndex >= 0 && index > lastIndex + 1 && !append("...")) {
      break;
    }
    if (!append(lines[index]!)) {
      break;
    }
    lastIndex = index;
  }

  return output.join("\n");
}

function renderSelectedEvidenceLines(
  lines: readonly string[],
  selected: ReadonlySet<number>,
): string {
  const ordered = [...selected].sort((left, right) => left - right);
  const output: string[] = [];
  let lastIndex = -1;
  for (const index of ordered) {
    if (lastIndex >= 0 && index > lastIndex + 1) {
      output.push("...");
    }
    output.push(lines[index]!);
    lastIndex = index;
  }
  return output.join("\n");
}

/**
 * Procedure library health maintenance (issue #2370).
 *
 * The library-health loop the agent-memory survey describes: consume the
 * telemetry Remnic already records (Memory Worth counters, access
 * timestamps, causal trajectories) and propose merge / repair-flag /
 * retire transitions for ACTIVE procedure memories.
 *
 * Shadow-first contract (mirrors `memory_governance_run`): the default run
 * mode produces a JSON report and writes NOTHING — not even the run
 * marker. Applying requires `apply: true` AND
 * `procedural.maintenance.enabled: true`.
 *
 * Actions, evaluated in this order per run:
 *   1. Merge   — cluster active procedures by normalized trigger phrase +
 *                step signature; most-recently-updated member becomes the
 *                canonical, the rest are superseded pointing at it. The
 *                canonical is stamped with the issue-#687 frontmatter
 *                contract (`reinforcement_count`, `last_reinforced_at`,
 *                `derived_via`, `derived_from`) so `patterns explain` reads
 *                procedure canonicals unchanged. A user-edited body never
 *                merges — the cluster is flagged instead.
 *   2. Repair  — flag (never rewrite) procedures whose `ProcedureStep`
 *                toolCall tools no longer appear in recent causal
 *                trajectories, via `structuredAttributes.needsRepair`.
 *   3. Retire  — demote to `archived` when failure-dominant past the
 *                configured thresholds, or idle past `retireIdleDays` with
 *                zero recorded outcomes. Demotion, never deletion; page
 *                versioning snapshots every overwrite. User-edited
 *                procedures are exempt and flagged instead.
 *
 * Deliberately NOT part of `runMemoryGovernance` — same isolation decision
 * as procedure mining (docs/procedural-memory.md).
 */

import path from "node:path";
import type { MemoryFile, PluginConfig } from "../types.js";
import { isActiveMemoryStatus } from "../memory-lifecycle-ledger-utils.js";
import { bumpMemoryCorpusVersionForDir } from "../memory-corpus-version.js";
import {
  buildProcedurePersistBody,
  parseProcedureStepsFromBody,
  type ProcedureStep,
} from "./procedure-types.js";
import {
  filterTrajectoriesByLookbackDays,
  readCausalTrajectoryRecords,
  type CausalTrajectoryRecord,
} from "../causal-trajectory.js";
import { readJsonFile, writeJsonFileAtomic } from "../json-store.js";
import { log } from "../logger.js";

type ProcedureLibraryStorage = {
  readAllMemories: () => Promise<MemoryFile[]>;
  writeMemoryFrontmatter: (
    memory: MemoryFile,
    patch: Record<string, unknown>,
    extras?: Record<string, unknown>,
  ) => Promise<unknown>;
  archiveMemory: (
    memory: MemoryFile,
    opts: {
      at: Date;
      actor: string;
      reasonCode: string;
      ruleVersion?: string;
      relatedMemoryIds?: string[];
    },
  ) => Promise<string | null>;
};

const MAINTENANCE_ACTOR = "procedure-library-maintenance";
const MAINTENANCE_RULE_VERSION = "procedure-library-maintenance:1";

export type ProcedureMaintenanceActionKind =
  | "merge"
  | "retire"
  | "flag_repair"
  | "flag_user_edited";

export type ProcedureMaintenanceReasonCode =
  | "merge_duplicate_signature"
  | "retire_failure_dominant"
  | "retire_idle"
  | "needs_repair_stale_tools"
  | "user_edited_protected";

export interface ProcedureMaintenanceEvidence {
  memoryId: string;
  mwSuccess: number;
  mwFail: number;
  lastAccessed: string | null;
  updated: string | null;
}

export interface ProcedureMaintenanceAction {
  action: ProcedureMaintenanceActionKind;
  reasonCode: ProcedureMaintenanceReasonCode;
  /** Canonical first for merges; otherwise the single targeted memory. */
  memoryIds: string[];
  canonicalId?: string;
  reason: string;
  evidence: ProcedureMaintenanceEvidence[];
}

export interface ProcedureLibraryMaintenanceReport {
  schemaVersion: 1;
  generatedAt: string;
  mode: "shadow" | "apply";
  scannedProcedures: number;
  proposed: ProcedureMaintenanceAction[];
  applied: ProcedureMaintenanceAction[];
  appliedCount: number;
  skippedReason?: "procedural_disabled" | "maintenance_disabled";
}

export interface ProcedureMaintenanceMarker {
  schemaVersion: 1;
  lastRunAt: string;
  lastApplyAt: string | null;
  appliedCount: number;
}

function maintenanceMarkerPath(memoryDir: string): string {
  return path.join(memoryDir, "state", "procedure-maintenance.json");
}

/** Read the last-run marker. Absent marker (or shadow-only history) → null apply timestamp. */
export async function readProcedureMaintenanceMarker(
  memoryDir: string,
): Promise<ProcedureMaintenanceMarker | null> {
  try {
    const raw = await readJsonFile(maintenanceMarkerPath(memoryDir));
    if (raw === null || typeof raw !== "object" || Array.isArray(raw)) return null;
    const m = raw as Record<string, unknown>;
    if (typeof m.lastRunAt !== "string") return null;
    return {
      schemaVersion: 1,
      lastRunAt: m.lastRunAt,
      lastApplyAt: typeof m.lastApplyAt === "string" ? m.lastApplyAt : null,
      appliedCount: typeof m.appliedCount === "number" ? m.appliedCount : 0,
    };
  } catch {
    return null;
  }
}

function evidenceFor(m: MemoryFile): ProcedureMaintenanceEvidence {
  return {
    memoryId: m.frontmatter.id,
    mwSuccess: m.frontmatter.mw_success ?? 0,
    mwFail: m.frontmatter.mw_fail ?? 0,
    lastAccessed: m.frontmatter.lastAccessed ?? null,
    updated: m.frontmatter.updated ?? null,
  };
}

function tsMs(value: unknown): number | null {
  if (typeof value !== "string") return null;
  const ms = Date.parse(value);
  return Number.isFinite(ms) ? ms : null;
}

/** Title line of a procedure body — everything before the first `## Step N` header. */
function procedureTitle(content: string): string {
  const text = content.replace(/\r\n/g, "\n").trim();
  const idx = text.search(/^##\s+Step\s+\d+\s*$/im);
  return (idx === -1 ? text : text.slice(0, idx)).trim();
}

function normalizePhrase(s: string): string {
  return s
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, " ")
    .trim();
}

/** Ordered (intent, tool) signature — the machine-mined shape of a procedure. */
function stepSignature(steps: ProcedureStep[] | null): string {
  if (steps === null) return "<unparsed>";
  return steps
    .map(
      (s) =>
        `${s.order}|${normalizePhrase(s.intent)}|${s.toolCall?.kind ?? ""}|${s.toolCall?.signature ?? ""}`,
    )
    .join(";;");
}

/**
 * A procedure is user-edited when its body no longer round-trips through the
 * miner's own serializer for its parsed steps — the stateless equivalent of
 * "body hash differs from last mined write". Freeform bodies with no step
 * headers count as user-authored.
 */
export function isUserEditedProcedure(content: string): boolean {
  const steps = parseProcedureStepsFromBody(content);
  if (steps === null) return true;
  const rebuilt = buildProcedurePersistBody(procedureTitle(content), steps);
  return rebuilt.trim() !== content.replace(/\r\n/g, "\n").trim();
}

/** Most-recently-updated wins; total comparator with stable id tiebreak (§12). */
function compareCanonical(a: MemoryFile, b: MemoryFile): number {
  const aMs = tsMs(a.frontmatter.updated) ?? tsMs(a.frontmatter.created) ?? 0;
  const bMs = tsMs(b.frontmatter.updated) ?? tsMs(b.frontmatter.created) ?? 0;
  if (aMs !== bMs) return aMs > bMs ? -1 : 1;
  const aId = a.frontmatter.id ?? "";
  const bId = b.frontmatter.id ?? "";
  if (aId !== bId) return aId < bId ? -1 : 1;
  return 0;
}

function recentTrajectoryToolText(
  trajectories: readonly CausalTrajectoryRecord[],
): string {
  return trajectories.map((r) => r.actionSummary).join("\n").toLowerCase();
}

/**
 * Run one library-health maintenance pass over the procedures in a storage.
 * Shadow mode performs NO writes (not even the state marker).
 */
export async function runProcedureLibraryMaintenance(options: {
  storage: ProcedureLibraryStorage,
  memoryDir: string;
  config: PluginConfig;
  apply?: boolean;
  now?: Date;
}): Promise<ProcedureLibraryMaintenanceReport> {
  const now = options.now ?? new Date();
  const nowIso = now.toISOString();
  const mode: "shadow" | "apply" = options.apply === true ? "apply" : "shadow";
  const cfg = options.config.procedural;
  if (cfg?.enabled !== true || cfg.maintenance?.enabled !== true) {
    return {
      schemaVersion: 1,
      generatedAt: nowIso,
      mode,
      scannedProcedures: 0,
      proposed: [],
      applied: [],
      appliedCount: 0,
      skippedReason: cfg?.enabled !== true ? "procedural_disabled" : "maintenance_disabled",
    };
  }
  const maintenance = cfg.maintenance;

  const all = await options.storage.readAllMemories();
  const byId = new Map<string, MemoryFile>();
  for (const m of all) {
    if (m.frontmatter.category !== "procedure") continue;
    // Only ACTIVE procedures are maintenance candidates. pending_review,
    // rejected, quarantined, superseded, and archived are never merge or
    // retire candidates (§41) — archived files live outside readAllMemories
    // entirely.
    if (!isActiveMemoryStatus(m.frontmatter.status)) continue;
    if (typeof m.frontmatter.id === "string" && m.frontmatter.id.length > 0) {
      byId.set(m.frontmatter.id, m);
    }
  }
  const activeProcedures = [...byId.values()];

  const report: ProcedureLibraryMaintenanceReport = {
    schemaVersion: 1,
    generatedAt: nowIso,
    mode,
    scannedProcedures: activeProcedures.length,
    proposed: [],
    applied: [],
    appliedCount: 0,
  };
  // Empty library: nothing to propose. Shadow returns immediately; an apply
  // run still falls through so the run marker records the pass.
  if (activeProcedures.length === 0 && mode === "shadow") return report;


  // --- 1. Merge -------------------------------------------------------------
  const mergeConsumed = new Set<string>();
  if (maintenance.mergeEnabled) {
    const clusters = new Map<string, MemoryFile[]>();
    for (const m of activeProcedures) {
      const steps = parseProcedureStepsFromBody(m.content);
      const key = `${normalizePhrase(procedureTitle(m.content))}\n@@\n${stepSignature(steps)}`;
      const bucket = clusters.get(key);
      if (bucket) bucket.push(m);
      else clusters.set(key, [m]);
    }
    for (const cluster of clusters.values()) {
      if (cluster.length < 2) continue;
      const sortedCluster = [...cluster].sort(compareCanonical);
      const userEdited = sortedCluster.filter((m) => isUserEditedProcedure(m.content));
      if (userEdited.length > 0) {
        report.proposed.push({
          action: "flag_user_edited",
          reasonCode: "user_edited_protected",
          memoryIds: sortedCluster.map((m) => m.frontmatter.id),
          reason:
            "duplicate-signature cluster contains user-edited bodies; merge skipped for manual review",
          evidence: sortedCluster.map(evidenceFor),
        });
        continue;
      }
      const canonical = sortedCluster[0]!;
      const duplicates = sortedCluster.slice(1);
      for (const m of sortedCluster) mergeConsumed.add(m.frontmatter.id);
      report.proposed.push({
        action: "merge",
        reasonCode: "merge_duplicate_signature",
        memoryIds: [canonical.frontmatter.id, ...duplicates.map((m) => m.frontmatter.id)],
        canonicalId: canonical.frontmatter.id,
        reason: `near-identical trigger phrase + step signature across ${sortedCluster.length} active procedures`,
        evidence: sortedCluster.map(evidenceFor),
      });
    }
  }

  // --- 2. Repair flag -------------------------------------------------------
  // Only meaningful when the lookback window holds trajectory evidence: an
  // empty window proves nothing about tool freshness.
  const trajectoryDir =
    typeof options.config.causalTrajectoryStoreDir === "string" &&
    options.config.causalTrajectoryStoreDir.trim().length > 0
      ? options.config.causalTrajectoryStoreDir.trim()
      : undefined;
  const { trajectories } = await readCausalTrajectoryRecords({
    memoryDir: options.memoryDir,
    causalTrajectoryStoreDir: trajectoryDir,
  });
  const recentTrajectories = filterTrajectoriesByLookbackDays(
    trajectories,
    cfg.lookbackDays,
    now.getTime(),
  );
  const repairFlags: ProcedureMaintenanceAction[] = [];
  const staleToolsByProcedure = new Map<string, string[]>();
  if (recentTrajectories.length > 0) {
    const toolText = recentTrajectoryToolText(recentTrajectories);
    for (const m of activeProcedures) {
      if (mergeConsumed.has(m.frontmatter.id)) continue;
      const steps = parseProcedureStepsFromBody(m.content);
      if (steps === null) continue;
      const tools = [
        ...new Set(
          steps
            .map((s) => s.toolCall?.kind)
            .filter((t): t is string => typeof t === "string" && t.length > 0),
        ),
      ];
      if (tools.length === 0) continue;
      const stale = tools.filter((t) => !toolText.includes(t.toLowerCase()));
      if (stale.length === 0) continue;
      staleToolsByProcedure.set(m.frontmatter.id, stale);
      repairFlags.push({
        action: "flag_repair",
        reasonCode: "needs_repair_stale_tools",
        memoryIds: [m.frontmatter.id],
        reason: `tools absent from last ${cfg.lookbackDays}d of trajectories: ${stale.join(", ")}`,
        evidence: [evidenceFor(m)],
      });
    }
  }

  // --- 3. Retire ------------------------------------------------------------
  const retireActions: ProcedureMaintenanceAction[] = [];
  const retireIds = new Set<string>();
  const idleMs = maintenance.retireIdleDays * 24 * 60 * 60 * 1000;
  for (const m of activeProcedures) {
    if (mergeConsumed.has(m.frontmatter.id)) continue;
    const mwSuccess = m.frontmatter.mw_success ?? 0;
    const mwFail = m.frontmatter.mw_fail ?? 0;
    const failureDominant =
      mwFail >= maintenance.retireMinOutcomes &&
      mwFail > mwSuccess * maintenance.retireFailRatio;
    // Half-open idle window (§23): fresh means last signal in
    // [now - idleMs, now); idle means strictly older than the window start.
    const lastSignalMs =
      tsMs(m.frontmatter.lastAccessed) ?? tsMs(m.frontmatter.updated);
    const idle =
      maintenance.retireIdleDays > 0 &&
      mwSuccess + mwFail === 0 &&
      lastSignalMs !== null &&
      lastSignalMs < now.getTime() - idleMs;
    const reasonCode: ProcedureMaintenanceReasonCode | null = failureDominant
      ? "retire_failure_dominant"
      : idle
        ? "retire_idle"
        : null;
    if (reasonCode === null) continue;
    if (isUserEditedProcedure(m.content)) {
      report.proposed.push({
        action: "flag_user_edited",
        reasonCode: "user_edited_protected",
        memoryIds: [m.frontmatter.id],
        reason: `user-edited body exempt from automatic retirement (${reasonCode} waived)`,
        evidence: [evidenceFor(m)],
      });
      continue;
    }
    retireIds.add(m.frontmatter.id);
    retireActions.push({
      action: "retire",
      reasonCode,
      memoryIds: [m.frontmatter.id],
      reason:
        reasonCode === "retire_failure_dominant"
          ? `mw_fail ${mwFail} >= ${maintenance.retireMinOutcomes} and > mw_success ${mwSuccess} * ${maintenance.retireFailRatio}`
          : `no access signal for ${maintenance.retireIdleDays}d and zero recorded outcomes`,
      evidence: [evidenceFor(m)],
    });
  }

  // Repair flags after merge/retire exclusions land in the report in
  // evaluation order (merge → repair → retire).
  for (const flag of repairFlags) {
    if (retireIds.has(flag.memoryIds[0]!)) continue;
    report.proposed.push(flag);
  }
  report.proposed.push(...retireActions);

  if (mode === "shadow") return report;

  // --- Apply ----------------------------------------------------------------
  const applied = report.proposed;
  let writes = 0;
  for (const action of applied) {
    try {
      if (action.action === "merge") {
        const canonicalId = action.canonicalId;
        const canonical = canonicalId !== undefined ? byId.get(canonicalId) : undefined;
        if (!canonical || canonicalId === undefined) continue;
        const memberIds = [...action.memoryIds].sort();
        const previousCount = canonical.frontmatter.reinforcement_count ?? 0;
        const newCount = Math.max(previousCount, memberIds.length);
        if (
          newCount !== canonical.frontmatter.reinforcement_count ||
          canonical.frontmatter.derived_via !== "pattern-reinforcement"
        ) {
          await options.storage.writeMemoryFrontmatter(
            canonical,
            {
              reinforcement_count: newCount,
              last_reinforced_at: nowIso,
              derived_via: "pattern-reinforcement",
              derived_from: memberIds,
              updated: nowIso,
            },
            {
              actor: MAINTENANCE_ACTOR,
              reasonCode: action.reasonCode,
              ruleVersion: MAINTENANCE_RULE_VERSION,
              relatedMemoryIds: memberIds,
            },
          );
          writes += 1;
        }
        for (const memberId of action.memoryIds) {
          if (memberId === canonicalId) continue;
          const member = byId.get(memberId);
          if (!member) continue;
          await options.storage.writeMemoryFrontmatter(
            member,
            {
              status: "superseded",
              supersededBy: canonicalId,
              supersededAt: nowIso,
              updated: nowIso,
            },
            {
              actor: MAINTENANCE_ACTOR,
              reasonCode: action.reasonCode,
              ruleVersion: MAINTENANCE_RULE_VERSION,
              relatedMemoryIds: [canonicalId],
            },
          );
          writes += 1;
        }
      } else if (action.action === "retire") {
        const memory = byId.get(action.memoryIds[0]!);
        if (!memory) continue;
        const archivedPath = await options.storage.archiveMemory(memory, {
          at: now,
          actor: `${MAINTENANCE_ACTOR}.apply`,
          reasonCode: action.reasonCode,
          ruleVersion: MAINTENANCE_RULE_VERSION,
          relatedMemoryIds: [],
        });
        if (archivedPath !== null) writes += 1;
      } else if (action.action === "flag_repair") {
        const memory = byId.get(action.memoryIds[0]!);
        if (!memory) continue;
        const existing = memory.frontmatter.structuredAttributes ?? {};
        const prior = existing.needsRepair;
        let priorReason: string | null = null;
        if (typeof prior === "string") {
          try {
            const parsed = JSON.parse(prior) as { reason?: unknown };
            if (typeof parsed.reason === "string") priorReason = parsed.reason;
          } catch {
            priorReason = prior;
          }
        }
        if (priorReason === action.reason) continue;
        const stamp = JSON.stringify({ reason: action.reason, detectedAt: nowIso });
        await options.storage.writeMemoryFrontmatter(
          memory,
          {
            structuredAttributes: { ...existing, needsRepair: stamp },
            updated: nowIso,
          },
          {
            actor: MAINTENANCE_ACTOR,
            reasonCode: action.reasonCode,
            ruleVersion: MAINTENANCE_RULE_VERSION,
          },
        );
        writes += 1;
      }
      // flag_user_edited writes nothing — flags are report-only by design.
      report.applied.push(action);
    } catch (err) {
      log.warn(
        `procedure-library-maintenance: action ${action.reasonCode} on ${action.memoryIds.join(",")} failed: ${err instanceof Error ? err.message : String(err)}`,
      );
    }
  }
  report.appliedCount = report.applied.length;

  if (writes > 0) {
    // Corpus bump so hot caches observe the pass. Archive already moved the
    // mention epoch when it removed the live file. Merge-supersede and repair
    // stamps are metadata-only, so this bump must not move the epoch.
    bumpMemoryCorpusVersionForDir(options.memoryDir, { indexedText: false });
  }
  try {
    await writeJsonFileAtomic(maintenanceMarkerPath(options.memoryDir), {
      schemaVersion: 1,
      lastRunAt: nowIso,
      lastApplyAt: nowIso,
      appliedCount: report.appliedCount,
    } satisfies ProcedureMaintenanceMarker);
  } catch (err) {
    log.warn(
      `procedure-library-maintenance: failed to persist run marker: ${err instanceof Error ? err.message : String(err)}`,
    );
  }
  return report;
}

/**
 * Procedural memory stats surface (issue #567 PR 5/5).
 *
 * Pure helper that tallies procedure memories by status and summarizes the
 * current `procedural.*` config so operators (and the dashboard) can see,
 * in one call, how procedural memory is behaving in a namespace.
 *
 * Consumed by:
 *   - CLI `remnic procedural stats`
 *   - HTTP `GET /engram/v1/procedural/stats`
 *   - MCP `remnic.procedural_stats` (+ `engram.procedural_stats` alias)
 */
import type { MemoryFile, MemoryStatus, PluginConfig } from "../types.js";
import type { StorageManager } from "../storage.js";
import { isActiveMemoryStatus } from "../memory-lifecycle-ledger-utils.js";
import { readProcedureMaintenanceMarker } from "./library-maintenance.js";

export interface ProcedureStatusCounts {
  total: number;
  active: number;
  pending_review: number;
  rejected: number;
  quarantined: number;
  superseded: number;
  archived: number;
  /** Any status the enum doesn't yet cover. */
  other: number;
}

export interface ProcedureStatsConfigSnapshot {
  enabled: boolean;
  minOccurrences: number;
  successFloor: number;
  autoPromoteOccurrences: number;
  autoPromoteEnabled: boolean;
  lookbackDays: number;
  recallMaxProcedures: number;
}

export interface ProcedureStatsRecent {
  /** ISO 8601 timestamp of the most recent procedure write, or null. */
  lastWriteAt: string | null;
  /** Count of procedure files with `created` (or `updated`) in the last 7 days. */
  writesLast7Days: number;
  /** Count of procedures whose `source` is the procedure miner. */
  minerSourced: number;
}

export interface ProcedureStatsReport {
  schemaVersion: 1;
  generatedAt: string;
  counts: ProcedureStatusCounts;
  recent: ProcedureStatsRecent;
  config: ProcedureStatsConfigSnapshot;
  /** ISO timestamp of the last library-maintenance run marker, or null (issue #2370). */
  lastMaintenanceAt: string | null;
  /** Active procedures currently carrying a `needsRepair` flag (issue #2370). */
  needsRepairFlags: number;
}

function snapshotConfig(config: PluginConfig): ProcedureStatsConfigSnapshot {
  const p = config.procedural;
  return {
    enabled: p?.enabled === true,
    minOccurrences: typeof p?.minOccurrences === "number" ? p.minOccurrences : 0,
    successFloor: typeof p?.successFloor === "number" ? p.successFloor : 0,
    autoPromoteOccurrences:
      typeof p?.autoPromoteOccurrences === "number"
        ? p.autoPromoteOccurrences
        : 0,
    autoPromoteEnabled: p?.autoPromoteEnabled === true,
    lookbackDays: typeof p?.lookbackDays === "number" ? p.lookbackDays : 0,
    recallMaxProcedures:
      typeof p?.recallMaxProcedures === "number" ? p.recallMaxProcedures : 0,
  };
}

function tsMs(value: unknown): number | null {
  if (typeof value !== "string") return null;
  const ms = Date.parse(value);
  return Number.isFinite(ms) ? ms : null;
}

/**
 * Read all memories from storage and tally procedures by status + recency.
 * `nowMs` is injectable so tests can pin the "last 7 days" window.
 */
export async function computeProcedureStats(options: {
  storage: StorageManager;
  config: PluginConfig;
  nowMs?: number;
}): Promise<ProcedureStatsReport> {
  const { storage, config } = options;
  const nowMs = options.nowMs ?? Date.now();
  const sevenDaysMs = 7 * 24 * 60 * 60 * 1000;

  const counts: ProcedureStatusCounts = {
    total: 0,
    active: 0,
    pending_review: 0,
    rejected: 0,
    quarantined: 0,
    superseded: 0,
    archived: 0,
    other: 0,
  };

  let lastWriteMs: number | null = null;
  let writesLast7Days = 0;
  let minerSourced = 0;
  let needsRepairFlags = 0;

  const known: MemoryStatus[] = [
    "active",
    "pending_review",
    "rejected",
    "quarantined",
    "superseded",
    "archived",
  ];

  // Iterate both live and archived memories so the counts surface matches
  // what operators expect when procedures have been archived via
  // `archiveMemory` (Codex P2 on #611). `readAllMemories` alone skips
  // `archive/`, which would otherwise underreport `counts.archived` and
  // `counts.total`.
  const seen = new Set<string>();
  const live = await storage.readAllMemories();
  const archived = await storage.readArchivedMemories();
  const pool: MemoryFile[] = [...live, ...archived];
  for (const m of pool) {
    if (m.frontmatter.category !== "procedure") continue;
    // Dedupe by id so a procedure appearing in both live + archive (mid-
    // archive race) isn't counted twice.
    if (seen.has(m.frontmatter.id)) continue;
    seen.add(m.frontmatter.id);
    counts.total += 1;
    const status = m.frontmatter.status ?? "active";
    if ((known as string[]).includes(status)) {
      // Safe index: the status enum values are the counts keys.
      (counts as unknown as Record<string, number>)[status] += 1;
    } else {
      counts.other += 1;
    }

    // Recency semantics (Codex P2 on #611): use the latest of `updated` and
    // `created`, not a fallback chain, so recently-edited procedures are
    // reflected in `lastWriteAt` and `writesLast7Days`. Missing timestamps
    // skip the row.
    const createdMs = tsMs(m.frontmatter.created);
    const updatedMs = tsMs(m.frontmatter.updated);
    const latestMs =
      createdMs !== null && updatedMs !== null
        ? Math.max(createdMs, updatedMs)
        : (updatedMs ?? createdMs);
    if (latestMs !== null) {
      if (lastWriteMs === null || latestMs > lastWriteMs) {
        lastWriteMs = latestMs;
      }
      // Exclusive upper bound per CLAUDE.md rule 35 — use half-open window.
      if (latestMs >= nowMs - sevenDaysMs && latestMs < nowMs) {
        writesLast7Days += 1;
      }
    }

    if (m.frontmatter.source === "procedure-miner") {
      minerSourced += 1;
    }
    if (
      m.frontmatter.structuredAttributes?.needsRepair !== undefined &&
      isActiveMemoryStatus(m.frontmatter.status)
    ) {
      needsRepairFlags += 1;
    }
  }

  const maintenanceMarker = await readProcedureMaintenanceMarker(storage.dir);
  return {
    schemaVersion: 1,
    generatedAt: new Date(nowMs).toISOString(),
    counts,
    recent: {
      lastWriteAt: lastWriteMs !== null ? new Date(lastWriteMs).toISOString() : null,
      writesLast7Days,
      minerSourced,
    },
    config: snapshotConfig(config),
    lastMaintenanceAt: maintenanceMarker?.lastRunAt ?? null,
    needsRepairFlags,
  };
}

/**
 * Render `ProcedureStatsReport` as a human-friendly plain-text block for CLI
 * operators. Keep it deterministic — no colors, no ANSI. Used by `--format text`.
 */
export function formatProcedureStatsText(report: ProcedureStatsReport): string {
  const { counts, recent, config } = report;
  const { autoPromoteEnabled } = config;
  const lines: string[] = [];
  lines.push(`Procedural memory stats (schema v${report.schemaVersion})`);
  lines.push(`  generated: ${report.generatedAt}`);
  lines.push("");
  lines.push(`  config:`);
  lines.push(`    enabled:                 ${config.enabled}`);
  lines.push(`    minOccurrences:          ${config.minOccurrences}`);
  lines.push(`    successFloor:            ${config.successFloor}`);
  lines.push(`    autoPromoteOccurrences:  ${config.autoPromoteOccurrences}`);
  lines.push(`    autoPromoteEnabled:      ${autoPromoteEnabled}`);
  lines.push(`    lookbackDays:            ${config.lookbackDays}`);
  lines.push(`    recallMaxProcedures:     ${config.recallMaxProcedures}`);
  lines.push("");
  lines.push(`  counts:`);
  lines.push(`    total:           ${counts.total}`);
  lines.push(`    active:          ${counts.active}`);
  lines.push(`    pending_review:  ${counts.pending_review}`);
  lines.push(`    rejected:        ${counts.rejected}`);
  lines.push(`    quarantined:     ${counts.quarantined}`);
  lines.push(`    superseded:      ${counts.superseded}`);
  lines.push(`    archived:        ${counts.archived}`);
  if (counts.other > 0) {
    lines.push(`    other:           ${counts.other}`);
  }
  lines.push("");
  lines.push(`  recent:`);
  lines.push(`    lastWriteAt:      ${recent.lastWriteAt ?? "(none)"}`);
  lines.push(`    writesLast7Days:  ${recent.writesLast7Days}`);
  lines.push(`    minerSourced:     ${recent.minerSourced}`);
  lines.push("");
  lines.push(`  maintenance:`);
  lines.push(`    lastMaintenanceAt: ${report.lastMaintenanceAt ?? "(never)"}`);
  lines.push(`    needsRepairFlags:  ${report.needsRepairFlags}`);
  return lines.join("\n") + "\n";
}

/**
 * Preference drift detection (issue #2371) — public barrel.
 *
 * Ordered leaf-first (types → config → pure recall stage → scan/resolution) so
 * the scan module, which is the only member with storage and contradiction
 * imports, initializes last.
 */

export * from "./drift-types.js";
export * from "./drift-config.js";
export * from "./drift-recall.js";
export * from "./preference-drift.js";

/**
 * Direct-answer retrieval tier eligibility (issue #518 slice 2).
 *
 * This module is a pure decision layer.  It takes a query, a set of
 * caller-resolved candidates (each already decorated with trust-zone,
 * taxonomy-bucket, and importance information), and the direct-answer
 * config, then returns an eligibility verdict.
 *
 * Keeping the module pure means:
 *
 * - Tests do not need a trust-zones store, taxonomy resolver, or importance
 *   scorer on disk.
 * - Slice 3 (retrieval.ts wiring) is responsible for resolving those signals
 *   before calling in; the wiring layer decides where candidates come from
 *   (entity index, token prefilter, etc.).  This module only decides
 *   whether the surfaced candidates add up to a confident direct answer.
 *
 * Not wired into retrieval yet — see slice 3.
 */

import {
  isUnsegmentableRecallChar as isUnsegmentableRecallCodepoint,
  normalizeRecallTokenSet,
  normalizeRecallTokens,
} from "./recall-tokenization.js";
import type { TrustZoneName } from "./trust-zones.js";
import type { MemoryFile, MemoryStatus } from "./types.js";

/**
 * Caller-supplied candidate.
 *
 * `trustZone`, `taxonomyBucket`, and `importanceScore` are resolved outside
 * this module because each comes from a different subsystem.  Passing them
 * as inputs keeps the function deterministic and easy to unit-test.
 *
 * `matchScore` is optional; if omitted, candidates are ranked by
 * token-overlap ratio.  Callers that already computed a better ranking
 * score (e.g. BM25, vector similarity) can supply it to drive the
 * ambiguity check.
 */
export interface DirectAnswerCandidate {
  memory: MemoryFile;
  trustZone: TrustZoneName | null;
  taxonomyBucket: string | null;
  importanceScore: number;
  matchScore?: number;
}

export interface DirectAnswerConfig {
  enabled: boolean;
  tokenOverlapFloor: number;
  importanceFloor: number;
  ambiguityMargin: number;
  eligibleTaxonomyBuckets: string[];
}

export interface DirectAnswerInput {
  query: string;
  candidates: DirectAnswerCandidate[];
  config: DirectAnswerConfig;
  /**
   * Optional entity-ref hints resolved from the query upstream.  When
   * supplied, a candidate with a set `entityRef` must match one of these
   * (case-insensitive) to remain eligible.  Candidates without an
   * `entityRef` are allowed through regardless.
   */
  queryEntityRefs?: string[];
}

export type DirectAnswerReason =
  | "disabled"
  | "empty-query"
  | "no-candidates"
  | "no-eligible-candidates"
  | "below-token-overlap-floor"
  | "ambiguous"
  | "eligible";

export interface DirectAnswerResult {
  eligible: boolean;
  reason: DirectAnswerReason;
  /** Winning candidate when eligible. */
  winner?: DirectAnswerCandidate;
  /** Computed token-overlap ratio (0..1) of the winner. */
  tokenOverlap?: number;
  /**
   * Human-readable summary suitable for
   * `RecallTierExplain.tierReason`.
   */
  narrative: string;
  /**
   * Filter labels that eliminated at least one candidate along the way.
   * Populated regardless of eligibility so the caller can surface the
   * narrowing steps in `RecallTierExplain.filteredBy`.
   */
  filteredBy: string[];
}

/** Filter labels — exported so callers and tests can match them structurally. */
export const FILTER_LABELS = {
  nonActiveStatus: "non-active-status",
  notTrustedZone: "not-trusted-zone",
  ineligibleTaxonomyBucket: "ineligible-taxonomy-bucket",
  belowImportanceFloor: "below-importance-floor",
  entityRefMismatch: "entity-ref-mismatch",
  belowTokenOverlapFloor: "below-token-overlap-floor",
} as const;

const PROMPT_RECALL_WORDS = new Set([
  "what",
  "who",
  "where",
  "when",
  "why",
  "how",
  "is",
  "are",
  "was",
  "were",
  "do",
  "does",
  "did",
  "find",
  "get",
  "show",
  "search",
  "lookup",
  "recall",
  "remember",
  "list",
  "status",
  "include",
  "tell",
  "me",
  "give",
  "about",
  "please",
  "the",
  "and",
  "for",
  "with",
  "from",
  "into",
  "that",
  "this",
  "найди",
  "найти",
  "поиск",
  "покажи",
  "статус",
  "включи",
]);

interface ScoredCandidate {
  candidate: DirectAnswerCandidate;
  tokenOverlap: number;
  requiredTokenMismatch: boolean;
}

function hasUnsegmentableRecallChar(token: string): boolean {
  return [...token].some((ch) => isUnsegmentableRecallCodepoint(ch));
}

function requiredCjkPhraseTokens(query: string): string[] {
  const phrases = new Set<string>();
  let segment = "";

  const addPhrase = (phrase: string) => {
    if ([...phrase].length >= 4) {
      phrases.add(phrase);
    }
  };

  const flushSegment = () => {
    let buffered = "";
    for (const run of segment.split(/\s+/)) {
      if (!run) continue;
      if ([...run].length >= 4) {
        addPhrase(buffered);
        buffered = "";
        addPhrase(run);
        continue;
      }
      buffered += run;
    }
    addPhrase(buffered);
    segment = "";
  };

  for (const ch of query.toLowerCase().normalize("NFC")) {
    if (hasUnsegmentableRecallChar(ch)) {
      segment += ch;
      continue;
    }
    if (/\p{M}/u.test(ch) && segment.length > 0 && !/\s$/u.test(segment)) {
      segment += ch;
      continue;
    }
    if (/\s/u.test(ch)) {
      segment += " ";
      continue;
    }
    flushSegment();
  }
  flushSegment();

  return [...phrases];
}

function requiredMixedScriptTokens(query: string): string[] {
  const required = new Set<string>();
  const parts: string[] = [];
  let segment = "";

  const flushSegment = () => {
    if (segment) {
      parts.push(segment);
    }
    segment = "";
  };

  const segmentableRecallTokens = (value: string) => {
    const tokens = new Set<string>();
    let segment = "";
    const flushSegmentableSegment = () => {
      for (const token of normalizeRecallTokenSet(segment, [], { minTokenLength: 1 })) {
        tokens.add(token);
      }
      segment = "";
    };

    for (const ch of value) {
      if (/[\p{L}\p{N}]/u.test(ch) && !hasUnsegmentableRecallChar(ch)) {
        segment += ch;
        continue;
      }
      if (/\p{M}/u.test(ch) && segment.length > 0) {
        segment += ch;
        continue;
      }
      flushSegmentableSegment();
    }
    flushSegmentableSegment();
    return tokens;
  };

  const hasRequiredSegmentableToken = (value: string) => {
    return segmentableRecallTokens(value).size > 0;
  };

  const hasBoundarySegmentableToken = (value: string) => {
    for (const token of segmentableRecallTokens(value)) {
      if (PROMPT_RECALL_WORDS.has(token)) {
        continue;
      }
      const hasNonAsciiCodepoint = [...token].some((ch) => (ch.codePointAt(0) ?? 0) > 0x7f);
      if (token.length >= 3 || /\p{N}/u.test(token) || hasNonAsciiCodepoint) {
        return true;
      }
    }
    return false;
  };

  const addRequiredTokens = (value: string) => {
    for (const token of normalizeRecallTokenSet(value, [], { minTokenLength: 1 })) {
      required.add(token);
    }
  };

  for (const ch of query.toLowerCase().normalize("NFC")) {
    if (/[\p{L}\p{N}\p{M}]/u.test(ch) || hasUnsegmentableRecallChar(ch)) {
      segment += ch;
      continue;
    }
    flushSegment();
  }
  flushSegment();

  for (const part of parts) {
    if (hasUnsegmentableRecallChar(part) && hasRequiredSegmentableToken(part)) {
      addRequiredTokens(part);
    }
  }

  for (let i = 0; i < parts.length - 1; i += 1) {
    const current = parts[i];
    const next = parts[i + 1];
    const currentHasUnsegmentable = hasUnsegmentableRecallChar(current);
    const nextHasUnsegmentable = hasUnsegmentableRecallChar(next);
    if (currentHasUnsegmentable === nextHasUnsegmentable) {
      continue;
    }
    const segmentablePart = currentHasUnsegmentable ? next : current;
    if (!hasBoundarySegmentableToken(segmentablePart)) {
      continue;
    }
    addRequiredTokens(current);
    addRequiredTokens(next);
  }

  for (let i = 1; i < parts.length - 1; i += 1) {
    const prev = parts[i - 1];
    const current = parts[i];
    const next = parts[i + 1];
    if (!hasUnsegmentableRecallChar(prev) || hasUnsegmentableRecallChar(current) || !hasUnsegmentableRecallChar(next)) {
      continue;
    }
    if (!hasRequiredSegmentableToken(current)) {
      continue;
    }
    addRequiredTokens(prev);
    addRequiredTokens(current);
    addRequiredTokens(next);
  }

  return [...required];
}

function requiredSegmentableUnicodeTokens(queryTokens: Set<string>): string[] {
  const segmentableTokens = [...queryTokens].filter((token) => !hasUnsegmentableRecallChar(token));
  const hasSegmentableUnicodeToken = segmentableTokens.some((token) =>
    [...token].some((ch) => (ch.codePointAt(0) ?? 0) > 0x7f)
  );
  if (!hasSegmentableUnicodeToken) {
    return [];
  }
  return segmentableTokens.filter((token) => {
    if (PROMPT_RECALL_WORDS.has(token)) {
      return false;
    }
    const hasNonAsciiCodepoint = [...token].some((ch) => (ch.codePointAt(0) ?? 0) > 0x7f);
    if (hasNonAsciiCodepoint) {
      return true;
    }
    if (!/^[a-z0-9]+$/u.test(token)) {
      return false;
    }
    return token.length >= 3 || /\p{N}/u.test(token);
  });
}

function countTokenOverlap(queryTokens: Set<string>, valueTokens: Set<string>): number {
  let matches = 0;
  for (const token of queryTokens) {
    if (valueTokens.has(token)) matches += 1;
  }
  return matches;
}

/**
 * Determine whether a query can be served by the direct-answer tier.
 *
 * Decision ladder, in order:
 *
 *   1. config.enabled === false → "disabled"
 *   2. empty query tokens → "empty-query"
 *   3. empty candidates → "no-candidates"
 *   4. hard filters drop all candidates → "no-eligible-candidates"
 *   5. token-overlap floor drops all → "below-token-overlap-floor"
 *   6. top two candidates within ambiguityMargin → "ambiguous"
 *   7. otherwise → "eligible"
 */
export function isDirectAnswerEligible(input: DirectAnswerInput): DirectAnswerResult {
  const { query, candidates, config, queryEntityRefs } = input;

  if (!config.enabled) {
    return {
      eligible: false,
      reason: "disabled",
      narrative: "direct-answer tier is disabled",
      filteredBy: [],
    };
  }

  const queryTokens = new Set(normalizeRecallTokens(query));
  if (queryTokens.size === 0) {
    return {
      eligible: false,
      reason: "empty-query",
      narrative: "query has no searchable tokens after normalization",
      filteredBy: [],
    };
  }

  if (candidates.length === 0) {
    return {
      eligible: false,
      reason: "no-candidates",
      narrative: "no candidates supplied",
      filteredBy: [],
    };
  }

  const filteredBy: string[] = [];
  let working: DirectAnswerCandidate[] = candidates;

  working = applyFilter(working, filteredBy, FILTER_LABELS.nonActiveStatus, (c) => {
    const status: MemoryStatus = c.memory.frontmatter.status ?? "active";
    return status === "active";
  });

  working = applyFilter(working, filteredBy, FILTER_LABELS.notTrustedZone, (c) => c.trustZone === "trusted");

  working = applyFilter(
    working,
    filteredBy,
    FILTER_LABELS.ineligibleTaxonomyBucket,
    (c) => c.taxonomyBucket !== null && config.eligibleTaxonomyBuckets.includes(c.taxonomyBucket)
  );

  working = applyFilter(working, filteredBy, FILTER_LABELS.belowImportanceFloor, (c) => {
    if (c.memory.frontmatter.verificationState === "user_confirmed") return true;
    return c.importanceScore >= config.importanceFloor;
  });

  if (queryEntityRefs && queryEntityRefs.length > 0) {
    const normRefs = new Set(queryEntityRefs.map((r) => r.toLowerCase()));
    working = applyFilter(working, filteredBy, FILTER_LABELS.entityRefMismatch, (c) => {
      const ref = c.memory.frontmatter.entityRef;
      if (!ref) return true;
      return normRefs.has(ref.toLowerCase());
    });
  }

  if (working.length === 0) {
    return {
      eligible: false,
      reason: "no-eligible-candidates",
      narrative: "no candidates survived eligibility filters",
      filteredBy,
    };
  }

  const scored: ScoredCandidate[] = working.map((candidate) => {
    const searchable = `${candidate.memory.frontmatter.tags?.join(" ") ?? ""} ${candidate.memory.content}`.trim();
    const searchableTokens = normalizeRecallTokenSet(searchable);
    const requiredSearchableTokens = normalizeRecallTokenSet(searchable, [], { minTokenLength: 1 });
    const requiredPhrases = requiredCjkPhraseTokens(query);
    const requiredMixedTokens = requiredMixedScriptTokens(query);
    const requiredUnicodeTokens = requiredSegmentableUnicodeTokens(queryTokens);
    const hasRequiredPhrase =
      requiredPhrases.length === 0 || requiredPhrases.every((token) => searchableTokens.has(token));
    const hasRequiredMixedTokens =
      requiredMixedTokens.length === 0 || requiredMixedTokens.every((token) => requiredSearchableTokens.has(token));
    const hasRequiredUnicodeTokens =
      requiredUnicodeTokens.length === 0 || requiredUnicodeTokens.every((token) => searchableTokens.has(token));
    const requiredTokenMismatch = !hasRequiredPhrase || !hasRequiredMixedTokens || !hasRequiredUnicodeTokens;
    const matches = requiredTokenMismatch ? 0 : countTokenOverlap(queryTokens, searchableTokens);
    return { candidate, tokenOverlap: matches / queryTokens.size, requiredTokenMismatch };
  });

  const overlapSurvivors = scored.filter((s) => !s.requiredTokenMismatch && s.tokenOverlap >= config.tokenOverlapFloor);
  if (overlapSurvivors.length < scored.length) {
    filteredBy.push(FILTER_LABELS.belowTokenOverlapFloor);
  }

  if (overlapSurvivors.length === 0) {
    return {
      eligible: false,
      reason: "below-token-overlap-floor",
      narrative: `no candidate met token-overlap floor ${config.tokenOverlapFloor}`,
      filteredBy,
    };
  }

  overlapSurvivors.sort(compareScored);

  if (overlapSurvivors.length >= 2) {
    const topScore = scoreFor(overlapSurvivors[0]);
    const secondScore = scoreFor(overlapSurvivors[1]);
    if (topScore - secondScore < config.ambiguityMargin) {
      return {
        eligible: false,
        reason: "ambiguous",
        narrative: `top two candidates within ambiguityMargin ${config.ambiguityMargin}`,
        filteredBy,
      };
    }
  }

  const winner = overlapSurvivors[0];
  const bucket = winner.candidate.taxonomyBucket ?? "unknown";
  return {
    eligible: true,
    reason: "eligible",
    winner: winner.candidate,
    tokenOverlap: winner.tokenOverlap,
    narrative: `trusted ${bucket}, unambiguous, token-overlap ${winner.tokenOverlap.toFixed(2)}`,
    filteredBy,
  };
}

function applyFilter(
  working: DirectAnswerCandidate[],
  filteredBy: string[],
  label: string,
  keep: (c: DirectAnswerCandidate) => boolean
): DirectAnswerCandidate[] {
  const before = working.length;
  const next = working.filter(keep);
  if (next.length < before) filteredBy.push(label);
  return next;
}

function scoreFor(s: ScoredCandidate): number {
  return s.candidate.matchScore ?? s.tokenOverlap;
}

function compareScored(a: ScoredCandidate, b: ScoredCandidate): number {
  const diff = scoreFor(b) - scoreFor(a);
  if (diff !== 0) return diff;
  // Stable secondary key on path so the comparator returns 0 only for equal
  // entries (CLAUDE.md rule 19).
  return a.candidate.memory.path.localeCompare(b.candidate.memory.path);
}

/**
 * Surprise helper — D-MEM-style novelty score for a turn against recent memories.
 *
 * Used (eventually, in a follow-up PR) by the smart buffer as an additive flush
 * trigger: a turn that is semantically far from everything already in memory is
 * "surprising" and worth extracting immediately, even if turn-count and signal
 * heuristics would otherwise keep buffering.
 *
 * This module intentionally contains ONLY the pure scoring function. Wiring
 * into the buffer, configuration flags, telemetry, and benchmark work live in
 * later PRs (see issue #563). Keeping the helper in a sibling file instead of
 * inside `buffer.ts` keeps the buffer module focused and makes the eventual
 * integration a small, reviewable change.
 *
 * # Formula
 *
 * Given an input `turn` and a list of `recentMemories`:
 *
 * 1. Embed the turn and every candidate memory via the caller-provided
 *    `embedFn`.
 * 2. For each candidate, compute cosine similarity `cos(turn, candidate)` in
 *    `[0, 1]` (negative cosines are clamped to 0 — "opposite directions"
 *    is treated as maximally diverse, consistent with `recall-mmr.ts`).
 * 3. Keep the top-`k` *highest* similarities (the turn's nearest neighbors).
 * 4. Average those top-`k` similarities → `nearestSim ∈ [0, 1]`.
 * 5. Return `1 − nearestSim` as the surprise score.
 *
 * Intuition: a turn that is close to at least one recent memory has a high
 * `nearestSim` and therefore a *low* surprise (near 0 = redundant). A turn
 * that is far from all of its k nearest neighbors has a low `nearestSim` and
 * therefore a *high* surprise (near 1 = novel).
 *
 * Using the top-k average instead of a single nearest neighbor makes the
 * score less sensitive to one outlier duplicate (e.g. an exact restatement of
 * a stale fact). `k=1` reduces to pure nearest-neighbor distance.
 *
 * # Edge cases
 *
 * - `recentMemories` empty → returns `1.0` (maximally surprising). There is
 *   nothing to compare against, so the turn cannot be redundant.
 * - `k` default is `5`. It is clamped to `[1, recentMemories.length]` so that
 *   small corpora still produce a meaningful score (e.g. 3 memories with
 *   `k=5` behaves the same as `k=3`).
 * - Zero-norm embeddings (all zeros) contribute similarity `0` (they cannot
 *   be "close" to anything), which is treated as maximally surprising for
 *   that pair. The rest of the corpus is scored normally.
 * - Embedding-length mismatches between the turn and a candidate are treated
 *   as similarity `0` for that pair. We do not silently truncate to the
 *   shorter vector because that would hide a real configuration bug.
 * - `embedFn` rejection is allowed to propagate. The caller decides whether
 *   to catch, fall back, or fail the flush decision — this helper has no
 *   opinion beyond the pure score.
 *
 * # Purity
 *
 * No I/O, no hidden globals. Given the same inputs and the same `embedFn`,
 * the output is deterministic.
 */

import { cosineSimilarity } from "./semantic-chunking.js";

/** Minimal shape of a recent memory passed to `computeSurprise`. */
export interface RecentMemoryLike {
  /** Stable identifier. Only used for debug/logging; not part of the score. */
  readonly id: string;
  /** Text to embed and compare against the incoming turn. */
  readonly content: string;
}

/** Options accepted by `computeSurprise`. */
export interface ComputeSurpriseOptions {
  /**
   * Embedding function. Called once for the turn and once per candidate
   * memory. Callers may wrap a provider client, a local model, or a
   * deterministic hash for tests.
   */
  readonly embedFn: (text: string) => Promise<readonly number[]>;
  /**
   * Number of nearest neighbors to average over. Defaults to 5. Clamped to
   * `[1, recentMemories.length]`.
   */
  readonly k?: number;
}

/** Default k (top nearest neighbors to average). */
export const DEFAULT_SURPRISE_K = 5;

/**
 * Compute a surprise score in `[0, 1]` for `turn` against `recentMemories`.
 *
 * See the module-level docstring for the exact formula, edge cases, and
 * purity guarantees.
 *
 * @param turn           The incoming turn text (caller is responsible for
 *                       stringifying structured turn content — this helper
 *                       only needs the text to embed).
 * @param recentMemories Candidate memories to compare against.
 * @param options        `embedFn` (required) and optional `k` (defaults to 5).
 * @returns A scalar in `[0, 1]`. `1.0` = maximally surprising / novel;
 *          `0.0` = redundant with at least one recent memory.
 */
export async function computeSurprise(
  turn: string,
  recentMemories: readonly RecentMemoryLike[],
  options: ComputeSurpriseOptions,
): Promise<number> {
  if (typeof turn !== "string") {
    throw new TypeError("computeSurprise: `turn` must be a string");
  }
  if (!options || typeof options.embedFn !== "function") {
    throw new TypeError(
      "computeSurprise: `options.embedFn` is required and must be a function",
    );
  }
  const candidates = Array.isArray(recentMemories) ? recentMemories : [];

  // Empty corpus → maximally surprising. Document decision: we prefer
  // "novelty by default" over "silence" because the surprise score is meant
  // to *promote* flushing, and an empty buffer of recent memories is the
  // clearest case of "we have no basis to call this redundant".
  if (candidates.length === 0) return 1;

  const kRaw = typeof options.k === "number" ? options.k : DEFAULT_SURPRISE_K;
  // Clamp k to [1, candidates.length]. Non-integer / non-finite values fall
  // back to the default, then get re-clamped below.
  const kClamped = clampK(kRaw, candidates.length);

  // Embed the turn and every candidate. Rejections propagate — that's the
  // caller's decision to handle. Run candidate embeddings in parallel so a
  // slow embedder does not serialize the whole pass.
  const turnEmbedding = await options.embedFn(turn);
  const candidateEmbeddings = await Promise.all(
    candidates.map((c) => options.embedFn(c.content)),
  );

  const sims: number[] = [];
  for (let i = 0; i < candidates.length; i += 1) {
    const candEmbedding = candidateEmbeddings[i] ?? [];
    sims.push(safeCosine(turnEmbedding, candEmbedding));
  }

  // Sort similarities descending and take the top-k (the nearest neighbors).
  sims.sort((a, b) => b - a);
  const top = sims.slice(0, kClamped);

  if (top.length === 0) {
    // Defensive — with `candidates.length >= 1` and `kClamped >= 1`, we
    // should always have at least one similarity. If we somehow do not,
    // treat as maximally surprising rather than returning NaN.
    return 1;
  }

  let sum = 0;
  for (const s of top) sum += s;
  const nearestSim = sum / top.length;

  const surprise = 1 - nearestSim;
  // Numerical safety: clamp the final value. Cosine is clamped to [0, 1]
  // per-pair already, so the mean cannot escape that range under normal
  // arithmetic, but floating-point drift is cheap to guard against.
  if (!Number.isFinite(surprise)) return 1;
  if (surprise < 0) return 0;
  if (surprise > 1) return 1;
  return surprise;
}

// -----------------------------------------------------------------------------
// Internals
// -----------------------------------------------------------------------------

function clampK(k: number, ceiling: number): number {
  if (!Number.isFinite(k)) {
    return Math.min(DEFAULT_SURPRISE_K, Math.max(1, ceiling));
  }
  const floored = Math.floor(k);
  if (floored < 1) return 1;
  if (floored > ceiling) return ceiling;
  return floored;
}

/**
 * Safe wrapper around `cosineSimilarity` that returns a similarity value in
 * `[0, 1]` (negative cosines are clamped to 0, matching the convention used
 * by `recall-mmr.ts`) and tolerates mismatched or empty vectors without
 * throwing. See `semantic-chunking.ts` for the shared cosine implementation.
 *
 * Returns `0` for:
 * - empty vectors,
 * - length mismatches (callers likely have a config bug, but surprise
 *   scoring is a soft signal — do not crash the buffer flush decision),
 * - non-finite cosine results (zero-norm inputs, arithmetic drift).
 */
function safeCosine(a: readonly number[], b: readonly number[]): number {
  if (!Array.isArray(a) || !Array.isArray(b)) return 0;
  if (a.length === 0 || b.length === 0) return 0;
  if (a.length !== b.length) return 0;
  const raw = cosineSimilarity(a as number[], b as number[]);
  if (!Number.isFinite(raw)) return 0;
  if (raw < 0) return 0;
  if (raw > 1) return 1;
  return raw;
}

/**
 * Buffer-surprise telemetry report (issue #563 PR 3).
 *
 * Reads the append-only `state/buffer-surprise-ledger.jsonl` file written
 * by `SmartBuffer` and summarizes the recent distribution of surprise
 * scores for the Doctor surface. This module is intentionally standalone
 * and pure — the only I/O is reading the ledger via the injected
 * `readEvents` callback, so it can be exercised directly in tests
 * without touching the filesystem.
 *
 * # Output shape
 *
 * `BufferSurpriseDistribution` has fields sized for a one-screen Doctor
 * display:
 *
 *   - `count`            — rows considered in the summary window.
 *   - `triggeredCount`   — rows whose `triggeredFlush === true`.
 *   - `triggeredRate`    — `triggeredCount / count`, or `0` when empty.
 *   - `mean`             — arithmetic mean of `surpriseScore`.
 *   - `median`           — middle value (50th percentile).
 *   - `p90`              — 90th percentile (tail of novelty).
 *   - `min`, `max`       — window extremes.
 *   - `currentThreshold` — threshold from the MOST RECENT row, or `null`.
 *
 * All percentile math uses the nearest-rank method (no interpolation) so
 * the report is stable across small windows.
 *
 * # Why a pure function + injected reader?
 *
 * The Doctor surface is exercised both at runtime (through the CLI and
 * gateway tools) and in tests. A pure distribution helper fed from an
 * arbitrary `readEvents` callback keeps the report logic trivially
 * testable without spinning up a real `StorageManager`.
 */

import type { BufferSurpriseEvent } from "./types.js";

export interface BufferSurpriseDistribution {
  count: number;
  triggeredCount: number;
  triggeredRate: number;
  mean: number;
  median: number;
  p90: number;
  min: number;
  max: number;
  currentThreshold: number | null;
}

export interface BufferSurpriseReportOptions {
  /**
   * Maximum number of recent rows to include. Defaults to `200` — large
   * enough to see a distribution, small enough to read in one sitting.
   */
  limit?: number;
  /** Lower-bound ISO timestamp; rows at or before this are excluded. */
  since?: string;
}

/**
 * Reader callback shape. The helper does not want to know whether the
 * rows come from a file, a queue, or an in-memory buffer.
 */
export type BufferSurpriseReader = (
  options: BufferSurpriseReportOptions,
) => Promise<readonly BufferSurpriseEvent[]>;

/**
 * Summarize the recent buffer-surprise distribution. Returns the empty
 * distribution shape when the ledger has no applicable rows — callers can
 * detect this via `count === 0` and render "no data yet".
 */
export async function reportBufferSurpriseDistribution(
  readEvents: BufferSurpriseReader,
  options: BufferSurpriseReportOptions = {},
): Promise<BufferSurpriseDistribution> {
  const limit = normalizeReportLimit(options.limit);
  const raw = await readEvents({ limit, since: options.since });

  // Filter for sanity: finite numeric scores in [0, 1], event tag match,
  // and the optional `since` lower bound. Malformed rows are skipped.
  const sinceMs =
    typeof options.since === "string" && options.since.length > 0
      ? Date.parse(options.since)
      : Number.NaN;
  const rows = raw.filter((row): row is BufferSurpriseEvent => {
    if (!row || row.event !== "BUFFER_SURPRISE") return false;
    const ts = Date.parse(row.timestamp);
    if (!Number.isFinite(ts)) return false;
    if (typeof row.surpriseScore !== "number") return false;
    if (!Number.isFinite(row.surpriseScore)) return false;
    if (row.surpriseScore < 0 || row.surpriseScore > 1) return false;
    // `triggeredFlush` must be a real boolean — not a string or other
    // truthy value. A row with `triggeredFlush: "false"` (string from a
    // JSON-parsing bug upstream) would otherwise be counted as
    // triggered, inflating the rate and misleading operators tuning the
    // threshold from real traffic.
    if (typeof row.triggeredFlush !== "boolean") return false;
    if (Number.isFinite(sinceMs)) {
      if (!Number.isFinite(ts) || ts <= sinceMs) return false;
    }
    return true;
  }).sort((left, right) => Date.parse(left.timestamp) - Date.parse(right.timestamp));

  const windowStart = Math.max(0, rows.length - limit);
  const windowRows = rows.slice(windowStart);

  if (windowRows.length === 0) {
    return {
      count: 0,
      triggeredCount: 0,
      triggeredRate: 0,
      mean: 0,
      median: 0,
      p90: 0,
      min: 0,
      max: 0,
      currentThreshold: null,
    };
  }

  const scores = windowRows.map((r) => r.surpriseScore).sort((a, b) => a - b);
  const triggeredCount = windowRows.reduce(
    (acc, r) => acc + (r.triggeredFlush ? 1 : 0),
    0,
  );
  const sum = scores.reduce((acc, v) => acc + v, 0);
  const mean = sum / scores.length;

  // Nearest-rank percentiles keep the output stable for small windows.
  const median = percentile(scores, 0.5);
  const p90 = percentile(scores, 0.9);

  // "Current" threshold is whichever was in force for the most recent row
  // — not necessarily the one configured right now, but the value the
  // ledger rows were judged against. That's what operators need to reason
  // about the distribution.
  const mostRecent = windowRows[windowRows.length - 1];
  const currentThreshold =
    mostRecent && typeof mostRecent.threshold === "number"
      ? mostRecent.threshold
      : null;

  return {
    count: scores.length,
    triggeredCount,
    triggeredRate: triggeredCount / scores.length,
    mean,
    median,
    p90,
    min: scores[0]!,
    max: scores[scores.length - 1]!,
    currentThreshold,
  };
}

function normalizeReportLimit(limit: number | undefined): number {
  if (limit === undefined) return 200;
  if (typeof limit !== "number" || !Number.isFinite(limit)) return 200;
  const floored = Math.floor(limit);
  return floored > 0 ? floored : 200;
}

/**
 * Nearest-rank percentile of a pre-sorted ascending array.
 *
 * Returns `sorted[ceil(p * n) - 1]`, with `p` clamped to `[0, 1]`.
 * This avoids the interpolation ambiguity of R-7/R-8 percentiles and is
 * stable when the window is small (e.g. 3-5 rows).
 */
function percentile(sorted: readonly number[], p: number): number {
  if (sorted.length === 0) return 0;
  const clamped = Math.max(0, Math.min(1, p));
  const rank = Math.max(1, Math.ceil(clamped * sorted.length));
  return sorted[rank - 1]!;
}

/**
 * skill-io.ts — filesystem export / import for procedural skill bundles
 * (issue #2369).
 *
 * Export writes `<dir>/<slug>/SKILL.md` and never deletes anything it did not
 * just render. Import walks every `<dir>/<slug>/SKILL.md`, rejects symlinks and any entry that
 * resolves outside the requested root, and persists `pending_review` procedure
 * memories through the sealed-envelope write path.
 *
 * Import is INERT: bundle resources (`scripts/`, binaries, extra files) are
 * never read, copied, or executed. Their presence is recorded as
 * `hasUnimportedResources` so a reviewer can act on it.
 */

import { lstat, mkdir, readdir, readFile, realpath, writeFile } from "node:fs/promises";
import path from "node:path";

import { log } from "../logger.js";
import type { StorageManager } from "../storage.js";
import { pathIsInside } from "../utils/path-containment.js";
import { composeMemoryEnvelope } from "../write-envelope.js";
import { buildProcedurePersistBody } from "./procedure-types.js";
import {
  parseSkillBundle,
  renderSkillBundle,
  sanitizeSkillSlug,
  SKILL_FILE_NAME,
  SKILL_IMPORT_SOURCE,
  type ParsedSkillBundle,
  type SkillBundle,
} from "./skill-projection.js";

export interface ExportSkillsResult {
  outDir: string;
  /** Slugs written this run, in projection order. */
  slugs: string[];
}

/** Write bundles as `<outDir>/<slug>/SKILL.md`. Creates directories as needed. */
export async function exportSkillBundles(options: {
  bundles: readonly SkillBundle[];
  outDir: string;
}): Promise<ExportSkillsResult> {
  const outDir = path.resolve(options.outDir);
  await mkdir(outDir, { recursive: true });
  const slugs: string[] = [];
  for (const bundle of options.bundles) {
    const dir = path.join(outDir, bundle.slug);
    if (!pathIsInside(outDir, dir)) {
      throw new Error(`skill export: refusing to write outside ${outDir} (slug ${bundle.slug})`);
    }
    try {
      const existing = await lstat(dir);
      if (existing.isSymbolicLink()) {
        throw new Error(`skill export: refusing to write through symlink ${dir}`);
      }
    } catch (err) {
      if ((err as NodeJS.ErrnoException).code !== "ENOENT") throw err;
    }
    await mkdir(dir, { recursive: true });
    const skillPath = path.join(dir, SKILL_FILE_NAME);
    try {
      const existingSkill = await lstat(skillPath);
      if (existingSkill.isSymbolicLink()) {
        throw new Error(`skill export: refusing to write through symlink ${skillPath}`);
      }
    } catch (err) {
      if ((err as NodeJS.ErrnoException).code !== "ENOENT") throw err;
    }
    await writeFile(skillPath, renderSkillBundle(bundle), "utf-8");
    slugs.push(bundle.slug);
  }
  return { outDir, slugs };
}

/** One bundle read off disk, plus the resource flag the reviewer needs. */
export interface ReadSkillBundle extends ParsedSkillBundle {
  /** True when the bundle directory holds anything besides SKILL.md. */
  hasUnimportedResources: boolean;
}

export interface ReadSkillBundlesResult {
  bundles: ReadSkillBundle[];
  /** Entries that were not importable, with the reason (never silent). */
  skipped: Array<{ entry: string; reason: string }>;
}

/**
 * Read every `<dir>/*​/SKILL.md` bundle. Symlinked roots, symlinked bundle
 * directories, symlinked SKILL.md files, and anything resolving outside `dir`
 * are skipped with a reason (Review Prevention Checklist §3, §10).
 */
export async function readSkillBundlesFromDir(dir: string): Promise<ReadSkillBundlesResult> {
  const root = path.resolve(dir);
  const rootStat = await lstat(root);
  if (rootStat.isSymbolicLink()) {
    throw new Error(`skill import: refusing to walk symlinked directory ${root}`);
  }
  if (!rootStat.isDirectory()) {
    throw new Error(`skill import: ${root} is not a directory`);
  }
  const rootReal = await realpath(root);

  const bundles: ReadSkillBundle[] = [];
  const skipped: Array<{ entry: string; reason: string }> = [];
  const entries = await readdir(root, { withFileTypes: true });
  // Stable order — readdir order is not guaranteed (§6).
  entries.sort((a, b) => (a.name < b.name ? -1 : a.name > b.name ? 1 : 0));

  for (const entry of entries) {
    try {
      if (entry.isSymbolicLink()) {
        skipped.push({ entry: entry.name, reason: "symlink" });
        continue;
      }
      if (!entry.isDirectory()) continue;
      const bundleDir = path.join(root, entry.name);
      const bundleReal = await realpath(bundleDir);
      if (!pathIsInside(rootReal, bundleReal)) {
        skipped.push({ entry: entry.name, reason: "resolves outside the import root" });
        continue;
      }
      const skillPath = path.join(bundleDir, SKILL_FILE_NAME);
      let skillStat;
      try {
        skillStat = await lstat(skillPath);
      } catch {
        skipped.push({ entry: entry.name, reason: `no ${SKILL_FILE_NAME}` });
        continue;
      }
      if (skillStat.isSymbolicLink() || !skillStat.isFile()) {
        skipped.push({ entry: entry.name, reason: `${SKILL_FILE_NAME} is not a regular file` });
        continue;
      }
      const parsed = parseSkillBundle(await readFile(skillPath, "utf-8"), sanitizeSkillSlug(entry.name));
      if (!parsed) {
        skipped.push({ entry: entry.name, reason: "empty body" });
        continue;
      }
      const siblings = await readdir(bundleDir);
      bundles.push({
        ...parsed,
        hasUnimportedResources: siblings.some((name) => name !== SKILL_FILE_NAME),
      });
    } catch (err) {
      skipped.push({
        entry: entry.name,
        reason: `unreadable: ${err instanceof Error ? err.message : String(err)}`,
      });
    }
  }

  return { bundles, skipped };
}

export interface ImportedSkillRecord {
  slug: string;
  memoryId: string;
  steps: number;
  hasUnimportedResources: boolean;
}

export interface ImportSkillsResult {
  imported: ImportedSkillRecord[];
  /** Bundles that were read but not persisted (e.g. tombstone-blocked). */
  rejected: Array<{ slug: string; reason: string }>;
}

/**
 * Persist read bundles as `pending_review` procedure memories.
 *
 * `pending_review` is unconditional: imported procedures never auto-promote,
 * regardless of `procedural.autoPromoteOccurrences`. Recall already excludes
 * non-active procedures, so review is the promotion checkpoint.
 */
export async function persistImportedSkills(options: {
  storage: StorageManager;
  bundles: readonly ReadSkillBundle[];
}): Promise<ImportSkillsResult> {
  const imported: ImportedSkillRecord[] = [];
  const rejected: Array<{ slug: string; reason: string }> = [];

  for (const bundle of options.bundles) {
    const title = (bundle.description ?? bundle.name ?? bundle.slug).trim() || bundle.slug;
    const content = bundle.steps ? buildProcedurePersistBody(title, bundle.steps) : bundle.body;
    const envelope = composeMemoryEnvelope(
      {
        content,
        category: "procedure",
        tags: ["skill-import", "procedure"],
        structuredAttributes: {
          skill_slug: bundle.slug,
          // Basename only — never an operator's absolute path.
          skill_source: `${bundle.slug}/${SKILL_FILE_NAME}`,
          ...(bundle.provenance.memoryId ? { skill_origin_memory_id: bundle.provenance.memoryId } : {}),
          ...(bundle.hasUnimportedResources ? { hasUnimportedResources: "true" } : {}),
        },
      },
      { source: SKILL_IMPORT_SOURCE },
      // Machine-generated / externally authored input — salvage, warn on drops.
      { salvage: true },
    );
    if (envelope.salvageNotes.length > 0) {
      log.warn(`skill-import write salvaged invalid fields: ${envelope.salvageNotes.join("; ")}`);
    }
    const written = await options.storage.writeSealedMemory(envelope, { status: "pending_review" });
    if (written.tombstoneBlocked) {
      rejected.push({ slug: bundle.slug, reason: "blocked by a tombstone; left for review" });
      continue;
    }
    imported.push({
      slug: bundle.slug,
      memoryId: written.id,
      steps: bundle.steps?.length ?? 0,
      hasUnimportedResources: bundle.hasUnimportedResources,
    });
  }

  return { imported, rejected };
}

export type LcmMessagePartKind =
  | "text"
  | "tool_call"
  | "tool_result"
  | "patch"
  | "file_read"
  | "file_write"
  | "step_start"
  | "step_finish"
  | "snapshot"
  | "retry";

export const LCM_MESSAGE_PART_KINDS: readonly LcmMessagePartKind[] = [
  "text",
  "tool_call",
  "tool_result",
  "patch",
  "file_read",
  "file_write",
  "step_start",
  "step_finish",
  "snapshot",
  "retry",
] as const;

export type MessagePartSourceFormat =
  | "openai"
  | "anthropic"
  | "openclaw"
  | "pi"
  | "lossless-claw"
  | "remnic";

export interface LcmMessagePartInput {
  ordinal?: number | null;
  kind: LcmMessagePartKind;
  payload: Record<string, unknown>;
  toolName?: string | null;
  tool_name?: string | null;
  filePath?: string | null;
  file_path?: string | null;
  createdAt?: string | null;
  created_at?: string | null;
}

export interface LcmMessagePartRow extends LcmMessagePartInput {
  id: number;
  messageId: number;
  ordinal: number;
  payloadJson: string;
  createdAt: string;
}

export interface ParseMessagePartsOptions {
  sourceFormat?: MessagePartSourceFormat;
  renderedContent?: string;
  allowRenderedFallback?: boolean;
}

const SECRET_KEY_RE = /(api[_-]?key|authorization|bearer|credential|password|secret|token)/i;
const MAX_PAYLOAD_STRING = 8_000;
const MAX_FILE_SCAN_CHARS = 20_000;

export function isLcmMessagePartKind(value: unknown): value is LcmMessagePartKind {
  return (
    typeof value === "string" &&
    (LCM_MESSAGE_PART_KINDS as readonly string[]).includes(value)
  );
}

export function parseMessageParts(
  input: unknown,
  options: ParseMessagePartsOptions = {},
): LcmMessagePartInput[] {
  const explicit = normalizeExplicitParts(input);
  if (explicit.length > 0) return explicit;

  const format = options.sourceFormat ?? inferSourceFormat(input);
  switch (format) {
    case "openai":
      return withRenderedFallback(parseOpenAiMessageParts(input, options), options);
    case "anthropic":
      return withRenderedFallback(parseAnthropicMessageParts(input, options), options);
    case "openclaw":
      return withRenderedFallback(parseOpenClawMessageParts(input, options), options);
    case "pi":
      return withRenderedFallback(parsePiMessageParts(input, options), options);
    case "lossless-claw":
    case "remnic":
      return withRenderedFallback(normalizeExplicitParts(input), options);
    default:
      return renderedFallbackParts(options);
  }
}

export function normalizeExplicitParts(input: unknown): LcmMessagePartInput[] {
  const rawParts = pickArray(input, "parts") ?? pickArray(input, "message_parts");
  if (!rawParts) return [];

  const parts: LcmMessagePartInput[] = [];
  rawParts.forEach((raw, index) => {
    if (!raw || typeof raw !== "object" || Array.isArray(raw)) return;
    const obj = raw as Record<string, unknown>;
    const kind = normalizeKind(obj.kind ?? obj.type);
    if (!kind) return;

    const payload =
      obj.payload && typeof obj.payload === "object" && !Array.isArray(obj.payload)
        ? (obj.payload as Record<string, unknown>)
        : { value: sanitizePayload(obj) };
    const toolName = asNonEmptyString(obj.toolName ?? obj.tool_name ?? obj.name);
    const filePath = asNonEmptyString(obj.filePath ?? obj.file_path ?? obj.path);
    const ordinal =
      typeof obj.ordinal === "number" && Number.isInteger(obj.ordinal)
        ? Math.max(0, obj.ordinal)
        : index;

    parts.push({
      ordinal,
      kind,
      payload: sanitizePayload(payload) as Record<string, unknown>,
      toolName,
      filePath,
      createdAt: asNonEmptyString(obj.createdAt ?? obj.created_at),
    });
  });
  return parts;
}

export function parseOpenAiMessageParts(
  input: unknown,
  _options: ParseMessagePartsOptions = {},
): LcmMessagePartInput[] {
  const items = gatherOpenAiItems(input);
  const parts: LcmMessagePartInput[] = [];
  for (const item of items) {
    const type = asNonEmptyString(item.type) ?? asNonEmptyString(item.kind);
    if (!type) continue;
    if (isOpenAiContentBlock(item)) {
      const text = asNonEmptyString(item.text ?? item.content);
      if (text) parts.push(makePart("text", { type, text }, { filePath: firstFilePath(text) }));
      continue;
    }
    if (type === "message") {
      for (const block of gatherContentBlocks(item.content)) {
        if (isOpenAiResponseItem(block)) {
          parts.push(
            ...parseOpenAiMessageParts([block]).map(({ ordinal: _ordinal, ...part }) => part),
          );
          continue;
        }
        const text = asNonEmptyString(block.text ?? block.content);
        if (text) parts.push(makePart("text", { type, text }, { filePath: firstFilePath(text) }));
      }
      continue;
    }
    if (type === "function_call") {
      const toolName = asNonEmptyString(item.name ?? item.tool_name);
      const callId = asNonEmptyString(item.call_id ?? item.callId);
      const itemId = asNonEmptyString(item.id);
      const payload = {
        id: callId ?? itemId,
        ...(callId ? { call_id: callId } : {}),
        ...(itemId && itemId !== callId ? { response_item_id: itemId } : {}),
        name: toolName,
        arguments: parseMaybeJson(item.arguments),
      };
      parts.push(classifyToolPart(toolName, payload));
      continue;
    }
    if (type === "function_call_output") {
      const output = asNonEmptyString(item.output) ?? JSON.stringify(sanitizePayload(item.output ?? item));
      const callId = asNonEmptyString(item.call_id ?? item.callId);
      const itemId = asNonEmptyString(item.id);
      parts.push(makePart("tool_result", {
        id: callId ?? itemId,
        ...(callId ? { call_id: callId } : {}),
        ...(itemId && itemId !== callId ? { response_item_id: itemId } : {}),
        output,
      }, {
        filePath: firstFilePath(output),
      }));
      continue;
    }
    if (type === "reasoning") {
      parts.push(makePart("step_start", { type, summary: sanitizePayload(item.summary ?? item) }));
      continue;
    }
    if (type === "retry") {
      parts.push(makePart("retry", { type, item: sanitizePayload(item) }));
    }
  }
  return withOrdinals(parts);
}

export function parseAnthropicMessageParts(
  input: unknown,
  _options: ParseMessagePartsOptions = {},
): LcmMessagePartInput[] {
  const blocks = gatherContentBlocks(
    Array.isArray(input) ? input : input && typeof input === "object" ? (input as Record<string, unknown>).content : input,
  );
  const parts: LcmMessagePartInput[] = [];
  for (const block of blocks) {
    const type = asNonEmptyString(block.type ?? block.kind);
    if (type === "text") {
      const text = asNonEmptyString(block.text);
      if (text) parts.push(makePart("text", { type, text }, { filePath: firstFilePath(text) }));
      continue;
    }
    if (type === "tool_use") {
      const toolName = asNonEmptyString(block.name);
      parts.push(classifyToolPart(toolName, {
        id: block.id,
        name: toolName,
        input: sanitizePayload(block.input),
      }));
      continue;
    }
    if (type === "tool_result") {
      const content = block.content;
      const rendered = renderUnknownContent(content);
      parts.push(makePart("tool_result", {
        id: block.tool_use_id,
        content: sanitizePayload(content),
        ...(typeof block.is_error === "boolean" ? { is_error: block.is_error } : {}),
        ...(typeof block.isError === "boolean" ? { isError: block.isError } : {}),
      }, {
        filePath: firstFilePath(rendered),
      }));
      continue;
    }
    if (type === "thinking") {
      parts.push(makePart("step_start", {
        type,
        thinking: truncateString(asNonEmptyString(block.thinking) ?? ""),
        signature: asNonEmptyString(block.signature),
      }));
      continue;
    }
    if (type === "redacted_thinking") {
      parts.push(makePart("step_finish", { type }));
    }
  }
  return withOrdinals(parts);
}

export function parseOpenClawMessageParts(
  input: unknown,
  options: ParseMessagePartsOptions = {},
): LcmMessagePartInput[] {
  const explicit = normalizeExplicitParts(input);
  if (explicit.length > 0) return explicit;
  if (Array.isArray(input)) return parseOpenClawContentArray(input, options);
  if (!input || typeof input !== "object") return [];
  const obj = input as Record<string, unknown>;

  const content = obj.content;
  if (Array.isArray(content)) {
    const mixedParts = parseOpenClawContentArray(content, options);
    if (mixedParts.length > 0) return mixedParts;
    const hasAnthropicBlocks = content.some(isAnthropicContentBlock);
    if (hasAnthropicBlocks) return parseAnthropicMessageParts({ content }, options);
    const piParts = parsePiMessageParts(input, { ...options, allowRenderedFallback: false });
    if (piParts.length > 0) return piParts;
  }

  const toolName = asNonEmptyString(obj.toolName ?? obj.tool_name ?? obj.name);
  if (toolName) {
    return withOrdinals([
      classifyToolPart(toolName, {
        name: toolName,
        input: sanitizePayload(obj.input ?? obj.arguments ?? obj.params),
        output: sanitizePayload(obj.output ?? obj.result),
      }),
    ]);
  }

  const rendered = options.allowRenderedFallback === false
    ? null
    : options.renderedContent ?? asNonEmptyString(obj.content);
  return rendered ? withOrdinals(partsFromRenderedText(rendered)) : [];
}

export function parsePiMessageParts(
  input: unknown,
  options: ParseMessagePartsOptions = {},
): LcmMessagePartInput[] {
  const explicit = normalizeExplicitParts(input);
  if (explicit.length > 0) return explicit;
  const inputRecord = isRecord(input) ? input : null;
  if (!inputRecord && !Array.isArray(input)) return renderedFallbackParts(options);

  if (inputRecord?.role === "bashExecution") {
    const command = asNonEmptyString(inputRecord.command);
    const output = asNonEmptyString(inputRecord.output);
    const rendered = [command ? `Ran ${command}` : null, output].filter(Boolean).join("\n");
    return withOrdinals([
      makePart("tool_result", {
        role: "bashExecution",
        command,
        output,
        exitCode: inputRecord.exitCode ?? inputRecord.exit_code,
      }, {
        toolName: "bashExecution",
        filePath: firstFilePathFromObject(inputRecord) ?? firstFilePath(rendered),
      }),
    ]);
  }

  const topLevelType = inputRecord
    ? asNonEmptyString(inputRecord.type ?? inputRecord.kind ?? inputRecord.role)
    : null;
  if (topLevelType === "toolResult" || topLevelType === "tool_result") {
    const toolName = asNonEmptyString(inputRecord?.name ?? inputRecord?.toolName ?? inputRecord?.tool_name);
    const output = inputRecord?.output ?? inputRecord?.result ?? inputRecord?.content;
    const rendered = renderUnknownContent(output ?? inputRecord);
    return withOrdinals([
      makePart("tool_result", {
        id: inputRecord?.id ?? inputRecord?.toolCallId ?? inputRecord?.tool_call_id,
        name: toolName,
        output: sanitizePayload(output),
        ...(typeof inputRecord?.isError === "boolean" ? { isError: inputRecord.isError } : {}),
        ...(typeof inputRecord?.is_error === "boolean" ? { is_error: inputRecord.is_error } : {}),
      }, {
        toolName,
        filePath: firstFilePathFromObject(inputRecord) ?? firstFilePath(rendered),
      }),
    ]);
  }

  const content = inputRecord?.content;
  const blocks = Array.isArray(input)
    ? input.filter(isRecord)
    : Array.isArray(content)
      ? content.filter(isRecord)
      : [];
  const parts: LcmMessagePartInput[] = [];

  if (typeof content === "string") {
    parts.push(makePart("text", { text: content }, { filePath: firstFilePath(content) }));
  }

  blocks.forEach((block, ordinal) => {
    const type = asNonEmptyString(block.type ?? block.kind);
    if (type === "text") {
      const text = asNonEmptyString(block.text ?? block.content);
      if (text) parts.push({ ...makePart("text", { type, text }, { filePath: firstFilePath(text) }), ordinal });
      return;
    }
    if (type === "toolCall" || type === "tool_call") {
      const toolName = asNonEmptyString(block.name ?? block.toolName ?? block.tool_name);
      const payload = {
        id: block.id,
        name: toolName,
        arguments: sanitizePayload(block.arguments ?? block.args ?? block.input ?? block.params),
      };
      parts.push({ ...classifyToolPart(toolName, payload), ordinal });
      return;
    }
    if (type === "toolResult" || type === "tool_result") {
      const rendered = renderUnknownContent(block.output ?? block.result ?? block.content ?? block);
      parts.push({
        ...makePart("tool_result", {
          id: block.id ?? block.toolCallId ?? block.tool_call_id,
          name: asNonEmptyString(block.name ?? block.toolName ?? block.tool_name),
          output: sanitizePayload(block.output ?? block.result ?? block.content),
          ...(typeof block.isError === "boolean" ? { isError: block.isError } : {}),
          ...(typeof block.is_error === "boolean" ? { is_error: block.is_error } : {}),
        }, {
          toolName: asNonEmptyString(block.name ?? block.toolName ?? block.tool_name),
          filePath: firstFilePathFromObject(block) ?? firstFilePath(rendered),
        }),
        ordinal,
      });
    }
  });

  const toolName = asNonEmptyString(inputRecord?.toolName ?? inputRecord?.tool_name ?? inputRecord?.name);
  if (parts.length === 0 && toolName) {
    parts.push(classifyToolPart(toolName, {
      name: toolName,
      arguments: sanitizePayload(inputRecord?.arguments ?? inputRecord?.args ?? inputRecord?.input ?? inputRecord?.params),
      output: sanitizePayload(inputRecord?.output ?? inputRecord?.result),
    }));
  }

  return withRenderedFallback(withOrdinals(parts), options);
}

export function partsFromRenderedText(text: string): LcmMessagePartInput[] {
  if (text.includes("*** Begin Patch")) {
    const paths = extractFilePaths(text);
    const patchPaths = extractPatchPaths(text);
    return withOrdinals((patchPaths.length > 0 ? patchPaths : paths).map((filePath) =>
      makePart("patch", { text: truncateString(text) }, { filePath })
    ));
  }
  const paths = extractFilePaths(text);
  if (paths.length === 0) return [];
  return withOrdinals(paths.map((filePath) =>
    makePart("file_read", { text: truncateString(text) }, { filePath })
  ));
}

function inferSourceFormat(input: unknown): MessagePartSourceFormat | undefined {
  if (input && typeof input === "object") {
    const obj = input as Record<string, unknown>;
    const explicit = asNonEmptyString(obj.sourceFormat ?? obj.source_format);
    if (explicit === "openai" || explicit === "anthropic" || explicit === "openclaw" || explicit === "pi" || explicit === "lossless-claw" || explicit === "remnic") {
      return explicit;
    }
    if (Array.isArray(obj.output)) return "openai";
    if (isOpenAiResponseItem(obj)) return "openai";
    if (Array.isArray(obj.content)) {
      const hasOpenAiBlocks = obj.content.some(isOpenAiContentBlock);
      const hasAnthropicBlocks = obj.content.some(isAnthropicContentBlock);
      const hasPiToolBlocks = obj.content.some(isPiToolContentBlock);
      if (hasOpenAiBlocks && (hasAnthropicBlocks || hasPiToolBlocks)) {
        return "openclaw";
      }
      if (hasOpenAiBlocks) return "openai";
    }
    if (isAnthropicMessageObject(obj)) return "anthropic";
    if (isPiMessageObject(obj)) return "pi";
    if (Array.isArray(obj.content)) return "anthropic";
  }
  if (Array.isArray(input)) {
    const records = input.filter(isRecord);
    const hasOpenAiBlocks = records.some((item) =>
      isRecord(item) && (isOpenAiResponseItem(item) || isOpenAiContentBlock(item))
    );
    const hasAnthropicBlocks = records.some(isAnthropicContentBlock);
    const hasPiToolBlocks = records.some(isPiToolContentBlock);
    if (hasOpenAiBlocks && (hasAnthropicBlocks || hasPiToolBlocks)) return "openclaw";
    if (hasOpenAiBlocks) return "openai";
    if (hasAnthropicBlocks) return "anthropic";
    if (hasPiToolBlocks) return "pi";
    return "anthropic";
  }
  return undefined;
}

function isPiMessageObject(obj: Record<string, unknown>): boolean {
  if (obj.role === "bashExecution") return true;
  if (obj.role === "toolResult" || obj.role === "tool_result") return true;
  const type = asNonEmptyString(obj.type ?? obj.kind);
  if (type === "toolCall" || type === "tool_call" || type === "toolResult" || type === "tool_result") return true;
  if (!Array.isArray(obj.content)) return false;
  return obj.content.some(isPiToolContentBlock);
}

function parseOpenClawContentArray(
  content: unknown[],
  options: ParseMessagePartsOptions,
): LcmMessagePartInput[] {
  const parts: LcmMessagePartInput[] = [];
  for (const block of content) {
    if (!isRecord(block)) continue;
    const blockParts = isOpenAiContentBlock(block) || isOpenAiResponseItem(block)
      ? parseOpenAiMessageParts([block], options)
      : isAnthropicContentBlock(block)
        ? parseAnthropicMessageParts({ content: [block] }, options)
        : isPiOpenClawContentBlock(block)
          ? parsePiMessageParts({ content: [block] }, { ...options, allowRenderedFallback: false })
          : [];
    parts.push(...blockParts.map(({ ordinal: _ordinal, ...part }) => part));
  }
  return withRenderedFallback(withOrdinals(parts), { ...options, allowRenderedFallback: false });
}

function isPiOpenClawContentBlock(value: unknown): boolean {
  if (!isRecord(value)) return false;
  const blockType = asNonEmptyString(value.type ?? value.kind);
  return blockType === "text" || isPiToolBlockType(blockType);
}

function isPiToolContentBlock(value: unknown): boolean {
  if (!isRecord(value)) return false;
  const blockType = asNonEmptyString(value.type ?? value.kind);
  return isPiToolBlockType(blockType);
}

function isPiToolBlockType(blockType: string | null): boolean {
  return blockType === "toolCall" || blockType === "tool_call" || blockType === "toolResult" || blockType === "tool_result";
}

function isAnthropicMessageObject(obj: Record<string, unknown>): boolean {
  if (isAnthropicContentBlock(obj)) return true;
  if (!Array.isArray(obj.content)) return false;
  return obj.content.some(isAnthropicContentBlock);
}

function isAnthropicContentBlock(value: unknown): boolean {
  if (!isRecord(value)) return false;
  const type = asNonEmptyString(value.type ?? value.kind);
  if (type === "tool_use" || type === "thinking" || type === "redacted_thinking") return true;
  return type === "tool_result" && value.tool_use_id !== undefined;
}

function isOpenAiResponseItem(obj: Record<string, unknown>): boolean {
  const type = asNonEmptyString(obj.type ?? obj.kind);
  return (
    type === "message" ||
    type === "function_call" ||
    type === "function_call_output" ||
    type === "reasoning" ||
    type === "retry"
  );
}

function isOpenAiContentBlock(value: unknown): boolean {
  if (!isRecord(value)) return false;
  const type = asNonEmptyString(value.type);
  return (
    type === "input_text" ||
    type === "output_text" ||
    type === "input_image" ||
    type === "input_file" ||
    type === "refusal"
  );
}

function gatherOpenAiItems(input: unknown): Record<string, unknown>[] {
  if (Array.isArray(input)) return input.filter(isRecord);
  if (!isRecord(input)) return [];
  if (Array.isArray(input.output)) return input.output.filter(isRecord);
  if (Array.isArray(input.items)) return input.items.filter(isRecord);
  if (!isOpenAiResponseItem(input) && Array.isArray(input.content) && input.content.some(isOpenAiContentBlock)) {
    return input.content.filter(isRecord);
  }
  return [input];
}

function gatherContentBlocks(input: unknown): Record<string, unknown>[] {
  if (Array.isArray(input)) return input.filter(isRecord);
  if (typeof input === "string") return [{ type: "text", text: input }];
  if (isRecord(input)) return [input];
  return [];
}

function classifyToolPart(
  toolName: string | null | undefined,
  payload: Record<string, unknown>,
): LcmMessagePartInput {
  const normalized = (toolName ?? "").toLowerCase();
  const rendered = renderUnknownContent(payload);
  const filePath =
    firstFilePathFromObject(payload) ?? firstFilePath(rendered) ?? null;

  if (normalized.includes("apply_patch") || rendered.includes("*** Begin Patch")) {
    return makePart("patch", payload, { toolName, filePath: filePath ?? extractPatchPaths(rendered)[0] ?? null });
  }
  if (/(write|edit|multiedit|create|save)/i.test(normalized)) {
    return makePart("file_write", payload, { toolName, filePath });
  }
  if (/(read|grep|glob|search|list|ls)/i.test(normalized)) {
    return makePart("file_read", payload, { toolName, filePath });
  }
  return makePart("tool_call", payload, { toolName, filePath });
}

function makePart(
  kind: LcmMessagePartKind,
  payload: Record<string, unknown>,
  options: { toolName?: string | null; filePath?: string | null } = {},
): LcmMessagePartInput {
  return {
    kind,
    payload: sanitizePayload(payload) as Record<string, unknown>,
    toolName: options.toolName ?? null,
    filePath: options.filePath ?? null,
  };
}

function withOrdinals(parts: LcmMessagePartInput[]): LcmMessagePartInput[] {
  return parts.map((part, ordinal) => ({ ...part, ordinal: part.ordinal ?? ordinal }));
}

function withRenderedFallback(
  parts: LcmMessagePartInput[],
  options: ParseMessagePartsOptions,
): LcmMessagePartInput[] {
  return parts.length > 0 ? parts : renderedFallbackParts(options);
}

function renderedFallbackParts(options: ParseMessagePartsOptions): LcmMessagePartInput[] {
  if (options.allowRenderedFallback === false) {
    return [];
  }
  const rendered = asNonEmptyString(options.renderedContent);
  return rendered ? partsFromRenderedText(rendered) : [];
}

function normalizeKind(value: unknown): LcmMessagePartKind | null {
  if (isLcmMessagePartKind(value)) return value;
  if (value === "tool_use" || value === "function_call") return "tool_call";
  if (value === "function_call_output") return "tool_result";
  if (value === "thinking" || value === "reasoning") return "step_start";
  return null;
}

function pickArray(input: unknown, key: string): unknown[] | null {
  if (!input || typeof input !== "object" || Array.isArray(input)) return null;
  const value = (input as Record<string, unknown>)[key];
  return Array.isArray(value) ? value : null;
}

function asNonEmptyString(value: unknown): string | null {
  if (typeof value !== "string") return null;
  const trimmed = value.trim();
  return trimmed.length > 0 ? trimmed : null;
}

function isRecord(value: unknown): value is Record<string, unknown> {
  return !!value && typeof value === "object" && !Array.isArray(value);
}

function parseMaybeJson(value: unknown): unknown {
  if (typeof value !== "string") return sanitizePayload(value);
  try {
    return sanitizePayload(JSON.parse(value));
  } catch {
    return truncateString(value);
  }
}

function sanitizePayload(value: unknown, depth = 0): unknown {
  if (value === null || value === undefined) return value;
  if (typeof value === "string") return truncateString(value);
  if (typeof value === "number" || typeof value === "boolean") return value;
  if (Array.isArray(value)) {
    if (depth >= 4) return "[truncated]";
    return value.slice(0, 100).map((item) => sanitizePayload(item, depth + 1));
  }
  if (typeof value === "object") {
    if (depth >= 4) return "[truncated]";
    const out: Record<string, unknown> = {};
    for (const [key, child] of Object.entries(value as Record<string, unknown>)) {
      out[key] = SECRET_KEY_RE.test(key) ? "[redacted]" : sanitizePayload(child, depth + 1);
    }
    return out;
  }
  return String(value);
}

function truncateString(value: string): string {
  return value.length > MAX_PAYLOAD_STRING
    ? `${value.slice(0, MAX_PAYLOAD_STRING)}...[truncated]`
    : value;
}

function renderUnknownContent(value: unknown): string {
  if (typeof value === "string") return value;
  try {
    return JSON.stringify(value ?? "");
  } catch {
    return String(value ?? "");
  }
}

function firstFilePathFromObject(value: unknown): string | null {
  if (!isRecord(value)) return null;
  const keys = ["file_path", "filePath", "path", "filename"];
  for (const key of keys) {
    const candidate = asNonEmptyString(value[key]);
    if (candidate) return candidate;
  }
  for (const child of Object.values(value)) {
    if (typeof child === "string") {
      const fromText = extractPatchPaths(child)[0] ?? firstFilePath(child);
      if (fromText) return fromText;
    }
    if (isRecord(child)) {
      const nested = firstFilePathFromObject(child);
      if (nested) return nested;
    }
  }
  return null;
}

function firstFilePath(text: string): string | null {
  return extractFilePaths(text)[0] ?? null;
}

function extractFilePaths(text: string): string[] {
  const out = new Set<string>();
  let token = "";
  const scanLength = Math.min(text.length, MAX_FILE_SCAN_CHARS);
  for (let index = 0; index <= scanLength; index += 1) {
    const char = index < scanLength ? text[index]! : " ";
    if (isFilePathTokenSeparator(char)) {
      addFilePathCandidate(out, token);
      token = "";
      continue;
    }
    token += char;
    if (token.length > 512) {
      addFilePathCandidate(out, token);
      token = "";
    }
  }
  return [...out].slice(0, 20);
}

function isFilePathTokenSeparator(char: string): boolean {
  return (
    char === " " ||
    char === "\n" ||
    char === "\r" ||
    char === "\t" ||
    char === "\"" ||
    char === "'" ||
    char === "`" ||
    char === "(" ||
    char === ")" ||
    char === "[" ||
    char === "]" ||
    char === "{" ||
    char === "}" ||
    char === "<" ||
    char === ">" ||
    char === ","
  );
}

function addFilePathCandidate(out: Set<string>, raw: string): void {
  const candidate = trimFilePathPunctuation(raw);
  if (candidate.length === 0 || candidate.includes("://")) return;
  if (isLikelyFilePath(candidate)) out.add(candidate);
}

function trimFilePathPunctuation(raw: string): string {
  let start = 0;
  let end = raw.length;
  while (start < end && isLeadingFilePathPunctuation(raw[start]!)) start += 1;
  while (end > start && isTrailingFilePathPunctuation(raw[end - 1]!)) end -= 1;
  return raw.slice(start, end);
}

function isLeadingFilePathPunctuation(char: string): boolean {
  return (
    char === ":" ||
    char === ";" ||
    char === "!" ||
    char === "?" ||
    char === "|" ||
    char === "*" ||
    char === "="
  );
}

function isTrailingFilePathPunctuation(char: string): boolean {
  return (
    char === "." ||
    char === ":" ||
    char === ";" ||
    char === "!" ||
    char === "?" ||
    char === "|" ||
    char === "*" ||
    char === "="
  );
}

function isLikelyFilePath(value: string): boolean {
  if (value.startsWith("/") || value.startsWith("./") || value.startsWith("../") || value.startsWith("~/")) {
    return hasValidFileExtension(value);
  }
  if (value.includes("/")) return hasValidFileExtension(value);
  return hasValidFileExtension(value);
}

function hasValidFileExtension(value: string): boolean {
  const lastSlash = value.lastIndexOf("/");
  const basename = value.slice(lastSlash + 1);
  if (isKnownExtensionlessRepositoryFile(basename)) return true;
  if (isKnownBareDotfile(basename)) return true;
  if (isBasenameDotfile(basename)) return isPathLikeFilePath(value);
  const dot = basename.lastIndexOf(".");
  if (dot <= 0 || dot === basename.length - 1) return false;
  const ext = basename.slice(dot + 1);
  if (ext.length < 1 || ext.length > 12) return false;
  for (const char of ext) {
    if (!isFileExtensionChar(char)) return false;
  }
  return true;
}

function isKnownExtensionlessRepositoryFile(basename: string): boolean {
  return /^(Dockerfile|Containerfile|Makefile|GNUmakefile|LICENSE|NOTICE|README|CHANGELOG|Procfile)$/.test(basename);
}

function isKnownBareDotfile(basename: string): boolean {
  return /^(\.env|\.gitignore|\.gitattributes|\.npmrc|\.yarnrc|\.editorconfig|\.prettierrc|\.eslintrc)$/.test(basename);
}

function isPathLikeFilePath(value: string): boolean {
  return value.startsWith("/") || value.startsWith("./") || value.startsWith("../") || value.startsWith("~/") || value.includes("/");
}

function isBasenameDotfile(basename: string): boolean {
  return /^\.[A-Za-z0-9][A-Za-z0-9._+-]*$/.test(basename);
}

function isFileExtensionChar(char: string): boolean {
  const code = char.charCodeAt(0);
  return (
    (code >= 48 && code <= 57) ||
    (code >= 65 && code <= 90) ||
    (code >= 97 && code <= 122) ||
    char === "_" ||
    char === "+" ||
    char === "-"
  );
}

function extractPatchPaths(text: string): string[] {
  const out = new Set<string>();
  for (const line of text.split(/\r?\n/)) {
    const match = line.match(/^\*\*\* (?:Add|Update|Delete) File: (.+)$/);
    if (match?.[1]) out.add(match[1].trim());
    const move = line.match(/^\*\*\* Move to: (.+)$/);
    if (move?.[1]) out.add(move[1].trim());
  }
  return [...out].slice(0, 20);
}

/**
 * Host-agnostic user-model contract for user-aware agents.
 *
 * This is intentionally separate from the existing `MemoryScope` type, which
 * still means extraction routing scope (`project` | `global`). User context
 * scopes describe where a model facet is safe and useful to apply.
 */

export const USER_MODEL_CORE_QUESTION =
  "What does the agent need to understand about this user to act well right now?";

export const USER_MODEL_DIMENSIONS = [
  "preferences",
  "goals",
  "projects",
  "constraints",
  "current_priorities",
  "communication_style",
  "risk_tolerance",
  "people_relationships",
  "past_decisions",
  "definitions_of_good",
  "ask_before_rules",
  "do_not_use_outside_rules",
] as const;

export type UserModelDimension = (typeof USER_MODEL_DIMENSIONS)[number];

export const USER_CONTEXT_SCOPES = [
  "personal",
  "work",
  "client",
  "project",
  "repo",
  "tool",
  "temporary",
  "private",
  "do-not-use-outside-this-context",
] as const;

export type UserContextScope = (typeof USER_CONTEXT_SCOPES)[number];

export const USER_BOUNDARY_SCOPES = [
  "temporary",
  "private",
  "do-not-use-outside-this-context",
] as const satisfies readonly UserContextScope[];

export type UserBoundaryScope = (typeof USER_BOUNDARY_SCOPES)[number];

export interface UserModelFacet {
  dimension: UserModelDimension;
  statement: string;
  scopes: UserContextScope[];
  appliesTo?: string[];
  sourceMemoryIds?: string[];
  confidence?: number;
  updatedAt?: string;
}

export interface UserModelCoverage {
  present: UserModelDimension[];
  missing: UserModelDimension[];
  byDimension: Record<UserModelDimension, UserModelFacet[]>;
}

const DIMENSION_ALIASES = new Map<string, UserModelDimension>([
  ["ask_me_before", "ask_before_rules"],
  ["ask_before", "ask_before_rules"],
  ["do_not_use_outside", "do_not_use_outside_rules"],
  ["dont_use_outside", "do_not_use_outside_rules"],
  ["definition_of_good", "definitions_of_good"],
  ["relationships", "people_relationships"],
  ["people_and_relationships", "people_relationships"],
  ["priorities", "current_priorities"],
]);

const SCOPE_ALIASES = new Map<string, UserContextScope>([
  ["do_not_use_outside_this_context", "do-not-use-outside-this-context"],
  ["do_not_use_outside", "do-not-use-outside-this-context"],
  ["dont_use_outside", "do-not-use-outside-this-context"],
  ["repository", "repo"],
  ["client_work", "client"],
]);

function normalizeToken(value: string): string {
  const parts: string[] = [];
  let current = "";

  const pushCurrent = () => {
    if (current.length === 0) return;
    parts.push(current);
    current = "";
  };

  for (const char of value.trim().toLowerCase()) {
    if ((char >= "a" && char <= "z") || (char >= "0" && char <= "9")) {
      current += char;
    } else if (char === "&") {
      pushCurrent();
      parts.push("and");
    } else if (char === "'" || char === '"') {
      continue;
    } else {
      pushCurrent();
    }
  }

  pushCurrent();
  return parts.join("_");
}

export function isUserModelDimension(value: unknown): value is UserModelDimension {
  return typeof value === "string" && USER_MODEL_DIMENSIONS.includes(value as UserModelDimension);
}

export function normalizeUserModelDimension(value: unknown): UserModelDimension | null {
  if (typeof value !== "string") return null;
  if (isUserModelDimension(value)) return value;
  const normalized = normalizeToken(value);
  if (isUserModelDimension(normalized)) return normalized;
  return DIMENSION_ALIASES.get(normalized) ?? null;
}

export function isUserContextScope(value: unknown): value is UserContextScope {
  return typeof value === "string" && USER_CONTEXT_SCOPES.includes(value as UserContextScope);
}

export function normalizeUserContextScope(value: unknown): UserContextScope | null {
  if (typeof value !== "string") return null;
  if (isUserContextScope(value)) return value;
  const normalized = normalizeToken(value);
  const hyphenated = normalized.split("_").join("-");
  if (isUserContextScope(hyphenated)) return hyphenated;
  return SCOPE_ALIASES.get(normalized) ?? null;
}

export function isUserBoundaryScope(value: unknown): value is UserBoundaryScope {
  return typeof value === "string" && USER_BOUNDARY_SCOPES.includes(value as UserBoundaryScope);
}

export function facetHasBoundary(facet: Pick<UserModelFacet, "scopes">): boolean {
  return facet.scopes.some(isUserBoundaryScope);
}

export function summarizeUserModelCoverage(
  facets: readonly UserModelFacet[],
  requiredDimensions: readonly UserModelDimension[] = USER_MODEL_DIMENSIONS,
): UserModelCoverage {
  const byDimension = Object.fromEntries(
    USER_MODEL_DIMENSIONS.map((dimension) => [dimension, [] as UserModelFacet[]]),
  ) as Record<UserModelDimension, UserModelFacet[]>;

  for (const facet of facets) {
    byDimension[facet.dimension].push(facet);
  }

  const present = requiredDimensions.filter((dimension) => byDimension[dimension].length > 0);
  const missing = requiredDimensions.filter((dimension) => byDimension[dimension].length === 0);

  return { present, missing, byDimension };
}

import type { MemoryFile, MemoryFrontmatter } from "../types.js";
import { screenCandidateFact } from "./injection-screen.js";
import type { InjectionScreenProfile } from "./injection-screen.js";
import { resolveSecurityCapabilities, type SecurityConfigProjection } from "../capabilities.js";
import { inferMemoryStatus, isArchivedMemoryPath, toMemoryPathRel } from "../memory-lifecycle-ledger-utils.js";
import { parseStrictCliDate } from "../training-export/date-parse.js";

export type AuditMemoryFindingCategory =
  | "injection-signature"
  | "write-burst"
  | "authority-escalation";

export interface AuditMemoryFinding {
  memoryId: string;
  category: AuditMemoryFindingCategory;
  rule: string;
  excerpt: string;
  lineageHint: string;
}

export interface AuditMemoryStorage {
  readAllMemories(): Promise<MemoryFile[]>;
  readAllColdMemories?: () => Promise<MemoryFile[]>;
  readMemoryByPath(filePath: string): Promise<MemoryFile | null>;
  writeMemoryFrontmatterIfUnchanged(
    expected: MemoryFile,
    patch: Partial<MemoryFrontmatter>,
    lifecycle?: {
      actor?: string;
      reasonCode?: string;
      ruleVersion?: string;
      at?: Date;
    },
  ): Promise<boolean>;
}

export interface AuditMemoryStoreOptions {
  memoryDir: string;
  since?: string | Date;
  quarantine?: boolean;
  /** Screen profile; defaults to "default" (named defense modes pass "hardened"). */
  profile?: InjectionScreenProfile;
  now?: Date;
  storage: AuditMemoryStorage;
}

export interface AuditMemoryReport {
  since?: string;
  scannedMemories: number;
  activeMemories: number;
  findings: AuditMemoryFinding[];
  quarantinedMemoryIds: string[];
  transitions: number;
  writeBurstStats: {
    groupCount: number;
    mean: number;
    standardDeviation: number;
    threshold: number;
    anomalousGroups: Array<{ lineageHint: string; count: number }>;
  };
}

function isActive(memory: MemoryFile, memoryDir: string): boolean {
  // #1955 review: legacy memories without an explicit status ARE active in
  // normal recall (inferMemoryStatus handles missing status), so the audit
  // must include them — otherwise injection-bearing legacy memories can
  // never be reported or quarantined. Explicit non-active statuses bail.
  const status = memory.frontmatter.status;
  if (status !== undefined && status !== "active") return false;
  if (memory.frontmatter.archivedAt !== undefined) return false;
  const pathRel = toMemoryPathRel(memoryDir, memory.path);
  if (isArchivedMemoryPath(memory.path) || isArchivedMemoryPath(pathRel)) return false;
  return inferMemoryStatus(memory.frontmatter, pathRel) === "active";
}

function parseSince(value: string | Date | undefined): Date | undefined {
  if (value === undefined) return undefined;
  if (value instanceof Date) {
    if (Number.isNaN(value.getTime())) throw new Error("invalid --since date");
    return new Date(value.getTime());
  }
  // Strict parse (rejects calendar overflow like 2026-02-31 and trailing
  // junk) — a silently reinterpreted date changes which memories
  // --quarantine may mutate (#1955 review).
  return parseStrictCliDate(value, "--since");
}

function isInWindow(memory: MemoryFile, since: Date | undefined): boolean {
  if (since === undefined) return true;
  const created = Date.parse(memory.frontmatter.created);
  const updated = Date.parse(memory.frontmatter.updated);
  return (Number.isFinite(created) && created >= since.getTime())
    || (Number.isFinite(updated) && updated >= since.getTime());
}

function excerpt(value: string): string {
  const compact = value.replace(/\s+/g, " ").trim();
  return compact.length > 180 ? `${compact.slice(0, 177)}...` : compact;
}

type LineageMetadata = MemoryFrontmatter & {
  sessionKey?: unknown;
  sourceSessionKey?: unknown;
  conversationId?: unknown;
};

function lineageHint(memory: MemoryFile): string {
  const frontmatter = memory.frontmatter as LineageMetadata;
  const source = frontmatter.sources?.[0];
  if (typeof source?.sessionKey === "string" && source.sessionKey.trim().length > 0) {
    return source.sessionKey.trim();
  }
  for (const value of [
    frontmatter.sourceSessionKey,
    frontmatter.sessionKey,
    frontmatter.conversationId,
    frontmatter.sourceTurnId,
    frontmatter.sourceConnector,
    frontmatter.source,
  ]) {
    if (typeof value === "string" && value.trim().length > 0) return value.trim();
  }
  return "unknown";
}

const GENERIC_LINEAGE_VALUES: Record<string, true> = {
  unknown: true,
  none: true,
  null: true,
  "n/a": true,
  na: true,
  extraction: true,
  connector: true,
};

function lineageKey(memory: MemoryFile): string | undefined {
  const frontmatter = memory.frontmatter as LineageMetadata;
  const source = frontmatter.sources?.[0];
  for (const value of [
    source?.sessionKey,
    frontmatter.sourceSessionKey,
    frontmatter.sessionKey,
    frontmatter.conversationId,
  ]) {
    if (typeof value !== "string") continue;
    const key = value.trim();
    if (key.length > 0 && GENERIC_LINEAGE_VALUES[key.toLowerCase()] !== true) return key;
  }
  return undefined;
}

/**
 * Group by lineage AND creation day: a burst is many writes in a SHORT
 * interval, so a long-lived legitimate session must not aggregate months of
 * normal writes into one quarantine-eligible bucket (#1955 review).
 */
function sourceGroups(memories: MemoryFile[]): Map<string, MemoryFile[]> {
  const groups = new Map<string, MemoryFile[]>();
  for (const memory of memories) {
    const lineage = lineageKey(memory);
    // Do not create an "unknown" group. Generic or absent provenance cannot
    // establish a write burst.
    if (lineage === undefined) continue;
    const day = typeof memory.frontmatter.created === "string" ? memory.frontmatter.created.slice(0, 10) : "";
    if (!day) continue;
    const key = `${lineage}@${day}`;
    const group = groups.get(key) ?? [];
    group.push(memory);
    groups.set(key, group);
  }
  return groups;
}

function burstBaseline(counts: number[]): {
  mean: number;
  standardDeviation: number;
  threshold: number;
} {
  if (counts.length === 0) return { mean: 0, standardDeviation: 0, threshold: 10 };
  const mean = counts.reduce((sum, count) => sum + count, 0) / counts.length;
  const variance = counts.reduce((sum, count) => sum + (count - mean) ** 2, 0) / counts.length;
  const standardDeviation = Math.sqrt(variance);
  return {
    mean,
    standardDeviation,
    threshold: Math.max(10, mean + 3 * standardDeviation),
  };
}

function writeBurstStats(groups: Map<string, MemoryFile[]>): AuditMemoryReport["writeBurstStats"] {
  const entries = [...groups.entries()];
  const counts = entries.map(([, group]) => group.length);
  const summary = burstBaseline(counts);
  const anomalousGroups = entries
    .filter(([, group], candidateIndex) => {
      const baselineCounts = counts.filter((_, index) => index !== candidateIndex);
      const baseline = burstBaseline(baselineCounts);
      return group.length > baseline.threshold;
    })
    .map(([lineage, group]) => ({ lineageHint: lineage, count: group.length }));
  return {
    groupCount: counts.length,
    mean: summary.mean,
    standardDeviation: summary.standardDeviation,
    threshold: summary.threshold,
    anomalousGroups,
  };
}

/**
 * The screen profile an audit sweep must use, resolved through the shared
 * security capability plan (#1523) rather than read off config (#3078). The
 * sweep matches the live write path, so a memory this deployment would
 * quarantine on write does not survive once stored; a deployment with the
 * screen DISABLED keeps the `default` weighting, because the sweep must
 * never be stricter than the configured write path.
 */
export function auditScreenProfile(config: SecurityConfigProjection): InjectionScreenProfile {
  const capabilities = resolveSecurityCapabilities(config);
  return capabilities.injectionScreen ? capabilities.injectionScreenProfile : "default";
}

export async function auditMemoryStore(options: AuditMemoryStoreOptions): Promise<AuditMemoryReport> {
  const since = parseSince(options.since);
  const storage = options.storage;
  const hotMemories = await storage.readAllMemories();
  const coldMemories = storage.readAllColdMemories ? await storage.readAllColdMemories() : [];
  const allMemories = [...hotMemories, ...coldMemories];
  const activeMemories = allMemories.filter(
    (memory) => isActive(memory, options.memoryDir) && isInWindow(memory, since),
  );
  const findings: AuditMemoryFinding[] = [];
  const quarantinePaths = new Map<string, { injection: boolean; burst: boolean }>();
  const profile = options.profile ?? "default";

  for (const memory of activeMemories) {
    const screened = screenCandidateFact(memory.content, profile);
    if (screened.quarantine === true) quarantinePaths.set(memory.path, { injection: true, burst: false });
    for (const screenFinding of screened.findings) {
      findings.push({
        memoryId: memory.frontmatter.id,
        category: "injection-signature",
        rule: screenFinding.rule,
        excerpt: excerpt(screenFinding.excerpt || memory.content),
        lineageHint: lineageHint(memory),
      });
      if (screenFinding.rule === "authority-escalation") {
        findings.push({
          memoryId: memory.frontmatter.id,
          category: "authority-escalation",
          rule: screenFinding.rule,
          excerpt: excerpt(screenFinding.excerpt || memory.content),
          lineageHint: lineageHint(memory),
        });
      }
    }
  }

  const groups = sourceGroups(activeMemories);
  const burstStats = writeBurstStats(groups);
  const anomalousLineages = new Set(burstStats.anomalousGroups.map((group) => group.lineageHint));
  for (const [lineage, group] of groups) {
    if (!anomalousLineages.has(lineage)) continue;
    for (const memory of group) {
      const q = quarantinePaths.get(memory.path) ?? { injection: false, burst: false };
      q.burst = true;
      quarantinePaths.set(memory.path, q);
      findings.push({
        memoryId: memory.frontmatter.id,
        category: "write-burst",
        rule: "write-burst",
        excerpt: excerpt(memory.content),
        lineageHint: lineage,
      });
    }
  }

  const quarantinedMemoryIds: string[] = [];
  if (options.quarantine) {
    const now = (options.now ?? new Date()).toISOString();
    for (const staleMemory of activeMemories) {
      const qInfo = quarantinePaths.get(staleMemory.path);
      if (!qInfo) continue;
      // #1955 review: the stale snapshot from readAllMemories can be old enough
      // that intermediate gateway writes would be lost if rewritten blindly. Fetch
      // the live record first.
      const memory = await storage.readMemoryByPath(staleMemory.path);
      if (!memory || !isActive(memory, options.memoryDir)) continue;
      if (qInfo.injection && !qInfo.burst && !screenCandidateFact(memory.content, profile).quarantine) continue;
      const changed = await storage.writeMemoryFrontmatterIfUnchanged(memory, {
        status: "pending_review",
        updated: now,
      }, {
        actor: "cli.security.audit-memory",
        reasonCode: "memory-poisoning-hardening",
        ruleVersion: "memory-poisoning.v1",
      });
      if (changed) quarantinedMemoryIds.push(memory.frontmatter.id);
    }
  }

  return {
    ...(since ? { since: since.toISOString() } : {}),
    scannedMemories: allMemories.length,
    activeMemories: activeMemories.length,
    findings,
    quarantinedMemoryIds,
    transitions: quarantinedMemoryIds.length,
    writeBurstStats: burstStats,
  };
}

export function formatAuditMemoryReport(report: AuditMemoryReport): string {
  const lines = [
    "Memory security audit",
    `Scanned: ${report.scannedMemories} total, ${report.activeMemories} active`,
    `Findings: ${report.findings.length}`,
    `Quarantined: ${report.transitions}`,
    "",
    "CATEGORY               MEMORY ID                 RULE                    LINEAGE              EXCERPT",
  ];
  if (report.findings.length === 0) {
    lines.push("(none)");
  } else {
    for (const finding of report.findings) {
      lines.push([
        finding.category.padEnd(22),
        finding.memoryId.padEnd(25),
        finding.rule.padEnd(23),
        finding.lineageHint.slice(0, 19).padEnd(20),
        finding.excerpt,
      ].join(" "));
    }
  }
  return lines.join("\n");
}

