                description: "Session identifier whose coding context scopes the operation.",
              },
              namespace: {
                type: "string",
                description: "Optional explicit namespace (overrides coding-context overlay).",
              },
            },
            required: ["subcommand"],
            additionalProperties: false,
          },
        },
        this.emitLegacyTools
      );
      this.tools = [...this.tools, ...architectureTools];
    }
    if (this.codegraphVisible) {
      // The 14 codegraph parity tools (issue #1554). Each delegates to its
      // boundary operation; the MCP dispatch injects the `tool` field from
      // the operation name. The inputSchema is intentionally permissive —
      // the boundary's zod schema owns validation (rule 51).
      const codegraphToolDefs: Array<{ suffix: string; description: string; required?: string[] }> = [
        { suffix: "index", description: "Index a repository into the code graph.", required: ["repoRoot"] },
        { suffix: "list_projects", description: "List code graph projects for the principal." },
        {
          suffix: "delete_project",
          description: "Delete a code graph project (requires confirm: true).",
          required: ["confirm"],
        },
        { suffix: "index_status", description: "Get the indexing status for a project." },
        { suffix: "search_graph", description: "Search the code graph for symbols.", required: ["query"] },
        {
          suffix: "trace_path",
          description: "Trace call/dependency paths from a starting symbol.",
          required: ["start"],
        },
        { suffix: "detect_changes", description: "Detect changed symbols since a git ref.", required: ["head"] },
        {
          suffix: "query_graph",
          description: "Run a structured query against the code graph.",
          required: ["structuredQuery"],
        },
        { suffix: "get_schema", description: "Get the code graph schema statistics." },
        { suffix: "get_snippet", description: "Get a source code snippet for a symbol.", required: ["qualifiedName"] },
        { suffix: "get_architecture", description: "Get the composed architecture card + graph stats." },
        {
          suffix: "search_code",
          description: "Search the code graph for code (functions, classes, methods).",
          required: ["query"],
        },
        {
          suffix: "manage_adr",
          description: "Manage ADRs via Track A decision records (list, get, record, supersede).",
          required: ["subcommand"],
        },
        {
          suffix: "ingest_traces",
          description: "Ingest call-site traces to upgrade edge confidence.",
          required: ["traces"],
        },
      ];
      for (const def of codegraphToolDefs) {
        const tools = withToolAliases(
          {
            name: `engram.codegraph_${def.suffix}`,
            description: def.description,
            inputSchema: {
              type: "object",
              properties: {
                sessionKey: {
                  type: "string",
                  description: "Session identifier whose coding context scopes the operation.",
                },
                project: { type: "string", description: "Explicit project id (defaults to session coding context)." },
                principal: { type: "string", description: "Authenticated principal override." },
                query: { type: "string" },
                limit: { type: "number" },
                start: { type: "string" },
                direction: { type: "string", enum: ["inbound", "outbound", "both"] },
                depth: { type: "number" },
                qualifiedName: { type: "string" },
                path: { type: "string" },
                structuredQuery: { type: "object" },
                head: { type: "string" },
                repoRoot: { type: "string" },
                mode: { type: "string", enum: ["auto", "full", "incremental"] },
                confirm: { type: "boolean" },
                subcommand: { type: "string", enum: ["list", "get", "record", "supersede"] },
                id: { type: "string" },
                title: { type: "string" },
                status: { type: "string", enum: ["proposed", "accepted", "superseded", "rejected"] },
                context: { type: "string" },
                decision: { type: "string" },
                consequences: { type: "string" },
                entityRefs: { type: "array", items: { type: "string" } },
                supersedesId: { type: "string" },
                traces: { type: "array", items: { type: "object" } },
              },
              required: def.required ?? [],
              additionalProperties: false,
            },
          },
          this.emitLegacyTools
        );
        this.tools = [...this.tools, ...tools];
      }
    }
    if (this.sessionDeltaVisible) {
      const deltaTools = withToolAliases(
        {
          name: "engram.coding_delta",
          description:
            "Get the session delta (commits + touched files since last seen) for the session's coding namespace (issue #1548 Track A PR 4). Subcommand: get.",
          inputSchema: {
            type: "object",
            properties: {
              subcommand: {
                type: "string",
                enum: ["get"],
                description: "Which delta operation to run.",
              },
              sessionKey: {
                type: "string",
                description: "Session identifier whose coding context scopes the operation.",
              },
              namespace: {
                type: "string",
                description: "Optional explicit namespace (overrides coding-context overlay).",
              },
            },
            required: ["subcommand"],
            additionalProperties: false,
          },
        },
        this.emitLegacyTools
      );
      this.tools = [...this.tools, ...deltaTools];
    }
    if (this.correctionVisible) {
      const correctionTools = correctionMcpTools.flatMap((tool) =>
        withToolAliases(tool, this.emitLegacyTools),
      );
      this.tools = [...this.tools, ...correctionTools];
    }
    if (this.chatVisible) {
      const chatTools = withToolAliases(
        {
          name: "engram.memory_chat",
          description:
            "Conversational memory inspection and correction (issue #1583). Send a message to chat about what Remnic remembers, inspect memories, or request corrections. Returns {reply, chatSessionId, pendingPlan?}.",
          inputSchema: {
            type: "object",
            properties: {
              message: {
                type: "string",
                description:
                  "The user's message — a question about memories, a correction request, or a confirmation (yes/apply) to proceed with a pending plan.",
              },
              chatSessionId: {
                type: "string",
                description: "Optional existing chat session id to resume. Omit to start a new session.",
              },
            },
            required: ["message"],
            additionalProperties: false,
          },
        },
        this.emitLegacyTools
      );
      this.tools = [...this.tools, ...chatTools];
    }
    // Apply `readOnlyHint` annotations to the conservative read-only
    // allowlist. Done as a final pass so every spread (chat, codegraph,
    // coding_*, correction, etc.) inherits the annotation without
    // scattering the same logic across every `withToolAliases` call site.
    // Suffix-based matching covers both the `remnic_*` and `engram.*`
    // naming forms emitted by `withToolAliases`.
    this.tools = this.tools.map((tool) =>
      isReadOnlyToolName(tool.name) && tool.annotations?.readOnlyHint !== true
        ? { ...tool, annotations: { ...(tool.annotations ?? {}), readOnlyHint: true } }
        : tool
    );
    // Apply `outputSchema` declarations from the registry. Like the
    // readOnlyHint pass above, this is a final suffix-based pass so every
    // tool (including both `remnic_*` and `engram.*` aliases) gets a
    // schema. Tools that already declare an outputSchema (e.g.
    // chatgpt_memory_inspector) are left untouched.
    this.tools = applyToolOutputSchemas(this.tools, CANONICAL_MCP_PREFIX, LEGACY_MCP_PREFIX);
  }

  /** Get clientInfo for a specific MCP session. Returns undefined for non-MCP requests. */
  getClientInfo(sessionId?: string): { name: string; version?: string } | undefined {
    if (sessionId) {
      return this.clientInfoBySession.get(sessionId);
    }
    return undefined;
  }

  /** Pop the session ID generated during an initialize handshake, keyed by correlation ID. */
  popInitSessionId(correlationId: string): string | undefined {
    const sid = this.initSessionIds.get(correlationId);
    if (sid !== undefined) this.initSessionIds.delete(correlationId);
    return sid;
  }

  async handleRequest(request: JsonRpcRequest, options?: McpRequestOptions): Promise<Record<string, unknown> | null> {
    const id = request.id ?? null;
    const method = request.method ?? "";

    if (method === "notifications/initialized") return null;
    if (method === "ping") {
      return { jsonrpc: "2.0", id, result: {} };
    }
    if (method === "initialize") {
      const params = request.params ?? {};
      // MCP initialize REQUIRES params.protocolVersion (string). Reject a
      // missing/mistyped field with JSON-RPC invalid params instead of
      // silently negotiating (repo rule: never reinterpret invalid input).
      // An unsupported-but-well-formed version gets the spec-mandated
      // counter-offer below instead: the server answers with the newest
      // version it supports and the client decides whether to proceed.
      if (typeof params.protocolVersion !== "string" || params.protocolVersion.length === 0) {
        return {
          jsonrpc: "2.0",
          id,
          error: {
            code: -32602,
            message: `initialize requires params.protocolVersion (string); supported versions: ${MCP_SUPPORTED_PROTOCOL_VERSIONS.join(", ")}`,
          },
        };
      }
      const rawClientInfo = params.clientInfo as { name?: string; version?: string } | undefined;
      // Generate a server-side session ID for this MCP session.
      // The caller should send this back as Mcp-Session-Id on subsequent requests.
      const newSessionId = randomUUID();
      if (rawClientInfo && typeof rawClientInfo.name === "string") {
        const info = { name: rawClientInfo.name, version: rawClientInfo.version as string | undefined };
        this.clientInfoBySession.set(newSessionId, info);
        // Evict oldest sessions if map exceeds limit
        if (this.clientInfoBySession.size > 1000) {
          const firstKey = this.clientInfoBySession.keys().next().value;
          if (firstKey) this.clientInfoBySession.delete(firstKey);
        }
      }
      const version = await getMcpServerVersion();
      // Store session ID keyed by correlation ID (unique per HTTP request) so
      // concurrent initializes with the same JSON-RPC id don't collide.
      const corrId = options?.correlationId;
      if (corrId) this.initSessionIds.set(corrId, newSessionId);
      return {
        jsonrpc: "2.0",
        id,
        result: {
          protocolVersion: MCP_SUPPORTED_PROTOCOL_VERSIONS.includes(params.protocolVersion)
            ? params.protocolVersion
            : MCP_DEFAULT_PROTOCOL_VERSION,
          capabilities: {
            tools: {},
            resources: {},
          },
          serverInfo: {
            name: "remnic",
            version,
          },
        },
      };
    }
    if (method === "tools/list") {
      // Issue #1850 round 5 (finding 3): a scoped/deny-all token must not
      // enumerate the full tool surface — filter advertised tools by the
      // token's ops allow-list via the same map callTool uses. Unrestricted
      // tokens (ops axis absent) see everything; unmapped tool ⇒ "" ⇒ hidden.
      const caps = tokenCapabilityStore.getStore();
      const tools =
        caps?.ops === undefined
          ? this.tools
          : this.tools.filter((t) => capabilityAllowsOp(caps, MCP_MIGRATED_OPERATIONS[toLegacyToolName(t.name)] ?? ""));
      return { jsonrpc: "2.0", id, result: { tools } };
    }
    if (method === "resources/list") {
      return {
        jsonrpc: "2.0",
        id,
        result: {
          resources: this.resources,
        },
      };
    }
    if (method === "resources/templates/list") {
      return {
        jsonrpc: "2.0",
        id,
        result: {
          resourceTemplates: [],
        },
      };
    }
    if (method === "resources/read") {
      const params = request.params ?? {};
      const uri = typeof params.uri === "string" ? params.uri : "";
      const resource = this.resources.find((entry) => entry.uri === uri);
      if (!resource) {
        return {
          jsonrpc: "2.0",
          id,
          error: {
            code: -32602,
            message: `Unknown resource URI: ${uri}`,
          },
        };
      }
      const text = this.resourceTextByUri.get(resource.uri);
      if (text === undefined) {
        return {
          jsonrpc: "2.0",
          id,
          error: {
            code: -32603,
            message: `Resource content unavailable: ${resource.uri}`,
          },
        };
      }
      return {
        jsonrpc: "2.0",
        id,
        result: {
          contents: [
            {
              uri: resource.uri,
              mimeType: resource.mimeType,
              text,
              _meta: resource._meta,
            },
          ],
        },
      };
    }
    if (method === "tools/call") {
      const params = request.params ?? {};
      const name = typeof params.name === "string" ? params.name : "";

      try {
        let argumentsObject: Record<string, unknown> = {};
        if ("arguments" in params && params.arguments !== undefined) {
          if (params.arguments === null || typeof params.arguments !== "object" || Array.isArray(params.arguments)) {
            throw new EngramAccessInputError("tools/call arguments must be an object when provided");
          }
          argumentsObject = params.arguments as Record<string, unknown>;
        }
        if (
          !("namespace" in argumentsObject) &&
          options?.namespaceOverride &&
          this.toolAcceptsArgument(name, "namespace")
        ) {
          argumentsObject = { ...argumentsObject, namespace: options.namespaceOverride };
        }
        const skipSessionKeyOverride =
          toLegacyToolName(name) === "engram.lcm_search" &&
          typeof argumentsObject.sessionPrefix === "string" &&
          argumentsObject.sessionPrefix.length > 0;
        if (
          !("sessionKey" in argumentsObject) &&
          !skipSessionKeyOverride &&
          options?.sessionKeyOverride &&
          this.toolAcceptsArgument(name, "sessionKey")
        ) {
          argumentsObject = { ...argumentsObject, sessionKey: options.sessionKeyOverride };
        }
        const effectivePrincipal = options?.principalOverride ?? this.authenticatedPrincipal;
        // Forward the MCP session scope (namespace/sessionKey overrides) so
        // tools like memory_chat bind the caller active scope (Thread 17).
        const mcpScope = {
          ...(options?.namespaceOverride ? { namespace: options.namespaceOverride } : {}),
          ...(options?.sessionKeyOverride ? { sessionKey: options.sessionKeyOverride } : {}),
        };
        // Abort before dispatch so a disconnected request never starts work.
        // Once a mutating tool has returned, cancellation is deferred to the
        // HTTP transport so it can account for the committed write first.
        throwMcpAbort(options?.abortSignal, "MCP request aborted before operation start");
        const result = await this.callTool(
          name,
          argumentsObject,
          effectivePrincipal,
          options?.sessionId,
          mcpScope,
          options?.enforceWriteQuota,
          options?.recordWriteCommit,
          options?.sourceConnector,
          options?.abortSignal
        );
        if (isReadOnlyToolName(name)) {
          throwMcpAbort(options?.abortSignal, "MCP request aborted before response");
        }
        const structuredContent = result;
        return {
          jsonrpc: "2.0",
          id,
          result: {
            content: [{ type: "text", text: JSON.stringify(result ?? null, null, 2) }],
            ...(structuredContent == null ? {} : { structuredContent }),
            isError: false,
          },
        };
      } catch (err) {
        // Cancellation is transport control flow, not a JSON-RPC tool error.
        // Preserve the original AbortError so HTTP can silently end a dead socket.
        if (isAbortError(err)) throw err;
        const message = err instanceof Error ? err.message : String(err);
        return {
          jsonrpc: "2.0",
          id,
          result: {
            content: [{ type: "text", text: message }],
            isError: true,
          },
        };
      }
    }

    return {
      jsonrpc: "2.0",
      id,
      error: {
        code: -32601,
        message: `Method not found: ${method}`,
      },
    };
  }

  async runStdio(input: Readable, output: Writable): Promise<void> {
    input.on("data", (chunk) => {
      this.buffer = Buffer.concat([this.buffer, Buffer.isBuffer(chunk) ? chunk : Buffer.from(chunk)]);
      this.scheduleFlush(output);
    });
    await new Promise<void>((resolve, reject) => {
      input.on("end", resolve);
      input.on("error", reject);
    });
    while (this.flushTask) {
      await this.flushTask;
    }
  }

  private scheduleFlush(output: Writable): void {
    if (this.flushTask) return;
    const task = this.flushBuffer(output)
      .catch((err) => {
        this.writeMessage(output, {
          jsonrpc: "2.0",
          id: null,
          error: {
            code: -32700,
            message: err instanceof Error ? err.message : String(err),
          },
        });
      })
      .finally(() => {
        if (this.flushTask === task) {
          this.flushTask = null;
        }
        if (this.buffer.length > 0) {
          this.scheduleFlush(output);
        }
      });
    this.flushTask = task;
  }

  private async flushBuffer(output: Writable): Promise<void> {
    while (true) {
      const headerEnd = this.buffer.indexOf("\r\n\r\n");
      if (headerEnd < 0) return;
      const headerText = this.buffer.slice(0, headerEnd).toString("utf-8");
      const headers = headerText.split("\r\n");
      const contentLengthHeader = headers.find((line) => line.toLowerCase().startsWith("content-length:"));
      if (!contentLengthHeader) {
        this.buffer = Buffer.alloc(0);
        return;
      }
      const contentLength = Number.parseInt(contentLengthHeader.split(":")[1]?.trim() ?? "0", 10);
      if (!Number.isFinite(contentLength) || contentLength < 0) {
        this.buffer = Buffer.alloc(0);
        return;
      }
      const messageStart = headerEnd + 4;
      const messageEnd = messageStart + contentLength;
      if (this.buffer.length < messageEnd) return;
      const body = this.buffer.slice(messageStart, messageEnd).toString("utf-8");
      this.buffer = this.buffer.slice(messageEnd);

      let parsed: JsonRpcRequest;
      try {
        parsed = JSON.parse(body) as JsonRpcRequest;
      } catch {
        this.writeMessage(output, {
          jsonrpc: "2.0",
          id: null,
          error: {
            code: -32700,
            message: "Parse error",
          },
        });
        continue;
      }
      const response = await this.handleRequest(parsed);
      if (response) {
        this.writeMessage(output, response);
      }
    }
  }

  private writeMessage(output: Writable, payload: Record<string, unknown>): void {
    const body = JSON.stringify(payload);
    const message = `Content-Length: ${Buffer.byteLength(body, "utf-8")}\r\n\r\n${body}`;
    output.write(message);
  }

  private toolAcceptsArgument(name: string, key: string): boolean {
    // Match by canonical name so argument validation resolves whether the
    // caller used `engram.*`, `remnic.*`, or `remnic_*` and regardless of
    // whether legacy aliases are advertised (issue #1427) — a tool stays
    // callable under those names even when only remnic_* appears in tools/list.
    const target = toCanonicalToolName(name);
    const tool = this.tools.find((entry) => toCanonicalToolName(entry.name) === target);
    const inputSchema = getObjectProperties(tool?.inputSchema);
    const properties = getObjectProperties(inputSchema?.properties);
    if (properties && Object.prototype.hasOwnProperty.call(properties, key)) {
      return true;
    }
    return inputSchema?.additionalProperties === true;
  }

  /**
   * Whether a tool accepts a `namespace` argument — i.e. it is a
   * namespace-scoped operation whose effective namespace MUST be gated by the
   * per-token allow-list. Exposed (public) so the HTTP MCP transport can run
   * the SAME effective-namespace enforcement the REST surface runs, without
   * duplicating the tool-schema introspection (issue #1850). Namespace-
   * agnostic tools (peer/wearables/etc.) return false and stay ungated,
   * matching the REST surface where those routes never call resolveNamespace.
   */
  toolAcceptsNamespace(name: string): boolean {
    return this.toolAcceptsArgument(name, "namespace");
  }

  /**
   * Determine whether oai-mem-citation guidance should be appended to recall.
   * Returns true when explicitly enabled via config OR when auto-detect is
   * active and the current MCP session belongs to a Codex adapter client.
   *
   * When no sessionId is provided (e.g., stdio transport where there are no
   * HTTP headers carrying mcp-session-id), fall back to checking if there is
   * exactly one known session whose clientInfo matches the Codex pattern.
   * This covers the common stdio case where a single client connection exists.
   */
  private shouldEmitCitations(mcpSessionId?: string): boolean {
    if (this.citationsEnabled) return true;
    if (!this.citationsAutoDetect) return false;

    // Direct session lookup (HTTP transport with mcp-session-id header).
    if (mcpSessionId) {
      const info = this.clientInfoBySession.get(mcpSessionId);
      if (!info) return false;
      return this.isCodexClient(info);
    }

    // Stdio fallback: no session ID available. If there is exactly one session
    // registered (the typical stdio pattern), check that session's clientInfo.
    if (this.clientInfoBySession.size === 1) {
      const [info] = [...this.clientInfoBySession.values()];
      if (info) return this.isCodexClient(info);
    }

    return false;
  }

  /** Check whether a clientInfo record identifies a Codex adapter client. */
  private isCodexClient(info: { name: string; version?: string }): boolean {
    const lowerName = info.name.toLowerCase();
    return lowerName === "codex-mcp-client" || lowerName.includes("codex");
  }

  /**
   * Build citation metadata for each recall result that has a path.
   * Line range defaults to 1-1 when not determinable from the summary.
   */
  private buildRecallCitations(response: EngramAccessRecallResponse): CitationMetadata[] {
    return response.results
      .filter((r) => r.path && r.path.length > 0)
      .map((r) => ({
        memoryId: r.id,
        path: r.path,
        lineStart: 1,
        lineEnd: 1,
        noteDefault: r.preview?.slice(0, 60) || r.id,
      }));
  }

  private async callTool(
    name: string,
    args: Record<string, unknown>,
    effectivePrincipal?: string,
    mcpSessionId?: string,
    scope?: { namespace?: string; sessionKey?: string },
    enforceWriteQuota?: () => void | Promise<void>,
    recordWriteCommit?: () => void,
    sourceConnector?: string,
    abortSignal?: AbortSignal
  ): Promise<unknown> {
    const migrated = MCP_MIGRATED_OPERATIONS[toLegacyToolName(name)];
    if (!migrated) {
      // Teaching rejection (#3035): name the nearest registered tool instead
      // of a bare "unknown tool". Semantics are unchanged — this still throws
      // and never executes a guessed correction.
      //
      // Candidates are the SAME capability-filtered set `tools/list` shows
      // (issue #1850 finding 3). Enumerating the global map here would let a
      // scoped or deny-all token recover the full tool surface through the
      // error path, re-opening the leak that fix closed.
      const caps = tokenCapabilityStore.getStore();
      const visible = this.tools
        .filter(
          (t) =>
            caps?.ops === undefined || capabilityAllowsOp(caps, MCP_MIGRATED_OPERATIONS[toLegacyToolName(t.name)] ?? "")
        )
        .map((t) => t.name);
      throw new Error(unknownToolError(name, visible));
    }
    const op = getOperation(migrated);
    if (!op) {
      throw new EngramAccessInputError(`access-boundary: operation not registered: ${migrated}`);
    }
    let envelope: Record<string, unknown>;
    const wireSchema = MCP_WIRE_SCHEMAS[migrated];
    if (wireSchema) {
      envelope = parseMcpRequest(wireSchema, args) as Record<string, unknown>;
    } else if (migrated.startsWith("codegraph_")) {
      envelope = { ...args, tool: migrated.slice("codegraph_".length) };
    } else if (migrated === "chat_message") {
      // memory_chat bypasses op.run(); gate op + resumed-session namespace like the HTTP route (#1850 r6).
      assertOperationAllowed(tokenCapabilityStore.getStore(), migrated);
      const message = typeof args.message === "string" ? args.message : "";
      if (!message) throw new EngramAccessInputError("message is required");
      const chatSessionId = typeof args.chatSessionId === "string" ? args.chatSessionId : undefined;
      if (chatSessionId) {
        await enforceChatSessionNamespace(this.service, chatSessionId);
      } else {
        // NEW chat session (no chatSessionId): processChatMessage mints a fresh
        // session under the EFFECTIVE namespace (scope.namespace OR server
        // default). Unlike the HTTP chat handler (which forwards no namespace),
        // the MCP scope CAN carry one (Thread 17), so route it through the SAME
        // effective-namespace chokepoint as the HTTP new-chat path
        // (enforceNamespaceAllowList maps undefined → default) — a namespace-
        // scoped token CANNOT start a chat in a namespace outside its allow-
        // list, including an unconfigured/forbidden server default. Fail closed;
        // no-op for unrestricted/legacy tokens (issue #1850 round 8).
        enforceNamespaceAllowList(
          tokenCapabilityStore.getStore(),
          scope?.namespace,
          this.service.configRef?.defaultNamespace
        );
      }
      const chatResult = await processChatMessage({
        service: this.service,
        config: this.service.configRef?.chat,
        memoryDir: this.service.memoryDir,
        message,
        ...(chatSessionId ? { chatSessionId } : {}),
        ...(effectivePrincipal ? { principal: effectivePrincipal } : {}),
        ...(scope?.namespace ? { namespace: scope.namespace } : {}),
        ...(scope?.sessionKey ? { sessionKey: scope.sessionKey } : {}),
      });
      if (chatResult && typeof chatResult === "object" && "error" in chatResult) {
        const { error: _stripped, ...wireResult } = chatResult as unknown as Record<string, unknown>;
        return wireResult;
      }
      return chatResult;
    } else {
      envelope = args;
    }
    // recall citation guidance (MCP-specific post-processing).
    if (migrated === "recall") {
      const result = (await op.run(envelope, {
        service: this.service,
        authenticatedPrincipal: effectivePrincipal,
        ...(sourceConnector ? { sourceConnector } : {}),
        ...(abortSignal ? { abortSignal } : {}),
      })) as { result: unknown };
      throwMcpAbort(abortSignal, "MCP recall aborted before postprocessing");
      const response = result.result as Record<string, unknown>;
      if (this.shouldEmitCitations(mcpSessionId)) {
        const citations = this.buildRecallCitations(response as unknown as EngramAccessRecallResponse);
        const guidance = buildCitationGuidance(citations);
        if (guidance.length > 0) {
          return {
            ...response,
            context: (((response as Record<string, unknown>).context as string) ?? "") + guidance,
            citations,
          };
        }
      }
      return response;
    }
    const output = (await op.run(envelope, {
      service: this.service,
      authenticatedPrincipal: effectivePrincipal,
      ...(enforceWriteQuota || recordWriteCommit
        ? {
            hooks: {
              ...(enforceWriteQuota ? { enforceWriteQuota } : {}),
              ...(recordWriteCommit ? { recordWriteCommit } : {}),
            },
          }
        : {}),
      ...(sourceConnector ? { sourceConnector } : {}),
      ...(abortSignal ? { abortSignal } : {}),
    })) as { result: unknown };
    return output.result;
  }
}

/**
 * Access-surface binding for the recall-miss diagnosis (issue #3033).
 *
 * `recall-why.ts` holds the stage logic and a port; this module binds that
 * port to the live orchestrator. It lives beside `access-recall-surface.ts`
 * rather than inside it because that file is at its file-size ratchet
 * ceiling (AGENTS.md: extract the addition to a sibling module).
 *
 * Namespace scope is enforced BEFORE the recall fires and the expected-memory
 * lookup is confined to namespaces the caller may read, so the diagnosis can
 * never confirm the existence of a memory in a namespace the caller has no
 * read access to. Read path and write path resolve through the same namespace
 * layer (Review Prevention Checklist #30): the lookup consumes exactly the
 * `recallNamespacesForPrincipal` set the recall itself is scoped by.
 */

import { resolveNamespaceCapabilities, resolveQmdCapabilities } from "./capabilities.js";
import { planRecallMode } from "./intent.js";
import { canReadNamespace, recallNamespacesForPrincipal, resolvePrincipal } from "./namespaces/principal.js";
import { isGenericRecallExcludedPath } from "./orchestration/generic-recall-paths.js";
import type { Orchestrator } from "./orchestrator.js";
import {
  explainRecallMiss,
  RecallWhyInputError,
  type RecallWhyDeps,
  type RecallWhyMemoryRef,
  type RecallWhyReport,
} from "./recall-why.js";
import { summarizeRecallWhy } from "./recall-why-renderer.js";
import {
  describeSearchDegradations,
  fatalSearchDegradations,
  type SearchDegradation,
} from "./search/port.js";
import type { MemoryFile, MemoryStatus } from "./types.js";

export interface RecallWhyRequest {
  query: string;
  /** Memory id or substring to trace through every stage. */
  expect?: string;
  sessionKey?: string;
  namespace?: string;
  authenticatedPrincipal?: string;
  sourceConnector?: string;
  abortSignal?: AbortSignal;
}

export interface RecallWhyResponse {
  /** False when the namespace ACL denied the diagnosis. */
  reportFound: boolean;
  report?: RecallWhyReport;
  /** One-line verdict, for agent callers that do not parse the full report. */
  summary?: string;
}

export interface RecallWhyServiceDeps {
  readonly orchestrator: Orchestrator;
  /** The surface's shared namespace resolver. */
  resolveNamespace(namespace?: string): string;
}

/**
 * Run the recall-miss diagnosis for one request.
 *
 * Throws {@link RecallWhyInputError} for caller-input faults so surfaces can
 * map them to a 400; backend faults are reported inside the report as
 * `backend_unavailable` rather than thrown, because an outage is a diagnosis
 * result, not a diagnosis failure.
 */
export async function runRecallWhy(deps: RecallWhyServiceDeps, request: RecallWhyRequest): Promise<RecallWhyResponse> {
  const query = typeof request.query === "string" ? request.query : "";
  if (query.trim().length === 0) {
    throw new RecallWhyInputError("recallWhy: query is required and must be non-empty");
  }
  const orchestrator = deps.orchestrator;
  const config = orchestrator.config;
  const namespacesEnabled = resolveNamespaceCapabilities(config).namespaces;
  const requestedNamespace = request.namespace?.trim() ? deps.resolveNamespace(request.namespace) : undefined;
  const authenticatedPrincipal = request.authenticatedPrincipal?.trim();
  const principal = authenticatedPrincipal || resolvePrincipal(request.sessionKey, config);

  if (requestedNamespace !== undefined) {
    if (!canReadNamespace(principal, requestedNamespace, config)) {
      return { reportFound: false };
    }
  } else if (namespacesEnabled && !authenticatedPrincipal && !request.sessionKey?.trim()) {
    // Namespaces on but no identity supplied: refuse rather than diagnose
    // against the global namespace (least-privileged default).
    return { reportFound: false };
  }

  const readableNamespaces =
    requestedNamespace !== undefined ? [requestedNamespace] : [...recallNamespacesForPrincipal(principal, config)];
  const recallSessionKey = request.sessionKey?.trim() || undefined;

  const whyDeps: RecallWhyDeps = {
    plannerMode: (prompt) => planRecallMode(prompt),
    scopedNamespaces: readableNamespaces,
    namespacesEnabled,
    isExcludedPath: (memoryPath) => isGenericRecallExcludedPath(memoryPath, config),
    runRecall: async (recallQuery, options) => {
      // A configured-but-unreachable search backend is an OUTAGE, and must
      // never render as "0 candidates" (Review Prevention Checklist #22).
      // This is the same pair of expressions the pipeline emits as
      // `qmdEnabled` / `qmdAvailable` on its recall_summary trace.
      if (resolveQmdCapabilities(config).qmd && !orchestrator.qmd.isAvailable()) {
        return {
          ok: false,
          reason: "backend_unavailable",
          detail: "the search backend is enabled but reported itself unavailable",
        };
      }
      // A backend that answers the availability probe can still fail
      // mid-recall (daemon timeout, deadline exceeded, subprocess error).
      // The pipeline already collects those; `degradationSink` hands us the
      // same array it fills, so the outage is observed rather than inferred.
      const degradations: SearchDegradation[] = [];
      try {
        const captured = await orchestrator.recallWithXrayCapture(recallQuery, options.sessionKey, {
          ...(options.namespace !== undefined ? { namespace: options.namespace } : {}),
          ...(authenticatedPrincipal ? { principalOverride: authenticatedPrincipal } : {}),
          ...(request.sourceConnector ? { sourceConnector: request.sourceConnector } : {}),
          ...(options.abortSignal !== undefined ? { abortSignal: options.abortSignal } : {}),
          degradationSink: degradations,
        });
        const fatal = fatalSearchDegradations(degradations);
        if (fatal.length > 0) {
          return { ok: false, reason: "backend_unavailable", detail: describeSearchDegradations(fatal) };
        }
        return { ok: true, snapshot: captured.snapshot };
      } catch (err) {
        // Cancellation is the caller's decision, not a backend outage.
        if (err instanceof Error && err.name === "AbortError") throw err;
        const observed = degradations.length > 0 ? `${describeSearchDegradations(degradations)}; ` : "";
        return {
          ok: false,
          reason: "backend_unavailable",
          detail: `${observed}${err instanceof Error ? err.message : "recall failed"}`,
        };
      }
    },
    findExpected: (expect) => findExpectedMemory(orchestrator, readableNamespaces, expect),
  };

  const report = await explainRecallMiss(query, {
    deps: whyDeps,
    ...(request.expect !== undefined ? { expect: request.expect } : {}),
    ...(recallSessionKey !== undefined ? { sessionKey: recallSessionKey } : {}),
    ...(requestedNamespace !== undefined ? { namespace: requestedNamespace } : {}),
    ...(request.abortSignal !== undefined ? { abortSignal: request.abortSignal } : {}),
  });

  return { reportFound: true, report, summary: summarizeRecallWhy(report) };
}

/**
 * Resolve `expect` to one stored memory, searching ONLY namespaces the
 * caller may read. An exact id match wins over a substring match; among
 * substring matches the lowest (memoryId, path) pair wins, so repeated runs
 * report the same memory.
 */
async function findExpectedMemory(
  orchestrator: Orchestrator,
  namespaces: readonly string[],
  expect: string
): Promise<RecallWhyMemoryRef | null> {
  const substringMatches: RecallWhyMemoryRef[] = [];
  const seenNamespaces = new Set<string>();
  for (const namespace of namespaces) {
    if (seenNamespaces.has(namespace)) continue;
    seenNamespaces.add(namespace);
    let memories: MemoryFile[];
    try {
      const storage = await orchestrator.getStorageForNamespace(namespace);
      memories = await storage.readAllMemories();
    } catch {
      // A namespace whose storage cannot be read contributes no candidates;
      // the diagnosis still reports on the ones that could be read.
      continue;
    }
    for (const memory of memories) {
      const memoryId = typeof memory.frontmatter.id === "string" ? memory.frontmatter.id : "";
      if (memoryId.length === 0) continue;
      const ref: RecallWhyMemoryRef = {
        memoryId,
        path: memory.path,
        status: (memory.frontmatter.status as MemoryStatus | undefined) ?? "active",
        namespace,
      };
      if (memoryId === expect) return ref;
      if (memoryId.includes(expect) || memory.path.includes(expect)) substringMatches.push(ref);
    }
  }
  if (substringMatches.length === 0) return null;
  // Total comparator: -1 / 0 / 1, and 0 for genuinely equal rows (#12).
  substringMatches.sort((a, b) => {
    if (a.memoryId !== b.memoryId) return a.memoryId < b.memoryId ? -1 : 1;
    if (a.path !== b.path) return a.path < b.path ? -1 : 1;
    return 0;
  });
  return substringMatches[0] ?? null;
}

/**
 * Recall-miss diagnosis (issue #3033).
 *
 * `remnic xray` explains the attribution of results that WERE returned.
 * Nothing explained an absence, so an operator who expected a memory back
 * could not tell their own configuration from a product defect. This module
 * answers the other question: given a query, which pipeline stage dropped
 * the memory I expected?
 *
 * Host-agnostic and strictly READ-ONLY: it persists nothing, indexes
 * nothing, and never mutates recall behaviour. It is deliberately NOT gated
 * by `recallDirectAnswerEnabled` (which gates the xray tier-explain block) —
 * a diagnostic that only works once the feature you are diagnosing is
 * already enabled is useless.
 *
 * Reuse, never fork (AGENTS.md rule 22 / issue decision 3). The pipeline is
 * not re-implemented here. Every stage decision comes from one of exactly
 * two places:
 *
 *   1. The `RecallXraySnapshot` the REAL recall published — its
 *      `results` / `headroomResults` / `appliedResults` / `filters` /
 *      `appliedResultLimit` fields already record what each stage saw and
 *      admitted. That snapshot IS the existing stage recorder.
 *   2. The same shared predicates the pipeline itself calls, injected
 *      through {@link RecallWhyDeps} so a caller cannot accidentally supply
 *      a divergent copy: `planRecallMode`, `isGenericRecallExcludedPath`,
 *      `ACTIVE_STATUSES`, and the shared namespace resolver.
 *
 * Stage order follows the recall contract in AGENTS.md
 * ("Retrieval/Intent/Cache Guardrails" #1): candidate retrieval headroom ->
 * policy filters -> rerank/boost -> cap -> format. A memory is reported
 * against the EARLIEST stage that dropped it.
 *
 * Empty is not failed (Review Prevention Checklist #22): a search-backend
 * outage returns `{ ok: false, failure: { reason: "backend_unavailable" } }`
 * and never "0 candidates".
 */

import { ACTIVE_STATUSES } from "./contradiction/contradiction-scan.js";
import type { RecallXrayResult, RecallXraySnapshot } from "./recall-xray.js";
import type { MemoryStatus, RecallPlanMode } from "./types.js";

/**
 * Pipeline stages, in contract order. Frozen `as const` WITHOUT a
 * `readonly RecallWhyStage[]` annotation so the derived union below stays
 * narrow (Review Prevention Checklist #47).
 */
export const RECALL_WHY_STAGES = Object.freeze(["retrieval", "policy-filter", "rerank", "cap", "format"] as const);

export type RecallWhyStage = (typeof RECALL_WHY_STAGES)[number];

// Pins the narrow union: an unused @ts-expect-error is itself a compile
// error, so widening RECALL_WHY_STAGES to string[] fails the build.
// @ts-expect-error "bogus" is not a RecallWhyStage
const _stageUnionIsNarrow: RecallWhyStage = "bogus";
void _stageUnionIsNarrow;

/** Why a candidate was dropped. */
export const RECALL_WHY_DROP_REASONS = Object.freeze([
  "backend-unavailable",
  "planner-mode",
  "namespace-scope",
  "path-excluded",
  "status-filter",
  "not-a-candidate",
  "score-floor",
  "cap-eviction",
] as const);

export type RecallWhyDropReason = (typeof RECALL_WHY_DROP_REASONS)[number];

// @ts-expect-error "bogus" is not a RecallWhyDropReason
const _reasonUnionIsNarrow: RecallWhyDropReason = "bogus";
void _reasonUnionIsNarrow;

/** A single dropped candidate, attributed to the stage that dropped it. */
export interface RecallWhyDrop {
  memoryId: string;
  path: string;
  reason: RecallWhyDropReason;
  /** Human-readable specifics, e.g. `status=superseded`. */
  detail: string;
}

/** What one pipeline stage saw and admitted. */
export interface RecallWhyStageRecord {
  stage: RecallWhyStage;
  /** Candidates entering the stage. Non-negative integer. */
  considered: number;
  /** Candidates leaving the stage. Non-negative integer. */
  admitted: number;
  /** Filter-ladder detail carried verbatim from the snapshot, when present. */
  reason?: string;
  drops: RecallWhyDrop[];
}

/** Verdict for the `--expect <memory-id|substring>` trace. */
export interface RecallWhyExpectation {
  /** The id or substring the caller asked about, exactly as supplied. */
  expect: string;
  /** True when a stored memory matched `expect`. */
  matched: boolean;
  memoryId?: string;
  path?: string;
  /** True when the memory survived to the injected set. */
  recalled: boolean;
  /** Stage that dropped it. Absent when `recalled` is true. */
  stage?: RecallWhyStage;
  reason?: RecallWhyDropReason;
  detail?: string;
  /** One-line operator remediation. Absent when `recalled` is true. */
  remediation?: string;
}

/** The diagnosis. Rendered identically by CLI, HTTP, and MCP. */
export interface RecallWhyReport {
  /** Stable v1 tag so downstream parsers can version-gate. */
  schemaVersion: "1";
  query: string;
  namespace?: string;
  plannerMode: RecallPlanMode;
  /**
   * False ONLY when the diagnosis itself could not run because the search
   * backend was unavailable. An honest empty pipeline is `ok: true`.
   */
  ok: boolean;
  failure?: { reason: "backend_unavailable"; detail: string };
  recallNamespaces: string[];
  /** Final user-facing cap the recall applied. Non-negative integer. */
  appliedResultLimit: number;
  stages: RecallWhyStageRecord[];
  /** Memory ids that survived every stage. */
  recalledMemoryIds: string[];
  expectation?: RecallWhyExpectation;
}

/**
 * Outcome of replaying the real recall. `ok: false` is reserved for a
 * search backend that could not answer — never for an honest empty
 * result (Review Prevention Checklist #22).
 */
export type RecallWhyRecallOutcome =
  | { ok: true; snapshot: RecallXraySnapshot | null }
  | { ok: false; reason: "backend_unavailable"; detail: string };

/** The stored memory a caller's `--expect` resolved to. */
export interface RecallWhyMemoryRef {
  memoryId: string;
  path: string;
  status: MemoryStatus;
  namespace: string;
}

/**
 * Injected pipeline access. Every member is either the real recall or a
 * predicate the real pipeline itself calls — never a reimplementation.
 */
export interface RecallWhyDeps {
  /** Runs the REAL recall with X-ray capture and reports backend faults. */
  runRecall(
    query: string,
    options: { sessionKey?: string; namespace?: string; abortSignal?: AbortSignal }
  ): Promise<RecallWhyRecallOutcome>;
  /** `planRecallMode` from `intent.ts` — the planner the pipeline uses. */
  plannerMode(query: string): RecallPlanMode;
  /**
   * Namespaces this caller reads, resolved through the SAME shared
   * resolver the recall path uses (rule 30). Used when the recall did
   * not record its own scope.
   */
  scopedNamespaces: readonly string[];
  namespacesEnabled: boolean;
  /** `isGenericRecallExcludedPath` bound to the live config. */
  isExcludedPath(path: string): boolean;
  /** Read-only lookup by exact memory id, else by id/path substring. */
  findExpected(expect: string): Promise<RecallWhyMemoryRef | null>;
}

export interface RecallWhyOptions {
  deps: RecallWhyDeps;
  /** Memory id or substring to trace through every stage. */
  expect?: string;
  sessionKey?: string;
  namespace?: string;
  abortSignal?: AbortSignal;
}

/** Thrown for caller-input faults so surfaces can map them to a 400. */
export class RecallWhyInputError extends Error {
  constructor(message: string) {
    super(message);
    this.name = "RecallWhyInputError";
  }
}

const REMEDIATION: Record<RecallWhyDropReason, string> = {
  "backend-unavailable":
    "The search backend did not answer. Check that the index daemon is running and reachable; this is an outage, not an empty result.",
  "planner-mode":
    "The planner classified this prompt as not needing recall. Pass an explicit recall mode, or rephrase the prompt so it reads as a memory request.",
  "namespace-scope":
    "The memory lives outside the namespaces this recall reads. Query its namespace explicitly, or grant the caller read access to it.",
  "path-excluded":
    "The path is served by a dedicated surface and is excluded from generic recall by design. Read it through that surface instead.",
  "status-filter":
    "Only active memories are injected. Reactivate the memory, or read it through an explicit search or archive surface.",
  "not-a-candidate":
    "The memory exists on disk but retrieval never saw it — the search index is stale for this path. Reindex, then retry.",
  "score-floor":
    "The candidate scored below the relevance floor. Use wording closer to the stored memory, or widen the retrieval budget.",
  "cap-eviction":
    "The candidate survived filtering but was cut by the final result cap. Raise the recall budget or narrow the query.",
};

/**
 * Diagnose why a query did not surface an expected memory.
 *
 * Runs the real recall once, then attributes the outcome to stages. When
 * `expect` is supplied, traces that one memory and names the exact stage
 * that dropped it plus a remediation hint.
 */
export async function explainRecallMiss(query: string, opts: RecallWhyOptions): Promise<RecallWhyReport> {
  // Validate the EXACT value — never normalize first (checklist #45). A
  // whitespace-only query is a caller fault, not an empty query.
  if (typeof query !== "string" || query.length === 0 || query.trim().length === 0) {
    throw new RecallWhyInputError("recallWhy: query is required and must be non-empty");
  }
  const expect = opts.expect;
  if (expect !== undefined && (typeof expect !== "string" || expect.length === 0 || expect.trim().length === 0)) {
    throw new RecallWhyInputError("recallWhy: expect must be a non-empty string when supplied");
  }
  const deps = opts.deps;
  const plannerMode = deps.plannerMode(query);
  const scopedNamespaces = [...deps.scopedNamespaces];

  const outcome = await deps.runRecall(query, {
    ...(opts.sessionKey !== undefined ? { sessionKey: opts.sessionKey } : {}),
    ...(opts.namespace !== undefined ? { namespace: opts.namespace } : {}),
    ...(opts.abortSignal !== undefined ? { abortSignal: opts.abortSignal } : {}),
  });

  if (!outcome.ok) {
    // Empty != failed. The retrieval stage reports the outage; no stage
    // downstream of it ran, so none is reported as having seen zero.
    return {
      schemaVersion: "1",
      query,
      ...(opts.namespace !== undefined ? { namespace: opts.namespace } : {}),
      plannerMode,
      ok: false,
      failure: { reason: "backend_unavailable", detail: outcome.detail },
      recallNamespaces: scopedNamespaces,
      appliedResultLimit: 0,
      stages: [
        {
          stage: "retrieval",
          considered: 0,
          admitted: 0,
          reason: `backend_unavailable: ${outcome.detail}`,
          drops: [],
        },
      ],
      recalledMemoryIds: [],
      ...(expect !== undefined
        ? {
            expectation: {
              expect,
              matched: false,
              recalled: false,
              stage: "retrieval" as const,
              reason: "backend-unavailable" as const,
              detail: outcome.detail,
              remediation: REMEDIATION["backend-unavailable"],
            },
          }
        : {}),
    };
  }

  const snapshot = outcome.snapshot;
  const stages = buildStages(snapshot, plannerMode);
  const recalledMemoryIds = (snapshot?.appliedResults ?? []).map((r) => r.memoryId);
  const expectation =
    expect === undefined ? undefined : await traceExpectation(expect, snapshot, plannerMode, deps, scopedNamespaces);

  return {
    schemaVersion: "1",
    query,
    ...(snapshot?.namespace !== undefined
      ? { namespace: snapshot.namespace }
      : opts.namespace !== undefined
        ? { namespace: opts.namespace }
        : {}),
    plannerMode,
    ok: true,
    recallNamespaces: scopedNamespaces,
    appliedResultLimit: nonNegativeInt(snapshot?.appliedResultLimit),
    stages,
    recalledMemoryIds,
    ...(expectation !== undefined ? { expectation } : {}),
  };
}

// ─── Stage attribution ────────────────────────────────────────────────────

/**
 * Retrieval-stage note per planner mode. `full` and `graph_mode` run the
 * ordinary pipeline and carry no note.
 */
const PLANNER_MODE_NOTE: Partial<Record<RecallPlanMode, string>> = {
  no_recall: "planner mode no_recall: retrieval never ran",
  minimal: "planner mode minimal: retrieval headroom is capped",
};

function buildStages(snapshot: RecallXraySnapshot | null, plannerMode: RecallPlanMode): RecallWhyStageRecord[] {
  if (snapshot === null) {
    // No snapshot published: either the planner short-circuited recall or
    // retrieval produced nothing to capture. Both are honest zero-candidate
    // states, distinct from the backend-outage branch above.
    return [
      {
        stage: "retrieval",
        considered: 0,
        admitted: 0,
        reason: PLANNER_MODE_NOTE[plannerMode] ?? "no candidates were captured for this query",
        drops: [],
      },
    ];
  }

  const captured = snapshot.results;
  const rejected = captured.filter((r) => nonEmpty(r.rejectedBy) !== undefined);
  const admittedByPolicy = captured.length - rejected.length;
  const headroom = snapshot.headroomResults;
  const applied = snapshot.appliedResults;
  const appliedIds = new Set(applied.map((r) => r.memoryId));
  const evicted = headroom.filter((r) => !appliedIds.has(r.memoryId));

  const filterLadder = snapshot.filters
    .map((f) => `${f.name}: ${f.admitted}/${f.considered}${f.reason ? ` (${f.reason})` : ""}`)
    .join("; ");

  return [
    {
      stage: "retrieval",
      considered: captured.length,
      admitted: captured.length,
      // Both stage paths annotate the retrieval row from the SAME table, so
      // a planner mode can never be reported on one path and dropped on the
      // other. Modes with no note omit the key rather than setting it to
      // undefined, keeping the JSON shape byte-stable.
      ...(PLANNER_MODE_NOTE[plannerMode] !== undefined ? { reason: PLANNER_MODE_NOTE[plannerMode] } : {}),
      drops: [],
    },
    {
      stage: "policy-filter",
      considered: captured.length,
      admitted: admittedByPolicy,
      ...(filterLadder.length > 0 ? { reason: filterLadder } : {}),
      drops: sortDrops(
        rejected.map((r) => ({
          memoryId: r.memoryId,
          path: r.path,
          reason: policyReasonFor(nonEmpty(r.rejectedBy) ?? ""),
          detail: `rejectedBy=${nonEmpty(r.rejectedBy) ?? "unknown"}`,
        }))
      ),
    },
    {
      stage: "rerank",
      considered: admittedByPolicy,
      admitted: headroom.length,
      drops: [],
    },
    {
      stage: "cap",
      considered: headroom.length,
      admitted: applied.length,
      reason: `appliedResultLimit=${nonNegativeInt(snapshot.appliedResultLimit)}`,
      drops: sortDrops(
        evicted.map((r) => ({
          memoryId: r.memoryId,
          path: r.path,
          reason: "cap-eviction" as const,
          detail: `cut by appliedResultLimit=${nonNegativeInt(snapshot.appliedResultLimit)}`,
        }))
      ),
    },
    {
      stage: "format",
      considered: applied.length,
      admitted: applied.length,
      reason: `budget used ${nonNegativeInt(snapshot.budget.used)}/${nonNegativeInt(snapshot.budget.chars)} chars`,
      drops: [],
    },
  ];
}

/**
 * Map a filter name the pipeline recorded in `rejectedBy` onto a drop
 * reason. Unknown filter names stay `score-floor`-free and report as
 * `path-excluded`-free too: they fall back to `not-a-candidate` only when
 * nothing matches, so a new pipeline filter can never be silently
 * mis-attributed to an existing reason.
 */
function policyReasonFor(rejectedBy: string): RecallWhyDropReason {
  const name = rejectedBy.toLowerCase();
  if (name.includes("namespace")) return "namespace-scope";
  if (name.includes("status") || name.includes("superseded") || name.includes("quarantine")) {
    return "status-filter";
  }
  if (name.includes("path") || name.includes("artifact") || name.includes("excluded")) {
    return "path-excluded";
  }
  if (name.includes("score") || name.includes("floor") || name.includes("threshold")) {
    return "score-floor";
  }
  return "not-a-candidate";
}

// ─── --expect trace ───────────────────────────────────────────────────────

async function traceExpectation(
  expect: string,
  snapshot: RecallXraySnapshot | null,
  plannerMode: RecallPlanMode,
  deps: RecallWhyDeps,
  /** Effective recall scope: what the pipeline recorded, else the caller's. */
  recallNamespaces: readonly string[]
): Promise<RecallWhyExpectation> {
  const ref = await deps.findExpected(expect);
  if (ref === null) {
    return {
      expect,
      matched: false,
      recalled: false,
      stage: "retrieval",
      reason: "not-a-candidate",
      detail: "no stored memory matches this id or substring",
      remediation: "Nothing on disk matches. Check the id or substring; the memory may never have been written.",
    };
  }

  const base = { expect, matched: true, memoryId: ref.memoryId, path: ref.path };

  if (snapshot !== null) {
    // The snapshot is authoritative about what actually happened, so it is
    // consulted before any predicate is re-evaluated.
    if (snapshot.appliedResults.some((r) => matchesRef(r, ref))) {
      return { ...base, recalled: true };
    }
    const rejectedRow = snapshot.results.find((r) => matchesRef(r, ref) && nonEmpty(r.rejectedBy) !== undefined);
    if (rejectedRow !== undefined) {
      const rejectedBy = nonEmpty(rejectedRow.rejectedBy) ?? "unknown";
      const reason = policyReasonFor(rejectedBy);
      return {
        ...base,
        recalled: false,
        stage: "policy-filter",
        reason,
        detail: `rejectedBy=${rejectedBy}`,
        remediation: REMEDIATION[reason],
      };
    }
    if (snapshot.headroomResults.some((r) => matchesRef(r, ref)) || snapshot.results.some((r) => matchesRef(r, ref))) {
      return {
        ...base,
        recalled: false,
        stage: "cap",
        reason: "cap-eviction",
        detail: `survived filtering but was cut by appliedResultLimit=${nonNegativeInt(snapshot.appliedResultLimit)}`,
        remediation: REMEDIATION["cap-eviction"],
      };
    }
  }

  // The memory never reached the capture. Attribute it to the earliest
  // stage whose own predicate rejects it, in contract order: the planner
  // gates retrieval, then the policy filters run namespace -> path ->
  // status (the order `filterRecallCandidates` and the state-view
  // admission apply them in).
  if (plannerMode === "no_recall") {
    return {
      ...base,
      recalled: false,
      stage: "retrieval",
      reason: "planner-mode",
      detail: "plannerMode=no_recall: retrieval never ran for this query",
      remediation: REMEDIATION["planner-mode"],
    };
  }
  if (deps.namespacesEnabled && !recallNamespaces.includes(ref.namespace)) {
    return {
      ...base,
      recalled: false,
      stage: "policy-filter",
      reason: "namespace-scope",
      detail: `namespace=${ref.namespace} is outside the recall scope [${recallNamespaces.join(", ")}]`,
      remediation: REMEDIATION["namespace-scope"],
    };
  }
  if (deps.isExcludedPath(ref.path)) {
    return {
      ...base,
      recalled: false,
      stage: "policy-filter",
      reason: "path-excluded",
      detail: `path=${ref.path} is excluded from generic recall`,
      remediation: REMEDIATION["path-excluded"],
    };
  }
  if (!ACTIVE_STATUSES.has(ref.status)) {
    return {
      ...base,
      recalled: false,
      stage: "policy-filter",
      reason: "status-filter",
      detail: `status=${ref.status}`,
      remediation: REMEDIATION["status-filter"],
    };
  }
  if (plannerMode === "minimal") {
    return {
      ...base,
      recalled: false,
      stage: "retrieval",
      reason: "planner-mode",
      detail: "plannerMode=minimal: retrieval headroom is capped for this query",
      remediation: REMEDIATION["planner-mode"],
    };
  }
  return {
    ...base,
    recalled: false,
    stage: "retrieval",
    reason: "not-a-candidate",
    detail: "the memory passes every policy filter but retrieval never returned it",
    remediation: REMEDIATION["not-a-candidate"],
  };
}

// ─── Internals ────────────────────────────────────────────────────────────

function matchesRef(result: RecallXrayResult, ref: RecallWhyMemoryRef): boolean {
  return result.memoryId === ref.memoryId || result.path === ref.path;
}

function nonEmpty(value: string | undefined): string | undefined {
  if (typeof value !== "string") return undefined;
  return value.length > 0 ? value : undefined;
}

function nonNegativeInt(value: unknown): number {
  // Reject non-finite explicitly rather than letting NaN fall through a
  // comparison (checklist #45).
  if (typeof value !== "number" || !Number.isFinite(value)) return 0;
  const floored = Math.floor(value);
  return floored > 0 ? floored : 0;
}

/** Total comparator: -1 / 0 / 1, and 0 for genuinely equal rows. */
function sortDrops(drops: RecallWhyDrop[]): RecallWhyDrop[] {
  return [...drops].sort((a, b) => {
    if (a.memoryId !== b.memoryId) return a.memoryId < b.memoryId ? -1 : 1;
    if (a.path !== b.path) return a.path < b.path ? -1 : 1;
    return 0;
  });
}

/**
 * Surface glue for the two recall-diagnostics reads (issue #3033).
 *
 * `access-http.ts` is at its file-size ratchet ceiling, so the route bodies
 * live here and the router keeps only a thin dispatch line each (AGENTS.md:
 * extract the addition to a sibling module). The pre-existing X-ray route
 * body moved here unchanged for the same reason and because the two reads
 * belong together — `xray` explains the results a recall returned, `why`
 * explains the ones it did not.
 *
 * Both helpers return `{ status, body }` rather than writing to the response
 * so they stay unit-testable, matching `handleWhoKnowsHttpQuery`.
 */

import { EngramAccessInputError } from "./access-errors.js";
import type { McpTool } from "./access-mcp.js";
import { RecallWhyInputError } from "./recall-why.js";
import type { RecallWhyRequest, RecallWhyResponse } from "./recall-why-service.js";
import { isRecallDisclosure, type RecallDisclosure } from "./types.js";

export interface RecallDiagnosticsHttpOutcome {
