// HTTP query handling (called from access-http.ts so the route stays thin —
// that file is size-grandfathered).
// ---------------------------------------------------------------------------

export interface WhoKnowsHttpOutcome {
  status: number;
  body: unknown;
}

export async function handleWhoKnowsHttpQuery(deps: {
  getParam: (name: string) => string | null;
  resolveNamespace: (namespace: string | undefined) => string | undefined;
  principal?: string;
  run: (request: { topic: string; limit?: number; namespace?: string; authenticatedPrincipal?: string }) => Promise<WhoKnowsResult>;
}): Promise<WhoKnowsHttpOutcome> {
  const topicParam = deps.getParam("topic");
  if (topicParam === null || topicParam.trim().length === 0) {
    return {
      status: 400,
      body: {
        error: "missing_topic",
        code: "missing_topic",
        message: "topic search parameter is required and must be non-empty",
      },
    };
  }
  let limit: number | undefined;
  const limitParam = deps.getParam("limit");
  if (limitParam !== null && limitParam !== "") {
    const parsed = Number(limitParam);
    if (!Number.isInteger(parsed) || parsed < 1 || parsed > WHO_KNOWS_MAX_LIMIT) {
      return {
        status: 400,
        body: {
          error: "invalid_limit",
          code: "invalid_limit",
          message: `limit expects an integer between 1 and ${WHO_KNOWS_MAX_LIMIT}`,
        },
      };
    }
    limit = parsed;
  }
  const namespaceParam = deps.getParam("namespace");
  // Always resolve (and allow-list check) the effective namespace, even when
  // the param is omitted — the implicit default namespace is still a
  // namespace every other GET route gates the same way.
  const namespace = deps.resolveNamespace(namespaceParam && namespaceParam.length > 0 ? namespaceParam : undefined);
  try {
    return {
      status: 200,
      body: await deps.run({
        topic: topicParam,
        ...(limit !== undefined ? { limit } : {}),
        ...(namespace !== undefined ? { namespace } : {}),
        ...(deps.principal ? { authenticatedPrincipal: deps.principal } : {}),
      }),
    };
  } catch (err) {
    // Input validation (including namespace ACL) is a 400; backend faults
    // bubble to the global handler so they return 500 and get logged.
    if (err instanceof EngramAccessInputError) {
      return { status: 400, body: { error: "invalid_request", code: "invalid_request", message: err.message } };
    }
    throw err;
  }
}

/**
 * Shared renderer for the recall-miss diagnosis (issue #3033).
 *
 * CLI, HTTP, and MCP all render the same {@link RecallWhyReport} through
 * this module — never their own formatting (AGENTS.md rule 22, the same
 * contract `recall-xray-renderer.ts` and `recall-explain-renderer.ts`
 * hold).
 */

import type { RecallWhyReport } from "./recall-why.js";

export type RecallWhyFormat = "json" | "markdown";

export const RECALL_WHY_FORMATS: readonly RecallWhyFormat[] = ["json", "markdown"] as const;

/**
 * Validate and coerce a user-provided `--format` / `format` argument.
 * Unknown values throw an error listing the valid options rather than
 * silently defaulting (Review Prevention Checklist #1 / #39).
 * `undefined` / `null` defaults to `"markdown"`.
 */
export function parseRecallWhyFormat(value: unknown): RecallWhyFormat {
  if (value === undefined || value === null) return "markdown";
  if (typeof value !== "string") {
    throw new Error(`--format expects one of ${RECALL_WHY_FORMATS.join(", ")}; got ${typeof value}`);
  }
  const normalized = value.trim().toLowerCase();
  if (normalized === "json" || normalized === "markdown") return normalized;
  throw new Error(`--format expects one of ${RECALL_WHY_FORMATS.join(", ")}; got ${JSON.stringify(value)}`);
}

export function renderRecallWhy(report: RecallWhyReport, format: RecallWhyFormat): string {
  return format === "json" ? renderRecallWhyJson(report) : renderRecallWhyMarkdown(report);
}

/** Deterministic JSON encoding of the report. */
export function renderRecallWhyJson(report: RecallWhyReport): string {
  return JSON.stringify(report, null, 2);
}

export function renderRecallWhyMarkdown(report: RecallWhyReport): string {
  const lines: string[] = ["# Recall diagnosis", ""];
  lines.push(`- query: \`${report.query}\``);
  lines.push(`- planner mode: \`${report.plannerMode}\``);
  if (report.namespace !== undefined) lines.push(`- namespace: \`${report.namespace}\``);
  lines.push(
    `- recall namespaces: ${
      report.recallNamespaces.length > 0 ? report.recallNamespaces.map((ns) => `\`${ns}\``).join(", ") : "_none_"
    }`
  );
  lines.push(`- applied result limit: ${report.appliedResultLimit}`);
  lines.push(
    `- recalled: ${
      report.recalledMemoryIds.length > 0 ? report.recalledMemoryIds.map((id) => `\`${id}\``).join(", ") : "_nothing_"
    }`
  );
  lines.push("");

  if (report.failure !== undefined) {
    // An outage is never rendered as an empty pipeline (checklist #22).
    lines.push("## Backend unavailable", "");
    lines.push(`The diagnosis could not run: \`${report.failure.reason}\` — ${report.failure.detail}`);
    lines.push("");
    lines.push("This is a backend outage, not a zero-candidate recall.");
    lines.push("");
  }

  lines.push("## Stages", "");
  lines.push("| stage | considered | admitted | detail |");
  lines.push("| --- | --- | --- | --- |");
  for (const stage of report.stages) {
    lines.push(`| ${stage.stage} | ${stage.considered} | ${stage.admitted} | ${escapeCell(stage.reason)} |`);
  }
  lines.push("");

  const dropped = report.stages.filter((stage) => stage.drops.length > 0);
  if (dropped.length > 0) {
    lines.push("## Drops", "");
    for (const stage of dropped) {
      lines.push(`### ${stage.stage}`, "");
      for (const drop of stage.drops) {
        lines.push(`- \`${drop.memoryId}\` (${drop.path}) — ${drop.reason}: ${drop.detail}`);
      }
      lines.push("");
    }
  }

  const expectation = report.expectation;
  if (expectation !== undefined) {
    lines.push("## Expected memory", "");
    lines.push(`- expect: \`${expectation.expect}\``);
    if (!expectation.matched) {
      lines.push("- matched: **no stored memory matches**");
    } else {
      lines.push(`- memory id: \`${expectation.memoryId ?? "unknown"}\``);
      lines.push(`- path: \`${expectation.path ?? "unknown"}\``);
    }
    lines.push("");
    if (expectation.recalled) {
      lines.push("**Recalled.** This memory survived every stage and was injected.");
    } else {
      lines.push(
        `**Dropped at ${expectation.stage ?? "unknown"}: ${expectation.reason ?? "unknown"}** — ${
          expectation.detail ?? "no detail recorded"
        }`
      );
      if (expectation.remediation !== undefined) {
        lines.push("");
        lines.push(`Remediation: ${expectation.remediation}`);
      }
    }
    lines.push("");
  }

  return `${lines.join("\n").trimEnd()}\n`;
}

/** One-line summary suited to a terminal or a chat reply. */
export function summarizeRecallWhy(report: RecallWhyReport): string {
  if (report.failure !== undefined) {
    return `backend_unavailable: ${report.failure.detail}`;
  }
  const expectation = report.expectation;
  if (expectation === undefined) {
    return `recalled ${report.recalledMemoryIds.length} memories (planner mode ${report.plannerMode})`;
  }
  if (!expectation.matched) {
    return `no stored memory matches ${JSON.stringify(expectation.expect)}`;
  }
  if (expectation.recalled) {
    return `${expectation.memoryId ?? expectation.expect} was recalled`;
  }
  return `dropped at ${expectation.stage ?? "unknown"}: ${expectation.reason ?? "unknown"}${
    expectation.detail !== undefined ? ` (${expectation.detail})` : ""
  }`;
}

function escapeCell(value: string | undefined): string {
  // A pipe inside a markdown table cell breaks the row; the filter ladder
  // joins with "; " and can legitimately contain one.
  return value === undefined ? "" : value.replace(/\\/g, "\\\\").replace(/\|/g, "\\|");
}

/**
 * Input validation for the `remnic why` command (issue #3033).
 *
 * Extracted from the CLI handlers so the validation paths are unit-testable
 * without booting an orchestrator — the same split `recall-xray-cli.ts`
 * uses. Every flag rejects a missing or unknown value with a listed-options
 * error instead of silently defaulting (Review Prevention Checklist #1 /
 * #39).
 */

import { parseRecallWhyFormat, type RecallWhyFormat } from "./recall-why-renderer.js";

export interface ParsedWhyCliOptions {
  format: RecallWhyFormat;
  /** Memory id or substring to trace, or undefined when not specified. */
  expect?: string;
  /** Trimmed namespace, or undefined when not specified. */
  namespace?: string;
  /** Trimmed session key, or undefined when not specified. */
  session?: string;
  /** Trimmed, tilde-unexpanded output path, or undefined when stdout. */
  outPath?: string;
}

export function parseWhyCliOptions(
  rawQuery: unknown,
  options: Record<string, unknown>
): { query: string } & ParsedWhyCliOptions {
  if (typeof rawQuery !== "string" || rawQuery.trim().length === 0) {
    throw new Error("why expects a non-empty query argument");
  }
  const format = parseRecallWhyFormat(Object.hasOwn(options, "format") ? options.format : undefined);
  return {
    query: rawQuery,
    format,
    ...maybeStringFlag(options, "expect"),
    ...maybeStringFlag(options, "namespace"),
    ...maybeStringFlag(options, "session"),
    ...maybeStringFlag(options, "out", "outPath"),
  };
}

/**
 * Read one optional string flag. `--flag` with no value arrives as `true`
 * from commander and must fail rather than be reinterpreted as "not
 * supplied"; a whitespace-only value is likewise a caller mistake, not a
 * request for the default.
 */
function maybeStringFlag(options: Record<string, unknown>, flag: string, key = flag): Record<string, string> {
  // `Object.hasOwn` + own-property enumeration: a value inherited from a
  // doctored prototype must never enable a flag (checklist #46).
  if (!Object.hasOwn(options, flag)) return {};
  const value = options[flag];
  if (value === undefined) return {};
  if (typeof value !== "string" || value.trim().length === 0) {
    throw new Error(`--${flag} expects a non-empty value`);
  }
  return { [key]: value.trim() };
}

/**
 * Input-validation + rendering helpers for the `remnic who-knows` CLI
 * command (issue #2057). Extracted so validation paths can be unit-tested
 * without booting an orchestrator (same pattern as `recall-xray-cli.ts`).
 *
 * Rules 14 + 51: bare `--limit`, non-integer or out-of-range values, and an
 * empty topic throw listed-options errors — never silent defaults.
 */

import {
  validateWhoKnowsInput,
  WHO_KNOWS_DEFAULT_LIMIT,
  WHO_KNOWS_MAX_LIMIT,
  type WhoKnowsResult,
} from "./who-knows.js";

export interface ParsedWhoKnowsCliOptions {
  topic: string;
  limit: number;
  namespace?: string;
  json: boolean;
}

/** Split raw argv into the positional topic and a flag bag. Value flags error when bare. */
export function extractWhoKnowsRawArgs(rest: string[]): {
  topic: string;
  options: Record<string, unknown>;
} {
  const VALUE_FLAGS: Record<string, true> = { "--limit": true, "--namespace": true };
  const positional: string[] = [];
  const options: Record<string, unknown> = {};
  for (let i = 0; i < rest.length; i++) {
    const token = rest[i];
    if (token.startsWith("--")) {
      if (token === "--json") {
        options.json = true;
      } else if (VALUE_FLAGS[token]) {
        const value = rest[i + 1];
        if (value === undefined || value.startsWith("--")) {
          throw new Error(`who-knows: ${token} expects a value`);
        }
        options[token.slice(2)] = value;
        i += 1;
      } else {
        throw new Error(`who-knows: unknown option ${token} (expected --limit, --namespace, or --json)`);
      }
    } else {
      positional.push(token);
    }
  }
  return { topic: positional.join(" ").trim(), options };
}

/** Validate the full option bag. Throws listed-options errors for bad input. */
export function parseWhoKnowsCliOptions(rawTopic: unknown, options: Record<string, unknown>): ParsedWhoKnowsCliOptions {
  if (typeof rawTopic !== "string" || rawTopic.trim().length === 0) {
    throw new Error("who-knows: topic is required and must be non-empty");
  }
  let limit = WHO_KNOWS_DEFAULT_LIMIT;
  if (options.limit !== undefined) {
    const parsed = typeof options.limit === "number" ? options.limit : Number(options.limit);
    if (!Number.isInteger(parsed) || parsed < 1 || parsed > WHO_KNOWS_MAX_LIMIT) {
      throw new Error(`who-knows: --limit expects an integer between 1 and ${WHO_KNOWS_MAX_LIMIT}`);
    }
    limit = parsed;
  }
  const namespace = typeof options.namespace === "string" && options.namespace.trim().length > 0
    ? options.namespace.trim()
    : undefined;
  validateWhoKnowsInput(rawTopic, limit);
  return { topic: rawTopic.trim(), limit, namespace, json: options.json === true };
}

export function renderWhoKnowsJson(result: WhoKnowsResult): string {
  return JSON.stringify(result, null, 2);
}

export function renderWhoKnowsText(result: WhoKnowsResult): string {
  if (result.results.length === 0) {
    return `who knows "${result.topic}": no evidence found`;
  }
  const lines = [`who knows "${result.topic}" (top ${result.results.length})`];
  result.results.forEach((hit, index) => {
    const name = hit.entityName || hit.entityId;
    lines.push(`${index + 1}. ${name} [${hit.entityId}] — score ${hit.score.toFixed(4)} — ${hit.rationale}`);
    for (const ref of hit.evidence) {
      lines.push(`   - ${ref.id} (${ref.path}) updated ${ref.updated}`);
    }
  });
  return lines.join("\n");
}

export function renderWhoKnows(result: WhoKnowsResult, json: boolean): string {
  return json ? renderWhoKnowsJson(result) : renderWhoKnowsText(result);
}

/**
 * CLI surface for memory-subject operations (issue #2372).
 *
 * `remnic promotion-candidates` — read-only surfacing of agent-subject,
 * reuse-signaled promotion candidates. `remnic subjects backfill` — the
 * deterministic shadow/apply stamp for unstamped memories. Runners take an
 * io seam (service/storage callbacks + stdout) so tests drive them without
 * booting an orchestrator; the remnic-cli entry supplies the real ones.
 */

import type {
  PromotionCandidatesResult,
  SubjectBackfillReport,
} from "./memory-subject.js";

export interface PromotionCandidatesCliOptions {
  namespace?: string;
  targetNamespace?: string;
  limit: number;
  json: boolean;
}

export function parsePromotionCandidatesCliOptions(args: {
  namespace?: string;
  targetNamespace?: string;
  limit?: string;
  json?: boolean;
}): PromotionCandidatesCliOptions {
  let limit = 20;
  if (args.limit !== undefined) {
    const parsed = Number(args.limit);
    if (!Number.isInteger(parsed) || parsed < 1 || parsed > 100) {
      throw new Error(
        `promotion-candidates: --limit expects an integer in [1, 100] (got ${JSON.stringify(args.limit)})`,
      );
    }
    limit = parsed;
  }
  return {
    ...(args.namespace !== undefined && args.namespace !== "" ? { namespace: args.namespace } : {}),
    ...(args.targetNamespace !== undefined && args.targetNamespace !== ""
      ? { targetNamespace: args.targetNamespace }
      : {}),
    limit,
    json: args.json === true,
  };
}

export function renderPromotionCandidates(result: PromotionCandidatesResult, json: boolean): string {
  if (json) return JSON.stringify(result, null, 2);
  const lines = [
    `Namespace: ${result.namespace}  Target layer: ${result.targetNamespace}  (minAccessCount ${result.minAccessCount})`,
  ];
  if (result.candidates.length === 0) {
    lines.push("No promotion candidates.");
    return lines.join("\n");
  }
  for (const c of result.candidates) {
    lines.push(
      `- ${c.id} [${c.category}] signal=${c.reuseSignal} access=${c.accessCount} reinforced=${c.reinforcementCount} mw=${c.mwSuccess}/${c.mwFail}`,
    );
    lines.push(`  ${c.content.replace(/\s+/g, " ").slice(0, 100)}`);
  }
  lines.push("Promote explicitly with the existing promotion commands; nothing is auto-promoted.");
  return lines.join("\n");
}

export async function runPromotionCandidatesCommand(
  rest: string[],
  io: {
    promotionCandidates: (request: {
      namespace?: string;
      targetNamespace?: string;
      limit?: number;
    }) => Promise<PromotionCandidatesResult>;
    stdout: (line: string) => void;
  },
): Promise<void> {
  const flag = (name: string): string | undefined => {
    const hit = rest.find((a) => a.startsWith(`--${name}=`));
    return hit === undefined ? undefined : hit.slice(name.length + 3);
  };
  const options = parsePromotionCandidatesCliOptions({
    namespace: flag("namespace"),
    targetNamespace: flag("target-namespace"),
    limit: flag("limit"),
    json: rest.includes("--json"),
  });
  const result = await io.promotionCandidates({
    ...(options.namespace !== undefined ? { namespace: options.namespace } : {}),
    ...(options.targetNamespace !== undefined ? { targetNamespace: options.targetNamespace } : {}),
    limit: options.limit,
  });
  io.stdout(renderPromotionCandidates(result, options.json));
}

export interface SubjectsBackfillCliOptions {
  mode: "shadow" | "apply";
  namespace?: string;
}

export function parseSubjectsBackfillCliOptions(args: {
  apply?: boolean;
  namespace?: string;
}): SubjectsBackfillCliOptions {
  return {
    mode: args.apply === true ? "apply" : "shadow",
    ...(args.namespace !== undefined && args.namespace !== "" ? { namespace: args.namespace } : {}),
  };
}

export async function runSubjectsBackfillCommand(
  rest: string[],
  io: {
    backfill: (options: { mode: "shadow" | "apply"; namespace?: string }) => Promise<SubjectBackfillReport>;
    stdout: (line: string) => void;
  },
): Promise<void> {
  const namespaceFlag = rest.find((a) => a.startsWith("--namespace="))?.slice("--namespace=".length);
  const options = parseSubjectsBackfillCliOptions({
    apply: rest.includes("--apply"),
    namespace: namespaceFlag,
  });
  const report = await io.backfill(options);
  const lines = [
    `Mode: ${report.mode}  Scanned: ${report.scanned}  Already stamped: ${report.alreadyStamped}  To stamp: ${report.stamped}`,
  ];
  for (const stamp of report.stamps) {
    lines.push(`- ${stamp.id} [${stamp.category}] → subject: ${stamp.subject}`);
  }
  if (report.mode === "shadow") {
    lines.push("Shadow run — nothing written. Re-run with --apply to stamp.");
  }
  io.stdout(lines.join("\n"));
}

/**
 * Input-validation helpers for the `remnic xray` CLI command (issue
 * #570, PR 3).
 *
 * Pulled out of `cli.ts` so the validation paths can be unit-tested in
 * isolation — the full CLI handler is hard to exercise without booting
 * an orchestrator.  CLAUDE.md rules 14 + 51 require that `--format`,
 * `--budget`, `--namespace`, and `--out` reject missing-value /
 * unknown / non-positive arguments with a listed-options error, rather
 * than silently defaulting.
 */

import {
  parseXrayFormat,
  type RecallXrayFormat,
} from "./recall-xray-renderer.js";
import {
  isRecallDisclosure,
  RECALL_DISCLOSURE_LEVELS,
  type RecallDisclosure,
} from "./types.js";

export interface ParsedXrayCliOptions {
  format: RecallXrayFormat;
  /** Positive integer override, or undefined when not specified. */
  budget?: number;
  /** Trimmed namespace, or undefined when not specified. */
  namespace?: string;
  /** Trimmed, tilde-unexpanded output path, or undefined when stdout. */
  outPath?: string;
  /** Disclosure depth for X-ray telemetry, or undefined when not specified. */
  disclosure?: RecallDisclosure;
}

/**
 * Validate and coerce `--disclosure <level>`.  Must be one of the
 * canonical levels; throws a listed-options error otherwise.
 */
export function parseXrayDisclosureFlag(value: unknown): RecallDisclosure | undefined {
  if (value === undefined || value === null) return undefined;
  if (typeof value !== "string" || !isRecallDisclosure(value)) {
    throw new Error(
      `--disclosure expects one of ${RECALL_DISCLOSURE_LEVELS.join(", ")}; got ${JSON.stringify(value)}`,
    );
  }
  return value;
}

/**
 * Validate and coerce `--budget <chars>`.  Must be a positive integer;
 * throws a listed-options error otherwise.
 */
export function parseXrayBudgetFlag(value: unknown): number | undefined {
  if (value === undefined || value === null) return undefined;
  const parsed = typeof value === "number" ? value : Number(value);
  if (
    !Number.isFinite(parsed) ||
    parsed <= 0 ||
    !Number.isInteger(parsed)
  ) {
    throw new Error(
      `--budget expects a positive integer; got ${JSON.stringify(value)}`,
    );
  }
  return parsed;
}

/**
 * Parse and validate the full option bag for `remnic xray`.  Extracted
 * so the CLI handler in `cli.ts` can stay thin and the validation can
 * be unit-tested without booting an orchestrator.
 */
export function parseXrayCliOptions(
  rawQuery: unknown,
  options: Record<string, unknown>,
): { query: string } & ParsedXrayCliOptions {
  if (typeof rawQuery !== "string" || rawQuery.trim().length === 0) {
    throw new Error("xray: <query> is required and must be non-empty");
  }
  const format = parseXrayFormat(options.format);
  const budget = parseXrayBudgetFlag(options.budget);
  const namespace =
    typeof options.namespace === "string" &&
    options.namespace.trim().length > 0
      ? options.namespace.trim()
      : undefined;
  const outPath =
    typeof options.out === "string" && options.out.trim().length > 0
      ? options.out.trim()
      : undefined;
  const disclosure = parseXrayDisclosureFlag(options.disclosure);
  return {
    query: rawQuery,
    format,
    ...(budget !== undefined ? { budget } : {}),
    ...(namespace !== undefined ? { namespace } : {}),
    ...(outPath !== undefined ? { outPath } : {}),
    ...(disclosure !== undefined ? { disclosure } : {}),
  };
}

/**
 * Unified Recall X-ray renderer (issue #570, PR 2).
 *
 * Pure functions that format a `RecallXraySnapshot` for human text,
 * GitHub-flavored markdown, and machine JSON consumption.  CLI / HTTP
 * / MCP surfaces all call into this module — they do NOT format X-ray
 * output themselves, so rendering is tested in one place (CLAUDE.md
 * rule 22).
 *
 * Scope for PR 2 (this slice):
 *   - Pure rendering.  No IO, no transport, no capture.
 *   - `renderXray(snapshot, format)` with format ∈
 *     `{"json", "text", "markdown"}`.
 *   - `parseXrayFormat(value)` — input validator that rejects unknown
 *     formats with a listed-options error (CLAUDE.md rule 51).
 *   - Golden-file-style tests in `recall-xray-renderer.test.ts`.
 */

import type {
  RecallFilterTrace,
  RecallXrayResult,
  RecallXraySnapshot,
  RecallXrayServedBy,
} from "./recall-xray.js";
import { summarizeDisclosureTokens } from "./recall-xray.js";
import { renderTierExplainTextLines } from "./recall-explain-renderer.js";
import { summarizeRetrievedMemoryProvenance } from "./memory-provenance.js";

export type RecallXrayFormat = "json" | "text" | "markdown";

export const RECALL_XRAY_FORMATS: readonly RecallXrayFormat[] = [
  "json",
  "text",
  "markdown",
] as const;

/**
 * Validate and coerce a user-provided `--format` / `format` argument to
 * `RecallXrayFormat`.  Unknown values throw an error listing valid
 * options (CLAUDE.md rule 51).  `undefined`/`null` defaults to `"text"`.
 */
export function parseXrayFormat(value: unknown): RecallXrayFormat {
  if (value === undefined || value === null) return "text";
  if (typeof value !== "string") {
    throw new Error(
      `--format expects one of ${RECALL_XRAY_FORMATS.join(", ")}; got ${typeof value}`,
    );
  }
  const v = value.trim().toLowerCase();
  if (v === "json" || v === "text" || v === "markdown") return v;
  throw new Error(
    `--format expects one of ${RECALL_XRAY_FORMATS.join(", ")}; got ${JSON.stringify(value)}`,
  );
}

/**
 * Top-level dispatcher.  CLI / HTTP / MCP callers should always route
 * through this function so the three formats stay in lock-step.
 */
export function renderXray(
  snapshot: RecallXraySnapshot | null,
  format: RecallXrayFormat,
): string {
  if (format === "json") return renderXrayJson(snapshot);
  if (format === "markdown") return renderXrayMarkdown(snapshot);
  return renderXrayText(snapshot);
}

// ─── JSON ─────────────────────────────────────────────────────────────────

/**
 * Deterministic JSON encoding of an X-ray snapshot.  Returns a stable
 * v1 envelope when the snapshot is absent so consumers can pattern-match
 * on `snapshotFound` rather than distinguishing `null` vs `{}`.
 */
export function renderXrayJson(snapshot: RecallXraySnapshot | null): string {
  if (!snapshot) {
    return JSON.stringify(
      { schemaVersion: "1", snapshotFound: false },
      null,
      2,
    );
  }
  // `snapshotFound` is injected *before* the rest so downstream JSON
  // consumers see it near the top of the document.
  return JSON.stringify(
    { snapshotFound: true, ...snapshot },
    null,
    2,
  );
}

// ─── Text ─────────────────────────────────────────────────────────────────

export function renderXrayText(snapshot: RecallXraySnapshot | null): string {
  const lines: string[] = ["=== Recall X-ray ==="];
  if (!snapshot) {
    lines.push("No X-ray snapshot captured.");
    return lines.join("\n");
  }

  lines.push(`query: ${snapshot.query}`);
  lines.push(`snapshot-id: ${snapshot.snapshotId}`);
  lines.push(`captured-at: ${formatCapturedAt(snapshot.capturedAt)}`);
  if (snapshot.sessionKey) lines.push(`session: ${snapshot.sessionKey}`);
  if (snapshot.namespace) lines.push(`namespace: ${snapshot.namespace}`);
  if (snapshot.traceId) lines.push(`trace-id: ${snapshot.traceId}`);
  lines.push(
    `budget: ${snapshot.budget.used} / ${snapshot.budget.chars} chars`,
  );
  if (snapshot.degradation) {
    lines.push(
      `degradation: ${snapshot.degradation.state}/${snapshot.degradation.reason}`,
    );
  }

  lines.push("");
  lines.push("--- filters ---");
  if (snapshot.filters.length === 0) {
    lines.push("(no filter traces recorded)");
  } else {
    for (const f of snapshot.filters) {
      lines.push(renderFilterTextLine(f));
    }
  }

  lines.push("");
  lines.push("--- results ---");
  if (snapshot.results.length === 0) {
    lines.push("(no results admitted)");
  } else {
    snapshot.results.forEach((result, idx) => {
      for (const line of renderResultTextLines(result, idx + 1)) {
        lines.push(line);
      }
    });
  }

  lines.push("");
  lines.push("--- tier explain ---");
  for (const line of renderTierExplainTextLines(snapshot.tierExplain ?? null)) {
    lines.push(line);
  }

  return lines.join("\n");
}

function renderFilterTextLine(f: RecallFilterTrace): string {
  const base = `- ${f.name}: ${f.admitted}/${f.considered} admitted`;
  return f.reason ? `${base} (${f.reason})` : base;
}

function renderResultTextLines(
  result: RecallXrayResult,
  rank: number,
): string[] {
  const lines: string[] = [];
  lines.push(`[${rank}] ${result.memoryId} — ${servedByLabel(result.servedBy)}`);
  if (result.path) lines.push(`    path: ${result.path}`);
  if (result.stateView) lines.push(`    state-view: ${result.stateView}`);
  lines.push(`    score: ${renderScoreDecomposition(result)}`);
  if (result.provenance) {
    lines.push(
      `    provenance: ${summarizeRetrievedMemoryProvenance(result.provenance)}`,
    );
    lines.push(`    retrieval-reason: ${result.provenance.retrievalReason}`);
    if (result.provenance.userContextScopes.length > 0) {
      lines.push(
        `    context-scopes: ${result.provenance.userContextScopes.join(", ")}`,
      );
    }
    if (
      result.provenance.safety !== "safe" ||
      result.provenance.safetyReasons.length > 0
    ) {
      const reasonSuffix =
        result.provenance.safetyReasons.length > 0
          ? ` (${result.provenance.safetyReasons.join(", ")})`
          : "";
      lines.push(`    safety: ${result.provenance.safety}${reasonSuffix}`);
    }
  }
  if (result.sourceSpan) {
    const q = truncateForXray(result.sourceSpan.quote, 120);
    lines.push(
      `    source: "${q}" (observed ${result.sourceSpan.observedAt}) [${result.sourceSpan.provenance}]`,
    );
  }
  if (result.admittedBy.length > 0) {
    lines.push(`    admitted-by: ${result.admittedBy.join(", ")}`);
  }
  if (result.rejectedBy) {
    lines.push(`    rejected-by: ${result.rejectedBy}`);
  }
  if (result.graphPath && result.graphPath.length > 0) {
    lines.push(`    graph-path: ${result.graphPath.join(" -> ")}`);
    // Issue #681 PR 3/3 — surface per-edge confidence inline so
    // operators can attribute floor-pruning / PageRank ranking
    // decisions to specific edges. Skipped when no confidences were
    // recorded (legacy snapshot or single-node path).
    if (
      result.graphEdgeConfidences &&
      result.graphEdgeConfidences.length > 0
    ) {
      lines.push(
        `    edge-confidences: ${result.graphEdgeConfidences
          .map((c) => c.toFixed(2))
          .join(", ")}`,
      );
    }
  }
  if (result.pathPenaltyApplied !== undefined) {
    lines.push(`    path-penalty: ${result.pathPenaltyApplied ? "yes" : "no"}`);
  }
  if (result.pathNodeIds && result.pathNodeIds.length > 0) {
    lines.push(`    path-node-ids: ${result.pathNodeIds.join(" -> ")}`);
  }
  if (result.auditEntryId) {
    lines.push(`    audit-entry: ${result.auditEntryId}`);
  }
  return lines;
}

// ─── Markdown ─────────────────────────────────────────────────────────────

export function renderXrayMarkdown(
  snapshot: RecallXraySnapshot | null,
): string {
  const lines: string[] = ["# Recall X-ray"];
  if (!snapshot) {
    lines.push("");
    lines.push("_No X-ray snapshot captured._");
    return lines.join("\n");
  }

  lines.push("");
  lines.push(`**Query:** ${mdInlineCode(snapshot.query)}`);
  lines.push("");
  lines.push("| Field | Value |");
  lines.push("| --- | --- |");
  lines.push(`| Snapshot ID | \`${snapshot.snapshotId}\` |`);
  lines.push(`| Captured at | ${formatCapturedAt(snapshot.capturedAt)} |`);
  if (snapshot.sessionKey) {
    lines.push(`| Session | \`${snapshot.sessionKey}\` |`);
  }
  if (snapshot.namespace) {
    lines.push(`| Namespace | \`${snapshot.namespace}\` |`);
  }
  if (snapshot.traceId) {
    lines.push(`| Trace ID | \`${snapshot.traceId}\` |`);
  }
  lines.push(
    `| Budget | ${snapshot.budget.used} / ${snapshot.budget.chars} chars |`,
  );
  if (snapshot.degradation) {
    lines.push(
      `| Degradation | ${snapshot.degradation.state}/${snapshot.degradation.reason} |`,
    );
  }

  lines.push("");
  lines.push("## Filters");
  if (snapshot.filters.length === 0) {
    lines.push("");
    lines.push("_No filter traces recorded._");
  } else {
    lines.push("");
    lines.push("| Filter | Considered | Admitted | Reason |");
    lines.push("| --- | ---: | ---: | --- |");
    for (const f of snapshot.filters) {
      const reason = f.reason ? mdEscape(f.reason) : "";
      lines.push(`| ${mdEscape(f.name)} | ${f.considered} | ${f.admitted} | ${reason} |`);
    }
  }

  lines.push("");
  lines.push("## Results");
  if (snapshot.results.length === 0) {
    lines.push("");
    lines.push("_No results admitted._");
  } else {
    snapshot.results.forEach((result, idx) => {
      for (const line of renderResultMarkdownLines(result, idx + 1)) {
        lines.push(line);
      }
    });

    // Per-disclosure token-spend summary (issue #677 PR 3/4).  Only
    // emitted when at least one result carries a disclosure level so
    // we don't pollute the snapshot for callers who haven't wired the
    // depth knob through.  Counts and tokens default to 0 for buckets
    // with no contributions.
    const summary = summarizeDisclosureTokens(snapshot.results);
    const hasAnyDisclosure =
      summary.chunk.count + summary.section.count + summary.raw.count > 0;
    if (hasAnyDisclosure) {
      lines.push("");
      lines.push("### Token spend by disclosure");
      lines.push("");
      lines.push("| Disclosure | Results | Estimated tokens |");
      lines.push("| --- | ---: | ---: |");
      lines.push(
        `| chunk | ${summary.chunk.count} | ${summary.chunk.estimatedTokens} |`,
      );
      lines.push(
        `| section | ${summary.section.count} | ${summary.section.estimatedTokens} |`,
      );
      lines.push(
        `| raw | ${summary.raw.count} | ${summary.raw.estimatedTokens} |`,
      );
      if (summary.unspecified.count > 0) {
        lines.push(
          `| _(unspecified)_ | ${summary.unspecified.count} | ${summary.unspecified.estimatedTokens} |`,
        );
      }
    }
  }

  lines.push("");
  lines.push("## Tier Explain");
  if (!snapshot.tierExplain) {
    lines.push("");
    lines.push(
      "_Not populated — direct-answer tier disabled or did not fire._",
    );
  } else {
    const te = snapshot.tierExplain;
    lines.push("");
    lines.push("| Field | Value |");
    lines.push("| --- | --- |");
    lines.push(`| Tier | \`${te.tier}\` |`);
    lines.push(`| Reason | ${mdEscape(te.tierReason)} |`);
    lines.push(`| Candidates considered | ${te.candidatesConsidered} |`);
    lines.push(`| Latency (ms) | ${te.latencyMs} |`);
    lines.push(
      `| Filtered by | ${
        te.filteredBy.length > 0
          ? te.filteredBy.map(mdInlineCode).join(", ")
          : "_(none)_"
      } |`,
    );
    if (te.sourceAnchors && te.sourceAnchors.length > 0) {
      lines.push("");
      lines.push("**Source anchors:**");
      for (const anchor of te.sourceAnchors) {
        const range = anchor.lineRange
          ? `:${anchor.lineRange[0]}-${anchor.lineRange[1]}`
          : "";
        lines.push(`- \`${anchor.path}${range}\``);
      }
    }
  }

  return lines.join("\n");
}

function renderResultMarkdownLines(
  result: RecallXrayResult,
  rank: number,
): string[] {
  const lines: string[] = [];
  lines.push("");
  lines.push(
    `### ${rank}. \`${result.memoryId}\` — ${servedByLabel(result.servedBy)}`,
  );
  if (result.path) {
    lines.push("");
    lines.push(`- **Path:** \`${result.path}\``);
  } else {
    lines.push("");
  }
  lines.push(`- **Score:** ${renderScoreDecomposition(result)}`);
  if (result.provenance) {
    lines.push(
      `- **Provenance:** ${mdEscape(summarizeRetrievedMemoryProvenance(result.provenance))}`,
    );
    lines.push(
      `- **Retrieval reason:** ${mdInlineCode(result.provenance.retrievalReason)}`,
    );
    if (result.provenance.userContextScopes.length > 0) {
      lines.push(
        `- **Context scopes:** ${result.provenance.userContextScopes
          .map(mdInlineCode)
          .join(", ")}`,
      );
    }
    if (
      result.provenance.safety !== "safe" ||
      result.provenance.safetyReasons.length > 0
    ) {
      const reasonSuffix =
        result.provenance.safetyReasons.length > 0
          ? ` (${result.provenance.safetyReasons.map(mdInlineCode).join(", ")})`
          : "";
      lines.push(
        `- **Safety:** ${mdInlineCode(result.provenance.safety)}${reasonSuffix}`,
      );
    }
  }
  if (result.sourceSpan) {
    const q = truncateForXray(result.sourceSpan.quote, 120);
    lines.push(
      `- **Source:** "${mdEscape(q)}" (${mdInlineCode(result.sourceSpan.observedAt)}) \u2014 ${result.sourceSpan.provenance}`,
    );
  }
  if (result.admittedBy.length > 0) {
    lines.push(
      `- **Admitted by:** ${result.admittedBy.map(mdInlineCode).join(", ")}`,
    );
  }
  if (result.stateView) {
    lines.push(`- **State view:** ${mdInlineCode(result.stateView)}`);
  }
  if (result.rejectedBy) {
    lines.push(`- **Rejected by:** ${mdInlineCode(result.rejectedBy)}`);
  }
  if (result.graphPath && result.graphPath.length > 0) {
    lines.push(
      `- **Graph path:** ${result.graphPath
        .map(mdInlineCode)
        .join(" → ")}`,
    );
    // Issue #681 PR 3/3 — render per-edge confidences as a parallel
    // markdown line so operators can correlate them with the path
    // arrows above. Skipped when no confidences were recorded.
    if (
      result.graphEdgeConfidences &&
      result.graphEdgeConfidences.length > 0
    ) {
      lines.push(
        `- **Edge confidences:** ${result.graphEdgeConfidences
          .map((c) => mdInlineCode(c.toFixed(2)))
          .join(", ")}`,
      );
    }
  }
  if (result.pathPenaltyApplied !== undefined) {
    lines.push(
      `- **Path penalty applied:** ${mdInlineCode(result.pathPenaltyApplied ? "yes" : "no")}`,
    );
  }
  if (result.pathNodeIds && result.pathNodeIds.length > 0) {
    lines.push(
      `- **Path node ids:** ${result.pathNodeIds.map(mdInlineCode).join(" → ")}`,
    );
  }
  if (result.auditEntryId) {
    lines.push(`- **Audit entry:** \`${result.auditEntryId}\``);
  }
  if (result.disclosure !== undefined) {
    const tokenLine =
      typeof result.estimatedTokens === "number"
        ? ` (~${result.estimatedTokens} tokens)`
        : "";
    lines.push(`- **Disclosure:** \`${result.disclosure}\`${tokenLine}`);
  } else if (typeof result.estimatedTokens === "number") {
    // Disclosure unspecified but tokens recorded — still surface the
    // budget so the operator can attribute spend.
    lines.push(`- **Estimated tokens:** ${result.estimatedTokens}`);
  }
  return lines;
}

// ─── Shared helpers ───────────────────────────────────────────────────────

function servedByLabel(servedBy: RecallXrayServedBy): string {
  return `served-by=${servedBy}`;
}

function renderScoreDecomposition(result: RecallXrayResult): string {
  const parts: string[] = [`final=${formatScore(result.scoreDecomposition.final)}`];
  const s = result.scoreDecomposition;
  if (s.vector !== undefined) parts.push(`vector=${formatScore(s.vector)}`);
  if (s.bm25 !== undefined) parts.push(`bm25=${formatScore(s.bm25)}`);
  if (s.importance !== undefined) {
    parts.push(`importance=${formatScore(s.importance)}`);
  }
  if (s.mmrPenalty !== undefined) {
    parts.push(`mmr_penalty=${formatScore(s.mmrPenalty)}`);
  }
  if (s.tierPrior !== undefined) {
    parts.push(`tier_prior=${formatScore(s.tierPrior)}`);
  }
  if (s.reinforcementBoost !== undefined && s.reinforcementBoost > 0) {
    parts.push(`reinforcement_boost=${formatScore(s.reinforcementBoost)}`);
  }
  return parts.join(" ");
}

function formatScore(value: number): string {
  // Deterministic 4-decimal formatting keeps golden files stable
  // without printing spurious trailing zeros via toString().
  if (!Number.isFinite(value)) return "0.0000";
  return value.toFixed(4);
}

function formatCapturedAt(ts: number): string {
  if (!Number.isFinite(ts) || ts < 0) return "(unknown)";
  // `new Date(n).toISOString()` throws a RangeError for finite numbers
  // outside the valid Date range (roughly |n| > 8.64e15).  That case
  // can surface when snapshots are corrupted or captured with a
  // custom clock, so coerce it to the same "(unknown)" fallback
  // rather than crashing the renderer.
  try {
    return new Date(ts).toISOString();
  } catch {
    return "(unknown)";
  }
}

function mdEscape(value: string): string {
  // Pipe is the only character that breaks GFM table rendering; escape
  // backslash first so we do not re-escape the escape character.
  return value.replace(/\\/g, "\\\\").replace(/\|/g, "\\|");
}

/**
 * Truncate a quote for X-ray display (issue #1575 PR 3). Collapses internal
 * whitespace runs (including newlines/carriage returns) to single spaces so
 * a multi-line source excerpt cannot split what is meant to be a single X-ray
 * row, then caps at `maxChars` on a word boundary with an ellipsis marker.
 * The JSON \`sourceSpan.quote\` stays verbatim — this is display-only.
 */
function truncateForXray(text: string, maxChars: number): string {
  const collapsed = text.replace(/\s+/g, " ").trim();
  if (collapsed.length <= maxChars) return collapsed;
  const slice = collapsed.slice(0, maxChars);
  const lastSpace = slice.lastIndexOf(" ");
  const cut = lastSpace > Math.floor(maxChars * 0.5) ? slice.slice(0, lastSpace) : slice;
  return `${cut}\u2026`;
}

function mdInlineCode(value: string): string {
  if (value.length === 0) return "``";
  // Use exactly enough backticks to unambiguously wrap content that
  // itself contains backticks (GFM rule).
  const longestRun = /`+/g;
  let maxLen = 0;
  for (const match of value.matchAll(longestRun)) {
    if (match[0].length > maxLen) maxLen = match[0].length;
  }
  const fence = "`".repeat(maxLen + 1);
  const pad = value.startsWith("`") || value.endsWith("`") ? " " : "";
  return `${fence}${pad}${value}${pad}${fence}`;
}

