function average(values: number[]): number | undefined {
  if (values.length === 0) return undefined;
  return values.reduce((sum, value) => sum + value, 0) / values.length;
}

function buildRecallProvenances(
  recall: EngramAccessRecallResponse,
  xray: RecallXraySnapshot | null,
): RetrievedMemoryProvenance[] {
  if (xray === null) {
    return recall.results.map(missingRecallProvenance);
  }
  const matchXrayResult = buildXrayResultMatcher(xray, recall.results);
  return recall.results.map((summary) => {
    const result = matchXrayResult(summary);
    if (result === undefined) {
      return missingXrayResultProvenance(summary);
    }
    return result.provenance ?? missingProvenance(result);
  });
}

function buildXrayResultMatcher(
  xray: RecallXraySnapshot | null,
  recallResults: EngramAccessRecallResponse["results"],
): (summary: EngramAccessRecallResponse["results"][number]) => RecallXrayResult | undefined {
  const xrayById = new Map<string, RecallXrayResult>();
  const xrayIdCounts = new Map<string, number>();
  const recallIdCounts = new Map<string, number>();
  const xrayByPath = new Map<string, RecallXrayResult>();
  for (const summary of recallResults) {
    recallIdCounts.set(summary.id, (recallIdCounts.get(summary.id) ?? 0) + 1);
  }
  for (const result of xray?.results ?? []) {
    xrayById.set(result.memoryId, result);
    xrayIdCounts.set(result.memoryId, (xrayIdCounts.get(result.memoryId) ?? 0) + 1);
    xrayByPath.set(result.path, result);
  }
  return (summary) => {
    if (summary.path) {
      const pathMatch = xrayByPath.get(summary.path);
      if (pathMatch) return pathMatch;
    }
    return xrayIdCounts.get(summary.id) === 1 && recallIdCounts.get(summary.id) === 1
      ? xrayById.get(summary.id)
      : undefined;
  };
}

function buildBlockedSameIdMatcher(
  xray: RecallXraySnapshot | null,
): (memoryId: string) => boolean {
  const blockedIds = new Set<string>();
  for (const result of xray?.results ?? []) {
    if (result.provenance?.safety === "blocked") {
      blockedIds.add(result.memoryId);
    }
  }
  return (memoryId) => blockedIds.has(memoryId);
}

function missingProvenance(result: RecallXrayResult): RetrievedMemoryProvenance {
  return {
    source: "unknown",
    scope: "unknown",
    userContextScopes: [],
    retrievalReason: `X-ray provenance missing for ${result.memoryId || result.path}`,
    confidence: 0,
    stale: false,
    corrected: false,
    correctionState: "none",
    safeToUse: false,
    safety: "blocked",
    safetyReasons: ["X-ray provenance was missing for this memory."],
  };
}

function missingXrayResultProvenance(
  summary: EngramAccessRecallResponse["results"][number],
): RetrievedMemoryProvenance {
  return {
    source: "unknown",
    scope: "unknown",
    userContextScopes: [],
    retrievalReason: `X-ray result missing for ${summary.path || summary.id}`,
    confidence: 0,
    stale: false,
    corrected: false,
    correctionState: "none",
    safeToUse: false,
    safety: "blocked",
    safetyReasons: ["X-ray result was missing for this recalled memory."],
  };
}

function missingRecallProvenance(
  summary: EngramAccessRecallResponse["results"][number],
): RetrievedMemoryProvenance {
  return {
    source: "unknown",
    scope: "unknown",
    userContextScopes: [],
    retrievalReason: `X-ray provenance unavailable for ${summary.id || summary.path}`,
    confidence: 0,
    stale: false,
    corrected: false,
    correctionState: "none",
    safeToUse: false,
    safety: "blocked",
    safetyReasons: ["X-ray provenance was unavailable for this recall."],
  };
}

function formatUnsafeRecallPreview(
  blockedCount: number,
  missingProvenanceCount: number,
): string {
  const reasons: string[] = [];
  if (blockedCount > 0) {
    reasons.push(`${blockedCount} retrieved ${memoryNoun(blockedCount)} ${isAre(blockedCount)} blocked`);
  }
  if (missingProvenanceCount > 0) {
    reasons.push(
      `${missingProvenanceCount} retrieved ${memoryNoun(missingProvenanceCount)} ${isAre(missingProvenanceCount)} missing X-ray provenance`,
    );
  }
  return `Recall preview withheld: ${joinReasons(reasons)} in the current context.`;
}

function memoryNoun(count: number): string {
  return count === 1 ? "memory" : "memories";
}

function isAre(count: number): string {
  return count === 1 ? "is" : "are";
}

function joinReasons(reasons: string[]): string {
  if (reasons.length <= 1) return reasons[0] ?? "memory safety could not be verified";
  return `${reasons.slice(0, -1).join(", ")} and ${reasons[reasons.length - 1]}`;
}

function truncate(value: string, maxChars: number): string {
  if (value.length <= maxChars) return value;
  return `${value.slice(0, Math.max(0, maxChars - 3))}...`;
}

/**
 * OAI-mem-citation parser and formatter (issue #379).
 *
 * Mirrors the citation block format used by Codex's `citations.rs` so that
 * Remnic recall responses produce compatible citation blocks. The model
 * appends these blocks to its final reply, and downstream hooks parse them
 * to increment memory usage tracking.
 *
 * Block format:
 *
 *   <oai-mem-citation>
 *   <citation_entries>
 *   path/to/file.md:1-5|note=[short explanation]
 *   </citation_entries>
 *   <rollout_ids>
 *   rollout-abc123
 *   </rollout_ids>
 *   </oai-mem-citation>
 */

/** A single citation entry referencing a memory file and line range. */
export interface CitationEntry {
  path: string;
  lineStart: number;
  lineEnd: number;
  note: string;
}

/** Parsed citation block containing entries and rollout/thread IDs. */
export interface CitationBlock {
  entries: CitationEntry[];
  rolloutIds: string[];
}

/** Metadata attached to a recall result for citation guidance. */
export interface CitationMetadata {
  memoryId: string;
  path: string;
  lineStart: number;
  lineEnd: number;
  rolloutId?: string;
  noteDefault: string;
}

// ---------------------------------------------------------------------------
// Parser
// ---------------------------------------------------------------------------

const OPEN_TAG = "<oai-mem-citation>";
const CLOSE_TAG = "</oai-mem-citation>";
const ENTRIES_OPEN = "<citation_entries>";
const ENTRIES_CLOSE = "</citation_entries>";
const ROLLOUT_OPEN = "<rollout_ids>";
const ROLLOUT_CLOSE = "</rollout_ids>";
/** Legacy alias accepted during parsing (Codex historically used thread_ids). */
const THREAD_OPEN = "<thread_ids>";
const THREAD_CLOSE = "</thread_ids>";

/**
 * Parse an `<oai-mem-citation>` block from arbitrary text.
 *
 * Returns `null` when no valid block is found. Malformed entry lines are
 * silently skipped; only valid lines contribute to the result. Rollout IDs
 * are deduped while preserving insertion order.
 */
export function parseOaiMemCitation(text: string): CitationBlock | null {
  const openIdx = text.indexOf(OPEN_TAG);
  if (openIdx < 0) return null;
  const closeIdx = text.indexOf(CLOSE_TAG, openIdx + OPEN_TAG.length);
  if (closeIdx < 0) return null;

  const inner = text.slice(openIdx + OPEN_TAG.length, closeIdx);

  const entries = parseEntries(inner);
  const rolloutIds = parseIds(inner, ROLLOUT_OPEN, ROLLOUT_CLOSE)
    ?? parseIds(inner, THREAD_OPEN, THREAD_CLOSE)
    ?? [];

  if (entries.length === 0 && rolloutIds.length === 0) return null;

  return { entries, rolloutIds };
}

function parseEntries(block: string): CitationEntry[] {
  const start = block.indexOf(ENTRIES_OPEN);
  if (start < 0) return [];
  const end = block.indexOf(ENTRIES_CLOSE, start + ENTRIES_OPEN.length);
  if (end < 0) return [];

  const raw = block.slice(start + ENTRIES_OPEN.length, end);
  const lines = raw.split("\n").map((l) => l.trim()).filter((l) => l.length > 0);
  const results: CitationEntry[] = [];
  for (const line of lines) {
    const parsed = parseEntryLine(line);
    if (parsed) results.push(parsed);
  }
  return results;
}

/**
 * Parse a single citation entry line:
 *   `<path>:<line_start>-<line_end>|note=[<note>]`
 *
 * Splits on the LAST `:` before the range pattern, not the first, because
 * file paths can contain colons on some systems (e.g., Windows drive letters
 * like `C:\` or macOS resource forks).
 */
function parseEntryLine(line: string): CitationEntry | null {
  // Match the range+note suffix anchored at the end, allowing the path prefix
  // to contain colons. The (.+) is greedy so it consumes everything up to the
  // LAST `:` before the `\d+-\d+|note=[...]` suffix.
  const match = line.match(/^(.+):(\d+)-(\d+)\|note=\[(.*)?\]$/);
  if (!match) return null;
  const [, pathRaw, startRaw, endRaw, noteRaw] = match;
  if (!pathRaw || !startRaw || !endRaw) return null;
  const lineStart = parseInt(startRaw, 10);
  const lineEnd = parseInt(endRaw, 10);
  const entryPath = pathRaw.trim();
  if (!entryPath || !isValidCitationRange(lineStart, lineEnd)) return null;
  return {
    path: entryPath,
    lineStart,
    lineEnd,
    note: noteRaw ?? "",
  };
}

function isValidCitationRange(lineStart: number, lineEnd: number): boolean {
  return (
    Number.isInteger(lineStart) &&
    Number.isInteger(lineEnd) &&
    lineStart >= 1 &&
    lineEnd >= lineStart
  );
}

function parseIds(block: string, openTag: string, closeTag: string): string[] | null {
  const start = block.indexOf(openTag);
  if (start < 0) return null;
  const end = block.indexOf(closeTag, start + openTag.length);
  if (end < 0) return null;

  const raw = block.slice(start + openTag.length, end);
  const lines = raw.split("\n").map((l) => l.trim()).filter((l) => l.length > 0);

  // Deduplicate preserving insertion order.
  const seen = new Set<string>();
  const unique: string[] = [];
  for (const id of lines) {
    if (!seen.has(id)) {
      seen.add(id);
      unique.push(id);
    }
  }
  return unique.length > 0 ? unique : null;
}

// ---------------------------------------------------------------------------
// Sanitizer
// ---------------------------------------------------------------------------

/**
 * Replace newline characters (\n, \r) with spaces so that note values can be
 * safely embedded in a single citation entry line without corrupting the
 * line-based parser (`parseEntryLine` splits on `\n`).
 */
export function sanitizeNoteForCitation(note: string): string {
  return note.replace(/[\r\n]+/g, " ").trim();
}

// ---------------------------------------------------------------------------
// Formatter
// ---------------------------------------------------------------------------

/**
 * Format a `CitationBlock` into the canonical `<oai-mem-citation>` XML block.
 */
export function formatOaiMemCitation(block: CitationBlock): string {
  const entryLines = block.entries
    .map((e) => `${e.path}:${e.lineStart}-${e.lineEnd}|note=[${sanitizeNoteForCitation(e.note)}]`)
    .join("\n");
  const idLines = block.rolloutIds.join("\n");

  return [
    OPEN_TAG,
    ENTRIES_OPEN,
    entryLines,
    ENTRIES_CLOSE,
    ROLLOUT_OPEN,
    idLines,
    ROLLOUT_CLOSE,
    CLOSE_TAG,
  ].join("\n");
}

// ---------------------------------------------------------------------------
// Guidance builder
// ---------------------------------------------------------------------------

/**
 * Build the citation guidance text appended to recall responses so that the
 * model knows how to emit a citation block in its reply.
 *
 * Returns an empty string when `citations` is empty (no guidance needed).
 */
export function buildCitationGuidance(citations: CitationMetadata[]): string {
  const validCitations = citations.filter((citation) =>
    citation.path.trim().length > 0 &&
    isValidCitationRange(citation.lineStart, citation.lineEnd)
  );
  if (validCitations.length === 0) return "";

  const entryExamples = validCitations.map((c) =>
    `${c.path}:${c.lineStart}-${c.lineEnd}|note=[${sanitizeNoteForCitation(c.noteDefault)}]`,
  );
  const rolloutExamples = validCitations
    .filter((c) => c.rolloutId != null)
    .map((c) => c.rolloutId!);

  // Dedupe rollout IDs preserving order.
  const seenRollouts = new Set<string>();
  const uniqueRollouts: string[] = [];
  for (const id of rolloutExamples) {
    if (!seenRollouts.has(id)) {
      seenRollouts.add(id);
      uniqueRollouts.push(id);
    }
  }

  const lines = [
    "",
    "[Remnic citation guidance]",
    "If you used any of the memories above, append the following to the END of your final reply:",
    OPEN_TAG,
    ENTRIES_OPEN,
    ...entryExamples,
    ENTRIES_CLOSE,
    ROLLOUT_OPEN,
    ...uniqueRollouts,
    ROLLOUT_CLOSE,
    CLOSE_TAG,
  ];

  return lines.join("\n");
}

/**
 * Diff-aware review-context packer (issue #569 PR 4).
 *
 * When an agent is asked "review this PR" / "what changed in this diff" /
 * "look at this diff", the prompt that reaches recall is short and generic
 * — the real signal is the diff itself. This module:
 *
 *   1. Detects review-intent prompts via `isReviewPrompt`.
 *   2. Extracts the touched file list from a unified diff via
 *      `parseTouchedFiles`.
 *   3. Re-ranks a set of candidate memories so that memories whose
 *      `entityRefs` mention a touched path float to the top. The boost is
 *      additive and bounded so it doesn't obliterate the original ranking —
 *      it's a bias, not a filter.
 *
 * Pure — no orchestrator, no storage. Callers inject the candidate memories
 * they already have from their normal recall pipeline. This keeps the
 * module easy to test and integrates cleanly with the existing tiered-recall
 * code in `orchestrator.ts` (the tier itself can be wired later; the pure
 * surface is what PRs 5/6/7 will call).
 */

import type {
  StructuralContextDegradation,
  StructuralContextProvider,
} from "./structural-context.js";

// ──────────────────────────────────────────────────────────────────────────
// Public types
// ──────────────────────────────────────────────────────────────────────────

/**
 * A memory candidate as fed into review-context ranking. The shape is a
 * deliberate subset of the core `MemorySummary` / recall result — only the
 * fields we actually need — so this module stays decoupled from the rest of
 * the codebase and can be reused by CLI tools, bench fixtures, etc.
 */
export interface ReviewCandidate {
  /** Opaque identifier. Echoed unchanged in the output. */
  id: string;
  /**
   * Pre-review relevance score from the upstream recall pipeline. Higher is
   * better. `0` is treated as "no prior signal" and gets the full review
   * boost when a path match is found.
   */
  score: number;
  /**
   * References the memory mentions (file paths, entity names, etc.). Used
   * to decide whether any touched file appears in the memory's scope.
   *
   * Accepts `undefined`/missing so callers can pass sparse records from
   * legacy storage without pre-filling.
   */
  entityRefs?: string[];
}

export interface ReviewContext {
  /**
   * Normalized file paths touched by the diff. Each entry is forward-slashed
   * and relative to the repo root when possible.
   */
  touchedFiles: string[];
  /**
   * Candidates re-sorted so memories whose `entityRefs` mention a touched
   * path are boosted. Shape matches the input `ReviewCandidate[]` — the
   * boost is recorded on each entry as `boost` for observability.
   */
  rankedRecall: Array<ReviewCandidate & { boost: number }>;
  /**
   * Structural-context provider degradation observed while expanding the
   * diff to touched symbols (issue #1548 Track A PR 5, #1536 pattern).
   * Present only when a provider was consulted AND it failed — a silent
   * provider failure must never look like "no structural matches"
   * (CLAUDE.md rule 34). Undefined when no provider was consulted (the
   * pure {@link packReviewContext} path) or when the provider succeeded.
   */
  structuralDegradation?: StructuralContextDegradation;
}

// ──────────────────────────────────────────────────────────────────────────
// Review-prompt heuristic
// ──────────────────────────────────────────────────────────────────────────

/**
 * Keyword list from the #569 design doc, plus obvious paraphrases. All
 * matching is case-insensitive and whole-word (so `reviewer` doesn't trigger
 * on `review` alone).
 */
const REVIEW_KEYWORD_PATTERNS: RegExp[] = [
  /\breview\b/i,
  /\bdiff\b/i,
  /\bwhat changed\b/i,
  /\blook at this pr\b/i,
  /\bwhat('?s|\s+is)\s+in\s+this\s+(pr|patch|diff|change)\b/i,
  /\bcode review\b/i,
];

/**
 * `true` when the prompt looks like a review / diff-explanation request.
 *
 * Empty / non-string input → `false` (the caller shouldn't branch on an
 * invalid prompt).
 */
export function isReviewPrompt(prompt: string | null | undefined): boolean {
  if (typeof prompt !== "string") return false;
  const trimmed = prompt.trim();
  if (!trimmed) return false;
  return REVIEW_KEYWORD_PATTERNS.some((re) => re.test(trimmed));
}

// ──────────────────────────────────────────────────────────────────────────
// Unified-diff parser — extract touched files
// ──────────────────────────────────────────────────────────────────────────

/**
 * Parse a unified diff and return the set of files touched. Accepts both the
 * `diff --git` form (`diff --git a/foo b/bar`) and the `--- / +++` form
 * (`--- a/foo\n+++ b/bar`). Returns deduplicated, repo-root-relative paths
 * (with the conventional `a/` / `b/` prefixes stripped).
 *
 * Path entries of `/dev/null` (used in adds/deletes) are excluded.
 */
export function parseTouchedFiles(diff: string | null | undefined): string[] {
  if (typeof diff !== "string" || !diff.trim()) return [];
  const touched = new Set<string>();
  const lines = diff.split(/\r?\n/);

  for (const line of lines) {
    // `diff --git a/foo/bar.ts b/foo/bar.ts`
    //
    // Paths may be quoted by git when they contain spaces or non-ASCII
    // characters, e.g. `diff --git "a/src/my file.ts" "b/src/my file.ts"`.
    // The two paths are always separated by whitespace at the top level, but
    // whitespace INSIDE quoted paths must NOT split the tokens. Parse the
    // two paths with an explicit tokenizer instead of a `\S+`-based regex
    // (which would shatter `"a/my file.ts"` into `"a/my` / `file.ts"`).
    const gitPrefix = line.match(/^diff --git\s+/);
    if (gitPrefix) {
      const rest = line.slice(gitPrefix[0].length);
      const paths = splitDiffGitPaths(rest);
      if (paths) {
        for (const raw of paths) {
          const stripped = stripDiffPathPrefix(raw);
          if (stripped && stripped !== "/dev/null") touched.add(stripped);
        }
      }
      continue;
    }
    // `--- a/foo/bar.ts` or `+++ b/foo/bar.ts` — or quoted:
    // `--- "a/foo bar.ts"` / `+++ "b/foo bar.ts"` when git emits C-quoted
    // paths for whitespace or non-ASCII filenames.
    //
    // Matched with an anchored prefix and an explicit tokenizer for the
    // tail so quoted paths containing whitespace are not split on the
    // first internal space. The previous `\S+` form silently dropped
    // everything after the first whitespace in a quoted path.
    const headerPrefix = line.match(/^(?:---|\+\+\+)[ \t]+/);
    if (headerPrefix) {
      // Linear trailing space/tab trim instead of /[ \t]+$/, whose anchored
      // quantifier backtracks polynomially on a long diff line (CodeQL
      // js/polynomial-redos).
      const sliced = line.slice(headerPrefix[0].length);
      let tailEnd = sliced.length;
      while (tailEnd > 0 && (sliced[tailEnd - 1] === " " || sliced[tailEnd - 1] === "\t")) tailEnd--;
      const tail = sliced.slice(0, tailEnd);
      const raw = extractSingleDiffPathToken(tail);
      if (raw) {
        const stripped = stripDiffPathPrefix(raw);
        if (stripped && stripped !== "/dev/null") touched.add(stripped);
      }
    }
  }

  return Array.from(touched).sort();
}

/**
 * Extract the single path token from the tail of a `---` / `+++` header
 * line. Returns `null` when the tail is empty or malformed (e.g. an
 * unterminated quoted path). The whole tail is consumed — trailing
 * timestamps from non-git diff frontends (`--- a/foo	2023-01-01`) fall
 * into a leading-token extraction like the quoted-form case.
 */
function extractSingleDiffPathToken(tail: string): string | null {
  if (tail.length === 0) return null;
  if (tail[0] === '"') {
    let j = 1;
    while (j < tail.length) {
      if (tail[j] === "\\" && j + 1 < tail.length) {
        j += 2;
        continue;
      }
      if (tail[j] === '"') break;
      j += 1;
    }
    if (j >= tail.length) return null; // unterminated quoted path
    return tail.slice(0, j + 1);
  }
  // Unquoted: consume up to the first tab or whitespace-run, so standard
  // `--- a/foo	<timestamp>` lines surface just `a/foo`. For ordinary
  // git-style output the tail has no whitespace at all.
  let j = 0;
  while (j < tail.length && tail[j] !== " " && tail[j] !== "\t") j += 1;
  return tail.slice(0, j);
}

/**
 * Split the `a-path b-path` portion of a `diff --git` line into exactly two
 * path tokens, respecting git's quoting convention. Returns `null` when the
 * input cannot be parsed into exactly two tokens.
 */
function splitDiffGitPaths(rest: string): [string, string] | null {
  const tokens: string[] = [];
  let i = 0;
  while (i < rest.length && tokens.length < 2) {
    // Skip leading whitespace between tokens.
    while (i < rest.length && (rest[i] === " " || rest[i] === "\t")) i += 1;
    if (i >= rest.length) break;
    if (rest[i] === '"') {
      // Quoted path: consume up to the matching unescaped `"`. Git escapes
      // inner quotes as `\"`, so we respect backslash escaping.
      let j = i + 1;
      while (j < rest.length) {
        if (rest[j] === "\\" && j + 1 < rest.length) {
          j += 2;
          continue;
        }
        if (rest[j] === '"') break;
        j += 1;
      }
      if (j >= rest.length) return null; // unterminated quoted path
      tokens.push(rest.slice(i, j + 1));
      i = j + 1;
    } else {
      // Unquoted path: run of non-whitespace.
      let j = i;
      while (j < rest.length && rest[j] !== " " && rest[j] !== "\t") j += 1;
      tokens.push(rest.slice(i, j));
      i = j;
    }
  }
  if (tokens.length !== 2) return null;
  return [tokens[0]!, tokens[1]!];
}

function stripDiffPathPrefix(raw: string): string {
  // Git conventionally prefixes paths with `a/` or `b/` in diffs, and
  // quotes the whole path (including the prefix) when it contains spaces or
  // non-ASCII bytes. Quote-stripping must therefore happen BEFORE the
  // prefix check — otherwise `"a/path with spaces.ts"` still starts with
  // `"a` and the prefix is never recognized.
  let s = raw;
  if (s.length >= 2 && s[0] === '"' && s[s.length - 1] === '"') {
    const decoded = decodeGitCQuotedPath(s.slice(1, -1));
    if (decoded === null) {
      return raw;
    }
    s = decoded;
  }
  // Normalize Windows-style backslashes. Must happen AFTER quote stripping
  // so that C-quote escape pairs are decoded before path separators are
  // normalized.
  s = s.replace(/\\/g, "/");
  if (s.startsWith("a/") || s.startsWith("b/")) s = s.slice(2);
  return s;
}

function decodeGitCQuotedPath(value: string): string | null {
  const bytes: number[] = [];
  const encoder = new TextEncoder();
  const appendText = (text: string) => {
    bytes.push(...encoder.encode(text));
  };

  for (let index = 0; index < value.length; index += 1) {
    const char = value[index]!;
    if (char !== "\\") {
      appendText(char);
      continue;
    }

    if (index + 1 >= value.length) {
      appendText("\\");
      continue;
    }

    const next = value[index + 1]!;
    if (next >= "0" && next <= "7") {
      let octal = next;
      let cursor = index + 2;
      while (cursor < value.length && octal.length < 3) {
        const digit = value[cursor]!;
        if (digit < "0" || digit > "7") break;
        octal += digit;
        cursor += 1;
      }
      bytes.push(Number.parseInt(octal, 8));
      index = cursor - 1;
      continue;
    }

    const escaped = cEscapeValue(next);
    if (escaped !== null) {
      appendText(escaped);
      index += 1;
      continue;
    }

    appendText(`\\${next}`);
    index += 1;
  }

  try {
    return new TextDecoder("utf-8", { fatal: true }).decode(Uint8Array.from(bytes));
  } catch {
    return null;
  }
}

function cEscapeValue(value: string): string | null {
  switch (value) {
    case "n":
      return "\n";
    case "t":
      return "\t";
    case "r":
      return "\r";
    case "b":
      return "\b";
    case "f":
      return "\f";
    case "\\":
    case '"':
      return value;
    default:
      return null;
  }
}

// ──────────────────────────────────────────────────────────────────────────
// Ranking
// ──────────────────────────────────────────────────────────────────────────

/**
 * Additive boost per matching touched-file. Tuned so that a single exact
 * match is enough to float a `score=0` candidate above a `score=0.4`
 * unmatched peer, but not so large it buries multi-signal results. `0.5`
 * per match, capped at `1.0` so three matches don't eclipse strong recall.
 */
const BOOST_PER_MATCH = 0.5;
const MAX_BOOST = 1.0;

/**
 * Count how many touched files appear in a memory's entityRefs. Matches are
 * literal substring matches on either direction — either the ref contains
 * the path, or the path contains the ref — so both
 *   - `"src/foo.ts"` refs matching a touched `"src/foo.ts"`, and
 *   - `"foo.ts"` refs matching a touched `"src/foo.ts"`
 * succeed.
 */
function countPathHits(entityRefs: string[] | undefined, touchedFiles: string[]): number {
  if (!entityRefs || entityRefs.length === 0) return 0;
  if (touchedFiles.length === 0) return 0;
  let hits = 0;
  for (const ref of entityRefs) {
    if (typeof ref !== "string" || !ref) continue;
    const lowered = ref.toLowerCase();
    for (const file of touchedFiles) {
      const flower = file.toLowerCase();
      if (lowered === flower) {
        hits += 1;
        break;
      }
      if (lowered.includes(flower) || flower.includes(lowered)) {
        hits += 1;
        break;
      }
    }
  }
  return hits;
}

/**
 * Build a review-context ranking for a set of candidate memories.
 *
 * Contract:
 *   - `touchedFiles` is the parsed diff file list.
 *   - `candidates` is passed through unchanged when no boost applies.
 *   - When a boost applies, the result is sorted by `(score + boost)` desc,
 *     with a stable secondary sort on the original `id` for determinism
 *     (CLAUDE.md #19 — comparators must return 0 for equal items).
 */
export function rankReviewCandidates(
  candidates: ReviewCandidate[],
  touchedFiles: string[],
): Array<ReviewCandidate & { boost: number }> {
  const annotated: Array<ReviewCandidate & { boost: number }> = candidates.map((c) => {
    const hits = countPathHits(c.entityRefs, touchedFiles);
    const boost = Math.min(MAX_BOOST, hits * BOOST_PER_MATCH);
    return { ...c, boost };
  });

  annotated.sort((a, b) => {
    const adjA = a.score + a.boost;
    const adjB = b.score + b.boost;
    if (adjA !== adjB) return adjB - adjA;
    // Stable secondary sort for deterministic ordering on ties.
    if (a.id < b.id) return -1;
    if (a.id > b.id) return 1;
    return 0;
  });

  return annotated;
}

// ──────────────────────────────────────────────────────────────────────────
// Packer entry point
// ──────────────────────────────────────────────────────────────────────────

export interface PackReviewContextInput {
  /** Unified diff, as produced by `git diff`. */
  diff: string | null | undefined;
  /** Candidate memories from the upstream recall pipeline. */
  candidates: ReviewCandidate[];
}

/**
 * Top-level entry point used by the orchestrator (and CLI / bench) when a
 * review-intent prompt is detected.
 *
 * Parses the diff, re-ranks the candidates, and returns both artefacts so
 * the caller can surface `touchedFiles` as context and `rankedRecall` as
 * the recall result.
 */
export function packReviewContext(input: PackReviewContextInput): ReviewContext {
  const touchedFiles = parseTouchedFiles(input.diff);
  const rankedRecall = rankReviewCandidates(input.candidates, touchedFiles);
  return { touchedFiles, rankedRecall };
}

// ──────────────────────────────────────────────────────────────────────────
// Structural-context enhancement (issue #1548 Track A PR 5)
// ──────────────────────────────────────────────────────────────────────────

/**
 * Input for the structural-context-aware review-context packer. The pure
 * {@link packReviewContext} stays unchanged (gate-off parity); this async
 * variant consults a {@link StructuralContextProvider} to expand the diff's
 * touched FILE paths into touched SYMBOL names, widening the match set so
 * memories that mention a changed symbol — not just the file path — float
 * up. The gate (`structuralProvider !== "none"`) is checked ONCE by the
 * caller, never inside this function (rule 39).
 */
export interface PackReviewContextStructuralInput extends PackReviewContextInput {
  /** A probed structural-context provider. Never undefined here. */
  provider: StructuralContextProvider;
  /** Cancellation forwarded to the provider subprocess (rule 40). */
  signal?: AbortSignal;
}

/**
 * Structural-context-aware packer.
 *
 * Contract (issue #1548 Track A PR 5, prove-fail-before characterization):
 *   - Provider returns symbols (`ok: true`) → symbol names are ADDED to the
 *     match set alongside touched files; memories mentioning a symbol get the
 *     same bounded additive boost as a file-path match.
 *   - Provider fails (`ok: false`, any code) → ranking falls back to
 *     FILE-PATH-ONLY boosting, BYTE-IDENTICAL to {@link packReviewContext}
 *     (the match set is exactly the touched files), AND `structuralDegradation`
 *     is populated so xray/doctor can surface the failure (rule 34).
 *
 * The underlying ranker ({@link rankReviewCandidates}) is reused unchanged,
 * so the deterministic ordering, boost cap, and tie-break are identical to
 * the pure path.
 */
export async function packReviewContextStructural(
  input: PackReviewContextStructuralInput,
): Promise<ReviewContext> {
  const touchedFiles = parseTouchedFiles(input.diff);
  const diffString = typeof input.diff === "string" ? input.diff : "";
  const result = await input.provider.symbolsForDiff(diffString, {
    signal: input.signal,
  });

  let matchTerms: string[] = touchedFiles;
  let structuralDegradation: StructuralContextDegradation | undefined;

  if (result.ok) {
    const symbolNames = result.symbols.map((sym) => sym.symbol);
    matchTerms = symbolNames.length > 0 ? [...touchedFiles, ...symbolNames] : touchedFiles;
  } else {
    // Fallback: file-path-only ranking, identical to the pure packer. The
    // degradation is surfaced so the failure is never silent (rule 34).
    structuralDegradation = {
      backend: "structural-context",
      code: result.code,
      detail: result.detail,
    };
  }

  const rankedRecall = rankReviewCandidates(input.candidates, matchTerms);
  return { touchedFiles, rankedRecall, structuralDegradation };
}

/**
 * @remnic/core — Onboarding
 *
 * Detects project language, shape, and documentation to produce
 * an onboarding plan for memory ingestion.
 */

import fs from "node:fs";
import path from "node:path";

// ── Types ────────────────────────────────────────────────────────────────────

export interface OnboardOptions {
  /** Directory to scan (defaults to cwd) */
  directory?: string;
  /** Max depth to walk (default: 6) */
  maxDepth?: number;
  /** Directories to skip */
  excludeDirs?: string[];
}

export interface LanguageInfo {
  /** Language name (e.g. "TypeScript", "Python") */
  language: string;
  /** Confidence in detection (0-1) */
  confidence: number;
  /** Evidence (e.g. ["package.json", "tsconfig.json", "*.ts files"]) */
  evidence: string[];
}

export interface DocFile {
  /** Absolute path */
  path: string;
  /** Relative path from project root */
  relativePath: string;
  /** Estimated type */
  kind: "readme" | "changelog" | "contributing" | "license" | "config" | "docs" | "other";
  /** File size in bytes */
  size: number;
}

export type ProjectShape = "app" | "library" | "monorepo" | "workspace" | "script" | "unknown";

export interface OnboardResult {
  /** Project root */
  directory: string;
  /** Detected languages (sorted by confidence) */
  languages: LanguageInfo[];
  /** Detected project shape */
  shape: ProjectShape;
  /** Shape evidence */
  shapeEvidence: string[];
  /** Discovered documentation files */
  docs: DocFile[];
  /** Total files scanned */
  totalFiles: number;
  /** Duration in ms */
  durationMs: number;
  /** Suggested ingestion plan */
  plan: IngestionPlan;
}

export interface IngestionPlan {
  /** Priority files to ingest first */
  priorityFiles: DocFile[];
  /** Estimated total files to ingest */
  estimatedFiles: number;
  /** Recommended categories */
  categories: string[];
  /** Suggested memory namespace */
  suggestedNamespace: string;
}

// ── Language detection rules ─────────────────────────────────────────────────

interface LanguageRule {
  language: string;
  extensions: string[];
  manifests: string[];
  configFiles: string[];
}

const LANGUAGE_RULES: LanguageRule[] = [
