const DEFAULT_EXCLUDE = new Set([
  "node_modules",
  ".git",
  "vendor",
  "__pycache__",
  ".venv",
  "venv",
  "dist",
  "build",
  ".next",
  ".nuxt",
  "target",
  "coverage",
  ".engram",
]);

// ── Main function ────────────────────────────────────────────────────────────

export function onboard(options: OnboardOptions): OnboardResult {
  const startTime = Date.now();
  const {
    maxDepth = 6,
    excludeDirs = [],
  } = options;
  const directory = path.resolve(options.directory ?? process.cwd());
  let rootStat: fs.Stats;
  try {
    rootStat = fs.statSync(directory);
  } catch (err) {
    throw new Error(`Cannot scan onboarding directory ${directory}: ${err instanceof Error ? err.message : String(err)}`);
  }
  if (!rootStat.isDirectory()) {
    throw new Error(`Cannot scan onboarding directory ${directory}: not a directory`);
  }

  const exclude = new Set([...DEFAULT_EXCLUDE, ...excludeDirs]);

  // Collect all files
  const files = walkDir(directory, exclude, maxDepth);

  // Detect languages
  const languages = detectLanguages(files, directory);

  // Detect shape
  const { shape, evidence: shapeEvidence } = detectShape(files, directory);

  // Discover docs
  const docs = discoverDocs(files, directory);

  // Build plan
  const plan = buildPlan(languages, shape, docs, directory);

  return {
    directory,
    languages,
    shape,
    shapeEvidence,
    docs,
    totalFiles: files.length,
    durationMs: Date.now() - startTime,
    plan,
  };
}

// ── Walk directory ───────────────────────────────────────────────────────────

function walkDir(
  root: string,
  exclude: Set<string>,
  maxDepth: number,
): string[] {
  const results: string[] = [];

  function walk(dir: string, depth: number): void {
    if (depth > maxDepth) return;
    let entries: fs.Dirent[];
    try {
      entries = fs.readdirSync(dir, { withFileTypes: true });
    } catch (err) {
      if (depth === 0) {
        throw new Error(`Cannot scan onboarding directory ${root}: ${err instanceof Error ? err.message : String(err)}`);
      }
      return;
    }

    for (const entry of entries) {
      if (exclude.has(entry.name)) continue;
      const fullPath = path.join(dir, entry.name);
      if (entry.isDirectory()) {
        walk(fullPath, depth + 1);
      } else if (entry.isFile()) {
        results.push(fullPath);
      }
    }
  }

  walk(root, 0);
  return results;
}

// ── Language detection ───────────────────────────────────────────────────────

function detectLanguages(files: string[], root: string): LanguageInfo[] {
  const results: LanguageInfo[] = [];

  // Count extensions
  const extCounts = new Map<string, number>();
  for (const f of files) {
    const ext = path.extname(f).toLowerCase();
    if (ext) extCounts.set(ext, (extCounts.get(ext) ?? 0) + 1);
  }

  // Check manifests at root level
  const rootFiles = new Set(
    files
      .filter((f) => path.dirname(f) === root)
      .map((f) => path.basename(f)),
  );

  for (const rule of LANGUAGE_RULES) {
    const evidence: string[] = [];
    let score = 0;

    // Extension matches
    let extMatch = 0;
    for (const ext of rule.extensions) {
      const count = extCounts.get(ext) ?? 0;
      if (count > 0) {
        extMatch += count;
        evidence.push(`${ext} files (${count})`);
      }
    }
    score += Math.min(extMatch * 0.05, 0.5);

    // Manifest matches
    for (const manifest of rule.manifests) {
      if (manifest.includes("*")) {
        // Glob pattern — e.g. "*.gemspec" matches files ending with ".gemspec"
        const suffix = manifest.replaceAll(/\*/g, "");
        if ([...rootFiles].some((f) => f.endsWith(suffix))) {
          score += 0.2;
          evidence.push(manifest);
        }
      } else if (rootFiles.has(manifest)) {
        score += 0.2;
        evidence.push(manifest);
      }
    }

    // Config matches
    for (const cfg of rule.configFiles) {
      if (rootFiles.has(cfg)) {
        score += 0.1;
        evidence.push(cfg);
      }
    }

    if (score > 0) {
      results.push({
        language: rule.language,
        confidence: Math.min(score, 1),
        evidence,
      });
    }
  }

  return results.sort((a, b) => b.confidence - a.confidence);
}

// ── Shape detection ──────────────────────────────────────────────────────────

function detectShape(
  files: string[],
  root: string,
): { shape: ProjectShape; evidence: string[] } {
  const rootFiles = new Set(
    files
      .filter((f) => path.dirname(f) === root)
      .map((f) => path.basename(f)),
  );

  const rootDirs = new Set<string>();
  try {
    for (const entry of fs.readdirSync(root, { withFileTypes: true })) {
      if (entry.isDirectory()) rootDirs.add(entry.name);
    }
  } catch {
    // ignore
  }

  const evidence: string[] = [];

  // Monorepo: workspace packages/ or libs/ dirs + root package.json with workspaces
  if (rootFiles.has("package.json")) {
    const pkg = readJsonSafe(path.join(root, "package.json"));
    if (pkg?.workspaces) {
      evidence.push("package.json has workspaces");
      return { shape: "monorepo", evidence };
    }
  }

  if (rootDirs.has("packages") || rootDirs.has("libs")) {
    evidence.push("has packages/ or libs/ directory");
    return { shape: "monorepo", evidence };
  }

  // Workspace: pnpm-workspace.yaml, Cargo workspace, go.work
  if (rootFiles.has("pnpm-workspace.yaml") || rootFiles.has("go.work")) {
    evidence.push("workspace manifest found");
    return { shape: "workspace", evidence };
  }

  const cargoToml = readTomlWorkspace(path.join(root, "Cargo.toml"));
  if (cargoToml) {
    evidence.push("Cargo.toml has workspace");
    return { shape: "workspace", evidence };
  }

  // Library: has lib/ or src/index.*, exports in package.json
  if (rootFiles.has("package.json")) {
    const pkg = readJsonSafe(path.join(root, "package.json"));
    if (pkg?.exports || pkg?.main) {
      // If it also has "bin", it's more of an app
      if (pkg?.bin) {
        evidence.push("package.json has bin");
        return { shape: "app", evidence };
      }
      evidence.push("package.json has exports/main");
      return { shape: "library", evidence };
    }
  }

  // Check for app indicators
  if (
    rootFiles.has("Dockerfile") ||
    rootFiles.has("docker-compose.yml") ||
    rootFiles.has("docker-compose.yaml") ||
    rootDirs.has("app") ||
    rootDirs.has("src") && rootDirs.has("public")
  ) {
    evidence.push("app-like structure detected");
    return { shape: "app", evidence };
  }

  // Script: few files, no package manifest
  if (files.length <= 5 && !rootFiles.has("package.json") && !rootFiles.has("pyproject.toml")) {
    evidence.push("few files, no manifest");
    return { shape: "script", evidence };
  }

  return { shape: "unknown", evidence: ["no strong shape signal"] };
}

// ── Doc discovery ────────────────────────────────────────────────────────────

function discoverDocs(files: string[], root: string): DocFile[] {
  const docs: DocFile[] = [];
  const docPatterns: Array<{ pattern: RegExp; kind: DocFile["kind"] }> = [
    { pattern: /^readme(\.\w+)?$/i, kind: "readme" },
    { pattern: /^changelog(\.\w+)?$/i, kind: "changelog" },
    { pattern: /^changes(\.\w+)?$/i, kind: "changelog" },
    { pattern: /^contributing(\.\w+)?$/i, kind: "contributing" },
    { pattern: /^code[_-]of[_-]conduct(\.\w+)?$/i, kind: "contributing" },
    { pattern: /^license(\.\w+)?$/i, kind: "license" },
    { pattern: /^copying(\.\w+)?$/i, kind: "license" },
    { pattern: /^\.env\.example$/i, kind: "config" },
    { pattern: /^\.editorconfig$/i, kind: "config" },
  ];

  for (const filePath of files) {
    const basename = path.basename(filePath).toLowerCase();
    const relPath = path.relative(root, filePath);
    let kind: DocFile["kind"] | undefined;

    // Check against patterns
    for (const { pattern, kind: k } of docPatterns) {
      if (pattern.test(basename)) {
        kind = k;
        break;
      }
    }

    // Check docs/ directories
    if (!kind && isUnderDocsDir(relPath)) {
      kind = "docs";
    }

    // Check markdown files at root or in docs/
    if (!kind && (basename.endsWith(".md") || basename.endsWith(".mdx"))) {
      if (path.dirname(relPath) === "." || isUnderDocsDir(relPath)) {
        kind = "docs";
      }
    }

    if (kind) {
      let size = 0;
      try {
        size = fs.statSync(filePath).size;
      } catch {
        // ignore
      }
      docs.push({
        path: filePath,
        relativePath: relPath,
        kind,
        size,
      });
    }
  }

  return docs;
}

function isUnderDocsDir(relPath: string): boolean {
  const parts = relPath.split(path.sep);
  return parts[0] === "docs" || parts[0] === "doc" || parts[0] === "documentation";
}

// ── Plan generation ──────────────────────────────────────────────────────────

function buildPlan(
  languages: LanguageInfo[],
  shape: ProjectShape,
  docs: DocFile[],
  _root: string,
): IngestionPlan {
  // Priority: README, CONTRIBUTING, then other docs
  const priorityOrder: Record<DocFile["kind"], number> = {
    readme: 0,
    contributing: 1,
    changelog: 2,
    license: 3,
    docs: 4,
    config: 5,
    other: 6,
  };

  const priorityFiles = [...docs]
    .filter((d) => d.size > 0)
    .sort((a, b) => priorityOrder[a.kind] - priorityOrder[b.kind]);

  // Recommended categories based on project shape
  const categories: string[] = ["fact", "preference", "decision", "principle"];
  if (shape === "monorepo" || shape === "workspace") {
    categories.push("entity");
  }

  // Namespace suggestion from primary language
  const suggestedNamespace = languages.length > 0
    ? languages[0].language.toLowerCase()
    : "project";

  return {
    priorityFiles,
    estimatedFiles: docs.filter((d) => d.size > 0).length,
    categories,
    suggestedNamespace,
  };
}

// ── Helpers ───────────────────────────────────────────────────────────────────

function readJsonSafe(filePath: string): Record<string, unknown> | null {
  try {
    return JSON.parse(fs.readFileSync(filePath, "utf8"));
  } catch {
    return null;
  }
}

function readTomlWorkspace(filePath: string): boolean {
  try {
    const content = fs.readFileSync(filePath, "utf8");
    return content.includes("[workspace]");
  } catch {
    return false;
  }
}

/**
 * @remnic/core — Workspace Tree Projection
 *
 * Generates a human-readable `.engram/context-tree/` from canonical memory.
 * Each node is a `.md` file with rich metadata, * (provenance, trust, confidence, source anchors).
 * Manual edits are preserved in fenced blocks.
 */

import fs from "node:fs";
import path from "node:path";
import { getCategoryDir, ALL_CATEGORY_KEYS } from "../utils/category-dir.js";

const VALID_PROJECTION_CATEGORIES = new Set(ALL_CATEGORY_KEYS);

// ── Types ────────────────────────────────────────────────────────────────────

export interface TreeNode {
  /** Relative path from context-tree root, e.g. "entities/claude.md" */
  path: string;
  /** Category from canonical memory */
  category: string;
  /** Human-readable title */
  title: string;
  /** File content (rendered markdown) */
  content: string;
  /** Source memory IDs that contributed to this node */
  sourceAnchors: string[];
  /** Confidence (0-1) */
  confidence: number;
  /** Trust zone classification */
  confidenceTier: string;
  /** When this node was generated */
  generatedAt: string;
  /** Provenance chain */
  provenance: ProvenanceEntry[];
}

export interface ProvenanceEntry {
  memoryId: string;
  source: string;
  extracted: string;
}

export interface GenerateOptions {
  /** Memory root directory (e.g. ~/.openclaw/workspace/memory/local) */
  memoryDir: string;
  /** Output directory (e.g. .engram/context-tree) */
  outputDir: string;
  /** Categories to include (default: all) */
  categories?: string[];
  /** Whether to include entity graph */
  includeEntities?: boolean;
  /** Whether to include orphaned questions */
  includeQuestions?: boolean;
  /** Max nodes per category (default: unlimited) */
  maxPerCategory?: number;
  /** Whether to watch for changes and regenerate incrementally */
  watch?: boolean;
}

export interface GenerateResult {
  nodesGenerated: number;
  nodesSkipped: number;
  categories: Record<string, number>;
  durationMs: number;
  outputDir: string;
}

// ── Generation ──────────────────────────────────────────────────────────────

/**
 * Generate a context tree from canonical memory.
 *
 * Reads memory `.md` files from the source directory, * and projects them into a clean, * human-readable tree structure at `outputDir`.
 */
export async function generateContextTree(options: GenerateOptions): Promise<GenerateResult> {
  const startTime = Date.now();
  const {
    memoryDir,
    outputDir,
    categories: filterCategories,
    includeEntities = true,
    includeQuestions = true,
    maxPerCategory = Infinity,
  } = options;

  let nodesGenerated = 0;
  let nodesSkipped = 0;
  const categoryCounts: Record<string, number> = {};
  const resolvedMemoryDir = path.resolve(memoryDir);
  const resolvedOutputDir = path.resolve(outputDir);
  const requestedCategories = validateProjectionCategories(filterCategories);
  const realMemoryDir = assertSafeMemoryRoot(resolvedMemoryDir);

  // Ensure output directory exists
  assertNotSymlink(resolvedOutputDir, "context tree outputDir");
  fs.mkdirSync(resolvedOutputDir, { recursive: true });
  const realOutputDir = fs.realpathSync(resolvedOutputDir);

  // Process each category (exclude 'question' — handled by separate includeQuestions pass)
  const allCategories = (requestedCategories ?? ALL_CATEGORY_KEYS)
    .filter((c) => c !== "question");

  for (const category of allCategories) {
    const categoryDir = getCategoryDir(memoryDir, category);
    if (!fs.existsSync(categoryDir)) continue;
    assertSafeInputRoot(realMemoryDir, categoryDir, `${category} memory category`);

    categoryCounts[category] = 0;
    const files = walkR(categoryDir, realMemoryDir);
    let count = 0;

    for (const filePath of files) {
      if (count >= maxPerCategory) {
        nodesSkipped++;
        continue;
      }

      const content = fs.readFileSync(filePath, "utf8");
      const fm = parseFrontmatter(content);
      if (!fm) {
        nodesSkipped++;
        continue;
      }

      const node = projectNode(filePath, category, fm, content);
      if (!node) {
        nodesSkipped++;
        continue;
      }

      // Write node to output
      const outputPath = resolveContainedOutputPath(realOutputDir, node.path);
      writeProjectedContent(realOutputDir, outputPath, node.content);

      nodesGenerated++;
      categoryCounts[category] = (categoryCounts[category] ?? 0) + 1;
      count++;
    }
  }

  // Process entities
  if (includeEntities) {
    const entitiesDir = path.join(memoryDir, "entities");
    if (fs.existsSync(entitiesDir)) {
      assertSafeInputRoot(realMemoryDir, entitiesDir, "entities root");
      categoryCounts["entity"] = 0;
      const entityFiles = walkR(entitiesDir, realMemoryDir);
      let count = 0;

      for (const filePath of entityFiles) {
        if (count >= maxPerCategory) {
          nodesSkipped++;
          continue;
        }

        const content = fs.readFileSync(filePath, "utf8");
        const fileName = path.basename(filePath, ".md");
        const node = projectEntityNode(fileName, content);

        const outputPath = resolveContainedOutputPath(realOutputDir, "entities", `${fileName}.md`);
        writeProjectedContent(realOutputDir, outputPath, node.content);

        nodesGenerated++;
        categoryCounts["entity"] = (categoryCounts["entity"] ?? 0) + 1;
        count++;
      }
    }
  }

  // Process questions
  const shouldIncludeQuestions =
    includeQuestions &&
    (requestedCategories === undefined || requestedCategories.includes("question"));
  if (shouldIncludeQuestions) {
    const questionsDir = path.join(memoryDir, "questions");
    if (fs.existsSync(questionsDir)) {
      assertSafeInputRoot(realMemoryDir, questionsDir, "questions root");
      categoryCounts["question"] = 0;
      const qFiles = walkR(questionsDir, realMemoryDir);
      let count = 0;

      for (const filePath of qFiles) {
        if (count >= maxPerCategory) {
          nodesSkipped++;
          continue;
        }

        const content = fs.readFileSync(filePath, "utf8");
        const fm = parseFrontmatter(content);
        if (!fm) {
          nodesSkipped++;
          continue;
        }

        const node = projectNode(filePath, "question", fm, content);
        if (!node) {
          nodesSkipped++;
          continue;
        }

        const outputPath = resolveContainedOutputPath(realOutputDir, node.path);
        writeProjectedContent(realOutputDir, outputPath, node.content);

        nodesGenerated++;
        categoryCounts["question"] = (categoryCounts["question"] ?? 0) + 1;
        count++;
      }
    }
  }

  // Write index
  const index = generateIndex(categoryCounts, resolvedOutputDir);
  writeProjectedContent(realOutputDir, resolveContainedOutputPath(realOutputDir, "INDEX.md"), index);

  return {
    nodesGenerated,
    nodesSkipped,
    categories: categoryCounts,
    durationMs: Date.now() - startTime,
    outputDir,
  };
}

// ── Helpers ──────────────────────────────────────────────────────────────────

function isPathInside(root: string, candidate: string): boolean {
  const relative = path.relative(root, candidate);
  return relative === "" || (!relative.startsWith("..") && !path.isAbsolute(relative));
}

function assertNotSymlink(targetPath: string, label: string): void {
  try {
    if (fs.lstatSync(targetPath).isSymbolicLink()) {
      throw new Error(`${label} must not be a symlink: ${targetPath}`);
    }
  } catch (err) {
    if ((err as NodeJS.ErrnoException).code === "ENOENT") return;
    throw err;
  }
}

function assertSafeMemoryRoot(targetPath: string): string {
  const stat = fs.lstatSync(targetPath);
  if (stat.isSymbolicLink()) {
    throw new Error(`memoryDir must not be a symlink: ${targetPath}`);
  }
  if (!stat.isDirectory()) {
    throw new Error(`memoryDir must be a directory: ${targetPath}`);
  }
  return fs.realpathSync(targetPath);
}

function assertSafeInputRoot(realMemoryDir: string, targetPath: string, label: string): void {
  const stat = fs.lstatSync(targetPath);
  if (stat.isSymbolicLink()) {
    throw new Error(`${label} must not be a symlink: ${targetPath}`);
  }
  if (!stat.isDirectory()) {
    throw new Error(`${label} must be a directory: ${targetPath}`);
  }
  const realTarget = fs.realpathSync(targetPath);
  if (!isPathInside(realMemoryDir, realTarget)) {
    throw new Error(`${label} escapes memoryDir: ${targetPath}`);
  }
}

function assertSafeOutputTarget(realOutputDir: string, outputPath: string): void {
  let current = realOutputDir;
  const relative = path.relative(realOutputDir, outputPath);
  if (relative.startsWith("..") || path.isAbsolute(relative)) {
    throw new Error(`context tree output path escapes outputDir: ${outputPath}`);
  }
  for (const segment of relative.split(path.sep).filter(Boolean)) {
    current = path.join(current, segment);
    try {
      const stat = fs.lstatSync(current);
      if (stat.isSymbolicLink()) {
        throw new Error(`context tree output path contains symlink: ${current}`);
      }
    } catch (err) {
      if ((err as NodeJS.ErrnoException).code === "ENOENT") {
        break;
      }
      throw err;
    }
  }
}

function validateProjectionCategories(categories: string[] | undefined): string[] | undefined {
  if (categories === undefined) {
    return undefined;
  }
  const validated: string[] = [];
  for (const category of categories) {
    if (typeof category !== "string" || !VALID_PROJECTION_CATEGORIES.has(category)) {
      throw new Error(`invalid context tree category: ${String(category)}`);
    }
    if (!validated.includes(category)) {
      validated.push(category);
    }
  }
  return validated;
}

function resolveContainedOutputPath(outputRoot: string, ...segments: string[]): string {
  const resolved = path.resolve(outputRoot, ...segments);
  const relative = path.relative(outputRoot, resolved);
  if (relative === "" || (!relative.startsWith("..") && !path.isAbsolute(relative))) {
    return resolved;
  }
  throw new Error(`context tree output path escapes outputDir: ${segments.join("/")}`);
}

function writeProjectedContent(realOutputDir: string, outputPath: string, generatedContent: string): void {
  assertSafeOutputTarget(realOutputDir, outputPath);
  fs.mkdirSync(path.dirname(outputPath), { recursive: true });
  const realParent = fs.realpathSync(path.dirname(outputPath));
  if (!isPathInside(realOutputDir, realParent)) {
    throw new Error(`context tree output path escapes outputDir: ${outputPath}`);
  }
  const existingContent = fs.existsSync(outputPath)
    ? fs.readFileSync(outputPath, "utf8")
    : "";
  fs.writeFileSync(
    outputPath,
    preserveManualFencedBlocks(generatedContent, existingContent),
  );
}

function preserveManualFencedBlocks(
  generatedContent: string,
  existingContent: string,
): string {
  const manualBlocks = extractManualFencedBlocks(existingContent)
    .filter((block) => !generatedContent.includes(block));
  if (manualBlocks.length === 0) {
    return generatedContent;
  }
  return `${generatedContent.trimEnd()}\n\n## Manual Edits\n\n${manualBlocks.join("\n\n")}\n`;
}

function extractManualFencedBlocks(content: string): string[] {
  const blocks: string[] = [];
  const seen = new Set<string>();
  const fencePattern = /(?:^|\n)([`~]{3,})[^\n]*\bmanual\b[^\n]*\n[\s\S]*?\n\1[ \t]*(?=\n|$)/gi;
  for (const match of content.matchAll(fencePattern)) {
    const block = match[0].trim();
    if (!seen.has(block)) {
      seen.add(block);
      blocks.push(block);
    }
  }
  return blocks;
}

function walkR(dir: string, realMemoryDir: string): string[] {
  const results: string[] = [];
  function walk(directory: string): void {
    for (const entry of fs.readdirSync(directory, { withFileTypes: true })) {
    const fullPath = path.join(directory, entry.name);
    if (entry.isSymbolicLink()) {
      throw new Error(`context tree input path contains symlink: ${fullPath}`);
    }
    if (entry.isDirectory()) {
      const realDir = fs.realpathSync(fullPath);
      if (!isPathInside(realMemoryDir, realDir)) {
        throw new Error(`context tree input path escapes memoryDir: ${fullPath}`);
      }
      walk(fullPath);
    } else if (entry.name.endsWith(".md")) {
      const realFile = fs.realpathSync(fullPath);
      if (!isPathInside(realMemoryDir, realFile)) {
        throw new Error(`context tree input path escapes memoryDir: ${fullPath}`);
      }
      results.push(fullPath);
    }
  }
  }
  walk(dir);
  return results;
}

interface Frontmatter {
  id: string;
  category: string;
  created: string;
  updated: string;
  confidence: number;
  confidenceTier: string;
  tags: string[];
  source: string;
  entityRef?: string;
  lifecycleState?: string;
}

function parseFrontmatter(content: string): Frontmatter | null {
  const match = content.match(/^---\n([\s\S]*?)\n---/);
  if (!match) return null;

  const fmText = match[1];
  const fm: Record<string, unknown> = {};
  for (const line of fmText.split("\n")) {
    const colonIdx = line.indexOf(":");
    if (colonIdx === -1) continue;
    const key = line.slice(0, colonIdx).trim();
    const value = line.slice(colonIdx + 1).trim();
    if (key === "tags") {
      try {
        fm[key] = JSON.parse(value) as string[];
      } catch {
        fm[key] = [] as string[];
      }
    } else if (key === "confidence") {
      const parsed = parseFloat(value);
      fm[key] = Number.isFinite(parsed) ? parsed : 0;
    } else {
      fm[key] = value;
    }
  }
  return fm as unknown as Frontmatter;
}

function extractBody(content: string): string {
  const match = content.match(/^---\n[\s\S]*?\n---\n([\s\S]*)/);
  return match ? match[1].trim() : content.trim();
}

function projectNode(
  filePath: string,
  category: string,
  fm: Frontmatter,
  rawContent: string,
): TreeNode | null {
  const body = extractBody(rawContent);
  const fileName = path.basename(filePath, ".md");
  const dateDir = path.basename(path.dirname(filePath));

  // Build relative path: category/date/file or just category/file
  let relPath: string;
  if (/^\d{4}-\d{2}-\d{2}$/.test(dateDir)) {
    relPath = path.join(category, dateDir, `${fileName}.md`);
  } else {
    relPath = path.join(category, `${fileName}.md`);
  }

  const generatedAt = new Date().toISOString();

  const md = `# ${fm.id}

> **Category:** ${fm.category}
> **Created:** ${fm.created}
> **Updated:** ${fm.updated ?? fm.created}
> **Confidence:** ${fm.confidence} (${fm.confidenceTier}${fm.lifecycleState ? `, ${fm.lifecycleState}` : ""})
${fm.tags?.length ? `\n> **Tags:** ${fm.tags.join(", ")}` : ""}
${fm.entityRef ? `\n> **Entity:** ${fm.entityRef}` : ""}
> **Source:** ${fm.source ?? "unknown"}
> **Projected:** ${generatedAt}

---

${body}
`;

  return {
    path: relPath,
    category,
    title: fm.id,
    content: md,
    sourceAnchors: [fm.id],
    confidence: fm.confidence ?? 0,
    confidenceTier: fm.confidenceTier ?? "unknown",
    generatedAt,
    provenance: [{
      memoryId: fm.id,
      source: fm.source ?? "unknown",
      extracted: fm.created,
    }],
  };
}

function projectEntityNode(fileName: string, content: string): TreeNode {
  const generatedAt = new Date().toISOString();

  const md = `> **Projected:** ${generatedAt}
> **Source:** canonical

---

${content}
`;

  return {
    path: path.join("entities", `${fileName}.md`),
    category: "entity",
    title: fileName,
    content: md,
    sourceAnchors: [fileName],
    confidence: 1,
    confidenceTier: "explicit",
    generatedAt,
    provenance: [{
      memoryId: fileName,
      source: "canonical",
      extracted: generatedAt,
    }],
  };
}

function generateIndex(
  categoryCounts: Record<string, number>,
  outputDir: string,
): string {
  const lines = [
    "# Context Tree Index",
    "",
    `Generated: ${new Date().toISOString()}`,
    "",
    "## Summary",
    "",
    `| Category | Count |`,
    `|----------|-------|`,
  ];

  let total = 0;
  for (const [cat, count] of Object.entries(categoryCounts).sort()) {
    lines.push(`| ${cat} | ${count} |`);
    total += count;
  }

  lines.push("");
  lines.push(`**Total:** ${total} nodes`);
  lines.push("");
  lines.push("## Structure");
  lines.push("");
  lines.push("```");
  lines.push("context-tree/");
  lines.push("├── entities/       # Entity knowledge graph");
  lines.push("├── fact/           # Factual memories (date-partitioned)");
  lines.push("├── correction/    # Correction memories");
  lines.push("├── decision/      # Decisions");
  lines.push("├── moment/        # Notable moments");
  lines.push("├── preference/    # Preferences");
  lines.push("├── principle/     # Principles");
  lines.push("├── question/      # Open questions");
  lines.push("└── INDEX.md        # This file");
  lines.push("```");

  return lines.join("\n") + "\n";
}

import { createHash } from "node:crypto";
import { parseFrontmatterFields } from "./frontmatter.js";

export type ReviewDeckChoice = "keep" | "prepare_fix" | "not_true";
export type ReviewDeckRisk = "reversible";

export interface ReviewDeckEvidence {
  sourceMemoryId?: string;
  sourceDate?: string;
  excerpt?: string;
  relation: "supports" | "conflicts" | "origin";
}

export interface ReviewDeckItem {
  schemaVersion: 1;
  itemId: string;
  source: "review";
  sourceId: string;
  memoryId?: string;
  content: string;
  category?: string;
  lifecycleState?: string;
  confidence?: number;
  confidenceTier?: string;
  reviewReason: string;
  reviewReasonLabel: string;
  supportCount: number;
  provenance: readonly ReviewDeckEvidence[];
  allowedChoices: readonly ReviewDeckChoice[];
  choiceRisk: Readonly<Record<ReviewDeckChoice, ReviewDeckRisk | "unavailable">>;
  namespace: string;
  revision: string;
}

export interface ReviewDeckPage {
  schemaVersion: 1;
  items: readonly ReviewDeckItem[];
  nextCursor?: string;
  total: number;
}

export type ReviewDeckActionRequest =
  | { schemaVersion: 1; itemId: string; revision: string; action: "keep" | "not_true"; idempotencyKey: string }
  | { schemaVersion: 1; itemId: string; revision: string; action: "prepare_fix"; correctionText: string; idempotencyKey: string };

export interface ReviewDeckActionReceipt {
  schemaVersion: 1;
  receiptId: string;
  itemId: string;
  action: "keep" | "not_true" | "prepare_fix" | "undo";
  outcome: "planned" | "applied" | "conflict" | "failed";
  effect: string;
  undoAvailable: boolean;
  appliedRevision?: string;
  correctionPlanId?: string;
  correctionPreview?: unknown;
}

export interface ReviewDeckUndoRequest {
  schemaVersion: 1;
  receiptId: string;
  expectedRevision: string;
  idempotencyKey: string;
}

export interface ReviewDeckSourceRow {
  itemId: string;
  filePath: string;
  fileContent: string;
  revision: string;
  content: string;
  category?: string;
  confidence?: number;
  confidenceTier?: string;
  reviewReason: string;
  created: string;
  source?: string;
  blockedBy?: string;
  lifecycleState?: string;
  context?: string;
}

export interface ReviewDeckSnapshot {
  corpusVersion: string;
  total: number;
  rows: readonly ReviewDeckSourceRow[];
}

export interface ReviewDeckCursorScope {
  principalDigest: string;
  namespace: string;
  filterDigest: string;
  corpusVersion: string;
}

export class ReviewDeckCursorError extends Error {
  constructor(message = "Invalid review deck cursor") {
    super(message);
    this.name = "ReviewDeckCursorError";
  }
}

const ALLOWED_CHOICES = ["keep", "prepare_fix", "not_true"] as const satisfies readonly ReviewDeckChoice[];
const REVERSIBLE_RISK = {
  keep: "reversible",
  prepare_fix: "reversible",
  not_true: "reversible",
} as const satisfies Record<ReviewDeckChoice, ReviewDeckRisk>;

const REVIEW_REASON_LABELS: Record<string, string> = {
  low_confidence: "Low confidence",
  suggestion: "Suggested memory",
  tombstone_blocked: "Blocked by a deletion",
  contradiction: "Conflicts with another memory",
  duplicate: "Possible duplicate",
};

const EXCERPT_LIMIT = 240;

export function computeReviewItemRevision(fileContent: string): string {
  return `rv1:${createHash("sha256").update(fileContent).digest("hex")}`;
}

export function projectReviewDeckItem(row: ReviewDeckSourceRow, namespace: string): ReviewDeckItem {
  const provenance = provenanceFromRow(row);
  return {
    schemaVersion: 1,
    itemId: row.itemId,
    source: "review",
    sourceId: row.itemId,
    memoryId: row.itemId,
    content: row.content,
    ...(row.category !== undefined ? { category: row.category } : {}),
    ...(row.lifecycleState !== undefined ? { lifecycleState: row.lifecycleState } : {}),
    ...(row.confidence !== undefined ? { confidence: row.confidence } : {}),
    ...(row.confidenceTier !== undefined ? { confidenceTier: row.confidenceTier } : {}),
    reviewReason: row.reviewReason,
    reviewReasonLabel: reviewReasonLabel(row.reviewReason),
    supportCount: provenance.filter((entry) => entry.relation === "supports").length,
    provenance,
    allowedChoices: ALLOWED_CHOICES,
    choiceRisk: REVERSIBLE_RISK,
    namespace,
    revision: row.revision,
  };
}

export function compareReviewDeckRows(a: ReviewDeckSourceRow, b: ReviewDeckSourceRow): number {
  const aBlocked = a.blockedBy && a.blockedBy.length > 0 ? 0 : 1;
  const bBlocked = b.blockedBy && b.blockedBy.length > 0 ? 0 : 1;
  if (aBlocked !== bBlocked) return aBlocked - bBlocked;
  const aConfidence = a.confidence ?? 0.5;
  const bConfidence = b.confidence ?? 0.5;
  if (aConfidence !== bConfidence) return aConfidence < bConfidence ? -1 : 1;
  if (a.created !== b.created) return a.created < b.created ? -1 : 1;
  if (a.itemId !== b.itemId) return a.itemId < b.itemId ? -1 : 1;
  return 0;
}

export function encodeReviewDeckCursor(scope: ReviewDeckCursorScope, lastSortKey: string): string {
  return Buffer.from(
    JSON.stringify({
      v: 1,
      p: scope.principalDigest,
      n: scope.namespace,
      f: scope.filterDigest,
      c: scope.corpusVersion,
      k: lastSortKey,
    }),
    "utf8",
  ).toString("base64url");
}

export function decodeReviewDeckCursor(cursor: string, scope: ReviewDeckCursorScope): string {
  const payload = parseCursorPayload(cursor);
  if (
    payload.p !== scope.principalDigest
    || payload.n !== scope.namespace
    || payload.f !== scope.filterDigest
    || payload.c !== scope.corpusVersion
  ) {
    throw new ReviewDeckCursorError("Review deck cursor scope mismatch");
  }
  return payload.k;
}

export function buildReviewDeckPage(
  rows: readonly ReviewDeckSourceRow[],
  opts: { scope: ReviewDeckCursorScope; cursor?: string; limit: number },
): ReviewDeckPage {
  const sorted = [...rows].sort(compareReviewDeckRows);
  const limit = Math.max(0, opts.limit);
  let start = 0;
  if (opts.cursor !== undefined) {
    const lastSortKey = decodeReviewDeckCursor(opts.cursor, opts.scope);
    start = sorted.findIndex((row) => reviewDeckSortKey(row) > lastSortKey);
    if (start < 0) start = sorted.length;
  }
  const pageRows = limit === 0 ? [] : sorted.slice(start, start + limit);
  const items = pageRows.map((row) => projectReviewDeckItem(row, opts.scope.namespace));
  const consumed = start + pageRows.length;
  const nextCursor =
    pageRows.length > 0 && consumed < sorted.length
      ? encodeReviewDeckCursor(opts.scope, reviewDeckSortKey(pageRows[pageRows.length - 1]))
      : undefined;
  return {
    schemaVersion: 1,
    items,
    total: sorted.length,
    ...(nextCursor !== undefined ? { nextCursor } : {}),
  };
}

function reviewDeckSortKey(row: ReviewDeckSourceRow): string {
  const blocked = row.blockedBy && row.blockedBy.length > 0 ? "0" : "1";
  return `${blocked}\t${(row.confidence ?? 0.5).toFixed(6)}\t${row.created}\t${row.itemId}`;
}

function reviewReasonLabel(reason: string): string {
  const known = REVIEW_REASON_LABELS[reason];
  if (known) return known;
  const words = reason.split("_").filter((part) => part.length > 0);
  if (words.length === 0) return "Review";
  return words
    .map((word) => word.charAt(0).toUpperCase() + word.slice(1).toLowerCase())
    .join(" ");
}

function provenanceFromRow(row: ReviewDeckSourceRow): ReviewDeckEvidence[] {
  const fm = parseFrontmatterFields(row.fileContent);
  const source = nonempty(row.source) ?? nonempty(fm.source);
  const context = nonempty(row.context) ?? nonempty(fm.context);
  const created = nonempty(row.created) ?? nonempty(fm.created);
  const supportIds = idList(fm.supports);
  const conflictIds = [...idList(fm.conflicts), ...idList(fm.contradicts)];
  const relatedIds = idList(fm.relatedMemoryIds);
  const relatedRelation = row.reviewReason === "contradiction" ? "conflicts" : "supports";
  const provenance: ReviewDeckEvidence[] = [];
  if (source !== undefined || context !== undefined) {
    provenance.push({
      relation: "origin",
      ...(created !== undefined ? { sourceDate: created } : {}),
      excerpt: truncateExcerpt(context ?? source ?? ""),
    });
  }
  for (const sourceMemoryId of supportIds) {
    provenance.push({ relation: "supports", sourceMemoryId });
  }
  for (const sourceMemoryId of conflictIds) {
    provenance.push({ relation: "conflicts", sourceMemoryId });
  }
  for (const sourceMemoryId of relatedIds) {
    if (supportIds.includes(sourceMemoryId) || conflictIds.includes(sourceMemoryId)) continue;
    provenance.push({ relation: relatedRelation, sourceMemoryId });
  }
  return provenance;
}


function idList(value: string | undefined): string[] {
  if (value === undefined || value.length === 0) return [];
  return value
    .replace(/^\[|\]$/g, "")
    .split(",")
    .map((part) => part.trim().replace(/^["']|["']$/g, ""))
    .filter((part) => part.length > 0);
}

function nonempty(value: string | undefined): string | undefined {
  if (value === undefined) return undefined;
  return value.trim().length > 0 ? value : undefined;
}

function truncateExcerpt(value: string): string {
  return value.length <= EXCERPT_LIMIT ? value : value.slice(0, EXCERPT_LIMIT);
}

function parseCursorPayload(cursor: string): { v: 1; p: string; n: string; f: string; c: string; k: string } {
  if (cursor.length === 0) throw new ReviewDeckCursorError("Malformed review deck cursor");
  let parsed: unknown;
  try {
    parsed = JSON.parse(Buffer.from(cursor, "base64url").toString("utf8"));
  } catch {
    throw new ReviewDeckCursorError("Malformed review deck cursor");
  }
  if (!parsed || typeof parsed !== "object") throw new ReviewDeckCursorError("Malformed review deck cursor");
  const record = parsed as Record<string, unknown>;
  if (record.v !== 1) throw new ReviewDeckCursorError("Unsupported review deck cursor schema");
  if (
    typeof record.p !== "string"
    || typeof record.n !== "string"
    || typeof record.f !== "string"
    || typeof record.c !== "string"
    || typeof record.k !== "string"
    || record.k.length === 0
  ) {
    throw new ReviewDeckCursorError("Malformed review deck cursor");
  }
  return { v: 1, p: record.p, n: record.n, f: record.f, c: record.c, k: record.k };
}

/**
 * @remnic/core — Review Inbox
 *
 * Manages low-confidence memories and suggestions pending review.
 * Integrates with the existing review-queue system.
 */

import fs from "node:fs";
import path from "node:path";
import { getCategoryDir, ALL_CATEGORY_DIRS } from "../utils/category-dir.js";
import { bumpMemoryCorpusVersionForDir } from "../memory-corpus-version.js";
import {
  HistoricalEntityCanonicalIdCache,
  canonicalizeEntityRefFrontmatter,
  repairContentAfterJournalMoveSync,
} from "../storage/entity-canonical-id-references.js";

// Write-boundary journal cache for review-queue promotions (issue #2213).
const historicalIdCache = new HistoricalEntityCanonicalIdCache();

/**
 * In-place raw rewrite under the uniform write-boundary rule (issue #2213):
 * canonicalize the effective entityRef at the write and REPAIR when the
 * journal moved across it — these rewrites re-serialize whole records, so an
 * unrelated approve/dismiss/flag must not write a legacy ref back out. On
 * repair exhaustion the ORIGINAL bytes are restored before the retryable
 * error propagates: performReview bumps the corpus sentinel only after the
 * action returns, so a half-applied rewrite would be invisible to a warm
 * cache while the caller is told the action failed.
 */
function writeReviewFileCanonicalized(memoryDir: string, filePath: string, content: string): void {
  const stateDir = path.join(memoryDir, "state");
  const idsAtWrite = historicalIdCache.get(stateDir);
  let originalBytes: string | null = null;
  try {
    originalBytes = fs.readFileSync(filePath, "utf8");
  } catch {
    originalBytes = null; // new file — rollback is removal
  }
  const written = canonicalizeEntityRefFrontmatter(content, idsAtWrite);
  fs.writeFileSync(filePath, written, "utf8");
  try {
    repairContentAfterJournalMoveSync({
      stateDir,
      cache: historicalIdCache,
      idsAtWrite,
      rawContent: content,
      lastWritten: written,
      rewrite: (next) => fs.writeFileSync(filePath, next, "utf8"),
    });
  } catch (err) {
    try {
      if (originalBytes === null) {
        fs.unlinkSync(filePath);
      } else {
        fs.writeFileSync(filePath, originalBytes, "utf8");
      }
    } catch {
      // Best effort — the retryable repair error is the primary signal.
    }
    throw err;
  }
}

// ── Types ────────────────────────────────────────────────────────────────────

export interface ReviewItem {
  /** Memory ID */
  id: string;
  /** Content text */
  content: string;
  /** Category */
  category: string;
  /** Confidence score (0-1) */
  confidence: number;
  /** Confidence tier */
  confidenceTier: string;
  /** Source */
  source: string;
  /** File path if available */
  filePath?: string;
  /** Created date */
  created: string;
  /** Reason it's in review */
  reviewReason: "low_confidence" | "suggestion" | "contradiction" | "duplicate" | "tombstone_blocked";
  /** Additional context */
  context?: string;
}

export type ReviewAction = "approve" | "dismiss" | "flag";

export interface ReviewResult {
  /** Item acted upon */
  itemId: string;
  /** Action taken */
  action: ReviewAction;
  /** Updated file path (if modified) */
  updatedPath?: string;
  /** Status message */
  message: string;
  /** Tombstone id cleared by an approve action (for the caller to revoke). */
  clearedTombstoneId?: string;
}

export interface ReviewListResult {
  /** Items pending review */
  items: ReviewItem[];
  /** Total count */
  total: number;
  /** Duration in ms */
  durationMs: number;
}

export interface ReviewOptions {
  /** Memory root directory */
  memoryDir: string;
  /** Filter by reason */
  reason?: ReviewItem["reviewReason"];
  /** Max items to return (default: 50) */
  limit?: number;
  /** Include items with confidence below this threshold (default: 0.7) */
  confidenceThreshold?: number;
}

export interface ReviewActionOptions {
  /** Match the threshold used when listing review items (default: 0.7) */
  confidenceThreshold?: number;
  /**
   * Revocation hook (issue #1579). When approving a memory whose frontmatter
   * carries `blockedBy: <tombstoneId>`, the hook fires so the caller (CLI /
   * orchestrator) can append a `kind: "revocation"` tombstone entry —
   * re-allowing the content. Fire-and-forget: a revocation failure MUST NOT
   * fail the approval (gotcha #13). The hook receives the tombstone id and
   * the memory id.
   */
  onApproveBlockedMemory?: (tombstoneId: string, memoryId: string) => void | Promise<void>;
}

interface ReviewFileMatch {
  filePath: string;
  location: "queue" | "category";
}

const DEFAULT_CONFIDENCE_THRESHOLD = 0.7;

function realMemoryRoot(memoryDir: string): string | null {
  try {
    const stat = fs.lstatSync(memoryDir);
    if (!stat.isDirectory() || stat.isSymbolicLink()) return null;
    return fs.realpathSync(memoryDir);
  } catch {
    return null;
  }
}

function isPathInside(rootReal: string, candidateReal: string): boolean {
  const relative = path.relative(rootReal, candidateReal);
  return relative === "" || (!!relative && !relative.startsWith("..") && !path.isAbsolute(relative));
}

function isSafeDirectory(rootReal: string, dir: string): boolean {
  try {
    const stat = fs.lstatSync(dir);
    if (!stat.isDirectory() || stat.isSymbolicLink()) return false;
    return isPathInside(rootReal, fs.realpathSync(dir));
  } catch {
    return false;
  }
}

function ensureSafeDirectory(rootReal: string, dir: string): void {
  if (fs.existsSync(dir)) {
    if (!isSafeDirectory(rootReal, dir)) {
      throw new Error(`Refusing to write through unsafe review path: ${dir}`);
    }
    return;
  }
  fs.mkdirSync(dir, { recursive: true });
  if (!isSafeDirectory(rootReal, dir)) {
    throw new Error(`Refusing to write through unsafe review path: ${dir}`);
  }
}

// ── Main functions ───────────────────────────────────────────────────────────

/**
 * List items pending review.
 */
export function listReviewItems(options: ReviewOptions): ReviewListResult {
  const startTime = Date.now();
  const {
    memoryDir,
    reason: filterReason,
    limit = 50,
    confidenceThreshold = DEFAULT_CONFIDENCE_THRESHOLD,
  } = options;
  const maxItems = Math.max(0, limit);
  const rootReal = realMemoryRoot(memoryDir);
  if (!rootReal || maxItems === 0) {
    return { items: [], total: 0, durationMs: Date.now() - startTime };
  }

  const items: ReviewItem[] = [];
  const isLimitReached = (): boolean => items.length >= maxItems;
  const addItem = (item: ReviewItem): void => {
    if (isLimitReached()) return;
    if (filterReason && item.reviewReason !== filterReason) return;
    items.push(item);
  };

  // Check suggestions directory
  const suggestionsDir = path.join(memoryDir, "suggestions");
  if (!isLimitReached() && fs.existsSync(suggestionsDir) && isSafeDirectory(rootReal, suggestionsDir)) {
    walkMd(rootReal, suggestionsDir, (filePath, content) => {
      if (isLimitReached()) return true;

      const fm = parseFrontmatter(content);
      const body = extractBody(content);
      if (!fm?.id) return false;

      addItem({
        id: fm.id as string,
        content: body,
        category: (fm.category as string) ?? "suggestion",
        confidence: parseConfidence(fm.confidence, 0.5),
        confidenceTier: (fm.confidenceTier as string) ?? "low",
        source: (fm.source as string) ?? "unknown",
        filePath,
        created: (fm.created as string) ?? new Date().toISOString(),
        reviewReason: "suggestion",
      });
      return isLimitReached();
    });
  }

  // Check review directory
  const reviewDir = path.join(memoryDir, "review");
  if (!isLimitReached() && fs.existsSync(reviewDir) && isSafeDirectory(rootReal, reviewDir)) {
    walkMd(rootReal, reviewDir, (filePath, content) => {
      if (isLimitReached()) return true;

      const fm = parseFrontmatter(content);
      const body = extractBody(content);
      if (!fm?.id) return false;

      addItem({
        id: fm.id as string,
        content: body,
        category: (fm.category as string) ?? "review",
        confidence: parseConfidence(fm.confidence, 0.5),
        confidenceTier: (fm.confidenceTier as string) ?? "low",
        source: (fm.source as string) ?? "unknown",
        filePath,
        created: (fm.created as string) ?? new Date().toISOString(),
        reviewReason: (fm.reviewReason as ReviewItem["reviewReason"]) ?? "low_confidence",
        context: fm.context as string | undefined,
      });
      return isLimitReached();
    });
  }

  // Scan all categories for low-confidence items
  const categories = ALL_CATEGORY_DIRS;
  for (const category of categories) {
    if (isLimitReached()) break;

    const dir = path.join(memoryDir, category);
    if (!fs.existsSync(dir) || !isSafeDirectory(rootReal, dir)) continue;

    walkMd(rootReal, dir, (filePath, content) => {
      if (isLimitReached()) return true;

      const fm = parseFrontmatter(content);
      const body = extractBody(content);
      if (!fm?.id) return false;

      const confidence = parseConfidence(fm.confidence, 1);
      if (confidence >= confidenceThreshold && !(typeof fm.blockedBy === "string" && fm.blockedBy.length > 0)) return false;
      if (parseBoolean(fm.reviewDismissed)) return false;

      // Skip if already in items
      if (items.some((i) => i.id === fm.id)) return false;

      addItem({
        id: fm.id as string,
        content: body,
        category: (fm.category as string) ?? category.slice(0, -1),
        confidence,
        confidenceTier: (fm.confidenceTier as string) ?? "low",
        source: (fm.source as string) ?? "unknown",
        filePath,
        created: (fm.created as string) ?? new Date().toISOString(),
        reviewReason: (typeof fm.blockedBy === "string" && fm.blockedBy.length > 0) ? "tombstone_blocked" : "low_confidence",
      });
      return isLimitReached();
    });
  }

  return {
    items,
    total: items.length,
    durationMs: Date.now() - startTime,
  };
}

/**
 * Perform a review action on an item.
 */
export function performReview(
  memoryDir: string,
  itemId: string,
  action: ReviewAction,
  options: ReviewActionOptions = {},
): ReviewResult {
  const result =
    action === "approve"
      ? approveItem(memoryDir, itemId, options)
      : action === "dismiss"
        ? dismissItem(memoryDir, itemId, options)
        : flagItem(memoryDir, itemId, options);
  // Review approval/dismissal/flagging edits, moves, or removes memory files
  // directly (out-of-band — it does not go through a StorageManager mutation
  // method), so bump the corpus sentinel to force the version-keyed hot cache
  // to rescan on its next read (issue #1902). Only bump when a file was
  // actually modified/moved (updatedPath set) — no-op early returns (item not
  // found, unparsable frontmatter) must not advance the sentinel or needlessly
  // clear caches (Cursor Medium).
  if (result.updatedPath !== undefined) bumpMemoryCorpusVersionForDir(memoryDir);
  return result;
}

// ── Actions ──────────────────────────────────────────────────────────────────

function approveItem(
  memoryDir: string,
  itemId: string,
  options: ReviewActionOptions,
): ReviewResult {
  const rootReal = realMemoryRoot(memoryDir);
  if (!rootReal) return { itemId, action: "approve", message: "Item not found" };
  const found = findReviewFileById(memoryDir, itemId, options);
  if (!found) {
    return { itemId, action: "approve", message: "Item not found" };
  }

  const content = fs.readFileSync(found.filePath, "utf8");
  const fm = parseFrontmatter(content);
  if (!fm) return { itemId, action: "approve", message: "Could not parse frontmatter" };

  // Issue #1579 — approving a tombstone-blocked memory fires the revocation
  // hook so the content is re-allowed (append-only log: a `kind: "revocation"`
  // entry supersedes the tombstone at lookup). Deferred until the approval's
  // writes commit (Codex P2, round 19): revoking before the promote left a
  // failed repair with the non-resurrection guard already destroyed, letting
  // a later extraction resurrect the content. Fire-and-forget once invoked:
  // a hook failure never fails the approval.
  const blockedBy = typeof fm.blockedBy === "string" ? fm.blockedBy : null;
  const fireBlockedRevocation = (): void => {
    if (!blockedBy || !options.onApproveBlockedMemory) return;
    try {
      const maybe = options.onApproveBlockedMemory(blockedBy, itemId);
      if (maybe && typeof (maybe as Promise<void>).then === "function") {
        void (maybe as Promise<void>).catch(() => undefined);
      }
    } catch {
      /* fire-and-forget — never fail the approval (gotcha #13) */
    }
  };

  const updatedContent = updateFrontmatterFields(content, {
    confidence: "0.9",
    confidenceTier: "high",
    reviewDismissed: null,
    // Clear the tombstone-block markers so the promoted memory is active.
    // Clear the tombstone-block markers AND restore active status so the
    // promoted memory is fully active in recall + provenance (issue #1579
    // review: leaving status: pending_review kept it invisible to recall).
    ...(blockedBy ? { blockedBy: null, tombstoneBlockTier: null, status: "active" } : {}),
  });

  if (found.location === "category") {
    writeReviewFileCanonicalized(memoryDir, found.filePath, updatedContent);
    fireBlockedRevocation();
    return {
      itemId,
      action: "approve",
      updatedPath: found.filePath,
      message: "Approved low-confidence memory in place with confidence 0.9",
      ...(blockedBy ? { clearedTombstoneId: blockedBy } : {}),
    };
  }

  // Promote queued suggestions/review items to their category directory.
  const category = (fm.category as string) ?? "fact";
  const targetDir = getCategoryDir(memoryDir, category);
  const dateDir = new Date().toISOString().split("T")[0];
  ensureSafeDirectory(rootReal, targetDir);
  const outputPath = path.join(targetDir, dateDir, path.basename(found.filePath));

  ensureSafeDirectory(rootReal, path.dirname(outputPath));
  // The suggestions/review queue dirs sit OUTSIDE the migration's reference
  // scan, so a queued pre-migration item can still carry a legacy entityRef
  // (issue #2213): promote it canonicalized against the target journal, and
  // REPAIR when the journal moved across the write.
  const reviewStateDir = path.join(memoryDir, "state");
  const idsAtWrite = historicalIdCache.get(reviewStateDir);
  const promotedWritten = canonicalizeEntityRefFrontmatter(updatedContent, idsAtWrite);
  const promotedPath = writeFileWithoutClobber(outputPath, promotedWritten, itemId);
  try {
    repairContentAfterJournalMoveSync({
      stateDir: reviewStateDir,
      cache: historicalIdCache,
      idsAtWrite,
      rawContent: updatedContent,
      lastWritten: promotedWritten,
      rewrite: (next) => fs.writeFileSync(promotedPath, next, "utf8"),
    });
  } catch (err) {
    // Roll back so a retried approve does not clobber-fail against a partial
    // promotion; the queue entry survives untouched (Bugbot).
    try {
      fs.unlinkSync(promotedPath);
    } catch {
      // Best effort — the retryable repair error below is the primary signal.
    }
    throw err;
  }

  // Remove from review, THEN revoke: the guard only falls once the approval
  // has fully committed (promoted file repaired + queue entry gone).
  fs.unlinkSync(found.filePath);
  fireBlockedRevocation();

  return {
    itemId,
    action: "approve",
    updatedPath: promotedPath,
    message: `Promoted to ${category} with confidence 0.9`,
    ...(blockedBy ? { clearedTombstoneId: blockedBy } : {}),
  };
}

function dismissItem(
  memoryDir: string,
  itemId: string,
  options: ReviewActionOptions,
): ReviewResult {
  const found = findReviewFileById(memoryDir, itemId, options);
  if (!found) {
    return { itemId, action: "dismiss", message: "Item not found" };
  }

  if (found.location === "queue") {
    fs.unlinkSync(found.filePath);
    return { itemId, action: "dismiss", message: "Dismissed and removed" };
  }

  const content = fs.readFileSync(found.filePath, "utf8");
  writeReviewFileCanonicalized(
    memoryDir,
    found.filePath,
    updateFrontmatterFields(content, {
      reviewDismissed: "true",
      reviewDismissedAt: new Date().toISOString(),
    }),
  );
  return {
    itemId,
    action: "dismiss",
    updatedPath: found.filePath,
    message: "Dismissed low-confidence memory in place",
  };
}

function flagItem(
  memoryDir: string,
  itemId: string,
  options: ReviewActionOptions,
): ReviewResult {
  const found = findReviewFileById(memoryDir, itemId, options);
  if (!found) {
    return { itemId, action: "flag", message: "Item not found" };
  }

  const content = fs.readFileSync(found.filePath, "utf8");
  const fixed = updateFrontmatterFields(content, {
    flagged: "true",
    flaggedAt: new Date().toISOString(),
  });
  writeReviewFileCanonicalized(memoryDir, found.filePath, fixed);
  return {
    itemId,
    action: "flag",
    updatedPath: found.filePath,
    message: "Flagged for further review",
  };
}

// ── Helpers ───────────────────────────────────────────────────────────────────

function findReviewFileById(
  memoryDir: string,
  id: string,
  options: ReviewActionOptions = {},
): ReviewFileMatch | null {
  const rootReal = realMemoryRoot(memoryDir);
  if (!rootReal) return null;
  for (const loc of ["suggestions", "review"]) {
    const dir = path.join(memoryDir, loc);
    if (!fs.existsSync(dir) || !isSafeDirectory(rootReal, dir)) continue;

    const found = findFileById(rootReal, dir, id);
    if (found) return { filePath: found, location: "queue" };
  }

  for (const category of ALL_CATEGORY_DIRS) {
    const dir = path.join(memoryDir, category);
    if (!fs.existsSync(dir) || !isSafeDirectory(rootReal, dir)) continue;

    const found = findFileById(rootReal, dir, id, (fm) => isLowConfidenceReviewCandidate(fm, options));
    if (found) return { filePath: found, location: "category" };
  }

  return null;
}

function findFileById(
  rootReal: string,
  dir: string,
  id: string,
  include?: (frontmatter: Record<string, unknown>) => boolean,
): string | null {
  const files = walkMdPaths(rootReal, dir);
  for (const filePath of files) {
    const content = readFileSafe(filePath);
    if (!content) continue;
    const fm = parseFrontmatter(content);
    if (fm?.id === id && (!include || include(fm))) return filePath;
  }
  return null;
}

function isLowConfidenceReviewCandidate(
  fm: Record<string, unknown>,
  options: ReviewActionOptions,
): boolean {
  const threshold = options.confidenceThreshold ?? DEFAULT_CONFIDENCE_THRESHOLD;
  // Issue #1579: tombstone-blocked facts are ALWAYS review candidates,
  // regardless of confidence. The block sets status: pending_review +
  // blockedBy; these must be visible in the review queue so an operator
  // can approve (revoke the tombstone) or dismiss them. Without this, a
  // high-confidence blocked fact is visible on disk but absent from the
  // review UI — a silent drop, which violates the non-resurrection design
  // (rule 34: visible, not silent).
  if (typeof fm.blockedBy === "string" && fm.blockedBy.length > 0) {
    return !parseBoolean(fm.reviewDismissed);
  }
  return (
    parseConfidence(fm.confidence, 1) < threshold &&
    !parseBoolean(fm.reviewDismissed)
  );
}

function parseBoolean(value: unknown): boolean {
  if (typeof value === "boolean") return value;
  if (typeof value !== "string") return false;
  const normalized = value.trim().toLowerCase();
  return normalized === "true" || normalized === "1" || normalized === "yes";
}

function parseConfidence(value: unknown, fallback: number): number {
  if (typeof value === "number") return Number.isFinite(value) ? value : fallback;
  if (typeof value === "string") {
    const n = parseFloat(value);
    return Number.isFinite(n) ? n : fallback;
  }
  return fallback;
}

function updateFrontmatterFields(
  content: string,
  fields: Record<string, string | null>,
): string {
  const match = content.match(/^(---\n)([\s\S]*?)(\n---(?:\n|$))/);
  if (!match) return content;

  const seen = new Set<string>();
  const lines = match[2].split("\n");
  const nextLines: string[] = [];
  for (const line of lines) {
    const colonIdx = line.indexOf(":");
    if (colonIdx === -1) {
      nextLines.push(line);
      continue;
    }
    const key = line.slice(0, colonIdx).trim();
    if (!Object.prototype.hasOwnProperty.call(fields, key)) {
      nextLines.push(line);
      continue;
    }
    seen.add(key);
    const value = fields[key];
    if (value !== null) {
      nextLines.push(`${key}: ${value}`);
    }
  }

  for (const [key, value] of Object.entries(fields)) {
    if (value !== null && !seen.has(key)) {
      nextLines.push(`${key}: ${value}`);
    }
  }

  return `${match[1]}${nextLines.join("\n")}${match[3]}${content.slice(match[0].length)}`;
}

function readFileSafe(filePath: string): string | null {
  try {
    return fs.readFileSync(filePath, "utf8");
  } catch {
    return null;
  }
}

function writeFileWithoutClobber(basePath: string, content: string, discriminator: string): string {
  const parsed = path.parse(basePath);
  const safeDiscriminator = sanitizeFilePart(discriminator);

  for (let attempt = 0; attempt < 1000; attempt++) {
    const candidate = attempt === 0
      ? basePath
      : path.join(
        parsed.dir,
        `${parsed.name}-${safeDiscriminator}${attempt === 1 ? "" : `-${attempt}`}${parsed.ext || ".md"}`,
      );

    try {
      fs.writeFileSync(candidate, content, { encoding: "utf8", flag: "wx" });
      return candidate;
    } catch (error) {
      if ((error as NodeJS.ErrnoException).code === "EEXIST") continue;
      throw error;
    }
  }

  throw new Error(`Could not find a free review promotion path for ${basePath}`);
}

function sanitizeFilePart(value: string): string {
  const chars: string[] = [];
  let previousWasDash = false;

  for (const char of value) {
    const next = isSafeFilePartChar(char) ? char : "-";
    if (next === "-" && previousWasDash) continue;
    chars.push(next);
    previousWasDash = next === "-";
    if (chars.length >= 64) break;
  }

  let start = 0;
  let end = chars.length;
  while (start < end && chars[start] === "-") start++;
  while (end > start && chars[end - 1] === "-") end--;

  const sanitized = chars.slice(start, end).join("");
  return sanitized || "review-item";
}

function isSafeFilePartChar(value: string): boolean {
  if (value.length !== 1) return false;
  const code = value.charCodeAt(0);
  return (
    (code >= 48 && code <= 57) ||
    (code >= 65 && code <= 90) ||
    (code >= 97 && code <= 122) ||
    value === "." ||
    value === "_" ||
    value === "-"
  );
}

function parseFrontmatter(content: string): Record<string, unknown> | null {
  const match = content.match(/^---\n([\s\S]*?)\n---/);
  if (!match) return null;

  const fm: Record<string, unknown> = {};
  for (const line of match[1].split("\n")) {
    const colonIdx = line.indexOf(":");
    if (colonIdx === -1) continue;
    const key = line.slice(0, colonIdx).trim();
    const value = line.slice(colonIdx + 1).trim();
    fm[key] = value;
  }
  return fm;
}

function extractBody(content: string): string {
  const match = content.match(/^---\n[\s\S]*?\n---\n([\s\S]*)/);
  return match ? match[1].trim() : content.trim();
}

function walkMd(rootReal: string, dir: string, callback: (filePath: string, content: string) => boolean | void): boolean {
  if (!isSafeDirectory(rootReal, dir)) return false;
  for (const entry of fs.readdirSync(dir, { withFileTypes: true })) {
    const fullPath = path.join(dir, entry.name);
    if (entry.isSymbolicLink()) continue;
    if (entry.isDirectory()) {
      if (walkMd(rootReal, fullPath, callback)) return true;
    } else if (entry.isFile() && entry.name.endsWith(".md")) {
      const content = readFileSafe(fullPath);
      if (content && callback(fullPath, content) === true) return true;
    }
  }
  return false;
}

function walkMdPaths(rootReal: string, dir: string): string[] {
  const results: string[] = [];
  if (!isSafeDirectory(rootReal, dir)) return results;
  for (const entry of fs.readdirSync(dir, { withFileTypes: true })) {
    const fullPath = path.join(dir, entry.name);
    if (entry.isSymbolicLink()) continue;
    if (entry.isDirectory()) {
      results.push(...walkMdPaths(rootReal, fullPath));
    } else if (entry.isFile() && entry.name.endsWith(".md")) {
      results.push(fullPath);
    }
  }
  return results;
}

/**
 * @remnic/core — Diff-Aware Sync
 *
 * Watches source files for changes and triggers re-ingestion
 * only for changed content. Uses file hashing to detect changes.
 */

import fs from "node:fs";
import path from "node:path";
import crypto from "node:crypto";

// ── Types ────────────────────────────────────────────────────────────────────

export interface SyncOptions {
  /** Source directory to watch */
  sourceDir: string;
  /** Memory root directory */
  memoryDir: string;
  /** State file path (stores hashes). Default: memoryDir/.sync-state.json */
  stateFile?: string;
  /** File extensions to watch (default: .md, .txt, .mdx) */
  extensions?: string[];
  /** Directories to exclude */
  excludeDirs?: string[];
  /** Poll interval for watchForChanges. Default: 5000ms */
  pollIntervalMs?: number;
  /** Whether to actually write changes (default: true) */
  dryRun?: boolean;
}

export interface SyncResult {
  /** Files scanned */
  scanned: number;
  /** Files changed since last sync */
  changed: FileChange[];
  /** Files unchanged */
  unchanged: number;
  /** Files deleted since last sync */
  deleted: string[];
  /** Files newly added */
  added: string[];
  /** Duration in ms */
  durationMs: number;
  /** State file path */
  stateFile: string;
}

export interface FileChange {
  /** Absolute file path */
  filePath: string;
  /** Relative path from source root */
  relativePath: string;
  /** Change type */
  type: "added" | "modified" | "deleted";
  /** Current content hash */
  currentHash: string;
  /** Previous content hash (if modified) */
  previousHash?: string;
  /** File size in bytes */
  size: number;
}

export interface SyncState {
  /** Map of relative path → content hash */
  fileHashes: Record<string, string>;
  /** Last sync timestamp */
  lastSyncAt: string;
  /** Version of state format */
  version: number;
}

// ── Constants ────────────────────────────────────────────────────────────────

const DEFAULT_EXTENSIONS = new Set([".md", ".txt", ".mdx", ".rst"]);
const DEFAULT_EXCLUDE = new Set([
  "node_modules",
  ".git",
  "dist",
  "build",
  ".engram",
  "coverage",
]);

// ── Main function ────────────────────────────────────────────────────────────

export function syncChanges(options: SyncOptions): SyncResult {
  const startTime = Date.now();
  const {
    sourceDir,
    memoryDir,
    extensions = [...DEFAULT_EXTENSIONS],
    excludeDirs = [],
    dryRun = false,
  } = options;

  const extSet = new Set(extensions);
  const excludeSet = new Set([...DEFAULT_EXCLUDE, ...excludeDirs]);
  const stateFilePath = options.stateFile ?? path.join(memoryDir, ".sync-state.json");

  // Load previous state
  const prevState = loadState(stateFilePath);

  // Scan current files
  const currentFiles = scanFiles(sourceDir, extSet, excludeSet);

  // Compute diffs
  const changes = computeDiff(currentFiles, prevState.fileHashes, sourceDir);

  const added = changes.filter((c) => c.type === "added").map((c) => c.relativePath);
  const modified = changes.filter((c) => c.type === "modified");
  const deleted = changes
    .filter((c) => c.type === "deleted")
    .map((c) => c.relativePath);

  // Update state (even in dry run, we want to show what would change)
  if (!dryRun) {
    const newState: SyncState = {
      fileHashes: {},
      lastSyncAt: new Date().toISOString(),
      version: 1,
    };

    // Build new state from current files
    for (const [relPath, hash] of Object.entries(currentFiles)) {
      newState.fileHashes[relPath] = hash;
    }

    // Write state
    fs.mkdirSync(path.dirname(stateFilePath), { recursive: true });
    fs.writeFileSync(stateFilePath, JSON.stringify(newState, null, 2));
  }

  return {
    scanned: Object.keys(currentFiles).length,
    changed: changes,
    unchanged:
      Object.keys(currentFiles).length - changes.filter((c) => c.type !== "deleted").length,
    deleted,
    added,
    durationMs: Date.now() - startTime,
    stateFile: stateFilePath,
  };
}

/**
 * Watch for changes and call callback on file changes.
 * Returns a stop function.
 */
export function watchForChanges(
  options: SyncOptions,
  onChange: (changes: FileChange[]) => void | Promise<void>,
): { stop: () => void } {
  const { sourceDir, extensions, excludeDirs } = options;
  const extSet = new Set(extensions ?? DEFAULT_EXTENSIONS);
  const excludeSet = new Set([...DEFAULT_EXCLUDE, ...(excludeDirs ?? [])]);
  const pollIntervalMs =
    typeof options.pollIntervalMs === "number" &&
    Number.isFinite(options.pollIntervalMs) &&
    options.pollIntervalMs > 0
      ? options.pollIntervalMs
      : 5000;

  let lastHashes: Record<string, string> = {};
  let pollInFlight = false;

  // Initial scan
  const currentFiles = scanFiles(sourceDir, extSet, excludeSet);
  lastHashes = { ...currentFiles };

  // Poll interval (FSWatcher doesn't reliably work for all platforms)
  const poll = async (): Promise<void> => {
    if (pollInFlight) return;
    pollInFlight = true;
    try {
      const nowFiles = scanFiles(sourceDir, extSet, excludeSet);
      const changes = computeDiff(nowFiles, lastHashes, sourceDir);

      if (changes.length > 0) {
        await onChange(changes);
        // Update hashes
        for (const change of changes) {
          if (change.type === "deleted") {
            delete lastHashes[change.relativePath];
          } else {
            lastHashes[change.relativePath] = change.currentHash;
          }
        }
      }
    } catch {
      // Leave lastHashes unchanged so the next poll retries the same diff.
    } finally {
      pollInFlight = false;
    }
  };
  const interval = setInterval(() => {
    void poll();
  }, pollIntervalMs);

  return {
    stop: () => clearInterval(interval),
  };
}

// ── File scanning ────────────────────────────────────────────────────────────

function scanFiles(
  root: string,
  extensions: Set<string>,
  exclude: Set<string>,
): Record<string, string> {
  const result: Record<string, string> = {};

  function walk(dir: string, isRoot = false): void {
    let entries: fs.Dirent[];
    try {
      entries = fs.readdirSync(dir, { withFileTypes: true });
    } catch (err) {
      if (isRoot) {
        throw new Error(
          `sync scan failed for ${dir}: ${err instanceof Error ? err.message : String(err)}`,
        );
      }
      return;
    }

    for (const entry of entries) {
      if (exclude.has(entry.name)) continue;

      const fullPath = path.join(dir, entry.name);
      if (entry.isDirectory()) {
        walk(fullPath);
      } else if (entry.isFile()) {
        const ext = path.extname(entry.name).toLowerCase();
        if (!extensions.has(ext)) continue;

        const relPath = path.relative(root, fullPath);
        try {
          const content = fs.readFileSync(fullPath, "utf8");
          result[relPath] = hashContent(content);
        } catch {
          // Can't read — skip
        }
      }
    }
  }

  walk(root, true);
  return result;
}

// ── Diff computation ─────────────────────────────────────────────────────────

function computeDiff(
  current: Record<string, string>,
  previous: Record<string, string>,
  sourceDir: string,
): FileChange[] {
  const changes: FileChange[] = [];

  // Find added and modified
  for (const [relPath, hash] of Object.entries(current)) {
    const fullPath = path.join(sourceDir, relPath);

    if (!(relPath in previous)) {
      // Added
      let size = 0;
      try {
        size = fs.statSync(fullPath).size;
      } catch {
        // ignore
      }
      changes.push({
        filePath: fullPath,
        relativePath: relPath,
        type: "added",
        currentHash: hash,
        size,
      });
    } else if (previous[relPath] !== hash) {
      // Modified
      let size = 0;
      try {
        size = fs.statSync(fullPath).size;
      } catch {
        // ignore
      }
      changes.push({
        filePath: fullPath,
        relativePath: relPath,
        type: "modified",
        currentHash: hash,
        previousHash: previous[relPath],
        size,
      });
    }
  }

  // Find deleted
  for (const relPath of Object.keys(previous)) {
    if (!(relPath in current)) {
      changes.push({
        filePath: path.join(sourceDir, relPath),
        relativePath: relPath,
        type: "deleted",
        currentHash: "",
        size: 0,
      });
    }
  }

  return changes;
}

// ── State management ─────────────────────────────────────────────────────────

function loadState(stateFilePath: string): SyncState {
  try {
    const raw = fs.readFileSync(stateFilePath, "utf8");
    return JSON.parse(raw);
  } catch {
    return {
      fileHashes: {},
      lastSyncAt: new Date(0).toISOString(),
      version: 1,
    };
  }
}

// ── Helpers ───────────────────────────────────────────────────────────────────

function hashContent(content: string): string {
  return crypto.createHash("sha256").update(content).digest("hex").slice(0, 16);
}

import fs from "node:fs";
import path from "node:path";
import { lstat, realpath } from "node:fs/promises";
import {
  drainPendingLifecycleForSyncOrThrow,
  drainPendingLifecycleLedgerForSync,
  type LifecyclePendingIo,
} from "./storage/memory-lifecycle-ledger-access.js";
import { writeFileAtomically } from "./maintenance/atomic-file.js";
import { log } from "./logger.js";
import { isErrnoCode } from "./utils/errno.js";
import { assertPathInsideRoot, pathIsInside } from "./utils/path-containment.js";
import { displayErrorDetail } from "./runtime/better-sqlite.js";
import { getConfiguredNamespaces } from "./scopes/scope-plan.js";
import { isSafeRouteNamespace } from "./routing/engine.js";
import { namespaceIdentityFromToken } from "./namespaces/identity.js";
import type { PluginConfig } from "./types.js";

type PendingImpressionDrain = () => Promise<{ pendingDeferred: boolean }>;

type PendingLifecycleDrain = {
  drainPendingMemoryLifecycleEventsForSync(): Promise<{ folded: boolean; pendingDeferred: boolean }>;
};

type LifecycleDrainAtPath = (
  ledgerPath: string,
) => Promise<{ folded: boolean; pendingDeferred: boolean }>;

type PendingImpressionHost = {
  drainPendingRecallImpressions(): Promise<{ pendingDeferred: boolean }>;
};
/**
 * Fold pending recall-impression spills before building an offline-sync snapshot.
 * A deferred or failed drain must abort the snapshot rather than silently omit
 * durable rows from the sync payload.
 */
export async function drainPendingImpressionsForOfflineSync(
  host: PendingImpressionDrain,
): Promise<void> {
  const maxAttempts = 3;
  let lastError: unknown;
  for (let attempt = 1; attempt <= maxAttempts; attempt++) {
    try {
      const result = await host();
      if (!result.pendingDeferred) return;
      lastError = undefined;
    } catch (error) {
      lastError = error;
    }
  }
  const detail = lastError
    ? `: ${displayErrorDetail(lastError) || "unknown error"}`
    : " (rotation lock held by a peer)";
  throw new Error(
    `offline-sync impression drain could not fold pending recall impressions after ${maxAttempts} attempts${detail}; aborting snapshot so the pending rows are not silently excluded (#2033)`,
  );
}


export async function getOfflineSyncStorage<T extends PendingLifecycleDrain & { dir: string }>(
  orchestrator: PendingImpressionHost & {
    config: { memoryDir: string };
    getStorage(namespace: string): Promise<T>;
    listOfflineSyncNamespaces?(): Promise<string[]>;
  },
  namespace: string,
): Promise<T> {
  const storage = await orchestrator.getStorage(namespace);
  const memoryRoot = path.resolve(orchestrator.config.memoryDir);
  // Recall impressions are global: the orchestrator's single LastRecallStore
  // roots at config.memoryDir, so the active recall_impressions.jsonl lives at
  // <memoryDir>/state/. Fold the global pending queue ONLY when THIS snapshot's
  // root actually contains that active file - a root snapshot. A namespace
  // snapshot (storage.dir under namespaces/<token>/) cannot carry it, so
  // draining there would empty the durable pending queue into a file this
  // snapshot omits and strand the row until a root sync; leave it pending for
  // the root sync instead (#2033).
  const impressionsFile = path.join(memoryRoot, "state", "recall_impressions.jsonl");
  if (pathIsInside(path.resolve(storage.dir), impressionsFile)) {
    await drainPendingImpressionsForOfflineSync(() => orchestrator.drainPendingRecallImpressions());
  }
  await drainPendingLifecycleForSyncOrThrow(() => storage.drainPendingMemoryLifecycleEventsForSync());
  // Root snapshot: buildOfflineSyncSnapshot walks `namespaces/<ns>/state/` for
  // every namespace under the memory root and INCLUDES each namespace's active
  // lifecycle ledger, but the per-namespace pending spill dirs are offline-sync
  // EXCLUDED. Draining only the root ledger above would let a root snapshot omit
  // append-only rows still sitting in a namespace's spill queue, so fold every
  // namespace ledger too - each through its OWN namespace storage so secure-store
  // AAD stays namespace-scoped (#2033, matching the CLI all-ledger drain). A
  // namespace snapshot folds only its own ledger, already done above.
  if (path.resolve(storage.dir) === memoryRoot && orchestrator.listOfflineSyncNamespaces) {
    const drained = new Set<string>([memoryRoot]);
    for (const ns of await orchestrator.listOfflineSyncNamespaces()) {
      // A single unresolvable namespace (e.g. a legacy canonical token dir whose
      // name exceeds the route-namespace length cap) must not abort the whole root
      // snapshot — degrade to draining the rest. listOfflineSyncNamespaces already
      // normalizes token dirs, so this is defense-in-depth.
      let nsStorage: T;
      try {
        nsStorage = await orchestrator.getStorage(ns);
      } catch (err) {
        log.debug(`offline-sync root drain: skipping namespace ${ns} (non-fatal): ${err}`);
        continue;
      }
      const nsDir = path.resolve(nsStorage.dir);
      if (drained.has(nsDir)) continue;
      drained.add(nsDir);
      await drainPendingLifecycleForSyncOrThrow(() => nsStorage.drainPendingMemoryLifecycleEventsForSync());
    }
  }
  return storage;
}

type OfflineSyncNamespaceHost = {
  config: PluginConfig;
  namespaceCatalog: { listNamespaces(): Promise<Array<{ namespace: string }>> };
};

/**
 * Every namespace whose lifecycle ledger a ROOT offline snapshot enumerates.
 * Configured namespaces plus catalog-discovered ones; the catalog is queried
 * best-effort so a catalog read failure still drains the configured set (#2033).
 */
export async function listOfflineSyncNamespaces(host: OfflineSyncNamespaceHost): Promise<string[]> {
  const names = new Set<string>(getConfiguredNamespaces(host.config));
  try {
    for (const ledgerPath of await offlineSyncLifecycleLedgerPaths(host.config.memoryDir)) {
      const namespaceDir = path.dirname(path.dirname(ledgerPath));
      if (path.basename(path.dirname(namespaceDir)) !== "namespaces") continue;
      // A namespace is stored under its canonical token dir `ns-<hex>`. Decode the
      // token back to the namespace NAME so the drain fanout resolves the SAME
      // storage the token dir belongs to (the catalog rebuild scanner decodes the
      // same way, catalog.ts finishRebuild). A raw dir already named as a plain
      // namespace is used verbatim. Skip any name the router would reject — e.g. a
      // canonical token dir whose decoded-or-raw name exceeds isSafeRouteNamespace's
      // 64-char cap — because getStorage() would throw `unsafe namespace` and 500
      // the whole root snapshot-stream (the offline-sync regression this fixes).
      const dirName = path.basename(namespaceDir);
      // namespaceIdentityFromToken returns "" for the ns-default token (the
      // default-namespace identity) — map that to the configured default
      // namespace instead of skipping the directory as an unsafe empty name.
      const decoded = namespaceIdentityFromToken(dirName);
      const name =
        decoded === null
          ? dirName
          : decoded.length > 0
            ? decoded
            : host.config.defaultNamespace;
      if (isSafeRouteNamespace(name)) {
        names.add(name);
      }
    }
  } catch {
    // best-effort: a filesystem scan failure must not block configured/catalog namespaces
  }
  try {
    for (const record of await host.namespaceCatalog.listNamespaces()) {
      names.add(record.namespace);
    }
  } catch {
    // best-effort: fall back to the configured and filesystem namespace sets
  }
  return [...names];
}

/**
 * Resolve the offline-sync storage for a snapshot, folding pending spills first.
 * For a root snapshot this also folds every namespace lifecycle ledger the
 * snapshot will enumerate, so append-only rows in a namespace spill queue are
 * never omitted (#2033).
 */
export function offlineSyncStorageForSnapshot<T extends PendingLifecycleDrain & { dir: string }>(
  host: PendingImpressionHost &
    OfflineSyncNamespaceHost & {
      getStorage(namespace: string): Promise<T>;
    },
  namespace: string,
): Promise<T> {
  return getOfflineSyncStorage(
    {
      config: { memoryDir: host.config.memoryDir },
      drainPendingRecallImpressions: () => host.drainPendingRecallImpressions(),
      getStorage: (ns: string) => host.getStorage(ns),
      listOfflineSyncNamespaces: () => listOfflineSyncNamespaces(host),
    },
    namespace,
  );
}

const LIFECYCLE_LEDGER_FILE = "memory-lifecycle-ledger.jsonl";

/**
 * Plaintext filesystem IO for a standalone (CLI) offline-sync lifecycle drain.
 * A standalone offline cache is plaintext - exactly like its LastRecallStore
 * impression drain - so spills read/append as UTF-8. `writeSecure` keeps the
 * atomic temp+rename the pending contract requires (#2033); a pure drain never
 * spills a new event, but the interface demands an atomic writer.
 */
function plaintextLifecyclePendingIo(): LifecyclePendingIo {
  return {
    writeSecure: async (filePath, payload) => {
      await writeFileAtomically(filePath, payload);
    },
    readSecure: (filePath) => fs.promises.readFile(filePath, "utf8"),
  };
}

/**
 * Lifecycle ledger paths under a standalone memory dir: the root `state/` ledger
 * plus every per-namespace `namespaces/<ns>/state/` ledger (#2033). Offline sync
 * pushes the whole memory dir, so every namespace's ledger can carry pending
 * spills that must be folded first.
 */
async function offlineSyncLifecycleLedgerPaths(memoryDir: string): Promise<string[]> {
  const paths = [path.join(memoryDir, "state", LIFECYCLE_LEDGER_FILE)];
  const namespacesBase = path.join(memoryDir, "namespaces");
  // Symlink/traversal containment (#2033): a symlinked <memoryDir>/namespaces
  // (or a symlinked child) must not redirect the pre-sync drain - and the
  // ledger appends/mkdirs it drives - outside memoryDir. Resolve the memory
  // root and the scan base through realpath, reject a symlinked/escaping/
  // non-directory base, and skip any symlinked/escaping child, mirroring the
  // lifecycle-compaction scanner (orchestration/maintenance.ts) and the
  // memory-store walkers (utils/path-containment). A rejected base is
  // non-fatal: drain the root ledger only, never through the poisoned link.
  let memoryDirReal: string;
  try {
    memoryDirReal = await realpath(memoryDir);
    const baseStat = await lstat(namespacesBase);
    if (baseStat.isSymbolicLink() || !baseStat.isDirectory()) {
      throw new Error("namespaces base is a symlink or not a directory");
    }
    assertPathInsideRoot(memoryDirReal, await realpath(namespacesBase), namespacesBase);
  } catch (err) {
    if (!isErrnoCode(err, "ENOENT")) {
      log.debug(`offline-sync lifecycle drain: namespaces base rejected (non-fatal): ${err}`);
    }
    return paths;
  }
  let entries: fs.Dirent[];
  try {
    entries = fs.readdirSync(namespacesBase, { withFileTypes: true });
  } catch (err) {
    if (!isErrnoCode(err, "ENOENT")) {
      log.debug(`offline-sync lifecycle drain: namespaces dir scan failed (non-fatal): ${err}`);
    }
    return paths;
  }
  for (const entry of entries.sort((a, b) => a.name.localeCompare(b.name))) {
    if (!entry.isDirectory() || entry.isSymbolicLink()) continue;
    const childPath = path.join(namespacesBase, entry.name);
    try {
      assertPathInsideRoot(memoryDirReal, await realpath(childPath), childPath);
    } catch (err) {
      log.debug(`offline-sync lifecycle drain: skipping out-of-root namespace dir ${childPath}: ${err}`);
      continue;
    }
    paths.push(path.join(childPath, "state", LIFECYCLE_LEDGER_FILE));
  }
  return paths;
}

/**
 * Fold pending memory-lifecycle spills into each active ledger under `memoryDir`
 * before a standalone (CLI) offline-sync snapshot (#2033). Mirrors the
 * access-service snapshot entrypoints, which drain lifecycle pending first: the
 * default sync exclude globs keep `memory-lifecycle-ledger.jsonl.pending.d` out
 * of the push, so an append-only row (promotion/import/explicit capture) that
 * spilled while the ledger lock was held would be silently dropped if the local
 * node were discarded before maintenance folds it. A deferred drain (lock held
 * by a peer) or a repeatedly failing fold ABORTS via
 * {@link drainPendingLifecycleForSyncOrThrow} rather than building/pushing a
 * snapshot that omits durable rows. Fast no-op per ledger with no pending dir.
 */
export async function drainPendingLifecycleForOfflineSync(
  memoryDir: string,
  drainAtPath: LifecycleDrainAtPath = (ledgerPath) => {
    const io = plaintextLifecyclePendingIo();
    const stateDir = path.dirname(ledgerPath);
    return drainPendingLifecycleLedgerForSync(
      ledgerPath,
      io,
      (payload) => fs.promises.appendFile(ledgerPath, payload),
      async () => {
        await fs.promises.mkdir(stateDir, { recursive: true });
      },
    );
  },
): Promise<void> {
  for (const ledgerPath of await offlineSyncLifecycleLedgerPaths(memoryDir)) {
    await drainPendingLifecycleForSyncOrThrow(() => drainAtPath(ledgerPath));
  }
}

/**
 * @remnic/core — Curation
 *
 * Deliberate ingestion of files into memory with provenance tracking.
 * Supports statement-level extraction, dedup, and contradiction checks.
 */

import fs from "node:fs";
import path from "node:path";
import crypto from "node:crypto";
import { getCategoryDir, ALL_CATEGORY_DIRS } from "../utils/category-dir.js";
import { bumpMemoryCorpusVersionForDir } from "../memory-corpus-version.js";
import {
  HistoricalEntityCanonicalIdCache,
  canonicalizeEntityRefFrontmatter,
  repairContentAfterJournalMoveSync,
} from "../storage/entity-canonical-id-references.js";

// ── Types ────────────────────────────────────────────────────────────────────

export interface CurateOptions {
  /** File or directory path to curate */
  targetPath: string;
  /** Memory root directory for writing */
  memoryDir: string;
  /** Source label (e.g. "manual", "docs", "onboarding") */
  source?: string;
  /** Category override (default: auto-detect) */
  category?: string;
  /** Confidence to assign (default: 0.9 for curated items) */
  confidence?: number;
  /** Entity reference to attach */
  entityRef?: string;
  /** Tags to add */
  tags?: string[];
  /** Whether to perform dedup check against existing memories */
  checkDuplicates?: boolean;
  /** Whether to detect contradictions */
  checkContradictions?: boolean;
  /** Whether to write files (default: true). False = dry run */
  write?: boolean;
}

export interface CuratedStatement {
  /** Unique ID for this statement */
  id: string;
  /** The extracted statement text */
  content: string;
  /** Category */
  category: string;
  /** Confidence */
  confidence: number;
  /** Provenance info */
  provenance: StatementProvenance;
  /** Hash of content for dedup */
  contentHash: string;
  /** Tags */
  tags: string[];
  /** Entity reference */
  entityRef?: string;
}

export interface StatementProvenance {
  /** Source file path */
  sourcePath: string;
  /** Relative path from project root */
  relativePath: string;
  /** Source label */
  source: string;
  /** Line number if extractable (0 = unknown) */
  lineNumber: number;
  /** Timestamp of ingestion */
  ingestedAt: string;
  /** Hash of the source file for diff tracking */
  sourceFileHash: string;
}

export interface CurateResult {
  /** Statements extracted */
  statements: CuratedStatement[];
  /** Files processed */
  filesProcessed: number;
  /** Files skipped (empty, binary, etc.) */
  filesSkipped: number;
  /** Duplicate statements found (if checkDuplicates) */
  duplicates: DuplicateResult[];
  /** Contradictions found (if checkContradictions) */
  contradictions: ContradictionResult[];
  /** Memory files written */
  written: string[];
  /** Duration in ms */
  durationMs: number;
}

export interface DuplicateResult {
  /** New statement */
  newStatement: CuratedStatement;
  /** Existing memory ID that matches */
  existingId: string;
  /** Similarity score (0-1) */
  similarity: number;
  /** Recommended action */
  action: "skip" | "merge" | "keep";
}

export interface ContradictionResult {
  /** New statement */
  newStatement: CuratedStatement;
  /** Conflicting memory ID */
  conflictingId: string;
  /** The conflicting content */
  conflictingContent: string;
  /** Severity */
  severity: "high" | "medium" | "low";
}

// ── Main function ────────────────────────────────────────────────────────────

export async function curate(options: CurateOptions): Promise<CurateResult> {
  const startTime = Date.now();
  const {
    targetPath,
    memoryDir,
    source = "curation",
    category: categoryOverride,
    confidence = 0.9,
    entityRef,
    tags = [],
    checkDuplicates = true,
    checkContradictions = false,
    write = true,
  } = options;

  const statements: CuratedStatement[] = [];
  const written: string[] = [];
  const duplicates: DuplicateResult[] = [];
  const contradictions: ContradictionResult[] = [];
  let filesProcessed = 0;
  let filesSkipped = 0;

  // Determine targets
  const targets = resolveTargets(targetPath);
  const provenanceRoot = resolveProvenanceRoot(targetPath);

  // Load existing memories for dedup/contradiction checks
  const existingMemories = checkDuplicates || checkContradictions
    ? loadExistingMemories(memoryDir)
    : new Map();

  // Process each file
  for (const filePath of targets) {
    const content = readFileSafe(filePath);
    if (!content) {
      filesSkipped++;
      continue;
    }

    if (isBinary(content)) {
      filesSkipped++;
      continue;
    }

    filesProcessed++;

    const sourceFileHash = hashContent(content);
    const fileStatements = extractStatements(
      content,
      filePath,
      provenanceRoot,
      source,
      sourceFileHash,
      categoryOverride,
      confidence,
      entityRef,
      tags,
    );

    for (const stmt of fileStatements) {
      // Dedup check
      if (checkDuplicates) {
        const dup = findDuplicate(stmt, existingMemories);
        if (dup) {
          duplicates.push(dup);
          if (dup.action === "skip") continue;
        }
      }

      // Contradiction check
      if (checkContradictions) {
        const contra = findContradiction(stmt, existingMemories);
        if (contra) {
          contradictions.push(contra);
        }
      }

      statements.push(stmt);

      // Write to memory
      if (write) {
        const writtenPath = writeStatement(stmt, memoryDir);
        written.push(writtenPath);
        existingMemories.set(stmt.contentHash, {
          id: stmt.id,
          content: stmt.content,
          category: stmt.category,
        });
      }
    }
  }

  // Per-statement corpus bumps happen in writeStatement (below) so a
  // same-process readAllMemories mid-batch never serves a stale/partial corpus
  // (Cursor Medium, #1902); no after-loop bump needed here.

  return {
    statements,
    filesProcessed,
    filesSkipped,
    duplicates,
    contradictions,
    written,
    durationMs: Date.now() - startTime,
  };
}

// ── Target resolution ────────────────────────────────────────────────────────

function resolveTargets(targetPath: string): string[] {
  const stat = fs.statSync(targetPath);
  if (stat.isFile()) return [targetPath];

  // Directory — walk for .md, .txt, .mdx
  const results: string[] = [];
  const extensions = new Set([".md", ".txt", ".mdx", ".rst"]);

  function walk(dir: string): void {
    for (const entry of fs.readdirSync(dir, { withFileTypes: true })) {
      const fullPath = path.join(dir, entry.name);
      if (entry.isDirectory()) {
        if (entry.name !== "node_modules" && entry.name !== ".git") {
          walk(fullPath);
        }
      } else if (extensions.has(path.extname(entry.name).toLowerCase())) {
        results.push(fullPath);
      }
    }
  }

  walk(targetPath);
  return results;
}

function resolveProvenanceRoot(targetPath: string): string {
  const resolvedTarget = path.resolve(targetPath);
  const stat = fs.statSync(resolvedTarget);
  return stat.isFile() ? path.dirname(resolvedTarget) : resolvedTarget;
}

// ── Statement extraction ─────────────────────────────────────────────────────

function extractStatements(
  content: string,
  filePath: string,
  projectRoot: string,
  source: string,
  sourceFileHash: string,
  categoryOverride: string | undefined,
  confidence: number,
  entityRef: string | undefined,
  tags: string[],
): CuratedStatement[] {
  const relativePath = path.relative(projectRoot, path.resolve(filePath)) || path.basename(filePath);
  const statements: CuratedStatement[] = [];
  const now = new Date().toISOString();

  // Split content into paragraphs/lines and extract meaningful statements
  const paragraphs = content
    .split(/\n{2,}/)
    .map((p) => p.trim())
    .filter((p) => p.length > 20 && p.length < 2000);

  // Also extract list items
  const listItems = content
    .split("\n")
    .filter((l) => /^\s*[-*]\s+/.test(l))
    .map((l) => l.replace(/^\s*[-*]\s+/, "").trim())
    .filter((l) => l.length > 10 && l.length < 500);

  const allItems = [...paragraphs, ...listItems];

  // Deduplicate within file
  const seen = new Set<string>();
  for (const item of allItems) {
    const hash = hashContent(item.toLowerCase());
    if (seen.has(hash)) continue;
    seen.add(hash);

    const id = generateId();
    const category = categoryOverride ?? detectCategory(item);

    statements.push({
      id,
      content: item,
      category,
      confidence,
      provenance: {
        sourcePath: filePath,
        relativePath,
        source,
        lineNumber: 0,
        ingestedAt: now,
        sourceFileHash,
      },
      contentHash: hash,
      tags: [...tags],
      entityRef,
    });
  }

  return statements;
}

// ── Category detection ───────────────────────────────────────────────────────

function detectCategory(text: string): string {
  const lower = text.toLowerCase();

  if (/^(always|never|must|should|don't|avoid|ensure)/.test(lower)) return "principle";
  if (/^(we|team|project)\s+(decided|chose|will|use)/.test(lower)) return "decision";
  if (/^(i|we)\s+(prefer|like|want|hate|dislike)/.test(lower)) return "preference";
  if (/fix|bug|issue|broken|error/i.test(lower)) return "correction";
  if (/\?.+$/.test(lower.trim())) return "question";

  return "fact";
}

// ── Dedup ────────────────────────────────────────────────────────────────────

interface ExistingMemory {
  id: string;
  content: string;
  category: string;
}

function findDuplicate(
  stmt: CuratedStatement,
  existing: Map<string, ExistingMemory>,
): DuplicateResult | null {
  const stmtLower = stmt.content.toLowerCase();

  // Exact hash match
  const exactMatch = existing.get(stmt.contentHash);
  if (exactMatch) {
    return {
      newStatement: stmt,
      existingId: exactMatch.id,
      similarity: 1,
      action: "skip",
    };
  }

  // Fuzzy match — check substring containment
  for (const [_, mem] of existing) {
    const memLower = mem.content.toLowerCase();
    if (memLower.length > 50 && stmtLower.length > 50) {
      // Check if one contains the other
      if (memLower.includes(stmtLower.slice(0, 40)) || stmtLower.includes(memLower.slice(0, 40))) {
        return {
          newStatement: stmt,
          existingId: mem.id,
          similarity: 0.85,
          action: "skip",
        };
      }
    }
  }

  return null;
}

// ── Contradiction detection ──────────────────────────────────────────────────

function findContradiction(
  stmt: CuratedStatement,
  existing: Map<string, ExistingMemory>,
): ContradictionResult | null {
  const negationPatterns = [
    /\b(not|don't|doesn't|isn't|aren't|won't|can't|never|no)\b/i,
  ];

  const hasNegation = negationPatterns.some((p) => p.test(stmt.content));
  if (!hasNegation) return null;

  // Strip negation and look for positive version
  const stripped = stmt.content
    .toLowerCase()
    .replace(/\b(not|don't|doesn't|isn't|aren't|won't|can't|never|no)\b/gi, "")
    .trim();

  if (stripped.length < 20) return null;

  for (const [_, mem] of existing) {
    const memLower = mem.content.toLowerCase();
    // If an existing memory affirms what this statement negates
    if (memLower.includes(stripped.slice(0, Math.min(30, stripped.length)))) {
      return {
        newStatement: stmt,
        conflictingId: mem.id,
        conflictingContent: mem.content,
        severity: "high",
      };
    }
  }

  return null;
}

// ── Memory loading ───────────────────────────────────────────────────────────

function loadExistingMemories(memoryDir: string): Map<string, ExistingMemory> {
  const result = new Map<string, ExistingMemory>();
  if (!fs.existsSync(memoryDir)) return result;

  // Walk all known category dirs for existing memories
  const dirs = ALL_CATEGORY_DIRS;
  for (const dir of dirs) {
    const fullDir = path.join(memoryDir, dir);
    if (!fs.existsSync(fullDir)) continue;

    walkFiles(fullDir, (filePath) => {
      const content = readFileSafe(filePath);
      if (!content) return;

      const fm = parseFrontmatter(content);
      const body = extractBody(content);
      if (!fm?.id || !body) return;

      const hash = hashContent(body.toLowerCase());
      result.set(hash, {
        id: fm.id,
        content: body,
        category: fm.category ?? dir.slice(0, -1),
      });
    });
  }

  return result;
}

// ── Writing ──────────────────────────────────────────────────────────────────

// Curation writes raw frontmatter directly, so it is a write boundary for
// entity references too (issue #2213): resolve through the target's journal.
const historicalIdCache = new HistoricalEntityCanonicalIdCache();

function writeStatement(stmt: CuratedStatement, memoryDir: string): string {
  const now = new Date();
  const dateDir = now.toISOString().split("T")[0];
  const categoryDir = getCategoryDir(memoryDir, stmt.category);

  const dir = path.join(categoryDir, dateDir);
  fs.mkdirSync(dir, { recursive: true });

  const fileName = `${stmt.category}-${Date.now()}-${stmt.id.slice(0, 8)}.md`;
  const filePath = path.join(dir, fileName);
  const historicalIds = historicalIdCache.get(path.join(memoryDir, "state"));

  // Keep the caller's ORIGINAL ref in the raw form: repair-after-write must
  // re-resolve from it, including the direction where a mapping was parked
  // and the resolution falls back to the legacy claimant (issue #2213).
  const rawBody = `${[
    "---",
    `id: ${stmt.id}`,
    `category: ${stmt.category}`,
    `created: ${stmt.provenance.ingestedAt}`,
    `updated: ${stmt.provenance.ingestedAt}`,
    `confidence: ${stmt.confidence}`,
    `confidenceTier: ${tierFromConfidence(stmt.confidence)}`,
    `source: ${stmt.provenance.source}`,
    `tags: ${JSON.stringify(stmt.tags)}`,
    stmt.entityRef ? `entityRef: ${stmt.entityRef}` : null,
    `provenanceFile: ${stmt.provenance.relativePath}`,
    `provenanceHash: ${stmt.provenance.sourceFileHash}`,
    "---",
  ]
    .filter(Boolean)
    .join("\n")}\n\n${stmt.content}\n`;
  const body = canonicalizeEntityRefFrontmatter(rawBody, historicalIds);

  fs.writeFileSync(filePath, body);
  // Post-write REPAIR (issue #2213): a peer process publishing the journal
  // across this write would otherwise strand the reference — the corpus bump
  // below no longer re-triggers the migration, and a parked mapping cannot be
  // fixed after the fact by the reconcile pass. On repair exhaustion, remove
  // the just-created file so the retryable error leaves no untracked partial
  // statement (a retry would otherwise duplicate it).
  try {
    repairContentAfterJournalMoveSync({
      stateDir: path.join(memoryDir, "state"),
      cache: historicalIdCache,
      idsAtWrite: historicalIds,
      rawContent: rawBody,
      lastWritten: body,
      rewrite: (next) => fs.writeFileSync(filePath, next),
    });
  } catch (err) {
    try {
      fs.unlinkSync(filePath);
    } catch {
      // Best effort — the retryable repair error is the primary signal.
    }
    throw err;
  }
  // Bump the corpus sentinel per write (out-of-band create) so a concurrent
  // same-process readAllMemories rescans and sees this statement immediately,
  // never a stale/partial corpus mid-batch (Cursor Medium, #1902). AFTER the
  // repair, so a rescan never captures pre-repair bytes.
  bumpMemoryCorpusVersionForDir(memoryDir);
  return filePath;
}

// ── Helpers ───────────────────────────────────────────────────────────────────

function generateId(): string {
  return crypto.randomUUID();
}

function hashContent(content: string): string {
  return crypto.createHash("sha256").update(content).digest("hex").slice(0, 16);
}

function tierFromConfidence(confidence: number): string {
  if (confidence >= 0.95) return "explicit";
  if (confidence >= 0.8) return "high";
  if (confidence >= 0.5) return "medium";
  return "low";
}

function readFileSafe(filePath: string): string | null {
  try {
    return fs.readFileSync(filePath, "utf8");
  } catch {
    return null;
  }
}

function isBinary(content: string): boolean {
  // Simple heuristic: if content has null bytes, it's binary
  for (let i = 0; i < Math.min(content.length, 8000); i++) {
    if (content.charCodeAt(i) === 0) return true;
  }
  return false;
}

interface SimpleFrontmatter {
  id?: string;
  category?: string;
  [key: string]: unknown;
}

function parseFrontmatter(content: string): SimpleFrontmatter | null {
  const match = content.match(/^---\n([\s\S]*?)\n---/);
  if (!match) return null;

  const fm: SimpleFrontmatter = {};
  for (const line of match[1].split("\n")) {
    const colonIdx = line.indexOf(":");
    if (colonIdx === -1) continue;
    const key = line.slice(0, colonIdx).trim();
    const value = line.slice(colonIdx + 1).trim();
    (fm as Record<string, unknown>)[key] = value;
  }
  return fm;
}

function extractBody(content: string): string {
  const match = content.match(/^---\n[\s\S]*?\n---\n([\s\S]*)/);
  return match ? match[1].trim() : content.trim();
}

function walkFiles(dir: string, callback: (filePath: string) => void): void {
  for (const entry of fs.readdirSync(dir, { withFileTypes: true })) {
    const fullPath = path.join(dir, entry.name);
    if (entry.isDirectory()) {
      walkFiles(fullPath, callback);
    } else if (entry.name.endsWith(".md")) {
      callback(fullPath);
    }
  }
}

import fs from "node:fs";
import path from "node:path";
import { MEMORY_CORPUS_VERSION_SENTINEL } from "../memory-corpus-version.js";
import {
  computeReviewItemRevision,
  type ReviewDeckSnapshot,
  type ReviewDeckSourceRow,
} from "./review-deck.js";
import { parseFrontmatterFields, splitMarkdownFrontmatter } from "./frontmatter.js";

const QUEUE_DIRS = ["suggestions", "review"] as const;

export function readReviewDeckSnapshot(opts: { memoryDir: string; namespace: string }): ReviewDeckSnapshot {
  const corpusVersion = readCorpusVersion(opts.memoryDir);
  const rootReal = realMemoryRoot(opts.memoryDir);
  if (!rootReal) return { corpusVersion, total: 0, rows: [] };

  const rows: ReviewDeckSourceRow[] = [];
  for (const location of QUEUE_DIRS) {
    const dir = path.join(opts.memoryDir, location);
    if (!fs.existsSync(dir) || !isSafeDirectory(rootReal, dir)) continue;
    walkMd(rootReal, dir, (filePath, content) => {
      const row = rowFromQueueFile(filePath, content, location);
      if (row) rows.push(row);
    });
  }
  return { corpusVersion, total: rows.length, rows };
}

export function readReviewDeckRow(opts: { memoryDir: string; itemId: string }): ReviewDeckSourceRow | null {
  const rootReal = realMemoryRoot(opts.memoryDir);
  if (!rootReal) return null;
  for (const location of QUEUE_DIRS) {
    const dir = path.join(opts.memoryDir, location);
    if (!fs.existsSync(dir) || !isSafeDirectory(rootReal, dir)) continue;
    let found: ReviewDeckSourceRow | null = null;
    walkMd(rootReal, dir, (filePath, content) => {
      const row = rowFromQueueFile(filePath, content, location);
      if (row?.itemId === opts.itemId) {
        found = row;
        return true;
      }
    });
    if (found) return found;
  }
  return null;
}

function readCorpusVersion(memoryDir: string): string {
  try {
    return String(fs.statSync(path.join(memoryDir, "state", MEMORY_CORPUS_VERSION_SENTINEL)).size);
  } catch {
    return "0";
  }
}

function rowFromQueueFile(
  filePath: string,
  content: string,
  location: (typeof QUEUE_DIRS)[number],
): ReviewDeckSourceRow | null {
  const fm = parseFrontmatter(content);
  const itemId = optionalString(fm?.id);
  if (!fm || !itemId || !isPendingQueueRow(fm)) return null;
  const blockedBy = optionalString(fm.blockedBy);
  const confidence = parseOptionalConfidence(fm.confidence);
  const category = optionalString(fm.category);
  const confidenceTier = optionalString(fm.confidenceTier);
  const source = optionalString(fm.source);
  const context = optionalString(fm.context);
  const lifecycleState = optionalString(fm.lifecycleState) ?? optionalString(fm.status);
  const created = optionalString(fm.created) ?? "";
  const explicitReason = optionalString(fm.reviewReason);
  return {
    itemId,
    filePath,
    fileContent: content,
    revision: computeReviewItemRevision(content),
    content: extractBody(content),
    reviewReason: explicitReason
      ?? (blockedBy ? "tombstone_blocked" : location === "suggestions" ? "suggestion" : "low_confidence"),
    created,
    ...(category ? { category } : {}),
    ...(confidence !== undefined ? { confidence } : {}),
    ...(confidenceTier ? { confidenceTier } : {}),
    ...(source ? { source } : {}),
    ...(blockedBy ? { blockedBy } : {}),
    ...(lifecycleState ? { lifecycleState } : {}),
    ...(context ? { context } : {}),
  };
}

function isPendingQueueRow(fm: Record<string, unknown>): boolean {
  if (parseBoolean(fm.reviewDismissed)) return false;
  const status = optionalString(fm.status);
  return status === undefined || status === "pending_review";
}

function realMemoryRoot(memoryDir: string): string | null {
  try {
    const stat = fs.lstatSync(memoryDir);
    if (!stat.isDirectory() || stat.isSymbolicLink()) return null;
    return fs.realpathSync(memoryDir);
  } catch {
    return null;
  }
}

function isPathInside(rootReal: string, candidateReal: string): boolean {
  const relative = path.relative(rootReal, candidateReal);
  return relative === "" || (!!relative && !relative.startsWith("..") && !path.isAbsolute(relative));
}

function isSafeDirectory(rootReal: string, dir: string): boolean {
  try {
    const stat = fs.lstatSync(dir);
    if (!stat.isDirectory() || stat.isSymbolicLink()) return false;
    return isPathInside(rootReal, fs.realpathSync(dir));
  } catch {
    return false;
  }
}

function walkMd(
  rootReal: string,
  dir: string,
  callback: (filePath: string, content: string) => boolean | void,
): boolean {
  if (!isSafeDirectory(rootReal, dir)) return false;
  for (const entry of fs.readdirSync(dir, { withFileTypes: true })) {
    const fullPath = path.join(dir, entry.name);
    if (entry.isSymbolicLink()) continue;
    if (entry.isDirectory()) {
      if (walkMd(rootReal, fullPath, callback)) return true;
    } else if (entry.isFile() && entry.name.endsWith(".md")) {
      const content = readFileSafe(fullPath);
      if (content && callback(fullPath, content) === true) return true;
    }
  }
  return false;
}

function readFileSafe(filePath: string): string | null {
  try {
    return fs.readFileSync(filePath, "utf8");
  } catch {
    return null;
  }
}

function parseFrontmatter(content: string): Record<string, unknown> | null {
  if (!content.startsWith("---\n")) return null;
  return parseFrontmatterFields(content);
}

function extractBody(content: string): string {
  return splitMarkdownFrontmatter(content)?.body.trim() ?? content.trim();
}

function parseBoolean(value: unknown): boolean {
  if (typeof value === "boolean") return value;
  if (typeof value !== "string") return false;
  const normalized = value.trim().toLowerCase();
  return normalized === "true" || normalized === "1" || normalized === "yes";
}

function optionalString(value: unknown): string | undefined {
  if (typeof value !== "string") return undefined;
  const trimmed = value.trim();
  return trimmed.length > 0 ? trimmed : undefined;
}

function parseOptionalConfidence(value: unknown): number | undefined {
  if (typeof value === "number") return Number.isFinite(value) ? value : undefined;
  if (typeof value === "string" && value.trim().length > 0) {
    const parsed = Number.parseFloat(value);
    return Number.isFinite(parsed) ? parsed : undefined;
  }
  return undefined;
}

/**
 * Single input-validation and error boundary for the CLI/MCP/HTTP access
 * surfaces (issue #1525, epic #1520 Phase 1).
 *
 * Every operation that crosses the access-service facade passes through ONE
 * registry entry: a zod-validated request envelope, a shared error mapper,
 * and the "reject invalid input and list valid options" behavior that
 * CLAUDE.md rules 14/17/24/28/36/48/51 previously had to be re-implemented
 * per handler. The three surfaces become thin adapters — one operation
 * definition, three transports — so a validation fix lands everywhere at
 * once.
