export type MemoryGovernanceMode = "shadow" | "apply";
export type MemoryGovernanceReasonCode =
  | "exact_duplicate"
  | "semantic_duplicate_candidate"
  | "disputed_memory"
  | "speculative_low_confidence"
  | "archive_candidate"
  | "explicit_capture_review"
  | "malformed_import";

