]);

function isDenialReportingVerb(token: string): boolean {
  return GROUNDING_DENIAL_REPORTING_VERBS.has(token);
}
const GROUNDING_NON_ASSERTIVE_REPORTING_VERBS = new Set([
  "allege",
  "alleged",
  "alleges",
  "alleging",
  "allegedly",
  "assert",
  "asserted",
