export interface AccessRecallSurfaceDeps {
  readonly auditAdapter: AccessAuditAdapter | null;
  readonly budget: CrossNamespaceBudget;
  buildRecallDebug(
    snapshot: LastRecallSnapshot | null,
    namespace: string,
    includeDebug: boolean,
    sessionKey?: string,
  ): Promise<EngramAccessRecallResponse["debug"] | undefined>;
  buildRecallResponseFromXraySnapshot(options: {
    query: string;
    sessionKey?: string;
    snapshot: RecallXraySnapshot;
    storageCorpusVersionsAtRecallStart: Array<{ namespace: string; version: number | null }>;
    disclosure: RecallDisclosure;
    startedAt: number;
    requestedMode?: RecallPlanMode | "auto";
    normalizedMode?: RecallPlanMode;
    /**
     * Read-authorization-gated namespace for the raw-excerpt LCM lookup (#1505
     * thread 2f7). Threaded through to `serializeRecallResults` so the
     * `includeRecall` x-ray path honours the SAME read gate as normal recall and
     * never attaches overlay transcript rows the gate excludes.
     */
    rawExcerptNamespace?: string;
    /**
     * Ordered, read-authorized LCM read session_id SET (#1505 fallback
     * unification). Threaded through to `serializeRecallResults` so the x-ray raw
     * disclosure path also finds excerpts archived at the coding read fallbacks.
     */
    rawExcerptSessionIds?: string[];
    /**
     * Force NO raw excerpts (#1505 thread NBHWz). Set when the IMPLICIT
     * raw-excerpt read gate found NO readable LCM namespace, so the x-ray
     * includeRecall path degrades to empty excerpts rather than falling back to
     * the write/overlay namespace the read gate excludes.
     */
    rawExcerptsSuppressed?: boolean;
  }): Promise<EngramAccessRecallResponse>;
  fetchRawExcerpts(
    disclosure: RecallDisclosure,
    context: {
      query: string;
      sessionKey?: string;
      namespace?: string;
      /**
       * Pre-resolved, ordered, read-authorized LCM read session_id SET (#1505
       * fallback unification). When supplied, raw disclosure queries each key in
       * order (primary coding overlay → read fallbacks) and merges rows, exactly
       * as the orchestrator recall path and `lcmSearch` do, so a branch-scoped
       * session finds excerpts archived at project/root scope. Already
       * read-gated by `resolveLcmReadSessionIds`, so an unauthorized
       * `<principal>-project-*` key is never present. Falls back to the legacy
       * single `namespace`-prefixed key when absent (sessionless / legacy
       * callers).
       */
      lcmSessionIds?: string[];
    } | null,
  ): Promise<EngramAccessMemorySummary["rawExcerpts"] | null>;
  maybeAttachCodingContext(
    sessionKey: string | undefined,
    options: { cwd?: string; projectTag?: string },
  ): Promise<void>;
  normalizeRecallMode(mode?: RecallPlanMode | "auto"): RecallPlanMode | undefined;
  readonly orchestrator: Orchestrator;
  resolveLcmReadSessionIds(
    explicitNamespace: string | undefined,
    resolvedNamespace: string,
    sessionKey: string,
    authenticatedPrincipal: string | undefined,
  ): string[];
  resolveNamespace(namespace?: string): string;
  resolveRawExcerptReadNamespace(
    explicitNamespace: string | undefined,
    sessionKey: string | undefined,
    authenticatedPrincipal: string | undefined,
  ): string | undefined;
  resolveRecallNamespace(
    namespace: string | undefined,
    sessionKey: string | undefined,
    authenticatedPrincipal?: string,
  ): string | undefined;
  resolveRequestPrincipal(sessionKey: string | undefined, authenticatedPrincipal?: string): string | undefined;
  serializeMemorySummary(
    memory: MemoryFile,
    baseDir: string,
    disclosure?: RecallDisclosure,
    rawExcerpts?: EngramAccessMemorySummary["rawExcerpts"],
  ): EngramAccessMemorySummary;
  serializeRecallResults(
    snapshot: LastRecallSnapshot | null,
    disclosure: RecallDisclosure,
    rawContext?:
      | {
          query: string;
          sessionKey?: string;
          /**
           * Read-authorization-gated namespace for the raw-excerpt LCM lookup
           * (#1505 thread 2f7). When the caller supplies it, the raw lookup uses
           * THIS namespace prefix instead of `snapshot.namespace` (the
           * write/overlay namespace), so raw disclosure honours the SAME read
           * gate as normal recall + `lcmSearch`. Omitted ⇒ falls back to the
           * snapshot namespace (single-store / sessionless callers, unchanged).
           */
          rawExcerptNamespace?: string;
          /**
           * Ordered, read-authorized LCM read session_id SET (#1505 fallback
           * unification). When supplied, raw disclosure queries each key (primary
           * coding overlay → read fallbacks) and merges rows so a branch-scoped
           * session finds excerpts archived at project/root scope. Already
           * read-gated, so no unauthorized overlay key is present. Omitted ⇒ the
           * legacy single `rawExcerptNamespace`-prefixed key (unchanged).
           */
          rawExcerptSessionIds?: string[];
          /**
           * Force NO raw excerpts even when `disclosure === "raw"` (#1505 thread
           * NBHWz). Set by callers when the IMPLICIT raw-excerpt read gate found
           * NO readable LCM namespace (a restrictive `default` READ policy with
           * no readable overlay/self namespace). The lookup must NOT fall back to
           * `snapshot.namespace` (the write/overlay namespace the read gate
           * excludes) — it returns empty excerpts so raw recall degrades
           * gracefully instead of leaking unreadable rows or throwing.
           */
          rawExcerptsSuppressed?: boolean;
        }
      | null,
  ): Promise<EngramAccessMemorySummary[]>;
  setCodingContext(request: EngramAccessSetCodingContextRequest): void;
  storageForAbsoluteRecallPath(
    memoryPath: string,
    primaryNamespace: string,
    recallNamespaces?: readonly string[],
  ): Promise<{ storage: StorageManager; dir: string } | null>;
}

export class AccessRecallSurface {
  constructor(
    private readonly deps: AccessRecallSurfaceDeps,
  ) {}

  async buildRecallResponseFromXraySnapshot(options: {
    query: string;
    sessionKey?: string;
    snapshot: RecallXraySnapshot;
    storageCorpusVersionsAtRecallStart: Array<{ namespace: string; version: number | null }>;
    disclosure: RecallDisclosure;
    startedAt: number;
    requestedMode?: RecallPlanMode | "auto";
    normalizedMode?: RecallPlanMode;
    /**
     * Read-authorization-gated namespace for the raw-excerpt LCM lookup (#1505
     * thread 2f7). Threaded through to `serializeRecallResults` so the
     * `includeRecall` x-ray path honours the SAME read gate as normal recall and
     * never attaches overlay transcript rows the gate excludes.
     */
    rawExcerptNamespace?: string;
    /**
     * Ordered, read-authorized LCM read session_id SET (#1505 fallback
     * unification). Threaded through to `serializeRecallResults` so the x-ray raw
     * disclosure path also finds excerpts archived at the coding read fallbacks.
     */
    rawExcerptSessionIds?: string[];
    /**
     * Force NO raw excerpts (#1505 thread NBHWz). Set when the IMPLICIT
     * raw-excerpt read gate found NO readable LCM namespace, so the x-ray
     * includeRecall path degrades to empty excerpts rather than falling back to
     * the write/overlay namespace the read gate excludes.
     */
    rawExcerptsSuppressed?: boolean;
  }): Promise<EngramAccessRecallResponse> {
    const memoryIds = options.snapshot.results.map((result) => result.memoryId);
    const includedMemories = options.snapshot.results.map((result) => ({
      id: result.memoryId,
      path: result.path,
    }));
    const namespace = options.snapshot.namespace
      ? this.deps.resolveNamespace(options.snapshot.namespace)
      : this.deps.orchestrator.config.defaultNamespace;
    const sourcesUsed = Array.from(
      new Set(options.snapshot.results.map((result) => result.servedBy)),
    );
    const snapshotForSerialization: LastRecallSnapshot = {
      sessionKey: options.sessionKey ?? "",
      recordedAt: new Date(options.snapshot.capturedAt).toISOString(),
      queryHash: createHash("sha256").update(options.query).digest("hex"),
      queryLen: options.query.length,
      memoryIds,
      namespace,
      recallNamespaces: [namespace],
      traceId: options.snapshot.traceId,
      plannerMode: options.normalizedMode,
      requestedMode:
        options.requestedMode && options.requestedMode !== "auto"
          ? options.requestedMode
          : undefined,
      sourcesUsed,
      budgetsApplied: {
        appliedTopK: memoryIds.length,
        recallBudgetChars: options.snapshot.budget.chars,
        maxMemoryTokens: this.deps.orchestrator.config.maxMemoryTokens,
        finalContextChars: options.snapshot.budget.used,
      },
      latencyMs: Date.now() - options.startedAt,
      includedMemories,
    };
    const results = await this.deps.serializeRecallResults(
      snapshotForSerialization,
      options.disclosure,
      {
        query: options.query,
        ...(options.sessionKey ? { sessionKey: options.sessionKey } : {}),
        ...(options.rawExcerptNamespace
          ? { rawExcerptNamespace: options.rawExcerptNamespace }
          : {}),
        ...(options.rawExcerptSessionIds !== undefined
          ? { rawExcerptSessionIds: options.rawExcerptSessionIds }
          : {}),
        ...(options.rawExcerptsSuppressed
          ? { rawExcerptsSuppressed: options.rawExcerptsSuppressed }
          : {}),
      },
    );
    const context = results
      .map((result) => {
        const content =
          typeof result.content === "string" && result.content.length > 0
            ? result.content
            : "";
        return content || result.preview;
      })
      .filter((text) => text.length > 0)
      .join("\n\n");

    return {
      query: options.query,
      ...(options.sessionKey ? { sessionKey: options.sessionKey } : {}),
      namespace,
      context,
      count: memoryIds.length,
      memoryIds,
      results,
      recordedAt: snapshotForSerialization.recordedAt,
      traceId: options.snapshot.traceId,
      plannerMode: options.normalizedMode,
      fallbackUsed: sourcesUsed.some((source) => source !== "hybrid"),
      sourcesUsed,
      disclosure: options.disclosure,
      budgetsApplied: snapshotForSerialization.budgetsApplied,
      storageCorpusVersionsAtRecallStart: options.storageCorpusVersionsAtRecallStart,
      latencyMs: snapshotForSerialization.latencyMs,
    };
  }

  async serializeRecallResults(
    snapshot: LastRecallSnapshot | null,
    disclosure: RecallDisclosure,
    rawContext:
      | {
          query: string;
          sessionKey?: string;
          /**
           * Read-authorization-gated namespace for the raw-excerpt LCM lookup
           * (#1505 thread 2f7). When the caller supplies it, the raw lookup uses
           * THIS namespace prefix instead of `snapshot.namespace` (the
           * write/overlay namespace), so raw disclosure honours the SAME read
           * gate as normal recall + `lcmSearch`. Omitted ⇒ falls back to the
           * snapshot namespace (single-store / sessionless callers, unchanged).
           */
          rawExcerptNamespace?: string;
          /**
           * Ordered, read-authorized LCM read session_id SET (#1505 fallback
           * unification). When supplied, raw disclosure queries each key (primary
           * coding overlay → read fallbacks) and merges rows so a branch-scoped
           * session finds excerpts archived at project/root scope. Already
           * read-gated, so no unauthorized overlay key is present. Omitted ⇒ the
           * legacy single `rawExcerptNamespace`-prefixed key (unchanged).
           */
          rawExcerptSessionIds?: string[];
          /**
           * Force NO raw excerpts even when `disclosure === "raw"` (#1505 thread
           * NBHWz). Set by callers when the IMPLICIT raw-excerpt read gate found
           * NO readable LCM namespace (a restrictive `default` READ policy with
           * no readable overlay/self namespace). The lookup must NOT fall back to
           * `snapshot.namespace` (the write/overlay namespace the read gate
           * excludes) — it returns empty excerpts so raw recall degrades
           * gracefully instead of leaking unreadable rows or throwing.
           */
          rawExcerptsSuppressed?: boolean;
        }
      | null = null,
  ): Promise<EngramAccessMemorySummary[]> {
    if (!snapshot) return [];
    const namespace = snapshot.namespace ? this.deps.resolveNamespace(snapshot.namespace) : this.deps.orchestrator.config.defaultNamespace;
    const storage = await this.deps.orchestrator.getStorage(namespace);
    const storageDir = storage.dir;
    const recallNamespaces = Array.from(
      new Set(
        [
          namespace,
          ...(Array.isArray(snapshot.recallNamespaces)
            ? snapshot.recallNamespaces.map((ns) => this.deps.resolveNamespace(ns))
            : []),
          this.deps.orchestrator.config.defaultNamespace,
          this.deps.orchestrator.config.sharedNamespace,
          ...(this.deps.orchestrator.config.namespacePolicies ?? []).map((p) => p.name),
        ].filter((ns): ns is string => typeof ns === "string" && ns.length > 0),
      ),
    );
    const results: EngramAccessMemorySummary[] = [];
    const seen = new Set<string>();
    const collectionNamespaceFromPrefix = (collectionPrefix: string): string | null => {
      const baseCollection = this.deps.orchestrator.config.qmdCollection;
      if (collectionPrefix === baseCollection) return this.deps.orchestrator.config.defaultNamespace;
      const namespaceSuffix = collectionPrefix.startsWith(`${baseCollection}--`)
        ? collectionPrefix.slice(baseCollection.length + 2)
        : "";
      if (!namespaceSuffix) return null;

      const decoded = namespaceIdentityFromToken(namespaceSuffix);
      if (decoded !== null) return decoded || this.deps.orchestrator.config.defaultNamespace;
      if (namespaceSuffix.startsWith("ns--")) {
        const legacyNamespace = namespaceSuffix.slice("ns--".length).trim();
        return legacyNamespace || null;
      }
      return null;
    };
    const readResultPath = async (
      memoryPath: string,
      preferredNamespace?: string,
    ): Promise<{ memory: MemoryFile; baseDir: string } | null> => {
      const parts = qmdCollectionPathParts(memoryPath);
      const coldCollection =
        this.deps.orchestrator.config.qmdColdCollection ?? "openclaw-engram-cold";
      const collectionNamespace = parts
        ? collectionNamespaceFromPrefix(parts.collection)
        : null;
      const preferredAttempted = Boolean(
        preferredNamespace &&
          (!parts ||
            (collectionNamespace === null && parts.collection !== coldCollection)),
      );
      if (preferredAttempted) {
        try {
          const preferredStorage = await this.deps.orchestrator.getStorage(
            this.deps.resolveNamespace(preferredNamespace),
          );
          for (const candidate of qmdResultPathCandidates(
            preferredStorage.dir,
            memoryPath,
          )) {
            const memory = await preferredStorage.readMemoryByPath(candidate);
            if (memory) return { memory, baseDir: preferredStorage.dir };
          }
        } catch (err) {
          if (err instanceof SecureStoreLockedError) throw err;
        }
      }
      if (parts && parts.collection === coldCollection) {
        const storages: Array<{ storage: StorageManager; dir: string }> = [];
        const seenStorageDirs = new Set<string>();
        const addStorage = (candidateStorage: StorageManager): void => {
          const candidateDir = nodePath.resolve(candidateStorage.dir);
          if (seenStorageDirs.has(candidateDir)) return;
          seenStorageDirs.add(candidateDir);
          storages.push({ storage: candidateStorage, dir: candidateDir });
        };
        addStorage(storage);
        for (const recallNamespace of recallNamespaces) {
          try {
            addStorage(await this.deps.orchestrator.getStorage(recallNamespace));
          } catch {
            continue;
          }
        }
        for (const candidateStorage of storages) {
          try {
            const coldRoot = nodePath.join(candidateStorage.dir, "cold");
            for (const candidatePath of qmdResultPathCandidates(
              coldRoot,
              parts.relativePath,
            )) {
              const memory =
                await candidateStorage.storage.readMemoryByPath(candidatePath);
              if (memory) return { memory, baseDir: candidateStorage.dir };
            }
          } catch (err) {
            if (err instanceof SecureStoreLockedError) throw err;
            continue;
          }
        }
        return null;
      }


      if (parts && collectionNamespace) {
        try {
          const collectionStorage =
            await this.deps.orchestrator.getStorage(collectionNamespace);
          for (const candidate of qmdResultPathCandidates(
            collectionStorage.dir,
            parts.relativePath,
          )) {
            const memory = await collectionStorage.readMemoryByPath(candidate);
            if (memory) return { memory, baseDir: collectionStorage.dir };
          }
          return null;
        } catch (err) {
          if (err instanceof SecureStoreLockedError) throw err;
          return null;
        }
      }

      if (nodePath.isAbsolute(memoryPath)) {
        const ownerStorage = await this.deps.storageForAbsoluteRecallPath(
          memoryPath,
          namespace,
          recallNamespaces,
        );
        if (!ownerStorage) return null;
        for (const candidate of qmdResultPathCandidates(
          ownerStorage.dir,
          memoryPath,
        )) {
          const memory = await ownerStorage.storage.readMemoryByPath(candidate);
          if (memory) return { memory, baseDir: ownerStorage.dir };
        }
        return null;
      }

      // A preferred namespace was supplied but its file is missing/stale. For a
      // relative path the preferred store was the only correct lead, so do not
      // fall through to the default store and surface a same-relative-path file
      // from the wrong namespace (#2020). Absolute paths self-identify above.
      if (preferredAttempted && !nodePath.isAbsolute(memoryPath)) return null;

      for (const candidate of qmdResultPathCandidates(storageDir, memoryPath)) {
        const memory = await storage.readMemoryByPath(candidate);
        if (memory) return { memory, baseDir: storageDir };
      }
      return null;
    };

    // Pre-fetch raw excerpts once when `disclosure === "raw"` so we don't
    // hit the LCM archive per-result (issue #677 PR 2/4).  Excerpts are
    // attached to the first result; per-result attribution is reserved
    // for a future PR if/when the LCM index can be joined to memory ids.
    // Coerce `null` (non-raw disclosure) to `undefined` so the optional
    // serializer field is never explicitly `null`.
    // Namespace for the LCM `${namespace}:${sessionKey}` prefix: prefer the
    // caller-supplied READ-AUTHORIZATION-GATED `rawExcerptNamespace` (#1505
    // thread 2f7) so raw disclosure honours the same read gate as normal recall
    // + `lcmSearch` and never attaches `<principal>-project-*` overlay rows the
    // gate excludes. Fall back to the snapshot's resolved namespace only when no
    // gated namespace was threaded (sessionless / legacy callers) — unchanged.
    const rawExcerptsResult =
      rawContext?.rawExcerptsSuppressed === true
        ? // Implicit raw recall with NO readable LCM namespace (#1505 thread
          // NBHWz): emit empty excerpts rather than falling back to the
          // write/overlay `namespace` the read gate excludes.
          []
        : await this.deps.fetchRawExcerpts(
            disclosure,
            rawContext
              ? {
                  query: rawContext.query,
                  ...(rawContext.sessionKey
                    ? { sessionKey: rawContext.sessionKey }
                    : {}),
                  namespace: rawContext.rawExcerptNamespace ?? namespace,
                  ...(rawContext.rawExcerptSessionIds !== undefined
                    ? { lcmSessionIds: rawContext.rawExcerptSessionIds }
                    : {}),
                }
              : null,
          );
    const rawExcerpts = rawExcerptsResult ?? undefined;
    for (const included of coerceIncludedMemories(snapshot)) {
      const memoryPath = included.path;
      if (!memoryPath) continue;
      const memoryNamespace = included.namespace;
      const seenKey = `${memoryNamespace ?? ""}\0${memoryPath}`;
      if (seen.has(seenKey)) continue;
      const resolved = await readResultPath(memoryPath, memoryNamespace);
      if (!resolved) continue;
      const { memory, baseDir } = resolved;
      seen.add(seenKey);
      results.push(
        this.deps.serializeMemorySummary(
          memory,
          baseDir,
          disclosure,
          // Attach the (possibly empty) raw excerpts to the first raw
          // result; subsequent results do not duplicate the array.
          results.length === 0 ? rawExcerpts : undefined,
        ),
      );
    }

    if (results.length > 0) return results;

    for (const memoryId of snapshot.memoryIds) {
      const memory = await storage.getMemoryById(memoryId);
      if (!memory || seen.has(memory.path)) continue;
      seen.add(memory.path);
      results.push(
        this.deps.serializeMemorySummary(
          memory,
          storageDir,
          disclosure,
          results.length === 0 ? rawExcerpts : undefined,
        ),
      );
    }
    return results;
  }

  /**
   * Fetch raw transcript excerpts from the LCM archive for `disclosure ===
   * "raw"` recalls (issue #677 PR 2/4).  Returns `null` for non-raw recall
   * depths, an empty array when LCM is disabled / not initialized / has no
   * matches, and an array of LCM-side excerpts otherwise.  Errors are
   * swallowed and treated as "no excerpts" so a failing LCM never breaks
   * the recall response.
   *
   * Namespace handling: LCM archival prefixes non-default-namespace
   * sessions with `${namespace}:${sessionKey}` (see `observe()` around
   * line 2498), so the lookup must mirror that prefix or raw recalls in
   * non-default namespaces miss their own excerpts.
   */
  async fetchRawExcerpts(
    disclosure: RecallDisclosure,
    context: {
      query: string;
      sessionKey?: string;
      namespace?: string;
      /**
       * Pre-resolved, ordered, read-authorized LCM read session_id SET (#1505
       * fallback unification). When supplied, raw disclosure queries each key in
       * order (primary coding overlay → read fallbacks) and merges rows, exactly
       * as the orchestrator recall path and `lcmSearch` do, so a branch-scoped
       * session finds excerpts archived at project/root scope. Already
       * read-gated by `resolveLcmReadSessionIds`, so an unauthorized
       * `<principal>-project-*` key is never present. Falls back to the legacy
       * single `namespace`-prefixed key when absent (sessionless / legacy
       * callers).
       */
      lcmSessionIds?: string[];
    } | null,
  ): Promise<EngramAccessMemorySummary["rawExcerpts"] | null> {
    if (disclosure !== "raw") return null;
    if (!context || !context.query) return [];
    // Privacy guard: raw disclosure must be session-scoped.  Without a
    // sessionKey, `lcm.searchContextFull(query, n, undefined)` searches
    // across every archived session in the LCM store and would return
    // excerpts from unrelated sessions (potentially crossing namespaces
    // via their `${namespace}:${sessionKey}` prefix encoding).  Treat a
    // missing sessionKey as "no excerpts" — callers asking for raw
    // disclosure outside a session get an empty list, not a leak.
    if (!context.sessionKey) return [];
    const lcm = this.deps.orchestrator.lcmEngine;
    if (!lcm || !lcm.enabled) return [];
    try {
      const legacyKey =
        context.namespace &&
        context.namespace !== this.deps.orchestrator.config.defaultNamespace
          ? `${context.namespace}:${context.sessionKey}`
          : context.sessionKey;
      const lcmSessionIds =
        context.lcmSessionIds !== undefined
          ? context.lcmSessionIds
          : [legacyKey];
      // Cap the excerpt fanout so recall responses stay bounded.  Five matches
      // is enough to anchor the model in the raw transcript without ballooning
      // token spend; raw is meant as the escape hatch, not the default. The cap
      // is applied across the MERGED result set so adding fallback keys never
      // inflates the excerpt budget.
      const limit = 5;
      const seenRows = new Set<string>();
      const excerpts: NonNullable<EngramAccessMemorySummary["rawExcerpts"]> = [];
      const settledRows = await Promise.allSettled(
        lcmSessionIds.map(async (lcmSessionKey) =>
          lcm.searchContextFull(context.query, limit, lcmSessionKey),
        ),
      );
      for (const result of settledRows) {
        if (excerpts.length >= limit) break;
        if (result.status !== "fulfilled") continue;
        for (const r of result.value) {
          const dedupeKey = lcmEvidenceIdentity(r, r.session_id).id;
          if (seenRows.has(dedupeKey)) continue;
          seenRows.add(dedupeKey);
          excerpts.push({
            turnIndex: r.turn_index,
            role: r.role,
            content: r.content,
            sessionId: r.session_id,
          });
          if (excerpts.length >= limit) break;
        }
      }
      return excerpts;
    } catch {
      // CLAUDE.md rule 13: never let an external subsystem (LCM/SQLite)
      // crash the primary recall flow.
      return [];
    }
  }

  async executeRecall(
    request: EngramAccessRecallRequest,
  ): Promise<{
    response: EngramAccessRecallResponse;
    budgetRecordPrincipal: string | null;
    reservation?: BudgetReservation;
  }> {
    const query = request.query;
    // Disclosure depth (issue #677).  Default to `"chunk"` when omitted so
    // pre-#677 callers see unchanged behavior.  Reject explicitly invalid
    // string values per CLAUDE.md rule 51 (do not silently fall back).
    const callerProvidedDisclosure =
      request.disclosure !== undefined && request.disclosure !== null;
    const requestedDisclosure: RecallDisclosure = (() => {
      if (!callerProvidedDisclosure) {
        return DEFAULT_RECALL_DISCLOSURE;
      }
      if (!isRecallDisclosure(request.disclosure)) {
        throw new EngramAccessInputError(
          `disclosure must be one of: chunk, section, raw (got: ${String(request.disclosure)})`,
        );
      }
      return request.disclosure;
    })();
    // Attach any coding context shipped with the recall request BEFORE
    // namespace resolution so the overlay applies to this recall (issue #569).
    if (request.codingContext !== undefined && request.sessionKey) {
      this.deps.setCodingContext({
        sessionKey: request.sessionKey,
        codingContext: request.codingContext,
      });
    }
    // Auto-resolve coding context from cwd/projectTag when no explicit
    // codingContext was supplied (issue #569 wiring). This allows Claude
    // Code hooks and OpenClaw connectors to get project-scoped memory
    // transparently.
    if (request.codingContext === undefined && request.sessionKey) {
      await this.deps.maybeAttachCodingContext(request.sessionKey, {
        cwd: request.cwd,
        projectTag: request.projectTag,
      });
    }
    const authenticatedPrincipal = request.authenticatedPrincipal?.trim();
    const namespaceOverride = this.deps.resolveRecallNamespace(
      request.namespace,
      request.sessionKey,
      authenticatedPrincipal,
    );
    const namespace = namespaceOverride ?? this.deps.orchestrator.config.defaultNamespace;
    // Normalize mode early so that no_recall / invalid modes skip budget
    // accounting (Codex P1: budget recorded before mode validation).
    const mode = this.deps.normalizeRecallMode(request.mode);
    const maybePrincipal = this.deps.resolveRequestPrincipal(request.sessionKey, authenticatedPrincipal);
    if (resolveNamespaceCapabilities(this.deps.orchestrator.config).namespaces && !maybePrincipal) {
      throw new EngramAccessInputError(
        "authentication required: namespaces are enabled and no principal was supplied",
      );
    }
    const principal = maybePrincipal ?? "default";
    const principalNamespace = defaultNamespaceForPrincipal(principal, this.deps.orchestrator.config);
    const profileCodingContext =
      request.sessionKey && typeof this.deps.orchestrator.getCodingContextForSession === "function"
        ? this.deps.orchestrator.getCodingContextForSession(request.sessionKey)
        : null;
    const profileCodingOverlay =
      !namespaceOverride &&
      profileCodingContext &&
      resolveNamespaceCapabilities(this.deps.orchestrator.config).namespaces &&
      this.deps.orchestrator.config.codingMode?.projectScope
        ? resolveCodingNamespaceOverlay(
            profileCodingContext,
            this.deps.orchestrator.config.codingMode,
            this.deps.orchestrator.config.defaultNamespace,
          )
        : null;
    const profilePlan = namespaceOverride
      ? null
      : resolveScopeProfilePlan({
          config: this.deps.orchestrator.config,
          principal,
          codingContext: profileCodingContext,
          codingOverlay: profileCodingOverlay,
        });
    const recallScopePlan = resolveScopePlan({
      config: this.deps.orchestrator.config,
      sessionKey: request.sessionKey,
      namespace: namespaceOverride,
      principalOverride: authenticatedPrincipal,
      codingContext: profileCodingContext,
      namespacesEnabled: resolveNamespaceCapabilities(this.deps.orchestrator.config).namespaces,
    });
    // Skip budget checks for modes that never perform a cross-namespace read.
    const modeSkipsBudget = mode === "no_recall";
    const effectiveNamespaces = recallScopePlan.readNamespaces;
    const budgetPrincipalNamespace = profilePlan?.baseNamespace ?? principalNamespace;
    let budgetDecision: BudgetDecision;
    let willReserveBudget = false;
    if (modeSkipsBudget) {
      budgetDecision = {
        allowed: true as const,
        reason: "allowed-same-namespace" as const,
        count: 0,
        limit: {
          softLimit: this.deps.orchestrator.config.recallCrossNamespaceBudgetSoftLimit ?? 10,
          hardLimit: this.deps.orchestrator.config.recallCrossNamespaceBudgetHardLimit ?? 30,
          windowMs: this.deps.orchestrator.config.recallCrossNamespaceBudgetWindowMs ?? 60_000,
        },
      };
    } else {
      // Peek at every effective namespace to determine whether ANY would be
      // cross-namespace WITHOUT recording side effects (Cursor review:
      // multi-count bug). When cross-namespace, the actual reserve
      // (budget.record) happens ATOMICALLY at admission just before the
      // pipeline runs (issue #1906) — see the reserve+rollback block below —
      // so concurrent recalls for one principal cannot each pass a stale peek
      // and collectively overrun the hard limit.
      let anyCrossNamespace = false;
      let denied: BudgetDecision | null = null;
      let crossNamespaceDecision: BudgetDecision | null = null;
      for (const ns of effectiveNamespaces) {
        const peek = this.deps.budget.peek({
          principal,
          principalNamespace: budgetPrincipalNamespace,
          queryNamespace: ns,
        });
        if (peek.reason !== "allowed-same-namespace") {
          anyCrossNamespace = true;
          crossNamespaceDecision ??= peek;
        }
        if (!peek.allowed) {
          denied = peek;
          break;
        }
      }
      if (denied) {
        // The peek projected a denial — deny without recording so the
        // bucket is not inflated by rejected attempts.
        budgetDecision = denied;
      } else if (anyCrossNamespace) {
        budgetDecision = crossNamespaceDecision ?? {
          allowed: true as const,
          reason: "allowed-under-soft" as const,
          count: 0,
          limit: {
            softLimit: this.deps.orchestrator.config.recallCrossNamespaceBudgetSoftLimit ?? 10,
            hardLimit: this.deps.orchestrator.config.recallCrossNamespaceBudgetHardLimit ?? 30,
            windowMs: this.deps.orchestrator.config.recallCrossNamespaceBudgetWindowMs ?? 60_000,
          },
        };
        willReserveBudget = true;
      } else {
        budgetDecision = {
          allowed: true as const,
          reason: "allowed-same-namespace" as const,
          count: 0,
          limit: {
            softLimit: this.deps.orchestrator.config.recallCrossNamespaceBudgetSoftLimit ?? 10,
            hardLimit: this.deps.orchestrator.config.recallCrossNamespaceBudgetHardLimit ?? 30,
            windowMs: this.deps.orchestrator.config.recallCrossNamespaceBudgetWindowMs ?? 60_000,
          },
        };
      }
      if (!budgetDecision.allowed) {
        throw new EngramAccessInputError(
          `recall denied: cross-namespace budget exceeded (${budgetDecision.count}/${budgetDecision.limit.hardLimit} in ${budgetDecision.limit.windowMs}ms window)`,
        );
      }
      // Prune expired principal buckets to prevent unbounded Map growth from
      // high-cardinality / transient principals (Codex P2 review feedback).
      this.deps.budget.gc();
    }
    const topK = Number.isFinite(request.topK) ? Math.max(0, Math.floor(request.topK ?? 0)) : undefined;
    // Issue #680 — historical recall pin.  Validate at the input boundary so
    // a malformed `asOf` is rejected with a structured 400 instead of
    // silently flooring at NaN inside the orchestrator (rule 51, gotcha #51).
    // Empty / undefined is fine — means "no pin".
    let asOf: string | undefined;
    if (request.asOf !== undefined && request.asOf !== null) {
      if (typeof request.asOf !== "string" || request.asOf.trim().length === 0) {
        throw new EngramAccessInputError(
          "asOf must be a non-empty ISO 8601 timestamp string",
        );
      }
      const parsed = Date.parse(request.asOf);
      if (!Number.isFinite(parsed)) {
        throw new EngramAccessInputError(
          `asOf must be a parseable ISO 8601 timestamp (got: "${request.asOf}")`,
        );
      }
      asOf = request.asOf;
    }
    let contextComposition: RecallContextComposition | undefined;
    const recallOptions: RecallInvocationOptions = {
      namespace: namespaceOverride,
      topK,
      mode,
      onContextComposition: (composition) => {
        contextComposition = composition;
      },
      onRecallPlanResolved: createRecallCorpusVersionCapture(this.deps.orchestrator, request.abortSignal, (versions) => { storageCorpusVersionsAtRecallStart = mergeRecallCorpusVersions(storageCorpusVersionsAtRecallStart, versions); }, true),
      ...(authenticatedPrincipal ? { principalOverride: authenticatedPrincipal } : {}),
      ...(request.sourceConnector ? { sourceConnector: request.sourceConnector } : {}),
      ...(request.stateView !== undefined ? { stateView: request.stateView } : {}),
      ...(asOf !== undefined ? { asOf } : {}),
      ...(request.includeLowConfidence === true ? { includeLowConfidence: true } : {}),
      ...(request.abortSignal ? { abortSignal: request.abortSignal } : {}),
      // Only surface a real wait: an uncontended recall (queueWaitMs 0) omits
      // the field so recall-timings stays additive and byte-identical to the
      // pre-#1906 uncontended path (acceptance: "record queueWaitMs ~0 or omit").
      ...(typeof request.queueWaitMs === "number" && request.queueWaitMs > 0
        ? { queueWaitMs: request.queueWaitMs }
        : {}),
    };
    const startedAt = Date.now();
    // #1906 atomic budget admission: the peek loop above and this record are
    // one synchronous JS turn (no await between them), so record()'s own
    // atomic project-and-push denies the Nth concurrent cross-namespace recall
    // for a principal BEFORE its pipeline runs — no over-admission. On a
    // pipeline failure/abort the reservation is rolled back (budget.release)
    // so an errored recall does not consume budget permanently.
    let reservedBudgetPrincipal: string | null = null;
    let reservedBudget: BudgetReservation | undefined;
    if (willReserveBudget) {
      const reserveDecision = this.deps.budget.record(principal);
      budgetDecision = reserveDecision;
      if (!reserveDecision.allowed) {
        throw new EngramAccessInputError(
          `recall denied: cross-namespace budget exceeded (${reserveDecision.count}/${reserveDecision.limit.hardLimit} in ${reserveDecision.limit.windowMs}ms window)`,
        );
      }
      reservedBudgetPrincipal = principal;
      reservedBudget = reserveDecision.reservation;
    }
    // #1906 review #5: the rollback covers the ENTIRE post-reservation
    // operation — orchestrator.recall AND serialization / debug / response
    // construction — so ANY failure after the reserve releases the exact
    // budget entry (by token, review #4) instead of leaking it.
    let storageCorpusVersionsAtRecallStart: Array<{ namespace: string; version: number | null }> = [];
    try {
      const context = await this.deps.orchestrator.recall(
        query,
        request.sessionKey,
        recallOptions,
      );
      const assembled = await assembleRecallResponse(this.deps, {
        request,
        context,
        contextComposition,
        storageCorpusVersionsAtRecallStart,
        query,
        mode,
        namespace,
        requestedDisclosure,
        callerProvidedDisclosure,
        topK,
        principal,
        authenticatedPrincipal,
        startedAt,
        budgetDecision,
        budgetRecordPrincipal: reservedBudgetPrincipal,
      });
      // Expose the reservation token so a consumer that fails AFTER this
      // returns (response clone, idempotency put) can release the exact entry
      // (#1906 review round 3, findings #1/#3).
      return { ...assembled, reservation: reservedBudget };
    } catch (err) {
      if (reservedBudget) this.deps.budget.release(reservedBudget);
      throw err;
    }
  }

  /**
   * Recall X-ray (issue #570).  Runs a recall with `xrayCapture: true`
   * and returns the resulting snapshot as structured JSON so every
   * surface (CLI / HTTP / MCP) gets the same payload.  Namespace scope
   * is enforced before the recall fires (CLAUDE.md rule 42 — read and
   * write paths must resolve through the same namespace layer) so an
   * unauthorized principal cannot capture an x-ray for a namespace it
   * cannot read.
   */
  async recallXray(request: {
    query: string;
    sessionKey?: string;
    namespace?: string;
    budget?: number;
    authenticatedPrincipal?: string;
    sourceConnector?: string;
    /**
     * Disclosure depth used to shape per-result payload (issue #677
     * PR 3/4).  When set, each X-ray result is decorated with the
     * matching `disclosure` field and `estimatedTokens` computed from
     * the actual rendered content at that depth, so the renderer's
     * "Token spend by disclosure" summary reflects real spend rather
     * than staying empty when no caller wires the depth knob through.
     */
    disclosure?: RecallDisclosure;
    /**
     * Free-form recall tag filter (issue #689). Mirrors the field on
     * `EngramAccessRecallRequest`. When non-empty, the captured X-ray
     * snapshot's `results` are filtered down to memories whose
     * frontmatter tags satisfy `tagMatch` ("any" by default), and a
     * `tag-filter` entry is appended to `filters`.
     */
    tags?: string[];
    /** Match mode for `tags`. See `EngramAccessRecallRequest.tagMatch`. */
    tagMatch?: "any" | "all";
    /** Recall planner mode override. Mirrors `EngramAccessRecallRequest.mode`. */
    mode?: RecallPlanMode | "auto";
    /**
     * User-aware context scopes active for this recall. Forwarded into
     * provenance construction so boundary scopes are evaluated against
     * the caller's real context instead of an empty-context default.
     */
    currentContextScopes?: readonly unknown[];
    /**
     * Internal inspector affordance: include a recall-shaped response
     * derived from the same X-ray snapshot. Left off by default so the
     * regular X-ray API/CLI/MCP surfaces keep their existing payload shape.
     */
    includeRecall?: boolean;
    /** Cancel the capture before it starts and propagate cancellation to recall. */
    abortSignal?: AbortSignal;
  }): Promise<{
    snapshotFound: boolean;
    snapshot?: RecallXraySnapshot;
    recall?: EngramAccessRecallResponse;
  }> {
    const query = typeof request.query === "string" ? request.query : "";
    if (query.trim().length === 0) {
      // Match the CLI contract (CLAUDE.md rule 51): reject empty
      // input with an explicit error rather than silently producing
      // an empty snapshot.
      throw new Error("recallXray: query is required and must be non-empty");
    }
    // Validate disclosure UP FRONT — before recall executes, before
    // the xray queue mutex is acquired, before namespace resolution.
    // A bad value should fail fast rather than after we've burned
    // cycles on an irreversible recall (Cursor Medium review on PR
    // #699).
    if (
      request.disclosure !== undefined &&
      !isRecallDisclosure(request.disclosure)
    ) {
      throw new EngramAccessInputError(
        `recallXray: disclosure must be one of: chunk, section, raw (got: ${String(request.disclosure)})`,
      );
    }

    const namespacesEnabled = resolveNamespaceCapabilities(this.deps.orchestrator.config).namespaces;
    const requestedNamespace = request.namespace?.trim()
      ? this.deps.resolveNamespace(request.namespace)
      : undefined;
    const authenticatedPrincipal = request.authenticatedPrincipal?.trim();
    const principal =
      authenticatedPrincipal
      || resolvePrincipal(request.sessionKey, this.deps.orchestrator.config);

    if (requestedNamespace) {
      if (
        !canReadNamespace(
          principal,
          requestedNamespace,
          this.deps.orchestrator.config,
        )
      ) {
        return { snapshotFound: false };
      }
    } else if (
      namespacesEnabled
      && !authenticatedPrincipal
      && !request.sessionKey?.trim()
    ) {
      // Namespaces enabled but no identity supplied — reject rather
      // than scanning the global namespace (CLAUDE.md rule 48:
      // least-privileged default).
      return { snapshotFound: false };
    }

    // Optional `--budget` override must be a positive integer.  Invalid
    // values throw rather than silently defaulting (CLAUDE.md rule 51).
    let budgetOverride: number | undefined;
    if (request.budget !== undefined && request.budget !== null) {
      const parsed =
        typeof request.budget === "number"
          ? request.budget
          : Number(request.budget);
      if (
        !Number.isFinite(parsed)
        || parsed <= 0
        || !Number.isInteger(parsed)
      ) {
        throw new Error(
          `recallXray: budget expects a positive integer; got ${JSON.stringify(request.budget)}`,
        );
      }
      budgetOverride = parsed;
    }
    const mode = this.deps.normalizeRecallMode(request.mode);
    const disclosure = request.disclosure ?? DEFAULT_RECALL_DISCLOSURE;

    // Reset when the orchestrator-owned snapshot lock is actually acquired so
    // queue wait is not misreported as recall latency.
    let recallStartedAt = Date.now();

    const recallSessionKey = request.sessionKey?.trim() || undefined;
    let storageCorpusVersionsAtRecallStart: Array<{ namespace: string; version: number | null }> = [];
    let xrayResponse: {
      snapshotFound: boolean;
      snapshot?: RecallXraySnapshot;
    } = { snapshotFound: false };

    {
      // Capture through the orchestrator-owned critical section so every
      // consumer of its mutable snapshot slot shares the same queue. The
      // returned clone remains owned by this call after the lock is released.
      const {
        snapshot: rawSnapshot,
        recallStartedAt: capturedRecallStartedAt,
      } = await this.deps.orchestrator.recallWithXrayCapture(
        query,
        recallSessionKey,
        {
          ...(requestedNamespace ? { namespace: requestedNamespace } : {}),
          ...(budgetOverride !== undefined
            ? { budgetCharsOverride: budgetOverride }
            : {}),
          ...(mode !== undefined ? { mode } : {}),
          onRecallPlanResolved: createRecallCorpusVersionCapture(this.deps.orchestrator, request.abortSignal, (versions) => { storageCorpusVersionsAtRecallStart = mergeRecallCorpusVersions(storageCorpusVersionsAtRecallStart, versions); }, true),
          // When the caller supplies an authenticated principal, forward
          // it via the dedicated override channel so orchestrator-side
          // ACL decisions use the SAME principal the access-surface
          // pre-check above authorized.  Threading an
          // `authenticatedPrincipal` through `sessionKey` would be wrong:
          // `resolvePrincipal(sessionKey)` only maps configured raw
          // session keys and otherwise collapses to `"default"`, which
          // in namespace-enabled deployments produces false denials /
          // wrong-scope serving despite the pre-check passing
          // (CLAUDE.md rule 42).
          ...(authenticatedPrincipal
            ? { principalOverride: authenticatedPrincipal }
            : {}),
          ...(request.sourceConnector ? { sourceConnector: request.sourceConnector } : {}),
          ...(request.currentContextScopes !== undefined
            ? { currentContextScopes: request.currentContextScopes }
            : {}),
          ...(request.abortSignal ? { abortSignal: request.abortSignal } : {}),
        },
      );
      recallStartedAt = capturedRecallStartedAt;
      // Cancellation covers queueing + recall/capture. Post-capture shaping is
      // intentionally not wired for mid-I/O abort in this change, but do not
      // begin that work after the caller has already canceled.
      throwIfAborted(request.abortSignal, "recall X-ray aborted before postprocessing");
      // Re-check namespace after capture: the recall may have served
      // from a different namespace than the caller requested.  Drop
      // the snapshot rather than leak cross-tenant data (CLAUDE.md
      // rules 42 + 47).  The comparison is strict so a snapshot whose
      // namespace is `undefined` cannot bypass the scope the caller
      // asked for.
      const namespaceMismatch =
        requestedNamespace !== undefined &&
        rawSnapshot?.namespace !== requestedNamespace;
      if (!rawSnapshot) {
        xrayResponse = { snapshotFound: false };
      } else if (namespaceMismatch) {
        xrayResponse = { snapshotFound: false };
      } else {
        // Tag filter (issue #689). Mirrors `recall()` semantics — applied
        // post-capture by reading each result's frontmatter tags and
        // dropping non-matching results. Filter activity surfaces as a
        // `tag-filter` entry in `snapshot.filters` so X-ray consumers can
        // see the "considered → admitted" delta.
        let snapshot = rawSnapshot;
        const xrayFilterTags = normalizeTags(request.tags);
        let xrayTagMatch: TagMatchMode | undefined;
        try {
          xrayTagMatch = parseTagMatch(request.tagMatch);
        } catch (err) {
          throw new EngramAccessInputError(
            err instanceof Error ? err.message : String(err),
          );
        }
        if (xrayFilterTags && xrayFilterTags.length > 0) {
          const namespace = snapshot.namespace
            ? this.deps.resolveNamespace(snapshot.namespace)
            : this.deps.orchestrator.config.defaultNamespace;
          const tagsByIndex = await Promise.all(
            snapshot.results.map(async (result) => {
              try {
                const storage = await this.deps.orchestrator.getStorage(namespace);
                const memory = await storage.readMemoryByPath(result.path);
                const t = memory?.frontmatter?.tags;
                // Normalize identically to the recall path
                // (`normalizeProjectionTags`): trim and drop empty strings
                // so X-ray tag matching stays consistent with the recall
                // surface. Without this, a frontmatter tag like " draft "
                // would match in recall but not in X-ray (cursor review).
                return Array.isArray(t) ? normalizeProjectionTags(t) : [];
              } catch {
                return [];
              }
            }),
          );
          const tagged = snapshot.results.map((result, index) => ({
            result,
            tags: tagsByIndex[index] ?? [],
          }));
          const { results: admittedTagged, trace } = applyTagFilter(tagged, {
            tags: xrayFilterTags,
            tagMatch: xrayTagMatch,
          });
          const admittedResults = admittedTagged.map((entry) => entry.result);
          const filters = trace ? [...snapshot.filters, trace] : snapshot.filters;
          snapshot = { ...snapshot, results: admittedResults, filters };
        }
        // Decorate per-result disclosure + token estimate when the caller
        // wired a depth knob (issue #677 PR 3/4 — codex review on #699
        // flagged that the renderer's per-disclosure summary stays empty
        // until callers populate these fields).  Estimate tokens from
        // the actual rendered payload at the requested depth so the
        // summary reflects real spend; chunk uses the preview, section
        // and raw use full content.  Best-effort only — a missing
        // memory or read failure is silently dropped (CLAUDE.md rule 13).
        if (request.disclosure !== undefined) {
          // Disclosure already validated up front; pin to the narrowed
          // type here.  Re-validation inside the queue would be dead code.
          const disclosure: RecallDisclosure = request.disclosure;
          const namespace = snapshot.namespace
            ? this.deps.resolveNamespace(snapshot.namespace)
            : this.deps.orchestrator.config.defaultNamespace;
          // Pre-fetch raw excerpts ONCE so the first raw-disclosure
          // result's token estimate includes the LCM-side excerpt spend
          // that `shapeMemorySummary` actually attaches in the recall
          // response.  Without this, raw recalls systematically
          // undercounted spend on the first result (Cursor Medium review
          // on PR #699).  Excerpts are scoped to the same session +
          // namespace as the recall.
          // Trim sessionKey to match what `orchestrator.recall(...)`
          // already does (`request.sessionKey?.trim() || undefined`),
          // otherwise a whitespace-padded key drives recall under one
          // identity but probes LCM under a different prefix and
          // misses stored excerpts (Cursor Low review on PR #699).
          const trimmedSessionKey = request.sessionKey?.trim() || undefined;
          // Read-authorization-gated namespace for the raw-excerpt LCM lookup
          // (#1505 thread 2f7). NOT `snapshot.namespace` (the write/overlay
          // namespace), which would attach `<principal>-project-*` overlay rows
          // when the principal can WRITE but not READ its self base. Mirrors the
          // recall + `lcmSearch` read gate. Resolved ONLY for raw disclosure (its
          // sole consumer); the `namespace` above is still used for the
          // memory-FILE reads below (a separate, snapshot-scoped read), so non-raw
          // x-ray decoration stays byte-for-byte unchanged.
          const rawExcerptNamespace =
            disclosure === "raw"
              ? this.deps.resolveRawExcerptReadNamespace(
                  request.namespace,
                  trimmedSessionKey,
                  authenticatedPrincipal,
                )
              : namespace;
          // `undefined` for an IMPLICIT raw recall means NO readable LCM namespace
          // exists (restrictive `default` READ policy, no readable overlay/self)
          // — suppress excerpts rather than fall back to the write/overlay
          // namespace the read gate excludes (#1505 thread NBHWz).
          const xrayHasExplicitNamespace =
            typeof request.namespace === "string" &&
            request.namespace.trim().length > 0;
          const rawExcerptsSuppressed =
            disclosure === "raw" &&
            !xrayHasExplicitNamespace &&
            rawExcerptNamespace === undefined;
          // Ordered, read-authorized LCM read key SET (#1505 fallback
          // unification) so raw disclosure finds excerpts a branch-scoped session
          // archived at project/root scope — exactly as recall + `lcmSearch` do.
          // Only meaningful with a concrete sessionKey + a readable namespace;
          // already read-gated so no unauthorized overlay key is present.
          const rawExcerptSessionIds =
            disclosure === "raw" && trimmedSessionKey && rawExcerptNamespace
              ? this.deps.resolveLcmReadSessionIds(
                  request.namespace,
                  rawExcerptNamespace,
                  trimmedSessionKey,
                  authenticatedPrincipal,
                )
              : undefined;
          const rawExcerpts =
            disclosure === "raw" && !rawExcerptsSuppressed
              ? await this.deps.fetchRawExcerpts(disclosure, {
                  query,
                  ...(trimmedSessionKey ? { sessionKey: trimmedSessionKey } : {}),
                  ...(rawExcerptNamespace
                    ? { namespace: rawExcerptNamespace }
                    : {}),
                  ...(rawExcerptSessionIds !== undefined
                    ? { lcmSessionIds: rawExcerptSessionIds }
                    : {}),
                })
              : disclosure === "raw"
                ? []
                : null;
          const rawExcerptText =
            rawExcerpts && rawExcerpts.length > 0
              ? rawExcerpts.map((e) => e.content).join("\n")
              : "";
          // Pre-load every memory in parallel so we can:
          //   (a) re-attribute raw excerpts to the *first readable* result
          //       rather than always to index 0 (Cursor Low review on PR
          //       #699: a missing/unreadable result[0] orphaned the excerpt
          //       budget); and
          //   (b) include the metadata fields `shapeMemorySummary` actually
          //       emits at every depth (id, path, category, status, created,
          //       updated, tags, entityRef) in the token estimate, so the
          //       summary reflects real spend rather than only payload-body
          //       spend (Cursor Low review on PR #699).
          const memoryByIndex = await Promise.all(
            snapshot.results.map(async (result) => {
              try {
                const storage = await this.deps.orchestrator.getStorage(namespace);
                return await storage.readMemoryByPath(result.path);
              } catch {
                return null;
              }
            }),
          );
          const firstReadableIndex = memoryByIndex.findIndex((m) => m !== null);
          const baseDir =
            (await this.deps.orchestrator.getStorage(namespace)).dir;
          const decorated = snapshot.results.map((result, index) => {
            const memory = memoryByIndex[index];
            if (!memory) {
              // Unreadable result: attach the disclosure tag anyway so
              // the per-disclosure summary classifies it correctly,
              // but skip the token estimate since we don't have the
              // content to measure.  Without the disclosure tag the
              // result silently flows into the `unspecified` bucket
              // even though the caller explicitly requested a depth
              // (Cursor Low review on PR #699).
              return { ...result, disclosure };
            }
            // Build a representative shaped summary so the estimate
            // counts every field `shapeMemorySummary` actually emits.
            // The serialized JSON form is a close-enough proxy for the
            // wire payload size.
            const shaped = shapeMemorySummary(
              memory,
              baseDir,
              disclosure,
              disclosure === "raw" &&
              index === firstReadableIndex &&
              rawExcerpts &&
              rawExcerpts.length > 0
                ? rawExcerpts
                : undefined,
            );
            return {
              ...result,
              disclosure,
              estimatedTokens: estimateRecallTokens(JSON.stringify(shaped)),
            };
          });
          // Edge case: every result was unreadable but rawExcerpts
          // still has content — credit that spend to result[0] rather
          // than dropping it on the floor.  Without this, the raw row
          // in the per-disclosure summary under-reports spend whenever
          // every memory file is missing/unreadable.
          if (
            disclosure === "raw" &&
            firstReadableIndex === -1 &&
            rawExcerptText.length > 0 &&
            decorated.length > 0
          ) {
            decorated[0] = {
              ...decorated[0]!,
              disclosure,
              estimatedTokens: estimateRecallTokens(rawExcerptText),
            };
          }
          const decoratedSnapshot = { ...snapshot, results: decorated };
          xrayResponse = {
            snapshotFound: true,
            snapshot: decoratedSnapshot,
          };
        } else {
          xrayResponse = {
            snapshotFound: true,
            snapshot,
          };
        }
      }
    }

    if (
      request.includeRecall === true &&
      xrayResponse.snapshotFound === true &&
      xrayResponse.snapshot
    ) {
      // Same read-authorization-gated raw-excerpt namespace the recall path uses
      // (#1505 thread 2f7), so the includeRecall x-ray path can't leak overlay
      // transcript rows via raw disclosure. Resolved ONLY for raw disclosure (the
      // sole consumer) so non-raw x-ray recall stays byte-for-byte unchanged. The
      // ordered LCM read key SET (#1505 fallback unification) adds the coding read
      // fallbacks so a branch-scoped session also finds excerpts at project/root
      // scope.
      const xrayRawExcerptNamespace =
        disclosure === "raw"
          ? this.deps.resolveRawExcerptReadNamespace(
              request.namespace,
              recallSessionKey,
              authenticatedPrincipal,
            )
          : undefined;
      // `undefined` for an IMPLICIT raw recall means NO readable LCM namespace
      // exists — suppress excerpts rather than fall back to the write/overlay
      // namespace the read gate excludes (#1505 thread NBHWz).
      const xrayHasExplicitNamespace =
        typeof request.namespace === "string" &&
        request.namespace.trim().length > 0;
      const xrayRawExcerptsSuppressed =
        disclosure === "raw" &&
        !xrayHasExplicitNamespace &&
        xrayRawExcerptNamespace === undefined;
      const xrayRawExcerptSessionIds =
        disclosure === "raw" && xrayRawExcerptNamespace && recallSessionKey
          ? this.deps.resolveLcmReadSessionIds(
              request.namespace,
              xrayRawExcerptNamespace,
              recallSessionKey,
              authenticatedPrincipal,
            )
          : undefined;
      return {
        ...xrayResponse,
        recall: await this.deps.buildRecallResponseFromXraySnapshot({
          query,
          sessionKey: recallSessionKey,
          snapshot: xrayResponse.snapshot,
          disclosure,
          startedAt: recallStartedAt,
          requestedMode: request.mode,
          normalizedMode: mode,
          storageCorpusVersionsAtRecallStart,
          ...(xrayRawExcerptNamespace
            ? { rawExcerptNamespace: xrayRawExcerptNamespace }
            : {}),
          ...(xrayRawExcerptSessionIds !== undefined
            ? { rawExcerptSessionIds: xrayRawExcerptSessionIds }
            : {}),
          ...(xrayRawExcerptsSuppressed
            ? { rawExcerptsSuppressed: xrayRawExcerptsSuppressed }
            : {}),
        }),
      };
    }
    return xrayResponse;
  }
}

/**
 * Category-alias split + replay restamp for observe/write (#2829).
 * Extracted from access-observe-write-surface.ts to stay under the 1200-line cap.
 *
 * The wire schema already maps an alias to "fact". `rawCategory` is the
 * caller's spelling: it must not reach the write candidate or fingerprint,
 * and a replay must rebuild the note from THIS request's spelling.
 */
import {
  canonicalCategoryForAlias,
  categoryAliasCoercion,
  reapplyCategoryCoercion,
  type CategoryAliasCoercion,
  type MemoryCategoryAlias,
} from "./access-schema.js";

export { reapplyCategoryCoercion };
export { buildWithBriefingLocation } from "./location/tagging.js";

export function splitCanonicalWriteRequest<T extends { rawCategory?: string; category?: string }>(
  request: T,
): {
  canonical: Omit<T, "rawCategory">;
  categoryCoercion: CategoryAliasCoercion | undefined;
} {
  const { rawCategory, ...canonical } = request;
  // #2962: a direct service caller bypasses the wire schema, so an accepted
  // alias can still sit on `category`. Canonicalize it at the same boundary
  // the schema's transform covers for HTTP/MCP/CLI, minting the retained
  // spelling from the request itself. A schema-minted `rawCategory` always
  // wins (it names the spelling the transform actually canonicalized);
  // near-misses pass through untouched and reject at the write candidate
  // with the attempted category echoed.
  if (rawCategory === undefined && typeof canonical.category === "string") {
    const mapped = canonicalCategoryForAlias(canonical.category);
    if (mapped !== undefined) {
      const from = canonical.category as MemoryCategoryAlias;
      return {
        canonical: { ...canonical, category: mapped } as Omit<T, "rawCategory">,
        categoryCoercion: { from, to: mapped },
      };
    }
  }
  return { canonical, categoryCoercion: categoryAliasCoercion(rawCategory) };
}

import * as nodePath from "node:path";
import { offlineSyncStorageForSnapshot } from "./offline-sync-impression-drain.js";
import { iterateOfflineSyncSnapshotFileRecords } from "./offline-sync.js";
import type { Orchestrator } from "./orchestrator.js";
import {
  CONTENT_HASH_NORMALIZER_VERSION,
  IDENTITY_RESOLUTION_VERSION,
  RECONCILE_MANIFEST_FORMAT,
  RECONCILE_MANIFEST_SCHEMA_VERSION,
  type ReconcileManifest,
  type ReconcileManifestFile,
  type ReconcileMemoryIdentity,
  type ReconcileMemoryParser,
  buildReconcileManifestFile,
  citationTemplateFingerprint,
  isCachedIdentityReusable,
  isReconcileMemoryIdentity,
} from "./reconcile/manifest.js";
import { createPersistedSupportPassportPrivateFileExclusion } from "./support-passport/card-projection.js";

export interface OfflineSyncManifestRequest {
  includeTranscripts?: boolean;
  signal?: AbortSignal;
}

export interface OfflineSyncManifestStreamResponse extends Omit<ReconcileManifest, "files"> {
  namespace: string;
  files: AsyncIterable<ReconcileManifestFile>;
}

export interface ServerIdentityCacheEntry {
  path: string;
  sha256: string;
  memory?: ReconcileMemoryIdentity;
  /** Stamped on sha-only entries so an upgrade re-parses them. */
  normalizerVersion?: number;
  identityResolutionVersion?: number;
  /** Stat identity the exclusion classification was computed against. */
  statIdentity?: string;
  /** Persisted support-passport private-memory classification for statIdentity. */
  excluded?: boolean;
}

/**
 * Decide what the manifest stream should persist, and whether a write is
 * needed at all.
 *
 * A write is required whenever the persisted set changed — an identity was
 * rebuilt, or an entry was dropped because its file lost its identity — and
 * also when a completed walk leaves entries for paths it never saw, which are
 * files that have since been deleted. Skipping the write in that last case
 * would strand those entries on disk forever.
 *
 * Pruning is gated on the walk completing: an aborted or partially consumed
 * stream has simply not observed the remaining paths, so it may only add.
 */
export function planServerIdentityCacheWrite(input: {
  persisted: ReadonlyMap<string, ServerIdentityCacheEntry>;
  yieldedPaths: ReadonlySet<string>;
  /** Paths the walk saw but never yielded (removed by the exclusion
   * callback). Not deleted — pruning them would drop their persisted
   * classification and force a re-classify on every later cycle. */
  retainedPaths?: ReadonlySet<string>;
  streamCompleted: boolean;
  cacheDirty: boolean;
}): { shouldWrite: boolean; entries: ServerIdentityCacheEntry[] } {
  const entries = input.streamCompleted
    ? [...input.persisted.values()].filter(
        (entry) => input.yieldedPaths.has(entry.path) || input.retainedPaths?.has(entry.path)
      )
    : [...input.persisted.values()];
  return { shouldWrite: input.cacheDirty || entries.length !== input.persisted.size, entries };
}

/**
 * The cache lives under `.remnic/` rather than `state/`: snapshot enumeration
 * excludes internal `.remnic/` paths structurally (`isInternalRemnicStatePath`),
 * whereas `state/` is only filtered by an allowlist of known node-local
 * artifacts. Under `state/` this node-local cache would be advertised as a peer
 * file, so convergence would transfer the cache itself — and the stream rewrites
 * it during finalization, so the advertised digest could go stale mid-transfer.
 */
function serverIdentityCachePath(storageDir: string): string {
  return nodePath.join(storageDir, ".remnic", "state", "converge-identity-cache.json");
}

async function loadServerIdentityCache(
  storageDir: string,
  citationTemplate?: string
): Promise<Map<string, ServerIdentityCacheEntry>> {
  const cache = new Map<string, ServerIdentityCacheEntry>();
  try {
    const raw = JSON.parse(
      await import("node:fs/promises").then((fs) => fs.readFile(serverIdentityCachePath(storageDir), "utf8"))
    ) as {
      citationTemplate?: string;
      files?: unknown[];
    };
    // Identities are derived after stripping inline attribution for a specific
    // citation template; entries written under a different one would produce
    // wrong contentHash values for unchanged files.
    if (raw.citationTemplate !== citationTemplateFingerprint(citationTemplate)) return cache;
    for (const candidate of raw.files ?? []) {
      const entry = candidate as Partial<ServerIdentityCacheEntry> | null;
      if (typeof entry?.path !== "string" || typeof entry.sha256 !== "string") continue;
      if (entry.memory !== undefined && !isReconcileMemoryIdentity(entry.memory)) continue;
      if (entry.statIdentity !== undefined && typeof entry.statIdentity !== "string") continue;
      if (entry.excluded !== undefined && typeof entry.excluded !== "boolean") continue;
      if (entry.normalizerVersion !== undefined && typeof entry.normalizerVersion !== "number") continue;
      if (entry.identityResolutionVersion !== undefined && typeof entry.identityResolutionVersion !== "number") {
        continue;
      }
      cache.set(entry.path, {
        path: entry.path,
        sha256: entry.sha256,
        ...(entry.memory ? { memory: entry.memory } : {}),
        ...(entry.memory
          ? {}
          : {
              ...(typeof entry.normalizerVersion === "number" ? { normalizerVersion: entry.normalizerVersion } : {}),
              ...(typeof entry.identityResolutionVersion === "number"
                ? { identityResolutionVersion: entry.identityResolutionVersion }
                : {}),
            }),
        ...(entry.statIdentity !== undefined && entry.excluded !== undefined
          ? { statIdentity: entry.statIdentity, excluded: entry.excluded }
          : {}),
      });
    }
  } catch {
    // missing or corrupt cache: cold build
  }
  return cache;
}

const serverIdentityCacheWriteLocks = new Map<string, Promise<void>>();

/** Serialize cache replacements per path: overlapping manifest streams for one
 * namespace would otherwise each publish a whole-file snapshot, and the slower
 * stream built from older filesystem state would overwrite the newer one. */
async function withServerIdentityCacheWriteLock(cachePath: string, write: () => Promise<void>): Promise<void> {
  const previous = serverIdentityCacheWriteLocks.get(cachePath) ?? Promise.resolve();
  const next = previous.then(write, write);
  serverIdentityCacheWriteLocks.set(cachePath, next);
  try {
    await next;
  } finally {
    if (serverIdentityCacheWriteLocks.get(cachePath) === next) {
      serverIdentityCacheWriteLocks.delete(cachePath);
    }
  }
}

/** Union of the entries being written and the current on-disk set; on conflict
 * the write wins (it reflects the newer run). Callers hold the write lock. */
export async function mergeServerIdentityCacheEntries(
  fs: typeof import("node:fs/promises"),
  cachePath: string,
  entries: readonly ServerIdentityCacheEntry[],
  citationTemplate: string | undefined,
  dropped: ReadonlySet<string> = new Set()
): Promise<ServerIdentityCacheEntry[]> {
  const merged = new Map(entries.map((entry) => [entry.path, entry]));
  try {
    const raw = JSON.parse(await fs.readFile(cachePath, "utf8")) as {
      citationTemplate?: string;
      files?: unknown[];
    };
    if (raw.citationTemplate === citationTemplateFingerprint(citationTemplate)) {
      for (const candidate of raw.files ?? []) {
        const entry = candidate as Partial<ServerIdentityCacheEntry> | null;
        if (typeof entry?.path !== "string" || typeof entry.sha256 !== "string") continue;
        if (entry.memory !== undefined && !isReconcileMemoryIdentity(entry.memory)) continue;
        if (dropped.has(entry.path) || merged.has(entry.path)) continue;
        merged.set(entry.path, {
          path: entry.path,
          sha256: entry.sha256,
          ...(entry.memory ? { memory: entry.memory } : {}),
          ...(entry.memory
            ? {}
            : {
                ...(typeof entry.normalizerVersion === "number" ? { normalizerVersion: entry.normalizerVersion } : {}),
                ...(typeof entry.identityResolutionVersion === "number"
                  ? { identityResolutionVersion: entry.identityResolutionVersion }
                  : {}),
              }),
          ...(entry.statIdentity !== undefined && entry.excluded !== undefined
            ? { statIdentity: entry.statIdentity, excluded: entry.excluded }
            : {}),
        });
      }
    }
  } catch {
    // missing or unreadable current cache: the write set stands alone
  }
  return [...merged.values()];
}

/** Record classifications for files the walk excluded (the exclusion callback
 * returned true, so they were never yielded): they were seen this walk, so
 * their entries must persist and must not be pruned as deleted. Mirrors the
 * per-yield classification application for never-yielded paths. */
export function retainExcludedClassifications(input: {
  persisted: Map<string, ServerIdentityCacheEntry>;
  classifications: ReadonlyMap<string, { statIdentity: string; excluded: boolean }>;
  yieldedPaths: ReadonlySet<string>;
}): { retained: Set<string>; changed: boolean } {
  const retained = new Set<string>();
  let changed = false;
  for (const [pathName, classification] of input.classifications) {
    if (input.yieldedPaths.has(pathName)) continue;
    retained.add(pathName);
    const entry = input.persisted.get(pathName) ?? { path: pathName, sha256: "" };
    if (entry.statIdentity === classification.statIdentity && entry.excluded === classification.excluded) {
      continue;
    }
    input.persisted.set(pathName, {
      ...entry,
      statIdentity: classification.statIdentity,
      excluded: classification.excluded,
    });
    changed = true;
  }
  return { retained, changed };
}

export async function createOfflineSyncManifestStream(
  orchestrator: Orchestrator,
  namespace: string,
  userExcludeRegexps: RegExp[],
  options: OfflineSyncManifestRequest,
  parseMemory: ReconcileMemoryParser
): Promise<OfflineSyncManifestStreamResponse> {
  const storage = await offlineSyncStorageForSnapshot(orchestrator, namespace);
  const citationTemplate = orchestrator.config.inlineSourceAttributionFormat;
  const identityCache = await loadServerIdentityCache(storage.dir, citationTemplate);
  // The exclusion callback runs before every yield; without the persisted
  // classification it would read and parse every candidate file, defeating the
  // warm-cache skip entirely.
  const classificationUpdates = new Map<string, { statIdentity: string; excluded: boolean }>();
  const snapshotFiles = iterateOfflineSyncSnapshotFileRecords({
    root: storage.dir,
    includeContent: false,
    includeTranscripts: options.includeTranscripts !== false,
    readFileDigest: async ({ filePath }) => storage.digestOfflineSyncFile(filePath),
    signal: options.signal,
    userExcludeRegexps,
    excludeFile: createPersistedSupportPassportPrivateFileExclusion(storage, identityCache, classificationUpdates),
  });
  return {
    namespace,
    format: RECONCILE_MANIFEST_FORMAT,
    schemaVersion: RECONCILE_MANIFEST_SCHEMA_VERSION,
    files: (async function* () {
      // Any change to the persisted set, not just a rebuilt identity: a file
      // that lost its identity, or a completed walk that must prune vanished
      // paths, also has to reach disk or the removal is lost forever.
      let cacheDirty = false;
      let streamCompleted = false;
      // Seeded with every previously cached entry so a partially consumed
      // stream (client disconnect, abort) can only add to the cache. Writing
      // just this run's rebuilds would drop every cache hit, so one edit to a
      // large corpus would shrink the cache to that single entry and force a
      // near-cold rebuild on the next request.
      const persistedEntries = new Map(identityCache);
      const yieldedPaths = new Set<string>();
      const retainedPaths = new Set<string>();
      const flush = async (): Promise<void> => {
        const { shouldWrite, entries } = planServerIdentityCacheWrite({
          persisted: persistedEntries,
          yieldedPaths,
          retainedPaths,
          streamCompleted,
          cacheDirty,
        });
        if (!shouldWrite) return;
        try {
          const fs = await import("node:fs/promises");
          const cachePath = serverIdentityCachePath(storage.dir);
          await withServerIdentityCacheWriteLock(cachePath, async () => {
            // Merge with whatever is on disk NOW: a concurrent stream for the
            // same namespace may have published newer entries after this
            // request loaded its snapshot, and a blind whole-file replace
            // would discard them.
            const written = new Set(entries.map((entry) => entry.path));
            const dropped = streamCompleted
              ? new Set([...identityCache.keys()].filter((pathName) => !written.has(pathName)))
              : new Set<string>();
            const merged = await mergeServerIdentityCacheEntries(
              fs,
              cachePath,
              entries,
              citationTemplate,
              dropped
            );
            await fs.mkdir(nodePath.dirname(cachePath), { recursive: true });
            const tmp = `${cachePath}.${process.pid}.${Math.random().toString(36).slice(2)}.tmp`;
            await fs.writeFile(
              tmp,
              JSON.stringify({ citationTemplate: citationTemplateFingerprint(citationTemplate), files: merged })
            );
            await fs.rename(tmp, cachePath);
          });
        } catch {
          // cache persistence is best-effort
        }
      };
      try {
        const applyClassification = (path: string, sha256: string): void => {
          const classification = classificationUpdates.get(path);
          if (classification === undefined) return;
          const entry = persistedEntries.get(path) ?? { path, sha256 };
          if (entry.statIdentity === classification.statIdentity && entry.excluded === classification.excluded) {
            return;
          }
          persistedEntries.set(path, {
            ...entry,
            ...(entry.memory ? { memory: entry.memory } : {}),
            statIdentity: classification.statIdentity,
            excluded: classification.excluded,
          });
          cacheDirty = true;
        };
        for await (const file of snapshotFiles) {
          yieldedPaths.add(file.path);
          const cached = identityCache.get(file.path);
          if (
            cached !== undefined &&
            cached.sha256.toLowerCase() === file.sha256.toLowerCase() &&
            isCachedIdentityReusable(cached)
          ) {
            applyClassification(file.path, file.sha256);
            yield {
              ...file,
              ...(cached.memory
                ? { memory: cached.memory }
                : {
                    normalizerVersion: cached.normalizerVersion,
                    identityResolutionVersion: cached.identityResolutionVersion,
                  }),
            };
            continue;
          }
          const built = await buildReconcileManifestFile(
            file,
            async ({ path }) => storage.readOfflineSyncFile(nodePath.join(storage.dir, path)),
            parseMemory,
            citationTemplate
          );
          // Negative results persist too: a memory-shaped file that parses
          // without an identity would otherwise be re-read on every warm run.
          const previous = persistedEntries.get(built.path);
          if (previous?.sha256 !== built.sha256 || (built.memory !== undefined && previous?.memory !== built.memory)) {
            cacheDirty = true;
          }
          if (built.memory === undefined && built.normalizerVersion === undefined) {
            // Read failed: do not persist a negative identity for this SHA.
            yield built;
            continue;
          }
          persistedEntries.set(built.path, {
            path: built.path,
            sha256: built.sha256,
            ...(built.memory !== undefined
              ? { memory: built.memory }
              : {
                  normalizerVersion: built.normalizerVersion,
                  identityResolutionVersion: built.identityResolutionVersion,
                }),
          });
          applyClassification(built.path, built.sha256);
          yield built;
        }
        streamCompleted = true;
      } finally {
        // Files the exclusion callback removed from the snapshot were seen
        // this walk but never yielded: persist their classifications so the
        // next cycle skips the read+parse, and keep them out of the
        // deleted-path prune.
        const retained = retainExcludedClassifications({
          persisted: persistedEntries,
          classifications: classificationUpdates,
          yieldedPaths,
        });
        for (const pathName of retained.retained) retainedPaths.add(pathName);
        if (retained.changed) cacheDirty = true;
        await flush();
      }
    })(),
  };
}

// Streaming offline-sync snapshot builder (PR #3148 round 5). Extracted from
// access-service.ts so the god-file line-count ratchet does not grow: the
// stream carries whole-generation omission metadata alongside the file walk,
// so a filtered embedding generation is announced instead of looking deleted.
import { createHash } from "node:crypto";
import type {
  OfflineSyncDeletionRevision,
  OfflineSyncFileRecord,
  OfflineSyncSnapshot,
} from "./offline-sync.js";
import {
  filterOfflineSyncDeletionRevisions,
  OFFLINE_SYNC_SNAPSHOT_FORMAT,
  iterateOfflineSyncSnapshotFileRecords,
} from "./offline-sync.js";
import {
  computeOmittedEmbeddingGenerationPaths,
  embeddingGenerationMembership,
} from "./offline-sync-embedding-generation.js";
import type { OfflineSyncExcludeFile, OfflineSyncFileTarget } from "./offline-sync-file-io.js";
import { matchesOfflineSyncDefaultExclude } from "./offline-sync-exclude-globs.js";
import type { OfflineSyncFileDigest } from "./offline-sync.js";

export interface OfflineSyncSnapshotStreamBuildOptions {
  root: string;
  namespace: string;
  includeContent: boolean;
  includeTranscripts: boolean;
  userExcludeRegexps?: readonly RegExp[];
  excludeFile: OfflineSyncExcludeFile;
  readFile: (target: OfflineSyncFileTarget) => Promise<Buffer>;
  readFileDigest: (target: OfflineSyncFileTarget) => Promise<OfflineSyncFileDigest>;
  deletions: readonly OfflineSyncDeletionRevision[];
  signal?: AbortSignal;
}

export type OfflineSyncSnapshotStreamBuild = Omit<OfflineSyncSnapshot, "files"> & {
  namespace: string;
  files: AsyncIterable<OfflineSyncFileRecord>;
};

/**
 * Build the streamed snapshot response: whole-generation omission computed
 * with the SAME filters the walk uses and announced in the header, so the
 * receiver never interprets a filtered generation as deleted.
 */
export async function buildEmbeddingAwareSnapshotStream(
  options: OfflineSyncSnapshotStreamBuildOptions,
): Promise<OfflineSyncSnapshotStreamBuild> {
  const storageHash = createHash("sha256").update(options.root).digest("hex").slice(0, 16);
  // Deletions: the canonical filter (exclusions + stale-tombstone exists
  // check) FIRST, then whole-generation suppression so a filtered generation
  // is never announced as deleted (PR #3148 round 6).
  const deletions = await filterOfflineSyncDeletionRevisions({
    root: options.root,
    deletions: options.deletions,
    includeTranscripts: options.includeTranscripts,
    userExcludeRegexps: options.userExcludeRegexps,
    excludeFile: options.excludeFile,
  });
  const omission = await computeOmittedEmbeddingGenerationPaths({
    rootAbs: options.root,
    userExcludeRegexps: options.userExcludeRegexps,
    excludeFile: options.excludeFile,
    // RAW pre-filter tombstones (see resolvePushEmbeddingGenerationState).
    tombstonedPaths: options.deletions.map((deletion) => deletion.path),
    isExcludedRelPath: (relPath) =>
      matchesOfflineSyncDefaultExclude(relPath) ||
      Boolean(options.userExcludeRegexps?.some((re) => re.test(relPath))),
  });
  const omittedDirs = new Set(omission.omittedDirs);
  const deletionsAfterGenerationSuppression = deletions.filter((deletion) => {
    const membership = embeddingGenerationMembership(deletion.path);
    return !(membership && omittedDirs.has(membership.shardDir));
  });
  return {
    namespace: options.namespace,
    format: OFFLINE_SYNC_SNAPSHOT_FORMAT,
    schemaVersion: 1,
    createdAt: new Date().toISOString(),
    sourceId: `remnic:${options.namespace}:${storageHash}`,
    includeTranscripts: options.includeTranscripts,
    deletions: deletionsAfterGenerationSuppression,
    ...(omission.omittedDirs.length > 0
      ? { omittedEmbeddingGenerationDirs: omission.omittedDirs }
      : {}),
    files: iterateOfflineSyncSnapshotFileRecords({
      root: options.root,
      includeContent: options.includeContent,
      includeTranscripts: options.includeTranscripts,
      readFile: options.readFile,
      readFileDigest: options.readFileDigest,
      signal: options.signal,
      userExcludeRegexps: options.userExcludeRegexps,
      excludeFile: options.excludeFile,
      skipEmbeddingGenerationPaths: omission.omittedPaths,
    }),
  };
}

import { createHash } from "node:crypto";

import { EngramAccessInputError } from "../access-service.js";
import type { CorrectionPlan, CorrectionRequest } from "../correction/index.js";
import type { Orchestrator } from "../orchestrator.js";
import type { MemoryLifecycleEvent } from "../types.js";
import {
  ReviewDeckCursorError,
  buildReviewDeckPage,
  type ReviewDeckActionReceipt,
  type ReviewDeckActionRequest,
  type ReviewDeckPage,
  type ReviewDeckUndoRequest,
} from "./review-deck.js";
import {
  executeReviewDeckAction,
  executeReviewDeckUndo,
  type ReviewDeckMutationContext,
} from "./review-deck-mutation.js";
import { readReviewDeckSnapshot } from "./review-deck-snapshot.js";

export interface ReviewDeckSurfaceDeps {
  readonly orchestrator: Orchestrator;
  resolveReadableNamespace(namespace: string | undefined, principal?: string): string;
  writableNamespaceFor(
    namespace: string | undefined,
    sessionKey: string | undefined,
    authenticatedPrincipal?: string,
  ): string;
  correctionPlan(request: CorrectionRequest, opts?: { abortSignal?: AbortSignal }): Promise<CorrectionPlan>;
}

function digest(value: string): string {
  return createHash("sha256").update(value).digest("hex");
}

export class ReviewDeckSurface {
  constructor(private readonly deps: ReviewDeckSurfaceDeps) {}

  async list(opts: {
    namespace?: string;
    principal?: string;
    cursor?: string;
    limit: number;
  }): Promise<ReviewDeckPage> {
    const namespace = this.deps.resolveReadableNamespace(opts.namespace, opts.principal);
    const storage = await this.deps.orchestrator.getStorage(namespace);
    const snapshot = readReviewDeckSnapshot({ memoryDir: storage.dir, namespace });
    try {
      return buildReviewDeckPage(snapshot.rows, {
        scope: {
          principalDigest: digest(opts.principal ?? ""),
          namespace,
          filterDigest: digest(""),
          corpusVersion: snapshot.corpusVersion,
        },
        cursor: opts.cursor,
        limit: opts.limit,
      });
    } catch (error) {
      if (error instanceof ReviewDeckCursorError) {
        throw new EngramAccessInputError(error.message);
      }
      throw error;
    }
  }

  async action(
    req: ReviewDeckActionRequest,
    opts: { namespace?: string; principal?: string; signal?: AbortSignal },
  ): Promise<ReviewDeckActionReceipt> {
    return executeReviewDeckAction(await this.mutationContext(opts), req);
  }

  async undo(
    req: ReviewDeckUndoRequest,
    opts: { namespace?: string; principal?: string; signal?: AbortSignal },
  ): Promise<ReviewDeckActionReceipt> {
    return executeReviewDeckUndo(await this.mutationContext(opts), req);
  }

  private async mutationContext(opts: {
    namespace?: string;
    principal?: string;
    signal?: AbortSignal;
  }): Promise<ReviewDeckMutationContext> {
    const namespace = this.deps.writableNamespaceFor(opts.namespace, undefined, opts.principal);
    this.deps.resolveReadableNamespace(namespace, opts.principal);
    const storage = await this.deps.orchestrator.getStorage(namespace);
    return {
      memoryDir: storage.dir,
      namespace,
      principalDigest: digest(opts.principal ?? ""),
      appendLifecycleEvents: async (events) => {
        await storage.appendMemoryLifecycleEvents(events as MemoryLifecycleEvent[]);
      },
      readLifecycleEvents: (memoryId) =>
        memoryId ? storage.getMemoryTimeline(memoryId) : storage.readMemoryLifecycleEvents(),
      onApproveBlockedMemory: (tombstoneId) => {
        void storage.revokeTombstone(tombstoneId, "user_correction").catch(() => undefined);
      },
      planCorrection: async ({ itemId, correctionText }) => {
        const plan = await this.deps.correctionPlan(
          {
            text: correctionText,
            targetIds: [itemId],
            principal: opts.principal,
            namespace,
          },
          opts.signal ? { abortSignal: opts.signal } : undefined,
        );
        return { planId: plan.planId, preview: plan };
      },
      signal: opts.signal,
    };
  }
}

import { enforceNamespaceAllowList, tokenCapabilityStore } from "../access-token-capabilities.js";
import type { StorageManager } from "../index.js";
import type { LocalLlmClient } from "../local-llm.js";
import type { PluginConfig } from "../types.js";
import {
  SupportPassportAccessSurface,
  type SupportPassportCreateGrantResult,
  type SupportPassportMemoryPreview,
  type SupportPassportRevokeGrantResult,
} from "./access-surface.js";
import type { SupportPassportOwnerScope } from "./card-state.js";
import type { SupportPassportCard, SupportPassportCardCategory } from "./contracts.js";
import { SupportPassportError } from "./errors.js";
import type {
  SupportPassportCreateGrantRequest,
  SupportPassportOwnerGrant,
  SupportPassportPublicGuide,
} from "./grant-contracts.js";
import { type SupportPassportModelRoute, createSupportPassportModelAdapter } from "./model-adapter.js";
import type { SupportPassportAnswerOutput } from "./model-contracts.js";
import { supportsSupportPassportPrivateFiles } from "./private-file.js";

export abstract class SupportPassportAccessServiceBase {
  private _supportPassportSurface: SupportPassportAccessSurface | undefined;

  abstract get configRef(): PluginConfig;
  abstract get localLlmRef(): LocalLlmClient | null;
  abstract getWritableStorageForNamespace(namespace?: string, principal?: string): Promise<SupportPassportOwnerScope>;
  abstract getStorageForResolvedNamespace(namespace: string): Promise<StorageManager>;

  get supportPassportGatewayRouteRef(): SupportPassportModelRoute | null {
    return null;
  }

  get supportPassportPlatformRef(): NodeJS.Platform {
    return process.platform;
  }

  private getSupportPassportSurface(publicRequest = false): SupportPassportAccessSurface {
    if (!this.supportPassportEnabled) {
      if (publicRequest) {
        throw new SupportPassportError("grant_not_found", "The share link was not found.", 404);
      }
      throw new SupportPassportError("feature_disabled", "Support passport is disabled.", 404);
    }
    if (!this._supportPassportSurface) {
      this._supportPassportSurface = new SupportPassportAccessSurface({
        config: this.configRef,
        platform: this.supportPassportPlatformRef,
        resolveOwner: async (principal) => {
          const owner = await this.getWritableStorageForNamespace(undefined, principal);
          enforceNamespaceAllowList(tokenCapabilityStore.getStore(), owner.namespace, this.configRef.defaultNamespace);
          return owner;
        },
        resolveNamespace: (namespace) => this.getStorageForResolvedNamespace(namespace),
        modelAdapter: createSupportPassportModelAdapter(this.configRef, {
          localLlm: this.localLlmRef ?? undefined,
          gatewayRoute: this.supportPassportGatewayRouteRef ?? undefined,
        }),
      });
    }
    return this._supportPassportSurface;
  }

  get supportPassportEnabled(): boolean {
    return (
      this.configRef.supportPassport?.enabled === true &&
      supportsSupportPassportPrivateFiles(this.supportPassportPlatformRef)
    );
  }

  async supportPassportListCards(principal: string): Promise<SupportPassportCard[]> {
    return this.getSupportPassportSurface().listCards(principal);
  }

  async supportPassportPreviewMemory(principal: string, memoryId: string): Promise<SupportPassportMemoryPreview> {
    return this.getSupportPassportSurface().previewMemory(principal, memoryId);
  }

  async supportPassportCreateManualDraft(
    principal: string,
    input: { title: string; statement: string; category: SupportPassportCardCategory; reviewBy: string },
    options: { signal?: AbortSignal; onCommitted?: () => void } = {}
  ): Promise<SupportPassportCard> {
    return this.getSupportPassportSurface().createManualDraft(principal, input, options);
  }

  async supportPassportGenerateDrafts(
    principal: string,
    input: {
      sourceMemoryIds: string[];
      sourceMemoryRevisions: Array<{ memoryId: string; revision: string }>;
      consent: boolean;
      signal?: AbortSignal;
      onCommitted?: () => void;
    }
  ): Promise<SupportPassportCard[]> {
    return this.getSupportPassportSurface().generateDrafts(principal, input);
  }

  async supportPassportReplaceCard(
    principal: string,
    cardId: string,
    input: {
      title: string;
      statement: string;
      category: SupportPassportCardCategory;
      reviewBy: string;
      expectedRevision: string;
    },
    options: { signal?: AbortSignal; onCommitted?: () => void } = {}
  ): Promise<SupportPassportCard> {
    return this.getSupportPassportSurface().replaceCard(principal, cardId, input, options);
  }

  async supportPassportApproveCard(
    principal: string,
    cardId: string,
    input: { expectedRevision: string; reasonCode?: string },
    options: { signal?: AbortSignal; onCommitted?: () => void } = {}
  ): Promise<SupportPassportCard> {
    return this.getSupportPassportSurface().approveCard(principal, cardId, input, options);
  }

  async supportPassportRejectCard(
    principal: string,
    cardId: string,
    input: { expectedRevision: string; reasonCode?: string },
    options: { signal?: AbortSignal; onCommitted?: () => void } = {}
  ): Promise<SupportPassportCard> {
    return this.getSupportPassportSurface().rejectCard(principal, cardId, input, options);
  }

  async supportPassportWithdrawCard(
    principal: string,
    cardId: string,
    input: { expectedRevision: string; reasonCode?: string },
    options: { signal?: AbortSignal; onCommitted?: () => void } = {}
  ): Promise<SupportPassportCard> {
    return this.getSupportPassportSurface().withdrawCard(principal, cardId, input, options);
  }

  async supportPassportCreateGrant(
    principal: string,
    input: SupportPassportCreateGrantRequest,
    options: { signal?: AbortSignal; onCommitted?: () => void } = {}
  ): Promise<SupportPassportCreateGrantResult> {
    return this.getSupportPassportSurface().createGrant(principal, input, options);
  }

  async supportPassportListGrants(principal: string): Promise<SupportPassportOwnerGrant[]> {
    return this.getSupportPassportSurface().listGrants(principal);
  }

  async supportPassportRevokeGrant(
    principal: string,
    grantId: string,
    input: { expectedVersion?: number },
    options: { signal?: AbortSignal; onCommitted?: () => void } = {}
  ): Promise<SupportPassportRevokeGrantResult> {
    return this.getSupportPassportSurface().revokeGrant(principal, grantId, input, options);
  }

  async supportPassportReadGrant(grantId: string, secret: string): Promise<SupportPassportPublicGuide> {
    return this.getSupportPassportSurface(true).readGrant(grantId, secret);
  }

  async supportPassportAskGrant(
    grantId: string,
    secret: string,
    question: string,
    signal?: AbortSignal
  ): Promise<SupportPassportAnswerOutput> {
    return this.getSupportPassportSurface(true).askGrant(grantId, secret, question, signal);
  }
}

/**
 * Renderers for RecallTierExplain (issue #518).
 *
 * Pure functions that format a `LastRecallSnapshot` and its
 * optional `tierExplain` field for human text and machine JSON
 * consumption.  CLI / HTTP / MCP surfaces consume these — they do
 * not format explain output themselves, so rendering is tested in
 * one place.
 */

import type { LastRecallSnapshot } from "./recall-state.js";
import type { RecallTierExplain } from "./types.js";
import { isRetrievalTier } from "./retrieval-tiers.js";
import type {
  RecallXraySnapshot,
  RecallFilterTrace,
  RecallXrayResult,
} from "./recall-xray.js";
import { renderXrayMarkdown } from "./recall-xray-renderer.js";

function sanitizeString(v: unknown): string | null {
  return typeof v === "string" && v.length > 0 ? v : null;
}

function sanitizeFiniteNumber(v: unknown): number | null {
  return typeof v === "number" && Number.isFinite(v) ? v : null;
}

/**
 * `text` and `json` are the original formats (backwards-compatible
 * since issue #518).  `markdown` was added in issue #570 PR 7 and
 * delegates to the shared X-ray renderer so the three observability
 * surfaces stay in lock-step (CLAUDE.md rule 22).
 */
export type RecallExplainFormat = "text" | "json" | "markdown";

export interface RecallExplainJsonPayload {
  hasExplain: boolean;
  snapshotFound: boolean;
  sessionKey: string | null;
  recordedAt: string | null;
  namespace: string | null;
  memoryIds: string[];
  source: string | null;
  sourcesUsed: string[] | null;
  latencyMs: number | null;
  tierExplain: RecallTierExplain | null;
}

function normalizeTierExplain(value: unknown): RecallTierExplain | null {
  if (!value || typeof value !== "object" || Array.isArray(value)) return null;
  const raw = value as Record<string, unknown>;
  const filteredBy = Array.isArray(raw.filteredBy)
    ? raw.filteredBy.filter((x): x is string => typeof x === "string")
    : [];
  const sourceAnchors = Array.isArray(raw.sourceAnchors)
    ? raw.sourceAnchors
        .filter(
          (a): a is { path: string; lineRange?: unknown } =>
            !!a && typeof a === "object" && typeof (a as { path?: unknown }).path === "string",
        )
        .map((a) => {
          const lr = (a as { lineRange?: unknown }).lineRange;
          const lineRange =
            Array.isArray(lr) &&
            lr.length === 2 &&
            Number.isFinite(lr[0]) &&
            Number.isFinite(lr[1])
              ? ([lr[0] as number, lr[1] as number] as [number, number])
              : undefined;
          return lineRange
            ? { path: (a as { path: string }).path, lineRange }
            : { path: (a as { path: string }).path };
        })
    : undefined;
  return {
    tier: isRetrievalTier(raw.tier) ? raw.tier : "hybrid",
    tierReason: typeof raw.tierReason === "string" ? raw.tierReason : "",
    filteredBy,
    candidatesConsidered: sanitizeFiniteNumber(raw.candidatesConsidered) ?? 0,
    latencyMs: sanitizeFiniteNumber(raw.latencyMs) ?? 0,
    ...(sourceAnchors !== undefined ? { sourceAnchors } : {}),
  };
}

export function toRecallExplainJson(
  snapshot: LastRecallSnapshot | null,
): RecallExplainJsonPayload {
  if (!snapshot) {
    return {
      hasExplain: false,
      snapshotFound: false,
      sessionKey: null,
      recordedAt: null,
      namespace: null,
      memoryIds: [],
      source: null,
      sourcesUsed: null,
      latencyMs: null,
      tierExplain: null,
    };
  }
  const normalizedExplain = normalizeTierExplain(snapshot.tierExplain);
  return {
    hasExplain: normalizedExplain !== null,
    snapshotFound: true,
    sessionKey: sanitizeString(snapshot.sessionKey),
    recordedAt: sanitizeString(snapshot.recordedAt),
    namespace: sanitizeString(snapshot.namespace),
    memoryIds: Array.isArray(snapshot.memoryIds)
      ? snapshot.memoryIds.filter((x): x is string => typeof x === "string")
      : [],
    source: sanitizeString(snapshot.source),
    sourcesUsed: Array.isArray(snapshot.sourcesUsed)
      ? snapshot.sourcesUsed.filter((x): x is string => typeof x === "string")
      : null,
    latencyMs: sanitizeFiniteNumber(snapshot.latencyMs),
    tierExplain: normalizedExplain,
  };
}

/**
 * Render the shared "--- tier explain ---" text block used by both the
 * recall-explain surface and the Recall X-ray surface.  Callers provide
 * the normalized `RecallTierExplain` (or `null` for the
 * not-populated/disabled case) so the block stays character-for-character
 * identical across surfaces (CLAUDE.md rule 22).  The returned strings do
 * NOT include leading blank lines or headers — callers own that framing.
 */
export function renderTierExplainTextLines(
  tierExplain: RecallTierExplain | null,
): string[] {
  const lines: string[] = [];
  if (!tierExplain) {
    lines.push(
      "(not populated — direct-answer tier disabled or did not fire)",
    );
    return lines;
  }
  lines.push(`tier: ${tierExplain.tier}`);
  lines.push(`reason: ${tierExplain.tierReason}`);
  lines.push(`candidates-considered: ${tierExplain.candidatesConsidered}`);
  lines.push(`latency-ms: ${tierExplain.latencyMs}`);
  if (tierExplain.filteredBy.length > 0) {
    lines.push(`filtered-by: ${tierExplain.filteredBy.join(", ")}`);
  } else {
    lines.push("filtered-by: (none)");
  }
  if (tierExplain.sourceAnchors && tierExplain.sourceAnchors.length > 0) {
    lines.push("source-anchors:");
    for (const anchor of tierExplain.sourceAnchors) {
      const range = anchor.lineRange
        ? `:${anchor.lineRange[0]}-${anchor.lineRange[1]}`
        : "";
      lines.push(`  - ${anchor.path}${range}`);
    }
  }
  return lines;
}

export function toRecallExplainText(
  snapshot: LastRecallSnapshot | null,
): string {
  const lines: string[] = ["=== Recall Explain ==="];

  if (!snapshot) {
    lines.push("No recall snapshot recorded yet.");
    return lines.join("\n");
  }

  const sessionKey = sanitizeString(snapshot.sessionKey);
  const recordedAt = sanitizeString(snapshot.recordedAt);
  const namespace = sanitizeString(snapshot.namespace);
  const source = sanitizeString(snapshot.source);
  lines.push(`session: ${sessionKey ?? "(unknown)"}`);
  lines.push(`recorded: ${recordedAt ?? "(unknown)"}`);
  if (namespace) lines.push(`namespace: ${namespace}`);
  if (source) lines.push(`source: ${source}`);
  const sourcesUsed = Array.isArray(snapshot.sourcesUsed)
    ? snapshot.sourcesUsed.filter((x): x is string => typeof x === "string")
    : [];
  if (sourcesUsed.length > 0) {
    lines.push(`sources-used: ${sourcesUsed.join(", ")}`);
  }
  const latencyMs = sanitizeFiniteNumber(snapshot.latencyMs);
  if (latencyMs !== null) {
    lines.push(`latency-ms: ${latencyMs}`);
  }
  const memoryIds = Array.isArray(snapshot.memoryIds)
    ? snapshot.memoryIds.filter((x): x is string => typeof x === "string")
    : [];
  if (memoryIds.length > 0) {
    lines.push(`memories: ${memoryIds.join(", ")}`);
  }

  const ex = normalizeTierExplain(snapshot.tierExplain);
  if (!ex) {
    lines.push("");
    lines.push(
      "tier-explain: (not populated — direct-answer tier disabled or did not fire)",
    );
    return lines.join("\n");
  }

  lines.push("");
  lines.push("--- tier explain ---");
  for (const line of renderTierExplainTextLines(ex)) {
    lines.push(line);
  }
  return lines.join("\n");
}

/**
 * Adapter: convert a `LastRecallSnapshot` into a best-effort
 * `RecallXraySnapshot` so the markdown renderer can produce a
 * consistent, richly-formatted document for callers that have asked
 * for `markdown` format.  The LastRecallSnapshot and the X-ray
 * snapshot share session/namespace/memoryIds; additional X-ray-only
 * fields (filters, score decomposition, graph path, audit id) are
 * left empty because the legacy snapshot doesn't carry them.  The
 * renderer handles missing fields gracefully.
 */
/**
 * Strip backticks, pipes, and newlines from a host-provided value so it
 * cannot escape its enclosing markdown code span, break the surrounding
 * table row, or inject extra rows when it lands in
 * `renderXrayMarkdown`.  Applied at the adapter boundary because
 * `LastRecallSnapshot` is hydrated from on-disk JSON without schema
 * validation (codex P2 review on #605).
 *
 * Accepts `unknown` so non-string truthy values (numbers, objects,
 * booleans, arrays) coming from a corrupted snapshot are coerced to
 * the empty string rather than crashing on `.replace(...)`.  Callers
 * should treat an empty return as "drop this field."
 */
function sanitizeForMarkdownInline(value: unknown): string {
  if (typeof value !== "string") return "";
  return value.replace(/[`|\r\n]/g, " ").trim();
}

/**
 * Map the legacy `LastRecallSnapshot.source` field to the
 * `RecallXrayServedBy` union used by the unified x-ray renderer.
 * Mirrors the `mapRecallSourceToXrayServedBy` helper inside
 * `orchestrator.ts` (which is private).  Keep the two in sync when a
 * new source lands — unknown values collapse to `"hybrid"` to preserve
 * backwards compatibility with older on-disk snapshots.
 */
function mapLegacySourceToServedBy(
  source: unknown,
): "hybrid" | "recent-scan" {
  if (source === "recent_scan") return "recent-scan";
  return "hybrid";
}

export function toRecallXraySnapshotFromLegacy(
  snapshot: LastRecallSnapshot | null,
): RecallXraySnapshot | null {
  if (!snapshot) return null;
  const capturedAt = (() => {
    if (typeof snapshot.recordedAt !== "string") return 0;
    const ms = Date.parse(snapshot.recordedAt);
    return Number.isFinite(ms) && ms >= 0 ? ms : 0;
  })();
  const memoryIds = Array.isArray(snapshot.memoryIds)
    ? snapshot.memoryIds.filter((x): x is string => typeof x === "string")
    : [];
  // Codex P2 + Cursor Medium on #605: every converted result used to
  // be stamped with `servedBy: "hybrid"`, misattributing legacy
  // snapshots that came from `recent_scan` (or any future source).
  // Propagate the recorded `source` so markdown `recall-explain`
  // output matches the `served-by=` string the native x-ray capture
  // would emit for the same recall.
  const servedBy = mapLegacySourceToServedBy(snapshot.source);
  const results: RecallXrayResult[] = memoryIds.map((memoryId) => ({
    memoryId,
    path: "",
    servedBy,
    scoreDecomposition: { final: 0 },
    admittedBy: [],
  }));
  const filters: RecallFilterTrace[] = [];
  return {
    schemaVersion: "1",
    // `LastRecallSnapshot` does not preserve the original query text;
    // synthesize a placeholder so the renderer has a non-empty
    // string to print.  `queryHash` + `queryLen` stay in the JSON
    // payload via `toRecallExplainJson` for callers that need them.
    query:
      snapshot.queryHash
        ? `(legacy explain; queryHash=${snapshot.queryHash})`
        : "(legacy explain)",
    // `snapshotId` is synthesized here; `sessionKey` is already
    // sanitized before it reaches the ID because we re-use the
    // sanitized string below.
    snapshotId: `legacy-${sanitizeForMarkdownInline(snapshot.sessionKey ?? "unknown") || "unknown"}-${capturedAt}`,
    capturedAt,
    // Run the raw on-disk value through the same normalizer the text
    // and JSON paths use so the markdown adapter cannot render
    // unvalidated tier-explain payloads (cursor / codex review on
    // #605).  A malformed tierExplain is dropped to null, matching the
    // behavior of the non-markdown surfaces.
    tierExplain: normalizeTierExplain(snapshot.tierExplain) ?? null,
    results,
    appliedResultLimit: 0,
    appliedResults: [],
    headroomResults: [],
    filters,
    budget: { chars: 0, used: 0 },
    // Sanitize legacy session metadata at the adapter boundary so a
    // malformed on-disk value (containing backticks, pipes, or
    // newlines) cannot break the enclosing markdown table when
    // `renderXrayMarkdown` prints it in a raw code-span cell (codex P2
    // review on #605).
    ...(snapshot.sessionKey
      ? (() => {
          const clean = sanitizeForMarkdownInline(snapshot.sessionKey);
          return clean ? { sessionKey: clean } : {};
        })()
      : {}),
    ...(snapshot.namespace
      ? (() => {
          const clean = sanitizeForMarkdownInline(snapshot.namespace);
          return clean ? { namespace: clean } : {};
        })()
      : {}),
  };
}

export function renderRecallExplain(
  snapshot: LastRecallSnapshot | null,
  format: RecallExplainFormat,
): string {
  if (format === "json") {
    return JSON.stringify(toRecallExplainJson(snapshot), null, 2);
  }
  if (format === "markdown") {
    // Delegate to the shared X-ray renderer so CLI / HTTP / MCP
    // markdown output all share one implementation (CLAUDE.md rule
    // 22).  The JSON and text paths remain byte-for-byte
    // backwards-compatible with pre-#570 behavior.
    return renderXrayMarkdown(toRecallXraySnapshotFromLegacy(snapshot));
  }
  return toRecallExplainText(snapshot);
}

export function parseRecallExplainFormat(value: unknown): RecallExplainFormat {
  if (value === undefined || value === null) return "text";
  if (typeof value !== "string") {
    throw new Error(
      `--format expects "text", "json", or "markdown", got ${typeof value}`,
    );
  }
  const v = value.trim().toLowerCase();
  if (v === "text" || v === "json" || v === "markdown") return v;
  throw new Error(
    `--format expects "text", "json", or "markdown", got ${JSON.stringify(value)}`,
  );
}

import { mkdir, readFile, stat, unlink, writeFile } from "node:fs/promises";
import path from "node:path";
import { gzipSync } from "node:zlib";
import { CAPSULE_SCHEMA_VERSION, EXPORT_FORMAT } from "./constants.js";
import {
  listFilesRecursive,
  sha256File,
  toPosixRelPath,
  writeJsonFile,
} from "./fs-utils.js";
import {
  CAPSULE_ID_PATTERN,
  CapsuleBlockSchema,
  ExportBundleV2Schema,
  ExportManifestV2Schema,
  type CapsuleBlock,
  type ExportBundleV2,
  type ExportManifestV2,
  type ExportMemoryRecordV1,
} from "./types.js";
import { encryptCapsuleFile } from "./capsule-crypto.js";
import { computeTransferOutputRel, DEFAULT_TRANSFER_EXCLUDE_DIRS } from "./exclusions.js";

/**
 * Default subdirectory excludes applied to every capsule export. These match
 * the shared plaintext transfer exclusions plus the `transcripts`
 * directory, which is excluded by default and only included when the caller
 * explicitly passes `transcripts` in {@link ExportCapsuleOptions.includeKinds}.
 */
const DEFAULT_EXCLUDE_DIRS = DEFAULT_TRANSFER_EXCLUDE_DIRS;

const TRANSCRIPTS_DIR = "transcripts" as const;

/**
 * Top-level directory under {@link ExportCapsuleOptions.root} that holds
 * per-peer profile bundles. When {@link ExportCapsuleOptions.peerIds} is
 * provided, only files under `peers/<peerId>/...` for the listed ids are
 * included; the rest of the `peers/` tree is excluded.
 */
const PEERS_DIR = "peers" as const;

/**
 * Options accepted by {@link exportCapsule}.
 *
 * `name` — capsule id, validated against {@link CAPSULE_ID_PATTERN}. The id
 * also forms the manifest's `capsule.id` and the archive filename.
 *
 * `root` — absolute or cwd-relative path to the memory directory to export.
 *
 * `since` — optional ISO-8601 timestamp; only files with `mtime >= since`
 * are included.
 *
 * `includeKinds` — optional allow-list of top-level subdirectory names
 * (e.g. `facts`, `entities`, `corrections`, `transcripts`). When set, files
 * directly under {@link root} are excluded and only files whose first path
 * segment is in the allow-list are kept. Pass `transcripts` here explicitly
 * to opt-in transcripts (they are excluded by default).
 *
 * `peerIds` — optional allow-list restricting the `peers/` tree to files
 * under `peers/<peerId>/...`. When omitted the entire `peers/` tree is
 * included (subject to {@link includeKinds}). When set to an empty array
 * the `peers/` tree is excluded entirely.
 *
 * `outDir` — optional output directory. Defaults to `<root>/.capsules`.
 *
 * `pluginVersion` — recorded in the manifest. Defaults to `"0.0.0"` so
 * tests do not need to thread a version through; production callers SHOULD
 * pass the running plugin version.
 *
 * `capsule` — optional overrides for the manifest's `capsule` block. The
 * caller may pass any subset; remaining fields are filled with conservative
 * defaults documented inline below.
 *
 * `now` — optional clock override (ms epoch) used for `manifest.createdAt`.
 * Tests pass a fixed value for deterministic output.
 *
 * `encrypt` — when `true`, encrypt the output archive using the secure-store
 * master key for `memoryDir`. The keyring must be unlocked before calling
 * (`remnic secure-store unlock`). The plaintext `.capsule.json.gz` is written
 * first, then encrypted to `<name>.capsule.json.gz.enc`; the plaintext is
 * removed after successful encryption. Requires `memoryDir` to be provided.
 *
 * `memoryDir` — required when `encrypt` is `true`. The memory directory whose
 * secure-store keyring holds the master key.
 */
export interface ExportCapsuleOptions {
  name: string;
  root: string;
  since?: string;
  includeKinds?: readonly string[];
  peerIds?: readonly string[];
  outDir?: string;
  pluginVersion?: string;
  capsule?: Partial<Omit<CapsuleBlock, "id">>;
  now?: number;
  /**
   * When `true`, encrypt the output archive. Requires the secure-store to be
   * unlocked and `memoryDir` to be set. The plaintext `.capsule.json.gz` is
   * replaced by `<name>.capsule.json.gz.enc` on success.
   */
  encrypt?: boolean;
  /**
   * Memory directory whose secure-store keyring holds the master key. Required
   * when `encrypt` is `true`; ignored otherwise.
   */
  memoryDir?: string;
  /**
   * When `true`, include the `transcripts/` directory in the export even
   * though it is excluded by default. Using this flag avoids hard-coding an
   * explicit `includeKinds` allow-list that would inadvertently drop other
   * valid memory directories (`peers/`, `forks/`, etc.). (Cursor / #747)
   *
   * Ignored when `includeKinds` is provided and already contains
   * `"transcripts"`.
   */
  includeTranscripts?: boolean;
}

export interface ExportCapsuleResult {
  archivePath: string;
  manifestPath: string;
  manifest: ExportManifestV2;
  /** When the export was encrypted, the `.enc` path. `null` when unencrypted. */
  encryptedArchivePath: string | null;
}

/**
 * Pure function that exports a memory directory as a portable, capsule-aware
 * V2 bundle.
 *
 * The output is a single `.capsule.json.gz` archive containing the entire
 * `ExportBundleV2` (manifest + records) plus a sidecar `manifest.json` for
 * cheap inspection. The bundle format is intentionally identical to the
 * existing `export-json` shape so PR 3/6's importer can reuse the V1 code
 * path with only a manifest version-dispatch.
 *
 * Determinism guarantees:
 *  - `manifest.files` and `bundle.records` are sorted by posix path.
 *  - `manifest.createdAt` is taken from {@link ExportCapsuleOptions.now}
 *    when provided.
 *  - The archive is gzip-compressed with default settings; no timestamp is
 *    embedded (Node's `gzipSync` does not write a header timestamp when
 *    using the synchronous helper, so byte-identical outputs are possible
 *    given identical inputs).
 *
 * Empty result handling: a capsule with zero matching files is still a
 * valid capsule and produces a well-formed manifest with an empty `files`
 * array and an archive containing the empty bundle.
 */
export async function exportCapsule(
  opts: ExportCapsuleOptions,
): Promise<ExportCapsuleResult> {
  validateName(opts.name);
  if (opts.encrypt === true && !opts.memoryDir) {
    throw new Error(
      "exportCapsule: 'memoryDir' is required when 'encrypt' is true so the " +
        "secure-store key can be retrieved.",
    );
  }
  const encryptionMemoryDir = opts.encrypt === true ? opts.memoryDir : undefined;
  const sinceMs = parseSince(opts.since);
  const includeKinds = normalizeIncludeKinds(opts.includeKinds);
  const peerFilter = normalizePeerIds(opts.peerIds);
  // `includeTranscripts: true` overrides the default transcripts exclusion
  // without requiring an explicit `includeKinds` list — so callers that want
  // all memory dirs + transcripts don't need to hard-code a list that would
  // inadvertently drop new dirs like `peers/` or `forks/`. (Cursor / #747)
  const transcriptsOverride = opts.includeTranscripts === true;

  const rootAbs = path.resolve(opts.root);
  await assertIsDirectory(rootAbs);

  const outDirAbs = path.resolve(opts.outDir ?? path.join(rootAbs, ".capsules"));
  // Reject outDir === root: the input scan would otherwise be entirely
  // skipped by `shouldInclude` (outDirRelPosix === ".") and the export would
  // silently succeed with an empty manifest/archive — a Rule 51 violation
  // and a data-loss footgun for callers that point outDir at the root.
  if (outDirAbs === rootAbs) {
    throw new Error(
      "exportCapsule: 'outDir' must not equal 'root'. " +
        "Choose a separate directory (default: <root>/.capsules) so the " +
        "export does not overwrite or shadow the source tree.",
    );
  }
  await mkdir(outDirAbs, { recursive: true });

  // If the output directory lives inside the export root, scan results would
  // re-import previous capsule archives on subsequent runs. Compute the
  // posix-relative path of the outDir under rootAbs (or `null` when it sits
  // outside) so {@link shouldInclude} can skip the entire subtree.
  const outDirRelPosix = computeTransferOutputRel(rootAbs, outDirAbs);

  const filesAbs = await listFilesRecursive(rootAbs);

  const records: ExportMemoryRecordV1[] = [];
  const manifestFiles: ExportManifestV2["files"] = [];

  for (const abs of filesAbs) {
    const relPosix = toPosixRelPath(abs, rootAbs);
    if (!shouldInclude(relPosix, includeKinds, peerFilter, outDirRelPosix, transcriptsOverride)) continue;

    if (sinceMs !== null) {
      const st = await stat(abs);
      if (st.mtimeMs < sinceMs) continue;
    }

    const content = await readFile(abs, "utf-8");
    records.push({ path: relPosix, content });
    const { sha256, bytes } = await sha256File(abs);
    manifestFiles.push({ path: relPosix, sha256, bytes });
  }

  records.sort((a, b) => a.path.localeCompare(b.path));
  manifestFiles.sort((a, b) => a.path.localeCompare(b.path));

  const capsule = buildCapsuleBlock(opts.name, opts.capsule);
  const includesTranscripts =
    transcriptsOverride || (includeKinds ?? new Set<string>()).has(TRANSCRIPTS_DIR);

  const createdAtMs = opts.now ?? Date.now();
  const manifest = ExportManifestV2Schema.parse({
    format: EXPORT_FORMAT,
    schemaVersion: CAPSULE_SCHEMA_VERSION,
    createdAt: new Date(createdAtMs).toISOString(),
    pluginVersion: opts.pluginVersion ?? "0.0.0",
    includesTranscripts,
    files: manifestFiles,
    capsule,
  } satisfies ExportManifestV2);

  const bundle: ExportBundleV2 = ExportBundleV2Schema.parse({
    manifest,
    records,
  });

  const archivePath = path.join(outDirAbs, `${opts.name}.capsule.json.gz`);
  const manifestPath = path.join(outDirAbs, `${opts.name}.manifest.json`);

  // Sidecar manifest for cheap inspection without decompressing the archive.
  await writeJsonFile(manifestPath, manifest);

  // Single-artifact gzip archive containing the whole bundle. JSON encoded
  // before gzip so the archive is opaque to file-tree filtering. Using the
  // sync helper keeps the function pure async (no filesystem callback chain)
  // and matches the existing transfer modules' style.
  const json = JSON.stringify(bundle);
  const gz = gzipSync(Buffer.from(json, "utf-8"));
  await writeFile(archivePath, gz);

  // Optional encryption (PR 4/4). When opts.encrypt is true, wrap the
  // plaintext gzip in a REMNIC-ENC sealed envelope and remove the plaintext.
  // Per gotcha #54: write the encrypted file before removing the plaintext so
  // a crash mid-encrypt does not destroy the only copy.
  if (opts.encrypt === true) {
    try {
      const { encPath } = await encryptCapsuleFile({
        sourceGzPath: archivePath,
        memoryDir: encryptionMemoryDir!,
      });
      // Remove the plaintext only after the encrypted file was written successfully.
      await unlink(archivePath);
      return { archivePath: encPath, manifestPath, manifest, encryptedArchivePath: encPath };
    } catch (error) {
      try {
        await unlink(archivePath);
      } catch {
        // Best-effort cleanup: do not leave a plaintext capsule after a failed encrypted export.
      }
      throw error;
    }
  }

  return { archivePath, manifestPath, manifest, encryptedArchivePath: null };
}

// ---------------------------------------------------------------------------
// Validation helpers
// ---------------------------------------------------------------------------

function validateName(name: unknown): void {
  if (typeof name !== "string" || !CAPSULE_ID_PATTERN.test(name)) {
    throw new Error(
      `exportCapsule: invalid capsule name. Expected /${CAPSULE_ID_PATTERN.source}/`,
    );
  }
  if (name.length > 64) {
    throw new Error(
      "exportCapsule: invalid capsule name. Must be 64 characters or fewer.",
    );
  }
}

/**
 * Strict ISO-8601 form accepted by {@link parseSince}. We accept exactly two
 * shapes:
 *
 *   1. Date-only:  `YYYY-MM-DD` — interpreted as UTC midnight per ECMAScript.
 *   2. Date+time with an explicit timezone designator:
 *      `YYYY-MM-DDTHH:MM(:SS(.fff)?)?(Z|±HH:MM)`.
 *
 * Notably **rejected**: date+time **without** a timezone (e.g.
 * `2026-02-28T00:00:00`). ECMAScript treats this as local time, which makes
 * acceptance and the resulting cutoff depend on the host's `TZ` and silently
 * shifts incremental-export windows for users outside UTC. Rule 51: reject
 * inputs that silently coerce to a host-dependent meaning.
 */
const ISO_8601_RE =
  /^\d{4}-\d{2}-\d{2}(?:[Tt]\d{2}:\d{2}(?::\d{2}(?:\.\d{1,9})?)?(?:[Zz]|[+-]\d{2}:?\d{2}))?$/;

function parseSince(since: string | undefined): number | null {
  if (since === undefined) return null;
  if (typeof since !== "string" || since.trim() === "") {
    throw new Error("exportCapsule: 'since' must be a non-empty ISO-8601 string");
  }
  if (!ISO_8601_RE.test(since)) {
    throw new Error(
      `exportCapsule: 'since' is not a valid ISO-8601 timestamp: ${since}`,
    );
  }
  const ms = Date.parse(since);
  if (!Number.isFinite(ms)) {
    throw new Error(
      `exportCapsule: 'since' is not a valid ISO-8601 timestamp: ${since}`,
    );
  }
  // Reject calendar overflow: `Date.parse("2026-02-31")` returns a finite ms
  // for March 3 because the JS Date constructor silently normalizes invalid
  // calendar values. Round-trip through `Date` and compare the year/month/day
  // components against the input prefix to catch this. Rule 51: silent
  // coercion of an exact time boundary is a Rule 51 violation that breaks
  // incremental exports.
  assertCalendarRoundTrip(since, ms);
  return ms;
}

export function isValidCapsuleSince(since: string): boolean {
  try {
    parseSince(since);
    return true;
  } catch {
    return false;
  }
}

/**
 * Verify that parsing {@link since} did not silently normalize an invalid
 * calendar date (e.g. `2026-02-31` → `2026-03-03`). We extract the
 * year/month/day from the input string (regex-validated above) and compare
 * against the parsed Date's UTC components. Both date-only forms and forms
 * with an explicit Z/offset are normalized to UTC by `Date.parse`; for the
 * non-Z case where the offset shifts the calendar day across midnight, we
 * re-derive the input's intended UTC instant by accounting for the offset
 * before the comparison.
 */
function assertCalendarRoundTrip(since: string, ms: number): void {
  const m = /^(\d{4})-(\d{2})-(\d{2})/.exec(since);
  if (!m) return;
  const wantY = Number(m[1]);
  const wantMo = Number(m[2]);
  const wantD = Number(m[3]);

  // For inputs with an explicit non-zero offset, compare against the
  // wall-clock components of that offset instead of UTC. Date.parse maps to
  // UTC, so 2026-02-31T00:00:00-05:00 and 2026-02-31T00:00:00Z both fail the
  // calendar check; the wall-clock comparison via `m[1..3]` is still the
  // right reference because the input's stated calendar day must exist.
  const offsetMatch = /([+-])(\d{2}):?(\d{2})$/.exec(since);
  let displayMs = ms;
  if (offsetMatch) {
    const sign = offsetMatch[1] === "-" ? -1 : 1;
    const offsetMin = sign * (Number(offsetMatch[2]) * 60 + Number(offsetMatch[3]));
    displayMs = ms + offsetMin * 60_000;
  }
  const dd = new Date(displayMs);
  const gotY = dd.getUTCFullYear();
  const gotMo = dd.getUTCMonth() + 1;
  const gotD = dd.getUTCDate();
  if (gotY !== wantY || gotMo !== wantMo || gotD !== wantD) {
    throw new Error(
      `exportCapsule: 'since' is not a valid ISO-8601 timestamp: ${since}`,
    );
  }
}

function normalizeIncludeKinds(
  kinds: readonly string[] | undefined,
): ReadonlySet<string> | null {
  if (kinds === undefined) return null;
  // Empty array is treated as "include nothing" rather than "include all"
  // so callers cannot accidentally widen the filter by passing []. This
  // mirrors PR-1/6 Rule 51: reject ambiguous input — but here we model it
  // as "explicit empty allow-list" rather than throwing, because empty
  // capsules ARE valid (see acceptance criteria).
  const set = new Set<string>();
  for (const raw of kinds) {
    if (typeof raw !== "string" || raw.trim() === "") {
      throw new Error("exportCapsule: 'includeKinds' entries must be non-empty strings");
    }
    if (raw.includes("/") || raw.includes("\\")) {
      throw new Error(
        `exportCapsule: 'includeKinds' entries must be top-level segment names, got: ${raw}`,
      );
    }
    set.add(raw);
  }
  return set;
}

function normalizePeerIds(
  peerIds: readonly string[] | undefined,
): ReadonlySet<string> | null {
  if (peerIds === undefined) return null;
  const set = new Set<string>();
  for (const raw of peerIds) {
    if (typeof raw !== "string" || raw.trim() === "") {
      throw new Error("exportCapsule: 'peerIds' entries must be non-empty strings");
    }
    if (raw.includes("/") || raw.includes("\\") || raw === "." || raw === "..") {
      throw new Error(
        `exportCapsule: 'peerIds' entries must be plain segment names, got: ${raw}`,
      );
    }
    set.add(raw);
  }
  return set;
}

async function assertIsDirectory(absPath: string): Promise<void> {
  // Mirror gotcha #24: existsSync returns true for files. The export root
  // MUST be a directory or the walk silently succeeds with zero entries.
  const st = await stat(absPath).catch(() => null);
  if (!st || !st.isDirectory()) {
    throw new Error(
      `exportCapsule: 'root' must be an existing directory: ${absPath}`,
    );
  }
}

function shouldInclude(
  relPosix: string,
  includeKinds: ReadonlySet<string> | null,
  peerFilter: ReadonlySet<string> | null,
  outDirRelPosix: string | null,
  transcriptsOverride = false,
): boolean {
  const parts = relPosix.split("/");
  if (parts.some((p) => DEFAULT_EXCLUDE_DIRS.has(p))) return false;

  // Exclude the output directory subtree. Without this, re-running against
  // the same root packages prior `.capsule.json.gz` archives and sidecar
  // manifests as records, causing bundle bloat and leaking stale exports.
  // `outDir === root` is rejected at the entrypoint (`exportCapsule`), so
  // {@link computeOutDirRel} never returns `"."` for the in-tree case here.
  if (outDirRelPosix !== null) {
    if (relPosix === outDirRelPosix) return false;
    if (relPosix.startsWith(`${outDirRelPosix}/`)) return false;
  }

  const top = parts[0];

  // Transcripts are opt-in: excluded unless caller explicitly listed them
  // in includeKinds OR passed `includeTranscripts: true`. The override flag
  // avoids the footgun of having the CLI build a hard-coded kinds list that
  // inadvertently drops valid memory dirs like `peers/` or `forks/`. (Cursor / #747)
  if (
    top === TRANSCRIPTS_DIR &&
    !transcriptsOverride &&
    (includeKinds === null || !includeKinds.has(TRANSCRIPTS_DIR))
  ) {
    return false;
  }

  if (includeKinds !== null) {
    // includeKinds restricts to whitelisted top-level segments. Files at
    // the repo root (no top-level dir) are excluded under an explicit
    // allow-list because they are not categorized.
    if (parts.length < 2) return false;
    if (!includeKinds.has(top)) return false;
  }

  if (top === PEERS_DIR && peerFilter !== null) {
    if (peerFilter.size === 0) return false;
    if (parts.length < 2) return false;
    if (!peerFilter.has(parts[1])) return false;
  }

  return true;
}

// ---------------------------------------------------------------------------
// Capsule-block defaults
// ---------------------------------------------------------------------------

/**
 * Build a {@link CapsuleBlock} for the manifest. PR 2/6 ships a minimal
 * snapshot: tier-weights and `directAnswerEnabled` default to zod-passing
 * placeholders so the bundle parses cleanly. PRs 3/6+ will wire real
 * retrieval-policy and identity-anchor snapshots into the override path.
 *
 * Defaults (chosen to be safe + least-surprising):
 *  - `version`           — `0.1.0` (capsule authors override per release).
 *  - `schemaVersion`     — `taxonomy-v1` until the taxonomy registry stabilizes.
 *  - `parentCapsule`     — `null` (explicit "no parent" sentinel).
 *  - `description`       — empty string. Capsule authors override.
 *  - `retrievalPolicy`   — empty `tierWeights` map + `directAnswerEnabled: false`.
 *    Empty weights mean "no overrides"; importers fall back to their local
 *    policy. `false` is the least-privileged default per Rule 48.
 *  - `includes`          — all flags `false` until later PRs wire the
 *    sub-bundles in.
 */
function buildCapsuleBlock(
  name: string,
  override: Partial<Omit<CapsuleBlock, "id">> | undefined,
): CapsuleBlock {
  // `parent` (structured, PR 4/6) and `parentCapsule` (legacy string) carry
  // overlapping information. The schema documents the invariant: when
  // `parent` is non-null, `parentCapsule` SHOULD equal `parent.capsuleId`.
  // We derive the legacy field from the structured field whenever the
  // caller supplies `parent` but omits `parentCapsule`, so a single-source
  // override path produces a manifest that satisfies the documented
  // invariant for legacy V2 readers (Cursor medium #751 round 3).
  // An explicit `parentCapsule` override still wins — including an explicit
  // `null` — so callers can intentionally diverge from the structured field
  // for migration scenarios.
  const parent = override?.parent ?? null;
  const parentCapsule =
    override && Object.prototype.hasOwnProperty.call(override, "parentCapsule")
      ? (override.parentCapsule ?? null)
      : (parent?.capsuleId ?? null);

  const merged: CapsuleBlock = {
    id: name,
    version: override?.version ?? "0.1.0",
    schemaVersion: override?.schemaVersion ?? "taxonomy-v1",
    parentCapsule,
    parent,
    description: override?.description ?? "",
    retrievalPolicy: override?.retrievalPolicy ?? {
      tierWeights: {},
      directAnswerEnabled: false,
    },
    includes: override?.includes ?? {
      taxonomy: false,
      identityAnchors: false,
      peerProfiles: false,
      procedural: false,
    },
  };
  // Re-parse to surface invalid overrides with the same zod errors a caller
  // would get when constructing a CapsuleBlock by hand.
  return CapsuleBlockSchema.parse(merged);
}

import { lstat, mkdir, readFile, realpath, stat, unlink, writeFile } from "node:fs/promises";
import path from "node:path";
import { createHash, randomUUID } from "node:crypto";
import { gunzipSync } from "node:zlib";
import { bumpMemoryCorpusVersionForDir } from "../memory-corpus-version.js";
import {
  HistoricalEntityCanonicalIdCache,
  readEntityRefFromFrontmatter,
  canonicalizeEntityRefFrontmatter,
  classifyEntityRefWritePath,
  repairContentAfterJournalMove,
  requestEntityCanonicalIdReconcile,
} from "../storage/entity-canonical-id-references.js";
import { withRawEntityPageMutation } from "../storage/entity-canonical-id-lock.js";
import {
  createVersion,
  type VersioningConfig,
  type VersioningLogger,
} from "../page-versioning.js";
import {
  assertIsDirectoryNotSymlink,
  assertRealpathInsideRoot,
  fromPosixRelPath,
  isPathInsideRoot,
  sha256String,
} from "./fs-utils.js";
import {
  parseExportBundle,
  type CapsuleBlock,
  type ExportManifestV2,
  type ExportMemoryRecordV1,
} from "./types.js";
import { isEncryptedCapsuleFile, decryptCapsuleFileInMemory } from "./capsule-crypto.js";

/**
 * Conflict-resolution mode for {@link importCapsule}. Inverse of the
 * `mode` selector in PR 4/6's CLI surface.
 *
 *  - `"skip"` (default) — when a target file already exists at the same
 *    relative path, leave it untouched. The corresponding record is reported
 *    via {@link ImportCapsuleResult.skipped}.
 *  - `"overwrite"` — when a target file exists, snapshot the prior content
 *    via {@link createVersion} (gotcha #54: write-before-delete; gotcha #25:
 *    don't destroy old state until new state is confirmed), then write the
 *    incoming content. The snapshot's `note` includes the source capsule id.
 *  - `"fork"` — never overwrite. Every record is rebased under
 *    `forks/<capsule-id>/<original-path>` and any YAML-frontmatter `id:`
 *    field is rewritten to a new fork-scoped value. The original tree is
 *    not touched.
 *
 * The mode is selected once per call and applied uniformly to every record
 * in the bundle. Mixed-mode imports are not supported by design — that
 * would let a single corrupted manifest silently land partial state.
 */
export type ImportCapsuleMode = "skip" | "overwrite" | "fork";

/**
 * Options accepted by {@link importCapsule}.
 *
 * `archivePath` — absolute or cwd-relative path to a `.capsule.json.gz`
 * archive produced by `exportCapsule`. The archive must contain a V2
 * bundle (`schemaVersion: 2`); V1 archives are rejected.
 *
 * `root` — absolute or cwd-relative path to the memory directory that
 * will receive the records. Must be an existing directory.
 *
 * `mode` — see {@link ImportCapsuleMode}. Defaults to `"skip"`.
 *
 * `versioning` — optional page-versioning config used by `mode: "overwrite"`
 * to snapshot prior content before replacing it. Snapshots are skipped when
 * not provided or when `enabled === false`. Tests pass an enabled config
 * to assert snapshot creation; production callers thread the
 * orchestrator's resolved versioning config.
 *
 * `log` — optional logger forwarded to {@link createVersion}.
 *
 * `now` — optional clock override (ms epoch) used to derive deterministic
 * fork ids in tests. Production callers omit this.
 */
export interface ImportCapsuleOptions {
  archivePath: string;
  root: string;
  mode?: ImportCapsuleMode;
  versioning?: VersioningConfig;
  log?: VersioningLogger;
  now?: number;
  /**
   * Memory directory whose secure-store keyring is used when the archive is
   * encrypted. Required when `archivePath` ends with `.enc` or when the file
   * starts with the REMNIC-ENC magic header. If `memoryDir` is omitted and the
   * archive turns out to be encrypted, `importCapsule` throws a clear error
   * rather than silently failing.
   *
   * When provided and the archive is NOT encrypted, the value is ignored.
   */
  memoryDir?: string;
  /**
   * Original secure-store passphrase for encrypted format-v2 archives. When
   * supplied, the importer derives the archive key from the embedded KDF
   * header, enabling restore without the source machine's unlocked keyring.
   */
  passphrase?: string;
}

export interface ImportCapsuleSkippedRecord {
  /** Original record path (capsule-relative, posix). */
  path: string;
  /**
   * Why this record was not written.
   *
   * `"exists"` — the target path already existed and the mode was `"skip"`,
   * OR the computed fork path already existed in fork mode.
   *
   * `"checksum_mismatch"` is intentionally absent: a checksum failure aborts
   * the import entirely (fail-closed) rather than skipping the offending
   * record, so no `ImportCapsuleSkippedRecord` is ever produced for it.
   */
  reason: "exists";
}

export interface ImportCapsuleImportedRecord {
  /** Capsule-relative posix path the record carried. */
  sourcePath: string;
  /** Memory-dir-relative posix path the file was written to. */
  targetPath: string;
  /** Whether a prior version snapshot was taken (overwrite-mode only). */
  snapshotted: boolean;
  /** Whether the frontmatter `id:` field was rewritten (fork-mode only). */
  rewroteId: boolean;
}

export interface ImportCapsuleResult {
  /** Records that landed on disk. */
  imported: ImportCapsuleImportedRecord[];
  /** Records that were not written. */
  skipped: ImportCapsuleSkippedRecord[];
  /** The manifest decoded from the archive. */
  manifest: ExportManifestV2;
}

/**
 * Pure async function that imports a capsule archive into a memory
 * directory. Inverse of {@link import("./capsule-export.js").exportCapsule}.
 *
 * Sequence:
 *   1. Read + gunzip + JSON.parse the archive.
 *   2. Validate the bundle through `parseExportBundle` (V1 rejected).
 *   3. Verify each record's content sha256 against the manifest entry.
 *      Any mismatch aborts the import BEFORE any file is written —
 *      partial-write recovery would require a full rollback we cannot
 *      offer cheaply, so we fail closed (gotcha #25).
 *   4. Apply the selected {@link ImportCapsuleMode} to every record.
 *
 * Determinism guarantees:
 *  - Imported records are returned sorted by `sourcePath`.
 *  - Skipped records are returned sorted by `path`.
 *  - Fork-mode rebases under a stable `forks/<capsule-id>/` prefix so
 *    repeated fork imports of the same capsule shape land in predictable
 *    locations (subsequent fork imports still skip-on-exist because the
 *    target tree is computed from the source path).
 */
export async function importCapsule(
  opts: ImportCapsuleOptions,
): Promise<ImportCapsuleResult> {
  const archiveAbs = path.resolve(opts.archivePath);
  const rootAbs = path.resolve(opts.root);
  await assertIsDirectoryNotSymlink(rootAbs, "importCapsule", "root");

  const mode: ImportCapsuleMode = opts.mode ?? "skip";
  // Reject unknown mode values up-front (rule 51). TypeScript callers get a
  // compile-time check via the union type; JS/CLI callers get a runtime error
  // here before any write begins — not a silent destructive fallback.
  if (mode !== "skip" && mode !== "overwrite" && mode !== "fork") {
    throw new Error(
      `importCapsule: unknown mode ${JSON.stringify(mode)}; expected "skip", "overwrite", or "fork"`,
    );
  }

  // Auto-detect encrypted archives. If the file ends with `.enc` or starts
  // with the REMNIC-ENC magic header, decrypt it first before gunzip+parse.
  // Rule 48: default is "not encrypted"; we only attempt decryption when the
  // header is definitively present, never on ambiguous content.
  const encrypted = await isEncryptedCapsuleFile(archiveAbs);
  let raw: Buffer;
  if (encrypted) {
    if (!opts.memoryDir && !opts.passphrase) {
      throw new Error(
        `importCapsule: archive is encrypted but 'memoryDir' was not provided. ` +
          `Pass the memory directory so the secure-store key can be retrieved, ` +
          `provide the original passphrase for a format-v2 archive restore, ` +
          `or run \`remnic secure-store unlock\` before importing.`,
      );
    }
    raw = await decryptCapsuleFileInMemory(archiveAbs, opts.memoryDir, {
      passphrase: opts.passphrase,
    });
  } else {
    raw = await readFile(archiveAbs);
  }
  const json = gunzipSync(raw).toString("utf-8");
  let parsedJson: unknown;
  try {
    parsedJson = JSON.parse(json);
  } catch (cause) {
    throw new Error(
      `importCapsule: archive is not valid JSON after gunzip: ${archiveAbs}`,
      { cause: cause as Error },
    );
  }

  const parsed = parseExportBundle(parsedJson);
  if (parsed.capsuleVersion !== 2) {
    // PR 1/6 ships a V1 reader; capsule import is V2-only by design. A V1
    // bundle does not carry a capsule block, so fork-mode (which depends on
    // `capsule.id` for the rebase prefix) cannot work. Reject up-front per
    // gotcha #51 instead of silently routing to a different code path.
    throw new Error(
      "importCapsule: archive is V1; only V2 capsule archives are supported",
    );
  }
  const bundle = parsed.bundle as { manifest: ExportManifestV2; records: ExportMemoryRecordV1[] };
  const manifest = bundle.manifest;
  const capsule = manifest.capsule;

  // Build a path → manifest-entry index for O(1) checksum lookup. The
  // manifest is the source of truth; records-without-manifest-entries and
  // manifest-entries-without-records are both treated as corruption.
  const manifestIndex = new Map<string, ExportManifestV2["files"][number]>();
  for (const f of manifest.files) {
    manifestIndex.set(f.path, f);
  }
  if (manifestIndex.size !== manifest.files.length) {
    throw new Error(
      "importCapsule: manifest contains duplicate file paths",
    );
  }
  const recordPaths = new Set<string>();
  for (const rec of bundle.records) {
    if (recordPaths.has(rec.path)) {
      throw new Error(
        `importCapsule: bundle contains duplicate record path: ${rec.path}`,
      );
    }
    recordPaths.add(rec.path);
  }

  // Phase 1: verify every record matches its manifest entry AND validate all
  // target paths before any filesystem mutation.  We do both in a single pass
  // so a corrupted or malicious archive cannot leave the memory dir partially
  // written (fail-closed per gotcha #25).
  //
  // The real root is resolved once via realpath so the subsequent per-record
  // inside-root checks are symlink-aware: a record path like `facts/a.md`
  // cannot write outside the intended sandbox via a symlinked subdirectory
  // (Codex P1 feedback).  If realpath fails (root does not exist) the earlier
  // assertIsDirectoryNotSymlink call already threw, so this should always succeed.
  const rootReal = await realpath(rootAbs).catch(() => rootAbs);

  // Tracks normalized, case-folded target paths seen so far in phase 1.  Maps
  // targetAbs.toLowerCase() → first source path so the collision error can name
  // both offending entries.  Two manifest entries whose computed target paths
  // normalize to the same absolute path (e.g. `subdir/file.md` and
  // `subdir/./file.md`, or differing case on case-insensitive filesystems such
  // as macOS and Windows) would both try to write the same inode — the second
  // would silently overwrite the first.  We reject the import up-front before
  // any write (Codex P2 thread on PR #741, line 283).
  const seenTargetPaths = new Map<string, string>();

  for (const rec of bundle.records) {
    // Checksum validation.
    const entry = manifestIndex.get(rec.path);
    if (!entry) {
      throw new Error(
        `importCapsule: archive checksum mismatch (record without manifest entry: ${rec.path})`,
      );
    }
    const { sha256, bytes } = sha256String(rec.content);
    if (sha256 !== entry.sha256 || bytes !== entry.bytes) {
      throw new Error(
        `importCapsule: archive checksum mismatch for ${rec.path}: ` +
          `expected sha256=${entry.sha256} bytes=${entry.bytes}, ` +
          `got sha256=${sha256} bytes=${bytes}`,
      );
    }

    // Source path validation: reject any record whose posix source path
    // contains a `..` segment, an absolute prefix, or any component that would
    // let fork-mode bypass its isolation invariant.  This check runs before
    // `computeTargetPath` so that fork mode's `forks/<id>/` rebase cannot be
    // bypassed by a path like `../../profile.md` (which `path.join` would
    // silently collapse, landing the file inside root but outside the fork
    // prefix — Cursor medium thread #741).  Rejecting `..` up-front is simpler
    // and more robust than normalising after the fact.
    //
    // Extended guard (Codex P1 #741 round 5): also reject paths containing
    // backslash separators (`\`), which are Windows path separators. On Windows
    // a path like `..\\escape.md` or `subdir\\..\\..\\escape.md` would resolve
    // to a parent traversal but would bypass a purely posix-split check.
    // Additionally, after posix-normalizing the path we re-check for a leading
    // `..` or `/` — this catches edge-cases such as `subdir/../..` where the
    // individual split segments are not `..` but the normalized result is.
    if (rec.path.includes("\\")) {
      throw new Error(
        `importCapsule: record path contains backslash separators (Windows-style paths are not allowed): ${rec.path}`,
      );
    }
    const posixNormalized = path.posix.normalize(rec.path);
    if (
      rec.path.startsWith("/") ||
      rec.path.split("/").some((seg) => seg === "..") ||
      posixNormalized.startsWith("..") ||
      posixNormalized.startsWith("/")
    ) {
      throw new Error(
        `importCapsule: record path escapes target root: ${rec.path}`,
      );
    }

    // Path-traversal validation (moved here from phase 2 per Cursor feedback:
    // the traversal check must run before ANY write so a malicious archive
    // with an escaping path that sorts last cannot land partial writes).
    //
    // We build targetAbs relative to the real-resolved root (rootReal) so
    // that the inside-root check is symlink-aware: if `rootReal !== rootAbs`
    // (the import root is itself behind a symlink), we still compare against
    // the canonical path (Codex P1).
    const targetRel = computeTargetPath(rec.path, mode, capsule.id);
    const targetAbs = path.join(rootReal, fromPosixRelPath(targetRel));
    if (!isPathInsideRoot(rootReal, targetAbs)) {
      throw new Error(
        `importCapsule: record path escapes target root: ${rec.path}`,
      );
    }

    // Symlink-aware containment check (Cursor thread #741 line 247/264).
    // The lexical check above handles `..`-traversal but cannot detect
    // symlinked subdirectories that point outside the root. We resolve the
    // nearest existing ancestor of the target via realpath to catch symlinks
    // anywhere in the path components. If any resolved prefix escapes rootReal,
    // the import is rejected before any write. This applies to ALL modes,
    // including fork mode whose rebase prefix may itself traverse a symlink.
    await assertRealpathInsideRoot(rootReal, targetAbs, rec.path, "importCapsule");

    // Target-file symlink check (Codex P1 #741 round 4, line 260).
    // `assertRealpathInsideRoot` resolves the nearest existing *ancestor* to
    // catch symlinked parent directories, but if the TARGET FILE itself already
    // exists and is a symlink, that check passes (the parent is real) while the
    // write would silently follow the symlink to a path outside root.  We
    // therefore lstat the target directly: if it exists and is a symlink we
    // reject the record up-front.  For new files the parent-canonicalization
    // performed above is sufficient; no realpath of a non-existent file is
    // needed.
    const targetLstat = await lstat(targetAbs).catch(() => null);
    if (targetLstat !== null && targetLstat.isSymbolicLink()) {
      throw new Error(
        `importCapsule: record target is a symlink and cannot be written to safely: ${rec.path}`,
      );
    }

    // Duplicate normalized target path detection (Codex P2 #741, line 283).
    // `path.join` already normalises `.` segments (e.g. `subdir/./file.md` →
    // `subdir/file.md`).  On case-insensitive filesystems (macOS default,
    // Windows), two paths that differ only in case would resolve to the same
    // inode.  We fold the dedup key to lowercase so that `subdir/File.md` and
    // `subdir/file.md` are detected as duplicates before any write occurs.
    // This is intentionally unconditional: the cost of an extra `.toLowerCase()`
    // on case-sensitive filesystems is negligible, and a defensive lowercase
    // is far simpler than probing filesystem case-sensitivity at runtime.
    const dedupKey = targetAbs.toLowerCase();
    const firstSourcePath = seenTargetPaths.get(dedupKey);
    if (firstSourcePath !== undefined) {
      throw new Error(
        `importCapsule: manifest contains two entries that resolve to the same target path: ` +
          `"${firstSourcePath}" and "${rec.path}" both map to "${targetRel}"`,
      );
    }
    seenTargetPaths.set(dedupKey, rec.path);
  }
  // Detect manifest-only entries (missing record). Treat as corruption.
  for (const f of manifest.files) {
    if (!recordPaths.has(f.path)) {
      throw new Error(
        `importCapsule: archive checksum mismatch (manifest entry without record: ${f.path})`,
      );
    }
  }

  // Phase 2: apply the mode. All records were validated in phase 1; we now
  // write to disk. Per-record errors propagate; each individual write is
  // atomic (mkdir + writeFile pair).
  const imported: ImportCapsuleImportedRecord[] = [];
  const skipped: ImportCapsuleSkippedRecord[] = [];
  // The target's completed migration journal is a write boundary here too
  // (issue #2213): a capsule can carry pre-migration memories whose entityRef
  // the target already renamed, and no recurring reconciliation pass exists
  // to absorb a stale ref after the fact. Read through the identity-keyed
  // cache PER RECORD so a peer migration completing mid-import is picked up
  // for every record written after it (one lstat per record).
  const journalStateDir = path.join(rootReal, "state");
  const historicalIdCache = new HistoricalEntityCanonicalIdCache();
  // Entity pages in THIS capsule can re-establish collisions the target's
  // journal already resolved (Codex P1): once the next migration parks the
  // mapping, a memory canonicalized onto the canonical claimant is
  // permanently misattributed. Memories whose ref targets a capsule-supplied
  // entity id import byte-faithful behind the reconcile marker instead; the
  // migration settles the collision and rewrites references per its verdict.
  const capsuleEntityIds = new Set(
    bundle.records
      .map((record) => computeTargetPath(record.path, mode, capsule.id))
      .filter((rel) => classifyEntityRefWritePath(rootReal, path.join(rootReal, fromPosixRelPath(rel))) === "entity")
      .map((rel) => path.basename(rel, ".md")),
  );

  // Sort by source path so the imported/skipped lists are deterministic
  // regardless of bundle order. (`exportCapsule` already sorts; we re-sort
  // defensively in case a hand-edited archive ships records in another order.)
  const sortedRecords = [...bundle.records].sort((a, b) =>
    a.path.localeCompare(b.path),
  );

  // The reconcile marker is published ONCE, after every record landed
  // (Codex P1, round 21): a per-record marker could be consumed by a peer
  // between a legacy-preserving memory write and its colliding entity page,
  // canonicalizing the memory onto the wrong claimant irreversibly.
  let reconcileNeeded = false;
  const applyRecords = async (): Promise<void> => {
  for (const rec of sortedRecords) {
    const targetRel = computeTargetPath(rec.path, mode, capsule.id);
    // Use rootReal (realpath-resolved) to stay consistent with phase 1's
    // traversal validation and avoid writing through stale symlinks.
    const targetAbs = path.join(rootReal, fromPosixRelPath(targetRel));

    const exists = await fileExistsAt(targetAbs);

    // Skip logic applies to both `skip` mode (explicit) and `fork` mode
    // (Cursor medium: fork mode must also be skip-on-exist for the computed
    // fork path, because production imports generate non-deterministic IDs —
    // so re-importing the same capsule should not overwrite user edits in the
    // fork tree or silently change file identities by generating new IDs).
    if ((mode === "skip" || mode === "fork") && exists) {
      skipped.push({ path: rec.path, reason: "exists" });
      continue;
    }

    let snapshotted = false;
    if (mode === "overwrite" && exists) {
      // Gotcha #54: snapshot BEFORE overwriting. If snapshot creation fails
      // we abort this record's import rather than silently destroying
      // history. The page-versioning module is responsible for atomic
      // sidecar writes; we just call it.
      if (opts.versioning && opts.versioning.enabled) {
        const prior = await readFile(targetAbs, "utf-8").catch(() => "");
        await createVersion(
          targetAbs,
          prior,
          "manual",
          opts.versioning,
          opts.log,
          `capsule-import: ${capsule.id}`,
          rootReal,
        );
        snapshotted = true;
      }
    }

    let contentToWrite = rec.content;
    let rewroteId = false;
    if (mode === "fork") {
      const forked = rewriteFrontmatterIdForFork(contentToWrite, capsule.id, opts.now);
      contentToWrite = forked.content;
      rewroteId = forked.rewrote;
    }

    await mkdir(path.dirname(targetAbs), { recursive: true });
    // Resolve at the write itself (mirrors capsule-merge): a peer migration
    // can complete during the snapshot/mkdir awaits, and capsule writes bump
    // only the corpus version, which the migration fingerprint ignores. The
    // post-write REPAIR re-canonicalizes and rewrites when the journal moved
    // across the write itself (a parked mapping cannot be fixed after the
    // fact by the reconcile pass). Only memory-tier records canonicalize;
    // entities/ pages carry relationship TARGETS only
    // rewriteRelationshipTargets understands, so they import byte-faithful
    // with a reconcile marker; everything else imports losslessly.
    const targetKind = classifyEntityRefWritePath(rootReal, targetAbs);
    const rawRef = targetKind === "memory" ? readEntityRefFromFrontmatter(contentToWrite) : null;
    if (targetKind === "memory" && rawRef !== null && capsuleEntityIds.has(rawRef)) {
      // Ref targets a capsule-supplied entity page (potential collision
      // claimant): keep the legacy bytes; the DEFERRED marker below lets the
      // migration settle the collision and rewrite per its verdict (Codex P1).
      await writeFile(targetAbs, contentToWrite, "utf-8");
      reconcileNeeded = true;
    } else if (targetKind === "memory") {
      const idsAtWrite = historicalIdCache.get(journalStateDir);
      const rawRecord = contentToWrite;
      contentToWrite = canonicalizeEntityRefFrontmatter(rawRecord, idsAtWrite);
      // Snapshot the pre-write bytes: a repair failure after the write must
      // restore them (or remove a newly created target), or the import
      // reports failure while an overwrite already destroyed the prior state
      // and the skipped corpus bump leaves warm caches stale (AGENTS.md §14).
      const originalBytes = await readFile(targetAbs, "utf-8").catch(() => null);
      await writeFile(targetAbs, contentToWrite, "utf-8");
      try {
        await repairContentAfterJournalMove({
          stateDir: journalStateDir,
          cache: historicalIdCache,
          idsAtWrite,
          rawContent: rawRecord,
          lastWritten: contentToWrite,
          rewrite: (content) => writeFile(targetAbs, content, "utf-8"),
        });
      } catch (err) {
        if (originalBytes === null) {
          await unlink(targetAbs).catch(() => undefined);
        } else {
          await writeFile(targetAbs, originalBytes, "utf-8").catch(() => undefined);
        }
        throw err;
      }
    } else {
      await writeFile(targetAbs, contentToWrite, "utf-8");
      if (targetKind === "entity") {
        reconcileNeeded = true;
      }
    }
    // Bump the corpus sentinel per write (Cursor Medium, #1902): a concurrent
    // readAllMemories during the import must rescan and see records already on
    // disk, never the pre-import corpus, mid-batch.
    bumpMemoryCorpusVersionForDir(rootReal);
    imported.push({
      sourcePath: rec.path,
      targetPath: targetRel,
      snapshotted,
      rewroteId,
    });
  }

  // Every record — including every collision claimant entity page — is on
  // disk; NOW the reconcile pass can settle collisions safely.
  if (reconcileNeeded) {
    await requestEntityCanonicalIdReconcile(journalStateDir);
  }
  };
  const firstEntityId = capsuleEntityIds.values().next().value;
  if (firstEntityId === undefined) {
    await applyRecords();
  } else {
    await withRawEntityPageMutation(
      rootReal,
      path.join(rootReal, "entities", `${firstEntityId}.md`),
      applyRecords,
    );
  }

  // Sort skipped for stable output (see comment above).
  skipped.sort((a, b) => a.path.localeCompare(b.path));

  // Per-record corpus bumps happen inside the loop above (Cursor Medium,
  // #1902); no after-batch bump needed here.

  return { imported, skipped, manifest };
}

// ---------------------------------------------------------------------------
// Path helpers
// ---------------------------------------------------------------------------

/**
 * Compute the destination relative path for a record under the chosen
 * mode.
 *
 *  - `skip` / `overwrite` — identity: the record's posix path is used as-is.
 *  - `fork` — rebased under `forks/<capsule-id>/<original-path>` so the
 *    original tree is never modified.
 */
function computeTargetPath(
  sourcePosix: string,
  mode: ImportCapsuleMode,
  capsuleId: string,
): string {
  if (mode === "fork") return `forks/${capsuleId}/${sourcePosix}`;
  return sourcePosix;
}

async function fileExistsAt(absPath: string): Promise<boolean> {
  const st = await stat(absPath).catch(() => null);
  return st !== null && st.isFile();
}

// ---------------------------------------------------------------------------
// Fork-mode id rewriting
// ---------------------------------------------------------------------------

/**
 * Rewrite a YAML-frontmatter `id:` field to a fork-scoped value.
 *
 * Strategy: we deliberately do NOT parse the entire YAML — memory files
 * use a deterministic top-of-file frontmatter delimited by `---` lines,
 * and the orchestrator's `parseFrontmatter` reads `id` as a top-level
 * key with a single-line scalar value. We mirror that contract:
 *
 *   - Detect a leading `---\n` … `\n---` block at the top of the file.
 *   - Within that block, locate the first `id:` line that is not nested
 *     under another key (cheap heuristic: line starts at column 0).
 *   - Replace its value with a new fork-id derived from `capsuleId` and
 *     a short random suffix (or {@link opts.now} when provided for tests).
 *
 * Files without a frontmatter block, or without an `id:` key inside one,
 * are returned unchanged with `rewrote: false`. This keeps non-memory
 * artifacts (READMEs, transcripts) byte-identical to the source.
 */
function rewriteFrontmatterIdForFork(
  content: string,
  capsuleId: string,
  now: number | undefined,
): { content: string; rewrote: boolean } {
  // Detect the dominant line ending in the file so we can preserve it when
  // rebuilding the frontmatter delimiters. Splitting/joining on `\n` silently
  // drops `\r` from CRLF files, changing the byte content (Cursor thread #741
  // line 467). We detect the ending of the very first line (the opening `---`)
  // and use that as the canonical separator for the reconstructed delimiters.
  // All three cases are covered: CRLF (\r\n), LF (\n), and bare CR (\r).
  const crlfMatch = /^---(\r\n|\r|\n)/.exec(content);
  // Fall back to LF if the file starts with `---` but has no newline (EOF).
  const eol = crlfMatch ? crlfMatch[1] : "\n";

  // Frontmatter block detection: `---` on its own line at the very start,
  // followed by content, followed by `---` on its own line. The closing
  // delimiter must be at column 0. We capture the trailing terminator
  // (`\r?\n` or end-of-string) as a separate group so we can re-emit it
  // verbatim, preserving CRLF/LF/EOF shape from the original file.
  const fmMatch = /^---\r?\n([\s\S]*?)\r?\n---(\r?\n|$)/.exec(content);
  if (!fmMatch) return { content, rewrote: false };
  const fmBody = fmMatch[1];
  const fmTrailer = fmMatch[2];
  const fmStart = fmMatch.index;
  const fmEnd = fmStart + fmMatch[0].length;

  // Find a top-level `id:` line. Top-level means the line begins at
  // column 0 inside the frontmatter body (no leading whitespace) and the
  // key is exactly `id`. We deliberately accept `id:` and `id : ` shapes
  // but reject `nested_id:` to avoid touching unrelated keys.
  const idLineRe = /^id:[ \t]*([^\r\n]*)$/m;
  const idMatch = idLineRe.exec(fmBody);
  if (!idMatch) return { content, rewrote: false };

  const newId = mintForkId(capsuleId, idMatch[1]?.trim() ?? "", now);
  const replacedBody = fmBody.replace(idLineRe, `id: ${newId}`);
  // Reconstruct the file: original prefix (always empty here, fmStart === 0
  // by the `^` anchor) + frontmatter delimiters around the rewritten body.
  // Use the detected `eol` for the opening/closing `---` lines so that CRLF
  // files remain CRLF and LF files remain LF, preserving byte-content fidelity
  // (Cursor thread #741 line 467).  The captured `fmTrailer` (the newline
  // immediately after the closing `---`, or end-of-string) is re-emitted
  // verbatim so the byte immediately after the closing fence is unchanged.
  const prefix = content.slice(0, fmStart);
  const tail = content.slice(fmEnd);
  const rebuilt = `${prefix}---${eol}${replacedBody}${eol}---${fmTrailer}${tail}`;
  return { content: rebuilt, rewrote: true };
}

/**
 * Derive a deterministic-when-`now`-is-set fork id from the capsule id and
 * the original record id. Production callers omit `now` and get a UUID
 * suffix; tests pass `now` for byte-stable assertions.
 */
function mintForkId(capsuleId: string, originalId: string, now: number | undefined): string {
  const base = originalId.length > 0 ? originalId : "fork";
  if (now === undefined) {
    const suffix = randomUUID().slice(0, 8);
    return `${base}-fork-${capsuleId}-${suffix}`;
  }
  // Deterministic suffix: short hash of (capsuleId, originalId, now). Using
  // sha256 over a sorted-key serialization (gotcha #38) so the suffix does
  // not depend on Object.entries order.
  const payload = JSON.stringify({ c: capsuleId, i: originalId, n: now });
  const suffix = createHash("sha256").update(payload, "utf-8").digest("hex").slice(0, 8);
  return `${base}-fork-${capsuleId}-${suffix}`;
}

// Note: `CapsuleBlock` is re-exported here purely so callers that want to
// inspect the manifest block don't have to deep-import from `./types.js`.
