interface WindowEntry {
  count: number;
  resetAt: number;
}

interface WindowReservation {
  commit(): void;
  release(): void;
}

class UnreadSupportPassportRequestError extends Error {
  constructor(readonly response: SupportPassportError) {
    super(response.message);
    this.name = "UnreadSupportPassportRequestError";
  }
}

class FixedWindowLimiter {
  private readonly entries = new Map<string, WindowEntry>();

  constructor(
    private readonly limit: number,
    private readonly windowMs: number,
    private readonly now: () => number
  ) {}

  consume(key: string): boolean {
    const reservation = this.reserve(key);
    if (!reservation) return false;
    reservation.commit();
    return true;
  }

  reserve(key: string): WindowReservation | undefined {
    const now = this.now();
    let entry = this.entries.get(key);
    if (!entry || entry.resetAt <= now) {
      if (!entry && this.entries.size >= PUBLIC_RATE_LIMIT_MAX_KEYS) {
        this.prune(now);
        if (this.entries.size >= PUBLIC_RATE_LIMIT_MAX_KEYS) return undefined;
      }
      entry = { count: 0, resetAt: now + this.windowMs };
      this.entries.set(key, entry);
    }
    if (entry.count >= this.limit) return undefined;
    entry.count += 1;
    let active = true;
    return {
      commit: () => {
        active = false;
      },
      release: () => {
        if (!active) return;
        active = false;
        if (this.entries.get(key) !== entry) return;
        entry.count -= 1;
        if (entry.count === 0) this.entries.delete(key);
      },
    };
  }

  allows(key: string): boolean {
    const now = this.now();
    const current = this.entries.get(key);
    if (current && current.resetAt > now) return current.count < this.limit;
    if (!current && this.entries.size >= PUBLIC_RATE_LIMIT_MAX_KEYS) {
      this.prune(now);
      if (this.entries.size >= PUBLIC_RATE_LIMIT_MAX_KEYS) return false;
    }
    return true;
  }

  private prune(now: number): void {
    for (const [key, entry] of this.entries) {
      if (entry.resetAt <= now) this.entries.delete(key);
    }
  }
}

class InFlightLimiter {
  private readonly counts = new Map<string, number>();
  private total = 0;

  constructor(
    private readonly perKeyLimit: number,
    private readonly totalLimit: number
  ) {}

  reserve(key: string): (() => void) | undefined {
    const current = this.counts.get(key) ?? 0;
    if (current >= this.perKeyLimit || this.total >= this.totalLimit) return undefined;
    this.counts.set(key, current + 1);
    this.total += 1;
    let active = true;
    return () => {
      if (!active) return;
      active = false;
      const count = this.counts.get(key) ?? 0;
      if (count <= 1) this.counts.delete(key);
      else this.counts.set(key, count - 1);
      this.total -= 1;
    };
  }
}

interface PublicRateLimits {
  authentications: InFlightLimiter;
  modelCalls: InFlightLimiter;
  grantReads: FixedWindowLimiter;
  networkReads: FixedWindowLimiter;
  networkReadFailures: FixedWindowLimiter;
  grantQuestions: FixedWindowLimiter;
  networkQuestions: FixedWindowLimiter;
  networkQuestionFailures: FixedWindowLimiter;
}

export interface SupportPassportPublicHandlerOptions {
  now?: () => number;
  trustedProxyAddresses?: readonly string[];
}

function createRateLimits(now: () => number): PublicRateLimits {
  return {
    authentications: new InFlightLimiter(PUBLIC_AUTH_MAX_IN_FLIGHT_PER_NETWORK, PUBLIC_AUTH_MAX_IN_FLIGHT_TOTAL),
    modelCalls: new InFlightLimiter(PUBLIC_MODEL_MAX_IN_FLIGHT_PER_NETWORK, PUBLIC_MODEL_MAX_IN_FLIGHT_TOTAL),
    grantReads: new FixedWindowLimiter(60, 60_000, now),
    networkReads: new FixedWindowLimiter(60, 60_000, now),
    networkReadFailures: new FixedWindowLimiter(60, 60_000, now),
    grantQuestions: new FixedWindowLimiter(20, 10 * 60_000, now),
    networkQuestions: new FixedWindowLimiter(20, 10 * 60_000, now),
    networkQuestionFailures: new FixedWindowLimiter(20, 10 * 60_000, now),
  };
}

function rateLimited(): SupportPassportError {
  return new SupportPassportError("rate_limited", "Too many helper requests.", 429);
}

async function runPublicOperation(
  service: EngramAccessService,
  name: "support_passport_grant_read" | "support_passport_grant_ask",
  input: Record<string, unknown>,
  signal?: AbortSignal
): Promise<unknown> {
  const operation = getOperation(name);
  if (!operation) throw new Error(`access-boundary: operation not registered: ${name}`);
  const output = (await operation.run(input, {
    service,
    ...(signal ? { abortSignal: signal } : {}),
  })) as { result: unknown };
  return output.result;
}

function reserveAuthenticatedLimits(
  networkLimiter: FixedWindowLimiter,
  grantLimiter: FixedWindowLimiter,
  networkKey: string,
  grantId: string
): WindowReservation {
  const network = networkLimiter.reserve(networkKey);
  if (!network) throw rateLimited();
  const grant = grantLimiter.reserve(grantId);
  if (!grant) {
    network.release();
    throw rateLimited();
  }
  let active = true;
  return {
    commit: () => {
      if (!active) return;
      active = false;
      network.commit();
      grant.commit();
    },
    release: () => {
      if (!active) return;
      active = false;
      grant.release();
      network.release();
    },
  };
}

async function readGrantUnderAuthenticationReservation(
  service: EngramAccessService,
  grantId: string,
  secret: string,
  networkKey: string,
  networkLimiter: FixedWindowLimiter,
  grantLimiter: FixedWindowLimiter,
  failureLimiter: FixedWindowLimiter
) {
  if (!failureLimiter.allows(networkKey)) throw rateLimited();
  const limits = reserveAuthenticatedLimits(networkLimiter, grantLimiter, networkKey, grantId);
  let guide: Awaited<ReturnType<EngramAccessService["supportPassportReadGrant"]>>;
  try {
    guide = (await runPublicOperation(service, "support_passport_grant_read", { grantId, secret })) as Awaited<
      ReturnType<EngramAccessService["supportPassportReadGrant"]>
    >;
  } catch (error) {
    if (error instanceof SupportPassportError) {
      if (error.code === "grant_not_found") {
        limits.release();
        if (!failureLimiter.consume(networkKey)) throw rateLimited();
      } else {
        limits.commit();
      }
    } else {
      limits.release();
    }
    throw error;
  }
  limits.commit();
  return guide;
}

async function readGrantWithRateLimits(
  service: EngramAccessService,
  grantId: string,
  secret: string,
  networkKey: string,
  networkLimiter: FixedWindowLimiter,
  grantLimiter: FixedWindowLimiter,
  failureLimiter: FixedWindowLimiter,
  authenticationLimiter: InFlightLimiter
) {
  const releaseAuthentication = authenticationLimiter.reserve(networkKey);
  if (!releaseAuthentication) throw rateLimited();
  try {
    return await readGrantUnderAuthenticationReservation(
      service,
      grantId,
      secret,
      networkKey,
      networkLimiter,
      grantLimiter,
      failureLimiter
    );
  } finally {
    releaseAuthentication();
  }
}

export function normalizeSupportPassportNetworkAddress(value: string | undefined): string | undefined {
  if (!value) return undefined;
  const address = value.trim().toLowerCase();
  const family = isIP(address);
  if (family === 0) return undefined;
  if (family === 4) return address;
  const canonical = new URL(`http://[${address}]/`).hostname.slice(1, -1);
  const mapped = /^::ffff:([0-9a-f]{1,4}):([0-9a-f]{1,4})$/.exec(canonical);
  if (!mapped) return canonical;
  const high = Number.parseInt(mapped[1] ?? "", 16);
  const low = Number.parseInt(mapped[2] ?? "", 16);
  return `${high >>> 8}.${high & 0xff}.${low >>> 8}.${low & 0xff}`;
}

function requestNetworkAddress(req: IncomingMessage, trustedProxyAddresses: ReadonlySet<string>): string {
  const directAddress = normalizeSupportPassportNetworkAddress(req.socket.remoteAddress) ?? "unknown";
  if (!trustedProxyAddresses.has(directAddress)) return directAddress;
  const forwarded = req.headers["x-forwarded-for"];
  if (typeof forwarded !== "string") return directAddress;
  const rawAddresses = forwarded.split(",");
  if (rawAddresses.length < 1 || rawAddresses.length > 32) return directAddress;
  const addresses = rawAddresses.map((address) => normalizeSupportPassportNetworkAddress(address));
  if (addresses.some((address) => address === undefined)) return directAddress;
  for (let index = addresses.length - 1; index >= 0; index -= 1) {
    const address = addresses[index];
    if (address && !trustedProxyAddresses.has(address)) return address;
  }
  return addresses[0] ?? directAddress;
}

function networkDigest(req: IncomingMessage, trustedProxyAddresses: ReadonlySet<string>): string {
  return createHash("sha256")
    .update(requestNetworkAddress(req, trustedProxyAddresses))
    .digest("hex");
}

function parseSecret(req: IncomingMessage): string | undefined {
  const raw = req.headers.authorization;
  if (typeof raw !== "string") return undefined;
  const match = /^(\S+)[ \t]+(\S+)$/.exec(raw);
  if (!match || match[1]?.toLowerCase() !== "supportpassport") return undefined;
  const secret = match[2] ?? "";
  if (!/^[A-Za-z0-9_-]{32,256}$/.test(secret)) return undefined;
  return secret;
}

function requestDeclaresBody(req: IncomingMessage): boolean {
  const contentLength = req.headers["content-length"];
  const transferEncoding = req.headers["transfer-encoding"];
  return transferEncoding !== undefined || (contentLength !== undefined && contentLength !== "0");
}

function respondJson(res: ServerResponse, status: number, payload: unknown): void {
  const body = JSON.stringify(payload);
  res.statusCode = status;
  res.setHeader("cache-control", "private, no-store");
  res.setHeader("vary", "Authorization");
  res.setHeader("content-type", "application/json; charset=utf-8");
  res.setHeader("content-length", String(Buffer.byteLength(body)));
  res.end(body);
}

function respondJsonAndCloseUnreadRequest(
  req: IncomingMessage,
  res: ServerResponse,
  status: number,
  payload: unknown
): void {
  res.shouldKeepAlive = false;
  res.setHeader("connection", "close");
  res.once("finish", () => req.destroy());
  respondJson(res, status, payload);
}

function respondBeforeReadingBody(
  req: IncomingMessage,
  res: ServerResponse,
  status: number,
  payload: unknown
): void {
  if (requestDeclaresBody(req)) {
    respondJsonAndCloseUnreadRequest(req, res, status, payload);
    return;
  }
  respondJson(res, status, payload);
}

async function readQuestionBody(req: IncomingMessage, signal: AbortSignal): Promise<string> {
  const content = await new Promise<Buffer>((resolve, reject) => {
    const chunks: Buffer[] = [];
    let bytes = 0;
    let settled = false;
    const cleanup = () => {
      req.off("data", onData);
      req.off("end", onEnd);
      req.off("error", onError);
      req.off("aborted", onAborted);
      signal.removeEventListener("abort", onSignalAbort);
    };
    const fail = (error: unknown) => {
      if (settled) return;
      settled = true;
      cleanup();
      reject(error);
    };
    const helperLeft = () =>
      isAbortError(signal.reason) ? signal.reason : abortError("The helper left.");
    const onData = (chunk: Buffer | string) => {
      const buffer = Buffer.isBuffer(chunk) ? chunk : Buffer.from(chunk);
      bytes += buffer.length;
      if (bytes > 4_096) {
        req.pause();
        fail(
          new UnreadSupportPassportRequestError(
            new SupportPassportError("invalid_input", "The helper question is invalid.", 400)
          )
        );
        return;
      }
      chunks.push(buffer);
    };
    const onEnd = () => {
      if (settled) return;
      settled = true;
      cleanup();
      resolve(Buffer.concat(chunks, bytes));
    };
    const onError = (error: Error) => fail(signal.aborted || req.aborted ? helperLeft() : error);
    const onAborted = () => fail(helperLeft());
    const onSignalAbort = () => fail(helperLeft());
    req.on("data", onData);
    req.once("end", onEnd);
    req.once("error", onError);
    req.once("aborted", onAborted);
    signal.addEventListener("abort", onSignalAbort, { once: true });
    if (signal.aborted) onSignalAbort();
  });
  let parsed: unknown;
  try {
    parsed = JSON.parse(content.toString("utf8"));
  } catch {
    throw new SupportPassportError("invalid_input", "The helper question is invalid.", 400);
  }
  if (!parsed || typeof parsed !== "object" || Array.isArray(parsed)) {
    throw new SupportPassportError("invalid_input", "The helper question is invalid.", 400);
  }
  const body = parsed as Record<string, unknown>;
  if (Object.keys(body).length !== 1 || typeof body.question !== "string") {
    throw new SupportPassportError("invalid_input", "The helper question is invalid.", 400);
  }
  const question = body.question.trim();
  if (question.length < 1 || question.length > 500) {
    throw new SupportPassportError("invalid_input", "The helper question is invalid.", 400);
  }
  return question;
}

function requestSignal(req: IncomingMessage, res: ServerResponse): { signal: AbortSignal; cleanup(): void } {
  const controller = new AbortController();
  const abort = () => {
    if (!res.writableFinished && !controller.signal.aborted) controller.abort(abortError("The helper left."));
  };
  req.once("aborted", abort);
  res.once("close", abort);
  return {
    signal: controller.signal,
    cleanup: () => {
      req.off("aborted", abort);
      res.off("close", abort);
    },
  };
}

function decodeGrantId(raw: string): string | undefined {
  try {
    const value = decodeURIComponent(raw);
    return /^[A-Za-z0-9_-]{1,128}$/.test(value) ? value.toLowerCase() : undefined;
  } catch {
    return undefined;
  }
}

export function buildSupportPassportPublicRequestHandler(
  service: EngramAccessService,
  options: SupportPassportPublicHandlerOptions = {}
): SupportPassportExternalRequestHandler {
  const rateLimits = createRateLimits(options.now ?? Date.now);
  const trustedProxyAddresses = new Set(
    (options.trustedProxyAddresses ?? [])
      .map((address) => normalizeSupportPassportNetworkAddress(address))
      .filter((address): address is string => address !== undefined)
  );
  return async (req, res) => {
    let parsed: URL;
    try {
      parsed = new URL(req.url ?? "/", "http://placeholder");
    } catch {
      return false;
    }
    const readMatch = /^\/engram\/v1\/support-passport\/public\/grants\/([^/]+)$/.exec(parsed.pathname);
    const askMatch = /^\/engram\/v1\/support-passport\/public\/grants\/([^/]+)\/ask$/.exec(parsed.pathname);
    const ownedRead = req.method === "GET" && readMatch;
    const ownedQuestion = req.method === "POST" && askMatch;
    if (!ownedRead && !ownedQuestion) return false;

    res.setHeader("cache-control", "private, no-store");
    res.setHeader("vary", "Authorization");
    const grantId = decodeGrantId((ownedRead ? readMatch?.[1] : askMatch?.[1]) ?? "");
    const secret = parseSecret(req);
    if (parsed.search.length > 0) {
      respondBeforeReadingBody(req, res, 400, {
        error: "The share link request is invalid.",
        code: "invalid_input",
      });
      return true;
    }
    if (ownedRead && requestDeclaresBody(req)) {
      respondJsonAndCloseUnreadRequest(req, res, 400, {
        error: "The share link request is invalid.",
        code: "invalid_input",
      });
      return true;
    }
    if (!grantId || !secret) {
      respondBeforeReadingBody(req, res, 404, {
        error: "The share link was not found.",
        code: "grant_not_found",
      });
      return true;
    }

    const lifecycle = requestSignal(req, res);
    try {
      const digest = networkDigest(req, trustedProxyAddresses);
      if (ownedRead) {
        const guide = await readGrantWithRateLimits(
          service,
          grantId,
          secret,
          digest,
          rateLimits.networkReads,
          rateLimits.grantReads,
          rateLimits.networkReadFailures,
          rateLimits.authentications
        );
        respondJson(res, 200, guide);
      } else {
        let releaseAuthentication = rateLimits.authentications.reserve(digest);
        if (!releaseAuthentication) throw new UnreadSupportPassportRequestError(rateLimited());
        try {
          let question: string;
          const bodyFailure = rateLimits.networkQuestionFailures.reserve(digest);
          if (!bodyFailure) throw new UnreadSupportPassportRequestError(rateLimited());
          try {
            question = await readQuestionBody(req, lifecycle.signal);
            bodyFailure.release();
          } catch (error) {
            const supportError =
              error instanceof UnreadSupportPassportRequestError ? error.response : error;
            if (supportError instanceof SupportPassportError && supportError.code === "invalid_input") {
              bodyFailure.commit();
            } else {
              bodyFailure.release();
            }
            throw error;
          }
          const releaseModelCall = rateLimits.modelCalls.reserve(digest);
          if (!releaseModelCall) throw rateLimited();
          try {
            await readGrantUnderAuthenticationReservation(
              service,
              grantId,
              secret,
              digest,
              rateLimits.networkQuestions,
              rateLimits.grantQuestions,
              rateLimits.networkQuestionFailures
            );
            releaseAuthentication();
            releaseAuthentication = undefined;
            const answer = await runPublicOperation(
              service,
              "support_passport_grant_ask",
              { grantId, secret, question },
              lifecycle.signal
            );
            respondJson(res, 200, answer);
          } finally {
            releaseModelCall();
          }
        } finally {
          releaseAuthentication?.();
        }
      }
    } catch (error) {
      if (error instanceof UnreadSupportPassportRequestError) {
        respondJsonAndCloseUnreadRequest(req, res, error.response.status, {
          error: error.response.message,
          code: error.response.code,
        });
        return true;
      }
      if (!(error instanceof SupportPassportError)) throw error;
      respondJson(res, error.status, { error: error.message, code: error.code });
    } finally {
      lifecycle.cleanup();
    }
    return true;
  };
}

export function composeSupportPassportExternalRequestHandlers(
  ...handlers: Array<SupportPassportExternalRequestHandler | undefined>
): SupportPassportExternalRequestHandler {
  return async (req, res, ctx) => {
    for (const handler of handlers) {
      if (handler && (await handler(req, res, ctx))) return true;
    }
    return false;
  };
}

import { createHash } from "node:crypto";
import path from "node:path";
import { z } from "zod";

import { expandTildePath } from "../utils/path.js";
import { serializeMutations, withHeldFileLock } from "../utils/serialize-mutations.js";
import {
  appendPrivateFileInPinnedDirectory,
  ensurePrivateDirectoryNoFollow,
  ensurePrivateDirectoryTreeNoFollow,
  withPrivateDirectoryNoFollow,
} from "./private-file.js";

const HashSchema = z.string().regex(/^[a-f0-9]{64}$/);

export const SupportPassportModelAuditRecordSchema = z
  .object({
    schemaVersion: z.literal(1),
    operation: z.enum(["draft_cards", "answer_question"]),
    actorHash: HashSchema,
    subjectIdsHash: HashSchema,
    modelUsed: z.string().trim().min(1).max(256),
    route: z.enum(["local", "direct", "gateway", "unavailable"]),
    outputSchemaVersion: z.literal(1),
    outcome: z.enum(["success", "error"]),
    errorClass: z
      .string()
      .trim()
      .min(1)
      .max(64)
      .regex(/^[a-z0-9_-]+$/)
      .optional(),
    occurredAt: z.string().datetime({ offset: true }),
    latencyMs: z.number().int().nonnegative(),
    usage: z
      .object({
        inputTokens: z.number().int().nonnegative().optional(),
        outputTokens: z.number().int().nonnegative().optional(),
        totalTokens: z.number().int().nonnegative().optional(),
      })
      .strict()
      .optional(),
  })
  .strict()
  .superRefine((record, ctx) => {
    if (record.outcome === "error" && !record.errorClass) {
      ctx.addIssue({
        code: z.ZodIssueCode.custom,
        message: "error records require an error class",
        path: ["errorClass"],
      });
    }
    if (record.outcome === "success" && record.errorClass) {
      ctx.addIssue({
        code: z.ZodIssueCode.custom,
        message: "success records cannot have an error class",
        path: ["errorClass"],
      });
    }
  });

export type SupportPassportModelAuditRecord = z.infer<typeof SupportPassportModelAuditRecordSchema>;

export interface SupportPassportModelAuditSink {
  record(record: SupportPassportModelAuditRecord): Promise<void>;
}

export function hashSupportPassportAuditValues(domain: string, values: string[]): string {
  return createHash("sha256")
    .update(`support-passport-audit:${domain}:v1`)
    .update("\0")
    .update([...values].sort().join("\0"))
    .digest("hex");
}

export class SupportPassportModelAuditStore implements SupportPassportModelAuditSink {
  private memoryDir: string;
  private auditDir: string;
  private memoryRootReady?: Promise<void>;
  private readonly runWithHeldFileLock: typeof withHeldFileLock;

  constructor(options: {
    memoryDir: string;
    withHeldFileLock?: typeof withHeldFileLock;
  }) {
    this.memoryDir = path.resolve(expandTildePath(options.memoryDir));
    this.auditDir = path.join(this.memoryDir, "state", "support-passport", "audit");
    this.runWithHeldFileLock = options.withHeldFileLock ?? withHeldFileLock;
  }

  async record(input: SupportPassportModelAuditRecord): Promise<void> {
    const record = SupportPassportModelAuditRecordSchema.parse(input);
    await this.ensureSafeDirectories();
    const day = record.occurredAt.slice(0, 10);
    const filePath = path.join(this.auditDir, `${day}.jsonl`);
    await serializeMutations(`support-passport-audit:${filePath}`, () =>
      withPrivateDirectoryNoFollow(
        this.memoryDir,
        this.auditDir,
        "support passport audit directory must remain inside the memory directory",
        async (pinnedDirectory) =>
          await this.runWithHeldFileLock(
            path.join(pinnedDirectory, `.${day}.lock`),
            {
              staleMs: 30_000,
              maxWaitMs: 5_000,
              heartbeatMs: 10_000,
            },
            async (acquired) => {
              if (!acquired) throw new Error("could not acquire the support passport audit lock");
              await appendPrivateFileInPinnedDirectory(
                pinnedDirectory,
                `${day}.jsonl`,
                `${JSON.stringify(record)}\n`,
                "support passport audit paths must be regular files in a stable directory"
              );
            }
          )
      )
    );
  }

  private async ensureSafeDirectories(): Promise<void> {
    await this.ensureMemoryRoot();
    await ensurePrivateDirectoryNoFollow(
      this.memoryDir,
      this.auditDir,
      "support passport audit directory must remain inside the memory directory"
    );
  }

  private async ensureMemoryRoot(): Promise<void> {
    if (!this.memoryRootReady) {
      const configuredMemoryDir = this.memoryDir;
      this.memoryRootReady = (async () => {
        await ensurePrivateDirectoryTreeNoFollow(
          configuredMemoryDir,
          "support passport memory directory must be a stable directory"
        );
        this.memoryDir = configuredMemoryDir;
        this.auditDir = path.join(configuredMemoryDir, "state", "support-passport", "audit");
      })();
    }
    const currentAttempt = this.memoryRootReady;
    try {
      await currentAttempt;
    } catch (error) {
      if (this.memoryRootReady === currentAttempt) this.memoryRootReady = undefined;
      throw error;
    }
  }
}

/**
 * Per-principal write rate limiter for the access HTTP surface
 * (issues #1937 / #2029).
 *
 * Extracted from access-http.ts so the limiter is a cohesive unit. Each
 * principal (authenticated caller identity) gets its own rolling-window
 * bucket, so one chatty connector cannot starve writes for the others;
 * requests with no resolved principal share a single global bucket.
 *
 * Deliberately transport-agnostic: it never throws `HttpError` — callers
 * translate a refusal into their own 429. It logs a sampled warning when it
 * refuses a write, so a sustained limit condition is diagnosable server-side
 * (previously the refusal was a bare throw with no trace).
 */

import { log } from "./logger.js";

// Defaults; overridable per instance via the constructor (config/env feed these
// through the server's `writeRateLimit*` settings).
const DEFAULT_WINDOW_MS = 60_000;
const DEFAULT_MAX_REQUESTS = 30;
// At most one rejection warning per this interval, carrying a rejected-count,
// so a storm is visible without flooding the log.
const LOG_INTERVAL_MS = 10_000;
// Bucket key for requests with no resolved principal.
const GLOBAL_BUCKET = "";

type Slot = { readonly recordedAt: number };

export interface WriteRateLimitReservation {
  commit(): void;
  release(): void;
}

function sanitizePositiveInteger(value: number | undefined, fallback: number): number {
  return typeof value === "number" && Number.isInteger(value) && value >= 1 ? value : fallback;
}

export class WriteRateLimiter {
  readonly maxRequests: number;
  readonly windowMs: number;
  // One rolling window per principal. Empty buckets are pruned so the map does
  // not grow without bound.
  private readonly buckets = new Map<string, Slot[]>();
  private readonly inFlight = new Map<string, number>();
  private lastLogAt = 0;
  private suppressed = 0;

  constructor(maxRequests?: number, windowMs?: number) {
    this.maxRequests = sanitizePositiveInteger(maxRequests, DEFAULT_MAX_REQUESTS);
    this.windowMs = sanitizePositiveInteger(windowMs, DEFAULT_WINDOW_MS);
  }

  private key(principal?: string): string {
    return principal?.trim() ? principal.trim() : GLOBAL_BUCKET;
  }

  private prune(slots: Slot[], now: number): void {
    while (slots.length > 0 && now - (slots[0]?.recordedAt ?? 0) >= this.windowMs) {
      slots.shift();
    }
  }

  /** Prune every bucket to the current window; drop buckets that go empty. */
  private sweep(now: number): void {
    for (const [key, slots] of this.buckets) {
      this.prune(slots, now);
      if (slots.length === 0) this.buckets.delete(key);
    }
  }

  /** Committed slots for a principal (test/introspection). */
  slotsFor(principal?: string): ReadonlyArray<Slot> {
    return this.buckets.get(this.key(principal)) ?? [];
  }

  inFlightFor(principal?: string): number {
    return this.inFlight.get(this.key(principal)) ?? 0;
  }

  /** Total live reservations across all principals (test/introspection). */
  totalSlots(): number {
    this.sweep(Date.now());
    let total = 0;
    for (const slots of this.buckets.values()) total += slots.length;
    for (const count of this.inFlight.values()) total += count;
    return total;
  }

  /** True if a write may proceed for the principal. Logs (sampled) when not. */
  hasCapacity(principal?: string): boolean {
    this.sweep(Date.now());
    const key = this.key(principal);
    const slots = this.buckets.get(key);
    if ((slots?.length ?? 0) + (this.inFlight.get(key) ?? 0) >= this.maxRequests) {
      this.logRejected(key);
      return false;
    }
    return true;
  }

  /** Record a committed write against the principal's rolling window. */
  record(principal?: string): void {
    this.sweep(Date.now());
    const key = this.key(principal);
    let slots = this.buckets.get(key);
    if (!slots) {
      slots = [];
      this.buckets.set(key, slots);
    }
    slots.push({ recordedAt: Date.now() });
  }

  /**
   * Reserve a slot for an in-flight write. Commit starts the rolling window
   * when persistence finishes. Release restores capacity after a failed write.
   */
  reserve(principal?: string): WriteRateLimitReservation | null {
    if (!this.hasCapacity(principal)) return null;
    const key = this.key(principal);
    this.inFlight.set(key, (this.inFlight.get(key) ?? 0) + 1);
    let active = true;
    const finish = (committed: boolean) => {
      if (!active) return;
      active = false;
      const count = this.inFlight.get(key) ?? 0;
      if (count <= 1) this.inFlight.delete(key);
      else this.inFlight.set(key, count - 1);
      if (committed) this.record(principal);
    };
    return { commit: () => finish(true), release: () => finish(false) };
  }

  private logRejected(principal: string): void {
    const now = Date.now();
    this.suppressed += 1;
    if (now - this.lastLogAt < LOG_INTERVAL_MS) return;
    const rejected = this.suppressed;
    this.suppressed = 0;
    this.lastLogAt = now;
    const who = principal === GLOBAL_BUCKET ? "(no principal)" : principal;
    log.warn(
      `write_rate_limited: rejected ${rejected} write(s) for principal ${who}; per-principal limit is ${this.maxRequests} per ${this.windowMs}ms. Raise server.writeRateLimitMaxRequests (or REMNIC_WRITE_RATE_LIMIT_MAX_REQUESTS) if sustained.`
    );
  }
}

import { createHash } from "node:crypto";

import { z } from "zod";

import { raceAbort, throwIfAborted } from "../abort-error.js";
import { log } from "../logger.js";
import { stripAttributesSuffix } from "../structured-attributes.js";
import type { MemoryFile } from "../types.js";
import { isSupportPassportPrivateMemory } from "./card-projection.js";
import type { SupportPassportCardService } from "./card-service.js";
import type { SupportPassportOwnerScope } from "./card-state.js";
import {
  type SupportPassportCard,
  SupportPassportListCardsInputSchema,
  SupportPassportNamespaceSchema,
  SupportPassportSourceMemoryIdSchema,
} from "./contracts.js";
import { SupportPassportError } from "./errors.js";
import type { SupportPassportGrantService } from "./grant-service.js";
import { type SupportPassportModelAdapter, SupportPassportModelCallError } from "./model-adapter.js";
import {
  type SupportPassportModelAuditRecord,
  type SupportPassportModelAuditSink,
  hashSupportPassportAuditValues,
} from "./model-audit.js";
import type { SupportPassportAnswerOutput } from "./model-contracts.js";

const DraftServiceInputSchema = z
  .object({
    principal: z.string().trim().min(1).max(512),
    sourceMemoryIds: z.array(SupportPassportSourceMemoryIdSchema).min(1).max(20),
    sourceMemoryRevisions: z
      .array(
        z
          .object({
            memoryId: SupportPassportSourceMemoryIdSchema,
            revision: z.string().regex(/^[0-9a-f]{64}$/),
          })
          .strict()
      )
      .min(1)
      .max(20),
    consent: z.literal(true),
  })
  .strict()
  .superRefine((input, ctx) => {
    if (new Set(input.sourceMemoryIds).size !== input.sourceMemoryIds.length) {
      ctx.addIssue({
        code: z.ZodIssueCode.custom,
        message: "source memory IDs must be unique",
        path: ["sourceMemoryIds"],
      });
    }
    const revisionIds = input.sourceMemoryRevisions.map((source) => source.memoryId);
    if (
      new Set(revisionIds).size !== revisionIds.length ||
      revisionIds.length !== input.sourceMemoryIds.length ||
      input.sourceMemoryIds.some((memoryId) => !revisionIds.includes(memoryId))
    ) {
      ctx.addIssue({
        code: z.ZodIssueCode.custom,
        message: "source memory revisions must match the selected memory IDs",
        path: ["sourceMemoryRevisions"],
      });
    }
  });

function hasStructuredAttributes(attributes: Readonly<Record<string, string>> | undefined): boolean {
  return attributes !== undefined && Object.keys(attributes).length > 0;
}

function supportPassportSourceContent(memory: Pick<MemoryFile, "content" | "frontmatter">): string {
  return hasStructuredAttributes(memory.frontmatter.structuredAttributes)
    ? stripAttributesSuffix(memory.content)
    : memory.content;
}

export function computeSupportPassportSourceRevision(
  content: string,
  structuredAttributes?: Record<string, string>
): string {
  return createHash("sha256")
    .update("support-passport-source:v1\0")
    .update(hasStructuredAttributes(structuredAttributes) ? stripAttributesSuffix(content) : content)
    .digest("hex");
}

export interface SupportPassportDraftServiceDependencies {
  cardService: SupportPassportCardService;
  modelAdapter: SupportPassportModelAdapter;
  resolveOwner(principal: string): Promise<SupportPassportOwnerScope>;
  audit: SupportPassportModelAuditSink;
  now?: () => Date;
}

export interface SupportPassportQuestionServiceDependencies {
  grantService: SupportPassportGrantService;
  modelAdapter: SupportPassportModelAdapter;
  audit: SupportPassportModelAuditSink;
  now?: () => Date;
}

export function isSupportPassportSourceEligible(memory: MemoryFile): boolean {
  const status = memory.frontmatter.status ?? "active";
  return (
    status === "active" &&
    !isSupportPassportPrivateMemory(memory) &&
    !memory.frontmatter.archivedAt &&
    !memory.frontmatter.blockedBy &&
    !memory.frontmatter.supersededBy
  );
}

function modelFailureAuditFields(error: unknown, signal: AbortSignal | undefined, latencyMs: number) {
  if (error instanceof SupportPassportModelCallError) {
    return { ...error.metadata, latencyMs };
  }
  if (error instanceof SupportPassportError) {
    return {
      modelUsed: "unavailable",
      route: "unavailable" as const,
      latencyMs,
      errorClass: error.code,
    };
  }
  return {
    modelUsed: "unavailable",
    route: "unavailable" as const,
    latencyMs,
    errorClass: signal?.aborted ? "aborted" : "provider_error",
  };
}

function operationErrorClass(error: unknown): string {
  return error instanceof SupportPassportError ? error.code : "operation_error";
}

async function recordAuditSafely(
  audit: SupportPassportModelAuditSink,
  record: SupportPassportModelAuditRecord
): Promise<void> {
  try {
    await audit.record(record);
  } catch {
    log.warn("support passport model audit write failed");
  }
}

function scheduleAudit(audit: SupportPassportModelAuditSink, record: SupportPassportModelAuditRecord): void {
  setImmediate(() => {
    void recordAuditSafely(audit, record);
  });
}

export class SupportPassportDraftService {
  private readonly cardService: SupportPassportCardService;
  private readonly modelAdapter: SupportPassportModelAdapter;
  private readonly resolveOwner: SupportPassportDraftServiceDependencies["resolveOwner"];
  private readonly audit: SupportPassportModelAuditSink;
  private readonly now: () => Date;

  constructor(dependencies: SupportPassportDraftServiceDependencies) {
    this.cardService = dependencies.cardService;
    this.modelAdapter = dependencies.modelAdapter;
    this.resolveOwner = dependencies.resolveOwner;
    this.audit = dependencies.audit;
    this.now = dependencies.now ?? (() => new Date());
  }

  async draftCards(input: {
    principal: string;
    sourceMemoryIds: string[];
    sourceMemoryRevisions: Array<{ memoryId: string; revision: string }>;
    consent: boolean;
    signal?: AbortSignal;
    onCommitted?: () => void;
  }): Promise<SupportPassportCard[]> {
    if (input.consent !== true) {
      throw new SupportPassportError("consent_required", "Drafting requires explicit consent.", 400);
    }
    const parsed = DraftServiceInputSchema.safeParse({
      principal: input.principal,
      sourceMemoryIds: input.sourceMemoryIds,
      sourceMemoryRevisions: input.sourceMemoryRevisions,
      consent: input.consent,
    });
    if (!parsed.success) throw new SupportPassportError("invalid_input", "The drafting request is invalid.", 400);
    const cancellationMessage = "The support guide draft was cancelled.";
    throwIfAborted(input.signal, cancellationMessage);
    const resolvedOwner = await raceAbort(this.resolveOwner(parsed.data.principal), input.signal, cancellationMessage);
    const owner = this.validateOwnerScope(resolvedOwner, parsed.data.principal);
    throwIfAborted(input.signal, cancellationMessage);
    const revisions = new Map(
      parsed.data.sourceMemoryRevisions.map((source) => [source.memoryId, source.revision] as const)
    );
    const selectedMemories: MemoryFile[] = [];
    const memories: Array<{ memoryId: string; content: string }> = [];
    for (const memoryId of parsed.data.sourceMemoryIds) {
      throwIfAborted(input.signal, cancellationMessage);
      const memory = await raceAbort(owner.storage.getMemoryById(memoryId), input.signal, cancellationMessage);
      throwIfAborted(input.signal, cancellationMessage);
      if (!memory || !isSupportPassportSourceEligible(memory)) {
        throw new SupportPassportError("invalid_input", "A selected memory is not available.", 400);
      }
      if (
        computeSupportPassportSourceRevision(memory.content, memory.frontmatter.structuredAttributes) !==
        revisions.get(memoryId)
      ) {
        throw new SupportPassportError("revision_conflict", "A selected memory changed after it was reviewed.", 409);
      }
      selectedMemories.push(memory);
      memories.push({ memoryId, content: supportPassportSourceContent(memory) });
    }
    await this.revalidateSources(owner.storage, selectedMemories, input.signal, cancellationMessage);
    const startedAt = Date.now();
    let modelResult: Awaited<ReturnType<SupportPassportModelAdapter["draftCards"]>>;
    try {
      modelResult = await this.modelAdapter.draftCards(
        {
          consent: true,
          memories,
        },
        input.signal
      );
    } catch (error) {
      scheduleAudit(this.audit, {
        schemaVersion: 1,
        operation: "draft_cards",
        actorHash: hashSupportPassportAuditValues("owner", [owner.principal]),
        subjectIdsHash: hashSupportPassportAuditValues("source-memory-ids", parsed.data.sourceMemoryIds),
        outputSchemaVersion: 1,
        outcome: "error",
        occurredAt: this.now().toISOString(),
        ...modelFailureAuditFields(error, input.signal, Math.max(0, Date.now() - startedAt)),
      });
      throw error;
    }
    const auditBase = {
      schemaVersion: 1 as const,
      operation: "draft_cards" as const,
      actorHash: hashSupportPassportAuditValues("owner", [owner.principal]),
      subjectIdsHash: hashSupportPassportAuditValues("source-memory-ids", parsed.data.sourceMemoryIds),
      modelUsed: modelResult.modelUsed,
      route: modelResult.route,
      outputSchemaVersion: 1 as const,
      occurredAt: this.now().toISOString(),
      latencyMs: Math.floor(modelResult.latencyMs),
      usage: modelResult.usage,
    };
    try {
      const cards = await this.cardService.createGeneratedDraftsForOwner({
        authenticatedPrincipal: owner.principal,
        owner,
        cards: modelResult.cards,
        signal: input.signal,
        ...(input.onCommitted ? { onCommitted: input.onCommitted } : {}),
        commitWithValidatedSources: async (commit) => {
          throwIfAborted(input.signal, cancellationMessage);
          const committed = await owner.storage.withMemorySnapshotsIfUnchanged(
            selectedMemories,
            async (memories) => {
              if (memories.some((memory) => !isSupportPassportSourceEligible(memory))) return false;
              throwIfAborted(input.signal, cancellationMessage);
              await commit();
              return true;
            },
          );
          if (committed !== true) {
            throw new SupportPassportError("invalid_input", "A selected memory is not available.", 400);
          }
        },
      });
      scheduleAudit(this.audit, { ...auditBase, outcome: "success" });
      return cards;
    } catch (error) {
      scheduleAudit(this.audit, {
        ...auditBase,
        outcome: "error",
        errorClass:
          error instanceof SupportPassportError
            ? error.code
            : input.signal?.aborted
              ? "aborted"
              : operationErrorClass(error),
      });
      throw error;
    }
  }

  private async revalidateSources(
    storage: SupportPassportOwnerScope["storage"],
    expected: readonly MemoryFile[],
    signal: AbortSignal | undefined,
    cancellationMessage: string
  ): Promise<void> {
    throwIfAborted(signal, cancellationMessage);
    const memories = await raceAbort(storage.readMemorySnapshotsIfUnchanged(expected), signal, cancellationMessage);
    throwIfAborted(signal, cancellationMessage);
    if (!memories || memories.some((memory) => !isSupportPassportSourceEligible(memory))) {
      throw new SupportPassportError("invalid_input", "A selected memory is not available.", 400);
    }
  }

  private validateOwnerScope(owner: SupportPassportOwnerScope, principal: string): SupportPassportOwnerScope {
    const requestedPrincipal = SupportPassportListCardsInputSchema.safeParse({ principal });
    const ownerPrincipal = SupportPassportListCardsInputSchema.safeParse({ principal: owner.principal });
    const namespace = SupportPassportNamespaceSchema.safeParse(owner.namespace);
    if (
      !requestedPrincipal.success ||
      !ownerPrincipal.success ||
      !namespace.success ||
      ownerPrincipal.data.principal !== requestedPrincipal.data.principal
    ) {
      throw new SupportPassportError("card_data_invalid", "The support passport owner scope is invalid.", 500);
    }
    return { ...owner, principal: ownerPrincipal.data.principal, namespace: namespace.data };
  }
}

export class SupportPassportQuestionService {
  private readonly grantService: SupportPassportGrantService;
  private readonly modelAdapter: SupportPassportModelAdapter;
  private readonly audit: SupportPassportModelAuditSink;
  private readonly now: () => Date;

  constructor(dependencies: SupportPassportQuestionServiceDependencies) {
    this.grantService = dependencies.grantService;
    this.modelAdapter = dependencies.modelAdapter;
    this.audit = dependencies.audit;
    this.now = dependencies.now ?? (() => new Date());
  }

  async askGrant(input: {
    grantId: string;
    secret: string;
    question: string;
    signal?: AbortSignal;
  }): Promise<SupportPassportAnswerOutput> {
    const cancellationMessage = "The helper question was cancelled.";
    throwIfAborted(input.signal, cancellationMessage);
    const guide = await raceAbort(this.grantService.readGrant(input), input.signal, cancellationMessage);
    throwIfAborted(input.signal, cancellationMessage);
    const startedAt = Date.now();
    let modelResult: Awaited<ReturnType<SupportPassportModelAdapter["answerQuestion"]>>;
    try {
      modelResult = await this.modelAdapter.answerQuestion({ guide, question: input.question }, input.signal);
    } catch (error) {
      scheduleAudit(this.audit, {
        schemaVersion: 1,
        operation: "answer_question",
        actorHash: hashSupportPassportAuditValues("helper-grant", [guide.grantId]),
        subjectIdsHash: hashSupportPassportAuditValues(
          "shared-card-ids",
          guide.cards.map((card) => card.cardId)
        ),
        outputSchemaVersion: 1,
        outcome: "error",
        occurredAt: this.now().toISOString(),
        ...modelFailureAuditFields(error, input.signal, Math.max(0, Date.now() - startedAt)),
      });
      throw error;
    }
    const auditBase = {
      schemaVersion: 1,
      operation: "answer_question" as const,
      actorHash: hashSupportPassportAuditValues("helper-grant", [guide.grantId]),
      subjectIdsHash: hashSupportPassportAuditValues(
        "shared-card-ids",
        guide.cards.map((card) => card.cardId)
      ),
      modelUsed: modelResult.modelUsed,
      route: modelResult.route,
      outputSchemaVersion: 1 as const,
      occurredAt: this.now().toISOString(),
      latencyMs: Math.floor(modelResult.latencyMs),
      usage: modelResult.usage,
    };
    try {
      throwIfAborted(input.signal, cancellationMessage);
      await raceAbort(this.grantService.readGrant(input), input.signal, cancellationMessage);
      throwIfAborted(input.signal, cancellationMessage);
      const answer = {
        answer: modelResult.answer,
        citedCardIds: modelResult.citedCardIds,
        coverage: modelResult.coverage,
      };
      scheduleAudit(this.audit, { ...auditBase, schemaVersion: 1, outcome: "success" });
      return answer;
    } catch (error) {
      scheduleAudit(this.audit, {
        ...auditBase,
        schemaVersion: 1,
        outcome: "error",
        errorClass: input.signal?.aborted ? "aborted" : operationErrorClass(error),
      });
      throw error;
    }
  }
}

import type { OperationName } from "./access-boundary.js";
import { runLcmCompactionFlushHttp, runLcmCompactionRecordHttp } from "./access-http-lcm-compaction.js";
import type { LcmCompactionFlushRequest, LcmCompactionRecordRequest } from "./access-schema.js";
import type { EngramAccessExtractionForceFlushRequest, EngramAccessService } from "./access-service.js";

export interface LifecycleFlushHttpDeps {
  service: Pick<EngramAccessService, "extractionForceFlush" | "lcmCompactionFlush" | "lcmCompactionRecord">;
  enforceTokenOp(op: OperationName): void;
  defaultNamespace?: string;
  readValidatedBody(schemaName: "lcmCompactionFlush"): Promise<LcmCompactionFlushRequest>;
  readValidatedBody(schemaName: "lcmCompactionRecord"): Promise<LcmCompactionRecordRequest>;
  readValidatedBody(schemaName: "extractionForceFlush"): Promise<EngramAccessExtractionForceFlushRequest>;
  ensureWriteRateLimitAvailable(): void;
  resolveNamespace(namespace: string | undefined): string | undefined;
  resolveRequestPrincipal(): string | undefined;
  recordWriteRateLimitHit(): void;
  respondJson(payload: unknown): void;
}

export async function maybeHandleLifecycleFlush(
  deps: LifecycleFlushHttpDeps,
  method: string | undefined,
  pathname: string,
  abortSignal: AbortSignal
): Promise<boolean> {
  if (method !== "POST") return false;
  if (pathname === "/engram/v1/lcm/compaction/flush" || pathname === "/remnic/v1/lcm/compaction/flush") {
    deps.enforceTokenOp("lcm_compaction_flush");
    const body = await deps.readValidatedBody("lcmCompactionFlush");
    const response = await runLcmCompactionFlushHttp({
      body,
      service: deps.service,
      ensureWriteRateLimitAvailable: deps.ensureWriteRateLimitAvailable,
      recordWriteRateLimitHit: deps.recordWriteRateLimitHit,
      resolveNamespace: deps.resolveNamespace,
      defaultNamespace: deps.defaultNamespace,
      resolveRequestPrincipal: deps.resolveRequestPrincipal,
      abortSignal,
    });
    deps.respondJson(response);
    return true;
  }

  if (pathname === "/engram/v1/lcm/compaction/record" || pathname === "/remnic/v1/lcm/compaction/record") {
    deps.enforceTokenOp("lcm_compaction_record");
    const body = await deps.readValidatedBody("lcmCompactionRecord");
    const response = await runLcmCompactionRecordHttp({
      body,
      service: deps.service,
      ensureWriteRateLimitAvailable: deps.ensureWriteRateLimitAvailable,
      recordWriteRateLimitHit: deps.recordWriteRateLimitHit,
      resolveNamespace: deps.resolveNamespace,
      resolveRequestPrincipal: deps.resolveRequestPrincipal,
    });
    deps.respondJson(response);
    return true;
  }

  if (pathname === "/engram/v1/extraction/flush" || pathname === "/remnic/v1/extraction/flush") {
    deps.enforceTokenOp("extraction_force_flush");
    const body = await deps.readValidatedBody("extractionForceFlush");
    deps.ensureWriteRateLimitAvailable();
    let writeRateLimitRecorded = false;
    const recordCommittedWrite = (): void => {
      if (writeRateLimitRecorded) return;
      writeRateLimitRecorded = true;
      deps.recordWriteRateLimitHit();
    };
    const response = await deps.service.extractionForceFlush({
      ...body,
      namespace: deps.resolveNamespace(body.namespace),
      authenticatedPrincipal: deps.resolveRequestPrincipal(),
      abortSignal,
      onCommitted: recordCommittedWrite,
    });
    recordCommittedWrite();
    deps.respondJson(response);
    return true;
  }

  return false;
}

import type { IncomingMessage, ServerResponse } from "node:http";

/**
 * GET /mcp SSE half of the MCP streamable-HTTP transport (issue #2718).
 *
 * Clients such as the Grok Build TUI open a GET stream after `initialize`;
 * that stream is reserved for server-initiated messages and this server has
 * none to push, so it carries only SSE comment heartbeats — never a
 * JSON-RPC payload. Header/heartbeat/cleanup shape mirrors
 * `handleGraphEventsSSE` in access-http.ts (25 s heartbeat, cleanup
 * registered in the server's `sseCleanupFns` set so `stop()` releases the
 * interval even if the client never disconnects), but it subscribes to no
 * event bus, resolves no namespace, and ignores `Last-Event-ID`.
 *
 * Lives in a sibling module rather than access-http.ts so the handler does
 * not push that file past its fileSizeGrandfather ceiling (issue #1995).
 */
export function handleMcpGetSse(
  req: IncomingMessage,
  res: ServerResponse,
  sseCleanupFns: Set<() => void>,
): void {
  res.writeHead(200, {
    "content-type": "text/event-stream; charset=utf-8",
    "cache-control": "no-cache, no-store, must-revalidate",
    "connection": "keep-alive",
    "x-accel-buffering": "no",
    "transfer-encoding": "chunked",
  });

  // Comment-only frames: `: ping\n\n` is a valid SSE comment that carries no
  // data and cannot be mistaken for a JSON-RPC message. One is written
  // immediately so clients and proxies see the stream is live without
  // waiting for the first 25 s tick.
  const heartbeat = (): void => {
    try { res.write(": ping\n\n"); } catch { /* client gone; cleanup fires via "close" */ }
  };
  heartbeat();
  const heartbeatInterval = setInterval(heartbeat, 25_000);

  const cleanup = (): void => {
    clearInterval(heartbeatInterval);
    sseCleanupFns.delete(cleanup);
    try { res.end(); } catch { /* ignore */ }
  };
  sseCleanupFns.add(cleanup);

  req.once("close", cleanup);
  req.once("error", cleanup);
}

import {
  getOperation,
  operationRequiresAuthorizedNamespace,
  operationUsesPrincipalNamespace,
  OPERATION_NAMES,
  type OperationName,
} from "./access-boundary.js";
import { EngramAccessInputError } from "./access-errors.js";
import {
  assertOperationAuthorizationAllowed,
  type TokenCapabilities,
} from "./access-token-capabilities.js";

const UNRESOLVABLE_RESOURCE_OPERATIONS = new Set<OperationName>([
  "review_resolve",
  "contradiction_detail",
  "chat_message",
  "chat_events",
]);

const HELPER_ONLY_OPERATIONS = new Set<OperationName>([
  "support_passport_grant_read",
  "support_passport_grant_ask",
]);

export interface AuthorizationProbeResponse {
  readonly authorized: true;
  readonly operations: readonly OperationName[];
}

/**
 * Verify that the presenting token may call every requested operation without
 * invoking any operation handler.
 */
export function probeOperationAuthorization(
  capabilities: TokenCapabilities | undefined | null,
  requestedOperations: readonly string[],
): AuthorizationProbeResponse {
  const operations: OperationName[] = [];
  for (const candidate of requestedOperations) {
    if (
      !OPERATION_NAMES.includes(candidate as OperationName) ||
      HELPER_ONLY_OPERATIONS.has(candidate as OperationName)
    ) {
      throw new EngramAccessInputError(`unsupported operation: ${candidate}`);
    }
    const operation = candidate as OperationName;
    if (!operations.includes(operation)) operations.push(operation);
  }

  if (operations.length === 0) {
    throw new EngramAccessInputError("at least one operation is required");
  }

  for (const operation of operations) {
    const boundOperation = getOperation(operation);
    if (!boundOperation) {
      throw new Error(
        `authorization probe operation is not registered: ${operation}`,
      );
    }
    assertOperationAuthorizationAllowed(capabilities, boundOperation.spec);
  }

  return { authorized: true, operations };
}

/**
 * Resolve every namespace an authorization probe can verify from the request.
 * Resource-scoped routes resolve their stored target only after a resource id
 * is supplied, so probes validate only request-resolvable namespaces.
 */
export function authorizationProbeNamespaces(
  operations: readonly OperationName[],
  requestedNamespace: string | undefined,
): readonly (string | undefined)[] {
  const namespaceOperations = operations.filter(
    (operation) =>
      operationRequiresAuthorizedNamespace(operation) &&
      !UNRESOLVABLE_RESOURCE_OPERATIONS.has(operation),
  );
  return namespaceOperations.length > 0 ? [requestedNamespace] : [];
}

/** Whether a probe must resolve the authenticated principal's owner namespace. */
export function authorizationProbeRequiresPrincipalNamespace(
  operations: readonly OperationName[],
): boolean {
  return operations.some(operationUsesPrincipalNamespace);
}

export type { AdapterContext, EngramAdapter, ResolvedIdentity } from "./types.js";
export { ClaudeCodeAdapter } from "./claude-code.js";
export { CodexAdapter } from "./codex.js";
export { GrokAdapter } from "./grok.js";
export { OpenCodeAdapter } from "./opencode.js";
export { ReplitAdapter } from "./replit.js";
export { HermesAdapter } from "./hermes.js";
export { AdapterRegistry } from "./registry.js";

/**
 * Deep-recall HTTP glue (issue #2332) — route body lives here so
 * access-http.ts stays at its structural ceiling (same seam as
 * meetings/http-glue.ts and location/http-glue.ts).
 *
 * Input errors map to 400; everything else rethrows so backend faults keep
 * flowing to the global 500 handler. `deepRecall.enabled` gating lives in
 * EngramAccessService — this module only translates transport shape.
 */

import type { IncomingMessage, ServerResponse } from "node:http";
import { deepRecallRequestSchema } from "./access-schema.js";
import { EngramAccessInputError } from "./access-errors.js";
import type { EngramAccessService } from "./access-service.js";
import { parseDeepRecallMaxSteps } from "./deep-recall-config.js";

type RespondJson = (res: ServerResponse, status: number, payload: unknown) => void;
type ReadJsonBody = (req: IncomingMessage) => Promise<unknown>;

export async function respondDeepRecall(
  req: IncomingMessage,
  res: ServerResponse,
  respondJson: RespondJson,
  readJsonBody: ReadJsonBody,
  service: EngramAccessService,
  /**
   * Resolve the caller scope for a body-supplied namespace/sessionKey. The
   * body `namespace` is user-controlled, so it MUST flow through the SAME
   * effective-namespace allow-list gate as the query-string value (issue
   * #1850 finding 2 / #2332 review): a scoped bearer that passes an allowed
   * `?namespace=` while setting a different `namespace` in the body would
   * otherwise read another tenant. access-http supplies the gate and applies
   * the query-string fallback, so this module never selects a namespace of
   * its own. Throws 403 when the effective namespace is not permitted.
   *
   * `authenticatedPrincipal` is the identity the transport authenticated, and
   * it MUST reach the service: authorization and the audit trail derive from
   * the presenting principal, never from the client-supplied `sessionKey`.
   * Dropping it let a crafted key matching another principal rule read that
   * principal's namespaces, and made a legitimate namespace-enabled request
   * with no session key fail as unauthenticated.
   */
  scopeFor: (
    bodyNamespace?: string,
    bodySessionKey?: string,
  ) => { namespace?: string; sessionKey?: string; authenticatedPrincipal?: string },
  /** Transport cancellation (issue #2915): aborts seed search, graph reads, policy calls. */
  abortSignal?: AbortSignal,
): Promise<void> {
  const parsed = deepRecallRequestSchema.safeParse(await readJsonBody(req));
  if (!parsed.success) {
    respondJson(
      res,
      400,
      { error: "invalid_request", detail: parsed.error.issues.map((i) => `${i.path.join(".")}: ${i.message}`).join("; ") },
    );
    return;
  }
  let maxSteps: number | undefined;
  try {
    maxSteps = parseDeepRecallMaxSteps(parsed.data.maxSteps);
  } catch (err) {
    throw new EngramAccessInputError(err instanceof Error ? err.message : String(err));
  }
  const scope = scopeFor(parsed.data.namespace, parsed.data.sessionKey);
  const result = await service.deepRecall({
    query: parsed.data.query,
    ...(maxSteps !== undefined ? { maxSteps } : {}),
    namespace: scope.namespace,
    sessionKey: scope.sessionKey,
    authenticatedPrincipal: scope.authenticatedPrincipal,
    ...(abortSignal ? { abortSignal } : {}),
  });
  respondJson(res, 200, result);
}

/**
 * Meetings HTTP route glue (issue #1900) — the route bodies extracted from
 * access-http.ts so the surface file stays under its structural ceiling. The
 * thin inline hooks in access-http.ts keep the pathname/method match + the
 * `enforceTokenOp("meetings_*")` boundary-dispatch marker (required by the
 * surface-catalog fitness test) and delegate the body here.
 *
 * `MeetingsInputError` (invalid dates/ids) maps to a 400; everything else
 * rethrows so backend faults keep flowing to the global 500 handler. Behaviour,
 * validation, and `meetings.enabled` gating live in MeetingsService — these
 * functions only translate transport shape.
 */

import type { IncomingMessage, ServerResponse } from "node:http";
import { EngramAccessInputError, type WearablesMeetingsScope } from "../access-service.js";
import { MeetingsInputError } from "./errors.js";

type RespondJson = (res: ServerResponse, status: number, payload: unknown) => void;
type ReadJsonBody = (req: IncomingMessage) => Promise<unknown>;

/** Minimal meetings surface the HTTP glue drives (satisfied by EngramAccessService). */
export interface MeetingsHttpService {
  meetingsList(date?: string, scope?: WearablesMeetingsScope): Promise<unknown>;
  meetingsGet(id: string, scope?: WearablesMeetingsScope): Promise<unknown>;
  meetingsBuild(date: string, scope?: WearablesMeetingsScope): Promise<unknown>;
}

function respondMeetingsError(respondJson: RespondJson, res: ServerResponse, err: unknown): boolean {
  if (err instanceof MeetingsInputError) {
    respondJson(res, 400, { error: "invalid_request", code: "invalid_request", message: err.message });
    return true;
  }
  return false;
}

/**
 * Decode a meeting `:id` URL path segment, mapping malformed percent-encoded
 * input (e.g. `%E0%A4%A`) to a 400 `MeetingsInputError` rather than letting the
 * `URIError` bubble up to the global 500 handler — mirrors the access-http
 * `decode*Segment` helpers.
 */
function decodeMeetingIdSegment(raw: string): string {
  try {
    return decodeURIComponent(raw);
  } catch {
    throw new MeetingsInputError("meeting id path segment is not valid percent-encoded input");
  }
}

/**
 * Per-principal write-quota hooks the build route shares with every other
 * mutating REST route: `enforceQuota` throws a 429 when the principal is over
 * budget; `recordHit` accounts the successful write. Injected from access-http
 * so the quota state stays owned by the server (issue #1937).
 */
export interface MeetingsWriteQuotaHooks {
  enforceQuota(): void;
  recordHit(): void;
}

export async function respondMeetingsList(
  res: ServerResponse,
  respondJson: RespondJson,
  service: MeetingsHttpService,
  date: string | undefined,
  scope?: WearablesMeetingsScope,
): Promise<void> {
  try {
    respondJson(res, 200, await service.meetingsList(date, scope));
  } catch (err) {
    if (respondMeetingsError(respondJson, res, err)) return;
    throw err;
  }
}

export async function respondMeetingsGet(
  res: ServerResponse,
  respondJson: RespondJson,
  service: MeetingsHttpService,
  rawId: string,
  scope?: WearablesMeetingsScope,
): Promise<void> {
  try {
    respondJson(res, 200, await service.meetingsGet(decodeMeetingIdSegment(rawId), scope));
  } catch (err) {
    if (respondMeetingsError(respondJson, res, err)) return;
    throw err;
  }
}

export async function respondMeetingsBuild(
  req: IncomingMessage,
  res: ServerResponse,
  respondJson: RespondJson,
  readJsonBody: ReadJsonBody,
  service: MeetingsHttpService,
  quota: MeetingsWriteQuotaHooks,
  scopeFor?: (bodyNamespace?: string, bodySessionKey?: string) => WearablesMeetingsScope,
): Promise<void> {
  const body = (await readJsonBody(req)) as Record<string, unknown>;
  const raw = body.date;
  if (raw !== undefined && raw !== null && raw !== "" && typeof raw !== "string") {
    throw new EngramAccessInputError(`date must be a string (got ${JSON.stringify(raw)})`);
  }
  const date = raw === undefined || raw === null || raw === "" ? undefined : raw;
  if (date === undefined) {
    throw new EngramAccessInputError("date is required (YYYY-MM-DD)");
  }
  // Build persists/deletes records, writes memories, and reindexes — a mutating
  // route, so it carries the same per-principal write quota as every other
  // write (capsule import/export, admin promote). Enforce before the write,
  // account the hit after it succeeds (issue #1937).
  quota.enforceQuota();
  const scope = scopeFor?.(
    typeof body.namespace === "string" ? body.namespace : undefined,
    typeof body.sessionKey === "string" ? body.sessionKey : undefined,
  );
  try {
    const result = await service.meetingsBuild(date, scope);
    quota.recordHit();
    respondJson(res, 200, result);
  } catch (err) {
    if (respondMeetingsError(respondJson, res, err)) return;
    throw err;
  }
}

import { createHash } from "node:crypto";
import { computeLegacyContentHash, normalizeLegacyContent } from "../content-hash.js";
import { inferMemoryStatus } from "../memory-lifecycle-ledger-utils.js";
import { DEFAULT_CITATION_FORMAT, stripCitationForTemplate } from "../source-attribution.js";
import { ContentHashIndex, type ContentHashPathEntry } from "../storage/content-hash-index.js";
import { storedContentIdentityCandidates } from "../structured-attributes.js";
import type { MemoryFrontmatter, MemoryStatus } from "../types.js";
import { RECALL_FALLBACK_DIRS } from "../utils/category-dir.js";
import {
  type ReconcileFileState,
  type ReconcilePlan,
  type ReconcilePlanEntry,
  type ReconcileSemanticAgreement,
  type ReconcileSemanticChange,
  compareReconcilePlanEntries,
  semanticAgreementKey,
  summarizeReconcilePlan,
} from "./plan.js";

export const RECONCILE_MANIFEST_FORMAT = "remnic-reconcile-manifest";
export const RECONCILE_MANIFEST_SCHEMA_VERSION = 1;
export const CONTENT_HASH_NORMALIZER_VERSION = 4;
/**
 * Version of the identity-resolution LOGIC (alias recovery, candidate
 * ordering), independent of the content normalizer: a cached manifest entry
 * written before an identity-resolution change carries an older value and is
 * reparsed even when its normalizerVersion still matches (issue #2367
 * review round 2). Bump when parsedMemoryIdentity's output shape or
 * semantics change.
 */
export const IDENTITY_RESOLUTION_VERSION = 2;

/**
 * Identity of the manifest-affecting implementation this peer builds
 * STREAMED manifests with. Advertised via offline-sync capabilities so the
 * client can key peer-side plan caches on it: a peer that upgrades its
 * normalization logic or citation template without rewriting stored files
 * keeps the same file hashes, and only this revision invalidates the stale
 * cached identities (#2803 / #2956 review).
 */
export function peerManifestRevision(citationTemplate?: string): string {
  return `schema=${RECONCILE_MANIFEST_SCHEMA_VERSION};normalizer=${CONTENT_HASH_NORMALIZER_VERSION};identity=${IDENTITY_RESOLUTION_VERSION};citation=${citationTemplateFingerprint(citationTemplate)}`;
}

export interface ReconcileMemoryIdentity {
  id: string;
  category: string;
  contentHash: string;
  /**
   * Recovered current-normalizer identities for a record whose persisted hash
   * is ambiguous under the legacy normalizer (issue #2367). The persisted
   * hash stays primary; these participate in duplicate bucketing so a
   * replica carrying the current form of the same fact still collapses.
   */
  contentHashAliases?: readonly string[];
  /** See IDENTITY_RESOLUTION_VERSION; absent on pre-versioning cache entries. */
  normalizerVersion?: number;
  identityResolutionVersion?: number;
  status: MemoryStatus;
}

export interface ReconcileManifestFile extends ReconcileFileState {
  memory?: ReconcileMemoryIdentity;
  /** Present on sha-only (negative) entries so an upgrade re-parses them. */
  normalizerVersion?: number;
  identityResolutionVersion?: number;
}

type ActiveFactManifestFile = ReconcileManifestFile & { memory: ReconcileMemoryIdentity };

export interface ReconcileManifest {
  format: typeof RECONCILE_MANIFEST_FORMAT;
  schemaVersion: typeof RECONCILE_MANIFEST_SCHEMA_VERSION;
  files: ReconcileManifestFile[];
}

export type ReconcileMemoryParser = (raw: string) => { frontmatter: MemoryFrontmatter; content: string } | null;

export interface BuildReconcileManifestOptions {
  files: Iterable<ReconcileFileState>;
  readFile: (file: ReconcileFileState) => Promise<Buffer | string | null>;
  parseMemory: ReconcileMemoryParser;
  cachedFiles?: Iterable<ReconcileManifestFile>;
  citationTemplate?: string;
  /** Cancellation (#2954): checked between read batches so an aborted run
   * stops scheduling new file reads instead of walking the whole corpus. */
  signal?: AbortSignal;
}

const SHA256_PATTERN = /^[a-f0-9]{64}$/i;
const MEMORY_DIRS = new Set(RECALL_FALLBACK_DIRS);

function isMemoryPath(filePath: string): boolean {
  if (!filePath.endsWith(".md")) return false;
  const segments = filePath.split("/");
  let index = 0;
  if (segments[index] === "cold" || segments[index] === "archive") index += 1;
  return MEMORY_DIRS.has(segments[index] ?? "");
}

function parsedMemoryIdentity(
  filePath: string,
  raw: Buffer | string,
  parseMemory: ReconcileMemoryParser,
  citationTemplate: string
): ReconcileMemoryIdentity | undefined {
  if (!isMemoryPath(filePath)) return undefined;
  const parsed = parseMemory(Buffer.isBuffer(raw) ? raw.toString("utf8") : raw);
  if (!parsed?.frontmatter.id) return undefined;

  const storedHash =
    parsed.frontmatter.contentHash && SHA256_PATTERN.test(parsed.frontmatter.contentHash)
      ? parsed.frontmatter.contentHash.toLowerCase()
      : undefined;
  const candidates = storedContentIdentityCandidates(parsed.content, (content) =>
    stripCitationForTemplate(content, citationTemplate)
  );
  const bodyHash = ContentHashIndex.computeHash(candidates[0] ?? "");
  const currentMatch = candidates.find((content) => ContentHashIndex.computeHash(content) === storedHash);
  const legacyMatch = [...candidates].reverse().find((content) => computeLegacyContentHash(content) === storedHash);
  let contentHash: string;
  let contentHashAliases: string[] | undefined;
  if (currentMatch) {
    contentHash = ContentHashIndex.computeHash(currentMatch);
  } else if (legacyMatch && normalizeLegacyContent(legacyMatch).length > 0) {
    // A non-empty legacy equality is ambiguous (issue #2367): the persisted
    // hash may be an explicit contentHashSource identity that merely collides
    // with the body's ASCII skeleton under the lossy legacy normalizer, and
    // nothing in the record proves which it is. Keep the persisted hash as
    // the primary identity and expose the recovered current identity as an
    // alias so replicas carrying either form still collapse.
    contentHash = storedHash ?? bodyHash;
    const recovered = ContentHashIndex.computeHash(legacyMatch);
    if (recovered !== contentHash) contentHashAliases = [recovered];
  } else {
    // An EMPTY legacy skeleton identifies nothing (every non-ASCII body maps
    // to it), so preserving it would collapse unrelated records. Recovering
    // the current identity here is repair, not replacement.
    contentHash = legacyMatch ? ContentHashIndex.computeHash(legacyMatch) : (storedHash ?? bodyHash);
  }

  return {
    id: parsed.frontmatter.id,
    category: parsed.frontmatter.category,
    contentHash,
    ...(contentHashAliases ? { contentHashAliases } : {}),
    normalizerVersion: CONTENT_HASH_NORMALIZER_VERSION,
    identityResolutionVersion: IDENTITY_RESOLUTION_VERSION,
    status: inferMemoryStatus(parsed.frontmatter, filePath),
  };
}

/**
 * Stable fingerprint of the citation template that `parsedMemoryIdentity` uses
 * to strip inline attribution before hashing. A persisted identity cache is
 * only reusable while this matches: identical file content under a different
 * template yields a different `contentHash`, which would silently change
 * duplicate and conflict decisions on a warm plan.
 */
export function citationTemplateFingerprint(citationTemplate?: string): string {
  return createHash("sha256")
    .update(citationTemplate ?? DEFAULT_CITATION_FORMAT)
    .digest("hex")
    .slice(0, 16);
}

/**
 * Structural guard for identities read back from an on-disk cache. A cache file
 * is untrusted JSON: without this an entry carrying `memory: null` survives the
 * loader's cast and then throws when the hit path dereferences
 * `memory.normalizerVersion`, aborting a manifest build that should instead
 * fall back to a cold parse.
 */
export function isReconcileMemoryIdentity(value: unknown): value is ReconcileMemoryIdentity {
  if (!value || typeof value !== "object" || Array.isArray(value)) return false;
  const memory = value as Record<string, unknown>;
  if (typeof memory.id !== "string") return false;
  if (typeof memory.category !== "string") return false;
  if (typeof memory.contentHash !== "string" || !SHA256_PATTERN.test(memory.contentHash)) return false;
  if (typeof memory.status !== "string") return false;
  if (memory.normalizerVersion !== undefined && typeof memory.normalizerVersion !== "number") return false;
  if (memory.identityResolutionVersion !== undefined && typeof memory.identityResolutionVersion !== "number") {
    return false;
  }
  if (
    memory.contentHashAliases !== undefined &&
    (!Array.isArray(memory.contentHashAliases) ||
      memory.contentHashAliases.some((alias) => typeof alias !== "string" || !SHA256_PATTERN.test(alias)))
  ) {
    return false;
  }
  return true;
}

/** A cache hit is valid only when the entry was built by the current parser.
 * Positive hits carry versions on `memory`; sha-only negatives stamp the same
 * versions on the entry itself. Unversioned negatives are pre-upgrade leftovers
 * and must miss so a newer parser can recognize an identity it previously skipped. */
export function isCachedIdentityReusable(cached: ReconcileManifestFile): boolean {
  if (cached.memory !== undefined) {
    return (
      cached.memory.normalizerVersion === CONTENT_HASH_NORMALIZER_VERSION &&
      cached.memory.identityResolutionVersion === IDENTITY_RESOLUTION_VERSION
    );
  }
  return (
    cached.normalizerVersion === CONTENT_HASH_NORMALIZER_VERSION &&
    cached.identityResolutionVersion === IDENTITY_RESOLUTION_VERSION
  );
}

export async function buildReconcileManifestFile(
  file: ReconcileFileState,
  readFile: (file: ReconcileFileState) => Promise<Buffer | string | null>,
  parseMemory: ReconcileMemoryParser,
  citationTemplate = DEFAULT_CITATION_FORMAT
): Promise<ReconcileManifestFile> {
  let raw: Buffer | string | null = null;
  let readFailed = false;
  if (isMemoryPath(file.path)) {
    try {
      raw = await readFile(file);
    } catch {
      readFailed = true;
      raw = null;
    }
  }
  if (raw !== null && createHash("sha256").update(raw).digest("hex") !== file.sha256.toLowerCase()) {
    raw = null;
  }
  const memory = raw === null ? undefined : parsedMemoryIdentity(file.path, raw, parseMemory, citationTemplate);
  // A thrown read is not a negative identity. Stamping versions here would
  // make the next warm cycle treat the failure as "this file has no id".
  if (readFailed) return { ...file };
  return {
    ...file,
    ...(memory
      ? { memory }
      : {
          normalizerVersion: CONTENT_HASH_NORMALIZER_VERSION,
          identityResolutionVersion: IDENTITY_RESOLUTION_VERSION,
        }),
  };
}

/** Read-batch size for manifest builds. Uncached files are independent (a
 * per-file read + sha256 + frontmatter parse); processing them in bounded
 * batches amortizes the per-file promise/async-hook overhead that dominates
 * boot-scale corpus builds (measured: ~66% of CPU in async_hooks._propagate +
 * GC at ~100k files) and overlaps IO waits, while the bound keeps memory flat.
 * Order is preserved: results land in input order regardless of completion
 * order, so the manifest output is byte-identical to the sequential form. */
const MANIFEST_BUILD_BATCH_SIZE = 50;

export async function buildReconcileManifest(options: BuildReconcileManifestOptions): Promise<ReconcileManifest> {
  const cachedByPath = new Map<string, ReconcileManifestFile>();
  for (const cached of options.cachedFiles ?? []) {
    cachedByPath.set(cached.path, cached);
  }

  const allFiles = [...options.files];
  // Every result — cache hit or rebuild — is stored at its own input index.
  // Pushing hits onto a dense array while rebuilds are assigned by index
  // silently drops entries whenever a miss precedes a hit: the rebuild lands
  // on the slot the hit already occupied.
  const files: ReconcileManifestFile[] = new Array(allFiles.length);
  // Cache hits stay on a synchronous fast path (no promise allocation, no
  // Promise.all — a fully-cached rebuild must not regress); only the uncached
  // entries ride the bounded batches.
  const uncached: Array<{ index: number; file: ReconcileFileState }> = [];
  for (let i = 0; i < allFiles.length; i += 1) {
    const file = allFiles[i]!;
    const cached = cachedByPath.get(file.path);
    if (
      cached !== undefined &&
      cached.sha256.toLowerCase() === file.sha256.toLowerCase() &&
      isCachedIdentityReusable(cached)
    ) {
      files[i] = {
        ...file,
        ...(cached.memory
          ? { memory: cached.memory }
          : {
              normalizerVersion: cached.normalizerVersion,
              identityResolutionVersion: cached.identityResolutionVersion,
            }),
      };
    } else {
      uncached.push({ index: i, file });
    }
  }
  for (let i = 0; i < uncached.length; i += MANIFEST_BUILD_BATCH_SIZE) {
    // Between batches, not within one: an abort mid-batch lets the in-flight
    // reads settle (their own fetch signal does the aborting) and stops the
    // NEXT batch from ever being scheduled.
    options.signal?.throwIfAborted();
    const batch = uncached.slice(i, i + MANIFEST_BUILD_BATCH_SIZE);
    const results = await Promise.all(
      batch.map(({ file }) =>
        buildReconcileManifestFile(file, options.readFile, options.parseMemory, options.citationTemplate)
      )
    );
    for (let j = 0; j < batch.length; j += 1) {
      files[batch[j]!.index] = results[j]!;
    }
  }
  files.sort((left, right) => (left.path < right.path ? -1 : left.path > right.path ? 1 : 0));
  return {
    format: RECONCILE_MANIFEST_FORMAT,
    schemaVersion: RECONCILE_MANIFEST_SCHEMA_VERSION,
    files,
  };
}

function activeFactByPath(manifest: ReconcileManifest | undefined): Map<string, ActiveFactManifestFile> {
  const result = new Map<string, ActiveFactManifestFile>();
  for (const file of manifest?.files ?? []) {
    if (file.memory?.category === "fact" && file.memory.status === "active") {
      result.set(file.path, file as ActiveFactManifestFile);
    }
  }
  return result;
}

function memoryIdentityHashes(memory: ReconcileMemoryIdentity): string[] {
  return [memory.contentHash, ...(memory.contentHashAliases ?? [])];
}

function contentHashRows(files: Iterable<ActiveFactManifestFile>, contentHash: string): ContentHashPathEntry[] {
  const rows: ContentHashPathEntry[] = [];
  for (const file of files) {
    rows.push({ path: file.path, contentHash });
  }
  return rows;
}

function classifySemanticChange(
  current: ReconcileSemanticAgreement,
  prior: ReconcileSemanticAgreement | undefined
): ReconcileSemanticChange {
  if (!prior) return "unchanged";
  const localChanged = current.local.sha256 !== prior.local.sha256;
  const peerChanged = current.peer.sha256 !== prior.peer.sha256;
  if (localChanged && peerChanged) return "both_modified";
  if (localChanged) return "local_changed";
  if (peerChanged) return "peer_changed";
  return "unchanged";
}

export function collapseActiveFactDuplicates(
  plan: ReconcilePlan,
  localManifests: ReadonlyMap<string, ReconcileManifest>,
  peerManifests: ReadonlyMap<string, ReconcileManifest>,
  priorSemanticAgreements?: ReadonlyMap<string, readonly ReconcileSemanticAgreement[]>
): ReconcilePlan {
  const entriesByNamespace = new Map<string, ReconcilePlanEntry[]>();
  for (const entry of plan.entries) {
    const entries = entriesByNamespace.get(entry.namespace) ?? [];
    entries.push({ ...entry });
    entriesByNamespace.set(entry.namespace, entries);
  }

  let changed = false;
  for (const namespace of new Set([...localManifests.keys(), ...peerManifests.keys()])) {
    const entries = entriesByNamespace.get(namespace) ?? [];
    const localManifest = localManifests.get(namespace);
    const peerManifest = peerManifests.get(namespace);
    const localByPath = activeFactByPath(localManifest);
    const peerByPath = activeFactByPath(peerManifest);
    const localFilesByPath = new Map((localManifest?.files ?? []).map((file) => [file.path, file]));
    const peerFilesByPath = new Map((peerManifest?.files ?? []).map((file) => [file.path, file]));
    const priorSemanticByPathPair = new Map(
      (priorSemanticAgreements?.get(namespace) ?? []).map((agreement) => [semanticAgreementKey(agreement), agreement])
    );
    const localByHash = new Map<string, ActiveFactManifestFile[]>();
    const peerByHash = new Map<string, ActiveFactManifestFile[]>();

    for (const file of localByPath.values()) {
      for (const hash of memoryIdentityHashes(file.memory)) {
        const bucket = localByHash.get(hash) ?? [];
        bucket.push(file);
        localByHash.set(hash, bucket);
      }
    }
    for (const file of peerByPath.values()) {
      for (const hash of memoryIdentityHashes(file.memory)) {
        const bucket = peerByHash.get(hash) ?? [];
        bucket.push(file);
        peerByHash.set(hash, bucket);
      }
    }

    const removed = new Set<ReconcilePlanEntry>();
    const replacements: ReconcilePlanEntry[] = [];
    const processedPathPairs = new Set<string>();
    for (const hash of new Set([...localByHash.keys(), ...peerByHash.keys()])) {
      const localCandidates = (localByHash.get(hash) ?? []).filter((file) => {
        const opposite = peerFilesByPath.get(file.path);
        const activeOpposite = peerByPath.get(file.path);
        return (
          opposite === undefined ||
          (activeOpposite !== undefined && memoryIdentityHashes(activeOpposite.memory).includes(hash))
        );
      });
      const peerCandidates = (peerByHash.get(hash) ?? []).filter((file) => {
        const opposite = localFilesByPath.get(file.path);
        const activeOpposite = localByPath.get(file.path);
        return (
          opposite === undefined ||
          (activeOpposite !== undefined && memoryIdentityHashes(activeOpposite.memory).includes(hash))
        );
      });
      const localPath = ContentHashIndex.resolvePathByHash(hash, contentHashRows(localCandidates, hash));
      const peerPath = ContentHashIndex.resolvePathByHash(hash, contentHashRows(peerCandidates, hash));

      if (localPath && peerPath && localPath !== peerPath) {
        const pathPair = `${localPath}\0${peerPath}`;
        if (processedPathPairs.has(pathPair)) continue;
        processedPathPairs.add(pathPair);
        const localFile = localByPath.get(localPath);
        const peerFile = peerByPath.get(peerPath);
        if (!localFile || !peerFile) continue;
        const duplicatePaths = new Set([
          ...localCandidates.map((file) => file.path),
          ...peerCandidates.map((file) => file.path),
        ]);
        const authoritativeSamePathEntries = new Set(
          entries.filter(
            (entry) =>
              duplicatePaths.has(entry.path) &&
              localFilesByPath.has(entry.path) &&
              peerFilesByPath.has(entry.path) &&
              entry.action !== "identical"
          )
        );
        if (authoritativeSamePathEntries.size > 0) {
          for (const entry of entries) {
            if (
              duplicatePaths.has(entry.path) &&
              !authoritativeSamePathEntries.has(entry) &&
              (entry.action === "pull" || entry.action === "push" || entry.action === "identical")
            ) {
              removed.add(entry);
              changed = true;
            }
          }
          continue;
        }
        const unsafeEntry = entries.some(
          (entry) => duplicatePaths.has(entry.path) && (entry.action === "suppress" || entry.action === "conflict")
        );
        if (unsafeEntry) continue;
        for (const entry of entries) {
          if (
            duplicatePaths.has(entry.path) &&
            (entry.action === "pull" || entry.action === "push" || entry.action === "identical")
          ) {
            removed.add(entry);
          }
        }
        const semanticAgreement: ReconcileSemanticAgreement = {
          local: { path: localPath, sha256: localFile.sha256 },
          peer: { path: peerPath, sha256: peerFile.sha256 },
        };
        replacements.push({
          path: localPath < peerPath ? localPath : peerPath,
          namespace,
          action: "identical",
          reason: "semantic_duplicate",
          semanticAgreement,
          semanticChange: classifySemanticChange(
            semanticAgreement,
            priorSemanticByPathPair.get(semanticAgreementKey(semanticAgreement))
          ),
        });
        changed = true;
        continue;
      }

      const sameSideEntries = entries.filter((entry) => {
        if (localPath && entry.reason === "local_only") {
          return localCandidates.some((file) => file.path === entry.path);
        }
        if (peerPath && entry.reason === "peer_only") {
          return peerCandidates.some((file) => file.path === entry.path);
        }
        return false;
      });
      const canonicalPath = localPath ?? peerPath;
      const hasSharedCanonical = localPath !== undefined && localPath === peerPath;
      if (!canonicalPath || sameSideEntries.length === 0 || (!hasSharedCanonical && sameSideEntries.length < 2)) {
        continue;
      }
      for (const entry of sameSideEntries) {
        if (entry.path !== canonicalPath) {
          removed.add(entry);
          changed = true;
        }
      }
    }

    if (removed.size > 0 || replacements.length > 0) {
      entriesByNamespace.set(
        namespace,
        [...entries.filter((entry) => !removed.has(entry)), ...replacements].sort(compareReconcilePlanEntries)
      );
    }
  }

  if (!changed) return plan;
  const entries = [...entriesByNamespace.values()].flat().sort(compareReconcilePlanEntries);
  return {
    entries,
    byNamespace: summarizeReconcilePlan(entries),
    converged: entries.every((entry) => entry.action === "identical"),
  };
}

import { EngramAccessInputError } from "./access-service.js";
import { isNamespaceKind, type NamespaceKind } from "./namespaces/catalog.js";

/** Optional string field from a JSON body: absent/null/"" → undefined. */
export function optionalQueryString(value: unknown, label: string): string | undefined {
  if (value === undefined || value === null || value === "") return undefined;
  if (typeof value !== "string") {
    throw new EngramAccessInputError(`${label} must be a string (got ${JSON.stringify(value)})`);
  }
  return value;
}

/** Optional non-empty query param: null/"" → undefined. */
export function nonEmptyQueryParam(value: string | null): string | undefined {
  return value !== null && value.length > 0 ? value : undefined;
}

/** Optional positive-integer query param; rejects invalid values. */
export function positiveIntQueryParam(value: string | null, label: string): number | undefined {
  if (value === null || value.length === 0) return undefined;
  const parsed = Number(value);
  if (!Number.isFinite(parsed) || parsed <= 0 || !Number.isInteger(parsed)) {
    throw new EngramAccessInputError(`${label} expects a positive integer`);
  }
  return parsed;
}

/** Optional namespace-kind query param; rejects dead or unknown kinds. */
export function optionalNamespaceKindQueryParam(value: string | null): NamespaceKind | undefined {
  if (value === null || value.length === 0) return undefined;
  if (!isNamespaceKind(value)) {
    throw new EngramAccessInputError(
      "kind must be one of: default, shared, project, branch, team-project, explicit",
    );
  }
  return value;
}

/**
 * Wearables HTTP glue (issue #2047) — the wearables-input→400 error mapper
 * extracted from access-http.ts so that size-grandfathered file keeps only
 * thin route branches (same pattern as meetings/http-glue.ts). Returns false
 * for non-wearables faults so backend errors keep flowing to the global 500
 * handler.
 */

import type { ServerResponse } from "node:http";
