/**
 * Clean up expired chat sessions based on TTL.
 */
export async function cleanupExpiredChatSessions(
  memoryDir: string,
  ttlHours: number,
): Promise<number> {
  const dir = chatSessionDir(memoryDir);
  let files: string[];
  try {
    files = await readdir(dir);
  } catch {
    return 0;
  }
  const now = Date.now();
  let removed = 0;
  for (const file of files) {
    if (!file.endsWith(".jsonl")) continue;
    try {
      const filePath = join(dir, file);
      const st = await stat(filePath);
      const ageHours = (now - st.mtimeMs) / (1000 * 60 * 60);
      // TTL of 0 = expire everything immediately. For positive TTLs the
      // boundary is inclusive; sub-millisecond APFS mtime skew is negligible
      // against an hour-scale threshold (rule 54 — deterministic cleanup).
      if (ttlHours <= 0 || ageHours >= ttlHours) {
        // Re-check mtime immediately before unlinking so a turn appended
        // mid-sweep (which refreshes mtime) is not deleted by the stale age
        // decision captured above (codex P2). ttlHours <= 0 (expire-all)
        // skips the re-check. The residual microsecond window is a
        // legitimate sweep of an over-TTL file.
        if (ttlHours > 0) {
          const fresh = await stat(filePath);
          const freshAge = (Date.now() - fresh.mtimeMs) / (1000 * 60 * 60);
          if (freshAge < ttlHours) continue;
        }
        await unlink(filePath);
        removed++;
      }
    } catch {
      // Best-effort cleanup; skip files we can't stat/unlink.
    }
  }
  return removed;
}

/**
 * Verify that a session belongs to the given principal (rule 42/47 —
 * per-session isolation, no cross-visibility).
 */
export function sessionBelongsToPrincipal(
  session: ChatSessionState,
  principal?: string,
): boolean {
  // A session with no recorded principal is accessible to anyone (legacy/
  // single-user case).  A session with a principal requires an exact match.
  if (!session.principal) return true;
  return session.principal === principal;
}

/**
 * MCP tool-name prefixes (issue #2705).
 *
 * Anthropic tool names must match `^[a-zA-Z0-9_-]{1,64}$`.
 * Advertised canonical form is `remnic_<suffix>`.
 * `remnic.` and `engram.` stay callable.
 */
export const CANONICAL_MCP_PREFIX = "remnic_";
export const LEGACY_MCP_PREFIX = "engram.";
export const DOTTED_REMNIC_PREFIX = "remnic.";

const KNOWN_PREFIXES = [CANONICAL_MCP_PREFIX, DOTTED_REMNIC_PREFIX, LEGACY_MCP_PREFIX] as const;

export function toolNameSuffix(name: string): string | null {
  for (const prefix of KNOWN_PREFIXES) {
    if (name.startsWith(prefix)) return name.slice(prefix.length);
  }
  return null;
}

export function toCanonicalToolName(name: string): string {
  const suffix = toolNameSuffix(name);
  return suffix === null ? name : `${CANONICAL_MCP_PREFIX}${suffix}`;
}

export function toLegacyToolName(name: string): string {
  const suffix = toolNameSuffix(name);
  return suffix === null ? name : `${LEGACY_MCP_PREFIX}${suffix}`;
}

export function toDottedRemnicName(name: string): string {
  const suffix = toolNameSuffix(name);
  return suffix === null ? name : `${DOTTED_REMNIC_PREFIX}${suffix}`;
}

export function withToolAliases<T extends { name: string }>(tool: T, emitLegacyTools = true): T[] {
  const suffix = toolNameSuffix(tool.name);
  if (suffix === null) return [tool];
  const canonicalName = `${CANONICAL_MCP_PREFIX}${suffix}`;
  const canonicalTool = canonicalName === tool.name ? tool : { ...tool, name: canonicalName };
  if (!emitLegacyTools) return [canonicalTool];
  const legacyName = `${LEGACY_MCP_PREFIX}${suffix}`;
  const legacyTool = legacyName === tool.name ? tool : { ...tool, name: legacyName };
  return [canonicalTool, legacyTool];
}

