/**
 * Output-schema registry for MCP tools — extracted from access-mcp.ts to
 * keep that file under the 3000-LOC structural ratchet.
 *
 * Contains the per-suffix JSON-Schema declarations (derived from
 * production TS return contracts) and the application helper that
 * assigns schemas to tool objects.
 */

const T_STRING = { type: "string" } as const;
const T_NUMBER = { type: "number" } as const;
const T_BOOLEAN = { type: "boolean" } as const;
const T_ARRAY = { type: "array" } as const;
const T_OBJECT = { type: "object" } as const;
const T_NULLABLE_OBJECT = { type: ["object", "null"] } as const;
const T_NULLABLE_STRING = { type: ["string", "null"] } as const;
const T_NULLABLE_NUMBER = { type: ["number", "null"] } as const;

/** Build a JSON Schema object type with the given properties. */
function objectSchema(
  properties: Record<string, Readonly<Record<string, unknown>>>,
  required?: readonly string[]
): Record<string, unknown> {
  return {
    type: "object",
    properties,
    ...(required && required.length > 0 ? { required } : {}),
    additionalProperties: true,
  };
}

/** RecallNavigationResult-shaped schema — shared by memory_expand/memory_traverse. */
function navigationResultSchema(): Record<string, unknown> {
  return objectSchema(
    {
      ok: T_BOOLEAN,
      action: T_STRING,
      memoryId: T_STRING,
      namespace: T_STRING,
      items: T_ARRAY,
      truncated: T_BOOLEAN,
      budget: objectSchema({ chars: T_NUMBER, used: T_NUMBER }),
      disclosureSpend: objectSchema({
        chunk: objectSchema({ count: T_NUMBER, estimatedTokens: T_NUMBER }),
        section: objectSchema({ count: T_NUMBER, estimatedTokens: T_NUMBER }),
        raw: objectSchema({ count: T_NUMBER, estimatedTokens: T_NUMBER }),
        unspecified: objectSchema({ count: T_NUMBER, estimatedTokens: T_NUMBER }),
      }),
      error: T_NULLABLE_STRING,
      message: T_NULLABLE_STRING,
      rendered: T_STRING,
    },
    ["ok", "action", "rendered"]
  );
}

/** MemoryStoreBrowseResult-shaped schema — shared by memory_ls/tree/find. */
function browseResultSchema(): Record<string, unknown> {
  return objectSchema(
    {
      ok: T_BOOLEAN,
      verb: T_STRING,
      namespace: T_STRING,
      path: T_STRING,
      total: T_NUMBER,
      entries: T_ARRAY,
      truncated: T_BOOLEAN,
      rendered: T_STRING,
      error: T_NULLABLE_STRING,
      message: T_NULLABLE_STRING,
    },
    ["ok", "verb", "rendered"],
  );
}

