// ---------------------------------------------------------------------------
// V2 capsule manifest (issue #676 PR 1/6)
// ---------------------------------------------------------------------------
//
// The V2 manifest extends V1 with a `capsule` block describing a reusable,
// shareable bundle of memory state ("capsule"). This PR introduces ONLY the
// schema and a backward-compatible reader. Actual export/import pipelines and
// CLI surfaces are deferred to subsequent PRs (2/6 through 6/6).

/**
 * Allowed pattern for a user-chosen capsule id.
 *
 * - lowercase or uppercase alphanumerics and dashes
 * - must start and end with an alphanumeric (no leading/trailing dashes)
 * - no consecutive dashes
 * - 1..64 characters
 *
 * The constraints are intentionally narrow so capsule ids round-trip cleanly
 * through filesystem paths, URLs, and registry slugs without escaping.
 */
export const CAPSULE_ID_PATTERN = /^[A-Za-z0-9](?:[A-Za-z0-9]|-(?!-))*[A-Za-z0-9]$|^[A-Za-z0-9]$/;

const CapsuleIdSchema = z
  .string()
  .min(1, "capsule.id must not be empty")
  .max(64, "capsule.id must be 64 characters or fewer")
  .regex(
    CAPSULE_ID_PATTERN,
    "capsule.id must be alphanumeric with single dashes (no spaces, no leading/trailing dashes)",
  );

/**
 * Permissive semver-ish validator. We accept the common subset
 * `MAJOR.MINOR.PATCH` with optional pre-release / build suffixes. This is
 * intentionally looser than full semver 2.0 so capsule authors can use simple
 * versions like `1.0.0` or `0.1.0-rc.1` without pulling in a parser.
 */
const SemverLikeSchema = z
  .string()
  .min(1, "capsule.version must not be empty")
  .regex(
    /^\d+\.\d+\.\d+(?:-[0-9A-Za-z.-]+)?(?:\+[0-9A-Za-z.-]+)?$/,
    "capsule.version must be a semver-like string (e.g. 1.0.0)",
  );

function isSafePosixRelativePathPrefix(value: string): boolean {
  if (value.startsWith("/") || value.includes("\\")) return false;
  const segments = value.split("/");
  return segments.every((segment) => segment !== "" && segment !== "." && segment !== "..");
}

export const CapsuleRetrievalPolicySchema = z.object({
  /**
   * Per-tier weight overrides applied during recall when the capsule is the
   * active scope. Keys are tier names (e.g. `bm25`, `vector`, `graph`); values
   * are non-negative finite multipliers. The set of valid keys is left open
   * for now so future tiers do not break older manifests.
   */
  tierWeights: z.record(
    z.string().min(1),
    z.number().finite().nonnegative(),
  ),
  /**
   * Whether the direct-answer fast path is allowed when this capsule is
   * active. Operators may disable it for capsules whose contents should
   * always flow through the full retrieval pipeline.
   */
  directAnswerEnabled: z.boolean(),
});

export type CapsuleRetrievalPolicy = z.infer<typeof CapsuleRetrievalPolicySchema>;

export const CapsuleIncludesSchema = z.object({
  taxonomy: z.boolean(),
  identityAnchors: z.boolean(),
  peerProfiles: z.boolean(),
  procedural: z.boolean(),
});

export type CapsuleIncludes = z.infer<typeof CapsuleIncludesSchema>;

/**
 * Structured linkage to the capsule that was forked to produce this one.
 *
 * - `capsuleId`  — the `id` field from the parent capsule's manifest block.
 * - `version`    — the `version` field from the parent capsule's manifest block
 *                  at the time the fork was taken.
 * - `forkRoot`   — the posix-relative directory prefix under which the parent's
 *                  records were planted inside the fork's memory root, e.g.
 *                  `forks/parent-id`. Stored here so downstream tooling can
 *                  locate the imported parent tree without re-parsing paths.
 */
export const CapsuleParentSchema = z.object({
  capsuleId: CapsuleIdSchema,
  version: SemverLikeSchema,
  /**
   * Posix-relative path prefix under the fork's memory root where the parent
   * capsule's records were placed. Typically `forks/<parent-capsule-id>`.
   * Must be a non-empty string with no leading slash.
   */
  forkRoot: z
    .string()
    .min(1, "capsule.parent.forkRoot must not be empty")
    .refine(isSafePosixRelativePathPrefix, {
      message:
        "capsule.parent.forkRoot must be a normalized posix-relative path with no traversal segments",
    }),
});

export type CapsuleParent = z.infer<typeof CapsuleParentSchema>;

export const CapsuleBlockSchema = z.object({
  id: CapsuleIdSchema,
  version: SemverLikeSchema,
  /**
   * Taxonomy schema version the capsule was authored against. Free-form for
   * now; later PRs may tighten this to a known taxonomy registry.
   */
  schemaVersion: z.string().min(1, "capsule.schemaVersion must not be empty"),
  /**
   * Optional reference to the parent capsule this one was forked or derived
   * from. `null` (not `undefined`) is the explicit "no parent" sentinel so
   * that round-trips through JSON do not silently drop the field.
   *
   * @deprecated Prefer {@link parent} (structured). This field is preserved
   *   for backward compatibility with V2 manifests written before PR 4/6.
   */
  parentCapsule: z.string().min(1).nullable(),
  /**
   * Structured fork-lineage pointer added in PR 4/6. When present, this
   * capsule is a fork of the described parent. `null` is the explicit
   * "not a fork" sentinel — round-trips through JSON cleanly without
   * silently dropping the field.
   *
   * Defaults to `null` so that V2 manifests written before PR 4/6 (which
   * omit this field) still parse without error. This preserves backward
   * compatibility with the existing `makeV2Manifest()` test fixtures and
   * any in-the-wild V2 archives produced by PR 2/6 and PR 3/6.
   *
   * Invariant: when `parent` is non-null, `parentCapsule` SHOULD equal
   * `parent.capsuleId` for backward compatibility with readers that only
   * understand the legacy field. `forkCapsule()` sets both.
   */
  parent: CapsuleParentSchema.nullable().default(null),
  description: z.string(),
  retrievalPolicy: CapsuleRetrievalPolicySchema,
  includes: CapsuleIncludesSchema,
});

export type CapsuleBlock = z.infer<typeof CapsuleBlockSchema>;

export const ExportManifestV2Schema = z.object({
  format: z.literal("openclaw-engram-export"),
  schemaVersion: z.literal(2),
  createdAt: z.string(),
  pluginVersion: z.string(),
  includesTranscripts: z.boolean(),
  files: z.array(
    z.object({
      path: z.string(),
      sha256: z.string(),
      bytes: z.number().int().nonnegative(),
    }),
  ),
  capsule: CapsuleBlockSchema,
});

export type ExportManifestV2 = z.infer<typeof ExportManifestV2Schema>;

export const ExportBundleV2Schema = z.object({
  manifest: ExportManifestV2Schema,
  records: z.array(ExportMemoryRecordV1Schema),
});

export type ExportBundleV2 = z.infer<typeof ExportBundleV2Schema>;

// ---------------------------------------------------------------------------
// Backward-compatible reader
// ---------------------------------------------------------------------------

export type AnyExportManifest = ExportManifestV1 | ExportManifestV2;
export type AnyExportBundle = ExportBundleV1 | ExportBundleV2;

/**
 * Normalized form returned by {@link parseExportManifest}. Callers that don't
 * care about the wire-format version can branch on `capsuleVersion` (1 or 2)
 * and trust that V1 manifests surface as `{ capsuleVersion: 1, capsule: null }`.
 */
export interface NormalizedExportManifest {
  capsuleVersion: 1 | 2;
  manifest: AnyExportManifest;
  capsule: CapsuleBlock | null;
}

/**
 * Parse an unknown manifest payload as either V1 or V2.
 *
 * Dispatch is driven by `schemaVersion` so we surface the most relevant
 * validation error per branch. If `schemaVersion` is missing or unknown we
 * fall back to V1 first (the historical wire format) and only report the V2
 * error if both branches fail.
 */
export function parseExportManifest(input: unknown): NormalizedExportManifest {
  const version =
    typeof input === "object" && input !== null
      ? (input as { schemaVersion?: unknown }).schemaVersion
      : undefined;

  if (version === 2) {
    const manifest = ExportManifestV2Schema.parse(input);
    return {
      capsuleVersion: 2,
      manifest,
      capsule: manifest.capsule,
    };
  }

  if (version === 1) {
    const manifest = ExportManifestV1Schema.parse(input);
    return { capsuleVersion: 1, manifest, capsule: null };
  }

  // Unknown / missing schemaVersion: try V1 then V2 so the reader stays
  // forgiving for hand-authored payloads but still produces a clear error.
  const v1 = ExportManifestV1Schema.safeParse(input);
  if (v1.success) {
    return { capsuleVersion: 1, manifest: v1.data, capsule: null };
  }
  const v2 = ExportManifestV2Schema.safeParse(input);
  if (v2.success) {
    return {
      capsuleVersion: 2,
      manifest: v2.data,
      capsule: v2.data.capsule,
    };
  }
  // Surface the V2 error since callers introducing capsules likely care most
  // about that branch's diagnostics.
  throw v2.error;
}

/**
 * Convenience: parse a full bundle (manifest + records) accepting either V1
 * or V2 manifests. Records currently share the V1 shape across both versions.
 */
export function parseExportBundle(input: unknown): {
  capsuleVersion: 1 | 2;
  bundle: AnyExportBundle;
  capsule: CapsuleBlock | null;
} {
  if (typeof input !== "object" || input === null) {
    // Defer to V1 schema so the user sees a familiar zod error.
    ExportBundleV1Schema.parse(input);
    throw new Error("unreachable");
  }
  const manifestRaw = (input as { manifest?: unknown }).manifest;
  const normalized = parseExportManifest(manifestRaw);
  if (normalized.capsuleVersion === 2) {
    const bundle = ExportBundleV2Schema.parse(input);
    return { capsuleVersion: 2, bundle, capsule: bundle.manifest.capsule };
  }
  const bundle = ExportBundleV1Schema.parse(input);
  return { capsuleVersion: 1, bundle, capsule: null };
}

/**
 * Binary file lifecycle management types.
 *
 * Defines the configuration, manifest, and record structures for the
 * three-stage binary lifecycle pipeline: mirror, redirect, clean.
 */

export interface BinaryLifecycleConfig {
  /** Master toggle. Default: false. */
  enabled: boolean;
  /** Days after mirror before local copy is eligible for cleanup. Default: 7. */
  gracePeriodDays: number;
  /** Files larger than this are skipped during scan. Default: 50 MB. */
  maxBinarySizeBytes: number;
  /** Glob patterns for binary file types to manage. */
  scanPatterns: string[];
  /** Backend configuration for binary storage. */
  backend: BinaryStorageBackendConfig;
}

export interface BinaryStorageBackendConfig {
  /** Backend type. "filesystem" copies to a local directory. "none" is a no-op (dry-run/testing). */
  type: "filesystem" | "s3" | "none";
  /** Destination directory for the filesystem backend. */
  basePath?: string;
  /** S3 bucket name (future). */
  s3Bucket?: string;
  /** S3 region (future). */
  s3Region?: string;
  /** S3 key prefix (future). */
  s3Prefix?: string;
}

export type BinaryAssetStatus =
  | "pending"
  | "mirrored"
  | "redirected"
  | "cleaned"
  | "error";

export interface BinaryAssetRecord {
  /** Relative path from memoryDir to the original file. */
  originalPath: string;
  /** Path (or URL) in the backend storage. */
  mirroredPath: string;
  /** Optional user-resolvable target to write into markdown links. */
  redirectPath?: string;
  /** SHA-256 hex digest of file content. */
  contentHash: string;
  /** File size in bytes. */
  sizeBytes: number;
  /** MIME type (e.g. "image/png"). */
  mimeType: string;
  /** ISO 8601 timestamp when the file was mirrored. */
  mirroredAt: string;
  /** ISO 8601 timestamp when markdown references were rewritten. */
  redirectedAt?: string;
  /** ISO 8601 timestamp when the local copy was deleted. */
  cleanedAt?: string;
  /** Current lifecycle status. */
  status: BinaryAssetStatus;
}

export interface BinaryLifecycleManifest {
  version: 1;
  assets: BinaryAssetRecord[];
  lastScanAt?: string;
}

export interface PipelineResult {
  scanned: number;
  mirrored: number;
  redirected: number;
  cleaned: number;
  errors: string[];
  dryRun: boolean;
}

export const DEFAULT_SCAN_PATTERNS = [
  "*.png",
  "*.jpg",
  "*.jpeg",
  "*.gif",
  "*.pdf",
  "*.mp3",
  "*.mp4",
  "*.wav",
];

export const DEFAULT_MAX_BINARY_SIZE_BYTES = 50 * 1024 * 1024; // 50 MB
export const DEFAULT_GRACE_PERIOD_DAYS = 7;

/**
 * Binary storage backend interface and implementations.
 *
 * Backends handle the actual persistence of binary files to an external
 * location. The pipeline calls upload/exists/delete through this interface
 * so swapping storage providers requires no pipeline changes.
 */

import type { Stats } from "node:fs";
import fsp from "node:fs/promises";
import path from "node:path";
import type { BinaryStorageBackendConfig } from "./types.js";
import { isErrnoCode } from "../utils/errno.js";

// ---------------------------------------------------------------------------
// Interface
// ---------------------------------------------------------------------------

export interface BinaryStorageBackend {
  /** Discriminator for the backend type. */
  readonly type: string;
  /**
   * Upload a local file to the backend.
   * @returns The backend path or URL where the file was stored.
   */
  upload(localPath: string, remotePath: string): Promise<string>;
  /** Check whether a remote path already exists in the backend. */
  exists(remotePath: string): Promise<boolean>;
  /** Delete a file from the backend. */
  delete(remotePath: string): Promise<void>;
  /** Return the user-resolvable markdown target for a stored backend path. */
  getRedirectTarget?(remotePath: string): string;
}

// ---------------------------------------------------------------------------
// Filesystem backend
// ---------------------------------------------------------------------------

export class FilesystemBackend implements BinaryStorageBackend {
  readonly type = "filesystem";
  private readonly basePath: string;

  constructor(basePath: string) {
    if (!basePath || basePath.trim().length === 0) {
      throw new Error("FilesystemBackend requires a non-empty basePath");
    }
    this.basePath = path.resolve(basePath);
  }

  private resolveRemotePath(remotePath: string): string {
    const resolved = path.isAbsolute(remotePath)
      ? path.resolve(remotePath)
      : path.resolve(this.basePath, remotePath);
    const relative = path.relative(this.basePath, resolved);
    if (relative === ".." || relative.startsWith(`..${path.sep}`) || path.isAbsolute(relative)) {
      throw new Error(`FilesystemBackend remotePath escapes basePath: ${JSON.stringify(remotePath)}`);
    }
    return resolved;
  }

  private isInsideBase(candidate: string, realBase: string): boolean {
    const relative = path.relative(realBase, candidate);
    return relative === "" || (relative !== ".." && !relative.startsWith(`..${path.sep}`) && !path.isAbsolute(relative));
  }

  private async realBasePathIfExists(): Promise<string | null> {
    try {
      const stat = await fsp.lstat(this.basePath);
      if (stat.isSymbolicLink()) {
        throw new Error(`FilesystemBackend basePath must not be a symlink: ${this.basePath}`);
      }
      if (!stat.isDirectory()) {
        throw new Error(`FilesystemBackend basePath must be a directory: ${this.basePath}`);
      }
      return await fsp.realpath(this.basePath);
    } catch (err) {
      if ((err as NodeJS.ErrnoException).code === "ENOENT") {
        return null;
      }
      throw err;
    }
  }

  private async ensureBaseDirectory(): Promise<string> {
    await fsp.mkdir(this.basePath, { recursive: true });
    const realBase = await this.realBasePathIfExists();
    if (realBase === null) {
      throw new Error(`FilesystemBackend failed to create basePath: ${this.basePath}`);
    }
    return realBase;
  }

  private async ensureSafeParentDirectory(dest: string): Promise<string> {
    const realBase = await this.ensureBaseDirectory();
    const destDir = path.dirname(dest);
    const relativeDir = path.relative(this.basePath, destDir);
    const segments = relativeDir === "" ? [] : relativeDir.split(path.sep);
    let current = this.basePath;

    for (const segment of segments) {
      if (segment === "." || segment === "") continue;
      current = path.join(current, segment);
      try {
        const stat = await fsp.lstat(current);
        if (stat.isSymbolicLink()) {
          throw new Error(`FilesystemBackend remotePath traverses symlink: ${current}`);
        }
        if (!stat.isDirectory()) {
          throw new Error(`FilesystemBackend remotePath parent is not a directory: ${current}`);
        }
      } catch (err) {
        if ((err as NodeJS.ErrnoException).code !== "ENOENT") {
          throw err;
        }
        await fsp.mkdir(current);
      }
    }

    const realParent = await fsp.realpath(destDir);
    if (!this.isInsideBase(realParent, realBase)) {
      throw new Error(`FilesystemBackend remotePath parent escapes basePath: ${dest}`);
    }
    return realBase;
  }

  private async resolveExistingRemotePath(remotePath: string): Promise<string | null> {
    const dest = this.resolveRemotePath(remotePath);
    const realBase = await this.realBasePathIfExists();
    if (realBase === null) {
      return null;
    }

    const destDir = path.dirname(dest);
    const relativeDir = path.relative(this.basePath, destDir);
    const segments = relativeDir === "" ? [] : relativeDir.split(path.sep);
    let current = this.basePath;
    for (const segment of segments) {
      if (segment === "." || segment === "") continue;
      current = path.join(current, segment);
      let stat: Stats;
      try {
        stat = await fsp.lstat(current);
      } catch (err) {
        if ((err as NodeJS.ErrnoException).code === "ENOENT") {
          return null;
        }
        throw err;
      }
      if (stat.isSymbolicLink()) {
        throw new Error(`FilesystemBackend remotePath traverses symlink: ${current}`);
      }
      if (!stat.isDirectory()) {
        return null;
      }
    }

    const realParent = await fsp.realpath(destDir).catch((err: NodeJS.ErrnoException) => {
      if (isErrnoCode(err, "ENOENT")) return null;
      throw err;
    });
    if (realParent === null) {
      return null;
    }
    if (!this.isInsideBase(realParent, realBase)) {
      throw new Error(`FilesystemBackend remotePath parent escapes basePath: ${JSON.stringify(remotePath)}`);
    }

    try {
      const stat = await fsp.lstat(dest);
      if (stat.isSymbolicLink()) {
        throw new Error(`FilesystemBackend remotePath points to symlink: ${dest}`);
      }
      if (!stat.isFile()) {
        return null;
      }
    } catch (err) {
      if ((err as NodeJS.ErrnoException).code === "ENOENT") {
        return null;
      }
      throw err;
    }

    const realDest = await fsp.realpath(dest);
    if (!this.isInsideBase(realDest, realBase)) {
      throw new Error(`FilesystemBackend remotePath escapes basePath: ${JSON.stringify(remotePath)}`);
    }
    return dest;
  }

  async upload(localPath: string, remotePath: string): Promise<string> {
    if (path.isAbsolute(remotePath)) {
      throw new Error(`FilesystemBackend upload remotePath must be relative: ${JSON.stringify(remotePath)}`);
    }
    const dest = this.resolveRemotePath(remotePath);
    const realBase = await this.ensureSafeParentDirectory(dest);
    try {
      const stat = await fsp.lstat(dest);
      if (stat.isSymbolicLink()) {
        throw new Error(`FilesystemBackend remotePath points to symlink: ${dest}`);
      }
    } catch (err) {
      if ((err as NodeJS.ErrnoException).code !== "ENOENT") {
        throw err;
      }
    }
    await fsp.copyFile(localPath, dest);
    const realDest = await fsp.realpath(dest);
    if (!this.isInsideBase(realDest, realBase)) {
      throw new Error(`FilesystemBackend remotePath escapes basePath: ${JSON.stringify(remotePath)}`);
    }
    return remotePath;
  }

  async exists(remotePath: string): Promise<boolean> {
    const dest = await this.resolveExistingRemotePath(remotePath);
    return dest !== null;
  }

  async delete(remotePath: string): Promise<void> {
    const dest = await this.resolveExistingRemotePath(remotePath);
    if (dest === null) {
      return;
    }
    try {
      await fsp.unlink(dest);
    } catch (err: unknown) {
      // Ignore ENOENT (already deleted); rethrow everything else.
      if ((err as NodeJS.ErrnoException).code !== "ENOENT") throw err;
    }
  }

  getRedirectTarget(remotePath: string): string {
    return this.resolveRemotePath(remotePath);
  }
}

// ---------------------------------------------------------------------------
// None backend (no-op, for dry-run / testing)
// ---------------------------------------------------------------------------

export class NoneBackend implements BinaryStorageBackend {
  readonly type = "none";

  async upload(_localPath: string, remotePath: string): Promise<string> {
    return remotePath;
  }

  async exists(_remotePath: string): Promise<boolean> {
    return false;
  }

  async delete(_remotePath: string): Promise<void> {
    // intentional no-op
  }
}

// ---------------------------------------------------------------------------
// Factory
// ---------------------------------------------------------------------------

export function createBackend(cfg: BinaryStorageBackendConfig): BinaryStorageBackend {
  switch (cfg.type) {
    case "filesystem": {
      if (!cfg.basePath) {
        throw new Error(
          "BinaryStorageBackendConfig.basePath is required when type is \"filesystem\"",
        );
      }
      return new FilesystemBackend(cfg.basePath);
    }
    case "s3":
      throw new Error("S3 binary storage backend is not yet implemented");
    case "none":
      return new NoneBackend();
    default:
      throw new Error(`Unknown binary storage backend type: ${String((cfg as { type: string }).type)}`);
  }
}

/**
 * Binary file scanner.
 *
 * Recursively walks the memory directory, matches files against configured
 * glob patterns, skips files already tracked in the manifest, and respects
 * the max-size limit.
 */

import fsp from "node:fs/promises";
import path from "node:path";
import crypto from "node:crypto";
import type { BinaryLifecycleConfig, BinaryLifecycleManifest } from "./types.js";

/**
 * Test whether a filename matches any of the provided glob patterns.
 * Supports simple `*.ext` patterns (the default scan patterns).
 * For more complex globs a proper library should be used; this covers
 * the 95% case without adding a dependency.
 */
export function matchesPatterns(filename: string, patterns: string[]): boolean {
  const lower = filename.toLowerCase();
  for (const pattern of patterns) {
    // Simple *.ext matching
    if (pattern.startsWith("*.")) {
      const ext = pattern.slice(1).toLowerCase(); // e.g. ".png"
      if (lower.endsWith(ext)) return true;
    } else if (lower === pattern.toLowerCase()) {
      return true;
    }
  }
  return false;
}

/**
 * Scan memoryDir recursively for binary files matching the configured patterns.
 * Returns relative paths (relative to memoryDir) for files not yet tracked.
 */
export async function scanForBinaries(
  memoryDir: string,
  config: BinaryLifecycleConfig,
  manifest: BinaryLifecycleManifest,
): Promise<string[]> {
  const tracked = new Map(manifest.assets.map((a) => [a.originalPath, a]));
  const results: string[] = [];

  async function walk(dir: string): Promise<void> {
    let entries: import("node:fs").Dirent[];
    try {
      entries = await fsp.readdir(dir, { withFileTypes: true });
    } catch {
      return; // skip unreadable directories
    }

    for (const entry of entries) {
      const fullPath = path.join(dir, entry.name);
      // Normalize to POSIX separators so redirect matching works on Windows
      // (markdown links always use forward slashes).
      const relativePath = path.relative(memoryDir, fullPath).split(path.sep).join("/");

      if (entry.isDirectory()) {
        // Skip the manifest directory itself and hidden dirs starting with .
        if (entry.name === ".binary-lifecycle") continue;
        await walk(fullPath);
        continue;
      }

      if (!entry.isFile()) continue;

      // Check pattern match
      if (!matchesPatterns(entry.name, config.scanPatterns)) continue;

      // Check file size
      try {
        const stat = await fsp.stat(fullPath);
        if (stat.size > config.maxBinarySizeBytes) continue;
        if (stat.size === 0) continue; // skip empty files
        const existing = tracked.get(relativePath);
        if (existing) {
          if (existing.sizeBytes !== stat.size) {
            results.push(relativePath);
            continue;
          }
          const contentHash = await hashFile(fullPath);
          if (existing.contentHash !== contentHash) {
            results.push(relativePath);
          }
          continue;
        }
      } catch {
        continue; // stat failure, skip
      }

      results.push(relativePath);
    }
  }

  await walk(memoryDir);
  return results;
}

async function hashFile(filePath: string): Promise<string> {
  const content = await fsp.readFile(filePath);
  return crypto.createHash("sha256").update(content).digest("hex");
}

/**
 * Binary lifecycle manifest — read/write operations.
 *
 * The manifest lives at `${memoryDir}/.binary-lifecycle/manifest.json`.
 * Writes use the atomic temp-then-rename pattern (CLAUDE.md #54).
 */

import fs from "node:fs";
import fsp from "node:fs/promises";
import path from "node:path";
import crypto from "node:crypto";
import type { BinaryLifecycleManifest } from "./types.js";

const MANIFEST_DIR = ".binary-lifecycle";
const MANIFEST_FILE = "manifest.json";

export function manifestDir(memoryDir: string): string {
  return path.join(memoryDir, MANIFEST_DIR);
}

export function manifestPath(memoryDir: string): string {
  return path.join(memoryDir, MANIFEST_DIR, MANIFEST_FILE);
}

/**
 * Read the manifest from disk. Returns a fresh empty manifest if the file
 * does not exist. Existing invalid manifests fail closed so the pipeline does
 * not overwrite state needed for safe cleanup.
 */
export async function readManifest(memoryDir: string): Promise<BinaryLifecycleManifest> {
  const filePath = manifestPath(memoryDir);
  let raw: string;
  try {
    raw = await fsp.readFile(filePath, "utf-8");
  } catch (err) {
    if ((err as NodeJS.ErrnoException).code === "ENOENT") {
      return emptyManifest();
    }
    throw new Error(`Failed to read binary lifecycle manifest at ${filePath}: ${err instanceof Error ? err.message : String(err)}`);
  }

  let parsed: unknown;
  try {
    parsed = JSON.parse(raw);
  } catch (err) {
    throw new Error(`Invalid binary lifecycle manifest JSON at ${filePath}: ${err instanceof Error ? err.message : String(err)}`);
  }

  // CLAUDE.md #18: validate the parsed result is a non-null object.
  if (typeof parsed !== "object" || parsed === null || Array.isArray(parsed)) {
    throw new Error(`Invalid binary lifecycle manifest shape at ${filePath}: expected object`);
  }
  const obj = parsed as Record<string, unknown>;
  if (obj.version !== 1 || !Array.isArray(obj.assets)) {
    throw new Error(`Invalid binary lifecycle manifest shape at ${filePath}: expected version 1 with assets array`);
  }
  return parsed as BinaryLifecycleManifest;
}

/**
 * Write the manifest atomically: write to a temp file, then rename.
 * CLAUDE.md #54: never delete before write. Write temp first, rename atomically.
 */
export async function writeManifest(
  memoryDir: string,
  manifest: BinaryLifecycleManifest,
): Promise<void> {
  const dir = manifestDir(memoryDir);
  await fsp.mkdir(dir, { recursive: true });
  const dest = manifestPath(memoryDir);
  const tmpSuffix = crypto.randomBytes(8).toString("hex");
  const tmpPath = `${dest}.${tmpSuffix}.tmp`;
  // Sort keys for deterministic output (CLAUDE.md #38).
  const content = JSON.stringify(manifest, null, 2) + "\n";
  await fsp.writeFile(tmpPath, content, "utf-8");
  try {
    await fsp.rename(tmpPath, dest);
  } catch (renameErr) {
    // Clean up temp on rename failure (cross-device edge case).
    try {
      await fsp.unlink(tmpPath);
    } catch {
      // ignore cleanup failure
    }
    throw renameErr;
  }
}

export function emptyManifest(): BinaryLifecycleManifest {
  return { version: 1, assets: [] };
}

/**
 * Binary lifecycle pipeline — mirror, redirect, clean.
 *
 * Three-stage pipeline:
 * 1. Mirror:   upload binary to backend, record in manifest
 * 2. Redirect: scan markdown for inline refs, replace with redirect path
 * 3. Clean:    after grace period, delete local copy
 */

import fsp from "node:fs/promises";
import path from "node:path";
import crypto from "node:crypto";
import type {
  BinaryAssetRecord,
  BinaryLifecycleConfig,
  PipelineResult,
} from "./types.js";
import type { BinaryStorageBackend } from "./backend.js";
import { readManifest, writeManifest } from "./manifest.js";
import { scanForBinaries } from "./scanner.js";
import { bumpMemoryCorpusVersionForDir } from "../memory-corpus-version.js";
import { RECALL_FALLBACK_DIRS } from "../utils/category-dir.js";
import {
  HistoricalEntityCanonicalIdCache,
  canonicalizeEntityRefFrontmatter,
  classifyEntityRefWritePath,
  repairContentAfterJournalMove,
  requestEntityCanonicalIdReconcile,
} from "../storage/entity-canonical-id-references.js";
import { withRawEntityPageMutation } from "../storage/entity-canonical-id-lock.js";

// Write-boundary journal cache for redirect rewrites (issue #2213).
const historicalIdCache = new HistoricalEntityCanonicalIdCache();

/**
 * True when `mdPath` is an active recall-corpus memory file under `memoryDir`
 * (a top-level RECALL_FALLBACK_DIRS category), so a redirect rewrite of it must
 * bump the corpus sentinel to self-heal a warm hot-memories cache (#1902).
 * entities/, artifacts/, and other non-recall paths need no bump.
 */
function isRecallCorpusMarkdown(mdPath: string, memoryDir: string): boolean {
  const rel = path.relative(memoryDir, mdPath);
  if (rel.startsWith("..") || path.isAbsolute(rel)) return false;
  const top = rel.split(path.sep)[0];
  return (RECALL_FALLBACK_DIRS as readonly string[]).includes(top);
}

/** Minimal logger interface so we don't depend on the full logger module. */
interface PipelineLogger {
  info(msg: string): void;
  warn(msg: string): void;
  error(msg: string): void;
}

type ReadMarkdownFile = (filePath: string) => Promise<string>;
type WriteMarkdownFile = (filePath: string, content: string) => Promise<void>;

interface PipelineOptions {
  dryRun?: boolean;
  /** Force-clean all files past grace period, ignoring redirect status. */
  forceClean?: boolean;
  /** Test hook for deterministic markdown read failures. */
  readMarkdownFile?: ReadMarkdownFile;
  /** Test hook for deterministic markdown write failures. */
  writeMarkdownFile?: WriteMarkdownFile;
}

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------

async function hashFile(filePath: string): Promise<string> {
  const content = await fsp.readFile(filePath);
  return crypto.createHash("sha256").update(content).digest("hex");
}

function guessMimeType(ext: string): string {
  const map: Record<string, string> = {
    ".png": "image/png",
    ".jpg": "image/jpeg",
    ".jpeg": "image/jpeg",
    ".gif": "image/gif",
    ".pdf": "application/pdf",
    ".mp3": "audio/mpeg",
    ".mp4": "video/mp4",
    ".wav": "audio/wav",
  };
  return map[ext.toLowerCase()] ?? "application/octet-stream";
}

/**
 * Escape special regex characters in a string.
 * CLAUDE.md #46: always escapeRegex on user-derived parts.
 */
function escapeRegex(s: string): string {
  return s.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
}

function resolveManifestAssetPath(memoryDir: string, originalPath: string): string | null {
  if (
    originalPath.length === 0 ||
    originalPath.includes("\0") ||
    originalPath.includes("\\") ||
    path.isAbsolute(originalPath) ||
    path.win32.isAbsolute(originalPath)
  ) {
    return null;
  }

  const memoryRoot = path.resolve(memoryDir);
  const fullPath = path.resolve(memoryRoot, originalPath);
  const relative = path.relative(memoryRoot, fullPath);
  if (relative === "" || relative === ".." || relative.startsWith(`..${path.sep}`) || path.isAbsolute(relative)) {
    return null;
  }

  return fullPath;
}

function validateBinaryLifecycleConfig(config: BinaryLifecycleConfig): void {
  if (
    typeof config.gracePeriodDays !== "number" ||
    !Number.isFinite(config.gracePeriodDays) ||
    !Number.isInteger(config.gracePeriodDays) ||
    config.gracePeriodDays < 0
  ) {
    throw new Error("binary lifecycle gracePeriodDays must be a finite non-negative integer");
  }
}

function remotePathForAsset(backend: BinaryStorageBackend, relPath: string): string {
  const normalized = relPath.split(path.sep).join("/");
  if (backend.type === "filesystem") {
    return `.binary-lifecycle/mirrors/${normalized}`;
  }
  return normalized;
}

function markdownTargetForAsset(asset: BinaryAssetRecord): string {
  return asset.redirectPath ?? asset.mirroredPath;
}

// ---------------------------------------------------------------------------
// Pipeline stages
// ---------------------------------------------------------------------------

async function stageMirror(
  memoryDir: string,
  newPaths: string[],
  backend: BinaryStorageBackend,
  assets: BinaryAssetRecord[],
  log: PipelineLogger,
  dryRun: boolean,
): Promise<{ mirrored: number; errors: string[] }> {
  let mirrored = 0;
  const errors: string[] = [];

  for (const relPath of newPaths) {
    const fullPath = path.join(memoryDir, relPath);
    try {
      const stat = await fsp.stat(fullPath);
      const contentHash = await hashFile(fullPath);
      const ext = path.extname(relPath);
      const mimeType = guessMimeType(ext);
      const remotePath = remotePathForAsset(backend, relPath);

      let backendLocation = remotePath;
      if (!dryRun) {
        backendLocation = await backend.upload(fullPath, remotePath);
      }
      const redirectPath = backend.getRedirectTarget?.(backendLocation);

      const record: BinaryAssetRecord = {
        originalPath: relPath,
        mirroredPath: backendLocation,
        ...(redirectPath ? { redirectPath } : {}),
        contentHash,
        sizeBytes: stat.size,
        mimeType,
        mirroredAt: new Date().toISOString(),
        status: "mirrored",
      };

      if (!dryRun) {
        const existingIndex = assets.findIndex((asset) => asset.originalPath === relPath);
        if (existingIndex >= 0) {
          assets.splice(existingIndex, 1);
        }
        assets.push(record);
      }
      mirrored++;
      log.info(`[binary-lifecycle] mirrored: ${relPath} (${stat.size} bytes)${dryRun ? " [dry-run]" : ""}`);
    } catch (err) {
      const msg = `mirror failed for ${relPath}: ${err instanceof Error ? err.message : String(err)}`;
      log.error(`[binary-lifecycle] ${msg}`);
      errors.push(msg);
    }
  }

  return { mirrored, errors };
}

async function stageRedirect(
  memoryDir: string,
  assets: BinaryAssetRecord[],
  log: PipelineLogger,
  dryRun: boolean,
  readMarkdownFile: ReadMarkdownFile,
  writeMarkdownFile: WriteMarkdownFile,
): Promise<{ redirected: number; errors: string[] }> {
  let redirected = 0;
  const errors: string[] = [];

  // Redirect mirrored assets and retry prior redirect errors. Clean-stage errors
  // remain safe because the redirect path validation below will keep rejecting
  // invalid manifest records.
  const candidates = assets.filter((a) => a.status === "mirrored" || a.status === "error");
  if (candidates.length === 0) return { redirected, errors };

  // Find all markdown files in memoryDir (recursive).
  const mdFiles = await findMarkdownFiles(memoryDir);

  for (const asset of candidates) {
    const assetAbsolute = resolveManifestAssetPath(memoryDir, asset.originalPath);
    if (assetAbsolute === null) {
      const msg = `redirect blocked for ${asset.originalPath}: manifest path is outside memoryDir`;
      log.error(`[binary-lifecycle] ${msg}`);
      errors.push(msg);
      if (!dryRun) {
        asset.status = "error";
      }
      continue;
    }

    const updates: Array<{ mdPath: string; content: string }> = [];
    let scanFailCount = 0;
    for (const mdPath of mdFiles) {
      try {
        const content = await readMarkdownFile(mdPath);

        const pattern = markdownReferencePattern(asset, assetAbsolute, mdPath);

        if (!pattern.test(content)) continue;

        // Reset lastIndex after test().
        pattern.lastIndex = 0;
        const updated = content.replace(pattern, (_match, open, _target, close) => {
          return `${open as string}${markdownTargetForAsset(asset)}${close as string}`;
        });
        updates.push({ mdPath, content: updated });
      } catch (err) {
        scanFailCount++;
        const msg = `redirect scan failed for ${mdPath}: ${err instanceof Error ? err.message : String(err)}`;
        log.error(`[binary-lifecycle] ${msg}`);
        errors.push(msg);
      }
    }

    if (scanFailCount > 0) {
      if (!dryRun) {
        asset.status = "error";
      }
      log.warn(
        `[binary-lifecycle] redirect blocked for ${asset.originalPath}: ` +
          `${scanFailCount} markdown scan failure(s)` +
          `${dryRun ? "" : " — status set to error"}`,
      );
      continue;
    }

    if (updates.length === 0) {
      if (asset.status === "error") {
        const verifyResult = await countRemainingLocalReferences(
          memoryDir,
          asset,
          assetAbsolute,
          mdFiles,
          readMarkdownFile,
        );
        if (verifyResult.errors.length > 0 || verifyResult.remaining > 0) {
          if (!dryRun) {
            asset.status = "error";
          }
          for (const msg of verifyResult.errors) {
            log.error(`[binary-lifecycle] ${msg}`);
            errors.push(msg);
          }
          if (verifyResult.remaining > 0) {
            const msg = `redirect verification failed for ${asset.originalPath}: ${verifyResult.remaining} local reference(s) remain`;
            log.warn(`[binary-lifecycle] ${msg}`);
            errors.push(msg);
          }
          continue;
        }

        if (asset.redirectedAt === undefined) {
          let remoteSeen = false;
          for (const mdPath of mdFiles) {
            try {
              const content = await readMarkdownFile(mdPath);
              if (content.includes(asset.mirroredPath)) {
                remoteSeen = true;
                break;
              }
            } catch {
              // Verify already succeeded; a later read error is not a local ref.
            }
          }
          if (!remoteSeen) {
            if (!dryRun) {
              asset.status = "mirrored";
            }
            log.info(`[binary-lifecycle] preserved mirrored asset without redirected marker: ${asset.originalPath}${dryRun ? " [dry-run]" : ""}`);
            continue;
          }
        }

        if (!Number.isFinite(new Date(asset.mirroredAt).getTime())) {
          const msg = `redirect blocked for ${asset.originalPath}: manifest mirroredAt is invalid`;
          log.error(`[binary-lifecycle] ${msg}`);
          errors.push(msg);
          if (!dryRun) {
            asset.status = "error";
          }
          continue;
        }

        if (!dryRun) {
          asset.status = "redirected";
          asset.redirectedAt = new Date().toISOString();
        }
        redirected++;
        log.info(`[binary-lifecycle] redirected: ${asset.originalPath}${dryRun ? " [dry-run]" : ""}`);
      }
      continue;
    }

    if (dryRun) {
      redirected++;
      log.info(`[binary-lifecycle] redirected: ${asset.originalPath} [dry-run]`);
      continue;
    }

    let writeFailCount = 0;
    for (const update of updates) {
      try {
        // Whole-record rewrite of bytes read earlier (issue #2213): for
        // memory-tier records, resolve the frontmatter entityRef through the
        // CURRENT journal at the write and REPAIR afterwards — writing back
        // the as-read bytes could revert a rewrite a peer migration performed
        // since the read. findMarkdownFiles also surfaces transcripts,
        // profiles, and other Markdown outside the migration's scope: those
        // keep their bytes (plus the redirect) untouched, and entities/ pages
        // get the bounded reconcile marker instead — their migrated surface
        // is relationship targets, not an entityRef frontmatter field.
        await withRawEntityPageMutation(memoryDir, update.mdPath, async () => {
        const stateDir = path.join(memoryDir, "state");
        const kind = classifyEntityRefWritePath(memoryDir, update.mdPath);
        if (kind === "memory") {
          const idsAtWrite = historicalIdCache.get(stateDir);
          const written = canonicalizeEntityRefFrontmatter(update.content, idsAtWrite);
          // Snapshot the ORIGINAL bytes: if repair fails after the write, the
          // catch below reports a failed redirect, so the file must return to
          // its pre-redirect state — a retry needs the original reference,
          // and the skipped corpus bump means a warm cache would otherwise
          // keep serving bytes that no longer match disk (AGENTS.md §14).
          const originalBytes = await readMarkdownFile(update.mdPath).catch(() => null);
          await writeMarkdownFile(update.mdPath, written);
          try {
            await repairContentAfterJournalMove({
              stateDir,
              cache: historicalIdCache,
              idsAtWrite,
              rawContent: update.content,
              lastWritten: written,
              rewrite: (next) => writeMarkdownFile(update.mdPath, next),
            });
          } catch (err) {
            if (originalBytes !== null) {
              await writeMarkdownFile(update.mdPath, originalBytes).catch(() => undefined);
            }
            throw err;
          }
        } else {
          await writeMarkdownFile(update.mdPath, update.content);
          if (kind === "entity") {
            await requestEntityCanonicalIdReconcile(stateDir);
          }
        }
        });
        // The redirect rewrote an on-disk memory file out-of-band (not through a
        // StorageManager mutation). Bump the corpus sentinel per write so a warm
        // hot-memories cache rescans — mid-batch too, never serving pre-redirect
        // content (#1902). Only recall-corpus files affect that cache.
        if (isRecallCorpusMarkdown(update.mdPath, memoryDir)) {
          bumpMemoryCorpusVersionForDir(memoryDir);
        }
      } catch (err) {
        writeFailCount++;
        const msg = `redirect write failed for ${update.mdPath}: ${err instanceof Error ? err.message : String(err)}`;
        log.error(`[binary-lifecycle] ${msg}`);
        errors.push(msg);
      }
    }

    if (writeFailCount > 0) {
      if (!dryRun) {
        asset.status = "error";
      }
      log.warn(
        `[binary-lifecycle] redirect write failure for ${asset.originalPath}: ` +
          `${writeFailCount} write failure(s) — status set to error`,
      );
      continue;
    }

    const verifyResult = await countRemainingLocalReferences(
      memoryDir,
      asset,
      assetAbsolute,
      mdFiles,
      readMarkdownFile,
    );
    if (verifyResult.errors.length > 0 || verifyResult.remaining > 0) {
asset.status = "error";
// Failed verify must not read as a completed redirect (#2471); this also
// clears stale stamps written by manifests from before that fix.
delete asset.redirectedAt;
      for (const msg of verifyResult.errors) {
        log.error(`[binary-lifecycle] ${msg}`);
        errors.push(msg);
      }
      if (verifyResult.remaining > 0) {
        const msg = `redirect verification failed for ${asset.originalPath}: ${verifyResult.remaining} local reference(s) remain`;
        log.warn(`[binary-lifecycle] ${msg}`);
        errors.push(msg);
      }
      continue;
    }
    asset.status = "redirected";
asset.redirectedAt = new Date().toISOString();
    redirected++;
    log.info(`[binary-lifecycle] redirected: ${asset.originalPath}`);
  }

  return { redirected, errors };
}

async function countRemainingLocalReferences(
  memoryDir: string,
  asset: BinaryAssetRecord,
  assetAbsolute: string,
  mdFiles: string[],
  readMarkdownFile: ReadMarkdownFile,
): Promise<{ remaining: number; errors: string[] }> {
  let remaining = 0;
  const errors: string[] = [];

  for (const mdPath of mdFiles) {
    try {
      const content = await readMarkdownFile(mdPath);
      const pattern = markdownReferencePattern(asset, assetAbsolute, mdPath);
      if (pattern.test(content)) {
        remaining++;
      }
    } catch (err) {
      errors.push(`redirect verification failed for ${mdPath}: ${err instanceof Error ? err.message : String(err)}`);
    }
  }

  return { remaining, errors };
}

function markdownReferencePattern(
  asset: BinaryAssetRecord,
  assetAbsolute: string,
  mdPath: string,
): RegExp {
  const mdDir = path.dirname(mdPath);
  const candidates = new Set<string>();
  const addCandidate = (candidate: string): void => {
    const normalized = candidate.split(path.sep).join("/");
    if (normalized.length === 0) return;
    candidates.add(normalized);
    const isParentTraversal = normalized === ".." || normalized.startsWith("../");
    if (!normalized.startsWith("./") && !normalized.startsWith("/") && !isParentTraversal) {
      candidates.add(`./${normalized}`);
    }
  };

  // Markdown links may be file-relative to the note or memory-root-relative in
  // Remnic notes. Match both forms so verification cannot miss a live local ref.
  addCandidate(path.relative(mdDir, assetAbsolute));
  const originalPath = asset.originalPath.split(path.sep).join("/");
  const originalAsFileRelative = path.resolve(mdDir, ...originalPath.split("/"));
  if (path.resolve(originalAsFileRelative) === path.resolve(assetAbsolute)) {
    addCandidate(originalPath);
  }
  addCandidate(`/${originalPath}`);

  const alternatives = [...candidates]
    .sort((a, b) => b.length - a.length)
    .map(escapeRegex)
    .join("|");

  return new RegExp(`(!?\\[[^\\]]*\\]\\()(${alternatives})(\\))`, "g");
}

async function stageClean(
  memoryDir: string,
  assets: BinaryAssetRecord[],
  backend: BinaryStorageBackend,
  gracePeriodDays: number,
  log: PipelineLogger,
  dryRun: boolean,
  forceClean: boolean,
): Promise<{ cleaned: number; errors: string[] }> {
  let cleaned = 0;
  const errors: string[] = [];
  const now = Date.now();
  const graceMs = gracePeriodDays * 24 * 60 * 60 * 1000;

  // Clean only assets that have been redirected (markdown refs already rewritten).
  // Mirrored-only assets must NOT be cleaned — their markdown refs still point
  // to the local file, so deletion would break links.
  const candidates = assets.filter(
    (a) => a.status === "redirected",
  );

  for (const asset of candidates) {
    const mirroredMs = new Date(asset.mirroredAt).getTime();
    if (!Number.isFinite(mirroredMs)) {
      const msg = `clean blocked for ${asset.originalPath}: manifest mirroredAt is invalid`;
      log.error(`[binary-lifecycle] ${msg}`);
      errors.push(msg);
      if (!dryRun) {
        asset.status = "error";
      }
      continue;
    }
    const ageMs = now - mirroredMs;

    if (!forceClean && ageMs < graceMs) {
      // Not yet past grace period.
      continue;
    }

    const fullPath = resolveManifestAssetPath(memoryDir, asset.originalPath);
    if (fullPath === null) {
      const msg = `clean blocked for ${asset.originalPath}: manifest path is outside memoryDir`;
      log.error(`[binary-lifecycle] ${msg}`);
      errors.push(msg);
      if (!dryRun) {
        asset.status = "error";
      }
      continue;
    }

    let remoteExists: boolean;
    try {
      remoteExists = await backend.exists(asset.mirroredPath);
    } catch (err) {
      const msg = `clean blocked for ${asset.originalPath}: failed to verify mirrored copy: ${err instanceof Error ? err.message : String(err)}`;
      log.error(`[binary-lifecycle] ${msg}`);
      errors.push(msg);
      continue;
    }

    if (!remoteExists) {
      const msg = `clean blocked for ${asset.originalPath}: mirrored copy is missing`;
      log.error(`[binary-lifecycle] ${msg}`);
      errors.push(msg);
      continue;
    }

    try {
      const currentHash = await hashFile(fullPath);
      if (currentHash !== asset.contentHash) {
        const msg = `clean blocked for ${asset.originalPath}: local content hash does not match manifest`;
        log.warn(`[binary-lifecycle] ${msg}`);
        errors.push(msg);
        continue;
      }
      if (!dryRun) {
        await fsp.unlink(fullPath);
        asset.status = "cleaned";
        asset.cleanedAt = new Date().toISOString();
      }
      cleaned++;
      log.info(`[binary-lifecycle] cleaned: ${asset.originalPath}${dryRun ? " [dry-run]" : ""}`);
    } catch (err) {
      if ((err as NodeJS.ErrnoException).code === "ENOENT") {
        // Already gone — mark as cleaned.
        if (!dryRun) {
          asset.status = "cleaned";
          asset.cleanedAt = new Date().toISOString();
          cleaned++;
        }
      } else {
        const msg = `clean failed for ${asset.originalPath}: ${err instanceof Error ? err.message : String(err)}`;
        log.error(`[binary-lifecycle] ${msg}`);
        errors.push(msg);
      }
    }
  }

  return { cleaned, errors };
}

// ---------------------------------------------------------------------------
// Markdown file discovery
// ---------------------------------------------------------------------------

async function findMarkdownFiles(dir: string): Promise<string[]> {
  const results: string[] = [];

  async function walk(current: string): Promise<void> {
    let entries: import("node:fs").Dirent[];
    try {
      entries = await fsp.readdir(current, { withFileTypes: true });
    } catch {
      return;
    }
    for (const entry of entries) {
      const full = path.join(current, entry.name);
      if (entry.isDirectory()) {
        if (entry.name === ".binary-lifecycle") continue;
        await walk(full);
      } else if (entry.isFile() && entry.name.endsWith(".md")) {
        results.push(full);
      }
    }
  }

  await walk(dir);
  return results;
}

// ---------------------------------------------------------------------------
// Main pipeline entry point
// ---------------------------------------------------------------------------

/**
 * Run the binary lifecycle pipeline: scan, mirror, redirect, clean.
 */
export async function runBinaryLifecyclePipeline(
  memoryDir: string,
  config: BinaryLifecycleConfig,
  backend: BinaryStorageBackend,
  log: PipelineLogger,
  opts?: PipelineOptions,
): Promise<PipelineResult> {
  validateBinaryLifecycleConfig(config);

  const dryRun = opts?.dryRun ?? false;
  const forceClean = opts?.forceClean ?? false;

  if (config.enabled === false) {
    return {
      scanned: 0,
      mirrored: 0,
      redirected: 0,
      cleaned: 0,
      errors: [],
      dryRun,
    };
  }

  const manifest = await readManifest(memoryDir);

  // Stage 0: Scan
  const newPaths = await scanForBinaries(memoryDir, config, manifest);
  const scanned = newPaths.length;

  // Stage 1: Mirror
  const mirrorResult = await stageMirror(
    memoryDir,
    newPaths,
    backend,
    manifest.assets,
    log,
    dryRun,
  );

  // Stage 2: Redirect
  const redirectResult = await stageRedirect(
    memoryDir,
    manifest.assets,
    log,
    dryRun,
    opts?.readMarkdownFile ?? ((filePath: string) => fsp.readFile(filePath, "utf-8")),
    opts?.writeMarkdownFile ?? ((filePath: string, content: string) => fsp.writeFile(filePath, content, "utf-8")),
  );

  // Stage 3: Clean
  const cleanResult = await stageClean(
    memoryDir,
    manifest.assets,
    backend,
    config.gracePeriodDays,
    log,
    dryRun,
    forceClean,
  );

  // Persist manifest (unless dry-run).
  manifest.lastScanAt = new Date().toISOString();
  if (!dryRun) {
    await writeManifest(memoryDir, manifest);
  }

  const allErrors = [
    ...mirrorResult.errors,
    ...redirectResult.errors,
    ...cleanResult.errors,
  ];

  return {
    scanned,
    mirrored: mirrorResult.mirrored,
    redirected: redirectResult.redirected,
    cleaned: cleanResult.cleaned,
    errors: allErrors,
    dryRun,
  };
}

export function splitMarkdownFrontmatter(content: string): { fields: string; body: string } | null {
  if (!content.startsWith("---\n")) return null;
  const end = content.indexOf("\n---", 4);
  if (end === -1) return null;
  const after = end + "\n---".length;
  const body = content.startsWith("\n", after) ? content.slice(after + 1) : content.slice(after);
  return { fields: content.slice(4, end), body };
}

export function parseFrontmatterFields(content: string): Record<string, string> {
  const split = splitMarkdownFrontmatter(content);
  if (!split) return {};
  const fields: Record<string, string> = {};
  for (const line of split.fields.split("\n")) {
    const colonIdx = line.indexOf(":");
    if (colonIdx === -1) continue;
    fields[line.slice(0, colonIdx).trim()] = line.slice(colonIdx + 1).trim();
  }
  return fields;
}

/**
 * @remnic/core — Codex Memory Extension Publisher
 *
 * Writes Remnic instructions into ~/.codex/memories_extensions/remnic/
 * so the Codex agent can discover and use Remnic memories during its
 * consolidation phase.
 */

import fs from "node:fs";
import os from "node:os";
import path from "node:path";

import type {
  MemoryExtensionPublisher,
  PublishContext,
  PublishResult,
  PublisherCapabilities,
} from "./types.js";

import {
  REMNIC_SEMANTIC_OVERVIEW,
  REMNIC_CITATION_FORMAT,
  REMNIC_MCP_TOOL_INVENTORY,
  REMNIC_RECALL_DECISION_RULES,
} from "./shared-instructions.js";
import { readEnvVar, resolveHomeDir } from "../runtime/env.js";

/** Folder name Remnic installs its extension under inside memories_extensions/. */
const REMNIC_EXTENSION_DIR_NAME = "remnic";

function resolveEnvHome(env?: NodeJS.ProcessEnv): string {
  if (env === undefined) return resolveHomeDir();
  return env.HOME?.trim() || env.USERPROFILE?.trim() || os.homedir();
}

function expandTildeWithHome(input: string, homeDir: string): string {
  if (input === "~") return homeDir;
  if (input.startsWith("~/") || input.startsWith("~\\")) {
    return path.join(homeDir, input.slice(2));
  }
  return input;
}

function normalizeHostRoot(input: string, homeDir: string): string {
  return path.resolve(expandTildeWithHome(input.trim(), homeDir));
}

/**
 * Codex-specific publisher that knows the Codex extension layout:
 *   ~/.codex/memories_extensions/remnic/instructions.md
 */
export class CodexMemoryExtensionPublisher implements MemoryExtensionPublisher {
  readonly hostId = "codex";

  static readonly capabilities: PublisherCapabilities = {
    isStub: false,
    instructionsMd: true,
    skillsFolder: false,
    citationFormat: true,
    readPathTemplate: true,
  };

  async resolveExtensionRoot(
    env?: NodeJS.ProcessEnv,
  ): Promise<string> {
    const homeDir = resolveEnvHome(env);
    const codexHomeInput = env === undefined
      ? readEnvVar("CODEX_HOME")?.trim()
      : env.CODEX_HOME?.trim();
    const codexHome = codexHomeInput
      ? normalizeHostRoot(codexHomeInput, homeDir)
      : path.resolve(homeDir, ".codex");
    return path.join(codexHome, "memories_extensions", REMNIC_EXTENSION_DIR_NAME);
  }

  async isHostAvailable(): Promise<boolean> {
    try {
      const home = readEnvVar("CODEX_HOME")?.trim() ||
        path.join(resolveHomeDir(), ".codex");
      return fs.existsSync(home);
    } catch {
      return false;
    }
  }

  async renderInstructions(ctx: PublishContext): Promise<string> {
    const memDir = ctx.config.memoryDir;
    const ns = ctx.config.namespace ?? "default";

    const sections: string[] = [
      `# Remnic Memory Extension for Codex\n`,
      `This document tells you how to use Remnic as an authoritative local ` +
        `memory source. Remnic is a local-first, file-backed memory system. ` +
        `All Remnic content lives on disk as plain Markdown.\n`,
      REMNIC_SEMANTIC_OVERVIEW,
      `## Where Remnic Content Lives\n\n` +
        `Memory base directory: \`${memDir}\`\n\n` +
        `Namespace: \`${ns}\`\n\n` +
        `Under the base directory, memories are organized by namespace:\n\n` +
        "```\n" +
        `${memDir}/<namespace>/\n` +
        `  MEMORY.md               # compact top-of-mind memory\n` +
        `  memory_summary.md       # optional longer summary\n` +
        `  skills/\n` +
        `    <skill-name>/SKILL.md # reusable workflows\n` +
        `  rollout_summaries/\n` +
        `    *.md                  # per-session rollup notes\n` +
        "```\n",
      REMNIC_CITATION_FORMAT,
      REMNIC_MCP_TOOL_INVENTORY,
      REMNIC_RECALL_DECISION_RULES,
      `## Sandboxing Rules (Codex Phase-2)\n\n` +
        `When running inside the Codex phase-2 consolidation sandbox:\n\n` +
        `- **No network.** Do not attempt HTTP calls or MCP connections.\n` +
        `- **No CLI invocation.** Do not shell out to \`remnic\` or \`engram\`.\n` +
        `- **No MCP tool calls.** Use filesystem reads only.\n` +
        `- **Local writes** are allowed only where Codex's sandbox policy permits.\n` +
        `- **Respect missing files.** If a file does not exist, move on silently.\n`,
    ];

    return sections.join("\n");
  }

  async publish(ctx: PublishContext): Promise<PublishResult> {
    const extensionRoot = await this.resolveExtensionRoot();
    const instructionsPath = path.join(extensionRoot, "instructions.md");
    const filesWritten: string[] = [];
    const skipped: string[] = [];

    ctx.log.info(`Publishing Codex memory extension to ${extensionRoot}`);

    // Ensure the extension root exists.
    fs.mkdirSync(extensionRoot, { recursive: true });

    // Render and write instructions.md using atomic write (temp + rename).
    // Per CLAUDE.md #54: never delete before write in file replace operations.
    const content = await this.renderInstructions(ctx);
    const tmpPath = `${instructionsPath}.tmp-${process.pid}-${Date.now()}`;

    try {
      fs.writeFileSync(tmpPath, content, "utf-8");
      fs.renameSync(tmpPath, instructionsPath);
      filesWritten.push(instructionsPath);
      ctx.log.info(`Wrote ${instructionsPath}`);
    } catch (err) {
      // Clean up temp file on failure.
      try {
        if (fs.existsSync(tmpPath)) {
          fs.unlinkSync(tmpPath);
        }
      } catch {
        // swallow cleanup error
      }
      throw err;
    }

    return {
      hostId: this.hostId,
      extensionRoot,
      filesWritten,
      skipped,
    };
  }

  async unpublish(): Promise<void> {
    const extensionRoot = await this.resolveExtensionRoot();
    if (fs.existsSync(extensionRoot)) {
      fs.rmSync(extensionRoot, { recursive: true, force: true });
    }
  }
}

