/**
 * Enrichment pipeline types (issue #365).
 *
 * Defines the provider interface, candidate shape, pipeline config,
 * and result types for the external enrichment subsystem.
 */

import type { ImportanceLevel, MemoryCategory } from "../types.js";

// ---------------------------------------------------------------------------
// Provider config & interface
// ---------------------------------------------------------------------------

export type EnrichmentCostTier = "free" | "cheap" | "expensive";

export interface EnrichmentProviderConfig {
  id: string;
  enabled: boolean;
  costTier: EnrichmentCostTier;
  rateLimit?: { maxPerMinute: number; maxPerDay: number };
}

export interface EnrichmentCandidate {
  text: string;
  source: string;
  sourceUrl?: string;
  confidence: number;
  category: MemoryCategory;
  tags?: string[];
}

export interface EnrichmentProvider {
  readonly id: string;
  readonly costTier: EnrichmentCostTier;
  enrich(entity: EntityEnrichmentInput): Promise<EnrichmentCandidate[]>;
  isAvailable(): Promise<boolean>;
}

// ---------------------------------------------------------------------------
// Entity enrichment input
// ---------------------------------------------------------------------------

export interface EntityEnrichmentInput {
  name: string;
  type: string;
  knownFacts: string[];
  importanceLevel: ImportanceLevel;
}

// ---------------------------------------------------------------------------
// Pipeline result
// ---------------------------------------------------------------------------

export interface EnrichmentResult {
  entityName: string;
  provider: string;
  candidatesFound: number;
  candidatesAccepted: number;
  candidatesRejected: number;
  acceptedCandidates: EnrichmentCandidate[];
  elapsed: number;
}

// ---------------------------------------------------------------------------
// Pipeline config
// ---------------------------------------------------------------------------

export interface EnrichmentPipelineConfig {
  enabled: boolean;
  providers: EnrichmentProviderConfig[];
  importanceThresholds: {
    critical: string[];
    high: string[];
    normal: string[];
    low: string[];
  };
  maxCandidatesPerEntity: number;
  autoEnrichOnCreate: boolean;
  scheduleIntervalMs: number;
}

/**
 * Build a default (disabled) pipeline config. Every consumer that needs a
 * config object should call this rather than duplicating the defaults.
 */
export function defaultEnrichmentPipelineConfig(): EnrichmentPipelineConfig {
  return {
    enabled: false,
    providers: [],
    importanceThresholds: {
      critical: [],
      high: [],
      normal: [],
      low: [],
    },
    maxCandidatesPerEntity: 20,
    autoEnrichOnCreate: false,
    scheduleIntervalMs: 3_600_000,
  };
}

/**
 * Enrichment provider registry (issue #365).
 *
 * Central registry for enrichment providers. Providers register themselves
 * at startup; the pipeline queries the registry to determine which providers
 * to run for a given importance tier.
 */

import type { ImportanceLevel } from "../types.js";
import type {
  EnrichmentPipelineConfig,
  EnrichmentProvider,
} from "./types.js";

export class EnrichmentProviderRegistry {
  private readonly providers = new Map<string, EnrichmentProvider>();

  /** Register a provider. Overwrites any existing provider with the same id. */
  register(provider: EnrichmentProvider): void {
    this.providers.set(provider.id, provider);
  }

  /** Look up a single provider by id. */
  get(id: string): EnrichmentProvider | undefined {
    return this.providers.get(id);
  }

  /**
   * Return all registered providers whose id appears in the config's
   * `providers` list with `enabled: true`.
   */
  listEnabled(config: EnrichmentPipelineConfig): EnrichmentProvider[] {
    const enabledIds = new Set(
      config.providers
        .filter((p) => p.enabled)
        .map((p) => p.id),
    );
    const result: EnrichmentProvider[] = [];
    for (const [id, provider] of this.providers.entries()) {
      if (enabledIds.has(id)) {
        result.push(provider);
      }
    }
    return result;
  }

  /**
   * Return providers that should run for a given importance level.
   * Providers are resolved from `config.importanceThresholds[level]` and
   * filtered to only those that are both registered and enabled.
   */
  getForImportance(
    level: ImportanceLevel,
    config: EnrichmentPipelineConfig,
  ): EnrichmentProvider[] {
    // "trivial" entities never get enrichment providers
    if (level === "trivial") return [];

    const thresholds = config.importanceThresholds;
    const providerIds: string[] =
      level === "critical"
        ? thresholds.critical
        : level === "high"
          ? thresholds.high
          : level === "normal"
            ? thresholds.normal
            : thresholds.low;

    const enabledIds = new Set(
      config.providers
        .filter((p) => p.enabled)
        .map((p) => p.id),
    );

    const result: EnrichmentProvider[] = [];
    for (const id of providerIds) {
      if (!enabledIds.has(id)) continue;
      const provider = this.providers.get(id);
      if (provider) {
        result.push(provider);
      }
    }
    return result;
  }
}

/**
 * Web search enrichment provider stub (issue #365).
 *
 * A basic provider backed by web search. Since this is opt-in and we do not
 * want to hard-code an API key, the provider accepts an optional `searchFn`
 * injection point. When no search function is configured it returns empty
 * results, making it safe to register unconditionally.
 */

import type {
  EnrichmentCandidate,
  EnrichmentCostTier,
  EnrichmentProvider,
  EntityEnrichmentInput,
} from "./types.js";

export type WebSearchFn = (query: string) => Promise<string[]>;

export interface WebSearchProviderOptions {
  /**
   * Injected search function. Each returned string is treated as a raw
   * snippet. When `undefined` the provider returns empty results.
   */
  searchFn?: WebSearchFn;
}

export class WebSearchProvider implements EnrichmentProvider {
  readonly id = "web-search";
  readonly costTier: EnrichmentCostTier = "cheap";

  private readonly searchFn: WebSearchFn | undefined;

  constructor(options: WebSearchProviderOptions = {}) {
    this.searchFn = options.searchFn;
  }

  async isAvailable(): Promise<boolean> {
    return this.searchFn !== undefined;
  }

  async enrich(entity: EntityEnrichmentInput): Promise<EnrichmentCandidate[]> {
    if (!this.searchFn) return [];

    const query = `${entity.name} ${entity.type}`;
    const snippets = await this.searchFn(query);

    return snippets
      .filter((s) => typeof s === "string" && s.trim().length > 0)
      .map((snippet) => ({
        text: snippet.trim(),
        source: this.id,
        sourceUrl: undefined,
        confidence: 0.5,
        category: "fact" as const,
        tags: ["web-search"],
      }));
  }
}

/**
 * Enrichment pipeline orchestrator (issue #365).
 *
 * For each entity, determines the importance tier, resolves the providers
 * to run, executes them in sequence (respecting rate limits), tags
 * candidates, and caps at `maxCandidatesPerEntity`.
 *
 * Accepted candidates are returned in each `EnrichmentResult` via the
 * `acceptedCandidates` field so that callers can persist them.
 */

import type { LoggerBackend } from "../logger.js";
import type { EnrichmentProviderRegistry } from "./provider-registry.js";
import type {
  EnrichmentCandidate,
  EnrichmentPipelineConfig,
  EnrichmentProvider,
  EnrichmentResult,
  EntityEnrichmentInput,
} from "./types.js";

// ---------------------------------------------------------------------------
// Rate-limit tracking
// ---------------------------------------------------------------------------

interface RateLimitBucket {
  minuteCount: number;
  minuteReset: number;
  dayCount: number;
  dayReset: number;
}

const rateBuckets = new Map<string, RateLimitBucket>();

function reserveRateLimitSlot(
  provider: EnrichmentProvider,
  config: EnrichmentPipelineConfig,
): boolean {
  const providerCfg = config.providers.find((p) => p.id === provider.id);
  if (!providerCfg?.rateLimit) return true;

  const now = Date.now();
  let bucket = rateBuckets.get(provider.id);
  if (!bucket) {
    bucket = {
      minuteCount: 0,
      minuteReset: now + 60_000,
      dayCount: 0,
      dayReset: now + 86_400_000,
    };
    rateBuckets.set(provider.id, bucket);
  }

  // Reset windows if expired
  if (now >= bucket.minuteReset) {
    bucket.minuteCount = 0;
    bucket.minuteReset = now + 60_000;
  }
  if (now >= bucket.dayReset) {
    bucket.dayCount = 0;
    bucket.dayReset = now + 86_400_000;
  }

  const { maxPerMinute, maxPerDay } = providerCfg.rateLimit;
  if (bucket.minuteCount >= maxPerMinute || bucket.dayCount >= maxPerDay) {
    return false;
  }

  bucket.minuteCount += 1;
  bucket.dayCount += 1;
  return true;
}

// ---------------------------------------------------------------------------
// Pipeline
// ---------------------------------------------------------------------------

export async function runEnrichmentPipeline(
  entities: EntityEnrichmentInput[],
  registry: EnrichmentProviderRegistry,
  config: EnrichmentPipelineConfig,
  log: LoggerBackend,
): Promise<EnrichmentResult[]> {
  if (!config.enabled) return [];
  if (entities.length === 0) return [];

  const results: EnrichmentResult[] = [];

  for (const entity of entities) {
    const providers = registry.getForImportance(entity.importanceLevel, config);
    const maxCandidates = config.maxCandidatesPerEntity;
    const hasPositiveCandidateBudget = maxCandidates > 0;
    let remainingCandidateBudget = hasPositiveCandidateBudget
      ? maxCandidates
      : Number.POSITIVE_INFINITY;

    for (const provider of providers) {
      if (hasPositiveCandidateBudget && remainingCandidateBudget <= 0) {
        break;
      }

      const start = Date.now();

      // Check availability
      let available: boolean;
      try {
        available = await provider.isAvailable();
      } catch {
        available = false;
      }

      if (!available) {
        log.debug?.(
          `enrichment: skipping provider ${provider.id} for ${entity.name} — unavailable`,
        );
        results.push({
          entityName: entity.name,
          provider: provider.id,
          candidatesFound: 0,
          candidatesAccepted: 0,
          candidatesRejected: 0,
          acceptedCandidates: [],
          elapsed: Date.now() - start,
        });
        continue;
      }

      // Reserve quota before the awaited provider call so concurrent pipelines
      // cannot all pass the same pre-await rate-limit check.
      if (!reserveRateLimitSlot(provider, config)) {
        log.debug?.(
          `enrichment: skipping provider ${provider.id} for ${entity.name} — rate limited`,
        );
        results.push({
          entityName: entity.name,
          provider: provider.id,
          candidatesFound: 0,
          candidatesAccepted: 0,
          candidatesRejected: 0,
          acceptedCandidates: [],
          elapsed: Date.now() - start,
        });
        continue;
      }

      // Run provider.
      // Count every attempt toward rate-limit buckets — including failures —
      // because the provider may have consumed external quota before throwing
      // (PR #425 review finding 2).
      let candidates: EnrichmentCandidate[];
      try {
        candidates = await provider.enrich(entity);
      } catch (err) {
        log.error?.(
          `enrichment: provider ${provider.id} failed for ${entity.name}: ${err instanceof Error ? err.message : String(err)}`,
        );
        results.push({
          entityName: entity.name,
          provider: provider.id,
          candidatesFound: 0,
          candidatesAccepted: 0,
          candidatesRejected: 0,
          acceptedCandidates: [],
          elapsed: Date.now() - start,
        });
        continue;
      }

      // Tag each candidate with provider id
      for (const candidate of candidates) {
        candidate.source = provider.id;
      }

      // Cap at maxCandidatesPerEntity across all providers for this entity.
      // 0 means "accept none"; undefined/negative means "no cap".
      let accepted: EnrichmentCandidate[];
      if (maxCandidates === 0) {
        accepted = [];
      } else if (hasPositiveCandidateBudget) {
        accepted = candidates.slice(0, remainingCandidateBudget);
        remainingCandidateBudget -= accepted.length;
      } else {
        accepted = candidates;
      }
      const rejected = candidates.length - accepted.length;

      results.push({
        entityName: entity.name,
        provider: provider.id,
        candidatesFound: candidates.length,
        candidatesAccepted: accepted.length,
        candidatesRejected: rejected,
        acceptedCandidates: accepted,
        elapsed: Date.now() - start,
      });
    }
  }

  return results;
}

/**
 * Enrichment audit trail (issue #365).
 *
 * Append-only JSONL log for every enrichment candidate that was evaluated.
 * Each entry records whether the candidate was accepted or rejected, the
 * provider that produced it, and an optional reason string.
 */

import { mkdir, readFile, appendFile } from "node:fs/promises";
import { existsSync } from "node:fs";
import path from "node:path";

// ---------------------------------------------------------------------------
// Types
// ---------------------------------------------------------------------------

export interface EnrichmentAuditEntry {
  timestamp: string;
  entityName: string;
  provider: string;
  candidateText: string;
  sourceUrl?: string;
  accepted: boolean;
  reason?: string;
}

// ---------------------------------------------------------------------------
// File helpers
// ---------------------------------------------------------------------------

const AUDIT_FILENAME = "enrichment-audit.jsonl";

function auditFilePath(auditDir: string): string {
  return path.join(auditDir, AUDIT_FILENAME);
}

// ---------------------------------------------------------------------------
// Public API
// ---------------------------------------------------------------------------

/**
 * Append a single audit entry to the JSONL log. Creates the audit directory
 * and file if they do not exist.
 */
export async function appendAuditEntry(
  auditDir: string,
  entry: EnrichmentAuditEntry,
): Promise<void> {
  await mkdir(auditDir, { recursive: true });
  const line = JSON.stringify(entry) + "\n";
  await appendFile(auditFilePath(auditDir), line, "utf-8");
}

/**
 * Read the audit log and return entries, optionally filtered to entries at
 * or after `since` (ISO 8601 timestamp, half-open interval).
 */
export async function readAuditLog(
  auditDir: string,
  since?: string,
): Promise<EnrichmentAuditEntry[]> {
  const filePath = auditFilePath(auditDir);
  if (!existsSync(filePath)) return [];
  const sinceMs = since === undefined ? undefined : Date.parse(since);
  if (since !== undefined && !Number.isFinite(sinceMs)) {
    throw new Error(`Invalid enrichment audit since timestamp: ${since}`);
  }

  const raw = await readFile(filePath, "utf-8");
  const entries: EnrichmentAuditEntry[] = [];

  for (const line of raw.split("\n")) {
    const trimmed = line.trim();
    if (trimmed.length === 0) continue;
    try {
      const parsed: unknown = JSON.parse(trimmed);
      if (
        typeof parsed === "object" &&
        parsed !== null &&
        "timestamp" in parsed &&
        "entityName" in parsed
      ) {
        const entry = parsed as EnrichmentAuditEntry;
        if (typeof entry.timestamp !== "string") continue;
        const entryMs = Date.parse(entry.timestamp);
        if (!Number.isFinite(entryMs)) continue;
        if (sinceMs !== undefined && entryMs < sinceMs) continue;
        entries.push(entry);
      }
    } catch {
      // Skip malformed lines
    }
  }

  return entries;
}

/**
 * Wearables CLI runner — one implementation shared by every CLI host
 * (`remnic wearables ...` and `openclaw engram wearables ...`), so the
 * surfaces never fork (same rule as the recall-explain renderers).
 *
 * Flag validation is strict: every value-taking flag requires a value,
 * unknown flags error with the valid list, and invalid values reject
 * loudly (CLAUDE.md rules 14 + 51).
 */

import { WearablesInputError } from "./errors.js";
import { builtInConnectorPackageSpecifier } from "./registry.js";
import type { WearablesService } from "./service.js";
import type { WearableSyncSummary } from "./types.js";

export interface WearablesCliIo {
  stdout: { write(chunk: string): unknown };
  stderr: { write(chunk: string): unknown };
}

const USAGE = `Usage: wearables <command> [options]

Commands:
  status                         Show configured sources, connectors, last sync
  check <source>                 Verify credentials/connectivity for a source
  sync [options]                 Pull + clean + store transcripts (and memories)
    --source <id>                Only this source (default: all enabled)
    --date <YYYY-MM-DD>          Exactly this day
    --days <n>                   Lookback window ending today (default 2)
    --force-memories             Re-extract memories for unchanged days
  transcript --date <YYYY-MM-DD> [--source <id>]
                                 Print the stored day transcript(s)
  search <query> [options]       Search stored transcripts
    --source <id>  --from <date>  --to <date>  --limit <n>
  memories [options]             List memories created from transcripts
    --source <id>  --date <date>  --limit <n>
  fuse <YYYY-MM-DD>              Fuse enabled sources' transcripts for a day
  fused <YYYY-MM-DD>             List fused conversations for a day
  speakers list                  Show the speaker registry
  speakers self <name>           Set the wearer's display name
  speakers set <source> <key> <name> [--self]
                                 Map a provider speaker label to a name
  speakers remove <source> <key> Remove a speaker mapping
  corrections list               Show correction rules (config + state)
  corrections add <match> <replace> [--regex] [--case-sensitive] [--source <id>]
                                 Add a transcript correction rule
  corrections remove <index>     Remove a state correction rule by index

Add --json to status/sync/search/memories for machine-readable output.
`;

interface ParsedFlags {
  flags: Map<string, string | true>;
  positional: string[];
}

/** Flags that take a value (everything else is boolean). */
const VALUE_FLAGS = new Set([
  "--source",
  "--date",
  "--days",
  "--from",
  "--to",
  "--limit",
]);
const BOOLEAN_FLAGS = new Set([
  "--json",
  "--force-memories",
  "--regex",
  "--case-sensitive",
  "--self",
]);

function parseFlags(args: string[]): ParsedFlags {
  const flags = new Map<string, string | true>();
  const positional: string[] = [];
  for (let index = 0; index < args.length; index++) {
    const arg = args[index];
    if (!arg.startsWith("--")) {
      positional.push(arg);
      continue;
    }
    if (BOOLEAN_FLAGS.has(arg)) {
      flags.set(arg, true);
      continue;
    }
    if (VALUE_FLAGS.has(arg)) {
      const value = args[index + 1];
      if (value === undefined || value.startsWith("--")) {
        throw new WearablesInputError(`${arg} requires a value`);
      }
      flags.set(arg, value);
      index++;
      continue;
    }
    throw new WearablesInputError(
      `unknown flag '${arg}' — valid flags: ${[...VALUE_FLAGS, ...BOOLEAN_FLAGS].join(", ")}`,
    );
  }
  return { flags, positional };
}

function flagString(parsed: ParsedFlags, name: string): string | undefined {
  const value = parsed.flags.get(name);
  return typeof value === "string" ? value : undefined;
}

function flagInt(parsed: ParsedFlags, name: string): number | undefined {
  const value = flagString(parsed, name);
  if (value === undefined) return undefined;
  const parsedValue = Number(value);
  if (
    !Number.isFinite(parsedValue) ||
    !Number.isInteger(parsedValue) ||
    parsedValue < 1
  ) {
    throw new WearablesInputError(`${name} expects a positive integer (got '${value}')`);
  }
  return parsedValue;
}

function renderSyncSummary(summary: WearableSyncSummary): string {
  const lines = [
    `${summary.source}: ${summary.conversations} conversation${summary.conversations === 1 ? "" : "s"} across ${summary.days.length} day${summary.days.length === 1 ? "" : "s"} (${summary.days.join(", ")})`,
    `  segments kept/dropped:  ${summary.segmentsKept}/${summary.segmentsDropped}`,
    `  redactions applied:     ${summary.redactions}`,
    `  corrections applied:    ${summary.correctionsApplied}`,
    `  transcripts written:    ${summary.transcriptsWritten.length > 0 ? summary.transcriptsWritten.join(", ") : "(none — unchanged)"}`,
    `  memories created:       ${summary.memoriesCreated} (skipped ${summary.memoriesSkipped})`,
  ];
  if (summary.memoriesPromoted > 0) {
    lines.push(`  memories promoted:      ${summary.memoriesPromoted}`);
  }
  if (summary.memoriesDemoted > 0) {
    lines.push(`  memories demoted:       ${summary.memoriesDemoted}`);
  }
  if (summary.memoriesBlocked > 0) {
    lines.push(`  memories blocked:       ${summary.memoriesBlocked}`);
  }
  if (summary.nativeMemoriesImported > 0) {
    lines.push(`  native memories queued: ${summary.nativeMemoriesImported}`);
  }
  for (const warning of summary.warnings) {
    lines.push(`  warning: ${warning}`);
  }
  return lines.join("\n");
}

/**
 * Run a wearables CLI command. Returns a process exit code; all output
 * goes through `io`.
 */
export async function runWearablesCliCommand(
  service: WearablesService,
  args: string[],
  io: WearablesCliIo,
): Promise<number> {
  const [command, ...rest] = args;
  try {
    switch (command) {
      case undefined:
      case "help":
      case "--help": {
        io.stdout.write(USAGE);
        return command === undefined ? 1 : 0;
      }
      case "status": {
        const parsed = parseFlags(rest);
        const status = await service.status();
        if (parsed.flags.has("--json")) {
          io.stdout.write(`${JSON.stringify(status, null, 2)}\n`);
          return 0;
        }
        io.stdout.write(
          `Wearables: ${status.enabled ? "enabled" : "disabled"} (timezone ${status.timezone})\n`,
        );
        if (status.sources.length === 0) {
          io.stdout.write(
            "No sources configured. Add wearables.sources.<id> to the plugin config.\n",
          );
          return 0;
        }
        for (const source of status.sources) {
          io.stdout.write(
            `  ${source.source} (${source.displayName}): ${source.enabled ? "enabled" : "disabled"}, ` +
              `connector ${source.connectorInstalled ? "installed" : `MISSING — npm install ${builtInConnectorPackageSpecifier(source.source)}`}, ` +
              `memoryMode ${source.memoryMode}, ` +
              `${source.transcriptDays} transcript day${source.transcriptDays === 1 ? "" : "s"}, ` +
              `last sync ${source.lastSyncAt ?? "never"}\n`,
          );
        }
        return 0;
      }
      case "check": {
        const [sourceId] = rest;
        if (!sourceId) {
          throw new WearablesInputError("check requires a source id (e.g. wearables check limitless)");
        }
        const result = await service.checkAuth(sourceId);
        io.stdout.write(
          result.ok
            ? `${sourceId}: OK${result.detail ? ` — ${result.detail}` : ""}\n`
            : `${sourceId}: FAILED${result.detail ? ` — ${result.detail}` : ""}\n`,
        );
        return result.ok ? 0 : 1;
      }
      case "sync": {
        const parsed = parseFlags(rest);
        if (parsed.positional.length > 0) {
          throw new WearablesInputError(
            `unexpected argument '${parsed.positional[0]}' — sync takes flags only`,
          );
        }
        const summaries = await service.sync({
          source: flagString(parsed, "--source"),
          date: flagString(parsed, "--date"),
          days: flagInt(parsed, "--days"),
          forceMemories: parsed.flags.has("--force-memories"),
        });
        if (parsed.flags.has("--json")) {
          io.stdout.write(`${JSON.stringify({ summaries }, null, 2)}\n`);
          return 0;
        }
        for (const summary of summaries) {
          io.stdout.write(`${renderSyncSummary(summary)}\n`);
        }
        io.stdout.write("OK\n");
        return 0;
      }
      case "transcript": {
        const parsed = parseFlags(rest);
        const date = flagString(parsed, "--date");
        if (!date) {
          throw new WearablesInputError("transcript requires --date <YYYY-MM-DD>");
        }
        const views = await service.dayTranscript(date, flagString(parsed, "--source"));
        if (views.length === 0) {
          io.stderr.write(`No stored transcripts for ${date}.\n`);
          return 1;
        }
        for (const view of views) {
          if (views.length > 1) {
            io.stdout.write(`\n===== ${view.source} — ${view.date} =====\n\n`);
          }
          if (view.overlapsWith.length > 0) {
            io.stdout.write(
              `(also recorded by: ${view.overlapsWith.join(", ")})\n\n`,
            );
          }
          io.stdout.write(`${view.body}\n`);
        }
        return 0;
      }
      case "search": {
        const parsed = parseFlags(rest);
        const query = parsed.positional.join(" ").trim();
        if (query.length === 0) {
          throw new WearablesInputError("search requires a query");
        }
        const results = await service.searchTranscripts(query, {
          source: flagString(parsed, "--source"),
          from: flagString(parsed, "--from"),
          to: flagString(parsed, "--to"),
          limit: flagInt(parsed, "--limit"),
        });
        if (parsed.flags.has("--json")) {
          io.stdout.write(`${JSON.stringify({ results }, null, 2)}\n`);
          return 0;
        }
        if (results.length === 0) {
          io.stdout.write("No matches.\n");
          return 0;
        }
        for (const result of results) {
          io.stdout.write(
            `${result.source} ${result.date}  ${result.snippet}\n`,
          );
        }
        if (results.some((result) => result.backend === "scan")) {
          io.stdout.write(
            "(search index unavailable — results from bounded text scan)\n",
          );
        }
        return 0;
      }
      case "memories": {
        const parsed = parseFlags(rest);
        const memories = await service.transcriptMemories({
          source: flagString(parsed, "--source"),
          date: flagString(parsed, "--date"),
          limit: flagInt(parsed, "--limit"),
        });
        if (parsed.flags.has("--json")) {
          io.stdout.write(`${JSON.stringify({ memories }, null, 2)}\n`);
          return 0;
        }
        if (memories.length === 0) {
          io.stdout.write("No wearable-derived memories found.\n");
          return 0;
        }
        for (const memory of memories) {
          const status = memory.status === "pending_review" ? " [pending review]" : "";
          io.stdout.write(
            `${memory.id} (${memory.source}${memory.date ? ` ${memory.date}` : ""})${status}\n  ${memory.content.split("\n")[0]}\n`,
          );
        }
        return 0;
      }
      case "speakers": {
        const [action, ...speakerArgs] = rest;
        if (action === "list" || action === undefined) {
          const registry = await service.listSpeakers();
          io.stdout.write(`Self: ${registry.selfName}\n`);
          const entries = Object.entries(registry.speakers);
          if (entries.length === 0) {
            io.stdout.write("No speaker overrides stored.\n");
            return 0;
          }
          for (const [key, override] of entries) {
            io.stdout.write(
              `  ${key} -> ${override.name}${override.isSelf ? " (you)" : ""}\n`,
            );
          }
          return 0;
        }
        if (action === "self") {
          const name = speakerArgs.join(" ").trim();
          if (name.length === 0) {
            throw new WearablesInputError("speakers self requires a name");
          }
          await service.setSelfName(name);
          io.stdout.write(`Self name set to '${name}'.\n`);
          return 0;
        }
        if (action === "set") {
          const parsed = parseFlags(speakerArgs);
          const [sourceId, speakerKey, ...nameParts] = parsed.positional;
          const name = nameParts.join(" ").trim();
          if (!sourceId || !speakerKey || name.length === 0) {
            throw new WearablesInputError(
              "speakers set requires: <source> <speakerKey> <name>",
            );
          }
          await service.setSpeaker(sourceId, speakerKey, name, {
            isSelf: parsed.flags.has("--self"),
          });
          io.stdout.write(`Mapped ${sourceId}:${speakerKey} -> ${name}.\n`);
          io.stdout.write(
            "(re-run `wearables sync --force-memories` to rebuild stored transcripts with the new label)\n",
          );
          return 0;
        }
        if (action === "remove") {
          const [sourceId, speakerKey] = speakerArgs;
          if (!sourceId || !speakerKey) {
            throw new WearablesInputError("speakers remove requires: <source> <speakerKey>");
          }
          await service.removeSpeaker(sourceId, speakerKey);
          io.stdout.write(`Removed mapping for ${sourceId}:${speakerKey}.\n`);
          return 0;
        }
        throw new WearablesInputError(
          `unknown speakers action '${action}' — expected list, self, set, or remove`,
        );
      }
      case "corrections": {
        const [action, ...correctionArgs] = rest;
        if (action === "list" || action === undefined) {
          const { fromConfig, fromState, stateFilePath } = await service.listCorrections();
          if (fromConfig.length === 0 && fromState.length === 0) {
            io.stdout.write("No correction rules configured.\n");
            return 0;
          }
          if (fromConfig.length > 0) {
            io.stdout.write("From config (wearables.corrections):\n");
            fromConfig.forEach((rule, index) => {
              io.stdout.write(`  [config ${index}] ${formatRule(rule)}\n`);
            });
          }
          if (fromState.length > 0) {
            io.stdout.write(`From state (${stateFilePath}):\n`);
            fromState.forEach((rule, index) => {
              io.stdout.write(`  [${index}] ${formatRule(rule)}\n`);
            });
          }
          return 0;
        }
        if (action === "add") {
          const parsed = parseFlags(correctionArgs);
          const [match, replace] = parsed.positional;
          if (match === undefined || replace === undefined) {
            throw new WearablesInputError(
              'corrections add requires: <match> <replace> (quote multi-word values)',
            );
          }
          const sourceFlag = flagString(parsed, "--source");
          await service.addCorrection({
            match,
            replace,
            ...(parsed.flags.has("--regex") ? { regex: true } : {}),
            ...(parsed.flags.has("--case-sensitive") ? { caseInsensitive: false } : {}),
            ...(sourceFlag !== undefined ? { sources: [sourceFlag] } : {}),
          });
          io.stdout.write(`Added correction: ${JSON.stringify(match)} -> ${JSON.stringify(replace)}.\n`);
          return 0;
        }
        if (action === "remove") {
          const [indexRaw] = correctionArgs;
          const index = Number(indexRaw);
          if (
            indexRaw === undefined ||
            !Number.isInteger(index) ||
            index < 0
          ) {
            throw new WearablesInputError("corrections remove requires a non-negative index");
          }
          const removed = await service.removeCorrection(index);
          io.stdout.write(`Removed correction ${formatRule(removed)}.\n`);
          return 0;
        }
        throw new WearablesInputError(
          `unknown corrections action '${action}' — expected list, add, or remove`,
        );
      }
      case "fuse": {
        const parsed = parseFlags(rest);
        const date = flagString(parsed, "--date") ?? parsed.positional[0];
        if (!date) {
          throw new WearablesInputError(
            "fuse requires a date (e.g. wearables fuse 2026-06-10)",
          );
        }
        const result = await service.fuseDay(date);
        if (parsed.flags.has("--json")) {
          io.stdout.write(`${JSON.stringify(result, null, 2)}\n`);
          return 0;
        }
        // `written:false` has two distinct meanings (issue #1849): a genuine
        // idempotent no-op (inputs unchanged) OR a deliberate SKIP — e.g.
        // mixed source timezones — where fusion was refused and any
        // previously-fused artifact for the day was cleared. The JSON path
        // carries `skipped`, but the text path collapsed both into
        // "(unchanged)", hiding a skip (and a possible artifact deletion)
        // behind an idempotent-looking label. Check `skipped` first and emit
        // a distinct skip line; reserve "(unchanged)" for written:false
        // WITHOUT a skip reason. Mirrors the `skipped` field the JSON path
        // serializes.
        if (result.skipped) {
          io.stdout.write(
            `Skipped fusing ${date}: ${result.skipped.reason} — no fused artifact written; any existing fused artifact for the day was cleared.\n`,
          );
        } else {
          io.stdout.write(
            `Fused ${date}: ${result.conversationCount} conversation${result.conversationCount === 1 ? "" : "s"} from ${result.sources.length} source${result.sources.length === 1 ? "" : "s"}.${result.written ? "" : " (unchanged)"}\n`,
          );
        }
        return 0;
      }
      case "fused": {
        const parsed = parseFlags(rest);
        const date = flagString(parsed, "--date") ?? parsed.positional[0];
        if (!date) {
          throw new WearablesInputError(
            "fused requires a date (e.g. wearables fused 2026-06-10)",
          );
        }
        const conversations = await service.fusedConversations(date);
        if (parsed.flags.has("--json")) {
          io.stdout.write(`${JSON.stringify({ date, conversations }, null, 2)}\n`);
          return 0;
        }
        if (conversations.length === 0) {
          io.stdout.write(`No fused conversations for ${date}.\n`);
          return 0;
        }
        for (const conv of conversations) {
          io.stdout.write(
            `${conv.id} ${conv.startIso}${conv.endIso ? ` \u2013 ${conv.endIso}` : ""} (${conv.sources.join(", ")}, ${conv.segments.length} segment${conv.segments.length === 1 ? "" : "s"})\n`,
          );
          for (const disagreement of conv.disagreements) {
            io.stdout.write(
              `  disagreement [${disagreement.kind}] @ ${disagreement.subject}: ${disagreement.candidates.length} candidate${disagreement.candidates.length === 1 ? "" : "s"}\n`,
            );
          }
        }
        return 0;
      }
      default:
        throw new WearablesInputError(
          `unknown wearables command '${command}'\n\n${USAGE}`,
        );
    }
  } catch (err) {
    if (err instanceof WearablesInputError) {
      io.stderr.write(`wearables: ${err.message}\n`);
      return 1;
    }
    throw err;
  }
}

function formatRule(rule: {
  match: string;
  replace: string;
  regex?: boolean;
  caseInsensitive?: boolean;
  sources?: string[];
}): string {
  const parts = [`${JSON.stringify(rule.match)} -> ${JSON.stringify(rule.replace)}`];
  if (rule.regex === true) parts.push("(regex)");
  if (rule.caseInsensitive === false) parts.push("(case-sensitive)");
  if (rule.sources && rule.sources.length > 0) {
    parts.push(`(sources: ${rule.sources.join(", ")})`);
  }
  return parts.join(" ");
}

/**
 * Meetings command group (issue #1900) — extracted from cli.ts so the surface
 * file stays under its structural ceiling. Mirrors the
 * registerResearchStatusCommands / registerCreationLedgerCommands seam: a single
 * registrar wires the `meetings` command (list / show / build) on the parent
 * `engram` command.
 *
 * Every subcommand forwards to the shared runner in meetings/cli.ts so this host
 * CLI and the standalone `remnic` CLI never fork behavior or formatting.
 * Behaviour is identical to the inline registration it replaces — the
 * cli-command-surface contract tests guard against silent drift.
 */

import type { Orchestrator } from "../orchestrator.js";
import type { CliCommand } from "../cli.js";
import { runMeetingsCliCommand } from "../meetings/cli.js";

export function registerMeetingsCommands(cmd: CliCommand, orchestrator: Orchestrator): void {
  const meetingsCmd = cmd
    .command("meetings")
    .description(
      "Retrospective meetings: list records, show one, build (detect + fuse + store) a day",
    );
  const forwardMeetings = async (argv: string[]): Promise<void> => {
    const service = await orchestrator.getMeetingsService();
    const code = await runMeetingsCliCommand(
      { store: service.store, builder: service.builder, config: service.config },
      argv,
      { stdout: process.stdout, stderr: process.stderr },
    );
    if (code !== 0) process.exitCode = code;
  };

  meetingsCmd
    .command("list")
    .description("List meeting records (all days, or one day)")
    .option("--date <date>", "Day to list (YYYY-MM-DD)")
    .option("--json", "JSON output")
    .action(async (...args: unknown[]) => {
      const options = (args[0] ?? {}) as Record<string, unknown>;
      await forwardMeetings([
        "list",
        ...(typeof options.date === "string" && options.date.length > 0
          ? ["--date", options.date]
          : []),
        ...(options.json === true ? ["--json"] : []),
      ]);
    });

  meetingsCmd
    .command("show <meeting-id>")
    .description("Print a stored meeting record")
    .action(async (...args: unknown[]) => {
      await forwardMeetings(["show", String(args[0] ?? "")]);
    });

  meetingsCmd
    .command("build")
    .description("Detect + fuse + store the day's meetings")
    .option("--date <date>", "Day to build (YYYY-MM-DD)")
    .option("--json", "JSON output")
    .action(async (...args: unknown[]) => {
      const options = (args[0] ?? {}) as Record<string, unknown>;
      await forwardMeetings([
        "build",
        ...(typeof options.date === "string" ? ["--date", options.date] : []),
        ...(options.json === true ? ["--json"] : []),
      ]);
    });
}

/**
 * Recall-navigation command group (issue #1956) — extracted from cli.ts so
 * the surface file stays at its structural ceiling (same seam as
 * deep-recall-commands.ts). `remnic navigate expand|traverse <memoryId>`
 * runs through EngramAccessService.recallNavigate — the same single
 * implementation MCP and HTTP call, sharing one renderer.
 */

import type { Orchestrator } from "../orchestrator.js";
import type { CliCommand } from "../cli.js";
import { EngramAccessService } from "../access-service.js";

function parseLimit(raw: unknown): number | undefined {
  if (raw === undefined || raw === null) return undefined;
  const value = typeof raw === "string" ? Number(raw) : raw;
  if (typeof value !== "number" || !Number.isFinite(value) || !Number.isInteger(value) || value < 1) {
    throw new Error(`--limit must be a positive integer; got ${JSON.stringify(raw)}`);
  }
  return value;
}

export function registerRecallNavigationCommands(cmd: CliCommand, orchestrator: Orchestrator): void {
  const run = async (args: unknown[], action: "expand" | "traverse") => {
    const memoryId = String(args[0] ?? "");
    const options = (args[args.length - 1] ?? {}) as Record<string, unknown>;
    const sessionKey = typeof options.sessionKey === "string" ? options.sessionKey : "";
    if (memoryId.length === 0 || sessionKey.length === 0) {
      console.error("usage: navigate <expand|traverse> <memoryId> --session-key <key> [--namespace <ns>]");
      process.exitCode = 1;
      return;
    }
    let limit: number | undefined;
    try {
      limit = action === "traverse" ? parseLimit(options.limit) : undefined;
    } catch (err) {
      console.error(err instanceof Error ? err.message : String(err));
      process.exitCode = 1;
      return;
    }
    const service = new EngramAccessService(orchestrator);
    try {
      const result = await service.recallNavigate({
        action,
        memoryId,
        sessionKey,
        ...(action === "expand" && typeof options.disclosure === "string"
          ? { disclosure: options.disclosure as "chunk" | "section" | "raw" }
          : {}),
        ...(action === "traverse" && typeof options.relation === "string" ? { relation: options.relation } : {}),
        ...(limit !== undefined ? { limit } : {}),
        ...(typeof options.namespace === "string" && options.namespace.length > 0
          ? { namespace: options.namespace }
          : {}),
      });
      if (options.json === true) {
        console.log(JSON.stringify(result, null, 2));
      } else {
        console.log(result.rendered);
      }
      if (!result.ok) process.exitCode = 1;
    } catch (err) {
      console.error(err instanceof Error ? err.message : String(err));
      process.exitCode = 1;
    }
  };

  cmd
    .command("navigate expand <memoryId>")
    .description("Re-render a served memory at deeper disclosure (issue #1956)")
    .option("--session-key <key>", "Session key whose recent recalls authorize the id (required)")
    .option("--disclosure <level>", "Target depth: section or raw (default raw)")
    .option("--namespace <ns>", "Namespace to scope the read to")
    .option("--json", "JSON output (items + budget + disclosure spend)")
    .action(async (...args: unknown[]) => run(args, "expand"));

  cmd
    .command("navigate traverse <memoryId>")
    .description("Follow typed links from a served memory; neighbors as chunk summaries (issue #1956)")
    .option("--session-key <key>", "Session key whose recent recalls authorize the id (required)")
    .option("--relation <type>", "Optional relation filter (supports, contradicts, elaborates, ...)")
    .option("--limit <n>", "Optional cap on returned neighbors")
    .option("--namespace <ns>", "Namespace to scope the read to")
    .option("--json", "JSON output (items + budget + disclosure spend)")
    .action(async (...args: unknown[]) => run(args, "traverse"));
}

/**
 * Deep-recall command group (issue #2332) — extracted from cli.ts so the
 * surface file stays at its structural ceiling (same seam as
 * meetings-commands.ts). `engram deep-recall <query>` runs the budgeted
 * REFINE/EXPAND/STOP loop through EngramAccessService — the same single
 * implementation MCP and HTTP call.
 *
 * Identity (issue #2915): with namespaces enabled the read path requires an
 * authenticated principal, and this standalone CLI runs without a transport
 * to authenticate one. It therefore exposes the SAME identity pattern the
 * access CLI already uses — `--principal` (the authenticated identity) or
 * `--session-key` (resolved through the configured principal mapping) — so a
 * namespace-enabled deployment is usable from the CLI instead of refusing
 * every invocation as unauthenticated.
 */

import type { Orchestrator } from "../orchestrator.js";
import type { CliCommand } from "../cli.js";
import { EngramAccessService } from "../access-service.js";
import { parseDeepRecallMaxSteps } from "../deep-recall-config.js";

export function registerDeepRecallCommands(cmd: CliCommand, orchestrator: Orchestrator): void {
  cmd
    .command("deep-recall <query>")
    .description("Budgeted multi-hop retrieval over the anchor graph (slow, thorough; issue #2332)")
    .option("--max-steps <n>", "Policy-step ceiling (cannot exceed the configured deepRecall.maxSteps)")
    .option("--namespace <ns>", "Namespace to scope the retrieval to")
    .option("--session-key <key>", "Session key for principal/namespace resolution (namespaces enabled)")
    .option("--principal <principal>", "Authenticated principal for namespace authorization (namespaces enabled)")
    .option("--json", "JSON output (full entries + trace)")
    .action(async (...args: unknown[]) => {
      const query = String(args[0] ?? "");
      const options = (args[args.length - 1] ?? {}) as Record<string, unknown>;
      let maxSteps: number | undefined;
      try {
        maxSteps = parseDeepRecallMaxSteps(options.maxSteps);
      } catch (err) {
        console.error(err instanceof Error ? err.message : String(err));
        process.exitCode = 1;
        return;
      }
      const sessionKey =
        typeof options.sessionKey === "string" && options.sessionKey.trim().length > 0
          ? options.sessionKey.trim()
          : undefined;
      const principal =
        typeof options.principal === "string" && options.principal.trim().length > 0
          ? options.principal.trim()
          : undefined;
      const service = new EngramAccessService(orchestrator);
      try {
        const result = await service.deepRecall({
          query,
          ...(maxSteps !== undefined ? { maxSteps } : {}),
          ...(typeof options.namespace === "string" && options.namespace.length > 0
            ? { namespace: options.namespace }
            : {}),
          ...(sessionKey !== undefined ? { sessionKey } : {}),
          ...(principal !== undefined ? { authenticatedPrincipal: principal } : {}),
        });
        if (options.json === true) {
          console.log(JSON.stringify(result, null, 2));
        } else {
          console.log(result.rendered);
        }
        if (!result.ok) process.exitCode = 1;
      } catch (err) {
        console.error(err instanceof Error ? err.message : String(err));
        process.exitCode = 1;
      }
    });
}

/**
 * Memory-store browse command group (issue #2978) — extracted from cli.ts
 * so the surface file stays at its structural ceiling (same seam as
 * cli/recall-navigation-commands.ts). `remnic browse ls|tree|find` runs
 * through EngramAccessService.memoryStoreBrowse — the same single
 * implementation MCP and HTTP call, sharing one renderer.
 */

import type { Orchestrator } from "../orchestrator.js";
import type { CliCommand } from "../cli.js";
import { EngramAccessService } from "../access-service.js";
import type { BrowseVerb } from "../memory-browse.js";

export function registerMemoryBrowseCommands(cmd: CliCommand, orchestrator: Orchestrator): void {
  const run = async (args: unknown[], verb: BrowseVerb) => {
    const options = (args[args.length - 1] ?? {}) as Record<string, unknown>;
    // `browse find <pattern>` takes the pattern as a positional arg; the
    // options object sits at the END of commander's action args.
    const pattern = typeof args[0] === "string" && args[0].length > 0
      ? args[0]
      : typeof options.pattern === "string"
        ? options.pattern
        : "";
    if (verb === "find" && pattern.trim().length === 0) {
      console.error("usage: browse <ls|tree|find> [path] [--pattern <glob>] [--depth <n>] [--namespace <ns>] [--json]");
      process.exitCode = 1;
      return;
    }
    const depth = verb === "tree" && options.depth !== undefined ? Number(options.depth) : undefined;
    if (depth !== undefined && (!Number.isFinite(depth) || !Number.isInteger(depth) || depth < 1 || depth > 4)) {
      console.error("--depth must be an integer between 1 and 4");
      process.exitCode = 1;
      return;
    }
    const service = new EngramAccessService(orchestrator);
    try {
      const result = await service.memoryStoreBrowse({
        verb,
        ...(typeof args[0] === "string" && args[0].length > 0 ? { path: args[0] } : {}),
        ...(depth !== undefined ? { depth } : {}),
        ...(verb === "find" ? { pattern } : {}),
        ...(typeof options.namespace === "string" && options.namespace.length > 0 ? { namespace: options.namespace } : {}),
      });
      if (options.json === true) {
        console.log(JSON.stringify(result, null, 2));
      } else {
        console.log(result.rendered);
      }
      if (!result.ok) process.exitCode = 1;
    } catch (err) {
      console.error(err instanceof Error ? err.message : String(err));
      process.exitCode = 1;
    }
  };

  cmd
    .command("browse ls [path]")
    .description("List children of a store path in your namespace (issue #2978)")
    .option("--namespace <ns>", "Namespace to scope the browse to")
    .option("--json", "JSON output (entries + counts + truncated flag)")
    .action(async (...args: unknown[]) => run(args, "ls"));

  cmd
    .command("browse tree [path]")
    .description("Depth-limited store tree under one path (issue #2978)")
    .option("--depth <n>", "Expansion depth, 1-4 (default 1)")
    .option("--namespace <ns>", "Namespace to scope the browse to")
    .option("--json", "JSON output (entries + counts + truncated flag)")
    .action(async (...args: unknown[]) => run(args, "tree"));

  cmd
    .command("browse find <pattern>")
    .description("Deterministic name/path glob or substring lookup (issue #2978)")
    .option("--namespace <ns>", "Namespace to scope the browse to")
    .option("--json", "JSON output (entries + counts + truncated flag)")
    .action(async (...args: unknown[]) => run(args, "find"));
}

import type { Orchestrator } from "../orchestrator.js";
