function resolveConfigPath(explicitPath?: string): string {
  if (explicitPath && explicitPath.trim().length > 0) return explicitPath.trim();
  const configured =
    readEnvVar("OPENCLAW_CONFIG_PATH") ||
    readEnvVar("OPENCLAW_ENGRAM_CONFIG_PATH");
  if (configured && configured.trim().length > 0) return configured.trim();
  return path.join(resolveHomeDir(), ".openclaw", "openclaw.json");
}

async function loadCliPluginConfig(configPath?: string): Promise<OperatorConfigLoadResult> {
  const resolvedPath = resolveConfigPath(configPath);
  try {
    const raw = JSON.parse(await readFile(resolvedPath, "utf-8")) as Record<string, unknown>;
    // Delegate slot → canonical → legacy resolution to the generic helper so
    // all config loaders stay in sync (#403).
    const entry = resolveOpenClawRemnicPluginEntry(raw);
    const parsedConfig = parseConfig(
      entry && typeof entry === "object"
        ? ((entry["config"] as Record<string, unknown> | undefined) ?? {})
        : {},
    );
    return {
      found: true,
      path: resolvedPath,
      parsed: true,
      memoryDir: parsedConfig.memoryDir,
      workspaceDir: parsedConfig.workspaceDir,
    };
  } catch (error) {
    const message = error instanceof Error ? error.message : String(error);
    return {
      found: !/ENOENT/i.test(message),
      path: resolvedPath,
      parsed: false,
      error: message,
    };
  }
}

async function isWritable(targetPath: string): Promise<boolean> {
  try {
    await access(targetPath, fsConstants.W_OK);
    return true;
  } catch {
    return false;
  }
}

async function pathExists(targetPath: string): Promise<boolean> {
  try {
    await access(targetPath, fsConstants.F_OK);
    return true;
  } catch {
    return false;
  }
}

function formatConfigValue(value: unknown): string {
  if (value === undefined || value === null) return "(unset)";
  if (typeof value === "string") return value.length > 0 ? value : "(unset)";
  if (typeof value === "number" || typeof value === "boolean") return String(value);
  return JSON.stringify(value);
}

async function gatherDirectoryStatus(
  paths: string[],
): Promise<Array<{ path: string; exists: boolean; writable: boolean }>> {
  return Promise.all(paths.map(async (targetPath) => {
    try {
      await access(targetPath, fsConstants.F_OK);
      return {
        path: targetPath,
        exists: true,
        writable: await isWritable(targetPath),
      };
    } catch {
      return {
        path: targetPath,
        exists: false,
        writable: false,
      };
    }
  }));
}

function getSetupPaths(config: PluginConfig): string[] {
  return [
    config.memoryDir,
    config.workspaceDir,
    path.join(config.memoryDir, "facts"),
    path.join(config.memoryDir, "entities"),
    path.join(config.memoryDir, "state"),
    path.join(config.memoryDir, "questions"),
    path.join(config.memoryDir, "artifacts"),
    path.join(config.memoryDir, "config"),
  ];
}

async function readJsonIfExists(filePath: string): Promise<unknown | null> {
  try {
    return JSON.parse(await readFile(filePath, "utf-8")) as unknown;
  } catch {
    return null;
  }
}

async function summarizeNativeKnowledgeStatus(config: PluginConfig): Promise<{
  enabled: boolean;
  includeFiles: string[];
  curatedIncludeSync: {
    statePath: string;
    exists: boolean;
    updatedAt: string | null;
    fileCount: number;
    activeChunkCount: number;
    deletedFileCount: number;
  };
  openclawWorkspaceAdapterEnabled: boolean;
  obsidianVaultAdapterEnabled: boolean;
  obsidianSync: {
    statePath: string;
    exists: boolean;
    updatedAt: string | null;
    vaultCount: number;
    activeChunkCount: number;
    deletedNoteCount: number;
  };
  openclawWorkspaceSync: {
    statePath: string;
    exists: boolean;
    updatedAt: string | null;
    fileCount: number;
    activeChunkCount: number;
    deletedFileCount: number;
  };
}> {
  const nativeKnowledge = config.nativeKnowledge;
  const nativeKnowledgeStateDir = nativeKnowledge?.stateDir ?? "state/native-knowledge";
  const curatedStatePath = nativeKnowledge
    ? resolveCuratedIncludeFilesStatePath(config.memoryDir, nativeKnowledge)
    : path.join(config.memoryDir, nativeKnowledgeStateDir, "curated-include-sync.json");
  const obsidianStatePath = nativeKnowledge
    ? resolveNativeKnowledgeStatePath(config.memoryDir, nativeKnowledge)
    : path.join(config.memoryDir, nativeKnowledgeStateDir, "obsidian-sync.json");
  const openclawStatePath = nativeKnowledge
    ? resolveOpenClawWorkspaceStatePath(config.memoryDir, nativeKnowledge)
    : path.join(config.memoryDir, nativeKnowledgeStateDir, "openclaw-workspace-sync.json");
  const [curatedRaw, obsidianRaw, openclawRaw] = await Promise.all([
    readJsonIfExists(curatedStatePath),
    readJsonIfExists(obsidianStatePath),
    readJsonIfExists(openclawStatePath),
  ]);

  const curatedFiles = curatedRaw && typeof curatedRaw === "object" && curatedRaw !== null
    && "files" in curatedRaw && typeof (curatedRaw as { files?: unknown }).files === "object"
    && (curatedRaw as { files?: unknown }).files !== null
      ? (curatedRaw as {
          updatedAt?: unknown;
          files: Record<string, { deleted?: boolean; chunks?: unknown[] }>;
        })
      : null;

  let curatedActiveChunkCount = 0;
  let curatedDeletedFileCount = 0;
  for (const file of Object.values(curatedFiles?.files ?? {})) {
    if (file.deleted) {
      curatedDeletedFileCount += 1;
      continue;
    }
    curatedActiveChunkCount += Array.isArray(file.chunks) ? file.chunks.length : 0;
  }

  const obsidianVaults = obsidianRaw && typeof obsidianRaw === "object" && obsidianRaw !== null
    && "vaults" in obsidianRaw && typeof (obsidianRaw as { vaults?: unknown }).vaults === "object"
    && (obsidianRaw as { vaults?: unknown }).vaults !== null
      ? (obsidianRaw as {
          updatedAt?: unknown;
          vaults: Record<string, { notes?: Record<string, { deleted?: boolean; chunks?: unknown[] }> }>;
        })
      : null;

  let obsidianActiveChunkCount = 0;
  let obsidianDeletedNoteCount = 0;
  for (const vault of Object.values(obsidianVaults?.vaults ?? {})) {
    for (const note of Object.values(vault.notes ?? {})) {
      if (note.deleted) {
        obsidianDeletedNoteCount += 1;
        continue;
      }
      obsidianActiveChunkCount += Array.isArray(note.chunks) ? note.chunks.length : 0;
    }
  }

  const openclawFiles = openclawRaw && typeof openclawRaw === "object" && openclawRaw !== null
    && "files" in openclawRaw && typeof (openclawRaw as { files?: unknown }).files === "object"
    && (openclawRaw as { files?: unknown }).files !== null
      ? (openclawRaw as {
          updatedAt?: unknown;
          files: Record<string, { deleted?: boolean; chunks?: unknown[] }>;
        })
      : null;

  let openclawActiveChunkCount = 0;
  let openclawDeletedFileCount = 0;
  for (const file of Object.values(openclawFiles?.files ?? {})) {
    if (file.deleted) {
      openclawDeletedFileCount += 1;
      continue;
    }
    openclawActiveChunkCount += Array.isArray(file.chunks) ? file.chunks.length : 0;
  }

  return {
    enabled: nativeKnowledge?.enabled === true,
    includeFiles: nativeKnowledge?.includeFiles ?? [],
    curatedIncludeSync: {
      statePath: curatedStatePath,
      exists: curatedFiles !== null,
      updatedAt: typeof curatedFiles?.updatedAt === "string" ? curatedFiles.updatedAt : null,
      fileCount: Object.keys(curatedFiles?.files ?? {}).length,
      activeChunkCount: curatedActiveChunkCount,
      deletedFileCount: curatedDeletedFileCount,
    },
    openclawWorkspaceAdapterEnabled: nativeKnowledge?.openclawWorkspace?.enabled === true,
    obsidianVaultAdapterEnabled: (nativeKnowledge?.obsidianVaults?.length ?? 0) > 0,
    obsidianSync: {
      statePath: obsidianStatePath,
      exists: obsidianVaults !== null,
      updatedAt: typeof obsidianVaults?.updatedAt === "string" ? obsidianVaults.updatedAt : null,
      vaultCount: Object.keys(obsidianVaults?.vaults ?? {}).length,
      activeChunkCount: obsidianActiveChunkCount,
      deletedNoteCount: obsidianDeletedNoteCount,
    },
    openclawWorkspaceSync: {
      statePath: openclawStatePath,
      exists: openclawFiles !== null,
      updatedAt: typeof openclawFiles?.updatedAt === "string" ? openclawFiles.updatedAt : null,
      fileCount: Object.keys(openclawFiles?.files ?? {}).length,
      activeChunkCount: openclawActiveChunkCount,
      deletedFileCount: openclawDeletedFileCount,
    },
  };
}

const CAPTURE_INSTRUCTIONS_START = "<!-- BEGIN ENGRAM EXPLICIT CAPTURE INSTRUCTIONS -->";
const CAPTURE_INSTRUCTIONS_END = "<!-- END ENGRAM EXPLICIT CAPTURE INSTRUCTIONS -->";

function buildCaptureInstructions(): string {
  return [
    CAPTURE_INSTRUCTIONS_START,
    "# Memory",
    "",
    "Use this file for explicit memory capture notes when Engram runs in explicit or hybrid mode.",
    "",
    "## Suggested format",
    "",
    "- Write durable facts, decisions, commitments, or corrections.",
    "- Keep entries concise and specific.",
    "- Avoid secrets, tokens, and private credentials.",
    "",
    "## Example",
    "",
    "- Decision: recall benchmark packs live under `state/evals/benchmarks/`.",
    "- Commitment: rerun `openclaw engram doctor --json` after changing retrieval settings.",
    "",
    CAPTURE_INSTRUCTIONS_END,
  ].join("\n");
}

function upsertManagedCaptureInstructions(existing: string | null, snippet: string): { content: string; updated: boolean; installed: boolean } {
  if (!existing || existing.trim().length === 0) {
    return { content: `${snippet}\n`, updated: false, installed: true };
  }
  if (existing.includes(CAPTURE_INSTRUCTIONS_START) && existing.includes(CAPTURE_INSTRUCTIONS_END)) {
    const next = existing.replace(
      new RegExp(`${CAPTURE_INSTRUCTIONS_START}[\\s\\S]*?${CAPTURE_INSTRUCTIONS_END}`),
      snippet,
    );
    return { content: next.endsWith("\n") ? next : `${next}\n`, updated: next !== existing, installed: false };
  }
  const trimmed = existing.trimEnd();
  return {
    content: `${trimmed}\n\n${snippet}\n`,
    updated: false,
    installed: true,
  };
}

function removeManagedCaptureInstructions(existing: string): { content: string; removed: boolean } {
  if (!existing.includes(CAPTURE_INSTRUCTIONS_START) || !existing.includes(CAPTURE_INSTRUCTIONS_END)) {
    return { content: existing, removed: false };
  }
  const stripped = existing
    .replace(new RegExp(`\\n*${CAPTURE_INSTRUCTIONS_START}[\\s\\S]*?${CAPTURE_INSTRUCTIONS_END}\\n*`), "\n")
    .replace(/\n{3,}/g, "\n\n")
    .trim();
  return {
    content: stripped.length > 0 ? `${stripped}\n` : "",
    removed: true,
  };
}

export async function runOperatorSetup(options: OperatorSetupOptions): Promise<OperatorSetupReport> {
  const now = options.now ?? new Date();
  const configStatus = await loadCliPluginConfig(options.configPath);
  const storage = options.orchestrator.storage;
  await storage.ensureDirectories();
  await mkdir(options.orchestrator.config.workspaceDir, { recursive: true });

  const qmdAvailable = await options.orchestrator.qmd.probe();
  const collectionState = resolveQmdCapabilities(options.orchestrator.config).qmd
    ? await options.orchestrator.qmd.ensureCollection(
        options.orchestrator.config.memoryDir,
        options.orchestrator.config.qmdCollection,
      )
    : "skipped";
  const nativeKnowledgeStatus = await summarizeNativeKnowledgeStatus(options.orchestrator.config);

  const memoryDocPath = path.join(options.orchestrator.config.workspaceDir, "MEMORY.md");
  const captureInstructionsMode =
    options.captureInstructionsMode
    ?? (options.installCaptureInstructions ? "install" : undefined);
  let memoryDocExists = false;
  try {
    await access(memoryDocPath, fsConstants.F_OK);
    memoryDocExists = true;
  } catch {
    memoryDocExists = false;
  }
  let memoryDocInstalled = false;
  let memoryDocUpdated = false;
  let memoryDocRemoved = false;
  const explicitCaptureEnabled = options.orchestrator.config.captureMode === "explicit"
    || options.orchestrator.config.captureMode === "hybrid";
  const captureInstructionsPreview = captureInstructionsMode ? buildCaptureInstructions() : null;
  if (captureInstructionsMode) {
    if (captureInstructionsMode === "preview") {
      // no-op, preview only
    } else if (captureInstructionsMode === "install") {
      const existing = memoryDocExists ? await readFile(memoryDocPath, "utf-8") : null;
      const next = upsertManagedCaptureInstructions(existing, captureInstructionsPreview ?? "");
      if (!existing || next.content !== existing) {
        await writeFile(memoryDocPath, next.content, "utf-8");
      }
      memoryDocExists = true;
      memoryDocInstalled = next.installed;
      memoryDocUpdated = next.updated;
    } else if (captureInstructionsMode === "remove" && memoryDocExists) {
      const existing = await readFile(memoryDocPath, "utf-8");
      const next = removeManagedCaptureInstructions(existing);
      if (next.removed) {
        if (next.content.length === 0) {
          await unlink(memoryDocPath);
          memoryDocExists = false;
        } else {
          await writeFile(memoryDocPath, next.content, "utf-8");
          memoryDocExists = true;
        }
        memoryDocRemoved = true;
      }
    }
  }

  const directories = await gatherDirectoryStatus(getSetupPaths(options.orchestrator.config));
  const nextSteps = [
    `Run \`openclaw engram doctor${options.installCaptureInstructions ? "" : " --json"}\` to verify runtime health.`,
    "Run `openclaw engram inventory --json` to capture a baseline footprint.",
    "If QMD is enabled and the collection is missing, add the collection to `~/.config/qmd/index.yml` and run `qmd update && qmd embed`.",
  ];
  if (explicitCaptureEnabled && !memoryDocExists) {
    nextSteps.push("Run `openclaw engram setup --preview-capture-instructions` to review the managed explicit-capture snippet, then `--install-capture-instructions` to write it.");
  }

  return {
    schemaVersion: 1,
    generatedAt: now.toISOString(),
    config: configStatus,
    memoryDir: options.orchestrator.config.memoryDir,
    workspaceDir: options.orchestrator.config.workspaceDir,
    directories,
    qmd: {
      enabled: resolveQmdCapabilities(options.orchestrator.config).qmd,
      available: qmdAvailable,
      collectionState,
      debugStatus: options.orchestrator.qmd.debugStatus(),
    },
    nativeKnowledge: nativeKnowledgeStatus,
    explicitCapture: {
      captureMode: options.orchestrator.config.captureMode,
      enabled: explicitCaptureEnabled,
      memoryDocPath,
      memoryDocExists,
      memoryDocInstalled,
      memoryDocUpdated,
      memoryDocRemoved,
      preview: captureInstructionsMode === "preview" ? captureInstructionsPreview : null,
    },
    nextSteps,
    verificationCommands: [
      "openclaw engram doctor --json",
      "openclaw engram inventory --json",
      "openclaw engram benchmark recall --json",
    ],
  };
}

function summarizeHygieneWarnings(
  warnings: Awaited<ReturnType<typeof lintWorkspaceFiles>>,
  hygiene: FileHygieneConfig | undefined,
): OperatorDoctorCheck {
  if (!hygiene?.enabled || hygiene.lintEnabled !== true) {
    return {
      key: "file_hygiene",
      status: "warn",
      summary: "File hygiene linting is disabled; bootstrap file truncation warnings are not active.",
      remediation: "Enable `fileHygiene.enabled` and `fileHygiene.lintEnabled` if large workspace bootstrap files are common.",
      details: {
        enabled: hygiene?.enabled === true,
        lintEnabled: hygiene?.lintEnabled === true,
      },
    };
  }
  if (warnings.length > 0) {
    return {
      key: "file_hygiene",
      status: "warn",
      summary: `${warnings.length} bootstrap file(s) are near or above the configured budget.`,
      remediation: "Archive/split the listed files or adjust `fileHygiene` budgets.",
      details: { warnings },
    };
  }
  return {
    key: "file_hygiene",
    status: "ok",
    summary: "Bootstrap file hygiene is within budget.",
    details: {
      enabled: true,
      lintPaths: hygiene.lintPaths,
      budgetBytes: hygiene.lintBudgetBytes,
    },
  };
}

function buildConfigReviewFinding(input: {
  key: string;
  status: "recommend" | "problem";
  setting: string;
  currentValue: unknown;
  defaultValue: unknown;
  recommendedValue: unknown;
  summary: string;
  rationale: string;
}): OperatorConfigReviewFinding {
  return {
    key: input.key,
    status: input.status,
    setting: input.setting,
    currentValue: formatConfigValue(input.currentValue),
    defaultValue: formatConfigValue(input.defaultValue),
    recommendedValue: formatConfigValue(input.recommendedValue),
    summary: input.summary,
    rationale: input.rationale,
  };
}

export async function runOperatorConfigReview(
  options: OperatorConfigReviewOptions,
): Promise<OperatorConfigReviewReport> {
  const now = options.now ?? new Date();
  const configStatus = await loadCliPluginConfig(options.configPath);
  return buildOperatorConfigReviewReport({
    now,
    configStatus,
    config: options.orchestrator.config,
  });
}

async function buildOperatorConfigReviewReport(input: {
  now: Date;
  configStatus: OperatorConfigLoadResult;
  config: PluginConfig;
}): Promise<OperatorConfigReviewReport> {
  const { now, configStatus, config } = input;
  // Resolve recall-operation gates once so this diagnostic reads capabilities,
  // not scattered config flags (#1566 Cluster C — rerank is a mixed-op flag).
  const caps = resolveCapabilities(config);
  const findings: OperatorConfigReviewFinding[] = [];
  const searchBackend = config.searchBackend ?? "qmd";
  const workspaceBootstrapFiles = [
    path.join(config.workspaceDir, "IDENTITY.md"),
    path.join(config.workspaceDir, "MEMORY.md"),
    path.join(config.workspaceDir, "USER.md"),
  ];
  const workspaceBootstrapExists = (await Promise.all(workspaceBootstrapFiles.map(pathExists))).some(Boolean);

  if (
    config.memoryOsPreset !== "conservative" &&
    config.memoryOsPreset !== "balanced" &&
    config.memoryOsPreset !== "research-max" &&
    config.memoryOsPreset !== "local-llm-heavy" &&
    resolveIndexingCapabilities(config).queryAwareIndexing === false &&
    resolvePresentationCapabilities(config).verbatimArtifacts === false &&
    !caps.rerank
  ) {
    findings.push(buildConfigReviewFinding({
      key: "balanced_preset",
      status: "recommend",
      setting: "memoryOsPreset",
      currentValue: config.memoryOsPreset,
      defaultValue: "(unset)",
      recommendedValue: "balanced",
      summary: "Adopt the balanced preset as the baseline configuration profile.",
      rationale:
        "The balanced preset enables the recommended indexing, reranking, and artifact defaults without turning on the higher-churn graph and learning loops.",
    }));
  }

  if (resolveQmdCapabilities(config).qmd && resolveQmdCapabilities(config).qmdDaemon === false) {
    findings.push(buildConfigReviewFinding({
      key: "qmd_daemon",
      status: "recommend",
      setting: "qmdDaemonEnabled",
      currentValue: resolveQmdCapabilities(config).qmdDaemon,
      defaultValue: true,
      recommendedValue: true,
      summary: "Enable the QMD daemon path when QMD powers recall.",
      rationale:
        "The daemon path reduces recall/search contention by preferring the MCP transport instead of repeated subprocess calls when QMD is available.",
    }));
  }

  if (workspaceBootstrapExists && config.nativeKnowledge?.enabled !== true) {
    findings.push(buildConfigReviewFinding({
      key: "native_knowledge_enabled",
      status: "recommend",
      setting: "nativeKnowledge.enabled",
      currentValue: config.nativeKnowledge?.enabled,
      defaultValue: false,
      recommendedValue: true,
      summary: "Enable native knowledge recall for workspace bootstrap documents.",
      rationale:
        "When files like IDENTITY.md or MEMORY.md already exist, native knowledge recall can chunk and inject them directly instead of relying only on extracted memories.",
    }));
  }

  if (workspaceBootstrapExists && config.fileHygiene?.enabled !== true) {
    findings.push(buildConfigReviewFinding({
      key: "file_hygiene_enabled",
      status: "recommend",
      setting: "fileHygiene.enabled",
      currentValue: config.fileHygiene?.enabled,
      defaultValue: false,
      recommendedValue: true,
      summary: "Enable file hygiene to avoid silent workspace-file truncation.",
      rationale:
        "OpenClaw bootstrap files can grow quietly; file hygiene warns before oversized files are truncated during prompt bootstrap.",
    }));
  }

  if (searchBackend === "qmd" && resolveQmdCapabilities(config).qmd === false) {
    findings.push(buildConfigReviewFinding({
      key: "qmd_search_backend_disabled",
      status: "problem",
      setting: "qmdEnabled",
      currentValue: resolveQmdCapabilities(config).qmd,
      defaultValue: true,
      recommendedValue: true,
      summary: "QMD search is selected but QMD is disabled.",
      rationale:
        "When searchBackend resolves to qmd while qmdEnabled is false, Engram falls back to the noop backend and disables the primary search path.",
    }));
  }

  if (resolveQmdCapabilities(config).qmdColdTier === true && resolveQmdCapabilities(config).qmd === false) {
    findings.push(buildConfigReviewFinding({
      key: "qmd_cold_tier_requires_qmd",
      status: "problem",
      setting: "qmdEnabled",
      currentValue: resolveQmdCapabilities(config).qmd,
      defaultValue: true,
      recommendedValue: true,
      summary: "Cold-tier QMD recall is enabled while QMD itself is disabled.",
      rationale:
        "The cold tier depends on the same QMD runtime as the hot tier, so turning QMD off leaves the extra tiering path unusable.",
    }));
  }

  if (resolveQmdCapabilities(config).qmdTierMigration && resolveQmdCapabilities(config).qmdColdTier !== true) {
    findings.push(buildConfigReviewFinding({
      key: "qmd_tier_migration_requires_cold_tier",
      status: "problem",
      setting: "qmdColdTierEnabled",
      currentValue: resolveQmdCapabilities(config).qmdColdTier,
      defaultValue: false,
      recommendedValue: true,
      summary: "Hot/cold tier migration is enabled without the cold tier itself.",
      rationale:
        "Tier migration depends on the cold-tier collection and recall path, so enabling migration while the cold tier is off leaves the feature in a contradictory state.",
    }));
  }

  if (resolveIndexingCapabilities(config).conversationIndex && config.conversationIndexBackend === "qmd" && resolveQmdCapabilities(config).qmd === false) {
    findings.push(buildConfigReviewFinding({
      key: "conversation_index_qmd_requires_qmd",
      status: "problem",
      setting: "qmdEnabled",
      currentValue: resolveQmdCapabilities(config).qmd,
      defaultValue: true,
      recommendedValue: true,
      summary: "The conversation index is configured for QMD while QMD is disabled.",
      rationale:
        "A QMD-backed conversation index cannot rebuild or serve queries when the underlying QMD runtime is disabled.",
    }));
  }

  const summary = findings.reduce(
    (acc, finding) => {
      acc[finding.status] += 1;
      return acc;
    },
    { recommend: 0, problem: 0 },
  );

  return {
    schemaVersion: 1,
    generatedAt: now.toISOString(),
    ok: configStatus.parsed && summary.problem === 0,
    config: configStatus,
    profile: {
      memoryOsPreset: config.memoryOsPreset,
      searchBackend,
      qmdEnabled: resolveQmdCapabilities(config).qmd,
      qmdDaemonEnabled: resolveQmdCapabilities(config).qmdDaemon,
      nativeKnowledgeEnabled: config.nativeKnowledge?.enabled === true,
      fileHygieneEnabled: config.fileHygiene?.enabled === true,
      conversationIndexEnabled: resolveIndexingCapabilities(config).conversationIndex,
    },
    summary,
    findings,
  };
}

/**
 * Summarize the provenance coverage of a set of memories (issue #1575 PR 3).
 * Pure function — counts the verified/unverified/none distribution so the
 * doctor check and any future surface can consume it without coupling to the
 * orchestrator. Legacy memories (no `provenance` field) count as `"none"`.
 */
export function summarizeProvenanceCoverage(
  memories: ReadonlyArray<{ frontmatter: { provenance?: string } }>,
): { counts: { verified: number; unverified: number; none: number }; total: number } {
  const counts = { verified: 0, unverified: 0, none: 0 };
  for (const mem of memories) {
    const tag = mem.frontmatter.provenance ?? "none";
    if (tag === "verified") counts.verified += 1;
    else if (tag === "unverified") counts.unverified += 1;
    else counts.none += 1;
  }
  return { counts, total: memories.length };
}

/**
 * Memory projection health (issue #1829). A present-but-unopenable projection
 * (wrong ABI / corrupt / bad perms) previously collapsed into the same silent
 * null as a missing file, hiding native-binding mismatches behind full-corpus
 * scans. This check stats + attempt-opens the projection so `remnic doctor`
 * distinguishes "not built yet" (normal) from "exists but broken" (needs a
 * rebuild / native-binding rebuild). Never throws.
 */
export function summarizeProjectionHealth(
  config: Pick<PluginConfig, "memoryDir">,
): OperatorDoctorCheck {
  const probe = probeProjectionHealth(config.memoryDir);
  if (probe.state === "absent") {
    return {
      key: "memory_projection",
      status: "ok",
      summary: "Memory projection index not built yet (normal until first maintenance run).",
      details: { state: probe.state },
    };
  }
  if (probe.state === "openable") {
    return {
      key: "memory_projection",
      status: "ok",
      summary: "Memory projection index opens cleanly.",
      details: { state: probe.state },
    };
  }
  if (probe.state === "present-but-invalid") {
    const schemaDetailSuffix = probe.detail ? ` (${probe.detail})` : "";
    return {
      key: "memory_projection",
      status: "error",
      summary: `Memory projection index exists but its schema is missing or unreadable${schemaDetailSuffix}; memory browse is falling back to full-corpus scans.`,
      remediation:
        "Rebuild the projection with `remnic rebuild-memory-projection --write`.",
      details: { state: probe.state, detail: probe.detail },
    };
  }
  const nativeSuffix = probe.nativeBindingMismatch
    ? " Native binding appears built for the wrong Node.js ABI."
    : "";
  const detailSuffix = probe.detail ? ` (${probe.detail})` : "";
  return {
    key: "memory_projection",
    status: "error",
    summary: `Memory projection index exists but could not be opened${detailSuffix}.${nativeSuffix}`,
    remediation: probe.nativeBindingMismatch
      ? "Rebuild the better-sqlite3 native binding for this Node.js (`node scripts/ensure-better-sqlite3.mjs` or `pnpm rebuild better-sqlite3`), then restart."
      : "Rebuild the projection with `remnic rebuild-memory-projection --write`; check file permissions and integrity.",
    details: {
      state: probe.state,
      detail: probe.detail,
      nativeBindingMismatch: probe.nativeBindingMismatch,
    },
  };
}

export async function runOperatorDoctor(options: OperatorDoctorOptions): Promise<OperatorDoctorReport> {
  const now = options.now ?? new Date();
  const configStatus = await loadCliPluginConfig(options.configPath);
  const checks: OperatorDoctorCheck[] = [];
  const config = options.orchestrator.config;
  const storage = options.orchestrator.storage;
  const configReview = await buildOperatorConfigReviewReport({
    now,
    configStatus,
    config,
  });
  const nativeKnowledgeStatus = await summarizeNativeKnowledgeStatus(config);
  const setupPaths = await gatherDirectoryStatus(getSetupPaths(config));
  const missingPaths = setupPaths.filter((entry) => !entry.exists).map((entry) => entry.path);

  checks.push({
    key: "config",
    status: configStatus.parsed
      ? "ok"
      : options.configPath
      ? "error"
      : "warn",
    summary: configStatus.parsed ? "OpenClaw config loaded and Engram config parsed successfully." : "Config file could not be parsed.",
    remediation: configStatus.parsed ? undefined : "Fix the config file or set OPENCLAW_ENGRAM_CONFIG_PATH/OPENCLAW_CONFIG_PATH.",
    details: configStatus,
  });

  checks.push({
    key: "memory_dir",
    status: missingPaths.length === 0 ? "ok" : "warn",
    summary: missingPaths.length === 0
      ? "Expected Engram directories exist."
      : `${missingPaths.length} expected directory path(s) are missing.`,
    remediation: missingPaths.length === 0 ? undefined : "Run `openclaw engram setup` to create missing directories.",
    details: { directories: setupPaths },
  });

  checks.push({
    key: "config_review",
    status: configReview.summary.problem > 0 ? "error" : configReview.summary.recommend > 0 ? "warn" : "ok",
    summary: configReview.summary.problem > 0
      ? `${configReview.summary.problem} configuration problem(s) detected.`
      : configReview.summary.recommend > 0
      ? `No configuration problems detected; ${configReview.summary.recommend} optional recommendation(s) are available.`
      : "No configuration problems detected.",
    remediation: configReview.summary.problem > 0 || configReview.summary.recommend > 0
      ? "Run `openclaw engram config-review` to inspect and fix the flagged configuration combinations."
      : undefined,
    details: configReview,
  });

  const qmdAvailable = await options.orchestrator.qmd.probe();
  const collectionState = resolveQmdCapabilities(config).qmd
    ? await options.orchestrator.qmd.ensureCollection(config.memoryDir, config.qmdCollection)
    : "skipped";
  checks.push({
    key: "qmd",
    status: !resolveQmdCapabilities(config).qmd
      ? "warn"
      : !qmdAvailable
      ? "error"
      : collectionState === "present"
      ? "ok"
      : collectionState === "missing"
      ? "error"
      : "warn",
    summary: !resolveQmdCapabilities(config).qmd
      ? "QMD is disabled in config."
      : qmdAvailable
      ? `QMD is reachable (${collectionState}).`
      : "QMD is not currently reachable.",
    remediation: !resolveQmdCapabilities(config).qmd
      ? "Enable `qmdEnabled` if you expect hybrid search."
      : !qmdAvailable
      ? "Ensure the `qmd` binary is installed and on PATH, or set `qmdPath`."
      : collectionState === "missing"
      ? "Add the configured collection to `~/.config/qmd/index.yml`."
      : collectionState === "present"
      ? undefined
      : "Re-run `openclaw engram setup` after restoring QMD access.",
    details: {
      available: qmdAvailable,
      collectionState,
      debugStatus: options.orchestrator.qmd.debugStatus(),
    },
  });

  const conversationIndex = await options.orchestrator.conversationIndexCoordinator.getHealth();
  checks.push({
    key: "conversation_index",
    status: conversationIndex.status === "ok"
      ? "ok"
      : conversationIndex.enabled
      ? "error"
      : "warn",
    summary: conversationIndex.enabled
      ? `Conversation index backend is ${conversationIndex.status}.`
      : "Conversation index is disabled.",
    remediation: conversationIndex.enabled && conversationIndex.status !== "ok"
      ? "Run `openclaw engram rebuild-index` to refresh the conversation index artifacts."
      : undefined,
    details: conversationIndex,
  });

  const meta = await storage.loadMeta();
  checks.push({
    key: "maintenance",
    status: meta.lastExtractionAt || meta.lastConsolidationAt ? "ok" : "warn",
    summary: meta.lastExtractionAt || meta.lastConsolidationAt
      ? "Extraction/consolidation metadata is present."
      : "No extraction or consolidation metadata found yet.",
    remediation: meta.lastExtractionAt || meta.lastConsolidationAt
      ? undefined
      : "Run a normal agent turn or `openclaw engram consolidate` after seeding memory.",
    details: meta,
  });

  // Extraction resilience (extraction hot-loop hardening). Surfaces the
  // persisted per-fingerprint retry/backoff state so an operator can see when
  // the extraction provider is failing without tailing logs. auth/config
  // failures are an error (misconfigured provider, will not self-heal at the
  // current cadence); transient backoff is a warn; a clean state is ok. Reads
  // the already-loaded meta — no extra I/O, cross-process safe (the in-memory
  // breaker lives in the daemon; this derives from durable state).
  const retryEntries = meta.extractionRetryState ?? [];
  const authConfigFailures = retryEntries.filter((entry) => entry.lastFailureClass === "auth_config");
  const nowMs = Date.now();
  const parkedFingerprints = retryEntries.filter((entry) => {
    const eligibleAt = Date.parse(entry.nextEligibleAt);
    return Number.isFinite(eligibleAt) && eligibleAt > nowMs;
  });
  // The in-memory breaker opens only after extractionBreakerFailureThreshold
  // CONSECUTIVE provider failures, each of which parks a fingerprint — so
  // doctor infers "likely open" only when the parked transient count reaches
  // that threshold. A single parked fingerprint is ordinary backoff, not a
  // suspended-extraction signal (cursor review: don't overclaim). The breaker
  // itself is per-process (daemon-only), hence the durable-signal inference.
  const providerRetryableParked = parkedFingerprints.filter(
    (entry) => entry.lastFailureClass === "provider_retryable",
  );
  const breakerLikelyOpen =
    providerRetryableParked.length >= Math.max(1, config.extractionBreakerFailureThreshold);
  const resilienceStatus: "ok" | "warn" | "error" =
    authConfigFailures.length > 0 ? "error" : parkedFingerprints.length > 0 ? "warn" : "ok";
  checks.push({
    key: "extraction-resilience",
    status: resilienceStatus,
    summary:
      resilienceStatus === "error"
        ? `Extraction provider has ${authConfigFailures.length} auth/config failure(s); the circuit breaker opens immediately and extraction is suspended.`
        : resilienceStatus === "warn"
          ? `${parkedFingerprints.length} extraction fingerprint(s) in backoff after transient provider failures${
              breakerLikelyOpen ? "; the provider circuit breaker is likely OPEN in the daemon (non-forced extraction is suspended until it half-opens)" : ""
            }.`
          : "No extraction provider failures are currently parked.",
    remediation:
      resilienceStatus === "error"
        ? 'Check the extraction LLM gateway/model configuration (a 401/403 or "no models configured" was seen). Extraction resumes automatically once the provider is reachable.'
        : resilienceStatus === "warn"
          ? "Transient provider failures (e.g. 429/5xx). Backoff clears automatically as the provider recovers; no action needed unless it persists."
          : undefined,
    details: {
      backoffFingerprintCount: retryEntries.length,
      authConfigFailureCount: authConfigFailures.length,
      parkedFingerprintCount: parkedFingerprints.length,
      providerRetryableParkedCount: providerRetryableParked.length,
      breakerLikelyOpen,
    },
  });

  // Memory projection health (issue #1829). Surfaces a present-but-unopenable
  // projection (wrong ABI / corrupt) that previously degraded every memory
  // list to a silent full-corpus scan. Absent and openable are both "ok".
  checks.push(summarizeProjectionHealth(config));

  // Provenance coverage (issue #1575 PR 3). Operators need to see the
  // verified/unverified/none distribution grow as extraction backfills.
  // Best-effort: a read failure surfaces as a warn, not an error.
  let provenanceCoverage: ReturnType<typeof summarizeProvenanceCoverage> = {
    counts: { verified: 0, unverified: 0, none: 0 },
    total: 0,
  };
  let provenanceReadOk = true;
  let provenancePartialTiers: string[] = [];
  try {
    // Include all tiers so cold-migrated and archived memories are counted
    // (codex thread PRRT_kwDORJXyws6Ojqz8 — readAllMemories is hot-only).
    // Use allSettled so a real read failure (e.g. locked encrypted store)
    // is surfaced as a partial-read warning, not silently swallowed
    // (codex thread PRRT_kwDORJXyws6OjygQ).
    const [hot, archived, cold] = await Promise.allSettled([
      storage.readAllMemories(),
      storage.readArchivedMemories(),
      storage.readAllColdMemories(),
    ]);
    const all: { frontmatter: { provenance?: string } }[] = [];
    if (hot.status === "fulfilled") all.push(...hot.value);
    else provenancePartialTiers.push("hot");
    if (archived.status === "fulfilled") all.push(...archived.value);
    else provenancePartialTiers.push("archived");
    if (cold.status === "fulfilled") all.push(...cold.value);
    else provenancePartialTiers.push("cold");
    provenanceCoverage = summarizeProvenanceCoverage(all);
  } catch {
    provenanceReadOk = false;
  }
  const pc = provenanceCoverage.counts;
  const totalProvenance = provenanceCoverage.total;
  const provenanceCovered = pc.verified + pc.unverified;
  const partialSuffix = provenancePartialTiers.length > 0
    ? ` (partial: ${provenancePartialTiers.join("/")} tier unreadable)`
    : "";
  checks.push({
    key: "provenance_coverage",
    status: !provenanceReadOk || provenancePartialTiers.length > 0
      ? "warn"
      : totalProvenance === 0
        ? "warn"
        : provenanceCovered === 0
          ? "warn"
          : "ok",
    summary: !provenanceReadOk
      ? "Could not read memories for provenance coverage."
      : totalProvenance === 0
        ? "No memories found yet — provenance coverage is empty."
        : `Provenance coverage: ${pc.verified} verified, ${pc.unverified} unverified, ${pc.none} none (${totalProvenance} total).${partialSuffix}`,
    remediation: !provenanceReadOk
      ? undefined
      : provenancePartialTiers.length > 0
        ? `Some tiers could not be read (${provenancePartialTiers.join(", ")}). Check storage health and re-run.`
        : provenanceCovered === 0 && totalProvenance > 0
          ? "New extractions will carry source spans. Existing legacy memories remain `none` until re-extracted."
          : undefined,
    details: { provenanceCounts: pc, total: totalProvenance, partialTiers: provenancePartialTiers.length > 0 ? provenancePartialTiers : undefined },
  });

  const syncedChunkCount =
    nativeKnowledgeStatus.curatedIncludeSync.activeChunkCount +
    nativeKnowledgeStatus.obsidianSync.activeChunkCount +
    nativeKnowledgeStatus.openclawWorkspaceSync.activeChunkCount;
  const hasSyncState =
    nativeKnowledgeStatus.curatedIncludeSync.exists ||
    nativeKnowledgeStatus.obsidianSync.exists ||
    nativeKnowledgeStatus.openclawWorkspaceSync.exists;
  checks.push({
    key: "native_knowledge",
    status: !nativeKnowledgeStatus.enabled
      ? "warn"
      : hasSyncState
        ? "ok"
        : "warn",
    summary: !nativeKnowledgeStatus.enabled
      ? "Native knowledge sync is disabled."
      : hasSyncState
        ? `Native knowledge sync state is present (${syncedChunkCount} active chunks).`
        : "Native knowledge sync is enabled but no sync state has been written yet.",
    remediation: !nativeKnowledgeStatus.enabled
      ? "Enable `nativeKnowledge.enabled` if curated workspace recall should participate in retrieval."
      : hasSyncState
        ? undefined
        : "Run a recall, sync, or setup flow that touches native knowledge sources, then rerun `openclaw engram doctor --json`.",
    details: nativeKnowledgeStatus,
  });

  const agentAccessEnabled = config.agentAccessHttp?.enabled === true;
  // A SecretRef object counts as "configured" (issue #757) — resolution
  // happens at service-start time, not at doctor-time.  We only check that
  // *something* is set; we never log the resolved value.
  const rawAuthToken = config.agentAccessHttp?.authToken;
  const authTokenConfigured =
    (typeof rawAuthToken === "string" && rawAuthToken.length > 0) ||
    (rawAuthToken !== null &&
      typeof rawAuthToken === "object" &&
      typeof (rawAuthToken as { source?: unknown }).source === "string");
  checks.push({
    key: "access_http_auth",
    status: !agentAccessEnabled
      ? "warn"
      : authTokenConfigured
      ? "ok"
      : "error",
    summary: !agentAccessEnabled
      ? "Agent access HTTP bridge is disabled."
      : authTokenConfigured
      ? "Agent access HTTP bridge has an auth token configured."
      : "Agent access HTTP bridge is enabled without an auth token.",
    remediation: !agentAccessEnabled
      ? "Ignore unless you plan to enable the HTTP bridge."
      : authTokenConfigured
      ? undefined
      : "Set `agentAccessHttp.authToken` before exposing the bridge.",
  });

  const warnings = config.fileHygiene?.lintEnabled
    ? await lintWorkspaceFiles({
        workspaceDir: config.workspaceDir,
        paths: config.fileHygiene.lintPaths,
        budgetBytes: config.fileHygiene.lintBudgetBytes,
        warnRatio: config.fileHygiene.lintWarnRatio,
      })
    : [];
  checks.push(summarizeHygieneWarnings(warnings, config.fileHygiene));

  // Memory Worth legacy counter audit (issue #560 PR 1).
  // Memories written before #560 have no `mw_success` / `mw_fail` frontmatter
  // fields. That is fully supported — readers treat the absence as a uniform
  // Beta(1,1) prior — but surfacing the count helps operators understand how
  // much history will bootstrap the scoring pipeline landed in later PRs.
  // This is an informational check, never an error.
  checks.push(await summarizeMemoryWorthLegacyCounters(storage));

  // Buffer surprise telemetry distribution (issue #563 PR 3).
  // Surfaces recent surprise scores so operators can calibrate the
  // `bufferSurpriseThreshold` from real traffic. Never an error — an empty
  // ledger is the expected state until the flag is turned on.
  checks.push(
    await summarizeBufferSurpriseDistribution(storage, config),
  );

  // Consolidation provenance integrity (issue #561 PR 4).
  // Validates that every `derived_from` entry resolves to an on-disk
  // page-version snapshot and every `derived_via` is a known operator.
  // Broken provenance emits warnings with the offending file path — the
  // check is informational (never an error) because a missing snapshot
  // can legitimately occur after log pruning or versioning being disabled
  // retroactively; operators need visibility, not a hard fail.  Review
  // feedback (PR #634): the summarizer threads the configured
  // `versioningSidecarDir` into the scan so deployments that override
  // the default `.versions` directory get accurate results instead of
  // false-missing warnings.
  checks.push(await summarizeConsolidationProvenance(storage, config));

  // Graph-edge decay maintenance status (issue #681 PR 2/3).
  // Reports whether the periodic decay job has run and surfaces last-run
  // counts. Disabled is "ok" with a note; enabled-but-never-run is "warn".
  checks.push(await summarizeGraphEdgeDecayStatus(config));

  // Tier distribution (issue #686 retention-completion).
  checks.push(await summarizeTierDistribution(options.orchestrator.storage));
  checks.push(await summarizeDreamsPhases(config, storage, meta));
  const extractionWatermark = await readAggregateExtractionWatermark({ config, rootStorage: storage, rootMeta: meta, storageForNamespace: (ns, rootDir) => options.orchestrator.getStorage?.(ns) ?? new StorageManager(rootDir) });
  checks.push(await summarizeExtractionLiveness(config, extractionWatermark, options.orchestrator.buffer));
  checks.push(...(await summarizeCorpusAndReplica(config, (d) => new StorageManager(d), options.resolveSecretRef)));
  // Security mitigation status (issue #565).
  // Reports whether the cross-namespace budget and anomaly detection
  // mitigations are enabled and surfaces config values for operator review.
  checks.push(summarizeSecurityMitigations(config));

  // Observation throughput + judge acceptance rate (issue #685).
  // Surfaces the total verdict count, accept/reject/defer breakdown, and the
  // most recent `observedAt` timestamp from the extraction-judge telemetry
  // ledger.  This closes the *(future)* item deferred in
  // `docs/trace-to-primitive.md`.  The check is purely informational — it
  // always resolves to `ok`; an empty ledger is the expected cold-install
  // state and is never an error.
  checks.push(await summarizeObservationThroughput(config.memoryDir));

  // Namespace maintenance fanout status (issue #1500).
  // Reports per-job+namespace maintenance outcomes (ran/skipped/failed) so
  // operators can verify that dynamic project/team namespaces are being
  // maintained. Informational: never errors on its own — a namespace that has
  // never been maintained is the expected cold-install state.
  const namespaceMaintenanceHealth = await summarizeNamespaceMaintenanceHealth(config);
  checks.push({
    key: "namespace_maintenance",
    status: namespaceMaintenanceHealth.totalFailed > 0 ? "warn" : "ok",
    summary:
      namespaceMaintenanceHealth.totalRan === 0 && namespaceMaintenanceHealth.totalFailed === 0
        ? "No namespace maintenance recorded yet (expected for a fresh install)."
        : `${namespaceMaintenanceHealth.totalRan} namespace maintenance run(s)` +
          (namespaceMaintenanceHealth.totalFailed > 0
            ? `, ${namespaceMaintenanceHealth.totalFailed} failure(s) across ${namespaceMaintenanceHealth.jobs.filter((j) => j.failed > 0).length} job(s)`
            : "") +
          ".",
    remediation:
      namespaceMaintenanceHealth.totalFailed > 0
        ? "Run `remnic namespaces maintenance` for per-namespace details."
        : undefined,
    details: namespaceMaintenanceHealth,
  });

  // Tombstone non-resurrection invariant (issue #1579). Reports active
  // tombstone count, last append, corrupted-line count, and rebuild
  // staleness so operators can verify the invariant is enforced and know
  // when a rebuild is warranted. Informational: never errors on its own.
  checks.push(await summarizeTombstoneStatus(options.orchestrator.storage));

  const summary = checks.reduce(
    (acc, check) => {
      acc[check.status] += 1;
      return acc;
    },
    { ok: 0, warn: 0, error: 0 },
  );

  return {
    schemaVersion: 1,
    generatedAt: now.toISOString(),
    ok: summary.error === 0,
    summary,
    config: configStatus,
    checks,
  };
}

/**
 * Categories whose memories are eligible for Memory Worth instrumentation.
 *
 * Memory Worth is a per-fact utility signal: the counters ride on extracted
 * facts whose retrieval outcome can be judged (success/fail) by the feedback
 * pipeline landing in issue #560 PR 3. Procedures, corrections, and other
 * non-fact memory kinds are out of scope — they are not expected to be
 * instrumented, and counting them as "legacy" would permanently inflate the
 * legacy bucket and make rollout progress misleading even when every fact
 * memory is instrumented.
 *
 * If a later PR widens Memory Worth to additional categories, extend this set
 * alongside the scoring/increment logic so the doctor audit stays in sync.
 */
const MEMORY_WORTH_ELIGIBLE_CATEGORIES: ReadonlySet<MemoryFile["frontmatter"]["category"]> =
  new Set(["fact", "procedure"]);

/**
 * Count memories that pre-date the Memory Worth counters introduced in issue
 * #560 — i.e., neither `mw_success` nor `mw_fail` is set on the frontmatter.
 *
 * Only memories whose category is eligible for Memory Worth (see
 * `MEMORY_WORTH_ELIGIBLE_CATEGORIES`) are considered. Procedures, corrections,
 * and other kinds that are not instrumented are excluded entirely — they're
 * neither "legacy" nor "instrumented" for the purposes of this audit. The
 * total in the returned details reflects only eligible memories.
 *
 * Returned as an `ok` check regardless of count, since legacy memories are
 * fully functional (readers treat missing counters as zero observations). The
 * numbers are informational for operators following the #560 rollout.
 *
 * Exported so unit tests can exercise the classification logic without
 * booting a full orchestrator.
 */
export async function summarizeMemoryWorthLegacyCounters(
  storage: StorageManager,
): Promise<OperatorDoctorCheck> {
  let legacy = 0;
  let instrumented = 0;
  let ineligible = 0;
  try {
    const memories = await storage.readAllMemories();
    for (const memory of memories) {
      if (!MEMORY_WORTH_ELIGIBLE_CATEGORIES.has(memory.frontmatter.category)) {
        ineligible += 1;
        continue;
      }
      const { mw_success, mw_fail } = memory.frontmatter;
      if (mw_success === undefined && mw_fail === undefined) {
        legacy += 1;
      } else {
        instrumented += 1;
      }
    }
  } catch (err) {
    return {
      key: "memory_worth_legacy",
      status: "warn",
      summary: "Could not enumerate memories to count Memory Worth instrumentation.",
      remediation: "Retry `remnic doctor` after ensuring the memory directory is readable.",
      details: { error: String(err) },
    };
  }

  const total = legacy + instrumented;
  return {
    key: "memory_worth_legacy",
    status: "ok",
    summary:
      total === 0
        ? "No Memory Worth–eligible memories on disk yet — counters will populate as facts are extracted."
        : `${legacy} of ${total} eligible memories have no Memory Worth counters yet (${instrumented} instrumented).`,
    details: { legacy, instrumented, total, ineligible },
  };
}

/**
 * Summarize the recent buffer-surprise telemetry distribution for the
 * Doctor report (issue #563 PR 3).
 *
 * Reports mean/median/p90 surprise scores and the triggered-flush rate
 * over the most recent window of ledger rows. An empty ledger is the
 * expected state until `bufferSurpriseTriggerEnabled` is turned on — the
 * check never escalates beyond `ok` / `warn` (ledger unreadable).
 *
 * Exported so tests can exercise the formatting without booting a real
 * orchestrator.
 */
export async function summarizeBufferSurpriseDistribution(
  storage: StorageManager,
  config: PluginConfig,
): Promise<OperatorDoctorCheck> {
  const storageWithLedger = storage as StorageManager & {
    readBufferSurpriseEvents?: (
      opts: { limit?: number },
    ) => Promise<BufferSurpriseEvent[]>;
  };

  // Defensive: older StorageManager builds (not yet rebuilt) may lack the
  // reader. Do not fail the entire Doctor run in that case.
  if (typeof storageWithLedger.readBufferSurpriseEvents !== "function") {
    return {
      key: "buffer_surprise_distribution",
      status: "ok",
      summary: "Buffer-surprise telemetry reader unavailable in this build.",
      details: { available: false },
    };
  }

  try {
    const dist = await reportBufferSurpriseDistribution(
      async (opts) =>
        storageWithLedger.readBufferSurpriseEvents!({ limit: opts.limit }),
      { limit: 200 },
    );

    if (dist.count === 0) {
      return {
        key: "buffer_surprise_distribution",
        status: "ok",
        summary: resolvePresentationCapabilities(config).bufferSurpriseTrigger
          ? "Surprise trigger is enabled but no telemetry has been recorded yet."
          : "Surprise trigger is disabled; no telemetry expected.",
        details: {
          enabled: resolvePresentationCapabilities(config).bufferSurpriseTrigger,
          distribution: dist,
        },
      };
    }

    const pct = (value: number) => (value * 100).toFixed(1);
    return {
      key: "buffer_surprise_distribution",
      status: "ok",
      summary: `Recent surprise: mean=${dist.mean.toFixed(3)}, median=${dist.median.toFixed(3)}, p90=${dist.p90.toFixed(3)}, triggered=${pct(dist.triggeredRate)}% over ${dist.count} turns (threshold=${dist.currentThreshold ?? config.bufferSurpriseThreshold}).`,
      details: {
        enabled: resolvePresentationCapabilities(config).bufferSurpriseTrigger,
        distribution: dist,
      },
    };
  } catch (err) {
    return {
      key: "buffer_surprise_distribution",
      status: "warn",
      summary: "Could not read buffer-surprise telemetry ledger.",
      remediation:
        "Retry `remnic doctor` after ensuring the memory state directory is readable.",
      details: { error: String(err) },
    };
  }
}

/**
 * Summarize the consolidation-provenance integrity scan for the doctor
 * report (issue #561 PR 4).  Returns an `ok` check when no issues are
 * found, `warn` otherwise.  Never returns `error` — a broken provenance
 * pointer is informational because it can legitimately result from log
 * pruning, versioning being disabled retroactively, or operator-driven
 * archive operations.
 *
 * Exported so unit tests can exercise the summarization without booting a
 * full orchestrator.
 */

async function summarizeGraphEdgeDecayStatus(
  config: Pick<
    PluginConfig,
    "memoryDir" | "graphEdgeDecayEnabled" | "graphEdgeDecayCadenceMs"
  >,
): Promise<OperatorDoctorCheck> {
  // Lazy import to keep the doctor fast when the feature is disabled.
  const { readGraphEdgeDecayStatus } = await import("./maintenance/graph-edge-decay.js");
  const { graphEdgeDecayEnabled } = config;
  const enabled = graphEdgeDecayEnabled === true;
  if (!enabled) {
    return {
      key: "graph_edge_decay",
      status: "ok",
      summary: "Graph-edge decay maintenance is disabled (graphEdgeDecayEnabled = false).",
      remediation: "Set graphEdgeDecayEnabled = true to opt into the periodic decay job (issue #681).",
      details: { enabled: false },
    };
  }

  const status = await readGraphEdgeDecayStatus(config.memoryDir);
  if (!status) {
    return {
      key: "graph_edge_decay",
      status: "warn",
      summary: "Graph-edge decay is enabled but has not run yet (no status file present).",
      remediation:
        "Trigger the cron, run `engram.graph_edge_decay_run` via MCP, or wait for the scheduled cadence to fire.",
      details: { enabled: true, lastRun: null, cadenceMs: config.graphEdgeDecayCadenceMs },
    };
  }

  return {
    key: "graph_edge_decay",
    status: "ok",
    summary:
      `Graph-edge decay last ran at ${status.ranAt} ` +
      `(${status.edgesDecayed}/${status.edgesTotal} edges decayed, ` +
      `${status.edgesBelowVisibilityThreshold} below visibility threshold).`,
    details: {
      enabled: true,
      lastRun: status.ranAt,
      durationMs: status.durationMs,
      edgesTotal: status.edgesTotal,
      edgesDecayed: status.edgesDecayed,
      edgesBelowVisibilityThreshold: status.edgesBelowVisibilityThreshold,
      topDecayedEntities: status.topDecayedEntities,
      cadenceMs: config.graphEdgeDecayCadenceMs,
    },
  };
}

/**
 * Summarize hot/cold tier distribution for the Doctor report
 * (issue #686 retention-completion).
 *
 * Shows:
 *   - hot vs cold memory counts
 *   - forgotten-memory count
 *   - top per-status breakdown
 *   - recent migrations in the last 7 days (from the tier-migration journal)
 *   - top demotion reasons from the journal
 *
 * Always returns an `ok` check — this section is informational, never
 * a gate. A missing journal or unreadable corpus is surfaced as a note,
 * not an error.
 *
 * Exported so tests can exercise the summarizer without a full orchestrator.
 */
export async function summarizeTierDistribution(
  storage: StorageManager,
): Promise<OperatorDoctorCheck> {
  try {
    const { summarizeTiers } = await import("./maintenance/tier-stats.js");
    const summary = await summarizeTiers(storage);

    // Read recent migration journal entries (last 7 days)
    const storageDir = (storage as unknown as { dir?: string }).dir ?? "";
    const journalPath = storageDir.length > 0
      ? path.join(storageDir, "state", "tier-migration-journal.jsonl")
      : null;
    let recentMigrations = 0;
    const demotionReasons: Record<string, number> = {};
    const sevenDaysAgoMs = Date.now() - 7 * 86_400_000;

    if (journalPath) {
      try {
        const { readFile } = await import("node:fs/promises");
        const raw = await readFile(journalPath, "utf-8");
        for (const line of raw.split("\n")) {
          const trimmed = line.trim();
          if (trimmed.length === 0) continue;
          try {
            const entry = JSON.parse(trimmed) as {
              ts?: string;
              changed?: boolean;
              fromTier?: string;
              toTier?: string;
              reason?: string;
            };
            const tsMs = entry.ts ? Date.parse(entry.ts) : NaN;
            if (Number.isFinite(tsMs) && tsMs >= sevenDaysAgoMs && entry.changed === true) {
              recentMigrations += 1;
              if (entry.fromTier === "hot" && entry.toTier === "cold" && typeof entry.reason === "string") {
                const reason = entry.reason;
                demotionReasons[reason] = (demotionReasons[reason] ?? 0) + 1;
              }
            }
          } catch {
            // Malformed line — skip
          }
        }
      } catch {
        // Journal not present yet — expected on fresh installs
      }
    }

    const topDemotionReasons = Object.entries(demotionReasons)
      .sort((a, b) => b[1] - a[1] || a[0].localeCompare(b[0]))
      .slice(0, 5)
      .map(([reason, count]) => ({ reason, count }));

    const statusParts = Object.entries(summary.byStatus)
      .sort((a, b) => b[1] - a[1] || a[0].localeCompare(b[0]))
      .slice(0, 6)
      .map(([s, n]) => `${s}: ${n}`)
      .join(", ");

    return {
      key: "tier_distribution",
      status: "ok",
      summary:
        `Tier distribution: hot=${summary.byTier.hot}, cold=${summary.byTier.cold}` +
        (summary.forgottenCount > 0 ? `, forgotten=${summary.forgottenCount}` : "") +
        `. Total: ${summary.total}.` +
        (recentMigrations > 0 ? ` Recent migrations (7d): ${recentMigrations}.` : ""),
      details: {
        total: summary.total,
        byTier: summary.byTier,
        byStatus: summary.byStatus,
        forgottenCount: summary.forgottenCount,
        statusSummary: statusParts,
        recentMigrations,
        topDemotionReasons,
      },
    };
  } catch (err) {
    return {
      key: "tier_distribution",
      status: "ok",
      summary: "Tier distribution unavailable — could not enumerate memories.",
      details: { error: String(err) },
    };
  }
}

/**
 * Dreams phases doctor check (issue #678 PR 2/4).
 *
 * Reports per-phase: enabled status, cadence, threshold values, and last-run
 * timestamp sourced from `meta.json` (the existing maintenance ledger).
 *
 * Last-run mapping (best available in PR 2; PR 3/4 will emit per-phase events):
 *   light sleep → `meta.lastExtractionAt`   (lifecycle pass runs with extraction)
 *   REM         → `meta.lastConsolidationAt` (semantic consolidation)
 *   deep sleep  → latest governance run manifest when present, otherwise null
 */
export async function summarizeDreamsPhases(
  config: Pick<PluginConfig, "memoryDir" | "dreamsPhases">,
  storage: StorageManager = new StorageManager(config.memoryDir),
  loadedMeta?: MetaState,
): Promise<OperatorDoctorCheck> {
  const phases: DreamsPhasesConfig = config.dreamsPhases;
  const meta = loadedMeta ?? (await storage.loadMeta());

  let deepSleepLastRun: string | null = null;
  let deepSleepLastRunWarning: string | null = null;
  try {
    // Read the latest governance run's manifest from the real on-disk format
    // rather than treating every failure as "no runs yet".
    const runsDir = path.join(config.memoryDir, "state", "memory-governance", "runs");
    const runIds = (await readdir(runsDir)).sort().reverse();
    if (runIds.length > 0) {
      const latestRunId = runIds[0];
      const manifestPath = path.join(
        runsDir,
        latestRunId,
        "manifest.json",
      );
      const raw = await readFile(manifestPath, "utf-8");
      const parsed = JSON.parse(raw) as Record<string, unknown>;
      if (typeof parsed.createdAt === "string" && parsed.createdAt.length > 0) {
        deepSleepLastRun = parsed.createdAt;
      }
    }
  } catch (error) {
    if (!isMissingPathError(error)) {
      deepSleepLastRunWarning = `Could not read latest governance run manifest: ${formatUnknownError(error)}`;
    }
  }

  // Build per-phase summary lines for the human-readable `summary` field.
  const phaseLines: string[] = [
    `lightSleep: enabled=${phases.lightSleep.enabled}, cadenceMs=${phases.lightSleep.cadenceMs}, promoteHeat=${phases.lightSleep.promoteHeatThreshold}, staleDecay=${phases.lightSleep.staleDecayThreshold}, archiveDecay=${phases.lightSleep.archiveDecayThreshold}, filterStale=${phases.lightSleep.filterStaleEnabled}, lastRun=${meta.lastExtractionAt ?? "never"}`,
    `rem: enabled=${phases.rem.enabled}, cadenceMs=${phases.rem.cadenceMs}, similarity=${phases.rem.similarityThreshold}, minCluster=${phases.rem.minClusterSize}, maxPerRun=${phases.rem.maxPerRun}, minIntervalMs=${phases.rem.minIntervalMs}, lastRun=${meta.lastConsolidationAt ?? "never"}`,
    `deepSleep: enabled=${phases.deepSleep.enabled}, cadenceMs=${phases.deepSleep.cadenceMs}, versioning=${phases.deepSleep.versioningEnabled}, versioningMaxPerPage=${phases.deepSleep.versioningMaxPerPage}, lastRun=${deepSleepLastRun ?? "never"}`,
  ];

  return {
    key: "dreams_phases",
    status: deepSleepLastRunWarning ? "warn" : "ok",
    summary: `Dreams pipeline phases: ${phaseLines.join("; ")}${deepSleepLastRunWarning ? `; ${deepSleepLastRunWarning}` : ""}`,
    remediation: deepSleepLastRunWarning
      ? "Inspect state/memory-governance/runs and repair or remove unreadable governance run artifacts."
      : undefined,
    details: {
      lightSleep: {
        enabled: phases.lightSleep.enabled,
        cadenceMs: phases.lightSleep.cadenceMs,
        promoteHeatThreshold: phases.lightSleep.promoteHeatThreshold,
        staleDecayThreshold: phases.lightSleep.staleDecayThreshold,
        archiveDecayThreshold: phases.lightSleep.archiveDecayThreshold,
        filterStaleEnabled: phases.lightSleep.filterStaleEnabled,
        lastRun: meta.lastExtractionAt ?? null,
      },
      rem: {
        enabled: phases.rem.enabled,
        cadenceMs: phases.rem.cadenceMs,
        similarityThreshold: phases.rem.similarityThreshold,
        minClusterSize: phases.rem.minClusterSize,
        maxPerRun: phases.rem.maxPerRun,
        minIntervalMs: phases.rem.minIntervalMs,
        lastRun: meta.lastConsolidationAt ?? null,
      },
      deepSleep: {
        enabled: phases.deepSleep.enabled,
        cadenceMs: phases.deepSleep.cadenceMs,
        versioningEnabled: phases.deepSleep.versioningEnabled,
        versioningMaxPerPage: phases.deepSleep.versioningMaxPerPage,
        lastRun: deepSleepLastRun,
        warning: deepSleepLastRunWarning,
      },
    },
  };
}

function summarizeSecurityMitigations(
  config: Pick<
    PluginConfig,
    | "recallCrossNamespaceBudgetEnabled"
    | "recallCrossNamespaceBudgetWindowMs"
    | "recallCrossNamespaceBudgetSoftLimit"
    | "recallCrossNamespaceBudgetHardLimit"
    | "recallAuditAnomalyDetectionEnabled"
    | "recallAuditAnomalyWindowMs"
    | "recallAuditAnomalyRepeatQueryLimit"
    | "recallAuditAnomalyNamespaceWalkLimit"
    | "recallAuditAnomalyHighCardinalityLimit"
    | "recallAuditAnomalyRapidFireLimit" | "recallSingleFlightEnabled"
  >,
): OperatorDoctorCheck {
  // Resolve access-setup gates once (#1566 Cluster B).
  const accessCaps = resolveAccessSetupCapabilities(config);
  const budgetEnabled = accessCaps.recallCrossNamespaceBudget;
  const anomalyEnabled = accessCaps.recallAuditAnomalyDetection;

  if (!budgetEnabled && !anomalyEnabled) {
    return {
      key: "security_mitigations",
      status: "warn",
      summary: "Memory-extraction mitigations are disabled (cross-namespace budget and anomaly detection off).",
      remediation: "Enable recallCrossNamespaceBudgetEnabled and/or recallAuditAnomalyDetectionEnabled for production deployments. See docs/security/memory-extraction-threat-model.md.",
      details: {
        budgetEnabled: false,
        anomalyDetectionEnabled: false,
      },
    };
  }

  const details: Record<string, unknown> = {
    budgetEnabled,
    anomalyDetectionEnabled: anomalyEnabled,
  };

  if (budgetEnabled) {
    details.budgetConfig = {
      windowMs: config.recallCrossNamespaceBudgetWindowMs,
      softLimit: config.recallCrossNamespaceBudgetSoftLimit,
      hardLimit: config.recallCrossNamespaceBudgetHardLimit,
    };
  }

  if (anomalyEnabled) {
    details.anomalyConfig = {
      windowMs: config.recallAuditAnomalyWindowMs,
      repeatQueryLimit: config.recallAuditAnomalyRepeatQueryLimit,
      namespaceWalkLimit: config.recallAuditAnomalyNamespaceWalkLimit,
      highCardinalityLimit: config.recallAuditAnomalyHighCardinalityLimit,
      rapidFireLimit: config.recallAuditAnomalyRapidFireLimit,
    };
  }

  return {
    key: "security_mitigations",
    status: "ok",
    summary: `Memory-extraction mitigation config enabled: ${budgetEnabled ? "budget" : ""}${budgetEnabled && anomalyEnabled ? ", " : ""}${anomalyEnabled ? "anomaly detection" : ""}.`,
    details: { ...details, configOnly: true },
  };
}

/**
 * Observation throughput check for `remnic doctor` (issue #685).
 *
 * Reads the extraction-judge verdict ledger to surface:
 *  - total observations (verdicts) recorded
 *  - accept / reject / defer breakdown
 *  - most-recent `observedAt` timestamp
 *
 * The check is purely informational (always `ok`): a missing or empty
 * ledger is the expected state on a fresh install and is never an error.
 * This closes the `*(future)*` item deferred in `docs/trace-to-primitive.md`.
 */
export async function summarizeObservationThroughput(
  memoryDir: string,
): Promise<OperatorDoctorCheck> {
  try {
    const stats = await readJudgeVerdictStats(memoryDir);
    if (stats.total === 0) {
      return {
        key: "observations",
        status: "ok",
        summary: "No observations recorded yet (extraction-judge telemetry ledger is empty or missing).",
        details: { total: 0, accept: 0, reject: 0, defer: 0, lastObservedAt: null },
      };
    }
    const acceptPct = ((stats.accept / stats.total) * 100).toFixed(1);
    const rejectPct = ((stats.reject / stats.total) * 100).toFixed(1);
    const deferPct = ((stats.defer / stats.total) * 100).toFixed(1);
    return {
      key: "observations",
      status: "ok",
      summary: `${stats.total} observations recorded: accept=${acceptPct}%, reject=${rejectPct}%, defer=${deferPct}%. Last observed: ${stats.lastTs ?? "unknown"}.`,
      details: {
        total: stats.total,
        accept: stats.accept,
        reject: stats.reject,
        defer: stats.defer,
        deferCapTriggered: stats.deferCapTriggered,
        deferRate: stats.deferRate,
        meanElapsedMs: stats.meanElapsedMs,
        firstObservedAt: stats.firstTs ?? null,
        lastObservedAt: stats.lastTs ?? null,
      },
    };
  } catch (err) {
    return {
      key: "observations",
      status: "warn",
      summary: "Could not read observation telemetry ledger.",
      remediation: "Retry `remnic doctor` after ensuring the memory state directory is readable.",
      details: { error: String(err) },
    };
  }
}

/**
 * Tombstone non-resurrection invariant status for `remnic doctor`
 * (issue #1579).
 *
 * Reports:
 *   - active tombstone count (excluding revoked)
 *   - revoked count (re-allowed via the review queue)
 *   - last append timestamp
 *   - corrupted-line count (skipped, not crashed — rule 34/18)
 *   - rebuild staleness (whether the in-memory index loaded cleanly)
 *
 * Always informational: a disabled or empty tombstone store is the expected
 * cold-install state and is never an error. A non-zero corrupted-line count
 * surfaces as `warn` so operators know a rebuild (`remnic doctor
 * --rebuild-tombstones`) will repair the log.
 */
export async function summarizeTombstoneStatus(
  storage: StorageManager,
): Promise<OperatorDoctorCheck> {
  try {
    const stats = await storage.getTombstoneStats();
    if (stats === null) {
      return {
        key: "tombstones",
        status: "ok",
        summary: "Tombstone non-resurrection invariant is disabled (tombstonesEnabled=false).",
        details: { enabled: false },
      };
    }
    const corrupted = stats.corruptedLines > 0;
    const parts = [
      `${stats.count} active tombstone(s)`,
      ...(stats.revoked > 0 ? [`${stats.revoked} revoked`] : []),
    ];
    if (stats.lastAppendAt) {
      parts.push(`last append ${stats.lastAppendAt}`);
    }
    if (corrupted) {
      parts.push(`${stats.corruptedLines} corrupted line(s) skipped`);
    }
    return {
      key: "tombstones",
      status: corrupted ? "warn" : "ok",
      summary:
        `Tombstone invariant enabled. ${parts.join(", ")}. ` +
        (corrupted
          ? "Run `remnic doctor --rebuild-tombstones` to repair the log."
          : "Re-observation of retired facts is blocked at the storage chokepoint."),
      remediation: corrupted
        ? "Rebuild the tombstone log from retired memories on disk."
        : undefined,
      details: {
        enabled: true,
        count: stats.count,
        revoked: stats.revoked,
        lastAppendAt: stats.lastAppendAt,
        corruptedLines: stats.corruptedLines,
        loaded: stats.loaded,
      },
    };
  } catch (err) {
    return {
      key: "tombstones",
      status: "warn",
      summary: "Could not read tombstone store stats.",
      remediation: "Ensure the memory state directory is readable and rerun `remnic doctor`.",
      details: { error: String(err) },
    };
  }
}

export async function summarizeConsolidationProvenance(
  storage: StorageManager,
  config: Pick<PluginConfig, "memoryDir"> & { versioningSidecarDir?: string },
): Promise<OperatorDoctorCheck> {
  let report: ConsolidationProvenanceReport;
  try {
    report = await runConsolidationProvenanceCheck({
      storage,
      memoryDir: config.memoryDir,
      // Honor the configured sidecar directory (PR #634 review): when an
      // operator overrides `versioningSidecarDir`, the default `.versions`
      // would point at the wrong location and every entry would report as
      // missing.  Undefined falls back to the helper's default.
      sidecarDir: config.versioningSidecarDir,
    });
  } catch (err) {
    return {
      key: "consolidation_provenance",
      status: "warn",
      summary: "Could not run consolidation-provenance integrity check.",
      remediation: "Ensure the memory directory is readable and rerun `remnic doctor`.",
      details: { error: String(err) },
    };
  }

  if (report.issues.length === 0) {
    return {
      key: "consolidation_provenance",
      status: "ok",
      summary:
        report.withProvenance === 0
          ? "No consolidation-provenance memories on disk yet."
          : `${report.withProvenance} consolidation-provenance memories verified (no broken references).`,
      details: report,
    };
  }

  return {
    key: "consolidation_provenance",
    status: "warn",
    summary: `${report.issues.length} consolidation-provenance integrity issue(s) detected across ${report.withProvenance} memories with provenance frontmatter.`,
    remediation:
      "Broken pointers are informational. Inspect flagged memories, and if they should resolve, re-snapshot via a consolidation pass or accept pruning.",
    details: report,
  };
}

function getMemoryAgeBand(memory: MemoryFile, now: Date): string {
  const created = Date.parse(memory.frontmatter.created ?? "");
  if (!Number.isFinite(created)) return "unknown";
  const ageDays = Math.max(0, Math.floor((now.getTime() - created) / 86_400_000));
  if (ageDays < 7) return "0_6d";
  if (ageDays < 30) return "7_29d";
  if (ageDays < 90) return "30_89d";
  return "90d_plus";
}

async function dirSize(targetPath: string): Promise<number> {
  try {
    const info = await stat(targetPath);
    if (info.isFile()) return info.size;
    if (!info.isDirectory()) return 0;
  } catch {
    return 0;
  }

  let total = 0;
  let entries;
  try {
    entries = await readdir(targetPath, { withFileTypes: true });
  } catch {
    return 0;
  }
  for (const entry of entries) {
    total += await dirSize(path.join(targetPath, entry.name));
  }
  return total;
}

async function summarizeStorageFootprint(memoryDir: string): Promise<{ bytes: number; byTopLevel: Record<string, number> }> {
  const topLevel = [
    "facts",
    "entities",
    "questions",
    "corrections",
    "artifacts",
    "state",
    "identity",
    "namespaces",
    "summaries",
    "profile.md",
  ];
  const byTopLevel: Record<string, number> = {};
  let bytes = 0;
  for (const name of topLevel) {
    const size = await dirSize(path.join(memoryDir, name));
    if (size > 0) {
      byTopLevel[name] = size;
      bytes += size;
    }
  }
  return { bytes, byTopLevel };
}

export async function runOperatorInventory(options: OperatorInventoryOptions): Promise<OperatorInventoryReport> {
  const now = options.now ?? new Date();
  const config = options.orchestrator.config;
  const namespaceEntries = await listNamespaces({ config });
  const uniqueRootEntries = new Map<string, { namespace: string; rootDir: string }>();
  for (const entry of namespaceEntries) {
    if (!uniqueRootEntries.has(entry.rootDir)) {
      uniqueRootEntries.set(entry.rootDir, { namespace: entry.namespace, rootDir: entry.rootDir });
    }
  }
  const categories: Record<string, number> = {};
  const statuses: Record<string, number> = {};
  const ageBands: Record<string, number> = {
    "0_6d": 0,
    "7_29d": 0,
    "30_89d": 0,
    "90d_plus": 0,
    unknown: 0,
  };
  const namespaces: OperatorInventoryNamespaceSummary[] = [];
  let totalMemories = 0;
  let totalEntities = 0;
  let archived = 0;
  let pendingReview = 0;
  let quarantined = 0;
  let rejected = 0;

  for (const entry of uniqueRootEntries.values()) {
    // Disable the hot-memories cache for these transient, one-shot inventory
    // reads (issue #1902, Codex Medium). Each namespace root is read exactly once
    // here; caching gives no benefit and would warm+RETAIN the full corpus under
    // the process-wide gate/TTL (this path bypasses NamespaceStorageRouter, so
    // the root is never registered in the per-dir maps). Disabling sidesteps both
    // the cross-namespace gate/TTL inheritance and the retained-memory footprint.
    const storage = new StorageManager(entry.rootDir, undefined, false);
    const memories = await storage.readAllMemories();
    const entities = await storage.readAllEntityFiles();
    namespaces.push({
      namespace: entry.namespace,
      memoryCount: memories.length,
      entityCount: entities.length,
    });
    totalMemories += memories.length;
    totalEntities += entities.length;
    for (const memory of memories) {
      const category = memory.frontmatter.category;
      categories[category] = (categories[category] ?? 0) + 1;
      const status = memory.frontmatter.status ?? "active";
      statuses[status] = (statuses[status] ?? 0) + 1;
      ageBands[getMemoryAgeBand(memory, now)] += 1;
      if (status === "archived") archived += 1;
      if (status === "pending_review") pendingReview += 1;
      if (status === "quarantined") quarantined += 1;
      if (status === "rejected") rejected += 1;
    }
  }

  const defaultStorage = new StorageManager(config.memoryDir);
  const profile = await defaultStorage.readProfile();
  const footprint = await summarizeStorageFootprint(config.memoryDir);
  const reviewRunId = (await listMemoryGovernanceRuns(config.memoryDir))[0];
  let reviewQueue = 0;
  if (reviewRunId) {
    try {
      reviewQueue = (await readMemoryGovernanceRunArtifact(config.memoryDir, reviewRunId)).reviewQueue.length;
    } catch {
      reviewQueue = 0;
    }
  }
  const conversationIndex = await options.orchestrator.conversationIndexCoordinator.getHealth();
  const nativeKnowledgeStatus = await summarizeNativeKnowledgeStatus(config);

  return {
    schemaVersion: 1,
    generatedAt: now.toISOString(),
    memoryDir: config.memoryDir,
    totals: {
      memories: totalMemories,
      entities: totalEntities,
      namespaces: namespaceEntries.length,
      reviewQueue,
      storageBytes: footprint.bytes,
    },
    categories,
    statuses,
    namespaces,
    ageBands,
    profile: {
      exists: profile.length > 0,
      chars: profile.length,
      lines: profile.length > 0 ? profile.split("\n").length : 0,
    },
    storageFootprint: footprint,
    archivePressure: {
      archived,
      pendingReview,
      quarantined,
      rejected,
    },
    conversationIndex: {
      enabled: conversationIndex.enabled,
      backend: conversationIndex.backend,
      status: conversationIndex.status,
      chunkDocCount: conversationIndex.chunkDocCount,
      lastUpdateAt: conversationIndex.lastUpdateAt,
    },
    nativeKnowledge: {
      enabled: nativeKnowledgeStatus.enabled,
      curatedIncludeSync: nativeKnowledgeStatus.curatedIncludeSync,
      obsidianSync: nativeKnowledgeStatus.obsidianSync,
      openclawWorkspaceSync: nativeKnowledgeStatus.openclawWorkspaceSync,
    },
  };
}

export async function runBenchmarkRecall(options: BenchmarkRecallOptions): Promise<BenchmarkRecallReport> {
  const now = options.now ?? new Date();
  const status = await getEvalHarnessStatus({
    memoryDir: options.config.memoryDir,
    evalStoreDir: options.config.evalStoreDir,
    enabled: resolveEvalCapabilities(options.config).evalHarness,
    shadowModeEnabled: resolveEvalCapabilities(options.config).evalShadowMode,
    baselineSnapshotsEnabled: resolveEvalCapabilities(options.config).benchmarkBaselineSnapshots,
    memoryRedTeamBenchEnabled: resolveEvalCapabilities(options.config).memoryRedTeamBench,
  });

  if (options.createSnapshot && options.snapshotId) {
    const snapshot = await createEvalBaselineSnapshot({
      memoryDir: options.config.memoryDir,
      evalStoreDir: options.config.evalStoreDir,
      baselineSnapshotsEnabled: resolveEvalCapabilities(options.config).benchmarkBaselineSnapshots,
      snapshotId: options.snapshotId,
      notes: options.snapshotNotes,
      gitRef: options.gitRef,
      createdAt: options.createdAt,
    });
    return {
      schemaVersion: 1,
      generatedAt: now.toISOString(),
      mode: "snapshot",
      status,
      snapshot: {
        targetPath: snapshot.targetPath,
        snapshotId: snapshot.snapshot.snapshotId,
      },
    };
  }

  if (options.baseEvalStoreDir && options.candidateEvalStoreDir) {
    const ciGate = await runEvalBenchmarkCiGate({
      baseEvalStoreDir: options.baseEvalStoreDir,
      candidateEvalStoreDir: options.candidateEvalStoreDir,
    });
    return {
      schemaVersion: 1,
      generatedAt: now.toISOString(),
      mode: "ci-gate",
      status,
      ciGate,
    };
  }

  if (options.snapshotId) {
    const baselineReport = await runEvalBaselineDeltaReport({
      memoryDir: options.config.memoryDir,
      evalStoreDir: options.config.evalStoreDir,
      benchmarkDeltaReporterEnabled: resolveEvalCapabilities(options.config).benchmarkDeltaReporter,
      snapshotId: options.snapshotId,
    });
    return {
      schemaVersion: 1,
      generatedAt: now.toISOString(),
      mode: "baseline-report",
      status,
      baselineReport,
    };
  }

  if (options.validatePath) {
    const validate = await validateEvalBenchmarkPack(options.validatePath, {
      memoryRedTeamBenchEnabled: resolveEvalCapabilities(options.config).memoryRedTeamBench,
    });
    return {
      schemaVersion: 1,
      generatedAt: now.toISOString(),
      mode: "validate",
      status,
      validate,
    };
  }

  return {
    schemaVersion: 1,
    generatedAt: now.toISOString(),
    mode: "status",
    status,
  };
}

export async function runOperatorRepair(options: OperatorRepairOptions): Promise<OperatorRepairReport> {
  const now = options.now ?? new Date();
  const dryRun = options.dryRun === true || options.apply !== true;
  const sessionCheck = await analyzeSessionIntegrity({ memoryDir: options.config.memoryDir });
  const sessionRepairPlan = planSessionRepair({
    report: sessionCheck,
    dryRun,
    allowSessionFileRepair: options.allowSessionFileRepair,
    sessionFilesDir: options.sessionFilesDir,
  });
  const sessionRepairApply = await applySessionRepair({
    plan: sessionRepairPlan,
  });
  // Resolve graph-construction gates once for this diagnostic (#1566 Cluster A).
  const graphCaps = resolveGraphConstructionCapabilities(options.config);
  const graphHealth = await analyzeGraphHealth(options.config.memoryDir, {
    entityGraphEnabled: graphCaps.entityGraph,
    timeGraphEnabled: graphCaps.timeGraph,
    causalGraphEnabled: graphCaps.causalGraph,
    includeRepairGuidance: true,
  });
  return {
    schemaVersion: 1,
    generatedAt: now.toISOString(),
    dryRun,
    sessionCheck,
    sessionRepairPlan,
    sessionRepairApply,
    graphHealth,
  };
}

import { stat } from "node:fs/promises";
import { launchProcess } from "../runtime/child-process.js";

export interface TailscaleCommandResult {
  code: number;
  stdout: string;
  stderr: string;
}

export type TailscaleCommandRunner = (
  command: string,
  args: string[],
  options?: { timeoutMs?: number },
) => Promise<TailscaleCommandResult>;

export interface TailscaleStatus {
  available: boolean;
  running: boolean;
  backendState?: string;
  version?: string;
  selfHostname?: string;
  selfIp?: string;
}

export interface TailscaleSyncOptions {
  sourceDir: string;
  destination: string;
  delete?: boolean;
  dryRun?: boolean;
  extraArgs?: string[];
}

export interface TailscaleHelperOptions {
  tailscaleBinary?: string;
  rsyncBinary?: string;
  timeoutMs?: number;
  runner?: TailscaleCommandRunner;
}

interface TailscaleStatusJson {
  BackendState?: string;
  Version?: string;
  Self?: {
    HostName?: string;
    TailscaleIPs?: string[];
  };
}

export class TailscaleHelper {
  private readonly tailscaleBinary: string;
  private readonly rsyncBinary: string;
  private readonly timeoutMs: number;
  private readonly runner: TailscaleCommandRunner;

  constructor(options: TailscaleHelperOptions = {}) {
    this.tailscaleBinary = options.tailscaleBinary ?? "tailscale";
    this.rsyncBinary = options.rsyncBinary ?? "rsync";
    this.timeoutMs = options.timeoutMs ?? 10_000;
    this.runner = options.runner ?? defaultCommandRunner;
  }

  async isAvailable(): Promise<boolean> {
    const result = await this.runner(this.tailscaleBinary, ["version"], { timeoutMs: this.timeoutMs });
    return result.code === 0;
  }

  async status(): Promise<TailscaleStatus> {
    const available = await this.isAvailable();
    if (!available) {
      return { available: false, running: false };
    }

    const result = await this.runner(this.tailscaleBinary, ["status", "--json"], { timeoutMs: this.timeoutMs });
    if (result.code !== 0) {
      return { available: true, running: false };
    }

    let parsed: TailscaleStatusJson;
    try {
      parsed = JSON.parse(result.stdout) as TailscaleStatusJson;
    } catch {
      throw new Error("tailscale status returned invalid JSON");
    }

    const backendState = parsed.BackendState ?? "";
    return {
      available: true,
      running: backendState === "Running",
      backendState,
      version: parsed.Version,
      selfHostname: parsed.Self?.HostName,
      selfIp: parsed.Self?.TailscaleIPs?.[0],
    };
  }

  async syncDirectory(options: TailscaleSyncOptions): Promise<void> {
    await assertReadableDirectory(options.sourceDir);

    const tailscaleStatus = await this.status();
    if (!tailscaleStatus.available) {
      throw new Error("tailscale is not installed or not available in PATH");
    }
    if (!tailscaleStatus.running) {
      throw new Error("tailscale daemon is not running");
    }

    const args: string[] = ["-az"];
    if (options.delete) args.push("--delete");
    if (options.dryRun) args.push("--dry-run");
    if (options.extraArgs?.length) args.push(...options.extraArgs);

    const sourceWithTrailingSlash = options.sourceDir.endsWith("/") ? options.sourceDir : `${options.sourceDir}/`;
    args.push(sourceWithTrailingSlash, options.destination);

    const result = await this.runner(this.rsyncBinary, args);
    if (result.code !== 0) {
      const stderr = result.stderr.trim();
      throw new Error(stderr ? `rsync failed: ${stderr}` : "rsync failed");
    }
  }
}

async function assertReadableDirectory(dir: string): Promise<void> {
  const info = await stat(dir);
  if (!info.isDirectory()) {
    throw new Error(`sourceDir must be a directory: ${dir}`);
  }
}

const defaultCommandRunner: TailscaleCommandRunner = (command, args, options) => {
  return new Promise((resolve) => {
    const child = launchProcess(command, args, {
      stdio: ["ignore", "pipe", "pipe"],
    });
    if (!child.stdout || !child.stderr) {
      resolve({ code: 1, stdout: "", stderr: "command pipes unavailable" });
      return;
    }

    let stdout = "";
    let stderr = "";
    let settled = false;

    const timeoutMs = options?.timeoutMs;
    const timeout = typeof timeoutMs === "number" && timeoutMs > 0
      ? setTimeout(() => {
          if (settled) return;
          settled = true;
          child.kill("SIGKILL");
          resolve({
            code: 124,
            stdout,
            stderr: stderr || "command timed out",
          });
        }, timeoutMs)
      : null;

    child.stdout.on("data", (chunk: Buffer) => {
      stdout += chunk.toString("utf-8");
    });
    child.stderr.on("data", (chunk: Buffer) => {
      stderr += chunk.toString("utf-8");
    });

    child.on("error", () => {
      if (settled) return;
      settled = true;
      if (timeout) clearTimeout(timeout);
      resolve({ code: 1, stdout, stderr });
    });

    child.on("close", (code) => {
      if (settled) return;
      settled = true;
      if (timeout) clearTimeout(timeout);
      resolve({ code: code ?? 1, stdout, stderr });
    });
  });
};

import path from "node:path";
import { randomUUID } from "node:crypto";
import { mkdir, readdir, readFile, rm, writeFile } from "node:fs/promises";
import type {
  CreateWorkProjectInput,
  CreateWorkTaskInput,
  UpdateWorkProjectInput,
  UpdateWorkTaskInput,
  WorkProject,
  WorkProjectStatus,
  WorkTask,
  WorkTaskListFilter,
  WorkTaskStatus,
} from "./types.js";
import { isErrnoCode } from "../utils/errno.js";

const TASK_TRANSITIONS: Record<WorkTaskStatus, Set<WorkTaskStatus>> = {
  todo: new Set(["in_progress", "blocked", "cancelled"]),
  in_progress: new Set(["todo", "blocked", "done", "cancelled"]),
  blocked: new Set(["todo", "in_progress", "cancelled"]),
  done: new Set(),
  cancelled: new Set(),
};

const PROJECT_MUTATION_CHAINS = new Map<string, Promise<unknown>>();
const TASK_MUTATION_CHAINS = new Map<string, Promise<unknown>>();

function serializeFrontmatter(values: object): string {
  const lines = Object.entries(values).map(([k, v]) => `${k}: ${JSON.stringify(v)}`);
  return `---\n${lines.join("\n")}\n---`;
}

function parseFrontmatter(raw: string): { data: Record<string, unknown>; body: string } | null {
  const match = raw.match(/^---\n([\s\S]*?)\n---\n?([\s\S]*)$/);
  if (!match) return null;
  const fm = match[1] ?? "";
  const body = match[2] ?? "";
  const data: Record<string, unknown> = {};
  for (const line of fm.split("\n")) {
    if (!line.trim()) continue;
    const idx = line.indexOf(":");
    if (idx <= 0) continue;
    const key = line.slice(0, idx).trim();
    const rawValue = line.slice(idx + 1).trim();
    try {
      data[key] = JSON.parse(rawValue);
    } catch {
      data[key] = rawValue;
    }
  }
  return { data, body };
}

function toSafeSlug(value: string): string {
  let slug = value.toLowerCase().trim().replace(/[^a-z0-9]+/g, "-");
  // Trim leading/trailing dashes without ReDoS-prone anchored quantifiers
  let start = 0;
  while (start < slug.length && slug[start] === "-") start++;
  let end = slug.length;
  while (end > start && slug[end - 1] === "-") end--;
  return slug.slice(start, end).slice(0, 80);
}

export const WORK_ID_PATTERN = /^[A-Za-z0-9][A-Za-z0-9-]{0,127}$/;

function makeId(prefix: string, titleOrName: string, now: Date): string {
  const slug = toSafeSlug(titleOrName) || "item";
  const nonce = randomUUID().slice(0, 8);
  return `${prefix}-${now.getTime()}-${slug}-${nonce}`;
}

function assertValidWorkId(id: string, kind: "task" | "project"): void {
  if (!WORK_ID_PATTERN.test(id)) {
    throw new Error(`invalid ${kind} id: ${id}`);
  }
}

function ensureString(value: unknown, fallback = ""): string {
  return typeof value === "string" ? value : fallback;
}

function ensureStringArray(value: unknown): string[] {
  if (!Array.isArray(value)) return [];
  return value.filter((entry) => typeof entry === "string");
}

function ensureNullableString(value: unknown): string | null {
  return typeof value === "string" ? value : null;
}

function ensureTaskStatus(value: unknown): WorkTaskStatus {
  if (value === "todo" || value === "in_progress" || value === "blocked" || value === "done" || value === "cancelled") {
    return value;
  }
  return "todo";
}

function ensureTaskPriority(value: unknown): WorkTask["priority"] {
  if (value === "low" || value === "medium" || value === "high") return value;
  return "medium";
}

function ensureProjectStatus(value: unknown): WorkProjectStatus {
  if (value === "active" || value === "on_hold" || value === "completed" || value === "archived") return value;
  return "active";
}

export class WorkStorage {
  private readonly tasksDir: string;
  private readonly projectsDir: string;

  constructor(private readonly memoryDir: string) {
    this.tasksDir = path.join(memoryDir, "work", "tasks");
    this.projectsDir = path.join(memoryDir, "work", "projects");
  }

  async ensureDirectories(): Promise<void> {
    await mkdir(this.tasksDir, { recursive: true });
    await mkdir(this.projectsDir, { recursive: true });
  }

  private taskPath(id: string): string {
    assertValidWorkId(id, "task");
    return path.join(this.tasksDir, `${id}.md`);
  }

  private projectPath(id: string): string {
    assertValidWorkId(id, "project");
    return path.join(this.projectsDir, `${id}.md`);
  }

  private serializeTask(task: WorkTask): string {
    return `${serializeFrontmatter(task)}\n\n${task.description}\n`;
  }

  private serializeProject(project: WorkProject): string {
    return `${serializeFrontmatter(project)}\n\n${project.description}\n`;
  }

  private async writeNewTask(task: WorkTask): Promise<void> {
    try {
      await writeFile(this.taskPath(task.id), this.serializeTask(task), { encoding: "utf-8", flag: "wx" });
    } catch (error) {
      if (isErrnoCode(error, "EEXIST")) {
        throw new Error(`task already exists: ${task.id}`);
      }
      throw error;
    }
  }

  private async writeTaskRecord(task: WorkTask): Promise<void> {
    await writeFile(this.taskPath(task.id), this.serializeTask(task), "utf-8");
  }

  private async writeNewProject(project: WorkProject): Promise<void> {
    try {
      await writeFile(this.projectPath(project.id), this.serializeProject(project), { encoding: "utf-8", flag: "wx" });
    } catch (error) {
      if (isErrnoCode(error, "EEXIST")) {
        throw new Error(`project already exists: ${project.id}`);
      }
      throw error;
    }
  }

  private async writeProjectRecord(project: WorkProject): Promise<void> {
    await writeFile(this.projectPath(project.id), this.serializeProject(project), "utf-8");
  }

  private async enqueueProjectMutation<T>(projectId: string, op: () => Promise<T>): Promise<T> {
    const mutationKey = this.projectPath(projectId);
    const previous = PROJECT_MUTATION_CHAINS.get(mutationKey) ?? Promise.resolve();
    const run = previous.catch(() => undefined).then(op);
    const cleanup = run.then(() => undefined, () => undefined).then(() => {
      if (PROJECT_MUTATION_CHAINS.get(mutationKey) === cleanup) {
        PROJECT_MUTATION_CHAINS.delete(mutationKey);
      }
    });
    PROJECT_MUTATION_CHAINS.set(mutationKey, cleanup);
    return run;
  }

  private async enqueueTaskMutation<T>(taskId: string, op: () => Promise<T>): Promise<T> {
    const mutationKey = this.taskPath(taskId);
    const previous = TASK_MUTATION_CHAINS.get(mutationKey) ?? Promise.resolve();
    const run = previous.catch(() => undefined).then(op);
    const cleanup = run.then(() => undefined, () => undefined).then(() => {
      if (TASK_MUTATION_CHAINS.get(mutationKey) === cleanup) {
        TASK_MUTATION_CHAINS.delete(mutationKey);
      }
    });
    TASK_MUTATION_CHAINS.set(mutationKey, cleanup);
    return run;
  }

  private parseTask(raw: string): WorkTask | null {
    const parsed = parseFrontmatter(raw);
    if (!parsed) return null;
    const d = parsed.data;
    return {
      id: ensureString(d.id),
      title: ensureString(d.title),
      description: ensureString(d.description, parsed.body.trim()),
      status: ensureTaskStatus(d.status),
      priority: ensureTaskPriority(d.priority),
      owner: ensureNullableString(d.owner),
      assignee: ensureNullableString(d.assignee),
      projectId: ensureNullableString(d.projectId),
      tags: ensureStringArray(d.tags),
      dueAt: ensureNullableString(d.dueAt),
      createdAt: ensureString(d.createdAt),
      updatedAt: ensureString(d.updatedAt),
    };
  }

  private parseProject(raw: string): WorkProject | null {
    const parsed = parseFrontmatter(raw);
    if (!parsed) return null;
    const d = parsed.data;
    return {
      id: ensureString(d.id),
      name: ensureString(d.name),
      description: ensureString(d.description, parsed.body.trim()),
      status: ensureProjectStatus(d.status),
      owner: ensureNullableString(d.owner),
      tags: ensureStringArray(d.tags),
      taskIds: ensureStringArray(d.taskIds),
      createdAt: ensureString(d.createdAt),
      updatedAt: ensureString(d.updatedAt),
    };
  }

  async createTask(input: CreateWorkTaskInput, now = new Date()): Promise<WorkTask> {
    await this.ensureDirectories();
    const timestamp = now.toISOString();
    const task: WorkTask = {
      id: input.id ?? makeId("task", input.title, now),
      title: input.title,
      description: input.description ?? "",
      status: input.status ?? "todo",
      priority: input.priority ?? "medium",
      owner: input.owner ?? null,
      assignee: input.assignee ?? null,
      projectId: input.projectId ?? null,
      tags: input.tags ?? [],
      dueAt: input.dueAt ?? null,
      createdAt: timestamp,
      updatedAt: timestamp,
    };

    if (task.projectId) {
      const project = await this.getProject(task.projectId);
      if (!project) {
        throw new Error(`project not found: ${task.projectId}`);
      }
    }

    if (task.projectId) {
      let taskFileCreated = false;
      try {
        await this.writeNewTask(task);
        taskFileCreated = true;
        await this.addTaskIdToProject(task.projectId, task.id, now);
      } catch (error) {
        if (taskFileCreated) {
          await rm(this.taskPath(task.id), { force: true }).catch(() => undefined);
        }
        throw error;
      }
    } else {
      await this.writeNewTask(task);
    }

    return task;
  }

  async getTask(id: string): Promise<WorkTask | null> {
    try {
      const raw = await readFile(this.taskPath(id), "utf-8");
      return this.parseTask(raw);
    } catch {
      return null;
    }
  }

  async listTasks(filter?: WorkTaskListFilter): Promise<WorkTask[]> {
    await this.ensureDirectories();
    const entries = await readdir(this.tasksDir, { withFileTypes: true });
    const out: WorkTask[] = [];
    for (const entry of entries) {
      if (!entry.isFile() || !entry.name.endsWith(".md")) continue;
      const raw = await readFile(path.join(this.tasksDir, entry.name), "utf-8");
      const task = this.parseTask(raw);
      if (!task) continue;
      if (filter?.status && task.status !== filter.status) continue;
      if (filter?.owner && task.owner !== filter.owner) continue;
      if (filter?.assignee && task.assignee !== filter.assignee) continue;
      if (filter?.projectId && task.projectId !== filter.projectId) continue;
      out.push(task);
    }
    out.sort((a, b) => a.createdAt.localeCompare(b.createdAt));
    return out;
  }

  async updateTask(
    id: string,
    patch: UpdateWorkTaskInput,
    now = new Date(),
    options?: { skipStatusTransitionValidation?: boolean },
  ): Promise<WorkTask | null> {
    return this.enqueueTaskMutation(id, async () => this.updateTaskUnlocked(id, patch, now, options));
  }

  private async updateTaskUnlocked(
    id: string,
    patch: UpdateWorkTaskInput,
    now = new Date(),
    options?: { skipStatusTransitionValidation?: boolean },
  ): Promise<WorkTask | null> {
    const existing = await this.getTask(id);
    if (!existing) return null;

    const projectIdPatched = Object.prototype.hasOwnProperty.call(patch, "projectId");
    const statusPatched = Object.prototype.hasOwnProperty.call(patch, "status");
    const nextProjectId = projectIdPatched ? patch.projectId ?? null : existing.projectId;

    if (
      statusPatched
      && patch.status
      && existing.status !== patch.status
      && options?.skipStatusTransitionValidation !== true
      && !TASK_TRANSITIONS[existing.status].has(patch.status)
    ) {
      throw new Error(`invalid task status transition: ${existing.status} -> ${patch.status}`);
    }

    if (projectIdPatched && nextProjectId) {
      const nextProject = await this.getProject(nextProjectId);
      if (!nextProject) {
        throw new Error(`project not found: ${nextProjectId}`);
      }
    }

    const next: WorkTask = {
      ...existing,
      ...patch,
      projectId: nextProjectId,
      tags: patch.tags ?? existing.tags,
      updatedAt: now.toISOString(),
    };
    await this.writeTaskRecord(next);
    if (projectIdPatched && existing.projectId !== nextProjectId) {
      try {
        if (nextProjectId) {
          await this.addTaskIdToProject(nextProjectId, id, now);
        }
        if (existing.projectId) {
          await this.removeTaskIdFromProject(existing.projectId, id, now);
        }
      } catch (error) {
        await this.writeTaskRecord(existing);
        if (nextProjectId) {
          await this.removeTaskIdFromProject(nextProjectId, id, now).catch(() => undefined);
        }
        if (existing.projectId) {
          await this.addTaskIdToProject(existing.projectId, id, now).catch(() => undefined);
        }
        throw error;
      }
    }
    return next;
  }

  async transitionTask(id: string, nextStatus: WorkTaskStatus, now = new Date()): Promise<WorkTask> {
    const existing = await this.getTask(id);
    if (!existing) throw new Error(`task not found: ${id}`);
    if (existing.status === nextStatus) return existing;
    if (!TASK_TRANSITIONS[existing.status].has(nextStatus)) {
      throw new Error(`invalid task status transition: ${existing.status} -> ${nextStatus}`);
    }
    const updated = await this.updateTask(id, { status: nextStatus }, now);
    if (!updated) throw new Error(`task not found after update: ${id}`);
    return updated;
  }

  async deleteTask(id: string): Promise<boolean> {
    const existing = await this.getTask(id);
    if (!existing) return false;
    let removedProjectLink = false;
    if (existing.projectId) {
      await this.removeTaskIdFromProject(existing.projectId, id);
      removedProjectLink = true;
    }
    try {
      await rm(this.taskPath(id));
      return true;
    } catch (error) {
      if (isErrnoCode(error, "ENOENT")) return false;
      if (removedProjectLink && existing.projectId) {
        await this.addTaskIdToProject(existing.projectId, id).catch(() => undefined);
      }
      throw error;
    }
  }

  async createProject(input: CreateWorkProjectInput, now = new Date()): Promise<WorkProject> {
    await this.ensureDirectories();
    const timestamp = now.toISOString();
    const project: WorkProject = {
      id: input.id ?? makeId("project", input.name, now),
      name: input.name,
      description: input.description ?? "",
      status: input.status ?? "active",
      owner: input.owner ?? null,
      tags: input.tags ?? [],
      taskIds: [],
      createdAt: timestamp,
      updatedAt: timestamp,
    };
    await this.writeNewProject(project);
    return project;
  }

  async getProject(id: string): Promise<WorkProject | null> {
    try {
      const raw = await readFile(this.projectPath(id), "utf-8");
      return this.parseProject(raw);
    } catch {
      return null;
    }
  }

  async listProjects(): Promise<WorkProject[]> {
    await this.ensureDirectories();
    const entries = await readdir(this.projectsDir, { withFileTypes: true });
    const out: WorkProject[] = [];
    for (const entry of entries) {
      if (!entry.isFile() || !entry.name.endsWith(".md")) continue;
      const raw = await readFile(path.join(this.projectsDir, entry.name), "utf-8");
      const project = this.parseProject(raw);
      if (project) out.push(project);
    }
    out.sort((a, b) => a.createdAt.localeCompare(b.createdAt));
    return out;
  }

  async updateProject(id: string, patch: UpdateWorkProjectInput, now = new Date()): Promise<WorkProject | null> {
    return this.enqueueProjectMutation(id, async () => this.updateProjectUnlocked(id, patch, now));
  }

  private async updateProjectUnlocked(id: string, patch: UpdateWorkProjectInput, now = new Date()): Promise<WorkProject | null> {
    const existing = await this.getProject(id);
    if (!existing) return null;
    const next: WorkProject = {
      ...existing,
      ...patch,
      tags: patch.tags ?? existing.tags,
      taskIds: patch.taskIds ? [...patch.taskIds].sort() : existing.taskIds,
      updatedAt: now.toISOString(),
    };
    await this.writeProjectRecord(next);
    return next;
  }

  async deleteProject(id: string): Promise<boolean> {
    return this.enqueueProjectMutation(id, async () => this.deleteProjectUnlocked(id));
  }

  private async deleteProjectUnlocked(id: string): Promise<boolean> {
    const existing = await this.getProject(id);
    if (!existing) return false;
    const unlinkedTasks: WorkTask[] = [];
    try {
      for (const taskId of existing.taskIds) {
        const task = await this.getTask(taskId);
        if (!task || task.projectId !== id) continue;
        const next: WorkTask = {
          ...task,
          projectId: null,
          updatedAt: new Date().toISOString(),
        };
        await this.writeTaskRecord(next);
        unlinkedTasks.push(task);
      }
      await rm(this.projectPath(id));
      return true;
    } catch (error) {
      for (const task of unlinkedTasks.reverse()) {
        try {
          await this.writeTaskRecord(task);
        } catch {
          // Preserve the original relationship failure for callers.
        }
      }
      if (isErrnoCode(error, "ENOENT")) return false;
      throw error;
    }
  }

  async linkTaskToProject(taskId: string, projectId: string, now = new Date()): Promise<{ task: WorkTask; project: WorkProject }> {
    const task = await this.getTask(taskId);
    if (!task) throw new Error(`task not found: ${taskId}`);
    const project = await this.getProject(projectId);
    if (!project) throw new Error(`project not found: ${projectId}`);

    const updatedTask = await this.updateTask(taskId, { projectId }, now);
    if (!updatedTask) throw new Error(`task not found after update: ${taskId}`);

    const updatedProject = await this.getProject(projectId);
    if (!updatedProject) throw new Error(`project not found after update: ${projectId}`);

    return { task: updatedTask, project: updatedProject };
  }

  private async removeTaskIdFromProject(projectId: string, taskId: string, now = new Date()): Promise<void> {
    await this.enqueueProjectMutation(projectId, async () => {
      const project = await this.getProject(projectId);
      if (!project) return;

      const filtered = project.taskIds.filter((id) => id !== taskId);
      if (filtered.length === project.taskIds.length) return;

      await this.updateProjectUnlocked(projectId, { taskIds: filtered }, now);
    });
  }

  private async addTaskIdToProject(projectId: string, taskId: string, now = new Date()): Promise<void> {
    await this.enqueueProjectMutation(projectId, async () => {
      const project = await this.getProject(projectId);
      if (!project) throw new Error(`project not found: ${projectId}`);

      const taskIds = new Set(project.taskIds);
      taskIds.add(taskId);
      await this.updateProjectUnlocked(projectId, { taskIds: Array.from(taskIds) }, now);
    });
  }
}

import { constants } from "node:fs";
import type { FileHandle } from "node:fs/promises";
import { mkdir, open, readdir, realpath, stat } from "node:fs/promises";
import { createServer, type IncomingMessage, type Server, type ServerResponse } from "node:http";
import { timingSafeEqual } from "node:crypto";
import path from "node:path";
import { pipeline } from "node:stream/promises";
import { URL } from "node:url";

export function hostToUrlAuthority(host: string): string {
  if (host.includes(":") && !host.startsWith("[") && !host.endsWith("]")) {
    return `[${host}]`;
  }
  return host;
}

export interface WebDavAuth {
  username: string;
  password: string;
}

export interface WebDavServerOptions {
  enabled?: boolean;
  host?: string;
  port: number;
  allowlistDirs: string[];
  auth?: WebDavAuth;
}

export interface WebDavServerStatus {
  running: boolean;
  host: string;
  port: number;
  rootCount: number;
}

interface AllowedRoot {
  absolute: string;
  name: string;
}

type WebDavReadOpenResult =
  | { ok: true; handle: FileHandle; size: number }
  | { ok: false; code: number; message: string };

function validateWebDavAuth(auth: WebDavAuth): WebDavAuth {
  if (typeof auth.username !== "string" || auth.username.trim().length === 0) {
    throw new Error("webdav auth.username must be a non-empty string");
  }
  if (typeof auth.password !== "string" || auth.password.trim().length === 0) {
    throw new Error("webdav auth.password must be a non-empty string");
  }
  return auth;
}

export async function openWebDavFileForRead(absolutePath: string): Promise<WebDavReadOpenResult> {
  let handle: FileHandle | null = null;
  try {
    handle = await open(absolutePath, constants.O_RDONLY | constants.O_NOFOLLOW);
    const info = await handle.stat();
    if (!info.isFile()) {
      await handle.close().catch(() => {});
      return { ok: false, code: 403, message: "path is not a file" };
    }
    return { ok: true, handle, size: info.size };
  } catch (err) {
    await handle?.close().catch(() => {});
    const code = (err as NodeJS.ErrnoException).code;
    if (code === "ELOOP") {
      return { ok: false, code: 403, message: "path escaped allowlist via symlink" };
    }
    if (code === "ENOENT" || code === "ENOTDIR") {
      return { ok: false, code: 404, message: "not found" };
    }
    return { ok: false, code: 404, message: "not found" };
  }
}

export class WebDavServer {
  private readonly options: Required<Omit<WebDavServerOptions, "auth">> & Pick<WebDavServerOptions, "auth">;
  private readonly allowedRoots: AllowedRoot[];
  private server: Server | null = null;
  private startPromise: Promise<WebDavServerStatus> | null = null;
  private listening = false;
  private boundPort: number;

  private constructor(
    options: Required<Omit<WebDavServerOptions, "auth">> & Pick<WebDavServerOptions, "auth">,
    allowedRoots: AllowedRoot[]
  ) {
    this.options = options;
    this.allowedRoots = allowedRoots;
    this.boundPort = options.port;
  }

  static async create(input: WebDavServerOptions): Promise<WebDavServer> {
    const options: Required<Omit<WebDavServerOptions, "auth">> & Pick<WebDavServerOptions, "auth"> = {
      enabled: input.enabled ?? false,
      host: input.host ?? "127.0.0.1",
      port: input.port,
      allowlistDirs: input.allowlistDirs,
      auth: input.auth ? validateWebDavAuth(input.auth) : undefined,
    };

    if (!Array.isArray(options.allowlistDirs) || options.allowlistDirs.length === 0) {
      throw new Error("webdav allowlistDirs must include at least one directory");
    }
    if (!Number.isInteger(options.port) || options.port < 0 || options.port > 65535) {
      throw new Error(`invalid webdav port: ${options.port}`);
    }

    const allowedRoots: AllowedRoot[] = [];
    const aliasSet = new Set<string>();
    for (const dir of options.allowlistDirs) {
      const resolved = path.resolve(dir);
      await mkdir(resolved, { recursive: true });
      const canonical = await realpath(resolved);
      const alias = path.basename(canonical) || "root";
      if (aliasSet.has(alias)) {
        throw new Error(`duplicate webdav allowlist alias: ${alias}`);
      }
      aliasSet.add(alias);
      allowedRoots.push({ absolute: canonical, name: alias });
    }

    return new WebDavServer(options, allowedRoots);
  }

  async start(): Promise<WebDavServerStatus> {
    if (!this.options.enabled) {
      throw new Error("webdav server is disabled; set enabled=true to start");
    }
    if (this.server && this.listening) {
      return this.status();
    }
    if (this.startPromise) return this.startPromise;

    const server = createServer((req, res) => {
      this.handle(req, res).catch((err) => {
        if (res.headersSent) {
          res.destroy(err as Error);
          return;
        }
        res.writeHead(500, { "Content-Type": "text/plain; charset=utf-8" });
        res.end("webdav error");
      });
    });
    this.server = server;
    this.listening = false;

    this.startPromise = (async () => {
      try {
        await new Promise<void>((resolve, reject) => {
          const onError = (err: Error) => {
            server.removeListener("listening", onListening);
            server.removeListener("close", onClose);
            reject(err);
          };
          const onListening = () => {
            server.removeListener("error", onError);
            server.removeListener("close", onClose);
            resolve();
          };
          const onClose = () => {
            server.removeListener("error", onError);
            server.removeListener("listening", onListening);
            reject(new Error("webdav server closed before listening"));
          };
          server.once("error", onError);
          server.once("listening", onListening);
          server.once("close", onClose);
          server.listen(this.options.port, this.options.host);
        });
      } catch (err) {
        if (this.server === server) {
          this.server = null;
        }
        this.listening = false;
        server.close();
        throw err;
      }

      const address = server.address();
      if (address && typeof address !== "string") {
        this.boundPort = address.port;
      }
      this.listening = true;

      return this.status();
    })();

    try {
      return await this.startPromise;
    } finally {
      this.startPromise = null;
    }
  }

  async stop(): Promise<void> {
    if (!this.server) return;
    const server = this.server;
    const pendingStart = this.startPromise;
    await new Promise<void>((resolve, reject) => {
      server.close((err) => {
        if (err && (err as NodeJS.ErrnoException).code !== "ERR_SERVER_NOT_RUNNING") {
          reject(err);
          return;
        }
        resolve();
      });
    });
    await pendingStart?.catch(() => undefined);
    if (this.server === server) {
      this.server = null;
    }
    this.listening = false;
    this.boundPort = this.options.port;
  }

  status(): WebDavServerStatus {
    return {
      running: this.server !== null && this.listening,
      host: this.options.host,
      port: this.boundPort,
      rootCount: this.allowedRoots.length,
    };
  }

  private async handle(req: IncomingMessage, res: ServerResponse): Promise<void> {
    if (!this.isAuthorized(req)) {
      res.writeHead(401, {
        "WWW-Authenticate": 'Basic realm="Engram WebDAV"',
        "Content-Type": "text/plain; charset=utf-8",
      });
      res.end("authentication required");
      return;
    }

    const method = (req.method ?? "GET").toUpperCase();
    if (method === "OPTIONS") {
      res.writeHead(204, {
        Allow: "OPTIONS, PROPFIND, GET, HEAD",
        DAV: "1",
      });
      res.end();
      return;
    }

    const parsed = new URL(req.url ?? "/", `http://${hostToUrlAuthority(this.options.host)}`);
    const resolved = await this.resolvePath(parsed.pathname);
    if (!resolved.ok) {
      res.writeHead(resolved.code, { "Content-Type": "text/plain; charset=utf-8" });
      res.end(resolved.message);
      return;
    }

    if (method === "PROPFIND") {
      await this.handlePropfind(resolved.absolutePath, resolved.rootAbsolute, resolved.displayPath, res);
      return;
    }

    if (method === "GET" || method === "HEAD") {
      await this.handleRead(method, resolved.absolutePath, resolved.rootAbsolute, res);
      return;
    }

    res.writeHead(405, {
      Allow: "OPTIONS, PROPFIND, GET, HEAD",
      "Content-Type": "text/plain; charset=utf-8",
    });
    res.end("method not allowed");
  }

  private isAuthorized(req: IncomingMessage): boolean {
    if (!this.options.auth) return true;
    const raw = req.headers.authorization;
    if (!raw) return false;
    const separator = raw.indexOf(" ");
    if (separator <= 0) return false;
    const scheme = raw.slice(0, separator).toLowerCase();
    if (scheme !== "basic") return false;
    const encodedPart = raw.slice(separator + 1).trim();
    if (!encodedPart) return false;

    try {
      const decoded = Buffer.from(encodedPart, "base64").toString("utf-8");
      const credentialSeparator = decoded.indexOf(":");
      if (credentialSeparator < 0) return false;
      const username = decoded.slice(0, credentialSeparator);
      const password = decoded.slice(credentialSeparator + 1);
      const usernameOk = this.timingSafeStringEqual(username, this.options.auth.username);
      const passwordOk = this.timingSafeStringEqual(password, this.options.auth.password);
      return Boolean((usernameOk ? 1 : 0) & (passwordOk ? 1 : 0));
    } catch {
      return false;
    }
  }

  private timingSafeStringEqual(a: string, b: string): boolean {
    const left = this.encodeAuthField(a);
    const right = this.encodeAuthField(b);
    if (!left || !right) return false;
    return timingSafeEqual(left, right);
  }

  private encodeAuthField(value: string): Buffer | null {
    const maxBytes = 512;
    const encoded = Buffer.from(value, "utf-8");
    if (encoded.length > maxBytes) return null;
    const out = Buffer.alloc(2 + maxBytes);
    out.writeUInt16BE(encoded.length, 0);
    encoded.copy(out, 2);
    return out;
  }

  private async resolvePath(
    requestPathname: string
  ): Promise<
    | { ok: true; absolutePath: string; displayPath: string; rootAbsolute: string }
    | { ok: false; code: number; message: string }
  > {
    let decodedPath: string;
    try {
      decodedPath = decodeURIComponent(requestPathname || "/");
    } catch {
      return { ok: false, code: 400, message: "invalid path encoding" };
    }
    if (decodedPath.includes("\0")) {
      return { ok: false, code: 400, message: "invalid path" };
    }

    const normalized = path.posix.normalize(decodedPath);
    const segments = normalized.split("/").filter((segment) => segment.length > 0);

    if (segments.length === 0) {
      return { ok: false, code: 403, message: "root listing is not allowed" };
    }

    const rootName = segments[0];
    const root = this.allowedRoots.find((entry) => entry.name === rootName);
    if (!root) {
      return { ok: false, code: 403, message: "path is outside allowlist" };
    }

    const relative = segments.slice(1);
    if (relative.some((segment) => segment === ".." || segment.includes("\\"))) {
      return { ok: false, code: 403, message: "path traversal is not allowed" };
    }

    const candidate = path.resolve(root.absolute, ...relative);
    if (!this.isPathInside(root.absolute, candidate)) {
      return { ok: false, code: 403, message: "path escaped allowlist" };
    }

    try {
      const canonicalCandidate = await realpath(candidate);
      if (!this.isPathInside(root.absolute, canonicalCandidate)) {
        return { ok: false, code: 403, message: "path escaped allowlist via symlink" };
      }
      return {
        ok: true,
        absolutePath: canonicalCandidate,
        displayPath: `/${segments.join("/")}`,
        rootAbsolute: root.absolute,
      };
    } catch (err) {
      const code = (err as NodeJS.ErrnoException).code;
      if (code === "ENOENT") {
        return {
          ok: true,
          absolutePath: candidate,
          displayPath: `/${segments.join("/")}`,
          rootAbsolute: root.absolute,
        };
      }
      if (code === "ENOTDIR" || code === "ELOOP") {
        return { ok: false, code: 400, message: "invalid path" };
      }
      throw err;
    }
  }

  private async handleRead(
    method: "GET" | "HEAD",
    absolutePath: string,
    rootAbsolute: string,
    res: ServerResponse
  ): Promise<void> {
    const revalidated = await this.revalidatePathInsideRoot(absolutePath, rootAbsolute);
    if (!revalidated.ok) {
      res.writeHead(revalidated.code, { "Content-Type": "text/plain; charset=utf-8" });
      res.end(revalidated.message);
      return;
    }
    const opened = await openWebDavFileForRead(revalidated.absolutePath);
    if (!opened.ok) {
      res.writeHead(opened.code, { "Content-Type": "text/plain; charset=utf-8" });
      res.end(opened.message);
      return;
    }

    const { handle, size } = opened;

    try {
      res.writeHead(200, {
        "Content-Length": String(size),
        "Content-Type": "application/octet-stream",
      });

      if (method === "HEAD") {
        res.end();
        return;
      }

      await pipeline(handle.createReadStream({ autoClose: false }), res);
    } finally {
      await handle.close().catch(() => {});
    }
  }

  private async handlePropfind(
    absolutePath: string,
    rootAbsolute: string,
    displayPath: string,
    res: ServerResponse
  ): Promise<void> {
    const revalidated = await this.revalidatePathInsideRoot(absolutePath, rootAbsolute);
    if (!revalidated.ok) {
      res.writeHead(revalidated.code, { "Content-Type": "text/plain; charset=utf-8" });
      res.end(revalidated.message);
      return;
    }
    absolutePath = revalidated.absolutePath;
    let info;
    try {
      info = await stat(absolutePath);
    } catch {
      res.writeHead(404, { "Content-Type": "text/plain; charset=utf-8" });
      res.end("not found");
      return;
    }

    const entries: string[] = [];
    if (info.isDirectory()) {
      const children = await readdir(absolutePath, { withFileTypes: true });
      for (const child of children) {
        const entry = await this.renderPropfindChildEntry(absolutePath, rootAbsolute, displayPath, child.name);
        if (entry) {
          entries.push(entry);
        }
      }
    }

    const xml = `<?xml version="1.0" encoding="utf-8"?>
<d:multistatus xmlns:d="DAV:">
${this.renderPropfindResponse(toEncodedHref(displayPath), info.isDirectory())}${entries.join("")}
</d:multistatus>`;

    res.writeHead(207, { "Content-Type": "application/xml; charset=utf-8" });
    res.end(xml);
  }

  private async renderPropfindChildEntry(
    parentAbsolutePath: string,
    rootAbsolute: string,
    displayPath: string,
    childName: string
  ): Promise<string | null> {
    const childAbsolutePath = path.join(parentAbsolutePath, childName);
    let revalidated;
    try {
      revalidated = await this.revalidatePathInsideRoot(childAbsolutePath, rootAbsolute);
    } catch {
      return null;
    }
    if (!revalidated.ok) {
      return null;
    }

    let info;
    try {
      info = await stat(revalidated.absolutePath);
    } catch {
      return null;
    }

    const childHref = toEncodedHref(`${displayPath.replace(/\/$/, "")}/${childName}`);
    return this.renderPropfindResponse(childHref, info.isDirectory());
  }

  private renderPropfindResponse(href: string, isDirectory: boolean): string {
    return `  <d:response>
    <d:href>${xmlEscape(href)}</d:href>
    <d:propstat><d:prop><d:resourcetype>${isDirectory ? "<d:collection/>" : ""}</d:resourcetype></d:prop><d:status>HTTP/1.1 200 OK</d:status></d:propstat>
  </d:response>
`;
  }

  private isPathInside(root: string, target: string): boolean {
    if (target === root) return true;
    if (root === path.parse(root).root) {
      return target.startsWith(root);
    }
    return target.startsWith(`${root}${path.sep}`);
  }

  private async revalidatePathInsideRoot(
    absolutePath: string,
    rootAbsolute: string
  ): Promise<{ ok: true; absolutePath: string } | { ok: false; code: number; message: string }> {
    try {
      const canonical = await realpath(absolutePath);
      if (!this.isPathInside(rootAbsolute, canonical)) {
        return { ok: false, code: 403, message: "path escaped allowlist via symlink" };
      }
      return { ok: true, absolutePath: canonical };
    } catch (err) {
      const code = (err as NodeJS.ErrnoException).code;
      if (code === "ENOENT" || code === "ENOTDIR") {
        return { ok: false, code: 404, message: "not found" };
      }
      if (code === "ELOOP") {
        return { ok: false, code: 403, message: "path escaped allowlist via symlink" };
      }
      throw err;
    }
  }
}

function xmlEscape(value: string): string {
  return value
    .replaceAll("&", "&amp;")
    .replaceAll("<", "&lt;")
    .replaceAll(">", "&gt;")
    .replaceAll('"', "&quot;")
    .replaceAll("'", "&apos;");
}

function toEncodedHref(pathname: string): string {
  return pathname
    .split("/")
    .map((segment) => encodeURIComponent(segment))
    .join("/");
}

import { createHash, timingSafeEqual } from "node:crypto";
import { createServer, type IncomingMessage, type ServerResponse } from "node:http";
import { mkdirSync, watch, type FSWatcher } from "node:fs";
import { readFile } from "node:fs/promises";
import path from "node:path";
import type { Duplex } from "node:stream";
import { graphSnapshotFromMemoryDir, type GraphSnapshot } from "./graph-dashboard-parser.js";
import { diffGraphSnapshots } from "./graph-dashboard-diff.js";

export interface DashboardServerOptions {
  memoryDir: string;
  host?: string;
  port?: number;
  publicDir?: string;
  watchDebounceMs?: number;
  authToken?: string;
}

export interface DashboardStatus {
  running: boolean;
  host: string;
  port: number;
  watching: boolean;
  lastUpdatedAt?: string;
  graphNodeCount: number;
  graphEdgeCount: number;
}

type WsClient = {
  id: string;
  socket: Duplex;
};

const LOOPBACK_HOSTS = new Set(["127.0.0.1", "localhost", "::1"]);

function normalizeOriginHostname(hostname: string): string {
  if (hostname.startsWith("[") && hostname.endsWith("]")) {
    return hostname.slice(1, -1);
  }
  return hostname;
}

function isLoopbackBindHost(host: string): boolean {
  return LOOPBACK_HOSTS.has(normalizeOriginHostname(host.trim().toLowerCase()));
}

function constantTimeEquals(a: string, b: string): boolean {
  const aBuffer = Buffer.from(a);
  const bBuffer = Buffer.from(b);
  if (aBuffer.length !== bBuffer.length) return false;
  return timingSafeEqual(aBuffer, bBuffer);
}

function parseDashboardPort(port: number | undefined): number {
  if (port === undefined) return 0;
  if (!Number.isInteger(port) || port < 0 || port > 65535) {
    throw new Error("dashboard port must be an integer from 0 to 65535");
  }
  return port;
}

function websocketAcceptKey(clientKey: string): string {
  return createHash("sha1")
    .update(`${clientKey}258EAFA5-E914-47DA-95CA-C5AB0DC85B11`)
    .digest("base64");
}

function encodeTextFrame(payload: string): Buffer {
  const payloadBuffer = Buffer.from(payload, "utf-8");
  const len = payloadBuffer.length;
  const header: number[] = [0x81];
  if (len <= 125) {
    header.push(len);
  } else if (len <= 0xffff) {
    header.push(126, (len >> 8) & 0xff, len & 0xff);
  } else {
    const high = Math.floor(len / 2 ** 32);
    const low = len >>> 0;
    header.push(127, (high >> 24) & 0xff, (high >> 16) & 0xff, (high >> 8) & 0xff, high & 0xff, (low >> 24) & 0xff, (low >> 16) & 0xff, (low >> 8) & 0xff, low & 0xff);
  }
  return Buffer.concat([Buffer.from(header), payloadBuffer]);
}

export class GraphDashboardServer {
  private readonly memoryDir: string;
  private readonly host: string;
  private readonly requestedPort: number;
  private readonly publicDir: string;
  private readonly watchDebounceMs: number;
  private readonly authToken: string | null;
  private server: ReturnType<typeof createServer> | null = null;
  private watcher: FSWatcher | null = null;
  private clients = new Map<string, WsClient>();
  private graphSnapshot: GraphSnapshot = {
    generatedAt: new Date(0).toISOString(),
    nodes: [],
    edges: [],
    stats: { nodes: 0, edges: 0, malformedLines: 0, filesMissing: [] },
  };
  private debounceTimer: NodeJS.Timeout | null = null;
  private lastError: string | null = null;
  private boundPort = 0;

  constructor(options: DashboardServerOptions) {
    this.memoryDir = options.memoryDir;
    this.host = options.host?.trim() || "127.0.0.1";
    this.requestedPort = parseDashboardPort(options.port);
    this.publicDir = options.publicDir ?? path.join(process.cwd(), "dashboard", "public");
    this.watchDebounceMs = Math.max(50, Math.floor(options.watchDebounceMs ?? 300));
    const authToken = options.authToken?.trim();
    this.authToken = authToken && authToken.length > 0 ? authToken : null;
  }

  async start(): Promise<DashboardStatus> {
    if (this.server) {
      return this.status();
    }
    if (!isLoopbackBindHost(this.host) && !this.authToken) {
      throw new Error("dashboard auth token is required when binding to a non-loopback host");
    }

    await this.rebuildSnapshot();
    const candidate = createServer((req, res) => {
      void this.handleHttp(req, res);
    });
    candidate.on("upgrade", (req, socket) => {
      this.handleUpgrade(req, socket);
    });
    try {
      await new Promise<void>((resolve, reject) => {
        const onError = (err: Error) => {
          candidate.off("listening", onListening);
          reject(err);
        };
        const onListening = () => {
          candidate.off("error", onError);
          resolve();
        };
        candidate.once("error", onError);
        candidate.once("listening", onListening);
        candidate.listen(this.requestedPort, this.host);
      });
    } catch (err) {
      this.lastError = err instanceof Error ? err.message : String(err);
      try {
        candidate.close();
      } catch {
        // no-op
      }
      throw err;
    }
    this.server = candidate;
    const addr = candidate.address();
    this.boundPort = typeof addr === "object" && addr ? addr.port : this.requestedPort;
    this.startWatcher();
    return this.status();
  }

  async stop(): Promise<void> {
    const closeServer = this.server;
    this.server = null;
    this.boundPort = 0;

    if (this.debounceTimer) {
      clearTimeout(this.debounceTimer);
      this.debounceTimer = null;
    }
    if (this.watcher) {
      this.watcher.close();
      this.watcher = null;
    }
    for (const client of this.clients.values()) {
      try {
        client.socket.destroy();
      } catch {
        // no-op
      }
    }
    this.clients.clear();

    if (closeServer) {
      await new Promise<void>((resolve, reject) => {
        closeServer.close((err) => {
          if (err) reject(err);
          else resolve();
        });
      });
    }
  }

  status(): DashboardStatus {
    return {
      running: this.server !== null,
      host: this.host,
      port: this.boundPort,
      watching: this.watcher !== null,
      lastUpdatedAt: this.graphSnapshot.generatedAt,
      graphNodeCount: this.graphSnapshot.stats.nodes,
      graphEdgeCount: this.graphSnapshot.stats.edges,
    };
  }

  private async handleHttp(req: IncomingMessage, res: ServerResponse): Promise<void> {
    const url = req.url ?? "/";
    if (req.method === "GET" && url === "/api/health") {
      if (!this.authorizeHttpApi(req, res)) return;
      this.respondJson(res, 200, {
        ok: true,
        running: this.server !== null,
        watching: this.watcher !== null,
        graph: this.graphSnapshot.stats,
        clients: this.clients.size,
        lastError: this.lastError ?? undefined,
      });
      return;
    }
    if (req.method === "GET" && url === "/api/graph") {
      if (!this.authorizeHttpApi(req, res)) return;
      this.respondJson(res, 200, this.graphSnapshot);
      return;
    }
    if (req.method === "GET" && url === "/app.js") {
      await this.respondStatic(res, path.join(this.publicDir, "app.js"), "application/javascript; charset=utf-8");
      return;
    }
    if (req.method === "GET" && (url === "/" || url === "/index.html")) {
      await this.respondStatic(res, path.join(this.publicDir, "index.html"), "text/html; charset=utf-8");
      return;
    }
    this.respondJson(res, 404, { error: "Not found" });
  }

  private respondJson(res: ServerResponse, status: number, payload: unknown): void {
    const body = JSON.stringify(payload, null, 2);
    res.statusCode = status;
    res.setHeader("content-type", "application/json; charset=utf-8");
    res.setHeader("content-length", String(Buffer.byteLength(body)));
    res.end(body);
  }

  private authorizeHttpApi(req: IncomingMessage, res: ServerResponse): boolean {
    if (!this.authToken) return true;
    const header = req.headers.authorization;
    const value = Array.isArray(header) ? header[0] : header;
    const prefix = "Bearer ";
    if (typeof value === "string" && value.startsWith(prefix)) {
      const supplied = value.slice(prefix.length);
      if (constantTimeEquals(supplied, this.authToken)) {
        return true;
      }
    }
    res.setHeader("www-authenticate", "Bearer");
    this.respondJson(res, 401, { error: "Unauthorized" });
    return false;
  }

  private async respondStatic(res: ServerResponse, filePath: string, contentType: string): Promise<void> {
    try {
      const body = await readFile(filePath, "utf-8");
      res.statusCode = 200;
      res.setHeader("content-type", contentType);
      res.setHeader("content-length", String(Buffer.byteLength(body)));
      res.end(body);
    } catch {
      this.respondJson(res, 404, { error: "Not found" });
    }
  }

  private handleUpgrade(req: IncomingMessage, socket: Duplex): void {
    const upgrade = typeof req.headers.upgrade === "string" ? req.headers.upgrade.toLowerCase() : "";
    const key = req.headers["sec-websocket-key"];
    const origin = typeof req.headers.origin === "string" ? req.headers.origin : "";
    if (upgrade !== "websocket" || typeof key !== "string") {
      socket.write("HTTP/1.1 400 Bad Request\r\n\r\n");
      socket.destroy();
      return;
    }
    if (!this.isAllowedOrigin(origin)) {
      socket.write("HTTP/1.1 403 Forbidden\r\n\r\n");
      socket.destroy();
      return;
    }
    if (!this.authorizeWebSocketUpgrade(req)) {
      socket.write("HTTP/1.1 401 Unauthorized\r\nWWW-Authenticate: Bearer\r\n\r\n");
      socket.destroy();
      return;
    }
    const accept = websocketAcceptKey(key);
    socket.write(
      [
        "HTTP/1.1 101 Switching Protocols",
        "Upgrade: websocket",
        "Connection: Upgrade",
        `Sec-WebSocket-Accept: ${accept}`,
        "",
        "",
      ].join("\r\n"),
    );
    const id = `${Date.now()}-${Math.random().toString(36).slice(2, 8)}`;
    this.clients.set(id, { id, socket });
    socket.on("close", () => {
      this.clients.delete(id);
    });
    socket.on("error", () => {
      this.clients.delete(id);
    });

    const hello = JSON.stringify({
      type: "hello",
      graph: this.graphSnapshot,
    });
    socket.write(encodeTextFrame(hello));
  }

  private isAllowedOrigin(origin: string): boolean {
    if (!origin) return false;
    try {
      const parsed = new URL(origin);
      const hostname = normalizeOriginHostname(parsed.hostname);
      if (parsed.protocol !== "http:") return false;
      const originPort = parsed.port ? Number(parsed.port) : 80;
      if (!Number.isFinite(originPort) || originPort !== this.boundPort) return false;
      if (LOOPBACK_HOSTS.has(hostname)) return true;
      return this.authToken !== null;
    } catch {
      return false;
    }
  }

  private authorizeWebSocketUpgrade(req: IncomingMessage): boolean {
    if (!this.authToken) return true;
    const supplied = this.webSocketTokenFromUrl(req.url) ?? this.webSocketTokenFromProtocol(req);
    return typeof supplied === "string" && constantTimeEquals(supplied, this.authToken);
  }

  private webSocketTokenFromUrl(rawUrl: string | undefined): string | null {
    if (!rawUrl) return null;
    try {
      const parsed = new URL(rawUrl, `http://${this.host}:${this.boundPort}`);
      const token = parsed.searchParams.get("token");
      return token && token.length > 0 ? token : null;
    } catch {
      return null;
    }
  }

  private webSocketTokenFromProtocol(req: IncomingMessage): string | null {
    const raw = req.headers["sec-websocket-protocol"];
    const values = Array.isArray(raw) ? raw : typeof raw === "string" ? raw.split(",") : [];
    for (const value of values) {
      const trimmed = value.trim();
      const prefix = "remnic-token.";
      if (!trimmed.startsWith(prefix)) continue;
      try {
        return Buffer.from(trimmed.slice(prefix.length), "base64url").toString("utf8");
      } catch {
        return null;
      }
    }
    return null;
  }

  private broadcast(payload: unknown): void {
    const frame = encodeTextFrame(JSON.stringify(payload));
    for (const [id, client] of this.clients.entries()) {
      try {
        client.socket.write(frame);
      } catch {
        this.clients.delete(id);
      }
    }
  }

  private startWatcher(): void {
    const graphDir = path.join(this.memoryDir, "state", "graphs");
    try {
      mkdirSync(graphDir, { recursive: true });
      this.watcher = watch(graphDir, { persistent: false }, () => {
        this.scheduleRebuild();
      });
      this.watcher.on("error", (err) => {
        this.lastError = err instanceof Error ? err.message : String(err);
      });
    } catch (err) {
      this.lastError = err instanceof Error ? err.message : String(err);
      this.watcher = null;
    }
  }

  private scheduleRebuild(): void {
    if (this.debounceTimer) clearTimeout(this.debounceTimer);
    this.debounceTimer = setTimeout(() => {
      this.debounceTimer = null;
      void this.rebuildAndBroadcast();
    }, this.watchDebounceMs);
  }

  private async rebuildAndBroadcast(): Promise<void> {
    const previous = this.graphSnapshot;
    await this.rebuildSnapshot();
    const patch = diffGraphSnapshots(previous, this.graphSnapshot);
    if (
      patch.addedEdges.length === 0 &&
      patch.removedEdges.length === 0 &&
      patch.updatedEdges.length === 0 &&
      patch.addedNodes.length === 0 &&
      patch.removedNodes.length === 0
    ) {
      return;
    }
    this.broadcast({
      type: "graph_patch",
      generatedAt: new Date().toISOString(),
      patch,
      graph: this.graphSnapshot,
    });
  }

  private async rebuildSnapshot(): Promise<void> {
    try {
      this.graphSnapshot = await graphSnapshotFromMemoryDir(this.memoryDir);
      this.lastError = null;
    } catch (err) {
      this.lastError = err instanceof Error ? err.message : String(err);
    }
  }
}

/**
 * `remnic chat` CLI implementation (issue #1583 PR 2).
 *
 * Interactive readline loop that streams assistant text and renders diffs.
 * Supports `--daemon-url` for remote daemon over HTTP (Tailscale fleet case)
 * and `--once` / non-TTY mode for scripting/tests
 * (`echo "question" | remnic chat --once`).
 *
 * Every turn routes through the shared `processChatMessage` factory
 * (issue #2479) so session lifecycle, transcript persistence, and
 * pending-plan/promotion markers behave identically to the HTTP/MCP
 * surfaces.
 *
 * This module is imported by cli.ts with a single thin registration line —
 * the god-file ratchet (#1520) tracks cli.ts LOC.
 */

import { createInterface } from "node:readline";

import type { EngramAccessService } from "../access-service.js";
import type { ChatConfig, ChatTurnResult } from "./chat-types.js";
import { processChatMessage } from "./chat-factory.js";
import {
  createChatSession,
  loadChatSession,
  sessionBelongsToPrincipal,
} from "./chat-session.js";

/**
 * Read all of stdin to a UTF-8 string (non-TTY / scripting mode).
 */
async function readAllStdin(): Promise<string> {
  const chunks: Buffer[] = [];
  for await (const chunk of process.stdin) {
    chunks.push(chunk as Buffer);
  }
  return Buffer.concat(chunks).toString("utf8").trim();
}

export interface ChatCliOptions {
  service: EngramAccessService;
  config: ChatConfig | undefined;
  memoryDir: string;
  principal?: string;
  namespace?: string;
  sessionKey?: string;
  /** Existing chat session id to resume. */
  sessionId?: string;
  /** Run a single message and exit (non-TTY / scripting mode). */
  once?: boolean;
  /** Input text for --once mode. */
  input?: string;
}

/**
 * Run the chat CLI.  In interactive mode, enters a readline loop.  In
 * `--once` mode, processes a single message and prints the reply to stdout.
 */
export async function runChatCli(opts: ChatCliOptions): Promise<void> {
  if (!opts.config?.enabled) {
    const msg = "[error] Remnic Chat is disabled. Set \"chat.enabled\": true in your config to enable it.";
    if (opts.once) { process.stdout.write(msg + "\n"); return; }
    console.error(msg);
    return;
  }
  const config = opts.config;
  const llm = opts.service.fallbackLlmRef ?? opts.service.localLlmRef;
  if (!llm) {
    const msg = "[error] No LLM model is available. Configure a local or cloud model to use Remnic Chat.";
    if (opts.once) {
      process.stdout.write(msg + "\n");
      return;
    }
    console.error(msg);
    return;
  }

  // Resolve the session up front so the banner and --once output print a
  // stable session id.  Each turn then routes through processChatMessage,
  // which reloads the session from disk — persisted state markers
  // (pending plan/promotion) stay authoritative across turns.
  let session;
  if (opts.sessionId) {
    session = await loadChatSession(opts.memoryDir, opts.sessionId);
    if (!session) {
      console.error(`Chat session not found: ${opts.sessionId}`);
      return;
    }
    if (!sessionBelongsToPrincipal(session, opts.principal)) {
      console.error("Access denied: this chat session belongs to a different principal.");
      return;
    }
  } else {
    session = await createChatSession(opts.memoryDir, {
      principal: opts.principal,
      sessionKey: opts.sessionKey,
      namespace: opts.namespace,
    });
  }

  const processTurn = (message: string): Promise<ChatTurnResult> =>
    processChatMessage({
      service: opts.service,
      config,
      memoryDir: opts.memoryDir,
      message,
      chatSessionId: session.id,
      principal: opts.principal,
    });

  // ── Non-TTY / --once mode ───────────────────────────────────────────
  if (opts.once) {
    // Read stdin here (not in cli.ts) so the god-file wiring stays thin.
    const message = opts.input ?? await readAllStdin();
    if (!message.trim()) {
      process.stdout.write("[error] No input provided.\n");
      return;
    }
    const result = await processTurn(message);
    process.stdout.write(result.reply + "\n");
    process.stdout.write(`[session: ${session.id}]\n`);
    return;
  }

  // ── Interactive mode ────────────────────────────────────────────────
  console.log(`Remnic Chat — session ${session.id}`);
  console.log("Type your message. Type 'exit' or Ctrl-C to quit.\n");

  const rl = createInterface({
    input: process.stdin,
    output: process.stdout,
    prompt: "you> ",
  });

  rl.prompt();

  let inFlight: Promise<void> = Promise.resolve();
  rl.on("line", (line: string) => {
    const message = line.trim();
    if (!message) {
      rl.prompt();
      return;
    }
    if (message === "exit" || message === "quit") {
      rl.close();
      return;
    }
    // Serialize turns: a second line waits for the first to finish so
    // transcript updates and engine state don't race on the same session.
    inFlight = inFlight.then(async () => {
    const result = await processTurn(message);

    console.log(`\nassistant> ${result.reply}\n`);
    if (result.pendingPlan) {
      console.log(`[pending plan: ${result.pendingPlan.planId} — reply 'apply' to confirm]\n`);
    }
    if (result.skippedTools && result.skippedTools.length > 0) {
      console.log(`[note: ${result.skippedTools.length} tool(s) skipped due to budget]\n`);
    }
    rl.prompt();
    }).catch(() => {
      console.error("[error] An unexpected error occurred during this turn. Please try again.");
      rl.prompt();
    });
  });

  await new Promise<void>((resolve) => {
    rl.on("close", resolve);
  });
}

import { access, readFile } from "node:fs/promises";
import path from "node:path";
import type { CompatCheckOptions, CompatCheckResult, CompatReport, CompatRunner } from "./types.js";
import { compareVersions } from "../version-utils.js";
import { launchProcess } from "../runtime/child-process.js";

const REQUIRED_HOOKS = ["before_prompt_build", "agent_end"];
const OPENCLAW_REMNIC_PLUGIN_ID = "openclaw-remnic";
const OPENCLAW_REMNIC_LEGACY_PLUGIN_ID = "openclaw-engram";

function isSafeCommandToken(command: string): boolean {
  return /^[a-zA-Z0-9._-]+$/.test(command);
}

const defaultRunner: CompatRunner = {
  async commandExists(command: string): Promise<boolean> {
    if (!isSafeCommandToken(command)) return false;
    const binary = process.platform === "win32" ? "where" : "which";
    const args = [command];
    return new Promise<boolean>((resolve) => {
      const child = launchProcess(binary, args, { stdio: "ignore" });
      child.on("error", () => resolve(false));
      child.on("close", (code) => resolve(code === 0));
    });
  },
};

function summarize(checks: CompatCheckResult[]): { ok: number; warn: number; error: number } {
  const out = { ok: 0, warn: 0, error: 0 };
  for (const check of checks) {
    out[check.level] += 1;
  }
  return out;
}

function stripCommentsAndStrings(source: string): string {
  const out: string[] = [];
  let i = 0;
  while (i < source.length) {
    const ch = source[i];
    const next = source[i + 1];

    if (ch === "/" && next === "/") {
      out.push(" ", " ");
      i += 2;
      while (i < source.length && source[i] !== "\n") {
        out.push(" ");
        i += 1;
      }
      continue;
    }

    if (ch === "/" && next === "*") {
      out.push(" ", " ");
      i += 2;
      while (i < source.length) {
        const c = source[i];
        const n = source[i + 1];
        out.push(c === "\n" ? "\n" : " ");
        i += 1;
        if (c === "*" && n === "/") {
          out.push(" ");
          i += 1;
          break;
        }
      }
      continue;
    }

    if (ch === '"' || ch === "'" || ch === "`") {
      const quote = ch;
      out.push(" ");
      i += 1;
      while (i < source.length) {
        const c = source[i];
        if (c === "\\") {
          out.push(" ");
          i += 1;
          if (i < source.length) {
            out.push(source[i] === "\n" ? "\n" : " ");
            i += 1;
          }
          continue;
        }
        out.push(c === "\n" ? "\n" : " ");
        i += 1;
        if (c === quote) break;
      }
      continue;
    }

    out.push(ch);
    i += 1;
  }
  return out.join("");
}

function parseHookRegistrations(source: string): Set<string> {
  const hooks = new Set<string>();
  let i = 0;

  while (i < source.length) {
    const ch = source[i];
    const next = source[i + 1];

    if (ch === "/" && next === "/") {
      i += 2;
      while (i < source.length && source[i] !== "\n") i += 1;
      continue;
    }

    if (ch === "/" && next === "*") {
      i += 2;
      while (i + 1 < source.length) {
        if (source[i] === "*" && source[i + 1] === "/") {
          i += 2;
          break;
        }
        i += 1;
      }
      continue;
    }

    if (ch === '"' || ch === "'" || ch === "`") {
      const quote = ch;
      i += 1;
      while (i < source.length) {
        if (source[i] === "\\") {
          i += 2;
          continue;
        }
        if (source[i] === quote) {
          i += 1;
          break;
        }
        i += 1;
      }
      continue;
    }

    if (source.startsWith("api.on", i) && (i === 0 || !/[a-zA-Z0-9_$\.]/.test(source[i - 1]))) {
      let j = i + "api.on".length;
      while (j < source.length && /\s/.test(source[j])) j += 1;
      if (source[j] !== "(") {
        i += 1;
        continue;
      }

      j += 1;
      while (j < source.length && /\s/.test(source[j])) j += 1;
      const quote = source[j];
      if (quote !== '"' && quote !== "'") {
        i += 1;
        continue;
      }

      j += 1;
      const start = j;
      while (j < source.length && source[j] !== quote) {
        if (source[j] === "\\") {
          j += 2;
        } else {
          j += 1;
        }
      }
      if (j < source.length) {
        const hook = source.slice(start, j);
        if (/^[a-z_]+$/.test(hook)) hooks.add(hook);
        i = j + 1;
        continue;
      }
    }

    i += 1;
  }

  return hooks;
}

function hasServiceStartRegistration(source: string): boolean {
  let i = 0;
  while (i < source.length) {
    const callIndex = source.indexOf("api.registerService", i);
    if (callIndex === -1) return false;
    if (callIndex > 0 && /[a-zA-Z0-9_$\.]/.test(source[callIndex - 1])) {
      i = callIndex + 1;
      continue;
    }

    let cursor = callIndex + "api.registerService".length;
    while (cursor < source.length && /\s/.test(source[cursor])) cursor += 1;
    if (source[cursor] !== "(") {
      i = callIndex + 1;
      continue;
    }

    cursor += 1;
    while (cursor < source.length && /\s/.test(source[cursor])) cursor += 1;
    if (source[cursor] !== "{") {
      i = callIndex + 1;
      continue;
    }

    if (objectLiteralHasTopLevelStart(source, cursor)) return true;
    i = cursor + 1;
  }
  return false;
}

function objectLiteralHasTopLevelStart(source: string, objectStart: number): boolean {
  let depth = 0;
  let i = objectStart;
  while (i < source.length) {
    const ch = source[i];
    if (ch === "{") {
      depth += 1;
      i += 1;
      continue;
    }
    if (ch === "}") {
      depth -= 1;
      if (depth === 0) return false;
      i += 1;
      continue;
    }
    if (depth === 1 && source.startsWith("start", i)) {
      const before = source[i - 1];
      const after = source[i + "start".length];
      if (
        (!before || !/[a-zA-Z0-9_$]/.test(before)) &&
        (!after || !/[a-zA-Z0-9_$]/.test(after))
      ) {
        let cursor = i + "start".length;
        while (cursor < source.length && /\s/.test(source[cursor])) cursor += 1;
        if (source[cursor] === ":" || source[cursor] === "(") return true;
      }
    }
    i += 1;
  }
  return false;
}

function hasCliRegistration(source: string): boolean {
  return /registerCli\s*\([^)]*\borchestrator\b[^)]*\)/m.test(source);
}

function parseCurrentNodeVersion(raw: string): [number, number, number] | null {
  const normalized = raw.startsWith("v") ? raw.slice(1) : raw;
  const match = normalized.match(/^(\d+)\.(\d+)\.(\d+)/);
  if (!match) return null;
  return [Number(match[1]), Number(match[2]), Number(match[3])];
}

type NodeEngineEvaluation =
  | { status: "satisfied" }
  | { status: "unsatisfied" }
  | { status: "unsupported"; reason: string };

type ComparatorOperator = ">" | ">=" | "<" | "<=" | "=";

interface ParsedRangeVersion {
  version: [number, number, number];
  specifiedParts: number;
}

function parseRangeVersion(raw: string): ParsedRangeVersion | null {
  const match = raw.trim().match(/^v?(\d+)(?:\.(\d+|x|\*))?(?:\.(\d+|x|\*))?$/i);
  if (!match) return null;

  const minor = match[2];
  const patch = match[3];
  if (minor && /^(x|\*)$/i.test(minor)) {
    return { version: [Number(match[1]), 0, 0], specifiedParts: 1 };
  }
  if (patch && /^(x|\*)$/i.test(patch)) {
    return {
      version: [Number(match[1]), Number(minor ?? 0), 0],
      specifiedParts: 2,
    };
  }

  return {
    version: [Number(match[1]), Number(minor ?? 0), Number(patch ?? 0)],
    specifiedParts: patch ? 3 : minor ? 2 : 1,
  };
}

function upperBoundForPartial(
  parsed: ParsedRangeVersion,
): [number, number, number] | null {
  if (parsed.specifiedParts === 1) {
    return [parsed.version[0] + 1, 0, 0];
  }
  if (parsed.specifiedParts === 2) {
    return [parsed.version[0], parsed.version[1] + 1, 0];
  }
  return null;
}

function upperBoundForCaret(
  parsed: ParsedRangeVersion,
): [number, number, number] {
  const [major, minor, patch] = parsed.version;
  if (parsed.specifiedParts === 1) {
    return [major + 1, 0, 0];
  }
  if (major > 0) return [major + 1, 0, 0];
  if (parsed.specifiedParts === 2) {
    return [0, minor + 1, 0];
  }
  if (minor > 0) return [0, minor + 1, 0];
  return [0, 0, patch + 1];
}

function upperBoundForTilde(
  parsed: ParsedRangeVersion,
): [number, number, number] {
  const [major, minor] = parsed.version;
  if (parsed.specifiedParts === 1) {
    return [major + 1, 0, 0];
  }
  return [major, minor + 1, 0];
}

function compareWithOperator(
  current: [number, number, number],
  operator: ComparatorOperator,
  target: [number, number, number],
): boolean {
  const comparison = compareVersions(current, target);
  switch (operator) {
    case ">":
      return comparison > 0;
    case ">=":
      return comparison >= 0;
    case "<":
      return comparison < 0;
    case "<=":
      return comparison <= 0;
    case "=":
      return comparison === 0;
  }
}

function evaluateComparatorToken(
  token: string,
  current: [number, number, number],
): NodeEngineEvaluation {
  const trimmed = token.trim();
  if (!trimmed || trimmed === "*" || /^x$/i.test(trimmed)) {
    return { status: "satisfied" };
  }

  const shorthand = trimmed.match(/^([~^])\s*(.+)$/);
  if (shorthand) {
    const parsed = parseRangeVersion(shorthand[2]);
    if (!parsed) {
      return {
        status: "unsupported",
        reason: `unsupported node engine comparator "${trimmed}"`,
      };
    }
    const upper = shorthand[1] === "^"
      ? upperBoundForCaret(parsed)
      : upperBoundForTilde(parsed);
    return compareWithOperator(current, ">=", parsed.version)
      && compareWithOperator(current, "<", upper)
      ? { status: "satisfied" }
      : { status: "unsatisfied" };
  }

  const comparator = trimmed.match(/^(>=|<=|>|<|=)?\s*(.+)$/);
  if (!comparator) {
    return {
      status: "unsupported",
      reason: `unsupported node engine comparator "${trimmed}"`,
    };
  }
  const operator = (comparator[1] ?? "=") as ComparatorOperator;
  const parsed = parseRangeVersion(comparator[2]);
  if (!parsed) {
    return {
      status: "unsupported",
      reason: `unsupported node engine comparator "${trimmed}"`,
    };
  }

  if (!comparator[1]) {
    const upper = upperBoundForPartial(parsed);
    if (upper) {
      return compareWithOperator(current, ">=", parsed.version)
        && compareWithOperator(current, "<", upper)
        ? { status: "satisfied" }
        : { status: "unsatisfied" };
    }
  }

  const partialUpper = upperBoundForPartial(parsed);
  if (partialUpper) {
    switch (operator) {
      case "=":
        return compareWithOperator(current, ">=", parsed.version)
          && compareWithOperator(current, "<", partialUpper)
          ? { status: "satisfied" }
          : { status: "unsatisfied" };
      case ">=":
        return compareWithOperator(current, ">=", parsed.version)
          ? { status: "satisfied" }
          : { status: "unsatisfied" };
      case ">":
        return compareWithOperator(current, ">=", partialUpper)
          ? { status: "satisfied" }
          : { status: "unsatisfied" };
      case "<=":
        return compareWithOperator(current, "<", partialUpper)
          ? { status: "satisfied" }
          : { status: "unsatisfied" };
      case "<":
        return compareWithOperator(current, "<", parsed.version)
          ? { status: "satisfied" }
          : { status: "unsatisfied" };
    }
  }

  return compareWithOperator(current, operator, parsed.version)
    ? { status: "satisfied" }
    : { status: "unsatisfied" };
}

function tokenizeRangeAlternative(alternative: string): string[] {
  const tokens: string[] = [];
  let i = 0;

  while (i < alternative.length) {
    while (i < alternative.length && /\s/.test(alternative[i])) i += 1;
    if (i >= alternative.length) break;

    let operator = "";
    const ch = alternative[i];
    if (ch === ">" || ch === "<") {
      operator = ch;
      i += 1;
      if (alternative[i] === "=") {
        operator += "=";
        i += 1;
      }
    } else if (ch === "=" || ch === "^" || ch === "~") {
      operator = ch;
      i += 1;
    }

    while (i < alternative.length && /\s/.test(alternative[i])) i += 1;
    const versionStart = i;
    while (i < alternative.length && !/\s/.test(alternative[i])) i += 1;
    const version = alternative.slice(versionStart, i);
    tokens.push(`${operator}${version}`);
  }

  return tokens;
}

function evaluateHyphenRange(
  alternative: string,
  current: [number, number, number],
): NodeEngineEvaluation | null {
  const match = alternative.match(/^(.+?)\s+-\s+(.+)$/);
  if (!match) return null;

  const lower = parseRangeVersion(match[1]);
  const upper = parseRangeVersion(match[2]);
  if (!lower || !upper) {
    return {
      status: "unsupported",
      reason: `unsupported node engine hyphen range "${alternative}"`,
    };
  }

  const lowerSatisfied = compareWithOperator(current, ">=", lower.version);
  const upperBound = upperBoundForPartial(upper);
  const upperSatisfied = upperBound
    ? compareWithOperator(current, "<", upperBound)
    : compareWithOperator(current, "<=", upper.version);
  return lowerSatisfied && upperSatisfied
    ? { status: "satisfied" }
    : { status: "unsatisfied" };
}

function evaluateNodeEngineRange(
  rawRange: string | undefined,
  currentVersion: [number, number, number],
): NodeEngineEvaluation {
  if (!rawRange || rawRange.trim().length === 0) {
    return { status: "unsupported", reason: "missing node engine range" };
  }

  const alternatives = rawRange.split("||").map((part) => part.trim()).filter(Boolean);
  if (alternatives.length === 0) {
    return { status: "unsupported", reason: "missing node engine range" };
  }

  let firstUnsupported: string | undefined;
  let hasUnsatisfiedAlternative = false;
  for (const alternative of alternatives) {
    const hyphenResult = evaluateHyphenRange(alternative, currentVersion);
    if (hyphenResult) {
      if (hyphenResult.status === "satisfied") {
        return { status: "satisfied" };
      }
      if (hyphenResult.status === "unsupported") {
        firstUnsupported ??= hyphenResult.reason;
      } else {
        hasUnsatisfiedAlternative = true;
      }
      continue;
    }

    const tokens = tokenizeRangeAlternative(alternative).filter(Boolean);
    if (tokens.length === 0) continue;
    let alternativeSatisfied = true;
    for (const token of tokens) {
      const result = evaluateComparatorToken(token, currentVersion);
      if (result.status === "unsupported") {
        firstUnsupported ??= result.reason;
        alternativeSatisfied = false;
        break;
      }
      if (result.status === "unsatisfied") {
        hasUnsatisfiedAlternative = true;
        alternativeSatisfied = false;
        break;
      }
    }
    if (alternativeSatisfied) {
      return { status: "satisfied" };
    }
  }

  if (hasUnsatisfiedAlternative) {
    return { status: "unsatisfied" };
  }
  if (firstUnsupported) {
    return { status: "unsupported", reason: firstUnsupported };
  }
  return { status: "unsatisfied" };
}

function hasMemoryPromptSectionRegistration(source: string): boolean {
  const apiReceiver = String.raw`(?:\bapi|\(\s*api\s*\)|\(\s*api\s+as\s+[^)]+\)|\(\s*<[^>]+>\s*api\s*\))`;
  return new RegExp(
    `${apiReceiver}\\s*\\??\\.\\s*registerMemoryPromptSection\\s*(?:\\?\\.)?\\s*\\(`,
  ).test(source);
}

export async function runCompatChecks(options: CompatCheckOptions): Promise<CompatReport> {
  const checks: CompatCheckResult[] = [];
  const runner = options.runner ?? defaultRunner;
  const pluginJsonPath = path.join(options.repoRoot, "openclaw.plugin.json");
  const packageJsonPath = path.join(options.repoRoot, "package.json");
  const indexPath = path.join(options.repoRoot, "src", "index.ts");

  let pluginRaw = "";
  let pluginManifestPresent = false;
  try {
    pluginRaw = await readFile(pluginJsonPath, "utf-8");
    pluginManifestPresent = true;
    checks.push({
      id: "plugin-manifest-present",
      title: "Plugin manifest present",
      level: "ok",
      message: "Found openclaw.plugin.json",
    });
  } catch {
    checks.push({
      id: "plugin-manifest-present",
      title: "Plugin manifest present",
      level: "error",
      message: "openclaw.plugin.json is missing",
      remediation: "Restore openclaw.plugin.json at repo root with plugin metadata.",
    });
  }

  if (pluginManifestPresent) {
    try {
      const plugin = JSON.parse(pluginRaw) as { id?: string; kind?: string };
      const isValidId = plugin.id === OPENCLAW_REMNIC_PLUGIN_ID || plugin.id === OPENCLAW_REMNIC_LEGACY_PLUGIN_ID;
      if (isValidId && plugin.kind === "memory") {
        checks.push({
          id: "plugin-manifest-shape",
          title: "Plugin manifest ID and kind",
          level: "ok",
          message: "Plugin manifest id/kind match expected values.",
        });
      } else {
        checks.push({
          id: "plugin-manifest-shape",
          title: "Plugin manifest ID and kind",
          level: "error",
          message: `Unexpected manifest values (id=${String(plugin.id)}, kind=${String(plugin.kind)})`,
          remediation: `Set manifest id=${OPENCLAW_REMNIC_PLUGIN_ID} (or ${OPENCLAW_REMNIC_LEGACY_PLUGIN_ID} for the shim) and kind=memory.`,
        });
      }
    } catch {
      checks.push({
        id: "plugin-manifest-shape",
        title: "Plugin manifest ID and kind",
        level: "error",
        message: "openclaw.plugin.json is not valid JSON",
        remediation: "Fix JSON syntax in openclaw.plugin.json.",
      });
    }
  }

  let packageRaw = "";
  let packageJsonPresent = false;
  try {
    packageRaw = await readFile(packageJsonPath, "utf-8");
    packageJsonPresent = true;
  } catch {
    checks.push({
      id: "package-json-present",
      title: "package.json present",
      level: "error",
      message: "package.json is missing",
      remediation: "Restore package.json at repo root.",
    });
  }

  if (packageJsonPresent) {
    try {
      const pkg = JSON.parse(packageRaw) as {
        openclaw?: { plugin?: string; extensions?: string[] };
        engines?: { node?: string };
      };
      const pluginPathOk = pkg.openclaw?.plugin === "./openclaw.plugin.json";
      const extOk = Array.isArray(pkg.openclaw?.extensions)
        && pkg.openclaw?.extensions.includes("./dist/index.js");
      if (pluginPathOk && extOk) {
        checks.push({
          id: "package-openclaw-exports",
          title: "package.json OpenClaw export wiring",
          level: "ok",
          message: "package.json openclaw.plugin/extensions wiring looks valid.",
        });
      } else {
        checks.push({
          id: "package-openclaw-exports",
          title: "package.json OpenClaw export wiring",
          level: "error",
          message: "package.json openclaw plugin/extension wiring is missing or invalid.",
          remediation: "Set openclaw.plugin to ./openclaw.plugin.json and include ./dist/index.js in openclaw.extensions.",
        });
      }

      const currentNode = options.currentNodeVersion ?? process.version;
      const currentVersion = parseCurrentNodeVersion(currentNode);
      const engineEvaluation: NodeEngineEvaluation = currentVersion
        ? evaluateNodeEngineRange(pkg.engines?.node, currentVersion)
        : { status: "unsupported", reason: "unable to parse current Node version" };
      if (engineEvaluation.status === "unsupported") {
        checks.push({
          id: "node-version-compat",
          title: "Node runtime compatibility",
          level: "warn",
          message: `Unable to evaluate node engine/current version: ${engineEvaluation.reason}.`,
          remediation: "Confirm Node version meets package.json engines.node requirement.",
          metadata: { enginesNode: pkg.engines?.node, currentNode },
        });
      } else if (engineEvaluation.status === "satisfied") {
        checks.push({
          id: "node-version-compat",
          title: "Node runtime compatibility",
          level: "ok",
          message: `Current Node ${currentNode} satisfies engines requirement ${pkg.engines?.node}.`,
        });
      } else {
        checks.push({
          id: "node-version-compat",
          title: "Node runtime compatibility",
          level: "error",
          message: `Current Node ${currentNode} does not satisfy engines requirement ${pkg.engines?.node}.`,
          remediation: "Upgrade Node runtime to meet package.json engines.node minimum.",
        });
      }
    } catch {
      checks.push({
        id: "package-json-parse",
        title: "package.json parse",
        level: "error",
        message: "package.json is not valid JSON",
        remediation: "Fix JSON syntax in package.json.",
      });
    }
  }

  try {
    await access(indexPath);
    const indexRaw = await readFile(indexPath, "utf-8");
    const structuralSource = stripCommentsAndStrings(indexRaw);
    const hooks = parseHookRegistrations(indexRaw);
    const missingHooks = REQUIRED_HOOKS.filter((hook) => !hooks.has(hook));
    // registerMemoryPromptSection is a valid alternative to the recall hook only
    // when it is registered on the OpenClaw plugin API object.
    const hasMemoryPromptSection = hasMemoryPromptSectionRegistration(structuralSource);
    const missingRequiredHooks = hasMemoryPromptSection
      ? missingHooks.filter((hook) => hook !== "before_prompt_build")
      : missingHooks;
    const hasGatewayStartHook = hooks.has("gateway_start");
    const hasServiceStart = hasServiceStartRegistration(structuralSource);
    if (missingRequiredHooks.length === 0 && (hasGatewayStartHook || hasServiceStart)) {
      checks.push({
        id: "hook-registration-core",
        title: "Core hook registration",
        level: "ok",
        message: "Core recall/extraction hooks and startup wiring are registered in src/index.ts.",
      });
    } else {
      const missingParts: string[] = [];
      if (missingRequiredHooks.length > 0) {
        missingParts.push(`hooks: ${missingRequiredHooks.join(", ")}`);
      }
      if (!hasGatewayStartHook && !hasServiceStart) {
        missingParts.push("startup wiring: gateway_start hook or api.registerService({ start })");
      }
      const remediationParts: string[] = [];
      if (missingRequiredHooks.length > 0) {
        remediationParts.push(`registers ${missingRequiredHooks.join(", ")}`);
      }
      if (!hasGatewayStartHook && !hasServiceStart) {
        remediationParts.push("registers gateway_start or api.registerService({ start })");
      }
      checks.push({
        id: "hook-registration-core",
        title: "Core hook registration",
        level: "error",
        message: `Missing expected registration(s): ${missingParts.join("; ")}`,
        remediation: `Ensure src/index.ts ${remediationParts.join(" and ")}.`,
      });
    }

    const cliWired = hasCliRegistration(structuralSource);
    checks.push({
      id: "cli-registration",
      title: "CLI registration wiring",
      level: cliWired ? "ok" : "warn",
      message: cliWired
        ? "CLI registration is wired in plugin bootstrap."
        : "CLI registration call not found in src/index.ts.",
      remediation: cliWired ? undefined : "Call registerCli(api, orchestrator) during plugin registration.",
    });
  } catch {
    checks.push({
      id: "hook-registration-core",
      title: "Core hook registration",
      level: "error",
      message: "src/index.ts is missing; cannot validate hook wiring.",
      remediation: "Restore src/index.ts and register required hooks.",
    });
  }

  const qmdAvailable = await runner.commandExists("qmd");
  checks.push({
    id: "qmd-binary-availability",
    title: "QMD binary availability",
    level: qmdAvailable ? "ok" : "warn",
    message: qmdAvailable
      ? "qmd binary is available in PATH."
      : "qmd binary is not available in PATH.",
    remediation: qmdAvailable ? undefined : "Install qmd or configure qmdPath in plugin config.",
  });

  return {
    generatedAt: (options.now ?? new Date()).toISOString(),
    checks,
    summary: summarize(checks),
  };
}

import { searchHarmonicRetrieval, type HarmonicRetrievalResult } from "../harmonic-retrieval.js";

export async function runHarmonicSearchCliCommand(options: {
  memoryDir: string;
  abstractionNodeStoreDir?: string;
  harmonicRetrievalEnabled: boolean;
