export type ResumeBundleSource = "tool_result" | "cli" | "system" | "manual";

export interface ResumeBundle {
  schemaVersion: 1;
  bundleId: string;
  recordedAt: string;
  sessionKey: string;
  source: ResumeBundleSource;
  scope: string;
  summary: string;
  objectiveStateSnapshotRefs?: string[];
  workProductEntryRefs?: string[];
  commitmentEntryRefs?: string[];
  keyFacts?: string[];
  nextActions?: string[];
  riskFlags?: string[];
  metadata?: Record<string, string>;
}

export interface ResumeBundleStatus {
  enabled: boolean;
  rootDir: string;
  bundlesDir: string;
  bundles: {
    total: number;
    valid: number;
    invalid: number;
    bySource: Partial<Record<ResumeBundleSource, number>>;
    latestBundleId?: string;
    latestRecordedAt?: string;
    latestSessionKey?: string;
  };
  latestBundle?: ResumeBundle;
  invalidBundles: Array<{
    path: string;
    error: string;
  }>;
}

const DEFAULT_RESUME_BUNDLE_REF_LIMIT = 5;

export function resolveResumeBundleDir(memoryDir: string, overrideDir?: string): string {
  if (typeof overrideDir === "string" && overrideDir.trim().length > 0) {
    return overrideDir.trim();
  }
  return path.join(memoryDir, "state", "resume-bundles");
}

export function validateResumeBundle(raw: unknown): ResumeBundle {
  if (!isRecord(raw)) throw new Error("resume bundle must be an object");
  if (raw.schemaVersion !== 1) throw new Error("schemaVersion must be 1");

  const source = assertString(raw.source, "source");
  if (!["tool_result", "cli", "system", "manual"].includes(source)) {
    throw new Error("source must be one of tool_result|cli|system|manual");
  }

  const recordedAt = assertIsoRecordedAt(assertString(raw.recordedAt, "recordedAt"));
  if (!Number.isFinite(Date.parse(recordedAt))) {
    throw new Error("recordedAt must be an ISO timestamp");
  }

  return {
    schemaVersion: 1,
    bundleId: assertSafePathSegment(assertString(raw.bundleId, "bundleId"), "bundleId"),
    recordedAt,
    sessionKey: assertString(raw.sessionKey, "sessionKey"),
    source: source as ResumeBundleSource,
    scope: assertString(raw.scope, "scope"),
    summary: assertString(raw.summary, "summary"),
    objectiveStateSnapshotRefs: optionalStringArray(raw.objectiveStateSnapshotRefs, "objectiveStateSnapshotRefs"),
    workProductEntryRefs: optionalStringArray(raw.workProductEntryRefs, "workProductEntryRefs"),
    commitmentEntryRefs: optionalStringArray(raw.commitmentEntryRefs, "commitmentEntryRefs"),
    keyFacts: optionalStringArray(raw.keyFacts, "keyFacts"),
    nextActions: optionalStringArray(raw.nextActions, "nextActions"),
    riskFlags: optionalStringArray(raw.riskFlags, "riskFlags"),
    metadata: validateStringRecord(raw.metadata, "metadata"),
  };
}

async function readValidatedItems<T>(options: {
  rootDir: string;
  validate: (raw: unknown) => T;
}): Promise<T[]> {
  const files = await listJsonFiles(options.rootDir);
  const items: T[] = [];
  for (const filePath of files) {
    try {
      items.push(options.validate(await readJsonFile(filePath)));
    } catch {
      // Status inspection already reports invalid artifacts. Bundle assembly fail-opens.
    }
  }
  return items;
}

async function readObjectiveStateSnapshotsForSession(options: {
  memoryDir: string;
  objectiveStateStoreDir?: string;
  sessionKey: string;
  maxResults?: number;
}): Promise<ObjectiveStateSnapshot[]> {
  const rootDir = resolveObjectiveStateStoreDir(options.memoryDir, options.objectiveStateStoreDir);
  const items = await readValidatedItems({
    rootDir: path.join(rootDir, "snapshots"),
    validate: validateObjectiveStateSnapshot,
  });
  return items
    .filter((item) => item.sessionKey === options.sessionKey)
    .sort((left, right) => right.recordedAt.localeCompare(left.recordedAt))
    .slice(0, options.maxResults ?? DEFAULT_RESUME_BUNDLE_REF_LIMIT);
}

async function readWorkProductEntriesForSession(options: {
  memoryDir: string;
  workProductLedgerDir?: string;
  sessionKey: string;
  maxResults?: number;
}): Promise<WorkProductLedgerEntry[]> {
  const rootDir = resolveWorkProductLedgerDir(options.memoryDir, options.workProductLedgerDir);
  const items = await readValidatedItems({
    rootDir: path.join(rootDir, "entries"),
    validate: validateWorkProductLedgerEntry,
  });
  return items
    .filter((item) => item.sessionKey === options.sessionKey)
    .sort((left, right) => right.recordedAt.localeCompare(left.recordedAt))
    .slice(0, options.maxResults ?? DEFAULT_RESUME_BUNDLE_REF_LIMIT);
}

async function readCommitmentEntriesForSession(options: {
  memoryDir: string;
  commitmentLedgerDir?: string;
  sessionKey: string;
  maxResults?: number;
  state?: CommitmentLedgerEntry["state"];
}): Promise<CommitmentLedgerEntry[]> {
  const rootDir = resolveCommitmentLedgerDir(options.memoryDir, options.commitmentLedgerDir);
  const items = await readValidatedItems({
    rootDir: path.join(rootDir, "entries"),
    validate: validateCommitmentLedgerEntry,
  });
  return items
    .filter((item) => item.sessionKey === options.sessionKey)
    .filter((item) => (options.state ? item.state === options.state : true))
    .sort((left, right) => right.recordedAt.localeCompare(left.recordedAt))
    .slice(0, options.maxResults ?? DEFAULT_RESUME_BUNDLE_REF_LIMIT);
}

function buildRecoveryFact(recoverySummary: {
  healthy: boolean;
  issueCount: number;
  incompleteTurns: number;
  brokenChains: number;
  checkpointHealthy: boolean;
}): string {
  return recoverySummary.healthy
    ? `Transcript recovery healthy with ${recoverySummary.issueCount} issue(s), ${recoverySummary.incompleteTurns} incomplete turn(s), and ${recoverySummary.brokenChains} broken chain(s).`
    : `Transcript recovery flagged ${recoverySummary.issueCount} issue(s), ${recoverySummary.incompleteTurns} incomplete turn(s), and ${recoverySummary.brokenChains} broken chain(s); checkpoint healthy: ${recoverySummary.checkpointHealthy ? "yes" : "no"}.`;
}

function buildBundleSummary(options: {
  sessionKey: string;
  openCommitmentCount: number;
  workProductCount: number;
  objectiveSnapshotCount: number;
  recoveryHealthy?: boolean;
}): string {
  const parts = [
    `${options.openCommitmentCount} open commitment(s)`,
    `${options.workProductCount} recent work product(s)`,
    `${options.objectiveSnapshotCount} recent objective-state snapshot(s)`,
  ];
  if (options.recoveryHealthy === false) {
    parts.push("transcript recovery issues remain");
  }
  return `Resume ${options.sessionKey}: ${parts.join(", ")}.`;
}

export async function buildResumeBundleFromState(options: {
  memoryDir: string;
  sessionKey: string;
  bundleId: string;
  recordedAt: string;
  scope: string;
  source?: ResumeBundleSource;
  transcriptEnabled?: boolean;
  objectiveStateMemoryEnabled?: boolean;
  objectiveStateStoreDir?: string;
  creationMemoryEnabled?: boolean;
  workProductLedgerDir?: string;
  commitmentLedgerEnabled?: boolean;
  commitmentLedgerDir?: string;
  maxRefsPerStore?: number;
}): Promise<ResumeBundle> {
  const recordedAt = assertIsoRecordedAt(options.recordedAt, "recordedAt");
  const maxRefsPerStore = Math.max(1, Math.floor(options.maxRefsPerStore ?? DEFAULT_RESUME_BUNDLE_REF_LIMIT));

  const objectiveSnapshots = options.objectiveStateMemoryEnabled
    ? await readObjectiveStateSnapshotsForSession({
        memoryDir: options.memoryDir,
        objectiveStateStoreDir: options.objectiveStateStoreDir,
        sessionKey: options.sessionKey,
        maxResults: maxRefsPerStore,
      })
    : [];

  const workProducts = options.creationMemoryEnabled
    ? await readWorkProductEntriesForSession({
        memoryDir: options.memoryDir,
        workProductLedgerDir: options.workProductLedgerDir,
        sessionKey: options.sessionKey,
        maxResults: maxRefsPerStore,
      })
    : [];

  const commitments = options.creationMemoryEnabled && options.commitmentLedgerEnabled
    ? await readCommitmentEntriesForSession({
        memoryDir: options.memoryDir,
        commitmentLedgerDir: options.commitmentLedgerDir,
        sessionKey: options.sessionKey,
        maxResults: maxRefsPerStore,
        state: "open",
      })
    : [];

  const openCommitments = commitments;
  const recordedAtMs = Date.parse(recordedAt);
  const overdueCommitments = openCommitments.filter((entry) => {
    if (!entry.dueAt) return false;
    const dueAtMs = Date.parse(entry.dueAt);
    return Number.isFinite(dueAtMs) && dueAtMs < recordedAtMs;
  });

  let recoverySummary:
    | {
        healthy: boolean;
        issueCount: number;
        incompleteTurns: number;
        brokenChains: number;
        checkpointHealthy: boolean;
      }
    | undefined;
  if (options.transcriptEnabled) {
    const transcript = new TranscriptManager(parseConfig({
      memoryDir: options.memoryDir,
      transcriptEnabled: true,
    }));
    await transcript.initialize();
    recoverySummary = await transcript.getRecoverySummary(options.sessionKey);
  }

  const keyFacts = [
    recoverySummary ? buildRecoveryFact(recoverySummary) : undefined,
    workProducts[0]?.summary,
    objectiveSnapshots[0]?.summary,
  ].filter((value): value is string => typeof value === "string" && value.length > 0);

  const nextActions = openCommitments
    .map((entry) => entry.summary)
    .filter((summary, index, values) => values.indexOf(summary) === index)
    .slice(0, maxRefsPerStore);

  const riskFlags = [
    recoverySummary && !recoverySummary.healthy ? buildRecoveryFact(recoverySummary) : undefined,
    ...objectiveSnapshots
      .filter((snapshot) => snapshot.outcome === "failure" || snapshot.outcome === "partial")
      .map((snapshot) => snapshot.summary),
    ...overdueCommitments.map((entry) => `Overdue commitment: ${entry.summary}`),
  ].filter((value, index, values): value is string =>
    typeof value === "string" && value.length > 0 && values.indexOf(value) === index,
  );

  return validateResumeBundle({
    schemaVersion: 1,
    bundleId: options.bundleId,
    recordedAt,
    sessionKey: options.sessionKey,
    source: options.source ?? "system",
    scope: options.scope,
    summary: buildBundleSummary({
      sessionKey: options.sessionKey,
      openCommitmentCount: openCommitments.length,
      workProductCount: workProducts.length,
      objectiveSnapshotCount: objectiveSnapshots.length,
      recoveryHealthy: recoverySummary?.healthy,
    }),
    objectiveStateSnapshotRefs: objectiveSnapshots.map((snapshot) => snapshot.snapshotId),
    workProductEntryRefs: workProducts.map((entry) => entry.entryId),
    commitmentEntryRefs: openCommitments.map((entry) => entry.entryId),
    keyFacts: keyFacts.length > 0 ? keyFacts : undefined,
    nextActions: nextActions.length > 0 ? nextActions : undefined,
    riskFlags: riskFlags.length > 0 ? riskFlags : undefined,
  });
}

export async function recordResumeBundle(options: {
  memoryDir: string;
  resumeBundleDir?: string;
  bundle: ResumeBundle;
}): Promise<string> {
  const rootDir = resolveResumeBundleDir(options.memoryDir, options.resumeBundleDir);
  const validated = validateResumeBundle(options.bundle);
  const day = recordStoreDay(validated.recordedAt);
  const bundlesDir = path.join(rootDir, "bundles", day);
  const filePath = path.join(bundlesDir, `${validated.bundleId}.json`);
  await mkdir(bundlesDir, { recursive: true });
  await writeFile(filePath, JSON.stringify(validated, null, 2), "utf8");
  return filePath;
}

async function readResumeBundles(options: {
  memoryDir: string;
  resumeBundleDir?: string;
}): Promise<{
  files: string[];
  bundles: ResumeBundle[];
  invalidBundles: Array<{ path: string; error: string }>;
}> {
  const rootDir = resolveResumeBundleDir(options.memoryDir, options.resumeBundleDir);
  const files = await listJsonFiles(path.join(rootDir, "bundles"));
  const bundles: ResumeBundle[] = [];
  const invalidBundles: Array<{ path: string; error: string }> = [];
  for (const filePath of files) {
    try {
      bundles.push(validateResumeBundle(await readJsonFile(filePath)));
    } catch (error) {
      invalidBundles.push({
        path: filePath,
        error: error instanceof Error ? error.message : String(error),
      });
    }
  }
  return { files, bundles, invalidBundles };
}

export async function getResumeBundleStatus(options: {
  memoryDir: string;
  resumeBundleDir?: string;
  enabled: boolean;
}): Promise<ResumeBundleStatus> {
  const rootDir = resolveResumeBundleDir(options.memoryDir, options.resumeBundleDir);
  const bundlesDir = path.join(rootDir, "bundles");
  if (!options.enabled) {
    return {
      enabled: false,
      rootDir,
      bundlesDir,
      bundles: {
        total: 0,
        valid: 0,
        invalid: 0,
        bySource: {},
      },
      invalidBundles: [],
    };
  }
  const { files, bundles, invalidBundles } = await readResumeBundles(options);

  let latestBundle: ResumeBundle | undefined;
  const bySource: Partial<Record<ResumeBundleSource, number>> = {};
  for (const bundle of bundles) {
    bySource[bundle.source] = (bySource[bundle.source] ?? 0) + 1;
    if (!latestBundle || Date.parse(bundle.recordedAt) > Date.parse(latestBundle.recordedAt)) {
      latestBundle = bundle;
    }
  }

  return {
    enabled: options.enabled,
    rootDir,
    bundlesDir,
    bundles: {
      total: files.length,
      valid: bundles.length,
      invalid: invalidBundles.length,
      bySource,
      latestBundleId: latestBundle?.bundleId,
      latestRecordedAt: latestBundle?.recordedAt,
      latestSessionKey: latestBundle?.sessionKey,
    },
    latestBundle,
    invalidBundles,
  };
}

import { createHash, randomUUID } from "node:crypto";
import { composeMemoryEnvelope } from "./write-envelope.js";
import { log } from "./logger.js";
import { link, mkdir, readFile, rename, rm, stat, writeFile } from "node:fs/promises";
import path from "node:path";
import { setTimeout as sleep } from "node:timers/promises";
import { StorageManager } from "./storage.js";
import type { MemoryFile, MemoryLink } from "./types.js";
import { isErrnoCode } from "./utils/errno.js";

export interface SemanticRulePromotionCandidate {
  id: string;
  sourceMemoryId: string;
  content: string;
  confidence: number;
  tags: string[];
  memoryKind: "note";
  lineage: string[];
}

export interface SemanticRulePromotionSkip {
  sourceMemoryId: string;
  reason:
    | "disabled"
    | "source-memory-missing"
    | "source-memory-forgotten"
    | "source-memory-not-episode"
    | "no-explicit-rule"
    | "duplicate-rule";
  existingRuleId?: string;
}

export interface SemanticRulePromotionReport {
  enabled: boolean;
  dryRun: boolean;
  promoted: SemanticRulePromotionCandidate[];
  skipped: SemanticRulePromotionSkip[];
}

const PROMOTION_LOCK_TIMEOUT_MS = 10 * 60 * 1000;
const PROMOTION_LOCK_RETRY_MS = 25;
const PROMOTION_LOCK_STALE_MS = 5 * 60 * 1000;
const PROMOTION_LOCK_OWNERLESS_GRACE_MS = 1000;
const PROMOTION_LOCK_HEARTBEAT_MS = 30 * 1000;

type SemanticRulePromotionTestHooks = {
  beforeLockOwnerWrite?: (lockDir: string, ownerToken: string) => Promise<void> | void;
  beforeLockRelease?: (lockDir: string, ownerToken: string) => Promise<void> | void;
  beforePromotedRuleWrite?: (lockDir: string, ownerToken: string) => Promise<void> | void;
  lockTimeoutMs?: number;
  lockRetryMs?: number;
  staleLockMs?: number;
  ownerlessGraceMs?: number;
  heartbeatMs?: number;
};

let testHooks: SemanticRulePromotionTestHooks | null = null;

export function setSemanticRulePromotionTestHooks(hooks: SemanticRulePromotionTestHooks | null): void {
  testHooks = hooks;
}

function promotionLockTimeoutMs(): number {
  return testHooks?.lockTimeoutMs ?? PROMOTION_LOCK_TIMEOUT_MS;
}

function promotionLockRetryMs(): number {
  return testHooks?.lockRetryMs ?? PROMOTION_LOCK_RETRY_MS;
}

function promotionLockStaleMs(): number {
  return testHooks?.staleLockMs ?? PROMOTION_LOCK_STALE_MS;
}

function promotionLockOwnerlessGraceMs(): number {
  return testHooks?.ownerlessGraceMs ?? PROMOTION_LOCK_OWNERLESS_GRACE_MS;
}

function promotionLockHeartbeatMs(): number {
  return testHooks?.heartbeatMs ?? PROMOTION_LOCK_HEARTBEAT_MS;
}

function promotionLockDir(memoryDir: string, ruleKey: string): string {
  const digest = createHash("sha256").update(ruleKey).digest("hex");
  return path.join(path.resolve(memoryDir), "state", "semantic-rule-promotion-locks", `${digest}.lock`);
}

function promotionHeartbeatPath(lockDir: string, token: string): string {
  return path.join(lockDir, `heartbeat.${token}.json`);
}

function promotionReapDir(lockDir: string): string {
  return `${lockDir}.reap`;
}

function promotionReleaseDir(lockDir: string): string {
  return `${lockDir}.release`;
}

async function pathExists(targetPath: string): Promise<boolean> {
  try {
    await stat(targetPath);
    return true;
  } catch (err) {
    if (isErrnoCode(err, "ENOENT")) return false;
    throw err;
  }
}

async function readPromotionLockOwner(lockDir: string): Promise<{
  acquiredAtMs: number | null;
  heartbeatAtMs: number | null;
  token: string | null;
}> {
  try {
    const owner = JSON.parse(await readFile(path.join(lockDir, "owner.json"), "utf8")) as {
      acquiredAt?: unknown;
      heartbeatAt?: unknown;
      token?: unknown;
    };
    const acquiredAtMs = typeof owner.acquiredAt === "string" ? Date.parse(owner.acquiredAt) : Number.NaN;
    const heartbeatAtMs = typeof owner.heartbeatAt === "string" ? Date.parse(owner.heartbeatAt) : Number.NaN;
    return {
      acquiredAtMs: Number.isFinite(acquiredAtMs) ? acquiredAtMs : null,
      heartbeatAtMs: Number.isFinite(heartbeatAtMs) ? heartbeatAtMs : null,
      token: typeof owner.token === "string" ? owner.token : null,
    };
  } catch {
    return {
      acquiredAtMs: null,
      heartbeatAtMs: null,
      token: null,
    };
  }
}

async function tryWritePromotionLockOwner(
  lockDir: string,
  owner: { token: string; acquiredAt: string }
): Promise<boolean> {
  const ownerPath = path.join(lockDir, "owner.json");
  const tempPath = path.join(lockDir, `owner.${process.pid}.${randomUUID()}.tmp`);
  await testHooks?.beforeLockOwnerWrite?.(lockDir, owner.token);
  try {
    await writeFile(
      tempPath,
      `${JSON.stringify(
        {
          pid: process.pid,
          token: owner.token,
          acquiredAt: owner.acquiredAt,
        },
        null,
        2
      )}\n`
    );
    await link(tempPath, ownerPath);
    return true;
  } catch (err) {
    if (isErrnoCode(err, "EEXIST") || isErrnoCode(err, "ENOENT")) {
      return false;
    }
    throw err;
  } finally {
    await rm(tempPath, { force: true });
  }
}

async function writePromotionLockHeartbeat(lockDir: string, token: string): Promise<void> {
  const heartbeatPath = promotionHeartbeatPath(lockDir, token);
  const tempPath = path.join(lockDir, `heartbeat.${process.pid}.${randomUUID()}.tmp`);
  try {
    await writeFile(
      tempPath,
      `${JSON.stringify(
        {
          pid: process.pid,
          token,
          heartbeatAt: new Date().toISOString(),
        },
        null,
        2
      )}\n`
    );
    await rename(tempPath, heartbeatPath);
  } catch (err) {
    await rm(tempPath, { force: true });
    throw err;
  }
}

async function refreshPromotionLockHeartbeat(lockDir: string, token: string): Promise<boolean> {
  const owner = await readPromotionLockOwner(lockDir);
  if (owner.token !== token) {
    return false;
  }
  await writePromotionLockHeartbeat(lockDir, token);
  return true;
}

async function readPromotionLockHeartbeatMs(lockDir: string, token: string | null): Promise<number | null> {
  if (!token) return null;
  try {
    return (await stat(promotionHeartbeatPath(lockDir, token))).mtimeMs;
  } catch (err) {
    if (isErrnoCode(err, "ENOENT")) return null;
    throw err;
  }
}

async function reapAbandonedPromotionGuard(guardDir: string): Promise<boolean> {
  let reapStat: { mtimeMs: number };
  try {
    reapStat = await stat(guardDir);
  } catch (err) {
    if (isErrnoCode(err, "ENOENT")) return false;
    throw err;
  }
  if (Date.now() - reapStat.mtimeMs < promotionLockStaleMs()) {
    return false;
  }

  const staleReapDir = `${guardDir}.stale-${process.pid}-${randomUUID()}`;
  try {
    await rename(guardDir, staleReapDir);
  } catch (err) {
    if (isErrnoCode(err, "ENOENT")) return false;
    throw err;
  }
  await rm(staleReapDir, { recursive: true, force: true });
  return true;
}

async function reapAbandonedPromotionGuards(lockDir: string): Promise<boolean> {
  const reapedReapGuard = await reapAbandonedPromotionGuard(promotionReapDir(lockDir));
  const reapedReleaseGuard = await reapAbandonedPromotionGuard(promotionReleaseDir(lockDir));
  return reapedReapGuard || reapedReleaseGuard;
}

async function hasPromotionGuard(lockDir: string): Promise<boolean> {
  return (await pathExists(promotionReapDir(lockDir))) || (await pathExists(promotionReleaseDir(lockDir)));
}

async function reapStalePromotionLock(lockDir: string): Promise<boolean> {
  if (await hasPromotionGuard(lockDir)) {
    await reapAbandonedPromotionGuards(lockDir);
    return false;
  }

  const reapDir = promotionReapDir(lockDir);
  try {
    await mkdir(reapDir);
  } catch (err) {
    if (isErrnoCode(err, "EEXIST")) return false;
    throw err;
  }

  let staleDir: string | null = null;
  try {
    return await reapStalePromotionLockWithGuard(lockDir, (value) => {
      staleDir = value;
    });
  } finally {
    if (staleDir) {
      await rm(staleDir, { recursive: true, force: true });
    }
    await rm(reapDir, { recursive: true, force: true });
  }
}

async function reapStalePromotionLockWithGuard(
  lockDir: string,
  setStaleDir: (staleDir: string) => void
): Promise<boolean> {
  let lockStat: { mtimeMs: number };
  try {
    lockStat = await stat(lockDir);
  } catch (err) {
    if (isErrnoCode(err, "ENOENT")) return false;
    throw err;
  }

  const owner = await readPromotionLockOwner(lockDir);
  const heartbeatMs = await readPromotionLockHeartbeatMs(lockDir, owner.token);
  const lockedAtMs = heartbeatMs ?? owner.heartbeatAtMs ?? owner.acquiredAtMs ?? lockStat.mtimeMs;
  const ownerlessLock = owner.token === null && owner.heartbeatAtMs === null && owner.acquiredAtMs === null;
  const staleAfterMs = ownerlessLock ? promotionLockOwnerlessGraceMs() : promotionLockStaleMs();
  if (Date.now() - lockedAtMs < staleAfterMs) {
    return false;
  }

  const staleDir = `${lockDir}.stale-${process.pid}-${randomUUID()}`;
  try {
    await rename(lockDir, staleDir);
    setStaleDir(staleDir);
  } catch (err) {
    if (isErrnoCode(err, "ENOENT")) return false;
    throw err;
  }

  const staleOwner = await readPromotionLockOwner(staleDir);
  const staleHeartbeatMs = await readPromotionLockHeartbeatMs(staleDir, staleOwner.token);
  const staleLockedAtMs = staleHeartbeatMs ?? staleOwner.heartbeatAtMs ?? staleOwner.acquiredAtMs ?? lockStat.mtimeMs;
  const staleOwnerlessLock =
    staleOwner.token === null && staleOwner.heartbeatAtMs === null && staleOwner.acquiredAtMs === null;
  const staleAfterRecheckMs = staleOwnerlessLock ? promotionLockOwnerlessGraceMs() : promotionLockStaleMs();
  if (Date.now() - staleLockedAtMs < staleAfterRecheckMs) {
    await rename(staleDir, lockDir);
    setStaleDir("");
    return false;
  }

  await rm(staleDir, { recursive: true, force: true });
  setStaleDir("");
  return true;
}

async function releasePromotionLock(lockDir: string, token: string): Promise<void> {
  const releaseDir = promotionReleaseDir(lockDir);
  const deadline = Date.now() + promotionLockTimeoutMs();
  await testHooks?.beforeLockRelease?.(lockDir, token);
  for (;;) {
    try {
      await mkdir(releaseDir);
      break;
    } catch (err) {
      if (!isErrnoCode(err, "EEXIST")) {
        throw err;
      }
      const owner = await readPromotionLockOwner(lockDir);
      if (owner.token !== token) {
        return;
      }
      await reapAbandonedPromotionGuard(releaseDir);
      if (Date.now() >= deadline) {
        throw new Error("Timed out releasing semantic rule promotion lock");
      }
      await sleep(promotionLockRetryMs());
    }
  }

  try {
    const owner = await readPromotionLockOwner(lockDir);
    if (owner.token !== token) {
      return;
    }
    await rm(lockDir, { recursive: true, force: true });
  } finally {
    await rm(releaseDir, { recursive: true, force: true });
  }
}

type PromotionLockLease = {
  assertHeld: () => Promise<void>;
  beforePromotedRuleWrite: () => Promise<void>;
};

async function withPromotionLock<T>(
  memoryDir: string,
  ruleKey: string,
  fn: (lease: PromotionLockLease) => Promise<T>
): Promise<T> {
  const lockDir = promotionLockDir(memoryDir, ruleKey);
  const lockRoot = path.dirname(lockDir);
  const deadline = Date.now() + promotionLockTimeoutMs();
  let lockToken: string | null = null;
  let heartbeat: NodeJS.Timeout | null = null;

  await mkdir(lockRoot, { recursive: true });
  for (;;) {
    try {
      if (await hasPromotionGuard(lockDir)) {
        await reapAbandonedPromotionGuards(lockDir);
        if (Date.now() >= deadline) {
          throw new Error("Timed out acquiring semantic rule promotion lock");
        }
        await sleep(promotionLockRetryMs());
        continue;
      }
      await mkdir(lockDir);
      if (await hasPromotionGuard(lockDir)) {
        await reapAbandonedPromotionGuards(lockDir);
        if (Date.now() >= deadline) {
          throw new Error("Timed out acquiring semantic rule promotion lock");
        }
        await sleep(promotionLockRetryMs());
        continue;
      }
      try {
        lockToken = randomUUID();
        const lockOwner = {
          token: lockToken,
          acquiredAt: new Date().toISOString(),
        };
        const wroteOwner = await tryWritePromotionLockOwner(lockDir, lockOwner);
        if (!wroteOwner) {
          lockToken = null;
          if (Date.now() >= deadline) {
            throw new Error("Timed out acquiring semantic rule promotion lock");
          }
          await sleep(promotionLockRetryMs());
          continue;
        }
        await writePromotionLockHeartbeat(lockDir, lockToken);
        const heartbeatToken = lockToken;
        const heartbeatMs = promotionLockHeartbeatMs();
        if (heartbeatMs > 0) {
          heartbeat = setInterval(() => {
            void refreshPromotionLockHeartbeat(lockDir, heartbeatToken)
              .then((ownsLock) => {
                if (!ownsLock && heartbeat) {
                  clearInterval(heartbeat);
                  heartbeat = null;
                }
              })
              .catch(() => undefined);
          }, heartbeatMs);
        }
      } catch (err) {
        lockToken = null;
        if (heartbeat) {
          clearInterval(heartbeat);
          heartbeat = null;
        }
        await rm(lockDir, { recursive: true, force: true });
        throw err;
      }
      break;
    } catch (err) {
      if (!isErrnoCode(err, "EEXIST")) {
        throw err;
      }
      if (await reapStalePromotionLock(lockDir)) {
        continue;
      }
      if (Date.now() >= deadline) {
        throw new Error("Timed out acquiring semantic rule promotion lock");
      }
      await sleep(promotionLockRetryMs());
    }
  }

  const assertHeld = async () => {
    if (!lockToken) {
      throw new Error("Semantic rule promotion lock is no longer held");
    }
    const ownsLock = await refreshPromotionLockHeartbeat(lockDir, lockToken);
    if (!ownsLock) {
      throw new Error("Semantic rule promotion lock is no longer held");
    }
  };

  let hasResult = false;
  let result: T | undefined;
  let callbackError: unknown;
  let releaseError: unknown;
  try {
    await assertHeld();
    result = await fn({
      assertHeld,
      beforePromotedRuleWrite: async () => {
        if (!lockToken) {
          throw new Error("Semantic rule promotion lock is no longer held");
        }
        await testHooks?.beforePromotedRuleWrite?.(lockDir, lockToken);
        await assertHeld();
      },
    });
    hasResult = true;
  } catch (err) {
    callbackError = err;
  } finally {
    if (heartbeat) {
      clearInterval(heartbeat);
    }
    if (lockToken) {
      try {
        await releasePromotionLock(lockDir, lockToken);
      } catch (err) {
        if (!hasResult && !callbackError) {
          releaseError = err;
        }
      }
    }
  }
  if (releaseError) {
    throw releaseError;
  }
  if (callbackError) {
    throw callbackError;
  }
  return result as T;
}

function normalizeRuleWhitespace(value: string): string {
  return value.replace(/\s+/g, " ").trim();
}

function stripTrailingClausePunctuation(value: string): string {
  // Linear trailing-punctuation strip (no `/[,:;]+$/` — CodeQL flags that as a
  // polynomial-backtracking ReDoS on long runs of ',;:'). Walk back once, O(n).
  let end = value.length;
  while (end > 0) {
    const ch = value[end - 1];
    if (ch === "," || ch === ":" || ch === ";") end--;
    else break;
  }
  return value.slice(0, end).trim();
}

function canonicalizeRuleContent(value: string): string {
  return extractExplicitIfThenRule(value) ?? normalizeRuleWhitespace(value);
}

function canonicalizeRuleKey(value: string): string {
  return canonicalizeRuleContent(value).toLowerCase();
}

function extractExplicitIfThenRule(content: string): string | null {
  const match = content.match(/\bif\b([\s\S]+?)\bthen\b([\s\S]+?)(?:[.!?](?:\s|$)|$)/i);
  if (!match) return null;
  const condition = stripTrailingClausePunctuation(normalizeRuleWhitespace(match[1] ?? ""));
  const outcome = stripTrailingClausePunctuation(normalizeRuleWhitespace(match[2] ?? ""));
  if (condition.length === 0 || outcome.length === 0) return null;
  return `IF ${condition} THEN ${outcome}.`;
}

function promotionConfidence(memory: MemoryFile): number {
  const base = Number.isFinite(memory.frontmatter.confidence) ? memory.frontmatter.confidence : 0.8;
  return Math.max(0.6, Math.min(0.98, base));
}

function promotionTags(memory: MemoryFile): string[] {
  return Array.from(new Set([...(memory.frontmatter.tags ?? []), "semantic-rule", "promoted-rule"]));
}

function buildSupportLinks(sourceMemoryId: string, confidence: number): MemoryLink[] {
  return [
    {
      targetId: sourceMemoryId,
      linkType: "supports",
      strength: confidence,
      reason: "Promoted from verified episodic memory",
    },
  ];
}

export async function promoteSemanticRuleFromMemory(options: {
  memoryDir: string;
  enabled: boolean;
  sourceMemoryId: string;
  dryRun?: boolean;
}): Promise<SemanticRulePromotionReport> {
  const report: SemanticRulePromotionReport = {
    enabled: options.enabled,
    dryRun: options.dryRun === true,
    promoted: [],
    skipped: [],
  };
  if (!options.enabled) {
    report.skipped.push({
      sourceMemoryId: options.sourceMemoryId,
      reason: "disabled",
    });
    return report;
  }

  const storage = new StorageManager(options.memoryDir);
  const sourceMemory = await storage.getMemoryById(options.sourceMemoryId);
  if (!sourceMemory) {
    report.skipped.push({
      sourceMemoryId: options.sourceMemoryId,
      reason: "source-memory-missing",
    });
    return report;
  }
  if (sourceMemory.frontmatter.status === "forgotten") {
    report.skipped.push({
      sourceMemoryId: options.sourceMemoryId,
      reason: "source-memory-forgotten",
    });
    return report;
  }
  if (sourceMemory.frontmatter.status === "archived" || sourceMemory.frontmatter.memoryKind !== "episode") {
    report.skipped.push({
      sourceMemoryId: options.sourceMemoryId,
      reason: "source-memory-not-episode",
    });
    return report;
  }

  const content = extractExplicitIfThenRule(sourceMemory.content);
  if (!content) {
    report.skipped.push({
      sourceMemoryId: options.sourceMemoryId,
      reason: "no-explicit-rule",
    });
    return report;
  }

  const ruleKey = canonicalizeRuleKey(content);
  const confidence = promotionConfidence(sourceMemory);
  const candidateBase = {
    sourceMemoryId: options.sourceMemoryId,
    content,
    confidence,
    tags: promotionTags(sourceMemory),
    memoryKind: "note" as const,
    lineage: [options.sourceMemoryId],
  };

  return withPromotionLock(options.memoryDir, ruleKey, async (lock) => {
    storage.invalidateAllMemoriesCacheForDir({ indexedText: false });
    const existingRule = (await storage.readAllMemories()).find(
      (memory) =>
        memory.frontmatter.category === "rule" &&
        memory.frontmatter.status !== "archived" &&
        memory.frontmatter.status !== "forgotten" &&
        canonicalizeRuleKey(memory.content) === ruleKey
    );
    if (existingRule) {
      report.skipped.push({
        sourceMemoryId: options.sourceMemoryId,
        reason: "duplicate-rule",
        existingRuleId: existingRule.frontmatter.id,
      });
      return report;
    }

    if (options.dryRun === true) {
      await lock.assertHeld();
      report.promoted.push({
        id: `dry-run:${options.sourceMemoryId}`,
        ...candidateBase,
      });
      return report;
    }

    await lock.beforePromotedRuleWrite();
    // Sealed-envelope write (issue #1989 PR4): rule content and tags are
    // derived from stored/LLM data — salvage; drops are warn-logged.
    const ruleEnvelope = composeMemoryEnvelope(
      { content, category: "rule", confidence, tags: candidateBase.tags, origin: sourceMemory.frontmatter.origin },
      { source: "semantic-rule-promotion" },
      { salvage: true },
    );
    if (ruleEnvelope.salvageNotes.length > 0) {
      log.warn(`rule-promotion write salvaged invalid fields: ${ruleEnvelope.salvageNotes.join("; ")}`);
    }
    const { id: id } = await storage.writeSealedMemory(ruleEnvelope, {
      lineage: candidateBase.lineage,
      sourceMemoryId: options.sourceMemoryId,
      memoryKind: "note",
      links: buildSupportLinks(options.sourceMemoryId, confidence),
    });
    report.promoted.push({
      id,
      ...candidateBase,
    });
    return report;
  });
}

/**
 * Training-data converter.
 *
 * Reads memory markdown files from a memoryDir, parses YAML
 * frontmatter, applies filters, and returns TrainingExportRecord[].
 *
 * Instruction is derived from the memory's category/tags.
 * Output is the memory content body.
 * The `input` field is empty string (synthesis is left to adapters).
 */

import { constants } from "node:fs";
import { lstat, open, readdir, realpath } from "node:fs/promises";
import path from "node:path";

import { parseStrictCliDate } from "./date-parse.js";
import type { TrainingExportOptions, TrainingExportRecord } from "./types.js";
import { isSupportPassportPrivateMemory } from "../support-passport/card-projection.js";
import { RECALL_FALLBACK_DIRS } from "../utils/category-dir.js";

// ---------------------------------------------------------------------------
// Frontmatter parsing (mirrors storage.ts but kept standalone)
// ---------------------------------------------------------------------------

interface ParsedMemory {
  id: string;
  category: string;
  confidence: number;
  created: string;
  updated: string;
  tags: string[];
  content: string;
  filePath: string;
}

function parseFrontmatter(raw: string): ParsedMemory | null {
  const match = raw.match(/^---\n([\s\S]*?)\n---\n?([\s\S]*)$/);
  if (!match) return null;

  const fmBlock = match[1];
  const content = (match[2] ?? "").trim();
  const fm: Record<string, string> = {};

  for (const line of fmBlock.split("\n")) {
    const colonIdx = line.indexOf(":");
    if (colonIdx === -1) continue;
    const key = line.slice(0, colonIdx).trim();
    const value = line.slice(colonIdx + 1).trim();
    fm[key] = value;
  }

  let tags: string[] = [];
  const tagsStr = fm.tags ?? "";
  const tagMatch = tagsStr.match(/\[(.*)]/);
  if (tagMatch) {
    tags = tagMatch[1]
      .split(",")
      .map((t) => t.trim().replace(/^"|"$/g, ""))
      .filter(Boolean);
  }

  const confidence = parseFloat(fm.confidence ?? "0.8");

  return {
    id: fm.id ?? "",
    category: fm.category ?? "fact",
    confidence: Number.isFinite(confidence) ? confidence : 0.8,
    created: fm.created ?? "",
    updated: fm.updated ?? "",
    tags,
    content,
    filePath: "",
  };
}

// ---------------------------------------------------------------------------
// Recursive directory scan
// ---------------------------------------------------------------------------

/**
 * Resolve the canonical real path of `dir`. Used as the containment root
 * when rejecting symlinks that escape `memoryDir` (data-exfil protection).
 */
async function safeRealpath(p: string): Promise<string | null> {
  try {
    return await realpath(p);
  } catch {
    return null;
  }
}

function isContainedPath(real: string, containmentRoot: string): boolean {
  return real === containmentRoot || real.startsWith(containmentRoot + path.sep);
}

/**
 * Recursively collect `.md` files under `dir`, returning deterministic,
 * lexicographically-sorted absolute paths.
 *
 * Security: rejects symlinks outright. A symlink named `facts/private.md`
 * pointing to `~/.ssh/id_rsa` (or a symlinked `facts/` directory pointing
 * outside `memoryDir`) must NOT be read/exported — that would be a data
 * exfiltration path out of the memory store.
 *
 * `containmentRoot` is the canonical real path that every resolved file
 * must sit under. Callers pass the real path of the memoryDir so symlinked
 * subdirectories (e.g. `facts/` pointing at `/tmp/other/facts`) cannot
 * leak files from outside the memory store.
 */
async function collectMarkdownFiles(
  dir: string,
  containmentRoot: string,
): Promise<string[]> {
  const files: string[] = [];

  const walk = async (d: string): Promise<void> => {
    // Refuse to descend into `d` at all if it is a symlink — regardless of
    // whether the symlink happens to still point inside `containmentRoot`,
    // traversing symlinked directories is easy to weaponise via TOCTOU.
    let dStat: import("node:fs").Stats | null = null;
    try {
      dStat = await lstat(d);
    } catch {
      return;
    }
    if (dStat.isSymbolicLink()) return;

    let entries: import("node:fs").Dirent[];
    try {
      entries = await readdir(d, { withFileTypes: true });
    } catch {
      return; // directory does not exist or is unreadable
    }

    // Sort entries lexicographically for deterministic output ordering.
    // `readdir` does not guarantee order across filesystems/platforms, which
    // would otherwise make identical corpora produce different dataset files.
    const sorted = [...entries].sort((a, b) => a.name.localeCompare(b.name));

    for (const entry of sorted) {
      const full = path.join(d, entry.name);

      // Skip symlinked entries entirely (security: prevents traversal out of
      // memoryDir). withFileTypes=true gives us the entry kind from lstat-
      // semantics, so we don't follow the link.
      if (entry.isSymbolicLink()) continue;

      if (entry.isDirectory()) {
        await walk(full);
      } else if (entry.isFile() && entry.name.endsWith(".md")) {
        // Defense in depth: confirm the resolved real path still lives under
        // the canonical containment root. `realpath` alone is not enough to
        // catch hard links that point at out-of-tree inodes (a hard link IS
        // the file, so realpath returns the in-tree path). We therefore also
        // reject entries whose `nlink > 1`: memory files should have a single
        // directory entry, and any additional hard link is a potential
        // exfiltration vector that the operator did not intend.
        let st: import("node:fs").Stats | null = null;
        try {
          st = await lstat(full);
        } catch {
          continue;
        }
        if (st.nlink > 1) continue;

        const real = await safeRealpath(full);
        if (!real) continue;
        if (!isContainedPath(real, containmentRoot)) {
          continue;
        }
        files.push(full);
      }
    }
  };

  await walk(dir);

  // Final stable sort of the absolute paths guarantees order regardless of
  // directory traversal quirks.
  return files.sort((a, b) => a.localeCompare(b));
}

export async function readContainedMarkdownFile(
  filePath: string,
  containmentRoot: string,
): Promise<string | null> {
  let handle: Awaited<ReturnType<typeof open>> | null = null;
  try {
    handle = await open(filePath, constants.O_RDONLY | constants.O_NOFOLLOW);
    const st = await handle.stat();
    if (!st.isFile() || st.nlink > 1) return null;

    const real = await safeRealpath(filePath);
    if (!real || !isContainedPath(real, containmentRoot)) return null;

    return await handle.readFile("utf-8");
  } catch {
    return null;
  } finally {
    await handle?.close().catch(() => undefined);
  }
}

// ---------------------------------------------------------------------------
// Build instruction from category + tags
// ---------------------------------------------------------------------------

function buildInstruction(category: string, tags: string[]): string {
  const tagSuffix = tags.length > 0 ? ` (${tags.join(", ")})` : "";
  switch (category) {
    case "fact":
      return `Recall a factual memory${tagSuffix}`;
    case "preference":
      return `Recall a user preference${tagSuffix}`;
    case "correction":
      return `Recall a correction${tagSuffix}`;
    case "entity":
      return `Recall entity information${tagSuffix}`;
    case "decision":
      return `Recall a decision${tagSuffix}`;
    case "relationship":
      return `Recall a relationship${tagSuffix}`;
    case "principle":
      return `Recall a principle${tagSuffix}`;
    case "commitment":
      return `Recall a commitment${tagSuffix}`;
    case "moment":
      return `Recall a moment${tagSuffix}`;
    case "skill":
      return `Recall a skill${tagSuffix}`;
    case "rule":
      return `Recall a rule${tagSuffix}`;
    case "personal":
      return `Recall personal information${tagSuffix}`;
    default:
      return `Recall a memory${tagSuffix}`;
  }
}

// ---------------------------------------------------------------------------
// Date helpers
// ---------------------------------------------------------------------------

function parseIsoDate(isoStr: string): Date | null {
  if (!isoStr) return null;
  try {
    return parseStrictCliDate(isoStr, "memory created timestamp");
  } catch {
    return null;
  }
}

// ---------------------------------------------------------------------------
// Public API
// ---------------------------------------------------------------------------

/**
 * Read memories from `memoryDir`, apply option filters, and return
 * an array of TrainingExportRecord for downstream adapters.
 */
export async function convertMemoriesToRecords(
  options: TrainingExportOptions,
): Promise<TrainingExportRecord[]> {
  const { memoryDir } = options;

  // Canonicalise the memoryDir once — this is the containment root every
  // resolved `.md` file must sit under (symlink/hard-link escape defense).
  const containmentRoot = await safeRealpath(memoryDir);
  if (!containmentRoot) return [];

  // Collect from every recall category directory (RECALL_FALLBACK_DIRS — the
  // single source of truth), so newly-routed categories (decisions/,
  // preferences/, ...) are exported, not just facts/ + corrections/ (#1546).
  // collectMarkdownFiles recurses, so flat (corrections/) vs dated
  // (decisions/<date>/) layouts are both handled.
  const dirs = RECALL_FALLBACK_DIRS.map((dir) => path.join(memoryDir, dir));
  if (options.includeEntities) {
    // entities/ is NOT a recall category — it stays a separate opt-in include.
    dirs.push(path.join(memoryDir, "entities"));
  }

  const allFiles: string[] = [];
  for (const dir of dirs) {
    const files = await collectMarkdownFiles(dir, containmentRoot);
    allFiles.push(...files);
  }

  const records: TrainingExportRecord[] = [];

  for (const filePath of allFiles) {
    const raw = await readContainedMarkdownFile(filePath, containmentRoot);
    if (raw === null) continue; // skip unreadable files

    const parsed = parseFrontmatter(raw);
    if (!parsed) continue; // skip malformed files
    if (!parsed.content) continue; // skip empty content
    if (isSupportPassportPrivateMemory({ frontmatter: { tags: parsed.tags } })) continue;

    parsed.filePath = filePath;

    // --- Apply filters ---

    // minConfidence (CLAUDE.md #35: half-open intervals where applicable,
    // but confidence is an inclusive lower bound)
    if (
      options.minConfidence !== undefined &&
      parsed.confidence < options.minConfidence
    ) {
      continue;
    }

    // categories filter
    if (
      options.categories !== undefined &&
      options.categories.length > 0 &&
      !options.categories.includes(parsed.category)
    ) {
      continue;
    }

    // since filter (half-open: created >= since)
    if (options.since) {
      const created = parseIsoDate(parsed.created);
      // Exclude memories with missing/unparseable dates when date filters are active
      if (!created || created.getTime() < options.since.getTime()) {
        continue;
      }
    }

    // until filter (exclusive upper bound per CLAUDE.md #35: created < until)
    if (options.until) {
      const created = parseIsoDate(parsed.created);
      // Exclude memories with missing/unparseable dates when date filters are active
      if (!created || created.getTime() >= options.until.getTime()) {
        continue;
      }
    }

    records.push({
      instruction: buildInstruction(parsed.category, parsed.tags),
      input: "",
      output: parsed.content,
      category: parsed.category,
      confidence: parsed.confidence,
      sourceIds: parsed.id ? [parsed.id] : undefined,
    });
  }

  return records;
}

import { mkdir, readFile, readdir, rename, stat, unlink, writeFile } from "node:fs/promises";
import path from "node:path";
import { log } from "./logger.js";
import { displayErrorDetail } from "./runtime/better-sqlite.js";
import { parseSessionIdentity, sessionStoragePaths } from "./session-identity.js";
import { resolveSafeStoragePath } from "./storage-paths.js";
import type { TranscriptEntry } from "./types.js";

/**
 * Lossless migration of legacy `transcripts/other/default/*.jsonl` files into
 * first-class `transcripts/session/<hash>/*.jsonl` directories (issue #1496).
 *
 * Older builds routed every non-legacy session key (e.g. `pi-geek:abc123`)
 * into the shared `other/default` directory on first write. That conflated
 * distinct standalone-client sessions into one transcript directory. This
 * migration splits those mixed files back out, grouping entries by
 * `entry.sessionKey` and re-homing each distinct session under its own
 * deterministic hashed directory.
 *
 * Safety contract (rules #54, #51, #18, #35):
 *   - Dry-run is the default; nothing is written without `apply: true`.
 *   - Writes go to a temp file then atomic-rename (never delete-before-write).
 *   - JSONL line ordering and byte content are preserved per session.
 *   - Idempotent: re-running after apply finds nothing left to migrate.
 *   - A manifest is returned (and written under `state/` on apply) as an audit
 *     trail.
 */

/**
 * Channel type that NEW writes use for first-class arbitrary keys. Subdirs of
 * this type whose `<id>` is a canonical `storagePathHash` (16 lowercase hex)
 * are already homed — every line there is, by definition, already in its
 * destination directory, so they are never migration sources.
 */
const FIRST_CLASS_CHANNEL_TYPE = "session";

/**
 * Matches a canonical `session/<hash>` channel id produced by
 * {@link storagePathHash} (16 lowercase hex chars). Used to tell a NEW
 * first-class directory (skip) apart from a LEGACY `session/<name>` directory.
 *
 * Pre-#1496 the OLD `parts.length >= 3` parser stored a key whose 3rd colon
 * segment was literally `session` (e.g. `foo:bar:session:baz`) under
 * `transcripts/session/baz` — a non-hash id. Those legacy dirs MUST still be
 * scanned and split, while genuine `session/<hash>` data is left untouched
 * (codex review on PR #1496 / PR #1504). The hex length is fixed because
 * `storagePathHash` slices the sha256 hex digest to 16 chars.
 */
const CANONICAL_SESSION_HASH_RE = /^[0-9a-f]{16}$/;

/**
 * True when `<type>/<id>` is a canonical first-class `session/<hash>` directory
 * (NEW write target) rather than a legacy stranded directory. Defensive: also
 * confirms the id is exactly what `storagePathHash` would produce for some
 * value by shape — a 16-hex string — so we never misclassify a legacy
 * `session/<name>` dir as homed and skip migrating it.
 */
function isCanonicalSessionDir(channelType: string, channelId: string): boolean {
  return channelType === FIRST_CLASS_CHANNEL_TYPE && CANONICAL_SESSION_HASH_RE.test(channelId);
}

export interface SessionMigrationEntryGroup {
  /** The distinct session key these lines belong to. */
  sessionKey: string;
  /** Whether this key is a recognized legacy `agent:<id>:...` shape. */
  legacy: boolean;
  /** Destination directory (relative to the transcripts root). */
  destDir: string;
  /** Number of JSONL entries that will move. */
  entryCount: number;
}

export interface SessionMigrationFilePlan {
  /** Source file path (relative to transcripts root). */
  sourceRelPath: string;
  /** The date-stamped file name (e.g. `2026-06-29.jsonl`). */
  fileName: string;
  /** Distinct session groups discovered inside this source file. */
  groups: SessionMigrationEntryGroup[];
  /** Lines that could not be parsed as JSON or lacked a sessionKey. */
  unmovableLines: number;
  /**
   * True when EVERY entry in the file already belongs in the source directory
   * (nothing to do). Such files are skipped.
   */
  alreadyHomed: boolean;
}

export interface SessionMigrationPlan {
  generatedAt: string;
  dryRun: boolean;
  transcriptsDir: string;
  /** Per-file plans that have at least one entry to move. */
  files: SessionMigrationFilePlan[];
  /** Distinct destination session keys across all files. */
  distinctSessions: number;
  /** Total entries that will be re-homed. */
  movedEntries: number;
}

export interface SessionMigrationResult {
  plan: SessionMigrationPlan;
  applied: boolean;
  filesRewritten: number;
  filesRemoved: number;
  errors: string[];
  manifestPath?: string;
}

export interface MigrateSessionTranscriptsOptions {
  /** The memory directory root (transcripts live under `<memoryDir>/transcripts`). */
  memoryDir: string;
  /** When true, perform the migration; otherwise produce a dry-run plan only. */
  apply?: boolean;
}

const DATE_FILE_RE = /^\d{4}-\d{2}-\d{2}\.jsonl$/;

function isDateStampedJsonl(name: string): boolean {
  return DATE_FILE_RE.test(name);
}

/**
 * Candidate source directories that older builds may have used to conflate or
 * misroute arbitrary sessions. We scan `transcripts/<type>/<id>/` two levels
 * deep and consider any directory EXCEPT the first-class `session/<hash>` tree
 * (whose contents are already homed). This covers:
 *
 *   - the shared `other/default` fallback every arbitrary key once landed in;
 *   - the OLD `parts.length >= 3` parser's directories (e.g. `foo:bar:baz` →
 *     `baz/default`, `foo:bar:baz:qux` → `baz/qux`), which the pre-#1496 build
 *     wrote even for non-`agent:` keys (Thread B / codex review on PR #1504).
 *
 * `planFile` is the actual gate: a line is only moved when its session key now
 * resolves to a DIFFERENT directory than the one it sits in. Legacy
 * `agent:<id>:...` keys still resolve to their original channel directory, so
 * scanning `main/default`, `discord/<chan>`, etc. is a safe no-op for them
 * (rule #39 — identical routing across paths). This keeps the migration
 * lossless and idempotent regardless of which directory data was stranded in.
 */
async function listFallbackSourceFiles(
  transcriptsDir: string
): Promise<Array<{ relPath: string; fileName: string; absPath: string }>> {
  const out: Array<{ relPath: string; fileName: string; absPath: string }> = [];
  let typeEntries: Array<{ name: string; isDirectory(): boolean }>;
  try {
    typeEntries = await readdir(transcriptsDir, { withFileTypes: true });
  } catch {
    return out;
  }

  for (const typeEnt of typeEntries) {
    if (!typeEnt.isDirectory()) continue;

    const typeDir = path.join(transcriptsDir, typeEnt.name);
    let idEntries: Array<{ name: string; isDirectory(): boolean }>;
    try {
      idEntries = await readdir(typeDir, { withFileTypes: true });
    } catch {
      continue;
    }

    for (const idEnt of idEntries) {
      if (!idEnt.isDirectory()) continue;

      // Only canonical `session/<hash>` dirs are already homed — skip those.
      // A LEGACY `session/<name>` dir (e.g. `foo:bar:session:baz` →
      // `session/baz` under the OLD parser) is a real migration source and
      // must be scanned/split (codex review on PR #1504). `planFile`'s
      // destination gate still guarantees losslessness/idempotence.
      if (isCanonicalSessionDir(typeEnt.name, idEnt.name)) continue;

      const chanDir = path.join(typeDir, idEnt.name);
      let files: string[];
      try {
        files = (await readdir(chanDir)).filter((f) => f.endsWith(".jsonl")).sort();
      } catch {
        continue;
      }
      for (const fileName of files) {
        out.push({
          relPath: path.join(typeEnt.name, idEnt.name, fileName),
          fileName,
          absPath: path.join(chanDir, fileName),
        });
      }
    }
  }

  return out.sort((a, b) => a.relPath.localeCompare(b.relPath));
}

interface ParsedSourceLine {
  sessionKey?: string;
  /** The raw JSONL text (without trailing newline). */
  raw: string;
}

/**
 * Parse a source JSONL file, preserving line order. Lines that are not valid
 * JSON or lack a string `sessionKey` are tracked as unmovable and left in the
 * source file so no data is lost (rule #18 — validate parse result type).
 */
function parseSourceLines(content: string): ParsedSourceLine[] {
  const out: ParsedSourceLine[] = [];
  for (const line of content.split("\n")) {
    if (!line.trim()) continue;
    let sessionKey: string | undefined;
    try {
      const parsed: unknown = JSON.parse(line);
      if (parsed && typeof parsed === "object") {
        const sk = (parsed as { sessionKey?: unknown }).sessionKey;
        if (typeof sk === "string" && sk.length > 0) {
          sessionKey = sk;
        }
      }
    } catch {
      // Unparseable line — keep it in place.
    }
    out.push({ sessionKey, raw: line });
  }
  return out;
}

/**
 * Build a per-file migration plan. A line is "movable" when its session key
 * resolves to a destination directory different from the source directory.
 */
function planFile(sourceRelPath: string, fileName: string, lines: ParsedSourceLine[]): SessionMigrationFilePlan {
  const sourceDir = path.dirname(sourceRelPath);
  const groups = new Map<string, { legacy: boolean; destDir: string; count: number }>();
  let unmovableLines = 0;
  let movableCount = 0;

  for (const line of lines) {
    if (!line.sessionKey) {
      unmovableLines += 1;
      continue;
    }
    const identity = parseSessionIdentity(line.sessionKey);
    const paths = sessionStoragePaths(line.sessionKey);
    // Only move when the destination directory differs from the source.
    if (paths.dir === sourceDir) {
      continue;
    }
    movableCount += 1;
    const existing = groups.get(line.sessionKey);
    if (existing) {
      existing.count += 1;
    } else {
      groups.set(line.sessionKey, {
        legacy: identity.legacy,
        destDir: paths.dir,
        count: 1,
      });
    }
  }

  const groupList: SessionMigrationEntryGroup[] = [...groups.entries()]
    .map(([sessionKey, info]) => ({
      sessionKey,
      legacy: info.legacy,
      destDir: info.destDir,
      entryCount: info.count,
    }))
    .sort((a, b) => a.sessionKey.localeCompare(b.sessionKey));

  return {
    sourceRelPath,
    fileName,
    groups: groupList,
    unmovableLines,
    alreadyHomed: movableCount === 0,
  };
}

/**
 * Compute the migration plan without modifying anything.
 */
export async function planSessionTranscriptMigration(
  options: MigrateSessionTranscriptsOptions
): Promise<SessionMigrationPlan> {
  const transcriptsDir = path.join(options.memoryDir, "transcripts");
  const sources = await listFallbackSourceFiles(transcriptsDir);
  const files: SessionMigrationFilePlan[] = [];
  const distinctSessions = new Set<string>();
  let movedEntries = 0;

  for (const source of sources) {
    if (!isDateStampedJsonl(source.fileName)) continue;
    let content: string;
    try {
      content = await readFile(source.absPath, "utf-8");
    } catch {
      continue;
    }
    const lines = parseSourceLines(content);
    const filePlan = planFile(source.relPath, source.fileName, lines);
    if (filePlan.alreadyHomed) continue;

    for (const group of filePlan.groups) {
      distinctSessions.add(group.sessionKey);
      movedEntries += group.entryCount;
    }
    files.push(filePlan);
  }

  return {
    generatedAt: new Date().toISOString(),
    dryRun: options.apply !== true,
    transcriptsDir,
    files,
    distinctSessions: distinctSessions.size,
    movedEntries,
  };
}

/**
 * Append `lines` (raw JSONL strings) to `<destDir>/<fileName>` using a
 * write-then-rename merge so a crash mid-migration cannot corrupt or truncate
 * the destination (rule #54).
 *
 * Existing destination content is preserved and de-duplicated by raw line so
 * re-running the migration is idempotent.
 */
async function mergeAppendLines(
  transcriptsDir: string,
  destDir: string,
  fileName: string,
  newLines: string[]
): Promise<void> {
  const destChannelDir = await resolveSafeStoragePath(transcriptsDir, destDir);
  await mkdir(destChannelDir, { recursive: true });
  const destPath = await resolveSafeStoragePath(transcriptsDir, destDir, fileName);

  const existing: string[] = [];
  const seen = new Set<string>();
  try {
    const raw = await readFile(destPath, "utf-8");
    for (const line of raw.split("\n")) {
      if (!line.trim()) continue;
      existing.push(line);
      seen.add(line);
    }
  } catch {
    // No existing destination file — fine.
  }

  const merged = [...existing];
  for (const line of newLines) {
    if (seen.has(line)) continue;
    merged.push(line);
    seen.add(line);
  }

  const body = merged.length > 0 ? `${merged.join("\n")}\n` : "";
  const tmpPath = await resolveSafeStoragePath(
    transcriptsDir,
    destDir,
    `${fileName}.migrate-${process.pid}-${Date.now()}.tmp`
  );
  await writeFile(tmpPath, body, "utf-8");
  await rename(tmpPath, destPath);
}

/**
 * Rewrite the source file to retain ONLY the lines that were not moved
 * (unparseable lines and any that already belong in the source dir). Uses
 * write-then-rename; deletes the source only when nothing remains.
 */
async function rewriteSourceRetainingUnmoved(
  transcriptsDir: string,
  sourceRelPath: string,
  retainedLines: string[]
): Promise<{ removed: boolean }> {
  const sourcePath = await resolveSafeStoragePath(transcriptsDir, sourceRelPath);
  if (retainedLines.length === 0) {
    // Atomic-rename into a sibling tombstone then unlink, so a crash leaves the
    // original intact (never delete-before-confirm; rule #54). Simpler and
    // equally safe: unlink only after destinations are confirmed written.
    try {
      await unlink(sourcePath);
    } catch (err) {
      const code =
        err && typeof err === "object" && "code" in err ? String((err as { code?: unknown }).code ?? "") : "";
      if (code !== "ENOENT") throw err;
    }
    return { removed: true };
  }

  const body = `${retainedLines.join("\n")}\n`;
  const sourceDir = path.dirname(sourceRelPath);
  const tmpPath = await resolveSafeStoragePath(
    transcriptsDir,
    sourceDir,
    `${path.basename(sourceRelPath)}.migrate-${process.pid}-${Date.now()}.tmp`
  );
  await writeFile(tmpPath, body, "utf-8");
  await rename(tmpPath, sourcePath);
  return { removed: false };
}

/**
 * Run the migration. Dry-run by default; pass `apply: true` to mutate.
 */
export async function migrateSessionTranscripts(
  options: MigrateSessionTranscriptsOptions
): Promise<SessionMigrationResult> {
  const plan = await planSessionTranscriptMigration(options);
  const apply = options.apply === true;

  if (!apply) {
    return {
      plan,
      applied: false,
      filesRewritten: 0,
      filesRemoved: 0,
      errors: [],
    };
  }

  const transcriptsDir = plan.transcriptsDir;
  const errors: string[] = [];
  let filesRewritten = 0;
  let filesRemoved = 0;

  for (const filePlan of plan.files) {
    try {
      const sourcePath = await resolveSafeStoragePath(transcriptsDir, filePlan.sourceRelPath);
      const content = await readFile(sourcePath, "utf-8");
      const lines = parseSourceLines(content);
      const sourceDir = path.dirname(filePlan.sourceRelPath);

      // Bucket lines by destination, preserving order. Retain unmovable lines
      // and any line already homed in the source dir.
      const byDest = new Map<string, string[]>();
      const retained: string[] = [];
      for (const line of lines) {
        if (!line.sessionKey) {
          retained.push(line.raw);
          continue;
        }
        const dest = sessionStoragePaths(line.sessionKey).dir;
        if (dest === sourceDir) {
          retained.push(line.raw);
          continue;
        }
        const bucket = byDest.get(dest) ?? [];
        bucket.push(line.raw);
        byDest.set(dest, bucket);
      }

      // 1. Write destinations FIRST (write-then-rename, idempotent merge).
      for (const [destDir, destLines] of byDest.entries()) {
        await mergeAppendLines(transcriptsDir, destDir, filePlan.fileName, destLines);
      }

      // 2. Only after all destinations are confirmed, rewrite/remove source.
      const { removed } = await rewriteSourceRetainingUnmoved(transcriptsDir, filePlan.sourceRelPath, retained);
      if (removed) {
        filesRemoved += 1;
      } else {
        filesRewritten += 1;
      }
    } catch (err) {
      // The `errors` array is surfaced to operators via the CLI
      // (`sessions migrate-transcripts --apply`) AND persisted in the audit
      // manifest. Raw `err.message`/`String(err)` can leak filesystem paths or
      // stack detail, so route operator-facing strings through the shared
      // `displayErrorDetail()` sanitizer (cursor review on PR #1504, rule #51).
      // The full error still goes to the operator-only debug log.
      const detail = displayErrorDetail(err);
      errors.push(
        `Failed to migrate ${filePlan.sourceRelPath}${detail ? `: ${detail}` : ""}`,
      );
      log.error(`session transcript migration failed for ${filePlan.sourceRelPath}:`, err);
    }
  }

  let manifestPath: string | undefined;
  try {
    manifestPath = await writeManifest(options.memoryDir, {
      plan,
      applied: true,
      filesRewritten,
      filesRemoved,
      errors,
    });
  } catch (err) {
    // Manifest is best-effort audit; do not fail the migration over it.
    log.debug(`failed to write session migration manifest: ${err}`);
  }

  return {
    plan,
    applied: true,
    filesRewritten,
    filesRemoved,
    errors,
    manifestPath,
  };
}

async function writeManifest(memoryDir: string, result: Omit<SessionMigrationResult, "manifestPath">): Promise<string> {
  const auditDir = path.join(memoryDir, "state", "session-migration");
  await mkdir(auditDir, { recursive: true });
  const stamp = new Date().toISOString().replace(/[:.]/g, "-");
  const manifestPath = path.join(auditDir, `migrate-transcripts-${stamp}.json`);
  await writeFile(manifestPath, JSON.stringify(result, null, 2), "utf-8");
  return manifestPath;
}

/** Best-effort byte-size summary for reporting (used by CLI output). */
export async function summarizeMigrationSources(memoryDir: string): Promise<{ files: number; bytes: number }> {
  const transcriptsDir = path.join(memoryDir, "transcripts");
  const sources = await listFallbackSourceFiles(transcriptsDir);
  let bytes = 0;
  let files = 0;
  for (const source of sources) {
    const info = await stat(source.absPath).catch(() => null);
    if (info?.isFile()) {
      bytes += info.size;
      files += 1;
    }
  }
  return { files, bytes };
}

/**
 * Training-export adapter registry.
 *
 * Maintains a name → adapter map so CLI and programmatic callers
 * can look up format-specific adapters at runtime.
 */

import type { TrainingExportAdapter } from "./types.js";

const adapters = new Map<string, TrainingExportAdapter>();

/**
 * Register a training-export adapter.
 *
 * Rejects empty names and duplicate registrations with an error
 * listing valid actions (CLAUDE.md rule #51).
 */
export function registerTrainingExportAdapter(adapter: TrainingExportAdapter): void {
  if (!adapter || typeof adapter !== "object" || Array.isArray(adapter)) {
    throw new Error(
      "registerTrainingExportAdapter: adapter must be an object with name, fileExtension, and formatRecords.",
    );
  }
  if (typeof adapter.name !== "string" || adapter.name.trim().length === 0) {
    throw new Error(
      "registerTrainingExportAdapter: adapter.name must be a non-empty string. " +
        "Provide a unique adapter name (e.g. 'weclone', 'axolotl', 'mlx').",
    );
  }
  if (typeof adapter.formatRecords !== "function") {
    throw new Error(
      "registerTrainingExportAdapter: adapter.formatRecords must be a function.",
    );
  }
  if (
    typeof adapter.fileExtension !== "string" ||
    !/^\.[A-Za-z0-9][A-Za-z0-9._-]*$/.test(adapter.fileExtension.trim())
  ) {
    throw new Error(
      "registerTrainingExportAdapter: adapter.fileExtension must be a non-empty extension like '.jsonl'.",
    );
  }

  const key = adapter.name.trim();

  if (adapters.has(key)) {
    throw new Error(
      `registerTrainingExportAdapter: adapter "${key}" is already registered. ` +
        `Currently registered adapters: [${listTrainingExportAdapters().join(", ")}].`,
    );
  }

  adapters.set(key, adapter);
}

/**
 * Retrieve a registered adapter by name, or `undefined` if not found.
 */
export function getTrainingExportAdapter(name: string): TrainingExportAdapter | undefined {
  return adapters.get(name.trim());
}

/**
 * List the names of all registered adapters.
 */
export function listTrainingExportAdapters(): string[] {
  return [...adapters.keys()];
}

/**
 * Remove all registered adapters.  Intended for test teardown only.
 */
export function clearTrainingExportAdapters(): void {
  adapters.clear();
}

/**
 * `remnic patterns` CLI helpers (issue #687 PR 4/4).
 *
 * Pure functions that:
 *
 *   1. Validate `--limit`, `--category`, `--since`, `--format` for
 *      `remnic patterns list` and `--format` for
 *      `remnic patterns explain <id>` (CLAUDE.md rules 14 + 51 — flags
 *      throw listed-options errors instead of silently defaulting).
 *
 *   2. Filter the memory corpus to canonical memories produced by the
 *      pattern-reinforcement maintenance job from issue #687 PR 2/4
 *      (`reinforcement_count > 0`) and sort them by reinforcement
 *      count, with `last_reinforced_at` (then `id`) as stable
 *      tiebreakers (CLAUDE.md rule 19).
 *
 *   3. Reconstruct a single canonical's full picture: its
 *      `derived_from` provenance chain (PR 2/4 stamps these), the
 *      cluster members it absorbed (memories pointing at it via
 *      `supersededBy`), and the canonical body so operators can read
 *      it inline.
 *
 *   4. Render `text` (default) / `markdown` / `json` output for both
 *      commands.  The CLI handler in `cli.ts` stays thin and delegates
 *      formatting here so HTTP / MCP surfaces (if added later) can
 *      reuse the same renderers (CLAUDE.md rule 22 — never fork
 *      formatting).
 */

import type { MemoryCategory, MemoryFile } from "./types.js";
import { DERIVED_FROM_MEMORY_ID_RE } from "./consolidation-operator.js";
import { parseStrictCliDate } from "./training-export/date-parse.js";

export const PATTERNS_OUTPUT_FORMATS = ["text", "markdown", "json"] as const;
export type PatternsOutputFormat = (typeof PATTERNS_OUTPUT_FORMATS)[number];

// ───────────────────────────────────────────────────────────────────────────
// Flag validation
// ───────────────────────────────────────────────────────────────────────────

/**
 * Validate `--format <fmt>`.  Throws a listed-options error for any
 * value not in `PATTERNS_OUTPUT_FORMATS`.  Returns `"text"` when the
 * value is `undefined` (no flag supplied).
 */
export function parsePatternsFormat(value: unknown): PatternsOutputFormat {
  if (value === undefined || value === null) return "text";
  if (
    typeof value !== "string" ||
    !(PATTERNS_OUTPUT_FORMATS as readonly string[]).includes(value)
  ) {
    throw new Error(
      `--format expects one of ${PATTERNS_OUTPUT_FORMATS.join(", ")}; got ${JSON.stringify(value)}`,
    );
  }
  return value as PatternsOutputFormat;
}

/**
 * Validate `--limit <N>`.  Must be a positive integer.  Returns
 * `undefined` when the flag is absent (the caller falls back to a
 * default).
 */
export function parsePatternsLimit(value: unknown): number | undefined {
  if (value === undefined || value === null) return undefined;
  const parsed = typeof value === "number" ? value : Number(value);
  if (!Number.isFinite(parsed) || !Number.isInteger(parsed) || parsed <= 0) {
    throw new Error(
      `--limit expects a positive integer; got ${JSON.stringify(value)}`,
    );
  }
  return parsed;
}

/**
 * Validate `--category <list>`.  Accepts a comma-separated list of
 * non-empty trimmed tokens.  Returns the deduplicated list, or
 * `undefined` when no flag was supplied.  CLAUDE.md rules 14 + 51:
 * `--category` with no value or with a value that resolves to zero
 * tokens is rejected.
 */
export function parsePatternsCategory(value: unknown): string[] | undefined {
  if (value === undefined || value === null) return undefined;
  if (typeof value !== "string") {
    throw new Error(
      `--category expects a comma-separated list of category names; got ${JSON.stringify(value)}`,
    );
  }
  const parts = value
    .split(",")
    .map((part) => part.trim())
    .filter((part) => part.length > 0);
  if (parts.length === 0) {
    throw new Error(
      `--category expects at least one non-empty category name; got ${JSON.stringify(value)}`,
    );
  }
  // Deduplicate while preserving first-seen order.
  const seen = new Set<string>();
  const unique: string[] = [];
  for (const part of parts) {
    if (!seen.has(part)) {
      seen.add(part);
      unique.push(part);
    }
  }
  return unique;
}

/**
 * Validate `--since <ISO>`.  Delegates to `parseStrictCliDate` which
 * enforces a strict ISO 8601 shape and rejects calendar overflows and
 * non-ISO formats (e.g. "12/25/2026", "Dec 25 2026") that bare
 * `Date.parse()` would silently accept.  Returns the canonical ISO
 * string (round-trip through `toISOString`) so downstream comparisons
 * use a consistent form.
 */
export function parsePatternsSince(value: unknown): string | undefined {
  if (value === undefined || value === null) return undefined;
  if (typeof value !== "string" || value.trim().length === 0) {
    throw new Error(
      `--since expects an ISO 8601 timestamp (e.g. 2026-04-01T00:00:00Z); got ${JSON.stringify(value)}`,
    );
  }
  // parseStrictCliDate throws with a descriptive message on invalid input.
  return parseStrictCliDate(value.trim(), "--since").toISOString();
}

export interface ParsedPatternsListOptions {
  format: PatternsOutputFormat;
  limit?: number;
  categories?: string[];
  sinceIso?: string;
}

export interface ParsedPatternsExplainOptions {
  format: PatternsOutputFormat;
}

/**
 * Validate the full option bag for `remnic patterns list`.  Extracted
 * from the CLI handler so validation can be unit-tested without
 * booting an orchestrator (CLAUDE.md rules 14 + 51).
 */
export function parsePatternsListOptions(
  options: Record<string, unknown>,
): ParsedPatternsListOptions {
  const format = parsePatternsFormat(options.format);
  const limit = parsePatternsLimit(options.limit);
  const categories = parsePatternsCategory(options.category);
  const sinceIso = parsePatternsSince(options.since);
  return {
    format,
    ...(limit !== undefined ? { limit } : {}),
    ...(categories !== undefined ? { categories } : {}),
    ...(sinceIso !== undefined ? { sinceIso } : {}),
  };
}

/**
 * Validate `remnic patterns explain` options + positional id.  Throws
 * when `<memoryId>` is missing or empty.
 */
export function parsePatternsExplainOptions(
  rawId: unknown,
  options: Record<string, unknown>,
): { id: string } & ParsedPatternsExplainOptions {
  if (typeof rawId !== "string" || rawId.trim().length === 0) {
    throw new Error("patterns explain: <memoryId> is required and must be non-empty");
  }
  const format = parsePatternsFormat(options.format);
  return { id: rawId.trim(), format };
}

// ───────────────────────────────────────────────────────────────────────────
// Core list / explain behavior
// ───────────────────────────────────────────────────────────────────────────

export interface PatternListRow {
  id: string;
  category: MemoryCategory;
  reinforcementCount: number;
  lastReinforcedAt?: string;
  status: string;
  /** First non-empty content line, trimmed to ~120 chars for the table. */
  preview: string;
  /** Full path on disk (relative to memoryDir) for operators who want to inspect the file. */
  path: string;
}

const DEFAULT_LIST_LIMIT = 50;

/**
 * Filter, sort, and slice the memory corpus down to the rows the
 * `remnic patterns list` command should print.
 *
 * Rules (each one is exercised by `tests/cli/patterns.test.ts`):
 *
 *   - Memories without `reinforcement_count` (or with a count <= 0) are
 *     dropped — these are not pattern canonicals.
 *   - When `categories` is supplied, only memories whose
 *     `frontmatter.category` is in the list survive.
 *   - When `sinceIso` is supplied, only memories whose
 *     `last_reinforced_at` is `>= sinceIso` survive.  Memories without
 *     `last_reinforced_at` are dropped under `--since` (PR 2/4 always
 *     stamps the timestamp alongside the count, so a missing timestamp
 *     means a malformed file the operator should not see in this view).
 *   - Sort by `reinforcement_count DESC`, then `last_reinforced_at
 *     DESC`, then `id ASC` for a stable, deterministic order
 *     (CLAUDE.md rule 19).
 *   - Apply `limit` (default 50).
 */
export function collectPatternMemories(
  memories: readonly MemoryFile[],
  opts: ParsedPatternsListOptions,
): PatternListRow[] {
  const sinceMs =
    opts.sinceIso !== undefined ? Date.parse(opts.sinceIso) : undefined;
  const categorySet =
    opts.categories !== undefined ? new Set(opts.categories) : undefined;

  const rows: PatternListRow[] = [];
  for (const memory of memories) {
    const fm = memory.frontmatter;
    const count = fm.reinforcement_count;
    if (typeof count !== "number" || !Number.isInteger(count) || count <= 0) {
      continue;
    }
    if (categorySet !== undefined && !categorySet.has(fm.category)) {
      continue;
    }
    if (sinceMs !== undefined) {
      if (typeof fm.last_reinforced_at !== "string") continue;
      const ts = Date.parse(fm.last_reinforced_at);
      if (!Number.isFinite(ts) || ts < sinceMs) continue;
    }
    rows.push({
      id: fm.id,
      category: fm.category,
      reinforcementCount: count,
      ...(fm.last_reinforced_at !== undefined
        ? { lastReinforcedAt: fm.last_reinforced_at }
        : {}),
      status: fm.status ?? "active",
      preview: extractPreview(memory.content),
      path: memory.path,
    });
  }

  rows.sort((a, b) => {
    if (b.reinforcementCount !== a.reinforcementCount) {
      return b.reinforcementCount - a.reinforcementCount;
    }
    // Guard NaN: malformed date strings make Date.parse return NaN, which
    // breaks the sort contract (NaN comparator return == non-deterministic
    // ordering).  Treat invalid/missing timestamps as 0 (oldest possible).
    const aRaw = a.lastReinforcedAt ? Date.parse(a.lastReinforcedAt) : NaN;
    const bRaw = b.lastReinforcedAt ? Date.parse(b.lastReinforcedAt) : NaN;
    const aTs = Number.isFinite(aRaw) ? aRaw : 0;
    const bTs = Number.isFinite(bRaw) ? bRaw : 0;
    if (bTs !== aTs) return bTs - aTs;
    if (a.id < b.id) return -1;
    if (a.id > b.id) return 1;
    return 0;
  });

  const limit = opts.limit ?? DEFAULT_LIST_LIMIT;
  return rows.slice(0, limit);
}

export interface PatternDerivedFromEntry {
  /** Raw `"<path>:<version>"` reference exactly as stored in `derived_from`. */
  ref: string;
  /** Source memory id, or the path component for older `path:version` references. */
  path: string;
  /** Page-version number component for older `path:version` references. */
  version: number | null;
  /** True when an older path-version reference had an invalid version component. */
  malformed?: boolean;
}

export interface PatternClusterMember {
  id: string;
  status: string;
  supersededAt?: string;
  path: string;
  preview: string;
}

export interface PatternExplainDetail {
  id: string;
  category: MemoryCategory;
  reinforcementCount: number;
  lastReinforcedAt?: string;
  status: string;
  derivedVia?: string;
  /** Full canonical body (frontmatter stripped). */
  canonicalContent: string;
  canonicalPath: string;
  /** Parsed `derived_from` chain — empty when PR 2/4 did not stamp it. */
  derivedFrom: PatternDerivedFromEntry[];
  /** Memories whose `supersededBy === <id>`, sorted by `supersededAt DESC` then `id ASC`. */
  clusterMembers: PatternClusterMember[];
}

/**
 * Build the structured detail object for a single canonical.  Returns
 * `null` when the memory is not found or has never been touched by
 * pattern reinforcement (i.e., no `reinforcement_count`).  The CLI
 * handler then prints a clean "not a pattern" error rather than
 * leaking an empty document.
 */
export function explainPatternMemory(
  memories: readonly MemoryFile[],
  id: string,
): PatternExplainDetail | null {
  const canonical = memories.find((m) => m.frontmatter.id === id);
  if (!canonical) return null;
  const fm = canonical.frontmatter;
  const count = fm.reinforcement_count;
  if (typeof count !== "number" || !Number.isInteger(count) || count <= 0) {
    return null;
  }

  const derivedFrom: PatternDerivedFromEntry[] = (fm.derived_from ?? []).map(
    (ref) => {
      const lastColon = ref.lastIndexOf(":");
      const pathLikeRef = looksLikeDerivedFromPath(ref);
      if (lastColon >= 0) {
        const path = ref.slice(0, lastColon);
        const versionStr = ref.slice(lastColon + 1);
        if (
          looksLikeDerivedFromPath(path) &&
          /^\d+$/.test(versionStr)
        ) {
          return { ref, path, version: Number(versionStr) };
        }
        if (!pathLikeRef && DERIVED_FROM_MEMORY_ID_RE.test(ref)) {
          return { ref, path: ref, version: null };
        }
        return { ref, path: ref, version: null, malformed: true };
      }
      if (DERIVED_FROM_MEMORY_ID_RE.test(ref)) {
        return {
          ref,
          path: ref,
          version: null,
        };
      }
      return { ref, path: ref, version: null, malformed: true };
    },
  );

  const members: PatternClusterMember[] = [];
  for (const m of memories) {
    if (m.frontmatter.supersededBy === id) {
      members.push({
        id: m.frontmatter.id,
        status: m.frontmatter.status ?? "active",
        ...(m.frontmatter.supersededAt !== undefined
          ? { supersededAt: m.frontmatter.supersededAt }
          : {}),
        path: m.path,
        preview: extractPreview(m.content),
      });
    }
  }
  members.sort((a, b) => {
    // Guard NaN: same rationale as collectPatternMemories sort — malformed
    // supersededAt strings must not produce a NaN return from the comparator.
    const aRaw = a.supersededAt ? Date.parse(a.supersededAt) : NaN;
    const bRaw = b.supersededAt ? Date.parse(b.supersededAt) : NaN;
    const aTs = Number.isFinite(aRaw) ? aRaw : 0;
    const bTs = Number.isFinite(bRaw) ? bRaw : 0;
    if (bTs !== aTs) return bTs - aTs;
    if (a.id < b.id) return -1;
    if (a.id > b.id) return 1;
    return 0;
  });

  return {
    id: fm.id,
    category: fm.category,
    reinforcementCount: count,
    ...(fm.last_reinforced_at !== undefined
      ? { lastReinforcedAt: fm.last_reinforced_at }
      : {}),
    status: fm.status ?? "active",
    ...(fm.derived_via !== undefined ? { derivedVia: fm.derived_via } : {}),
    canonicalContent: canonical.content.trim(),
    canonicalPath: canonical.path,
    derivedFrom,
    clusterMembers: members,
  };
}

// ───────────────────────────────────────────────────────────────────────────
// Renderers
// ───────────────────────────────────────────────────────────────────────────

export function renderPatternsList(
  rows: readonly PatternListRow[],
  format: PatternsOutputFormat,
): string {
  if (format === "json") {
    return JSON.stringify({ rows }, null, 2);
  }
  if (rows.length === 0) {
    if (format === "markdown") {
      return "# Pattern memories\n\n_No reinforced patterns found._\n";
    }
    return "No reinforced patterns found.";
  }
  if (format === "markdown") {
    const lines: string[] = ["# Pattern memories", ""];
    lines.push("| Count | ID | Category | Last reinforced | Preview |");
    lines.push("| --- | --- | --- | --- | --- |");
    for (const row of rows) {
      const last = row.lastReinforcedAt ?? "—";
      const preview = escapePipes(row.preview);
      lines.push(
        `| ${row.reinforcementCount} | \`${row.id}\` | ${row.category} | ${last} | ${preview} |`,
      );
    }
    return lines.join("\n") + "\n";
  }
  // text
  const lines: string[] = [];
  lines.push(`Pattern memories (${rows.length}):`);
  lines.push("");
  for (const row of rows) {
    const last = row.lastReinforcedAt ?? "—";
    lines.push(
      `  [${row.reinforcementCount}x] ${row.id}  (${row.category}, last_reinforced=${last}, status=${row.status})`,
    );
    if (row.preview.length > 0) {
      lines.push(`        ${row.preview}`);
    }
    lines.push(`        path: ${row.path}`);
  }
  return lines.join("\n");
}

export function renderPatternExplain(
  detail: PatternExplainDetail,
  format: PatternsOutputFormat,
): string {
  if (format === "json") {
    return JSON.stringify(detail, null, 2);
  }
  const last = detail.lastReinforcedAt ?? "—";
  const derivedVia = detail.derivedVia ?? "—";
  if (format === "markdown") {
    const lines: string[] = [];
    lines.push(`# Pattern: \`${detail.id}\``);
    lines.push("");
    lines.push(`- **Reinforcement count:** ${detail.reinforcementCount}`);
    lines.push(`- **Last reinforced:** ${last}`);
    lines.push(`- **Category:** ${detail.category}`);
    lines.push(`- **Status:** ${detail.status}`);
    lines.push(`- **Derived via:** ${derivedVia}`);
    lines.push(`- **Path:** \`${detail.canonicalPath}\``);
    lines.push("");
    lines.push("## Canonical content");
    lines.push("");
    lines.push("```");
    lines.push(detail.canonicalContent);
    lines.push("```");
    lines.push("");
    lines.push(`## Derived from (${detail.derivedFrom.length})`);
    lines.push("");
    if (detail.derivedFrom.length === 0) {
      lines.push("_No derived_from entries recorded._");
    } else {
      for (const entry of detail.derivedFrom) {
        const versionStr =
          entry.version !== null
            ? ` v${entry.version}`
            : entry.malformed
              ? " (malformed)"
              : "";
        lines.push(`- \`${entry.path}\`${versionStr}`);
      }
    }
    lines.push("");
    lines.push(`## Cluster members (${detail.clusterMembers.length})`);
    lines.push("");
    if (detail.clusterMembers.length === 0) {
      lines.push("_No superseded members reference this canonical._");
    } else {
      for (const member of detail.clusterMembers) {
        const ts = member.supersededAt ?? "—";
        lines.push(`- \`${member.id}\` (status=${member.status}, supersededAt=${ts})`);
        if (member.preview.length > 0) {
          lines.push(`  - ${escapePipes(member.preview)}`);
        }
      }
    }
    return lines.join("\n") + "\n";
  }
  // text
  const lines: string[] = [];
  lines.push(`Pattern: ${detail.id}`);
  lines.push(`  reinforcement_count: ${detail.reinforcementCount}`);
  lines.push(`  last_reinforced_at: ${last}`);
  lines.push(`  category:           ${detail.category}`);
  lines.push(`  status:             ${detail.status}`);
  lines.push(`  derived_via:        ${derivedVia}`);
  lines.push(`  path:               ${detail.canonicalPath}`);
  lines.push("");
  lines.push("Canonical content:");
  for (const line of detail.canonicalContent.split("\n")) {
    lines.push(`  ${line}`);
  }
  lines.push("");
  lines.push(`Derived from (${detail.derivedFrom.length}):`);
  if (detail.derivedFrom.length === 0) {
    lines.push("  (none)");
  } else {
    for (const entry of detail.derivedFrom) {
      const versionStr =
        entry.version !== null
          ? ` v${entry.version}`
          : entry.malformed
            ? " (malformed)"
            : "";
      lines.push(`  - ${entry.path}${versionStr}`);
    }
  }
  lines.push("");
  lines.push(`Cluster members (${detail.clusterMembers.length}):`);
  if (detail.clusterMembers.length === 0) {
    lines.push("  (none)");
  } else {
    for (const member of detail.clusterMembers) {
      const ts = member.supersededAt ?? "—";
      lines.push(`  - ${member.id} (status=${member.status}, supersededAt=${ts})`);
      if (member.preview.length > 0) {
        lines.push(`      ${member.preview}`);
      }
    }
  }
  return lines.join("\n");
}

// ───────────────────────────────────────────────────────────────────────────
// Internal helpers
// ───────────────────────────────────────────────────────────────────────────

function extractPreview(content: string): string {
  const trimmed = content.trim();
  if (trimmed.length === 0) return "";
  const firstLine = trimmed.split("\n").find((line) => line.trim().length > 0) ?? "";
  const collapsed = firstLine.trim().replace(/\s+/g, " ");
  if (collapsed.length <= 120) return collapsed;
  return collapsed.slice(0, 117) + "...";
}

function looksLikeDerivedFromPath(value: string): boolean {
  return value.includes("/") || value.includes(".");
}

/**
 * Escape characters that would break a Markdown table cell:
 *   - backslashes first (so the `\|` escape below isn't double-escaped)
 *   - then pipe characters
 *
 * CodeQL "Incomplete string escaping or encoding": backslash must be
 * escaped before pipe so that a literal `\` in content isn't
 * misinterpreted as part of a `\|` escape sequence.
 */
function escapePipes(value: string): string {
  return value.replace(/\\/g, "\\\\").replace(/\|/g, "\\|");
}

import type { LocalSessionParsedFile, LocalSessionRole, LocalSessionSourceAdapter, LocalSessionTurn } from "./types.js";

const VALID_ROLES = new Set<LocalSessionRole>(["user", "assistant", "tool", "system", "other"]);

function normalizeRole(value: unknown): LocalSessionRole {
  if (typeof value !== "string") return "other";
  const role = value.trim().toLowerCase();
  if (VALID_ROLES.has(role as LocalSessionRole)) {
    return role as LocalSessionRole;
  }
  if (role === "human") return "user";
  if (role === "ai" || role === "model" || role === "bot") return "assistant";
  if (role === "function") return "tool";
  return "other";
}

function normalizeTimestamp(value: unknown): string | undefined {
  if (typeof value === "number" && Number.isFinite(value)) {
    const millis = value > 1e12 ? value : value * 1000;
    const date = new Date(millis);
    return Number.isFinite(date.getTime()) ? date.toISOString() : undefined;
  }
  if (typeof value !== "string" || value.trim().length === 0) return undefined;
  const date = new Date(value);
  return Number.isFinite(date.getTime()) ? date.toISOString() : undefined;
}

function normalizeContent(value: unknown): string | undefined {
  if (typeof value === "string") {
    const trimmed = value.trim();
    return trimmed.length > 0 ? trimmed : undefined;
  }
  if (Array.isArray(value)) {
    const parts = value
      .map((part) => normalizeContent(part))
      .filter((part): part is string => typeof part === "string")
      .join("\n")
      .trim();
    return parts.length > 0 ? parts : undefined;
  }
  if (!value || typeof value !== "object") return undefined;
  const obj = value as Record<string, unknown>;
  if (firstString(obj.type) === "tool_result") return undefined;
  return normalizeContent(obj.text ?? obj.content ?? obj.message ?? obj.parts ?? obj.value ?? obj.input);
}

function firstString(...values: unknown[]): string | undefined {
  for (const value of values) {
    if (typeof value === "string" && value.trim().length > 0) {
      return value.trim();
    }
    if (typeof value === "number" && Number.isFinite(value)) {
      return String(value);
    }
  }
  return undefined;
}

function firstContent(...values: unknown[]): string | undefined {
  for (const value of values) {
    const content = normalizeContent(value);
    if (content) return content;
  }
  return undefined;
}

function objectField(value: unknown): Record<string, unknown> | undefined {
  return value && typeof value === "object" ? (value as Record<string, unknown>) : undefined;
}

const SESSION_KEY_FIELDS = [
  "sessionKey",
  "session_key",
  "sessionId",
  "session_id",
  "conversationId",
  "conversation_id",
  "threadId",
  "thread_id",
  "transcriptId",
  "transcript_id",
] as const;

function hasUsableSessionKeyField(value: unknown): boolean {
  return (
    (typeof value === "string" && value.trim().length > 0) ||
    (typeof value === "number" && Number.isFinite(value))
  );
}

function inheritEnvelopeSessionFields(row: unknown, envelope: Record<string, unknown>): unknown {
  if (!row || typeof row !== "object" || Array.isArray(row)) return row;
  const child = row as Record<string, unknown>;
  const inherited: Record<string, unknown> = {};
  for (const key of SESSION_KEY_FIELDS) {
    if (!hasUsableSessionKeyField(child[key]) && hasUsableSessionKeyField(envelope[key])) {
      inherited[key] = envelope[key];
    }
  }
  return Object.keys(inherited).length > 0 ? { ...child, ...inherited } : row;
}

function codexRoleFromTypes(
  rowType: string | undefined,
  payloadType: string | undefined
): LocalSessionRole | undefined {
  if (payloadType === "agent_message") return "assistant";
  if (payloadType === "user_message") return "user";
  if (rowType === "event_msg") return "user";
  if (rowType === "response_item") return "assistant";
  return undefined;
}

function sessionKeyFromRow(row: unknown): string | undefined {
  if (!row || typeof row !== "object") return undefined;
  const obj = row as Record<string, unknown>;
  const nestedMessage = objectField(obj.message);
  const payload = objectField(obj.payload);
  const payloadMessage = objectField(payload?.message);
  const rowType = firstString(obj.type, obj.kind, obj.event)?.toLowerCase();
  return firstString(
    obj.sessionKey,
    obj.session_key,
    obj.sessionId,
    obj.session_id,
    obj.conversationId,
    obj.conversation_id,
    obj.threadId,
    obj.thread_id,
    obj.transcriptId,
    obj.transcript_id,
    nestedMessage?.sessionKey,
    nestedMessage?.session_key,
    nestedMessage?.sessionId,
    nestedMessage?.session_id,
    nestedMessage?.conversationId,
    nestedMessage?.conversation_id,
    nestedMessage?.threadId,
    nestedMessage?.thread_id,
    nestedMessage?.transcriptId,
    nestedMessage?.transcript_id,
    rowType === "session_meta" ? payload?.id : undefined,
    payload?.sessionKey,
    payload?.session_key,
    payload?.sessionId,
    payload?.session_id,
    payload?.conversationId,
    payload?.conversation_id,
    payload?.threadId,
    payload?.thread_id,
    payload?.transcriptId,
    payload?.transcript_id,
    payloadMessage?.sessionKey,
    payloadMessage?.session_key,
    payloadMessage?.sessionId,
    payloadMessage?.session_id,
    payloadMessage?.conversationId,
    payloadMessage?.conversation_id,
    payloadMessage?.threadId,
    payloadMessage?.thread_id,
    payloadMessage?.transcriptId,
    payloadMessage?.transcript_id
  );
}

function extractRowsFromJson(value: unknown): unknown[] {
  if (Array.isArray(value)) return value;
  if (!value || typeof value !== "object") return [];
  const obj = value as Record<string, unknown>;
  for (const key of ["turns", "messages", "events", "entries", "items"]) {
    const rows = obj[key];
    if (Array.isArray(rows) && rows.length > 0) {
      return rows.map((row) => inheritEnvelopeSessionFields(row, obj));
    }
  }
  return [obj];
}

function parseJsonlRows(
  content: string,
  adapterId: string,
  strict: boolean | undefined,
  fileRef: string
): { rows: unknown[]; warnings: LocalSessionParsedFile["warnings"] } {
  const rows: unknown[] = [];
  const warnings: LocalSessionParsedFile["warnings"] = [];
  for (const [index, line] of content.split("\n").entries()) {
    const trimmed = line.trim();
    if (trimmed.length === 0) continue;
    try {
      rows.push(JSON.parse(trimmed));
    } catch {
      const warning = {
        code: `${adapterId}.jsonl.invalid_line`,
        message: `Skipping invalid JSONL line ${index + 1} in fileRef ${fileRef}.`,
        fileRef,
        line: index + 1,
      };
      if (strict) throw new Error(warning.message);
      warnings.push(warning);
    }
  }
  return { rows, warnings };
}

function parseRows(
  content: string,
  extension: string,
  adapterId: string,
  strict: boolean | undefined,
  fileRef: string
): { rows: unknown[]; warnings: LocalSessionParsedFile["warnings"] } {
  if (extension === ".jsonl") {
    return parseJsonlRows(content, adapterId, strict, fileRef);
  }
  try {
    return { rows: extractRowsFromJson(JSON.parse(content)), warnings: [] };
  } catch {
    const message = `Invalid ${adapterId} JSON in fileRef ${fileRef}; skipping file.`;
    if (strict) throw new Error(message);
    return {
      rows: [],
      warnings: [{ code: `${adapterId}.json.invalid`, message, fileRef }],
    };
  }
}

function turnFromRow(row: unknown, fallbackSessionKey: string): LocalSessionTurn | null {
  if (!row || typeof row !== "object") return null;
  const obj = row as Record<string, unknown>;
  const nestedMessage = objectField(obj.message);
  const payload = objectField(obj.payload);
  const payloadItem = objectField(payload?.item);
  const payloadMessage = objectField(payload?.message);
  const author = objectField(obj.author);
  const rowType = firstString(obj.type, obj.kind, obj.event);
  const payloadType = firstString(payload?.type, payloadItem?.type);
  const codexRole = codexRoleFromTypes(rowType, payloadType);

  const content = firstContent(
    obj.content,
    obj.text,
    obj.message,
    obj.body,
    obj.parts,
    obj.input,
    payload?.message,
    payload?.content,
    payload?.text,
    payload?.body,
    payload?.parts,
    payload?.input,
    payloadMessage?.content,
    payloadMessage?.text,
    payloadMessage?.parts,
    payloadMessage?.input,
    payloadItem?.content,
    payloadItem?.text,
    payloadItem?.message,
    payloadItem?.parts,
    payloadItem?.input,
    nestedMessage?.content,
    nestedMessage?.text,
    nestedMessage?.parts,
    nestedMessage?.input
  );
  if (!content) return null;

  const role = normalizeRole(
    obj.role ??
      obj.sender ??
      obj.actor ??
      payload?.role ??
      payload?.sender ??
      payloadMessage?.role ??
      payloadMessage?.sender ??
      payloadItem?.role ??
      nestedMessage?.role ??
      nestedMessage?.sender ??
      author?.role ??
      codexRole ??
      obj.type
  );

  return {
    role,
    content,
    timestamp: normalizeTimestamp(
      obj.timestamp ??
        obj.createdAt ??
        obj.created_at ??
        obj.time ??
        obj.date ??
        payload?.timestamp ??
        payload?.createdAt ??
        payload?.created_at ??
        payloadMessage?.timestamp ??
        payloadMessage?.createdAt ??
        payloadMessage?.created_at ??
        payloadItem?.timestamp ??
        payloadItem?.created_at ??
        nestedMessage?.timestamp ??
        nestedMessage?.created_at
    ),
    sessionKey: sessionKeyFromRow(row) ?? fallbackSessionKey,
    sourceId: firstString(obj.id, obj.uuid, obj.turnId, obj.turn_id, payload?.id, payloadItem?.id),
  };
}

function shouldSkipRowForAdapter(adapterId: string, row: unknown): boolean {
  if (adapterId !== "codex-jsonl" || !row || typeof row !== "object") return false;
  const obj = row as Record<string, unknown>;
  const payload = objectField(obj.payload);
  const rowType = firstString(obj.type, obj.kind, obj.event)?.toLowerCase();
  const payloadType = firstString(payload?.type)?.toLowerCase();
  return rowType === "compacted" || payloadType === "compacted";
}

type CodexMirrorSurface = "event-agent-message" | "response-item";

const CODEX_MIRROR_SURFACE_PRIORITY: Record<CodexMirrorSurface, number> = {
  "event-agent-message": 1,
  "response-item": 2,
};

function codexMirrorSurface(row: unknown): CodexMirrorSurface | undefined {
  if (!row || typeof row !== "object") return undefined;
  const obj = row as Record<string, unknown>;
  const payload = objectField(obj.payload);
  const payloadItem = objectField(payload?.item);
  const rowType = firstString(obj.type, obj.kind, obj.event)?.toLowerCase();
  const payloadType = firstString(payload?.type, payloadItem?.type)?.toLowerCase();
  if (rowType === "event_msg" && payloadType === "agent_message") return "event-agent-message";
  if (rowType === "response_item") return "response-item";
  return undefined;
}

function codexMirrorKey(adapterId: string, row: unknown, turn: LocalSessionTurn): string | undefined {
  if (adapterId !== "codex-jsonl" || turn.role !== "assistant") return undefined;
  const surface = codexMirrorSurface(row);
  if (!surface) return undefined;
  const sessionKey = turn.sessionKey?.trim();
  const content = turn.content.replace(/\s+/g, " ").trim();
  if (!sessionKey || content.length === 0) return undefined;
  return `${sessionKey}\0${turn.role}\0${content}`;
}

function pushTurnWithCodexMirrorDedupe(
  adapterId: string,
  row: unknown,
  turn: LocalSessionTurn,
  turns: LocalSessionTurn[],
  codexMirrorTurns: Map<string, { index: number; surface: CodexMirrorSurface; rowSignal?: string }[]>
): void {
  const key = codexMirrorKey(adapterId, row, turn);
  const surface = key ? codexMirrorSurface(row) : undefined;
  if (!key || !surface) {
    turns.push(turn);
    return;
  }

  const candidates = codexMirrorTurns.get(key) ?? [];
  const rowSignal = turn.sourceId ?? turn.timestamp;
  const matchingIndex = candidates.findIndex((candidate) => {
    if (candidate.surface === surface) {
      return Boolean(candidate.rowSignal && rowSignal && candidate.rowSignal === rowSignal);
    }
    return Boolean(candidate.rowSignal && rowSignal && candidate.rowSignal === rowSignal);
  });
  const existing = matchingIndex >= 0 ? candidates[matchingIndex] : undefined;
  if (existing) {
    if (CODEX_MIRROR_SURFACE_PRIORITY[surface] > CODEX_MIRROR_SURFACE_PRIORITY[existing.surface]) {
      turns[existing.index] = turn;
      candidates[matchingIndex] = { index: existing.index, surface, ...(rowSignal ? { rowSignal } : {}) };
      codexMirrorTurns.set(key, candidates);
    }
    return;
  }

  candidates.push({ index: turns.length, surface, ...(rowSignal ? { rowSignal } : {}) });
  codexMirrorTurns.set(key, candidates);
  turns.push(turn);
}

function makeJsonTranscriptAdapter(id: string): LocalSessionSourceAdapter {
  return {
    id,
    parseFile(input, options = {}) {
      const parsed = parseRows(input.content, input.fileExtension, id, options.strict, input.fileRef);
      const fallbackSessionKey = `${id}:${input.fileRef}`;
      let currentSessionKey = fallbackSessionKey;
      const turns: LocalSessionTurn[] = [];
      const codexMirrorTurns = new Map<string, { index: number; surface: CodexMirrorSurface; rowSignal?: string }[]>();
      for (const row of parsed.rows) {
        if (shouldSkipRowForAdapter(id, row)) continue;
        currentSessionKey = sessionKeyFromRow(row) ?? currentSessionKey;
        const turn = turnFromRow(row, currentSessionKey);
        if (turn) {
          currentSessionKey = turn.sessionKey ?? currentSessionKey;
          pushTurnWithCodexMirrorDedupe(id, row, turn, turns, codexMirrorTurns);
        }
      }
      return { turns, warnings: parsed.warnings };
    },
  };
}

const BUILT_IN_ADAPTERS = new Map<string, LocalSessionSourceAdapter>();

export function registerLocalSessionSourceAdapter(adapter: LocalSessionSourceAdapter): void {
  if (!adapter || typeof adapter !== "object") {
    throw new Error("local session source adapter must be an object");
  }
  if (typeof adapter.id !== "string" || adapter.id.trim().length === 0) {
    throw new Error("local session source adapter id must be a non-empty string");
  }
  if (typeof adapter.parseFile !== "function") {
    throw new Error(`local session adapter '${adapter.id}' must define parseFile`);
  }
  const id = adapter.id.trim();
  if (BUILT_IN_ADAPTERS.has(id)) {
    throw new Error(`local session adapter '${id}' is already registered`);
  }
  BUILT_IN_ADAPTERS.set(id, adapter.id === id ? adapter : { ...adapter, id });
}

export function getLocalSessionSourceAdapter(id: string | undefined): LocalSessionSourceAdapter | undefined {
  const key = typeof id === "string" && id.trim().length > 0 ? id.trim() : "generic-jsonl";
  return BUILT_IN_ADAPTERS.get(key);
}

export function listLocalSessionSourceAdapters(): string[] {
  return [...BUILT_IN_ADAPTERS.keys()].sort();
}

for (const adapterId of ["generic-jsonl", "codex-jsonl", "claude-jsonl"]) {
  registerLocalSessionSourceAdapter(makeJsonTranscriptAdapter(adapterId));
}

