    pattern: /\b[A-Za-z]:\\(?:[^\\/:*?"<>|,;\r\n]+\\)*[^\\/:*?"<>|,;\s\r\n]+/g,
    replacement: "[REDACTED_PATH]",
  },
  {
    name: "unc-windows-spaced-path",
    pattern:
      /\\\\[^\\/:*?"<>|,;\s\r\n]+\\[^\\/:*?"<>|,;\r\n]+\\(?:[^\\/:*?"<>|,;\r\n]+\\)*[^\\/:*?"<>|,;\s\r\n]+(?: [^\\/:*?"<>|,;\s\r\n]+)+\.[A-Za-z0-9_-]+/g,
    replacement: "[REDACTED_PATH]",
  },
  {
    name: "unc-windows-spaced-extensionless-path",
    pattern:
      /\\\\[^\\/:*?"<>|,;\s\r\n]+\\[^\\/:*?"<>|,;\r\n]+\\(?:[^\\/:*?"<>|,;\r\n]+\\)*[^\\/:*?"<>|,;\s\r\n]+(?: [^\\/:*?"<>|,;\s\r\n]+)+(?=$|["'<>)](?!\\)|[,;.]|\s+(?:before|after|then|and|or)\b)/gi,
    replacement: "[REDACTED_PATH]",
  },
  {
    name: "unc-windows-share-root",
    pattern: /\\\\[^\\/:*?"<>|,;\s\r\n]+\\[^\\/:*?"<>|,;\s\r\n]+(?=$|[\s"',;<>)]|[.,](?:\s|$))/g,
    replacement: "[REDACTED_PATH]",
  },
  {
    name: "unc-windows-path",
    pattern: /\\\\[^\\/:*?"<>|,;\s\r\n]+\\[^\\/:*?"<>|,;\r\n]+\\(?:[^\\/:*?"<>|,;\r\n]+\\)*[^\\/:*?"<>|,;\s\r\n]+/g,
    replacement: "[REDACTED_PATH]",
  },
];

function cloneRedactionRule(rule: CompiledRedactionRule): CompiledRedactionRule {
  return {
    name: rule.name,
    pattern: new RegExp(rule.pattern.source, rule.pattern.flags),
    replacement: rule.replacement,
  };
}

export function compileRedactionRules(config: RedactionConfig = {}): CompiledRedactionRule[] {
  const rules: CompiledRedactionRule[] =
    config.disableDefaults === true ? [] : DEFAULT_REDACTION_RULES.map(cloneRedactionRule);
  const customRules = config.rules ?? [];
  if (!Array.isArray(customRules)) {
    throw new Error("redaction rules must be an array");
  }
  for (const rule of customRules) {
    if (!rule || typeof rule !== "object") {
      throw new Error("redaction rule must be an object");
    }
    if (typeof rule.name !== "string" || rule.name.trim().length === 0) {
      throw new Error("redaction rule name must be a non-empty string");
    }
    if (typeof rule.pattern !== "string" || rule.pattern.length === 0) {
      throw new Error(`redaction rule '${rule.name}' pattern must be non-empty`);
    }
    const flags = rule.flags ?? "g";
    rules.push({
      name: rule.name.trim(),
      pattern: new RegExp(rule.pattern, flags.includes("g") ? flags : `${flags}g`),
      replacement: rule.replacement ?? `[REDACTED_${rule.name.trim().toUpperCase()}]`,
    });
  }
  return rules;
}

export function redactSessionSummaryText(
  text: string,
  rules: readonly CompiledRedactionRule[]
): { text: string; report: RedactionReport } {
  let redacted = text;
  let applied = 0;
  const ruleNames = new Set<string>();

  for (const rule of rules) {
    rule.pattern.lastIndex = 0;
    const matches = redacted.match(rule.pattern);
    if (!matches || matches.length === 0) continue;
    applied += matches.length;
    ruleNames.add(rule.name);
    redacted = redacted.replace(rule.pattern, rule.replacement);
  }

  return {
    text: redacted,
    report: {
      applied,
      ruleNames: [...ruleNames].sort(),
    },
  };
}

// ---------------------------------------------------------------------------
// Bulk-import pipeline types and validation
// ---------------------------------------------------------------------------

import { parseIsoOffsetTimestamp } from "../utils/iso-timestamp.js";
import type { SourceConnectorProvenance } from "../types.js";

export interface BulkImportSource {
  turns: ImportTurn[];
  metadata: {
    source: string;
    exportDate: string;
    messageCount: number;
    dateRange: { from: string; to: string };
  };
}

export interface ImportTurn extends SourceConnectorProvenance {
  role: "user" | "assistant" | "other";
  content: string;
  timestamp: string;
  participantId?: string;
  participantName?: string;
  replyToId?: string;
  turnFingerprint?: string;
  persistProcessedFingerprint?: boolean;
  parts?: import("../message-parts/index.js").LcmMessagePartInput[];
  rawContent?: unknown;
  sourceFormat?: import("../message-parts/index.js").MessagePartSourceFormat;
  importProvenance?: ImportTurnProvenance;
}

export interface ImportTurnProvenance {
  sourceLabel?: string;
  sourceId?: string;
  sourceTimestamp?: string;
  importedFromPath?: string;
  importedAt?: string;
  metadata?: Record<string, unknown>;
}

export interface BulkImportOptions {
  batchSize?: number;
  dryRun?: boolean;
  dedup?: boolean;
  trustLevel?: "import";
  namespace?: string;
}

export type ImportSourceRole = ImportTurn["role"];

export interface BulkImportResult {
  memoriesCreated: number;
  duplicatesSkipped: number;
  entitiesCreated: number;
  turnsProcessed: number;
  batchesProcessed: number;
  errors: BulkImportError[];
}

export interface BulkImportError {
  batchIndex: number;
  message: string;
}

export interface BulkImportSourceAdapter {
  name: string;
  parse(
    input: unknown,
    options?: { strict?: boolean; platform?: string },
  ): Promise<BulkImportSource> | BulkImportSource;
}

// ---------------------------------------------------------------------------
// Validation helpers
// ---------------------------------------------------------------------------

const VALID_ROLES: ReadonlySet<string> = new Set(["user", "assistant", "other"]);

export interface ImportTurnValidationIssue {
  code: string;
  message: string;
  index?: number;
}

export function isImportRole(value: unknown): value is ImportSourceRole {
  return typeof value === "string" && VALID_ROLES.has(value);
}

/**
 * Parse an ISO-8601 / RFC 3339 timestamp used by bulk-import adapters.
 *
 * Accepts variable-precision fractional seconds and either a `Z` suffix or a
 * `[+-]HH:MM` timezone offset, so adapters may preserve their source
 * timestamps verbatim. Returns milliseconds since epoch, or `null` if the
 * string is not a well-formed timestamp (including overflowed calendar dates
 * or out-of-range offsets).
 *
 * Delegates to the shared parser in `utils/iso-timestamp.ts` — do not
 * reimplement locally; extend that helper instead.
 */
export function parseIsoTimestamp(value: string): number | null {
  return parseIsoOffsetTimestamp(value);
}

export function validateImportTurn(
  turn: ImportTurn,
  index?: number,
): ImportTurnValidationIssue[] {
  const issues: ImportTurnValidationIssue[] = [];

  if (!turn || typeof turn !== "object") {
    issues.push({
      code: "turn.invalid",
      message: "Import turn must be an object.",
      index,
    });
    return issues;
  }

  if (!isImportRole(turn.role)) {
    issues.push({
      code: "turn.role.invalid",
      message:
        `Import turn role must be 'user', 'assistant', or 'other', ` +
        `received '${String(turn.role)}'.`,
      index,
    });
  }

  if (
    !turn.content ||
    typeof turn.content !== "string" ||
    turn.content.trim().length === 0
  ) {
    issues.push({
      code: "turn.content.invalid",
      message: "Import turn content must be a non-empty string.",
      index,
    });
  }

  if (
    !turn.timestamp ||
    typeof turn.timestamp !== "string" ||
    parseIsoTimestamp(turn.timestamp) === null
  ) {
    issues.push({
      code: "turn.timestamp.invalid",
      message:
        `Import turn timestamp must be a valid ISO timestamp, ` +
        `received '${String(turn.timestamp)}'.`,
      index,
    });
  }

  return issues;
}

// ---------------------------------------------------------------------------
// Bulk-import source adapter registry
// ---------------------------------------------------------------------------

import type { BulkImportSourceAdapter } from "./types.js";

const adapters = new Map<string, BulkImportSourceAdapter>();

/**
 * Register a source adapter. Rejects duplicate names and empty names.
 */
export function registerBulkImportSource(
  adapter: BulkImportSourceAdapter,
): void {
  if (!adapter || typeof adapter !== "object") {
    throw new Error("bulk-import adapter must be an object");
  }
  if (
    !adapter.name ||
    typeof adapter.name !== "string" ||
    adapter.name.trim().length === 0
  ) {
    throw new Error("bulk-import adapter name must be a non-empty string");
  }
  if (typeof adapter.parse !== "function") {
    throw new Error(
      `bulk-import adapter '${adapter.name}' must have a parse function`,
    );
  }
  const key = adapter.name.trim();
  if (adapters.has(key)) {
    throw new Error(
      `bulk-import source adapter '${key}' is already registered`,
    );
  }
  // Store adapter with trimmed name so `adapter.name` stays consistent with
  // the registry key returned by `listBulkImportSources()`.
  const normalized: BulkImportSourceAdapter =
    adapter.name === key ? adapter : { ...adapter, name: key };
  adapters.set(key, normalized);
}

/**
 * Retrieve a registered adapter by name.
 *
 * Names are trimmed on write (see `registerBulkImportSource`), so we
 * also trim on read to avoid the asymmetric-lookup footgun where a
 * whitespace-padded lookup would never find a registered adapter.
 * Non-string or empty-after-trim inputs return undefined.
 */
export function getBulkImportSource(
  name: string,
): BulkImportSourceAdapter | undefined {
  if (typeof name !== "string") return undefined;
  const key = name.trim();
  if (key.length === 0) return undefined;
  return adapters.get(key);
}

/**
 * List all registered adapter names.
 */
export function listBulkImportSources(): string[] {
  return [...adapters.keys()];
}

/**
 * Clear all registered adapters (for testing).
 */
export function clearBulkImportSources(): void {
  adapters.clear();
}

// ---------------------------------------------------------------------------
// Bulk-import batch processing pipeline
// ---------------------------------------------------------------------------

import {
  validateImportTurn,
  type BulkImportError,
  type BulkImportOptions,
  type BulkImportResult,
  type BulkImportSource,
  type ImportTurn,
} from "./types.js";

const DEFAULT_BATCH_SIZE = 20;
const MIN_BATCH_SIZE = 1;
const MAX_BATCH_SIZE = 1000;

export interface ProcessBatchResult {
  memoriesCreated: number;
  duplicatesSkipped: number;
  /**
   * Number of entities created by the batch. Optional so Phase-1 stubs that
   * only count memories can omit it; when absent it is treated as 0.
   */
  entitiesCreated?: number;
}

export interface ProcessBatchContext {
  dedup: boolean;
  trustLevel: "import";
  namespace?: string;
}

export type ProcessBatchFn = (
  turns: ImportTurn[],
  context: ProcessBatchContext,
) => Promise<ProcessBatchResult>;

export function validateBatchSize(value: number | undefined): number {
  if (value === undefined) return DEFAULT_BATCH_SIZE;
  if (typeof value !== "number" || !Number.isFinite(value)) {
    throw new Error(
      `batchSize must be a finite number, received ${String(value)}`,
    );
  }
  if (!Number.isInteger(value)) {
    throw new Error(
      `batchSize must be an integer, received ${value}`,
    );
  }
  if (value < MIN_BATCH_SIZE || value > MAX_BATCH_SIZE) {
    throw new Error(
      `batchSize must be between ${MIN_BATCH_SIZE} and ${MAX_BATCH_SIZE}, received ${value}`,
    );
  }
  return value;
}

export function resolveBulkImportContext(
  options: BulkImportOptions,
): ProcessBatchContext {
  if (options.dedup !== undefined && typeof options.dedup !== "boolean") {
    throw new Error(
      `dedup must be a boolean when provided, received ${String(options.dedup)}`,
    );
  }
  if (options.trustLevel !== undefined && options.trustLevel !== "import") {
    throw new Error(
      `trustLevel must be 'import' when provided, received ${String(options.trustLevel)}`,
    );
  }
  if (options.namespace !== undefined) {
    if (typeof options.namespace !== "string" || options.namespace.trim().length === 0) {
      throw new Error(
        `namespace must be a non-empty string when provided, received ${String(options.namespace)}`,
      );
    }
  }

  return {
    dedup: options.dedup !== false,
    trustLevel: options.trustLevel ?? "import",
    ...(options.namespace !== undefined
      ? { namespace: options.namespace }
      : {}),
  };
}

/**
 * Format a batch of turns into a conversation transcript string.
 */
export function formatBatchTranscript(turns: ImportTurn[]): string {
  return turns
    .map((t) => {
      const prefix =
        t.participantName ?? t.participantId ?? t.role;
      return `[${t.timestamp}] ${prefix}: ${t.content}`;
    })
    .join("\n");
}

/**
 * Run the bulk-import pipeline over a parsed source.
 *
 * Splits turns into batches and delegates each to `processBatch`.
 * In dryRun mode, validates and counts without calling `processBatch`.
 */
export async function runBulkImportPipeline(
  source: BulkImportSource,
  options: BulkImportOptions = {},
  processBatch: ProcessBatchFn,
): Promise<BulkImportResult> {
  const batchSize = validateBatchSize(options.batchSize);
  const dryRun = options.dryRun === true;
  const batchContext = resolveBulkImportContext(options);

  const result: BulkImportResult = {
    memoriesCreated: 0,
    duplicatesSkipped: 0,
    entitiesCreated: 0,
    turnsProcessed: 0,
    batchesProcessed: 0,
    errors: [],
  };

  const turns = source.turns;

  if (!turns || turns.length === 0) {
    return result;
  }

  // Validate all turns upfront; collect validation errors
  const validTurns: ImportTurn[] = [];
  for (let i = 0; i < turns.length; i += 1) {
    const issues = validateImportTurn(turns[i], i);
    if (issues.length > 0) {
      const error: BulkImportError = {
        batchIndex: -1,
        message: issues.map((iss) => iss.message).join("; "),
      };
      result.errors.push(error);
    } else {
      validTurns.push(turns[i]);
    }
  }

  if (dryRun) {
    result.turnsProcessed = validTurns.length;
    result.batchesProcessed =
      validTurns.length > 0
        ? Math.ceil(validTurns.length / batchSize)
        : 0;
    return result;
  }

  // Process in batches
  let batchIndex = 0;
  for (let i = 0; i < validTurns.length; i += batchSize) {
    const batch = validTurns.slice(i, i + batchSize);
    try {
      const batchResult = await processBatch(batch, batchContext);
      result.memoriesCreated += batchResult.memoriesCreated;
      result.duplicatesSkipped += batchResult.duplicatesSkipped;
      if (typeof batchResult.entitiesCreated === "number") {
        result.entitiesCreated += batchResult.entitiesCreated;
      }
    } catch (err: unknown) {
      const message =
        err instanceof Error ? err.message : String(err);
      result.errors.push({ batchIndex, message });
    }
    result.turnsProcessed += batch.length;
    result.batchesProcessed += 1;
    batchIndex += 1;
  }

  return result;
}

/**
 * Wearable transcript cleanup — deterministic, zero-LLM normalization.
 *
 * ASR output from always-on wearables is noisy: fragmented utterances,
 * filler tokens, stuttered repeats, and occasional pure garbage. This
 * module cleans a conversation in place-order without changing meaning:
 * everything here is conservative and reversible by re-syncing.
 */

import { detectScriptHints, type ScriptHint } from "./text-language.js";
import type {
  WearableCleanupSettings,
  WearableConversation,
  WearableTranscriptSegment,
} from "./types.js";

export interface CleanupResult {
  conversation: WearableConversation;
  /** Segments removed by the low-quality heuristic. */
  droppedSegments: number;
  /** Segments merged into a predecessor. */
  mergedSegments: number;
}

/** Merge consecutive same-speaker segments when gaps are below this. */
const MERGE_GAP_MS = 30_000;

/**
 * Speaker labels that carry no real diarization signal. Bee (and other
 * providers that fall back to a placeholder) emit "Unknown"/"unknown"
 * or an empty string when diarization is unavailable; merging on such a
 * label would collapse an entire conversation into one segment (issue #1811).
 */
const GENERIC_SPEAKER_PATTERN = /^unknown$/i;

/**
 * Standalone filler tokens stripped when `stripFillers` is on, for
 * scripts that separate words with spaces. Matched case-insensitively
 * as whole tokens — "um" inside "umbrella" is never touched.
 * Deliberately short and low-risk: meaning-bearing hedges ("like",
 * "well", Spanish "este", Arabic "يعني") are NOT stripped, and neither
 * is "mm", which is also a unit of length.
 */
const TOKEN_FILLERS: Readonly<Partial<Record<ScriptHint, readonly string[]>>> = {
  latin: [
    "um",
    "uh",
    "uhm",
    "umm",
    "uhh",
    "erm",
    "hmm",
    "mhm",
    "ähm",
    "äh",
    "ehm",
    "euh",
    "mmm",
  ],
  korean: ["음", "으음", "엄", "어어"],
  arabic: ["امم", "اممم", "اه"],
  cyrillic: ["эм", "ээ", "ммм"],
};

/**
 * Filler tokens for scripts without word spaces. These are removed
 * inline, so each entry must be unambiguous on its own: the elongated
 * Japanese hesitation forms and the two Chinese hesitation particles
 * qualify, while a bare 「あの」 ("that") does not (issue #2196).
 */
const INLINE_FILLERS: Readonly<Partial<Record<ScriptHint, readonly string[]>>> = {
  japanese: ["えーと", "えっと", "ええと", "あのー", "あのう", "うーん"],
  han: ["呃", "嗯"],
};

/**
 * Punctuation that trails a filler and collapses with it, so
 * 「えーと、では」 becomes 「では」 rather than 「、では」. Arabic sentence
 * punctuation is included: an Arabic filler is normally followed by
 * `،`, and without it the token survives the pass.
 */
const TRAILING_FILLER_PUNCTUATION = "[,.、。،؛؟!?]?";

interface FillerMatchers {
  token: RegExp | null;
  inline: RegExp | null;
}

/**
 * Compiled matchers are cached per (script hints + extra tokens) key.
 * A day of transcripts is thousands of segments over a handful of
 * scripts, so this compiles a few regexes instead of one per segment.
 */
const FILLER_MATCHER_CACHE = new Map<string, FillerMatchers>();

function escapeRegExp(value: string): string {
  return value.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
}

/**
 * Build one alternation from `tokens`, or `null` when none remain.
 *
 * Each token contributes BOTH its composed and its decomposed spelling,
 * so `ähm` also matches an ASR that emits `a\u0308hm`. Matching both
 * forms keeps the surrounding transcript byte-identical, which
 * normalizing the text before stripping would not.
 *
 * JavaScript alternation is first-match, not longest-match, so the
 * tokens are sorted longest-first. Without that a built-in prefix such
 * as 「あのー」 would match ahead of a longer operator token that starts
 * with it and leave the tail in the transcript. Ties break on the token
 * itself so the pattern is stable across runs.
 */
function buildAlternation(
  tokens: readonly string[],
  shape: (pattern: string) => { source: string; flags: string },
): RegExp | null {
  const forms = new Set<string>();
  for (const token of tokens) {
    forms.add(token.normalize("NFC"));
    forms.add(token.normalize("NFD"));
  }
  const unique = [...forms].sort(
    (left, right) => right.length - left.length || (left < right ? -1 : left > right ? 1 : 0),
  );
  if (unique.length === 0) return null;
  const { source, flags } = shape(unique.map((token) => escapeRegExp(token)).join("|"));
  return new RegExp(source, flags);
}

function buildFillerMatchers(
  hints: readonly ScriptHint[],
  extraTokens: readonly string[],
): FillerMatchers {
  // Structural key: comma-joining collapses `["a,b"]` and `["a","b"]`
  // onto one entry, and the first caller's regex would then clean the
  // second caller's transcripts.
  const key = JSON.stringify([hints, extraTokens]);
  const cached = FILLER_MATCHER_CACHE.get(key);
  if (cached) return cached;

  const tokens: string[] = [];
  const inline: string[] = [];
  for (const hint of hints) {
    tokens.push(...(TOKEN_FILLERS[hint] ?? []));
    inline.push(...(INLINE_FILLERS[hint] ?? []));
  }
  // Operator tokens apply to every script: the operator knows their own
  // language, and routing them by script hint would silently drop them.
  for (const extra of extraTokens) {
    const trimmed = extra.trim();
    if (trimmed.length === 0) continue;
    if (SPACE_DELIMITED_TOKEN.test(trimmed)) tokens.push(trimmed);
    else inline.push(trimmed);
  }

  const matchers: FillerMatchers = {
    token: buildAlternation(tokens, (pattern) => ({
      source: `(?:^|\\s)(?:${pattern})${TRAILING_FILLER_PUNCTUATION}(?=\\s|$)`,
      flags: "giu",
    })),
    inline: buildAlternation(inline, (pattern) => ({
      source: `(?:${pattern})${TRAILING_FILLER_PUNCTUATION}`,
      flags: "gu",
    })),
  };
  FILLER_MATCHER_CACHE.set(key, matchers);
  return matchers;
}

/**
 * A token whose first character belongs to a space-delimited script.
 *
 * Anything outside this set is removed INLINE, so a script that does
 * space its words must appear here. Hebrew `אה` routed to the inline
 * matcher would strip the suffix of `נראה` and corrupt the transcript.
 */
const SPACE_DELIMITED_TOKEN =
  /^[\p{Script=Latin}\p{Script=Cyrillic}\p{Script=Greek}\p{Script=Hangul}\p{Script=Arabic}\p{Script=Hebrew}\p{N}]/u;

/** Apply configured cleanup passes to one conversation. */
export function cleanConversation(
  conversation: WearableConversation,
  settings: WearableCleanupSettings,
  extraFillerTokens: readonly string[] = [],
): CleanupResult {
  let segments = conversation.segments.map((segment) => ({ ...segment }));
  let droppedSegments = 0;
  let mergedSegments = 0;
  // Optional on the type so other connectors keep the legacy no-op
  // default; absent means "off" (unchanged merge behavior).
  const preserveBoundaries = settings.preserveUtteranceBoundaries === true;

  if (settings.stripFillers) {
    for (const segment of segments) {
      segment.text = stripFillerTokens(segment.text, extraFillerTokens);
    }
  }

  if (settings.collapseRepeats) {
    for (const segment of segments) {
      segment.text = collapseImmediateRepeats(segment.text);
    }
  }

  for (const segment of segments) {
    segment.text = normalizeWhitespace(segment.text);
  }

  if (settings.dropLowQuality) {
    const kept: WearableTranscriptSegment[] = [];
    for (const segment of segments) {
      if (isLowQualitySegment(segment.text)) {
        droppedSegments += 1;
      } else {
        kept.push(segment);
      }
    }
    segments = kept;
  } else {
    // Even without the quality heuristic, segments whose text became
    // empty after filler stripping carry no information.
    const kept = segments.filter((segment) => segment.text.length > 0);
    droppedSegments += segments.length - kept.length;
    segments = kept;
  }

  if (settings.mergeSameSpeaker) {
    const merged: WearableTranscriptSegment[] = [];
    for (const segment of segments) {
      const previous = merged[merged.length - 1];
      if (previous && canMerge(previous, segment, preserveBoundaries)) {
        previous.text = `${previous.text} ${segment.text}`.trim();
        if (segment.endIso) previous.endIso = segment.endIso;
        mergedSegments += 1;
      } else {
        merged.push(segment);
      }
    }
    segments = merged;
  }

  return {
    conversation: { ...conversation, segments },
    droppedSegments,
    mergedSegments,
  };
}

function canMerge(
  previous: WearableTranscriptSegment,
  next: WearableTranscriptSegment,
  preserveUtteranceBoundaries: boolean,
): boolean {
  if (previous.speakerKey !== next.speakerKey) return false;
  // A generic/low-confidence speaker label ("Unknown", empty) carries no
  // real diarization: merging on it collapses unrelated utterances. When
  // the source opts into boundary preservation, refuse to merge across
  // such a label (issue #1811). The keys are equal here, so checking one
  // suffices; diarized labels still merge normally.
  if (preserveUtteranceBoundaries) {
    const label = previous.speakerKey.trim();
    if (label.length === 0 || GENERIC_SPEAKER_PATTERN.test(label)) return false;
  }
  const previousEnd = previous.endIso
    ? Date.parse(previous.endIso)
    : Number.NaN;
  const nextStart = next.startIso ? Date.parse(next.startIso) : Number.NaN;
  // Without timestamps, adjacency is the only signal — still merge.
  if (Number.isNaN(previousEnd) || Number.isNaN(nextStart)) return true;
  return nextStart - previousEnd <= MERGE_GAP_MS;
}

/**
 * Remove filler tokens from `text`. The built-in token set is chosen
 * from the scripts present in the text, so a Japanese or Korean segment
 * is cleaned by its own list instead of silently keeping every filler
 * (issue #2196). Operator tokens apply to every script.
 */
export function stripFillerTokens(
  text: string,
  extraTokens: readonly string[] = [],
): string {
  const matchers = buildFillerMatchers(detectScriptHints(text), extraTokens);
  let result = text;
  if (matchers.token) result = result.replace(matchers.token, " ");
  if (matchers.inline) result = result.replace(matchers.inline, "");
  return normalizeWhitespace(result);
}

/**
 * Collapse immediate word/phrase stutters: "I I I think" -> "I think",
 * "we should we should go" -> "we should go". Only collapses *adjacent*
 * repeats (up to 4-word phrases) so intentional repetition across a
 * sentence is preserved.
 */
export function collapseImmediateRepeats(text: string): string {
  const words = text.split(/\s+/).filter((word) => word.length > 0);
  if (words.length < 2) return text.trim();
  const out: string[] = [];
  let index = 0;
  while (index < words.length) {
    out.push(words[index]);
    index += 1;
    // Greedily consume every adjacent repeat of the phrase that just
    // ended at the output tail (largest phrase first, then re-check so
    // "I I I think" fully collapses to "I think").
    let matched = true;
    while (matched) {
      matched = false;
      for (let size = 4; size >= 1; size--) {
        if (out.length < size || index + size > words.length) continue;
        const tail = out.slice(-size).join(" ").toLowerCase();
        // Spoken digit sequences legitimately repeat ("555 555 1234");
        // never collapse a phrase that carries no letters.
        if (!/\p{L}/u.test(tail)) continue;
        const ahead = words.slice(index, index + size).join(" ").toLowerCase();
        if (tail === ahead) {
          index += size;
          matched = true;
          break;
        }
      }
    }
  }
  return out.join(" ");
}

/**
 * Heuristic ASR-garbage detector. Intentionally conservative: it only
 * drops segments that carry no plausible information.
 */
export function isLowQualitySegment(text: string): boolean {
  const trimmed = text.trim();
  if (trimmed.length === 0) return true;
  // Single repeated character runs ("aaaaaa", "######").
  if (/^(.)\1{4,}$/.test(trimmed)) return true;
  // Mostly non-letter content with no digits (timestamps/amounts are
  // information; "%$#@!" is not).
  const letters = trimmed.replace(/[^\p{L}\p{N}]/gu, "");
  if (letters.length === 0) return true;
  if (trimmed.length >= 12 && letters.length / trimmed.length < 0.3) {
    return true;
  }
  // One identical token repeated many times ("yeah yeah yeah yeah yeah").
  const words = trimmed.toLowerCase().split(/\s+/);
  if (words.length >= 5) {
    const unique = new Set(words);
    if (unique.size === 1) return true;
  }
  return false;
}

export function normalizeWhitespace(text: string): string {
  return text.replace(/\s+/g, " ").trim();
}

import { validateActivityBaseUrl } from "./config.js";
import { displayErrorDetail } from "../runtime/better-sqlite.js";
import type { ActivitySnapshot, ActivitySnapshotPage, ActivitySourceCheck, ActivitySourceClient } from "./types.js";

/** Abort a stalled capture-daemon request rather than hang the whole sync. */
const DEFAULT_REQUEST_TIMEOUT_MS = 30_000;

export interface ActivityHttpSourceClientOptions {
  machineLabel: string;
  baseUrl: string;
  token?: string;
  /** Per-request timeout in ms; defaults to DEFAULT_REQUEST_TIMEOUT_MS. */
  timeoutMs?: number;
}

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null;
}

function stringField(value: Record<string, unknown>, field: string): string {
  const result = value[field];
  if (typeof result !== "string" || result.length === 0) {
    throw new TypeError(`activity source response has no valid ${field}`);
  }
  return result;
}

/**
 * Content fields (app/windowTitle/text) may be legitimately empty: a foreground
 * window can be untitled or have no extractable text. Require the string TYPE
 * (a missing/non-string field still fails loudly) but tolerate "", matching the
 * durable store's contract — else a blank window poisons the day cursor by
 * failing every replay of the same page.
 */
function contentStringField(value: Record<string, unknown>, field: string): string {
  const result = value[field];
  if (typeof result !== "string") {
    throw new TypeError(`activity source response has invalid ${field}`);
  }
  return result;
}

function optionalStringField(value: Record<string, unknown>, field: string): string | undefined {
  const result = value[field];
  if (result === undefined || result === null) return undefined;
  if (typeof result !== "string") throw new TypeError(`activity source response has invalid ${field}`);
  return result;
}

function snapshotFromWire(value: unknown, machine: string): ActivitySnapshot {
  if (!isRecord(value)) throw new TypeError("activity source returned a non-object snapshot");
  const textSource = stringField(value, "textSource");
  if (textSource !== "ax" && textSource !== "ocr") {
    throw new TypeError("activity source response has invalid textSource");
  }
  const browserUrl = optionalStringField(value, "browserUrl");
  const simhash = optionalStringField(value, "simhash");
  return {
    machine,
    capturedAtUtc: stringField(value, "capturedAtUtc"),
    app: contentStringField(value, "app"),
    windowTitle: contentStringField(value, "windowTitle"),
    ...(browserUrl === undefined ? {} : { browserUrl }),
    text: contentStringField(value, "text"),
    textSource,
    contentHash: stringField(value, "contentHash"),
    ...(simhash === undefined ? {} : { simhash }),
  };
}

function responsePage(value: unknown, machine: string): ActivitySnapshotPage {
  if (!isRecord(value) || !Array.isArray(value.snapshots)) {
    throw new TypeError("activity source response has no snapshots array");
  }
  // A missing/undefined nextCursor (field omitted, not JSON null) is normal
  // end-of-pagination — only a present non-string value is invalid.
  const nextCursor = value.nextCursor === undefined ? null : value.nextCursor;
  if (nextCursor !== null && typeof nextCursor !== "string") {
    throw new TypeError("activity source response has invalid nextCursor");
  }
  return {
    snapshots: value.snapshots.map((snapshot) => snapshotFromWire(snapshot, machine)),
    nextCursor,
  };
}

function requestUrl(baseUrl: string, path: string, query: Record<string, string | undefined>): string {
  const url = new URL(path, baseUrl);
  const parts = Object.entries(query)
    .filter((entry): entry is [string, string] => entry[1] !== undefined)
    .map(([key, value]) => `${encodeURIComponent(key)}=${encodeURIComponent(value)}`);
  url.search = parts.join("&");
  return url.toString();
}

export class ActivityHttpSourceClient implements ActivitySourceClient {
  readonly machineLabel: string;
  private readonly baseUrl: string;
  private readonly token: string | undefined;
  private readonly timeoutMs: number;

  constructor(options: ActivityHttpSourceClientOptions) {
    if (options.machineLabel.trim().length === 0) throw new RangeError("activity source machine label must not be empty");
    if (options.timeoutMs !== undefined && (!Number.isFinite(options.timeoutMs) || options.timeoutMs <= 0)) {
      throw new RangeError("activity source timeoutMs must be a positive number");
    }
    this.machineLabel = options.machineLabel;
    this.baseUrl = validateActivityBaseUrl(options.baseUrl).toString();
    this.token = options.token;
    this.timeoutMs = options.timeoutMs ?? DEFAULT_REQUEST_TIMEOUT_MS;
  }

  private async request(url: string, signal?: AbortSignal): Promise<Response> {
    // Bound every request so a stalled daemon aborts instead of hanging the
    // sync forever; honor the caller's signal too when one is supplied.
    const timeout = AbortSignal.timeout(this.timeoutMs);
    const composed = signal === undefined ? timeout : AbortSignal.any([signal, timeout]);
    const response = await fetch(url, {
      headers: this.token === undefined ? undefined : { authorization: `Bearer ${this.token}` },
      signal: composed,
    });
    if (!response.ok) throw new Error(`activity source HTTP ${response.status}`);
    return response;
  }

  async verify(signal?: AbortSignal): Promise<ActivitySourceCheck> {
    try {
      await this.request(requestUrl(this.baseUrl, "/v1/health", {}), signal);
      return { ok: true };
    } catch (error: unknown) {
      // The controlled `HTTP <status>` message is safe to surface verbatim;
      // anything else (network/runtime fetch errors that can embed hostnames or
      // absolute paths) is reduced to a sanitized name+code via
      // displayErrorDetail, matching the wearables operator-facing path.
      const detail =
        error instanceof Error && error.message.startsWith("activity source HTTP ")
          ? error.message.slice("activity source ".length)
          : displayErrorDetail(error) || "request failed";
      return { ok: false, detail };
    }
  }

  async fetchSnapshots(opts: {
    date: string;
    timezone: string;
    cursor?: string | null;
    signal?: AbortSignal;
  }): Promise<ActivitySnapshotPage> {
    const response = await this.request(
      requestUrl(this.baseUrl, "/v1/snapshots", {
        date: opts.date,
        timezone: opts.timezone,
        cursor: opts.cursor ?? undefined,
      }),
      opts.signal,
    );
    return responsePage(await response.json(), this.machineLabel);
  }
}

