import {
  activityDayWindow,
  activityDigestPath,
  composeActivityDigestBody,
  composeActivityDigestMeta,
  isValidActivityDate,
  serializeActivityDigest,
} from "./digest.js";
import type { ActivityStore } from "./store.js";
import type { ActivitySnapshot, ActivitySourceClient } from "./types.js";

const MAX_SYNC_PAGES = 10_000;

/**
 * Sync cursors are scoped per (machine, local day): each date resumes its own
 * pagination independently, so a multi-day window never inherits an earlier
 * day's cursor (which could skip backfill). Encoded into the store's single
 * key column with a NUL separator that cannot occur in a machine label.
 */
export function activityCursorKey(machine: string, date: string): string {
  return `${machine}\u0000${date}`;
}

// Serializes the list -> compose -> write digest section per (memoryDir, date)
// so two sources syncing the same day cannot lose-update each other's digest:
// the last writer in the chain lists every row present and wins.
const digestLocks = new Map<string, Promise<unknown>>();

function withDigestLock<T>(key: string, fn: () => Promise<T>): Promise<T> {
  const prior = digestLocks.get(key) ?? Promise.resolve();
  const next = prior.then(fn, fn);
  const tail = next.then(
    () => undefined,
    () => undefined,
  );
  digestLocks.set(key, tail);
  void tail.then(() => {
    if (digestLocks.get(key) === tail) digestLocks.delete(key);
  });
  return next;
}

export interface ActivitySyncOptions {
  date: string;
  timezone: string;
  memoryDir: string;
  store: ActivityStore;
  signal?: AbortSignal;
  /** Runaway-pagination guard; defaults to MAX_SYNC_PAGES. */
  maxPages?: number;
  /**
   * Search-index refresh, run after a digest is (re)written so the durable
   * markdown becomes discoverable (AGENTS.md rule 31; the digest lives in the
   * QMD collection root but bypasses the extraction->persist->index pipeline).
   * Host-agnostic: the caller injects the core index seam (SearchBackend.update).
   * Best-effort — a failure never fails the sync (rows/digest are durable and
   * index on the next update); it surfaces as `reindexError`.
   */
  afterWrites?: (signal?: AbortSignal) => Promise<void>;
}

export interface ActivitySyncResult {
  machine: string;
  fetched: number;
  inserted: number;
  duplicates: number;
  cursor: string | null;
  digestWritten: boolean;
  /** Set when the post-write reindex threw; the sync still succeeded. */
  reindexError?: string;
}

function snapshotForMachine(snapshot: ActivitySnapshot, machine: string): ActivitySnapshot {
  return {
    machine,
    capturedAtUtc: snapshot.capturedAtUtc,
    app: snapshot.app,
    windowTitle: snapshot.windowTitle,
    ...(snapshot.browserUrl === undefined ? {} : { browserUrl: snapshot.browserUrl }),
    text: snapshot.text,
    textSource: snapshot.textSource,
    contentHash: snapshot.contentHash,
    ...(snapshot.simhash === undefined ? {} : { simhash: snapshot.simhash }),
  };
}

async function writeDigestIfChanged(memoryDir: string, date: string, serialized: string): Promise<boolean> {
  const target = activityDigestPath(memoryDir, date);
  try {
    if ((await readFile(target, "utf8")) === serialized) return false;
  } catch (error: unknown) {
    if (!(error instanceof Error) || !("code" in error) || error.code !== "ENOENT") throw error;
  }

  await mkdir(path.dirname(target), { recursive: true, mode: 0o700 });
  const temporary = `${target}.${process.pid}.${randomUUID()}.tmp`;
  await writeFile(temporary, serialized, { encoding: "utf8", mode: 0o600 });
  await rename(temporary, target);
  return true;
}

/**
 * Pull one source's local-day snapshots and persist its cursor only after every
 * page and the derived digest are durable. Replays after a partial failure are
 * safe because ActivityStore deduplicates an exact captured snapshot.
 */
export async function syncActivitySource(
  source: ActivitySourceClient,
  options: ActivitySyncOptions,
): Promise<ActivitySyncResult> {
  if (!isValidActivityDate(options.date)) {
    throw new RangeError(`Invalid activity date "${options.date}"; expected a real YYYY-MM-DD day.`);
  }
  if (source.machineLabel.trim().length === 0) {
    throw new RangeError("activity source machine label must not be empty");
  }
  const maxPages = options.maxPages ?? MAX_SYNC_PAGES;
  if (!Number.isInteger(maxPages) || maxPages < 1) {
    throw new RangeError("activity sync maxPages must be a positive integer");
  }

  const cursorKey = activityCursorKey(source.machineLabel, options.date);
  let cursor = options.store.getCursor(cursorKey);
  let pages = 0;
  let fetched = 0;
  let inserted = 0;
  let duplicates = 0;
  const seenCursors = new Set<string>();
  let completed = false;

  while (pages < maxPages) {
    options.signal?.throwIfAborted();
    const page = await source.fetchSnapshots({
      date: options.date,
      timezone: options.timezone,
      cursor,
      signal: options.signal,
    });
    pages += 1;
    fetched += page.snapshots.length;

    for (const snapshot of page.snapshots) {
      // Persist every row keyed by its own timestamp: an out-of-window snapshot
      // (replay file, timezone-boundary bug) is durable under its own day and
      // never lost, while the day digest below is a window query so it never
      // pollutes options.date. A malformed instant is rejected loudly here.
      const result = options.store.insertSnapshot(snapshotForMachine(snapshot, source.machineLabel));
      if (result.inserted) inserted += 1;
      else duplicates += 1;
    }
    if (page.nextCursor === null) {
      completed = true;
      break;
    }
    if (typeof page.nextCursor !== "string" || page.nextCursor.length === 0) {
      throw new TypeError("activity source returned an invalid cursor");
    }
    if (seenCursors.has(page.nextCursor)) {
      throw new Error("activity source returned a repeated cursor");
    }
    seenCursors.add(page.nextCursor);
    cursor = page.nextCursor;
  }

  // Only a loop that ran out of its page budget without seeing a terminal
  // null cursor is a runaway; completing on the final allowed page is normal.
  if (!completed) {
    throw new Error(`activity source exceeded ${maxPages} pages`);
  }

  // Re-check abort before the durable write section: stop() may have fired after
  // the last page returned, or while this date waited behind digestLocks. An
  // aborted tick must not compose/write a digest or advance the cursor.
  options.signal?.throwIfAborted();
  const digestWritten = await withDigestLock(`${options.memoryDir}\u0000${options.date}`, async () => {
    options.signal?.throwIfAborted();
    const { startUtc, endUtc } = activityDayWindow(options.date, options.timezone);
    const snapshots = options.store.listSnapshotsForDay(null, startUtc, endUtc);
    const body = composeActivityDigestBody(options.date, options.timezone, snapshots);
    const machines = [...new Set(snapshots.map((snapshot) => snapshot.machine))].sort((a, b) =>
      a < b ? -1 : a > b ? 1 : 0,
    );
    const serialized = serializeActivityDigest(composeActivityDigestMeta(options.date, machines, snapshots, body), body);
    return writeDigestIfChanged(options.memoryDir, options.date, serialized);
  });

  options.signal?.throwIfAborted();
  options.store.setCursor(cursorKey, cursor);

  // Rows and digest are durable and the cursor has advanced; refresh the search
  // index so the new digest is discoverable (rule 31). Best-effort: a failure
  // is reported, not thrown — the data indexes on the next update.
  let reindexError: string | undefined;
  if (digestWritten && options.afterWrites !== undefined) {
    try {
      await options.afterWrites(options.signal);
    } catch (error: unknown) {
      // reindexError is part of the exported ActivitySyncResult. Keep our
      // controlled QMD strict messages, but reduce opaque backend errors (which
      // can embed absolute paths / loader stacks) to a sanitized name+code.
      reindexError =
        error instanceof Error && error.message.startsWith("QMD ")
          ? error.message
          : displayErrorDetail(error) || "reindex failed";
    }
  }

  return {
    machine: source.machineLabel,
    fetched,
    inserted,
    duplicates,
    cursor,
    digestWritten,
    ...(reindexError === undefined ? {} : { reindexError }),
  };
}

/**
 * Filesystem readJournal(D) for the vault daily-note journal (issue #1987).
 *
 * Reuses the #1985 template resolver (every layout #1985 can resolve works
 * here — no separate path configuration) and the #1985 containment
 * discipline: symlinked vault roots and notes that escape the vault are
 * refused before any byte is read. Exactly ONE readFile per call; a
 * missing note is a legitimate no-journal day, not an error (§22).
 */
import { closeSync, constants as fsConstants, fstatSync, lstatSync, openSync, readFileSync, realpathSync, statSync } from "node:fs";
import path from "node:path";

import { expandTildePath } from "../utils/path.js";
import { readVaultJournal } from "./journal-vault-read.js";
import type { ActivityTimelineVaultConfig } from "./types.js";
import { resolveVaultNotePath } from "./vault-path.js";

export type ReadJournalResult =
  | { ok: true; exists: false; reason: "missing_file" | "missing_heading"; filePath: string }
  | {
      ok: true;
      exists: true;
      text: string;
      heading: string;
      warnings: readonly string[];
      filePath: string;
    }
  | { ok: false; reason: "duplicate_heading"; lines: readonly number[]; filePath: string }
  | { ok: false; reason: "not_directory" | "path_escape" | "symlink_escape"; filePath: string };

/** Publisher-owned daily-note heading sections that must never count as journal text. */
export function publisherOwnedSectionNames(vault: ActivityTimelineVaultConfig): string[] {
  if (vault.sectionStrategy !== "heading") return [];
  const names: string[] = [];
  for (const target of Object.values(vault.publish)) {
    if (target.enabled && target.target === "daily" && target.section.trim().length > 0) {
      names.push(target.section);
    }
  }
  return names;
}

export function readJournalForDate(input: {
  vault: ActivityTimelineVaultConfig;
  date: string;
  timezone?: string;
}): ReadJournalResult {
  const journalSection = input.vault.readback.journalSection;
  const relative = resolveVaultNotePath(input.vault.dailyNotePath, input.date, {
    timezone: input.timezone,
  });
  const root = path.resolve(expandTildePath(input.vault.vaultPath));
  const filePath = path.join(root, relative);

  try {
    const rootStat = lstatSync(root);
    if (rootStat.isSymbolicLink() || !rootStat.isDirectory()) {
      return { ok: false, reason: "not_directory", filePath };
    }
  } catch {
    // The vault root itself is missing: no note can exist, so this is a
    // no-journal day, not a configuration error.
    return { ok: true, exists: false, reason: "missing_file", filePath };
  }

  const lexical = path.relative(root, filePath);
  if (
    lexical.length === 0 ||
    lexical === ".." ||
    lexical.startsWith(`..${path.sep}`) ||
    path.isAbsolute(lexical)
  ) {
    return { ok: false, reason: "path_escape", filePath };
  }
  if (!containedBySymlinks(root, filePath)) {
    return { ok: false, reason: "symlink_escape", filePath };
  }

  // One read of a no-follow fd. Ancestor/note symlink swaps cannot redirect
  // the bytes: the path is verified, then the same fd is read once.
  let fileText: string;
  try {
    fileText = readVerifiedDailyNote(root, filePath);
  } catch (err) {
    const code = (err as NodeJS.ErrnoException).code;
    if (code === "ENOENT") {
      return { ok: true, exists: false, reason: "missing_file", filePath };
    }
    if (code === "ELOOP" || code === "EISDIR") {
      return { ok: false, reason: "symlink_escape", filePath };
    }
    throw err;
  }

  const result = readVaultJournal({
    fileText,
    journalSection,
    publishSectionNames: publisherOwnedSectionNames(input.vault),
  });
  return { ...result, filePath };
}

/**
 * Containment under symlinks (mirrors the #1985 publisher helper): the
 * deepest existing ancestor of the note must still resolve inside the
 * real vault root. A symlink chain that leaves the vault is refused
 * before any note byte is read.
 */
function containedBySymlinks(root: string, dest: string): boolean {
  const realRoot = realpathSync(root);
  let probe = dest;
  for (;;) {
    try {
      if (statSync(probe).isFile() || statSync(probe).isDirectory()) {
        const real = realpathSync(probe);
        return real === realRoot || real.startsWith(`${realRoot}${path.sep}`);
      }
    } catch {
      // ENOENT: walk up to the parent.
    }
    const parent = path.dirname(probe);
    if (parent === probe) return false;
    probe = parent;
  }
}

function symlinkRejected(): NodeJS.ErrnoException {
  const err = new Error("symlink refused") as NodeJS.ErrnoException;
  err.code = "ELOOP";
  return err;
}

/**
 * Open the verified daily note with O_NOFOLLOW, fstat a regular file whose
 * identity still matches the path, then read that same fd once. Any symlink
 * in the root→note chain is refused.
 */
function readVerifiedDailyNote(root: string, filePath: string): string {
  const relative = path.relative(root, filePath);
  const parts = relative.split(path.sep).filter((part) => part.length > 0 && part !== ".");
  let cursor = root;
  for (const part of parts) {
    cursor = path.join(cursor, part);
    const st = lstatSync(cursor);
    if (st.isSymbolicLink()) throw symlinkRejected();
  }

  const parent = path.dirname(filePath);
  const parentLstat = lstatSync(parent);
  if (parentLstat.isSymbolicLink() || !parentLstat.isDirectory()) throw symlinkRejected();
  const nofollow = fsConstants.O_NOFOLLOW ?? 0;
  const parentFd = openSync(parent, fsConstants.O_RDONLY | fsConstants.O_DIRECTORY | nofollow);
  try {
    const parentFstat = fstatSync(parentFd);
    if (parentFstat.ino !== parentLstat.ino || parentFstat.dev !== parentLstat.dev) {
      throw symlinkRejected();
    }
  } finally {
    closeSync(parentFd);
  }

  const fd = openSync(filePath, fsConstants.O_RDONLY | nofollow);
  try {
    const opened = fstatSync(fd);
    if (!opened.isFile()) throw symlinkRejected();
    const pathLstat = lstatSync(filePath);
    if (pathLstat.isSymbolicLink() || pathLstat.ino !== opened.ino || pathLstat.dev !== opened.dev) {
      throw symlinkRejected();
    }
    try {
      const fdPath = realpathSync(`/proc/self/fd/${fd}`);
      const realRoot = realpathSync(root);
      if (fdPath !== realRoot && !fdPath.startsWith(`${realRoot}${path.sep}`)) {
        throw symlinkRejected();
      }
    } catch (err) {
      if ((err as NodeJS.ErrnoException).code === "ELOOP") throw err;
    }
    return readFileSync(fd, "utf8");
  } finally {
    closeSync(fd);
  }
}

/**
 * Per-day change detection for journal extraction (issue #1987).
 *
 * `<memoryDir>/state/timeline.json` stores a content hash of the
 * POST-STRIP journal text per day. An unchanged day is never re-extracted
 * (same pattern as the wearables day-skip); a day edited weeks later
 * re-extracts exactly once per content change.
 */
import { createHash, randomBytes } from "node:crypto";
import { mkdirSync, readFileSync, renameSync, writeFileSync } from "node:fs";
import path from "node:path";

import { withHeldFileLock } from "../utils/serialize-mutations.js";

export interface TimelineState {
  version: 1;
  journal: Record<string, string>;
}

const STATE_DIR_NAME = "state";
const STATE_FILE_NAME = "timeline.json";

export function timelineStatePath(memoryDir: string): string {
  return path.join(memoryDir, STATE_DIR_NAME, STATE_FILE_NAME);
}

/** Hash the post-strip section text — Remnic-stripped noise must not re-trigger extraction. */
export function hashJournalText(text: string): string {
  return createHash("sha256").update(text, "utf8").digest("hex");
}

export function readTimelineState(memoryDir: string): TimelineState {
  const filePath = timelineStatePath(memoryDir);
  let parsed: unknown;
  try {
    parsed = JSON.parse(readFileSync(filePath, "utf8"));
  } catch {
    // A corrupt state file must never block extraction: treat as empty.
    return { version: 1, journal: {} };
  }
  if (typeof parsed !== "object" || parsed === null || !("journal" in parsed)) {
    return { version: 1, journal: {} };
  }
  const journal: unknown = parsed.journal;
  if (typeof journal !== "object" || journal === null) return { version: 1, journal: {} };
  const hashes: Record<string, string> = {};
  for (const [date, value] of Object.entries(journal)) {
    if (typeof value === "string" && value.length > 0) hashes[date] = value;
  }
  return { version: 1, journal: hashes };
}

/** Write new before deleting old (§42): unique temp file first, then an atomic rename. */
export function writeTimelineState(memoryDir: string, state: TimelineState): void {
  const filePath = timelineStatePath(memoryDir);
  mkdirSync(path.dirname(filePath), { recursive: true });
  const tempPath = `${filePath}.${process.pid}.${randomBytes(8).toString("hex")}.tmp`;
  writeFileSync(tempPath, `${JSON.stringify(state, null, 2)}\n`);
  renameSync(tempPath, filePath);
}

export function journalDateLockPath(memoryDir: string, date: string): string {
  return path.join(memoryDir, STATE_DIR_NAME, `journal-extract-${date}.lock`);
}

export function timelineStateLockPath(memoryDir: string): string {
  return `${timelineStatePath(memoryDir)}.lock`;
}

const DATE_LOCK_OPTS = { staleMs: 120_000, maxWaitMs: 60_000 } as const;
const STATE_LOCK_OPTS = { staleMs: 30_000, maxWaitMs: 15_000 } as const;

/** Hold the per-date extract lock for hash reread → extract → commit. Fail closed. */
export async function withJournalDateLock<T>(
  memoryDir: string,
  date: string,
  task: () => Promise<T>,
): Promise<T> {
  return withHeldFileLock(journalDateLockPath(memoryDir, date), DATE_LOCK_OPTS, async (acquired) => {
    if (!acquired) {
      throw new Error(`journal: could not acquire the extract lock for ${date}`);
    }
    return task();
  });
}

/** Reread-merge one day's hash under the state-file lock, unique tmp + rename. */
export async function commitJournalHash(memoryDir: string, date: string, hash: string): Promise<void> {
  await withHeldFileLock(timelineStateLockPath(memoryDir), STATE_LOCK_OPTS, async (acquired) => {
    if (!acquired) {
      throw new Error("journal: could not acquire the timeline state lock");
    }
    const latest = readTimelineState(memoryDir);
    writeTimelineState(memoryDir, setJournalHash(latest, date, hash));
  });
}

/** Pure update: set one day's hash. Returns a new state object. */
export function setJournalHash(state: TimelineState, date: string, hash: string): TimelineState {
  return { ...state, journal: { ...state.journal, [date]: hash } };
}

/** True when the day's stored hash matches — unchanged days are skipped. */
export function journalUnchanged(state: TimelineState, date: string, text: string): boolean {
  const stored = state.journal[date];
  return typeof stored === "string" && stored === hashJournalText(text);
}

/**
 * Read-only vault daily-note journal section (issue #1987 first slice).
 *
 * Pure: caller supplies the file text (one read; the filesystem wrapper
 * lives in journal-read.ts). Extracts the unique journal section via
 * the shared ATX heading matcher, then strips every Remnic-owned region
 * (journal-strip.ts) so published output can never re-enter the journal.
 * Missing note and missing section are distinct, labeled no-journal
 * outcomes (§22); duplicate headings refuse with line numbers.
 */

import { parseAtxHeading } from "./journal-section.js";
import { stripRemnicOwnedRegions } from "./journal-strip.js";

export interface ReadVaultJournalInput {
  fileText: string | null | undefined;
  journalSection: string;
  publishSectionNames?: readonly string[];
}

export type ReadVaultJournalResult =
  | { ok: true; exists: false; reason: "missing_file" | "missing_heading" }
  | { ok: true; exists: true; text: string; heading: string; warnings: readonly string[] }
  | { ok: false; reason: "duplicate_heading"; lines: readonly number[] };

export function readVaultJournal(input: ReadVaultJournalInput): ReadVaultJournalResult {
  if (input.fileText === null || input.fileText === undefined) {
    return { ok: true, exists: false, reason: "missing_file" };
  }
  if (input.journalSection.length === 0) {
    return { ok: true, exists: false, reason: "missing_heading" };
  }

  const lines = splitFileLines(input.fileText);
  const hits: number[] = [];
  const levels: number[] = [];
  for (let i = 0; i < lines.length; i++) {
    const heading = parseAtxHeading(lines[i]!);
    if (heading && heading.text === input.journalSection) {
      hits.push(i + 1);
      levels.push(heading.level);
    }
  }
  if (hits.length === 0) return { ok: true, exists: false, reason: "missing_heading" };
  if (hits.length > 1) return { ok: false, reason: "duplicate_heading", lines: hits };

  const headingIndex = hits[0]! - 1;
  const level = levels[0]!;
  let endIndex = lines.length;
  for (let i = headingIndex + 1; i < lines.length; i++) {
    const heading = parseAtxHeading(lines[i]!);
    if (heading && heading.level <= level) {
      endIndex = i;
      break;
    }
  }

  const body = lines.slice(headingIndex + 1, endIndex).join("\n");
  const stripped = stripRemnicOwnedRegions(body, input.publishSectionNames ?? []);
  return {
    ok: true,
    exists: true,
    text: trimNewlines(stripped.text),
    heading: input.journalSection,
    warnings: stripped.warnings,
  };
}

function splitFileLines(fileText: string): string[] {
  const lines = fileText.split("\n");
  for (let i = 0; i < lines.length; i++) {
    const line = lines[i]!;
    if (line.endsWith("\r")) lines[i] = line.slice(0, -1);
  }
  return lines;
}

function trimNewlines(text: string): string {
  let start = 0;
  let end = text.length;
  while (start < end && (text[start] === "\n" || text[start] === "\r")) start++;
  while (end > start && (text[end - 1] === "\n" || text[end - 1] === "\r")) end--;
  return text.slice(start, end);
}

/**
 * Review-only journal extraction pass (issue #1987, reusing #1984's design).
 *
 * Vault journal text is user-authored but unverified: candidates land
 * `pending_review` ONLY — there is no auto-approve path by design, so no
 * journal-derived memory ever reaches `active` without explicit review
 * approval. A judge reject drops the candidate even in review mode.
 * Standard sanitization applies before extraction; unsafe text extracts
 * nothing (the placeholder is never written as memory content).
 *
 * Per-day change detection lives in journal-state.ts (timeline.json);
 * this module is the pure pass over one day's POST-STRIP text.
 */
import { scoreImportance } from "../importance.js";
import { getVerdictKind, type JudgeCandidate, type JudgeVerdict } from "../extraction-judge.js";
import { log } from "../logger.js";
import { sanitizeMemoryContent } from "../sanitize.js";
import { stripAttributesSuffix } from "../structured-attributes.js";
import type {
  BufferTurn,
  ExtractedFact,
  ExtractionResult,
  ImportanceScore,
  MemoryStatus,
} from "../types.js";
import { composeMemoryEnvelope, type SealedMemoryEnvelope, type WriteContext } from "../write-envelope.js";
import { buildJournalMemoryProvenance } from "./journal-vault-provenance.js";
import type { ActivityTimelineJournalConfig } from "./types.js";

/** The subset of StorageManager the journal pass writes through. */
export interface JournalStorageIo {
  writeSealedMemory(
    envelope: SealedMemoryEnvelope,
    extras: { status: MemoryStatus; contentHashSource: string; importance?: ImportanceScore },
  ): Promise<{ tombstoneBlocked?: boolean }>;
  hasFactContentHash(content: string): Promise<boolean>;
  readAllMemories(): Promise<Array<{ path: string; frontmatter: { tags?: string[]; source?: unknown }; content: string }>>;
}

export interface JournalMemoryWriter {
  writeSealedMemory: JournalStorageIo["writeSealedMemory"];
  /** Dedup beyond the fact-only hash index: scans journal-tagged memories. */
  hasJournalMemoryContent(content: string): Promise<boolean>;
}

/**
 * The storage fact-hash index only covers category "fact"; journal
 * candidates span every category, so dedup additionally scans existing
 * journal-tagged memories for an exact content match (wearables parity,
 * Codex P2 on PR #1458).
 */
export function createJournalMemoryWriter(storage: JournalStorageIo): JournalMemoryWriter {
  return {
    writeSealedMemory: storage.writeSealedMemory.bind(storage),
    hasJournalMemoryContent: async (content: string) => {
      if (await storage.hasFactContentHash(content)) return true;
      const needle = stripAttributesSuffix(content);
      const memories = await storage.readAllMemories();
      return memories.some(
        (memory) =>
          Array.isArray(memory.frontmatter.tags) &&
          memory.frontmatter.tags.includes("journal") &&
          stripAttributesSuffix(memory.content) === needle,
      );
    },
  };
}

/** Result of one day's journal extraction run, including the skip reason. */
export type JournalExtractionRunResult = JournalExtractionResult & {
  skippedReason?: string;
  filePath?: string;
};
export interface JournalExtractionDeps {
  extract(turns: BufferTurn[]): Promise<ExtractionResult>;
  writer: JournalMemoryWriter;
  /** LLM-as-judge batch evaluation; absent degrades to review-only writes. */
  judge?(candidates: JudgeCandidate[]): Promise<Map<number, JudgeVerdict>>;
  now?(): Date;
  /** Fires once after any candidate write — the §31 reindex hook. */
  afterWrites?(): Promise<void>;
}

export interface JournalExtractionResult {
  /** pending_review candidates written this run. */
  pendingReview: number;
  /** Candidates the judge rejected — dropped, never queued. */
  rejectedByJudge: number;
  /** Candidates skipped by in-run or persisted dedup. */
  skipped: number;
  /** True when the pass extracted the day (caller advances the state hash). */
  completed: boolean;
  warnings: string[];
}

export async function runJournalReviewExtraction(input: {
  date: string;
  journalText: string;
  source: "memoryDir" | "vault";
  journalConfig: Pick<ActivityTimelineJournalConfig, "extractionMode">;
  deps: JournalExtractionDeps;
}): Promise<JournalExtractionResult> {
  const result: JournalExtractionResult = {
    pendingReview: 0,
    rejectedByJudge: 0,
    skipped: 0,
    completed: false,
    warnings: [],
  };
  if (input.journalConfig.extractionMode !== "review") return result;
  if (input.journalText.trim().length === 0) {
    result.completed = true;
    return result;
  }

  // Standard sanitization like any other source. A violation extracts
  // NOTHING — the sanitized placeholder must never become memory content.
  const sanitized = sanitizeMemoryContent(input.journalText);
  if (!sanitized.clean) {
    result.warnings.push(
      `journal text for ${input.date} failed sanitization (${sanitized.violations.length} violation(s)); extraction skipped`,
    );
    result.completed = true;
    return result;
  }

  const provenance = buildJournalMemoryProvenance({ source: input.source, date: input.date });

  let extracted: ExtractionResult;
  try {
    extracted = await input.deps.extract([
      {
        role: "user",
        content: sanitized.text,
        timestamp: (input.deps.now ?? ((): Date => new Date()))().toISOString(),
      },
    ]);
  } catch (err) {
    // Provider/parse failure must not throw out of the pass; the caller
    // does NOT advance the state hash, so the next run retries this day.
    log.warn(
      `journal extraction failed for ${input.date}: ${err instanceof Error ? err.message : String(err)}`,
    );
    return result;
  }
  if (extracted.extractionFailure !== undefined) {
    log.warn(
      `journal extraction reported a failure for ${input.date}: ${extracted.extractionFailure}`,
    );
    return result;
  }
  result.completed = true;

  let verdicts = new Map<number, JudgeVerdict>();
  const candidates = dedupeInRun(extracted.facts, result);
  if (input.deps.judge !== undefined && candidates.length > 0) {
    try {
      verdicts = await input.deps.judge(
        candidates.map((fact) => ({
          text: fact.content,
          category: fact.category,
          confidence: fact.confidence,
          tags: fact.tags,
          importanceLevel: scoreImportance(fact.content, fact.category, fact.tags).level,
        })),
      );
    } catch (err) {
      log.warn(
        `journal extraction judge unavailable for ${input.date}: ${err instanceof Error ? err.message : String(err)} — review-only writes continue without verdicts`,
      );
    }
  }

  let wrote = false;
  const ctx: WriteContext = { source: "journal", now: input.deps.now };
  for (let index = 0; index < candidates.length; index += 1) {
    const fact = candidates[index]!;
    const verdict = verdicts.get(index);
    const verdictKind = verdict === undefined ? undefined : getVerdictKind(verdict);
    if (verdictKind === "reject") {
      result.rejectedByJudge += 1;
      continue;
    }
    const normalizedKey = fact.content.trim().toLowerCase();
    if (await input.deps.writer.hasJournalMemoryContent(fact.content)) {
      result.skipped += 1;
      continue;
    }
    // Journal text is machine-extracted: salvage mode, warn-logged drops.
    const envelope = composeMemoryEnvelope(
      {
        content: fact.content,
        category: fact.category,
        tags: [...fact.tags, ...provenance.tags],
        entityRef: fact.entityRef,
        confidence: fact.confidence,
        validAt: provenance.validAt,
        structuredAttributes: { ...provenance.structuredAttributes },
        sourceConnector: "journal",
        sourceReason: input.source === "vault" ? "vault daily-note journal" : "memoryDir journal",
      },
      ctx,
      { salvage: true },
    );
    if (envelope.salvageNotes.length > 0) {
      log.warn(`journal write salvaged invalid fields: ${envelope.salvageNotes.join("; ")}`);
    }
    const write = await input.deps.writer.writeSealedMemory(envelope, {
      status: "pending_review",
      contentHashSource: normalizedKey,
      importance: scoreImportance(fact.content, fact.category, fact.tags),
    });
    if (write.tombstoneBlocked) {
      result.skipped += 1;
      continue;
    }
    result.pendingReview += 1;
    wrote = true;
  }

  if (wrote && input.deps.afterWrites !== undefined) {
    try {
      await input.deps.afterWrites();
    } catch (err) {
      // The writes are durable; a reindex failure is reported, not thrown
      // (§31 — the data indexes on the next update).
      result.warnings.push(
        `reindex after journal writes failed: ${err instanceof Error ? err.message : String(err)}`,
      );
    }
  }
  return result;
}

/** Keep the strongest copy per normalized content so one day cannot duplicate itself. */
function dedupeInRun(
  facts: ExtractedFact[],
  result: JournalExtractionResult,
): ExtractedFact[] {
  const seen = new Map<string, ExtractedFact>();
  for (const fact of facts) {
    const key = fact.content.trim().toLowerCase();
    if (!seen.has(key)) seen.set(key, fact);
    else result.skipped += 1;
  }
  return [...seen.values()];
}

/**
 * Build provenance for journal-derived memories (issue #1987).
 *
 * Pure: no I/O, no clock — the day comes from the caller. The source is
 * validated through the journal-source parser, so `structuredAttributes.
 * journalSource` is always a canonical journal source value ("memoryDir"
 * | "vault"), never a re-declared copy of the allow-list.
 */
import { resolveJournalSource } from "./journal-source.js";

export interface JournalMemoryProvenance {
  tags: string[];
  structuredAttributes: Record<string, string>;
  validAt: string;
}

const DAY_PATTERN = /^\d{4}-\d{2}-\d{2}$/;

export function buildJournalMemoryProvenance(input: {
  /** Journal source; must be one of the journal-source allow-list values. */
  source: string;
  /** Journal day, YYYY-MM-DD. */
  date: string;
}): JournalMemoryProvenance {
  if (typeof input.source !== "string") {
    throw new RangeError("journal provenance source must be a string");
  }
  const resolved = resolveJournalSource({ source: input.source });
  if (!resolved.ok) {
    throw new RangeError(
      `journal provenance source must be one of "memoryDir", "vault": ${JSON.stringify(input.source)}`,
    );
  }

  if (typeof input.date !== "string" || !DAY_PATTERN.test(input.date)) {
    throw new RangeError(
      `journal provenance date must be exactly YYYY-MM-DD: ${JSON.stringify(input.date)}`,
    );
  }
  const [year, month, day] = input.date
    .split("-")
    .map(Number) as [number, number, number];
  // Round-trip through UTC rejects non-calendar days (2026-02-30) and the
  // two-digit-year Date.UTC remap (0026 -> 1926) without reading a clock.
  const utc = new Date(Date.UTC(year, month - 1, day));
  if (
    utc.getUTCFullYear() !== year ||
    utc.getUTCMonth() !== month - 1 ||
    utc.getUTCDate() !== day
  ) {
    throw new RangeError(
      `journal provenance date must be a real calendar day: ${input.date}`,
    );
  }

  return {
    tags: ["journal", `journal-day:${input.date}`],
    structuredAttributes: { journalSource: resolved.mode },
    validAt: `${input.date}T00:00:00.000Z`,
  };
}

/**
 * Strip Remnic-owned regions from a vault journal section (issue #1987).
 *
 * Loop prevention for vault journals: before daily-note text is treated
 * as journal text, every managed marker region and every configured
 * owned heading section is removed, so published output can never
 * re-enter the journal. Pure string-in/string-out. No filesystem.
 *
 * Fail-closed marker semantics — a partial Remnic region is NEVER kept:
 *  - an unterminated start marker strips to the end of the section and
 *    records a warning;
 *  - an end marker with no matching start (a pair split across the
 *    journal-section boundary) strips everything before it in the
 *    section, so pre-section published output cannot leak in, and
 *    records a warning.
 * Heading lines parse through the SAME exported ATX parser the
 * journal-section reader uses, so a heading the reader recognizes is
 * always a heading this stripper strips.
 */
import { parseAtxHeading } from "./journal-section.js";

const MARKER_OPEN = "<!-- remnic:";
const MARKER_CLOSE = "-->";
const START_SUFFIX = ":start";
const END_SUFFIX = ":end";

export interface StripResult {
  text: string;
  warnings: readonly string[];
}

type RegionMarker = { kind: "start" | "end"; name: string };

export function stripRemnicOwnedRegions(
  sectionText: string,
  ownedHeadings: readonly string[],
): StripResult {
  const warnings: string[] = [];
  const marked = stripMarkerRegions(sectionText, warnings);
  return { text: stripOwnedHeadings(marked, ownedHeadings), warnings };
}

function stripMarkerRegions(text: string, warnings: string[]): string {
  const lines = text.split("\n");
  const keep = lines.map(() => true);
  let openName: string | null = null;
  for (let i = 0; i < lines.length; i++) {
    const marker = parseRegionMarker(lines[i]!);
    if (openName !== null) {
      keep[i] = false;
      if (marker && marker.kind === "end" && marker.name === openName) openName = null;
      continue;
    }
    if (marker) {
      keep[i] = false;
      if (marker.kind === "start") {
        openName = marker.name;
      } else {
        for (let j = 0; j < i; j++) keep[j] = false;
        // Stray end marker: the matching start lives outside this section
        // (a pair split across the section boundary). Everything before it
        // in the section is presumed published output — fail closed.
        warnings.push(`unmatched remnic region end "${marker.name}"`);

      }
    }
  }
  if (openName !== null) {
    warnings.push(`unclosed remnic region "${openName}"`);
  }
  return emitKeptLines(lines, keep);
}

function stripOwnedHeadings(text: string, ownedHeadings: readonly string[]): string {
  const wanted = ownedHeadingSet(ownedHeadings);
  if (wanted.size === 0 || text.length === 0) return text;
  const lines = text.split("\n");
  const keep = lines.map(() => true);
  for (let i = 0; i < lines.length; i++) {
    if (!keep[i]) continue;
    const heading = parseAtxHeading(lines[i]!);
    if (!heading || !wanted.has(heading.text)) continue;
    keep[i] = false;
    for (let j = i + 1; j < lines.length; j++) {
      const next = parseAtxHeading(lines[j]!);
      if (next && next.level <= heading.level) break;
      keep[j] = false;
    }
  }
  return emitKeptLines(lines, keep);
}

/**
 * Emit kept lines, collapsing the one blank line each removal would
 * otherwise double. Text outside removals is preserved byte-for-byte.
 */
function emitKeptLines(lines: readonly string[], keep: readonly boolean[]): string {
  const out: string[] = [];
  let dropped = false;
  for (let i = 0; i < lines.length; i++) {
    if (!keep[i]) {
      dropped = true;
      continue;
    }
    const line = lines[i]!;
    const previous = out.length > 0 ? out[out.length - 1]! : null;
    if (dropped && previous !== null && previous.trim().length === 0 && line.trim().length === 0) {
      dropped = false;
      continue;
    }
    out.push(line);
    dropped = false;
  }
  return out.join("\n");
}

function parseRegionMarker(line: string): RegionMarker | null {
  const trimmed = line.trim();
  if (!trimmed.startsWith(MARKER_OPEN) || !trimmed.endsWith(MARKER_CLOSE)) return null;
  const inner = trimmed.slice(MARKER_OPEN.length, trimmed.length - MARKER_CLOSE.length).trim();
  if (inner.endsWith(START_SUFFIX)) {
    const name = inner.slice(0, -START_SUFFIX.length);
    return name.length > 0 ? { kind: "start", name } : null;
  }
  if (inner.endsWith(END_SUFFIX)) {
    const name = inner.slice(0, -END_SUFFIX.length);
    return name.length > 0 ? { kind: "end", name } : null;
  }
  return null;
}

function ownedHeadingSet(ownedHeadings: readonly string[]): Set<string> {
  const wanted = new Set<string>();
  for (const entry of ownedHeadings) {
    if (typeof entry !== "string") continue;
    const trimmed = entry.trim();
    if (trimmed.length > 0) wanted.add(trimmed);
  }
  return wanted;
}

import { scoreImportance, isAboveImportanceThreshold } from "../importance.js";
import { getVerdictKind, type JudgeCandidate, type JudgeVerdict, type JudgeVerdictKind } from "../extraction-judge.js";
import { log } from "../logger.js";
import type { ExtractedFact, ExtractionResult, ImportanceScore, MemoryStatus } from "../types.js";
import {
  composeMemoryEnvelope,
  type MemoryWriteInput,
  type SealedMemoryEnvelope,
  type WriteContext,
} from "../write-envelope.js";
import { computeTrustScore, decideSmart, type SmartDecision } from "../wearables/trust.js";
import { activityDayWindow } from "./digest.js";
import type { ActivityConfig } from "./types.js";

const ACTIVITY_ALLOWED_CATEGORIES: Record<string, true> = {
  decision: true,
  commitment: true,
  preference: true,
  moment: true,
};
const FIRST_PERSON = /\b(?:i|we|my|our|i['’]ve|we['’]ve)\b/i;
/**
 * Attribution detection. On-screen text routinely quotes other people, so a
 * first-person pronoun is not ownership evidence. Two shapes are rejected,
 * case-insensitively, with the speaker slot excluding bare first-person
 * pronouns (word-anchored) so "We decided" stays eligible while names that
 * merely begin with a pronoun ("Wendy", "Ian") do not:
 *   - verb attribution:  "Alice wrote: I decided ..." (leading speaker + verb)
 *   - leading label:     "Alice: I decided ..." (chat/comment sender headers)
 * Common document labels ("Note:", "TODO:") are not senders and stay eligible.
 */
const ATTRIBUTION_SPEAKER = String.raw`(?!(?:i|we|us|me|my|our)\b)[A-Za-z][\w.'’-]*`;
const SPEECH_VERB =
  String.raw`(?:said|says|wrote|writes|posted|typed|asked|replied|messaged|commented|noted|announced|added|responded|mentioned|told)`;
const VERB_ATTRIBUTION = new RegExp(String.raw`^\s*${ATTRIBUTION_SPEAKER}\s+${SPEECH_VERB}\b`, "i");
const LABEL_ATTRIBUTION = new RegExp(
  String.raw`^\s*(${ATTRIBUTION_SPEAKER}(?:\s+[A-Za-z][\w.'’-]*){0,3})\s*:\s*`,
  "i",
);
// A sender named inside an otherwise-allowlisted label ("Update from Alice:",
// "Note by Bob:") is still attribution. Case-sensitive on the capitalized name
// so generic labels ("Summary by section:") stay eligible.
const LABEL_NAMES_SENDER = /\b(?:from|by)\s+[A-Z][a-z]/;
const NON_SENDER_LABELS: Record<string, true> = {
  note: true, notes: true, todo: true, fixme: true, reminder: true, update: true,
  updates: true, warning: true, info: true, tip: true, tips: true, summary: true,
  status: true, tldr: true, fyi: true, idea: true, goal: true, goals: true,
  plan: true, plans: true, action: true, actions: true, context: true, question: true,
};
const TRUST_ATTRIBUTE_KEYS: Record<string, true> = {
  trustscore: true,
  trustdecision: true,
  judgeverdict: true,
};

export interface ActivityMemoryWriter {
  /**
   * Locate an existing activity memory for this day whose normalized content
   * matches, or null. The dedup identity is `(activity day, normalized content)`:
   * `dayStartUtc`/`dayEndUtc` bound the half-open day window and `normalizedKey`
   * is trim+lowercase content — so whitespace/case variants collapse, while the
   * SAME text on a different day is NOT a duplicate (recurring actions persist
   * per day). Enables dedup and in-place promotion instead of duplicate or
   * frozen-pending records.
   */
  findActivityMemoryByContent(
    normalizedKey: string,
    dayStartUtc: string,
    dayEndUtc: string,
  ): Promise<{ id: string; status: MemoryStatus | undefined } | null>;
  /**
   * Count active + pending_review activity memories whose event time falls in
   * the half-open [startUtc, endUtc) day window. Seeds `maxMemoriesPerDay` so
   * the cap holds across repeated digest runs on the same day rather than
   * resetting on every call.
   */
  countActivityMemoriesForDay(startUtc: string, endUtc: string): Promise<number>;
  /**
   * Promote a pending_review activity memory to active, merging trust evidence.
   * Returns false when the row is missing or no longer pending.
   */
  promoteActivityMemory(
    id: string,
    attributeUpdates: Record<string, string>,
    confidence?: number,
  ): Promise<boolean>;
  /**
   * Demote a pending_review activity memory to rejected on a fresh judge-reject
   * re-verdict. Active rows are never auto-demoted. Returns false when missing
   * or no longer pending.
   */
  demoteActivityMemory(id: string, attributeUpdates: Record<string, string>): Promise<boolean>;
  writeSealedMemory(
    envelope: SealedMemoryEnvelope,
    extras: { status: MemoryStatus; contentHashSource: string; importance?: ImportanceScore },
  ): Promise<{ tombstoneBlocked?: boolean }>;
}

export interface ActivityMemoryGenerationDeps {
  extract(digestBody: string): Promise<ExtractionResult>;
  judge(candidates: JudgeCandidate[]): Promise<Map<number, JudgeVerdict>>;
  writer: ActivityMemoryWriter;
  now?: () => Date;
}

export interface ActivityMemoryGenerationResult {
  created: number;
  /** Earlier pending_review writes promoted to active by a stronger reassessment. */
  promoted: number;
  /** Earlier pending_review writes retired by a fresh judge-reject verdict. */
  demoted: number;
  pendingReview: number;
  rejectedDisplayedContent: number;
  rejectedByJudge: number;
  skipped: number;
}

/**
 * Activity snapshots contain arbitrary third-party text. Only durable claims
 * explicitly framed as the user's or team's own action, decision, commitment,
 * preference, or moment may enter the trust gate. A first-person pronoun alone
 * is not ownership evidence: quoted or attributed third-party speech (e.g.
 * "Alice wrote: I decided to leave") is rejected.
 */
export function isEligibleActivityFact(fact: ExtractionResult["facts"][number]): boolean {
  if (ACTIVITY_ALLOWED_CATEGORIES[fact.category] !== true) return false;
  if (!FIRST_PERSON.test(fact.content)) return false;
  if (VERB_ATTRIBUTION.test(fact.content)) return false;
  const label = LABEL_ATTRIBUTION.exec(fact.content);
  if (label !== null) {
    const labelText = label[1].trim();
    const firstToken = labelText.split(/\s+/)[0].toLowerCase();
    if (NON_SENDER_LABELS[firstToken] !== true || LABEL_NAMES_SENDER.test(labelText)) return false;
  }
  return true;
}

/**
 * Compose an activity envelope in salvage mode (issue #1989 pattern): digest
 * facts are MACHINE-generated, so one malformed optional field must not abort a
 * whole day's writes. Dropped fields are warn-logged, never silent.
 */
function composeSalvagedActivityEnvelope(
  input: MemoryWriteInput,
  ctx: WriteContext,
): SealedMemoryEnvelope {
  const envelope = composeMemoryEnvelope(input, ctx, { salvage: true });
  if (envelope.salvageNotes.length > 0) {
    log.warn(`activity write salvaged invalid fields: ${envelope.salvageNotes.join("; ")}`);
  }
  return envelope;
}

interface WritableCandidate {
  fact: ExtractedFact;
  key: string;
  status: Extract<MemoryStatus, "active" | "pending_review">;
  trust: number;
  trustDecision: string;
  judgeVerdict?: JudgeVerdictKind;
  importance: ImportanceScore;
}

export async function generateActivityMemories(
  date: string,
  digestBody: string,
  config: ActivityConfig,
  deps: ActivityMemoryGenerationDeps,
): Promise<ActivityMemoryGenerationResult> {
  const result: ActivityMemoryGenerationResult = {
    created: 0,
    promoted: 0,
    demoted: 0,
    pendingReview: 0,
    rejectedDisplayedContent: 0,
    rejectedByJudge: 0,
    skipped: 0,
  };
  // `extractionMode` is the independent extraction gate (per the config contract);
  // `enabled` gates source ingestion, not extraction of a supplied digest.
  if (config.extractionMode !== "smart" || digestBody.trim().length === 0) return result;

  // Event-time bound: the digest's local day. Backfilled or delayed digests
  // then land on the day they describe rather than at write time.
  const { startUtc, endUtc } = activityDayWindow(date, config.timezone);

  let extracted: ExtractionResult;
  try {
    extracted = await deps.extract(digestBody);
  } catch (err) {
    // A provider/parse failure must not throw out of the pass; return the
    // structured zero-result so the caller can retry on the next digest run.
    log.warn(
      `activity extraction failed; skipping the day's memory pass: ${err instanceof Error ? err.message : String(err)}`,
    );
    return result;
  }
  if (extracted.extractionFailure !== undefined) {
    // In-band failure marker (partial/failed provider result): treat like a
    // thrown extraction — warn and return the structured zero-result.
    log.warn(
      `activity extraction reported a failure; skipping the day's memory pass: ${extracted.extractionFailure}`,
    );
    return result;
  }
  const candidates = extracted.facts.filter((fact) => {
    if (!isEligibleActivityFact(fact)) {
      result.rejectedDisplayedContent += 1;
      return false;
    }
    const importance = scoreImportance(fact.content, fact.category, fact.tags);
    if (
      !Number.isFinite(fact.confidence) ||
      fact.confidence < config.minConfidence ||
      !isAboveImportanceThreshold(importance.level, config.minImportance)
    ) {
      result.skipped += 1;
      return false;
    }
    return true;
  });
  let verdicts: Map<number, JudgeVerdict>;
  try {
    verdicts = await deps.judge(candidates.map((fact) => ({
      text: fact.content,
      category: fact.category,
      confidence: fact.confidence,
      tags: fact.tags,
      importanceLevel: scoreImportance(fact.content, fact.category, fact.tags).level,
    })));
  } catch (err) {
    // Degraded smart mode (wearables parity): a judge failure must not abort the
    // day's writes. Fall back to trust scoring alone (no judge accept boost).
    log.warn(
      `activity extraction judge unavailable; using trust scoring only: ${err instanceof Error ? err.message : String(err)}`,
    );
    verdicts = new Map();
  }

  // Score every candidate once, then keep the STRONGEST (highest-trust) copy per
  // normalized key so a weaker earlier duplicate (e.g. a judge-rejected one)
  // cannot crowd out a stronger later one. The day is fixed for this digest, so
  // the normalized content alone keys the in-run set.
  interface ScoredCandidate {
    fact: ExtractedFact;
    key: string;
    trust: number;
    verdictKind?: JudgeVerdictKind;
    decision: SmartDecision;
    importance: ImportanceScore;
  }
  const strongestByKey = new Map<string, ScoredCandidate>();
  for (let index = 0; index < candidates.length; index += 1) {
    const fact = candidates[index];
    const verdict = verdicts.get(index);
    const verdictKind = verdict === undefined ? undefined : getVerdictKind(verdict);
    const trust = computeTrustScore({
      extractionConfidence: fact.confidence,
      sourceTrust: config.sourceTrust,
      judgeVerdict: verdictKind,
      evidence: { corroboratedBySources: [] },
    });
    const decision = decideSmart(trust, verdictKind, {
      autoApproveTrust: config.autoApproveTrust,
      reviewTrust: config.reviewTrust,
    });
    // Dedup key: trim + lowercase so whitespace/case variants collapse (day-scoped).
    const key = fact.content.trim().toLowerCase();
    const scored: ScoredCandidate = {
      fact,
      key,
      trust,
      verdictKind,
      decision,
      importance: scoreImportance(fact.content, fact.category, fact.tags),
    };
    const prev = strongestByKey.get(key);
    if (prev === undefined) {
      strongestByKey.set(key, scored);
    } else {
      // In-run duplicate: keep the copy with the more durable decision (active >
      // review > drop), breaking ties by trust — so a higher-confidence reject
      // cannot crowd out a lower-trust accepted copy.
      result.skipped += 1;
      const rankOf = (outcome: SmartDecision["outcome"]): number =>
        outcome === "active" ? 2 : outcome === "review" ? 1 : 0;
      const curRank = rankOf(scored.decision.outcome);
      const prevRank = rankOf(prev.decision.outcome);
      if (curRank > prevRank || (curRank === prevRank && trust > prev.trust)) {
        strongestByKey.set(key, scored);
      }
    }
  }

  const writable: WritableCandidate[] = [];
  for (const scored of strongestByKey.values()) {
    const existing = await deps.writer.findActivityMemoryByContent(scored.key, startUtc, endUtc);
    if (existing !== null) {
      // Same-day duplicate of a persisted row: reassess in place; never write new
      // or use a cap slot. (The same text on another day is not found here.)
      if (existing.status === "pending_review") {
        if (scored.decision.outcome === "drop" && scored.decision.reason === "judge-rejected") {
          if (
            await deps.writer.demoteActivityMemory(existing.id, {
              trustScore: scored.trust.toFixed(3),
              trustDecision: "demoted-by-rejection",
              judgeVerdict: "reject",
            })
          ) {
            result.demoted += 1;
            continue;
          }
        } else if (scored.decision.outcome === "active") {
          if (
            await deps.writer.promoteActivityMemory(
              existing.id,
              {
                trustScore: scored.trust.toFixed(3),
                trustDecision: "promoted-by-reassessment",
                ...(scored.verdictKind !== undefined ? { judgeVerdict: scored.verdictKind } : {}),
              },
              scored.trust,
            )
          ) {
            result.promoted += 1;
            continue;
          }
        }
      }
      result.skipped += 1;
      continue;
    }
    if (scored.decision.outcome === "drop") {
      if (scored.decision.reason === "judge-rejected") result.rejectedByJudge += 1;
      else result.skipped += 1;
      continue;
    }
    writable.push({
      fact: scored.fact,
      key: scored.key,
      status: scored.decision.outcome === "active" ? "active" : "pending_review",
      trust: scored.trust,
      trustDecision: scored.decision.reason,
      ...(scored.verdictKind !== undefined ? { judgeVerdict: scored.verdictKind } : {}),
      importance: scored.importance,
    });
  }
  writable.sort((a, b) => {
    if (a.trust !== b.trust) return b.trust - a.trust;
    return a.key < b.key ? -1 : a.key > b.key ? 1 : 0;
  });

  // Seed the cap from memories already persisted for this day so repeated digest
  // runs cannot each write up to the limit. `0` stays uncapped.
  const alreadyWritten =
    config.maxMemoriesPerDay > 0 ? await deps.writer.countActivityMemoriesForDay(startUtc, endUtc) : 0;
  let remaining =
    config.maxMemoriesPerDay > 0
      ? Math.max(0, config.maxMemoriesPerDay - alreadyWritten)
      : Number.POSITIVE_INFINITY;

  for (const entry of writable) {
    if (remaining <= 0) {
      result.skipped += 1;
      continue;
    }
    // Trust fields FIRST so the salvage-mode 64-entry cap can never trim these
    // load-bearing keys; extractor attributes ride along after and never override
    // them (collisions are compared against the canonical lowercase form).
    const structuredAttributes: Record<string, string> = {
      trustScore: entry.trust.toFixed(3),
      trustDecision: entry.trustDecision,
      ...(entry.judgeVerdict !== undefined ? { judgeVerdict: entry.judgeVerdict } : {}),
    };
    for (const [key, value] of Object.entries(entry.fact.structuredAttributes ?? {})) {
      if (TRUST_ATTRIBUTE_KEYS[key.trim().toLowerCase()] !== true) structuredAttributes[key] = value;
    }
    const envelope = composeSalvagedActivityEnvelope(
      {
        content: entry.fact.content,
        category: entry.fact.category,
        tags: [...entry.fact.tags, "activity"],
        entityRef: entry.fact.entityRef,
        // Persist the decision-derived trust as confidence; extractor attributes
        // ride along, with trust score/decision + judge verdict added last so
        // downstream sees the active/pending rationale (wearable-path parity).
        confidence: entry.trust,
        validAt: startUtc,
        structuredAttributes,
        sourceConnector: "activity",
        sourceReason: "screen activity digest",
      },
      { source: "activity", now: deps.now },
    );
    const write = await deps.writer.writeSealedMemory(envelope, {
      status: entry.status,
      contentHashSource: entry.key,
      importance: entry.importance,
    });
    if (write.tombstoneBlocked) {
      result.skipped += 1;
      continue;
    }
    if (entry.status === "active") result.created += 1;
    else result.pendingReview += 1;
    remaining -= 1;
  }
  return result;
}

/**
 * Activity retention and export policy (issue #2053 first slice).
 *
 * Pure helpers. Surfaces and parseConfig wiring wait for a later PR.
 * Master `activity.enabled` false denies retain and empties export.
 */
import { coerceBooleanLike, coerceNumber } from "../connectors/coerce.js";

export const MS_PER_DAY = 86_400_000;

export interface ActivityPrivacyPolicy {
  enabled: boolean;
  /** `0` keeps forever. */
  retentionDays: number;
  exportIncludeObservations: boolean;
}

function asRecord(value: unknown, name: string): Record<string, unknown> {
  if (typeof value !== "object" || value === null || Array.isArray(value)) {
    throw new TypeError(`${name} must be an object`);
  }
  return value as Record<string, unknown>;
}

function parseGate(value: unknown, key: string, fallback: boolean): boolean {
  if (value === undefined) return fallback;
  const parsed = coerceBooleanLike(value, key);
  if (parsed === undefined) throw new TypeError(`${key} must be a boolean`);
  return parsed;
}

/** Parse retention and export knobs. Independent of timeline/journal/weekly blocks. */
export function parseActivityPrivacy(raw?: unknown): ActivityPrivacyPolicy {
  if (raw === undefined || raw === null) {
    return { enabled: false, retentionDays: 0, exportIncludeObservations: false };
  }
  const config = asRecord(raw, "activity");
  const enabled = parseGate(config.enabled, "activity.enabled", false);
  let retentionDays = 0;
  if (config.retentionDays !== undefined) {
    const parsed = coerceNumber(config.retentionDays, "activity.retentionDays");
    if (parsed === undefined || !Number.isInteger(parsed) || parsed < 0) {
      throw new RangeError("activity.retentionDays must be a non-negative integer");
    }
    retentionDays = parsed;
  }
  const exportIncludeObservations = parseGate(
    config.exportIncludeObservations,
    "activity.exportIncludeObservations",
    false,
  );
  return { enabled, retentionDays, exportIncludeObservations };
}

/**
 * Half-open retain window: keep when age is in `[0, retentionDays)`.
 * `retentionDays === 0` keeps forever. Master off denies.
 */
export function shouldRetain(
  capturedAtMs: number,
  nowMs: number,
  retentionDays: number,
  enabled = true,
): boolean {
  if (!enabled) return false;
  if (retentionDays < 0 || !Number.isInteger(retentionDays)) {
    throw new RangeError("activity.retentionDays must be a non-negative integer");
  }
  if (retentionDays === 0) return true;
  return nowMs - capturedAtMs < retentionDays * MS_PER_DAY;
}

/** Export payload. Master off or the export gate off returns empty. */
export function observationsForExport<T>(
  observations: readonly T[],
  policy: Pick<ActivityPrivacyPolicy, "enabled" | "exportIncludeObservations">,
): readonly T[] {
  if (!policy.enabled || !policy.exportIncludeObservations) return [];
  return observations;
}

/**
 * Activity retention deletion planner (issue #2053).
 *
 * Pure: decides what a retention pass may delete. Never performs I/O.
 * Safety rule: a path outside the activity-owned roots is refused, never
 * planned for deletion, so unrelated Remnic memories survive.
 */
import { shouldRetain } from "./privacy.js";

export const ACTIVITY_DELETE_SCOPES = [
  "observations",
  "cards",
  "journal",
  "weekly",
  "providerCache",
] as const;
export type ActivityDeleteScope = (typeof ACTIVITY_DELETE_SCOPES)[number];

const KNOWN_SCOPES: readonly string[] = ACTIVITY_DELETE_SCOPES;

/** Deletion only ever touches these memory-dir-relative roots. */
const OWNED_ROOTS: readonly string[] = ["activity", "wearables", "meetings"];

export interface ActivityDeleteCandidate {
  /** Which activity artifact family this item belongs to. */
  scope: string;
  /** Memory-dir-relative path, POSIX separators. */
  relPath: string;
  capturedAtMs: number;
}

export interface ActivityDeletePlan {
  deletePaths: string[];
  keptCount: number;
  /** Candidates refused because they are not activity-owned paths. */
  refused: string[];
}

function isRefusablePath(relPath: unknown): boolean {
  if (typeof relPath !== "string") return true;
  if (relPath.trim() === "") return true;
  // Validate the EXACT candidate path. Trimming first would let
  // " activity/x.md" validate as owned and then plan a delete for
  // "activity/x.md" — a path the caller never supplied. Surrounding
  // whitespace means this is not a clean owned path: refuse it.
  if (relPath !== relPath.trim()) return true;
  if (relPath.startsWith("/")) return true;
  const segments = relPath.split("/");
  if (segments.includes("..")) return true;
  const [root = "", ...rest] = segments;
  return (
    rest.length === 0 ||
    !OWNED_ROOTS.includes(root) ||
    rest.some((segment) => segment.length === 0)
  );
}

function sortedUnique(paths: Iterable<string>): string[] {
  return [...new Set(paths)].sort();
}

export function planActivityDeletion(input: {
  candidates: readonly ActivityDeleteCandidate[];
  scopes: readonly string[];
  retentionDays: number;
  nowMs: number;
}): ActivityDeletePlan {
  const { candidates, scopes, retentionDays, nowMs } = input;

  for (const scope of scopes) {
    if (!KNOWN_SCOPES.includes(scope)) {
      throw new RangeError(`unknown activity delete scope: ${scope}`);
    }
  }
  if (!Number.isInteger(retentionDays) || retentionDays < 0) {
    throw new RangeError("retentionDays must be a non-negative integer");
  }
  if (!Number.isFinite(nowMs)) {
    throw new RangeError("nowMs must be a finite number");
  }

  const selectedScopes = new Set(scopes);
  const deletePaths: string[] = [];
  const refused: string[] = [];
  let keptCount = 0;

  for (const candidate of candidates) {
    if (!KNOWN_SCOPES.includes(candidate.scope)) {
      refused.push(String(candidate.relPath));
      continue;
    }
    if (!selectedScopes.has(candidate.scope)) continue;
    if (isRefusablePath(candidate.relPath)) {
      refused.push(String(candidate.relPath));
      continue;
    }
    // A corrupt timestamp must never resolve toward deletion: every
    // comparison against NaN is false, which shouldRetain reads as
    // "not retained". Refuse the candidate instead.
    if (typeof candidate.capturedAtMs !== "number" || !Number.isFinite(candidate.capturedAtMs)) {
      refused.push(candidate.relPath);
      continue;
    }
    if (shouldRetain(candidate.capturedAtMs, nowMs, retentionDays, true)) {
      keptCount += 1;
      continue;
    }
    deletePaths.push(candidate.relPath);
  }

  return {
    deletePaths: sortedUnique(deletePaths),
    keptCount,
    refused: sortedUnique(refused),
  };
}

/**
 * Content-free activity health snapshot (issue #2053 slice).
 *
 * Pure status builder. Surfaces report gate state, retention policy, source
 * revision, last analysis outcome, and counts only — never observation or
 * card content, prompts, or media.
 */

export const ACTIVITY_ANALYSIS_STATUSES = ["ok", "failed", "skipped", "never"] as const;
export type ActivityAnalysisStatus = (typeof ACTIVITY_ANALYSIS_STATUSES)[number];

export interface ActivityHealthSnapshot {
  enabled: boolean;
  retentionDays: number;
  sourceRevision: string | null;
  lastAnalysisStatus: ActivityAnalysisStatus;
  observationCount: number;
  cardCount: number;
}

const STATUS_ALLOW_LIST = ACTIVITY_ANALYSIS_STATUSES.join(", ");

/**
 * Build the health snapshot. Master `enabled: false` still returns a snapshot
 * (surfaces must report the gate); counts stay as given and are never redacted.
 */
export function buildActivityHealth(input: {
  enabled: boolean;
  retentionDays: number;
  sourceRevision?: string | null;
  lastAnalysisStatus?: string | null;
  observationCount: number;
  cardCount: number;
}): ActivityHealthSnapshot {
  const { enabled, retentionDays, observationCount, cardCount } = input;
  if (!Number.isInteger(retentionDays) || retentionDays < 0) {
    throw new RangeError("retentionDays must be a non-negative integer");
  }
  if (!Number.isInteger(observationCount) || observationCount < 0) {
    throw new RangeError("invalid count: observationCount must be a non-negative integer");
  }
  if (!Number.isInteger(cardCount) || cardCount < 0) {
    throw new RangeError("invalid count: cardCount must be a non-negative integer");
  }
  const rawRevision = input.sourceRevision;
  const trimmedRevision = typeof rawRevision === "string" ? rawRevision.trim() : "";
  const rawStatus = input.lastAnalysisStatus;
  let lastAnalysisStatus: ActivityAnalysisStatus = "never";
  if (rawStatus !== undefined && rawStatus !== null) {
    if (!(ACTIVITY_ANALYSIS_STATUSES as readonly string[]).includes(rawStatus)) {
      throw new TypeError(
        `unknown analysis status ${JSON.stringify(rawStatus)}; expected one of: ${STATUS_ALLOW_LIST}`,
      );
    }
    lastAnalysisStatus = rawStatus as ActivityAnalysisStatus;
  }
  return {
    enabled,
    retentionDays,
    sourceRevision: trimmedRevision === "" ? null : trimmedRevision,
    lastAnalysisStatus,
    observationCount,
    cardCount,
  };
}

/**
 * Master-override resolution for activity feature gates (issue #2053).
 *
 * With `activity.enabled` false, every feature gate reads false regardless of
 * its own config value. Gate values accept booleans and the same string tokens
 * as `parsePrivacyEnabled`; anything else throws so a typo can never silently
 * disable (or enable) a gate. Internal helper — wiring it into parseConfig is
 * a later slice.
 */

import { parsePrivacyEnabled } from "./privacy-enabled.js";

// Frozen at runtime AND still literal-typed: `Object.freeze` preserves the
// `as const` tuple, so ActivityFeatureGate stays a five-member union for
// TypeScript consumers while a JavaScript consumer cannot push a key into
// the array and have resolveActivityGates accept it forever. An explicit
// `readonly string[]` annotation would widen the union back to `string`.
export const ACTIVITY_FEATURE_GATES = Object.freeze([
  "analysis",
  "journal",
  "weekly",
  "export",
  "memoryCreation",
] as const);
export type ActivityFeatureGate = (typeof ACTIVITY_FEATURE_GATES)[number];

export type ActivityGateSet = Readonly<Record<ActivityFeatureGate, boolean>>;


function parseGateValue(key: string, value: unknown): boolean {
  const parsed = parsePrivacyEnabled(value);
  if (!parsed.ok) {
    throw new TypeError(
      `invalid value for activity gate "${key}": ${JSON.stringify(value)} is not a boolean or known token`,
    );
  }
  return parsed.enabled;
}

export function resolveActivityGates(input: {
  enabled?: unknown;
  gates?: Readonly<Record<string, unknown>>;
}): ActivityGateSet {
  const rawGates = input.gates;
  if (rawGates !== undefined && (typeof rawGates !== "object" || rawGates === null || Array.isArray(rawGates))) {
    throw new TypeError("activity gates must be an object");
  }
  if (rawGates) {
    // getOwnPropertyNames, not Object.keys: a non-enumerable own property
    // would skip the unknown-key check below while still being readable by
    // the hasOwn path that resolves values.
    for (const key of Object.getOwnPropertyNames(rawGates)) {
      if (!(ACTIVITY_FEATURE_GATES as readonly string[]).includes(key)) {
        throw new TypeError(
          `unknown activity gate "${key}"; allowed gates: ${ACTIVITY_FEATURE_GATES.join(", ")}`,
        );
      }
    }
  }

  const master =
    input.enabled === undefined ? false : parseGateValue("enabled", input.enabled);

  const result = {} as Record<ActivityFeatureGate, boolean>;
  for (const gate of ACTIVITY_FEATURE_GATES) {
    // Object.keys above enumerates OWN properties only, so an inherited
    // "analysis" never reaches the unknown-key check. Reading it here anyway
    // would let a gate object with an altered prototype enable a gate the
    // caller never set: read own properties only.
    // A PRESENT own key whose value is undefined is not the same as an
    // absent key: composed config objects often carry explicit undefined,
    // and the API promises to throw for invalid values, so present-but-
    // undefined goes through parseGateValue (which refuses it) rather than
    // silently reading as false.
    const present = rawGates !== undefined && Object.hasOwn(rawGates, gate);
    result[gate] = present ? parseGateValue(gate, (rawGates as Record<string, unknown>)[gate]) : false;
  }
  if (!master) {
    for (const gate of ACTIVITY_FEATURE_GATES) {
      result[gate] = false;
    }
  }
  return Object.freeze(result);
}

/**
 * Half-open activity privacy window (issue #2053).
 */
import { shouldRetain } from "./privacy.js";

export interface PrivacyWindowItem {
  capturedAtMs: number;
}

export interface PrivacyWindowOptions {
  fromMs: number;
  toMs: number;
  retainDays: number;
}

/**
 * Keep items in `[fromMs, toMs)`.
 * `retainDays` 0 keeps all ages. `retainDays` N drops older than N days before `toMs`.
 * `toMs <= fromMs` returns `[]`.
 */
export function filterPrivacyWindow<T extends PrivacyWindowItem>(
  items: readonly T[],
  options: PrivacyWindowOptions,
): T[] {
  const { fromMs, toMs, retainDays } = options;
  if (toMs <= fromMs) return [];
  return items.filter((item) => {
    const capturedAtMs = item.capturedAtMs;
    if (capturedAtMs < fromMs || capturedAtMs >= toMs) return false;
    return shouldRetain(capturedAtMs, toMs, retainDays);
  });
}

/**
 * Drop listed keys from one activity item (issue #2053).
 */

export interface ActivityRedactOptions {
  dropKeys: readonly string[];
}

/**
 * Return a shallow copy without `dropKeys`.
 * Unknown keys are ignored. Empty `dropKeys` is a shallow copy.
 * Does not mutate `item`.
 */
export function redactActivityFields<T extends Record<string, unknown>>(
  item: T,
  options: ActivityRedactOptions,
): T {
  const result: Record<string, unknown> = { ...item };
  for (const key of options.dropKeys) {
    delete result[key];
  }
  return result as T;
}

/**
 * Normalize activity privacy drop keys (issue #2053).
 *
 * Trim, drop empty, unique, localeCompare sort.
 * Does not mutate the input list.
 */

export function normalizeDropKeys(keys: readonly string[]): string[] {
  const unique = [...new Set(keys.map((key) => key.trim()).filter((key) => key.length > 0))];
  unique.sort((a, b) => a.localeCompare(b));
  return unique;
}

/**
 * Vault publisher service (issue #1985): composes the landed primitives —
 * path templates (`vault-path.ts`), managed regions (`vault-publish.ts`),
 * marker insertion (`vault-insert.ts`), region-name validation
 * (`vault-region.ts`), begin/end pair assertion (`vault-region-pair.ts`) —
 * into one publish pass over a single vault note.
 *
 * Guarantees: everything outside the managed region (and, in frontmatter
 * mode, everything except `prefix`-owned keys) is byte-identical after
 * publish; unchanged content produces no write; all writes are temp-file +
 * rename in the note's own directory; dry-run performs zero writes; a
 * destination that changed after it was read aborts with `concurrent_write`
 * instead of clobbering an editor's concurrent save; symlinked paths that
 * resolve outside the vault, and symlinked note files, are refused before
 * any write.
 */
import { createHash, randomBytes } from "node:crypto";
import { chmodSync, chownSync, lstatSync, mkdirSync, readFileSync, realpathSync, renameSync, statSync, unlinkSync, writeFileSync, type Stats } from "node:fs";
import path from "node:path";

import { expandTildePath } from "../utils/path.js";
import { applyManagedRegion, fileLines, headingSurvivesRoundTrip } from "./vault-publish.js";
import {
  renderVaultPropertyValue,
  validateVaultProperties,
  type VaultPropertyValue,
} from "./vault-frontmatter.js";
import { insertMarkersUnderHeading } from "./vault-insert.js";
import { validateRegionName } from "./vault-region.js";
import { assertBeginEndPair } from "./vault-region-pair.js";
import { expandVaultTemplateTokens, resolveVaultNotePath } from "./vault-path.js";
import { summarizeVaultPublish, type VaultPublishResult, type VaultPublishStatus } from "./vault-status.js";

export interface VaultSectionProvenance {
  generatorVersion: string;
  /** Local-time generation stamp of the artifact; supplied by the caller so republishing an unchanged artifact stays a no-op. */
  generatedAt: string;
}

export interface VaultSectionPublish {
  /** Managed-region name (the heading name under the heading strategy). */
  name: string;
  /** Rendered artifact body the region owns. */
  content: string;
  /** Unprefixed stats, e.g. `{ focus_minutes: "220" }`; keys get the configured prefix. Values are plain single-line scalars or lists of them (vault-frontmatter.ts). */
  properties?: Readonly<Record<string, VaultPropertyValue>>;
  /** When present, a provenance footer line is appended inside the region. */
  provenance?: VaultSectionProvenance;
}

export interface PublishVaultNoteInput {
  /** Vault root; absolute or `~` path; must be an existing directory. */
  vaultPath: string;
  /** Vault-relative note path template (date tokens). */
  notePathTemplate: string;
  /** Local day, YYYY-MM-DD. */
  date: string;
  sections: readonly VaultSectionPublish[];
  strategy?: "markers" | "heading";
  /** Markers strategy: heading under which missing marker pairs are inserted. */
  insertUnderHeading?: string;
  createMissingNotes?: boolean;
  /** Vault-relative template file used only when creating a missing note. */
  noteTemplate?: string;
  propertiesMode?: "off" | "frontmatter" | "dataview-inline";
  /** Property key prefix, default `remnic_`. */
  propertiesPrefix?: string;
  dryRun?: boolean;
}

// Bounded whitespace runs: an unbounded `\s*` chain around a lazy capture is the
// CodeQL js/polynomial-redos shape `check:regex-safety` rejects (issue #2439).
// The name is captured up to the TERMINAL `:start`/`:end` suffix, so a marker
// carrying a stray colon (`remnic:A:B:start`) is still seen by the scanner
// instead of being silently invisible to it. `validateRegionName` rejects `:`
// in a configured name, so such a marker can never be a legitimate pair and
// always resolves to a refusal below.
const START_MARKER_RE = /^<!--\s{0,8}remnic:(.+):start\s{0,8}-->$/;
const END_MARKER_RE = /^<!--\s{0,8}remnic:(.+):end\s{0,8}-->$/;

type SectionOutcome =
  | { ok: true; text: string }
  | { ok: false; outcome: "skipped" | "error"; reason: string };

export function publishVaultNote(input: PublishVaultNoteInput): VaultPublishStatus {
  if (typeof input !== "object" || input === null) {
    throw new TypeError("publishVaultNote requires an input object.");
  }
  if (!Array.isArray(input.sections) || input.sections.length === 0) {
    throw new RangeError("publishVaultNote requires at least one section.");
  }
  const strategy = input.strategy ?? "markers";
  const propertiesMode = input.propertiesMode ?? "off";
  const prefix = input.propertiesPrefix ?? "remnic_";
  if (typeof prefix !== "string" || prefix.length === 0) {
    throw new RangeError("propertiesPrefix must be a non-empty string.");
  }
  for (const section of input.sections) {
    const name = validateRegionName(section.name);
    if (!name.ok) {
      throw new RangeError(`Section name ${JSON.stringify(section.name)} is not a valid region name.`);
    }
  }


  // Issue #2917: input boundaries are total and run BEFORE any note byte
  // is read or written, so a rejection can never leave a half-merged
  // note behind.

  // The heading strategy matches a section by scanning note headings with
  // the shared ATX parser (`applyHeadingRegion`/`insertMarkersUnderHeading`).
  // A name whose rendered heading parses back to something else — a
  // trailing `#` run is stripped as a closing sequence (`## Timeline #`
  // reads as `Timeline`) — can never be matched, so every publish would
  // no-op or mis-scope. Reject it here rather than at match time.
  const headingsToProbe =
    strategy === "heading" ? input.sections.map((section) => section.name) : [];
  if (typeof input.insertUnderHeading === "string" && input.insertUnderHeading.length > 0) {
    headingsToProbe.push(input.insertUnderHeading);
  }
  for (const headingName of headingsToProbe) {
    if (!headingSurvivesRoundTrip(headingName)) {
      throw new RangeError(
        `Section name ${JSON.stringify(headingName)} is not matchable by the heading parser; it must survive a render-and-parse round trip.`,
      );
    }
  }

  // Property values land in note frontmatter or inline fields; validate
  // their shape and bounds (vault-frontmatter.ts) against the final
  // prefixed keys, in every mode, before any file access.
  const propertyEntries: Array<{ key: string; value: VaultPropertyValue }> = [];
  for (const section of input.sections) {
    if (!section.properties) continue;
    for (const key of Object.keys(section.properties)) {
      const value = section.properties[key];
      if (value === undefined) continue;
      propertyEntries.push({ key: `${prefix}${key}`, value });
    }
  }
  if (propertyEntries.length > 0) {
    const checked = validateVaultProperties(propertyEntries);
    if (!checked.ok) {
      throw new RangeError(`Vault publish properties rejected: ${checked.reason}.`);
    }
  }
  const relative = resolveVaultNotePath(input.notePathTemplate, input.date);
  const result = publishRelative(input, relative, { strategy, propertiesMode, prefix });
  return summarizeVaultPublish(result);
}

function publishRelative(
  input: PublishVaultNoteInput,
  relative: string,
  opts: { strategy: "markers" | "heading"; propertiesMode: string; prefix: string },
): VaultPublishResult[] {
  const vault = expandTildePath(input.vaultPath);
  try {
    // A symlinked vault root is rejected outright (security checklist §3):
    // statSync follows links, lstatSync does not.
    const rootStat = lstatSync(vault);
    if (rootStat.isSymbolicLink() || !rootStat.isDirectory()) return refuse(relative, "error", "not_directory");
  } catch {
    return refuse(relative, "error", "not_directory");
  }

  const root = path.resolve(vault);
  const dest = path.resolve(root, relative);
  const lexical = path.relative(root, dest);
  // `..notes/x.md` is an in-vault name, not parent traversal: only `..`
  // exactly or a `..${path.sep}` prefix escapes.
  if (lexical.length === 0 || lexical === ".." || lexical.startsWith(`..${path.sep}`) || path.isAbsolute(lexical)) {
    return refuse(relative, "error", "path_escape");
  }
  if (!containedBySymlinks(root, dest)) {
    return refuse(relative, "error", "symlink_escape");
  }
  let currentText: string | null = null;
  let expected: DestExpectation | null = null;
  try {
    // A symlinked note is refused even when its target lives inside the
    // vault (issue #1985): writeAtomic renames over the link itself, which
    // would destroy the symlink and leave the target stale while the
    // status still says `updated`.
    if (lstatSync(dest).isSymbolicLink()) {
      return refuse(relative, "error", "symlinked_note");
    }
    const st = statSync(dest);
    if (st.isFile()) {
      currentText = readFileSync(dest, "utf8");
      expected = {
        ino: st.ino,
        mtimeMs: st.mtimeMs,
        size: st.size,
        sha256: createHash("sha256").update(currentText, "utf8").digest("hex"),
      };
    } else return refuse(relative, "error", "not_a_file");
  } catch (err) {
    if ((err as NodeJS.ErrnoException).code !== "ENOENT") throw err;
  }

  let created = false;
  if (currentText === null) {
    if (input.createMissingNotes === true && typeof input.noteTemplate === "string" && input.noteTemplate.length > 0) {
      const templatePath = path.resolve(root, input.noteTemplate);
      const templateRel = path.relative(root, templatePath);
      if (templateRel === ".." || templateRel.startsWith(`..${path.sep}`) || path.isAbsolute(templateRel) || templateRel.length === 0 || !containedBySymlinks(root, templatePath)) {
        return refuse(relative, "error", "template_escape");
      }
      try {
        const templateText = readFileSync(templatePath, "utf8");
        currentText = expandVaultTemplateTokens(templateText, input.date);
        if (!currentText.endsWith("\n")) currentText += "\n";
        created = true;
      } catch {
        return refuse(relative, "error", "template_unreadable");
      }
    } else {
      return refuse(relative, "skipped", "missing_file");
    }
  }

  const original = currentText;
  let text = original;
  const failures: Array<{ outcome: "skipped" | "error"; reason: string }> = [];
  const appliedSections: VaultSectionPublish[] = [];

  for (const section of input.sections) {
    const prefixed =
      opts.propertiesMode === "off" || !section.properties
        ? undefined
        : Object.fromEntries(
            Object.entries(section.properties).map(([key, value]) => [`${opts.prefix}${key}`, value]),
          );
    const content = decorate(section, prefixed, opts.propertiesMode);
    const step = applySection(text, section, content, opts.strategy, input.insertUnderHeading, created);
    if (step.ok) {
      text = step.text;
      appliedSections.push(section);
    } else {
      failures.push({ outcome: step.outcome, reason: step.reason });
    }
  }

  if (failures.length > 0 && appliedSections.length === 0) {
    const worst = failures.find((f) => f.outcome === "error") ?? failures[0]!;
    return [{ path: relative, outcome: worst.outcome, reason: failures.map((f) => f.reason).join("; ") }];
  }
  if (failures.some((f) => f.outcome === "error")) {
    return [{ path: relative, outcome: "error", reason: failures.map((f) => f.reason).join("; ") }];
  }

  // Partial publish (issue #1985 review): when some sections applied and
  // others were skipped, the write covers ONLY the applied sections — their
  // frontmatter properties, and the reported status. A skipped section's
  // properties must never reach the file, and the omission must be surfaced
  // as its own `skipped` row rather than reported as a plain `updated`.
  const skippedReason = failures.length > 0 ? failures.map((f) => f.reason).join("; ") : undefined;
  const withSkipped = (rows: VaultPublishResult[]): VaultPublishResult[] =>
    skippedReason === undefined ? rows : [...rows, { path: relative, outcome: "skipped", reason: skippedReason }];

  if (opts.propertiesMode === "frontmatter") {
    const updates = frontmatterUpdates(appliedSections, opts.prefix);
    if (Object.keys(updates).length > 0) {
      const merged = mergeFrontmatterKeys(text, updates);
      if (!merged.ok) {
        return [{ path: relative, outcome: "error", reason: merged.reason }];
      }
      text = merged.text;
    }
  }

  const prevHash = createHash("sha256").update(original, "utf8").digest("hex");
  const nextHash = createHash("sha256").update(text, "utf8").digest("hex");
  if (prevHash === nextHash) {
    return withSkipped([{ path: relative, outcome: "unchanged" }]);
  }
  if (input.dryRun === true) {
    return withSkipped([{ path: relative, outcome: "updated" }]);
  }
  if (created) {
    // A brand-new note may live in absent folders (Daily/{yyyy}/{MM}). Make
    // the parent chain only here, after every refusal above has passed: the
    // lexical path check and `containedBySymlinks` already proved the deepest
    // existing ancestor is a real directory inside the vault, so every segment
    // `mkdirSync` adds lands beneath that contained ancestor.
    try {
      mkdirSync(path.dirname(dest), { recursive: true });
    } catch {
      return refuse(relative, "error", "mkdir_failed");
    }
  }

  const write = writeAtomic(dest, text, expected);
  if (write === "concurrent") {
    // The note changed after it was read (editor autosave): keep the user's
    // bytes and surface the abort — never a silent overwrite, never `updated`.
    return [{ path: relative, outcome: "error", reason: "concurrent_write" }];
  }
  if (write !== "written") {
    return [{ path: relative, outcome: "error", reason: "rename_failed" }];
  }
  return withSkipped([{ path: relative, outcome: "updated" }]);
}

function refuse(relative: string, outcome: "skipped" | "error", reason: string): VaultPublishResult[] {
  return [{ path: relative, outcome, reason }];
}

function decorate(
  section: VaultSectionPublish,
  prefixed: Record<string, VaultPropertyValue> | undefined,
  mode: string,
): string {
  const parts: string[] = [section.content];
  if (prefixed !== undefined && mode === "dataview-inline") {
    for (const [key, value] of Object.entries(prefixed)) {
      parts.push(`${key}:: ${renderVaultPropertyValue(value)}`);
    }
  }
  if (section.provenance !== undefined) {
    parts.push(
      `*(generated by Remnic timeline · ${section.provenance.generatorVersion} · ${section.provenance.generatedAt})*`,
    );
  }
  return parts.join("\n");
}

function applySection(
  text: string,
  section: VaultSectionPublish,
  content: string,
  strategy: "markers" | "heading",
  insertUnderHeading: string | undefined,
  freshNote: boolean,
): SectionOutcome {
  if (strategy === "markers") {
    const mismatch = findMarkerMismatch(text);
    if (mismatch !== null) {
      return { ok: false, outcome: "skipped", reason: mismatch };
    }
    const applied = applyManagedRegion(text, { strategy: "markers", name: section.name, content });
    if (applied.ok) return { ok: true, text: applied.text };
    if (typeof insertUnderHeading === "string" && insertUnderHeading.length > 0) {
      const inserted = insertMarkersUnderHeading(text, {
        heading: insertUnderHeading,
        name: section.name,
        content,
      });
      if (inserted.ok) return { ok: true, text: inserted.text };
      if (inserted.reason === "duplicate_heading") {
        return {
          ok: false,
          outcome: "error",
          reason: `duplicate_heading:${inserted.lines.join(",")}`,
        };
      }
      return { ok: false, outcome: "skipped", reason: "no_marker" };
    }
    if (freshNote) {
      const suffix = `${text.endsWith("\n") ? "" : "\n"}<!-- remnic:${section.name}:start -->\n${content}\n<!-- remnic:${section.name}:end -->\n`;
      return { ok: true, text: text + suffix };
    }
    return { ok: false, outcome: "skipped", reason: "no_marker" };
  }

  const applied = applyManagedRegion(text, { strategy: "heading", name: section.name, content });
  if (applied.ok) return { ok: true, text: applied.text };
  if (applied.reason === "duplicate_heading") {
    return { ok: false, outcome: "error", reason: `duplicate_heading:${applied.lines.join(",")}` };
  }
  return { ok: false, outcome: "skipped", reason: "no_heading" };
}

/**
 * Refuse any note whose `remnic:<name>:{start,end}` markers are not a flat
 * sequence of correctly named pairs. Every line outside a code block is
 * scanned — a fenced or indented pair is sample text, invisible to this
 * scan and to replacement —
 * because `applyManagedRegion` pairs a start with the next end of the SAME
 * name and would otherwise span a malformed region and delete every byte
 * in between. Four shapes are malformed:
 *   - a crossed pair (`start:A` closed by `end:B`)
 *   - a nested start (`start:A`, `start:B`, `end:A`, `end:B`), where the
 *     inner region's end is the ONLY end left after A closes, so a
 *     replacement spans B's start marker and the user bytes around it
 *   - an orphan end with no open region, which cannot be paired at all
 *   - a marker line that carries the `remnic:…:start`/`:end` shape but no
 *     parseable name (empty name, or whitespace past the bounded run), which
 *     the pairing scan cannot classify at all
 * Ambiguity always resolves to "keep the user's bytes".
 */
function findMarkerMismatch(text: string): string | null {
  let begin: string | null = null;
  for (const row of fileLines(text)) {
    if (row.fenced) continue;
    const trimmed = row.line.trim();
    const start = START_MARKER_RE.exec(trimmed);
    if (start) {
      const name = start[1]!;
      if (begin !== null) return `nested_start:${begin}:${name}`;
      begin = name;
      continue;
    }
    const match = END_MARKER_RE.exec(trimmed);
    if (!match) {
      if (looksLikeRemnicMarkerLine(trimmed)) return `unparsable_marker:${trimmed}`;
      continue;
    }
    const end = match[1]!;
    if (begin === null) return `orphan_end:${end}`;
    // A blank marker name cannot be paired at all: refuse rather than let
    // assertBeginEndPair throw out of the publisher.
    if (begin.trim().length === 0 || end.trim().length === 0) return `name_mismatch:${begin}:${end}`;
    if (!assertBeginEndPair({ beginName: begin, endName: end }).ok) return `name_mismatch:${begin}:${end}`;
    begin = null;
  }
  return null;
}

/**
 * True for a line shaped like this publisher's own marker — `<!--` … `-->`
 * wrapping `remnic:` … terminal `:start`/`:end` — that neither marker regex
 * accepted. Classification only; the caller refuses the file. The exact
 * trimmed line is inspected, never a normalized rewrite of it, so no
 * "helpful" transform can widen what counts as parseable.
 */
function looksLikeRemnicMarkerLine(trimmed: string): boolean {
  if (!trimmed.startsWith("<!--") || !trimmed.endsWith("-->")) return false;
  const inner = trimmed.slice(4, -3).trim();
  if (!inner.startsWith("remnic:")) return false;
  return inner.endsWith(":start") || inner.endsWith(":end");
}

function frontmatterUpdates(
  sections: readonly VaultSectionPublish[],
  prefix: string,
): Record<string, VaultPropertyValue> {
  const updates: Record<string, VaultPropertyValue> = {};
  for (const section of sections) {
    if (!section.properties) continue;
    for (const [key, value] of Object.entries(section.properties)) {
      updates[`${prefix}${key}`] = value;
    }
  }
  return updates;
}

/**
 * Targeted frontmatter edit: only `updates` keys are inserted or replaced;
 * every other byte of the note (key order, comments, anchors, spacing) is
 * preserved. Never parses-and-redumps the YAML block.
 */
export function mergeFrontmatterKeys(
  noteText: string,
  updates: Readonly<Record<string, VaultPropertyValue>>,
): { ok: true; text: string } | { ok: false; reason: string } {
  const entries = Object.entries(updates);
  if (entries.length === 0) return { ok: true, text: noteText };
  // The writer re-validates the same boundary the publisher entry checked
  // (issue #2917): this function is exported, so a direct caller must not
  // be able to smuggle a newline-bearing or unbounded value into a note.
  const checked = validateVaultProperties(entries.map(([key, value]) => ({ key, value })));
  if (!checked.ok) {
    return { ok: false, reason: "invalid_property" };
  }

  const eol = noteText.includes("\r\n") ? "\r\n" : "\n";
  const openRe = /^---\r?$/;
  const firstLineEnd = noteText.indexOf("\n");
  const firstLine = firstLineEnd === -1 ? noteText : noteText.slice(0, firstLineEnd);

  if (!openRe.test(firstLine)) {
    const block = [
      "---",
      ...entries.map(([key, value]) => `${key}: ${renderVaultPropertyValue(value)}`),
      "---",
      "",
    ].join(eol);
    return { ok: true, text: block + eol + noteText };
  }

  const lines = noteText.split(eol);
  let closeIdx = -1;
  for (let i = 1; i < lines.length; i += 1) {
    if (openRe.test(lines[i]!)) {
      closeIdx = i;
      break;
    }
  }
  if (closeIdx === -1) {
    return { ok: false, reason: "malformed_frontmatter" };
  }

  const pending = new Map(entries);
  for (let i = 1; i < closeIdx; i += 1) {
    const line = lines[i]!;
    const idx = line.indexOf(":");
    if (idx === -1) continue;
    const rawKey = line.slice(0, idx);
    // Leading whitespace is exactly the signal that this is a nested,
    // user-owned child key (`custom:` / `  remnic_focus: old`). Only an
    // unindented top-level mapping may satisfy a pending update, so the
    // key is NOT trimmed before that decision.
    if (rawKey !== rawKey.trimStart()) continue;
    const key = rawKey.trimEnd();
    if (!pending.has(key)) continue;
    lines[i] = `${rawKey}: ${renderVaultPropertyValue(pending.get(key)!)}`;
    pending.delete(key);
  }
  const insertAt = closeIdx;
  const added: string[] = [];
  for (const [key, value] of pending.entries()) {
    added.push(`${key}: ${renderVaultPropertyValue(value)}`);
  }
  lines.splice(insertAt, 0, ...added);
  return { ok: true, text: lines.join(eol) };
}

/**
 * Containment under symlinks: the deepest existing ancestor of `dest` must
 * still resolve inside the (real) vault root. A symlink chain that leaves
 * the vault is refused before any note byte is read.
 */
function containedBySymlinks(root: string, dest: string): boolean {
  const realRoot = realpathSync(root);
  let probe = dest;
  for (;;) {
    try {
      if (lstatSync(probe).isSymbolicLink() || statSync(probe).isFile() || statSync(probe).isDirectory()) {
        const real = realpathSync(probe);
        return real === realRoot || real.startsWith(`${realRoot}${path.sep}`);
      }
    } catch {
      // ENOENT: walk up to the parent.
    }
    const parent = path.dirname(probe);
    if (parent === probe) return false;
    probe = parent;
  }
}

/**
 * Destination identity captured when the note was read for this publish:
 * inode + mtime + size + content hash. Any drift by replace time is a
 * concurrent write (an editor that saves in place changes mtimeMs/size/
 * bytes; one that saves atomically changes the inode) and aborts the
 * replace. `null` means the destination did not exist at read time.
 */
interface DestExpectation {
  ino: number;
  mtimeMs: number;
  size: number;
  sha256: string;
}

/** Test-only injection point (issue #1985 review): runs after the note was
 *  read and rendered but before the pre-replace verification, so tests can
 *  simulate a concurrent editor save landing inside that window. Never set
 *  in production code. */
export interface VaultPublisherTestHooks {
  beforeReplaceVerify?: (dest: string) => void;
}

let vaultPublisherTestHooks: VaultPublisherTestHooks | null = null;

export function setVaultPublisherTestHooks(hooks: VaultPublisherTestHooks | null): void {
  vaultPublisherTestHooks = hooks;
}

/**
 * Temp file + rename in the note's own directory; one retry on EBUSY/EPERM.
 *
 * The replacement inode must inherit the destination's permissions: a fresh
 * temp file is `0666 & ~umask`, so renaming it over a `0600` note under a
 * `0022` umask silently widens the note to `0644`. Mode is carried via
 * chmodSync (not a writeFileSync mode option, which umask would mask);
 * ownership is carried only as far as the process's privilege allows
 * (chownSync to another owner fails EPERM for non-root and is ignored).
 *
 * Concurrent-write guard (issue #1985 final review): `text` is derived from
 * the snapshot in `expect`; if the destination no longer matches that
 * snapshot — different inode, mtime, size, bytes, or existence — the rename
 * is refused (`"concurrent"`) and the user's bytes are kept. Deliberately
 * abort-only, no re-read/re-render retry: the refusal direction is the
 * contract, and the next scheduled publish converges against fresh content.
 */
function writeAtomic(dest: string, text: string, expect: DestExpectation | null): "written" | "concurrent" | "failed" {
  const tmpPath = path.join(path.dirname(dest), `.remnic-vault-${randomBytes(8).toString("hex")}.tmp`);
  writeFileSync(tmpPath, text);
  let prev: Stats | null = null;
  try {
    prev = statSync(dest);
  } catch {
    prev = null; // destination absent (new note) — not an error yet
  }
  if (prev !== null) {
    try {
      chmodSync(tmpPath, prev.mode & 0o7777);
      chownSync(tmpPath, prev.uid, prev.gid);
    } catch {
      // Insufficient privilege (EPERM): the temp file keeps its default
      // mode/owner.
    }
  }
  vaultPublisherTestHooks?.beforeReplaceVerify?.(dest);
  try {
    const concurrent =
      expect === null
        ? prev !== null // someone created the note after we planned to
        : prev === null || // the note vanished since it was read
          prev.ino !== expect.ino ||
          prev.mtimeMs !== expect.mtimeMs ||
          prev.size !== expect.size ||
          createHash("sha256").update(readFileSync(dest, "utf8"), "utf8").digest("hex") !== expect.sha256;
    if (concurrent) {
      try {
        unlinkSync(tmpPath);
      } catch {
        // best-effort cleanup
      }
      return "concurrent";
    }
  } catch {
    // Destination unreadable at verify time: refuse to replace.
    try {
      unlinkSync(tmpPath);
    } catch {
      // best-effort cleanup
    }
    return "concurrent";
  }
  for (let attempt = 0; attempt < 2; attempt += 1) {
    try {
      renameSync(tmpPath, dest);
      return "written";
    } catch (err) {
      const code = (err as NodeJS.ErrnoException).code;
      if (attempt === 1 || (code !== "EBUSY" && code !== "EPERM")) {
        try {
          unlinkSync(tmpPath);
        } catch {
          // best-effort cleanup
        }
        if (code === "EBUSY" || code === "EPERM") return "failed";
        throw err;
      }
    }
  }
  return "failed";
}

/**
 * Assert a managed-region begin/end name pair (issue #1985).
 *
 * Trim both names. Empty throws. Mismatch is name_mismatch. Else ok.
 */

export type BeginEndPairInput = {
  beginName: string;
  endName: string;
};

export type BeginEndPairResult = { ok: true } | { ok: false; error: "name_mismatch" };

export function assertBeginEndPair({ beginName, endName }: BeginEndPairInput): BeginEndPairResult {
  const begin = beginName.trim();
  const end = endName.trim();
  if (begin.length === 0 || end.length === 0) {
    throw new RangeError("Region name must be non-empty.");
  }
  if (begin !== end) {
    return { ok: false, error: "name_mismatch" };
  }
  return { ok: true };
}

/**
 * Pure vault-publish outcome aggregator (issue #1985).
 *
 * `summarizeVaultPublish` folds per-file publish results into the status
 * shape the publish report and the dry-run print: sorted per-file outcomes
 * plus zero-filled counts. It performs no I/O and never mutates its input.
 *
 * Fail-closed contract: an unrecognized outcome is refused, never coerced
 * into `skipped` or `error`, and `skipped`/`error` must carry a non-blank
 * reason so every un-actionable row says why.
 */

export const VAULT_PUBLISH_OUTCOMES = ["updated", "unchanged", "skipped", "error"] as const;
export type VaultPublishOutcome = (typeof VAULT_PUBLISH_OUTCOMES)[number];

export interface VaultPublishResult {
  /** Vault-relative note path. */
  path: string;
  outcome: string;
  /** Required for skipped and error, e.g. "no_marker". */
  reason?: string;
}

export interface VaultPublishStatus {
  results: Array<{ path: string; outcome: VaultPublishOutcome; reason?: string }>;
  counts: Record<VaultPublishOutcome, number>;
  /** True when at least one entry is an error. */
  hasError: boolean;
}

interface ValidatedEntry {
  path: string;
  outcome: VaultPublishOutcome;
  reason?: string;
}

/** Total order: path asc, then outcome in allow-list order, then reason. */
function compareEntries(a: ValidatedEntry, b: ValidatedEntry): number {
  if (a.path !== b.path) return a.path < b.path ? -1 : 1;
  const rankA = VAULT_PUBLISH_OUTCOMES.indexOf(a.outcome);
  const rankB = VAULT_PUBLISH_OUTCOMES.indexOf(b.outcome);
  if (rankA !== rankB) return rankA < rankB ? -1 : 1;
  const reasonA = a.reason ?? "";
  const reasonB = b.reason ?? "";
  if (reasonA !== reasonB) return reasonA < reasonB ? -1 : 1;
  return 0;
}

export function summarizeVaultPublish(results: readonly VaultPublishResult[]): VaultPublishStatus {
  if (!Array.isArray(results)) {
    throw new TypeError(`summarizeVaultPublish expects an array of results (got ${typeof results})`);
  }

  const entries: ValidatedEntry[] = [];
  for (const entry of results) {
    if (typeof entry !== "object" || entry === null) {
      throw new TypeError(`vault publish result entries must be objects (got ${typeof entry})`);
    }
    if (typeof entry.path !== "string" || entry.path.trim() === "") {
      throw new RangeError(`vault publish result requires a non-blank path (got ${JSON.stringify(entry.path)})`);
    }
    const outcome = VAULT_PUBLISH_OUTCOMES.find((candidate) => candidate === entry.outcome);
    if (outcome === undefined) {
      throw new TypeError(
        `unknown vault publish outcome ${JSON.stringify(entry.outcome)}; expected one of: ${VAULT_PUBLISH_OUTCOMES.join(", ")}`,
      );
    }
    if (outcome === "skipped" || outcome === "error") {
      if (typeof entry.reason !== "string" || entry.reason.trim() === "") {
        throw new TypeError(
          `vault publish outcome "${outcome}" requires a non-blank reason, e.g. "no_marker" (got ${JSON.stringify(entry.reason)})`,
        );
      }
      entries.push({ path: entry.path, outcome, reason: entry.reason });
    } else {
      if (entry.reason !== undefined) {
        throw new TypeError(
          `vault publish outcome "${outcome}" must not carry a reason (got ${JSON.stringify(entry.reason)})`,
        );
      }
      entries.push({ path: entry.path, outcome });
    }
  }

  const sorted = [...entries].sort(compareEntries);

  const counts = {} as Record<VaultPublishOutcome, number>;
  for (const outcome of VAULT_PUBLISH_OUTCOMES) counts[outcome] = 0;
  for (const entry of sorted) counts[entry.outcome] += 1;

  return {
    results: sorted,
    counts,
    hasError: counts.error > 0,
  };
}

/**
 * Managed-region marker insertion (issue #1985).
 *
 * Inserts a `<!-- remnic:<name>:start/end -->` pair under a unique ATX
 * heading when the region is absent. Code blocks — fenced or indented —
 * are invisible to
 * the heading scan, so a live region is never inserted into a `## …`
 * example. This helper never replaces (see `vault-publish.ts`), never
 * creates files, and never invents a heading. Pure string-in/string-out.
 */
import { fileLines, parseAtxHeading } from "./vault-publish.js";

export type InsertVaultRegionResult =
  | { ok: true; text: string; inserted: true }
  | { ok: true; text: string; inserted: false }
  | { ok: false; reason: "no_heading"; text: string }
  | { ok: false; reason: "duplicate_heading"; lines: readonly number[]; text: string };

export function insertMarkersUnderHeading(
  fileText: string,
  opts: { heading: string; name: string; content: string },
): InsertVaultRegionResult {
  if (typeof opts.heading !== "string" || opts.heading.length === 0) {
    throw new RangeError("Heading must be non-empty.");
  }
  if (typeof opts.name !== "string" || opts.name.length === 0) {
    throw new RangeError("Region name must be non-empty.");
  }

  const startMarker = `<!-- remnic:${opts.name}:start -->`;
  const endMarker = `<!-- remnic:${opts.name}:end -->`;
  const rows = fileLines(fileText);
  // A fenced example pair is sample text, not a live region (issue #1985):
  // only markers outside a code block count as "already present".
  const present =
    rows.some((row) => !row.fenced && row.line.includes(startMarker)) &&
    rows.some((row) => !row.fenced && row.line.includes(endMarker));
  if (present) return { ok: true, text: fileText, inserted: false };

  const hits: Array<{ row: (typeof rows)[number]; level: number }> = [];
  for (const row of rows) {
    if (row.fenced) continue;
    const heading = parseAtxHeading(row.line);
    if (heading && heading.text === opts.heading) {
      hits.push({ row, level: heading.level });
    }
  }
  if (hits.length === 0) return { ok: false, reason: "no_heading", text: fileText };
  if (hits.length > 1) {
    return { ok: false, reason: "duplicate_heading", lines: hits.map((hit) => hit.row.number), text: fileText };
  }

  const hit = hits[0]!;

  const eol = fileText.includes("\r\n") ? "\r\n" : "\n";
  const prefix =
    hit.row.next === fileText.length && !fileText.endsWith("\n") && !fileText.endsWith("\r")
      ? `${fileText}${eol}`
      : fileText.slice(0, hit.row.next);
  let content = opts.content.replace(/\r\n/g, "\n").replace(/\r/g, "\n");
  if (eol === "\r\n") content = content.replace(/\n/g, "\r\n");
  if (content.length > 0 && !content.endsWith(eol)) content += eol;

  const text = `${prefix}${startMarker}${eol}${content}${endMarker}${eol}${fileText.slice(hit.row.next)}`;
  return { ok: true, text, inserted: true };
}

/**
 * Merge vault note frontmatter keys (issue #1985).
 *
 * Pure string helper. Empty updates leave the original YAML unchanged.
 * Listed keys stay. Output keys are sorted. Keys with newlines are rejected.
 */

function assertNoNewlineKey(key: string): void {
  if (key.includes("\n") || key.includes("\r")) {
    throw new RangeError("Vault frontmatter keys must not contain newlines.");
  }
}

export function applyVaultFrontmatter(
  existingYaml: string,
  updates: Readonly<Record<string, string>>,
): string {
  const entries = Object.entries(updates);
  if (entries.length === 0) return existingYaml;

  const merged = new Map<string, string>();
  for (const line of existingYaml.split("\n")) {
    const idx = line.indexOf(":");
    if (idx === -1) continue;
    const key = line.slice(0, idx).trim();
    if (key.length === 0) continue;
    assertNoNewlineKey(key);
    merged.set(key, line.slice(idx + 1).trim());
  }
  for (const [key, value] of entries) {
    assertNoNewlineKey(key);
    merged.set(key, value);
  }

  return [...merged.keys()]
    .sort((a, b) => (a < b ? -1 : a > b ? 1 : 0))
    .map((key) => `${key}: ${merged.get(key)}`)
    .join("\n");
}

/**
 * Frontmatter property boundary for the vault publisher (issue #2917).
 *
 * Property values written into note frontmatter must be single-line
 * plain YAML scalars (or lists of them) whose rendered `key: value` line
 * cannot change shape or inject keys when a YAML parser reads the note
 * back. Validation is pure and total; the publisher runs it before any
 * note byte is read or written, so a rejection can never leave a
 * half-merged note behind.
 */

/** A supported property value: one plain scalar, or a list of them. */
export type VaultPropertyValue = string | readonly string[];

export const VAULT_PROPERTY_KEY_MAX_CHARS = 64;
export const VAULT_PROPERTY_SCALAR_MAX_CHARS = 200;
export const VAULT_PROPERTY_LIST_MAX_ITEMS = 20;
export const VAULT_PROPERTY_TOTAL_MAX_CHARS = 2_000;

// C0 controls, DEL, and C1 controls. Covers \n, \r, \t — a newline is the
// frontmatter-injection primitive (`v\ninjected: yes` becomes a new key).
const CONTROL_RE = /[\u0000-\u001f\u007f-\u009f]/;
// Characters that make the first character a YAML indicator. `-`, `?`,
// and `:` only indicate when followed by a space, so `-5` stays a plain
// scalar while `- 5` does not.
const INDICATOR_CHARS = ",[]{}#&*!|>'\"%@`";
const INJECTION_RE = /: | #/;
// Flow-collection delimiters. Lists render as `[a, b]`; a bare delimiter
// inside an item splits or closes the sequence on re-read.
const FLOW_ITEM_DELIM_RE = /[[\]{},]/;

export type ValidateVaultPropertyResult = { ok: true } | { ok: false; reason: string };

/** Render a validated value the way `mergeFrontmatterKeys` writes it. */
export function renderVaultPropertyValue(value: VaultPropertyValue): string {
  return typeof value === "string" ? value : `[${value.join(", ")}]`;
}

function hasLeadingYamlIndicator(text: string): boolean {
  const first = text[0];
  if (first === undefined) return false;
  return INDICATOR_CHARS.includes(first) || ("-?:".includes(first) && text[1] === " ");
}

function validateScalar(value: string, label: string): ValidateVaultPropertyResult {
  if (value.length === 0) {
    return { ok: false, reason: `${label} must not be empty` };
  }
  if (value.length > VAULT_PROPERTY_SCALAR_MAX_CHARS) {
    return { ok: false, reason: `${label} exceeds ${VAULT_PROPERTY_SCALAR_MAX_CHARS} characters` };
  }
  if (CONTROL_RE.test(value)) {
    return { ok: false, reason: `${label} must not contain control characters or line breaks` };
  }
  if (value !== value.trim()) {
    return { ok: false, reason: `${label} must not carry leading or trailing whitespace` };
  }
  if (hasLeadingYamlIndicator(value)) {
    return { ok: false, reason: `${label} must be a plain scalar (leading "${value[0]}" changes its YAML shape)` };
  }
  if (INJECTION_RE.test(value)) {
    return { ok: false, reason: `${label} must not contain ": " or " #"` };
  }
  if (value.endsWith(":")) {
    return { ok: false, reason: `${label} must not end with ":"` };
  }
  return { ok: true };
}

/**
 * Validate the final (already-prefixed) property set a publish would
 * write: key shape, per-value scalar/list shape, per-value bounds, and
 * the total rendered size across every entry.
 */
export function validateVaultProperties(
  entries: ReadonlyArray<{ key: string; value: VaultPropertyValue }>,
): ValidateVaultPropertyResult {
  let total = 0;
  for (const { key, value } of entries) {
    if (key.length === 0) {
      return { ok: false, reason: "property keys must not be empty" };
    }
    if (key.length > VAULT_PROPERTY_KEY_MAX_CHARS) {
      return { ok: false, reason: `property key exceeds ${VAULT_PROPERTY_KEY_MAX_CHARS} characters` };
    }
    if (
      CONTROL_RE.test(key) ||
      key !== key.trim() ||
      key.includes(":") ||
      key.includes("#") ||
      hasLeadingYamlIndicator(key)
    ) {
      return { ok: false, reason: `property key ${JSON.stringify(key)} is not a plain mapping key` };
    }
    if (typeof value === "string") {
      const scalar = validateScalar(value, `property ${key}`);
      if (!scalar.ok) return scalar;
    } else {
      if (!Array.isArray(value) || value.length === 0) {
        return { ok: false, reason: `property ${key} must be a scalar string or a non-empty list of scalar strings` };
      }
      if (value.length > VAULT_PROPERTY_LIST_MAX_ITEMS) {
        return { ok: false, reason: `property ${key} exceeds ${VAULT_PROPERTY_LIST_MAX_ITEMS} list items` };
      }
      for (const item of value) {
        if (typeof item !== "string") {
          return { ok: false, reason: `property ${key} must be a scalar string or a list of scalar strings` };
        }
        const scalar = validateScalar(item, `property ${key} list item`);
        if (!scalar.ok) return scalar;
        // Lists render in flow form `[a, b]`; a bare delimiter inside an
        // item would split or close the sequence on re-read.
        if (FLOW_ITEM_DELIM_RE.test(item)) {
          return {
            ok: false,
            reason: `property ${key} list item must not contain flow delimiters "[", "]", "{", "}", or ","`,
          };
        }
      }
    }
    total += key.length + 2 + renderVaultPropertyValue(value).length;
    if (total > VAULT_PROPERTY_TOTAL_MAX_CHARS) {
      return {
        ok: false,
        reason: `frontmatter properties exceed the ${VAULT_PROPERTY_TOTAL_MAX_CHARS}-character total`,
      };
    }
  }
  return { ok: true };
}

/**
 * Format a vault-relative note path as an Obsidian wikilink (issue #1985).
 *
 * Relative paths only. Rejects absolute paths, `..` segments, empty input,
 * and newlines. Strips a trailing `.md` suffix.
 */
import path from "node:path";

export function formatVaultWikilink(notePath: string): string {
  if (typeof notePath !== "string" || notePath.trim().length === 0) {
    throw new RangeError("Vault wikilink path must be a non-empty relative path.");
  }
  if (notePath.includes("\n") || notePath.includes("\r")) {
    throw new RangeError("Vault wikilink path must not contain newlines.");
  }
  if (path.posix.isAbsolute(notePath) || path.win32.isAbsolute(notePath)) {
    throw new RangeError("Vault wikilink path must be relative; absolute paths are rejected.");
  }
  if (notePath.split(/[\\/]/).some((segment) => segment === "..")) {
    throw new RangeError("Vault wikilink path must not contain `..` segments.");
  }

  const stripped = notePath.endsWith(".md") ? notePath.slice(0, -3) : notePath;
  if (stripped.length === 0) {
    throw new RangeError("Vault wikilink path must be a non-empty relative path.");
  }
  return `[[${stripped}]]`;
}

/**
 * Join vault-relative path segments (issue #1985).
 *
 * Joins with `/`. Rejects an empty list, empty parts, `..`, absolute
 * parts, backslash, and newline.
 */
import path from "node:path";

export function joinVaultSegments(parts: readonly string[]): string {
  if (parts.length === 0) {
    throw new RangeError("Vault path parts must be a non-empty list.");
  }
  for (const part of parts) {
    if (typeof part !== "string" || part.length === 0) {
      throw new RangeError("Vault path part must be non-empty.");
    }
    if (part.includes("\\")) {
      throw new RangeError("Vault path part must not contain a backslash.");
    }
    if (part.includes("\n") || part.includes("\r")) {
      throw new RangeError("Vault path part must not contain a newline.");
    }
    if (path.posix.isAbsolute(part) || path.win32.isAbsolute(part)) {
      throw new RangeError("Vault path part must be relative.");
    }
    if (part.split("/").includes("..")) {
      throw new RangeError("Vault path part must not contain `..`.");
    }
  }
  return parts.join("/");
}

/**
 * Strip a trailing `.md` suffix from a vault note path (issue #1985).
 *
 * Case-sensitive. Does not strip `.markdown`. Empty input is rejected.
 */

export function stripVaultMdSuffix(notePath: string): string {
  if (typeof notePath !== "string" || notePath.length === 0) {
    throw new RangeError("Vault path must be non-empty.");
  }
  return notePath.endsWith(".md") ? notePath.slice(0, -3) : notePath;
}

/**
 * Pure vault publish dry-run planner (issue #1985).
 *
 * `planVaultDryRun` predicts per-note publish outcomes from text the caller
 * has already read. It takes strings, not paths, and returns only a report:
 * zero writes is a property of the signature, not a promise. Reporting a
 * note as `skipped` with reason `missing_file` when `currentText` is null,
 * matching the real publisher, which refuses to create a missing note.
 *
 * Internal helper: nothing calls it yet. CLI/HTTP wiring for the `--dry-run`
 * flag is a later slice of #1985.
 */
import { summarizeVaultPublish } from "./vault-status.js";
import type { VaultPublishOutcome, VaultPublishResult, VaultPublishStatus } from "./vault-status.js";

export interface VaultDryRunInput {
  /** Vault-relative note path, for reporting only. */
  path: string;
  /** Current note text, or null when the note does not exist. */
  currentText: string | null;
  /** The text a real publish would produce, or null when it would skip. */
  nextText: string | null;
  /** Required when nextText is null: why the publish would skip. */
  skipReason?: string;
}

export function planVaultDryRun(inputs: readonly VaultDryRunInput[]): VaultPublishStatus {
  const results: VaultPublishResult[] = [];
  for (const input of inputs) {
    if (typeof input !== "object" || input === null) {
      throw new TypeError(`vault dry-run inputs must be objects (got ${typeof input})`);
    }
    if (typeof input.path !== "string" || input.path.trim() === "") {
      throw new RangeError(`vault dry-run input requires a non-blank path (got ${JSON.stringify(input.path)})`);
    }
    // Validate the exact values before classification: a non-string or
    // undefined text field is malformed input, and letting it reach the
    // comparison would silently report a prediction for data the contract
    // does not permit (two undefined fields would read as "unchanged").
    for (const field of ["currentText", "nextText"] as const) {
      const value = input[field];
      if (value !== null && typeof value !== "string") {
        throw new TypeError(
          `vault dry-run input ${field} must be a string or null (got ${typeof value})`,
        );
      }
    }
    if (input.nextText === null) {
      if (typeof input.skipReason !== "string" || input.skipReason.trim() === "") {
        throw new TypeError(
          `vault dry-run skip (nextText null) requires a non-blank skipReason (got ${JSON.stringify(input.skipReason)})`,
        );
      }
      results.push({ path: input.path, outcome: "skipped", reason: input.skipReason });
      continue;
    }
    if (input.skipReason !== undefined) {
      throw new TypeError(
        `vault dry-run skipReason is only valid when nextText is null (path ${JSON.stringify(input.path)})`,
      );
    }
    // A missing note is NOT a create: the real publisher (vault-publish.ts
    // publishVaultRegion) refuses to create missing files and returns
    // missing_file, so the dry run must predict that skip rather than promise
    // an update the real run will not perform.
    if (input.currentText === null) {
      results.push({ path: input.path, outcome: "skipped", reason: "missing_file" });
      continue;
    }
    // Byte-exact compare: a publish that rewrites only trailing whitespace is
    // still a write.
    const outcome: VaultPublishOutcome = input.currentText === input.nextText ? "unchanged" : "updated";
    results.push({ path: input.path, outcome });
  }
  return summarizeVaultPublish(results);
}

// ---------------------------------------------------------------------------
// Shared importer base (issue #568)
// ---------------------------------------------------------------------------
//
// The importer adapters defined by issue #568 (`@remnic/import-chatgpt`,
// `@remnic/import-claude`, `@remnic/import-gemini`, `@remnic/import-mem0`) all
// follow the same three-step shape:
//
//   1. parse(input)          — turn a raw file / API payload into a
//                              source-specific intermediate structure.
//   2. transform(parsed)     — flatten that structure into a uniform list of
//                              `ImportedMemory` records with provenance
//                              attached (sourceLabel, importedFromPath,
//                              importedAt).
//   3. writeTo(orchestrator) — hand each memory to the orchestrator via
//                              `ingestBulkImportBatch`. Dry-run mode stops
//                              after transform() and never calls writeTo().
//
// This file defines the shared `ImporterAdapter` interface plus a thin
// `runImporter` helper that handles batching, dry-run plan reporting, and
// progress callbacks so every adapter does not reimplement the same loop.
//
// The existing lower-level `BulkImportSourceAdapter` (weclone-shaped: produces
// turn-structured transcripts) remains untouched and continues to drive
// `runBulkImportCliCommand`. Importer adapters are the higher-level surface
// intended for the four memory sources in #568 — they emit *memories*
// (intent-level content) rather than raw conversation turns.

import { validateImportTurn, type ImportTurn } from "../bulk-import/types.js";

/**
 * A single imported memory record with provenance.
 *
 * Every importer MUST attach a truthful `sourceLabel` (e.g. `"chatgpt"`,
 * `"claude"`, `"gemini"`, `"mem0"`) and MAY attach the export's origin path or
 * URL in `importedFromPath`. `importedAt` is always set by `runImporter` so
 * adapters do not need to timestamp records themselves.
 */
export interface ImportedMemory {
  /**
   * The user-facing memory content. This is the string that will eventually
   * land in the memory store (after extraction / orchestrator processing).
   */
  content: string;
  /**
   * Source-specific identifier for idempotent re-imports. Optional — when
   * present, adapters SHOULD use the source's stable id (e.g. ChatGPT memory
   * uuid); when absent, the orchestrator's own content hashing provides dedup.
   */
  sourceId?: string;
  /**
   * Source-specific timestamp at which the memory was originally created or
   * last updated. ISO 8601. Optional — adapters fall back to `importedAt`
   * when the source does not expose a creation timestamp.
   */
  sourceTimestamp?: string;
  /**
   * Human-readable short label identifying the origin platform
   * (`"chatgpt"`, `"claude"`, `"gemini"`, `"mem0"`). Required so the
   * orchestrator can attribute recalled memories correctly.
   */
  sourceLabel: string;
  /**
   * Path to the export file the memory was parsed from, OR the endpoint URL
   * for API-based imports. Optional but strongly recommended so users can
   * trace a memory back to the file they imported.
   */
  importedFromPath?: string;
  /**
   * ISO 8601 timestamp set by `runImporter` immediately before writeTo().
   * Adapters MAY populate this themselves; `runImporter` will fill in the
   * current wall-clock time when absent.
   */
  importedAt?: string;
  /**
   * Adapter-specific raw metadata preserved for debugging / future rehydration
   * (e.g. conversation id, thread id, tags). Must be JSON-serializable;
   * adapters MUST NOT stash functions or circular references here.
   */
  metadata?: Record<string, unknown>;
}

/**
 * Options threaded through every importer run. Adapters receive this object
 * from `runImporter`; the top-level CLI populates it from `--dry-run`,
 * `--batch-size`, and `--rate-limit` flags.
 */
export interface RunImportOptions {
  /**
   * When true, parse + transform but skip writeTo(). `runImporter` prints a
   * summary of what WOULD have been imported and returns early.
   */
  dryRun?: boolean;
  /**
   * Target batch size for writeTo(). Adapters that chunk memories into
   * smaller orchestrator calls should honor this. Defaults to
   * `DEFAULT_IMPORT_BATCH_SIZE` when undefined. Values outside the valid
   * range throw from `validateImportBatchSize`.
   */
  batchSize?: number;
  /**
   * Optional rate limit for API-backed importers (mem0). Expressed as
   * requests-per-second. Adapters that do not hit an external API may ignore
   * this. When provided, `validateImportRateLimit` enforces the positive-
   * finite contract.
   */
  rateLimit?: number;
  /**
   * Invoked after every chunk of memories is processed. `total` is the full
   * count of memories produced by `transform`; `processed` counts memories
   * already ingested (or skipped in dry-run mode). Adapters SHOULD call this
   * incrementally — `runImporter` itself calls it once per batch.
   */
  onProgress?: (progress: ImportProgress) => void;
}

export interface ImportProgress {
  processed: number;
  total: number;
  /** Current phase for human-readable logging. */
  phase: "parse" | "transform" | "write" | "dry-run";
}

/**
 * Interface every importer package implements.
 *
 * The three-method surface intentionally mirrors the issue #568 spec:
 *
 *   - `parse(input)`: raw payload → intermediate representation.
 *   - `transform(parsed)`: intermediate representation → `ImportedMemory[]`.
 *   - `writeTo(target, memories, options)`: actually commit to the
 *     orchestrator (or whatever target the host provides).
 *
 * Adapters MAY keep `parse` and `transform` separate (e.g. ChatGPT conversions
 * that need to split saved-memories from conversation summaries) or collapse
 * them into a single operation — what matters is that the combined pipeline
 * produces an array of `ImportedMemory` records with correct provenance.
 *
 * `Parsed` is generic so strongly-typed intermediate shapes survive through
 * the adapter's own code without leaking to callers of `runImporter`.
 */
export interface ImporterAdapter<Parsed = unknown> {
  /** Short stable name used by `remnic import --adapter <name>`. */
  name: string;
  /** Human-readable label surfaced in CLI output and source attribution. */
  sourceLabel: string;

  /**
   * Parse a raw payload (file contents, API response, etc.) into the adapter
   * intermediate representation. Pure — MUST NOT call the orchestrator.
   */
  parse(input: unknown, options?: ImporterParseOptions): Parsed | Promise<Parsed>;

  /**
   * Flatten parsed input into an array of importable memories. Pure — MUST
   * NOT call the orchestrator. Provenance fields (`sourceLabel`,
   * `importedFromPath`) should be populated here.
   */
  transform(parsed: Parsed, options?: ImporterTransformOptions): ImportedMemory[] | Promise<ImportedMemory[]>;

  /**
   * Commit the transformed memories to the orchestrator (or equivalent
   * target). `runImporter` only invokes this when dryRun is false.
   *
   * Adapters typically call `orchestrator.ingestBulkImportBatch` once per
   * batch after converting `ImportedMemory` records into `ImportTurn` shapes.
   */
  writeTo(
    target: ImporterWriteTarget,
    memories: ImportedMemory[],
    options: RunImportOptions,
  ): Promise<ImporterWriteResult>;
}

/**
 * Shape of the "target" passed to `writeTo`.
 *
 * This is intentionally narrower than the full `Orchestrator` class: importer
 * adapters only need to push `ImportTurn[]` batches and read the active
 * bulk-import namespace. Narrowing keeps test doubles simple (the slice-1
 * integration test uses a pure in-memory mock) and prevents adapters from
 * reaching into orchestrator internals that would make them harder to move
 * between host environments.
 */
export interface ImporterWriteTarget {
  ingestBulkImportBatch(
    turns: ImportTurn[],
    options?: { deadlineMs?: number },
  ): Promise<unknown>;
  bulkImportWriteNamespace?(): string;
}

export interface ImporterWriteResult {
  memoriesIngested: number;
  /** Optional: adapter-surfaced duplicates or skipped entries. */
  skipped?: number;
}

/** Options forwarded to `parse`. Adapter-specific; additive by design. */
export interface ImporterParseOptions {
  strict?: boolean;
  /** Source path passed through for provenance. */
  filePath?: string;
  /**
   * Requests-per-second throttle, forwarded from the top-level
   * `RunImportOptions.rateLimit`. Only meaningful for API-backed importers
   * (mem0) — file-based adapters ignore it. `runImporter` copies this
   * through automatically so CLI users never have to stash it on
   * `parseOptions` themselves. Cursor review on PR #602.
   */
  rateLimit?: number;
}

/** Options forwarded to `transform`. */
export interface ImporterTransformOptions {
  /** When true, adapters that normally skip bulk conversations should include them. */
  includeConversations?: boolean;
  /** Maximum number of memories to emit. Primarily for tests. */
  maxMemories?: number;
  /** Adapter-specific minimum source text length for importers that filter tiny prompts. */
  minPromptLength?: number;
}

// ---------------------------------------------------------------------------
// Validation helpers
// ---------------------------------------------------------------------------

export const DEFAULT_IMPORT_BATCH_SIZE = 25;
const MIN_IMPORT_BATCH_SIZE = 1;
const MAX_IMPORT_BATCH_SIZE = 500;

/**
 * Coerce and validate the caller-supplied batch size. CLAUDE.md rule 14/51:
 * reject invalid CLI input rather than silently defaulting.
 */
export function validateImportBatchSize(value: number | undefined): number {
  if (value === undefined) return DEFAULT_IMPORT_BATCH_SIZE;
  if (typeof value !== "number" || !Number.isFinite(value)) {
    throw new Error(
      `batchSize must be a finite number, received ${String(value)}`,
    );
  }
  if (!Number.isInteger(value)) {
    throw new Error(`batchSize must be an integer, received ${value}`);
  }
  if (value < MIN_IMPORT_BATCH_SIZE || value > MAX_IMPORT_BATCH_SIZE) {
    throw new Error(
      `batchSize must be between ${MIN_IMPORT_BATCH_SIZE} and ${MAX_IMPORT_BATCH_SIZE}, ` +
        `received ${value}`,
    );
  }
  return value;
}

/**
 * Validate the `--rate-limit` (requests per second) value used by API
 * importers. Zero / negative / non-finite values throw — the CLI must reject
 * them rather than silently import at unlimited speed.
 */
export function validateImportRateLimit(value: number | undefined): number | undefined {
  if (value === undefined) return undefined;
  if (typeof value !== "number" || !Number.isFinite(value)) {
    throw new Error(
      `rateLimit must be a finite number (requests per second), received ${String(value)}`,
    );
  }
  if (value <= 0) {
    throw new Error(
      `rateLimit must be greater than 0 (requests per second), received ${value}`,
    );
  }
  return value;
}

// ---------------------------------------------------------------------------
// Orchestration helpers
// ---------------------------------------------------------------------------

/**
 * Convert an `ImportedMemory` into an `ImportTurn` suitable for
 * `orchestrator.ingestBulkImportBatch`. The resulting turn is always
 * `role="user"` because every downstream source (saved memories, personal
 * context, mem0 entries) represents a first-person statement rather than an
 * assistant response.
 *
 * Keeps provenance on the turn via `participantName` so the extraction
 * pipeline's transcript renderer labels the speaker with the source platform.
 */
export function importedMemoryToTurn(memory: ImportedMemory): ImportTurn {
  const timestamp =
    typeof memory.sourceTimestamp === "string" && memory.sourceTimestamp.length > 0
      ? memory.sourceTimestamp
      : (memory.importedAt ?? new Date().toISOString());
  return {
    role: "user",
    content: memory.content,
    timestamp,
    participantName: memory.sourceLabel,
    ...(memory.sourceId !== undefined ? { participantId: memory.sourceId } : {}),
    importProvenance: {
      sourceLabel: memory.sourceLabel,
      ...(memory.sourceId !== undefined ? { sourceId: memory.sourceId } : {}),
      ...(memory.sourceTimestamp !== undefined ? { sourceTimestamp: memory.sourceTimestamp } : {}),
      ...(memory.importedFromPath !== undefined ? { importedFromPath: memory.importedFromPath } : {}),
      ...(memory.importedAt !== undefined ? { importedAt: memory.importedAt } : {}),
      ...(memory.metadata !== undefined ? { metadata: memory.metadata } : {}),
    },
  };
}

function invalidImportedMemoryError(
  adapterName: string,
  index: number,
  issues: string[],
): Error {
  return new Error(
    `Importer '${adapterName}' produced invalid memory at index ${index}: ${issues.join("; ")}`,
  );
}

function validateImportedMemory(
  memory: ImportedMemory,
  adapterName: string,
  index: number,
): void {
  const issues: string[] = [];
  if (typeof memory.sourceLabel !== "string" || memory.sourceLabel.trim().length === 0) {
    issues.push("sourceLabel must be a non-empty string");
  }
  issues.push(
    ...validateImportTurn(importedMemoryToTurn(memory), index).map(
      (issue) => issue.message,
    ),
  );
  if (issues.length > 0) {
    throw invalidImportedMemoryError(adapterName, index, issues);
  }
}

export interface RunImporterResult {
  adapter: string;
  sourceLabel: string;
  /**
   * Total memories produced by `transform`. In dry-run mode this is the same
   * as the number of memories that WOULD have been written.
   */
  memoriesPlanned: number;
  /**
   * Number of memories actually handed to writeTo(). Always zero in dry-run
   * mode.
   */
  memoriesWritten: number;
  batchesProcessed: number;
  dryRun: boolean;
  /** Mirrors the importedAt stamped on every memory. */
  importedAt: string;
}

/**
 * Orchestrate `parse → transform → writeTo` for an adapter. This is the
 * default pipeline used by the CLI; adapters are free to implement their own
 * orchestration when they need per-record rate-limiting or streaming parses
 * that would not fit in the "produce full array before writing" shape.
 *
 * Mutates the supplied memory records by filling in `importedAt` when the
 * adapter did not set it (CLAUDE.md rule 38: records are written in insertion
 * order to keep the provenance log stable).
 */
export async function runImporter<Parsed>(
  adapter: ImporterAdapter<Parsed>,
  input: unknown,
  target: ImporterWriteTarget,
  options: RunImportOptions & {
    parseOptions?: ImporterParseOptions;
    transformOptions?: ImporterTransformOptions;
  } = {},
): Promise<RunImporterResult> {
  const batchSize = validateImportBatchSize(options.batchSize);
  validateImportRateLimit(options.rateLimit);

  const importedAt = new Date().toISOString();
  const dryRun = options.dryRun === true;
  const onProgress = options.onProgress;

  // Phase 1 — parse. Forward the validated rateLimit so API-backed adapters
  // (mem0) can throttle their own fetches. Caller-supplied parseOptions
  // takes precedence so tests can still override.
  onProgress?.({ processed: 0, total: 0, phase: "parse" });
  const parseOptions: ImporterParseOptions = {
    ...(options.rateLimit !== undefined ? { rateLimit: options.rateLimit } : {}),
    ...(options.parseOptions ?? {}),
  };
  const parsed = await adapter.parse(input, parseOptions);

  // Phase 2 — transform
  onProgress?.({ processed: 0, total: 0, phase: "transform" });
  const memoriesRaw = await adapter.transform(parsed, options.transformOptions);
  if (!Array.isArray(memoriesRaw)) {
    throw new Error(
      `Importer '${adapter.name}' transform() returned a non-array. ` +
        "Adapters must produce ImportedMemory[].",
    );
  }
  const memories = memoriesRaw.map((memory, index) => {
    if (memory === null || typeof memory !== "object") {
      throw invalidImportedMemoryError(adapter.name, index, [
        "memory must be an object",
      ]);
    }
    const record = memory as ImportedMemory;
    const sourceLabel =
      typeof record.sourceLabel === "string" && record.sourceLabel.trim().length > 0
        ? record.sourceLabel.trim()
        : adapter.sourceLabel.trim();
    return {
      ...record,
      sourceLabel,
      importedAt: record.importedAt ?? importedAt,
    };
  });
  memories.forEach((memory, index) => validateImportedMemory(memory, adapter.name, index));

  // Phase 3 — write (or dry-run plan)
  if (dryRun) {
    onProgress?.({
      processed: memories.length,
      total: memories.length,
      phase: "dry-run",
    });
    return {
      adapter: adapter.name,
      sourceLabel: adapter.sourceLabel,
      memoriesPlanned: memories.length,
      memoriesWritten: 0,
      batchesProcessed: 0,
      dryRun: true,
      importedAt,
    };
  }

  let batchesProcessed = 0;
  let memoriesWritten = 0;
  for (let i = 0; i < memories.length; i += batchSize) {
    const batch = memories.slice(i, i + batchSize);
    const result = await adapter.writeTo(target, batch, options);
    memoriesWritten += result.memoriesIngested;
    batchesProcessed += 1;
    onProgress?.({
      processed: Math.min(i + batch.length, memories.length),
      total: memories.length,
      phase: "write",
    });
  }

  return {
    adapter: adapter.name,
    sourceLabel: adapter.sourceLabel,
    memoriesPlanned: memories.length,
    memoriesWritten,
    batchesProcessed,
    dryRun: false,
    importedAt,
  };
}

/**
 * Default `writeTo` implementation for importers that want to hand every
 * memory to `orchestrator.ingestBulkImportBatch` without custom routing.
 * Adapters that need per-record rate-limiting or conversation-thread linking
 * are free to implement their own `writeTo`.
 */
export async function defaultWriteMemoriesToOrchestrator(
  target: ImporterWriteTarget,
  memories: ImportedMemory[],
): Promise<ImporterWriteResult> {
  if (memories.length === 0) {
    return { memoriesIngested: 0 };
  }
  memories.forEach((memory, index) =>
    validateImportedMemory(memory, "defaultWriteMemoriesToOrchestrator", index),
  );
  const turns = memories.map(importedMemoryToTurn);
  await target.ingestBulkImportBatch(turns);
  return { memoriesIngested: memories.length };
}

// ---------------------------------------------------------------------------
// File-importer factory (issue #2794)
// ---------------------------------------------------------------------------

/** Parse args `defineFileImporterAdapter` forwards — the keys file adapters use. */
export interface FileImporterParseArgs {
  strict?: boolean;
  filePath?: string;
}

/** Per-package config consumed by `defineFileImporterAdapter`. */
export interface FileImporterDefinition<Parsed> {
  name: string;
  sourceLabel: string;
  /** Decode the raw export file. Receives only `strict` / `filePath`. */
  parse(input: unknown, options: FileImporterParseArgs): Parsed | Promise<Parsed>;
  /** Flatten the parsed export into `ImportedMemory[]` with provenance. */
  transform(
    parsed: Parsed,
    options: ImporterTransformOptions | undefined,
  ): ImportedMemory[] | Promise<ImportedMemory[]>;
}

/**
 * Build the standard file-importer `ImporterAdapter`: parse with the
 * `strict`/`filePath` spread, a package-specific `transform`, and `writeTo`
 * delegating to `defaultWriteMemoriesToOrchestrator` (issue #2794).
 */
export function defineFileImporterAdapter<Parsed>(
  definition: FileImporterDefinition<Parsed>,
): ImporterAdapter<Parsed> {
  return {
    name: definition.name,
    sourceLabel: definition.sourceLabel,
    parse(input, options) {
      return definition.parse(input, {
        ...(options?.strict !== undefined ? { strict: options.strict } : {}),
        ...(options?.filePath !== undefined ? { filePath: options.filePath } : {}),
      });
    },
    transform: (parsed, options) => definition.transform(parsed, options),
    writeTo: defaultWriteMemoriesToOrchestrator,
  };
}

/**
 * Meetings CLI runner (issue #1900) — one implementation shared by every CLI
 * host (`remnic meetings ...` and `openclaw engram meetings ...`) so the
 * surfaces never fork (same rule as the wearables/recall-explain runners).
 *
 * Flag validation is strict: value-taking flags require a value, unknown flags
 * error with the valid list, malformed dates/ids reject loudly, and a missing
 * record is a caller error — all `MeetingsInputError` → exit code 1 (CLAUDE.md
 * rules 14 + 51). Backend faults bubble to the host's 500 handler.
 */

import { isValidTranscriptDate } from "../wearables/day-store.js";
import type { MeetingsBuilder, MeetingsDayBuildSummary } from "./build.js";
import { MeetingsInputError } from "./errors.js";
import { meetingIdDate, type MeetingRecordStore, type MeetingRecordSummary } from "./store.js";
import type { MeetingsConfig } from "./types.js";

export interface MeetingsCliIo {
  stdout: { write(chunk: string): unknown };
  stderr: { write(chunk: string): unknown };
}

/** Everything the runner drives. Injected so tests wire a store + builder over
 *  synthetic fixtures with no real filesystem. */
export interface MeetingsCliDeps {
  store: MeetingRecordStore;
  builder: MeetingsBuilder;
  /**
   * Meetings config, so list/show honor `meetings.enabled`. The runner reads the
   * store directly (not through an enabled-aware service), so without this gate a
   * disabled subsystem would still expose stored records via list/show even
   * though `build` refuses. Disabled => no exposure (issue #1900).
   */
  config: MeetingsConfig;
}

const USAGE = `Usage: meetings <command> [options]

Commands:
  list [--date <YYYY-MM-DD>]     List meeting records (all days, or one day)
  show <meeting-id>              Print a stored meeting record
  build --date <YYYY-MM-DD>      Detect + fuse + store the day's meetings

Add --json to list/build for machine-readable output.
`;

const VALUE_FLAGS: Record<string, true> = { "--date": true };
const BOOLEAN_FLAGS: Record<string, true> = { "--json": true };

interface ParsedFlags {
  flags: Map<string, string | true>;
  positional: string[];
}

function parseFlags(args: string[]): ParsedFlags {
  const flags = new Map<string, string | true>();
  const positional: string[] = [];
  for (let i = 0; i < args.length; i++) {
    const arg = args[i]!;
    if (!arg.startsWith("--")) {
      positional.push(arg);
      continue;
    }
    if (VALUE_FLAGS[arg] === true) {
      const value = args[i + 1];
      if (value === undefined || value.startsWith("--")) {
        throw new MeetingsInputError(`flag ${arg} requires a value`);
      }
      flags.set(arg, value);
      i++;
      continue;
    }
    if (BOOLEAN_FLAGS[arg] === true) {
      flags.set(arg, true);
      continue;
    }
    const known = [...Object.keys(VALUE_FLAGS), ...Object.keys(BOOLEAN_FLAGS)].sort().join(", ");
    throw new MeetingsInputError(`unknown flag ${arg} (valid: ${known})`);
  }
  return { flags, positional };
}

function requireDate(parsed: ParsedFlags): string {
  const value = parsed.flags.get("--date");
  if (typeof value !== "string") {
    throw new MeetingsInputError("--date <YYYY-MM-DD> is required");
  }
  if (!isValidTranscriptDate(value)) {
    throw new MeetingsInputError(`--date must be a real YYYY-MM-DD; got '${value}'`);
  }
  return value;
}

function renderSummaryLine(summary: MeetingRecordSummary): string {
  const attendees = summary.attendees.length > 0 ? summary.attendees.join(", ") : "(none)";
  const sources = summary.sources.length > 0 ? summary.sources.join("+") : "(none)";
  const corroborated =
    summary.corroboratedBy.length > 0 ? ` corroborated=${summary.corroboratedBy.join("+")}` : "";
  return (
    `  ${summary.id}  ${summary.startUtc}–${summary.endUtc}  [${summary.detectionSource}]` +
    ` sources=${sources}${corroborated} attendees=${attendees} snapshots=${summary.snapshotCount}`
  );
}

function renderBuildSummary(summary: MeetingsDayBuildSummary): string {
  if (!summary.enabled) {
    return `meetings disabled — set meetings.enabled=true to build (${summary.date})`;
  }
  const lines = [
    `${summary.date}: ${summary.meetings.length} meeting${summary.meetings.length === 1 ? "" : "s"} ` +
      `(${summary.built} written, ${summary.skipped} unchanged, ${summary.removed.length} removed)`,
  ];
  for (const meeting of summary.meetings) {
    const sources = meeting.sources.length > 0 ? meeting.sources.join("+") : "(none)";
    lines.push(
      `  ${meeting.id}  ${meeting.startUtc}–${meeting.endUtc}  [${meeting.detectionSource}]` +
        ` sources=${sources} snapshots=${meeting.snapshotCount} ${meeting.written ? "written" : "unchanged"}`,
    );
  }
  if (summary.reindexWarning !== undefined) {
    lines.push(`  warning: ${summary.reindexWarning}`);
  }
  if (summary.memoryWarning !== undefined) {
    lines.push(`  warning: ${summary.memoryWarning}`);
  }
  return lines.join("\n");
}

/** Run a meetings CLI command. Returns a process exit code; all output via `io`. */
export async function runMeetingsCliCommand(
  deps: MeetingsCliDeps,
  args: string[],
  io: MeetingsCliIo,
): Promise<number> {
  const [command, ...rest] = args;
  try {
    switch (command) {
      case undefined:
      case "help":
      case "--help": {
        io.stdout.write(USAGE);
        return command === undefined ? 1 : 0;
      }
      case "list": {
        const parsed = parseFlags(rest);
        const json = parsed.flags.has("--json");
        const dateFlag = parsed.flags.get("--date");
        // Validate --date regardless of enabled state: a malformed --date is a
        // caller error on every path, so it must reject before the disabled
        // list short-circuit returns an empty result.
        if (typeof dateFlag === "string" && !isValidTranscriptDate(dateFlag)) {
          throw new MeetingsInputError(`--date must be a real YYYY-MM-DD; got '${dateFlag}'`);
        }
        if (!deps.config.enabled) {
          if (json) {
            io.stdout.write(typeof dateFlag === "string" ? "[]\n" : "{}\n");
          } else {
            io.stdout.write("meetings disabled — set meetings.enabled=true to build\n");
          }
          return 0;
        }
        if (typeof dateFlag === "string") {
          const summaries = await deps.store.listMeetingSummaries(dateFlag);
          if (json) {
            io.stdout.write(`${JSON.stringify(summaries, null, 2)}\n`);
            return 0;
          }
          if (summaries.length === 0) {
            io.stdout.write(`No meetings for ${dateFlag}.\n`);
            return 0;
          }
          io.stdout.write(`${dateFlag}:\n`);
          for (const summary of summaries) io.stdout.write(`${renderSummaryLine(summary)}\n`);
          return 0;
        }
        const dates = await deps.store.listMeetingDates();
        if (json) {
          const out: Record<string, MeetingRecordSummary[]> = {};
          for (const date of dates) out[date] = await deps.store.listMeetingSummaries(date);
          io.stdout.write(`${JSON.stringify(out, null, 2)}\n`);
          return 0;
        }
        if (dates.length === 0) {
          io.stdout.write("No meetings recorded.\n");
          return 0;
        }
        for (const date of dates) {
          const summaries = await deps.store.listMeetingSummaries(date);
          io.stdout.write(`${date}:\n`);
          for (const summary of summaries) io.stdout.write(`${renderSummaryLine(summary)}\n`);
        }
        return 0;
      }
      case "show": {
        const parsed = parseFlags(rest);
        if (!deps.config.enabled) {
          io.stdout.write("meetings disabled — set meetings.enabled=true to build\n");
          return 0;
        }
        const id = parsed.positional[0];
        if (id === undefined) {
          throw new MeetingsInputError("show requires a meeting id");
        }
        const date = meetingIdDate(id);
        if (date === null) {
          throw new MeetingsInputError(`invalid meeting id '${id}' — expected mtg-YYYY-MM-DD-<hash>`);
        }
        // meetingIdDate matches the id's SHAPE; a syntactically valid but
        // impossible calendar date (e.g. mtg-2026-13-40-...) must surface as a
        // clean input error, not a 500 from the store's path validator.
        if (!isValidTranscriptDate(date)) {
          throw new MeetingsInputError(`invalid meeting id '${id}' — '${date}' is not a real calendar date`);
        }
        const raw = await deps.store.readMeetingRecord(date, id);
        if (raw === null) {
          throw new MeetingsInputError(`meeting '${id}' not found`);
        }
        io.stdout.write(raw.endsWith("\n") ? raw : `${raw}\n`);
        return 0;
      }
      case "build": {
        const parsed = parseFlags(rest);
        const date = requireDate(parsed);
        const summary = await deps.builder.buildDay(date);
        if (parsed.flags.has("--json")) {
          io.stdout.write(`${JSON.stringify(summary, null, 2)}\n`);
          return 0;
        }
        io.stdout.write(`${renderBuildSummary(summary)}\n`);
        return 0;
      }
      default:
        throw new MeetingsInputError(`unknown meetings command '${command}'\n\n${USAGE}`);
    }
  } catch (err) {
    if (err instanceof MeetingsInputError) {
      io.stderr.write(`meetings: ${err.message}\n`);
      return 1;
    }
    throw err;
  }
}

import type { Dirent } from "node:fs";
import { appendFile, mkdir, readdir, rm } from "node:fs/promises";
import path from "node:path";

import type { RecallContextDegradation } from "./recall-context-composition.js";

export interface RecallAuditEntry {
  ts: string;
  sessionKey: string;
  agentId: string;
  trigger: string;
  queryText: string;
  candidateMemoryIds: string[];
  summary: string | null;
  injectedChars: number;
  toggleState: "enabled" | "disabled-primary" | "disabled-secondary";
  latencyMs?: number;
  plannerMode?: string;
  requestedMode?: string;
  fallbackUsed?: boolean;
  /** Injected-context degradation (#2972). Absent on a healthy recall. */
  degradation?: RecallContextDegradation;
}

function formatIsoDate(ts: string): string {
  const normalized = new Date(ts);
  if (Number.isNaN(normalized.getTime())) {
    return new Date().toISOString().slice(0, 10);
  }
  return normalized.toISOString().slice(0, 10);
}

export function buildRecallAuditPath(rootDir: string, ts: string, sessionKey: string): string {
  const safeSessionKey = encodeURIComponent(sessionKey);
  return path.join(rootDir, "transcripts", formatIsoDate(ts), `${safeSessionKey}.jsonl`);
}

export async function appendRecallAuditEntry(
  rootDir: string,
  entry: RecallAuditEntry,
): Promise<string> {
  const filePath = buildRecallAuditPath(rootDir, entry.ts, entry.sessionKey);
  await mkdir(path.dirname(filePath), { recursive: true });
  await appendFile(filePath, `${JSON.stringify(entry)}\n`, "utf8");
  return filePath;
}

export async function pruneRecallAuditEntries(
  rootDir: string,
  retentionDays: number,
  now: Date = new Date(),
): Promise<string[]> {
  const transcriptsDir = path.join(rootDir, "transcripts");
  const removed: string[] = [];
  const cutoff = new Date(now);
  cutoff.setUTCHours(0, 0, 0, 0);
  cutoff.setUTCDate(cutoff.getUTCDate() - Math.max(1, Math.floor(retentionDays)));
  let entries: Dirent[];
  try {
    entries = await readdir(transcriptsDir, { withFileTypes: true });
  } catch {
    return removed;
  }

  for (const entry of entries) {
    if (!entry.isDirectory()) continue;
    if (!/^\d{4}-\d{2}-\d{2}$/.test(entry.name)) continue;
    const day = new Date(`${entry.name}T00:00:00.000Z`);
    if (Number.isNaN(day.getTime()) || day >= cutoff) continue;
    const dirPath = path.join(transcriptsDir, entry.name);
    await rm(dirPath, { recursive: true, force: true });
    removed.push(dirPath);
  }

  return removed;
}

import fs from "node:fs";
import path from "node:path";

import { MAGIC_BYTES } from "../secure-store/secure-fs.js";
import { OKF_RESERVED_BASENAMES } from "./type-mapping.js";

export interface OkfLintFinding {
  file: string;
  code: "missing_frontmatter" | "missing_type" | "empty_type" | "reserved_basename" | "skipped_encrypted";
  message: string;
}

export interface OkfLintResult {
  ok: boolean;
  scanned: number;
  findings: OkfLintFinding[];
}

function isEncryptedBlob(raw: string): boolean {
  // secure-store writes a binary envelope starting with MAGIC_BYTES at offset
  // 0 — match that fixed position, never a substring anywhere in the file.
  return raw.startsWith(MAGIC_BYTES.toString("ascii"));
}

function hasFrontmatter(raw: string): boolean {
  return raw.startsWith("---\n") || raw.startsWith("---\r\n");
}

function readType(raw: string): string | undefined {
  const close = raw.indexOf("\n---", 4);
  if (close === -1) return undefined;
  const block = raw.slice(4, close);
  const match = /^type:[ \t]*(.*)$/m.exec(block);
  if (!match) return undefined;
  const value = match[1]!.trim().replace(/^["']|["']$/g, "");
  return value;
}

function walkMarkdown(root: string, out: string[]): void {
  let entries: fs.Dirent[];
  try {
    entries = fs.readdirSync(root, { withFileTypes: true });
  } catch {
    return;
  }
  for (const entry of entries.sort((a, b) => a.name.localeCompare(b.name))) {
    if (entry.name === "state" || entry.name === ".git") continue;
    const full = path.join(root, entry.name);
    let stat: fs.Stats;
    try {
      stat = fs.lstatSync(full);
    } catch {
      continue;
    }
    if (stat.isSymbolicLink()) continue;
    if (stat.isDirectory()) {
      walkMarkdown(full, out);
      continue;
    }
    if (stat.isFile() && entry.name.endsWith(".md")) out.push(full);
  }
}

export function lintOkfDir(memoryDir: string): OkfLintResult {
  const files: string[] = [];
  walkMarkdown(memoryDir, files);
  const findings: OkfLintFinding[] = [];
  for (const file of files) {
    const rel = path.relative(memoryDir, file);
    const base = path.basename(file);
    if (OKF_RESERVED_BASENAMES[base] === true) {
      findings.push({
        file: rel,
        code: "reserved_basename",
        message: `${base} is reserved by OKF §6/§7`,
      });
      continue;
    }
    let raw: string;
    try {
      raw = fs.readFileSync(file, "utf8");
    } catch {
      continue;
    }
    if (isEncryptedBlob(raw)) {
      findings.push({
        file: rel,
        code: "skipped_encrypted",
        message: "skipped (encrypted)",
      });
      continue;
    }
    if (!hasFrontmatter(raw)) {
      findings.push({
        file: rel,
        code: "missing_frontmatter",
        message: "missing YAML frontmatter",
      });
      continue;
    }
    const type = readType(raw);
    if (type === undefined) {
      findings.push({ file: rel, code: "missing_type", message: "missing type" });
    } else if (type.length === 0) {
      findings.push({ file: rel, code: "empty_type", message: "empty type" });
    }
  }
  const actionable = findings.filter((f) => f.code !== "skipped_encrypted");
  return { ok: actionable.length === 0, scanned: files.length, findings };
}

import fs from "node:fs";
import path from "node:path";

import { lintOkfDir } from "./lint.js";
import { okfTypeForCategory } from "./type-mapping.js";

export interface OkfSweepResult {
  scanned: number;
  written: number;
}

function insertType(raw: string, type: string): string | null {
  const crlf = raw.startsWith("---\r\n");
  if (!crlf && !raw.startsWith("---\n")) return null;
  const lines = raw.split("\n");
  let close = -1;
  for (let index = 1; index < lines.length; index += 1) {
    const line = lines[index]!;
    if (line === "---" || line === "---\r" || line === "...") {
      close = index;
      break;
    }
  }
  if (close === -1) return null;
  const block = lines.slice(1, close);
  const categoryLine = block.find((line) => line.startsWith("category:"));
  const category = categoryLine
    ? categoryLine.slice("category:".length).trim().replace(/^["']|["']$/g, "")
    : "fact";
  const resolved = type || okfTypeForCategory(category);
  const typeIndex = block.findIndex((line) => line.startsWith("type:"));
  if (typeIndex === -1) {
    block.push(`type: ${resolved}${crlf ? "\r" : ""}`);
  } else {
    const current = block[typeIndex]!;
    const bare = current.endsWith("\r") ? current.slice(0, -1) : current;
    const value = bare.slice("type:".length).trim().replace(/^["']|["']$/g, "");
    if (value !== "") return null;
    block[typeIndex] = `type: ${resolved}${current.endsWith("\r") ? "\r" : ""}`;
  }
  return [lines[0], ...block, ...lines.slice(close)].join("\n");
}

export function runOkfConformanceSweep(
  memoryDir: string,
  options: { sweepEnabled: boolean; conformanceEnabled: boolean },
): OkfSweepResult {
  if (!options.sweepEnabled || !options.conformanceEnabled) {
    return { scanned: 0, written: 0 };
  }
  const lint = lintOkfDir(memoryDir);
  let written = 0;
  for (const finding of lint.findings) {
    if (finding.code !== "missing_type" && finding.code !== "empty_type") continue;
    const file = path.join(memoryDir, finding.file);
    const raw = fs.readFileSync(file, "utf8");
    const next = insertType(raw, "");
    if (next === null || next === raw) continue;
    fs.writeFileSync(file, next);
    written += 1;
  }
  return { scanned: lint.scanned, written };
}

import { readdirSync, readFileSync, statSync, unlinkSync } from "node:fs";
import path from "node:path";

import { writeFileAtomically } from "../maintenance/atomic-file.js";
import { normalizeProjectionPreview } from "../memory-projection-format.js";
import { OKF_RESERVED_BASENAMES } from "./type-mapping.js";

export const OKF_INDEX_MARKER = "<!-- remnic-okf-index -->";

const INDEXED_ROOTS = ["entities", "facts", "corrections", "summaries"] as const;

export interface OkfIndexReport {
  written: string[];
  removed: string[];
}

export async function runOkfIndexMaintenance(
  memoryDir: string,
  enabled: boolean,
): Promise<OkfIndexReport> {
  const written: string[] = [];
  const removed: string[] = [];
  const dirs = collectIndexDirs(memoryDir);
  for (const dir of dirs) {
    const indexPath = path.join(dir, "index.md");
    if (!enabled) {
      if (isGeneratedIndex(indexPath)) {
        unlinkSync(indexPath);
        removed.push(indexPath);
      }
      continue;
    }
    const next = renderIndex(dir);
    if (next === null) continue;
    if (isUnchangedGenerated(indexPath, next)) continue;
    await writeFileAtomically(indexPath, next);
    written.push(indexPath);
  }
  return { written, removed };
}

function collectIndexDirs(memoryDir: string): string[] {
  const dirs = [memoryDir];
  for (const root of INDEXED_ROOTS) {
    const full = path.join(memoryDir, root);
    if (!isDir(full)) continue;
    dirs.push(full);
    if (root === "facts") {
      for (const entry of safeList(full)) {
        const child = path.join(full, entry);
        if (isDir(child) && /^\d{4}-\d{2}-\d{2}$/.test(entry)) dirs.push(child);
      }
    }
  }
  return dirs;
}

function renderIndex(dir: string): string | null {
  const entries = safeList(dir)
    .filter((name) => name.endsWith(".md") && OKF_RESERVED_BASENAMES[name] !== true)
    .sort((a, b) => a.localeCompare(b));
  if (entries.length === 0) return null;
  const lines = [OKF_INDEX_MARKER, "", `# ${path.basename(dir)}`, ""];
  for (const name of entries) {
    const preview = previewFile(path.join(dir, name));
    lines.push(`* [${titleFrom(name, preview)}](${name}) - ${preview}`);
  }
  lines.push("");
  return lines.join("\n");
}

function previewFile(filePath: string): string {
  try {
    return normalizeProjectionPreview(readFileSync(filePath, "utf8"), 120);
  } catch {
    return "";
  }
}

function titleFrom(name: string, preview: string): string {
  return preview.split(" ").slice(0, 8).join(" ") || name.replace(/\.md$/, "");
}

function isGeneratedIndex(filePath: string): boolean {
  try {
    return readFileSync(filePath, "utf8").includes(OKF_INDEX_MARKER);
  } catch {
    return false;
  }
}

function isUnchangedGenerated(filePath: string, next: string): boolean {
  try {
    return readFileSync(filePath, "utf8") === next;
  } catch {
    return false;
  }
}

function isDir(dir: string): boolean {
  try {
    return statSync(dir).isDirectory();
  } catch {
    return false;
  }
}

function safeList(dir: string): string[] {
  try {
    return readdirSync(dir);
  } catch {
    return [];
  }
}

/**
 * Issue #2345 — internal contracts, config bounds, digests, and validators for
 * the privacy-safe action-to-outcome trajectory evaluator.
 *
 * Internal module: never re-exported from the package root by itself. The
 * public surface is `eval-trajectory.ts` (builder) and `eval-trajectory-store.ts`
 * (validation, persistence, promotion gate). Keeping this layer separate holds
 * every file under the #1995 new-file ratchet cap while preserving one
 * subsystem.
 */

import { createHash } from "node:crypto";
import type { MemoryActionOutcome, MemoryActionPolicyDecision, MemoryActionType } from "./types.js";

// ---------------------------------------------------------------------------
// Constants and bounded config
// ---------------------------------------------------------------------------

export const EVAL_TRAJECTORY_REPORT_SCHEMA_VERSION = 1;

/** Default delayed-outcome window: 7 days, half-open `actionAt < outcomeAt < actionAt + window`. */
export const DEFAULT_EVAL_TRAJECTORY_OUTCOME_WINDOW_MS = 604_800_000;
/** Default allowed clock skew for input timestamps beyond `asOf`. */
export const DEFAULT_EVAL_TRAJECTORY_MAX_FUTURE_SKEW_MS = 300_000;
/** Default cap on emitted rows per report. */
export const DEFAULT_EVAL_TRAJECTORY_MAX_ROWS = 5_000;
export const MAX_EVAL_TRAJECTORY_ROWS_LIMIT = 50_000;
/** Default reader expiry: a report older than 30 days fails the checked read. */
export const DEFAULT_EVAL_TRAJECTORY_REPORT_MAX_AGE_MS = 2_592_000_000;

export interface EvalTrajectoryWeights {
  task: number;
  context: number;
  trust: number;
  stale: number;
}

export const DEFAULT_EVAL_TRAJECTORY_WEIGHTS: Readonly<EvalTrajectoryWeights> = Object.freeze({
  task: 1,
  context: 0.25,
  trust: 1,
  stale: 0.5,
});

const MEMORY_ACTION_TYPES: Record<string, true> = {
  store_episode: true,
  store_note: true,
  update_note: true,
  create_artifact: true,
  summarize_node: true,
  discard: true,
  link_graph: true,
};

/** Action types whose live execution is destructive (irreversible) for promotion gating. */
export const DESTRUCTIVE_ACTION_TYPES: Record<string, true> = { discard: true };

export const STALE_LIFECYCLE_STATES: Record<string, true> = {
  active: true,
  stale: true,
  archived: true,
  superseded: true,
};

export const STALE_OUTCOMES: Record<string, true> = {
  success: true,
  partial: true,
  failure: true,
  unknown: true,
};

/**
 * Fixed promotion thresholds for `deriveUnifiedMemoryPromotionReport`. These
 * are deliberately conservative named constants — #2348 owns application, and
 * any loosening must be a reviewed change, not a config knob.
 */
export const EVAL_TRAJECTORY_PROMOTION_THRESHOLDS = Object.freeze({
  minJoinedRows: 30,
  minReach: 0.5,
});

export interface EvalTrajectoryRunConfig {
  outcomeWindowMs: number;
  maxFutureSkewMs: number;
  weights: EvalTrajectoryWeights;
  maxRows: number;
}

export function resolveEvalTrajectoryRunConfig(partial?: Partial<EvalTrajectoryRunConfig>): EvalTrajectoryRunConfig {
  const source = partial ?? {};
  const weightsSource = source.weights ?? DEFAULT_EVAL_TRAJECTORY_WEIGHTS;
  const weights: EvalTrajectoryWeights = {
    task: Number(weightsSource.task),
    context: Number(weightsSource.context),
    trust: Number(weightsSource.trust),
    stale: Number(weightsSource.stale),
  };
  for (const [name, value] of Object.entries(weights)) {
    if (!Number.isFinite(value) || value < 0) {
      throw new Error(`eval trajectory weight '${name}' must be a finite non-negative number`);
    }
  }
  const totalWeight = weights.task + weights.context + weights.trust + weights.stale;
  if (!(totalWeight > 0)) {
    throw new Error("eval trajectory weights must have a positive total weight");
  }

  const outcomeWindowMs = Number(source.outcomeWindowMs ?? DEFAULT_EVAL_TRAJECTORY_OUTCOME_WINDOW_MS);
  if (!Number.isSafeInteger(outcomeWindowMs) || outcomeWindowMs <= 0) {
    throw new Error("outcomeWindowMs must be a positive integer");
  }
  const maxFutureSkewMs = Number(source.maxFutureSkewMs ?? DEFAULT_EVAL_TRAJECTORY_MAX_FUTURE_SKEW_MS);
  if (!Number.isSafeInteger(maxFutureSkewMs) || maxFutureSkewMs < 0) {
    throw new Error("maxFutureSkewMs must be a non-negative integer");
  }
  const maxRows = Number(source.maxRows ?? DEFAULT_EVAL_TRAJECTORY_MAX_ROWS);
  if (!Number.isSafeInteger(maxRows) || maxRows < 1 || maxRows > MAX_EVAL_TRAJECTORY_ROWS_LIMIT) {
    throw new Error(`maxRows must be an integer in [1, ${MAX_EVAL_TRAJECTORY_ROWS_LIMIT}]`);
  }
  return { outcomeWindowMs, maxFutureSkewMs, weights, maxRows };
}

