/**
 * Location boundary operations (issue #2047) — the five `location_*`
 * operations registered through the access boundary so MCP, HTTP, and any
 * batch transport share one validated dispatch. Handlers are thin: they run
 * the same `location/surfaces.ts` runners the CLI uses. Fleet-wide: location
 * config and day files are machine-level (no namespace scoping).
 */

import { z } from "zod";
import { defineOperation } from "../access-boundary.js";
import type { EngramAccessService } from "../access-service.js";
import { backfillMemoryStorage } from "./backfill.js";
import {
  runLocationBackfill,
  runLocationCheck,
  runLocationDay,
  runLocationStatus,
  runLocationSync,
  type LocationSurfaceDeps,
} from "./surfaces.js";

/** Zod shape shared by the location operations (null-for-absent tolerant). */
const dateField = z.union([z.string(), z.null()]).optional();
const daysField = z.union([z.number(), z.string(), z.null()]).optional();
const dryRunField = z.union([z.boolean(), z.null()]).optional();

function locationDeps(service: EngramAccessService): LocationSurfaceDeps {
  return {
    config: service.configRef.location,
    memoryDir: service.memoryDir,
    getMemoryStorage: () => backfillMemoryStorage(service.configRef),
  };
}

defineOperation({
  name: "location_status",
  description: "Location sync status (gates, providers, last sync, day counts).",
  fleetWide: true,
  schema: z.object({}).passthrough(),
  handler: async (_input, ctx) => ({
    result: await runLocationStatus(locationDeps(ctx.service)),
  }),
});

defineOperation({
  name: "location_check",
  description: "Probe every enabled location provider.",
  fleetWide: true,
  schema: z.object({}).passthrough(),
  handler: async (_input, ctx) => ({
    result: await runLocationCheck(locationDeps(ctx.service)),
  }),
});

defineOperation({
  name: "location_sync",
  description: "Sync location days (default window: syncDays ending yesterday).",
  fleetWide: true,
  schema: z.object({ date: dateField, days: daysField }).passthrough(),
  handler: async (input, ctx) => ({
    result: {
      days: await runLocationSync(locationDeps(ctx.service), {
        ...(input.date !== undefined && input.date !== null && input.date !== "" ? { endDate: input.date } : {}),
        ...(input.days !== undefined && input.days !== null && input.days !== "" ? { days: Number(input.days) } : {}),
      }),
    },
  }),
});

defineOperation({
  name: "location_backfill",
  description: "Sync an explicit historical day range (≤ 90 days) and re-tag overlapping memories (issue #2046).",
  fleetWide: true,
  schema: z.object({ from: dateField, to: dateField, dryRun: dryRunField }).passthrough(),
  handler: async (input, ctx) => ({
    result: await runLocationBackfill(locationDeps(ctx.service), {
      from: input.from ?? null,
      to: input.to ?? null,
      dryRun: input.dryRun === true,
    }),
  }),
});

defineOperation({
  name: "location_day",
  description: "Read one stored location day.",
  fleetWide: true,
  schema: z.object({ date: dateField }).passthrough(),
  handler: async (input, ctx) => ({
    result: await runLocationDay(locationDeps(ctx.service).memoryDir, input.date),
  }),
});

import { mkdirSync, rmSync } from "node:fs";
import { mkdtemp } from "node:fs/promises";
import path from "node:path";

import { parseOaiMemCitation } from "../citations.js";
import { inferMemoryStatus } from "../memory-lifecycle-ledger-utils.js";
import { normalizeProjectionPreview } from "../memory-projection-format.js";
import { lintOkfDir } from "../okf/lint.js";
import { okfTypeForMemory, OKF_PROFILE_TYPE } from "../okf/type-mapping.js";
import { resolveNamespaceChildRoot } from "../namespaces/path.js";
import {
  OKF_EXPORT_VERSION,
  publishBundle,
  renderFrontmatter,
  rejectSymlinkPath,
  writeBundleFile,
} from "../okf/render.js";
// Re-exported for the existing `@remnic/core/export-okf` consumers and tests
// (one public surface; the value itself now lives in okf/render.ts).
export { OKF_EXPORT_VERSION };
import { StorageManager } from "../storage.js";
import type { MemoryFile, MemoryLink, MemoryStatus } from "../types.js";

// Shared bundle mechanics (frontmatter, publish, symlink guard, file write)
// live in ../okf/render.ts — one source of truth for every OKF exporter.
export const OKF_LOG_TRUNCATION_MARKER = "<!-- okf-log-truncated -->";
export const DEFAULT_OKF_LOG_MAX_ENTRIES = 500;

const MEMORY_STATUSES: readonly MemoryStatus[] = [
  "active",
  "pending_review",
  "rejected",
  "quarantined",
  "superseded",
  "archived",
  "forgotten",
];

export interface ExportOkfOptions {
  memoryDir: string;
  /**
   * Optional namespace segment. Resolved here, once, through the shared
   * containment guard: both CLI entry points used to join the raw operator
   * value onto `memoryDir/namespaces`, so `--namespace ../../..` escaped the
   * namespace root and exported an arbitrary tree (rule 9 — one resolver, not
   * a per-caller guard).
   */
  namespace?: string;
  outDir: string;
  includeStatus?: readonly string[];
  includeCategories?: readonly string[];
  excludeTags?: readonly string[];
  includeProfile?: boolean;
  includeWearables?: boolean;
  includeLog?: boolean;
  logMaxEntries?: number;
  force?: boolean;
}

export interface ExportOkfResult {
  exported: number;
  excluded: number;
  byCategory: Record<string, number>;
  plaintextWarning: boolean;
}

export function parseIncludeStatus(raw: unknown): MemoryStatus[] {
  const values = splitCsv(raw);
  if (values.length === 0) return ["active"];
  const allowed = new Set<string>(MEMORY_STATUSES);
  for (const value of values) {
    if (!allowed.has(value)) {
      throw new Error(`invalid --include-status ${value}; allowed: ${MEMORY_STATUSES.join(", ")}`);
    }
  }
  return values as MemoryStatus[];
}

export async function exportOkfBundle(opts: ExportOkfOptions): Promise<ExportOkfResult> {
  const outDir = path.resolve(opts.outDir);
  rejectSymlinkPath(outDir);
  const namespace = (opts.namespace ?? "").trim();
  const memoryDir = namespace
    ? resolveNamespaceChildRoot(opts.memoryDir, namespace, "--namespace")
    : opts.memoryDir;
  const includeStatus = new Set(parseIncludeStatus(opts.includeStatus));
  const includeCategories = opts.includeCategories?.length ? new Set(opts.includeCategories) : null;
  const excludeTags = new Set(opts.excludeTags ?? []);
  const storage = new StorageManager(memoryDir);
  const memories = await storage.readAllMemories();
  const included: MemoryFile[] = [];
  let excluded = 0;
  for (const memory of memories) {
    const rel = toRel(memory.path, memoryDir);
    if (!opts.includeWearables && rel.startsWith("wearables/")) {
      excluded += 1;
      continue;
    }
    const status = inferMemoryStatus(memory.frontmatter, memory.path);
    if (!includeStatus.has(status)) {
      excluded += 1;
      continue;
    }
    if (includeCategories && !includeCategories.has(memory.frontmatter.category)) {
      excluded += 1;
      continue;
    }
    if ((memory.frontmatter.tags ?? []).some((tag) => excludeTags.has(tag))) {
      excluded += 1;
      continue;
    }
    included.push(memory);
  }
  included.sort((a, b) => toRel(a.path, memoryDir).localeCompare(toRel(b.path, memoryDir)));

  // Stage inside the destination's parent, not the OS temp dir: publishBundle
  // finishes with a rename, and a rename across filesystems fails with EXDEV
  // whenever --out lives on a different mount than /tmp.
  mkdirSync(path.dirname(outDir), { recursive: true });
  const staging = await mkdtemp(path.join(path.dirname(outDir), ".remnic-okf-export-"));
  const byCategory: Record<string, number> = {};
  const idToRel = new Map<string, string>();
  for (const memory of included) {
    const rel = toRel(memory.path, memoryDir);
    idToRel.set(memory.frontmatter.id, rel);
  }
  for (const memory of included) {
    const rel = toRel(memory.path, memoryDir);
    const rendered = renderMemory(memory, rel, idToRel);
    writeBundleFile(staging, rel, rendered);
    const category = memory.frontmatter.category;
    byCategory[category] = (byCategory[category] ?? 0) + 1;
  }

  if (opts.includeProfile) {
    try {
      const profile = await storage.readProfile();
      if (profile) {
        writeBundleFile(
          staging,
          "profile.md",
          renderFrontmatter({
            type: OKF_PROFILE_TYPE,
            title: "User Profile",
            timestamp: new Date(0).toISOString(),
          }) + profile.replace(/^\uFEFF/, ""),
        );
      }
    } catch {
      // Profile is optional even when requested.
    }
  }

  if (opts.includeLog) {
    const events = await storage.readAllMemoryLifecycleEvents();
    writeBundleFile(staging, "log.md", renderLog(events, idToRel, opts.logMaxEntries ?? DEFAULT_OKF_LOG_MAX_ENTRIES));
  }

  writeIndexes(staging, included, memoryDir);
  const lint = lintOkfDir(staging);
  const blocking = lint.findings.filter((f) => f.code !== "skipped_encrypted" && f.code !== "reserved_basename");
  if (blocking.length > 0) {
    rmSync(staging, { recursive: true, force: true });
    throw new Error(`OKF export failed lint: ${blocking.map((f) => `${f.file}: ${f.message}`).join("; ")}`);
  }

  publishBundle(staging, outDir, opts.force === true);
  return {
    exported: included.length,
    excluded,
    byCategory,
    plaintextWarning: true,
  };
}


function renderMemory(memory: MemoryFile, rel: string, idToRel: Map<string, string>): string {
  const fm = memory.frontmatter;
  const title = firstHeading(memory.content) ?? `${humanize(fm.category)} ${fm.created.slice(0, 10)}`;
  const type = fm.type ?? okfTypeForMemory(fm);
  const fields: Record<string, unknown> = {
    ...fm,
    type,
    title,
    description: normalizeProjectionPreview(memory.content),
    tags: fm.tags ?? [],
    timestamp: fm.updated,
  };
  if (fm.artifactType) fields.resource = rel;
  let body = memory.content.trim();
  const citation = parseOaiMemCitation(body);
  if (citation) {
    const start = body.indexOf("<oai-mem-citation>");
    const end = body.indexOf("</oai-mem-citation>");
    if (start >= 0 && end > start) {
      body = `${body.slice(0, start).trimEnd()}\n\n${body.slice(end + "</oai-mem-citation>".length).trimStart()}`.trim();
    }
    const lines = citation.entries.map((entry, index) => `${index + 1}. [${entry.path}](${entry.path})`);
    body = `${body}\n\n# Citations\n\n${lines.join("\n")}\n`;
  }
  const links = fm.links ?? [];
  if (links.length > 0) {
    body += `\n# Related\n\n${links.map((link) => renderRelated(link, idToRel)).join("\n")}\n`;
  }
  return renderFrontmatter(fields) + body + (body.endsWith("\n") ? "" : "\n");
}

function renderRelated(link: MemoryLink, idToRel: Map<string, string>): string {
  const target = idToRel.get(link.targetId) ?? link.targetId;
  const href = target.startsWith("/") ? target : `/${target}`;
  return `- ${link.linkType}: [${link.targetId}](${href})`;
}

function writeIndexes(root: string, memories: MemoryFile[], memoryDir: string): void {
  const groups = new Map<string, MemoryFile[]>();
  for (const memory of memories) {
    const rel = toRel(memory.path, memoryDir);
    const dir = path.posix.dirname(rel);
    const key = dir === "." ? "" : dir.split("/")[0] ?? "";
    const list = groups.get(key) ?? [];
    list.push(memory);
    groups.set(key, list);
  }
  const sections = [...groups.keys()].sort().map((key) => {
    const heading = key === "" ? "Root" : humanize(key);
    const lines = (groups.get(key) ?? [])
      .sort((a, b) => toRel(a.path, memoryDir).localeCompare(toRel(b.path, memoryDir)))
      .map((memory) => {
        const rel = toRel(memory.path, memoryDir);
        const title = firstHeading(memory.content) ?? memory.frontmatter.id;
        const description = normalizeProjectionPreview(memory.content);
        return `* [${title}](/${rel}) - ${description}`;
      });
    return `## ${heading}\n\n${lines.join("\n")}`;
  });
  writeBundleFile(root, "index.md", `---\nokf_version: "${OKF_EXPORT_VERSION}"\n---\n\n${sections.join("\n\n")}\n`);
}

function renderLog(
  events: Array<{ timestamp?: string; type?: string; action?: string; memoryId?: string }>,
  idToRel: Map<string, string>,
  maxEntries: number,
): string {
  const sorted = [...events].sort((a, b) => String(b.timestamp ?? "").localeCompare(String(a.timestamp ?? "")));
  const truncated = sorted.length > maxEntries;
  const kept = sorted.slice(0, maxEntries);
  const byDay = new Map<string, typeof kept>();
  for (const event of kept) {
    const day = String(event.timestamp ?? "").slice(0, 10) || "unknown";
    const list = byDay.get(day) ?? [];
    list.push(event);
    byDay.set(day, list);
  }
  const days = [...byDay.keys()].sort((a, b) => b.localeCompare(a));
  const parts = ["# Log", ""];
  for (const day of days) {
    parts.push(`## ${day}`, "");
    for (const event of byDay.get(day) ?? []) {
      const action = boldAction(event.type ?? event.action ?? "Update");
      const id = event.memoryId;
      const rel = id ? idToRel.get(id) : undefined;
      const target = rel ? `[${id}](/${rel})` : id ?? "";
      parts.push(`- **${action}** ${target}`.trimEnd());
    }
    parts.push("");
  }
  if (truncated) parts.push(OKF_LOG_TRUNCATION_MARKER, "");
  return `${parts.join("\n")}\n`;
}

function boldAction(raw: string): string {
  const lower = raw.toLowerCase();
  if (lower.includes("create") || lower.includes("add")) return "Creation";
  if (lower.includes("deprecat") || lower.includes("delete") || lower.includes("archiv")) return "Deprecation";
  return "Update";
}


export function firstHeading(content: string): string | undefined {
  for (const line of content.split("\n")) {
    // `\S` makes the capture boundary disjoint from `\s+`, so the regex
    // cannot backtrack across split points — `\s+(.+)` was superlinear on
    // whitespace-heavy lines (CodeQL js/polynomial-redos). `.` still excludes
    // \r\u2028\u2029, preserving the skip-line behavior on those lines.
    const match = /^#\s+(\S.*)$/.exec(line.trim());
    if (match) return match[1]!.trim();
  }
  return undefined;
}

function humanize(value: string): string {
  return value.replace(/[_-]/g, " ").replace(/\b\w/g, (ch) => ch.toUpperCase());
}



function splitCsv(raw: unknown): string[] {
  if (raw === undefined || raw === null || raw === "") return [];
  const parts = Array.isArray(raw) ? raw.map(String) : String(raw).split(",");
  return parts.map((part) => part.trim()).filter((part) => part.length > 0);
}

function toRel(abs: string, root: string): string {
  return path.relative(path.resolve(root), path.resolve(abs)).split(path.sep).join("/");
}

/**
 * LLM adapter for the chat engine (issue #1583).
 *
 * The adapter exposes the production {@link ChatLlmAdapter} interface so the
 * engine is decoupled from the routing chain.  Two implementations:
 *
 * - {@link createProductionChatLlmAdapter}: wraps the existing
 *   FallbackLlmClient / LocalLlmClient routing chain so local Ollama/vLLM
 *   models are fully supported (gotcha 1).  Memory chat must not require
 *   cloud.
 *
 * - {@link StubChatLlmAdapter}: test-only adapter that drives scripted
 *   tool-call sequences.  PR 1 tests use this to verify the engine loop,
 *   confirmation protocol, budget exhaustion, and citation guard without
 *   real LLM calls.
 */

import type { ChatLlmAdapter, ChatLlmMessage, ChatLlmResponse, ChatLlmToolCall, ChatToolSchema } from "./chat-types.js";

// ---------------------------------------------------------------------------
// Minimal LLM-client interface (duck-typed from FallbackLlmClient and
// LocalLlmClient — both expose chatCompletion returning {content}|null).
// ---------------------------------------------------------------------------

interface LlmLikeClient {
  chatCompletion(
    messages: Array<{ role: string; content: string }>,
    options?: { model?: string; signal?: AbortSignal; [k: string]: unknown },
  ): Promise<{ content: string; modelUsed?: string } | null>;
}

/**
 * Create a production LLM adapter from an existing routing-chain client
 * (FallbackLlmClient or LocalLlmClient).
 *
 * The adapter maps the chat engine's message format to the client's
 * chatCompletion signature, injects the tool schema as a system-level
 * instruction (OpenAI function-calling compat), and parses tool-call requests
 * from the model's response.
 */
export function createProductionChatLlmAdapter(
  client: LlmLikeClient,
): ChatLlmAdapter {
  return {
    async complete(
      messages: ChatLlmMessage[],
      options: { tools: ChatToolSchema[]; model?: string; signal?: AbortSignal },
    ): Promise<ChatLlmResponse | null> {
      // Build the tool-calling instruction appended to the system message.
      const toolInstruction = formatToolInstruction(options.tools);
      const mapped = messages.map((m) => {
        if (m.role === "system") {
          return { role: m.role, content: m.content + "\n\n" + toolInstruction };
        }
        // Normalize tool results to a provider-safe role. The underlying
        // chat-completion clients do not implement native tool-call envelopes,
        // so a bare role:"tool" (without tool_call_id) is rejected by
        // OpenAI/Anthropic/Ollama endpoints. Surface the result as a user
        // message so the follow-up LLM turn always succeeds (P1).
        if (m.role === "tool") {
          const tag = m.toolCallId ? `[tool:${m.toolCallId}]` : "[tool]";
          return { role: "user", content: `${tag} ${m.content}` };
        }
        return { role: m.role, content: m.content };
      });
      const result = await client.chatCompletion(mapped, {
        ...(options.model ? { model: options.model } : {}),
        ...(options.signal ? { signal: options.signal } : {}),
      });
      if (!result) return null;
      const toolCalls = parseToolCalls(result.content);
      return {
        content: stripToolCallJson(result.content, toolCalls),
        toolCalls,
      };
    },
  };
}

/**
 * Format the available tools as a function-calling instruction for the LLM.
 * Models that support native function-calling can ignore this; models that
 * don't (most local models) use it to emit structured tool calls.
 */
function formatToolInstruction(tools: ChatToolSchema[]): string {
  if (tools.length === 0) return "";
  const lines = [
    "## Available tools",
    "",
    "You may call the following tools by emitting a JSON block on its own line:",
    "```json",
    '{"tool": "<name>", "arguments": { ... }}',
    "```",
    "",
    "Call one tool at a time. After receiving the tool result, continue your",
    "reasoning or emit another tool call. When you have a final answer, reply",
    "with text only (no tool-call JSON).",
    "",
    "Tools:",
  ];
  for (const t of tools) {
    const params = JSON.stringify(t.function.parameters);
    lines.push(`- ${t.function.name}: ${t.function.description}`);
    lines.push(`  Parameters: ${params}`);
  }
  return lines.join("\n");
}

/**
 * Parse a tool-call JSON block from the model's response content.
 * Tolerates leading/trailing text and code fences.
 */
export function parseToolCalls(content: string): ChatLlmToolCall[] {
  const calls: ChatLlmToolCall[] = [];
  // Match ```json ... ``` blocks and bare JSON objects with "tool" key.
  const patterns = [
    /```json\s*\n([\s\S]*?)\n```/g,
    /```\s*\n([\s\S]*?)\n```/g,
  ];
  const candidates: string[] = [];
  for (const pattern of patterns) {
    let match: RegExpExecArray | null;
    while ((match = pattern.exec(content)) !== null) {
      candidates.push(match[1]);
    }
  }
  // Also try bare JSON lines.
  for (const line of content.split("\n")) {
    const trimmed = line.trim();
    if (trimmed.startsWith("{") && trimmed.includes('"tool"')) {
      candidates.push(trimmed);
    }
  }
  const seen = new Set<string>();
  for (const candidate of candidates) {
    try {
      const parsed = JSON.parse(candidate) as { tool?: string; arguments?: Record<string, unknown> };
      if (typeof parsed.tool === "string" && parsed.tool.length > 0) {
        const args = parsed.arguments ?? {};
        // De-duplicate: a fenced block and its inner bare line can both match.
        const key = parsed.tool + ":" + JSON.stringify(args);
        if (seen.has(key)) continue;
        seen.add(key);
        calls.push({
          id: `call_${calls.length + 1}`,
          name: parsed.tool,
          arguments: args,
        });
      }
    } catch {
      // Not valid JSON — skip.
    }
  }
  return calls;
}

/**
 * Remove tool-call JSON blocks from the content, leaving only prose.
 */
function stripToolCallJson(content: string, toolCalls: ChatLlmToolCall[]): string {
  if (toolCalls.length === 0) return content;
  let result = content;
  // Remove fenced blocks.
  result = result.replace(/```json\s*\n[\s\S]*?\n```/g, "");
  result = result.replace(/```\s*\n[\s\S]*?\n```/g, "");
  // Remove bare JSON tool-call lines.
  result = result
    .split("\n")
    .filter((line) => {
      const trimmed = line.trim();
      return !(trimmed.startsWith("{") && trimmed.includes('"tool"'));
    })
    .join("\n");
  return result.trim();
}

// ---------------------------------------------------------------------------
// Stub adapter — for tests (rule 33: production signature, scripted behaviour)
// ---------------------------------------------------------------------------

/**
 * A scripted step in the stub adapter.  Each step is consumed in order for
 * each LLM call; the last step repeats if the engine loops beyond the
 * script length.
 */
export interface StubLlmStep {
  content?: string;
  toolCalls?: Array<{ name: string; arguments: Record<string, unknown> }>;
}

export class StubChatLlmAdapter implements ChatLlmAdapter {
  private steps: StubLlmStep[];
  private callIndex = 0;

  constructor(steps: StubLlmStep[]) {
    this.steps = steps;
  }

  async complete(
    _messages: ChatLlmMessage[],
    _options: { tools: ChatToolSchema[]; model?: string; signal?: AbortSignal },
  ): Promise<ChatLlmResponse | null> {
    const step = this.steps[Math.min(this.callIndex, this.steps.length - 1)];
    this.callIndex++;
    const toolCalls: ChatLlmToolCall[] = (step.toolCalls ?? []).map((tc, i) => ({
      id: `call_${i + 1}`,
      name: tc.name,
      arguments: tc.arguments,
    }));
    return {
      content: step.content ?? "",
      toolCalls,
    };
  }

  /** Reset the call index (for test reuse). */
  reset(): void {
    this.callIndex = 0;
  }
}

/**
 * A stub adapter that always returns null (simulates LLM outage, rule 13).
 */
export class NullChatLlmAdapter implements ChatLlmAdapter {
  async complete(): Promise<null> {
    return null;
  }
}

/**
 * Production chat-tool executor (issue #1583).
 *
 * Each method is a thin adapter over the corresponding EngramAccessService
 * method — zero new business logic (rule 22).  The executor carries the
 * session's principal/namespace/sessionKey so every tool call flows through
 * access-service with the caller's identity (rule 42).
 *
 * Correction tools (correction_plan / correction_apply / memory_promote) are
 * stubbed behind the same interface until the Correction Contract (#1580)
 * merges.  The stub returns a clear not-available marker so the engine and
 * surfaces degrade gracefully.
 */

import type { EngramAccessService } from "../access-service.js";
import type { ChatToolExecutor } from "./chat-engine.js";

export interface ChatExecutorBindings {
  service: EngramAccessService;
  principal?: string;
  namespace?: string;
  sessionKey?: string;
}

/**
 * Create a production executor bound to the caller's identity.
 */
export function createChatExecutor(bindings: ChatExecutorBindings): ChatToolExecutor {
  const { service, principal, namespace, sessionKey } = bindings;

  return {
    async memorySearch(query: string, maxResults?: number): Promise<string> {
      const result = await service.memorySearch({
        query,
        ...(namespace ? { namespace } : {}),
        ...(maxResults !== undefined ? { maxResults } : {}),
        ...(principal ? { principal } : {}),
      });
      return JSON.stringify(result);
    },

    async memoryGet(memoryId: string): Promise<string> {
      const result = await service.memoryGet(memoryId, namespace, principal, sessionKey);
      return JSON.stringify(result);
    },

    async memoryTimeline(memoryId: string, limit?: number): Promise<string> {
      const result = await service.memoryTimeline(memoryId, namespace, limit ?? 200, principal);
      return JSON.stringify(result);
    },

    async recallExplain(query: string): Promise<string> {
      const result = await service.recallExplain({
        ...(sessionKey ? { sessionKey } : {}),
        ...(namespace ? { namespace } : {}),
        ...(principal ? { authenticatedPrincipal: principal } : {}),
        ...(query ? { query } : {}),
      });
      return JSON.stringify(result);
    },

    async entityGet(name: string): Promise<string> {
      const result = await service.entityGet(name, namespace, principal);
      return JSON.stringify(result);
    },

    async stats(): Promise<string> {
      const [profile, entities, questions] = await Promise.all([
        service.memoryProfile(namespace, principal),
        service.memoryEntitiesList(namespace, principal),
        service.memoryQuestions(namespace, principal),
      ]);
      return JSON.stringify({ profile, entities, questions });
    },

    async reviewList(runId?: string): Promise<string> {
      const result = await service.reviewQueue(runId, namespace, principal);
      return JSON.stringify(result);
    },

    async scopeInspect(): Promise<string> {
      return JSON.stringify({
        namespace: namespace ?? "default",
        principal: principal ?? "default",
        sessionKey: sessionKey ?? undefined,
      });
    },

    // ── Correction tools — stubbed until #1580 merges ──────────────────
    // When the Correction Contract lands, replace these stubs with calls to
    // the correction module's plan/apply interface.  The engine, CLI, and
    // MCP tool all consume this interface, so the stub-to-real swap is a
    // single-file change here.

    async correctionPlan(request: string): Promise<{ planId: string; preview: string }> {
      // Stub: the Correction Contract (#1580) is not yet merged.
      // Return a not-available marker that the engine surfaces gracefully.
      return {
        planId: `stub-${Date.now()}`,
        preview: `[Correction Contract (#1580) not yet available]\n\nRequested correction: "${request}"\n\nThe plan/apply pipeline is pending. Inspection tools are fully functional.`,
      };
    },

    async correctionApply(planId: string): Promise<string> {
      // Stub: no-op until #1580 merges.
      return JSON.stringify({
        applied: false,
        planId,
        reason: "Correction Contract (#1580) not yet available. No mutation was applied.",
      });
    },

    async memoryPromote(memoryId: string): Promise<string> {
      // Delegate to the existing memoryPromote service method if available.
      try {
        const serviceWithPromote = service as EngramAccessService & {
          memoryPromote?: (memoryId: string, namespace?: string, principal?: string) => Promise<unknown>;
        };
        if (typeof serviceWithPromote.memoryPromote === "function") {
          const result = await serviceWithPromote.memoryPromote(memoryId, namespace, principal);
          return JSON.stringify(result);
        }
      } catch {
        // Fall through to stub.
      }
      return JSON.stringify({
        promoted: false,
        memoryId,
        reason: "Memory promotion is not available in this build.",
      });
    },
  };
}

import type { IncomingMessage, ServerResponse } from "node:http";
import path from "node:path";

import { EngramAccessForbiddenError } from "../access-errors.js";
import type { EngramAccessService } from "../access-service.js";
import { enforceNamespaceAllowList, tokenCapabilityStore } from "../access-token-capabilities.js";
import type { WriteRateLimitReservation } from "../write-rate-limiter.js";
import { handleSupportPassportOwnerHttp } from "./access-http.js";
import { buildSupportPassportPublicRequestHandler } from "./public-http.js";

const SUPPORT_PASSPORT_QUOTA_LIMITED_WRITE_TOOLS = new Set([
  "engram.support_passport_draft_create",
  "remnic.support_passport_draft_create",
  "engram.support_passport_drafts_generate",
  "remnic.support_passport_drafts_generate",
  "engram.support_passport_card_replace",
  "remnic.support_passport_card_replace",
  "engram.support_passport_card_approve",
  "remnic.support_passport_card_approve",
  "engram.support_passport_card_reject",
  "remnic.support_passport_card_reject",
  "engram.support_passport_card_withdraw",
  "remnic.support_passport_card_withdraw",
  "engram.support_passport_grant_create",
  "remnic.support_passport_grant_create",
  "engram.support_passport_grant_revoke",
  "remnic.support_passport_grant_revoke",
]);
const SUPPORT_PASSPORT_ADMIN_CONSOLE_ASSETS = new Map<string, string>([
  ["what-helps-me.css", "text/css; charset=utf-8"],
  ["model.js", "application/javascript; charset=utf-8"],
  ["app.js", "application/javascript; charset=utf-8"],
]);

export abstract class SupportPassportAccessHttpBase {
  private supportPassportPublicHandler: ReturnType<typeof buildSupportPassportPublicRequestHandler> | undefined;
  protected abstract readonly service: EngramAccessService;
  protected abstract readonly adminConsolePublicDir: string;
  protected abstract resolveRequestPrincipal(req: IncomingMessage): string | undefined;
  protected abstract readJsonBody(req: IncomingMessage, maxBodyBytes?: number): Promise<Record<string, unknown>>;
  protected abstract respondJson(res: ServerResponse, status: number, payload: unknown): void;
  protected abstract reserveWriteRateLimitSlot(req?: IncomingMessage): WriteRateLimitReservation;
  protected abstract respondAdminConsoleShell(
    req: IncomingMessage,
    res: ServerResponse,
    pathname: string,
    relativePath?: string,
    allowPrefill?: boolean,
  ): Promise<void>;
  protected abstract respondStatic(res: ServerResponse, filePath: string, contentType: string): Promise<void>;

  protected handleSupportPassportOwnerRequest(
    req: IncomingMessage,
    res: ServerResponse,
    pathname: string,
    hasQuery: boolean,
    abortSignal: AbortSignal
  ): Promise<boolean> {
    return handleSupportPassportOwnerHttp({
      req,
      res,
      pathname,
      hasQuery,
      service: this.service,
      principal: this.resolveRequestPrincipal(req),
      abortSignal,
      readJsonBody: () => this.readJsonBody(req),
      respondJson: (status, payload) => {
        res.setHeader("cache-control", "private, no-store");
        res.setHeader("vary", "Authorization");
        this.respondJson(res, status, payload);
      },
      reserveWriteRateLimitSlot: () => this.reserveWriteRateLimitSlot(req),
    });
  }

  protected handleSupportPassportPublicRequest(req: IncomingMessage, res: ServerResponse): Promise<boolean> {
    this.supportPassportPublicHandler ??= buildSupportPassportPublicRequestHandler(this.service, {
      trustedProxyAddresses: this.service.configRef?.supportPassport?.trustedProxyAddresses ?? [],
    });
    return this.supportPassportPublicHandler(req, res, {
      authorized: false,
      tokenAuthorized: false,
    });
  }

  protected async enforceSupportPassportAuthorizationProbe(req: IncomingMessage): Promise<void> {
    const principal = this.resolveRequestPrincipal(req)?.trim();
    if (!principal) {
      throw new EngramAccessForbiddenError("A trusted principal is required for support passport access.");
    }
    const owner = await this.service.getWritableStorageForNamespace(undefined, principal);
    enforceNamespaceAllowList(
      tokenCapabilityStore.getStore(),
      owner.namespace,
      this.service.configRef.defaultNamespace
    );
  }

  protected isSupportPassportQuotaLimitedWriteTool(toolName: string): boolean {
    return SUPPORT_PASSPORT_QUOTA_LIMITED_WRITE_TOOLS.has(toolName);
  }

  protected async handleSupportPassportUi(
    req: IncomingMessage,
    res: ServerResponse,
    pathname: string
  ): Promise<boolean> {
    if (req.method !== "GET") return false;
    const isSupportPassportPath =
      pathname === "/remnic/ui/what-helps-me" ||
      pathname === "/engram/ui/what-helps-me" ||
      pathname.startsWith("/remnic/ui/what-helps-me/") ||
      pathname.startsWith("/engram/ui/what-helps-me/");
    if (!isSupportPassportPath) return false;
    if (!this.service.supportPassportEnabled) {
      this.respondJson(res, 404, { error: "not_found" });
      return true;
    }
    if (pathname === "/remnic/ui/what-helps-me" || pathname === "/engram/ui/what-helps-me") {
      const search = new URL(req.url ?? pathname, "http://placeholder").search;
      res.statusCode = 301;
      res.setHeader("location", `${pathname}/${search}`);
      res.end();
      return true;
    }
    if (pathname === "/remnic/ui/what-helps-me/" || pathname === "/engram/ui/what-helps-me/") {
      const helperRequest = new URL(req.url ?? pathname, "http://placeholder").searchParams.has("grant");
      res.setHeader("content-security-policy", "frame-ancestors 'none'");
      res.setHeader("x-frame-options", "DENY");
      await this.respondAdminConsoleShell(req, res, pathname, "what-helps-me/index.html", !helperRequest);
      return true;
    }
    const fileName = pathname.split("/").at(-1) ?? "";
    const assetType = SUPPORT_PASSPORT_ADMIN_CONSOLE_ASSETS.get(fileName);
    if (assetType && pathname.split("/").length === 5) {
      await this.respondStatic(res, path.join(this.adminConsolePublicDir, "what-helps-me", fileName), assetType);
      return true;
    }
    this.respondJson(res, 404, { error: "not_found" });
    return true;
  }
}

/**
 * Chat engine — the bounded tool-loop agent (issue #1583).
 *
 * Loop: user message → LLM (with tool schema) → execute tool calls → feed
 * results back → final reply.  Max `chat.maxToolCallsPerTurn` tool calls per
 * user turn; budget exhausted → reply with partial results + what was
 * skipped (rule 34 — never a silent stall).
 *
 * Confirmation protocol (the safety core): mutating tools
 * (correction_apply, memory_promote) are two-phase in the engine itself,
 * independent of the LLM's judgment.  The engine intercepts a mutation tool
 * call, checks the session's confirmedPlanIds set; absent → the engine
 * returns the plan preview to the user with a confirmation prompt; the
 * user's affirmative (exact-match: yes/y/apply/confirm — deterministic, not
 * LLM-interpreted) marks it confirmed for ONE apply.
 */

import { randomUUID } from "node:crypto";

import type {
  ChatLlmAdapter,
  ChatLlmMessage,
  ChatSessionState,
  ChatToolResult,
  ChatToolSchema,
  ChatTurnResult,
} from "./chat-types.js";
import { buildChatSystemPrompt } from "./chat-system-prompt.js";
import {
  buildChatToolSchemas,
  MUTATING_TOOLS,
  type ChatToolName,
} from "./chat-tools.js";

// ---------------------------------------------------------------------------
// Tool executor — delegates each tool to access-service (rule 22)
// ---------------------------------------------------------------------------

/**
 * The executor interface the engine calls for each tool.  Each implementation
 * is a thin adapter over the corresponding access-service method — zero new
 * business logic lives in the engine.
 */
export interface ChatToolExecutor {
  memorySearch(query: string, maxResults?: number): Promise<string>;
  memoryGet(memoryId: string): Promise<string>;
  memoryTimeline(memoryId: string, limit?: number): Promise<string>;
  recallExplain(query: string): Promise<string>;
  entityGet(name: string): Promise<string>;
  stats(): Promise<string>;
  reviewList(runId?: string): Promise<string>;
  scopeInspect(): Promise<string>;
  /**
   * Generate a correction plan.  Returns a JSON string with a planId and
   * a diff preview.  When the Correction Contract (#1580) is not merged,
   * this is a stub that returns a not-available marker.
   */
  correctionPlan(request: string): Promise<{ planId: string; preview: string }>;
  /**
   * Apply a correction plan.  Returns a JSON result string.
   */
  correctionApply(planId: string): Promise<string>;
  /**
   * Promote a memory's tier.  Returns a JSON result string.
   */
  memoryPromote(memoryId: string): Promise<string>;
}

// ---------------------------------------------------------------------------
// Engine options
// ---------------------------------------------------------------------------

export interface ChatEngineOptions {
  llm: ChatLlmAdapter;
  executor: ChatToolExecutor;
  maxToolCallsPerTurn: number;
  model?: string;
  /** Whether the Correction Contract (#1580) plan/apply is available. */
  correctionAvailable: boolean;
  /** Whether the scope resolver (#1494) is available. */
  scopeInspectAvailable: boolean;
}

// ---------------------------------------------------------------------------
// Confirmation keywords — deterministic, not LLM-interpreted
// ---------------------------------------------------------------------------

// Exact-match confirmations. Unrecognized text keeps the conservative
// no-apply default, so this stays a small fixed set (issue #2198).
const CONFIRMATION_KEYWORDS: Record<string, true> = {
  yes: true,
  y: true,
  apply: true,
  confirm: true,
  "はい": true, // Japanese
  "sí": true, // Spanish
  ja: true, // German/Dutch
  "نعم": true, // Arabic
};

export function isConfirmationMessage(text: string): boolean {
  return CONFIRMATION_KEYWORDS[text.trim().toLowerCase()] === true;
}

// ---------------------------------------------------------------------------
// Engine
// ---------------------------------------------------------------------------

export class ChatEngine {
  private readonly llm: ChatLlmAdapter;
  private readonly executor: ChatToolExecutor;
  private readonly maxToolCallsPerTurn: number;
  private readonly model?: string;
  private readonly correctionAvailable: boolean;
  private readonly scopeInspectAvailable: boolean;
  private readonly systemPrompt: string;
  private readonly toolSchemas: ChatToolSchema[];
  private readonly allowedToolNames: Set<string>;

  constructor(opts: ChatEngineOptions) {
    this.llm = opts.llm;
    this.executor = opts.executor;
    this.maxToolCallsPerTurn = opts.maxToolCallsPerTurn;
    this.model = opts.model;
    this.correctionAvailable = opts.correctionAvailable;
    this.scopeInspectAvailable = opts.scopeInspectAvailable;
    this.systemPrompt = buildChatSystemPrompt({
      correctionAvailable: opts.correctionAvailable,
    });
    this.toolSchemas = buildChatToolSchemas({
      correctionAvailable: opts.correctionAvailable,
      scopeInspectAvailable: opts.scopeInspectAvailable,
    });
    // Pre-compute the set of allowed tool names for fast lookup (cursor HIGH —
    // executeTool must not run a tool that's not in the active schema set).
    this.allowedToolNames = new Set(this.toolSchemas.map((t) => t.function.name));
  }

  /**
   * Process a single user message.  The session state is mutated in place
   * (confirmedPlanIds, pendingPlanId) — the caller persists the transcript.
   */
  async processMessage(
    userMessage: string,
    session: ChatSessionState,
  ): Promise<ChatTurnResult> {
    // ── Confirmation fast-path ──────────────────────────────────────────
    // If there is a pending plan and the user's message is an exact-match
    // confirmation keyword, mark the plan confirmed and apply it directly
    // (bypassing the LLM — deterministic, not LLM-interpreted).
    if (
      isConfirmationMessage(userMessage) &&
      this.correctionAvailable
    ) {
      // Confirm + apply a pending correction plan.
      if (session.pendingPlanId) {
        const planId = session.pendingPlanId;
        session.confirmedPlanIds.add(planId);
        session.pendingPlanId = undefined;
        try {
          const applyResult = await this.executor.correctionApply(planId);
          // Consume the one-time confirmation on success so a later
          // tool-loop correction_apply cannot re-apply the same plan id
          // (cursor Medium: stale confirm allowed re-apply).
          session.confirmedPlanIds.delete(planId);
          return {
            reply: `Correction applied.\n\n${applyResult}`,
            chatSessionId: session.id,
            ...(session.pendingPromotionId ? {} : {}),
          };
        } catch (err) {
          // Roll back: the plan was NOT applied — restore the pending state
          // so the user can retry (cursor HIGH OlACo).
          session.confirmedPlanIds.delete(planId);
          session.pendingPlanId = planId;
          const msg = err instanceof Error ? err.message : String(err);
          return {
            reply: "[error] Failed to apply the correction. Please try again or re-request the plan.",
            chatSessionId: session.id,
            error: msg,
          };
        }
      }
      // Confirm + apply a pending memory promotion.
      if (session.pendingPromotionId) {
        const memoryId = session.pendingPromotionId;
        session.pendingPromotionId = undefined;
        try {
          const promoteResult = await this.executor.memoryPromote(memoryId);
          return {
            reply: `Memory promoted.\n\n${promoteResult}`,
            chatSessionId: session.id,
          };
        } catch (err) {
          // Roll back: the promotion was NOT applied — restore pending state.
          session.pendingPromotionId = memoryId;
          const msg = err instanceof Error ? err.message : String(err);
          return {
            reply: "[error] Failed to promote the memory. Please try again.",
            chatSessionId: session.id,
            error: msg,
          };
        }
      }
    }

    // ── Normal tool-loop ────────────────────────────────────────────────
    // Build the transcript context, filtering out:
    //  - the system header (seq === 0)
    //  - internal state markers (pending_plan:/pending_promotion:/plan_applied:)
    //  - the last user entry if it matches userMessage (the caller already
    //    appended it to the transcript before calling processMessage — adding
    //    it again below would duplicate it in the prompt).
    const recentEntries = session.transcript
      .slice(-21)
      .filter((e) => e.role !== "system" || e.seq !== 0)
      .filter((e) => !(e.role === "system" && /^[a-z_]+:/.test(e.content)))
      .filter((e, _i, arr) => {
        // Drop the last user entry if it duplicates the current message.
        if (e.role === "user" && e.content === userMessage) {
          const lastUser = [...arr].reverse().find((x) => x.role === "user");
          return e !== lastUser;
        }
        return true;
      });
    const conversation: ChatLlmMessage[] = [
      { role: "system", content: this.systemPrompt },
      ...recentEntries.map((e) => ({
        role: e.role as "user" | "assistant" | "tool",
        content: e.content,
        ...(e.toolCallId ? { toolCallId: e.toolCallId } : {}),
      })),
      { role: "user", content: userMessage },
    ];

    let toolCallCount = 0;
    const skippedTools: string[] = [];
    let pendingPlan: { planId: string; preview: string } | undefined;

    for (;;) {
      let response;
      try {
        response = await this.llm.complete(conversation, {
          tools: this.toolSchemas,
          ...(this.model ? { model: this.model } : {}),
        });
      } catch (err) {
        const msg = err instanceof Error ? err.message : String(err);
        return {
          reply: "[error] The model request failed. Check your model configuration and retry.",
          chatSessionId: session.id,
          error: msg,
        };
      }

      // LLM outage (rule 13) — tagged error reply.
      if (!response) {
        return {
          reply: "[error] No LLM model is available. Configure a local or cloud model to use Remnic Chat.",
          chatSessionId: session.id,
          error: "no_llm_available",
        };
      }

      // No tool calls → final reply.
      if (response.toolCalls.length === 0) {
        // Citation guard: if the reply asserts memory content without tool
        // results in this turn, append a citation-missing warning.
        let reply = response.content;
        if (toolCallCount === 0 && looksLikeMemoryAssertion(reply)) {
          reply += "\n\n⚠️ The above assertion was not grounded in a tool result this turn. Please verify with memory_search or memory_get.";
        }
        return {
          reply,
          chatSessionId: session.id,
          ...(pendingPlan ? { pendingPlan } : {}),
          ...(skippedTools.length > 0 ? { skippedTools } : {}),
        };
      }

      // Push the assistant response content once for this LLM turn (not per
      // tool call — avoids duplicate assistant messages in the conversation).
      conversation.push({ role: "assistant", content: response.content });

      // Execute each tool call (budget-limited).
      for (const tc of response.toolCalls) {
        if (toolCallCount >= this.maxToolCallsPerTurn) {
          skippedTools.push(tc.name);
          continue;
        }
        toolCallCount++;

        // ── Tool-schema gate (cursor HIGH OlCjs — must run before mutating-tool
        // interception so disabled tools like correction_apply/memory_promote
        // are rejected before any confirmation flow or executor call).
        if (!this.allowedToolNames.has(tc.name)) {
          conversation.push({
            role: "tool",
            content: JSON.stringify({ error: `Tool '${tc.name}' is not available in this configuration.` }),
            toolCallId: tc.id,
          });
          continue;
        }

        // ── Confirmation protocol for mutating tools ──────────────────
        if (MUTATING_TOOLS.has(tc.name as ChatToolName)) {
          if (tc.name === "correction_apply") {
            const planId = typeof tc.arguments.planId === "string" ? tc.arguments.planId : "";
            if (!session.confirmedPlanIds.has(planId)) {
              // Not confirmed — return the plan preview for user confirmation.
              // The plan was generated by a prior correction_plan call; fetch it.
              try {
                const plan = await this.executor.correctionPlan(
                  `retrieve plan ${planId}`,
                );
                // Bind the REQUESTED planId so the confirmation fast-path applies
                // the exact plan shown (not an executor re-minted id).
                pendingPlan = { planId, preview: plan.preview };
                session.pendingPlanId = planId;
                conversation.push({
                  role: "tool",
                  content: JSON.stringify({
                    intercepted: true,
                    message: "This mutation requires confirmation. The plan preview has been shown to the user.",
                  }),
                  toolCallId: tc.id,
                });
                return {
                  reply: formatPlanPreview(plan.preview),
                  chatSessionId: session.id,
                  pendingPlan,
                };
              } catch {
                conversation.push({
                  role: "tool",
                  content: JSON.stringify({ error: "Plan not found or expired." }),
                  toolCallId: tc.id,
                });
                continue;
              }
            }
            // Confirmed — consume the one-time confirmation.
            session.confirmedPlanIds.delete(planId);
          }
        }

        // ── memory_promote confirmation (mutating tool) ─────────────────
        // memory_promote is NEVER executed directly in the tool loop — it can
        // only be applied via the confirmation fast-path at the top of
        // processMessage (cursor HIGH: prevent bypass via repeated tool calls).
        if (tc.name === "memory_promote" && this.correctionAvailable) {
          const memoryId = typeof tc.arguments.memoryId === "string" ? tc.arguments.memoryId : "";
          session.pendingPromotionId = memoryId;
          conversation.push({
            role: "tool",
            content: JSON.stringify({
              intercepted: true,
              message: `Memory promotion requires confirmation. Reply 'apply' to promote memory '${memoryId}'.`,
            }),
            toolCallId: tc.id,
          });
          return {
            reply: `I want to promote memory \`${memoryId}\`. Reply **apply** to confirm this promotion, or **cancel** to discard it.`,
            chatSessionId: session.id,
          };
        }

        // ── Execute the tool ───────────────────────────────────────────
        let result: ChatToolResult;
        try {
          result = await this.executeTool(tc.name, tc.arguments, session);
        } catch (err) {
          const msg = err instanceof Error ? err.message : String(err);
          result = { content: JSON.stringify({ error: msg }) };
        }

        // Feed the tool result back into the conversation.
        conversation.push({
          role: "tool",
          content: result.content,
          toolCallId: tc.id,
        });

        // If a correction_plan surfaced, track the pending plan.
        if (tc.name === "correction_plan" && this.correctionAvailable) {
          try {
            const parsed = JSON.parse(result.content) as { planId?: string; preview?: string };
            if (parsed.planId && parsed.preview) {
              pendingPlan = { planId: parsed.planId, preview: parsed.preview };
              session.pendingPlanId = parsed.planId;
            }
          } catch {
            // The plan result might be a stub — that's fine.
          }
        }
      }

      // If we hit the budget and there are still tool calls, report partial.
      if (skippedTools.length > 0) {
        // Ask the LLM for a final summary with what we have.
        conversation.push({
          role: "user",
          content: `[system] Tool budget exhausted (${this.maxToolCallsPerTurn} calls). ${skippedTools.length} tool(s) were skipped: ${skippedTools.join(", ")}. Please summarize what you found.`,
        });
        // One more LLM call for the summary, then we're done.
        let summaryResponse;
        try {
          summaryResponse = await this.llm.complete(conversation, {
            tools: [], // No more tools — force a text reply.
            ...(this.model ? { model: this.model } : {}),
          });
        } catch {
          // Budget-exhaustion summary is best-effort — don't mask the partial
          // results with a transport error (kilo review, Thread 16).
          summaryResponse = null;
        }
        const summaryText = summaryResponse?.content ?? "I reached my tool-call budget. Here is what I found so far, but some queries were skipped.";
        return {
          reply: summaryText,
          chatSessionId: session.id,
          ...(pendingPlan ? { pendingPlan } : {}),
          skippedTools,
        };
      }
    }
  }

  /**
   * Execute a single tool by name, delegating to the executor.
   */
  private async executeTool(
    name: string,
    args: Record<string, unknown>,
    _session: ChatSessionState,
  ): Promise<ChatToolResult> {
    switch (name as ChatToolName) {
      case "memory_search": {
        const query = typeof args.query === "string" ? args.query : "";
        const maxResults = typeof args.maxResults === "number" ? args.maxResults : undefined;
        return { content: await this.executor.memorySearch(query, maxResults) };
      }
      case "memory_get": {
        const memoryId = typeof args.memoryId === "string" ? args.memoryId : "";
        return { content: await this.executor.memoryGet(memoryId) };
      }
      case "memory_timeline": {
        const memoryId = typeof args.memoryId === "string" ? args.memoryId : "";
        const limit = typeof args.limit === "number" ? args.limit : undefined;
        return { content: await this.executor.memoryTimeline(memoryId, limit) };
      }
      case "recall_explain": {
        const query = typeof args.query === "string" ? args.query : "";
        return { content: await this.executor.recallExplain(query) };
      }
      case "entity_get": {
        const entityName = typeof args.name === "string" ? args.name : "";
        return { content: await this.executor.entityGet(entityName) };
      }
      case "stats": {
        return { content: await this.executor.stats() };
      }
      case "correction_plan": {
        const request = typeof args.request === "string" ? args.request : "";
        const plan = await this.executor.correctionPlan(request);
        return { content: JSON.stringify(plan) };
      }
      case "correction_apply": {
        const planId = typeof args.planId === "string" ? args.planId : "";
        return { content: await this.executor.correctionApply(planId) };
      }
      case "memory_promote": {
        const memoryId = typeof args.memoryId === "string" ? args.memoryId : "";
        return { content: await this.executor.memoryPromote(memoryId) };
      }
      case "review_list": {
        const runId = typeof args.runId === "string" ? args.runId : undefined;
        return { content: await this.executor.reviewList(runId) };
      }
      case "scope_inspect": {
        return { content: await this.executor.scopeInspect() };
      }
      default:
        return { content: JSON.stringify({ error: `Unknown tool: ${name}` }) };
    }
  }
}

