/**
 * Heuristic: does the reply look like it's asserting stored memory content
 * without citing a tool result?  This is intentionally simple — flag, don't
 * police perfectly (per the issue's pitfall note).
 */
function looksLikeMemoryAssertion(text: string): boolean {
  const lower = text.toLowerCase();
  // Phrases that indicate a memory assertion.
  const assertionPhrases = [
    "you remember",
    "i remember",
    "according to my memory",
    "your memory",
    "stored memory",
    "remnic remembers",
    "remnic knows",
  ];
  // Only flag if there's an assertion AND no citation marker.
  const hasAssertion = assertionPhrases.some((p) => lower.includes(p));
  const hasCitation = lower.includes("[id:") || lower.includes("memory id") || lower.includes("source:");
  return hasAssertion && !hasCitation;
}

/**
 * Format a plan preview for display to the user.
 */
function formatPlanPreview(preview: string): string {
  return [
    "Here is the correction plan I generated:",
    "",
    "```diff",
    preview,
    "```",
    "",
    "Reply **apply** to confirm and apply this correction.",
    "Reply **cancel** to discard it.",
  ].join("\n");
}

/**
 * Memory-store browse boundary operations (issue #2978).
 *
 * `memory_ls` / `memory_tree` / `memory_find` route MCP, HTTP, and CLI
 * dispatch through the shared validation + error-mapping layer
 * (access-boundary.ts) to the single `EngramAccessService.memoryStoreBrowse`
 * implementation. Sibling module so access-operations-batch.ts stays at its
 * ceiling seam (same layout as recall-navigation-operations.ts).
 */

import { z } from "zod";

import { defineOperation } from "./access-boundary.js";
import { EngramAccessInputError } from "./access-errors.js";
import type { BrowseVerb, MemoryStoreBrowseRequest } from "./memory-browse.js";

function strictSchema<T extends z.ZodRawShape>(shape: T): z.ZodType<Record<string, unknown>> {
  return z.preprocess(
    (data) => {
      if (data !== null && typeof data === "object" && !Array.isArray(data)) {
        return Object.fromEntries(Object.entries(data as Record<string, unknown>).filter(([, value]) => value !== null));
      }
      return data;
    },
    z.object(shape).passthrough(),
  ) as unknown as z.ZodType<Record<string, unknown>>;
}

function optStr(value: unknown): string | undefined {
  return typeof value === "string" ? value : undefined;
}

function optInt(value: unknown): number | undefined {
  if (typeof value === "number") return value;
  if (typeof value === "string" && Number.isFinite(Number(value))) return Number(value);
  return undefined;
}

function reqStr(value: unknown, field: string): string {
  if (typeof value !== "string" || value.trim().length === 0) {
    throw new EngramAccessInputError(`${field} is required`);
  }
  return value;
}

const verbShape = {
  namespace: z.string().optional(),
} as const;

function browseRequest(verb: BrowseVerb, input: Record<string, unknown>): MemoryStoreBrowseRequest {
  return {
    verb,
    ...(optStr(input.path) !== undefined ? { path: optStr(input.path) } : {}),
    ...(optInt(input.depth) !== undefined ? { depth: optInt(input.depth) } : {}),
    ...(optStr(input.pattern) !== undefined ? { pattern: optStr(input.pattern) } : {}),
    namespace: optStr(input.namespace),
  };
}

defineOperation({
  name: "memory_ls",
  description: "List the children of one store path in the caller's namespace: category dirs with counts, memory files with a one-line description.",
  schema: strictSchema({ ...verbShape, path: z.string().optional() }),
  handler: async (input, ctx) => ({
    result: await ctx.service.memoryStoreBrowse({ ...browseRequest("ls", input), authenticatedPrincipal: ctx.authenticatedPrincipal }),
  }),
});

defineOperation({
  name: "memory_tree",
  description: "Depth-limited tree of store paths under one directory, one-line descriptions, entry-capped.",
  schema: strictSchema({ ...verbShape, path: z.string().optional(), depth: z.union([z.number(), z.string()]).optional() }),
  handler: async (input, ctx) => ({
    result: await ctx.service.memoryStoreBrowse({ ...browseRequest("tree", input), authenticatedPrincipal: ctx.authenticatedPrincipal }),
  }),
});

defineOperation({
  name: "memory_find",
  description: "Deterministic name/path match (`*` glob or substring) over the caller's namespace store; semantic search stays memory_search.",
  schema: strictSchema({ ...verbShape, pattern: z.string() }),
  handler: async (input, ctx) => ({
    result: await ctx.service.memoryStoreBrowse({
      ...browseRequest("find", { ...input, pattern: reqStr(input.pattern, "pattern") }),
      authenticatedPrincipal: ctx.authenticatedPrincipal,
    }),
  }),
});

/**
 * Shared `timeline publish` implementation (issue #1985).
 *
 * Both CLI trees dispatch this one function: the host command group in
 * `cli/timeline-publish-commands.ts` and the standalone binary's shared
 * runner in `timeline/query.ts`. A documented command that exists on only
 * one tree is a defect — the shipped `@remnic/cli` binary must publish too.
 */
import { existsSync, readFileSync } from "node:fs";

import type { PluginConfig } from "../../types.js";
import { activityDateInTimezone, isValidActivityDate } from "../digest.js";
import { journalPath } from "../journal.js";
import { publishVaultNote, type VaultSectionPublish } from "../vault-publisher.js";

export interface TimelinePublishIo {
  stdout: { write(chunk: string): unknown };
  stderr: { write(chunk: string): unknown };
}

export interface TimelinePublishOptions {
  date?: unknown;
  week?: unknown;
  what?: unknown;
  dryRun?: unknown;
}

const AVAILABLE_KINDS = ["timeline"] as const;
const KNOWN_KINDS = ["timeline", "standup", "weekly", "locations"] as const;
const UNLANDED_REASONS: Record<string, string> = {
  standup: "the standup renderer lands with timeline phase 3",
  weekly: "the weekly review renderer lands with timeline phase 4",
  locations: "the location day renderer is not wired to publishing yet",
};

export function runTimelinePublishCli(
  config: PluginConfig,
  options: TimelinePublishOptions,
  io: TimelinePublishIo,
): number {
  const vault = config.activity?.timeline?.vault;

  if (options.week !== undefined) {
    io.stderr.write("--week is not available yet: the weekly review renderer lands with timeline phase 4.\n");
    return 1;
  }
  if (!vault || vault.enabled !== true) {
    io.stderr.write(
      "Vault publishing is disabled: set activity.timeline.vault.enabled=true and configure vaultPath first.\n",
    );
    return 1;
  }

  // An explicitly empty --date is invalid, not absent (issue #2917): ""
  // can never be a day, and silently falling back to today would publish
  // the wrong note. Only a missing --date means "today".
  if (options.date !== undefined && (typeof options.date !== "string" || options.date.length === 0)) {
    io.stderr.write(`Invalid --date ${JSON.stringify(options.date ?? "")}; expected YYYY-MM-DD.\n`);
    return 1;
  }
  // Timeline artifacts are grouped on the configured activity timezone's
  // calendar day, so "today" must be derived there — the host-local day
  // drifts by one near either timezone's midnight.
  const date =
    typeof options.date === "string" && options.date.length > 0
      ? options.date
      : activityDateInTimezone(new Date(), config.activity?.timezone ?? "UTC");
  if (!isValidActivityDate(date)) {
    io.stderr.write(`Invalid --date "${date}"; expected YYYY-MM-DD.\n`);
    return 1;
  }

  const requested = parseKinds(typeof options.what === "string" && options.what.length > 0 ? options.what : "timeline");
  if (typeof requested !== "string") {
    io.stderr.write(requested.error);
    return 1;
  }
  const kinds = requested.split(",");
  const sections: VaultSectionPublish[] = [];
  let notePathTemplate = vault.dailyNotePath;

  for (const kind of kinds) {
    if ((AVAILABLE_KINDS as readonly string[]).indexOf(kind) === -1) {
      io.stderr.write(`--what ${kind} is not available yet: ${UNLANDED_REASONS[kind] ?? "unknown kind"}.\n`);
      return 1;
    }
    const target = vault.publish[kind as "timeline"];
    if (target.enabled !== true) {
      io.stderr.write(`--what ${kind} is disabled: enable activity.timeline.vault.publish.${kind}.enabled.\n`);
      return 1;
    }
    // Honor the target's configured note file; config parsing already
    // rejects target="weekly" with an empty weeklyNotePath.
    notePathTemplate = target.target === "weekly" ? vault.weeklyNotePath : vault.dailyNotePath;
    const source = journalPath(config.memoryDir, date);
    if (!existsSync(source)) {
      io.stderr.write(
        `No timeline artifact for ${date}: run the journal recap generation first (${kind} target reads the persisted day recap).\n`,
      );
      return 1;
    }
    sections.push({ name: target.section, content: readFileSync(source, "utf8").trimEnd() });
  }

  const status = publishVaultNote({
    vaultPath: vault.vaultPath,
    notePathTemplate,
    date,
    sections,
    strategy: vault.sectionStrategy,
    insertUnderHeading: vault.insertUnderHeading.length > 0 ? vault.insertUnderHeading : undefined,
    createMissingNotes: vault.createMissingNotes,
    noteTemplate: vault.noteTemplate.length > 0 ? vault.noteTemplate : undefined,
    propertiesMode: vault.properties.mode,
    propertiesPrefix: vault.properties.prefix,
    dryRun: options.dryRun === true,
  });

  for (const row of status.results) {
    const label = row.outcome === "updated" && options.dryRun === true ? "would update" : row.outcome;
    io.stdout.write(`${label}  ${row.path}${row.reason ? `  (${row.reason})` : ""}\n`);
  }
  io.stdout.write(
    `updated=${status.counts.updated} unchanged=${status.counts.unchanged} skipped=${status.counts.skipped} error=${status.counts.error}\n`,
  );
  return status.hasError ? 1 : 0;
}

/**
 * `--what` is normalized to a comma-joined kind list. An empty normalized
 * list (`--what ','`) is rejected here rather than reaching the publisher,
 * which throws a RangeError on a zero-length section list.
 */
function parseKinds(raw: string): string | { error: string } {
  const kinds = raw
    .split(",")
    .map((part) => part.trim())
    .filter((part) => part.length > 0);
  for (const kind of kinds) {
    if ((KNOWN_KINDS as readonly string[]).indexOf(kind) === -1) {
      return { error: `Unknown --what kind "${kind}"; valid kinds are ${KNOWN_KINDS.join(", ")}.\n` };
    }
  }
  if (new Set(kinds).size !== kinds.length) {
    return { error: "--what must not repeat a kind.\n" };
  }
  if (kinds.length === 0) {
    return { error: `--what must name at least one artifact; valid kinds are ${KNOWN_KINDS.join(", ")}.\n` };
  }
  return kinds.join(",");
}

const CONFLICT_POLICIES = ["skip", "overwrite", "dedupe"] as const;

export type ConflictPolicy = typeof CONFLICT_POLICIES[number];

export function parseConflictPolicy(
  value: unknown,
  context: string,
): ConflictPolicy {
  if (value === undefined) return "skip";
  if (typeof value === "string" && (CONFLICT_POLICIES as readonly string[]).includes(value)) {
    return value as ConflictPolicy;
  }
  throw new Error(
    `${context}: invalid conflict policy "${String(value)}"; expected skip, overwrite, or dedupe`,
  );
}

import type { ExportManifestV1, ExportMemoryRecordV1 } from "./types.js";
import { sha256Bytes, sha256String } from "./fs-utils.js";

export interface TransferIntegrityRecord {
  path: string;
  content: string | Uint8Array;
}

export function validateManifestRecords(
  manifest: Pick<ExportManifestV1, "files">,
  records: readonly TransferIntegrityRecord[],
  errorPrefix: string,
): void {
  const manifestByPath = new Map<string, ExportManifestV1["files"][number]>();
  for (const file of manifest.files) {
    if (manifestByPath.has(file.path)) {
      throw new Error(`${errorPrefix}: duplicate manifest path: ${file.path}`);
    }
    manifestByPath.set(file.path, file);
  }

  const recordByPath = new Map<string, TransferIntegrityRecord>();
  for (const record of records) {
    if (recordByPath.has(record.path)) {
      throw new Error(`${errorPrefix}: duplicate record path: ${record.path}`);
    }
    recordByPath.set(record.path, record);
  }

  for (const record of records) {
    const expected = manifestByPath.get(record.path);
    if (!expected) {
      throw new Error(`${errorPrefix}: record missing from manifest: ${record.path}`);
    }
    assertContentIntegrity(record, expected, errorPrefix);
  }

  for (const file of manifest.files) {
    if (!recordByPath.has(file.path)) {
      throw new Error(`${errorPrefix}: manifest file missing from records: ${file.path}`);
    }
  }
}

export function validateExportBundleRecords(
  manifest: Pick<ExportManifestV1, "files">,
  records: readonly ExportMemoryRecordV1[],
  errorPrefix: string,
): void {
  validateManifestRecords(manifest, records, errorPrefix);
}

function assertContentIntegrity(
  record: TransferIntegrityRecord,
  expected: ExportManifestV1["files"][number],
  errorPrefix: string,
): void {
  const actual = typeof record.content === "string"
    ? sha256String(record.content)
    : sha256Bytes(record.content);
  if (actual.bytes !== expected.bytes) {
    throw new Error(
      `${errorPrefix}: byte count mismatch for ${record.path}`,
    );
  }
  if (actual.sha256 !== expected.sha256) {
    throw new Error(
      `${errorPrefix}: checksum mismatch for ${record.path}`,
    );
  }
}

import { isReplayRole, parseIsoTimestamp, type ReplayRole } from "../types.js";

type NormalizeRoleOptions = {
  assistantAliases?: string[];
  userAliases?: string[];
};

type NormalizeTimestampOptions = {
  acceptDateObject?: boolean;
  trimString?: boolean;
};

export function normalizeReplayRole(value: unknown, options: NormalizeRoleOptions = {}): ReplayRole | null {
  if (typeof value !== "string") return null;
  const role = value.trim().toLowerCase();
  if (isReplayRole(role)) return role;

  if (options.userAliases?.includes(role) || role === "human") return "user";
  if (options.assistantAliases?.includes(role) || role === "ai" || role === "model") return "assistant";
  return null;
}

export function normalizeReplayContent(value: unknown): string | null {
  if (typeof value === "string") {
    const content = value.trim();
    return content.length > 0 ? content : null;
  }
  if (Array.isArray(value)) {
    const text = value
      .map((part) => normalizeReplayContent(part) ?? "")
      .filter((part) => part.length > 0)
      .join("\n")
      .trim();
    return text.length > 0 ? text : null;
  }
  if (value && typeof value === "object") {
    const obj = value as Record<string, unknown>;
    if (Array.isArray(obj.parts)) return normalizeReplayContent(obj.parts);
    if (Array.isArray(obj.content)) return normalizeReplayContent(obj.content);
    if (typeof obj.content === "string") return normalizeReplayContent(obj.content);
    if (typeof obj.text === "string") return normalizeReplayContent(obj.text);
  }
  return null;
}

export function normalizeReplayTimestamp(value: unknown, options: NormalizeTimestampOptions = {}): string | null {
  const toIso = (millis: number): string | null => {
    if (!Number.isFinite(millis)) return null;
    const date = new Date(millis);
    if (!Number.isFinite(date.getTime())) return null;
    try {
      return date.toISOString();
    } catch {
      return null;
    }
  };

  if (typeof value === "number" && Number.isFinite(value)) {
    const millis = value > 1e12 ? value : value * 1000;
    return toIso(millis);
  }

  if (options.acceptDateObject && value instanceof Date && Number.isFinite(value.getTime())) {
    return toIso(value.getTime());
  }

  if (typeof value !== "string") return null;
  const raw = options.trimString === false ? value : value.trim();
  if (raw.length === 0) return null;
  const millis = parseIsoTimestamp(raw);
  return millis === null ? null : toIso(millis);
}

export const SQLITE_SCHEMA_VERSION = 1 as const;

export const SQLITE_TABLES_SQL = `
CREATE TABLE IF NOT EXISTS meta (
  key TEXT PRIMARY KEY,
  value TEXT NOT NULL
);

CREATE TABLE IF NOT EXISTS files (
  path_rel TEXT PRIMARY KEY,
  bytes INTEGER NOT NULL,
  sha256 TEXT NOT NULL,
  content TEXT NOT NULL
);
`;

import path from "node:path";
import { readFile } from "node:fs/promises";
import { writeFileAtomically } from "./atomic-file.js";

interface LedgerWriteOptions<T extends object> {
  memoryDir: string;
  outputPath: string;
  rows: T[];
  now: Date;
  atomicWrite?: typeof writeFileAtomically;
}

export function toHourBucketIso(timestamp: string): string | null {
  const normalized = /(?:Z|[+-]\d{2}:\d{2})$/u.test(timestamp) ? timestamp : `${timestamp}Z`;
  const ms = Date.parse(normalized);
  if (!Number.isFinite(ms)) return null;
  const d = new Date(ms);
  d.setUTCMinutes(0, 0, 0);
  return d.toISOString();
}

export async function backupAndWriteRebuiltObservations<T extends object>(
  options: LedgerWriteOptions<T>,
): Promise<string | undefined> {
  const stamp = options.now.toISOString().replace(/[-:]/g, "").replace(/\.\d{3}Z$/, "Z");
  const atomicWrite = options.atomicWrite ?? writeFileAtomically;
  const archiveRoot = path.join(options.memoryDir, "archive", "observations", stamp);
  let backupPath: string | undefined = path.join(
    archiveRoot,
    "state",
    "observation-ledger",
    "rebuilt-observations.jsonl",
  );
  try {
    const existing = await readFile(options.outputPath, "utf-8");
    await atomicWrite(backupPath, existing);
  } catch (err) {
    const code = (err as NodeJS.ErrnoException).code;
    if (code && code === "ENOENT") {
      backupPath = undefined;
    } else {
      throw err;
    }
  }

  const rebuiltAt = options.now.toISOString();
  const lines = options.rows.map((row) =>
    JSON.stringify({
      ...row,
      rebuiltAt,
    }),
  );
  await atomicWrite(options.outputPath, lines.length > 0 ? `${lines.join("\n")}\n` : "");
  return backupPath;
}

/**
 * Corpus-watermark doctor check (issue #2149).
 *
 * Lives beside operator-toolkit.ts (which is at its structural-ratchet ceiling)
 * so the god file only gains the wiring. Reports each namespace's memory-file
 * count, newest write, and a short census-digest prefix, and WARNS when a
 * namespace could not be scanned (unreadable/churning) or enumeration failed —
 * a scan failure omits a namespace, so an unconditional "ok" would certify a
 * partial fleet or conflate an unreadable corpus with an empty deployment
 * (issue #2156 round-7). Peer comparison (count/age divergence thresholds) is a
 * follow-up.
 *
 * Namespaces are resolved through the shared resolveCorpusNamespaceRoots helper
 * (issue #2156 finding C) so the doctor and the /health surface enumerate the
 * SAME tenant set and cannot drift. The caller supplies `storageFactory` (a
 * `dir -> CorpusStorage`) so this module never imports the storage god-module
 * directly (issue #1533 ratchet).
 */

import {
  type CorpusStorage,
  type CorpusWatermark,
  computeCorpusWatermarks,
  resolveCorpusNamespaceRoots,
} from "./corpus-watermark.js";
import { summarizeReplicaDivergence } from "./operator-doctor-replica.js";
import type { OperatorDoctorCheck } from "./operator-toolkit.js";
import type { ResolveSecretRefFn } from "./resolve-auth-token.js";
import type { PluginConfig } from "./types.js";

const DIGEST_PREFIX_LENGTH = 12;

export async function summarizeCorpusWatermark(
  config: PluginConfig,
  storageFactory: (dir: string) => CorpusStorage,
  now?: Date
): Promise<OperatorDoctorCheck> {
  let resolved: string[] = [];
  let watermarks: CorpusWatermark[] = [];
  let enumerationFailed = false;
  try {
    // The doctor orchestrator has no live namespace catalog, so config-driven
    // enumeration (deduped by root inside the shared helper) is the whole set.
    const rootByNamespace = new Map<string, string>();
    for (const root of await resolveCorpusNamespaceRoots({ config, propagateDiscoveryErrors: true })) {
      rootByNamespace.set(root.namespace, root.rootDir);
    }
    resolved = [...rootByNamespace.keys()];
    watermarks = await computeCorpusWatermarks(
      resolved,
      (namespace) => storageFactory(rootByNamespace.get(namespace) ?? config.memoryDir),
      now
    );
  } catch {
    // Namespace ENUMERATION itself failed (distinct from a per-namespace scan).
    enumerationFailed = true;
  }

  const computed = new Set(watermarks.map((w) => w.namespace));
  const failed = resolved.filter((namespace) => !computed.has(namespace));
  const lines = watermarks.map(
    (w) =>
      `${w.namespace}: ${w.memoryFileCount} files, newest=${w.newestWriteAt ?? "never"}, ` +
      `digest=${w.digest.slice(0, DIGEST_PREFIX_LENGTH)}`
  );

  if (enumerationFailed) {
    return {
      key: "corpus_watermark",
      status: "warn",
      summary: "Could not resolve corpus namespaces (enumeration failed).",
      remediation: "Ensure the memory directory and namespace catalog are readable, then rerun `remnic doctor`.",
      details: { corpus: watermarks, resolved: resolved.length, failed: failed.length },
    };
  }
  if (failed.length > 0) {
    return {
      key: "corpus_watermark",
      status: "warn",
      summary:
        `Corpus watermark unavailable for ${failed.length} of ${resolved.length} namespace(s) ` +
        `(unreadable or churning): ${failed.join(", ")}.` +
        (lines.length > 0 ? ` Reporting ${lines.length}: ${lines.join("; ")}` : ""),
      remediation: "Inspect the omitted namespace roots for permission/backend errors, then rerun `remnic doctor`.",
      details: { corpus: watermarks, resolved: resolved.length, failed },
    };
  }
  return {
    key: "corpus_watermark",
    status: "ok",
    summary:
      resolved.length === 0
        ? "No corpus namespaces resolved yet."
        : `Corpus watermark across ${watermarks.length} namespace(s): ${lines.join("; ")}`,
    details: { corpus: watermarks },
  };
}

/**
 * Extract the watermark array this check stores under `details.corpus` (issue
 * #2149). The replica-divergence doctor check reuses the local watermark set
 * computed here rather than rescanning the corpus, and consumes it through this
 * helper so the `details.corpus` shape stays owned by the module that produces it.
 */
export function corpusWatermarksFromCheck(check: OperatorDoctorCheck): CorpusWatermark[] {
  const details = check.details;
  if (!details || typeof details !== "object" || !("corpus" in details) || !Array.isArray(details.corpus)) {
    return [];
  }
  // This check always stores a CorpusWatermark[] under `corpus` (guarded above).
  return details.corpus as CorpusWatermark[];
}

/**
 * Build the corpus-watermark and replica-divergence doctor checks together.
 *
 * They are paired deliberately: the replica comparison consumes the corpus
 * check's watermarks (one scan, not two) AND its completeness — an incomplete
 * local census must not let the replica check certify convergence. The pairing
 * lives HERE, next to the corpus check + `corpusWatermarksFromCheck` it consumes
 * and the `PluginConfig` it needs, so the sibling replica module stays a light
 * tsup DTS entry free of the heavy `PluginConfig` type graph (round 6, coderabbit).
 */
export async function summarizeCorpusAndReplica(
  config: PluginConfig,
  storageFactory: (dir: string) => CorpusStorage,
  resolveSecretRef?: ResolveSecretRefFn | null,
): Promise<OperatorDoctorCheck[]> {
  const watermarkCheck = await summarizeCorpusWatermark(config, storageFactory);
  const replicaCheck = await summarizeReplicaDivergence(
    config.replicaPeers,
    corpusWatermarksFromCheck(watermarkCheck),
    { resolveSecretRef, localCensusComplete: watermarkCheck.status === "ok" },
  );
  return [watermarkCheck, replicaCheck];
}

/**
 * Consolidation provenance integrity check (issue #561 PR 4).
 *
 * Validates that every memory carrying consolidation provenance frontmatter
 * (`derived_from`, `derived_via`) resolves to real data:
 *
 *   - Each `derived_from` entry `"<path>:<version>"` must name a
 *     page-version snapshot that exists on disk (via the sidecar layout
 *     documented in `page-versioning.ts`).
 *   - Each `derived_via` must be one of the known
 *     `ConsolidationOperator` values — malformed values are surfaced as
 *     warnings rather than crashes so legacy or future operators survive a
 *     rollback.
 *
 * Non-fatal: every failure renders a warning with the offending file path
 * and a human-readable reason.  Integrity problems are informational for
 * now — we do not auto-heal or archive broken memories.
 */

import path from "node:path";
import { lstat, readdir, readFile, realpath, stat } from "node:fs/promises";
import { constants as fsConstants } from "node:fs";
import type { StorageManager } from "./storage.js";
import {
  DERIVED_FROM_MEMORY_ID_RE,
  isConsolidationOperator,
} from "./consolidation-operator.js";
// Import the canonical `sidecarKey` from page-versioning (PR #634
// review, cursor Medium) so a future key-format change stays in
// lock-step with the doctor scan.
import { sidecarKey } from "./page-versioning.js";
import { RECALL_FALLBACK_DIRS } from "./utils/category-dir.js";
import { isMacOsReplicationJunkBasename } from "./utils/macos-replication-junk.js";

/**
 * Regex to spot a `derived_via: <value>` line in the raw YAML frontmatter
 * between the opening and first closing `---` delimiters.  We use the raw
 * text rather than the parsed `frontmatter.derived_via` because the
 * read-path parser coerces unknown values back to `undefined` — that
 * would silently hide corrupted-or-future operators from the doctor scan
 * (PR #634 review feedback, codex P2).
 */
// Allow empty capture groups so truncated/blank `derived_via:` and
// `derived_from:` lines (key present, no value) are distinguishable
// from "key missing entirely" (regex returns null).  Optional
// leading whitespace accepts indented keys which `parseFrontmatter`
// also accepts (PR #634 round-6 review, codex P2).
const DERIVED_VIA_RAW_RE = /^[\t ]*derived_via:[\t ]*(.*)$/mu;
const DERIVED_FROM_RAW_RE = /^[\t ]*derived_from:[\t ]*(.*)$/mu;

/**
 * Tokenize a YAML-block-style list under `key:` in the given
 * frontmatter slice.  Looks for lines matching `^  - <value>` after a
 * `key:` line and before the next non-list line.  Returns `null` when
 * the key is missing or the value is a scalar / flow list (no block
 * entries found).
 *
 * Only used for the mixed-list malformed-entry detection — it does
 * not try to decode YAML escape sequences since we only need the
 * entry count + raw token text to compare against the parsed array.
 */
function tokenizeRawBlockList(fmSlice: string, key: string): string[] | null {
  const lines = fmSlice.split("\n");
  // Accept indented keys too — parseFrontmatter does (PR #634 round-7
  // review, codex P2 / cursor Low).
  const keyRe = new RegExp(`^[\\t ]*${key}:[\\t ]*(.*)$`, "u");
  let startIdx = -1;
  for (let i = 0; i < lines.length; i++) {
    const m = lines[i].match(keyRe);
    if (m) {
      if (m[1].trim().length === 0) {
        startIdx = i + 1;
      }
      break;
    }
  }
  if (startIdx < 0) return null;
  const items: string[] = [];
  for (let i = startIdx; i < lines.length; i++) {
    const line = lines[i];
    if (!/^\s+-/.test(line)) break; // not a block-list entry
    const m = line.match(/^\s+-\s*(.*)$/u);
    if (!m) break;
    let tok = m[1].trim();
    if (
      (tok.startsWith('"') && tok.endsWith('"') && tok.length >= 2) ||
      (tok.startsWith("'") && tok.endsWith("'") && tok.length >= 2)
    ) {
      tok = tok.slice(1, -1);
    }
    items.push(tok);
  }
  return items.length > 0 ? items : null;
}

/**
 * Tokenize a YAML-flow-style list (`["a", "b", ...]`) into a flat
 * string array.  Returns `null` when the input isn't a flow list.
 * Best-effort — we don't implement a full YAML parser, just enough to
 * detect mixed valid/invalid entries for the doctor integrity check.
 */
function tokenizeRawFlowList(raw: string): string[] | null {
  const trimmed = raw.trim();
  if (!trimmed.startsWith("[") || !trimmed.endsWith("]")) return null;
  const inner = trimmed.slice(1, -1);
  const parts: string[] = [];
  let current = "";
  let inSingle = false;
  let inDouble = false;
  for (let i = 0; i < inner.length; i++) {
    const ch = inner[i];
    if (inDouble) {
      if (ch === "\\" && i + 1 < inner.length) {
        current += inner[++i];
        continue;
      }
      if (ch === '"') {
        inDouble = false;
        continue;
      }
      current += ch;
    } else if (inSingle) {
      if (ch === "'" && inner[i + 1] === "'") {
        current += "'";
        i++;
        continue;
      }
      if (ch === "'") {
        inSingle = false;
        continue;
      }
      current += ch;
    } else if (ch === '"') {
      inDouble = true;
    } else if (ch === "'") {
      inSingle = true;
    } else if (ch === ",") {
      parts.push(current.trim());
      current = "";
    } else {
      current += ch;
    }
  }
  if (current.trim().length > 0 || parts.length > 0) {
    parts.push(current.trim());
  }
  return parts;
}

/**
 * One integrity warning attached to a specific memory.
 */
export interface ConsolidationProvenanceIssue {
  /** Absolute path to the memory markdown file. */
  memoryPath: string;
  /** Memory id from frontmatter. */
  memoryId: string;
  /** Type of integrity issue. */
  kind:
    | "derived_from_missing_snapshot"
    | "derived_from_malformed_entry"
    | "derived_via_unknown_operator";
  /** Human-readable detail — includes the offending value when relevant. */
  detail: string;
}

/**
 * Summary of a provenance-integrity scan.  Used by the operator-doctor
 * report and surfaced in the CLI output.
 */
export interface ConsolidationProvenanceReport {
  /** Total memories inspected. */
  scanned: number;
  /** Memories that carry `derived_from` and/or `derived_via`. */
  withProvenance: number;
  /** One entry per problem detected (may be empty). */
  issues: ConsolidationProvenanceIssue[];
}

const DERIVED_FROM_ENTRY_RE = /^(.+):(\d+)$/;

/**
 * Build the on-disk snapshot path for a `"<relpath>:<version>"` entry,
 * relative to the given memory directory.  Mirrors the layout documented
 * in `page-versioning.ts`:
 *
 *   memoryDir/<sidecarDir>/<sidecarKey>/<version><ext>
 */
function resolveSnapshotPath(
  memoryDir: string,
  sidecarDir: string,
  entry: string,
): { ok: true; snapshotPath: string } | { ok: false; reason: string } {
  const match = entry.match(DERIVED_FROM_ENTRY_RE);
  if (!match) {
    return { ok: false, reason: `malformed entry (expected "<path>:<version>")` };
  }
  const pagePath = match[1];
  const versionId = match[2];
  const ext = path.extname(pagePath) || ".md";
  const key = sidecarKey(pagePath);
  const snapshotPath = path.join(memoryDir, sidecarDir, key, `${versionId}${ext}`);
  return { ok: true, snapshotPath };
}

/**
 * Scan every memory under `storage` and flag consolidation-provenance
 * problems.  Does not throw on individual failures — collects them in the
 * returned report.
 */
export async function runConsolidationProvenanceCheck(options: {
  storage: StorageManager;
  memoryDir: string;
  /**
   * Page-versioning sidecar directory name.  Defaults to `.versions` —
   * matches the baked-in default used by `setVersioningConfig` when
   * versioning is enabled via config.
   */
  sidecarDir?: string;
}): Promise<ConsolidationProvenanceReport> {
  const { storage, memoryDir } = options;
  const sidecarDir = options.sidecarDir ?? ".versions";

  const report: ConsolidationProvenanceReport = {
    scanned: 0,
    withProvenance: 0,
    issues: [],
  };

  let memories;
  try {
    memories = await storage.readAllMemories();
  } catch {
    // If we can't enumerate memories at all, surface a single synthetic
    // issue rather than throwing — the doctor wrapper treats an empty
    // issues list as "ok" and we don't want a filesystem hiccup to crash
    // the whole diagnostic.
    return {
      scanned: 0,
      withProvenance: 0,
      issues: [
        {
          memoryPath: memoryDir,
          memoryId: "(unreadable)",
          kind: "derived_from_malformed_entry",
          detail: "Could not enumerate memory directory to scan provenance.",
        },
      ],
    };
  }

  for (const memory of memories) {
    report.scanned += 1;
    const fm = memory.frontmatter;
    const derivedFrom = fm.derived_from;
    const derivedVia = fm.derived_via;

    // Raw frontmatter values from disk — the read-path parser coerces
    // malformed `derived_from` and unknown `derived_via` back to
    // `undefined`, which would silently hide on-disk corruption from
    // the doctor scan (PR #634 review feedback, codex P2).  We
    // re-extract both via regex so integrity issues are reported even
    // when the parser normalized them away.  `rawDerivedVia` /
    // `rawDerivedFrom` being `""` (empty string) represents a
    // corrupted file with the key present but the value truncated —
    // that's distinct from "key missing entirely" (undefined).
    let rawDerivedVia: string | undefined;
    let rawDerivedFrom: string | undefined;
    let rawDerivedViaKeyPresent = false;
    let rawDerivedFromKeyPresent = false;
    let duplicateViaKeys = false;
    let duplicateFromKeys = false;
    let viaMatchCount = 0;
    let fromMatchCount = 0;
    let fmSlice = "";
    try {
      const raw = await readFile(memory.path, "utf-8");
      const frontmatterEnd = raw.indexOf("\n---", raw.indexOf("---") + 3);
      fmSlice = frontmatterEnd > 0 ? raw.slice(0, frontmatterEnd) : raw;
      // Use matchAll to find ALL occurrences of `derived_via` / `derived_from`
      // in the raw YAML.  `parseFrontmatter` keeps the LAST assignment when
      // duplicate keys appear, so the doctor must read the last occurrence
      // to match what the storage reader actually uses (PR #634 review,
      // codex P2 — duplicate `derived_via` keys caused false-clean or
      // false-unknown-operator warnings depending on order).
      const viaMatches = [...fmSlice.matchAll(new RegExp(DERIVED_VIA_RAW_RE.source, DERIVED_VIA_RAW_RE.flags + "g"))];
      viaMatchCount = viaMatches.length;
      duplicateViaKeys = viaMatches.length > 1;
      if (viaMatches.length > 0) {
        rawDerivedViaKeyPresent = true;
        // Use the last occurrence — `parseFrontmatter` keeps the last
        // assignment when duplicate keys appear, so the doctor must
        // match that behavior to produce accurate warnings (PR #634
        // review, codex P2).
        const lastVia = viaMatches[viaMatches.length - 1];
        let val = lastVia[1].trim();
        if (
          (val.startsWith('"') && val.endsWith('"')) ||
          (val.startsWith("'") && val.endsWith("'"))
        ) {
          val = val.slice(1, -1);
        }
        rawDerivedVia = val;
      }
      const fromMatches = [...fmSlice.matchAll(new RegExp(DERIVED_FROM_RAW_RE.source, DERIVED_FROM_RAW_RE.flags + "g"))];
      fromMatchCount = fromMatches.length;
      duplicateFromKeys = fromMatches.length > 1;
      if (fromMatches.length > 0) {
        rawDerivedFromKeyPresent = true;
        const lastFrom = fromMatches[fromMatches.length - 1];
        rawDerivedFrom = lastFrom[1].trim();
      }
    } catch {
      // Fall through to the parsed values.
    }

    const hasFrom = Array.isArray(derivedFrom) && derivedFrom.length > 0;
    const hasVia = derivedVia !== undefined && derivedVia !== null;
    const hasRawVia = rawDerivedVia !== undefined && rawDerivedVia.length > 0;
    // A raw `derived_from` that the parser dropped indicates on-disk
    // corruption we must surface.  We detect this by: (a) the raw YAML
    // contains a `derived_from:` key, AND (b) the parsed frontmatter
    // has no valid array.  A scalar like `derived_from: facts/a.md:7`
    // (list brackets omitted) or a blank `derived_from:` both hit this
    // branch.
    const hasRawMalformedFrom = rawDerivedFromKeyPresent && !hasFrom;
    // A blank `derived_via:` with no value is also corrupt — the
    // parser drops it to undefined, but the raw key is still present
    // on disk (PR #634 round-3 review, codex P2).
    const hasBlankRawVia =
      rawDerivedViaKeyPresent &&
      (rawDerivedVia === undefined || rawDerivedVia.length === 0) &&
      !hasVia;
    if (
      !hasFrom && !hasVia && !hasRawVia &&
      !hasRawMalformedFrom && !hasBlankRawVia
    ) continue;
    report.withProvenance += 1;

    // Duplicate-key detection (PR #634 review, codex P2): when the raw
    // YAML contains multiple `derived_via` or `derived_from` lines,
    // `parseFrontmatter` silently uses the last one.  Flag this as a
    // malformed entry so operators can inspect and fix the file.
    if (duplicateViaKeys) {
      report.issues.push({
        memoryPath: memory.path,
        memoryId: fm.id,
        kind: "derived_via_unknown_operator",
        detail: `raw YAML contains ${viaMatchCount} "derived_via" keys; parseFrontmatter uses the last occurrence`,
      });
    }
    if (duplicateFromKeys) {
      report.issues.push({
        memoryPath: memory.path,
        memoryId: fm.id,
        kind: "derived_from_malformed_entry",
        detail: `raw YAML contains ${fromMatchCount} "derived_from" keys; parseFrontmatter uses the last occurrence`,
      });
    }

    if (hasRawMalformedFrom) {
      const display = rawDerivedFrom ?? "(blank)";
      report.issues.push({
        memoryPath: memory.path,
        memoryId: fm.id,
        kind: "derived_from_malformed_entry",
        detail: `raw YAML "derived_from: ${display}" could not be parsed as a list`,
      });
    }

    // Mixed-list detection (PR #634 round-4 + round-5 review, codex
    // P2): when the parser DID return a valid list but the raw YAML
    // includes additional tokens that got dropped, flag those as
    // malformed.  Handles both flow-style (`["a", "", "b"]`) and
    // block-style (`\n  - a\n  - \n  - b`) YAML lists.
    if (hasFrom && rawDerivedFromKeyPresent) {
      let rawList: string[] | null = null;
      if (rawDerivedFrom && rawDerivedFrom.length > 0) {
        rawList = tokenizeRawFlowList(rawDerivedFrom);
      }
      if (rawList === null) {
        // Fall back to block-list tokenization by re-reading the full
        // frontmatter (already loaded above as `raw`) and scanning
        // the lines following `derived_from:`.
        rawList = tokenizeRawBlockList(fmSlice, "derived_from");
      }
      if (rawList !== null && rawList.length > derivedFrom!.length) {
        for (const tok of rawList) {
          if (tok.length === 0) {
            report.issues.push({
              memoryPath: memory.path,
              memoryId: fm.id,
              kind: "derived_from_malformed_entry",
              detail: `raw YAML derived_from contains an empty entry (mixed list)`,
            });
            continue;
          }
          if (!derivedFrom!.includes(tok)) {
            // Accept either the snapshot format `<path>:<version>` or
            // a bare memory id (issue #687 PR 2/4 — pattern
            // reinforcement uses ID-shaped entries).  PR #730
            // review feedback, Codex P2.
            if (
              !/^(.+):(\d+)$/u.test(tok) &&
              !DERIVED_FROM_MEMORY_ID_RE.test(tok)
            ) {
              report.issues.push({
                memoryPath: memory.path,
                memoryId: fm.id,
                kind: "derived_from_malformed_entry",
                detail: `raw YAML derived_from contains a malformed entry: ${JSON.stringify(tok)}`,
              });
            }
          }
        }
      }
    }
    if (hasBlankRawVia) {
      report.issues.push({
        memoryPath: memory.path,
        memoryId: fm.id,
        kind: "derived_via_unknown_operator",
        detail: "raw YAML has `derived_via:` key with empty value",
      });
    }

    if (hasFrom) {
      for (const entry of derivedFrom!) {
        // Pattern-reinforcement (issue #687 PR 2/4) records source
        // memory IDs directly in `derived_from` rather than
        // page-versioning snapshot references.  Memory IDs may
        // contain `:` for namespace-prefixed forms like
        // `global:fact-abc-123`, but never `/` or `.` — those remain
        // exclusive to snapshot paths (PR #730 review feedback,
        // Codex P1).  For ID-shaped entries we skip the snapshot
        // file check entirely — but ONLY when the operator is
        // `pattern-reinforcement`, which is the sole operator that
        // legitimately stores IDs rather than snapshot references.
        // Allowing the bypass for split/merge/update would weaken
        // validation on those existing consolidation paths (PR #730
        // review, Codex P2).
        if (
          derivedVia === "pattern-reinforcement" &&
          DERIVED_FROM_MEMORY_ID_RE.test(entry)
        ) {
          continue;
        }
        const resolved = resolveSnapshotPath(memoryDir, sidecarDir, entry);
        if (!resolved.ok) {
          report.issues.push({
            memoryPath: memory.path,
            memoryId: fm.id,
            kind: "derived_from_malformed_entry",
            detail: `${JSON.stringify(entry)}: ${resolved.reason}`,
          });
          continue;
        }
        // Require a regular file at the snapshot path (PR #634
        // round-8 review, codex P2) — a directory or device node at
        // that path means the sidecar was corrupted and the snapshot
        // is effectively missing.
        let snapshotOk = false;
        try {
          const st = await stat(resolved.snapshotPath);
          snapshotOk = st.isFile();
        } catch {
          snapshotOk = false;
        }
        if (!snapshotOk) {
          report.issues.push({
            memoryPath: memory.path,
            memoryId: fm.id,
            kind: "derived_from_missing_snapshot",
            detail: `${entry} → ${resolved.snapshotPath} (not a regular file)`,
          });
        }
      }
    }

    // Check the RAW YAML value for unknown operators.  The parsed value
    // (`fm.derived_via`) is always known-good because the read-path
    // normalizer dropped anything else to undefined.
    if (hasRawVia && !isConsolidationOperator(rawDerivedVia)) {
      report.issues.push({
        memoryPath: memory.path,
        memoryId: fm.id,
        kind: "derived_via_unknown_operator",
        detail: `unknown operator: ${JSON.stringify(rawDerivedVia)}`,
      });
    }
  }

  // Parse-failure detection (PR #634 round-4 review, codex P2):
  // `readAllMemories()` silently drops files whose frontmatter
  // doesn't parse.  Walk every recall category directory for `.md` files
  // that DO reference provenance frontmatter but didn't come back from the
  // reader — those are the corruption cases the doctor is meant to surface.
  // Uses RECALL_FALLBACK_DIRS (the single source of truth) so newly-routed
  // categories (decisions/, preferences/, ...) are scanned too (#1546).
  try {
    const seenPaths = new Set(memories.map((m) => m.path));
    for (const rootName of RECALL_FALLBACK_DIRS) {
      const rootPath = path.join(memoryDir, rootName);
      for await (const file of walkMarkdownFiles(rootPath, memoryDir)) {
        if (seenPaths.has(file)) continue;
        try {
          const raw = await readFile(file, "utf-8");
          if (
            DERIVED_FROM_RAW_RE.test(raw) ||
            DERIVED_VIA_RAW_RE.test(raw)
          ) {
            report.withProvenance += 1;
            report.issues.push({
              memoryPath: file,
              memoryId: "(parse failed)",
              kind: "derived_from_malformed_entry",
              detail:
                "frontmatter could not be parsed by storage reader; provenance fields visible in raw YAML",
            });
          }
        } catch {
          // Unreadable file — skip.
        }
      }
    }
  } catch {
    // Best-effort; don't fail the whole scan on a filesystem hiccup.
  }

  return report;
}

/**
 * Recursively yield all `.md` file paths under `root`.  Silent on
 * missing directories — the facts/corrections dirs may not exist in
 * fresh installs.  Symlinked roots/directories are skipped so the
 * best-effort parse-failure pass cannot escape `memoryDir`.
 */
async function* walkMarkdownFiles(root: string, memoryDir: string): AsyncGenerator<string> {
  let entries;
  let memoryDirReal: string;
  try {
    const rootStat = await lstat(root);
    if (!rootStat.isDirectory() || rootStat.isSymbolicLink()) return;
    memoryDirReal = await realpath(memoryDir);
    const rootReal = await realpath(root);
    if (!isPathWithin(rootReal, memoryDirReal)) return;
    entries = await readdir(root, { withFileTypes: true });
  } catch {
    return;
  }
  for (const entry of entries) {
    if (isMacOsReplicationJunkBasename(entry.name)) continue;
    const full = path.join(root, entry.name);
    if (entry.isSymbolicLink()) continue;
    if (entry.isDirectory()) {
      yield* walkMarkdownFiles(full, memoryDirReal);
    } else if (entry.isFile() && entry.name.endsWith(".md")) {
      try {
        const fileReal = await realpath(full);
        if (!isPathWithin(fileReal, memoryDirReal)) continue;
      } catch {
        continue;
      }
      yield full;
    }
  }
}

function isPathWithin(candidate: string, root: string): boolean {
  const relative = path.relative(root, candidate);
  return relative === "" || (!!relative && !relative.startsWith("..") && !path.isAbsolute(relative));
}

import path from "node:path";
import { readFile } from "node:fs/promises";
import type { GraphEdge, GraphType } from "./graph.js";
import { graphEdgeKey } from "./graph-dashboard-key.js";

export interface GraphSnapshotNode {
  id: string;
}

export interface GraphSnapshotStats {
  nodes: number;
  edges: number;
  malformedLines: number;
  filesMissing: GraphType[];
}

export interface GraphSnapshot {
  generatedAt: string;
  nodes: GraphSnapshotNode[];
  edges: GraphEdge[];
  stats: GraphSnapshotStats;
}

const GRAPH_TYPES: GraphType[] = ["entity", "time", "causal"];

function graphFile(memoryDir: string, type: GraphType): string {
  return path.join(memoryDir, "state", "graphs", `${type}.jsonl`);
}

function isGraphEdge(raw: unknown, expectedType: GraphType): raw is GraphEdge {
  if (!raw || typeof raw !== "object") return false;
  const edge = raw as Record<string, unknown>;
  return (
    edge.type === expectedType &&
    typeof edge.from === "string" &&
    edge.from.length > 0 &&
    typeof edge.to === "string" &&
    edge.to.length > 0 &&
    typeof edge.weight === "number" &&
    Number.isFinite(edge.weight) &&
    typeof edge.label === "string" &&
    typeof edge.ts === "string"
  );
}

export async function graphSnapshotFromMemoryDir(memoryDir: string): Promise<GraphSnapshot> {
  const nodes = new Set<string>();
  const edges: GraphEdge[] = [];
  const filesMissing: GraphType[] = [];
  let malformedLines = 0;
  const seenEdges = new Set<string>();

  for (const type of GRAPH_TYPES) {
    const filePath = graphFile(memoryDir, type);
    let raw = "";
    try {
      raw = await readFile(filePath, "utf-8");
    } catch (err) {
      if ((err as NodeJS.ErrnoException).code !== "ENOENT") {
        throw err;
      }
      filesMissing.push(type);
      continue;
    }
    for (const line of raw.split("\n")) {
      const trimmed = line.trim();
      if (!trimmed) continue;
      let parsed: unknown;
      try {
        parsed = JSON.parse(trimmed);
      } catch {
        malformedLines += 1;
        continue;
      }
      if (!isGraphEdge(parsed, type)) {
        malformedLines += 1;
        continue;
      }
      const key = graphEdgeKey(parsed);
      if (seenEdges.has(key)) continue;
      seenEdges.add(key);
      edges.push(parsed);
      nodes.add(parsed.from);
      nodes.add(parsed.to);
    }
  }

  const sortedEdges = edges.sort((a, b) =>
    a.type.localeCompare(b.type) ||
    a.from.localeCompare(b.from) ||
    a.to.localeCompare(b.to) ||
    a.ts.localeCompare(b.ts)
  );
  const sortedNodes = [...nodes].sort((a, b) => a.localeCompare(b)).map((id) => ({ id }));

  return {
    generatedAt: new Date().toISOString(),
    nodes: sortedNodes,
    edges: sortedEdges,
    stats: {
      nodes: sortedNodes.length,
      edges: sortedEdges.length,
      malformedLines,
      filesMissing,
    },
  };
}

import type { GraphEdge } from "./graph.js";
import { graphEdgeKey } from "./graph-dashboard-key.js";
import type { GraphSnapshot } from "./graph-dashboard-parser.js";

export interface GraphPatch {
  addedNodes: string[];
  removedNodes: string[];
  addedEdges: GraphEdge[];
  removedEdges: GraphEdge[];
  updatedEdges: Array<{ previous: GraphEdge; next: GraphEdge }>;
}

function compareGraphEdges(a: GraphEdge, b: GraphEdge): number {
  return a.type.localeCompare(b.type) || a.from.localeCompare(b.from) || a.to.localeCompare(b.to);
}

function edgeFieldsChanged(previous: GraphEdge, next: GraphEdge): boolean {
  return (
    previous.weight !== next.weight ||
    (previous.confidence ?? 1) !== (next.confidence ?? 1) ||
    (previous.lastReinforcedAt ?? null) !== (next.lastReinforcedAt ?? null)
  );
}

export function diffGraphSnapshots(previous: GraphSnapshot, next: GraphSnapshot): GraphPatch {
  const prevNodeSet = new Set(previous.nodes.map((node) => node.id));
  const nextNodeSet = new Set(next.nodes.map((node) => node.id));
  const prevEdges = new Map(previous.edges.map((edge) => [graphEdgeKey(edge), edge]));
  const nextEdges = new Map(next.edges.map((edge) => [graphEdgeKey(edge), edge]));

  const addedNodes = [...nextNodeSet].filter((id) => !prevNodeSet.has(id)).sort((a, b) => a.localeCompare(b));
  const removedNodes = [...prevNodeSet].filter((id) => !nextNodeSet.has(id)).sort((a, b) => a.localeCompare(b));
  const addedEdges = [...nextEdges.entries()]
    .filter(([key]) => !prevEdges.has(key))
    .map(([, edge]) => edge)
    .sort(compareGraphEdges);
  const removedEdges = [...prevEdges.entries()]
    .filter(([key]) => !nextEdges.has(key))
    .map(([, edge]) => edge)
    .sort(compareGraphEdges);
  const updatedEdges = [...nextEdges.entries()]
    .flatMap(([key, nextEdge]) => {
      const previousEdge = prevEdges.get(key);
      return previousEdge && edgeFieldsChanged(previousEdge, nextEdge)
        ? [{ previous: previousEdge, next: nextEdge }]
        : [];
    })
    .sort((a, b) => compareGraphEdges(a.next, b.next));

  return {
    addedNodes,
    removedNodes,
    addedEdges,
    removedEdges,
    updatedEdges,
  };
}

export type VersionTriple = readonly [number, number, number];

export function compareVersions(a: VersionTriple, b: VersionTriple): number {
  for (let i = 0; i < 3; i += 1) {
    if (a[i] > b[i]) return 1;
    if (a[i] < b[i]) return -1;
  }
  return 0;
}

/**
 * Deterministic first-pass timeline classification (issue #2049).
 *
 * Signal-only: application name, browser domain, and window-title keywords.
 * No LLM, no scoring, no intent inference — an app/window match says what was
 * on screen, never that the user meant it. First matching rule (in declared
 * order: domain, then app, then title) wins; no match stays visible in the
 * reserved `system.unknown` category with confidence 0.
 */

import type { TimelineCategory, TimelineObservation } from "./types.js";
import { TIMELINE_RESERVED_UNKNOWN } from "./categories.js";

const DOMAIN_CONFIDENCE = 0.85;
const APP_CONFIDENCE = 0.9;
const TITLE_CONFIDENCE = 0.7;
const UNKNOWN_CONFIDENCE = 0;

interface ClassificationRule {
  categoryId: string;
  /** Substring matches against the browser URL host (most specific signal). */
  domains?: readonly string[];
  /** Substring matches against the application name. */
  apps?: readonly string[];
  /** Substring matches against the window title (weakest signal). */
  titles?: readonly string[];
}

/**
 * Ordered rules. Domain rules come first (a browser on github.com is
 * development even though the app is Chrome), then app rules, then title
 * keywords. Order is part of the contract: inserting a rule changes only
 * classifications below it.
 */
const RULES: readonly ClassificationRule[] = [
  { categoryId: "development", domains: ["github.com", "gitlab.com", "stackoverflow.com", "linear.app", "atlassian.net"] },
  { categoryId: "communication", domains: ["mail.google.com", "gmail.com", "outlook.com", "outlook.office.com", "slack.com"] },
  { categoryId: "design", domains: ["figma.com", "canva.com"] },
  { categoryId: "documents", domains: ["docs.google.com", "notion.so", "dropbox.com"] },
  { categoryId: "entertainment", domains: ["youtube.com", "netflix.com", "spotify.com"] },
  { categoryId: "data", domains: ["metabase", "tableau", "grafana"] },

  { categoryId: "development", apps: ["code", "cursor", "neovim", "vim", "emacs", "xcode", "intellij", "terminal", "iterm", "warp", "wezterm", "kitty", "alacritty", "zed", "sublime", "datagrip"] },
  { categoryId: "communication", apps: ["slack", "discord", "teams", "mail", "outlook", "thunderbird", "messages", "signal", "whatsapp", "telegram", "zoom", "facetime", "meet"] },
  { categoryId: "design", apps: ["figma", "sketch", "photoshop", "illustrator", "indesign", "premiere", "after effects", "davinci", "blender", "ableton", "logic pro", "final cut"] },
  { categoryId: "documents", apps: ["word", "pages", "notion", "obsidian", "notes", "typora", "bear", "preview", "acrobat"] },
  { categoryId: "data", apps: ["excel", "numbers", "sheets", "tableau"] },
  { categoryId: "admin", apps: ["finder", "settings", "system preferences", "activity monitor", "files", "explorer"] },
  { categoryId: "entertainment", apps: ["spotify", "music", "youtube", "vlc", "quicktime", "steam", "netflix", "podcast", "tv"] },
  { categoryId: "browsing", apps: ["chrome", "safari", "firefox", "edge", "arc", "brave", "browser"] },

  { categoryId: "development", titles: ["pull request", "merge conflict", "terminal —", "repository"] },
  { categoryId: "communication", titles: ["inbox"] },
  { categoryId: "data", titles: ["spreadsheet", "pivot table"] },
];

export interface TimelineClassification {
  categoryId: string;
  confidence: number;
}

/**
 * Classify one observation. Throws if a rule targets a category missing from
 * the registry (configuration error must fail loudly, not fall back silently).
 */
export function classifyTimelineObservation(
  observation: Pick<TimelineObservation, "app" | "windowTitle" | "browserUrl">,
  categories: readonly TimelineCategory[],
): TimelineClassification {
  const app = observation.app.toLowerCase();
  const title = observation.windowTitle.toLowerCase();
  const domain = observation.browserUrl === undefined ? "" : hostOf(observation.browserUrl);
  for (const rule of RULES) {
    if (rule.domains !== undefined && domain !== "" && rule.domains.some((pattern) => domain.includes(pattern))) {
      return checkedRule(rule, DOMAIN_CONFIDENCE, categories);
    }
  }
  for (const rule of RULES) {
    if (rule.apps !== undefined && rule.apps.some((pattern) => app.includes(pattern))) {
      return checkedRule(rule, APP_CONFIDENCE, categories);
    }
  }
  for (const rule of RULES) {
    if (rule.titles !== undefined && rule.titles.some((pattern) => title.includes(pattern))) {
      return checkedRule(rule, TITLE_CONFIDENCE, categories);
    }
  }
  return { categoryId: TIMELINE_RESERVED_UNKNOWN, confidence: UNKNOWN_CONFIDENCE };
}

/** Verify the rule's target exists in the registry before returning it. */
function checkedRule(
  rule: ClassificationRule,
  confidence: number,
  categories: readonly TimelineCategory[],
): TimelineClassification {
  if (!categories.some((category) => category.id === rule.categoryId)) {
    throw new RangeError(`timeline classification rule targets unknown category: ${rule.categoryId}`);
  }
  return { categoryId: rule.categoryId, confidence };
}

/** Lowercased hostname of a URL, or "" when unparseable (never throws). */
function hostOf(url: string): string {
  try {
    return new URL(url).hostname.toLowerCase();
  } catch {
    return url.toLowerCase();
  }
}

/**
 * Deterministic timeline-card day builder (issue #2049).
 *
 * Semantics (all half-open [start, end), all UTC internally):
 * - Observations are grouped per capture machine and sorted by
 *   (canonical capture instant, contentHash) — never by array position.
 * - Compatibility rule: two consecutive observations on one machine merge
 *   into the same card iff they share the exact (app, windowTitle) pair.
 * - Gap rule: a merge happens only when the inter-observation gap is
 *   ≤ MERGE_GAP_MS (2 min). A card's end extends from its last observation
 *   by at most MAX_DWELL_MS (15 min, matching the digest dwell cap), is
 *   clipped by the next observation on the machine, by any user pause, and
 *   by the local day end — so cards never overlap on a track.
 * - Idle: any uncovered remainder between consecutive cards on a machine
 *   track (which in practice means a gap > MAX_DWELL_MS) becomes a derived
 *   idle card with no evidence. The day's leading/trailing uncovered ranges
 *   are represented by the absence of cards, not by invented idle.
 * - Pause: user-declared intervals are unioned, clipped to the day, emitted
 *   as pause cards, and never overlapped by activity dwell or idle.
 * - Nothing is invented for gaps: idle/pause cards carry no evidence and are
 *   flagged by kind; an app/window match never claims user intent.
 *
 * Output is byte-stable: identical inputs produce identical
 * `serializeTimelineDay()` bytes across runs and process restarts.
 */

import { createHash } from "node:crypto";

import { activityDayWindow } from "../digest.js";
import { DEFAULT_TIMELINE_CATEGORIES, TIMELINE_RESERVED_IDLE, TIMELINE_RESERVED_PAUSE, validateTimelineCategories } from "./categories.js";
import { classifyTimelineObservation } from "./classify.js";
import type { TimelineCard, TimelineCategory, TimelineDay, TimelineObservation, TimelinePause } from "./types.js";

export const TIMELINE_FORMAT_VERSION = 1;

/** Max inter-observation gap that still merges into one card. */
export const TIMELINE_MERGE_GAP_MS = 120_000;
/** Max dwell attributed past a card's last observation (digest parity). */
export const TIMELINE_MAX_DWELL_MS = 15 * 60_000;

export interface TimelineBuildInput {
  /** Local day, YYYY-MM-DD. */
  date: string;
  timezone: string;
  /** Stored observations for the day (e.g. from ActivityStore.listSnapshotsForDay). */
  observations: readonly TimelineObservation[];
  /** User-declared pauses (UTC, half-open); may overlap and extend past the day. */
  pauses?: readonly TimelinePause[];
  /** Registry override; validated. Defaults to the built-in registry. */
  categories?: readonly TimelineCategory[];
}

/** Canonical UTC ISO instant, or the raw string when unparseable (dropped later). */
function canonicalMs(iso: string): number {
  const parsed = Date.parse(iso);
  return Number.isFinite(parsed) ? parsed : Number.NaN;
}

function isoOf(ms: number): string {
  return new Date(ms).toISOString();
}

/** Content identity of one observation: machine + instant + content hash. */
function evidenceKeyOf(observation: TimelineObservation): string {
  return `${observation.machine}|${isoOf(canonicalMs(observation.capturedAtUtc))}|${observation.contentHash}`;
}

function stableCardId(identity: string): string {
  return `tlc_${createHash("sha256").update(identity, "utf8").digest("hex").slice(0, 16)}`;
}

function formatDurationMinutes(ms: number): string {
  return `${Math.round(ms / 60_000)}m`;
}

/** Union overlapping/adjacent [start,end) intervals; returns sorted, disjoint ms pairs. */
function unionIntervals(intervals: readonly (readonly [number, number])[]): Array<[number, number]> {
  const sorted = [...intervals].sort((a, b) => a[0] - b[0] || a[1] - b[1]);
  const merged: Array<[number, number]> = [];
  for (const interval of sorted) {
    const last = merged[merged.length - 1];
    if (last !== undefined && interval[0] <= last[1]) {
      last[1] = Math.max(last[1], interval[1]);
    } else {
      merged.push([interval[0], interval[1]]);
    }
  }
  return merged;
}

/** Remove [cutStart,cutEnd) from [start,end); returns the remaining pieces. */
function subtractInterval(start: number, end: number, cutStart: number, cutEnd: number): Array<[number, number]> {
  if (cutEnd <= start || cutStart >= end) return [[start, end]];
  const pieces: Array<[number, number]> = [];
  if (cutStart > start) pieces.push([start, cutStart]);
  if (cutEnd < end) pieces.push([cutEnd, end]);
  return pieces;
}

interface MergedObservations {
  machine: string;
  observations: TimelineObservation[];
}

/** Per-machine merge pass: compatibility + gap rules (see module doc). */
function mergeTrack(
  machine: string,
  track: TimelineObservation[],
  pauses: readonly (readonly [number, number])[],
): MergedObservations[] {
  const cards: MergedObservations[] = [];
  let current: TimelineObservation[] = [];
  const pauseStartsAfter = (fromMs: number, toMs: number): boolean =>
    pauses.some(([ps, pe]) => ps >= fromMs && ps < toMs && pe > ps);
  for (const observation of track) {
    const last = current[current.length - 1];
    if (last !== undefined) {
      const gap = canonicalMs(observation.capturedAtUtc) - canonicalMs(last.capturedAtUtc);
      const sameKey = observation.app === last.app && observation.windowTitle === last.windowTitle;
      const pauseBetween = pauseStartsAfter(canonicalMs(last.capturedAtUtc), canonicalMs(observation.capturedAtUtc));
      if (!sameKey || gap > TIMELINE_MERGE_GAP_MS || pauseBetween) {
        cards.push({ machine, observations: current });
        current = [];
      }
    }
    current.push(observation);
  }
  if (current.length > 0) cards.push({ machine, observations: current });
  return cards;
}

/** Build one replayable local day of timeline cards. Pure; throws on bad input. */
export function buildTimelineDay(input: TimelineBuildInput): TimelineDay {
  const categories = input.categories ?? DEFAULT_TIMELINE_CATEGORIES;
  validateTimelineCategories(categories);
  const window = activityDayWindow(input.date, input.timezone);
  const dayStartMs = Date.parse(window.startUtc);
  const dayEndMs = Date.parse(window.endUtc);

  // Observations: canonicalize, drop instants outside the day window.
  const observations = input.observations
    .filter((observation) => Number.isFinite(canonicalMs(observation.capturedAtUtc)))
    .filter((observation) => {
      const ms = canonicalMs(observation.capturedAtUtc);
      return ms >= dayStartMs && ms < dayEndMs;
    });

  // Pauses: validate instants, clip to the day, union overlaps.
  for (const pause of input.pauses ?? []) {
    const startMs = canonicalMs(pause.startUtc);
    const endMs = canonicalMs(pause.endUtc);
    if (!Number.isFinite(startMs) || !Number.isFinite(endMs) || startMs >= endMs) {
      throw new RangeError("timeline pause must be a valid half-open [startUtc, endUtc) interval");
    }
  }
  const pauseIntervals = unionIntervals(
    (input.pauses ?? [])
      .map((pause) => [canonicalMs(pause.startUtc), canonicalMs(pause.endUtc)] as const)
      .map(([startMs, endMs]) => [Math.max(startMs, dayStartMs), Math.min(endMs, dayEndMs)] as const)
      .filter(([startMs, endMs]) => endMs > startMs),
  );

  // Group per machine; sort by (instant, contentHash) — position-independent.
  const tracks = new Map<string, TimelineObservation[]>();
  for (const observation of observations) {
    const track = tracks.get(observation.machine) ?? [];
    track.push(observation);
    tracks.set(observation.machine, track);
  }
  for (const track of tracks.values()) {
    track.sort(
      (a, b) => canonicalMs(a.capturedAtUtc) - canonicalMs(b.capturedAtUtc) || (a.contentHash < b.contentHash ? -1 : a.contentHash > b.contentHash ? 1 : 0),
    );
  }

  const cards: TimelineCard[] = [];
  const machines = [...tracks.keys()].sort();
  for (const machine of machines) {
    const track = tracks.get(machine) ?? [];
    const merged = mergeTrack(machine, track, pauseIntervals);
    // [startMs, endMs] per merged card, reused by the idle pass below.
    const trackIntervals: Array<[number, number]> = [];
    for (let index = 0; index < merged.length; index++) {
      const group = merged[index];
      const first = group.observations[0];
      const last = group.observations[group.observations.length - 1];
      const startMs = canonicalMs(first.capturedAtUtc);
      const lastMs = canonicalMs(last.capturedAtUtc);
      const nextObsMs = index + 1 < merged.length ? canonicalMs(merged[index + 1].observations[0].capturedAtUtc) : Number.POSITIVE_INFINITY;
      const pauseStartMs = pauseIntervals.find(([ps]) => ps > lastMs)?.[0] ?? Number.POSITIVE_INFINITY;
      const endMs = Math.max(lastMs, Math.min(lastMs + TIMELINE_MAX_DWELL_MS, nextObsMs, pauseStartMs, dayEndMs));
      trackIntervals.push([startMs, endMs]);
      const evidenceIds = group.observations.map((observation) => observation.id);
      const classification = classifyTimelineObservation(first, categories);
      cards.push({
        id: stableCardId(`activity|${machine}|${evidenceKeyOf(first)}|${evidenceKeyOf(last)}`),
        kind: "activity",
        title: first.windowTitle.length > 0 ? first.windowTitle : first.app,
        summary: `${first.app} · ${machine} · ${evidenceIds.length} obs · ${formatDurationMinutes(endMs - startMs)}`,
        categoryId: classification.categoryId,
        confidence: classification.confidence,
        startUtc: isoOf(startMs),
        endUtc: isoOf(endMs),
        dayKey: input.date,
        timezone: input.timezone,
        machine,
        evidenceIds,
        evidenceRange: { firstKey: evidenceKeyOf(first), lastKey: evidenceKeyOf(last) },
      });
    }

    // Idle: uncovered remainders between consecutive cards on this track,
    // pauses removed (a pause wins over idle covering the same minutes).
    for (let index = 0; index + 1 < trackIntervals.length; index++) {
      const gapStart = trackIntervals[index][1];
      const gapEnd = trackIntervals[index + 1][0];
      if (gapEnd <= gapStart) continue;
      let pieces: Array<[number, number]> = [[gapStart, gapEnd]];
      for (const [pauseStart, pauseEnd] of pauseIntervals) {
        pieces = pieces.flatMap(([start, end]) => subtractInterval(start, end, pauseStart, pauseEnd));
      }
      for (const [start, end] of pieces) {
        cards.push({
          id: stableCardId(`idle|${machine}|${isoOf(start)}|${isoOf(end)}`),
          kind: "idle",
          title: "Idle",
          summary: `${formatDurationMinutes(end - start)} gap on ${machine}`,
          categoryId: TIMELINE_RESERVED_IDLE,
          confidence: 1,
          startUtc: isoOf(start),
          endUtc: isoOf(end),
          dayKey: input.date,
          timezone: input.timezone,
          machine,
          evidenceIds: [],
          evidenceRange: null,
        });
      }
    }
  }

  for (const [pauseStart, pauseEnd] of pauseIntervals) {
    const reason = (input.pauses ?? []).find((pause) => canonicalMs(pause.startUtc) === pauseStart)?.reason;
    cards.push({
      id: stableCardId(`pause|${isoOf(pauseStart)}|${isoOf(pauseEnd)}`),
      kind: "pause",
      title: "Paused",
      summary: reason === undefined ? `${formatDurationMinutes(pauseEnd - pauseStart)} user pause` : `${formatDurationMinutes(pauseEnd - pauseStart)} user pause — ${reason}`,
      categoryId: TIMELINE_RESERVED_PAUSE,
      confidence: 1,
      startUtc: isoOf(pauseStart),
      endUtc: isoOf(pauseEnd),
      dayKey: input.date,
      timezone: input.timezone,
      machine: null,
      evidenceIds: [],
      evidenceRange: null,
    });
  }

  cards.sort((a, b) => a.startUtc < b.startUtc ? -1 : a.startUtc > b.startUtc ? 1 : a.endUtc < b.endUtc ? -1 : a.endUtc > b.endUtc ? 1 : (a.machine ?? "") < (b.machine ?? "") ? -1 : (a.machine ?? "") > (b.machine ?? "") ? 1 : a.id < b.id ? -1 : a.id > b.id ? 1 : 0);

  return {
    formatVersion: TIMELINE_FORMAT_VERSION,
    date: input.date,
    timezone: input.timezone,
    startUtc: window.startUtc,
    endUtc: window.endUtc,
    cards,
  };
}

/**
 * Canonical byte-stable serialization. Card objects are constructed in a
 * fixed field order, so `JSON.stringify` output is stable across runs.
 */
export function serializeTimelineDay(day: TimelineDay): string {
  return JSON.stringify(day);
}

/**
 * Timeline range/search query (issue #1983 PR1).
 *
 * Pure functions over an in-memory card list. Half-open UTC [from, to).
 * A zero-length range is an instant: include the card whose [start, end)
 * contains it. Search returns distinct empty vs store_unreadable shapes.
 *
 * Config: activity.timeline.qa.{enabled, maxRangeDays}.
 * MCP/HTTP and recall injection are later PRs.
 */
import { parseFlexibleIsoTimestamp } from "../../utils/iso-timestamp.js";
import type { PluginConfig } from "../../types.js";
import type { ActivityTimelineQaConfig } from "../types.js";
import { runTimelinePublishCli } from "./publish-cli.js";
import type { TimelineCard } from "./types.js";

const RANGE_FORMATS = ["cards", "compact"] as const;
const MS_PER_DAY = 86_400_000;
const DEFAULT_MAX_RANGE_DAYS = 31;
const DEFAULT_SEARCH_LIMIT = 10;
const MIN_SEARCH_LIMIT = 1;
const MAX_SEARCH_LIMIT = 50;

export type TimelineRangeFormat = (typeof RANGE_FORMATS)[number];

/** Card fields the query layer reads; later slices may add optional extras. */
export type TimelineQueryCard = TimelineCard & {
  detailedSummary?: string;
  distraction?: boolean;
};

export interface TimelineRangeQuery {
  from: string;
  to: string;
  categories?: readonly string[];
  includeDistractions?: boolean;
  format: TimelineRangeFormat;
  maxRangeDays?: number;
}

export interface TimelineCompactCard {
  start: string;
  end: string;
  category: string;
  title: string;
  summary: string;
}

export interface TimelineCompactRange {
  day: string;
  cards: TimelineCompactCard[];
}

export interface TimelineSearchQuery {
  query: string;
  from?: string;
  to?: string;
  limit?: number;
}

export type TimelineSearchResult =
  | { ok: true; results: TimelineQueryCard[] }
  | { ok: false; error: "store_unreadable" };

export interface TimelineCliIo {
  stdout: { write(chunk: string): unknown };
  stderr: { write(chunk: string): unknown };
}

/** Inject cards so CLI tests never need ActivityStore. */
export interface TimelineCliDeps {
  cards: readonly TimelineQueryCard[] | null;
  qa: ActivityTimelineQaConfig;
  timelineEnabled?: boolean;
  /** Required for `publish`; range/search never read it. */
  config?: PluginConfig;
  /** Production host loads cards through regenerateTimelineDay. */
  loadCards?: (window: { from?: string; to?: string }) => Promise<readonly TimelineQueryCard[] | null>;
}

const USAGE = `Usage: timeline <command> [options]

Commands:
  range --from <ISO> --to <ISO> [--format cards|compact] [--categories id,id] [--include-distractions]
  search --query <text> [--from <ISO>] [--to <ISO>] [--limit N]
  publish [--date YYYY-MM-DD] [--what timeline] [--dry-run]
`;

// Per-subcommand flag allow-lists (issue #1985 review): a shared union table
// let `timeline publish --from …` parse and then silently discard `--from`,
// publishing today's note on a query-only flag — and `range --date` likewise.
// Every subcommand validates its own syntax before dispatch.
const PUBLISH_FLAGS = {
  value: { "--date": true, "--week": true, "--what": true } as Record<string, true>,
  boolean: { "--dry-run": true } as Record<string, true>,
};
const RANGE_FLAGS = {
  value: { "--from": true, "--to": true, "--format": true, "--categories": true } as Record<string, true>,
  boolean: { "--include-distractions": true } as Record<string, true>,
};
const SEARCH_FLAGS = {
  value: { "--query": true, "--from": true, "--to": true, "--limit": true } as Record<string, true>,
  boolean: {} as Record<string, true>,
};

function parseInstant(value: string, label: string): number {
  const ms = parseFlexibleIsoTimestamp(value);
  if (ms === null) {
    throw new TypeError(`${label} must be an ISO date or datetime`);
  }
  return ms;
}

function assertRange(fromMs: number, toMs: number, maxRangeDays: number): void {
  if (fromMs > toMs) {
    throw new RangeError("reversed range: from must be <= to");
  }
  if (fromMs === toMs) return;
  if (toMs - fromMs > maxRangeDays * MS_PER_DAY) {
    throw new RangeError(`range exceeds timeline.qa.maxRangeDays (${maxRangeDays})`);
  }
}

/**
 * Validate a range request completely - format, instants, ordering, and
 * qa.maxRangeDays - with no card access. Production callers must run this
 * before any side-effecting card loader so an invalid range fails before
 * day regeneration or analysis spend.
 */
export function validateTimelineRangeQuery(query: {
  from: string;
  to: string;
  format: string;
  maxRangeDays?: number;
}): void {
  if (!RANGE_FORMATS.includes(query.format as TimelineRangeFormat)) {
    throw new TypeError(`format must be one of: ${RANGE_FORMATS.join(", ")}`);
  }
  const maxRangeDays = query.maxRangeDays ?? DEFAULT_MAX_RANGE_DAYS;
  assertRange(parseInstant(query.from, "from"), parseInstant(query.to, "to"), maxRangeDays);
}

/** Validate optional search bounds the way queryTimelineSearch applies them. */
export function validateTimelineSearchBounds(bounds: { from?: string; to?: string }): void {
  const fromMs = parseInstant(bounds.from ?? bounds.to!, "from");
  const toMs = parseInstant(bounds.to ?? bounds.from!, "to");
  assertRange(fromMs, toMs, DEFAULT_MAX_RANGE_DAYS);
}

function cardOverlaps(card: TimelineQueryCard, fromMs: number, toMs: number): boolean {
  const start = Date.parse(card.startUtc);
  const end = Date.parse(card.endUtc);
  if (fromMs === toMs) return start <= fromMs && fromMs < end;
  return start < toMs && end > fromMs;
}

function passesFilters(
  card: TimelineQueryCard,
  categories: ReadonlySet<string> | undefined,
  includeDistractions: boolean,
): boolean {
  if (!includeDistractions && card.distraction === true) return false;
  if (categories && !categories.has(card.categoryId)) return false;
  return true;
}

function filterRange(
  cards: readonly TimelineQueryCard[],
  fromMs: number,
  toMs: number,
  categories: ReadonlySet<string> | undefined,
  includeDistractions: boolean,
): TimelineQueryCard[] {
  return cards.filter(
    (card) => cardOverlaps(card, fromMs, toMs) && passesFilters(card, categories, includeDistractions),
  );
}

function toCompact(cards: readonly TimelineQueryCard[], from: string): TimelineCompactRange {
  const day = from.length >= 10 ? from.slice(0, 10) : cards[0]?.dayKey ?? from;
  return {
    day,
    cards: cards.map((card) => ({
      start: card.startUtc,
      end: card.endUtc,
      category: card.categoryId,
      title: card.title,
      summary: card.summary,
    })),
  };
}

export function queryTimelineRange(
  cards: readonly TimelineQueryCard[],
  query: TimelineRangeQuery,
): TimelineCard[] | TimelineCompactRange {
  if (!RANGE_FORMATS.includes(query.format)) {
    throw new TypeError(`format must be one of: ${RANGE_FORMATS.join(", ")}`);
  }
  const maxRangeDays = query.maxRangeDays ?? DEFAULT_MAX_RANGE_DAYS;
  const fromMs = parseInstant(query.from, "from");
  const toMs = parseInstant(query.to, "to");
  assertRange(fromMs, toMs, maxRangeDays);
  const categories = query.categories ? new Set(query.categories) : undefined;
  const matched = filterRange(cards, fromMs, toMs, categories, query.includeDistractions === true);
  if (query.format === "compact") return toCompact(matched, query.from);
  return matched;
}

function haystack(card: TimelineQueryCard): string {
  const parts = [card.title, card.summary];
  if (card.detailedSummary) parts.push(card.detailedSummary);
  return parts.join(" ").toLowerCase();
}

function tokenMatchCount(card: TimelineQueryCard, tokens: readonly string[]): number {
  const text = haystack(card);
  let count = 0;
  for (const token of tokens) {
    if (text.includes(token)) count += 1;
  }
  return count;
}

export function queryTimelineSearch(
  cards: readonly TimelineQueryCard[] | null | undefined,
  query: TimelineSearchQuery,
): TimelineSearchResult {
  if (!Array.isArray(cards)) return { ok: false, error: "store_unreadable" };
  const tokens = query.query.trim().toLowerCase().split(/\s+/).filter(Boolean);
  const limit = query.limit ?? DEFAULT_SEARCH_LIMIT;
  if (!Number.isInteger(limit) || limit < MIN_SEARCH_LIMIT || limit > MAX_SEARCH_LIMIT) {
    throw new RangeError(`limit must be an integer from ${MIN_SEARCH_LIMIT} to ${MAX_SEARCH_LIMIT}`);
  }
  let pool = cards;
  if (query.from !== undefined || query.to !== undefined) {
    const fromMs = parseInstant(query.from ?? query.to!, "from");
    const toMs = parseInstant(query.to ?? query.from!, "to");
    assertRange(fromMs, toMs, DEFAULT_MAX_RANGE_DAYS);
    pool = filterRange(cards, fromMs, toMs, undefined, true);
  }
  if (tokens.length === 0) return { ok: true, results: [] };
  const ranked = pool
    .map((card) => ({ card, matches: tokenMatchCount(card, tokens) }))
    .filter((row) => row.matches > 0)
    .sort((a, b) => {
      if (a.matches !== b.matches) return b.matches - a.matches;
      const recency = Date.parse(b.card.endUtc) - Date.parse(a.card.endUtc);
      if (recency !== 0) return recency;
      return a.card.id < b.card.id ? -1 : a.card.id > b.card.id ? 1 : 0;
    })
    .slice(0, limit)
    .map((row) => row.card);
  return { ok: true, results: ranked };
}

function parseFlags(
  args: string[],
  spec: { value: Record<string, true>; boolean: Record<string, true> },
): { flags: Map<string, string | true>; positional: string[] } {
  const flags = new Map<string, string | true>();
  const positional: string[] = [];
  for (let i = 0; i < args.length; i += 1) {
    const arg = args[i]!;
    if (!arg.startsWith("--")) {
      positional.push(arg);
      continue;
    }
    if (spec.value[arg] === true) {
      const value = args[i + 1];
      if (value === undefined || value.startsWith("--")) {
        throw new TypeError(`flag ${arg} requires a value`);
      }
      flags.set(arg, value);
      i += 1;
      continue;
    }
    if (spec.boolean[arg] === true) {
      flags.set(arg, true);
      continue;
    }
    const known = [...Object.keys(spec.value), ...Object.keys(spec.boolean)].sort().join(", ");
    throw new TypeError(`unknown flag ${arg} (valid: ${known})`);
  }
  return { flags, positional };
}

function flagString(flags: Map<string, string | true>, name: string): string | undefined {
  const value = flags.get(name);
  return typeof value === "string" ? value : undefined;
}

/** Shared CLI runner. `deps.cards` may be an in-memory fixture. */
export async function runTimelineCliCommand(
  deps: TimelineCliDeps,
  args: string[],
  io: TimelineCliIo,
): Promise<number> {
  const [command, ...rest] = args;
  try {
    if (command === undefined || command === "help" || command === "--help") {
      io.stdout.write(USAGE);
      return command === undefined ? 1 : 0;
    }
    // `publish` writes into the user's vault and is not a qa/query surface,
    // so it dispatches before the qa gate. Flags are validated against the
    // publish-only set: `--from`/`--format` are query syntax and must be
    // rejected here, not silently dropped while today's note is published.
    if (command === "publish") {
      if (deps.config === undefined) {
        io.stderr.write("timeline publish requires the Remnic config — run `remnic doctor`\n");
        return 1;
      }
      const { flags: publishFlags, positional } = parseFlags(rest, PUBLISH_FLAGS);
      // `publish` takes flags only (issue #2917): a stray positional used
      // to be silently discarded while today's note published.
      if (positional.length > 0) {
        throw new TypeError(
          `timeline publish takes no positional arguments (got ${JSON.stringify(positional.join(" "))})`,
        );
      }
      return runTimelinePublishCli(
        deps.config,
        {
          date: flagString(publishFlags, "--date"),
          week: flagString(publishFlags, "--week"),
          what: flagString(publishFlags, "--what"),
          dryRun: publishFlags.get("--dry-run") === true,
        },
        io,
      );
    }
    if (deps.timelineEnabled === false || !deps.qa.enabled) {
      io.stderr.write("timeline qa disabled — set activity.timeline.qa.enabled=true\n");
      return 1;
    }
    const { flags } = parseFlags(rest, command === "range" ? RANGE_FLAGS : SEARCH_FLAGS);
    if (command === "range") {
      const from = flagString(flags, "--from");
      const to = flagString(flags, "--to");
      if (!from || !to) throw new TypeError("range requires --from and --to");
      const formatRaw = flagString(flags, "--format") ?? "compact";
      if (formatRaw !== "cards" && formatRaw !== "compact") {
        throw new TypeError("format must be one of: cards, compact");
      }
      // Validate the complete request before the side-effecting loader: an
      // over-wide or malformed range must fail before any day regeneration
      // or analysis spend.
      validateTimelineRangeQuery({ from, to, format: formatRaw, maxRangeDays: deps.qa.maxRangeDays });
      const cards = Array.isArray(deps.cards)
        ? deps.cards
        : deps.loadCards === undefined
          ? null
          : await deps.loadCards({ from, to });
      if (!Array.isArray(cards)) {
        io.stderr.write("store_unreadable\n");
        return 1;
      }
      const categoriesRaw = flagString(flags, "--categories");
      const result = queryTimelineRange(cards, {
        from,
        to,
        format: formatRaw,
        categories: categoriesRaw ? categoriesRaw.split(",").filter(Boolean) : undefined,
        includeDistractions: flags.get("--include-distractions") === true,
        maxRangeDays: deps.qa.maxRangeDays,
      });
      io.stdout.write(`${JSON.stringify(result)}\n`);
      return 0;
    }
    if (command === "search") {
      const q = flagString(flags, "--query");
      if (q === undefined) throw new TypeError("search requires --query");
      const limitRaw = flagString(flags, "--limit");
      const limit = limitRaw === undefined ? undefined : Number(limitRaw);
      if (limitRaw !== undefined && !Number.isInteger(limit)) {
        throw new RangeError("limit must be an integer from 1 to 50");
      }
      const from = flagString(flags, "--from");
      const to = flagString(flags, "--to");
      // Bounds are validated before the side-effecting loader so a malformed
      // or over-wide window fails before any day regeneration or analysis.
      if (from !== undefined || to !== undefined) {
        validateTimelineSearchBounds({ from, to });
      }
      const cards = Array.isArray(deps.cards)
        ? deps.cards
        : deps.loadCards === undefined
          ? null
          : await deps.loadCards({ from, to });
      const result = queryTimelineSearch(cards, {
        query: q,
        from,
        to,
        limit,
      });
      io.stdout.write(`${JSON.stringify(result)}\n`);
      return result.ok ? 0 : 1;
    }
    throw new TypeError(`unknown command ${command} (valid: range, search, publish)`);
  } catch (err) {
    io.stderr.write(`${err instanceof Error ? err.message : String(err)}\n`);
    return 1;
  }
}

/**
 * Timeline correction store (issue #2049): manual card/category edits that
 * survive day rebuilds. Corrections are keyed by the card's stable
 * content-derived id, so rebuilding the same evidence reproduces the same
 * card ids and re-applies the edit; an explicit `reset()` reverts a card to
 * its derived values. Corrections are user edits, not evidence — they live in
 * their own small SQLite file, never in the #1899 snapshot store.
 */

import { mkdirSync } from "node:fs";
import path from "node:path";

import { openBetterSqlite3, type BetterSqlite3Database } from "../../runtime/better-sqlite.js";
import { DEFAULT_TIMELINE_CATEGORIES, validateTimelineCategories } from "./categories.js";
import type { TimelineCard, TimelineCategory, TimelineCorrection } from "./types.js";

export function timelineCorrectionDatabasePath(memoryDir: string): string {
  return path.join(memoryDir, "state", "activity-timeline.sqlite");
}

interface CorrectionRow {
  card_id: string;
  category_id: string | null;
  title: string | null;
  edited_at_utc: string;
}

function rowToCorrection(row: CorrectionRow): TimelineCorrection {
  return {
    cardId: row.card_id,
    categoryId: row.category_id ?? undefined,
    title: row.title ?? undefined,
    editedAtUtc: row.edited_at_utc,
  };
}

export class TimelineCorrectionStore {
  private readonly db: BetterSqlite3Database;

  constructor(db: BetterSqlite3Database) {
    this.db = db;
  }

  static open(memoryDir: string): TimelineCorrectionStore {
    mkdirSync(path.join(memoryDir, "state"), { recursive: true });
    const db = openBetterSqlite3(timelineCorrectionDatabasePath(memoryDir));
    db.pragma("journal_mode = WAL");
    db.pragma("busy_timeout = 5000");
    db.exec(`
      CREATE TABLE IF NOT EXISTS timeline_corrections (
        card_id       TEXT PRIMARY KEY,
        category_id   TEXT,
        title         TEXT,
        edited_at_utc TEXT NOT NULL
      );
    `);
    return new TimelineCorrectionStore(db);
  }

  /**
   * Persist one correction. `categoryId`, when set, must exist in `categories`
   * (defaults to the built-in registry) — an unknown category is a malformed
   * edit and must fail rather than silently strand the card.
   */
  upsert(correction: TimelineCorrection, categories: readonly TimelineCategory[] = DEFAULT_TIMELINE_CATEGORIES): void {
    validateTimelineCategories(categories);
    if (typeof correction.cardId !== "string" || correction.cardId.length === 0) {
      throw new RangeError("timeline correction requires a non-empty cardId");
    }
    if (typeof correction.editedAtUtc !== "string" || Number.isNaN(Date.parse(correction.editedAtUtc))) {
      throw new RangeError("timeline correction requires a valid editedAtUtc instant");
    }
    if ((correction.categoryId === undefined && correction.title === undefined) || (correction.title !== undefined && correction.title.length === 0)) {
      throw new RangeError("timeline correction must set a categoryId and/or a non-empty title");
    }
    if (correction.categoryId !== undefined && !categories.some((category) => category.id === correction.categoryId)) {
      throw new RangeError(`timeline correction targets unknown category: ${correction.categoryId}`);
    }
    this.db
      .prepare(
        `INSERT INTO timeline_corrections (card_id, category_id, title, edited_at_utc)
         VALUES (?, ?, ?, ?)
         ON CONFLICT(card_id) DO UPDATE SET category_id = excluded.category_id, title = excluded.title, edited_at_utc = excluded.edited_at_utc`,
      )
      .run(correction.cardId, correction.categoryId ?? null, correction.title ?? null, correction.editedAtUtc);
  }

  get(cardId: string): TimelineCorrection | undefined {
    const row = this.db.prepare("SELECT card_id, category_id, title, edited_at_utc FROM timeline_corrections WHERE card_id = ?").get(cardId);
    return row === undefined ? undefined : rowToCorrection(row as CorrectionRow);
  }

  /** All corrections ordered by card id (deterministic listing). */
  list(): TimelineCorrection[] {
    return this.db
      .prepare("SELECT card_id, category_id, title, edited_at_utc FROM timeline_corrections ORDER BY card_id ASC")
      .all()
      .map((row) => rowToCorrection(row as CorrectionRow));
  }

  /** Explicitly reset a card to its derived values; true when a correction existed. */
  reset(cardId: string): boolean {
    return this.db.prepare("DELETE FROM timeline_corrections WHERE card_id = ?").run(cardId).changes > 0;
  }

  close(): void {
    this.db.close();
  }
}

/** Corrections whose cardId is in `cards`, in incoming list order. */
export function correctionsForCards(
  cards: readonly TimelineCard[],
  corrections: readonly TimelineCorrection[],
): TimelineCorrection[] {
  const ids = new Set(cards.map((card) => card.id));
  return corrections.filter((correction) => ids.has(correction.cardId));
}

/**
 * Apply corrections to built cards. Overrides title/category, sets confidence
 * to 1 (a human confirmed it), and stamps manual-edit provenance. Uncorrected
 * cards pass through untouched, so serialization stays byte-stable for them.
 */
export function applyTimelineCorrections(
  cards: readonly TimelineCard[],
  corrections: readonly TimelineCorrection[],
): TimelineCard[] {
  const byCardId = new Map(corrections.map((correction) => [correction.cardId, correction]));
  return cards.map((card) => {
    const correction = byCardId.get(card.id);
    if (correction === undefined) return card;
    return {
      id: card.id,
      kind: card.kind,
      title: correction.title ?? card.title,
      summary: card.summary,
      categoryId: correction.categoryId ?? card.categoryId,
      confidence: 1,
      startUtc: card.startUtc,
      endUtc: card.endUtc,
      dayKey: card.dayKey,
      timezone: card.timezone,
      machine: card.machine,
      evidenceIds: card.evidenceIds,
      evidenceRange: card.evidenceRange,
      manualEdit: {
        ...(correction.categoryId !== undefined ? { categoryId: correction.categoryId } : {}),
        ...(correction.title !== undefined ? { title: correction.title } : {}),
        editedAtUtc: correction.editedAtUtc,
      },
    };
  });
}

/**
 * Deterministic daily journal recap from timeline cards (issue #2051).
 *
 * Pure: cards + date + timezone in, Markdown out. No LLM, no I/O.
 * Same cards always produce the same bytes. Empty days still yield a
 * valid file body. Does not invent people, mood, or productivity claims.
 */
import { activityDayWindow } from "../digest.js";
import type { TimelineCardKind } from "./types.js";

/**
 * Minimal card shape the renderer reads. `TimelineCard` is assignable, and
 * so is the privacy-projected export card whose `title` is stripped
 * (issue #2051): a title-less card renders its stable id instead.
 */
export interface JournalRenderCard {
  id: string;
  kind: TimelineCardKind;
  title?: string;
  categoryId: string;
  startUtc: string;
  endUtc: string;
}
export interface DeterministicJournalOptions {
  date: string;
  timezone: string;
}

interface ClippedCard {
  card: JournalRenderCard;
  startMs: number;
  endMs: number;
  durationMs: number;
}

function formatMinutes(ms: number): string {
  return `${Math.round(ms / 60_000)}m`;
}

function clipToWindow(
  cards: readonly JournalRenderCard[],
  winStart: number,
  winEnd: number,
): ClippedCard[] {
  const clipped: ClippedCard[] = [];
  for (const card of cards) {
    const start = Date.parse(card.startUtc);
    const end = Date.parse(card.endUtc);
    if (!Number.isFinite(start) || !Number.isFinite(end)) continue;
    const startMs = Math.max(start, winStart);
    const endMs = Math.min(end, winEnd);
    if (endMs <= startMs) continue;
    clipped.push({ card, startMs, endMs, durationMs: endMs - startMs });
  }
  clipped.sort((left, right) => {
    const byStart = left.startMs - right.startMs;
    if (byStart !== 0) return byStart;
    const byTitle = (left.card.title ?? "").localeCompare(right.card.title ?? "");
    if (byTitle !== 0) return byTitle;
    return left.card.id.localeCompare(right.card.id);
  });
  return clipped;
}

function categoryLines(clipped: readonly ClippedCard[]): string[] {
  const totals = new Map<string, number>();
  for (const row of clipped) {
    totals.set(row.card.categoryId, (totals.get(row.card.categoryId) ?? 0) + row.durationMs);
  }
  const rows = [...totals.entries()].sort((left, right) => {
    const byDuration = right[1] - left[1];
    return byDuration !== 0 ? byDuration : left[0].localeCompare(right[0]);
  });
  if (rows.length === 0) return ["_No categories._"];
  return rows.map(([categoryId, durationMs]) => `- ${formatMinutes(durationMs)} ${categoryId}`);
}

function mergeIntervals(intervals: readonly (readonly [number, number])[]): Array<[number, number]> {
  const ordered = [...intervals].sort((left, right) => left[0] - right[0] || left[1] - right[1]);
  const merged: Array<[number, number]> = [];
  for (const [start, end] of ordered) {
    const last = merged[merged.length - 1];
    if (!last || start > last[1]) merged.push([start, end]);
    else last[1] = Math.max(last[1], end);
  }
  return merged;
}

function countGaps(
  winStart: number,
  winEnd: number,
  intervals: readonly (readonly [number, number])[],
): number {
  const merged = mergeIntervals(intervals);
  let gaps = 0;
  let cursor = winStart;
  for (const [start, end] of merged) {
    if (start > cursor) gaps += 1;
    cursor = Math.max(cursor, end);
  }
  if (cursor < winEnd) gaps += 1;
  return gaps;
}

/** Render a byte-stable Markdown journal for one local day. */
export function renderDeterministicJournal(
  cards: readonly JournalRenderCard[],
  options: DeterministicJournalOptions,
): string {
  const window = activityDayWindow(options.date, options.timezone);
  const winStart = Date.parse(window.startUtc);
  const winEnd = Date.parse(window.endUtc);
  const clipped = clipToWindow(cards, winStart, winEnd);
  const idle = clipped.filter((row) => row.card.kind === "idle").length;
  const pause = clipped.filter((row) => row.card.kind === "pause").length;
  const gaps = countGaps(
    winStart,
    winEnd,
    clipped.map((row) => [row.startMs, row.endMs]),
  );
  const cardLines =
    clipped.length === 0
      ? ["_No cards._"]
      : clipped.map((row) => `- ${formatMinutes(row.durationMs)} ${row.card.title ?? row.card.id}`);
  return [
    `# Journal — ${options.date} (${options.timezone})`,
    "",
    "## Categories",
    "",
    ...categoryLines(clipped),
    "",
    "## Cards",
    "",
    ...cardLines,
    "",
    "## Gaps / idle / pause",
    "",
    `- Gaps: ${gaps}`,
    `- Idle: ${idle}`,
    `- Pause: ${pause}`,
    "",
  ].join("\n");
}

/**
 * Persist a deterministic daily journal recap (issue #2051).
 *
 * Writes journal/<YYYY-MM-DD>.md through writeJournalFile. Existing files
 * stay byte-identical unless force is set. Body is renderDeterministicJournal.
 */
import { journalPath, writeJournalFile } from "../journal.js";
import { renderDeterministicJournal } from "./journal-recap.js";
import type { TimelineCard } from "./types.js";

export interface PersistDeterministicJournalInput {
  memoryDir: string;
  date: string;
  cards: readonly TimelineCard[];
  timezone: string;
  force?: boolean;
}

export interface PersistDeterministicJournalResult {
  path: string;
  wrote: boolean;
}

export function persistDeterministicJournal(
  input: PersistDeterministicJournalInput,
): PersistDeterministicJournalResult {
  const filePath = journalPath(input.memoryDir, input.date);
  const wrote = writeJournalFile(
    filePath,
    renderDeterministicJournal(input.cards, {
      date: input.date,
      timezone: input.timezone,
    }),
    input.force === true,
  );
  return { path: filePath, wrote };
}

/**
 * Deterministic weekly time/activity summary over timeline cards (issue #2052).
 *
 * Pure: cards + week bounds + category registry in, snapshot out. Half-open
 * UTC [weekStart, weekEnd). Previous-period comparison is omitted in this
 * slice and marked unavailable, never a silent zero. Later surfaces
 * (CLI/MCP/HTTP/UI) consume this shape; they are not built here.
 */
import { parseFlexibleIsoTimestamp } from "../../utils/iso-timestamp.js";
import { activityDayWindow, assertValidTimezone } from "../digest.js";
import type { WeeklyPreviousPeriod } from "./week-previous.js";
import type { TimelineCard, TimelineCardKind, TimelineCategory } from "./types.js";

export const WEEKLY_ACTIVITY_FORMAT_VERSION = 1;

export interface WeeklyActivityOptions {
  timezone: string;
  weekStartUtc: string;
  weekEndUtc: string;
  categories: readonly TimelineCategory[];
}

export interface WeeklyCategoryTotal {
  categoryId: string;
  durationMs: number;
}

export interface WeeklyKindTotals {
  activeMs: number;
  idleMs: number;
  pauseMs: number;
  gapMs: number;
  unclassifiedMs: number;
}

export interface WeeklyDayTotal extends WeeklyKindTotals {
  date: string;
  startUtc: string;
  endUtc: string;
  categories: WeeklyCategoryTotal[];
}

/** First slice never computes a prior week; the field is present so callers cannot treat absence as zero. */
export interface WeeklyPreviousPeriodUnavailable {
  available: false;
}

export interface WeeklyActivitySummary extends WeeklyKindTotals {
  formatVersion: number;
  timezone: string;
  weekStartUtc: string;
  weekEndUtc: string;
  categories: WeeklyCategoryTotal[];
  days: WeeklyDayTotal[];
  previousPeriod: WeeklyPreviousPeriod;
}

interface Acc extends WeeklyKindTotals {
  byCategory: Map<string, number>;
  intervals: Array<[number, number]>;
}

function parseBound(value: string, label: string): number {
  const ms = parseFlexibleIsoTimestamp(value);
  if (ms === null) {
    throw new RangeError(`${label} is not a valid ISO timestamp`);
  }
  return ms;
}

function clip(start: number, end: number, winStart: number, winEnd: number): [number, number] | null {
  const clippedStart = Math.max(start, winStart);
  const clippedEnd = Math.min(end, winEnd);
  return clippedEnd > clippedStart ? [clippedStart, clippedEnd] : null;
}

function unionDuration(intervals: readonly (readonly [number, number])[]): number {
  const sorted = [...intervals].sort((a, b) => a[0] - b[0] || a[1] - b[1]);
  let total = 0;
  let curStart = Number.NaN;
  let curEnd = Number.NaN;
  for (const [start, end] of sorted) {
    if (!Number.isFinite(curStart)) {
      curStart = start;
      curEnd = end;
      continue;
    }
    if (start <= curEnd) {
      curEnd = Math.max(curEnd, end);
      continue;
    }
    total += curEnd - curStart;
    curStart = start;
    curEnd = end;
  }
  if (Number.isFinite(curStart)) total += curEnd - curStart;
  return total;
}

function localDateOf(ms: number, timezone: string): string {
  const parts = new Intl.DateTimeFormat("en-CA", {
    timeZone: timezone,
    year: "numeric",
    month: "2-digit",
    day: "2-digit",
  }).formatToParts(new Date(ms));
  const get = (type: string): string => parts.find((part) => part.type === type)?.value ?? "";
  return `${get("year")}-${get("month")}-${get("day")}`;
}

function shiftIsoDate(date: string, days: number): string {
  const parsed = new Date(`${date}T00:00:00Z`);
  parsed.setUTCDate(parsed.getUTCDate() + days);
  return parsed.toISOString().slice(0, 10);
}

function daysOverlappingWeek(
  weekStartMs: number,
  weekEndMs: number,
  timezone: string,
): Array<{ date: string; startMs: number; endMs: number }> {
  if (weekEndMs <= weekStartMs) return [];
  let date = localDateOf(weekStartMs, timezone);
  let window = activityDayWindow(date, timezone);
  if (Date.parse(window.startUtc) > weekStartMs) {
    date = shiftIsoDate(date, -1);
    window = activityDayWindow(date, timezone);
  }
  const days: Array<{ date: string; startMs: number; endMs: number }> = [];
  while (Date.parse(window.startUtc) < weekEndMs) {
    const startMs = Math.max(Date.parse(window.startUtc), weekStartMs);
    const endMs = Math.min(Date.parse(window.endUtc), weekEndMs);
    if (endMs > startMs) days.push({ date, startMs, endMs });
    date = shiftIsoDate(date, 1);
    window = activityDayWindow(date, timezone);
  }
  return days;
}

function emptyAcc(categoryIds: readonly string[]): Acc {
  return {
    activeMs: 0,
    idleMs: 0,
    pauseMs: 0,
    gapMs: 0,
    unclassifiedMs: 0,
    byCategory: new Map(categoryIds.map((id) => [id, 0])),
    intervals: [],
  };
}

function addClipped(acc: Acc, kind: TimelineCardKind, categoryId: string, known: ReadonlySet<string>, start: number, end: number): void {
  const duration = end - start;
  acc.intervals.push([start, end]);
  if (kind === "idle") acc.idleMs += duration;
  else if (kind === "pause") acc.pauseMs += duration;
  else acc.activeMs += duration;
  if (known.has(categoryId)) {
    acc.byCategory.set(categoryId, (acc.byCategory.get(categoryId) ?? 0) + duration);
  } else {
    acc.unclassifiedMs += duration;
  }
}

function sortCategoryTotals(byCategory: Map<string, number>): WeeklyCategoryTotal[] {
  return [...byCategory.entries()]
    .map(([categoryId, durationMs]) => ({ categoryId, durationMs }))
    .sort((a, b) => b.durationMs - a.durationMs || (a.categoryId < b.categoryId ? -1 : a.categoryId > b.categoryId ? 1 : 0));
}

function finish(acc: Acc, windowMs: number): WeeklyKindTotals & { categories: WeeklyCategoryTotal[] } {
  const covered = unionDuration(acc.intervals);
  return {
    activeMs: acc.activeMs,
    idleMs: acc.idleMs,
    pauseMs: acc.pauseMs,
    gapMs: Math.max(0, windowMs - covered),
    unclassifiedMs: acc.unclassifiedMs,
    categories: sortCategoryTotals(acc.byCategory),
  };
}

/** Build a time/activity summary for one half-open week. Pure. */
export function buildWeeklyActivitySummary(
  cards: readonly TimelineCard[],
  options: WeeklyActivityOptions,
): WeeklyActivitySummary {
  assertValidTimezone(options.timezone);
  const weekStartMs = parseBound(options.weekStartUtc, "weekStartUtc");
  const weekEndMs = parseBound(options.weekEndUtc, "weekEndUtc");
  if (weekStartMs > weekEndMs) {
    throw new RangeError("reversed range: weekStartUtc must be <= weekEndUtc");
  }

  const categoryIds = options.categories.map((category) => category.id);
  const known = new Set(categoryIds);
  const week = emptyAcc(categoryIds);
  const dayWindows = daysOverlappingWeek(weekStartMs, weekEndMs, options.timezone);
  const dayAccs = dayWindows.map(() => emptyAcc(categoryIds));

  for (const card of cards) {
    const start = Date.parse(card.startUtc);
    const end = Date.parse(card.endUtc);
    if (!Number.isFinite(start) || !Number.isFinite(end) || end <= start) continue;
    const weekClip = clip(start, end, weekStartMs, weekEndMs);
    if (!weekClip) continue;
    addClipped(week, card.kind, card.categoryId, known, weekClip[0], weekClip[1]);
    for (let i = 0; i < dayWindows.length; i++) {
      const day = dayWindows[i];
      const dayClip = clip(start, end, day.startMs, day.endMs);
      if (dayClip) addClipped(dayAccs[i], card.kind, card.categoryId, known, dayClip[0], dayClip[1]);
    }
  }

  const weekTotals = finish(week, weekEndMs - weekStartMs);
  const days: WeeklyDayTotal[] = dayWindows.map((day, i) => {
    const totals = finish(dayAccs[i], day.endMs - day.startMs);
    return {
      date: day.date,
      startUtc: new Date(day.startMs).toISOString(),
      endUtc: new Date(day.endMs).toISOString(),
      ...totals,
    };
  });

  return {
    formatVersion: WEEKLY_ACTIVITY_FORMAT_VERSION,
    timezone: options.timezone,
    weekStartUtc: new Date(weekStartMs).toISOString(),
    weekEndUtc: new Date(weekEndMs).toISOString(),
    ...weekTotals,
    days,
    previousPeriod: { available: false },
  };
}

/**
 * Versioned weekly time/activity snapshot store (issue #2052).
 *
 * Files live at `<memoryDir>/activity/weekly/<ns>/<week>--<identity>.json`,
 * outside recall fallback dirs. Same inputs skip rewrite by content hash.
 * A new sourceRevision or configHash is a new file.
 */
import { randomBytes } from "node:crypto";
import { mkdirSync, readFileSync, renameSync, unlinkSync, writeFileSync } from "node:fs";
import path from "node:path";

import { namespaceIdentityToken } from "../../namespaces/identity.js";
import { hashActivityBody, isValidActivityDate } from "../digest.js";
import type { WeeklyActivitySummary } from "./weekly.js";

export const WEEKLY_SNAPSHOT_FORMAT_VERSION = 1;
export const WEEKLY_SNAPSHOT_DIR = path.join("activity", "weekly");

export interface PersistWeeklySnapshotInput {
  memoryDir: string;
  namespace: string;
  summary: WeeklyActivitySummary;
  sourceRevision: string;
  configHash: string;
}

export interface PersistWeeklySnapshotResult {
  path: string;
  written: boolean;
}

function requireToken(value: string, name: string): string {
  if (typeof value !== "string" || value.trim().length === 0) {
    throw new TypeError(`${name} must be a non-empty string`);
  }
  return value.trim();
}

export function weeklySnapshotPath(input: PersistWeeklySnapshotInput): string {
  const memoryDir = requireToken(input.memoryDir, "memoryDir");
  const namespace = requireToken(input.namespace, "namespace");
  const sourceRevision = requireToken(input.sourceRevision, "sourceRevision");
  const configHash = requireToken(input.configHash, "configHash");
  const weekStartUtc = input.summary?.weekStartUtc;
  if (typeof weekStartUtc !== "string") {
    throw new TypeError("summary.weekStartUtc must be an ISO timestamp");
  }
  const weekDate = weekStartUtc.slice(0, 10);
  if (!isValidActivityDate(weekDate)) {
    throw new RangeError("summary.weekStartUtc must be an ISO timestamp");
  }
  const identity = hashActivityBody(
    `${input.summary.weekStartUtc}\0${input.summary.weekEndUtc}\0${sourceRevision}\0${configHash}`,
  );
  return path.join(
    path.resolve(memoryDir),
    WEEKLY_SNAPSHOT_DIR,
    namespaceIdentityToken(namespace),
    `${weekDate}--${identity}.json`,
  );
}

/** Persist one weekly snapshot. Same bytes are a no-op. */
export function persistWeeklySnapshot(input: PersistWeeklySnapshotInput): PersistWeeklySnapshotResult {
  const namespace = requireToken(input.namespace, "namespace");
  const sourceRevision = requireToken(input.sourceRevision, "sourceRevision");
  const configHash = requireToken(input.configHash, "configHash");
  const filePath = weeklySnapshotPath(input);
  const payload = {
    formatVersion: WEEKLY_SNAPSHOT_FORMAT_VERSION,
    namespace,
    sourceRevision,
    configHash,
    summary: input.summary,
  };
  const contentHash = hashActivityBody(JSON.stringify(payload));
  const text = `${JSON.stringify({ ...payload, contentHash })}\n`;

  try {
    if (readFileSync(filePath, "utf8") === text) {
      return { path: filePath, written: false };
    }
  } catch (error) {
    if (!(typeof error === "object" && error !== null && "code" in error && error.code === "ENOENT")) {
      throw error;
    }
  }

  mkdirSync(path.dirname(filePath), { recursive: true, mode: 0o700 });
  const tmpPath = `${filePath}.${process.pid}.${randomBytes(8).toString("hex")}.tmp`;
  writeFileSync(tmpPath, text, { encoding: "utf8", mode: 0o600 });
  try {
    renameSync(tmpPath, filePath);
  } catch (error) {
    try {
      unlinkSync(tmpPath);
    } catch {
      // Best-effort cleanup of the temp file.
    }
    throw error;
  }
  return { path: filePath, written: true };
}

/**
 * Config-driven surface for evidence-bound timeline-card analysis (issue #2050).
 *
 * Composes the parsed `activity.timeline.analysis` config with the local/remote
 * provider seams and `analyzeTimelineCards`. The AI gate is independent of
 * activity capture, timeline derivation, and memory creation: disabled means
 * zero provider calls and zero analysis artifacts. Every failure leaves the
 * deterministic cards byte-identical and returns a typed status.
 */
import { activityDayWindow } from "../digest.js";
import type { ActivityTimelineAnalysisConfig } from "../types.js";
import { analyzeTimelineCards, type TimelineAnalysisStatus } from "./analysis.js";
import type { AnalysisFailure } from "./analysis-failure.js";
import {
  timelineAnalysisCompleteFromClients,
  type TimelineAnalysisLocalLlm,
  type TimelineAnalysisRemoteLlm,
} from "./analysis-provider.js";
import { buildAnalysisRunMetadata, type AnalysisRunMetadata } from "./analysis-metadata.js";
import type { TimelineCard, TimelineCategory, TimelineCorrection, TimelineObservation } from "./types.js";

export interface TimelineAnalysisRunInput {
  /** Local calendar day being analyzed (YYYY-MM-DD). */
  date: string;
  /** IANA timezone the day is bucketed in. */
  timezone: string;
  /** Deterministic cards for the day (the bytes that must survive failure). */
  cards: readonly TimelineCard[];
  /** Day observations — the only evidence the provider may see. */
  observations: readonly TimelineObservation[];
  categories?: readonly TimelineCategory[];
  /** Prior accepted manual corrections, surfaced to the prompt as edits. */
  corrections?: readonly TimelineCorrection[];
  config: ActivityTimelineAnalysisConfig;
  deps: {
    localLlm?: TimelineAnalysisLocalLlm | null;
    remoteLlm?: TimelineAnalysisRemoteLlm | null;
  };
  signal?: AbortSignal;
}

export interface TimelineAnalysisRunResult {
  status: TimelineAnalysisStatus;
  /** Same card objects as the input on any non-ok status. */
  cards: TimelineCard[];
  failure?: AnalysisFailure;
  /** Provider/model/prompt-version provenance; identifiers only, never content. */
  metadata?: AnalysisRunMetadata;
}

/**
 * Run the optional analysis for one day. Observations are confined to the
 * DST-aware day window before anything is sent, so a mis-scoped caller cannot
 * widen the evidence the provider sees.
 */
export async function runTimelineCardAnalysis(
  input: TimelineAnalysisRunInput,
): Promise<TimelineAnalysisRunResult> {
  // Throws RangeError on an impossible date or invalid timezone before any
  // provider contact — the window bounds the whole run.
  const { startUtc, endUtc } = activityDayWindow(input.date, input.timezone);
  if (!input.config.enabled) {
    return { status: "disabled", cards: input.cards as TimelineCard[] };
  }
  const start = Date.parse(startUtc);
  const end = Date.parse(endUtc);
  const observations = input.observations.filter((observation) => {
    const captured = Date.parse(observation.capturedAtUtc);
    return Number.isFinite(captured) && captured >= start && captured < end;
  });
  const result = await analyzeTimelineCards({
    enabled: true,
    cards: input.cards,
    observations,
    provider: input.config.provider,
    model: input.config.model,
    complete: timelineAnalysisCompleteFromClients({
      localLlm: input.deps.localLlm ?? null,
      remoteLlm: input.deps.remoteLlm ?? null,
    }),
    ...(input.config.timeoutMs === undefined ? {} : { timeoutMs: input.config.timeoutMs }),
    date: input.date,
    timezone: input.timezone,
    ...(input.categories === undefined ? {} : { categories: input.categories }),
    ...(input.config.preferences === undefined ? {} : { preferences: input.config.preferences }),
    ...(input.corrections === undefined ? {} : { priorEdits: input.corrections }),
    ...(input.signal === undefined ? {} : { signal: input.signal }),
  });
  if (result.status !== "ok") {
    return {
      status: result.status,
      cards: result.cards,
      ...(result.failure === undefined ? {} : { failure: result.failure }),
    };
  }
  return {
    status: "ok",
    cards: result.cards,
    metadata: buildAnalysisRunMetadata({
      provider: result.provider ?? "unknown",
      model: result.model ?? "unknown",
      promptVersion: String(result.promptVersion ?? "v0"),
      observationCount: observations.length,
    }),
  };
}

/**
 * Deterministic machine-readable recap export from timeline cards (issue #2051).
 *
 * Pure: cards + date + timezone in, stable JSON out. No LLM, no I/O, no
 * persistence. Same cards always serialize to the same bytes, regardless of
 * input array order: cards are sorted by id before serialization.
 *
 * Privacy boundary (issue #2053 policy): a card `title` is captured
 * observation content (the source window title). It is excluded unless the
 * export explicitly permits observations — the same default as
 * `activity.exportIncludeObservations`. Evidence references (store row ids,
 * identity hashes) are always kept: they point at content without copying it.
 */
import type { TimelineCard } from "./types.js";

export interface DeterministicRecapOptions {
  date: string;
  timezone: string;
  cards: readonly TimelineCard[];
  /**
   * Include observation-derived card content (`title`). Default false,
   * matching the `activity.exportIncludeObservations` policy default.
   */
  includeObservations?: boolean;
}

/** Card projected for export: `title` present only when the policy permits. */
export interface RecapExportCard extends Omit<TimelineCard, "title"> {
  title?: string;
}

export interface DeterministicRecap {
  date: string;
  timezone: string;
  cards: RecapExportCard[];
}

/**
 * Project one card for export with a fixed key order. Observation-derived
 * `title` is dropped unless `includeObservations`; user-authored provenance
 * (manual edits, pause reasons inside `summary`) stays, and evidence
 * references always stay.
 */
export function projectCardForRecapExport(
  card: TimelineCard,
  includeObservations: boolean,
): RecapExportCard {
  const projected: RecapExportCard = {
    id: card.id,
    kind: card.kind,
    summary: card.summary,
    categoryId: card.categoryId,
    confidence: card.confidence,
    startUtc: card.startUtc,
    endUtc: card.endUtc,
    dayKey: card.dayKey,
    timezone: card.timezone,
    machine: card.machine,
    evidenceIds: card.evidenceIds,
    evidenceRange: card.evidenceRange,
  };
  if (card.manualEdit !== undefined) {
    projected.manualEdit = card.manualEdit;
  }
  if (includeObservations) {
    projected.title = card.title;
  }
  return projected;
}

function compareCardIds(a: RecapExportCard, b: RecapExportCard): number {
  if (a.id < b.id) return -1;
  if (a.id > b.id) return 1;
  return 0;
}

/**
 * Build the byte-stable JSON recap document for one local day.
 * Callers may `JSON.stringify` the returned object; construction order
 * (date, timezone, cards, and the per-card key order) is fixed, so
 * serialization is deterministic.
 */
export function exportDeterministicRecap(
  options: DeterministicRecapOptions,
): DeterministicRecap {
  const includeObservations = options.includeObservations === true;
  return {
    date: options.date,
    timezone: options.timezone,
    cards: options.cards
      .map((card) => projectCardForRecapExport(card, includeObservations))
      .sort(compareCardIds),
  };
}

/**
 * Deterministic recap export over a bounded date range (issue #2051).
 *
 * Pure: cards + inclusive [startDate, endDate] + timezone in, stable JSON or
 * Markdown out. No LLM, no I/O. Every date in the range gets a day entry —
 * empty days included — and cards land on their stored `dayKey`, so reruns
 * with the same inputs always produce the same bytes regardless of input
 * card order. Cards whose `dayKey` falls outside the range are not exported.
 *
 * The range is bounded: at most `maxDays` days (default 366) per call, so a
 * swapped start/end or a multi-year span fails with a typed error instead of
 * producing an unbounded document.
 */
import { isValidActivityDate } from "../digest.js";
import { parseRecapDate } from "./recap-date.js";
import { renderDeterministicJournal } from "./journal-recap.js";
import {
  projectCardForRecapExport,
  type RecapExportCard,
} from "./recap-export.js";
import type { TimelineCard } from "./types.js";

export const DEFAULT_RECAP_RANGE_MAX_DAYS = 366;

export interface DeterministicRecapRangeOptions {
  /** Inclusive first local day, YYYY-MM-DD. */
  startDate: string;
  /** Inclusive last local day, YYYY-MM-DD. */
  endDate: string;
  timezone: string;
  cards: readonly TimelineCard[];
  /** Include observation-derived card content (`title`). Default false. */
  includeObservations?: boolean;
  /** Hard upper bound on exported days; default 366. */
  maxDays?: number;
}

export interface DeterministicRecapDay {
  date: string;
  timezone: string;
  cards: RecapExportCard[];
}

export interface DeterministicRecapRange {
  startDate: string;
  endDate: string;
  timezone: string;
  days: DeterministicRecapDay[];
}

export type DeterministicRecapRangeResult =
  | { ok: true; range: DeterministicRecapRange }
  | {
      ok: false;
      error:
        | "invalid_start_date"
        | "invalid_end_date"
        | "end_before_start"
        | "range_too_large";
      /** The enforced day bound, present on range_too_large. */
      limit?: number;
    };

export type DeterministicRecapRangeMarkdownResult =
  | { ok: true; markdown: string; dayCount: number }
  | Extract<DeterministicRecapRangeResult, { ok: false }>;

function compareCardIds(a: RecapExportCard, b: RecapExportCard): number {
  if (a.id < b.id) return -1;
  if (a.id > b.id) return 1;
  return 0;
}

/** UTC-midnight stepping over validated real calendar dates. */
function* isoDays(startDate: string, endDate: string): Generator<string> {
  const endMs = Date.parse(`${endDate}T00:00:00Z`);
  let cursor = new Date(`${startDate}T00:00:00Z`);
  while (cursor.getTime() <= endMs) {
    yield cursor.toISOString().slice(0, 10);
    cursor = new Date(cursor.getTime() + 86_400_000);
  }
}

function dayCount(startDate: string, endDate: string): number {
  return (
    (Date.parse(`${endDate}T00:00:00Z`) - Date.parse(`${startDate}T00:00:00Z`)) /
      86_400_000 +
    1
  );
}

/**
 * Build the byte-stable JSON recap document for an inclusive local-day
 * range. Day entries are ascending; day cards are sorted by id; per-card
 * key order is fixed by `projectCardForRecapExport`.
 */
export function exportDeterministicRecapRange(
  options: DeterministicRecapRangeOptions,
): DeterministicRecapRangeResult {
  const start = parseRecapDate(options.startDate);
  if (!start.ok || !isValidActivityDate(start.date)) {
    return { ok: false, error: "invalid_start_date" };
  }
  const end = parseRecapDate(options.endDate);
  if (!end.ok || !isValidActivityDate(end.date)) {
    return { ok: false, error: "invalid_end_date" };
  }
  if (Date.parse(`${end.date}T00:00:00Z`) < Date.parse(`${start.date}T00:00:00Z`)) {
    return { ok: false, error: "end_before_start" };
  }
  const limit = options.maxDays ?? DEFAULT_RECAP_RANGE_MAX_DAYS;
  if (!Number.isInteger(limit) || limit < 1) {
    throw new RangeError(`maxDays must be a positive integer; got ${options.maxDays}`);
  }
  if (dayCount(start.date, end.date) > limit) {
    return { ok: false, error: "range_too_large", limit };
  }

  const includeObservations = options.includeObservations === true;
  const byDay = new Map<string, RecapExportCard[]>();
  for (const card of options.cards) {
    if (card.dayKey < start.date || card.dayKey > end.date) continue;
    const bucket = byDay.get(card.dayKey);
    const projected = projectCardForRecapExport(card, includeObservations);
    if (bucket === undefined) byDay.set(card.dayKey, [projected]);
    else bucket.push(projected);
  }

  const days: DeterministicRecapDay[] = [];
  for (const date of isoDays(start.date, end.date)) {
    days.push({
      date,
      timezone: options.timezone,
      cards: (byDay.get(date) ?? []).sort(compareCardIds),
    });
  }
  return {
    ok: true,
    range: {
      startDate: start.date,
      endDate: end.date,
      timezone: options.timezone,
      days,
    },
  };
}

/**
 * Render the byte-stable Markdown recap for an inclusive local-day range:
 * one `renderDeterministicJournal` section per day, ascending. Validation
 * and bounds match `exportDeterministicRecapRange`.
 */
export function renderDeterministicJournalRange(
  options: DeterministicRecapRangeOptions,
): DeterministicRecapRangeMarkdownResult {
  const exported = exportDeterministicRecapRange(options);
  if (!exported.ok) return exported;
  const sections = exported.range.days.map((day) =>
    renderDeterministicJournal(day.cards, {
      date: day.date,
      timezone: day.timezone,
    }),
  );
  return {
    ok: true,
    markdown: sections.join("\n"),
    dayCount: exported.range.days.length,
  };
}

/**
 * Deterministic Markdown recap from timeline cards (issue #2051 leftover).
 *
 * Pure: date + timezone + cards in, Markdown out. No LLM, no I/O, no
 * persistence. Cards are sorted by id. Empty cards print (empty).
 */
import type { TimelineCard } from "./types.js";

export interface RecapMarkdownOptions {
  date: string;
  timezone: string;
  cards: readonly TimelineCard[];
}

function compareCardIds(a: TimelineCard, b: TimelineCard): number {
  if (a.id < b.id) return -1;
  if (a.id > b.id) return 1;
  return 0;
}

/** Render a byte-stable Markdown recap for one local day. */
export function renderRecapMarkdown(options: RecapMarkdownOptions): string {
  const cards = [...options.cards].sort(compareCardIds);
  const body = cards.length === 0 ? ["(empty)"] : cards.map((card) => `- ${card.id}`);
  return [`# Recap — ${options.date} (${options.timezone})`, "", ...body, ""].join("\n");
}

/**
 * Deterministic machine-readable week export from daily totals (issue #2052).
 *
 * Pure: weekStart + timezone + days in, stable JSON out. No LLM, no I/O, no
 * persistence. Same days always serialize to the same bytes, regardless of
 * input array order: days are sorted by date before serialization.
 */

export interface DeterministicWeekDay {
  date: string;
}

export interface DeterministicWeekOptions {
  weekStart: string;
  timezone: string;
  days: readonly DeterministicWeekDay[];
}

export interface DeterministicWeek {
  weekStart: string;
  timezone: string;
  days: DeterministicWeekDay[];
}

function compareDates(a: DeterministicWeekDay, b: DeterministicWeekDay): number {
  if (a.date < b.date) return -1;
  if (a.date > b.date) return 1;
  return 0;
}

/**
 * Build the byte-stable JSON week document.
 * Callers may `JSON.stringify` the returned object; construction order
 * (weekStart, timezone, days) is fixed, so serialization is deterministic.
 */
export function exportDeterministicWeek(
  options: DeterministicWeekOptions,
): DeterministicWeek {
  return {
    weekStart: options.weekStart,
    timezone: options.timezone,
    days: [...options.days].sort(compareDates),
  };
}

/**
 * Deterministic markdown week snapshot from daily totals (issue #2052 leftover).
 *
 * Pure: weekStart + timezone + days in, stable markdown out. No LLM, no I/O, no
 * persistence. Days are sorted by date. Empty days print heading + (empty).
 */

export interface WeekSnapshotDay {
  date: string;
}

export interface WeekSnapshotOptions {
  weekStart: string;
  timezone: string;
  days: readonly WeekSnapshotDay[];
}

function compareDates(a: WeekSnapshotDay, b: WeekSnapshotDay): number {
  if (a.date < b.date) return -1;
  if (a.date > b.date) return 1;
  return 0;
}

/** Render a byte-stable Markdown week snapshot. */
export function renderWeekSnapshot(options: WeekSnapshotOptions): string {
  const days = [...options.days].sort(compareDates);
  const body =
    days.length === 0
      ? ["## Days", "(empty)"]
      : days.flatMap((day) => [`## ${day.date}`, "(empty)", ""]);
  return [
    "# Week snapshot",
    "",
    `- weekStart: ${options.weekStart}`,
    `- timezone: ${options.timezone}`,
    "",
    ...body,
    "",
  ].join("\n");
}

/**
 * Weekly dashboard snapshot composition (issue #2052).
 *
 * Composes the #2052 helpers into one machine-readable week document:
 * duration/category/day totals (`weekly.ts`), an explicit previous-period
 * comparison (`week-previous.ts`), threshold-gated recurrence
 * (`week-recurring.ts`), top application/domain summaries, source
 * card/evidence counts, and uncertainty flags. Pure: no I/O, no clock, no
 * LLM. This is a time/activity summary, never a score; it makes no claim
 * about mood, productivity, intent, presence, or quality of work.
 *
 * The result extends `WeeklyActivitySummary`, so `persistWeeklySnapshot`
 * accepts it unchanged: identical inputs rewrite nothing, and a new
 * sourceRevision or configHash keys a new snapshot file instead of mutating
 * an unrelated period. Application/domain attribution arrives as structured
 * per-card metadata (from the observations that built the cards), never
 * parsed back out of card prose.
 */
import type { TimelineCard } from "./types.js";
import { compareWeeklyPreviousPeriod, type WeeklyPreviousPeriod } from "./week-previous.js";
import {
  findRecurringPatterns,
  type RecurringPattern,
  type WeekDayOccurrence,
} from "./week-recurring.js";
import {
  buildWeeklyActivitySummary,
  type WeeklyActivityOptions,
  type WeeklyActivitySummary,
} from "./weekly.js";

export const WEEKLY_DASHBOARD_FORMAT_VERSION = 1;
export const DEFAULT_TOP_SOURCE_LIMIT = 10;
const DAY_MS = 86_400_000;
const WEEK_DAYS_MS = 7 * DAY_MS;

/** Structured activity metadata for one card, keyed by card id. */
export interface WeekSourceAttribution {
  /** Application name from the card's source observations. */
  app: string;
  /** Lowercased browser hostname, when the frontmost window was a browser. */
  domain?: string;
}

export interface WeeklySourceTotal {
  key: string;
  durationMs: number;
}

export interface WeeklyEvidenceStats {
  activityCardCount: number;
  idleCardCount: number;
  pauseCardCount: number;
  /** Evidence ids summed across in-week activity cards; repeats possible. */
  evidenceCount: number;
  /** Distinct evidence ids across in-week activity cards. */
  distinctEvidenceCount: number;
}

export interface WeeklyUncertainty {
  /** In-week cards clipped at a week bound: the week sees only part of them. */
  clippedCardCount: number;
  /** In-week cards carrying a manual edit; totals may not match raw captures. */
  manualEditCount: number;
  /** In-week cards classified with confidence 0 (unclassified signal). */
  unclassifiedCardCount: number;
}

export interface WeeklyDashboardSources {
  applications: WeeklySourceTotal[];
  domains: WeeklySourceTotal[];
}

export interface WeeklyDashboardRecurring {
  categories: RecurringPattern[];
  applications: RecurringPattern[];
}

export interface WeeklyDashboard extends WeeklyActivitySummary {
  dashboardFormatVersion: number;
  sources: WeeklyDashboardSources;
  recurring: WeeklyDashboardRecurring;
  evidence: WeeklyEvidenceStats;
  uncertainty: WeeklyUncertainty;
}

export interface WeeklyDashboardOptions extends WeeklyActivityOptions {
  /** Per-card application/domain metadata; cards without an entry are skipped in `sources`. */
  attributions?: ReadonlyMap<string, WeekSourceAttribution>;
  /** Cards of the immediately preceding week; absent keeps `previousPeriod` explicitly unavailable. */
  previousWeekCards?: readonly TimelineCard[];
  /** Distinct-day threshold passed to `findRecurringPatterns`. */
  recurrenceMinDays?: number;
  /** Max entries per source list; >= 1. */
  topSourceLimit?: number;
}

interface ClippedCard {
  card: TimelineCard;
  startMs: number;
  endMs: number;
  clipStartMs: number;
  clipEndMs: number;
}

function clippedInWeek(
  cards: readonly TimelineCard[],
  weekStartMs: number,
  weekEndMs: number,
): ClippedCard[] {
  const clipped: ClippedCard[] = [];
  for (const card of cards) {
    const startMs = Date.parse(card.startUtc);
    const endMs = Date.parse(card.endUtc);
    if (!Number.isFinite(startMs) || !Number.isFinite(endMs) || endMs <= startMs) continue;
    const clipStartMs = Math.max(startMs, weekStartMs);
    const clipEndMs = Math.min(endMs, weekEndMs);
    if (clipEndMs > clipStartMs) {
      clipped.push({ card, startMs, endMs, clipStartMs, clipEndMs });
    }
  }
  return clipped;
}

function normalizedAttribution(
  cardId: string,
  attributions: ReadonlyMap<string, WeekSourceAttribution> | undefined,
): { app: string; domain?: string } | null {
  const attribution = attributions?.get(cardId);
  if (attribution === undefined) return null;
  if (typeof attribution.app !== "string" || attribution.app.trim() === "") {
    throw new RangeError(`attribution for card ${cardId} must have a non-blank app`);
  }
  const app = attribution.app.trim();
  if (attribution.domain === undefined) return { app };
  if (typeof attribution.domain !== "string" || attribution.domain.trim() === "") {
    throw new RangeError(`attribution for card ${cardId} must have a non-blank domain when present`);
  }
  return { app, domain: attribution.domain.trim().toLowerCase() };
}

function rankTotals(totals: Map<string, number>, limit: number): WeeklySourceTotal[] {
  return [...totals.entries()]
    .map(([key, durationMs]) => ({ key, durationMs }))
    .sort(
      (a, b) =>
        b.durationMs - a.durationMs || (a.key < b.key ? -1 : a.key > b.key ? 1 : 0),
    )
    .slice(0, limit);
}

/** Build the full dashboard snapshot for one half-open week. Pure. */
export function buildWeeklyDashboard(
  cards: readonly TimelineCard[],
  options: WeeklyDashboardOptions,
): WeeklyDashboard {
  const summary = buildWeeklyActivitySummary(cards, options);
  const topSourceLimit = options.topSourceLimit ?? DEFAULT_TOP_SOURCE_LIMIT;
  if (!Number.isInteger(topSourceLimit) || topSourceLimit < 1) {
    throw new RangeError(`topSourceLimit must be an integer >= 1; got ${topSourceLimit}`);
  }

  // Canonical bounds from the summary: identical clipping arithmetic to
  // weekly.ts regardless of how the caller spelled the input timestamps.
  const weekStartMs = Date.parse(summary.weekStartUtc);
  const weekEndMs = Date.parse(summary.weekEndUtc);
  const inWeek = clippedInWeek(cards, weekStartMs, weekEndMs);

  const applicationTotals = new Map<string, number>();
  const domainTotals = new Map<string, number>();
  const applicationOccurrences: WeekDayOccurrence[] = [];
  const categoryOccurrences: WeekDayOccurrence[] = [];
  const evidence: WeeklyEvidenceStats = {
    activityCardCount: 0,
    idleCardCount: 0,
    pauseCardCount: 0,
    evidenceCount: 0,
    distinctEvidenceCount: 0,
  };
  const uncertainty: WeeklyUncertainty = {
    clippedCardCount: 0,
    manualEditCount: 0,
    unclassifiedCardCount: 0,
  };
  const distinctEvidence = new Set<number>();
  const dayWindows = summary.days.map((day) => ({
    date: day.date,
    startMs: Date.parse(day.startUtc),
    endMs: Date.parse(day.endUtc),
  }));

  for (const day of summary.days) {
    for (const total of day.categories) {
      if (total.durationMs > 0) {
        categoryOccurrences.push({ date: day.date, key: total.categoryId, durationMs: total.durationMs });
      }
    }
  }

  for (const { card, startMs, endMs, clipStartMs, clipEndMs } of inWeek) {
    if (startMs < weekStartMs || endMs > weekEndMs) {
      uncertainty.clippedCardCount++;
    }
    if (card.kind === "idle") {
      evidence.idleCardCount++;
      continue;
    }
    if (card.kind === "pause") {
      evidence.pauseCardCount++;
      continue;
    }
    evidence.activityCardCount++;
    for (const id of card.evidenceIds) {
      evidence.evidenceCount++;
      distinctEvidence.add(id);
    }
    if (card.manualEdit !== undefined) uncertainty.manualEditCount++;
    if (card.confidence === 0) uncertainty.unclassifiedCardCount++;

    const attribution = normalizedAttribution(card.id, options.attributions);
    if (attribution === null) continue;
    const durationMs = clipEndMs - clipStartMs;
    applicationTotals.set(attribution.app, (applicationTotals.get(attribution.app) ?? 0) + durationMs);
    if (attribution.domain !== undefined) {
      domainTotals.set(attribution.domain, (domainTotals.get(attribution.domain) ?? 0) + durationMs);
    }
    for (const day of dayWindows) {
      const dayStartMs = Math.max(clipStartMs, day.startMs);
      const dayEndMs = Math.min(clipEndMs, day.endMs);
      if (dayEndMs > dayStartMs) {
        applicationOccurrences.push({ date: day.date, key: attribution.app, durationMs: dayEndMs - dayStartMs });
      }
    }
  }
  evidence.distinctEvidenceCount = distinctEvidence.size;

  let previousPeriod: WeeklyPreviousPeriod = { available: false };
  if (options.previousWeekCards !== undefined) {
    const previousSummary = buildWeeklyActivitySummary(options.previousWeekCards, {
      ...options,
      weekStartUtc: new Date(weekStartMs - WEEK_DAYS_MS).toISOString(),
      weekEndUtc: summary.weekStartUtc,
    });
    previousPeriod = compareWeeklyPreviousPeriod({
      previous: previousSummary,
      current: summary,
      previousStartUtc: previousSummary.weekStartUtc,
      previousEndUtc: previousSummary.weekEndUtc,
    });
  }

  return {
    ...summary,
    previousPeriod,
    dashboardFormatVersion: WEEKLY_DASHBOARD_FORMAT_VERSION,
    sources: {
      applications: rankTotals(applicationTotals, topSourceLimit),
      domains: rankTotals(domainTotals, topSourceLimit),
    },
    recurring: {
      categories: findRecurringPatterns({
        occurrences: categoryOccurrences,
        minDays: options.recurrenceMinDays,
      }),
      applications: findRecurringPatterns({
        occurrences: applicationOccurrences,
        minDays: options.recurrenceMinDays,
      }),
    },
    evidence,
    uncertainty,
  };
}

/**
 * Previous-week duration comparison (issue #2052).
 *
 * The prior week is explicit when unavailable. It is never silently treated
 * as zero.
 */

export interface WeeklyDurationTotals {
  activeMs: number;
  idleMs: number;
  pauseMs: number;
  gapMs: number;
  unclassifiedMs: number;
}

export type WeeklyPreviousPeriod =
  | { available: false }
  | {
      available: true;
      previousStartUtc: string;
      previousEndUtc: string;
      deltaActiveMs: number;
      deltaIdleMs: number;
      deltaPauseMs: number;
      deltaGapMs: number;
      deltaUnclassifiedMs: number;
    };

const DURATION_FIELDS = [
  "activeMs",
  "idleMs",
  "pauseMs",
  "gapMs",
  "unclassifiedMs",
] as const;

function assertFiniteTotals(totals: WeeklyDurationTotals, label: string): void {
  for (const field of DURATION_FIELDS) {
    const value = totals[field];
    if (typeof value !== "number" || !Number.isFinite(value)) {
      throw new TypeError(`${label}.${field} must be a finite number; got ${String(value)}.`);
    }
  }
}

/**
 * Compare this week's duration totals against the previous week's.
 *
 * `previous` absent (null/undefined) or lacking trimmed start/end timestamps
 * returns `{ available: false }` — never zero deltas. Otherwise returns the
 * per-field deltas (`current - previous`, may be negative). Pure.
 */
export function compareWeeklyPreviousPeriod(input: {
  previous: WeeklyDurationTotals | null | undefined;
  current: WeeklyDurationTotals;
  previousStartUtc?: string;
  previousEndUtc?: string;
}): WeeklyPreviousPeriod {
  const { previous, current, previousStartUtc, previousEndUtc } = input;
  assertFiniteTotals(current, "current");

  if (previous === null || previous === undefined) {
    return { available: false };
  }
  assertFiniteTotals(previous, "previous");

  const start = previousStartUtc?.trim() ?? "";
  const end = previousEndUtc?.trim() ?? "";
  if (start === "" || end === "") {
    return { available: false };
  }

  return {
    available: true,
    previousStartUtc: start,
    previousEndUtc: end,
    deltaActiveMs: current.activeMs - previous.activeMs,
    deltaIdleMs: current.idleMs - previous.idleMs,
    deltaPauseMs: current.pauseMs - previous.pauseMs,
    deltaGapMs: current.gapMs - previous.gapMs,
    deltaUnclassifiedMs: current.unclassifiedMs - previous.unclassifiedMs,
  };
}

/**
 * Recurring weekly pattern gate (issue #2052).
 *
 * A category/application key counts as recurring only when it appeared on at
 * least `minDays` DISTINCT days of the analyzed week, so a one-off blip is
 * never reported as a pattern. Pure: no I/O, no clock, no input mutation.
 * Validation happens on the exact occurrence values before any key trimming
 * (AGENTS.md: validate before normalizing; reject non-finite numbers
 * explicitly instead of letting NaN fall through a comparison).
 */
import { isValidActivityDate } from "../digest.js";

export const DEFAULT_RECURRENCE_MIN_DAYS = 3;

/** Lowest threshold that still means "recurring": two distinct days. */
export const MIN_RECURRENCE_MIN_DAYS = 2;

export interface WeekDayOccurrence {
  /** YYYY-MM-DD inside the analyzed week. */
  date: string;
  /** Category id or application/domain label. */
  key: string;
  durationMs: number;
}

export interface RecurringPattern {
  key: string;
  /** Count of DISTINCT days the key appeared on. */
  dayCount: number;
  totalDurationMs: number;
}

export function findRecurringPatterns(input: {
  occurrences: readonly WeekDayOccurrence[];
  minDays?: number;
}): RecurringPattern[] {
  const minDays = input.minDays ?? DEFAULT_RECURRENCE_MIN_DAYS;
  // A floor of 2 is the module's defining invariant, not a preference: at
  // minDays 1 every key that appeared once is "recurring", which is exactly
  // the one-off blip this helper exists to exclude. Configuration must not be
  // able to switch the invariant off.
  if (!Number.isInteger(minDays) || minDays < MIN_RECURRENCE_MIN_DAYS) {
    throw new RangeError(
      `Invalid minDays ${minDays}; expected an integer >= ${MIN_RECURRENCE_MIN_DAYS}.`,
    );
  }

  const daysByKey = new Map<string, Set<string>>();
  const totalsByKey = new Map<string, number>();

  for (const occurrence of input.occurrences) {
    if (!isValidActivityDate(occurrence.date)) {
      throw new RangeError(`Invalid date "${occurrence.date}"; expected YYYY-MM-DD.`);
    }
    if (
      typeof occurrence.durationMs !== "number" ||
      !Number.isFinite(occurrence.durationMs) ||
      occurrence.durationMs < 0
    ) {
      throw new RangeError(`Invalid durationMs ${occurrence.durationMs}; expected a finite number >= 0.`);
    }
    const key = occurrence.key.trim();
    if (key === "") continue;
    let days = daysByKey.get(key);
    if (!days) {
      days = new Set<string>();
      daysByKey.set(key, days);
      totalsByKey.set(key, 0);
    }
    days.add(occurrence.date);
    totalsByKey.set(key, totalsByKey.get(key)! + occurrence.durationMs);
  }

  const patterns: RecurringPattern[] = [];
  for (const [key, days] of daysByKey) {
    if (days.size < minDays) continue;
    patterns.push({ key, dayCount: days.size, totalDurationMs: totalsByKey.get(key)! });
  }

  patterns.sort((a, b) => {
    if (a.dayCount !== b.dayCount) return b.dayCount - a.dayCount;
    if (a.totalDurationMs !== b.totalDurationMs) return b.totalDurationMs - a.totalDurationMs;
    if (a.key < b.key) return -1;
    if (a.key > b.key) return 1;
    return 0;
  });
  return patterns;
}

/**
 * Weekly snapshot config hash (issue #2052).
 *
 * `persistWeeklySnapshot` keys each snapshot file by a `configHash`; this
 * computes that digest deterministically from the weekly config so every
 * caller derives the same value for the same inputs. Stable across category
 * order and key insertion order; any semantic change produces a new digest,
 * which keys a new snapshot file instead of mutating an unrelated period.
 *
 * Values are validated, not merely non-blank: a typo like `"Not/AZone"` or
 * `"monady"` would otherwise get a durable snapshot identity, and correcting
 * the typo later would fork the stored history instead of continuing it.
 */
import { assertValidTimezone, hashActivityBody } from "../digest.js";

export interface WeeklyConfigInput {
  timezone: string;
  weekStartsOn: string;
  /** Category definitions that shape the snapshot. */
  categories: readonly { id: string; name: string }[];
}

/** Week-start vocabulary. Lowercase day names, matching the config surface. */
export const WEEK_START_DAYS = Object.freeze([
  "monday",
  "tuesday",
  "wednesday",
  "thursday",
  "friday",
  "saturday",
  "sunday",
] as const);

function requireNonBlank(value: unknown, field: string): string {
  if (typeof value !== "string" || value.trim() === "") {
    throw new RangeError(`${field} must be a non-blank string`);
  }
  return value;
}

export function computeWeeklyConfigHash(input: WeeklyConfigInput): string {
  if (typeof input !== "object" || input === null) {
    throw new RangeError("input must be a WeeklyConfigInput object");
  }
  const rawTimezone = requireNonBlank(input.timezone, "timezone");
  assertValidTimezone(rawTimezone);
  // Canonicalize before hashing: `utc` and `UTC` are the same zone, and
  // `US/Eastern` is an alias of `America/New_York`. Hashing the raw string
  // gives two callers two identities for one zone, which would fork one
  // snapshot history on a harmless casing or alias change.
  const timezone = new Intl.DateTimeFormat("en-US", { timeZone: rawTimezone })
    .resolvedOptions().timeZone;
  const weekStartsOn = requireNonBlank(input.weekStartsOn, "weekStartsOn");
  if (!(WEEK_START_DAYS as readonly string[]).includes(weekStartsOn)) {
    throw new RangeError(
      `weekStartsOn must be one of ${WEEK_START_DAYS.join(", ")}; got ${JSON.stringify(weekStartsOn)}`,
    );
  }
  if (!Array.isArray(input.categories)) {
    throw new RangeError("categories must be an array of category definitions");
  }
  // Copy + sort: never sort the caller's array in place, and hash category
  // order-independently so a harmless reorder cannot orphan stored snapshots.
  const sorted = input.categories
    .map((category, index) => ({
      id: requireNonBlank(category?.id, `categories[${index}].id`),
      name: requireNonBlank(category?.name, `categories[${index}].name`),
    }))
    .sort((a, b) => (a.id < b.id ? -1 : a.id > b.id ? 1 : 0));
  for (let index = 1; index < sorted.length; index++) {
    if (sorted[index].id === sorted[index - 1].id) {
      throw new RangeError(`duplicate category id: ${sorted[index].id}`);
    }
  }
  // Fixed field order; JSON.stringify each part so no separator can collide
  // with category content.
  const body = [
    JSON.stringify(timezone),
    JSON.stringify(weekStartsOn),
    ...sorted.map((category) => JSON.stringify([category.id, category.name])),
  ].join("\n");
  return hashActivityBody(body);
}

/**
 * Bounded overlapping observation batches for timeline analysis (issue #2050).
 */
import type { TimelineObservation } from "./types.js";

export type TimelineBatchObservation = Pick<TimelineObservation, "id" | "capturedAtUtc">;

export interface BatchObservationsOptions {
  maxBatch: number;
  overlap: number;
}

function compareObservations(a: TimelineBatchObservation, b: TimelineBatchObservation): number {
  const time = Date.parse(a.capturedAtUtc) - Date.parse(b.capturedAtUtc);
  if (time !== 0) return time;
  return a.id - b.id;
}

/** Split observations into overlapping windows. Order is capturedAtUtc, then id. */
export function batchObservations<T extends TimelineBatchObservation>(
  observations: readonly T[],
  options: BatchObservationsOptions,
): T[][] {
  const { maxBatch, overlap } = options;
  if (!Number.isInteger(overlap) || overlap < 0) {
    throw new RangeError("overlap must be a non-negative integer");
  }
  if (maxBatch === 0) return [];
  if (!Number.isInteger(maxBatch) || maxBatch < 1) {
    throw new RangeError("maxBatch must be 0 or a positive integer");
  }
  if (overlap >= maxBatch) {
    throw new RangeError("overlap must be less than maxBatch");
  }
  if (observations.length === 0) return [];

  const ordered = [...observations].sort(compareObservations);
  const step = maxBatch - overlap;
  const batches: T[][] = [];
  for (let start = 0; start < ordered.length; start += step) {
    batches.push(ordered.slice(start, start + maxBatch));
    if (start + maxBatch >= ordered.length) break;
  }
  return batches;
}

/**
 * Drop analysis claims that do not cite a supplied observation (issue #2050).
 */
export interface TimelineEvidenceClaim {
  observationId: number;
}

export interface TimelineEvidenceObservation {
  id: number;
}

/** Keep claims whose observationId is present. Preserve claim order. */
export function boundEvidence<T extends TimelineEvidenceClaim>(
  claims: readonly T[],
  observations: readonly TimelineEvidenceObservation[],
): T[] {
  if (observations.length === 0) return [];
  const ids = new Set(observations.map((observation) => observation.id));
  return claims.filter((claim) => ids.has(claim.observationId));
}

/**
 * Deterministic evidence-only analysis prompt (issue #2050).
 * No LLM call. Prompt lists observation id and capturedAtUtc only.
 */
export type AnalysisPromptObservation = {
  id: number;
  capturedAtUtc: string;
};

const INSTRUCTIONS =
  "Use only supplied evidence. Preserve chronology. Do not invent people, places, or tasks. Return strict JSON.";

function listedObservation(observation: AnalysisPromptObservation): AnalysisPromptObservation {
  return { id: observation.id, capturedAtUtc: observation.capturedAtUtc };
}

/** Build a deterministic prompt. Observations sort by id. Empty lists render as (empty). */
export function buildAnalysisPrompt(input: {
  observations: readonly AnalysisPromptObservation[];
}): string {
  const listed = [...input.observations].sort((a, b) => a.id - b.id).map(listedObservation);
  const body = listed.length === 0 ? "(empty)" : JSON.stringify(listed);
  return `${INSTRUCTIONS}\nObservations: ${body}`;
}

/**
 * Parse a timeline analysis claim's observationId (issue #2050).
 */
export type ParseClaimObservationIdResult =
  | { ok: true; observationId: string }
  | { ok: false; error: "missing_observation" };

export function parseClaimObservationId(claim: {
  observationId?: string | null;
}): ParseClaimObservationIdResult {
  const raw = claim.observationId;
  if (raw == null) return { ok: false, error: "missing_observation" };
  const observationId = raw.trim();
  if (observationId.length === 0) return { ok: false, error: "missing_observation" };
  return { ok: true, observationId };
}

/**
 * Stable observation-id order for timeline analysis (issue #2050 leftover).
 *
 * localeCompare sort. Empty input → []. Does not mutate input. Drops empty strings.
 */

/** Return a new localeCompare-sorted id list. Empty strings are dropped. */
export function sortObservationIds(ids: readonly string[]): string[] {
  return ids.filter((id) => id !== "").sort((a, b) => a.localeCompare(b));
}

/**
 * Deterministic half-open recap window clip (issue #2051).
 *
 * Clips cards to [windowStartMs, windowEndMs) so recap renderers share one
 * day-boundary derivation instead of re-deriving it per renderer.
 */
export interface RecapWindowCard {
  id: string;
  startUtc: string;
  endUtc: string;
}

export interface ClippedRecapCard {
  id: string;
  startMs: number;
  endMs: number;
  durationMs: number;
}

export function clipCardsToRecapWindow(
  cards: readonly RecapWindowCard[],
  windowStartMs: number,
  windowEndMs: number,
): ClippedRecapCard[] {
  // NaN fails every comparison, so an unchecked non-finite bound slips past the
  // ordering guard and emits NaN timestamps and durations — `durationMs <= 0`
  // is also false for NaN, so the card is not even dropped.
  if (!Number.isFinite(windowStartMs) || !Number.isFinite(windowEndMs)) {
    throw new RangeError(
      `recap window bounds must be finite; got start ${windowStartMs} and end ${windowEndMs}`,
    );
  }
  if (windowEndMs <= windowStartMs) {
    throw new RangeError(
      `recap window end ${windowEndMs} must be greater than start ${windowStartMs}`,
    );
  }
  const out: ClippedRecapCard[] = [];
  for (const card of cards) {
    const startMs = Date.parse(card.startUtc);
    const endMs = Date.parse(card.endUtc);
    if (!Number.isFinite(startMs) || !Number.isFinite(endMs)) {
      continue;
    }
    const clippedStart = Math.max(startMs, windowStartMs);
    const clippedEnd = Math.min(endMs, windowEndMs);
    const durationMs = clippedEnd - clippedStart;
    if (durationMs <= 0) {
      continue;
    }
    out.push({ id: card.id, startMs: clippedStart, endMs: clippedEnd, durationMs });
  }
  out.sort((a, b) => a.startMs - b.startMs || (a.id < b.id ? -1 : a.id > b.id ? 1 : 0));
  return out;
}

/**
 * Merge user hand-edits into a regenerated journal recap (issue #2051).
 *
 * Rule: user edits survive regeneration; an explicit reset is the only
 * way to discard them. Pure — no I/O, no clock, no randomness.
 */

export interface RecapSection {
  /** Stable section key, e.g. "highlights". */
  key: string;
  body: string;
}

export type MergeRecapEditsResult = {
  sections: RecapSection[];
  /** Section keys whose user edit was kept over the regenerated body. */
  preserved: string[];
  /** Section keys taken from the regenerated recap. */
  regenerated: string[];
};

function dedupeByFirst(list: readonly RecapSection[]): RecapSection[] {
  const seen = new Set<string>();
  const out: RecapSection[] = [];
  for (const section of list) {
    if (seen.has(section.key)) continue;
    seen.add(section.key);
    out.push(section);
  }
  return out;
}

export function mergeRecapUserEdits(input: {
  generated: readonly RecapSection[];
  edited?: readonly RecapSection[];
  reset?: boolean;
}): MergeRecapEditsResult {
  const generated = dedupeByFirst(input.generated);
  const edited = dedupeByFirst(input.edited ?? []);
  const editedByKey = new Map(edited.map((s) => [s.key, s]));

  const sections: RecapSection[] = [];
  const preserved: string[] = [];
  const regenerated: string[] = [];

  for (const gen of generated) {
    const edit = editedByKey.get(gen.key);
    if (!input.reset && edit !== undefined && edit.body.trim() !== "") {
      sections.push({ key: gen.key, body: edit.body });
      preserved.push(gen.key);
    } else {
      sections.push({ key: gen.key, body: gen.body });
      regenerated.push(gen.key);
    }
  }

  if (!input.reset) {
    const generatedKeys = new Set(generated.map((s) => s.key));
    const editedOnly = edited
      .filter((s) => !generatedKeys.has(s.key))
      .filter((s) => s.body.trim() !== "")
      .sort((a, b) => (a.key < b.key ? -1 : a.key > b.key ? 1 : 0));
    for (const edit of editedOnly) {
      sections.push({ key: edit.key, body: edit.body });
      preserved.push(edit.key);
    }
  }

  return { sections, preserved, regenerated };
}

/**
 * Fallback selection for the daily journal recap (issue #2051).
 *
 * Picks the journal body in precedence order: AI render, then the last stored
 * journal, then the deterministic render. A blank body at any level falls
 * through to the next one, so a provider failure never replaces a stored good
 * journal with a thinner deterministic render. This function takes no card
 * list and performs no writes, so discarding deterministic source cards is not
 * something it can do; storage callers own that decision.
 *
 * Pure: no I/O, no clock. Does not mutate its input. Internal helper; wiring
 * into the recap build path is a later slice.
 */

import { isAnalysisFailureKind } from "./analysis-failure.js";

export const RECAP_SOURCE_KINDS = ["ai", "deterministic", "previous"] as const;
export type RecapSourceKind = (typeof RECAP_SOURCE_KINDS)[number];

export interface RecapCandidate {
  /** Rendered journal body. */
  body: string;
  kind: RecapSourceKind;
}

export type RecapSelection =
  | { ok: true; body: string; kind: RecapSourceKind; failure?: string }
  | { ok: false; error: "no_recap_available"; failure?: string };

const SLOT_ORDER: readonly RecapSourceKind[] = [
  "ai",
  "previous",
  "deterministic",
];

function isRecapSourceKind(value: unknown): value is RecapSourceKind {
  return (
    typeof value === "string" &&
    (RECAP_SOURCE_KINDS as readonly string[]).includes(value)
  );
}

/** Select the journal body for one day. Throws TypeError on a bad kind. */
export function selectRecapForDay(input: {
  /** Present only when the AI run succeeded and validated. */
  ai?: RecapCandidate | null;
  /** Always available when cards exist: the deterministic render. */
  deterministic?: RecapCandidate | null;
  /** The last valid stored journal for this day, if any. */
  previous?: RecapCandidate | null;
  /**
   * Typed failure kind from a provider error, when one occurred. Validated
   * against the analysis-failure allow-list: an arbitrary string here would
   * flow into telemetry and downstream exhaustive handling as though it were
   * a known kind, so a misspelled "timeot" is refused instead of echoed.
   */
  failure?: string | null;
}): RecapSelection {
  let failure: string | undefined;
  if (input.failure !== undefined && input.failure !== null) {
    if (!isAnalysisFailureKind(input.failure)) {
      throw new TypeError(
        `unknown recap failure kind; expected one of the analysis failure kinds, got a non-allow-listed value`,
      );
    }
    failure = input.failure;
  }

  // Validate every supplied candidate FIRST. Returning on the first valid
  // body would let a malformed lower-priority candidate hide behind a valid
  // higher-priority one, so the kind contract would hold only sometimes.
  for (const slot of SLOT_ORDER) {
    const candidate = input[slot];
    if (candidate == null) continue;

    const kind = candidate.kind;
    if (!isRecapSourceKind(kind)) {
      throw new TypeError(
        `unknown recap source kind: ${String(kind)}; allowed kinds: ${RECAP_SOURCE_KINDS.join(", ")}`,
      );
    }
    if (kind !== slot) {
      throw new TypeError(
        `recap candidate passed as "${slot}" has kind "${kind}"; kind must match its slot`,
      );
    }
    if (typeof candidate.body !== "string") {
      throw new TypeError(
        `recap candidate body for slot "${slot}" must be a string`,
      );
    }
  }

  for (const slot of SLOT_ORDER) {
    const candidate = input[slot];
    if (candidate == null) continue;
    if (candidate.body.trim() === "") continue;
    return failure === undefined
      ? { ok: true, body: candidate.body, kind: candidate.kind }
      : { ok: true, body: candidate.body, kind: candidate.kind, failure };
  }

  return failure === undefined
    ? { ok: false, error: "no_recap_available" }
    : { ok: false, error: "no_recap_available", failure };
}

/**
 * Extract a unique ATX heading section (issue #1987).
 *
 * Pure string helper. No filesystem. Missing heading returns null.
 * Duplicate headings refuse. Empty headings are rejected.
 */

export type ExtractJournalSectionResult =
  | string
  | null
  | { error: "duplicate_heading" }
  | { error: "empty_heading" };

export function extractJournalSection(
  markdown: string,
  heading: string,
): ExtractJournalSectionResult {
  const wanted = heading.trim();
  if (wanted.length === 0) return { error: "empty_heading" };

  const lines = splitFileLines(markdown);
  const hits: number[] = [];
  const levels: number[] = [];
  for (let i = 0; i < lines.length; i++) {
    const parsed = parseAtxHeading(lines[i]!);
    if (parsed && parsed.text === wanted) {
      hits.push(i);
      levels.push(parsed.level);
    }
  }
  if (hits.length === 0) return null;
  if (hits.length > 1) return { error: "duplicate_heading" };

  const headingIndex = hits[0]!;
  const level = levels[0]!;
  let endIndex = lines.length;
  for (let i = headingIndex + 1; i < lines.length; i++) {
    const parsed = parseAtxHeading(lines[i]!);
    if (parsed && parsed.level <= level) {
      endIndex = i;
      break;
    }
  }
  return lines.slice(headingIndex + 1, endIndex).join("\n");
}

function splitFileLines(fileText: string): string[] {
  const lines = fileText.split("\n");
  for (let i = 0; i < lines.length; i++) {
    const line = lines[i]!;
    if (line.endsWith("\r")) lines[i] = line.slice(0, -1);
  }
  return lines;
}

export function parseAtxHeading(line: string): { level: number; text: string } | null {
  let level = 0;
  while (level < line.length && level < 6 && line[level] === "#") level++;
  if (level === 0) return null;
  const after = line[level];
  if (after !== " " && after !== "\t") return null;

  let start = level + 1;
  let end = line.length;
  while (start < end && (line[start] === " " || line[start] === "\t")) start++;
  while (end > start && (line[end - 1] === " " || line[end - 1] === "\t")) end--;

  let hashEnd = end;
  while (hashEnd > start && line[hashEnd - 1] === "#") hashEnd--;
  if (hashEnd < end && hashEnd > start && (line[hashEnd - 1] === " " || line[hashEnd - 1] === "\t")) {
    end = hashEnd;
    while (end > start && (line[end - 1] === " " || line[end - 1] === "\t")) end--;
  }
  return { level, text: line.slice(start, end) };
}

/**
 * Parse the activity privacy enabled flag (issue #2053 leftover).
 *
 * Boolean passthrough. String tokens true/1/yes/on and false/0/no/off.
 * Unknown values fail closed as invalid_enabled.
 */

export type ParsePrivacyEnabledResult =
  | { ok: true; enabled: boolean }
  | { ok: false; error: "invalid_enabled" };

const ENABLED_TOKENS: Record<string, boolean> = {
  true: true,
  "1": true,
  yes: true,
  on: true,
  false: false,
  "0": false,
  no: false,
  off: false,
};

/** Accept a boolean or known token. Unknown values are invalid_enabled. */
export function parsePrivacyEnabled(value: unknown): ParsePrivacyEnabledResult {
  if (typeof value === "boolean") return { ok: true, enabled: value };
  if (typeof value === "string") {
    const token = value.trim().toLowerCase();
    if (Object.hasOwn(ENABLED_TOKENS, token)) {
      return { ok: true, enabled: ENABLED_TOKENS[token] };
    }
  }
  return { ok: false, error: "invalid_enabled" };
}

import crypto from "node:crypto";
import {
  type ObjectiveStateChangeKind,
  type ObjectiveStateOutcome,
  type ObjectiveStateSnapshot,
  recordObjectiveStateSnapshot,
} from "./objective-state.js";
import {
  parseMessageParts,
  type LcmMessagePartInput,
  type MessagePartSourceFormat,
} from "./message-parts/index.js";

interface ToolCallContext {
  toolName?: string;
  toolCallId?: string;
  args?: Record<string, unknown>;
}

interface DerivedObjectiveStateResult {
  snapshots: ObjectiveStateSnapshot[];
  filePaths: string[];
}

interface ObservedMessageWithParts {
  role?: string;
  content?: string;
  parts?: LcmMessagePartInput[] | null;
  rawContent?: unknown;
  sourceFormat?: MessagePartSourceFormat;
}

interface ObservedPartEntry {
  messageIndex: number;
  partIndex: number;
  part: LcmMessagePartInput;
}

const rawProviderParts = new WeakSet<LcmMessagePartInput>();

function markRawProviderParts(parts: LcmMessagePartInput[]): LcmMessagePartInput[] {
  for (const part of parts) {
    rawProviderParts.add(part);
  }
  return parts;
}

function isRawProviderPart(part: LcmMessagePartInput): boolean {
  return rawProviderParts.has(part);
}

function hashSha256(value: string): string {
  return crypto.createHash("sha256").update(value).digest("hex");
}

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

function optionalString(value: unknown): string | undefined {
  if (typeof value !== "string") return undefined;
  const trimmed = value.trim();
  return trimmed.length > 0 ? trimmed : undefined;
}

function toolNameTokens(toolName: string | undefined): string[] {
  if (!toolName) return [];
  return toolName
    .replace(/([a-z0-9])([A-Z])/g, "$1_$2")
    .toLowerCase()
    .split(/[^a-z0-9]+/)
    .filter((token) => token.length > 0);
}

function normalizedToolName(toolName: string | undefined): string {
  return toolNameTokens(toolName).join("_");
}

function parseToolArguments(value: unknown): Record<string, unknown> | undefined {
  if (isRecord(value)) return value;
  if (typeof value !== "string") return undefined;
  try {
    const parsed = JSON.parse(value) as unknown;
    return isRecord(parsed) ? parsed : undefined;
  } catch {
    return undefined;
  }
}

function stableStringify(value: unknown): string {
  if (Array.isArray(value)) {
    return `[${value.map((entry) => stableStringify(entry)).join(",")}]`;
  }
  if (isRecord(value)) {
    return `{${Object.keys(value)
      .sort()
      .map((key) => `${JSON.stringify(key)}:${stableStringify(value[key])}`)
      .join(",")}}`;
  }
  return JSON.stringify(value) ?? String(value);
}

function extractTextContent(value: unknown): string {
  if (typeof value === "string") return value.trim();
  if (Array.isArray(value)) {
    return value
      .map((block) => {
        if (typeof block === "string") return block.trim();
        if (isRecord(block) && block.type === "text" && typeof block.text === "string") {
          return block.text.trim();
        }
        return "";
      })
      .filter((item) => item.length > 0)
      .join("\n");
  }
  if (isRecord(value)) {
    return JSON.stringify(value);
  }
  return "";
}

function parseToolResultPayload(content: unknown): unknown {
  const text = extractTextContent(content);
  if (text.length === 0) return undefined;
  try {
    return JSON.parse(text) as unknown;
  } catch {
    return text;
  }
}

function resultHash(value: unknown): string | undefined {
  if (value === undefined) return undefined;
  const canonical =
    typeof value === "string" ? value : stableStringify(value);
  if (!canonical || canonical.length === 0) return undefined;
  return `sha256:${hashSha256(canonical)}`;
}

function getToolCallContexts(messages: Array<Record<string, unknown>>): Map<string, ToolCallContext> {
  const contexts = new Map<string, ToolCallContext>();
  for (const message of messages) {
    if (message.role !== "assistant") continue;
    const toolCalls = message.tool_calls ?? message.toolCalls;
    if (!Array.isArray(toolCalls)) continue;
    for (const call of toolCalls) {
      if (!isRecord(call)) continue;
      const toolCallId = optionalString(call.id) ?? optionalString(call.toolCallId);
      if (!toolCallId) continue;
      const fn = isRecord(call.function) ? call.function : undefined;
      const toolName =
        optionalString(fn?.name) ??
        optionalString(call.name);
      const args =
        parseToolArguments(fn?.arguments) ??
        parseToolArguments(call.arguments) ??
        parseToolArguments(call.args) ??
        parseToolArguments(call.input);
      contexts.set(toolCallId, { toolCallId, toolName, args });
    }
  }
  return contexts;
}

function toolCallIdForMessage(message: Record<string, unknown>): string | undefined {
  return (
    optionalString(message.tool_call_id) ??
    optionalString(message.toolCallId) ??
    optionalString(message.tool_use_id) ??
    optionalString(message.toolUseId)
  );
}

function toolNameForMessage(message: Record<string, unknown>, context?: ToolCallContext): string | undefined {
  return (
    optionalString(message.name) ??
    optionalString(message.toolName) ??
    optionalString(message.tool) ??
    context?.toolName
  );
}

function pickString(args: Record<string, unknown> | undefined, keys: string[]): string | undefined {
  if (!args) return undefined;
  for (const key of keys) {
    const value = optionalString(args[key]);
    if (value) return value;
  }
  return undefined;
}

function pickFirstStringArrayValue(args: Record<string, unknown> | undefined, key: string): string | undefined {
  const value = args?.[key];
  if (!Array.isArray(value)) return undefined;
  for (const item of value) {
    const candidate = optionalString(item);
    if (candidate) return candidate;
  }
  return undefined;
}

function fileScopeFromArgs(args: Record<string, unknown> | undefined): {
  scope?: string;
  sourcePath?: string;
  destinationPath?: string;
} {
  const destinationPath =
    pickString(args, ["destination", "dest", "targetPath", "target", "to"]) ??
    pickString(args, ["path", "filePath", "workspacePath", "projectPath"]) ??
    pickFirstStringArrayValue(args, "paths");
  const sourcePath =
    pickString(args, ["source", "src", "from", "oldPath"]);
  const scope = destinationPath ?? sourcePath;
  return { scope, sourcePath, destinationPath };
}

function fileContentHash(args: Record<string, unknown> | undefined): string | undefined {
  const content =
    pickString(args, ["content", "patch", "diff", "text", "value"]) ??
    args?.updates;
  return resultHash(content);
}

function inferOutcome(message: Record<string, unknown>, parsedPayload: unknown): ObjectiveStateOutcome {
  if (message.isError === true) return "failure";
  if (isRecord(parsedPayload)) {
    if (parsedPayload.partial === true || parsedPayload.status === "partial") return "partial";
    if (parsedPayload.success === false || parsedPayload.ok === false) return "failure";
    if (parsedPayload.success === true || parsedPayload.ok === true) return "success";
    if (typeof parsedPayload.exitCode === "number") {
      return parsedPayload.exitCode === 0 ? "success" : "failure";
    }
    if (optionalString(parsedPayload.error)) return "failure";
    if (parsedPayload.status === "error" || parsedPayload.status === "failed") return "failure";
    if (parsedPayload.status === "ok" || parsedPayload.status === "success") return "success";
    const outputText = [
      optionalString(parsedPayload.stdout),
      optionalString(parsedPayload.stderr),
    ].filter((entry): entry is string => entry !== undefined).join("\n");
    if (outputText) {
      const outputOutcome = inferOutcome({}, outputText);
      if (outputOutcome !== "unknown") return outputOutcome;
    }
  }
  if (typeof parsedPayload === "string") {
    const lowered = parsedPayload.toLowerCase();
    const loweredForFailure = lowered
      .replace(/\b(?:previously\s+)?failed tests?\s+now\s+pass(?:ed|es)?\b/g, "");
    const hasZeroCountMarker = /\b(?:0|no)\s+(?:errors?|failures?|exceptions?|timeouts?)\b/.test(lowered);
    const loweredForFailureCounts = loweredForFailure
      .replace(/\b(?:0|no)\s+errors?\b/g, "")
      .replace(/\b(?:0|no)\s+failures?\b/g, "")
      .replace(/\b(?:0|no)\s+exceptions?\b/g, "")
      .replace(/\b(?:0|no)\s+timeouts?\b/g, "");
    const hasNonZeroErrorCounts = /\b[1-9]\d*\s+errors?\b/.test(loweredForFailureCounts);
    const hasNegatedSuccessMarkers =
      /\b(?:not|did not|didn't|doesn't|isn't|aren't|wasn't|weren't|won't|can't|couldn't|shouldn't|wouldn't)\s+(?:ok|pass|passed|passes|succeeded|success)\b/.test(loweredForFailure);
    const hasSuccessMarkers =
      /\b(success|succeeded|pass|passes|passed|ok)\b/.test(lowered) ||
      hasZeroCountMarker;
    const hasFailureMarkers =
      hasNegatedSuccessMarkers ||
      /\b(exceptions?|failed|failures?|fatal|timeouts?|timed out)\b/.test(loweredForFailureCounts) ||
      hasNonZeroErrorCounts ||
      /\berrors?\b/.test(loweredForFailureCounts) ||
      /\b[a-z]+error\b/.test(loweredForFailureCounts) ||
      /\b[a-z]+exception\b/.test(loweredForFailureCounts);

    if (hasFailureMarkers) return "failure";
    if (hasSuccessMarkers) return "success";
  }
  return "unknown";
}

function isProcessTool(toolName: string | undefined, args: Record<string, unknown> | undefined): boolean {
  const tokens = toolNameTokens(toolName);
  const normalizedName = normalizedToolName(toolName);
  if (pickString(args, ["cmd", "command", "script"])) return true;
  return ["exec", "shell", "bash", "terminal", "run_command", "exec_command"].some((token) =>
    token.includes("_") ? normalizedName === token : tokens.includes(token),
  );
}

function isFileTool(toolName: string | undefined, args: Record<string, unknown> | undefined): boolean {
  const tokens = toolNameTokens(toolName);
  const fileScope = fileScopeFromArgs(args);
  if (fileScope.scope) return true;
  return ["file", "path", "patch", "directory", "mkdir", "rename", "move"].some((token) =>
    tokens.includes(token),
  );
}

function inferFileChangeKind(toolName: string | undefined, outcome: ObjectiveStateOutcome): ObjectiveStateChangeKind {
  if (outcome === "failure") return "failed";
  const tokens = toolNameTokens(toolName);
  if (["delete", "remove", "unlink"].some((token) => tokens.includes(token))) return "deleted";
  if (["create", "mkdir", "new"].some((token) => tokens.includes(token))) return "created";
  if (["write", "edit", "patch", "update", "append", "move", "rename"].some((token) => tokens.includes(token))) {
    return "updated";
  }
  return "observed";
}

function buildFileValueRefs(
  args: Record<string, unknown> | undefined,
  changeKind: ObjectiveStateChangeKind,
): Pick<ObjectiveStateSnapshot, "before" | "after"> {
  const { sourcePath, destinationPath, scope } = fileScopeFromArgs(args);
  const contentHash = fileContentHash(args);

  if (changeKind === "failed") {
    if (sourcePath && destinationPath && sourcePath !== destinationPath) {
      return {
        before: { ref: sourcePath },
        after: { ref: destinationPath },
      };
    }
    return {
      before: sourcePath ? { ref: sourcePath } : undefined,
      after: scope ? { ref: scope } : undefined,
    };
  }

  if (changeKind === "deleted") {
    return {
      before: scope ? { exists: true, ref: scope } : undefined,
      after: { exists: false },
    };
  }

  if (changeKind === "created") {
    return {
      after: {
        exists: true,
        ref: scope,
        valueHash: contentHash,
      },
    };
  }

  if (sourcePath && destinationPath && sourcePath !== destinationPath) {
    return {
      before: { exists: true, ref: sourcePath },
      after: {
        exists: true,
        ref: destinationPath,
      },
    };
  }

  return {
    after: {
      exists: true,
      ref: scope,
      valueHash: contentHash,
    },
  };
}

function summarizeSnapshot(
  kind: ObjectiveStateSnapshot["kind"],
  changeKind: ObjectiveStateChangeKind,
  toolName: string,
  scope: string,
): string {
  const action =
    changeKind === "executed"
      ? "Executed"
      : changeKind === "failed"
        ? "Failed"
        : changeKind === "created"
          ? "Created"
          : changeKind === "deleted"
            ? "Deleted"
            : changeKind === "updated"
              ? "Updated"
              : "Observed";
  if (kind === "process") return `${action} process via ${toolName}: ${scope}`;
  if (kind === "file") return `${action} file via ${toolName}: ${scope}`;
  return `${action} tool result from ${toolName}: ${scope}`;
}

function buildGenericToolAfterRef(outcome: ObjectiveStateOutcome, parsedPayload: unknown): ObjectiveStateSnapshot["after"] {
  const valueHash = resultHash(parsedPayload);
  return valueHash ? { valueHash } : { exists: outcome !== "failure" };
}

function snapshotIdFor(
  sessionKey: string,
  recordedAt: string,
  index: number,
  toolName: string,
  scope: string,
  stableKey?: string,
): string {
  const digest = crypto
    .createHash("sha256")
    .update(
      stableKey
        ? `${sessionKey}|${recordedAt}|${index}|${toolName}|${scope}|stable|${stableKey}`
        : `${sessionKey}|${recordedAt}|${index}|${toolName}|${scope}`,
    )
    .digest("hex")
    .slice(0, 12);
  return `obj-${digest}`;
}

function objectiveStatePartsForObservedMessage(
  message: ObservedMessageWithParts,
): LcmMessagePartInput[] {
  if (message.role === "user") {
    const explicitParts = Array.isArray(message.parts) && message.parts.length > 0
      ? sanitizeUserRoleToolResultParts(message.parts)
      : [];
    if (Array.isArray(message.parts) && message.parts.length > 0) {
      const rawParts = userRawToolResultParts(message);
      return mergeObservedEvidenceParts(explicitParts, rawParts);
    }
    return userRawToolResultParts(message);
  }
  if (message.role !== "assistant") {
    return [];
  }
  const explicitParts = Array.isArray(message.parts) && message.parts.length > 0
    ? message.parts
    : [];
  const rawParts = assistantRawObjectiveStateParts(message);
  return mergeObservedEvidenceParts(explicitParts, rawParts);
}

function userRawToolResultParts(message: ObservedMessageWithParts): LcmMessagePartInput[] {
  const rawContent = message.rawContent ?? message.content;
  if (!containsProviderToolResultBlock(rawContent)) {
    return [];
  }
  return markRawProviderParts(
    sanitizeUserRoleToolResultParts(parseMessageParts(rawContent, {
      sourceFormat: message.sourceFormat,
      allowRenderedFallback: false,
    })),
  );
}

function assistantRawObjectiveStateParts(message: ObservedMessageWithParts): LcmMessagePartInput[] {
  if (message.rawContent === undefined || message.rawContent === null) {
    return [];
  }
  return markRawProviderParts(parseMessageParts(message.rawContent, {
    sourceFormat: message.sourceFormat,
    allowRenderedFallback: false,
  }));
}

function mergeObservedEvidenceParts(
  explicitParts: LcmMessagePartInput[],
  rawParts: LcmMessagePartInput[],
): LcmMessagePartInput[] {
  if (explicitParts.length === 0) return rawParts;
  if (rawParts.length === 0) return explicitParts;

  const merged = [...explicitParts];
  const seen = new Set(
    explicitParts
      .filter(isObjectiveStateEvidencePart)
      .map(objectiveStateEvidencePartKey),
  );

  for (const part of rawParts) {
    if (!isObjectiveStateEvidencePart(part)) continue;
    const key = objectiveStateEvidencePartKey(part);
    if (seen.has(key)) continue;
    seen.add(key);
    merged.push(part);
  }

  return merged;
}

function isObjectiveStateEvidencePart(part: LcmMessagePartInput): boolean {
  return (
    part.kind === "tool_call" ||
    part.kind === "tool_result" ||
    part.kind === "file_write" ||
    part.kind === "patch"
  );
}

function objectiveStateEvidencePartKey(part: LcmMessagePartInput): string {
  const id = partToolCallId(part);
  if (id) return `${part.kind}:id:${id}`;
  const toolName = partToolName(part) ?? "";
  const filePath = partFilePath(part) ?? "";
  return `${part.kind}:shape:${toolName}:${filePath}:${stableStringify(partPayload(part))}`;
}

function flattenObservedParts(messages: readonly ObservedMessageWithParts[]): ObservedPartEntry[] {
  const entries: ObservedPartEntry[] = [];
  messages.forEach((message, messageIndex) => {
    const parts = objectiveStatePartsForObservedMessage(message);
    parts.forEach((part, partIndex) => {
      entries.push({ messageIndex, partIndex, part });
    });
  });
  return entries.sort((a, b) => {
    if (a.messageIndex !== b.messageIndex) return a.messageIndex - b.messageIndex;
    const aOrdinal = typeof a.part.ordinal === "number" ? a.part.ordinal : a.partIndex;
    const bOrdinal = typeof b.part.ordinal === "number" ? b.part.ordinal : b.partIndex;
    if (aOrdinal !== bOrdinal) return aOrdinal - bOrdinal;
    return a.partIndex - b.partIndex;
  });
}

function sanitizeUserRoleToolResultParts(parts: LcmMessagePartInput[]): LcmMessagePartInput[] {
  return parts
    .filter((part) => part.kind === "tool_result")
    .map((part) => {
      const payload = { ...partPayload(part) };
      delete payload.name;
      delete payload.tool;
      delete payload.toolName;
      delete payload.tool_name;
      return {
        ...part,
        toolName: null,
        tool_name: null,
        payload,
      };
    });
}

function containsProviderToolResultBlock(value: unknown): boolean {
  if (Array.isArray(value)) {
    return value.some(containsProviderToolResultBlock);
  }
  if (!isRecord(value)) return false;
  const type = optionalString(value.type ?? value.kind);
  if (
    type === "tool_result" ||
    type === "function_call_output"
  ) {
    return true;
  }
  return (
    containsProviderToolResultBlock(value.content) ||
    containsProviderToolResultBlock(value.output) ||
    containsProviderToolResultBlock(value.items)
  );
}

function partPayload(part: LcmMessagePartInput): Record<string, unknown> {
  return isRecord(part.payload) ? part.payload : {};
}

function partToolCallId(part: LcmMessagePartInput): string | undefined {
  const payload = partPayload(part);
  return (
    optionalString(payload.call_id) ??
    optionalString(payload.callId) ??
    optionalString(payload.id) ??
    optionalString(payload.tool_call_id) ??
    optionalString(payload.toolCallId) ??
    optionalString(payload.tool_use_id) ??
    optionalString(payload.toolUseId)
  );
}

function partToolName(part: LcmMessagePartInput): string | undefined {
  const payload = partPayload(part);
  return (
    optionalString(part.toolName) ??
    optionalString(part.tool_name) ??
    optionalString(payload.name) ??
    optionalString(payload.toolName) ??
    optionalString(payload.tool_name) ??
    (part.kind === "patch" ? "apply_patch" : undefined) ??
    (part.kind === "file_write" ? "file_write" : undefined)
  );
}

function partFilePath(part: LcmMessagePartInput): string | undefined {
  const payload = partPayload(part);
  return (
    optionalString(part.filePath) ??
    optionalString(part.file_path) ??
    optionalString(payload.path) ??
    optionalString(payload.filePath) ??
    optionalString(payload.file_path)
  );
}

function syntheticPartId(options: {
  sessionKey: string;
  messageIndex: number;
  partIndex: number;
  part: LcmMessagePartInput;
}): string {
  const digest = hashSha256(
    [
      options.sessionKey,
      String(options.messageIndex),
      String(options.part.ordinal ?? options.partIndex),
      options.part.kind,
      optionalString(options.part.toolName) ?? "",
      optionalString(options.part.tool_name) ?? "",
      optionalString(options.part.filePath) ?? "",
      optionalString(options.part.file_path) ?? "",
      stableStringify(options.part.payload),
    ].join("|"),
  ).slice(0, 12);
  return `part-${digest}`;
}

function toolArgumentsFromPart(part: LcmMessagePartInput): Record<string, unknown> {
  const payload = partPayload(part);
  const parsedArgs =
    parseToolArguments(payload.arguments) ??
    parseToolArguments(payload.input) ??
    parseToolArguments(payload.args) ??
    parseToolArguments(payload.params) ??
    payload;
  const args = { ...parsedArgs };
  const filePath = partFilePath(part);
  if (filePath && !pickString(args, ["path", "filePath", "file_path"])) {
    args.path = filePath;
  }
  if (part.kind === "patch" && !pickString(args, ["patch", "diff", "text"])) {
    const text = optionalString(payload.text) ?? optionalString(payload.patch);
    if (text) args.patch = text;
  }
  return args;
}

function toolResultContentFromPart(part: LcmMessagePartInput): unknown {
  const payload = partPayload(part);
  if ("output" in payload) return payload.output;
  if ("content" in payload) return payload.content;
  if ("result" in payload) return payload.result;
  if ("value" in payload) return payload.value;
  return payload;
}

function inlineToolResultContentFromPart(part: LcmMessagePartInput): unknown {
  const payload = partPayload(part);
  if (hasDefinedPayloadKey(payload, "output")) return payload.output;
  if (hasDefinedPayloadKey(payload, "result")) return payload.result;
  if (part.kind === "tool_result" && hasDefinedPayloadKey(payload, "value")) {
    return payload.value;
  }

  const statusPayload: Record<string, unknown> = {};
  for (const key of ["exitCode", "ok", "success", "error", "stdout", "stderr"]) {
    if (hasDefinedPayloadKey(payload, key)) {
      statusPayload[key] = payload[key];
    }
  }
  return Object.keys(statusPayload).length > 0 ? statusPayload : payload;
}

function hasDefinedPayloadKey(payload: Record<string, unknown>, key: string): boolean {
  return Object.prototype.hasOwnProperty.call(payload, key) && payload[key] !== undefined;
}

function partHasInlineToolResult(part: LcmMessagePartInput): boolean {
  const payload = partPayload(part);
  return (
    hasDefinedPayloadKey(payload, "output") ||
    hasDefinedPayloadKey(payload, "result") ||
    (part.kind === "tool_result" && hasDefinedPayloadKey(payload, "value")) ||
    hasDefinedPayloadKey(payload, "exitCode") ||
    hasDefinedPayloadKey(payload, "ok") ||
    hasDefinedPayloadKey(payload, "success") ||
    hasDefinedPayloadKey(payload, "error") ||
    hasDefinedPayloadKey(payload, "stdout") ||
    hasDefinedPayloadKey(payload, "stderr")
  );
}

function toolResultIsError(part: LcmMessagePartInput): boolean {
  const payload = partPayload(part);
  return payload.isError === true ||
    payload.is_error === true ||
    payload.ok === false ||
    payload.success === false ||
    optionalString(payload.error) !== undefined;
}

function buildSyntheticAssistantToolCall(
  id: string,
  toolName: string,
  args: Record<string, unknown>,
): Record<string, unknown> {
  return {
    role: "assistant",
    tool_calls: [
      {
        id,
        function: {
          name: toolName,
          arguments: JSON.stringify(args),
        },
      },
    ],
  };
}

function observedPartsToAgentMessages(options: {
  sessionKey: string;
  messages: readonly ObservedMessageWithParts[];
}): Array<Record<string, unknown>> {
  const entries = flattenObservedParts(options.messages);
  const resultIds = new Set(
    entries
      .filter((entry) => entry.part.kind === "tool_result")
      .map((entry) => partToolCallId(entry.part))
      .filter((id): id is string => id !== undefined),
  );
  const synthetic: Array<Record<string, unknown>> = [];
  let pendingIdlessToolCallId: string | undefined;

  for (let entryIndex = 0; entryIndex < entries.length; entryIndex += 1) {
    const entry = entries[entryIndex]!;
    const { part } = entry;
    if (
      part.kind === "tool_call" ||
      part.kind === "file_write" ||
      part.kind === "patch"
    ) {
      const toolName = partToolName(part);
      if (!toolName) continue;
      const observedToolCallId = partToolCallId(part);
      const id = observedToolCallId ??
        syntheticPartId({
          sessionKey: options.sessionKey,
          messageIndex: entry.messageIndex,
          partIndex: entry.partIndex,
          part,
        });
      const args = toolArgumentsFromPart(part);
      synthetic.push(buildSyntheticAssistantToolCall(id, toolName, args));
      const nextEntry = entries[entryIndex + 1];
      const nextIsIdlessToolResult =
        nextEntry?.part.kind === "tool_result" &&
        partToolCallId(nextEntry.part) === undefined;
      pendingIdlessToolCallId = nextIsIdlessToolResult
        ? id
        : undefined;

      const hasSeparateToolResult = resultIds.has(id) || nextIsIdlessToolResult;
      if (partHasInlineToolResult(part) && !hasSeparateToolResult) {
        synthetic.push({
          role: "tool",
          tool_call_id: id,
          name: toolName,
          content: inlineToolResultContentFromPart(part),
          ...(toolResultIsError(part) ? { isError: true } : {}),
        });
        pendingIdlessToolCallId = undefined;
        continue;
      }

      if (
        (part.kind === "file_write" || part.kind === "patch") &&
        !nextIsIdlessToolResult &&
        !resultIds.has(id) &&
        !isRawProviderPart(part)
      ) {
        synthetic.push({
          role: "tool",
          tool_call_id: id,
          name: toolName,
          content: { ok: true, source: "message_part" },
        });
        pendingIdlessToolCallId = undefined;
      }
      continue;
    }

    if (part.kind === "tool_result") {
      const id = partToolCallId(part) ?? pendingIdlessToolCallId;
      const toolName = partToolName(part);
      synthetic.push({
        role: "tool",
        ...(id ? { tool_call_id: id } : {}),
        ...(toolName ? { name: toolName } : {}),
        content: toolResultContentFromPart(part),
        ...(toolResultIsError(part) ? { isError: true } : {}),
      });
      pendingIdlessToolCallId = undefined;
    }
  }

  return synthetic;
}

export function deriveObjectiveStateSnapshotsFromAgentMessages(options: {
  sessionKey: string;
  recordedAt: string;
  messages: Array<Record<string, unknown>>;
}): ObjectiveStateSnapshot[] {
  const toolCallsById = getToolCallContexts(options.messages);
  const snapshots: ObjectiveStateSnapshot[] = [];

  for (const message of options.messages) {
    if (message.role !== "tool") continue;
    const toolCallId = toolCallIdForMessage(message);
    const context = toolCallId ? toolCallsById.get(toolCallId) : undefined;
    const toolName = toolNameForMessage(message, context);
    if (!toolName) continue;

    const parsedPayload = parseToolResultPayload(message.content);
    const outcome = inferOutcome(message, parsedPayload);
    const args = context?.args;
    const command = pickString(args, ["cmd", "command", "script"]);

    let kind: ObjectiveStateSnapshot["kind"] = "tool";
    let changeKind: ObjectiveStateChangeKind = outcome === "failure" ? "failed" : "observed";
    let scope = toolName;
    let before: ObjectiveStateSnapshot["before"];
    let after: ObjectiveStateSnapshot["after"];

    if (isProcessTool(toolName, args)) {
      kind = "process";
      changeKind = outcome === "failure" ? "failed" : "executed";
      scope = command ?? toolName;
      after = { exists: outcome !== "failure", valueHash: resultHash(parsedPayload) };
    } else if (isFileTool(toolName, args)) {
      kind = "file";
      changeKind = inferFileChangeKind(toolName, outcome);
      const fileScope = fileScopeFromArgs(args);
      scope = fileScope.scope ?? toolName;
      const refs = buildFileValueRefs(args, changeKind);
      before = refs.before;
      after = refs.after;
    } else {
      after = buildGenericToolAfterRef(outcome, parsedPayload);
    }

    snapshots.push({
      schemaVersion: 1,
      snapshotId: snapshotIdFor(
        options.sessionKey,
        options.recordedAt,
        snapshots.length,
        toolName,
        scope,
        toolCallId,
      ),
      recordedAt: options.recordedAt,
      sessionKey: options.sessionKey,
      source: "tool_result",
      kind,
      changeKind,
      scope,
      summary: summarizeSnapshot(kind, changeKind, toolName, scope),
      toolName,
      command,
      outcome,
      before,
      after,
      tags: ["agent-end", `tool:${toolName}`],
      metadata: toolCallId ? { toolCallId } : undefined,
    });
  }

  return snapshots;
}

export function deriveObjectiveStateSnapshotsFromObservedMessages(options: {
  sessionKey: string;
  recordedAt: string;
  messages: readonly ObservedMessageWithParts[];
}): ObjectiveStateSnapshot[] {
  const syntheticMessages = observedPartsToAgentMessages({
    sessionKey: options.sessionKey,
    messages: options.messages,
  });
  if (syntheticMessages.length === 0) return [];

  return deriveObjectiveStateSnapshotsFromAgentMessages({
    sessionKey: options.sessionKey,
    recordedAt: options.recordedAt,
    messages: syntheticMessages,
  });
}

export async function recordObjectiveStateSnapshotsFromAgentMessages(options: {
  memoryDir: string;
  objectiveStateStoreDir?: string;
  objectiveStateMemoryEnabled: boolean;
  objectiveStateSnapshotWritesEnabled: boolean;
  sessionKey: string;
  recordedAt: string;
  messages: Array<Record<string, unknown>>;
}): Promise<DerivedObjectiveStateResult> {
  if (!options.objectiveStateMemoryEnabled || !options.objectiveStateSnapshotWritesEnabled) {
    return { snapshots: [], filePaths: [] };
  }

  const snapshots = deriveObjectiveStateSnapshotsFromAgentMessages({
    sessionKey: options.sessionKey,
    recordedAt: options.recordedAt,
    messages: options.messages,
  });

  const filePaths: string[] = [];
  for (const snapshot of snapshots) {
    filePaths.push(
      await recordObjectiveStateSnapshot({
        memoryDir: options.memoryDir,
        objectiveStateStoreDir: options.objectiveStateStoreDir,
        snapshot,
      }),
    );
  }

  return { snapshots, filePaths };
}

export async function recordObjectiveStateSnapshotsFromObservedMessages(options: {
  memoryDir: string;
  objectiveStateStoreDir?: string;
  objectiveStateMemoryEnabled: boolean;
  objectiveStateSnapshotWritesEnabled: boolean;
  sessionKey: string;
  recordedAt: string;
  messages: readonly ObservedMessageWithParts[];
}): Promise<DerivedObjectiveStateResult> {
  if (!options.objectiveStateMemoryEnabled || !options.objectiveStateSnapshotWritesEnabled) {
    return { snapshots: [], filePaths: [] };
  }

  const snapshots = deriveObjectiveStateSnapshotsFromObservedMessages({
    sessionKey: options.sessionKey,
    recordedAt: options.recordedAt,
    messages: options.messages,
  });

  const filePaths: string[] = [];
  for (const snapshot of snapshots) {
    filePaths.push(
      await recordObjectiveStateSnapshot({
        memoryDir: options.memoryDir,
        objectiveStateStoreDir: options.objectiveStateStoreDir,
        snapshot,
      }),
    );
  }

  return { snapshots, filePaths };
}

/**
 * Recall disclosure auto-escalation policy (issue #677 PR 4/4).
 *
 * Pure helper that decides the *effective* disclosure depth for a recall
 * given the configured policy and the observed top-K confidence.  Lives
 * outside `access-service.ts` so the decision logic can be unit-tested
 * exhaustively without booting an orchestrator.
 *
 * Policy summary:
 *
 *   manual (default):
 *     The caller's `disclosure` is honored verbatim.  Auto-escalation
 *     does not run.
 *
 *   auto:
 *     If the caller did NOT explicitly specify a disclosure (i.e. the
 *     value in use is the system default) AND the recall's top-K
 *     confidence falls below the configured threshold, escalate from
 *     `chunk` to `section`.  `raw` is never auto-selected — it requires
 *     an explicit caller request because of its higher cost and the
 *     LCM-archive read paths it activates.  If the caller explicitly
 *     passed a disclosure (even `chunk`), the policy respects that
 *     choice and does not escalate.
 *
 * The threshold compares against `final` from the top result's score
 * decomposition.  When the snapshot has no results or no scores, no
 * escalation fires (`undefined` confidence is treated as "skip" rather
 * than "always escalate").
 */

import type { RecallDisclosure } from "./types.js";

export type DisclosureEscalationMode = "manual" | "auto";

export const DISCLOSURE_ESCALATION_MODES: readonly DisclosureEscalationMode[] = [
  "manual",
  "auto",
] as const;

export function isDisclosureEscalationMode(
  value: unknown,
): value is DisclosureEscalationMode {
  return (
    typeof value === "string" &&
    (DISCLOSURE_ESCALATION_MODES as readonly string[]).includes(value)
  );
}

/**
 * Threshold defaults — applied when config-side coercion produces an
 * out-of-range or missing value.  0.5 is a deliberate midpoint:
 * confidently-served recalls (top-K >= 0.5) stay on the cheap chunk
 * tier; ambiguous recalls escalate to section.
 */
export const DEFAULT_DISCLOSURE_ESCALATION_THRESHOLD = 0.5;

export interface DisclosureEscalationDecision {
  /** The disclosure depth the caller should use to shape the response. */
  effective: RecallDisclosure;
  /**
   * `true` when the policy escalated from the original disclosure;
   * `false` when the original was kept (either by manual mode, by
   * caller explicit choice, or because confidence stayed above the
   * threshold).
   */
  escalated: boolean;
  /**
   * Human-readable reason for the decision.  Always populated; surfaces
   * in operator-facing telemetry / debug paths.
   */
  reason: string;
}

export interface DecideDisclosureEscalationInput {
  /** The mode from config (`manual` | `auto`). */
  mode: DisclosureEscalationMode;
  /** Threshold in [0, 1]; values outside this range fall back to the default. */
  threshold: number;
  /** Disclosure resolved at request time (after default-fill). */
  originalDisclosure: RecallDisclosure;
  /**
   * Whether the caller explicitly specified a disclosure value.  Auto
   * mode only acts when the caller did NOT specify, so explicit
   * `chunk` requests are not silently upgraded.
   */
  callerProvidedDisclosure: boolean;
  /**
   * Top-K confidence (`final` score from the highest-ranked result),
   * or `undefined` when the snapshot has no scored results.
   */
  topKConfidence: number | undefined;
}

/**
 * Decide whether to escalate disclosure depth based on policy + signals.
 * Pure function — no IO, no state.
 */
export function decideDisclosureEscalation(
  input: DecideDisclosureEscalationInput,
): DisclosureEscalationDecision {
  if (input.mode === "manual") {
    return {
      effective: input.originalDisclosure,
      escalated: false,
      reason: "escalation-mode=manual",
    };
  }

  if (input.callerProvidedDisclosure) {
    return {
      effective: input.originalDisclosure,
      escalated: false,
      reason: "caller-explicit-disclosure",
    };
  }

  // Only chunk → section auto-escalation is allowed.  Section and raw
  // are never demoted; raw is never auto-selected.
  if (input.originalDisclosure !== "chunk") {
    return {
      effective: input.originalDisclosure,
      escalated: false,
      reason: `original-disclosure=${input.originalDisclosure}-not-eligible-for-auto`,
    };
  }

  if (
    input.topKConfidence === undefined ||
    !Number.isFinite(input.topKConfidence)
  ) {
    return {
      effective: input.originalDisclosure,
      escalated: false,
      reason: "no-top-k-confidence",
    };
  }

  const threshold =
    Number.isFinite(input.threshold) &&
    input.threshold >= 0 &&
    input.threshold <= 1
      ? input.threshold
      : DEFAULT_DISCLOSURE_ESCALATION_THRESHOLD;

  if (input.topKConfidence < threshold) {
    return {
      effective: "section",
      escalated: true,
      reason: `top-k-confidence=${input.topKConfidence.toFixed(3)}<${threshold}`,
    };
  }

  return {
    effective: input.originalDisclosure,
    escalated: false,
    reason: `top-k-confidence=${input.topKConfidence.toFixed(3)}>=${threshold}`,
  };
}

/**
 * Adapter interface for external system identity resolution.
 *
 * Each adapter maps an external system's session/identity conventions
 * to Engram's namespace + principal model. Adapters are stateless and
 * lightweight — they don't manage lifecycles or load plugins.
 */

export interface AdapterContext {
  /** Raw HTTP headers from the incoming request */
  headers: Record<string, string | string[] | undefined>;
  /** MCP client info (from initialize handshake, if available) */
  clientInfo?: { name: string; version?: string };
  /** Explicit session key from request args */
  sessionKey?: string;
  /** Explicit namespace from already-validated request args */
  namespace?: string;
  /** Explicit principal from already-validated request args */
  principal?: string;
}

export interface ResolvedIdentity {
  /** Engram namespace (scopes memory access) */
  namespace: string;
  /** False for an inferred namespace; omitted values retain explicit-namespace validation. */
  namespaceExplicit?: boolean;
  /** Engram principal (authorization subject) */
  principal: string;
  /** Session key for continuity tracking */
  sessionKey?: string;
  /** Which adapter resolved this identity */
  adapterId: string;
}

export interface EngramAdapter {
  /** Adapter identifier (e.g., "claude-code", "codex", "hermes", "replit") */
  readonly id: string;

  /** Whether this adapter recognizes the given request context */
  matches(context: AdapterContext): boolean;

  /** Map external session/identity to Engram namespace + principal */
  resolveIdentity(context: AdapterContext): ResolvedIdentity;
}

/**
 * Extract and trim a single header value from a headers record.
 * Returns undefined if the header is missing, empty, or all whitespace.
 */
export function headerValue(
  headers: Record<string, string | string[] | undefined>,
  key: string,
): string | undefined {
  const exactValue = normalizeHeaderValue(headers[key]);
  if (exactValue !== undefined) {
    return exactValue;
  }

  const normalizedKey = key.toLowerCase();
  for (const [headerKey, raw] of Object.entries(headers)) {
    if (headerKey.toLowerCase() !== normalizedKey) {
      continue;
    }
    const value = normalizeHeaderValue(raw);
    if (value !== undefined) {
      return value;
    }
  }

  return undefined;
}

function normalizeHeaderValue(raw: string | string[] | undefined): string | undefined {
  const value = Array.isArray(raw) ? raw[0] : raw;
  return typeof value === "string" && value.trim().length > 0 ? value.trim() : undefined;
}

import { readdirSync, readFileSync } from "node:fs";
import path from "node:path";

import { EngramAccessInputError } from "../access-errors.js";
import { activityDigestPath, isValidActivityDate } from "../activity/digest.js";
import { parseFrontmatter } from "../storage.js";

export interface StandupBrief {
  date: string;
  yesterday: string;
  today: string;
  highlights: string[];
  priorities: string[];
  blockers: string[];
  activityGrid: string;
  markdown: string;
}

export function parseStandupDate(raw: unknown, now = new Date()): string {
  if (raw === undefined || raw === null) {
    return now.toISOString().slice(0, 10);
  }
  const value = String(raw);
  if (!isValidActivityDate(value)) {
    // Typed so the HTTP surface maps it to 400 (EngramAccessInputError);
    // subclasses Error, so the CLI still prints the message verbatim.
    throw new EngramAccessInputError(`invalid --date ${value}; expected YYYY-MM-DD`);
  }
  return value;
}

/** Look back at most this many days for the prior active day (issue #1981). */
const STANDUP_PRIOR_DAY_LOOKBACK = 7;

function shiftDays(date: string, days: number): string {
  const ms = Date.parse(`${date}T00:00:00Z`);
  return new Date(ms + days * 86_400_000).toISOString().slice(0, 10);
}

/**
 * Prior active day: the most recent of the 7 days before `date` that has an
 * activity digest (working-day lookback — Monday resolves to Friday, not
 * Sunday, when the weekend has no digests). Calendar-previous day when no
 * day in the window qualifies.
 */
export function previousActiveDate(memoryDir: string, date: string): string {
  for (let back = 1; back <= STANDUP_PRIOR_DAY_LOOKBACK; back += 1) {
    const candidate = shiftDays(date, -back);
    if (readOptional(activityDigestPath(memoryDir, candidate)) !== null) return candidate;
  }
  return shiftDays(date, -1);
}

export function buildStandup(memoryDir: string, date: string): StandupBrief {
  const yesterday = previousActiveDate(memoryDir, date);
  const todayBody = readOptional(activityDigestPath(memoryDir, date));
  const yesterdayBody = readOptional(activityDigestPath(memoryDir, yesterday));
  const highlights = extractHighlights(yesterdayBody);
  const commitments = sortCommitments(readOpenCommitments(memoryDir));
  const dateMs = Date.parse(`${date}T00:00:00Z`);
  const overdue = commitments.filter(
    (c) => c.expiresAt !== undefined && Number.isFinite(Date.parse(c.expiresAt)) && Date.parse(c.expiresAt) < dateMs,
  );
  const open = commitments.filter((c) => !overdue.includes(c));
  const priorities = open.map((c) => (c.expiresAt ? `${c.text} (due ${c.expiresAt.slice(0, 10)})` : c.text));
  const blockers = [
    ...extractBlockers(yesterdayBody),
    ...overdue.map((c) => `commitment past due: ${c.text} (was due ${c.expiresAt?.slice(0, 10)})`),
  ];
  const activityGrid = renderGrid(yesterday, yesterdayBody);
  const markdown = [
    `# Standup ${date}`,
    "",
    `## Yesterday (${yesterday})`,
    yesterdayBody ? firstLines(yesterdayBody, 8) : "_No activity digest._",
    "",
    `## Today (${date})`,
    todayBody ? firstLines(todayBody, 8) : "_No activity digest._",
    "",
    "## Highlights",
    ...(highlights.length > 0 ? highlights.map((line) => `- ${line}`) : ["- _None._"]),
    "",
    "## Today's priorities",
    ...(priorities.length > 0 ? priorities.map((line) => `- ${line}`) : ["- (no tracked commitments — add priorities manually)"]),
    "",
    "## Blockers",
    ...(blockers.length > 0 ? blockers.map((line) => `- ${line}`) : ["- _None._"]),
    "",
    "## Activity grid",
    "",
    activityGrid,
    "",
  ].join("\n");
  return {
    date,
    yesterday,
    today: date,
    highlights,
    priorities,
    blockers,
    activityGrid,
    markdown,
  };
}

function readOptional(filePath: string): string | null {
  try {
    return readFileSync(filePath, "utf8");
  } catch {
    return null;
  }
}

/** Drop a leading `--- … ---` frontmatter block so its fields never render. */
function stripFrontmatter(body: string): string {
  const lines = body.split("\n");
  if (lines[0]?.trim() !== "---") return body;
  const end = lines.indexOf("---", 1);
  return end < 0 ? body : lines.slice(end + 1).join("\n");
}

function firstLines(body: string, n: number): string {
  return (
    stripFrontmatter(body)
      .split("\n")
      .filter((line) => line.trim().length > 0 && !line.startsWith("#") && !line.startsWith("---"))
      .slice(0, n)
      .join("\n")
      .trim() || "_Empty digest._"
  );
}

function extractHighlights(body: string | null): string[] {
  if (!body) return [];
  return stripFrontmatter(body)
    .split("\n")
    .map((line) => line.replace(/^[-*]\s+/, "").trim())
    .filter((line) => line.length > 0 && !line.startsWith("#") && !line.startsWith("---"))
    .slice(0, 5);
}

function extractBlockers(body: string | null): string[] {
  if (!body) return [];
  return stripFrontmatter(body)
    .split("\n")
    .map((line) => line.replace(/^[-*]\s+/, "").trim())
    .filter((line) => line.length > 0 && /blocker|blocked|stuck|waiting/i.test(line))
    .slice(0, 5);
}

// ── Activity grid (24 hour buckets, byte-stable) ────────────────────────────

const GRID_GLYPHS = ["░", "▁", "▂", "▃", "▄", "█"] as const;

/** Local hour of a digest timeline span line `- [HH:MM] app — window`, or null. */
function spanHour(line: string): number | null {
  if (!line.startsWith("- [")) return null;
  const close = line.indexOf("]", 3);
  if (close < 0) return null;
  const clock = line.slice(3, close);
  const sep = clock.indexOf(":");
  if (sep <= 0) return null;
  const hour = Number.parseInt(clock.slice(0, sep), 10);
  return Number.isInteger(hour) && hour >= 0 && hour <= 23 ? hour : null;
}

function renderGrid(yesterday: string, body: string | null): string {
  if (!body) return `prior day ${yesterday}: no activity digest (empty)`;
  const counts: number[] = new Array(24).fill(0);
  for (const line of stripFrontmatter(body).split("\n")) {
    const hour = spanHour(line);
    if (hour !== null) counts[hour] = counts[hour]! + 1;
  }
  const max = Math.max(...counts);
  if (max === 0) return `prior day ${yesterday}: digest present, no timeline activity`;
  const glyphs = counts
    .map((count) =>
      count === 0 ? "·" : GRID_GLYPHS[Math.min(GRID_GLYPHS.length - 1, Math.ceil((count / max) * GRID_GLYPHS.length) - 1)],
    )
    .join("");
  const nonEmpty = counts.map((count, hour) => (count > 0 ? `${hour}` : null)).filter((h): h is string => h !== null);
  return [`prior day ${yesterday} — 24 hour buckets (· = idle):`, glyphs, `non-empty hours: ${nonEmpty.join(", ")}`].join(
    "\n",
  );
}

// ── Open commitments (deterministic facts scan) ─────────────────────────────

interface OpenCommitment {
  id: string;
  text: string;
  created: string;
  expiresAt?: string;
}

function readOpenCommitments(memoryDir: string): OpenCommitment[] {
  const factsDir = path.join(memoryDir, "facts");
  let dayDirs: string[];
  try {
    dayDirs = readdirSync(factsDir, { withFileTypes: true })
      .filter((entry) => entry.isDirectory() && !entry.isSymbolicLink() && isValidActivityDate(entry.name))
      .map((entry) => entry.name)
      .sort();
  } catch {
    return [];
  }
  const out: OpenCommitment[] = [];
  for (const day of dayDirs) {
    let files: string[];
    try {
      files = readdirSync(path.join(factsDir, day), { withFileTypes: true })
        .filter((entry) => entry.isFile() && !entry.isSymbolicLink() && entry.name.endsWith(".md"))
        .map((entry) => entry.name)
        .sort();
    } catch {
      continue;
    }
    for (const name of files) {
      const parsed = parseFrontmatter(readOptional(path.join(factsDir, day, name)) ?? "");
      if (!parsed) continue;
      const fm = parsed.frontmatter;
      if (fm.category !== "commitment") continue;
      if ((fm.status ?? "active") !== "active") continue;
      if (fm.tags.some((tag) => tag === "fulfilled" || tag === "expired")) continue;
      const text = parsed.content
        .split("\n")
        .map((line) => line.trim())
        .find((line) => line.length > 0);
      if (!text) continue;
      out.push({
        id: fm.id,
        text,
        created: fm.created,
        ...(fm.expiresAt !== undefined ? { expiresAt: fm.expiresAt } : {}),
      });
    }
  }
  return out;
}

function sortCommitments(list: OpenCommitment[]): OpenCommitment[] {
  return [...list].sort((a, b) => {
    // Due-ness first: a commitment with a concrete expiry outranks an
    // undated one; earlier expiry is more due. Created, then id, as the
    // stable tiebreak (§12).
    const aDated = a.expiresAt !== undefined ? 0 : 1;
    const bDated = b.expiresAt !== undefined ? 0 : 1;
    if (aDated !== bDated) return aDated - bDated;
    const ka = a.expiresAt ?? a.created;
    const kb = b.expiresAt ?? b.created;
    if (ka !== kb) return ka < kb ? -1 : 1;
    if (a.id !== b.id) return a.id < b.id ? -1 : 1;
    return 0;
  });
}

export function standupHelp(): string {
  return `Usage: remnic standup [--date YYYY-MM-DD]

Deterministic yesterday/today/blockers brief: prior-working-day highlights,
today's priorities from open commitments, blocker candidates, and a 24-hour
activity grid.
`;
}

/**
 * Graph-edge decay maintenance job (issue #681 PR 2/3).
 *
 * For each edge in the on-disk JSONL graph stores
 * (`<memoryDir>/state/graphs/{entity,time,causal}.jsonl`) call
 * {@link decayEdgeConfidence} from PR 1/3 and write the decayed edge
 * back to disk via the temp+rename atomic-replace pattern (CLAUDE.md
 * gotcha #54: never delete-before-write).
 *
 * Emits a structured telemetry record per run that the doctor surface
 * (`remnic doctor`) and a tail of the maintenance ledger can consume.
 *
 * Pure-helper-style API (the function takes a `memoryDir` + opts and
 * returns a record); callers wire the cron / MCP tool / CLI surfaces.
 */

import {
  mkdir,
  readdir,
  readFile,
  rename,
  writeFile,
} from "node:fs/promises";
import path from "node:path";

import {
  decayEdgeConfidence,
  DEFAULT_DECAY_FLOOR,
  DEFAULT_DECAY_PER_WINDOW,
  DEFAULT_DECAY_WINDOW_MS,
  readEdgeConfidence,
  type DecayOptions,
} from "../graph-edge-reinforcement.js";
import { writeGraphJsonlAtomic } from "../graph-jsonl.js";
import { log } from "../logger.js";
import { assertGraphLockHeld, yieldForLockHeartbeat } from "../graph-write-lock.js";
import {
  graphFilePath,
  graphsDir,
  readEdgesStrict,
  withGraphWriteLock,
  type GraphEdge,
  type GraphType,
} from "../graph.js";
import { isSafeRouteNamespace } from "../routing/engine.js";

/** Default visibility threshold for the "below visibility" telemetry counter. */
export const DEFAULT_VISIBILITY_THRESHOLD = 0.2;

const GRAPH_TYPES: readonly GraphType[] = ["entity", "time", "causal"] as const;

/** Per-edge-type breakdown emitted by {@link runGraphEdgeDecayMaintenance}. */
export interface GraphEdgeDecayPerTypeStats {
  type: GraphType;
  edgesTotal: number;
  edgesDecayed: number;
  edgesBelowVisibilityThreshold: number;
}

/** Top-decayed-entity entry (label + total confidence drop summed across edges). */
export interface GraphEdgeDecayTopEntity {
  label: string;
  totalDrop: number;
  edgeCount: number;
}

/**
 * Telemetry record emitted by every run of the decay job. Persisted to
 * `<memoryDir>/state/graph-edge-decay-status.json` for doctor consumption
 * and (optionally) appended to the maintenance ledger by callers.
 */
export interface GraphEdgeDecayTelemetry {
  ranAt: string;
  durationMs: number;
  edgesTotal: number;
  edgesDecayed: number;
  edgesBelowVisibilityThreshold: number;
  topDecayedEntities: GraphEdgeDecayTopEntity[];
  perType: GraphEdgeDecayPerTypeStats[];
  windowMs: number;
  perWindow: number;
  floor: number;
  visibilityThreshold: number;
}

export interface GraphEdgeDecayOptions extends DecayOptions {
  /** Confidence threshold below which an edge counts as "low visibility". */
  visibilityThreshold?: number;
  /** Override "now" for deterministic testing. Defaults to `new Date().toISOString()`. */
  now?: string;
  /** When `true`, do not write decayed edges back — just compute telemetry. */
  dryRun?: boolean;
}

/** Path of the latest-run status file. */
export function graphEdgeDecayStatusPath(memoryDir: string): string {
  return path.join(memoryDir, "state", "graph-edge-decay-status.json");
}


/**
 * Run a single decay pass over every edge type.
 *
 * Idempotency: PR 1/3's `decayEdgeConfidence` advances `lastReinforcedAt`
 * by exactly the windows it just charged for, so a second run with the
 * same `now` (or any `now` inside the new grace window) is a no-op.
 *
 * Returns the telemetry record. The record is also persisted to
 * {@link graphEdgeDecayStatusPath} so doctor / CLI can read the last run
 * without re-scanning the graphs.
 */
export async function runGraphEdgeDecayMaintenance(
  memoryDir: string,
  options: GraphEdgeDecayOptions = {},
): Promise<GraphEdgeDecayTelemetry> {
  const startedAt = Date.now();
  const ranAt = options.now ?? new Date().toISOString();
  const windowMs = options.windowMs ?? DEFAULT_DECAY_WINDOW_MS;
  const perWindow = options.perWindow ?? DEFAULT_DECAY_PER_WINDOW;
  const floor = options.floor ?? DEFAULT_DECAY_FLOOR;
  const visibilityThreshold =
    typeof options.visibilityThreshold === "number" && Number.isFinite(options.visibilityThreshold)
      ? Math.max(0, Math.min(1, options.visibilityThreshold))
      : DEFAULT_VISIBILITY_THRESHOLD;
  const dryRun = options.dryRun === true;

  await mkdir(graphsDir(memoryDir), { recursive: true });

  const perType: GraphEdgeDecayPerTypeStats[] = [];
  // Aggregate per-label decay drops across ALL graph types so the
  // "top decayed entities" list reflects whichever label dominated
  // each edge (entity name, threadId, or causal phrase). Sorting by
  // total confidence drop highlights the edges decay actually moved
  // most in this pass.
  const dropByLabel = new Map<string, { totalDrop: number; edgeCount: number }>();

  let edgesTotal = 0;
  let edgesDecayed = 0;
  let edgesBelowVisibilityThreshold = 0;

  for (const type of GRAPH_TYPES) {
    const filePath = graphFilePath(memoryDir, type);

    // Hold the per-graph-file write lock across BOTH the read-snapshot
    // and the atomic rewrite so concurrent `appendEdge()` calls cannot
    // sneak in between (issue #729 / Codex P1, line 224). Without this
    // lock the snapshot rewrite would silently drop any edge appended
    // by extraction during the same window. Read failures other than
    // ENOENT are surfaced via `readEdgesStrict` so I/O outages cannot
    // be reported as "no edges to decay" (Codex P1, line 120).
    const {
      typeDecayed,
      typeBelow,
      typeTotal,
    } = await withGraphWriteLock(filePath, async (lock) => {
      const edges = await readEdgesStrict(memoryDir, type);
      const updated: GraphEdge[] = new Array(edges.length);

      let localDecayed = 0;
      let localBelow = 0;
      let localChangedAny = false;

      for (let i = 0; i < edges.length; i += 1) {
        // Round N+19 A: the per-edge decay pass is CPU-bound; yield
        // periodically so the lock's mtime heartbeat timer can fire and a
        // peer does not judge the lock stale mid-run.
        if (i > 0 && i % 5_000 === 0) await yieldForLockHeartbeat();
        const edge = edges[i];
        const before = readEdgeConfidence(edge);
        const decayed = decayEdgeConfidence(edge, ranAt, { windowMs, perWindow, floor });
        const after = readEdgeConfidence(decayed);

        // Only count as "decayed" when the confidence actually dropped.
        // `decayEdgeConfidence` may return an unchanged copy (still inside
        // the grace window, or already at/below the floor) — those are
        // visited but not decayed.
        if (after < before) {
          localDecayed += 1;
          const drop = before - after;
          const label = typeof edge.label === "string" ? edge.label : "";
          // Skip empty labels in the top list — surfacing them produces
          // a meaningless "" entry that crowds the report.
          if (label.length > 0) {
            const prev = dropByLabel.get(label);
            if (prev) {
              prev.totalDrop += drop;
              prev.edgeCount += 1;
            } else {
              dropByLabel.set(label, { totalDrop: drop, edgeCount: 1 });
            }
          }
        }
        if (after < visibilityThreshold) {
          localBelow += 1;
        }
        updated[i] = decayed;
        // Detect any structural change (confidence OR lastReinforcedAt anchor advance)
        // so we only rewrite the JSONL when there's something to persist.
        if (
          decayed.confidence !== edge.confidence ||
          decayed.lastReinforcedAt !== edge.lastReinforcedAt
        ) {
          localChangedAny = true;
        }
      }

      if (!dryRun && localChangedAny && edges.length > 0) {
        // Round N+19 A: revalidate ownership before the rename-backed
        // replace — a peer that stale-broke this lock during the (yielding)
        // decay pass owns the file now. Leave it untouched; the next run
        // re-decays from whatever the peer published. The pass reports zero
        // decayed edges for this type so the telemetry never claims a
        // rewrite that did not land (per-label drop totals may still include
        // the skipped pass — the warning names it).
        try {
          await assertGraphLockHeld(filePath, lock);
        } catch (err) {
          log.warn(
            `graph decay: skipped the ${type} rewrite — ${err instanceof Error ? err.message : String(err)}; per-label drop totals may include this skipped pass`,
          );
          return { typeDecayed: 0, typeBelow: localBelow, typeTotal: edges.length };
        }
        await writeGraphJsonlAtomic(filePath, updated, lock);
      }

      return {
        typeDecayed: localDecayed,
        typeBelow: localBelow,
        typeTotal: edges.length,
      };
    });

    edgesDecayed += typeDecayed;
    edgesBelowVisibilityThreshold += typeBelow;
    edgesTotal += typeTotal;
    perType.push({
      type,
      edgesTotal: typeTotal,
      edgesDecayed: typeDecayed,
      edgesBelowVisibilityThreshold: typeBelow,
    });
  }

  // Stable secondary key on label keeps ordering deterministic when two
  // labels happen to have exactly the same totalDrop (gotcha #19).
  const topDecayedEntities: GraphEdgeDecayTopEntity[] = [...dropByLabel.entries()]
    .map(([label, agg]) => ({ label, totalDrop: agg.totalDrop, edgeCount: agg.edgeCount }))
    .sort((a, b) => {
      if (b.totalDrop !== a.totalDrop) return b.totalDrop - a.totalDrop;
      return a.label.localeCompare(b.label);
    })
    .slice(0, 5);

  const telemetry: GraphEdgeDecayTelemetry = {
    ranAt,
    durationMs: Date.now() - startedAt,
    edgesTotal,
    edgesDecayed,
    edgesBelowVisibilityThreshold,
    topDecayedEntities,
    perType,
    windowMs,
    perWindow,
    floor,
    visibilityThreshold,
  };

  if (!dryRun) {
    await persistTelemetry(memoryDir, telemetry);
  }

  return telemetry;
}

async function persistTelemetry(
  memoryDir: string,
  telemetry: GraphEdgeDecayTelemetry,
): Promise<void> {
  const statusPath = graphEdgeDecayStatusPath(memoryDir);
  await mkdir(path.dirname(statusPath), { recursive: true });
  const tempPath = `${statusPath}.${process.pid}.${Date.now()}.${Math.random().toString(36).slice(2)}.tmp`;
  // Wrap I/O in try/catch (gotcha #13) — failing to persist telemetry must
  // not blow up the maintenance run; the in-memory record is still returned.
  try {
    await writeFile(tempPath, JSON.stringify(telemetry, null, 2) + "\n", "utf-8");
    await rename(tempPath, statusPath);
  } catch {
    // Best-effort: callers still receive the in-memory telemetry record.
  }
}

/** Read the last persisted decay-run telemetry, if any. */
export async function readGraphEdgeDecayStatus(
  memoryDir: string,
): Promise<GraphEdgeDecayTelemetry | null> {
  try {
    const raw = await readFile(graphEdgeDecayStatusPath(memoryDir), "utf-8");
    const parsed = JSON.parse(raw);
    // Validate the parsed payload is a plain object (gotcha #18: JSON.parse('null') is valid).
    if (typeof parsed !== "object" || parsed === null || Array.isArray(parsed)) {
      return null;
    }
    return parsed as GraphEdgeDecayTelemetry;
  } catch {
    return null;
  }
}

/**
 * Per-namespace telemetry record returned by
 * {@link runGraphEdgeDecayMaintenanceAcrossNamespaces}. Each entry
 * pairs the namespace name with its decay telemetry (or an error
 * string if that namespace's run failed). Allows operators to spot
 * I/O outages on a single namespace without masking the rest.
 */
export interface GraphEdgeDecayNamespaceResult {
  namespace: string;
  storageRoot: string;
  telemetry?: GraphEdgeDecayTelemetry;
  error?: string;
}

/**
 * Discover every namespace storage root that may contain graph files.
 *
 * Returns a list of `{ namespace, storageRoot }` entries:
 *   - The default namespace at `memoryDir` (always present).
 *   - Each subdirectory under `memoryDir/namespaces/` that passes
 *     `isSafeRouteNamespace`.
 *
 * Per gotcha #42: read paths must enumerate the same namespace layer
 * as write paths so non-default namespaces don't get skipped during
 * maintenance. Issue #729 / Codex P2.
 */
export async function discoverGraphNamespaceRoots(
  memoryDir: string,
  options: { namespacesEnabled: boolean; defaultNamespace: string },
): Promise<{ namespace: string; storageRoot: string }[]> {
  const seen = new Map<string, string>();
  // Default namespace always lives at memoryDir (NamespaceStorageRouter
  // falls back to memoryDir when memoryDir/namespaces/<default> does
  // not exist).
  seen.set(options.defaultNamespace, memoryDir);

  if (!options.namespacesEnabled) {
    return [...seen.entries()].map(([namespace, storageRoot]) => ({ namespace, storageRoot }));
  }

  const namespacesDir = path.join(memoryDir, "namespaces");
  let entries: import("node:fs").Dirent[];
  try {
    entries = await readdir(namespacesDir, { withFileTypes: true });
  } catch {
    // No namespaces dir yet — only the default namespace exists.
    return [...seen.entries()].map(([namespace, storageRoot]) => ({ namespace, storageRoot }));
  }
  for (const entry of entries) {
    if (!entry.isDirectory()) continue;
    if (!isSafeRouteNamespace(entry.name)) continue;
    const root = path.join(namespacesDir, entry.name);
    seen.set(entry.name, root);
  }

  return [...seen.entries()].map(([namespace, storageRoot]) => ({ namespace, storageRoot }));
}

/**
 * Run the decay maintenance pass against every namespace storage root.
 *
 * In namespaces-enabled deployments, non-default namespaces store
 * their graph JSONLs under `memoryDir/namespaces/<ns>/state/graphs/`,
 * so a single-root run only updates the default namespace and silently
 * skips the rest (issue #729 / Codex P2).
 *
 * Failures in one namespace do not block other namespaces; per-root
 * errors are surfaced in the `error` field of each result.
 */
export async function runGraphEdgeDecayMaintenanceAcrossNamespaces(
  memoryDir: string,
  options: GraphEdgeDecayOptions & {
    namespacesEnabled: boolean;
    defaultNamespace: string;
  },
): Promise<GraphEdgeDecayNamespaceResult[]> {
  const { namespacesEnabled, defaultNamespace, ...decayOptions } = options;
  const roots = await discoverGraphNamespaceRoots(memoryDir, {
    namespacesEnabled,
    defaultNamespace,
  });

  const results: GraphEdgeDecayNamespaceResult[] = [];
  for (const { namespace, storageRoot } of roots) {
    try {
      const telemetry = await runGraphEdgeDecayMaintenance(storageRoot, decayOptions);
      results.push({ namespace, storageRoot, telemetry });
    } catch (err) {
      results.push({
        namespace,
        storageRoot,
        error: err instanceof Error ? err.message : String(err),
      });
    }
  }
  return results;
}

/**
 * Shared OKF bundle-rendering helpers (issues #1948 + #1950).
 *
 * One source of truth for the mechanics every OKF bundle exporter uses:
 * deterministic frontmatter rendering, staging-directory file writes, the
 * symlink-guarded atomic publish, and the bundle version stamp. The memory
 * exporter (transfer/export-okf.ts) and the codegraph exporter
 * (coding/export-okf-codegraph.ts) both consume this module so their
 * bundles are byte-compatible in convention (rule 38 — deterministic
 * rendering discipline; rule 9 — stable seam over shared mechanics).
 */
import { randomUUID } from "node:crypto";
import { lstatSync, mkdirSync, readdirSync, renameSync, rmSync, writeFileSync } from "node:fs";
import path from "node:path";

/** OKF spec version emitted in every bundle root index. */
export const OKF_EXPORT_VERSION = "0.1";

/**
 * Render a YAML frontmatter block from a flat field map.
 *
 * Key order: the canonical OKF keys first (`type`, `title`, `description`,
 * `tags`, `timestamp`), everything else alphabetical — one deterministic
 * layout so identical inputs always render byte-identical files. A key set
 * to `undefined` is omitted; callers must not pass a key twice.
 */
export function renderFrontmatter(fields: Record<string, unknown>): string {
  const keys = Object.keys(fields).sort((a, b) => {
    const order = ["type", "title", "description", "tags", "timestamp"];
    const ai = order.indexOf(a);
    const bi = order.indexOf(b);
    if (ai >= 0 || bi >= 0) return (ai < 0 ? 99 : ai) - (bi < 0 ? 99 : bi);
    return a.localeCompare(b);
  });
  const lines = keys.flatMap((key) => yamlLine(key, fields[key]));
  return `---\n${lines.join("\n")}\n---\n\n`;
}

function yamlLine(key: string, value: unknown): string[] {
  if (value === undefined) return [];
  if (Array.isArray(value)) {
    if (value.length === 0) return [`${key}: []`];
    if (value.every((item) => typeof item !== "object" || item === null)) {
      return [`${key}:`, ...value.map((item) => `  - ${yamlScalar(item)}`)];
    }
    return [`${key}: ${JSON.stringify(value)}`];
  }
  if (typeof value === "object" && value !== null) return [`${key}: ${JSON.stringify(value)}`];
  return [`${key}: ${yamlScalar(value)}`];
}

function yamlScalar(value: unknown): string {
  if (typeof value === "string") {
    if (value === "" || /[:#\n]/.test(value) || value !== value.trim()) return JSON.stringify(value);
    return value;
  }
  return String(value);
}

/**
 * Write one file into a bundle staging tree. `rel` is a POSIX-style
 * bundle-relative path; parent directories are created as needed.
 */
export function writeBundleFile(root: string, rel: string, content: string): void {
  const dest = path.join(root, ...rel.split("/"));
  mkdirSync(path.dirname(dest), { recursive: true });
  writeFileSync(dest, content, "utf8");
}

/**
 * Publish a staged bundle: refuse a non-empty target without `--force`,
 * swap via rename so the target is never observed half-written, and keep a
 * restorable backup when replacing an existing tree.
 */
export function publishBundle(staging: string, outDir: string, force: boolean): void {
  let exists = false;
  try {
    const stat = lstatSync(outDir);
    if (stat.isSymbolicLink()) throw new Error(`--out must not be a symlink: ${outDir}`);
    if (!stat.isDirectory()) throw new Error(`--out exists and is not a directory: ${outDir}`);
    exists = true;
    const entries = readdirSync(outDir).filter((name) => name !== "." && name !== "..");
    if (entries.length > 0 && !force) {
      rmSync(staging, { recursive: true, force: true });
      throw new Error(`--out ${outDir} is not empty; pass --force to replace it`);
    }
  } catch (err) {
    if ((err as NodeJS.ErrnoException).code !== "ENOENT") throw err;
  }
  mkdirSync(path.dirname(outDir), { recursive: true });
  if (exists && force) {
    // A fixed backup name is not reusable: an earlier crash between the two
    // renames, or an unrelated directory a user created, leaves the path
    // occupied and every later --force export fails on the rename. Each
    // attempt takes its own name and removes it on both the success and the
    // rollback path.
    const backup = `${outDir}.okf-prev-${randomUUID().slice(0, 8)}`;
    try {
      renameSync(outDir, backup);
    } catch {
      rmSync(staging, { recursive: true, force: true });
      throw new Error(`cannot replace --out ${outDir}`);
    }
    try {
      renameSync(staging, outDir);
      rmSync(backup, { recursive: true, force: true });
    } catch (err) {
      try {
        renameSync(backup, outDir);
        rmSync(staging, { recursive: true, force: true });
      } catch {
        // Keep the backup when the restore itself fails: it is the only
        // surviving copy of the operator's previous bundle.
      }
      throw err;
    }
    return;
  }
  renameSync(staging, outDir);
}

/**
 * Reject a --out path with a symlink anywhere in its component chain
 * (pattern 42 + hermes-shim precedent): a symlinked component could aim
 * the atomic rename outside the operator's chosen directory.
 */
export function rejectSymlinkPath(target: string): void {
  let current = path.resolve(target);
  while (true) {
    try {
      if (lstatSync(current).isSymbolicLink()) {
        throw new Error(`--out path component is a symlink: ${current}`);
      }
    } catch (err) {
      if ((err as NodeJS.ErrnoException).code !== "ENOENT") throw err;
    }
    const parent = path.dirname(current);
    if (parent === current) break;
    current = parent;
  }
}

import type { IncomingMessage, ServerResponse } from "node:http";

import { type OperationName, getOperation } from "../access-boundary.js";
import type { EngramAccessService } from "../access-service.js";
import { SupportPassportError } from "./errors.js";
import { SupportPassportOwnerCreateGrantRequestSchema } from "./grant-contracts.js";

export interface SupportPassportOwnerHttpDependencies {
  req: IncomingMessage;
  res: ServerResponse;
  pathname: string;
  hasQuery: boolean;
  service: EngramAccessService;
  principal?: string;
  abortSignal: AbortSignal;
  readJsonBody(): Promise<Record<string, unknown>>;
  respondJson(status: number, payload: unknown): void;
  reserveWriteRateLimitSlot(): { commit(): void; release(): void };
}

const OWNER_ROOT = "/engram/v1/support-passport";

export const SUPPORT_PASSPORT_OWNER_HTTP_ROUTES = [
  { method: "GET", pathname: `${OWNER_ROOT}/cards`, operation: "support_passport_cards_list" },
  { method: "POST", pathname: `${OWNER_ROOT}/drafts`, operation: "support_passport_draft_create" },
  { method: "POST", pathname: `${OWNER_ROOT}/drafts/generate`, operation: "support_passport_drafts_generate" },
  { method: "GET", pathname: `${OWNER_ROOT}/grants`, operation: "support_passport_grants_list" },
  { method: "POST", pathname: `${OWNER_ROOT}/grants`, operation: "support_passport_grant_create" },
  { method: "GET", pathname: `${OWNER_ROOT}/memories/:id`, operation: "support_passport_memory_preview" },
  { method: "PUT", pathname: `${OWNER_ROOT}/cards/:id`, operation: "support_passport_card_replace" },
  { method: "POST", pathname: `${OWNER_ROOT}/cards/:id/approve`, operation: "support_passport_card_approve" },
  { method: "POST", pathname: `${OWNER_ROOT}/cards/:id/reject`, operation: "support_passport_card_reject" },
  { method: "POST", pathname: `${OWNER_ROOT}/cards/:id/withdraw`, operation: "support_passport_card_withdraw" },
  { method: "POST", pathname: `${OWNER_ROOT}/grants/:id/revoke`, operation: "support_passport_grant_revoke" },
] as const satisfies ReadonlyArray<{ method: string; pathname: string; operation: OperationName }>;

function decodeId(value: string, label: string): string {
  try {
    return decodeURIComponent(value);
  } catch {
    throw new SupportPassportError("invalid_input", `${label} is invalid.`, 400);
  }
}

function closeUnreadRequestAfterResponse(req: IncomingMessage, res: ServerResponse): void {
  const contentLength = req.headers["content-length"];
  const declaresBody =
    req.headers["transfer-encoding"] !== undefined ||
    (contentLength !== undefined && contentLength !== "0");
  if (!declaresBody || req.readableEnded || req.destroyed) return;
  res.shouldKeepAlive = false;
  res.setHeader("connection", "close");
  res.once("finish", () => req.destroy());
}

async function runOperation(
  name: OperationName,
  input: Record<string, unknown>,
  dependencies: SupportPassportOwnerHttpDependencies,
  recordWriteCommit?: () => void
): Promise<unknown> {
  const operation = getOperation(name);
  if (!operation) throw new Error(`access-boundary: operation not registered: ${name}`);
  const output = (await operation.run(input, {
    service: dependencies.service,
    authenticatedPrincipal: dependencies.principal,
    abortSignal: dependencies.abortSignal,
    ...(recordWriteCommit ? { hooks: { recordWriteCommit } } : {}),
  })) as { result: unknown };
  return output.result;
}

async function runWrite(
  name: OperationName,
  input: Record<string, unknown>,
  dependencies: SupportPassportOwnerHttpDependencies
): Promise<unknown> {
  const writeQuota = dependencies.reserveWriteRateLimitSlot();
  try {
    const result = await runOperation(name, input, dependencies, writeQuota.commit);
    writeQuota.commit();
    return result;
  } catch (error) {
    writeQuota.release();
    throw error;
  }
}

export async function handleSupportPassportOwnerHttp(
  dependencies: SupportPassportOwnerHttpDependencies
): Promise<boolean> {
  const { req, pathname } = dependencies;
  try {
    let operation: OperationName | undefined;
    let input: Record<string, unknown> = {};
    let quotaLimitedWrite = false;

    if (req.method === "GET" && pathname === `${OWNER_ROOT}/cards`) {
      operation = "support_passport_cards_list";
    } else if (req.method === "POST" && pathname === `${OWNER_ROOT}/drafts`) {
      operation = "support_passport_draft_create";
      quotaLimitedWrite = true;
    } else if (req.method === "POST" && pathname === `${OWNER_ROOT}/drafts/generate`) {
      operation = "support_passport_drafts_generate";
      quotaLimitedWrite = true;
    } else if (pathname === `${OWNER_ROOT}/grants` && req.method === "GET") {
      operation = "support_passport_grants_list";
    } else if (pathname === `${OWNER_ROOT}/grants` && req.method === "POST") {
      operation = "support_passport_grant_create";
      quotaLimitedWrite = true;
    } else {
      const memoryMatch = new RegExp(`^${OWNER_ROOT}/memories/([^/]+)$`).exec(pathname);
      const cardMatch = new RegExp(`^${OWNER_ROOT}/cards/([^/]+)(?:/(approve|reject|withdraw))?$`).exec(pathname);
      const grantMatch = new RegExp(`^${OWNER_ROOT}/grants/([^/]+)/revoke$`).exec(pathname);
      if (memoryMatch && req.method === "GET") {
        operation = "support_passport_memory_preview";
        input.memoryId = decodeId(memoryMatch[1] ?? "", "memoryId");
      } else if (cardMatch && req.method === "PUT" && !cardMatch[2]) {
        operation = "support_passport_card_replace";
        input.cardId = decodeId(cardMatch[1] ?? "", "cardId");
        quotaLimitedWrite = true;
      } else if (cardMatch && req.method === "POST" && cardMatch[2]) {
        operation = `support_passport_card_${cardMatch[2]}` as OperationName;
        input.cardId = decodeId(cardMatch[1] ?? "", "cardId");
        quotaLimitedWrite = true;
      } else if (grantMatch && req.method === "POST") {
        operation = "support_passport_grant_revoke";
        input.grantId = decodeId(grantMatch[1] ?? "", "grantId");
        quotaLimitedWrite = true;
      }
    }

    if (!operation) return false;
    dependencies.res.setHeader("cache-control", "private, no-store");
    dependencies.res.setHeader("vary", "Authorization");
    if (dependencies.hasQuery) {
      throw new SupportPassportError("invalid_input", "Support passport routes do not accept query values.", 400);
    }
    if (req.method !== "GET") {
      const body = await dependencies.readJsonBody();
      for (const pathField of Object.keys(input)) {
        if (Object.hasOwn(body, pathField)) {
          throw new SupportPassportError("invalid_input", `${pathField} belongs in the URL path.`, 400);
        }
      }
      input = { ...input, ...body };
    }
    if (operation === "support_passport_drafts_generate" && !Object.hasOwn(input, "sourceMemoryRevisions")) {
      throw new SupportPassportError("invalid_input", "Review the selected notes again before drafting.", 400);
    }
    if (operation === "support_passport_grant_create") {
      const grant = SupportPassportOwnerCreateGrantRequestSchema.safeParse(input);
      if (!grant.success) throw new SupportPassportError("invalid_input", "The share link request is invalid.", 400);
      input = {
        cardIds: grant.data.cardIds,
        cardRevisions: grant.data.cardRevisions,
        ...(grant.data.expiresAt !== undefined
          ? { expiresAt: grant.data.expiresAt }
          : { durationMs: grant.data.durationMs }),
      };
    }
    const result = quotaLimitedWrite
      ? await runWrite(operation, input, dependencies)
      : await runOperation(operation, input, dependencies);
    dependencies.respondJson(200, result);
  } catch (error) {
    if (!(error instanceof SupportPassportError)) throw error;
    closeUnreadRequestAfterResponse(req, dependencies.res);
    dependencies.respondJson(error.status, { error: error.message, code: error.code });
  }
  return true;
}

